CREATE OR REPLACE FUNCTION "api"."zoho_sync_manifest_v1"("p_changed_since" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'scholarship', 'search', 'api'
    AS $$
  select jsonb_build_object(
    'contract_version','zoho-integration-v1',
    'boundary','server-side-pilot-only',
    'changed_since',p_changed_since,
    'providers',jsonb_build_object(
      'count',(select count(*) from catalogue.providers p where not exists (select 1 from security.layer4_search_blocked_providers cf_block where cf_block.provider_id=p.id) and (p_changed_since is null or p.updated_at > p_changed_since)),
      'max_updated_at',(select max(p.updated_at) from catalogue.providers p where not exists (select 1 from security.layer4_search_blocked_providers cf_block where cf_block.provider_id=p.id))
    ),
    'courses',jsonb_build_object(
      'count',(select count(*) from search.course_documents d where (d.course_id is null or d.course_id not in (select cf_block.course_id from security.layer4_search_blocked_courses cf_block where cf_block.course_id is not null)) and (p_changed_since is null or greatest(d.updated_at,d.source_updated_at,d.generated_at) > p_changed_since)),
      'max_updated_at',(select max(greatest(d.updated_at,d.source_updated_at,d.generated_at)) from search.course_documents d where (d.course_id is null or d.course_id not in (select cf_block.course_id from security.layer4_search_blocked_courses cf_block where cf_block.course_id is not null)))
    ),
    'scholarships',jsonb_build_object(
      'count',(select count(*) from scholarship.scholarships s where not exists (select 1 from security.layer4_search_blocked_scholarships cf_block where cf_block.scholarship_id=s.id) and s.lifecycle_status='active' and s.publication_status='published' and (p_changed_since is null or s.updated_at > p_changed_since)),
      'max_updated_at',(select max(s.updated_at) from scholarship.scholarships s where not exists (select 1 from security.layer4_search_blocked_scholarships cf_block where cf_block.scholarship_id=s.id) and s.lifecycle_status='active' and s.publication_status='published')
    ),
    'ordering',jsonb_build_object(
      'providers','name_asc,provider_id_asc',
      'courses','title_asc,course_id_asc',
      'scholarships','name_asc,scholarship_id_asc'
    ),
    'generated_at',now()
  );
$$;


ALTER FUNCTION "api"."zoho_sync_manifest_v1"("p_changed_since" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "catalogue"."enforce_course_identifier_provider"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'catalogue'
    AS $$
begin
  if not exists (select 1 from catalogue.courses c where c.id=new.course_id and c.provider_id=new.provider_id) then
    raise exception 'course identifier provider does not match course provider';
  end if;
  return new;
end $$;


ALTER FUNCTION "catalogue"."enforce_course_identifier_provider"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "catalogue"."guard_de_daad_provider_registration"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'catalogue', 'ref', 'pg_temp'
    AS $$
begin
  if lower(coalesce(new.registration_scheme, '')) = 'daad'
     and exists (
       select 1
       from catalogue.providers p
       join ref.countries c on c.id = p.country_id
       where p.id = new.provider_id
         and upper(c.iso_alpha2::text) = 'DE'
     ) then
    raise exception using
      errcode = '23514',
      message = 'DE DAAD canonical APPLY blocked: DAAD programme feed does not expose a stable provider identifier; resolve sanctioned HRK/provider identity mapping before writes';
  end if;
  return new;
end
$$;


ALTER FUNCTION "catalogue"."guard_de_daad_provider_registration"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "catalogue"."mirror_course_registration_identifier"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'ref', 'pipeline'
    AS $$
declare s ref.identifier_schemes; v_provider uuid; v_ev uuid;
begin
  if tg_op in ('UPDATE','DELETE') then
    if tg_op='UPDATE' and new.course_id=old.course_id and new.scheme=old.scheme and new.registration_code=old.registration_code
       and new.evidence_id is not distinct from old.evidence_id and new.source_id is not distinct from old.source_id then
      return new;
    end if;
    select * into s from ref.identifier_schemes where scheme=old.scheme and entity_type='course' and mirror_registrations and status='active';
    if found then
      delete from catalogue.course_identifiers i where i.course_id=old.course_id and i.scheme=old.scheme and i.identifier=old.registration_code
        and not exists (select 1 from catalogue.course_registrations r where r.course_id=old.course_id and r.scheme=old.scheme
                         and r.registration_code=old.registration_code and (tg_op='DELETE' or r.id<>old.id));
    end if;
    if tg_op='DELETE' then return old; end if;
  end if;
  select * into s from ref.identifier_schemes where scheme=new.scheme and entity_type='course' and mirror_registrations and status='active';
  if not found then return new; end if;
  select c.provider_id into v_provider from catalogue.courses c where c.id=new.course_id;
  select e.id into v_ev from pipeline.evidence_artifacts e where e.id=new.evidence_id;
  insert into catalogue.course_identifiers(course_id,provider_id,scheme,identifier,country_id,issuing_authority,is_primary,source_id,evidence_id,verified_at)
  values(new.course_id,v_provider,new.scheme,new.registration_code,coalesce(new.country_id,s.country_id),s.issuing_authority,true,new.source_id,v_ev,now())
  on conflict (provider_id, scheme, identifier) do update
    set course_id=excluded.course_id, country_id=excluded.country_id, source_id=excluded.source_id, evidence_id=excluded.evidence_id, verified_at=excluded.verified_at
    where (catalogue.course_identifiers.course_id, catalogue.course_identifiers.country_id, catalogue.course_identifiers.source_id, catalogue.course_identifiers.evidence_id)
          is distinct from (excluded.course_id, excluded.country_id, excluded.source_id, excluded.evidence_id);
  return new;
end $$;


ALTER FUNCTION "catalogue"."mirror_course_registration_identifier"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "catalogue"."mirror_provider_registration_identifier"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'ref', 'pipeline'
    AS $$
declare s ref.identifier_schemes; v_ev uuid;
begin
  if tg_op in ('UPDATE','DELETE') then
    if tg_op='UPDATE' and new.provider_id=old.provider_id and new.registration_scheme=old.registration_scheme and new.registration_code=old.registration_code
       and new.valid_from is not distinct from old.valid_from and new.valid_to is not distinct from old.valid_to
       and new.evidence_id is not distinct from old.evidence_id and new.source_id is not distinct from old.source_id then
      return new;
    end if;
    select * into s from ref.identifier_schemes where scheme=old.registration_scheme and entity_type='provider' and mirror_registrations and status='active';
    if found and (tg_op='DELETE' or new.provider_id<>old.provider_id or new.registration_scheme<>old.registration_scheme or new.registration_code<>old.registration_code) then
      delete from catalogue.provider_identifiers i where i.provider_id=old.provider_id and i.scheme=old.registration_scheme and i.identifier=old.registration_code;
    end if;
    if tg_op='DELETE' then return old; end if;
  end if;
  select * into s from ref.identifier_schemes where scheme=new.registration_scheme and entity_type='provider' and mirror_registrations and status='active';
  if not found then return new; end if;
  select e.id into v_ev from pipeline.evidence_artifacts e where e.id=new.evidence_id;
  insert into catalogue.provider_identifiers(provider_id,scheme,identifier,country_id,issuing_authority,is_primary,valid_from,valid_to,source_id,evidence_id,verified_at)
  values(new.provider_id,new.registration_scheme,new.registration_code,s.country_id,s.issuing_authority,true,new.valid_from,new.valid_to,new.source_id,v_ev,coalesce(new.checked_at,now()))
  on conflict (provider_id, scheme, identifier) do update
    set valid_from=excluded.valid_from, valid_to=excluded.valid_to, source_id=excluded.source_id, evidence_id=excluded.evidence_id, verified_at=excluded.verified_at
    where (catalogue.provider_identifiers.valid_from, catalogue.provider_identifiers.valid_to, catalogue.provider_identifiers.source_id, catalogue.provider_identifiers.evidence_id)
          is distinct from (excluded.valid_from, excluded.valid_to, excluded.source_id, excluded.evidence_id);
  return new;
end $$;


ALTER FUNCTION "catalogue"."mirror_provider_registration_identifier"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "l4_api"."block_decide"("p_entity_type" "text", "p_entity_id" "uuid", "p_block_scope" "text", "p_event_type" "text", "p_reason_code" "text", "p_comment" "text" DEFAULT NULL::"text", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_review_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_approval_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'l4_api', 'security', 'pipeline', 'auth'
    AS $$
declare v_actor uuid:=auth.uid(); v_rank int; v_prev uuid; v_id uuid; v_email text;
begin
  if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  if v_rank<5 then raise exception 'PIM Admin role required for block/unblock' using errcode='42501'; end if;
  if not security.layer4_entity_exists(p_entity_type,p_entity_id) then raise exception 'entity not found' using errcode='22023'; end if;
  if p_block_scope not in ('operational','publication','search','data_quality_quarantine') then raise exception 'invalid block scope' using errcode='22023'; end if;
  if p_event_type not in ('block','unblock') then raise exception 'invalid block event' using errcode='22023'; end if;
  if length(trim(coalesce(p_reason_code,'')))<3 then raise exception 'reason code required' using errcode='22023'; end if;
  if p_expires_at is not null and p_expires_at<=now() then raise exception 'expiry must be in the future' using errcode='22023'; end if;
  if p_review_at is not null and p_review_at<=now() then raise exception 'review must be in the future' using errcode='22023'; end if;

  select id into v_prev
  from pipeline.layer4_block_decisions
  where entity_type=p_entity_type and entity_id=p_entity_id and block_scope=p_block_scope
  order by created_at desc,id desc limit 1;

  select email into v_email from auth.users where id=v_actor;

  insert into pipeline.layer4_block_decisions(
    entity_type,entity_id,block_scope,event_type,reason_code,comment,
    actor_id,actor_email,expires_at,review_at,supersedes_decision_id,approval_context
  ) values (
    p_entity_type,p_entity_id,p_block_scope,p_event_type,trim(p_reason_code),
    nullif(trim(coalesce(p_comment,'')),''),
    v_actor,v_email,p_expires_at,p_review_at,v_prev,coalesce(p_approval_context,'{}')
  ) returning id into v_id;

  return jsonb_build_object(
    'ok',true,'decision_id',v_id,'event_type',p_event_type,'scope',p_block_scope,
    'blocked',p_event_type='block',
    'deletion_performed',false,
    'canonical_changed',false,
    'consumer_cutover_authorised',false
  );
end $$;


