CREATE OR REPLACE FUNCTION "l4_api"."layer4_quality_diagnostics"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'scholarship', 'catalogue', 'auth'
    AS $$
declare v_actor uuid:=auth.uid();v_rank int;v jsonb;
begin
 if v_actor is null then raise exception 'authentication required' using errcode='42501';end if;v_rank:=security.current_role_rank();if v_rank<3 then raise exception 'curator role required' using errcode='42501';end if;
 with d as(
  select 'error' type,'high' severity,'Scholarship scope candidates missing Evidence' title,'Cannot safely bulk-accept without retained Evidence.' detail,(select count(*) from scholarship.course_mapping_candidates where status='needs_review' and evidence_id is null)::int count,'Return affected cohorts to evidence acquisition before acceptance.' recommendation
  union all select 'error','critical','Scholarship/Course provider mismatch','Candidate Course belongs to a different Provider from its Scholarship.',(select count(*) from scholarship.course_mapping_candidates cmc join scholarship.scholarships s on s.id=cmc.scholarship_id join catalogue.courses c on c.id=cmc.course_id where cmc.status='needs_review' and c.provider_id is distinct from s.provider_id)::int,'Do not accept; inspect identity/source mapping.'
  union all select 'issue','medium','Stale Scholarship scope review','Scope candidates have remained unresolved for more than seven days.',(select count(*) from scholarship.course_mapping_candidates where status='needs_review' and updated_at<now()-interval '7 days')::int,'Resolve by cohort, reject, or refine the eligibility rule.'
  union all select 'issue','medium','Stale generic Layer 4 review','Generic Layer 4 items have remained pending for more than seven days.',(select count(*) from pipeline.layer4_review_items where status='pending' and created_at<now()-interval '7 days')::int,'Use grouped return/reject actions instead of one-by-one review.'
  union all select 'issue','medium','Accepted candidates without canonical mapping','Accepted Scholarship scope candidates must have a matching Course mapping.',(select count(*) from scholarship.course_mapping_candidates cmc where cmc.status='accepted' and not exists(select 1 from scholarship.course_mappings m where m.scholarship_id=cmc.scholarship_id and m.course_id=cmc.course_id))::int,'Reconcile candidate/mapping integrity before publication.'
  union all select 'improvement','info','Large review cohorts','Large cohorts are better handled as governed rules than individual rows.',(select count(*) from (select scholarship_id,candidate_reason from scholarship.course_mapping_candidates where status='needs_review' group by 1,2 having count(*)>=100) x)::int,'Cross-check one sample set and source rule, then take one audited cohort decision.'
 ) select coalesce(jsonb_agg(jsonb_build_object('type',type,'severity',severity,'title',title,'detail',detail,'count',count,'recommendation',recommendation,'active',count>0)),'[]'::jsonb) into v from d;
 return v;
end $$;


ALTER FUNCTION "l4_api"."layer4_quality_diagnostics"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "l4_api"."layer4_quality_finding_resolve"("p_finding_id" "uuid", "p_status" "text", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'auth'
    AS $$
declare v_actor uuid:=auth.uid();v_rank int;
begin
 if v_actor is null then raise exception 'authentication required' using errcode='42501';end if;v_rank:=security.current_role_rank();if v_rank<3 then raise exception 'curator role required' using errcode='42501';end if;if p_status not in('resolved','dismissed','open') then raise exception 'invalid status';end if;
 update pipeline.layer4_quality_findings set status=p_status,resolved_at=case when p_status='open' then null else now() end,resolution_note=case when p_status='open' then null else nullif(trim(coalesce(p_note,'')),'') end,actor_id=v_actor,last_seen_at=now() where id=p_finding_id;if not found then raise exception 'finding not found';end if;return jsonb_build_object('ok',true,'finding_id',p_finding_id,'status',p_status);
end $$;


ALTER FUNCTION "l4_api"."layer4_quality_finding_resolve"("p_finding_id" "uuid", "p_status" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "l4_api"."layer4_quality_finding_upsert"("p_finding_type" "text", "p_domain" "text", "p_title" "text", "p_detail" "text", "p_severity" "text", "p_group_key" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'auth'
    AS $$
declare v_actor uuid:=auth.uid();v_rank int;v_id uuid;v_fp text;
begin
 if v_actor is null then raise exception 'authentication required' using errcode='42501';end if;v_rank:=security.current_role_rank();if v_rank<3 then raise exception 'curator role required' using errcode='42501';end if;
 if p_finding_type not in('error','issue','improvement') then raise exception 'invalid finding type';end if;if p_severity not in('info','low','medium','high','critical') then raise exception 'invalid severity';end if;if length(trim(coalesce(p_title,'')))<4 then raise exception 'title required';end if;
 v_fp:=md5(lower(trim(p_finding_type))||'|'||lower(trim(coalesce(p_domain,'layer4')))||'|'||lower(trim(p_title))||'|'||coalesce(p_group_key,'{}'::jsonb)::text);
 insert into pipeline.layer4_quality_findings(fingerprint,finding_type,domain,severity,title,detail,group_key,source,status,actor_id) values(v_fp,p_finding_type,coalesce(nullif(trim(p_domain),''),'layer4'),p_severity,trim(p_title),nullif(trim(coalesce(p_detail,'')),''),coalesce(p_group_key,'{}'::jsonb),'operator','open',v_actor)
 on conflict(fingerprint) do update set severity=excluded.severity,detail=excluded.detail,last_seen_at=now(),status='open',resolved_at=null,resolution_note=null,actor_id=v_actor returning id into v_id;
 return jsonb_build_object('ok',true,'finding_id',v_id,'fingerprint',v_fp);
end $$;


ALTER FUNCTION "l4_api"."layer4_quality_finding_upsert"("p_finding_type" "text", "p_domain" "text", "p_title" "text", "p_detail" "text", "p_severity" "text", "p_group_key" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "l4_api"."layer4_quality_findings_read"("p_status" "text" DEFAULT 'open'::"text", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'auth'
    AS $$
declare v_actor uuid:=auth.uid();v_rank int;v jsonb;
begin
 if v_actor is null then raise exception 'authentication required' using errcode='42501';end if;v_rank:=security.current_role_rank();if v_rank<3 then raise exception 'curator role required' using errcode='42501';end if;
 select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v from (select id,finding_type,domain,severity,title,detail,group_key,source,status,actor_id,detected_at,last_seen_at,resolved_at,resolution_note from pipeline.layer4_quality_findings where p_status is null or status=p_status order by case severity when 'critical' then 1 when 'high' then 2 when 'medium' then 3 when 'low' then 4 else 5 end,last_seen_at desc limit greatest(1,least(coalesce(p_limit,100),250))) x;return v;
end $$;


ALTER FUNCTION "l4_api"."layer4_quality_findings_read"("p_status" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "l4_api"."layer4_review_bulk_decide"("p_entity_type" "text", "p_field_code" "text", "p_escalation_reason" "text", "p_action" "text", "p_reason" "text", "p_confirmation" "text", "p_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'auth'
    AS $$
declare v_actor uuid:=auth.uid();v_rank int;v_count int;v_expected text;v_ok int:=0;v_failed int:=0;v_op uuid;r record;v_err jsonb:='[]'::jsonb;
begin
 if v_actor is null then raise exception 'authentication required' using errcode='42501';end if;v_rank:=security.current_role_rank();if v_rank<4 then raise exception 'pipeline_operator role required for mass decisions' using errcode='42501';end if;
 if p_action not in('reject','request_more_evidence','return_layer2','return_layer3') then raise exception 'unsupported generic mass action';end if;if length(trim(coalesce(p_reason,'')))<8 then raise exception 'decision reason must be at least 8 characters';end if;
 -- CF-247 A2 (Platform Admin 30 Oct 2026 06:53): AER items are never decided in bulk; the group is skipped and counted, nothing is decided
 -- CF-247 P1 (Platform Admin 2 Nov 2026 14:50): university descriptions are decided one at a time in the Inbox; the group is skipped and counted
 if p_field_code = 'provider_description' then
  select count(*) into v_count from pipeline.layer4_review_items where status='pending' and entity_type=p_entity_type and field_code=p_field_code and coalesce(escalation_reason,'')=coalesce(p_escalation_reason,'');
  return jsonb_build_object('ok',false,'action',p_action,'processed',0,'failed',0,'skipped_aer',0,'skipped_description',v_count,'remaining_in_group',v_count,'reason','one_at_a_time',
   'message',v_count||' university description(s) skipped: each is approved or rejected on its own in the Inbox','publication_changed',false);
 end if;
 if p_field_code = any (security.aer_review_kinds_v1()) then
  select count(*) into v_count from pipeline.layer4_review_items where status='pending' and entity_type=p_entity_type and field_code=p_field_code and coalesce(escalation_reason,'')=coalesce(p_escalation_reason,'');
  return jsonb_build_object('ok',false,'action',p_action,'processed',0,'failed',0,'skipped_aer',v_count,'remaining_in_group',v_count,'reason','aer_review_path_only',
   'message',v_count||' AER item(s) skipped: AER items are decided one at a time in the AER review path (decision A2)','publication_changed',false);
 end if;
 select count(*) into v_count from pipeline.layer4_review_items where status='pending' and entity_type=p_entity_type and field_code=p_field_code and coalesce(escalation_reason,'')=coalesce(p_escalation_reason,'');if v_count=0 then raise exception 'no pending review items in group';end if;
 v_count:=least(v_count,greatest(1,least(coalesce(p_limit,500),500)));v_expected:=upper(p_action)||' '||v_count;if trim(coalesce(p_confirmation,''))<>v_expected then raise exception 'confirmation must exactly match %',v_expected;end if;
 insert into pipeline.layer4_mass_operations(target_kind,action,actor_id,group_key,reason,before_count) values('review_queue',p_action,v_actor,jsonb_build_object('entity_type',p_entity_type,'field_code',p_field_code,'escalation_reason',coalesce(p_escalation_reason,'')),trim(p_reason),v_count) returning id into v_op;
 for r in select id from pipeline.layer4_review_items where status='pending' and entity_type=p_entity_type and field_code=p_field_code and coalesce(escalation_reason,'')=coalesce(p_escalation_reason,'') order by created_at limit v_count loop
  begin perform security.layer4_review_decide_impl(r.id,p_action,trim(p_reason),null);v_ok:=v_ok+1;exception when others then v_failed:=v_failed+1;if jsonb_array_length(v_err)<10 then v_err:=v_err||jsonb_build_array(jsonb_build_object('review_item_id',r.id,'error',sqlerrm));end if;end;
 end loop;
 update pipeline.layer4_mass_operations set affected_count=v_ok,result=jsonb_build_object('failed_count',v_failed,'sample_errors',v_err,'publication_changed',false) where id=v_op;
 return jsonb_build_object('ok',v_failed=0,'operation_id',v_op,'action',p_action,'processed',v_ok,'failed',v_failed,'remaining_in_group',greatest((select count(*) from pipeline.layer4_review_items where status='pending' and entity_type=p_entity_type and field_code=p_field_code and coalesce(escalation_reason,'')=coalesce(p_escalation_reason,'')),0),'sample_errors',v_err,'publication_changed',false,'skipped_aer',0);
end $$;


ALTER FUNCTION "l4_api"."layer4_review_bulk_decide"("p_entity_type" "text", "p_field_code" "text", "p_escalation_reason" "text", "p_action" "text", "p_reason" "text", "p_confirmation" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "l4_api"."layer4_review_groups"("p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'auth'
    AS $$
declare v_actor uuid:=auth.uid();v_rank int;v jsonb;
begin
 if v_actor is null then raise exception 'authentication required' using errcode='42501';end if;v_rank:=security.current_role_rank();if v_rank<3 then raise exception 'curator role required' using errcode='42501';end if;
 with g as(select entity_type,field_code,coalesce(escalation_reason,'') escalation_reason,count(*) item_count,min(created_at) oldest_at,max(created_at) newest_at,count(*) filter(where evidence_id is null) missing_evidence_count from pipeline.layer4_review_items where status='pending' group by 1,2,3 order by count(*) desc limit greatest(1,least(coalesce(p_limit,100),250)))
 select coalesce(jsonb_agg(jsonb_build_object('group_id',md5(entity_type||'|'||field_code||'|'||escalation_reason),'entity_type',entity_type,'field_code',field_code,'escalation_reason',escalation_reason,'item_count',item_count,'missing_evidence_count',missing_evidence_count,'oldest_at',oldest_at,'newest_at',newest_at)),'[]'::jsonb) into v from g;return v;
end $$;


ALTER FUNCTION "l4_api"."layer4_review_groups"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "l4_api"."layer4_scholarship_scope_bulk_decide"("p_scholarship_id" "uuid", "p_candidate_reason" "text", "p_action" "text", "p_reason" "text", "p_confirmation" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'scholarship', 'catalogue', 'auth'
    AS $$
declare v_actor uuid:=auth.uid();v_rank int;v_count int;v_missing int;v_mismatch int;v_inserted int:=0;v_affected int:=0;v_op uuid;v_expected text;
begin
 if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
 v_rank:=security.current_role_rank();if v_rank<4 then raise exception 'pipeline_operator role required for mass decisions' using errcode='42501';end if;
 if p_action not in('accept','reject') then raise exception 'invalid mass action';end if;
 if length(trim(coalesce(p_reason,'')))<8 then raise exception 'decision reason must be at least 8 characters';end if;
 select count(*),count(*) filter(where cmc.evidence_id is null),count(*) filter(where c.provider_id is distinct from s.provider_id)
 into v_count,v_missing,v_mismatch
 from scholarship.course_mapping_candidates cmc join scholarship.scholarships s on s.id=cmc.scholarship_id join catalogue.courses c on c.id=cmc.course_id
 where cmc.status='needs_review' and cmc.scholarship_id=p_scholarship_id and cmc.candidate_reason=p_candidate_reason;
 if v_count=0 then raise exception 'no pending candidates in this cohort';end if;
 v_expected:=upper(p_action)||' '||v_count;if trim(coalesce(p_confirmation,''))<>v_expected then raise exception 'confirmation must exactly match %',v_expected;end if;
 if p_action='accept' and (v_missing>0 or v_mismatch>0) then raise exception 'structural blockers prevent bulk accept: missing evidence %, provider mismatch %',v_missing,v_mismatch;end if;
 insert into pipeline.layer4_mass_operations(target_kind,action,actor_id,group_key,reason,before_count,result)
 values('scholarship_course_scope',p_action,v_actor,jsonb_build_object('scholarship_id',p_scholarship_id,'candidate_reason',p_candidate_reason),trim(p_reason),v_count,jsonb_build_object('confirmation',p_confirmation,'semantic_warning',lower(coalesce(p_candidate_reason,'')) ~ '(exclusion|exact|requires governed review|country|eligib)')) returning id into v_op;
 if p_action='accept' then
  insert into scholarship.course_mappings(scholarship_id,course_id,mapping_state,mapping_basis,evidence_id,mapped_by)
  select cmc.scholarship_id,cmc.course_id,'mapped','layer4_mass_review:'||v_op::text,cmc.evidence_id,v_actor
  from scholarship.course_mapping_candidates cmc where cmc.status='needs_review' and cmc.scholarship_id=p_scholarship_id and cmc.candidate_reason=p_candidate_reason
  on conflict(scholarship_id,course_id) do nothing;
  get diagnostics v_inserted=row_count;
  update scholarship.course_mapping_candidates set status='accepted',updated_at=now() where status='needs_review' and scholarship_id=p_scholarship_id and candidate_reason=p_candidate_reason;
  get diagnostics v_affected=row_count;
 else
  update scholarship.course_mapping_candidates set status='rejected',updated_at=now() where status='needs_review' and scholarship_id=p_scholarship_id and candidate_reason=p_candidate_reason;
  get diagnostics v_affected=row_count;
 end if;
 update pipeline.layer4_mass_operations set affected_count=v_affected,result=result||jsonb_build_object('mappings_inserted',v_inserted,'missing_evidence',v_missing,'provider_mismatch',v_mismatch,'publication_changed',false) where id=v_op;
 return jsonb_build_object('ok',true,'operation_id',v_op,'action',p_action,'affected_count',v_affected,'mappings_inserted',v_inserted,'publication_changed',false,'search_refresh_required',false);
end $$;


ALTER FUNCTION "l4_api"."layer4_scholarship_scope_bulk_decide"("p_scholarship_id" "uuid", "p_candidate_reason" "text", "p_action" "text", "p_reason" "text", "p_confirmation" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "l4_api"."layer4_scholarship_scope_groups"("p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'scholarship', 'catalogue', 'auth'
    AS $$
declare v_actor uuid:=auth.uid(); v_rank int; v jsonb;
begin
 if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
 v_rank:=security.current_role_rank(); if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;
 with g as (
  select cmc.scholarship_id,cmc.candidate_reason,s.name scholarship_name,s.provider_id,p.canonical_name provider_name,
   count(*) candidate_count,count(cmc.evidence_id) evidence_count,
   count(*) filter(where c.provider_id is distinct from s.provider_id) provider_mismatch_count,
   count(*) filter(where exists(select 1 from scholarship.course_mappings m where m.scholarship_id=cmc.scholarship_id and m.course_id=cmc.course_id)) already_mapped_count,
   count(*) filter(where cmc.updated_at<now()-interval '7 days') stale_count,count(distinct c.study_level_id) study_level_count,
   bool_or(lower(cmc.candidate_reason) ~ '(exclusion|exact|requires governed review|country|eligib|no[_ ]explicit|scope)') semantic_warning,
   min(cmc.updated_at) oldest_at,max(cmc.updated_at) newest_at,(array_agg(c.canonical_title order by c.canonical_title))[1:5] sample_courses
  from scholarship.course_mapping_candidates cmc join scholarship.scholarships s on s.id=cmc.scholarship_id join catalogue.providers p on p.id=s.provider_id join catalogue.courses c on c.id=cmc.course_id
  where cmc.status='needs_review' group by cmc.scholarship_id,cmc.candidate_reason,s.name,s.provider_id,p.canonical_name order by count(*) desc,s.name limit greatest(1,least(coalesce(p_limit,100),250))
 ) select coalesce(jsonb_agg(jsonb_build_object('group_id',md5(scholarship_id::text||'|'||candidate_reason),'scholarship_id',scholarship_id,'scholarship_name',scholarship_name,'provider_id',provider_id,'provider_name',provider_name,'candidate_reason',candidate_reason,'candidate_count',candidate_count,'evidence_count',evidence_count,'provider_mismatch_count',provider_mismatch_count,'already_mapped_count',already_mapped_count,'stale_count',stale_count,'study_level_count',study_level_count,'semantic_warning',semantic_warning,'structural_ready',(evidence_count=candidate_count and provider_mismatch_count=0),'oldest_at',oldest_at,'newest_at',newest_at,'sample_courses',to_jsonb(sample_courses))),'[]'::jsonb) into v from g;
 return v;
end $$;


ALTER FUNCTION "l4_api"."layer4_scholarship_scope_groups"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "l4_api"."layer4_scholarship_scope_preview"("p_scholarship_id" "uuid", "p_candidate_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'scholarship', 'catalogue', 'auth'
    AS $$
declare v_actor uuid:=auth.uid();v_rank int;v_count int;v_evidence int;v_mismatch int;v_mapped int;v_sample jsonb;v_name text;v_provider text;
begin
 if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if; v_rank:=security.current_role_rank();if v_rank<3 then raise exception 'curator role required' using errcode='42501';end if;
 select count(*),count(cmc.evidence_id),count(*) filter(where c.provider_id is distinct from s.provider_id),count(*) filter(where exists(select 1 from scholarship.course_mappings m where m.scholarship_id=cmc.scholarship_id and m.course_id=cmc.course_id)),max(s.name),max(p.canonical_name) into v_count,v_evidence,v_mismatch,v_mapped,v_name,v_provider from scholarship.course_mapping_candidates cmc join scholarship.scholarships s on s.id=cmc.scholarship_id join catalogue.providers p on p.id=s.provider_id join catalogue.courses c on c.id=cmc.course_id where cmc.status='needs_review' and cmc.scholarship_id=p_scholarship_id and cmc.candidate_reason=p_candidate_reason;
 select coalesce(jsonb_agg(x),'[]'::jsonb) into v_sample from(select jsonb_build_object('course_id',c.id,'course_title',c.canonical_title,'course_code',c.course_code,'has_evidence',cmc.evidence_id is not null,'already_mapped',exists(select 1 from scholarship.course_mappings m where m.scholarship_id=cmc.scholarship_id and m.course_id=cmc.course_id),'provider_match',c.provider_id=s.provider_id)x from scholarship.course_mapping_candidates cmc join scholarship.scholarships s on s.id=cmc.scholarship_id join catalogue.courses c on c.id=cmc.course_id where cmc.status='needs_review' and cmc.scholarship_id=p_scholarship_id and cmc.candidate_reason=p_candidate_reason order by c.canonical_title limit 20)q;
 return jsonb_build_object('ok',true,'scholarship_id',p_scholarship_id,'scholarship_name',v_name,'provider_name',v_provider,'candidate_reason',p_candidate_reason,'candidate_count',v_count,'evidence_count',v_evidence,'missing_evidence_count',v_count-v_evidence,'provider_mismatch_count',v_mismatch,'already_mapped_count',v_mapped,'semantic_warning',lower(coalesce(p_candidate_reason,'')) ~ '(exclusion|exact|requires governed review|country|eligib|no[_ ]explicit|scope)','structural_ready',(v_count>0 and v_evidence=v_count and v_mismatch=0),'accept_confirmation','ACCEPT '||v_count,'reject_confirmation','REJECT '||v_count,'sample',v_sample,'publication_changed',false);
end $$;


ALTER FUNCTION "l4_api"."layer4_scholarship_scope_preview"("p_scholarship_id" "uuid", "p_candidate_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "l4_api"."layer4_scope_rule_apply"("p_rule_id" "uuid", "p_limit" integer DEFAULT 1000) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'scholarship', 'catalogue', 'auth'
    AS $$
declare v_actor uuid:=auth.uid();v_rank int;v_rule pipeline.layer4_scope_rules%rowtype;r record;v_ok int:=0;v_skip int:=0;v_res jsonb;v_op uuid;
begin
 if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
 v_rank:=security.current_role_rank(); if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
 select * into v_rule from pipeline.layer4_scope_rules where id=p_rule_id and enabled; if not found then raise exception 'enabled rule not found'; end if;
 insert into pipeline.layer4_mass_operations(target_kind,action,actor_id,group_key,reason,before_count)
 select 'scholarship_course_scope','rule_'||v_rule.decision,v_actor,jsonb_build_object('rule_id',v_rule.id,'scholarship_id',v_rule.scholarship_id,'candidate_reason',v_rule.candidate_reason),v_rule.rule_reason,count(*)
 from scholarship.course_mapping_candidates where status='needs_review' and scholarship_id=v_rule.scholarship_id and candidate_reason=v_rule.candidate_reason and evidence_id=v_rule.evidence_id returning id into v_op;
 for r in select id from scholarship.course_mapping_candidates where status='needs_review' and scholarship_id=v_rule.scholarship_id and candidate_reason=v_rule.candidate_reason and evidence_id=v_rule.evidence_id order by created_at limit greatest(1,least(coalesce(p_limit,1000),5000)) loop
   v_res:=security.layer4_scope_rule_apply_one_impl(r.id);
   if coalesce((v_res->>'applied')::boolean,false) then v_ok:=v_ok+1; else v_skip:=v_skip+1; end if;
 end loop;
 update pipeline.layer4_mass_operations set affected_count=v_ok,result=jsonb_build_object('rule_id',v_rule.id,'applied',v_ok,'skipped',v_skip,'publication_changed',false,'search_refresh_required',false) where id=v_op;
 return jsonb_build_object('ok',true,'operation_id',v_op,'rule_id',v_rule.id,'applied',v_ok,'skipped',v_skip,'publication_changed',false,'search_refresh_required',false);
end$$;


ALTER FUNCTION "l4_api"."layer4_scope_rule_apply"("p_rule_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "l4_api"."layer4_scope_rule_save"("p_scholarship_id" "uuid", "p_candidate_reason" "text", "p_decision" "text", "p_reason" "text", "p_confirmation" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'scholarship', 'catalogue', 'auth'
    AS $$
declare v_actor uuid:=auth.uid();v_rank int;v_count int;v_missing int;v_mismatch int;v_evidence_versions int;v_evidence uuid;v_provider uuid;v_expected text;v_rule uuid;
begin
 if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
 v_rank:=security.current_role_rank(); if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
 if p_decision not in('accept','reject') then raise exception 'invalid rule decision'; end if;
 if length(trim(coalesce(p_reason,'')))<8 then raise exception 'rule reason must be at least 8 characters'; end if;
 select count(*),count(*) filter(where cmc.evidence_id is null),count(*) filter(where c.provider_id is distinct from s.provider_id),count(distinct cmc.evidence_id),max(cmc.evidence_id),max(s.provider_id)
 into v_count,v_missing,v_mismatch,v_evidence_versions,v_evidence,v_provider
 from scholarship.course_mapping_candidates cmc join scholarship.scholarships s on s.id=cmc.scholarship_id join catalogue.courses c on c.id=cmc.course_id
 where cmc.status='needs_review' and cmc.scholarship_id=p_scholarship_id and cmc.candidate_reason=p_candidate_reason;
 if v_count=0 then raise exception 'no pending candidates in cohort'; end if;
 v_expected:='SAVE RULE '||v_count; if trim(coalesce(p_confirmation,''))<>v_expected then raise exception 'confirmation must exactly match %',v_expected; end if;
 if v_missing>0 or v_mismatch>0 or v_evidence_versions<>1 then raise exception 'rule blocked: missing evidence %, provider mismatch %, evidence versions %',v_missing,v_mismatch,v_evidence_versions; end if;
 insert into pipeline.layer4_scope_rules(scholarship_id,candidate_reason,evidence_id,provider_id,decision,rule_reason,conditions,created_by)
 values(p_scholarship_id,p_candidate_reason,v_evidence,v_provider,p_decision,trim(p_reason),jsonb_build_object('exact_evidence_required',true,'exact_provider_required',true,'source_cohort_count',v_count),v_actor)
 on conflict(scholarship_id,candidate_reason,evidence_id) do update set provider_id=excluded.provider_id,decision=excluded.decision,rule_reason=excluded.rule_reason,conditions=excluded.conditions,enabled=true,updated_at=now(),created_by=v_actor
 returning id into v_rule;
 return jsonb_build_object('ok',true,'rule_id',v_rule,'cohort_count',v_count,'decision',p_decision,'evidence_id',v_evidence,'provider_id',v_provider,'publication_changed',false);
end$$;


ALTER FUNCTION "l4_api"."layer4_scope_rule_save"("p_scholarship_id" "uuid", "p_candidate_reason" "text", "p_decision" "text", "p_reason" "text", "p_confirmation" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "l4_api"."layer4_scope_rule_set_state"("p_rule_id" "uuid", "p_enabled" boolean, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'auth'
    AS $$
declare v_actor uuid:=auth.uid();v_rank int;
begin
 if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
 v_rank:=security.current_role_rank(); if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
 if length(trim(coalesce(p_reason,'')))<8 then raise exception 'state-change reason must be at least 8 characters'; end if;
 update pipeline.layer4_scope_rules set enabled=p_enabled,updated_at=now(),conditions=conditions||jsonb_build_object('last_state_reason',trim(p_reason),'last_state_actor',v_actor,'last_state_at',now()) where id=p_rule_id;
 if not found then raise exception 'rule not found'; end if;
 return jsonb_build_object('ok',true,'rule_id',p_rule_id,'enabled',p_enabled,'publication_changed',false);
