    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'l4_api', 'security', 'auth'
    AS $$ select security.layer4_publication_state_read(p_entity_type,p_entity_id,p_target_scope) $$;


ALTER FUNCTION "l4_api"."publication_state"("p_entity_type" "text", "p_entity_id" "uuid", "p_target_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."edge_request_note"("p_request_id" bigint, "p_function" "text", "p_mode" "text") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  insert into pipeline.edge_request_log(slot, request_id, function_name, mode, created_at)
  values ((p_request_id % 50000)::int, p_request_id, p_function, nullif(p_mode, ''), now())
  on conflict (slot) do update set request_id = excluded.request_id, function_name = excluded.function_name, mode = excluded.mode, created_at = excluded.created_at;
$$;


ALTER FUNCTION "pipeline"."edge_request_note"("p_request_id" bigint, "p_function" "text", "p_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."get_maintenance_drain_status"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare s pipeline.maintenance_state; v_me int := pg_backend_pid();
        v_cron jsonb; v_db jsonb; v_api int; v_edge int; v_netq int; v_fei int; v_pages int; v_l4 int; v_locks jsonb; v_back jsonb;
        v_off int; v_active int; v_settings int; v_elapsed numeric; v_alert int; v_safe boolean;
begin
  perform pipeline.maintenance_actor_v1(1);
  select * into s from pipeline.maintenance_state where id;
  -- cron runs still going (only runs whose session is alive count; a crashed run left as 'running' is listed as stale)
  select coalesce(jsonb_agg(jsonb_build_object('job', j.jobname, 'started', d.start_time, 'stale', a.pid is null) order by d.start_time), '[]'::jsonb) into v_cron
    from cron.job_run_details d left join cron.job j on j.jobid = d.jobid left join pg_stat_activity a on a.pid = d.job_pid
   where d.status in ('running', 'starting');
  -- busy database sessions (not this one, not the API's own connections) that touch catalogue or pipeline
  select coalesce(jsonb_agg(jsonb_build_object('pid', a.pid, 'app', a.application_name, 'user', a.usename, 'state', a.state, 'since', coalesce(a.xact_start, a.query_start),
                                               'query', left(regexp_replace(a.query, '\s+', ' ', 'g'), 160)) order by a.query_start), '[]'::jsonb) into v_db
    from pg_stat_activity a
   where a.backend_type = 'client backend' and a.pid <> v_me and coalesce(a.state, 'idle') <> 'idle' and a.application_name not like 'PostgREST%'
     and (a.query ~* '\m(catalogue|pipeline)\.' or exists (select 1 from pg_locks l join pg_class c on c.oid = l.relation join pg_namespace n on n.oid = c.relnamespace
                                                            where l.pid = a.pid and n.nspname in ('catalogue', 'pipeline')));
  -- website, Zoho and admin reads through the API: shown, not counted (they are short and a migration waits for them)
  select count(*) into v_api from pg_stat_activity a where a.backend_type = 'client backend' and a.pid <> v_me and coalesce(a.state, 'idle') <> 'idle' and a.application_name like 'PostgREST%';
  -- edge worker calls that may still be running: sent within the edge function time limit and not answered (or the wait timed out)
  select count(*) into v_edge from pipeline.edge_request_log e left join net._http_response r on r.id = e.request_id
   where e.created_at > now() - interval '150 seconds'  -- fixed: Supabase edge function wall-clock limit (API time-out)
     and (r.id is null or coalesce(r.timed_out, false));
  select count(*) into v_netq from net.http_request_queue;
  -- live worker leases
  select count(*) into v_fei from pipeline.field_enrich_items where state = 'leased' and coalesce(leased_until, 'infinity') > now();
  select count(*) into v_pages from pipeline.coverage_course_pages where leased_until > now();
  select count(*) into v_l4 from pipeline.layer4_review_items where status = 'pending' and claimed_at is not null;
  -- locks other sessions hold or wait for on catalogue tables (any but a plain read), or write locks on pipeline tables
  select coalesce(jsonb_agg(jsonb_build_object('table', n.nspname || '.' || c.relname, 'mode', l.mode, 'granted', l.granted, 'pid', l.pid)), '[]'::jsonb) into v_locks
    from pg_locks l join pg_class c on c.oid = l.relation join pg_namespace n on n.oid = c.relnamespace
   where l.pid <> v_me and l.locktype = 'relation' and c.relkind in ('r', 'p', 'm')
     and ((n.nspname = 'catalogue' and (not l.granted or l.mode <> 'AccessShareLock'))
       or (n.nspname = 'pipeline' and c.relname not like 'maintenance\_%' and (not l.granted or l.mode not in ('AccessShareLock', 'RowShareLock'))));
  select count(*) into v_active from cron.job where active;
  if s.is_paused then
    select count(*) into v_off from pipeline.maintenance_job_snapshot where window_id = s.window_id and kind = 'job' and switched_off;
    select coalesce(jsonb_agg(j.jobname order by j.jobname), '[]'::jsonb) into v_back
      from pipeline.maintenance_job_snapshot m join cron.job j on j.jobname = m.name
     where m.window_id = s.window_id and m.kind = 'job' and m.switched_off and j.active;
    select count(*) into v_settings
      from (select * from pipeline.maintenance_job_snapshot where window_id = s.window_id and kind = 'setting') m
      full join pipeline.platform_toolset_settings t on t.toolset_key = m.toolset_key and t.key = m.setting_key
     where m.id is null or t.key is null or m.value is distinct from t.value;
    v_elapsed := round(extract(epoch from now() - s.paused_at)::numeric);
    v_alert := coalesce(s.auto_alert_after_minutes, security.pipeline_num_v1('maintenance.alert_after_minutes', 15)::int);
  end if;
  v_safe := coalesce(s.is_paused, false)
            and jsonb_array_length(v_cron) = 0 and jsonb_array_length(v_db) = 0 and v_edge = 0 and v_netq = 0
            and v_fei = 0 and v_pages = 0 and v_l4 = 0 and jsonb_array_length(v_locks) = 0 and jsonb_array_length(coalesce(v_back, '[]'::jsonb)) = 0;
  return jsonb_build_object(
    'checked_at', now(), 'is_paused', coalesce(s.is_paused, false),
    'state', case when not coalesce(s.is_paused, false) then 'ACTIVE' when v_safe then 'SAFE' else 'DRAINING' end,
    'window_id', s.window_id, 'paused_at', s.paused_at, 'paused_by', s.paused_by, 'reason', s.reason,
    'elapsed_seconds', v_elapsed, 'alert_after_minutes', v_alert, 'overdue', coalesce(v_elapsed > v_alert * 60, false),
    'active_jobs', v_active, 'jobs_switched_off', coalesce(v_off, 0), 'jobs_switched_on_again', coalesce(v_back, '[]'::jsonb),
    'running_cron', jsonb_array_length(v_cron), 'running_cron_detail', v_cron,
    'db_backends', jsonb_array_length(v_db), 'db_backends_detail', v_db, 'api_reads', v_api,
    'edge_calls_in_flight', v_edge, 'http_queue', v_netq,
    'leases', jsonb_build_object('field_enrich_items', v_fei, 'coverage_course_pages', v_pages, 'layer4_claims', v_l4), 'leases_total', v_fei + v_pages + v_l4,
    'catalogue_locks', jsonb_array_length(v_locks), 'locks_detail', v_locks,
    'settings_changed_since_pause', coalesce(v_settings, 0),
    'safe_to_migrate', v_safe,
    'last_result', s.last_result);
end $$;


ALTER FUNCTION "pipeline"."get_maintenance_drain_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."layer2_carry_forward_discovery_candidates"("p_new_version" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_new pipeline.layer2_source_profile_versions; v_old pipeline.layer2_source_profile_versions; v_n integer:=0;
begin
  select * into v_new from pipeline.layer2_source_profile_versions where id=p_new_version;
  if not found then return 0; end if;
  select * into v_old from pipeline.layer2_source_profile_versions
   where profile_id=v_new.profile_id and version_no<v_new.version_no order by version_no desc limit 1;
  if not found then return 0; end if;
  if (v_new.configuration->'discovery_strategy') is distinct from (v_old.configuration->'discovery_strategy')
     or (v_new.configuration->'url_patterns') is distinct from (v_old.configuration->'url_patterns') then return 0; end if;
  if exists (select 1 from pipeline.layer2_course_discovery_candidates where source_profile_version_id=v_new.id) then return 0; end if;
  insert into pipeline.layer2_course_discovery_candidates(trial_course_id,course_id,source_profile_version_id,provider_attempt_id,evidence_id,
         discovered_url,discovered_title,discovered_regulatory_code,match_score,match_basis,status,selected,blocker,created_at)
  select c.trial_course_id,c.course_id,v_new.id,c.provider_attempt_id,c.evidence_id,c.discovered_url,c.discovered_title,c.discovered_regulatory_code,
         c.match_score,coalesce(c.match_basis,'{}'::jsonb)||jsonb_build_object('carried_forward_from_version',v_old.id,'carried_forward_at',now()),
         c.status,c.selected,c.blocker,c.created_at
    from pipeline.layer2_course_discovery_candidates c where c.source_profile_version_id=v_old.id;
  get diagnostics v_n=row_count;
  return v_n;
end $$;


ALTER FUNCTION "pipeline"."layer2_carry_forward_discovery_candidates"("p_new_version" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."layer2_course_decision_context_snapshot"("p_course_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pipeline', 'catalogue', 'public'
    AS $$
select jsonb_build_object(
 'course_id',c.id,
 'qilt_provider', case when exists(select 1 from catalogue.provider_outcomes po where po.provider_id=c.provider_id and coalesce(po.status,'active')='active') then 'present' else 'not_available' end,
 'qilt_study_area', case when exists(select 1 from catalogue.provider_outcomes po where po.provider_id=c.provider_id and po.external_study_area_id is not null and coalesce(po.status,'active')='active') then 'present' else 'not_available' end,
 'prisms_provider', case when exists(select 1 from catalogue.student_flow_observations sf where sf.provider_id=c.provider_id and coalesce(sf.status,'active')='active') then 'present' else 'not_available' end,
 'prisms_state', case when exists(select 1 from catalogue.student_flow_observations sf where sf.subdivision_id is not null and coalesce(sf.status,'active')='active') then 'present' else 'not_available' end,
 'context_is_course_grain', false
)
from catalogue.courses c where c.id=p_course_id;
$$;


ALTER FUNCTION "pipeline"."layer2_course_decision_context_snapshot"("p_course_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."layer2_course_factual_snapshot"("p_course_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pipeline', 'catalogue', 'public'
    AS $$
select jsonb_build_object(
  'course_id', c.id,
  'identity', case when c.stable_key is not null and c.provider_id is not null and coalesce(c.canonical_title,c.display_title) is not null then 'present' else 'ambiguous' end,
  'course_url', case when coalesce(c.course_url,(select cl.url from catalogue.course_links cl where cl.link_type = 'official_course' and cl.course_id=c.id and coalesce(cl.status,'active')='active' order by cl.is_primary desc nulls last, cl.created_at desc limit 1)) is not null then 'present' else 'not_yet_enriched' end,
  'provider_current_tuition', case when exists(select 1 from catalogue.course_fees f where f.course_id=c.id and f.audience='international' and f.fee_type='provider_current_tuition' and coalesce(f.status,'active')='active') then 'present' else 'not_yet_enriched' end,
  'intakes', case when exists(select 1 from catalogue.course_intakes i where i.course_id=c.id and coalesce(i.status,'active')='active') then 'present' else 'not_yet_enriched' end,
  'english_requirements', case when exists(select 1 from catalogue.course_english_requirements e where e.course_id=c.id and coalesce(e.status,'active')='active') then 'present' else 'not_yet_enriched' end,
  'campus_delivery', case when exists(select 1 from catalogue.course_campuses cc where cc.course_id=c.id) then 'present' else 'not_yet_enriched' end,
  'description', case when nullif(btrim(c.description),'') is not null then 'present' else 'not_yet_enriched' end,
  'verification', case when c.last_verified_at is null then 'not_yet_enriched' when c.last_verified_at < now()-interval '180 days' then 'stale' else 'present' end
)
from catalogue.courses c where c.id=p_course_id;
$$;


ALTER FUNCTION "pipeline"."layer2_course_factual_snapshot"("p_course_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."layer2_evidence_version_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_job_version uuid;
begin
  if new.job_id is not null then
    select source_profile_version_id into v_job_version from pipeline.jobs where id=new.job_id;
    if v_job_version is not null then
      if new.source_profile_version_id is null then new.source_profile_version_id:=v_job_version;
      elsif new.source_profile_version_id<>v_job_version then raise exception 'Evidence configuration version does not match Job configuration version' using errcode='23514';
      end if;
    end if;
  end if;
  return new;
end
$$;


ALTER FUNCTION "pipeline"."layer2_evidence_version_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."layer2_route_scope_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_domain text; v_target text; v_enabled boolean;
begin
  select domain,target_entity_type,enabled into v_domain,v_target,v_enabled
  from pipeline.layer2_source_profiles where id=new.profile_id;
  if v_domain is null then raise exception 'Layer 2 source profile not found' using errcode='23503'; end if;
  if not (
    (v_domain='course_facts' and v_target='course_fact')
    or (v_domain='scholarship' and v_target='scholarship')
    or (v_domain='provider_asset' and v_target='provider_asset')
  ) then
    raise exception 'Layer 2 acquisition routes are limited to Course, Scholarship and Provider Asset enrichment; QILT/PRISMS remain Layer 1' using errcode='23514';
  end if;
  if not coalesce(v_enabled,false) then
    raise exception 'Layer 2 source profile is not enabled' using errcode='23514';
  end if;
  return new;
end $$;


ALTER FUNCTION "pipeline"."layer2_route_scope_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."layer3_cascade_test_cap_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $_$
begin
  if new.run_label like 'c-%' and pipeline.layer3_cascade_test_spent_usd() >= 6.0 then
    raise exception 'cascade test spend cap US$6 reached (spent %)', pipeline.layer3_cascade_test_spent_usd();
  end if;
  return new;
end $_$;


ALTER FUNCTION "pipeline"."layer3_cascade_test_cap_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "pipeline"."layer3_cascade_test_spent_usd"() RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
  select coalesce(sum(cost_usd),0) from pipeline.layer3_holdout_results where run_label like 'c-%'
$$;


