CREATE OR REPLACE FUNCTION "public"."admin_adapter_autobuild"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_pid uuid := nullif(p_args->>'provider_id', '')::uuid; v_reason text := btrim(coalesce(p_args->>'reason', ''));
        v_today int; v_cap int; v_id uuid; v jsonb;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 5 then raise exception 'PIM Operator or Platform Admin required' using errcode = '42501'; end if;
  if p_action = 'states' then
    select coalesce(jsonb_object_agg(x.id, security.adapter_autobuild_state_v1(x.id::uuid)), '{}'::jsonb) into v
      from (select distinct jsonb_array_elements_text(coalesce(p_args->'provider_ids', '[]'::jsonb)) id limit 200) x;
    return v;
  end if;
  if p_action = 'read' then
    return security.adapter_autobuild_state_v1(v_pid) || jsonb_build_object('can_manage', v_rank >= 6,
      'today', (select count(*) from pipeline.adapter_autobuilds b where (b.created_at at time zone 'Australia/Melbourne')::date = (now() at time zone 'Australia/Melbourne')::date),
      'per_day', (security.firecrawl_setting('autobuild_per_day') #>> '{}')::int,
      'model', security.ai_route_v1('adapter_builder')->>'model');
  end if;
  if v_rank < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action = 'start' then
    if not exists (select 1 from catalogue.providers where id = v_pid) then raise exception 'unknown provider'; end if;
    if exists (select 1 from pipeline.uni_adapters u where u.provider_id = v_pid and u.admit) then raise exception 'this provider already has an admitting adapter: change it in the builder instead'; end if;
    if exists (select 1 from pipeline.adapter_autobuilds b where b.provider_id = v_pid and b.status not in ('done', 'failed', 'stopped')) then raise exception 'a build is already running for this provider'; end if;
    v_today := (select count(*) from pipeline.adapter_autobuilds b where (b.created_at at time zone 'Australia/Melbourne')::date = (now() at time zone 'Australia/Melbourne')::date);
    v_cap := coalesce((security.firecrawl_setting('autobuild_per_day') #>> '{}')::int, 25);
    if v_today >= v_cap then raise exception 'the automatic builds for today are used (% of %). It is a setting under Adapter builder', v_today, v_cap; end if;
    insert into pipeline.adapter_autobuilds(provider_id, credits_cap, requested_by, reason, note)
    values (v_pid, coalesce((security.firecrawl_setting('autobuild_credits') #>> '{}')::int, 150), auth.uid(), v_reason, 'Waiting to start (within 2 minutes).')
    returning id into v_id;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'adapter_autobuild_start', v_pid::text, jsonb_build_object('build_id', v_id, 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true, 'build_id', v_id);
  elsif p_action = 'stop' then
    update pipeline.adapter_autobuilds set status = 'stopped', note = 'Stopped by a Platform Admin: ' || v_reason, updated_at = now()
     where provider_id = v_pid and status not in ('done', 'failed', 'stopped') returning id into v_id;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'adapter_autobuild_stop', v_pid::text, jsonb_build_object('build_id', v_id, 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', v_id is not null);
  end if;
  raise exception 'unknown action';
end $$;


ALTER FUNCTION "public"."admin_adapter_autobuild"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_adapter_build"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', ''));
  v_pid uuid := nullif(p_args->>'provider_id', '')::uuid; v_pids uuid[]; v_cc text := upper(nullif(btrim(p_args->>'country'), ''));
  v_q text := nullif(btrim(p_args->>'query'), ''); v_stage text := nullif(btrim(p_args->>'stage'), ''); v_wave text := nullif(btrim(p_args->>'wave'), '');
  v_limit int := least(greatest(coalesce((p_args->>'limit')::int, 50), 1), 200);  -- fixed: page size bounds
  v_offset int := greatest(coalesce((p_args->>'offset')::int, 0), 0);
  r jsonb; v_fields text[]; v_adapter text[]; v_enrich text[]; v_done jsonb := '[]'::jsonb; v_job jsonb; v_m int; v_open uuid[]; v_stopped uuid[]; v_new uuid[]; p uuid; v_item jsonb;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  v_pids := coalesce(array(select x::uuid from jsonb_array_elements_text(coalesce(p_args->'provider_ids', '[]'::jsonb)) x), '{}');
  if v_pid is not null then v_pids := array_append(v_pids, v_pid); end if;

  if p_action in ('list', 'waves') then
    return (with base as (
      select pr.id provider_id, coalesce(pr.display_name, pr.canonical_name) name, k.iso_alpha2::text country,
             (select count(*) from catalogue.courses c where c.provider_id = pr.id and c.lifecycle_status = 'active') courses,
             b.pages_read, b.ready, b.review, b.not_ready, b.adds, b.checked_at, b.wave, b.readiness->'ready' ready_fields,
             u.enabled adapter_on, coalesce(u.admit, false) and cardinality(coalesce(u.admit_fields, '{}')) > 0 admitting,
             o.status onboarding, o.stop_reason, o.note onboarding_note,
             case when o.status is not null and o.status not in ('done', 'cancelled', 'stopped') then 'building'
                  when coalesce(u.admit, false) and cardinality(coalesce(u.admit_fields, '{}')) > 0 then 'admitted'
                  when u.enabled then 'tested'
                  when o.status = 'stopped' and o.stop_reason in ('too_few_pages', 'no_website') then 'needs_pages'
                  when o.status = 'stopped' then 'stopped'
                  else 'no_adapter' end stage
        from catalogue.providers pr
        join ref.countries k on k.id = pr.country_id
        left join pipeline.uni_adapters u on u.provider_id = pr.id
        left join pipeline.adapter_builds b on b.provider_id = pr.id
        left join lateral (select * from pipeline.provider_onboarding o where o.provider_id = pr.id order by o.created_at desc limit 1) o on true
       where coalesce(pr.lifecycle_status, 'active') = 'active'
         and k.iso_alpha2::text = any (security.catalogue_country_codes_v1())
         and exists (select 1 from catalogue.courses c where c.provider_id = pr.id and c.lifecycle_status = 'active')
         and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = pr.id)
         and (v_cc is null or k.iso_alpha2::text = v_cc)
         and (v_q is null or pr.canonical_name ilike '%' || v_q || '%' or coalesce(pr.display_name, '') ilike '%' || v_q || '%')
         and (v_wave is null or b.wave = v_wave)),
      f as (select * from base where v_stage is null or stage = v_stage)
      select case when p_action = 'waves' then
        jsonb_build_object('waves', coalesce((select jsonb_agg(jsonb_build_object('wave', w.wave, 'universities', w.n, 'courses', w.courses, 'by_stage', w.by_stage, 'ready', w.ready, 'review', w.review, 'not_ready', w.not_ready, 'adds', w.adds) order by w.wave)
                    from (select wave, count(*) n, sum(courses) courses, sum(ready) ready, sum(review) review, sum(not_ready) not_ready, sum(adds) adds,
                                 (select jsonb_object_agg(s.stage, s.n) from (select stage, count(*) n from base b2 where b2.wave = b1.wave group by stage) s) by_stage
                            from base b1 where wave is not null group by wave) w), '[]'::jsonb))
      else jsonb_build_object(
        'summary', (select jsonb_build_object('universities', count(*), 'courses', sum(courses), 'by_stage', (select jsonb_object_agg(s.stage, s.n) from (select stage, count(*) n from base group by stage) s),
                                              'ready', sum(ready), 'review', sum(review), 'not_ready', sum(not_ready), 'adds', sum(adds)) from base),
        'total', (select count(*) from f), 'limit', v_limit, 'offset', v_offset,
        'items', coalesce((select jsonb_agg(to_jsonb(z))
                             from (select * from f order by case stage when 'tested' then 1 when 'building' then 2 when 'needs_pages' then 3 when 'stopped' then 4 when 'no_adapter' then 5 else 6 end,
                                                          adds desc nulls last, courses desc, name limit v_limit offset v_offset) z), '[]'::jsonb),
        'can_build', v_rank >= 5, 'can_admit', v_rank >= 6) end
      from (select 1) one);

  elsif p_action = 'read' then
    if v_pid is null then raise exception 'choose a university'; end if;
    r := case when v_rank >= 5 then security.adapter_build_store_v1(v_pid) else security.adapter_build_fields_v1(v_pid) end;
    return r || jsonb_build_object(
      'university', (select jsonb_build_object('name', coalesce(pr.display_name, pr.canonical_name), 'website', pr.website, 'country', k.iso_alpha2) from catalogue.providers pr join ref.countries k on k.id = pr.country_id where pr.id = v_pid),
      'courses', (select count(*) from catalogue.courses c where c.provider_id = v_pid and c.lifecycle_status = 'active'),
      'pages', (select jsonb_build_object('bound', count(*), 'read', count(*) filter (where read_status = 'read' and identity_basis is not null),
                                          'other_course', count(*) filter (where read_status = 'identity_mismatch'), 'unreadable', count(*) filter (where read_status in ('fetch_failed', 'blocked', 'refused_host', 'robots_disallowed', 'needs_render', 'too_thin')))
                  from pipeline.coverage_course_pages where provider_id = v_pid),
      'links_fixed', (select count(*) from pipeline.admin_control_events e where e.action = 'rebind' and e.area = 'coverage'
                         and (e.detail->>'course_id')::uuid in (select c.id from catalogue.courses c where c.provider_id = v_pid)),
      'adapter', (select jsonb_build_object('enabled', u.enabled, 'admit', u.admit, 'admit_fields', u.admit_fields, 'updated_at', u.updated_at, 'patterns', (select jsonb_agg(k) from jsonb_object_keys(coalesce(u.patterns, '{}'::jsonb)) k)) from pipeline.uni_adapters u where u.provider_id = v_pid),
      'build', (select jsonb_build_object('status', o.status, 'stage', security.provider_onboarding_stage_v1(o.status, o.stop_reason, o.result), 'stop_reason', o.stop_reason, 'note', o.note,
                                          'started_at', o.started_at, 'finished_at', o.finished_at, 'updated_at', o.updated_at)
                  from pipeline.provider_onboarding o where o.provider_id = v_pid order by o.created_at desc limit 1),
      'ai_cost_usd', (select round(coalesce(sum(d.cost_usd), 0), 3) from pipeline.uni_adapter_drafts d where d.provider_id = v_pid),
      'wave', (select wave from pipeline.adapter_builds where provider_id = v_pid),
      'admitted', (select admitted from pipeline.adapter_builds where provider_id = v_pid),
      'can_build', v_rank >= 5, 'can_admit', v_rank >= 6);

  elsif p_action = 'build' then
    if v_rank < 5 then raise exception 'PIM Operator or Platform Admin required' using errcode = '42501'; end if;
    if length(v_reason) < 4 then raise exception 'give a reason (kept with the build)'; end if;
    v_pids := array(select i from unnest(v_pids) i where not security.flag_provider_held_v1(i, array['course_pages_not_found']));  -- CF-247 20 Oct 2026: held providers are left out
    if cardinality(v_pids) = 0 then raise exception 'choose universities (those held because their course pages could not be found are left out until released)'; end if;
    v_open := array(select distinct o.provider_id from pipeline.provider_onboarding o where o.provider_id = any (v_pids) and o.status not in ('done', 'cancelled', 'stopped'));
    v_stopped := array(select o.id from (select distinct on (o.provider_id) o.* from pipeline.provider_onboarding o where o.provider_id = any (v_pids) order by o.provider_id, o.created_at desc) o
                        where o.status = 'stopped');
    v_new := array(select i from unnest(v_pids) i where i <> all (v_open)
                     and not exists (select 1 from pipeline.provider_onboarding o where o.provider_id = i and o.status = 'stopped'
                                       and o.created_at = (select max(o2.created_at) from pipeline.provider_onboarding o2 where o2.provider_id = i)));
    if cardinality(v_stopped) > 0 then perform public.admin_provider_onboarding('retry', jsonb_build_object('ids', to_jsonb(v_stopped), 'reason', 'Build adapter: ' || v_reason)); end if;
    if cardinality(v_new) > 0 then perform public.admin_provider_onboarding('start', jsonb_build_object('provider_ids', to_jsonb(v_new), 'reason', 'Build adapter: ' || v_reason)); end if;
    if v_wave is not null then
      insert into pipeline.adapter_builds(provider_id, wave) select i, v_wave from unnest(v_pids) i
      on conflict (provider_id) do update set wave = excluded.wave, updated_at = now();
    end if;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('adapters', 'build', cardinality(v_pids) || ' universities', jsonb_build_object('decision', 267, 'reason', v_reason, 'wave', v_wave, 'started', cardinality(v_new), 'retried', cardinality(v_stopped), 'already_building', cardinality(v_open), 'provider_ids', to_jsonb(v_pids)), auth.uid());
    return jsonb_build_object('started', cardinality(v_new), 'retried', cardinality(v_stopped), 'already_building', cardinality(v_open));

  elsif p_action = 'set_wave' then
    if v_rank < 5 then raise exception 'PIM Operator or Platform Admin required' using errcode = '42501'; end if;
    if cardinality(v_pids) = 0 then raise exception 'choose universities'; end if;
    insert into pipeline.adapter_builds(provider_id, wave) select i, v_wave from unnest(v_pids) i
    on conflict (provider_id) do update set wave = excluded.wave, updated_at = now();
    return jsonb_build_object('ok', true, 'wave', v_wave, 'universities', cardinality(v_pids));

  elsif p_action = 'admit' then
    if v_rank < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
    if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
    if cardinality(v_pids) = 0 then raise exception 'choose universities'; end if;
    v_fields := case when p_args ? 'fields' then array(select jsonb_array_elements_text(p_args->'fields')) end;
    foreach p in array v_pids loop
      r := security.adapter_build_store_v1(p);
      -- only Ready fields are admitted, whatever was asked
      v_adapter := array(select f from jsonb_array_elements_text(r->'ready') f where f in ('intakes', 'fee', 'english', 'delivery') and (v_fields is null or f = any (v_fields)) and not (r->'fields'->f->>'admitted')::boolean);
      -- duration, campus and study level fill only what the catalogue lacks, so they run whenever a Ready field has values to add
      v_enrich := array(select f from jsonb_array_elements_text(r->'ready') f where f in ('duration', 'campus', 'study_level') and (v_fields is null or f = any (v_fields)) and (r->'fields'->f->>'new')::int > 0);
      v_m := null; v_job := null;
      if cardinality(v_adapter) > 0 then
        -- 18 Oct 2026 (first wave): the source approvals the admit jobs need are made here, once. Two admit jobs starting in the same minute
        -- each tried to create a missing one and the second failed (coverage-admit-intakes, Loyalist College, 05:40 UTC).
        insert into search.enrichment_source_gates(projection_code, domain_code, source_id, gate_status, approval_ref, approved_at, created_at, updated_at)
        select 'courses', d, security.coverage_sweep_source(p), 'approved', 'CF-CHG-20260915-247; Decision 267 (Build adapter: a Platform Admin admits Ready fields)', now(), now(), now()
          from unnest(array_remove(array['official_course_url', case when 'intakes' = any (v_adapter) then 'course_intake' end,
                                         case when 'english' = any (v_adapter) then 'course_english' end, case when 'fee' = any (v_adapter) then 'provider_current_tuition' end], null)) d
        on conflict do nothing;
        perform public.admin_uni_adapter_control('admit', jsonb_build_object('provider_id', p, 'admit', true, 'reason', 'Build adapter: ' || v_reason,
                  'fields', to_jsonb(array(select distinct f from unnest(coalesce((select u.admit_fields from pipeline.uni_adapters u where u.provider_id = p and u.admit), '{}') || v_adapter) f order by f))));
      end if;
      if cardinality(v_enrich) > 0 then
        -- 18 Oct 2026 (wave 2 check): a course tried before and held as "no value" is tried again when its page reading now gives a value
        -- for the field (new input). Only those flags are released, with the reason; the rest stay held.
        update pipeline.enrichment_flags f set state = 'released', cleared_at = now(), released_at = now(), release_kind = 'auto',
               release_reason = 'Build adapter: the course page reading now gives a value (Decision 267)', updated_at = now()
         where f.entity = 'course' and f.reason_code = 'enrich_no_value' and f.state in ('raised', 'counting')
           and f.field in (select case x when 'study_level' then 'level' else x end from unnest(v_enrich) x)
           and exists (select 1 from pipeline.coverage_course_pages g join catalogue.courses c on c.id = g.course_id and c.provider_id = p and c.lifecycle_status = 'active'
                        where g.course_id::text = f.entity_key and g.read_status = 'read' and g.identity_basis is not null
                          and case f.field when 'duration' then security.enrich_parse_duration_v1(g.candidates->'adapter_extra'->>'duration') is not null
                                           when 'level' then security.enrich_parse_level_v1(coalesce(g.candidates->'adapter_extra'->>'study_level', g.candidates->'adapter_extra'->>'aqf_level')) is not null
                                           when 'campus' then nullif(btrim(coalesce(g.candidates->'adapter_extra'->>'campus', g.candidates->'adapter_extra'->>'location')), '') is not null
                                           else false end);
        v_job := public.admin_enrich_fields('start', jsonb_build_object('provider_ids', jsonb_build_array(p), 'reason', 'Build adapter: ' || v_reason,
                  'fields', to_jsonb(array(select case f when 'study_level' then 'level' else f end from unnest(v_enrich) f))));
      end if;
      if 'majors' in (select jsonb_array_elements_text(r->'ready')) and (v_fields is null or 'majors' = any (v_fields)) and (r->'fields'->'majors'->>'new')::int > 0 then
        v_m := security.adapter_build_admit_majors_v1(p);
      end if;
      v_item := jsonb_build_object('provider_id', p, 'adapter_fields', to_jsonb(v_adapter), 'enrich_fields', to_jsonb(v_enrich), 'enrich_job', v_job->'job_id', 'majors_written', v_m,
                              'left_for_review', r->'review', 'not_ready', r->'not_ready');
      update pipeline.adapter_builds set admitted = admitted
               || coalesce((select jsonb_object_agg(f, jsonb_build_object('at', now(), 'by', auth.uid(), 'job_id', v_job->'job_id')) from unnest(v_enrich) f), '{}'::jsonb)
               || case when v_m is not null then jsonb_build_object('majors', jsonb_build_object('at', now(), 'by', auth.uid(), 'written', v_m)) else '{}'::jsonb end,
             updated_at = now()
       where provider_id = p;
      v_done := v_done || v_item;
    end loop;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('adapters', 'build_admit', cardinality(v_pids) || ' universities', jsonb_build_object('decision', 267, 'reason', v_reason, 'fields_asked', to_jsonb(v_fields), 'done', v_done), auth.uid());
    return jsonb_build_object('admitted', v_done);
  end if;
  raise exception 'unknown action %', p_action using errcode = '22023';
end $$;


ALTER FUNCTION "public"."admin_adapter_build"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_adapter_builder"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_pid uuid := nullif(p_args->>'provider_id', '')::uuid; v_reason text := btrim(coalesce(p_args->>'reason', ''));
        v_id uuid; v_d pipeline.uni_adapter_drafts%rowtype; v_n int; v_b jsonb; v_samples jsonb; v_m jsonb; v_s jsonb; v_cid uuid; v_code text; v_host text; v_dom text;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 5 then raise exception 'Platform Admin or Operator required' using errcode = '42501'; end if;
  if p_action = 'read' then
    return jsonb_build_object('budget', security.adapter_builder_budget(), 'can_manage', v_rank >= 6,
      'model', security.adapter_builder_model_for_v1(v_pid), 'models', case when v_rank >= 6 then security.adapter_builder_models_v1() else '[]'::jsonb end,
      'max_samples', 10,
      -- v2.15.232 (Feature 2): the provider's courses, to attach a course page entered by hand as a sample
      'courses', case when v_rank >= 6 then coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'course', coalesce(c.display_title, c.canonical_title),
                   'code', (select cr.registration_code from catalogue.course_registrations cr where cr.course_id = c.id and lower(cr.scheme) = 'cricos' limit 1)) order by coalesce(c.display_title, c.canonical_title))
                   from catalogue.courses c where c.provider_id = v_pid and c.lifecycle_status = 'active'), '[]'::jsonb) else '[]'::jsonb end,
      'website', (select p.website from catalogue.providers p where p.id = v_pid),
      'pages', case when v_rank >= 6 then coalesce((select jsonb_agg(jsonb_build_object('course', x.title, 'code', x.code, 'url', x.url, 'read', x.read_status = 'read') order by x.title) from (
                 select distinct on (pg.url) coalesce(c.display_title, c.canonical_title) title, pg.url, pg.read_status,
                        (select cr.registration_code from catalogue.course_registrations cr where cr.course_id = pg.course_id and lower(cr.scheme) = 'cricos' limit 1) code
                   from pipeline.coverage_course_pages pg join catalogue.courses c on c.id = pg.course_id
                  where pg.provider_id = v_pid and pg.url is not null limit 600) x), '[]'::jsonb) else '[]'::jsonb end,
      'drafts', coalesce((select jsonb_agg(to_jsonb(d) order by d.created_at desc) from (select * from pipeline.uni_adapter_drafts where provider_id = v_pid order by created_at desc limit 3) d), '[]'::jsonb));
  end if;
  if v_rank < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action = 'model' then
    if not exists (select 1 from catalogue.providers where id = v_pid) then raise exception 'unknown provider'; end if;
    v_code := nullif(btrim(coalesce(p_args->>'profile_code', '')), '');
    if v_code is null then
      delete from pipeline.uni_adapter_models where provider_id = v_pid;
    else
      if not exists (select 1 from jsonb_array_elements(security.adapter_builder_models_v1()) x where x->>'code' = v_code) then
        raise exception 'that model is not enabled and qualified for intake work (Models & services)';
      end if;
      insert into pipeline.uni_adapter_models(provider_id, profile_code, set_by, reason) values (v_pid, v_code, auth.uid(), v_reason)
        on conflict (provider_id) do update set profile_code = excluded.profile_code, set_by = excluded.set_by, set_at = now(), reason = excluded.reason;
    end if;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'adapter_builder_model', v_pid::text, jsonb_build_object('profile_code', v_code, 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true, 'model', security.adapter_builder_model_for_v1(v_pid));
  end if;
  if p_action = 'start' then
    v_n := least(greatest(coalesce(nullif(p_args->>'samples', '')::int, (security.firecrawl_setting('builder_samples') #>> '{}')::int, 6), 1), 10);  -- v2.15.255: optional number of samples
    select coalesce(jsonb_agg(jsonb_build_object('course_id', x.course_id, 'course', x.title, 'code', x.code, 'url', x.url, 'kind', x.kind) order by x.kr, x.kind), '[]'::jsonb) into v_samples from (
      select q.*, row_number() over (partition by q.kind order by random()) kr from (
        select distinct on (pg.url) pg.course_id, coalesce(c.display_title, c.canonical_title) title, (select cr.registration_code from catalogue.course_registrations cr where cr.course_id = pg.course_id and lower(cr.scheme) = 'cricos' limit 1) code, pg.url,
               case when coalesce(c.display_title, c.canonical_title) ~* '/|, bachelor|and bachelor|double' then 'double'
                    when coalesce(c.display_title, c.canonical_title) ~* 'master|graduate|doctor|postgrad' then 'postgraduate'
                    when coalesce(c.display_title, c.canonical_title) ~* 'certificate|diploma' then 'certificate or diploma'
                    else 'undergraduate' end kind
          from pipeline.coverage_course_pages pg join catalogue.courses c on c.id = pg.course_id and c.lifecycle_status in ('active', 'inactive')
         where pg.provider_id = v_pid and pg.read_status = 'read' and pg.url is not null) q
      order by kr, kind limit v_n) x;
    if jsonb_array_length(coalesce(v_samples, '[]'::jsonb)) = 0 then raise exception 'no confirmed course page for this university yet - find pages first'; end if;
    insert into pipeline.uni_adapter_drafts(provider_id, samples, reason, created_by) values (v_pid, v_samples, v_reason, auth.uid()) returning id into v_id;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'adapter_builder_start', v_pid::text, jsonb_build_object('draft_id', v_id, 'samples', v_samples, 'reason', v_reason), auth.uid());
    perform security.fc_month_refuse_v1(1);  -- Decision 5 E-8 F2 (2 Nov 2026): a capture spends Firecrawl credits
    perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'adapter_capture', 'draft_id', v_id));
    return jsonb_build_object('ok', true, 'draft_id', v_id);
  end if;
  -- v2.15.232 (Feature 2): a course page entered by hand. It must be on the provider's own website; it is saved as the course's
  -- official page (entered by hand, locked) through admin_course_edit, then added as a sample exactly as add_sample does.
  if p_action = 'add_page' then
    v_cid := nullif(p_args->>'course_id', '')::uuid;
    select c.provider_id into v_pid from catalogue.courses c where c.id = v_cid;
    if v_pid is null then raise exception 'pick one of this provider''s courses'; end if;
    if nullif(p_args->>'provider_id', '') is not null and v_pid <> (p_args->>'provider_id')::uuid then raise exception 'that course belongs to another provider'; end if;
    v_code := btrim(coalesce(p_args->>'url', ''));
    if v_code !~* '^https?://[^\s/]+\.[^\s]+$' then raise exception 'enter a full web address starting with https://'; end if;
    v_host := lower(regexp_replace(substring(v_code from '^https?://([^/:?#]+)'), '^www\.', ''));
    select lower(regexp_replace(substring(coalesce(p.website, '') from '^(?:https?://)?([^/:?#]+)'), '^www\.', '')) into v_dom from catalogue.providers p where p.id = v_pid;
    if coalesce(v_dom, '') = '' then raise exception 'record the provider''s own website first (step 1), then add its course pages'; end if;
    if not (v_host = v_dom or v_host like '%.' || v_dom) then raise exception 'this page is not on the provider''s own website (%)', v_dom; end if;
    perform public.admin_course_edit(v_cid, 'set_official_url', jsonb_build_object('url', v_code, 'reason', v_reason));
    return public.admin_adapter_builder('add_sample', jsonb_build_object('course_id', v_cid, 'reason', v_reason));
  end if;
  if p_action = 'add_sample' then
    v_cid := nullif(p_args->>'course_id', '')::uuid;
    select jsonb_build_object('course_id', pg.course_id, 'course', coalesce(c.display_title, c.canonical_title),
             'code', (select cr.registration_code from catalogue.course_registrations cr where cr.course_id = pg.course_id and lower(cr.scheme) = 'cricos' limit 1),
             'url', pg.url, 'kind', 'chosen'), pg.provider_id
      into v_s, v_pid
      from pipeline.coverage_course_pages pg join catalogue.courses c on c.id = pg.course_id
     where pg.url is not null and (pg.course_id = v_cid or (v_cid is null and pg.provider_id = v_pid and pg.url = nullif(p_args->>'url', '')))
     order by (pg.read_status = 'read') desc limit 1;
    if v_s is null then raise exception 'this course has no stored page to sample'; end if;
    select * into v_d from pipeline.uni_adapter_drafts where provider_id = v_pid order by created_at desc limit 1;
    if v_d.id is not null and v_d.status in ('capturing', 'proposing') then raise exception 'the current samples are still being captured or proposed; try again in a minute'; end if;
    if v_d.id is null then
      insert into pipeline.uni_adapter_drafts(provider_id, samples, reason, created_by) values (v_pid, jsonb_build_array(v_s), v_reason, auth.uid()) returning id into v_id;
    else
      if exists (select 1 from jsonb_array_elements(v_d.samples) x where x->>'url' = v_s->>'url') then raise exception 'this page is already a sample'; end if;
      if jsonb_array_length(v_d.samples) >= 10 then raise exception 'a draft holds at most 10 samples: capture new samples to start again'; end if;
      update pipeline.uni_adapter_drafts set samples = samples || jsonb_build_array(v_s), status = 'capturing', updated_at = now() where id = v_d.id;
      v_id := v_d.id;
    end if;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'adapter_builder_add_sample', v_pid::text, jsonb_build_object('draft_id', v_id, 'sample', v_s, 'reason', v_reason), auth.uid());
    perform security.fc_month_refuse_v1(1);  -- Decision 5 E-8 F2 (2 Nov 2026): a capture spends Firecrawl credits
    perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'adapter_capture', 'draft_id', v_id));
    return jsonb_build_object('ok', true, 'draft_id', v_id);
  end if;
  select * into v_d from pipeline.uni_adapter_drafts where id = (p_args->>'draft_id')::uuid;
  if v_d.id is null then raise exception 'unknown draft'; end if;
  if p_action = 'marks' then
    if jsonb_typeof(coalesce(p_args->'marks', '[]'::jsonb)) <> 'array' then raise exception 'marks must be a list'; end if;
    update pipeline.uni_adapter_drafts set marks = coalesce(p_args->'marks', '[]'::jsonb), comments = left(coalesce(p_args->>'comments', ''), 4000), updated_at = now() where id = v_d.id;
    return jsonb_build_object('ok', true);
  elsif p_action = 'propose' then
    if jsonb_array_length(v_d.captures) = 0 then raise exception 'capture the sample pages first'; end if;
    v_b := security.adapter_builder_budget();
    if (v_b->>'used_usd')::numeric >= (v_b->>'limit_usd')::numeric then raise exception 'the AI allowance for today is used (US$ % of %). It is a setting under Adapter builder', v_b->>'used_usd', v_b->>'limit_usd'; end if;
    if (v_b->>'proposals')::int >= (v_b->>'limit_proposals')::int then raise exception 'the proposals for today are used (% of %). It is a setting under Adapter builder', v_b->>'proposals', v_b->>'limit_proposals'; end if;
    perform security.ai_use_refuse_v1('adapter_builder');  -- Decision 5 E-7 (2 Nov 2026)
    v_m := security.adapter_builder_model_for_v1(v_d.provider_id);
    update pipeline.uni_adapter_drafts set status = 'proposing', marks = coalesce(p_args->'marks', marks), comments = coalesce(left(p_args->>'comments', 4000), comments), model = v_m->>'model', model_profile = v_m->>'code', updated_at = now() where id = v_d.id;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'adapter_builder_propose', v_d.provider_id::text, jsonb_build_object('draft_id', v_d.id, 'budget', v_b, 'model', v_m), auth.uid());
    perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'adapter_propose', 'draft_id', v_d.id));
    return jsonb_build_object('ok', true);
  end if;
  raise exception 'unknown action';
end $_$;


ALTER FUNCTION "public"."admin_adapter_builder"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_adapter_builder_basics"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_pid uuid; v_q text; v jsonb;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 5 then raise exception 'PIM Operator or Platform Admin required' using errcode = '42501'; end if;
  if p_action = 'search' then
    v_q := btrim(coalesce(p_args->>'q', ''));
    if length(v_q) < 2 then return jsonb_build_object('providers', '[]'::jsonb); end if;
    select coalesce(jsonb_agg(x order by x->>'name'), '[]'::jsonb) into v from (
      select jsonb_build_object('provider_id', p.id, 'name', coalesce(p.display_name, p.canonical_name), 'website', p.website,
               'country', (select k.iso_alpha2 from ref.countries k where k.id = p.country_id),
               'courses', (select count(*) from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active'),
               'adapter', (select case when not u.enabled then 'off' when u.admit then 'admitting' else 'testing' end from pipeline.uni_adapters u where u.provider_id = p.id)) x
        from catalogue.providers p
       where p.lifecycle_status = 'active' and (coalesce(p.display_name, p.canonical_name) ilike '%' || v_q || '%' or p.website ilike '%' || v_q || '%')
       order by (exists (select 1 from pipeline.uni_adapters u where u.provider_id = p.id)) desc, coalesce(p.display_name, p.canonical_name) limit 20) s;
    return jsonb_build_object('providers', v);
  end if;
  if p_action <> 'basics' then raise exception 'unknown action'; end if;
  v_pid := nullif(p_args->>'provider_id', '')::uuid;
  if not exists (select 1 from catalogue.providers where id = v_pid) then raise exception 'unknown provider'; end if;
  select jsonb_build_object(
    'provider_id', p.id, 'name', coalesce(p.display_name, p.canonical_name), 'website', p.website,
    'country', (select k.iso_alpha2 from ref.countries k where k.id = p.country_id),
    'courses', (select count(*) from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active'),
    'pages', (select jsonb_build_object('stored', count(*), 'read', count(*) filter (where pg.read_status = 'read'),
                                        'needs_render', count(*) filter (where pg.read_status in ('needs_render', 'blocked')))
                from pipeline.coverage_course_pages pg where pg.provider_id = p.id),
    'adapter', (select jsonb_build_object('enabled', u.enabled, 'admit', u.admit, 'admit_fields', u.admit_fields, 'notes', left(coalesce(u.notes, ''), 600),
                                          'updated_at', u.updated_at, 'patterns', (select count(*) from jsonb_object_keys(coalesce(u.patterns, '{}'::jsonb))),
                                          'json_paths', (select count(*) from jsonb_object_keys(coalesce(u.json_paths, '{}'::jsonb))))
                  from pipeline.uni_adapters u where u.provider_id = p.id),
    'qualify', case when exists (select 1 from pipeline.uni_adapters u where u.provider_id = p.id) then security.adapter_qualify_one_v1(p.id, 0.5, 0.9) end,
    'central', (select coalesce(jsonb_agg(jsonb_build_object('kind', f.kind, 'url', f.url, 'status', f.status, 'found_via', f.found_via,
                         'decision', f.decision) order by f.kind, f.rank, f.updated_at desc), '[]'::jsonb)
                  from pipeline.provider_fact_sources f where f.provider_id = p.id and f.status not in ('failed', 'no_values')),
    'suggested', (select coalesce(jsonb_agg(jsonb_build_object('kind', s.kind, 'url', s.url, 'title', s.title, 'source', s.source) order by s.kind, s.source, s.rn), '[]'::jsonb) from (select distinct on (q.kind, q.url) q.* from (
                    -- v2.15.245 (Feature 4): pages found by the Firecrawl map of the site, then those among its stored links
                    select m.kind, m.url, m.title, 'map'::text source, m.rn from (select e->>'kind' kind, e->>'url' url, e->>'title' title, row_number() over (partition by e->>'kind' order by (e->>'score')::numeric desc) rn
                      from pipeline.provider_central_search cs, jsonb_array_elements(coalesce(cs.found, '[]'::jsonb)) e where cs.provider_id = p.id) m
                     where m.rn <= 3 and not exists (select 1 from pipeline.provider_fact_sources f where f.provider_id = p.id and f.kind = m.kind and f.url = m.url)
                    union all
                    select * from (select k.kind, u.url, u.title, 'links'::text source, row_number() over (partition by k.kind order by length(u.url)) rn
                      from pipeline.coverage_provider_urls u
                      cross join lateral (select case
                               when u.url ~* '(key-?dates|academic-?calendar|semester-?dates|term-?dates|important-?dates|principal-?dates)' then 'intake_calendar'
                               when u.url ~* '(international.*(fee|tuition)|(fee|tuition).*international|fee-?schedule|tuition-?fees)' then 'fee_schedule'
                               when u.url ~* '(english-?language-?requirement|english-?requirement|english-?proficiency)' then 'english_policy' end kind) k
                     where u.provider_id = p.id and k.kind is not null
                       and not exists (select 1 from pipeline.provider_fact_sources f where f.provider_id = p.id and f.kind = k.kind and f.url = u.url)) l where l.rn <= 3) q order by q.kind, q.url, (q.source <> 'map')) s),
    -- v2.15.245 (Fix 3, Features 1-4): where the website came from, the central page search, contacts and every course's page
    'website_found', (select jsonb_build_object('website', d.website, 'source', d.site_source, 'status', d.status, 'searched_at', d.site_searched_at, 'requested', d.requested_at is not null,
                        'basis', d.site_evidence->>'basis', 'note', d.site_evidence->>'note', 'refused', d.site_evidence->>'refused') from pipeline.coverage_provider_discovery d where d.provider_id = p.id),
    'central_search', (select jsonb_build_object('state', s.state, 'searched_at', s.searched_at, 'requested', s.requested_at is not null, 'found', coalesce(jsonb_array_length(s.found), 0),
                        'error', s.evidence->>'error', 'addresses', (s.evidence->>'addresses')::int) from pipeline.provider_central_search s where s.provider_id = p.id),
    'contacts', jsonb_build_object('phone', p.phone, 'email', p.email,
                        'checked_at', (select k.checked_at from pipeline.provider_contact_checks k where k.provider_id = p.id and k.kind = 'public_general'),
                        'outcome', (select k.outcome from pipeline.provider_contact_checks k where k.provider_id = p.id and k.kind = 'public_general')),
    'course_list', (select coalesce(jsonb_agg(z.x order by z.rk, z.x->>'title'), '[]'::jsonb) from (
                      select jsonb_build_object('course_id', c.id, 'title', coalesce(c.display_title, c.canonical_title), 'code', c.course_code, 'url', g.url, 'read_status', g.read_status,
                               'state', st.state, 'search', ls.state, 'searched_at', ls.sent_at) x,
                             case st.state when 'no_page' then 1 when 'not_found' then 2 when 'wrong_page' then 3 when 'old_site' then 4 when 'searching' then 5 when 'stored' then 6 else 7 end rk
                        from catalogue.courses c
                        left join pipeline.coverage_course_pages g on g.course_id = c.id
                        left join pipeline.course_link_search ls on ls.course_id = c.id
                        cross join lateral (select case when g.read_status = 'read' and coalesce(g.status, 'bound') <> 'mismatch' then 'read'
                                                        -- 22 Oct 2026 (UTS): say what is wrong with a bound page instead of "stored, not read yet"
                                                        when g.url is not null and (g.status = 'mismatch' or g.read_status = 'identity_mismatch') and g.read_status <> 'refused_host' then 'wrong_page'
                                                        when g.url is not null and g.read_status = 'refused_host' then 'old_site'
                                                        when g.url is not null then 'stored'
                                                        when ls.state in ('queued', 'sent') then 'searching' when ls.state = 'none' then 'not_found' else 'no_page' end state) st
                       where c.provider_id = p.id and c.lifecycle_status = 'active' limit 2000) z),  -- fixed: one university's list (was 500)
    'can_manage', v_rank >= 6)
    into v from catalogue.providers p where p.id = v_pid;
  return v;
end $$;


ALTER FUNCTION "public"."admin_adapter_builder_basics"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_adapter_evaluation"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_np numeric; v_ur numeric; v_fs numeric;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 5 then raise exception 'Platform Admin or Operator required' using errcode = '42501'; end if;
  v_np := coalesce((security.firecrawl_setting('eval_no_page_share') #>> '{}')::numeric, 0.3);
  v_ur := coalesce((security.firecrawl_setting('eval_unreadable_share') #>> '{}')::numeric, 0.2);
  v_fs := coalesce((security.firecrawl_setting('eval_field_share') #>> '{}')::numeric, 0.5);
  return jsonb_build_object('settings', jsonb_build_object('no_page_share', v_np, 'unreadable_share', v_ur, 'field_share', v_fs),
    'universities', coalesce((select jsonb_agg(x order by (x->>'gap')::int desc) from (
      select jsonb_build_object('provider_id', c.provider_id, 'name', c.name, 'country', c.country, 'courses', s.courses, 'confirmed', s.confirmed, 'no_page', s.no_page, 'unreadable', s.unreadable,
               'intakes', s.intakes, 'english', s.english,
               'adapter', case when a.provider_id is null then 'none' when a.admit then 'admitting' when a.enabled then 'testing' else 'off' end,
               'gap', greatest(s.courses - s.intakes, 0) + greatest(s.courses - s.english, 0),
               'next', case when a.admit and a.enabled then 'admitting'
                            when s.courses > 0 and s.no_page::numeric / s.courses >= v_np then 'find_pages'
                            when s.courses > 0 and s.unreadable::numeric / s.courses >= v_ur then 'adapter_page_data'
                            when s.confirmed > 0 and s.intakes::numeric / s.confirmed < v_fs then 'adapter_intakes'
                            when s.confirmed > 0 and s.english::numeric / s.confirmed < v_fs then 'adapter_english'
                            else 'admit_as_is' end) x
      from pipeline.firecrawl_target_cache c
      cross join lateral (select coalesce((c.stats->>'courses')::int, 0) courses, coalesce((c.stats->>'confirmed')::int, 0) confirmed, coalesce((c.stats->>'no_page')::int, 0) no_page,
                                 coalesce((c.stats->>'unreadable')::int, 0) unreadable, coalesce((c.stats->>'intakes')::int, 0) intakes, coalesce((c.stats->>'english')::int, 0) english) s
      left join pipeline.uni_adapters a on a.provider_id = c.provider_id
      where c.included) q), '[]'::jsonb),
    'figures_at', (select max(c.stats_at) from pipeline.firecrawl_target_cache c));
end $$;


ALTER FUNCTION "public"."admin_adapter_evaluation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_adapter_measures"("p_provider_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  -- D6 (30 Oct 2026): a request through the API (JWT claims present) must be a signed-in user of rank 5 or above (Platform Admin or Operator, as written on 5 Oct 2026); a direct database session (the owner, a migration) has no claims. (current_user is always the owner inside a security definer function, so it cannot tell them apart)
  if (auth.uid() is not null or coalesce(auth.role(), '') <> '') and (auth.uid() is null or coalesce(v_rank, 0) < 5) then raise exception 'Platform Admin or Operator required' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(x order by x->>'name') from (
    select jsonb_build_object('provider_id', p.id, 'name', coalesce(p.display_name, p.canonical_name), 'country', security.coverage_country(p.id),
      'adapter', (select case when not u.enabled then 'off' when u.admit then 'admitting' else 'testing' end from pipeline.uni_adapters u where u.provider_id = p.id),
      'pages_read', count(*),
      'intakes', count(*) filter (where q.ia), 'intakes_agree', count(*) filter (where q.ia and q.held_itk = q.ad_itk), 'intakes_differ', count(*) filter (where q.ia and q.held_itk is not null and q.held_itk <> q.ad_itk), 'intakes_new', count(*) filter (where q.ia and q.held_itk is null),
      'fees', count(*) filter (where q.fa), 'fees_equal', count(*) filter (where q.fa and q.fee_held), 'fees_differ', count(*) filter (where q.fa and not q.fee_held and q.any_fee), 'fees_new', count(*) filter (where q.fa and not q.any_fee),
      'ielts', count(*) filter (where q.ea), 'extra', count(*) filter (where q.xa)) x
    from catalogue.providers p
    join lateral (
      select pg.candidates->>'intakes_by' = 'adapter' ia, pg.candidates->>'fee_by' = 'adapter' fa, pg.candidates->>'english_by' = 'adapter' ea, pg.candidates ? 'adapter_extra' xa,
             (select array_agg(distinct m order by m) from jsonb_array_elements_text(coalesce(pg.candidates->'intakes', '[]'::jsonb)) m) ad_itk,
             (select array_agg(distinct i.intake_label order by i.intake_label) from catalogue.course_intakes i where i.course_id = pg.course_id and i.status = 'active') held_itk,
             exists (select 1 from catalogue.course_fees f where f.course_id = pg.course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international' and f.amount = nullif(pg.candidates->'fee'->>'value', '')::numeric) fee_held,
             exists (select 1 from catalogue.course_fees f where f.course_id = pg.course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international') any_fee
        from pipeline.coverage_course_pages pg where pg.provider_id = p.id and pg.read_status = 'read') q on true
    where p.id = any (p_provider_ids)
    group by p.id) s), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."admin_adapter_measures"("p_provider_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_adapter_measures"("p_provider_ids" "uuid"[]) IS 'CF-247 Decision 254: adapter measures per university (pages read; intakes, fees, IELTS and extra fields read by the adapter compared with held values). Read only. D6 (30 Oct 2026): API callers must be signed in with rank 5 or above (Platform Admin or Operator); a direct owner session without JWT claims is allowed.';



CREATE OR REPLACE FUNCTION "public"."admin_adapter_shadow"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_before jsonb; v_after jsonb; v_reason text := btrim(coalesce(p_args->>'reason', ''));
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if p_action = 'summary' then return security.adapter_shadow_summary_v1(); end if;
  if p_action = 'providers' then
    return coalesce((select jsonb_agg(x order by x->>'agreement' nulls last) from (
      select jsonb_build_object('provider_id', d.provider_id, 'provider', pr.name, 'task', d.task, 'compared', count(*),
             'both_found', count(*) filter (where d.shadow_found and d.layer3_found),
             'agreement', round(count(*) filter (where d.agree)::numeric / nullif(count(*) filter (where d.shadow_found and d.layer3_found), 0), 4),
             'shadow_found', count(*) filter (where d.shadow_found), 'layer3_found', count(*) filter (where d.layer3_found)) x
        from pipeline.adapter_shadow_reads d left join catalogue.providers pr on pr.id = d.provider_id
       where d.status = 'done' and (p_args->>'task' is null or d.task = p_args->>'task')
       group by d.provider_id, pr.name, d.task having count(*) >= 5) q), '[]'::jsonb);
  end if;
  if p_action = 'settings' then
    if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
    select to_jsonb(s) into v_before from pipeline.adapter_shadow_settings s where id = 1;
    update pipeline.adapter_shadow_settings set
      enabled = coalesce((p_args->>'enabled')::boolean, enabled),
      daily_usd_max = coalesce((p_args->>'daily_usd_max')::numeric, daily_usd_max),
      daily_reads_max = coalesce((p_args->>'daily_reads_max')::int, daily_reads_max),
      reason = v_reason, updated_by = auth.uid(), updated_at = now()
    where id = 1 returning to_jsonb(adapter_shadow_settings) into v_after;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('adapter_shadow', 'settings', 'phase3', jsonb_build_object('before', v_before, 'after', v_after, 'reason', v_reason), auth.uid());
    return v_after;
  end if;
  raise exception 'action must be summary, providers or settings';
end $$;


ALTER FUNCTION "public"."admin_adapter_shadow"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_adapters"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', '')); v_pid uuid; v_ids uuid[]; v_on boolean; v_days int; v_n int;
        v_pat text := coalesce(security.firecrawl_setting('target_name_pattern') #>> '{}', '(^|[^a-z])universit(y|ies)([^a-z]|$)');
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 4 then raise exception 'Operator or above required' using errcode = '42501'; end if;
  if p_action = 'list' then
    return jsonb_build_object('as_at', now(), 'can_manage', v_rank >= 6, 'can_qualify', v_rank >= 5,
      'settings', jsonb_build_object('read_cycle_default', 90, 'read_cycle_min', 7, 'read_cycle_max', 365,
                                     'min_read_share', coalesce(security.firecrawl_setting('eval_field_share'), '0.5'::jsonb), 'min_agree_share', coalesce(security.firecrawl_setting('qualify_agree_share'), '0.9'::jsonb)),
      'adapters', coalesce((
        with t as (select * from security.firecrawl_targets_fast()),
             ids as (select a.provider_id from pipeline.uni_adapters a union select t.provider_id from t where t.included),
             pg as (select g.provider_id, count(*) pages, count(*) filter (where g.read_status = 'read') pages_read, min(g.next_read_at) filter (where g.read_status in ('read', 'identity_mismatch')) next_read, max(g.read_at) last_read
                      from pipeline.coverage_course_pages g where g.provider_id in (select ids.provider_id from ids) group by g.provider_id),
             q as (select distinct on (x.provider_id) x.provider_id, x.job_id, x.measured_at, x.passing, x.pages_read
                     from pipeline.adapter_qualifications x join pipeline.admin_jobs j on j.id = x.job_id and j.kind = 'qualify_adapters' and j.state = 'done'
                    order by x.provider_id, x.measured_at desc)
        select jsonb_agg(jsonb_build_object(
                 'provider_id', p.id, 'name', coalesce(p.display_name, p.canonical_name), 'country', k.iso_alpha2, 'state', s.code,
                 'university', coalesce(p.display_name, p.canonical_name) ~* v_pat,
                 'adapter', case when a.provider_id is null then null else jsonb_build_object('state', case when not a.enabled then 'off' when a.admit then 'admitting' else 'testing' end,
                              'fields', case when a.admit then to_jsonb(coalesce(a.admit_fields, '{}')) else '[]'::jsonb end, 'read_cycle_days', a.read_cycle_days, 'updated_at', a.updated_at, 'admit_changed_at', a.admit_changed_at) end,
                 'target', case when t.provider_id is null then null else jsonb_build_object('included', t.included, 'rule_match', t.rule_match, 'override_reason', t.override_reason,
                                                                                  'rule_reason', (select c.rule_reason from pipeline.firecrawl_target_cache c where c.provider_id = t.provider_id)) end,
                 'pages', coalesce(pg.pages, 0), 'pages_read', coalesce(pg.pages_read, 0), 'next_read', pg.next_read, 'last_read', pg.last_read,
                 'qualify', case when q.provider_id is null then null else jsonb_build_object('job_id', q.job_id, 'at', q.measured_at, 'passing', to_jsonb(q.passing), 'pages_read', q.pages_read) end)
               order by coalesce(p.display_name, p.canonical_name))
          from ids join catalogue.providers p on p.id = ids.provider_id
          left join ref.countries k on k.id = p.country_id left join ref.subdivisions s on s.id = p.subdivision_id
          left join pipeline.uni_adapters a on a.provider_id = p.id left join t on t.provider_id = p.id
          left join pg on pg.provider_id = p.id left join q on q.provider_id = p.id), '[]'::jsonb));
  end if;
  if p_action = 'detail' then
    v_pid := (p_args->>'provider_id')::uuid;
    if not exists (select 1 from catalogue.providers p where p.id = v_pid) then raise exception 'unknown provider'; end if;
    return (select jsonb_build_object(
      'provider_id', p.id, 'name', coalesce(p.display_name, p.canonical_name), 'country', k.iso_alpha2, 'state', s.code, 'website', p.website,
      'can_manage', v_rank >= 6, 'can_qualify', v_rank >= 5,
      'english_policy', (select jsonb_build_object('status', pp.status, 'style', pp.style, 'url', pp.url, 'decided_at', pp.decided_at)
                         from pipeline.provider_policy_proposals pp where pp.provider_id = p.id and pp.kind = 'english_policy' and pp.status in ('approved', 'proposed', 'no_values')
                         order by (pp.status = 'approved') desc, (pp.status = 'proposed') desc, pp.updated_at desc limit 1),
      'calendar', (select jsonb_build_object('status', pp.status, 'style', pp.style, 'url', pp.url, 'decided_at', pp.decided_at)
                   from pipeline.provider_policy_proposals pp where pp.provider_id = p.id and pp.kind = 'intake_calendar' and pp.status in ('approved', 'proposed', 'no_values')
                   order by (pp.status = 'approved') desc, (pp.status = 'proposed') desc, pp.updated_at desc limit 1),
      'central_pages', (select coalesce(jsonb_agg(jsonb_build_object('kind', x.kind, 'url', x.url, 'status', x.status, 'read_at', x.read_at, 'evidence_id', x.evidence_id) order by x.kind, x.rank desc), '[]'::jsonb)
                        from pipeline.provider_fact_sources x where x.provider_id = p.id and x.found_via = 'manual' and x.kind in ('english_policy', 'intake_calendar')),
      'courses', m.courses, 'pages_read', m.pages_read,
      'intakes', jsonb_build_object('held', m.i_held, 'adapter', m.i_adapter, 'central', m.i_central, 'reader', m.i_reader, 'excluded', m.i_x),
      'english', jsonb_build_object('held', m.e_held, 'adapter', m.e_adapter, 'central', m.e_central, 'reader', m.e_reader, 'excluded', m.e_x),
      'fee', jsonb_build_object('held', m.f_held, 'adapter', m.f_adapter, 'reader', m.f_reader, 'excluded', m.f_x),
      'schedule', (select jsonb_build_object('read_cycle_days', (select a.read_cycle_days from pipeline.uni_adapters a where a.provider_id = p.id), 'read_cycle_default', 90,
                     'next_read', min(g.next_read_at) filter (where g.read_status in ('read', 'identity_mismatch')), 'last_read', max(g.read_at),
                     'due_7_days', count(*) filter (where g.next_read_at < now() + interval '7 days'), 'due_30_days', count(*) filter (where g.next_read_at < now() + interval '30 days'),
                     'by_status', (select coalesce(jsonb_object_agg(z.st, z.n), '{}'::jsonb) from (select coalesce(g2.read_status, 'not_read') st, count(*) n from pipeline.coverage_course_pages g2 where g2.provider_id = p.id group by 1) z))
                   from pipeline.coverage_course_pages g where g.provider_id = p.id),
      'qualifications', (select coalesce(jsonb_agg(jsonb_build_object('job_id', x.job_id, 'title', j.title, 'at', x.measured_at, 'pages_read', x.pages_read, 'fields', x.fields, 'passing', to_jsonb(x.passing)) order by x.measured_at desc), '[]'::jsonb)
                         from (select * from pipeline.adapter_qualifications x where x.provider_id = p.id order by x.measured_at desc limit 5) x join pipeline.admin_jobs j on j.id = x.job_id),
      'tasks', (select coalesce(jsonb_agg(jsonb_build_object('id', j.id, 'kind', j.kind, 'state', j.state, 'title', j.title, 'created_at', j.created_at, 'finished_at', j.finished_at, 'result', j.result, 'error', j.error) order by j.created_at desc), '[]'::jsonb)
                from (select * from pipeline.admin_jobs j where j.scope = p.id::text or coalesce(j.args->'providers', '[]'::jsonb) ? p.id::text or coalesce(j.args->'provider_ids', '[]'::jsonb) ? p.id::text order by j.created_at desc limit 20) j),
      'log', (select coalesce(jsonb_agg(jsonb_build_object('at', e.created_at, 'area', e.area, 'action', e.action, 'detail', e.detail - 'courses', 'by', (select u.email from auth.users u where u.id = e.actor)) order by e.created_at desc), '[]'::jsonb)
              from (select * from pipeline.admin_control_events e where e.target = p.id::text order by e.created_at desc limit 30) e))
      from catalogue.providers p left join ref.countries k on k.id = p.country_id left join ref.subdivisions s on s.id = p.subdivision_id
      cross join lateral (select count(*) courses, count(*) filter (where cf.read_status = 'read') pages_read,
                                 count(*) filter (where cf.intakes_src <> 'missing') i_held, count(*) filter (where cf.intakes_src = 'adapter') i_adapter,
                                 count(*) filter (where cf.intakes_src = 'central') i_central, count(*) filter (where cf.intakes_src = 'reader') i_reader, count(*) filter (where cf.intakes_x) i_x,
                                 count(*) filter (where cf.english_src <> 'missing') e_held, count(*) filter (where cf.english_src = 'adapter') e_adapter,
                                 count(*) filter (where cf.english_src = 'central') e_central, count(*) filter (where cf.english_src = 'reader') e_reader, count(*) filter (where cf.english_x) e_x,
                                 count(*) filter (where cf.fee_src <> 'missing') f_held, count(*) filter (where cf.fee_src = 'adapter') f_adapter,
                                 count(*) filter (where cf.fee_src = 'reader') f_reader, count(*) filter (where cf.fee_x) f_x
                          from security.university_course_fields_v1(p.id) cf) m
     where p.id = v_pid);
  end if;
  if v_rank < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  v_ids := array(select distinct (x)::uuid from jsonb_array_elements_text(case when jsonb_typeof(p_args->'provider_ids') = 'array' then p_args->'provider_ids' else '[]'::jsonb end) x);
  if cardinality(v_ids) = 0 then raise exception 'choose at least one adapter'; end if;
  if cardinality(v_ids) > 2000 then raise exception 'choose 2000 adapters or fewer at a time'; end if;
  if p_action = 'set_on' then
    v_on := (p_args->>'on')::boolean;
    if v_on is null then raise exception 'say on or off'; end if;
    v_ids := array(select a.provider_id from pipeline.uni_adapters a where a.provider_id = any (v_ids) and a.enabled is distinct from v_on);
    update pipeline.uni_adapters set enabled = v_on, updated_at = now(), updated_by = auth.uid() where provider_id = any (v_ids);
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
      select 'toolsets', 'uni_adapter_switch', x::text, jsonb_build_object('on', v_on, 'reason', v_reason, 'together_with', cardinality(v_ids)), auth.uid() from unnest(v_ids) x;
    return jsonb_build_object('ok', true, 'changed', cardinality(v_ids), 'on', v_on);
  elsif p_action = 'set_cycle' then
    v_days := nullif(p_args->>'days', '')::int;
    if v_days is not null and (v_days < 7 or v_days > 365) then raise exception 'the read cycle is 7 to 365 days, or empty for the default'; end if;
    v_ids := array(select a.provider_id from pipeline.uni_adapters a where a.provider_id = any (v_ids));
    if cardinality(v_ids) = 0 then raise exception 'none of those universities has an adapter'; end if;
    update pipeline.uni_adapters set read_cycle_days = v_days, updated_at = now(), updated_by = auth.uid() where provider_id = any (v_ids);
    update pipeline.coverage_course_pages set next_read_at = read_at + make_interval(days => coalesce(v_days, 90)) where provider_id = any (v_ids) and read_status in ('read', 'identity_mismatch') and read_at is not null and leased_until is null;
    get diagnostics v_n = row_count;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
      select 'toolsets', 'uni_adapter_read_cycle', x::text, jsonb_build_object('days', v_days, 'reason', v_reason, 'together_with', cardinality(v_ids)), auth.uid() from unnest(v_ids) x;
    return jsonb_build_object('ok', true, 'changed', cardinality(v_ids), 'pages_rescheduled', v_n, 'days', v_days);
  end if;
  raise exception 'unknown action';
end $_$;


ALTER FUNCTION "public"."admin_adapters"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_admission_lifecycle_read_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'public'
    AS $$
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  if security.current_role_rank() < 5 then raise exception 'PIM Admin role is required' using errcode='42501'; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object(
    'data_type',p.data_type,'label',p.label,'layer',p.layer,'cycle_days',p.cycle_days,'check_days',p.check_days,
    'window_months',p.window_months,'on_demand',p.on_demand,'rationale',p.rationale,
    'profiles', case when p.layer='L2' then (select count(*) from pipeline.layer2_source_profiles sp where sp.enabled
        and sp.domain = case p.data_type when 'course_facts' then 'course_facts' when 'scholarships' then 'scholarship' when 'provider_assets' then 'provider_asset' end) end,
    'aligned', case when p.layer='L2' then (select count(*) from pipeline.layer2_source_profiles sp where sp.enabled and sp.freshness_sla_hours=p.cycle_days*24
        and sp.domain = case p.data_type when 'course_facts' then 'course_facts' when 'scholarships' then 'scholarship' when 'provider_assets' then 'provider_asset' end) end,
    'next_due', case when p.layer='L1' then (select min(o.next_ingestion_at) from pipeline.layer1_source_operations o join pipeline.sources s on s.id=o.source_id
        where (p.data_type='regulatory_register' and (s.label ilike 'CRICOS%' or s.label ilike 'NZQA%')) or (p.data_type='qilt' and s.label ilike 'QILT%')
           or (p.data_type='prisms' and s.label ilike '%PRISMS%') or (p.data_type='rankings' and (s.label ilike 'QS %' or s.label ilike 'Times Higher%'))) end
  ) order by p.layer, p.data_type),'[]'::jsonb) from pipeline.admission_lifecycle_policy p);
end $$;


ALTER FUNCTION "public"."admin_admission_lifecycle_read_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_aer"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := coalesce(security.current_role_rank(), 0); a jsonb; v_size int; v_off int; v_sort text; v_dir text; v_sql text; v_total int; v_rows jsonb;
        v_kind text; v_id uuid; v_reason text; v_exp timestamptz; v_cur jsonb; v_new jsonb; ch jsonb; v_key text; v_txt text; v_num numeric; v_lvl uuid;
        m catalogue.provider_entry_matrix%rowtype; x catalogue.course_entry_requirements%rowtype; v_out jsonb; v_cc text; v_ev pipeline.evidence_artifacts%rowtype;
        v_src pipeline.entry_matrix_sources%rowtype; v_run pipeline.entry_matrix_runs%rowtype; v_c record; v_levels uuid[]; v_band text; v_last text; v_n int;
        v_editable text[]; v_fields jsonb := '{}'::jsonb;
begin
  if auth.uid() is null or v_rank < 1 then raise exception 'assigned StudySearch role required' using errcode = '42501'; end if;
  -- empty filter values mean "any"
  a := coalesce((select jsonb_object_agg(e.key, e.value) from jsonb_each(coalesce(p_args, '{}'::jsonb)) e
                  where e.value not in ('null'::jsonb, '""'::jsonb) and not (jsonb_typeof(e.value) = 'string' and btrim(e.value #>> '{}') = '')), '{}'::jsonb);
  v_size := greatest(1, least(coalesce((a->>'page_size')::int, 50), 100));  -- fixed: a page is at most 100 rows (W11)
  v_off := greatest(0, coalesce((a->>'offset')::int, 0));
  v_dir := case when lower(coalesce(a->>'direction', 'asc')) = 'desc' then 'desc' else 'asc' end;
  v_reason := btrim(coalesce(p_args->>'reason', ''));
  v_kind := coalesce(a->>'kind', 'matrix');

  -- ---------------------------------------------------------------- reads
  -- CF-247 AER Phase B (mandate 2 Nov 2026 §13, §15): AER coverage and the provider drill-down, Curator (rank 3) and above only;
  -- viewers and counsellors see none of it
  if p_action in ('coverage', 'coverage_provider') then
    if v_rank < 3 then raise exception 'curator role required: AER coverage is for operations roles' using errcode = '42501'; end if;
    return security.aer_coverage_read_v1(p_action, a);
  end if;
  if p_action = 'summary' then
    return jsonb_build_object(
      'matrix', (select coalesce(jsonb_object_agg(s, n), '{}'::jsonb) from (select m0.status s, count(*) n from catalogue.provider_entry_matrix m0
                  where (a->>'provider_id' is null or m0.provider_id = (a->>'provider_id')::uuid) and (a->>'country' is null or m0.country_code = upper(a->>'country')) group by 1) z),
      'course', (select coalesce(jsonb_object_agg(s, n), '{}'::jsonb) from (select x0.status s, count(*) n from catalogue.course_entry_requirements x0
                  join catalogue.courses c0 on c0.id = x0.course_id where (a->>'provider_id' is null or c0.provider_id = (a->>'provider_id')::uuid) group by 1) z),
      'sources', (select jsonb_build_object('total', count(*), 'fetch_failed', count(*) filter (where s0.status = 'failed'),
                    'held', count(*) filter (where r0.state = 'failed'), 'reading', count(*) filter (where r0.state in ('queued', 'leased') or s0.status in ('found', 'reading')),
                    'read', count(*) filter (where r0.state = 'done'))
                   from pipeline.entry_matrix_sources s0
                   left join lateral (select r1.state from pipeline.entry_matrix_runs r1 where r1.source_id = s0.id order by r1.created_at desc limit 1) r0 on true
                  where a->>'provider_id' is null or s0.provider_id = (a->>'provider_id')::uuid),
      'providers_with_active', (select count(distinct m1.provider_id) from catalogue.provider_entry_matrix m1 where m1.status = 'active'),
      'providers_in_scope', (select jsonb_array_length(coalesce(security.toolset_setting('pipeline', 'entry.providers'), '[]'::jsonb))),
      'courses_with_active', (select count(distinct x1.course_id) from catalogue.course_entry_requirements x1 join catalogue.courses c1 on c1.id = x1.course_id
                               where x1.status = 'active' and (a->>'provider_id' is null or c1.provider_id = (a->>'provider_id')::uuid)),
      'courses_waiting', (select count(distinct x2.course_id) from catalogue.course_entry_requirements x2 join catalogue.courses c2 on c2.id = x2.course_id
                           where x2.status = 'proposed' and (a->>'provider_id' is null or c2.provider_id = (a->>'provider_id')::uuid)),
      'can_edit', v_rank >= 3, 'can_reread', v_rank >= 6);

  elsif p_action = 'course_programme' then
    -- W17 (29 Oct 2026): the course-level programme by provider, with cost and balance
    return security.course_entry_programme_v1(v_rank >= 6);

  elsif p_action = 'course_batch_preview' then
    -- W17: how many courses the next batch would read and what it is estimated to cost; asks nothing
    return security.course_entry_batch_v1((a->>'provider_id')::uuid, (a->>'size')::int, null, auth.uid(), true);

  elsif p_action = 'options' then
    return jsonb_build_object(
      'providers', (select coalesce(jsonb_agg(jsonb_build_object('id', z.id, 'name', z.n) order by z.n), '[]'::jsonb) from (
                     select p.id, coalesce(p.display_name, p.canonical_name) n from catalogue.providers p
                      where exists (select 1 from catalogue.provider_entry_matrix m0 where m0.provider_id = p.id)
                         or exists (select 1 from pipeline.entry_matrix_sources s0 where s0.provider_id = p.id)
                         or exists (select 1 from catalogue.course_entry_requirements x0 join catalogue.courses c0 on c0.id = x0.course_id where c0.provider_id = p.id)
                      limit 300) z),  -- fixed: option list bound (W11)
      'countries', (select coalesce(jsonb_agg(jsonb_build_object('code', z.cc, 'name', z.n) order by z.n), '[]'::jsonb) from (
                     select distinct m0.country_code cc, k0.name n from catalogue.provider_entry_matrix m0 join ref.countries k0 on k0.id = m0.country_id) z),
      'all_countries', (select coalesce(jsonb_agg(jsonb_build_object('code', k0.iso_alpha2, 'name', k0.name) order by k0.name), '[]'::jsonb) from ref.countries k0 where k0.iso_alpha2 ~ '^[A-Z]{2}$'),
      'levels', (select coalesce(jsonb_agg(jsonb_build_object('code', l0.short_code, 'name', l0.name) order by l0.sort_order), '[]'::jsonb) from ref.study_levels l0),
      'level_labels', (select coalesce(jsonb_agg(z.v order by z.v), '[]'::jsonb) from (select distinct m0.level_label v from catalogue.provider_entry_matrix m0 where m0.level_label is not null limit 300) z),
      'bands', (select coalesce(jsonb_agg(z.v order by z.v), '[]'::jsonb) from (select distinct b v from (select m0.benchmark_band b from catalogue.provider_entry_matrix m0 union select x0.benchmark_band from catalogue.course_entry_requirements x0) u where b is not null limit 300) z),
      'editions', (select coalesce(jsonb_agg(z.v order by z.v), '[]'::jsonb) from (select distinct m0.edition v from catalogue.provider_entry_matrix m0 where m0.edition is not null limit 100) z),
      'intake_years', (select coalesce(jsonb_agg(z.v order by z.v), '[]'::jsonb) from (select distinct m0.intake_year v from catalogue.provider_entry_matrix m0 where m0.intake_year is not null) z),
      'matrix_kinds', '["provider_minimum", "band_ladder", "course_minimum", "rank_band"]'::jsonb,
      'requirement_kinds', '["prior_qualification", "minimum_grade", "subject_prerequisite", "portfolio_interview", "work_experience", "other", "override", "general_note"]'::jsonb,
      'scales', '["percentage", "points", "aggregate", "gpa", "letter", "rank", "none"]'::jsonb,
      'audiences', '["international", "domestic", "all"]'::jsonb,
      'statuses', '["active", "proposed", "unverified", "inactive", "superseded"]'::jsonb);

  elsif p_action = 'matrix_list' then
    v_sort := case a->>'sort' when 'provider' then 'f.provider_name' when 'country' then 'f.country_code' when 'level' then 'f.level_label'
                when 'qualification' then 'f.qualification_name' when 'band' then 'f.benchmark_band' when 'min' then 'f.min_value'
                when 'status' then 'f.status' when 'as_at' then 'f.as_at' when 'updated' then 'f.updated_at' when 'edition' then 'f.edition'
                else 'f.provider_name' end;
    v_sql := format($q$
      with f as (
        select m.*, coalesce(p.display_name, p.canonical_name) provider_name, r.state run_state
          from catalogue.provider_entry_matrix m join catalogue.providers p on p.id = m.provider_id
          left join ref.study_levels l on l.id = m.study_level_id left join pipeline.entry_matrix_runs r on r.id = m.run_id
         where ($1->>'provider_id' is null or m.provider_id = ($1->>'provider_id')::uuid)
           and ($1->>'country' is null or m.country_code = upper($1->>'country'))
           and ($1->>'level' is null or l.short_code = $1->>'level' or m.level_label = $1->>'level')
           and ($1->>'status' is null or m.status = $1->>'status')
           and ($1->>'matrix_kind' is null or m.matrix_kind = $1->>'matrix_kind')
           and ($1->>'band' is null or m.benchmark_band = $1->>'band')
           and ($1->>'edition' is null or m.edition = $1->>'edition')
           and ($1->>'intake_year' is null or m.intake_year = ($1->>'intake_year')::int)
           and ($1->>'read_state' is null or coalesce(r.state, 'manual') = $1->>'read_state')
           and ($1->>'q' is null or m.qualification_name ilike '%%' || left($1->>'q', 100) || '%%' or m.quote ilike '%%' || left($1->>'q', 100) || '%%'
                or m.level_label ilike '%%' || left($1->>'q', 100) || '%%'))
      select (select count(*) from f)::int,
             (select coalesce(jsonb_agg(security.aer_row_v1('matrix', z.id) order by z.o), '[]'::jsonb)
                from (select f.id, row_number() over (order by %s %s nulls last, f.provider_name, f.country_code, f.qualification_name, f.id) o
                        from f order by %s %s nulls last, f.provider_name, f.country_code, f.qualification_name, f.id limit $2 offset $3) z)
    $q$, v_sort, v_dir, v_sort, v_dir);
    execute v_sql into v_total, v_rows using a, v_size, v_off;
    return jsonb_build_object('total', v_total, 'offset', v_off, 'page_size', v_size, 'rows', v_rows);

  elsif p_action = 'course_list' then
    v_sort := case a->>'sort' when 'provider' then 'f.provider_name' when 'course' then 'f.course_title' when 'kind' then 'f.kind'
                when 'status' then 'f.status' when 'as_at' then 'f.as_at' when 'updated' then 'f.updated_at' when 'score' then 'f.min_entry_score'
                else 'f.provider_name' end;
    v_sql := format($q$
      with f as (
        select x.*, c.canonical_title course_title, c.course_code, coalesce(p.display_name, p.canonical_name) provider_name
          from catalogue.course_entry_requirements x join catalogue.courses c on c.id = x.course_id join catalogue.providers p on p.id = c.provider_id
         where ($1->>'provider_id' is null or c.provider_id = ($1->>'provider_id')::uuid)
           and ($1->>'course' is null or c.course_code ilike left($1->>'course', 60) || '%%' or c.canonical_title ilike '%%' || left($1->>'course', 100) || '%%' or c.id::text = $1->>'course')
           and ($1->>'requirement_kind' is null or x.kind = $1->>'requirement_kind')
           and ($1->>'audience' is null or x.audience = $1->>'audience')
           and ($1->>'status' is null or x.status = $1->>'status')
           and ($1->>'band' is null or x.benchmark_band = $1->>'band')
           and ($1->>'as_at_from' is null or x.as_at >= ($1->>'as_at_from')::date)
           and ($1->>'as_at_to' is null or x.as_at <= ($1->>'as_at_to')::date)
           and ($1->>'q' is null or x.description ilike '%%' || left($1->>'q', 100) || '%%' or x.quote ilike '%%' || left($1->>'q', 100) || '%%'))
      select (select count(*) from f)::int,
             (select coalesce(jsonb_agg(security.aer_row_v1('course', z.id) order by z.o), '[]'::jsonb)
                from (select f.id, row_number() over (order by %s %s nulls last, f.provider_name, f.course_title, f.id) o
                        from f order by %s %s nulls last, f.provider_name, f.course_title, f.id limit $2 offset $3) z)
    $q$, v_sort, v_dir, v_sort, v_dir);
    execute v_sql into v_total, v_rows using a, v_size, v_off;
    return jsonb_build_object('total', v_total, 'offset', v_off, 'page_size', v_size, 'rows', v_rows);

  elsif p_action = 'sources_list' then
    v_sort := case a->>'sort' when 'provider' then 'f.provider_name' when 'status' then 'f.status' when 'read' then 'f.run_state'
                when 'read_at' then 'f.read_at' when 'cost' then 'f.cost_usd' else 'f.provider_name' end;
    v_sql := format($q$
      with f as (
        select s.*, coalesce(p.display_name, p.canonical_name) provider_name, r.id run_id, r.state run_state, r.cost_usd, r.error run_error,
               case when r.state = 'failed' then 'held' when r.state in ('queued', 'leased') or s.status in ('found', 'reading') then 'reading'
                    when s.status = 'failed' then 'fetch_failed' when r.state = 'done' then 'read' else 'none' end hold_state
          from pipeline.entry_matrix_sources s join catalogue.providers p on p.id = s.provider_id
          left join lateral (select r1.* from pipeline.entry_matrix_runs r1 where r1.source_id = s.id order by r1.created_at desc limit 1) r on true
         where ($1->>'provider_id' is null or s.provider_id = ($1->>'provider_id')::uuid)
           and ($1->>'status' is null or s.status = $1->>'status')
           and ($1->>'hold_state' is null or (case when r.state = 'failed' then 'held' when r.state in ('queued', 'leased') or s.status in ('found', 'reading') then 'reading'
                    when s.status = 'failed' then 'fetch_failed' when r.state = 'done' then 'read' else 'none' end) = $1->>'hold_state')
           and ($1->>'q' is null or s.url ilike '%%' || left($1->>'q', 100) || '%%' or coalesce(r.error, s.error, '') ilike '%%' || left($1->>'q', 100) || '%%'))
      select (select count(*) from f)::int,
             (select coalesce(jsonb_agg(jsonb_build_object('id', z.id, 'provider_id', z.provider_id, 'provider_name', z.provider_name, 'url', z.url, 'title', z.title,
                  'found_via', z.found_via, 'status', z.status, 'read_via', z.read_via, 'http', z.http_status, 'attempts', z.attempts, 'read_at', z.read_at,
                  'error', left(z.error, 300), 'evidence_id', z.evidence_id, 'content_hash', left(z.content_hash, 16), 'hold_state', z.hold_state,
                  'type', case when z.url ~* '\.pdf($|[?#])' then 'PDF' when z.read_via = 'firecrawl' and e.mime_type = 'text/html' then 'Rendered page' else 'Web page' end,
                  'mime', e.mime_type, 'captured_at', e.captured_at, 'stored', e.storage_path is not null,
                  'in_scope', security.entry_matrix_enabled_v1(z.provider_id),
                  'next_refresh', case when z.read_at is not null and coalesce(z.read_via, '') <> 'stored'
                                       then z.read_at + make_interval(days => security.pipeline_num_v1('entry.matrix_refresh_days', 30)::int) end,
                  'last_success', (select max(r2.done_at) from pipeline.entry_matrix_runs r2 where r2.source_id = z.id and r2.state = 'done'),
                  'run', case when z.run_id is null then null else (select jsonb_build_object('id', r3.id, 'state', r3.state, 'attempts', r3.attempts, 'rows', r3.rows_admitted,
                      'not_kept', r3.rows_dropped, 'cost_usd', r3.cost_usd, 'error', left(r3.error, 300), 'done_at', r3.done_at, 'basis', r3.result->>'page_basis',
                      'worker', r3.result->>'worker', 'outcome', r3.result->>'outcome', 'review_item_id', r3.review_item_id, 'review_status', (select li.status from pipeline.layer4_review_items li where li.id = r3.review_item_id),
                      'dropped', (select coalesce(jsonb_object_agg(d.k, d.n), '{}'::jsonb) from (select dx->>'reason' k, count(*) n from jsonb_array_elements(coalesce(r3.result->'dropped', '[]'::jsonb)) dx group by 1) d))
                    from pipeline.entry_matrix_runs r3 where r3.id = z.run_id) end) order by z.o), '[]'::jsonb)
                from (select f.*, row_number() over (order by %s %s nulls last, f.provider_name, f.url) o from f order by %s %s nulls last, f.provider_name, f.url limit $2 offset $3) z
                left join pipeline.evidence_artifacts e on e.id = z.evidence_id)
    $q$, v_sort, v_dir, v_sort, v_dir);
    execute v_sql into v_total, v_rows using a, v_size, v_off;
    return jsonb_build_object('total', v_total, 'offset', v_off, 'page_size', v_size, 'rows', v_rows, 'can_reread', v_rank >= 6,
      'ai_allowed', security.ai_use_allowed_v1('entry_matrix'));

  elsif p_action = 'row' then
    v_id := (a->>'id')::uuid; v_out := security.aer_row_v1(v_kind, v_id);
    if v_out is null then raise exception 'row not found'; end if;
    return v_out || jsonb_build_object(
      'evidence', (select jsonb_build_object('id', e.id, 'source_url', e.source_url, 'captured_at', e.captured_at, 'mime', e.mime_type, 'stored', e.storage_path is not null,
                     'content_hash', left(e.content_hash, 16)) from pipeline.evidence_artifacts e where e.id = (v_out->>'evidence_id')::uuid),
      'run', (select jsonb_build_object('id', r.id, 'state', r.state, 'model', r.model_code, 'worker', r.result->>'worker', 'prompt', r.result->>'prompt_version',
                'basis', r.result->>'page_basis', 'cost_usd', r.cost_usd, 'done_at', r.done_at) from pipeline.entry_matrix_runs r where r.id = (v_out->>'run_id')::uuid),
      'history', (select coalesce(jsonb_agg(jsonb_build_object('at', h.at, 'field', h.field, 'action', h.action, 'before', h.before, 'after', h.after, 'reason', h.reason,
                    'actor', coalesce(u.email, h.actor::text)) order by h.at desc, h.id desc), '[]'::jsonb)
                    from (select * from pipeline.manual_edit_log h0 where h0.entity = case v_kind when 'matrix' then 'entry_matrix' else 'course_entry' end
                           and h0.entity_id = v_id order by h0.at desc, h0.id desc limit 50) h left join auth.users u on u.id = h.actor),  -- fixed: 50 history entries
      'can_edit', v_rank >= 3 and v_out->>'status' in ('active', 'unverified'),
      'can_restore', v_rank >= 3 and v_out->>'status' in ('inactive', 'unverified')
                     and (select h.action from pipeline.manual_edit_log h where h.entity = case v_kind when 'matrix' then 'entry_matrix' else 'course_entry' end
                           and h.entity_id = v_id and h.action in ('withdraw', 'quarantine', 'restore') order by h.at desc, h.id desc limit 1) in ('withdraw', 'quarantine'));

  elsif p_action = 'course_search' then
    return (select coalesce(jsonb_agg(jsonb_build_object('id', z.id, 'title', z.canonical_title, 'code', z.course_code, 'provider', z.pn, 'provider_id', z.provider_id) order by z.canonical_title), '[]'::jsonb)
              from (select c.id, c.canonical_title, c.course_code, c.provider_id, coalesce(p.display_name, p.canonical_name) pn
                      from catalogue.courses c join catalogue.providers p on p.id = c.provider_id
                     where length(coalesce(a->>'q', '')) >= 2
                       and (a->>'provider_id' is null or c.provider_id = (a->>'provider_id')::uuid)
                       and (c.course_code ilike left(a->>'q', 60) || '%' or c.canonical_title ilike '%' || left(a->>'q', 100) || '%')
                     limit 20) z);  -- fixed: 20 suggestions

  elsif p_action = 'evidence_options' then
    return (select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'source_url', e.source_url, 'captured_at', e.captured_at, 'mime', e.mime_type) order by e.captured_at desc), '[]'::jsonb)
              from (select e0.* from pipeline.evidence_artifacts e0
                     where e0.storage_path is not null
                       and (e0.id in (select s0.evidence_id from pipeline.entry_matrix_sources s0 where s0.provider_id = (a->>'provider_id')::uuid)
                            or e0.id in (select g.evidence_id from pipeline.coverage_course_pages g where g.course_id = (a->>'course_id')::uuid)
                            or (a->>'url' is not null and rtrim(e0.source_url, '/') = rtrim(a->>'url', '/')))
                     order by e0.captured_at desc nulls last limit 20) e);  -- fixed: 20 stored copies

  elsif p_action = 'resolve' then
    v_id := (a->>'course_id')::uuid; v_cc := upper(coalesce(a->>'country', ''));
    v_out := security.entry_resolve_v1(v_id, v_cc);  -- the live resolver, unchanged (W13)
    select x0.id, x0.provider_id, x0.study_level_id, l.short_code, x0.canonical_title, x0.course_code, coalesce(p.display_name, p.canonical_name) pn into v_c
      from catalogue.courses x0 left join ref.study_levels l on l.id = x0.study_level_id join catalogue.providers p on p.id = x0.provider_id where x0.id = v_id;
    v_levels := array_remove(array[v_c.study_level_id] || array(
                  select l2.id from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'entry.level_equivalents'), '[]'::jsonb)) q
                    join ref.study_levels l2 on l2.short_code = split_part(q, '=', 2) where split_part(q, '=', 1) = v_c.short_code), null);
    select r.benchmark_band into v_band from catalogue.course_entry_requirements r
     where r.course_id = v_c.id and r.status = 'active' and r.benchmark_band is not null and r.audience in ('international', 'all') order by r.updated_at desc limit 1;
    return jsonb_build_object('course', jsonb_build_object('id', v_c.id, 'title', v_c.canonical_title, 'code', v_c.course_code, 'provider', v_c.pn, 'level', v_c.short_code),
      'resolution', v_out,
      'steps', jsonb_build_array(
        jsonb_build_object('step', 1, 'rule', 'course_override', 'active_rows', (select count(*) from catalogue.course_entry_requirements r left join ref.countries k5 on k5.id = r.country_id
            where r.course_id = v_c.id and r.status = 'active' and r.kind = 'override' and r.audience in ('international', 'all') and (r.country_id is null or k5.iso_alpha2 = v_cc))),
        jsonb_build_object('step', 2, 'rule', 'course_country_row', 'active_rows', (select count(*) from catalogue.provider_entry_matrix m0
            where m0.provider_id = v_c.provider_id and m0.status = 'active' and m0.country_code = v_cc and m0.course_id = v_c.id)),
        jsonb_build_object('step', 3, 'rule', 'band_ladder', 'band', v_band, 'active_rows', case when v_band is null then 0 else (select count(*) from catalogue.provider_entry_matrix m0
            where m0.provider_id = v_c.provider_id and m0.status = 'active' and m0.country_code = v_cc and m0.course_id is null and m0.matrix_kind = 'band_ladder'
              and m0.benchmark_band = v_band and (m0.study_level_id = any (v_levels) or security.entry_label_levels_v1(m0.level_label) && v_levels)) end,
            'band_table_rows', (select count(*) from catalogue.provider_entry_matrix m0 where m0.provider_id = v_c.provider_id and m0.status = 'active' and m0.country_code = v_cc
              and m0.matrix_kind = 'band_ladder' and (m0.study_level_id = any (v_levels) or security.entry_label_levels_v1(m0.level_label) && v_levels))),
        jsonb_build_object('step', 4, 'rule', 'provider_minimum', 'active_rows', (select count(*) from catalogue.provider_entry_matrix m0
            where m0.provider_id = v_c.provider_id and m0.status = 'active' and m0.country_code = v_cc and m0.course_id is null and m0.matrix_kind = 'provider_minimum'
              and (m0.study_level_id = any (v_levels) or security.entry_label_levels_v1(m0.level_label) && v_levels))),
        jsonb_build_object('step', 5, 'rule', 'contact_provider', 'active_rows', 0)),
      'not_used', jsonb_build_object(
        'proposed_matrix', (select count(*) from catalogue.provider_entry_matrix m0 where m0.provider_id = v_c.provider_id and m0.country_code = v_cc and m0.status = 'proposed'),
        'unverified_matrix', (select count(*) from catalogue.provider_entry_matrix m0 where m0.provider_id = v_c.provider_id and m0.country_code = v_cc and m0.status = 'unverified'),
        'proposed_course', (select count(*) from catalogue.course_entry_requirements r where r.course_id = v_c.id and r.status = 'proposed'),
        'levels', (select coalesce(jsonb_agg(l3.short_code), '[]'::jsonb) from ref.study_levels l3 where l3.id = any (v_levels))));
  end if;

  -- ---------------------------------------------------------------- writes (W4-W10): Curator and above, a reason, the row as read
  if p_action = 'course_batch' then
    -- W17: one bounded batch of course reads (Platform Admin); every course read goes to Layer 4
    if v_rank < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
    return security.course_entry_batch_v1((a->>'provider_id')::uuid, (a->>'size')::int, v_reason, auth.uid(), false);
  end if;
  if p_action not in ('update', 'add', 'lifecycle', 'reread') then raise exception 'unknown action %', p_action; end if;
  if p_action = 'reread' then
    if v_rank < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  elsif v_rank < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  if length(v_reason) < 5 then raise exception 'give a reason (kept in the history)' using errcode = '22023'; end if;
  if v_kind not in ('matrix', 'course') then raise exception 'unknown kind' using errcode = '22023'; end if;

  if p_action = 'reread' then
    -- W12: one source, bounded, through the one mechanism (security.aer_reread_v1, 29 Oct 2026); never past a terminal evidence hold
    return security.aer_reread_v1((a->>'source_id')::uuid, v_reason, auth.uid());
  end if;

  if p_action = 'add' then
    -- W5: a row an operator supplies from official evidence: active, provenance manual, audited
    if coalesce(btrim(a->>'quote'), '') = '' or length(a->>'quote') > 300 then raise exception 'give the exact quote from the source (up to 300 characters)' using errcode = '22023'; end if;
    if coalesce(a->>'source_url', '') !~* '^https?://[^[:space:]]+\.[^[:space:]]+$' then raise exception 'give the official source address, starting with https://' using errcode = '22023'; end if;
    select * into v_ev from pipeline.evidence_artifacts where id = (a->>'evidence_id')::uuid;
    if v_ev.id is null or v_ev.storage_path is null then raise exception 'choose the stored copy of the source page' using errcode = '22023'; end if;
    if lower(rtrim(regexp_replace(v_ev.source_url, '^https?://(www\.)?', ''), '/')) <> lower(rtrim(regexp_replace(a->>'source_url', '^https?://(www\.)?', ''), '/')) then
      raise exception 'the stored copy is of another address (%); store the source page first', v_ev.source_url using errcode = '22023'; end if;
    v_new := a;
  else
    v_id := (a->>'id')::uuid;
    begin v_exp := (p_args->>'expected_updated_at')::timestamptz; exception when others then v_exp := null; end;
    if v_exp is null then raise exception 'reload the row before changing it' using errcode = '22023'; end if;
  end if;

  if v_kind = 'matrix' then
    if p_action = 'add' then
      v_cc := upper(coalesce(a->>'country', ''));
      if not exists (select 1 from ref.countries k0 where k0.iso_alpha2 = v_cc) then raise exception 'choose the country of prior education' using errcode = '22023'; end if;
      if not exists (select 1 from catalogue.providers p0 where p0.id = (a->>'provider_id')::uuid) then raise exception 'choose the provider' using errcode = '22023'; end if;
      m.id := gen_random_uuid(); m.provider_id := (a->>'provider_id')::uuid; m.country_code := v_cc; m.country_id := (select k0.id from ref.countries k0 where k0.iso_alpha2 = v_cc);
      m.matrix_kind := coalesce(a->>'matrix_kind', 'provider_minimum'); m.audience := coalesce(a->>'audience', 'international');
      m.quote := btrim(a->>'quote'); m.source_url := btrim(a->>'source_url'); m.evidence_id := v_ev.id; m.content_hash := v_ev.content_hash;
      m.status := 'active'; m.as_at := coalesce((a->>'as_at')::date, current_date); m.conditions := '{}'::jsonb;
      m.course_id := (a->>'course_id')::uuid; m.created_at := now(); m.updated_at := now(); m.version := 1;
      if m.matrix_kind not in ('provider_minimum', 'band_ladder', 'course_minimum', 'rank_band') then raise exception 'unknown matrix kind' using errcode = '22023'; end if;
      if m.matrix_kind = 'course_minimum' and (m.course_id is null or not exists (select 1 from catalogue.courses c0 where c0.id = m.course_id and c0.provider_id = m.provider_id)) then
        raise exception 'a course minimum needs one of this provider''s courses' using errcode = '22023'; end if;
      m.provenance := jsonb_build_object('reader', 'manual', 'actor', auth.uid(), 'reason', v_reason, 'at', now(), 'evidence_id', v_ev.id);
      m.grade_scale := 'none';  -- CF-247 D5: no scale is stored by omission; "Not stated on the page" is chosen explicitly
      v_editable := array['qualification', 'level_label', 'level_code', 'band', 'min_grade', 'min_value', 'scale', 'conditions', 'edition', 'intake_year', 'as_at'];
      ch := a; v_cur := '{}'::jsonb;
    else
      select * into m from catalogue.provider_entry_matrix where id = v_id for update;
      if m.id is null then raise exception 'row not found'; end if;
      if m.updated_at is distinct from v_exp then raise exception 'this row was changed by someone else since you opened it; reload and try again' using errcode = '40001'; end if;
      v_cur := security.aer_row_v1('matrix', v_id);
      if p_action = 'update' then
        if m.status = 'proposed' then raise exception 'a proposed row is decided in Layer 4, not edited here' using errcode = '22023'; end if;
        if m.status not in ('active', 'unverified') then raise exception 'only an active or quarantined row can be corrected; restore it first' using errcode = '22023'; end if;
        v_editable := array['qualification', 'level_label', 'level_code', 'band', 'min_grade', 'min_value', 'scale', 'conditions', 'edition', 'intake_year', 'as_at'];
        ch := coalesce(p_args->'changes', '{}'::jsonb);
        if exists (select 1 from jsonb_object_keys(ch) k0 where not (k0 = any (v_editable))) then raise exception 'this field cannot be changed here' using errcode = '22023'; end if;
        if ch = '{}'::jsonb then return jsonb_build_object('ok', true, 'row', v_cur, 'changed', 0); end if;
      end if;
    end if;
    if p_action in ('update', 'add') then
      for v_key in select * from jsonb_object_keys(ch) loop
        if not (v_key = any (v_editable)) then continue; end if;
        v_txt := nullif(btrim(ch->>v_key), '');
        if v_key = 'qualification' then
          if v_txt is null or length(v_txt) > 300 then raise exception 'give the qualification as published (up to 300 characters)' using errcode = '22023'; end if; m.qualification_name := v_txt;
        elsif v_key = 'level_label' then m.level_label := left(v_txt, 120);
        elsif v_key = 'level_code' then
          if v_txt is null then m.study_level_id := null;
          else select l0.id into v_lvl from ref.study_levels l0 where l0.short_code = v_txt; if v_lvl is null then raise exception 'unknown study level' using errcode = '22023'; end if; m.study_level_id := v_lvl; end if;
        elsif v_key = 'band' then m.benchmark_band := left(v_txt, 60);
        elsif v_key = 'min_grade' then m.min_grade := left(v_txt, 120);
        elsif v_key = 'min_value' then
          if v_txt is not null and v_txt !~ '^[0-9]+(\.[0-9]+)?$' then raise exception 'the numeric value is a number, for example 65 or 3.5' using errcode = '22023'; end if; m.min_value := v_txt::numeric;
        elsif v_key = 'scale' then
          if coalesce(v_txt, 'none') not in ('percentage', 'points', 'aggregate', 'gpa', 'letter', 'rank', 'none', 'not_stated') then raise exception 'unknown scale' using errcode = '22023'; end if;
          -- CF-247 D5 (decision A4, admin §11.2): "Not stated on the page" keeps the printed grade with no scale; the website marker reads it
          if v_txt = 'not_stated' and (position('scale_stated' in pg_get_functiondef('security.entry_matrix_payload_v1(uuid,text)'::regprocedure)) = 0
                                       or position('scale_stated' in pg_get_functiondef('security.entry_resolve_v1(uuid,text)'::regprocedure)) = 0) then
            raise exception '"Not stated on the page" can be chosen once the website marker is live (D5)' using errcode = '22023'; end if;
          m.grade_scale := case when v_txt = 'not_stated' then null else coalesce(v_txt, 'none') end;
        elsif v_key = 'conditions' then m.conditions := security.aer_conditions_v1(ch->'conditions');
        elsif v_key = 'edition' then m.edition := left(v_txt, 100);
        elsif v_key = 'intake_year' then
          if v_txt is not null and (v_txt !~ '^\d{4}$' or v_txt::int not between 2000 and 2100) then raise exception 'the intake year is a year, for example 2027' using errcode = '22023'; end if; m.intake_year := v_txt::int;
        elsif v_key = 'as_at' then
          begin m.as_at := coalesce(v_txt::date, m.as_at); exception when others then raise exception 'the as-at date is a date, for example 29/10/2026' using errcode = '22023'; end;
        end if;
      end loop;
      if m.qualification_name is null then raise exception 'give the qualification as published' using errcode = '22023'; end if;
      -- W7: source-supported values, a value with its scale
      if m.min_value is not null and coalesce(m.grade_scale, 'none') = 'none' then raise exception 'a numeric value needs its scale (percentage, points, GPA, ...)' using errcode = '22023'; end if;
      -- CF-247 D5: a scale not stated on the page keeps the grade as printed and holds no number
      if m.grade_scale is null and m.min_grade is null then raise exception '"Not stated on the page" needs the grade as printed' using errcode = '22023'; end if;
      if not security.aer_band_in_quote_v1(m.benchmark_band, m.quote) then raise exception 'the band "%" is not printed in the row''s quote', m.benchmark_band using errcode = '22023'; end if;
      if not security.aer_numbers_in_quote_v1(m.min_grade, m.quote) then raise exception 'the minimum "%" is not printed in the row''s quote', m.min_grade using errcode = '22023'; end if;
      if m.min_value is not null and not security.aer_numbers_in_quote_v1(m.min_value::text, m.quote) then raise exception 'the value % is not printed in the row''s quote', m.min_value using errcode = '22023'; end if;
    end if;
    begin
      if p_action = 'add' then
        insert into catalogue.provider_entry_matrix select m.*;
        v_id := m.id;
      elsif p_action = 'update' then
        update catalogue.provider_entry_matrix set qualification_name = m.qualification_name, level_label = m.level_label, study_level_id = m.study_level_id,
               benchmark_band = m.benchmark_band, min_grade = m.min_grade, min_value = m.min_value, grade_scale = m.grade_scale, conditions = m.conditions,
               edition = m.edition, intake_year = m.intake_year, as_at = m.as_at, version = coalesce(version, 1) + 1, updated_at = clock_timestamp()
         where id = v_id;
      else  -- lifecycle
        if a->>'lifecycle' = 'withdraw' then
          if m.status <> 'active' then raise exception 'only an active row can be withdrawn' using errcode = '22023'; end if;
          update catalogue.provider_entry_matrix set status = 'inactive', status_reason = 'withdrawn: ' || v_reason, withdrawal_reason = left(v_reason, 500),
                 valid_to = current_date, updated_at = clock_timestamp() where id = v_id;
        elsif a->>'lifecycle' = 'quarantine' then
          if m.status <> 'active' then raise exception 'only an active row can be quarantined' using errcode = '22023'; end if;
          update catalogue.provider_entry_matrix set status = 'unverified', status_reason = 'quarantined: ' || v_reason, updated_at = clock_timestamp() where id = v_id;
        elsif a->>'lifecycle' = 'restore' then
          select h.action into v_last from pipeline.manual_edit_log h where h.entity = 'entry_matrix' and h.entity_id = v_id and h.action in ('withdraw', 'quarantine', 'restore')
           order by h.at desc, h.id desc limit 1;
          if m.status not in ('inactive', 'unverified') or coalesce(v_last, '') not in ('withdraw', 'quarantine') then
            raise exception 'only a row withdrawn or quarantined here can be restored; a row never admitted is decided in Layer 4' using errcode = '22023'; end if;
          update catalogue.provider_entry_matrix set status = 'active', status_reason = null, withdrawal_reason = null, valid_to = null, updated_at = clock_timestamp() where id = v_id;
        else raise exception 'unknown lifecycle action' using errcode = '22023'; end if;
      end if;
    exception when unique_violation then
      raise exception 'another active row already has this provider, country, level, band and qualification; correct that row instead' using errcode = '23505';
    end;
  else  -- course requirement rows
    if p_action = 'add' then
      if not exists (select 1 from catalogue.courses c0 where c0.id = (a->>'course_id')::uuid) then raise exception 'choose the course' using errcode = '22023'; end if;
      x.id := gen_random_uuid(); x.course_id := (a->>'course_id')::uuid; x.kind := coalesce(a->>'requirement_kind', 'minimum_grade'); x.audience := coalesce(a->>'audience', 'international');
      if x.kind not in ('prior_qualification', 'minimum_grade', 'subject_prerequisite', 'portfolio_interview', 'work_experience', 'other', 'override', 'general_note') then raise exception 'unknown requirement kind' using errcode = '22023'; end if;
      if x.audience not in ('international', 'domestic', 'all') then raise exception 'unknown audience' using errcode = '22023'; end if;
      if a->>'country' is not null then x.country_id := (select k0.id from ref.countries k0 where k0.iso_alpha2 = upper(a->>'country')); if x.country_id is null then raise exception 'unknown country' using errcode = '22023'; end if; end if;
      x.quote := btrim(a->>'quote'); x.source_url := btrim(a->>'source_url'); x.evidence_id := v_ev.id; x.status := 'active'; x.as_at := coalesce((a->>'as_at')::date, current_date);
      x.provenance := jsonb_build_object('reader', 'manual', 'actor', auth.uid(), 'reason', v_reason, 'at', now(), 'evidence_id', v_ev.id);
      x.description := btrim(coalesce(a->>'description', '')); x.created_at := now(); x.updated_at := now();
      v_editable := array['description', 'min_grade', 'min_value', 'scale', 'min_entry_score', 'min_entry_score_basis', 'band', 'as_at'];
      ch := a; v_cur := '{}'::jsonb;
    else
      select * into x from catalogue.course_entry_requirements where id = v_id for update;
      if x.id is null then raise exception 'row not found'; end if;
      if x.updated_at is distinct from v_exp then raise exception 'this row was changed by someone else since you opened it; reload and try again' using errcode = '40001'; end if;
      v_cur := security.aer_row_v1('course', v_id);
      if p_action = 'update' then
        if x.status = 'proposed' then raise exception 'a proposed row is decided in Layer 4, not edited here' using errcode = '22023'; end if;
        if x.status not in ('active', 'unverified') then raise exception 'only an active or quarantined row can be corrected; restore it first' using errcode = '22023'; end if;
        v_editable := array['description', 'min_grade', 'min_value', 'scale', 'min_entry_score', 'min_entry_score_basis', 'band', 'as_at'];
        ch := coalesce(p_args->'changes', '{}'::jsonb);
        if exists (select 1 from jsonb_object_keys(ch) k0 where not (k0 = any (v_editable))) then raise exception 'this field cannot be changed here' using errcode = '22023'; end if;
        if ch = '{}'::jsonb then return jsonb_build_object('ok', true, 'row', v_cur, 'changed', 0); end if;
      end if;
    end if;
    if p_action in ('update', 'add') then
      for v_key in select * from jsonb_object_keys(ch) loop
        if not (v_key = any (v_editable)) then continue; end if;
        v_txt := nullif(btrim(ch->>v_key), '');
        if v_key = 'description' then if v_txt is null then raise exception 'give the requirement as published' using errcode = '22023'; end if; x.description := left(v_txt, 1000);
        elsif v_key = 'min_grade' then x.min_grade := left(v_txt, 120);
        elsif v_key = 'min_value' then
          if v_txt is not null and v_txt !~ '^[0-9]+(\.[0-9]+)?$' then raise exception 'the numeric value is a number, for example 65 or 3.5' using errcode = '22023'; end if; x.min_value := v_txt::numeric;
        elsif v_key = 'scale' then
          if coalesce(v_txt, 'none') not in ('percentage', 'points', 'aggregate', 'gpa', 'letter', 'rank', 'none') then raise exception 'unknown scale' using errcode = '22023'; end if; x.grade_scale := coalesce(v_txt, 'none');
        elsif v_key = 'min_entry_score' then
          if v_txt is not null and v_txt !~ '^[0-9]+(\.[0-9]+)?$' then raise exception 'the course score is a number, for example 75' using errcode = '22023'; end if; x.min_entry_score := v_txt::numeric;
        elsif v_key = 'min_entry_score_basis' then x.min_entry_score_basis := left(v_txt, 120);
        elsif v_key = 'band' then x.benchmark_band := left(v_txt, 60);
        elsif v_key = 'as_at' then
          begin x.as_at := coalesce(v_txt::date, x.as_at); exception when others then raise exception 'the as-at date is a date, for example 29/10/2026' using errcode = '22023'; end;
        end if;
      end loop;
      if coalesce(x.description, '') = '' then raise exception 'give the requirement as published' using errcode = '22023'; end if;
      if x.min_value is not null and coalesce(x.grade_scale, 'none') = 'none' then raise exception 'a numeric value needs its scale (percentage, points, GPA, ...)' using errcode = '22023'; end if;
      if x.min_entry_score is not null and nullif(btrim(x.min_entry_score_basis), '') is null then raise exception 'a course score needs its printed basis (for example "2027 Guaranteed ATAR")' using errcode = '22023'; end if;
      if not security.aer_band_in_quote_v1(x.benchmark_band, x.quote) then raise exception 'the band "%" is not printed in the row''s quote', x.benchmark_band using errcode = '22023'; end if;
      if not security.aer_numbers_in_quote_v1(x.min_grade, x.quote) then raise exception 'the minimum "%" is not printed in the row''s quote', x.min_grade using errcode = '22023'; end if;
      if x.min_value is not null and not security.aer_numbers_in_quote_v1(x.min_value::text, x.quote) then raise exception 'the value % is not printed in the row''s quote', x.min_value using errcode = '22023'; end if;
      if x.min_entry_score is not null and not security.aer_numbers_in_quote_v1(x.min_entry_score::text, x.quote) then raise exception 'the course score % is not printed in the row''s quote', x.min_entry_score using errcode = '22023'; end if;
    end if;
    if p_action = 'add' then
      insert into catalogue.course_entry_requirements select x.*;
      v_id := x.id;
    elsif p_action = 'update' then
      update catalogue.course_entry_requirements set description = x.description, min_grade = x.min_grade, min_value = x.min_value, grade_scale = x.grade_scale,
             min_entry_score = x.min_entry_score, min_entry_score_basis = x.min_entry_score_basis, benchmark_band = x.benchmark_band, as_at = x.as_at, updated_at = clock_timestamp()
       where id = v_id;
    else
      if a->>'lifecycle' = 'withdraw' then
        if x.status <> 'active' then raise exception 'only an active row can be withdrawn' using errcode = '22023'; end if;
        update catalogue.course_entry_requirements set status = 'inactive', status_reason = 'withdrawn: ' || v_reason, updated_at = clock_timestamp() where id = v_id;
      elsif a->>'lifecycle' = 'quarantine' then
        if x.status <> 'active' then raise exception 'only an active row can be quarantined' using errcode = '22023'; end if;
        update catalogue.course_entry_requirements set status = 'unverified', status_reason = 'quarantined: ' || v_reason, updated_at = clock_timestamp() where id = v_id;
      elsif a->>'lifecycle' = 'restore' then
        select h.action into v_last from pipeline.manual_edit_log h where h.entity = 'course_entry' and h.entity_id = v_id and h.action in ('withdraw', 'quarantine', 'restore')
         order by h.at desc, h.id desc limit 1;
        if x.status not in ('inactive', 'unverified') or coalesce(v_last, '') not in ('withdraw', 'quarantine') then
          raise exception 'only a row withdrawn or quarantined here can be restored; a row never admitted is decided in Layer 4' using errcode = '22023'; end if;
        update catalogue.course_entry_requirements set status = 'active', status_reason = null, updated_at = clock_timestamp() where id = v_id;
      else raise exception 'unknown lifecycle action' using errcode = '22023'; end if;
    end if;
  end if;

  -- W10: one history entry per changed field (before and after), the actor, the time and the reason
  v_new := security.aer_row_v1(v_kind, v_id);
  if p_action = 'update' then
    insert into pipeline.manual_edit_log(entity, entity_id, field, action, before, after, reason, actor)
    select case v_kind when 'matrix' then 'entry_matrix' else 'course_entry' end, v_id, f.key, 'edit', v_cur->f.key, v_new->f.key, v_reason, auth.uid()
      from jsonb_each(v_new) f
     where f.key in ('qualification', 'level_label', 'level_code', 'band', 'min_grade', 'min_value', 'scale', 'conditions', 'edition', 'intake_year', 'as_at',
                     'description', 'min_entry_score', 'min_entry_score_basis')
       and (v_cur->f.key) is distinct from f.value;
    get diagnostics v_n = row_count;
  elsif p_action = 'add' then
    insert into pipeline.manual_edit_log(entity, entity_id, field, action, before, after, reason, actor)
    values (case v_kind when 'matrix' then 'entry_matrix' else 'course_entry' end, v_id, '*', 'add', null, v_new - 'provenance', v_reason, auth.uid());
    v_n := 1;
  else
    insert into pipeline.manual_edit_log(entity, entity_id, field, action, before, after, reason, actor)
    values (case v_kind when 'matrix' then 'entry_matrix' else 'course_entry' end, v_id, 'status', a->>'lifecycle', v_cur->'status', v_new->'status', v_reason, auth.uid());
    v_n := 1;
  end if;
  return jsonb_build_object('ok', true, 'row', v_new, 'changed', v_n);
end $_$;


ALTER FUNCTION "public"."admin_aer"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_aer"("p_action" "text", "p_args" "jsonb") IS 'CF-247 AER operations workspace (Catalogue › Entry requirements): bounded lists, summary, row history, governed edit / add / withdraw / quarantine / restore with reason, concurrency and audit (manual_edit_log), bounded source re-read, resolution inspection. Admission of AI rows stays in Layer 4.';



CREATE OR REPLACE FUNCTION "public"."admin_aer_delivery_progress"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode = '42501'; end if;
  if coalesce(security.current_role_rank(), 0) < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;  -- fixed: the Data Delivery screen's rank (admin_layer23 data_delivery)
  return security.data_delivery_aer_progress_v1() || jsonb_build_object('counted_at', now());
end $$;


ALTER FUNCTION "public"."admin_aer_delivery_progress"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_aer_delivery_progress"() IS 'CF-247 F-AER.04 (delivery item 6): Layer 2/3 › Operations, Data Delivery, AER panel stage 4 (discovery and admission). Curator and above; read only; never part of the consumer API.';



CREATE OR REPLACE FUNCTION "public"."admin_aer_discovery"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := coalesce(security.current_role_rank(), 0); v_out text := nullif(p_args->>'outcome', ''); v_q text := nullif(p_args->>'q', '');
        v_lim int := least(greatest(coalesce((p_args->>'limit')::int, 50), 1), 500); v_off int := greatest(coalesce((p_args->>'offset')::int, 0), 0);  -- fixed: page size bounds of a screen list
begin
  if (auth.uid() is not null or coalesce(auth.role(), '') <> '') and (auth.uid() is null or v_rank < 4) then
    raise exception 'Pipeline Operator or above required' using errcode = '42501'; end if;
  -- one pass over the outcomes (materialised once), then the counts and the page
  return (
    with o as materialized (select * from security.aer_discovery_outcomes_v1()),
    c as (select * from pipeline.aer_discovery_campaigns order by id desc limit 1),
    pg as (select * from o where (v_out is null or o.outcome = v_out) and (v_q is null or o.provider ilike '%' || v_q || '%')
            order by o.courses desc, o.provider limit v_lim offset v_off)
    select jsonb_build_object(
      'campaign', (select to_jsonb(c) || jsonb_build_object('credits_used', security.aer_discovery_campaign_used_v1(c.id),
                                                             'credit_cap_now', security.pipeline_num_v1('aer.discovery_campaign_credit_cap', c.credit_cap),
                                                             'asked', (select count(distinct q.provider_id) from pipeline.aer_source_discover_requests q where q.campaign_id = c.id)) from c),
      'providers', (select count(*) from o),
      'with_outcome', (select count(*) from o where o.outcome not in ('not_asked', 'searching', 'refused', 'failed')),
      'by_outcome', (select coalesce(jsonb_object_agg(z.outcome, z.n), '{}'::jsonb) from (select o.outcome, count(*) n from o group by 1) z),
      'metrics', security.aer_discovery_metrics_v1(),  -- 12 Nov 2026 (D2)
      'rows', (select coalesce(jsonb_agg(to_jsonb(pg) order by pg.courses desc, pg.provider), '[]'::jsonb) from pg)));
end $$;


ALTER FUNCTION "public"."admin_aer_discovery"("p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_aer_discovery"("p_args" "jsonb") IS 'CF-247 F-AER.04: Catalogue › Entry requirements, AER source discovery: the campaign status and, per eligible provider, source, outcome, last checked, evidence and next action (filter by outcome or name, paged). Rank 4 and above; read only; never part of the consumer API.';



CREATE OR REPLACE FUNCTION "public"."admin_aer_machine_withdraw_v1"("p_item" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if; -- fixed: rank 6 is the Platform Admin
  return security.aer_machine_withdraw_v1(p_item, p_reason, auth.uid());
end $$;


ALTER FUNCTION "public"."admin_aer_machine_withdraw_v1"("p_item" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_aer_outcomes"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := coalesce(security.current_role_rank(), 0); b pipeline.aer_course_outcome_builds%rowtype; v_build jsonb; v_page int; v_off int;
begin
  if (auth.uid() is not null or coalesce(auth.role(), '') <> '') and (auth.uid() is null or v_rank < 4) then
    raise exception 'Pipeline Operator or above required' using errcode = '42501'; end if;
  select * into b from pipeline.aer_course_outcome_builds x order by x.built_at desc limit 1;
  v_build := case when b.built_at is null then jsonb_build_object('built', false)
    else jsonb_build_object('built', true, 'built_at', b.built_at, 'took_ms', b.took_ms, 'courses', b.courses,
      'age_seconds', greatest(round(extract(epoch from now() - b.built_at)), 0)::int,
      'stale', now() - b.built_at > make_interval(mins => security.pipeline_num_v1('aer.outcome_register_stale_after_minutes', 180)::int),
      'refresh_every_minutes', security.pipeline_num_v1('aer.outcome_register_every_minutes', 60)) end;
  if coalesce(p_args->>'part', 'summary') = 'summary' then
    return jsonb_build_object('build', v_build,
      'by_outcome', coalesce((select jsonb_agg(jsonb_build_object('outcome', x.outcome, 'country', x.country, 'courses', x.n, 'published', x.np, 'providers', x.pv) order by x.outcome, x.country)
                                from (select a.outcome, a.country, count(*) n, count(*) filter (where a.provider_published) np, count(distinct a.provider_id) pv
                                        from pipeline.aer_course_outcomes a group by 1, 2) x), '[]'::jsonb),
      'by_detail', coalesce((select jsonb_agg(jsonb_build_object('outcome', x.outcome, 'detail', x.d, 'courses', x.n) order by x.outcome, x.n desc)
                               from (select a.outcome, regexp_replace(a.detail, '\d+', 'N', 'g') d, count(*) n from pipeline.aer_course_outcomes a group by 1, 2) x), '[]'::jsonb));
  end if;
  v_page := least(greatest(coalesce((p_args->>'limit')::int, security.pipeline_num_v1('aer.outcome_register_page_rows', 5000)::int), 1),
                  security.pipeline_num_v1('aer.outcome_register_page_rows', 5000)::int);
  v_off := greatest(coalesce((p_args->>'offset')::int, 0), 0);
  return jsonb_build_object('build', v_build, 'total', (select count(*) from pipeline.aer_course_outcomes), 'offset', v_off, 'limit', v_page,
    'columns', jsonb_build_array('course_id', 'course_code', 'course_title', 'provider', 'provider_published', 'country', 'outcome', 'detail',
                                 'course_url', 'page_status', 'identity_basis', 'read_state', 'read_reason', 'review_item_id', 'built_at'),
    'rows', coalesce((select jsonb_agg(jsonb_build_array(a.course_id, a.course_code, a.course_title, a.provider_name, a.provider_published, a.country, a.outcome, a.detail,
                                                         a.course_url, a.page_status, a.identity_basis, a.read_state, a.read_reason, a.review_item_id, a.built_at)
                                       order by a.country, a.provider_name, a.course_title, a.course_id)
                        from (select * from pipeline.aer_course_outcomes y order by y.country, y.provider_name, y.course_title, y.course_id offset v_off limit v_page) a), '[]'::jsonb));
end $$;


ALTER FUNCTION "public"."admin_aer_outcomes"("p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_aer_outcomes"("p_args" "jsonb") IS 'CF-247 AER production closure C1: the course outcome register for Catalogue › Entry requirements › Resolution inspection: part summary (counts by outcome and country, with build time, age and stale flag) or part rows (a page of rows for Download CSV). Rank 4 and above. Admin read only; never part of the consumer API.';



CREATE OR REPLACE FUNCTION "public"."admin_aer_qualification_lookup"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := coalesce(security.current_role_rank(), 0); v_in text := lower(btrim(coalesce(p_args->>'qualification', ''))); v_cc text := upper(nullif(btrim(p_args->>'country'), ''));
        v_code text; v_q ref.aer_qualifications%rowtype; v_lim int := least(greatest(coalesce((p_args->>'limit')::int, 200), 1), 1000);  -- fixed: list bounds of a screen read
begin
  if (auth.uid() is not null or coalesce(auth.role(), '') <> '') and (auth.uid() is null or v_rank < 4) then
    raise exception 'Pipeline Operator or above required' using errcode = '42501'; end if;
  if v_in = '' then
    return jsonb_build_object('qualifications', (select coalesce(jsonb_agg(to_jsonb(q) - 'created_at' order by q.scope, q.family, q.code), '[]'::jsonb) from ref.aer_qualifications q));
  end if;
  select * into v_q from ref.aer_qualifications q where lower(q.code) = v_in or lower(q.name) = v_in or v_in = any(q.aliases) order by (lower(q.code) = v_in) desc limit 1;
  if v_q.code is null then return jsonb_build_object('qualification', null, 'why', 'no qualification has this code, name or alias'); end if;
  return jsonb_build_object(
    'qualification', to_jsonb(v_q) - 'created_at',
    'education_country', v_cc,
    -- qualification-first requirements: global ones apply whatever the education country; a country-restricted one only for its countries; unresolved shown as such
    'requirements', (select coalesce(jsonb_agg(jsonb_build_object('provider_id', r.provider_id, 'provider', coalesce(p.display_name, p.canonical_name), 'status', r.status,
                       'applicability', r.applicability, 'applies_to_country', case when r.applicability = 'global' then true when r.applicability = 'countries' then v_cc = any(r.applicable_countries) end,
                       'level', r.level_label, 'min_grade', r.min_grade, 'min_value', r.min_value, 'scale', r.grade_scale, 'conditions', r.conditions, 'quote', r.quote, 'source_url', r.source_url)
                       order by coalesce(p.display_name, p.canonical_name), r.level_label), '[]'::jsonb)
                       from (select * from catalogue.provider_qualification_requirements r0 where r0.qualification_code = v_q.code and r0.status in ('active', 'proposed') limit v_lim) r
                       join catalogue.providers p on p.id = r.provider_id),
    -- the education country's matrix rows that name this qualification (a national route printed under the country)
    'country_matrix_rows', case when v_cc is null then '[]'::jsonb else (select coalesce(jsonb_agg(jsonb_build_object('provider_id', m.provider_id, 'provider', coalesce(p.display_name, p.canonical_name),
                       'status', m.status, 'level', m.level_label, 'qualification', m.qualification_name, 'min_grade', m.min_grade, 'min_value', m.min_value, 'scale', m.grade_scale, 'quote', m.quote)), '[]'::jsonb)
                       from (select * from catalogue.provider_entry_matrix m0 where m0.country_code = v_cc and m0.status in ('active', 'proposed')
                               and exists (select 1 from unnest(array_append(v_q.aliases, lower(v_q.name))) a where length(a) >= 3 and lower(m0.qualification_name) like '%' || a || '%') limit v_lim) m
                       join catalogue.providers p on p.id = m.provider_id) end);
end $$;


ALTER FUNCTION "public"."admin_aer_qualification_lookup"("p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_aer_qualification_lookup"("p_args" "jsonb") IS 'CF-247 F-AER.03: Catalogue › Entry requirements, by qualification: with no qualification, the qualification list; with a code, name or alias (and an optional education country), each provider''s active and waiting qualification-first requirements (global ones apply whatever the country) and that country''s matrix rows naming the qualification. Rank 4 and above; read only; not part of the consumer API.';



CREATE OR REPLACE FUNCTION "public"."admin_aer_read_now"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := coalesce(security.current_role_rank(), 0); v_pid uuid := nullif(p_args->>'provider_id', '')::uuid; v_cid uuid := nullif(p_args->>'course_id', '')::uuid; v_action text := coalesce(nullif(p_args->>'action', ''), 'status'); v_st jsonb;
begin
  if auth.uid() is null or v_rank < 1 then raise exception 'assigned StudySearch role required' using errcode = '42501'; end if;
  if v_pid is null and v_cid is null then raise exception 'provider_id or course_id required' using errcode = '22023'; end if;
  if v_action not in ('status', 'run') then raise exception 'unknown action %', v_action using errcode = '22023'; end if;
  if v_action = 'run' and v_rank < 6 then  -- fixed: the rank of the existing per-course read and per-source read again (Platform Admin)
    return (security.aer_read_now_out_v1('permission_denied', 'rank', 'Reading entry requirements on demand needs the Platform Admin role. Nothing was asked.', 'A Platform Admin can do this, or it waits for the scheduled reader.') - 'actions') || jsonb_build_object('known', true, 'can_run', false);
  end if;
  if v_action = 'run' then
    return security.aer_read_now_v1(v_pid, v_cid, p_args->>'note', auth.uid()) || jsonb_build_object('can_run', true);
  end if;
  v_st := security.aer_read_now_status_v1(v_pid, v_cid);
  return v_st || jsonb_build_object('can_run', v_rank >= 6);  -- fixed: same rank as run
end $$;


ALTER FUNCTION "public"."admin_aer_read_now"("p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_aer_read_now"("p_args" "jsonb") IS 'CF-247 AER read now (10 Nov 2026): Read / refresh entry requirements now for one provider or course. action status (any assigned role) returns the stage timeline and the outcome a click would have; action run (Platform Admin) starts the governed work and returns the outcome. Outcomes: queued, in_progress, human_review_required, already_up_to_date, no_eligible_work, source_unavailable, switch_off, budget_reached, permission_denied. Starts no scraper and approves nothing.';



CREATE OR REPLACE FUNCTION "public"."admin_aer_schedule"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := coalesce(security.current_role_rank(), 0); v_next jsonb; v_rows int := security.pipeline_num_v1('aer.schedule_preview_rows', 30)::int;
        v_cost numeric := security.course_entry_cost_v1(); v_cap int := security.pipeline_num_v1('aer.schedule_daily_max', 200)::int;
begin
  if (auth.uid() is not null or coalesce(auth.role(), '') <> '') and (auth.uid() is null or v_rank < 4) then
    raise exception 'Pipeline Operator or above required' using errcode = '42501'; end if;
  v_next := security.aer_schedule_tick_v1(true);
  return jsonb_build_object(
    'job', (select jsonb_build_object('jobname', j.jobname, 'schedule', j.schedule, 'active', j.active, 'db_role', j.username) from cron.job j where j.jobname = 'aer-scheduled-read'),
    'runs_as', jsonb_build_object('role', v_next->'runs_as'->>'role', 'rank', v_next->'runs_as'->'rank', 'source', v_next->'runs_as'->>'source'),
    'next_run', v_next - 'checked' - 'new' - 'held' - 'matrix' - 'skipped' - 'runs_as'
                || jsonb_build_object('by_provider', (select coalesce(jsonb_agg(z order by z.n desc, z.provider), '[]'::jsonb) from (
                     select x->>'country' country, x->>'provider' provider, count(*) n from jsonb_array_elements(v_next->'new') x group by 1, 2 order by 3 desc, 2 limit v_rows) z),
                   'by_country', (select coalesce(jsonb_object_agg(k, n), '{}'::jsonb) from (select x->>'country' k, count(*) n from jsonb_array_elements(v_next->'new' || v_next->'held') x group by 1) z)),
    'countries', (with n as (select e.country, count(*) nc, count(distinct e.provider_id) np from security.aer_schedule_courses_v1(null, true) e group by 1)
                  select coalesce(jsonb_agg(security.aer_schedule_country_v1(cc) || jsonb_build_object('eligible_courses', coalesce(n.nc, 0),
                                                                                                      'eligible_providers', coalesce(n.np, 0)) order by cc), '[]'::jsonb)
                    from unnest(security.catalogue_country_codes_v1()) cc left join n on n.country = cc),
    'daily', jsonb_build_object('cap', v_cap, 'ai_usd_at_most', round(v_cap * v_cost, 2), 'cost_per_course_usd', round(v_cost, 5),
                                'course_reads_firecrawl', 0, 'used_24h', v_next->'used_24h'),
    'last_runs', (select coalesce(jsonb_agg(jsonb_build_object('ran_at', x.ran_at, 'course_reads', x.course_reads, 'corrections', x.corrections, 'matrix_pages', x.matrix_pages,
                                                               'back_pressure', x.back_pressure, 'refusal', x.refusal, 'estimate_usd', x.estimate_usd) order by x.ran_at desc), '[]'::jsonb)
                    from (select * from pipeline.aer_schedule_runs order by ran_at desc limit 5) x));  -- fixed: the last five runs are shown
end $$;


ALTER FUNCTION "public"."admin_aer_schedule"("p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_aer_schedule"("p_args" "jsonb") IS 'CF-247 scheduled AER reading: Catalogue › Entry requirements › Course-level reading: the job state, what the next run of aer-scheduled-read would ask (by country and provider, held reads, entry pages, estimated US$ and Firecrawl credits), the countries (on, or off with the reason, and eligible courses), the daily figures and the last five runs. Rank 4 and above. Read only; never part of the consumer API.';



CREATE OR REPLACE FUNCTION "public"."admin_aer_source"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := coalesce(security.current_role_rank(), 0); v_act text := coalesce(nullif(p_args->>'action', ''), 'check');
        v_pid uuid := nullif(p_args->>'provider_id', '')::uuid; v_url text := trim(coalesce(p_args->>'url', '')); v_how text := coalesce(nullif(p_args->>'how', ''), 'url');
        v_cls text[] := array(select jsonb_array_elements_text(case when jsonb_typeof(p_args->'classes') = 'array' then p_args->'classes' else '[]'::jsonb end));
        v_reason text := trim(coalesce(p_args->>'reason', '')); v_sha text := lower(nullif(p_args->>'sha256', '')); v_bytes bigint := nullif(p_args->>'bytes', '')::bigint;
        v_chk jsonb; v_sid uuid; v_att bigint; v_reused text; v_country text; v_outcome text; s record; v_ids uuid[];
begin
  if auth.uid() is null or v_rank < 1 then raise exception 'assigned StudySearch role required' using errcode = '42501'; end if;
  if v_act = 'meta' then
    v_ids := array(select x::uuid from jsonb_array_elements_text(case when jsonb_typeof(p_args->'source_ids') = 'array' then p_args->'source_ids' else '[]'::jsonb end) x limit 200);  -- fixed: one screen page
    return coalesce((select jsonb_object_agg(m.id, jsonb_build_object(
      'classes', (select a.classes from pipeline.aer_source_attachments a where a.source_id = m.id order by a.at desc limit 1),
      'attached', (select jsonb_build_object('how', a.how, 'at', a.at, 'complete', a.how = 'url' or a.completed_at is not null, 'reused', a.reused)
                     from pipeline.aer_source_attachments a where a.source_id = m.id order by a.at desc limit 1),
      'found_via', m.found_via,
      'version', (select count(distinct r.content_hash) from pipeline.entry_matrix_runs r where r.source_id = m.id),
      'last_verified', m.read_at,
      'next_retry', case when m.status = 'found' then 'Next entry-matrix-read run (every 5 minutes)'
                         when m.status = 'reading' then 'Being fetched now'
                         when m.status = 'failed' then 'No tries left (entry.matrix_attempts): attach it again, or upload the PDF'
                         when m.status = 'robots_disallowed' then 'The site does not allow fetching: upload the PDF'
                         when m.status = 'pdf_step_b' then 'Waits while PDF reading is off (entry.pdf_enabled)'
                         when m.status = 'inactive' then 'Withdrawn: attach it again to ask the fetch again' end))
      from pipeline.entry_matrix_sources m where m.id = any(v_ids)), '{}'::jsonb);
  end if;
  if v_act = 'check' then
    if v_rank < 4 then raise exception 'Pipeline Operator or above required' using errcode = '42501'; end if;  -- fixed: the rank of the AER discovery read
    return security.aer_source_check_v1(v_pid, v_url, v_cls, v_how, v_sha, v_bytes) || jsonb_build_object('can_attach', v_rank >= 6);
  end if;
  if v_act not in ('attach', 'upload_begin') then raise exception 'unknown action %', v_act using errcode = '22023'; end if;
  if v_rank < 6 then raise exception 'Platform Admin required to attach a source' using errcode = '42501'; end if;  -- fixed: the rank of Read again and of the source seed
  if length(v_reason) < 5 then raise exception 'reason required' using errcode = '22023'; end if;
  if (v_act = 'attach') <> (v_how = 'url') then raise exception 'attach takes an address; upload_begin takes a PDF' using errcode = '22023'; end if;
  v_chk := security.aer_source_check_v1(v_pid, v_url, v_cls, v_how, v_sha, v_bytes);
  if not coalesce((v_chk->>'ok')::boolean, false) then return v_chk || jsonb_build_object('attached', false); end if;
  v_sid := nullif(v_chk->>'source_id', '')::uuid;
  if v_sid is null then
    insert into pipeline.entry_matrix_sources(provider_id, url, title, rank, found_via, status)
    values (v_pid, v_url, left(nullif(trim(p_args->>'title'), ''), 200), 1, 'manual', case when v_how = 'pdf_upload' then 'inactive' else 'found' end)
    returning id into v_sid;
    v_reused := null; v_outcome := case when v_how = 'pdf_upload' then 'Source added; the file is stored next.' else 'Source added: the next entry-matrix-read run fetches and reads it; its rows go to Layer 4.' end;
  else
    select * into s from pipeline.entry_matrix_sources x where x.id = v_sid for update;
    v_reused := v_chk->>'reuse';
    if v_how = 'url' and s.status in ('failed', 'inactive') then
      update pipeline.entry_matrix_sources set status = 'found', attempts = 0, error = null, updated_at = now() where id = v_sid;
      v_outcome := 'Existing source asked again: the next entry-matrix-read run fetches and reads it.';
    else
      v_outcome := v_chk->>'next_action';
    end if;
  end if;
  insert into pipeline.aer_source_attachments(source_id, provider_id, how, classes, reason, ownership, reused, content_hash, attached_by, completed_at)
  values (v_sid, v_pid, v_how, v_cls, v_reason, jsonb_build_object('rule', v_chk->>'ownership', 'host', v_chk->>'host', 'official_host', v_chk->>'official_host'),
          v_reused, case when v_how = 'pdf_upload' then v_sha end, auth.uid(), case when v_how = 'url' or v_reused = 'stored_copy' then now() end)
  returning id into v_att;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('entry_matrix', 'source_' || v_act, 'pipeline.entry_matrix_sources',
          jsonb_build_object('source_id', v_sid, 'attachment_id', v_att, 'provider_id', v_pid, 'url', v_url, 'how', v_how, 'classes', to_jsonb(v_cls), 'reused', v_reused, 'reason', v_reason), auth.uid());
  if v_act = 'upload_begin' and coalesce(v_reused, '') <> 'stored_copy' then
    select k.iso_alpha2 into v_country from catalogue.providers p join ref.countries k on k.id = p.country_id where p.id = v_pid;
    return v_chk || jsonb_build_object('attached', true, 'source_id', v_sid, 'attachment_id', v_att, 'upload', true,
      'storage_path', format('layer2/%s/entry-matrix/%s/%s/%s.pdf.gz', coalesce(v_country, 'XX'), v_pid, v_sid, v_sha), 'outcome', v_outcome);
  end if;
  return v_chk || jsonb_build_object('attached', true, 'source_id', v_sid, 'attachment_id', v_att, 'upload', false, 'outcome', v_outcome);
end $$;


ALTER FUNCTION "public"."admin_aer_source"("p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_aer_source"("p_args" "jsonb") IS 'CF-247 F-AER.04 D3: Catalogue › Entry requirements › Sources: check (rank 4), attach an address or begin a PDF upload (Platform Admin, reason), and meta for listed sources (classes, version, last verified, next retry). Never part of the consumer API.';



CREATE OR REPLACE FUNCTION "public"."admin_ai_config"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_reason text := trim(coalesce(p_args->>'reason', '')); m record;
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'a reason is required'; end if;
  if p_action = 'central_model' then
    select * into m from pipeline.scholarship_ai_models x where x.code = p_args->>'code' and x.status <> 'retired' and x.model_identifier <> 'person';
    if m.code is null then raise exception 'choose one of the scholarship AI models that is not retired'; end if;
    update pipeline.central_ai_settings set model_code = m.code, model_identifier = m.model_identifier, reason = v_reason, changed_at = now(), changed_by = auth.uid() where id = 1;
  elsif p_action = 'central_on' then
    update pipeline.central_ai_settings set enabled = coalesce((p_args->>'on')::boolean, false), reason = v_reason, changed_at = now(), changed_by = auth.uid() where id = 1;
  else
    raise exception 'unknown action %', p_action;
  end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('ai_config', p_action, 'central_ai', p_args - 'reason' || jsonb_build_object('reason', v_reason, 'change', 'CF-247 v2.15.264'), auth.uid());
  return public.admin_ai_config_read();
end $$;


ALTER FUNCTION "public"."admin_ai_config"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_ai_config_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 3 then raise exception 'assigned StudySearch role required' using errcode = '42501'; end if;
  return jsonb_build_object(
    'can_manage', v_rank >= 6, 'generated_at', now(),
    'openrouter', (select jsonb_build_object(
        'mode', coalesce((select t.enforcement from pipeline.platform_toolsets t where t.key = 'openrouter'), 'stop'),
        'mode_reason', (select t.reason from pipeline.platform_toolsets t where t.key = 'openrouter'),
        'credit_floor_usd', (security.toolset_setting('openrouter', 'credit_floor_usd'))::text::numeric,
        'low_balance_warn_usd', (security.toolset_setting('openrouter', 'low_balance_warn_usd'))::text::numeric,
        'balance', (select jsonb_build_object('remaining_usd', round(o.remaining_usd, 2), 'total_credits', coalesce(o.payload->>'total_credits', o.payload#>>'{data,total_credits}')::numeric, 'observed_at', o.observed_at)
                      from pipeline.layer3_openrouter_observations o where o.kind = 'credits' order by o.observed_at desc limit 1),
        'key', jsonb_build_object('secret', 'OPENROUTER_API_KEY', 'shared_by_profiles', (select count(*) from pipeline.layer3_model_profiles p where p.secret_env_key = 'OPENROUTER_API_KEY'),
                                  'profile_id', (select p.id from pipeline.layer3_model_profiles p where p.code = (security.toolset_setting('firecrawl', 'builder_model_profile') #>> '{}')),
                                  'profile_code', security.toolset_setting('firecrawl', 'builder_model_profile') #>> '{}'))),
    'uses', (select coalesce(jsonb_agg(jsonb_build_object('use', g.use, 'label', g.label, 'spent_today', g.spent, 'guard', g.guard, 'calls', g.calls,
                 'allowed', security.ai_use_allowed_v1(g.use),
                 'models', case g.use
                   when 'scholarship_ai' then (select coalesce(jsonb_agg(jsonb_build_object('code', m.code, 'label', m.label, 'model', m.model_identifier, 'status', m.status) order by m.status <> 'active', m.code), '[]'::jsonb)
                                                 from pipeline.scholarship_ai_models m where m.status = 'active')
                   when 'adapter_builder' then jsonb_build_array(jsonb_build_object('model', security.toolset_setting('firecrawl', 'builder_model') #>> '{}', 'profile', security.toolset_setting('firecrawl', 'builder_model_profile') #>> '{}', 'set_on', 'firecrawl.builder_model'))
                   when 'central_ai' then (select jsonb_build_array(jsonb_build_object('code', c.model_code, 'model', c.model_identifier, 'enabled', c.enabled, 'calls_at_once', c.calls_at_once, 'reason', c.reason, 'changed_at', c.changed_at)) from pipeline.central_ai_settings c where c.id = 1)
                   when 'course_match' then jsonb_build_array(jsonb_build_object('model', 'qwen/qwen3-30b-a3b-instruct-2507', 'fixed', 'worker coverage-sweep (AI_MATCH_MODEL)'))
                 end)), '[]'::jsonb)
               from security.ai_spend_today_v1() g),
    'central_choices', (select coalesce(jsonb_agg(jsonb_build_object('code', m.code, 'label', m.label, 'model', m.model_identifier, 'status', m.status) order by m.code), '[]'::jsonb)
                          from pipeline.scholarship_ai_models m where m.status <> 'retired' and m.model_identifier <> 'person'),
    'profiles', (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'code', p.code, 'model', p.model_identifier, 'enabled', p.enabled, 'paused', p.paused,
                    'prompt_version', p.prompt_profile_version, 'prompt_chars', length(coalesce(p.prompt_system, '')), 'prompt_hash', left(md5(coalesce(p.prompt_system, '')), 12),
                    'tasks', p.allowed_task_classes, 'requests_per_day', p.requests_per_day, 'cost_ceiling_usd', p.cost_ceiling_usd, 'holdout', p.holdout_qualification,
                    'used_now', p.code = (security.toolset_setting('firecrawl', 'builder_model_profile') #>> '{}'))
                    order by p.code = (security.toolset_setting('firecrawl', 'builder_model_profile') #>> '{}') desc, p.enabled desc, p.code), '[]'::jsonb)
                   from pipeline.layer3_model_profiles p where p.retired_at is null),
    'events', (select coalesce(jsonb_agg(jsonb_build_object('at', e.created_at, 'area', e.area, 'action', e.action, 'target', e.target, 'reason', e.detail->>'reason') order by e.created_at desc), '[]'::jsonb)
                 from (select * from pipeline.admin_control_events e where e.area in ('ai_config', 'scholarship_ai', 'openrouter') or (e.area = 'toolsets' and e.target like 'openrouter%')
                        order by e.created_at desc limit 20) e));
end $$;


