CREATE OR REPLACE FUNCTION "public"."admin_enrich_fields"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_cc text[]; v_pids uuid[]; v_fields text[]; v_job uuid; v_reason text; v_n int; v_title text; v_src pipeline.admin_jobs%rowtype;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  v_cc := array(select upper(x) from jsonb_array_elements_text(coalesce(p_args->'countries', '[]'::jsonb)) x);
  v_pids := array(select x::uuid from jsonb_array_elements_text(coalesce(p_args->'provider_ids', '[]'::jsonb)) x);
  v_fields := array(select x from jsonb_array_elements_text(coalesce(p_args->'fields', '[]'::jsonb)) x where x in (select f.field from security.enrich_fields_v1() f));
  -- CF-247 F-CDESC.06 (Platform Admin 10 Nov 2026): Fill description / Recheck description for chosen courses or one university, and the read-back of what they delivered, run through this same task engine
  if p_action in ('verify', 'description_tasks') or (p_action in ('preview', 'start') and (p_args ? 'course_ids' or p_args ? 'mode')) then
    return security.cdesc_on_demand_v1(p_action, p_args, v_rank, auth.uid());
  end if;
  if p_action = 'fields' then
    return jsonb_build_object('fields', (select jsonb_agg(jsonb_build_object('field', f.field, 'label', f.label, 'level', f.level, 'allowed', f.sources) order by f.sort) from security.enrich_fields_v1() f),
      'rules', (select coalesce(jsonb_agg(jsonb_build_object('country', r.country_code, 'field', r.field, 'sources', r.sources, 'reason', r.reason, 'updated_at', r.updated_at) order by r.country_code, r.field), '[]'::jsonb) from pipeline.field_source_rules r),
      'countries', (select jsonb_agg(c order by c) from unnest(security.catalogue_country_codes_v1()) c),
      'can_start', v_rank >= 4, 'can_manage', v_rank >= 6);
  elsif p_action = 'preview' then
    if coalesce(array_length(v_fields, 1), 0) = 0 then raise exception 'choose at least one field'; end if;
    return (with scope as (
              select c.id, c.provider_id, c.study_level_id, c.primary_field_id, c.duration_value, c.delivery_mode, c.open_to_international, k.iso_alpha2::text cc
                from catalogue.courses c join catalogue.providers p on p.id = c.provider_id join ref.countries k on k.id = p.country_id
               where c.lifecycle_status = 'active' and (cardinality(v_cc) = 0 or k.iso_alpha2::text = any (v_cc)) and (cardinality(v_pids) = 0 or c.provider_id = any (v_pids))),
            f as (select x field from unnest(v_fields) x)
            select jsonb_build_object('courses', (select count(*) from scope), 'universities', (select count(distinct provider_id) from scope),
              'fields', jsonb_agg(jsonb_build_object('field', f.field,
                'missing', case f.field when 'campus' then (select count(*) from scope s where not exists (select 1 from catalogue.course_campuses x where x.course_id = s.id))
                                        when 'duration' then (select count(*) from scope s where s.duration_value is null)
                                        when 'level' then (select count(*) from scope s where s.study_level_id is null)
                                        when 'delivery' then (select count(*) from scope s where nullif(btrim(s.delivery_mode), '') is null)
                                        when 'field_of_study' then (select count(*) from scope s where s.primary_field_id is null)
                                        when 'international' then (select count(*) from scope s where s.open_to_international is null)
                                        when 'english' then (select count(*) from scope s where not exists (select 1 from catalogue.course_english_requirements x where x.course_id = s.id and coalesce(x.status, 'active') = 'active'))
                                        when 'intakes' then (select count(*) from scope s where not exists (select 1 from catalogue.course_intakes x where x.course_id = s.id and x.status = 'active'))
                                        when 'campus_region' then (select count(*) from catalogue.campuses k where k.provider_id in (select provider_id from scope) and k.status = 'active' and k.subdivision_id is null and nullif(btrim(k.city), '') is not null)
                                        when 'provider_address' then (select count(*) from catalogue.providers p where p.id in (select provider_id from scope) and nullif(btrim(p.address_line1), '') is null)
                                        -- CF-247 Workstream C (3 Nov 2026): course description; application deadline (active intakes, none dated)
                                        when 'description' then (select count(*) from scope s join catalogue.courses c on c.id = s.id where nullif(btrim(c.description), '') is null)
                                        when 'deadline' then (select count(*) from scope s where security.enrich_deadline_missing_v1(s.id)) end,
                'stored_page', case when f.field = 'provider_address' then (select count(distinct s2.provider_id) from pipeline.evidence_artifacts e join pipeline.sources s2 on s2.id = e.source_id
                                                                             where s2.provider_id in (select provider_id from scope) and e.evidence_type in ('provider_contact_html_snapshot', 'enrich_home_page'))
                                    else (select count(*) from scope s join pipeline.coverage_course_pages g on g.course_id = s.id where g.evidence_id is not null) end,
                'adapter_value', case f.field when 'campus' then (select count(*) from scope s where exists (select 1 from pipeline.uni_adapter_results r where r.course_id = s.id and coalesce(r.fields->'extra'->>'campus', r.fields->'extra'->>'location') is not null))
                                              when 'duration' then (select count(*) from scope s where s.duration_value is null and exists (select 1 from pipeline.uni_adapter_results r where r.course_id = s.id and r.fields->'extra'->>'duration' is not null))
                                              when 'delivery' then (select count(*) from scope s where nullif(btrim(s.delivery_mode), '') is null and exists (select 1 from pipeline.uni_adapter_results r where r.course_id = s.id and r.fields->'extra'->>'mode' is not null))
                                              when 'level' then (select count(*) from scope s where s.study_level_id is null and exists (select 1 from pipeline.uni_adapter_results r where r.course_id = s.id and r.fields->'extra'->>'study_level' is not null))
                                              else null end) order by f.field))
              from f)
           -- 3 Nov 2026 (Platform Admin 09:32 §3): what Start would queue and its estimated spend
           || security.enrich_fields_estimate_v1(v_cc, v_pids, v_fields, coalesce((p_args->>'ai')::boolean, true), coalesce((p_args->>'scraper')::boolean, false));
  elsif p_action = 'start' then
    if v_rank < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
    v_reason := btrim(coalesce(p_args->>'reason', ''));
    if length(v_reason) < 4 then raise exception 'give a reason (it is kept with the task)'; end if;
    if coalesce(array_length(v_fields, 1), 0) = 0 then raise exception 'choose at least one field'; end if;
    if cardinality(v_cc) = 0 and cardinality(v_pids) = 0 then raise exception 'choose countries or universities'; end if;
    v_title := 'Enrich ' || (select string_agg(lower(f.label), ', ' order by f.sort) from security.enrich_fields_v1() f where f.field = any (v_fields)) || ' · ' || case when cardinality(v_pids) > 0 then cardinality(v_pids) || ' universit' || case when cardinality(v_pids) = 1 then 'y' else 'ies' end else array_to_string(v_cc, ', ') end;
    insert into pipeline.admin_jobs(kind, lane, state, title, args, progress, requested_by, reason, scope)
    values ('enrich_fields', 'enrich', 'queued', left(v_title, 200),
            jsonb_build_object('countries', to_jsonb(v_cc), 'provider_ids', to_jsonb(v_pids), 'fields', to_jsonb(v_fields),
                               'ai', coalesce((p_args->>'ai')::boolean, true), 'scraper', coalesce((p_args->>'scraper')::boolean, false)),
            jsonb_build_object('done', 0, 'total', 0), auth.uid(), v_reason, coalesce(nullif(array_to_string(v_cc, ', '), ''), cardinality(v_pids) || ' universities'))
    returning id into v_job;
    -- one item per course and missing field; one per university for its address and its campus list
    insert into pipeline.field_enrich_items(job_id, provider_id, course_id, field)
    select v_job, c.provider_id, c.id, f.x
      from catalogue.courses c join catalogue.providers p on p.id = c.provider_id join ref.countries k on k.id = p.country_id
      cross join unnest(v_fields) f(x)
     where c.lifecycle_status = 'active' and f.x <> 'provider_address'
       -- 3 Nov 2026 (Platform Admin 09:32 §6): the standing queue's rules; unpublished providers wait, and an item another open task holds is left to it
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = c.provider_id)
       and not security.enrich_item_in_flight_v1(c.provider_id, c.id, f.x)
       and (cardinality(v_cc) = 0 or k.iso_alpha2::text = any (v_cc)) and (cardinality(v_pids) = 0 or c.provider_id = any (v_pids))
       and case f.x when 'campus' then not exists (select 1 from catalogue.course_campuses x where x.course_id = c.id)
                    when 'duration' then c.duration_value is null when 'level' then c.study_level_id is null
                    when 'delivery' then nullif(btrim(c.delivery_mode), '') is null when 'field_of_study' then c.primary_field_id is null
                    when 'international' then c.open_to_international is null
                    when 'english' then not exists (select 1 from catalogue.course_english_requirements x where x.course_id = c.id and coalesce(x.status, 'active') = 'active')
                    when 'intakes' then not exists (select 1 from catalogue.course_intakes x where x.course_id = c.id and x.status = 'active')
                    when 'description' then nullif(btrim(c.description), '') is null when 'deadline' then security.enrich_deadline_missing_v1(c.id) else false end
    on conflict do nothing;
    -- 23 Oct 2026: campus regions, one item per university with campus cities that have no region
    perform security.campus_regions_apply_v1();
    insert into pipeline.field_enrich_items(job_id, provider_id, course_id, field)
    select v_job, p.id, null::uuid, 'campus_region'
      from catalogue.providers p join ref.countries k on k.id = p.country_id
     where 'campus_region' = any (v_fields)
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id) and not security.enrich_item_in_flight_v1(p.id, null, 'campus_region')
       and (cardinality(v_cc) = 0 or k.iso_alpha2::text = any (v_cc)) and (cardinality(v_pids) = 0 or p.id = any (v_pids))
       and exists (select 1 from catalogue.campuses k2 where k2.provider_id = p.id and k2.status = 'active' and k2.subdivision_id is null and nullif(btrim(k2.city), '') is not null)
    on conflict do nothing;
    insert into pipeline.field_enrich_items(job_id, provider_id, course_id, field, state)
    select distinct v_job, e.provider_id, null::uuid, 'campus_list', 'waiting' from pipeline.field_enrich_items e where e.job_id = v_job and e.field = 'campus'
    on conflict do nothing;
    if 'provider_address' = any (v_fields) then
      insert into pipeline.field_enrich_items(job_id, provider_id, course_id, field)
      select v_job, p.id, null::uuid, 'provider_address'
        from catalogue.providers p join ref.countries k on k.id = p.country_id
       where nullif(btrim(p.address_line1), '') is null and coalesce(p.lifecycle_status, 'active') = 'active'
         and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id) and not security.enrich_item_in_flight_v1(p.id, null, 'provider_address')
         and exists (select 1 from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active')
         and (cardinality(v_cc) = 0 or k.iso_alpha2::text = any (v_cc)) and (cardinality(v_pids) = 0 or p.id = any (v_pids))
      on conflict do nothing;
    end if;
    select count(*) into v_n from pipeline.field_enrich_items where job_id = v_job;
    update pipeline.admin_jobs set progress = jsonb_build_object('done', 0, 'total', v_n) where id = v_job;
    insert into pipeline.admin_job_events(job_id, note) values (v_job, v_n || ' item(s) to settle');
    return jsonb_build_object('job_id', v_job, 'items', v_n);
  elsif p_action = 'retry' then
    -- 3 Nov 2026 (Platform Admin 09:32 §3 "Retry failed items"): the failed items of a finished task go into a new task of the same engine,
    -- with a reason; items another open task holds and unpublished providers are left out, as at Start
    if v_rank < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
    v_reason := btrim(coalesce(p_args->>'reason', ''));
    if length(v_reason) < 4 then raise exception 'give a reason (it is kept with the task)'; end if;
    select * into v_src from pipeline.admin_jobs j where j.id = nullif(p_args->>'job_id', '')::uuid and j.kind = 'enrich_fields';
    if v_src.id is null then raise exception 'unknown task'; end if;
    if v_src.state not in ('done', 'failed', 'cancelled') then raise exception 'the task is still open; retry its failed items when it has finished'; end if;
    select count(*) into v_n from (select 1 from pipeline.field_enrich_items e
      where e.job_id = v_src.id and e.state = 'failed' and e.field <> 'campus_list'
        and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = e.provider_id)
        and not security.enrich_item_in_flight_v1(e.provider_id, e.course_id, e.field)
      limit security.pipeline_num_v1('enrich.retry_items_max', 5000)::int) z;
    if v_n = 0 then raise exception 'no failed item to retry (or each is already in another open task)'; end if;
    insert into pipeline.admin_jobs(kind, lane, state, title, args, progress, requested_by, reason, scope)
    values ('enrich_fields', 'enrich', 'queued', left('Retry failed · ' || v_src.title, 200), (v_src.args - 'standing') || jsonb_build_object('retry_of', v_src.id),
            jsonb_build_object('done', 0, 'total', 0), auth.uid(), v_reason, v_src.scope)
    returning id into v_job;
    insert into pipeline.field_enrich_items(job_id, provider_id, course_id, field)
    select v_job, e.provider_id, e.course_id, e.field from pipeline.field_enrich_items e
     where e.job_id = v_src.id and e.state = 'failed' and e.field <> 'campus_list'
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = e.provider_id)
       and not security.enrich_item_in_flight_v1(e.provider_id, e.course_id, e.field)
     order by e.id limit security.pipeline_num_v1('enrich.retry_items_max', 5000)::int
    on conflict do nothing;
    insert into pipeline.field_enrich_items(job_id, provider_id, course_id, field, state)
    select distinct v_job, e.provider_id, null::uuid, 'campus_list', 'waiting' from pipeline.field_enrich_items e where e.job_id = v_job and e.field = 'campus'
    on conflict do nothing;
    select count(*) into v_n from pipeline.field_enrich_items where job_id = v_job;
    update pipeline.admin_jobs set progress = jsonb_build_object('done', 0, 'total', v_n) where id = v_job;
    insert into pipeline.admin_job_events(job_id, note, detail) values (v_job, v_n || ' failed item(s) to settle again', jsonb_build_object('retry_of', v_src.id, 'reason', v_reason));
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('enrich_fields', 'retry_failed', v_src.id::text, jsonb_build_object('job_id', v_job, 'items', v_n, 'reason', v_reason), auth.uid());
    return jsonb_build_object('job_id', v_job, 'items', v_n, 'retry_of', v_src.id);
  elsif p_action = 'export' then
    -- 3 Nov 2026 (Platform Admin 09:32 §3 "Export execution and evidence results"): every item of a task with its source, quote and evidence,
    -- in pages (pass the last id as after)
    return (select jsonb_build_object('rows', coalesce(jsonb_agg(z.x order by z.id), '[]'::jsonb), 'page_rows', security.pipeline_num_v1('enrich.export_page_rows', 2000)) from (
      select e.id, jsonb_build_object('id', e.id, 'university', coalesce(p.display_name, p.canonical_name), 'course', c.canonical_title, 'course_code', c.course_code,
               'course_id', e.course_id, 'provider_id', e.provider_id, 'field', e.field, 'state', e.state, 'source', e.source, 'value', e.value, 'quote', e.quote,
               'reason', e.reason, 'evidence_id', e.evidence_id, 'attempts', e.attempts, 'cost_usd', e.cost_usd, 'updated_at', e.updated_at) x
        from pipeline.field_enrich_items e join catalogue.providers p on p.id = e.provider_id left join catalogue.courses c on c.id = e.course_id
       where e.job_id = nullif(p_args->>'job_id', '')::uuid and e.id > coalesce(nullif(p_args->>'after', '')::bigint, 0)
       order by e.id limit security.pipeline_num_v1('enrich.export_page_rows', 2000)::int) z);
  elsif p_action = 'rule_set' then
    if v_rank < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
    v_reason := btrim(coalesce(p_args->>'reason', ''));
    if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
    if not exists (select 1 from security.enrich_fields_v1() f where f.field = p_args->>'field') then raise exception 'unknown field'; end if;
    if exists (select 1 from jsonb_array_elements_text(coalesce(p_args->'sources', '[]'::jsonb)) s
                where s not in (select unnest(f.sources) from security.enrich_fields_v1() f where f.field = p_args->>'field')) then
      raise exception 'a source that cannot fill this field';
    end if;
    insert into pipeline.field_source_rules(country_code, field, sources, reason, updated_by, updated_at)
    values (upper(coalesce(nullif(p_args->>'country', ''), 'ALL')), p_args->>'field', array(select jsonb_array_elements_text(p_args->'sources')), v_reason, auth.uid(), now())
    on conflict (country_code, field) do update set sources = excluded.sources, reason = excluded.reason, updated_by = excluded.updated_by, updated_at = now();
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('field_sources', 'set', upper(coalesce(nullif(p_args->>'country', ''), 'ALL')) || '.' || (p_args->>'field'), jsonb_build_object('sources', p_args->'sources', 'reason', v_reason), auth.uid());
    return public.admin_enrich_fields('fields', '{}'::jsonb);
  elsif p_action = 'stats' then
    -- v2.15.275: coverage over time and the job's telemetry, with the limits in force and where they are changed
    return jsonb_build_object(
      'coverage', (with s as (select * from pipeline.enrich_coverage_snapshots),
                        last as (select max(at) t from s), first as (select min(at) t from s),
                        dayago as (select max(at) t from s where at <= now() - make_interval(hours => 24))
                   select coalesce(jsonb_agg(jsonb_build_object('country', n.country_code, 'field', n.field, 'courses', n.courses, 'filled', n.filled,
                            'first', (select x.filled from s x, first where x.at = first.t and x.country_code = n.country_code and x.field = n.field),
                            'day_ago', (select x.filled from s x, dayago where x.at = dayago.t and x.country_code = n.country_code and x.field = n.field))
                            order by n.country_code, n.field), '[]'::jsonb)
                     from s n, last where n.at = last.t and (cardinality(v_cc) = 0 or n.country_code = any (v_cc))),
      'snapshot_at', (select max(at) from pipeline.enrich_coverage_snapshots),
      'first_snapshot_at', (select min(at) from pipeline.enrich_coverage_snapshots),
      'last_24h', jsonb_build_object(
        'settled', (select count(*) from pipeline.field_enrich_items where state in ('filled', 'review', 'skipped', 'failed') and updated_at > now() - make_interval(hours => 24)),
        'filled', (select count(*) from pipeline.field_enrich_items where state = 'filled' and updated_at > now() - make_interval(hours => 24)),
        'last_hour', (select count(*) from pipeline.field_enrich_items where state in ('filled', 'review', 'skipped', 'failed') and updated_at > now() - make_interval(hours => 1)),
        'ai_calls', (select count(*) from pipeline.edge_request_log l where l.mode = 'enrich_ai' and l.created_at > now() - make_interval(hours => 24)),
        'ai_failed', (select count(*) from pipeline.edge_request_log l join net._http_response r on r.id = l.request_id where l.mode = 'enrich_ai' and l.created_at > now() - make_interval(hours => 24) and r.status_code <> 200),
        'ai_cost_usd', (select round(coalesce(sum(cost_usd), 0), 3) from pipeline.field_enrich_items where updated_at > now() - make_interval(hours => 24)),
        'scraper_credits', (select coalesce(sum(u.units), 0) from pipeline.coverage_vendor_usage u where u.purpose = 'enrich_address' and u.at > now() - make_interval(hours => 24)),
        'pages_requested', (select count(*) from pipeline.field_enrich_items where reason = 'course page asked to be read' and updated_at > now() - make_interval(hours => 24))),
      'limits', jsonb_build_object(
        'model', (select security.ai_route_v1('course_other_fields')->>'model'),
        'ai_guard_usd', (select (value #>> '{}')::numeric from pipeline.platform_toolset_settings where toolset_key = 'openrouter' and key = 'guard_enrich_fields'),
        'ai_spent_today_usd', (select x.spent from security.ai_spend_today_v1() x where x.use = 'enrich_fields'),
        'openrouter_mode', (select enforcement from pipeline.platform_toolsets where key = 'openrouter'),
        'calls_at_once', security.pipeline_num_v1('enrich.ai_calls_at_once', 2), 'items_per_call', security.pipeline_num_v1('enrich.ai_items_per_call', 30),
        'items_a_minute', security.pipeline_num_v1('batch.enrich_fields', 400), 'campus_min_pages', security.pipeline_num_v1('enrich.campus_min_pages', 2),
        'scraper_share', (select (value #>> '{}')::numeric from pipeline.platform_toolset_settings where toolset_key = 'firecrawl' and key = 'daily_share_other'),
        'reads_share', (select (value #>> '{}')::numeric from pipeline.platform_toolset_settings where toolset_key = 'firecrawl' and key = 'daily_share_reads')));
  elsif p_action = 'jobs' then
    return (select jsonb_build_object('jobs', coalesce(jsonb_agg(jsonb_build_object('id', j.id, 'title', j.title, 'state', j.state, 'progress', j.progress, 'result', j.result, 'reason', j.reason,
                     'args', j.args, 'created_at', j.created_at, 'finished_at', j.finished_at) order by j.created_at desc), '[]'::jsonb))
              from (select * from pipeline.admin_jobs where kind = 'enrich_fields' order by created_at desc limit 20) j);
  elsif p_action = 'items' then
    return (select jsonb_build_object('items', coalesce(jsonb_agg(x order by x->>'id' desc), '[]'::jsonb)) from (
      select jsonb_build_object('id', e.id, 'field', e.field, 'state', e.state, 'source', e.source, 'value', e.value, 'quote', e.quote, 'reason', e.reason,
               'provider', coalesce(p.display_name, p.canonical_name), 'course', c.canonical_title, 'course_id', e.course_id, 'provider_id', e.provider_id) x
        from pipeline.field_enrich_items e join catalogue.providers p on p.id = e.provider_id left join catalogue.courses c on c.id = e.course_id
       where e.job_id = (p_args->>'job_id')::uuid and (nullif(p_args->>'field', '') is null or e.field = p_args->>'field')
         and (nullif(p_args->>'state', '') is null or e.state = p_args->>'state')
       order by e.id desc limit least(greatest(coalesce((p_args->>'limit')::int, 50), 1), 200)) z);
  end if;
  raise exception 'unknown action %', p_action using errcode = '22023';
end $$;


ALTER FUNCTION "public"."admin_enrich_fields"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_enrich_plan"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_pid uuid := nullif(p_args->>'provider', '')::uuid; v_reason text := btrim(coalesce(p_args->>'reason', ''));
        v_plan jsonb; v_steps jsonb; v_est_c numeric; v_est_u numeric; v_left_c numeric; v_left_u numeric; v_id uuid; v_cc text := upper(nullif(btrim(coalesce(p_args->>'country', '')), ''));
        v_open jsonb; v_carry jsonb := '[]'::jsonb;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  v_left_c := greatest(0, security.fc_setting_num_v1('ondemand_credits_per_day', 2000) - security.fc_on_demand_today_v1());
  v_left_u := greatest(0, coalesce((security.toolset_setting('openrouter', 'ondemand_usd_per_day'))::text::numeric, 0)
                          - coalesce((select sum(coalesce((r.actual->>'usd')::numeric, (r.estimate->>'usd')::numeric, 0)) from pipeline.enrich_plan_runs r
                                       where r.mode = 'manual' and r.created_at >= security.fc_day_start_v1()), 0));
  if p_action = 'overview' then
    return jsonb_build_object(
      'auto', (select jsonb_build_object('enabled', c.auto_enabled, 'reason', c.reason, 'at', c.updated_at) from pipeline.enrich_plan_control c where c.id = 1),
      'open', jsonb_build_object('auto', (select count(*) from pipeline.enrich_plan_runs where mode = 'auto' and state in ('queued', 'running')),
                                 'manual', (select count(*) from pipeline.enrich_plan_runs where mode = 'manual' and state in ('queued', 'running'))),
      'on_demand', jsonb_build_object('credits', security.fc_setting_num_v1('ondemand_credits_per_day', 2000), 'credits_used', security.fc_on_demand_today_v1(), 'credits_left', v_left_c,
                                      'usd', (security.toolset_setting('openrouter', 'ondemand_usd_per_day'))::text::numeric, 'usd_left', v_left_u),
      'shares', (select jsonb_object_agg(g, jsonb_build_object('share', security.fc_setting_num_v1('daily_share_' || g, 0), 'left', security.fc_budget_left_v1(pp)))
                   from (values ('course_search', 'course_link_search'), ('reads', 'scrape'), ('central', 'central_map'), ('scholarships', 'sch_scrape'), ('other', 'other')) v(g, pp)),
      'limits', jsonb_build_object('open_max', security.pipeline_num_v1('plans.auto_open_max', 20), 'per_run', security.pipeline_num_v1('plans.auto_per_run', 10),
                                   'redo_days', security.pipeline_num_v1('plans.redo_days', 14), 'replan_per_hour', security.pipeline_num_v1('plans.replan_per_hour', 0),
                                   'replan_min_new_gaps', security.pipeline_num_v1('plans.replan_min_new_gaps', 5), 'replan_min_days', security.pipeline_num_v1('plans.replan_min_days', 2),
                                   'replan_on_evidence', security.pipeline_num_v1('plans.replan_on_evidence', 0), 'replan_on_retry', security.pipeline_num_v1('plans.replan_on_retry', 0),
                                   'retry_after_hours', security.pipeline_num_v1('plans.retry_after_hours', 6), 'step_retry_max', security.pipeline_num_v1('plans.step_retry_max', 3),
                                   'fair_order', security.pipeline_num_v1('plans.fair_order', 0), 'run_now_supersedes_auto', security.pipeline_num_v1('plans.run_now_supersedes_auto', 1),
                                   'wait_hours', security.pipeline_num_v1('plans.step_wait_hours', 48)),
      'needs_person', (select coalesce(jsonb_agg(jsonb_build_object('run', r.id, 'provider_id', r.provider_id, 'name', coalesce(p.display_name, p.canonical_name),
                                  'mode', r.mode, 'note', r.needs_person, 'finished_at', r.finished_at) order by r.finished_at desc), '[]'::jsonb)
                         from pipeline.enrich_plan_runs r join catalogue.providers p on p.id = r.provider_id
                        where r.state = 'done' and r.needs_person is not null
                          and not exists (select 1 from pipeline.enrich_plan_runs r2 where r2.provider_id = r.provider_id and r2.created_at > r.created_at)),
      'unit_costs', security.enrich_unit_costs_v1(), 'can_run', v_rank >= 4, 'can_manage', v_rank >= 6);
  elsif p_action = 'list' then
    return jsonb_build_object('items', (select coalesce(jsonb_agg(z order by z.missing desc, z.best_rank nulls last), '[]'::jsonb) from (
      select x.provider_id, x.name, x.country, x.courses, x.missing, x.best_rank,
             (select jsonb_build_object('id', r.id, 'mode', r.mode, 'state', r.state, 'created_at', r.created_at, 'finished_at', r.finished_at, 'needs_person', r.needs_person,
                       'step', (select e->>'label' from jsonb_array_elements(r.steps) e where e->>'status' in ('pending', 'waiting', 'running') limit 1))
                from pipeline.enrich_plan_runs r where r.provider_id = x.provider_id order by r.created_at desc limit 1) last_run
        from security.enrich_plan_priority_v1() x
       where (v_cc is null or x.country = v_cc) and (coalesce(p_args->>'query', '') = '' or x.name ilike '%' || (p_args->>'query') || '%')
       order by x.missing desc, x.best_rank nulls last
       limit least(greatest(coalesce((p_args->>'limit')::int, 50), 1), 200) offset greatest(coalesce((p_args->>'offset')::int, 0), 0)) z));
  elsif p_action = 'plan' then
    if v_pid is null then raise exception 'choose a university'; end if;
    return security.enrich_plan_v1(v_pid) || jsonb_build_object('on_demand', jsonb_build_object('credits_left', v_left_c, 'usd_left', v_left_u),
      'runs', (select coalesce(jsonb_agg(to_jsonb(r) order by r.created_at desc), '[]'::jsonb) from (select * from pipeline.enrich_plan_runs where provider_id = v_pid order by created_at desc limit 10) r),
      'can_run', v_rank >= 4);
  elsif p_action = 'run' then
    if v_rank < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
    if length(v_reason) < 4 then raise exception 'give a reason (kept with the run)'; end if;
    v_plan := security.enrich_plan_v1(v_pid);
    if v_plan is null then raise exception 'choose a university'; end if;
    -- 3 Nov 2026 (Platform Admin P0 mandate 10:44 §3 Agent A): one plan per university. Run now on a university with an open automatic plan
    -- takes it over (plans.run_now_supersedes_auto): the tasks its running steps started are carried into this run, not started twice
    if v_plan->'open_run' is not null and v_plan->>'open_run' <> 'null' then
      select to_jsonb(r) into v_open from pipeline.enrich_plan_runs r where r.id = (v_plan->'open_run'->>'id')::uuid and r.state in ('queued', 'running') for update;
    end if;
    if v_open is not null and (v_open->>'mode' <> 'auto' or security.pipeline_num_v1('plans.run_now_supersedes_auto', 1) <= 0) then
      raise exception 'a plan is already running for this university%', case when v_open->>'mode' = 'manual'
        then ' (a Run now started ' || to_char((v_open->>'created_at')::timestamptz, 'DD Mon YYYY HH24:MI') || '); wait for it to finish or cancel it first' else '' end;
    end if;
    if v_open is not null then
      v_carry := (select coalesce(jsonb_agg(s || jsonb_build_object('note', 'carried over from the automatic plan this Run now superseded')), '[]'::jsonb)
                    from jsonb_array_elements(v_open->'steps') s where s->>'status' = 'running');
    end if;
    v_steps := (select coalesce(jsonb_agg(x || jsonb_build_object('status', 'pending')), '[]'::jsonb) from jsonb_array_elements(v_plan->'steps') x
                 where x->>'step' in (select jsonb_array_elements_text(coalesce(p_args->'steps', '[]'::jsonb))));
    v_steps := (select coalesce(jsonb_agg(x), '[]'::jsonb) from jsonb_array_elements(v_steps) x
                 where not exists (select 1 from jsonb_array_elements(v_carry) k where k->>'step' = x->>'step'));  -- already running: carried, not started again
    if jsonb_array_length(v_steps) + jsonb_array_length(v_carry) = 0 then raise exception 'choose at least one step'; end if;
    select coalesce(sum((x->>'est_credits')::numeric), 0), coalesce(sum((x->>'est_usd')::numeric), 0) into v_est_c, v_est_u from jsonb_array_elements(v_steps) x;
    -- 12 Nov 2026 (Platform Admin 21:07): on demand is not held by toolset limits; only the account's own credit stops it
    if v_est_c > coalesce(security.fc_vendor_estimate_v1(), v_est_c) then raise exception 'the estimate (% credits) is more than the Firecrawl credit left on the plan (% credits)', round(v_est_c), round(security.fc_vendor_estimate_v1()); end if;
    if v_est_u > coalesce((security.on_demand_credit_left_v1()->>'openrouter_balance_usd')::numeric - (security.on_demand_credit_left_v1()->>'openrouter_floor_usd')::numeric, v_est_u) then
      raise exception 'the estimate (US$%) would take the OpenRouter balance below its floor (US$% left above the floor)', round(v_est_u, 2),
        round((security.on_demand_credit_left_v1()->>'openrouter_balance_usd')::numeric - (security.on_demand_credit_left_v1()->>'openrouter_floor_usd')::numeric, 2);
    end if;
    if v_open is not null then
      update pipeline.enrich_plan_runs set state = 'cancelled', finished_at = now(), updated_at = now(), reason = reason || ' · superseded by Run now: ' || v_reason,
             steps = (select coalesce(jsonb_agg(case when s->>'status' in ('pending', 'waiting') then s || jsonb_build_object('status', 'cancelled', 'note', 'superseded by Run now', 'finished_at', now())
                                                     when s->>'status' = 'running' then s || jsonb_build_object('status', 'handed_over', 'note', 'task carried into the Run now plan', 'finished_at', now())
                                                     else s end order by o), '[]'::jsonb)
                        from jsonb_array_elements(steps) with ordinality e(s, o))
       where id = (v_open->>'id')::uuid;
    end if;
    insert into pipeline.enrich_plan_runs(provider_id, mode, steps, estimate, requested_by, reason)
    values (v_pid, 'manual', v_steps || v_carry, jsonb_build_object('credits', v_est_c, 'usd', v_est_u) || case when v_open is not null then jsonb_build_object('superseded', v_open->>'id') else '{}'::jsonb end,
            auth.uid(), v_reason) returning id into v_id;
    if v_open is not null then
      update pipeline.admin_jobs set args = args || jsonb_build_object('plan_run', v_id, 'plan_mode', 'manual', 'superseded_run', v_open->>'id')
       where id in (select nullif(k->'ref'->>'id', '')::uuid from jsonb_array_elements(v_carry) k where k->'ref'->>'kind' = 'job');
      insert into pipeline.admin_control_events(area, action, target, detail, actor)
      values ('enrich_plan', 'supersede', v_pid::text, jsonb_build_object('run', v_id, 'superseded', v_open->>'id', 'carried', v_carry, 'reason', v_reason), auth.uid());
    end if;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('enrich_plan', 'run', v_pid::text, jsonb_build_object('run', v_id, 'steps', p_args->'steps', 'estimate_credits', v_est_c, 'estimate_usd', v_est_u, 'reason', v_reason), auth.uid());
    perform security.enrich_plan_tick_v1(v_id);  -- the first step starts now (this run only)
    return jsonb_build_object('run_id', v_id, 'estimate', jsonb_build_object('credits', v_est_c, 'usd', v_est_u));
  elsif p_action = 'cancel' then
    if v_rank < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
    update pipeline.enrich_plan_runs set state = 'cancelled', finished_at = now(), updated_at = now(), reason = reason || ' · cancelled: ' || coalesce(nullif(v_reason, ''), 'by a person')
     where id = (p_args->>'run_id')::uuid and state in ('queued', 'running') returning id into v_id;
    if v_id is null then return jsonb_build_object('cancelled', false); end if;
    -- 3 Nov 2026 (Platform Admin 09:32 §3 "Cancel safely"): the run's open steps stop and each running step's task is cancelled
    return jsonb_build_object('cancelled', true) || security.enrich_plan_cancel_steps_v1(v_id, coalesce(nullif(v_reason, ''), 'by a person'));
  elsif p_action = 'retry' then
    -- 3 Nov 2026 (Platform Admin 09:32 §3 "Retry failed items"): the failed, timed-out or stopped steps of a finished run run again as a Run now
    -- of the same university, through the same steps, estimate and on-demand allowance
    if v_rank < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
    if length(v_reason) < 4 then raise exception 'give a reason (kept with the run)'; end if;
    select r.provider_id, jsonb_agg(s->'step') into v_pid, v_steps
      from pipeline.enrich_plan_runs r cross join lateral jsonb_array_elements(r.steps) s
     where r.id = nullif(p_args->>'run_id', '')::uuid and r.state in ('done', 'failed', 'cancelled') and s->>'status' in ('failed', 'timed_out', 'stopped')
     group by r.provider_id;
    if v_pid is null then raise exception 'nothing to retry: the run is still open, or none of its steps failed'; end if;
    return public.admin_enrich_plan('run', jsonb_build_object('provider', v_pid, 'steps', v_steps,
             'reason', 'Retry of the failed steps of run ' || left(p_args->>'run_id', 8) || ': ' || v_reason)) || jsonb_build_object('retry_of', p_args->>'run_id', 'steps', v_steps);
  elsif p_action = 'export' then
    -- 3 Nov 2026 (Platform Admin 09:32 §3 "Export execution and evidence results"): one row per step of each run of the last plans.export_days
    -- days (one university, or all), plans.export_runs_per_page runs a page
    return jsonb_build_object('page_runs', security.pipeline_num_v1('plans.export_runs_per_page', 500),
      'runs', (select count(*) from (select 1 from pipeline.enrich_plan_runs r0
               where (v_pid is null or r0.provider_id = v_pid) and r0.created_at > now() - make_interval(days => security.pipeline_num_v1('plans.export_days', 30)::int)
               limit security.pipeline_num_v1('plans.export_runs_per_page', 500)::int offset greatest(coalesce(nullif(p_args->>'offset', '')::int, 0), 0)) c),
      'rows', (select coalesce(jsonb_agg(to_jsonb(z) order by z.created_at desc, z.run, z.step_no), '[]'::jsonb) from (
      select r.id run, coalesce(p.display_name, p.canonical_name) university, r.provider_id, r.mode, r.state, r.created_at, r.finished_at, r.reason, r.needs_person,
             e.o step_no, e.s->>'step' step, e.s->>'label' label, e.s->>'status' status, e.s->>'note' note, e.s->'ref'->>'kind' task_kind, e.s->'ref'->>'id' task_id,
             e.s->>'started_at' step_started_at, e.s->>'finished_at' step_finished_at, e.s->>'est_credits' est_credits, e.s->>'est_usd' est_usd,
             r.actual->>'credits' actual_credits, r.actual->>'usd' actual_usd
        from (select * from pipeline.enrich_plan_runs r0
               where (v_pid is null or r0.provider_id = v_pid) and r0.created_at > now() - make_interval(days => security.pipeline_num_v1('plans.export_days', 30)::int)
               order by r0.created_at desc, r0.id
               limit security.pipeline_num_v1('plans.export_runs_per_page', 500)::int offset greatest(coalesce(nullif(p_args->>'offset', '')::int, 0), 0)) r
        join catalogue.providers p on p.id = r.provider_id
        cross join lateral jsonb_array_elements(r.steps) with ordinality e(s, o)) z));
  elsif p_action = 'unit_costs' then
    -- 3 Nov 2026 (Platform Admin 09:32 §3 "Estimate new Firecrawl/AI expenditure"): the unit costs the plan estimates use, for other confirmations
    return jsonb_build_object('unit_costs', security.enrich_unit_costs_v1(), 'on_demand', jsonb_build_object('credits_left', v_left_c, 'usd_left', v_left_u));
  elsif p_action = 'control' then
    if v_rank < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
    if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
    update pipeline.enrich_plan_control set auto_enabled = coalesce((p_args->>'auto')::boolean, auto_enabled), owner = auth.uid(), reason = v_reason, updated_at = now() where id = 1;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('enrich_plan', case when (p_args->>'auto')::boolean then 'auto_on' else 'auto_off' end, 'enrich-plan-auto', jsonb_build_object('reason', v_reason), auth.uid());
    return public.admin_enrich_plan('overview', '{}'::jsonb);
  end if;
  raise exception 'unknown action %', p_action using errcode = '22023';
end $_$;


ALTER FUNCTION "public"."admin_enrich_plan"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_entry_course_link_decide"("p_link" "uuid", "p_course" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare l catalogue.entry_course_links%rowtype; v_reason text := btrim(coalesce(p_reason, '')); v_m int := 0; v_q int := 0;
begin
  if auth.uid() is null or security.current_role_rank() < 3 then raise exception 'Layer 4 reviewer required' using errcode = '42501'; end if;
  if length(v_reason) < 5 then raise exception 'reason required'; end if;
  select * into l from catalogue.entry_course_links where id = p_link for update;
  if l.id is null then raise exception 'course link not found'; end if;
  if p_course is not null and not exists (select 1 from catalogue.courses c where c.id = p_course and c.provider_id = l.provider_id) then
    raise exception 'the course is not one of this provider''s catalogue courses' using errcode = '22023';
  end if;
  update catalogue.entry_course_links set course_id = p_course, state = case when p_course is null then 'rejected' else 'confirmed' end, method = 'person',
         reason = v_reason, decided_by = auth.uid(), decided_at = now(), updated_at = now()
   where id = l.id;
  -- the label's waiting rows take the decision (admitted rows are changed only by a later read and its decision)
  update catalogue.provider_entry_matrix m set course_id = p_course, updated_at = now()
   where m.provider_id = l.provider_id and m.status = 'proposed' and security.entry_course_title_key_v1(m.course_label) = l.label_key
     and m.course_id is distinct from p_course;
  get diagnostics v_m = row_count;
  update catalogue.provider_qualification_requirements q set course_id = p_course, updated_at = now()
   where q.provider_id = l.provider_id and q.status = 'proposed' and security.entry_course_title_key_v1(q.course_label) = l.label_key
     and q.course_id is distinct from p_course;
  get diagnostics v_q = row_count;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('entry_matrix', case when p_course is null then 'course_link_none' else 'course_link' end, 'catalogue.entry_course_links',
          jsonb_build_object('link', l.id, 'provider', l.provider_id, 'label', l.course_label, 'course', p_course, 'previous', l.course_id, 'previous_state', l.state,
                             'rows', v_m, 'qualification_rows', v_q, 'reason', v_reason), auth.uid());
  return jsonb_build_object('ok', true, 'state', case when p_course is null then 'rejected' else 'confirmed' end, 'rows', v_m, 'qualification_rows', v_q);
end $$;


ALTER FUNCTION "public"."admin_entry_course_link_decide"("p_link" "uuid", "p_course" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_entry_course_link_decide"("p_link" "uuid", "p_course" "uuid", "p_reason" "text") IS 'F-AER.08 Layer 4: a person links a printed course label to one of the provider''s catalogue courses (or records none); the label''s waiting rows take it';



CREATE OR REPLACE FUNCTION "public"."admin_entry_course_links"("p_provider" "uuid", "p_state" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or security.current_role_rank() < 3 then raise exception 'Layer 4 reviewer required' using errcode = '42501'; end if;
  -- suggestions for the provider's unresolved labels not yet suggested (made here, outside the read that records the rows)
  perform security.entry_course_link_suggest_v1(l.id) from catalogue.entry_course_links l
    where l.provider_id = p_provider and l.state = 'unresolved' and not (l.evidence ? 'suggested_at');
  return jsonb_build_object('provider_id', p_provider,
    'counts', (select jsonb_object_agg(state, n) from (select state, count(*) n from catalogue.entry_course_links where provider_id = p_provider group by 1) z),
    'links', coalesce((select jsonb_agg(jsonb_build_object('id', l.id, 'label', l.course_label, 'state', l.state, 'method', l.method, 'cricos', l.cricos_code,
                         'course_id', l.course_id, 'course', c.canonical_title, 'course_code', c.course_code, 'candidates', l.candidates, 'evidence', l.evidence,
                         'reason', l.reason, 'decided_at', l.decided_at,
                         'waiting_rows', (select count(*) from catalogue.provider_entry_matrix m where m.provider_id = l.provider_id and m.status = 'proposed'
                                            and security.entry_course_title_key_v1(m.course_label) = l.label_key)
                                       + (select count(*) from catalogue.provider_qualification_requirements q where q.provider_id = l.provider_id and q.status = 'proposed'
                                            and security.entry_course_title_key_v1(q.course_label) = l.label_key))
                       order by case l.state when 'unresolved' then 0 when 'rejected' then 1 else 2 end, l.course_label)
                       from catalogue.entry_course_links l left join catalogue.courses c on c.id = l.course_id
                      where l.provider_id = p_provider and (p_state is null or l.state = p_state)), '[]'::jsonb));
end $$;


ALTER FUNCTION "public"."admin_entry_course_links"("p_provider" "uuid", "p_state" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_entry_course_links"("p_provider" "uuid", "p_state" "text") IS 'F-AER.08 Layer 4 course links: each printed course label of a provider''s entry tables, its catalogue course or suggestions (made on first view), and its waiting rows';



CREATE OR REPLACE FUNCTION "public"."admin_entry_matrix_reread"("p_source_ids" "uuid"[], "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_src pipeline.entry_matrix_sources%rowtype; v_run pipeline.entry_matrix_runs%rowtype; v_sid uuid;
        v_reason text := trim(coalesce(p_reason, '')); v_runs int := 0; v_rows int := 0; v_items int := 0; v_n int;
        v_older_rows int := 0; v_older_items int := 0; v_ids jsonb := '[]'; v_skipped jsonb := '[]';
begin
  -- a request through the API (JWT claims present) must be a Platform Admin; a direct database session (the owner, a migration) has no claims. (current_user is always the owner inside a security definer function, so it cannot tell them apart)
  if (auth.uid() is not null or coalesce(auth.role(), '') <> '') and (auth.uid() is null or security.current_role_rank() < 6) then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(trim(coalesce(p_reason, ''))) < 5 then raise exception 'reason required'; end if;
  if coalesce(array_length(p_source_ids, 1), 0) = 0 then raise exception 'no sources given'; end if;
  -- A5 (30 Oct 2026): one source at a time, in ascending id order, so locks are always taken in the same order
  for v_sid in select distinct u from unnest(p_source_ids) u order by 1 loop
    select * into v_src from pipeline.entry_matrix_sources where id = v_sid for update;
    if v_src.id is null then
      v_skipped := v_skipped || jsonb_build_array(jsonb_build_object('source', v_sid, 'why', 'not_found')); continue;
    end if;
    -- W28: the run on the newest stored copy (the source's current content_hash), else the latest run; older copies keep their history
    select * into v_run from pipeline.entry_matrix_runs where source_id = v_src.id
     order by (content_hash is not distinct from v_src.content_hash) desc, created_at desc, id desc limit 1 for update;
    if v_run.id is null then
      v_skipped := v_skipped || jsonb_build_array(jsonb_build_object('source', v_src.id, 'why', 'never_read')); continue;
    end if;
    if v_run.state in ('queued', 'leased') then
      v_skipped := v_skipped || jsonb_build_array(jsonb_build_object('source', v_src.id, 'why', 'already_waiting')); continue;
    end if;

    -- W28: runs on older stored copies are not read again. Their proposed rows, then their still-pending item, are superseded; decided items stay
    update catalogue.provider_entry_matrix m set status = 'superseded', status_reason = 'older stored copy; read again on the newest copy: ' || v_reason, updated_at = now()
     where m.status = 'proposed' and m.run_id in (select r.id from pipeline.entry_matrix_runs r left join pipeline.layer4_review_items li on li.id = r.review_item_id
                                                   where r.source_id = v_src.id and r.id <> v_run.id and (li.id is null or li.status = 'pending'));
    get diagnostics v_n = row_count; v_older_rows := v_older_rows + v_n;
    update pipeline.layer4_review_items li set status = 'superseded'
     where li.status = 'pending' and li.id in (select r.review_item_id from pipeline.entry_matrix_runs r where r.source_id = v_src.id and r.id <> v_run.id);
    get diagnostics v_n = row_count; v_older_items := v_older_items + v_n;

    -- the newest copy's run only (done or failed; D3: a failed run, held_unparsed included, can be read again here after a reader change):
    -- rows first, then the item (its trigger, entry_matrix_review_apply_v1, then finds no proposed rows left), earlier result kept, re-queued
    if v_run.state in ('done', 'failed') then
      update catalogue.provider_entry_matrix set status = 'superseded', status_reason = 'read again: ' || v_reason, updated_at = now()
       where run_id = v_run.id and status = 'proposed';
      get diagnostics v_n = row_count; v_rows := v_rows + v_n;
      if v_run.review_item_id is not null then
        update pipeline.layer4_review_items set status = 'superseded' where id = v_run.review_item_id and status = 'pending';
        get diagnostics v_n = row_count; v_items := v_items + v_n;
      end if;
      update pipeline.entry_matrix_runs
         set previous_results = previous_results || jsonb_build_array(jsonb_build_object('result', v_run.result, 'rows_admitted', v_run.rows_admitted,
               'rows_dropped', v_run.rows_dropped, 'cost_usd', v_run.cost_usd, 'model', v_run.model_code, 'review_item_id', v_run.review_item_id, 'done_at', v_run.done_at,
               'reread_at', now(), 'reason', v_reason,
               -- D3: the earlier result's state, error and the attempts it used stay with it; earlier_index links it to what came before
               'state', v_run.state, 'error', v_run.error, 'attempts_used', v_run.attempts, 'earlier_index', jsonb_array_length(v_run.previous_results))),
             state = 'queued', attempts = 0, leased_until = null, result = null, rows_admitted = 0, rows_dropped = 0, review_item_id = null,
             error = null, done_at = null, updated_at = now()
       where id = v_run.id;
      v_runs := v_runs + 1; v_ids := v_ids || jsonb_build_array(v_run.id);
    end if;
  end loop;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('entry_matrix', 'reread', 'pipeline.entry_matrix_runs',
          jsonb_build_object('sources', to_jsonb(p_source_ids), 'runs', v_runs, 'rows_superseded', v_rows + v_older_rows, 'items_superseded', v_items + v_older_items, 'reason', v_reason,
                             'run_ids', v_ids, 'older_rows_superseded', v_older_rows, 'older_items_superseded', v_older_items, 'skipped', v_skipped), auth.uid());
  return jsonb_build_object('ok', true, 'runs', v_runs, 'rows_superseded', v_rows + v_older_rows, 'items_superseded', v_items + v_older_items,
                            'older_items_superseded', v_older_items, 'skipped', v_skipped);
end $$;


ALTER FUNCTION "public"."admin_entry_matrix_reread"("p_source_ids" "uuid"[], "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_entry_matrix_reread"("p_source_ids" "uuid"[], "p_reason" "text") IS 'CF-247 AER v1.1: read stored entry-requirements pages again after a reader change; proposed rows and pending items superseded, earlier result kept. Platform Admin, logged. A5 (30 Oct 2026): per source only the run on the newest stored copy (W28 ordering) is re-queued; runs on older copies keep their history and their proposed rows and pending Layer 4 item are superseded; unknown, never-read and already-waiting sources are skipped and reported.';



CREATE OR REPLACE FUNCTION "public"."admin_entry_matrix_seed"("p_rows" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(trim(coalesce(p_reason, ''))) < 5 then raise exception 'reason required'; end if;
  insert into pipeline.entry_matrix_sources(provider_id, url, title, rank, found_via)
  select (r->>'provider_id')::uuid, r->>'url', left(r->>'title', 200), 1, 'manual'
    from jsonb_array_elements(p_rows) r
   where exists (select 1 from catalogue.providers p where p.id = (r->>'provider_id')::uuid) and r->>'url' ~ '^https?://'
  on conflict (provider_id, url) do nothing;
  get diagnostics v_n = row_count;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('entry_matrix', 'seed', 'pipeline.entry_matrix_sources', jsonb_build_object('rows', jsonb_array_length(p_rows), 'added', v_n, 'reason', trim(p_reason)), auth.uid());
  return jsonb_build_object('ok', true, 'added', v_n);
end $$;


ALTER FUNCTION "public"."admin_entry_matrix_seed"("p_rows" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_entry_requirements"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := coalesce(security.current_role_rank(), 0); v_pid uuid; v_cid uuid; v_size int; v_page int; v_status text; v_cc text; v_level text;
        v_total int; v jsonb; c record; g record; v_job uuid; v_reason text;
begin
  if auth.uid() is null or v_rank < 1 then raise exception 'assigned StudySearch role required' using errcode = '42501'; end if;
  v_size := greatest(1, least(coalesce(nullif(p_args->>'page_size', '')::int, 50), 100));  -- fixed: a page is at most 100 rows
  v_page := greatest(1, coalesce(nullif(p_args->>'page', '')::int, 1));
  if p_action = 'provider_matrix' then
    v_pid := nullif(p_args->>'provider_id', '')::uuid; if v_pid is null then raise exception 'provider_id required'; end if;
    v_status := nullif(p_args->>'status', ''); v_cc := upper(nullif(p_args->>'country', '')); v_level := nullif(p_args->>'level', '');
    if v_status is not null and v_status not in ('active', 'proposed', 'inactive', 'superseded', 'unverified') then raise exception 'unknown status'; end if;
    select count(*) into v_total from catalogue.provider_entry_matrix m
     where m.provider_id = v_pid and (v_status is null or m.status = v_status) and (v_cc is null or m.country_code = v_cc) and (v_level is null or m.level_label = v_level);
    return jsonb_build_object('total', v_total, 'page', v_page, 'page_size', v_size,
      'counts', (select coalesce(jsonb_object_agg(s, n), '{}'::jsonb) from (select m.status s, count(*) n from catalogue.provider_entry_matrix m where m.provider_id = v_pid group by 1) z),
      'countries', (select coalesce(jsonb_agg(jsonb_build_object('code', z.cc, 'n', z.n) order by z.cc), '[]'::jsonb) from (select m.country_code cc, count(*) n from catalogue.provider_entry_matrix m where m.provider_id = v_pid group by 1) z),
      'levels', (select coalesce(jsonb_agg(distinct m.level_label), '[]'::jsonb) from catalogue.provider_entry_matrix m where m.provider_id = v_pid and m.level_label is not null),
      -- AER programme (29 Oct 2026): the provider's sources and each one's latest read, holds included (at most 50; fixed: a page of sources)
      'sources_total', (select count(*) from pipeline.entry_matrix_sources s where s.provider_id = v_pid),
      'sources', (select coalesce(jsonb_agg(z.x order by z.o, z.u), '[]'::jsonb) from (
        select case s.status when 'read' then 1 when 'found' then 2 when 'reading' then 2 else 3 end o, s.url u,
               jsonb_build_object('id', s.id, 'url', s.url, 'title', s.title, 'status', s.status, 'read_via', s.read_via, 'http', s.http_status,
                 'error', s.error, 'attempts', s.attempts, 'read_at', s.read_at,
                 'run', (select jsonb_build_object('state', r.state, 'rows', r.rows_admitted, 'not_kept', r.rows_dropped, 'error', r.error, 'cost_usd', r.cost_usd,
                                 'done_at', r.done_at, 'basis', r.result->>'page_basis',
                                 'review_status', (select li.status from pipeline.layer4_review_items li where li.id = r.review_item_id))
                           from pipeline.entry_matrix_runs r where r.source_id = s.id order by r.updated_at desc limit 1)) x
          from pipeline.entry_matrix_sources s where s.provider_id = v_pid order by 1, 2 limit 50) z),
      'rows', (select coalesce(jsonb_agg(z.x order by z.cc, z.lv, z.band, z.q), '[]'::jsonb) from (
        select m.country_code cc, m.level_label lv, m.benchmark_band band, m.qualification_name q,
               jsonb_build_object('id', m.id, 'country', m.country_code, 'level', m.level_label, 'kind', m.matrix_kind, 'qualification', m.qualification_name,
                 'band', m.benchmark_band, 'min_grade', m.min_grade, 'min_value', m.min_value, 'scale', m.grade_scale, 'conditions', m.conditions, 'quote', m.quote,
                 'source_url', m.source_url, 'evidence', case when e.id is null then null else jsonb_build_object('id', e.id, 'captured_at', e.captured_at, 'content_hash', e.content_hash) end,
                 'as_at', m.as_at, 'edition', m.edition, 'status', m.status, 'status_reason', m.status_reason, 'course_code', k.course_code,
                 'run', case when r.id is null then null else jsonb_build_object('id', r.id, 'state', r.state, 'attempts', r.attempts, 'error', r.error, 'done_at', r.done_at,
                   'review_item_id', r.review_item_id, 'review_status', (select li.status from pipeline.layer4_review_items li where li.id = r.review_item_id)) end) x
          from catalogue.provider_entry_matrix m left join pipeline.entry_matrix_runs r on r.id = m.run_id left join pipeline.evidence_artifacts e on e.id = m.evidence_id
          left join catalogue.courses k on k.id = m.course_id
         where m.provider_id = v_pid and (v_status is null or m.status = v_status) and (v_cc is null or m.country_code = v_cc) and (v_level is null or m.level_label = v_level)
         order by m.country_code, m.level_label, m.benchmark_band, m.qualification_name limit v_size offset (v_page - 1) * v_size) z));
  elsif p_action = 'course' then
    v_cid := nullif(p_args->>'course_id', '')::uuid; if v_cid is null then raise exception 'course_id required'; end if;
    select x.id, x.provider_id, x.canonical_title, x.course_code, l.short_code lvl, k.iso_alpha2 cc into c
      from catalogue.courses x left join ref.study_levels l on l.id = x.study_level_id join catalogue.providers p on p.id = x.provider_id left join ref.countries k on k.id = p.country_id where x.id = v_cid;
    if c.id is null then raise exception 'course not found'; end if;
    select pg.url, pg.status, pg.identity_basis, e.id ev, e.captured_at, e.storage_path is not null held into g
      from pipeline.coverage_course_pages pg left join pipeline.evidence_artifacts e on e.id = pg.evidence_id where pg.course_id = v_cid;
    return jsonb_build_object('course', jsonb_build_object('id', c.id, 'title', c.canonical_title, 'code', c.course_code, 'level', c.lvl, 'country', c.cc, 'provider_id', c.provider_id),
      'page', case when g.url is null then null else jsonb_build_object('url', g.url, 'status', g.status, 'identity_basis', g.identity_basis, 'evidence_id', g.ev, 'captured_at', g.captured_at, 'held', g.held) end,
      'rows', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'kind', r.kind, 'audience', r.audience, 'description', r.description, 'min_grade', r.min_grade,
                 'min_entry_score', r.min_entry_score, 'min_entry_score_basis', r.min_entry_score_basis, 'benchmark_band', r.benchmark_band, 'quote', r.quote,
                 'source_url', r.source_url, 'evidence_id', r.evidence_id, 'confidence', r.confidence, 'as_at', r.as_at, 'status', r.status, 'status_reason', r.status_reason,
                 'review_item_id', r.provenance->>'review_item_id', 'model', r.provenance->>'model') order by r.status, r.kind), '[]'::jsonb)
               from (select * from catalogue.course_entry_requirements r0 where r0.course_id = v_cid order by r0.created_at desc limit 100) r),  -- fixed: a course's rows, at most 100
      'reviews', (select coalesce(jsonb_agg(jsonb_build_object('id', li.id, 'status', li.status, 'created_at', li.created_at, 'rows', li.proposed_value->'rows') order by li.created_at desc), '[]'::jsonb)
                    from (select * from pipeline.layer4_review_items l0 where l0.entity_type = 'course' and l0.entity_id = v_cid and l0.field_code = 'course_entry_first_read' order by l0.created_at desc limit 10) li),
      'reads', (select coalesce(jsonb_agg(jsonb_build_object('item_id', fi.id, 'state', fi.state, 'reason', fi.reason, 'cost_usd', fi.cost_usd, 'created_at', fi.created_at,
                    'dropped', fi.value->'dropped', 'notes', fi.value->'notes') order by fi.created_at desc), '[]'::jsonb)
                  from (select * from pipeline.field_enrich_items f0 where f0.course_id = v_cid and f0.field = 'entry_requirements' order by f0.id desc limit 10) fi),
      'countries', (select coalesce(jsonb_agg(jsonb_build_object('code', k2.iso_alpha2, 'name', k2.name) order by k2.name), '[]'::jsonb) from ref.countries k2 where k2.iso_alpha2 ~ '^[A-Z]{2}$'),
      'can_read', v_rank >= 6 and g.held is true and c.cc in (select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'entry.course_read_countries'), '[]'::jsonb))));
  elsif p_action = 'resolve' then
    v_cid := nullif(p_args->>'course_id', '')::uuid; if v_cid is null then raise exception 'course_id required'; end if;
    return security.entry_resolve_v1(v_cid, p_args->>'country');
  elsif p_action = 'read' then
    if v_rank < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
    v_cid := nullif(p_args->>'course_id', '')::uuid; v_reason := btrim(coalesce(p_args->>'reason', ''));
    if length(v_reason) < 5 then raise exception 'give a reason (kept in the log)'; end if;
    select x.id, x.provider_id, x.canonical_title, k.iso_alpha2 cc into c
      from catalogue.courses x join catalogue.providers p on p.id = x.provider_id left join ref.countries k on k.id = p.country_id where x.id = v_cid;
    if c.id is null then raise exception 'course not found'; end if;
    if c.cc is null or c.cc not in (select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'entry.course_read_countries'), '[]'::jsonb))) then
      raise exception 'course entry requirements are not read for this country (entry.course_read_countries)';
    end if;
    if exists (select 1 from pipeline.field_enrich_items f where f.course_id = v_cid and f.field = 'entry_requirements' and f.state in ('queued', 'waiting', 'ai', 'leased', 'review')) then
      raise exception 'a read of this course is already in progress or waits in Layer 4';
    end if;
    v_job := security.course_entry_read_enqueue_v1(v_cid, auth.uid(), v_reason);
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('entry_requirements', 'course_read', v_cid::text, jsonb_build_object('reason', v_reason, 'job_id', v_job), auth.uid());
    return jsonb_build_object('job_id', v_job);
  end if;
  raise exception 'unknown action %', p_action;
end $_$;


ALTER FUNCTION "public"."admin_entry_requirements"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_entry_requirements"("p_action" "text", "p_args" "jsonb") IS 'CF-247 Track C Step B (B5): bounded admin reads of entry requirements (provider matrix, a course''s rows, the resolver) and the Platform Admin''s one-course read request.';



CREATE OR REPLACE FUNCTION "public"."admin_evidence_copy_roles"("p_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_out jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode = '42501'; end if;
  if security.current_role_rank() < 3 then raise exception 'assigned StudySearch role required' using errcode = '42501'; end if;
  if coalesce(array_length(p_ids, 1), 0) > 200 then raise exception 'at most 200 ids'; end if;  -- fixed: one list page (the list's own limit)
  with e as (
    select x.id, x.evidence_type, x.storage_path, coalesce(x.captured_at, x.created_at) t,
           case when x.storage_path like 'layer2/%/coverage/%' then split_part(x.storage_path, '/', 5) end k
      from pipeline.evidence_artifacts x where x.id = any(p_ids)),
  c as materialized (  -- every copy of the course pages on screen, read once
    select split_part(y.storage_path, '/', 5) k, y.evidence_type, coalesce(y.captured_at, y.created_at) t from pipeline.evidence_artifacts y
     where y.storage_path like 'layer2/%/coverage/%' and split_part(y.storage_path, '/', 5) in (select e.k from e where e.k is not null)),
  r as (
    select e.id, e.k,
           case when e.k is null then null else (select g.evidence_id = e.id from pipeline.coverage_course_pages g
                                                  where g.course_id = case when e.k ~* '^[0-9a-f-]{36}$' then e.k::uuid end) end in_use,
           e.k is not null and (exists (select 1 from catalogue.course_fees f where f.evidence_id = e.id) or exists (select 1 from catalogue.course_intakes i where i.evidence_id = e.id)
             or exists (select 1 from catalogue.course_english_requirements q where q.evidence_id = e.id) or exists (select 1 from catalogue.course_links l where l.evidence_id = e.id)
             or exists (select 1 from catalogue.course_campuses cc where cc.evidence_id = e.id)) values_live,
           (select count(*) from c where c.k = e.k and c.evidence_type = e.evidence_type) copies,
           (select count(*) from c where c.k = e.k and c.evidence_type = e.evidence_type and c.t <= e.t) nth,
           case when e.k is not null then 'course_page'
                when e.storage_path like 'layer2/%/provider-facts/%' then 'provider_facts'
                when e.evidence_type = 'regulatory_snapshot' then 'register_file'
                when e.evidence_type in ('website_screenshot', 'screenshot') then 'screenshot' else 'other' end kind
      from e)
  select coalesce(jsonb_object_agg(r.id, jsonb_build_object('kind', r.kind,
           'role', case when r.kind <> 'course_page' then null when r.in_use then 'in_use' when r.values_live then 'older_values_live' else 'older' end,
           'copy', r.nth, 'copies', r.copies)), '{}'::jsonb) into v_out from r;
  return v_out;
end $_$;


ALTER FUNCTION "public"."admin_evidence_copy_roles"("p_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_evidence_reuse_today"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_from timestamptz := date_trunc('day', now() at time zone 'Australia/Melbourne') at time zone 'Australia/Melbourne'; v jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode = '42501'; end if;
  if security.current_role_rank() < 3 then raise exception 'assigned StudySearch role required' using errcode = '42501'; end if;
  select jsonb_build_object('since', v_from,
           'read', count(*),
           'kept', count(*) filter (where coalesce(e.captured_at, e.created_at) < v_from),
           'new_copies', count(*) filter (where coalesce(e.captured_at, e.created_at) >= v_from),
           'on', security.pipeline_num_v1('evidence.reuse_unchanged_pages', 1) >= 1)
    into v
    from pipeline.coverage_course_pages g join pipeline.evidence_artifacts e on e.id = g.evidence_id
   where g.read_status = 'read' and g.read_at >= v_from;
  return v || jsonb_build_object('new_bytes', (select coalesce(sum((o.metadata->>'size')::bigint), 0) from pipeline.evidence_artifacts e join storage.objects o on o.bucket_id = 'evidence' and o.name = e.storage_path
                                                where e.storage_path like 'layer2/%/coverage/%' and coalesce(e.captured_at, e.created_at) >= v_from));
end $$;


ALTER FUNCTION "public"."admin_evidence_reuse_today"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_evidence_summary"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare e pipeline.evidence_artifacts%rowtype; v_course uuid; v_key text; v_page record; v_obj record; v_src record; v_job record; v_supplied jsonb; v_lim int := 20;  -- fixed: values listed in the panel (the total is given)
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode = '42501'; end if;
  if security.current_role_rank() < 3 then raise exception 'assigned StudySearch role required' using errcode = '42501'; end if;
  select * into e from pipeline.evidence_artifacts where id = p_id;
  if e.id is null then return jsonb_build_object('error', 'not_found'); end if;

  v_course := case when coalesce(e.metadata->>'course_id', '') ~* '^[0-9a-f-]{36}$' then (e.metadata->>'course_id')::uuid end;
  if v_course is null then select g.course_id into v_course from pipeline.coverage_course_pages g where g.evidence_id = e.id limit 1; end if;
  if v_course is null then
    select x.course_id into v_course from (
      select course_id from catalogue.course_fees where evidence_id = e.id union all select course_id from catalogue.course_intakes where evidence_id = e.id
      union all select course_id from catalogue.course_english_requirements where evidence_id = e.id union all select course_id from catalogue.course_links where evidence_id = e.id) x limit 1;
  end if;
  select g.evidence_id, g.url, g.status, g.read_status, g.identity_basis into v_page from pipeline.coverage_course_pages g where g.course_id = v_course;
  select o.id, (o.metadata->>'size')::bigint size into v_obj from storage.objects o where o.bucket_id = 'evidence' and o.name = e.storage_path;
  select s.label, s.url, s.source_type into v_src from pipeline.sources s where s.id = e.source_id;
  select j.id, j.job_type, j.status into v_job from pipeline.jobs j where j.id = e.job_id;
  v_key := case when e.storage_path like 'layer2/%/coverage/%' then split_part(e.storage_path, '/', 5) end;

  with s as (
    select 'Fee' field, concat_ws(' ', f.currency_code, to_char(f.amount, 'FM999,999,990'), case f.basis when 'annual' then 'a year' when 'total_indicative' then 'whole course' else f.basis end, f.fee_year::text) val, f.status, 1 o from catalogue.course_fees f where f.evidence_id = e.id
    union all select 'Intake', coalesce(i.intake_label, to_char(i.start_date, 'DD Mon YYYY'), i.intake_year::text), i.status, 2 from catalogue.course_intakes i where i.evidence_id = e.id
    union all select 'English', concat_ws(' ', t.code, 'overall ' || r.overall_score::text, case when r.component_scores is not null and r.component_scores <> '{}'::jsonb then 'bands ' || (select string_agg(v.value, '/' order by v.key) from jsonb_each_text(r.component_scores) v) end), r.status, 3
      from catalogue.course_english_requirements r left join ref.english_tests t on t.id = r.english_test_id where r.evidence_id = e.id
    union all select 'Link: ' || replace(l.link_type, '_', ' '), l.url, l.status, 4 from catalogue.course_links l where l.evidence_id = e.id
    union all select 'Campus', c.name, null, 5 from catalogue.course_campuses cc join catalogue.campuses c on c.id = cc.campus_id where cc.evidence_id = e.id)
  select jsonb_build_object('total', count(*), 'items', coalesce((select jsonb_agg(jsonb_build_object('field', z.field, 'value', z.val, 'status', z.status) order by z.o, z.field, z.val)
                                                               from (select * from s order by o limit v_lim) z), '[]'::jsonb))
    into v_supplied from s;

  return jsonb_build_object(
    'id', e.id, 'evidence_type', e.evidence_type, 'captured_at', coalesce(e.captured_at, e.created_at),
    'page_url', e.source_url, 'source', case when v_src.label is not null then jsonb_build_object('label', v_src.label, 'url', v_src.url, 'type', v_src.source_type) end,
    'fetched_via', e.metadata->>'fetched_via', 'worker', e.metadata->>'worker',
    'course', (select jsonb_build_object('id', c.id, 'title', coalesce(c.display_title, c.canonical_title), 'code', c.course_code,
                 'provider', coalesce(p.display_name, p.canonical_name), 'provider_id', p.id)
                 from catalogue.courses c left join catalogue.providers p on p.id = c.provider_id where c.id = v_course),
    'accepted', case when v_course is null then null else jsonb_build_object(
                 'basis', coalesce(e.metadata->>'identity_basis', case when v_page.evidence_id = e.id then v_page.identity_basis end),
                 'in_use', v_page.evidence_id = e.id, 'page_now', v_page.url) end,
    'supplied', v_supplied,
    'reviews_open', (select count(*) from pipeline.layer4_review_items r where r.evidence_id = e.id and r.status not in ('approved', 'rejected', 'corrected', 'closed', 'resolved')),
    'copies', case when v_key is null then null else (select jsonb_build_object(
                 'earlier', count(*) filter (where coalesce(x.captured_at, x.created_at) < coalesce(e.captured_at, e.created_at)),
                 'later', count(*) filter (where coalesce(x.captured_at, x.created_at) > coalesce(e.captured_at, e.created_at)),
                 'newest_id', (array_agg(x.id order by coalesce(x.captured_at, x.created_at) desc) filter (where coalesce(x.captured_at, x.created_at) > coalesce(e.captured_at, e.created_at)))[1])
               from pipeline.evidence_artifacts x where x.evidence_type = e.evidence_type and x.storage_path like 'layer2/%/coverage/%' and split_part(x.storage_path, '/', 5) = v_key and x.id <> e.id) end,
    'file', jsonb_build_object('available', v_obj.id is not null, 'size_bytes', v_obj.size, 'mime_type', e.mime_type, 'content_hash', e.content_hash, 'storage_path', e.storage_path),
    'job', case when v_job.id is not null then jsonb_build_object('id', v_job.id, 'type', v_job.job_type, 'status', v_job.status) end);
end $_$;


ALTER FUNCTION "public"."admin_evidence_summary"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_exit_awards"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', '')); v_pid uuid := (p_args->>'provider_id')::uuid; v_res jsonb;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 4 then raise exception 'Layer 4 reviewer or Platform Admin required' using errcode = '42501'; end if;
  if p_action = 'read' and p_args->>'scope' = 'settings' then
    return (select to_jsonb(s) - 'id' from pipeline.award_link_settings s where s.id = 1);
  end if;
  if p_action = 'read' then
    return coalesce((select jsonb_agg(jsonb_build_object('child_course_id', x.child_course_id, 'child', ch.canonical_title, 'child_code', ch.course_code, 'parent_course_id', x.parent_course_id, 'parent', pc.canonical_title,
                     'years', x.exit_years, 'page_url', x.page_url, 'printed', x.printed, 'active', x.active, 'set_by', x.set_by, 'link_type', x.link_type, 'register_check', x.register_check, 'check_detail', x.check_detail,
                     'annual_fee', x.annual_fee, 'fee_year', x.fee_year, 'total_fee', x.total_fee, 'applied_at', x.applied_at) order by pc.canonical_title, x.exit_years)
                     from pipeline.course_exit_awards x join catalogue.courses ch on ch.id = x.child_course_id join catalogue.courses pc on pc.id = x.parent_course_id where x.provider_id = v_pid), '[]'::jsonb);
  end if;
  if coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action = 'detect' then
    v_res := jsonb_build_object('found', security.exit_awards_detect_v2(v_pid));
  elsif p_action = 'apply' then
    v_res := security.exit_awards_apply_v2(v_pid);
  elsif p_action = 'set' then
    if not exists (select 1 from catalogue.courses c where c.id = (p_args->>'child_course_id')::uuid and c.provider_id = v_pid)
       or not exists (select 1 from catalogue.courses c where c.id = (p_args->>'parent_course_id')::uuid and c.provider_id = v_pid) then
      raise exception 'both courses must belong to this university';
    end if;
    if coalesce((p_args->>'years')::numeric, 0) not between 0.5 and 8 then raise exception 'years must be from 0.5 to 8'; end if;
    if security.is_double_degree_title((select c.canonical_title from catalogue.courses c where c.id = (p_args->>'parent_course_id')::uuid)) then raise exception 'the parent must be a single degree, not a double degree'; end if;
    insert into pipeline.course_exit_awards(child_course_id, parent_course_id, provider_id, exit_years, page_url, evidence_id, printed, set_by, reason, link_type)
      select (p_args->>'child_course_id')::uuid, pg.course_id, v_pid, (p_args->>'years')::numeric, coalesce(nullif(btrim(p_args->>'page_url'), ''), pg.url), pg.evidence_id, left(p_args->>'printed', 300), 'hand', v_reason, coalesce(nullif(p_args->>'link_type', ''), 'exit_award')
      from pipeline.coverage_course_pages pg where pg.course_id = (p_args->>'parent_course_id')::uuid
    on conflict (child_course_id) do update set parent_course_id = excluded.parent_course_id, exit_years = excluded.exit_years, page_url = excluded.page_url, evidence_id = excluded.evidence_id, printed = excluded.printed, set_by = 'hand', reason = excluded.reason, active = true, link_type = excluded.link_type, set_at = now() where pipeline.course_exit_awards.child_course_id = excluded.child_course_id;
    update pipeline.course_exit_awards x set register_check = c.v[1], check_detail = c.v[2] from (select security.award_register_check((p_args->>'child_course_id')::uuid, (p_args->>'parent_course_id')::uuid) v) c where x.child_course_id = (p_args->>'child_course_id')::uuid;
    v_res := jsonb_build_object('ok', true);
  elsif p_action = 'settings' then
    update pipeline.award_link_settings set same_year_tolerance = coalesce((p_args->>'same_year_tolerance')::numeric, same_year_tolerance), lagged_tolerance = coalesce((p_args->>'lagged_tolerance')::numeric, lagged_tolerance), updated_by = auth.uid(), updated_at = now(), reason = v_reason where id = 1;
    update pipeline.course_exit_awards x set register_check = (security.award_register_check(x.child_course_id, x.parent_course_id))[1], check_detail = (security.award_register_check(x.child_course_id, x.parent_course_id))[2] where x.active;
    update pipeline.course_host_pages h set register_check = (security.award_register_check(h.course_id, h.host_course_id))[1], check_detail = (security.award_register_check(h.course_id, h.host_course_id))[2] where h.active and h.link_type = 'shared_page';
    v_res := jsonb_build_object('ok', true, 'links', (select count(*) from pipeline.course_exit_awards where active), 'passing', (select count(*) from pipeline.course_exit_awards where active and register_check = 'pass'));
  elsif p_action in ('off', 'on') then
    update pipeline.course_exit_awards set active = (p_action = 'on'), set_by = 'hand', reason = v_reason, set_at = now() where child_course_id = (p_args->>'child_course_id')::uuid;
    v_res := jsonb_build_object('ok', true);
  else
    raise exception 'unknown action';
  end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'exit_awards_' || p_action, coalesce(v_pid::text, p_args->>'child_course_id'), jsonb_build_object('result', v_res, 'args', p_args), auth.uid());
  return v_res;
end $$;


ALTER FUNCTION "public"."admin_exit_awards"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_fc_extract_report"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or security.current_role_rank() < 4 then raise exception 'Pipeline Operator role required' using errcode = '42501'; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('run_label', run_label, 'task_class', task_class, 'cases', n, 'right', ok, 'wrong_admitted', wrong, 'missed', missed, 'errors', errs,
                   'credits', credits, 'pass_80_rule', (n >= 30 and ok::numeric / n >= 0.80 and wrong = 0), 'last', last) order by last desc), '[]'::jsonb)
    from (select run_label, task_class, count(*) n, count(*) filter (where outcome in ('exact', 'exact_not_stated')) ok, count(*) filter (where outcome = 'wrong_admitted') wrong,
                 count(*) filter (where outcome = 'missed') missed, count(*) filter (where outcome = 'error') errs, sum(credits) credits, max(created_at) last
            from pipeline.fc_extract_results group by 1, 2) s);
end $$;


ALTER FUNCTION "public"."admin_fc_extract_report"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_fc_profiles_read_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare s jsonb; v jsonb; v_at timestamptz; v_reason text;
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  select jsonb_object_agg(key, value), max(updated_at) filter (where key = 'scrape_profiles_version'), max(reason) filter (where key = 'scrape_profiles_version')
    into s, v_at, v_reason from pipeline.platform_toolset_settings
   where toolset_key = 'firecrawl' and key in ('scrape_profiles', 'scrape_profile_lanes', 'scrape_profile_overrides', 'scrape_profiles_version', 'screenshot_max_mb');
  v := jsonb_build_object(
    'profiles', s->'scrape_profiles', 'lanes', s->'scrape_profile_lanes', 'overrides', s->'scrape_profile_overrides',
    'version', (s->>'scrape_profiles_version')::int, 'screenshot_max_mb', (s->>'screenshot_max_mb')::numeric, 'saved_at', v_at, 'reason', v_reason,
    'formats', '["markdown","rawHtml","html","links","screenshot"]'::jsonb, 'never_sent', '["json","summary","question","highlights","onlyCleanContent"]'::jsonb,
    'can_edit', coalesce(security.current_role_rank(), 0) >= 6);
  v := v || jsonb_build_object('problems', to_jsonb(security.fc_scrape_profiles_check_v1(v->'profiles', v->'lanes', v->'overrides')),
    'history', coalesce((select jsonb_agg(jsonb_build_object('at', e.created_at, 'version', e.detail->'version', 'reason', e.detail->>'reason') order by e.created_at desc)
                           from (select * from pipeline.admin_control_events where area = 'toolsets' and action = 'fc_profiles' order by created_at desc limit 10) e), '[]'::jsonb));
  return v;
end $$;


ALTER FUNCTION "public"."admin_fc_profiles_read_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_fc_profiles_read_v1"() IS 'CF-247 Firecrawl format profiles: the profiles, lane map, overrides, version, allowed and never-sent formats, any problem the check finds, and the last ten saves, for Toolsets and limits › Firecrawl › Format profiles.';



CREATE OR REPLACE FUNCTION "public"."admin_fc_profiles_set_v1"("p_profiles" "jsonb", "p_lanes" "jsonb", "p_overrides" "jsonb", "p_reason" "text", "p_expected_version" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_reason, '')); v_errs text[]; v_ver int; v_before jsonb;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  v_errs := security.fc_scrape_profiles_check_v1(p_profiles, coalesce(p_lanes, '{}'::jsonb), coalesce(p_overrides, '[]'::jsonb));
  if cardinality(v_errs) > 0 then raise exception 'not saved: %', array_to_string(v_errs, '; ') using errcode = '22023'; end if;
  select (value #>> '{}')::int into v_ver from pipeline.platform_toolset_settings where toolset_key = 'firecrawl' and key = 'scrape_profiles_version' for update;
  if p_expected_version is not null and p_expected_version <> v_ver then
    raise exception 'someone saved version % since you opened this; reload and make the change again', v_ver using errcode = '40001';
  end if;
  select jsonb_object_agg(key, value) into v_before from pipeline.platform_toolset_settings
   where toolset_key = 'firecrawl' and key in ('scrape_profiles', 'scrape_profile_lanes', 'scrape_profile_overrides');
  update pipeline.platform_toolset_settings s set value = x.v, reason = v_reason, updated_by = auth.uid(), updated_at = now()
    from (values ('scrape_profiles', p_profiles), ('scrape_profile_lanes', coalesce(p_lanes, '{}'::jsonb)), ('scrape_profile_overrides', coalesce(p_overrides, '[]'::jsonb)),
                 ('scrape_profiles_version', to_jsonb(v_ver + 1))) x(k, v)
   where s.toolset_key = 'firecrawl' and s.key = x.k;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('toolsets', 'fc_profiles', 'firecrawl.scrape_profiles',
          jsonb_build_object('version', v_ver + 1, 'before', v_before, 'after', jsonb_build_object('scrape_profiles', p_profiles, 'scrape_profile_lanes', p_lanes, 'scrape_profile_overrides', p_overrides), 'reason', v_reason),
          auth.uid());
  return jsonb_build_object('ok', true, 'version', v_ver + 1);
end $$;


ALTER FUNCTION "public"."admin_fc_profiles_set_v1"("p_profiles" "jsonb", "p_lanes" "jsonb", "p_overrides" "jsonb", "p_reason" "text", "p_expected_version" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_fc_profiles_set_v1"("p_profiles" "jsonb", "p_lanes" "jsonb", "p_overrides" "jsonb", "p_reason" "text", "p_expected_version" integer) IS 'CF-247 Firecrawl format profiles: Platform Admin saves the profiles, the lane map and the university overrides together with a reason; refused when security.fc_scrape_profiles_check_v1 finds a problem or someone saved since (p_expected_version); the version goes up by one; logged in admin_control_events.';



CREATE OR REPLACE FUNCTION "public"."admin_fee_reader"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_pid uuid := nullif(p_args->>'provider', '')::uuid; v_reason text := btrim(coalesce(p_args->>'reason', '')); v_n int; v_id uuid;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  if p_action = 'overview' then
    return jsonb_build_object(
      'scope', jsonb_build_object('countries', (select s.value from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'fees.countries'),
                                  'types', (select s.value from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'fees.provider_types'),
                                  'auto_confidence', security.pipeline_num_v1('fees.auto_admit_confidence', 0.85)),
      'profiles', (select coalesce(jsonb_agg(to_jsonb(cp) order by cp.country_code), '[]'::jsonb) from pipeline.fee_country_profiles cp),
      'spend_today', (select x.spent from security.ai_spend_today_v1() x where x.use = 'fee_ai'),
      'providers', (select coalesce(jsonb_agg(z order by z.name), '[]'::jsonb) from (
         select p.id provider_id, coalesce(p.display_name, p.canonical_name) name, k.iso_alpha2 country,
                (select count(*) from pipeline.provider_fact_sources f where f.provider_id = p.id and f.kind = 'fee_schedule') pages,
                (select count(*) from pipeline.provider_fact_sources f where f.provider_id = p.id and f.kind = 'fee_schedule' and f.content_hash is not null) pages_read,
                (select max(q.finished_at) from pipeline.fee_reader_queue q where q.provider_id = p.id) last_read,
                (select jsonb_object_agg(o, n) from (select r.outcome o, count(*) n from pipeline.fee_reader_rows r
                   where r.provider_id = p.id and r.queue_id in (select distinct on (q.fact_source_id) q.id from pipeline.fee_reader_queue q where q.provider_id = p.id and q.state = 'done' order by q.fact_source_id, q.finished_at desc)
                   group by 1) o) outcomes,
                (select count(*) from pipeline.fee_reader_findings x where x.provider_id = p.id and x.resolved_at is null) open_findings,
                (select count(distinct cf.course_id) from catalogue.course_fees cf join catalogue.courses c on c.id = cf.course_id
                  where c.provider_id = p.id and cf.fee_type = 'provider_current_tuition' and cf.status = 'active') courses_with_fee,
                (select count(*) from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active') courses
           from catalogue.providers p join ref.countries k on k.id = p.country_id
          where security.fee_reader_in_scope_v1(p.id) or exists (select 1 from pipeline.fee_reader_queue q where q.provider_id = p.id)) z));
  elsif p_action = 'provider' then
    return jsonb_build_object(
      'pages', (select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'url', f.url, 'status', f.status, 'found_via', f.found_via, 'read_at', f.read_at, 'stopped', f.status = 'rejected',
                  -- 22 Oct 2026: what the AI fee reader got from the page (the status above is the page fetch)
                  'fees', (select count(*) from pipeline.fee_reader_rows r where r.fact_source_id = f.id and r.outcome <> 'replaced'),
                  'admitted', (select count(*) from pipeline.fee_reader_rows r where r.fact_source_id = f.id and r.outcome = 'admitted'),
                  'to_review', (select count(*) from pipeline.fee_reader_rows r where r.fact_source_id = f.id and r.outcome = 'review'),
                  'already_held', (select count(*) from pipeline.fee_reader_rows r where r.fact_source_id = f.id and r.outcome = 'same'),
                  'last', (select jsonb_build_object('state', q.state, 'rows', q.rows_found, 'cost', q.cost_usd, 'at', coalesce(q.finished_at, q.created_at), 'error', q.error)
                             from pipeline.fee_reader_queue q where q.fact_source_id = f.id order by q.created_at desc limit 1)) order by f.rank desc, f.url), '[]'::jsonb)
                  from pipeline.provider_fact_sources f where f.provider_id = v_pid and f.kind = 'fee_schedule'),
      'rows', (select coalesce(jsonb_agg(to_jsonb(r) - 'provider_id' - 'queue_id' || jsonb_build_object('course', (select c.canonical_title from catalogue.courses c where c.id = r.course_id))
                                         order by r.outcome, r.qualification), '[]'::jsonb)
                 from (select * from pipeline.fee_reader_rows r where r.provider_id = v_pid
                         and r.queue_id in (select distinct on (q.fact_source_id) q.id from pipeline.fee_reader_queue q where q.provider_id = v_pid and q.state = 'done' order by q.fact_source_id, q.finished_at desc)
                       limit 500) r),
      'findings', (select coalesce(jsonb_agg(to_jsonb(x) order by x.resolved_at nulls first, x.last_seen desc), '[]'::jsonb) from (select * from pipeline.fee_reader_findings x where x.provider_id = v_pid order by x.last_seen desc limit 100) x),
      'notes', (select to_jsonb(r) from pipeline.fee_reader_recipes r where r.provider_id = v_pid),
      'can_run', v_rank >= 4, 'can_manage', v_rank >= 6);
  elsif p_action = 'read_again' then
    if v_rank < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
    if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
    update pipeline.fee_reader_queue set state = 'queued', attempts = 0, leased_until = null, error = null
     where id in (select distinct on (q.fact_source_id) q.id from pipeline.fee_reader_queue q where q.provider_id = v_pid
                    and not exists (select 1 from pipeline.provider_fact_sources sf where sf.id = q.fact_source_id and sf.status = 'rejected')  -- 22 Oct 2026: stopped pages stay stopped
                  order by q.fact_source_id, q.created_at desc);
    get diagnostics v_n = row_count;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('fees', 'read_again', v_pid::text, jsonb_build_object('pages', v_n, 'reason', v_reason), auth.uid());
    return jsonb_build_object('queued', v_n);
  elsif p_action in ('page_add', 'page_stop', 'page_resume') then
    -- 22 Oct 2026 (Platform Admin 15:57): add the right fee page by hand, stop one that gives no fees, or start it again
    if v_rank < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
    if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
    if not exists (select 1 from catalogue.providers p where p.id = v_pid) then raise exception 'unknown provider'; end if;
    if p_action = 'page_add' then
      if btrim(coalesce(p_args->>'url', '')) !~ '^https?://[^ ]+$' or length(btrim(p_args->>'url')) not between 12 and 500 then
        raise exception 'give the full page address (http or https)';
      end if;
      insert into pipeline.provider_fact_sources(provider_id, kind, url, title, rank, found_via, status)
      values (v_pid, 'fee_schedule', btrim(p_args->>'url'), null, 9, 'manual', 'found')
      on conflict (provider_id, kind, url) do update set status = 'found', attempts = 0, rank = 9, found_via = 'manual', read_at = null, updated_at = now()
      returning id into v_id;
    elsif p_action = 'page_stop' then
      update pipeline.provider_fact_sources set status = 'rejected', updated_at = now()
       where id = nullif(p_args->>'page', '')::uuid and provider_id = v_pid and kind = 'fee_schedule' returning id into v_id;
      if v_id is null then raise exception 'unknown fee page'; end if;
      update pipeline.fee_reader_queue set state = 'failed', error = 'stopped by a person', leased_until = null where fact_source_id = v_id and state = 'queued';
    else
      update pipeline.provider_fact_sources f set status = case when f.evidence_id is not null and f.content_hash is not null then 'read' else 'found' end,
             attempts = 0, read_at = case when f.evidence_id is not null and f.content_hash is not null then f.read_at end, updated_at = now()
       where f.id = nullif(p_args->>'page', '')::uuid and f.provider_id = v_pid and f.kind = 'fee_schedule' and f.status = 'rejected' returning f.id into v_id;
      if v_id is null then raise exception 'unknown or not stopped fee page'; end if;
      update pipeline.fee_reader_queue set state = 'queued', attempts = 0, error = null, leased_until = null
       where id = (select q.id from pipeline.fee_reader_queue q where q.fact_source_id = v_id order by q.created_at desc limit 1);
    end if;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('fees', p_action, v_pid::text, jsonb_build_object('page', v_id, 'url', p_args->>'url', 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true, 'page', v_id);
  elsif p_action = 'notes_set' then
    if v_rank < 5 then raise exception 'PIM Admin role or above required' using errcode = '42501'; end if;
    if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
    insert into pipeline.fee_reader_recipes(provider_id, notes, updated_by) values (v_pid, left(btrim(p_args->>'notes'), 1500), 'person')
    on conflict (provider_id) do update set history = (jsonb_build_array(jsonb_build_object('version', pipeline.fee_reader_recipes.version, 'notes', pipeline.fee_reader_recipes.notes,
                                                         'at', pipeline.fee_reader_recipes.updated_at, 'by', pipeline.fee_reader_recipes.updated_by)) || pipeline.fee_reader_recipes.history) - 5,
           version = pipeline.fee_reader_recipes.version + 1, notes = excluded.notes, updated_at = now(), updated_by = 'person';
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('fees', 'notes_set', v_pid::text, jsonb_build_object('reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true);
  elsif p_action = 'profile_set' then
    if v_rank < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
    if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
    insert into pipeline.fee_country_profiles(country_code, currency_code, usual_unit, full_time_units_a_year, unit_name, terms_a_year, notes, reason, updated_by)
    values (upper(p_args->>'country'), upper(p_args->>'currency'), p_args->>'usual_unit', nullif(p_args->>'full_time_units_a_year', '')::numeric, p_args->>'unit_name',
            nullif(p_args->>'terms_a_year', '')::numeric, p_args->>'notes', v_reason, auth.uid())
    on conflict (country_code) do update set currency_code = excluded.currency_code, usual_unit = excluded.usual_unit, full_time_units_a_year = excluded.full_time_units_a_year,
           unit_name = excluded.unit_name, terms_a_year = excluded.terms_a_year, notes = excluded.notes, reason = excluded.reason, updated_by = excluded.updated_by, updated_at = now();
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('fees', 'profile_set', upper(p_args->>'country'), p_args, auth.uid());
    return public.admin_fee_reader('overview', '{}'::jsonb);
  end if;
  raise exception 'unknown action %', p_action using errcode = '22023';
end $_$;


ALTER FUNCTION "public"."admin_fee_reader"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_fee_rule_control"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_id bigint := nullif(p_args->>'id', '')::bigint; r pipeline.fee_wording_rules%rowtype; v_res jsonb;
begin
  if auth.uid() is null or v_rank < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
  if p_action in ('approve','run','pause','resume') and v_rank < 5 then raise exception 'PIM Operator role or above required to approve or run a rule' using errcode = '42501'; end if;
  if p_action = 'create' then
    if nullif(p_args->>'provider_id', '') is null or not exists (select 1 from catalogue.providers where id = (p_args->>'provider_id')::uuid) then raise exception 'choose the university'; end if;
    if length(btrim(coalesce(p_args->>'phrase', ''))) < 6 then raise exception 'type at least 6 characters of the words that come before the fee'; end if;
    if coalesce(p_args->>'basis', '') not in ('annual','total_indicative','per_semester','per_trimester') then raise exception 'choose the fee period'; end if;
    insert into pipeline.fee_wording_rules(provider_id, label, phrase, basis, url_pattern, note, created_by)
    values ((p_args->>'provider_id')::uuid, coalesce(nullif(btrim(coalesce(p_args->>'label', '')), ''), left(btrim(p_args->>'phrase'), 60)), btrim(p_args->>'phrase'),
            p_args->>'basis', nullif(btrim(coalesce(p_args->>'url_pattern', '')), ''), nullif(btrim(coalesce(p_args->>'note', '')), ''), auth.uid())
    returning * into r;
  else
    select * into r from pipeline.fee_wording_rules where id = v_id;
    if r.id is null then raise exception 'rule not found'; end if;
    if p_action = 'approve' then
      if r.status <> 'draft' then raise exception 'only a draft can be approved'; end if;
      update pipeline.fee_wording_rules set status = 'active', approved_by = auth.uid(), approved_at = now() where id = r.id;
      v_res := security.fee_rule_run_v1(r.id, true, auth.uid());
    elsif p_action = 'run' then
      if r.status <> 'active' then raise exception 'only an active rule can be run'; end if;
      v_res := security.fee_rule_run_v1(r.id, true, auth.uid());
    elsif p_action = 'pause' then update pipeline.fee_wording_rules set status = 'paused' where id = r.id;
    elsif p_action = 'resume' then update pipeline.fee_wording_rules set status = 'active' where id = r.id;
    elsif p_action = 'delete' then
      if r.status <> 'draft' then raise exception 'only a draft can be deleted; pause an approved rule instead'; end if;
      delete from pipeline.fee_wording_rules where id = r.id;
    else raise exception 'unknown action %', p_action; end if;
  end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('fee_rules', p_action, coalesce(r.label, v_id::text), p_args || jsonb_build_object('rule_id', r.id) || coalesce(jsonb_build_object('result', v_res), '{}'::jsonb), auth.uid());
  return public.admin_fee_rules_read() || jsonb_build_object('result', v_res, 'rule_id', r.id);
end $$;


ALTER FUNCTION "public"."admin_fee_rule_control"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_fee_rule_preview"("p_provider_id" "uuid", "p_phrase" "text", "p_url_pattern" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or security.current_role_rank() < 3 then raise exception 'assigned StudySearch role required' using errcode = '42501'; end if;
  if length(btrim(coalesce(p_phrase, ''))) < 6 then raise exception 'type at least 6 characters of the words that come before the fee'; end if;
  return (select jsonb_build_object(
      'would_admit', count(*) filter (where amounts = 1 and not has_fee and not exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = m.course_id and l.field = 'tuition')),
      'ambiguous', count(*) filter (where amounts > 1), 'already_had_fee', count(*) filter (where amounts = 1 and has_fee),
      'amount_range', jsonb_build_object('min', min(amount), 'max', max(amount)),
      'samples', (select coalesce(jsonb_agg(s), '[]'::jsonb) from (
          select jsonb_build_object('course_id', m2.course_id, 'course', coalesce(c.display_title, c.canonical_title), 'code', c.course_code, 'amount', m2.amount,
                 'fee_year', m2.fee_year, 'text', m2.matched_text, 'url', m2.url, 'has_fee', m2.has_fee, 'amounts', m2.amounts) s
            from security.fee_rule_matches(p_provider_id, p_phrase, nullif(btrim(coalesce(p_url_pattern, '')), '')) m2 join catalogue.courses c on c.id = m2.course_id
           order by m2.amounts desc, m2.amount limit 15) z))
    from security.fee_rule_matches(p_provider_id, p_phrase, nullif(btrim(coalesce(p_url_pattern, '')), '')) m);
end $$;


ALTER FUNCTION "public"."admin_fee_rule_preview"("p_provider_id" "uuid", "p_phrase" "text", "p_url_pattern" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_fee_rules_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'assigned StudySearch role required' using errcode = '42501'; end if;
  return jsonb_build_object(
    'can_create', v_rank >= 4, 'can_approve', v_rank >= 5,
    'rules', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'provider_id', r.provider_id, 'provider', coalesce(p.display_name, p.canonical_name),
                'label', r.label, 'phrase', r.phrase, 'basis', r.basis, 'url_pattern', r.url_pattern, 'status', r.status, 'admitted', r.admitted,
                'created_at', r.created_at, 'created_by', cu.email, 'approved_at', r.approved_at, 'approved_by', au.email, 'last_run_at', r.last_run_at, 'note', r.note)
                order by r.status = 'active' desc, r.created_at desc), '[]'::jsonb)
                from pipeline.fee_wording_rules r left join catalogue.providers p on p.id = r.provider_id
                left join auth.users cu on cu.id = r.created_by left join auth.users au on au.id = r.approved_by),
    'suggestions', (select coalesce(jsonb_agg(s order by (s->>'pages')::int desc), '[]'::jsonb) from (
       select jsonb_build_object('provider_id', w.provider_id, 'provider', coalesce(p.display_name, p.canonical_name), 'phrase', w.phrase,
              'pages', count(distinct w.course_id), 'example', min(w.example),
              'has_rule', exists (select 1 from pipeline.fee_wording_rules r where r.provider_id = w.provider_id and lower(r.phrase) = lower(w.phrase))) s
         from (select g.provider_id, g.course_id, security.fee_suggest_phrase(c->>'context', (c->>'amount')::numeric) phrase, left(c->>'context', 240) example
                 from pipeline.coverage_course_pages g
                 join pipeline.provider_priority pp on pp.provider_id = g.provider_id and pp.rank <= 100
                 cross join lateral jsonb_array_elements(coalesce(g.candidates->'fee'->'candidates', '[]'::jsonb)) c
                where g.read_status = 'read' and g.identity_basis in ('cricos_code','manual') and coalesce(g.candidates->'fee'->>'safe', 'false') <> 'true'
                  and coalesce((c->>'domestic')::boolean, false) = false
                  and not exists (select 1 from catalogue.course_fees f where f.course_id = g.course_id and f.fee_type = 'provider_current_tuition' and f.status = 'active')) w
         join catalogue.providers p on p.id = w.provider_id
        where w.phrase is not null
        group by w.provider_id, p.display_name, p.canonical_name, w.phrase
       having count(distinct w.course_id) >= 10
        order by count(distinct w.course_id) desc limit 25) z),
    'recent', (select coalesce(jsonb_agg(jsonb_build_object('at', a.admitted_at, 'rule_id', a.rule_id, 'course_id', a.course_id,
                'course', coalesce(c.display_title, c.canonical_title), 'code', c.course_code, 'amount', a.amount, 'fee_year', a.fee_year, 'basis', a.basis, 'text', a.matched_text)
                order by a.admitted_at desc), '[]'::jsonb)
                from (select * from pipeline.fee_rule_admissions order by admitted_at desc limit 30) a join catalogue.courses c on c.id = a.course_id));
end $$;


ALTER FUNCTION "public"."admin_fee_rules_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_fee_rules_report"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tol numeric := coalesce((p_args->>'tolerance')::numeric, 0.05); v_year int := coalesce((p_args->>'year')::int, extract(year from now())::int); v_out jsonb;
  v_hosts text[] := security.l4_shared_hosts_v1();
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 4 then raise exception 'Operator or above required' using errcode = '42501'; end if;
  with pg as (
    select distinct on (f.course_id) f.course_id, f.amount pa, f.fee_year, f.evidence_id, substring(ea.source_url from '^https?://(?:www\.)?([^/:?#]+)') h
      from catalogue.course_fees f left join pipeline.evidence_artifacts ea on ea.id = f.evidence_id
     where f.fee_type = 'provider_current_tuition' and f.audience = 'international' and f.status = 'active' and f.amount > 0
       and f.basis in ('annual', 'indicative_annual', 'current indicative annual international tuition')
     order by f.course_id, f.fee_year desc nulls last, f.created_at desc),
  cr as (select distinct on (course_id) course_id, amount ca from catalogue.course_fees where fee_type = 'tuition' and audience = 'international' and status = 'active' and basis = 'registered_total_course' and amount > 0 order by course_id, created_at desc),
  j as (
    select c.id course_id, c.display_title, p.id provider_id, p.display_name provider, k.iso_alpha2 country, pg.pa, pg.fee_year,
           cr.ca / greatest(case c.duration_unit when 'weeks' then c.duration_value / 52.0 when 'years' then c.duration_value when 'months' then c.duration_value / 12.0 end, 1) ann,
           exists (select 1 from pipeline.manual_locks m where m.entity = 'course' and m.entity_id = c.id and m.field in ('tuition', 'fee', 'fees')) locked,
           (pg.evidence_id is not null and exists (select 1 from pipeline.evidence_artifacts ea where ea.id = pg.evidence_id)) has_ev,
           (pg.h = any(v_hosts) and not coalesce(pg.h = substring(p.website from '^https?://(?:www\.)?([^/:?#]+)') or pg.h like '%.' || substring(p.website from '^https?://(?:www\.)?([^/:?#]+)'), false)) shared
      from pg join cr using (course_id) join catalogue.courses c on c.id = pg.course_id
      join catalogue.providers p on p.id = c.provider_id left join ref.countries k on k.id = p.country_id
     where c.duration_value > 0 and c.duration_unit in ('weeks', 'years', 'months')),
  m as (select j.*, abs(pa - ann) / ann gap, (abs(pa - ann) / ann > v_tol) differs, (ann > 0 and abs(pa / ann - 0.5) < 0.03) half from j),
  w as (select m.*, (differs and not locked and has_ev and not shared) chg from m)
  select jsonb_build_object(
    'as_at', now(), 'tolerance', v_tol, 'year', v_year, 'rule', 'rule_2',
    'compared', (select count(*) from w),
    'agree', (select count(*) from w where not differs),
    'differ', (select count(*) from w where differs),
    'would_change', (select count(*) from w where chg),
    'suspected_half', (select count(*) from w where chg and half),
    'suspected_half_sample', (select coalesce(jsonb_agg(x), '[]'::jsonb) from (select jsonb_build_object('course_id', course_id, 'title', display_title, 'provider', provider, 'page_fee', pa, 'cricos_per_year', round(ann, 0)) x from w where chg and half order by provider, display_title limit 40) t),
    'protected_by_hand', (select count(*) from w where differs and locked),
    'kept_no_evidence', (select count(*) from w where differs and not locked and not has_ev),
    'kept_other_site', (select count(*) from w where differs and not locked and has_ev and shared),
    'page_higher', (select count(*) from w where chg and pa > ann),
    'page_lower', (select count(*) from w where chg and pa < ann),
    'gap_over_20', (select count(*) from w where chg and gap > 0.2),
    'by_country', (select coalesce(jsonb_agg(x order by x->>'country'), '[]'::jsonb) from (select jsonb_build_object('country', country, 'compared', count(*), 'would_change', count(*) filter (where chg)) x from w group by country) t),
    'by_provider', (select coalesce(jsonb_agg(x), '[]'::jsonb) from (select jsonb_build_object('provider_id', provider_id, 'provider', provider, 'country', country, 'compared', count(*), 'would_change', count(*) filter (where chg)) x from w group by provider_id, provider, country order by count(*) filter (where chg) desc limit 25) t),
    'sample', (select coalesce(jsonb_agg(x), '[]'::jsonb) from (select jsonb_build_object('course_id', course_id, 'title', display_title, 'provider', provider, 'page_fee', pa, 'page_year', fee_year, 'cricos_per_year', round(ann, 0), 'gap', round(gap, 2)) x from w where chg order by gap desc limit 20) t)
  ) into v_out;
  return v_out;
end $$;


ALTER FUNCTION "public"."admin_fee_rules_report"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_field_coverage"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_cc text := upper(nullif(btrim(coalesce(p_args->>'country', '')), ''));
        v_pid uuid := nullif(p_args->>'provider', '')::uuid; v_reason text := btrim(coalesce(p_args->>'reason', '')); v_f pipeline.field_crosscheck_findings%rowtype;
        v_job pipeline.admin_jobs%rowtype; v_ef text; v_actor text; v_id bigint; v_released int := 0; v_r jsonb; v_snap jsonb;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 1 then raise exception 'assigned StudySearch role required' using errcode = '42501'; end if;
  if p_action = 'overview' then
    -- CF-247 W35: every country (no provider filter) answers from the cached snapshot; one university's figures are read live
    v_snap := case when v_pid is null then (select s.payload from pipeline.admin_read_snapshots s where s.key = 'field_coverage') end;
    select * into v_job from pipeline.admin_jobs j where j.kind = 'enrich_fields' and coalesce((j.args->>'standing')::boolean, false) order by j.created_at desc limit 1;
    return jsonb_build_object(
      'register', (select jsonb_agg(jsonb_build_object('field', r.field, 'level', r.level, 'label', r.label, 'group', r.grp, 'reader', r.reader, 'fills', r.fills,
                                                     'target_pct', r.target_pct, 'reason', r.reason, 'updated_at', r.updated_at) order by r.sort)
                     from pipeline.field_register r where r.active),
      -- every course field by country (the hourly coverage build); provider fields counted now
      'courses_by_country', case when v_snap is not null then (select coalesce(jsonb_agg(e), '[]'::jsonb) from jsonb_array_elements(v_snap->'courses_by_country') e where v_cc is null or e->>'country' = v_cc) else (select coalesce(jsonb_agg(jsonb_build_object('country', x.country_code, 'field', x.attribute, 'total', x.total, 'filled', x.filled,
                                                                        'in_queue', x.in_queue, 'not_stated', x.not_stated, 'in_review', x.in_review)), '[]'::jsonb)
                               from (select a.country_code, a.attribute, count(*) total, count(*) filter (where a.state = 'admitted') filled,
                                            count(*) filter (where a.state = 'in_queue') in_queue, count(*) filter (where a.state = 'not_on_page') not_stated,
                                            count(*) filter (where a.state in ('in_review', 'candidate', 'awaiting_l3')) in_review
                                       from pipeline.course_attribute_coverage a
                                      where (v_cc is null or a.country_code = v_cc) and (v_pid is null or a.provider_id = v_pid) group by 1, 2) x) end,
      'providers_by_country', case when v_snap is not null then (select coalesce(jsonb_agg(e), '[]'::jsonb) from jsonb_array_elements(v_snap->'providers_by_country') e where v_cc is null or e->>'country' = v_cc) else (select coalesce(jsonb_agg(jsonb_build_object('country', z.cc, 'field', z.field, 'total', z.total, 'filled', z.filled)), '[]'::jsonb)
                                 from (select p.cc, f.field, count(*) total, count(*) filter (where f.has) filled
                                         from (select p.*, security.coverage_country(p.id) cc from catalogue.providers p
                                                where coalesce(p.lifecycle_status, 'active') = 'active' and exists (select 1 from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active')
                                                  and (v_pid is null or p.id = v_pid)) p
                                         cross join lateral (values
                                           ('p_website', nullif(btrim(p.website), '') is not null),
                                           ('p_address', nullif(btrim(p.address_line1), '') is not null),
                                           ('p_campuses', exists (select 1 from catalogue.campuses k where k.provider_id = p.id)),
                                           ('p_type', p.provider_type_id is not null),
                                           ('p_international', p.enrols_international is not null),
                                           ('p_logo', nullif(btrim(p.logo_url), '') is not null or exists (select 1 from catalogue.provider_assets a where a.provider_id = p.id and a.asset_type = 'logo')),
                                           ('p_contact', nullif(btrim(p.phone), '') is not null or nullif(btrim(p.email), '') is not null),
                                           ('p_scholarships', exists (select 1 from scholarship.scholarships s where s.provider_id = p.id and s.lifecycle_status = 'active')),
                                           ('p_description', nullif(btrim(p.description), '') is not null)) f(field, has)
                                        where v_cc is null or p.cc = v_cc
                                        group by 1, 2) z) end,
      'computed_at', case when v_snap is not null then (v_snap->>'computed_at')::timestamptz else (select max(computed_at) from pipeline.course_attribute_coverage) end,
      'queue', jsonb_build_object(
        'enabled', (select enabled from pipeline.field_gap_queue_control where id = 1),
        'switched', (select jsonb_build_object('reason', reason, 'at', updated_at) from pipeline.field_gap_queue_control where id = 1),
        'schedule', (select j.schedule from cron.job j where j.jobname = 'field-gap-queue'),
        'last_tick', (select jsonb_build_object('at', d.start_time, 'status', d.status, 'message', left(d.return_message, 300)) from cron.job_run_details d join cron.job j on j.jobid = d.jobid
                       where j.jobname = 'field-gap-queue' order by d.start_time desc limit 1),
        'recheck_days', security.pipeline_num_v1('gaps.recheck_days', 60), 'items_per_run', security.pipeline_num_v1('gaps.items_per_run', 30000),
        'reads_per_day', security.pipeline_num_v1('gaps.scraper_reads_per_day', 200),
        'reads_today', (select count(*) from pipeline.field_enrich_items e join pipeline.admin_jobs j on j.id = e.job_id
                         where j.kind = 'enrich_fields' and coalesce((j.args->>'standing')::boolean, false) and 'scraper' = any (e.tried)
                           and e.updated_at >= (date_trunc('day', now() at time zone 'Australia/Melbourne') at time zone 'Australia/Melbourne')),
        'ai_spent_today_usd', case when v_snap is not null then (v_snap->>'ai_spent_today_usd')::numeric else (select x.spent from security.ai_spend_today_v1() x where x.use = 'enrich_fields') end,
        'ai_guard_usd', (select (s.value #>> '{}')::numeric from pipeline.platform_toolset_settings s where s.toolset_key = 'openrouter' and s.key = 'guard_enrich_fields'),
        'job', case when v_job.id is null then null else jsonb_build_object('id', v_job.id, 'state', v_job.state, 'title', v_job.title, 'progress', v_job.progress,
                     'created_at', v_job.created_at, 'finished_at', v_job.finished_at,
                     'by_field', (select jsonb_object_agg(field, s) from (select field, jsonb_object_agg(state, n) s from (
                                    select e.field, e.state, count(*) n from pipeline.field_enrich_items e where e.job_id = v_job.id group by 1, 2) a group by field) b)) end,
        'runs', (select count(*) from pipeline.admin_jobs j where j.kind = 'enrich_fields' and coalesce((j.args->>'standing')::boolean, false)),
        'filled_7d', (select count(*) from pipeline.field_enrich_items e join pipeline.admin_jobs j on j.id = e.job_id
                       where coalesce((j.args->>'standing')::boolean, false) and e.state = 'filled' and e.updated_at > now() - interval '7 days')),
      'crosscheck', (select coalesce(jsonb_agg(jsonb_build_object('field', field, 'state', state, 'n', n)), '[]'::jsonb)
                       from (select x.field, x.state, count(*) n from pipeline.field_crosscheck_findings x
                              where (v_cc is null or security.coverage_country(x.provider_id) = v_cc) and (v_pid is null or x.provider_id = v_pid) group by 1, 2) y),
      'can_decide', v_rank >= 4, 'can_manage', v_rank >= 6,
      'snapshot', case when v_snap is not null then security.admin_read_snapshot_meta_v1('field_coverage') end);
  elsif p_action = 'findings' then
    return jsonb_build_object('items', (select coalesce(jsonb_agg(r), '[]'::jsonb) from (
      select x.id, x.field, x.held_value, x.page_value, x.source, x.quote, x.state, x.found_at, x.course_id, c.canonical_title course, coalesce(p.display_name, p.canonical_name) provider,
             security.coverage_country(x.provider_id) country
        from pipeline.field_crosscheck_findings x join catalogue.courses c on c.id = x.course_id join catalogue.providers p on p.id = x.provider_id
       where x.state = coalesce(nullif(p_args->>'state', ''), 'open') and (nullif(p_args->>'field', '') is null or x.field = p_args->>'field')
         and (v_cc is null or security.coverage_country(x.provider_id) = v_cc) and (v_pid is null or x.provider_id = v_pid)
       order by coalesce(p.display_name, p.canonical_name), c.canonical_title, x.field
       limit least(greatest(coalesce((p_args->>'limit')::int, 50), 1), 200) offset greatest(coalesce((p_args->>'offset')::int, 0), 0)) r));
  elsif p_action = 'finding_decide' then
    if v_rank < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
    select * into v_f from pipeline.field_crosscheck_findings where id = (p_args->>'id')::bigint for update;
    if v_f.id is null or v_f.state <> 'open' then raise exception 'this difference is no longer open'; end if;
    if p_args->>'decision' = 'dismiss' then
      update pipeline.field_crosscheck_findings set state = 'dismissed', decided_at = now(), decided_by = auth.uid(), note = nullif(v_reason, '') where id = v_f.id;
    elsif p_args->>'decision' = 'accept' then
      perform set_config('cf.manual_edit', 'on', true);
      update catalogue.courses c set duration_value = case when v_f.field = 'duration' then (v_f.page_value->>'value')::numeric else c.duration_value end,
             duration_unit = case when v_f.field = 'duration' then v_f.page_value->>'unit' else c.duration_unit end,
             study_level_id = case when v_f.field = 'level' then (v_f.page_value->>'level_id')::uuid else c.study_level_id end,
             delivery_mode = case when v_f.field = 'delivery' then v_f.page_value->>'mode' else c.delivery_mode end, updated_at = now()
       where c.id = v_f.course_id;
      insert into pipeline.manual_locks(entity, entity_id, field, mode, set_by) values ('course', v_f.course_id, v_f.field, 'value', auth.uid())
      on conflict (entity, entity_id, field) do update set mode = 'value', set_by = excluded.set_by, set_at = now();
      update pipeline.field_crosscheck_findings set state = 'accepted', decided_at = now(), decided_by = auth.uid(), note = nullif(v_reason, '') where id = v_f.id;
      insert into search.refresh_requests(requested_by) values ('field cross-check accepted');
    else raise exception 'decision is dismiss or accept'; end if;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('field_crosscheck', p_args->>'decision', v_f.field || ' ' || v_f.course_id, jsonb_build_object('held', v_f.held_value, 'found', v_f.page_value, 'quote', v_f.quote, 'reason', v_reason), auth.uid());
    return jsonb_build_object('id', v_f.id, 'state', case when p_args->>'decision' = 'dismiss' then 'dismissed' else 'accepted' end);
  elsif p_action = 'queue_set' then
    if v_rank < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
    if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
    update pipeline.field_gap_queue_control set enabled = coalesce((p_args->>'enabled')::boolean, enabled), owner = auth.uid(), reason = v_reason, updated_at = now() where id = 1;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('field_gap_queue', case when (p_args->>'enabled')::boolean then 'on' else 'off' end, 'field-gap-queue', jsonb_build_object('reason', v_reason), auth.uid());
    return public.admin_field_coverage('overview', '{}'::jsonb);
  elsif p_action = 'target_set' then
    if v_rank < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
    if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
    update pipeline.field_register set target_pct = (p_args->>'target_pct')::numeric, reason = v_reason, updated_by = auth.uid(), updated_at = now()
     where field = p_args->>'field';
    if not found then raise exception 'unknown field'; end if;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('field_register', 'target', p_args->>'field', jsonb_build_object('target_pct', p_args->'target_pct', 'reason', v_reason), auth.uid());
    return public.admin_field_coverage('overview', '{}'::jsonb);
  elsif p_action = 'stalled' then
    -- CF-247 21 Oct 2026: fields below target that are not moving or are behind, with the cause and the action that resolves it
    return jsonb_build_object('items', (select coalesce(jsonb_agg(x), '[]'::jsonb) from jsonb_array_elements(security.field_stalled_v1()) x
                                         where (v_cc is null or x->>'country' = v_cc) and x->>'reason' is not null),
                              'days', security.pipeline_num_v1('stall.days', 7), 'min_points', security.pipeline_num_v1('stall.min_points', 1),
                              'gap_points', security.pipeline_num_v1('stall.country_gap_points', 30),
                              'history_from', (select min(snapshot_date) from pipeline.field_coverage_daily),
                              'can_fill', v_rank >= 4, 'can_release', v_rank >= 6);
  elsif p_action in ('fill_now', 'release_and_fill') then
    if v_rank < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
    if v_cc is null then raise exception 'choose a country'; end if;
    v_ef := case p_args->>'field' when 'campus_city' then 'campus' when 'p_address' then 'provider_address' else p_args->>'field' end;
    if not exists (select 1 from security.enrich_fields_v1() e where e.field = v_ef) then raise exception 'this field is not filled by Enrich fields'; end if;
    if p_action = 'release_and_fill' then
      if v_rank < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
      if length(v_reason) < 4 then raise exception 'give a reason (kept with each released hold)'; end if;
      v_actor := coalesce((select u.email from auth.users u where u.id = auth.uid()), auth.uid()::text);
      for v_id in select f.id from pipeline.enrichment_flags f
                   where f.entity = 'course' and f.field = v_ef and f.reason_code = 'enrich_no_value' and f.state = 'counting'
                     and security.coverage_country(f.provider_id) = v_cc loop
        perform security.flag_release_v1(v_id, v_actor, 'person', 'Coverage › Stalled fields: ' || v_reason, jsonb_build_object('country', v_cc, 'field', v_ef), false);
        v_released := v_released + 1;
      end loop;
    end if;
    v_r := public.admin_enrich_fields('start', jsonb_build_object('countries', jsonb_build_array(v_cc), 'fields', jsonb_build_array(v_ef), 'ai', true, 'scraper', true,
             'reason', coalesce(nullif(v_reason, ''), 'Coverage › Stalled fields: Fill now')));
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('field_stalled', p_action, v_cc || '.' || v_ef, jsonb_build_object('released', v_released, 'task', v_r, 'reason', v_reason), auth.uid());
    return coalesce(v_r, '{}'::jsonb) || jsonb_build_object('released', v_released);
  elsif p_action = 'wording_list' then
    -- CF-247 21 Oct 2026: a university's own delivery wording (Platform Admin "Keep two, fix reader")
    return jsonb_build_object('items', (select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'provider_id', d.provider_id,
               'provider', coalesce((select coalesce(p.display_name, p.canonical_name) from catalogue.providers p where p.id = d.provider_id), 'Every university'),
               'phrase', d.phrase, 'mode', d.mode, 'active', d.active, 'reason', d.reason, 'set_at', d.set_at) order by d.active desc, d.set_at desc), '[]'::jsonb)
             from pipeline.delivery_wording d), 'can_edit', v_rank >= 5);
  elsif p_action in ('wording_set', 'wording_off') then
    if v_rank < 5 then raise exception 'PIM Admin role or above required' using errcode = '42501'; end if;
    if length(v_reason) < 4 then raise exception 'give a reason (kept with the phrase)'; end if;
    if p_action = 'wording_off' then
      update pipeline.delivery_wording set active = false, reason = v_reason, set_by = auth.uid(), set_at = now() where id = (p_args->>'id')::bigint;
    else
      if length(btrim(coalesce(p_args->>'phrase', ''))) < 3 then raise exception 'give the phrase as the page writes it'; end if;
      insert into pipeline.delivery_wording(provider_id, phrase, mode, reason, set_by)
      values (nullif(p_args->>'provider_id', '')::uuid, btrim(p_args->>'phrase'), p_args->>'mode', v_reason, auth.uid())
      on conflict (provider_id, phrase) do update set mode = excluded.mode, active = true, reason = excluded.reason, set_by = excluded.set_by, set_at = now();
    end if;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('delivery_wording', p_action, coalesce(p_args->>'phrase', p_args->>'id'), jsonb_build_object('mode', p_args->>'mode', 'provider_id', p_args->>'provider_id', 'reason', v_reason), auth.uid());
    return public.admin_field_coverage('wording_list', '{}'::jsonb) || jsonb_build_object('crosscheck', security.field_crosscheck_v1());
  elsif p_action = 'run_now' then
    if v_rank < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
    return security.field_gap_queue_tick_v1();
  end if;
  raise exception 'unknown action %', p_action using errcode = '22023';
end $$;


