CREATE OR REPLACE FUNCTION "public"."admin_firecrawl_credits"("p_hours" integer DEFAULT 24) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 3 then raise exception 'assigned StudySearch role required' using errcode = '42501'; end if;
  return security.firecrawl_credits_report_v1(p_hours) || jsonb_build_object('can_manage', v_rank >= 6,
    -- v2.15.265: today's refusals by university (Melbourne day), most first
    'refused_by_uni', (select coalesce(jsonb_agg(z order by z.n desc, z.name), '[]'::jsonb) from (
        select r.provider_id, coalesce(p.display_name, p.canonical_name) as name, security.coverage_country(r.provider_id) as country,
               security.fc_provider_tier_v1(r.provider_id) as tier, sum(r.n)::int as n,
               jsonb_object_agg(r.grp || ':' || r.reason, r.n) as reasons,
               exists (select 1 from pipeline.firecrawl_search_holds h where h.provider_id = r.provider_id
                        and not exists (select 1 from pipeline.firecrawl_search_resumes x where x.provider_id = h.provider_id and x.resumed_at > h.held_at)) as held
          from pipeline.firecrawl_refusals_by_provider r join catalogue.providers p on p.id = r.provider_id
         where r.day = (now() at time zone 'Australia/Melbourne')::date
         group by r.provider_id, p.display_name, p.canonical_name order by sum(r.n) desc limit 100) z));
end $$;


ALTER FUNCTION "public"."admin_firecrawl_credits"("p_hours" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_firecrawl_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_fc uuid; v_obs record; v_fig record;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 5 then raise exception 'Platform Admin or Operator required' using errcode = '42501'; end if;
  select p.id into v_fc from pipeline.layer2_acquisition_providers p where p.provider_key = 'firecrawl';
  select o.* into v_obs from pipeline.vendor_credit_observations o where o.provider_id = v_fc order by o.observed_at desc limit 1;
  select f.* into v_fig from pipeline.firecrawl_panel_figures f where f.id = 1;
  return jsonb_build_object(
    'can_manage', coalesce(v_rank, 0) >= 6,
    'figures_at', v_fig.refreshed_at,
    'plan', jsonb_build_object('budget', security.layer2_provider_budget_status(v_fc, 1), 'vendor', case when v_obs.provider_id is null then null else jsonb_build_object('observed_at', v_obs.observed_at, 'plan_credits', v_obs.plan_units, 'remaining', v_obs.remaining_units, 'period_start', v_obs.raw->>'billing_period_start', 'period_end', v_obs.period_end) end),
    'targets', coalesce((select jsonb_agg(jsonb_build_object('provider_id', t.provider_id, 'country', t.country, 'name', t.name, 'domain', t.domain, 'rule_match', t.rule_match, 'included', t.included, 'override_reason', t.override_reason, 'rule_reason', t.rule_reason)
                 || coalesce(t.stats, jsonb_build_object('courses', t.courses))
                 || jsonb_build_object('adapter', case when a.provider_id is null then 'none' when a.admit then 'admitting' when a.enabled then 'testing' else 'off' end,
                                       'requests_open', (select count(*) from pipeline.uni_adapter_requests r where r.provider_id = t.provider_id and r.status = 'open'))
               order by (a.provider_id is not null) desc, t.included desc, t.country, coalesce(t.courses, 0) desc)
               from pipeline.firecrawl_target_cache t left join pipeline.uni_adapters a on a.provider_id = t.provider_id where t.name is not null), '[]'::jsonb),
    'backlog', coalesce(v_fig.backlog, '{}'::jsonb),
    'runs', coalesce((select jsonb_agg(to_jsonb(r) - 'settings' order by r.created_at desc) from (select * from pipeline.firecrawl_runs order by created_at desc limit 12) r), '[]'::jsonb),
    'spend', coalesce((select jsonb_agg(jsonb_build_object('purpose', s.purpose, 'target', s.target, 'units', s.units) order by s.units desc) from (
               select u.purpose, coalesce(tc.included, false) target, sum(u.units) units
               from pipeline.coverage_vendor_usage u left join pipeline.firecrawl_target_cache tc on tc.provider_id = u.provider_id
               where u.acquisition_provider_id = v_fc and u.at >= coalesce((v_obs.raw->>'billing_period_start')::timestamptz, date_trunc('month', now()))
               group by 1, 2) s), '[]'::jsonb)
  );
end $$;


ALTER FUNCTION "public"."admin_firecrawl_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_firecrawl_report"("p_since" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_since timestamptz := coalesce(p_since, now() - interval '7 days'); v_fc uuid; v_obs record;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 5 then raise exception 'Platform Admin or Operator required' using errcode = '42501'; end if;
  select p.id into v_fc from pipeline.layer2_acquisition_providers p where p.provider_key = 'firecrawl';
  select o.* into v_obs from pipeline.vendor_credit_observations o where o.provider_id = v_fc order by o.observed_at desc limit 1;
  return jsonb_build_object(
    'since', v_since, 'generated_at', now(),
    'account', case when v_obs.provider_id is null then null else jsonb_build_object('plan_credits', v_obs.plan_units, 'remaining', v_obs.remaining_units, 'period_start', v_obs.raw->>'billing_period_start', 'period_end', v_obs.period_end, 'observed_at', v_obs.observed_at) end,
    'totals', (select jsonb_build_object('calls', count(*), 'succeeded', count(*) filter (where success), 'failed', count(*) filter (where not success), 'credits', coalesce(sum(credits_used), 0),
                 'api_errors', count(*) filter (where http is null or http >= 400), 'timeouts', count(*) filter (where outcome = 'timeout' or error ~* 'timed? ?out'),
                 'rate_limited', count(*) filter (where http = 429), 'stealth_used', count(*) filter (where proxy_used ~* 'stealth|enhanced'), 'median_ms', percentile_disc(0.5) within group (order by duration_ms))
               from pipeline.firecrawl_calls where at >= v_since),
    'by_endpoint', coalesce((select jsonb_agg(x order by x->>'endpoint') from (select jsonb_build_object('endpoint', endpoint, 'use_case', use_case, 'calls', count(*), 'succeeded', count(*) filter (where success), 'credits', coalesce(sum(credits_used), 0)) x
               from pipeline.firecrawl_calls where at >= v_since group by endpoint, use_case) q), '[]'::jsonb),
    'by_outcome', coalesce((select jsonb_object_agg(coalesce(outcome, 'unknown'), n) from (select outcome, count(*) n from pipeline.firecrawl_calls where at >= v_since group by 1) q), '{}'::jsonb),
    'by_site', coalesce((select jsonb_agg(x order by (x->>'failed')::int desc, (x->>'calls')::int desc) from (
        select jsonb_build_object('site', h, 'calls', count(*), 'failed', count(*) filter (where not success),
               'page_statuses', (select jsonb_object_agg(coalesce(s2.ps::text, 'none'), s2.n) from (select page_status ps, count(*) n from pipeline.firecrawl_calls k2 where k2.at >= v_since and regexp_replace(lower(substring(k2.url from '^https?://([^/?#]+)')), '^www\.', '') = q.h group by 1) s2),
               'errors', (select jsonb_agg(distinct left(k3.error, 160)) from pipeline.firecrawl_calls k3 where k3.at >= v_since and k3.error is not null and regexp_replace(lower(substring(k3.url from '^https?://([^/?#]+)')), '^www\.', '') = q.h),
               'proxies', (select jsonb_agg(distinct k4.proxy_used) from pipeline.firecrawl_calls k4 where k4.at >= v_since and k4.proxy_used is not null and regexp_replace(lower(substring(k4.url from '^https?://([^/?#]+)')), '^www\.', '') = q.h),
               'samples', (select jsonb_agg(jsonb_build_object('url', k5.url, 'scrape_id', k5.scrape_id, 'http', k5.http, 'page_status', k5.page_status, 'error', left(k5.error, 200), 'at', k5.at)) from (
                   select * from pipeline.firecrawl_calls k5 where k5.at >= v_since and not k5.success and regexp_replace(lower(substring(k5.url from '^https?://([^/?#]+)')), '^www\.', '') = q.h order by k5.at desc limit 5) k5)) x
        from (select regexp_replace(lower(substring(url from '^https?://([^/?#]+)')), '^www\.', '') h, success from pipeline.firecrawl_calls where at >= v_since and endpoint = 'scrape' and url ~ '^https?://') q
        group by h having count(*) filter (where not success) > 0) z), '[]'::jsonb),
    'errors', coalesce((select jsonb_agg(x order by (x->>'calls')::int desc) from (
        select jsonb_build_object('error', e, 'calls', count(*), 'first_at', min(at), 'last_at', max(at), 'sample_scrape_id', (array_agg(scrape_id order by at desc) filter (where scrape_id is not null))[1], 'sample_url', (array_agg(url order by at desc))[1]) x
        from (select coalesce(left(error, 200), 'HTTP ' || coalesce(http::text, 'none') || ', page status ' || coalesce(page_status::text, 'none')) e, at, scrape_id, url from pipeline.firecrawl_calls where at >= v_since and not success) q group by e) z), '[]'::jsonb)
  );
end $$;


ALTER FUNCTION "public"."admin_firecrawl_report"("p_since" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_firecrawl_search_resume"("p_provider_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(trim(coalesce(p_reason, ''))) < 4 then raise exception 'a reason is required'; end if;
  insert into pipeline.firecrawl_search_resumes(provider_id, reason, set_by) values (p_provider_id, trim(p_reason), auth.uid());
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('firecrawl', 'search_resume', p_provider_id::text, jsonb_build_object('reason', trim(p_reason), 'change', 'CF-247 v2.15.262'), auth.uid());
  return jsonb_build_object('ok', true);
end $$;


ALTER FUNCTION "public"."admin_firecrawl_search_resume"("p_provider_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_firecrawl_write"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', '')); v_uc text := p_args->>'use_case';
        v_run uuid; v_n int; v_settings jsonb; v_cap numeric; v_budget jsonb; v_pid uuid; v_inc boolean; v_r pipeline.firecrawl_runs%rowtype;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action = 'target' then
    v_pid := (p_args->>'provider_id')::uuid;
    if not exists (select 1 from catalogue.providers p where p.id = v_pid) then raise exception 'unknown provider'; end if;
    if p_args->'included' is null or jsonb_typeof(p_args->'included') = 'null' then
      update pipeline.firecrawl_targets set included = (select t.rule_match from security.firecrawl_targets_v1() t where t.provider_id = v_pid), reason = 'back to the rule: ' || v_reason, set_by = auth.uid(), set_at = now() where provider_id = v_pid;
    else
      v_inc := (p_args->>'included')::boolean;
      insert into pipeline.firecrawl_targets(provider_id, included, reason, set_by, set_at) values (v_pid, v_inc, v_reason, auth.uid(), now())
        on conflict (provider_id) do update set included = excluded.included, reason = excluded.reason, set_by = excluded.set_by, set_at = now() where pipeline.firecrawl_targets.provider_id = excluded.provider_id;
    end if;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'firecrawl_target', v_pid::text, jsonb_build_object('included', p_args->'included', 'reason', v_reason), auth.uid());
    -- v2.15.232 (Fix 4): say which domain page-finding will search (none when the provider has no website and no read page yet)
    return jsonb_build_object('ok', true, 'domain', (select t.domain from security.firecrawl_targets_v1() t where t.provider_id = v_pid));
  elsif p_action = 'start' then
    if v_uc not in ('read_page', 'find_page') then raise exception 'use case must be read_page or find_page'; end if;
    if exists (select 1 from pipeline.firecrawl_runs r where r.use_case = v_uc and r.status = 'running') then raise exception 'a run of this use case is still open. Let it finish or stop it first'; end if;
    v_budget := security.layer2_provider_budget_status((select p.id from pipeline.layer2_acquisition_providers p where p.provider_key = 'firecrawl'), 1);
    if not coalesce((v_budget->>'allowed')::boolean, false) then raise exception 'Firecrawl is at its reserve. Check the plan on this page first'; end if;
    select coalesce(jsonb_object_agg(s.key, s.value), '{}'::jsonb) into v_settings from pipeline.platform_toolset_settings s where s.toolset_key = 'firecrawl';
    v_cap := (v_settings->>(case when v_uc = 'read_page' then 'read_credits_per_run' else 'find_credits_per_run' end))::numeric;
    insert into pipeline.firecrawl_runs(use_case, settings, reason, requested_by, credits_cap) values (v_uc, v_settings, v_reason, auth.uid(), v_cap) returning id into v_run;
    insert into pipeline.firecrawl_run_items(run_id, course_id, provider_id, country, url, input)
      select v_run, b.course_id, b.provider_id, b.country, b.url, b.input from (select distinct on (b0.course_id) b0.* from security.firecrawl_backlog_v1(v_uc) b0
             where nullif(p_args->>'provider_id', '') is null or b0.provider_id = (p_args->>'provider_id')::uuid  -- v2.15.232: one provider only, from the adapter builder
             order by b0.course_id) b
      order by b.provider_id, b.course_id;
    get diagnostics v_n = row_count;
    update pipeline.firecrawl_runs set items = v_n, status = case when v_n = 0 then 'done' else 'running' end, finished_at = case when v_n = 0 then now() end where id = v_run;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'firecrawl_run_start', v_uc, jsonb_build_object('run_id', v_run, 'items', v_n, 'credits_cap', v_cap, 'provider_id', p_args->'provider_id', 'reason', v_reason), auth.uid());
    if v_n > 0 then perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'fc_run', 'run_id', v_run)); end if;
    return jsonb_build_object('ok', true, 'run_id', v_run, 'items', v_n, 'credits_cap', v_cap);
  elsif p_action in ('stop', 'continue') then
    select * into v_r from pipeline.firecrawl_runs where id = (p_args->>'run_id')::uuid;
    if v_r.id is null then raise exception 'unknown run'; end if;
    if p_action = 'stop' then
      update pipeline.firecrawl_runs set status = 'stopped', finished_at = now() where id = v_r.id and status = 'running';
    else
      if v_r.status not in ('running', 'stopped_credit_cap', 'stopped_plan_reserve', 'stopped') then raise exception 'only an open or stopped run can be continued'; end if;
      if p_args ? 'add_credits' then update pipeline.firecrawl_runs set credits_cap = credits_cap + greatest((p_args->>'add_credits')::numeric, 0) where id = v_r.id; end if;
      update pipeline.firecrawl_runs set status = 'running', finished_at = null where id = v_r.id;
      perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'fc_run', 'run_id', v_r.id));
    end if;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'firecrawl_run_' || p_action, v_r.id::text, jsonb_build_object('add_credits', p_args->'add_credits', 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true);
  end if;
  raise exception 'unknown action';
end $$;


ALTER FUNCTION "public"."admin_firecrawl_write"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_flags"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int; v_can boolean; v_actor text; v_reason text; v_id bigint; v_out jsonb := '[]'::jsonb; v_r jsonb; v_lim int; v_off int;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode = '42501'; end if;
  v_rank := security.current_role_rank();
  if v_rank < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  v_can := v_rank >= security.pipeline_num_v1('flag.manage_min_rank', 6)::int;
  v_actor := coalesce((select u.email from auth.users u where u.id = auth.uid()), auth.uid()::text);
  v_lim := least(greatest(coalesce((p_args->>'limit')::int, 50), 1), 200); v_off := greatest(coalesce((p_args->>'offset')::int, 0), 0);
  if p_action = 'summary' then
    return jsonb_build_object('can_change', v_can,
      'release_codes', case when v_can then '["*"]'::jsonb when v_rank >= security.pipeline_num_v1('flag.course_pages_release_min_rank', 4)::int then '["course_pages_not_found"]'::jsonb else '[]'::jsonb end,
      'by_reason', (select coalesce(jsonb_agg(z order by z.held desc, z.reason_code), '[]'::jsonb) from (
          select f.entity, f.reason_code, count(*) filter (where f.state = 'raised') held, count(*) filter (where f.state = 'counting') counting,
                 count(*) filter (where f.state = 'released') released, count(*) filter (where f.state = 'raised' and f.raised_by_kind = 'person') by_person,
                 min(f.next_check_at) filter (where f.state = 'raised') next_check
            from pipeline.enrichment_flags f group by 1, 2) z),
      'last_24h', (select jsonb_object_agg(e.action, e.n) from (select action, count(*) n from pipeline.enrichment_flag_events where at > now() - interval '24 hours' group by 1) e));
  elsif p_action = 'list' then
    return (with x as (
      select f.*, coalesce(p.display_name, p.canonical_name, pp.canonical_name) provider_name, coalesce(c.display_title, c.canonical_title) course_title, count(*) over () total
        from pipeline.enrichment_flags f
        left join catalogue.providers p on f.entity = 'provider' and p.id = f.provider_id
        left join catalogue.courses c on f.entity = 'course' and c.id::text = f.entity_key
        left join catalogue.providers pp on pp.id = coalesce(f.provider_id, c.provider_id)
       where (nullif(p_args->>'state', '') is null or f.state = p_args->>'state')
         and (nullif(p_args->>'entity', '') is null or f.entity = p_args->>'entity')
         and (nullif(p_args->>'reason_code', '') is null or f.reason_code = p_args->>'reason_code')
         and (nullif(p_args->>'q', '') is null or coalesce(p.canonical_name, pp.canonical_name, '') ilike '%' || (p_args->>'q') || '%' or coalesce(c.display_title, c.canonical_title, '') ilike '%' || (p_args->>'q') || '%' or f.entity_key ilike '%' || (p_args->>'q') || '%')
       order by f.updated_at desc, f.id desc limit v_lim offset v_off)
      select jsonb_build_object('can_change', v_can, 'total', coalesce(max(x.total), 0), 'items', coalesce(jsonb_agg(jsonb_build_object(
        'id', x.id, 'entity', x.entity, 'entity_key', x.entity_key, 'provider_id', x.provider_id, 'provider_name', x.provider_name, 'course_title', x.course_title,
        'field', x.field, 'reason_code', x.reason_code, 'reason', x.reason, 'kind', x.kind, 'state', x.state, 'tries', x.tries, 'checks', x.checks,
        'raised_by', x.source, 'raised_by_kind', x.raised_by_kind, 'flagged_at', x.flagged_at, 'next_check_at', x.next_check_at,
        'released_at', x.released_at, 'released_by', x.released_by, 'release_kind', x.release_kind, 'release_reason', x.release_reason,
        -- 22 Oct 2026 (Platform Admin 08:12): the toolset used before the flag
        'tools', case when x.entity in ('provider', 'course') and x.provider_id is not null
                      then security.flag_tool_summary_v1(x.provider_id, case when x.entity = 'course' and x.entity_key ~ '^[0-9a-f-]{36}$' then x.entity_key::uuid end) end) order by x.updated_at desc, x.id desc), '[]'::jsonb)) from x);
  elsif p_action = 'events' then
    v_id := (p_args->>'id')::bigint;
    return jsonb_build_object('flag', (select to_jsonb(f) from pipeline.enrichment_flags f where f.id = v_id),
      'tools', (select security.flag_tool_summary_v1(f.provider_id, case when f.entity = 'course' and f.entity_key ~ '^[0-9a-f-]{36}$' then f.entity_key::uuid end)
                  from pipeline.enrichment_flags f where f.id = v_id and f.entity in ('provider', 'course') and f.provider_id is not null),
      'events', (select coalesce(jsonb_agg(to_jsonb(e) - 'flag_id' order by e.at desc, e.id desc), '[]'::jsonb) from pipeline.enrichment_flag_events e where e.flag_id = v_id));
  elsif p_action in ('release', 'raise') then
    if not v_can and not (p_action = 'release' and v_rank >= security.pipeline_num_v1('flag.course_pages_release_min_rank', 4)::int  -- CF-247 20 Oct 2026: operators release "course pages not found"
        and not exists (select 1 from jsonb_array_elements_text(coalesce(p_args->'ids', '[]'::jsonb)) i join pipeline.enrichment_flags x on x.id = i::bigint where x.reason_code <> 'course_pages_not_found')) then raise exception 'your role cannot change flags' using errcode = '42501'; end if;
    v_reason := btrim(coalesce(p_args->>'reason', ''));
    if length(v_reason) < 4 then raise exception 'give a reason (it is kept with the flag)'; end if;
    if p_action = 'release' then
      for v_id in select (jsonb_array_elements_text(coalesce(p_args->'ids', '[]'::jsonb)))::bigint loop
        v_r := security.flag_release_v1(v_id, v_actor, 'person', v_reason, jsonb_build_object('user_id', auth.uid()), false);
        if v_r is not null then v_out := v_out || v_r; end if;
      end loop;
      return jsonb_build_object('released', jsonb_array_length(v_out), 'items', v_out);
    end if;
    if p_args->>'entity' = 'provider' then
      if not exists (select 1 from catalogue.providers where id = (p_args->>'key')::uuid) then raise exception 'provider not found'; end if;
      v_r := security.flag_raise_v1('provider', p_args->>'key', (p_args->>'key')::uuid, '', 'manual_hold', v_reason, 'hard', v_actor, 'person', jsonb_build_object('user_id', auth.uid()), null, null);
    elsif p_args->>'entity' = 'job' then
      if not exists (select 1 from cron.job where jobname = p_args->>'key') then raise exception 'job not found'; end if;
      perform cron.alter_job((select jobid from cron.job where jobname = p_args->>'key'), active := false);
      v_r := security.flag_raise_v1('job', p_args->>'key', null, '', 'manual_hold', v_reason, 'hard', v_actor, 'person', jsonb_build_object('user_id', auth.uid()), null, null);
    else
      raise exception 'a person can hold a provider or a job';
    end if;
    return v_r;
  elsif p_action = 'targets' then
    return jsonb_build_object(
      'providers', (select coalesce(jsonb_agg(jsonb_build_object('key', p.id, 'label', p.canonical_name) order by p.canonical_name), '[]'::jsonb)
                      from (select id, canonical_name from catalogue.providers where canonical_name ilike '%' || coalesce(p_args->>'q', '') || '%' order by canonical_name limit 10) p),
      'jobs', (select coalesce(jsonb_agg(jsonb_build_object('key', j.jobname, 'label', j.jobname) order by j.jobname), '[]'::jsonb)
                 from (select jobname from cron.job where jobname ilike '%' || coalesce(p_args->>'q', '') || '%' order by jobname limit 10) j));
  end if;
  raise exception 'unknown action %', p_action;
end $_$;


ALTER FUNCTION "public"."admin_flags"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_gap_causes"("p_country" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_at timestamptz; v_prev timestamptz;
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  select max(at) into v_at from pipeline.gap_cause_snapshots;
  select max(at) into v_prev from pipeline.gap_cause_snapshots where at < v_at;
  return jsonb_build_object('at', v_at, 'previous', v_prev, 'run', security.gap_causes_run_meta_v1(v_at),
    'countries', (select coalesce(jsonb_agg(distinct s.country_code), '[]'::jsonb) from pipeline.gap_cause_snapshots s where s.at = v_at),
    'rows', (select coalesce(jsonb_agg(jsonb_build_object('country', s.country_code, 'attribute', s.attribute, 'cause', s.cause, 'action', s.action, 'automatic', s.automatic,
                     'courses', s.courses, 'change', s.courses - coalesce(p.courses, 0)) order by s.country_code, s.attribute, s.courses desc), '[]'::jsonb)
               from pipeline.gap_cause_snapshots s
               left join pipeline.gap_cause_snapshots p on p.at = v_prev and p.country_code = s.country_code and p.attribute = s.attribute and p.cause = s.cause
              where s.at = v_at and (p_country is null or s.country_code = upper(p_country))));
end $$;


ALTER FUNCTION "public"."admin_gap_causes"("p_country" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_governed_action"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  c_code constant text := 'aer_pr_a_recovery_close';
  c_rmit constant text := '8e1adb6c-e069-43db-9584-bd054255e702';
  c_scope_closed constant jsonb := '["9d22a19e-c3f7-4012-b738-17bc0b481e7f", "1719c3ba-1ddf-483e-935e-c750124ba99c"]';
  v_snap jsonb; v_hash text; v_mins int := security.pipeline_num_v1('governed.approval_minutes', 15)::int; v_max int := security.pipeline_num_v1('governed.max_attempts', 3)::int;
  v_key text; v_prev pipeline.admin_control_events%rowtype; v_job pipeline.admin_jobs%rowtype; v_id uuid := gen_random_uuid(); v_ev bigint;
  v_dry jsonb; v_post jsonb; v_failed int; v_reason text := btrim(coalesce(p_args->>'reason', ''));
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if p_action not in ('read', 'preview', 'approve') then raise exception 'unknown request %', p_action; end if;
  -- allowlist: one action, fixed parameters; no SQL text is ever taken from the request
  if p_action <> 'read' and coalesce(p_args->>'action', '') <> c_code then raise exception 'not an allowed action'; end if;

  select count(*) into v_failed from pipeline.admin_jobs where kind = 'governed_action' and args->>'action' = c_code and state = 'failed';
  if p_action = 'read' then
    select * into v_job from pipeline.admin_jobs where kind = 'governed_action' and args->>'action' = c_code and state = 'done' order by finished_at desc limit 1;
    return jsonb_build_object('actions', jsonb_build_array(jsonb_build_object('action', c_code, 'label', 'Close the AER PR A recovery',
      'what', 'Removes RMIT from the entry-requirements reading scope, restoring UTS and WSU, after the six recovery runs settled. Admits nothing; the proposed rows stay in Layer 4 review.',
      'decision', 'Decision 268', 'done', v_job.id is not null, 'paused', v_failed >= v_max, 'failed_attempts', v_failed, 'max_attempts', v_max)),
      'snapshot', security.governed_aer_close_snapshot_v1(), 'last', case when v_job.id is null then null else to_jsonb(v_job) end,
      'history', (select coalesce(jsonb_agg(jsonb_build_object('id', j.id, 'state', j.state, 'at', j.finished_at, 'reason', j.reason, 'result', j.result) order by j.created_at desc), '[]'::jsonb)
                    from pipeline.admin_jobs j where j.kind = 'governed_action' and j.args->>'action' = c_code));
  end if;

  if p_action = 'preview' then
    v_snap := security.governed_aer_close_snapshot_v1();
    v_hash := md5(v_snap::text);
    -- the live dry run: the action's own steps, then rolled back
    begin
      update pipeline.platform_toolset_settings set value = c_scope_closed where toolset_key = 'pipeline' and key = 'entry.providers';
      v_dry := jsonb_build_object('scope_after', (select value from pipeline.platform_toolset_settings where toolset_key = 'pipeline' and key = 'entry.providers'),
                                  'rmit_in_scope_after', security.entry_matrix_enabled_v1(c_rmit::uuid));
      raise exception using errcode = 'P0001', message = 'governed dry run', detail = v_dry::text;
    exception when others then
      if sqlerrm = 'governed dry run' then
        get stacked diagnostics v_key = pg_exception_detail; v_dry := v_key::jsonb || jsonb_build_object('ok', true, 'rolled_back', true);
      else v_dry := jsonb_build_object('ok', false, 'error', left(sqlerrm, 300)); end if;
    end;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('governed_actions', 'preview', c_code, jsonb_build_object('action_hash', v_hash, 'ok', (v_snap->>'ok')::boolean and coalesce((v_dry->>'ok')::boolean, false),
              'expires_at', now() + make_interval(mins => v_mins), 'dry_run', v_dry), auth.uid())
    returning id into v_ev;
    return jsonb_build_object('action', c_code, 'preview_id', v_ev, 'action_hash', v_hash, 'expires_at', now() + make_interval(mins => v_mins),
      'ok', (v_snap->>'ok')::boolean and coalesce((v_dry->>'ok')::boolean, false) and v_failed < v_max, 'paused', v_failed >= v_max,
      'snapshot', v_snap, 'dry_run', v_dry,
      'already_done', exists (select 1 from pipeline.admin_jobs where kind = 'governed_action' and args->>'action' = c_code and state = 'done'));
  end if;

  -- approve: one at a time per action; a repeated click or retry with the same key returns the first result and runs nothing
  perform pg_advisory_xact_lock(hashtext('governed_action:' || c_code));
  v_key := btrim(coalesce(p_args->>'idempotency_key', ''));
  if v_key !~ '^[0-9a-f-]{36}$' then raise exception 'an idempotency key is required'; end if;
  select * into v_job from pipeline.admin_jobs where kind = 'governed_action' and args->>'idempotency_key' = v_key;
  if v_job.id is not null then return jsonb_build_object('repeated', true, 'id', v_job.id, 'state', v_job.state, 'result', v_job.result); end if;
  if length(v_reason) < 5 then raise exception 'give a reason (kept in the log)'; end if;

  select * into v_job from pipeline.admin_jobs where kind = 'governed_action' and args->>'action' = c_code and state = 'done' limit 1;
  select * into v_prev from pipeline.admin_control_events where id = nullif(p_args->>'preview_id', '')::bigint and area = 'governed_actions' and action = 'preview' and target = c_code;
  v_snap := security.governed_aer_close_snapshot_v1();
  v_hash := md5(v_snap::text);
  -- refusals: recorded, nothing changed
  if v_job.id is not null or v_failed >= v_max or v_prev.id is null or v_prev.actor is distinct from auth.uid()
     or now() > (v_prev.detail->>'expires_at')::timestamptz or v_prev.detail->>'action_hash' is distinct from p_args->>'action_hash'
     or v_hash is distinct from p_args->>'action_hash' or not (v_snap->>'ok')::boolean then
    v_post := jsonb_build_object('refused', true, 'why', case
      when v_job.id is not null then 'already done (task ' || v_job.id || ')'
      when v_failed >= v_max then 'paused after ' || v_failed || ' failed attempts'
      when v_prev.id is null or v_prev.actor is distinct from auth.uid() then 'no preview of yours to approve'
      when now() > (v_prev.detail->>'expires_at')::timestamptz then 'the preview has expired; preview again'
      when v_prev.detail->>'action_hash' is distinct from p_args->>'action_hash' then 'the approval does not match the preview'
      when v_hash is distinct from p_args->>'action_hash' then 'the live state changed since the preview; preview again'
      else 'a precondition failed' end, 'snapshot', v_snap);
    insert into pipeline.admin_jobs(id, kind, lane, state, title, args, result, requested_by, reason, created_at, started_at, updated_at, finished_at)
    values (v_id, 'governed_action', 'governed', 'cancelled', 'Close the AER PR A recovery (refused)', jsonb_build_object('action', c_code, 'idempotency_key', v_key, 'action_hash', p_args->>'action_hash', 'preview_id', v_prev.id),
            v_post, auth.uid(), v_reason, now(), now(), now(), now());
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('governed_actions', 'refused', c_code, jsonb_build_object('task', v_id, 'why', v_post->>'why'), auth.uid());
    return jsonb_build_object('id', v_id, 'state', 'cancelled') || v_post;
  end if;

  -- run once: the action's steps and its post-checks together; any failure leaves nothing changed and is recorded
  begin
    update pipeline.platform_toolset_settings set value = c_scope_closed, updated_by = auth.uid(), updated_at = now(),
           reason = 'Governed action ' || c_code || ' (Decision 268): ' || left(v_reason, 300)
     where toolset_key = 'pipeline' and key = 'entry.providers';
    v_post := jsonb_build_object(
      'scope_restored', (select value from pipeline.platform_toolset_settings where toolset_key = 'pipeline' and key = 'entry.providers') = c_scope_closed,
      'rmit_out_of_scope', not security.entry_matrix_enabled_v1(c_rmit::uuid),
      'uts_wsu_in_scope', security.entry_matrix_enabled_v1('9d22a19e-c3f7-4012-b738-17bc0b481e7f') and security.entry_matrix_enabled_v1('1719c3ba-1ddf-483e-935e-c750124ba99c'),
      'counts_unchanged', (security.governed_aer_close_snapshot_v1()->'counts') = (v_snap->'counts'),
      'runs_unchanged', (security.governed_aer_close_snapshot_v1()->'runs') = (v_snap->'runs'));
    if not ((v_post->>'scope_restored')::boolean and (v_post->>'rmit_out_of_scope')::boolean and (v_post->>'uts_wsu_in_scope')::boolean
            and (v_post->>'counts_unchanged')::boolean and (v_post->>'runs_unchanged')::boolean) then
      raise exception 'post-check failed: %', v_post;
    end if;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('governed_actions', 'executed', c_code, jsonb_build_object('task', v_id, 'action_hash', v_hash, 'preview_id', v_prev.id, 'post_checks', v_post,
              'scope_before', v_snap->'scope'->'now', 'scope_after', c_scope_closed, 'counts', v_snap->'counts', 'cost_usd_since_open', v_snap->'cost_usd_since_open'), auth.uid())
    returning id into v_ev;
    insert into pipeline.admin_jobs(id, kind, lane, state, title, args, result, requested_by, reason, created_at, started_at, updated_at, finished_at)
    values (v_id, 'governed_action', 'governed', 'done', 'Close the AER PR A recovery', jsonb_build_object('action', c_code, 'idempotency_key', v_key, 'action_hash', v_hash, 'preview_id', v_prev.id),
            jsonb_build_object('post_checks', v_post, 'audit_event', v_ev, 'before', v_snap, 'scope_after', c_scope_closed), auth.uid(), v_reason, now(), now(), now(), now());
    return jsonb_build_object('id', v_id, 'state', 'done', 'audit_event', v_ev, 'post_checks', v_post, 'scope_after', c_scope_closed);
  exception when others then
    insert into pipeline.admin_jobs(id, kind, lane, state, title, args, result, error, requested_by, reason, created_at, started_at, updated_at, finished_at)
    values (v_id, 'governed_action', 'governed', 'failed', 'Close the AER PR A recovery (failed; nothing changed)', jsonb_build_object('action', c_code, 'idempotency_key', v_key, 'action_hash', v_hash, 'preview_id', v_prev.id),
            jsonb_build_object('nothing_changed', true, 'attempt', v_failed + 1, 'paused_after', v_max), left(sqlerrm, 500), auth.uid(), v_reason, now(), now(), now(), now());
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('governed_actions', 'failed', c_code, jsonb_build_object('task', v_id, 'error', left(sqlerrm, 300), 'attempt', v_failed + 1), auth.uid());
    return jsonb_build_object('id', v_id, 'state', 'failed', 'error', left(sqlerrm, 300), 'nothing_changed', true, 'paused', v_failed + 1 >= v_max);
  end;
end $_$;


ALTER FUNCTION "public"."admin_governed_action"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_governed_action"("p_action" "text", "p_args" "jsonb") IS 'CF-247 Decision 268: governed actions run from the admin UI (Platform Admin only). One allowlisted action: close the AER PR A recovery.';



CREATE OR REPLACE FUNCTION "public"."admin_host_pages"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', '')); v_pid uuid := nullif(p_args->>'provider_id', '')::uuid; v_cid uuid := nullif(p_args->>'course_id', '')::uuid; v_res jsonb; v_h pipeline.course_host_pages%rowtype;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 4 then raise exception 'Layer 4 reviewer or Platform Admin required' using errcode = '42501'; end if;
  if p_action = 'read' then
    return coalesce((select jsonb_agg(jsonb_build_object('course_id', h.course_id, 'course', ch.canonical_title, 'code', ch.course_code, 'link_type', h.link_type, 'host_course_id', h.host_course_id, 'host', hc.canonical_title,
                     'host_url', h.host_url, 'basis', h.basis, 'printed', h.printed, 'register_check', h.register_check, 'check_detail', h.check_detail, 'active', h.active, 'set_by', h.set_by, 'applied_at', h.applied_at, 'set_at', h.set_at) order by h.link_type, ch.canonical_title)
                     from pipeline.course_host_pages h join catalogue.courses ch on ch.id = h.course_id left join catalogue.courses hc on hc.id = h.host_course_id where h.provider_id = v_pid), '[]'::jsonb);
  end if;
  if coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action = 'detect' then
    v_res := security.host_pages_detect_v1(v_pid);
  elsif p_action = 'apply' then
    v_res := security.host_pages_apply_v1(v_pid);
  elsif p_action = 'confirm_page' then
    select * into v_h from pipeline.course_host_pages h where h.course_id = v_cid;
    if v_h.course_id is null or v_h.link_type = 'no_public_page' then raise exception 'no page to confirm for this course'; end if;
    update pipeline.coverage_course_pages pg set read_status = 'read', identity_basis = 'host_page' where pg.course_id = v_cid and pg.url = v_h.host_url and pg.read_status = 'identity_mismatch';
    update pipeline.course_host_pages set set_by = 'hand', reason = v_reason, applied_at = now(), set_at = now() where course_id = v_cid;
    v_res := jsonb_build_object('ok', true);
  elsif p_action = 'no_page' then
    v_res := public.admin_course_edit(v_cid, 'remove_official_url', jsonb_build_object('reason', v_reason));
    update pipeline.course_host_pages set set_by = 'hand', reason = v_reason, applied_at = now(), set_at = now() where course_id = v_cid;
    v_res := jsonb_build_object('ok', true);
  elsif p_action in ('off', 'on') then
    update pipeline.course_host_pages set active = (p_action = 'on'), set_by = 'hand', reason = v_reason, set_at = now() where course_id = v_cid;
    v_res := jsonb_build_object('ok', true);
  else
    raise exception 'unknown action';
  end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'host_pages_' || p_action, coalesce(v_pid::text, v_cid::text), jsonb_build_object('result', v_res, 'args', p_args), auth.uid());
  return v_res;
end $$;


ALTER FUNCTION "public"."admin_host_pages"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_intake_cohort_prepare_v1"("p_scope" "text", "p_size" integer, "p_reason" "text", "p_preview_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare tok jsonb; body jsonb; sig text; s jsonb; c uuid; existing pipeline.intake_ui_requests%rowtype;
begin
 if auth.uid() is null or security.current_role_rank()<greatest(coalesce((select control_rank from pipeline.automation_catalogue where jobname='intake-dates-apply'),6),3) then
 raise exception 'your role cannot prepare this job' using errcode='42501'; end if;
 if coalesce(btrim(p_reason),'')='' then raise exception 'an audited reason is required'; end if;
 tok:=p_preview_token::jsonb; body:=tok->'body';
 select encode(extensions.hmac(body::text,secret,'sha256'),'hex') into sig from pipeline.intake_ui_signing_key;
 if sig is null or tok->>'signature' is distinct from sig or body->>'requester' is distinct from auth.uid()::text or body->>'scope' is distinct from p_scope
 or (body->>'size')::integer is distinct from p_size then raise exception 'invalid or foreign preview'; end if;
 -- Serialise preparation of the same preview; this is not the intake job's lock.
 perform pg_advisory_xact_lock(hashtextextended(p_preview_token,0)); -- fixed: token-level duplicate preparation guard
 select * into existing from pipeline.intake_ui_requests where preview_token=p_preview_token;
 if found then
 if existing.reason<>btrim(p_reason) then raise exception 'fixed cohort reason cannot change'; end if;
 return jsonb_build_object('cohort_id',existing.cohort_id,'preview_token',p_preview_token,'request_key',existing.request_key,'reason',existing.reason); end if;
 if (body->>'expires_at')::timestamptz<clock_timestamp() then raise exception 'preview expired; preview again'; end if;
 s:=security.intake_ui_selection_v1(p_scope,p_size);
 if encode(extensions.digest(s::text,'sha256'),'hex') is distinct from body->>'fingerprint' then raise exception 'selection or evidence changed; preview again'; end if;
 if jsonb_array_length(s->'courses')=0 then raise exception 'no eligible courses: inspect missing evidence and current intake rules'; end if;
 insert into pipeline.run_now_cohorts(job,label,selection_rule,selection,requested_by,reason)
 values('intake-dates-apply','Operator intake cohort',s->>'rule',s-'courses',auth.uid(),btrim(p_reason)) returning id into c;
 insert into pipeline.run_now_cohort_members(cohort_id,course_id,provider_id,pick,pattern,fills,evidence)
 select c,(m->>'course_id')::uuid,(m->>'provider_id')::uuid,(m->>'pick')::integer,m->>'pattern',array(select jsonb_array_elements_text(m->'fills')),m->'at_selection'
 from jsonb_array_elements(s->'courses') m;
 insert into pipeline.intake_ui_requests(cohort_id,requested_by,preview_token,scope,size,reason)
 values(c,auth.uid(),p_preview_token,p_scope,p_size,btrim(p_reason)) returning * into existing;
 insert into pipeline.admin_control_events(area,action,target,detail,actor)
 values('run_now','cohort_prepared','intake-dates-apply',jsonb_build_object('cohort_id',c,'selection',s-'courses'),auth.uid());
 return jsonb_build_object('cohort_id',c,'preview_token',p_preview_token,'request_key',existing.request_key,'reason',existing.reason);
end $$;


ALTER FUNCTION "public"."admin_intake_cohort_prepare_v1"("p_scope" "text", "p_size" integer, "p_reason" "text", "p_preview_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_intake_date_withdraw_v1"("p_intake_ids" "uuid"[], "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb := '[]'::jsonb; x uuid; r jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if coalesce(array_length(p_intake_ids, 1), 0) = 0 or array_length(p_intake_ids, 1) > 50 then raise exception 'name 1 to 50 intakes' using errcode = '22023'; end if;  -- fixed: a reviewed list, not a bulk tool
  -- every named intake first, then each course's intakes held once (the hold would otherwise refuse a second intake of the same course)
  foreach x in array p_intake_ids loop
    r := security.intake_date_withdraw_v1(x, p_reason, auth.uid()::text, false); v := v || r;
  end loop;
  insert into pipeline.manual_locks(entity, entity_id, field, mode, set_by, set_at)
  select distinct 'course', (e->>'course_id')::uuid, 'intakes', 'value', auth.uid(), now() from jsonb_array_elements(v) e where (e->>'withdrawn')::boolean
  on conflict (entity, entity_id, field) do nothing;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('intake_dates', 'withdraw', 'catalogue.course_intakes', jsonb_build_object('reason', p_reason, 'results', v), auth.uid());
  return jsonb_build_object('results', v, 'withdrawn', (select count(*) from jsonb_array_elements(v) e where (e->>'withdrawn')::boolean));
end $$;


ALTER FUNCTION "public"."admin_intake_date_withdraw_v1"("p_intake_ids" "uuid"[], "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_intake_date_withdraw_v1"("p_intake_ids" "uuid"[], "p_reason" "text") IS 'CF-247 (direction 5 Nov 2026 15:50 §1): the Platform Admin''s governed withdrawal of intake values the intake-dates process admitted (security.intake_date_withdraw_v1), with a reason, recorded in the admin control log.';



CREATE OR REPLACE FUNCTION "public"."admin_intake_progress_v1"("p_view" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "statement_timeout" TO '20s'
    AS $$
declare v_rank int := security.current_role_rank(); v_since timestamptz; v_until timestamptz := now(); v_window text := coalesce(p_args->>'window', 'latest'); v_status jsonb;
        v_runs int := security.pipeline_num_v1('intake_progress.runs_listed', 24)::int;
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'Operations read permission required' using errcode = '42501'; end if;
  if p_view = 'status' then
    v_status := security.intake_progress_status_v1(v_rank);
    return v_status || jsonb_build_object('alerts', security.intake_progress_alerts_v1(v_status), 'rank', v_rank);
  elsif p_view in ('window', 'runs') then
    if v_window = 'latest' then
      select max(e.run_at) into v_since from pipeline.course_intake_date_events e where e.outcome <> 'withdrawn';
      v_until := v_since;
    elsif v_window in ('24h', '7d', '30d') then
      v_since := now() - make_interval(days => case v_window when '24h' then 1 when '7d' then 7 else 30 end);  -- fixed: the windows named by decision 16:36 §3D
    else raise exception 'unknown window %', v_window using errcode = '22023';
    end if;
    if v_since is null then return jsonb_build_object('window', v_window, 'empty', true, 'universities', security.intake_progress_universities_v1(now(), now())); end if;
    if p_view = 'runs' then return security.intake_progress_runs_v1(v_since, v_until, v_runs); end if;
    return jsonb_build_object('window', v_window, 'since', v_since, 'until', v_until, 'funnel', security.intake_progress_window_v1(v_since, v_until),
      'universities', security.intake_progress_universities_v1(v_since, v_until), 'runs', security.intake_progress_runs_v1(v_since, v_until, v_runs));
  elsif p_view = 'failures' then
    return security.intake_progress_failures_v1(nullif(p_args->>'class', ''), nullif(p_args->>'provider_id', '')::uuid,
                                                security.pipeline_num_v1('intake_progress.failure_rows', 50)::int);
  elsif p_view = 'observations' then
    -- decision 20:03: the history of the intake chain is the generic observer's readings (pipeline.progress_observations, job first-run-verify)
    return (select coalesce(jsonb_agg(jsonb_build_object('transition', o.transition_key, 'measured_at', o.measured_at, 'zero_reason', o.zero_reason, 'stalled', o.stalled,
                     'eligible', o.measures->'eligible', 'processed', o.measures->'processed', 'created', o.measures->'created', 'admitted', o.measures->'admitted',
                     'published', o.measures->'published') order by o.measured_at desc, o.transition_key), '[]'::jsonb)
              from (select o.* from pipeline.progress_observations o where o.transition_key in ('intake_selection', 'intake_admission', 'intake_publication')
                     order by o.measured_at desc limit security.pipeline_num_v1('process_results.history_rows', 30)::int * 3) o);
  end if;
  raise exception 'unknown view %', p_view using errcode = '22023';
end $$;


ALTER FUNCTION "public"."admin_intake_progress_v1"("p_view" "text", "p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_intake_progress_v1"("p_view" "text", "p_args" "jsonb") IS 'CF-247 Automation Progress (decision 5 Nov 2026 16:36 §3-§8): Layer 2/3 Operations › Process results › Automation progress. Views status, window (latest, 24h, 7d, 30d), runs, failures (class, provider_id) and observations (the generic progress observer''s readings of the intake chain), from persisted records only; Operations read (rank 3) and above. Read only: Pause/Resume is the existing public.admin_automation_control.';



CREATE OR REPLACE FUNCTION "public"."admin_intake_revisit_backfill_undo_v1"("p_batch" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if btrim(coalesce(p_reason, '')) = '' then raise exception 'a reason is required' using errcode = '22023'; end if;
  v := security.intake_revisit_backfill_undo_v1(p_batch);
