CREATE OR REPLACE FUNCTION "public"."admin_layer1_add_source"("p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_country uuid; v_url text := btrim(coalesce(p_args->>'url', '')); v_label text := btrim(coalesce(p_args->>'label', ''));
        v_authority text := btrim(coalesce(p_args->>'authority_name', '')); v_reason text := btrim(coalesce(p_args->>'reason', ''));
        v_days int := coalesce(nullif(p_args->>'ingestion_cadence_days', '')::int, 30); v_dom text; v_id uuid;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  select k.id into v_country from ref.countries k where k.iso_alpha2 = upper(btrim(coalesce(p_args->>'country_code', '')));
  if v_country is null then raise exception 'choose a country'; end if;
  if length(v_label) < 4 then raise exception 'enter the register''s name'; end if;
  if v_url !~* '^https://[^[:space:]/]+\.[^[:space:]]+$' then raise exception 'enter the register''s https address'; end if;
  if length(v_authority) < 3 then raise exception 'enter the authority that publishes it'; end if;
  if v_days not between 1 and 365 then raise exception 'the refresh interval is 1 to 365 days'; end if;
  if length(v_reason) < 4 then v_reason := 'Layer 1 › Sources: register added'; end if;
  if exists (select 1 from pipeline.sources s where lower(s.url) = lower(v_url) and s.status <> 'retired') then raise exception 'a source with this address already exists'; end if;
  v_dom := lower(regexp_replace(substring(v_url from '^https://([^/:?#]+)'), '^www\.', ''));
  insert into pipeline.sources(source_type, country_id, url, label, trust_rank, status, metadata)
  values ('web', v_country, v_url, v_label, 10, 'active',
          jsonb_build_object('layer', '1', 'added_in', 'v2.15.246', 'added_by', auth.uid(), 'needs_reader', true, 'dataset_class', coalesce(nullif(p_args->>'dataset_class', ''), 'register'),
                             'notes', nullif(btrim(coalesce(p_args->>'notes', '')), '')))
  returning id into v_id;
  insert into pipeline.layer1_source_operations(source_id, authority_name, authority_domains, expected_format, expected_count_kind, active, paused, verification_cadence_days,
         ingestion_cadence_days, variance_warn_percent, variance_block_percent, verification_status, variance_decision, verification_message, next_verification_at, auto_ingest, change_reason, updated_by, updated_at)
  values (v_id, v_authority, array[v_dom], coalesce(nullif(btrim(coalesce(p_args->>'expected_format', '')), ''), 'not set: needs a reader'), 'records', true, true, 1,
          v_days, 5, 20, 'unverified', 'unknown', 'Added by hand; it runs once a reader (adapter) is assigned to it.', null, false, v_reason, auth.uid(), now());
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('layer1', 'add_source', v_id::text, jsonb_build_object('label', v_label, 'url', v_url, 'country', upper(p_args->>'country_code'), 'reason', v_reason), auth.uid());
  return jsonb_build_object('ok', true, 'source_id', v_id, 'label', v_label);
end $_$;


ALTER FUNCTION "public"."admin_layer1_add_source"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_layer1_policy_run_v1"("p_source_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_policy uuid;
begin
  -- SS-020 follow-up (Option A, 4 Nov 2026 10:00 §8): the same rank (4), reason (5 characters), enabled-policy rule, duplicate check and audit
  -- as Refresh schedules › Run on demand, which it replaces as the entry point
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 4 then raise exception 'Pipeline Operator required' using errcode = '42501'; end if;
  select id into v_policy from pipeline.refresh_policies where layer = 1 and source_id = p_source_id order by updated_at desc, id limit 1;
  if v_policy is null then raise exception 'this source has no refresh policy; a Platform Admin starts it with Run now' using errcode = '22023'; end if;
  return security.scheduler_policy_run_now_v1_browser_bridge(v_policy, p_reason);
end $$;


ALTER FUNCTION "public"."admin_layer1_policy_run_v1"("p_source_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_layer1_schedule"("p_source_id" "uuid", "p_schedule" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_days int; v_auto boolean; v_rank int; v_before jsonb; v_after jsonb; v_policy pipeline.refresh_policies%rowtype; v_next timestamptz;
begin
  v_rank := coalesce(security.current_role_rank(), 0);
  if auth.uid() is null or v_rank < 4 then raise exception 'Pipeline Operator required' using errcode = '42501'; end if;
  select case p_schedule when 'daily' then 1 when 'weekly' then 7 when 'monthly' then 30 when 'quarterly' then 91 when 'yearly' then 365 when 'manual' then 30 end,
         p_schedule <> 'manual' into v_days, v_auto;
  if v_days is null then raise exception 'schedule must be daily, weekly, monthly, quarterly, yearly or manual'; end if;
  select jsonb_build_object('verification_cadence_days', verification_cadence_days, 'ingestion_cadence_days', ingestion_cadence_days, 'auto_ingest', auto_ingest)
    into v_before from pipeline.layer1_source_operations where source_id = p_source_id for update;
  if v_before is null then raise exception 'not a Layer 1 source'; end if;
  -- SS-020 follow-up (Decision 269 amendment; Option A, 4 Nov 2026 10:00 §8): a register with a Layer 1 refresh policy is scheduled by that
  -- policy (security.refresh_scheduler_tick_impl). Its Schedule goes through the legacy Edit schedule control, with that control's rank (4),
  -- reason (5 characters) and audit (refresh_policy_action_events); verification_cadence_days is no longer written for it.
  select * into v_policy from pipeline.refresh_policies where layer = 1 and source_id = p_source_id order by updated_at desc, id limit 1 for update;
  if found then
    if length(btrim(coalesce(p_reason, ''))) < 5 then raise exception 'give a reason of at least 5 characters (kept in the log)' using errcode = '22023'; end if;
    if v_rank < 6 and p_schedule = 'manual' then raise exception 'Manual switches automatic loading off: Platform Admin required' using errcode = '42501'; end if;
    v_next := greatest(now(), coalesce(v_policy.next_due_at - coalesce(v_policy.cadence_interval, make_interval()), now()) + make_interval(days => v_days));
    v_before := v_before || jsonb_build_object('refresh_policy', jsonb_build_object('policy_id', v_policy.id, 'cadence_interval', v_policy.cadence_interval::text, 'next_due_at', v_policy.next_due_at));
    perform security.scheduler_policy_edit_v1_browser_bridge(v_policy.id, v_policy.updated_at, v_days, v_next, v_policy.enabled, p_reason);
    if v_rank >= 6 then
      update pipeline.layer1_source_operations
         set ingestion_cadence_days = case when p_schedule = 'manual' then ingestion_cadence_days else v_days end,
             auto_ingest = v_auto, change_reason = left(p_reason, 500), updated_by = auth.uid(), updated_at = now()
       where source_id = p_source_id;
    end if;
    select jsonb_build_object('verification_cadence_days', o.verification_cadence_days, 'ingestion_cadence_days', o.ingestion_cadence_days, 'auto_ingest', o.auto_ingest,
             'refresh_policy', jsonb_build_object('policy_id', p.id, 'cadence_interval', p.cadence_interval::text, 'next_due_at', p.next_due_at))
      into v_after from pipeline.layer1_source_operations o, pipeline.refresh_policies p where o.source_id = p_source_id and p.id = v_policy.id;
  else
    -- no Layer 1 refresh policy: its runs come from next_verification_at (layer1_regulatory_scheduler_tick_impl), and only the Platform Admin
    -- changes it, as before
    if v_rank < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
    if length(btrim(coalesce(p_reason, ''))) < 4 then raise exception 'give a reason (kept in the log)'; end if;
    update pipeline.layer1_source_operations
       set verification_cadence_days = v_days, ingestion_cadence_days = case when p_schedule = 'manual' then ingestion_cadence_days else v_days end,
           auto_ingest = v_auto, next_verification_at = least(coalesce(next_verification_at, now() + make_interval(days => v_days)), now() + make_interval(days => v_days)),
           change_reason = left(p_reason, 500), updated_by = auth.uid(), updated_at = now()
     where source_id = p_source_id
    returning jsonb_build_object('verification_cadence_days', verification_cadence_days, 'ingestion_cadence_days', ingestion_cadence_days, 'auto_ingest', auto_ingest) into v_after;
  end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('layer1', 'layer1_schedule_set', p_source_id::text, jsonb_build_object('schedule', p_schedule, 'before', v_before, 'after', v_after, 'reason', left(p_reason, 500)), auth.uid());
  return jsonb_build_object('ok', true, 'schedule', p_schedule) || v_after;
end $$;


ALTER FUNCTION "public"."admin_layer1_schedule"("p_source_id" "uuid", "p_schedule" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_layer23"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int; v_out jsonb; v_list jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode = '42501'; end if;
  v_rank := security.current_role_rank();
  if coalesce(v_rank, 0) < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  if p_action = 'data_delivery' then
    -- CF-247 F-OPS.03A (Platform Admin 9 Nov 2026): the Data Delivery summary at the top of Layer 2/3 > Operations. One read, same rank as the screen (3 and above, checked above).
    return security.data_delivery_v1();
  end if;
  if p_action = 'universities_page' then
    -- CF-247 W33 (30 Oct 2026): one page of Layer 2/3 › Universities. The filters, the name search and the order (by name) the screen
    -- offered on the whole list are applied here; the page size and the most rows ticked at once are settings (layer23.*). The same
    -- rows and fields as 'universities'; the onboarding stage and the course-page counts are worked out for the rows of the page only.
    -- mode 'ticks' answers every matching row in short form (for Tick every row shown), and no page.
    declare
      v_size int := greatest(security.pipeline_num_v1('layer23.universities_page_size', 100)::int, 1);
      v_tick_max int := greatest(security.pipeline_num_v1('layer23.universities_tick_max', 2000)::int, 1);
      v_off int := greatest(coalesce(nullif(p_args->>'offset', '')::int, 0), 0);
      v_ticks boolean := coalesce(p_args->>'mode', '') = 'ticks';
      v_pid uuid := nullif(p_args->>'provider_id', '')::uuid;
      v_country text := nullif(btrim(coalesce(p_args->>'country', '')), '');
      v_state text := nullif(btrim(coalesce(p_args->>'state', '')), '');
      v_kind text := coalesce(nullif(btrim(coalesce(p_args->>'kind', '')), ''), 'any');
      v_adapter text := nullif(btrim(coalesce(p_args->>'adapter', '')), '');
      v_qualify text := nullif(btrim(coalesce(p_args->>'qualify', '')), '');
      v_target text := nullif(btrim(coalesce(p_args->>'target', '')), '');
      v_stage text := nullif(btrim(coalesce(p_args->>'stage', '')), '');
      v_q text := nullif(btrim(coalesce(p_args->>'q', '')), '');
      v_pat text := coalesce(security.firecrawl_setting('target_name_pattern') #>> '{}', '(^|[^a-z])universit(y|ies)([^a-z]|$)');
      -- the read-cycle bounds are those public.admin_adapters enforces in set_cycle and answers in 'list' (kept identical to it)
      v_settings jsonb := case when v_rank >= 4 then jsonb_build_object('read_cycle_default', 90, 'read_cycle_min', 7, 'read_cycle_max', 365,
                            'min_read_share', coalesce(security.firecrawl_setting('eval_field_share'), '0.5'::jsonb),
                            'min_agree_share', coalesce(security.firecrawl_setting('qualify_agree_share'), '0.9'::jsonb)) end;
    begin
        with t as materialized (select x.provider_id, x.included, x.rule_match, x.override_reason from security.firecrawl_targets_fast() x where v_rank >= 4),
        ob as materialized (select distinct on (o.provider_id) o.id, o.provider_id, o.status, o.stop_reason, o.note, o.result, o.updated_at
                              from pipeline.provider_onboarding o order by o.provider_id, o.created_at desc),
        ib as materialized (select i.provider_id, i.kind, count(*) c from security.layer4_inbox_items_v1() i where i.provider_id is not null group by 1, 2),
        ibn as (select ib.provider_id, sum(ib.c)::int n from ib group by 1),
        q as (select distinct on (x.provider_id) x.provider_id, x.job_id, x.measured_at, x.passing, x.pages_read
                from pipeline.adapter_qualifications x join pipeline.admin_jobs j on j.id = x.job_id and j.kind = 'qualify_adapters' and j.state = 'done'
               where v_rank >= 4 order by x.provider_id, x.measured_at desc),
        ids as (select a.provider_id from pipeline.uni_adapters a where v_rank >= 4 union select t.provider_id from t where t.included union select ob.provider_id from ob),
        u as materialized (
          select p.id provider_id, coalesce(p.display_name, p.canonical_name) name, k.iso_alpha2 country, s.code state, l.inlist,
                 case when l.inlist then coalesce(p.display_name, p.canonical_name) ~* v_pat else true end university,
                 case when l.inlist and a.provider_id is not null then case when not a.enabled then 'off' when a.admit then 'admitting' else 'testing' end end adapter_state,
                 case when l.inlist and a.admit then coalesce(a.admit_fields, '{}') else '{}' end admit_fields,
                 l.inlist and q.provider_id is not null qualified, case when l.inlist then coalesce(q.passing, '{}') else '{}' end passing,
                 case when l.inlist then t.included end target_included,
                 ob.id ob_id, ob.status ob_status, ob.stop_reason ob_stop, coalesce(ibn.n, 0) inbox
            from ids join catalogue.providers p on p.id = ids.provider_id
            left join ref.countries k on k.id = p.country_id left join ref.subdivisions s on s.id = p.subdivision_id
            left join pipeline.uni_adapters a on a.provider_id = p.id and v_rank >= 4
            left join t on t.provider_id = p.id left join q on q.provider_id = p.id
            left join ob on ob.provider_id = p.id left join ibn on ibn.provider_id = p.id
            cross join lateral (select v_rank >= 4 and (a.provider_id is not null or coalesce(t.included, false)) inlist) l),
        f as materialized (
          select u.* from u
           where (v_pid is null or u.provider_id = v_pid)
             and (v_country is null or u.country = v_country) and (v_state is null or u.state = v_state)
             and (v_kind <> 'university' or u.university)
             and (v_adapter is null or (v_adapter = 'none' and u.adapter_state is null) or u.adapter_state = v_adapter)
             and (v_qualify is null
                  or (v_qualify = 'never' and not u.qualified)
                  or (v_qualify = 'passing' and cardinality(u.passing) > 0)
                  or (v_qualify = 'waiting' and u.adapter_state is not null and u.adapter_state <> 'off' and exists (select 1 from unnest(u.passing) x where x <> all (u.admit_fields)))
                  or (v_qualify not in ('never', 'passing', 'waiting') and u.qualified and cardinality(u.passing) = 0))
             and (v_target is null or (v_target = 'in' and coalesce(u.target_included, false)) or (v_target <> 'in' and not coalesce(u.target_included, false)))
             and (v_q is null or strpos(lower(u.name), lower(v_q)) > 0)
             and (v_stage is null
                  or (v_stage = 'none' and u.ob_id is null)
                  or (v_stage = 'inbox' and u.inbox > 0)
                  or (u.ob_id is not null and (
                       (v_stage = 'working' and u.ob_status in ('queued', 'website', 'course_pages', 'capturing', 'proposing', 'applying', 'qualifying', 'scholarships', 'waiting_admit', 'waiting_courses'))
                    or (v_stage = 'person' and u.ob_status = 'stopped' and coalesce(u.ob_stop, '') in ('nothing_ready', 'approve_central'))
                    or (v_stage = 'stopped' and u.ob_status = 'stopped' and coalesce(u.ob_stop, '') not in ('nothing_ready', 'approve_central'))
                    or (v_stage = 'done' and u.ob_status = 'done')
                    or v_stage not in ('none', 'inbox', 'working', 'person', 'stopped', 'done'))))),
        pg as (select f.* from f order by f.name, f.provider_id offset v_off limit v_size)
        select jsonb_build_object('as_at', now(), 'can_manage', v_rank >= 6, 'can_qualify', v_rank >= 5, 'can_onboard', v_rank >= 6, 'settings', v_settings,
          'paged', true, 'page_size', v_size, 'offset', v_off,
          'total', (select count(*) from u), 'matched', (select count(*) from f),
          'tally', (select jsonb_build_object('admitting', count(*) filter (where f.adapter_state = 'admitting'), 'testing', count(*) filter (where f.adapter_state = 'testing'),
                                              'off', count(*) filter (where f.adapter_state = 'off'), 'none', count(*) filter (where f.adapter_state is null)) from f),
          'countries', (select coalesce(jsonb_agg(z.c order by z.c collate "C"), '[]'::jsonb) from (select distinct u.country c from u where u.country is not null) z),
          'states', (select coalesce(jsonb_agg(z.c order by z.c collate "C"), '[]'::jsonb) from (select distinct u.state c from u where u.state is not null and (v_country is null or u.country = v_country)) z),
          'adapters', case when v_ticks then '[]'::jsonb else (select coalesce(jsonb_agg(jsonb_build_object(
              'provider_id', pg.provider_id, 'name', pg.name, 'country', pg.country, 'state', pg.state, 'university', pg.university,
              'adapter', case when pg.adapter_state is null then null else jsonb_build_object('state', pg.adapter_state, 'fields', to_jsonb(pg.admit_fields), 'read_cycle_days', a.read_cycle_days, 'updated_at', a.updated_at, 'admit_changed_at', a.admit_changed_at) end,
              'target', case when pg.target_included is null then null else jsonb_build_object('included', t.included, 'rule_match', t.rule_match, 'override_reason', t.override_reason,
                             'rule_reason', (select c.rule_reason from pipeline.firecrawl_target_cache c where c.provider_id = pg.provider_id)) end,
              'pages', gp.pages, 'pages_read', gp.pages_read, 'next_read', gp.next_read, 'last_read', gp.last_read,
              'qualify', case when not pg.qualified then null else jsonb_build_object('job_id', q.job_id, 'at', q.measured_at, 'passing', to_jsonb(q.passing), 'pages_read', q.pages_read) end,
              'onboarding', case when pg.ob_id is null then null else jsonb_build_object('id', ob.id, 'status', ob.status, 'stage', security.provider_onboarding_stage_v1(ob.status, ob.stop_reason, ob.result),
                             'phase', ob.result->>'phase', 'stop_reason', ob.stop_reason, 'note', ob.note, 'updated_at', ob.updated_at) end,
              'inbox', pg.inbox, 'inbox_kinds', coalesce((select jsonb_object_agg(ib.kind, ib.c) from ib where ib.provider_id = pg.provider_id), '{}'::jsonb))
              order by pg.name, pg.provider_id), '[]'::jsonb)
            from pg left join pipeline.uni_adapters a on a.provider_id = pg.provider_id left join t on t.provider_id = pg.provider_id
            left join q on q.provider_id = pg.provider_id left join ob on ob.provider_id = pg.provider_id
            cross join lateral (select count(*) pages, count(*) filter (where g.read_status = 'read') pages_read,
                                       min(g.next_read_at) filter (where g.read_status in ('read', 'identity_mismatch')) next_read, max(g.read_at) last_read
                                  from pipeline.coverage_course_pages g where g.provider_id = pg.provider_id) gp) end,
          'ticks', case when not v_ticks then null else (select jsonb_build_object('capped', count(*) > v_tick_max, 'rows', coalesce(jsonb_agg(jsonb_build_object(
              'provider_id', z.provider_id, 'name', z.name,
              'adapter', case when z.adapter_state is null then null else jsonb_build_object('state', z.adapter_state, 'fields', to_jsonb(z.admit_fields)) end,
              'qualify', case when not z.qualified then null else jsonb_build_object('passing', to_jsonb(z.passing)) end,
              'onboarding', case when z.ob_id is null then null else jsonb_build_object('id', z.ob_id, 'status', z.ob_status) end) order by z.name, z.provider_id)
              filter (where z.rn <= v_tick_max), '[]'::jsonb))
            from (select f.*, row_number() over (order by f.name, f.provider_id) rn from f) z) end)
          into v_out;
      return v_out;
    end;
  end if;

  -- only the kind and the university of each item are used here: the detail of every item (its stored copy and whether a newer copy exists) is not built (3 s, now 0.2 s)
  create temp table if not exists _l23_inbox on commit drop as select i.kind, i.provider_id from security.layer4_inbox_items_v2(null, null, null, false) i;
  create temp table if not exists _l23_ob on commit drop as
    select distinct on (o.provider_id) o.id, o.provider_id, o.status, o.stop_reason, o.note, o.result, o.updated_at,
           security.provider_onboarding_stage_v1(o.status, o.stop_reason, o.result) stage
      from pipeline.provider_onboarding o order by o.provider_id, o.created_at desc;

  if p_action = 'operations' then
    with st(key, label, ord, kinds, what) as (values
      ('website', 'Find the website', 1, array['website_needed', 'site_down'], 'The official website is found and checked.'),
      ('pages', 'Find course pages', 2, array['pages_not_found', 'too_few_pages'], 'Each course''s own page is found by its CRICOS code or the university''s listing, and read.'),
      ('adapter', 'Build the adapter', 3, array['nothing_ready', 'onboarding_failed'], 'Sample pages are captured, the AI proposes the adapter, it is applied and qualified.'),
      ('enrich', 'Admit and enrich', 4, array['central_to_approve', 'course_link', 'fee_check', 'not_offered', 'not_on_site', 'counsellor_report'], 'Fields that pass are admitted, central pages fill what pages do not say, courses are enriched.'),
      ('scholarships', 'Scholarships', 5, array['held_scholarship'], 'Scholarship pages are found, read and checked by the AI before they are published.')),
    n as (select
      count(*) filter (where o.status = 'website') website_run, count(*) filter (where o.status = 'queued') website_wait,
      count(*) filter (where o.status in ('course_pages', 'waiting_courses')) pages_run,
      count(*) filter (where o.status in ('capturing', 'proposing', 'applying', 'qualifying')) adapter_run,
      count(*) filter (where o.status = 'scholarships' and o.result->>'phase' = 'enrich') enrich_run, count(*) filter (where o.status = 'waiting_admit') enrich_wait,
      count(*) filter (where o.status = 'scholarships' and coalesce(o.result->>'phase', '') <> 'enrich') sch_run,
      count(*) filter (where o.status = 'done') done, count(*) filter (where o.status = 'stopped') stopped
      from _l23_ob o)
    select jsonb_build_object('as_at', now(), 'can_manage', v_rank >= 6, 'rank', v_rank,
      'done', n.done, 'stopped_onboarding', n.stopped,
      'enrich_review', (select count(*) from pipeline.field_enrich_items f where f.state = 'review'),
      'settings', (select jsonb_build_object('enabled', s.enabled, 'auto_admit', s.auto_admit, 'max_active', s.max_active) from pipeline.provider_onboarding_settings s limit 1),
      'stages', (select jsonb_agg(jsonb_build_object('key', st.key, 'label', st.label, 'order', st.ord, 'what', st.what, 'kinds', to_jsonb(st.kinds),
          'running', case st.key when 'website' then n.website_run when 'pages' then n.pages_run when 'adapter' then n.adapter_run when 'enrich' then n.enrich_run else n.sch_run end,
          'waiting', case st.key when 'website' then n.website_wait
                                 when 'pages' then (select count(*) from pipeline.coverage_provider_discovery d where d.status = 'pending')
                                 when 'adapter' then (select count(*) from pipeline.adapter_builds b where b.wave is not null and coalesce(b.ready, 0) = 0 and b.checked_at is null)
                                 when 'enrich' then n.enrich_wait
                                 else (select count(*) from pipeline.scholarship_ai_reviews r where r.status = 'pending' and coalesce(r.recheck->>'state', 'none') in ('queued', 'leased')) end,
          'stopped', (select count(*) from _l23_inbox i where i.kind = any(st.kinds)),
          'stopped_by_kind', (select coalesce(jsonb_object_agg(k.kind, k.c), '{}'::jsonb) from (select i.kind, count(*) c from _l23_inbox i where i.kind = any(st.kinds) group by 1) k),
          'jobs', (select coalesce(jsonb_agg(a.jobname order by a.sort), '[]'::jsonb) from pipeline.automation_catalogue a where a.layer23_stage = st.key))
        order by st.ord) from st))
      into v_out from n;
    return v_out;
  end if;

  if p_action = 'universities' then
    -- Adapters (Operator and above) as on the old Adapters tab; a Curator sees the universities in onboarding only
    v_list := case when v_rank >= 4 then public.admin_adapters('list', '{}'::jsonb) else jsonb_build_object('can_manage', false, 'can_qualify', false, 'adapters', '[]'::jsonb) end;
    with a as (select x from jsonb_array_elements(coalesce(v_list->'adapters', '[]'::jsonb)) x),
    ids as (select (x->>'provider_id')::uuid provider_id from a),
    extra as (  -- universities in onboarding with no adapter and not in the Firecrawl targets
      select jsonb_build_object('provider_id', p.id, 'name', coalesce(p.display_name, p.canonical_name), 'country', k.iso_alpha2, 'state', s.code,
               'university', true, 'adapter', null, 'target', null, 'qualify', null,
               'pages', (select count(*) from pipeline.coverage_course_pages g where g.provider_id = p.id),
               'pages_read', (select count(*) from pipeline.coverage_course_pages g where g.provider_id = p.id and g.read_status = 'read')) x
        from _l23_ob o join catalogue.providers p on p.id = o.provider_id
        left join ref.countries k on k.id = p.country_id left join ref.subdivisions s on s.id = p.subdivision_id
       where o.provider_id not in (select provider_id from ids)),
    allrows as (select x from a union all select x from extra),
    inbox as (select provider_id, count(*) n, jsonb_object_agg(kind, c) by_kind from (select provider_id, kind, count(*) c from _l23_inbox where provider_id is not null group by 1, 2) z group by 1)
    select jsonb_build_object('as_at', now(), 'can_manage', v_list->'can_manage', 'can_qualify', v_list->'can_qualify', 'can_onboard', v_rank >= 6, 'settings', v_list->'settings',
      'adapters', coalesce(jsonb_agg(r.x || jsonb_build_object(
          'onboarding', case when o.id is null then null else jsonb_build_object('id', o.id, 'status', o.status, 'stage', o.stage, 'phase', o.result->>'phase', 'stop_reason', o.stop_reason, 'note', o.note, 'updated_at', o.updated_at) end,
          'inbox', coalesce(i.n, 0), 'inbox_kinds', coalesce(i.by_kind, '{}'::jsonb))
        order by r.x->>'name'), '[]'::jsonb))
      into v_out
      from allrows r left join _l23_ob o on o.provider_id = (r.x->>'provider_id')::uuid left join inbox i on i.provider_id = (r.x->>'provider_id')::uuid;
    return v_out;
  end if;
  raise exception 'unknown action %', p_action;
end $_$;


ALTER FUNCTION "public"."admin_layer23"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_layer23"("p_action" "text", "p_args" "jsonb") IS 'CF-247 20 Oct 2026: Layer 2/3 › Operations (stages, jobs, stopped for a person) and Universities (adapter and onboarding per university). Read only.';



CREATE OR REPLACE FUNCTION "public"."admin_layer3_control"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "sql"
    SET "search_path" TO 'public', 'extensions'
    AS $$ select security.admin_layer3_control_v1(p_action, coalesce(p_args,'{}'::jsonb)) $$;


ALTER FUNCTION "public"."admin_layer3_control"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_layer3_control_read"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$ select security.admin_layer3_control_read_v1() $$;


ALTER FUNCTION "public"."admin_layer3_control_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_layer4_aer_queue"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 4 then raise exception 'Pipeline Operator or above required' using errcode = '42501'; end if;
  if coalesce(p_args, '{}'::jsonb) ? 'summary_provider_id' then return security.layer4_aer_university_summary_v1((p_args->>'summary_provider_id')::uuid); end if;
  return security.layer4_aer_queue_v1(coalesce(p_args, '{}'::jsonb));
end $$;


ALTER FUNCTION "public"."admin_layer4_aer_queue"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_layer4_drain_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  return jsonb_build_object('acting', security.pipeline_num_v1('layer4.drain_on', 0) = 1,
    'verdicts', coalesce((select jsonb_object_agg(z.verdict, z.n) from (select s.verdict, count(*) n from pipeline.layer4_drain_state s
                           join pipeline.layer4_review_items i on i.id = s.item_id and i.status = 'pending' group by 1) z), '{}'::jsonb),
    'applied', (select count(*) from pipeline.layer4_drain_state where applied),
    'dead_letters', (select count(*) from pipeline.layer4_drain_state s join pipeline.layer4_review_items i on i.id = s.item_id and i.status = 'pending' where s.dead_letter_at is not null));
end $$;


ALTER FUNCTION "public"."admin_layer4_drain_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_layer4_drain_v1"() IS 'CF-247 worker v1.0.0: what job layer4-drain found for the pending Layer 4 items (by verdict), how many actions it took and how many dead letters wait, for Curator and above.';



CREATE OR REPLACE FUNCTION "public"."admin_layer4_groups"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_lim int := least(greatest(coalesce((p_args->>'limit')::int, security.pipeline_num_v1('layer4.inbox_page_size', 25)::int), 1), 200);  -- fixed: page size bounds
        v_off int := greatest(coalesce((p_args->>'offset')::int, 0), 0); v_grp text := upper(coalesce(p_args->>'group', ''));
        v_prov uuid := nullif(p_args->>'provider_id', '')::uuid; v_kind text := nullif(p_args->>'kind', ''); v_kinds jsonb; v_t int := security.pipeline_num_v1('layer4.target_days', 7)::int;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode = '42501'; end if;
  if security.current_role_rank() < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  if p_args->>'action' = 'flow' then return security.layer4_flow_report_v1(); end if;
  if coalesce(p_args->>'action', 'summary') = 'summary' then
    return security.layer4_group_counts_v1(v_prov) || jsonb_build_object('labels', jsonb_build_object('C', 'Ready for my decision', 'D', 'Information needed from me',
             'B', 'Technical recovery', 'A', 'Settled by existing rules'));
  end if;
  if v_grp not in ('A', 'B', 'C', 'D', 'I') then raise exception 'choose a group: C, D, B or I (Human input needed requests; A is counts only)'; end if;
  if v_grp = 'A' then raise exception 'group A is settled by existing rules and has no cards; see its rules in the summary'; end if;
  v_kinds := security.layer4_inbox_hooks_v1()->'kinds';
  -- the stored groups only (never classified here); a row whose input changed since it was grouped is listed under C until it is grouped again
  return (with g0 as (select x.kind, x.ref, x.provider_id, x.item_created_at created_at, x.cls, x.rule,
                             case when x.grp <> 'C' and ((rd.classified_at is not null and rd.classified_at > x.input_at) or (iv.updated_at is not null and iv.updated_at > x.input_at)) then 'C' else x.grp end grp,
                             (rd.classified_at is not null and rd.classified_at > x.input_at) or (iv.updated_at is not null and iv.updated_at > x.input_at) stale
                        from pipeline.layer4_item_groups x
                        left join pipeline.layer4_item_readiness rd on x.kind in ('course_link', 'aer_review', 'provider_description', 'no_page_first_run', 'conjoint_first_run')
                             and rd.item_id = case when x.ref ~ '^[0-9a-f-]{36}$' then x.ref::uuid end
                        left join pipeline.layer4_interventions iv on x.kind = 'intervention' and iv.id = case when x.ref ~ '^[0-9]+$' then x.ref::bigint end
                       where x.state = 'waiting' and (v_prov is null or x.provider_id = v_prov) and (v_kind is null or x.kind = v_kind)),
               -- I: the Human input needed requests (their own line); C, D, B: the waiting items, one disposition each
               g as (select * from g0 where case when v_grp = 'I' then g0.kind = 'intervention' else g0.kind <> 'intervention' and g0.grp = v_grp end),
               pg as (select * from g order by g.created_at, g.kind, g.ref limit v_lim offset v_off),
               b as (select i.kind, i.ref, i.provider_id, i.subject, i.why, i.suggestion, i.created_at, i.detail
                       from security.layer4_inbox_items_v2(null, null, array(select pg.kind || ':' || pg.ref from pg where pg.kind <> 'intervention'), true) i
                      where exists (select 1 from pg where pg.kind <> 'intervention')),
               j as (select pg.created_at, pg.kind, pg.ref, jsonb_build_object('kind', pg.kind, 'ref', pg.ref, 'provider_id', pg.provider_id,
                              'provider', (select coalesce(p.display_name, p.canonical_name) from catalogue.providers p where p.id = pg.provider_id),
                              'subject', coalesce(b.subject, (select x.subject from pipeline.layer4_interventions x where pg.kind = 'intervention' and x.id::text = pg.ref)),
                              'why', b.why, 'suggestion', b.suggestion, 'created_at', pg.created_at, 'late', pg.created_at < now() - make_interval(days => v_t),
                              'detail', coalesce(b.detail, '{}'::jsonb), 'o', (v_kinds->pg.kind->>'order')::int, 'hook', pg.kind = 'intervention',
                              'group', pg.grp, 'class', case when pg.stale then 'not_grouped_yet' else pg.cls end, 'rule', pg.rule) item
                       from pg left join b on b.kind = pg.kind and b.ref = pg.ref
                      -- a stored row whose item has just left the Inbox is not drawn (the next run marks it closed)
                      where pg.kind = 'intervention' or b.ref is not null)
    select jsonb_build_object('group', v_grp, 'total', (select count(*) from g), 'offset', v_off, 'limit', v_lim,
                              'items', coalesce((select jsonb_agg(j.item order by j.created_at, j.kind, j.ref) from j), '[]'::jsonb)));
end $_$;


ALTER FUNCTION "public"."admin_layer4_groups"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_layer4_inbox"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int; v_hooks jsonb; v_kinds jsonb; v_kind text; v_ref text; v_choice text; v_reason text; v_value text; v_pid uuid;
        v_target int := security.pipeline_num_v1('layer4.target_days', 7)::int; v_actor text; v_lim int; v_off int; v_q text; v_r jsonb; v_c jsonb; v_det jsonb; v_out jsonb; v_ids uuid[]; v_event bigint;
        -- CF-247 Layer 4 Inbox performance (4 Nov 2026): counts, pages, lazy detail and kind hooks
        v_hc jsonb; v_prov uuid; v_fkind text; v_bkind text; v_has boolean; v_ao int; v_aat timestamptz; v_ak text; v_ar text; v_h jsonb; v_hp jsonb; v_hargs jsonb;
        v_total bigint := 0; v_before bigint := 0; v_hitems jsonb := '[]'; v_keys text[]; v_fn text; v_np bigint; v_ho int;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode = '42501'; end if;
  v_rank := security.current_role_rank();
  v_actor := coalesce((select u.email from auth.users u where u.id = auth.uid()), auth.uid()::text);
  if v_rank < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  v_lim := least(greatest(coalesce((p_args->>'limit')::int, 50), 1), 200); v_off := greatest(coalesce((p_args->>'offset')::int, 0), 0);  -- fixed: page size bounds
  v_q := nullif(btrim(p_args->>'q'), '');
  v_hooks := security.layer4_inbox_hooks_v1(); v_kinds := v_hooks->'kinds';
  v_fkind := nullif(p_args->>'kind', '');
  -- a built-in kind is read from the item list; a registered kind from its hooks
  v_bkind := case when v_fkind is null or security.layer4_inbox_kinds_v1() ? v_fkind then v_fkind else '-' end;

  if p_action = 'summary' then
    -- counts only: no item is built (Platform Admin 4 Nov 2026 06:53 §1, bounded first queries)
    v_hc := security.layer4_inbox_hook_counts_v1(v_hooks, null);
    return (with b as (select * from security.layer4_inbox_counts_v1(v_target)),
                 h as (select x->>'kind' kind, (x->>'n')::bigint n, (x->>'oldest')::timestamptz oldest, (x->>'late')::bigint late, x->'by_provider' bp from jsonb_array_elements(v_hc->'items') x),
                 k as (select kind, sum(n)::bigint n, min(oldest) oldest, sum(late)::bigint late from b group by 1 union all select kind, n, oldest, late from h where n > 0)
      select jsonb_build_object('kinds', v_kinds, 'target_days', v_target, 'rank', v_rank,
        'by_kind', (select coalesce(jsonb_object_agg(k.kind, jsonb_build_object('n', k.n, 'oldest', k.oldest, 'late', k.late)), '{}'::jsonb) from k),
        'total', (select coalesce(sum(n), 0) from k),
        'universities', (select count(distinct p) from (select provider_id p from b where provider_id is not null
                                                        union select (y->>'provider_id')::uuid from h, jsonb_array_elements(h.bp) y where y->>'provider_id' is not null) u),
        'late', (select coalesce(sum(late), 0) from k),
        'paging', jsonb_build_object('items', security.pipeline_num_v1('layer4.inbox_page_size', 25)::int,
                                     'universities', security.pipeline_num_v1('layer4.inbox_universities_page_size', 25)::int,
                                     'detail_parallel', security.pipeline_num_v1('layer4.inbox_detail_parallel', 3)::int),
        'hooks_missing', v_hooks->'missing', 'hooks_failed', (v_hooks->'failed') || (v_hc->'failed')));

  elsif p_action = 'universities' then
    -- counts by university; names and course counts for the universities of this page only
    v_hc := case when v_bkind = '-' or v_fkind is null then security.layer4_inbox_hook_counts_v1(v_hooks, v_fkind) else '{"items": []}'::jsonb end;
    return (with c as (select b.kind, b.provider_id, b.n, b.oldest from security.layer4_inbox_counts_v1(v_target) b where v_bkind is distinct from '-' and (v_fkind is null or b.kind = v_fkind)
                       union all
                       select x->>'kind', (y->>'provider_id')::uuid, (y->>'n')::bigint, (y->>'oldest')::timestamptz
                         from jsonb_array_elements(v_hc->'items') x, jsonb_array_elements(x->'by_provider') y where coalesce((y->>'n')::bigint, 0) > 0),
                 g as (select c.provider_id, sum(c.n)::bigint n, min(c.oldest) oldest, min((v_kinds->c.kind->>'order')::int) first_order, jsonb_object_agg(c.kind, c.n) by_kind
                         from c group by 1),
                 u as (select g.*, coalesce(p.display_name, p.canonical_name, 'Platform') name, k.iso_alpha2::text country,
                              (select count(*) from catalogue.courses cc where cc.provider_id = g.provider_id and cc.lifecycle_status = 'active') courses
                         from g left join catalogue.providers p on p.id = g.provider_id left join ref.countries k on k.id = p.country_id
                        where (nullif(p_args->>'country', '') is null or k.iso_alpha2 = p_args->>'country')
                          and (v_q is null or coalesce(p.display_name, p.canonical_name, '') ilike '%' || v_q || '%'))
      select jsonb_build_object('total', (select count(*) from u), 'limit', v_lim, 'offset', v_off,
        'items', coalesce((select jsonb_agg(jsonb_build_object('provider_id', z.provider_id, 'name', z.name, 'country', z.country, 'courses', z.courses, 'n', z.n, 'oldest', z.oldest,
                     'late', z.oldest < now() - make_interval(days => v_target), 'by_kind', z.by_kind)
                   order by z.first_order, z.courses desc nulls last, z.name)
            from (select * from u order by first_order, courses desc nulls last, name limit v_lim offset v_off) z), '[]'::jsonb)));

  elsif p_action = 'items' then
    if not (p_args ? 'provider_id' or p_args ? 'kind') then return jsonb_build_object('total', 0, 'items', '[]'::jsonb, 'before', 0, 'more', false); end if;
    v_prov := nullif(p_args->>'provider_id', '')::uuid;
    -- UR-04 (1 Nov 2026): a stable position (kind order, kind, created, ref) so every item is reached once, oldest first; kinds have their own order
    v_has := p_args ? 'after_ref';
    if v_has then v_ao := (p_args->>'after_o')::int; v_aat := (p_args->>'after_at')::timestamptz; v_ak := p_args->>'after_kind'; v_ar := p_args->>'after_ref'; end if;
    -- the built-in kinds: keys first (no detail), then the detail of this page's items only
    if v_bkind is distinct from '-' then
      with k as (select e.key kind, (e.value->>'order')::int o from jsonb_each(v_kinds) e),
           x as (select i.kind, i.ref, i.created_at, k.o, count(*) over () t,
                        count(*) filter (where v_has and (k.o, i.kind, i.created_at, i.ref) <= (v_ao, v_ak, v_aat, v_ar)) over () b
                   from security.layer4_inbox_items_v2(v_prov, v_bkind, null, false) i join k on k.kind = i.kind),
           pg as (select * from x where not v_has or (x.o, x.kind, x.created_at, x.ref) > (v_ao, v_ak, v_aat, v_ar) order by o, kind, created_at, ref limit v_lim + 1)
      select coalesce((select max(t) from x), 0), coalesce((select max(b) from x), 0), array(select pg.kind || ':' || pg.ref from pg) into v_total, v_before, v_keys;
    end if;
    -- registered kinds: their own pages and counts, merged in the same order
    for v_h in select x from jsonb_array_elements(v_hooks->'hooks') x where x->>'mode' = 'kind' and (v_fkind is null or x->>'kind' = v_fkind) loop
      v_ho := (v_h->>'order')::int;
      if v_hc is null then v_hc := security.layer4_inbox_hook_counts_v1(v_hooks, v_fkind); end if;
      v_np := coalesce((select case when v_prov is null then (x->>'n')::bigint
                                     else (select sum((y->>'n')::bigint) from jsonb_array_elements(x->'by_provider') y where (y->>'provider_id')::uuid = v_prov) end
                          from jsonb_array_elements(v_hc->'items') x where x->>'kind' = v_h->>'kind'), 0);
      v_total := v_total + v_np;
      if v_has and (v_ho, v_h->>'kind') < (v_ao, v_ak) then v_before := v_before + v_np; continue; end if;
      v_hargs := jsonb_strip_nulls(jsonb_build_object('provider_id', v_prov, 'limit', v_lim + 1));
      if v_has and (v_ho, v_h->>'kind') = (v_ao, v_ak) then v_hargs := v_hargs || jsonb_build_object('after_at', v_aat, 'after_ref', v_ar); end if;
      v_hp := security.layer4_inbox_hook_call_v1(v_h->>'page_fn', v_hargs, null);
      if v_hp ? 'error' or jsonb_typeof(v_hp->'items') is distinct from 'array' then continue; end if;
      if v_has and (v_ho, v_h->>'kind') = (v_ao, v_ak) then v_before := v_before + coalesce((v_hp->>'before')::bigint, 0); end if;
      v_hitems := v_hitems || coalesce((select jsonb_agg(i || jsonb_build_object('kind', v_h->>'kind', 'o', v_ho, '_s', lpad(n::text, 10, '0'),
                                                 'late', coalesce((i->>'late')::boolean, (i->>'created_at')::timestamptz < now() - make_interval(days => v_target)),
                                                 'detail', coalesce(i->'detail', '{}'::jsonb)) order by n)
                                          from jsonb_array_elements(v_hp->'items') with ordinality y(i, n) where i ? 'ref'), '[]'::jsonb);
    end loop;
    return (with b as (select i.kind, i.ref, i.provider_id, coalesce(p.display_name, p.canonical_name) provider, i.subject, i.why, i.suggestion, i.created_at, i.detail,
                              (v_kinds->i.kind->>'order')::int o
                         from security.layer4_inbox_items_v2(v_prov, v_bkind, v_keys, true) i left join catalogue.providers p on p.id = i.provider_id
                        where coalesce(array_length(v_keys, 1), 0) > 0),
                 m as (select b.o, b.kind, b.created_at, b.ref s, jsonb_build_object('kind', b.kind, 'ref', b.ref, 'provider_id', b.provider_id, 'provider', b.provider, 'subject', b.subject,
                              'why', b.why, 'suggestion', b.suggestion, 'created_at', b.created_at, 'late', b.created_at < now() - make_interval(days => v_target), 'detail', b.detail, 'o', b.o) j from b
                       union all
                       select (h->>'o')::int, h->>'kind', (h->>'created_at')::timestamptz, h->>'_s', (h - '_s') || jsonb_build_object('hook', true) from jsonb_array_elements(v_hitems) h),
                 pg as (select * from m order by o, kind, created_at, s limit v_lim)
      select jsonb_build_object('total', v_total, 'before', v_before, 'more', (select count(*) from m) > v_lim,
                                'items', coalesce((select jsonb_agg(pg.j order by pg.o, pg.kind, pg.created_at, pg.s) from pg), '[]'::jsonb)));

  elsif p_action = 'detail' then
    -- lazy detail of the items on screen (at most one page): the stored-copy facts of a built-in item and a hook's detail (kind or extension)
    return (with a as (select x->>'kind' kind, x->>'ref' ref from jsonb_array_elements(case when jsonb_typeof(p_args->'items') = 'array' then p_args->'items' else '[]'::jsonb end) x
                        where x ? 'kind' and x ? 'ref' limit v_lim),
                 b as (select i.kind, i.ref, i.detail from security.layer4_inbox_items_v2(null, null, array(select a.kind || ':' || a.ref from a where security.layer4_inbox_kinds_v1() ? a.kind), true) i
                        where exists (select 1 from a where security.layer4_inbox_kinds_v1() ? a.kind))
      select jsonb_build_object('items', coalesce(jsonb_agg(jsonb_build_object('kind', a.kind, 'ref', a.ref, 'detail', b.detail,
               'hook_detail', security.layer4_inbox_hook_call_v1((select h->>'detail_fn' from jsonb_array_elements(v_hooks->'hooks') h where h->>'kind' = a.kind limit 1), null, a.ref))), '[]'::jsonb))
        from a left join b on b.kind = a.kind and b.ref = a.ref);
  end if;

  -- CF-247 20 Oct 2026: the decisions taken here, newest first (replaces the old Review queue history)
  if p_action = 'decided' then
    return jsonb_build_object('items', coalesce((select jsonb_agg(jsonb_build_object('at', e.created_at, 'kind', e.detail->>'kind', 'choice', e.detail->>'choice', 'value', e.detail->>'value',
             'reason', e.detail->>'reason', 'provider_id', e.detail->>'provider_id',
             'provider', (select coalesce(p.display_name, p.canonical_name) from catalogue.providers p where p.id::text = e.detail->>'provider_id'),
             'by', (select u.email from auth.users u where u.id::text = e.actor::text)) order by e.id desc)
           from (select * from pipeline.admin_control_events x where x.area = 'layer4' and x.action = 'inbox_decide' order by x.id desc limit v_lim offset v_off) e), '[]'::jsonb));
  end if;
  if p_action <> 'decide' then raise exception 'unknown action %', p_action; end if;
  v_kind := p_args->>'kind'; v_ref := p_args->>'ref'; v_choice := p_args->>'choice'; v_value := nullif(btrim(p_args->>'value'), '');
  v_c := (select c from jsonb_array_elements(v_kinds->v_kind->'choices') c where c->>'key' = v_choice);
  if v_c is null then raise exception 'unknown choice % for %', v_choice, v_kind; end if;
  if v_c ? 'link' then raise exception 'this choice opens another screen'; end if;
  if v_rank < coalesce((v_c->>'rank')::int, 4) then raise exception 'your role cannot make this choice' using errcode = '42501'; end if;  -- fixed: university and value choices need Pipeline Operator or above unless the choice names a higher rank
  -- a registered kind or recovery choice is decided by its own function, which checks the item, enforces its rules and writes its own audit row
  if v_c ? 'hook' then
    v_fn := (select h->>'decide_fn' from jsonb_array_elements(v_hooks->'hooks') h where h->>'id' = v_c->>'hook');
    if v_fn is null then raise exception 'this choice is not available yet'; end if;
    execute format('select %s($1, $2, $3, $4)', v_fn) into v_r using v_ref, v_choice, v_value, coalesce(nullif(btrim(p_args->>'reason'), ''), v_c->>'reason', '');
    -- CF-247 decision 12:24 §4: the reply carries its normalised acknowledgement, read from the records just written
    return security.layer4_action_ack_v1(v_kind, v_ref, jsonb_build_object('ok', coalesce((v_r->>'ok')::boolean, false), 'kind', v_kind, 'choice', v_choice, 'returns', coalesce(v_r->>'returns', v_c->>'returns'),
                              'result', v_r->'result', 'ref', v_ref, 'event_id', v_r->'event_id', 'request', v_r->'request', 'outcome', v_r->'outcome', 'hook', v_c->>'hook'));
  end if;
  v_reason := coalesce(nullif(btrim(p_args->>'reason'), ''), v_c->>'reason', '');
  if length(v_reason) < 4 then raise exception 'give a reason (kept with the decision)'; end if;
  if v_c->>'input' = 'url' and (v_value is null or v_value !~* '^https?://[^\s/]+\.[^\s]+$') then raise exception 'enter the full web address (https://…)'; end if;
  select i.provider_id, i.detail into v_pid, v_det from security.layer4_inbox_items_v2(null, v_kind, array[v_kind || ':' || v_ref], true) i;
  if v_det is null then raise exception 'this item is no longer waiting (someone may have decided it)'; end if;
  -- CF-247 mandate 16:32 §8: the same decision sent again returns the first; a retry on an unchanged stop is refused (both audited, never taken)
  v_det := v_det || jsonb_build_object('_guard', security.layer4_decide_guard_v1(v_kind, v_ref, v_choice, v_pid));
  if v_det->'_guard' is not null and jsonb_typeof(v_det->'_guard') = 'object' then
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('layer4', 'inbox_refused', v_kind || ':' || v_ref, jsonb_build_object('kind', v_kind, 'ref', v_ref, 'choice', v_choice, 'value', v_value, 'reason', v_reason, 'provider_id', v_pid,
            'result', v_det->'_guard'), auth.uid()) returning id into v_event;
    return security.layer4_action_ack_v1(v_kind, v_ref, jsonb_build_object('ok', false, 'kind', v_kind, 'choice', v_choice, 'ref', v_ref, 'event_id', v_event,
                                         'request', v_det->'_guard'->>'request', 'result', v_det->'_guard'));
  end if;
  v_det := v_det - '_guard';

  -- SS-016 fee check (1 Nov 2026): an address on a fee-check item was taken as a plain Approve and admitted the proposed fee (46 decisions
  -- on 30 Oct). A fee check is admitted or not; a different course page is set on the course record.
  if v_kind = 'course_link' and v_det->>'field_code' = 'provider_current_tuition_validation' and v_choice = 'enter' then
    raise exception 'this is a fee check: admit the proposed fee or do not admit it. A different course page is set on the course record';
  end if;

  -- 24 Oct 2026 (hotfix D1): a course-link row that holds a fee (identity re-verification quarantine, fee floor) is not a link decision
  if v_kind = 'course_link' and v_det->>'field_code' = 'provider_current_tuition' and v_choice in ('use', 'enter') then
    if v_choice = 'use' then raise exception 'this item holds a fee, not a new page: enter the course page''s address, or keep the page we hold'; end if;
    v_r := security.layer4_fee_item_rebind_v1(v_ref::uuid, v_value, v_reason);
  elsif v_kind in ('no_page_first_run', 'conjoint_first_run') then
    -- hotfix 26 Oct 2026: a university's first run (no page published / conjoint rule); applied by security.no_page_review_apply_v1
    if v_choice = 'has_page' then
      begin
        v_ids := array(select jsonb_array_elements_text(v_value::jsonb)::uuid);
      exception when others then raise exception 'tick the sample courses that have their own page';
      end;
      if coalesce(array_length(v_ids, 1), 0) = 0 then raise exception 'tick the sample courses that have their own page'; end if;
      if exists (select 1 from unnest(v_ids) x(id) where not exists (select 1 from pipeline.course_no_page n where n.review_item_id = v_ref::uuid and n.course_id = x.id)) then
        raise exception 'a ticked course is not in this sample';
      end if;
    end if;
    v_r := public.layer4_review_decide(v_ref::uuid,
             case v_choice when 'approve' then 'approve' when 'reject' then 'reject' else 'edit_and_approve' end, v_reason,
             case v_choice when 'has_page' then jsonb_build_object('has_page_course_ids', to_jsonb(v_ids))
                           when 'parent' then jsonb_build_object('parent_url', v_value) end);
  elsif v_kind = 'aer_review' then
    -- CF-247 A1-A3 (Platform Admin 30 Oct 2026 06:53): one AER item at a time; Approve except sends the ticked rows to leave out
    if v_choice = 'approve_except' then
      begin
        v_ids := array(select jsonb_array_elements_text(v_value::jsonb)::uuid);
      exception when others then raise exception 'tick the rows to leave out';
      end;
      if coalesce(array_length(v_ids, 1), 0) = 0 then raise exception 'tick the rows to leave out'; end if;
    end if;
    v_r := public.layer4_review_decide(v_ref::uuid, case v_choice when 'approve' then 'approve' when 'reject' then 'reject' else 'edit_and_approve' end, v_reason,
             case when v_choice = 'approve_except' then jsonb_build_object('mode', 'approve_except', 'exclude_row_ids', to_jsonb(v_ids)) end);
  elsif v_kind = 'provider_description' then
    -- CF-247 P1 (Platform Admin 2 Nov 2026 10:28): a university description is approved as read or rejected, never edited
    v_r := public.layer4_review_decide(v_ref::uuid, case v_choice when 'approve' then 'approve' else 'reject' end, v_reason, null);
  elsif v_kind = 'course_link' and v_choice = 'refuse' then
    -- mandate 3 Nov 2026 20:47 §5: refuse the proposed page without claiming a held page
    v_r := security.layer4_course_link_refuse_v1(v_ref::uuid, v_reason);
  elsif v_kind = 'course_page_needed' then
    -- Decision 179 (Platform Admin 3 Nov 2026 20:29): add the page, search again, or record that no page exists
    v_r := security.course_page_needed_decide_v1(v_ref::uuid, v_choice, v_value, v_reason);
  elsif v_kind = 'held_scholarship' and v_choice = 'duplicate' then
    -- handover 3 Nov 2026 Priority 2 item 8: close a held scholarship as a duplicate of a published one (the reviewer names it)
    v_r := security.scholarship_duplicate_close_v1(v_ref::bigint, v_value, v_reason);
  elsif v_kind = 'course_link' then
    v_r := public.layer4_review_decide(v_ref::uuid, case v_choice when 'keep' then 'reject' when 'use' then 'approve' else 'edit_and_approve' end, v_reason,
                                       case when v_choice = 'enter' then to_jsonb(v_value) end);
  elsif v_kind = 'held_scholarship' then
    v_r := public.admin_scholarship_ai('review_decide', jsonb_build_object('review_id', v_ref::bigint, 'decision', case when v_choice = 'publish' then 'admit' else 'refuse' end,
                                                                         'extraction_id', v_det->'extraction_id', 'reason', v_reason));
  elsif v_kind = 'provider_departure' then  -- CF-247 20 Oct 2026: from the retired Review queue (Provider departures); Platform Admin
    if v_choice = 'merged' then
      select array_agg(p.id) into v_ids from catalogue.providers p
       where p.lifecycle_status = 'active' and p.id <> v_pid and p.country_id = (select q.country_id from catalogue.providers q where q.id = v_pid)
         and (lower(coalesce(p.display_name, p.canonical_name)) = lower(v_value)
              or p.id in (select r.provider_id from catalogue.provider_registrations r where upper(r.registration_code) = upper(v_value)));
      if coalesce(array_length(v_ids, 1), 0) <> 1 then raise exception 'enter the successor''s exact name or its CRICOS or NZQA code (% found)', coalesce(array_length(v_ids, 1), 0); end if;
    end if;
    v_r := public.layer4_provider_departure_decide(v_ref::bigint, v_choice, case when v_choice = 'merged' then v_ids[1] end, v_reason);
  elsif v_kind = 'counsellor_report' then  -- CF-247 20 Oct 2026: closed here (Coverage › Counsellor reports retired); Zoho reads the outcome back
    v_r := public.admin_counsellor_reports('close', jsonb_build_object('ids', jsonb_build_array(v_ref), 'outcome', case v_choice when 'report_fixed' then 'fixed' else 'not_changed' end, 'reason', v_reason));
  elsif v_choice = 'website' then
    v_r := public.admin_provider_website_set(v_pid, v_value);
    if v_kind in ('pages_not_found', 'site_down') then
      v_r := v_r || jsonb_build_object('released', security.flag_release_v1((v_det->>'flag_id')::bigint, v_actor, 'person', 'Layer 4: website changed to ' || v_value || '. ' || v_reason, jsonb_build_object('user_id', auth.uid()), false));
    end if;
  elsif v_choice in ('release', 'keep') then
    v_r := security.flag_release_v1((v_det->>'flag_id')::bigint, v_actor, 'person', 'Layer 4: ' || v_reason, jsonb_build_object('user_id', auth.uid()), false);
  elsif v_choice = 'wait' then
    update pipeline.enrichment_flags set flagged_at = now() where id = (v_det->>'flag_id')::bigint;  -- asked again after the waiting period
    v_r := jsonb_build_object('waiting', true);
  elsif v_choice = 'cricos_only' then
    v_r := public.admin_adapter_build('set_wave', jsonb_build_object('wave', 'cricos-only', 'provider_ids', jsonb_build_array(v_pid)));
  elsif v_choice = 'rebuild' then
    v_r := public.admin_adapter_build('build', jsonb_build_object('provider_ids', jsonb_build_array(v_pid), 'reason', 'Layer 4: ' || v_reason));
  elsif v_choice = 'retry' then
    v_r := public.admin_provider_onboarding('retry', jsonb_build_object('ids', jsonb_build_array((v_det->>'onboarding_id')::uuid), 'reason', 'Layer 4: ' || v_reason));
  elsif v_choice = 'archive' then
    v_r := public.admin_provider_archive(v_pid, 'Layer 4: ' || v_reason, false);
  elsif v_choice = 'archive_course' then
    v_r := public.admin_course_edit((v_det->>'course_id')::uuid, 'archive', jsonb_build_object('reason', 'Layer 4: ' || v_reason));
    perform security.flag_release_v1((v_det->>'flag_id')::bigint, v_actor, 'person', 'Layer 4: course archived. ' || v_reason, jsonb_build_object('user_id', auth.uid()), false);
  else
    raise exception 'choice % is not handled', v_choice;
  end if;
  -- CF-247 mandate 16:32 §8: whether the item is still waiting after the decision, so a decision that did not apply is never recorded as done
  if jsonb_typeof(v_r) = 'object' or v_r is null then
    v_r := coalesce(v_r, '{}'::jsonb) || jsonb_build_object('still_waiting', exists (select 1 from security.layer4_inbox_items_v2(null, v_kind, array[v_kind || ':' || v_ref], false)));
  end if;
  if coalesce(v_r->>'still_waiting', '') = 'false' then
    update pipeline.layer4_item_groups set state = 'closed', closed_at = now() where kind = v_kind and ref = v_ref and state = 'waiting';
  end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('layer4', 'inbox_decide', v_kind || ':' || v_ref, jsonb_build_object('kind', v_kind, 'ref', v_ref, 'choice', v_choice, 'value', v_value, 'reason', v_reason, 'provider_id', v_pid, 'result', v_r), auth.uid())
  returning id into v_event;
  -- UR-06 (1 Nov 2026): the reply names the audit event and what the decision actually did, read back from its destination
  return security.layer4_action_ack_v1(v_kind, v_ref, jsonb_build_object('ok', true, 'kind', v_kind, 'choice', v_choice, 'returns', v_c->>'returns', 'result', v_r, 'ref', v_ref, 'event_id', v_event,
                            'outcome', security.layer4_decision_outcome_v1(v_kind, v_choice, v_r)));
end $_$;


