CREATE OR REPLACE FUNCTION "public"."admin_pipeline_settings_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_fc record;
begin
  if auth.uid() is null or security.current_role_rank() < 4 then raise exception 'Pipeline Operator role required' using errcode = '42501'; end if;
  select billing_config into v_fc from pipeline.layer2_acquisition_providers where provider_key = 'firecrawl';
  return jsonb_build_object(
    'can_change', security.current_role_rank() >= 6,
    'course_pages', jsonb_build_object(
      -- v2.15.269: job sizes are in the settings register (Pipeline settings › Job sizes)
      'matcher_prepare_universities', security.pipeline_num_v1('batch.ai_match_prepare_universities', null)::int,
      'matcher_prepare_courses', security.pipeline_num_v1('batch.ai_match_prepare_courses', null)::int,
      'matcher_items_per_minute', security.pipeline_num_v1('batch.ai_match', null)::int,
      'matcher_concurrency', security.pipeline_num_v1('concurrency.ai_match', null)::int,
      'search_per_minute', security.pipeline_num_v1('batch.link_search_worker', null)::int,
      'search_monthly_credit_cap', (select monthly_credit_cap from pipeline.course_link_search_settings limit 1),
      'queued', jsonb_build_object('matcher_ready', (select count(*) from pipeline.coverage_ai_match where state = 'ready'),
                                   'matcher_never_offered', (select count(*) from pipeline.coverage_ai_match where state = 'none'),
                                   'searches_queued', (select count(*) from pipeline.course_link_search where state = 'queued')),
      'priority_countries', (select coalesce(jsonb_agg(k.iso_alpha2 order by p.sort), '[]'::jsonb) from pipeline.priority_pins p join ref.countries k on k.id = p.target_id where p.kind = 'country')),
    'reading', jsonb_build_object(
      'read_batch_per_30s', security.pipeline_num_v1('batch.coverage_read', null)::int,
      'pages_waiting', (select count(*) from pipeline.coverage_course_pages where status = 'bound' and read_status is null)),
    'identity', (select jsonb_object_agg(k.iso_alpha2, jsonb_build_object('active', c.active, 'currency', c.currency_code, 'identities', c.identities, 'approved_ref', c.approved_ref, 'min_annual_international', c.min_annual_international))
                   from pipeline.coverage_admission_countries c join ref.countries k on k.id = c.country_id),
    -- v2.15.269: the Layer 3 block is removed (Layer 3 retired 12 Oct 2026)
    'budgets', jsonb_build_object(
      'firecrawl_monthly_limit', (v_fc.billing_config->>'monthly_vendor_units_limit')::int,
      'firecrawl_stop_at_remaining', (v_fc.billing_config->>'stop_at_vendor_units_remaining')::int,
      'firecrawl_used_this_month', (select coalesce(sum(units), 0) from pipeline.coverage_vendor_usage where at >= date_trunc('month', now())),
      'firecrawl_by_purpose', (select jsonb_object_agg(purpose, u) from (select purpose, sum(units) u from pipeline.coverage_vendor_usage where at >= date_trunc('month', now()) group by 1) z),
      'openrouter', (select jsonb_build_object('remaining_usd', remaining_usd, 'observed_at', observed_at) from pipeline.layer3_openrouter_observations where kind = 'credits' order by observed_at desc limit 1)),
    'recent_changes', (select coalesce(jsonb_agg(jsonb_build_object('at', created_at, 'area', area, 'action', action, 'target', target) order by created_at desc), '[]'::jsonb)
                         from (select * from pipeline.admin_control_events where area in ('settings', 'layer3', 'automations', 'course_link_search', 'requeue') order by created_at desc limit 20) e));
end $$;


ALTER FUNCTION "public"."admin_pipeline_settings_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_pipeline_settings_write"("p_key" "text", "p_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v int; v_n numeric; v_txt text; v_before jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  v_before := public.admin_pipeline_settings_read();
  case p_key
    -- v2.15.269: job sizes are settings in the register; the job reads them, it is not rewritten
    when 'course_pages.matcher_prepare_universities' then
      v := (p_value#>>'{}')::int; if v < 1 or v > 500 then raise exception 'between 1 and 500'; end if;
      update pipeline.platform_toolset_settings set value = to_jsonb(v), reason = 'Pipeline settings', updated_by = auth.uid(), updated_at = now() where toolset_key = 'pipeline' and key = 'batch.ai_match_prepare_universities';
    when 'course_pages.matcher_prepare_courses' then
      v := (p_value#>>'{}')::int; if v < 1 or v > 5000 then raise exception 'between 1 and 5,000'; end if;
      update pipeline.platform_toolset_settings set value = to_jsonb(v), reason = 'Pipeline settings', updated_by = auth.uid(), updated_at = now() where toolset_key = 'pipeline' and key = 'batch.ai_match_prepare_courses';
    when 'course_pages.matcher_items_per_minute' then
      v := (p_value#>>'{}')::int; if v < 1 or v > 200 then raise exception 'between 1 and 200'; end if;
      update pipeline.platform_toolset_settings set value = to_jsonb(v), reason = 'Pipeline settings', updated_by = auth.uid(), updated_at = now() where toolset_key = 'pipeline' and key = 'batch.ai_match';
    when 'course_pages.matcher_concurrency' then
      v := (p_value#>>'{}')::int; if v < 1 or v > 24 then raise exception 'between 1 and 24'; end if;
      update pipeline.platform_toolset_settings set value = to_jsonb(v), reason = 'Pipeline settings', updated_by = auth.uid(), updated_at = now() where toolset_key = 'pipeline' and key = 'concurrency.ai_match';
    when 'course_pages.search_per_minute' then
      v := (p_value#>>'{}')::int; if v < 1 or v > 120 then raise exception 'between 1 and 120'; end if;
      update pipeline.platform_toolset_settings set value = to_jsonb(v), reason = 'Pipeline settings', updated_by = auth.uid(), updated_at = now() where toolset_key = 'pipeline' and key = 'batch.link_search_worker';
    when 'course_pages.search_monthly_credit_cap' then
      perform public.admin_course_link_search_settings((p_value#>>'{}')::int);
    when 'reading.read_batch_per_30s' then
      v := (p_value#>>'{}')::int; if v < 10 or v > 200 then raise exception 'between 10 and 200'; end if;
      update pipeline.platform_toolset_settings set value = to_jsonb(v), reason = 'Pipeline settings', updated_by = auth.uid(), updated_at = now() where toolset_key = 'pipeline' and key = 'batch.coverage_read';
    -- v2.15.269: the Layer 3 settings are removed (Layer 3 retired 12 Oct 2026; its jobs no longer exist)
    when 'identity.attribute' then
      if not (p_value->>'attribute') in ('official_url', 'english', 'intakes', 'tuition') then raise exception 'attribute must be official_url, english, intakes or tuition'; end if;
      if exists (select 1 from jsonb_array_elements_text(p_value->'identities') x where x not in ('cricos_code', 'nzqa_code', 'exact_title', 'title_level', 'field_award', 'degree_name', 'manual', 'host_page', 'adapter_code', 'adapter_title')) then raise exception 'unknown identity'; end if;
      update pipeline.coverage_admission_countries c
         set identities = jsonb_set(c.identities, array[p_value->>'attribute'], coalesce(p_value->'identities', '[]'::jsonb), true), updated_at = now(),
             approved_ref = c.approved_ref || format('; Settings page, Platform Admin %s (%s: %s)', to_char(now() at time zone 'Australia/Melbourne', 'DD Mon YYYY HH24:MI'), p_value->>'attribute', p_value->'identities')
        from ref.countries k where k.id = c.country_id and k.iso_alpha2 = p_value->>'country';
      if not found then raise exception 'country % not found', p_value->>'country'; end if;
    -- 23 Oct 2026 (NZ brief C3): the international fee floor per country, in its currency; null switches the floor off
    when 'fee.floor' then
      if p_value->>'value' is not null and ((p_value->>'value')::numeric <= 0 or (p_value->>'value')::numeric > 200000) then raise exception 'between 1 and 200,000, or empty for no floor'; end if;
      update pipeline.coverage_admission_countries c
         set min_annual_international = nullif(p_value->>'value', '')::numeric, updated_at = now(),
             approved_ref = c.approved_ref || format('; Settings page, Platform Admin %s (fee floor: %s)', to_char(now() at time zone 'Australia/Melbourne', 'DD Mon YYYY HH24:MI'), coalesce(p_value->>'value', 'none'))
        from ref.countries k where k.id = c.country_id and k.iso_alpha2 = p_value->>'country';
      if not found then raise exception 'country % not found', p_value->>'country'; end if;
    else raise exception 'unknown setting %', p_key;
  end case;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('settings', 'change', p_key, jsonb_build_object('value', p_value, 'before', v_before #> string_to_array(p_key, '.')), auth.uid());
  return public.admin_pipeline_settings_read();
end $$;


ALTER FUNCTION "public"."admin_pipeline_settings_write"("p_key" "text", "p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_pipeline_yield"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 5 then raise exception 'PIM Admin role or above required' using errcode = '42501'; end if;
  -- CF-247 P0 mandate 3 Nov 2026 §6: each lane's work, holds and cost beside the stage yield
  return security.pipeline_yield_v1(nullif(p_args->>'hours', '')::int) || jsonb_build_object('lane_status', security.lane_status_v1())
         -- CF-247 mandate 3 Nov 2026 12:04 §5: the per-field backlog, measured by the platform
         || jsonb_build_object('field_backlog', security.field_backlog_v1(nullif(p_args->>'country', '')))
         -- CF-247 IQ-00066: plans finished by outcome (a done plan with no step done moved no data), steps and tasks not needed
         || jsonb_build_object('plan_outcomes', security.plan_outcomes_v1());
end $$;


ALTER FUNCTION "public"."admin_pipeline_yield"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_platform_alerts"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', '')); v_id uuid; v_n int;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 4 then raise exception 'not allowed' using errcode = '42501'; end if;
  if p_action = 'read' then
    return jsonb_build_object(
      'can_change', coalesce(v_rank, 0) >= 6,
      'settings', jsonb_build_object(
        'delivery_enabled', coalesce((security.toolset_setting('pipeline', 'alerts.delivery_enabled') #>> '{}')::boolean, false),
        'webhook_enabled', coalesce((security.toolset_setting('pipeline', 'alerts.webhook_enabled') #>> '{}')::boolean, false),
        'webhook_address_stored', exists (select 1 from vault.secrets s where s.name = 'studysearch_alert_webhook_url'),
        'test_mode', coalesce((security.toolset_setting('pipeline', 'alerts.test_mode') #>> '{}')::boolean, false),
        'min_severity', security.pipeline_num_v1('alerts.min_severity', 3), 'confirm_minutes', security.pipeline_num_v1('alerts.confirm_minutes', 15),
        'cooldown_minutes', security.pipeline_num_v1('alerts.cooldown_minutes', 60), 'reminder_hours', security.pipeline_num_v1('alerts.reminder_hours', 12)),
      'counts', coalesce((select jsonb_object_agg(x.status, x.n) from (select a.status, count(*) n from pipeline.platform_alerts a where a.created_at > now() - interval '7 days' group by 1) x), '{}'::jsonb),
      'recent', coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (select a.id, a.kind, a.severity, a.title, a.status, a.created_at, a.sent_at, a.attempts, a.last_error
                                                                                           from pipeline.platform_alerts a order by a.created_at desc limit 12) x), '[]'::jsonb),
      'scorecards', coalesce((select jsonb_agg(s.scorecard order by s.week_start desc) from (select x.week_start, x.scorecard from pipeline.ops_scorecards x order by x.week_start desc limit 2) s), '[]'::jsonb));
  elsif p_action = 'scorecard' then
    return security.ops_scorecard_v1(coalesce(nullif(p_args->>'week_start', '')::date, date_trunc('week', (now() at time zone 'Australia/Melbourne'))::date),
             (select s.scorecard from pipeline.ops_scorecards s where s.week_start = coalesce(nullif(p_args->>'week_start', '')::date, date_trunc('week', (now() at time zone 'Australia/Melbourne'))::date)));
  end if;
  if coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action = 'acknowledge' then
    update pipeline.platform_issues set acknowledged_at = now(), acknowledged_by = auth.uid(), acknowledged_note = left(v_reason, 300)
     where id = (p_args->>'id')::uuid and resolved_at is null returning id into v_id;
    if v_id is null then raise exception 'this issue is closed or does not exist'; end if;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('platform health', 'acknowledge', v_id::text, jsonb_build_object('reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true, 'id', v_id);
  elsif p_action = 'test' then
    perform security.platform_alerts_add_v1(null, 'alerts:test', 'test', 'info', '[StudySearch] Test alert',
      'A test alert from Platform health: ' || v_reason || '. If it reached you, the alert destination works.', 'test:' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSUS'));
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('platform health', 'alert_test', 'alerts', jsonb_build_object('reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true);
  end if;
  raise exception 'unknown action';
end $$;


ALTER FUNCTION "public"."admin_platform_alerts"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_platform_alerts"("p_action" "text", "p_args" "jsonb") IS 'StudySearch SS-014C/D (31 Oct 2026): Platform health › Alerts and weekly scorecard. read and scorecard rank 4+; acknowledge an issue and send a test alert: Platform Admin (rank 6) with a reason, logged in admin_control_events. Admin only; never part of the consumer API.';



CREATE OR REPLACE FUNCTION "public"."admin_platform_cost_model_save_v1"("p_item_key" "text", "p_monthly_usd" numeric, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'public'
    AS $$
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  if security.current_role_rank() < 6 then raise exception 'Platform Admin role is required' using errcode='42501'; end if;
  if p_monthly_usd is null or p_monthly_usd < -100000 or p_monthly_usd > 100000 then raise exception 'monthly amount out of range' using errcode='22023'; end if;
  update pipeline.platform_cost_model set monthly_usd=p_monthly_usd, notes=coalesce(p_notes,notes), updated_by=auth.uid(), updated_at=now()
   where item_key=p_item_key and basis<>'usage_actual';
  if not found then raise exception 'unknown or usage-based cost item' using errcode='22023'; end if;
  return public.admin_platform_resources_read_v1(30);
end $$;


ALTER FUNCTION "public"."admin_platform_cost_model_save_v1"("p_item_key" "text", "p_monthly_usd" numeric, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_platform_notices_read"("p_layer" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v jsonb;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 3 then raise exception 'assigned StudySearch role required' using errcode = '42501'; end if;
  v := security.platform_notices_cached_v1(true);  -- CF-247 W35: the cached snapshot (job admin-read-snapshots)
  return jsonb_build_object('can_manage', v_rank >= 6, 'generated_at', now(), 'snapshot', security.admin_read_snapshot_meta_v1('platform_notices'),
    'notices', coalesce((select jsonb_agg(n || jsonb_build_object('acknowledged', a.acknowledged_at is not null and a.acknowledged_at >= (n->>'last_at')::timestamptz,
                                                                   'acknowledged_at', a.acknowledged_at, 'ack_reason', a.reason)
                                          order by case n->>'severity' when 'high' then 0 when 'warning' then 1 else 2 end, (n->>'last_at') desc)
                         from jsonb_array_elements(v) n left join pipeline.platform_notice_acks a on a.notice_key = n->>'key'
                         where p_layer is null or (n->>'layer')::int = p_layer), '[]'::jsonb));
end $$;


ALTER FUNCTION "public"."admin_platform_notices_read"("p_layer" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_platform_resources_read_v1"("p_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'public'
    AS $$
declare v jsonb; d int := greatest(7,least(coalesce(p_days,30),180)); cp pipeline.platform_compute_profile%rowtype; growth numeric; latest pipeline.platform_resource_observations%rowtype;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  if security.current_role_rank() < 5 then raise exception 'PIM Admin role is required' using errcode='42501'; end if;
  select * into cp from pipeline.platform_compute_profile where id=1;
  select * into latest from pipeline.platform_resource_observations order by observed_at desc limit 1;
  with daily as (select date_trunc('day',observed_at) dd, max(db_bytes) b from pipeline.platform_resource_observations where observed_at >= now()-make_interval(days=>d) group by 1)
  select regr_slope(b, extract(epoch from dd)/86400.0) into growth from daily;
  select jsonb_build_object(
    'compute', to_jsonb(cp) - 'updated_by',
    'latest', to_jsonb(latest),
    'memory_ratio', round(latest.db_bytes::numeric/nullif(cp.memory_bytes,0),2),
    'growth_bytes_per_day', round(coalesce(growth,0)),
    'days_until_memory', case when coalesce(growth,0) > 0 and latest.db_bytes < cp.memory_bytes then floor((cp.memory_bytes-latest.db_bytes)/growth) end,
    'thresholds', (select to_jsonb(p) - 'notification_target' from pipeline.platform_capacity_policy p where environment='pilot'),
    'daily', coalesce((select jsonb_agg(x order by x->>'day') from (
        select jsonb_build_object('day',date_trunc('day',observed_at)::date,'db_bytes',max(db_bytes),'cache_hit_pct',min(cache_hit_pct),
          'cron_failures',sum(cron_failures),'cron_max_seconds',max(cron_max_seconds),'cron_max_concurrent',max(cron_max_concurrent),
          'acquisition_units',sum(coalesce((select sum((a->>'units')::numeric) from jsonb_array_elements(acquisition) a),0)),
          'ai_cost_usd',sum(ai_cost_usd)) x
        from pipeline.platform_resource_observations where observed_at >= now()-make_interval(days=>d) group by date_trunc('day',observed_at)) z),'[]'::jsonb),
    'storage', (select jsonb_build_object('evidence_object_bytes',evidence_object_bytes,'evidence_objects',evidence_object_count,'orphans',orphan_object_count,'observed_at',observed_at)
                from pipeline.platform_capacity_observations order by observed_at desc limit 1),
    'costs', (select jsonb_build_object(
        'items', coalesce(jsonb_agg(jsonb_build_object('key',item_key,'label',label,'category',category,'basis',basis,
                 'monthly_usd', case when basis='usage_actual' and category='ai' then coalesce(latest.ai_cost_mtd_usd,0) else monthly_usd end,'notes',notes) order by category, item_key),'[]'::jsonb),
        'total_monthly_usd', sum(case when basis='usage_actual' and category='ai' then coalesce(latest.ai_cost_mtd_usd,0) else monthly_usd end),
        'acquisition_units_mtd', latest.acquisition_units_mtd, 'acquisition_cost_mtd_usd', latest.acquisition_cost_mtd_usd)
      from pipeline.platform_cost_model),
    'can_edit', security.current_role_rank() >= 6)
  into v;
  return v;
end $$;


ALTER FUNCTION "public"."admin_platform_resources_read_v1"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_policy_tables_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v jsonb := '[]'::jsonb; t record; v_rows jsonb;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 3 then raise exception 'assigned StudySearch role required' using errcode = '42501'; end if;
  for t in select p.tbl, min(p.key_col) key_col, jsonb_agg(jsonb_build_object('col', p.col, 'label', p.label, 'unit', p.unit,
                    'type', (select c.data_type from information_schema.columns c where c.table_schema = 'pipeline' and c.table_name = p.tbl and c.column_name = p.col))) cols
             from security.policy_columns_v1() p group by p.tbl loop
    execute format('select coalesce(jsonb_agg(to_jsonb(x) order by x.%I::text), ''[]''::jsonb) from pipeline.%I x', t.key_col, t.tbl) into v_rows;
    v := v || jsonb_build_object('table', t.tbl, 'key', t.key_col, 'columns', t.cols, 'rows', v_rows);
  end loop;
  return jsonb_build_object('can_manage', v_rank >= 6, 'tables', v,
    'providers', (select coalesce(jsonb_object_agg(p.id, coalesce(p.display_name, p.canonical_name)), '{}'::jsonb) from catalogue.providers p
                   where p.id in (select provider_id from pipeline.provider_fee_profiles union select provider_id from pipeline.provider_fee_basis_rules)));
end $$;


ALTER FUNCTION "public"."admin_policy_tables_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_policy_tables_write"("p_table" "text", "p_row" "text", "p_column" "text", "p_value" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_key text; v_type text; v_before jsonb; v_txt text := p_value #>> '{}';
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(btrim(coalesce(p_reason, ''))) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  select p.key_col into v_key from security.policy_columns_v1() p where p.tbl = p_table and p.col = p_column;
  if v_key is null then raise exception 'this value cannot be changed here'; end if;
  select c.data_type into v_type from information_schema.columns c where c.table_schema = 'pipeline' and c.table_name = p_table and c.column_name = p_column;
  if v_type in ('integer', 'bigint', 'numeric') and (v_txt is null or v_txt !~ '^\d+(\.\d+)?$') then raise exception 'a number of 0 or more is needed'; end if;
  if v_type = 'boolean' and v_txt not in ('true', 'false') then raise exception 'yes or no is needed'; end if;
  if v_type = 'date' and v_txt !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'a date (YYYY-MM-DD) is needed'; end if;
  execute format('select to_jsonb(x.%I) from pipeline.%I x where x.%I::text = $1', p_column, p_table, v_key) into v_before using p_row;
  execute format('update pipeline.%I set %I = $1::%s where %I::text = $2', p_table, p_column, v_type, v_key) using v_txt, p_row;
  if not found then raise exception 'row not found'; end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('policies', 'change', p_table || '.' || p_column || ':' || p_row, jsonb_build_object('before', v_before, 'after', p_value, 'reason', btrim(p_reason)), auth.uid());
  return public.admin_policy_tables_read();
end $_$;


ALTER FUNCTION "public"."admin_policy_tables_write"("p_table" "text", "p_row" "text", "p_column" "text", "p_value" "jsonb", "p_reason" "text") OWNER TO "postgres";


