CREATE OR REPLACE FUNCTION "public"."admin_provider_calendar_set"("p_provider_id" "uuid", "p_periods" "jsonb", "p_url" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_id uuid; v_src uuid; v_clean jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if not exists (select 1 from catalogue.providers where id = p_provider_id) then raise exception 'provider not found'; end if;
  if coalesce(btrim(p_url), '') !~* '^https?://' then raise exception 'the calendar page address is required'; end if;
  select jsonb_agg(jsonb_build_object('period', lower(btrim(e->>'period')), 'months', jsonb_build_array((e->>'month')::int)))
    into v_clean
    from jsonb_array_elements(coalesce(p_periods, '[]'::jsonb)) e
   where lower(btrim(e->>'period')) ~ '^(semester|trimester|term|session|study_period|teaching_period) [1-6]$' and (e->>'month') ~ '^([1-9]|1[0-2])$';
  if v_clean is null then raise exception 'give at least one period (for example semester 1) with a month from 1 to 12'; end if;
  insert into pipeline.provider_fact_sources(provider_id, kind, url, title, rank, found_via, status)
  values (p_provider_id, 'intake_calendar', btrim(p_url), 'Calendar page given by a Platform Admin', 9, 'manual', 'found')
  on conflict on constraint provider_fact_sources_key do nothing;
  select id into v_src from pipeline.provider_fact_sources where provider_id = p_provider_id and kind = 'intake_calendar' and url = btrim(p_url);
  insert into pipeline.provider_policy_proposals(provider_id, fact_source_id, kind, parser, url, style, proposal, status, decided_by, decided_at, decision_note)
  values (p_provider_id, v_src, 'intake_calendar', 'set by hand', btrim(p_url), 'by_hand', jsonb_build_object('periods', v_clean), 'approved', auth.uid(), now(), left(p_note, 500))
  returning id into v_id;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('policies', 'calendar_set', btrim(p_url), jsonb_build_object('decision', 'Decision 228', 'proposal_id', v_id, 'provider_id', p_provider_id, 'periods', v_clean), auth.uid());
  return jsonb_build_object('id', v_id, 'to_answer', (select count(*) from security.semester_intake_plan_v1(p_provider_id) r where r.outcome = 'answer'));
end $_$;


ALTER FUNCTION "public"."admin_provider_calendar_set"("p_provider_id" "uuid", "p_periods" "jsonb", "p_url" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_central_page"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', '')); v_pid uuid := (p_args->>'provider_id')::uuid;
        v_kind text := p_args->>'kind'; v_url text := btrim(coalesce(p_args->>'url', '')); v_id uuid;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if p_action not in ('add', 'read_again') then raise exception 'unknown action'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if not exists (select 1 from catalogue.providers p where p.id = v_pid) then raise exception 'unknown provider'; end if;
  if coalesce(v_kind, '') not in ('english_policy', 'intake_calendar', 'fee_schedule') then raise exception 'kind must be english_policy, intake_calendar or fee_schedule'; end if;
  if v_url !~ '^https?://[^ ]+$' or length(v_url) not between 12 and 500 then raise exception 'give the full page address (http or https)'; end if;
  insert into pipeline.provider_fact_sources(provider_id, kind, url, title, rank, found_via, status)
    values (v_pid, v_kind, v_url, nullif(btrim(coalesce(p_args->>'title', '')), ''), 9, 'manual', 'found')
  on conflict (provider_id, kind, url) do update set status = 'found', attempts = 0, rank = 9, found_via = 'manual', updated_at = now() where pipeline.provider_fact_sources.provider_id = excluded.provider_id
  returning id into v_id;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('toolsets', 'central_page_' || p_action, v_pid::text, jsonb_build_object('source_id', v_id, 'kind', v_kind, 'url', v_url, 'reason', v_reason), auth.uid());
  return jsonb_build_object('ok', true, 'source_id', v_id, 'note', 'The page is read through Firecrawl by the provider-facts job within about 10 minutes, then parsed into a proposal for approval in Layer 4 Review › Attributes.');
end $_$;


ALTER FUNCTION "public"."admin_provider_central_page"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_create"("p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_id uuid := gen_random_uuid(); v_name text := nullif(btrim(coalesce(p_args->>'name', '')), ''); v_country uuid := nullif(p_args->>'country_id', '')::uuid;
        v_web text := nullif(btrim(coalesce(p_args->>'website', '')), '');
begin
  if auth.uid() is null or security.current_role_rank() < 5 then raise exception 'PIM Operator role or above required' using errcode = '42501'; end if;
  if v_name is null then raise exception 'enter the provider name'; end if;
  if v_country is null or not exists (select 1 from ref.countries where id = v_country) then raise exception 'choose the country'; end if;
  if v_web is not null and v_web !~* '^https?://[^\s/]+\.[^\s]+$' then raise exception 'enter a full web address starting with https://'; end if;
  if exists (select 1 from catalogue.providers where lower(canonical_name) = lower(v_name) and country_id = v_country) then raise exception 'a provider with this name already exists in that country'; end if;
  perform set_config('cf.manual_edit', 'on', true);
  insert into catalogue.providers(id, stable_key, canonical_name, display_name, country_id, subdivision_id, website, primary_city, lifecycle_status)
  values (v_id, 'manual:' || v_id, v_name, v_name, v_country, nullif(p_args->>'subdivision_id', '')::uuid, v_web, nullif(btrim(coalesce(p_args->>'city', '')), ''), 'active');
  if v_web is not null then
    insert into pipeline.coverage_provider_discovery(provider_id, website, status, attempts, next_due_at, updated_at) values (v_id, v_web, 'pending', 0, now(), now())
    on conflict (provider_id) do nothing;
  end if;
  insert into pipeline.manual_edit_log(entity, entity_id, field, action, after, reason, actor)
  values ('provider', v_id, null, 'create', p_args, nullif(btrim(coalesce(p_args->>'reason', '')), ''), auth.uid());
  return public.admin_provider_edit_read(v_id);
end $_$;


ALTER FUNCTION "public"."admin_provider_create"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_credit_fee"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', '')); v_pid uuid; v_id uuid; v_ids uuid[]; v_src uuid; v_res jsonb; v_ev uuid;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action = 'read' then
    return coalesce((select jsonb_agg(to_jsonb(x) - 'course_ids' || jsonb_build_object('courses', cardinality(x.course_ids)) order by x.set_at desc) from pipeline.provider_credit_fees x where x.provider_id = (p_args->>'provider_id')::uuid), '[]'::jsonb);
  elsif p_action = 'add' then
    v_pid := (p_args->>'provider_id')::uuid;
    if not exists (select 1 from catalogue.providers p where p.id = v_pid) then raise exception 'unknown provider'; end if;
    if jsonb_typeof(p_args->'course_ids') <> 'array' or jsonb_array_length(p_args->'course_ids') = 0 then raise exception 'give the courses the rate applies to'; end if;
    v_ids := array(select distinct x::uuid from jsonb_array_elements_text(p_args->'course_ids') x);
    if exists (select 1 from unnest(v_ids) x where not exists (select 1 from catalogue.courses co where co.id = x and co.provider_id = v_pid)) then raise exception 'every course must belong to this university'; end if;
    if coalesce(p_args->>'source_url', '') !~ '^https?://[^ ]+$' then raise exception 'give the page that prints the rate'; end if;
    select s.id into v_src from pipeline.provider_fact_sources s where s.provider_id = v_pid and s.url = btrim(p_args->>'source_url') order by s.updated_at desc limit 1;
    if v_src is null then
      select pg.evidence_id into v_ev from pipeline.coverage_course_pages pg
       where pg.provider_id = v_pid and pg.read_status = 'read' and pg.evidence_id is not null and pg.candidates->>'final_url' = btrim(p_args->>'source_url') limit 1;
    end if;
    if v_src is null and v_ev is null then raise exception 'attach the rate page as a central page first, or give a course page read in the international view, so it is read with evidence'; end if;
    insert into pipeline.provider_credit_fees(provider_id, label, course_ids, rate, rate_credits, annual_credits, fee_year, currency_code, source_url, fact_source_id, evidence_id, reason, set_by)
      values (v_pid, btrim(coalesce(p_args->>'label', 'per-credit rate')), v_ids, (p_args->>'rate')::numeric, (p_args->>'rate_credits')::numeric, (p_args->>'annual_credits')::numeric,
              (p_args->>'fee_year')::int, upper(btrim(p_args->>'currency_code')), btrim(p_args->>'source_url'), v_src, v_ev, v_reason, auth.uid())
      returning id into v_id;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'credit_fee_add', v_pid::text, jsonb_build_object('rule_id', v_id, 'args', p_args - 'course_ids', 'courses', cardinality(v_ids), 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true, 'id', v_id, 'annual_fee', round((p_args->>'rate')::numeric / (p_args->>'rate_credits')::numeric * (p_args->>'annual_credits')::numeric, 2));
  elsif p_action = 'apply' then
    v_id := (p_args->>'id')::uuid;
    v_res := security.provider_credit_fee_apply_v1(v_id);
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'credit_fee_apply', v_id::text, jsonb_build_object('result', v_res, 'reason', v_reason), auth.uid());
    return v_res;
  elsif p_action = 'off' then
    v_id := (p_args->>'id')::uuid;
    update pipeline.provider_credit_fees set active = false, reason = v_reason, set_by = auth.uid(), set_at = now() where id = v_id;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'credit_fee_off', v_id::text, jsonb_build_object('reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true);
  end if;
  raise exception 'unknown action';
end $_$;


ALTER FUNCTION "public"."admin_provider_credit_fee"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_description_fill_v1"("p_provider_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_out jsonb := '[]'::jsonb; v_pid uuid; p catalogue.providers%rowtype; r pipeline.provider_description_reads%rowtype; v_q int := 0; v_word text;
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 3 then raise exception 'An operator is required' using errcode = '42501'; end if;
  if coalesce(array_length(p_provider_ids, 1), 0) = 0 then raise exception 'choose at least one provider'; end if;
  if array_length(p_provider_ids, 1) > security.pipeline_num_v1('pdesc.fill_max_per_click', 25) then
    raise exception 'one click fills at most % providers (Settings › Pipeline settings › Provider descriptions)', security.pipeline_num_v1('pdesc.fill_max_per_click', 25)::int;
  end if;
  if security.pipeline_num_v1('pdesc.enabled', 0) < 1 then raise exception 'The provider description reader is switched off'; end if;
  foreach v_pid in array p_provider_ids loop
    select * into p from catalogue.providers where id = v_pid;
    v_word := null;
    if p.id is null then v_word := 'not_found';
    elsif exists (select 1 from pipeline.manual_locks l where l.entity = 'provider' and l.entity_id = p.id and l.field in ('description', 'p_description', 'all')) then v_word := 'manual';
    elsif nullif(btrim(p.description), '') is not null and security.provider_description_basic_profile_v1(p.id) is null then v_word := 'has_description';
    elsif p.lifecycle_status <> 'active' or p.publication_status <> 'published' then v_word := 'not_live';
    elsif not coalesce((security.provider_description_identity_v1(p.id, coalesce((select a.source_url from pipeline.evidence_artifacts a where a.id = security.provider_description_stored_v1(p.id)), p.website))->>'ok')::boolean, false) then v_word := 'identity';
    end if;
    if v_word is null then
      select * into r from pipeline.provider_description_reads x where x.provider_id = p.id and x.state in ('queued', 'reading', 'proposed') limit 1;
      if r.id is not null and r.state in ('reading', 'proposed') then v_word := 'in_progress';
      elsif r.id is not null then
        update pipeline.provider_description_reads set next_try_at = now(), tries = 0, updated_at = now(),
               checks = coalesce(checks, '{}'::jsonb) || jsonb_build_object('on_demand', jsonb_build_object('by', auth.uid(), 'at', now()))
         where id = r.id;
        v_word := 'queued'; v_q := v_q + 1;
      else
        -- a new read: earlier reads stay as they are (the admission ledger refers to them)
        insert into pipeline.provider_description_reads(provider_id, state, next_try_at, reason, checks)
        values (p.id, 'queued', now(), 'Operator asked to fill the description (on demand)', jsonb_build_object('on_demand', jsonb_build_object('by', auth.uid(), 'at', now())));
        v_word := 'queued'; v_q := v_q + 1;
      end if;
    end if;
    v_out := v_out || jsonb_build_object('provider_id', v_pid, 'name', coalesce(p.display_name, p.canonical_name), 'outcome', v_word);
  end loop;
  if v_q > 0 then
    perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'provider_description', 'limit', security.pipeline_num_v1('batch.provider_description', 3)::int));
  end if;
  return jsonb_build_object('queued', v_q, 'providers', v_out);
end $$;


ALTER FUNCTION "public"."admin_provider_description_fill_v1"("p_provider_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_provider_description_fill_v1"("p_provider_ids" "uuid"[]) IS 'CF-247 F-PDESC (20261112010000): the operator''s Fill description. Queues each provider on demand (not held by the lane AI and Firecrawl limits) and starts a worker call; skips a manually maintained description.';



CREATE OR REPLACE FUNCTION "public"."admin_provider_description_funnel_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_out jsonb; v_job jsonb; v_last jsonb := null; v_sel jsonb; v_elig int; v_pending int; v_pmax numeric := security.pipeline_num_v1('pdesc.pending_max', 10);
        v_size int := least(security.pipeline_num_v1('pdesc.queue_per_run', 10), security.pipeline_num_v1('pdesc.pending_max', 10), security.pipeline_num_v1('run_now.pilot_cap', 20))::int;
        v_stall text; v_policy int; v_run int; v_spent numeric; v_fc numeric; v_big boolean; v_pat text[];
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'curator role required' using errcode = '42501'; end if;
  -- many providers in scope (QA B2): identity and the stored page are counted from the register in one pass instead of provider by provider, so the screen stays inside its time-out
  select count(*) > security.pipeline_num_v1('pdesc.funnel_detail_max', 400) into v_big from catalogue.providers p join ref.countries k on k.id = p.country_id left join ref.provider_types t on t.id = p.provider_type_id
   where p.lifecycle_status = 'active' and coalesce(security.toolset_setting('pipeline', 'pdesc.countries'), '["AU"]'::jsonb) ? k.iso_alpha2::text and security.pdesc_type_in_scope_v1(t.code);
  v_pat := security.pdesc_about_like_patterns_v1();
  with base as (
    select p.id, p.stable_key, p.website, nullif(btrim(p.description), '') is not null has_desc, nullif(btrim(p.website), '') is not null has_site,
           p.lifecycle_status = 'active' and p.publication_status = 'published' and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id) live,
           coalesce(security.toolset_setting('pipeline', 'pdesc.countries'), '["AU"]'::jsonb) ? k.iso_alpha2::text
             and security.pdesc_type_in_scope_v1(t.code) policy_scope
      from catalogue.providers p join ref.countries k on k.id = p.country_id left join ref.provider_types t on t.id = p.provider_type_id
     where p.lifecycle_status = 'active'),
  st as (
    select b.*, case when b.live and b.policy_scope then case when v_big and jsonb_array_length(coalesce(security.toolset_setting('pipeline', 'pdesc.provider_keys'), '[]'::jsonb)) = 0 then true else security.provider_description_scope_v1(b.id) end end run_scope,
           case when b.live and b.policy_scope then case when v_big then b.has_site and not exists (select 1 from pipeline.provider_identity_findings f where f.provider_id = b.id and f.state = 'open')
                                                                           and not exists (select 1 from catalogue.providers o where o.id <> b.id and o.lifecycle_status = 'active' and security.site_host_v1(o.website) = security.site_host_v1(b.website))
                                                 else coalesce((security.provider_description_identity_v1(b.id, b.website)->>'ok')::boolean, false) end end identity_ok,
           case when b.live and b.policy_scope then case when v_big then security.provider_description_stored_candidate_v1(b.id, v_pat) else security.provider_description_stored_v1(b.id) is not null end end stored_page,
           lr.state, lr.rule, lr.published_at, lr.consumer_checked_at, lr.created_at read_created
      from base b left join lateral (select x.state, x.rule, x.published_at, x.consumer_checked_at, x.created_at from pipeline.provider_description_reads x where x.provider_id = b.id order by x.created_at desc, x.id desc limit 1) lr on true)
  select jsonb_build_object(
    'contract', 'provider-description-funnel-v1', 'as_at', now(),
    'stages', jsonb_build_array(
      jsonb_build_object('key', 'registry', 'label', 'Active providers', 'n', count(*)),
      jsonb_build_object('key', 'live', 'label', 'Active, published, not hidden', 'n', count(*) filter (where live)),
      jsonb_build_object('key', 'website', 'label', 'With a website', 'n', count(*) filter (where live and has_site)),
      jsonb_build_object('key', 'policy_scope', 'label', 'In the set countries and institution types', 'n', count(*) filter (where live and policy_scope)),
      jsonb_build_object('key', 'run_scope', 'label', 'In the run scope (pdesc.provider_keys applied)', 'n', count(*) filter (where run_scope)),
      jsonb_build_object('key', 'identity_clear', 'label', 'Identity clear (policy scope)', 'n', count(*) filter (where identity_ok)),
      jsonb_build_object('key', 'stored_page', 'label', 'Official About page already stored (policy scope)', 'n', count(*) filter (where stored_page)),
      jsonb_build_object('key', 'read', 'label', 'Read at least once', 'n', count(*) filter (where state is not null)),
      jsonb_build_object('key', 'queued', 'label', 'Queued or reading', 'n', count(*) filter (where state in ('queued', 'reading'))),
      jsonb_build_object('key', 'proposed', 'label', 'Proposed, waiting for a person in Layer 4', 'n', count(*) filter (where state = 'proposed')),
      jsonb_build_object('key', 'held', 'label', 'Held by a rule', 'n', count(*) filter (where state in ('held', 'dead_letter'))),
      jsonb_build_object('key', 'rejected', 'label', 'Rejected by a person', 'n', count(*) filter (where state = 'rejected')),
      jsonb_build_object('key', 'admitted', 'label', 'Approved and admitted', 'n', count(*) filter (where state in ('admitted', 'verified'))),
      jsonb_build_object('key', 'published', 'label', 'Description held by the catalogue', 'n', count(*) filter (where has_desc and live)),
      jsonb_build_object('key', 'consumer_checked', 'label', 'Checked on the Website read', 'n', count(*) filter (where consumer_checked_at is not null))),
    'held_reasons', coalesce((select jsonb_agg(jsonb_build_object('rule', z.rule, 'state', z.state, 'n', z.n) order by z.n desc, z.rule) from (select s.rule, s.state, count(*) n from st s where s.state in ('held', 'dead_letter', 'rejected') group by 1, 2) z), '[]'::jsonb),
    'policy_scope_outside_run_scope', count(*) filter (where live and policy_scope and not run_scope),
    'oldest_open_read', min(read_created) filter (where state in ('queued', 'reading', 'proposed')))
    into v_out from st;
  v_policy := (select (x->>'n')::int from jsonb_array_elements(v_out->'stages') x where x->>'key' = 'policy_scope');
  v_run := (select (x->>'n')::int from jsonb_array_elements(v_out->'stages') x where x->>'key' = 'run_scope');
  select count(*) into v_pending from pipeline.layer4_review_items i where i.field_code = 'provider_description' and i.status = 'pending';
  v_sel := security.provider_description_selection_v1(jsonb_build_object('filter', 'all', 'prefilter', v_big, 'size', v_size, 'mode', case when security.pipeline_num_v1('pdesc.acquire_direct', 0) >= 1 then 'approved' else 'stored' end));
  v_elig := (v_sel->>'eligible')::int;
  select jsonb_build_object('name', j.jobname, 'schedule', j.schedule, 'active', j.active) into v_job from cron.job j where j.jobname = 'provider-description-read';
  if to_regclass('cron.job_run_details') is not null then
    execute $q$select jsonb_build_object('status', d.status, 'started', d.start_time, 'finished', d.end_time) from cron.job_run_details d join cron.job j on j.jobid = d.jobid where j.jobname = 'provider-description-read' order by d.start_time desc limit 1$q$ into v_last;
  end if;
  select coalesce(sum(l.cost_usd), 0) into v_spent from pipeline.ai_spend_ledger l where l.lane = 'provider_description' and l.source <> 'opening';
  select coalesce(sum(r.firecrawl_reads), 0) into v_fc from pipeline.provider_description_reads r;
  v_stall := case when security.pipeline_num_v1('pdesc.enabled', 0) < 1 then 'reader_off'
                  when coalesce((v_job->>'active')::boolean, false) is not true then 'job_paused'
                  when v_pending >= v_pmax and security.pipeline_num_v1('pdesc.machine_admit_on', 0) < 1 then 'review_full'
                  when v_elig > 0 then 'next_run_will_queue'
                  when v_policy > v_run then 'run_scope_limited_by_pdesc_provider_keys'
                  when v_pending > 0 then 'waiting_for_reviewers'
                  else 'no_eligible_provider_in_scope' end;
  return v_out || jsonb_build_object(
    'layer4', jsonb_build_object('pending', v_pending, 'pending_max', v_pmax,
       'oldest_pending', (select min(i.created_at) from pipeline.layer4_review_items i where i.field_code = 'provider_description' and i.status = 'pending'),
       'decided', (select count(*) from pipeline.layer4_review_items i where i.field_code = 'provider_description' and i.status <> 'pending')),
    'job', coalesce(v_job, '{}'::jsonb), 'last_run', v_last,
    'settings', jsonb_build_object('enabled', security.pipeline_num_v1('pdesc.enabled', 0) >= 1, 'acquire_direct', security.pipeline_num_v1('pdesc.acquire_direct', 0) >= 1,
       'acquire_firecrawl', security.pipeline_num_v1('pdesc.acquire_firecrawl', 0) >= 1, 'queue_per_run', security.pipeline_num_v1('pdesc.queue_per_run', 10),
       'pinned_providers', jsonb_array_length(coalesce(security.toolset_setting('pipeline', 'pdesc.provider_keys'), '[]'::jsonb)),
       'countries', coalesce(security.toolset_setting('pipeline', 'pdesc.countries'), '["AU"]'::jsonb), 'provider_types', coalesce(security.toolset_setting('pipeline', 'pdesc.provider_types'), '["university"]'::jsonb)),
    'spend', jsonb_build_object('ai_usd', round(v_spent, 4), 'ai_usd_max', security.pipeline_num_v1('pdesc.ai_usd_max', 1), 'firecrawl_reads', v_fc, 'firecrawl_reads_max', security.pipeline_num_v1('pdesc.firecrawl_reads_max', 0)),
    'next_run', jsonb_build_object('eligible', v_elig, 'size', v_size, 'exclusions', coalesce((select jsonb_agg(jsonb_build_object('reason', z.reason, 'n', z.n) order by z.n desc, z.reason)
                                                                                                from (select x->>'reason' reason, count(*) n from jsonb_array_elements(coalesce(v_sel->'exclusions', '[]'::jsonb)) x group by 1) z), '[]'::jsonb)),
    'stall', v_stall);
end $_$;


ALTER FUNCTION "public"."admin_provider_description_funnel_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_provider_description_funnel_v1"() IS 'Provider descriptions (lane P-DESC, 8 Nov 2026): read-only whole-catalogue funnel from registry to published, held reasons, Layer 4 waiting and oldest age, job and last run, spend and why the next run will or will not queue. Curator role or above. Reads only; no write, no decision.';



CREATE OR REPLACE FUNCTION "public"."admin_provider_description_machine_withdraw_v1"("p_provider" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin (rank 6) is needed to withdraw a machine description' using errcode = '42501'; end if; -- fixed: rank 6 is the Platform Admin role
  return security.provider_description_machine_withdraw_v1(p_provider, p_reason, auth.uid());
end $$;


ALTER FUNCTION "public"."admin_provider_description_machine_withdraw_v1"("p_provider" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_provider_description_machine_withdraw_v1"("p_provider" "uuid", "p_reason" "text") IS 'CF-247 F-PDESC: withdraw one machine-admitted provider description (restore the earlier text, keep the audit, record who and why). Platform Admin (rank 6) only; the person is recorded, not the system account.';



CREATE OR REPLACE FUNCTION "public"."admin_provider_description_prompt_v1"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_text text := btrim(coalesce(p_args->>'system_prompt', '')); v_reason text := btrim(coalesce(p_args->>'reason', '')); v_ver int;
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 3 then raise exception 'not allowed' using errcode = '42501'; end if; -- the same rank as Fill and the Enrich fields tab
  if p_action = 'read' then
    return jsonb_build_object(
      'prompt_on', security.pipeline_num_v1('pdesc.prompt_on', 0) >= 1,
      'can_edit', coalesce(security.current_role_rank(), 0) >= 6,
      'active', (select to_jsonb(x) from (select version, system_prompt, reason, created_at, activated_at from pipeline.provider_description_prompts where status = 'active') x),
      'history', (select coalesce(jsonb_agg(to_jsonb(x) order by x.version desc), '[]'::jsonb) from (select version, status, reason, created_at, activated_at, left(system_prompt, 160) preview from pipeline.provider_description_prompts order by version desc limit 20) x),
      'refused_words', security.toolset_setting('pipeline', 'pdesc.prompt_refused_words'),
      'length', jsonb_build_object('min_sentences', security.pipeline_num_v1('pdesc.min_sentences', 2), 'max_sentences', security.pipeline_num_v1('pdesc.max_sentences', 5),
                                   'min_chars', security.pipeline_num_v1('pdesc.min_chars', 150), 'max_chars', security.pipeline_num_v1('pdesc.max_chars', 900)),
      -- AI spend, Firecrawl use, controls and progress for the screens (Platform Admin 11 Nov 2026 06:11: "should be visible on UI")
      'status', jsonb_build_object(
        'ai_spent_usd', (select round(coalesce(sum(l.cost_usd), 0), 4) from pipeline.ai_spend_ledger l where l.lane = 'provider_description' and l.source <> 'opening'),
        'ai_ceiling_usd', security.pipeline_num_v1('pdesc.ai_usd_max', 1),
        'ai_today_usd', (select round(coalesce(sum(l.cost_usd), 0), 4) from pipeline.ai_spend_ledger l where l.lane = 'provider_description' and l.source <> 'opening' and l.at >= date_trunc('day', now() at time zone 'UTC') at time zone 'UTC'),
        'ai_daily_guard_usd', coalesce((security.toolset_setting('openrouter', 'guard_provider_description') #>> '{}')::numeric, 1),
        'firecrawl_used_window', (select coalesce(sum(x.firecrawl_reads), 0) from pipeline.provider_description_reads x where x.updated_at > now() - make_interval(hours => security.pipeline_num_v1('pdesc.firecrawl_window_hours', 24)::int)),
        'firecrawl_allowance', security.pipeline_num_v1('pdesc.firecrawl_reads_max', 0), 'firecrawl_window_hours', security.pipeline_num_v1('pdesc.firecrawl_window_hours', 24),
        'firecrawl_share_left_today', security.fc_budget_left_v1('provider_description'), 'firecrawl_share_day', security.fc_setting_num_v1('daily_share_pdesc', 0),
        'reader_every_minutes', security.pipeline_num_v1('pdesc.every_minutes', 10), 'batch', security.pipeline_num_v1('batch.provider_description', 3),
        'admitted_24h', (select count(*) from pipeline.provider_description_machine_admissions a where a.outcome = 'admitted' and a.created_at > now() - interval '24 hours'), -- fixed: a display window
        'described', (select count(*) from catalogue.providers p where nullif(btrim(p.description), '') is not null and p.lifecycle_status = 'active' and p.publication_status = 'published'),
        'queued', (select count(*) from pipeline.provider_description_reads x where x.state = 'queued'),
        'on_demand_waiting', (select count(*) from pipeline.provider_description_reads x where x.state in ('queued', 'reading') and security.pdesc_on_demand_live_v1(x.checks)),
        'held', (select count(*) from pipeline.provider_description_reads x where x.state = 'held'),
        'manual', (select count(*) from pipeline.manual_locks l where l.entity = 'provider' and l.field in ('description', 'p_description')),
        'self_heal_last', (select jsonb_build_object('at', d.start_time, 'status', d.status) from cron.job_run_details d join cron.job j on j.jobid = d.jobid where j.jobname = 'provider-description-self-heal' order by d.start_time desc limit 1),
        'reader_last', (select jsonb_build_object('at', d.start_time, 'status', d.status) from cron.job_run_details d join cron.job j on j.jobid = d.jobid where j.jobname = 'provider-description-read' order by d.start_time desc limit 1)));
  elsif p_action = 'save' then
    if coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
    if length(v_reason) < 4 then raise exception 'a reason is required'; end if;
    if length(v_text) < 200 then raise exception 'the prompt is too short (200 characters or more)'; end if; -- fixed: the table's own check (a prompt is never empty)
    if v_text = (select system_prompt from pipeline.provider_description_prompts where status = 'active') then raise exception 'the prompt is unchanged'; end if;
    perform pg_advisory_xact_lock(hashtext('cf247 provider description prompt'));
    select coalesce(max(version), 2) + 1 into v_ver from pipeline.provider_description_prompts;
    update pipeline.provider_description_prompts set status = 'retired' where status = 'active';
    insert into pipeline.provider_description_prompts(version, system_prompt, status, reason, created_by, activated_at, activated_by)
    values (v_ver, v_text, 'active', v_reason, auth.uid(), now(), auth.uid());
    return jsonb_build_object('ok', true, 'version', v_ver);
  end if;
  raise exception 'unknown action %', p_action;
end $$;


ALTER FUNCTION "public"."admin_provider_description_prompt_v1"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_provider_description_prompt_v1"("p_action" "text", "p_args" "jsonb") IS 'CF-247 F-PDESC (20261112010000): read and save the provider-description prompt (Models & services › AI & OpenRouter). A save is a new active version with a reason; nothing is edited in place.';



CREATE OR REPLACE FUNCTION "public"."admin_provider_description_run_v1"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_actor uuid:=auth.uid(); v_rank int:=security.current_role_rank(); c pipeline.provider_description_cohorts%rowtype;
 v_res jsonb; v_preview jsonb; v_fresh jsonb; x jsonb; v_id uuid; v_reason text:=btrim(coalesce(p_args->>'reason','')); v_n int:=0; v_run uuid; v_why text;
 v_mode text; v_args jsonb; v_ids uuid[]; v_history jsonb; v_rule text; v_diagnosis jsonb; v_context jsonb; v_issue bigint; v_ai_request bigint; v_ai_model text; v_ai_why text; v_job pipeline.automation_catalogue%rowtype; v_dispatch_error text; v_dispatch_sqlstate text;
begin
 if v_actor is null or v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;
 select * into v_job from pipeline.automation_catalogue where jobname='provider-description-read';
 if p_action='verify' and v_rank<coalesce(v_job.control_rank,6) then raise exception 'your role cannot verify this job publication' using errcode='42501'; end if;
 if p_action='capabilities' then
 return jsonb_build_object('contract','provider-description-run-v1','can_run',v_rank>=coalesce(v_job.control_rank,6),'control_rank',coalesce(v_job.control_rank,6),'reason_min_chars',security.pipeline_num_v1('pdesc.reason_min_chars',5)::int,
 'can_explain',v_rank>=coalesce(v_job.control_rank,6),'can_diagnose',security.pipeline_num_v1('ops.ai_diagnosis_on',0)>=1 and security.ai_use_allowed_v1('ops_diagnose') and nullif(security.ai_route_v1('ops_diagnosis')->>'model','') is not null,'ai_diagnosis_reason','AI assistance requires the existing approved Operations diagnosis switch, model and spending guards plus an existing open issue linked to this exact provider and evidence. Explain evidence always uses stored checks.',
 'countries',coalesce((select jsonb_agg(jsonb_build_object('code',k.iso_alpha2,'label',coalesce(to_jsonb(k)->>'name',to_jsonb(k)->>'country_name',k.iso_alpha2::text),'enabled',coalesce(security.toolset_setting('pipeline','pdesc.countries'),'[]')?k.iso_alpha2::text)) from ref.countries k where k.iso_alpha2 in ('AU','NZ','CA')),'[]'),
 'provider_types',coalesce((select jsonb_agg(jsonb_build_object('code',t.code,'label',coalesce(to_jsonb(t)->>'label',to_jsonb(t)->>'name',t.code),'enabled',coalesce(security.toolset_setting('pipeline','pdesc.provider_types'),'[]')?t.code)) from ref.provider_types t),'[]'),
 'providers',coalesce((select jsonb_agg(jsonb_build_object('provider_id',p.id,'name',coalesce(p.display_name,p.canonical_name),'country',k.iso_alpha2,'type',t.code) order by coalesce(p.display_name,p.canonical_name)) from catalogue.providers p join ref.countries k on k.id=p.country_id left join ref.provider_types t on t.id=p.provider_type_id where security.provider_description_scope_v1(p.id)),'[]'),
 'min_size',1,'max_size',security.provider_description_cohort_cap_v1(),'default_size',security.pipeline_num_v1('batch.provider_description',3)::int,
 'modes',jsonb_build_array(jsonb_build_object('id','stored','label','Stored official evidence + approved AI','allowed',true),jsonb_build_object('id','approved','label','Existing authorised acquisition + approved AI','allowed',security.pipeline_num_v1('pdesc.acquire_direct',0)>=1)),
 'model',(select security.ai_route_v1('provider_description')->>'model'),'enabled',security.pipeline_num_v1('pdesc.enabled',0)>=1,
 'job_active',coalesce((select active from cron.job where jobname='provider-description-read'),false),
 'policy',jsonb_build_object('countries',security.toolset_setting('pipeline','pdesc.countries'),'types',security.toolset_setting('pipeline','pdesc.provider_types'),'provider_keys',security.toolset_setting('pipeline','pdesc.provider_keys'),'ai_usd_max',security.pipeline_num_v1('pdesc.ai_usd_max',1),'pending_max',security.pipeline_num_v1('pdesc.pending_max',10),'reserved_usd',(select coalesce(sum(reserved_usd),0) from pipeline.provider_description_reads),'remaining_usd',greatest(0,security.pipeline_num_v1('pdesc.ai_usd_max',1)-(select coalesce(sum(cost_usd),0) from pipeline.ai_spend_ledger where lane='provider_description' and source<>'opening')-(select coalesce(sum(reserved_usd),0) from pipeline.provider_description_reads)),'actual_ai_calls',(select coalesce(sum(ai_calls),0) from pipeline.provider_description_reads),'recorded_billable_calls',(select coalesce(sum(calls),0) from pipeline.ai_spend_ledger where lane='provider_description' and source<>'opening'),'recorded_cost_usd',(select coalesce(sum(cost_usd),0) from pipeline.ai_spend_ledger where lane='provider_description' and source<>'opening'),'ai_call_counter_scope','reported model calls since provider-description-autonomy instrumentation; ledger calls are separate recorded billable calls','budget_period','lifetime pilot','required_approval','Individual human Layer 4 decision'));
 elsif p_action='preview' then
 v_args:=p_args||jsonb_build_object('mode',coalesce(nullif(p_args->>'mode',''),'stored'));
 -- Fill fields (Provider Catalogue and Provider Detail): the screen names what it wants to do; the governed selection gets the same description state it always had.
 if nullif(p_args->>'fill_mode','') is not null then
  if p_args->>'fill_mode' not in ('missing','upgrade_basic') then raise exception 'unsupported fill mode' using errcode='22023'; end if;
  v_args:=v_args||jsonb_build_object('description_state',case p_args->>'fill_mode' when 'upgrade_basic' then 'stale' else 'missing' end,'upgrade',p_args->>'fill_mode'='upgrade_basic');
 end if;
 v_res:=security.provider_description_selection_multi_v1(v_args);
 insert into pipeline.provider_description_cohorts(requested_by,selection,snapshot,expires_at)
 values(v_actor,v_args,v_res,now()+make_interval(mins=>security.pipeline_num_v1('pdesc.ui_preview_minutes',10)::int)) returning id into v_id;
 return v_res||jsonb_build_object('token',v_id,'preview_token',v_id,'expires_at',now()+make_interval(mins=>security.pipeline_num_v1('pdesc.ui_preview_minutes',10)::int));
 elsif p_action='prepare' then
 if v_rank<coalesce(v_job.control_rank,6) then raise exception 'your role cannot prepare this job' using errcode='42501'; end if;
 if length(v_reason)<security.pipeline_num_v1('pdesc.reason_min_chars',5) then raise exception 'audit reason is shorter than the governed minimum' using errcode='22023'; end if;
 select * into c from pipeline.provider_description_cohorts where id=nullif(p_args->>'preview_token','')::uuid and requested_by=v_actor for update;
 if c.id is null then raise exception 'unknown owned preview' using errcode='42501'; end if;
 if c.state in ('prepared','started') then return security.provider_description_run_result_v1(c.id); end if;
 if c.expires_at<now() then raise exception 'preview expired; preview again' using errcode='22023'; end if;
 v_fresh:=security.provider_description_selection_multi_v1(c.selection);
 for x in select * from jsonb_array_elements(c.snapshot->'providers') where (value->>'eligible')::boolean loop
  if not exists(select 1 from jsonb_array_elements(v_fresh->'providers') f where f->>'provider_id'=x->>'provider_id' and (f->>'eligible')::boolean and f->>'evidence_id' is not distinct from x->>'evidence_id' and f->>'source_hash' is not distinct from x->>'source_hash' and f->>'current_description' is not distinct from x->>'current_description' and f->>'last_read_id' is not distinct from x->>'last_read_id') then raise exception 'preview changed; preview again' using errcode='22023'; end if;
  v_n:=v_n+1;
  insert into pipeline.provider_description_cohort_members(cohort_id,provider_id,evidence_id,pick,snapshot) values(c.id,(x->>'provider_id')::uuid,(x->>'evidence_id')::uuid,v_n,x);
 end loop;
 if v_n=0 then raise exception 'no eligible provider with approved evidence in this preview' using errcode='22023'; end if;
 update pipeline.provider_description_cohorts set state='prepared',reason=v_reason,prepared_at=now() where id=c.id;
 insert into pipeline.admin_control_events(area,action,target,detail,actor) values('provider_descriptions','cohort_prepare',c.id::text,jsonb_build_object('selected',v_n,'reason',v_reason,'selection',c.selection),v_actor);
 return security.provider_description_run_result_v1(c.id);
 elsif p_action='run' then
 if v_rank<coalesce(v_job.control_rank,6) then raise exception 'your role cannot start this job' using errcode='42501'; end if;
 select * into c from pipeline.provider_description_cohorts where id=nullif(p_args->>'cohort_id','')::uuid and requested_by=v_actor for update;
 if c.id is null or c.state='preview' then raise exception 'unknown owned fixed cohort' using errcode='42501'; end if;
 if c.run_id is not null then return security.provider_description_run_result_v1(c.id)||jsonb_build_object('repeat',true); end if;
 if (select count(*) from pipeline.provider_description_cohort_members where cohort_id=c.id)>security.provider_description_cohort_cap_v1() then
   raise exception 'current_cap_changed: the fixed cohort exceeds the current governed cap; prepare a new cohort' using errcode='22023';
 end if;
 -- Same task kind, catalogue permission, pause/spend/review rules and provider-description job. Never a second scheduler.
 v_why:=case when not coalesce(security.toolset_setting('pipeline','run_now.jobs'),'[]'::jsonb)?'provider-description-read' then 'job_not_allowlisted'
 when v_job.jobname is null then 'job_not_catalogued'
 when not exists(select 1 from cron.job where jobname='provider-description-read' and active) then 'job_paused'
 when security.pipeline_num_v1('pdesc.enabled',0)<1 then 'reader_off'
 when not security.ai_use_allowed_v1('provider_description') then 'ai_refused'
 when (select coalesce(sum(cost_usd),0) from pipeline.ai_spend_ledger where lane='provider_description' and source<>'opening')>=security.pipeline_num_v1('pdesc.ai_usd_max',1) then 'ai_ceiling'
 when (select count(*) from pipeline.layer4_review_items where field_code='provider_description' and status='pending')>=security.pipeline_num_v1('pdesc.pending_max',10) then 'review_full' end;
 -- Policy/capacity holds are durable: the fixed cohort stays recoverable and the existing scheduled job resumes it.
 for x in select m.snapshot from pipeline.provider_description_cohort_members m where m.cohort_id=c.id order by m.pick loop
   v_fresh:=security.provider_description_selection_v1(c.selection||jsonb_build_object('provider_id',x->>'provider_id','size',1));
   if not exists(select 1 from jsonb_array_elements(v_fresh->'providers') f where (f->>'eligible')::boolean and f->>'evidence_id' is not distinct from x->>'evidence_id' and f->>'source_hash' is not distinct from x->>'source_hash' and f->>'current_description' is not distinct from x->>'current_description') then
     update pipeline.provider_description_cohort_members set snapshot=snapshot||jsonb_build_object('eligibility_reason','selection_changed_before_run','eligible',false) where cohort_id=c.id and provider_id=(x->>'provider_id')::uuid; continue;
   end if;
   insert into pipeline.provider_description_reads(provider_id) values((x->>'provider_id')::uuid) on conflict do nothing returning id into v_id;
   if v_id is null then select id into v_id from pipeline.provider_description_reads where provider_id=(x->>'provider_id')::uuid and state in ('queued','reading','proposed') order by created_at desc limit 1; end if;
   update pipeline.provider_description_cohort_members set read_id=v_id where cohort_id=c.id and provider_id=(x->>'provider_id')::uuid;
   v_n:=v_n+1; v_id:=null;
 end loop;
 update pipeline.provider_description_cohorts set state='started' where id=c.id;
 if v_why is null and v_n>0 then
   perform set_config('cf.pdesc_run_now',c.id::text,true);
   begin
     v_res:=security.provider_description_fire_v1();
   exception when others then
     -- OTHERS deliberately excludes query cancellation: the caller's statement/lock limits remain authoritative.
     get stacked diagnostics v_dispatch_error=message_text,v_dispatch_sqlstate=returned_sqlstate;
     v_res:=jsonb_build_object('sent',0,'parked',true,'reason','reader_dispatch_failed','error',v_dispatch_error,'sqlstate',v_dispatch_sqlstate,'retry_strategy','existing provider-description-read schedule resumes this saved queued cohort');
   end;
 else v_res:=jsonb_build_object('sent',0,'parked',true,'reason',coalesce(v_why,'selection_changed_before_run')); end if;
 insert into pipeline.admin_jobs(kind,lane,state,title,args,result,error,requested_by,reason,started_at,finished_at,scope,outcome)
 values('job_run_now','run_now',case when v_dispatch_error is not null then 'failed' when v_why is null then 'done' else 'cancelled' end,'Provider descriptions: bounded Run Now',jsonb_build_object('job','provider-description-read','cohort_id',c.id,'idempotency_key',c.request_key),v_res||jsonb_build_object('selected',v_n,'admitted',0,'publication_measured_separately',true),v_dispatch_error,v_actor,c.reason,now(),clock_timestamp(),'cohort:'||c.id,case when v_dispatch_error is not null then 'failed_retryable' when v_why is not null then 'blocked_policy' else 'succeeded_no_movement' end) returning id into v_run;
 update pipeline.provider_description_cohorts set run_id=v_run where id=c.id;
 insert into pipeline.admin_control_events(area,action,target,detail,actor) values('provider_descriptions','run_now','provider-description-read',jsonb_build_object('cohort_id',c.id,'run_id',v_run,'dispatch',v_res,'reason',c.reason),v_actor);
 return security.provider_description_run_result_v1(c.id)||jsonb_build_object('dispatch',v_res);
  elsif p_action='fill_caps' then
 -- Fill fields: what the panel needs to know before it asks anything. No provider list (capabilities carries every provider in scope; the panel does not need it).
 return jsonb_build_object('contract','provider-description-fill-v1','can_run',v_rank>=coalesce(v_job.control_rank,6),'control_rank',coalesce(v_job.control_rank,6),'reason_min_chars',security.pipeline_num_v1('pdesc.reason_min_chars',5)::int,
  'min_size',1,'max_size',security.provider_description_cohort_cap_v1(),
  'cap',jsonb_build_object('queue_per_run',security.pipeline_num_v1('pdesc.queue_per_run',10),'pending_max',security.pipeline_num_v1('pdesc.pending_max',10),'pilot_cap',security.pipeline_num_v1('run_now.pilot_cap',20),'queue_cap',security.pipeline_num_v1('pdesc.queue_cap',60),'effective',security.provider_description_cohort_cap_v1()),
  'enabled',security.pipeline_num_v1('pdesc.enabled',0)>=1,'job_active',coalesce((select active from cron.job where jobname='provider-description-read'),false),
  'run_now_allowed',coalesce(security.toolset_setting('pipeline','run_now.jobs'),'[]'::jsonb)?'provider-description-read',
  'poll_seconds',greatest(30,security.pipeline_num_v1('pdesc.every_minutes',60)::int*15) /* fixed: a quarter of the reader's own window (minutes x 60 / 4), never faster than twice a minute */,'status_max',security.provider_description_cohort_cap_v1(),
  'modes',jsonb_build_array(jsonb_build_object('id','stored','label','Stored official evidence + approved AI','allowed',true),jsonb_build_object('id','approved','label','Existing authorised acquisition + approved AI','allowed',security.pipeline_num_v1('pdesc.acquire_direct',0)>=1)),
  'fill_modes',jsonb_build_array('missing','upgrade_basic','preview_only','verify_publication'),
  'upgrade_basic_on',security.pipeline_num_v1('pdesc.registry_upgrade_on',0)>=1 and security.pipeline_num_v1('pdesc.machine_admit_on',0)>=1,
  'quality_classes',to_jsonb(security.provider_description_quality_classes_v1()));
 elsif p_action in ('provider_status','provider_publication') then
 -- Fill fields, read only: the state of up to the governed number of providers, and the task that last included each. Needs no saved cohort, so it works after the browser was closed.
 select coalesce(array_agg(distinct (e)::uuid),array[]::uuid[]) into v_ids from jsonb_array_elements_text(case when jsonb_typeof(p_args->'provider_ids')='array' then p_args->'provider_ids' else '[]'::jsonb end) e;
 if cardinality(v_ids)=0 or cardinality(v_ids)>security.provider_description_cohort_cap_v1() then raise exception 'name between 1 and % providers',security.provider_description_cohort_cap_v1() using errcode='22023'; end if;
 if p_action='provider_publication' then
  if v_rank<coalesce(v_job.control_rank,6) then raise exception 'your role cannot verify this job publication' using errcode='42501'; end if;
  v_res:=security.provider_description_publication_read_v1(v_ids);
  insert into pipeline.admin_control_events(area,action,target,detail,actor) values('provider_descriptions','verify_provider_publication',array_to_string(v_ids,','),jsonb_build_object('providers',cardinality(v_ids),'as_at',now(),'reason','Operator requested actual catalogue and consumer read-back from Fill fields'),v_actor);
  return v_res;
 end if;
 return security.provider_description_fill_status_v1(v_ids,coalesce((p_args->>'feeds')::boolean,false),v_actor);
 elsif p_action='quality_counts' then
 return security.provider_description_quality_counts_v1();
 elsif p_action='quality_refresh' then
 if v_rank<coalesce(v_job.control_rank,6) then raise exception 'your role cannot refresh the quality snapshot' using errcode='42501'; end if;
 select array_agg(distinct (e)::uuid) into v_ids from jsonb_array_elements_text(case when jsonb_typeof(p_args->'provider_ids')='array' then p_args->'provider_ids' else '[]'::jsonb end) e;
 return security.provider_description_quality_refresh_v1(v_ids);
 elsif p_action in ('saved','verify','diagnose') then
 if p_action='diagnose' and nullif(p_args->>'preview_token','') is not null then select * into c from pipeline.provider_description_cohorts where id=(p_args->>'preview_token')::uuid and requested_by=v_actor;
 elsif nullif(p_args->>'cohort_id','') is not null then select * into c from pipeline.provider_description_cohorts where id=(p_args->>'cohort_id')::uuid and requested_by=v_actor;
 else select * into c from pipeline.provider_description_cohorts where requested_by=v_actor order by created_at desc,id desc limit 1; end if;
 if p_action='diagnose' then
   if v_rank<coalesce(v_job.control_rank,6) then raise exception 'your role cannot diagnose this job' using errcode='42501'; end if;
   if length(v_reason)<security.pipeline_num_v1('pdesc.reason_min_chars',5) then raise exception 'audit reason required'; end if;
   if c.id is null and nullif(p_args->>'preview_token','') is not null then select * into c from pipeline.provider_description_cohorts where id=(p_args->>'preview_token')::uuid and requested_by=v_actor; end if;
   if c.id is null then raise exception 'owned saved evidence required' using errcode='42501'; end if;
   select coalesce(r.rule,m.snapshot->>'eligibility_reason'),coalesce(r.reason,m.snapshot->>'reason') into v_rule,v_why from pipeline.provider_description_cohort_members m left join pipeline.provider_description_reads r on r.id=m.read_id where m.cohort_id=c.id and m.provider_id=(p_args->>'provider_id')::uuid;
   if v_rule is null then select x->>'eligibility_reason',x->>'reason' into v_rule,v_why from jsonb_array_elements(c.snapshot->'providers') x where x->>'provider_id'=p_args->>'provider_id'; end if;
   if v_rule is null then raise exception 'provider is not in owned saved evidence' using errcode='42501'; end if;
   v_diagnosis:=jsonb_build_object('method','stored_checks','rule',v_rule,'explanation',coalesce(v_why,case v_rule when 'no_verified_stored_source' then 'A current official About/Overview page stored against this exact provider is needed.' when 'unchanged_unsuitable_evidence' then 'The same evidence previously failed or was rejected. A changed approved source is needed before another AI read.' when 'review_full' then 'The validated proposal is parked until Layer 4 capacity becomes available; no further AI read is needed.' else 'Inspect the official source, identity references and validation checks. Only the existing human Layer 4 decision can authorise admission.' end),'ai_used',false,'cost_usd',0,'ai_reason','Provider-description AI diagnostics have no approved existing route.','at',now());
   -- AI is advice through the existing Operations lane only, bound to an already recorded issue and the exact stored source.
   select coalesce((select m.snapshot||jsonb_build_object('evidence_id',coalesce(r.evidence_id,m.evidence_id),'source_hash',coalesce(r.content_hash,m.snapshot->>'source_hash'),'checks',r.checks,'sentences',r.proposal->'sentences') from pipeline.provider_description_cohort_members m left join pipeline.provider_description_reads r on r.id=m.read_id where m.cohort_id=c.id and m.provider_id=(p_args->>'provider_id')::uuid),
     (select z from jsonb_array_elements(c.snapshot->'providers') z where z->>'provider_id'=p_args->>'provider_id')) into v_context;
   v_ai_model:=nullif(security.ai_route_v1('ops_diagnosis')->>'model','');
   v_ai_why:=case when security.pipeline_num_v1('ops.ai_diagnosis_on',0)<1 then 'ops.ai_diagnosis_on is 0'
      when v_ai_model is null then 'no approved Operations diagnosis model'
      when not security.ai_use_allowed_v1('ops_diagnose') then 'existing Operations AI spending guard refuses assistance'
      when nullif(v_context->>'evidence_id','') is null then 'no exact stored evidence reference for an existing issue' end;
   if v_ai_why is null then
    select i.id into v_issue from pipeline.integration_issues i where i.status not in ('closed','superseded') and (p_args->>'provider_id')::uuid=any(i.provider_ids)
      and jsonb_path_exists(i.evidence,'$.**.evidence_id ? (@ == $id)',jsonb_build_object('id',v_context->>'evidence_id')) order by i.id desc limit 1;
    if v_issue is null then v_ai_why:='no existing open integration issue links this exact provider and stored evidence'; end if;
   end if;
   if v_ai_why is null then
    perform pg_advisory_xact_lock(hashtext('cf247 pdesc diagnosis '||v_issue::text)); -- fixed: duplicate request suppression for the existing issue/evidence.
    select q.id into v_ai_request from pipeline.ops_ai_diagnosis_requests q where q.issue_id=v_issue and q.context->>'provider_description_evidence_id'=v_context->>'evidence_id' and q.state in ('queued','leased','answered','refused') order by q.id desc limit 1;
    if v_ai_request is null then
     insert into pipeline.ops_ai_diagnosis_requests(issue_id,context,model,note)
     values(v_issue,jsonb_build_object('issue',v_issue,'provider_id',p_args->>'provider_id','provider_description_evidence_id',v_context->>'evidence_id','evidence',v_context,'question','Explain why this official source or claim is unsuitable and which evidence is missing. Advice only; do not authorise a description or change any setting.',
       'deterministic',v_diagnosis,'root_causes',(select jsonb_agg(jsonb_build_object('code',rc.code,'class',rc.class,'title',rc.title,'description',rc.description)) from pipeline.ops_root_causes rc)),v_ai_model,'Provider description evidence explanation; advice through existing Operations diagnosis') returning id into v_ai_request;
    end if;
    v_diagnosis:=v_diagnosis||jsonb_build_object('request_id',v_ai_request,'request_status','queued','integration_issue_id',v_issue,'model',v_ai_model,'ai_reason','Queued through the existing Operations diagnosis worker; no approval or settings authority.');
   else v_diagnosis:=v_diagnosis||jsonb_build_object('ai_reason',v_ai_why); end if;
   update pipeline.provider_description_cohort_members set snapshot=snapshot||jsonb_build_object('diagnosis',v_diagnosis) where cohort_id=c.id and provider_id=(p_args->>'provider_id')::uuid;
   update pipeline.provider_description_cohorts set snapshot=jsonb_set(snapshot,'{providers}',(select jsonb_agg(case when z->>'provider_id'=p_args->>'provider_id' then z||jsonb_build_object('diagnosis',v_diagnosis) else z end) from jsonb_array_elements(snapshot->'providers') z)) where id=c.id;
   insert into pipeline.admin_control_events(area,action,target,detail,actor) values('provider_descriptions','explain_evidence',c.id::text,jsonb_build_object('provider_id',p_args->>'provider_id','reason',v_reason,'diagnosis',v_diagnosis),v_actor);
   return v_diagnosis;
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('cohort_id',h.id,'state',h.state,'created_at',h.created_at,'reason',h.reason,'run_id',h.run_id) order by h.created_at desc),'[]') into v_history from (select * from pipeline.provider_description_cohorts where requested_by=v_actor order by created_at desc limit security.pipeline_num_v1('pdesc.queue_per_run',10)::int) h;
 if c.state='preview' then
   v_preview:=jsonb_set(c.snapshot,'{providers}',coalesce((select jsonb_agg(z||case when z->'diagnosis'->>'request_id' is not null then jsonb_build_object('diagnosis',(z->'diagnosis')||coalesce((select jsonb_build_object('request_status',q.state,'ai_used',q.state='answered','explanation',coalesce(q.answer->>'reasoning',z->'diagnosis'->>'explanation'),'answer',q.answer,'model',q.model,'cost_usd',q.cost_usd,'answered_at',q.answered_at) from pipeline.ops_ai_diagnosis_requests q where q.id=(z->'diagnosis'->>'request_id')::bigint),'{}'::jsonb)) else '{}'::jsonb end) from jsonb_array_elements(c.snapshot->'providers') z),'[]'::jsonb));
   return jsonb_build_object('preview',v_preview||jsonb_build_object('token',c.id,'expires_at',c.expires_at),'scope',c.selection,'history',v_history);
 end if;
 if c.id is null then return jsonb_build_object('history',v_history,'providers','[]'::jsonb,'runs','[]'::jsonb); end if;
 v_res:=security.provider_description_run_result_v1(c.id);
 if p_action='verify' then
   update pipeline.provider_description_cohorts set verified_at=now(),verification=v_res-'last_verification' where id=c.id;
   insert into pipeline.admin_control_events(area,action,target,detail,actor) values('provider_descriptions','verify',c.id::text,jsonb_build_object('totals',v_res->'totals','as_at',now(),'reason','Operator requested actual catalogue and consumer read-back'),v_actor);
 end if;
 return v_res||jsonb_build_object('history',v_history);
 end if;
 raise exception 'unknown provider-description action %',p_action using errcode='22023';
end $_$;


ALTER FUNCTION "public"."admin_provider_description_run_v1"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_provider_description_run_v1"("p_action" "text", "p_args" "jsonb") IS 'Provider Description autonomy 4 Nov 2026: authorised bounded scope preview, actor-bound saved immutable cohort, idempotent governed Run Now through existing provider-description-read, persisted results and actual Website read-back; existing Layer 4 is the only admission decision. Explain evidence preserves original checks without AI spend.';



CREATE OR REPLACE FUNCTION "public"."admin_provider_descriptions"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_ids uuid[]; v_n int; v_reason text := btrim(coalesce(p_args->>'reason', ''));
        v_cc text := upper(nullif(btrim(coalesce(p_args->>'country', '')), ''));
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'curator role required' using errcode = '42501'; end if;
  if p_action = 'metrics' then
    return (with el as (
              select p.id, coalesce(p.display_name, p.canonical_name) name, k.iso_alpha2 cc, nullif(btrim(p.description), '') is not null present,
                     (select r.state from pipeline.provider_description_reads r where r.provider_id = p.id order by r.created_at desc limit 1) state,
                     (select r.rule from pipeline.provider_description_reads r where r.provider_id = p.id order by r.created_at desc limit 1) rule,
                     security.provider_description_stored_v1(p.id) is not null stored
                from catalogue.providers p join ref.countries k on k.id = p.country_id
               where security.provider_description_scope_v1(p.id) and (v_cc is null or k.iso_alpha2 = v_cc)
                 and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id)),
            rd as (select r.* from pipeline.provider_description_reads r join el on el.id = r.provider_id)
      select jsonb_build_object(
        'enabled', security.pipeline_num_v1('pdesc.enabled', 0) >= 1,
        'job_active', coalesce((select j.active from cron.job j where j.jobname = 'provider-description-read'), false),
        'by_country', coalesce((select jsonb_agg(jsonb_build_object('country', cc, 'eligible', n, 'present', pr, 'missing', n - pr, 'stored_pages', st) order by cc)
                                  from (select cc, count(*) n, count(*) filter (where present) pr, count(*) filter (where stored) st from el group by cc) c), '[]'::jsonb),
        'eligible', (select count(*) from el), 'present', (select count(*) from el where present), 'missing', (select count(*) from el where not present),
        'stored_pages_available', (select count(*) from el where stored),
        'queued', (select count(*) from el where state = 'queued'), 'reading', (select count(*) from el where state = 'reading'),
        'proposed', (select count(*) from el where state = 'proposed'), 'held', (select count(*) from el where state = 'held'),
        'dead_letter', (select count(*) from el where state = 'dead_letter'), 'admitted', (select count(*) from el where state = 'admitted'),
        'verified', (select count(*) from el where state = 'verified'), 'rejected', (select count(*) from el where state = 'rejected'),
        'published', (select count(*) from rd where rd.state = 'admitted' and rd.published_at is not null),
        'pages_acquired', (select count(*) from rd where rd.read_via in ('direct', 'firecrawl')),
        'pages_reused', (select count(*) from rd where rd.read_via = 'stored'),
        'ai_reads', (select count(*) from rd where rd.model is not null),
        'retried', (select count(*) from rd where rd.tries > 1),
        'cost_usd', (select round(coalesce(sum(rd.cost_usd), 0), 4) from rd),
        'firecrawl_reads', (select coalesce(sum(rd.firecrawl_reads), 0) from rd),
        'ai_usd_max', security.pipeline_num_v1('pdesc.ai_usd_max', 1), 'firecrawl_reads_max', security.pipeline_num_v1('pdesc.firecrawl_reads_max', 0),
        'cost_per_admitted_usd', (select case when count(*) filter (where rd.state = 'admitted') = 0 then null
                                              else round(sum(rd.cost_usd) / count(*) filter (where rd.state = 'admitted'), 4) end from rd),
        'reads_last_7_days', (select count(*) from rd where rd.updated_at > now() - make_interval(days => 7) and rd.model is not null),
        'last_run', (select max(l.created_at) from pipeline.edge_request_log l where l.function_name = 'coverage-sweep' and l.mode = 'provider_description'),
        'layer4_pending', (select count(*) from pipeline.layer4_review_items i where i.field_code = 'provider_description' and i.status = 'pending'),
        'layer4_decided', (select count(*) from pipeline.layer4_review_items i where i.field_code = 'provider_description' and i.status <> 'pending'),
        'rejections', coalesce((select jsonb_agg(jsonb_build_object('rule', rule, 'n', n) order by n desc)
                                  from (select rd.rule, count(*) n from rd where rd.state in ('held', 'rejected', 'dead_letter') group by rd.rule) z), '[]'::jsonb),
        'backlog', (select count(*) from el where not present and coalesce(state, 'none') not in ('proposed', 'held', 'dead_letter', 'rejected')),
        'providers', coalesce((select jsonb_agg(jsonb_build_object('provider_id', el.id, 'provider', el.name, 'country', el.cc, 'present', el.present, 'state', el.state,
                                                                  'rule', el.rule, 'stored_page', el.stored) order by el.cc, el.name) from el), '[]'::jsonb)));
  elsif p_action = 'retry' then
    -- dead letters and held reads go back to the queue (PIM Admin and above, with a reason)
    if v_rank < 5 then raise exception 'PIM Admin role required' using errcode = '42501'; end if;
    if length(v_reason) < 5 then raise exception 'reason required'; end if;
    v_ids := array(select jsonb_array_elements_text(coalesce(p_args->'provider_ids', '[]'::jsonb))::uuid);
    update pipeline.provider_description_reads r set state = 'queued', tries = 0, next_try_at = now(), leased_until = null, rule = 'retried', reason = v_reason, updated_at = now()
     where r.state in ('dead_letter', 'held') and r.provider_id = any (v_ids)
       and not exists (select 1 from pipeline.provider_description_reads o where o.provider_id = r.provider_id and o.state in ('queued', 'reading', 'proposed'))
       and r.id = (select r2.id from pipeline.provider_description_reads r2 where r2.provider_id = r.provider_id order by r2.created_at desc limit 1);
    get diagnostics v_n = row_count;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('provider_descriptions', 'retry', 'pipeline.provider_description_reads', jsonb_build_object('providers', to_jsonb(v_ids), 'requeued', v_n, 'reason', v_reason), auth.uid());
    return jsonb_build_object('ok', true, 'requeued', v_n);
  end if;
  raise exception 'unknown action %', p_action using errcode = '22023';
end $$;


ALTER FUNCTION "public"."admin_provider_descriptions"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_provider_descriptions"("p_action" "text", "p_args" "jsonb") IS 'CF-247 P1 provider descriptions (mandate §8): metrics for Coverage › Every field (eligible, present, missing, proposed, held, admitted, dead letter, stored pages, pages acquired and reused, AI reads, cost and cost per admitted description, rejections by rule, Layer 4 queue, last run, backlog, by country and provider) and retry of dead letters (PIM Admin, with a reason).';



CREATE OR REPLACE FUNCTION "public"."admin_provider_domain_moved"("p_provider_id" "uuid", "p_new_host" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_old text; v_new text := lower(btrim(coalesce(p_new_host, ''))); v_pages int := 0; v_lists int := 0; v_reason text := btrim(coalesce(p_reason, '')); v_rx text;
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if v_new !~ '^[a-z0-9.-]+\.[a-z]{2,}$' then raise exception 'give the new host only, for example www.example.ac.nz'; end if;
  select lower(regexp_replace(website, '^https?://([^/]+).*$', '\1')) into v_old from catalogue.providers where id = p_provider_id and website ~* '^https?://';
  if v_old is null then raise exception 'the provider has no website to move from'; end if;
  if v_old = v_new then raise exception 'the website already is %: nothing to move', v_old; end if;  -- N5: no-op refused, nothing logged
  v_rx := '^(https?://)' || regexp_replace(v_old, '\.', '\\.', 'g') || '(?=/|$)';
  update pipeline.coverage_course_pages g
     set url = regexp_replace(g.url, v_rx, '\1' || v_new, 'i'), next_read_at = now(), read_attempts = 0, leased_until = null
   where g.course_id in (select id from catalogue.courses where provider_id = p_provider_id)
     and g.status in ('bound', 'ambiguous') and g.url ~* v_rx;
  get diagnostics v_pages = row_count;
  update pipeline.provider_course_lists l
     set url = regexp_replace(l.url, v_rx, '\1' || v_new, 'i'), updated_at = now()
   where l.provider_id = p_provider_id and l.url ~* v_rx;
  get diagnostics v_lists = row_count;
  perform set_config('cf.manual_edit', 'on', true);
  update catalogue.providers set website = 'https://' || v_new, updated_at = now() where id = p_provider_id;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('layer1', 'provider_domain_moved', p_provider_id::text, jsonb_build_object('from', v_old, 'to', v_new, 'pages', v_pages, 'lists', v_lists, 'reason', v_reason), auth.uid());
  return jsonb_build_object('from', v_old, 'to', v_new, 'pages_moved', v_pages, 'lists_moved', v_lists);
end $_$;


ALTER FUNCTION "public"."admin_provider_domain_moved"("p_provider_id" "uuid", "p_new_host" "text", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_provider_domain_moved"("p_provider_id" "uuid", "p_new_host" "text", "p_reason" "text") IS 'CF-247 NZ brief item 2: moves a provider''s bound course pages and list sources to a new host (identity proof and evidence kept, pages read again first in line). Platform Admin, logged; the same host is refused.';



CREATE OR REPLACE FUNCTION "public"."admin_provider_edit"("p_provider_id" "uuid", "p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_p catalogue.providers%rowtype; v_field text; v_before jsonb; v_after jsonb; v_val jsonb; v_url text;
        v_reason text := nullif(btrim(coalesce(p_args->>'reason', '')), '');
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  select * into v_p from catalogue.providers where id = p_provider_id;
  if v_p.id is null then raise exception 'provider not found'; end if;
  if p_action in ('archive','restore') and v_rank < 5 then raise exception 'PIM Operator role or above required' using errcode = '42501'; end if;
  perform set_config('cf.manual_edit', 'on', true);

  if p_action = 'set_core' then
    v_field := p_args->>'field';
    if v_field is null or v_field not in ('display_name','short_name','website','phone','email','description','primary_city','address_line1','postcode') then raise exception 'this field cannot be edited here'; end if;
    v_val := p_args->'value';
    if jsonb_typeof(v_val) = 'string' then v_val := to_jsonb(nullif(btrim(v_val #>> '{}'), '')); end if;
    if v_field = 'website' and v_val is not null and v_val <> 'null'::jsonb and (v_val #>> '{}') !~* '^https?://[^\s/]+\.[^\s]+$' then raise exception 'enter a full web address starting with https://'; end if;
    if v_field = 'website' and v_val is not null and v_val <> 'null'::jsonb and security.third_party_host_v1(v_val #>> '{}') then raise exception 'that is a third-party site (a course directory or similar), not the provider''s own website'; end if;
    if v_field = 'email' and v_val is not null and v_val <> 'null'::jsonb and (v_val #>> '{}') !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'enter a valid email address'; end if;
    v_before := to_jsonb(v_p)->v_field;
    update catalogue.providers p set display_name = r.display_name, short_name = r.short_name, website = r.website, phone = r.phone, email = r.email,
           description = r.description, primary_city = r.primary_city, address_line1 = r.address_line1, postcode = r.postcode, updated_at = now()
      from (select (jsonb_populate_record(x0, jsonb_build_object(v_field, v_val))).* from catalogue.providers x0 where x0.id = p_provider_id) r
     where p.id = p_provider_id;
    perform security.manual_lock_set('provider', p_provider_id, v_field, 'value');
    v_after := v_val;

  elsif p_action = 'set_course_finder' then
    v_field := 'course_finder'; v_url := btrim(coalesce(p_args->>'url', ''));
    if v_url !~* '^https?://[^\s/]+\.[^\s]+$' then raise exception 'enter a full web address starting with https://'; end if;
    if security.third_party_host_v1(v_url) then raise exception 'that is a third-party course directory: use the provider''s own website or the regulator''s page'; end if;
    select to_jsonb(d.website) into v_before from pipeline.coverage_provider_discovery d where d.provider_id = p_provider_id;
    insert into pipeline.coverage_provider_discovery(provider_id, website, status, attempts, next_due_at, updated_at)
    values (p_provider_id, v_url, 'pending', 0, now(), now())
    on conflict (provider_id) do update set website = excluded.website, status = 'pending', attempts = 0, next_due_at = now(), leased_until = null,
           last_error = null, updated_at = now();
    -- v2.15.232 (Fix 3): an address entered by hand is marked manual and locked, so automation never replaces it
    update pipeline.coverage_provider_discovery set site_source = 'manual', site_searched_at = now() where provider_id = p_provider_id;
    perform security.manual_lock_set('provider', p_provider_id, 'course_finder', 'value');
    v_after := to_jsonb(v_url);

  elsif p_action = 'release' then
    v_field := p_args->>'field';
    select to_jsonb(l) into v_before from pipeline.manual_locks l where entity = 'provider' and entity_id = p_provider_id and field = v_field;
    if v_before is null then raise exception 'nothing to release'; end if;
    delete from pipeline.manual_locks where entity = 'provider' and entity_id = p_provider_id and field = v_field;
    -- v2.15.232: handing the course finder address back to automation lets the site search replace it again
    if v_field = 'course_finder' then update pipeline.coverage_provider_discovery set site_source = null where provider_id = p_provider_id and site_source = 'manual'; end if;

  elsif p_action in ('archive','restore') then
    -- v2.15.238 (R5): archive and restore go through the clean-up workflow (status 'archived'; adapter, link search and waiting reviews
    -- switched off, and back on at restore). The workflow logs the change itself.
    if p_action = 'archive' then perform security.provider_archive_apply_v1(p_provider_id, 'manual', coalesce(v_reason, 'Archived by hand'), auth.uid(), true);
    else perform security.provider_restore_v1(p_provider_id, coalesce(v_reason, 'Restored by hand'), auth.uid(), true); end if;
    return public.admin_provider_edit_read(p_provider_id);

  else
    raise exception 'unknown action %', p_action;
  end if;

  insert into pipeline.manual_edit_log(entity, entity_id, field, action, before, after, reason, actor)
  values ('provider', p_provider_id, v_field, p_action, v_before, v_after, v_reason, auth.uid());
  return public.admin_provider_edit_read(p_provider_id);
end $_$;


ALTER FUNCTION "public"."admin_provider_edit"("p_provider_id" "uuid", "p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_edit_read"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'assigned StudySearch role required' using errcode = '42501'; end if;
  if not exists (select 1 from catalogue.providers where id = p_provider_id) then raise exception 'provider not found'; end if;
  return (select jsonb_build_object(
    'provider', jsonb_build_object('id', p.id, 'canonical_name', p.canonical_name, 'display_name', p.display_name, 'short_name', p.short_name,
               'website', p.website, 'phone', p.phone, 'email', p.email, 'description', p.description, 'primary_city', p.primary_city,
               'address_line1', p.address_line1, 'postcode', p.postcode, 'lifecycle_status', p.lifecycle_status, 'country', k.name, 'state', s.name,
               'manual_provider', p.stable_key like 'manual:%', 'website_verdict', security.provider_site_verdict_v1(p.id, p.website),
               'active_courses', (select count(*) from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active')),
    'course_finder', (select jsonb_build_object('address', d.website, 'status', d.status, 'pages_found', d.kept_count, 'mapped_at', d.mapped_at,
                               'verdict', security.provider_site_verdict_v1(p.id, d.website), 'source', d.site_source)
                        from pipeline.coverage_provider_discovery d where d.provider_id = p.id),
    'link_recipe', (select jsonb_build_object('search_domain', r.search_domain, 'patterns', r.patterns, 'active', r.active)
                      from pipeline.course_link_recipes r where r.provider_id = p.id),
    -- v2.15.234 (Fix 2): where the public phone and email came from, and (PIM Operator and above) the regulator's contact, internal only
    'public_contact', (select jsonb_build_object('phone', cp.phone, 'email', cp.email, 'url', cp.source_url, 'at', cp.observed_at)
                         from pipeline.provider_contact_points cp where cp.provider_id = p.id and cp.kind = 'public_general' and cp.is_current),
    'regulatory_contact', case when v_rank >= 5 then (select jsonb_build_object('name', cp.name, 'title', cp.title, 'phone', cp.phone, 'email', cp.email, 'url', cp.source_url, 'at', cp.observed_at)
                         from pipeline.provider_contact_points cp where cp.provider_id = p.id and cp.kind = 'regulatory_peo' and cp.is_current) end,
    'regulatory_check', case when v_rank >= 5 then (select jsonb_build_object('outcome', k.outcome, 'at', k.checked_at) from pipeline.provider_contact_checks k where k.provider_id = p.id and k.kind = 'regulatory_peo') end,
    'locks', (select coalesce(jsonb_object_agg(l.field, jsonb_build_object('mode', l.mode, 'at', l.set_at)), '{}'::jsonb)
               from pipeline.manual_locks l where l.entity = 'provider' and l.entity_id = p.id),
    'history', (select coalesce(jsonb_agg(jsonb_build_object('at', h.at, 'field', h.field, 'action', h.action, 'before', h.before, 'after', h.after,
               'reason', h.reason, 'by', u.email) order by h.at desc), '[]'::jsonb)
               from (select * from pipeline.manual_edit_log where entity = 'provider' and entity_id = p.id order by at desc limit 20) h left join auth.users u on u.id = h.actor),
    -- v2.15.238 (R5): why and when the provider was archived
    'archive', (select jsonb_build_object('source', a.source, 'reason', a.reason, 'at', a.archived_at) from pipeline.provider_archives a where a.provider_id = p.id and a.restored_at is null),
    'can_edit', v_rank >= 3, 'can_manage', v_rank >= 5)
   from catalogue.providers p left join ref.countries k on k.id = p.country_id left join ref.subdivisions s on s.id = p.subdivision_id where p.id = p_provider_id);
end $$;


ALTER FUNCTION "public"."admin_provider_edit_read"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_english_groups_set_v1"("p_proposal_id" "uuid", "p_bindings" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare x pipeline.provider_policy_proposals%rowtype; b jsonb; g jsonb; v_out jsonb := '[]'::jsonb; v_fields text[]; v_paths text[]; v_code text; v_path text;
        v_reason text := btrim(coalesce(p_reason, '')); v_regex text; v_withdrawn int := 0; v_ids uuid[]; v_plan jsonb; v_day text := to_char(now() at time zone 'Australia/Melbourne', 'FMDD Mon YYYY');
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  select * into x from pipeline.provider_policy_proposals where id = p_proposal_id for update;
  if x.id is null or x.kind <> 'english_policy' then raise exception 'not an English policy proposal'; end if;
  if x.status not in ('proposed', 'approved') then raise exception 'a % policy cannot be bound', x.status; end if;
  if jsonb_typeof(x.proposal->'groups') is distinct from 'array' or jsonb_array_length(x.proposal->'groups') = 0 then raise exception 'this policy has no course groups'; end if;
  if jsonb_typeof(p_bindings) is distinct from 'array' then raise exception 'bindings must be a list'; end if;
  for b in select e from jsonb_array_elements(p_bindings) e loop
    g := null;
    select gg into g from jsonb_array_elements(x.proposal->'groups') gg where gg->>'group_name' = b->>'group_name' and coalesce(gg->>'level', '') = coalesce(b->>'level', '') limit 1;
    if g is null then raise exception 'course group "%" (level %) is not in this policy', b->>'group_name', coalesce(b->>'level', 'any'); end if;
    v_fields := array(select distinct btrim(f) from jsonb_array_elements_text(case when jsonb_typeof(b->'fields') = 'array' then b->'fields' else '[]'::jsonb end) f where btrim(f) <> '');
    v_paths := '{}';
    foreach v_code in array v_fields loop
      v_path := null;
      select path into v_path from ref.fields_of_study where code = v_code and status = 'active';
      if v_path is null then raise exception 'field of education "%" is not an active field', v_code; end if;
      v_paths := v_paths || v_path;
    end loop;
    v_regex := nullif(btrim(coalesce(b->>'title_regex', '')), '');
    if v_regex is not null then
      if length(v_regex) > 200 then raise exception 'the title pattern is too long'; end if;  -- fixed: a bound on a person's pattern, not an operational value
      begin perform '' ~* v_regex; exception when others then raise exception 'the title pattern is not a valid pattern'; end;
    end if;
    if cardinality(v_fields) = 0 and v_regex is null then raise exception 'course group "%" needs at least one field of education or a title pattern', b->>'group_name'; end if;
    v_out := v_out || jsonb_build_object('group_name', g->>'group_name', 'level', g->'level', 'fields', to_jsonb(v_fields), 'field_paths', to_jsonb(v_paths), 'title_regex', v_regex,
                                         'note', left(coalesce(b->>'note', ''), 300), 'bound_by', auth.uid(), 'bound_at', now());
  end loop;
  update pipeline.provider_policy_proposals set proposal = jsonb_set(proposal, '{group_bindings}', v_out, true), updated_at = now() where id = x.id;
  -- rows an earlier binding wrote for a course the bindings no longer reach are withdrawn (kept, not deleted)
  with w as (
    update catalogue.course_english_requirements e set status = 'withdrawn', last_verified_at = now(),
           notes = coalesce(e.notes, '') || format(' Withdrawn %s: the course group binding of this policy changed and no longer reaches this course.', v_day)
     where e.status = 'active' and e.source_requirement_key like 'policy:' || x.id || ':%' and e.notes like 'English requirement for the course group%'
       and e.course_id not in (select pl.course_id from security.provider_english_plan_v1(x.id) pl where pl.plan = 'group')
    returning e.course_id)
  select coalesce(array_agg(course_id), '{}'), count(*) into v_ids, v_withdrawn from w;
  if v_withdrawn > 0 then perform search.refresh_course_enrichment_scoped_v1(v_ids, true); end if;
  v_plan := security.provider_policy_refresh_one_v1(x.id);
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('policies', 'english_groups_bound', 'english_policy: ' || x.url,
          jsonb_build_object('decision', 'Platform Admin 6 Nov 2026 §3 D2', 'proposal_id', x.id, 'provider_id', x.provider_id, 'bindings', v_out, 'reason', v_reason, 'withdrawn_rows', v_withdrawn), auth.uid());
  return jsonb_build_object('bound', jsonb_array_length(v_out), 'withdrawn_rows', v_withdrawn, 'plan', v_plan);
end $$;


ALTER FUNCTION "public"."admin_provider_english_groups_set_v1"("p_proposal_id" "uuid", "p_bindings" "jsonb", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_provider_english_groups_set_v1"("p_proposal_id" "uuid", "p_bindings" "jsonb", "p_reason" "text") IS 'CF-247 English requirements (6 Nov 2026 D2): a Platform Admin binds the course groups of an English policy (faculty or course-group table) to courses by ASCED field of education and/or a title pattern, with a reason. Only a bound group reaches a course, and only once the policy is approved. Logged in admin_control_events.';



CREATE OR REPLACE FUNCTION "public"."admin_provider_english_propose"("p_provider_id" "uuid", "p_rule" "jsonb", "p_url" "text", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_id uuid; v_src uuid; v_ev uuid; v_defaults jsonb := '{}'::jsonb; v_ex jsonb := '[]'::jsonb; v_prop jsonb; k text; r jsonb; v_note text := btrim(coalesce(p_note, ''));
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if not exists (select 1 from catalogue.providers where id = p_provider_id) then raise exception 'provider not found'; end if;
  if coalesce(btrim(p_url), '') !~* '^https?://' then raise exception 'the central English page address is required'; end if;
  if length(v_note) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  -- one requirement: IELTS overall from 4 to 9 in halves, optional lowest band
  for k in select x from unnest(array['undergraduate', 'postgraduate']) x loop
    r := p_rule->k;
    continue when r is null;
    if (r->>'overall') !~ '^[4-9](\.[05])?$' or coalesce(r->>'min_band', '5') !~ '^[3-9](\.[05])?$' then raise exception 'the % rule needs an IELTS overall (and lowest band) from 4 to 9 in halves', k; end if;
    v_defaults := v_defaults || jsonb_build_object(k, jsonb_build_array(jsonb_build_object('test_code', 'IELTS', 'overall_score', (r->>'overall')::numeric,
                    'component_scores', case when r ? 'min_band' then jsonb_build_object('listening', (r->>'min_band')::numeric, 'reading', (r->>'min_band')::numeric, 'writing', (r->>'min_band')::numeric, 'speaking', (r->>'min_band')::numeric) else '{}'::jsonb end,
                    'quote', left(coalesce(r->>'quote', ''), 400))));
  end loop;
  for r in select e from jsonb_array_elements(coalesce(p_rule->'named', '[]'::jsonb)) e loop
    if length(btrim(coalesce(r->>'name', ''))) < 4 or (r->>'overall') !~ '^[4-9](\.[05])?$' or coalesce(r->>'min_band', '5') !~ '^[3-9](\.[05])?$' then raise exception 'each named course needs a name and an IELTS overall (and lowest band) from 4 to 9 in halves'; end if;
    v_ex := v_ex || jsonb_build_array(jsonb_build_object('name', btrim(r->>'name'), 'level', null, 'reqs', jsonb_build_array(jsonb_build_object('test_code', 'IELTS', 'overall_score', (r->>'overall')::numeric,
              'component_scores', case when r ? 'min_band' then jsonb_build_object('listening', (r->>'min_band')::numeric, 'reading', (r->>'min_band')::numeric, 'writing', (r->>'min_band')::numeric, 'speaking', (r->>'min_band')::numeric) else '{}'::jsonb end,
              'quote', left(coalesce(r->>'quote', ''), 400)))));
  end loop;
  if v_defaults = '{}'::jsonb and jsonb_array_length(v_ex) = 0 then raise exception 'give at least one level rule or named course'; end if;
  v_prop := jsonb_build_object('parser', 'written out from the central page', 'style', case when v_defaults = '{}'::jsonb then 'named_courses' else 'level_default' end,
                               'defaults', v_defaults, 'exceptions', v_ex, 'named', '[]'::jsonb, 'caveats', '[]'::jsonb, 'signals', '[]'::jsonb, 'conflicts', '[]'::jsonb);
  insert into pipeline.provider_fact_sources(provider_id, kind, url, title, rank, found_via, status)
  values (p_provider_id, 'english_policy', btrim(p_url), 'Central English page given by a Platform Admin', 9, 'manual', 'found')
  on conflict on constraint provider_fact_sources_key do nothing;
  select id, evidence_id into v_src, v_ev from pipeline.provider_fact_sources where provider_id = p_provider_id and kind = 'english_policy' and url = btrim(p_url);
  insert into pipeline.provider_policy_proposals(provider_id, fact_source_id, kind, parser, content_hash, evidence_id, url, style, proposal, status, decision_note)
  values (p_provider_id, v_src, 'english_policy', 'written out from the central page', md5(v_prop::text), v_ev, btrim(p_url), v_prop->>'style', v_prop, 'proposed', left(v_note, 500))
  on conflict (fact_source_id, parser, content_hash) do nothing
  returning id into v_id;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('policies', 'english_rule_proposed', btrim(p_url), jsonb_build_object('decision', 'Decision 254', 'proposal_id', v_id, 'provider_id', p_provider_id, 'rule', p_rule, 'note', v_note), auth.uid());
  return jsonb_build_object('id', v_id, 'note', 'Approve or reject it in Layer 4 Review › Attributes.');
end $_$;


ALTER FUNCTION "public"."admin_provider_english_propose"("p_provider_id" "uuid", "p_rule" "jsonb", "p_url" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_english_status_read"("p_provider" "uuid" DEFAULT NULL::"uuid", "p_stage" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 200) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 4 then raise exception 'Pipeline Operator role required' using errcode = '42501'; end if;
  select jsonb_build_object(
    'stages', (select coalesce(jsonb_object_agg(a.stage, jsonb_build_object('providers', a.n, 'missing_courses', a.m)), '{}'::jsonb)
                 from (select s.stage, count(*) n, sum(s.missing_courses) m from security.english_policy_status_v1(p_provider, null, 1000) s group by 1) a),
    'rows', (select coalesce(jsonb_agg(to_jsonb(s)), '[]'::jsonb) from security.english_policy_status_v1(p_provider, p_stage, p_limit) s),
    'proposals', (select coalesce(jsonb_object_agg(a.status, a.n), '{}'::jsonb) from (select pp.status, count(*) n from pipeline.provider_policy_proposals pp where pp.kind = 'english_policy' group by 1) a),
    'rows_from_groups', (select count(*) from catalogue.course_english_requirements e where e.status = 'active' and e.notes like 'English requirement for the course group%'),
    'credits_7d', (select coalesce(jsonb_object_agg(a.purpose, a.u), '{}'::jsonb) from (select u.purpose, sum(u.units) u from pipeline.coverage_vendor_usage u
                    where u.purpose in ('central_map', 'provider_facts_search', 'provider_facts_scrape') and u.at > now() - interval '7 days' group by 1) a),
    'scope', jsonb_build_object('provider_types', coalesce((select t.value from pipeline.platform_toolset_settings t where t.toolset_key = 'pipeline' and t.key = 'central.english_provider_types'), '["*"]'::jsonb),
                                'search_new_providers', security.pipeline_num_v1('central.english_search_non_university', 0)),
    'jobs', (select coalesce(jsonb_agg(jsonb_build_object('job', j.jobname, 'schedule', j.schedule, 'active', j.active,
                  'last_run', (select jsonb_build_object('at', d.start_time, 'status', d.status) from cron.job_run_details d where d.jobid = j.jobid order by d.start_time desc limit 1)) order by j.jobname), '[]'::jsonb)
               from cron.job j where j.jobname in ('central-find', 'central-attach', 'central-ai', 'provider-facts', 'policy-auto-approve', 'provider-english-defaults', 'policy-add-tests', 'coverage-admit')))
    into v;
  return v;
end $$;


ALTER FUNCTION "public"."admin_provider_english_status_read"("p_provider" "uuid", "p_stage" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_provider_english_status_read"("p_provider" "uuid", "p_stage" "text", "p_limit" integer) IS 'CF-247 English requirements (6 Nov 2026 §5): Coverage › Attributes › English policies, "No rule yet": providers by stage with the reason and the next try, the proposals by status, rows written from course groups, central credits used in 7 days, the provider-type scope, and the jobs of the route. Read only.';



CREATE OR REPLACE FUNCTION "public"."admin_provider_extra_domain"("p_provider" "uuid", "p_domain" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_d text := lower(regexp_replace(regexp_replace(trim(coalesce(p_domain, '')), '^https?://', ''), '/.*$', ''));
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(trim(coalesce(p_reason, ''))) < 5 then raise exception 'reason required'; end if;
  if security.third_party_host_v1('https://' || v_d) then raise exception 'a directory or third-party site is never a provider course domain'; end if;
  insert into pipeline.provider_extra_domains(provider_id, domain, reason, added_by) values (p_provider, v_d, trim(p_reason), auth.uid())
  on conflict (provider_id, domain) do update set state = 'approved', reason = excluded.reason, added_by = excluded.added_by, added_at = now();
  -- discovery runs again for the provider (status back to pending; nothing deleted)
  update pipeline.coverage_provider_discovery set status = 'pending', attempts = 0, next_due_at = now(), updated_at = now() where provider_id = p_provider;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('binding', 'extra_domain', 'pipeline.provider_extra_domains', jsonb_build_object('provider_id', p_provider, 'domain', v_d, 'reason', trim(p_reason)), auth.uid());
  return jsonb_build_object('ok', true, 'domain', v_d);
end $_$;


ALTER FUNCTION "public"."admin_provider_extra_domain"("p_provider" "uuid", "p_domain" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_fee_newer_year"("p_action" "text", "p_source_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare f pipeline.provider_fact_sources%rowtype; x record; v_src uuid; v_n int := 0; v_err int := 0; v_last text; v_rows jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if p_action not in ('preview', 'apply') then raise exception 'action must be preview or apply'; end if;
  select * into f from pipeline.provider_fact_sources where id = p_source_id for update;
  if f.id is null or f.kind <> 'fee_schedule' or f.status <> 'parsed' or f.decision is distinct from 'approved' then raise exception 'not an approved parsed fee schedule'; end if;
  if p_action = 'preview' then
    select coalesce(jsonb_agg(jsonb_build_object('course_code', course_code, 'title', course_title, 'schedule_amount', amount, 'schedule_year', fee_year, 'current_amount', current_amount, 'current_year', cur_year) order by course_title), '[]'::jsonb) into v_rows from (select o.*, cf.fee_year cur_year from security.provider_fee_proposal_rows(p_source_id) o
    join lateral (select y.fee_year from catalogue.course_fees y where y.course_id = o.course_id and y.fee_type = 'provider_current_tuition' and y.status = 'active' and y.audience = 'international'
                   order by y.fee_year desc nulls last limit 1) cf on true
   where o.outcome = 'differs' and o.fee_year is not null and cf.fee_year is not null and o.fee_year > cf.fee_year) ny;
    return jsonb_build_object('rows', v_rows, 'count', jsonb_array_length(v_rows));
  end if;
  if length(btrim(coalesce(p_note, ''))) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if f.evidence_id is null or f.content_hash is null then raise exception 'the document has no stored evidence; read it again first'; end if;
  v_src := security.coverage_sweep_source(f.provider_id);
  for x in select o.*, cf.fee_year cur_year from security.provider_fee_proposal_rows(p_source_id) o
    join lateral (select y.fee_year from catalogue.course_fees y where y.course_id = o.course_id and y.fee_type = 'provider_current_tuition' and y.status = 'active' and y.audience = 'international'
                   order by y.fee_year desc nulls last limit 1) cf on true
   where o.outcome = 'differs' and o.fee_year is not null and cf.fee_year is not null and o.fee_year > cf.fee_year loop
    begin
      perform security.coverage_apply_course_v1(x.course_id, v_src, f.evidence_id, f.url, f.content_hash,
        jsonb_build_object('fee_amount', x.amount, 'currency_code', x.currency_code, 'fee_year', x.fee_year, 'fee_basis', x.basis,
          'fee_notes', 'Later-year fee from the provider''s international fee schedule; approved by a Platform Admin'));
      v_n := v_n + 1;
    exception when others then v_err := v_err + 1; v_last := left(sqlerrm, 200);
    end;
  end loop;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('fees', 'newer_year_fees_applied', f.url, jsonb_build_object('source_id', f.id, 'provider_id', f.provider_id, 'written', v_n, 'refused', v_err, 'last_error', v_last, 'reason', left(p_note, 500)), auth.uid());
  return jsonb_build_object('written', v_n, 'refused', v_err, 'last_error', v_last);
end $$;


ALTER FUNCTION "public"."admin_provider_fee_newer_year"("p_action" "text", "p_source_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_fee_range"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', ''));
  v_pid uuid := nullif(p_args->>'provider_id', '')::uuid; v_res jsonb; v_r catalogue.provider_fee_ranges%rowtype;
  v_low numeric; v_high numeric; v_levels text[];
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 4 then raise exception 'Layer 4 reviewer or Platform Admin required' using errcode = '42501'; end if;
  if p_action = 'read' then
    if v_pid is null then
      return jsonb_build_object('settings', (select to_jsonb(s) - 'id' from pipeline.provider_fee_range_settings s where s.id = 1),
               'levels', (select jsonb_agg(jsonb_build_object('code', l.code, 'name', l.name) order by l.sort_order) from ref.study_levels l where l.status = 'active'),
               'ranges', coalesce((select jsonb_agg(security.provider_fee_range_json_v1(r.provider_id)) from catalogue.provider_fee_ranges r
                                    where p_args->>'scope' = 'all' or exists (select 1 from pipeline.uni_adapters a where a.provider_id = r.provider_id)), '[]'::jsonb));
    end if;
    return jsonb_build_object('range', security.provider_fee_range_json_v1(v_pid),
             'courses', coalesce((select jsonb_agg(to_jsonb(w) order by w.skip nulls first, w.whole_fee) from (select * from security.provider_course_whole_fees_v1(v_pid) limit 2000) w), '[]'::jsonb));
  end if;
  if coalesce(v_rank, 0) < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if p_action = 'refresh' then
    v_res := security.provider_fee_ranges_refresh_v1(v_pid);
  elsif p_action = 'publish' then
    select * into v_r from catalogue.provider_fee_ranges r where r.provider_id = v_pid;
    if v_r.provider_id is null then raise exception 'no range for this provider yet (refresh first)'; end if;
    if coalesce(v_r.manual_low, v_r.low_amount) is null or coalesce(v_r.manual_high, v_r.high_amount) is null then raise exception 'no range to publish'; end if;
    if not v_r.meets_minimum and v_r.manual_low is null and v_r.manual_high is null then raise exception 'fewer courses than the minimum in the settings: set the range by hand or lower the minimum'; end if;
    update catalogue.provider_fee_ranges set published = true, published_by = auth.uid(), published_at = now(), publish_reason = v_reason where provider_id = v_pid;
    v_res := jsonb_build_object('ok', true, 'published', true);
  elsif p_action = 'unpublish' then
    update catalogue.provider_fee_ranges set published = false, published_by = auth.uid(), published_at = now(), publish_reason = v_reason where provider_id = v_pid;
    v_res := jsonb_build_object('ok', true, 'published', false);
  elsif p_action = 'set' then
    v_low := nullif(p_args->>'low', '')::numeric; v_high := nullif(p_args->>'high', '')::numeric;
    if v_low is null or v_high is null or v_low <= 0 or v_high < v_low then raise exception 'give a lowest and a highest amount (lowest no more than highest)'; end if;
    insert into catalogue.provider_fee_ranges(provider_id) values (v_pid) on conflict (provider_id) do nothing;
    update catalogue.provider_fee_ranges set manual_low = v_low, manual_high = v_high, manual_note = nullif(btrim(coalesce(p_args->>'note', '')), ''), manual_by = auth.uid(), manual_at = now() where provider_id = v_pid;
    v_res := jsonb_build_object('ok', true);
  elsif p_action = 'release' then
    update catalogue.provider_fee_ranges set manual_low = null, manual_high = null, manual_note = null, manual_by = auth.uid(), manual_at = now() where provider_id = v_pid;
    v_res := jsonb_build_object('ok', true);
  elsif p_action = 'settings' then
    select array_agg(x) into v_levels from jsonb_array_elements_text(coalesce(p_args->'excluded_level_codes', '[]'::jsonb)) x;
    if exists (select 1 from unnest(coalesce(v_levels, '{}')) x where x not in (select l.code from ref.study_levels l)) then raise exception 'unknown study level'; end if;
    update pipeline.provider_fee_range_settings set include_under_one_year = coalesce((p_args->>'include_under_one_year')::boolean, include_under_one_year), min_courses = coalesce((p_args->>'min_courses')::int, min_courses), min_fee_year = coalesce((p_args->>'min_fee_year')::int, min_fee_year), min_whole_fee = coalesce((p_args->>'min_whole_fee')::numeric, min_whole_fee), excluded_level_codes = coalesce(v_levels, excluded_level_codes), updated_by = auth.uid(), updated_at = now(), reason = v_reason where id = 1;
    v_res := security.provider_fee_ranges_refresh_v1(null);
  else
    raise exception 'unknown action';
  end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('coverage', 'fee_range_' || p_action, coalesce(v_pid::text, 'all'), jsonb_build_object('result', v_res, 'args', p_args), auth.uid());
  return v_res;
end $$;


ALTER FUNCTION "public"."admin_provider_fee_range"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_fee_schedule_decide"("p_source_id" "uuid", "p_action" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare f pipeline.provider_fact_sources%rowtype; x record; v_src uuid; v_n int := 0; v_err int := 0; v_sum jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if p_action not in ('approve','reject') then raise exception 'action must be approve or reject'; end if;
  select * into f from pipeline.provider_fact_sources where id = p_source_id for update;
  if f.id is null or f.kind <> 'fee_schedule' or f.status <> 'parsed' then raise exception 'not a parsed fee schedule'; end if;
  if f.decision is not null then raise exception 'already decided (%)', f.decision; end if;
  if p_action = 'reject' then
    update pipeline.provider_fact_sources set decision = 'rejected', decided_by = auth.uid(), decided_at = now(), decision_note = left(p_note, 500), updated_at = now() where id = p_source_id;
    return jsonb_build_object('decision', 'rejected');
  end if;
  if f.evidence_id is null or f.content_hash is null then raise exception 'the document has no stored evidence; read it again first'; end if;
  v_src := security.coverage_sweep_source(f.provider_id);
  -- what the document proposed, counted before anything is written
  select jsonb_object_agg(o, n) into v_sum from (select outcome o, count(*) n from security.provider_fee_proposal_rows(p_source_id) group by 1) s;
  for x in select * from security.provider_fee_proposal_rows(p_source_id) where outcome = 'new' loop
    begin
      perform security.coverage_apply_course_v1(x.course_id, v_src, f.evidence_id, f.url, f.content_hash,
        jsonb_build_object('fee_amount', x.amount, 'currency_code', x.currency_code, 'fee_year', x.fee_year, 'fee_basis', x.basis,
                           'fee_notes', 'From the provider''s international fee schedule; approved by a Platform Admin'));
      v_n := v_n + 1;
    exception when others then v_err := v_err + 1;
    end;
  end loop;
  v_sum := coalesce(v_sum, '{}'::jsonb) || jsonb_build_object('written', v_n, 'refused', v_err) || jsonb_build_object('flags', security.fee_schedule_settle_flags_v1(p_source_id));
  update pipeline.provider_fact_sources set decision = 'approved', decided_by = auth.uid(), decided_at = now(), decision_note = left(p_note, 500),
         apply_summary = v_sum, updated_at = now() where id = p_source_id;
  return jsonb_build_object('decision', 'approved') || v_sum;
end $$;


ALTER FUNCTION "public"."admin_provider_fee_schedule_decide"("p_source_id" "uuid", "p_action" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_fee_schedule_refile"("p_source_id" "uuid", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare f pipeline.provider_fact_sources%rowtype; x record; v_src uuid; v_n int := 0; v_err int := 0; v_last text;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  select * into f from pipeline.provider_fact_sources where id = p_source_id for update;
  if f.id is null or f.kind <> 'fee_schedule' or f.status <> 'parsed' or f.decision is distinct from 'approved' then raise exception 'not an approved parsed fee schedule'; end if;
  if length(btrim(coalesce(p_note, ''))) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if f.evidence_id is null or f.content_hash is null then raise exception 'the document has no stored evidence; read it again first'; end if;
  v_src := security.coverage_sweep_source(f.provider_id);
  for x in select * from security.provider_fee_proposal_rows(p_source_id) where outcome = 'new' loop
    begin
      perform security.coverage_apply_course_v1(x.course_id, v_src, f.evidence_id, f.url, f.content_hash,
        jsonb_build_object('fee_amount', x.amount, 'currency_code', x.currency_code, 'fee_year', x.fee_year, 'fee_basis', x.basis,
                           'fee_notes', 'From the provider''s international fee schedule; refiled by a Platform Admin'));
      v_n := v_n + 1;
    exception when others then v_err := v_err + 1; v_last := left(sqlerrm, 200);
    end;
  end loop;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('fees', 'fee_schedule_refiled', f.url, jsonb_build_object('source_id', f.id, 'provider_id', f.provider_id, 'written', v_n, 'refused', v_err, 'last_error', v_last, 'reason', left(p_note, 500)), auth.uid());
