end $$;


ALTER FUNCTION "public"."admin_provider_fee_schedule_refile"("p_source_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_fee_schedules_read"("p_source_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
begin
  if auth.uid() is null or v_rank < 4 then raise exception 'pipeline operator role required' using errcode = '42501'; end if;
  if p_source_id is not null then
    return jsonb_build_object('can_decide', v_rank >= 6, 'rows', coalesce((select jsonb_agg(to_jsonb(x) order by x.outcome, x.course_code)
             from security.provider_fee_proposal_rows(p_source_id) x), '[]'::jsonb));
  end if;
  return jsonb_build_object(
    'can_decide', v_rank >= 6,
    'totals', (select jsonb_build_object(
        'documents_found', count(*) filter (where f.kind = 'fee_schedule'),
        'documents_read', count(*) filter (where f.kind = 'fee_schedule' and f.status in ('parsed','no_values')),
        'with_fee_rows', count(*) filter (where f.status = 'parsed'),
        'awaiting_decision', count(*) filter (where f.status = 'parsed' and f.decision is null),
        'providers_searched', (select count(distinct s.provider_id) from pipeline.provider_fact_search s where s.kind = 'fee_schedule' and s.state <> 'queued'),
        'providers_queued', (select count(*) from pipeline.provider_fact_search s where s.kind = 'fee_schedule' and s.state = 'queued'))
        from pipeline.provider_fact_sources f),
    'documents', coalesce((select jsonb_agg(d order by d->>'decided_at' desc nulls first, (d->>'new')::int desc) from (
        select jsonb_build_object('id', f.id, 'provider_id', f.provider_id, 'provider', coalesce(p.display_name, p.canonical_name), 'country', security.coverage_country(f.provider_id), 'url', f.url, 'fee_year', f.parse_summary->>'fee_year',
               'read_at', f.read_at, 'decision', f.decision, 'decided_at', f.decided_at, 'apply_summary', f.apply_summary,
               'rows', k.n, 'new', k.n_new, 'same', k.n_same, 'differs', k.n_differs, 'no_course', k.n_no_course) d
          from pipeline.provider_fact_sources f join catalogue.providers p on p.id = f.provider_id
          -- Layer 4 recovery (1 Nov 2026): each document's proposal rows are worked out once, not five times (8.2 s timed out at the 8 s limit)
          cross join lateral (select count(*) n, count(*) filter (where x.outcome = 'new') n_new, count(*) filter (where x.outcome = 'same') n_same,
                                     count(*) filter (where x.outcome = 'differs') n_differs, count(*) filter (where x.outcome = 'no_course') n_no_course
                                from security.provider_fee_proposal_rows(f.id) x) k
         where f.status = 'parsed' order by (f.decision is null) desc, f.read_at desc limit greatest(1, least(coalesce(p_limit, 50), 300))) q), '[]'::jsonb));
end $$;


ALTER FUNCTION "public"."admin_provider_fee_schedules_read"("p_source_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_fee_year_relabel"("p_action" "text", "p_source_later" "uuid", "p_source_earlier" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare fl pipeline.provider_fact_sources%rowtype; fe pipeline.provider_fact_sources%rowtype; v_rows jsonb; v_all jsonb; x jsonb; v_src uuid; v_n int := 0; v_err int := 0; v_last text;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if p_action not in ('preview', 'apply') then raise exception 'action must be preview or apply'; end if;
  select * into fl from pipeline.provider_fact_sources where id = p_source_later for update;
  select * into fe from pipeline.provider_fact_sources where id = p_source_earlier for update;
  if fl.id is null or fe.id is null or fl.provider_id <> fe.provider_id or fl.kind <> 'fee_schedule' or fe.kind <> 'fee_schedule'
     or fl.decision is distinct from 'approved' or fe.decision is distinct from 'approved' or fl.status <> 'parsed' or fe.status <> 'parsed' then
    raise exception 'two approved parsed fee schedules of one provider are required'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('course_id', l.course_id, 'title', l.course_title, 'later_amount', l.amount, 'later_year', l.fee_year, 'later_basis', l.basis, 'later_currency', l.currency_code,
         'earlier_amount', e.amount, 'earlier_year', e.fee_year, 'earlier_basis', e.basis, 'earlier_currency', e.currency_code) order by l.course_title), '[]'::jsonb) into v_all
    from security.provider_fee_proposal_rows(p_source_later) l
    join security.provider_fee_proposal_rows(p_source_earlier) e on e.course_id = l.course_id
   where l.fee_year is not null and e.fee_year is not null and l.fee_year > e.fee_year and l.course_id is not null and l.basis = 'annual' and e.basis = 'annual'
     and exists (select 1 from catalogue.course_fees y where y.course_id = l.course_id and y.fee_type = 'provider_current_tuition' and y.status = 'active' and y.audience = 'international'
                 and y.fee_year = e.fee_year and abs(y.amount - l.amount) < 1)
     and abs(e.amount - l.amount) >= 1
     and not exists (select 1 from catalogue.course_fees y where y.course_id = l.course_id and y.fee_type = 'provider_current_tuition' and y.status = 'active' and y.audience = 'international' and y.fee_year = l.fee_year);
  select coalesce(jsonb_agg(el - 'course_id'), '[]'::jsonb) into v_rows from jsonb_array_elements(v_all) el;
  if p_action = 'preview' then return jsonb_build_object('count', jsonb_array_length(v_all), 'rows', v_rows); end if;
  if length(btrim(coalesce(p_note, ''))) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if fl.evidence_id is null or fe.evidence_id is null or fl.content_hash is null or fe.content_hash is null then raise exception 'both documents need stored evidence'; end if;
  v_src := security.coverage_sweep_source(fl.provider_id);
  for x in select el from jsonb_array_elements(v_all) el loop
    begin
      perform security.coverage_apply_course_v1((x->>'course_id')::uuid, v_src, fe.evidence_id, fe.url, fe.content_hash,
        jsonb_build_object('fee_amount', (x->>'earlier_amount')::numeric, 'currency_code', x->>'earlier_currency', 'fee_year', (x->>'earlier_year')::int, 'fee_basis', x->>'earlier_basis',
          'fee_notes', 'Earlier-year fee from the provider''s international fee schedule; the page figure was the later year; approved by a Platform Admin'));
      perform security.coverage_apply_course_v1((x->>'course_id')::uuid, v_src, fl.evidence_id, fl.url, fl.content_hash,
        jsonb_build_object('fee_amount', (x->>'later_amount')::numeric, 'currency_code', x->>'later_currency', 'fee_year', (x->>'later_year')::int, 'fee_basis', x->>'later_basis',
          'fee_notes', 'Later-year fee from the provider''s international fee schedule; matches the course page; approved by a Platform Admin'));
      v_n := v_n + 1;
    exception when others then v_err := v_err + 1; v_last := left(sqlerrm, 200);
    end;
  end loop;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('fees', 'fee_year_relabelled', fl.url, jsonb_build_object('later_source', fl.id, 'earlier_source', fe.id, 'provider_id', fl.provider_id, 'courses', v_n, 'refused', v_err, 'last_error', v_last, 'reason', left(p_note, 500)), auth.uid());
  return jsonb_build_object('courses', v_n, 'refused', v_err, 'last_error', v_last);
end $$;


ALTER FUNCTION "public"."admin_provider_fee_year_relabel"("p_action" "text", "p_source_later" "uuid", "p_source_earlier" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_identity"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := coalesce(security.current_role_rank(), 0); v_pid uuid := nullif(p_args->>'provider_id', '')::uuid; v_url text := btrim(coalesce(p_args->>'url', ''));
        v_src text := nullif(btrim(coalesce(p_args->>'source', '')), ''); v_id bigint;
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  if p_action = 'summary' then
    return jsonb_build_object(
      'findings', (select coalesce(jsonb_object_agg(check_code, n), '{}'::jsonb) from (select check_code, count(*) n from pipeline.provider_identity_findings where state = 'open' group by 1) z),
      'investigations', (select coalesce(jsonb_object_agg(state, n), '{}'::jsonb) from (select state, count(*) n from pipeline.provider_identity_investigations group by 1) z),
      'lifecycle', (select coalesce(jsonb_object_agg(state, n), '{}'::jsonb) from (select state, count(*) n from pipeline.provider_lifecycle_events group by 1) z));
  elsif p_action = 'provider' then
    return jsonb_build_object('findings', (select coalesce(jsonb_agg(to_jsonb(f)), '[]'::jsonb) from pipeline.provider_identity_findings f where f.provider_id = v_pid),
                              'investigations', (select coalesce(jsonb_agg(to_jsonb(i) order by i.opened_at desc), '[]'::jsonb) from pipeline.provider_identity_investigations i where i.provider_id = v_pid),
                              'evidence', security.provider_identity_evidence_v1(v_pid));
  elsif p_action = 'candidate' then
    if v_rank < 5 then raise exception 'PIM Operator role or above required' using errcode = '42501'; end if;
    if security.website_refusal_v1(v_url) is not null or v_url = '' then raise exception 'enter one full web address starting with https://'; end if;
    if length(coalesce(v_src, '')) < 8 then raise exception 'say where the candidate comes from (a register entry or a first-party page), not how it was guessed'; end if;
    select id into v_id from pipeline.provider_identity_investigations where provider_id = v_pid and state in ('open', 'blocked_evidence', 'proposed');
    if v_id is null then raise exception 'no open identity investigation for this provider'; end if;
    update pipeline.provider_identity_investigations set candidates = candidates || jsonb_build_array(jsonb_build_object('url', v_url, 'provenance', 'person', 'ref', v_src, 'by', auth.uid(), 'at', now())),
           updated_at = now() where id = v_id;
    -- the existing website check (Curator and above, one at a time per provider) reads the candidate; it never saves a website
    return jsonb_build_object('investigation', v_id, 'check', public.admin_provider_website_check('check', jsonb_build_object('provider_id', v_pid, 'url', v_url)));
  elsif p_action = 'close' then
    if v_rank < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
    update pipeline.provider_identity_investigations set state = 'closed', closed_at = now(), closed_by = auth.uid(), close_note = left(coalesce(p_args->>'note', ''), 500), updated_at = now()
     where id = (p_args->>'investigation')::bigint and state in ('open', 'blocked_evidence', 'proposed');
    return jsonb_build_object('closed', found);
  end if;
  raise exception 'unknown action %', p_action;
end $$;


ALTER FUNCTION "public"."admin_provider_identity"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_provider_identity"("p_action" "text", "p_args" "jsonb") IS 'CF-247 ops G: provider identity findings and investigations; a candidate site with its provenance goes to the existing website check (never saved here)';



CREATE OR REPLACE FUNCTION "public"."admin_provider_lifecycle"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := coalesce(security.current_role_rank(), 0); v_id bigint := nullif(p_args->>'event', '')::bigint; v_note text := nullif(btrim(coalesce(p_args->>'note', '')), ''); v_new bigint;
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  if p_action = 'list' then
    return coalesce((select jsonb_agg(to_jsonb(e) - 'plan' order by e.created_at desc) from (select * from pipeline.provider_lifecycle_events order by created_at desc limit 200) e), '[]'::jsonb);  -- fixed: a screen page
  elsif p_action = 'plan' then
    return security.provider_lifecycle_plan_v1(v_id);
  elsif p_action = 'propose' then
    if v_rank < 5 then raise exception 'PIM Operator role or above required' using errcode = '42501'; end if;
    if not security.provider_lifecycle_evidence_ok_v1(p_args->'evidence') then raise exception 'authoritative evidence is required: a register record, a first-party page or an admin record, each with a reference'; end if;
    insert into pipeline.provider_lifecycle_events(scope, provider_id, country_id, transition, successor_provider_id, effective_date, evidence, source)
    values (coalesce(p_args->>'scope', 'provider'), nullif(p_args->>'provider_id', '')::uuid, nullif(p_args->>'country_id', '')::uuid, p_args->>'transition',
            nullif(p_args->>'successor_provider_id', '')::uuid, (p_args->>'effective_date')::date,
            p_args->'evidence' || jsonb_build_array(jsonb_build_object('kind', 'admin_record', 'ref', 'auth.users:' || auth.uid(), 'at', now(), 'note', v_note)), 'admin')
    returning id into v_new;
    update pipeline.provider_lifecycle_events set plan = security.provider_lifecycle_plan_v1(v_new), planned_at = now(), state = 'planned' where id = v_new;
    return jsonb_build_object('event', v_new, 'state', 'planned');
  elsif p_action in ('approve', 'reject', 'execute', 'reverse', 'replan') then
    if v_rank < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
    if p_action = 'replan' then
      update pipeline.provider_lifecycle_events set plan = security.provider_lifecycle_plan_v1(v_id), planned_at = now(), updated_at = now() where id = v_id and state in ('planned', 'approved');
      return jsonb_build_object('event', v_id, 'replanned', found);
    elsif p_action in ('approve', 'reject') then
      if length(coalesce(v_note, '')) < 4 then raise exception 'a reason is required'; end if;
      update pipeline.provider_lifecycle_events set state = case when p_action = 'approve' then 'approved' else 'rejected' end, decided_by = auth.uid(), decided_at = now(),
             decision_note = v_note, updated_at = now()
       where id = v_id and state = 'planned';
      if not found then raise exception 'only a planned event can be approved or rejected'; end if;
      insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('provider', 'lifecycle_' || p_action, v_id::text, jsonb_build_object('note', v_note), auth.uid());
      return jsonb_build_object('event', v_id, 'state', case when p_action = 'approve' then 'approved' else 'rejected' end);
    elsif p_action = 'execute' then
      return security.provider_lifecycle_execute_v1(v_id, auth.uid());
    else
      return security.provider_lifecycle_reverse_v1(v_id, auth.uid(), v_note);
    end if;
  end if;
  raise exception 'unknown action %', p_action;
end $$;


ALTER FUNCTION "public"."admin_provider_lifecycle"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_provider_lifecycle"("p_action" "text", "p_args" "jsonb") IS 'CF-247 ops G: provider and country lifecycle events: list, plan, propose (with authoritative evidence), approve, reject, execute (lifecycle.cascade_on), reverse';



CREATE OR REPLACE FUNCTION "public"."admin_provider_logo_capability"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int; v_min int;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode = '42501'; end if;
  v_rank := security.current_role_rank(); v_min := security.logo_upload_min_rank_v1();
  return jsonb_build_object('rank', v_rank, 'min_rank', v_min, 'can_upload', v_rank >= v_min,
    'finder', (select jsonb_build_object('checked', count(*) filter (where status not in ('queued', 'trying')),
                                         'found', count(*) filter (where status = 'found'),
                                         'not_found', count(*) filter (where status in ('not_found', 'failed')),
                                         'waiting', count(*) filter (where status in ('queued', 'trying') or requested_at is not null))
                 from pipeline.provider_logo_finds));
end $$;


ALTER FUNCTION "public"."admin_provider_logo_capability"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_logo_find_request"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode = '42501'; end if;
  if security.current_role_rank() < security.logo_upload_min_rank_v1() then raise exception 'your role cannot change logos' using errcode = '42501'; end if;
  if not exists (select 1 from catalogue.providers p where p.id = p_provider_id) then raise exception 'provider not found' using errcode = 'P0002'; end if;
  insert into pipeline.provider_logo_finds(provider_id, status, requested_at, requested_by, updated_at)
  values (p_provider_id, 'queued', now(), auth.uid(), now())
  on conflict (provider_id) do update set status = 'queued', requested_at = now(), requested_by = auth.uid(), updated_at = now();
  return jsonb_build_object('provider_id', p_provider_id, 'queued', true,
    'has_website', exists (select 1 from catalogue.providers p where p.id = p_provider_id and nullif(btrim(p.website), '') is not null));
end $$;


ALTER FUNCTION "public"."admin_provider_logo_find_request"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_onboarding"("p_action" "text" DEFAULT 'read'::"text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', '')); v_ids uuid[]; v_n int;
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  -- v2.15.255: one university's journey: steps, tasks, AI drafts, and the scholarships found with their state
  if p_action = 'journey' then
    return (select jsonb_build_object('id', o.id, 'status', o.status, 'stop_reason', o.stop_reason, 'started_at', o.started_at,
      'stage', security.provider_onboarding_stage_v1(o.status, o.stop_reason, o.result), 'phase', o.result->>'phase', 'source', o.source,
      'admitted_at', o.result->'admitted_at', 'enriched', o.result->'enriched', 'auto_admitted', o.result->'auto_admitted', 'scholarship_admit', o.result->'scholarship_admit', 'finished_at', o.finished_at, 'ai_attempts', coalesce((o.result->>'ai_attempts')::int, 0),
      'qualify', o.result->'qualify', 'held', o.result->'held', 'ready', o.result->'ready', 'central_pages', o.result->'central_pages', 'scholarship_search', o.result->'scholarships',
      'events', (select coalesce(jsonb_agg(jsonb_build_object('at', e.at, 'status', e.status, 'stop_reason', e.stop_reason, 'note', e.note) order by e.at), '[]'::jsonb)
                   from pipeline.provider_onboarding_events e where e.onboarding_id = o.id),
      'tasks', (select coalesce(jsonb_agg(jsonb_build_object('id', j.id, 'kind', j.kind, 'title', j.title, 'state', j.state, 'created_at', j.created_at, 'finished_at', j.finished_at,
                   'note', left(coalesce(j.result->>'note', j.error, ''), 300)) order by j.created_at), '[]'::jsonb)
                  from pipeline.admin_jobs j where j.scope = o.provider_id::text and j.created_at >= coalesce(o.started_at, o.created_at) - interval '1 minute'),
      'drafts', (select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'status', d.status, 'created_at', d.created_at, 'updated_at', d.updated_at, 'samples', jsonb_array_length(coalesce(d.samples, '[]'::jsonb)),
                   'proposals', jsonb_array_length(coalesce(d.proposals, '[]'::jsonb)), 'model', d.model, 'cost_usd', d.cost_usd, 'reason', d.reason) order by d.created_at), '[]'::jsonb)
                  from pipeline.uni_adapter_drafts d where d.provider_id = o.provider_id and d.created_at >= coalesce(o.started_at, o.created_at) - interval '1 minute'),
      'scholarships', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name, 'publication_status', s.publication_status, 'lifecycle_status', s.lifecycle_status,
                   'created_at', s.created_at, 'url', s.source_url) order by s.created_at desc), '[]'::jsonb)
                  from scholarship.scholarships s where s.provider_id = o.provider_id and s.created_at >= coalesce(o.started_at, o.created_at) - interval '1 minute'),
      'ai_waiting', (select count(*) from pipeline.scholarship_ai_queue q where q.provider_id = o.provider_id and q.state = 'queued'),
      'ai_read', (select coalesce(jsonb_object_agg(t.v, t.n), '{}'::jsonb) from (select coalesce(x.verdict, 'failed') v, count(*) n from pipeline.scholarship_ai_extractions x
                   where x.provider_id = o.provider_id and x.at >= coalesce(o.started_at, o.created_at) group by 1) t))
      from pipeline.provider_onboarding o where o.id = nullif(p_args->>'id', '')::uuid);
  end if;
  -- v2.15.259: the pilot group now (live) and its hourly snapshots
  if p_action = 'pilot' then
    return (select jsonb_build_object('cohort', c.cohort, 'report', security.onboarding_pilot_report_v1(c.cohort),
              'snapshots', (select coalesce(jsonb_agg(jsonb_build_object('at', s.at, 'data', s.data) order by s.at), '[]'::jsonb)
                              from pipeline.onboarding_pilot_snapshots s where s.cohort = c.cohort))
              from (select m.cohort from pipeline.onboarding_pilot m group by m.cohort order by max(m.picked_at) desc limit 1) c);
  end if;
  if p_action <> 'read' then
    if v_rank < 6 then raise exception 'Platform Admin required' using errcode = '42501'; end if;
    if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
    if p_action = 'start' then
      v_ids := case when p_args->>'scope' = 'no_adapter' then array(
                 select pr.id from catalogue.providers pr
                  where pr.lifecycle_status = 'active' and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = pr.id)
                    and exists (select 1 from catalogue.courses c where c.provider_id = pr.id and c.lifecycle_status = 'active')
                    and not exists (select 1 from pipeline.uni_adapters a where a.provider_id = pr.id and a.enabled and coalesce(a.admit, false)))
               else array(select x::uuid from jsonb_array_elements_text(coalesce(p_args->'provider_ids', '[]'::jsonb)) x) end;
      if coalesce(cardinality(v_ids), 0) = 0 then raise exception 'choose universities'; end if;
      insert into pipeline.provider_onboarding(provider_id, source, requested_by, reason, priority)
      select i, case when p_args->>'scope' = 'no_adapter' then 'backfill' else 'manual' end, auth.uid(), v_reason,
             case when p_args->>'scope' = 'no_adapter' then (select least(count(*), 99999)::int from catalogue.courses c where c.provider_id = i and c.lifecycle_status = 'active') else 200000 end
        from unnest(v_ids) i
      on conflict do nothing;
      get diagnostics v_n = row_count;
    elsif p_action = 'stop' then
      update pipeline.provider_onboarding set status = 'cancelled', note = 'Stopped by a person: ' || v_reason, finished_at = now(), updated_at = now()
       where id = any (array(select x::uuid from jsonb_array_elements_text(coalesce(p_args->'ids', '[]'::jsonb)) x)) and status not in ('done', 'cancelled');
      get diagnostics v_n = row_count;
    elsif p_action = 'retry' then
      update pipeline.provider_onboarding set status = case when stop_reason in ('capture_failed', 'proposal_failed') then 'course_pages' else 'website' end,
             stop_reason = null, attempts = 0, job_id = null, step_started_at = now(), note = 'Retried by a person: ' || v_reason, requested_by = auth.uid(), updated_at = now()
       where id = any (array(select x::uuid from jsonb_array_elements_text(coalesce(p_args->'ids', '[]'::jsonb)) x)) and status = 'stopped';
      get diagnostics v_n = row_count;
    elsif p_action = 'settings' then
      update pipeline.provider_onboarding_settings set enabled = coalesce((p_args->>'enabled')::boolean, enabled), auto_start_new = coalesce((p_args->>'auto_start_new')::boolean, auto_start_new),
             max_active = coalesce((p_args->>'max_active')::int, max_active), run_as = case when (p_args->>'run_as_me')::boolean then auth.uid() else run_as end,
             changed_by = auth.uid(), changed_at = now(), reason = v_reason,
             -- v2.15.259: Admit automatically, recorded with who and why
             auto_admit = coalesce((p_args->>'auto_admit')::boolean, auto_admit),
             auto_admit_reason = case when p_args ? 'auto_admit' then v_reason else auto_admit_reason end,
             auto_admit_by = case when p_args ? 'auto_admit' then auth.uid() else auto_admit_by end,
             auto_admit_at = case when p_args ? 'auto_admit' then now() else auto_admit_at end where id = 1;
      v_n := 1;
    elsif p_action = 'pilot_pick' then
      v_n := security.onboarding_pilot_pick_v1(coalesce(nullif(p_args->>'cohort', ''), 'pilot-' || to_char(now() at time zone 'Australia/Melbourne', 'YYYY-MM-DD')),
               coalesce((p_args->>'au')::int, 60), coalesce((p_args->>'nz')::int, 25), coalesce((p_args->>'ca')::int, 15));
    else raise exception 'unknown action';
    end if;
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('onboarding', p_action, coalesce(p_args->>'scope', ''), p_args || jsonb_build_object('count', v_n), auth.uid());
  end if;
  return jsonb_build_object(
    'can_manage', v_rank >= 6,
    'settings', (select to_jsonb(s) - 'id' from pipeline.provider_onboarding_settings s where s.id = 1),
    'counts', (select coalesce(jsonb_object_agg(t.status, t.n), '{}'::jsonb) from (select status, count(*) n from pipeline.provider_onboarding group by 1) t),
    -- v2.15.258: rows by journey stage (1 Provider in ... 7 Admit scholarships, then Done)
    'pilot_latest', (select jsonb_build_object('at', s.at, 'data', s.data) from pipeline.onboarding_pilot_snapshots s order by s.at desc limit 1),
    'stages', (select coalesce(jsonb_object_agg(t.stage, t.n), '{}'::jsonb) from (select security.provider_onboarding_stage_v1(status, stop_reason, result) stage, count(*) n
                 from pipeline.provider_onboarding group by 1) t),
    'stops', (select coalesce(jsonb_object_agg(t.r, t.n), '{}'::jsonb) from (select stop_reason r, count(*) n from pipeline.provider_onboarding where status = 'stopped' group by 1) t),
    'without_adapter', (select count(*) from catalogue.providers pr where pr.lifecycle_status = 'active'
                          and exists (select 1 from catalogue.courses c where c.provider_id = pr.id and c.lifecycle_status = 'active')
                          and not exists (select 1 from pipeline.uni_adapters a where a.provider_id = pr.id and a.enabled and coalesce(a.admit, false))),
    -- v2.15.258: universities without an admitting adapter that are not in onboarding yet (what "Onboard all" would add), and the pace
    'not_queued', (select count(*) from catalogue.providers pr where pr.lifecycle_status = 'active'
                     and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = pr.id)
                     and exists (select 1 from catalogue.courses c where c.provider_id = pr.id and c.lifecycle_status = 'active')
                     and not exists (select 1 from pipeline.uni_adapters a where a.provider_id = pr.id and a.enabled and coalesce(a.admit, false))
                     and not exists (select 1 from pipeline.provider_onboarding o where o.provider_id = pr.id and o.status not in ('done', 'cancelled'))),
    'pace', (select jsonb_build_object('finished_last_hour', count(distinct e.onboarding_id) filter (where e.at > now() - interval '1 hour'),
                                       'finished_last_6_hours', count(distinct e.onboarding_id))
               from pipeline.provider_onboarding_events e where e.at > now() - interval '6 hours' and e.status in ('waiting_admit', 'stopped', 'done')),
    'approvals_waiting', (select count(*) from pipeline.provider_fact_sources fs where fs.decision is null and fs.status = 'parsed' and fs.kind = 'fee_schedule')
                         + (select count(*) from pipeline.provider_policy_proposals pp where pp.status = 'proposed'),
    'rows', (select coalesce(jsonb_agg(x order by x->>'sort'), '[]'::jsonb) from (
       select jsonb_build_object('sort', lpad((case o.status when 'stopped' then 1 when 'waiting_admit' then 2 else 3 end)::text, 2, '0') || to_char(o.updated_at, 'YYYYMMDDHH24MISS'),
              'id', o.id, 'provider_id', o.provider_id, 'name', coalesce(nullif(pr.display_name, ''), pr.canonical_name), 'country', (select k.iso_alpha2 from ref.countries k where k.id = pr.country_id),
              'website', pr.website, 'status', o.status, 'stop_reason', o.stop_reason,
              'stage', security.provider_onboarding_stage_v1(o.status, o.stop_reason, o.result), 'phase', o.result->>'phase', 'enriched', o.result->'enriched',
              'in_register', pr.canonical_source_id is not null, 'note', o.note, 'source', o.source, 'job_id', o.job_id,
              'auto_admitted', o.result->'auto_admitted', 'pilot', exists (select 1 from pipeline.onboarding_pilot m where m.provider_id = o.provider_id),
              'ready', o.result->'ready', 'held', o.result->'held', 'central_pages', o.result->'central_pages', 'scholarships', o.result->'scholarships'->'new_scholarships', 'ai_attempts', coalesce((o.result->>'ai_attempts')::int, 0),
              'scholarships_live', jsonb_build_object('found', (select count(*) from scholarship.scholarships s where s.provider_id = o.provider_id and s.created_at >= coalesce(o.started_at, o.created_at) - interval '1 minute'),
                 'published', (select count(*) from scholarship.scholarships s where s.provider_id = o.provider_id and s.created_at >= coalesce(o.started_at, o.created_at) - interval '1 minute' and s.publication_status = 'published'),
                 'waiting_ai', (select count(*) from pipeline.scholarship_ai_queue q where q.provider_id = o.provider_id and q.state = 'queued'),
                 'searched', o.result ? 'scholarships'),
              'courses', (select count(*) from catalogue.courses c where c.provider_id = o.provider_id and c.lifecycle_status = 'active'),
              'pages_read', (select count(*) from pipeline.coverage_course_pages pg where pg.provider_id = o.provider_id and pg.read_status = 'read'),
              'started_at', o.started_at, 'step_started_at', o.step_started_at, 'updated_at', o.updated_at, 'finished_at', o.finished_at, 'created_at', o.created_at) x
         from pipeline.provider_onboarding o join catalogue.providers pr on pr.id = o.provider_id
        where (p_args->>'status' is null or o.status = p_args->>'status' or (p_args->>'status' = 'active' and o.status in ('website', 'course_pages', 'capturing', 'proposing', 'applying', 'qualifying', 'scholarships')))
          and (coalesce((p_args->>'pilot')::boolean, false) = false or exists (select 1 from pipeline.onboarding_pilot m where m.provider_id = o.provider_id))
          and (p_args->>'stage' is null or security.provider_onboarding_stage_v1(o.status, o.stop_reason, o.result) = p_args->>'stage')
          and (p_args->>'q' is null or coalesce(pr.display_name, pr.canonical_name) ilike '%' || (p_args->>'q') || '%')
        order by case o.status when 'stopped' then 1 when 'waiting_admit' then 2 else 3 end, o.updated_at desc
        limit least(greatest(coalesce((p_args->>'limit')::int, 200), 1), 500)) t));
end $$;


ALTER FUNCTION "public"."admin_provider_onboarding"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_pick_v1"("p_query" "text" DEFAULT NULL::"text", "p_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank();
        v_q text := nullif(btrim(coalesce(p_query, '')), '');
        v_like text;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 3 then raise exception 'assigned StudySearch role required' using errcode = '42501'; end if;
  v_like := '%' || replace(replace(replace(coalesce(v_q, ''), '\', '\\'), '%', '\%'), '_', '\_') || '%';
  return jsonb_build_object(
    -- the providers already in the list, by name (archived ones too, so a stale id is still named)
    'named', (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', coalesce(p.display_name, p.canonical_name), 'country', c.iso_alpha2,
                                                           'archived', p.lifecycle_status = 'archived') order by coalesce(p.display_name, p.canonical_name)), '[]'::jsonb)
                from catalogue.providers p left join ref.countries c on c.id = p.country_id
               where p.id = any (coalesce(p_ids, '{}'))),
    -- providers to add: active, name or short name contains the search (two characters or more)
    'found', case when length(coalesce(v_q, '')) < 2 then '[]'::jsonb else
             (select coalesce(jsonb_agg(jsonb_build_object('id', z.id, 'name', z.name, 'country', z.country) order by z.rk, z.name), '[]'::jsonb)
                from (select p.id, coalesce(p.display_name, p.canonical_name) as name, c.iso_alpha2 as country,
                             case when lower(coalesce(p.short_name, '')) = lower(v_q) then 0
                                  when lower(coalesce(p.display_name, p.canonical_name)) like lower(v_q) || '%' then 1 else 2 end as rk
                        from catalogue.providers p left join ref.countries c on c.id = p.country_id
                       where p.lifecycle_status = 'active'
                         and (coalesce(p.display_name, p.canonical_name) ilike v_like escape '\' or p.canonical_name ilike v_like escape '\'
                              or coalesce(p.short_name, '') ilike v_like escape '\')
                       order by 4, 2
                       limit 20) z) end);  -- fixed: one display page of search results
end $$;


ALTER FUNCTION "public"."admin_provider_pick_v1"("p_query" "text", "p_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_provider_pick_v1"("p_query" "text", "p_ids" "uuid"[]) IS 'CF-247 F-OPS (11 Nov 2026): Settings > Pipeline settings provider picker. Names the provider ids of a list setting and finds active providers by name. Read only; role rank 3 or more.';



CREATE OR REPLACE FUNCTION "public"."admin_provider_policies_read"("p_kind" "text" DEFAULT 'english_policy'::"text", "p_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 4 then raise exception 'Pipeline Operator role required' using errcode = '42501'; end if;
  if p_kind not in ('english_policy', 'intake_calendar') then raise exception 'kind must be english_policy or intake_calendar'; end if;
  if p_id is not null then
    select jsonb_build_object('proposal', to_jsonb(x) - 'content_hash', 'provider', coalesce(p.display_name, p.canonical_name),
             'rows', case when x.kind = 'english_policy' then (select coalesce(jsonb_agg(jsonb_build_object('course_id', r.course_id, 'title', r.title, 'study_level', r.study_level,
                   'plan', r.plan, 'reason', r.reason, 'outcome', r.outcome, 'existing', r.existing,
                   'ielts', (select q->'overall_score' from jsonb_array_elements(r.requirements) q where q->>'test_code' = 'IELTS' limit 1))
                   order by case r.outcome when 'write' then 0 when 'differs' then 1 when 'agrees' then 2 else 3 end, r.title), '[]'::jsonb)
                   from security.provider_english_plan_v1(x.id) r) end)
      into v from pipeline.provider_policy_proposals x join catalogue.providers p on p.id = x.provider_id
     where x.id = p_id and x.kind = p_kind;
    if v is null then raise exception 'proposal not found'; end if;
    return v;
  end if;
  select jsonb_build_object(
    'can_decide', security.current_role_rank() >= 6,
    'totals', jsonb_build_object(
      'documents_found', (select count(*) from pipeline.provider_fact_sources f where f.kind = p_kind),
      'documents_read', (select count(*) from pipeline.provider_fact_sources f where f.kind = p_kind and f.status in ('read', 'parsed', 'no_values')),
      'providers_found', (select count(distinct f.provider_id) from pipeline.provider_fact_sources f where f.kind = p_kind),
      'no_values_by_style', (select coalesce(jsonb_object_agg(coalesce(style, 'none'), n), '{}'::jsonb) from (select style, count(*) n from pipeline.provider_policy_proposals
                               where kind = p_kind and status = 'no_values' group by 1) s)),
    'proposals', (select coalesce(jsonb_agg(jsonb_build_object(
         'id', x.id, 'provider_id', x.provider_id, 'provider', coalesce(p.display_name, p.canonical_name), 'country', k.iso_alpha2,
         'url', x.url, 'style', x.style, 'status', x.status, 'parser', x.parser, 'created_at', x.created_at,
         'decided_at', x.decided_at, 'decision_note', x.decision_note, 'apply_summary', x.apply_summary,
         'caveats', x.proposal->'caveats', 'conflicts', x.proposal->'conflicts',
         'defaults', x.proposal->'defaults', 'periods', x.proposal->'periods',
         'group_count', jsonb_array_length(case when jsonb_typeof(x.proposal->'groups') = 'array' then x.proposal->'groups' else '[]'::jsonb end), 'bound_groups', jsonb_array_length(coalesce(x.proposal->'group_bindings', '[]'::jsonb)),
         'named_requirements', (select count(*) from jsonb_array_elements(coalesce(x.proposal->'exceptions', '[]'::jsonb)) e where jsonb_typeof(e->'reqs') = 'array' and jsonb_array_length(e->'reqs') > 0),
         'named_courses', jsonb_array_length(coalesce(x.proposal->'named', '[]'::jsonb)),
         'plan', x.plan_summary, 'plan_at', x.plan_at)
       order by (x.status = 'proposed') desc, coalesce(p.display_name, p.canonical_name)), '[]'::jsonb)
       from pipeline.provider_policy_proposals x join catalogue.providers p on p.id = x.provider_id left join ref.countries k on k.id = p.country_id
      where x.kind = p_kind and x.status in ('proposed', 'approved', 'rejected'))) into v;
  return v;
end $$;


ALTER FUNCTION "public"."admin_provider_policies_read"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_policy_decide"("p_id" "uuid", "p_action" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare x pipeline.provider_policy_proposals%rowtype; v jsonb := '{}'::jsonb; v_ag int := 0; v_df int := 0; v_sum jsonb;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if p_action not in ('approve', 'reject') then raise exception 'action must be approve or reject'; end if;
  select * into x from pipeline.provider_policy_proposals where id = p_id for update;
  if x.id is null then raise exception 'proposal not found'; end if;
  if x.status <> 'proposed' then raise exception 'already decided or not a proposal (%)', x.status; end if;
  if p_action = 'approve' and x.kind = 'english_policy' then
    v_sum := security.provider_policy_refresh_one_v1(p_id);
    v_ag := coalesce((v_sum->>'agrees')::int, 0); v_df := coalesce((v_sum->>'differs')::int, 0);
    if v_ag + v_df >= 10 and v_df > v_ag then
      raise exception 'This default does not match most course pages (% agree, % differ), so it cannot be approved', v_ag, v_df;
    end if;
  end if;
  update pipeline.provider_policy_proposals set status = case when p_action = 'approve' then 'approved' else 'rejected' end,
         decided_by = auth.uid(), decided_at = now(), decision_note = left(p_note, 500), updated_at = now() where id = p_id;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('policies', p_action, x.kind || ': ' || x.url, jsonb_build_object('decision', 'Decision 227', 'proposal_id', x.id, 'provider_id', x.provider_id), auth.uid());
  -- one approved document per university and kind: its other waiting documents are closed
  if p_action = 'approve' then
    update pipeline.provider_policy_proposals
       set status = 'superseded', decided_at = now(), updated_at = now(),
           decision_note = 'Closed: another document for this university was approved (' || x.url || ')'
     where provider_id = x.provider_id and kind = x.kind and status = 'proposed' and id <> x.id
       -- CF-247 6 Nov 2026 (English requirements): a course-group reading and a level-default reading are decided separately; approving one never closes the other
       and (jsonb_array_length(case when jsonb_typeof(proposal->'groups') = 'array' then proposal->'groups' else '[]'::jsonb end) > 0) = (jsonb_array_length(case when jsonb_typeof(x.proposal->'groups') = 'array' then x.proposal->'groups' else '[]'::jsonb end) > 0);
  end if;
  if p_action = 'approve' and x.kind = 'english_policy' then v := jsonb_build_object('to_fill', coalesce((v_sum->>'write')::int, 0)); end if;
  if p_action = 'approve' and x.kind = 'intake_calendar' then
    v := jsonb_build_object('to_answer', (select count(*) from security.semester_intake_plan_v1(x.provider_id) r where r.outcome = 'answer'));
  end if;
  return jsonb_build_object('status', case when p_action = 'approve' then 'approved' else 'rejected' end) || v;
end $$;


ALTER FUNCTION "public"."admin_provider_policy_decide"("p_id" "uuid", "p_action" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_policy_decide_bulk"("p_ids" "uuid"[], "p_action" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id uuid; v_ok int := 0; v_fill int := 0; v_skip jsonb := '[]'::jsonb; r jsonb; v_status text;
begin
  if auth.uid() is null or security.current_role_rank() < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if p_action not in ('approve', 'reject') then raise exception 'action must be approve or reject'; end if;
  if coalesce(cardinality(p_ids), 0) = 0 or cardinality(p_ids) > 200 then raise exception 'choose between 1 and 200 documents'; end if;
  foreach v_id in array p_ids loop
    -- a document closed earlier in this same action (another of its university was approved) is skipped
    select status into v_status from pipeline.provider_policy_proposals where id = v_id;
    if v_status is distinct from 'proposed' then
      v_skip := v_skip || jsonb_build_object('id', v_id, 'reason', case when v_status = 'superseded' then 'another document for this university was approved' else 'already decided' end);
      continue;
    end if;
    begin
      r := public.admin_provider_policy_decide(v_id, p_action, p_note);
      v_ok := v_ok + 1; v_fill := v_fill + coalesce((r->>'to_fill')::int, 0);
    exception when others then
      v_skip := v_skip || jsonb_build_object('id', v_id, 'reason', sqlerrm);
    end;
  end loop;
  return jsonb_build_object('done', v_ok, 'to_fill', v_fill, 'skipped', v_skip);
end $$;


ALTER FUNCTION "public"."admin_provider_policy_decide_bulk"("p_ids" "uuid"[], "p_action" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_publish"("p_provider_id" "uuid", "p_published" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_before text; v_after text := case when p_published then 'published' else 'unpublished' end;
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 5 then raise exception 'PIM Operator role or above required' using errcode = '42501'; end if;
  select publication_status into v_before from catalogue.providers where id = p_provider_id;
  if not found then raise exception 'provider not found'; end if;
  if p_published and exists (select 1 from catalogue.providers where id = p_provider_id and lifecycle_status <> 'active') then
    raise exception 'an archived provider cannot be published: restore it first';
  end if;
  if v_before is distinct from v_after then
    perform set_config('cf.manual_edit', 'on', true);
    update catalogue.providers set publication_status = v_after, updated_at = now() where id = p_provider_id;
    insert into pipeline.manual_edit_log(entity, entity_id, field, action, before, after, reason, actor)
    values ('provider', p_provider_id, 'publication_status', case when p_published then 'publish' else 'unpublish' end, to_jsonb(v_before), to_jsonb(v_after), null, auth.uid());
    insert into search.refresh_requests(requested_by) values (format('provider %s %s', left(p_provider_id::text, 8), v_after));
  end if;
  return jsonb_build_object('provider_id', p_provider_id, 'publication_status', v_after);
end $$;


