CREATE OR REPLACE FUNCTION "public"."admin_provider_sch_search"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_pid uuid; v_on boolean; v_reason text; v_site text; v_own text;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 1 then raise exception 'assigned StudySearch role required' using errcode = '42501'; end if;
  if p_action = 'states' then
    return coalesce((select jsonb_object_agg(p.id::text, jsonb_build_object(
             'on', coalesce(f.enabled, true), 'auto', coalesce(f.auto, false), 'reason', f.reason, 'set_at', f.set_at,
             'directory_only', security.provider_directory_only_v1(p.id), 'own_site', security.provider_own_site_v1(p.id),
             'can_manage', v_rank >= 4))
      from catalogue.providers p left join pipeline.provider_scholarship_search f on f.provider_id = p.id
     where p.id in (select (jsonb_array_elements_text(coalesce(p_args->'provider_ids', '[]'::jsonb)))::uuid)), '{}'::jsonb);
  elsif p_action = 'off_count' then
    return jsonb_build_object('off', (select count(*) from pipeline.provider_scholarship_search where not enabled),
                              'auto', (select count(*) from pipeline.provider_scholarship_search where not enabled and auto));
  elsif p_action = 'set' then
    if v_rank < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
    v_pid := nullif(p_args->>'provider_id', '')::uuid; v_on := (p_args->>'on')::boolean; v_reason := btrim(coalesce(p_args->>'reason', ''));
    v_site := nullif(btrim(coalesce(p_args->>'website', '')), '');
    if v_pid is null or v_on is null then raise exception 'provider and on/off are required'; end if;
    if length(v_reason) < 4 then raise exception 'give a reason (it is kept in the log)'; end if;
    if v_on then
      if v_site is not null and security.third_party_host_v1(v_site) then raise exception 'that address is a directory site; enter the provider''s own website'; end if;
      v_own := security.provider_own_site_v1(v_pid);
      if v_site is not null and v_site is distinct from v_own then
        perform public.admin_provider_website_set(v_pid, v_site);  -- saved as entered by a person (Curator and above), logged
        v_own := v_site;
      end if;
      if v_own is null then raise exception 'enter the provider''s own website to switch scholarship search on'; end if;
      -- a fresh search from the provider's own website (the 30-course rule and the credit caps still apply)
      insert into pipeline.scholarship_discovery_providers(provider_id, website, priority, reason, status)
      values (v_pid, v_own, 4, 'enabled_by_person', 'pending')
      on conflict (provider_id) do update set website = excluded.website, site_origin = null, status = 'pending', attempts = 0,
             leased_until = null, last_error = null, reason = 'enabled_by_person', updated_at = now();
    end if;
    insert into pipeline.provider_scholarship_search(provider_id, enabled, auto, reason, set_by, set_at)
    values (v_pid, v_on, false, v_reason, auth.uid(), now())
    on conflict (provider_id) do update set enabled = excluded.enabled, auto = false, reason = excluded.reason, set_by = excluded.set_by, set_at = now();
    insert into pipeline.provider_scholarship_search_log(provider_id, enabled, auto, reason, website, set_by) values (v_pid, v_on, false, v_reason, v_own, auth.uid());
    return public.admin_provider_sch_search('states', jsonb_build_object('provider_ids', jsonb_build_array(v_pid)));
  end if;
  raise exception 'unknown action %', p_action using errcode = '22023';
end $$;


ALTER FUNCTION "public"."admin_provider_sch_search"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_set_type"("p_provider_id" "uuid", "p_type_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_before uuid; v_type uuid; v_code text := nullif(btrim(coalesce(p_type_code, '')), '');
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 5 then raise exception 'PIM Admin role or above required' using errcode = '42501'; end if;
  select provider_type_id into v_before from catalogue.providers where id = p_provider_id;
  if not found then raise exception 'provider not found'; end if;
  if v_code is null or v_code = 'auto' then
    delete from pipeline.manual_locks where entity = 'provider' and entity_id = p_provider_id and field = 'provider_type_id';
    insert into pipeline.manual_edit_log(entity, entity_id, field, action, before, after, reason, actor)
    values ('provider', p_provider_id, 'provider_type_id', 'unlock', to_jsonb(v_before), null, 'type from the register rules', auth.uid());
    perform security.provider_type_classify_v1();
  else
    select id into v_type from ref.provider_types where code = v_code and status = 'active';
    if v_type is null then raise exception 'unknown institution type %', v_code; end if;
    perform set_config('cf.manual_edit', 'on', true);
    update catalogue.providers set provider_type_id = v_type, provider_type_basis = 'Set by a person', provider_type_set_at = now(), updated_at = now() where id = p_provider_id;
    insert into pipeline.manual_locks(entity, entity_id, field, mode, set_by) values ('provider', p_provider_id, 'provider_type_id', 'value', auth.uid())
      on conflict (entity, entity_id, field) do update set set_by = excluded.set_by, set_at = now();
    insert into pipeline.manual_edit_log(entity, entity_id, field, action, before, after, reason, actor)
    values ('provider', p_provider_id, 'provider_type_id', 'set', to_jsonb(v_before), to_jsonb(v_type), null, auth.uid());
  end if;
  return (select jsonb_build_object('provider_id', p.id, 'provider_type_code', t.code, 'provider_type_name', t.name, 'provider_type_basis', p.provider_type_basis,
            'provider_type_locked', exists (select 1 from pipeline.manual_locks l where l.entity = 'provider' and l.entity_id = p.id and l.field = 'provider_type_id'))
          from catalogue.providers p left join ref.provider_types t on t.id = p.provider_type_id where p.id = p_provider_id);
end $$;


ALTER FUNCTION "public"."admin_provider_set_type"("p_provider_id" "uuid", "p_type_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_type_rules"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id uuid; v_before jsonb;
begin
  if auth.uid() is null or coalesce(security.current_role_rank(), 0) < 1 then raise exception 'assigned StudySearch role required' using errcode = '42501'; end if;
  if p_action = 'list' then
    return jsonb_build_object(
      'rules', coalesce((select jsonb_agg(to_jsonb(r) order by r.position) from pipeline.provider_type_rules r), '[]'::jsonb),
      'types', coalesce((select jsonb_agg(jsonb_build_object('code', t.code, 'name', t.name, 'description', t.description) order by t.name) from ref.provider_types t where t.status = 'active'), '[]'::jsonb),
      'counts', coalesce((select jsonb_object_agg(coalesce(t.code, 'none'), n) from (select pr.provider_type_id, count(*) n from catalogue.providers pr group by 1) z left join ref.provider_types t on t.id = z.provider_type_id), '{}'::jsonb),
      'can_edit', coalesce(security.current_role_rank(), 0) >= 6);
  elsif p_action = 'save' then
    if coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
    v_id := (p_args->>'id')::uuid;
    select to_jsonb(r) into v_before from pipeline.provider_type_rules r where r.id = v_id;
    if v_before is null then raise exception 'rule not found'; end if;
    if p_args ? 'result_type' and not exists (select 1 from ref.provider_types t where t.code = p_args->>'result_type' and t.status = 'active') then raise exception 'unknown institution type'; end if;
    update pipeline.provider_type_rules set
      result_type = coalesce(p_args->>'result_type', result_type),
      enabled = coalesce((p_args->>'enabled')::boolean, enabled),
      position = coalesce((p_args->>'position')::int, position),
      updated_at = now(), updated_by = auth.uid()
    where id = v_id;
    insert into pipeline.manual_edit_log(entity, entity_id, field, action, before, after, reason, actor)
    values ('provider', v_id, 'provider_type_rule', 'rule_change', v_before, (select to_jsonb(r) from pipeline.provider_type_rules r where r.id = v_id), nullif(p_args->>'reason', ''), auth.uid());
    return jsonb_build_object('saved', true, 'classify', security.provider_type_classify_v1());
  elsif p_action = 'run' then
    if coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
    return security.provider_type_classify_v1();
  end if;
  raise exception 'unknown action %', p_action;
end $$;


ALTER FUNCTION "public"."admin_provider_type_rules"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_website_check"("p_action" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := coalesce(security.current_role_rank(), 0); v_pid uuid := nullif(p_args->>'provider_id', '')::uuid; v_url text := btrim(coalesce(p_args->>'url', ''));
        v_extra text := nullif(btrim(coalesce(p_args->>'extra_site', '')), ''); v_reason text := nullif(btrim(coalesce(p_args->>'reason', '')), ''); v_site text; v_id uuid;
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  select nullif(btrim(p.website), '') into v_site from catalogue.providers p where p.id = v_pid;
  if not found then raise exception 'choose a provider'; end if;
  if p_action = 'list' then
    return jsonb_build_object('website', v_site, 'sites', to_jsonb(security.provider_website_list_v1(v_site)),
      'can_check', true, 'can_change', v_rank >= 6,
      'checks', coalesce((select jsonb_agg(to_jsonb(x) order by x.requested_at desc) from (
         select c.id, c.url, c.action, c.extra_site, c.reason, c.requested_at, c.state, c.verdict, c.why, c.checked_at, c.applied, c.apply_note,
                c.result - 'worker' as result
           from pipeline.provider_website_checks c where c.provider_id = v_pid order by c.requested_at desc
          limit 5) x), '[]'::jsonb));  -- fixed: the five latest checks are shown
  end if;
  if p_action not in ('check', 'change') then raise exception 'unknown action %', p_action; end if;
  if p_action = 'change' and v_rank < 6 then raise exception 'Platform Admin required to change a website' using errcode = '42501'; end if;
  if v_url = '' and p_action = 'check' then v_url := (security.provider_website_list_v1(v_site))[1]; end if;
  if v_url !~* '^https?://' and v_url ~* '^[a-z0-9-]+(\.[a-z0-9-]+)+' then v_url := 'https://' || v_url; end if;
  if coalesce(v_url, '') !~* '^https?://[^\s/,;]+\.[^\s,;]+$' then raise exception 'enter one full web address starting with https://'; end if;
  if v_extra is not null and v_extra !~* '^https?://' then v_extra := 'https://' || v_extra; end if;
  if v_extra is not null and v_extra !~* '^https?://[^\s/,;]+\.[^\s,;]+$' then raise exception 'the other site must be one web address'; end if;
  if p_action = 'change' and length(coalesce(v_reason, '')) < 4 then raise exception 'a reason is required'; end if;
  if security.third_party_host_v1(v_url) then raise exception 'that is a third-party site (a course directory or similar), not the provider''s own website'; end if;
  if exists (select 1 from pipeline.provider_website_checks c where c.provider_id = v_pid and c.state <> 'done') then raise exception 'a check for this provider is already running; wait for its result'; end if;
  insert into pipeline.provider_website_checks(provider_id, url, action, extra_site, reason, requested_by)
  values (v_pid, v_url, p_action, case when p_action = 'change' then v_extra end, v_reason, auth.uid()) returning id into v_id;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('provider', 'website_' || p_action || '_asked', v_pid::text, jsonb_build_object('url', v_url, 'extra_site', v_extra, 'reason', v_reason, 'check_id', v_id, 'change', 'CF-247 bug 18/10-01'), auth.uid());
  perform security.provider_website_check_kick_v1();
  return jsonb_build_object('id', v_id, 'url', v_url, 'action', p_action, 'state', 'queued');
end $_$;


ALTER FUNCTION "public"."admin_provider_website_check"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_website_set"("p_provider_id" "uuid", "p_url" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_url text := btrim(coalesce(p_url, '')); v_dom text;
begin
  if auth.uid() is null or security.current_role_rank() < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  if v_url !~* '^https?://[^\s/]+\.[^\s]+$' then raise exception 'enter a full web address starting with https://'; end if;
  -- recorded as entered by hand (locked, logged) through the provider editor
  perform public.admin_provider_edit(p_provider_id, 'set_core', jsonb_build_object('field', 'website', 'value', v_url));
  perform public.admin_provider_edit(p_provider_id, 'set_course_finder', jsonb_build_object('url', v_url));
  update pipeline.coverage_provider_discovery set site_source = 'manual', site_searched_at = now(), updated_at = now() where provider_id = p_provider_id;
  v_dom := lower(regexp_replace(substring(v_url from '^(?:https?://)?([^/:?#]+)'), '^www\.', ''));
  if v_dom ~ '^[a-z0-9.-]+\.[a-z]{2,}$' then
    insert into pipeline.course_link_recipes(provider_id, search_domain, patterns, active, notes, updated_at)
    select p_provider_id, v_dom,
           jsonb_build_array(jsonb_build_object(
             're', '(?i)^https?://([a-z0-9-]+\.)*' || regexp_replace(v_dom, '\.', '\\.', 'g')
                   || '/(?!.*\.(pdf|docx?|xlsx?|pptx?|jpe?g|png|gif|svg|zip)$)(?!(.*/)?(news|events?|blog|staff|people|media|search|tags?|category)(/|$)).+$',
             'rep', '\&')),
           true, 'Generic recipe: any page on the provider''s own site, from a website entered by a person; used only when the reader proves the page is the course''s (Decision 222, 2 Oct 2026)', now()
     where not exists (select 1 from pipeline.course_link_recipes x where x.provider_id = p_provider_id);
    insert into pipeline.course_link_search(course_id, provider_id, stage, state, queued_at)
    select c.id, c.provider_id, case when c.course_code ~ '^[0-9]{6}[0-9A-Z]$' then 'cricos' else 'title' end, 'queued', now()
      from catalogue.courses c
     where c.provider_id = p_provider_id and c.lifecycle_status = 'active'
       and exists (select 1 from pipeline.course_link_recipes x where x.provider_id = p_provider_id and x.active)
       and not exists (select 1 from pipeline.coverage_course_pages g where g.course_id = c.id)
    on conflict (course_id) do nothing;
  end if;
  return public.admin_provider_websites('{}'::jsonb);
end $_$;


ALTER FUNCTION "public"."admin_provider_website_set"("p_provider_id" "uuid", "p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_provider_websites"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_country text := upper(nullif(p_args->>'country', '')); v_lim int := least(greatest(coalesce((p_args->>'limit')::int, 50), 1), 200);
begin
  if auth.uid() is null or security.current_role_rank() < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  return (with q as (
    select p.id, coalesce(p.display_name, p.canonical_name) name, k.iso_alpha2::text country, d.site_searched_at, d.site_evidence,
           (select count(*) from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active') courses,
           (select min(upper(r.registration_code)) from catalogue.provider_registrations r where r.provider_id = p.id and lower(r.registration_scheme) = 'cricos') cricos,
           (select min(upper(r.registration_code)) from catalogue.provider_registrations r where r.provider_id = p.id and lower(r.registration_scheme) = 'ircc_dli') dli
      from pipeline.coverage_provider_discovery d join catalogue.providers p on p.id = d.provider_id join ref.countries k on k.id = p.country_id
     where d.status = 'no_website' and d.site_searched_at is not null and (v_country is null or k.iso_alpha2 = v_country))
    select jsonb_build_object('total', (select count(*) from q), 'can_edit', true,
      'countries', coalesce((select jsonb_object_agg(country, n) from (select country, count(*) n from q group by 1) c), '{}'::jsonb),
      'items', coalesce((select jsonb_agg(jsonb_build_object('provider_id', id, 'name', name, 'country', country, 'courses', courses, 'cricos', cricos, 'dli', dli,
                 'searched_at', site_searched_at, 'query', site_evidence->>'query', 'note', site_evidence->>'note',
                 'tried', coalesce((select jsonb_agg(t->>'page') from jsonb_array_elements(coalesce(site_evidence->'tried', '[]'::jsonb)) t where t->>'page' is not null), '[]'::jsonb))
               order by courses desc, name) from (select * from q order by courses desc, name limit v_lim) z), '[]'::jsonb)));
end $$;


ALTER FUNCTION "public"."admin_provider_websites"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_queue_watch"("p_action" "text" DEFAULT 'list'::"text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_reason text := btrim(coalesce(p_args->>'reason', '')); v jsonb;
begin
  if auth.uid() is null or coalesce(v_rank, 0) < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  if p_action = 'list' then
    return jsonb_build_object(
      'queues', (select coalesce(jsonb_agg(to_jsonb(s) || jsonb_build_object('label', w.label, 'area', w.area, 'purpose', w.purpose, 'jobs', w.jobnames, 'tools', w.tools,
                         'nothing_left_is', w.exhausted_label, 'fix', w.retry_label, 'fix_at', w.fix_at, 'why_idle', security.lane_why_idle_v1(w.key)) order by w.sort), '[]'::jsonb)
                   from pipeline.queue_watch w left join pipeline.queue_watch_state s on s.key = w.key where w.enabled),
      'events', (select coalesce(jsonb_agg(to_jsonb(e) order by e.at desc), '[]'::jsonb) from (select * from pipeline.queue_watch_events order by at desc limit 50) e),  -- fixed: screen list length
      'fixes', (select coalesce(jsonb_agg(to_jsonb(f) order by f.at desc), '[]'::jsonb) from (select * from pipeline.queue_watch_fixes order by at desc limit 30) f),  -- fixed: screen list length
      'alerts', (select coalesce(jsonb_agg(to_jsonb(a) order by a.raised_at desc), '[]'::jsonb) from (select * from pipeline.queue_watch_alerts order by raised_at desc limit 30) a),  -- fixed: screen list length
      'settings', jsonb_build_object('window_minutes', security.pipeline_num_v1('queue_watch.window_minutes', 60), 'stuck_minutes', security.pipeline_num_v1('queue_watch.stuck_minutes', 120)),
      'can_run', v_rank >= 4);
  elsif p_action = 'report' then
    return security.queue_watch_report_v1(null);
  elsif p_action = 'run' then
    if v_rank < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
    if length(v_reason) < 4 then raise exception 'give a reason (kept in the log)'; end if;
    v := security.queue_watch_run_v1(true);
    insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('queue_watch', 'run', null, jsonb_build_object('reason', v_reason, 'result', v), auth.uid());
    return v;
  end if;
  raise exception 'unknown action';
end $$;


ALTER FUNCTION "public"."admin_queue_watch"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_ranking_link"("p_publisher_institution_id" "uuid", "p_action" "text", "p_provider_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := security.current_role_rank(); v_cid uuid; v_n int;
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'Curator role required' using errcode = '42501'; end if;
  if p_action = 'run_rules' then
    if v_rank < 4 then raise exception 'Pipeline Operator role required' using errcode = '42501'; end if;
    return security.ranking_link_auto_v1();
  end if;
  if p_action not in ('link', 'reject') or p_provider_id is null then raise exception 'action must be link or reject, with a provider'; end if;
  select security.ranking_country_id(country_text) into v_cid from ranking.publisher_institutions where id = p_publisher_institution_id;
  if not found then raise exception 'publisher institution not found'; end if;
  if p_action = 'reject' then
    update ranking.provider_mappings set status = 'rejected', reviewed_by = auth.uid(), reviewed_at = now(), note = coalesce(left(p_note, 300), note)
     where publisher_institution_id = p_publisher_institution_id and provider_id = p_provider_id and status = 'candidate';
    return jsonb_build_object('rejected', true);
  end if;
  if not exists (select 1 from catalogue.providers p where p.id = p_provider_id and p.lifecycle_status = 'active' and (v_cid is null or p.country_id = v_cid)) then
    raise exception 'the provider must be active and in the same country as the ranked university';
  end if;
  v_n := security.ranking_link_apply_v1(p_publisher_institution_id, p_provider_id, 'manual_person', left(coalesce(p_note, 'Linked by a person'), 300), auth.uid());
  return jsonb_build_object('linked', true, 'observations_linked', v_n);
end $$;


ALTER FUNCTION "public"."admin_ranking_link"("p_publisher_institution_id" "uuid", "p_action" "text", "p_provider_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_read"("p_operation" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'security'
    AS $$
declare v_result jsonb;v_id uuid;
begin
 if p_operation='platform_health' then return security.admin_platform_health_v1(p_args); end if;
 if p_operation='live_activity' then return security.admin_live_activity_v1(); end if;
 if p_operation in ('course_coverage','course_coverage_courses','course_coverage_providers') then return security.admin_course_coverage_read(p_operation,p_args); end if;
 if p_operation='scholarship_ai' then return security.scholarship_ai_control_read_impl(coalesce(nullif(p_args->>'country_code',''),'AU')); end if;
 if p_operation='layer3_queue_status' then return security.layer3_queue_status_read_v1(); end if;
 if p_operation='admin_filter_option_page' then return security.admin_filter_option_page(p_args); end if;
 if p_operation='dashboard' then return security.admin_dashboard_maturity(); end if;
 if p_operation='layer_status_summary' then return security.admin_layer_status_summary(); end if;
 if p_operation='catalogue_filter_page' then return security.admin_catalogue_filter_page(p_args); end if;
 if p_operation in ('provider_filters','course_filters') then return security.admin_catalogue_filter_options(p_operation,p_args); end if;
 if p_operation='evidence_page' then return security.admin_evidence_page(p_args); end if;
 if p_operation in ('evidence_filters','evidence_detail','evidence_observations','evidence_entities') then return security.admin_evidence_read(p_operation,p_args); end if;
 if p_operation='courses_page' then return security.admin_course_page_fast(p_args); end if;
 if p_operation='campuses_page' then return security.admin_campus_page_fast(p_args); end if;
 if p_operation in ('providers_page','scholarships_page') then return security.admin_catalogue_page(p_operation,p_args); end if;
 if p_operation in ('qilt_outcomes','qilt_filters','prisms_student_flow','prisms_filters') then return security.admin_insights_read(p_operation,p_args); end if;
 if p_operation='ranking_imports' then return security.admin_ranking_imports_read(p_args); end if;
 if p_operation in ('ranking_summary','ranking_filters','ranking_observations') then return security.admin_ranking_read(p_operation,p_args); end if;
 if p_operation in ('ranking_filter_options','ranking_link_candidates','ranking_provider_search','provider_ranking_history') then return security.admin_ranking_links_read(p_operation,p_args); end if;
 if p_operation in ('provider_asset_summary','provider_asset_coverage','provider_asset_context') then return security.admin_provider_asset_read(p_operation,p_args); end if;
 if p_operation in ('provider_contacts_page','provider_contact_detail','provider_contact_imports','provider_contact_import_detail') then return security.admin_provider_contact_read(p_operation,p_args); end if;
 if p_operation='contextual_compare' then return security.admin_contextual_compare(p_args); end if;
 if p_operation='reviews_page' then return security.admin_operational_page(p_operation,p_args); end if;
 if p_operation='layer2_dispatcher_tuning' then return security.admin_layer2_dispatcher_tuning_read_v1(p_args); end if;
 if p_operation='enrichment_operations' then return security.admin_enrichment_operations_read(p_args); end if;
 if p_operation='jobs_runtime' then return security.admin_jobs_runtime_read_v1(p_args); end if;
 if p_operation in ('reviews','jobs','sources') then return security.admin_operations_read(p_operation,p_args); end if;
 if p_operation='layer1_operations' then return security.admin_layer1_operations_read(p_args); end if;
 if p_operation='layer2_ops_alerts' then return security.layer2_operational_alerts_read(); end if;
 if p_operation='layer2_parent_runs' then return security.admin_layer2_parent_runs(coalesce(nullif(p_args->>'limit','')::integer,10)); end if;
 if p_operation='layer2_ops_overview' then return security.admin_layer2_ops_read('layer2_ops_overview',p_args); end if;
 if p_operation='layer2_ops_run_detail' then return security.admin_layer2_ops_read(p_operation,p_args); end if;
 if p_operation in ('layer2_acquisition_providers','layer2_provider_attempts') then return security.admin_layer2_provider_read(p_operation,p_args); end if;
 if p_operation='attributes' then return security.admin_pim_governance_read(p_args); end if;
 if p_operation in ('pipeline_overview','pipeline_jobs_page','pipeline_job_detail','pipeline_sources_page','pipeline_filters') then v_result:=security.admin_pipeline_ops_read(p_operation,p_args);return security.admin_pipeline_ops_sanitise_result(p_operation,v_result);end if;
 if p_operation in ('data_quality_overview','data_quality_exceptions','data_quality_quarantine') then return security.admin_data_quality_read(p_operation,p_args); end if;
 if p_operation in ('platform_readiness','platform_capacity','platform_environment_gates','platform_uat_catalogue','platform_workloads','platform_retention','platform_active_blocks') then return security.admin_platform_maturity_read(p_operation,p_args); end if;
 if p_operation='publication_overview' then return security.admin_publication_overview(); end if;
 if p_operation='provider_insights' then v_id:=nullif(p_args->>'id','')::uuid;return jsonb_build_object('contextual_insights',security.admin_contextual_insights_v2('provider',v_id));end if;
 if p_operation='provider_detail' then v_id:=nullif(p_args->>'id','')::uuid;return security.admin_provider_detail(v_id)-'courses'-'courses_page'-'evidence'-'evidence_page'-'sources'-'history';end if;
 if p_operation='campus_detail' then v_id:=nullif(p_args->>'id','')::uuid;return security.admin_campus_detail(v_id);end if;
 if p_operation='course_insights' then v_id:=nullif(p_args->>'id','')::uuid;return jsonb_build_object('contextual_insights',security.admin_contextual_insights_v2('course',v_id));end if;
 v_result:=security.admin_read_impl(p_operation,p_args);
 if p_operation='course_detail' then v_id:=nullif(p_args->>'id','')::uuid;return v_result||jsonb_build_object('fee_summary',security.admin_course_fee_summary(v_id))||jsonb_build_object('entry_summary',security.admin_course_entry_summary(v_id))||jsonb_build_object('display_code',security.course_display_code_v1(v_id))||jsonb_build_object('course_scholarships',security.admin_course_scholarships(v_id));end if;
 if p_operation='scholarship_detail' then v_id:=nullif(p_args->>'id','')::uuid;return v_result||jsonb_build_object('semantic_summary',security.admin_scholarship_semantic_summary(v_id));end if;
 return v_result;
end $$;


