CREATE OR REPLACE FUNCTION "public"."layer3_fallback_profile_service"("p_profile_id" "uuid", "p_task_class" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_f pipeline.layer3_model_profiles%rowtype;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;
  select f.* into v_f
  from pipeline.layer3_model_profiles p
  join pipeline.layer3_model_profiles f on f.id=p.fallback_profile_id
  where p.id=p_profile_id
    and f.enabled and not f.paused
    and p_task_class=any(f.allowed_task_classes)
    and coalesce((f.quality_benchmark->>'pass')::boolean,false) is true;
  if not found then return null; end if;
  return jsonb_build_object(
    'id',v_f.id,'aggregator_provider',v_f.aggregator_provider,'base_url',v_f.base_url,
    'model_identifier',v_f.model_identifier,'secret_env_key',v_f.secret_env_key,
    'prompt_profile_version',v_f.prompt_profile_version,'prompt_system',v_f.prompt_system,
    'validators',v_f.deterministic_validators,'max_output_tokens',v_f.max_output_tokens,
    'retry_ceiling',v_f.retry_ceiling,'timeout_ms',v_f.timeout_ms,'cost_ceiling_usd',v_f.cost_ceiling_usd
  );
end $$;


ALTER FUNCTION "public"."layer3_fallback_profile_service"("p_profile_id" "uuid", "p_task_class" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."layer3_holdout_cases_service"("p_gold_set" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
begin
  perform public.layer3_routing_service_guard();
  return jsonb_build_object('gold_set',p_gold_set,
    'task_class',(select s.task_class from pipeline.layer3_holdout_sets s where s.gold_set=p_gold_set),
    'frozen_digest',(select s.digest from pipeline.layer3_holdout_sets s where s.gold_set=p_gold_set),
    'contract_fingerprint',(select s.contract_fingerprint from pipeline.layer3_holdout_sets s where s.gold_set=p_gold_set),
    'current_digest',pipeline.layer3_holdout_digest(p_gold_set),
    'cases',coalesce((select jsonb_agg(jsonb_build_object('case_id',c.id,'case_key',c.case_key,'course_id',c.course_id,'evidence_id',c.evidence_id,
            'storage_path',e.storage_path,'mime_type',e.mime_type,'source_url',e.source_url,'text_sha256',c.text_sha256,'gold',c.gold,
            'evidence_excerpt',c.evidence_excerpt,'candidate_context',c.candidate_context) order by c.case_key)
      from pipeline.layer3_holdout_cases c join pipeline.evidence_artifacts e on e.id=c.evidence_id where c.gold_set=p_gold_set),'[]'::jsonb));
end $$;


