CREATE OR REPLACE FUNCTION "public"."svc_adapter_apply_continue"("p_provider_id" "uuid", "p_after" "uuid") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if p_after is null or not exists (select 1 from pipeline.uni_adapters a where a.provider_id = p_provider_id and a.enabled) then return null; end if;
  return pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'adapter_apply', 'provider_id', p_provider_id, 'after', p_after));
end $$;


ALTER FUNCTION "public"."svc_adapter_apply_continue"("p_provider_id" "uuid", "p_after" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_adapter_apply_next"("p_provider_id" "uuid", "p_after" "uuid", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if not exists (select 1 from pipeline.uni_adapters a where a.provider_id = p_provider_id and a.enabled) then return jsonb_build_object('adapter', null, 'pages', '[]'::jsonb); end if;
  return jsonb_build_object('adapter', security.uni_adapter_json(p_provider_id), 'pages', coalesce((select jsonb_agg(x) from (
    select jsonb_build_object('course_id', pg.course_id, 'url', pg.url, 'title', coalesce(c.display_title, c.canonical_title), 'code', c.course_code, 'country', k.iso_alpha2::text,
                              'status', pg.status, 'read_status', pg.read_status, 'identity_basis', pg.identity_basis, 'storage_path', e.storage_path) x
    from pipeline.coverage_course_pages pg join catalogue.courses c on c.id = pg.course_id join catalogue.providers p on p.id = pg.provider_id join ref.countries k on k.id = p.country_id
    join pipeline.evidence_artifacts e on e.id = pg.evidence_id
    where pg.provider_id = p_provider_id and pg.read_status in ('identity_mismatch', 'read') and e.storage_path is not null and c.lifecycle_status in ('active', 'inactive')
      and (p_after is null or pg.course_id > p_after)
    order by pg.course_id limit greatest(1, least(coalesce(p_limit, 100), 300))) q), '[]'::jsonb));
end $$;


ALTER FUNCTION "public"."svc_adapter_apply_next"("p_provider_id" "uuid", "p_after" "uuid", "p_limit" integer) OWNER TO "postgres";


