CREATE OR REPLACE FUNCTION "public"."svc_aer_source_upload_record"("p_attachment" bigint, "p_path" "text", "p_sha" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare a pipeline.aer_source_attachments%rowtype; v_res jsonb; v_q int;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into a from pipeline.aer_source_attachments where id = p_attachment for update;
  if a.id is null or a.how <> 'pdf_upload' then raise exception 'upload attachment not found'; end if;
  if a.completed_at is not null then return jsonb_build_object('ok', true, 'already', true); end if;
  if a.content_hash is distinct from lower(p_sha) or p_path !~ ('/entry-matrix/' || a.provider_id || '/' || a.source_id || '/' || a.content_hash || '\.pdf\.gz$') then
    raise exception 'the stored file does not match the upload that was checked'; end if;
  v_res := public.svc_entry_matrix_fetch_record(a.source_id, 'read', null, null, p_path, a.content_hash, 'application/pdf', null);
  update pipeline.aer_source_attachments set storage_path = p_path, completed_at = now() where id = a.id;
  v_q := security.entry_matrix_enqueue_v1();
  return jsonb_build_object('ok', true, 'source_id', a.source_id, 'evidence_id', v_res->>'evidence_id', 'reads_queued', v_q,
                            'outcome', 'Stored as the source''s copy; the next entry-matrix-read run reads it and its rows go to Layer 4 for a person.');
end $_$;


ALTER FUNCTION "public"."svc_aer_source_upload_record"("p_attachment" bigint, "p_path" "text", "p_sha" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_aer_source_upload_record"("p_attachment" bigint, "p_path" "text", "p_sha" "text") IS 'CF-247 F-AER.04 D3: records a PDF a person uploaded (edge function aer-source-upload) as the entry source''s stored copy and queues its one read. Service role only.';



CREATE OR REPLACE FUNCTION "public"."svc_aer_v2_shadow_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare h jsonb; v_lim int := greatest(1, least(coalesce(p_limit, 1), 40));  -- fixed: the upper bound of the setting batch.aer_v2_shadow
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  h := security.aer_v2_shadow_hold_v1();
  if h->>'held' is not null then return jsonb_build_object('items', '[]'::jsonb, 'held', h->>'held', 'budget', h->'budget'); end if;
  return jsonb_build_object(
    'version', h->'version', 'budget', h->'budget',
    'countries', (select coalesce(jsonb_agg(k.iso_alpha2 order by k.iso_alpha2), '[]'::jsonb) from ref.countries k where k.iso_alpha2 is not null),
    'qualifications', (select coalesce(jsonb_agg(jsonb_build_object('code', q.code, 'name', q.name) order by q.code), '[]'::jsonb) from ref.aer_qualifications q),
    'items', (select coalesce(jsonb_agg(to_jsonb(x) order by x.sample_rank), '[]'::jsonb) from security.aer_v2_shadow_candidates_v1(h->'version'->>'version', v_lim) x));
end $$;


ALTER FUNCTION "public"."svc_aer_v2_shadow_next"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_aer_v2_shadow_next"("p_limit" integer) IS 'AER v2 step 1 (worker mode aer_v2_shadow): the trial prompt version, reference codes and the next stored course pages of the shadow sample; nothing while held';



CREATE OR REPLACE FUNCTION "public"."svc_aer_v2_shadow_record"("p_course_id" "uuid", "p_prompt_version" "text", "p_model" "text", "p_evidence_id" "uuid", "p_content_hash" "text", "p_records" "jsonb", "p_checks" "jsonb", "p_seen_not_mapped" "jsonb", "p_cost_usd" numeric, "p_error" "text", "p_worker" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_model text; v_prov uuid; v_pass int; v_fail int; v_id bigint;
        v_checks jsonb := case when jsonb_typeof(p_checks) = 'array' then p_checks else '[]'::jsonb end;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if not exists (select 1 from pipeline.aer_prompt_versions x where x.version = p_prompt_version) then raise exception 'unknown AER prompt version %', p_prompt_version; end if;
  select x->>'model_identifier' into v_model from jsonb_array_elements(security.ai_route_v1('entry_requirements_v2_shadow')->'models') x where x->>'model_identifier' = p_model;
  if p_model is distinct from v_model then raise exception 'model % is not a model of the route entry_requirements_v2_shadow', p_model; end if;  -- pinned: only a model of the route's cascade is kept
  select c.provider_id into v_prov from catalogue.courses c where c.id = p_course_id;
  if v_prov is null then raise exception 'course % not found', p_course_id; end if;
  select count(*) filter (where coalesce((x->>'pass')::boolean, false)), count(*) filter (where not coalesce((x->>'pass')::boolean, false))
    into v_pass, v_fail from jsonb_array_elements(v_checks) x;
  -- shadow only: the result is kept here and nowhere else (no catalogue table, no Layer 4 item)
  insert into pipeline.aer_v2_shadow_results(prompt_version, model, course_id, provider_id, evidence_id, content_hash, records, checks, seen_not_mapped, passed, failed, cost_usd, error, worker)
  values (p_prompt_version, p_model, p_course_id, v_prov, p_evidence_id, p_content_hash,
          case when jsonb_typeof(p_records) = 'array' then p_records else '[]'::jsonb end, v_checks,
          case when jsonb_typeof(p_seen_not_mapped) = 'array' then p_seen_not_mapped else '[]'::jsonb end,
          v_pass, v_fail, greatest(coalesce(p_cost_usd, 0), 0), left(p_error, 400), left(p_worker, 40))  -- fixed: column display lengths
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'passed', v_pass, 'failed', v_fail);
end $$;


ALTER FUNCTION "public"."svc_aer_v2_shadow_record"("p_course_id" "uuid", "p_prompt_version" "text", "p_model" "text", "p_evidence_id" "uuid", "p_content_hash" "text", "p_records" "jsonb", "p_checks" "jsonb", "p_seen_not_mapped" "jsonb", "p_cost_usd" numeric, "p_error" "text", "p_worker" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_aer_v2_shadow_record"("p_course_id" "uuid", "p_prompt_version" "text", "p_model" "text", "p_evidence_id" "uuid", "p_content_hash" "text", "p_records" "jsonb", "p_checks" "jsonb", "p_seen_not_mapped" "jsonb", "p_cost_usd" numeric, "p_error" "text", "p_worker" "text") IS 'AER v2 step 1 (worker mode aer_v2_shadow): records one shadow read of a stored course page (pinned model checked); writes pipeline.aer_v2_shadow_results only';



CREATE OR REPLACE FUNCTION "public"."svc_aer_v3_eval_next_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare r record; v_spent numeric; v_cap numeric := security.pipeline_num_v1('ai_eval.aer_v3_max_usd', 2);
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  perform set_config('cf247.ai_eval_path', 'on', true);
  if security.pipeline_num_v1('ai_eval.offline_runs_on', 0) <> 1 then return jsonb_build_object('run', null, 'why', 'ai_eval.offline_runs_on is 0'); end if;
  if security.pipeline_num_v1('ai_eval.aer_v3_runs_on', 0) <> 1 then return jsonb_build_object('run', null, 'why', 'ai_eval.aer_v3_runs_on is 0'); end if;
  select coalesce(sum(a.cost_usd), 0) into v_spent from pipeline.ai_eval_answers a join pipeline.ai_eval_runs x on x.id = a.run_id where security.aer_v3_eval_version_v1(x.version_id);
  if v_spent >= v_cap then return jsonb_build_object('run', null, 'why', format('spend cap reached: US$%s of US$%s (ai_eval.aer_v3_max_usd)', round(v_spent, 4), v_cap)); end if;
  select * into r from pipeline.ai_eval_runs
   where (state = 'queued' or (state = 'answering' and leased_until < now())) and security.aer_v3_eval_version_v1(version_id)
   order by requested_at limit 1 for update skip locked;
  if not found then return jsonb_build_object('run', null); end if;
  update pipeline.ai_eval_runs set state = 'answering', leased_until = now() + interval '30 minutes' where id = r.id;  -- fixed: claim lease
  return jsonb_build_object('run', r.id, 'set_id', r.set_id, 'budget', jsonb_build_object('cap_usd', v_cap, 'spent_usd', v_spent),
    'version', (select jsonb_build_object('id', v.id, 'version', v.version, 'model', v.model_identifier, 'body', v.body, 'spec', v.spec) from pipeline.ai_instruction_versions v where v.id = r.version_id),
    'countries', (select coalesce(jsonb_agg(k.iso_alpha2 order by k.iso_alpha2), '[]'::jsonb) from ref.countries k where k.iso_alpha2 is not null),
    'qualifications', (select coalesce(jsonb_agg(jsonb_build_object('code', q.code, 'name', q.name) order by q.code), '[]'::jsonb) from ref.aer_qualifications q),
    'examples', (select coalesce(jsonb_agg(security.aer_v3_eval_subject_v1(m.example_id) order by m.example_id), '[]'::jsonb)
                   from pipeline.ai_eval_set_members m where m.set_id = r.set_id
                    and not exists (select 1 from pipeline.ai_eval_answers a where a.run_id = r.id and a.example_id = m.example_id)));
end $_$;


ALTER FUNCTION "public"."svc_aer_v3_eval_next_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_aer_v3_eval_next_v1"() IS 'AER v3 benchmark: leases one opened AER v2 prompt v3 run for worker mode aer_v3_eval (both switches on and under the spend cap); answers go back through public.svc_ai_eval_answer_record_v1 and are scored by security.ai_eval_score_v1.';



CREATE OR REPLACE FUNCTION "public"."svc_ai_canary_answer_record_v1"("p_proposal_code" "text", "p_item_key" "text", "p_answer" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform set_config('cf247.ai_eval_path', 'on', true);
  update pipeline.ai_canary_assignments c set verdict = p_answer->>'verdict', value = p_answer->'value', quote_on_page = (p_answer->>'quote_on_page')::boolean,
         cost_usd = (p_answer->>'cost_usd')::numeric, tokens_in = (p_answer->>'tokens_in')::int, tokens_out = (p_answer->>'tokens_out')::int, error = p_answer->>'error', answered_at = now()
    from pipeline.ai_improvement_proposals p where p.id = c.proposal_id and p.code = p_proposal_code and c.item_key = p_item_key and c.answered_at is null;
  return jsonb_build_object('recorded', found);
end $$;


ALTER FUNCTION "public"."svc_ai_canary_answer_record_v1"("p_proposal_code" "text", "p_item_key" "text", "p_answer" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ai_eval_answer_record_v1"("p_run" bigint, "p_answers" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c int; v_left int;
begin
  perform set_config('cf247.ai_eval_path', 'on', true);
  if not exists (select 1 from pipeline.ai_eval_runs where id = p_run and state in ('queued', 'answering')) then
    raise exception 'ai_eval: run % is not open for answers', p_run using errcode = '22023';
  end if;
  insert into pipeline.ai_eval_answers(run_id, example_id, verdict, value, quote, quote_on_page, tokens_in, tokens_out, cost_usd, error)
  select p_run, (a->>'example_id')::bigint, a->>'verdict', a->'value', a->>'quote', (a->>'quote_on_page')::boolean, (a->>'tokens_in')::int, (a->>'tokens_out')::int,
         (a->>'cost_usd')::numeric, a->>'error'
    from jsonb_array_elements(coalesce(p_answers->'answers', p_answers)) a
   where exists (select 1 from pipeline.ai_eval_set_members m join pipeline.ai_eval_runs r on r.set_id = m.set_id where r.id = p_run and m.example_id = (a->>'example_id')::bigint)
  on conflict (run_id, example_id) do nothing;
  get diagnostics c = row_count;
  select count(*) into v_left from pipeline.ai_eval_set_members m join pipeline.ai_eval_runs r on r.set_id = m.set_id
   where r.id = p_run and not exists (select 1 from pipeline.ai_eval_answers a where a.run_id = p_run and a.example_id = m.example_id);
  if v_left = 0 or coalesce((p_answers->>'done')::boolean, false) then
    update pipeline.ai_eval_runs set state = 'recorded', recorded_at = now(), leased_until = null, worker = left(p_answers->>'worker', 60) where id = p_run;
  end if;
  return jsonb_build_object('run', p_run, 'recorded', c, 'unanswered', v_left);
end $$;


ALTER FUNCTION "public"."svc_ai_eval_answer_record_v1"("p_run" bigint, "p_answers" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ai_eval_run_next_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record;
begin
  perform set_config('cf247.ai_eval_path', 'on', true);
  if security.pipeline_num_v1('ai_eval.offline_runs_on', 0) <> 1 then return jsonb_build_object('run', null, 'why', 'ai_eval.offline_runs_on is 0'); end if;
  select * into r from pipeline.ai_eval_runs
   where (state = 'queued' or (state = 'answering' and leased_until < now()))
     and not security.aer_v3_eval_version_v1(version_id)  -- 14 Nov 2026: AER v3 runs are leased by public.svc_aer_v3_eval_next_v1 only
   order by requested_at limit 1 for update skip locked;
  if not found then return jsonb_build_object('run', null); end if;
  update pipeline.ai_eval_runs set state = 'answering', leased_until = now() + interval '30 minutes' where id = r.id;  -- fixed: claim lease
  return jsonb_build_object('run', r.id, 'arm', r.arm, 'set_id', r.set_id,
    'version', (select jsonb_build_object('id', v.id, 'code', v.code, 'version', v.version, 'kind', v.kind, 'home', v.home, 'body', v.body, 'spec', v.spec, 'model', v.model_identifier)
                  from pipeline.ai_instruction_versions v where v.id = r.version_id),
    'examples', (select coalesce(jsonb_agg(jsonb_build_object('example_id', x.id, 'entity', x.entity, 'entity_id', x.entity_id, 'field', x.field,
                                                             'input_ref', x.input_ref, 'evidence_id', x.evidence_id, 'page_ref', x.page_ref) order by x.id), '[]')
                   from pipeline.ai_eval_set_members m join pipeline.ai_eval_examples x on x.id = m.example_id where m.set_id = r.set_id));
end $$;


ALTER FUNCTION "public"."svc_ai_eval_run_next_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ai_input_observe_v1"("p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_n int := 0; v_gone int := 0;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then return jsonb_build_object('kept', 0); end if;
  insert into pipeline.ai_input_observations (contract, worker, read, field, item_id, course_id, storage_path, source_sha256, converter, source_chars,
         sent_chars, limit_chars, cut, cut_at, lean_chars, lean_tables, lean_table_rows, preflight_sent, preflight_full, prompt_key, model, schema_key,
         input_sha256, fingerprint, selector, sel_input, sel_blocks, sel_chars, sel_no_selection, sel_block_ids, preflight_selection, sel_sha256, sel_ms)
  select left(x->>'contract', 60), left(x->>'worker', 60), left(x->>'read', 40), left(x->>'field', 40), (x->>'item_id')::bigint,
         case when x->>'course_id' ~ '^[0-9a-f-]{36}$' then (x->>'course_id')::uuid end, left(x->>'storage_path', 400), left(x->>'source_sha256', 64),
         left(x->>'converter', 40), (x->>'source_chars')::int, (x->>'sent_chars')::int, (x->>'limit_chars')::int, coalesce((x->>'cut')::boolean, false),
         (x->>'cut_at')::int, (x->>'lean_chars')::int, (x->>'lean_tables')::int, (x->>'lean_table_rows')::int,
         case when x->>'preflight_sent' in ('likely', 'unknown', 'no_signal', 'not_measured') then x->>'preflight_sent' end,
         case when x->>'preflight_full' in ('likely', 'unknown', 'no_signal', 'not_measured') then x->>'preflight_full' end,
         left(x->>'prompt_key', 120), left(x->>'model', 120), left(x->>'schema_key', 120), left(x->>'input_sha256', 64), left(x->>'fingerprint', 64),
         left(x->>'selector', 60), left(x->>'sel_input', 40), (x->>'sel_blocks')::int, (x->>'sel_chars')::int, (x->>'sel_no_selection')::boolean,
         case when jsonb_typeof(x->'sel_block_ids') = 'array' then (select array_agg(left(e, 12)) from (select jsonb_array_elements_text(x->'sel_block_ids') e limit 400) z) end,  -- fixed: the recorded id list's length, a storage bound
         case when x->>'preflight_selection' in ('likely', 'unknown', 'no_signal', 'not_measured') then x->>'preflight_selection' end,
         left(x->>'sel_sha256', 64), (x->>'sel_ms')::int
    from jsonb_array_elements(p_rows) x
   where coalesce(x->>'read', '') <> '' and coalesce(x->>'field', '') <> '' and coalesce(x->>'contract', '') <> '';
  get diagnostics v_n = row_count;
  delete from pipeline.ai_input_observations o
   where o.id in (select o2.id from pipeline.ai_input_observations o2
                   where o2.observed_at < now() - make_interval(days => security.pipeline_num_v1('reading.input_observation_retention_days', 30)::int)
                   order by o2.id limit security.pipeline_num_v1('reading.input_observation_purge_batch', 2000)::int);
  get diagnostics v_gone = row_count;
  return jsonb_build_object('kept', v_n, 'expired_removed', v_gone);
end $_$;


