CREATE OR REPLACE FUNCTION "public"."svc_ai_model_answered_v1"("p_source" "text", "p_source_id" "text", "p_model" "text", "p_attempts" "jsonb" DEFAULT NULL::"jsonb", "p_worker" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare n int := 0;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if jsonb_typeof(p_attempts) = 'array' then
    insert into pipeline.ai_invocations (service_code, model, attempt_no, outcome, failure_kind, input_tokens, output_tokens, cost_usd, source, source_id, worker)
    select nullif(x->>'service', ''), x->>'model', coalesce((x->>'attempt_no')::int, 1), case when x->>'outcome' = 'answered' then 'answered' else 'failed' end,
           case when x->>'failure_kind' in ('http', 'timeout', 'empty', 'cut', 'non_json', 'refused') then x->>'failure_kind' end,
           (x->>'input_tokens')::int, (x->>'output_tokens')::int, (x->>'cost')::numeric, nullif(x->>'source', ''), nullif(x->>'source_id', ''), left(p_worker, 60)
      from jsonb_array_elements(p_attempts) x where nullif(x->>'model', '') is not null and coalesce(x->>'failure_kind', '') <> 'key_limit';
    get diagnostics n = row_count;
    -- CF-247 worker v1.0.3: attempts the OpenRouter key refused for its own limit: an account stop, kept apart from the model's attempts
    insert into pipeline.ai_key_limit_attempts (service_code, model, attempt_no, source, source_id, worker)
    select nullif(x->>'service', ''), x->>'model', coalesce((x->>'attempt_no')::int, 1), nullif(x->>'source', ''), nullif(x->>'source_id', ''), left(p_worker, 60)
      from jsonb_array_elements(p_attempts) x where nullif(x->>'model', '') is not null and x->>'failure_kind' = 'key_limit';
    -- CF-247 worker v1.0.0: the time of each attempt, for the model health check (pipeline.ai_attempt_times)
    insert into pipeline.ai_attempt_times (service_code, model, outcome, ms)
    select nullif(x->>'service', ''), x->>'model', case when x->>'outcome' = 'answered' then 'answered' else 'failed' end, (x->>'ms')::int
      from jsonb_array_elements(p_attempts) x where nullif(x->>'model', '') is not null and coalesce(x->>'ms', '') ~ '^[0-9]{1,9}$'
       and coalesce(x->>'failure_kind', '') <> 'key_limit';
  end if;
  if p_model is not null and p_source is not null and exists (select 1 from pipeline.ai_model_catalogue m where m.model_identifier = p_model) then
    update pipeline.ai_spend_ledger l set model = p_model
     where l.id = (select max(x.id) from pipeline.ai_spend_ledger x where x.source = p_source and x.source_id = p_source_id and x.at > now() - interval '15 minutes')  -- fixed: the record of the same worker call
       and l.model is distinct from p_model;
    if p_attempts is null then get diagnostics n = row_count; end if;
  end if;
  return n;
end $_$;


