CREATE OR REPLACE FUNCTION "public"."svc_calendar_refresh_v1"("p_reader" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_budget numeric := security.pipeline_num_v1('central.calendar_refresh_credit_budget', 40);
        v_each numeric := security.pipeline_num_v1('central.calendar_refresh_credits_per_read', 5); v_res numeric;
        v_batch int := security.pipeline_num_v1('batch.calendar_refresh', 1)::int;
        v_age int := security.pipeline_num_v1('central.calendar_refresh_min_age_days', 7)::int;
        v_next int := extract(year from (now() at time zone 'Australia/Melbourne'))::int + 1;  -- fixed: the next academic year in Australia
        v_spent numeric; v_asked int := 0; r record; v_prop uuid;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  -- one run at a time (a scheduled run and a manual one never both ask)
  if not pg_try_advisory_xact_lock(hashtext('cf247.calendar_refresh')) then return jsonb_build_object('asked', 0, 'skipped', 'another refresh run is in progress'); end if;
  -- outcomes of earlier requests: the provider-facts job has read the document again (or given up)
  update pipeline.calendar_refresh_requests q set
         status = case when f.status in ('failed', 'error') then 'failed' when f.content_hash is distinct from q.old_content_hash then 'new_edition_stored' else 'unchanged' end,
         new_evidence_id = f.evidence_id, new_content_hash = f.content_hash, resolved_at = now(),
         yield = case when f.content_hash is distinct from q.old_content_hash then 'pending' else 'no_next_year' end
    from pipeline.provider_fact_sources f
   where f.id = q.fact_source_id and q.status = 'requested' and f.status not in ('found', 'reading') and f.updated_at > q.requested_at;
  update pipeline.calendar_refresh_requests q set credits_used = (select coalesce(sum(c.credits_used), 0) from pipeline.firecrawl_calls c where c.at >= q.requested_at
                                                                     and c.at < coalesce(q.resolved_at, now()) + interval '1 hour'  -- fixed: the read follows the request
                                                                     -- the address, or any read for that university without a course while the request was open (counted high, never low)
                                                                     and (c.url = q.url or (c.provider_id = q.provider_id and c.course_id is null and c.at <= coalesce(q.resolved_at, now()))))
   where q.requested_at > now() - interval '7 days';  -- fixed: credits of recent requests are refreshed; older ones are settled
  -- useful yield: the new edition, read by the current reader, gives a next-year start
  for r in select q.id, q.fact_source_id from pipeline.calendar_refresh_requests q where q.yield = 'pending' loop
    select p.id into v_prop from pipeline.provider_policy_proposals p
     where p.fact_source_id = r.fact_source_id and p.kind = 'intake_calendar' and p.status = 'approved' and (p.parser like '%' || p_reader or p.parser = 'provider-policy-calendar-dates-v2')
       and p.content_hash = (select f.content_hash from pipeline.provider_fact_sources f where f.id = r.fact_source_id)
     order by p.decided_at desc nulls last limit 1;
    if v_prop is not null then
      update pipeline.calendar_refresh_requests set next_year_starts = (select count(*) from security.calendar_proposal_dates_v1(v_prop) d where d.kind = 'start' and d.year >= v_next),
             yield = case when exists (select 1 from security.calendar_proposal_dates_v1(v_prop) d where d.kind = 'start' and d.year >= v_next) then 'next_year_starts' else 'no_next_year' end
       where id = r.id;
    end if;
  end loop;
  select coalesce(sum(greatest(q.credit_estimate, coalesce(q.credits_used, 0))), 0) into v_spent from pipeline.calendar_refresh_requests q;
  if v_batch > 0 and not exists (select 1 from pipeline.calendar_refresh_requests q where q.status = 'requested') then
    for r in
      with rel as (select * from security.calendar_reread_relevant_v1()),
      held as (select rel.provider_id from rel where exists (select 1 from security.calendar_dated_periods_v2(rel.provider_id) p where p.kind = 'start' and p.year_ok and p.year >= v_next))
      select f.id, f.provider_id, f.url, f.evidence_id, f.content_hash, f.read_at, rel.missing
        from pipeline.provider_fact_sources f join rel on rel.provider_id = f.provider_id join pipeline.calendar_reread_state s on s.fact_source_id = f.id
       where f.kind = 'intake_calendar' and f.evidence_id is not null and f.status not in ('found', 'reading') and f.decided_by is null and f.decision is null
         -- never a person's binding, and never a reading that says the calendar is not the main teaching calendar
         and not exists (select 1 from pipeline.provider_policy_proposals p where p.fact_source_id = f.id and p.status = 'approved'
                           and (p.decided_by is not null or p.parser = 'set by hand' or coalesce(p.proposal->>'scope', '') not in ('', 'main_teaching')))
         and security.calendar_scope_v1('{}'::jsonb, f.url, null) = 'main_teaching'
         and s.reader_version = p_reader and s.state in ('dated_by_parser', 'read_by_ai', 'no_dates') and coalesce(s.reason, '') not like 'not needed:%'
         and coalesce(f.read_at, f.updated_at) < now() - make_interval(days => v_age)
         and f.provider_id not in (select held.provider_id from held)
         and not exists (select 1 from pipeline.calendar_refresh_requests q where q.url = f.url)
         -- its own reading by the current reader shows no next-year start
         and not exists (select 1 from pipeline.provider_policy_proposals p, security.calendar_proposal_dates_v1(p.id) d
                          where p.fact_source_id = f.id and p.kind = 'intake_calendar' and p.status = 'approved' and d.kind = 'start' and d.year >= v_next)
       order by rel.missing desc, f.rank nulls last
       limit v_batch
    loop
      -- the reservation: the larger of the setting and what an earlier Firecrawl read of this address used
      v_res := greatest(v_each, coalesce((select max(c.credits_used) from pipeline.firecrawl_calls c where c.url = r.url), 0));
      exit when v_spent + v_res > v_budget;
      insert into pipeline.calendar_refresh_requests(fact_source_id, provider_id, url, reader_version, reason, old_evidence_id, old_content_hash, old_read_at, credit_estimate)
      values (r.id, r.provider_id, r.url, p_reader, format('no %s start in the stored copy read by %s; no equivalent %s edition held; %s intake rows miss a date', v_next, p_reader, v_next, r.missing),
              r.evidence_id, r.content_hash, r.read_at, v_res)
      on conflict do nothing;
      update pipeline.provider_fact_sources set status = 'found', attempts = 0, updated_at = now() where id = r.id;
      v_spent := v_spent + v_res; v_asked := v_asked + 1;
    end loop;
  end if;
  return jsonb_build_object('asked', v_asked, 'credits_counted', v_spent, 'budget', v_budget,
    'open', (select count(*) from pipeline.calendar_refresh_requests where status = 'requested'));
end $$;


ALTER FUNCTION "public"."svc_calendar_refresh_v1"("p_reader" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_calendar_refresh_v1"("p_reader" "text") IS 'CF-247 (mandate 5 Nov 2026 12:44 R2): records the outcome, credit use and yield of earlier calendar refresh requests, then asks the existing provider-facts job to read again (status found) at most batch.calendar_refresh stored main teaching calendars of top universities whose reading by the given reader shows no next-year start, with no equivalent edition held, an old copy, no person''s decision and no earlier request for the address, while the credits counted stay within central.calendar_refresh_credit_budget. The old edition is kept. Service role only.';



CREATE OR REPLACE FUNCTION "public"."svc_calendar_reread_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  insert into pipeline.calendar_reread_state(fact_source_id, provider_id, content_hash)
  select f.id, f.provider_id, f.content_hash from pipeline.provider_fact_sources f
   where f.kind = 'intake_calendar' and f.evidence_id is not null
     and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = f.provider_id)
  on conflict (fact_source_id) do update set state = 'waiting', attempts = 0, content_hash = excluded.content_hash, reason = 'the stored document changed'
   where pipeline.calendar_reread_state.content_hash is distinct from excluded.content_hash and pipeline.calendar_reread_state.state <> 'leased';
  with pick as (
    select s.fact_source_id from pipeline.calendar_reread_state s left join pipeline.enrich_focus_providers fp on fp.provider_id = s.provider_id and fp.in_focus
     where (s.state = 'waiting' or (s.state = 'leased' and s.leased_until < now())) and s.attempts < 3  -- fixed: three tries, then failed with the reason
     order by fp.rank nulls last, s.created_at limit greatest(1, least(coalesce(p_limit, 20), 60)) for update of s skip locked),  -- fixed: the worker's call bound
  upd as (update pipeline.calendar_reread_state s set state = 'leased', leased_until = now() + interval '4 minutes', attempts = s.attempts + 1  -- fixed: lease
            from pick where s.fact_source_id = pick.fact_source_id returning s.*)
  select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'provider_id', f.provider_id, 'url', f.url, 'storage_path', e.storage_path,
           'trusted_address', security.calendar_scope_v1('{}'::jsonb, f.url, null) = 'main_teaching')), '[]'::jsonb) into v
    from upd u join pipeline.provider_fact_sources f on f.id = u.fact_source_id join pipeline.evidence_artifacts e on e.id = f.evidence_id;
  return v;
end $$;


ALTER FUNCTION "public"."svc_calendar_reread_next"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_calendar_reread_next"("p_limit" integer) IS 'CF-247 (decision 5 Nov 2026 §2): the next stored calendar documents for the current calendar reader (new, changed, or never read by it), focus universities first; leased for the worker. Service role only.';



CREATE OR REPLACE FUNCTION "public"."svc_calendar_reread_next_v2"("p_limit" integer, "p_reader" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb; v_rel jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if coalesce(p_reader, '') = '' then raise exception 'the calendar reader version is required'; end if;
  select coalesce(jsonb_object_agg(x.provider_id, x.missing), '{}'::jsonb) into v_rel from security.calendar_reread_relevant_v2() x;
  insert into pipeline.calendar_reread_state(fact_source_id, provider_id, content_hash)
  select f.id, f.provider_id, f.content_hash from pipeline.provider_fact_sources f
   where f.kind = 'intake_calendar' and f.evidence_id is not null
     and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = f.provider_id)
  on conflict (fact_source_id) do update set state = 'waiting', attempts = 0, content_hash = excluded.content_hash, reason = 'the stored document changed'
   where pipeline.calendar_reread_state.content_hash is distinct from excluded.content_hash and pipeline.calendar_reread_state.state <> 'leased';
  -- the reader changed: every document read by an earlier reader is read again (none with an AI read still open)
  update pipeline.calendar_reread_state s set state = 'waiting', attempts = 0, reason = 'the calendar reader changed to ' || p_reader
   where s.reader_version is distinct from p_reader and s.state in ('dated_by_parser', 'read_by_ai', 'no_dates', 'failed', 'sent_to_ai')
     and not (s.state = 'no_dates' and s.reason like 'not needed:%')
     and not exists (select 1 from pipeline.central_ai_queue q where q.fact_source_id = s.fact_source_id and q.state in ('queued', 'leased'));
  -- set aside until needed: no intake row of the university misses a date, or the address is not a main teaching calendar
  update pipeline.calendar_reread_state s set state = 'no_dates', reader_version = p_reader, last_at = now(),
         reason = case when not v_rel ? s.provider_id::text then 'not needed: no intake row of this university in the intake scope misses a date'
                       else 'not needed: the address is not a main teaching calendar' end
    from pipeline.provider_fact_sources f
   where f.id = s.fact_source_id and s.state = 'waiting'
     and (not v_rel ? s.provider_id::text or security.calendar_scope_v1('{}'::jsonb, f.url, null) <> 'main_teaching');
  -- needed again: woken when the university's rows need a date again and the address is a main teaching calendar
  update pipeline.calendar_reread_state s set state = 'waiting', attempts = 0, reason = 'needed: intake rows of this university miss a date'
    from pipeline.provider_fact_sources f
   where f.id = s.fact_source_id and s.state = 'no_dates' and s.reason like 'not needed:%'
     and v_rel ? s.provider_id::text and security.calendar_scope_v1('{}'::jsonb, f.url, null) = 'main_teaching';
  with pick as (
    select s.fact_source_id from pipeline.calendar_reread_state s
     where (s.state = 'waiting' or (s.state = 'leased' and s.leased_until < now())) and s.attempts < 3  -- fixed: three tries, then failed with the reason
     order by (v_rel->>s.provider_id::text)::int desc nulls last, s.created_at limit greatest(1, least(coalesce(p_limit, 20), 60)) for update of s skip locked),  -- fixed: the worker's call bound
  upd as (update pipeline.calendar_reread_state s set state = 'leased', leased_until = now() + interval '4 minutes', attempts = s.attempts + 1  -- fixed: lease
            from pick where s.fact_source_id = pick.fact_source_id returning s.*)
  select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'provider_id', f.provider_id, 'url', f.url, 'storage_path', e.storage_path,
           'trusted_address', security.calendar_scope_v1('{}'::jsonb, f.url, null) = 'main_teaching')), '[]'::jsonb) into v
    from upd u join pipeline.provider_fact_sources f on f.id = u.fact_source_id join pipeline.evidence_artifacts e on e.id = f.evidence_id;
  return v;
end $$;


ALTER FUNCTION "public"."svc_calendar_reread_next_v2"("p_limit" integer, "p_reader" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_calendar_reread_next_v2"("p_limit" integer, "p_reader" "text") IS 'CF-247 (mandate 5 Nov 2026 R1, §8): the next stored calendar documents for the given calendar reader: new, changed, or read by an earlier reader; only main teaching calendars of universities in the intake scope with rows missing a date, most missing first (the rest set aside as not needed, woken when needed); leased for the worker. Replaces svc_calendar_reread_next(integer). Service role only.';



CREATE OR REPLACE FUNCTION "public"."svc_calendar_reread_record"("p_id" "uuid", "p_parsed" "jsonb", "p_send_to_ai" boolean, "p_reason" "text", "p_error" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare s pipeline.calendar_reread_state%rowtype; r jsonb; v_q bigint;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into s from pipeline.calendar_reread_state where fact_source_id = p_id for update;
  if s.fact_source_id is null then return jsonb_build_object('ok', false); end if;
  if p_error is not null then
    update pipeline.calendar_reread_state set state = case when s.attempts >= 3 then 'failed' else 'waiting' end, reason = left(p_error, 400), leased_until = null, last_at = now()  -- fixed: three tries
     where fact_source_id = p_id;
    return jsonb_build_object('ok', true, 'state', 'error');
  end if;
  -- the dated parser's reading is recorded as a proposal of its own (never into an approved one); approval stays with the existing mechanism
  if p_parsed is not null and jsonb_array_length(coalesce(p_parsed->'periods', '[]'::jsonb)) > 0 then
    r := public.svc_provider_policy_record(p_id, p_parsed);
  end if;
  if p_send_to_ai then
    -- the existing central-page AI queue (job central-ai, pinned model); one open item a document
    if not coalesce((select c.enabled from pipeline.central_ai_settings c where c.id = 1), false) then
      p_send_to_ai := false; p_reason := 'the central-page AI reader is switched off; ' || coalesce(p_reason, '');
    else
      insert into pipeline.central_ai_queue(fact_source_id, provider_id, kind, content_hash)
      select f.id, f.provider_id, f.kind, f.content_hash from pipeline.provider_fact_sources f where f.id = p_id
         and not exists (select 1 from pipeline.central_ai_queue q where q.fact_source_id = f.id and q.state in ('queued', 'leased'))
      returning id into v_q;
    end if;
  end if;
  update pipeline.calendar_reread_state set state = case when p_send_to_ai then 'sent_to_ai' when r is not null then 'dated_by_parser' else 'no_dates' end,
         reader = coalesce(p_parsed->>'parser', s.reader), reason = left(p_reason, 400), parser_summary = jsonb_build_object('periods', jsonb_array_length(coalesce(p_parsed->'periods', '[]'::jsonb)),
         'starts', (select count(*) from jsonb_array_elements(coalesce(p_parsed->'periods', '[]'::jsonb)) e, jsonb_array_elements(coalesce(e->'starts', '[]'::jsonb)) x),
         'deadlines', (select count(*) from jsonb_array_elements(coalesce(p_parsed->'periods', '[]'::jsonb)) e, jsonb_array_elements(coalesce(e->'deadlines', '[]'::jsonb)) x),
         'proposal', r), leased_until = null, last_at = now()
   where fact_source_id = p_id;
  return jsonb_build_object('ok', true, 'proposal', r, 'sent_to_ai', p_send_to_ai);
end $$;


ALTER FUNCTION "public"."svc_calendar_reread_record"("p_id" "uuid", "p_parsed" "jsonb", "p_send_to_ai" boolean, "p_reason" "text", "p_error" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_calendar_reread_record"("p_id" "uuid", "p_parsed" "jsonb", "p_send_to_ai" boolean, "p_reason" "text", "p_error" "text") IS 'CF-247 (decision 5 Nov 2026 §2): records a stored calendar document read again: the dated parser''s reading as its own proposal (existing approval), and the existing central-page AI queue when the parser cannot read it safely, with the reason. Service role only.';



CREATE OR REPLACE FUNCTION "public"."svc_calendar_reread_record_v2"("p_id" "uuid", "p_parsed" "jsonb", "p_send_to_ai" boolean, "p_reason" "text", "p_error" "text", "p_reader" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  r := public.svc_calendar_reread_record(p_id, p_parsed, p_send_to_ai, p_reason, p_error);
  if p_error is null then update pipeline.calendar_reread_state set reader_version = p_reader where fact_source_id = p_id; end if;
  return r || jsonb_build_object('reader', p_reader);
end $$;


ALTER FUNCTION "public"."svc_calendar_reread_record_v2"("p_id" "uuid", "p_parsed" "jsonb", "p_send_to_ai" boolean, "p_reason" "text", "p_error" "text", "p_reader" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_calendar_reread_record_v2"("p_id" "uuid", "p_parsed" "jsonb", "p_send_to_ai" boolean, "p_reason" "text", "p_error" "text", "p_reader" "text") IS 'CF-247 (mandate 5 Nov 2026 R1): records a stored calendar document read again (svc_calendar_reread_record) with the calendar reader version that read it. Service role only.';



CREATE OR REPLACE FUNCTION "public"."svc_central_ai_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb; s pipeline.central_ai_settings%rowtype;
        -- 13 Nov 2026: each kind of central page has its own route (model, cap, switch); the settings row keeps the lane switch and calls at once
        v_cal jsonb := security.ai_route_gate_v1('calendar_reading'); v_pol jsonb := security.ai_route_gate_v1('central_english_policy');
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into s from pipeline.central_ai_settings where id = 1;
  if not coalesce(s.enabled, false) then return '[]'::jsonb; end if;
  with pick as (select q.id from pipeline.central_ai_queue q where (q.state = 'queued' or (q.state = 'leased' and q.leased_until < now())) and q.attempts < 3
                   and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = q.provider_id)  -- 22 Oct 2026 (Platform Admin 11:42): unpublished providers wait; publishing them again brings them back
                   and security.ai_route_open_v1(case when q.kind = 'intake_calendar' then v_cal else v_pol end, q.provider_id)
                 order by q.id limit greatest(1, least(coalesce(p_limit, 6), 10)) for update skip locked),
  upd as (update pipeline.central_ai_queue q set state = 'leased', leased_until = now() + interval '4 minutes', attempts = q.attempts + 1 from pick where q.id = pick.id returning q.*)
  select coalesce(jsonb_agg(jsonb_build_object('queue_id', u.id, 'id', u.fact_source_id, 'kind', u.kind, 'url', f.url, 'provider', coalesce(p.display_name, p.canonical_name),
           'storage_path', e.storage_path, 'notes', case when u.kind = 'intake_calendar' then security.calendar_reader_notes_v1(u.provider_id) end, 'model', (case when u.kind = 'intake_calendar' then v_cal else v_pol end)->>'model',
           'model_code', (case when u.kind = 'intake_calendar' then v_cal else v_pol end)#>>'{models,0,code}', 'models', (case when u.kind = 'intake_calendar' then v_cal else v_pol end)->'models')), '[]'::jsonb) into v
    from upd u join pipeline.provider_fact_sources f on f.id = u.fact_source_id join pipeline.evidence_artifacts e on e.id = f.evidence_id
    join catalogue.providers p on p.id = u.provider_id;
  return v;
end $$;


ALTER FUNCTION "public"."svc_central_ai_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_central_ai_record"("p_queue_id" bigint, "p_parsed" "jsonb", "p_cost" numeric, "p_error" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare q pipeline.central_ai_queue%rowtype; r jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into q from pipeline.central_ai_queue where id = p_queue_id for update;
  if q.id is null then return jsonb_build_object('ok', false); end if;
  if p_error is not null then
    update pipeline.central_ai_queue set state = case when p_error = 'time budget' then 'queued' when attempts >= 3 then 'failed' else 'queued' end,
           attempts = case when p_error = 'time budget' then greatest(attempts - 1, 0) else attempts end, leased_until = null, error = left(p_error, 400), cost_usd = coalesce(cost_usd, 0) + coalesce(p_cost, 0)
     where id = q.id;
    return jsonb_build_object('ok', true, 'status', 'error');
  end if;
  r := public.svc_provider_policy_record(q.fact_source_id, p_parsed);
  if q.kind = 'intake_calendar' then perform security.calendar_reader_findings_record_v1(q.fact_source_id, q.provider_id, p_parsed); end if;  -- CF-247 decision 5 Nov 2026 §7
  update pipeline.central_ai_queue set state = 'done', done_at = now(), leased_until = null, status = r->>'status', cost_usd = coalesce(cost_usd, 0) + coalesce(p_cost, 0), error = null where id = q.id;
  if r->>'status' = 'proposed' then
    update pipeline.provider_onboarding o set stop_reason = 'approve_central', updated_at = now(),
           note = 'The AI read its central pages; approve or reject them in the Adapter builder (1.3) or Providers › Onboarding › Approvals waiting.'
     where o.provider_id = q.provider_id and o.status = 'stopped' and o.stop_reason = 'nothing_ready';
  end if;
  return jsonb_build_object('ok', true, 'status', r->>'status');
end $$;


ALTER FUNCTION "public"."svc_central_ai_record"("p_queue_id" bigint, "p_parsed" "jsonb", "p_cost" numeric, "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_central_entry_record"("p_provider_id" "uuid", "p_found" "jsonb", "p_evidence" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_entry jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select coalesce(jsonb_agg(e), '[]'::jsonb) into v_entry
    from jsonb_array_elements(case when jsonb_typeof(p_found) = 'array' then p_found else '[]'::jsonb end) e
   where e->>'kind' = 'entry_requirements' and e->>'url' ~* '^https?://';
  if coalesce(p_evidence, '{}'::jsonb) ? 'error' then
    -- a failed try: the request settles 'failed' (security.aer_source_discover_v1) and is asked again within the maximum tries
    update pipeline.provider_central_search s
       set state = 'queued', leased_until = null, requested_at = null, updated_at = now(),
           evidence = coalesce(s.evidence, '{}'::jsonb) || jsonb_build_object('error', p_evidence->>'error', 'entry_search', p_evidence)
     where s.provider_id = p_provider_id;
    return;
  end if;
  update pipeline.provider_central_search s
     set found = coalesce((select jsonb_agg(e) from jsonb_array_elements(coalesce(s.found, '[]'::jsonb)) e where e->>'kind' is distinct from 'entry_requirements'), '[]'::jsonb) || v_entry,
         evidence = (coalesce(s.evidence, '{}'::jsonb) - 'error' - 'refusal' - 'note') || jsonb_build_object('entry_search', p_evidence || jsonb_build_object('suggested', jsonb_array_length(v_entry))),
         state = 'done', searched_at = now(), requested_at = null, leased_until = null, updated_at = now()
   where s.provider_id = p_provider_id;
end $$;


ALTER FUNCTION "public"."svc_central_entry_record"("p_provider_id" "uuid", "p_found" "jsonb", "p_evidence" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_central_entry_record"("p_provider_id" "uuid", "p_found" "jsonb", "p_evidence" "jsonb") IS 'CF-247 F-AER.01 (20261111100000): records a targeted entry-requirements search of a provider''s own website: replaces only the entry_requirements suggestions in provider_central_search.found and sets searched_at; an error is a failed try. Called by worker coverage-sweep central_find.';



CREATE OR REPLACE FUNCTION "public"."svc_central_find_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  with pick as (
    select s.provider_id from pipeline.provider_central_search s join catalogue.providers p on p.id = s.provider_id
     where (s.state = 'queued' or (s.state = 'leased' and s.leased_until < now())) and s.attempts < 3
       and p.lifecycle_status = 'active' and p.website ~* '^https?://' and not security.third_party_host_v1(p.website)
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = s.provider_id)
       and (s.requested_at is not null or not security.flag_provider_held_v1(s.provider_id, array['central_not_due', 'central_budget', 'site_unreachable']))  -- CF-247 15 Oct 2026: held until due
     order by (s.requested_at is null), s.requested_at, (select count(*) from catalogue.courses c where c.provider_id = s.provider_id and c.lifecycle_status = 'active') desc
     limit greatest(1, least(coalesce(p_limit, 4), 10)) for update of s skip locked),
  upd as (update pipeline.provider_central_search s set state = 'leased', leased_until = now() + interval '10 minutes', attempts = s.attempts + 1, updated_at = now()
            from pick where s.provider_id = pick.provider_id returning s.provider_id)
  select coalesce(jsonb_agg(jsonb_build_object('provider_id', u.provider_id, 'name', coalesce(p.display_name, p.canonical_name), 'website', p.website)), '[]'::jsonb)
    into v from upd u join catalogue.providers p on p.id = u.provider_id;
  return v;
end $$;


ALTER FUNCTION "public"."svc_central_find_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_central_find_record"("p_provider_id" "uuid", "p_found" "jsonb", "p_evidence" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_last timestamptz; v_due timestamptz;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if p_found is null then  -- no credit to spend: back in the queue, unchanged, and held by a flag until it is due (CF-247 15 Oct 2026: it was picked again every 5 minutes)
    update pipeline.provider_central_search set state = 'queued', leased_until = null, attempts = greatest(attempts - 1, 0), evidence = p_evidence, requested_at = null, updated_at = now() where provider_id = p_provider_id;
    select max(x.at) into v_last from pipeline.coverage_vendor_usage x where x.provider_id = p_provider_id and security.fc_purpose_group_v1(x.purpose) = 'central';
    v_due := v_last + make_interval(days => security.fc_setting_num_v1('central_refresh_days', 30)::int);
    if v_due > now() then
      perform security.flag_raise_v1('provider', p_provider_id::text, p_provider_id, 'central_pages', 'central_not_due',
        format('Central pages read on %s; due again on %s (Firecrawl settings › central refresh days)', to_char(v_last at time zone 'Australia/Melbourne', 'DD Mon YYYY'), to_char(v_due at time zone 'Australia/Melbourne', 'DD Mon YYYY')),
        'hard', 'central-find', 'auto', coalesce(p_evidence, '{}'::jsonb) || jsonb_build_object('last_read', v_last, 'due', v_due), null, v_due);
    else
      perform security.flag_raise_v1('provider', p_provider_id::text, p_provider_id, 'central_pages', 'central_budget', 'No Firecrawl credit left in today''s share for central pages', 'hard', 'central-find', 'auto',
        coalesce(p_evidence, '{}'::jsonb), null, (date_trunc('day', now() at time zone 'Australia/Melbourne') + interval '1 day') at time zone 'Australia/Melbourne');  -- fixed: the daily budget resets at midnight
    end if;
    return;
  end if;
  update pipeline.provider_central_search s
     set state = case when p_evidence ? 'error' then (case when attempts >= 3 then 'failed' else 'queued' end) else 'done' end,
         found = case when p_evidence ? 'error' then s.found else p_found end, evidence = p_evidence, leased_until = null,
         searched_at = case when p_evidence ? 'error' then searched_at else now() end,
         requested_at = case when p_evidence ? 'error' then requested_at end, updated_at = now()
   where provider_id = p_provider_id;
end $$;


ALTER FUNCTION "public"."svc_central_find_record"("p_provider_id" "uuid", "p_found" "jsonb", "p_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_cf245_capture_coverage_snapshot"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'search', 'ref', 'catalogue'
    AS $$
declare v_hour timestamptz:=date_trunc('hour',now()); v_rows integer:=0;
begin
  if current_user not in('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
  with countries as (
    select trim(c.iso_alpha2)::text country_code,count(*)::bigint total_courses
    from search.course_documents d join ref.countries c on c.id=d.country_id
    where trim(c.iso_alpha2) in('AU','NZ') group by 1
  ), coverage as (
    select trim(c.iso_alpha2)::text country_code,'official_course_url'::text field_key,count(*) filter(where d.official_course_url is not null)::bigint covered_count
    from search.course_documents d join ref.countries c on c.id=d.country_id where trim(c.iso_alpha2) in('AU','NZ') group by 1
    union all
    select trim(c.iso_alpha2)::text,'intake_availability',count(*) filter(where jsonb_array_length(coalesce(d.intake_options,'[]'::jsonb))>0)::bigint
    from search.course_documents d join ref.countries c on c.id=d.country_id where trim(c.iso_alpha2) in('AU','NZ') group by 1
    union all
    select trim(c.iso_alpha2)::text,'english_requirements',count(*) filter(where jsonb_array_length(coalesce(d.english_requirement_options,'[]'::jsonb))>0)::bigint
    from search.course_documents d join ref.countries c on c.id=d.country_id where trim(c.iso_alpha2) in('AU','NZ') group by 1
    union all
    select trim(c.iso_alpha2)::text,'provider_current_international_tuition',count(*) filter(where d.has_provider_current_tuition)::bigint
    from search.course_documents d join ref.countries c on c.id=d.country_id where trim(c.iso_alpha2) in('AU','NZ') group by 1
    union all
    select trim(c.iso_alpha2)::text,'scholarship',count(*) filter(where jsonb_array_length(coalesce(d.scholarship_options,'[]'::jsonb))>0)::bigint
    from search.course_documents d join ref.countries c on c.id=d.country_id where trim(c.iso_alpha2) in('AU','NZ') group by 1
  ), backlog as (
    select country_code,field_key,
      count(*) filter(where backlog_state='queueable')::bigint queueable_count,
      count(*) filter(where backlog_state='blocked')::bigint blocked_count,
      count(*) filter(where backlog_state='awaiting_source_profile_qualification')::bigint awaiting_count
    from pipeline.au_nz_enrichment_backlog_v1 group by country_code,field_key
  )
  insert into pipeline.enrichment_coverage_snapshots(snapshot_hour,country_code,field_key,covered_count,total_courses,queueable_count,blocked_count,awaiting_qualification_count,not_applicable_count)
  select v_hour,cv.country_code,cv.field_key,cv.covered_count,co.total_courses,coalesce(b.queueable_count,0),coalesce(b.blocked_count,0),coalesce(b.awaiting_count,0),0
  from coverage cv join countries co using(country_code) left join backlog b using(country_code,field_key)
  on conflict(snapshot_hour,country_code,field_key) do update set covered_count=excluded.covered_count,total_courses=excluded.total_courses,queueable_count=excluded.queueable_count,blocked_count=excluded.blocked_count,awaiting_qualification_count=excluded.awaiting_qualification_count,not_applicable_count=excluded.not_applicable_count,observed_at=now();
  get diagnostics v_rows=row_count;
  return jsonb_build_object('ok',true,'snapshot_hour',v_hour,'rows',v_rows,'change_control_ref','CF-CHG-20260915-245');
end $$;


ALTER FUNCTION "public"."svc_cf245_capture_coverage_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_cf245_refresh_hourly_admin_cache"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare
  v_rows integer:=0;
begin
  if current_user not in('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;

  delete from pipeline.layer2_enrichment_hourly_admin_cache_v1
  where hour_utc < date_trunc('hour',now())-interval '8 days';

  delete from pipeline.layer2_enrichment_hourly_admin_cache_v1
  where hour_utc >= date_trunc('hour',now())-interval '168 hours';

  insert into pipeline.layer2_enrichment_hourly_admin_cache_v1
  select *
  from pipeline.layer2_enrichment_hourly_v1
  where hour_utc >= date_trunc('hour',now())-interval '168 hours';

  get diagnostics v_rows=row_count;
  return jsonb_build_object(
    'ok',true,
    'rows',v_rows,
    'observed_at',now(),
    'change_control_ref','CF-CHG-20260915-245'
  );
end $$;


ALTER FUNCTION "public"."svc_cf245_refresh_hourly_admin_cache"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_cf245_replay_observed_coursefacts"("p_limit" integer DEFAULT 100, "p_apply" boolean DEFAULT false, "p_source_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'catalogue', 'ref', 'security'
    AS $$
declare
  v_limit integer:=least(greatest(coalesce(p_limit,100),1),500);
  v_intake_courses integer:=0;
  v_english_courses integer:=0;
  v_intake_rows integer:=0;
  v_english_rows integer:=0;
  v_fee_backlog integer:=0;
begin
  if current_user not in ('postgres','service_role') and coalesce(auth.role(),'')<>'service_role' then
    raise exception 'service_role required' using errcode='42501';
  end if;

  create temporary table if not exists pg_temp.cf245_replay_candidates(
    source_record_id uuid primary key,
    source_id uuid not null,
    evidence_id uuid not null,
    course_id uuid not null,
    provider_cricos text not null,
    course_cricos text not null,
    source_url text not null,
    parsed_payload jsonb not null,
    search_admitted boolean not null,
    intake_safe boolean not null,
    english_safe boolean not null,
    intake_missing_before boolean not null,
    english_missing_before boolean not null,
    fee_requires_layer3 boolean not null
  ) on commit drop;
  truncate pg_temp.cf245_replay_candidates;

  insert into pg_temp.cf245_replay_candidates
  with ranked as (
    select r.*,q.admitted_domains,q.metadata qualification_metadata,
           row_number() over(partition by r.source_id,r.course_cricos order by r.observed_at desc,r.id desc) rn
    from pipeline.course_fact_source_records r
    join pipeline.course_fact_source_qualifications q
      on q.source_id=r.source_id
     and upper(btrim(q.provider_cricos))=upper(btrim(r.provider_cricos))
     and q.qualification_status in ('qualified','bounded')
     and coalesce((q.metadata->>'apply_admitted')::boolean,false)
    where r.status='observed'
      and r.evidence_id is not null
      and (p_source_id is null or r.source_id=p_source_id)
      and coalesce((r.parsed_payload->>'identity_match')::boolean,false)
      and coalesce((r.parsed_payload->>'regulatory_code_seen')::boolean,false)
      and nullif(r.parsed_payload->>'course_id','') is not null
  ), resolved as (
    select r.*,(r.parsed_payload->>'course_id')::uuid course_id,
      exists(select 1 from catalogue.course_intakes ci where ci.course_id=(r.parsed_payload->>'course_id')::uuid and coalesce(ci.status,'active')='active') intake_exists,
      exists(select 1 from catalogue.course_english_requirements ce where ce.course_id=(r.parsed_payload->>'course_id')::uuid and coalesce(ce.status,'active')='active') english_exists,
      coalesce((r.qualification_metadata->>'search_admitted')::boolean,false) search_admitted
    from ranked r
    where r.rn=1
      and exists(
        select 1 from catalogue.courses c
        where c.id=(r.parsed_payload->>'course_id')::uuid
          and exists(select 1 from catalogue.course_registrations cr where cr.course_id=c.id and lower(cr.scheme)='cricos' and upper(btrim(cr.registration_code))=upper(btrim(r.course_cricos)))
          and exists(select 1 from catalogue.provider_registrations pr where pr.provider_id=c.provider_id and lower(pr.registration_scheme)='cricos' and upper(btrim(pr.registration_code))=upper(btrim(r.provider_cricos)) and coalesce(pr.status,'active') not in ('inactive','cancelled','archived'))
      )
      and not security.layer4_entity_or_parent_blocked('course',(r.parsed_payload->>'course_id')::uuid,'operational')
  )
  select id,source_id,evidence_id,course_id,provider_cricos,course_cricos,source_url,parsed_payload,search_admitted,
    coalesce(
      ('intake'=any(admitted_domains))
      and jsonb_typeof(coalesce(parsed_payload->'intakes','[]'::jsonb))='array'
      and exists(
        select 1 from jsonb_array_elements(coalesce(parsed_payload->'intakes','[]'::jsonb)) x(v)
        where jsonb_typeof(x.v)='string'
          and lower(trim(both '"' from x.v::text)) in ('january','february','march','april','may','june','july','august','september','october','november','december')
      ),false) as intake_safe,
    coalesce(('english_requirement'=any(admitted_domains)) and (
      nullif(parsed_payload->'english_requirements'->>'ielts_overall','')::numeric between 1 and 9
      or nullif(parsed_payload->'english_requirements'->>'pte_overall','')::numeric between 10 and 90
      or nullif(parsed_payload->'english_requirements'->>'toefl_overall','')::numeric between 1 and 120
    ),false) as english_safe,
    coalesce(not intake_exists,false),
    coalesce(not english_exists,false),
    coalesce(('international_fee'=any(admitted_domains))
      and coalesce((parsed_payload->>'fee_safe')::boolean,false)
      and nullif(parsed_payload->'provider_current_tuition'->>'amount','')::numeric>0
      and coalesce(parsed_payload->'provider_current_tuition'->>'basis','')='annual_or_indicative_requires_validation',false) as fee_requires_layer3
  from resolved
  where (not intake_exists or not english_exists or (
      ('international_fee'=any(admitted_domains))
      and coalesce((parsed_payload->>'fee_safe')::boolean,false)
      and parsed_payload->'provider_current_tuition' is not null
    ))
  order by (not intake_exists)::int+(not english_exists)::int desc, observed_at desc
  limit v_limit;

  select count(*) filter(where intake_safe and intake_missing_before),
         count(*) filter(where english_safe and english_missing_before),
         count(*) filter(where fee_requires_layer3)
    into v_intake_courses,v_english_courses,v_fee_backlog
  from pg_temp.cf245_replay_candidates;

  if not p_apply then
    return jsonb_build_object('apply',false,'selected_records',(select count(*) from pg_temp.cf245_replay_candidates),'intake_courses',v_intake_courses,'english_courses',v_english_courses,'fee_candidates_for_layer3',v_fee_backlog,'change_control_ref','CF-CHG-20260915-245');
  end if;

  with rows as (
    select c.*,initcap(lower(trim(both '"' from x.v::text))) intake_label
    from pg_temp.cf245_replay_candidates c
    cross join lateral jsonb_array_elements(coalesce(c.parsed_payload->'intakes','[]'::jsonb)) x(v)
    where c.intake_safe and c.intake_missing_before and jsonb_typeof(x.v)='string'
      and lower(trim(both '"' from x.v::text)) in ('january','february','march','april','may','june','july','august','september','october','november','december')
  ), ins as (
    insert into catalogue.course_intakes(course_id,intake_year,intake_label,start_date,application_deadline,campus_id,status,source_id,evidence_id,confidence,source_intake_key)
    select course_id,null,intake_label,null,null,null,'active',source_id,evidence_id,1,'cf245:'||lower(course_cricos)||':month:'||lower(intake_label)
    from rows
    on conflict(course_id,source_id,source_intake_key) where source_id is not null and source_intake_key is not null do nothing
    returning 1
  ) select count(*) into v_intake_rows from ins;

  with e as (
    select c.*,x.test_code,x.score
    from pg_temp.cf245_replay_candidates c
    cross join lateral (
      values
        ('IELTS'::text,nullif(c.parsed_payload->'english_requirements'->>'ielts_overall','')::numeric),
        ('PTE'::text,nullif(c.parsed_payload->'english_requirements'->>'pte_overall','')::numeric),
        ('TOEFL_IBT'::text,nullif(c.parsed_payload->'english_requirements'->>'toefl_overall','')::numeric)
    ) x(test_code,score)
    where c.english_safe and c.english_missing_before
      and ((x.test_code='IELTS' and x.score between 1 and 9) or (x.test_code='PTE' and x.score between 10 and 90) or (x.test_code='TOEFL_IBT' and x.score between 1 and 120))
  ), ins as (
    insert into catalogue.course_english_requirements(course_id,english_test_id,overall_score,component_scores,notes,source_id,evidence_id,confidence,source_requirement_key,status,valid_from,valid_to,last_verified_at)
    select e.course_id,t.id,e.score,'{}'::jsonb,'CF-245 deterministic replay from qualified first-party Evidence',e.source_id,e.evidence_id,1,'cf245:'||lower(e.course_cricos)||':'||lower(e.test_code),'active',null,null,now()
    from e join ref.english_tests t on t.code=e.test_code
    on conflict(course_id,english_test_id) do nothing
    returning 1
  ) select count(*) into v_english_rows from ins;

  insert into pipeline.layer2_field_admissions(source_record_id,course_id,source_id,evidence_id,field_key,status,reason_code,candidate_payload,canonical_changed,search_admission_eligible,change_control_ref,decided_at)
  select c.source_record_id,c.course_id,c.source_id,c.evidence_id,'intake_availability','admitted','deterministic_observed_replay',c.parsed_payload->'intakes',true,c.search_admitted,'CF-CHG-20260915-245',now()
  from pg_temp.cf245_replay_candidates c
  where c.intake_safe and c.intake_missing_before and exists(select 1 from catalogue.course_intakes ci where ci.course_id=c.course_id and ci.source_id=c.source_id and ci.evidence_id=c.evidence_id)
  on conflict(source_record_id,field_key) do nothing;

  insert into pipeline.layer2_field_admissions(source_record_id,course_id,source_id,evidence_id,field_key,status,reason_code,candidate_payload,canonical_changed,search_admission_eligible,change_control_ref,decided_at)
  select c.source_record_id,c.course_id,c.source_id,c.evidence_id,'english_requirements','admitted','deterministic_observed_replay',c.parsed_payload->'english_requirements',true,c.search_admitted,'CF-CHG-20260915-245',now()
  from pg_temp.cf245_replay_candidates c
  where c.english_safe and c.english_missing_before and exists(select 1 from catalogue.course_english_requirements ce where ce.course_id=c.course_id and ce.source_id=c.source_id and ce.evidence_id=c.evidence_id)
  on conflict(source_record_id,field_key) do nothing;

  return jsonb_build_object('apply',true,'selected_records',(select count(*) from pg_temp.cf245_replay_candidates),'intake_courses_targeted',v_intake_courses,'intake_rows_inserted',v_intake_rows,'english_courses_targeted',v_english_courses,'english_rows_inserted',v_english_rows,'fee_candidates_for_layer3',v_fee_backlog,'change_control_ref','CF-CHG-20260915-245');
end $$;


ALTER FUNCTION "public"."svc_cf245_replay_observed_coursefacts"("p_limit" integer, "p_apply" boolean, "p_source_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_cf245_run_tuition_benchmark"("p_case_limit" integer DEFAULT 4) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'net', 'public', 'extensions'
    AS $$
declare v_nonce uuid:=extensions.gen_random_uuid();v_request_id bigint;v_base text;
begin
  if current_user not in ('postgres','service_role') and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required' using errcode='42501'; end if;
  insert into pipeline.pilot_edge_nonces(id,function_name,expires_at) values(v_nonce,'layer3-cf245-tuition-benchmark',now()+interval '5 minutes');
  v_base:=public.coursefinder_runtime_edge_base_url();if v_base is null then raise exception 'runtime Edge base URL missing';end if;
  select net.http_post(url:=rtrim(v_base,'/')||'/layer3-cf245-tuition-benchmark',headers:=jsonb_build_object('content-type','application/json','x-cf-run-nonce',v_nonce::text),body:=jsonb_build_object('case_limit',least(greatest(coalesce(p_case_limit,4),3),6)),timeout_milliseconds:=120000) into v_request_id;
  return jsonb_build_object('request_id',v_request_id,'nonce',v_nonce,'case_limit',least(greatest(coalesce(p_case_limit,4),3),6));
end $$;


ALTER FUNCTION "public"."svc_cf245_run_tuition_benchmark"("p_case_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_cf245_run_tuition_benchmark"("p_case_limit" integer) IS 'CF-245 Pilot-only one-shot fee-specific Layer 3 benchmark dispatcher. Benchmark cannot mutate canonical fees; PASS only unpauses the dedicated validation profile.';



CREATE OR REPLACE FUNCTION "public"."svc_cf247_dispatch_layer3"("p_limit" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'net', 'public', 'extensions'
    AS $$
declare
  v_nonce uuid:=extensions.gen_random_uuid();
  v_request_id bigint;
  v_base text;
  v_limit integer:=least(greatest(coalesce(p_limit,10),1),25);
begin
  if current_user not in ('postgres','service_role')
     and coalesce(auth.role(),'')<>'service_role' then
    raise exception 'service_role required' using errcode='42501';
  end if;

  insert into pipeline.pilot_edge_nonces(id,function_name,expires_at)
  values(v_nonce,'layer3-work-dispatch',now()+interval '5 minutes');

  v_base:=public.coursefinder_runtime_edge_base_url();
  if v_base is null then raise exception 'runtime Edge base URL missing'; end if;

  select net.http_post(
    url:=rtrim(v_base,'/')||'/layer3-work-dispatch',
    headers:=jsonb_build_object(
      'content-type','application/json',
      'x-cf-run-nonce',v_nonce::text
    ),
    body:=jsonb_build_object(
      'limit',v_limit,
      'worker','cf247-manual-bounded'
    ),
    timeout_milliseconds:=120000
  ) into v_request_id;

  return jsonb_build_object(
    'request_id',v_request_id,
    'nonce',v_nonce,
    'limit',v_limit
  );
end $$;


ALTER FUNCTION "public"."svc_cf247_dispatch_layer3"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_companion_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  with pick as (
    select p.course_id from pipeline.course_companion_pages p
     where p.next_read_at <= now() and (p.leased_until is null or p.leased_until < now())
       and p.read_attempts < security.pipeline_num_v1('companion.max_attempts', 4)
       and p.status <> 'gone'
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.provider_id)  -- 22 Oct 2026 (Platform Admin 11:42): unpublished providers wait; publishing them again brings them back
     order by p.next_read_at
     limit greatest(1, least(coalesce(p_limit, 40), 200))  -- fixed: per-call safety cap; the run size is batch.companion_read
     for update skip locked),
  upd as (update pipeline.course_companion_pages p set leased_until = now() + interval '10 minutes', updated_at = now()  -- fixed: lease for one call
            from pick where p.course_id = pick.course_id returning p.*)
  select coalesce(jsonb_agg(jsonb_build_object('course_id', u.course_id, 'provider_id', u.provider_id, 'url', u.url, 'via', c.read_via, 'patterns', c.patterns,
           'code', co.course_code, 'country', (select k.iso_alpha2 from catalogue.providers pr join ref.countries k on k.id = pr.country_id where pr.id = u.provider_id))), '[]'::jsonb)
    into v
    from upd u join pipeline.uni_adapter_companions c on c.provider_id = u.provider_id join catalogue.courses co on co.id = u.course_id;
  return v;
end $$;


ALTER FUNCTION "public"."svc_companion_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_companion_record"("p_course_id" "uuid", "p_status" "text", "p_http" integer, "p_via" "text", "p_path" "text", "p_sha" "text", "p_values" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  update pipeline.course_companion_pages
     set status = case when p_status in ('due', 'read', 'blocked', 'failed', 'gone', 'waiting_scraper', 'too_thin') then p_status else 'failed' end,
         http_status = p_http, fetched_via = p_via, leased_until = null, updated_at = now(),
         storage_path = coalesce(p_path, storage_path), sha256 = coalesce(p_sha, sha256),
         "values" = case when p_status = 'read' then coalesce(p_values, '{}'::jsonb) else "values" end,
         read_at = case when p_status = 'read' then now() else read_at end,
         read_attempts = case when p_status = 'read' then 0 when p_status = 'waiting_scraper' then read_attempts else read_attempts + 1 end,
         next_read_at = case when p_status = 'read' then now() + make_interval(days => security.pipeline_num_v1('companion.reread_days', 60)::int)
                             else now() + make_interval(hours => security.pipeline_num_v1('companion.retry_hours', 12)::int) end
   where course_id = p_course_id;
  return p_status;
end $$;


ALTER FUNCTION "public"."svc_companion_record"("p_course_id" "uuid", "p_status" "text", "p_http" integer, "p_via" "text", "p_path" "text", "p_sha" "text", "p_values" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_course_description_check_v1"("p_course" "uuid", "p_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  return security.course_description_check_v1(p_course, p_value);
end $$;


ALTER FUNCTION "public"."svc_course_description_check_v1"("p_course" "uuid", "p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_course_link_search_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_person boolean := security.pipeline_num_v1('search.person_task_bypass', 1) >= 1;
        v_daycap int := security.pipeline_num_v1('search.daily_picked_cap', 100)::int; v_room int;
        v_course_stop int := security.pipeline_num_v1('search.stop_per_course_after', 6)::int; v_on boolean; v_cap numeric; v_used numeric; v_lim int := greatest(1, least(coalesce(p_limit, 40), 200)); v jsonb; v_stopped uuid[];
        -- CF-247 operating model 3.3.2: providers of an open on-demand request covering course search (pass 1), the scheduled room (pass 2)
        v_od uuid[]; v_sched int; v_pass int; v_take int; v_part jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select enabled, monthly_credit_cap into v_on, v_cap from pipeline.course_link_search_settings where id = 1;
  select coalesce(sum(units), 0) into v_used from pipeline.coverage_vendor_usage where purpose = 'course_link_search' and at >= date_trunc('month', now());
  if not coalesce(v_on, false) or v_used + 2 * v_lim > v_cap then return '[]'::jsonb; end if;
  -- v2.15.262: inside the day's Firecrawl share for course search, and not for universities whose search has stopped
  -- 13 Nov 2026 (operating model 3.3.2): the share and the daily cap below hold the scheduled pick (pass 2) only; an open on-demand request's
  -- providers are picked first (pass 1) up to the run size
  v_od := array(select distinct x from pipeline.on_demand_requests r, unnest(r.provider_ids) x
                 where r.state = 'open' and r.expires_at > now() and 'firecrawl' = any (r.toolsets)
                   and (r.purpose_groups is null or security.fc_purpose_group_v1('course_link_search') = any (r.purpose_groups)));
  v_sched := greatest(0, least(v_lim, floor(security.fc_budget_left_v1('course_link_search') / 2)::int));
  if v_sched < 1 and cardinality(v_od) = 0 then return '[]'::jsonb; end if;
  -- R2 (C-Q1): the day's picked-courses cap (UTC day); a person's running Find course pages task is counted but not held
  select v_daycap - count(*) into v_room from pipeline.course_link_search where sent_at >= (date_trunc('day', now() at time zone 'UTC') at time zone 'UTC');
  if v_room > 0 then v_sched := least(v_sched, v_room); end if;
  v_stopped := array(select x.provider_id from security.fc_search_stopped_v1() x);
  v := '[]'::jsonb;
  for v_pass in 1 .. 2 loop
  v_take := case v_pass when 1 then case when cardinality(v_od) > 0 then v_lim else 0 end else least(v_sched, v_lim - jsonb_array_length(v)) end;
  continue when v_take < 1;
  -- 22 Oct 2026 (Platform Admin 18:26): provider-level checks once per provider, not once per queued row (the run timed out)
  with prov as materialized (  -- materialized: worked out once, not folded back into every row
    select q.provider_id,
           security.enrich_focus_v1(q.provider_id) focus,
           security.site_few_course_pages_v1(q.provider_id) few,
           security.site_not_checked_v1(q.provider_id) unchecked,
           exists (select 1 from pipeline.provider_onboarding o
                    where o.provider_id = q.provider_id and o.source in ('backfill', 'new_provider')
                      and not exists (select 1 from pipeline.firecrawl_search_resumes r where r.provider_id = q.provider_id and r.resumed_at > o.created_at)) bulk,
           coalesce(security.coverage_country(q.provider_id) in (select jsonb_array_elements_text(sp.value) from pipeline.platform_toolset_settings sp
                                                                  where sp.toolset_key = 'pipeline' and sp.key = 'search.priority_countries'), false) prio,
           security.fc_provider_tier_v1(q.provider_id) tier, rc.search_domain,
           (q.provider_id = any (v_stopped)) stopped  -- 24 Oct 2026 (hotfix D2): kept as a flag; the row check below decides
      from (select distinct s0.provider_id from pipeline.course_link_search s0 where s0.state = 'queued') q
      join pipeline.course_link_recipes rc on rc.provider_id = q.provider_id and rc.active
     where not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = q.provider_id)  -- v2.15.237: paused while the provider is unpublished or archived
       -- v2.15.255: while Firecrawl is for target universities only, take only their searches
       and (not coalesce((security.firecrawl_setting('target_only') #>> '{}')::boolean, true) or q.provider_id = any (v_od)
            or exists (select 1 from pipeline.firecrawl_target_cache tc where tc.provider_id = q.provider_id and tc.included))
       -- v2.15.265: never a search limited to a directory site
       and not security.third_party_host_v1('https://' || rc.search_domain)
       -- 21 Oct 2026: providers with no course pages to find are not searched (search.skip_providers)
       and not exists (select 1 from catalogue.providers px, pipeline.platform_toolset_settings sk
                        where px.id = q.provider_id and sk.toolset_key = 'pipeline' and sk.key = 'search.skip_providers' and sk.value ? px.stable_key)),
  pick as (
    select s.course_id, s.provider_id, s.stage, c.course_code, c.canonical_title, pv.search_domain
      from pipeline.course_link_search s join prov pv on pv.provider_id = s.provider_id
      join catalogue.courses c on c.id = s.course_id
      left join pipeline.provider_priority pp on pp.provider_id = s.provider_id
     where s.state = 'queued'
       and security.search_stop_gate_v1(s.provider_id, s.course_id, pv.stopped) is null  -- S1: the one stop gate (university stop with the person bypass, per-course stop)
       and (case when v_pass = 1 then s.provider_id = any (v_od)
                 else not (s.provider_id = any (v_od)) and (v_room > 0 or (v_person and security.link_search_person_task_v1(s.provider_id, s.course_id))) end)  -- R2: the daily cap
       and (v_pass = 1 or pv.focus or s.requested_at is not null)  -- CF-247 15 Oct: focus providers only; 18 Oct: a search a person asked for runs for any provider
       -- 22 Oct 2026 (NZ review fixes 1 and 2, Platform Admin 13:28 fix 1): unless a person asked: not where the site lists too few course
       -- pages, not before the site is checked, and for universities the site list first
       and case when s.requested_at is not null and (not pv.bulk or (v_person and security.link_search_person_task_v1(s.provider_id, s.course_id))) then true
                when pv.few or pv.unchecked then false
                else security.site_list_match_done_v1(s.course_id, s.provider_id) end
     -- v2.15.265: top-50, Australian 30+ courses, overseas, small providers; CRICOS-code searches first within each
     -- 21 Oct 2026 (Platform Admin "Keep 13,000, fix order only"): priority countries first (search.priority_countries)
     order by (s.requested_at is null), s.requested_at, pv.prio desc, pv.tier, (s.stage <> 'cricos'), coalesce(pp.rank, 100000),
              md5(s.course_id::text || to_char(now(), 'YYYYMMDDHH24MI'))
     limit v_take
     for update of s skip locked),
  upd as (
    update pipeline.course_link_search s set state = 'sent', sent_at = now(), req_id = null,
           query = case p.stage when 'cricos' then '"' || p.course_code || '" site:' || p.search_domain
                                else case when security.coverage_country(p.provider_id) = 'CA'
                                     then trim(regexp_replace(regexp_replace(regexp_replace(p.canonical_title, '\s*\([^)]*\)', ' ', 'g'), '\s+-\s+(UBCV|UBCO|Major|Honours|Open Learning)\M.*$', '', 'i'), '[:"]+', ' ', 'g')) || ' site:' || p.search_domain
                                     else '"' || replace(regexp_replace(p.canonical_title, '\s*\(\s*Level\s+\d{1,2}\s*\)\s*$', '', 'i'), '"', '') || '" site:' || p.search_domain end end
      from pick p where s.course_id = p.course_id
    returning s.course_id, s.provider_id, s.stage, s.query)
  select coalesce(jsonb_agg(jsonb_build_object('course_id', course_id, 'provider_id', provider_id, 'stage', stage, 'query', query)), '[]'::jsonb) into v_part from upd;
  v := v || v_part;
  end loop;
  return v;
end $_$;


ALTER FUNCTION "public"."svc_course_link_search_next"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_course_link_search_next"("p_limit" integer) IS 'Course page searches to send: pass 1 the providers of an open on-demand request covering course search (operating model 3.3.2, no share or daily cap), pass 2 the scheduled pick (day share, daily picked cap, focus, target list). Policies hold in both.';



CREATE OR REPLACE FUNCTION "public"."svc_course_link_search_prior_v1"("p_queries" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  return (select coalesce(jsonb_object_agg(z.k, z.results), '{}'::jsonb) from (
    select distinct on (k) k, s.results
      from pipeline.course_link_search s
      cross join lateral (select lower(btrim(regexp_replace(normalize(coalesce(s.query, ''), NFKC), '\s+', ' ', 'g'))) k) n
     where n.k = any (p_queries) and n.k <> '' and s.state <> 'sent' and jsonb_typeof(s.results) = 'array'
       and s.sent_at >= now() - make_interval(hours => security.pipeline_num_v1('ops_cost.repeat_search_hours', 24)::int)
     order by k, s.sent_at desc) z);
end $$;


ALTER FUNCTION "public"."svc_course_link_search_prior_v1"("p_queries" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_course_link_search_record"("p_course_id" "uuid", "p_http" integer, "p_urls" "text"[], "p_error" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.course_link_search%rowtype; v_c text[];
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into r from pipeline.course_link_search where course_id = p_course_id and state = 'sent' for update;
  if r.course_id is null then return 'not_sent'; end if;
  -- the worker ran out of time or credits before searching: back in the queue, no attempt counted
  if p_error in ('time budget', 'credit budget') then
    update pipeline.course_link_search set state = 'queued' where course_id = p_course_id;
    return 'requeued';
  end if;
  if p_http = 200 then
    v_c := security.course_link_pick_v1(r.provider_id, coalesce(p_urls, '{}'));
    -- S1: a page rejected or blocked for this course is never taken from a search result
    v_c := coalesce(array(select t.u from unnest(v_c) with ordinality t(u, o) where not security.page_refused_v1(p_course_id, t.u) order by t.o), '{}');
    if cardinality(v_c) > 0 then
      update pipeline.course_link_search set state = 'found', results = to_jsonb(p_urls), candidates = to_jsonb(v_c), cand_idx = 1,
             bound_url = v_c[1], done_at = now() where course_id = p_course_id;
      perform security.course_link_bind_v1(p_course_id, r.provider_id, v_c[1], case r.stage when 'cricos' then 'cricos_search' else 'title_search' end);
      return 'found';
    elsif r.stage = 'cricos' then
      update pipeline.course_link_search set stage = 'title', state = 'queued', results = to_jsonb(p_urls), attempts = 0 where course_id = p_course_id;
      return 'title_next';
    else
      update pipeline.course_link_search set state = 'none', results = to_jsonb(p_urls), done_at = now() where course_id = p_course_id;
      return 'none';
    end if;
  end if;
  update pipeline.course_link_search set attempts = attempts + 1, state = case when attempts + 1 >= 3 then 'error' else 'queued' end,
         results = jsonb_build_object('http_status', p_http, 'body', left(coalesce(p_error, ''), 300))
   where course_id = p_course_id;
  return 'failed';
end $$;


ALTER FUNCTION "public"."svc_course_link_search_record"("p_course_id" "uuid", "p_http" integer, "p_urls" "text"[], "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_course_list_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  with pick as (
    select l.id from pipeline.provider_course_lists l
     where l.status <> 'stopped' and l.next_read_at <= now() and (l.leased_until is null or l.leased_until < now())
       and l.read_attempts < security.pipeline_num_v1('course_list.max_attempts', 4)
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = l.provider_id)  -- unpublished providers wait
     order by l.next_read_at
     limit greatest(1, least(coalesce(p_limit, 5), 50))  -- fixed: per-call safety cap; the run size is batch.course_list_read
     for update skip locked),
  upd as (update pipeline.provider_course_lists l set leased_until = now() + interval '10 minutes', updated_at = now()  -- fixed: lease for one call
            from pick where l.id = pick.id returning l.*)
  select coalesce(jsonb_agg(jsonb_build_object('id', u.id, 'provider_id', u.provider_id, 'url', u.url,
           'max_pages', security.pipeline_num_v1('course_list.max_pages', 10)::int, 'min_links', security.pipeline_num_v1('course_list.min_links', 20)::int, 'link_pattern', u.link_pattern, 'child_pattern', u.child_pattern, 'read_via', u.read_via)), '[]'::jsonb)
    into v from upd u;
  return v;
end $$;


ALTER FUNCTION "public"."svc_course_list_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_course_list_record"("p_id" "uuid", "p_status" "text", "p_http" integer, "p_via" "text", "p_links" "jsonb", "p_pages" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare l pipeline.provider_course_lists%rowtype; v_new int := 0; v_n int := 0;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into l from pipeline.provider_course_lists where id = p_id for update;
  if l.id is null then return jsonb_build_object('error', 'unknown course list'); end if;
  if p_status = 'read' then
    v_n := coalesce(jsonb_array_length(p_links), 0);
    with ins as (
      insert into pipeline.coverage_provider_urls(provider_id, url, title, tokens, title_tokens, source)
      select l.provider_id, left(e->>'url', 1000), left(e->>'title', 300), security.coverage_text_tokens(security.coverage_slug(e->>'url')),
             security.coverage_text_tokens(regexp_replace(coalesce(e->>'title', ''), '\s[|–—]\s.*$', '')), 'course_list'
        from jsonb_array_elements(coalesce(p_links, '[]'::jsonb)) e where coalesce(e->>'url', '') ~ '^https?://'
      on conflict (provider_id, url) do update set last_seen_at = now(),
             title = coalesce(nullif(pipeline.coverage_provider_urls.title, ''), excluded.title),
             title_tokens = case when cardinality(pipeline.coverage_provider_urls.title_tokens) = 0 then excluded.title_tokens else pipeline.coverage_provider_urls.title_tokens end
      returning (xmax = 0) inserted)
    select count(*) filter (where inserted) into v_new from ins;
  end if;
  update pipeline.provider_course_lists set
         status = case when p_status in ('read', 'failed', 'blocked', 'gone', 'due') then p_status else 'failed' end,
         http_status = p_http, fetched_via = p_via, leased_until = null, updated_at = now(), pages_read = coalesce(p_pages, 0),
         links_found = case when p_status = 'read' then v_n else links_found end, links_new = case when p_status = 'read' then v_new else links_new end,
         read_at = case when p_status = 'read' then now() else read_at end,
         read_attempts = case when p_status = 'read' then 0 when p_status = 'due' then read_attempts else read_attempts + 1 end,
         next_read_at = case when p_status = 'read' then now() + make_interval(days => security.pipeline_num_v1('course_list.reread_days', 7)::int)
                             when p_status = 'due' then now()
                             else now() + make_interval(hours => security.pipeline_num_v1('course_list.retry_hours', 12)::int) end
   where id = p_id;
  return jsonb_build_object('links', v_n, 'new', v_new);
end $_$;


ALTER FUNCTION "public"."svc_course_list_record"("p_id" "uuid", "p_status" "text", "p_http" integer, "p_via" "text", "p_links" "jsonb", "p_pages" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_coursefacts_apply_record"("p_source_id" "uuid", "p_evidence_id" "uuid", "p_provider_cricos" "text", "p_course_cricos" "text", "p_source_record_id" "text", "p_source_url" "text", "p_content_hash" "text", "p_payload" "jsonb", "p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
 v_provider uuid;v_course uuid;v_record uuid;v_test uuid;r jsonb;
 v_fee_year int;v_amount numeric;v_currency text;v_basis text;v_fee_key text;v_audience text;
 v_links int:=0;v_fees int:=0;v_intakes int:=0;v_english int:=0;
begin
 if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required';end if;
 select pr.provider_id into v_provider from catalogue.provider_registrations pr join catalogue.providers p on p.id=pr.provider_id join ref.countries c on c.id=p.country_id where c.iso_alpha2='AU' and lower(pr.registration_scheme)='cricos' and upper(btrim(pr.registration_code))=upper(btrim(p_provider_cricos)) and coalesce(pr.status,'active') not in ('inactive','cancelled','archived') order by pr.checked_at desc nulls last limit 1;
 if v_provider is null then raise exception 'provider CRICOS not resolved';end if;
 select cr.course_id into v_course from catalogue.course_registrations cr join catalogue.courses c on c.id=cr.course_id where c.provider_id=v_provider and lower(cr.scheme)='cricos' and upper(btrim(cr.registration_code))=upper(btrim(p_course_cricos)) limit 1;
 if v_course is null then raise exception 'course CRICOS not resolved';end if;
 if p_apply and security.layer4_entity_or_parent_blocked('course',v_course,'operational') then raise exception 'course operationally blocked by Layer 4' using errcode='42501'; end if;
 if coalesce(btrim(p_source_record_id),'')='' or coalesce(btrim(p_source_url),'')='' or coalesce(btrim(p_content_hash),'')='' then raise exception 'source identity/evidence fields required';end if;
 if not exists(select 1 from pipeline.course_fact_source_qualifications q where q.source_id=p_source_id and q.provider_cricos=upper(btrim(p_provider_cricos)) and q.qualification_status in ('qualified','bounded')) then raise exception 'source not qualified for AU course facts';end if;
 if not p_apply then return jsonb_build_object('resolved',true,'provider_id',v_provider,'course_id',v_course,'would_apply_link',nullif(btrim(p_payload->>'course_url'),'') is not null,'would_apply_fee',p_payload ? 'fee_amount','would_apply_intakes',coalesce(jsonb_array_length(coalesce(p_payload->'intakes','[]'::jsonb)),0),'would_apply_english',coalesce(jsonb_array_length(coalesce(p_payload->'english_requirements','[]'::jsonb)),0));end if;
 insert into pipeline.course_fact_source_records(source_id,source_record_id,source_url,provider_cricos,course_cricos,content_hash,evidence_id,parsed_payload,status,observed_at)
 values(p_source_id,p_source_record_id,p_source_url,upper(btrim(p_provider_cricos)),upper(btrim(p_course_cricos)),p_content_hash,p_evidence_id,p_payload,'observed',now())
 on conflict(source_id,source_record_id,content_hash) do update set evidence_id=coalesce(excluded.evidence_id,pipeline.course_fact_source_records.evidence_id),parsed_payload=excluded.parsed_payload,observed_at=now(),error_text=null returning id into v_record;
 if nullif(btrim(p_payload->>'course_url'),'') is not null then
   insert into catalogue.course_links(course_id,link_type,url,audience,label,is_primary,status,source_id,evidence_id,confidence,last_verified_at,updated_at)
   values(v_course,coalesce(nullif(btrim(p_payload->>'link_type'),''),'official_course'),btrim(p_payload->>'course_url'),coalesce(nullif(btrim(p_payload->>'audience'),''),'international'),'Official provider course page',false,'active',p_source_id,p_evidence_id,1,now(),now())
   on conflict(course_id,link_type,url) do update set audience=excluded.audience,label=excluded.label,status='active',source_id=excluded.source_id,evidence_id=excluded.evidence_id,confidence=1,last_verified_at=now(),updated_at=now();
   v_links:=1;
 end if;
 if p_payload ? 'fee_amount' then
   v_fee_year:=nullif(p_payload->>'fee_year','')::int;v_amount:=nullif(p_payload->>'fee_amount','')::numeric;v_currency:=coalesce(nullif(btrim(p_payload->>'currency_code'),''),'AUD');v_basis:=nullif(btrim(p_payload->>'fee_basis'),'');v_audience:=coalesce(nullif(btrim(p_payload->>'audience'),''),'international');v_fee_key:=coalesce(nullif(btrim(p_payload->>'fee_key'),''),lower(upper(btrim(p_course_cricos))||':'||v_audience||':'||coalesce(v_fee_year::text,'current')||':'||coalesce(v_basis,'tuition')));
   if v_amount is null or v_amount<=0 then raise exception 'positive fee amount required';end if;
   if not exists(select 1 from ref.currencies where code=v_currency) then raise exception 'currency not seeded: %',v_currency;end if;
   insert into catalogue.course_fees(course_id,fee_year,audience,fee_type,amount,currency_code,basis,notes,source_id,evidence_id,confidence,campus_id,source_fee_key,status,last_verified_at,source_snapshot_at,updated_at)
   values(v_course,v_fee_year,v_audience,'provider_current_tuition',v_amount,v_currency,v_basis,p_payload->>'fee_notes',p_source_id,p_evidence_id,1,null,v_fee_key,'active',now(),now(),now())
   on conflict(course_id,source_id,source_fee_key) where source_id is not null and source_fee_key is not null do update set fee_year=excluded.fee_year,audience=excluded.audience,fee_type=excluded.fee_type,amount=excluded.amount,currency_code=excluded.currency_code,basis=excluded.basis,notes=excluded.notes,evidence_id=excluded.evidence_id,confidence=1,status='active',last_verified_at=now(),source_snapshot_at=now(),updated_at=now();
   v_fees:=1;
 end if;
 for r in select value from jsonb_array_elements(coalesce(p_payload->'intakes','[]'::jsonb)) loop
   if nullif(btrim(r->>'intake_label'),'') is null then raise exception 'intake_label required';end if;
   insert into catalogue.course_intakes as ci(course_id,intake_year,intake_label,start_date,application_deadline,campus_id,status,source_id,evidence_id,confidence,source_intake_key)
   values(v_course,nullif(r->>'intake_year','')::int,r->>'intake_label',nullif(r->>'start_date','')::date,nullif(r->>'application_deadline','')::date,null,coalesce(nullif(r->>'status',''),'active'),p_source_id,p_evidence_id,1,coalesce(nullif(r->>'source_intake_key',''),lower(upper(btrim(p_course_cricos))||':'||coalesce((r->>'intake_year'),'current')||':'||(r->>'intake_label'))))
   on conflict(course_id,source_id,source_intake_key) where source_id is not null and source_intake_key is not null do update set intake_year=case when excluded.intake_year is null or excluded.intake_year<ci.intake_year then ci.intake_year else excluded.intake_year end,intake_label=excluded.intake_label,
     start_date=case when excluded.intake_year>ci.intake_year then excluded.start_date when excluded.intake_year<ci.intake_year then ci.start_date else coalesce(excluded.start_date,ci.start_date) end,
     application_deadline=case when excluded.intake_year>ci.intake_year then excluded.application_deadline when excluded.intake_year<ci.intake_year then ci.application_deadline else coalesce(excluded.application_deadline,ci.application_deadline) end,
     status=excluded.status,evidence_id=excluded.evidence_id,confidence=1;
   v_intakes:=v_intakes+1;
 end loop;
 for r in select value from jsonb_array_elements(coalesce(p_payload->'english_requirements','[]'::jsonb)) loop
   select id into v_test from ref.english_tests where code=upper(btrim(r->>'test_code')) limit 1;
   if v_test is null then raise exception 'english test not seeded: %',r->>'test_code';end if;
   insert into catalogue.course_english_requirements(course_id,english_test_id,overall_score,component_scores,notes,source_id,evidence_id,confidence,source_requirement_key,status,valid_from,valid_to,last_verified_at)
   values(v_course,v_test,nullif(r->>'overall_score','')::numeric,coalesce(r->'component_scores','{}'::jsonb),r->>'notes',p_source_id,p_evidence_id,1,coalesce(nullif(r->>'source_requirement_key',''),lower(upper(btrim(p_course_cricos))||':'||upper(btrim(r->>'test_code')))),coalesce(nullif(r->>'status',''),'active'),nullif(r->>'valid_from','')::date,nullif(r->>'valid_to','')::date,now())
   on conflict(course_id,english_test_id) do update set overall_score=excluded.overall_score,component_scores=excluded.component_scores,notes=excluded.notes,source_id=excluded.source_id,evidence_id=excluded.evidence_id,confidence=1,source_requirement_key=excluded.source_requirement_key,status=excluded.status,valid_from=excluded.valid_from,valid_to=excluded.valid_to,last_verified_at=now();
   v_english:=v_english+1;
 end loop;
 update pipeline.course_fact_source_records set status='applied',applied_at=now() where id=v_record;
 return jsonb_build_object('resolved',true,'provider_id',v_provider,'course_id',v_course,'links_applied',v_links,'fees_applied',v_fees,'intakes_applied',v_intakes,'english_applied',v_english,'source_record_id',v_record);
end $$;


ALTER FUNCTION "public"."svc_coursefacts_apply_record"("p_source_id" "uuid", "p_evidence_id" "uuid", "p_provider_cricos" "text", "p_course_cricos" "text", "p_source_record_id" "text", "p_source_url" "text", "p_content_hash" "text", "p_payload" "jsonb", "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_coursefacts_register_evidence"("p_source_id" "uuid", "p_source_url" "text", "p_storage_path" "text", "p_content_hash" "text", "p_mime_type" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pipeline'
    AS $$
declare v_id uuid;begin
 if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required';end if;
 insert into pipeline.evidence_artifacts(source_id,evidence_type,source_url,storage_path,content_hash,mime_type,metadata)
 values(p_source_id,'source_snapshot',p_source_url,p_storage_path,p_content_hash,p_mime_type,coalesce(p_metadata,'{}'::jsonb)) returning id into v_id;
 return v_id;end $$;


