CREATE OR REPLACE FUNCTION "public"."svc_coverage_read_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline'
    AS $$
declare v jsonb;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  with due as (
    select p.course_id, p.provider_id, p.status st, coalesce(pp.rank,100000) prank, coalesce(cp.sort,1000000) csort, row_number() over (partition by p.provider_id order by (p.status<>'bound'), p.next_read_at) rk
      from pipeline.coverage_course_pages p left join pipeline.provider_priority pp on pp.provider_id=p.provider_id left join pipeline.course_priority cp on cp.course_id=p.course_id
     where p.status in ('bound','ambiguous') and coalesce(p.next_read_at,now())<=now() and coalesce(p.leased_until,'-infinity')<now() and p.read_attempts<3
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.provider_id)),  -- v2.15.237: paused while the provider is unpublished or archived
  pick as (select course_id from due where rk<=20 order by csort, least(prank,101), (st<>'bound'), rk, random() limit greatest(1,least(coalesce(p_limit,20),200))),
  upd as (update pipeline.coverage_course_pages p set leased_until=now()+interval '10 minutes', read_attempts=p.read_attempts+1
            from pick where p.course_id=pick.course_id and coalesce(p.leased_until,'-infinity')<now()  -- W30: re-checked on the locked row; one claim per page
            returning p.course_id, p.provider_id, p.url, p.status, p.basis, p.read_status)
  select coalesce(jsonb_agg(jsonb_build_object('course_id',u.course_id,'provider_id',u.provider_id,'url',u.url,'title',c.canonical_title,'code',c.course_code,'country',security.coverage_country(u.provider_id),'status',u.status,'basis',u.basis,'render_ok',(u.read_status in ('needs_render','blocked') and security.render_country_v1(u.provider_id)),'manual',coalesce(u.basis='manual',false),'direct_only',exists (select 1 from pipeline.page_reread_pilot rr where rr.course_id=u.course_id and rr.outcome_at is null),'rendered_before',(exists (select 1 from pipeline.coverage_course_pages q where q.course_id=u.course_id and q.fetched_via='firecrawl') or exists (select 1 from pipeline.page_link_repairs x where x.course_id=u.course_id and x.reason like 'university adapter: international view read%')),'priority',coalesce((select pp.rank<=100 from pipeline.provider_priority pp where pp.provider_id=u.provider_id),false) or exists (select 1 from pipeline.course_priority cp where cp.course_id=u.course_id))),'[]'::jsonb)
    into v from upd u join catalogue.courses c on c.id=u.course_id;
  return v;
end $$;


ALTER FUNCTION "public"."svc_coverage_read_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_coverage_read_record"("p_course_id" "uuid", "p_read_status" "text", "p_http_status" integer, "p_fetched_via" "text", "p_identity_basis" "text", "p_storage_path" "text", "p_sha256" "text", "p_candidates" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'security'
    AS $_$
declare v_row pipeline.coverage_course_pages%rowtype; v_ev uuid; v_src uuid;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  select * into v_row from pipeline.coverage_course_pages where course_id=p_course_id;
  if v_row.course_id is null then raise exception 'course page not bound'; end if;
  -- night run: a page read and confirmed before keeps its reading when a later read fails for a passing reason
  if p_read_status in ('fetch_failed', 'blocked', 'needs_render', 'too_thin', 'not_html') and v_row.read_status = 'read' and v_row.identity_basis is not null and v_row.evidence_id is not null then
    update pipeline.coverage_course_pages set http_status = p_http_status, leased_until = null, next_read_at = case when p_read_status = 'needs_render' then date_trunc('month', now()) + interval '1 month 1 hour' else now() + make_interval(days => security.pipeline_num_v1('retry.course_page_http_failed_days', 7)::int) end where course_id = p_course_id; -- fixed: month roll-over for pages that need a browser
    return jsonb_build_object('evidence_id', null, 'kept_previous_read', true, 'failed_as', p_read_status);
  end if;
  if p_storage_path is not null and p_sha256 ~ '^[0-9a-f]{64}$' then
    v_src:=security.coverage_sweep_source(v_row.provider_id);
    select id into v_ev from pipeline.evidence_artifacts where source_id=v_src and content_hash=p_sha256 and source_url=v_row.url limit 1;
    if v_ev is null then
      v_ev:=public.svc_coursefacts_register_evidence(v_src, v_row.url, p_storage_path, p_sha256, 'text/html',
        jsonb_build_object('layer',2,'kind','provider_course_page','worker','coverage-sweep','course_id',p_course_id,'identity_basis',p_identity_basis,'fetched_via',p_fetched_via,'gzip',true) || case when p_http_status is not null then jsonb_build_object('page_status', p_http_status) else '{}'::jsonb end || case when coalesce(p_candidates->>'text_sha', '') ~ '^[0-9a-f]{64}$' then jsonb_build_object('text_sha', p_candidates->>'text_sha') else '{}'::jsonb end);  -- 19 Oct 2026: text hash for unchanged-page reuse
    end if;
  end if;
  update pipeline.coverage_course_pages set read_status=p_read_status, read_at=now(), http_status=p_http_status, fetched_via=p_fetched_via,
         identity_basis=p_identity_basis, evidence_id=coalesce(v_ev,evidence_id), candidates=p_candidates, leased_until=null,
         next_read_at=case when p_read_status in ('read','identity_mismatch') then now()+make_interval(days => coalesce((select a.read_cycle_days from pipeline.uni_adapters a where a.provider_id=v_row.provider_id), security.pipeline_num_v1('reread.course_page_default_days', 90)::int)) when p_read_status='needs_render' and security.render_country_v1(v_row.provider_id) then now()+make_interval(hours => security.pipeline_num_v1('retry.course_page_render_hours', 24)::int) when p_read_status='needs_render' then date_trunc('month',now())+interval '1 month 1 hour' else now()+make_interval(hours => security.pipeline_num_v1('retry.course_page_failed_hours', 6)::int) end, -- fixed: month roll-over
         read_attempts=case when p_read_status='needs_render' then greatest(read_attempts-1,0) else read_attempts end,
         status=case when p_read_status='identity_mismatch' then 'mismatch' when status='ambiguous' and p_identity_basis='cricos_code' and security.coverage_identity_allowed(provider_id, 'cricos_code', 'official_url') then 'bound' else status end,
         basis=case when status='ambiguous' and p_identity_basis='cricos_code' and security.coverage_identity_allowed(provider_id, 'cricos_code', 'official_url') then 'cricos_code_on_page' else basis end
   where course_id=p_course_id;
  return jsonb_build_object('evidence_id',v_ev);
end $_$;


ALTER FUNCTION "public"."svc_coverage_read_record"("p_course_id" "uuid", "p_read_status" "text", "p_http_status" integer, "p_fetched_via" "text", "p_identity_basis" "text", "p_storage_path" "text", "p_sha256" "text", "p_candidates" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_coverage_read_record"("p_course_id" "uuid", "p_read_status" "text", "p_http_status" integer, "p_fetched_via" "text", "p_identity_basis" "text", "p_storage_path" "text", "p_sha256" "text", "p_candidates" "jsonb") IS 'Records one course-page read by worker coverage-sweep. A stored copy is registered as evidence with its identity basis, fetch route, text hash and (CF-247 R7, 14 Nov 2026) the page''s own status as metadata.page_status.';



CREATE OR REPLACE FUNCTION "public"."svc_coverage_reextract_next"("p_limit" integer, "p_version" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline'
    AS $$
declare v jsonb;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('course_id',cp.course_id,'storage_path',e.storage_path,'title',c.canonical_title,'code',c.course_code,'status',cp.status,'url',cp.url,'country',security.coverage_country(cp.provider_id))),'[]'::jsonb)
    into v
    from (select * from pipeline.coverage_course_pages cp0
           where cp0.read_status='read' and cp0.identity_basis is not null and cp0.evidence_id is not null
             and coalesce(cp0.candidates->>'extractor','')<>p_version
             and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = cp0.provider_id)  -- v2.15.237: paused while the provider is unpublished or archived
           order by exists (select 1 from pipeline.layer4_review_items r4 where r4.entity_id = cp0.course_id and r4.status = 'pending'
                          and r4.field_code = 'provider_current_tuition_validation') desc, cp0.read_at limit greatest(1,least(coalesce(p_limit,50),200))) cp
    join pipeline.evidence_artifacts e on e.id=cp.evidence_id join catalogue.courses c on c.id=cp.course_id;
  return v;
end $$;


ALTER FUNCTION "public"."svc_coverage_reextract_next"("p_limit" integer, "p_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_coverage_reidentify_next"("p_limit" integer, "p_rule" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security'
    AS $$
declare v jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v from (
    select p.course_id, p.evidence_id, e.storage_path, coalesce(nullif(p.candidates->>'final_url', ''), p.url) url, co.canonical_title title, co.course_code code,
           security.coverage_country(p.provider_id) country
      from pipeline.coverage_course_pages p
      join pipeline.evidence_artifacts e on e.id = p.evidence_id
      join catalogue.courses co on co.id = p.course_id and co.lifecycle_status = 'active'
     where p.status = 'mismatch' and p.read_status = 'identity_mismatch' and coalesce(p.basis, '') <> 'manual' and e.storage_path is not null
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.provider_id)  -- v2.15.237: paused while the provider is unpublished or archived
       and not exists (select 1 from pipeline.coverage_reidentify_done d where d.course_id = p.course_id and d.evidence_id = p.evidence_id and d.rule = p_rule)
          and not security.page_refused_v1(p.course_id, p.url) /* 24 Oct 2026; S1: a rejected or blocked page is never re-bound */
     order by p.course_id limit greatest(1, least(coalesce(p_limit, 100), 400)) for update of p skip locked) x;
  return v;
end $$;


ALTER FUNCTION "public"."svc_coverage_reidentify_next"("p_limit" integer, "p_rule" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_coverage_reidentify_record"("p_course_id" "uuid", "p_evidence_id" "uuid", "p_rule" "text", "p_identity_basis" "text", "p_candidates" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_n int := 0;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  insert into pipeline.coverage_reidentify_done(course_id, evidence_id, rule, identity_basis) values (p_course_id, p_evidence_id, p_rule, p_identity_basis)
  on conflict (course_id, evidence_id, rule) do nothing;
  if p_identity_basis is not null then
    update pipeline.coverage_course_pages set status = 'bound', read_status = 'read', identity_basis = p_identity_basis, candidates = p_candidates, leased_until = null
     where course_id = p_course_id and evidence_id = p_evidence_id and status = 'mismatch' and coalesce(basis, '') <> 'manual';
    get diagnostics v_n = row_count;
  end if;
  return case when v_n > 0 then 'passed' when p_identity_basis is not null then 'changed' else 'still_mismatch' end;
end $$;


ALTER FUNCTION "public"."svc_coverage_reidentify_record"("p_course_id" "uuid", "p_evidence_id" "uuid", "p_rule" "text", "p_identity_basis" "text", "p_candidates" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_coverage_site_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline'
    AS $$
declare v jsonb;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  with pick as (
    select d.provider_id from pipeline.coverage_provider_discovery d
     where d.status='no_website' and coalesce(d.site_searched_at,'-infinity')<now()-make_interval(days => security.pipeline_num_v1('retry.no_website_days', 30)::int) and coalesce(d.leased_until,'-infinity')<now()
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = d.provider_id)  -- v2.15.237: paused while the provider is unpublished or archived
     order by (d.requested_at is null), d.requested_at, (select count(*) from catalogue.courses c where c.provider_id=d.provider_id and c.lifecycle_status='active') desc
     limit greatest(1,least(coalesce(p_limit,5),20)) for update skip locked),
  upd as (update pipeline.coverage_provider_discovery d set leased_until=now()+interval '10 minutes' from pick where d.provider_id=pick.provider_id returning d.provider_id)
  select coalesce(jsonb_agg(jsonb_build_object('provider_id',u.provider_id,'name',coalesce(p.display_name,p.canonical_name),'trading',p.short_name,
           'cricos',(select min(upper(pr.registration_code)) from catalogue.provider_registrations pr where pr.provider_id=u.provider_id and lower(pr.registration_scheme)='cricos'),'country',security.coverage_country(u.provider_id),
           'dli',(select min(upper(pr.registration_code)) from catalogue.provider_registrations pr where pr.provider_id=u.provider_id and lower(pr.registration_scheme)='ircc_dli'))),'[]'::jsonb)
    into v from upd u join catalogue.providers p on p.id=u.provider_id;
  return v;
end $$;


ALTER FUNCTION "public"."svc_coverage_site_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_coverage_site_record"("p_provider_id" "uuid", "p_website" "text", "p_evidence" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $_$
declare v_dom text;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  -- v2.15.245: no credit to spend: searched again in a day; nothing else is recorded
  if coalesce(p_evidence->>'note', '') ilike '%budget%' then
    update pipeline.coverage_provider_discovery set leased_until=null, site_searched_at=now()-make_interval(days => greatest(0, security.pipeline_num_v1('retry.no_website_days', 30)::int - security.pipeline_num_v1('retry.website_after_budget_days', 1)::int)), site_evidence=p_evidence, updated_at=now() where provider_id=p_provider_id;
    return;
  end if;
  -- v2.15.232 (Fix 3): a course finder address entered by hand is kept; the search result is stored as evidence only
  if exists (select 1 from pipeline.manual_locks l where l.entity='provider' and l.entity_id=p_provider_id and l.field='course_finder')
     or exists (select 1 from pipeline.coverage_provider_discovery d where d.provider_id=p_provider_id and d.site_source='manual') then
    update pipeline.coverage_provider_discovery set site_searched_at=now(), leased_until=null, site_evidence=p_evidence, updated_at=now() where provider_id=p_provider_id;
    return;
  end if;
  -- v2.15.233 (Feature 1): a course directory or other third-party site is never recorded as the provider's site
  if nullif(p_website,'') is not null and security.third_party_host_v1(p_website) then
    update pipeline.coverage_provider_discovery set site_searched_at=now(), leased_until=null, updated_at=now(),
           site_evidence=coalesce(p_evidence,'{}'::jsonb)||jsonb_build_object('refused', p_website, 'refused_why', 'third-party site, not the provider''s own')
     where provider_id=p_provider_id;
    return;
  end if;
  update pipeline.coverage_provider_discovery set site_searched_at=now(), leased_until=null, site_evidence=p_evidence,
         website=coalesce(nullif(p_website,''),website), site_source=case when nullif(p_website,'') is not null then coalesce('search_verified_'||nullif(p_evidence->>'basis',''),'search_verified_cricos_code') else site_source end,
         status=case when nullif(p_website,'') is not null then 'pending' else status end, attempts=case when nullif(p_website,'') is not null then 0 else attempts end,
         requested_at=null, updated_at=now()
   where provider_id=p_provider_id;
  -- v2.15.245 (Platform Admin, 11 Oct 2026): a website found and verified goes on the provider's record, with its follow-on work
  if nullif(p_website,'') is not null then perform security.provider_website_adopt_v1(p_provider_id, p_website); end if;
  -- Decision 220: a Canadian site gets the generic recipe for its own .ca domain, and its active courses with no
  -- candidate page are queued for the course-page search by title.
  if nullif(p_website,'') is not null and security.coverage_country(p_provider_id) = 'CA' then
    v_dom := lower(regexp_replace(substring(btrim(p_website) from '^(?:https?://)?([^/:?#]+)'), '^www\.', ''));
    if v_dom ~ '^[a-z0-9.-]+\.ca$' then
      insert into pipeline.course_link_recipes(provider_id, search_domain, patterns, active, notes, updated_at)
      select p_provider_id, v_dom,
             jsonb_build_array(jsonb_build_object(
               're', '(?i)^https?://([a-z0-9-]+\.)*' || regexp_replace(v_dom, '\.', '\\.', 'g')
                     || '/(?!.*\.(pdf|docx?|xlsx?|pptx?|jpe?g|png|gif|svg|zip)$)(?!(.*/)?(news|events?|blog|staff|people|media|search|tags?|category)(/|$)).+$',
               'rep', '\&')),
             true, 'Generic recipe: any page on the provider''s own site; used only when the reader proves the page is the course''s (CA, Decision 220, 2 Oct 2026)', now()
       where not exists (select 1 from pipeline.course_link_recipes x where x.provider_id = p_provider_id);
      insert into pipeline.course_link_search(course_id, provider_id, stage, state, queued_at)
      select c.id, c.provider_id, 'title', 'queued', now()
        from catalogue.courses c
       where c.provider_id = p_provider_id and c.lifecycle_status = 'active'
         and exists (select 1 from pipeline.course_link_recipes x where x.provider_id = p_provider_id and x.active)
         and not exists (select 1 from pipeline.coverage_course_pages g where g.course_id = c.id)
      on conflict (course_id) do nothing;
    end if;
  end if;
end $_$;


ALTER FUNCTION "public"."svc_coverage_site_record"("p_provider_id" "uuid", "p_website" "text", "p_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_coverage_text_sha"("p_course_id" "uuid") RETURNS "text"
