CREATE OR REPLACE FUNCTION "public"."svc_credential_next"("p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  with pick as (
    select c.id course_id, pg.evidence_id, e.storage_path
      from catalogue.courses c
      join pipeline.coverage_course_pages pg on pg.course_id = c.id and pg.read_status = 'read' and pg.evidence_id is not null
      join pipeline.evidence_artifacts e on e.id = pg.evidence_id and e.storage_path is not null
      left join pipeline.course_credential_reads r on r.course_id = c.id
     where c.study_level_id is null and c.lifecycle_status in ('active', 'inactive')
       and security.coverage_country(c.provider_id) in (select distinct x.country_code from pipeline.credential_rules x where x.enabled)
       and (r.course_id is null or (r.evidence_id is distinct from pg.evidence_id and (r.outcome <> 'leased' or r.leased_until < now()))
            or (r.outcome = 'leased' and r.leased_until < now()))
     order by (c.lifecycle_status = 'active') desc, pg.read_at desc
     limit greatest(1, least(coalesce(p_limit, 50), 200))  -- fixed: per-call safety cap; the run size is batch.credential_read
     for update of c skip locked),
  lease as (insert into pipeline.course_credential_reads as r (course_id, evidence_id, outcome, leased_until, attempts)
            select p.course_id, p.evidence_id, 'leased', now() + interval '10 minutes', 1 from pick p  -- fixed: lease for one call
            on conflict (course_id) do update set evidence_id = excluded.evidence_id, outcome = 'leased', leased_until = excluded.leased_until, attempts = r.attempts + 1
            returning r.course_id)
  select jsonb_build_object(
    'rows', (select coalesce(jsonb_agg(jsonb_build_object('course_id', p.course_id, 'evidence_id', p.evidence_id, 'storage_path', p.storage_path)), '[]'::jsonb) from pick p where p.course_id in (select course_id from lease)),
    'rules', (select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'kind', x.kind, 'regex', x.regex) order by x.kind, x.id), '[]'::jsonb) from pipeline.credential_rules x where x.enabled))
    into v;
  return v;
end $$;


ALTER FUNCTION "public"."svc_credential_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_credential_record"("p_course_id" "uuid", "p_evidence_id" "uuid", "p_found" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_country text; v_levels text[]; v_basis text; v_level text; v_outcome text; v_ev record; v_text text; v_applied boolean := false;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select security.coverage_country(c.provider_id) into v_country from catalogue.courses c where c.id = p_course_id;
  if p_found is null then
    update pipeline.course_credential_reads set outcome = 'failed', leased_until = null, read_at = now() where course_id = p_course_id;
    return jsonb_build_object('outcome', 'failed');
  end if;
  -- a labelled credential decides; otherwise the official credential names decide when they give one level
  select array_agg(distinct security.credential_level_v1(v_country, f->>'text')) filter (where security.credential_level_v1(v_country, f->>'text') is not null)
    into v_levels from jsonb_array_elements(p_found) f where f->>'kind' = 'labelled';
  v_basis := 'labelled';
  if coalesce(cardinality(v_levels), 0) = 0 then
    select array_agg(distinct security.credential_level_v1(v_country, f->>'text')) filter (where security.credential_level_v1(v_country, f->>'text') is not null)
      into v_levels from jsonb_array_elements(p_found) f where f->>'kind' = 'phrase';
    v_basis := 'phrase';
  end if;
  v_outcome := case when coalesce(cardinality(v_levels), 0) = 1 then 'level' when coalesce(cardinality(v_levels), 0) > 1 then 'ambiguous' else 'none' end;
  v_level := case when v_outcome = 'level' then v_levels[1] end;
  select (select f->>'text' from jsonb_array_elements(p_found) f where f->>'kind' = v_basis and security.credential_level_v1(v_country, f->>'text') is not null limit 1) into v_text;  -- fixed: the first credential found is kept as the quote
  update pipeline.course_credential_reads set outcome = v_outcome, study_level_code = v_level, basis = case when v_outcome = 'none' then null else v_basis end,
         found = p_found, leased_until = null, read_at = now(), evidence_id = p_evidence_id
   where course_id = p_course_id;
  if v_outcome in ('level', 'ambiguous') then
    select e.id, e.source_id, coalesce(e.captured_at, e.created_at) at, coalesce(e.content_hash, md5(e.id::text)) h into v_ev from pipeline.evidence_artifacts e where e.id = p_evidence_id;
    if v_ev.source_id is not null then
      insert into catalogue.course_study_level_observations(course_id, study_level_id, source_id, evidence_id, scheme, registration_code, source_value, mapping_status, source_snapshot_at, content_hash)
      values (p_course_id, (select sl.id from ref.study_levels sl where sl.code = v_level), v_ev.source_id, v_ev.id, 'provider_page', v_basis,
              left(coalesce(v_text, (select string_agg(f->>'text', ' | ') from jsonb_array_elements(p_found) f)), 300),
              case when v_outcome = 'level' then 'mapped' else 'review_required' end, v_ev.at, v_ev.h)
      on conflict (course_id, source_id, scheme, registration_code, source_snapshot_at) do nothing;
    end if;
  end if;
  if v_outcome = 'level' then
    update catalogue.courses c set study_level_id = (select sl.id from ref.study_levels sl where sl.code = v_level), updated_at = now()
     where c.id = p_course_id and c.study_level_id is null
       and not exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = c.id and l.field = 'study_level_id');
    v_applied := found;
    update pipeline.course_credential_reads set applied = v_applied where course_id = p_course_id;
  end if;
  return jsonb_build_object('outcome', v_outcome, 'level', v_level, 'applied', v_applied);
end $$;


ALTER FUNCTION "public"."svc_credential_record"("p_course_id" "uuid", "p_evidence_id" "uuid", "p_found" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_cricos_peo_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  with pick as (
    select p.id, coalesce(p.display_name, p.canonical_name) name,
           (select min(upper(r.registration_code)) from catalogue.provider_registrations r where r.provider_id = p.id and lower(r.registration_scheme) = 'cricos') cricos
      from catalogue.providers p
     where p.lifecycle_status = 'active'
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id)  -- v2.15.237: paused while the provider is unpublished or archived
       and exists (select 1 from catalogue.provider_registrations r where r.provider_id = p.id and lower(r.registration_scheme) = 'cricos' and r.registration_code ~* '^[0-9]{5}[A-Z]$')
       and exists (select 1 from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active')
       and not exists (select 1 from pipeline.provider_contact_checks k where k.provider_id = p.id and k.kind = 'regulatory_peo'
                         and (k.checked_at > now() - make_interval(days => security.pipeline_num_v1('recheck.cricos_contact_days', 180)::int) and k.outcome <> 'budget' or k.checked_at > now() - interval '1 hour')) -- fixed: a check in flight
     order by (select count(*) from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active') desc
     limit greatest(1, least(coalesce(p_limit, 4), 8))),
  lease as (insert into pipeline.provider_contact_checks(provider_id, kind, checked_at, outcome) select id, 'regulatory_peo', now(), 'leased' from pick
            on conflict (provider_id, kind) do update set checked_at = now(), outcome = 'leased' returning provider_id)
  select coalesce(jsonb_agg(jsonb_build_object('provider_id', p.id, 'name', p.name, 'cricos', p.cricos)), '[]'::jsonb) into v
    from pick p where p.id in (select provider_id from lease);
  return v;
end $_$;


ALTER FUNCTION "public"."svc_cricos_peo_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_cricos_peo_record"("p_provider_id" "uuid", "p_outcome" "text", "p_name" "text", "p_title" "text", "p_phone" "text", "p_email" "text", "p_url" "text", "p_evidence" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  insert into pipeline.provider_contact_checks(provider_id, kind, checked_at, outcome, evidence)
  values (p_provider_id, 'regulatory_peo', now(), coalesce(p_outcome, 'not_found'), coalesce(p_evidence, '{}'::jsonb))
  on conflict (provider_id, kind) do update set checked_at = now(), outcome = excluded.outcome, evidence = excluded.evidence;
  if coalesce(p_outcome, '') <> 'found' or coalesce(nullif(btrim(p_name), ''), nullif(btrim(p_phone), ''), nullif(btrim(p_email), '')) is null then return; end if;
  update pipeline.provider_contact_points set is_current = false where provider_id = p_provider_id and kind = 'regulatory_peo' and is_current;
  insert into pipeline.provider_contact_points(provider_id, kind, source, name, title, phone, email, source_url, evidence)
  values (p_provider_id, 'regulatory_peo', 'cricos', left(nullif(btrim(p_name), ''), 200), left(nullif(btrim(p_title), ''), 200), left(nullif(btrim(p_phone), ''), 40),
          lower(left(nullif(btrim(p_email), ''), 200)), p_url, coalesce(p_evidence, '{}'::jsonb));
end $$;


ALTER FUNCTION "public"."svc_cricos_peo_record"("p_provider_id" "uuid", "p_outcome" "text", "p_name" "text", "p_title" "text", "p_phone" "text", "p_email" "text", "p_url" "text", "p_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_english_table_apply"("p_provider_cricos" "text", "p_programs" "jsonb", "p_minimum" "jsonb", "p_table1" "jsonb", "p_table3" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'security', 'search'
    AS $_$
declare v_source uuid; v_e1 uuid; v_e3 uuid; r record; v_ok int:=0; v_skipped jsonb:='[]'::jsonb; v_courses uuid[]:='{}'; v_doc jsonb; v_ev uuid; v_res jsonb;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  -- only courses with no English requirement are written; existing course-page values are never overwritten
  if jsonb_array_length(coalesce(p_programs,'[]'::jsonb))<30 then raise exception 'too few Table 1 programs; apply refused'; end if;
  if not exists(select 1 from jsonb_array_elements(p_minimum) q where q->>'test_code'='IELTS') then raise exception 'minimum IELTS requirement missing; apply refused'; end if;
  select s.id into v_source from pipeline.sources s where s.source_type='provider_english_requirements' and s.metadata->>'provider_cricos'=upper(btrim(p_provider_cricos))
     and exists(select 1 from pipeline.course_fact_source_qualifications q where q.source_id=s.id and q.qualification_status='qualified' and 'english_requirement'=any(q.admitted_domains));
  if v_source is null then raise exception 'no qualified English requirements source for provider %', p_provider_cricos; end if;
  foreach v_doc in array array[p_table1,p_table3] loop
    if coalesce(v_doc->>'storage_path','')='' or coalesce(v_doc->>'sha256','') !~ '^[0-9a-f]{64}$' then raise exception 'stored table file and its SHA-256 are required'; end if;
    select e.id into v_ev from pipeline.evidence_artifacts e where e.source_id=v_source and e.content_hash=v_doc->>'sha256' limit 1;
    if v_ev is null then
      v_ev:=public.svc_coursefacts_register_evidence(v_source,v_doc->>'url',v_doc->>'storage_path',v_doc->>'sha256','application/pdf',
        jsonb_build_object('layer',2,'kind','provider_english_requirements','document',v_doc->>'document','worker','fee-schedule-etl','decision','Decision 162 step 4'));
    end if;
    if v_doc is not distinct from p_table1 then v_e1:=v_ev; else v_e3:=v_ev; end if;
  end loop;
  for r in select * from security.english_table_plan_v1(p_provider_cricos,p_programs,p_minimum)
            where plan in ('table1','minimum') and comparison='none' and course_cricos is not null loop
    begin
      v_res:=public.svc_coursefacts_apply_record(v_source, case when r.plan='table1' then v_e1 else v_e3 end, p_provider_cricos, r.course_cricos,
        'uq-elp:'||r.plan||':'||r.course_cricos, case when r.plan='table1' then p_table1->>'url' else p_table3->>'url' end,
        case when r.plan='table1' then p_table1->>'sha256' else p_table3->>'sha256' end,
        jsonb_build_object('english_requirements',(select jsonb_agg(jsonb_build_object('test_code',q->>'test_code','overall_score',q->'overall_score','component_scores',coalesce(q->'component_scores','{}'::jsonb),
            'source_requirement_key','d162-elp:'||lower(r.course_cricos)||':'||lower(q->>'test_code'),
            'notes',case when r.reason like 'double degree:%' then 'Decision 162: UQ '||r.reason when r.plan='table1' then 'Decision 162: UQ ELP Table 1 (higher-than-minimum) - '||r.program else 'Decision 162: UQ minimum ELP (Procedure cl. 10-11; Table 3)' end))
          from jsonb_array_elements(r.requirements) q),'extraction_worker','fee-schedule-etl','plan',r.plan,'table1_program',r.program), true);
      v_ok:=v_ok+1; v_courses:=v_courses||r.course_id;
    exception when others then v_skipped:=v_skipped||jsonb_build_object('course',r.title,'reason',left(sqlerrm,200));
    end;
  end loop;
  if cardinality(v_courses)>0 then perform search.refresh_course_enrichment_scoped_v1(v_courses,true); end if;
  return jsonb_build_object('applied',v_ok,'skipped',jsonb_array_length(v_skipped),'skipped_detail',v_skipped,'source_id',v_source,'table1_evidence',v_e1,'table3_evidence',v_e3);
end $_$;


ALTER FUNCTION "public"."svc_english_table_apply"("p_provider_cricos" "text", "p_programs" "jsonb", "p_minimum" "jsonb", "p_table1" "jsonb", "p_table3" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_english_table_preview"("p_provider_cricos" "text", "p_programs" "jsonb", "p_minimum" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security'
    AS $$
declare v jsonb;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  with pl as (select * from security.english_table_plan_v1(p_provider_cricos,p_programs,p_minimum)),
       t1 as (select e->>'name' name, e->>'section' section from jsonb_array_elements(p_programs) e)
  select jsonb_build_object(
    'courses',(select count(*) from pl),
    'by_plan',(select jsonb_object_agg(plan,n) from (select plan,count(*) n from pl group by 1) x),
    'by_comparison',(select jsonb_object_agg(plan||':'||comparison,n) from (select plan,comparison,count(*) n from pl where comparison is not null group by 1,2) x),
    'would_write',(select count(*) from pl where plan in ('table1','minimum') and comparison='none' and course_cricos is not null),
    'held_by_reason',(select jsonb_object_agg(reason,n) from (select reason,count(*) n from pl where plan='held' group by 1) x),
    'table1_programs',(select jsonb_agg(jsonb_build_object('program',t1.name,'section',t1.section,
         'courses',(select count(*) from pl where pl.program=t1.name)) order by t1.name) from t1),
    'table1_not_in_catalogue',(select jsonb_agg(t1.name order by t1.name) from t1 where not exists(select 1 from pl where pl.program=t1.name)),
    'differs',(select jsonb_agg(jsonb_build_object('title',title,'plan',plan,'program',program,'planned',(select jsonb_object_agg(q->>'test_code',q->'overall_score') from jsonb_array_elements(requirements) q),'existing',existing) order by title) from pl where comparison='differs'),
    'held',(select jsonb_agg(jsonb_build_object('title',title,'reason',reason,'existing',existing) order by reason,title) from pl where plan='held'),
    'written_sample',(select jsonb_agg(x) from (select jsonb_build_object('title',title,'plan',plan,'ielts',(select q->'overall_score' from jsonb_array_elements(requirements) q where q->>'test_code'='IELTS')) x from pl where plan in ('table1','minimum') and comparison='none' order by plan desc,title limit 12) s)
  ) into v;
  return v;
end $$;


ALTER FUNCTION "public"."svc_english_table_preview"("p_provider_cricos" "text", "p_programs" "jsonb", "p_minimum" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_enrich_ai_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v jsonb; v_lim int := greatest(1, least(coalesce(p_limit, 10), 40));
        -- 13 Nov 2026 (Platform Admin 19:14): the model and the budget of each field group come from its route (pipeline.ai_service_routes)
        v_r jsonb; v_top jsonb; v_off text[]; v_capf text[]; v_not text[]; v_off_rest boolean; v_cap_rest boolean; v_od uuid[];
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  v_r := security.ai_enrich_routes_v1();
  v_top := v_r->'top';
  v_off := array(select jsonb_array_elements_text(v_r->'off_fields')); v_capf := array(select jsonb_array_elements_text(v_r->'limit_fields'));
  v_not := array(select jsonb_array_elements_text(v_r->'rest_except'));
  v_off_rest := coalesce((v_r->>'off_rest')::boolean, false); v_cap_rest := coalesce((v_r->>'limit_rest')::boolean, false);
  v_od := array(select jsonb_array_elements_text(v_r->'on_demand_providers'))::uuid[];
  -- 22 Oct 2026 (Platform Admin 11:42): items of unpublished providers in automatic tasks (standing gap queue, automatic plans) are settled
  -- without the AI; the gap queue asks for them again once the provider is published (reason 'provider unpublished'). A task a person started runs.
  update pipeline.field_enrich_items e set state = 'skipped', reason = 'provider unpublished', leased_until = null, updated_at = now()
    from pipeline.admin_jobs j
   where j.id = e.job_id and e.state = 'ai' and (coalesce((j.args->>'standing')::boolean, false) or j.args->>'plan_mode' = 'auto')
     and exists (select 1 from security.provider_hidden_v1 h where h.provider_id = e.provider_id);
  with pick0 as (select e.id, e.job_id, e.course_id from pipeline.field_enrich_items e
                 where (e.state = 'ai' or (e.state = 'leased' and e.leased_until < now())) and e.attempts < 3
                   and not (e.field = any(v_off)) and not (v_off_rest and not (e.field = any(v_not)))
                   and (e.provider_id = any(v_od) or (not (e.field = any(v_capf)) and not (v_cap_rest and not (e.field = any(v_not)))))  -- a held route hands out no work for its fields (a cap or the ceiling does not hold an on-demand provider)
                 order by e.job_id, (e.course_id is null), e.course_id, e.id limit v_lim for update skip locked),  -- a course's fields together
  -- CF-247 Release B (§6 priority 2): with enrich.multi_field_on, the rest of each leased course's due stored-page items of the same task too
  pick1 as (select e.id from pipeline.field_enrich_items e
             where security.pipeline_num_v1('enrich.multi_field_on', 1) >= 1 and e.source = 'ai_stored' and e.course_id is not null
               and (e.job_id, e.course_id) in (select p0.job_id, p0.course_id from pick0 p0 where p0.course_id is not null)
               and (e.state = 'ai' or (e.state = 'leased' and e.leased_until < now())) and e.attempts < 3
               and not (e.field = any(v_off)) and not (v_off_rest and not (e.field = any(v_not)))
                   and (e.provider_id = any(v_od) or (not (e.field = any(v_capf)) and not (v_cap_rest and not (e.field = any(v_not)))))
             for update skip locked),
  pick as (select p0.id from pick0 p0 union select p1.id from pick1 p1),
  upd as (update pipeline.field_enrich_items e set state = 'leased', leased_until = now() + make_interval(mins => 4), attempts = e.attempts + 1, updated_at = now()
            from pick where e.id = pick.id returning e.*)
  select jsonb_build_object('model', coalesce(v_top->>'model', ''), 'model_code', coalesce(v_top#>>'{models,0,code}', ''),
    'models', coalesce(v_top->'models', '[]'::jsonb), 'routes', v_r->'routes', 'held', v_r->'held',
    'pages', coalesce((select jsonb_agg(g.x) from (
                         select jsonb_build_object('course_id', u.course_id, 'storage_path', min(u.storage_path), 'title', min(c.canonical_title), 'provider', min(coalesce(p.display_name, p.canonical_name)),
                                  'items', jsonb_agg(jsonb_build_object('item_id', u.id, 'field', u.field,
                                    'hint', case when u.reason = 'the quote is not on the page' then 'last time the quote given for this field was not found on the page' end))) x
                           from upd u join catalogue.courses c on c.id = u.course_id join catalogue.providers p on p.id = u.provider_id
                          where u.source = 'ai_stored' and u.course_id is not null group by u.course_id) g), '[]'::jsonb),
    'titles', coalesce((select jsonb_agg(jsonb_build_object('item_id', u.id, 'field', u.field, 'title', c.canonical_title, 'level', sl.name, 'provider', coalesce(p.display_name, p.canonical_name)))
                        from upd u join catalogue.courses c on c.id = u.course_id join catalogue.providers p on p.id = u.provider_id left join ref.study_levels sl on sl.id = c.study_level_id
                       where u.source = 'ai_title'), '[]'::jsonb),
    'campus_lists', coalesce((select jsonb_agg(jsonb_build_object('item_id', u.id, 'provider', coalesce(p.display_name, p.canonical_name), 'storage_path', u.storage_path,
                         'names', (select coalesce(jsonb_agg(jsonb_build_object('text', q, 'pages', n) order by n desc), '[]'::jsonb)
                                     from (select c.quote q, count(*) n from pipeline.field_enrich_items c where c.job_id = u.job_id and c.provider_id = u.provider_id and c.field = 'campus' and c.quote is not null group by c.quote order by 2 desc limit 80) z)))
                        from upd u join catalogue.providers p on p.id = u.provider_id where u.field = 'campus_list'), '[]'::jsonb),
    'regions', coalesce((select jsonb_agg(jsonb_build_object('item_id', u.id, 'provider', coalesce(p.display_name, p.canonical_name), 'country', k.name,
                         'cities', (select coalesce(jsonb_agg(distinct btrim(c2.city)), '[]'::jsonb) from catalogue.campuses c2
                                     where c2.provider_id = u.provider_id and c2.status = 'active' and c2.subdivision_id is null and nullif(btrim(c2.city), '') is not null),
                         'regions', (select coalesce(jsonb_agg(s2.name order by s2.name), '[]'::jsonb) from ref.subdivisions s2 where s2.country_id = p.country_id)))
                        from upd u join catalogue.providers p on p.id = u.provider_id join ref.countries k on k.id = p.country_id where u.field = 'campus_region'), '[]'::jsonb),
    'addresses', coalesce((select jsonb_agg(jsonb_build_object('item_id', u.id, 'provider_id', u.provider_id, 'provider', coalesce(p.display_name, p.canonical_name), 'storage_path', u.storage_path,
                         'website', case when u.source = 'scraper' then p.website end, 'country', (select k.iso_alpha2 from ref.countries k where k.id = p.country_id)))
                        from upd u join catalogue.providers p on p.id = u.provider_id where u.field = 'provider_address'), '[]'::jsonb),
    'entry', jsonb_build_object('model', coalesce(v_r#>>'{routes,course_entry_requirements,model}', ''), 'models', coalesce(v_r#>'{routes,course_entry_requirements,models}', '[]'::jsonb),
                                'page_chars', security.pipeline_num_v1('entry.course_page_chars', 100000)::int),  -- CF-247 Track C Step B: the entry model, from its route
    'fields', (select jsonb_agg(jsonb_build_object('code', f.code, 'name', f.name) order by f.code) from ref.fields_of_study f where f.code ~ '^asced-\d{4}$' and f.code !~ '00$'),
    'levels', (select jsonb_agg(jsonb_build_object('code', l.short_code, 'name', l.name) order by l.sort_order) from ref.study_levels l where l.short_code is not null))
    into v;
  return v;
end $_$;


ALTER FUNCTION "public"."svc_enrich_ai_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_enrich_ai_record"("p_results" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare r jsonb; i pipeline.field_enrich_items%rowtype; v_val jsonb; v_out jsonb := '{}'::jsonb; v_k text; v_ev uuid;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  for r in select * from jsonb_array_elements(coalesce(p_results, '[]'::jsonb)) loop
    select * into i from pipeline.field_enrich_items where id = (r->>'item_id')::bigint for update;
    if i.id is null then continue; end if;
    -- CF-247 Release B (D3): the reader version recorded with an absence (pipeline.course_field_absence.reader_version)
    perform set_config('cf247.reader_version', left(coalesce(nullif(concat_ws(' ', nullif(r->>'worker', ''), nullif(r->>'prompt_version', ''), nullif(r->>'model', '')), ''),
                                                                'enrich_ai ' || coalesce(i.source, '') || ' ' || coalesce(security.ai_service_model_v1(security.ai_ledger_service_v1('enrich_fields', 'field_enrich_items', jsonb_build_object('field', i.field))), '')), 200), true);
    v_ev := i.evidence_id;
    if r->>'storage_path' is not null then
      insert into pipeline.evidence_artifacts(source_id, evidence_type, source_url, storage_path, content_hash, mime_type, metadata, capture_version, evidence_group_key)
      values (security.coverage_sweep_source(i.provider_id), 'enrich_home_page', r->>'url', r->>'storage_path', r->>'sha256', 'application/gzip',
              jsonb_build_object('item_id', i.id, 'provider_id', i.provider_id, 'worker', 'coverage-sweep enrich_ai'), 1, 'enrich:' || i.id)
      returning id into v_ev;
    end if;
    update pipeline.field_enrich_items set cost_usd = coalesce(cost_usd, 0) + coalesce((r->>'cost')::numeric, 0), model = coalesce(nullif(r->>'model', ''), model), evidence_id = v_ev,
           storage_path = coalesce(r->>'storage_path', storage_path), leased_until = null, updated_at = now() where id = i.id;
    if r->>'retry' = 'true' then
      update pipeline.field_enrich_items set state = case when attempts >= 3 then 'failed' else 'ai' end, reason = left(r->>'reason', 300) where id = i.id;
      v_k := 'retry';
    elsif r->>'error' is not null then
      update pipeline.field_enrich_items set state = case when attempts >= 3 then 'failed' else 'ai' end, reason = left(r->>'error', 300) where id = i.id;
      v_k := 'error';
    elsif i.field = 'campus' then
      if nullif(btrim(r->'value'->>'campus'), '') is not null then
        update pipeline.field_enrich_items set state = 'waiting', quote = left(r->'value'->>'campus', 300) where id = i.id; v_k := 'campus_named';
      else
        if security.enrich_fallback_v1(i.id) then v_k := 'provider_fact';  -- 22 Oct 2026 (fix 4): the provider's only campus
        else update pipeline.field_enrich_items set state = 'skipped', reason = 'the page names no campus' where id = i.id; v_k := 'not_stated'; end if;
      end if;
    elsif i.field = 'entry_requirements' then
      -- CF-247 Track C Step B (28 Oct 2026): course academic entry requirements, proposed for a person (B1)
      v_k := security.enrich_entry_record_v1(i.id, r);
    elsif i.field in ('description', 'deadline') then
      -- CF-247 Workstream C (3 Nov 2026): course description and application deadline from the stored course page
      v_k := security.enrich_course_text_record_v1(i.id, r);
    elsif i.field = 'campus_list' then
      update pipeline.field_enrich_items set value = jsonb_build_object('campuses', coalesce(r->'value'->'campuses', '[]'::jsonb)), quote = left(r->>'quote', 300) where id = i.id;
      v_k := 'campus_list'; perform security.enrich_campus_list_apply_v1(i.id);
    else
      v_val := case i.field
        when 'duration' then security.enrich_parse_duration_v1(r->>'quote')
        when 'delivery' then (select jsonb_build_object('mode', r->'value'->>'mode') where r->'value'->>'mode' in ('on_campus', 'online', 'blended', 'on_campus_and_online'))
        when 'level' then (select jsonb_build_object('level_id', l.id) from ref.study_levels l where l.short_code = r->'value'->>'level')
        when 'field_of_study' then (select jsonb_build_object('field_id', f.id) from ref.fields_of_study f where f.code = r->'value'->>'field' and f.code ~ '^asced-\d{4}$')
        when 'international' then (select jsonb_build_object('open', (r->'value'->>'open')::boolean) where r->'value'->>'open' in ('true', 'false'))
        when 'provider_address' then (select r->'value' where nullif(btrim(r->'value'->>'street'), '') is not null)
        when 'english' then security.enrich_parse_english_v1(r->'value'->>'text', r->>'quote')
        when 'intakes' then coalesce(security.enrich_parse_intakes_v1(r->'value'->>'text', r->>'quote'),
                                     security.enrich_parse_intake_periods_v1(i.provider_id, r->'value'->>'text', r->>'quote'))  -- 23 Oct 2026: semesters from the approved calendar
        when 'campus_region' then (select r->'value' where jsonb_array_length(coalesce(r->'value'->'cities', '[]'::jsonb)) > 0)
        when 'campus' then null end;
      if v_val is null then
        if security.enrich_fallback_v1(i.id) then v_k := 'provider_fact';  -- 22 Oct 2026 (fix 4): a provider-level or registered fact
        else
        update pipeline.field_enrich_items set state = 'skipped', reason = coalesce(nullif(r->>'reason', ''), 'the page does not state it') where id = i.id;
        v_k := 'not_stated';
        end if;
      else
        update pipeline.field_enrich_items set value = v_val, quote = left(coalesce(r->>'quote', i.quote), 300) where id = i.id;
        v_k := security.enrich_apply_v1(i.id);
      end if;
    end if;
    v_out := v_out || jsonb_build_object(v_k, coalesce((v_out->>v_k)::int, 0) + 1);
  end loop;
  return v_out;
end $_$;


ALTER FUNCTION "public"."svc_enrich_ai_record"("p_results" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_enrich_ai_stash_v1"("p_results" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int;
begin
  if jsonb_typeof(p_results) <> 'array' or jsonb_array_length(p_results) = 0 then return jsonb_build_object('kept', 0); end if;
  insert into pipeline.enrich_ai_answers(item_id, attempts, evidence_id, storage_path, answer, cost_usd)
  select e.id, e.attempts, e.evidence_id, e.storage_path, x, (x->>'cost')::numeric
    from jsonb_array_elements(p_results) x join pipeline.field_enrich_items e on e.id = (x->>'item_id')::bigint
   where not coalesce((x->>'retry')::boolean, false)
  on conflict (item_id, attempts) do nothing;
  get diagnostics v_n = row_count;
  return jsonb_build_object('kept', v_n);
end $$;


ALTER FUNCTION "public"."svc_enrich_ai_stash_v1"("p_results" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_entry_country_refs_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('a2', trim(k.iso_alpha2::text), 'a3', trim(k.iso_alpha3::text), 'name', k.name, 'official', k.official_name) order by k.iso_alpha2), '[]'::jsonb)
            from ref.countries k);
end $$;


ALTER FUNCTION "public"."svc_entry_country_refs_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_entry_country_refs_v1"() IS 'CF-247 AER v1.1 D2: the country reference list the entry-matrix worker checks an equivalency page''s heading against (service role).';



CREATE OR REPLACE FUNCTION "public"."svc_entry_matrix_fetch_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if security.pipeline_num_v1('entry.matrix_enabled', 0) < 1 then return '[]'::jsonb; end if;
  -- AER Step B (29 Oct 2026): PDFs wait only while entry.pdf_enabled is 0
  if security.pipeline_num_v1('entry.pdf_enabled', 0) < 1 then
    update pipeline.entry_matrix_sources s set status = 'pdf_step_b', updated_at = now()
     where s.status = 'found' and s.url ~* '\.pdf($|[?#])';
  end if;
  with pick as (select s.id from pipeline.entry_matrix_sources s
                 where (s.status = 'found' or (s.status = 'reading' and s.updated_at < now() - interval '20 minutes'))  -- fixed: claim timer
                   and s.attempts < security.pipeline_num_v1('entry.matrix_attempts', 3)
                   and security.entry_matrix_enabled_v1(s.provider_id)
                 order by s.rank, s.created_at limit greatest(1, least(coalesce(p_limit, 4), 20)) for update skip locked),
  upd as (update pipeline.entry_matrix_sources s set status = 'reading', attempts = s.attempts + 1, updated_at = now() from pick where s.id = pick.id returning s.*)
  select coalesce(jsonb_agg(jsonb_build_object('source_id', u.id, 'provider_id', u.provider_id, 'url', u.url,
           'country', (select k.iso_alpha2 from catalogue.providers p join ref.countries k on k.id = p.country_id where p.id = u.provider_id),
           'pdf', u.url ~* '\.pdf($|[?#])', 'pdf_max_bytes', security.pipeline_num_v1('entry.pdf_max_bytes', 20000000)::bigint,
           'render', coalesce(security.toolset_setting('pipeline', 'entry.render_hosts'), '[]'::jsonb) ? lower(substring(u.url from '^https?://(?:www\.)?([^/:?#]+)')),
           'render_wait_ms', security.pipeline_num_v1('entry.render_wait_ms', 5000)::int)), '[]'::jsonb)
    into v from upd u;
  return v;
end $_$;


ALTER FUNCTION "public"."svc_entry_matrix_fetch_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_entry_matrix_fetch_record"("p_source_id" "uuid", "p_status" "text", "p_via" "text", "p_http" integer, "p_storage_path" "text", "p_sha256" "text", "p_mime" "text", "p_error" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare s pipeline.entry_matrix_sources%rowtype; v_src uuid; v_ev uuid;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into s from pipeline.entry_matrix_sources where id = p_source_id for update;
  if s.id is null then raise exception 'source not found'; end if;
  if p_status = 'read' and p_storage_path is not null and p_sha256 ~ '^[0-9a-f]{64}$' then
    v_src := security.coverage_sweep_source(s.provider_id);
    select id into v_ev from pipeline.evidence_artifacts where source_id = v_src and content_hash = p_sha256 and source_url = s.url limit 1;
    if v_ev is null then
      v_ev := public.svc_coursefacts_register_evidence(v_src, s.url, p_storage_path, p_sha256, coalesce(p_mime, 'text/html'),
                jsonb_build_object('layer', 2, 'kind', 'provider_entry_requirements', 'worker', 'coverage-sweep', 'entry_matrix_source_id', s.id, 'read_via', p_via));
    end if;
    update pipeline.entry_matrix_sources set status = 'read', read_via = p_via, http_status = p_http, evidence_id = v_ev, content_hash = p_sha256,
           read_at = now(), error = null, updated_at = now() where id = s.id;
    return jsonb_build_object('status', 'read', 'evidence_id', v_ev);
  end if;
  -- 29 Oct 2026: a Firecrawl budget refusal is not the page failing; it waits for the next read without using one of its tries
  update pipeline.entry_matrix_sources set
         attempts = case when p_error in ('credits_refused', 'credits_reserve', 'no_firecrawl_key') then greatest(attempts - 1, 0) else attempts end,
         status = case when p_status = 'robots_disallowed' then 'robots_disallowed'
                       when p_error in ('credits_refused', 'credits_reserve', 'no_firecrawl_key') then 'found'
                       when attempts >= security.pipeline_num_v1('entry.matrix_attempts', 3) then 'failed' else 'found' end,
         http_status = p_http, error = left(coalesce(p_error, p_status), 400), updated_at = now()
   where id = s.id;
  return jsonb_build_object('status', p_status);
end $_$;


ALTER FUNCTION "public"."svc_entry_matrix_fetch_record"("p_source_id" "uuid", "p_status" "text", "p_via" "text", "p_http" integer, "p_storage_path" "text", "p_sha256" "text", "p_mime" "text", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_entry_matrix_inspect_paths"("p_source_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('source_id', s.id, 'url', s.url, 'storage_path', e.storage_path, 'mime', e.mime_type, 'content_hash', s.content_hash) order by s.url), '[]'::jsonb)
            from pipeline.entry_matrix_sources s left join pipeline.evidence_artifacts e on e.id = s.evidence_id
           where s.id = any(p_source_ids[1:12]));  -- fixed: diagnostic batch cap
end $$;


ALTER FUNCTION "public"."svc_entry_matrix_inspect_paths"("p_source_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_entry_matrix_inspect_paths"("p_source_ids" "uuid"[]) IS 'CF-247 AER v1.1 tooling: stored-copy paths of up to 12 entry-matrix sources for the read-only worker mode entry_inspect (service role).';



CREATE OR REPLACE FUNCTION "public"."svc_entry_matrix_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb; v_route jsonb := security.ai_route_v1('entry_matrices'); v_model text := v_route->>'model';  -- 13 Nov 2026: the route (pipeline.ai_service_routes)
        v_od uuid[] := security.ai_on_demand_providers_v1('entry_matrices');
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if security.pipeline_num_v1('entry.matrix_enabled', 0) < 1 or not security.ai_use_allowed_v1('entry_matrix') then return '[]'::jsonb; end if;
  -- the route: switched off, no allowed model or the credit floor holds everything; a cap or the daily ceiling holds all but on-demand providers
  if v_model is null or (coalesce((v_route->>'held')::boolean, true) and not (coalesce((v_route->>'on_demand_exempt')::boolean, false) and cardinality(v_od) > 0)) then return '[]'::jsonb; end if;
  with pick as (select r.id from pipeline.entry_matrix_runs r
                 where (r.state = 'queued' or (r.state = 'leased' and r.leased_until < now()))
                   and r.attempts < security.pipeline_num_v1('entry.matrix_attempts', 3)
                   and security.entry_matrix_enabled_v1(r.provider_id)
                   and (not (v_route->>'held')::boolean or r.provider_id = any(v_od))
                 order by r.created_at limit greatest(1, least(coalesce(p_limit, 4), 20)) for update skip locked),
  upd as (update pipeline.entry_matrix_runs r set state = 'leased', leased_until = now() + interval '5 minutes',  -- fixed: lease timer
                 attempts = r.attempts + 1, model_code = v_model, updated_at = now() from pick where r.id = pick.id returning r.*)
  select coalesce(jsonb_agg(jsonb_build_object('run_id', u.id, 'source_id', u.source_id, 'provider_id', u.provider_id,
           'provider', coalesce(p.display_name, p.canonical_name), 'country', k.iso_alpha2, 'url', s.url, 'storage_path', e.storage_path, 'mime', e.mime_type,
           'model', v_model, 'model_code', split_part(v_model, '/', 2), 'models', v_route->'models',
           'max_rows', security.pipeline_num_v1('entry.matrix_max_rows_per_page', 400)::int,
           'max_tokens', security.pipeline_num_v1('entry.matrix_max_tokens', 8000)::int,
           'slice_chars', security.pipeline_num_v1('entry.matrix_slice_chars', 24000)::int,
           'slice_concurrency', security.pipeline_num_v1('entry.matrix_slice_concurrency', 1)::int,
           'pdf_max_pages', security.pipeline_num_v1('entry.pdf_max_pages', 40)::int,
           'completeness_required', security.entry_completeness_required_v1(u.provider_id))), '[]'::jsonb) into v
    from upd u join pipeline.entry_matrix_sources s on s.id = u.source_id join pipeline.evidence_artifacts e on e.id = s.evidence_id
    join catalogue.providers p on p.id = u.provider_id left join ref.countries k on k.id = p.country_id;
  return v;
end $$;


ALTER FUNCTION "public"."svc_entry_matrix_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_entry_matrix_record"("p_run_id" "uuid", "p_result" "jsonb", "p_cost" numeric, "p_error" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.entry_matrix_runs%rowtype; f pipeline.entry_matrix_sources%rowtype; x jsonb; v_country uuid; v_conf numeric;
        v_min_conf numeric := security.pipeline_num_v1('entry.matrix_min_confidence', 0.85);
        v_in int := 0; v_dropped jsonb := coalesce(p_result->'dropped', '[]'::jsonb); v_item uuid; v_first boolean; v_field text;
        v_all_conf boolean := true;
        v_qin int := 0; v_qx jsonb; v_qcode text;  -- 12 Nov 2026 (F-AER.03): qualification rows
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into r from pipeline.entry_matrix_runs where id = p_run_id for update;
  if r.id is null then return jsonb_build_object('ok', false, 'error', 'unknown run'); end if;
  -- completeness guard (26 Oct 2026): under entry.completeness_providers only a read the worker found complete proposes rows
  if p_error is null and security.entry_completeness_required_v1(r.provider_id) and coalesce(p_result->'completeness'->>'status', 'missing') <> 'complete' then
    p_error := 'held_incomplete: no complete verdict (' || coalesce(p_result->'completeness'->>'status', 'missing') || ')';
  end if;
  if p_error is not null then
    update pipeline.entry_matrix_runs set
           -- a held read is kept whole in the run history; an unreadable page is not read again, an incomplete read is retried within entry.matrix_attempts
           previous_results = case when p_result is null then previous_results
                                   else previous_results || jsonb_build_array(jsonb_build_object('held', p_error like 'held_%', 'reason', left(p_error, 400),
                                          'attempt', attempts, 'model', model_code, 'at', now(), 'result', p_result)) end,
           state = case when p_error like 'held_unparsed%' then 'failed' when p_error = 'time budget' and coalesce(p_cost, 0) = 0 then 'queued' when attempts >= security.pipeline_num_v1('entry.matrix_attempts', 3) then 'failed' else 'queued' end,
           attempts = case when p_error = 'time budget' and coalesce(p_cost, 0) = 0 then greatest(attempts - 1, 0) else attempts end,  -- 29 Oct 2026: a cut read that spent uses a try
           leased_until = null, error = left(p_error, 400), cost_usd = cost_usd + coalesce(p_cost, 0), updated_at = now()
     where id = r.id;
    return jsonb_build_object('ok', true, 'status', 'error');
  end if;
  select * into f from pipeline.entry_matrix_sources where id = r.source_id;
  v_first := not exists (select 1 from catalogue.provider_entry_matrix m where m.provider_id = r.provider_id and m.status = 'active');
  for x in select * from jsonb_array_elements(coalesce(p_result->'rows', '[]'::jsonb)) loop
    select k.id into v_country from ref.countries k where k.iso_alpha2 = upper(x->>'country_code');
    v_conf := nullif(x->>'confidence', '')::numeric;
    if v_country is null then v_dropped := v_dropped || jsonb_build_array(jsonb_build_object('reason', 'unknown_country', 'country', x->>'country_name')); continue; end if;
    if coalesce(v_conf, 0) < v_min_conf then v_dropped := v_dropped || jsonb_build_array(jsonb_build_object('reason', 'low_confidence', 'country', x->>'country_code')); continue; end if;
    if nullif(trim(x->>'quote'), '') is null or nullif(trim(x->>'qualification_name'), '') is null then
      v_dropped := v_dropped || jsonb_build_array(jsonb_build_object('reason', 'missing_quote_or_qualification', 'country', x->>'country_code')); continue; end if;
    if (x->>'min_value') is not null and coalesce(x->>'grade_scale', 'none') = 'none' then
      v_dropped := v_dropped || jsonb_build_array(jsonb_build_object('reason', 'value_without_scale', 'country', x->>'country_code')); continue; end if;
    insert into catalogue.provider_entry_matrix(provider_id, course_label, matrix_kind, benchmark_band, level_label, study_level_id, country_id, country_code,
             qualification_name, min_grade, min_value, grade_scale, conditions, edition, intake_year, quote, source_url, source_id, evidence_id,
             content_hash, run_id, confidence, status, provenance)
    values (r.provider_id, nullif(trim(x->>'course_name'), ''),
            case when nullif(trim(x->>'course_name'), '') is not null then 'course_minimum' when x->>'grade_scale' = 'rank' then 'rank_band'
                 when nullif(trim(x->>'benchmark_band'), '') is not null then 'band_ladder' else 'provider_minimum' end,
            nullif(trim(x->>'benchmark_band'), ''), nullif(trim(x->>'study_level'), ''), security.entry_level_map_v1(x->>'study_level'),
            v_country, upper(x->>'country_code'), left(trim(x->>'qualification_name'), 300), nullif(trim(x->>'min_grade'), ''),
            (x->>'min_value')::numeric, coalesce(nullif(x->>'grade_scale', ''), 'none'), coalesce(x->'conditions', '{}'::jsonb),
            nullif(trim(p_result->>'edition'), ''), nullif(p_result->>'intake_year', '')::int, left(trim(x->>'quote'), 300), f.url, f.id, f.evidence_id,
            r.content_hash, r.id, v_conf, 'proposed',
            jsonb_build_object('reader', coalesce(nullif(p_result->>'reader', ''), 'entry_ai'), 'model', r.model_code, 'run_id', r.id, 'worker', p_result->>'worker', 'prompt', p_result->>'prompt_version'));
    v_in := v_in + 1;
  end loop;
  -- 12 Nov 2026 (F-AER.03 qualification-first): rows the reader kept for a recognised international qualification that name no country of education are recorded
  -- beside the matrix with their identity and applicability, on the same Layer 4 item; an unrecognised qualification is dropped (unknown_qualification)
  if security.pipeline_num_v1('reading.entry_qualification_first_on', 0) >= 1 then
    for v_qx in select * from jsonb_array_elements(coalesce(p_result->'qualification_rows', '[]'::jsonb)) loop
      select q.code into v_qcode from ref.aer_qualifications q where q.code = v_qx->>'qualification_code' and q.scope = 'international';
      v_conf := nullif(v_qx->>'confidence', '')::numeric;
      if v_qcode is null then v_dropped := v_dropped || jsonb_build_array(jsonb_build_object('reason', 'unknown_qualification', 'country', v_qx->>'country_token', 'qualification', v_qx->>'qualification_name')); continue; end if;
      if coalesce(v_conf, 0) < v_min_conf then v_dropped := v_dropped || jsonb_build_array(jsonb_build_object('reason', 'low_confidence', 'qualification', v_qcode)); continue; end if;
      if nullif(trim(v_qx->>'quote'), '') is null then v_dropped := v_dropped || jsonb_build_array(jsonb_build_object('reason', 'missing_quote_or_qualification', 'qualification', v_qcode)); continue; end if;
      if (v_qx->>'min_value') is not null and coalesce(v_qx->>'grade_scale', 'none') = 'none' then
        v_dropped := v_dropped || jsonb_build_array(jsonb_build_object('reason', 'value_without_scale', 'qualification', v_qcode)); continue; end if;
      insert into catalogue.provider_qualification_requirements(provider_id, course_label, qualification_code, qualification_label, applicability, level_label, study_level_id, min_grade, min_value,
               grade_scale, conditions, quote, source_url, source_id, evidence_id, content_hash, run_id, confidence, status, provenance)
      values (r.provider_id, nullif(trim(v_qx->>'course_name'), ''), v_qcode, left(coalesce(nullif(trim(v_qx->>'qualification_name'), ''), v_qcode), 300),
              case when v_qx->>'applicability' = 'global' then 'global' else 'unresolved' end,
              nullif(trim(v_qx->>'study_level'), ''), security.entry_level_map_v1(v_qx->>'study_level'), nullif(trim(v_qx->>'min_grade'), ''), (v_qx->>'min_value')::numeric,
              coalesce(nullif(v_qx->>'grade_scale', ''), 'none'), coalesce(v_qx->'conditions', '{}'::jsonb), left(trim(v_qx->>'quote'), 300), f.url, f.id, f.evidence_id,
              r.content_hash, r.id, v_conf, 'proposed',
              jsonb_build_object('reader', coalesce(nullif(p_result->>'reader', ''), 'entry_ai'), 'model', r.model_code, 'run_id', r.id, 'worker', p_result->>'worker', 'prompt', p_result->>'prompt_version',
                                 'country_token', v_qx->>'country_token', 'applicability_basis', v_qx->>'applicability_basis'));
      v_qin := v_qin + 1;
    end loop;
  end if;
  if v_in + v_qin > 0 then
    v_field := case when v_first then 'entry_matrix_first_run' else 'entry_matrix_change' end;
    if v_first or security.pipeline_num_v1('entry.matrix_first_run_review', 1) >= 1 then
      insert into pipeline.layer4_review_items(entity_type, entity_id, field_code, evidence_id, before_value, proposed_value, layer2_state, layer3_state,
                                               status, escalation_reason, change_control_ref)
      values ('provider', r.provider_id, v_field, f.evidence_id,
              jsonb_build_object('active_rows', (select count(*) from catalogue.provider_entry_matrix m where m.provider_id = r.provider_id and m.status = 'active')),
              jsonb_build_object('run_id', r.id, 'url', f.url, 'rows', v_in, 'dropped', jsonb_array_length(v_dropped),
                'qualification_rows', v_qin,
                -- F-AER.08 (12 Nov 2026): course rows and those whose course is not linked to a catalogue course (Layer 4 course links)
                'course_rows', (select count(*) from catalogue.provider_entry_matrix m where m.run_id = r.id and m.course_label is not null)
                             + (select count(*) from catalogue.provider_qualification_requirements q where q.run_id = r.id and q.course_label is not null),
                'course_rows_unlinked', (select count(*) from catalogue.provider_entry_matrix m where m.run_id = r.id and m.course_label is not null and m.course_id is null)
                             + (select count(*) from catalogue.provider_qualification_requirements q where q.run_id = r.id and q.course_label is not null and q.course_id is null),
                'qualification_sample', (select jsonb_agg(jsonb_build_object('id', q.id, 'qualification', q.qualification_code, 'label', q.qualification_label, 'applicability', q.applicability,
                                   'level', q.level_label, 'min_grade', q.min_grade, 'min_value', q.min_value, 'scale', q.grade_scale, 'quote', q.quote) order by q.qualification_code, q.level_label)
                             from (select * from catalogue.provider_qualification_requirements q2 where q2.run_id = r.id order by q2.qualification_code, q2.level_label limit 12) q),
                'countries', (select count(distinct m.country_id) from catalogue.provider_entry_matrix m where m.run_id = r.id),
                'sample', (select jsonb_agg(jsonb_build_object('id', m.id, 'country', m.country_code, 'course', m.course_label, 'course_linked', m.course_id is not null, 'level', m.level_label, 'qualification', m.qualification_name,
                                   'min_grade', m.min_grade, 'scale', m.grade_scale, 'band', m.benchmark_band, 'quote', m.quote) order by m.country_code, m.level_label)
                             from (select * from catalogue.provider_entry_matrix m2 where m2.run_id = r.id order by m2.country_code, m2.level_label limit 12) m)),
              jsonb_build_object('source', 'entry matrix reader', 'page', f.url, 'entry_matrix_source_id', f.id), jsonb_build_object('run_id', r.id, 'model', r.model_code),
              'pending',
              case when v_first then 'Entry matrix first run: a person approves the matrix before any row is admitted (entry.matrix_first_run_review)'
                   else 'Entry matrix page changed: the new reading replaces the admitted rows only on approval' end,
              'CF-CHG-20260915-247')
      returning id into v_item;
    else
      -- changed page, review of changes off: admitted only when every row met the confidence (the first run always went to a person)
      perform security.entry_matrix_review_apply_v1(null, 'approve', null, 'entry.matrix_first_run_review 0: changed page admitted', r.id);
    end if;
  end if;
  update pipeline.entry_matrix_runs set state = 'done', done_at = now(), leased_until = null, error = null, rows_admitted = v_in,
         rows_dropped = jsonb_array_length(v_dropped), slices = nullif(p_result->>'slices', '')::int,
         result = jsonb_build_object('dropped', v_dropped, 'edition', p_result->'edition', 'worker', p_result->'worker',
                                     'prompt_version', p_result->'prompt_version', 'page_basis', p_result->'page_basis', 'completeness', p_result->'completeness', 'qualification_rows', v_qin, 'reader', p_result->'reader', 'cell_reader', p_result->'cell_reader'),
         cost_usd = cost_usd + coalesce(p_cost, 0), review_item_id = v_item, updated_at = now()
   where id = r.id;
  -- Step C (29 Oct 2026): a rendered page (entry.render_hosts) read with no row opens a Layer 4 note; a person confirms "no matrix published here"
  if v_in + v_qin = 0 and f.read_via = 'firecrawl'
     and coalesce(security.toolset_setting('pipeline', 'entry.render_hosts'), '[]'::jsonb) ? lower(substring(f.url from '^https?://(?:www\.)?([^/:?#]+)')) then
    v_item := security.entry_rendered_note_v1(r.id);
  end if;
  return jsonb_build_object('ok', true, 'status', case when v_in + v_qin = 0 then 'no_rows' when v_item is not null then 'layer4' else 'admitted' end,
                            'rows', v_in, 'qualification_rows', v_qin, 'dropped', jsonb_array_length(v_dropped), 'review_item_id', v_item);
end $$;


