CREATE OR REPLACE FUNCTION "public"."svc_lean_qualify_next_v1"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb; v_run text; v_spent numeric; v_fee jsonb := security.ai_route_v1('fee_reader'); v_int jsonb := security.ai_route_v1('course_other_fields');
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if security.pipeline_num_v1('reading.lean_qualify_on', 0) < 1 then return '[]'::jsonb; end if;
  select c.run_label into v_run from pipeline.lean_qualify_cases c where c.state = 'pending' order by c.id limit 1;
  if v_run is null then return '[]'::jsonb; end if;
  -- the hard ceiling: nothing more is handed out once the run's recorded cost reaches it
  select coalesce(sum(c.cost_usd), 0) into v_spent from pipeline.lean_qualify_cases c where c.run_label = v_run;
  if v_spent >= security.pipeline_num_v1('reading.lean_qualify_ceiling_usd', 0) then return '[]'::jsonb; end if;
  with pick as (select c.id from pipeline.lean_qualify_cases c
                 where c.run_label = v_run and c.state = 'pending' and (c.leased_until is null or c.leased_until < now()) and c.attempts < 2  -- fixed: two tries
                   and ((c.field = 'fees' and coalesce((v_fee->>'held')::boolean, true) = false and v_fee->>'model' is not null)
                     or (c.field = 'intakes' and coalesce((v_int->>'held')::boolean, true) = false and v_int->>'model' is not null))
                 order by c.id limit greatest(1, least(coalesce(p_limit, 1), 20)) for update skip locked),  -- fixed: the setting batch.lean_qualify's upper bound
  upd as (update pipeline.lean_qualify_cases c set leased_until = now() + interval '5 minutes', attempts = c.attempts + 1 from pick where c.id = pick.id  -- fixed: lease, longer than one worker call
          returning c.*)
  select coalesce(jsonb_agg(jsonb_build_object('case_id', u.id, 'field', u.field, 'kind', u.kind, 'storage_path', u.storage_path, 'gold', u.gold,
           'provider', coalesce(p.display_name, p.canonical_name), 'country', k.iso_alpha2, 'title', co.canonical_title, 'url', e.source_url,
           'profile', case when u.field = 'fees' then (select to_jsonb(cp) - 'reason' - 'updated_by' - 'updated_at' from pipeline.fee_country_profiles cp where cp.country_code = k.iso_alpha2) end,
           'courses', case when u.field = 'fees' and co.id is not null then jsonb_build_array(jsonb_build_object('id', co.id, 'title', co.canonical_title, 'level', sl.code)) else '[]'::jsonb end,
           'page_chars', security.pipeline_num_v1('fees.page_chars', 40000)::int,
           'model', case when u.field = 'fees' then v_fee->>'model' else v_int->>'model' end,
           'models', case when u.field = 'fees' then v_fee->'models' else v_int->'models' end) order by u.id), '[]'::jsonb) into v
    from upd u left join catalogue.courses co on co.id = u.course_id left join ref.study_levels sl on sl.id = co.study_level_id
    left join catalogue.providers p on p.id = co.provider_id left join ref.countries k on k.id = p.country_id
    left join pipeline.evidence_artifacts e on e.id = u.evidence_id;
  return v;
end $$;


ALTER FUNCTION "public"."svc_lean_qualify_next_v1"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_lean_qualify_next_v1"("p_limit" integer) IS 'CF-247 Lean AI Input Phase 1b-3 (worker mode lean_qualify): leases pending qualification pages with their label, course context and the service''s pinned route, while reading.lean_qualify_on is 1, the run''s recorded cost is below reading.lean_qualify_ceiling_usd and the route is not held.';



CREATE OR REPLACE FUNCTION "public"."svc_lean_qualify_record_v1"("p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int := 0;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if jsonb_typeof(p_rows) <> 'array' then return jsonb_build_object('recorded', 0); end if;
  update pipeline.lean_qualify_cases c set
     state = case when x->>'error' = 'time budget' then 'pending' when x->>'error' is not null then 'failed' when (x->>'not_negative')::boolean then 'skipped' else 'done' end,
     leased_until = null, done_at = case when x->>'error' = 'time budget' then null else now() end, result = x - 'case_id', error = left(x->>'error', 300),
     cost_usd = c.cost_usd + coalesce((x#>>'{arms,baseline,cost}')::numeric, 0) + coalesce((x#>>'{arms,candidate,cost}')::numeric, 0)
    from jsonb_array_elements(p_rows) x
   where c.id = (x->>'case_id')::bigint and c.state = 'pending';
  get diagnostics v_n = row_count;
  return jsonb_build_object('recorded', v_n);
end $$;


ALTER FUNCTION "public"."svc_lean_qualify_record_v1"("p_rows" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_lean_qualify_record_v1"("p_rows" "jsonb") IS 'CF-247 Lean AI Input Phase 1b-3 (worker mode lean_qualify): records each page''s baseline and candidate answers with their checks and cost; a page out of time goes back to pending; writes nothing else.';



CREATE OR REPLACE FUNCTION "public"."svc_lean_sections_eval_next_v1"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if security.pipeline_num_v1('reading.lean_sections_eval_on', 0) < 1 then return '[]'::jsonb; end if;
  with pick as (select c.id from pipeline.lean_section_eval_cases c
                 where c.state = 'pending' and (c.leased_until is null or c.leased_until < now())
                 order by c.id limit greatest(1, least(coalesce(p_limit, 1), 200)) for update skip locked),  -- fixed: the setting batch.lean_sections_eval's upper bound
  upd as (update pipeline.lean_section_eval_cases c set leased_until = now() + interval '5 minutes' from pick where c.id = pick.id  -- fixed: lease, longer than one worker call
          returning c.id, c.field, c.storage_path, c.gold)
  select coalesce(jsonb_agg(jsonb_build_object('case_id', upd.id, 'field', upd.field, 'storage_path', upd.storage_path, 'gold', upd.gold) order by upd.id), '[]'::jsonb) into v from upd;
  return v;
end $$;


ALTER FUNCTION "public"."svc_lean_sections_eval_next_v1"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_lean_sections_eval_next_v1"("p_limit" integer) IS 'CF-247 Lean AI Input Phase 1b step 1 (worker mode lean_sections_eval): leases pending labelled cases (stored page path, field, gold value) while reading.lean_sections_eval_on is 1.';



CREATE OR REPLACE FUNCTION "public"."svc_lean_sections_eval_record_v1"("p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int := 0;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if jsonb_typeof(p_rows) <> 'array' then return jsonb_build_object('recorded', 0); end if;
  update pipeline.lean_section_eval_cases c set
     state = case when x->>'error' is null then 'done' else 'failed' end, leased_until = null, done_at = now(),
     selector = left(x->>'selector', 40), converter = left(x->>'converter', 40), worker = left(x->>'worker', 60),
     page_chars = (x->>'page_chars')::int, cut_chars = (x->>'cut_chars')::int, lean_chars = (x->>'lean_chars')::int, lean_blocks = (x->>'lean_blocks')::int,
     gold_in_page = (x->>'gold_in_page')::boolean, gold_in_current = (x->>'gold_in_current')::boolean, gold_in_first_cut = (x->>'gold_in_first_cut')::boolean,
     gold_in_lean = (x->>'gold_in_lean')::boolean, gold_in_selection = (x->>'gold_in_selection')::boolean, no_selection = (x->>'no_selection')::boolean,
     selected_blocks = (x->>'selected_blocks')::int, selected_chars = (x->>'selected_chars')::int,
     block_ids = case when jsonb_typeof(x->'block_ids') = 'array' then x->'block_ids' end, error = left(x->>'error', 300)
    from jsonb_array_elements(p_rows) x
   where c.id = (x->>'case_id')::bigint and c.state = 'pending';
  get diagnostics v_n = row_count;
  return jsonb_build_object('recorded', v_n);
end $$;


ALTER FUNCTION "public"."svc_lean_sections_eval_record_v1"("p_rows" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_lean_sections_eval_record_v1"("p_rows" "jsonb") IS 'CF-247 Lean AI Input Phase 1b step 1 (worker mode lean_sections_eval): records each labelled case''s result (value on the page, in the first cut, in the converted page, in the selected sections; sizes; block ids).';



CREATE OR REPLACE FUNCTION "public"."svc_logo_find_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_items jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  with pick as (
    select p.id, p.canonical_name, p.website, k.iso_alpha2 country, f.requested_at
      from catalogue.providers p
      left join ref.countries k on k.id = p.country_id
      left join pipeline.provider_logo_finds f on f.provider_id = p.id
     where p.lifecycle_status = 'active' and nullif(btrim(p.website), '') is not null
       and (f.requested_at is not null or p.publication_status = 'published')  -- 22 Oct 2026 (Platform Admin 11:42): unpublished providers wait; publishing them again brings them back
       and not exists (select 1 from catalogue.provider_assets a where a.provider_id = p.id and a.is_primary and a.status = 'approved'
                        and a.asset_type in ('logo', 'logo_dark', 'logo_light'))
       and (f.provider_id is null
            or f.requested_at is not null
            or f.status = 'queued'
            or (f.status = 'trying' and f.last_tried_at < now() - interval '15 minutes')  -- fixed: claim lease, a run that died
            )
       -- CF-247 15 Oct 2026 (flag unit): a provider held (website down, logo not found) waits for its flag's recheck; a person's request goes through
       and (f.requested_at is not null or not security.flag_provider_held_v1(p.id, array['site_unreachable', 'logo_not_found']))
     order by (f.requested_at is not null) desc, f.requested_at, (select count(*) from catalogue.courses c where c.provider_id = p.id) desc, p.id
     limit greatest(p_limit, 0)
     for update of p skip locked),
  claim as (
    insert into pipeline.provider_logo_finds(provider_id, status, tries, last_tried_at, updated_at)
    select id, 'trying', 1, now(), now() from pick
    on conflict (provider_id) do update set status = 'trying', tries = pipeline.provider_logo_finds.tries + 1, last_tried_at = now(), requested_at = null, updated_at = now()
    returning provider_id)
  select coalesce(jsonb_agg(jsonb_build_object('provider_id', pick.id, 'name', pick.canonical_name, 'website', pick.website, 'country', pick.country)), '[]'::jsonb)
    into v_items from pick join claim on claim.provider_id = pick.id;
  return jsonb_build_object('items', v_items, 'min_pixels', security.pipeline_num_v1('logo.min_pixels', 64)::int);
end $$;


ALTER FUNCTION "public"."svc_logo_find_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_logo_find_record"("p_provider_id" "uuid", "p_status" "text", "p_reason" "text", "p_method" "text", "p_storage_path" "text", "p_mime_type" "text", "p_content_hash" "text", "p_width" integer, "p_height" integer, "p_source_url" "text", "p_page_url" "text", "p_evidence" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_asset uuid; v_status text := p_status; f record;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if p_status not in ('found', 'not_found', 'failed') then raise exception 'unknown status %', p_status; end if;
  if p_status = 'found' then
    if p_storage_path is null or p_content_hash is null or p_mime_type not in ('image/svg+xml', 'image/png', 'image/jpeg', 'image/webp') then raise exception 'stored logo required'; end if;
    if exists (select 1 from catalogue.provider_assets a where a.provider_id = p_provider_id and a.is_primary and a.status = 'approved' and a.asset_type in ('logo', 'logo_dark', 'logo_light')) then
      v_status := 'skipped_has_logo';  -- a person added one meanwhile: theirs stays
    else
      insert into catalogue.provider_assets(provider_id, asset_type, source_url, storage_path, mime_type, width, height, content_hash, is_primary, status, observed_at, verified_at, metadata)
      values (p_provider_id, 'logo', p_source_url, p_storage_path, p_mime_type, p_width, p_height, p_content_hash, true, 'approved', now(), now(),
              jsonb_build_object('source_class', 'website_logo_finder', 'method', p_method, 'page_url', p_page_url, 'managed_storage', true, 'change_control_ref', 'CF-CHG-20260915-247') || coalesce(p_evidence, '{}'::jsonb))
      on conflict (provider_id, asset_type, coalesce(content_hash, ''), source_url) do update
        set storage_path = excluded.storage_path, is_primary = true, status = 'approved', verified_at = now(), metadata = catalogue.provider_assets.metadata || excluded.metadata
      returning id into v_asset;
      for f in select id from pipeline.enrichment_flags where entity = 'provider' and entity_key = p_provider_id::text and reason_code in ('logo_not_found', 'site_unreachable') and state <> 'released' loop
        perform security.flag_release_v1(f.id, 'logo-find', 'auto', 'Logo found and attached', jsonb_build_object('method', p_method, 'source_url', p_source_url), false);
      end loop;
    end if;
  else
    -- CF-247 15 Oct 2026 (flag unit): a home page that does not answer holds the provider (free recheck); otherwise the logo is looked for again later
    if coalesce(p_reason, '') like 'home page not read%' then
      perform security.flag_raise_v1('provider', p_provider_id::text, p_provider_id, '', 'site_unreachable', 'Website did not answer: ' || p_reason, 'hard', 'logo-find', 'auto',
        coalesce(p_evidence, '{}'::jsonb) || jsonb_build_object('page_url', p_page_url),
        null, now() + make_interval(days => coalesce(security.flag_list_num_v1('flag.recheck_days', 0), 3)));
    else
      perform security.flag_raise_v1('provider', p_provider_id::text, p_provider_id, 'logo', 'logo_not_found', coalesce(p_reason, 'no logo on the home page'), 'hard', 'logo-find', 'auto',
        coalesce(p_evidence, '{}'::jsonb) || jsonb_build_object('page_url', p_page_url),
        null, now() + make_interval(days => security.pipeline_num_v1('logo.retry_after_days', 30)::int));
    end if;
  end if;
  update pipeline.provider_logo_finds set status = v_status, reason = p_reason, method = p_method, source_url = p_source_url, page_url = p_page_url,
         provider_asset_id = coalesce(v_asset, provider_asset_id), updated_at = now()
   where provider_id = p_provider_id;
  return jsonb_build_object('provider_id', p_provider_id, 'status', v_status, 'provider_asset_id', v_asset);
end $$;


ALTER FUNCTION "public"."svc_logo_find_record"("p_provider_id" "uuid", "p_status" "text", "p_reason" "text", "p_method" "text", "p_storage_path" "text", "p_mime_type" "text", "p_content_hash" "text", "p_width" integer, "p_height" integer, "p_source_url" "text", "p_page_url" "text", "p_evidence" "jsonb") OWNER TO "postgres";


