CREATE OR REPLACE FUNCTION "public"."svc_openrouter_balance_record"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rem numeric;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  v_rem := (p_payload->>'total_credits')::numeric - (p_payload->>'total_usage')::numeric;
  if v_rem is null then raise exception 'no balance in the reading'; end if;
  insert into pipeline.layer3_openrouter_observations(kind, payload, remaining_usd) values ('credits', p_payload, v_rem);
  return jsonb_build_object('remaining_usd', round(v_rem, 4));
end $$;


ALTER FUNCTION "public"."svc_openrouter_balance_record"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_openrouter_key_record_v1"("p_source" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare eb jsonb := case when jsonb_typeof(p_payload->'effective_budget') = 'object' then p_payload->'effective_budget' end;
        v_key numeric; v_eb numeric; v_rem numeric; v_lim numeric; v_reset text; v_scope text; v_id bigint;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if p_source not in ('poll', 'refusal') then raise exception 'source must be poll or refusal'; end if;
  v_key := nullif(p_payload->>'limit_remaining', '')::numeric;
  v_eb := nullif(eb->>'remaining_usd', '')::numeric;
  v_rem := least(v_key, v_eb);  -- least() leaves out a null: no limit on that layer
  if v_eb is not null and (v_key is null or v_eb <= v_key) then  -- the budget blocks first
    v_lim := nullif(eb->>'limit_usd', '')::numeric; v_reset := nullif(eb->>'reset_interval', ''); v_scope := coalesce(nullif(eb->>'scope', ''), 'budget');
  else
    v_lim := coalesce(nullif(p_payload->>'limit', '')::numeric, nullif(p_payload->>'limit_usd', '')::numeric);
    v_reset := coalesce(nullif(p_payload->>'limit_reset', ''), (regexp_match(coalesce(p_payload->>'message', ''), '\((daily|weekly|monthly) limit\)', 'i'))[1]);
    v_scope := 'key_limit';
  end if;
  if p_source = 'refusal' then v_rem := coalesce(v_rem, 0); end if;  -- a refusal is no room, whatever the figures say
  insert into pipeline.openrouter_key_observations (source, http, remaining_usd, limit_usd, limit_reset, scope, usage_daily, usage_weekly, usage_monthly, payload)
  values (p_source, nullif(p_payload->>'http', '')::int, v_rem, v_lim, lower(v_reset), v_scope, nullif(p_payload->>'usage_daily', '')::numeric,
          nullif(p_payload->>'usage_weekly', '')::numeric, nullif(p_payload->>'usage_monthly', '')::numeric,
          p_payload - 'label' - 'creator_user_id' - 'organization_id' - 'workspace_id')
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'source', p_source, 'remaining_usd', v_rem, 'limit_usd', v_lim, 'limit_reset', lower(v_reset), 'scope', v_scope);
end $$;


ALTER FUNCTION "public"."svc_openrouter_key_record_v1"("p_source" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ops_diagnosis_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb; v_today int; v_room int; v_ref text; v_tz text := 'Australia/Melbourne';  -- fixed: the platform's reporting time zone
        v_route jsonb := security.ai_route_v1('ops_diagnosis');  -- 13 Nov 2026: the model and the service cap come from the route
begin
  if security.pipeline_num_v1('ops.ai_diagnosis_on', 0) < 1 then return jsonb_build_object('items', '[]'::jsonb, 'held', 'ops.ai_diagnosis_on is 0'); end if;
  if coalesce((v_route->>'held')::boolean, true) then return jsonb_build_object('items', '[]'::jsonb, 'held', coalesce(v_route->>'held_reason', 'the route is held')); end if;
  if (select coalesce(sum(t.spent), 0) from security.ai_spend_today_v1() t) >= security.pipeline_num_v1('budgets.ai_daily_ceiling_usd', 14) then
    return jsonb_build_object('items', '[]'::jsonb, 'held', 'daily AI ceiling reached');
  end if;
  -- the lane's spend must count in the daily ceiling (security.ai_spend_today_v1 lists the lanes it sums)
  if not exists (select 1 from security.ai_spend_today_v1() t where t.use = 'ops_diagnose') then
    return jsonb_build_object('items', '[]'::jsonb, 'held', 'the ops_diagnose lane is not counted in the daily AI ceiling yet (security.ai_spend_today_v1)');
  end if;
  v_ref := security.ai_use_refusal_v1('ops_diagnose');  -- the existing guard: credit floor, daily ceiling, lane guard (stop mode)
  if v_ref is not null then return jsonb_build_object('items', '[]'::jsonb, 'held', v_ref); end if;
  if (select coalesce(sum(l.cost_usd), 0) from pipeline.ai_spend_ledger l where l.lane = 'ops_diagnose' and l.at >= (date_trunc('day', now() at time zone 'UTC') at time zone 'UTC'))  -- fixed: the UTC day the AI guards count
     >= security.pipeline_num_v1('ops.ai_diagnosis_usd_per_day', 0.5) then
    return jsonb_build_object('items', '[]'::jsonb, 'held', 'ops.ai_diagnosis_usd_per_day reached');
  end if;
  select count(*) into v_today from pipeline.ops_ai_diagnosis_requests q where q.state in ('leased', 'answered') and (q.requested_at at time zone v_tz)::date = (now() at time zone v_tz)::date;
  v_room := greatest(least(coalesce(p_limit, 1), security.pipeline_num_v1('ops.ai_requests_per_day', 20)::int - v_today), 0);
  with c as (select q.id from pipeline.ops_ai_diagnosis_requests q where q.state = 'queued' or (q.state = 'leased' and q.leased_until < now())
              order by q.requested_at limit v_room for update skip locked)
  update pipeline.ops_ai_diagnosis_requests q set state = 'leased', leased_until = now() + interval '10 minutes',  -- fixed: lease timer
         model = v_route->>'model'
    from c where q.id = c.id;
  select coalesce(jsonb_agg(jsonb_build_object('id', q.id, 'model', q.model, 'models', v_route->'models', 'lease_until', q.leased_until, 'contract', 'ops-diagnose-v1', 'context', q.context,
           'instructions', 'You diagnose one StudySearch integration issue from the context only. Choose exactly one root_cause from the codes in context.root_causes. '
                           || 'Give confidence from 0 to 1. Give evidence as short quotes copied exactly, character for character, from text values in the context (not paraphrased). '
                           || 'Do not propose actions, settings or code changes. Answer with one JSON object that matches response_schema and nothing else.',
           'response_schema', jsonb_build_object('type', 'object', 'required', jsonb_build_array('root_cause', 'confidence', 'evidence'), 'additionalProperties', false,
             'properties', jsonb_build_object(
               'root_cause', jsonb_build_object('type', 'string', 'enum', (select jsonb_agg(c.code order by c.code) from pipeline.ops_root_causes c)),
               'confidence', jsonb_build_object('type', 'number', 'minimum', 0, 'maximum', 1),
               'evidence', jsonb_build_object('type', 'array', 'minItems', 1, 'items', jsonb_build_object('type', 'string')),
               'reasoning', jsonb_build_object('type', 'string'))))), '[]'::jsonb) into v
    from pipeline.ops_ai_diagnosis_requests q where q.state = 'leased' and q.leased_until > now();
  return jsonb_build_object('items', v, 'contract', 'ops-diagnose-v1');
end $$;


ALTER FUNCTION "public"."svc_ops_diagnosis_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_ops_diagnosis_record"("p_id" bigint, "p_answer" "jsonb", "p_cost_usd" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare q pipeline.ops_ai_diagnosis_requests; v_ctx text; v_bad int; v_conf numeric := (p_answer->>'confidence')::numeric; v_applied boolean := false; i pipeline.integration_issues;
begin
  select * into q from pipeline.ops_ai_diagnosis_requests where id = p_id for update;
  if not found or q.state <> 'leased' then raise exception 'no leased AI diagnosis request %', p_id using errcode = 'P0002'; end if;
  -- a worker error is recorded (with any cost spent) and the request is not retried
  if p_answer ? 'error' then
    update pipeline.ops_ai_diagnosis_requests set state = 'refused', answer = p_answer, cost_usd = p_cost_usd, answered_at = now(),
           note = left('worker error: ' || (p_answer->>'error'), 300) where id = p_id;
    return jsonb_build_object('id', p_id, 'state', 'refused', 'reason', 'worker error');
  end if;
  -- quotes are checked against the context's text values (not its JSON text, where quotation marks are escaped)
  v_ctx := (select string_agg(x #>> '{}', E'\n') from jsonb_path_query(q.context, 'strict $.** ? (@.type() == "string")') x);
  select count(*) into v_bad from jsonb_array_elements_text(coalesce(p_answer->'evidence', '[]'::jsonb)) e where position(e in v_ctx) = 0;
  if not exists (select 1 from pipeline.ops_root_causes c where c.code = p_answer->>'root_cause') or v_conf is null or v_conf < 0 or v_conf > 1
     or jsonb_array_length(coalesce(p_answer->'evidence', '[]'::jsonb)) = 0 or v_bad > 0 then
    update pipeline.ops_ai_diagnosis_requests set state = 'refused', answer = p_answer, cost_usd = p_cost_usd, answered_at = now(),
           note = 'refused: unknown root cause, confidence outside 0 to 1, or evidence not quoted from the context' where id = p_id;
    return jsonb_build_object('id', p_id, 'state', 'refused');
  end if;
  select * into i from pipeline.integration_issues where id = q.issue_id for update;
  if v_conf >= security.pipeline_num_v1('ops.ai_min_confidence', 0.5) and v_conf > coalesce((i.diagnosis->>'confidence')::numeric, 0) then
    update pipeline.integration_issues set diagnosis = coalesce(diagnosis, '{}'::jsonb) || jsonb_build_object('root_cause', p_answer->>'root_cause', 'confidence', v_conf,
             'evidence', p_answer->'evidence', 'method', 'ai_assisted', 'at', now(), 'model', q.model, 'deterministic', i.diagnosis->>'root_cause', 'request', p_id),
           next_action_at = now() where id = q.issue_id;
    v_applied := true;
  end if;
  update pipeline.ops_ai_diagnosis_requests set state = 'answered', answer = p_answer, cost_usd = p_cost_usd, answered_at = now(),
         note = case when v_applied then 'applied to the diagnosis' else 'kept as advice (confidence not above the deterministic diagnosis or the minimum)' end where id = p_id;
  return jsonb_build_object('id', p_id, 'state', 'answered', 'applied', v_applied);
end $_$;


ALTER FUNCTION "public"."svc_ops_diagnosis_record"("p_id" bigint, "p_answer" "jsonb", "p_cost_usd" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_pilot_automation_authorize"("p_key" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline', 'extensions'
    AS $$
  select coalesce((
    select k.enabled
      and (k.expires_at is null or k.expires_at > now())
      and k.key_hash = encode(extensions.digest(convert_to(coalesce(p_key,''),'UTF8'),'sha256'),'hex')
    from pipeline.pilot_automation_keys k
    where k.name='coursefinder_pilot_automation'
  ), false);
$$;


