CREATE OR REPLACE FUNCTION "public"."svc_programme_next"("p_limit" integer DEFAULT 40) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb; v_max int := security.pipeline_num_v1('programme.read_attempts', 3)::int;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  with pick as (select c.id from pipeline.programme_candidates c
                 where c.state in ('found', 'failed') and c.read_attempts < v_max and c.next_read_at <= now() and coalesce(c.leased_until, '-infinity') < now()
                 order by c.state = 'failed', c.found_at limit greatest(1, least(coalesce(p_limit, 40), 100))  -- fixed: per-call safety cap; the run size is batch.programme_read
                 for update skip locked),
       upd as (update pipeline.programme_candidates c set leased_until = now() + interval '10 minutes', read_attempts = c.read_attempts + 1, updated_at = now()  -- fixed: lease for one call
                 from pick where c.id = pick.id returning c.id, c.provider_id, c.url)
  select coalesce(jsonb_agg(jsonb_build_object('id', u.id, 'provider_id', u.provider_id, 'url', u.url)), '[]'::jsonb) into v from upd u;
  return v;
end $$;


ALTER FUNCTION "public"."svc_programme_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_programme_record"("p_id" bigint, "p_result" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_c pipeline.programme_candidates; v_country text; v_heading text; v_title text; v_level text; v_status text := coalesce(p_result->>'status', 'failed');
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into v_c from pipeline.programme_candidates where id = p_id;
  if v_c.id is null then return jsonb_build_object('error', 'unknown candidate'); end if;
  v_country := security.coverage_country(v_c.provider_id);
  -- 23 Oct 2026: jsonb cannot hold a null character, so none reaches here (the worker removes them); chr(0) itself is refused by PostgreSQL
  v_heading := nullif(btrim(left(p_result->>'heading', 300)), '');
  v_title := nullif(btrim(left(coalesce(p_result->>'og_title', p_result->>'title'), 300)), '');
  if v_status in ('read', 'too_thin') and coalesce(v_heading, v_title) is not null then
    v_level := coalesce(security.credential_level_v1(v_country, v_heading), security.credential_level_v1(v_country, v_title));
    update pipeline.programme_candidates set state = 'read', heading = coalesce(v_heading, v_title), page_title = v_title, final_url = p_result->>'final_url',
           study_level_code = v_level, http_status = (p_result->>'http')::int, fetched_via = p_result->>'via', read_at = now(), leased_until = null, updated_at = now(),
           outcome = case when v_level is null then 'no_level' end
     where id = p_id;
  else
    update pipeline.programme_candidates set state = case when v_status = 'gone' then 'gone' else 'failed' end, http_status = (p_result->>'http')::int,
           fetched_via = p_result->>'via', read_at = now(), leased_until = null, updated_at = now(), outcome = v_status,
           next_read_at = now() + interval '1 day'  -- fixed: a failed page is tried again the next day
     where id = p_id;
  end if;
  return jsonb_build_object('level', v_level);
end $$;


ALTER FUNCTION "public"."svc_programme_record"("p_id" bigint, "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_programme_source_next"("p_limit" integer DEFAULT 4) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  with pick as (select s.id from pipeline.programme_sources s
                 where s.status <> 'stopped' and s.next_read_at <= now() and coalesce(s.leased_until, '-infinity') < now()
                 order by s.next_read_at limit greatest(1, least(coalesce(p_limit, 4), 20))  -- fixed: per-call safety cap; the run size is batch.programme_discover
                 for update skip locked),
       upd as (update pipeline.programme_sources s set leased_until = now() + interval '10 minutes', updated_at = now()  -- fixed: lease for one call
                 from pick where s.id = pick.id returning s.*)
  select coalesce(jsonb_agg(jsonb_build_object('id', u.id, 'provider_id', u.provider_id, 'url', u.url, 'kind', u.kind, 'url_pattern', u.url_pattern,
           'child_pattern', u.child_pattern, 'read_via', u.read_via, 'max_urls', security.pipeline_num_v1('programme.max_urls', 3000)::int)), '[]'::jsonb) into v from upd u;
  return v;
end $$;


ALTER FUNCTION "public"."svc_programme_source_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_programme_source_record"("p_id" bigint, "p_status" "text", "p_http" integer, "p_via" "text", "p_urls" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_s pipeline.programme_sources; v_found int := 0; v_new int := 0;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into v_s from pipeline.programme_sources where id = p_id;
  if v_s.id is null then return jsonb_build_object('error', 'unknown source'); end if;
  if p_status = 'read' and jsonb_typeof(p_urls) = 'array' then
    with u as (select distinct on (x->>'url') x->>'url' url, nullif(left(x->>'title', 300), '') title
                 from jsonb_array_elements(p_urls) x where x->>'url' ~* '^https?://' and x->>'url' ~* v_s.url_pattern),
         ins as (insert into pipeline.programme_candidates(provider_id, programme_source_id, url, link_title)
                 select v_s.provider_id, v_s.id, u.url, u.title from u on conflict (provider_id, url) do nothing returning 1)
    select (select count(*) from u), (select count(*) from ins) into v_found, v_new;
  end if;
  update pipeline.programme_sources ps set status = case when p_status in ('read', 'blocked', 'gone') then p_status else 'failed' end,
         http_status = p_http, fetched_via = p_via, found = case when p_status = 'read' then v_found else ps.found end,
         found_new = case when p_status = 'read' then v_new else ps.found_new end, read_at = now(), leased_until = null, updated_at = now(),
         next_read_at = now() + make_interval(days => case when p_status = 'read' then security.pipeline_num_v1('programme.reread_days', 30)::int else 1 end)  -- fixed: a failed read is tried the next day
   where ps.id = p_id;
  return jsonb_build_object('found', v_found, 'new', v_new);
end $$;


ALTER FUNCTION "public"."svc_programme_source_record"("p_id" bigint, "p_status" "text", "p_http" integer, "p_via" "text", "p_urls" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_asset_access_descriptor"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'public'
    AS $$
  select coalesce((
    select jsonb_build_object(
      'provider_id',a.provider_id,
      'provider_asset_id',a.id,
      'asset_type',a.asset_type,
      'storage_path',a.storage_path,
      'mime_type',a.mime_type,
      'content_hash',a.content_hash,
      'verified_at',a.verified_at,
      'source_url',a.source_url
    )
    from catalogue.provider_assets a
    where a.provider_id=p_provider_id
      and a.is_primary
      and a.status='approved'
      and a.asset_type in('logo','logo_dark','logo_light')
      and a.storage_path is not null
    order by
      case a.asset_type when 'logo' then 0 when 'logo_light' then 1 else 2 end,
      a.verified_at desc nulls last,
      a.id
    limit 1
  ),'{}'::jsonb)
$$;


ALTER FUNCTION "public"."svc_provider_asset_access_descriptor"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_asset_access_descriptors"("p_stable_keys" "text"[]) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'public'
    AS $$
  with requested as (
    select distinct nullif(btrim(x),'') stable_key from unnest(coalesce(p_stable_keys,array[]::text[])) x
  ), matched as (
    select p.stable_key,p.id provider_id,a.id provider_asset_id,a.asset_type,a.storage_path,a.mime_type,a.content_hash,a.verified_at,a.source_url
    from requested r
    join catalogue.providers p on p.stable_key=r.stable_key
    left join lateral (
      select x.* from catalogue.provider_assets x
      where x.provider_id=p.id and x.is_primary and x.status='approved'
        and x.asset_type in('logo','logo_dark','logo_light') and x.storage_path is not null
      order by case x.asset_type when 'logo' then 0 when 'logo_light' then 1 else 2 end,
               x.verified_at desc nulls last,x.id
      limit 1
    ) a on true
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'stable_key',stable_key,'provider_id',provider_id,'provider_asset_id',provider_asset_id,
    'asset_type',asset_type,'storage_path',storage_path,'mime_type',mime_type,'content_hash',content_hash,
    'verified_at',verified_at,'source_url',source_url
  ) order by stable_key),'[]'::jsonb) from matched
$$;


ALTER FUNCTION "public"."svc_provider_asset_access_descriptors"("p_stable_keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_asset_manual_upload_apply"("p_provider_id" "uuid", "p_storage_path" "text", "p_mime_type" "text", "p_content_hash" "text", "p_actor_id" "uuid", "p_source_url" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'security', 'public'
    AS $$
declare v_asset_id uuid;v_source_url text;v_source_class text;
begin
  if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
  if not exists(select 1 from catalogue.providers p where p.id=p_provider_id) then raise exception 'provider_not_found' using errcode='P0002'; end if;
  if nullif(p_storage_path,'') is null or nullif(p_content_hash,'') is null then raise exception 'stored_asset_hash_required' using errcode='23514'; end if;
  if p_mime_type not in ('image/svg+xml','image/png','image/jpeg','image/webp') then raise exception 'unsupported_asset_mime' using errcode='23514'; end if;
  v_source_url:=coalesce(nullif(btrim(p_source_url),''),'manual-upload://provider/'||p_provider_id::text||'/logo/'||p_content_hash);
  v_source_class:=case when nullif(btrim(p_source_url),'') is null then 'manual_admin_upload' else 'manual_admin_url_import' end;
  update catalogue.provider_assets set is_primary=false,status=case when status='approved' then 'superseded' else status end
   where provider_id=p_provider_id and is_primary and asset_type in ('logo','logo_dark','logo_light');
  select id into v_asset_id from catalogue.provider_assets
   where provider_id=p_provider_id and asset_type='logo' and coalesce(content_hash,'')=p_content_hash and source_url=v_source_url
   order by verified_at desc nulls last,id limit 1;
  if v_asset_id is null then
    insert into catalogue.provider_assets(provider_id,asset_type,source_url,evidence_id,storage_path,mime_type,width,height,content_hash,is_primary,status,observed_at,verified_at,metadata)
    values(p_provider_id,'logo',v_source_url,null,p_storage_path,p_mime_type,null,null,p_content_hash,true,'approved',now(),now(),jsonb_build_object('source_class',v_source_class,'uploaded_by',p_actor_id,'uploaded_at',now(),'change_control_ref','CF-CHG-20260904-103','managed_storage',true,'source_url',nullif(btrim(p_source_url),'')))
    returning id into v_asset_id;
  else
    update catalogue.provider_assets set storage_path=p_storage_path,mime_type=p_mime_type,is_primary=true,status='approved',verified_at=now(),metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('source_class',v_source_class,'uploaded_by',p_actor_id,'uploaded_at',now(),'change_control_ref','CF-CHG-20260904-103','managed_storage',true,'source_url',nullif(btrim(p_source_url),''))
    where id=v_asset_id;
  end if;
  return jsonb_build_object('provider_id',p_provider_id,'provider_asset_id',v_asset_id,'storage_path',p_storage_path,'content_hash',p_content_hash,'source_url',v_source_url,'primary',true,'status','approved');
end
$$;


ALTER FUNCTION "public"."svc_provider_asset_manual_upload_apply"("p_provider_id" "uuid", "p_storage_path" "text", "p_mime_type" "text", "p_content_hash" "text", "p_actor_id" "uuid", "p_source_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_contact_import_apply"("p_batch_id" "uuid", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline'
    AS $$
declare
 v_batch pipeline.provider_contact_import_batches%rowtype;r pipeline.provider_contact_import_rows%rowtype;v_contact pipeline.provider_contacts%rowtype;
 v_contact_id uuid;v_version_id uuid;v_old_version uuid;v_identity text;v_current_core text;v_row_core text;
 v_created int:=0;v_updated int:=0;v_restored int:=0;v_unchanged int:=0;v_skipped int:=0;v_failed int:=0;v_error text;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service role required' using errcode='42501'; end if;
 if p_actor is null then raise exception 'actor required' using errcode='22023'; end if;
 select * into v_batch from pipeline.provider_contact_import_batches where id=p_batch_id for update;
 if not found then raise exception 'Provider Contact import not found' using errcode='P0002'; end if;
 if v_batch.status='uploaded' then raise exception 'validate import before apply' using errcode='22023'; end if;
 if v_batch.status='applied' then return jsonb_build_object('ok',true,'batch_id',p_batch_id,'unchanged',true,'summary',v_batch.apply_summary); end if;

 for r in select * from pipeline.provider_contact_import_rows where batch_id=p_batch_id order by row_number loop
  if r.applied_action is not null then continue; end if;
  if r.proposed_action='unchanged' then update pipeline.provider_contact_import_rows set applied_action='unchanged',applied_at=now() where id=r.id;v_unchanged:=v_unchanged+1;continue;
  elsif r.proposed_action in ('duplicate','provider_unmatched','provider_ambiguous','invalid','conflict') then update pipeline.provider_contact_import_rows set applied_action='skipped',applied_at=now() where id=r.id;v_skipped:=v_skipped+1;continue;
  end if;

  begin
   v_contact_id:=r.matched_contact_id;v_identity:=split_part(coalesce(r.logical_key,''),'|',2);
   if r.proposed_action='create' then
    insert into pipeline.provider_contacts(provider_id,record_type,lifecycle_status,identity_key,created_by,updated_by,metadata)
    values(r.mapped_provider_id,coalesce(nullif(r.source_payload->>'contact_record_type',''),'named_staff'),'active',v_identity,p_actor,p_actor,
     jsonb_build_object('origin','import','import_batch_id',p_batch_id,'change_control','CF-CHG-20260902-080'))
    on conflict(provider_id,identity_key) where identity_key is not null do nothing returning id into v_contact_id;
    if v_contact_id is null then select id into v_contact_id from pipeline.provider_contacts where provider_id=r.mapped_provider_id and identity_key=v_identity limit 1;
     if v_contact_id is null then raise exception 'concurrent contact identity conflict'; end if;
    end if;
    v_version_id:=security.provider_contact_append_version(v_contact_id,p_actor,r.normalized_payload,'import','first_party','Provider Contact CSV import create',p_batch_id,r.id,v_batch.evidence_artifact_id,null);
    insert into pipeline.provider_contact_audit_events(contact_id,batch_id,event_type,actor_id,reason,after_version_id,metadata)
    values(v_contact_id,p_batch_id,'import_create',p_actor,'Provider Contact CSV import create',v_version_id,jsonb_build_object('import_row_id',r.id,'change_control','CF-CHG-20260902-080'));
    update pipeline.provider_contact_import_rows set matched_contact_id=v_contact_id,applied_action='create',applied_at=now() where id=r.id;v_created:=v_created+1;

   elsif r.proposed_action='update' then
    select * into v_contact from pipeline.provider_contacts where id=v_contact_id for update;
    if not found then raise exception 'matched contact disappeared'; end if;if v_contact.lifecycle_status='deleted' then raise exception 'contact became deleted after validation'; end if;
    v_old_version:=v_contact.current_version_id;
    v_version_id:=security.provider_contact_append_version(v_contact_id,p_actor,r.normalized_payload,'import','first_party','Provider Contact CSV import update',p_batch_id,r.id,v_batch.evidence_artifact_id,null);
    insert into pipeline.provider_contact_audit_events(contact_id,batch_id,event_type,actor_id,reason,before_version_id,after_version_id,metadata)
    values(v_contact_id,p_batch_id,'import_update',p_actor,'Provider Contact CSV import update',v_old_version,v_version_id,jsonb_build_object('import_row_id',r.id,'change_control','CF-CHG-20260902-080'));
    update pipeline.provider_contact_import_rows set applied_action='update',applied_at=now() where id=r.id;v_updated:=v_updated+1;

   elsif r.proposed_action='restore' then
    select * into v_contact from pipeline.provider_contacts where id=v_contact_id for update;if not found then raise exception 'matched contact disappeared'; end if;
    v_old_version:=v_contact.current_version_id;
    select security.provider_contact_core_hash(jsonb_build_object('full_name',cv.full_name,'team_name',cv.team_name,'job_title',cv.job_title,'functional_area',cv.functional_area,
     'region_scope',cv.region_scope,'countries_or_markets',cv.countries_or_markets,'work_email',cv.work_email,'work_phone',cv.work_phone,'staff_location',cv.staff_location,
     'verification_state',cv.verification_state,'verified_on',case when cv.verified_on is null then null else cv.verified_on::text end,'source_url',cv.source_url))
    into v_current_core from pipeline.provider_contact_versions cv where cv.id=v_contact.current_version_id;
    v_row_core:=security.provider_contact_core_hash(r.normalized_payload);
    update pipeline.provider_contacts set lifecycle_status='active',deleted_at=null,deleted_by=null,delete_reason=null,restored_at=now(),restored_by=p_actor,updated_at=now(),updated_by=p_actor where id=v_contact_id;
    if v_current_core is distinct from v_row_core then
     v_version_id:=security.provider_contact_append_version(v_contact_id,p_actor,r.normalized_payload,'import','first_party','Provider Contact CSV import restore/update',p_batch_id,r.id,v_batch.evidence_artifact_id,null);
    else v_version_id:=v_old_version;end if;
    insert into pipeline.provider_contact_audit_events(contact_id,batch_id,event_type,actor_id,reason,before_version_id,after_version_id,metadata)
    values(v_contact_id,p_batch_id,'restore',p_actor,'Provider Contact CSV import restore',v_old_version,v_version_id,jsonb_build_object('import_row_id',r.id,'change_control','CF-CHG-20260902-080'));
    update pipeline.provider_contact_import_rows set applied_action='restore',applied_at=now() where id=r.id;v_restored:=v_restored+1;
   else raise exception 'unsupported proposed action %',r.proposed_action;
   end if;
  exception when others then
   get stacked diagnostics v_error=message_text;
   update pipeline.provider_contact_import_rows set applied_action='failed',applied_at=now(),conflict_detail=coalesce(conflict_detail,'{}'::jsonb)||jsonb_build_object('apply_error',v_error) where id=r.id;
   v_failed:=v_failed+1;
  end;
 end loop;

 update pipeline.provider_contact_import_batches set status=case when v_failed>0 then 'partial' else 'applied' end,applied_at=now(),
 apply_summary=jsonb_build_object('created',v_created,'updated',v_updated,'restored',v_restored,'unchanged',v_unchanged,'skipped',v_skipped,'failed',v_failed,'applied_by',p_actor,'applied_at',now())
 where id=p_batch_id;
 insert into pipeline.provider_contact_audit_events(batch_id,event_type,actor_id,reason,metadata)
 values(p_batch_id,'import_apply',p_actor,'Provider Contact CSV batch apply',jsonb_build_object('created',v_created,'updated',v_updated,'restored',v_restored,'unchanged',v_unchanged,'skipped',v_skipped,'failed',v_failed,'change_control','CF-CHG-20260902-080'));
 return jsonb_build_object('ok',v_failed=0,'batch_id',p_batch_id,'summary',jsonb_build_object('created',v_created,'updated',v_updated,'restored',v_restored,'unchanged',v_unchanged,'skipped',v_skipped,'failed',v_failed));
end $$;


ALTER FUNCTION "public"."svc_provider_contact_import_apply"("p_batch_id" "uuid", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_contact_import_finalize_review_state"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline'
    AS $$
declare
  v_pending int:=0;
  v_resolved int:=0;
  v_status text;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service role required' using errcode='42501';
  end if;

  select count(*) filter(where l.status='pending'),
         count(*) filter(where l.status<>'pending')
  into v_pending,v_resolved
  from pipeline.provider_contact_import_rows r
  join pipeline.layer4_review_items l on l.id=r.layer4_review_item_id
  where r.batch_id=p_batch_id;

  update pipeline.provider_contact_import_rows r
  set applied_action='parked_layer4',applied_at=coalesce(applied_at,now())
  from pipeline.layer4_review_items l
  where r.batch_id=p_batch_id
    and l.id=r.layer4_review_item_id
    and l.status='pending'
    and coalesce(r.applied_action,'') in ('','skipped');

  update pipeline.provider_contact_import_batches
  set status=case
        when status='partial' then 'partial'
        when v_pending>0 then 'applied_with_review_pending'
        else 'applied'
      end,
      apply_summary=coalesce(apply_summary,'{}'::jsonb)||
        jsonb_build_object('layer4_review_pending',v_pending,'layer4_resolved',v_resolved)
  where id=p_batch_id
  returning status into v_status;

  return jsonb_build_object('ok',true,'batch_id',p_batch_id,'status',v_status,'layer4_review_pending',v_pending,'layer4_resolved',v_resolved);
end $$;


ALTER FUNCTION "public"."svc_provider_contact_import_finalize_review_state"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_contact_import_park_layer4"("p_batch_id" "uuid", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'catalogue'
    AS $$
declare
  v_batch pipeline.provider_contact_import_batches%rowtype;
  r pipeline.provider_contact_import_rows%rowtype;
  v_prior pipeline.provider_contact_import_rows%rowtype;
  v_review_id uuid;
  v_before jsonb;
  v_layer2 jsonb;
  v_candidates jsonb;
  v_reason text;
  v_count int:=0;
  v_actions jsonb;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service role required' using errcode='42501';
  end if;
  if p_actor is null then raise exception 'actor required' using errcode='22023'; end if;

  select * into v_batch from pipeline.provider_contact_import_batches where id=p_batch_id for update;
  if not found then raise exception 'Provider Contact import not found' using errcode='P0002'; end if;
  if v_batch.status not in ('validated','uploaded') then
    return jsonb_build_object('ok',true,'batch_id',p_batch_id,'unchanged',true,'status',v_batch.status);
  end if;

  -- A repeated logical key is auto-skip only when it is the same source row semantics.
  -- Legacy/merged labels or differing payloads are judgement calls and move to L4.
  for r in
    select *
    from pipeline.provider_contact_import_rows
    where batch_id=p_batch_id
      and proposed_action in ('duplicate','provider_ambiguous','conflict')
    order by row_number
  loop
    if r.layer4_review_item_id is not null then continue; end if;

    v_before:=null;
    v_candidates:='[]'::jsonb;
    v_reason:=null;

    if r.proposed_action='duplicate' then
      select * into v_prior
      from pipeline.provider_contact_import_rows
      where batch_id=p_batch_id
        and logical_key=r.logical_key
        and row_number<r.row_number
      order by row_number
      limit 1;

      if not found then continue; end if;

      -- Exact repeat remains deterministic skip. Different legacy/source label or payload parks for human resolution.
      if coalesce(v_prior.source_institution_name,'')=coalesce(r.source_institution_name,'')
         and v_prior.normalized_payload=r.normalized_payload then
        continue;
      end if;

      v_before:=jsonb_build_object(
        'prior_import_row_id',v_prior.id,
        'prior_row_number',v_prior.row_number,
        'source_institution_name',v_prior.source_institution_name,
        'current_institution_name',v_prior.current_institution_name,
        'normalized_payload',v_prior.normalized_payload
      );
      v_reason:='duplicate_candidate_requires_human_resolution';

    elsif r.proposed_action='conflict' then
      select jsonb_build_object(
        'contact_id',c.id,'provider_id',c.provider_id,'record_type',c.record_type,'lifecycle_status',c.lifecycle_status,
        'version_id',v.id,'version_no',v.version_no,'full_name',v.full_name,'team_name',v.team_name,'job_title',v.job_title,
        'functional_area',v.functional_area,'region_scope',v.region_scope,'countries_or_markets',v.countries_or_markets,
        'work_email',v.work_email,'work_phone',v.work_phone,'staff_location',v.staff_location,
        'verification_state',v.verification_state,'verified_on',v.verified_on,'source_class',v.source_class,
        'source_authority',v.source_authority,'source_url',v.source_url,'source_page_title',v.source_page_title
      ) into v_before
      from pipeline.provider_contacts c
      left join pipeline.provider_contact_versions v on v.id=c.current_version_id
      where c.id=r.matched_contact_id;
      v_reason:='manual_current_version_conflicts_with_import';

    elsif r.proposed_action='provider_ambiguous' then
      select coalesce(jsonb_agg(jsonb_build_object(
        'provider_id',p.id,'stable_key',p.stable_key,'provider_name',p.canonical_name
      ) order by p.canonical_name,p.stable_key),'[]'::jsonb)
      into v_candidates
      from catalogue.providers p
      where p.id in (
        select value::uuid
        from jsonb_array_elements_text(
          coalesce(r.conflict_detail#>'{provider_mapping,candidate_provider_ids}','[]'::jsonb)
        )
      );
      v_before:=jsonb_build_object('candidate_providers',v_candidates);
      v_reason:='provider_mapping_ambiguous';
    end if;

    v_layer2:=jsonb_strip_nulls(jsonb_build_object(
      'domain','provider_contact_import',
      'import_batch_id',p_batch_id,
      'import_row_id',r.id,
      'row_number',r.row_number,
      'classification',r.proposed_action,
      'logical_key',r.logical_key,
      'source_institution_name',r.source_institution_name,
      'current_institution_name',r.current_institution_name,
      'mapped_provider_id',r.mapped_provider_id,
      'matched_contact_id',r.matched_contact_id,
      'candidate_providers',v_candidates,
      'validation_errors',r.validation_errors,
      'conflict_detail',r.conflict_detail
    ));

    insert into pipeline.layer4_review_items(
      entity_type,entity_id,field_code,evidence_id,before_value,proposed_value,
      layer2_state,layer3_state,status,escalation_reason,change_control_ref
    ) values (
      'provider_contact_import_row',r.id,'provider_contact_reconciliation',v_batch.evidence_artifact_id,
      v_before,r.normalized_payload,v_layer2,
      jsonb_build_object('source','provider-contact-csv-v1','human_review_reason',v_reason),
      'pending',v_reason,'CF-CHG-20260902-080'
    )
    returning id into v_review_id;

    update pipeline.provider_contact_import_rows
    set layer4_review_item_id=v_review_id,
        conflict_detail=coalesce(conflict_detail,'{}'::jsonb)||
          jsonb_build_object('layer4_review_item_id',v_review_id,'layer4_reason',v_reason)
    where id=r.id;

    v_count:=v_count+1;
  end loop;

  select jsonb_object_agg(proposed_action,n) into v_actions
  from (
    select proposed_action,count(*) n
    from pipeline.provider_contact_import_rows
    where batch_id=p_batch_id
    group by proposed_action
  ) s;

  update pipeline.provider_contact_import_batches
  set status='validated',
      dry_run_summary=jsonb_build_object(
        'rows',(select count(*) from pipeline.provider_contact_import_rows where batch_id=p_batch_id),
        'actions',coalesce(v_actions,'{}'::jsonb),
        'layer4_review_pending',(select count(*) from pipeline.provider_contact_import_rows rr
          join pipeline.layer4_review_items l on l.id=rr.layer4_review_item_id
          where rr.batch_id=p_batch_id and l.status='pending'),
        'parser_version',parser_version,
        'validated_by',p_actor,
        'validated_at',coalesce(validated_at,now())
      )
  where id=p_batch_id;

  return jsonb_build_object(
    'ok',true,'batch_id',p_batch_id,'layer4_created',v_count,
    'layer4_review_pending',(select count(*) from pipeline.provider_contact_import_rows rr
      join pipeline.layer4_review_items l on l.id=rr.layer4_review_item_id
      where rr.batch_id=p_batch_id and l.status='pending'),
    'actions',coalesce(v_actions,'{}'::jsonb)
  );
end $$;


ALTER FUNCTION "public"."svc_provider_contact_import_park_layer4"("p_batch_id" "uuid", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_contact_import_register"("p_country_code" "text", "p_original_filename" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_content_hash" "text", "p_storage_path" "text", "p_uploaded_by" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'pipeline'
    AS $_$
declare v_existing uuid;v_evidence uuid;v_batch uuid;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service role required' using errcode='42501'; end if;
 if upper(coalesce(p_country_code,'')) !~ '^[A-Z]{2}$' then raise exception 'valid country code required' using errcode='22023'; end if;
 if coalesce(btrim(p_original_filename),'')='' then raise exception 'original filename required' using errcode='22023'; end if;
 if p_byte_size is null or p_byte_size<=0 then raise exception 'positive byte size required' using errcode='22023'; end if;
 if coalesce(btrim(p_content_hash),'')='' then raise exception 'content hash required' using errcode='22023'; end if;
 if coalesce(btrim(p_storage_path),'')='' then raise exception 'storage path required' using errcode='22023'; end if;
 if p_uploaded_by is null then raise exception 'uploader required' using errcode='22023'; end if;

 select id into v_existing from pipeline.provider_contact_import_batches where content_hash=p_content_hash limit 1;
 if v_existing is not null then return jsonb_build_object('duplicate',true,'batch_id',v_existing); end if;

 insert into pipeline.evidence_artifacts(evidence_type,storage_path,content_hash,mime_type,captured_at,metadata,retention_class,review_state,capture_version,evidence_group_key)
 values('provider_contact_import_file',p_storage_path,p_content_hash,p_mime_type,now(),
  jsonb_build_object('country_code',upper(p_country_code),'original_filename',p_original_filename,'byte_size',p_byte_size,'uploaded_by',p_uploaded_by,
   'manual_upload',true,'parser_contract','provider-contact-csv-v1','change_control','CF-CHG-20260902-080'),
  'source_evidence','pending_review',1,'provider_contacts:'||upper(p_country_code))
 returning id into v_evidence;

 insert into pipeline.provider_contact_import_batches(country_code,evidence_artifact_id,original_filename,mime_type,byte_size,content_hash,storage_path,uploaded_by,metadata)
 values(upper(p_country_code),v_evidence,p_original_filename,p_mime_type,p_byte_size,p_content_hash,p_storage_path,p_uploaded_by,jsonb_build_object('change_control','CF-CHG-20260902-080'))
 returning id into v_batch;

 return jsonb_build_object('duplicate',false,'batch_id',v_batch,'evidence_id',v_evidence,'status','uploaded');
end $_$;


ALTER FUNCTION "public"."svc_provider_contact_import_register"("p_country_code" "text", "p_original_filename" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_content_hash" "text", "p_storage_path" "text", "p_uploaded_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_contact_import_validate"("p_batch_id" "uuid", "p_rows" "jsonb", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'pipeline', 'catalogue'
    AS $_$
declare
 v_batch pipeline.provider_contact_import_batches%rowtype;v_row jsonb;v_ord bigint;v_map jsonb;v_provider uuid;v_mapping_state text;
 v_record_type text;v_full_name text;v_job_title text;v_function text;v_region text;v_markets text;v_email text;v_phone text;v_location text;
 v_verify text;v_verified text;v_source_url text;v_source_title text;v_notes text;v_identity text;v_logical text;v_errors jsonb;v_action text;
 v_matched uuid;v_lifecycle text;v_current_source text;v_current_core text;v_row_core text;v_norm_payload jsonb;v_counts jsonb;v_domain text;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service role required' using errcode='42501'; end if;
 if p_actor is null then raise exception 'actor required' using errcode='22023'; end if;
 if jsonb_typeof(p_rows)<>'array' then raise exception 'rows array required' using errcode='22023'; end if;
 select * into v_batch from pipeline.provider_contact_import_batches where id=p_batch_id for update;
 if not found then raise exception 'Provider Contact import not found' using errcode='P0002'; end if;
 if v_batch.status in ('applied','partial') then raise exception 'applied import cannot be revalidated' using errcode='22023'; end if;

 delete from pipeline.provider_contact_import_rows where batch_id=p_batch_id;
 for v_row,v_ord in select value,ordinality from jsonb_array_elements(p_rows) with ordinality loop
  v_errors:='[]'::jsonb;v_provider:=null;v_matched:=null;v_lifecycle:=null;v_current_source:=null;v_current_core:=null;
  v_record_type:=lower(btrim(coalesce(v_row->>'contact_record_type','')));
  v_full_name:=nullif(btrim(coalesce(v_row->>'staff_name','')),'');v_job_title:=nullif(btrim(coalesce(v_row->>'job_title','')),'');
  v_function:=nullif(btrim(coalesce(v_row->>'functional_area','')),'');v_region:=nullif(btrim(coalesce(v_row->>'region_scope','')),'');
  v_markets:=nullif(btrim(coalesce(v_row->>'countries_or_markets','')),'');v_email:=nullif(lower(btrim(coalesce(v_row->>'email',''))),'');
  v_phone:=nullif(btrim(coalesce(v_row->>'phone','')),'');v_location:=nullif(btrim(coalesce(v_row->>'staff_location','')),'');
  v_verify:=nullif(lower(btrim(coalesce(v_row->>'verification_status',''))),'');v_verified:=nullif(btrim(coalesce(v_row->>'verified_on','')),'');
  v_source_url:=nullif(btrim(coalesce(v_row->>'official_source_url','')),'');v_source_title:=nullif(btrim(coalesce(v_row->>'source_page_title','')),'');
  v_notes:=nullif(btrim(coalesce(v_row->>'notes','')),'');

  if v_record_type not in ('named_staff','team_contact') then v_errors:=v_errors||jsonb_build_array('invalid_contact_record_type'); end if;
  if v_record_type='named_staff' and v_full_name is null then v_errors:=v_errors||jsonb_build_array('named_staff_requires_staff_name'); end if;
  if coalesce(v_email,v_phone,v_job_title,v_function,v_region,v_source_url) is null then v_errors:=v_errors||jsonb_build_array('meaningful_assignment_contact_or_source_required'); end if;
  if v_email is not null then
   if v_email !~* '^[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}$' then v_errors:=v_errors||jsonb_build_array('invalid_professional_email');
   else v_domain:=split_part(v_email,'@',2);
    if v_domain in ('gmail.com','googlemail.com','yahoo.com','yahoo.com.au','hotmail.com','outlook.com','live.com','icloud.com','proton.me','protonmail.com') then
     v_errors:=v_errors||jsonb_build_array('personal_free_mail_not_permitted');
    end if;
   end if;
  end if;
  if v_source_url is not null and v_source_url !~* '^https?://' then v_errors:=v_errors||jsonb_build_array('invalid_official_source_url'); end if;
  if v_verified is not null and v_verified !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then v_errors:=v_errors||jsonb_build_array('verified_on_must_be_iso_date'); end if;

  v_map:=security.provider_contact_provider_map(v_batch.country_code,v_row->>'current_institution_name');
  v_mapping_state:=coalesce(v_map->>'state','unmatched');
  if v_mapping_state='mapped' then v_provider:=(v_map->>'provider_id')::uuid; end if;
  v_identity:=case when v_mapping_state='mapped' then security.provider_contact_identity_key(v_record_type,v_full_name,v_job_title,v_region,v_email,v_source_url) else null end;
  if v_mapping_state='mapped' and v_identity is null then v_errors:=v_errors||jsonb_build_array('insufficient_contact_identity'); end if;

  v_norm_payload:=jsonb_strip_nulls(jsonb_build_object(
   'full_name',v_full_name,'team_name',case when v_record_type='team_contact' then coalesce(v_full_name,v_function,v_job_title) else null end,
   'job_title',v_job_title,'functional_area',v_function,'region_scope',v_region,'countries_or_markets',v_markets,'work_email',v_email,'work_phone',v_phone,
   'staff_location',v_location,'verification_state',v_verify,'verified_on',v_verified,'source_class','import','source_authority','first_party',
   'source_url',v_source_url,'source_page_title',v_source_title,'source_notes',v_notes));
  v_row_core:=security.provider_contact_core_hash(v_norm_payload);
  v_logical:=case when v_provider is null or v_identity is null then null else v_provider::text||'|'||v_identity end;

  if jsonb_array_length(v_errors)>0 then v_action:='invalid';
  elsif v_mapping_state='unmatched' then v_action:='provider_unmatched';
  elsif v_mapping_state='ambiguous' then v_action:='provider_ambiguous';
  elsif exists(select 1 from pipeline.provider_contact_import_rows rr where rr.batch_id=p_batch_id and rr.logical_key=v_logical) then v_action:='duplicate';
  else
   select c.id,c.lifecycle_status,cv.source_class,security.provider_contact_core_hash(jsonb_build_object(
    'full_name',cv.full_name,'team_name',cv.team_name,'job_title',cv.job_title,'functional_area',cv.functional_area,'region_scope',cv.region_scope,
    'countries_or_markets',cv.countries_or_markets,'work_email',cv.work_email,'work_phone',cv.work_phone,'staff_location',cv.staff_location,
    'verification_state',cv.verification_state,'verified_on',case when cv.verified_on is null then null else cv.verified_on::text end,'source_url',cv.source_url))
   into v_matched,v_lifecycle,v_current_source,v_current_core
   from pipeline.provider_contacts c left join pipeline.provider_contact_versions cv on cv.id=c.current_version_id
   where c.provider_id=v_provider and c.identity_key=v_identity limit 1;

   if v_matched is null then v_action:='create';
   elsif v_current_core=v_row_core then v_action:=case when v_lifecycle='deleted' then 'restore' else 'unchanged' end;
   elsif v_current_source='manual' then v_action:='conflict';
   elsif v_lifecycle='deleted' then v_action:='restore';
   else v_action:='update';
   end if;
  end if;

  insert into pipeline.provider_contact_import_rows(batch_id,row_number,row_hash,logical_key,source_payload,normalized_payload,source_institution_name,current_institution_name,
   mapped_provider_id,mapping_state,matched_contact_id,proposed_action,validation_errors,conflict_detail)
  values(p_batch_id,v_ord::int,md5(v_row::text),v_logical,v_row,v_norm_payload,nullif(btrim(v_row->>'gug_2026_university_name'),''),
   nullif(btrim(v_row->>'current_institution_name'),''),v_provider,v_mapping_state,v_matched,v_action,v_errors,
   case when v_mapping_state='ambiguous' then jsonb_build_object('provider_mapping',v_map)
    when v_action='conflict' then jsonb_build_object('reason','manual_current_version_differs','current_contact_id',v_matched)
    when v_action='duplicate' then jsonb_build_object('reason','duplicate_logical_contact_within_batch') else '{}'::jsonb end);
 end loop;

 select jsonb_object_agg(proposed_action,n) into v_counts from (
  select proposed_action,count(*) n from pipeline.provider_contact_import_rows where batch_id=p_batch_id group by proposed_action)s;
 update pipeline.provider_contact_import_batches set status='validated',validated_at=now(),dry_run_summary=jsonb_build_object(
  'rows',jsonb_array_length(p_rows),'actions',coalesce(v_counts,'{}'::jsonb),'parser_version',parser_version,'validated_by',p_actor,'validated_at',now())
 where id=p_batch_id;
 return jsonb_build_object('ok',true,'batch_id',p_batch_id,'rows',jsonb_array_length(p_rows),'actions',coalesce(v_counts,'{}'::jsonb));
end $_$;


ALTER FUNCTION "public"."svc_provider_contact_import_validate"("p_batch_id" "uuid", "p_rows" "jsonb", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_contact_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  with cand as materialized (  -- 22 Oct 2026: the cheap filters first, so the directory-site test runs only on what is left
    select p.id, coalesce(p.display_name, p.canonical_name) name, p.website,
           (select count(*) from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active') courses
      from catalogue.providers p
     where p.lifecycle_status = 'active' and p.website ~* '^https?://' and (p.phone is null or p.email is null)
       and not exists (select 1 from pipeline.provider_contact_checks k where k.provider_id = p.id and k.kind = 'public_general' and k.checked_at > now() - make_interval(days => security.pipeline_num_v1('contact.recheck_days', 90)::int))
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id)  -- v2.15.237: paused while the provider is unpublished or archived
       and exists (select 1 from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active')),
  pick as (
    select c.id, c.name, c.website, security.coverage_country(c.id) country
      from cand c
     where not security.third_party_host_v1(c.website)
     order by c.courses desc
     limit greatest(1, least(coalesce(p_limit, 8), 20))),
  lease as (insert into pipeline.provider_contact_checks(provider_id, kind, checked_at, outcome) select id, 'public_general', now(), 'leased' from pick
            on conflict (provider_id, kind) do update set checked_at = now(), outcome = 'leased' returning provider_id)
  select coalesce(jsonb_agg(jsonb_build_object('provider_id', p.id, 'name', p.name, 'website', p.website, 'country', p.country)), '[]'::jsonb) into v
    from pick p where p.id in (select provider_id from lease);
  return v;
end $$;


ALTER FUNCTION "public"."svc_provider_contact_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_contact_record"("p_provider_id" "uuid", "p_phone" "text", "p_email" "text", "p_url" "text", "p_evidence" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_phone text := nullif(btrim(coalesce(p_phone, '')), ''); v_email text := lower(nullif(btrim(coalesce(p_email, '')), ''));
        v_prev pipeline.provider_contact_points%rowtype;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if v_email is not null and v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then v_email := null; end if;
  if v_phone is not null and length(regexp_replace(v_phone, '\D', '', 'g')) not between 8 and 15 then v_phone := null; end if;
  insert into pipeline.provider_contact_checks(provider_id, kind, checked_at, outcome, evidence)
  values (p_provider_id, 'public_general', now(), case when v_phone is null and v_email is null then 'not_found' else 'found' end, coalesce(p_evidence, '{}'::jsonb))
  on conflict (provider_id, kind) do update set checked_at = now(), outcome = excluded.outcome, evidence = excluded.evidence;
  select * into v_prev from pipeline.provider_contact_points where provider_id = p_provider_id and kind = 'public_general' and is_current;
  update pipeline.provider_contact_points set is_current = false where provider_id = p_provider_id and kind = 'public_general' and is_current;
  if v_phone is not null or v_email is not null then
    insert into pipeline.provider_contact_points(provider_id, kind, source, phone, email, source_url, evidence)
    values (p_provider_id, 'public_general', 'provider_site', v_phone, v_email, p_url, coalesce(p_evidence, '{}'::jsonb));
  end if;
  -- v2.15.235: a value this job wrote earlier is replaced (or cleared when the new read finds none); an empty value is filled; a value
  -- entered by hand is locked and kept by the manual-value guard.
  update catalogue.providers p
     set phone = case when p.phone is not distinct from v_prev.phone and v_prev.id is not null then v_phone else coalesce(p.phone, v_phone) end,
         email = case when p.email is not distinct from v_prev.email and v_prev.id is not null then v_email else coalesce(p.email, v_email) end,
         updated_at = now()
   where p.id = p_provider_id
     and ((p.phone is null and v_phone is not null) or (p.email is null and v_email is not null)
          or (v_prev.id is not null and ((p.phone is not distinct from v_prev.phone and p.phone is distinct from v_phone)
                                      or (p.email is not distinct from v_prev.email and p.email is distinct from v_email))));
end $_$;


ALTER FUNCTION "public"."svc_provider_contact_record"("p_provider_id" "uuid", "p_phone" "text", "p_email" "text", "p_url" "text", "p_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_description_cohort_next"("p_limit" integer, "p_cohort" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required' using errcode='42501'; end if;
 if not exists(select 1 from pipeline.provider_description_cohorts c where c.id=p_cohort and c.state='started') then raise exception 'unknown started cohort'; end if;
 perform set_config('cf.pdesc_cohort',p_cohort::text,true);
 perform set_config('cf.pdesc_worker_protocol','provider-description-reserve-v1',true); -- only the reservation-capable worker calls this (new in this release)
 return public.svc_provider_description_next(p_limit);
end $$;


ALTER FUNCTION "public"."svc_provider_description_cohort_next"("p_limit" integer, "p_cohort" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_description_lease_v1"("p_limit" integer, "p_cohort" "uuid" DEFAULT NULL::"uuid", "p_protocol" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required' using errcode='42501'; end if;
 if p_protocol is distinct from 'provider-description-reserve-v1' then return jsonb_build_object('idle',true,'reason','worker_protocol_required','items','[]'::jsonb); end if;
 if p_cohort is not null then return public.svc_provider_description_cohort_next(p_limit,p_cohort); end if;
 perform set_config('cf.pdesc_worker_protocol',p_protocol,true);
 return public.svc_provider_description_next(p_limit);
end $$;


ALTER FUNCTION "public"."svc_provider_description_lease_v1"("p_limit" integer, "p_cohort" "uuid", "p_protocol" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_provider_description_lease_v1"("p_limit" integer, "p_cohort" "uuid", "p_protocol" "text") IS 'Provider descriptions (validation 5 Nov 2026): the only lease for the reservation-capable coverage-sweep worker; a worker that does not declare provider-description-reserve-v1 receives no item.';



CREATE OR REPLACE FUNCTION "public"."svc_provider_description_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb; v_rt jsonb := security.ai_route_v1('provider_description'); v_model text; v_pending int; v_spent numeric; v_fc_used int; v_mach boolean := security.pipeline_num_v1('pdesc.machine_admit_on', 0) >= 1; v_cap numeric; v_afford numeric; v_od boolean; v_over boolean := false; v_pv text := security.provider_description_prompt_active_v1()->>'version'; /* 20261112010000: on demand, over a lane limit, the active prompt version */ v_fc_res int; v_fc_left int; v_ws text[]; v_stored jsonb; v_reoffer uuid[]; v_tries numeric := security.pipeline_num_v1('pdesc.tries', 3); v_acq boolean := security.pipeline_num_v1('pdesc.acquire_direct', 0) >= 1; -- the two settings the pick tests on every due read, read once
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if security.pipeline_num_v1('pdesc.enabled', 0) < 1 then return jsonb_build_object('idle', true, 'reason', 'off', 'items', '[]'::jsonb); end if;
  -- Validation 5 Nov 2026: a worker leases only through public.svc_provider_description_lease_v1 or _cohort_next, which declare the
  -- reservation protocol. A worker from before this release (it calls this function directly and never reserves) gets no item, so it cannot
  -- make an unreserved paid AI call against this database.
  if coalesce(auth.role(), '') = 'service_role' and coalesce(current_setting('cf.pdesc_worker_protocol', true), '') <> 'provider-description-reserve-v1' then
    return jsonb_build_object('idle', true, 'reason', 'worker_protocol_required', 'items', '[]'::jsonb);
  end if;
  -- fixed: serialize reservation of review slots across all reader callers; no waiting behind another worker.
  if not pg_try_advisory_xact_lock(hashtext('cf247 provider description capacity')) then return jsonb_build_object('idle',true,'reason','capacity_in_flight','items','[]'::jsonb); end if;
  v_cap := case when v_mach then security.pipeline_num_v1('pdesc.concurrency_max', 12) else security.pipeline_num_v1('pdesc.pending_max', 10) end;
  select (case when v_mach then 0 else (select count(*) from pipeline.layer4_review_items i where i.field_code='provider_description' and i.status='pending') end)
       + (select count(*) from pipeline.provider_description_reads r where r.state='reading' and r.leased_until>=now()) into v_pending;
  if v_pending >= v_cap then return jsonb_build_object('idle', true, 'reason', 'review_full', 'items', '[]'::jsonb); end if;
  v_model := v_rt->>'model';  -- 13 Nov 2026: the route (pipeline.ai_service_routes)
  if nullif(btrim(v_model), '') is null then return jsonb_build_object('idle', true, 'reason', 'no_model', 'items', '[]'::jsonb); end if;
  -- the shared AI rule (credit floor, daily ceiling, lane guard; v2.15.404): nothing new is claimed while AI use is refused
  if not security.ai_use_allowed_v1(case when security.pdesc_on_demand_due_v1() then 'provider_description_on_demand' else 'provider_description' end) then return jsonb_build_object('idle', true, 'reason', 'ai_refused', 'items', '[]'::jsonb); end if; /* 20261112010000 */
  -- the pilot's hard ceilings: total AI spend of this lane in the shared ledger, and total Firecrawl reads of this reader
  select coalesce(sum(l.cost_usd), 0) into v_spent from pipeline.ai_spend_ledger l where l.lane = 'provider_description' and l.source <> 'opening';
  select coalesce(sum(r.firecrawl_reads), 0) into v_fc_used from pipeline.provider_description_reads r
   where r.updated_at > now() - make_interval(hours => security.pipeline_num_v1('pdesc.firecrawl_window_hours', 24)::int); -- 20261110250000: an allowance a window, not a lifetime count
  -- 20261112010000: a read an operator asked for (checks.on_demand) is not held by the lane limits; while one is due, this call takes on-demand reads only
  v_od := security.pdesc_on_demand_due_v1();
  if v_od then v_over := true; end if;
  if coalesce((v_rt->>'held')::boolean, true) and not (coalesce((v_rt->>'on_demand_exempt')::boolean, false) and v_od) then return jsonb_build_object('idle', true, 'reason', 'route_held', 'detail', v_rt->>'held_reason', 'items', '[]'::jsonb); end if;
  if v_spent >= security.pipeline_num_v1('pdesc.ai_usd_max', 1) and not v_od then return jsonb_build_object('idle', true, 'reason', 'ai_ceiling', 'spent_usd', v_spent, 'items', '[]'::jsonb); end if;
  if v_mach then
    -- automatic mode: no more reads in progress than the AI spend still available covers, at the dearer of the set cost and the observed cost of a read
    v_afford := floor((security.pipeline_num_v1('pdesc.ai_usd_max', 1) - v_spent - coalesce((select sum(x.reserved_usd) from pipeline.provider_description_reads x where x.state = 'reading'), 0))
                      / greatest(security.pipeline_num_v1('pdesc.read_cost_floor_usd', 0.003), coalesce((select sum(x.cost_usd) / nullif(count(*) filter (where x.ai_calls > 0), 0) from pipeline.provider_description_reads x), 0)))
                - (select count(*) from pipeline.provider_description_reads x where x.state = 'reading' and x.leased_until >= now());
    if v_afford < 1 and not v_od then return jsonb_build_object('idle', true, 'reason', 'ai_spend_committed', 'spent_usd', v_spent, 'items', '[]'::jsonb); end if;
    if v_od then v_afford := null; end if;
  end if;
  -- QA N4: Firecrawl reads held by worker calls still in flight are not available again; with automatic admission on, this call is granted at most pdesc.firecrawl_per_call of what the ceiling still allows after them
  v_fc_res := coalesce((select sum(coalesce((x.checks->>'firecrawl_reserved')::int, 0)) from pipeline.provider_description_reads x where x.state = 'reading' and x.leased_until >= now()), 0);
  v_fc_left := case when v_mach then least(greatest(0, security.pipeline_num_v1('pdesc.firecrawl_reads_max', 0)::int - v_fc_used - v_fc_res), security.pipeline_num_v1('pdesc.firecrawl_per_call', 5)::int)
                    else greatest(0, security.pipeline_num_v1('pdesc.firecrawl_reads_max', 0)::int - v_fc_used) end;
  if v_od then v_fc_left := security.pipeline_num_v1('pdesc.firecrawl_per_call', 5)::int; end if; -- 20261112010000: on demand, the per-call share only (spent as purpose provider_description_on_demand)
  if v_mach then
    -- QA N6/N7/N11: a provider the automatic rule must not describe now (locked, earlier rejection, withdrawn, cleared by hand, open finding, unusable name, already described) is held here, before any AI call
    update pipeline.provider_description_reads r set state='held',rule='machine_declined_'||(b.blk->>'rule'),reason=left(b.blk->>'reason',400),leased_until=null,updated_at=now() -- fixed: the stored reason shows its first 400 characters
      from (select x.id,security.provider_description_machine_blocked_v1(x.provider_id) blk from pipeline.provider_description_reads x where (x.state='queued' and x.next_try_at<=now()) or (x.state='reading' and x.leased_until<now())) b
     where r.id=b.id and b.blk is not null;
  end if;
  -- one pass (9 Nov 2026, lease statement time-out): the stored About copy of each provider with open work is found ONCE here and read from v_stored below; it was found up to three times per queued row.
  -- Only a provider with a copy at an About address can have one (security.pdesc_about_like_patterns_v1 is the first step of security.provider_description_stored_v1), so the others are not asked.
  v_ws := security.pdesc_about_like_patterns_v1();
  select coalesce(jsonb_object_agg(z.pid, to_jsonb(z.sid)), '{}'::jsonb) into v_stored from (
    select x.provider_id::text pid, security.provider_description_stored_v1(x.provider_id) sid
      from (select distinct o.provider_id from pipeline.provider_description_reads o where (o.state='queued' or (o.state='reading' and o.leased_until<now()))
               and exists (select 1 from pipeline.sources s join pipeline.evidence_artifacts a on a.source_id=s.id where s.provider_id=o.provider_id and lower(a.source_url) like any (v_ws))
             offset 0) x) z -- offset 0 is an optimisation fence: without it the planner moves the not-null test below the DISTINCT and asks stored_v1 for every open read
   where z.sid is not null;
  -- identity hold (10 Nov 2026): due queued reads are tested for the provider identity, the ones tested longest ago first (each tested read is marked checks.identity_checked_at, so the same oldest reads are not tested on every call). The stored About copy is read from v_stored (found once, above).
  -- Only wrong_host (a provider with no website gives this too) and provider_host_conflict hold the read, with the identity rule and reason and the mark checks.identity_hold: the selection offers such a read again as soon as the provider passes (website or host corrected).
  -- Any other outcome (provider_inactive, a lifecycle hold, an open identity finding) leaves the read queued as before. wrong_host is taken by the register-fact tier; provider_host_conflict waits for a person. Not for a Run Now cohort (the job guard holds those).
  if v_mach and nullif(current_setting('cf.pdesc_cohort',true),'') is null and security.pipeline_num_v1('batch.provider_description', 3) >= 1 then
    update pipeline.provider_description_reads r set state=case when h.hold then 'held' else r.state end, rule=case when h.hold then h.idr else r.rule end, reason=case when h.hold then left(h.why,400) else r.reason end, -- fixed: the stored reason shows its first 400 characters
           leased_until=case when h.hold then null else r.leased_until end, updated_at=case when h.hold then now() else r.updated_at end,
           checks=coalesce(r.checks,'{}'::jsonb)||jsonb_build_object('identity_checked_at',now())||case when h.hold then jsonb_build_object('identity_hold',true) else '{}'::jsonb end
      from (select o.id, i.v->>'rule' idr, i.v->>'reason' why, (not coalesce((i.v->>'ok')::boolean,false) and i.v->>'rule' in ('wrong_host','provider_host_conflict')) hold
              from (select x.id, x.provider_id, pp.website from pipeline.provider_description_reads x join catalogue.providers pp on pp.id=x.provider_id and pp.lifecycle_status='active' and pp.publication_status='published'
                     where x.state='queued' and x.next_try_at<=now() order by (x.checks->>'identity_checked_at') nulls first, x.next_try_at, x.id limit security.pipeline_num_v1('batch.provider_description', 3)::int) o
              cross join lateral (select security.provider_description_identity_v1(o.provider_id, coalesce((select a.source_url from pipeline.evidence_artifacts a where a.id=(v_stored->>o.provider_id::text)::uuid), o.website)) v offset 0) i) h
     where r.id=h.id and r.state='queued';
  end if;
  -- identity re-offer (9 Nov 2026): a provider whose latest finished read was held on an identity rule (pdesc.identity_reeval_rules) by another reader than the one running now (security.pdesc_reader_behaviour_v1) is not held or skipped on recovery knowledge:
  -- that knowledge recorded the earlier reader's failure. Found once here from the latest finished read of each provider. A failure of any other kind, or of the current reader, keeps its memory.
  v_reoffer := array(select l.provider_id from (select distinct on (o.provider_id) o.provider_id, o.state, o.rule, o.checks from pipeline.provider_description_reads o
                        where o.state not in ('queued', 'reading') order by o.provider_id, o.created_at desc) l
                      where l.state = 'held' and coalesce(security.toolset_setting('pipeline', 'pdesc.identity_reeval_rules'), '[]'::jsonb) ? l.rule
                        and coalesce(l.checks->'identity'->>'reader_behavior_version', '') is distinct from coalesce(security.pdesc_reader_behaviour_v1(), ''));
  update pipeline.provider_description_reads r set state='held',rule='recovery_knowledge_unchanged_failure',reason='The same stored evidence already failed; changed approved evidence or an authorised correction is needed before another AI call.',leased_until=null,updated_at=now()
  where r.id in (select x.id from pipeline.provider_description_reads x join pipeline.evidence_artifacts a on a.id=(v_stored->>x.provider_id::text)::uuid
    where x.state='queued' and not (x.provider_id = any(v_reoffer)) and not security.pdesc_on_demand_live_v1(x.checks) and not coalesce((security.ops_learning_retry_check_v1('provider_description:official_about',x.provider_id::text,security.provider_description_signature_v1(coalesce(a.content_hash,a.id::text),v_model,coalesce(v_pv,x.prompt_version,'provider-description-v2')))->>'allowed')::boolean,true)
    order by x.next_try_at,x.id limit security.pipeline_num_v1('batch.provider_description',3)::int);
  with act as materialized (select pz.country_id,count(*) n from pipeline.provider_description_reads o join catalogue.providers pz on pz.id=o.provider_id
                              where v_mach and o.state in ('reading','proposed','admitted','held') and o.updated_at > now() - make_interval(hours => security.pipeline_num_v1('pdesc.rate_window_hours', 3)::int) group by pz.country_id),
  pick as (select l.id from (
             -- lazy pick (9 Nov 2026, lease and record time-outs): the cheap tests and the order are worked out for every due read (inner query), then the dear per-provider tests
             -- (scope, recovery memory, identity, hidden) run only on the reads taken in that order until the limit is reached. The same reads in the same order as before; the whole queue is no longer tested on every call.
             select c.id from (
               select r.id, r.provider_id, r.prompt_version, r.checks from pipeline.provider_description_reads r
                 where ((r.state = 'queued' and r.next_try_at <= now()) or (r.state = 'reading' and r.leased_until < now()))
                   and r.tries < v_tries
                   and (not v_over or security.pdesc_on_demand_live_v1(r.checks))
                   and ((select nullif(btrim(p.description),'') from catalogue.providers p where p.id=r.provider_id) is null
                     or (not v_mach and exists(select 1 from pipeline.provider_description_reads own where own.provider_id=r.provider_id and own.state in ('admitted','verified'))) or (v_mach and security.provider_description_basic_profile_v1(r.provider_id) is not null))
                   and not exists(select 1 from pipeline.manual_locks l where l.entity='provider' and l.entity_id=r.provider_id and l.field in ('description','p_description','all'))
                   and (nullif(current_setting('cf.pdesc_cohort',true),'') is null or exists(select 1 from pipeline.provider_description_cohort_members m where m.cohort_id=nullif(current_setting('cf.pdesc_cohort',true),'')::uuid and m.read_id=r.id and (m.evidence_id is null or exists(select 1 from pipeline.evidence_artifacts a where a.id=m.evidence_id and coalesce(a.content_hash,a.id::text)=m.snapshot->>'source_hash' and coalesce(a.captured_at,a.created_at)>now()-make_interval(days=>security.pipeline_num_v1('pdesc.source_max_age_days',365)::int)))))
                   -- acquisition off (pdesc.acquire_direct 0): only a provider with a stored About copy is read
                   -- IQ-00055: a CASE, so the stored copy is not looked up per queued row while direct acquisition is on
                   and case when v_acq then true else (v_stored->>r.provider_id::text) is not null end
                 order by security.pdesc_on_demand_live_v1(r.checks) desc, case when v_mach then coalesce((select a.n from act a join catalogue.providers pr on pr.id = r.provider_id where a.country_id = pr.country_id), 0) else 0 end, r.next_try_at, r.created_at
                 offset 0) c -- offset 0 is an optimisation fence: the dear tests below are not moved under the sort, so they stop with the limit
              where security.provider_description_scope_v1(c.provider_id)
                and (c.provider_id = any(v_reoffer) or security.pdesc_on_demand_live_v1(c.checks) or coalesce((security.ops_learning_retry_check_v1('provider_description:official_about',c.provider_id::text,security.provider_description_signature_v1((select coalesce(a.content_hash,a.id::text) from pipeline.evidence_artifacts a where a.id=(v_stored->>c.provider_id::text)::uuid),v_model,coalesce(v_pv,c.prompt_version,'provider-description-v2')))->>'allowed')::boolean,true))
                and exists(select 1 from catalogue.providers p where p.id=c.provider_id and p.publication_status='published' and (security.provider_description_identity_v1(p.id,coalesce((select a.source_url from pipeline.evidence_artifacts a where a.id=(v_stored->>p.id::text)::uuid),p.website))->>'ok')::boolean)
                and not exists(select 1 from security.provider_hidden_v1 h where h.provider_id=c.provider_id)) o
           -- the row lock, as before: skip a read another call holds; the due test is repeated on the locked row, as the lock of the old single query re-tested it
           cross join lateral (select q.id from pipeline.provider_description_reads q where q.id = o.id
                                  and ((q.state = 'queued' and q.next_try_at <= now()) or (q.state = 'reading' and q.leased_until < now()))
                                  and q.tries < v_tries
                                for update skip locked) l
           limit greatest(1, least(coalesce(p_limit, 3),security.pipeline_num_v1('batch.provider_description',3)::int,(v_cap - v_pending)::int,coalesce(v_afford, 1000000)::int))),
  upd as (update pipeline.provider_description_reads r set state = 'reading', tries = r.tries + 1, prompt_version = coalesce(v_pv, r.prompt_version), checks=coalesce(r.checks,'{}'::jsonb)||jsonb_build_object('description_at_lease',(select p.description from catalogue.providers p where p.id=r.provider_id),'identity_snapshot',security.provider_description_identity_snapshot_v1(r.provider_id),'firecrawl_reserved',case when v_mach and r.id=(select pk.id from pick pk order by pk.id limit 1) then v_fc_left else 0 end),
                 leased_until = now() + interval '20 minutes',  -- fixed: claim timer (a lost worker call is taken again)
                 updated_at = now()
            from pick where r.id = pick.id returning r.*)
  select coalesce(jsonb_agg(jsonb_build_object('item_id', u.id, 'provider_id', u.provider_id, 'on_demand', security.pdesc_on_demand_live_v1(u.checks), 'provider', coalesce(p.display_name, p.canonical_name),
           'website', p.website, 'country', k.iso_alpha2, 'identity_names',jsonb_build_array(p.canonical_name,p.display_name), 'provider_type',(select t.code from ref.provider_types t where t.id=p.provider_type_id), 'hosts', to_jsonb(security.provider_hosts_v1(u.provider_id)),
           'stored', (select jsonb_build_object('evidence_id', a.id, 'storage_path', a.storage_path, 'url', a.source_url, 'captured_at', coalesce(a.captured_at, a.created_at),'content_hash',coalesce(a.content_hash,a.id::text))
                        from pipeline.evidence_artifacts a where a.id = st.stored_id),
           -- About pages the central page finder suggested (page type about_page, central.ts), on the provider's own hosts, best first
           -- IQ-00055: the page rule once per suggestion (a lateral), for the filter and the order
           'candidates', (select coalesce(jsonb_agg(z.url order by (z.pg->>'main_host')::boolean desc, z.score desc, length(z.url)), '[]'::jsonb) from (
                            select y.url, y.score, g.pg from (
                              select distinct e->>'url' url, coalesce((e->>'score')::numeric, 0) score
                                from pipeline.provider_central_search cs, jsonb_array_elements(coalesce(cs.found, '[]'::jsonb)) e
                               where cs.provider_id = u.provider_id and e->>'kind' = 'about_page' and e->>'url' ~* '^https?://'
                                 and coalesce((e->>'score')::numeric, 0) >= security.pipeline_num_v1('central.min_suggest_score', 4)) y
                              cross join lateral (select security.provider_description_page_v1(u.provider_id, y.url) pg offset 0) g
                             where (g.pg->>'ok')::boolean) z))), '[]'::jsonb)
    into v
    -- IQ-00055: the stored copy once per claimed row
    from upd u cross join lateral (select case when nullif(current_setting('cf.pdesc_cohort',true),'') is not null then (select m.evidence_id from pipeline.provider_description_cohort_members m where m.cohort_id=nullif(current_setting('cf.pdesc_cohort',true),'')::uuid and m.read_id=u.id) else (v_stored->>u.provider_id::text)::uuid end stored_id offset 0) st
         join catalogue.providers p on p.id = u.provider_id join ref.countries k on k.id = p.country_id;
  return jsonb_build_object('model', v_model, 'models', v_rt->'models', 'prompt', security.provider_description_prompt_active_v1(),
    'acquire_direct', security.pipeline_num_v1('pdesc.acquire_direct', 0) >= 1 and coalesce((select c.selection->>'mode' from pipeline.provider_description_cohorts c where c.id=nullif(current_setting('cf.pdesc_cohort',true),'')::uuid),'approved')='approved',
    'acquire_firecrawl', security.pipeline_num_v1('pdesc.acquire_firecrawl', 0) >= 1 and coalesce((select c.selection->>'mode' from pipeline.provider_description_cohorts c where c.id=nullif(current_setting('cf.pdesc_cohort',true),'')::uuid),'approved')='approved',
    'firecrawl_left', v_fc_left,
    'page_chars', security.pipeline_num_v1('pdesc.page_chars', 16000)::int,'verbatim_span_max_chars',security.pipeline_num_v1('pdesc.verbatim_span_max_chars',120)::int,
    'min_quote_chars', security.pipeline_num_v1('pdesc.min_quote_chars', 20)::int,
    'about_patterns', coalesce(security.toolset_setting('pipeline', 'pdesc.about_patterns'), '[]'::jsonb),
    -- pilot 2 Nov 2026 16:16: the page rule's lists, for the home page's links (security.provider_description_page_v1 decides the same way)
    'page_rule', jsonb_build_object('about_prefixes', coalesce(security.toolset_setting('pipeline', 'pdesc.about_prefixes'), '[]'::jsonb),
                                    'refused_path_words', coalesce(security.toolset_setting('pipeline', 'pdesc.refused_path_words'), '[]'::jsonb),
                                    'refused_host_labels', coalesce(security.toolset_setting('pipeline', 'pdesc.refused_host_labels'), '[]'::jsonb),
                                    'about_max_segments', security.pipeline_num_v1('pdesc.about_max_segments', 2)::int),
    -- pilot 2 Nov 2026 16:16 (CDU held at 916 characters): the model is told the limits the validation applies
    'length', jsonb_build_object('min_sentences', security.pipeline_num_v1('pdesc.min_sentences', 2)::int, 'max_sentences', security.pipeline_num_v1('pdesc.max_sentences', 5)::int,
                                 'min_chars', security.pipeline_num_v1('pdesc.min_chars', 150)::int, 'max_chars', security.pipeline_num_v1('pdesc.max_chars', 900)::int),
    'items', v);
end $$;


ALTER FUNCTION "public"."svc_provider_description_next"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_provider_description_next"("p_limit" integer) IS 'CF-247 P1 provider descriptions: worker lease (mode provider_description). Nothing while pdesc.enabled is 0 or pdesc.pending_max proposals wait in Layer 4. Gives each provider''s own hosts, its stored About copy when held, the pinned Enrich fields model and the limits.';



CREATE OR REPLACE FUNCTION "public"."svc_provider_description_record"("p_results" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare x jsonb; r pipeline.provider_description_reads%rowtype; v_ev uuid; v_url text; v_cap timestamptz; v_via text; v_hash text;
        v_chk jsonb; v_item uuid; v_tally jsonb := '{}'::jsonb; v_out text; v_max int := security.pipeline_num_v1('pdesc.tries', 3)::int; v_err text; v_m jsonb; v_src uuid; v_idc jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  perform pg_advisory_xact_lock(hashtext('cf247 provider description capacity')); -- fixed: serialize final Layer 4 capacity check with leases.
  for x in select * from jsonb_array_elements(coalesce(p_results, '[]'::jsonb)) loop
    select * into r from pipeline.provider_description_reads where id = (x->>'item_id')::uuid for update;
    if r.id is null or r.state <> 'reading' then v_tally := v_tally || jsonb_build_object('stale', coalesce((v_tally->>'stale')::int, 0) + 1); continue; end if;
    update pipeline.provider_description_reads set ai_calls=ai_calls+case when coalesce((x->>'ai_call_started')::boolean,false) then 1 else 0 end, checks=coalesce(checks,'{}'::jsonb)||jsonb_strip_nulls(jsonb_build_object('identity',x->'identity_check','ai_reservation',x->'ai_reservation','cost_known',x->'cost_known')), reserved_usd=case when coalesce((x->>'cost_known')::boolean,false) or coalesce((x->>'cost')::numeric,0)>0 then 0 else reserved_usd end, cost_usd = cost_usd + greatest(coalesce((x->>'cost')::numeric, 0), 0),
           firecrawl_reads = firecrawl_reads + greatest(coalesce((x->>'fc_reads')::int, 0), 0),
           model = coalesce(nullif(x->>'model', ''), model), prompt_version = coalesce(nullif(x->>'prompt_version', ''), prompt_version),
           worker = coalesce(left(nullif(x->>'worker', ''), 60), worker), updated_at = now()
     where id = r.id;
    v_ev := null; v_url := null; v_cap := null; v_via := null; v_hash := null;
    -- the page: a stored copy, or a page the worker read and stored now (registered as evidence under the provider's coverage-sweep source)
    if (x->>'stored_evidence_id') is not null then
      select a.id, a.source_url, coalesce(a.captured_at, a.created_at), coalesce(a.content_hash, a.id::text) into v_ev, v_url, v_cap, v_hash
        from pipeline.evidence_artifacts a join pipeline.sources s on s.id = a.source_id
       where a.id = (x->>'stored_evidence_id')::uuid and s.provider_id = r.provider_id;
      v_via := case when v_ev is not null then 'stored' end;
    elsif x->'fetch'->>'status' = 'read' and x->'fetch'->>'storage_path' is not null and x->'fetch'->>'sha256' ~ '^[0-9a-f]{64}$' then
      v_url := x->'fetch'->>'url'; v_hash := x->'fetch'->>'sha256'; v_via := x->'fetch'->>'via'; v_cap := now();
      if security.provider_page_host_v1(r.provider_id, v_url) = 'own' then
        -- the sweep source is found once (9 Nov 2026, record time-out): security.coverage_sweep_source is volatile, so as a test on every row it could not be an index condition and the lookup read the whole (source, hash) index (22 ms on average, 142 ms at worst, against 0.2 ms with the id in hand)
        v_src := security.coverage_sweep_source(r.provider_id);
        select a.id into v_ev from pipeline.evidence_artifacts a where a.source_id = v_src and a.content_hash = v_hash and a.source_url = v_url limit 1;
        if v_ev is null then
          v_ev := public.svc_coursefacts_register_evidence(v_src, v_url, x->'fetch'->>'storage_path', v_hash,
                    coalesce(x->'fetch'->>'mime', 'text/html'),
                    jsonb_build_object('layer', 2, 'kind', 'provider_about_page', 'worker', 'coverage-sweep', 'provider_description_read_id', r.id, 'read_via', v_via) || case when jsonb_typeof(x->'fetch'->'http') = 'number' then jsonb_build_object('page_status', (x->'fetch'->>'http')::int) else '{}'::jsonb end);
        end if;
      end if;
    end if;
    update pipeline.provider_description_reads set evidence_id = coalesce(v_ev, evidence_id), source_url = coalesce(v_url, x->'fetch'->>'url', source_url),
           read_via = coalesce(v_via, read_via), content_hash = coalesce(v_hash, content_hash), source_captured_at = coalesce(v_cap, source_captured_at)
     where id = r.id;
    v_err := nullif(x->>'error', '');
    if v_err is not null or coalesce((x->>'retry')::boolean, false) then
      -- a failed read is tried again after pdesc.retry_minutes, at most pdesc.tries times; then the dead letter list
      update pipeline.provider_description_reads set state = case when tries >= v_max then 'dead_letter' else 'queued' end,
             next_try_at = now() + make_interval(mins => security.pipeline_num_v1('pdesc.retry_minutes', 360)::int), leased_until = null,
             rule = case when tries >= v_max then 'dead_letter' else 'retry' end, reason = left(coalesce(v_err, x->>'reason', 'retry'), 400), updated_at = now()
       where id = r.id returning state into v_out;
      v_tally := v_tally || jsonb_build_object(v_out, coalesce((v_tally->>v_out)::int, 0) + 1); continue;
    end if;
    if x->'answer' is null and x->>'rule' in ('source_identity_proof_missing','ai_ceiling','ai_daily_guard','ai_refused','model_pricing_unavailable','invalid_model_pricing','unrecognised_pricing_component','ai_budget_refused','existing_cost_reservation_uncertain') and coalesce((select reserved_usd from pipeline.provider_description_reads where id=r.id),0)=0 then
      update pipeline.provider_description_reads set state='queued',tries=greatest(0,tries-1),next_try_at=now()+make_interval(mins=>security.pipeline_num_v1('pdesc.retry_minutes',360)::int),leased_until=null,rule=x->>'rule',reason=left(coalesce(x->>'reason','Waiting for existing AI spending or pricing policy to allow the next read.'),400),updated_at=now() where id=r.id;
      v_tally:=v_tally||jsonb_build_object('parked_policy',coalesce((v_tally->>'parked_policy')::int,0)+1); continue;
    end if;
    if x->'answer' is null then
      -- no page to read: no About page on the provider's own hosts, robots.txt, another provider's host
      update pipeline.provider_description_reads set state = 'held', leased_until = null, rule = coalesce(nullif(x->>'rule', ''), 'no_about_page'),
             reason = left(coalesce(x->>'reason', 'no About page found on the provider''s own website'), 400), updated_at = now()
       where id = r.id;
      v_tally := v_tally || jsonb_build_object('held', coalesce((v_tally->>'held')::int, 0) + 1); continue;
    end if;
    select * into r from pipeline.provider_description_reads where id = r.id;
    -- sentence filter (migration 20261110110000): a sentence that fails a sentence rule is left out and the others are kept; a proposal stores and passes on the KEPT sentences (checks.dropped says what was left out and why)
    v_chk := security.provider_description_validate_v1(r.provider_id, r.source_url, r.source_captured_at, x->'answer' || jsonb_build_object('drop_failing', true));
    if v_chk->>'outcome' in ('propose', 'verified') and v_chk ? 'sentences' then x := jsonb_set(x, '{answer,sentences}', v_chk->'sentences'); end if;
    if v_chk->>'outcome' = 'propose' and r.evidence_id is null then
      v_chk := jsonb_build_object('ok', false, 'outcome', 'held', 'rule', 'no_evidence', 'reason', 'the page copy is not stored as evidence', 'checks', v_chk->'checks');
    end if;
    if (select p.description from catalogue.providers p where p.id=r.provider_id) is distinct from r.checks->>'description_at_lease' then
      v_chk:=jsonb_build_object('ok',false,'outcome','held','rule','description_changed_after_lease','reason','The description was edited while this read was in progress; retain the human value.','checks',v_chk->'checks');
    end if;
    if r.checks->'identity_snapshot' is not null and r.checks->'identity_snapshot' is distinct from security.provider_description_identity_snapshot_v1(r.provider_id) then
      v_chk:=jsonb_build_object('ok',false,'outcome','held','rule','identity_changed_after_lease','reason','Provider names, type, country or website changed after source identity was checked.','checks',v_chk->'checks');
    end if;
    if not security.provider_description_scope_v1(r.provider_id) or exists(select 1 from pipeline.manual_locks l where l.entity='provider' and l.entity_id=r.provider_id and l.field in ('description','p_description','all')) then
      v_chk:=jsonb_build_object('ok',false,'outcome','held','rule','provider_eligibility_changed','reason','Provider eligibility or manual lock changed after the read was leased.','checks',v_chk->'checks');
    end if;
    if exists(select 1 from pipeline.provider_description_cohort_members m where m.read_id=r.id and (m.evidence_id is distinct from r.evidence_id or m.snapshot->>'source_hash' is distinct from r.content_hash) and m.evidence_id is not null) then
      v_chk:=jsonb_build_object('ok',false,'outcome','held','rule','cohort_evidence_changed','reason','The recorded evidence differs from the immutable cohort source. Preview the changed evidence again.','checks',v_chk->'checks');
    end if;
    if x->'quality_hold' is not null then
      v_chk:=jsonb_build_object('ok',false,'outcome','held','rule',coalesce(x->'quality_hold'->>'rule','worker_quality_hold'),'reason',x->'quality_hold'->>'reason','checks',v_chk->'checks');
    end if;
    v_idc := security.provider_description_identity_v1(r.provider_id,r.source_url); -- once: the same answer was asked for up to three times
    if not (v_idc->>'ok')::boolean then
      v_chk:=jsonb_build_object('ok',false,'outcome','held','rule',v_idc->>'rule','reason',v_idc->>'reason','checks',v_chk->'checks');
    end if;
    if v_chk->>'outcome' in ('propose','verified') and not coalesce((x->'identity_check'->>'ok')::boolean,(r.checks->'identity'->>'ok')::boolean,false) then
      v_chk:=jsonb_build_object('ok',false,'outcome','held','rule','source_identity_proof_missing','reason','The worker did not provide current source-identity proof; retain this evidence and retry only through the current approved reader.','checks',v_chk->'checks');
    end if;
    v_chk:=v_chk||jsonb_build_object('checks',coalesce(v_chk->'checks','{}'::jsonb)||jsonb_strip_nulls(jsonb_build_object('identity',x->'identity_check','ai_reservation',x->'ai_reservation','cost_known',x->'cost_known','description_at_lease',r.checks->'description_at_lease','identity_snapshot',r.checks->'identity_snapshot')));
    if v_chk->>'outcome'='propose' and security.pipeline_num_v1('pdesc.machine_admit_on',0)>=1 then
      -- machine rule pdesc-machine-v1. A description the TEXT rule refuses waits for a person in Layer 4 while there is room (pdesc.machine_pending_max); any other refusal (a lock, an earlier
      -- rejection, a withdrawal, an open finding ...) or no room: HELD with the whole proposal and the exact reason. Nothing is dropped.
      v_m:=security.provider_description_machine_gate_v1(r.provider_id,v_chk->>'text',jsonb_build_object('tier',r.read_via,'sentences',x->'answer'->'sentences'));
      if not (v_m->>'ok')::boolean and (v_m->>'rule' not like 'machine_text%' or (select count(*) from pipeline.layer4_review_items i where i.field_code='provider_description' and i.status='pending')>=security.pipeline_num_v1('pdesc.machine_pending_max',200)) then
        update pipeline.provider_description_reads set state='held',leased_until=null,proposal=jsonb_build_object('description',v_chk->>'text','sentences',x->'answer'->'sentences'),checks=v_chk->'checks',rule='machine_declined_'||(v_m->>'rule'),
          reason=left(v_m->>'reason'||case when v_m->>'rule' like 'machine_text%' then ' Held with the full proposal: the places for a person to decide in Layer 4 are taken (pdesc.machine_pending_max).' else '' end,400),last_verified_at=now(),updated_at=now() where id=r.id; -- fixed: the stored reason shows its first 400 characters
        v_tally:=v_tally||jsonb_build_object('machine_declined',coalesce((v_tally->>'machine_declined')::int,0)+1); continue;
      end if;
    end if;
    if v_chk->>'outcome'='propose' and security.pipeline_num_v1('pdesc.machine_admit_on',0)<1 and (select count(*) from pipeline.layer4_review_items i where i.field_code='provider_description' and i.status='pending')>=security.pipeline_num_v1('pdesc.pending_max',10) then
      -- Keep the complete validated proposal; scheduler resumes this exact evidence without another AI call.
      update pipeline.provider_description_reads set state='held',leased_until=null,proposal=jsonb_build_object('description',v_chk->>'text','sentences',x->'answer'->'sentences'),checks=v_chk->'checks',rule='review_full',reason='Layer 4 provider-description capacity is full; resume automatically when a slot is free',updated_at=now() where id=r.id;
      v_tally:=v_tally||jsonb_build_object('parked',coalesce((v_tally->>'parked')::int,0)+1); continue;
    end if;
    if v_chk->>'outcome' = 'propose' then
      insert into pipeline.layer4_review_items(entity_type, entity_id, field_code, evidence_id, before_value, proposed_value, layer2_state, layer3_state, status, escalation_reason, change_control_ref)
      values ('provider', r.provider_id, 'provider_description', r.evidence_id,
              jsonb_build_object('description', (select nullif(btrim(p.description), '') from catalogue.providers p where p.id = r.provider_id)),
              jsonb_build_object('description', v_chk->>'text', 'sentences', x->'answer'->'sentences', 'source_url', r.source_url, 'evidence_id', r.evidence_id,
                                 'captured_at', r.source_captured_at, 'read_id', r.id),
              jsonb_build_object('read_via', r.read_via, 'content_hash', r.content_hash, 'source_url', r.source_url),
              jsonb_build_object('model', r.model, 'prompt_version', r.prompt_version, 'worker', r.worker, 'cost_usd', r.cost_usd, 'checks', v_chk->'checks', 'rule', v_chk->>'rule'),
              'pending', 'Provider description read from the official page: every sentence quotes the page. A person approves or rejects it; nothing is published before.',
              'CF-247 P1 provider descriptions (Platform Admin 2 Nov 2026 10:28)')
      returning id into v_item;
      update pipeline.provider_description_reads set state = 'proposed', leased_until = null, proposal = jsonb_build_object('description', v_chk->>'text', 'sentences', x->'answer'->'sentences'),
             checks = v_chk->'checks', rule = v_chk->>'rule', reason = null, review_item_id = v_item, last_verified_at = now(), updated_at = now()
       where id = r.id;
      v_out := 'proposed';
      if security.pipeline_num_v1('pdesc.machine_admit_on',0)>=1 then
        -- admitted here under the machine rule, or left waiting for a person with the reason on the item; a failure never undoes the proposal
        begin
          v_m:=security.provider_description_machine_admit_v1(v_item);
          if (v_m->>'ok')::boolean then v_out:='admitted'; end if;
        exception when others then null;
        end;
      end if;
    elsif v_chk->>'outcome' = 'verified' then
      update pipeline.provider_description_reads set state = 'verified', leased_until = null, proposal = jsonb_build_object('description', v_chk->>'text', 'sentences', x->'answer'->'sentences'),
             checks = v_chk->'checks', rule = v_chk->>'rule', reason = v_chk->>'reason', last_verified_at = now(), updated_at = now()
       where id = r.id;
      v_out := 'verified';
    else
      update pipeline.provider_description_reads set state = 'held', leased_until = null, proposal = jsonb_build_object('sentences', x->'answer'->'sentences'),
             checks = v_chk->'checks', rule = v_chk->>'rule', reason = left(v_chk->>'reason', 400), updated_at = now()
       where id = r.id;
      v_out := 'held';
    end if;
    v_tally := v_tally || jsonb_build_object(v_out, coalesce((v_tally->>v_out)::int, 0) + 1);
  end loop;
  return v_tally;
end $_$;


ALTER FUNCTION "public"."svc_provider_description_record"("p_results" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_provider_description_record"("p_results" "jsonb") IS 'CF-247 P1 provider descriptions: records the worker''s reads. A stored or newly stored own-host page is the evidence; a failed read is retried (pdesc.tries, pdesc.retry_minutes) then dead-lettered; a read that passes security.provider_description_validate_v1 becomes one Layer 4 item (provider_description); one that matches the description held is verified; anything else is held with its rule. Never writes catalogue.providers.';



CREATE OR REPLACE FUNCTION "public"."svc_provider_description_reserve_v1"("p_item" "uuid", "p_model" "text", "p_max_cost" numeric, "p_source_hash" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.provider_description_reads%rowtype; v_model text; v_spent numeric; v_today numeric; v_reserved numeric; v_cap numeric; v_daily numeric; v_source_hash text;
begin
 if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtext('cf247 provider description spend')); -- fixed: serialize reservations across reader calls.
 select * into r from pipeline.provider_description_reads where id=p_item for update;
 if r.id is null or r.state<>'reading' or r.leased_until<=now() then return jsonb_build_object('ok',false,'reason','no_active_read_lease'); end if;
 select x->>'model_identifier' into v_model from jsonb_array_elements(security.ai_route_v1('provider_description')->'models') x where x->>'model_identifier' = p_model;  -- a model of the route's cascade
 if p_model is distinct from v_model or p_max_cost is null or p_max_cost<=0 then return jsonb_build_object('ok',false,'reason','invalid_pinned_model_price_quote'); end if;
 v_source_hash:=coalesce(nullif(p_source_hash,''),(select coalesce(a.content_hash,a.id::text) from pipeline.evidence_artifacts a where a.id=security.provider_description_stored_v1(r.provider_id)));
 if v_source_hash is null then return jsonb_build_object('ok',false,'reason','no_source_version_before_ai'); end if;
 if exists(select 1 from pipeline.provider_description_reads rejected where rejected.provider_id=r.provider_id and rejected.state='rejected' and rejected.content_hash=v_source_hash) then return jsonb_build_object('ok',false,'reason','unchanged_rejected_evidence'); end if;
 if not security.pdesc_on_demand_live_v1(r.checks) and not coalesce((security.ops_learning_retry_check_v1('provider_description:official_about',r.provider_id::text,security.provider_description_signature_v1(v_source_hash,p_model,coalesce(r.prompt_version,'provider-description-v2')))->>'allowed')::boolean,true) then return jsonb_build_object('ok',false,'reason','recovery_knowledge_unchanged_failure'); end if;
 if r.checks->'identity_snapshot' is not null and r.checks->'identity_snapshot' is distinct from security.provider_description_identity_snapshot_v1(r.provider_id) then return jsonb_build_object('ok',false,'reason','identity_changed_after_lease'); end if;
 if r.reserved_usd>0 then return jsonb_build_object('ok',false,'reason','existing_cost_reservation_uncertain','ai_calls',r.ai_calls,'reserved_usd',r.reserved_usd); end if;
 if security.pipeline_num_v1('pdesc.enabled',0)<1 or not security.ai_use_allowed_v1(case when security.pdesc_on_demand_live_v1(r.checks) then 'provider_description_on_demand' else 'provider_description' end) then /* 20261112010000 */ return jsonb_build_object('ok',false,'reason','ai_refused'); end if;
 select coalesce(sum(cost_usd),0),coalesce(sum(cost_usd) filter(where at>=date_trunc('day',now() at time zone 'UTC') at time zone 'UTC'),0) into v_spent,v_today from pipeline.ai_spend_ledger where lane='provider_description' and source<>'opening';
 select coalesce(sum(reserved_usd),0) into v_reserved from pipeline.provider_description_reads where reserved_usd>0 and id<>r.id;
 v_cap:=security.pipeline_num_v1('pdesc.ai_usd_max',1);
 v_daily:=coalesce((security.toolset_setting('openrouter','guard_provider_description')#>>'{}')::numeric,1);
 if v_spent+v_reserved+p_max_cost>v_cap and not security.pdesc_on_demand_live_v1(r.checks) then /* 20261112010000: on demand is not held by the lane ceiling */ return jsonb_build_object('ok',false,'reason','ai_ceiling','remaining_usd',greatest(0,v_cap-v_spent-v_reserved)); end if;
 if v_today+v_reserved+p_max_cost>v_daily and not security.pdesc_on_demand_live_v1(r.checks) then /* 20261112010000: nor by the lane daily guard */ return jsonb_build_object('ok',false,'reason','ai_daily_guard','remaining_usd',greatest(0,v_daily-v_today-v_reserved)); end if;
 update pipeline.provider_description_reads set reserved_usd=p_max_cost where id=r.id;
 return jsonb_build_object('ok',true,'reserved_usd',p_max_cost,'remaining_usd',greatest(0,v_cap-v_spent-v_reserved-p_max_cost));
end $$;


ALTER FUNCTION "public"."svc_provider_description_reserve_v1"("p_item" "uuid", "p_model" "text", "p_max_cost" numeric, "p_source_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_provider_description_reserve_v1"("p_item" "uuid", "p_model" "text", "p_max_cost" numeric, "p_source_hash" "text") IS 'Provider descriptions: service-only pre-call price reservation for the pinned approved model, inside the unchanged lifetime pilot ceiling and daily lane guard. Actual ledger cost replaces the reservation on record; no new spending authority.';



CREATE OR REPLACE FUNCTION "public"."svc_provider_document_check_record"("p_doc_key" "text", "p_url" "text", "p_sha256" "text", "p_http_status" integer, "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v_prev text; v_applied text; v_changed boolean;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  select sha256 into v_prev from pipeline.provider_document_checks where doc_key=p_doc_key and sha256 is not null order by checked_at desc limit 1;
  select e.content_hash into v_applied from pipeline.evidence_artifacts e where e.source_url=p_url order by e.captured_at desc nulls last limit 1;
  v_changed:=p_sha256 is not null and ((v_prev is not null and v_prev<>p_sha256) or (v_prev is null and v_applied is not null and v_applied<>p_sha256));
  insert into pipeline.provider_document_checks(doc_key,url,sha256,http_status,changed,applied_sha256,note)
  values (p_doc_key,p_url,p_sha256,p_http_status,v_changed,v_applied,left(p_note,300));
  return jsonb_build_object('changed',v_changed,'previous',v_prev,'applied',v_applied);
end $$;


ALTER FUNCTION "public"."svc_provider_document_check_record"("p_doc_key" "text", "p_url" "text", "p_sha256" "text", "p_http_status" integer, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_english_add_tests_v1"("p_proposal_id" "uuid", "p_parser" "text", "p_parsed" "jsonb", "p_error" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare x pipeline.provider_policy_proposals%rowtype; lv text; v_appr jsonb; v_base jsonb; v_new jsonb; v_ia numeric; v_ip numeric; q jsonb; c text;
        v_prop jsonb; v_added jsonb := '[]'::jsonb; v_skipped jsonb := '[]'::jsonb; v_ids uuid[]; v_courses uuid[] := '{}'; v_rows int := 0; v_out int := 0; n int;
        v_scope text[] := array(select jsonb_array_elements_text(coalesce(p_parsed->'add_only', '[]'::jsonb)));
        v_prior jsonb; v_keep text[]; v_day text := to_char(now() at time zone 'Australia/Melbourne', 'FMDD Mon YYYY');
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into x from pipeline.provider_policy_proposals where id = p_proposal_id for update;
  if x.id is null or x.kind <> 'english_policy' or x.status <> 'approved' then return jsonb_build_object('skipped', 'not an approved English policy'); end if;
  v_prior := coalesce(x.proposal->'added_tests'->'added', '[]'::jsonb);
  v_prop := x.proposal - 'added_tests';
  -- take out what this rule added before (it is read again below)
  for lv in select distinct e->>'level' from jsonb_array_elements(v_prior) e loop
    if jsonb_typeof(v_prop->'defaults'->lv) = 'array' then
      v_prop := jsonb_set(v_prop, array['defaults', lv], (select coalesce(jsonb_agg(a), '[]'::jsonb) from jsonb_array_elements(v_prop->'defaults'->lv) a
                                                         where not exists (select 1 from jsonb_array_elements(v_prior) e where e->>'level' = lv and e->>'test_code' = a->>'test_code')));
    end if;
  end loop;
  if p_parsed is not null and p_error is null and cardinality(v_scope) > 0 then
    for lv in select k from jsonb_object_keys(coalesce(p_parsed->'defaults', '{}'::jsonb)) k where k in ('undergraduate', 'postgraduate') loop
      v_base := v_prop->'defaults'->lv;
      if jsonb_typeof(v_base) is distinct from 'array' then
        v_skipped := v_skipped || jsonb_build_object('level', lv, 'why', 'the approved policy has no default for this level'); continue;
      end if;
      v_ia := null; v_ip := null;
      select (e->>'overall_score')::numeric into v_ia from jsonb_array_elements(v_base) e where e->>'test_code' = 'IELTS' limit 1;
      select (e->>'overall_score')::numeric into v_ip from jsonb_array_elements(p_parsed->'defaults'->lv) e where e->>'test_code' = 'IELTS' limit 1;
      if v_ia is null or v_ip is distinct from v_ia then
        v_skipped := v_skipped || jsonb_build_object('level', lv, 'why', format('IELTS on this reading (%s) is not the approved IELTS (%s)', coalesce(v_ip::text, 'none'), coalesce(v_ia::text, 'none')));
        if v_ip is not null and v_ia is not null then
          insert into pipeline.enrichment_flags(entity, entity_key, provider_id, field, reason_code, reason, source)
          values ('policy', x.id::text, x.provider_id, 'english', 'policy_reading_differs',
                  format('The %s IELTS on the stored policy page reads %s; the approved policy holds %s. A person checks the policy (%s)', lv, v_ip, v_ia, x.url), 'policy-add-tests')
          on conflict (entity, entity_key, field, reason_code) do update set reason = excluded.reason, flagged_at = now(), cleared_at = null;
        end if;
        continue;
      end if;
      select coalesce(jsonb_agg(e), '[]'::jsonb) into v_new from jsonb_array_elements(p_parsed->'defaults'->lv) e
       where e->>'test_code' = any (v_scope) and e->>'test_code' in (select t.code from ref.english_tests t where t.status = 'active')
         and not exists (select 1 from jsonb_array_elements(v_base) a where a->>'test_code' = e->>'test_code');
      if jsonb_array_length(v_new) = 0 then continue; end if;
      v_prop := jsonb_set(v_prop, array['defaults', lv], v_base || v_new);
      for q in select e from jsonb_array_elements(v_new) e loop
        with ins as (
          insert into catalogue.course_english_requirements(course_id, english_test_id, overall_score, component_scores, notes, source_id, evidence_id,
                                                            confidence, source_requirement_key, status, last_verified_at)
          select r.course_id, t.id, (q->>'overall_score')::numeric, coalesce(q->'component_scores', '{}'::jsonb),
                 format('%s %s from the same stored page, added %s (the page''s IELTS for this level matches the approved policy).', r.notes, t.name, v_day),
                 r.source_id, r.evidence_id, r.confidence, 'policy:' || x.id || ':' || lower(q->>'test_code'), 'active', now()
            from catalogue.course_english_requirements r
            join ref.english_tests ti on ti.id = r.english_test_id and ti.code = 'IELTS'
            join catalogue.courses co on co.id = r.course_id
            left join ref.study_levels sl on sl.id = co.study_level_id
            join ref.english_tests t on t.code = q->>'test_code'
           where r.source_requirement_key = 'policy:' || x.id || ':ielts' and r.status = 'active' and r.overall_score = v_ia
             and r.notes like 'Default for %'  -- level defaults only: a course the policy names keeps its own requirement
             and case when sl.code in ('bachelor', 'bachelor_honours', 'associate_degree') then 'undergraduate'
                      when sl.code in ('graduate_certificate', 'graduate_diploma', 'masters', 'masters_coursework', 'masters_extended') then 'postgraduate' end = lv
          on conflict (course_id, english_test_id) do update
             set overall_score = excluded.overall_score, component_scores = excluded.component_scores, notes = excluded.notes,
                 evidence_id = excluded.evidence_id, status = 'active', last_verified_at = now()
           where catalogue.course_english_requirements.source_requirement_key = excluded.source_requirement_key  -- only rows this rule wrote
          returning course_id)
        select array_agg(course_id) into v_ids from ins;
        v_rows := v_rows + coalesce(cardinality(v_ids), 0);
        v_courses := v_courses || coalesce(v_ids, '{}');
        v_added := v_added || jsonb_build_object('level', lv, 'test_code', q->>'test_code', 'overall_score', q->'overall_score', 'quote', q->>'quote',
                                                 'courses', coalesce(cardinality(v_ids), 0));
      end loop;
    end loop;
  end if;
  -- a test added before that this reading no longer gives for that level: its rows are withdrawn (kept, not deleted)
  for lv, c in select distinct e->>'level', e->>'test_code' from jsonb_array_elements(v_prior) e loop
    if exists (select 1 from jsonb_array_elements(v_added) a where a->>'level' = lv and a->>'test_code' = c) then continue; end if;
    with w as (
      update catalogue.course_english_requirements r set status = 'withdrawn', last_verified_at = now(),
             notes = r.notes || format(' Withdrawn %s: the stored page read again no longer gives it for this level.', v_day)
        from catalogue.courses co left join ref.study_levels sl on sl.id = co.study_level_id
       where co.id = r.course_id and r.source_requirement_key = 'policy:' || x.id || ':' || lower(c) and r.status = 'active'
         and r.notes like '%from the same stored page, added%'
         and case when sl.code in ('bachelor', 'bachelor_honours', 'associate_degree') then 'undergraduate'
                  when sl.code in ('graduate_certificate', 'graduate_diploma', 'masters', 'masters_coursework', 'masters_extended') then 'postgraduate' end = lv
      returning r.course_id)
    select array_agg(course_id) into v_ids from w;
    n := coalesce(cardinality(v_ids), 0); v_out := v_out + n;
    v_courses := v_courses || coalesce(v_ids, '{}');
  end loop;
  update pipeline.provider_policy_proposals
     set proposal = v_prop || jsonb_build_object('added_tests', jsonb_build_object('parser', p_parser, 'checked_at', now(), 'added', v_added, 'skipped', v_skipped,
                                                                                 'withdrawn_rows', v_out, 'error', p_error)),
         plan_at = case when v_rows + v_out > 0 then null else plan_at end, updated_at = now()
   where id = x.id;
  if cardinality(v_courses) > 0 then
    perform search.refresh_course_enrichment_scoped_v1((select array_agg(distinct cc) from unnest(v_courses) cc), true);
  end if;
  if v_rows + v_out > 0 then
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('policies', 'add_tests', 'english_policy: ' || x.url, jsonb_build_object('proposal_id', x.id, 'provider_id', x.provider_id, 'parser', p_parser,
            'added', v_added, 'rows', v_rows, 'withdrawn_rows', v_out), null);
  end if;
  return jsonb_build_object('added', jsonb_array_length(v_added), 'rows', v_rows, 'withdrawn', v_out, 'skipped', jsonb_array_length(v_skipped));
end $$;


ALTER FUNCTION "public"."svc_provider_english_add_tests_v1"("p_proposal_id" "uuid", "p_parser" "text", "p_parsed" "jsonb", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_facts_docs"("p_ids" "uuid"[], "p_kind" "text", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  return coalesce((select jsonb_agg(x) from (
    select jsonb_build_object('id', f.id, 'provider_id', f.provider_id, 'kind', f.kind, 'url', f.url, 'rank', f.rank,
             'provider', p.canonical_name, 'country', k.iso_alpha2, 'storage_path', e.storage_path, 'sha256', f.content_hash) x
      from pipeline.provider_fact_sources f
      join pipeline.evidence_artifacts e on e.id = f.evidence_id
      join catalogue.providers p on p.id = f.provider_id
      left join ref.countries k on k.id = p.country_id
     where f.status in ('read', 'parsed', 'no_values') and e.storage_path is not null
       and (p_ids is null or cardinality(p_ids) = 0 or f.id = any(p_ids))
       and (p_kind is null or f.kind = p_kind)
     order by f.read_at desc nulls last
     limit greatest(1, least(coalesce(p_limit, 20), 400))) s), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."svc_provider_facts_docs"("p_ids" "uuid"[], "p_kind" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_facts_read_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  with pick as (
    select f.id from pipeline.provider_fact_sources f
     where ((f.kind = 'fee_schedule' and security.tuition_chase_enabled(f.provider_id))
            or f.kind in ('english_policy', 'intake_calendar'))
       and (f.status = 'found' or (f.status = 'reading' and f.updated_at < now() - interval '20 minutes')) and f.attempts < security.pipeline_num_v1('retry.provider_facts_attempts', 3)
       and not (f.status = 'found' and security.provider_fact_refusal_v1(f.parse_summary->>'error')
                and f.updated_at > now() - make_interval(hours => security.pipeline_num_v1('retry.provider_facts_refusal_hours', 6)::int))  -- CF-247 7 Nov 2026: a refused page waits, it is not read at once again
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = f.provider_id)  -- v2.15.237: paused while the provider is unpublished or archived
     order by (f.linked_from is null), f.rank,
              (select count(*) from catalogue.courses c where c.provider_id = f.provider_id and c.lifecycle_status = 'active') desc, f.created_at limit greatest(1, least(coalesce(p_limit, 10), 30))
     for update skip locked),
  upd as (update pipeline.provider_fact_sources f set status = 'reading', attempts = f.attempts + 1, updated_at = now() from pick where f.id = pick.id
          returning f.id, f.provider_id, f.kind, f.url)
  select coalesce(jsonb_agg(jsonb_build_object('id', u.id, 'provider_id', u.provider_id, 'kind', u.kind, 'url', u.url,
           'country', (select k.iso_alpha2 from catalogue.providers p join ref.countries k on k.id = p.country_id where p.id = u.provider_id),
           'currency', (select a.currency_code from catalogue.providers p join pipeline.coverage_admission_countries a on a.country_id = p.country_id where p.id = u.provider_id))), '[]'::jsonb)
    into v from upd u;
  return v;
end $$;


ALTER FUNCTION "public"."svc_provider_facts_read_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_facts_read_record"("p_id" "uuid", "p_status" "text", "p_http" integer, "p_storage_path" "text", "p_sha256" "text", "p_mime" "text", "p_rows" "jsonb", "p_summary" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare f pipeline.provider_fact_sources%rowtype; v_src uuid; v_ev uuid; v_cur text; v_n int := 0;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into f from pipeline.provider_fact_sources where id = p_id for update;
  if f.id is null then raise exception 'source not found'; end if;
  if p_status not in ('read','failed') then raise exception 'status must be read or failed'; end if;
  if p_status = 'failed' then
    -- CF-247 7 Nov 2026: a refusal (credits, the target list, the run's time) is not the page failing: the try it used is given back and the page stays found
    if security.provider_fact_refusal_v1(p_summary->>'error') then
      update pipeline.provider_fact_sources set status = 'found', attempts = greatest(attempts - 1, 0), http_status = p_http,
             parse_summary = p_summary, updated_at = now() where id = p_id;
      return jsonb_build_object('status', 'refused');
    end if;
    update pipeline.provider_fact_sources set status = case when attempts >= 3 then 'failed' else 'found' end, http_status = p_http,
           parse_summary = p_summary, updated_at = now() where id = p_id;
    return jsonb_build_object('status', 'failed');
  end if;
  if p_storage_path is not null and p_sha256 ~ '^[0-9a-f]{64}$' then
    v_src := security.coverage_sweep_source(f.provider_id);
    select id into v_ev from pipeline.evidence_artifacts where source_id = v_src and content_hash = p_sha256 and source_url = f.url limit 1;
    if v_ev is null then
      v_ev := public.svc_coursefacts_register_evidence(v_src, f.url, p_storage_path, p_sha256, coalesce(p_mime, 'text/markdown'),
                jsonb_build_object('layer', 2, 'kind', 'provider_' || f.kind, 'worker', 'coverage-sweep', 'provider_fact_source_id', f.id) || case when p_http is not null then jsonb_build_object('page_status', p_http) else '{}'::jsonb end);
    end if;
  end if;
  select a.currency_code into v_cur from catalogue.providers p join pipeline.coverage_admission_countries a on a.country_id = p.country_id where p.id = f.provider_id;
  -- a re-read replaces the rows parsed before (kept, marked not current, for the record)
  update pipeline.provider_fee_rows set current = false where source_id = p_id and current;
  if f.kind = 'fee_schedule' and v_cur is not null then
    insert into pipeline.provider_fee_rows(source_id, provider_id, course_code, amount, currency_code, basis, fee_year, column_label, row_text)
    select p_id, f.provider_id, upper(btrim(r->>'course_code')), (r->>'amount')::numeric, v_cur, nullif(r->>'basis', ''), nullif(r->>'fee_year', '')::int,
           left(r->>'column_label', 120), left(r->>'row_text', 500)
      from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) r
     where coalesce(r->>'course_code', '') ~ '^[0-9A-Za-z]{4,12}$' and coalesce(r->>'amount', '') ~ '^[0-9]+(\.[0-9]+)?$'
       and (r->>'amount')::numeric between 1000 and 200000
       and coalesce(nullif(r->>'basis', ''), 'annual') in ('annual','per_semester','per_trimester','total_indicative')
    on conflict on constraint provider_fee_rows_key do update set current = true, fee_year = excluded.fee_year, column_label = excluded.column_label, row_text = excluded.row_text;
    get diagnostics v_n = row_count;
  end if;
  update pipeline.provider_fact_sources set status = case when f.kind <> 'fee_schedule' then 'read' when v_n > 0 then 'parsed' else 'no_values' end,
         http_status = p_http, evidence_id = coalesce(v_ev, evidence_id), content_hash = coalesce(p_sha256, content_hash), read_at = now(),
         parse_summary = coalesce(p_summary, '{}'::jsonb) || jsonb_build_object('fee_rows', v_n), updated_at = now()
   where id = p_id;
  return jsonb_build_object('status', 'read', 'fee_rows', v_n, 'evidence_id', v_ev);
end $_$;


ALTER FUNCTION "public"."svc_provider_facts_read_record"("p_id" "uuid", "p_status" "text", "p_http" integer, "p_storage_path" "text", "p_sha256" "text", "p_mime" "text", "p_rows" "jsonb", "p_summary" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_facts_read_record_v2"("p_id" "uuid", "p_status" "text", "p_http" integer, "p_storage_path" "text", "p_sha256" "text", "p_mime" "text", "p_rows" "jsonb", "p_summary" "jsonb", "p_links" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare f pipeline.provider_fact_sources%rowtype; v_dom text; v jsonb; v_n int := 0;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  v := public.svc_provider_facts_read_record(p_id, p_status, p_http, p_storage_path, p_sha256, p_mime, p_rows, p_summary);
  select * into f from pipeline.provider_fact_sources where id = p_id;
  if p_status = 'read' and f.kind = 'fee_schedule' and f.linked_from is null and jsonb_typeof(p_links) = 'array' then
    select r.search_domain into v_dom from pipeline.course_link_recipes r where r.provider_id = f.provider_id;
    insert into pipeline.provider_fact_sources(provider_id, kind, url, title, rank, linked_from)
    select f.provider_id, 'fee_schedule', left(x.url, 2000), 'Linked from ' || left(f.url, 200), x.rk, f.id
      from (select e->>'url' url, row_number() over (order by coalesce(nullif(e->>'year', '')::int, 0) desc) rk
              from jsonb_array_elements(p_links) e
             where (e->>'url') ~* ('^https?://([a-z0-9-]+\.)*' || regexp_replace(coalesce(v_dom, '#'), '([.-])', '\\\1', 'g') || '(/|$)')) x
     where x.rk <= 4
    on conflict (provider_id, kind, url) do nothing;
    get diagnostics v_n = row_count;
  end if;
  return v || jsonb_build_object('linked', v_n);
end $_$;


ALTER FUNCTION "public"."svc_provider_facts_read_record_v2"("p_id" "uuid", "p_status" "text", "p_http" integer, "p_storage_path" "text", "p_sha256" "text", "p_mime" "text", "p_rows" "jsonb", "p_summary" "jsonb", "p_links" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_facts_search_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  with pick as (
    select s.provider_id, s.kind, dom.d search_domain
      from pipeline.provider_fact_search s
      join catalogue.providers pr on pr.id = s.provider_id
      left join pipeline.course_link_recipes r on r.provider_id = s.provider_id and r.active
      -- CF-247 6 Nov 2026 (English requirements, decision D3): without a course link recipe, a provider's own website host is the search domain for its English
      -- page, and only while central.english_search_non_university is 1 (shipped 0, so the picks are exactly what they were)
      cross join lateral (select coalesce(r.search_domain, case when s.kind = 'english_policy' and security.pipeline_num_v1('central.english_search_non_university', 0) = 1
                                  then nullif(regexp_replace(regexp_replace(coalesce(btrim(pr.website), ''), '^https?://(www\.)?', '', 'i'), '[/?#].*$', ''), '') end) d) dom
     where dom.d is not null
       and (s.state = 'queued' or (s.state = 'sent' and s.sent_at < now() - interval '20 minutes' and s.attempts < security.pipeline_num_v1('retry.provider_facts_attempts', 3)))
       and (s.kind <> 'fee_schedule' or security.tuition_chase_enabled(s.provider_id))
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = s.provider_id)  -- v2.15.237: paused while the provider is unpublished or archived
     order by (s.kind <> 'fee_schedule'), s.queued_at, s.provider_id limit greatest(1, least(coalesce(p_limit, 20), 60))
     for update of s skip locked),
  upd as (
    update pipeline.provider_fact_search s set state = 'sent', sent_at = now(), attempts = s.attempts + 1,
           query = case p.kind when 'fee_schedule' then 'international student tuition fees site:' || p.search_domain
                               when 'english_policy' then 'English language requirements international students site:' || p.search_domain
                               else 'academic calendar key dates intakes site:' || p.search_domain end
      from pick p where s.provider_id = p.provider_id and s.kind = p.kind
    returning s.provider_id, s.kind, s.query)
  select coalesce(jsonb_agg(jsonb_build_object('provider_id', provider_id, 'kind', kind, 'query', query)), '[]'::jsonb) into v from upd;
  return v;
end $_$;


ALTER FUNCTION "public"."svc_provider_facts_search_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_facts_search_record"("p_provider_id" "uuid", "p_kind" "text", "p_http" integer, "p_results" "jsonb", "p_error" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_dom text; v_n int := 0;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select r.search_domain into v_dom from pipeline.course_link_recipes r where r.provider_id = p_provider_id;
  if p_http <> 200 then
    update pipeline.provider_fact_search set state = case when attempts >= 3 then 'error' else 'queued' end where provider_id = p_provider_id and kind = p_kind;
    return 0;
  end if;
  insert into pipeline.provider_fact_sources(provider_id, kind, url, title, rank)
  select p_provider_id, p_kind, x.url, left(x.title, 300), x.rk
    from (select e->>'url' url, e->>'title' title, row_number() over () rk
            from jsonb_array_elements(coalesce(p_results, '[]'::jsonb)) e
           where (e->>'url') ~* ('^https?://([a-z0-9-]+\.)*' || regexp_replace(coalesce(v_dom, '#'), '([.-])', '\\\1', 'g') || '(/|$)')) x
   where x.rk <= 3
  on conflict (provider_id, kind, url) do nothing;
  get diagnostics v_n = row_count;
  update pipeline.provider_fact_search set state = case when v_n > 0 or exists (select 1 from pipeline.provider_fact_sources f where f.provider_id = p_provider_id and f.kind = p_kind) then 'done' else 'none' end,
         done_at = now() where provider_id = p_provider_id and kind = p_kind;
  return v_n;
end $_$;


ALTER FUNCTION "public"."svc_provider_facts_search_record"("p_provider_id" "uuid", "p_kind" "text", "p_http" integer, "p_results" "jsonb", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_policy_add_tests_next"("p_parser" "text", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  return coalesce((select jsonb_agg(s.x) from (
    select jsonb_build_object('id', pp.id, 'source_id', pp.fact_source_id, 'provider', p.canonical_name, 'url', pp.url, 'storage_path', e.storage_path) x
      from pipeline.provider_policy_proposals pp
      join pipeline.evidence_artifacts e on e.id = pp.evidence_id
      join catalogue.providers p on p.id = pp.provider_id
     where pp.kind = 'english_policy' and pp.status = 'approved' and e.storage_path is not null
       and pp.parser <> 'written out from the central page'  -- Decision 264: hand-written policies are not read again by the parser
       and coalesce(pp.proposal->'added_tests'->>'parser', '') is distinct from p_parser
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = pp.provider_id)  -- 22 Oct 2026 (Platform Admin 11:42): unpublished providers wait; publishing them again brings them back
     order by pp.decided_at
     limit greatest(1, least(coalesce(p_limit, 40), 200))) s), '[]'::jsonb);  -- fixed: per-call safety cap; the run size is batch.policy_add_tests
end $$;


ALTER FUNCTION "public"."svc_provider_policy_add_tests_next"("p_parser" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_policy_record"("p_source_id" "uuid", "p_parsed" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare f pipeline.provider_fact_sources%rowtype; v_id uuid; v_status text; v_parser text := coalesce(p_parsed->>'parser', 'unknown');
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into f from pipeline.provider_fact_sources where id = p_source_id;
  if f.id is null or f.kind not in ('english_policy', 'intake_calendar') then raise exception 'not an English policy or calendar document'; end if;
  if jsonb_typeof(p_parsed) <> 'object' then raise exception 'parsed result must be an object'; end if;
  v_status := case
    when f.kind = 'english_policy' and (coalesce(p_parsed->'defaults', '{}'::jsonb) <> '{}'::jsonb
           or exists (select 1 from jsonb_array_elements(coalesce(p_parsed->'exceptions', '[]'::jsonb)) e
                       where jsonb_typeof(e->'reqs') = 'array' and jsonb_array_length(e->'reqs') > 0)
           -- CF-247 6 Nov 2026 (English requirements, parser v0.3.0): a faculty or course-group table is a proposal when a group has a quoted score
           or (jsonb_typeof(p_parsed->'groups') = 'array' and exists (select 1 from jsonb_array_elements(p_parsed->'groups') g, jsonb_array_elements(case when jsonb_typeof(g->'reqs') = 'array' then g->'reqs' else '[]'::jsonb end) q
                where coalesce(q->>'quote', '') <> '' and q->>'overall_score' ~ '^[0-9]+(\.[0-9]+)?$'))) then 'proposed'
    when f.kind = 'intake_calendar' and jsonb_array_length(coalesce(p_parsed->'periods', '[]'::jsonb)) > 0 then 'proposed'
    else 'no_values' end;
  insert into pipeline.provider_policy_proposals(provider_id, fact_source_id, kind, parser, content_hash, evidence_id, url, style, proposal, status)
  values (f.provider_id, f.id, f.kind, v_parser, f.content_hash, f.evidence_id, f.url, left(p_parsed->>'style', 40), p_parsed, v_status)
  on conflict on constraint provider_policy_proposals_key do update
     set proposal = case when pipeline.provider_policy_proposals.proposal ? 'group_bindings' then excluded.proposal || jsonb_build_object('group_bindings', pipeline.provider_policy_proposals.proposal->'group_bindings') else excluded.proposal end,  -- a person's bindings survive a re-read by the same parser
         style = excluded.style, evidence_id = excluded.evidence_id,
         status = case when pipeline.provider_policy_proposals.status in ('proposed', 'no_values') then excluded.status else pipeline.provider_policy_proposals.status end,
         updated_at = now()
  returning id, status into v_id, v_status;
  update pipeline.provider_policy_proposals set status = 'superseded', updated_at = now()
   where fact_source_id = f.id and id <> v_id and status in ('proposed', 'no_values') and parser <> 'written out from the central page';
  return jsonb_build_object('id', v_id, 'status', v_status);
end $_$;


ALTER FUNCTION "public"."svc_provider_policy_record"("p_source_id" "uuid", "p_parsed" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_provider_policy_reparse_next"("p_parser" "text", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  return coalesce((select jsonb_agg(s.x) from (
    select jsonb_build_object('id', f.id, 'provider', p.canonical_name, 'url', f.url, 'storage_path', e.storage_path) x
      from pipeline.provider_fact_sources f
      join pipeline.evidence_artifacts e on e.id = f.evidence_id and e.storage_path is not null
      join catalogue.providers p on p.id = f.provider_id
     where f.kind = 'english_policy' and f.status in ('read', 'parsed', 'no_values')
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = f.provider_id)  -- unpublished providers wait, as for the other policy jobs
       and not exists (select 1 from pipeline.provider_policy_proposals pp where pp.fact_source_id = f.id and pp.parser = p_parser)  -- each page is read once per parser version
       and not exists (select 1 from pipeline.provider_policy_proposals pp where pp.fact_source_id = f.id and pp.status in ('approved', 'proposed'))  -- a live reading is never read over
       and exists (select 1 from pipeline.provider_policy_proposals pp where pp.fact_source_id = f.id
                      and (pp.status = 'no_values' or (pp.status = 'rejected' and coalesce(pp.decision_note, '') ~* 'facult')))
     order by (select count(*) from catalogue.courses c where c.provider_id = f.provider_id and c.lifecycle_status = 'active') desc, f.id
     limit greatest(1, least(coalesce(p_limit, 20), 200))) s), '[]'::jsonb);  -- fixed: per-call safety cap; the run size is batch.policy_reparse
end $$;


ALTER FUNCTION "public"."svc_provider_policy_reparse_next"("p_parser" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_provider_policy_reparse_next"("p_parser" "text", "p_limit" integer) IS 'CF-247 English requirements (6 Nov 2026 D5): stored English pages whose latest reading gave no values (or was rejected as one faculty row) and that the given parser has not read. The policy-add-tests job reads them again from the stored copy: no Firecrawl, no AI.';



CREATE OR REPLACE FUNCTION "public"."svc_provider_register_facts_put"("p_source_id" "uuid", "p_evidence_id" "uuid", "p_scheme" "text", "p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_out jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  with src as materialized (
    select ord, upper(btrim(c)) code, r->'facts' facts, security.register_name_key_v1(r->'names'->>0) name_key
    from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) with ordinality x(r, ord)
    cross join lateral jsonb_array_elements_text(coalesce(r->'codes', '[]'::jsonb)) c
    where btrim(c) <> ''
  ), reg as (
    select distinct on (upper(pr.registration_code)) upper(pr.registration_code) code, pr.provider_id
    from catalogue.provider_registrations pr
    where lower(pr.registration_scheme) = lower(p_scheme)
    order by upper(pr.registration_code), pr.checked_at desc nulls last
  ), m0 as (
    select s.ord, s.code, s.facts, s.name_key, coalesce(reg.provider_id, p.id) provider_id
    from src s
    left join reg on reg.code = s.code
    left join catalogue.providers p on p.stable_key = 'provider:' || lower(p_scheme) || ':' || lower(s.code)
  ), consistent as materialized (
    select name_key from src where name_key is not null group by 1 having count(distinct facts::text) = 1
  ), named as materialized (
    select p.id provider_id, security.register_name_key_v1(p.canonical_name) name_key
    from catalogue.providers p
    where p.stable_key like 'provider:' || lower(p_scheme) || ':%'
  ), m as materialized (
    select ord, code, facts, provider_id, false by_name from m0 where provider_id is not null
    union all
    select s.ord, s.code, s.facts, n.provider_id, true
    from m0 s
    join consistent k on k.name_key = s.name_key
    join named n on n.name_key = s.name_key
      or (strpos(s.name_key, '?') > 0 and n.name_key like replace(s.name_key, '?', '_'))
      or (strpos(n.name_key, '?') > 0 and s.name_key like replace(n.name_key, '?', '_'))
    where s.provider_id is null
  ), f as (
    select distinct on (m.provider_id, e.key) m.provider_id, e.key fact_code, nullif(btrim(e.value), '') fact_value
    from m cross join lateral jsonb_each_text(coalesce(m.facts, '{}'::jsonb)) e
    order by m.provider_id, e.key, m.by_name, m.ord desc
  ), w as (
    insert into catalogue.provider_register_facts (provider_id, fact_code, value, source_id, evidence_id, observed_at)
    select provider_id, fact_code, fact_value, p_source_id, p_evidence_id, now() from f
    on conflict (provider_id, fact_code) do update set value = excluded.value, source_id = excluded.source_id,
      evidence_id = coalesce(excluded.evidence_id, catalogue.provider_register_facts.evidence_id), observed_at = now()
    returning 1
  )
  select jsonb_build_object(
    'rows', jsonb_array_length(coalesce(p_rows, '[]'::jsonb)),
    'providers_matched', (select count(distinct provider_id) from m),
    'codes_unmatched', (select count(*) from m0 where provider_id is null and not exists (select 1 from m where m.code = m0.code)),
    'matched_by_name', (select count(distinct provider_id) from m where by_name),
    'facts_written', (select count(*) from w))
  into v_out;
  return v_out;
end $$;


