CREATE OR REPLACE FUNCTION "public"."svc_scholarship_ai_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare v jsonb; v_rt jsonb := security.ai_route_gate_v1('scholarship_extraction'); v_reuse int := security.pipeline_num_v1('waste.page_reuse_hours', 24)::int; v_win bigint[]; v_tp text[]; v_off uuid[];
        v_scan int := security.pipeline_num_v1('batch.sch_ai_pick_scan', 60)::int;
        -- CF-247 P0 mandate 3 Nov 2026 §6: while the scholarship Firecrawl lane is held, only items with a stored copy are taken
        v_paid boolean := security.pipeline_num_v1('lanes.stored_first_on', 1) < 1 or security.lane_paid_hold_v1('sch_scrape') is null;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  -- CF-247 F-SCH 13 Nov 2026: one bounded window of the next items, in the picker's order and filters; only these are checked and leased
  -- (the due items are put in order first and the per-item checks run only until the window is full: offset 0 keeps them out of the sort)
  select array_agg(w.id) into v_win from (
    select o.id from (select q.id, q.provider_id, q.run_kind from pipeline.scholarship_ai_queue q
                       left join pipeline.scholarship_page_candidates cd on cd.id = q.candidate_id  -- F-SCH.15: never-decided pages first
                       where ((q.state = 'queued' and q.next_try_at <= now()) or (q.state = 'leased' and q.leased_until < now())) and q.attempts < 3
                       order by (q.run_kind = 'test') desc, (q.run_kind = 'qualify') desc, q.step desc, (cd.admit_status is not null), q.id offset 0) o
     where (o.provider_id is null or o.run_kind in ('test', 'qualify') or not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = o.provider_id))
       and (v_paid or security.scholarship_ai_has_copy_v1(o.id))
     limit greatest(20, least(v_scan, 2000))) w;
  -- the same two checks, once per distinct site and provider in the window (one row each), not once per item: 67 ms for 200 items, was 1.1 s per item check
  select array_agg(h.host) into v_tp from (select distinct on (security.site_host_v1(w.url)) security.site_host_v1(w.url) host, w.url
                                              from pipeline.scholarship_ai_queue w where w.id = any(v_win)) h
   where h.host is not null and security.third_party_host_v1(h.url);
  select array_agg(p.provider_id) into v_off from (select distinct w.provider_id from pipeline.scholarship_ai_queue w where w.id = any(v_win) and w.provider_id is not null) p
   where security.provider_sch_search_off_v1(p.provider_id);
  -- v2.15.271 (Platform Admin, 14 Oct 2026): pages on a directory site, and providers whose scholarship search is Off, are closed, not read
  update pipeline.scholarship_ai_queue q
     set state = 'failed', done_at = now(), leased_until = null,
         skip_reason = case when security.third_party_host_v1(q.url) then 'directory site' else 'scholarship search off for this provider' end
   where q.id = any(v_win) and q.state in ('queued', 'leased')  -- F-SCH 13 Nov 2026: the window only (was every due item: 27 s at 8,981)
     and (security.site_host_v1(q.url) = any(v_tp) or q.provider_id = any(v_off));
  -- CF-247 15 Oct (waste rules): a queued candidate whose page was stored within the reuse time takes that copy, so it is not read again
  update pipeline.scholarship_page_candidates c set storage_path = x.storage_path, content_hash = x.content_hash, evidence_id = coalesce(c.evidence_id, x.evidence_id)
    from (select distinct on (q.candidate_id) q.candidate_id, e.storage_path, e.content_hash, e.evidence_id
            from pipeline.scholarship_ai_queue q
            join pipeline.scholarship_ai_extractions e on e.url = q.url and e.storage_path is not null and e.error is null and e.at > now() - make_interval(hours => v_reuse)
           where q.state = 'queued' and q.next_try_at <= now() and q.candidate_id is not null and not q.fresh_read  -- CF-247 4 Nov 2026: an approved fresh read takes no copy
           order by q.candidate_id, e.at desc) x
   where c.id = x.candidate_id and c.storage_path is null and v_reuse > 0;
  with pick as (
    select q.id from pipeline.scholarship_ai_queue q
     where ((q.state = 'queued' and q.next_try_at <= now()) or (q.state = 'leased' and q.leased_until < now())) and q.attempts < 3 and q.id = any(v_win)  -- F-SCH 13 Nov 2026: only from the checked window
       and (q.provider_id is null or q.run_kind in ('test', 'qualify') or not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = q.provider_id))  -- 22 Oct 2026 (Platform Admin 11:42): unpublished providers wait; publishing them again brings them back
       -- 13 Nov 2026: the route's switch, cap and the daily ceiling (a test or qualification run a person started is not held by a limit); a model that is not allowed waits
       and (security.ai_route_open_v1(v_rt, q.provider_id) or (q.run_kind in ('test', 'qualify') and coalesce((v_rt->>'on_demand_exempt')::boolean, false)))
       and exists (select 1 from pipeline.ai_model_catalogue am where am.code = q.model_code and am.status = 'allowed')
       and (v_paid or security.scholarship_ai_has_copy_v1(q.id))  -- the others wait, with no try used (they were refused and closed after 3 tries)
     order by (q.run_kind = 'test') desc, (q.run_kind = 'qualify') desc, q.step desc, q.id
     limit greatest(1, least(coalesce(p_limit, 8), 20)) for update skip locked),
  upd as (update pipeline.scholarship_ai_queue q set state = 'leased', leased_until = now() + interval '4 minutes', attempts = q.attempts + 1 from pick where q.id = pick.id returning q.*)
  select coalesce(jsonb_agg(jsonb_build_object('queue_id', u.id, 'model_code', u.model_code, 'model', m.model_identifier, 'prompt_version', u.prompt_version,
           'prompt', (select p.text from pipeline.scholarship_ai_prompts p where p.version = u.prompt_version), 'run_kind', u.run_kind, 'url', u.url, 'recovery', u.recovery,
           'scholarship_name', (select s.name from scholarship.scholarships s where s.id = u.scholarship_id),
           'candidate_id', u.candidate_id, 'scholarship_id', u.scholarship_id, 'provider_id', u.provider_id, 'country', case when u.provider_id is not null then security.coverage_country(u.provider_id) end,  -- v2.15.256
           'provider', (select coalesce(pr.display_name, pr.canonical_name) from catalogue.providers pr where pr.id = u.provider_id),
           'currency', case when u.provider_id is not null then scholarship.provider_currency(u.provider_id) else 'AUD' end,
           'storage_path', case when u.fresh_read then null else coalesce(u.storage_path, (select c.storage_path from pipeline.scholarship_page_candidates c where c.id = u.candidate_id),
                                    (select e.storage_path from pipeline.scholarship_pages sp join pipeline.evidence_artifacts e on e.id = sp.evidence_id where sp.scholarship_id = u.scholarship_id),
                                    (select e.storage_path from scholarship.scholarships s join pipeline.evidence_artifacts e on e.id = s.evidence_id where s.id = u.scholarship_id),
                                    -- CF-247 15 Oct (waste rules): a copy of the same page stored within the reuse time
                                    (select x.storage_path from pipeline.scholarship_ai_extractions x where x.url = u.url and x.storage_path is not null and x.error is null and x.at > now() - make_interval(hours => v_reuse) order by x.at desc limit 1)) end)), '[]'::jsonb)
    into v from upd u join pipeline.ai_model_catalogue m on m.code = u.model_code;
  return v;
end $$;


ALTER FUNCTION "public"."svc_scholarship_ai_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_ai_record"("p_queue_id" bigint, "p_answer" "jsonb", "p_checks" "jsonb", "p_verdict" "text", "p_cost" numeric, "p_tokens_in" integer, "p_tokens_out" integer, "p_seconds" numeric, "p_error" "text", "p_storage_path" "text", "p_sha256" "text", "p_final_url" "text", "p_rule_facts" "jsonb", "p_retry" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare q pipeline.scholarship_ai_queue%rowtype; v_id bigint; v_ev uuid; v_on boolean; r jsonb; v_why text; v_next text; v_prev record;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  -- R5 (14 Nov 2026): search refreshes this answer causes are queued (search.course_refresh_requests) so the paid answer commits inside the 8 s limit
  if security.pipeline_num_v1('search.defer_ai_record_refresh_on', 1) = 1 then perform set_config('cf247.defer_search_refresh', 'on', true); end if;
  select * into q from pipeline.scholarship_ai_queue where id = p_queue_id for update;
  if q.id is null then return jsonb_build_object('ok', false, 'reason', 'no queue item'); end if;
  if p_retry then
    -- CF-247 7 Nov 2026: a read refused for credits, the university cap or the run's time is not the page failing. It gives its try back and waits
    -- (retry.sch_ai_wait_minutes); it is closed only when it has waited longer than sch_ai.wait_max_days. Before this it was closed "after 3 tries" (202 items).
    update pipeline.scholarship_ai_queue set attempts = greatest(attempts - 1, 0), leased_until = null,
           state = case when q.created_at < now() - make_interval(days => security.pipeline_num_v1('sch_ai.wait_max_days', 14)::int) then 'failed' else 'queued' end,
           done_at = case when q.created_at < now() - make_interval(days => security.pipeline_num_v1('sch_ai.wait_max_days', 14)::int) then now() end,
           skip_reason = case when q.created_at < now() - make_interval(days => security.pipeline_num_v1('sch_ai.wait_max_days', 14)::int) then 'no scraper credit within the waiting time' end,
           next_try_at = now() + make_interval(mins => security.pipeline_num_v1('retry.sch_ai_wait_minutes', 30)::int) where id = q.id;
    -- an approved single read that has waited longer than the waiting time ends its request
    if q.read_request_id is not null and q.created_at < now() - make_interval(days => security.pipeline_num_v1('sch_ai.wait_max_days', 14)::int) then
      update pipeline.scholarship_read_requests set state = 'refused', finished_at = now(), outcome = jsonb_build_object('why', 'no scraper credit within the waiting time')
       where id = q.read_request_id and state = 'queued';
    end if;
    return jsonb_build_object('ok', true, 'retry', true);
  end if;
  -- v2.15.256: a value an earlier model in this chain proved stands when this model's value is not proven (its own proven value wins)
  if p_error is null and p_verdict = 'scholarship' and not coalesce((p_checks->>'value')::boolean, false)
     and coalesce(p_answer->'value'->>'kind', 'not_stated') not in ('not_stated', 'non_monetary') then
    -- R5 (14 Nov 2026): the root row and its children by id and root_id (indexed), the same rows as the join on coalesce(root_id, id)
    select e.answer->'value' val, e.model_code into v_prev from pipeline.scholarship_ai_extractions e
     where e.queue_id in (select x.id from pipeline.scholarship_ai_queue x where x.id = coalesce(q.root_id, q.id) and coalesce(x.root_id, x.id) = coalesce(q.root_id, q.id)
                          union all
                          select x.id from pipeline.scholarship_ai_queue x where x.root_id = coalesce(q.root_id, q.id))
       and e.queue_id <> q.id and e.verdict = 'scholarship' and e.error is null
       and coalesce((e.checks->>'value')::boolean, false) order by e.id desc limit 1;
    if v_prev.val is not null then
      p_answer := jsonb_set(p_answer, '{value}', v_prev.val) || jsonb_build_object('value_from', v_prev.model_code);
      p_checks := p_checks || jsonb_build_object('value', true);
    end if;
  end if;
  -- a candidate page read live for the first time: its copy and read are recorded on the candidate, as the scheduled reader does
  if q.candidate_id is not null and p_storage_path is not null then
    update pipeline.scholarship_page_candidates set storage_path = p_storage_path, content_hash = p_sha256, final_url = coalesce(p_final_url, final_url), read_at = now(),
           read_status = coalesce(nullif(p_rule_facts->>'read_status', ''), 'read'), next_read_at = now() + make_interval(days => security.pipeline_num_v1('reread.scholarship_ai_days', 90)::int), leased_until = null,
           facts = case when p_rule_facts ? 'facts' then p_rule_facts->'facts' else facts end
     where id = q.candidate_id;
  end if;
  if p_storage_path is not null then
    insert into pipeline.evidence_artifacts(source_id, evidence_type, source_url, storage_path, content_hash, mime_type, metadata, capture_version, evidence_group_key)
    values (security.coverage_sweep_source(q.provider_id), 'scholarship_ai_page', coalesce(p_final_url, q.url), p_storage_path, p_sha256, 'application/gzip',
            jsonb_build_object('queue_id', q.id, 'candidate_id', q.candidate_id, 'scholarship_id', q.scholarship_id, 'model', q.model_code, 'worker', 'coverage-sweep scholarship_ai'), 1, 'scholarship_ai:' || q.id)
    returning id into v_ev;
    if q.candidate_id is not null then update pipeline.scholarship_page_candidates set evidence_id = coalesce(evidence_id, v_ev) where id = q.candidate_id; end if;
  end if;
  insert into pipeline.scholarship_ai_extractions(queue_id, model_code, model_identifier, prompt_version, run_kind, job_id, sample_id, candidate_id, scholarship_id, provider_id, url,
         storage_path, content_hash, evidence_id, answer, checks, verdict, cost_usd, tokens_in, tokens_out, seconds, error)
  values (q.id, q.model_code, (select m.model_identifier from pipeline.ai_model_catalogue m where m.code = q.model_code), q.prompt_version, q.run_kind, q.job_id, q.sample_id, q.candidate_id, q.scholarship_id, q.provider_id,
          coalesce(p_final_url, q.url), coalesce(p_storage_path, (select c.storage_path from pipeline.scholarship_page_candidates c where c.id = q.candidate_id)), p_sha256,
          coalesce(v_ev, (select c.evidence_id from pipeline.scholarship_page_candidates c where c.id = q.candidate_id), (select sp.evidence_id from pipeline.scholarship_pages sp where sp.scholarship_id = q.scholarship_id)),
          p_answer, p_checks, p_verdict, p_cost, p_tokens_in, p_tokens_out, p_seconds, p_error)
  returning id into v_id;
  -- v2.15.250 (bugs 11/10-6 follow-up): an unsettled answer (failed reply, name not proven, or a stated fact not proven by its quote)
  -- goes to the next model in the chain, on the same stored copy; after the last model it goes to Layer 4 while AI admission is on
  -- CF-247 4 Nov 2026: an approved single read whose page could not be read ends here (one read; no retry, no other model)
  if q.read_request_id is not null and p_error is not null and p_storage_path is null then
    update pipeline.scholarship_ai_queue set state = 'done', done_at = now(), leased_until = null, extraction_id = v_id where id = q.id;
    r := security.scholarship_read_request_close_v1(q.read_request_id, v_id, 'read_failed', 'Approved read: the page could not be read (' || left(p_error, 200) || ')');
    return jsonb_build_object('ok', true, 'extraction', v_id, 'request', r);
  end if;
  v_why := case when q.run_kind in ('admit', 'reread') then security.scholarship_ai_unsettled_v1(p_answer, p_checks, p_verdict, p_error) end;
  -- v2.15.250 (23:50): an answer that would admit is confirmed by the next model while confirm_admissions is on
  if v_why is null and q.run_kind in ('admit', 'reread') and p_error is null and p_verdict = 'scholarship' and p_answer->>'audience' in ('international', 'both')
     and coalesce((p_checks->>'audience')::boolean, false) and coalesce(p_answer->>'offered', '') <> 'no'
     and coalesce((select s.confirm_admissions from pipeline.scholarship_ai_extract_settings s where s.id = 1), true)
     and security.scholarship_ai_next_model_v1(q.model_code) is not null then
    v_why := 'a second model confirms each admission';
  end if;
  v_next := case when v_why is not null then security.scholarship_ai_next_model_v1(q.model_code) end;
  if v_next is not null then
    update pipeline.scholarship_ai_queue set state = 'done', done_at = now(), leased_until = null, extraction_id = v_id where id = q.id;
    insert into pipeline.scholarship_ai_queue(model_code, prompt_version, run_kind, job_id, sample_id, candidate_id, scholarship_id, provider_id, url, step, storage_path, root_id, fresh_read, read_request_id)
    values (v_next, q.prompt_version, q.run_kind, q.job_id, q.sample_id, q.candidate_id, q.scholarship_id, q.provider_id, coalesce(p_final_url, q.url), q.step + 1,
            coalesce(p_storage_path, q.storage_path), coalesce(q.root_id, q.id), q.fresh_read and coalesce(p_storage_path, q.storage_path) is null, q.read_request_id);
    return jsonb_build_object('ok', true, 'extraction', v_id, 'escalated_to', v_next, 'why', v_why);
  end if;
  update pipeline.scholarship_ai_queue set state = case when p_error is null or attempts >= 3 then 'done' else 'queued' end, done_at = case when p_error is null or attempts >= 3 then now() end,
         leased_until = null, next_try_at = now() + interval '10 minutes', extraction_id = v_id where id = q.id;
  -- CF-247 4 Nov 2026: an approved single read never admits or publishes; its answer goes to the held item in Layer 4, where the decision stays
  if q.read_request_id is not null then
    if p_error is null or q.attempts >= 3 then
      r := security.scholarship_read_request_close_v1(q.read_request_id, v_id, case when p_error is null then 'read' else 'read_failed' end,
             coalesce(v_why, 'Approved read: answer recorded; the decision stays in Layer 4'));
    end if;
    return jsonb_build_object('ok', true, 'extraction', v_id, 'request', r);
  end if;
  select ai_admission into v_on from pipeline.scholarship_ai_extract_settings where id = 1;
  -- F-SCH redesign (12 Nov 2026, directive §5 and §9): after the last model, a stated fact its quote does not prove is dropped (unknown) and the
  -- proven remainder goes through the governed admission path; a technical failure stays on the extraction for the coverage classifier and recoveries.
  -- Neither is a Layer 4 review. A detail read (run_kind detail) only fills empty canonical fields.
  if v_on and v_why is not null and p_error is null and q.run_kind = 'admit' then
    update pipeline.scholarship_ai_extractions set answer = security.scholarship_ai_strip_unproven_v1(answer, checks) where id = v_id;
    r := coalesce(security.scholarship_ai_apply_v1(v_id), '{}'::jsonb) || jsonb_build_object('unproven_dropped', v_why);
  elsif v_on and v_why is not null and p_error is null and q.run_kind = 'reread' then
    -- a re-read that does not prove a stated fact again never withdraws on that ground: the record keeps its admitted facts and their evidence
    r := jsonb_build_object('unproven_kept', v_why) || case when coalesce(q.prompt_version, 0) >= 3 then jsonb_build_object('detail', security.scholarship_detail_apply_v1(v_id)) else '{}'::jsonb end;
    update pipeline.scholarship_ai_extractions set applied = r || jsonb_build_object('at', now()) where id = v_id;
  elsif v_on and v_why is not null and p_error is not null and q.attempts >= 3 then r := jsonb_build_object('technical_failure', left(p_error, 200));
  elsif p_error is null and v_on and q.run_kind in ('admit', 'reread') then r := security.scholarship_ai_apply_v1(v_id);
  elsif p_error is null and q.run_kind = 'detail' then
    r := security.scholarship_detail_apply_v1(v_id);
    update pipeline.scholarship_ai_extractions set applied = coalesce(r, '{}'::jsonb) || jsonb_build_object('at', now()) where id = v_id;
  end if;
  return jsonb_build_object('ok', true, 'extraction', v_id, 'applied', r);
end $$;


ALTER FUNCTION "public"."svc_scholarship_ai_record"("p_queue_id" bigint, "p_answer" "jsonb", "p_checks" "jsonb", "p_verdict" "text", "p_cost" numeric, "p_tokens_in" integer, "p_tokens_out" integer, "p_seconds" numeric, "p_error" "text", "p_storage_path" "text", "p_sha256" "text", "p_final_url" "text", "p_rule_facts" "jsonb", "p_retry" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_apply_records"("p_source_id" "uuid", "p_evidence_id" "uuid", "p_records" "jsonb", "p_mode" "text" DEFAULT 'apply'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  r jsonb;
  cyc jsonb;
  win jsonb;
  sc jsonb;
  grp jsonb;
  crt jsonb;
  tier jsonb;
  cov jsonb;
  v_source_key text;
  v_identifier_scheme text;
  v_source_record_id text;
  v_stable_key text;
  v_entity_id uuid;
  v_scholarship_id uuid;
  v_provider_id uuid;
  v_cycle_id uuid;
  v_group_id uuid;
  v_parent_group_id uuid;
  v_target_id uuid;
  v_country_id uuid;
  v_seen int := 0;
  v_changed int := 0;
  v_unmapped int := 0;
  v_cycles int := 0;
  v_windows int := 0;
  v_scopes int := 0;
  v_groups int := 0;
  v_criteria int := 0;
  v_tiers int := 0;
  v_coverage int := 0;
begin
  if auth.role() <> 'service_role' then raise exception 'service_role required'; end if;
  if p_mode not in ('dry_run','apply') then raise exception 'mode must be dry_run or apply'; end if;
  if jsonb_typeof(p_records) <> 'array' then raise exception 'records must be JSON array'; end if;

  select metadata->>'scholarship_source_key' into v_source_key
  from pipeline.sources where id=p_source_id;
  if nullif(v_source_key,'') is null then raise exception 'scholarship source not prepared'; end if;

  for r in select value from jsonb_array_elements(p_records)
  loop
    v_seen := v_seen + 1;
    v_source_record_id := nullif(btrim(r->>'source_record_id'),'');
    v_identifier_scheme := coalesce(nullif(btrim(r->>'identifier_scheme'),''), v_source_key || '_id');
    if v_source_record_id is null then raise exception 'source_record_id required'; end if;
    if nullif(btrim(r->>'name'),'') is null then raise exception 'scholarship name required for %',v_source_record_id; end if;

    v_provider_id := null;
    if nullif(btrim(r->>'provider_cricos'),'') is not null then
      select public.svc_scholarship_resolve_au_provider(r->>'provider_cricos') into v_provider_id;
      if v_provider_id is null then v_unmapped := v_unmapped + 1; end if;
    end if;

    if p_mode='dry_run' then
      continue;
    end if;

    select scholarship_id into v_scholarship_id
    from scholarship.identifiers
    where source_id=p_source_id and scheme=v_identifier_scheme and identifier_value=v_source_record_id
    limit 1;

    if v_scholarship_id is null then
      v_stable_key := 'scholarship:AU:' || v_source_key || ':' || lower(v_source_record_id);
      v_entity_id := scholarship.deterministic_uuid(v_stable_key);

      insert into pim.entity_registry(id,entity_type,stable_key,lifecycle_status)
      values(v_entity_id,'scholarship',v_stable_key,'active')
      on conflict(stable_key) do update set updated_at=now()
      returning id into v_scholarship_id;
    else
      select stable_key into v_stable_key from scholarship.scholarships where id=v_scholarship_id;
      if v_stable_key is null then v_stable_key := 'scholarship:AU:' || v_source_key || ':' || lower(v_source_record_id); end if;
      update pim.entity_registry set lifecycle_status='active',updated_at=now() where id=v_scholarship_id;
    end if;

    insert into scholarship.scholarships(
      id,stable_key,provider_id,name,scholarship_type,description,audience,award_value_text,
      application_required,application_open_date,application_close_date,academic_year,source_url,
      lifecycle_status,publication_status,source_id,evidence_id,confidence,updated_at
    ) values (
      v_scholarship_id,v_stable_key,v_provider_id,r->>'name',r->>'scholarship_type',r->>'description',
      r->>'audience',r->>'award_value_text',coalesce((r->>'application_required')::boolean,true),
      nullif(r->>'application_open_date','')::date,nullif(r->>'application_close_date','')::date,
      nullif(r->>'academic_year','')::int,r->>'source_url','active','unpublished',p_source_id,p_evidence_id,
      coalesce(nullif(r->>'confidence','')::numeric,1.0),now()
    )
    on conflict(id) do update set
      provider_id=excluded.provider_id,
      name=excluded.name,
      scholarship_type=excluded.scholarship_type,
      description=excluded.description,
      audience=excluded.audience,
      award_value_text=excluded.award_value_text,
      application_required=excluded.application_required,
      application_open_date=excluded.application_open_date,
      application_close_date=excluded.application_close_date,
      academic_year=excluded.academic_year,
      source_url=excluded.source_url,
      lifecycle_status='active',
      source_id=excluded.source_id,
      evidence_id=excluded.evidence_id,
      confidence=excluded.confidence,
      updated_at=now();

    insert into scholarship.identifiers(id,scholarship_id,scheme,identifier_value,source_id,evidence_id,is_primary,status)
    values(
      scholarship.deterministic_uuid(v_stable_key || ':identifier:' || v_identifier_scheme || ':' || v_source_record_id),
      v_scholarship_id,v_identifier_scheme,v_source_record_id,p_source_id,p_evidence_id,true,'active'
    )
    on conflict(source_id,scheme,identifier_value) do update set
      scholarship_id=excluded.scholarship_id,evidence_id=excluded.evidence_id,is_primary=true,status='active';

    for cyc in select value from jsonb_array_elements(coalesce(r->'cycles','[]'::jsonb))
    loop
      if nullif(btrim(cyc->>'cycle_code'),'') is null then raise exception 'cycle_code required'; end if;
      v_cycle_id := scholarship.deterministic_uuid(v_stable_key || ':cycle:' || (cyc->>'cycle_code'));
      insert into scholarship.offering_cycles(
        id,scholarship_id,cycle_code,academic_year,intake_label,valid_from,valid_to,status,source_id,evidence_id,metadata
      ) values (
        v_cycle_id,v_scholarship_id,cyc->>'cycle_code',nullif(cyc->>'academic_year','')::int,cyc->>'intake_label',
        nullif(cyc->>'valid_from','')::date,nullif(cyc->>'valid_to','')::date,coalesce(cyc->>'status','active'),
        p_source_id,p_evidence_id,coalesce(cyc->'metadata','{}'::jsonb)
      )
      on conflict(scholarship_id,cycle_code) do update set
        academic_year=excluded.academic_year,intake_label=excluded.intake_label,valid_from=excluded.valid_from,
        valid_to=excluded.valid_to,status=excluded.status,source_id=excluded.source_id,evidence_id=excluded.evidence_id,
        metadata=excluded.metadata;
      v_cycles := v_cycles + 1;

      for win in select value from jsonb_array_elements(coalesce(cyc->'windows','[]'::jsonb))
      loop
        if nullif(btrim(win->>'window_key'),'') is null then raise exception 'window_key required'; end if;
        insert into scholarship.application_windows(
          id,scholarship_id,cycle_id,round_code,label,opens_at,closes_at,application_method,application_url,status,
          source_id,evidence_id,metadata
        ) values (
          scholarship.deterministic_uuid(v_stable_key || ':cycle:' || (cyc->>'cycle_code') || ':window:' || (win->>'window_key')),
          v_scholarship_id,v_cycle_id,win->>'round_code',win->>'label',nullif(win->>'opens_at','')::timestamptz,
          nullif(win->>'closes_at','')::timestamptz,win->>'application_method',win->>'application_url',
          coalesce(win->>'status','unknown'),p_source_id,p_evidence_id,coalesce(win->'metadata','{}'::jsonb)
        )
        on conflict(id) do update set
          round_code=excluded.round_code,label=excluded.label,opens_at=excluded.opens_at,closes_at=excluded.closes_at,
          application_method=excluded.application_method,application_url=excluded.application_url,status=excluded.status,
          source_id=excluded.source_id,evidence_id=excluded.evidence_id,metadata=excluded.metadata;
        v_windows := v_windows + 1;
      end loop;

      for sc in select value from jsonb_array_elements(coalesce(cyc->'scopes','[]'::jsonb))
      loop
        if nullif(btrim(sc->>'scope_key'),'') is null then raise exception 'scope_key required'; end if;
        v_target_id := null;
        if sc->>'scope_type'='provider' then
          if nullif(sc->>'target_code','') is not null then
            select public.svc_scholarship_resolve_au_provider(sc->>'target_code') into v_target_id;
          else v_target_id := v_provider_id;
          end if;
        elsif sc->>'scope_type'='study_level' then
          select id into v_target_id from ref.study_levels where code=sc->>'target_code' and status='active' limit 1;
        elsif sc->>'scope_type'='country' then
          select id into v_target_id from ref.countries where iso_alpha2=upper(sc->>'target_code') limit 1;
        elsif sc->>'scope_type' <> 'global' then
          raise exception 'unsupported v1 scope type %',sc->>'scope_type';
        end if;
        if sc->>'scope_type' <> 'global' and v_target_id is null then
          raise exception 'unresolved scope % target %',sc->>'scope_type',sc->>'target_code';
        end if;

        insert into scholarship.scopes(
          id,scholarship_id,scope_type,provider_id,study_level_id,country_id,include_exclude,source_id,evidence_id,cycle_id
        ) values (
          scholarship.deterministic_uuid(v_stable_key || ':cycle:' || (cyc->>'cycle_code') || ':scope:' || (sc->>'scope_key')),
          v_scholarship_id,sc->>'scope_type',case when sc->>'scope_type'='provider' then v_target_id end,
          case when sc->>'scope_type'='study_level' then v_target_id end,
          case when sc->>'scope_type'='country' then v_target_id end,
          coalesce(sc->>'include_exclude','include'),p_source_id,p_evidence_id,v_cycle_id
        ) on conflict(id) do update set
          provider_id=excluded.provider_id,study_level_id=excluded.study_level_id,country_id=excluded.country_id,
          include_exclude=excluded.include_exclude,source_id=excluded.source_id,evidence_id=excluded.evidence_id,cycle_id=excluded.cycle_id;
        v_scopes := v_scopes + 1;
      end loop;

      for grp in select value from jsonb_array_elements(coalesce(cyc->'criterion_groups','[]'::jsonb))
      loop
        if nullif(btrim(grp->>'group_code'),'') is null then raise exception 'group_code required'; end if;
        v_parent_group_id := null;
        if nullif(btrim(grp->>'parent_group_code'),'') is not null then
          v_parent_group_id := scholarship.deterministic_uuid(v_stable_key || ':cycle:' || (cyc->>'cycle_code') || ':group:' || (grp->>'parent_group_code'));
        end if;
        v_group_id := scholarship.deterministic_uuid(v_stable_key || ':cycle:' || (cyc->>'cycle_code') || ':group:' || (grp->>'group_code'));
        insert into scholarship.criterion_groups(
          id,scholarship_id,cycle_id,parent_group_id,group_code,label,conjunction,is_mandatory,display_order,source_id,evidence_id
        ) values (
          v_group_id,v_scholarship_id,v_cycle_id,v_parent_group_id,grp->>'group_code',grp->>'label',
          coalesce(grp->>'conjunction','all'),coalesce((grp->>'is_mandatory')::boolean,true),
          coalesce(nullif(grp->>'display_order','')::int,0),p_source_id,p_evidence_id
        )
        on conflict(scholarship_id,group_code) do update set
          cycle_id=excluded.cycle_id,parent_group_id=excluded.parent_group_id,label=excluded.label,
          conjunction=excluded.conjunction,is_mandatory=excluded.is_mandatory,display_order=excluded.display_order,
          source_id=excluded.source_id,evidence_id=excluded.evidence_id;
        v_groups := v_groups + 1;
      end loop;

      for crt in select value from jsonb_array_elements(coalesce(cyc->'criteria','[]'::jsonb))
      loop
        if nullif(btrim(crt->>'criterion_key'),'') is null then raise exception 'criterion_key required'; end if;
        v_group_id := null;
        if nullif(btrim(crt->>'group_code'),'') is not null then
          v_group_id := scholarship.deterministic_uuid(v_stable_key || ':cycle:' || (cyc->>'cycle_code') || ':group:' || (crt->>'group_code'));
        end if;
        insert into scholarship.criteria(
          id,scholarship_id,criterion_type,operator,value_text,value_number,value_codes,value_json,human_text,
          is_mandatory,machine_evaluable,status,source_id,evidence_id,confidence,cycle_id,criterion_group_id
        ) values (
          scholarship.deterministic_uuid(v_stable_key || ':cycle:' || (cyc->>'cycle_code') || ':criterion:' || (crt->>'criterion_key')),
          v_scholarship_id,crt->>'criterion_type',crt->>'operator',crt->>'value_text',nullif(crt->>'value_number','')::numeric,
          case when jsonb_typeof(crt->'value_codes')='array' then array(select jsonb_array_elements_text(crt->'value_codes')) else null end,
          crt->'value_json',crt->>'human_text',coalesce((crt->>'is_mandatory')::boolean,true),
          coalesce((crt->>'machine_evaluable')::boolean,false),coalesce(crt->>'status','active'),p_source_id,p_evidence_id,
          coalesce(nullif(crt->>'confidence','')::numeric,1.0),v_cycle_id,v_group_id
        ) on conflict(id) do update set
          criterion_type=excluded.criterion_type,operator=excluded.operator,value_text=excluded.value_text,
          value_number=excluded.value_number,value_codes=excluded.value_codes,value_json=excluded.value_json,
          human_text=excluded.human_text,is_mandatory=excluded.is_mandatory,machine_evaluable=excluded.machine_evaluable,
          status=excluded.status,source_id=excluded.source_id,evidence_id=excluded.evidence_id,confidence=excluded.confidence,
          cycle_id=excluded.cycle_id,criterion_group_id=excluded.criterion_group_id;
        v_criteria := v_criteria + 1;
      end loop;

      for tier in select value from jsonb_array_elements(coalesce(cyc->'award_tiers','[]'::jsonb))
      loop
        if nullif(btrim(tier->>'tier_code'),'') is null then raise exception 'tier_code required'; end if;
        insert into scholarship.award_tiers(
          id,scholarship_id,tier_code,label,amount,currency_code,percentage,basis,maximum_amount,notes,display_order,
          cycle_id,source_id,evidence_id
        ) values (
          scholarship.deterministic_uuid(v_stable_key || ':cycle:' || (cyc->>'cycle_code') || ':tier:' || (tier->>'tier_code')),
          v_scholarship_id,tier->>'tier_code',tier->>'label',nullif(tier->>'amount','')::numeric,tier->>'currency_code',
          nullif(tier->>'percentage','')::numeric,tier->>'basis',nullif(tier->>'maximum_amount','')::numeric,tier->>'notes',
          coalesce(nullif(tier->>'display_order','')::int,0),v_cycle_id,p_source_id,p_evidence_id
        ) on conflict(id) do update set
          label=excluded.label,amount=excluded.amount,currency_code=excluded.currency_code,percentage=excluded.percentage,
          basis=excluded.basis,maximum_amount=excluded.maximum_amount,notes=excluded.notes,display_order=excluded.display_order,
          cycle_id=excluded.cycle_id,source_id=excluded.source_id,evidence_id=excluded.evidence_id;
        v_tiers := v_tiers + 1;
      end loop;

      for cov in select value from jsonb_array_elements(coalesce(cyc->'coverage','[]'::jsonb))
      loop
        if nullif(btrim(cov->>'coverage_key'),'') is null then raise exception 'coverage_key required'; end if;
        insert into scholarship.coverage(
          id,scholarship_id,coverage_type,percentage,amount,currency_code,duration_value,duration_unit,notes,
          source_id,evidence_id,cycle_id
        ) values (
          scholarship.deterministic_uuid(v_stable_key || ':cycle:' || (cyc->>'cycle_code') || ':coverage:' || (cov->>'coverage_key')),
          v_scholarship_id,cov->>'coverage_type',nullif(cov->>'percentage','')::numeric,nullif(cov->>'amount','')::numeric,
          cov->>'currency_code',nullif(cov->>'duration_value','')::numeric,cov->>'duration_unit',cov->>'notes',
          p_source_id,p_evidence_id,v_cycle_id
        ) on conflict(id) do update set
          coverage_type=excluded.coverage_type,percentage=excluded.percentage,amount=excluded.amount,
          currency_code=excluded.currency_code,duration_value=excluded.duration_value,duration_unit=excluded.duration_unit,
          notes=excluded.notes,source_id=excluded.source_id,evidence_id=excluded.evidence_id,cycle_id=excluded.cycle_id;
        v_coverage := v_coverage + 1;
      end loop;
    end loop;

    v_changed := v_changed + 1;
  end loop;

  return jsonb_build_object(
    'mode',p_mode,'seen',v_seen,'changed',v_changed,'unmappedProviders',v_unmapped,
    'cycles',v_cycles,'windows',v_windows,'scopes',v_scopes,'criterionGroups',v_groups,
    'criteria',v_criteria,'awardTiers',v_tiers,'coverage',v_coverage
  );
end
$$;


ALTER FUNCTION "public"."svc_scholarship_apply_records"("p_source_id" "uuid", "p_evidence_id" "uuid", "p_records" "jsonb", "p_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_candidate_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare v jsonb; v_ok uuid[] := '{}'; v_p record;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  -- CF-247 scholarship recovery F1: the skip rules run when candidates are recorded and hourly (security.scholarship_candidate_skip_v1);
  -- the holds are checked once per provider in a window of due candidates, not per candidate row
  create temp table if not exists sch_cand_win(id bigint, provider_id uuid, url text, requested boolean, tier int, priority int, found_at timestamptz) on commit drop;
  truncate sch_cand_win;
  insert into sch_cand_win
  select c.id, c.provider_id, c.url, c.requested_at is not null, coalesce(d.tier, 9), d.priority, c.found_at
    from pipeline.scholarship_page_candidates c join pipeline.scholarship_discovery_providers d on d.provider_id=c.provider_id and d.priority in (0,1,3,4)
   where c.matched_scholarship_id is null and c.admit_status is null and c.next_read_at<=now() and coalesce(c.leased_until,'-infinity')<now() and c.attempts<3
   order by (c.requested_at is not null) desc, coalesce(d.tier, 9), (d.priority not in (0,3)), c.found_at, c.id
   limit greatest(1, security.pipeline_num_v1('scholarship.candidate_pick_window', 600)::int);
  for v_p in select distinct w.provider_id from sch_cand_win w loop
    -- v2.15.237 unpublished; v2.15.265 eligibility and cap; v2.15.271 search off
    if not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = v_p.provider_id) and not security.fc_sch_held_v1(v_p.provider_id, true)
       and not security.provider_sch_search_off_v1(v_p.provider_id) then v_ok := v_ok || v_p.provider_id; end if;
  end loop;
  with ranked as (
    select w.id, w.requested, w.tier, w.priority, row_number() over (partition by w.provider_id order by (w.url ~* 'international') desc, w.found_at, w.id) rn
      from sch_cand_win w where w.provider_id = any (v_ok) and not security.third_party_host_v1(w.url)),
  pick as (
    select c.id from pipeline.scholarship_page_candidates c join ranked r on r.id=c.id
     -- re-checked on the locked row, so concurrent readers never take the same page
     where coalesce(c.leased_until,'-infinity')<now() and c.admit_status is null and c.matched_scholarship_id is null and c.next_read_at<=now()
     order by r.requested desc, r.tier, r.rn, (r.priority not in (0,3)), c.id -- 11 Oct 2026: on-demand candidates first
     limit greatest(1,least(coalesce(p_limit,30), security.pipeline_num_v1('scholarship.candidates_max', 60)::int)) for update of c skip locked),
  upd as (update pipeline.scholarship_page_candidates c set leased_until=now()+interval '5 minutes', attempts=c.attempts+1 from pick where c.id=pick.id  -- fixed: claim lease
          returning c.id, c.url, c.provider_id)
  select coalesce(jsonb_agg(jsonb_build_object('candidate_id',u.id,'url',u.url,'provider_id',u.provider_id,'currency',scholarship.provider_currency(u.provider_id),
           'site',(select coalesce(site_origin,website) from pipeline.scholarship_discovery_providers d where d.provider_id=u.provider_id),
           'hosts',(select to_jsonb(allowed_hosts) from pipeline.scholarship_discovery_providers d where d.provider_id=u.provider_id))),'[]'::jsonb)
    into v from upd u;
  return v;
end $$;


ALTER FUNCTION "public"."svc_scholarship_candidate_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_candidate_record"("p_candidate_id" bigint, "p_read_status" "text", "p_http_status" integer, "p_fetched_via" "text", "p_final_url" "text", "p_storage_path" "text", "p_sha256" "text", "p_facts" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $_$
declare r jsonb; c pipeline.scholarship_page_candidates%rowtype; v_ev uuid; v_ai boolean := coalesce((select s.ai_admission from pipeline.scholarship_ai_extract_settings s where s.id=1),false) and exists (select 1 from pipeline.scholarship_ai_models m where m.status='active');
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  if p_read_status='deferred' then -- out of time in this run: back to the queue unchanged
    update pipeline.scholarship_page_candidates set leased_until=null, attempts=greatest(0,attempts-1) where id=p_candidate_id;
    return jsonb_build_object('admitted',false,'deferred',true);
  end if;
  update pipeline.scholarship_page_candidates set read_status=p_read_status, http_status=p_http_status, fetched_via=p_fetched_via, final_url=p_final_url,
         read_at=now(), leased_until=null, storage_path=coalesce(p_storage_path,storage_path), content_hash=coalesce(p_sha256,content_hash), facts=coalesce(p_facts,facts),
         next_read_at=case when p_read_status in ('read','robots_disallowed','gone','redirected_away','section_missing') then now()+make_interval(days => security.pipeline_num_v1('reread.scholarship_candidate_days', 90)::int) else now()+make_interval(hours => security.pipeline_num_v1('retry.scholarship_candidate_failed_hours', 6)::int) end,
         admit_status=case when p_read_status in ('redirected_away','section_missing') then 'rejected'  -- CF-247 scholarship recovery F7, F5
                           when not v_ai and p_read_status='read' and coalesce((p_facts->'admission'->>'admit')::boolean,false) is not true then 'rejected' else admit_status end,
         admit_reasons=case when p_read_status in ('redirected_away','section_missing') then array[p_read_status]
                            when not v_ai and p_read_status='read' and coalesce((p_facts->'admission'->>'admit')::boolean,false) is not true
                            then array(select jsonb_array_elements_text(coalesce(p_facts->'admission'->'reasons','[]'))) else admit_reasons end
   where id=p_candidate_id;
  if not v_ai and p_read_status='read' and coalesce((p_facts->'admission'->>'admit')::boolean,false) then r:=security.scholarship_admit_from_provider_page_v1(p_candidate_id); end if;
  -- v2.15.249 (bugs 11/10-6): with AI admission on, the AI decides every page read (its copy is kept), not the rules
  if v_ai and p_read_status in ('read','too_thin') and p_storage_path is not null then
    insert into pipeline.scholarship_ai_queue(model_code,prompt_version,run_kind,candidate_id,provider_id,url)
    select a.model_code,a.prompt_version,'admit',p_candidate_id,(select x.provider_id from pipeline.scholarship_page_candidates x where x.id=p_candidate_id),coalesce(p_final_url,(select x.url from pipeline.scholarship_page_candidates x where x.id=p_candidate_id))
      from security.scholarship_ai_active_v1() a where not exists (select 1 from pipeline.scholarship_ai_queue q where q.candidate_id=p_candidate_id and q.state in ('queued','leased'));
    r:=jsonb_build_object('admitted',false,'ai','queued');
  end if;
  select * into c from pipeline.scholarship_page_candidates where id=p_candidate_id;
  -- v2.15.248 (Platform Admin bugs 11/10-5, Fix 2): a stored page that did not become a scholarship is kept as evidence of the decision
  if c.storage_path is not null and c.evidence_id is null and coalesce(c.admit_status,'')<>'admitted' then
    insert into pipeline.evidence_artifacts(source_id,evidence_type,source_url,storage_path,content_hash,mime_type,metadata,capture_version,evidence_group_key)
    values (security.coverage_sweep_source(c.provider_id),'scholarship_candidate_page',coalesce(c.final_url,c.url),c.storage_path,c.content_hash,'application/gzip',
            jsonb_build_object('candidate_id',c.id,'provider_id',c.provider_id,'read_status',c.read_status,'decision',coalesce(c.admit_status,c.read_status),'reasons',to_jsonb(coalesce(c.admit_reasons,'{}'::text[])),'worker','coverage-sweep scholarship candidates'),1,'scholarship_candidate:'||c.id)
    returning id into v_ev;
    update pipeline.scholarship_page_candidates set evidence_id=v_ev where id=c.id;
  end if;
  -- (Fix 4) a page that lists scholarships is suggested as the provider's listing page, for a person to confirm
  if coalesce(c.admit_status,'')<>'admitted' and c.read_status in ('read','too_thin')
     and (coalesce(c.facts->>'h1','')||' '||coalesce(c.title,'')||' '||coalesce(c.facts->>'page_title','') ~* '(scholarships? (finder|search|list|directory)|grants and scholarships|find (a|your) scholarship|^\s*scholarships\s*$)'
          or coalesce(c.admit_reasons,'{}') && array['listing_page'] or c.url ~* '(scholarship-finder|/scholarships?/?$|/grants-scholarships/?$)') then
    insert into pipeline.scholarship_listing_pages(provider_id,url,url_norm,source,active,status)
    values (c.provider_id,coalesce(c.final_url,c.url),security.scholarship_url_norm(coalesce(c.final_url,c.url)),'suggested',false,'suggested')
    on conflict (provider_id,url_norm) do nothing;
  end if;
  return coalesce(r, jsonb_build_object('admitted',false));
end $_$;


ALTER FUNCTION "public"."svc_scholarship_candidate_record"("p_candidate_id" bigint, "p_read_status" "text", "p_http_status" integer, "p_fetched_via" "text", "p_final_url" "text", "p_storage_path" "text", "p_sha256" "text", "p_facts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_discover_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare v jsonb; v_win uuid[]; v_ok uuid[] := '{}'; v_held uuid[] := '{}'; r record;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  -- CF-247 scholarship recovery F1/F3: a small window at the head of the queue, ordered by the stored tier (no per-row course count);
  -- pending and deferred rows when due, mapped and empty rows when their re-discovery date has come
  select array_agg(x.provider_id order by x.t, x.priority, x.due, x.provider_id) into v_win from (
    select d.provider_id, coalesce(d.tier, 9) t, d.priority, coalesce(d.next_discover_at, '-infinity') due from pipeline.scholarship_discovery_providers d
     where d.status in ('pending', 'deferred', 'mapped', 'empty') and coalesce(d.leased_until,'-infinity')<now() and d.attempts<3
       and (case when d.status in ('pending', 'deferred') then coalesce(d.next_discover_at, '-infinity') else d.next_discover_at end) <= now()
     order by coalesce(d.tier, 9), d.priority, coalesce(d.next_discover_at, '-infinity'), d.provider_id
     limit greatest(1, security.pipeline_num_v1('scholarship.discover_pick_window', 60)::int)) x;
  -- the holds, only on the window (v2.15.237 unpublished, v2.15.265 eligibility and cap, directory site, v2.15.271 search off)
  for r in select d.provider_id, d.website from pipeline.scholarship_discovery_providers d where d.provider_id = any (coalesce(v_win, '{}')) loop
    if exists (select 1 from security.provider_hidden_v1 h where h.provider_id = r.provider_id) or security.fc_sch_held_v1(r.provider_id, true)
       or security.third_party_host_v1(coalesce(r.website, '')) or security.provider_sch_search_off_v1(r.provider_id) then v_held := v_held || r.provider_id;
    else v_ok := v_ok || r.provider_id; end if;
  end loop;
  if cardinality(v_held) > 0 then
    update pipeline.scholarship_discovery_providers set next_discover_at = now() + make_interval(hours => security.pipeline_num_v1('retry.scholarship_discovery_held_hours', 6)::int)
     where provider_id = any (v_held);
  end if;
  with pick as (
    select d.provider_id from pipeline.scholarship_discovery_providers d
     where d.provider_id = any (v_ok) and coalesce(d.leased_until,'-infinity')<now()
     order by coalesce(d.tier, 9), d.priority, coalesce(d.next_discover_at, '-infinity'), d.provider_id
     limit greatest(1,least(coalesce(p_limit,3), security.pipeline_num_v1('scholarship.discover_providers_max', 6)::int)) for update skip locked),
  upd as (update pipeline.scholarship_discovery_providers d set leased_until=now()+interval '5 minutes', attempts=d.attempts+1, updated_at=now()  -- fixed: claim lease
            from pick where d.provider_id=pick.provider_id returning d.provider_id, d.website, d.reason, d.allowed_hosts)
  select coalesce(jsonb_agg(jsonb_build_object('provider_id',u.provider_id,'website',u.website,'reason',u.reason,'hosts',to_jsonb(u.allowed_hosts),
           'names',security.provider_name_list(u.provider_id),'held',security.scholarship_held_without_page(u.provider_id),
           -- F4: every source recorded for the provider (manual first), after its website
           'sources',(select coalesce(jsonb_agg(z.url order by z.o, z.id), '[]'::jsonb) from (select l.url, l.id, case l.source when 'manual' then 0 else 1 end o
                        from pipeline.scholarship_listing_pages l where l.provider_id = u.provider_id and l.active and l.source in ('manual', 'auto')
                         and not security.third_party_host_v1(l.url) order by 3, l.id limit greatest(0, security.pipeline_num_v1('scholarship.sources_per_provider_max', 5)::int - 1)) z))),'[]'::jsonb) into v from upd u;
  return v;
end $$;


ALTER FUNCTION "public"."svc_scholarship_discover_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_discover_record"("p_provider_id" "uuid", "p_status" "text", "p_site_origin" "text", "p_method" "text", "p_url_count" integer, "p_candidates" "jsonb", "p_matches" "jsonb", "p_error" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare v_kept int; v_matched int:=0; m jsonb; r jsonb; v_cid bigint; v_new int; v_status text;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  insert into pipeline.scholarship_page_candidates(provider_id,url,url_norm,title,source)
  select p_provider_id, c->>'url', security.scholarship_url_norm(c->>'url'), nullif(left(c->>'title',300),''), coalesce(c->>'source','sitemap')
    from jsonb_array_elements(coalesce(p_candidates,'[]')) c
   where coalesce(c->>'url','') ~* '^https?://' and (security.url_on_provider_sites(c->>'url', p_provider_id) or security.url_on_provider_site(c->>'url', p_site_origin))
  on conflict (provider_id,url_norm) do update set title=coalesce(pipeline.scholarship_page_candidates.title, excluded.title);
  get diagnostics v_new = row_count;
  -- CF-247 scholarship recovery F1: the address skip rules on the candidates just recorded (was: on every pick)
  if v_new > 0 then perform security.scholarship_candidate_skip_v1(p_provider_id, v_new); end if;
  select count(*) into v_kept from pipeline.scholarship_page_candidates where provider_id=p_provider_id;
  -- F3: a refused or failed map is deferred and tried again (never a final "empty", and its last count is kept); a map that ran is due again
  -- after the re-discovery cadence
  v_status := case when p_status in ('mapped', 'empty', 'deferred', 'failed') then p_status else 'failed' end;
  update pipeline.scholarship_discovery_providers set status=v_status, site_origin=coalesce(p_site_origin,site_origin), method=p_method,
         url_count=case when v_status='deferred' then url_count else p_url_count end, kept_count=v_kept,
         discovered_at=case when v_status='deferred' then discovered_at else now() end, leased_until=null, last_error=p_error, updated_at=now(),
         attempts=case when v_status in ('mapped', 'empty', 'deferred') then 0 else attempts end,
         next_discover_at=case when v_status='deferred' then now()+make_interval(hours => security.pipeline_num_v1('retry.scholarship_discovery_deferred_hours', 6)::int)
                               when v_status in ('mapped', 'empty') then now()+make_interval(days => security.pipeline_num_v1('reread.scholarship_discovery_days', 30)::int)
                               else next_discover_at end,
         sources_mapped=coalesce(to_jsonb(string_to_array(p_method, '+')), '[]'::jsonb)
   where provider_id=p_provider_id;
  for m in select * from jsonb_array_elements(coalesce(p_matches,'[]')) loop
    select id into v_cid from pipeline.scholarship_page_candidates where provider_id=p_provider_id and url_norm=security.scholarship_url_norm(m->>'url');
    if v_cid is null then continue; end if;
    if (select provider_id from scholarship.scholarships where id=(m->>'scholarship_id')::uuid) is distinct from p_provider_id then continue; end if;
    r:=security.scholarship_page_match_v1((m->>'scholarship_id')::uuid, m->>'url', m->>'basis', v_cid);
    if (r->>'matched')::boolean then v_matched:=v_matched+1; end if;
  end loop;
  update pipeline.scholarship_discovery_providers set matched_count=coalesce(matched_count,0)+v_matched where provider_id=p_provider_id;
  return jsonb_build_object('kept',v_kept,'matched',v_matched,'status',v_status,'new',v_new);
end $$;


ALTER FUNCTION "public"."svc_scholarship_discover_record"("p_provider_id" "uuid", "p_status" "text", "p_site_origin" "text", "p_method" "text", "p_url_count" integer, "p_candidates" "jsonb", "p_matches" "jsonb", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_eligibility_next"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb; v_model text; v_why text; v_rt jsonb := security.ai_route_gate_v1('scholarship_eligibility');
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  if security.pipeline_num_v1('sch_elig.on', 0) < 1 then return jsonb_build_object('items', '[]'::jsonb, 'held', 'sch_elig.on is 0'); end if;
  v_why := security.ai_use_refusal_v1('scholarship_ai');
  if v_why is not null then return jsonb_build_object('items', '[]'::jsonb, 'held', v_why); end if;
  v_model := v_rt->>'model';  -- 13 Nov 2026: the route (pipeline.ai_service_routes)
  if v_model is null then return jsonb_build_object('items', '[]'::jsonb, 'held', coalesce(v_rt->>'held_reason', 'no allowed model in the cascade')); end if;
  if (v_rt->>'held')::boolean and not (coalesce((v_rt->>'on_demand_exempt')::boolean, false) and jsonb_array_length(v_rt->'on_demand_providers') > 0) then return jsonb_build_object('items', '[]'::jsonb, 'held', v_rt->>'held_reason'); end if;
  with pick as (
    select e.candidate_id from pipeline.scholarship_eligibility_reads e
     where ((e.state = 'queued' and coalesce(e.next_try_at, '-infinity') <= now()) or (e.state = 'leased' and e.leased_until < now()))
       and security.ai_route_open_v1(v_rt, e.provider_id)
     order by e.queued_at, e.candidate_id limit greatest(1, least(coalesce(p_limit, 10), 40))  -- fixed: the worker's upper bound per call
     for update skip locked),
  upd as (update pipeline.scholarship_eligibility_reads e set state = 'leased', leased_until = now() + interval '15 minutes', tries = e.tries + 1, updated_at = now()  -- fixed: lease timer
            from pick where e.candidate_id = pick.candidate_id returning e.candidate_id)
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', c.id, 'url', coalesce(c.final_url, c.url), 'storage_path', c.storage_path, 'provider_id', c.provider_id,
           'provider', (select coalesce(p.display_name, p.canonical_name) from catalogue.providers p where p.id = c.provider_id),
           'country', security.coverage_country(c.provider_id),
           'name', coalesce(nullif(btrim(c.facts->'admission'->>'name'), ''), nullif(btrim(c.facts->'ai'->>'name'), ''), c.title, ''),
           'model', v_model, 'models', v_rt->'models',
           'link_follow', security.pipeline_num_v1('sch_elig.link_follow_on', 1) >= 1,
           'links_max', security.pipeline_num_v1('sch_elig.links_max', 1)::int)), '[]'::jsonb)
    into v from upd u join pipeline.scholarship_page_candidates c on c.id = u.candidate_id;
  return jsonb_build_object('items', v);
end $$;


ALTER FUNCTION "public"."svc_scholarship_eligibility_next"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_eligibility_record"("p_id" bigint, "p_result" "jsonb", "p_cost" numeric, "p_error" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.scholarship_eligibility_reads%rowtype; v_state text; v_max int := security.pipeline_num_v1('sch_elig.max_tries', 2)::int;
        v_retry interval := make_interval(hours => security.pipeline_num_v1('retry.sch_eligibility_hours', 6)::int);
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into r from pipeline.scholarship_eligibility_reads where candidate_id = p_id for update;
  if r.candidate_id is null then return 'missing'; end if;
  if p_error is not null or coalesce(p_result->>'outcome', '') not in ('proven', 'silent', 'unread') or p_result->>'outcome' = 'unread' then
    v_state := case when r.tries < v_max then 'queued' else 'failed' end;
    update pipeline.scholarship_eligibility_reads set state = v_state, leased_until = null, cost_usd = cost_usd + coalesce(p_cost, 0),
           last_error = left(coalesce(p_error, 'outcome ' || coalesce(p_result->>'outcome', 'missing')), 300),
           outcome = case when v_state = 'failed' and p_result->>'outcome' = 'unread' then 'unread' end,
           result = case when v_state = 'failed' then p_result end,
           next_try_at = case when v_state = 'queued' then now() + v_retry end, read_at = case when v_state = 'failed' then now() end, updated_at = now()
     where candidate_id = p_id;
  else
    v_state := 'done';
    update pipeline.scholarship_eligibility_reads set state = 'done', leased_until = null, cost_usd = cost_usd + coalesce(p_cost, 0), last_error = null,
           outcome = p_result->>'outcome', result = p_result, applied = null, next_try_at = null, read_at = now(), updated_at = now()
     where candidate_id = p_id;
  end if;
  return v_state;
end $$;


ALTER FUNCTION "public"."svc_scholarship_eligibility_record"("p_id" bigint, "p_result" "jsonb", "p_cost" numeric, "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."svc_scholarship_fc_budget"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_used numeric := (select coalesce(sum(u.units), 0) from pipeline.coverage_vendor_usage u where u.purpose in ('sch_map', 'sch_search', 'sch_scrape'));
        v_life boolean := security.scholarship_flag_v1('scholarship.lifetime_cap_on', false);
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  return jsonb_build_object(
    'used', v_used,
    -- CF-247 scholarship recovery F8: the all-time cap is retired into the normal settings. Off (default): the worker's ceiling is the daily
    -- scholarship share above what is used, and svc_fc_spend (daily budget, share, per-university cap, monthly plan) decides each call.
    'cap', case when v_life then (select s.value from pipeline.scholarship_layer_settings s where s.key = 'firecrawl_cap')
                else v_used + security.fc_setting_num_v1('daily_share_scholarships', 3500) end,
    'lifetime_cap', v_life,
    'reserve', (select s.value from pipeline.scholarship_layer_settings s where s.key = 'firecrawl_reserve'),
    -- 11 Oct 2026: read scholarship pages through the scraper first (1 = on, 0 = off)
    'scraper', coalesce((select s.value from pipeline.scholarship_layer_settings s where s.key = 'read_via_scraper'), 1));
end $$;


ALTER FUNCTION "public"."svc_scholarship_fc_budget"() OWNER TO "postgres";


