    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
  select coalesce(sum(units),0) from pipeline.coverage_vendor_usage where purpose in ('sch_map','sch_search','sch_scrape')
$$;


