CREATE OR REPLACE FUNCTION "public"."svc_worker_report_v1"("p_mode" "text", "p_status" integer, "p_ms" integer, "p_body" "jsonb", "p_worker" "text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id bigint; v_items int; v_failed int; v_ok int; v_landed jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  v_items := coalesce(security.worker_call_work_v1(p_body::text), 0)::int;
  -- CF-247 lanes (3 Nov 2026): counts are read only when they are numbers (scholarship_read answers "applied": [], and the cast failed, so
  -- none of its calls was recorded)
  v_failed := coalesce(security.jsonb_int_v1(p_body->'failed'), security.jsonb_int_v1(p_body->'tally'->'failed'), 0)
            + coalesce(security.jsonb_int_v1(p_body->'tally'->'fetch_failed'), 0) + coalesce(security.jsonb_int_v1(p_body->'tally'->'scrape_failed'), 0)
            + case when p_status >= 400 or coalesce(p_body->>'ok', 'true') = 'false' then 1 else 0 end;
  v_ok := greatest(0, coalesce(security.jsonb_int_v1(p_body->'done'), security.jsonb_int_v1(p_body->'applied'), v_items - v_failed));
  v_landed := coalesce(p_body->'landed', p_body->'tally', '{}'::jsonb);
  insert into pipeline.mode_outcome_ledger(mode, status, ms, items, ok, failed, landed, worker, detail)
  values (left(coalesce(p_mode, ''), 60), coalesce(p_status, 200), p_ms, v_items, v_ok, v_failed, v_landed, left(p_worker, 80),
          case when length((p_body - 'ok' - 'mode' - 'workerVersion' - 'tally' - 'landed')::text) <= 4000 then p_body - 'ok' - 'mode' - 'workerVersion' - 'tally' - 'landed'
               else jsonb_build_object('truncated', true, 'keys', (select jsonb_agg(k) from jsonb_object_keys(p_body) k)) end)  -- fixed: a row keeps at most 4 KB of detail
  returning id into v_id;
  -- CF-247 scholarship recovery F2: what the call achieved (an HTTP 500 or no work with an error is never "succeeded")
  update pipeline.mode_outcome_ledger set outcome = security.worker_call_outcome_v1(coalesce(p_status, 200), p_body, v_items, v_ok, v_failed) where id = v_id;
  -- CF-247 P0 mandate 3 Nov 2026 §6: the lane outcome and the hold reason (budget held, source limit, idle, failed, done)
  update pipeline.mode_outcome_ledger l set lane_outcome = x.o[1], hold_reason = x.o[2]
    from (select security.worker_lane_outcome_v1(left(coalesce(p_mode, ''), 60), y.outcome, p_body) o from pipeline.mode_outcome_ledger y where y.id = v_id) x
   where l.id = v_id;
  return v_id;
end $$;


ALTER FUNCTION "public"."svc_worker_report_v1"("p_mode" "text", "p_status" integer, "p_ms" integer, "p_body" "jsonb", "p_worker" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."svc_worker_report_v1"("p_mode" "text", "p_status" integer, "p_ms" integer, "p_body" "jsonb", "p_worker" "text") IS 'R1 Q3: the worker reports every call''s outcome to pipeline.mode_outcome_ledger (service role only)';



CREATE OR REPLACE FUNCTION "public"."svc_worker_settings_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  return (select coalesce(jsonb_object_agg(s.key, s.value), '{}'::jsonb) from pipeline.platform_toolset_settings s
           where (s.toolset_key = 'firecrawl' and s.key in ('read_proxy', 'map_limit_course_site', 'map_limit_central', 'map_limit_central_search', 'map_limit_scholarships',
                                                          'search_results_website', 'search_results_register', 'search_results_cricos',
                                                          'search_results_scholarship_search', 'search_results_scholarship_discover',
                                                          -- CF-247 Firecrawl format profiles (worker v0.99.0)
                                                          'scrape_profiles', 'scrape_profile_lanes', 'scrape_profile_overrides', 'scrape_profiles_version', 'screenshot_max_mb'))
              or (s.toolset_key = 'pipeline' and (s.key like 'enrich.%' or s.key like 'reading.%'))  -- v2.15.275: Enrich fields worker values
              or (s.toolset_key = 'pipeline' and s.key like 'scholarship.%')  -- CF-247 scholarship recovery F10: scholarship worker sizes and waits
              or (s.toolset_key = 'pipeline' and s.key like 'admission.%'));  -- CF-247 pre-AI admission gate (Decision 278): its switch, floors and enforcement switches
end $$;


ALTER FUNCTION "public"."svc_worker_settings_v1"() OWNER TO "postgres";


