CREATE OR REPLACE FUNCTION "public"."ui_scholarship_detail"("p_scholarship_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'scholarship', 'catalogue', 'pipeline', 'auth'
    AS $$
select case when s.id is null then null else jsonb_build_object(
'id',s.id,'stable_key',s.stable_key,'name',s.name,'provider_id',s.provider_id,'provider_name',coalesce(p.display_name,p.canonical_name),'type',s.scholarship_type,'audience',s.audience,'nationalities',s.nationalities,'award_value_is_maximum',s.award_value_is_maximum,'description',s.description,'award_value_text',s.award_value_text,'award_duration_basis',s.award_duration_basis,'lifecycle_status',s.lifecycle_status,'publication_status',s.publication_status,'confidence',s.confidence,'source_url',s.source_url,'source_id',s.source_id,'evidence_id',s.evidence_id,
'identifiers',coalesce((select jsonb_agg(to_jsonb(i) order by i.is_primary desc,i.scheme) from scholarship.identifiers i where i.scholarship_id=s.id),'[]'::jsonb),
'cycles',coalesce((select jsonb_agg(to_jsonb(cy) order by cy.academic_year desc nulls last,cy.cycle_code) from scholarship.offering_cycles cy where cy.scholarship_id=s.id),'[]'::jsonb),
'windows',coalesce((select jsonb_agg(to_jsonb(w) order by w.opens_at nulls last,w.label) from scholarship.application_windows w where w.scholarship_id=s.id),'[]'::jsonb),
'scopes',coalesce((select jsonb_agg(to_jsonb(sc) order by sc.scope_type) from scholarship.scopes sc where sc.scholarship_id=s.id),'[]'::jsonb),
'criterion_groups',coalesce((select jsonb_agg(to_jsonb(g) order by g.display_order,g.group_code) from scholarship.criterion_groups g where g.scholarship_id=s.id),'[]'::jsonb),
'criteria',coalesce((select jsonb_agg(to_jsonb(cr) order by cr.criterion_type) from scholarship.criteria cr where cr.scholarship_id=s.id),'[]'::jsonb),
'award_tiers',coalesce((select jsonb_agg(to_jsonb(a) order by a.display_order,a.label) from scholarship.award_tiers a where a.scholarship_id=s.id),'[]'::jsonb),
'coverage',coalesce((select jsonb_agg(to_jsonb(cv) order by cv.coverage_type) from scholarship.coverage cv where cv.scholarship_id=s.id),'[]'::jsonb),
'evidence',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'type',e.evidence_type,'source_url',e.source_url,'hash',e.content_hash,'captured_at',e.captured_at) order by e.captured_at desc) from pipeline.evidence_artifacts e where e.id=s.evidence_id or e.entity_id=s.id),'[]'::jsonb)
) end from scholarship.scholarships s left join catalogue.providers p on p.id=s.provider_id where s.id=p_scholarship_id and auth.uid() is not null and security.current_role_rank() >= 1;
$$;


ALTER FUNCTION "public"."ui_scholarship_detail"("p_scholarship_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_scholarships_list"("p_limit" integer DEFAULT 500) RETURNS TABLE("id" "uuid", "stable_key" "text", "name" "text", "provider_id" "uuid", "provider_name" "text", "scholarship_type" "text", "audience" "text", "award_value_text" "text", "academic_year" integer, "publication_status" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'scholarship', 'catalogue', 'auth'
    AS $$
select s.id,s.stable_key,s.name,s.provider_id,coalesce(p.display_name,p.canonical_name),s.scholarship_type,s.audience,s.award_value_text,s.academic_year,s.publication_status
from scholarship.scholarships s left join catalogue.providers p on p.id=s.provider_id
where auth.uid() is not null order by coalesce(p.display_name,p.canonical_name),s.name limit least(greatest(coalesce(p_limit,500),1),1000)
$$;


ALTER FUNCTION "public"."ui_scholarships_list"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_scholarships_page"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_query" "text" DEFAULT NULL::"text", "p_country_code" "text" DEFAULT NULL::"text", "p_lifecycle_status" "text" DEFAULT NULL::"text", "p_publication_status" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT 'scholarship'::"text", "p_direction" "text" DEFAULT 'asc'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'scholarship', 'catalogue', 'ref', 'pipeline', 'auth'
    AS $$
declare v_limit int:=least(greatest(coalesce(p_limit,50),1),200);v_offset int:=greatest(coalesce(p_offset,0),0);v_sort text:=lower(coalesce(p_sort,'scholarship'));v_dir text:=case when lower(coalesce(p_direction,'asc'))='desc' then 'desc' else 'asc' end;
begin
 if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
 if security.current_role_rank()<1 then raise exception 'assigned StudySearch role required' using errcode='42501'; end if;
 return (with base as (
  select s.id,s.stable_key,s.name,s.scholarship_type,s.description,s.audience,s.award_value_text,s.award_value_type,s.award_percentage,s.award_amount,s.award_currency_code,s.academic_year,s.application_required,s.application_open_date,s.application_close_date,s.lifecycle_status,s.publication_status,s.source_url,s.created_at,s.updated_at,s.provider_id,coalesce(p.display_name,p.canonical_name) provider_name,co.iso_alpha2::text country_code,co.name country_name,co.default_currency_code::text currency_code,
   (select count(*)::int from scholarship.offering_cycles oc where oc.scholarship_id=s.id) cycle_count,
   (select count(*)::int from scholarship.application_windows aw where aw.scholarship_id=s.id) window_count,
   (select count(*)::int from pipeline.evidence_artifacts e where e.entity_id=s.id)+case when s.evidence_id is not null then 1 else 0 end evidence_count,
   (select count(*)::int from scholarship.course_mappings m where m.scholarship_id=s.id and m.mapping_state='mapped') mapped_course_count,
   (select count(*)::int from scholarship.course_mapping_candidates mc where mc.scholarship_id=s.id and mc.status='needs_review') review_course_count,
   left(regexp_replace(coalesce(s.description,''),'\s+',' ','g'),220) description_excerpt
  from scholarship.scholarships s left join catalogue.providers p on p.id=s.provider_id left join ref.countries co on co.id=p.country_id
  where (nullif(trim(coalesce(p_query,'')),'') is null or s.name ilike '%'||trim(p_query)||'%' or coalesce(p.display_name,p.canonical_name,'') ilike '%'||trim(p_query)||'%' or coalesce(s.stable_key,'') ilike '%'||trim(p_query)||'%' or coalesce(s.description,'') ilike '%'||trim(p_query)||'%' or coalesce(s.award_value_text,'') ilike '%'||trim(p_query)||'%' or coalesce(s.scholarship_type,'') ilike '%'||trim(p_query)||'%' or coalesce(s.academic_year::text,'') ilike '%'||trim(p_query)||'%')
   and (nullif(trim(coalesce(p_country_code,'')),'') is null or co.iso_alpha2::text=upper(trim(p_country_code)))
   and (nullif(trim(coalesce(p_lifecycle_status,'')),'') is null or s.lifecycle_status=trim(p_lifecycle_status))
   and (nullif(trim(coalesce(p_publication_status,'')),'') is null or s.publication_status=trim(p_publication_status))
 ), numbered as(select *,count(*) over() total_count from base), ordered as(select * from numbered order by
   case when v_sort='scholarship' and v_dir='asc' then lower(name) end asc,case when v_sort='scholarship' and v_dir='desc' then lower(name) end desc,
   case when v_sort='provider' and v_dir='asc' then lower(coalesce(provider_name,'')) end asc,case when v_sort='provider' and v_dir='desc' then lower(coalesce(provider_name,'')) end desc,
   case when v_sort='award' and v_dir='asc' then coalesce(award_percentage,award_amount) end asc nulls last,case when v_sort='award' and v_dir='desc' then coalesce(award_percentage,award_amount) end desc nulls last,
   case when v_sort='year' and v_dir='asc' then academic_year end asc nulls last,case when v_sort='year' and v_dir='desc' then academic_year end desc nulls last,
   case when v_sort='close' and v_dir='asc' then application_close_date end asc nulls last,case when v_sort='close' and v_dir='desc' then application_close_date end desc nulls last,
   case when v_sort='courses' and v_dir='asc' then mapped_course_count end asc,case when v_sort='courses' and v_dir='desc' then mapped_course_count end desc,
   case when v_sort='evidence' and v_dir='asc' then evidence_count end asc,case when v_sort='evidence' and v_dir='desc' then evidence_count end desc,
   case when v_sort='updated' and v_dir='asc' then updated_at end asc,case when v_sort='updated' and v_dir='desc' then updated_at end desc,
   lower(name),id limit v_limit offset v_offset)
 select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),'total',coalesce(max(total_count),0),'limit',v_limit,'offset',v_offset,'sort',v_sort,'direction',v_dir) from ordered o);
end $$;


ALTER FUNCTION "public"."ui_scholarships_page"("p_limit" integer, "p_offset" integer, "p_query" "text", "p_country_code" "text", "p_lifecycle_status" "text", "p_publication_status" "text", "p_sort" "text", "p_direction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ui_search_courses"("p_query" "text", "p_limit" integer DEFAULT 50) RETURNS TABLE("course_id" "uuid", "provider_name" "text", "course_title" "text", "level_code" "text", "rank" real, "has_scholarship" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'search', 'ref', 'auth'
    AS $$
select d.course_id,d.provider_name,d.course_title,sl.code,
       ts_rank_cd(d.search_tsv,websearch_to_tsquery('english',coalesce(p_query,'')))::real,d.has_scholarship
from search.course_documents d left join ref.study_levels sl on sl.id=d.study_level_id
where auth.uid() is not null and (coalesce(trim(p_query),'')='' or d.search_tsv @@ websearch_to_tsquery('english',p_query))
order by ts_rank_cd(d.search_tsv,websearch_to_tsquery('english',coalesce(p_query,''))) desc,d.course_title
limit least(greatest(coalesce(p_limit,50),1),100)
$$;


ALTER FUNCTION "public"."ui_search_courses"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."website_api_v2_auth"("p_token_sha256" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare k private.api_keys%rowtype; v_prev boolean := false;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into k from private.api_keys where platform = 'website' and api_version = 'v2' and enabled and token_sha256 = lower(coalesce(p_token_sha256, ''));
  if k.key_name is null then
    select * into k from private.api_keys where platform = 'website' and api_version = 'v2' and enabled and previous_valid_until > now()
       and previous_token_sha256 = lower(coalesce(p_token_sha256, ''));
    v_prev := k.key_name is not null;
  end if;
  if k.key_name is null then return null; end if;
  return jsonb_build_object('key_name', k.key_name, 'previous', v_prev, 'rate_per_minute', coalesce(k.rate_per_minute, security.pipeline_num_v1('website.rate_per_minute', 300)::int),
                            'logo_link_days', security.pipeline_num_v1('website.logo_link_days', 365));
end $$;


ALTER FUNCTION "public"."website_api_v2_auth"("p_token_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."website_api_v2_log"("p_key_name" "text", "p_action" "text", "p_status" integer, "p_elapsed_ms" integer, "p_items" integer, "p_bytes" integer, "p_error_code" "text", "p_request_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  insert into pipeline.api_requests(platform, api_version, key_name, action, status, elapsed_ms, items, bytes, error_code, request_id)
  values ('website', 'v2', p_key_name, left(p_action, 40), p_status, p_elapsed_ms, p_items, p_bytes, left(p_error_code, 40), p_request_id);
end $$;


ALTER FUNCTION "public"."website_api_v2_log"("p_key_name" "text", "p_action" "text", "p_status" integer, "p_elapsed_ms" integer, "p_items" integer, "p_bytes" integer, "p_error_code" "text", "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."website_api_v2_rate"("p_key_name" "text", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  return api.zoho_integration_rate_check_v1('website-v2:' || p_key_name, 'all', p_limit, 60);  -- fixed: the limit is per minute
end $$;


ALTER FUNCTION "public"."website_api_v2_rate"("p_key_name" "text", "p_limit" integer) OWNER TO "postgres";


