    v := jsonb_set(v, '{items}', (select coalesce(jsonb_agg(public.website_v3_provider_item(x) order by o), '[]'::jsonb)
                                    from jsonb_array_elements(v->'items') with ordinality t(x, o)));
  end if;
  return v;
end $$;


