$$;


ALTER FUNCTION "public"."website_v3_scholarship"("p_scholarship_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."website_v3_scholarship"("p_scholarship_id" "text") IS 'Website API v3 (Decision 277): the scholarship with no paging asked (first 200 linked courses, as v2), R24 and linked_courses_total.';



CREATE OR REPLACE FUNCTION "public"."website_v3_scholarship"("p_scholarship_id" "text", "p_courses" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v jsonb := public.website_v2_scholarship(p_scholarship_id); v_id uuid; v_total int; v_page int; v_size int; v_paged boolean;
        c jsonb := coalesce(p_courses, '{}'::jsonb);
begin
  v_paged := nullif(c->>'page', '') is not null or nullif(c->>'page_size', '') is not null;
  if v_paged then
    if coalesce(c->>'page', '1') !~ '^[0-9]+$' or coalesce(c->>'page_size', '200') !~ '^[0-9]+$' then
      raise exception 'INVALID_INPUT: courses_page and courses_page_size must be whole numbers' using errcode = '22023';
    end if;
    v_page := coalesce((c->>'page')::int, 1);
    v_size := coalesce((c->>'page_size')::int, 200);  -- fixed: API contract, no paging asked = the v2 first 200 (build brief WP-1.3)
    if v_page < 1 or v_size < 1 or v_size > 200 then  -- fixed: API contract range 1–200 (build brief WP-1.3)
      raise exception 'INVALID_INPUT: courses_page must be 1 or more and courses_page_size 1-200' using errcode = '22023';
    end if;
  else
    v_page := 1; v_size := 200;  -- fixed: API contract, the v2 first page
  end if;
  if jsonb_typeof(v->'item') is distinct from 'object' then return v; end if;  -- NOT_FOUND and errors pass through as v2
  select s.id into v_id from scholarship.scholarships s where s.stable_key = btrim(p_scholarship_id);
  select count(*) into v_total from scholarship.course_mappings m join search.course_documents d on d.course_id = m.course_id
   where m.scholarship_id = v_id and m.mapping_state = 'mapped';
  v := jsonb_set(v, '{item}', public.website_v3_scholarship_item(v->'item'));
  if v_paged then
    v := jsonb_set(v, '{item}', (v->'item') || jsonb_build_object(
      'linked_courses', coalesce((select jsonb_agg(x.j order by x.t, x.k) from (
          select d.course_title t, d.course_stable_key k, jsonb_build_object('course_id', d.course_stable_key, 'course_code', d.course_code, 'title', d.course_title,
                   'saving_per_year', fc.scholarship_saving_amount, 'saving_currency', fc.currency_code, 'saving_basis', fc.fee_basis) j
            from scholarship.course_mappings m
            join search.course_documents d on d.course_id = m.course_id
            left join lateral (select f.scholarship_saving_amount, f.currency_code, f.fee_basis from scholarship.course_financial_calculations f
                                where f.scholarship_id = v_id and f.course_id = d.course_id and f.calculation_status = 'calculated'
                                order by f.fee_year desc nulls last limit 1) fc on true
           where m.scholarship_id = v_id and m.mapping_state = 'mapped'
           order by d.course_title, d.course_stable_key
           offset (v_page - 1) * v_size limit v_size) x), '[]'::jsonb),
      'linked_courses_truncated', v_page * v_size < v_total));
  end if;
  return jsonb_set(v, '{item}', (v->'item') || jsonb_build_object('linked_courses_total', v_total, 'linked_courses_page', v_page, 'linked_courses_page_size', v_size));
end $_$;


ALTER FUNCTION "public"."website_v3_scholarship"("p_scholarship_id" "text", "p_courses" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."website_v3_scholarship"("p_scholarship_id" "text", "p_courses" "jsonb") IS 'Website API v3 (Decision 277): website_v2_scholarship with nationality_eligibility_status (R24) and linked-course paging (R29: courses_page, courses_page_size; linked_courses_total).';



CREATE OR REPLACE FUNCTION "public"."website_v3_scholarship_item"("p_item" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id uuid; v_status text; v_more jsonb;
begin
  if p_item is null or jsonb_typeof(p_item) <> 'object' or not (p_item ? 'scholarship_id') then return p_item; end if;
  select s.id into v_id from scholarship.scholarships s where s.stable_key = p_item->>'scholarship_id';
  if v_id is null then return p_item; end if;
  v_status := case
    when exists (select 1 from pipeline.layer4_review_items r where r.entity_type = 'scholarship' and r.entity_id = v_id and r.status = 'pending'
                   and r.field_code in ('nationalities', 'nationality', 'citizenship_eligibility', 'audience', 'student_type'))
      or exists (select 1 from pipeline.scholarship_ai_reviews a where a.scholarship_id = v_id and a.status = 'pending' and a.reason ~* 'who it is for')
      then 'under_review'
    when (jsonb_typeof(p_item->'citizenship_eligibility') = 'array' and jsonb_array_length(p_item->'citizenship_eligibility') > 0)
      or p_item->>'student_type' = 'domestic'
      or exists (select 1 from scholarship.criteria c where c.scholarship_id = v_id and coalesce(c.status, 'active') not in ('rejected', 'superseded', 'withdrawn')
                   and c.criterion_type in ('nationality', 'citizenship_and_residency') and cardinality(c.value_codes) > 0)
      then 'restricted'
    when exists (select 1 from scholarship.nationality_readings nr where nr.scholarship_id = v_id and cardinality(nr.codes) = 0 and nr.phrases ? 'ANY')
      then 'unrestricted'
    else 'unknown' end;
  -- F-SCH developer field contract: one read of each source per scholarship; null means not held
  with cr as (
    select c.value_json from scholarship.criteria c
     where c.scholarship_id = v_id and coalesce(c.status, 'active') not in ('rejected', 'superseded', 'withdrawn') and c.criterion_type = 'nationality'),
  ad as (select d.award_type, d.sponsor, d.programme, d.award_code, d.application_rolling from scholarship.award_details d where d.scholarship_id = v_id)
  select jsonb_build_object(
    'description', (select s.description from scholarship.scholarships s where s.id = v_id),
    'award_type', (select ad.award_type from ad),
    'sponsor', (select ad.sponsor from ad),
    'programme', (select ad.programme from ad),
    'award_code', (select ad.award_code from ad),
    'benefits', coalesce((select jsonb_agg(jsonb_build_object('type', cv.coverage_type, 'amount', cv.amount, 'currency', cv.currency_code, 'percentage', cv.percentage,
                                 'is_maximum', cv.notes like 'sch-extract-v3:% (maximum)%') order by cv.coverage_type, cv.id)
                          from scholarship.coverage cv where cv.scholarship_id = v_id and cv.notes like 'sch-extract-v3:%'), '[]'::jsonb),
    'application', jsonb_build_object(
        'method', (select w.application_method from scholarship.application_windows w where w.scholarship_id = v_id and w.application_method is not null order by w.created_at desc limit 1),
        'url', (select w.application_url from scholarship.application_windows w where w.scholarship_id = v_id and w.application_url is not null order by w.created_at desc limit 1),
        'rolling', (select ad.application_rolling from ad)),
    'award_duration', (select jsonb_build_object('value', cv.duration_value, 'unit', cv.duration_unit) from scholarship.coverage cv
                        where cv.scholarship_id = v_id and cv.coverage_type = 'award_duration' and cv.duration_unit is not null order by cv.id desc limit 1),
    'academic_year', (select s.academic_year from scholarship.scholarships s where s.id = v_id),
    'excluded_nationality_codes', coalesce((select jsonb_agg(distinct x) from cr, jsonb_array_elements_text(coalesce(cr.value_json->'excluded', '[]'::jsonb)) x), '[]'::jsonb),
    'nationality_regions', coalesce((select jsonb_agg(distinct x) from cr, jsonb_array_elements_text(coalesce(cr.value_json->'regions', '[]'::jsonb)) x), '[]'::jsonb))
    into v_more;
  -- the v2 keys win: a key v2 already returns (description on `scholarship`) is never replaced
  return v_more || p_item || jsonb_build_object('nationality_eligibility_status', v_status);
end $$;


ALTER FUNCTION "public"."website_v3_scholarship_item"("p_item" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."website_v3_scholarship_item"("p_item" "jsonb") IS 'Website API v3: a v2 scholarship item with nationality_eligibility_status (R24) and the F-SCH detail fields (description, award_type, sponsor, programme, award_code, benefits, application, award_duration, academic_year, excluded_nationality_codes, nationality_regions); v2 keys unchanged.';



CREATE OR REPLACE FUNCTION "public"."website_v3_scholarships"("p_filters" "jsonb", "p_page" integer, "p_page_size" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb := public.website_v2_scholarships(p_filters, p_page, p_page_size);
begin
  if jsonb_typeof(v->'items') = 'array' then
    v := jsonb_set(v, '{items}', (select coalesce(jsonb_agg(public.website_v3_scholarship_item(x) order by o), '[]'::jsonb)
                                    from jsonb_array_elements(v->'items') with ordinality t(x, o)));
  end if;
  return v;
end $$;


ALTER FUNCTION "public"."website_v3_scholarships"("p_filters" "jsonb", "p_page" integer, "p_page_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."website_v3_scholarships"("p_filters" "jsonb", "p_page" integer, "p_page_size" integer) IS 'Website API v3 (Decision 277): website_v2_scholarships with nationality_eligibility_status (R24).';



CREATE OR REPLACE FUNCTION "public"."website_v3_sync"("p_cursor" "text", "p_full" boolean, "p_entities" "text"[], "p_page_size" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb := public.website_v2_sync(p_cursor, p_full, p_entities, p_page_size);
begin
  if jsonb_typeof(v->'items') = 'array' then
    v := jsonb_set(v, '{items}', (select coalesce(jsonb_agg(case when not (x ? 'item') or jsonb_typeof(x->'item') <> 'object' then x
                                                                  when x->>'entity' = 'course' then jsonb_set(x, '{item}', public.website_v3_course_item_r28(x->'item'))
                                                                  when x->>'entity' = 'provider' then jsonb_set(x, '{item}', public.website_v3_provider_item(x->'item'))
                                                                  when x->>'entity' = 'scholarship' then jsonb_set(x, '{item}', public.website_v3_scholarship_item(x->'item'))
                                                                  else x end order by o), '[]'::jsonb)
                                    from jsonb_array_elements(v->'items') with ordinality t(x, o)));
  end if;
  return v;
end $$;


ALTER FUNCTION "public"."website_v3_sync"("p_cursor" "text", "p_full" boolean, "p_entities" "text"[], "p_page_size" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."website_v3_sync"("p_cursor" "text", "p_full" boolean, "p_entities" "text"[], "p_page_size" integer) IS 'Website API v3 (Decision 277): website_v2_sync with R28 on course items, R23 on provider items and R24 on scholarship items.';



