COMMENT ON FUNCTION "publishing"."refresh_course_publication_search_v1"() IS 'CF-CHG-20260823-024: explicit Search refresh after bounded publication state changes.';



CREATE OR REPLACE FUNCTION "publishing"."set_course_publication_v1"("p_course_id" "uuid", "p_target_status" "text", "p_profile_code" "text" DEFAULT 'pilot-course-positive-v1'::"text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'publishing', 'catalogue', 'ref', 'pg_temp'
    AS $$
declare v_target text:=lower(trim(coalesce(p_target_status,''))); v_prior text; v_country text; v_locale text; v_ready jsonb; v_canonical_changed integer:=0; v_website_changed integer:=0; v_zoho_changed integer:=0; v_website_status text; v_zoho_status text; v_changed boolean;
begin
if v_target not in ('published','internal','unpublished','blocked') then raise exception 'unsupported publication status: %',p_target_status using errcode='22023'; end if;
select c.publication_status,trim(co.iso_alpha2::text) into v_prior,v_country from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id where c.id=p_course_id for update of c;
if not found then raise exception 'course not found: %',p_course_id using errcode='P0002'; end if;
v_ready:=publishing.course_publication_readiness_v1(p_course_id,p_profile_code);
if v_target in ('published','internal') and not coalesce((v_ready->>'eligible')::boolean,false) then raise exception 'publication profile blocked: %',v_ready::text using errcode='42501'; end if;
v_locale:=case v_country when 'AU' then 'en-AU' when 'NZ' then 'en-NZ' else 'en' end;
v_website_status:=case v_target when 'published' then 'published' when 'blocked' then 'blocked' else 'unpublished' end;
v_zoho_status:=case v_target when 'published' then 'published' when 'internal' then 'internal' when 'blocked' then 'blocked' else 'unpublished' end;
update catalogue.courses set publication_status=v_target,updated_at=now() where id=p_course_id and publication_status is distinct from v_target; get diagnostics v_canonical_changed=row_count;
insert into publishing.entity_states(entity_id,channel_code,locale,publication_status,published_at,unpublished_at,last_checked_at,updated_at) values(p_course_id,'website',v_locale,v_website_status,case when v_website_status='published' then now() end,case when v_website_status in ('unpublished','blocked') then now() end,now(),now())
on conflict(entity_id,channel_code,locale) do update set publication_status=excluded.publication_status,published_at=case when excluded.publication_status='published' then excluded.published_at else publishing.entity_states.published_at end,unpublished_at=case when excluded.publication_status in ('unpublished','blocked') then excluded.unpublished_at else publishing.entity_states.unpublished_at end,last_checked_at=now(),updated_at=now() where publishing.entity_states.publication_status is distinct from excluded.publication_status; get diagnostics v_website_changed=row_count;
insert into publishing.entity_states(entity_id,channel_code,locale,publication_status,published_at,unpublished_at,last_checked_at,updated_at) values(p_course_id,'zoho',v_locale,v_zoho_status,case when v_zoho_status='published' then now() end,case when v_zoho_status in ('unpublished','blocked') then now() end,now(),now())
on conflict(entity_id,channel_code,locale) do update set publication_status=excluded.publication_status,published_at=case when excluded.publication_status='published' then excluded.published_at else publishing.entity_states.published_at end,unpublished_at=case when excluded.publication_status in ('unpublished','blocked') then excluded.unpublished_at else publishing.entity_states.unpublished_at end,last_checked_at=now(),updated_at=now() where publishing.entity_states.publication_status is distinct from excluded.publication_status; get diagnostics v_zoho_changed=row_count;
v_changed:=(v_canonical_changed+v_website_changed+v_zoho_changed)>0;
if v_changed then insert into publishing.publication_events(entity_id,profile_code,prior_status,target_status,changed,reason,readiness,change_control_ref) values(p_course_id,p_profile_code,v_prior,v_target,true,p_reason,v_ready,'CF-CHG-20260823-024'); end if;
return jsonb_build_object('course_id',p_course_id,'profile_code',p_profile_code,'prior_status',v_prior,'target_status',v_target,'changed',v_changed,'canonical_changed',v_canonical_changed=1,'website_channel',v_website_status,'website_changed',v_website_changed=1,'zoho_channel',v_zoho_status,'zoho_changed',v_zoho_changed=1,'search_refresh_required',v_canonical_changed=1,'readiness',v_ready);
end $$;


ALTER FUNCTION "publishing"."set_course_publication_v1"("p_course_id" "uuid", "p_target_status" "text", "p_profile_code" "text", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "publishing"."set_course_publication_v1"("p_course_id" "uuid", "p_target_status" "text", "p_profile_code" "text", "p_reason" "text") IS 'CF-CHG-20260823-024: service-only bounded Course publication mutation; requires profile readiness for internal/published.';



CREATE OR REPLACE FUNCTION "ref"."resolve_subdivision_exact"("p_country_id" "uuid", "p_source_state" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'ref'
    AS $$
  select s.id
  from ref.subdivisions s
  where s.country_id = p_country_id
    and nullif(btrim(p_source_state),'') is not null
    and (
      upper(s.code) = upper(btrim(p_source_state))
      or lower(s.name) = lower(btrim(p_source_state))
      or upper(regexp_replace(s.code, '^.*-', '')) = upper(btrim(p_source_state))
    )
  order by case
    when upper(s.code) = upper(btrim(p_source_state)) then 0
    when lower(s.name) = lower(btrim(p_source_state)) then 1
    else 2
  end, s.id
  limit 1
$$;


ALTER FUNCTION "ref"."resolve_subdivision_exact"("p_country_id" "uuid", "p_source_state" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "scholarship"."decode_entities"("p" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v text := p; m text[];
begin
  if v is null then return null; end if;
  for m in select regexp_matches(v, '&#[xX]([0-9a-fA-F]{1,6});', 'g') loop
    v := replace(v, '&#x' || m[1] || ';', chr(('x' || lpad(m[1], 8, '0'))::bit(32)::int));
    v := replace(v, '&#X' || m[1] || ';', chr(('x' || lpad(m[1], 8, '0'))::bit(32)::int));
  end loop;
  for m in select regexp_matches(v, '&#([0-9]{1,7});', 'g') loop
    v := replace(v, '&#' || m[1] || ';', chr(m[1]::int));
  end loop;
  return replace(replace(v, '&apos;', ''''), '&amp;', '&');
end $$;


ALTER FUNCTION "scholarship"."decode_entities"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "scholarship"."deterministic_uuid"("p_key" "text") RETURNS "uuid"
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
  select (
    substr(md5(p_key),1,8) || '-' ||
    substr(md5(p_key),9,4) || '-' ||
    '5' || substr(md5(p_key),14,3) || '-' ||
    'a' || substr(md5(p_key),18,3) || '-' ||
    substr(md5(p_key),21,12)
  )::uuid
$$;


ALTER FUNCTION "scholarship"."deterministic_uuid"("p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "scholarship"."money_prefix"("p_currency" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select case upper(coalesce(p_currency, 'AUD')) when 'AUD' then 'A$' when 'NZD' then 'NZ$' when 'CAD' then 'C$' when 'USD' then 'US$' when 'GBP' then '£' else upper(p_currency) || ' ' end
$_$;


ALTER FUNCTION "scholarship"."money_prefix"("p_currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "scholarship"."normalise_first_party_url"("p_url" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $_$
  select nullif(lower(regexp_replace(split_part(replace(coalesce(p_url,''),'&amp;','&'),'#',1),'/+$','')),'');
$_$;


ALTER FUNCTION "scholarship"."normalise_first_party_url"("p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "scholarship"."normalise_title"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select nullif(lower(regexp_replace(trim(coalesce(p_text,'')),'[^a-z0-9]+','','g')),'');
$$;


ALTER FUNCTION "scholarship"."normalise_title"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "scholarship"."provider_currency"("p_provider_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce((select k.default_currency_code from catalogue.providers p join ref.countries k on k.id = p.country_id where p.id = p_provider_id), 'AUD')
$$;


ALTER FUNCTION "scholarship"."provider_currency"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "scholarship"."course_financial_calculations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "mapping_id" "uuid" NOT NULL,
    "scholarship_id" "uuid" NOT NULL,
    "course_id" "uuid" NOT NULL,
    "course_fee_id" "uuid",
    "calculation_status" "text" NOT NULL,
    "award_value_type" "text",
    "award_percentage" numeric(7,4),
    "award_amount" numeric(14,2),
    "currency_code" character(3),
    "fee_amount" numeric(14,2),
    "fee_type" "text",
    "fee_basis" "text",
    "fee_year" integer,
    "scholarship_saving_amount" numeric(14,2),
    "net_fee_amount" numeric(14,2),
    "calculation_formula" "text",
    "calculation_reason" "text",
    "scholarship_evidence_id" "uuid",
    "fee_evidence_id" "uuid",
    "calculated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "course_financial_calculations_status_check" CHECK (("calculation_status" = ANY (ARRAY['calculated'::"text", 'award_not_structured'::"text", 'award_scope_unresolved'::"text", 'fee_not_found'::"text", 'fee_ambiguous'::"text", 'currency_mismatch'::"text", 'not_applicable'::"text"])))
);


ALTER TABLE "scholarship"."course_financial_calculations" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "scholarship"."refresh_course_financial_calculation"("p_mapping_id" "uuid") RETURNS "scholarship"."course_financial_calculations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'catalogue', 'pipeline'
    AS $$
declare
  v_map scholarship.course_mappings%rowtype;
  v_s scholarship.scholarships%rowtype;
  v_fee catalogue.course_fees%rowtype;
  v_status text;
  v_reason text;
  v_saving numeric(14,2);
  v_net numeric(14,2);
  v_formula text;
  v_result scholarship.course_financial_calculations%rowtype;
  v_years numeric;
  v_est numeric(14,2);
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;
  select * into v_map from scholarship.course_mappings where id=p_mapping_id;
  if not found then raise exception 'mapping not found' using errcode='22023'; end if;
  select * into v_s from scholarship.scholarships where id=v_map.scholarship_id;

  if v_s.award_value_type is distinct from 'percentage' or v_s.award_percentage is null then
    v_status:='award_not_structured'; v_reason:='Percentage calculation requires a structured award_percentage.';
  elsif v_s.award_value_is_maximum then
    v_status:='award_not_structured'; v_reason:='The award is a maximum ("up to"); no saving is worked out.';
  elsif v_s.award_applies_to_fee_type is distinct from 'tuition_fee' then
    v_status:='award_scope_unresolved'; v_reason:='The provider page does not say the percentage is off tuition fees.';
  else
    -- Decision 212: the provider's annual international tuition fee for the course; the scholarship's year when it
    -- states one, otherwise the latest year recorded
    select f.* into v_fee from catalogue.course_fees f
     where f.course_id=v_map.course_id and f.audience='international' and f.fee_type='provider_current_tuition'
       and f.basis in ('annual','indicative_annual','current indicative annual international tuition')
       and f.amount > 0 and coalesce(f.status,'active') not in ('inactive','retired','superseded')
       and (v_s.academic_year is null or f.fee_year is null or f.fee_year=v_s.academic_year)
     order by (f.fee_year is not distinct from v_s.academic_year) desc, f.fee_year desc nulls last, f.updated_at desc nulls last
     limit 1;
    if v_fee.id is null then
      -- Decision 247: no annual fee from the provider; estimate one from the registered CRICOS course cost
      select f.* into v_fee from catalogue.course_fees f join pipeline.sources src on src.id = f.source_id
       where f.course_id = v_map.course_id and f.audience in ('international', 'all') and f.fee_type = 'tuition' and f.basis = 'registered_total_course'
         and src.label = 'CRICOS Providers, Courses and Locations' and f.amount > 0 and coalesce(f.status, 'active') = 'active'
       order by f.updated_at desc nulls last, f.id limit 1;
      select case c.duration_unit when 'weeks' then c.duration_value / 52.0 when 'months' then c.duration_value / 12.0 when 'years' then c.duration_value end
        into v_years from catalogue.courses c where c.id = v_map.course_id;
      if v_fee.id is null or coalesce(v_years, 0) <= 0 then
        v_fee := null; v_status:='fee_not_found'; v_reason:='No annual international tuition fee is recorded for this course, and no registered course cost and duration to estimate one.';
      elsif v_s.award_currency_code is not null and v_s.award_currency_code <> v_fee.currency_code then
        v_status:='currency_mismatch'; v_reason:='Scholarship and Course fee currencies differ.';
      else
        v_est := round(v_fee.amount / greatest(v_years, 1), 2);
        v_saving := round(v_est * (v_s.award_percentage / 100.0), 2);
        v_net := round(v_est - v_saving, 2);
        v_formula := 'estimated annual tuition = registered total course tuition / registered duration in years (at least 1); saving = estimate * (award_percentage / 100), per year';
        v_status := 'calculated';
        v_reason := 'Estimated from the registered CRICOS course cost (Decision 247); replaced by the provider''s annual fee when one is recorded.';
      end if;
    elsif exists (select 1 from catalogue.course_fees f where f.course_id=v_map.course_id and f.id<>v_fee.id and f.audience='international'
                    and f.fee_type='provider_current_tuition' and f.basis in ('annual','indicative_annual','current indicative annual international tuition')
                    and f.amount > 0 and coalesce(f.status,'active') not in ('inactive','retired','superseded')
                    and f.fee_year is not distinct from v_fee.fee_year and f.amount<>v_fee.amount) then
      v_fee:=null; v_status:='fee_ambiguous'; v_reason:='More than one annual tuition fee is recorded for the same year; a person must settle which applies.';
    elsif v_s.award_currency_code is not null and v_s.award_currency_code<>v_fee.currency_code then
      v_status:='currency_mismatch'; v_reason:='Scholarship and Course fee currencies differ.';
    else
      v_saving:=round(v_fee.amount*(v_s.award_percentage/100.0),2);
      v_net:=round(v_fee.amount-v_saving,2);
      v_formula:='annual tuition fee * (award_percentage / 100), per year';
      v_status:='calculated';
      v_reason:='Per-year saving from the provider''s annual international tuition fee'||coalesce(' for '||v_fee.fee_year,'')||'.';
    end if;
  end if;

  insert into scholarship.course_financial_calculations(
    mapping_id,scholarship_id,course_id,course_fee_id,calculation_status,
    award_value_type,award_percentage,award_amount,currency_code,fee_amount,fee_type,fee_basis,fee_year,
    scholarship_saving_amount,net_fee_amount,calculation_formula,calculation_reason,
    scholarship_evidence_id,fee_evidence_id,calculated_at,metadata)
  values(
    v_map.id,v_s.id,v_map.course_id,v_fee.id,v_status,
    v_s.award_value_type,v_s.award_percentage,v_s.award_amount,coalesce(v_s.award_currency_code,v_fee.currency_code),coalesce(v_est,v_fee.amount),v_fee.fee_type,
    case when v_est is not null then 'estimated_annual_from_registered_total' when v_fee.id is not null then 'annual' end,v_fee.fee_year,
    v_saving,v_net,v_formula,v_reason,coalesce(v_map.evidence_id,v_s.evidence_id),v_fee.evidence_id,now(),
    jsonb_build_object('award_duration_basis',v_s.award_duration_basis,'academic_year',v_s.academic_year,'fee_basis_recorded',v_fee.basis,'decision','Decision 212'))
  on conflict(mapping_id) do update set
    scholarship_id=excluded.scholarship_id,course_id=excluded.course_id,course_fee_id=excluded.course_fee_id,
    calculation_status=excluded.calculation_status,award_value_type=excluded.award_value_type,
    award_percentage=excluded.award_percentage,award_amount=excluded.award_amount,currency_code=excluded.currency_code,
    fee_amount=excluded.fee_amount,fee_type=excluded.fee_type,fee_basis=excluded.fee_basis,fee_year=excluded.fee_year,
    scholarship_saving_amount=excluded.scholarship_saving_amount,net_fee_amount=excluded.net_fee_amount,
    calculation_formula=excluded.calculation_formula,calculation_reason=excluded.calculation_reason,
    scholarship_evidence_id=excluded.scholarship_evidence_id,fee_evidence_id=excluded.fee_evidence_id,
    calculated_at=excluded.calculated_at,metadata=excluded.metadata
  returning * into v_result;
  return v_result;
end $$;


ALTER FUNCTION "scholarship"."refresh_course_financial_calculation"("p_mapping_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "scholarship"."refresh_course_financial_calculations"("p_course_id" "uuid" DEFAULT NULL::"uuid", "p_scholarship_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'catalogue'
    AS $$
declare
  r record;
  v_total integer:=0;
  v_calculated integer:=0;
  v_unresolved integer:=0;
  v_status text;
begin
  if current_user not in ('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;
  for r in
    select m.id
    from scholarship.course_mappings m
    join scholarship.scholarships s on s.id=m.scholarship_id
    where m.mapping_state='mapped'
      and (p_course_id is null or m.course_id=p_course_id)
      and (p_scholarship_id is null or m.scholarship_id=p_scholarship_id)
      and (s.award_value_type='percentage' or exists(select 1 from scholarship.course_financial_calculations fc where fc.mapping_id=m.id))
  loop
    select (scholarship.refresh_course_financial_calculation(r.id)).calculation_status into v_status;
    v_total:=v_total+1;
    if v_status='calculated' then v_calculated:=v_calculated+1; else v_unresolved:=v_unresolved+1; end if;
  end loop;
  return jsonb_build_object('ok',true,'refreshed',v_total,'calculated',v_calculated,'unresolved',v_unresolved);
end $$;


ALTER FUNCTION "scholarship"."refresh_course_financial_calculations"("p_course_id" "uuid", "p_scholarship_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "scholarship"."value_label"("p_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship'
    AS $$
  select case
    when s.award_value_type = 'percentage' and s.award_percentage is not null then
      case when s.award_value_is_maximum then 'Up to ' else '' end
      || trim(to_char(s.award_percentage, 'FM990.##'), '.') || '%'
      || case when s.award_applies_to_fee_type = 'tuition_fee' then ' of tuition fees' else ' off fees' end
      || case s.award_duration_basis when 'program_duration' then ' for the course' when 'annual_program_duration' then ' for the course' when 'per_semester' then ' a semester' when 'one_off' then ', one-off' else '' end
    when s.award_value_type = 'fixed_amount' and s.award_amount is not null then
      case when s.award_value_is_maximum then 'Up to ' else '' end
      || scholarship.money_prefix(coalesce(s.award_currency_code, 'AUD'))
      || to_char(s.award_amount, 'FM999,999,999')
      || case s.award_duration_basis when 'annual' then ' a year' when 'annual_program_duration' then ' a year for the course' when 'one_off' then ' one-off' when 'per_semester' then ' a semester' when 'program_duration' then ' for the course' else '' end
    when exists (select 1 from scholarship.award_tiers t where t.scholarship_id = s.id and t.tier_code like 'page_tier_%') then s.award_value_text
    else null end
  from scholarship.scholarships s where s.id = p_id
$$;


ALTER FUNCTION "scholarship"."value_label"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "search"."course_candidates_v1"("p_query" "text" DEFAULT NULL::"text", "p_query_embedding" "extensions"."vector" DEFAULT NULL::"extensions"."vector", "p_embedding_model" "text" DEFAULT NULL::"text", "p_profile_code" "text" DEFAULT 'website-default'::"text", "p_mode" "text" DEFAULT 'keyword'::"text", "p_country_codes" "text"[] DEFAULT NULL::"text"[], "p_subdivision_codes" "text"[] DEFAULT NULL::"text"[], "p_level_codes" "text"[] DEFAULT NULL::"text"[], "p_field_codes" "text"[] DEFAULT NULL::"text"[], "p_delivery_modes" "text"[] DEFAULT NULL::"text"[], "p_has_fee" boolean DEFAULT NULL::boolean, "p_has_scholarship" boolean DEFAULT NULL::boolean, "p_publication_statuses" "text"[] DEFAULT ARRAY['published'::"text", 'internal'::"text"], "p_limit" integer DEFAULT 20) RETURNS TABLE("course_id" "uuid", "fts_rank" real, "vector_similarity" real, "fused_score" double precision, "mode_used" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'search', 'extensions'
    AS $$
declare
  v_profile_id uuid;
  v_rrf_k integer := 60;
  v_fts_weight double precision := 1.0;
  v_vector_weight double precision := 0.55;
  v_limit integer := greatest(1,least(coalesce(p_limit,20),100));
  v_candidate_limit integer;
  v_has_vectors boolean := false;
begin
  select id,
         coalesce((config->>'rrf_k')::integer,60),
         coalesce((config->>'fts_weight')::double precision,1.0),
         coalesce((config->>'vector_weight')::double precision,0.55)
  into v_profile_id,v_rrf_k,v_fts_weight,v_vector_weight
  from search.profiles
  where code=p_profile_code and status='active'
  limit 1;

  if v_profile_id is null then
    return;
  end if;

  v_candidate_limit := greatest(200,least(v_limit*20,2000));

  if p_mode in ('hybrid','vector') and p_query_embedding is not null and p_embedding_model is not null then
    select exists(
      select 1 from search.course_embeddings e
      where e.profile_id=v_profile_id and e.model_name=p_embedding_model
      limit 1
    ) into v_has_vectors;
  end if;

  if p_mode='keyword' or (p_mode='hybrid' and not v_has_vectors) then
    return query
    with q as (
      select websearch_to_tsquery('english',coalesce(nullif(trim(p_query),''),'')) as tsq
    ), base as (
      select d.course_id,
        case when coalesce(trim(p_query),'')='' then 0::real else ts_rank_cd(d.search_tsv,(select tsq from q))::real end as score
      from search.course_documents d
      where (p_country_codes is null or d.country_code=any(p_country_codes))
        and (p_subdivision_codes is null or d.subdivision_codes && p_subdivision_codes)
        and (p_level_codes is null or d.study_level_code=any(p_level_codes))
        and (p_field_codes is null or d.primary_field_code=any(p_field_codes))
        and (p_delivery_modes is null or d.delivery_modes && p_delivery_modes)
        and (p_has_fee is null or d.has_fee=p_has_fee)
        and (p_has_scholarship is null or d.has_scholarship=p_has_scholarship)
        and (p_publication_statuses is null or d.publication_status=any(p_publication_statuses))
        and (coalesce(trim(p_query),'')='' or d.search_tsv @@ (select tsq from q))
      order by score desc,d.course_title,d.course_id
      limit v_limit
    ), ranked as (
      select b.*,row_number() over(order by b.score desc,b.course_id) as pos from base b
    )
    select r.course_id,r.score,null::real,
      (v_fts_weight/(v_rrf_k+r.pos))::double precision,
      case when p_mode='hybrid' then 'fts_fallback' else 'keyword' end::text
    from ranked r
    order by r.pos;
    return;
  end if;

  if p_mode='vector' and not v_has_vectors then
    return;
  end if;

  return query
  with q as (
    select websearch_to_tsquery('english',coalesce(nullif(trim(p_query),''),'')) as tsq
  ), fts_base as (
    select d.course_id,
      case when coalesce(trim(p_query),'')='' then 0::real else ts_rank_cd(d.search_tsv,(select tsq from q))::real end as score
    from search.course_documents d
    where p_mode='hybrid'
      and (p_country_codes is null or d.country_code=any(p_country_codes))
      and (p_subdivision_codes is null or d.subdivision_codes && p_subdivision_codes)
      and (p_level_codes is null or d.study_level_code=any(p_level_codes))
      and (p_field_codes is null or d.primary_field_code=any(p_field_codes))
      and (p_delivery_modes is null or d.delivery_modes && p_delivery_modes)
      and (p_has_fee is null or d.has_fee=p_has_fee)
      and (p_has_scholarship is null or d.has_scholarship=p_has_scholarship)
      and (p_publication_statuses is null or d.publication_status=any(p_publication_statuses))
      and (coalesce(trim(p_query),'')='' or d.search_tsv @@ (select tsq from q))
    order by score desc,d.course_title,d.course_id
    limit v_candidate_limit
  ), fts as (
    select course_id,score,row_number() over(order by score desc,course_id) as pos from fts_base
  ), vec_base as (
    select d.course_id,(1-(e.embedding <=> p_query_embedding))::real as similarity
    from search.course_embeddings e
    join search.course_documents d on d.course_id=e.course_id
    where e.profile_id=v_profile_id
      and e.model_name=p_embedding_model
      and e.content_hash=d.semantic_content_hash
      and (p_country_codes is null or d.country_code=any(p_country_codes))
      and (p_subdivision_codes is null or d.subdivision_codes && p_subdivision_codes)
      and (p_level_codes is null or d.study_level_code=any(p_level_codes))
      and (p_field_codes is null or d.primary_field_code=any(p_field_codes))
      and (p_delivery_modes is null or d.delivery_modes && p_delivery_modes)
      and (p_has_fee is null or d.has_fee=p_has_fee)
      and (p_has_scholarship is null or d.has_scholarship=p_has_scholarship)
      and (p_publication_statuses is null or d.publication_status=any(p_publication_statuses))
    order by e.embedding <=> p_query_embedding
    limit v_candidate_limit
  ), vec as (
    select course_id,similarity,row_number() over(order by similarity desc,course_id) as pos from vec_base
  ), merged as (
    select coalesce(f.course_id,v.course_id) as course_id,
           f.score as fts_rank,v.similarity as vector_similarity,
           f.pos as fts_pos,v.pos as vec_pos
    from fts f full outer join vec v using(course_id)
  )
  select m.course_id,m.fts_rank,m.vector_similarity,
    (case when m.fts_pos is null then 0 else v_fts_weight/(v_rrf_k+m.fts_pos) end
     + case when m.vec_pos is null then 0 else v_vector_weight/(v_rrf_k+m.vec_pos) end)::double precision,
    case when p_mode='vector' then 'vector' else 'hybrid' end::text
  from merged m
  order by 4 desc,m.fts_rank desc nulls last,m.vector_similarity desc nulls last,m.course_id
  limit v_limit;
end
$$;


ALTER FUNCTION "search"."course_candidates_v1"("p_query" "text", "p_query_embedding" "extensions"."vector", "p_embedding_model" "text", "p_profile_code" "text", "p_mode" "text", "p_country_codes" "text"[], "p_subdivision_codes" "text"[], "p_level_codes" "text"[], "p_field_codes" "text"[], "p_delivery_modes" "text"[], "p_has_fee" boolean, "p_has_scholarship" boolean, "p_publication_statuses" "text"[], "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "search"."course_refresh_request_v1"("p_course_ids" "uuid"[], "p_requested_by" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n integer;
begin
  if p_course_ids is null or cardinality(p_course_ids) = 0 then return 0; end if;
  insert into search.course_refresh_requests(course_id, requested_by)
  select distinct c.id, coalesce(p_requested_by, 'unknown') from unnest(p_course_ids) c(id) where c.id is not null;
  get diagnostics v_n = row_count;
  return v_n;
end
$$;


ALTER FUNCTION "search"."course_refresh_request_v1"("p_course_ids" "uuid"[], "p_requested_by" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "search"."course_refresh_request_v1"("p_course_ids" "uuid"[], "p_requested_by" "text") IS 'Queues courses for the scoped search refresh (search.course_refresh_requests); refreshed by security.search_course_refresh_drain_v1. Insert only, never waits on a lock.';



CREATE OR REPLACE FUNCTION "search"."rebuild_course_documents"() RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'search'
    AS $$
declare v_result jsonb;
begin
  v_result := search.refresh_course_documents_v3(true);
  return (v_result->'base'->>'stage_count')::bigint;
end $$;


ALTER FUNCTION "search"."rebuild_course_documents"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "search"."refresh_course_base_v3"("p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'search', 'catalogue', 'publishing', 'ref', 'pipeline', 'extensions', 'pg_temp'
    AS $$
declare
  v_generation bigint;
  v_current_generation bigint;
  v_stage_count bigint;
  v_new bigint;
  v_changed bigint;
  v_unchanged bigint;
  v_removed bigint;
  v_applied bigint := 0;
  v_stage_hash text;
  v_country_counts jsonb;
  v_coverage jsonb;
begin
  drop table if exists pg_temp.cf_search_course_base_v3_stage;

  create temp table cf_search_course_base_v3_stage on commit drop as
  with gates as (
    select g.country_id
    from search.projection_country_gates g
    where g.projection_code='courses' and g.gate_status='approved'
  )
  select
    c.id as course_id,
    c.provider_id,
    p.country_id,
    c.study_level_id,
    c.primary_field_id,
    c.stable_key as course_stable_key,
    p.stable_key as provider_stable_key,
    c.course_code,
    trim(co.iso_alpha2::text) as country_code,
    sl.code as study_level_code,
    fos.code as primary_field_code,
    fos.name as primary_field_name,
    coalesce(p.display_name,p.canonical_name) as provider_name,
    c.canonical_title as course_title,
    coalesce(coll.collection_names,'{}'::text[]) as collection_names,
    coalesce(acad.academic_option_names,'{}'::text[]) as academic_option_names,
    c.description,
    case when cardinality(coalesce(geo.subdivision_codes,'{}'::text[])) > 0 then geo.subdivision_codes
         when co.iso_alpha2 = any (security.region_fallback_countries_v1()) and psd.code is not null then array[psd.code]  -- CF-247 15 Oct: no campus, the provider's province (listed countries)
         else '{}'::text[] end as subdivision_codes,
    case when cardinality(coalesce(geo.delivery_modes,'{}'::text[])) > 0 then geo.delivery_modes
         when nullif(btrim(c.delivery_mode),'') is not null then array[c.delivery_mode] else '{}'::text[] end as delivery_modes,  -- v2.15.276 O1: the course's own mode when no campus mode is held
    (cardinality(coalesce(geo.subdivision_codes,'{}'::text[])) > 0 or (co.iso_alpha2 = any (security.region_fallback_countries_v1()) and psd.code is not null)) as has_state,
    c.publication_status,
    (select max(es.completeness_score) from publishing.entity_states es where es.entity_id=c.id) as completeness_score,
    greatest(c.updated_at,p.updated_at,coalesce(geo.geo_updated_at,'epoch'::timestamptz),coalesce(fos.updated_at,'epoch'::timestamptz)) as source_updated_at,
    concat_ws(' ',c.canonical_title,coalesce(p.display_name,p.canonical_name),coalesce(c.course_code,''),coalesce(sl.name,''),coalesce(fos.name,''),coalesce(array_to_string(coll.collection_names,' '),''),coalesce(array_to_string(acad.academic_option_names,' '),''),coalesce(c.description,'')) as base_search_text,
    setweight(to_tsvector('english',coalesce(c.canonical_title,'')),'A') ||
    setweight(to_tsvector('english',coalesce(p.display_name,p.canonical_name,'')),'B') ||
    setweight(to_tsvector('english',concat_ws(' ',coalesce(c.course_code,''),coalesce(sl.name,''),coalesce(fos.name,''),coalesce(array_to_string(coll.collection_names,' '),''),coalesce(array_to_string(acad.academic_option_names,' '),''))),'B') ||
    setweight(to_tsvector('english',coalesce(c.description,'')),'C') as base_search_tsv
  from catalogue.courses c
  join catalogue.providers p on p.id=c.provider_id
  join gates g on g.country_id=p.country_id
  join ref.countries co on co.id=p.country_id
  left join ref.study_levels sl on sl.id=c.study_level_id
  left join ref.fields_of_study fos on fos.id=c.primary_field_id
  left join ref.subdivisions psd on psd.id=p.subdivision_id
  left join lateral (
    select
      coalesce(array_agg(distinct sd.code order by sd.code) filter (where sd.code is not null),'{}'::text[]) as subdivision_codes,
      coalesce(array_agg(distinct cc.delivery_mode order by cc.delivery_mode) filter (where nullif(trim(cc.delivery_mode),'') is not null),'{}'::text[]) as delivery_modes,
      max(cp.updated_at) as geo_updated_at
    from catalogue.course_campuses cc
    join catalogue.campuses cp on cp.id=cc.campus_id
    left join ref.subdivisions sd on sd.id=cp.subdivision_id
    where cc.course_id=c.id
  ) geo on true
  left join lateral (
    select array_agg(distinct cl.name order by cl.name) as collection_names
    from catalogue.course_collection_memberships cm
    join catalogue.course_collections cl on cl.id=cm.collection_id
    where cm.course_id=c.id
  ) coll on true
  left join lateral (
    select array_agg(distinct ao.name order by ao.name) as academic_option_names
    from catalogue.course_academic_options ao
    where ao.course_id=c.id and ao.status='active'
  ) acad on true
  where c.lifecycle_status='active'
    and p.publication_status='published' and p.lifecycle_status='active';  -- v2.15.236 (Feature 4): an unpublished or archived provider's courses leave search

  alter table cf_search_course_base_v3_stage
    add column projection_version text not null default 'course-v3',
    add column generated_at timestamptz not null default now(),
    add column content_hash text,
    add column semantic_content_hash text;

  update cf_search_course_base_v3_stage s
  set semantic_content_hash=encode(extensions.digest(jsonb_build_object(
      'course',s.course_stable_key,'provider',s.provider_name,'title',s.course_title,'code',s.course_code,
      'level',s.study_level_code,'field',s.primary_field_code,'collections',s.collection_names,
      'academic_options',s.academic_option_names,'description',s.description
    )::text,'sha256'),'hex'),
      content_hash=encode(extensions.digest(jsonb_build_object(
      'course',s.course_stable_key,'provider',s.provider_stable_key,'country',s.country_code,
      'level',s.study_level_code,'field',s.primary_field_code,'states',s.subdivision_codes,
      'delivery',s.delivery_modes,'has_state',s.has_state,'publication',s.publication_status,
      'semantic',encode(extensions.digest(jsonb_build_object(
        'course',s.course_stable_key,'provider',s.provider_name,'title',s.course_title,'code',s.course_code,
        'level',s.study_level_code,'field',s.primary_field_code,'collections',s.collection_names,
        'academic_options',s.academic_option_names,'description',s.description
      )::text,'sha256'),'hex')
    )::text,'sha256'),'hex') where true;

  select count(*) into v_stage_count from cf_search_course_base_v3_stage;
  select coalesce(jsonb_object_agg(country_code,cnt),'{}'::jsonb) into v_country_counts
  from (select country_code,count(*) cnt from cf_search_course_base_v3_stage group by country_code order by country_code) x;
  select jsonb_build_object(
    'with_field',count(*) filter(where primary_field_id is not null),
    'with_state',count(*) filter(where has_state),
    'with_delivery',count(*) filter(where cardinality(delivery_modes)>0)
  ) into v_coverage from cf_search_course_base_v3_stage;

  select count(*) into v_new from cf_search_course_base_v3_stage s left join search.course_documents d using(course_id) where d.course_id is null;
  select count(*) into v_changed from cf_search_course_base_v3_stage s join search.course_documents d using(course_id)
   where d.content_hash is distinct from s.content_hash or d.projection_version is distinct from 'course-v3';
  select count(*) into v_unchanged from cf_search_course_base_v3_stage s join search.course_documents d using(course_id)
   where d.content_hash is not distinct from s.content_hash and d.projection_version='course-v3';
  select count(*) into v_removed from search.course_documents d left join cf_search_course_base_v3_stage s using(course_id) where s.course_id is null;

  select generation into v_current_generation from search.projection_state where projection_code='courses' for update;
  if v_current_generation is null then
    insert into search.projection_state(projection_code,generation,row_count,metadata) values('courses',1,0,'{}'::jsonb)
    returning generation into v_current_generation;
  end if;

  select encode(extensions.digest(coalesce(string_agg(course_id::text||':'||content_hash,'|' order by course_id::text),''),'sha256'),'hex') into v_stage_hash from cf_search_course_base_v3_stage;

  if p_apply then
    v_generation:=v_current_generation+1;
    insert into search.course_documents(
      course_id,provider_id,country_id,study_level_id,primary_field_id,course_stable_key,provider_stable_key,course_code,country_code,study_level_code,primary_field_code,primary_field_name,
      provider_name,course_title,collection_names,academic_option_names,description,search_text,search_tsv,subdivision_codes,delivery_modes,has_state,
      publication_status,completeness_score,catalogue_generation,projection_version,source_updated_at,generated_at,content_hash,semantic_content_hash,updated_at
    )
    select course_id,provider_id,country_id,study_level_id,primary_field_id,course_stable_key,provider_stable_key,course_code,country_code,study_level_code,primary_field_code,primary_field_name,
      provider_name,course_title,collection_names,academic_option_names,description,base_search_text,base_search_tsv,subdivision_codes,delivery_modes,has_state,
      publication_status,completeness_score,v_generation,'course-v3',source_updated_at,generated_at,content_hash,semantic_content_hash,now()
    from cf_search_course_base_v3_stage
    on conflict(course_id) do update set
      provider_id=excluded.provider_id,country_id=excluded.country_id,study_level_id=excluded.study_level_id,primary_field_id=excluded.primary_field_id,
      course_stable_key=excluded.course_stable_key,provider_stable_key=excluded.provider_stable_key,course_code=excluded.course_code,country_code=excluded.country_code,
      study_level_code=excluded.study_level_code,primary_field_code=excluded.primary_field_code,primary_field_name=excluded.primary_field_name,provider_name=excluded.provider_name,
      course_title=excluded.course_title,collection_names=excluded.collection_names,academic_option_names=excluded.academic_option_names,description=excluded.description,
      subdivision_codes=excluded.subdivision_codes,delivery_modes=excluded.delivery_modes,has_state=excluded.has_state,publication_status=excluded.publication_status,
      completeness_score=excluded.completeness_score,catalogue_generation=excluded.catalogue_generation,projection_version='course-v3',source_updated_at=excluded.source_updated_at,
      generated_at=excluded.generated_at,content_hash=excluded.content_hash,semantic_content_hash=case when nullif(trim(search.course_documents.enrichment_semantic_text),'') is null then excluded.semantic_content_hash else encode(extensions.digest(jsonb_build_object('base',excluded.course_stable_key,'provider',excluded.provider_name,'title',excluded.course_title,'code',excluded.course_code,'level',excluded.study_level_code,'field',excluded.primary_field_code,'collections',excluded.collection_names,'academic_options',excluded.academic_option_names,'description',excluded.description,'enrichment',nullif(trim(search.course_documents.enrichment_semantic_text),''))::text,'sha256'),'hex') end,updated_at=now()
    where search.course_documents.content_hash is distinct from excluded.content_hash
       or search.course_documents.projection_version is distinct from 'course-v3';
    get diagnostics v_applied=row_count;
    delete from search.course_documents d where not exists(select 1 from cf_search_course_base_v3_stage s where s.course_id=d.course_id);
  else
    v_generation:=v_current_generation;
  end if;

  return jsonb_build_object('apply',p_apply,'projection','courses','projection_version','course-v3','generation',v_generation,
    'stage_count',v_stage_count,'new',v_new,'changed',v_changed,'unchanged',v_unchanged,'removed',v_removed,'applied_rows',v_applied,
    'countries',v_country_counts,'coverage',v_coverage,'base_content_hash',v_stage_hash);
end
$$;


ALTER FUNCTION "search"."refresh_course_base_v3"("p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "search"."refresh_course_documents_v2"("p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'search', 'catalogue', 'scholarship', 'publishing', 'ref', 'pipeline', 'extensions', 'pg_temp'
    AS $$
declare
  v_generation bigint;
  v_current_generation bigint;
  v_stage_count bigint;
  v_new bigint;
  v_changed bigint;
  v_unchanged bigint;
  v_removed bigint;
  v_applied bigint := 0;
  v_stage_hash text;
  v_country_counts jsonb;
  v_coverage jsonb;
begin
  drop table if exists pg_temp.cf_search_course_stage;

  create temp table cf_search_course_stage on commit drop as
  with gates as (
    select g.country_id
    from search.projection_country_gates g
    where g.projection_code='courses' and g.gate_status='approved'
  ),
  eg as (
    select
      bool_or(domain_code='scholarship' and gate_status='approved') as scholarship_ok,
      bool_or(domain_code='course_link' and gate_status='approved') as link_ok,
      bool_or(domain_code='course_fee' and gate_status='approved') as fee_ok,
      bool_or(domain_code='course_intake' and gate_status='approved') as intake_ok,
      bool_or(domain_code='course_english' and gate_status='approved') as english_ok
    from search.enrichment_gates
    where projection_code='courses'
  )
  select
    c.id as course_id,
    c.provider_id,
    p.country_id,
    c.study_level_id,
    c.primary_field_id,
    c.stable_key as course_stable_key,
    p.stable_key as provider_stable_key,
    c.course_code,
    trim(co.iso_alpha2::text) as country_code,
    sl.code as study_level_code,
    fos.code as primary_field_code,
    fos.name as primary_field_name,
    coalesce(p.display_name,p.canonical_name) as provider_name,
    c.canonical_title as course_title,
    coalesce(coll.collection_names,'{}'::text[]) as collection_names,
    coalesce(acad.academic_option_names,'{}'::text[]) as academic_option_names,
    c.description,
    coalesce(geo.subdivision_codes,'{}'::text[]) as subdivision_codes,
    coalesce(geo.delivery_modes,'{}'::text[]) as delivery_modes,
    cardinality(coalesce(geo.subdivision_codes,'{}'::text[])) > 0 as has_state,
    (select link_ok from eg) and exists(
      select 1 from catalogue.course_links l
      where l.link_type = 'official_course' and l.course_id=c.id and l.status='active'
        and (l.valid_from is null or l.valid_from<=current_date)
        and (l.valid_to is null or l.valid_to>=current_date)
    ) as has_link,
    (select fee_ok from eg) and exists(
      select 1 from catalogue.course_fees f
      where f.course_id=c.id and f.status='active'
        and f.audience in ('international','all')
        and (f.valid_from is null or f.valid_from<=current_date)
        and (f.valid_to is null or f.valid_to>=current_date)
    ) as has_fee,
    (select intake_ok from eg) and exists(
      select 1 from catalogue.course_intakes i
      where i.course_id=c.id and i.status='active'
    ) as has_intake,
    (select english_ok from eg) and exists(
      select 1 from catalogue.course_english_requirements er
      where er.course_id=c.id
    ) as has_english,
    (select scholarship_ok from eg) and exists(
      select 1
      from scholarship.scopes ss
      join scholarship.scholarships s on s.id=ss.scholarship_id
      where s.lifecycle_status='active'
        and s.publication_status in ('published','internal')
        and ((ss.scope_type='course' and ss.course_id=c.id)
          or (ss.scope_type='provider' and ss.provider_id=c.provider_id))
    ) as has_scholarship,
    c.publication_status,
    (select max(es.completeness_score) from publishing.entity_states es where es.entity_id=c.id) as completeness_score,
    greatest(c.updated_at,p.updated_at,coalesce(geo.geo_updated_at,'epoch'::timestamptz),coalesce(fos.updated_at,'epoch'::timestamptz)) as source_updated_at,
    concat_ws(' ',
      c.canonical_title,
      coalesce(p.display_name,p.canonical_name),
      coalesce(c.course_code,''),
      coalesce(sl.name,''),
      coalesce(fos.name,''),
      coalesce(array_to_string(coll.collection_names,' '),''),
      coalesce(array_to_string(acad.academic_option_names,' '),''),
      coalesce(c.description,'')
    ) as search_text,
    setweight(to_tsvector('english',coalesce(c.canonical_title,'')),'A') ||
    setweight(to_tsvector('english',coalesce(p.display_name,p.canonical_name,'')),'B') ||
    setweight(to_tsvector('english',concat_ws(' ',coalesce(c.course_code,''),coalesce(sl.name,''),coalesce(fos.name,''),coalesce(array_to_string(coll.collection_names,' '),''),coalesce(array_to_string(acad.academic_option_names,' '),''))),'B') ||
    setweight(to_tsvector('english',coalesce(c.description,'')),'C') as search_tsv
  from catalogue.courses c
  join catalogue.providers p on p.id=c.provider_id
  join gates g on g.country_id=p.country_id
  join ref.countries co on co.id=p.country_id
  left join ref.study_levels sl on sl.id=c.study_level_id
  left join ref.fields_of_study fos on fos.id=c.primary_field_id
  left join lateral (
    select
      coalesce(array_agg(distinct sd.code order by sd.code) filter (where sd.code is not null),'{}'::text[]) as subdivision_codes,
      coalesce(array_agg(distinct cc.delivery_mode order by cc.delivery_mode) filter (where nullif(trim(cc.delivery_mode),'') is not null),'{}'::text[]) as delivery_modes,
      max(cp.updated_at) as geo_updated_at
    from catalogue.course_campuses cc
    join catalogue.campuses cp on cp.id=cc.campus_id
    left join ref.subdivisions sd on sd.id=cp.subdivision_id
    where cc.course_id=c.id
  ) geo on true
  left join lateral (
    select array_agg(distinct cl.name order by cl.name) as collection_names
    from catalogue.course_collection_memberships cm
    join catalogue.course_collections cl on cl.id=cm.collection_id
    where cm.course_id=c.id
  ) coll on true
  left join lateral (
    select array_agg(distinct ao.name order by ao.name) as academic_option_names
    from catalogue.course_academic_options ao
    where ao.course_id=c.id and ao.status='active'
  ) acad on true
  where c.lifecycle_status='active';

  alter table cf_search_course_stage
    add column projection_version text not null default 'course-v2',
    add column generated_at timestamptz not null default now(),
    add column content_hash text,
    add column semantic_content_hash text;

  update cf_search_course_stage s
  set semantic_content_hash=encode(extensions.digest(jsonb_build_object(
      'course',s.course_stable_key,
      'provider',s.provider_name,
      'title',s.course_title,
      'code',s.course_code,
      'level',s.study_level_code,
      'field',s.primary_field_code,
      'collections',s.collection_names,
      'academic_options',s.academic_option_names,
      'description',s.description
    )::text,'sha256'),'hex'),
      content_hash=encode(extensions.digest(jsonb_build_object(
      'course',s.course_stable_key,
      'provider',s.provider_stable_key,
      'country',s.country_code,
      'level',s.study_level_code,
      'field',s.primary_field_code,
      'states',s.subdivision_codes,
      'delivery',s.delivery_modes,
      'has_state',s.has_state,
      'has_link',s.has_link,
      'has_fee',s.has_fee,
      'has_intake',s.has_intake,
      'has_english',s.has_english,
      'has_scholarship',s.has_scholarship,
      'publication',s.publication_status,
      'semantic',encode(extensions.digest(jsonb_build_object(
        'course',s.course_stable_key,'provider',s.provider_name,'title',s.course_title,'code',s.course_code,
        'level',s.study_level_code,'field',s.primary_field_code,'collections',s.collection_names,
        'academic_options',s.academic_option_names,'description',s.description
      )::text,'sha256'),'hex')
    )::text,'sha256'),'hex') where true;

  select count(*) into v_stage_count from cf_search_course_stage;
  select coalesce(jsonb_object_agg(country_code,cnt),'{}'::jsonb)
  into v_country_counts
  from (select country_code,count(*) cnt from cf_search_course_stage group by country_code order by country_code) x;

  select jsonb_build_object(
    'with_field',count(*) filter(where primary_field_id is not null),
    'with_state',count(*) filter(where has_state),
    'with_delivery',count(*) filter(where cardinality(delivery_modes)>0),
    'with_link',count(*) filter(where has_link),
    'with_fee',count(*) filter(where has_fee),
    'with_intake',count(*) filter(where has_intake),
    'with_english',count(*) filter(where has_english),
    'with_scholarship',count(*) filter(where has_scholarship)
  ) into v_coverage from cf_search_course_stage;

  select count(*) into v_new
  from cf_search_course_stage s left join search.course_documents d using(course_id)
  where d.course_id is null;

  select count(*) into v_changed
  from cf_search_course_stage s join search.course_documents d using(course_id)
  where d.content_hash is distinct from s.content_hash or d.projection_version is distinct from s.projection_version;

  select count(*) into v_unchanged
  from cf_search_course_stage s join search.course_documents d using(course_id)
  where d.content_hash is not distinct from s.content_hash and d.projection_version is not distinct from s.projection_version;

  select count(*) into v_removed
  from search.course_documents d left join cf_search_course_stage s using(course_id)
  where s.course_id is null;

  select generation into v_current_generation from search.projection_state where projection_code='courses' for update;
  if v_current_generation is null then
    insert into search.projection_state(projection_code,generation,row_count,metadata) values('courses',1,0,'{}'::jsonb)
    returning generation into v_current_generation;
  end if;

  select encode(extensions.digest(coalesce(string_agg(course_id::text||':'||content_hash,'|' order by course_id::text),''),'sha256'),'hex')
  into v_stage_hash from cf_search_course_stage;

  if p_apply then
    v_generation := v_current_generation + 1;

    insert into search.course_documents(
      course_id,provider_id,country_id,study_level_id,primary_field_id,
      course_stable_key,provider_stable_key,course_code,country_code,study_level_code,primary_field_code,primary_field_name,
      provider_name,course_title,collection_names,academic_option_names,description,search_text,search_tsv,
      subdivision_codes,delivery_modes,has_state,has_link,has_fee,has_intake,has_english,has_scholarship,
      publication_status,completeness_score,catalogue_generation,projection_version,source_updated_at,generated_at,content_hash,semantic_content_hash,updated_at
    )
    select
      course_id,provider_id,country_id,study_level_id,primary_field_id,
      course_stable_key,provider_stable_key,course_code,country_code,study_level_code,primary_field_code,primary_field_name,
      provider_name,course_title,collection_names,academic_option_names,description,search_text,search_tsv,
      subdivision_codes,delivery_modes,has_state,has_link,has_fee,has_intake,has_english,has_scholarship,
      publication_status,completeness_score,v_generation,projection_version,source_updated_at,generated_at,content_hash,semantic_content_hash,now()
    from cf_search_course_stage
    on conflict(course_id) do update set
      provider_id=excluded.provider_id,
      country_id=excluded.country_id,
      study_level_id=excluded.study_level_id,
      primary_field_id=excluded.primary_field_id,
      course_stable_key=excluded.course_stable_key,
      provider_stable_key=excluded.provider_stable_key,
      course_code=excluded.course_code,
      country_code=excluded.country_code,
      study_level_code=excluded.study_level_code,
      primary_field_code=excluded.primary_field_code,
      primary_field_name=excluded.primary_field_name,
      provider_name=excluded.provider_name,
      course_title=excluded.course_title,
      collection_names=excluded.collection_names,
      academic_option_names=excluded.academic_option_names,
      description=excluded.description,
      search_text=excluded.search_text,
      search_tsv=excluded.search_tsv,
      subdivision_codes=excluded.subdivision_codes,
      delivery_modes=excluded.delivery_modes,
      has_state=excluded.has_state,
      has_link=excluded.has_link,
      has_fee=excluded.has_fee,
      has_intake=excluded.has_intake,
      has_english=excluded.has_english,
      has_scholarship=excluded.has_scholarship,
      publication_status=excluded.publication_status,
      completeness_score=excluded.completeness_score,
      catalogue_generation=excluded.catalogue_generation,
      projection_version=excluded.projection_version,
      source_updated_at=excluded.source_updated_at,
      generated_at=excluded.generated_at,
      content_hash=excluded.content_hash,
      semantic_content_hash=excluded.semantic_content_hash,
      updated_at=now()
    where search.course_documents.content_hash is distinct from excluded.content_hash
       or search.course_documents.projection_version is distinct from excluded.projection_version;

    get diagnostics v_applied=row_count;

    delete from search.course_documents d
    where not exists(select 1 from cf_search_course_stage s where s.course_id=d.course_id);

    update search.projection_state
    set generation=v_generation,
        rebuilt_at=now(),
        row_count=v_stage_count,
        content_hash=v_stage_hash,
        metadata=jsonb_build_object(
          'projection_version','course-v2',
          'countries',v_country_counts,
          'coverage',v_coverage,
          'country_gate','explicit',
          'enrichment_gate','explicit'
        )
    where projection_code='courses';
  else
    v_generation := v_current_generation;
  end if;

  return jsonb_build_object(
    'apply',p_apply,
    'projection','courses',
    'projection_version','course-v2',
    'generation',v_generation,
    'stage_count',v_stage_count,
    'new',v_new,
    'changed',v_changed,
    'unchanged',v_unchanged,
    'removed',v_removed,
    'applied_rows',v_applied,
    'countries',v_country_counts,
    'coverage',v_coverage,
    'content_hash',v_stage_hash
  );
end
$$;


ALTER FUNCTION "search"."refresh_course_documents_v2"("p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "search"."refresh_course_documents_v3"("p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'search', 'extensions', 'pg_temp'
    AS $$
declare
  v_base jsonb;
  v_enrichment_dry jsonb;
  v_enrichment jsonb;
  v_full_hash text;
  v_coverage jsonb;
  v_generation bigint;
  v_enrichment_changed bigint;
  v_base_new bigint;
begin
  if p_apply then
    perform pg_advisory_xact_lock(hashtext('cf247:search_course_documents_writer'));  -- fixed: the one writer lock for search.course_documents (W27)
  end if;
  v_base:=search.refresh_course_base_v3(p_apply);
  v_enrichment_dry:=search.refresh_course_enrichment_v1(false);
  v_enrichment_changed:=coalesce((v_enrichment_dry->>'changed')::bigint,0);
  v_base_new:=coalesce((v_base->>'new')::bigint,0);

  if p_apply and (v_enrichment_changed>0 or v_base_new>0) then
    v_enrichment:=search.refresh_course_enrichment_v1(true);
  else
    v_enrichment:=v_enrichment_dry;
  end if;

  if p_apply then
    select encode(extensions.digest(coalesce(string_agg(course_id::text||':'||coalesce(content_hash,'')||':'||coalesce(enrichment_content_hash,''),'|' order by course_id::text),''),'sha256'),'hex')
      into v_full_hash from search.course_documents;
    select jsonb_build_object(
      'with_field',count(*) filter(where primary_field_id is not null),
      'with_state',count(*) filter(where has_state),
      'with_delivery',count(*) filter(where cardinality(delivery_modes)>0),
      'with_regulatory_tuition',count(*) filter(where has_regulatory_tuition),
      'with_provider_current_tuition',count(*) filter(where has_provider_current_tuition),
      'with_official_url',count(*) filter(where official_course_url is not null),
      'with_intake',count(*) filter(where has_intake),
      'with_english',count(*) filter(where has_english),
      'with_scholarship',count(*) filter(where has_scholarship)
    ) into v_coverage from search.course_documents;
    update search.projection_state
      set generation=generation+1,rebuilt_at=now(),row_count=(select count(*) from search.course_documents),content_hash=v_full_hash,
          metadata=jsonb_build_object(
            'projection_version','course-v3','countries',v_base->'countries','coverage',v_coverage,
            'country_gate','explicit','enrichment_gate','domain_and_source_explicit',
            'base_content_hash',v_base->>'base_content_hash','enrichment_stage_hash',v_enrichment->>'stage_hash',
            'refresh_function','search.refresh_course_documents_v3'
          )
      where projection_code='courses'
      returning generation into v_generation;
  else
    select generation into v_generation from search.projection_state where projection_code='courses';
  end if;

  return jsonb_build_object('apply',p_apply,'projection','courses','projection_version','course-v3','generation',v_generation,
    'base',v_base,'enrichment',v_enrichment,'full_content_hash',v_full_hash);
end
$$;


ALTER FUNCTION "search"."refresh_course_documents_v3"("p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "search"."refresh_course_enrichment_core_scoped_v1"("p_course_ids" "uuid"[], "p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'search', 'catalogue', 'scholarship', 'pipeline', 'ref', 'extensions', 'pg_temp'
    AS $_$
declare
  v_rows bigint;
  v_changed bigint;
  v_unchanged bigint;
  v_stage_hash text;
  v_coverage jsonb;
begin
  drop table if exists pg_temp.cf_search_enrichment_stage;
  create temp table cf_search_enrichment_stage on commit drop as
  with global_gates as (
    select
      bool_or(domain_code='regulatory_tuition' and gate_status='approved') regulatory_ok,
      bool_or(domain_code='provider_current_tuition' and gate_status='approved') provider_fee_ok,
      bool_or(domain_code='official_course_url' and gate_status='approved') link_ok,
      bool_or(domain_code='course_intake' and gate_status='approved') intake_ok,
      bool_or(domain_code='course_english' and gate_status='approved') english_ok,
      bool_or(domain_code='scholarship' and gate_status='approved') scholarship_ok
    from search.enrichment_gates where projection_code='courses'
  )
  select d.course_id,
    case
      when d.country_code='NZ' then 'not_applicable'
      when not (select regulatory_ok from global_gates) then 'not_admitted'
      when rf.fee_id is null then 'source_null'
      when rf.amount=0 then 'zero'
      else 'present'
    end as regulatory_tuition_state,
    ((select regulatory_ok from global_gates) and rf.fee_id is not null) as has_regulatory_tuition,
    case when (select regulatory_ok from global_gates) then rf.amount end as regulatory_tuition_amount,
    case when (select regulatory_ok from global_gates) then rf.currency_code end as regulatory_tuition_currency,
    case when (select regulatory_ok from global_gates) then rf.basis end as regulatory_tuition_basis,
    ((select provider_fee_ok from global_gates) and pf.option_count>0) as has_provider_current_tuition,
    case when (select provider_fee_ok from global_gates) then pf.annual_amount end as provider_annual_tuition_amount,
    case when (select provider_fee_ok from global_gates) then pf.annual_currency end as provider_annual_tuition_currency,
    case when (select provider_fee_ok from global_gates) then coalesce(pf.options,'[]'::jsonb) else '[]'::jsonb end as provider_tuition_options,
    case when (select link_ok from global_gates) then lk.url end as official_course_url,
    case when (select intake_ok from global_gates) then coalesce(it.options,'[]'::jsonb) else '[]'::jsonb end as intake_options,
    case when (select intake_ok from global_gates) then it.earliest_date end as earliest_intake_date,
    case when (select english_ok from global_gates) then coalesce(en.options,'[]'::jsonb) else '[]'::jsonb end as english_requirement_options,
    case when (select scholarship_ok from global_gates) then coalesce(sc.options,'[]'::jsonb) else '[]'::jsonb end as scholarship_options,
    concat_ws(' ',
      case when (select intake_ok from global_gates) then it.semantic_text end,
      case when (select english_ok from global_gates) then en.semantic_text end,
      case when (select scholarship_ok from global_gates) then sc.semantic_text end
    ) as enrichment_semantic_text
  from search.course_documents d
  left join lateral (
    select f.id fee_id,f.amount,f.currency_code,f.basis
    from catalogue.course_fees f join pipeline.sources s on s.id=f.source_id
    where f.course_id=d.course_id and f.status='active' and f.audience in ('international','all')
      and f.fee_type='tuition' and f.basis='registered_total_course'
      and s.label='CRICOS Providers, Courses and Locations'
    order by f.updated_at desc nulls last,f.id limit 1
  ) rf on true
  left join lateral (
    select count(*) option_count,
      -- CF-247 16 Oct 2026: the latest year's annual fee (was the lowest of any year)
      (array_agg(f.amount order by f.fee_year desc nulls last, f.amount) filter(where f.basis in ('annual','indicative_annual')))[1] annual_amount,
      (array_agg(f.currency_code order by f.fee_year desc nulls last, f.amount) filter(where f.basis in ('annual','indicative_annual')))[1] annual_currency,
      jsonb_agg(jsonb_build_object('fee_year',f.fee_year,'amount',f.amount,'currency',trim(f.currency_code),'basis',f.basis,'load_basis',f.load_basis,'campus_id',f.campus_id,'valid_from',f.valid_from,'valid_to',f.valid_to,'last_verified_at',f.last_verified_at) order by f.fee_year desc nulls last,f.basis,f.amount,f.id) options
    from catalogue.course_fees f
    join search.enrichment_source_gates sg on sg.projection_code='courses' and sg.domain_code='provider_current_tuition' and sg.source_id=f.source_id and sg.gate_status='approved'
    where f.course_id=d.course_id and f.status='active' and f.audience in ('international','all') and f.fee_type='provider_current_tuition'
      and (f.valid_from is null or f.valid_from<=current_date) and (f.valid_to is null or f.valid_to>=current_date)
  ) pf on true
  left join lateral (
    -- 2 Nov 2026 (E16-2, Platform Admin 07:21; integrator review): one link, or the primary link, as before; with several and none primary,
    -- the link equal to courses.course_url (the same page however it is spelled: case, http or https, www, a closing slash or a section)
    -- when it passes the course page check (security.course_page_check_v1); otherwise today's choice. No link is withdrawn here: only links
    -- shown to be wrong are removed, by their own governed step
    select case when count(*) <= 1 or bool_or(l.is_primary)
                then (array_agg(l.url order by l.is_primary desc,l.last_verified_at desc nulls last,l.updated_at desc nulls last,l.id))[1]
                else coalesce((select k.u from unnest(array_agg(l.url order by l.last_verified_at desc nulls last,l.updated_at desc nulls last,l.id)) with ordinality k(u, o)
                        join catalogue.courses c on c.id=d.course_id
                       where regexp_replace(regexp_replace(regexp_replace(lower(k.u),'#.*$',''),'^https?://(www\.)?',''),'/+$','')
                             =regexp_replace(regexp_replace(regexp_replace(lower(c.course_url),'#.*$',''),'^https?://(www\.)?',''),'/+$','')
                         and security.course_page_check_v1(d.course_id,k.u)->>'verdict'='pass'
                       order by (k.u=c.course_url) desc,k.o limit 1),
                     (array_agg(l.url order by l.is_primary desc,l.last_verified_at desc nulls last,l.updated_at desc nulls last,l.id))[1]) end url
    from catalogue.course_links l
    join search.enrichment_source_gates sg on sg.projection_code='courses' and sg.domain_code='official_course_url' and sg.source_id=l.source_id and sg.gate_status='approved'
    where l.course_id=d.course_id and l.status='active'
      and (l.valid_from is null or l.valid_from<=current_date) and (l.valid_to is null or l.valid_to>=current_date)
  ) lk on true
  left join lateral (
    select jsonb_agg(jsonb_build_object('year',i.intake_year,'label',i.intake_label,'start_date',i.start_date,'application_deadline',i.application_deadline,'campus_id',i.campus_id) order by i.start_date nulls last,i.intake_year,i.intake_label,i.id) options,
      min(i.start_date) filter(where i.start_date>=current_date) earliest_date,
      string_agg(distinct concat_ws(' ',i.intake_year::text,i.intake_label), ' ' order by concat_ws(' ',i.intake_year::text,i.intake_label)) semantic_text
    from catalogue.course_intakes i
    join search.enrichment_source_gates sg on sg.projection_code='courses' and sg.domain_code='course_intake' and sg.source_id=i.source_id and sg.gate_status='approved'
    where i.course_id=d.course_id and i.status='active'
  ) it on true
  left join lateral (
    select jsonb_agg(jsonb_build_object('test_code',t.code,'test_name',t.name,'overall_score',er.overall_score,'component_scores',er.component_scores,'notes',er.notes,'valid_from',er.valid_from,'valid_to',er.valid_to,'last_verified_at',er.last_verified_at) order by t.code,er.overall_score,er.id) options,
      string_agg(distinct concat_ws(' ',t.name,t.code,er.overall_score::text), ' ' order by concat_ws(' ',t.name,t.code,er.overall_score::text)) semantic_text
    from catalogue.course_english_requirements er
    join ref.english_tests t on t.id=er.english_test_id
    join search.enrichment_source_gates sg on sg.projection_code='courses' and sg.domain_code='course_english' and sg.source_id=er.source_id and sg.gate_status='approved'
    where er.course_id=d.course_id and er.status='active'
      and (er.valid_from is null or er.valid_from<=current_date) and (er.valid_to is null or er.valid_to>=current_date)
  ) en on true
  left join lateral (
    select jsonb_agg(jsonb_build_object('scholarship_key',s.stable_key,'name',s.name,'award_value_text',scholarship.value_label(s.id),'academic_year',s.academic_year,'application_close_date',s.application_close_date,'source_url',s.source_url,
             'audience',s.audience,'nationalities',s.nationalities,'is_maximum',s.award_value_is_maximum,
             'saving_per_year',fc.scholarship_saving_amount,'saving_currency',fc.currency_code,'saving_basis',fc.fee_basis)
             order by fc.scholarship_saving_amount desc nulls last, s.name) options,
      string_agg(s.name,' ' order by s.name) semantic_text
    from scholarship.course_mappings cm join scholarship.scholarships s on s.id=cm.scholarship_id
    left join scholarship.course_financial_calculations fc on fc.mapping_id=cm.id and fc.calculation_status='calculated'
    where cm.course_id=d.course_id and cm.mapping_state='mapped'
      and s.lifecycle_status='active' and s.publication_status in ('published','internal')
      and s.audience in ('international','international_and_domestic')
  ) sc on true
  where d.course_id = any(p_course_ids);

  alter table cf_search_enrichment_stage add column enrichment_content_hash text;
  update cf_search_enrichment_stage s set enrichment_content_hash=encode(extensions.digest(jsonb_build_object(
    'regulatory_state',s.regulatory_tuition_state,'regulatory_amount',s.regulatory_tuition_amount,'regulatory_currency',s.regulatory_tuition_currency,'regulatory_basis',s.regulatory_tuition_basis,
    'has_provider_current_tuition',s.has_provider_current_tuition,'provider_annual_amount',s.provider_annual_tuition_amount,'provider_annual_currency',s.provider_annual_tuition_currency,'provider_options',s.provider_tuition_options,
    'official_url',s.official_course_url,'intakes',s.intake_options,'english',s.english_requirement_options,'scholarships',s.scholarship_options,'semantic_text',s.enrichment_semantic_text
  )::text,'sha256'),'hex')
  where s.course_id is not null;

  select count(*) into v_rows from cf_search_enrichment_stage;
  select count(*) into v_changed from cf_search_enrichment_stage s join search.course_documents d using(course_id) where d.enrichment_content_hash is distinct from s.enrichment_content_hash;
  select count(*) into v_unchanged from cf_search_enrichment_stage s join search.course_documents d using(course_id) where d.enrichment_content_hash is not distinct from s.enrichment_content_hash;
  select encode(extensions.digest(coalesce(string_agg(course_id::text||':'||enrichment_content_hash,'|' order by course_id::text),''),'sha256'),'hex') into v_stage_hash from cf_search_enrichment_stage;
  select jsonb_build_object(
    'regulatory_present',count(*) filter(where regulatory_tuition_state='present'),
    'regulatory_zero',count(*) filter(where regulatory_tuition_state='zero'),
    'regulatory_source_null',count(*) filter(where regulatory_tuition_state='source_null'),
    'regulatory_not_applicable',count(*) filter(where regulatory_tuition_state='not_applicable'),
    'with_provider_current_tuition',count(*) filter(where has_provider_current_tuition),
    'with_provider_annual_tuition',count(*) filter(where provider_annual_tuition_amount is not null),
    'with_official_url',count(*) filter(where official_course_url is not null),
    'with_intake',count(*) filter(where jsonb_array_length(intake_options)>0),
    'with_english',count(*) filter(where jsonb_array_length(english_requirement_options)>0),
    'with_scholarship',count(*) filter(where jsonb_array_length(scholarship_options)>0)
  ) into v_coverage from cf_search_enrichment_stage;

  if p_apply then
    update search.course_documents d set
      regulatory_tuition_state=s.regulatory_tuition_state,
      has_regulatory_tuition=s.has_regulatory_tuition,
      regulatory_tuition_amount=s.regulatory_tuition_amount,
      regulatory_tuition_currency=s.regulatory_tuition_currency,
      regulatory_tuition_basis=s.regulatory_tuition_basis,
      has_provider_current_tuition=s.has_provider_current_tuition,
      has_fee=s.has_provider_current_tuition,
      provider_annual_tuition_amount=s.provider_annual_tuition_amount,
      provider_annual_tuition_currency=s.provider_annual_tuition_currency,
      provider_tuition_options=s.provider_tuition_options,
      official_course_url=s.official_course_url,
      has_link=(s.official_course_url is not null),
      intake_options=s.intake_options,
      earliest_intake_date=s.earliest_intake_date,
      has_intake=(jsonb_array_length(s.intake_options)>0),
      english_requirement_options=s.english_requirement_options,
      has_english=(jsonb_array_length(s.english_requirement_options)>0),
      scholarship_options=s.scholarship_options,
      has_scholarship=(jsonb_array_length(s.scholarship_options)>0),
      enrichment_semantic_text=nullif(trim(s.enrichment_semantic_text),''),
      enrichment_content_hash=s.enrichment_content_hash,
      search_text=concat_ws(' ',d.course_title,d.provider_name,d.course_code,d.study_level_code,d.primary_field_name,array_to_string(d.collection_names,' '),array_to_string(d.academic_option_names,' '),d.description,nullif(trim(s.enrichment_semantic_text),'')),
      search_tsv=setweight(to_tsvector('english',coalesce(d.course_title,'')),'A') || setweight(to_tsvector('english',coalesce(d.provider_name,'')),'B') || setweight(to_tsvector('english',concat_ws(' ',coalesce(d.course_code,''),coalesce(d.study_level_code,''),coalesce(d.primary_field_name,''),coalesce(array_to_string(d.collection_names,' '),''),coalesce(array_to_string(d.academic_option_names,' '),''))),'B') || setweight(to_tsvector('english',concat_ws(' ',coalesce(d.description,''),coalesce(s.enrichment_semantic_text,''))),'C'),
      semantic_content_hash=encode(extensions.digest(jsonb_build_object('base',d.course_stable_key,'provider',d.provider_name,'title',d.course_title,'code',d.course_code,'level',d.study_level_code,'field',d.primary_field_code,'collections',d.collection_names,'academic_options',d.academic_option_names,'description',d.description,'enrichment',nullif(trim(s.enrichment_semantic_text),''))::text,'sha256'),'hex'),
      projection_version='course-v3',
      generated_at=now(),
      updated_at=now()
    from cf_search_enrichment_stage s where d.course_id=s.course_id;
  end if;

  return jsonb_build_object('projection_version','course-v3','scope','courses','requested_courses',coalesce(cardinality(p_course_ids),0),'apply',p_apply,'rows',v_rows,'changed',v_changed,'unchanged',v_unchanged,'stage_hash',v_stage_hash,'coverage',v_coverage);
end
$_$;


ALTER FUNCTION "search"."refresh_course_enrichment_core_scoped_v1"("p_course_ids" "uuid"[], "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "search"."refresh_course_enrichment_core_v1"("p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'search', 'catalogue', 'scholarship', 'pipeline', 'ref', 'extensions', 'pg_temp'
    AS $_$
declare
  v_rows bigint;
  v_changed bigint;
  v_unchanged bigint;
  v_stage_hash text;
  v_coverage jsonb;
begin
  drop table if exists pg_temp.cf_search_enrichment_stage;
  create temp table cf_search_enrichment_stage on commit drop as
  with global_gates as (
    select
      bool_or(domain_code='regulatory_tuition' and gate_status='approved') regulatory_ok,
      bool_or(domain_code='provider_current_tuition' and gate_status='approved') provider_fee_ok,
      bool_or(domain_code='official_course_url' and gate_status='approved') link_ok,
      bool_or(domain_code='course_intake' and gate_status='approved') intake_ok,
      bool_or(domain_code='course_english' and gate_status='approved') english_ok,
      bool_or(domain_code='scholarship' and gate_status='approved') scholarship_ok
    from search.enrichment_gates where projection_code='courses'
  )
  select d.course_id,
    case
      when d.country_code='NZ' then 'not_applicable'
      when not (select regulatory_ok from global_gates) then 'not_admitted'
      when rf.fee_id is null then 'source_null'
      when rf.amount=0 then 'zero'
      else 'present'
    end as regulatory_tuition_state,
    ((select regulatory_ok from global_gates) and rf.fee_id is not null) as has_regulatory_tuition,
    case when (select regulatory_ok from global_gates) then rf.amount end as regulatory_tuition_amount,
    case when (select regulatory_ok from global_gates) then rf.currency_code end as regulatory_tuition_currency,
    case when (select regulatory_ok from global_gates) then rf.basis end as regulatory_tuition_basis,
    ((select provider_fee_ok from global_gates) and pf.option_count>0) as has_provider_current_tuition,
    case when (select provider_fee_ok from global_gates) then pf.annual_amount end as provider_annual_tuition_amount,
    case when (select provider_fee_ok from global_gates) then pf.annual_currency end as provider_annual_tuition_currency,
    case when (select provider_fee_ok from global_gates) then coalesce(pf.options,'[]'::jsonb) else '[]'::jsonb end as provider_tuition_options,
    case when (select link_ok from global_gates) then lk.url end as official_course_url,
    case when (select intake_ok from global_gates) then coalesce(it.options,'[]'::jsonb) else '[]'::jsonb end as intake_options,
    case when (select intake_ok from global_gates) then it.earliest_date end as earliest_intake_date,
    case when (select english_ok from global_gates) then coalesce(en.options,'[]'::jsonb) else '[]'::jsonb end as english_requirement_options,
    case when (select scholarship_ok from global_gates) then coalesce(sc.options,'[]'::jsonb) else '[]'::jsonb end as scholarship_options,
    concat_ws(' ',
      case when (select intake_ok from global_gates) then it.semantic_text end,
      case when (select english_ok from global_gates) then en.semantic_text end,
      case when (select scholarship_ok from global_gates) then sc.semantic_text end
    ) as enrichment_semantic_text
  from search.course_documents d
  left join lateral (
    select f.id fee_id,f.amount,f.currency_code,f.basis
    from catalogue.course_fees f join pipeline.sources s on s.id=f.source_id
    where f.course_id=d.course_id and f.status='active' and f.audience in ('international','all')
      and f.fee_type='tuition' and f.basis='registered_total_course'
      and s.label='CRICOS Providers, Courses and Locations'
    order by f.updated_at desc nulls last,f.id limit 1
  ) rf on true
  left join lateral (
    select count(*) option_count,
      -- CF-247 16 Oct 2026: the latest year's annual fee (was the lowest of any year)
      (array_agg(f.amount order by f.fee_year desc nulls last, f.amount) filter(where f.basis in ('annual','indicative_annual')))[1] annual_amount,
      (array_agg(f.currency_code order by f.fee_year desc nulls last, f.amount) filter(where f.basis in ('annual','indicative_annual')))[1] annual_currency,
      jsonb_agg(jsonb_build_object('fee_year',f.fee_year,'amount',f.amount,'currency',trim(f.currency_code),'basis',f.basis,'load_basis',f.load_basis,'campus_id',f.campus_id,'valid_from',f.valid_from,'valid_to',f.valid_to,'last_verified_at',f.last_verified_at) order by f.fee_year desc nulls last,f.basis,f.amount,f.id) options
    from catalogue.course_fees f
    join search.enrichment_source_gates sg on sg.projection_code='courses' and sg.domain_code='provider_current_tuition' and sg.source_id=f.source_id and sg.gate_status='approved'
    where f.course_id=d.course_id and f.status='active' and f.audience in ('international','all') and f.fee_type='provider_current_tuition'
      and (f.valid_from is null or f.valid_from<=current_date) and (f.valid_to is null or f.valid_to>=current_date)
  ) pf on true
  left join lateral (
    -- 2 Nov 2026 (E16-2, Platform Admin 07:21; integrator review): one link, or the primary link, as before; with several and none primary,
    -- the link equal to courses.course_url (the same page however it is spelled: case, http or https, www, a closing slash or a section)
    -- when it passes the course page check (security.course_page_check_v1); otherwise today's choice. No link is withdrawn here: only links
    -- shown to be wrong are removed, by their own governed step
    select case when count(*) <= 1 or bool_or(l.is_primary)
                then (array_agg(l.url order by l.is_primary desc,l.last_verified_at desc nulls last,l.updated_at desc nulls last,l.id))[1]
                else coalesce((select k.u from unnest(array_agg(l.url order by l.last_verified_at desc nulls last,l.updated_at desc nulls last,l.id)) with ordinality k(u, o)
                        join catalogue.courses c on c.id=d.course_id
                       where regexp_replace(regexp_replace(regexp_replace(lower(k.u),'#.*$',''),'^https?://(www\.)?',''),'/+$','')
                             =regexp_replace(regexp_replace(regexp_replace(lower(c.course_url),'#.*$',''),'^https?://(www\.)?',''),'/+$','')
                         and security.course_page_check_v1(d.course_id,k.u)->>'verdict'='pass'
                       order by (k.u=c.course_url) desc,k.o limit 1),
                     (array_agg(l.url order by l.is_primary desc,l.last_verified_at desc nulls last,l.updated_at desc nulls last,l.id))[1]) end url
    from catalogue.course_links l
    join search.enrichment_source_gates sg on sg.projection_code='courses' and sg.domain_code='official_course_url' and sg.source_id=l.source_id and sg.gate_status='approved'
    where l.course_id=d.course_id and l.status='active'
      and (l.valid_from is null or l.valid_from<=current_date) and (l.valid_to is null or l.valid_to>=current_date)
  ) lk on true
  left join lateral (
    select jsonb_agg(jsonb_build_object('year',i.intake_year,'label',i.intake_label,'start_date',i.start_date,'application_deadline',i.application_deadline,'campus_id',i.campus_id) order by i.start_date nulls last,i.intake_year,i.intake_label,i.id) options,
      min(i.start_date) filter(where i.start_date>=current_date) earliest_date,
      string_agg(distinct concat_ws(' ',i.intake_year::text,i.intake_label), ' ' order by concat_ws(' ',i.intake_year::text,i.intake_label)) semantic_text
    from catalogue.course_intakes i
    join search.enrichment_source_gates sg on sg.projection_code='courses' and sg.domain_code='course_intake' and sg.source_id=i.source_id and sg.gate_status='approved'
    where i.course_id=d.course_id and i.status='active'
  ) it on true
  left join lateral (
    select jsonb_agg(jsonb_build_object('test_code',t.code,'test_name',t.name,'overall_score',er.overall_score,'component_scores',er.component_scores,'notes',er.notes,'valid_from',er.valid_from,'valid_to',er.valid_to,'last_verified_at',er.last_verified_at) order by t.code,er.overall_score,er.id) options,
      string_agg(distinct concat_ws(' ',t.name,t.code,er.overall_score::text), ' ' order by concat_ws(' ',t.name,t.code,er.overall_score::text)) semantic_text
    from catalogue.course_english_requirements er
    join ref.english_tests t on t.id=er.english_test_id
    join search.enrichment_source_gates sg on sg.projection_code='courses' and sg.domain_code='course_english' and sg.source_id=er.source_id and sg.gate_status='approved'
    where er.course_id=d.course_id and er.status='active'
      and (er.valid_from is null or er.valid_from<=current_date) and (er.valid_to is null or er.valid_to>=current_date)
  ) en on true
  left join lateral (
    select jsonb_agg(jsonb_build_object('scholarship_key',s.stable_key,'name',s.name,'award_value_text',scholarship.value_label(s.id),'academic_year',s.academic_year,'application_close_date',s.application_close_date,'source_url',s.source_url,
             'audience',s.audience,'nationalities',s.nationalities,'is_maximum',s.award_value_is_maximum,
             'saving_per_year',fc.scholarship_saving_amount,'saving_currency',fc.currency_code,'saving_basis',fc.fee_basis)
             order by fc.scholarship_saving_amount desc nulls last, s.name) options,
      string_agg(s.name,' ' order by s.name) semantic_text
    from scholarship.course_mappings cm join scholarship.scholarships s on s.id=cm.scholarship_id
    left join scholarship.course_financial_calculations fc on fc.mapping_id=cm.id and fc.calculation_status='calculated'
    where cm.course_id=d.course_id and cm.mapping_state='mapped'
      and s.lifecycle_status='active' and s.publication_status in ('published','internal')
      and s.audience in ('international','international_and_domestic')
  ) sc on true;

  alter table cf_search_enrichment_stage add column enrichment_content_hash text;
  update cf_search_enrichment_stage s set enrichment_content_hash=encode(extensions.digest(jsonb_build_object(
    'regulatory_state',s.regulatory_tuition_state,'regulatory_amount',s.regulatory_tuition_amount,'regulatory_currency',s.regulatory_tuition_currency,'regulatory_basis',s.regulatory_tuition_basis,
    'has_provider_current_tuition',s.has_provider_current_tuition,'provider_annual_amount',s.provider_annual_tuition_amount,'provider_annual_currency',s.provider_annual_tuition_currency,'provider_options',s.provider_tuition_options,
    'official_url',s.official_course_url,'intakes',s.intake_options,'english',s.english_requirement_options,'scholarships',s.scholarship_options,'semantic_text',s.enrichment_semantic_text
  )::text,'sha256'),'hex') where true;

  select count(*) into v_rows from cf_search_enrichment_stage;
  select count(*) into v_changed from cf_search_enrichment_stage s join search.course_documents d using(course_id) where d.enrichment_content_hash is distinct from s.enrichment_content_hash;
  select count(*) into v_unchanged from cf_search_enrichment_stage s join search.course_documents d using(course_id) where d.enrichment_content_hash is not distinct from s.enrichment_content_hash;
  select encode(extensions.digest(coalesce(string_agg(course_id::text||':'||enrichment_content_hash,'|' order by course_id::text),''),'sha256'),'hex') into v_stage_hash from cf_search_enrichment_stage;
  select jsonb_build_object(
    'regulatory_present',count(*) filter(where regulatory_tuition_state='present'),
    'regulatory_zero',count(*) filter(where regulatory_tuition_state='zero'),
    'regulatory_source_null',count(*) filter(where regulatory_tuition_state='source_null'),
    'regulatory_not_applicable',count(*) filter(where regulatory_tuition_state='not_applicable'),
    'with_provider_current_tuition',count(*) filter(where has_provider_current_tuition),
    'with_provider_annual_tuition',count(*) filter(where provider_annual_tuition_amount is not null),
    'with_official_url',count(*) filter(where official_course_url is not null),
    'with_intake',count(*) filter(where jsonb_array_length(intake_options)>0),
    'with_english',count(*) filter(where jsonb_array_length(english_requirement_options)>0),
    'with_scholarship',count(*) filter(where jsonb_array_length(scholarship_options)>0)
  ) into v_coverage from cf_search_enrichment_stage;

  if p_apply then
    update search.course_documents d set
      regulatory_tuition_state=s.regulatory_tuition_state,
      has_regulatory_tuition=s.has_regulatory_tuition,
      regulatory_tuition_amount=s.regulatory_tuition_amount,
      regulatory_tuition_currency=s.regulatory_tuition_currency,
      regulatory_tuition_basis=s.regulatory_tuition_basis,
      has_provider_current_tuition=s.has_provider_current_tuition,
      has_fee=s.has_provider_current_tuition,
      provider_annual_tuition_amount=s.provider_annual_tuition_amount,
      provider_annual_tuition_currency=s.provider_annual_tuition_currency,
      provider_tuition_options=s.provider_tuition_options,
      official_course_url=s.official_course_url,
      has_link=(s.official_course_url is not null),
      intake_options=s.intake_options,
      earliest_intake_date=s.earliest_intake_date,
      has_intake=(jsonb_array_length(s.intake_options)>0),
      english_requirement_options=s.english_requirement_options,
      has_english=(jsonb_array_length(s.english_requirement_options)>0),
      scholarship_options=s.scholarship_options,
      has_scholarship=(jsonb_array_length(s.scholarship_options)>0),
      enrichment_semantic_text=nullif(trim(s.enrichment_semantic_text),''),
      enrichment_content_hash=s.enrichment_content_hash,
      search_text=concat_ws(' ',d.course_title,d.provider_name,d.course_code,d.study_level_code,d.primary_field_name,array_to_string(d.collection_names,' '),array_to_string(d.academic_option_names,' '),d.description,nullif(trim(s.enrichment_semantic_text),'')),
      search_tsv=setweight(to_tsvector('english',coalesce(d.course_title,'')),'A') || setweight(to_tsvector('english',coalesce(d.provider_name,'')),'B') || setweight(to_tsvector('english',concat_ws(' ',coalesce(d.course_code,''),coalesce(d.study_level_code,''),coalesce(d.primary_field_name,''),coalesce(array_to_string(d.collection_names,' '),''),coalesce(array_to_string(d.academic_option_names,' '),''))),'B') || setweight(to_tsvector('english',concat_ws(' ',coalesce(d.description,''),coalesce(s.enrichment_semantic_text,''))),'C'),
      semantic_content_hash=encode(extensions.digest(jsonb_build_object('base',d.course_stable_key,'provider',d.provider_name,'title',d.course_title,'code',d.course_code,'level',d.study_level_code,'field',d.primary_field_code,'collections',d.collection_names,'academic_options',d.academic_option_names,'description',d.description,'enrichment',nullif(trim(s.enrichment_semantic_text),''))::text,'sha256'),'hex'),
      projection_version='course-v3',
      generated_at=now(),
      updated_at=now()
    from cf_search_enrichment_stage s where d.course_id=s.course_id and (d.enrichment_content_hash is distinct from s.enrichment_content_hash or d.projection_version is distinct from 'course-v3' or d.updated_at = now());
  end if;

  return jsonb_build_object('projection_version','course-v3','apply',p_apply,'rows',v_rows,'changed',v_changed,'unchanged',v_unchanged,'stage_hash',v_stage_hash,'coverage',v_coverage);
end
$_$;


ALTER FUNCTION "search"."refresh_course_enrichment_core_v1"("p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "search"."refresh_course_enrichment_scoped_v1"("p_course_ids" "uuid"[], "p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'search', 'catalogue', 'scholarship', 'pipeline', 'ref', 'extensions', 'pg_temp'
    AS $$
declare v_result jsonb;
begin
  if p_course_ids is null or cardinality(p_course_ids) = 0 then
    return jsonb_build_object('projection_version','course-v3','scope','courses','requested_courses',0,'apply',p_apply,'rows',0,'changed',0,'unchanged',0);
  end if;
  if p_apply then
    perform pg_advisory_xact_lock(hashtext('cf247:search_course_documents_writer'));  -- fixed: the one writer lock for search.course_documents (W27)
    perform 1 from search.course_documents d where d.course_id = any(p_course_ids) order by d.course_id for update;
  end if;
  v_result := search.refresh_course_enrichment_core_scoped_v1(p_course_ids, p_apply);
  if p_apply then
    update search.course_documents d
    set semantic_content_hash=encode(extensions.digest(jsonb_build_object(
      'course',d.course_stable_key,
      'provider',d.provider_name,
      'title',d.course_title,
      'code',d.course_code,
      'level',d.study_level_code,
      'field',d.primary_field_code,
      'collections',d.collection_names,
      'academic_options',d.academic_option_names,
      'description',d.description
    )::text,'sha256'),'hex')
    where d.enrichment_semantic_text is null and d.course_id = any(p_course_ids);
  end if;
  return v_result;
end
$$;


ALTER FUNCTION "search"."refresh_course_enrichment_scoped_v1"("p_course_ids" "uuid"[], "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "search"."refresh_course_enrichment_v1"("p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'search', 'extensions', 'pg_temp'
    AS $$
declare
  v_result jsonb;
begin
  v_result:=search.refresh_course_enrichment_core_v1(p_apply);
  if p_apply then
    update search.course_documents d
    set semantic_content_hash=encode(extensions.digest(jsonb_build_object(
      'course',d.course_stable_key,
      'provider',d.provider_name,
      'title',d.course_title,
      'code',d.course_code,
      'level',d.study_level_code,
      'field',d.primary_field_code,
      'collections',d.collection_names,
      'academic_options',d.academic_option_names,
      'description',d.description
    )::text,'sha256'),'hex')
    where d.enrichment_semantic_text is null;
  end if;
  return v_result;
end
$$;


ALTER FUNCTION "search"."refresh_course_enrichment_v1"("p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_autobuild_state_v1"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'adapter', (select case when not u.enabled then 'off' when u.admit then 'admitting' else 'testing' end from pipeline.uni_adapters u where u.provider_id = p_provider_id),
    'admit_fields', (select u.admit_fields from pipeline.uni_adapters u where u.provider_id = p_provider_id),
    'build', (select jsonb_build_object('id', b.id, 'status', b.status, 'note', b.note, 'error', b.error, 'result', b.result, 'created_at', b.created_at, 'updated_at', b.updated_at)
                from pipeline.adapter_autobuilds b where b.provider_id = p_provider_id order by b.created_at desc limit 1))
$$;


ALTER FUNCTION "security"."adapter_autobuild_state_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_build_admit_majors_v1"("p_provider_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int;
begin
  insert into catalogue.course_specialisations(course_id, name, source, evidence_id, page_url)
  select pg.course_id, initcap(m), 'adapter', pg.evidence_id, pg.url
    from pipeline.coverage_course_pages pg
    cross join lateral unnest(security.adapter_build_majors_v1(pg.candidates->'adapter_extra'->>'majors')) m
   where pg.provider_id = p_provider_id and pg.read_status = 'read' and pg.identity_basis is not null
     and not exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = pg.course_id and l.field = 'majors')
  on conflict do nothing;
  get diagnostics v_n = row_count;
  return v_n;
end $$;


ALTER FUNCTION "security"."adapter_build_admit_majors_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_build_fields_v1"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_min_read numeric := coalesce((security.firecrawl_setting('eval_field_share') #>> '{}')::numeric, 0.5);
  v_min_agree numeric := coalesce((security.firecrawl_setting('qualify_agree_share') #>> '{}')::numeric, 0.9);
  v_tol numeric := security.pipeline_num_v1('build.duration_tolerance_years', 0.25);
  v_pages int; v_out jsonb := '{}'::jsonb; r record; v_share numeric; v_agree numeric; v_state text; v_why text;
  u pipeline.uni_adapters%rowtype; b pipeline.adapter_builds%rowtype; v_adds int := 0;
begin
  select * into u from pipeline.uni_adapters where provider_id = p_provider_id;
  select * into b from pipeline.adapter_builds where provider_id = p_provider_id;
  -- 18 Oct 2026 (first wave): measured on the pages of active courses only (archived courses are not admitted)
  v_pages := (select count(*) from pipeline.coverage_course_pages pg join catalogue.courses c on c.id = pg.course_id and c.lifecycle_status = 'active'
               where pg.provider_id = p_provider_id and pg.read_status = 'read' and pg.identity_basis is not null);
  for r in
    with pg as (
      select pg.course_id, pg.candidates c, pg.candidates->'adapter_extra' x, true act from pipeline.coverage_course_pages pg
        join catalogue.courses c0 on c0.id = pg.course_id and c0.lifecycle_status = 'active'
       where pg.provider_id = p_provider_id and pg.read_status = 'read' and pg.identity_basis is not null),
    d as (
      select 'duration' field, count(*) filter (where y.rd) rd, count(*) filter (where y.rd and y.held and y.eq) ag, count(*) filter (where y.rd and y.held and not y.eq) df, count(*) filter (where y.rd and not y.held and y.act) nw
        from (select pg.act, pv is not null rd, c.duration_value is not null held,
                     abs(coalesce(security.adapter_build_years_v1((pv->>'value')::numeric, pv->>'unit'), -99) - coalesce(security.adapter_build_years_v1(c.duration_value, c.duration_unit), 99)) <= v_tol eq
                from pg join catalogue.courses c on c.id = pg.course_id
                cross join lateral (select security.enrich_parse_duration_v1(pg.x->>'duration') pv) z) y
      union all
      select 'study_level', count(*) filter (where y.rd), count(*) filter (where y.rd and y.held and y.eq), count(*) filter (where y.rd and y.held and not y.eq), count(*) filter (where y.rd and not y.held and y.act)
        from (select pg.act, lv.id is not null rd, c.study_level_id is not null held,
                     security.adapter_build_level_family_v1(lv.short_code) = security.adapter_build_level_family_v1(hl.short_code) eq
                from pg join catalogue.courses c on c.id = pg.course_id
                left join ref.study_levels lv on lv.id = security.enrich_parse_level_v1(coalesce(pg.x->>'study_level', pg.x->>'aqf_level'))
                left join ref.study_levels hl on hl.id = c.study_level_id) y
      union all
      select 'campus', count(*) filter (where y.rd), count(*) filter (where y.rd and y.known), count(*) filter (where y.rd and not y.known), count(*) filter (where y.rd and y.known and not y.held and y.act)
        -- 18 Oct 2026 (first wave): a campus reading agrees when it names one of the university's own campuses; a reading that names none
        -- (page navigation, "Distance and online") differs, so a university with no campus list is never Ready for campus
        from (select pg.act, v is not null rd,
                     exists (select 1 from catalogue.course_campuses cc where cc.course_id = pg.course_id) held,
                     exists (select 1 from catalogue.campuses k where k.provider_id = p_provider_id
                                and length(btrim(regexp_replace(k.name, '\s*campus\s*', ' ', 'gi'))) >= 3  -- fixed: a name shorter than this matches anything
                                and strpos(lower(v), lower(btrim(regexp_replace(k.name, '\s*campus\s*', ' ', 'gi')))) > 0) known
                from pg cross join lateral (select nullif(btrim(coalesce(pg.x->>'campus', pg.x->>'location')), '') v) z) y
      union all
      select 'majors', count(*) filter (where y.rd), count(*) filter (where y.rd and y.held and y.eq), count(*) filter (where y.rd and y.held and not y.eq), count(*) filter (where y.rd and not y.held and y.act)
        from (select pg.act, v is not null rd,
                     exists (select 1 from catalogue.course_specialisations s where s.course_id = pg.course_id and s.status = 'active') held,
                     (select coalesce(array_agg(lower(s.name) order by lower(s.name)), '{}') from catalogue.course_specialisations s where s.course_id = pg.course_id and s.status = 'active')
                       = security.adapter_build_majors_v1(v) eq
                from pg cross join lateral (select nullif(btrim(pg.x->>'majors'), '') v) z) y
      union all
      select 'intakes', count(*) filter (where y.rd and not y.ex), count(*) filter (where y.rd and not y.ex and y.held and y.eq), count(*) filter (where y.rd and not y.ex and y.held and not y.eq), count(*) filter (where y.rd and not y.ex and not y.held)
        from (select (pg.c->>'intakes_by' = 'adapter') rd, security.uni_adapter_excluded(pg.course_id, 'intakes') ex, h.itk is not null held, (h.itk = a.itk) eq
                from pg
                cross join lateral (select array_agg(distinct m order by m) itk from jsonb_array_elements_text(coalesce(pg.c->'intakes', '[]'::jsonb)) m) a
                cross join lateral (select array_agg(distinct i.intake_label order by i.intake_label) itk from catalogue.course_intakes i where i.course_id = pg.course_id and i.status = 'active') h) y
      union all
      -- 18 Oct 2026 (wave 2): a fee the admit cross-check would hold back (more than admit.fee_crosscheck_pct from the CRICOS registered
      -- course total) differs; it is not a value the click would add
      select 'fee', count(*) filter (where y.rd and not y.ex), count(*) filter (where y.rd and not y.ex and ((y.held and y.eq) or (not y.held and not y.far))),
             count(*) filter (where y.rd and not y.ex and ((y.held and not y.eq) or (not y.held and y.far))), count(*) filter (where y.rd and not y.ex and not y.held and not y.far)
        from (select (pg.c->>'fee_by' = 'adapter' and nullif(pg.c->'fee'->>'value', '') is not null) rd, security.uni_adapter_excluded(pg.course_id, 'fee') ex,
                     exists (select 1 from catalogue.course_fees f where f.course_id = pg.course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international') held,
                     exists (select 1 from catalogue.course_fees f where f.course_id = pg.course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international' and f.amount = nullif(pg.c->'fee'->>'value', '')::numeric) eq,
                     coalesce((select ck.months >= 12 and abs(ck.fee * ck.months / 12.0 - ck.reg) > security.pipeline_num_v1('admit.fee_crosscheck_pct', 25) / 100.0 * ck.reg
                                 from (select case when (pg.c->'fee'->>'value') ~ '^[0-9]+(\.[0-9]+)?$' then (pg.c->'fee'->>'value')::numeric end fee, d.regulatory_tuition_amount reg,
                                              case co.duration_unit when 'months' then co.duration_value when 'weeks' then co.duration_value * 12 / 52.0 when 'years' then co.duration_value * 12 end months  -- fixed: calendar units
                                         from search.course_documents d join catalogue.courses co on co.id = d.course_id
                                        where d.course_id = pg.course_id and d.regulatory_tuition_basis = 'registered_total_course' and d.regulatory_tuition_amount > 0) ck
                                where ck.fee is not null), false) far
                from pg) y
      union all
      select 'english', count(*) filter (where y.rd and not y.ex), count(*) filter (where y.rd and not y.ex and y.held and y.eq), count(*) filter (where y.rd and not y.ex and y.held and not y.eq), count(*) filter (where y.rd and not y.ex and not y.held)
        from (select (pg.c->>'english_by' = 'adapter' and nullif(pg.c->'english'->>'ielts_overall', '') is not null) rd, security.uni_adapter_excluded(pg.course_id, 'english') ex,
                     -- 18 Oct 2026 (wave 2): a course holding any English requirement (a policy level, another test) is held; only an IELTS score is compared
                     exists (select 1 from catalogue.course_english_requirements e2 where e2.course_id = pg.course_id and e2.status = 'active') held,
                     (h.score is null or h.score = nullif(pg.c->'english'->>'ielts_overall', '')::numeric) eq
                from pg
                cross join lateral (select max(e.overall_score) score from catalogue.course_english_requirements e join ref.english_tests t on t.id = e.english_test_id and t.code = 'IELTS' where e.course_id = pg.course_id and e.status = 'active') h) y
      union all
      select 'delivery', count(*) filter (where y.rd and not y.ex), count(*) filter (where y.rd and not y.ex and y.held and y.eq), count(*) filter (where y.rd and not y.ex and y.held and not y.eq), count(*) filter (where y.rd and not y.ex and not y.held)
        from (select (x0.mode is not null and x0.mode <> 'on_campus_and_online') rd, security.uni_adapter_excluded(pg.course_id, 'delivery') ex,
                     co.delivery_mode is not null held, (co.delivery_mode = x0.mode) eq
                from pg join catalogue.courses co on co.id = pg.course_id
                cross join lateral (select security.delivery_mode_from_text(pg.x->>'mode') mode) x0) y)
    select * from d
  loop
    v_share := case when v_pages > 0 then round(r.rd::numeric / v_pages, 3) else 0 end;
    v_agree := case when (r.ag + r.df) > 0 then round(r.ag::numeric / (r.ag + r.df), 3) end;
    v_out := v_out || jsonb_build_object(r.field, jsonb_build_object('read', r.rd, 'agree', r.ag, 'differ', r.df, 'new', r.nw, 'read_share', v_share, 'agree_share', v_agree));
  end loop;
  for r in select f, ord from unnest(array['intakes', 'fee', 'english', 'delivery', 'duration', 'campus', 'study_level', 'majors']) with ordinality t(f, ord) loop
    if not v_out ? r.f then v_out := v_out || jsonb_build_object(r.f, jsonb_build_object('read', 0, 'agree', 0, 'differ', 0, 'new', 0, 'read_share', 0, 'agree_share', null)); end if;
    v_share := (v_out->r.f->>'read_share')::numeric; v_agree := (v_out->r.f->>'agree_share')::numeric;
    if (v_out->r.f->>'read')::int = 0 then v_state := 'not_ready';
      v_why := case when u.provider_id is null then 'no adapter yet' when r.f = 'majors' and not (coalesce(u.patterns, '{}'::jsonb) ? 'majors') then 'the adapter does not read majors yet' else 'not read by the adapter' end;
    elsif v_share < v_min_read then v_state := 'review'; v_why := format('read on %s of %s pages, under the %s%% needed', v_out->r.f->>'read', v_pages, round(v_min_read * 100));
    elsif v_agree is not null and v_agree < v_min_agree then v_state := 'review';
      v_why := case when r.f = 'campus' then format('%s of %s readings name no campus the university has%s', v_out->r.f->>'differ', (v_out->r.f->>'agree')::int + (v_out->r.f->>'differ')::int,
                                                    case when not exists (select 1 from catalogue.campuses k where k.provider_id = p_provider_id) then ' (it has no campus list yet: Enrich fields can build one)' else '' end)
                    else format('%s of %s readings differ from the catalogue', v_out->r.f->>'differ', (v_out->r.f->>'agree')::int + (v_out->r.f->>'differ')::int) end;
    else v_state := 'ready'; v_why := case when (v_out->r.f->>'new')::int > 0 then format('adds %s values the catalogue does not hold', v_out->r.f->>'new') else 'agrees with the catalogue' end; end if;
    v_out := jsonb_set(v_out, array[r.f], (v_out->r.f) || jsonb_build_object('state', v_state, 'why', v_why, 'order', r.ord,
              'admitted', case when r.f in ('intakes', 'fee', 'english', 'delivery') then coalesce(u.admit, false) and r.f = any (coalesce(u.admit_fields, '{}'))
                               else coalesce(b.admitted, '{}'::jsonb) ? r.f end));
    if v_state = 'ready' then v_adds := v_adds + (v_out->r.f->>'new')::int; end if;
  end loop;
  return jsonb_build_object('provider_id', p_provider_id, 'pages_read', v_pages, 'has_adapter', u.provider_id is not null, 'fields', v_out,
    'ready', (select coalesce(jsonb_agg(k order by (v->>'order')::int), '[]'::jsonb) from jsonb_each(v_out) x(k, v) where v->>'state' = 'ready'),
    'review', (select coalesce(jsonb_agg(k order by (v->>'order')::int), '[]'::jsonb) from jsonb_each(v_out) x(k, v) where v->>'state' = 'review'),
    'not_ready', (select coalesce(jsonb_agg(k order by (v->>'order')::int), '[]'::jsonb) from jsonb_each(v_out) x(k, v) where v->>'state' = 'not_ready'),
    'adds', v_adds, 'min_read', v_min_read, 'min_agree', v_min_agree, 'measured_at', now());
end $_$;


ALTER FUNCTION "security"."adapter_build_fields_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_build_level_family_v1"("p_code" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case when p_code in ('MA', 'MC', 'MR', 'ME') then 'M' when p_code in ('CT', 'C1', 'C2', 'C3', 'C4') then 'C' else p_code end
$$;


ALTER FUNCTION "security"."adapter_build_level_family_v1"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_build_majors_v1"("p_text" "text") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(array_agg(distinct lower(btrim(m)) order by lower(btrim(m))), '{}')
    from regexp_split_to_table(coalesce(p_text, ''), '\s*(\||;|\n)\s*') m where length(btrim(m)) between 2 and 200
$$;


ALTER FUNCTION "security"."adapter_build_majors_v1"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_build_refresh_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int := 0; p uuid;
begin
  for p in select u.provider_id from pipeline.uni_adapters u left join pipeline.adapter_builds b on b.provider_id = u.provider_id
            where u.enabled order by b.checked_at nulls first, u.provider_id
            limit security.pipeline_num_v1('batch.adapter_build_readiness', 100)::int loop
    perform security.adapter_build_store_v1(p); v_n := v_n + 1;
  end loop;
  return jsonb_build_object('measured', v_n);
end $$;


ALTER FUNCTION "security"."adapter_build_refresh_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_build_store_v1"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r jsonb := security.adapter_build_fields_v1(p_provider_id);
begin
  insert into pipeline.adapter_builds(provider_id, readiness, pages_read, ready, review, not_ready, adds, checked_at, updated_at)
  values (p_provider_id, r, (r->>'pages_read')::int, jsonb_array_length(r->'ready'), jsonb_array_length(r->'review'), jsonb_array_length(r->'not_ready'), (r->>'adds')::int, now(), now())
  on conflict (provider_id) do update set readiness = excluded.readiness, pages_read = excluded.pages_read, ready = excluded.ready, review = excluded.review,
         not_ready = excluded.not_ready, adds = excluded.adds, checked_at = now(), updated_at = now();
  return r;
end $$;


ALTER FUNCTION "security"."adapter_build_store_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_build_years_v1"("p_value" numeric, "p_unit" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case lower(coalesce(p_unit, '')) when 'years' then p_value when 'months' then p_value / 12 when 'weeks' then p_value / 52  -- fixed: calendar units
                                         when 'semesters' then p_value / 2 end
$$;


ALTER FUNCTION "security"."adapter_build_years_v1"("p_value" numeric, "p_unit" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_builder_budget"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- 13 Nov 2026: the allowance, the proposals a day and the model are the route adapter_builder's (they were the settings builder_ai_daily_usd,
  -- builder_proposals_per_day and builder_model). A held route leaves no allowance.
  with today as (select (now() at time zone 'Australia/Melbourne')::date d), rt as (select security.ai_route_v1('adapter_builder') j),
  rounds as (select (p->>'cost')::numeric cost from pipeline.uni_adapter_drafts dr cross join lateral jsonb_array_elements(dr.proposals) p, today
             where ((p->>'at')::timestamptz at time zone 'Australia/Melbourne')::date = today.d)
  select jsonb_build_object('used_usd', coalesce((select sum(cost) from rounds), 0), 'proposals', (select count(*) from rounds),
                            'limit_usd', case when (rt.j->>'held')::boolean then 0 else (rt.j#>>'{cap,usd}')::numeric end,
                            'limit_proposals', case when (rt.j->>'held')::boolean then 0 else coalesce((rt.j#>>'{cap,calls}')::int, coalesce((security.firecrawl_setting('builder_proposals_per_day') #>> '{}')::int, 30)) end,
                            'model', rt.j->>'model', 'held', rt.j->>'held_reason') from rt
$$;


ALTER FUNCTION "security"."adapter_builder_budget"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_builder_model_for_v1"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- 13 Nov 2026: the model is the route adapter_builder's. A provider's own choice is kept only when the route's cascade names its model.
  -- code is the Layer 3 profile that holds the OpenRouter credential for that model (the builder's profile first).
  with rt as (select security.ai_route_v1('adapter_builder') j),
  own as (select m.code, m.model_identifier, a.set_at, a.reason
            from pipeline.uni_adapter_models a join pipeline.layer3_model_profiles m on m.code = a.profile_code, rt
           where a.provider_id = p_provider_id and m.enabled and not m.paused and m.retired_at is null
             and exists (select 1 from jsonb_array_elements(rt.j->'models') x where x->>'model_identifier' = m.model_identifier))
  select coalesce(
    (select jsonb_build_object('code', o.code, 'model', o.model_identifier, 'chosen', true, 'set_at', o.set_at, 'reason', o.reason) from own o),
    (select jsonb_build_object('code', (select p.code from pipeline.layer3_model_profiles p where p.model_identifier = rt.j->>'model' and p.retired_at is null
                                          order by (p.code = security.firecrawl_setting('builder_model_profile') #>> '{}') desc, p.enabled desc, p.code limit 1),
                               'model', rt.j->>'model', 'chosen', false) from rt))
$$;


ALTER FUNCTION "security"."adapter_builder_model_for_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_builder_models_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- 13 Nov 2026: only the models of the route adapter_builder's cascade can be chosen for a provider
  select coalesce(jsonb_agg(jsonb_build_object('code', m.code, 'model', m.model_identifier, 'max_output_tokens', m.max_output_tokens) order by m.model_identifier), '[]'::jsonb)
    from pipeline.layer3_model_profiles m
   where m.enabled and not m.paused and m.retired_at is null and m.aggregator_provider = 'openrouter'
     and 'provider_intake_validation' = any(m.allowed_task_classes)
     and exists (select 1 from jsonb_array_elements(security.ai_route_v1('adapter_builder')->'models') x where x->>'model_identifier' = m.model_identifier)
$$;


ALTER FUNCTION "security"."adapter_builder_models_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_fee_year_setting"("p_reading" "jsonb") RETURNS integer
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $_$
  select case when coalesce(p_reading->>'fee_year', '') ~ '^20[2-9][0-9]$'
               and (p_reading->>'fee_year')::int between extract(year from now() at time zone 'Australia/Melbourne')::int
                                                     and extract(year from now() at time zone 'Australia/Melbourne')::int + 1
              then (p_reading->>'fee_year')::int end
$_$;


ALTER FUNCTION "security"."adapter_fee_year_setting"("p_reading" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_overwrite_gated_v1"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare m pipeline.job_input_marks%rowtype; v_in timestamptz := security.admit_input_mark_v1(); v jsonb; v_more boolean;
        v_full int := security.pipeline_num_v1('waste.admit_full_check_hours', 6)::int;
begin
  insert into pipeline.job_input_marks(job_key) values ('adapter-overwrite') on conflict do nothing;
  select * into m from pipeline.job_input_marks where job_key = 'adapter-overwrite' for update;
  if not coalesce((m.last_result->>'more')::boolean, true) and m.last_input_at is not null and v_in <= m.last_input_at
     and m.last_full_at > now() - make_interval(hours => v_full) then
    update pipeline.job_input_marks set runs_skipped = runs_skipped + 1, last_run_at = now() where job_key = 'adapter-overwrite';
    return jsonb_build_object('skipped', 'no new input');
  end if;
  perform security.fee_crosscheck_guard_v1();  -- CF-247 15 Oct: a fee far from the registered course total is held back first
  v := security.adapter_overwrite_v1(p_limit);
  v_more := coalesce((v->>'replaced')::int, 0) >= p_limit;
  update pipeline.job_input_marks set last_input_at = v_in, last_full_at = now(), last_run_at = now(), last_result = v || jsonb_build_object('more', v_more),
         runs_done = runs_done + 1 where job_key = 'adapter-overwrite';
  return v;
end $$;


ALTER FUNCTION "security"."adapter_overwrite_gated_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_overwrite_v1"("p_limit" integer DEFAULT 200) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare r record; v_src uuid; v_ok int := 0; v_err int := 0; v_last text; v_courses uuid[] := '{}'; v_payload jsonb; v_itk text[]; v_ielts numeric; v_band numeric; v_fee numeric; v_fy int; v_cur text; v_mode_n int := 0;
begin
  for r in
    select pg.course_id, pg.provider_id, pg.url, pg.evidence_id, e.content_hash, pg.candidates c, pg.identity_basis ib, u.admit_fields af, u.reading rd, co.delivery_mode cur_mode, coalesce(security.delivery_mode_from_text(pg.candidates->'adapter_extra'->>'mode'), security.delivery_mode_from_location(coalesce(pg.candidates->'adapter_extra'->>'location', pg.candidates->'adapter_extra'->>'campus'))) new_mode,
           (select pr.registration_code from catalogue.provider_registrations pr where pr.provider_id = pg.provider_id and lower(pr.registration_scheme) = 'cricos' and coalesce(pr.status, 'active') not in ('inactive', 'cancelled', 'archived') order by pr.checked_at desc nulls last limit 1) pc,
           (select cr.registration_code from catalogue.course_registrations cr where cr.course_id = pg.course_id and lower(cr.scheme) = 'cricos' limit 1) cc,
           (select array_agg(distinct i.intake_label order by i.intake_label) from catalogue.course_intakes i where i.course_id = pg.course_id and i.status = 'active') cur_itk,
           (select r2.overall_score from catalogue.course_english_requirements r2 join ref.english_tests t on t.id = r2.english_test_id where r2.course_id = pg.course_id and t.code = 'IELTS' and coalesce(r2.status, 'active') = 'active' limit 1) cur_ielts,
           (select f.amount from catalogue.course_fees f where f.course_id = pg.course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international' order by f.fee_year desc nulls last limit 1) cur_fee,
           u.admit adm,
           (select (select array_agg(distinct z::int order by z::int) from jsonb_array_elements_text(l.cv->'months') z)
                   = (select array_agg(distinct extract(month from to_date(i.intake_label, 'Month'))::int order by extract(month from to_date(i.intake_label, 'Month'))::int)
                        from catalogue.course_intakes i where i.course_id = pg.course_id and i.status = 'active' and i.intake_label ~ '^(January|February|March|April|May|June|July|August|September|October|November|December)$')
              from (select x.candidate_value cv from pipeline.layer3_validated_readings x where x.entity_type = 'course' and x.entity_id = pg.course_id and x.status = 'validated'
                       and x.task_class = 'provider_intake_validation' and jsonb_typeof(x.candidate_value->'months') = 'array' order by x.created_at desc limit 1) l) r5_itk,
           (select (select (t->>'overall')::numeric from jsonb_array_elements(l.cv->'tests') t where t->>'test' = 'IELTS' limit 1)
                   = (select r3.overall_score from catalogue.course_english_requirements r3 join ref.english_tests t3 on t3.id = r3.english_test_id where r3.course_id = pg.course_id and t3.code = 'IELTS' and coalesce(r3.status, 'active') = 'active' limit 1)
              from (select x.candidate_value cv from pipeline.layer3_validated_readings x where x.entity_type = 'course' and x.entity_id = pg.course_id and x.status = 'validated'
                       and x.task_class = 'provider_english_validation' and jsonb_typeof(x.candidate_value->'tests') = 'array' order by x.created_at desc limit 1) l) r5_eng,
           (select abs((l.cv->>'amount')::numeric - (select f.amount from catalogue.course_fees f where f.course_id = pg.course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international' order by f.fee_year desc nulls last limit 1))
                   <= 0.01 * (l.cv->>'amount')::numeric
              from (select x.candidate_value cv from pipeline.layer3_validated_readings x where x.entity_type = 'course' and x.entity_id = pg.course_id and x.status = 'validated'
                       and x.task_class = 'provider_current_tuition_validation' and (x.candidate_value->>'amount') ~ '^[0-9]+(\.[0-9]+)?$' order by x.created_at desc limit 1) l) r5_fee
      from pipeline.coverage_course_pages pg
      join pipeline.evidence_artifacts e on e.id = pg.evidence_id
      join catalogue.courses co on co.id = pg.course_id and co.lifecycle_status = 'active'
      join pipeline.uni_adapters u on u.provider_id = pg.provider_id and u.enabled
       and (u.admit or exists (select 1 from pipeline.layer3_validated_readings l3 where l3.entity_type = 'course' and l3.entity_id = pg.course_id and l3.status = 'validated'
                                and l3.task_class in ('provider_intake_validation', 'provider_english_validation', 'provider_current_tuition_validation')))
     where pg.read_status = 'read' and pg.identity_basis is not null
       and (pg.candidates->>'intakes_by' = 'adapter' or pg.candidates->>'english_by' = 'adapter' or pg.candidates->>'fee_by' = 'adapter' or pg.candidates->'adapter_extra' ? 'mode' or pg.candidates->'adapter_extra' ? 'campus' or pg.candidates->'adapter_extra' ? 'location')
       and security.coverage_identity_allowed(pg.provider_id, pg.identity_basis, null)
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = pg.provider_id)  -- v2.15.237: paused while the provider is unpublished or archived
       and not security.layer4_entity_or_parent_blocked('course', pg.course_id, 'operational')
  loop
    exit when v_ok >= greatest(1, least(coalesce(p_limit, 200), 1000));
    v_payload := '{}'::jsonb;
    v_itk := (select array_agg(distinct m order by m) from jsonb_array_elements_text(coalesce(r.c->'intakes', '[]'::jsonb)) m);
    if r.c->>'intakes_by' = 'adapter' and v_itk is not null and r.cur_itk is distinct from v_itk
       and security.coverage_identity_allowed(r.provider_id, r.ib, 'intakes') and (('intakes' = any (r.af) and r.adm) or coalesce(r.r5_itk, false)) and not security.uni_adapter_excluded(r.course_id, 'intakes')
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = r.course_id and k.field in ('intakes', 'intake')) then
      v_payload := v_payload || jsonb_build_object('intakes', (select jsonb_agg(jsonb_build_object('intake_label', m, 'source_intake_key', lower(coalesce(r.cc, r.course_id::text)) || ':current:' || lower(m))) from unnest(v_itk) m));
    end if;
    v_ielts := nullif(r.c->'english'->>'ielts_overall', '')::numeric;
    v_band := nullif(r.c->'english'->>'ielts_min_band', '')::numeric;
    if r.c->>'english_by' = 'adapter' and v_ielts is not null and r.cur_ielts is distinct from v_ielts
       and security.coverage_identity_allowed(r.provider_id, r.ib, 'english') and (('english' = any (r.af) and r.adm) or coalesce(r.r5_eng, false)) and not security.uni_adapter_excluded(r.course_id, 'english')
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = r.course_id and k.field in ('english', 'english_requirements')) then
      v_payload := v_payload || jsonb_build_object('english_requirements', jsonb_build_array(jsonb_build_object('test_code', 'IELTS', 'overall_score', v_ielts,
                      'component_scores', case when v_band is null then '{}'::jsonb else jsonb_build_object('listening', v_band, 'reading', v_band, 'writing', v_band, 'speaking', v_band) end,
                      'notes', 'University adapter reading of the course page')));
    end if;
    -- v0.17 (Platform Admin 23:41, decision 4): the international annual fee the adapter read is admitted too
    v_fee := nullif(r.c->'fee'->>'value', '')::numeric;
    v_fy := coalesce(nullif(r.c->'fee'->>'fee_year', '')::int, security.adapter_fee_year_setting(r.rd), extract(year from now() at time zone 'Australia/Melbourne')::int);
    v_cur := coalesce(nullif(r.c->'fee'->>'currency', ''), case security.coverage_country(r.provider_id) when 'NZ' then 'NZD' when 'CA' then 'CAD' else 'AUD' end);
    if r.c->>'fee_by' = 'adapter' and v_fee is not null and v_fee between 1000 and 500000 and (select f.amount from catalogue.course_fees f where f.course_id = r.course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international' and coalesce(f.fee_year, 0) = coalesce(v_fy, 0) order by f.updated_at desc nulls last limit 1) is distinct from v_fee
       -- gate hotfix 26 Oct 2026: the fee branch checks tuition identity like the intakes and English branches, before anything is superseded
       and security.coverage_identity_allowed(r.provider_id, r.ib, 'tuition')
       and (('fee' = any (r.af) and r.adm) or coalesce(r.r5_fee, false)) and not security.uni_adapter_excluded(r.course_id, 'fee') and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = r.course_id and k.field in ('tuition', 'fee', 'fees')) then
      v_payload := v_payload || jsonb_build_object('fee_amount', v_fee, 'fee_year', v_fy, 'currency_code', v_cur, 'fee_basis', 'annual', 'audience', 'international',
                     'fee_notes', 'University adapter reading of the course page (international annual fee)',
                     'fee_key', lower(coalesce(r.cc, r.course_id::text)) || ':international:' || coalesce(v_fy::text, 'current') || ':annual');
    end if;
    -- 5 Oct (Platform Admin 11:48): delivery read from the international view of the course page
    if r.new_mode is not null and r.cur_mode is distinct from r.new_mode and ('delivery' = any (r.af) and r.adm) and not security.uni_adapter_excluded(r.course_id, 'delivery')
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = r.course_id and k.field in ('delivery_mode', 'delivery')) then
      begin
        update catalogue.courses set delivery_mode = r.new_mode, updated_at = now() where id = r.course_id;
        insert into pipeline.adapter_overwrite_changes(course_id, provider_id, field, before, after, evidence_id, page_url) values (r.course_id, r.provider_id, 'delivery', to_jsonb(r.cur_mode), to_jsonb(r.new_mode), r.evidence_id, r.url);
        v_mode_n := v_mode_n + 1; v_courses := v_courses || r.course_id;
      exception when others then v_err := v_err + 1; v_last := left(sqlerrm, 200);
      end;
    end if;
    continue when v_payload = '{}'::jsonb;
    begin
      v_src := security.coverage_sweep_source(r.provider_id);
      insert into search.enrichment_source_gates(projection_code, domain_code, source_id, gate_status, approval_ref, approved_at, created_at, updated_at)
        select 'courses', d, v_src, 'approved', 'CF-CHG-20260915-247, Decision 253, Platform Admin 4 Oct 2026 22:43 (adapter readings replace held values)', now(), now(), now()
        from unnest(array_remove(array[case when v_payload ? 'intakes' then 'course_intake' end, case when v_payload ? 'english_requirements' then 'course_english' end, case when v_payload ? 'fee_amount' then 'provider_current_tuition' end], null)) d
        where not exists (select 1 from search.enrichment_source_gates g where g.projection_code = 'courses' and g.domain_code = d and g.source_id = v_src);
      if v_payload ? 'intakes' then
        update catalogue.course_intakes set status = 'withdrawn' where course_id = r.course_id and status = 'active' and source_id is not null and intake_label <> all (v_itk);
        insert into pipeline.adapter_overwrite_changes(course_id, provider_id, field, before, after, evidence_id, page_url) values (r.course_id, r.provider_id, 'intakes', to_jsonb(r.cur_itk), to_jsonb(v_itk), r.evidence_id, r.url);
      end if;
      if v_payload ? 'english_requirements' then
        insert into pipeline.adapter_overwrite_changes(course_id, provider_id, field, before, after, evidence_id, page_url) values (r.course_id, r.provider_id, 'english_ielts', to_jsonb(r.cur_ielts), to_jsonb(v_ielts), r.evidence_id, r.url);
      end if;
      if v_payload ? 'fee_amount' then
        update catalogue.course_fees set status = 'superseded', updated_at = now() where course_id = r.course_id and status = 'active' and fee_type = 'provider_current_tuition' and audience = 'international' and source_id is not null and coalesce(fee_year, 0) = coalesce(v_fy, 0) and amount <> v_fee;
        insert into pipeline.adapter_overwrite_changes(course_id, provider_id, field, before, after, evidence_id, page_url) values (r.course_id, r.provider_id, 'fee', to_jsonb(r.cur_fee), jsonb_build_object('amount', v_fee, 'year', v_fy, 'currency', v_cur), r.evidence_id, r.url);
      end if;
      if r.pc is null or r.cc is null then
        perform security.coverage_apply_course_v1(r.course_id, v_src, r.evidence_id, r.url, r.content_hash, v_payload);
      else
        perform public.svc_coursefacts_apply_record(v_src, r.evidence_id, r.pc, r.cc, 'coverage:' || r.course_id, r.url, r.content_hash, v_payload, true);
      end if;
      update pipeline.layer4_review_items set status = 'superseded', decided_at = now() where entity_type = 'course' and entity_id = r.course_id and status = 'pending' and field_code in (case when v_payload ? 'intakes' then 'course_intake' end, case when v_payload ? 'english_requirements' then 'course_english' end, case when v_payload ? 'fee_amount' then 'course_tuition' end);
      v_ok := v_ok + 1; v_courses := v_courses || r.course_id;
    exception when others then v_err := v_err + 1; v_last := left(sqlerrm, 200);
    end;
  end loop;
  if cardinality(v_courses) > 0 then perform search.refresh_course_enrichment_scoped_v1(v_courses, true); end if;
  return jsonb_build_object('delivery', v_mode_n, 'replaced', v_ok, 'errors', v_err, 'last_error', v_last);
end $_$;


ALTER FUNCTION "security"."adapter_overwrite_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_qualify_one_v1"("p_provider_id" "uuid", "p_min_read" numeric, "p_min_agree" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_pages int; v_fields jsonb := '{}'::jsonb; v_pass text[] := '{}'; r record; v_f jsonb; v_share numeric; v_agree_share numeric; v_ok boolean; v_why text;
begin
  select count(*) into v_pages from pipeline.coverage_course_pages pg where pg.provider_id = p_provider_id and pg.read_status = 'read' and pg.identity_basis is not null;
  for r in
    with pg as (
      select pg.course_id, pg.candidates c from pipeline.coverage_course_pages pg
       where pg.provider_id = p_provider_id and pg.read_status = 'read' and pg.identity_basis is not null),
    m as (
      select 'intakes' field,
             count(*) filter (where x.rd and not x.ex) rd, count(*) filter (where x.rd and not x.ex and x.held and x.eq) ag, count(*) filter (where x.rd and not x.ex and x.held and not x.eq) df, count(*) filter (where x.rd and not x.ex and not x.held) nw, count(*) filter (where x.ex) ex, 0 un
        from (select (pg.c->>'intakes_by' = 'adapter') rd, security.uni_adapter_excluded(pg.course_id, 'intakes') ex,
                     h.itk is not null held, (h.itk = a.itk) eq
                from pg
                cross join lateral (select array_agg(distinct m order by m) itk from jsonb_array_elements_text(coalesce(pg.c->'intakes', '[]'::jsonb)) m) a
                cross join lateral (select array_agg(distinct i.intake_label order by i.intake_label) itk from catalogue.course_intakes i where i.course_id = pg.course_id and i.status = 'active') h) x
      union all
      select 'fee',
             count(*) filter (where x.rd and not x.ex), count(*) filter (where x.rd and not x.ex and x.held and x.eq), count(*) filter (where x.rd and not x.ex and x.held and not x.eq), count(*) filter (where x.rd and not x.ex and not x.held), count(*) filter (where x.ex), 0
        from (select (pg.c->>'fee_by' = 'adapter' and nullif(pg.c->'fee'->>'value', '') is not null) rd, security.uni_adapter_excluded(pg.course_id, 'fee') ex,
                     exists (select 1 from catalogue.course_fees f where f.course_id = pg.course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international') held,
                     exists (select 1 from catalogue.course_fees f where f.course_id = pg.course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international' and f.amount = nullif(pg.c->'fee'->>'value', '')::numeric) eq
                from pg) x
      union all
      select 'english',
             count(*) filter (where x.rd and not x.ex), count(*) filter (where x.rd and not x.ex and x.held and x.eq), count(*) filter (where x.rd and not x.ex and x.held and not x.eq), count(*) filter (where x.rd and not x.ex and not x.held), count(*) filter (where x.ex), 0
        from (select (pg.c->>'english_by' = 'adapter' and nullif(pg.c->'english'->>'ielts_overall', '') is not null) rd, security.uni_adapter_excluded(pg.course_id, 'english') ex,
                     h.score is not null held, (h.score = nullif(pg.c->'english'->>'ielts_overall', '')::numeric) eq
                from pg
                cross join lateral (select max(e.overall_score) score from catalogue.course_english_requirements e join ref.english_tests t on t.id = e.english_test_id and t.code = 'IELTS' where e.course_id = pg.course_id and e.status = 'active') h) x
      union all
      select 'delivery',
             count(*) filter (where x.rd and not x.ex), count(*) filter (where x.rd and not x.ex and x.held and x.eq), count(*) filter (where x.rd and not x.ex and x.held and not x.eq), count(*) filter (where x.rd and not x.ex and not x.held), count(*) filter (where x.ex), count(*) filter (where x.un and not x.ex)
        from (select (x0.mode is not null and x0.mode <> 'on_campus_and_online') rd, (x0.mode = 'on_campus_and_online') un, security.uni_adapter_excluded(pg.course_id, 'delivery') ex,
                     co.delivery_mode is not null held, (co.delivery_mode = x0.mode) eq
                from pg join catalogue.courses co on co.id = pg.course_id
                cross join lateral (select security.delivery_mode_from_text(pg.c->'adapter_extra'->>'mode') mode) x0) x)
    select * from m
  loop
    v_share := case when (v_pages - r.ex) > 0 then round(r.rd::numeric / (v_pages - r.ex), 3) else 0 end;
    v_agree_share := case when (r.ag + r.df) > 0 then round(r.ag::numeric / (r.ag + r.df), 3) else null end;
    v_ok := r.rd > 0 and v_share >= p_min_read and (v_agree_share is null or v_agree_share >= p_min_agree);
    v_why := case when r.rd = 0 then 'not read by the adapter'
                  when v_share < p_min_read then 'read on ' || r.rd || ' of ' || (v_pages - r.ex) || ' pages, under the share needed'
                  when v_agree_share is not null and v_agree_share < p_min_agree then r.df || ' of ' || (r.ag + r.df) || ' readings differ from the catalogue'
                  when r.un > 0 then 'passes, but ' || r.un || ' page(s) print a required mix the reader did not understand'
                  else 'passes' end;
    v_f := jsonb_build_object('read', r.rd, 'agree', r.ag, 'differ', r.df, 'new', r.nw, 'excluded', r.ex, 'unclear', r.un, 'read_share', v_share, 'agree_share', v_agree_share, 'pass', v_ok, 'why', v_why);
    v_fields := v_fields || jsonb_build_object(r.field, v_f);
    if v_ok then v_pass := v_pass || r.field; end if;
  end loop;
  return jsonb_build_object('pages_read', v_pages, 'fields', v_fields, 'passing', to_jsonb(v_pass));
end $$;


ALTER FUNCTION "security"."adapter_qualify_one_v1"("p_provider_id" "uuid", "p_min_read" numeric, "p_min_agree" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_shadow_found_v1"("p_task" "text", "v" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select case when v is null or jsonb_typeof(v) <> 'object' then false
              when p_task = 'intake' then jsonb_typeof(v->'months') = 'array' and jsonb_array_length(v->'months') > 0
              when p_task = 'tuition' then jsonb_typeof(v->'amount') = 'number' or (v->>'amount') ~ '^[0-9]+(\.[0-9]+)?$'
              else jsonb_typeof(v->'tests') = 'array' and jsonb_array_length(v->'tests') > 0 end
$_$;


ALTER FUNCTION "security"."adapter_shadow_found_v1"("p_task" "text", "v" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_shadow_same_v1"("p_task" "text", "a" "jsonb", "b" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when a is null or b is null then null
    when p_task = 'intake' then
      coalesce((select array_agg(distinct (m)::int order by (m)::int) from jsonb_array_elements_text(a->'months') m), '{}')
      = coalesce((select array_agg(distinct (m)::int order by (m)::int) from jsonb_array_elements_text(b->'months') m), '{}')
    when p_task = 'tuition' then
      round((a->>'amount')::numeric) = round((b->>'amount')::numeric)
      and nullif(substring(a->>'fee_year' from '[0-9]{4}'), '') is not distinct from nullif(substring(b->>'fee_year' from '[0-9]{4}'), '')
      and lower(coalesce(a->>'audience', '')) = lower(coalesce(b->>'audience', ''))
    else
      coalesce((select array_agg(distinct (t->>'test') || ':' || trim_scale((t->>'overall')::numeric)::text order by (t->>'test') || ':' || trim_scale((t->>'overall')::numeric)::text) from jsonb_array_elements(a->'tests') t), '{}')
      = coalesce((select array_agg(distinct (t->>'test') || ':' || trim_scale((t->>'overall')::numeric)::text order by (t->>'test') || ':' || trim_scale((t->>'overall')::numeric)::text) from jsonb_array_elements(b->'tests') t), '{}')
  end
$$;


ALTER FUNCTION "security"."adapter_shadow_same_v1"("p_task" "text", "a" "jsonb", "b" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adapter_shadow_summary_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with s as (select * from pipeline.adapter_shadow_settings where id = 1),
  d as (select * from pipeline.adapter_shadow_reads where status = 'done'),
  t as (
    select d.round, d.task, count(*) compared,
           count(*) filter (where d.shadow_found and d.layer3_found) both_found,
           count(*) filter (where d.agree) agree_n,
           count(*) filter (where d.shadow_found) shadow_found_n,
           count(*) filter (where d.layer3_found) layer3_found_n,
           count(*) filter (where d.shadow_found and not d.layer3_found) shadow_only,
           count(*) filter (where d.layer3_found and not d.shadow_found) layer3_only,
           round(sum(d.cost_usd), 4) shadow_cost_usd, round(sum(d.layer3_cost_usd), 4) layer3_cost_usd,
           round(avg(d.input_chars)) avg_input_chars,
           count(*) filter (where d.input_basis <> 'page') adapter_input_n
      from d group by d.round, d.task)
  select jsonb_build_object(
    'settings', (select to_jsonb(s) from s),
    'round', (select s.round from s),
    'today', (select jsonb_build_object('reads', count(*), 'cost_usd', round(coalesce(sum(cost_usd), 0), 4), 'errors', count(*) filter (where status = 'error'))
                from pipeline.adapter_shadow_reads where claimed_at >= date_trunc('day', now() at time zone 'UTC') at time zone 'UTC'),
    'fields', coalesce((select jsonb_agg(jsonb_build_object(
        'task', t.task, 'compared', t.compared, 'both_found', t.both_found, 'agree_n', t.agree_n,
        'agreement', case when t.both_found > 0 then round(t.agree_n::numeric / t.both_found, 4) end,
        'shadow_found_rate', round(t.shadow_found_n::numeric / nullif(t.compared, 0), 4),
        'layer3_found_rate', round(t.layer3_found_n::numeric / nullif(t.compared, 0), 4),
        'shadow_only', t.shadow_only, 'layer3_only', t.layer3_only,
        'shadow_cost_usd', t.shadow_cost_usd, 'layer3_cost_usd', t.layer3_cost_usd,
        'avg_input_chars', t.avg_input_chars, 'adapter_input_n', t.adapter_input_n,
        'eligible_to_retire', t.compared >= s.min_compared and t.both_found > 0
            and t.agree_n::numeric / t.both_found >= s.retire_match and t.shadow_found_n >= t.layer3_found_n) order by t.task)
      from t, s where t.round = s.round), '[]'::jsonb),
    'earlier_rounds', coalesce((select jsonb_agg(jsonb_build_object('round', t.round, 'task', t.task, 'compared', t.compared, 'both_found', t.both_found,
        'agreement', case when t.both_found > 0 then round(t.agree_n::numeric / t.both_found, 4) end,
        'shadow_found_rate', round(t.shadow_found_n::numeric / nullif(t.compared, 0), 4),
        'layer3_found_rate', round(t.layer3_found_n::numeric / nullif(t.compared, 0), 4), 'shadow_cost_usd', t.shadow_cost_usd) order by t.round, t.task)
      from t, s where t.round < s.round), '[]'::jsonb))
$$;


ALTER FUNCTION "security"."adapter_shadow_summary_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adjust_evidence_entity_link"("p_evidence_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_provider_id" "uuid", "p_delta" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
begin
  if p_evidence_id is null or p_entity_id is null or p_entity_type is null then return; end if;
  insert into pipeline.evidence_entity_links(evidence_id,entity_type,entity_id,provider_id,link_count,updated_at)
  values(p_evidence_id,p_entity_type,p_entity_id,p_provider_id,greatest(p_delta,0),now())
  on conflict(evidence_id,entity_type,entity_id) do update set provider_id=coalesce(excluded.provider_id,pipeline.evidence_entity_links.provider_id),link_count=greatest(0,pipeline.evidence_entity_links.link_count+p_delta),updated_at=now();
  delete from pipeline.evidence_entity_links where evidence_id=p_evidence_id and entity_type=p_entity_type and entity_id=p_entity_id and link_count=0;
end $$;


ALTER FUNCTION "security"."adjust_evidence_entity_link"("p_evidence_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_provider_id" "uuid", "p_delta" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."adjust_evidence_lineage_stats"("p_evidence_id" "uuid", "p_observation_delta" bigint, "p_source_null_delta" bigint, "p_rejected_delta" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
begin
  if p_evidence_id is null then return; end if;
  insert into pipeline.evidence_lineage_stats(evidence_id,observation_count,source_null_count,rejected_count,updated_at)
  values(p_evidence_id,greatest(p_observation_delta,0),greatest(p_source_null_delta,0),greatest(p_rejected_delta,0),now())
  on conflict(evidence_id) do update set
    observation_count=greatest(0,pipeline.evidence_lineage_stats.observation_count+p_observation_delta),
    source_null_count=greatest(0,pipeline.evidence_lineage_stats.source_null_count+p_source_null_delta),
    rejected_count=greatest(0,pipeline.evidence_lineage_stats.rejected_count+p_rejected_delta),
    updated_at=now();
end
$$;


ALTER FUNCTION "security"."adjust_evidence_lineage_stats"("p_evidence_id" "uuid", "p_observation_delta" bigint, "p_source_null_delta" bigint, "p_rejected_delta" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."adjust_evidence_lineage_stats"("p_evidence_id" "uuid", "p_observation_delta" bigint, "p_source_null_delta" bigint, "p_rejected_delta" bigint) IS 'Internal CF-241 Evidence lineage counter mutator. Direct browser execution revoked; maintained through governed trigger path only.';



CREATE OR REPLACE FUNCTION "security"."admin_a15_acceptance_status"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'ref', 'search', 'publishing', 'public', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_metrics jsonb;
  v_key_contacts jsonb;
  v_watch jsonb;
  v_security jsonb;
  v_authority jsonb;
  v_ok boolean;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<1 then raise exception 'assigned StudySearch role required' using errcode='42501'; end if;

  v_metrics:=jsonb_build_object(
    'profile_total',(select count(*) from pipeline.provider_contact_profiles),
    'profile_au',(select count(*) from pipeline.provider_contact_profiles p join ref.countries c on c.id=p.country_id where c.iso_alpha2='AU'),
    'profile_nz',(select count(*) from pipeline.provider_contact_profiles p join ref.countries c on c.id=p.country_id where c.iso_alpha2='NZ'),
    'profile_success',(select count(*) from pipeline.provider_contact_profiles where last_success_at is not null and last_error is null),
    'profile_errors',(select count(*) from pipeline.provider_contact_profiles where last_error is not null),
    'current_contacts',(select count(*) from pipeline.provider_contact_observations where is_current and verification_state<>'rejected'),
    'contact_providers',(select count(distinct provider_id) from pipeline.provider_contact_observations where is_current and verification_state<>'rejected'),
    'territory_contacts',(select count(*) from pipeline.provider_contact_observations where is_current and verification_state<>'rejected' and nullif(trim(territory_text),'') is not null),
    'rejected_contacts',(select count(*) from pipeline.provider_contact_observations where verification_state='rejected'),
    'email_contacts',(select count(*) from pipeline.provider_contact_observations where is_current and verification_state<>'rejected' and nullif(trim(work_email),'') is not null),
    'phone_contacts',(select count(*) from pipeline.provider_contact_observations where is_current and verification_state<>'rejected' and nullif(trim(work_phone),'') is not null),
    'reviewed_rejection_violations',(
      select count(*) from pipeline.provider_contact_observations
      where metadata ? 'a15_quality_review_at'
        and metadata ? 'a15_quality_disposition'
        and not (metadata ? 'a15_quality_reconciliation')
        and (verification_state<>'rejected' or is_current)
    )
  );

  v_key_contacts:=jsonb_build_object(
    'uow',(
      select count(*)=5
      from pipeline.provider_contact_observations o
      join catalogue.providers p on p.id=o.provider_id
      where lower(p.canonical_name)='university of wollongong'
        and o.is_current and o.verification_state='current'
        and o.metadata->>'a15_quality_reconciliation'='uow_first_party_regional_experts'
    ),
    'vu',(
      select count(*)=2
      from pipeline.provider_contact_observations o
      join catalogue.providers p on p.id=o.provider_id
      where lower(p.canonical_name)='victoria university'
        and o.is_current and o.verification_state='current'
        and o.full_name is null and o.job_title='International Student Enquiries'
        and o.team_name='VU International' and o.work_email='international@vu.edu.au'
        and o.work_phone='+61 3 9919 1164'
        and o.metadata->>'a15_quality_reconciliation'='vu_final_preferred_contact'
    ),
    'wellington',exists(
      select 1
      from pipeline.provider_contact_observations o
      join catalogue.providers p on p.id=o.provider_id
      where lower(p.canonical_name)='victoria university of wellington'
        and o.is_current and o.verification_state='current' and o.full_name is null
        and o.job_title='International Student Experience' and o.team_name='International Student Experience'
        and o.work_email='international-support@vuw.ac.nz' and o.work_phone='+64 4 463 5350'
        and o.metadata->>'a15_quality_reconciliation'='wellington_international_student_experience'
    ),
    'sydney',(
      select count(*)=4
      from pipeline.provider_contact_observations o
      join catalogue.providers p on p.id=o.provider_id
      where lower(p.canonical_name)='the university of sydney'
        and o.is_current and o.verification_state='current'
        and o.team_name='International Recruitment'
        and o.source_url='https://www.sydney.edu.au/study/applying/how-to-apply/international-students/contact-our-regional-experts.html'
        and o.metadata->>'a15_quality_reconciliation'='sydney_first_party_regional_experts'
        and (o.full_name,o.job_title,o.territory_text,o.work_email) in (
          ('Chris Lawrance','Regional Manager','Americas and Europe','chris.lawrance@sydney.edu.au'),
          ('Nishant Jadhav','Senior Regional Manager','Central Asia, South Asia, Middle East and Africa','nishant.jadhav@sydney.edu.au'),
          ('Sean Lee','Senior Regional Manager','Asia (excluding China, Hong Kong and Macau)','sean.lee@sydney.edu.au'),
          ('Sherrie Huan','Senior Regional Manager','China, Hong Kong and Macau','sherrie.huan@sydney.edu.au')
        )
    ),
    'otago',exists(
      select 1 from pipeline.provider_contact_observations o join catalogue.providers p on p.id=o.provider_id
      where lower(p.canonical_name)='university of otago'
        and o.is_current and o.verification_state='current' and o.full_name is null
        and o.job_title='International Marketing and Recruitment'
        and o.team_name='International Marketing and Recruitment'
        and o.metadata->>'a15_quality_reconciliation'='otago_team_contact'
    )
  );

  v_watch:=jsonb_build_object(
    'contact_removed_count',(select count(*) from pipeline.provider_contact_watch_events where event_type='contact_removed'),
    'contact_restored_count',(select count(*) from pipeline.provider_contact_watch_events where event_type='contact_restored'),
    'removal_supported',position('contact_removed' in pg_get_functiondef('public.provider_contact_profile_reconcile_service(uuid,text[],integer)'::regprocedure))>0,
    'restoration_supported',position('contact_restored' in pg_get_functiondef('public.provider_contact_observation_upsert_service(jsonb)'::regprocedure))>0
  );

  v_security:=jsonb_build_object(
    'rls_enabled',(
      select bool_and(c.relrowsecurity)
      from pg_class c join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='pipeline' and c.relname in (
        'provider_contact_profiles','provider_contact_observations',
        'provider_contact_watch_events','provider_contact_enrichment_attempts'
      )
    ),
    'no_direct_table_grants',not exists(
      select 1 from information_schema.role_table_grants
      where table_schema='pipeline'
        and table_name in (
          'provider_contact_profiles','provider_contact_observations',
          'provider_contact_watch_events','provider_contact_enrichment_attempts'
        )
        and grantee in ('anon','authenticated','PUBLIC')
    ),
    'service_upsert_private',
      not has_function_privilege('anon','public.provider_contact_observation_upsert_service(jsonb)','execute')
      and not has_function_privilege('authenticated','public.provider_contact_observation_upsert_service(jsonb)','execute'),
    'service_reconcile_private',
      not has_function_privilege('anon','public.provider_contact_profile_reconcile_service(uuid,text[],integer)','execute')
      and not has_function_privilege('authenticated','public.provider_contact_profile_reconcile_service(uuid,text[],integer)','execute')
  );

  v_authority:=jsonb_build_object(
    'providers',(select count(*) from catalogue.providers),
    'courses',(select count(*) from catalogue.courses),
    'search_documents',(select count(*) from search.course_documents),
    'publication_entity_states',(select count(*) from publishing.entity_states),
    'publication_events',(select count(*) from publishing.publication_events),
    'publication_approvals',(select count(*) from publishing.publication_approvals),
    'expected',jsonb_build_object(
      'providers',3085,'courses',43461,'search_documents',33105,
      'publication_entity_states',0,'publication_events',9,'publication_approvals',2
    )
  );

  v_ok:=v_metrics @> jsonb_build_object(
      'profile_total',60,'profile_au',52,'profile_nz',8,'profile_success',60,'profile_errors',0,
      'current_contacts',31,'contact_providers',11,'territory_contacts',17,'rejected_contacts',45,
      'email_contacts',30,'phone_contacts',18,'reviewed_rejection_violations',0
    )
    and coalesce((v_key_contacts->>'uow')::boolean,false)
    and coalesce((v_key_contacts->>'vu')::boolean,false)
    and coalesce((v_key_contacts->>'wellington')::boolean,false)
    and coalesce((v_key_contacts->>'sydney')::boolean,false)
    and coalesce((v_key_contacts->>'otago')::boolean,false)
    and coalesce((v_watch->>'removal_supported')::boolean,false)
    and coalesce((v_watch->>'restoration_supported')::boolean,false)
    and coalesce((v_watch->>'contact_removed_count')::integer,0)>0
    and coalesce((v_security->>'rls_enabled')::boolean,false)
    and coalesce((v_security->>'no_direct_table_grants')::boolean,false)
    and coalesce((v_security->>'service_upsert_private')::boolean,false)
    and coalesce((v_security->>'service_reconcile_private')::boolean,false)
    and (v_authority-'expected')=(v_authority->'expected');

  return jsonb_build_object(
    'ok',v_ok,
    'change_control','CF-CHG-20260829-046',
    'frozen_baseline','A15-60-profile-first-party-v1',
    'metrics',v_metrics,
    'key_contacts',v_key_contacts,
    'watch_events',v_watch,
    'security',v_security,
    'authority',v_authority,
    'canonical_mutation_authorised',false,
    'search_mutation_authorised',false,
    'publication_mutation_authorised',false
  );
end $$;


ALTER FUNCTION "security"."admin_a15_acceptance_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_automation_control_v1"("p_job" "text", "p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'cron', 'security'
    SET "statement_timeout" TO '100s'
    AS $$
declare j cron.job%rowtype; c pipeline.automation_catalogue%rowtype; v_rank int:=security.current_role_rank(); v_n int; v_every int; v_sched text; v_cmd text; r record;
begin
  -- SS-016 (Platform Admin 1 Nov 2026 21:02): the floor is rank 5, so the refusal names the PIM Admin; the boundary is unchanged
  if auth.uid() is null or v_rank<5 then raise exception 'PIM Admin role or above required to change automations. A Pipeline Operator records the issue and raises it with the PIM Admin' using errcode='42501'; end if;
  -- Pipeline Maintenance Mode (15 Nov 2026): while paused, a job can still be paused but not switched on, run or changed
  if p_action not in ('pause','pause_area') and security.maintenance_hold_v1() then
    raise exception 'The pipeline is paused for maintenance: use Resume Pipeline on Automations first' using errcode = '55000';
  end if;
  if p_action in ('pause_area','resume_area') then
    for r in select j2.jobid, j2.jobname from cron.job j2 join pipeline.automation_catalogue c2 on c2.jobname=j2.jobname where c2.area=p_args->>'area' and c2.control_rank<=v_rank
                 -- UR-07 (1 Nov 2026): an area resume never switches on a retiring or retired job
                 and not (p_action='resume_area' and exists (select 1 from pipeline.component_register cr where cr.kind='job' and cr.name=j2.jobname and cr.status in ('retiring','retired'))) loop
      perform cron.alter_job(r.jobid, active => p_action='resume_area');
      if p_action='resume_area' then perform security.job_idle_flag_person_release_v1(r.jobname, coalesce(nullif(p_args->>'reason',''),'area '||coalesce(p_args->>'area','')||' switched on')); end if;  -- D14
    end loop;
    insert into pipeline.admin_control_events(area,action,target,detail,actor) values ('automations',p_action,p_args->>'area',p_args,auth.uid());
    return security.admin_automations_read_v1();
  end if;
  select * into j from cron.job where jobname=p_job;
  if j.jobid is null then raise exception 'unknown automation'; end if;
  select * into c from pipeline.automation_catalogue where jobname=p_job;
  -- SS-016 acceptance S1 (1 Nov 2026): the refusal names the role that changes this automation; the check is unchanged
  if v_rank<coalesce(c.control_rank,6) then raise exception 'this automation is changed by the %', case when coalesce(c.control_rank,6)>=6 then 'Platform Admin' when c.control_rank=5 then 'PIM Admin' else 'Pipeline Operator or above' end using errcode='42501'; end if;
  -- UR-07 (1 Nov 2026): a retiring or retired job cannot be switched on, run or re-scheduled; it can still be paused
  if p_action <> 'pause' and exists (select 1 from pipeline.component_register cr where cr.kind='job' and cr.name=p_job and cr.status in ('retiring','retired')) then
    raise exception 'this automation is retired (%); it cannot be switched on, run or changed',
      coalesce((select 'replaced by '||cr.replaced_by from pipeline.component_register cr where cr.kind='job' and cr.name=p_job and cr.status in ('retiring','retired') and cr.replaced_by is not null limit 1), 'no replacement recorded');
  end if;
  if p_action in ('pause','resume') then
    perform cron.alter_job(j.jobid, active => p_action='resume');
    -- D14 (31 Oct 2026): a person switching the job on releases its automatic idle-pause flag, so Flags matches and the idle guard applies again
    if p_action='resume' then perform security.job_idle_flag_person_release_v1(p_job, coalesce(nullif(p_args->>'reason',''),'switched on')); end if;
  elsif p_action='run_now' then
    execute j.command;
  elsif p_action='set_every' then
    v_every:=(p_args->>'minutes')::int;
    if v_every not in (1,2,3,5,10,15,20,30,60,120,360,1440) then raise exception 'choose 1, 2, 3, 5, 10, 15, 20, 30 or 60 minutes, or 2, 6 or 24 hours'; end if;
    v_sched:=case when v_every=1 then '* * * * *'
                  when v_every<60 then (abs(hashtext(p_job))%v_every)::text||'-59/'||v_every||' * * * *'
                  when v_every=60 then (abs(hashtext(p_job))%60)::text||' * * * *'
                  when v_every=1440 then (abs(hashtext(p_job))%60)::text||' '||(abs(hashtext(p_job||'h'))%24)::text||' * * *'
                  else (abs(hashtext(p_job))%60)::text||' */'||(v_every/60)||' * * *' end;
    perform cron.alter_job(j.jobid, schedule => v_sched);
  elsif p_action='set_batch' then
    if not coalesce(c.batch_editable,false) then raise exception 'batch size cannot be changed for this automation'; end if;
    v_n:=(p_args->>'batch')::int;
    -- v2.15.269: the size lives in a setting; change the setting (its own range applies), never the job
    if j.command ~ 'pipeline_num_v1\(''' then
      v_sched:=substring(j.command from 'pipeline_num_v1\(''([^'']+)''');
      if v_n is null or exists (select 1 from pipeline.platform_toolset_settings s where s.toolset_key='pipeline' and s.key=v_sched and ((s.min_value is not null and v_n<s.min_value) or (s.max_value is not null and v_n>s.max_value))) then
        raise exception 'batch size out of range for %', v_sched; end if;
      update pipeline.platform_toolset_settings set value=to_jsonb(v_n), reason=coalesce(nullif(p_args->>'reason',''),'Automations: batch size'), updated_by=auth.uid(), updated_at=now() where toolset_key='pipeline' and key=v_sched;
      insert into pipeline.admin_control_events(area,action,target,detail,actor) values ('toolsets','setting','pipeline.'||v_sched,jsonb_build_object('after',v_n,'from','Automations'),auth.uid());
    elsif j.command ~ 'scholarship_setting\(''' then
      if v_n is null or v_n<1 or v_n>500 then raise exception 'batch size must be 1-500'; end if;
      update pipeline.scholarship_layer_settings set value=v_n where key=substring(j.command from 'scholarship_setting\(''([^'']+)''');
    else
    if v_n is null or v_n<1 or v_n>500 then raise exception 'batch size must be 1-500'; end if;
    v_cmd:=case when j.command ~ '"limit"\s*:\s*\d+' then regexp_replace(j.command,'"limit"\s*:\s*\d+','"limit":'||v_n)
                else regexp_replace(j.command,'\(\s*\d+\s*\)','('||v_n||')') end;
    perform cron.alter_job(j.jobid, command => v_cmd);
    end if;
  else raise exception 'unknown action'; end if;
  insert into pipeline.admin_control_events(area,action,target,detail,actor) values ('automations',p_action,p_job,p_args,auth.uid());
  return security.admin_automations_read_v1();
end $$;


ALTER FUNCTION "security"."admin_automation_control_v1"("p_job" "text", "p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_automations_read_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'cron', 'security'
    AS $$
begin
  if auth.uid() is null or security.current_role_rank()<3 then raise exception 'assigned StudySearch role required' using errcode='42501'; end if;
  -- v2.15.246 (Fix 4): one pass over the last 8 days of run history instead of three lookups per job (34 s, so the list failed with
  -- a server error); the last run, runs and failures in 24 hours are read from it. Jobs not yet in the catalogue are named.
  return (with r as materialized (select d.jobid, d.start_time, d.end_time, d.status, d.return_message from cron.job_run_details d where d.start_time >= now() - interval '8 days'),
               agg as (select jobid, count(*) filter (where start_time >= now() - interval '24 hours') runs_24h,
                              count(*) filter (where start_time >= now() - interval '24 hours' and status = 'failed') failed_24h, max(start_time) last_at from r group by jobid),
               last as materialized (select r.* from r join agg on agg.jobid = r.jobid and agg.last_at = r.start_time)
    select jsonb_build_object('generated_at',now(),'rank',security.current_role_rank(),
    'jobs',(select coalesce(jsonb_agg(jsonb_build_object(
        'job',j.jobname,'area',coalesce(c.area,'Other'),'sort',coalesce(c.sort,999),'label',coalesce(c.label,j.jobname),'description',coalesce(c.description,''),
        'schedule',j.schedule,'active',j.active,'control_rank',coalesce(c.control_rank,6),'catalogued',c.jobname is not null,
        'batch',case when coalesce(c.batch_editable,false) then security.automation_batch(j.command) end,
        'last',(select jsonb_build_object('at',l.start_time,'status',l.status,'seconds',round(extract(epoch from (l.end_time-l.start_time))::numeric,1),'message',case when l.status<>'succeeded' then left(l.return_message,200) end)
                  from last l where l.jobid=j.jobid limit 1),
        'runs_24h',coalesce(a.runs_24h,0),
        'failed_24h',coalesce(a.failed_24h,0),
        -- UR-07 (1 Nov 2026): a retiring or retired job says so, with its replacement and removal date
        'retirement',(select jsonb_build_object('status',cr.status,'replaced_by',cr.replaced_by,'retire_after',cr.retire_after,'note',cr.note,'purpose',cr.purpose) from pipeline.component_register cr
                       where cr.kind='job' and cr.name=j.jobname and cr.status in ('retiring','retired') limit 1)
      ) order by coalesce(c.area,'Other'), coalesce(c.sort,999), j.jobname),'[]'::jsonb) from cron.job j left join pipeline.automation_catalogue c on c.jobname=j.jobname left join agg a on a.jobid=j.jobid),
    'events',(select coalesce(jsonb_agg(jsonb_build_object('at',e.created_at,'action',e.action,'target',e.target,'detail',e.detail) order by e.created_at desc),'[]'::jsonb)
                from (select * from pipeline.admin_control_events where area='automations' order by created_at desc limit 15) e)));
end $$;


ALTER FUNCTION "security"."admin_automations_read_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_campus_detail"("p_campus_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'pipeline', 'ref', 'scholarship', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_result jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<1 then raise exception 'assigned StudySearch role required' using errcode='42501'; end if;

  select jsonb_build_object(
    'id',ca.id,'stable_key',ca.stable_key,'name',ca.name,'campus_code',ca.campus_code,
    'provider_id',ca.provider_id,'provider_name',coalesce(p.display_name,p.canonical_name),
    'country_code',co.iso_alpha2,'country_name',co.name,'subdivision_code',sd.code,'subdivision_name',sd.name,
    'city',ca.city,'address_line1',ca.address_line1,'address_line2',ca.address_line2,'postcode',ca.postcode,
    'latitude',ca.latitude,'longitude',ca.longitude,'phone',ca.phone,'website',ca.website,
    'status',ca.status,'publication_status',ca.publication_status,'valid_from',ca.valid_from,'valid_to',ca.valid_to,
    'last_verified_at',ca.last_verified_at,'created_at',ca.created_at,'updated_at',ca.updated_at,
    'source',jsonb_build_object('source_id',ca.source_id,'source_label',s.label,'source_type',s.source_type,'source_url',s.url),
    'evidence',case when e.id is null then '[]'::jsonb else jsonb_build_array(jsonb_build_object('id',e.id,'type',e.evidence_type,'source_url',e.source_url,'storage_path',e.storage_path,'content_hash',e.content_hash,'captured_at',e.captured_at)) end,
    'courses_page',coalesce((
      with base as (
        select c.id,c.stable_key,c.canonical_title,c.course_code,c.lifecycle_status,c.publication_status,cc.delivery_mode,cc.is_primary
        from catalogue.course_campuses cc join catalogue.courses c on c.id=cc.course_id
        where cc.campus_id=ca.id
      ), numbered as (select *,count(*) over() total_count from base), ordered as (
        select * from numbered order by lower(canonical_title),id limit 25
      )
      select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),'total',coalesce(max(total_count),0),'limit',25,'offset',0) from ordered o
    ),jsonb_build_object('items','[]'::jsonb,'total',0,'limit',25,'offset',0)),
    'scholarship_count',(select count(distinct ss.scholarship_id) from scholarship.scopes ss where ss.campus_id=ca.id and coalesce(ss.include_exclude,'include')='include')
  ) into v_result
  from catalogue.campuses ca
  join catalogue.providers p on p.id=ca.provider_id
  join ref.countries co on co.id=ca.country_id
  left join ref.subdivisions sd on sd.id=ca.subdivision_id
  left join pipeline.sources s on s.id=ca.source_id
  left join pipeline.evidence_artifacts e on e.id=ca.evidence_id
  where ca.id=p_campus_id;

  return coalesce(v_result,'{}'::jsonb);
end
$$;


ALTER FUNCTION "security"."admin_campus_detail"("p_campus_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_campus_page_fast"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'ref', 'public', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_limit integer:=least(greatest(coalesce(nullif(p_args->>'limit','')::integer,50),1),200);
  v_offset integer:=greatest(coalesce(nullif(p_args->>'offset','')::integer,0),0);
  v_sort text:=lower(coalesce(nullif(p_args->>'sort',''),'name'));
  v_dir text:=lower(coalesce(nullif(p_args->>'direction',''),'asc'));
  v_simple boolean;
  v_total bigint:=0;
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode='42501';
  end if;
  select security.current_role_rank() into v_rank;
  if v_rank<1 then
    raise exception 'assigned StudySearch role required' using errcode='42501';
  end if;

  v_simple :=
    nullif(trim(coalesce(p_args->>'query','')),'') is null
    and nullif(p_args->>'country_code','') is null
    and nullif(p_args->>'subdivision_code','') is null
    and nullif(p_args->>'provider_id','') is null
    and nullif(p_args->>'status','') is null
    and nullif(p_args->>'publication_status','') is null
    and v_sort in ('name','campus')
    and v_dir='asc';

  if not v_simple then
    return security.admin_catalogue_page('campuses_page',p_args);
  end if;

  select count(*) into v_total from catalogue.campuses;

  with paged as (
    select
      ca.id,ca.stable_key,ca.name,ca.campus_code,ca.provider_id,
      ca.subdivision_id,ca.city,ca.status,ca.publication_status,
      ca.last_verified_at,ca.created_at,ca.updated_at
    from catalogue.campuses ca
    order by lower(ca.name),ca.id
    limit v_limit offset v_offset
  ), enriched as (
    select
      pg.id,pg.stable_key,pg.name,pg.campus_code,pg.provider_id,
      coalesce(p.display_name,p.canonical_name) provider_name,
      co.iso_alpha2::text country_code,co.name country_name,
      sd.code subdivision_code,sd.name subdivision_name,
      pg.city,pg.status,pg.publication_status,pg.last_verified_at,pg.created_at,pg.updated_at,
      coalesce(cc.course_count,0)::int course_count
    from paged pg
    join catalogue.providers p on p.id=pg.provider_id
    join ref.countries co on co.id=p.country_id
    left join ref.subdivisions sd on sd.id=pg.subdivision_id
    left join lateral (
      select count(*)::int course_count
      from catalogue.course_campuses cc
      where cc.campus_id=pg.id
    ) cc on true
  )
  select jsonb_build_object(
    'items',coalesce(jsonb_agg(to_jsonb(e)),'[]'::jsonb),
    'total',v_total,
    'limit',v_limit,
    'offset',v_offset,
    'sort','name',
    'direction','asc',
    'execution_profile','page_first_unfiltered_v1'
  )
  into v_result
  from enriched e;

  return v_result;
end $$;


ALTER FUNCTION "security"."admin_campus_page_fast"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_catalogue_filter_options"("p_operation" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'ref', 'auth'
    AS $$
declare
  v_rank integer := 0;
  v_country text := upper(nullif(trim(coalesce(p_args->>'country_code','')),''));
  v_subdivision text := upper(nullif(trim(coalesce(p_args->>'subdivision_code','')),''));
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode='42501';
  end if;
  select security.current_role_rank() into v_rank;
  if v_rank < 1 then
    raise exception 'assigned StudySearch role required' using errcode='42501';
  end if;

  if p_operation='provider_filters' then
    return jsonb_build_object(
      'countries',coalesce((
        select jsonb_agg(jsonb_build_object('code',x.code,'name',x.name) order by x.name)
        from (
          select distinct c.iso_alpha2::text code,c.name
          from ref.countries c
          where exists(select 1 from catalogue.providers p where p.country_id=c.id)
        ) x
      ),'[]'::jsonb),
      'subdivisions',coalesce((
        select jsonb_agg(jsonb_build_object('code',x.code,'name',x.name,'type',x.subdivision_type) order by x.name)
        from (
          select distinct s.code,s.name,s.subdivision_type
          from ref.subdivisions s
          join ref.countries c on c.id=s.country_id
          where (v_country is null or c.iso_alpha2::text=v_country)
            and (
              exists(select 1 from catalogue.providers p where p.subdivision_id=s.id)
              or exists(select 1 from catalogue.campuses cp where cp.subdivision_id=s.id)
            )
        ) x
      ),'[]'::jsonb)
    );
  elsif p_operation='course_filters' then
    return jsonb_build_object(
      'countries',coalesce((
        select jsonb_agg(jsonb_build_object('code',x.code,'name',x.name) order by x.name)
        from (
          select distinct co.iso_alpha2::text code,co.name
          from catalogue.courses c
          join catalogue.providers p on p.id=c.provider_id
          join ref.countries co on co.id=p.country_id
        ) x
      ),'[]'::jsonb),
      'subdivisions',coalesce((
        select jsonb_agg(jsonb_build_object('code',x.code,'name',x.name,'type',x.subdivision_type) order by x.name)
        from (
          select distinct s.code,s.name,s.subdivision_type
          from catalogue.courses c
          join catalogue.providers p on p.id=c.provider_id
          join ref.countries co on co.id=p.country_id
          join catalogue.course_campuses cc on cc.course_id=c.id
          join catalogue.campuses cp on cp.id=cc.campus_id
          join ref.subdivisions s on s.id=cp.subdivision_id
          where (v_country is null or co.iso_alpha2::text=v_country)
        ) x
      ),'[]'::jsonb),
      'providers',coalesce((
        select jsonb_agg(jsonb_build_object('id',x.id,'name',x.name,'stable_key',x.stable_key) order by x.name)
        from (
          select distinct p.id,coalesce(p.display_name,p.canonical_name) name,p.stable_key
          from catalogue.courses c
          join catalogue.providers p on p.id=c.provider_id
          join ref.countries co on co.id=p.country_id
          where (v_country is null or co.iso_alpha2::text=v_country)
            and (v_subdivision is null or exists(
              select 1
              from catalogue.course_campuses cc
              join catalogue.campuses cp on cp.id=cc.campus_id
              join ref.subdivisions s on s.id=cp.subdivision_id
              where cc.course_id=c.id and s.code=v_subdivision
            ))
        ) x
      ),'[]'::jsonb),
      'levels',coalesce((
        select jsonb_agg(jsonb_build_object('code',x.code,'name',x.name) order by x.sort_order,x.name)
        from (
          select distinct sl.code,sl.name,sl.sort_order
          from catalogue.courses c
          join ref.study_levels sl on sl.id=c.study_level_id
          join catalogue.providers p on p.id=c.provider_id
          join ref.countries co on co.id=p.country_id
          where (v_country is null or co.iso_alpha2::text=v_country)
            and (v_subdivision is null or exists(
              select 1 from catalogue.course_campuses cc
              join catalogue.campuses cp on cp.id=cc.campus_id
              join ref.subdivisions s on s.id=cp.subdivision_id
              where cc.course_id=c.id and s.code=v_subdivision
            ))
        ) x
      ),'[]'::jsonb),
      'fields',coalesce((
        select jsonb_agg(jsonb_build_object('code',x.code,'name',x.name) order by x.name)
        from (
          select distinct fos.code,fos.name
          from catalogue.courses c
          join ref.fields_of_study fos on fos.id=c.primary_field_id
          join catalogue.providers p on p.id=c.provider_id
          join ref.countries co on co.id=p.country_id
          where (v_country is null or co.iso_alpha2::text=v_country)
            and (v_subdivision is null or exists(
              select 1 from catalogue.course_campuses cc
              join catalogue.campuses cp on cp.id=cc.campus_id
              join ref.subdivisions s on s.id=cp.subdivision_id
              where cc.course_id=c.id and s.code=v_subdivision
            ))
        ) x
      ),'[]'::jsonb),
      'delivery_modes',coalesce((
        select jsonb_agg(jsonb_build_object('code',x.code,'name',x.code) order by x.code)
        from (
          select distinct cc.delivery_mode code
          from catalogue.course_campuses cc
          join catalogue.courses c on c.id=cc.course_id
          join catalogue.providers p on p.id=c.provider_id
          join ref.countries co on co.id=p.country_id
          where cc.delivery_mode is not null and btrim(cc.delivery_mode)<>''
            and (v_country is null or co.iso_alpha2::text=v_country)
            and (v_subdivision is null or exists(
              select 1 from catalogue.course_campuses cc2
              join catalogue.campuses cp2 on cp2.id=cc2.campus_id
              join ref.subdivisions s2 on s2.id=cp2.subdivision_id
              where cc2.course_id=c.id and s2.code=v_subdivision
            ))
        ) x
      ),'[]'::jsonb)
    );
  end if;

  raise exception 'unsupported catalogue filter operation: %',p_operation using errcode='22023';
end
$$;


ALTER FUNCTION "security"."admin_catalogue_filter_options"("p_operation" "text", "p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."admin_catalogue_filter_options"("p_operation" "text", "p_args" "jsonb") IS 'CF-CHG-20260820-015 role-checked governed Provider/Course filter-option read for Admin browser UX.';



CREATE OR REPLACE FUNCTION "security"."admin_catalogue_filter_page"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'ref', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_kind text:=lower(nullif(trim(coalesce(p_args->>'filter_kind','')),''));
  v_query text:=lower(nullif(trim(coalesce(p_args->>'query','')),''));
  v_country text:=upper(nullif(trim(coalesce(p_args->>'country_code','')),''));
  v_subdivision text:=upper(nullif(trim(coalesce(p_args->>'subdivision_code','')),''));
  v_limit integer:=least(greatest(coalesce(nullif(p_args->>'limit','')::integer,10),1),10);
  v_offset integer:=greatest(coalesce(nullif(p_args->>'offset','')::integer,0),0);
  v_items jsonb:='[]'::jsonb;
  v_total integer:=0;
  v_sub_id uuid;
  v_empty text;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<1 then raise exception 'assigned StudySearch role required' using errcode='42501'; end if;
  if v_subdivision is not null then select sd.id into v_sub_id from ref.subdivisions sd where sd.code=v_subdivision; end if;

  if v_kind='country' then
    with q as (
      select distinct co.iso_alpha2::text value,co.name label,co.iso_alpha2::text meta
      from catalogue.courses c
      join catalogue.providers p on p.id=c.provider_id
      join ref.countries co on co.id=p.country_id
      where v_query is null or lower(co.name||' '||co.iso_alpha2::text) like '%'||v_query||'%'
    ), n as (select count(*) total from q),
    page as (select * from q order by lower(label),value limit v_limit offset v_offset)
    select coalesce((select jsonb_agg(jsonb_build_object('value',value,'label',label,'meta',meta) order by lower(label),value) from page),'[]'::jsonb),
           coalesce((select total from n),0)
      into v_items,v_total;

  elsif v_kind='subdivision' then
    with q as (
      select s.code value,s.name label,s.code meta
      from catalogue.courses c
      join catalogue.providers p on p.id=c.provider_id
      join ref.countries co on co.id=p.country_id
      join catalogue.course_campuses cc on cc.course_id=c.id
      join catalogue.campuses cp on cp.id=cc.campus_id
      join ref.subdivisions s on s.id=cp.subdivision_id
      where (v_country is null or co.iso_alpha2::text=v_country)
        and (v_query is null or lower(s.name||' '||s.code) like '%'||v_query||'%')
      union
      select s.code,s.name,s.code
      from catalogue.courses c
      join catalogue.providers p on p.id=c.provider_id
      join ref.countries co on co.id=p.country_id
      join ref.subdivisions s on s.id=p.subdivision_id
      where (v_country is null or co.iso_alpha2::text=v_country)
        and (v_query is null or lower(s.name||' '||s.code) like '%'||v_query||'%')
        and not exists(select 1 from catalogue.course_campuses cc join catalogue.campuses cp on cp.id=cc.campus_id
                        where cc.course_id=c.id and cp.subdivision_id is not null)
    ), n as (select count(*) total from q),
    page as (select * from q order by lower(label),value limit v_limit offset v_offset)
    select coalesce((select jsonb_agg(jsonb_build_object('value',value,'label',label,'meta',meta) order by lower(label),value) from page),'[]'::jsonb),
           coalesce((select total from n),0)
      into v_items,v_total;

  elsif v_kind='provider' then
    with q as (
      select distinct p.id::text value,coalesce(p.display_name,p.canonical_name) label,p.stable_key meta
      from catalogue.courses c
      join catalogue.providers p on p.id=c.provider_id
      join ref.countries co on co.id=p.country_id
      where (v_country is null or co.iso_alpha2::text=v_country)
        and (v_subdivision is null or exists(
          select 1 from catalogue.course_campuses cc
          join catalogue.campuses cp on cp.id=cc.campus_id
          join ref.subdivisions s on s.id=cp.subdivision_id
          where cc.course_id=c.id and s.code=v_subdivision
        ) or (p.subdivision_id=v_sub_id and not exists(
          select 1 from catalogue.course_campuses cc join catalogue.campuses cp on cp.id=cc.campus_id
          where cc.course_id=c.id and cp.subdivision_id is not null)))
        and (v_query is null or lower(coalesce(p.display_name,p.canonical_name)||' '||coalesce(p.stable_key,'')) like '%'||v_query||'%')
    ), n as (select count(*) total from q),
    page as (select * from q order by lower(label),value limit v_limit offset v_offset)
    select coalesce((select jsonb_agg(jsonb_build_object('value',value,'label',label,'meta',meta) order by lower(label),value) from page),'[]'::jsonb),
           coalesce((select total from n),0)
      into v_items,v_total;

  elsif v_kind='level' then
    with q as (
      select distinct sl.code value,sl.name label,sl.code meta,sl.sort_order
      from catalogue.courses c
      join ref.study_levels sl on sl.id=c.study_level_id
      join catalogue.providers p on p.id=c.provider_id
      join ref.countries co on co.id=p.country_id
      where (v_country is null or co.iso_alpha2::text=v_country)
        and (v_subdivision is null or exists(
          select 1 from catalogue.course_campuses cc
          join catalogue.campuses cp on cp.id=cc.campus_id
          join ref.subdivisions s on s.id=cp.subdivision_id
          where cc.course_id=c.id and s.code=v_subdivision
        ) or (p.subdivision_id=v_sub_id and not exists(
          select 1 from catalogue.course_campuses cc join catalogue.campuses cp on cp.id=cc.campus_id
          where cc.course_id=c.id and cp.subdivision_id is not null)))
        and (v_query is null or lower(sl.name||' '||sl.code) like '%'||v_query||'%')
    ), n as (select count(*) total from q),
    page as (select value,label,meta from q order by sort_order,lower(label),value limit v_limit offset v_offset)
    select coalesce((select jsonb_agg(jsonb_build_object('value',value,'label',label,'meta',meta)) from page),'[]'::jsonb),
           coalesce((select total from n),0)
      into v_items,v_total;

  elsif v_kind='field' then
    with q as (
      select distinct fos.code value,fos.name label,fos.code meta
      from catalogue.courses c
      join ref.fields_of_study fos on fos.id=c.primary_field_id
      join catalogue.providers p on p.id=c.provider_id
      join ref.countries co on co.id=p.country_id
      where (v_country is null or co.iso_alpha2::text=v_country)
        and (v_subdivision is null or exists(
          select 1 from catalogue.course_campuses cc
          join catalogue.campuses cp on cp.id=cc.campus_id
          join ref.subdivisions s on s.id=cp.subdivision_id
          where cc.course_id=c.id and s.code=v_subdivision
        ) or (p.subdivision_id=v_sub_id and not exists(
          select 1 from catalogue.course_campuses cc join catalogue.campuses cp on cp.id=cc.campus_id
          where cc.course_id=c.id and cp.subdivision_id is not null)))
        and (v_query is null or lower(fos.name||' '||fos.code) like '%'||v_query||'%')
    ), n as (select count(*) total from q),
    page as (select * from q order by lower(label),value limit v_limit offset v_offset)
    select coalesce((select jsonb_agg(jsonb_build_object('value',value,'label',label,'meta',meta) order by lower(label),value) from page),'[]'::jsonb),
           coalesce((select total from n),0)
      into v_items,v_total;

  elsif v_kind='delivery' then
    with q as (
      select m value,upper(left(replace(m,'_',' '),1))||substr(replace(m,'_',' '),2) label,null::text meta
      from (
        select distinct coalesce(nullif(btrim(c.delivery_mode),''),cc.delivery_mode) m
        from catalogue.courses c
        join catalogue.providers p on p.id=c.provider_id
        join ref.countries co on co.id=p.country_id
        left join catalogue.course_campuses cc on cc.course_id=c.id and nullif(btrim(c.delivery_mode),'') is null
        where (v_country is null or co.iso_alpha2::text=v_country)
          and (v_subdivision is null or exists(
          select 1 from catalogue.course_campuses cc2
          join catalogue.campuses cp2 on cp2.id=cc2.campus_id
          join ref.subdivisions s2 on s2.id=cp2.subdivision_id
          where cc2.course_id=c.id and s2.code=v_subdivision
        ) or (p.subdivision_id=v_sub_id and not exists(
          select 1 from catalogue.course_campuses cc2 join catalogue.campuses cp2 on cp2.id=cc2.campus_id
          where cc2.course_id=c.id and cp2.subdivision_id is not null)))
      ) x
      where m is not null and btrim(m)<>''
        and (v_query is null or lower(replace(m,'_',' ')) like '%'||v_query||'%')
    ), n as (select count(*) total from q),
    page as (select * from q order by lower(label),value limit v_limit offset v_offset)
    select coalesce((select jsonb_agg(jsonb_build_object('value',value,'label',label,'meta',meta) order by lower(label),value) from page),'[]'::jsonb),
           coalesce((select total from n),0)
      into v_items,v_total;
  elsif v_kind='university_group' then
    with q as (
      select replace(ic.code,'au_','') value,ic.name label,
             (select count(*)::int from security.university_group_provider_ids(ic.code) g) provider_count,
             (select count(*)::int from catalogue.courses c where c.provider_id in (select security.university_group_provider_ids(ic.code))) course_count
      from ref.institution_collections ic
      join ref.countries co on co.id=ic.country_id
      where ic.collection_type='university_group' and ic.status='active'
        and (v_country is null or co.iso_alpha2::text=v_country)
        and (v_query is null or lower(ic.name||' '||replace(ic.code,'au_','')) like '%'||v_query||'%')
    ), n as (select count(*) total from q),
    page as (select * from q order by lower(label),value limit v_limit offset v_offset)
    select coalesce((select jsonb_agg(jsonb_build_object('value',value,'label',label,
                       'meta',provider_count||case when provider_count=1 then ' university' else ' universities' end,
                       'count',course_count,'course_count',course_count,'provider_count',provider_count) order by lower(label),value) from page),'[]'::jsonb),
           coalesce((select total from n),0)
      into v_items,v_total;

  else
    raise exception 'unsupported catalogue filter kind: %',coalesce(v_kind,'') using errcode='22023';
  end if;

  if v_total=0 and v_query is null then
    v_empty:=case v_kind
      when 'university_group' then 'No university groups are set up for this country.'
      when 'field' then 'Field of study is not classified for this country yet.'
      when 'subdivision' then 'No regions are recorded for this country.'
      when 'delivery' then 'No delivery mode is recorded for these courses.'
      else null end;
  end if;
  return jsonb_build_object(
    'items',v_items,'total',v_total,'limit',v_limit,'offset',v_offset,
    'has_more',(v_offset+jsonb_array_length(v_items))<v_total
  )||case when v_empty is null then '{}'::jsonb else jsonb_build_object('empty_reason',v_empty) end;
end $$;


ALTER FUNCTION "security"."admin_catalogue_filter_page"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_catalogue_page"("p_operation" "text", "p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'security', 'catalogue', 'ref', 'scholarship', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_limit integer:=least(greatest(coalesce(nullif(p_args->>'limit','')::integer,50),1),200);
  v_offset integer:=greatest(coalesce(nullif(p_args->>'offset','')::integer,0),0);
  v_sort text:=lower(coalesce(nullif(p_args->>'sort',''),'name'));
  v_dir text:=case when lower(coalesce(nullif(p_args->>'direction',''),'asc'))='desc' then 'desc' else 'asc' end;
  v_result jsonb;
  v_provider_id uuid:=nullif(p_args->>'provider_id','')::uuid;
  v_has_fee boolean:=case when nullif(p_args->>'has_fee','') is null then null else (p_args->>'has_fee')::boolean end;
  v_has_intake boolean:=case when nullif(p_args->>'has_intake','') is null then null else (p_args->>'has_intake')::boolean end;
  v_has_english boolean:=case when nullif(p_args->>'has_english','') is null then null else (p_args->>'has_english')::boolean end;
  v_has_scholarship boolean:=case when nullif(p_args->>'has_scholarship','') is null then null else (p_args->>'has_scholarship')::boolean end;
  v_has_state boolean:=case when nullif(p_args->>'has_state','') is null then null else (p_args->>'has_state')::boolean end;
  v_has_link boolean:=case when nullif(p_args->>'has_link','') is null then null else (p_args->>'has_link')::boolean end;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<1 then raise exception 'assigned StudySearch role required' using errcode='42501'; end if;

  if p_operation='providers_page' then
    -- CF-247 Provider Catalogue columns (directive 9 Nov 2026): the page, its new columns, filters and sorts (v2 is retiring)
    return security.admin_providers_page_v3(p_args);
  elsif p_operation='courses_page' then
    return public.ui_courses_decision_page(v_limit,v_offset,nullif(p_args->>'query',''),nullif(p_args->>'country_code',''),nullif(p_args->>'subdivision_code',''),v_provider_id,nullif(p_args->>'level_code',''),nullif(p_args->>'field_code',''),nullif(p_args->>'delivery_mode',''),nullif(p_args->>'lifecycle_status',''),nullif(p_args->>'publication_status',''),v_has_fee,v_has_intake,v_has_english,v_has_scholarship,nullif(p_args->>'min_completeness','')::numeric,nullif(p_args->>'freshness',''),coalesce(nullif(p_args->>'sort',''),'course'),v_dir,v_has_state,v_has_link,nullif(p_args->>'university_group',''));
  elsif p_operation='scholarships_page' then
    return security.admin_scholarships_page(p_args);
  elsif p_operation='campuses_page' then
    with base as (
      select ca.id,ca.stable_key,ca.name,ca.campus_code,ca.provider_id,coalesce(p.display_name,p.canonical_name) provider_name,co.iso_alpha2::text country_code,co.name country_name,sd.code subdivision_code,sd.name subdivision_name,ca.city,ca.status,ca.publication_status,ca.last_verified_at,ca.created_at,ca.updated_at,(select count(*)::int from catalogue.course_campuses cc where cc.campus_id=ca.id) course_count
      from catalogue.campuses ca join catalogue.providers p on p.id=ca.provider_id join ref.countries co on co.id=p.country_id left join ref.subdivisions sd on sd.id=ca.subdivision_id
      where (nullif(trim(coalesce(p_args->>'query','')),'') is null or ca.name ilike '%'||trim(p_args->>'query')||'%' or coalesce(ca.campus_code,'') ilike '%'||trim(p_args->>'query')||'%' or coalesce(ca.stable_key,'') ilike '%'||trim(p_args->>'query')||'%' or coalesce(ca.city,'') ilike '%'||trim(p_args->>'query')||'%' or coalesce(p.display_name,p.canonical_name,'') ilike '%'||trim(p_args->>'query')||'%')
        and (nullif(p_args->>'country_code','') is null or co.iso_alpha2::text=upper(p_args->>'country_code'))
        and (nullif(p_args->>'subdivision_code','') is null or sd.code=upper(p_args->>'subdivision_code'))
        and (v_provider_id is null or ca.provider_id=v_provider_id)
        and (nullif(p_args->>'status','') is null or ca.status=p_args->>'status')
        and (nullif(p_args->>'publication_status','') is null or ca.publication_status=p_args->>'publication_status')
    ), numbered as (select *,count(*) over() total_count from base), ordered as (
      select * from numbered order by
        case when v_sort in ('name','campus') and v_dir='asc' then lower(name) end asc,
        case when v_sort in ('name','campus') and v_dir='desc' then lower(name) end desc,
        case when v_sort='provider' and v_dir='asc' then lower(provider_name) end asc,
        case when v_sort='provider' and v_dir='desc' then lower(provider_name) end desc,
        case when v_sort='city' and v_dir='asc' then lower(coalesce(city,'')) end asc,
        case when v_sort='city' and v_dir='desc' then lower(coalesce(city,'')) end desc,
        case when v_sort='courses' and v_dir='asc' then course_count end asc,
        case when v_sort='courses' and v_dir='desc' then course_count end desc,
        case when v_sort='modified' and v_dir='asc' then updated_at end asc,
        case when v_sort='modified' and v_dir='desc' then updated_at end desc,
        lower(name),id
      limit v_limit offset v_offset
    )
    select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),'total',coalesce(max(total_count),0),'limit',v_limit,'offset',v_offset,'sort',v_sort,'direction',v_dir) into v_result from ordered o;
    return v_result;
  else
    raise exception 'unsupported catalogue page operation: %',p_operation using errcode='22023';
  end if;
end
$$;


ALTER FUNCTION "security"."admin_catalogue_page"("p_operation" "text", "p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."admin_catalogue_page"("p_operation" "text", "p_args" "jsonb") IS 'CF-CHG-20260820-007 role-checked server-side catalogue paging/search for Admin decision grids. Course readiness uses canonical six-signal presence, not Search completeness.';



CREATE OR REPLACE FUNCTION "security"."admin_contextual_compare"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'ref', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_type text:=lower(coalesce(nullif(btrim(p_args->>'entity_type'),''),'provider'));
  v_ids uuid[];
  v_count integer:=0;
  v_items jsonb:='[]'::jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if coalesce(v_rank,0)<1 then raise exception 'catalogue reader role required' using errcode='42501'; end if;
  if v_type not in ('provider','course') then raise exception 'invalid comparison entity type' using errcode='22023'; end if;
  if jsonb_typeof(coalesce(p_args->'ids','[]'::jsonb))<>'array' then raise exception 'ids must be an array' using errcode='22023'; end if;

  begin
    select coalesce(array_agg(value::uuid order by ordinality),'{}'::uuid[])
      into v_ids
    from jsonb_array_elements_text(coalesce(p_args->'ids','[]'::jsonb)) with ordinality as z(value,ordinality);
  exception when invalid_text_representation then
    raise exception 'invalid comparison id' using errcode='22023';
  end;

  v_count:=coalesce(array_length(v_ids,1),0);
  if v_count>6 then raise exception 'maximum six comparison entities' using errcode='22023'; end if;
  if v_count=0 then
    return jsonb_build_object('entity_type',v_type,'items','[]'::jsonb,'total',0,'max_items',6);
  end if;

  if v_type='provider' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',p.id,
      'name',coalesce(p.display_name,p.canonical_name),
      'country_code',co.iso_alpha2,
      'subdivision',sd.name,
      'city',p.primary_city,
      'contextual_insights',security.admin_contextual_insights_v2('provider',p.id),
      'ranking_context',security.admin_provider_rankings(p.id,10)
    ) order by u.ord),'[]'::jsonb)
    into v_items
    from unnest(v_ids) with ordinality u(id,ord)
    join catalogue.providers p on p.id=u.id
    left join ref.countries co on co.id=p.country_id
    left join ref.subdivisions sd on sd.id=p.subdivision_id;
  else
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',c.id,
      'name',coalesce(c.display_title,c.canonical_title),
      'provider_id',p.id,
      'provider_name',coalesce(p.display_name,p.canonical_name),
      'course_code',c.course_code,
      'study_level',coalesce(sl.name,sl.code),
      'field_of_study',coalesce(f.name,f.code),
      'contextual_insights',security.admin_contextual_insights_v2('course',c.id),
      'ranking_context',security.admin_provider_rankings(p.id,10)
    ) order by u.ord),'[]'::jsonb)
    into v_items
    from unnest(v_ids) with ordinality u(id,ord)
    join catalogue.courses c on c.id=u.id
    join catalogue.providers p on p.id=c.provider_id
    left join ref.study_levels sl on sl.id=c.study_level_id
    left join ref.fields_of_study f on f.id=c.primary_field_id;
  end if;

  return jsonb_build_object(
    'entity_type',v_type,
    'items',v_items,
    'total',jsonb_array_length(v_items),
    'requested_total',v_count,
    'max_items',6,
    'authority_note','Context only. QILT/PRISMS statistics and QS/THE institutional rankings retain governed source grain; Provider rankings never become Course facts.'
  );
end
$$;


ALTER FUNCTION "security"."admin_contextual_compare"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_contextual_insights"("p_entity_type" "text", "p_entity_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'scholarship', 'ref'
    AS $$
declare
  v_rank smallint;
  v_provider uuid;
  v_course uuid;
  v_country uuid;
  v_country_code text;
  v_subdivision uuid;
  v_level uuid;
  v_field uuid;
  v_outcomes jsonb:='[]'::jsonb;
  v_flow jsonb:='[]'::jsonb;
  v_scholarships jsonb:='[]'::jsonb;
  v_outcome_count int:=0;
  v_flow_direct_count int:=0;
  v_flow_context_count int:=0;
  v_scholarship_count int:=0;
  v_flow_state text:='not_available';
  v_flow_granularity text:='none';
begin
  v_rank:=security.current_role_rank();
  if coalesce(v_rank,0)<1 then
    raise exception 'catalogue reader role required' using errcode='42501';
  end if;

  if p_entity_type='provider' then
    select p.id,p.country_id,p.subdivision_id,c.iso_alpha2
      into v_provider,v_country,v_subdivision,v_country_code
    from catalogue.providers p
    left join ref.countries c on c.id=p.country_id
    where p.id=p_entity_id;
    if v_provider is null then return '{}'::jsonb; end if;

    select count(*) into v_outcome_count
    from catalogue.provider_outcomes po
    where po.provider_id=v_provider and coalesce(po.status,'current') in ('active','current');

    select coalesce(jsonb_agg(to_jsonb(x) order by x.collection_year_to desc nulls last,x.metric_name),'[]'::jsonb)
    into v_outcomes
    from (
      select
        po.id,
        coalesce(os.source_family,case when v_country_code='AU' then 'QILT' else 'outcomes' end) source_family,
        coalesce(os.name,os.code,'Student outcomes') source_label,
        om.name metric_name,
        om.code metric_code,
        om.unit,
        po.metric_value,
        po.national_benchmark,
        po.response_count,
        po.audience,
        po.collection_year_from,
        po.collection_year_to,
        esa.name study_area,
        sl.name study_level,
        po.status,
        po.observed_at,
        po.evidence_id,
        'provider'::text granularity
      from catalogue.provider_outcomes po
      left join ref.outcome_surveys os on os.id=po.survey_id
      left join ref.outcome_metrics om on om.id=po.metric_id
      left join ref.external_study_areas esa on esa.id=po.external_study_area_id
      left join ref.study_levels sl on sl.id=po.study_level_id
      where po.provider_id=v_provider and coalesce(po.status,'current') in ('active','current')
      order by po.collection_year_to desc nulls last,po.observed_at desc nulls last,om.name
      limit 12
    ) x;

    select count(*) into v_flow_direct_count
    from catalogue.student_flow_observations sf
    where sf.provider_id=v_provider and coalesce(sf.status,'current') in ('active','current');

    if v_flow_direct_count>0 then
      v_flow_state:='direct_provider';
      v_flow_granularity:='provider';
      select coalesce(jsonb_agg(to_jsonb(x) order by x.period_end desc nulls last,x.metric_value desc nulls last),'[]'::jsonb)
      into v_flow
      from (
        select sf.id,coalesce(os.source_family,case when v_country_code='AU' then 'PRISMS' else 'student_flow' end) source_family,
               coalesce(os.name,os.code,'International student flow') source_label,
               om.name metric_name,om.code metric_code,sf.metric_value,sf.period_start,sf.period_end,sf.period_type,
               sd.name subdivision,esa.name study_area,sf.source_nationality_name nationality,
               sf.is_suppressed,sf.suppression_code,sf.status,sf.observed_at,sf.evidence_id,
               'provider'::text granularity
        from catalogue.student_flow_observations sf
        left join ref.outcome_surveys os on os.id=sf.survey_id
        left join ref.outcome_metrics om on om.id=sf.metric_id
        left join ref.subdivisions sd on sd.id=sf.subdivision_id
        left join ref.external_study_areas esa on esa.id=sf.external_study_area_id
        where sf.provider_id=v_provider and coalesce(sf.status,'current') in ('active','current')
        order by sf.period_end desc nulls last,sf.metric_value desc nulls last
        limit 10
      ) x;
    else
      select count(*) into v_flow_context_count
      from catalogue.student_flow_observations sf
      where coalesce(sf.status,'current') in ('active','current')
        and sf.subdivision_id in (
          select v_subdivision where v_subdivision is not null
          union
          select cp.subdivision_id from catalogue.campuses cp where cp.provider_id=v_provider and cp.subdivision_id is not null
        );

      if v_flow_context_count>0 then
        v_flow_state:='regional_context';
        v_flow_granularity:='regional';
        select coalesce(jsonb_agg(to_jsonb(x) order by x.period_end desc nulls last,x.metric_value desc nulls last),'[]'::jsonb)
        into v_flow
        from (
          select sf.id,coalesce(os.source_family,case when v_country_code='AU' then 'PRISMS' else 'student_flow' end) source_family,
                 coalesce(os.name,os.code,'International student flow') source_label,
                 om.name metric_name,om.code metric_code,sf.metric_value,sf.period_start,sf.period_end,sf.period_type,
                 sd.name subdivision,esa.name study_area,sf.source_nationality_name nationality,
                 sf.is_suppressed,sf.suppression_code,sf.status,sf.observed_at,sf.evidence_id,
                 'regional_context'::text granularity
          from catalogue.student_flow_observations sf
          left join ref.outcome_surveys os on os.id=sf.survey_id
          left join ref.outcome_metrics om on om.id=sf.metric_id
          left join ref.subdivisions sd on sd.id=sf.subdivision_id
          left join ref.external_study_areas esa on esa.id=sf.external_study_area_id
          where coalesce(sf.status,'current') in ('active','current')
            and sf.subdivision_id in (
              select v_subdivision where v_subdivision is not null
              union
              select cp.subdivision_id from catalogue.campuses cp where cp.provider_id=v_provider and cp.subdivision_id is not null
            )
          order by sf.period_end desc nulls last,sf.metric_value desc nulls last
          limit 10
        ) x;
      else
        v_flow_state:=case when v_country_code='AU' then 'not_mapped' else 'country_counterpart_not_available' end;
      end if;
    end if;

    select count(distinct s.id) into v_scholarship_count
    from scholarship.scholarships s
    left join scholarship.scopes sc on sc.scholarship_id=s.id and coalesce(sc.include_exclude,'include')='include'
    where coalesce(s.lifecycle_status,'active')='active'
      and (s.provider_id=v_provider or sc.provider_id=v_provider);

    select coalesce(jsonb_agg(to_jsonb(x) order by x.application_close_date nulls last,x.name),'[]'::jsonb)
    into v_scholarships
    from (
      select distinct on(s.id)
        s.id,s.name,s.scholarship_type,s.audience,s.award_value_text,s.academic_year,
        s.application_required,s.application_open_date,s.application_close_date,
        s.lifecycle_status,s.publication_status,s.source_url,s.evidence_id,
        case when exists(select 1 from scholarship.scopes sc where sc.scholarship_id=s.id and sc.provider_id=v_provider and coalesce(sc.include_exclude,'include')='include')
             then 'provider_scope' else 'provider_owner' end relationship,
        'provider'::text granularity
      from scholarship.scholarships s
      left join scholarship.scopes sc on sc.scholarship_id=s.id
      where coalesce(s.lifecycle_status,'active')='active'
        and (s.provider_id=v_provider or (sc.provider_id=v_provider and coalesce(sc.include_exclude,'include')='include'))
      order by s.id,s.application_close_date nulls last
      limit 10
    ) x;

  elsif p_entity_type='course' then
    select c.id,c.provider_id,p.country_id,coalesce(camp.subdivision_id,p.subdivision_id),pco.iso_alpha2,c.study_level_id,c.primary_field_id
      into v_course,v_provider,v_country,v_subdivision,v_country_code,v_level,v_field
    from catalogue.courses c
    join catalogue.providers p on p.id=c.provider_id
    left join ref.countries pco on pco.id=p.country_id
    left join lateral (
      select cp.subdivision_id
      from catalogue.course_campuses cc
      join catalogue.campuses cp on cp.id=cc.campus_id
      where cc.course_id=c.id and cp.subdivision_id is not null
      order by coalesce(cc.is_primary,false) desc
      limit 1
    ) camp on true
    where c.id=p_entity_id;
    if v_course is null then return '{}'::jsonb; end if;

    select count(*) into v_outcome_count
    from catalogue.provider_outcomes po
    where po.provider_id=v_provider and coalesce(po.status,'current') in ('active','current')
      and (po.study_level_id is null or v_level is null or po.study_level_id=v_level);

    select coalesce(jsonb_agg(to_jsonb(x) order by x.level_match desc,x.collection_year_to desc nulls last,x.metric_name),'[]'::jsonb)
    into v_outcomes
    from (
      select
        po.id,
        coalesce(os.source_family,case when v_country_code='AU' then 'QILT' else 'outcomes' end) source_family,
        coalesce(os.name,os.code,'Student outcomes') source_label,
        om.name metric_name,om.code metric_code,om.unit,po.metric_value,po.national_benchmark,po.response_count,
        po.audience,po.collection_year_from,po.collection_year_to,esa.name study_area,sl.name study_level,
        po.status,po.observed_at,po.evidence_id,
        case when po.study_level_id=v_level then true else false end level_match,
        'provider_context'::text granularity
      from catalogue.provider_outcomes po
      left join ref.outcome_surveys os on os.id=po.survey_id
      left join ref.outcome_metrics om on om.id=po.metric_id
      left join ref.external_study_areas esa on esa.id=po.external_study_area_id
      left join ref.study_levels sl on sl.id=po.study_level_id
      where po.provider_id=v_provider and coalesce(po.status,'current') in ('active','current')
        and (po.study_level_id is null or v_level is null or po.study_level_id=v_level)
      order by (po.study_level_id=v_level) desc,po.collection_year_to desc nulls last,po.observed_at desc nulls last,om.name
      limit 10
    ) x;

    select count(*) into v_flow_direct_count
    from catalogue.student_flow_observations sf
    where sf.course_id=v_course and coalesce(sf.status,'current') in ('active','current');

    if v_flow_direct_count>0 then
      v_flow_state:='direct_course';
      v_flow_granularity:='course';
      select coalesce(jsonb_agg(to_jsonb(x) order by x.period_end desc nulls last,x.metric_value desc nulls last),'[]'::jsonb)
      into v_flow
      from (
        select sf.id,coalesce(os.source_family,case when v_country_code='AU' then 'PRISMS' else 'student_flow' end) source_family,
               coalesce(os.name,os.code,'International student flow') source_label,om.name metric_name,om.code metric_code,
               sf.metric_value,sf.period_start,sf.period_end,sf.period_type,sd.name subdivision,esa.name study_area,
               sf.source_nationality_name nationality,sf.is_suppressed,sf.suppression_code,sf.status,sf.observed_at,sf.evidence_id,
               'course'::text granularity
        from catalogue.student_flow_observations sf
        left join ref.outcome_surveys os on os.id=sf.survey_id
        left join ref.outcome_metrics om on om.id=sf.metric_id
        left join ref.subdivisions sd on sd.id=sf.subdivision_id
        left join ref.external_study_areas esa on esa.id=sf.external_study_area_id
        where sf.course_id=v_course and coalesce(sf.status,'current') in ('active','current')
        order by sf.period_end desc nulls last,sf.metric_value desc nulls last
        limit 10
      ) x;
    else
      select count(*) into v_flow_context_count
      from catalogue.student_flow_observations sf
      where coalesce(sf.status,'current') in ('active','current')
        and sf.field_of_study_id=v_field
        and sf.subdivision_id in (
          select v_subdivision where v_subdivision is not null
          union
          select cp.subdivision_id from catalogue.course_campuses cc join catalogue.campuses cp on cp.id=cc.campus_id where cc.course_id=v_course and cp.subdivision_id is not null
        );
      if v_flow_context_count>0 then
        v_flow_state:='regional_field_context';
        v_flow_granularity:='regional_field';
        select coalesce(jsonb_agg(to_jsonb(x) order by x.period_end desc nulls last,x.metric_value desc nulls last),'[]'::jsonb)
        into v_flow
        from (
          select sf.id,coalesce(os.source_family,case when v_country_code='AU' then 'PRISMS' else 'student_flow' end) source_family,
                 coalesce(os.name,os.code,'International student flow') source_label,om.name metric_name,om.code metric_code,
                 sf.metric_value,sf.period_start,sf.period_end,sf.period_type,sd.name subdivision,esa.name study_area,
                 sf.source_nationality_name nationality,sf.is_suppressed,sf.suppression_code,sf.status,sf.observed_at,sf.evidence_id,
                 'regional_field_context'::text granularity
          from catalogue.student_flow_observations sf
          left join ref.outcome_surveys os on os.id=sf.survey_id
          left join ref.outcome_metrics om on om.id=sf.metric_id
          left join ref.subdivisions sd on sd.id=sf.subdivision_id
          left join ref.external_study_areas esa on esa.id=sf.external_study_area_id
          where coalesce(sf.status,'current') in ('active','current')
            and sf.field_of_study_id=v_field
            and sf.subdivision_id in (
              select v_subdivision where v_subdivision is not null
              union
              select cp.subdivision_id from catalogue.course_campuses cc join catalogue.campuses cp on cp.id=cc.campus_id where cc.course_id=v_course and cp.subdivision_id is not null
            )
          order by sf.period_end desc nulls last,sf.metric_value desc nulls last
          limit 10
        ) x;
      else
        select count(*) into v_flow_context_count
        from catalogue.student_flow_observations sf
        where coalesce(sf.status,'current') in ('active','current')
            and sf.subdivision_id in (
              select v_subdivision where v_subdivision is not null
              union
              select cp.subdivision_id from catalogue.course_campuses cc join catalogue.campuses cp on cp.id=cc.campus_id where cc.course_id=v_course and cp.subdivision_id is not null
              union
              select cp.subdivision_id from catalogue.campuses cp where cp.provider_id=v_provider and cp.subdivision_id is not null
            );
        select coalesce(jsonb_agg(to_jsonb(x) order by x.period_end desc nulls last,x.metric_value desc nulls last),'[]'::jsonb)
        into v_flow
        from (
          select sf.id,coalesce(os.source_family,case when v_country_code='AU' then 'PRISMS' else 'student_flow' end) source_family,
                 coalesce(os.name,os.code,'International student flow') source_label,om.name metric_name,om.code metric_code,
                 sf.metric_value,sf.period_start,sf.period_end,sf.period_type,sd.name subdivision,esa.name study_area,
                 sf.source_nationality_name nationality,sf.is_suppressed,sf.suppression_code,sf.status,sf.observed_at,sf.evidence_id,
                 'regional_context'::text granularity
          from catalogue.student_flow_observations sf
          left join ref.outcome_surveys os on os.id=sf.survey_id
          left join ref.outcome_metrics om on om.id=sf.metric_id
          left join ref.subdivisions sd on sd.id=sf.subdivision_id
          left join ref.external_study_areas esa on esa.id=sf.external_study_area_id
          where coalesce(sf.status,'current') in ('active','current')
            and sf.subdivision_id in (
              select v_subdivision where v_subdivision is not null
              union
              select cp.subdivision_id from catalogue.course_campuses cc join catalogue.campuses cp on cp.id=cc.campus_id where cc.course_id=v_course and cp.subdivision_id is not null
              union
              select cp.subdivision_id from catalogue.campuses cp where cp.provider_id=v_provider and cp.subdivision_id is not null
            )
          order by sf.period_end desc nulls last,sf.metric_value desc nulls last
          limit 10
        ) x;
        if v_flow_context_count>0 then
          v_flow_state:='regional_context';
          v_flow_granularity:='regional';
        else
          v_flow_state:=case when v_country_code='AU' then 'not_mapped' else 'country_counterpart_not_available' end;
        end if;
      end if;
    end if;

    select count(distinct s.id) into v_scholarship_count
    from scholarship.scholarships s
    where coalesce(s.lifecycle_status,'active')='active'
      and exists (
        select 1 from scholarship.scopes inc
        where inc.scholarship_id=s.id and coalesce(inc.include_exclude,'include')='include'
          and (
            inc.course_id=v_course
            or inc.provider_id=v_provider
            or (inc.study_level_id is not null and inc.study_level_id=v_level and (s.provider_id is null or s.provider_id=v_provider))
            or (inc.field_id is not null and inc.field_id=v_field and (s.provider_id is null or s.provider_id=v_provider))
            or (inc.country_id is not null and inc.country_id=v_country)
            or (inc.campus_id is not null and inc.campus_id in (select cc.campus_id from catalogue.course_campuses cc where cc.course_id=v_course))
          )
      )
      and not exists (
        select 1 from scholarship.scopes exc
        where exc.scholarship_id=s.id and exc.include_exclude='exclude'
          and (
            exc.course_id=v_course
            or exc.provider_id=v_provider
            or (exc.study_level_id is not null and exc.study_level_id=v_level)
            or (exc.field_id is not null and exc.field_id=v_field)
            or (exc.country_id is not null and exc.country_id=v_country)
            or (exc.campus_id is not null and exc.campus_id in (select cc.campus_id from catalogue.course_campuses cc where cc.course_id=v_course))
          )
      );

    select coalesce(jsonb_agg(to_jsonb(x) order by x.application_close_date nulls last,x.name),'[]'::jsonb)
    into v_scholarships
    from (
      select distinct on(s.id)
        s.id,s.name,s.scholarship_type,s.audience,s.award_value_text,s.academic_year,
        s.application_required,s.application_open_date,s.application_close_date,
        s.lifecycle_status,s.publication_status,s.source_url,s.evidence_id,
        case
          when exists(select 1 from scholarship.scopes z where z.scholarship_id=s.id and z.course_id=v_course and coalesce(z.include_exclude,'include')='include') then 'course_scope'
          when exists(select 1 from scholarship.scopes z where z.scholarship_id=s.id and z.provider_id=v_provider and coalesce(z.include_exclude,'include')='include') then 'provider_scope'
          when exists(select 1 from scholarship.scopes z where z.scholarship_id=s.id and z.study_level_id=v_level and coalesce(z.include_exclude,'include')='include') then 'study_level_scope'
          when exists(select 1 from scholarship.scopes z where z.scholarship_id=s.id and z.field_id=v_field and coalesce(z.include_exclude,'include')='include') then 'field_scope'
          else 'broader_scope'
        end relationship,
        case
          when exists(select 1 from scholarship.scopes z where z.scholarship_id=s.id and z.course_id=v_course and coalesce(z.include_exclude,'include')='include') then 'course'
          else 'contextual_eligibility'
        end granularity
      from scholarship.scholarships s
      where coalesce(s.lifecycle_status,'active')='active'
        and exists (
          select 1 from scholarship.scopes inc
          where inc.scholarship_id=s.id and coalesce(inc.include_exclude,'include')='include'
            and (
              inc.course_id=v_course or inc.provider_id=v_provider
              or (inc.study_level_id is not null and inc.study_level_id=v_level and (s.provider_id is null or s.provider_id=v_provider))
              or (inc.field_id is not null and inc.field_id=v_field and (s.provider_id is null or s.provider_id=v_provider))
              or (inc.country_id is not null and inc.country_id=v_country)
              or (inc.campus_id is not null and inc.campus_id in (select cc.campus_id from catalogue.course_campuses cc where cc.course_id=v_course))
            )
        )
        and not exists (
          select 1 from scholarship.scopes exc
          where exc.scholarship_id=s.id and exc.include_exclude='exclude'
            and (
              exc.course_id=v_course or exc.provider_id=v_provider
              or (exc.study_level_id is not null and exc.study_level_id=v_level)
              or (exc.field_id is not null and exc.field_id=v_field)
              or (exc.country_id is not null and exc.country_id=v_country)
              or (exc.campus_id is not null and exc.campus_id in (select cc.campus_id from catalogue.course_campuses cc where cc.course_id=v_course))
            )
        )
      order by s.id,s.application_close_date nulls last
      limit 10
    ) x;
  else
    raise exception 'unsupported contextual entity type' using errcode='22023';
  end if;

  return jsonb_build_object(
    'country_code',v_country_code,
    'student_outcomes',jsonb_build_object(
      'semantic_group','student_outcomes',
      'source_label',case when v_country_code='AU' then 'QILT' else 'Country outcomes / benchmark source' end,
      'relationship_state',case when v_outcome_count>0 then 'available' else case when v_country_code='AU' then 'not_mapped' else 'country_counterpart_not_available' end end,
      'granularity',case when p_entity_type='provider' then 'provider' else 'provider_context' end,
      'total',v_outcome_count,
      'items',v_outcomes
    ),
    'student_flow',jsonb_build_object(
      'semantic_group','international_student_flow',
      'source_label',case when v_country_code='AU' then 'PRISMS' else 'Country student-flow source' end,
      'relationship_state',v_flow_state,
      'granularity',v_flow_granularity,
      'direct_total',v_flow_direct_count,
      'context_total',v_flow_context_count,
      'items',v_flow
    ),
    'scholarships',jsonb_build_object(
      'semantic_group','scholarships_funding',
      'source_label','Scholarships',
      'relationship_state',case when v_scholarship_count>0 then 'available' else 'none_related' end,
      'granularity',case when p_entity_type='provider' then 'provider' else 'governed_scope' end,
      'total',v_scholarship_count,
      'items',v_scholarships
    ),
    'authority_note','Context only. Provider/regional statistics are not Course facts and do not authorise Search or Publication mutation.'
  );
end $$;


ALTER FUNCTION "security"."admin_contextual_insights"("p_entity_type" "text", "p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_contextual_insights_v2"("p_entity_type" "text", "p_entity_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'scholarship', 'ref', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_provider uuid;
  v_level uuid;
  v_country_code text;
  v_items jsonb:='[]'::jsonb;
  v_total integer:=0;
  v_base jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if coalesce(v_rank,0)<1 then raise exception 'catalogue reader role required' using errcode='42501'; end if;

  v_base:=security.admin_contextual_insights(p_entity_type,p_entity_id);

  if p_entity_type='provider' then
    select p.id,co.iso_alpha2 into v_provider,v_country_code
    from catalogue.providers p left join ref.countries co on co.id=p.country_id
    where p.id=p_entity_id;
  elsif p_entity_type='course' then
    select c.provider_id,c.study_level_id,co.iso_alpha2 into v_provider,v_level,v_country_code
    from catalogue.courses c
    join catalogue.providers p on p.id=c.provider_id
    left join ref.countries co on co.id=p.country_id
    where c.id=p_entity_id;
  else
    raise exception 'unsupported contextual entity type' using errcode='22023';
  end if;

  if v_provider is null then return v_base; end if;

  select count(*) into v_total
  from catalogue.provider_outcomes po
  where po.provider_id=v_provider
    and coalesce(po.status,'current') in ('active','current')
    and (p_entity_type='provider' or po.study_level_id is null or v_level is null or po.study_level_id=v_level);

  select coalesce(jsonb_agg(jsonb_strip_nulls(to_jsonb(x)) order by x.level_match desc,x.collection_year_to desc nulls last,x.metric_name),'[]'::jsonb)
  into v_items
  from (
    select
      po.id,
      coalesce(os.source_family,case when v_country_code='AU' then 'QILT' else 'outcomes' end) source_family,
      coalesce(os.name,os.code,'Student outcomes') source_label,
      os.code survey_code,
      om.name metric_name,
      om.code metric_code,
      om.unit,
      po.metric_value,
      po.national_benchmark,
      po.response_count,
      po.confidence_low,
      po.confidence_high,
      po.audience,
      po.collection_year_from,
      po.collection_year_to,
      po.source_cohort_code,
      esa.name study_area,
      esa.external_code study_area_code,
      coalesce(sl.name,case po.source_cohort_code when 'UG' then 'Undergraduate' when 'PGC' then 'Postgraduate coursework' when 'PGR' then 'Postgraduate research' else null end) study_level,
      coalesce(sl.code,po.source_cohort_code) study_level_code,
      po.status,
      po.observed_at,
      po.evidence_id,
      case when p_entity_type='course' and po.study_level_id=v_level then true else false end level_match,
      case when p_entity_type='provider' then 'provider' else 'provider_context' end granularity
    from catalogue.provider_outcomes po
    left join ref.outcome_surveys os on os.id=po.survey_id
    left join ref.outcome_metrics om on om.id=po.metric_id
    left join ref.external_study_areas esa on esa.id=po.external_study_area_id
    left join ref.study_levels sl on sl.id=po.study_level_id
    where po.provider_id=v_provider
      and coalesce(po.status,'current') in ('active','current')
      and (p_entity_type='provider' or po.study_level_id is null or v_level is null or po.study_level_id=v_level)
    order by
      case when p_entity_type='course' and po.study_level_id=v_level then 1 else 0 end desc,
      po.collection_year_to desc nulls last,
      po.observed_at desc nulls last,
      om.name
    limit 60
  ) x;

  v_base:=jsonb_set(v_base,'{student_outcomes,items}',v_items,true);
  v_base:=jsonb_set(v_base,'{student_outcomes,total}',to_jsonb(v_total),true);
  v_base:=jsonb_set(v_base,'{student_outcomes,granularity}',to_jsonb(case when p_entity_type='provider' then 'provider' else 'provider_context' end),true);
  return v_base;
end
$$;


ALTER FUNCTION "security"."admin_contextual_insights_v2"("p_entity_type" "text", "p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_course_coverage_read"("p_operation" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security', 'auth'
    AS $$
declare v_tier text:=nullif(p_args->>'tier',''); v jsonb;
  v_cstate text:=nullif(p_args->>'completeness_state','');
  -- Decision 213: country (ISO code) and provider filters
  v_country text:=upper(nullif(btrim(coalesce(p_args->>'country','')),''));
  v_provider uuid:=nullif(p_args->>'provider','')::uuid;
  c_states constant text[]:=array['present','source_null','not_applicable','zero','suppressed','not_yet_enriched','stale','ambiguous','rejected'];
  -- CF-247 21 Oct 2026: every course field of the field register, in its order (was a fixed list of 7)
  c_attrs text[]:=array(select f.field from pipeline.field_register f where f.level='course' and f.active order by f.sort);
begin
  if auth.uid() is null or security.current_role_rank()<1 then raise exception 'assigned StudySearch role required' using errcode='42501'; end if;
  if p_operation='course_coverage_providers' then
    return coalesce((select jsonb_agg(jsonb_build_object('id',q.provider_id,'name',q.name,'country',q.country_code,'courses',q.n) order by q.n desc, q.name)
      from (select x.provider_id, max(coalesce(p.display_name,p.canonical_name)) name, max(x.country_code) country_code, count(*) n
              from pipeline.course_completeness x join catalogue.providers p on p.id=x.provider_id
             where (v_country is null or x.country_code=v_country)
               and (coalesce(p_args->>'query','')='' or coalesce(p.display_name,p.canonical_name) ilike '%'||(p_args->>'query')||'%' or p.canonical_name ilike '%'||(p_args->>'query')||'%')
             group by x.provider_id order by count(*) desc limit 30) q),'[]'::jsonb);
  elsif p_operation='course_coverage' and exists (select 1 from pipeline.course_coverage_snapshot s where s.id=1) then
    -- CF-247 W34 (30 Oct 2026, Platform Admin 06:53): the totals come from the derived snapshot pipeline.course_coverage_totals, rebuilt by
    -- job course-coverage-snapshot after an hourly source build changes (security.course_coverage_snapshot_refresh_v1), never on open.
    -- The same answer as the live re-total below (kept only for a database with no snapshot yet), plus 'snapshot': when it was built and
    -- last checked against the sources, and whether it is stale. Trends and the provider name stay live (small tables); the drill-downs
    -- (course_coverage_courses, course_coverage_providers) stay live and exact. The role check above is unchanged.
    declare v_stale_min int:=greatest(security.pipeline_num_v1('snapshot.course_coverage_stale_minutes',30)::int,1);
    begin
      with t as (select * from pipeline.course_coverage_totals x
                  where (v_tier is null or x.tier=v_tier) and (v_country is null or x.country_code=v_country) and (v_provider is null or x.provider_id=v_provider)),
           h as (select * from pipeline.course_coverage_snapshot where id=1)
      select jsonb_build_object(
        'computed_at',(select h.source_computed_at from h),
        'courses',(select coalesce(sum(t.n),0) from t where t.kind='group'),
        'providers',(select count(distinct t.provider_id) from t where t.kind='group'),
        'tier',v_tier,'country',v_country,
        'provider',case when v_provider is null then null else (select jsonb_build_object('id',p.id,'name',coalesce(p.display_name,p.canonical_name)) from catalogue.providers p where p.id=v_provider) end,
        'countries',(select jsonb_agg(jsonb_build_object('code',country_code,'courses',n,'providers',pn) order by n desc, country_code) from (
            select x.country_code, sum(x.n) n, count(distinct x.provider_id) pn from pipeline.course_coverage_totals x where x.kind='completeness' group by 1) k),
        'attributes',(select jsonb_agg(jsonb_build_object('attribute',attribute,'states',states,'total',total) order by ord) from (
            select attribute, jsonb_object_agg(state,n) states, sum(n) total, min(array_position(c_attrs,attribute)) ord
              from (select t.attribute,t.state,sum(t.n) n from t where t.kind='attr' group by 1,2) s group by attribute) x),
        'tiers',(select jsonb_agg(jsonb_build_object('tier',tier,'courses',n,'providers',p) order by tier) from (
            select x.tier, sum(x.n) n, count(distinct x.provider_id) p from pipeline.course_coverage_totals x
             where x.kind='group' and (v_country is null or x.country_code=v_country) group by x.tier) t2),
        -- daily history has no provider dimension: no attribute trend for one provider
        'trend',case when v_provider is null then (select jsonb_agg(jsonb_build_object('date',snapshot_date,'attribute',attribute,'admitted',adm,'total',tot) order by snapshot_date, attribute) from (
            select snapshot_date, attribute, sum(courses) filter (where state='admitted') adm, sum(courses) tot
              from pipeline.course_coverage_daily_by_country where snapshot_date>=current_date-60 and (v_tier is null or tier=v_tier) and (v_country is null or country_code=v_country) group by 1,2) d) end,
        'completeness_states',(select jsonb_agg(jsonb_build_object('attribute',attribute,'states',
              (select jsonb_object_agg(k, coalesce((cs->>k)::int,0)) from unnest(c_states) k),'total',total) order by ord) from (
            select attribute, jsonb_object_agg(cstate,n) cs, sum(n) total, min(array_position(c_attrs,attribute)) ord
              from (select attribute, security.coverage_completeness_state(state) cstate, sum(n) n from (
                      select t.attribute,t.state,sum(t.n) n from t where t.kind='attr' group by 1,2) s0
                    group by 1,2) s group by attribute) x),
        'field_sources',(select jsonb_agg(jsonb_build_object('field',z.field,'source',z.src,'courses',z.n) order by z.field,z.src) from (
            select t.attribute field, t.state src, sum(t.n) n from t where t.kind='source' group by 1,2) z),
        'field_sources_at',(select h.field_sources_at from h),
        'completeness_state_map',(select jsonb_object_agg(s, security.coverage_completeness_state(s))
            from unnest(array['admitted','candidate','in_review','awaiting_l3','not_on_page','in_queue','blocked','page_found','site_known','no_website','missing_l1','no_reader']) s),
        'completeness',(select jsonb_build_object(
              'computed_at',max(c.max_computed_at),
              'courses',coalesce(sum(c.n),0),
              'attributes',max(c.attributes),
              'completeness',round(sum(c.sum_completeness)/nullif(sum(c.n),0),1),
              'accounted_pct',round(sum(c.sum_accounted)/nullif(sum(c.n),0),1),
              'fully_complete',coalesce(sum(c.n) filter (where c.admitted=c.attributes),0),
              'by_admitted',(select jsonb_agg(jsonb_build_object('admitted',b.admitted,'courses',b.n) order by b.admitted) from (
                  select c2.admitted, sum(c2.n) n from t c2 where c2.kind='completeness' group by 1) b),
              'trend',case when v_tier is null then (select jsonb_agg(jsonb_build_object('date',d.snapshot_date,'courses',d.courses,'completeness',d.completeness,
                          'accounted_pct',d.accounted_pct,'fully_complete',d.fully_complete,'computed_at',d.computed_at) order by d.snapshot_date)
                        from pipeline.completeness_daily d where d.snapshot_date>=current_date-60
                         and case when v_provider is not null then d.scope='provider' and d.scope_id=v_provider
                                  when v_country is not null then d.scope='country:'||v_country
                                  else d.scope='platform' end) end)
            from t c where c.kind='completeness'),
        'snapshot',(select jsonb_build_object('source','snapshot','generated_at',h.generated_at,'checked_at',h.checked_at,
              'source_computed_at',h.source_computed_at,'completeness_computed_at',h.completeness_computed_at,'field_sources_at',h.field_sources_at,
              'stale_after_minutes',v_stale_min,'stale',h.checked_at < now() - make_interval(mins => v_stale_min)) from h)
      ) into v;
      return v;
    end;
  elsif p_operation='course_coverage' then
    with a as (select * from pipeline.course_attribute_coverage x
                where (v_tier is null or x.tier=v_tier) and (v_country is null or x.country_code=v_country) and (v_provider is null or x.provider_id=v_provider)),
         cc as (select * from pipeline.course_completeness x
                where (v_tier is null or x.tier=v_tier) and (v_country is null or x.country_code=v_country) and (v_provider is null or x.provider_id=v_provider))
    select jsonb_build_object(
      'computed_at',(select max(computed_at) from pipeline.course_attribute_coverage),
      'courses',(select count(distinct course_id) from a),
      'providers',(select count(distinct provider_id) from a),
      'tier',v_tier,'country',v_country,
      'provider',case when v_provider is null then null else (select jsonb_build_object('id',p.id,'name',coalesce(p.display_name,p.canonical_name)) from catalogue.providers p where p.id=v_provider) end,
      'countries',(select jsonb_agg(jsonb_build_object('code',country_code,'courses',n,'providers',pn) order by n desc) from (
          select country_code, count(*) n, count(distinct provider_id) pn from pipeline.course_completeness group by 1) k),
      'attributes',(select jsonb_agg(jsonb_build_object('attribute',attribute,'states',states,'total',total) order by ord) from (
          select attribute, jsonb_object_agg(state,n) states, sum(n) total, min(array_position(c_attrs,attribute)) ord
            from (select attribute,state,count(*) n from a group by 1,2) s group by attribute) x),
      'tiers',(select jsonb_agg(jsonb_build_object('tier',tier,'courses',n,'providers',p) order by tier) from (
          select tier, count(distinct course_id) n, count(distinct provider_id) p from pipeline.course_attribute_coverage
           where (v_country is null or country_code=v_country) group by tier) t),
      -- daily history has no provider dimension: no attribute trend for one provider
      'trend',case when v_provider is null then (select jsonb_agg(jsonb_build_object('date',snapshot_date,'attribute',attribute,'admitted',adm,'total',tot) order by snapshot_date, attribute) from (
          select snapshot_date, attribute, sum(courses) filter (where state='admitted') adm, sum(courses) tot
            from pipeline.course_coverage_daily_by_country where snapshot_date>=current_date-60 and (v_tier is null or tier=v_tier) and (v_country is null or country_code=v_country) group by 1,2) d) end,
      'completeness_states',(select jsonb_agg(jsonb_build_object('attribute',attribute,'states',
            (select jsonb_object_agg(k, coalesce((cs->>k)::int,0)) from unnest(c_states) k),'total',total) order by ord) from (
          select attribute, jsonb_object_agg(cstate,n) cs, sum(n) total, min(array_position(c_attrs,attribute)) ord
            from (select attribute, security.coverage_completeness_state(state) cstate, sum(n) n from (
                    select attribute,state,count(*) n from a group by 1,2) s0
                  group by 1,2) s group by attribute) x),
      -- Who supplied intakes, English and fees (adapter, central page, reader, hand-entered, other, or missing); snapshot rebuilt hourly.
      'field_sources',(select jsonb_agg(jsonb_build_object('field',z.field,'source',z.src,'courses',z.n) order by z.field,z.src) from (
          select 'intakes' field, s.intakes_src src, count(*) n from pipeline.course_field_source s where (v_tier is null or s.tier=v_tier) and (v_country is null or s.country_code=v_country) and (v_provider is null or s.provider_id=v_provider) group by 2
          union all select 'english', s.english_src, count(*) from pipeline.course_field_source s where (v_tier is null or s.tier=v_tier) and (v_country is null or s.country_code=v_country) and (v_provider is null or s.provider_id=v_provider) group by 2
          union all select 'fee', s.fee_src, count(*) from pipeline.course_field_source s where (v_tier is null or s.tier=v_tier) and (v_country is null or s.country_code=v_country) and (v_provider is null or s.provider_id=v_provider) group by 2) z),
      'field_sources_at',(select max(computed_at) from pipeline.course_field_source),
      'completeness_state_map',(select jsonb_object_agg(s, security.coverage_completeness_state(s))
          from unnest(array['admitted','candidate','in_review','awaiting_l3','not_on_page','in_queue','blocked','page_found','site_known','no_website','missing_l1','no_reader']) s),
      'completeness',(select jsonb_build_object(
            'computed_at',max(cc.computed_at),
            'courses',count(*),
            'attributes',max(cc.attributes),
            'completeness',round(avg(cc.completeness),1),
            'accounted_pct',round(avg(cc.accounted_pct),1),
            'fully_complete',count(*) filter (where cc.admitted=cc.attributes),
            'by_admitted',(select jsonb_agg(jsonb_build_object('admitted',b.admitted,'courses',b.n) order by b.admitted) from (
                select c2.admitted, count(*) n from cc c2 group by 1) b),
            'trend',case when v_tier is null then (select jsonb_agg(jsonb_build_object('date',d.snapshot_date,'courses',d.courses,'completeness',d.completeness,
                        'accounted_pct',d.accounted_pct,'fully_complete',d.fully_complete,'computed_at',d.computed_at) order by d.snapshot_date)
                      from pipeline.completeness_daily d where d.snapshot_date>=current_date-60
                       and case when v_provider is not null then d.scope='provider' and d.scope_id=v_provider
                                when v_country is not null then d.scope='country:'||v_country
                                else d.scope='platform' end) end)
          from cc)
    ) into v;
    return v||jsonb_build_object('snapshot',jsonb_build_object('source','live','generated_at',now(),'checked_at',now(),'stale',false));
  elsif p_operation='course_coverage_courses' then
    if v_cstate is not null and not (v_cstate = any(c_states)) then raise exception 'unknown completeness state %', v_cstate; end if;
    select jsonb_build_object('total',(select count(*) from pipeline.course_attribute_coverage x where x.attribute=p_args->>'attribute'
                 and (case when v_cstate is not null then security.coverage_completeness_state(x.state)=v_cstate else x.state=p_args->>'state' end)
                 and (v_tier is null or x.tier=v_tier) and (v_country is null or x.country_code=v_country) and (v_provider is null or x.provider_id=v_provider)),
      'items',coalesce((select jsonb_agg(r) from (
        select x.course_id, c.canonical_title title, coalesce(p.display_name,p.canonical_name) provider_name, x.tier, x.country_code,
               (select min(registration_code) from catalogue.course_registrations cr where cr.course_id=x.course_id and lower(cr.scheme)='cricos') cricos,
               x.state, security.coverage_completeness_state(x.state) completeness_state, cc.completeness, cc.accounted_pct
          from pipeline.course_attribute_coverage x join catalogue.courses c on c.id=x.course_id join catalogue.providers p on p.id=x.provider_id
          left join pipeline.course_completeness cc on cc.course_id=x.course_id
         where x.attribute=p_args->>'attribute'
           and (case when v_cstate is not null then security.coverage_completeness_state(x.state)=v_cstate else x.state=p_args->>'state' end)
           and (v_tier is null or x.tier=v_tier) and (v_country is null or x.country_code=v_country) and (v_provider is null or x.provider_id=v_provider)
         order by coalesce(p.display_name,p.canonical_name), c.canonical_title
         limit least(coalesce(nullif(p_args->>'limit','')::int,50),200) offset greatest(coalesce(nullif(p_args->>'offset','')::int,0),0)) r),'[]'::jsonb))
      into v;
    return v;
  end if;
  raise exception 'unknown coverage operation %', p_operation;
end $$;


ALTER FUNCTION "security"."admin_course_coverage_read"("p_operation" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_course_decision_context"("p_course_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'security', 'catalogue', 'ref', 'public'
    AS $$
with course_base as (select c.id course_id,c.provider_id,c.primary_field_id,c.study_level_id from catalogue.courses c where c.id=p_course_id),
campus_states as (select distinct ca.subdivision_id from course_base b join catalogue.course_campuses cc on cc.course_id=b.course_id join catalogue.campuses ca on ca.id=cc.campus_id where ca.subdivision_id is not null),
qilt as (select jsonb_agg(jsonb_build_object('context_type',case when po.external_study_area_id is null then 'qilt_provider' else 'qilt_provider_study_area' end,'grain',case when po.external_study_area_id is null then 'provider' else 'provider_study_area' end,'provider_id',po.provider_id,'external_study_area_id',po.external_study_area_id,'study_level_id',po.study_level_id,'audience',po.audience,'collection_year_from',po.collection_year_from,'collection_year_to',po.collection_year_to,'metric_id',po.metric_id,'metric_value',po.metric_value,'response_count',po.response_count,'national_benchmark',po.national_benchmark,'source_id',po.source_id,'evidence_id',po.evidence_id,'observed_at',po.observed_at,'course_grain',false) order by po.collection_year_to desc nulls last,po.observed_at desc) filter(where po.id is not null) data from course_base b left join lateral (select po.* from catalogue.provider_outcomes po where po.provider_id=b.provider_id and coalesce(po.status,'current') in ('active','current') order by po.collection_year_to desc nulls last,po.observed_at desc limit 30) po on true),
prisms_provider as (select jsonb_agg(jsonb_build_object('context_type','prisms_provider','grain','provider','provider_id',sf.provider_id,'subdivision_id',sf.subdivision_id,'external_study_area_id',sf.external_study_area_id,'field_of_study_id',sf.field_of_study_id,'study_level_id',sf.study_level_id,'audience',sf.audience,'period_start',sf.period_start,'period_end',sf.period_end,'period_type',sf.period_type,'metric_id',sf.metric_id,'metric_value',sf.metric_value,'is_suppressed',sf.is_suppressed,'suppression_code',sf.suppression_code,'source_id',sf.source_id,'evidence_id',sf.evidence_id,'observed_at',sf.observed_at,'course_grain',false) order by sf.period_end desc nulls last,sf.observed_at desc) filter(where sf.id is not null) data from course_base b left join lateral (select sf.* from catalogue.student_flow_observations sf where sf.provider_id=b.provider_id and coalesce(sf.status,'current') in ('active','current') order by sf.period_end desc nulls last,sf.observed_at desc limit 30) sf on true),
prisms_state as (select jsonb_agg(jsonb_build_object('context_type','prisms_state','grain','state_or_subdivision','subdivision_id',sf.subdivision_id,'source_geography_type',sf.source_geography_type,'source_geography_key',sf.source_geography_key,'source_geography_name',sf.source_geography_name,'external_study_area_id',sf.external_study_area_id,'field_of_study_id',sf.field_of_study_id,'study_level_id',sf.study_level_id,'audience',sf.audience,'period_start',sf.period_start,'period_end',sf.period_end,'metric_id',sf.metric_id,'metric_value',sf.metric_value,'is_suppressed',sf.is_suppressed,'suppression_code',sf.suppression_code,'source_id',sf.source_id,'evidence_id',sf.evidence_id,'observed_at',sf.observed_at,'course_grain',false) order by sf.period_end desc nulls last,sf.observed_at desc) data from (select sf.* from catalogue.student_flow_observations sf where sf.subdivision_id in (select subdivision_id from campus_states) and coalesce(sf.status,'current') in ('active','current') order by sf.period_end desc nulls last,sf.observed_at desc limit 30) sf)
select jsonb_build_object('course_id',b.course_id,'provider_id',b.provider_id,'context_semantics','decision_context_not_course_fact','qilt',coalesce(q.data,'[]'::jsonb),'prisms_provider',coalesce(pp.data,'[]'::jsonb),'prisms_state',coalesce(ps.data,'[]'::jsonb)) from course_base b cross join qilt q cross join prisms_provider pp cross join prisms_state ps;
$$;


ALTER FUNCTION "security"."admin_course_decision_context"("p_course_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_course_entry_summary"("p_course_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'ref', 'pipeline'
    AS $$
declare
  v_rank integer;
begin
  select security.current_role_rank() into v_rank;
  if coalesce(v_rank,0) < 1 then
    raise exception 'assigned StudySearch role required' using errcode='42501';
  end if;

  return jsonb_build_object(
    'intakes', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', i.id,
          'intake_year', i.intake_year,
          'intake_label', i.intake_label,
          'start_date', i.start_date,
          'application_deadline', i.application_deadline,
          'campus_id', i.campus_id,
          'campus', case when ca.id is null then null else jsonb_build_object(
            'id', ca.id,
            'stable_key', ca.stable_key,
            'name', ca.name,
            'city', ca.city,
            'subdivision_code', sd.code,
            'subdivision_name', sd.name,
            'country_code', co.iso_alpha2
          ) end,
          'status', i.status,
          'confidence', i.confidence,
          'source_intake_key', i.source_intake_key,
          'source', jsonb_build_object(
            'source_id', i.source_id,
            'source_label', s.label,
            'source_type', s.source_type,
            'source_url', s.url
          ),
          'evidence', case when e.id is null then null else jsonb_build_object(
            'id', e.id,
            'type', e.evidence_type,
            'source_url', e.source_url,
            'captured_at', e.captured_at,
            'valid_from', e.valid_from,
            'valid_to', e.valid_to,
            'content_hash', e.content_hash
          ) end
        ) order by i.intake_year, i.start_date nulls last, i.intake_label
      )
      from catalogue.course_intakes i
      left join catalogue.campuses ca on ca.id=i.campus_id
      left join ref.countries co on co.id=ca.country_id
      left join ref.subdivisions sd on sd.id=ca.subdivision_id
      left join pipeline.sources s on s.id=i.source_id
      left join pipeline.evidence_artifacts e on e.id=i.evidence_id
      where i.course_id=p_course_id
    ), '[]'::jsonb),
    'english_requirements', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', er.id,
          'test_id', et.id,
          'test_code', et.code,
          'test_name', et.name,
          'score_scale', et.score_scale,
          'overall_score', er.overall_score,
          'component_scores', er.component_scores,
          'notes', er.notes,
          'status', er.status,
          'confidence', er.confidence,
          'source_requirement_key', er.source_requirement_key,
          'valid_from', er.valid_from,
          'valid_to', er.valid_to,
          'last_verified_at', er.last_verified_at,
          'scope', 'course',
          'source', jsonb_build_object(
            'source_id', er.source_id,
            'source_label', s.label,
            'source_type', s.source_type,
            'source_url', s.url
          ),
          'evidence', case when e.id is null then null else jsonb_build_object(
            'id', e.id,
            'type', e.evidence_type,
            'source_url', e.source_url,
            'captured_at', e.captured_at,
            'valid_from', e.valid_from,
            'valid_to', e.valid_to,
            'content_hash', e.content_hash
          ) end
        ) order by et.code
      )
      from catalogue.course_english_requirements er
      join ref.english_tests et on et.id=er.english_test_id
      left join pipeline.sources s on s.id=er.source_id
      left join pipeline.evidence_artifacts e on e.id=er.evidence_id
      where er.course_id=p_course_id
    ), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "security"."admin_course_entry_summary"("p_course_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_course_fee_summary"("p_course_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'pipeline', 'auth'
    AS $$
declare
  v_rank integer := 0;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode='42501';
  end if;
  select security.current_role_rank() into v_rank;
  if v_rank < 1 then
    raise exception 'assigned StudySearch role required' using errcode='42501';
  end if;

  return jsonb_build_object(
    'fee_used',security.course_fee_used_v1(p_course_id),
    'cricos_registered',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',cf.id,
        'fee_type',cf.fee_type,
        'amount',cf.amount,
        'currency',cf.currency_code,
        'basis',cf.basis,
        'load_basis',cf.load_basis,
        'fee_year',cf.fee_year,
        'audience',cf.audience,
        'campus_id',cf.campus_id,
        'valid_from',cf.valid_from,
        'valid_to',cf.valid_to,
        'status',cf.status,
        'source_fee_key',cf.source_fee_key,
        'source_id',cf.source_id,
        'source_snapshot_at',cf.source_snapshot_at,
        'last_verified_at',cf.last_verified_at,
        'evidence_id',cf.evidence_id,
        'source',case when s.id is null then null else jsonb_build_object(
          'id',s.id,'label',s.label,'type',s.source_type,'url',s.url
        ) end,
        'evidence',case when e.id is null then null else jsonb_build_object(
          'id',e.id,'type',e.evidence_type,'source_url',e.source_url,
          'content_hash',e.content_hash,'captured_at',e.captured_at
        ) end
      ) order by case cf.fee_type when 'tuition' then 1 when 'non_tuition' then 2 when 'estimated_total_course_cost' then 3 else 9 end,cf.fee_type)
      from catalogue.course_fees cf
      left join pipeline.sources s on s.id=cf.source_id
      left join pipeline.evidence_artifacts e on e.id=cf.evidence_id
      where cf.course_id=p_course_id
        and cf.basis='registered_total_course'
        and coalesce(cf.status,'active')='active'
    ),'[]'::jsonb),
    'provider_current',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',cf.id,
        'fee_type',cf.fee_type,
        'amount',cf.amount,
        'currency',cf.currency_code,
        'basis',cf.basis,
        'load_basis',cf.load_basis,
        'fee_year',cf.fee_year,
        'audience',cf.audience,
        'campus_id',cf.campus_id,
        'valid_from',cf.valid_from,
        'valid_to',cf.valid_to,
        'status',cf.status,
        'source_fee_key',cf.source_fee_key,
        'source_id',cf.source_id,
        'source_snapshot_at',cf.source_snapshot_at,
        'last_verified_at',cf.last_verified_at,
        'evidence_id',cf.evidence_id,
        'source',case when s.id is null then null else jsonb_build_object(
          'id',s.id,'label',s.label,'type',s.source_type,'url',s.url
        ) end,
        'evidence',case when e.id is null then null else jsonb_build_object(
          'id',e.id,'type',e.evidence_type,'source_url',e.source_url,
          'content_hash',e.content_hash,'captured_at',e.captured_at
        ) end
      ) order by cf.fee_year desc nulls last,cf.last_verified_at desc nulls last,cf.created_at desc)
      from catalogue.course_fees cf
      left join pipeline.sources s on s.id=cf.source_id
      left join pipeline.evidence_artifacts e on e.id=cf.evidence_id
      where cf.course_id=p_course_id
        and cf.fee_type ~ '^provider_current_'
        and coalesce(cf.status,'active')='active'
    ),'[]'::jsonb),
    'other',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',cf.id,'fee_type',cf.fee_type,'amount',cf.amount,'currency',cf.currency_code,
        'basis',cf.basis,'load_basis',cf.load_basis,'fee_year',cf.fee_year,'audience',cf.audience,
        'campus_id',cf.campus_id,'valid_from',cf.valid_from,'valid_to',cf.valid_to,'status',cf.status,
        'source_id',cf.source_id,'source_snapshot_at',cf.source_snapshot_at,'last_verified_at',cf.last_verified_at,
        'evidence_id',cf.evidence_id
      ) order by cf.created_at desc)
      from catalogue.course_fees cf
      where cf.course_id=p_course_id
        and cf.basis is distinct from 'registered_total_course'
        and not (cf.fee_type ~ '^provider_current_')
        and coalesce(cf.status,'active')='active'
    ),'[]'::jsonb)
  );
end
$$;


ALTER FUNCTION "security"."admin_course_fee_summary"("p_course_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."admin_course_fee_summary"("p_course_id" "uuid") IS 'CF-CHG-20260820-001 private role-checked Admin fee read helper. Preserves fee type, basis, year/audience/campus scope, validity, source/evidence, snapshot and verification. Unknown non-CRICOS/non-provider-current fee semantics are isolated in other rather than mislabeled.';



CREATE OR REPLACE FUNCTION "security"."admin_course_field_states"("p_course_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'pim', 'ref', 'security', 'auth'
    AS $$
declare
  c catalogue.courses%rowtype;
  v_l4 text[]:=array[]::text[];
  v_codes text[];
  v_domains text[]:=array[]::text[];
  v_course_url text; v_url_ev uuid;
  v_fee record; v_fee_l3 record; v_reg_tuition int:=0; v_l3_open text;
  v_mode_count int:=0; v_intake_count int:=0; v_english_count int:=0; v_campus_count int:=0; v_reg_count int:=0; v_academic_count int:=0; v_category_count int:=0; v_collection_count int:=0;
  v_fee_state jsonb;
  function_result jsonb;
begin
  if auth.uid() is null or security.current_role_rank()<1 then raise exception 'assigned StudySearch role required' using errcode='42501'; end if;
  select * into c from catalogue.courses where id=p_course_id;
  if c.id is null then return '[]'::jsonb; end if;

  select coalesce(array_agg(distinct field_code),array[]::text[]) into v_l4 from pipeline.layer4_course_field_resolutions where course_id=c.id and status='applied';
  -- Provider-scoped Layer 2 sources (Decision 149): the provider's CRICOS codes and the domains its qualified sources admit.
  select coalesce(array_agg(distinct upper(btrim(pr.registration_code))),array[]::text[]) into v_codes
    from catalogue.provider_registrations pr where pr.provider_id=c.provider_id and lower(pr.registration_scheme)='cricos';
  select coalesce(array_agg(distinct d),array[]::text[]) into v_domains
    from pipeline.course_fact_source_qualifications q, unnest(q.admitted_domains) d
   where upper(btrim(q.provider_cricos))=any(v_codes) and q.qualification_status in ('qualified','bounded')
     and not exists (select 1 from pipeline.sources s where s.id=q.source_id and s.source_type='provider_fee_schedule');

  select cl.url, cl.evidence_id into v_course_url, v_url_ev from catalogue.course_links cl
   where cl.course_id=c.id and cl.link_type='official_course' and coalesce(cl.status,'active')='active'
   order by (cl.audience='international') desc, cl.last_verified_at desc nulls last, cl.created_at desc limit 1;
  v_course_url:=coalesce(nullif(c.course_url,''),v_course_url);

  select f.id, f.evidence_id, f.source_id into v_fee from catalogue.course_fees f
   where f.course_id=c.id and f.fee_type='provider_current_tuition' and coalesce(f.status,'active')='active'
   order by f.fee_year desc nulls last, f.updated_at desc nulls last limit 1;
  if v_fee.id is not null then
    select w.id, coalesce(p.model_identifier, p.code) model into v_fee_l3 from pipeline.layer3_work_items w
      left join pipeline.layer3_interpretations i on i.id=w.interpretation_id
      left join pipeline.layer3_model_profiles p on p.id=coalesce(i.profile_id,w.profile_id)
     where w.entity_id=c.id and w.status='admitted' and w.evidence_id=v_fee.evidence_id order by w.updated_at desc limit 1;
  end if;
  select count(*) into v_reg_tuition from catalogue.course_fees f
   where f.course_id=c.id and f.fee_type='tuition' and f.basis='registered_total_course' and coalesce(f.status,'active')='active';
  select case when bool_or(w.status in ('pending','reserved','interpreting','validated','admission_pending','failed')) then 'awaiting_l3'
              when bool_or(w.status='layer4_required') then 'awaiting_l4' end
    into v_l3_open from pipeline.layer3_work_items w where w.entity_id=c.id and w.task_class='provider_current_tuition_validation';

  select count(*) into v_intake_count from catalogue.course_intakes i where i.course_id=c.id and coalesce(i.status,'active')='active';
  select count(*) into v_english_count from catalogue.course_english_requirements e where e.course_id=c.id and coalesce(e.status,'active')='active';
  select count(*), count(*) filter (where nullif(cc.delivery_mode,'') is not null) into v_campus_count, v_mode_count from catalogue.course_campuses cc where cc.course_id=c.id;
  select count(*) into v_reg_count from catalogue.course_regulatory_observations r where r.course_id=c.id and r.valid_to is null;
  select count(*) into v_academic_count from catalogue.course_academic_options a where a.course_id=c.id and coalesce(a.status,'active')='active';
  select count(*) into v_category_count from pim.entity_categories ec join pim.entity_registry er on er.id=ec.entity_id where er.entity_type='course' and er.stable_key=c.stable_key;
  select count(*) into v_collection_count from catalogue.course_collection_memberships m where m.course_id=c.id;

  -- Provider tuition (Decision 162: CRICOS registered tuition is the Layer 1 figure; provider tuition is a refinement).
  if v_fee.id is not null then
    v_fee_state:=jsonb_build_object('value_state','resolved',
      'resolved_layer',case when 'provider_current_tuition'=any(v_l4) then 4 when v_fee_l3.id is not null then 3 else 2 end,
      'resolved_by',case when 'provider_current_tuition'=any(v_l4) then 'Layer 4 resolution' when v_fee_l3.id is not null then 'Layer 3 · '||coalesce(v_fee_l3.model,'qualified model') when exists (select 1 from pipeline.sources fs where fs.id=v_fee.source_id and fs.source_type='provider_fee_schedule') then 'Layer 2 provider fee schedule' else 'Layer 2 provider rule' end,
      'evidence_id',v_fee.evidence_id);
  elsif v_l3_open is not null then
    v_fee_state:=jsonb_build_object('value_state',v_l3_open,'resolved_layer',null);
  elsif 'international_fee'=any(v_domains) then
    v_fee_state:=jsonb_build_object('value_state','awaiting_l2','resolved_layer',null);
  elsif v_reg_tuition>0 then
    v_fee_state:=jsonb_build_object('value_state','l1_covers','resolved_layer',1,'resolved_by','CRICOS registered international tuition applies');
  else
    v_fee_state:=jsonb_build_object('value_state','not_collected','resolved_layer',null);
  end if;

  function_result:=jsonb_build_array(
    jsonb_build_object('code','provider','label','Provider','group','Identity','value_state',case when c.provider_id is not null then 'resolved' else 'source_missing' end,'resolved_layer',1,'resolved_by','CRICOS','editable_l4',false,'authority','Layer 1'),
    jsonb_build_object('code','course_code','label','CRICOS / Course code','group','Identity','value_state',case when nullif(c.course_code,'') is not null then 'resolved' else 'source_missing' end,'resolved_layer',1,'resolved_by','CRICOS','editable_l4',false,'authority','Layer 1'),
    jsonb_build_object('code','study_level','label','Study level','group','Identity','value_state',case when c.study_level_id is not null then 'resolved' else 'source_missing' end,'resolved_layer',1,'resolved_by','CRICOS','editable_l4',false,'authority','Layer 1'),
    jsonb_build_object('code','field_of_study','label','Field of study','group','Identity','value_state',case when c.primary_field_id is not null then 'resolved' else 'source_missing' end,'resolved_layer',1,'resolved_by','CRICOS','editable_l4',false,'authority','Layer 1'),
    jsonb_build_object('code','duration','label','Duration','group','Course facts','value_state',case when c.duration_value is not null then 'resolved' else 'not_collected' end,'resolved_layer',case when 'duration'=any(v_l4) then 4 when c.duration_value is not null then 1 end,'resolved_by',case when 'duration'=any(v_l4) then 'Layer 4 resolution' else 'CRICOS' end,'editable_l4',true,'authority','Layer 1'),
    jsonb_build_object('code','delivery_mode','label','Delivery mode','group','Course facts','value_state',case when nullif(c.delivery_mode,'') is not null or v_mode_count>0 then 'resolved' else 'not_collected' end,'resolved_layer',case when 'delivery_mode'=any(v_l4) then 4 when nullif(c.delivery_mode,'') is not null or v_mode_count>0 then 1 end,'resolved_by',case when 'delivery_mode'=any(v_l4) then 'Layer 4 resolution' else 'CRICOS course locations' end,'editable_l4',true,'authority','Layer 1'),
    jsonb_build_object('code','official_course_url','label','Official Course URL','group','Course facts','value_state',case when v_course_url is not null then 'resolved' when 'official_course_url'=any(v_domains) then 'awaiting_l2' else 'not_collected' end,'resolved_layer',case when 'official_course_url'=any(v_l4) then 4 when v_course_url is not null then 2 end,'resolved_by',case when 'official_course_url'=any(v_l4) then 'Layer 4 resolution' when v_course_url is not null then 'Layer 2 provider rule' end,'evidence_id',v_url_ev,'editable_l4',true,'authority','Enrichment'),
    jsonb_build_object('code','course_description','label','Course description','group','Course facts','value_state',case when nullif(c.description,'') is not null then 'resolved' when 'official_course_url'=any(v_domains) then 'awaiting_l2' else 'not_collected' end,'resolved_layer',case when 'course_description'=any(v_l4) then 4 when nullif(c.description,'') is not null then 2 end,'editable_l4',true,'authority','Enrichment'),
    jsonb_build_object('code','provider_current_tuition','label','Current Provider tuition','group','Fees','editable_l4',true,'authority','Enrichment')||v_fee_state,
    jsonb_build_object('code','intakes','label','Intakes','group','Entry & availability','value_state',case when v_intake_count>0 then 'resolved' when 'intake'=any(v_domains) then 'awaiting_l2' else 'not_collected' end,'resolved_layer',case when 'intakes'=any(v_l4) then 4 when v_intake_count>0 then 2 end,'editable_l4',true,'authority','Enrichment'),
    jsonb_build_object('code','english_requirement','label','English requirement','group','Entry & availability','value_state',case when v_english_count>0 then 'resolved' when 'english_requirement'=any(v_domains) then 'awaiting_l2' else 'not_collected' end,'resolved_layer',case when 'english_requirement'=any(v_l4) then 4 when v_english_count>0 then 2 end,'editable_l4',true,'authority','Enrichment'),
    jsonb_build_object('code','campuses','label','Campuses','group','Delivery','value_state',case when v_campus_count>0 then 'resolved' else 'source_missing' end,'resolved_layer',1,'resolved_by','CRICOS','editable_l4',false,'authority','Layer 1'),
    jsonb_build_object('code','academic_options','label','Academic options','group','Structure','value_state',case when v_academic_count>0 then 'resolved' else 'not_collected' end,'resolved_layer',case when v_academic_count>0 then 2 end,'editable_l4',true,'authority','Enrichment'),
    jsonb_build_object('code','categories','label','Categories','group','Structure','value_state',case when v_category_count>0 then 'resolved' else 'l4_input' end,'resolved_layer',case when v_category_count>0 then 4 end,'editable_l4',true,'authority','PIM / Layer 4'),
    jsonb_build_object('code','collections','label','Collections','group','Structure','value_state',case when v_collection_count>0 then 'resolved' else 'l4_input' end,'resolved_layer',case when v_collection_count>0 then 4 end,'editable_l4',true,'authority','PIM / Layer 4'),
    jsonb_build_object('code','regulatory_facts','label','Regulatory facts','group','Regulatory','value_state',case when v_reg_count>0 then 'resolved' else 'source_missing' end,'resolved_layer',1,'resolved_by','CRICOS','editable_l4',false,'authority','Layer 1'),
    jsonb_build_object('code','publication','label','Publication','group','Governance','value_state','resolved','resolved_layer',null,'editable_l4',false,'authority','Governed action')
  );
  return function_result;
end $$;


ALTER FUNCTION "security"."admin_course_field_states"("p_course_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_course_page_fast"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'public', 'auth'
    AS $_$
declare
  v_q text:=nullif(trim(coalesce(p_args->>'query','')),'');
  v_provider_id uuid;
  v_sort text:=lower(coalesce(nullif(p_args->>'sort',''),'course'));
  v_dir text:=lower(coalesce(nullif(p_args->>'direction',''),'asc'));
  v_simple boolean;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  if security.current_role_rank()<1 then raise exception 'assigned StudySearch role required' using errcode='42501'; end if;

  v_simple :=
    v_q is null
    and nullif(p_args->>'country_code','') is null
    and nullif(p_args->>'subdivision_code','') is null
    and nullif(p_args->>'provider_id','') is null
    and nullif(p_args->>'level_code','') is null
    and nullif(p_args->>'field_code','') is null
    and nullif(p_args->>'delivery_mode','') is null
    and nullif(p_args->>'lifecycle_status','') is null
    and nullif(p_args->>'publication_status','') is null
    and nullif(p_args->>'has_fee','') is null
    and nullif(p_args->>'has_intake','') is null
    and nullif(p_args->>'has_english','') is null
    and nullif(p_args->>'has_scholarship','') is null
    and nullif(p_args->>'has_state','') is null
    and nullif(p_args->>'has_link','') is null
    and nullif(p_args->>'min_completeness','') is null
    and nullif(p_args->>'freshness','') is null
    and nullif(p_args->>'university_group','') is null
    and nullif(p_args->>'applicant','') is null
    and nullif(p_args->>'description','') is null
    and v_sort='course' and v_dir='asc';

  if v_simple then
    -- CF-247 Course Catalogue columns (mandate 5 Nov 2026 17:31): every page carries the extra columns, read set-based over its ids
    return security.course_list_with_extras_v1(security.admin_course_page_unfiltered_fast(p_args));
  end if;

  if v_q is not null and v_q ~* '^course:' then
    select c.provider_id into v_provider_id
    from catalogue.courses c where c.stable_key=v_q limit 1;
  elsif v_q is not null and v_q ~ '^[0-9]{6}[A-Za-z]$' then
    select c.provider_id into v_provider_id
    from catalogue.courses c where upper(c.course_code)=upper(v_q) limit 1;
  end if;

  if v_provider_id is not null and nullif(p_args->>'provider_id','') is null then
    return security.course_list_with_extras_v1(security.admin_course_page_fast_base(p_args||jsonb_build_object('provider_id',v_provider_id::text)));
  end if;

  return security.course_list_with_extras_v1(security.admin_course_page_fast_base(p_args));
end $_$;


ALTER FUNCTION "security"."admin_course_page_fast"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."admin_course_page_fast_base"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'ref', 'scholarship', 'search', 'public', 'auth'
    AS $$
declare
  v_rank integer:=0;
  v_limit integer:=least(greatest(coalesce(nullif(p_args->>'limit','')::integer,50),1),200);
  v_offset integer:=greatest(coalesce(nullif(p_args->>'offset','')::integer,0),0);
  v_sort text:=lower(coalesce(nullif(p_args->>'sort',''),'course'));
  v_dir text:=case when lower(coalesce(nullif(p_args->>'direction',''),'asc'))='desc' then 'desc' else 'asc' end;
  v_provider_id uuid:=nullif(p_args->>'provider_id','')::uuid;
  v_has_fee boolean:=case when nullif(p_args->>'has_fee','') is null then null else (p_args->>'has_fee')::boolean end;
  v_has_intake boolean:=case when nullif(p_args->>'has_intake','') is null then null else (p_args->>'has_intake')::boolean end;
  v_has_english boolean:=case when nullif(p_args->>'has_english','') is null then null else (p_args->>'has_english')::boolean end;
  v_has_scholarship boolean:=case when nullif(p_args->>'has_scholarship','') is null then null else (p_args->>'has_scholarship')::boolean end;
  v_has_state boolean:=case when nullif(p_args->>'has_state','') is null then null else (p_args->>'has_state')::boolean end;
  v_has_link boolean:=case when nullif(p_args->>'has_link','') is null then null else (p_args->>'has_link')::boolean end;
  v_min_completeness numeric:=nullif(p_args->>'min_completeness','')::numeric;
  v_group text:=nullif(trim(coalesce(p_args->>'university_group','')),'');
  v_result jsonb;
  v_sub_id uuid;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<1 then raise exception 'assigned StudySearch role required' using errcode='42501'; end if;
  if nullif(trim(coalesce(p_args->>'subdivision_code','')),'') is not null then
    select sd.id into v_sub_id from ref.subdivisions sd where sd.code=upper(trim(p_args->>'subdivision_code'));
  end if;

  -- Fee/readiness ordering is still intentionally not promoted by the v2.10 UI.
  -- Preserve the accepted legacy implementation only for explicit direct callers of
  -- those derived sorts. All normal derived filters remain in the bounded fast path.
  -- 12 Nov 2026 (Platform Admin, Course catalogue): the Course description filter is applied in the bounded path below only
  if v_sort in ('fee','completeness') and nullif(p_args->>'description','') is null then
    return security.admin_course_page_search_state(public.ui_courses_decision_page(
      v_limit,v_offset,nullif(p_args->>'query',''),nullif(p_args->>'country_code',''),nullif(p_args->>'subdivision_code',''),v_provider_id,
      nullif(p_args->>'level_code',''),nullif(p_args->>'field_code',''),nullif(p_args->>'delivery_mode',''),nullif(p_args->>'lifecycle_status',''),nullif(p_args->>'publication_status',''),
      v_has_fee,v_has_intake,v_has_english,v_has_scholarship,v_min_completeness,nullif(p_args->>'freshness',''),
      v_sort,v_dir,v_has_state,v_has_link,v_group
    ));
  end if;

  with base as (
    select
      c.id,c.stable_key,c.canonical_title,c.display_title,c.course_code,c.course_url,
      c.lifecycle_status,c.publication_status,c.last_verified_at,c.created_at,c.updated_at,c.provider_id,
      c.duration_value,c.description,c.delivery_mode canonical_delivery_mode,c.open_to_international,c.open_to_domestic,
      coalesce(p.display_name,p.canonical_name) provider_name,
      co.iso_alpha2::text country_code,co.name country_name,co.default_currency_code::text currency_code,
      sl.code level_code,sl.name level_name,fos.code field_code,fos.name field_of_study
    from catalogue.courses c
    join catalogue.providers p on p.id=c.provider_id
    join ref.countries co on co.id=p.country_id
    left join ref.study_levels sl on sl.id=c.study_level_id
    left join ref.fields_of_study fos on fos.id=c.primary_field_id
    where (nullif(trim(coalesce(p_args->>'query','')),'') is null
      or c.canonical_title ilike '%'||trim(p_args->>'query')||'%'
      or coalesce(c.display_title,'') ilike '%'||trim(p_args->>'query')||'%'
      or coalesce(p.display_name,p.canonical_name,'') ilike '%'||trim(p_args->>'query')||'%'
      or coalesce(c.course_code,'') ilike '%'||trim(p_args->>'query')||'%'
      or coalesce(c.stable_key,'') ilike '%'||trim(p_args->>'query')||'%'
      or exists(select 1 from catalogue.course_identifiers ci where ci.course_id=c.id and ci.scheme='studysearch' and upper(ci.identifier) like upper(trim(p_args->>'query'))||'%'))
      and (nullif(trim(coalesce(p_args->>'country_code','')),'') is null or co.iso_alpha2::text=upper(trim(p_args->>'country_code')))
      and (v_provider_id is null or c.provider_id=v_provider_id)
      and (v_group is null or c.provider_id in (select security.university_group_provider_ids(v_group)))
      and (nullif(trim(coalesce(p_args->>'level_code','')),'') is null or sl.code=trim(p_args->>'level_code'))
      and (nullif(trim(coalesce(p_args->>'field_code','')),'') is null or fos.code=trim(p_args->>'field_code'))
      and (nullif(trim(coalesce(p_args->>'lifecycle_status','')),'') is null or c.lifecycle_status=trim(p_args->>'lifecycle_status'))
      and (nullif(trim(coalesce(p_args->>'publication_status','')),'') is null or c.publication_status=trim(p_args->>'publication_status'))
      and (nullif(trim(coalesce(p_args->>'subdivision_code','')),'') is null or exists(
        select 1 from catalogue.course_campuses cc
        join catalogue.campuses ca on ca.id=cc.campus_id
        join ref.subdivisions sd on sd.id=ca.subdivision_id
        where cc.course_id=c.id and sd.code=upper(trim(p_args->>'subdivision_code')))
        or (p.subdivision_id=v_sub_id and not exists(
          select 1 from catalogue.course_campuses cc join catalogue.campuses ca on ca.id=cc.campus_id
          where cc.course_id=c.id and ca.subdivision_id is not null)))
      and (nullif(trim(coalesce(p_args->>'delivery_mode','')),'') is null
        or nullif(btrim(c.delivery_mode),'')=trim(p_args->>'delivery_mode')
        or (nullif(btrim(c.delivery_mode),'') is null
            and exists(select 1 from catalogue.course_campuses cc where cc.course_id=c.id and cc.delivery_mode=trim(p_args->>'delivery_mode'))))
      and (nullif(trim(coalesce(p_args->>'freshness','')),'') is null
        or (p_args->>'freshness'='never_verified' and c.last_verified_at is null)
        or (p_args->>'freshness'='modified_7d' and c.updated_at>=now()-interval '7 days')
        or (p_args->>'freshness'='modified_30d' and c.updated_at>=now()-interval '30 days')
        or (p_args->>'freshness'='stale_180d' and (c.last_verified_at is null or c.last_verified_at<now()-interval '180 days')))
      and (v_has_fee is null or exists(
        select 1 from catalogue.course_fees cf
        where cf.course_id=c.id and coalesce(cf.status,'active')='active')=v_has_fee)
      and (v_has_intake is null or exists(
        select 1 from catalogue.course_intakes ci
        where ci.course_id=c.id and coalesce(ci.status,'active')='active')=v_has_intake)
      and (v_has_english is null or exists(
        select 1 from catalogue.course_english_requirements er
        where er.course_id=c.id and coalesce(er.status,'active')='active')=v_has_english)
      and (v_has_scholarship is null or exists(
        select 1 from scholarship.scopes ss
        where coalesce(ss.include_exclude,'include')='include'
          and (ss.course_id=c.id or (ss.scope_type='provider' and ss.provider_id=c.provider_id)))=v_has_scholarship)
      and (v_has_state is null or (p.subdivision_id is not null or exists(
        select 1 from catalogue.course_campuses cc
        join catalogue.campuses ca on ca.id=cc.campus_id
        where cc.course_id=c.id and ca.subdivision_id is not null))=v_has_state)
      and (v_has_link is null or exists(
        select 1 from catalogue.course_links l where l.link_type = 'official_course' and l.course_id=c.id and l.status='active')=v_has_link)
      and (nullif(p_args->>'applicant','') is null
        or (p_args->>'applicant'='international' and c.open_to_international is true)
        or (p_args->>'applicant'='domestic_only' and c.open_to_international is false)
        or (p_args->>'applicant'='both' and c.open_to_international is true and c.open_to_domestic is true)
        or (p_args->>'applicant'='unknown' and c.open_to_international is null))
      -- 12 Nov 2026 (Platform Admin, Course catalogue): Course description filter: held or not, or written by the description reader in the last day or week
      and (nullif(p_args->>'description','') is null
        or (p_args->>'description'='populated' and nullif(btrim(c.description),'') is not null)
        or (p_args->>'description'='missing' and nullif(btrim(c.description),'') is null)
        or (p_args->>'description' in ('updated_24h','updated_7d') and nullif(btrim(c.description),'') is not null and exists (
          -- the reading must be the text held now: a description edited by hand after the reading is not counted as written by the reader
          select 1 from pipeline.field_enrich_items e where e.course_id=c.id and e.field='description' and e.state='filled' and btrim(e.value->>'text')=btrim(c.description)
             and e.updated_at>=now()-case when p_args->>'description'='updated_24h' then interval '1 day' else interval '7 days' end)))  -- fixed: the filter's own windows, as the Freshness filter's
      and (v_min_completeness is null or (
        (exists(select 1 from catalogue.course_registrations r where r.course_id=c.id))::int
        +(c.duration_value is not null or exists(select 1 from catalogue.course_academic_options a where a.course_id=c.id))::int
        +(exists(select 1 from catalogue.course_fees cf where cf.course_id=c.id and coalesce(cf.status,'active')='active'))::int
        +(exists(select 1 from catalogue.course_intakes ci where ci.course_id=c.id and coalesce(ci.status,'active')='active'))::int
        +(exists(select 1 from catalogue.course_english_requirements er where er.course_id=c.id and coalesce(er.status,'active')='active'))::int
        +(c.description is not null and length(trim(c.description))>0)::int
      )*100.0/6.0 >= v_min_completeness)
  ), matched as materialized (
    select b.id,b.canonical_title,b.provider_name,b.field_of_study,b.updated_at,b.last_verified_at,b.provider_id from base b
  ), adm as materialized (
    -- CF-247 Course Catalogue columns (mandate 5 Nov 2026 17:31 §8): the Last data admitted and Adapter status sorts run set-based over the
    -- whole filtered set (one aggregate of the admission ledgers; one join of the adapter tables). Each is built only for its own sort.
    select a.course_id,max(a.at) at from security.course_admissions_v1() a where v_sort='admitted' group by a.course_id
  ), ads as materialized (
    select m.id course_id,security.course_adapter_rank_v1(security.course_adapter_state_from_v1(u.provider_id is not null,u.enabled,u.admit,
             p.leased_until>now(),p.status,p.read_status,r.before_read_status)) rank
    from matched m
    left join pipeline.uni_adapters u on u.provider_id=m.provider_id
    left join pipeline.coverage_course_pages p on p.course_id=m.id
    left join (select distinct on (x.course_id) x.course_id,x.before_read_status from pipeline.uni_adapter_results x
               where v_sort='adapter' order by x.course_id,x.at desc,x.id desc) r on r.course_id=m.id
    where v_sort='adapter'
  ), numbered as (
    -- CF-247 W34 (30 Oct 2026): the filters run once into the matching ids with their sort keys only; the total is their count and
    -- the page is the ordered ids; the page's rows are then read in full. Before, every matching course was carried with all its
    -- columns (the description too) through a window count and a full sort (1.0 to 1.6 s idle, 3.0 s under load).
    -- Same rows, same order, same fields, same total.
    select k.id,k.ord,(select count(*) from matched) total_count
    from unnest(array(select numbered.id from matched numbered left join adm on adm.course_id=numbered.id left join ads on ads.course_id=numbered.id order by
      -- 24 Oct 2026 (UI audit Phase 2): the International fee and City columns sort; one indexed lookup per filtered course
      case when v_sort='intl_fee' and v_dir='asc' then (select cf.amount from catalogue.course_fees cf where cf.course_id=numbered.id and cf.fee_type='provider_current_tuition' and cf.audience='international' and cf.status='active' order by cf.fee_year desc nulls last, cf.updated_at desc limit 1) end asc nulls last,
      case when v_sort='intl_fee' and v_dir='desc' then (select cf.amount from catalogue.course_fees cf where cf.course_id=numbered.id and cf.fee_type='provider_current_tuition' and cf.audience='international' and cf.status='active' order by cf.fee_year desc nulls last, cf.updated_at desc limit 1) end desc nulls last,
      -- 12 Nov 2026 (QA of #1081): with the Course description filter the fee and completeness sorts run here too
      case when v_sort='fee' and v_dir='asc' then (select cf.amount from catalogue.course_fees cf where cf.course_id=numbered.id and cf.fee_type='tuition' and cf.basis='registered_total_course' and coalesce(cf.status,'active')='active' order by cf.source_snapshot_at desc nulls last,cf.last_verified_at desc nulls last,cf.created_at desc limit 1) end asc nulls last,
      case when v_sort='fee' and v_dir='desc' then (select cf.amount from catalogue.course_fees cf where cf.course_id=numbered.id and cf.fee_type='tuition' and cf.basis='registered_total_course' and coalesce(cf.status,'active')='active' order by cf.source_snapshot_at desc nulls last,cf.last_verified_at desc nulls last,cf.created_at desc limit 1) end desc nulls last,
      case when v_sort='completeness' then security.course_completeness_v1(numbered.id) end * case when v_dir='desc' then -1 else 1 end asc nulls last,
      case when v_sort='city' and v_dir='asc' then (select min(lower(ca.city)) from catalogue.course_campuses cc join catalogue.campuses ca on ca.id=cc.campus_id where cc.course_id=numbered.id and nullif(btrim(ca.city),'') is not null) end asc nulls last,
      case when v_sort='city' and v_dir='desc' then (select min(lower(ca.city)) from catalogue.course_campuses cc join catalogue.campuses ca on ca.id=cc.campus_id where cc.course_id=numbered.id and nullif(btrim(ca.city),'') is not null) end desc nulls last,
      case when v_sort='admitted' and v_dir='asc' then adm.at end asc nulls last,
      case when v_sort='admitted' and v_dir='desc' then adm.at end desc nulls last,
      case when v_sort='adapter' and v_dir='asc' then ads.rank end asc nulls last,
      case when v_sort='adapter' and v_dir='desc' then ads.rank end desc nulls last,
      case when v_sort='course' and v_dir='asc' then lower(canonical_title) end asc,
      case when v_sort='course' and v_dir='desc' then lower(canonical_title) end desc,
      case when v_sort='provider' and v_dir='asc' then lower(provider_name) end asc,
      case when v_sort='provider' and v_dir='desc' then lower(provider_name) end desc,
      case when v_sort='field' and v_dir='asc' then lower(coalesce(field_of_study,'')) end asc,
      case when v_sort='field' and v_dir='desc' then lower(coalesce(field_of_study,'')) end desc,
      case when v_sort='modified' and v_dir='asc' then updated_at end asc,
      case when v_sort='modified' and v_dir='desc' then updated_at end desc,
      case when v_sort='verified' and v_dir='asc' then last_verified_at end asc nulls first,
      case when v_sort='verified' and v_dir='desc' then last_verified_at end desc nulls last,
      lower(canonical_title),id
    limit v_limit offset v_offset)) with ordinality k(id,ord)
  ), paged as (
    select
      c.id,c.stable_key,c.canonical_title,c.display_title,c.course_code,c.course_url,
      c.lifecycle_status,c.publication_status,c.last_verified_at,c.created_at,c.updated_at,c.provider_id,
      c.duration_value,c.description,c.delivery_mode canonical_delivery_mode,c.open_to_international,c.open_to_domestic,
      coalesce(p.display_name,p.canonical_name) provider_name,
      co.iso_alpha2::text country_code,co.name country_name,co.default_currency_code::text currency_code,
      sl.code level_code,sl.name level_name,fos.code field_code,fos.name field_of_study,
      n.total_count,n.ord
    from numbered n
    join catalogue.courses c on c.id=n.id
    join catalogue.providers p on p.id=c.provider_id
    join ref.countries co on co.id=p.country_id
    left join ref.study_levels sl on sl.id=c.study_level_id
    left join ref.fields_of_study fos on fos.id=c.primary_field_id
  ), enriched as (
    select
      pg.id,pg.stable_key,pg.canonical_title,pg.display_title,pg.course_code,pg.course_url,
      pg.lifecycle_status,pg.publication_status,pg.last_verified_at,pg.created_at,pg.updated_at,pg.provider_id,
      pg.open_to_international,pg.open_to_domestic,coalesce(ssc.identifier,pg.course_code) display_code,case when ssc.identifier is not null then 'studysearch' else 'own' end code_kind,
      pg.provider_name,pg.country_code,pg.country_name,pg.currency_code,pg.level_code,pg.level_name,pg.field_code,pg.field_of_study,
      coalesce(nullif(btrim(pg.canonical_delivery_mode),''),case when dm.mode_count=1 then dm.single_mode when dm.mode_count>1 then dm.mode_count::text||' modes' end) delivery_mode,
      fee.amount fee_amount,fee.currency_code::text fee_currency,ifee.amount intl_fee_amount,ifee.currency_code::text intl_fee_currency,ifee.fee_year intl_fee_year,ifee.basis intl_fee_basis,gcity.city_names,
      sig.has_registration,sig.has_structure,sig.has_fee,sig.has_intake,sig.has_english,sig.has_description,
      round(((sig.has_registration::int+sig.has_structure::int+sig.has_fee::int+sig.has_intake::int+sig.has_english::int+sig.has_description::int)*100.0/6.0)::numeric,2) completeness_score_v2,
      round(((sig.has_registration::int+sig.has_structure::int+sig.has_fee::int+sig.has_intake::int+sig.has_english::int+sig.has_description::int)*100.0/6.0)::numeric,2) completeness_score,
      sch.has_scholarship,lnk.has_link,(coalesce(geo.region_count,0)>0 or psd.id is not null) has_state,
      coalesce(geo.campus_count,0) campus_count,
      case when geo.region_count=1 then geo.single_code when coalesce(geo.region_count,0)=0 then psd.code else null end subdivision_code,
      case when geo.region_count=1 then geo.single_name when geo.region_count>1 then geo.region_count::text||' regions' else psd.name end subdivision_name,
      case when coalesce(geo.region_count,0)>0 then geo.region_count when psd.id is not null then 1 else 0 end region_count,
      case when coalesce(geo.region_count,0)>0 then 'campus' when psd.id is not null then 'provider' else null end region_source,
      (d.course_id is not null) search_projected,d.publication_status search_projection_status,d.completeness_score search_projection_completeness,
      d.projection_version search_projection_version,d.catalogue_generation search_catalogue_generation,d.updated_at search_projection_updated_at,
      d.generated_at search_projection_generated_at,d.has_fee search_has_fee,d.has_intake search_has_intake,d.has_english search_has_english,d.has_scholarship search_has_scholarship,
      security.provider_university_groups(pg.provider_id) university_groups,
      pg.total_count,pg.ord
    from paged pg
    left join search.course_documents d on d.course_id=pg.id
    left join lateral (
      select cf.amount,cf.currency_code from catalogue.course_fees cf
      where cf.course_id=pg.id and cf.fee_type='tuition' and cf.basis='registered_total_course' and coalesce(cf.status,'active')='active'
      order by cf.source_snapshot_at desc nulls last,cf.last_verified_at desc nulls last,cf.created_at desc limit 1
    ) fee on true
    -- 23 Oct 2026 (Platform Admin 12:52): the international fee a provider publishes, and the campus cities
    left join lateral (select cf.amount, cf.currency_code, cf.fee_year, cf.basis from catalogue.course_fees cf where cf.course_id=pg.id and cf.fee_type='provider_current_tuition'
      and cf.audience='international' and cf.status='active' order by cf.fee_year desc nulls last, cf.updated_at desc limit 1) ifee on true
    left join lateral (select string_agg(distinct ca.city, ', ') city_names from catalogue.course_campuses cc join catalogue.campuses ca on ca.id=cc.campus_id
      where cc.course_id=pg.id and nullif(btrim(ca.city),'') is not null) gcity on true
    cross join lateral (
      select
        exists(select 1 from catalogue.course_registrations r where r.course_id=pg.id) has_registration,
        (pg.duration_value is not null or exists(select 1 from catalogue.course_academic_options a where a.course_id=pg.id)) has_structure,
        exists(select 1 from catalogue.course_fees cf where cf.course_id=pg.id and coalesce(cf.status,'active')='active') has_fee,
        exists(select 1 from catalogue.course_intakes ci where ci.course_id=pg.id and coalesce(ci.status,'active')='active') has_intake,
        exists(select 1 from catalogue.course_english_requirements er where er.course_id=pg.id and coalesce(er.status,'active')='active') has_english,
        (pg.description is not null and length(trim(pg.description))>0) has_description
    ) sig
    cross join lateral (select exists(select 1 from scholarship.scopes ss where coalesce(ss.include_exclude,'include')='include' and (ss.course_id=pg.id or (ss.scope_type='provider' and ss.provider_id=pg.provider_id))) has_scholarship) sch
    cross join lateral (select exists(select 1 from catalogue.course_links l where l.link_type = 'official_course' and l.course_id=pg.id and l.status='active') has_link) lnk
    left join lateral (
      select count(distinct cc.campus_id)::int campus_count,count(distinct sd.id)::int region_count,min(sd.code) single_code,min(sd.name) single_name
      from catalogue.course_campuses cc join catalogue.campuses ca on ca.id=cc.campus_id left join ref.subdivisions sd on sd.id=ca.subdivision_id where cc.course_id=pg.id
    ) geo on true
    left join ref.subdivisions psd on psd.id=(select p2.subdivision_id from catalogue.providers p2 where p2.id=pg.provider_id)
    left join lateral (select i.identifier from catalogue.course_identifiers i where i.course_id=pg.id and i.scheme='studysearch'
      and not exists (select 1 from catalogue.course_identifiers j join ref.course_code_schemes s on s.scheme=j.scheme and s.printed where j.course_id=pg.id) limit 1) ssc on true
    left join lateral (
      select count(distinct cc.delivery_mode)::int mode_count,min(cc.delivery_mode) single_mode
      from catalogue.course_campuses cc where cc.course_id=pg.id and cc.delivery_mode is not null and btrim(cc.delivery_mode)<>''
    ) dm on true
  )
  select jsonb_build_object(
    'items',coalesce(jsonb_agg(to_jsonb(e)-'total_count'-'ord' order by e.ord),'[]'::jsonb),
    'total',coalesce(max(total_count),0),'limit',v_limit,'offset',v_offset,'sort',v_sort,'direction',v_dir,
    'execution_profile','paged_enrichment_v3'
  ) into v_result from enriched e;
  return v_result;
end
$$;


