CREATE OR REPLACE FUNCTION "security"."aer_closure_evidence_v1"("p_cause" "text", "p_provider" "uuid", "p_source" "uuid", "p_level" "text", "p_scope_kind" "text" DEFAULT NULL::"text", "p_scope_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_n bigint;
begin
  if p_scope_kind = 'review_items' then
    -- no pending item of this provider is classified with this defect any more (settled, reclassified or ready)
    select count(*) into v_n from pipeline.aer_review_readiness z
     where z.provider_id = p_provider and z.root_cause = p_cause and z.readiness = p_scope_key and z.settled_at is null;
    return case when v_n = 0 then jsonb_build_object('basis', 'no pending review item with this defect', 'checked_at', now()) end;
  end if;
  if p_cause in ('non_country_heading', 'requirement_type_columns', 'reader_omission', 'unscaled_column', 'pdf_table_layout', 'policy_hold',
                 'extraction_failed', 'manifest_unparsed', 'not_extracted') then
    -- a later run of the same source finished, and its read is checked complete against the source's own table manifest
    -- (or the page has no table and rows were read)
    select r1.id, r1.state, r1.content_hash, r1.result->'completeness' c, jsonb_array_length(coalesce(r1.result->'rows', '[]'::jsonb)) n_rows
      into r from pipeline.entry_matrix_runs r1 where r1.source_id = p_source order by r1.created_at desc limit 1;
    if r.id is null or r.state <> 'done' then return null; end if;
    if coalesce(r.c->>'status', '') = 'complete' or (coalesce(r.c->>'status', '') = 'not_applicable' and r.n_rows > 0) then
      return jsonb_build_object('basis', 'later run checked against the source manifest', 'run_id', r.id, 'content_hash', r.content_hash,
        'completeness', r.c->>'status', 'expected', r.c->'expected', 'matched', r.c->'matched', 'rows_read', r.n_rows,
        'active_rows', (select count(*) from catalogue.provider_entry_matrix m where m.run_id = r.id and m.status = 'active'));
    end if;
    return null;
  elsif p_cause = 'source_unreadable' then
    select s.status, s.read_at into r from pipeline.entry_matrix_sources s where s.id = p_source;
    return case when r.status = 'read' then jsonb_build_object('basis', 'source now read', 'read_at', r.read_at) end;
  elsif p_cause = 'stale_source' then
    select s.status, s.read_at into r from pipeline.entry_matrix_sources s where s.id = p_source;
    return case when r.read_at >= now() - make_interval(days => security.pipeline_num_v1('aer.stale_source_days', 90)::int)
                then jsonb_build_object('basis', 'source read again', 'read_at', r.read_at) end;
  elsif p_cause = 'no_source' then
    select count(*) into v_n from pipeline.entry_matrix_sources s where s.provider_id = p_provider;
    return case when v_n > 0 then jsonb_build_object('basis', 'source recorded', 'sources', v_n) end;
  elsif p_cause = 'awaiting_layer4' then
    select (select count(*) from catalogue.provider_entry_matrix m where m.provider_id = p_provider and m.status = 'proposed')
         + (select count(*) from catalogue.course_entry_requirements x join catalogue.courses c on c.id = x.course_id where c.provider_id = p_provider and x.status = 'proposed') into v_n;
    return case when v_n = 0 then jsonb_build_object('basis', 'nothing waits for Layer 4', 'proposed', 0) end;
  elsif p_cause = 'course_read_held' then
    select count(*) into v_n from pipeline.aer_course_outcomes o join catalogue.courses c on c.id = o.course_id left join ref.study_levels l on l.id = c.study_level_id
     where o.provider_id = p_provider and o.outcome = 'source_unreadable' and coalesce(l.short_code, 'none') = coalesce(p_level, 'none');
    return case when v_n = 0 then jsonb_build_object('basis', 'no course read held at this level', 'held', 0) end;
  elsif p_cause in ('consumer_unevidenced', 'consumer_unadmitted', 'consumer_number_without_scale') then
    -- the current findings no longer hold the provider for this check: no offending active row
    return jsonb_build_object('basis', 'no offending active row', 'checked_at', now());
  end if;
  return null;
end $$;


ALTER FUNCTION "security"."aer_closure_evidence_v1"("p_cause" "text", "p_provider" "uuid", "p_source" "uuid", "p_level" "text", "p_scope_kind" "text", "p_scope_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_closure_evidence_v1"("p_cause" "text", "p_provider" "uuid", "p_source" "uuid", "p_level" "text", "p_scope_kind" "text", "p_scope_key" "text") IS 'CF-247 AER Phase B: the evidence that closes a finding that is no longer found (mandate §12: auto-close only where verified evidence proves resolution); null keeps it open.';



CREATE OR REPLACE FUNCTION "security"."aer_conditions_v1"("p" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v jsonb := coalesce(p, '{}'::jsonb); v_item jsonb;
begin
  if jsonb_typeof(v) <> 'object' then raise exception 'conditions must be a set of named parts' using errcode = '22023'; end if;
  if exists (select 1 from jsonb_object_keys(v) k where k not in ('best_n', 'subject_minimums', 'alternatives')) then
    raise exception 'conditions take only: best of N subjects, subject minimums, alternative routes' using errcode = '22023'; end if;
  if v ? 'best_n' and v->'best_n' <> 'null'::jsonb and (jsonb_typeof(v->'best_n') <> 'number' or (v->>'best_n')::numeric not between 1 and 20 or (v->>'best_n')::numeric % 1 <> 0) then
    raise exception 'best of N subjects must be a whole number from 1 to 20' using errcode = '22023'; end if;
  for v_item in select * from jsonb_array_elements(coalesce(v->'subject_minimums', '[]'::jsonb)) loop
    if jsonb_typeof(v_item) <> 'object' or nullif(btrim(v_item->>'subject'), '') is null then raise exception 'each subject minimum needs a subject' using errcode = '22023'; end if;
  end loop;
  for v_item in select * from jsonb_array_elements(coalesce(v->'alternatives', '[]'::jsonb)) loop
    if jsonb_typeof(v_item) <> 'object' or nullif(btrim(v_item->>'route'), '') is null then raise exception 'each alternative needs its route' using errcode = '22023'; end if;
  end loop;
  return jsonb_build_object('best_n', case when v->'best_n' is null or v->'best_n' = 'null'::jsonb then null else v->'best_n' end,
    'subject_minimums', coalesce((select jsonb_agg(jsonb_build_object('subject', btrim(x->>'subject'), 'min_grade', nullif(btrim(x->>'min_grade'), ''))) from jsonb_array_elements(coalesce(v->'subject_minimums', '[]'::jsonb)) x), '[]'::jsonb),
    'alternatives', coalesce((select jsonb_agg(jsonb_build_object('route', btrim(x->>'route'), 'min_grade', nullif(btrim(x->>'min_grade'), ''))) from jsonb_array_elements(coalesce(v->'alternatives', '[]'::jsonb)) x), '[]'::jsonb));
end $$;


ALTER FUNCTION "security"."aer_conditions_v1"("p" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_conditions_v1"("p" "jsonb") IS 'CF-247 AER workspace: validates and normalises a matrix row''s structured conditions (W4).';



CREATE OR REPLACE FUNCTION "security"."aer_course_counts_verify_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 workstream C: verify of remedy aer_course_counts (authority release). Passed when the AER reader counts eligible courses again: the
  -- stored coverage (written by aer-reconcile) and a fresh read both have courses for the providers that have active courses.
  with f as (select count(*) filter (where s.courses_eligible > 0) fresh_with_courses, count(*) filter (where s.course_req_active + s.course_req_proposed > 0) fresh_with_req
               from security.aer_provider_states_v1() s),
  t as (select count(*) filter (where c.courses_eligible > 0) stored_with_courses from pipeline.aer_provider_coverage c where c.eligible),
  a as (select count(distinct c.provider_id) with_active_courses from catalogue.courses c join security.aer_eligible_v1() e on e.provider_id = c.provider_id
         where c.lifecycle_status = 'active' and c.open_to_international is not false)
  select jsonb_build_object('passed', f.fresh_with_courses > 0 and t.stored_with_courses > 0 and f.fresh_with_courses >= a.with_active_courses,
                            'measure', jsonb_build_object('fresh_with_courses', f.fresh_with_courses, 'fresh_with_requirements', f.fresh_with_req,
                                                          'stored_with_courses', t.stored_with_courses, 'providers_with_active_courses', a.with_active_courses),
                            'evidence', jsonb_build_object('issue', p_issue, 'at', now()))
    from f, t, a
$$;


ALTER FUNCTION "security"."aer_course_counts_verify_v1"("p_issue" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_course_counts_verify_v1"("p_issue" bigint) IS 'CF-247 workstream C: verify of remedy aer_course_counts: the AER coverage reader counts eligible courses (fresh and stored). Returns {passed, measure, evidence}. Read-only.';



CREATE OR REPLACE FUNCTION "security"."aer_course_outcomes_build_v1"("p_source" "text" DEFAULT 'job'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_t timestamptz := clock_timestamp(); v_n int; v_by jsonb;
begin
  -- single flight: an overlapping run does not build a second time
  if not pg_try_advisory_xact_lock(hashtextextended('cf247.aer.outcome_register', 0)) then return jsonb_build_object('state', 'busy'); end if;
  delete from pipeline.aer_course_outcomes;
  insert into pipeline.aer_course_outcomes(course_id, provider_id, country, provider_name, provider_published, course_title, course_code, outcome, detail,
                                           course_url, page_status, identity_basis, read_state, read_reason, review_item_id, built_at)
  with scope as (select el.course_id from security.course_entry_eligible_v1() el),  -- CF-247 D6 (3 Nov 2026): the entry-reading eligibility rules
  c as (
    select c.id, c.provider_id, k.iso_alpha2 cc, coalesce(p.display_name, p.canonical_name) pname, p.publication_status = 'published' pub,
           coalesce(c.display_title, c.canonical_title) title, c.course_code, g.status gs, g.url, g.identity_basis,
           (e.storage_path is not null) stored,
           (g.status = 'bound' and security.coverage_identity_allowed(c.provider_id, g.identity_basis, 'entry_requirements')) id_ok,
           exists (select 1 from scope s where s.course_id = c.id) in_scope
      from catalogue.courses c
      join catalogue.providers p on p.id = c.provider_id
      join ref.countries k on k.id = p.country_id
      left join pipeline.coverage_course_pages g on g.course_id = c.id
      left join pipeline.evidence_artifacts e on e.id = g.evidence_id
     where c.lifecycle_status = 'active'
       and coalesce(security.toolset_setting('pipeline', 'entry.course_read_countries'), '["AU"]'::jsonb) ? k.iso_alpha2),
  li as (select distinct on (f.course_id) f.course_id, f.state, f.reason from pipeline.field_enrich_items f
          where f.field = 'entry_requirements' order by f.course_id, f.updated_at desc),
  cpend as (select distinct on (i.entity_id) i.entity_id course_id, i.id from pipeline.layer4_review_items i
             where i.status = 'pending' and i.field_code = 'course_entry_first_read' order by i.entity_id, i.created_at),
  ppend as (select i.entity_id provider_id, count(*) n, (array_agg(i.id order by i.created_at))[1] first_id from pipeline.layer4_review_items i
             where i.status = 'pending' and i.field_code in ('entry_matrix_first_run', 'entry_matrix_change') group by i.entity_id),
  mact as (select m.provider_id, count(*) n from catalogue.provider_entry_matrix m where m.status = 'active' group by 1),
  cact as (select r.course_id, count(*) n from catalogue.course_entry_requirements r where r.status = 'active' group by 1)
  select c.id, c.provider_id, c.cc, c.pname, coalesce(c.pub, false), c.title, c.course_code, o.outcome, o.detail,
         c.url, c.gs, c.identity_basis, li.state, li.reason,
         case when o.outcome = 'awaiting_review' then coalesce(cp.id, pp.first_id) when cp.id is not null then cp.id end, now()
    from c
    left join li on li.course_id = c.id
    left join cpend cp on cp.course_id = c.id
    left join ppend pp on pp.provider_id = c.provider_id
    left join mact ma on ma.provider_id = c.provider_id
    left join cact ca on ca.course_id = c.id
    cross join lateral (select case
        when ca.n is not null then 'admitted_course'
        when ma.n is not null then 'admitted_provider'
        when cp.id is not null then 'awaiting_review'
        when li.state = 'skipped' then 'no_requirement_published'
        when pp.n is not null then 'awaiting_review'
        when c.gs is null then 'no_course_url'
        when c.gs <> 'bound' or not c.id_ok then 'identity_unresolved'
        when li.state = 'failed' or not c.stored then 'source_unreadable'
        else 'excluded' end outcome) oc
    cross join lateral (select oc.outcome, case oc.outcome
        when 'admitted_course' then ca.n || ' active course-level row(s)'
        when 'admitted_provider' then 'provider table active (' || ma.n || ' rows): the resolver answers by country'
             || case when cp.id is not null then '; the course''s own read also waits in Layer 4' else '' end
        when 'awaiting_review' then case when cp.id is not null then 'the course''s read waits in Layer 4 (course entry first read)'
             else 'the provider''s table waits in Layer 4 (' || pp.n || ' item(s))' end
        when 'no_requirement_published' then 'read finished, nothing kept: ' || coalesce(li.reason, 'no reason recorded')
             || case when pp.n is not null then '; the provider''s table waits in Layer 4' else '' end
        when 'no_course_url' then 'no official course page found'
        when 'identity_unresolved' then case when c.gs <> 'bound' then 'course page ' || c.gs
             else 'identity basis ' || coalesce(c.identity_basis, 'none') || ' is not accepted for entry requirements' end
        when 'source_unreadable' then case when li.state = 'failed' then 'read held or failed: ' || coalesce(li.reason, 'no reason recorded')
             else 'the bound course page has no stored copy' end
        else case when not c.in_scope then 'outside the entry-reading rules (provider not AER-eligible or hidden, country switched off, or a manual lock)'
             else 'eligible, not read: course reads are held (AER production-closure mandate, 30 Oct 2026)' end end detail) o;
  get diagnostics v_n = row_count;
  select coalesce(jsonb_object_agg(x.outcome, x.n), '{}'::jsonb) into v_by from (select a.outcome, count(*) n from pipeline.aer_course_outcomes a group by 1) x;
  insert into pipeline.aer_course_outcome_builds(built_at, finished_at, took_ms, courses, by_outcome, source)
  values (v_t, clock_timestamp(), round(extract(epoch from clock_timestamp() - v_t) * 1000)::int, v_n, v_by, p_source);
  return jsonb_build_object('state', 'built', 'courses', v_n, 'took_ms', round(extract(epoch from clock_timestamp() - v_t) * 1000)::int);
end $$;


ALTER FUNCTION "security"."aer_course_outcomes_build_v1"("p_source" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_course_outcomes_build_v1"("p_source" "text") IS 'CF-247 AER production closure C1: rebuilds pipeline.aer_course_outcomes (one primary entry-requirement outcome per active course of the entry-read countries) and records the build. Read only on every source table.';



CREATE OR REPLACE FUNCTION "security"."aer_course_outcomes_refresh_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_last timestamptz;
begin
  select max(b.built_at) into v_last from pipeline.aer_course_outcome_builds b;
  if v_last is not null
     -- fixed: fire guard (the job checks every 5 minutes; a build due now is not put off by a few seconds of start jitter)
     and v_last > clock_timestamp() - make_interval(mins => security.pipeline_num_v1('aer.outcome_register_every_minutes', 60)::int) + interval '30 seconds' then
    return jsonb_build_object('state', 'fresh', 'built_at', v_last);
  end if;
  return security.aer_course_outcomes_build_v1('job');
end $$;


ALTER FUNCTION "security"."aer_course_outcomes_refresh_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_course_outcomes_refresh_v1"() IS 'CF-247 AER production closure C1: job aer-outcome-register; rebuilds the course outcome register when it is older than aer.outcome_register_every_minutes.';



CREATE OR REPLACE FUNCTION "security"."aer_course_population_v1"() RETURNS TABLE("course_id" "uuid", "provider_id" "uuid", "country" "text", "provider_name" "text", "tier" integer, "prio" bigint, "title" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ select * from security.aer_course_population_v1(null::uuid) $$;


ALTER FUNCTION "security"."aer_course_population_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_course_population_v1"() IS 'CF-247 entry reading (Platform Admin mandate 3 Nov 2026 13:09 D6): the courses entry reading may read, one rule for job aer-scheduled-read and Read next batch (security.course_entry_eligible_v1): an AER-eligible (security.aer_eligible_v1), unhidden provider of a country switched on (aer.schedule_countries less aer.schedule_countries_off); an active course with a bound official page whose stored copy exists and whose identity admits entry requirements; no manual lock in aer.schedule_lock_fields. prio orders providers (aer.priority_provider_types first, then by name). Replaces the fixed list entry.course_read_providers. Read-only.';



CREATE OR REPLACE FUNCTION "security"."aer_course_population_v1"("p_provider" "uuid") RETURNS TABLE("course_id" "uuid", "provider_id" "uuid", "country" "text", "provider_name" "text", "tier" integer, "prio" bigint, "title" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with s as (select coalesce(security.toolset_setting('pipeline', 'aer.schedule_lock_fields'), '[]'::jsonb) locks,
                    coalesce(security.toolset_setting('pipeline', 'aer.priority_provider_types'), '[]'::jsonb) pt,
                    -- CF-247 workstream C (Integration Controller 3 Nov 2026 18:30): followed providers, then the largest AER shortfall, first
                    coalesce((security.toolset_setting('pipeline', 'coverage.aer_reader_priority_on') #>> '{}')::boolean, false) gap_first,
                    coalesce(security.toolset_setting('pipeline', 'coverage.aer_priority_providers'), '[]'::jsonb) followed),
  pv as (select e.provider_id, e.country, coalesce(p.display_name, p.short_name, p.canonical_name) pname,
                case when s.gap_first and s.followed ? e.provider_id::text then -1000000
                     when s.gap_first and coalesce(k.shortfall, 0) > 0 then -least(k.shortfall, 999999)
                     when s.pt ? coalesce(t.code, '') then 1 else 2 end tier
           from security.aer_eligible_v1() e
           join catalogue.providers p on p.id = e.provider_id
           left join ref.provider_types t on t.id = p.provider_type_id
           left join pipeline.coverage_provider_reconciliation k on k.domain = 'aer' and k.provider_id = e.provider_id
          cross join s
          where (p_provider is null or e.provider_id = p_provider)
            and (security.aer_schedule_country_v1(e.country)->>'on')::boolean
            and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = e.provider_id)),
  pr as (select pv.*, dense_rank() over (order by pv.tier, pv.pname, pv.provider_id) prio from pv)
  select c.id, pr.provider_id, pr.country, pr.pname, pr.tier, pr.prio, c.canonical_title
    from pr
    join catalogue.courses c on c.provider_id = pr.provider_id and c.lifecycle_status = 'active'
    join pipeline.coverage_course_pages g on g.course_id = c.id and g.status = 'bound'
    join pipeline.evidence_artifacts a on a.id = g.evidence_id and a.storage_path is not null
   cross join s
   where (security.coverage_identity_allowed(c.provider_id, g.identity_basis, 'entry_requirements') or c.id in (select t.course_id from security.aer_title_identity_courses_v1() t)) -- 20261111040000 (set-based: 20261111060000): own-site title and level match (Platform Admin decision 10 Nov 2026)
     and not exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = c.id and (s.locks ? l.field or l.field = 'all'))
$$;


ALTER FUNCTION "security"."aer_course_population_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_course_population_v1"("p_provider" "uuid") IS 'CF-247 AER read now (10 Nov 2026): the eligibility rules of the scheduled entry reading (security.aer_course_population_v1()) for one provider, or all providers when null. The no-argument form delegates here, so the rules are written once. Read only.';



CREATE OR REPLACE FUNCTION "security"."aer_coverage_read_v1"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_day date; v_pid uuid := nullif(p_args->>'provider_id', '')::uuid; v_size int; v_off int; v_q text := nullif(btrim(coalesce(p_args->>'q', '')), '');
        v_sev text := nullif(p_args->>'severity', ''); v_cc text := nullif(upper(coalesce(p_args->>'country', '')), ''); v_cause text := nullif(p_args->>'root_cause', '');
        v_disp text := nullif(p_args->>'disposition', '');
begin
  v_size := greatest(1, least(coalesce((p_args->>'page_size')::int, 50), 100));  -- fixed: a page is at most 100 rows (W11)
  v_off := greatest(0, coalesce((p_args->>'offset')::int, 0));
  select max(d.day) into v_day from pipeline.aer_coverage_daily d;
  if p_action = 'coverage_provider' then
    return jsonb_build_object(
      'provider', (select jsonb_build_object('id', p.id, 'name', coalesce(p.display_name, p.short_name), 'country', e.country, 'eligible', e.provider_id is not null)
                     from catalogue.providers p left join security.aer_eligible_v1() e on e.provider_id = p.id where p.id = v_pid),
      'sources', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'url', s.url, 'title', s.title, 'rank', s.rank, 'status', s.status, 'read_at', s.read_at,
                     'error', left(s.error, 200), 'shape', mf.shape, 'scope_country', mf.scope_country, 'expected', mf.expected_cells, 'matched', mf.matched_cells,
                     'run_state', mf.run_state, 'reason', mf.reason) order by s.rank, s.title), '[]'::jsonb)
                    from pipeline.entry_matrix_sources s
                    left join lateral (select m.* from pipeline.aer_source_manifests m where m.source_id = s.id order by m.computed_at desc limit 1) mf on true
                   where s.provider_id = v_pid),
      'findings', (select coalesce(jsonb_agg(jsonb_build_object('id', g.id, 'root_cause', g.root_cause, 'label', rc.label, 'severity', g.severity, 'state', g.state,
                     'scope_kind', g.scope_kind, 'scope', g.scope_label, 'study_level', g.study_level, 'owner_role', g.owner_role, 'next_action', g.next_action,
                     'first_seen', g.first_seen, 'last_seen', g.last_seen, 'resolved_at', g.resolved_at, 'reopen_count', g.reopen_count, 'evidence', g.evidence,
                     'closure_evidence', g.closure_evidence) order by g.state = 'resolved', g.severity, g.root_cause), '[]'::jsonb)
                     from pipeline.aer_gap_findings g join pipeline.aer_gap_root_causes rc on rc.code = g.root_cause where g.provider_id = v_pid),
      'active', (select jsonb_build_object('rows', count(*), 'countries', coalesce(jsonb_agg(distinct m.country_code), '[]'::jsonb),
                                           'qualifications', count(distinct lower(m.qualification_name)), 'levels', coalesce(jsonb_agg(distinct m.level_label) filter (where m.level_label is not null), '[]'::jsonb))
                   from catalogue.provider_entry_matrix m where m.provider_id = v_pid and m.status = 'active'),
      'course', (select jsonb_build_object('active', count(*) filter (where x.status = 'active'), 'proposed', count(*) filter (where x.status = 'proposed'))
                   from catalogue.course_entry_requirements x join catalogue.courses c on c.id = x.course_id where c.provider_id = v_pid),
      'queue', (select to_jsonb(c) - 'evidence' from pipeline.aer_provider_coverage c where c.provider_id = v_pid),
      'evidence', (select c.evidence from pipeline.aer_provider_coverage c where c.provider_id = v_pid));
  end if;
  return jsonb_build_object(
    'as_at', (select max(r.finished_at) from pipeline.aer_reconcile_runs r),
    'day', v_day,
    'job', (select jsonb_build_object('active', j.active, 'schedule', j.schedule) from cron.job j where j.jobname = 'aer-reconcile'),
    'last_run', (select to_jsonb(r) from (select r.id, r.started_at, r.finished_at, r.result from pipeline.aer_reconcile_runs r order by r.id desc limit 1) r),
    'measures', (select coalesce(jsonb_agg(to_jsonb(d) - 'run_id' order by d.country = 'ALL' desc, d.country), '[]'::jsonb) from pipeline.aer_coverage_daily d where d.day = v_day),
    'progress', (select coalesce(jsonb_agg(jsonb_build_object('days', w.n, 'day', d.day, 'discovery_n', d.discovery_n, 'extraction_n', d.extraction_n,
                   'admission_n', d.admission_n, 'consumer_n', d.consumer_n, 'eligible', d.eligible) order by w.n), '[]'::jsonb)
                   from unnest(array[7, 30]) w(n)  -- fixed: the mandate's 7- and 30-day progress windows
                   join lateral (select x.* from pipeline.aer_coverage_daily x where x.country = 'ALL' and x.day <= v_day - w.n order by x.day desc limit 1) d on true),
    'open', (select jsonb_build_object('P0', count(*) filter (where g.severity = 'P0'), 'P1', count(*) filter (where g.severity = 'P1'), 'P2', count(*) filter (where g.severity = 'P2'))
               from pipeline.aer_gap_findings g where g.state <> 'resolved'),
    'changes_7d', (select jsonb_build_object('opened', count(*) filter (where x.event = 'opened'), 'resolved', count(*) filter (where x.event = 'resolved'),
                                             'reopened', count(*) filter (where x.event = 'reopened'))
                     from pipeline.aer_gap_events x where x.at > now() - make_interval(days => 7)),  -- fixed: display window
    'root_causes', (select coalesce(jsonb_agg(z order by z.sev, z.providers desc), '[]'::jsonb) from (
                      select rc.code, rc.label, rc.severity, rc.severity sev, rc.owner_role, rc.next_action, count(distinct g.provider_id) providers, count(*) findings
                        from pipeline.aer_gap_findings g join pipeline.aer_gap_root_causes rc on rc.code = g.root_cause
                       where g.state <> 'resolved' group by rc.code) z),
    'population', (select r.result->'population' from pipeline.aer_reconcile_runs r where r.finished_at is not null order by r.id desc limit 1),
    'dispositions', (select coalesce(jsonb_object_agg(z.disposition, z.n), '{}'::jsonb) from (select c.disposition, count(*) n from pipeline.aer_provider_coverage c
                      where c.eligible and (v_cc is null or c.country = v_cc) group by 1) z),
    -- the gap queue, in its priority order (universities and tertiary providers first, held sources next to them)
    'providers', (with fl as (
                    select c.*, (select count(*) filter (where g.severity = 'P0') from pipeline.aer_gap_findings g where g.provider_id = c.provider_id and g.state <> 'resolved') p0,
                           (select count(*) filter (where g.severity = 'P1') from pipeline.aer_gap_findings g where g.provider_id = c.provider_id and g.state <> 'resolved') p1,
                           (select count(*) filter (where g.severity = 'P2') from pipeline.aer_gap_findings g where g.provider_id = c.provider_id and g.state <> 'resolved') p2,
                           (select g.next_action from pipeline.aer_gap_findings g where g.provider_id = c.provider_id and g.state <> 'resolved' order by g.severity, g.root_cause limit 1) next_action,
                           (select g.owner_role from pipeline.aer_gap_findings g where g.provider_id = c.provider_id and g.state <> 'resolved' order by g.severity, g.root_cause limit 1) owner_role
                      from pipeline.aer_provider_coverage c
                     where c.eligible and (v_cc is null or c.country = v_cc) and (v_q is null or coalesce(c.provider_name, '') ilike '%' || v_q || '%')
                       and (v_disp is null or c.disposition = v_disp) and (v_cause is null or v_cause = any (c.root_causes))
                       and (v_sev is null or exists (select 1 from pipeline.aer_gap_findings g where g.provider_id = c.provider_id and g.state <> 'resolved' and g.severity = v_sev)))
                  select jsonb_build_object('total', (select count(*) from fl), 'offset', v_off, 'page_size', v_size,
                    'items', coalesce((select jsonb_agg(jsonb_build_object('provider_id', f.provider_id, 'name', f.provider_name, 'country', f.country, 'type', f.provider_type,
                       'disposition', f.disposition, 'discovery', f.discovery_state, 'extraction', f.extraction_state, 'admission', f.admission_state,
                       'consumer_resolvable', f.consumer_resolvable, 'priority', f.priority_rank, 'tier', f.priority_tier, 'courses', f.courses_eligible,
                       'p0', f.p0, 'p1', f.p1, 'p2', f.p2, 'next_action', f.next_action, 'owner_role', f.owner_role, 'sources', f.sources, 'active_rows', f.matrix_active,
                       'course_active', f.course_req_active, 'held_scopes', f.held_scopes, 'disposition_since', f.disposition_since,
                       'primary_url', (select s.url from pipeline.entry_matrix_sources s where s.provider_id = f.provider_id and s.status = 'read' order by s.rank, s.created_at limit 1))
                       order by f.priority_rank)
                      from (select * from fl order by fl.priority_rank limit v_size offset v_off) f), '[]'::jsonb))),
    'alerts', (select coalesce(jsonb_agg(jsonb_build_object('check', p.check_key, 'title', p.title, 'first_seen', p.first_seen)), '[]'::jsonb)
                 from pipeline.platform_issues p where p.check_key like 'aer:%' and p.resolved_at is null),
    'readiness', (select coalesce(jsonb_object_agg(z.readiness, z.n), '{}'::jsonb) from (select r.readiness, count(*) n from pipeline.aer_review_readiness r
                    where r.settled_at is null group by 1) z),
    'weekly', security.aer_weekly_section_v1(date_trunc('week', now() at time zone 'Australia/Sydney')::date - 7),  -- fixed: the week just ended
    'weekly_email', coalesce((security.toolset_setting('pipeline', 'aer.weekly_email_enabled') #>> '{}')::boolean, false));
end $$;


ALTER FUNCTION "security"."aer_coverage_read_v1"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_coverage_read_v1"("p_action" "text", "p_args" "jsonb") IS 'CF-247 AER Phase B (mandate §13; B5): the AER overview (four measures with numerator and denominator, 7- and 30-day progress, open P0/P1/P2, opened/resolved/reopened, root causes) and the provider drill-down with next action and owner. Read through public.admin_aer(''coverage'' / ''coverage_provider''), Curator and above. Admin only; never part of the consumer API.';



CREATE OR REPLACE FUNCTION "security"."aer_coverage_v1"("p_providers" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("provider_id" "uuid", "country" "text", "provider_name" "text", "provider_type" "text", "disposition" "text", "measures" "jsonb", "categories" "jsonb", "gaps" "text"[], "shortfall" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 workstream C (P0 mandates 3 Nov 2026 §5/§12 and §8): each AER-eligible provider (security.aer_eligible_v1), plus every provider of a
  -- provider-level type in an AER country that the eligibility rule leaves out (so a major registered provider is never silently omitted), with
  -- what its sources list against what is held: entry-requirement sources and their manifests (published cells, countries and pathways named),
  -- matrix rows by applicant country, qualification (curriculum) and study level, the pathways in coverage.aer_pathways (IB, A Levels, Nepal and
  -- so on: a gap only where a source of the provider names the pathway), rows that are domestic only (never read as universal), course-level
  -- requirements on courses whose official page is bound, effective period, intakes and application deadlines. Each gap carries the input through
  -- which the scheduled AER reader can act on it (route). The AER disposition is read from pipeline.aer_provider_coverage. Read-only.
  with s as (select security.pipeline_num_v1('coverage.aer_course_min_pct', 20) cpct, security.pipeline_num_v1('coverage.intake_min_pct', 50) ipct,
                    security.pipeline_num_v1('coverage.deadline_min_pct', 25) dpct,
                    coalesce(security.toolset_setting('pipeline', 'coverage.provider_level_types'), '[]'::jsonb) pl),
  pw as (select k label, v pat from security.coverage_kv_v1('coverage.aer_pathways')),
  el as (select e.provider_id, e.country, true eligible from security.aer_eligible_v1() e
         union all
         select p.id, k.iso_alpha2::text, false from catalogue.providers p join ref.countries k on k.id = p.country_id join ref.provider_types t on t.id = p.provider_type_id
          cross join s
          where k.iso_alpha2::text in (select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'aer.eligible_countries'), '[]'::jsonb)))
            and p.lifecycle_status = 'active' and p.publication_status = 'published' and t.code in (select jsonb_array_elements_text(s.pl))
            and not exists (select 1 from security.aer_eligible_v1() e where e.provider_id = p.id)),
  pv as (select el.provider_id id, el.country cc, el.eligible, coalesce(p.display_name, p.short_name, p.canonical_name) nm, t.code ptype, p.enrols_international
           from el join catalogue.providers p on p.id = el.provider_id left join ref.provider_types t on t.id = p.provider_type_id
          where p_providers is null or el.provider_id = any (p_providers)),
  src as (select x.provider_id, count(*) n, count(*) filter (where x.status = 'read') nread, count(*) filter (where x.status = 'failed') nfail,
                md5(string_agg(x.url || '=' || coalesce(x.content_hash, ''), '|' order by x.url)) fp
            from pipeline.entry_matrix_sources x join pv on pv.id = x.provider_id group by 1),
  mf as (select distinct on (mm.source_id) mm.* from pipeline.aer_source_manifests mm join pv on pv.id = mm.provider_id order by mm.source_id, mm.computed_at desc),
  man as (select mf.provider_id, sum(coalesce(mf.expected_cells, 0)) expected, sum(coalesce(mf.matched_cells, 0)) matched, sum(coalesce(mf.omitted_cells, 0)) omitted,
                 array_remove(array_agg(distinct upper(mf.scope_country)), null) countries,
                 string_agg(coalesce(mf.heading, '') || ' ' || coalesce(mf.scope_label, '') || ' ' || coalesce(mf.sections::text, ''), ' ') txt
            from mf group by 1),
  mxr as (select m.* from catalogue.provider_entry_matrix m join pv on pv.id = m.provider_id),
  mx as (select m.provider_id, count(*) filter (where m.status = 'active') act, count(*) filter (where m.status = 'proposed') prop,
                count(*) filter (where m.status not in ('active', 'proposed')) other,
                array_remove(array_agg(distinct upper(m.country_code)) filter (where m.status in ('active', 'proposed')), null) countries,
                count(distinct upper(m.country_code)) filter (where m.status = 'active') countries_active,
                count(distinct lower(m.qualification_name)) filter (where m.status in ('active', 'proposed')) quals,
                count(distinct lower(m.qualification_name)) filter (where m.status = 'active') quals_active,
                count(distinct coalesce(m.study_level_id::text, m.aer_level, m.level_label)) filter (where m.status in ('active', 'proposed')) levels,
                count(*) filter (where m.status in ('active', 'proposed') and (m.edition is not null or m.intake_year is not null)) dated,
                count(*) filter (where m.status in ('active', 'proposed') and m.audience = 'domestic') domestic,
                count(*) filter (where m.status in ('active', 'proposed') and m.audience <> 'domestic') intl
           from mxr m group by 1),
  pwh as (select m.provider_id, pw.label from mxr m cross join pw
           where m.status in ('active', 'proposed') and (coalesce(m.country_code, '') || ' ' || coalesce(m.qualification_name, '') || ' ' || coalesce(m.level_label, '')) ~* pw.pat
           group by 1, 2),
  pwl as (select man.provider_id, pw.label from man cross join pw where man.txt ~* pw.pat),
  co as (select c.provider_id, c.id from catalogue.courses c join pv on pv.id = c.provider_id where c.lifecycle_status = 'active' and c.open_to_international is not false),
  cs as (select co.provider_id, count(*) courses,
                count(*) filter (where exists (select 1 from pipeline.aer_course_outcomes o where o.course_id = co.id and o.page_status = 'bound')) paged,
                count(*) filter (where exists (select 1 from catalogue.course_entry_requirements r where r.course_id = co.id and r.status = 'active')) req_active,
                count(*) filter (where exists (select 1 from catalogue.course_entry_requirements r where r.course_id = co.id and r.status in ('active', 'proposed'))) req_any,
                count(*) filter (where exists (select 1 from catalogue.course_entry_requirements r where r.course_id = co.id and r.status in ('active', 'proposed'))
                                   and not exists (select 1 from catalogue.course_entry_requirements r where r.course_id = co.id and r.status in ('active', 'proposed') and r.audience <> 'domestic')) req_domestic_only,
                count(*) filter (where exists (select 1 from catalogue.course_entry_requirements r where r.course_id = co.id and r.status in ('active', 'proposed') and r.country_id is not null)) req_country,
                count(*) filter (where exists (select 1 from catalogue.course_intakes i where i.course_id = co.id and i.status = 'active' and (i.start_date is not null or nullif(btrim(coalesce(i.intake_label, '')), '') is not null))) intake,
                count(*) filter (where exists (select 1 from catalogue.course_intakes i where i.course_id = co.id and i.status = 'active' and i.application_deadline is not null)) deadline
           from co group by 1),
  d as (select pv.*, coalesce(src.n, 0) n, coalesce(src.nread, 0) nread, coalesce(src.nfail, 0) nfail, coalesce(man.expected, 0) expected, coalesce(man.matched, 0) matched,
               coalesce(man.omitted, 0) omitted, coalesce(man.countries, '{}') man_countries, coalesce(mx.act, 0) mact, coalesce(mx.prop, 0) mprop, coalesce(mx.other, 0) mother,
               coalesce(mx.countries, '{}') mx_countries, coalesce(mx.countries_active, 0) countries_active, coalesce(mx.quals, 0) quals, coalesce(mx.quals_active, 0) quals_active,
               coalesce(mx.levels, 0) levels, coalesce(mx.dated, 0) dated, coalesce(mx.domestic, 0) mx_domestic, coalesce(mx.intl, 0) mx_intl,
               coalesce(cs.courses, 0) courses, coalesce(cs.paged, 0) paged, coalesce(cs.req_active, 0) req_active, coalesce(cs.req_any, 0) req_any,
               coalesce(cs.req_domestic_only, 0) req_dom, coalesce(cs.req_country, 0) req_country, coalesce(cs.intake, 0) intake, coalesce(cs.deadline, 0) deadline,
               coalesce(array(select pwh.label from pwh where pwh.provider_id = pv.id order by 1), '{}') pathways_held,
               coalesce(array(select pwl.label from pwl where pwl.provider_id = pv.id order by 1), '{}') pathways_listed,
               apc.disposition aer_disposition, coalesce(pv.ptype, '') in (select jsonb_array_elements_text(s.pl)) plevel, s.cpct, s.ipct, s.dpct
          from pv cross join s left join src on src.provider_id = pv.id left join man on man.provider_id = pv.id left join mx on mx.provider_id = pv.id
          left join cs on cs.provider_id = pv.id left join pipeline.aer_provider_coverage apc on apc.provider_id = pv.id),
  g as (select d.*, array(select x from unnest(d.man_countries) x where not x = any (d.mx_countries) order by x) missing_countries,
               array(select x from unnest(d.pathways_listed) x where not x = any (d.pathways_held) order by x) missing_pathways from d),
  h as (select g.*, array_remove(array[
           case when not g.eligible then 'outside_aer_population' end,
           case when g.n = 0 and g.req_any = 0 and g.mact + g.mprop = 0 then 'no_source' end,
           case when g.n > 0 and g.nread = 0 then 'source_unread' end,
           case when g.omitted > 0 then 'cells_omitted' end,
           case when cardinality(g.missing_countries) > 0 then 'countries_missing' end,
           case when g.mx_domestic > 0 and g.mx_intl = 0 or g.req_dom > 0 and g.req_dom = g.req_any then 'domestic_only_source' end,
           case when g.paged > 0 and g.req_any * 100 < g.cpct * g.paged then 'course_level_gap' end,
           case when g.courses > 0 and g.intake * 100 < g.ipct * g.courses then 'intake_gap' end,
           case when g.courses > 0 and g.deadline * 100 < g.dpct * g.courses then 'deadline_gap' end]
           || coalesce(array(select 'pathway_missing:' || x from unnest(g.missing_pathways) x), '{}'), null) gaps from g)
  select h.id, h.cc, h.nm, h.ptype,
         case when cardinality(h.gaps) = 0 then coalesce(h.aer_disposition, 'covered') else coalesce(h.aer_disposition, 'unreconciled') || '+gaps' end,
         jsonb_build_object('eligible', h.eligible, 'enrols_international', h.enrols_international, 'sources', h.n, 'sources_read', h.nread, 'sources_failed', h.nfail,
           'manifest_cells', h.expected, 'manifest_matched', h.matched, 'manifest_omitted', h.omitted, 'matrix_active', h.mact, 'matrix_proposed', h.mprop,
           'matrix_other', h.mother, 'matrix_dated', h.dated, 'matrix_domestic', h.mx_domestic, 'courses', h.courses, 'courses_with_page', h.paged,
           'courses_req_active', h.req_active, 'courses_req_any', h.req_any, 'courses_req_domestic_only', h.req_dom, 'courses_req_country', h.req_country,
           'courses_intake', h.intake, 'courses_deadline', h.deadline, 'aer_disposition', h.aer_disposition, 'provider_level', h.plevel,
           -- CF-247 AER missing-university strategy §E: report class, source fingerprint (changes when a page's stored copy changes), inventory outcomes
           'aer_class', security.aer_source_class_v1(h.id),
           'source_fingerprint', (select src.fp from src where src.provider_id = h.id),
           'inventory', (select jsonb_object_agg(i.outcome, i.n) from (select x.outcome, count(*) n from pipeline.aer_source_inventory x where x.provider_id = h.id group by 1) i),
           -- the input through which the scheduled AER reader (Release C, D6) acts on each gap
           'routes', jsonb_strip_nulls(jsonb_build_object(
             'outside_aer_population', case when not h.eligible then 'security.aer_eligible_v1 (aer.eligible_countries; provider enrols_international, now ' || coalesce(h.enrols_international::text, 'not recorded') || ')' end,
             'no_source', case when h.n = 0 then 'pipeline.entry_matrix_sources: an entry page must be recorded before security.entry_matrix_enabled_v1 admits the provider' end,
             'source_unread', case when h.n > 0 and h.nread = 0 then 'pipeline.entry_matrix_sources status found: read by entry-matrix-read' end,
             'matrix', case when h.n > 0 then 'pipeline.entry_matrix_sources read_at: due again after entry.matrix_refresh_days (aer-scheduled-read step c)' end,
             'courses_due', case when h.paged > h.req_any then 'security.aer_schedule_courses_v1 (bound page; due unless waiting, tried within aer.schedule_retry_days or locked)' end,
             'courses_without_page', case when h.courses > h.paged then 'pipeline.coverage_course_pages status bound with a stored copy (course page binding, workstream B)' end))),
         jsonb_build_object('countries_listed', to_jsonb(h.man_countries), 'countries_held', to_jsonb(h.mx_countries), 'countries_active', h.countries_active,
           'countries_missing', to_jsonb(h.missing_countries), 'qualifications', h.quals, 'qualifications_active', h.quals_active, 'study_levels', h.levels,
           'pathways_listed', to_jsonb(h.pathways_listed), 'pathways_held', to_jsonb(h.pathways_held), 'pathways_missing', to_jsonb(h.missing_pathways)),
         h.gaps,
         (greatest(0, h.paged - h.req_any) + cardinality(h.missing_countries) + cardinality(h.missing_pathways) + h.omitted + case when h.eligible then 0 else 1 end)::int
    from h
$$;


ALTER FUNCTION "security"."aer_coverage_v1"("p_providers" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_coverage_v1"("p_providers" "uuid"[]) IS 'CF-247 workstream C (P0 mandates 3 Nov 2026 §5/§12 and §8): per AER-eligible provider (and each provider-level type the eligibility rule leaves out), sources and manifests against matrix rows by applicant country, qualification and study level, named pathways (coverage.aer_pathways: IB, A Levels, Nepal), domestic-only rows, course-level requirements on courses with a bound page, effective period, intakes and deadlines; each gap with the scheduled AER reader input that acts on it. Read-only.';



CREATE OR REPLACE FUNCTION "security"."aer_coverage_verify_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with fresh as (
    select p.id provider_id, k.iso_alpha2::text country,
           not exists (select 1 from pipeline.entry_matrix_sources s where s.provider_id = p.id) no_source
      from catalogue.providers p join ref.countries k on k.id = p.country_id
     where k.iso_alpha2 in ('AU', 'NZ') and p.lifecycle_status = 'active' and p.publication_status = 'published' and p.enrols_international is true),
  snap as (select c.provider_id, c.country, c.disposition, c.discovery_state from pipeline.aer_provider_coverage c where c.eligible)
  select jsonb_build_object(
    'run_id', (select max(r.id) from pipeline.aer_reconcile_runs r), 'checked_at', now(),
    'fresh', (select jsonb_build_object('AU', count(*) filter (where country = 'AU'), 'NZ', count(*) filter (where country = 'NZ'), 'no_source', count(*) filter (where no_source)) from fresh),
    'stored', (select jsonb_build_object('AU', count(*) filter (where country = 'AU'), 'NZ', count(*) filter (where country = 'NZ'),
                                         'not_discovered_state', count(*) filter (where discovery_state = 'not_discovered')) from snap),
    'missing_from_queue', (select coalesce(jsonb_agg(f.provider_id), '[]'::jsonb) from fresh f where not exists (select 1 from snap s where s.provider_id = f.provider_id)),
    'not_eligible_now', (select coalesce(jsonb_agg(s.provider_id), '[]'::jsonb) from snap s where not exists (select 1 from fresh f where f.provider_id = s.provider_id)),
    'discovery_mismatch', (select coalesce(jsonb_agg(f.provider_id), '[]'::jsonb) from fresh f join snap s on s.provider_id = f.provider_id
                            where f.no_source <> (s.discovery_state = 'not_discovered')),
    'ok', not exists (select 1 from fresh f where not exists (select 1 from snap s where s.provider_id = f.provider_id))
          and not exists (select 1 from snap s where not exists (select 1 from fresh f where f.provider_id = s.provider_id))
          and not exists (select 1 from fresh f join snap s on s.provider_id = f.provider_id where f.no_source <> (s.discovery_state = 'not_discovered')))
$$;


ALTER FUNCTION "security"."aer_coverage_verify_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_coverage_verify_v1"() IS 'CF-247 AER (Platform Admin 2 Nov 2026 15:43 §5): compares the stored gap queue (pipeline.aer_provider_coverage, last run) with a fresh catalogue-to-AER anti-join written out independently of the reconcile (AU/NZ literal, as the Platform Admin''s rule states it); ok is true when no provider is missing, extra or differently discovered. Read-only.';



CREATE OR REPLACE FUNCTION "security"."aer_covered_courses_v1"() RETURNS TABLE("course_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with lv as (select l.id, array_remove(array[l.id] || array(select l2.id from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'entry.level_equivalents'), '[]'::jsonb)) p
                                                          join ref.study_levels l2 on l2.short_code = split_part(p, '=', 2) where split_part(p, '=', 1) = l.short_code), null) ids
              from ref.study_levels l),
  pm as (select m.provider_id, array_agg(distinct x) levels
           from catalogue.provider_entry_matrix m
           cross join lateral unnest(array_remove(array[m.study_level_id], null) || coalesce(security.entry_label_levels_v1(m.level_label), '{}'::uuid[])) x
          where m.status = 'active' and m.course_id is null and m.matrix_kind = 'provider_minimum' and m.min_grade is not null and m.grade_scale is distinct from 'none'
          group by 1)
  select co.id from catalogue.courses co join lv on lv.id = co.study_level_id join pm on pm.provider_id = co.provider_id and pm.levels && lv.ids
   where co.lifecycle_status = 'active'
  union
  select m.course_id from catalogue.provider_entry_matrix m
   where m.status = 'active' and m.course_id is not null and m.min_grade is not null and m.grade_scale is distinct from 'none'
  union
  select r.course_id from catalogue.course_entry_requirements r
   where r.status = 'active' and r.kind = 'override' and r.audience in ('international', 'all') and (r.min_grade is not null or r.min_entry_score is not null)
$$;


ALTER FUNCTION "security"."aer_covered_courses_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_covered_courses_v1"() IS 'AER coverage (Decision 276): courses with a published minimum for any applicant country under resolver rules 1, 2 and 4 (as security.aer_resolver_coverage_v1)';



CREATE OR REPLACE FUNCTION "security"."aer_current_findings_v1"() RETURNS TABLE("fingerprint" "text", "root_cause" "text", "provider_id" "uuid", "source_id" "uuid", "scope_kind" "text", "scope_key" "text", "scope_label" "text", "study_level" "text", "evidence" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  with el as (select * from security.aer_eligible_v1()),
  src as (
    select s.id, s.provider_id, s.title, s.url, s.status, s.error, s.read_at, s.content_hash,
           r.id run_id, r.state, r.error run_error, r.content_hash run_hash, r.result->'completeness'->>'status' cstatus,
           coalesce(r.result->'completeness'->>'heading', substring(r.error from '\("([^"]{1,120})')) heading,
           (select k.iso_alpha2::text from ref.countries k where k.iso_alpha2 ~ '^[A-Z]{2}$'
               and lower(replace(coalesce(s.title, ''), '-', ' ')) like '%' || lower(k.name) || '%' order by length(k.name) desc limit 1) title_country
      from pipeline.entry_matrix_sources s
      left join lateral (select r1.* from pipeline.entry_matrix_runs r1 where r1.source_id = s.id order by r1.created_at desc limit 1) r on true),
  src_f as (
    -- a source whose fetch failed, a read source never extracted, a read source whose latest run is held or incomplete, a stale source
    select s.*, c.cause from src s
     cross join lateral (values
       (case when s.status = 'failed' then 'source_unreadable' end),
       (case when s.status = 'read' and s.run_id is null then 'not_extracted' end),
       (case when s.status = 'read' then security.aer_run_cause_v1(s.state, s.run_error, s.cstatus) end),
       (case when s.status = 'read' and s.read_at < now() - make_interval(days => security.pipeline_num_v1('aer.stale_source_days', 90)::int) then 'stale_source' end)) c(cause)
     where c.cause is not null),
  src_rows as (
    select f.cause, f.provider_id, f.id source_id,
           case when f.cause = 'non_country_heading' then 'qualification' when f.title_country is not null then 'country' else 'source' end scope_kind,
           case when f.cause = 'non_country_heading' then btrim(regexp_replace(lower(coalesce(f.heading, f.title, '')), '[^a-z0-9]+', ' ', 'g'))
                when f.title_country is not null then f.title_country else f.id::text end scope_key,
           coalesce(case when f.cause = 'non_country_heading' then f.heading end, f.title, f.url) scope_label,
           jsonb_build_object('source_title', f.title, 'url', f.url, 'source_status', f.status, 'source_error', left(f.error, 200), 'read_at', f.read_at,
                              'run_id', f.run_id, 'run_state', f.state, 'run_error', left(f.run_error, 300), 'completeness', f.cstatus) evidence
      from src_f f),
  prov_rows as (
    -- an eligible provider with no source
    select 'no_source' cause, e.provider_id, null::uuid source_id, 'provider' scope_kind, null::text scope_key, e.country scope_label, null::text study_level,
           (jsonb_build_object('country', e.country) || coalesce(jsonb_strip_nulls(jsonb_build_object('route', r.route, 'reason', r.reason, 'next_action', r.next_action, 'parked', r.parked,
                                                                                                    'courses_waiting', r.courses_waiting, 'best_url', r.best_url, 'best_score', r.best_score)), '{}'::jsonb)) evidence
      from el e left join security.aer_no_source_route_v1() r on r.provider_id = e.provider_id where not exists (select 1 from pipeline.entry_matrix_sources s where s.provider_id = e.provider_id)
    union all
    -- extracted requirements waiting for Layer 4
    select 'awaiting_layer4', w.provider_id, null, 'provider', null, null, null,
           jsonb_build_object('matrix_proposed', sum(w.m), 'course_proposed', sum(w.c))
      from (select m.provider_id, count(*) m, 0 c from catalogue.provider_entry_matrix m where m.status = 'proposed' group by 1
            union all
            select c.provider_id, 0, count(*) from catalogue.course_entry_requirements x join catalogue.courses c on c.id = x.course_id where x.status = 'proposed' group by 1) w
     group by w.provider_id
    union all
    -- course entry reads held whole (course outcome register), by study level
    select 'course_read_held', o.provider_id, null, 'study_level', coalesce(l.short_code, 'none'), coalesce(l.short_code, 'none'), coalesce(l.short_code, 'none'),
           jsonb_build_object('courses', count(*), 'sample', (array_agg(jsonb_build_object('course_id', o.course_id, 'reason', left(o.read_reason, 160)) order by o.course_id))[1:5])
      from pipeline.aer_course_outcomes o join catalogue.courses c on c.id = o.course_id left join ref.study_levels l on l.id = c.study_level_id
     where o.outcome = 'source_unreadable'
     group by o.provider_id, l.short_code
    union all
    -- a defect named on pending Layer 4 items: one finding per provider and root cause, linked to every item (mandate 16:33 §9)
    select z.root_cause, z.provider_id, null, 'review_items', z.readiness, z.readiness, null,
           jsonb_build_object('items', count(*), 'sample', (array_agg(z.review_item_id order by z.review_item_id))[1:20])
      from pipeline.aer_review_readiness z
     where z.settled_at is null and z.root_cause is not null and z.readiness in ('reader_correction_required', 'evidence_required', 'superseded_invalid')
     group by z.root_cause, z.provider_id, z.readiness
    union all
    -- P0: active (consumer-resolvable) rows without evidence or quote
    select 'consumer_unevidenced', z.provider_id, null, 'provider', null, null, null, jsonb_build_object('rows', count(*), 'sample', (array_agg(z.id order by z.id))[1:20])
      from (select m.provider_id, m.id from catalogue.provider_entry_matrix m where m.status = 'active' and (m.evidence_id is null or btrim(coalesce(m.quote, '')) = '')
            union all
            select c.provider_id, x.id from catalogue.course_entry_requirements x join catalogue.courses c on c.id = x.course_id
             where x.status = 'active' and (x.evidence_id is null or btrim(coalesce(x.quote, '')) = '')) z
     group by z.provider_id
    union all
    -- P0: active AI-read rows whose Layer 4 item is not approved
    select 'consumer_unadmitted', z.provider_id, null, 'provider', null, null, null, jsonb_build_object('rows', count(*), 'sample', (array_agg(z.id order by z.id))[1:20])
      from (select m.provider_id, m.id from catalogue.provider_entry_matrix m
              left join pipeline.entry_matrix_runs r on r.id = m.run_id left join pipeline.layer4_review_items li on li.id = r.review_item_id
             where m.status = 'active' and coalesce(m.provenance->>'reader', '') <> 'manual' and coalesce(li.status, 'none') not in ('approved', 'edited_approved')
            union all
            select c.provider_id, x.id from catalogue.course_entry_requirements x join catalogue.courses c on c.id = x.course_id
              left join pipeline.layer4_review_items li on li.id = nullif(x.provenance->>'review_item_id', '')::uuid
             where x.status = 'active' and coalesce(x.provenance->>'reader', '') <> 'manual' and coalesce(li.status, 'none') not in ('approved', 'edited_approved')) z
     group by z.provider_id
    union all
    -- P0: active numeric minimum without its scale
    select 'consumer_number_without_scale', z.provider_id, null, 'provider', null, null, null, jsonb_build_object('rows', count(*), 'sample', (array_agg(z.id order by z.id))[1:20])
      from (select m.provider_id, m.id from catalogue.provider_entry_matrix m where m.status = 'active' and m.min_value is not null and coalesce(m.grade_scale, 'none') = 'none'
            union all
            select c.provider_id, x.id from catalogue.course_entry_requirements x join catalogue.courses c on c.id = x.course_id
             where x.status = 'active' and x.min_value is not null and coalesce(x.grade_scale, 'none') = 'none') z
     group by z.provider_id),
  allr as (
    select cause, provider_id, source_id, scope_kind, scope_key, scope_label, null::text study_level, evidence from src_rows
    union all
    select cause, provider_id, source_id, scope_kind, scope_key, scope_label, study_level, evidence from prov_rows)
  select distinct on (1) security.aer_fingerprint_v1(a.provider_id, a.source_id, a.scope_kind, a.scope_key, a.study_level, a.cause),
         a.cause, a.provider_id, a.source_id, a.scope_kind, a.scope_key, a.scope_label, a.study_level, a.evidence
    from allr a
   order by 1
$_$;


ALTER FUNCTION "security"."aer_current_findings_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_current_findings_v1"() IS 'CF-247 AER Phase B: every AER gap the existing data shows now (sources, reading runs and their stored completeness, proposed rows, the course outcome register, active rows), one row per fingerprint. Read-only; no page is read and no AI is called.';



CREATE OR REPLACE FUNCTION "security"."aer_discovery_campaign_ask_v1"("p_preview" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c pipeline.aer_discovery_campaigns%rowtype; v_cap numeric; v_batch int := security.pipeline_num_v1('aer.discovery_campaign_batch', 60)::int;
        v_retry int := security.pipeline_num_v1('aer.discovery_campaign_retry_hours', 3)::int; v_tries int := security.pipeline_num_v1('aer.source_discover_max_tries', 3)::int;
        v_used numeric; v_per numeric; v_open int; v_room int; v_asked int := 0; v_cand int := 0; v_left int; r record;
begin
  select * into c from pipeline.aer_discovery_campaigns x where x.state = 'running' order by x.id desc limit 1;
  if c.id is null then return jsonb_build_object('on', false, 'why', 'no running campaign'); end if;
  if security.pipeline_num_v1('aer.discovery_campaign_on', 0) < 1 then return jsonb_build_object('on', false, 'campaign', c.id, 'why', 'aer.discovery_campaign_on is 0'); end if;
  v_cap := security.pipeline_num_v1('aer.discovery_campaign_credit_cap', c.credit_cap);
  v_used := security.aer_discovery_campaign_used_v1(c.id);
  select coalesce(round(sum(units) / nullif(count(distinct provider_id), 0), 1), 4) into v_per from pipeline.coverage_vendor_usage where purpose in ('central_map', 'central_entry_search');
  v_per := greatest(v_per, 1);
  select count(*) into v_open from pipeline.aer_source_discover_requests q where q.campaign_id = c.id and q.outcome is null;
  v_room := greatest(0, least(v_batch - v_open, floor((v_cap - v_used - v_per * v_open) / v_per)))::int;
  -- providers still without an outcome: eligible, no entry source, a usable website, not asked by this campaign to an outcome
  for r in
    with cand as (
      select e.provider_id, (select count(*) from catalogue.courses k where k.provider_id = e.provider_id and k.lifecycle_status = 'active') n
        from security.aer_eligible_v1() e join catalogue.providers p on p.id = e.provider_id
       where not exists (select 1 from pipeline.entry_matrix_sources s where s.provider_id = e.provider_id)
         and p.website ~* '^https?://' and not security.third_party_host_v1(p.website)
         and not exists (select 1 from pipeline.aer_source_discover_requests q where q.provider_id = e.provider_id and q.outcome is null)
         and not exists (select 1 from pipeline.aer_source_discover_requests q where q.campaign_id = c.id and q.provider_id = e.provider_id
                           and q.outcome in ('entry_source_found', 'course_pages_found', 'no_entry_page', 'superseded'))
         and (select count(*) from pipeline.aer_source_discover_requests q where q.campaign_id = c.id and q.provider_id = e.provider_id and q.outcome = 'failed') < v_tries
         and not exists (select 1 from pipeline.aer_source_discover_requests q where q.campaign_id = c.id and q.provider_id = e.provider_id
                           and q.outcome = 'refused' and q.outcome_at > now() - make_interval(hours => v_retry)))
    select * from cand order by n desc, provider_id
  loop
    v_cand := v_cand + 1;
    continue when v_asked >= v_room;  -- counted, asked in a later run
    if not p_preview then
      insert into pipeline.provider_central_search(provider_id, state, requested_at, attempts, updated_at) values (r.provider_id, 'queued', now(), 0, now())
      on conflict (provider_id) do update set state = case when pipeline.provider_central_search.state = 'leased' and pipeline.provider_central_search.leased_until > now() then pipeline.provider_central_search.state else 'queued' end,
             requested_at = now(), attempts = 0, updated_at = now();
      insert into pipeline.aer_source_discover_requests(provider_id, campaign_id, detail) values (r.provider_id, c.id, jsonb_build_object('planned_credits', v_per, 'route', 'campaign'));
    end if;
    v_asked := v_asked + 1;
  end loop;
  -- what is left: providers this campaign has not yet taken to an outcome (candidates, asked now or later) and its open requests
  v_left := v_cand + v_open;
  if not p_preview then
    if v_left = 0 then
      update pipeline.aer_discovery_campaigns set state = 'complete', completed_at = now(), detail = detail || jsonb_build_object('credits_used', v_used) where id = c.id;
    elsif v_used >= v_cap then
      update pipeline.aer_discovery_campaigns set state = 'cap_reached', completed_at = now(), detail = detail || jsonb_build_object('credits_used', v_used, 'left_without_outcome', v_left) where id = c.id;
    end if;
  end if;
  return jsonb_build_object('on', true, 'campaign', c.id, 'preview', p_preview, 'asked', v_asked, 'open', v_open, 'room', v_room, 'credits_used', v_used, 'credit_cap', v_cap,
                            'credits_per_provider', v_per, 'left_without_outcome', v_left);
end $$;


ALTER FUNCTION "security"."aer_discovery_campaign_ask_v1"("p_preview" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_discovery_campaign_ask_v1"("p_preview" boolean) IS 'CF-247 F-AER.04: one step of the running AER discovery campaign (called by security.aer_source_discover_v1, job aer-source-discover): asks the central-page search about eligible providers with no entry source until each has a recorded outcome, within aer.discovery_campaign_batch a run and the campaign credit ceiling; marks the campaign complete or cap_reached. With true: what it would ask, nothing written.';



CREATE OR REPLACE FUNCTION "security"."aer_discovery_campaign_over_v1"("p_provider" "uuid", "p_units" numeric) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- true when this provider has an open request of the running campaign and the spend would take the campaign past its ceiling
  select exists (select 1 from pipeline.aer_discovery_campaigns c join pipeline.aer_source_discover_requests q on q.campaign_id = c.id
                  where c.state = 'running' and q.provider_id = p_provider and q.outcome is null
                    and security.aer_discovery_campaign_used_v1(c.id) + coalesce(p_units, 0) > security.pipeline_num_v1('aer.discovery_campaign_credit_cap', c.credit_cap))
$$;


ALTER FUNCTION "security"."aer_discovery_campaign_over_v1"("p_provider" "uuid", "p_units" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_discovery_campaign_over_v1"("p_provider" "uuid", "p_units" numeric) IS 'CF-247 F-AER.04: whether a central-page spend for a provider asked by the running discovery campaign would pass the campaign ceiling (public.svc_fc_spend refuses it as campaign_cap).';



CREATE OR REPLACE FUNCTION "security"."aer_discovery_campaign_used_v1"("p_campaign" bigint) RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- credits the campaign used: central-page spends (maps and entry searches) of the providers it asked about, from each request on
  -- 12 Nov 2026 (D2): from each provider's first request of the campaign, through the (provider_id, at) index; the same total as any request before the spend
  with f as (select q.provider_id, min(q.requested_at) t from pipeline.aer_source_discover_requests q where q.campaign_id = p_campaign group by 1)
  select coalesce(sum(u.units), 0) from f join pipeline.coverage_vendor_usage u on u.provider_id = f.provider_id and u.at >= f.t
   where security.fc_purpose_group_v1(u.purpose) = 'central'
$$;


ALTER FUNCTION "security"."aer_discovery_campaign_used_v1"("p_campaign" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_discovery_campaign_used_v1"("p_campaign" bigint) IS 'CF-247 F-AER.04: Firecrawl credits used by an AER discovery campaign (central-page spends of the providers it asked about, from each request on).';



CREATE OR REPLACE FUNCTION "security"."aer_discovery_campaign_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- one pass over the outcomes (the read is used by a screen)
  with o as materialized (select x.outcome from security.aer_discovery_outcomes_v1() x),
  c as (select * from pipeline.aer_discovery_campaigns order by id desc limit 1)
  select jsonb_build_object(
    'campaign', (select to_jsonb(c) || jsonb_build_object('credits_used', security.aer_discovery_campaign_used_v1(c.id),
                                                           'credit_cap_now', security.pipeline_num_v1('aer.discovery_campaign_credit_cap', c.credit_cap),
                                                           'asked', (select count(distinct q.provider_id) from pipeline.aer_source_discover_requests q where q.campaign_id = c.id)) from c),
    'providers', (select count(*) from o),
    'by_outcome', (select coalesce(jsonb_object_agg(z.outcome, z.n), '{}'::jsonb) from (select o.outcome, count(*) n from o group by 1) z),
    'with_outcome', (select count(*) from o where o.outcome not in ('not_asked', 'searching', 'refused', 'failed')))
$$;


ALTER FUNCTION "security"."aer_discovery_campaign_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_discovery_campaign_v1"() IS 'CF-247 F-AER.04: status of the latest AER discovery campaign: credits used against the ceiling, providers asked, providers by outcome and how many have a recorded outcome. Read only.';



CREATE OR REPLACE FUNCTION "security"."aer_discovery_metrics_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with c as (select * from pipeline.aer_discovery_campaigns order by id desc limit 1),
  f as (select q.provider_id, min(q.requested_at) first_at from pipeline.aer_source_discover_requests q join c on q.campaign_id = c.id group by 1),
  last as (select distinct on (q.provider_id) q.provider_id, q.outcome from pipeline.aer_source_discover_requests q join c on q.campaign_id = c.id
            order by q.provider_id, q.requested_at desc),
  src as (select s.provider_id, s.status from pipeline.entry_matrix_sources s join f on f.provider_id = s.provider_id and s.created_at >= f.first_at),
  m as (select (select count(*) from f) attempted,
               (select count(*) from src) new_sources,
               (select count(distinct provider_id) from src where status = 'read') usable,
               (select count(*) from last where outcome in ('no_entry_page', 'course_pages_found')) not_found,
               (select count(*) from last where outcome is null) open,
               (select security.aer_discovery_campaign_used_v1(c.id) from c) credits,
               (select coalesce(sum(x.units), 0) from pipeline.aer_discovery_spare_spends x join c on x.campaign_id = c.id) spare_all,
               (select coalesce(sum(x.units), 0) from pipeline.aer_discovery_spare_spends x where x.at >= security.fc_day_start_v1()) spare_today)
  select jsonb_build_object('providers_attempted', m.attempted, 'new_sources', m.new_sources, 'usable_sources', m.usable, 'not_found', m.not_found, 'open', m.open,
                            'credits', m.credits, 'spare_credits_total', m.spare_all, 'spare_credits_today', m.spare_today,
                            'cost_per_usable_source', case when m.usable > 0 then round(m.credits / m.usable, 1) end,
                            'by_outcome', (select coalesce(jsonb_object_agg(coalesce(z.outcome, 'searching'), z.n), '{}'::jsonb) from (select outcome, count(*) n from last group by 1) z),
                            'spare', security.aer_discovery_spare_room_v1())
    from m
$$;


ALTER FUNCTION "security"."aer_discovery_metrics_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_discovery_metrics_v1"() IS 'CF-247 F-AER.04 D2: AER discovery campaign metrics (providers attempted, new and usable sources, not found, credits, spare credits, cost per usable source, spare room now).';



CREATE OR REPLACE FUNCTION "security"."aer_discovery_outcomes_v1"() RETURNS TABLE("provider_id" "uuid", "provider" "text", "country" "text", "website" "text", "courses" integer, "outcome" "text", "source_url" "text", "source_type" "text", "source_status" "text", "last_checked" timestamp with time zone, "evidence" "jsonb", "next_action" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  with e as (select e.provider_id, e.country from security.aer_eligible_v1() e),
  src as (select distinct on (s.provider_id) s.provider_id, s.url, s.status, coalesce(s.read_at, s.updated_at) at from pipeline.entry_matrix_sources s
           order by s.provider_id, (s.status = 'read') desc, s.updated_at desc),
  req as (select distinct on (q.provider_id) q.provider_id, q.outcome, q.requested_at, q.outcome_at, q.detail, q.campaign_id from pipeline.aer_source_discover_requests q
           order by q.provider_id, q.requested_at desc),
  fails as (select q.provider_id, count(*) n from pipeline.aer_source_discover_requests q where q.outcome = 'failed' group by 1)
  select e.provider_id, coalesce(p.display_name, p.canonical_name), e.country, p.website,
         (select count(*)::int from catalogue.courses c where c.provider_id = e.provider_id and c.lifecycle_status = 'active'),
         case when src.provider_id is not null then 'source_' || src.status
              when coalesce(p.website, '') !~* '^https?://' then 'no_website'
              when security.third_party_host_v1(p.website) then 'website_is_directory'
              when req.provider_id is null then 'not_asked'
              when req.outcome is null then 'searching'
              when req.outcome = 'failed' and coalesce(fails.n, 0) >= security.pipeline_num_v1('aer.source_discover_max_tries', 3) then 'search_failed'
              else req.outcome end,
         src.url,
         case when src.url is null then null when src.url ~* '\.pdf($|[?#])' then 'pdf' else 'web page' end,
         src.status,
         greatest(src.at, req.outcome_at, req.requested_at),
         coalesce(req.detail, '{}'::jsonb) || jsonb_build_object('campaign_id', req.campaign_id),
         case when src.provider_id is not null and src.status = 'read' then 'read on its refresh schedule (entry.matrix_refresh_days)'
              when src.provider_id is not null then 'read by entry-matrix-read; failures retried within entry.matrix_attempts'
              when coalesce(p.website, '') !~* '^https?://' or security.third_party_host_v1(p.website) then 'set the provider''s own website (Provider catalogue), or attach an entry source by hand'
              when req.outcome is null and req.provider_id is not null then 'central-page search in progress'
              when req.outcome = 'refused' then 'asked again after aer.discovery_campaign_retry_hours (a budget was used up)'
              when req.outcome in ('no_entry_page', 'course_pages_found') then 'no entry page on the website: course-level reading from course pages; attach an entry source by hand if one exists'
              when req.outcome = 'failed' then 'search failed: retried up to aer.source_discover_max_tries, then attach by hand'
              else 'asked by the discovery campaign' end
    from e join catalogue.providers p on p.id = e.provider_id
    left join src on src.provider_id = e.provider_id
    left join req on req.provider_id = e.provider_id
    left join fails on fails.provider_id = e.provider_id
$_$;


ALTER FUNCTION "security"."aer_discovery_outcomes_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_discovery_outcomes_v1"() IS 'CF-247 F-AER.04: for every AER-eligible provider, the entry-requirements source (address, document type, status), the discovery outcome, when it was last checked, the evidence and the next action. Read only, counted live.';



CREATE OR REPLACE FUNCTION "security"."aer_discovery_spare_ok_v1"("p_provider" "uuid", "p_units" numeric) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- a provider with an open request of the running campaign, and spare room for this spend
  select exists (select 1 from pipeline.aer_discovery_campaigns c join pipeline.aer_source_discover_requests q on q.campaign_id = c.id
                  where c.state = 'running' and q.provider_id = p_provider and q.outcome is null)
     and coalesce((security.aer_discovery_spare_room_v1()->>'room')::numeric, 0) >= coalesce(p_units, 0)
$$;


ALTER FUNCTION "security"."aer_discovery_spare_ok_v1"("p_provider" "uuid", "p_units" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_discovery_spare_room_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_max numeric; v_win numeric; v_margin numeric; v_start timestamptz := security.fc_day_start_v1();
        v_end timestamptz; v_left_h numeric; v_total numeric; v_auto numeric; v_taken numeric; v_vendor numeric;
        v_reserved numeric := 0; v_central_left numeric := 0; v_share numeric; v_used numeric; v_recent numeric; v_prev numeric; v_need numeric;
        v_groups jsonb := '{}'::jsonb; v_room numeric; g record;
begin
  v_max := least(security.pipeline_num_v1('aer.discovery_spare_daily_max', 0), 1000);  -- fixed: Platform Admin decision D2 sets 1,000 credits a day as the most
  if v_max <= 0 then return jsonb_build_object('room', 0, 'why', 'aer.discovery_spare_daily_max is 0'); end if;
  if security.pipeline_num_v1('aer.discovery_campaign_on', 0) < 1 or not exists (select 1 from pipeline.aer_discovery_campaigns c where c.state = 'running') then
    return jsonb_build_object('room', 0, 'why', 'no running campaign'); end if;
  if not coalesce((select (s.value #>> '{}')::boolean from pipeline.platform_toolset_settings s where s.toolset_key = 'firecrawl' and s.key = 'daily_budget_on'), false) then
    return jsonb_build_object('room', 0, 'why', 'daily budget off'); end if;
  v_win := greatest(security.pipeline_num_v1('aer.discovery_spare_window_hours', 3), 1);
  v_margin := greatest(security.pipeline_num_v1('aer.discovery_spare_margin_pct', 50), 0);
  v_end := (((v_start at time zone 'Australia/Melbourne') + interval '1 day') at time zone 'Australia/Melbourne');  -- fixed: the Firecrawl budget day (fc_day_start_v1)
  v_left_h := greatest(0, extract(epoch from (v_end - now())) / 3600);
  v_total := security.fc_setting_num_v1('daily_budget_total', 15000);
  v_auto := security.fc_billed_today_v1() - security.fc_on_demand_today_v1();
  select coalesce(sum(x.units), 0) into v_taken from pipeline.aer_discovery_spare_spends x where x.at >= v_start;
  -- every other group keeps what it is projected to still need today; central keeps its own unused share (the campaign uses that first)
  for g in with u as (select security.fc_purpose_group_v1(x.purpose) grp,
                             coalesce(sum(x.units) filter (where x.at >= v_start), 0) used,
                             coalesce(sum(x.units) filter (where x.at >= now() - make_interval(secs => v_win * 3600)), 0) recent,
                             coalesce(sum(x.units) filter (where x.at >= now() - interval '1 day' and x.at < v_end - interval '1 day'), 0) prev
                        from pipeline.coverage_vendor_usage x
                       where x.at >= least(v_start, now() - make_interval(secs => v_win * 3600), now() - interval '1 day') and x.on_demand_run is null
                       group by 1)
            select substr(s.key, 13) grp, (s.value #>> '{}')::numeric share, coalesce(u.used, 0) used, coalesce(u.recent, 0) recent, coalesce(u.prev, 0) prev
              from pipeline.platform_toolset_settings s left join u on u.grp = substr(s.key, 13)
             where s.toolset_key = 'firecrawl' and s.key like 'daily\_share\_%' loop
    v_used := g.used; v_recent := g.recent; v_prev := g.prev;
    if g.grp = 'central' then
      v_central_left := greatest(0, g.share - v_used);
      v_groups := v_groups || jsonb_build_object(g.grp, jsonb_build_object('share', g.share, 'used', v_used, 'kept', v_central_left));
    else
      v_need := least(greatest(0, g.share - v_used), ceil(greatest(v_recent / v_win * v_left_h, v_prev) * (1 + v_margin / 100)));
      v_reserved := v_reserved + v_need;
      v_groups := v_groups || jsonb_build_object(g.grp, jsonb_build_object('share', g.share, 'used', v_used, 'recent', v_recent, 'previous_day_same_hours', v_prev, 'kept', v_need));
    end if;
  end loop;
  v_vendor := security.fc_priority_room_v1();
  if v_vendor is null then
    return jsonb_build_object('room', 0, 'why', 'no vendor balance read in the last 2 hours', 'groups', v_groups); end if;
  v_room := greatest(0, floor(least(v_max - v_taken, v_total - v_auto - v_reserved - v_central_left, v_vendor)));
  return jsonb_build_object('room', v_room, 'daily_max', v_max, 'taken_today', v_taken, 'day_total', v_total, 'billed_automatic', v_auto, 'kept_for_others', v_reserved,
                            'central_unused', v_central_left, 'vendor_above_floor', v_vendor, 'hours_left', round(v_left_h, 1), 'groups', v_groups,
                            'why', case when v_room > 0 then 'spare capacity' when v_max - v_taken <= 0 then 'daily maximum taken' when v_vendor <= 0 then 'vendor floor'
                                        else 'no spare capacity' end);
end $$;


ALTER FUNCTION "security"."aer_discovery_spare_room_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_discovery_spare_room_v1"() IS 'CF-247 F-AER.04 D2: Firecrawl credits the AER discovery campaign may still take today beyond the central share, from verified unused capacity only, with the breakdown.';



CREATE OR REPLACE FUNCTION "security"."aer_e13_class_v1"("p_gate" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case when p_gate is null then null
              when coalesce((p_gate->>'complete')::boolean, false) then 'complete'
              when coalesce((p_gate->>'rows_cut')::int, 0) > 0 then 'row_limit'
              when jsonb_array_length(coalesce(p_gate->'shared_page', '[]'::jsonb)) > 0 then 'shared_page'
              when jsonb_array_length(coalesce(p_gate->'drops_uncovered', '[]'::jsonb)) > 0 then 'drops_uncovered'
              else 'row_level' end
$$;


ALTER FUNCTION "security"."aer_e13_class_v1"("p_gate" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_e13_pilot_report_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with s as (select s.* from pipeline.aer_read_supersessions s where s.reason like 'AER technical recovery (E13)%')
  select jsonb_build_object('asked', (select count(*) from s), 'replaced', (select count(*) from s where s.state = 'superseded'),
    'refused', (select count(*) from s where s.state = 'refused'), 'waiting', (select count(*) from s where s.state = 'requested'),
    'yield_pct', (select round(100.0 * count(*) filter (where s.state = 'superseded') / nullif(count(*) filter (where s.state <> 'requested'), 0), 1) from s),
    'refused_why', (select jsonb_object_agg(k, n) from (select left(coalesce(s.outcome, 'unknown'), 80) k, count(*) n from s where s.state = 'refused' group by 1) z),
    'replacements_approved', (select count(*) from s join pipeline.layer4_review_items i on i.id = s.new_item_id where i.status in ('approved', 'edited_approved')),
    'replacements_waiting', (select count(*) from s join pipeline.layer4_review_items i on i.id = s.new_item_id where i.status = 'pending'),
    'by_university', (select jsonb_object_agg(z.pid, z.j) from (select c.provider_id::text pid, jsonb_build_object('asked', count(*), 'replaced', count(*) filter (where s.state = 'superseded')) j
                        from s join catalogue.courses c on c.id = s.course_id group by 1) z))
$$;


ALTER FUNCTION "security"."aer_e13_pilot_report_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_e13_recover_v1"("p_preview" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_on boolean := security.pipeline_num_v1('aer.e13_recover_on', 0) >= 1;
        v_batch int := security.pipeline_num_v1('batch.aer_e13_recover', 10)::int;
        v_day int := security.pipeline_num_v1('aer.e13_recover_daily_max', 40)::int;
        v_per int := security.pipeline_num_v1('aer.e13_recover_per_provider', 2)::int;
        v_tries int := security.pipeline_num_v1('aer.schedule_held_max_tries', 2)::int;
        v_retry interval := make_interval(days => security.pipeline_num_v1('aer.schedule_held_retry_days', 14)::int);
        v_tag text := 'AER technical recovery (E13)';
        v_owner uuid; v_rank int; v_ai text; v_bal numeric; v_floor numeric; v_cost numeric := security.course_entry_cost_v1();
        v_used int; v_room int; v_why text; r record; g jsonb; v_res jsonb; v_n int := 0;
        v_asked jsonb := '[]'::jsonb; v_skip jsonb := '[]'::jsonb; v_cand int := 0;
        -- 4 Nov 2026 (direction 10:00 §4): a bounded, reversible pilot: listed universities only, a total over the pilot, and never an item whose
        -- corrected read was refused on the same stored copy (the reader is deterministic on unchanged evidence)
        v_prov text[] := security.pipeline_list_v1('aer.e13_recover_providers', '[]'::jsonb); v_total int := security.pipeline_num_v1('aer.e13_recover_total_max', 40)::int; v_all int;
begin
  select c.owner into v_owner from pipeline.field_gap_queue_control c where c.id = 1;
  select ro.rank into v_rank from security.user_roles ur join security.roles ro on ro.code = ur.role_code
   where ur.user_id = v_owner and (ur.expires_at is null or ur.expires_at > now()) and ro.status = 'active' order by ro.rank desc limit 1;
  select count(*) into v_used from pipeline.aer_read_supersessions s
   where s.requested_at > now() - interval '1 day' and s.reason like v_tag || '%';  -- fixed: the daily budget is counted over the last 24 hours
  select count(*) into v_all from pipeline.aer_read_supersessions s where s.reason like v_tag || '%';
  v_room := greatest(0, least(v_batch, v_day - v_used, v_total - v_all));
  v_ai := security.ai_use_refusal_v1('enrich_fields');
  select o.remaining_usd into v_bal from pipeline.layer3_openrouter_observations o where o.kind = 'credits' order by o.observed_at desc limit 1;
  v_floor := coalesce((security.toolset_setting('openrouter', 'credit_floor_usd'))::text::numeric, 0);
  v_why := case when not v_on and not p_preview then 'aer.e13_recover_on is 0'
                when v_owner is null then 'no owner to run as (Coverage > Attributes, Fill the gaps)'
                when coalesce(v_rank, 0) < 6 then 'the owner it runs as does not hold the Platform Admin role'  -- fixed: the rank Read next batch requires
                when v_ai is not null then 'AI reading is stopped (AI limits): ' || v_ai
                when cardinality(v_prov) = 0 then 'no university is in the pilot (aer.e13_recover_providers)'
                when v_room = 0 and v_all >= v_total then 'the pilot total is used (aer.e13_recover_total_max)'
                when v_room = 0 then 'the daily budget of E13 recovery is used (aer.e13_recover_daily_max)'
                when v_bal is not null and v_bal - v_room * v_cost < v_floor then 'the estimate would take the OpenRouter balance below its floor (Toolsets & limits)' end;
  if v_why is not null and not (p_preview and v_why = 'aer.e13_recover_on is 0') then
    return jsonb_build_object('on', v_on, 'preview', p_preview, 'refusal', v_why, 'used_24h', v_used, 'room', v_room, 'asked', 0);
  end if;
  for r in
    with c as (
      select i.id, i.entity_id, i.created_at, co.provider_id,
             (select count(*) from pipeline.aer_read_supersessions s where s.old_item_id = i.id) tries
        from pipeline.layer4_review_items i
        join pipeline.layer4_item_readiness x on x.item_id = i.id
        join catalogue.courses co on co.id = i.entity_id
        join pipeline.coverage_course_pages pg on pg.course_id = i.entity_id
       where i.status = 'pending' and i.field_code = 'course_entry_first_read'
         and x.readiness = 'technical_blocked' and 'completeness_gate' = any (x.reasons)
         and security.aer_e13_class_v1(x.gate) = 'drops_uncovered'
         and pg.evidence_id is not null and pg.url = i.proposed_value->>'url'
         and co.provider_id::text = any (v_prov)
         -- mandate 16:32 §4: the shared rule (an unchanged copy, reader and settings never read again; a change makes it eligible)
         and coalesce((security.aer_recovery_rule_v1(i.id)->>'eligible')::boolean, false)
         and not exists (select 1 from pipeline.aer_read_supersessions s where s.old_item_id = i.id and (s.state = 'requested' or s.requested_at > now() - v_retry))
         and not exists (select 1 from pipeline.field_enrich_items f where f.course_id = i.entity_id and f.field = 'entry_requirements' and f.state in ('queued', 'waiting', 'ai', 'leased'))),
    k as (select c.*, row_number() over (partition by c.provider_id order by c.tries, c.created_at, c.id) turn from c where c.tries < v_tries)
    select * from k where k.turn <= v_per order by k.turn, k.tries, k.created_at, k.id
  loop
    exit when v_n >= v_room;
    v_cand := v_cand + 1;
    -- the gate result may be older than the item's last change: checked again before anything is asked
    g := security.course_entry_gate_v1(r.id);
    if security.aer_e13_class_v1(g) is distinct from 'drops_uncovered' then
      v_skip := v_skip || jsonb_build_object('item_id', r.id, 'why', 'the gate now says ' || coalesce(security.aer_e13_class_v1(g), 'nothing'));
      continue;
    end if;
    if p_preview then
      v_asked := v_asked || jsonb_build_object('item_id', r.id, 'course_id', r.entity_id, 'provider_id', r.provider_id, 'tries', r.tries); v_n := v_n + 1;
      continue;
    end if;
    begin
      v_res := security.course_entry_correction_v1(r.id, v_owner,
                 v_tag || ': the held read dropped printed requirements that no row covers; read again from the stored copy of the same page (try ' || (r.tries + 1) || ')');
      v_asked := v_asked || jsonb_build_object('item_id', r.id, 'course_id', r.entity_id, 'provider_id', r.provider_id, 'tries', r.tries, 'job_id', v_res->>'job_id');
      v_n := v_n + 1;
    exception when others then
      v_skip := v_skip || jsonb_build_object('item_id', r.id, 'why', left(sqlerrm, 300));
    end;
  end loop;
  return jsonb_build_object('on', v_on, 'preview', p_preview, 'refusal', null, 'used_24h', v_used, 'pilot_used', v_all, 'room', v_room, 'candidates', v_cand, 'asked', v_n,
                            'estimate_usd', round(v_n * v_cost, 4), 'items', v_asked, 'skipped', v_skip);
end $$;


ALTER FUNCTION "security"."aer_e13_recover_v1"("p_preview" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_eligible_v1"() RETURNS TABLE("provider_id" "uuid", "country" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- Phase A baseline §1.1: country in aer.eligible_countries, active, published, enrols international students
  select p.id, k.iso_alpha2::text
    from catalogue.providers p join ref.countries k on k.id = p.country_id
   where k.iso_alpha2::text in (select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'aer.eligible_countries'), '[]'::jsonb)))
     and p.lifecycle_status = 'active' and p.publication_status = 'published' and p.enrols_international is true
$$;


ALTER FUNCTION "security"."aer_eligible_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_eligible_v1"() IS 'CF-247 AER Phase B: the eligible AU/NZ providers (Phase A baseline §1.1), the denominator of every AER measure.';



CREATE OR REPLACE FUNCTION "security"."aer_fair_courses_v1"("p_room" integer) RETURNS TABLE("course_id" "uuid", "provider_id" "uuid", "country" "text", "provider_name" "text", "tier" integer, "turn" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_lim numeric := security.pipeline_num_v1('aer.schedule_layer4_max', 600);
        v_share int := greatest(1, ceil(v_lim * security.pipeline_num_v1('wc.aer_provider_share_pct', 10) / 100.0))::int;
        v_reserve numeric := ceil(v_lim * security.pipeline_num_v1('wc.aer_new_provider_reserve_pct', 10) / 100.0);
        v_room numeric := coalesce((security.work_review_room_v1('aer')->>'room')::numeric, 0);
        v_cands jsonb;
begin
  if coalesce(p_room, 0) <= 0 or v_room <= 0 then return; end if;
  create temp table if not exists aer_fair_cands (course_id uuid, provider_id uuid, country text, provider_name text, tier integer, turn bigint, n bigint) on commit drop;
  truncate aer_fair_cands;
  insert into aer_fair_cands
  select c.course_id, c.provider_id, c.country, c.provider_name, c.tier, c.turn, row_number() over ()
    from security.aer_schedule_courses_v1((p_room * security.pipeline_num_v1('wc.aer_candidate_factor', 5))::int) c;
  select jsonb_agg(jsonb_build_object('entity', e.course_id::text, 'provider_id', e.provider_id, 'field', 'entry_requirements', 'category', 'aer', 'priority', -e.n) order by e.n)
    into v_cands
    from (select a.*, row_number() over (partition by a.provider_id order by a.n) k, coalesce(l.waiting, 0) waiting
            from aer_fair_cands a left join security.aer_provider_load_v1() l on l.provider_id = a.provider_id) e
   where e.waiting + e.k <= v_share and (v_room > v_reserve or e.waiting = 0);
  return query
    select a.course_id, a.provider_id, a.country, a.provider_name, a.tier, a.turn
      from security.work_fair_pick_v1('aer', 'entry_read', coalesce(v_cands, '[]'::jsonb), p_room * 2) p  -- fixed: twice the room, as the tick's own selection
      join aer_fair_cands a on a.course_id::text = p.entity
     order by p.pos;
end $$;


ALTER FUNCTION "security"."aer_fair_courses_v1"("p_room" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_fair_projection_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with lim as (select security.pipeline_num_v1('aer.schedule_layer4_max', 600) l,
                      ceil(security.pipeline_num_v1('aer.schedule_layer4_max', 600) * security.pipeline_num_v1('wc.aer_provider_share_pct', 10) / 100.0) share,
                      ceil(security.pipeline_num_v1('aer.schedule_layer4_max', 600) * security.pipeline_num_v1('wc.aer_new_provider_reserve_pct', 10) / 100.0) reserve),
       q as (select distinct on (i.entity_id, i.field_code) i.entity_id, i.field_code, coalesce(c.provider_id, case when i.entity_type = 'provider' then i.entity_id end) pid,
                    security.aer_route_v1(i.field_code, y.gate)->>'route' route
               from pipeline.layer4_review_items i left join pipeline.layer4_item_readiness y on y.item_id = i.id
               left join catalogue.courses c on i.entity_type = 'course' and c.id = i.entity_id
              where i.status = 'pending' and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run', 'entry_matrix_change')
              order by i.entity_id, i.field_code, i.created_at),
       prog as (select f.provider_id pid, count(distinct coalesce(f.course_id, f.provider_id)) n from pipeline.field_enrich_items f
                 where f.field = 'entry_requirements' and f.state in ('queued', 'waiting', 'ai', 'leased') group by 1),
       p as (select q.pid, count(*) filter (where q.route in ('review', 'review_except', 'matrix_except')) ready, count(*) filter (where q.route = 'awaiting_gate') unchecked,
                    count(*) filter (where q.route not in ('review', 'review_except', 'matrix_except', 'awaiting_gate')) held from q group by 1)
  select jsonb_build_object('limit', lim.l, 'share', lim.share, 'reserve', lim.reserve,
    'ready', (select sum(ready) from p), 'unchecked', (select sum(unchecked) from p), 'held', (select sum(held) from p), 'in_progress', coalesce((select sum(n) from prog), 0),
    'room_now', greatest(lim.l - coalesce((select sum(ready + unchecked) from p), 0) - coalesce((select sum(n) from prog), 0), 0),
    'room_when_gated', greatest(lim.l - coalesce((select sum(ready) from p), 0) - coalesce((select sum(n) from prog), 0), 0),
    'universities', coalesce((select jsonb_agg(jsonb_build_object('provider_id', p.pid, 'name', coalesce(pv.display_name, pv.canonical_name), 'ready', p.ready, 'unchecked', p.unchecked,
                     'held', p.held, 'in_progress', coalesce(prog.n, 0), 'new_reads_allowed', greatest(lim.share - p.ready - coalesce(prog.n, 0), 0),
                     'at_share', p.ready + coalesce(prog.n, 0) >= lim.share) order by p.ready + p.unchecked + p.held desc)
               from p left join prog on prog.pid = p.pid left join catalogue.providers pv on pv.id = p.pid), '[]'::jsonb))
  from lim
$$;


ALTER FUNCTION "security"."aer_fair_projection_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_fingerprint_v1"("p_provider" "uuid", "p_source" "uuid", "p_scope_kind" "text", "p_scope_key" "text", "p_level" "text", "p_cause" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select md5(concat_ws('|', p_provider::text, coalesce(p_source::text, ''), p_scope_kind, coalesce(p_scope_key, ''), coalesce(p_level, ''), p_cause))
$$;


ALTER FUNCTION "security"."aer_fingerprint_v1"("p_provider" "uuid", "p_source" "uuid", "p_scope_kind" "text", "p_scope_key" "text", "p_level" "text", "p_cause" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_fingerprint_v1"("p_provider" "uuid", "p_source" "uuid", "p_scope_kind" "text", "p_scope_key" "text", "p_level" "text", "p_cause" "text") IS 'CF-247 AER Phase B: the stable fingerprint of a gap: md5 of provider, source, scope kind, scope key, study level and root cause.';



CREATE OR REPLACE FUNCTION "security"."aer_flat_v1"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  -- the canonical flat form of the worker (course-entry.ts, entry.ts, aer-v2.ts): letters and digits, case, accents and spacing ignored
  select regexp_replace(lower(normalize(coalesce(p, ''), NFKD)), '[^a-z0-9]+', '', 'g')
$$;


ALTER FUNCTION "security"."aer_flat_v1"("p" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_flat_v1"("p" "text") IS 'AER v2: the canonical flat comparison form (letters and digits only, lower case, NFKD), the same as the worker''s quote check';



CREATE OR REPLACE FUNCTION "security"."aer_machine_admit_v1"("p_item" "uuid", "p_via" "text" DEFAULT 'run'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_review_items%rowtype; v jsonb; v_mode int := security.pipeline_num_v1('aer.machine_mode', 0)::int; v_res jsonb; v_dec uuid; v_reason text; v_aer jsonb;
        v_sys uuid := security.system_actor_id(); v_after int; v_course uuid; v_prov uuid; v_out text;
        v_ref constant text := 'CF-247 F-AER.04; Platform Admin decision 10 Nov 2026 (AER recovery pack decision 1: machine admission of complete, source-proved course reads)';
begin
  if v_mode < 1 then return jsonb_build_object('ok', false, 'rule', 'machine_mode_off'); end if;
  if v_mode >= 2 and not exists (select 1 from pipeline.aer_machine_validations x where x.passed and x.validated_at > now() - make_interval(days => 7)) then -- fixed: a validation is valid for 7 days
    v_mode := 1; -- admit mode without a passing validation runs as shadow (a passing check never switches admission on by itself)
  end if;
  if v_mode >= 2 and security.pipeline_num_v1('aer.machine_suspended', 0) >= 1 then v_mode := 1; end if;
  if v_mode >= 2 then
    select * into i from pipeline.layer4_review_items where id = p_item for update skip locked;
    if i.id is null then return jsonb_build_object('ok', false, 'rule', 'item_locked'); end if;
  end if;
  v := security.aer_machine_check_v1(p_item);
  select c.id, c.provider_id into v_course, v_prov from pipeline.layer4_review_items li join catalogue.courses c on c.id = li.entity_id where li.id = p_item;
  v_out := case when coalesce((v->>'ok')::boolean, false) then (case when v_mode >= 2 then 'admitted' else 'would_admit' end)
                when coalesce((v->>'audit')::boolean, false) then 'audit_sample' else 'declined' end;
  if v_mode < 2 then
    insert into pipeline.aer_machine_admissions (review_item_id, course_id, provider_id, mode, outcome, reason_code, reason, next_action, checks, evidence_id, content_hash, source_url, actor)
    values (p_item, v_course, v_prov, 'shadow', v_out, v->>'rule', v->>'reason', v->>'next_action', coalesce(v->'checks', '{}'::jsonb),
            nullif(v->'checks'->>'evidence_id', '')::uuid, v->'checks'->>'content_hash', v->'checks'->>'source_url', v_sys)
    on conflict (review_item_id) where mode = 'shadow' do update set outcome = excluded.outcome, reason_code = excluded.reason_code, reason = excluded.reason, next_action = excluded.next_action,
           checks = excluded.checks, evidence_id = excluded.evidence_id, content_hash = excluded.content_hash, source_url = excluded.source_url, updated_at = now();
    return jsonb_build_object('ok', true, 'mode', 'shadow', 'outcome', v_out, 'rule', v->>'rule');
  end if;
  if v_out <> 'admitted' then
    if v_out = 'audit_sample' or coalesce((v->>'transient')::boolean, false) is false then
      update pipeline.layer4_review_items set escalation_reason = left('Machine rule aer-machine-v1 did not admit this: ' || (v->>'rule') || '. ' || regexp_replace(coalesce(escalation_reason, ''), '^Machine rule aer-machine-v1[^:]*: [a-z0-9_]+\. ', ''), 1000) -- fixed: the column shows 1000 characters
       where id = p_item and status = 'pending' and coalesce(escalation_reason, '') not like 'Machine rule aer-machine-v1 did not admit this: ' || (v->>'rule') || '.%';
    end if;
    if not exists (select 1 from pipeline.aer_machine_admissions m where m.review_item_id = p_item and m.mode = 'admit' and m.outcome = v_out and m.reason_code is not distinct from v->>'rule') then
      insert into pipeline.aer_machine_admissions (review_item_id, course_id, provider_id, mode, outcome, reason_code, reason, next_action, checks, actor)
      values (p_item, v_course, v_prov, 'admit', v_out, v->>'rule', v->>'reason', v->>'next_action', coalesce(v->'checks', '{}'::jsonb), v_sys);
    end if;
    return jsonb_build_object('ok', false, 'mode', 'admit', 'outcome', v_out, 'rule', v->>'rule', 'reason', v->>'reason');
  end if;
  -- admit: the same apply a person's approval uses (E13 runs again inside it), then the same records
  v_aer := security.aer_review_lineage_v1(p_item);
  v_reason := format('Auto (aer-machine-v1, %s): complete first read (E13 and D-R3 passed), %s rows each with an exact quote on the stored page %s (content hash %s), page bound to the course by %s, confidence at least %s. Not a person''s decision.',
                     coalesce(p_via, 'run'), v->'checks'->>'rows', coalesce(v->'checks'->>'source_url', ''), left(coalesce(v->'checks'->>'content_hash', ''), 12), v->'checks'->>'identity_basis', v->'checks'->>'min_confidence'); -- fixed: a short hash prefix for reading; the full hash is in the ledger
  -- 13 Nov 2026: machine Approve except, the same apply a person's Approve except uses
  if coalesce((v->'checks'->>'held_back')::int, 0) > 0 then
    v_reason := v_reason || format(' Approve except (Platform Admin 12 Nov 2026 22:25): %s row(s) held back, each failing a row rule; they are not admitted.', v->'checks'->>'held_back');
  end if;
  v_res := security.course_entry_review_apply_v1(p_item, 'approve', (i.proposed_value - 'exclude_row_ids')
             || case when coalesce((v->'checks'->>'held_back')::int, 0) > 0 then jsonb_build_object('exclude_row_ids', v->'checks'->'exclude_row_ids') else '{}'::jsonb end, v_reason);
  select count(*) into v_after from catalogue.course_entry_requirements x where x.provenance->>'review_item_id' = p_item::text and x.status = 'active';
  if v_after = 0 or v_after <> coalesce((v_res->>'admitted')::int, -1) then raise exception 'aer-machine: read-back found % active rows, apply reported %', v_after, v_res->>'admitted'; end if;
  update pipeline.layer4_review_items set status = 'approved', decided_at = now() where id = p_item and status = 'pending';
  insert into pipeline.layer4_decisions (review_item_id, action, actor_id, reason, before_value, proposed_value, final_value, evidence_id, layer2_state, layer3_state, change_control_ref)
  values (i.id, 'approve', v_sys, v_reason, i.before_value, i.proposed_value, i.proposed_value - 'exclude_row_ids', i.evidence_id,
          coalesce(i.layer2_state, '{}'::jsonb) || jsonb_build_object('machine_rule', 'aer-machine-v1', 'actor_kind', 'machine', 'via', coalesce(p_via, 'run')), coalesce(i.layer3_state, '{}'::jsonb), v_ref)
  returning id into v_dec;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('layer4', 'aer_approve', 'pipeline.layer4_review_items', jsonb_build_object('review_item_id', i.id, 'decision_id', v_dec, 'kind', i.field_code, 'reason', v_reason, 'lineage', v_aer,
          'excluded_row_ids', '[]'::jsonb, 'result', v_res, 'auto', true, 'machine_rule', 'aer-machine-v1', 'actor_kind', 'machine'), v_sys);
  insert into pipeline.search_refresh_signals(entity_type, entity_id, review_decision_id, reason, change_control_ref)
  values ('course', i.entity_id, v_dec, 'Accepted machine-rule Layer 4 canonical change: ' || v_reason, v_ref);
  insert into pipeline.aer_machine_admissions (review_item_id, course_id, provider_id, mode, outcome, reason_code, reason, checks, rows_admitted, decision_id, evidence_id, content_hash, source_url, actor)
  values (i.id, v_course, v_prov, 'admit', 'admitted', 'aer-machine-v1', v_reason, coalesce(v->'checks', '{}'::jsonb) || jsonb_build_object('apply', v_res, 'via', coalesce(p_via, 'run')),
          v_after, v_dec, i.evidence_id, v->'checks'->>'content_hash', v->'checks'->>'source_url', v_sys);
  return jsonb_build_object('ok', true, 'mode', 'admit', 'outcome', 'admitted', 'decision_id', v_dec, 'rows', v_after);
end $$;


ALTER FUNCTION "security"."aer_machine_admit_v1"("p_item" "uuid", "p_via" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_machine_admit_v1"("p_item" "uuid", "p_via" "text") IS 'CF-247 F-AER.04 rule aer-machine-v1 for one waiting first course entry read. Mode 1 (or 2 without a passing validation, or while suspended): records the shadow result only. Mode 2: admits through security.course_entry_review_apply_v1 (the apply a person''s approval uses), settles the item as a machine decision under the system automation account and records the A1 lineage event, the search refresh signal and the ledger; anything else stays waiting with the exact reason.';



CREATE OR REPLACE FUNCTION "security"."aer_machine_check_v1"("p_item" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_review_items%rowtype; c catalogue.courses%rowtype; g pipeline.coverage_course_pages%rowtype; v_gate jsonb; v_ev pipeline.evidence_artifacts%rowtype; v_bev pipeline.evidence_artifacts%rowtype;
        v_conf numeric := security.pipeline_num_v1('aer.machine_min_confidence', 0.8); v_qmin int := security.pipeline_num_v1('aer.machine_min_quote_chars', 8)::int;
        v_audit numeric := security.pipeline_num_v1('aer.machine_audit_pct', 5); v_n int; v_bad int; v_bucket int; v_checks jsonb := '{}'::jsonb;
        v_ex uuid[] := '{}'::uuid[]; v_exon boolean := security.pipeline_num_v1('aer.machine_except_on', 0) >= 1;
  function_fail constant text := 'A person decides in Layer 4.';
begin
  select * into i from pipeline.layer4_review_items where id = p_item;
  if i.id is null or i.entity_type <> 'course' or i.field_code <> 'course_entry_first_read' then
    return jsonb_build_object('ok', false, 'rule', 'not_a_course_entry_read', 'reason', 'Only first course entry reads are in scope.', 'next_action', function_fail);
  end if;
  if i.status <> 'pending' then return jsonb_build_object('ok', false, 'rule', 'item_not_pending', 'reason', 'The item is ' || i.status || '.', 'next_action', 'Nothing to do.'); end if;
  if i.claimed_at is not null and i.claimed_at > now() - make_interval(mins => 60) then -- fixed: a person who opened the item in the last hour keeps it
    return jsonb_build_object('ok', false, 'rule', 'claimed_by_person', 'reason', 'A person opened this item in the last hour.', 'next_action', 'The person decides; the rule looks again later.', 'transient', true);
  end if;
  select * into c from catalogue.courses where id = i.entity_id;
  if c.id is null or c.lifecycle_status <> 'active' then return jsonb_build_object('ok', false, 'rule', 'course_not_active', 'reason', 'The course is not active.', 'next_action', function_fail); end if;
  if exists (select 1 from security.provider_hidden_v1 h where h.provider_id = c.provider_id) then
    return jsonb_build_object('ok', false, 'rule', 'provider_hidden', 'reason', 'The provider is hidden.', 'next_action', function_fail);
  end if;
  if exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = c.id and l.field in ('entry_requirements', 'all')) then
    return jsonb_build_object('ok', false, 'rule', 'manual_lock', 'reason', 'The course''s entry requirements are locked by a person.', 'next_action', function_fail);
  end if;
  -- no earlier person's rejection or return of an entry read for this course (conflicting evidence goes to a person)
  if exists (select 1 from pipeline.layer4_review_items o where o.entity_id = c.id and o.field_code = 'course_entry_first_read' and o.id <> i.id
               and o.status in ('rejected', 'more_evidence', 'returned_layer2', 'returned_layer3')) then
    return jsonb_build_object('ok', false, 'rule', 'earlier_rejection', 'reason', 'A person rejected or returned an earlier entry read of this course.', 'next_action', function_fail);
  end if;
  if exists (select 1 from pipeline.layer4_review_items o where o.entity_id = c.id and o.field_code = 'course_entry_first_read' and o.status = 'pending' and o.id <> i.id) then
    return jsonb_build_object('ok', false, 'rule', 'duplicate_waiting', 'reason', 'Another entry read of this course is also waiting.', 'next_action', function_fail);
  end if;
  if exists (select 1 from catalogue.course_entry_requirements x where x.course_id = c.id and x.status = 'active') then
    return jsonb_build_object('ok', false, 'rule', 'active_rows_exist', 'reason', 'The course already has active entry requirements; replacing them is a person''s decision.', 'next_action', function_fail);
  end if;
  if exists (select 1 from pipeline.aer_machine_admissions m where m.course_id = c.id and m.outcome = 'withdrawn') then
    return jsonb_build_object('ok', false, 'rule', 'withdrawn_awaiting_person', 'reason', 'A machine admission of this course was withdrawn.', 'next_action', function_fail);
  end if;
  -- source identity and provenance: the course's current bound page, an identity basis admitted for entry requirements, and the read taken from that page's content
  select * into g from pipeline.coverage_course_pages p where p.course_id = c.id and p.status = 'bound' order by p.bound_at desc nulls last limit 1;
  if g.course_id is null then return jsonb_build_object('ok', false, 'rule', 'no_bound_page', 'reason', 'The course has no bound course page now.', 'next_action', function_fail); end if;
  if not (security.coverage_identity_allowed(c.provider_id, g.identity_basis, 'entry_requirements') or coalesce((security.aer_title_identity_ok_v1(c.id)->>'ok')::boolean, false)) then -- 20261111040000
    return jsonb_build_object('ok', false, 'rule', 'identity_not_admitted', 'reason', format('The page is matched to the course by %s, which is not admitted for entry requirements.', coalesce(g.identity_basis, 'no basis')), 'next_action', function_fail);
  end if;
  select * into v_ev from pipeline.evidence_artifacts where id = i.evidence_id;
  select * into v_bev from pipeline.evidence_artifacts where id = g.evidence_id;
  if v_ev.id is null or v_ev.storage_path is null then return jsonb_build_object('ok', false, 'rule', 'evidence_missing', 'reason', 'The stored page the read came from is missing.', 'next_action', function_fail); end if;
  -- the read's stored page must be the course's bound page: the same stored copy, the same content, or (the bound page captured again since) the same address
  -- with the read's copy still inside the platform's freshness period for entry sources (aer.stale_source_days, 90; a re-capture changes the raw hash every day)
  if i.evidence_id is distinct from g.evidence_id and (v_ev.content_hash is null or v_ev.content_hash is distinct from v_bev.content_hash) then
    if v_bev.id is null or v_ev.source_url is distinct from v_bev.source_url then
      return jsonb_build_object('ok', false, 'rule', 'page_changed_since_read', 'reason', 'The course is now bound to a different page from the one this read was taken from.', 'next_action', 'A person decides, or the read is replaced by a read of the current page.');
    end if;
    if v_ev.captured_at < now() - make_interval(days => security.pipeline_num_v1('aer.stale_source_days', 90)::int) then
      return jsonb_build_object('ok', false, 'rule', 'read_copy_stale', 'reason', format('The read was taken from a copy captured %s, older than the freshness period for entry sources.', v_ev.captured_at::date), 'next_action', 'A person decides, or the read is replaced by a read of the current page.');
    end if;
    v_checks := v_checks || jsonb_build_object('recaptured_since_read', true, 'read_copy_captured_at', v_ev.captured_at, 'bound_copy_captured_at', v_bev.captured_at);
  end if;
  v_checks := v_checks || jsonb_build_object('identity_basis', g.identity_basis, 'title_identity', case when security.coverage_identity_allowed(c.provider_id, g.identity_basis, 'entry_requirements') then null else security.aer_title_identity_ok_v1(c.id) end, 'source_url', v_ev.source_url, 'content_hash', v_ev.content_hash, 'evidence_id', v_ev.id);
  -- the rows: at least one, each with an exact quote (verified on the page by the reader), enough confidence, from this item's evidence
  select count(*), count(*) filter (where coalesce(length(btrim(x.quote)), 0) < v_qmin or coalesce(x.confidence, 0) < v_conf or x.evidence_id is distinct from i.evidence_id)
    into v_n, v_bad
    from catalogue.course_entry_requirements x where x.provenance->>'review_item_id' = i.id::text and x.status = 'proposed';
  if v_n = 0 then return jsonb_build_object('ok', false, 'rule', 'no_rows', 'reason', 'The read has no waiting rows.', 'next_action', function_fail); end if;
  if v_bad > 0 and v_exon then
    -- 13 Nov 2026 (machine Approve except): rows without an exact quote, enough confidence or this read's evidence are held back
    select coalesce(array_agg(x.id), '{}'::uuid[]) into v_ex from catalogue.course_entry_requirements x
     where x.provenance->>'review_item_id' = i.id::text and x.status = 'proposed'
       and (coalesce(length(btrim(x.quote)), 0) < v_qmin or coalesce(x.confidence, 0) < v_conf or x.evidence_id is distinct from i.evidence_id);
  elsif v_bad > 0 then
    return jsonb_build_object('ok', false, 'rule', 'row_unsupported', 'reason', format('%s of %s waiting rows lack an exact quote of %s characters, confidence %s or this read''s evidence.', v_bad, v_n, v_qmin, v_conf), 'next_action', function_fail, 'checks', v_checks);
  end if;
  -- completeness: E13 + D-R3 (the same gate a person's approval runs)
  v_gate := security.course_entry_gate_v1(i.id, v_ex);
  -- 13 Nov 2026 (machine Approve except): rows the gate names at row level (domestic route stored for all, not a requirement, another programme) are held back
  -- and the gate is run again on the rest; any other gate class (dropped printed requirement, rows cut, shared page) still holds the whole read
  if v_exon and v_gate is not null and not coalesce((v_gate->>'complete')::boolean, false) and security.aer_e13_class_v1(v_gate) = 'row_level' then
    v_ex := v_ex || coalesce(array(select (e->>'id')::uuid
                                     from jsonb_array_elements(coalesce(v_gate->'audience', '[]'::jsonb) || coalesce(v_gate->'not_requirement', '[]'::jsonb) || coalesce(v_gate->'other_programme', '[]'::jsonb)) e
                                    where jsonb_typeof(e) = 'object' and e ? 'id'), '{}'::uuid[]);
    v_gate := security.course_entry_gate_v1(i.id, v_ex);
  end if;
  if cardinality(v_ex) > 0 and v_n - cardinality(v_ex) <= 0 then
    return jsonb_build_object('ok', false, 'rule', 'all_rows_held', 'reason', 'Every waiting row fails a row rule, so nothing can be admitted automatically.', 'next_action', function_fail, 'checks', v_checks);
  end if;
  if v_gate is null or not coalesce((v_gate->>'complete')::boolean, false) then
    return jsonb_build_object('ok', false, 'rule', 'gate_incomplete', 'reason', coalesce((select string_agg(w, '; ') from jsonb_array_elements_text(v_gate->'reasons') w), 'The completeness gate did not pass.'),
                              'next_action', 'Technical recovery (aer-replay, corrected reads) or a person in Layer 4.', 'checks', v_checks);
  end if;
  v_checks := v_checks || jsonb_build_object('rows', v_n, 'gate', 'E13 complete', 'min_confidence', v_conf, 'min_quote_chars', v_qmin)
              || case when cardinality(v_ex) > 0 then jsonb_build_object('exclude_row_ids', to_jsonb(v_ex), 'held_back', cardinality(v_ex)) else '{}'::jsonb end;
  -- random audit sample: deterministic per item, so a re-run gives the same answer
  v_bucket := (('x' || substr(md5(i.id::text || ':aer-machine-v1'), 1, 8))::bit(32)::bigint % 100)::int; -- fixed: 100 buckets for a per-cent share
  if v_bucket < v_audit then
    return jsonb_build_object('ok', false, 'rule', 'audit_sample', 'audit', true, 'reason', format('Random audit sample (%s%%): the rule would admit this read; a person checks it.', v_audit), 'next_action', function_fail, 'checks', v_checks);
  end if;
  return jsonb_build_object('ok', true, 'rule', case when cardinality(v_ex) > 0 then 'aer-machine-v1-except' else 'aer-machine-v1' end, 'course_id', c.id, 'provider_id', c.provider_id, 'checks', v_checks);
end $$;


ALTER FUNCTION "security"."aer_machine_check_v1"("p_item" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_machine_check_v1"("p_item" "uuid") IS 'CF-247 F-AER.04 rule aer-machine-v1 (read only): whether a waiting first course entry read is complete and source-proved enough for machine admission. The first failing check names the rule, the reason and the next action. A random audit sample (aer.machine_audit_pct) is returned as audit_sample. A re-capture of the same bound address passes inside aer.stale_source_days (20261111030000).';



CREATE OR REPLACE FUNCTION "security"."aer_machine_history_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with s as (select security.pipeline_num_v1('aer.machine_min_confidence', 0.8) conf, security.pipeline_num_v1('aer.machine_min_quote_chars', 8)::int qmin),
  h as (select i.id, d.action, i.proposed_value
          from pipeline.layer4_review_items i join pipeline.layer4_decisions d on d.review_item_id = i.id
         where i.field_code = 'course_entry_first_read' and d.actor_id is distinct from security.system_actor_id()),
  x as (select h.id, h.action,
               (select count(*) from catalogue.course_entry_requirements r where r.provenance->>'review_item_id' = h.id::text) nrows,
               (select count(*) from catalogue.course_entry_requirements r cross join s where r.provenance->>'review_item_id' = h.id::text
                  and (coalesce(length(btrim(r.quote)), 0) < s.qmin or coalesce(r.confidence, 0) < s.conf)) bad,
               security.course_entry_read_check_v1(
                 (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'kind', r.kind, 'audience', r.audience, 'quote', r.quote)), '[]'::jsonb)
                    from catalogue.course_entry_requirements r where r.provenance->>'review_item_id' = h.id::text and r.status in ('active', 'superseded')),
                 coalesce(h.proposed_value->'dropped', '[]'::jsonb)) chk
          from h),
  y as (select x.*, (nrows > 0 and bad = 0 and jsonb_array_length(coalesce(chk->'drops_uncovered', '[]')) = 0 and jsonb_array_length(coalesce(chk->'not_requirement', '[]')) = 0
                     and jsonb_array_length(coalesce(chk->'audience', '[]')) = 0) would from x)
  select jsonb_build_object('contract', 'aer-machine-history-v1', 'as_at', now(), 'human_decisions', count(*),
           'human_approved', count(*) filter (where action in ('approve', 'edit_and_approve')),
           'human_not_approved', count(*) filter (where action not in ('approve', 'edit_and_approve')),
           'rule_would_admit', count(*) filter (where would),
           'rule_would_admit_and_human_approved', count(*) filter (where would and action = 'approve'),
           'rule_would_admit_but_human_edited_or_refused', count(*) filter (where would and action <> 'approve'),
           'rule_would_hold_human_approved', count(*) filter (where not would and action in ('approve', 'edit_and_approve')),
           'disagreements', coalesce(jsonb_agg(jsonb_build_object('item', id, 'action', action)) filter (where would and action <> 'approve'), '[]'::jsonb),
           'note', 'Row-level rules (quote, confidence, read check E13 drops / not-a-requirement / audience) over rows as recorded; identity and page-change rules use the binding at decision time, which is not kept, so they are not part of this measure.')
    from y
$$;


ALTER FUNCTION "security"."aer_machine_history_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_machine_history_v1"() IS 'CF-247 F-AER.04 (read only): how rule aer-machine-v1''s row-level checks agree with the human decisions already made on first course entry reads.';



CREATE OR REPLACE FUNCTION "security"."aer_machine_report_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('contract', 'aer-machine-report-v1', 'as_at', now(),
    'mode', security.pipeline_num_v1('aer.machine_mode', 0), 'suspended', security.pipeline_num_v1('aer.machine_suspended', 0) >= 1,
    'validated', (select jsonb_build_object('passed', x.passed, 'at', x.validated_at) from pipeline.aer_machine_validations x order by x.validated_at desc limit 1),
    'shadow', (select coalesce(jsonb_object_agg(k, n), '{}'::jsonb) from (select m.outcome k, count(*) n from pipeline.aer_machine_admissions m join pipeline.layer4_review_items i on i.id = m.review_item_id and i.status = 'pending' where m.mode = 'shadow' group by 1) z),
    'shadow_declined_by_rule', (select coalesce(jsonb_object_agg(k, n), '{}'::jsonb) from (select m.reason_code k, count(*) n from pipeline.aer_machine_admissions m join pipeline.layer4_review_items i on i.id = m.review_item_id and i.status = 'pending' where m.mode = 'shadow' and m.outcome = 'declined' group by 1) z),
    'admitted', (select count(*) from pipeline.aer_machine_admissions where mode = 'admit' and outcome = 'admitted' and withdrawn_at is null),
    'admitted_24h', (select count(*) from pipeline.aer_machine_admissions where mode = 'admit' and outcome = 'admitted' and withdrawn_at is null and created_at > now() - make_interval(hours => 24)), -- fixed: report window
    'rows_admitted', (select coalesce(sum(rows_admitted), 0) from pipeline.aer_machine_admissions where mode = 'admit' and outcome = 'admitted' and withdrawn_at is null),
    'withdrawn', (select count(*) from pipeline.aer_machine_admissions where outcome = 'withdrawn'),
    'courses_with_active_aer', (select count(distinct course_id) from catalogue.course_entry_requirements where status = 'active'),
    'waiting_course_reads', (select count(*) from pipeline.layer4_review_items where field_code = 'course_entry_first_read' and status = 'pending'))
$$;


ALTER FUNCTION "security"."aer_machine_report_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_machine_report_v1"() IS 'CF-247 F-AER.04 scoreboard (read only): mode, suspension, last validation, shadow outcomes and decline rules on waiting items, admissions (total, 24 hours, rows), withdrawals, courses with active AER and waiting reads.';



CREATE OR REPLACE FUNCTION "security"."aer_machine_run_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_mode int := security.pipeline_num_v1('aer.machine_mode', 0)::int; v_batch int := security.pipeline_num_v1('batch.aer_machine', 60)::int;
        v_cap int := security.pipeline_num_v1('aer.machine_daily_max', 300)::int; v_used int; v_t0 timestamptz := clock_timestamp(); v_susp jsonb; r record; v jsonb;
        v_n int := 0; v_out jsonb := '{}'::jsonb; v_err int := 0;
begin
  -- 12 Nov 2026 (F-AER.04, decision D1): with course admission off the job still steps the matrix class, which has its own switch (aer.matrix_machine_mode)
  if v_mode < 1 then return jsonb_build_object('mode', 0, 'matrix', security.aer_matrix_machine_run_v1()); end if;
  begin v_susp := security.aer_machine_suspend_check_v1(); exception when others then v_susp := jsonb_build_object('error', sqlerrm); end;
  select count(*) into v_used from pipeline.aer_machine_admissions where mode = 'admit' and outcome = 'admitted' and created_at > now() - make_interval(hours => 24); -- fixed: the cap counts the last 24 hours
  -- gate-complete items first (the readiness job's record), then the rest that were never looked at by the rule, oldest first
  for r in select i.id from pipeline.layer4_review_items i
             left join pipeline.layer4_item_readiness k on k.item_id = i.id
             left join pipeline.aer_machine_admissions s on s.review_item_id = i.id and s.mode = 'shadow'
            where i.status = 'pending' and i.field_code = 'course_entry_first_read' and i.entity_type = 'course'
              and (s.id is null or s.updated_at < now() - make_interval(hours => 6) or coalesce(k.gate_checked_at, '-infinity') > s.updated_at) -- fixed: an unchanged item is looked at again after 6 hours
            order by coalesce((k.gate->>'complete')::boolean, false) desc, (s.id is null) desc, i.created_at
            limit v_batch loop
    exit when clock_timestamp() - v_t0 > make_interval(secs => 45); -- fixed: a run stays inside the job's time
    exit when v_mode >= 2 and v_used >= v_cap;
    begin
      v := security.aer_machine_admit_v1(r.id, 'run');
      v_n := v_n + 1;
      v_out := jsonb_set(v_out, array[coalesce(v->>'outcome', v->>'rule', 'unknown')], to_jsonb(coalesce((v_out->>coalesce(v->>'outcome', v->>'rule', 'unknown'))::int, 0) + 1));
      if v->>'outcome' = 'admitted' then v_used := v_used + 1; end if;
    exception when others then v_err := v_err + 1;
    end;
  end loop;
  return jsonb_build_object('mode', v_mode, 'effective', case when v_mode >= 2 and security.pipeline_num_v1('aer.machine_suspended', 0) < 1
                              and exists (select 1 from pipeline.aer_machine_validations x where x.passed and x.validated_at > now() - make_interval(days => 7)) then 'admit' else 'shadow' end,
                            'checked', v_n, 'outcomes', v_out, 'errors', v_err, 'admitted_24h', v_used, 'cap', v_cap, 'suspension', v_susp)
         -- 12 Nov 2026 (F-AER.04, decision D1): the same job steps rule aer-matrix-machine-v1 (country tables and qualification rows); its own ledger, errors returned, never raised
         || jsonb_build_object('matrix', security.aer_matrix_machine_run_v1());
end $$;


ALTER FUNCTION "security"."aer_machine_run_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_machine_run_v1"() IS 'CF-247 F-AER.04: one run of the catalogued job aer-machine-admission: the suspension check, then up to batch.aer_machine waiting course reads through rule aer-machine-v1 (gate-complete first), within aer.machine_daily_max in admit mode. Does nothing while aer.machine_mode is 0.';



CREATE OR REPLACE FUNCTION "security"."aer_machine_suspend_check_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_bad record; v_sys uuid := security.system_actor_id();
begin
  if security.pipeline_num_v1('aer.machine_suspended', 0) >= 1 then return jsonb_build_object('suspended', true, 'already', true); end if;
  -- a person's non-approval of a read the rule would have admitted (audit sample or shadow would_admit), or a withdrawal
  select d.review_item_id item, d.action, d.created_at, m.outcome into v_bad
    from pipeline.layer4_decisions d
    join pipeline.aer_machine_admissions m on m.review_item_id = d.review_item_id and m.outcome in ('audit_sample', 'would_admit')
   where d.actor_id is distinct from v_sys and d.action in ('reject', 'request_more_evidence', 'return_layer2', 'return_layer3') and d.created_at > m.created_at
   order by d.created_at desc limit 1;
  if v_bad.item is null then
    select m.review_item_id item, 'withdrawn' action, m.withdrawn_at created_at, m.outcome into v_bad from pipeline.aer_machine_admissions m where m.outcome = 'withdrawn' order by m.withdrawn_at desc limit 1;
  end if;
  if v_bad.item is null then return jsonb_build_object('suspended', false); end if;
  if exists (select 1 from pipeline.admin_control_events e where e.area = 'pipeline' and e.action = 'aer_machine_suspended' and e.detail->>'review_item_id' = v_bad.item::text) then
    return jsonb_build_object('suspended', false, 'note', 'the defect on item ' || v_bad.item || ' was already acted on and a person resumed the rule');
  end if;
  update pipeline.platform_toolset_settings set value = to_jsonb(1), updated_at = now(),
         reason = format('Suspended by rule aer-machine-v1: a person %s item %s that the rule would have admitted (%s). A person reviews and sets this back to 0 with a reason.', v_bad.action, v_bad.item, v_bad.outcome)
   where toolset_key = 'pipeline' and key = 'aer.machine_suspended';
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('pipeline', 'aer_machine_suspended', 'aer.machine_suspended', jsonb_build_object('review_item_id', v_bad.item, 'person_action', v_bad.action, 'at', v_bad.created_at, 'ledger_outcome', v_bad.outcome), v_sys);
  return jsonb_build_object('suspended', true, 'item', v_bad.item, 'action', v_bad.action);
end $$;


ALTER FUNCTION "security"."aer_machine_suspend_check_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_machine_suspend_check_v1"() IS 'CF-247 F-AER.04: sets aer.machine_suspended = 1 (admission stops, shadow continues) when a person rejects or returns a read the rule would have admitted, or a machine admission is withdrawn. Each defect suspends once; only a person resumes.';



CREATE OR REPLACE FUNCTION "security"."aer_machine_validate_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_hist jsonb := security.aer_machine_history_v1(); v_min_h numeric := security.pipeline_num_v1('aer.machine_shadow_min_hours', 24);
        v_first timestamptz; v_hours numeric; v_n int; v_would int; v_regress int := 0; v_human_bad int; r record; v_c jsonb; v_pass boolean; v_detail jsonb;
begin
  select min(created_at), count(*), count(*) filter (where outcome = 'would_admit') into v_first, v_n, v_would from pipeline.aer_machine_admissions where mode = 'shadow';
  v_hours := extract(epoch from (now() - coalesce(v_first, now()))) / 3600.0;
  -- independent re-check: every current would_admit item is checked again now; one that no longer passes (other than now decided or claimed) is a regression
  for r in select m.review_item_id from pipeline.aer_machine_admissions m join pipeline.layer4_review_items i on i.id = m.review_item_id and i.status = 'pending'
            where m.mode = 'shadow' and m.outcome = 'would_admit' loop
    v_c := security.aer_machine_check_v1(r.review_item_id);
    if not coalesce((v_c->>'ok')::boolean, false) and coalesce(v_c->>'rule', '') not in ('audit_sample', 'claimed_by_person', 'item_not_pending') then v_regress := v_regress + 1; end if;
  end loop;
  select count(*) into v_human_bad from pipeline.layer4_decisions d join pipeline.aer_machine_admissions m on m.review_item_id = d.review_item_id and m.outcome in ('would_admit', 'audit_sample')
   where d.actor_id is distinct from security.system_actor_id() and d.action <> 'approve';
  v_pass := v_hours >= v_min_h and v_n >= 50 and v_regress = 0 and v_human_bad = 0 -- fixed: at least 50 shadow results
            and coalesce((v_hist->>'rule_would_admit_but_human_edited_or_refused')::int, 1) <= greatest(1, ((v_hist->>'rule_would_admit')::int) / 50); -- fixed: at most 2% disagreement with past human decisions
  v_detail := jsonb_build_object('shadow_hours', round(v_hours, 1), 'shadow_min_hours', v_min_h, 'shadow_results', v_n, 'shadow_would_admit', v_would, 'regressions_on_recheck', v_regress,
                                 'human_non_approvals_of_rule_admits', v_human_bad, 'history', v_hist - 'disagreements', 'history_disagreements', v_hist->'disagreements');
  insert into pipeline.aer_machine_validations(passed, detail, validated_by) values (v_pass, v_detail, auth.uid());
  return v_detail || jsonb_build_object('passed', v_pass, 'note', 'A pass does not switch admission on. A person (or the Integration Controller under the Platform Admin decision) sets aer.machine_mode to 2 with a reason.');
end $$;


ALTER FUNCTION "security"."aer_machine_validate_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_machine_validate_v1"() IS 'CF-247 F-AER.04: records whether rule aer-machine-v1 may be switched to admit: shadow period, at least 50 shadow results, every would-admit re-checked now with no regression, no person refused a read the rule would admit, and agreement with past human decisions. Never changes a setting.';



CREATE OR REPLACE FUNCTION "security"."aer_machine_withdraw_v1"("p_item" "uuid", "p_reason" "text", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare m pipeline.aer_machine_admissions%rowtype; v_n int;
begin
  if length(btrim(coalesce(p_reason, ''))) < 5 then raise exception 'a reason is required'; end if;
  select * into m from pipeline.aer_machine_admissions where review_item_id = p_item and mode = 'admit' and outcome = 'admitted' and withdrawn_at is null for update;
  if m.id is null then raise exception 'no machine admission to withdraw for item %', p_item; end if;
  if exists (select 1 from pipeline.layer4_decisions d where d.review_item_id = p_item and d.actor_id is distinct from security.system_actor_id()) then
    raise exception 'a person has decided this item since; withdraw through Layer 4';
  end if;
  update catalogue.course_entry_requirements x set status = 'proposed', status_reason = 'machine admission withdrawn: ' || btrim(p_reason), updated_at = now()
   where x.provenance->>'review_item_id' = p_item::text and x.status = 'active';
  get diagnostics v_n = row_count;
  update pipeline.layer4_review_items set status = 'pending', decided_at = null,
         escalation_reason = left('Machine admission (aer-machine-v1) withdrawn: ' || btrim(p_reason) || '. A person decides.', 1000) where id = p_item; -- fixed: column display width
  update pipeline.aer_machine_admissions set withdrawn_at = now(), withdrawn_reason = btrim(p_reason), updated_at = now() where id = m.id;
  insert into pipeline.aer_machine_admissions (review_item_id, course_id, provider_id, mode, outcome, reason_code, reason, rows_admitted, decision_id, actor)
  values (p_item, m.course_id, m.provider_id, 'admit', 'withdrawn', 'withdrawn', btrim(p_reason), v_n, m.decision_id, p_actor);
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('layer4', 'aer_machine_withdraw', 'pipeline.layer4_review_items', jsonb_build_object('review_item_id', p_item, 'rows_back_to_proposed', v_n, 'reason', btrim(p_reason), 'decision_id', m.decision_id), p_actor);
  insert into pipeline.search_refresh_signals(entity_type, entity_id, review_decision_id, reason, change_control_ref)
  values ('course', m.course_id, m.decision_id, 'Machine admission withdrawn: ' || btrim(p_reason), 'CF-247 F-AER.04');
  return jsonb_build_object('ok', true, 'rows_back_to_proposed', v_n, 'item', p_item);
end $$;


ALTER FUNCTION "security"."aer_machine_withdraw_v1"("p_item" "uuid", "p_reason" "text", "p_actor" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_machine_withdraw_v1"("p_item" "uuid", "p_reason" "text", "p_actor" "uuid") IS 'CF-247 F-AER.04: rollback of one machine admission: its rows back to proposed, the item back to pending for a person, ledger and decision kept, and the rule suspended by the next run.';



CREATE OR REPLACE FUNCTION "security"."aer_matrix_machine_admit_v1"("p_item" "uuid", "p_via" "text" DEFAULT 'run'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_review_items%rowtype; v jsonb; v_mode int := security.aer_matrix_machine_effective_v1(); v_res jsonb; v_dec uuid; v_reason text; v_out text;
        v_sys uuid := security.system_actor_id(); v_run uuid; v_after int;
        v_ref constant text := 'CF-247 F-AER.04; Platform Admin decision D1 11 Nov 2026 (machine admission of source-verified country tables and qualification rows)';
begin
  if v_mode < 1 then return jsonb_build_object('ok', false, 'rule', 'matrix_machine_off'); end if;
  if v_mode >= 2 then
    select * into i from pipeline.layer4_review_items where id = p_item for update skip locked;
    if i.id is null then return jsonb_build_object('ok', false, 'rule', 'item_locked'); end if;
  else
    select * into i from pipeline.layer4_review_items where id = p_item;
  end if;
  v := security.aer_matrix_machine_check_v1(p_item);
  v_run := nullif(v->'checks'->>'run_id', '')::uuid;
  v_out := case when coalesce((v->>'ok')::boolean, false) then (case when v_mode >= 2 then 'admitted' else 'would_admit' end)
                when coalesce((v->>'audit')::boolean, false) then 'audit_sample' else 'declined' end;
  if v_mode < 2 then
    insert into pipeline.aer_matrix_machine_admissions (review_item_id, provider_id, run_id, mode, outcome, reason_code, reason, checks, actor)
    values (p_item, i.entity_id, v_run, 'shadow', v_out, v->>'rule', v->>'reason', coalesce(v->'checks', '{}'::jsonb), v_sys)
    on conflict (review_item_id) where mode = 'shadow' do update set outcome = excluded.outcome, reason_code = excluded.reason_code, reason = excluded.reason,
           checks = excluded.checks, run_id = excluded.run_id, updated_at = now();
    return jsonb_build_object('ok', true, 'mode', 'shadow', 'outcome', v_out, 'rule', v->>'rule');
  end if;
  if v_out <> 'admitted' then
    if v->>'rule' not in ('item_not_pending', 'not_this_class', 'claimed_by_person', 'decided') then
      update pipeline.layer4_review_items set escalation_reason = left('Machine rule aer-matrix-machine-v1 did not admit this: ' || (v->>'rule') || '. '
               || regexp_replace(coalesce(escalation_reason, ''), '^Machine rule aer-matrix-machine-v1[^:]*: [a-z0-9_]+\. ', ''), 1000)  -- fixed: the column shows 1000 characters
       where id = p_item and status = 'pending' and coalesce(escalation_reason, '') not like 'Machine rule aer-matrix-machine-v1 did not admit this: ' || (v->>'rule') || '.%';
    end if;
    if not exists (select 1 from pipeline.aer_matrix_machine_admissions m where m.review_item_id = p_item and m.mode = 'admit' and m.outcome = v_out and m.reason_code is not distinct from v->>'rule') then
      insert into pipeline.aer_matrix_machine_admissions (review_item_id, provider_id, run_id, mode, outcome, reason_code, reason, checks, actor)
      values (p_item, i.entity_id, v_run, 'admit', v_out, v->>'rule', v->>'reason', coalesce(v->'checks', '{}'::jsonb), v_sys);
    end if;
    return jsonb_build_object('ok', false, 'mode', 'admit', 'outcome', v_out, 'rule', v->>'rule');
  end if;
  -- admit: the same apply a person's approval uses (D-R3, D4 and the completeness guard run again inside it), then the same records
  v_reason := format('Auto (aer-matrix-machine-v1, %s): first read of the provider''s own source %s (host %s, content hash %s), %s country rows and %s qualification rows, each with an exact quote, a published minimum, a mapped level and confidence at least %s; qualification applicability explicit. Not a person''s decision.',
                     coalesce(p_via, 'run'), coalesce(v->'checks'->>'source_url', ''), v->'checks'->>'host', left(coalesce(v->'checks'->>'content_hash', ''), 12),
                     v->'checks'->>'rows', v->'checks'->>'qualification_rows', v->'checks'->>'min_confidence');  -- fixed: a short hash prefix for reading; the full hash is in the ledger
  -- 12 Nov 2026 (Platform Admin 22:25): machine Approve except, the same apply a person's Approve except uses
  if coalesce((v->'checks'->>'held_back')::int, 0) > 0 then
    v_reason := v_reason || format(' Approve except (Platform Admin 12 Nov 2026 22:25): %s row(s) held back, each failing a row rule (%s); they are not admitted.',
                                   v->'checks'->>'held_back', v->'checks'->'held_back_by_rule');
  end if;
  v_res := security.entry_matrix_review_apply_v1(p_item, 'approve', jsonb_build_object('reviewer', 'aer-matrix-machine-v1',
             'exclude_row_ids', coalesce(v->'checks'->'exclude_row_ids', '[]'::jsonb)), v_reason);
  select (select count(*) from catalogue.provider_entry_matrix m where m.run_id = v_run and m.status = 'active')
       + (select count(*) from catalogue.provider_qualification_requirements q where q.run_id = v_run and q.status = 'active') into v_after;
  if v_after = 0 or v_after <> coalesce((v_res->>'admitted')::int, 0) + coalesce((v_res->>'qualification_admitted')::int, 0) then
    raise exception 'aer-matrix-machine: read-back found % active rows, apply reported %', v_after, v_res; end if;
  update pipeline.layer4_review_items set status = 'approved', decided_at = now() where id = p_item and status = 'pending';
  insert into pipeline.layer4_decisions (review_item_id, action, actor_id, reason, before_value, proposed_value, final_value, evidence_id, layer2_state, layer3_state, change_control_ref)
  values (i.id, 'approve', v_sys, v_reason, i.before_value, i.proposed_value, i.proposed_value, i.evidence_id,
          coalesce(i.layer2_state, '{}'::jsonb) || jsonb_build_object('machine_rule', 'aer-matrix-machine-v1', 'actor_kind', 'machine', 'via', coalesce(p_via, 'run')), coalesce(i.layer3_state, '{}'::jsonb), v_ref)
  returning id into v_dec;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('layer4', 'aer_approve', 'pipeline.layer4_review_items', jsonb_build_object('review_item_id', i.id, 'decision_id', v_dec, 'kind', i.field_code, 'reason', v_reason,
          'result', v_res, 'auto', true, 'machine_rule', 'aer-matrix-machine-v1', 'actor_kind', 'machine'), v_sys);
  insert into pipeline.search_refresh_signals(entity_type, entity_id, review_decision_id, reason, change_control_ref)
  values ('provider', i.entity_id, v_dec, 'Accepted machine-rule Layer 4 canonical change: ' || v_reason, v_ref);
  insert into pipeline.aer_matrix_machine_admissions (review_item_id, provider_id, run_id, mode, outcome, reason_code, reason, checks, rows_admitted, decision_id, actor)
  values (i.id, i.entity_id, v_run, 'admit', 'admitted', 'aer-matrix-machine-v1', v_reason, coalesce(v->'checks', '{}'::jsonb) || jsonb_build_object('apply', v_res, 'via', coalesce(p_via, 'run')),
          v_after, v_dec, v_sys);
  return jsonb_build_object('ok', true, 'mode', 'admit', 'outcome', 'admitted', 'decision_id', v_dec, 'rows', v_after);
end $$;


ALTER FUNCTION "security"."aer_matrix_machine_admit_v1"("p_item" "uuid", "p_via" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_matrix_machine_admit_v1"("p_item" "uuid", "p_via" "text") IS 'CF-247 F-AER.04 (decision D1): rule aer-matrix-machine-v1 on one entry-matrix item: in shadow records what it would do; in admit mode (mode 2 with a passing validation) admits through security.entry_matrix_review_apply_v1 with the Layer 4 decision by the system actor (actor_kind machine), control event, search refresh signal and ledger row, or records why the item stays with a person.';



CREATE OR REPLACE FUNCTION "security"."aer_matrix_machine_check_v1"("p_item" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_review_items%rowtype; r pipeline.entry_matrix_runs%rowtype; f pipeline.entry_matrix_sources%rowtype; v_web text; v_sh text; v_ph text; g jsonb;
        v_conf numeric := security.pipeline_num_v1('aer.matrix_machine_min_confidence', 0.9); v_qmin int := security.pipeline_num_v1('aer.machine_min_quote_chars', 8)::int;
        v_pct numeric := security.pipeline_num_v1('aer.matrix_machine_audit_pct', 5); v_nm int; v_nq int; v_bad text; v_checks jsonb; v_ex jsonb; v_exids uuid[] := '{}'::uuid[];
        decline constant text := 'A person decides this in Layer 4 (Approve, Approve except or Reject).';
begin
  select * into i from pipeline.layer4_review_items where id = p_item;
  if i.id is null or i.status <> 'pending' then return jsonb_build_object('ok', false, 'rule', 'item_not_pending', 'reason', 'The item is no longer waiting.'); end if;
  if i.field_code = 'entry_matrix_change' then return jsonb_build_object('ok', false, 'rule', 'change_of_admitted_table', 'reason', 'A change to an admitted table stays with a person.', 'next_action', decline); end if;
  if i.field_code <> 'entry_matrix_first_run' or i.entity_type <> 'provider' then return jsonb_build_object('ok', false, 'rule', 'not_this_class', 'reason', 'Not an entry-matrix first read.'); end if;
  if i.claimed_at is not null or i.assigned_to is not null then return jsonb_build_object('ok', false, 'rule', 'claimed_by_person', 'reason', 'A person has taken this item.'); end if;
  if exists (select 1 from pipeline.layer4_decisions d where d.review_item_id = i.id) then return jsonb_build_object('ok', false, 'rule', 'decided', 'reason', 'The item already has a decision.'); end if;
  select * into r from pipeline.entry_matrix_runs where review_item_id = i.id;
  if r.id is null then return jsonb_build_object('ok', false, 'rule', 'no_run', 'reason', 'No read is linked to this item.', 'next_action', decline); end if;
  select * into f from pipeline.entry_matrix_sources where id = r.source_id;
  v_checks := jsonb_build_object('run_id', r.id, 'source_id', f.id, 'source_url', f.url, 'content_hash', r.content_hash, 'evidence_id', f.evidence_id);
  if exists (select 1 from pipeline.manual_locks l where l.entity = 'provider' and l.entity_id = i.entity_id and l.field in ('entry_requirements', 'all')) then
    return jsonb_build_object('ok', false, 'rule', 'manual_lock', 'reason', 'The provider''s entry requirements are locked by a person.', 'next_action', decline, 'checks', v_checks); end if;
  -- protected rejection: a person rejected or returned an earlier read of THIS source (a provider that publishes one page per country keeps its other pages on their merits)
  if exists (select 1 from pipeline.layer4_review_items o where o.entity_id = i.entity_id and o.field_code like 'entry_matrix%' and o.id <> i.id
               and o.status in ('rejected', 'more_evidence', 'returned_layer2', 'returned_layer3')
               and (o.layer2_state->>'entry_matrix_source_id' = f.id::text or o.proposed_value->>'url' = f.url)) then
    return jsonb_build_object('ok', false, 'rule', 'earlier_rejection', 'reason', 'A person rejected or returned an earlier entry-matrix read of this source.', 'next_action', decline, 'checks', v_checks); end if;
  if f.evidence_id is null or not exists (select 1 from pipeline.evidence_artifacts e where e.id = f.evidence_id and e.storage_path is not null) then
    return jsonb_build_object('ok', false, 'rule', 'evidence_missing', 'reason', 'The stored copy of the source is missing.', 'next_action', decline, 'checks', v_checks); end if;
  -- 12 Nov 2026 (D3): a copy a person uploaded is not proven to be what the official address serves; it stays with a person
  if f.read_via is null and exists (select 1 from pipeline.aer_source_attachments a where a.source_id = f.id and a.how = 'pdf_upload' and a.content_hash = f.content_hash) then
    return jsonb_build_object('ok', false, 'rule', 'uploaded_copy', 'reason', 'The stored copy was uploaded by a person, not fetched from the official address.', 'next_action', decline, 'checks', v_checks); end if;
  if r.content_hash is distinct from f.content_hash then
    return jsonb_build_object('ok', false, 'rule', 'stale_copy', 'reason', 'The read is not of the source''s current stored copy.', 'next_action', decline, 'checks', v_checks); end if;
  select p.website into v_web from catalogue.providers p where p.id = i.entity_id;
  v_sh := security.site_host_v1(f.url); v_ph := security.site_host_v1(v_web);
  if v_sh is null or v_ph is null or not (v_sh = v_ph or v_sh like '%.' || v_ph) then
    return jsonb_build_object('ok', false, 'rule', 'source_not_official_host', 'reason', format('The source host %s is not the provider''s own website host %s.', coalesce(v_sh, '?'), coalesce(v_ph, '?')),
                              'next_action', decline, 'checks', v_checks); end if;
  if exists (select 1 from catalogue.providers o where o.id <> i.entity_id and o.lifecycle_status = 'active' and security.site_host_v1(o.website) = v_ph) then
    return jsonb_build_object('ok', false, 'rule', 'host_shared', 'reason', 'Another active provider uses the same website host.', 'next_action', decline, 'checks', v_checks); end if;
  -- 12 Nov 2026 (Platform Admin 22:25, machine Approve except): rows that fail a row rule are held back; the gate is judged on the rows admitted
  if security.pipeline_num_v1('aer.matrix_machine_except_on', 0) >= 1 then
    v_ex := security.aer_matrix_machine_exclusions_v1(r.id);
    v_exids := coalesce(array(select jsonb_array_elements_text(v_ex->'ids')::uuid), '{}'::uuid[]);
  end if;
  g := security.entry_matrix_gate_v1(r.id, v_exids);
  if g is not null and not coalesce((g->>'complete')::boolean, true) then
    return jsonb_build_object('ok', false, 'rule', 'gate_incomplete', 'reason', 'The read cannot be shown complete (D-R3).', 'next_action', decline, 'checks', v_checks || jsonb_build_object('gate', g)); end if;
  if coalesce(r.result->'completeness'->>'status', 'missing') in ('incomplete', 'unparsed')
     or (security.entry_completeness_required_v1(i.entity_id) and coalesce(r.result->'completeness'->>'status', 'missing') <> 'complete') then
    return jsonb_build_object('ok', false, 'rule', 'completeness', 'reason', 'The read has not passed the completeness guard.', 'next_action', decline, 'checks', v_checks); end if;
  select count(*) into v_nm from catalogue.provider_entry_matrix m where m.run_id = r.id and m.status = 'proposed';
  select count(*) into v_nq from catalogue.provider_qualification_requirements q where q.run_id = r.id and q.status = 'proposed';
  -- F-AER.08 (12 Nov 2026, decision 1): a read of an aligned PDF grid stays with a person until aer.grid_machine_admission_on (shadow validation first)
  if coalesce(r.result->>'reader', '') = 'pdf-grid-v1' and security.pipeline_num_v1('aer.grid_machine_admission_on', 0) < 1 then
    return jsonb_build_object('ok', false, 'rule', 'grid_reader_shadow', 'reason', 'A read of an aligned PDF grid stays with a person until its first reads are validated (aer.grid_machine_admission_on).',
                              'next_action', decline, 'checks', v_checks); end if;
  if v_ex is not null and v_nm + v_nq > 0 and v_nm + v_nq - cardinality(v_exids) <= 0 then
    return jsonb_build_object('ok', false, 'rule', 'all_rows_held', 'reason', 'Every proposed row fails a row rule, so nothing can be admitted automatically.', 'next_action', decline,
                              'checks', v_checks || jsonb_build_object('held_back_by_rule', v_ex->'by_rule')); end if;
  if v_nm + v_nq = 0 then return jsonb_build_object('ok', false, 'rule', 'no_rows', 'reason', 'The read proposes no row.', 'next_action', decline, 'checks', v_checks); end if;
  -- every row: confidence, quote, destination level, a published minimum (never inferred)
  select x.why into v_bad from (
    select case when coalesce(m.confidence, 0) < v_conf then 'low_confidence' when length(btrim(coalesce(m.quote, ''))) < v_qmin then 'short_quote'
                when m.study_level_id is null then 'level_unmapped'
                when not ((m.min_value is not null and coalesce(m.grade_scale, 'none') <> 'none') or nullif(btrim(coalesce(m.min_grade, '')), '') is not null) then 'no_minimum'
                when not security.aer_quote_has_value_v1(m.quote, m.min_grade, m.min_value) then 'minimum_not_in_quote' end why
      from catalogue.provider_entry_matrix m where m.run_id = r.id and m.status = 'proposed'
    union all
    select case when q.applicability = 'unresolved' then 'applicability_unresolved' when coalesce(q.confidence, 0) < v_conf then 'low_confidence'
                when length(btrim(coalesce(q.quote, ''))) < v_qmin then 'short_quote' when q.study_level_id is null then 'level_unmapped'
                when not ((q.min_value is not null and coalesce(q.grade_scale, 'none') <> 'none') or nullif(btrim(coalesce(q.min_grade, '')), '') is not null) then 'no_minimum'
                when not security.aer_quote_has_value_v1(q.quote, q.min_grade, q.min_value) then 'minimum_not_in_quote' end
      from catalogue.provider_qualification_requirements q where q.run_id = r.id and q.status = 'proposed') x
   where x.why is not null limit 1;
  if v_bad is not null and v_ex is null then return jsonb_build_object('ok', false, 'rule', 'row_' || v_bad, 'reason', 'At least one proposed row fails ' || v_bad || '.', 'next_action', decline,
                                                       'checks', v_checks || jsonb_build_object('rows', v_nm, 'qualification_rows', v_nq)); end if;
  if v_ex is null and (exists (select 1 from catalogue.provider_entry_matrix m where m.run_id = r.id and m.status = 'proposed' group by m.row_hash having count(*) > 1)
     or exists (select 1 from catalogue.provider_qualification_requirements q where q.run_id = r.id and q.status = 'proposed' group by q.qualification_code, q.level_label having count(*) > 1)) then
    return jsonb_build_object('ok', false, 'rule', 'duplicate_identity', 'reason', 'Two proposed rows share one identity.', 'next_action', decline, 'checks', v_checks); end if;
  if v_ex is null and (exists (select 1 from catalogue.provider_entry_matrix p join catalogue.provider_entry_matrix a on a.row_hash = p.row_hash and a.status = 'active' and a.id <> p.id
              where p.run_id = r.id and p.status = 'proposed' and a.source_id is distinct from r.source_id)
     or exists (select 1 from catalogue.provider_qualification_requirements p join catalogue.provider_qualification_requirements a
                  on a.provider_id = p.provider_id and a.qualification_code = p.qualification_code and a.level_label is not distinct from p.level_label and a.status = 'active'
              where p.run_id = r.id and p.status = 'proposed' and a.source_id is distinct from r.source_id)) then
    return jsonb_build_object('ok', false, 'rule', 'conflicting_active', 'reason', 'A proposed row has the identity of an active row from another source.', 'next_action', decline, 'checks', v_checks); end if;
  v_checks := v_checks || jsonb_build_object('rows', v_nm, 'qualification_rows', v_nq, 'host', v_sh, 'min_confidence', v_conf)
              || case when v_ex is not null then jsonb_build_object('exclude_row_ids', coalesce(v_ex->'ids', '[]'::jsonb), 'held_back', cardinality(v_exids),
                                                                    'held_back_by_rule', coalesce(v_ex->'by_rule', '{}'::jsonb)) else '{}'::jsonb end;
  if abs(hashtext(i.id::text)) % 100 < v_pct then  -- fixed: a per cent sample
    return jsonb_build_object('ok', false, 'audit', true, 'rule', 'audit_sample', 'reason', 'Chosen for the audit sample: a person checks this passing item.', 'next_action', decline, 'checks', v_checks); end if;
  return jsonb_build_object('ok', true, 'rule', case when cardinality(v_exids) > 0 then 'aer-matrix-machine-v1-except' else 'aer-matrix-machine-v1' end, 'checks', v_checks);
end $$;


ALTER FUNCTION "security"."aer_matrix_machine_check_v1"("p_item" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_matrix_machine_check_v1"("p_item" "uuid") IS 'CF-247 F-AER.04 (decision D1): rule aer-matrix-machine-v1 for one entry-matrix Layer 4 item: ok only for a never-decided first read of the provider''s own official source whose every row is source-proved with a published minimum, mapped level and explicit applicability; otherwise the reason it stays with a person. Read only.';



CREATE OR REPLACE FUNCTION "security"."aer_matrix_machine_effective_v1"() RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- 2 only with mode 2, a passing validation from the last 7 days, and neither suspension switch on; otherwise the mode, at most 1
  select case when security.pipeline_num_v1('aer.matrix_machine_mode', 0) >= 2
               and exists (select 1 from pipeline.aer_matrix_machine_validations x where x.passed and x.validated_at > now() - interval '7 days')  -- fixed: a validation is valid for 7 days
               and security.pipeline_num_v1('aer.machine_suspended', 0) < 1 then 2
              else least(security.pipeline_num_v1('aer.matrix_machine_mode', 0)::int, 1) end
$$;


ALTER FUNCTION "security"."aer_matrix_machine_effective_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_matrix_machine_exclusions_v1"("p_run" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- the proposed rows of one read that fail a row rule of the machine check, each with its rule (the same rules, in the same order)
  with cfg as materialized (select security.pipeline_num_v1('aer.matrix_machine_min_confidence', 0.9) conf, security.pipeline_num_v1('aer.machine_min_quote_chars', 8)::int qmin,
                                   security.pipeline_num_v1('aer.course_link_on', 1) >= 1 link_on),
  run as materialized (select r.id, r.source_id from pipeline.entry_matrix_runs r where r.id = p_run),
  m as materialized (select m.* from catalogue.provider_entry_matrix m join run on m.run_id = run.id where m.status = 'proposed'),
  q as materialized (select q.* from catalogue.provider_qualification_requirements q join run on q.run_id = run.id where q.status = 'proposed'),
  why as (
    select m.id, case when coalesce(m.confidence, 0) < cfg.conf then 'low_confidence' when length(btrim(coalesce(m.quote, ''))) < cfg.qmin then 'short_quote'
                      when m.study_level_id is null then 'level_unmapped'
                      when not ((m.min_value is not null and coalesce(m.grade_scale, 'none') <> 'none') or nullif(btrim(coalesce(m.min_grade, '')), '') is not null) then 'no_minimum'
                      when not security.aer_quote_has_value_v1(m.quote, m.min_grade, m.min_value) then 'minimum_not_in_quote'
                      when cfg.link_on and m.course_label is not null and m.course_id is null then 'course_unlinked'
                      when exists (select 1 from m m2 where m2.row_hash = m.row_hash and m2.id <> m.id) then 'duplicate_identity'
                      when exists (select 1 from catalogue.provider_entry_matrix a, run where a.row_hash = m.row_hash and a.status = 'active' and a.id <> m.id
                                      and a.source_id is distinct from run.source_id) then 'conflicting_active' end w
      from m, cfg
    union all
    select q.id, case when q.applicability = 'unresolved' then 'applicability_unresolved' when coalesce(q.confidence, 0) < cfg.conf then 'low_confidence'
                      when length(btrim(coalesce(q.quote, ''))) < cfg.qmin then 'short_quote' when q.study_level_id is null then 'level_unmapped'
                      when not ((q.min_value is not null and coalesce(q.grade_scale, 'none') <> 'none') or nullif(btrim(coalesce(q.min_grade, '')), '') is not null) then 'no_minimum'
                      when not security.aer_quote_has_value_v1(q.quote, q.min_grade, q.min_value) then 'minimum_not_in_quote'
                      when cfg.link_on and q.course_label is not null and q.course_id is null then 'course_unlinked'
                      when exists (select 1 from q q2 where q2.qualification_code = q.qualification_code and q2.level_label is not distinct from q.level_label
                                      and q2.course_label is not distinct from q.course_label and q2.id <> q.id) then 'duplicate_identity'
                      when exists (select 1 from catalogue.provider_qualification_requirements a, run where a.provider_id = q.provider_id and a.qualification_code = q.qualification_code
                                      and a.level_label is not distinct from q.level_label and a.course_label is not distinct from q.course_label and a.status = 'active'
                                      and a.source_id is distinct from run.source_id) then 'conflicting_active' end
      from q, cfg)
  select jsonb_build_object('ids', coalesce(jsonb_agg(why.id order by why.id) filter (where why.w is not null), '[]'::jsonb),
                            'by_rule', coalesce((select jsonb_object_agg(z.w, z.n) from (select w, count(*) n from why where w is not null group by w) z), '{}'::jsonb))
    from why
$$;


ALTER FUNCTION "security"."aer_matrix_machine_exclusions_v1"("p_run" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_matrix_machine_exclusions_v1"("p_run" "uuid") IS 'CF-247 machine Approve except (Platform Admin 12 Nov 2026 22:25): the proposed rows of a read that fail a row rule, held back while the rest are admitted.';



CREATE OR REPLACE FUNCTION "security"."aer_matrix_machine_run_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_mode int; v_batch int; v_cap int; v_used int; v_t0 timestamptz := clock_timestamp(); r record; v jsonb; v_n int := 0;
        v_out jsonb := '{}'::jsonb; v_err int := 0;
begin
  -- settings are read inside the block, so an unreadable value is returned as an error like any other, never raised into the calling course run
  v_mode := security.aer_matrix_machine_effective_v1();
  v_batch := security.pipeline_num_v1('batch.aer_matrix_machine', 20)::int;
  v_cap := security.pipeline_num_v1('aer.matrix_machine_daily_max', 40)::int;
  if v_mode < 1 then return jsonb_build_object('mode', 0); end if;
  select count(*) into v_used from pipeline.aer_matrix_machine_admissions where mode = 'admit' and outcome = 'admitted' and created_at > now() - interval '24 hours';  -- fixed: the cap counts the last 24 hours
  for r in select i.id from pipeline.layer4_review_items i
             left join pipeline.aer_matrix_machine_admissions s on s.review_item_id = i.id and s.mode = 'shadow'
            where i.status = 'pending' and i.field_code in ('entry_matrix_first_run', 'entry_matrix_change')
              and (v_mode >= 2 or s.id is null or s.updated_at < now() - interval '6 hours')  -- fixed: an unchanged item is looked at again after 6 hours in shadow
              and not (v_mode >= 2 and exists (select 1 from pipeline.aer_matrix_machine_admissions a where a.review_item_id = i.id and a.mode = 'admit' and a.created_at > now() - interval '6 hours'))
            order by (s.id is null) desc, i.created_at
            limit v_batch loop
    exit when clock_timestamp() - v_t0 > interval '40 seconds';  -- fixed: a run stays inside the job's time
    exit when v_mode >= 2 and v_used >= v_cap;
    begin
      v := security.aer_matrix_machine_admit_v1(r.id, 'run');
      v_n := v_n + 1;
      v_out := jsonb_set(v_out, array[coalesce(v->>'outcome', v->>'rule', 'unknown')], to_jsonb(coalesce((v_out->>coalesce(v->>'outcome', v->>'rule', 'unknown'))::int, 0) + 1));
      if v->>'outcome' = 'admitted' then v_used := v_used + 1; end if;
    exception when others then v_err := v_err + 1;
    end;
  end loop;
  return jsonb_build_object('mode', v_mode, 'checked', v_n, 'outcomes', v_out, 'errors', v_err, 'admitted_24h', v_used, 'cap', v_cap);
exception when others then
  return jsonb_build_object('error', left(sqlerrm, 300));  -- isolated: the matrix class never breaks the course run that calls it
end $$;


ALTER FUNCTION "security"."aer_matrix_machine_run_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_matrix_machine_run_v1"() IS 'CF-247 F-AER.04 (decision D1): one step of rule aer-matrix-machine-v1 over the waiting entry-matrix items (batch.aer_matrix_machine a run, aer.matrix_machine_daily_max a day), called by security.aer_machine_run_v1 (job aer-machine-admission); errors are returned, never raised.';



CREATE OR REPLACE FUNCTION "security"."aer_matrix_machine_validate_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_min int := security.pipeline_num_v1('aer.matrix_machine_min_shadow', 20)::int; v_conf numeric := security.pipeline_num_v1('aer.matrix_machine_min_confidence', 0.9);
        v_qmin int := security.pipeline_num_v1('aer.machine_min_quote_chars', 8)::int; v_n int; v_would int; v_regress int := 0; r record; v_c jsonb; v_hist jsonb; v_pass boolean; v_detail jsonb;
begin
  select count(*), count(*) filter (where outcome = 'would_admit') into v_n, v_would from pipeline.aer_matrix_machine_admissions where mode = 'shadow';
  -- independent re-check of every current would-admit item
  for r in select m.review_item_id from pipeline.aer_matrix_machine_admissions m join pipeline.layer4_review_items i on i.id = m.review_item_id and i.status = 'pending'
            where m.mode = 'shadow' and m.outcome = 'would_admit' loop
    v_c := security.aer_matrix_machine_check_v1(r.review_item_id);
    if not coalesce((v_c->>'ok')::boolean, false) and coalesce(v_c->>'rule', '') not in ('audit_sample', 'claimed_by_person', 'item_not_pending') then v_regress := v_regress + 1; end if;
  end loop;
  -- agreement with past human matrix decisions: would the row rules have admitted the read a person decided, and did the person approve it unchanged?
  with h as (select i.id, d.action, emr.id run_id from pipeline.layer4_decisions d join pipeline.layer4_review_items i on i.id = d.review_item_id
              join pipeline.entry_matrix_runs emr on emr.review_item_id = i.id
             where i.field_code = 'entry_matrix_first_run' and d.actor_id is distinct from security.system_actor_id()),
  x as (select h.id, h.action,
               not exists (select 1 from catalogue.provider_entry_matrix m where m.run_id = h.run_id
                             and (coalesce(m.confidence, 0) < v_conf or length(btrim(coalesce(m.quote, ''))) < v_qmin or m.study_level_id is null
                                  or not ((m.min_value is not null and coalesce(m.grade_scale, 'none') <> 'none') or nullif(btrim(coalesce(m.min_grade, '')), '') is not null)
                                  or not security.aer_quote_has_value_v1(m.quote, m.min_grade, m.min_value)))
               and exists (select 1 from catalogue.provider_entry_matrix m where m.run_id = h.run_id) would
          from h)
  select jsonb_build_object('human_decisions', count(*), 'rule_would_admit', count(*) filter (where would),
           'rule_would_admit_and_human_approved', count(*) filter (where would and action = 'approve'),
           'rule_would_admit_but_human_edited_or_refused', count(*) filter (where would and action <> 'approve'),
           'disagreements', coalesce(jsonb_agg(jsonb_build_object('item', id, 'action', action)) filter (where would and action <> 'approve'), '[]'::jsonb)) into v_hist from x;
  v_pass := v_n >= v_min and v_regress = 0
            and coalesce((v_hist->>'rule_would_admit_but_human_edited_or_refused')::int, 1) <= greatest(0, ((v_hist->>'rule_would_admit')::int) / 50);  -- fixed: at most 2% disagreement, none on a small history
  v_detail := jsonb_build_object('shadow_results', v_n, 'shadow_would_admit', v_would, 'shadow_min', v_min, 'regressions_on_recheck', v_regress, 'history', v_hist);
  insert into pipeline.aer_matrix_machine_validations(passed, detail, validated_by) values (v_pass, v_detail, auth.uid());
  return v_detail || jsonb_build_object('passed', v_pass, 'note', 'A pass does not switch admission on. A person (or the Integration Controller under the Platform Admin decision) sets aer.matrix_machine_mode to 2 with a reason.');
end $$;


ALTER FUNCTION "security"."aer_matrix_machine_validate_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_matrix_machine_validate_v1"() IS 'CF-247 F-AER.04 (decision D1): validates rule aer-matrix-machine-v1 (enough shadow results, every would-admit item re-checked, agreement with past human matrix decisions: at most 2%, none on a history under 50 rule admits) and records it. A pass switches nothing on.';



CREATE OR REPLACE FUNCTION "security"."aer_matrix_machine_withdraw_v1"("p_item" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a pipeline.aer_matrix_machine_admissions%rowtype; v_off int; v_back int; v_qoff int; v_qback int;
begin
  if length(btrim(coalesce(p_reason, ''))) < 5 then raise exception 'reason required'; end if;
  select * into a from pipeline.aer_matrix_machine_admissions where review_item_id = p_item and mode = 'admit' and outcome = 'admitted' and withdrawn_at is null order by id desc limit 1 for update;
  if a.id is null then return jsonb_build_object('ok', false, 'why', 'no machine admission to withdraw'); end if;
  update catalogue.provider_entry_matrix set status = 'inactive', status_reason = 'machine admission withdrawn: ' || p_reason, updated_at = now() where run_id = a.run_id and status = 'active';
  get diagnostics v_off = row_count;
  update catalogue.provider_entry_matrix set status = 'active', status_reason = null, updated_at = now() where status = 'superseded' and status_reason = 'replaced by run ' || a.run_id;
  get diagnostics v_back = row_count;
  update catalogue.provider_qualification_requirements set status = 'inactive', status_reason = 'machine admission withdrawn: ' || p_reason, updated_at = now() where run_id = a.run_id and status = 'active';
  get diagnostics v_qoff = row_count;
  update catalogue.provider_qualification_requirements set status = 'active', status_reason = null, updated_at = now() where status = 'superseded' and status_reason = 'replaced by run ' || a.run_id;
  get diagnostics v_qback = row_count;
  update pipeline.aer_matrix_machine_admissions set withdrawn_at = now(), withdrawn_reason = p_reason, updated_at = now() where id = a.id;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('layer4', 'aer_machine_withdraw', 'pipeline.layer4_review_items', jsonb_build_object('review_item_id', p_item, 'rule', 'aer-matrix-machine-v1', 'reason', p_reason,
          'rows_withdrawn', v_off + v_qoff, 'rows_restored', v_back + v_qback), auth.uid());
  insert into pipeline.search_refresh_signals(entity_type, entity_id, review_decision_id, reason, change_control_ref)
  values ('provider', a.provider_id, a.decision_id, 'Machine admission withdrawn: ' || p_reason, 'CF-247 F-AER.04');
  return jsonb_build_object('ok', true, 'rows_withdrawn', v_off + v_qoff, 'rows_restored', v_back + v_qback);
end $$;


ALTER FUNCTION "security"."aer_matrix_machine_withdraw_v1"("p_item" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_matrix_machine_withdraw_v1"("p_item" "uuid", "p_reason" "text") IS 'CF-247 F-AER.04 (decision D1): reverses an aer-matrix-machine-v1 admission: the read''s active rows become inactive, rows it replaced become active again, the ledger and a control event record it.';



CREATE OR REPLACE FUNCTION "security"."aer_matrix_rank_repair_v1"("p_preview" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank text := (select string_agg('(' || w || ')', '|') from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'entry.matrix_rank_words'), '[]'::jsonb)) w where btrim(w) <> '');
        v_score text := (select string_agg('(' || w || ')', '|') from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'entry.matrix_score_words'), '[]'::jsonb)) w where btrim(w) <> '');
        r record; v_n int := 0; v_runs uuid[] := '{}';
begin
  if v_rank is null or v_score is null then return jsonb_build_object('rows', 0, 'runs', 0); end if;
  for r in select m.id, m.run_id, m.min_value, m.min_grade, m.grade_scale, m.benchmark_band, m.quote, (regexp_match(m.benchmark_band, '[0-9]+(?:\.[0-9]+)?'))[1] sc
             from catalogue.provider_entry_matrix m
            where m.status = 'proposed' and m.grade_scale = 'rank' and m.min_value is not null and m.benchmark_band is not null
              and m.run_id in (select (i.proposed_value->>'run_id')::uuid from pipeline.layer4_review_items i where i.status = 'pending' and i.field_code like 'entry_matrix%')
              and coalesce(m.quote, '') ~* v_rank and coalesce(m.quote, '') ~* v_score
              and (regexp_match(m.benchmark_band, '[0-9]+(?:\.[0-9]+)?'))[1] is not null
              and strpos(coalesce(m.quote, ''), (regexp_match(m.benchmark_band, '[0-9]+(?:\.[0-9]+)?'))[1]) > 0
              and strpos(coalesce(m.quote, ''), trim_scale(m.min_value)::text) > 0 loop
    v_n := v_n + 1; v_runs := v_runs || r.run_id;
    if not p_preview then
      insert into pipeline.aer_row_repairs(table_name, row_id, run_id, rule, before, after)
      values ('catalogue.provider_entry_matrix', r.id, r.run_id, 'rank_swapped_with_indicative_score',
              jsonb_build_object('min_value', r.min_value, 'min_grade', r.min_grade, 'grade_scale', r.grade_scale, 'benchmark_band', r.benchmark_band),
              jsonb_build_object('min_value', r.sc::numeric, 'min_grade', r.sc, 'grade_scale', 'points', 'benchmark_band', trim_scale(r.min_value)::text));
      update catalogue.provider_entry_matrix set min_value = r.sc::numeric, min_grade = r.sc, grade_scale = 'points', benchmark_band = trim_scale(r.min_value)::text, updated_at = now()
       where id = r.id and status = 'proposed';
    end if;
  end loop;
  return jsonb_build_object('rows', v_n, 'runs', (select count(distinct x) from unnest(v_runs) x), 'preview', p_preview);
end $$;


ALTER FUNCTION "security"."aer_matrix_rank_repair_v1"("p_preview" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_matrix_rank_repair_v1"("p_preview" boolean) IS 'CF-247 AER technical holds (7 Nov 2026): puts a provider rank stored as the qualification minimum (and the printed indicative score stored as the band) the right way round on matrix rows still waiting for a person; the original is kept in pipeline.aer_row_repairs. Never touches an admitted row.';



CREATE OR REPLACE FUNCTION "security"."aer_matrix_route_activate_v1"("p_provider" "uuid", "p_expected" integer, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_max int := security.pipeline_num_v1('aer.matrix_route_activate_max', 5)::int; v_ids uuid[]; v_n int;
begin
  if current_user <> 'postgres' then raise exception 'activating mapped course pages is a Platform Admin step'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;
  if not security.ai_use_allowed_v1('entry_matrix') then raise exception 'entry matrix AI use is stopped (daily guard or credit floor); nothing changed'; end if;
  select array_agg(x.id) into v_ids from (select r.id from pipeline.aer_matrix_route r where r.provider_id = p_provider and r.state = 'held' order by r.created_at, r.id limit v_max) x;
  v_n := coalesce(cardinality(v_ids), 0);
  if v_n <> p_expected then raise exception 'count guard: % held pages would be activated (cap %), expected %; nothing changed', v_n, v_max, p_expected; end if;
  update pipeline.entry_matrix_sources s set status = 'read', error = null, read_at = now(), updated_at = now()
    from pipeline.aer_matrix_route r where r.id = any (v_ids) and s.id = r.source_id and s.status = 'inactive';
  update pipeline.aer_matrix_route r set state = 'activated', activated_at = now() where r.id = any (v_ids);
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('entry_matrix', 'route_activate', 'provider: ' || p_provider, jsonb_build_object('activated', v_n, 'cap', v_max, 'reason', btrim(p_reason), 'route_ids', to_jsonb(v_ids)), null);
  return jsonb_build_object('ok', true, 'activated', v_n);
end $$;


ALTER FUNCTION "security"."aer_matrix_route_activate_v1"("p_provider" "uuid", "p_expected" integer, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_matrix_route_activate_v1"("p_provider" "uuid", "p_expected" integer, "p_reason" "text") IS 'CF-247 AER (8 Nov 2026): Platform Admin only. Sets at most aer.matrix_route_activate_max held mapped pages to status read so the existing entry matrix reader reads them (AI, pinned model, daily guard); results go to Layer 4 as proposed runs.';



CREATE OR REPLACE FUNCTION "security"."aer_matrix_route_attach_v1"("p_provider" "uuid", "p_expected" integer, "p_md5" "text", "p_reason" "text", "p_include_items" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int; v_md5 text; v_added int := 0; r record; v_src uuid;
begin
  if current_user <> 'postgres' then raise exception 'mapping a course page as a matrix source is a Platform Admin step'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;
  select count(*), md5(string_agg(c.item_id::text || ':' || c.content_hash, ',' order by c.item_id)) into v_n, v_md5
    from security.aer_matrix_route_candidates_v1(p_provider, p_include_items) c;
  if v_n <> p_expected or v_md5 is distinct from p_md5 then
    raise exception 'count and md5 guard: % candidates (md5 %), expected % (md5 %); nothing changed', v_n, v_md5, p_expected, p_md5;
  end if;
  for r in select * from security.aer_matrix_route_candidates_v1(p_provider, p_include_items) order by item_id loop
    insert into pipeline.entry_matrix_sources(provider_id, url, title, rank, found_via, status, read_via, evidence_id, content_hash, read_at, error)
    values (p_provider, r.url, left(r.course_title, 200), 1, 'manual', 'inactive', 'stored', r.evidence_id, r.content_hash, now(),
            'held: course page mapped as a matrix source (aer_matrix_route), waiting for a Platform Admin activation')
    on conflict (provider_id, url) do nothing
    returning id into v_src;
    if v_src is null then continue; end if;
    insert into pipeline.aer_matrix_route(provider_id, course_id, old_item_id, source_id, url, evidence_id, content_hash, rows_cut, reason)
    values (p_provider, r.course_id, r.item_id, v_src, r.url, r.evidence_id, r.content_hash, r.rows_cut, btrim(p_reason));
    v_added := v_added + 1;
  end loop;
  if v_added <> p_expected then raise exception 'count guard after change: % mapped, % expected', v_added, p_expected; end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('entry_matrix', 'route_attach', 'provider: ' || p_provider,
          jsonb_build_object('mapped', v_added, 'expected', p_expected, 'md5', v_md5, 'reason', btrim(p_reason), 'status', 'inactive (held)', 'fetch', false, 'ai', false,
                             'locked_included', coalesce(cardinality(p_include_items), 0), 'old_items_changed', 0), null);
  return jsonb_build_object('ok', true, 'mapped', v_added, 'md5', v_md5);
end $$;


ALTER FUNCTION "security"."aer_matrix_route_attach_v1"("p_provider" "uuid", "p_expected" integer, "p_md5" "text", "p_reason" "text", "p_include_items" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_matrix_route_attach_v1"("p_provider" "uuid", "p_expected" integer, "p_md5" "text", "p_reason" "text", "p_include_items" "uuid"[]) IS 'CF-247 AER (8 Nov 2026): Platform Admin only, count and md5 guarded. Maps each candidate course page as a matrix source in status inactive (read_via stored, the stored copy) with a held route row and one audit event. No fetch, no AI, no change to the waiting items.';



CREATE OR REPLACE FUNCTION "security"."aer_matrix_route_candidates_v1"("p_provider" "uuid", "p_include_items" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS TABLE("item_id" "uuid", "course_id" "uuid", "course_title" "text", "url" "text", "evidence_id" "uuid", "content_hash" "text", "rows_cut" integer, "locked" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select i.id, i.entity_id, k.canonical_title, a.source_url, a.id, a.content_hash, x.cut::int,
         exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = i.entity_id and l.field in ('official_url', 'course_url'))
    from pipeline.layer4_review_items i
    join catalogue.courses k on k.id = i.entity_id and k.provider_id = p_provider
    join pipeline.evidence_artifacts a on a.id = i.evidence_id and a.storage_path is not null and a.content_hash is not null and a.mime_type like 'text/html%'
         and a.source_url ~ '^https?://'
    cross join lateral (select count(*) cut from jsonb_array_elements(coalesce(i.proposed_value->'dropped', '[]'::jsonb)) d where d->>'reason' = 'over_row_limit') x
   where i.status = 'pending' and i.field_code = 'course_entry_first_read' and i.entity_type = 'course'
     and x.cut >= security.pipeline_num_v1('aer.row_limit_matrix_rows', 30)
     and not exists (select 1 from pipeline.aer_matrix_route r where r.old_item_id = i.id)
     and not exists (select 1 from pipeline.entry_matrix_sources s where s.provider_id = p_provider and s.url = a.source_url)
     and (i.id = any (coalesce(p_include_items, '{}'::uuid[]))
          or not exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = i.entity_id and l.field in ('official_url', 'course_url')))
$$;


ALTER FUNCTION "security"."aer_matrix_route_candidates_v1"("p_provider" "uuid", "p_include_items" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_matrix_route_candidates_v1"("p_provider" "uuid", "p_include_items" "uuid"[]) IS 'CF-247 AER (8 Nov 2026): the waiting course reads of a provider cut at aer.row_limit_matrix_rows or more rows with a stored HTML copy, nothing mapped yet; courses with a hand lock on the page address only when named in p_include_items. Read only.';



CREATE OR REPLACE FUNCTION "security"."aer_matrix_route_stamp_tg"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.aer_matrix_route%rowtype;
begin
  if new.source_id is null or new.course_id is not null then return new; end if;
  select * into r from pipeline.aer_matrix_route where source_id = new.source_id and state <> 'closed';
  if r.id is null then return new; end if;
  new.course_id := r.course_id;
  new.matrix_kind := 'course_minimum';
  new.course_label := coalesce(new.course_label, (select k.canonical_title from catalogue.courses k where k.id = r.course_id));
  return new;
end $$;


ALTER FUNCTION "security"."aer_matrix_route_stamp_tg"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_matrix_route_stamp_tg"() IS 'CF-247 AER (8 Nov 2026): a matrix row written from a mapped course page (pipeline.aer_matrix_route) is that course''s row: course_id, matrix_kind course_minimum, course_label. Sorts before the identity trigger so the row hash includes the course.';



CREATE OR REPLACE FUNCTION "security"."aer_measures_v1"() RETURNS TABLE("country" "text", "eligible" integer, "discovery_n" integer, "discovered_any" integer, "extraction_n" integer, "admission_n" integer, "active_any" integer, "consumer_n" integer, "detail" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with el as (select * from security.aer_eligible_v1()),
  pf as (
    select e.provider_id, e.country,
           exists (select 1 from pipeline.entry_matrix_sources s where s.provider_id = e.provider_id) disc_any,
           exists (select 1 from pipeline.entry_matrix_sources s where s.provider_id = e.provider_id and s.status = 'read') disc,
           exists (select 1 from pipeline.aer_gap_findings f join pipeline.aer_gap_root_causes rc on rc.code = f.root_cause
                    where f.provider_id = e.provider_id and f.state <> 'resolved' and rc.measure = 'extraction') ext_gap,
           (exists (select 1 from catalogue.provider_entry_matrix m where m.provider_id = e.provider_id and m.status = 'active')
            or exists (select 1 from catalogue.course_entry_requirements x join catalogue.courses c on c.id = x.course_id where c.provider_id = e.provider_id and x.status = 'active')) act,
           (exists (select 1 from catalogue.provider_entry_matrix m where m.provider_id = e.provider_id and m.status = 'proposed')
            or exists (select 1 from catalogue.course_entry_requirements x join catalogue.courses c on c.id = x.course_id where c.provider_id = e.provider_id and x.status = 'proposed')) prop,
           exists (select 1 from pipeline.aer_course_outcomes o where o.provider_id = e.provider_id and o.outcome in ('admitted_course', 'admitted_provider')) cons,
           exists (select 1 from pipeline.aer_gap_findings f where f.provider_id = e.provider_id and f.state <> 'resolved' and f.severity = 'P0') p0
      from el e),
  g as (select coalesce(c, 'ALL') country, count(*) eligible,
               count(*) filter (where disc) discovery_n, count(*) filter (where disc_any) discovered_any,
               count(*) filter (where disc and not ext_gap) extraction_n,
               count(*) filter (where act and not prop) admission_n, count(*) filter (where act) active_any,
               count(*) filter (where cons and not p0) consumer_n
          from (select pf.*, pf.country c from pf) x group by grouping sets ((c), ()))
  select g.country, g.eligible::int, g.discovery_n::int, g.discovered_any::int, g.extraction_n::int, g.admission_n::int, g.active_any::int, g.consumer_n::int,
         jsonb_build_object(
           'countries_published', (select count(distinct m.country_code) from catalogue.provider_entry_matrix m join el on el.provider_id = m.provider_id
                                    where m.status = 'active' and (g.country = 'ALL' or el.country = g.country)),
           'qualifications_active', (select count(distinct lower(m.qualification_name)) from catalogue.provider_entry_matrix m join el on el.provider_id = m.provider_id
                                      where m.status = 'active' and (g.country = 'ALL' or el.country = g.country)),
           'matrix_rows', (select jsonb_build_object('active', count(*) filter (where m.status = 'active'), 'proposed', count(*) filter (where m.status = 'proposed'))
                             from catalogue.provider_entry_matrix m join el on el.provider_id = m.provider_id where g.country = 'ALL' or el.country = g.country),
           'postgraduate', (select jsonb_build_object('active_rows', count(*) filter (where x.status = 'active'), 'proposed_rows', count(*) filter (where x.status = 'proposed'),
                                     'courses_active', count(distinct x.course_id) filter (where x.status = 'active'))
                              from catalogue.course_entry_requirements x join catalogue.courses c on c.id = x.course_id join ref.study_levels l on l.id = c.study_level_id
                              join el on el.provider_id = c.provider_id
                             where l.short_code in (select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'aer.postgraduate_levels'), '[]'::jsonb)))
                               and (g.country = 'ALL' or el.country = g.country)),
           'layer4_pending', (select coalesce(jsonb_object_agg(z.field_code, z.n), '{}'::jsonb) from (select li.field_code, count(*) n from pipeline.layer4_review_items li
                                where li.status = 'pending' and li.field_code in ('course_entry_first_read', 'entry_matrix_first_run', 'entry_matrix_change') group by 1) z),
           'sources', (select jsonb_build_object('total', count(*), 'read', count(*) filter (where s.status = 'read'), 'failed', count(*) filter (where s.status = 'failed'),
                                                 'last_read', max(s.read_at))
                         from pipeline.entry_matrix_sources s join el on el.provider_id = s.provider_id where g.country = 'ALL' or el.country = g.country),
           'definitions', jsonb_build_object(
             'discovery', 'eligible providers with an official AER source read', 'extraction', 'of those, providers with no open extraction finding',
             'admission', 'eligible providers with active requirements and none waiting for Layer 4', 'consumer', 'eligible providers with a course that resolves to an admitted requirement and no open P0'))
    from g
$$;


ALTER FUNCTION "security"."aer_measures_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_measures_v1"() IS 'CF-247 AER Phase B (mandate §13): the four AER measures over the eligible providers, by country and in all, with their sub-figures. Read-only.';



CREATE OR REPLACE FUNCTION "security"."aer_no_source_route_v1"() RETURNS TABLE("provider_id" "uuid", "route" "text", "reason" "text", "next_action" "text", "parked" boolean, "courses_waiting" integer, "best_url" "text", "best_score" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with m as (select greatest(security.pipeline_num_v1('central.min_suggest_score', 4), 3) v),  -- fixed: the worker never suggests a page that scores under 3
  np as (select e.provider_id, security.site_host_v1(p.website) ph
           from security.aer_eligible_v1() e join catalogue.providers p on p.id = e.provider_id
          where not exists (select 1 from pipeline.entry_matrix_sources s where s.provider_id = e.provider_id)),
  -- only links that can score at all are scored (every page rule needs one of these words)
  lk as materialized (
    select u.provider_id, u.url, u.title from pipeline.coverage_provider_urls u join np on np.provider_id = u.provider_id
     where lower(u.url || ' ' || coalesce(u.title, '')) ~ 'equivalen|requirement|qualification|admission|entry'
    union all
    select l.provider_id, l.url, l.anchor_text from pipeline.provider_discovery_links l join np on np.provider_id = l.provider_id
     where lower(l.url || ' ' || coalesce(l.anchor_text, '')) ~ 'equivalen|requirement|qualification|admission|entry'),
  sc as materialized (select lk.provider_id, lk.url, security.entry_source_score_v1(lk.url, lk.title) score, security.site_host_v1(lk.url) uh from lk),
  best as (select distinct on (sc.provider_id) sc.provider_id, sc.url, sc.score
             from sc join np on np.provider_id = sc.provider_id
            where sc.score is not null and (sc.uh = np.ph or right(sc.uh, length(np.ph) + 1) = '.' || np.ph)
            order by sc.provider_id, sc.score desc, length(sc.url), sc.url),
  crs as (select c.provider_id, count(*)::int n from security.aer_schedule_courses_v1(100000, true) c group by 1),  -- fixed: every course the scheduled reading could read, not a page of them
  bnd as (select c.provider_id, g.identity_basis, count(*) n
            from catalogue.courses c join pipeline.coverage_course_pages g on g.course_id = c.id and g.status = 'bound'
            join pipeline.evidence_artifacts a on a.id = g.evidence_id and a.storage_path is not null
           where c.lifecycle_status = 'active' and c.provider_id in (select np.provider_id from np) group by 1, 2),
  bid as (select b.provider_id, sum(b.n)::int n_bound,
                 coalesce(sum(b.n) filter (where not security.coverage_identity_allowed(b.provider_id, b.identity_basis, 'entry_requirements')), 0)::int n_unconfirmed
            from bnd b group by 1),
  sh as (select np.provider_id, exists (select 1 from catalogue.providers o where o.id <> np.provider_id and o.lifecycle_status = 'active' and np.ph is not null and security.site_host_v1(o.website) = np.ph) shared from np),
  x as (select np.provider_id, b.url, b.score, m.v min_score, coalesce(crs.n, 0) courses, coalesce(bid.n_unconfirmed, 0) unconfirmed, coalesce(sh.shared, false) shared,
               case when b.score >= m.v and coalesce(sh.shared, false) then 'source_page_host_shared'
                    when b.score >= m.v then 'source_page_stored'
                    when coalesce(crs.n, 0) > 0 then 'course_pages_waiting'
                    when coalesce(bid.n_unconfirmed, 0) > 0 then 'course_pages_unconfirmed'
                    when b.score is not null then 'weak_page_only'
                    else 'nothing_stored' end route
          from np cross join m left join best b on b.provider_id = np.provider_id left join crs on crs.provider_id = np.provider_id
          left join bid on bid.provider_id = np.provider_id left join sh on sh.provider_id = np.provider_id)
  select x.provider_id, x.route,
         case x.route
           when 'source_page_stored' then 'A stored link on the provider''s own website scores ' || x.score || ' as its international entry-requirements page: ' || x.url
           when 'source_page_host_shared' then 'A stored entry-requirements page exists, but its website is also used by another active provider, so it is not attached by itself: ' || x.url
           when 'course_pages_waiting' then x.courses || ' course pages are stored and matched to their course; the entry requirements are read from them, one course at a time.'
           when 'course_pages_unconfirmed' then x.unconfirmed || ' course pages are stored but matched to their course by title only, which is not admitted for entry requirements.'
           when 'weak_page_only' then 'Only a general entry-requirements page is stored (score ' || x.score || ', under the ' || x.min_score || ' needed for a suggestion): ' || x.url
           else 'Nothing is stored to read: no entry-requirements link and no matched course page.' end,
         case x.route
           when 'source_page_stored' then 'Job aer-source-stored-find attaches it for the entry matrix reader once Entry pages from stored links: on is 1; a person decides the first read in Layer 4.'
           when 'source_page_host_shared' then 'A person confirms which provider the website and the page belong to.'
           when 'course_pages_waiting' then 'Scheduled entry reading (job aer-scheduled-read) reads them while Layer 4 has room; a person decides every first read in Layer 4.'
           when 'course_pages_unconfirmed' then 'Platform Admin decision: admit title-matched pages for entry requirements, or a person confirms each course page.'
           when 'weak_page_only' then 'Lower Find central pages: minimum score (not under 3), or a person confirms the page.'
           else 'Parked. A new page search of the provider''s website (it uses Firecrawl credits, when the budget allows) or a person adds the entry-requirements page.' end,
         x.route in ('nothing_stored', 'course_pages_unconfirmed', 'source_page_host_shared', 'weak_page_only'),
         case when x.courses > 0 then x.courses end, x.url, x.score
    from x
$$;


ALTER FUNCTION "security"."aer_no_source_route_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_no_source_route_v1"() IS 'CF-247 (10 Nov 2026): for each AER-eligible provider with no entry-requirements source, the route the platform can take from what it already stores (a stored entry page on the provider''s own website, stored and matched course pages, matched by title only, a general page only, or nothing), the reason, the next action and whether the provider is parked. Read only; used by the no_source finding and Data Delivery.';



CREATE OR REPLACE FUNCTION "security"."aer_numbers_in_quote_v1"("p_text" "text", "p_quote" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(bool_and(exists (select 1 from regexp_matches(coalesce(p_quote, ''), '[0-9]+(?:\.[0-9]+)?', 'g') q where q[1]::numeric = t[1]::numeric)), true)
    from regexp_matches(coalesce(p_text, ''), '[0-9]+(?:\.[0-9]+)?', 'g') t
$$;


ALTER FUNCTION "security"."aer_numbers_in_quote_v1"("p_text" "text", "p_quote" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_numbers_in_quote_v1"("p_text" "text", "p_quote" "text") IS 'CF-247 AER workspace: every number in a value is printed in the quote (W7).';



CREATE OR REPLACE FUNCTION "security"."aer_packet_facts_v1"("p_item" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rows int; v_complete int; v_flagged int; v_ns jsonb; v_nr jsonb; v_list jsonb; v_cap int := security.pipeline_num_v1('aer.review_packet_rows', 30)::int;
begin
  with x as (select r.*, array_remove(array[case when r.country = 'not_stated' then 'country' end, case when r.qualification = 'not_stated' then 'qualification' end, case when r.grade = 'not_stated' then 'grade' end,
                                            case when r.scale = 'not_stated' then 'scale' end, case when r.applicability = 'not_stated' then 'applicability' end,
                                            case when r.source_page = 'not_stated' then 'source page' end, case when r.year = 'not_stated' then 'year' end], null) miss
               from security.aer_packet_rows_v1(p_item) r)
  select count(*), count(*) filter (where cardinality(miss) = 0), count(*) filter (where cardinality(miss) > 0),
         jsonb_strip_nulls(jsonb_build_object('country', nullif(count(*) filter (where country = 'not_stated'), 0), 'qualification', nullif(count(*) filter (where qualification = 'not_stated'), 0),
              'grade', nullif(count(*) filter (where grade = 'not_stated'), 0), 'scale', nullif(count(*) filter (where scale = 'not_stated'), 0), 'applicability', nullif(count(*) filter (where applicability = 'not_stated'), 0),
              'source_page', nullif(count(*) filter (where source_page = 'not_stated'), 0), 'year', nullif(count(*) filter (where year = 'not_stated'), 0))),
         jsonb_strip_nulls(jsonb_build_object('year', nullif(count(*) filter (where year = 'not_recorded'), 0))),
         coalesce((select jsonb_agg(jsonb_build_object('row', z.row_id, 'not_stated', to_jsonb(z.miss)) order by z.row_id) from (select * from x where cardinality(miss) > 0 order by row_id limit v_cap) z), '[]'::jsonb)
    into v_rows, v_complete, v_flagged, v_ns, v_nr, v_list from x;
  return jsonb_build_object('item', p_item, 'rows', v_rows, 'complete_rows', v_complete, 'flagged_rows', v_flagged, 'not_stated', v_ns, 'not_recorded', v_nr, 'flagged', v_list,
    'section', jsonb_strip_nulls(jsonb_build_object(
       'Rows', v_rows, 'Rows with every fact stated', v_complete, 'Rows with a fact not stated', nullif(v_flagged, 0),
       'Facts not stated (rows)', nullif(v_ns, '{}'::jsonb), 'Facts the row cannot hold', nullif(v_nr, '{}'::jsonb),
       'Rows to check', nullif(v_list, '[]'::jsonb),
       'Note', 'A fact the page does not print is shown as not stated. It is never filled in, inferred from another row or country, or taken from the date the page was read.')));
end $$;


ALTER FUNCTION "security"."aer_packet_facts_v1"("p_item" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_packet_facts_v1"("p_item" "uuid") IS 'CF-247 AER read now (10 Nov 2026): the facts check of one waiting entry item for its reviewer: rows, rows with every fact stated, and how many rows leave country, qualification, grade, scale, applicability, source page or year not stated. Read only; nothing is filled in.';



CREATE OR REPLACE FUNCTION "security"."aer_packet_rows_v1"("p_item" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("item_id" "uuid", "field_code" "text", "provider_id" "uuid", "course_id" "uuid", "row_id" "uuid", "track" "text", "country" "text", "qualification" "text", "grade" "text", "scale" "text", "applicability" "text", "source_page" "text", "year" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select i.id, i.field_code, i.entity_id, null::uuid, m.id, 'matrix'::text,
         case when nullif(btrim(m.country_code), '') is not null then 'stated' else 'not_stated' end,
         case when nullif(btrim(m.qualification_name), '') is not null then 'stated' else 'not_stated' end,
         case when nullif(btrim(m.min_grade), '') is not null or m.min_value is not null then 'stated' else 'not_stated' end,
         case when nullif(btrim(m.min_grade), '') is null and m.min_value is null then 'not_applicable' when nullif(btrim(m.grade_scale), '') is not null then 'stated' else 'not_stated' end,
         case when (nullif(btrim(m.level_label), '') is not null or m.study_level_id is not null or m.aer_level is not null) and nullif(btrim(m.audience), '') is not null then 'stated' else 'not_stated' end,
         case when nullif(btrim(m.source_url), '') is not null and nullif(btrim(m.quote), '') is not null and m.evidence_id is not null then 'stated' else 'not_stated' end,
         -- the printed year or edition only; as_at is the date the page was read, never a year the page states
         case when m.intake_year is not null or nullif(btrim(m.edition), '') is not null then 'stated' else 'not_stated' end
    from pipeline.layer4_review_items i
    join pipeline.entry_matrix_runs r on r.review_item_id = i.id
    join catalogue.provider_entry_matrix m on m.run_id = r.id and m.status = 'proposed'
   where i.status = 'pending' and i.field_code in ('entry_matrix_first_run', 'entry_matrix_change') and (p_item is null or i.id = p_item)
  union all
  select i.id, i.field_code, c.provider_id, i.entity_id, q.id, 'course'::text,
         -- a course row carries its audience, not a country of prior education: a country is stated only when the row has one, otherwise the fact does not apply (it is never taken from another row)
         case when q.country_id is not null then 'stated' else 'not_applicable' end,
         case when nullif(btrim(q.description), '') is not null then 'stated' else 'not_stated' end,
         case when nullif(btrim(q.min_grade), '') is not null or q.min_value is not null or q.min_entry_score is not null then 'stated'
              when q.kind = 'minimum_grade' then 'not_stated' else 'not_applicable' end,  -- fixed: only a minimum-grade row is expected to print a grade
         case when ((nullif(btrim(q.min_grade), '') is not null or q.min_value is not null) and nullif(btrim(q.grade_scale), '') is null)
                or (q.min_entry_score is not null and nullif(btrim(q.min_entry_score_basis), '') is null) then 'not_stated'
              when nullif(btrim(q.min_grade), '') is not null or q.min_value is not null or q.min_entry_score is not null then 'stated' else 'not_applicable' end,
         case when nullif(btrim(q.audience), '') is not null then 'stated' else 'not_stated' end,
         case when nullif(btrim(q.source_url), '') is not null and nullif(btrim(q.quote), '') is not null and q.evidence_id is not null then 'stated' else 'not_stated' end,
         'not_recorded'::text  -- the course row has no field for a printed intake year: it is said so, not guessed
    from pipeline.layer4_review_items i
    join catalogue.course_entry_requirements q on q.provenance->>'review_item_id' = i.id::text and q.status = 'proposed'
    join catalogue.courses c on c.id = i.entity_id
   where i.status = 'pending' and i.field_code = 'course_entry_first_read' and (p_item is null or i.id = p_item)
$$;


ALTER FUNCTION "security"."aer_packet_rows_v1"("p_item" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_packet_rows_v1"("p_item" "uuid") IS 'CF-247 AER read now (10 Nov 2026): for every proposed row of a waiting entry item (provider matrix or course read), whether country, qualification, grade, scale, applicability, source page and year are stated, not stated, not applicable or not recorded. Nothing is inferred or filled. Read only.';



CREATE OR REPLACE FUNCTION "security"."aer_parked_items_v1"() RETURNS TABLE("item_id" "uuid", "provider_id" "uuid", "field_code" "text", "failure_class" "text", "reason" "text", "next_action" "text", "parked_since" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- the technical lane's own record of a hold that waits for a setting, a person or another copy of the page (stage parked, action park); a transient hold being retried (action retry_backoff) is not parked
  select i.id, w.provider_id, i.field_code, w.failure_class, w.unresolved_blocker->>'reason', w.unresolved_blocker->>'next_action', w.first_blocked_at
    from pipeline.work_items w
    join pipeline.layer4_review_items i on i.id::text = w.entity
   where w.lane = 'aer_technical' and w.work_kind = 'l4_item' and w.stage = 'parked' and w.unresolved_blocker->>'action' = 'park'
     and i.status = 'pending' and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run')  -- fixed: the two entry-requirement item kinds the scheduled reading counts
$$;


ALTER FUNCTION "security"."aer_parked_items_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_parked_items_v1"() IS 'CF-247 (10 Nov 2026): the pending entry-requirement Layer 4 items that the technical lane has parked with their exact reason and next action (row limit, human input, duplicate, stale read). A parked hold is not a decision a reviewer can make, so security.aer_schedule_tick_v1 does not count it against aer.schedule_layer4_max.';



CREATE OR REPLACE FUNCTION "security"."aer_pending_packets_v1"("p_provider" "uuid" DEFAULT NULL::"uuid", "p_course" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("item_id" "uuid", "field_code" "text", "provider_id" "uuid", "course_id" "uuid", "created_at" timestamp with time zone, "readiness" "text", "route" "text", "reasons" "text"[], "gate_complete" boolean, "packet_state" "text", "classified_at" timestamp with time zone, "parked_reason" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select z.id, z.field_code, z.pid, z.cid, z.created_at, z.readiness, z.route, z.reasons, z.complete,
         case when z.readiness = 'judgement_ready' then 'reviewer_ready'
              when z.parked_reason is not null then 'needs_input'
              when z.readiness is null then 'not_checked'
              else 'technical_hold' end,
         z.classified_at, z.parked_reason
    from (select i.id, i.field_code, coalesce(c.provider_id, case when i.entity_type = 'provider' then i.entity_id end) pid, case when i.entity_type = 'course' then i.entity_id end cid, i.created_at,
                 y.readiness, y.route, y.reasons, coalesce((y.gate->>'complete')::boolean, false) complete, y.classified_at, pk.reason parked_reason
            from pipeline.layer4_review_items i
            left join pipeline.layer4_item_readiness y on y.item_id = i.id
            left join catalogue.courses c on i.entity_type = 'course' and c.id = i.entity_id
            -- the technical lane's parked record of THIS item, by the unique key (lane, entity, work_kind): the rule of security.aer_parked_items_v1() without computing it for every item (that function costs seconds on its own)
            left join lateral (select w.unresolved_blocker->>'reason' reason from pipeline.work_items w
                                where w.lane = 'aer_technical' and w.work_kind = 'l4_item' and w.entity = i.id::text and w.stage = 'parked' and w.unresolved_blocker->>'action' = 'park'
                                  and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run')) pk on true  -- fixed: the two entry-requirement item kinds the parked record covers
           where i.status = 'pending' and i.field_code = any (security.aer_review_kinds_v1())
             and (p_course is null or (i.entity_type = 'course' and i.entity_id = p_course))
             and (p_provider is null or coalesce(c.provider_id, case when i.entity_type = 'provider' then i.entity_id end) = p_provider)) z
$$;


ALTER FUNCTION "security"."aer_pending_packets_v1"("p_provider" "uuid", "p_course" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_pending_packets_v1"("p_provider" "uuid", "p_course" "uuid") IS 'CF-247 AER read now (10 Nov 2026): the waiting entry-requirement Layer 4 items of a provider or a course with their packet state from the stored completeness gate: reviewer_ready (a person can decide it now), technical_hold (the gate holds it; recovery applies), needs_input (parked by the technical lane), not_checked. Read only.';



CREATE OR REPLACE FUNCTION "security"."aer_progress_counts_v1"("p_since" timestamp with time zone, "p_provider" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with dec as (select d.* from pipeline.layer4_decisions d join pipeline.layer4_review_items i on i.id = d.review_item_id
                left join catalogue.courses c on i.entity_type = 'course' and c.id = i.entity_id
               where d.created_at >= p_since and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run', 'entry_matrix_change')
                 and (p_provider is null or coalesce(c.provider_id, case when i.entity_type = 'provider' then i.entity_id end) = p_provider))
  select jsonb_build_object('since', p_since,
    'submitted', (select count(*) from pipeline.admin_control_events e where e.area = 'layer4' and e.action = 'inbox_decide' and e.created_at >= p_since
                   and e.target like 'aer_review:%' and (p_provider is null or e.detail->>'provider_id' = p_provider::text)),
    'saved', (select count(*) from dec), 'saved_by_action', (select jsonb_object_agg(z.action, z.n) from (select dec.action, count(*) n from dec group by 1) z),
    'admitted_rows', (select count(*) from catalogue.course_entry_requirements x where x.status = 'active' and x.provenance->>'review_item_id' in (select dec.review_item_id::text from dec))
                     + (select count(*) from catalogue.provider_entry_matrix m join pipeline.entry_matrix_runs r on r.id = m.run_id where m.status = 'active' and r.review_item_id in (select dec.review_item_id from dec)),
    'admitted_courses', (select count(distinct x.course_id) from catalogue.course_entry_requirements x where x.status = 'active' and x.provenance->>'review_item_id' in (select dec.review_item_id::text from dec)),
    'published_courses', (select count(distinct x.course_id) from catalogue.course_entry_requirements x join search.course_documents d on d.course_id = x.course_id
                           where x.status = 'active' and x.provenance->>'review_item_id' in (select dec.review_item_id::text from dec)))
$$;


ALTER FUNCTION "security"."aer_progress_counts_v1"("p_since" timestamp with time zone, "p_provider" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_provider_load_v1"() RETURNS TABLE("provider_id" "uuid", "waiting" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select z.pid, count(distinct z.k) from (
    select q.provider_id pid, q.item_id::text k
      from security.aer_review_ready_v1(null) q join pipeline.work_review_categories rc on rc.category = 'aer'
     where q.field_code = any (rc.field_codes) and q.ready and q.duplicate_of is null and coalesce(q.readiness, '') not in ('resolvable', 'closed')
    union all
    select f.provider_id, 'read:' || coalesce(f.course_id, f.provider_id)
      from pipeline.field_enrich_items f join pipeline.work_review_categories rc on rc.category = 'aer'
     where f.field = any (rc.in_progress_fields) and f.state in ('queued', 'waiting', 'ai', 'leased')) z
   where z.pid is not null group by z.pid
$$;


ALTER FUNCTION "security"."aer_provider_load_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_provider_stage_v1"("p_providers" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("provider_id" "uuid", "provider_name" "text", "stage" "text", "sources" "jsonb", "reads" "jsonb", "layer4" "jsonb", "admitted" "jsonb", "consumer" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_ids uuid[] := coalesce(p_providers, array(select x::uuid from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'coverage.aer_priority_providers'), '[]'::jsonb)) x));
        v_scan int := greatest(1, security.pipeline_num_v1('coverage.stage_gate_scan', 50)::int);
        v_sample int := greatest(0, security.pipeline_num_v1('coverage.stage_consumer_course_sample', 20)::int);
        r record; i record; g jsonb; v_ready int; v_block int; v_checked int; v_why jsonb; v_pub int; v_seen int; v_prov jsonb; v_cpub int; v_ccheck int;
begin
  for r in select p.id, coalesce(p.display_name, p.short_name, p.canonical_name) nm, p.stable_key from catalogue.providers p where p.id = any (v_ids) order by 2 loop
    provider_id := r.id; provider_name := r.nm;
    select jsonb_build_object('attached', count(*), 'read', count(*) filter (where s.status = 'read'), 'failed', count(*) filter (where s.status = 'failed'),
                              'unread', count(*) filter (where s.status not in ('read', 'failed')), 'fingerprint', md5(string_agg(s.url || '=' || coalesce(s.content_hash, ''), '|' order by s.url)))
      into sources from pipeline.entry_matrix_sources s where s.provider_id = r.id;
    with lr as (select distinct on (x.source_id) x.* from pipeline.entry_matrix_runs x where x.provider_id = r.id order by x.source_id, x.created_at desc),
    cr as (select li.status, count(*) n from pipeline.layer4_review_items li join catalogue.courses c on c.id = li.entity_id
            where c.provider_id = r.id and li.field_code = 'course_entry_first_read' group by 1)
    select jsonb_build_object('matrix_done', (select count(*) from lr where lr.state = 'done'),
             'matrix_held', (select count(*) from lr where lr.state = 'failed'),
             'matrix_held_reasons', (select coalesce(jsonb_object_agg(w, n), '{}'::jsonb) from (select split_part(coalesce(lr.error, 'failed'), ':', 1) w, count(*) n from lr where lr.state = 'failed' group by 1) z),
             'course_reads', (select coalesce(jsonb_object_agg(cr.status, cr.n), '{}'::jsonb) from cr))
      into reads;
    v_ready := 0; v_block := 0; v_checked := 0; v_why := '{}'::jsonb;
    for i in (select 'matrix' kind, x.id run_id, li.id item_id, li.created_at from pipeline.entry_matrix_runs x join pipeline.layer4_review_items li on li.id = x.review_item_id
               where x.provider_id = r.id and li.status = 'pending'
              union all
              select 'course', null, li.id, li.created_at from pipeline.layer4_review_items li join catalogue.courses c on c.id = li.entity_id
               where c.provider_id = r.id and li.field_code = 'course_entry_first_read' and li.status = 'pending')
             order by 4 desc limit v_scan loop
      g := case i.kind when 'matrix' then security.entry_matrix_gate_v1(i.run_id, '{}'::uuid[]) else security.course_entry_gate_v1(i.item_id, '{}'::uuid[]) end;
      v_checked := v_checked + 1;
      if coalesce((g->>'complete')::boolean, false) then v_ready := v_ready + 1;
      else
        v_block := v_block + 1;
        v_why := v_why || jsonb_build_object(i.kind || ': ' || left(coalesce(g->'reasons'->>0, 'incomplete'), 90),
                                             coalesce((v_why->>(i.kind || ': ' || left(coalesce(g->'reasons'->>0, 'incomplete'), 90)))::int, 0) + 1);
      end if;
    end loop;
    layer4 := jsonb_build_object('pending', (select count(*) from (select li.id from pipeline.entry_matrix_runs x join pipeline.layer4_review_items li on li.id = x.review_item_id
                                                                    where x.provider_id = r.id and li.status = 'pending'
                                                                   union all select li.id from pipeline.layer4_review_items li join catalogue.courses c on c.id = li.entity_id
                                                                    where c.provider_id = r.id and li.field_code = 'course_entry_first_read' and li.status = 'pending') z),
                                 'checked', v_checked, 'judgement_ready', v_ready, 'technically_blocked', v_block, 'blocked_reasons', v_why);
    select jsonb_build_object('matrix_active', (select count(*) from catalogue.provider_entry_matrix m where m.provider_id = r.id and m.status = 'active'),
                              'matrix_proposed', (select count(*) from catalogue.provider_entry_matrix m where m.provider_id = r.id and m.status = 'proposed'),
                              'course_rows_active', count(*) filter (where x.status = 'active'), 'courses_with_active', count(distinct x.course_id) filter (where x.status = 'active'),
                              'course_rows_proposed', count(*) filter (where x.status = 'proposed'))
      into admitted from catalogue.course_entry_requirements x join catalogue.courses c on c.id = x.course_id where c.provider_id = r.id;
    -- the website projection, read only (the consumer API is not changed or re-shaped; G3)
    v_prov := case when to_regprocedure('public.website_v2_provider(text)') is not null then public.website_v2_provider(r.stable_key) end;
    v_pub := coalesce(jsonb_array_length(case when jsonb_typeof(v_prov->'item'->'entry_matrix') = 'array' then v_prov->'item'->'entry_matrix' end), 0);
    v_cpub := 0; v_ccheck := 0;
    if to_regprocedure('public.website_v2_course(text)') is not null then
      for i in select c.stable_key from catalogue.courses c where c.provider_id = r.id and c.lifecycle_status = 'active'
                 and exists (select 1 from catalogue.course_entry_requirements x where x.course_id = c.id and x.status = 'active') order by c.id limit v_sample loop
        g := public.website_v2_course(i.stable_key)->'item'->'entry';
        v_ccheck := v_ccheck + 1;
        if g is not null and jsonb_typeof(g) = 'object' and (g->>'min_score' is not null or jsonb_array_length(coalesce(case when jsonb_typeof(g->'prerequisites') = 'array' then g->'prerequisites' end, '[]'::jsonb)) > 0)
          then v_cpub := v_cpub + 1; end if;
      end loop;
    end if;
    consumer := jsonb_build_object('provider_matrix_rows_published', v_pub, 'provider_found', coalesce(v_prov ? 'item', false),
                                   'courses_checked', v_ccheck, 'courses_with_published_entry', v_cpub);
    stage := case when v_pub > 0 or v_cpub > 0 then 'published'
                  when (admitted->>'matrix_active')::int + (admitted->>'course_rows_active')::int > 0 then 'admitted_not_published'
                  when v_ready > 0 then 'awaiting_judgement'
                  when v_block > 0 then 'technically_blocked'
                  when (reads->>'matrix_held')::int > 0 then 'read_held'
                  when (sources->>'read')::int > 0 or jsonb_typeof(reads->'course_reads') = 'object' and reads->'course_reads' <> '{}'::jsonb then 'read'
                  when (sources->>'attached')::int > 0 then 'source_attached'
                  else 'no_source' end;
    return next;
  end loop;
end $$;


ALTER FUNCTION "security"."aer_provider_stage_v1"("p_providers" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_provider_stage_v1"("p_providers" "uuid"[]) IS 'CF-247 workstream C (Integration Controller 3 Nov 2026 18:30): per followed provider (coverage.aer_priority_providers, or those given), the AER stages kept apart: sources attached; reads done or held with reasons; Layer 4 items judgement-ready or technically blocked (D-R3 and E13 gates, coverage.stage_gate_scan items); active rows; and what the website projection returns (public.website_v2_provider, public.website_v2_course, read only). Discovery and an AI read never count as admission. Read-only.';



CREATE OR REPLACE FUNCTION "security"."aer_provider_states_v1"() RETURNS TABLE("provider_id" "uuid", "provider_name" "text", "country" "text", "provider_type" "text", "disposition" "text", "discovery_state" "text", "extraction_state" "text", "admission_state" "text", "consumer_resolvable" boolean, "priority_tier" integer, "priority_rank" integer, "courses_eligible" integer, "sources" integer, "sources_read" integer, "sources_failed" integer, "runs_held" integer, "runs_failed" integer, "matrix_active" integer, "matrix_other" integer, "course_req_active" integer, "course_req_proposed" integer, "layer4" "jsonb", "held_scopes" "jsonb", "root_causes" "text"[], "evidence" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with el as (select e.provider_id, e.country from security.aer_eligible_v1() e),
  pv as (select el.provider_id, el.country, coalesce(p.display_name, p.short_name, p.canonical_name) pname, t.code ptype
           from el join catalogue.providers p on p.id = el.provider_id left join ref.provider_types t on t.id = p.provider_type_id),
  src as (
    select s.provider_id, count(*) n, count(*) filter (where s.status = 'read') nread, count(*) filter (where s.status = 'failed') nfail,
           count(*) filter (where s.status = 'read' and r.state = 'failed' and coalesce(r.error, '') ~* '^held') nheld,
           count(*) filter (where s.status = 'read' and ((r.state = 'failed' and coalesce(r.error, '') !~* '^held') or r.id is null)) nrfail,
           count(*) filter (where s.status = 'read' and r.state = 'done') ndone,
           count(*) filter (where r.result->>'outcome' = 'no_requirements_table' and li.status in ('approved', 'edited_approved')) nnotable,
           count(*) filter (where li.status = 'pending') l4pend,
           count(*) filter (where li.status is not null and li.status not in ('pending', 'approved', 'edited_approved', 'superseded')) l4other,
           coalesce(jsonb_agg(jsonb_build_object('source_id', s.id, 'url', s.url, 'status', s.status, 'run_id', r.id, 'run_state', r.state,
                     'run_error', left(r.error, 160), 'review_item_id', li.id, 'review_status', li.status) order by s.rank, s.title), '[]'::jsonb) ev
      from pipeline.entry_matrix_sources s
      join el on el.provider_id = s.provider_id
      left join lateral (select r1.id, r1.state, r1.error, r1.result, r1.review_item_id from pipeline.entry_matrix_runs r1 where r1.source_id = s.id order by r1.created_at desc limit 1) r on true
      left join pipeline.layer4_review_items li on li.id = r.review_item_id
     group by s.provider_id),
  mx as (select m.provider_id, count(*) filter (where m.status = 'active') act, count(*) filter (where m.status <> 'active') other,
                count(*) filter (where m.status = 'proposed') prop
           from catalogue.provider_entry_matrix m join el on el.provider_id = m.provider_id group by 1),
  -- course-level requirements of the provider's eligible courses (active, published)
  cr as (select c.provider_id, count(*) filter (where x.status = 'active') act, count(*) filter (where x.status = 'proposed') prop
           from catalogue.course_entry_requirements x join catalogue.courses c on c.id = x.course_id join el on el.provider_id = c.provider_id
          where c.lifecycle_status = 'active' group by 1),  -- CF-247 workstream C: course visibility follows the provider; no AU or NZ course is 'published'
  cc as (select c.provider_id, count(*) n from catalogue.courses c join el on el.provider_id = c.provider_id
          where c.lifecycle_status = 'active' and c.open_to_international is not false group by 1),
  co as (select o.provider_id, bool_or(o.outcome in ('admitted_course', 'admitted_provider')) cons, count(*) filter (where o.outcome = 'awaiting_review') aw
           from pipeline.aer_course_outcomes o join el on el.provider_id = o.provider_id group by 1),
  fd as (select g.provider_id, array_agg(distinct g.root_cause order by g.root_cause) causes, bool_or(g.severity = 'P0') p0,
                coalesce(jsonb_agg(distinct jsonb_build_object('kind', g.scope_kind, 'scope', g.scope_label)) filter (where g.scope_kind in ('country', 'qualification')), '[]'::jsonb) scopes
           from pipeline.aer_gap_findings g join el on el.provider_id = g.provider_id where g.state <> 'resolved' group by 1),
  na as (select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'aer.not_applicable_provider_types'), '[]'::jsonb)) code),
  pt as (select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'aer.priority_provider_types'), '[]'::jsonb)) code),
  d as (
    select pv.*, coalesce(src.n, 0) n, coalesce(src.nread, 0) nread, coalesce(src.nfail, 0) nfail, coalesce(src.nheld, 0) nheld, coalesce(src.nrfail, 0) nrfail,
           coalesce(src.ndone, 0) ndone, coalesce(src.nnotable, 0) nnotable, coalesce(src.l4pend, 0) l4pend, coalesce(src.l4other, 0) l4other, coalesce(src.ev, '[]'::jsonb) ev,
           coalesce(mx.act, 0) mact, coalesce(mx.other, 0) mother, coalesce(mx.prop, 0) mprop, coalesce(cr.act, 0) cact, coalesce(cr.prop, 0) cprop,
           coalesce(cc.n, 0) courses, coalesce(co.aw, 0) caw, coalesce(co.cons, false) and not coalesce(fd.p0, false) cons,
           coalesce(fd.causes, '{}') causes, coalesce(fd.scopes, '[]'::jsonb) scopes,
           case when pv.ptype in (select code from pt) then 1 else 2 end tier
      from pv left join src on src.provider_id = pv.provider_id left join mx on mx.provider_id = pv.provider_id left join cr on cr.provider_id = pv.provider_id
      left join cc on cc.provider_id = pv.provider_id left join co on co.provider_id = pv.provider_id left join fd on fd.provider_id = pv.provider_id),
  x as (
    select d.*, case
      when d.n = 0 then case
        when d.cact > 0 then 'course_only'                                   -- no matrix source, but course-level requirements are active
        when d.cprop > 0 or d.caw > 0 or d.mprop > 0 then 'awaiting_layer4'
        when d.mact > 0 then 'active_verified'
        when d.ptype in (select code from na) then 'not_applicable_evidenced' -- the register type is the evidence (setting, empty by default)
        else 'not_discovered' end
      when d.nfail = d.n or d.nrfail > 0 then 'reader_failed'
      when d.nheld > 0 then 'source_held'
      when d.mprop > 0 or d.cprop > 0 or d.l4pend > 0 or d.caw > 0 then 'awaiting_layer4'
      when d.mact > 0 then 'active_verified'
      when d.cact > 0 then 'course_only'
      when d.nnotable > 0 then 'source_not_published_evidenced'           -- an approved Layer 4 "no requirements table" note
      else 'reader_failed' end disp                                         -- read and finished, but nothing extracted and no evidence why
      from d)
  select x.provider_id, x.pname, x.country, x.ptype, x.disp,
         case when x.n = 0 then 'not_discovered' when x.nread > 0 then 'source_read' else 'source_unreadable' end,
         case when x.n = 0 then 'none' when x.nrfail > 0 or x.nfail = x.n then 'failed' when x.nheld > 0 then 'held' when x.ndone > 0 then 'complete' else 'none' end,
         case when (x.mact > 0 or x.cact > 0) and (x.mprop > 0 or x.cprop > 0 or x.l4pend > 0 or x.caw > 0) then 'active_and_awaiting'
              when x.mact > 0 or x.cact > 0 then 'active' when x.mprop > 0 or x.cprop > 0 or x.l4pend > 0 or x.caw > 0 then 'awaiting' else 'none' end,
         x.cons, x.tier,
         (row_number() over (order by x.tier,
            -- display order, not an operational value: held and failed sources sit with the providers still to be discovered
            array_position(array['source_held', 'reader_failed', 'not_discovered', 'awaiting_layer4', 'course_only', 'source_not_published_evidenced',
                                 'not_applicable_evidenced', 'active_verified'], x.disp), x.courses desc, x.pname, x.provider_id))::int,
         x.courses::int, x.n::int, x.nread::int, x.nfail::int, x.nheld::int, x.nrfail::int, x.mact::int, x.mother::int, x.cact::int, x.cprop::int,
         jsonb_build_object('matrix_pending', x.l4pend, 'matrix_returned_or_rejected', x.l4other, 'course_awaiting_review', x.caw),
         x.scopes, x.causes, jsonb_build_object('sources', x.ev)
    from x
$$;


ALTER FUNCTION "security"."aer_provider_states_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_provider_states_v1"() IS 'CF-247 AER catalogue-first gap queue (Platform Admin 2 Nov 2026 15:43): every eligible provider with its report disposition, discovery/extraction/admission states, exact source, run and review ids and priority. Database metadata only; no crawl.';



CREATE OR REPLACE FUNCTION "security"."aer_quote_has_value_v1"("p_quote" "text", "p_grade" "text", "p_value" numeric) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  -- the published minimum is in the quote as a whole token: the grade text when the row has one, otherwise the value (70, 3.3; never 170 or 3.35)
  select case when nullif(btrim(coalesce(p_grade, '')), '') is not null
              then coalesce(p_quote, '') ~* ('(^|[^0-9A-Za-z.])' || regexp_replace(btrim(p_grade), '([.*+?^${}()|\[\]\\])', '\\\1', 'g') || '($|[^0-9A-Za-z])')
              when p_value is not null
              then coalesce(p_quote, '') ~ ('(^|[^0-9.])' || replace(trim_scale(p_value)::text, '.', '\.') || '($|[^0-9])')
              else false end
$_$;


ALTER FUNCTION "security"."aer_quote_has_value_v1"("p_quote" "text", "p_grade" "text", "p_value" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_quote_has_value_v1"("p_quote" "text", "p_grade" "text", "p_value" numeric) IS 'CF-247 F-AER.04 D1: true when a row''s published minimum (grade text, or value) is in its quote as a whole token.';



CREATE OR REPLACE FUNCTION "security"."aer_read_now_class_v1"("p_outcome" "text", "p_reason" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$ select case
  when p_outcome = 'budget_reached' then 'budget_hold'
  when p_outcome = 'human_review_required' then 'human_review'
  when p_reason in ('nothing_stored', 'no_course_page') then 'no_source_on_record'
  when p_reason in ('course_page_not_bound', 'no_stored_copy', 'identity_not_admitted', 'host_shared', 'weak_page_only', 'stored_page_not_yet_attached', 'stored_find_off', 'robots_disallowed') then 'source_found_not_read'
  when p_reason = 'tried_not_found' then 'tried_not_found'
  when p_reason in ('technical_failure_retry', 'technical_failure_retried', 'source_fetch_failed') then 'technical_failure'
  end $$;


ALTER FUNCTION "security"."aer_read_now_class_v1"("p_outcome" "text", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_read_now_class_v1"("p_outcome" "text", "p_reason" "text") IS 'CF-247 AER read now (10 Nov 2026, Operating Model v1.7): the kind of evidence behind an outcome, as a screen label only (no_source_on_record, source_found_not_read, tried_not_found, technical_failure, budget_hold, human_review, or null). Derived from the existing outcome and reason; it is not stored and is not a state.';



CREATE OR REPLACE FUNCTION "security"."aer_read_now_out_v1"("p_outcome" "text", "p_reason" "text", "p_text" "text", "p_next" "text", "p_actions" "jsonb" DEFAULT '[]'::"jsonb", "p_extra" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$ select jsonb_build_object('outcome', p_outcome, 'reason', p_reason, 'text', p_text, 'next_action', p_next, 'actions', coalesce(p_actions, '[]'::jsonb)) || coalesce(p_extra, '{}'::jsonb) $$;


ALTER FUNCTION "security"."aer_read_now_out_v1"("p_outcome" "text", "p_reason" "text", "p_text" "text", "p_next" "text", "p_actions" "jsonb", "p_extra" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_read_now_plan_v1"("p_provider" "uuid", "p_course" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_pid uuid; v_cid uuid; v_pname text; v_ctitle text; v_cc text; v_life text;
  v_ai text := security.ai_use_refusal_v1('enrich_fields'); v_aim text := security.ai_use_refusal_v1('entry_matrix');
  v_bal numeric; v_floor numeric := coalesce((security.toolset_setting('openrouter', 'credit_floor_usd'))::text::numeric, 0); v_cost numeric := security.course_entry_cost_v1();
  v_per int := security.pipeline_num_v1('aer.schedule_per_provider', 5)::int; v_daymax int := security.pipeline_num_v1('aer.schedule_daily_max', 200)::int;
  v_l4max int := security.pipeline_num_v1('aer.schedule_layer4_max', 600)::int; v_srcmax int := security.pipeline_num_v1('entry.attach_per_provider', 3)::int;
  v_replay_on boolean := security.pipeline_num_v1('aer.replay_on', 1) >= 1; v_replay_per int := security.pipeline_num_v1('aer.replay_per_provider', 5)::int;
  v_replay_left int := security.pipeline_num_v1('aer.replay_daily_max', 100)::int - (select count(*) from pipeline.aer_read_supersessions s where s.reason like 'Replay of the stored read%' and s.requested_at > now() - interval '1 day');  -- fixed: the replay cap is counted over the last 24 hours, as the replay job counts it
  v_e13_on boolean := security.pipeline_num_v1('aer.e13_recover_on', 0) >= 1; v_sf_on boolean := security.pipeline_num_v1('aer.source_stored_find_on', 0) >= 1;
  v_used int; v_od int; v_l4 int; v_parked int; v_prog int; v_room int; v_n int; v_actions jsonb := '[]'::jsonb; v_blocks jsonb := '[]'::jsonb; v_extra jsonb;
  r record; g record; p jsonb; v_cnt jsonb; v_same boolean := false; v_sn record; v_hold_ids uuid[]; v_retry int := security.pipeline_num_v1('aer.schedule_retry_days', 30)::int; v_when timestamptz; v_inflight int; v_elig int; v_pick uuid[]; v_ready int; v_hold int; v_input int; v_chk int; v_srcs int; v_stale text; v_route text;
begin
  if p_course is not null then
    select c.id, c.provider_id, coalesce(c.display_title, c.canonical_title), c.lifecycle_status, k.iso_alpha2::text, coalesce(pv.display_name, pv.canonical_name)
      into v_cid, v_pid, v_ctitle, v_life, v_cc, v_pname
      from catalogue.courses c join catalogue.providers pv on pv.id = c.provider_id left join ref.countries k on k.id = pv.country_id where c.id = p_course;
  else
    select pv.id, coalesce(pv.display_name, pv.canonical_name), k.iso_alpha2::text into v_pid, v_pname, v_cc
      from catalogue.providers pv left join ref.countries k on k.id = pv.country_id where pv.id = p_provider;
  end if;
  if v_pid is null then return security.aer_read_now_out_v1('no_eligible_work', 'unknown_scope', 'That provider or course was not found.', null); end if;
  select o.remaining_usd into v_bal from pipeline.layer3_openrouter_observations o where o.kind = 'credits' order by o.observed_at desc limit 1;

  ---------------------------------------------------------------------------------------------------------------------------------- one course
  if v_cid is not null then
    if v_life is distinct from 'active' then return security.aer_read_now_out_v1('no_eligible_work', 'course_not_active', 'The course is not active, so there is nothing to read.', null); end if;
    if v_cc is null or not coalesce(security.toolset_setting('pipeline', 'entry.course_read_countries'), '[]'::jsonb) ? v_cc then
      return security.aer_read_now_out_v1('switch_off', 'course_read_country_off', 'Course entry requirements are not read for ' || coalesce(v_cc, 'this country') || ' (setting Course entry requirements: countries read).',
                                          'A Platform Admin switches the country on in Toolsets & limits.');
    end if;
    if exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = v_cid
                  and (coalesce(security.toolset_setting('pipeline', 'aer.schedule_lock_fields'), '[]'::jsonb) ? l.field or l.field = 'all')) then
      return security.aer_read_now_out_v1('human_review_required', 'manual_lock', 'This course''s entry requirements are locked by hand. A lock is a person''s decision, so nothing is read.',
                                          'A Platform Admin lifts the lock if the course should be read.');
    end if;
    if exists (select 1 from pipeline.field_enrich_items f where f.course_id = v_cid and f.field = 'entry_requirements' and f.state in ('queued', 'waiting', 'ai', 'leased')) then
      return security.aer_read_now_out_v1('in_progress', 'read_in_progress', 'A read of this course is already waiting or running. You can close this page: it carries on, and the result appears here.',
                                          'The reader finishes it, then its rows wait in Layer 4 for a person.');
    end if;
    -- a waiting packet: complete = a person's decision; held = recovery from stored records first
    select * into g from security.aer_pending_packets_v1(null, v_cid) order by created_at limit 1;
    if g.item_id is not null then
      if g.packet_state = 'reviewer_ready' then
        return security.aer_read_now_out_v1('human_review_required', 'packet_ready', 'A complete reviewer packet for this course is waiting in Layer 4. A person decides it; nothing is published until then.', 'Open the item in Layer 4.',
                                            '[]', jsonb_build_object('item_id', g.item_id));
      elsif g.packet_state = 'not_checked' then
        return security.aer_read_now_out_v1('in_progress', 'waiting_for_gate', 'The waiting read has not been checked by the completeness gate yet (job layer4-readiness).', 'The gate checks it on its next run.', '[]', jsonb_build_object('item_id', g.item_id));
      elsif g.packet_state = 'needs_input' then
        return security.aer_read_now_out_v1('human_review_required', 'needs_input', 'The waiting read needs input before it can be decided: ' || coalesce(g.parked_reason, 'parked by the technical lane') || '.',
                                            'A person or the Platform Admin supplies it; the read is not repeated on an unchanged page.', '[]', jsonb_build_object('item_id', g.item_id));
      end if;
      -- technical hold: replay from the stored records (no AI, no fetch)
      if v_replay_on and v_replay_left > 0 then
        p := security.aer_replay_plan_v1(g.item_id);
        if coalesce((p->>'ok')::boolean, false) then
          return security.aer_read_now_out_v1('queued', 'replay_from_stored_records', 'The held read can be recovered from its stored records. It is replaced by a complete read for a person to decide; nothing is read again from the web.', 'Open the item in Layer 4 once it is replaced.',
                                              jsonb_build_array(jsonb_build_object('kind', 'replay_item', 'item_id', g.item_id)), jsonb_build_object('item_id', g.item_id));
        end if;
      end if;
      if not v_e13_on then
        return security.aer_read_now_out_v1('switch_off', 'e13_recover_off', 'The waiting read is held by the completeness gate. A corrected read from its stored page is possible, but the E13 recovery switch is off (setting Entry requirements: re-read held reads from stored evidence).',
                                            'A Platform Admin decides whether to switch E13 recovery on.', '[]', jsonb_build_object('item_id', g.item_id));
      end if;
      return security.aer_read_now_out_v1('human_review_required', 'needs_input', 'The waiting read is held by the completeness gate and its automatic recovery has already run or is not possible (' || coalesce(left(p->>'why', 160), 'see Layer 4') || ').',
                                          'A person completes it in Layer 4.', '[]', jsonb_build_object('item_id', g.item_id));
    end if;
    select pg.url, pg.status, pg.identity_basis, pg.evidence_id, a.storage_path is not null held, a.captured_at, a.content_hash hash into g from pipeline.coverage_course_pages pg left join pipeline.evidence_artifacts a on a.id = pg.evidence_id where pg.course_id = v_cid;
    if g.url is null then return security.aer_read_now_out_v1('source_unavailable', 'no_course_page', 'No official page is bound to this course, so there is nothing to read.', 'Course-page discovery binds it; a person can add the page. No search is started from here.'); end if;
    if g.status is distinct from 'bound' then return security.aer_read_now_out_v1('source_unavailable', 'course_page_not_bound', 'The course page is not bound to this course (' || coalesce(g.status, 'unknown') || ').', 'The page binding is resolved in course-page discovery.', '[]', jsonb_build_object('url', g.url)); end if;
    if not g.held then return security.aer_read_now_out_v1('source_unavailable', 'no_stored_copy', 'The page is known but no stored copy exists. Fetching it uses the scraper budget, which is not started from here.', 'The page is stored by the course-page crawl.', '[]', jsonb_build_object('url', g.url)); end if;
    if not security.coverage_identity_allowed(v_pid, g.identity_basis, 'entry_requirements') then
      return security.aer_read_now_out_v1('source_unavailable', 'identity_not_admitted', 'The page is matched to the course by ' || replace(coalesce(g.identity_basis, 'an unrecorded basis'), '_', ' ') || ' only, which is not admitted for entry requirements (a Platform Admin decision is pending). It is not read.',
                                          'A Platform Admin decision, or a person confirms the course page.', '[]', jsonb_build_object('url', g.url));
    end if;
    select f.state, f.evidence_id, f.updated_at, f.reason into r from pipeline.field_enrich_items f where f.course_id = v_cid and f.field = 'entry_requirements' and f.state in ('review', 'filled', 'skipped', 'failed') order by f.id desc limit 1;
    -- unchanged evidence is not read again: the same stored copy, or another copy with the same content hash
    v_same := r.state in ('review', 'filled', 'skipped') and (r.evidence_id is not distinct from g.evidence_id
              or exists (select 1 from pipeline.evidence_artifacts e1 join pipeline.evidence_artifacts e2 on e2.content_hash = e1.content_hash where e1.id = r.evidence_id and e2.id = g.evidence_id and e1.content_hash is not null));
    if v_same and r.state = 'skipped' and r.reason in ('the page does not state it', 'no quoted requirement was on the page', 'no row met the admission rules') then
      return security.aer_read_now_out_v1('already_up_to_date', 'tried_not_found', 'The stored copy of this course''s page was read on ' || to_char(r.updated_at at time zone 'Australia/Melbourne', 'DD Mon YYYY') || ' and no entry requirement was kept from it (recorded: "' || r.reason || '"). An unchanged copy is not read again, so nothing is spent.',
                                          'A person can add the requirement or correct the page. It is read again when the page changes or after ' || security.pipeline_num_v1('aer.schedule_retry_days', 30)::int || ' days.', '[]', jsonb_build_object('url', g.url));
    end if;
    if v_same then
      return security.aer_read_now_out_v1('already_up_to_date', 'same_stored_copy', 'This course was read on the current stored copy of its page (' || to_char(r.updated_at at time zone 'Australia/Melbourne', 'DD Mon YYYY') || ')' || case when r.state = 'skipped' then '; recorded: "' || left(coalesce(r.reason, 'no reason recorded'), 160) || '"' else '' end || '. An unchanged copy is not read again, so nothing is spent.',
                                          'It is read again when the page changes or after ' || security.pipeline_num_v1('aer.schedule_retry_days', 30)::int || ' days if it kept nothing.', '[]', jsonb_build_object('url', g.url));
    end if;
    -- asked from here already for this stored copy (same content hash) within the retry interval: not queued again, so a click cannot re-queue a failing read for ever
    if r.state = 'failed' then
    select max(e.created_at) into v_when from pipeline.admin_control_events e where e.area = 'aer_read_now' and e.created_at > now() - make_interval(days => v_retry)
       and e.detail->'started' @> jsonb_build_array(jsonb_build_object('kind', 'read_course', 'course_id', v_cid::text, 'content_hash', coalesce(g.hash, g.evidence_id::text, '')));
    if v_when is not null then
      return security.aer_read_now_out_v1('no_eligible_work', 'technical_failure_retried', 'The last read of this course failed (recorded: "' || left(coalesce(r.reason, 'no reason recorded'), 160) || '") and was already asked again from here on ' || to_char(v_when at time zone 'Australia/Melbourne', 'DD Mon YYYY') || ' against the same stored copy of the page. It is not asked again against an unchanged page.',
                                          'It is read again when the page changes or after ' || v_retry || ' days.', '[]', jsonb_build_object('url', g.url));
    end if;
    end if;
    if v_ai is not null then return security.aer_read_now_out_v1('budget_reached', 'ai_stopped', 'AI reading is stopped (AI limits): ' || v_ai || '. Nothing was asked.', 'It resumes when the AI limit allows.'); end if;
    if v_bal is not null and v_bal - v_cost < v_floor then return security.aer_read_now_out_v1('budget_reached', 'credit_floor', 'The read would take the OpenRouter balance below its floor (Toolsets & limits). Nothing was asked.', 'A Platform Admin tops up or lowers the floor.'); end if;
    if r.state = 'failed' then
      return security.aer_read_now_out_v1('queued', 'technical_failure_retry', 'The last read of this course failed (recorded: "' || left(coalesce(r.reason, 'no reason recorded'), 160) || '"). It will be read again from the stored copy of its official page. No scraper is used. Its rows wait in Layer 4 for a person.', 'Open the item in Layer 4 when it arrives.',
                                          jsonb_build_array(jsonb_build_object('kind', 'read_course', 'course_id', v_cid, 'content_hash', coalesce(g.hash, g.evidence_id::text, ''))), jsonb_build_object('url', g.url, 'estimate_usd', round(v_cost, 4)));
    end if;
    return security.aer_read_now_out_v1('queued', 'course_read', 'The course will be read from the stored copy of its official page. No scraper is used. Its rows wait in Layer 4 for a person.', 'Open the item in Layer 4 when it arrives.',
                                        jsonb_build_array(jsonb_build_object('kind', 'read_course', 'course_id', v_cid, 'content_hash', coalesce(g.hash, g.evidence_id::text, ''))), jsonb_build_object('url', g.url, 'estimate_usd', round(v_cost, 4)));
  end if;

  ---------------------------------------------------------------------------------------------------------------------------------- one provider (the university's matrix and its course-level reading)
  if not exists (select 1 from security.aer_eligible_v1() e where e.provider_id = v_pid) then
    return security.aer_read_now_out_v1('no_eligible_work', 'not_aer_eligible', 'This provider is outside entry-requirements reading (it must be an active, published provider that enrols international students, in a country that is read).', null);
  end if;
  if not coalesce((security.aer_schedule_country_v1(v_cc)->>'on')::boolean, false) then
    return security.aer_read_now_out_v1('switch_off', 'country_off', 'Entry-requirements reading is switched off for ' || coalesce(v_cc, 'this country') || ': ' || coalesce(security.aer_schedule_country_v1(v_cc)->>'reason', 'switched off') || '.', 'A Platform Admin switches the country on in Toolsets & limits.');
  end if;
  select count(*) into v_inflight from (
    select 1 from pipeline.entry_matrix_runs mr where mr.provider_id = v_pid and mr.state in ('queued', 'leased')
    union all select 1 from pipeline.entry_matrix_sources s where s.provider_id = v_pid and s.status in ('found', 'reading')
    union all select 1 from pipeline.field_enrich_items f where f.provider_id = v_pid and f.field = 'entry_requirements' and f.state in ('queued', 'waiting', 'ai', 'leased')) z;
  if v_inflight > 0 then
    return security.aer_read_now_out_v1('in_progress', 'work_in_flight', v_inflight || ' read(s) for this provider are already waiting or running. You can close this page: they carry on, and the stages below update.', 'The reader finishes them, then the rows wait in Layer 4 for a person.',
                                        '[]', jsonb_build_object('in_flight', v_inflight));
  end if;
  select count(*) filter (where packet_state = 'reviewer_ready'), count(*) filter (where packet_state = 'technical_hold'), count(*) filter (where packet_state = 'needs_input'), count(*) filter (where packet_state = 'not_checked'),
         array_agg(item_id order by created_at, item_id) filter (where packet_state = 'technical_hold' and field_code = 'course_entry_first_read')
    into v_ready, v_hold, v_input, v_chk, v_hold_ids from security.aer_pending_packets_v1(v_pid, null);  -- one scoped call; the held ids are passed down to the replay step below
  select count(*) into v_srcs from pipeline.entry_matrix_sources s where s.provider_id = v_pid;
  select coalesce(sum(x.course_reads + x.corrections), 0) into v_used from pipeline.aer_schedule_runs x where x.ran_at > now() - interval '1 day';  -- fixed: the daily cap is counted over the last 24 hours, reads and corrections together, as the scheduled reader counts it
  select coalesce(sum(coalesce((e.detail->>'course_reads')::int, 0) + coalesce((e.detail->>'rereads')::int, 0) + coalesce((e.detail->>'replays')::int, 0)), 0) into v_od from pipeline.admin_control_events e where e.area = 'aer_read_now' and e.created_at > now() - interval '1 day';  -- fixed: same window; course reads, source reads again and replays asked from here all count against the shared daily allowance
  select count(*), count(*) filter (where exists (select 1 from pipeline.work_items w where w.lane = 'aer_technical' and w.work_kind = 'l4_item' and w.entity = i.id::text and w.stage = 'parked' and w.unresolved_blocker->>'action' = 'park'))
    into v_l4, v_parked from pipeline.layer4_review_items i where i.status = 'pending' and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run');  -- fixed: the two kinds the scheduled reading counts
  select count(*) into v_prog from pipeline.field_enrich_items f where f.field = 'entry_requirements' and f.state in ('queued', 'waiting', 'ai', 'leased');

  -- (a) a source whose latest read failed technically is read again from its stored copy (not a held_unparsed source, not a markdown copy: those are fetched again by the entry reader under its own guard)
  for r in select s.id, s.url, lr.content_hash h from pipeline.entry_matrix_sources s
            join lateral (select * from pipeline.entry_matrix_runs mr where mr.source_id = s.id order by (mr.content_hash is not distinct from s.content_hash) desc, mr.created_at desc limit 1) lr on true
            left join pipeline.evidence_artifacts ev on ev.id = s.evidence_id
           where s.provider_id = v_pid and s.status = 'read' and lr.state = 'failed' and coalesce(lr.error, '') not like 'held%' and ev.storage_path is not null and coalesce(ev.mime_type, '') <> 'text/markdown'
              -- once asked from here for this page (same content hash) a failed read is not queued again before the retry interval (setting Entry requirements: retry days)
              and not exists (select 1 from pipeline.admin_control_events e where e.area = 'aer_read_now' and e.created_at > now() - make_interval(days => v_retry)
                                and e.detail->'started' @> jsonb_build_array(jsonb_build_object('kind', 'reread_source', 'source_id', s.id::text, 'content_hash', coalesce(lr.content_hash, ''))))
           order by s.read_at nulls first, s.id limit v_srcmax loop
    if not security.entry_matrix_enabled_v1(v_pid) then v_blocks := v_blocks || jsonb_build_array(jsonb_build_object('outcome', 'switch_off', 'reason', 'matrix_reader_off', 'text', 'The entry-matrix reader does not read this provider (settings Entry matrices: reader on and providers).')); exit;
    elsif v_aim is not null then v_blocks := v_blocks || jsonb_build_array(jsonb_build_object('outcome', 'budget_reached', 'reason', 'ai_stopped', 'text', 'AI reading of entry matrices is stopped (AI limits): ' || v_aim || '.')); exit;
    end if;
    v_actions := v_actions || jsonb_build_array(jsonb_build_object('kind', 'reread_source', 'source_id', r.id, 'url', r.url, 'content_hash', coalesce(r.h, '')));
  end loop;
  -- (b) held course reads that the stored records can replace (no AI, no fetch), within the replay switch, its per-provider and daily caps
  if v_hold > 0 then
    if not v_replay_on then v_blocks := v_blocks || jsonb_build_array(jsonb_build_object('outcome', 'switch_off', 'reason', 'replay_off', 'text', v_hold || ' held read(s) could be replaced from stored records, but that recovery is switched off (setting Entry requirements: recover held reads from stored records).'));
    elsif v_replay_left <= 0 then v_blocks := v_blocks || jsonb_build_array(jsonb_build_object('outcome', 'budget_reached', 'reason', 'replay_daily_cap', 'text', 'The daily allowance of replays from stored records is used.'));
    else
      v_n := 0;
      for r in select h.item_id from unnest(coalesce(v_hold_ids, '{}'::uuid[])) with ordinality h(item_id, ord) left join pipeline.aer_replay_checks k on k.item_id = h.item_id
                order by k.checked_at nulls first, h.ord limit v_replay_per loop
        p := security.aer_replay_plan_v1(r.item_id);
        if coalesce((p->>'ok')::boolean, false) and v_n < least(v_replay_per, v_replay_left) then
          v_actions := v_actions || jsonb_build_array(jsonb_build_object('kind', 'replay_item', 'item_id', r.item_id)); v_n := v_n + 1;
        end if;
      end loop;
    end if;
    if not v_e13_on and v_n = 0 then v_blocks := v_blocks || jsonb_build_array(jsonb_build_object('outcome', 'switch_off', 'reason', 'e13_recover_off', 'text', v_hold || ' read(s) are held by the completeness gate; a corrected read from the stored page needs the E13 recovery switch, which is off.')); end if;
  end if;
  -- (c) first reads of courses whose bound page is already stored (the scheduled reader's own population and function), within Layer 4 room, the daily cap, the AI guard and the credit floor
  select count(*) into v_elig from security.aer_course_population_v1(v_pid) q
   where not exists (select 1 from pipeline.field_enrich_items f where f.course_id = q.course_id and f.field = 'entry_requirements')
     and not exists (select 1 from pipeline.layer4_review_items i where i.entity_id = q.course_id and i.field_code = 'course_entry_first_read' and i.status = 'pending');
  if v_elig > 0 then
    v_room := least(v_per, v_daymax - v_used - v_od, v_l4max - (v_l4 - v_parked + v_prog));
    if v_ai is not null then v_blocks := v_blocks || jsonb_build_array(jsonb_build_object('outcome', 'budget_reached', 'reason', 'ai_stopped', 'text', 'AI reading is stopped (AI limits): ' || v_ai || '. ' || v_elig || ' course(s) are waiting to be read.'));
    elsif v_bal is not null and v_bal - least(v_per, v_elig) * v_cost < v_floor then v_blocks := v_blocks || jsonb_build_array(jsonb_build_object('outcome', 'budget_reached', 'reason', 'credit_floor', 'text', 'Reading courses would take the OpenRouter balance below its floor (Toolsets & limits).'));
    elsif v_daymax - v_used - v_od <= 0 then v_blocks := v_blocks || jsonb_build_array(jsonb_build_object('outcome', 'budget_reached', 'reason', 'daily_cap', 'text', 'The daily allowance of course reads (' || v_daymax || ') is used, scheduled and on demand together.'));
    elsif v_l4max - (v_l4 - v_parked + v_prog) <= 0 then v_blocks := v_blocks || jsonb_build_array(jsonb_build_object('outcome', 'human_review_required', 'reason', 'layer4_full', 'text', 'Layer 4 holds ' || (v_l4 - v_parked) || ' entry-requirement items for a person (limit ' || v_l4max || '). No new course read starts until decisions are made; ' || v_elig || ' course(s) of this provider are waiting.'));
    else
      select array_agg(q.course_id order by q.title, q.course_id) into v_pick from (
        select q0.course_id, q0.title from security.aer_course_population_v1(v_pid) q0
         where not exists (select 1 from pipeline.field_enrich_items f where f.course_id = q0.course_id and f.field = 'entry_requirements')
           and not exists (select 1 from pipeline.layer4_review_items i where i.entity_id = q0.course_id and i.field_code = 'course_entry_first_read' and i.status = 'pending')
         order by q0.title, q0.course_id limit v_room) q;
      if v_pick is not null then v_actions := v_actions || coalesce((select jsonb_agg(jsonb_build_object('kind', 'read_course', 'course_id', c)) from unnest(v_pick) c), '[]'::jsonb); end if;
    end if;
  end if;

  v_extra := jsonb_build_object('packets', jsonb_build_object('reviewer_ready', v_ready, 'technical_hold', v_hold, 'needs_input', v_input, 'not_checked', v_chk), 'courses_waiting_to_be_read', v_elig, 'sources', v_srcs, 'blocks', v_blocks);
  if jsonb_array_length(v_actions) > 0 then
    if not exists (select 1 from jsonb_array_elements(v_actions) x where x->>'kind' <> 'reread_source') then
      return security.aer_read_now_out_v1('queued', 'technical_failure_retry', jsonb_array_length(v_actions) || ' source(s) whose last read failed technically are read again from their stored copy. No fetch, no page search. Every result waits in Layer 4 for a person.', 'Watch the stages below, or open Layer 4 when rows arrive.', v_actions, v_extra);
    end if;
    return security.aer_read_now_out_v1('queued', 'work_started', 'Starting ' || jsonb_array_length(v_actions) || ' read(s) from what is already stored: no scraper, no page search. Every result waits in Layer 4 for a person.', 'Watch the stages below, or open Layer 4 when rows arrive.', v_actions, v_extra);
  end if;
  -- nothing to start: say exactly why, most specific first
  for r in select b->>'outcome' o, b from jsonb_array_elements(v_blocks) b order by array_position(array['switch_off', 'budget_reached', 'human_review_required', 'source_unavailable'], b->>'outcome') nulls last loop
    return security.aer_read_now_out_v1(r.o, r.b->>'reason', r.b->>'text', null, '[]', v_extra);
  end loop;
  if v_ready > 0 or v_input > 0 then
    return security.aer_read_now_out_v1('human_review_required', case when v_ready > 0 then 'packet_ready' else 'needs_input' end,
      case when v_ready > 0 then v_ready || ' complete reviewer packet(s) are waiting in Layer 4 for a person.' else v_input || ' waiting read(s) need input before a person can decide them.' end || ' Nothing is published until a person decides.', 'Open the items in Layer 4.', '[]', v_extra);
  end if;
  if v_srcs > 0 or v_hold > 0 or v_chk > 0 then
    if v_hold + v_chk > 0 then return security.aer_read_now_out_v1('in_progress', 'waiting_for_recovery', (v_hold + v_chk) || ' waiting read(s) are held by the completeness gate; automatic recovery handles them on its next run.', 'Job aer-replay and the gate run hourly.', '[]', v_extra); end if;
    -- what each source actually recorded (a source that is only waiting is "in flight" above). Only a source read by a finished run that kept no row is "read, nothing kept". A read the reader HELD (held_unparsed, held_incomplete, held: ...) found nothing absent: the reader could not read the page reliably.
    select count(*) filter (where s.status = 'failed') n_fail, count(*) filter (where s.status = 'robots_disallowed') n_robots,
           count(*) filter (where s.status = 'read' and lr.state = 'done' and coalesce(lr.rows_admitted, 0) = 0) n_none,
           count(*) filter (where s.status = 'read' and lr.state = 'done' and coalesce(lr.rows_admitted, 0) > 0) n_rows,
           count(*) filter (where s.status = 'read' and lr.state = 'failed' and lr.error like 'held%') n_held,
           count(*) filter (where s.status = 'read' and lr.state = 'failed' and coalesce(lr.error, '') not like 'held%') n_rfail,
           min(s.url) filter (where s.status = 'failed') u_fail, min(coalesce(s.error, '')) filter (where s.status = 'failed') e_fail, min(s.url) filter (where s.status = 'robots_disallowed') u_robots,
           min(s.url) filter (where s.status = 'read' and lr.state = 'done' and coalesce(lr.rows_admitted, 0) = 0) u_none,
           min(s.url) filter (where s.status = 'read' and lr.state = 'failed' and lr.error like 'held%') u_held, min(coalesce(lr.error, '')) filter (where s.status = 'read' and lr.state = 'failed' and lr.error like 'held%') e_held,
           min(s.url) filter (where s.status = 'read' and lr.state = 'failed' and coalesce(lr.error, '') not like 'held%') u_rfail, min(coalesce(lr.error, '')) filter (where s.status = 'read' and lr.state = 'failed' and coalesce(lr.error, '') not like 'held%') e_rfail
      into v_sn
      from pipeline.entry_matrix_sources s
      left join lateral (select mr.state, mr.rows_admitted, mr.error from pipeline.entry_matrix_runs mr where mr.source_id = s.id order by (mr.content_hash is not distinct from s.content_hash) desc, mr.created_at desc limit 1) lr on true
     where s.provider_id = v_pid and s.status <> 'inactive';
    v_extra := v_extra || jsonb_build_object('source_counts', jsonb_build_object('read_with_rows_kept', v_sn.n_rows, 'read_nothing_kept', v_sn.n_none, 'held_by_the_reader', v_sn.n_held, 'read_failed', v_sn.n_rfail, 'fetch_failed', v_sn.n_fail, 'robots_disallowed', v_sn.n_robots));
    if v_sn.n_fail > 0 then
      return security.aer_read_now_out_v1('source_unavailable', 'source_fetch_failed', v_sn.n_fail || ' source(s) could not be fetched or opened (first: ' || v_sn.u_fail || '; recorded: "' || coalesce(nullif(left(v_sn.e_fail, 120), ''), 'no reason recorded') || '"). The page is not stored, so there is nothing to read again from here.',
        'It is fetched again after ' || security.pipeline_num_v1('entry.matrix_refresh_days', 30)::int || ' days, or a person checks or replaces the page.', '[]', v_extra);
    end if;
    if v_sn.n_robots > 0 then
      return security.aer_read_now_out_v1('source_unavailable', 'robots_disallowed', v_sn.n_robots || ' source(s) are disallowed by the website''s robots.txt (first: ' || v_sn.u_robots || '). They are not fetched.', 'A person supplies the page another way, or leaves it.', '[]', v_extra);
    end if;
    if v_sn.n_held > 0 then
      return security.aer_read_now_out_v1('human_review_required', 'reader_held', v_sn.n_held || ' source(s) were read but the reader held them (first: ' || v_sn.u_held || '; recorded: "' || coalesce(nullif(left(v_sn.e_held, 120), ''), 'no reason recorded') || '"). The reader could not read the page reliably, so nothing is known about what it states.',
        'A reader change under change control, or a person supplying the table, reads it again. It is not read again against an unchanged page.', '[]', v_extra);
    end if;
    if v_sn.n_rfail > 0 then
      return security.aer_read_now_out_v1('no_eligible_work', 'technical_failure_retried', v_sn.n_rfail || ' source(s) have a read that failed technically (first: ' || v_sn.u_rfail || '; recorded: "' || coalesce(nullif(left(v_sn.e_rfail, 120), ''), 'no reason recorded') || '"). It is not asked again from here against an unchanged page.',
        'It is read again when the page changes, or after ' || v_retry || ' days if it was already asked from here. A person can use Read again under the advanced controls.', '[]', v_extra);
    end if;
    if v_sn.n_none > 0 then
      return security.aer_read_now_out_v1('already_up_to_date', 'tried_not_found', v_sn.n_none || ' source(s) were read to the end and no entry-requirement row was kept from them (first: ' || v_sn.u_none || '). An unchanged page is not read again, so nothing is spent.',
        'A person can correct or replace the page. It is fetched again after ' || security.pipeline_num_v1('entry.matrix_refresh_days', 30)::int || ' days and read again only if it changed.', '[]', v_extra);
    end if;
    return security.aer_read_now_out_v1('already_up_to_date', 'sources_read', 'Every source of this provider has been read on its current stored copy. A page that has not changed is not read again, so nothing is spent.', 'Pages are fetched again after ' || security.pipeline_num_v1('entry.matrix_refresh_days', 30)::int || ' days, and read again only if they changed.', '[]', v_extra);
  end if;
  select coalesce(f.evidence->>'route', 'not_classified') into v_route from pipeline.aer_gap_findings f where f.provider_id = v_pid and f.root_cause = 'no_source' and f.state <> 'resolved' order by f.last_seen desc limit 1;
  if v_route is null then return security.aer_read_now_out_v1('no_eligible_work', 'nothing_to_read', 'No source, matched course page or waiting read needs work for this provider right now.', null, '[]', v_extra); end if;
  return case v_route
    when 'source_page_stored' then security.aer_read_now_out_v1(case when v_sf_on then 'source_unavailable' else 'switch_off' end, case when v_sf_on then 'stored_page_not_yet_attached' else 'stored_find_off' end,
        case when v_sf_on then 'A stored link on the provider''s own website scores as its entry-requirements page, but it is not attached as a source yet.' else 'A stored link scores as the provider''s entry-requirements page, but attaching it is switched off (setting Entry pages from stored links: on).' end,
        'Job aer-source-stored-find attaches it on its next hourly run' || case when v_sf_on then '.' else ' once a Platform Admin switches it on.' end, '[]', v_extra)
    when 'course_pages_waiting' then security.aer_read_now_out_v1('no_eligible_work', 'courses_already_read', 'Every course page of this provider that can be read has been read or is waiting in Layer 4.', null, '[]', v_extra)
    when 'course_pages_unconfirmed' then security.aer_read_now_out_v1('source_unavailable', 'identity_not_admitted', 'Course pages are stored but matched to their courses by title only, which is not admitted for entry requirements (a Platform Admin decision is pending). None is read.', 'A Platform Admin decision, or a person confirms each course page.', '[]', v_extra)
    when 'source_page_host_shared' then security.aer_read_now_out_v1('source_unavailable', 'host_shared', 'A stored entry-requirements page exists, but its website is also used by another active provider, so it is not attached by itself.', 'A person confirms which provider the website and the page belong to.', '[]', v_extra)
    when 'weak_page_only' then security.aer_read_now_out_v1('source_unavailable', 'weak_page_only', 'Only a general entry-requirements page is stored, under the score for a suggestion.', 'Lower Find central pages: minimum score (not under 3), or a person confirms the page.', '[]', v_extra)
    when 'nothing_stored' then security.aer_read_now_out_v1('source_unavailable', 'nothing_stored', 'Nothing is stored to read: no entry-requirements link and no matched course page. A page search would use scraper credits, so it is not started from here.', 'A person adds the entry-requirements page, or a search is requested when the budget allows.', '[]', v_extra)
    else security.aer_read_now_out_v1('no_eligible_work', 'nothing_to_read', 'No source, matched course page or waiting read needs work for this provider right now.', null, '[]', v_extra) end;
end $$;


ALTER FUNCTION "security"."aer_read_now_plan_v1"("p_provider" "uuid", "p_course" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_read_now_plan_v1"("p_provider" "uuid", "p_course" "uuid") IS 'CF-247 AER read now (10 Nov 2026): what one click of Read / refresh entry requirements now would do for a provider or a course, or why it would do nothing, as one outcome (queued, in_progress, human_review_required, already_up_to_date, no_eligible_work, source_unavailable, switch_off, budget_reached) with a plain reason and the actions it would take. Reuses stored copies before any paid call; starts no scraper, no page search and no E13 AI re-read. Read only.';



CREATE OR REPLACE FUNCTION "security"."aer_read_now_source_v1"("p_provider" "uuid", "p_course" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare g record; v_list jsonb; v_n int;
begin
  if p_course is not null then
    select pg.url, pg.status, pg.identity_basis, a.captured_at, left(a.content_hash, 12) hash, (a.storage_path is not null) stored into g
      from pipeline.coverage_course_pages pg left join pipeline.evidence_artifacts a on a.id = pg.evidence_id where pg.course_id = p_course;
    if g.url is null then return jsonb_build_object('kind', 'course_page', 'recorded', false); end if;
    return jsonb_build_object('kind', 'course_page', 'recorded', true, 'url', g.url, 'binding', g.status, 'matched_by', g.identity_basis, 'stored', g.stored, 'captured_at', g.captured_at, 'content_hash', g.hash,
      'last_read', (select jsonb_build_object('state', f.state, 'recorded_reason', left(f.reason, 200), 'at', f.updated_at) from pipeline.field_enrich_items f
                     where f.course_id = p_course and f.field = 'entry_requirements' and f.state in ('review', 'filled', 'skipped', 'failed') order by f.id desc limit 1));
  end if;
  select count(*) into v_n from pipeline.entry_matrix_sources s where s.provider_id = p_provider;
  select coalesce(jsonb_agg(x.j order by x.rk nulls last, x.id), '[]'::jsonb) into v_list from (
    select s.id, s.rank rk, jsonb_build_object('url', s.url, 'status', s.status, 'http_status', s.http_status, 'read_at', s.read_at, 'stored', ev.storage_path is not null, 'content_hash', left(s.content_hash, 12), 'error', left(s.error, 160),
             'last_run', (select jsonb_build_object('state', mr.state, 'rows_kept', mr.rows_admitted, 'error', left(mr.error, 160), 'at', coalesce(mr.done_at, mr.updated_at))
                            from pipeline.entry_matrix_runs mr where mr.source_id = s.id order by (mr.content_hash is not distinct from s.content_hash) desc, mr.created_at desc limit 1)) j
      from pipeline.entry_matrix_sources s left join pipeline.evidence_artifacts ev on ev.id = s.evidence_id where s.provider_id = p_provider) x;
  return jsonb_build_object('kind', 'matrix_sources', 'recorded', v_n > 0, 'count', v_n, 'sources', v_list);
end $$;


ALTER FUNCTION "security"."aer_read_now_source_v1"("p_provider" "uuid", "p_course" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_read_now_source_v1"("p_provider" "uuid", "p_course" "uuid") IS 'CF-247 AER read now (10 Nov 2026, Operating Model v1.7): the source that was examined, exactly as the existing readers recorded it. For a course: the bound page, its binding and match basis, the stored copy and its hash, and the last read result. For a provider: each entry source with its status, http status, read time, stored copy and last run (rows kept, error). Read only; nothing is inferred and a missing record is reported as not recorded.';



CREATE OR REPLACE FUNCTION "security"."aer_read_now_status_v1"("p_provider" "uuid", "p_course" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_pid uuid; v_cid uuid; v_pname text; v_ctitle text; v_cc text; v_plan jsonb; v_stages jsonb; v_last jsonb; v_facts jsonb;
  v_src int := 0; v_stored int := 0; v_srcread int := 0; v_read_at timestamptz; v_pages int := 0; v_prop_m int := 0; v_prop_c int := 0; v_runs_done int := 0; v_runs_held int := 0;
  v_ready int := 0; v_hold int := 0; v_input int := 0; v_chk int := 0; v_act_m int := 0; v_act_c int := 0; v_approved int := 0; v_rejected int := 0; v_pub text; v_cls timestamptz;
  v_rr int := 0; v_rc int := 0; v_rf int := 0; v_rns jsonb := '{}'::jsonb; v_next timestamptz; v_ready_ids uuid[];
begin
  if p_course is not null then
    select c.id, c.provider_id, coalesce(c.display_title, c.canonical_title) into v_cid, v_pid, v_ctitle from catalogue.courses c where c.id = p_course;
  else v_pid := p_provider; end if;
  select coalesce(pv.display_name, pv.canonical_name), k.iso_alpha2::text, pv.publication_status into v_pname, v_cc, v_pub from catalogue.providers pv left join ref.countries k on k.id = pv.country_id where pv.id = v_pid;
  if v_pname is null then return jsonb_build_object('known', false, 'reason', 'That provider or course was not found.'); end if;
  v_plan := security.aer_read_now_plan_v1(v_pid, v_cid);
  select count(*) filter (where packet_state = 'reviewer_ready'), count(*) filter (where packet_state = 'technical_hold'), count(*) filter (where packet_state = 'needs_input'), count(*) filter (where packet_state = 'not_checked'), max(classified_at),
         array_agg(item_id) filter (where packet_state = 'reviewer_ready')
    into v_ready, v_hold, v_input, v_chk, v_cls, v_ready_ids from security.aer_pending_packets_v1(v_pid, v_cid);  -- one scoped call; the ready ids are passed to the facts check below
  -- facts of the reviewer-ready packets only (rows of a held packet are not yet a packet)
  select count(*), count(*) filter (where x.country <> 'not_stated' and x.qualification <> 'not_stated' and x.grade <> 'not_stated' and x.scale <> 'not_stated' and x.applicability <> 'not_stated' and x.source_page <> 'not_stated' and x.year <> 'not_stated'),
         jsonb_strip_nulls(jsonb_build_object('country', nullif(count(*) filter (where x.country = 'not_stated'), 0), 'qualification', nullif(count(*) filter (where x.qualification = 'not_stated'), 0), 'grade', nullif(count(*) filter (where x.grade = 'not_stated'), 0),
              'scale', nullif(count(*) filter (where x.scale = 'not_stated'), 0), 'applicability', nullif(count(*) filter (where x.applicability = 'not_stated'), 0), 'source_page', nullif(count(*) filter (where x.source_page = 'not_stated'), 0),
              'year', nullif(count(*) filter (where x.year = 'not_stated'), 0)))
    into v_rr, v_rc, v_rns
    from security.aer_packet_rows_v1(null) x
   where x.item_id = any (coalesce(v_ready_ids, '{}'::uuid[])) and (v_cid is null or x.course_id = v_cid) and (x.provider_id = v_pid);
  v_rf := v_rr - v_rc;
  if v_cid is null then
    select count(*), count(*) filter (where s.evidence_id is not null), count(*) filter (where s.status = 'read'), max(s.read_at) into v_src, v_stored, v_srcread, v_read_at from pipeline.entry_matrix_sources s where s.provider_id = v_pid;
    select count(*) into v_pages from pipeline.coverage_course_pages g join catalogue.courses c on c.id = g.course_id join pipeline.evidence_artifacts a on a.id = g.evidence_id and a.storage_path is not null
     where c.provider_id = v_pid and c.lifecycle_status = 'active' and g.status = 'bound';
    select count(*) into v_prop_m from catalogue.provider_entry_matrix m where m.provider_id = v_pid and m.status = 'proposed';
    select count(*) into v_prop_c from catalogue.course_entry_requirements q join catalogue.courses c on c.id = q.course_id where c.provider_id = v_pid and q.status = 'proposed';
    select count(*) filter (where r.state = 'done'), count(*) filter (where r.state = 'failed') into v_runs_done, v_runs_held from pipeline.entry_matrix_runs r where r.provider_id = v_pid;
    select count(*) into v_act_m from catalogue.provider_entry_matrix m where m.provider_id = v_pid and m.status = 'active';
    select count(*) into v_act_c from catalogue.course_entry_requirements q join catalogue.courses c on c.id = q.course_id where c.provider_id = v_pid and q.status = 'active';
    select count(*) filter (where i.status in ('approved', 'edited_approved')), count(*) filter (where i.status = 'rejected') into v_approved, v_rejected
      from pipeline.layer4_review_items i left join catalogue.courses c on i.entity_type = 'course' and c.id = i.entity_id
     where i.field_code = any (security.aer_review_kinds_v1()) and coalesce(c.provider_id, case when i.entity_type = 'provider' then i.entity_id end) = v_pid;
  else
    select count(*), count(*) filter (where a.storage_path is not null) into v_src, v_stored from pipeline.coverage_course_pages g left join pipeline.evidence_artifacts a on a.id = g.evidence_id where g.course_id = v_cid and g.status = 'bound';
    v_pages := v_src;
    select count(*) into v_prop_c from catalogue.course_entry_requirements q where q.course_id = v_cid and q.status = 'proposed';
    select count(*) filter (where f.state in ('review', 'filled', 'skipped')), count(*) filter (where f.state = 'failed') into v_runs_done, v_runs_held from pipeline.field_enrich_items f where f.course_id = v_cid and f.field = 'entry_requirements';
    select max(f.updated_at) into v_read_at from pipeline.field_enrich_items f where f.course_id = v_cid and f.field = 'entry_requirements' and f.state in ('review', 'filled', 'skipped');
    select count(*) into v_act_c from catalogue.course_entry_requirements q where q.course_id = v_cid and q.status = 'active';
    select count(*) filter (where i.status in ('approved', 'edited_approved')), count(*) filter (where i.status = 'rejected') into v_approved, v_rejected
      from pipeline.layer4_review_items i where i.entity_type = 'course' and i.entity_id = v_cid and i.field_code = 'course_entry_first_read';
  end if;
  select jsonb_build_object('event', e.id, 'at', e.created_at, 'by', e.actor, 'outcome', e.detail->>'outcome', 'reason', e.detail->>'reason', 'started', e.detail->'started', 'note', e.detail->>'note')
    into v_last from pipeline.admin_control_events e where e.area = 'aer_read_now' and e.target = coalesce(v_cid, v_pid)::text order by e.id desc limit 1;
  select security.cron_next_run_v1(j.schedule, now()) into v_next from cron.job j where j.jobname = 'aer-scheduled-read' and j.active;
  v_stages := jsonb_build_array(
    jsonb_build_object('key', 'source_found', 'label', 'Source found', 'state', case when v_cid is not null then case when v_stored > 0 then 'done' else 'none' end when v_src > 0 or v_pages > 0 then 'done' else 'none' end,
      'n', case when v_cid is not null then v_stored else v_src end, 'unit', case when v_cid is not null then 'stored course page' else 'entry source' end,
      'detail', case when v_cid is not null then case when v_stored > 0 then 'The official course page is stored and bound.' else 'No stored copy of an official course page.' end
                     else v_src || ' entry source(s), ' || v_stored || ' with a stored copy; ' || v_pages || ' bound course page(s) stored' || case when v_read_at is not null then '; last read ' || to_char(v_read_at at time zone 'Australia/Melbourne', 'DD Mon YYYY HH24:MI') else '' end end),
    jsonb_build_object('key', 'parsed', 'label', 'AI parsed candidates', 'state', case when v_prop_m + v_prop_c > 0 then 'done' when v_runs_done > 0 then 'partial' else 'none' end, 'n', v_prop_m + v_prop_c, 'unit', 'candidate row',
      'detail', (v_prop_m + v_prop_c) || ' candidate row(s) waiting (' || v_prop_m || ' university table, ' || v_prop_c || ' course); ' || v_runs_done || ' read(s) done' || case when v_runs_held > 0 then ', ' || v_runs_held || ' failed or held' else '' end || '. Candidates are not admissions.'),
    jsonb_build_object('key', 'packet', 'label', 'Complete reviewer packet', 'state', case when v_ready > 0 then 'done' when v_hold + v_input + v_chk > 0 then 'partial' else 'none' end, 'n', v_ready, 'unit', 'packet',
      'detail', v_ready || ' complete (' || v_rc || ' of ' || v_rr || ' rows state every fact' || case when v_rf > 0 then '; ' || v_rf || ' have a fact not stated, flagged for the reviewer' else '' end || '); ' || v_hold || ' held by the completeness gate, ' || v_input || ' need input, ' || v_chk || ' not checked yet.'),
    jsonb_build_object('key', 'human', 'label', 'Awaiting a person in Layer 4', 'state', case when v_ready > 0 then 'waiting' when v_approved + v_rejected > 0 then 'done' else 'none' end, 'n', v_ready, 'unit', 'decision',
      'detail', v_ready || ' packet(s) ready for a person to decide; ' || v_approved || ' approved and ' || v_rejected || ' rejected to date. Nothing is active until a person approves.'),
    jsonb_build_object('key', 'active', 'label', 'Approved and active', 'state', case when v_act_m + v_act_c > 0 then 'done' else 'none' end, 'n', v_act_m + v_act_c, 'unit', 'active row',
      'detail', v_act_m || ' university table row(s) and ' || v_act_c || ' course row(s) are active canonical rows.'),
    jsonb_build_object('key', 'consumer', 'label', 'Visible to the website', 'state', 'unknown', 'n', null, 'unit', null,
      'detail', 'Not measured for one ' || case when v_cid is null then 'provider' else 'course' end || ' here. Active rows reach the website when the ' || case when v_cid is null then 'provider' else 'course' end || ' is published' || case when v_pub is not null then ' (provider: ' || v_pub || ')' else '' end || '; the Website and Zoho read-back is in Operations › Data Delivery.'));
  return jsonb_build_object('known', true, 'scope', case when v_cid is null then 'provider' else 'course' end,
    'provider', jsonb_build_object('id', v_pid, 'name', v_pname, 'country', v_cc), 'course', case when v_cid is not null then jsonb_build_object('id', v_cid, 'title', v_ctitle) end,
    'stages', v_stages, 'outcome', (v_plan - 'actions' - 'blocks') || jsonb_build_object('class', security.aer_read_now_class_v1(v_plan->>'outcome', v_plan->>'reason')), 'source', security.aer_read_now_source_v1(v_pid, v_cid),
    'will_do', coalesce(v_plan->'actions', '[]'::jsonb),
    'blocks', (select coalesce(jsonb_agg(b || jsonb_build_object('class', security.aer_read_now_class_v1(b->>'outcome', b->>'reason'))), '[]'::jsonb) from jsonb_array_elements(coalesce(v_plan->'blocks', '[]'::jsonb)) b), 'last_request', v_last,
    'facts', jsonb_build_object('rows_in_reviewer_ready_packets', v_rr, 'rows_every_fact_stated', v_rc, 'rows_with_a_fact_not_stated', v_rf, 'not_stated', v_rns),
    'next_scheduled_read', v_next, 'packets_classified_at', v_cls, 'counted_at', now());
end $$;


ALTER FUNCTION "security"."aer_read_now_status_v1"("p_provider" "uuid", "p_course" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_read_now_status_v1"("p_provider" "uuid", "p_course" "uuid") IS 'CF-247 AER read now (10 Nov 2026): the stage timeline of one provider or course (source found, AI parsed candidates, complete reviewer packet, awaiting a person, approved and active, consumer visible) with counts from the existing tables, the facts check of the reviewer-ready packets, the last request and what the next click would do. Read only; a packet awaiting a person is never reported as published.';



CREATE OR REPLACE FUNCTION "security"."aer_read_now_v1"("p_provider" "uuid", "p_course" "uuid", "p_note" "text", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_key text := coalesce(p_course, p_provider)::text; v_plan jsonb; a jsonb; v_reason text; v_started jsonb := '[]'::jsonb; v_skipped jsonb := '[]'::jsonb; v_reads int := 0; v_rereads int := 0; v_replays int := 0; v_ev bigint; v_job uuid; v_res jsonb; v_out text; v_why text;
begin
  if p_provider is null and p_course is null then raise exception 'a provider or a course is required' using errcode = '22023'; end if;
  -- one click at a time for one scope: a second click waits here, then finds the first one's work in flight and starts nothing (idempotent)
  perform pg_advisory_xact_lock(hashtext('cf247:aer-read-now:' || v_key));
  v_reason := 'Read / refresh entry requirements now' || coalesce(' - ' || nullif(btrim(left(p_note, 300)), ''), '');
  v_plan := security.aer_read_now_plan_v1(p_provider, p_course);
  v_out := v_plan->>'outcome'; v_why := v_plan->>'reason';
  if v_out = 'queued' then
    for a in select x from jsonb_array_elements(v_plan->'actions') x loop
      begin
        if a->>'kind' = 'read_course' then
          v_job := security.course_entry_read_enqueue_v1((a->>'course_id')::uuid, p_actor, v_reason);
          v_started := v_started || jsonb_build_array(jsonb_build_object('kind', 'read_course', 'course_id', a->>'course_id', 'job_id', v_job, 'content_hash', coalesce(a->>'content_hash', ''))); v_reads := v_reads + 1;
        elsif a->>'kind' = 'reread_source' then
          v_res := security.aer_reread_v1((a->>'source_id')::uuid, v_reason, p_actor);
          v_started := v_started || jsonb_build_array(jsonb_build_object('kind', 'reread_source', 'source_id', a->>'source_id', 'run', v_res->>'run', 'content_hash', coalesce(a->>'content_hash', ''))); v_rereads := v_rereads + 1;
        elsif a->>'kind' = 'replay_item' then
          v_res := security.aer_replay_apply_v1((a->>'item_id')::uuid, security.aer_replay_plan_v1((a->>'item_id')::uuid));
          if not coalesce((v_res->>'applied')::boolean, false) then raise exception 'the replay was not applied: %', coalesce(v_res->>'why', 'refused'); end if;
          v_started := v_started || jsonb_build_array(jsonb_build_object('kind', 'replay_item', 'item_id', a->>'item_id', 'new_item', v_res->>'new_item', 'applied', v_res->'applied')); v_replays := v_replays + 1;
        end if;
      exception when others then
        v_skipped := v_skipped || jsonb_build_array(jsonb_build_object('action', a, 'why', left(sqlerrm, 300)));
      end;
    end loop;
    if jsonb_array_length(v_started) = 0 then
      v_out := 'no_eligible_work'; v_why := 'refused';
      v_plan := security.aer_read_now_out_v1(v_out, v_why, 'Nothing was started: ' || coalesce(v_skipped->0->>'why', 'the reader refused every request') || '.', null, '[]', jsonb_build_object('skipped', v_skipped));
    end if;
  end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('aer_read_now', case when p_course is not null then 'course' else 'provider' end, v_key,
          jsonb_build_object('outcome', v_out, 'reason', v_why, 'note', nullif(btrim(left(p_note, 300)), ''), 'course_reads', v_reads, 'rereads', v_rereads, 'replays', v_replays, 'started', v_started, 'skipped', v_skipped, 'provider_id', coalesce(p_provider, (select c.provider_id from catalogue.courses c where c.id = p_course))), p_actor)
  returning id into v_ev;
  return (v_plan - 'actions') || jsonb_build_object('outcome', v_out, 'reason', v_why, 'class', security.aer_read_now_class_v1(v_out, v_why), 'started', v_started, 'skipped', v_skipped, 'event', v_ev);
end $$;


ALTER FUNCTION "security"."aer_read_now_v1"("p_provider" "uuid", "p_course" "uuid", "p_note" "text", "p_actor" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_read_now_v1"("p_provider" "uuid", "p_course" "uuid", "p_note" "text", "p_actor" "uuid") IS 'CF-247 AER read now (10 Nov 2026): runs the plan of Read / refresh entry requirements now for one provider or course, once at a time (a second click starts nothing while work is in flight), through the existing functions only (course_entry_read_enqueue_v1, aer_reread_v1, aer_replay_apply_v1), and records one admin_control_events row (area aer_read_now). It approves, admits and publishes nothing: every result waits in Layer 4 for a person.';



CREATE OR REPLACE FUNCTION "security"."aer_read_supersession_close_v1"("p_id" "uuid", "p_state" "text", "p_why" "text", "p_new_item" "uuid", "p_diff" "jsonb") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  update pipeline.aer_read_supersessions set state = p_state, outcome = left(p_why, 500), new_item_id = p_new_item, diff = p_diff, closed_at = now()
   where id = p_id and state = 'requested'
$$;


ALTER FUNCTION "security"."aer_read_supersession_close_v1"("p_id" "uuid", "p_state" "text", "p_why" "text", "p_new_item" "uuid", "p_diff" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_read_supersession_close_v1"("p_id" "uuid", "p_state" "text", "p_why" "text", "p_new_item" "uuid", "p_diff" "jsonb") IS 'CF-247 D-R2: closes one requested correction as superseded (with the new item and diff) or refused (with the reason).';



CREATE OR REPLACE FUNCTION "security"."aer_read_supersessions_guard_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'DELETE' then raise exception 'D-R2 history is kept: a supersession record is never deleted' using errcode = '42501'; end if;
  if old.state <> 'requested' or new.state not in ('superseded', 'refused')
     or (new.id, new.old_item_id, new.course_id, new.source_url, new.old_evidence_id, new.enrich_item_id, new.job_id, new.requested_by, new.reason, new.requested_at)
        is distinct from (old.id, old.old_item_id, old.course_id, old.source_url, old.old_evidence_id, old.enrich_item_id, old.job_id, old.requested_by, old.reason, old.requested_at) then
    raise exception 'D-R2 history is kept: a supersession record moves once from requested to superseded or refused' using errcode = '42501';
  end if;
  return new;
end $$;


ALTER FUNCTION "security"."aer_read_supersessions_guard_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_reconcile_v1"("p_limit" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "statement_timeout" TO '120s'
    AS $_$
declare v_run bigint; v_lim int := coalesce(p_limit, security.pipeline_num_v1('batch.aer_reconcile', 5000)::int);
        v_found int; v_new int := 0; v_obs int := 0; v_res int := 0; v_reo int := 0; v_man int; v_day date; f record; v_ev jsonb; v_p0 int;
        v_alerts boolean := coalesce((security.toolset_setting('pipeline', 'aer.alerts_enabled') #>> '{}')::boolean, true);
        v_today int; v_prev int; v_reg int := security.pipeline_num_v1('aer.regression_alert_providers', 1)::int; v_out jsonb; v_week date; v_weekly text;
        v_first boolean; v_left jsonb; v_joined jsonb; v_qn int; v_pop jsonb;
begin
  -- single flight: a run already in progress is not started again
  if not pg_try_advisory_xact_lock(hashtext('aer-reconcile')) then  -- fixed: lock key
    return jsonb_build_object('skipped', 'another aer-reconcile run is in progress');
  end if;
  insert into pipeline.aer_reconcile_runs default values returning id into v_run;
  v_day := (now() at time zone 'Australia/Sydney')::date;  -- fixed: the mandate's reporting time zone

  -- 1 manifests: one per source and content hash, from the run already stored
  insert into pipeline.aer_source_manifests(source_id, provider_id, content_hash, run_id, run_state, basis, shape, heading, scope_country, scope_label,
                                            expected_cells, matched_cells, omitted_cells, omitted_columns, sections, reason)
  select s.id, s.provider_id, r.content_hash, r.id, r.state, coalesce(r.result->'completeness'->>'basis', r.result->>'page_basis', 'none'),
         security.aer_run_shape_v1(r.state, r.error, r.result->'completeness'->>'status', coalesce(r.result->>'page_basis', '')),
         left(coalesce(r.result->'completeness'->>'heading', substring(r.error from '\("([^"]{1,200})')), 200),
         (select k.iso_alpha2::text from ref.countries k where k.iso_alpha2 ~ '^[A-Z]{2}$' and lower(replace(coalesce(s.title, ''), '-', ' ')) like '%' || lower(k.name) || '%'
           order by length(k.name) desc limit 1),
         left(s.title, 200),
         nullif(r.result->'completeness'->>'expected', '')::int, nullif(r.result->'completeness'->>'matched', '')::int,
         jsonb_array_length(coalesce(r.result->'completeness'->'omitted', '[]'::jsonb)), coalesce(r.result->'completeness'->'omitted_columns', '[]'::jsonb),
         jsonb_build_object('omitted', coalesce(r.result->'completeness'->'omitted', '[]'::jsonb), 'unexplained', jsonb_array_length(coalesce(r.result->'completeness'->'unexplained', '[]'::jsonb)),
                            'completeness', r.result->'completeness'->>'status', 'rows_read', jsonb_array_length(coalesce(r.result->'rows', '[]'::jsonb))),
         left(coalesce(r.error, r.result->'completeness'->>'reason'), 400)
    from pipeline.entry_matrix_sources s
    join lateral (select r1.* from pipeline.entry_matrix_runs r1 where r1.source_id = s.id order by r1.created_at desc limit 1) r on true
   where r.state in ('done', 'failed')
  on conflict (source_id, content_hash) do update set run_id = excluded.run_id, run_state = excluded.run_state, basis = excluded.basis, shape = excluded.shape,
         heading = excluded.heading, expected_cells = excluded.expected_cells, matched_cells = excluded.matched_cells, omitted_cells = excluded.omitted_cells,
         omitted_columns = excluded.omitted_columns, sections = excluded.sections, reason = excluded.reason, computed_at = now()
   where aer_source_manifests.run_id is distinct from excluded.run_id or aer_source_manifests.run_state is distinct from excluded.run_state;
  get diagnostics v_man = row_count;

  -- 1b Layer 4 review readiness: every pending AER item has a row (awaiting_human_review until classified); settled items are closed, never reopened
  insert into pipeline.aer_review_readiness(review_item_id, field_code, entity_type, entity_id, provider_id, readiness, basis, item_status)
  select li.id, li.field_code, li.entity_type, li.entity_id, r.provider_id, 'awaiting_human_review', 'reconcile_default', li.status
    from pipeline.entry_matrix_runs r join pipeline.layer4_review_items li on li.id = r.review_item_id
   where li.status = 'pending' and li.field_code in ('entry_matrix_first_run', 'entry_matrix_change')
  union
  select li.id, li.field_code, li.entity_type, li.entity_id, o.provider_id, 'awaiting_human_review', 'reconcile_default', li.status
    from pipeline.aer_course_outcomes o join pipeline.layer4_review_items li on li.id = o.review_item_id
   where o.outcome = 'awaiting_review' and li.status = 'pending' and li.field_code = 'course_entry_first_read'
  on conflict (review_item_id) do nothing;
  update pipeline.aer_review_readiness z set item_status = li.status, settled_at = now(), updated_at = now()
    from pipeline.layer4_review_items li where li.id = z.review_item_id and z.settled_at is null and li.status <> 'pending';

  -- 2 the current findings
  if to_regclass('pg_temp.aer_cur') is null then
    create temp table aer_cur (fingerprint text primary key, root_cause text, provider_id uuid, source_id uuid, scope_kind text, scope_key text,
                               scope_label text, study_level text, evidence jsonb) on commit drop;
  end if;
  truncate pg_temp.aer_cur;
  insert into pg_temp.aer_cur select * from security.aer_current_findings_v1();
  get diagnostics v_found = row_count;

  -- 3a found again after it was resolved: reopened
  for f in update pipeline.aer_gap_findings g set state = 'reopened', resolved_at = null, reopen_count = g.reopen_count + 1, last_seen = now(), evidence = c.evidence,
                  last_run_id = v_run, closure_evidence = null
             from pg_temp.aer_cur c where c.fingerprint = g.fingerprint and g.state = 'resolved'
           returning g.id, g.fingerprint loop
    insert into pipeline.aer_gap_events(finding_id, fingerprint, event, run_id, detail) values (f.id, f.fingerprint, 'reopened', v_run, '{}'::jsonb);
    v_reo := v_reo + 1;
  end loop;
  -- 3b still there: observed (no event; nothing duplicated)
  update pipeline.aer_gap_findings g set last_seen = now(), evidence = c.evidence, last_run_id = v_run, scope_label = c.scope_label
    from pg_temp.aer_cur c where c.fingerprint = g.fingerprint and g.state in ('open', 'reopened') and g.last_run_id is distinct from v_run;
  get diagnostics v_obs = row_count;
  -- 3c new: opened (P0 first; at most batch.aer_reconcile a run)
  for f in insert into pipeline.aer_gap_findings(fingerprint, root_cause, provider_id, source_id, scope_kind, scope_key, scope_label, study_level, severity, evidence,
                                                 owner_role, next_action, last_run_id)
           select c.fingerprint, c.root_cause, c.provider_id, c.source_id, c.scope_kind, c.scope_key, c.scope_label, c.study_level, rc.severity, c.evidence,
                  rc.owner_role, rc.next_action, v_run
             from pg_temp.aer_cur c join pipeline.aer_gap_root_causes rc on rc.code = c.root_cause
            where not exists (select 1 from pipeline.aer_gap_findings g where g.fingerprint = c.fingerprint)
            order by rc.severity, c.root_cause, c.fingerprint
            limit greatest(v_lim, 0)
           returning id, fingerprint loop
    insert into pipeline.aer_gap_events(finding_id, fingerprint, event, run_id) values (f.id, f.fingerprint, 'opened', v_run);
    v_new := v_new + 1;
  end loop;
  -- 3d no longer found: resolved only with closure evidence
  for f in select g.id, g.fingerprint, g.root_cause, g.provider_id, g.source_id, g.study_level, g.scope_kind, g.scope_key from pipeline.aer_gap_findings g
            where g.state in ('open', 'reopened') and not exists (select 1 from pg_temp.aer_cur c where c.fingerprint = g.fingerprint) loop
    v_ev := security.aer_closure_evidence_v1(f.root_cause, f.provider_id, f.source_id, f.study_level, f.scope_kind, f.scope_key);
    if v_ev is not null then
      update pipeline.aer_gap_findings set state = 'resolved', resolved_at = now(), closure_evidence = v_ev, last_run_id = v_run where id = f.id;
      insert into pipeline.aer_gap_events(finding_id, fingerprint, event, run_id, detail) values (f.id, f.fingerprint, 'resolved', v_run, v_ev);
      v_res := v_res + 1;
    end if;
  end loop;

  -- 4 the daily snapshot (the last run of the day stands)
  insert into pipeline.aer_coverage_daily(day, country, eligible, discovery_n, extraction_n, admission_n, consumer_n, open_p0, open_p1, open_p2,
                                          new_findings, resolved_findings, reopened_findings, detail, run_id, computed_at)
  select v_day, m.country, m.eligible, m.discovery_n, m.extraction_n, m.admission_n, m.consumer_n,
         (select count(*) from pipeline.aer_gap_findings g join security.aer_eligible_v1() e on e.provider_id = g.provider_id
           where g.state <> 'resolved' and g.severity = 'P0' and (m.country = 'ALL' or e.country = m.country)),
         (select count(*) from pipeline.aer_gap_findings g join security.aer_eligible_v1() e on e.provider_id = g.provider_id
           where g.state <> 'resolved' and g.severity = 'P1' and (m.country = 'ALL' or e.country = m.country)),
         (select count(*) from pipeline.aer_gap_findings g join security.aer_eligible_v1() e on e.provider_id = g.provider_id
           where g.state <> 'resolved' and g.severity = 'P2' and (m.country = 'ALL' or e.country = m.country)),
         (select count(*) from pipeline.aer_gap_events x join pipeline.aer_gap_findings g on g.id = x.finding_id join security.aer_eligible_v1() e on e.provider_id = g.provider_id
           where x.event = 'opened' and (x.at at time zone 'Australia/Sydney')::date = v_day and (m.country = 'ALL' or e.country = m.country)),
         (select count(*) from pipeline.aer_gap_events x join pipeline.aer_gap_findings g on g.id = x.finding_id join security.aer_eligible_v1() e on e.provider_id = g.provider_id
           where x.event = 'resolved' and (x.at at time zone 'Australia/Sydney')::date = v_day and (m.country = 'ALL' or e.country = m.country)),
         (select count(*) from pipeline.aer_gap_events x join pipeline.aer_gap_findings g on g.id = x.finding_id join security.aer_eligible_v1() e on e.provider_id = g.provider_id
           where x.event = 'reopened' and (x.at at time zone 'Australia/Sydney')::date = v_day and (m.country = 'ALL' or e.country = m.country)),
         m.detail || jsonb_build_object('discovered_any', m.discovered_any, 'active_any', m.active_any), v_run, now()
    from security.aer_measures_v1() m
  on conflict (day, country) do update set eligible = excluded.eligible, discovery_n = excluded.discovery_n, extraction_n = excluded.extraction_n,
         admission_n = excluded.admission_n, consumer_n = excluded.consumer_n, open_p0 = excluded.open_p0, open_p1 = excluded.open_p1, open_p2 = excluded.open_p2,
         new_findings = excluded.new_findings, resolved_findings = excluded.resolved_findings, reopened_findings = excluded.reopened_findings,
         detail = excluded.detail, run_id = excluded.run_id, computed_at = excluded.computed_at;

  -- 4b the catalogue-first gap queue and the population against the baseline (exact providers that joined or left)
  v_first := not exists (select 1 from pipeline.aer_provider_coverage);
  if to_regclass('pg_temp.aer_prov') is null then
    create temp table aer_prov on commit drop as select * from security.aer_provider_states_v1() limit 0;
  end if;
  truncate pg_temp.aer_prov;
  insert into pg_temp.aer_prov select * from security.aer_provider_states_v1();
  select coalesce(jsonb_agg(c.provider_id order by c.provider_id), '[]'::jsonb) into v_left
    from pipeline.aer_provider_coverage c where c.eligible and not exists (select 1 from pg_temp.aer_prov x where x.provider_id = c.provider_id);
  select coalesce(jsonb_agg(x.provider_id order by x.provider_id), '[]'::jsonb) into v_joined
    from pg_temp.aer_prov x where not exists (select 1 from pipeline.aer_provider_coverage c where c.provider_id = x.provider_id and c.eligible);
  update pipeline.aer_provider_coverage c set eligible = false, last_run_id = v_run, updated_at = now()
   where c.eligible and not exists (select 1 from pg_temp.aer_prov x where x.provider_id = c.provider_id);
  insert into pipeline.aer_provider_coverage as c (provider_id, provider_name, country, provider_type, eligible, disposition, discovery_state, extraction_state, admission_state,
         consumer_resolvable, priority_tier, priority_rank, courses_eligible, sources, sources_read, sources_failed, runs_held, runs_failed, matrix_active, matrix_other,
         course_req_active, course_req_proposed, layer4, held_scopes, root_causes, evidence, last_run_id)
  select x.provider_id, x.provider_name, x.country, x.provider_type, true, x.disposition, x.discovery_state, x.extraction_state, x.admission_state, x.consumer_resolvable,
         x.priority_tier, x.priority_rank, x.courses_eligible, x.sources, x.sources_read, x.sources_failed, x.runs_held, x.runs_failed, x.matrix_active, x.matrix_other,
         x.course_req_active, x.course_req_proposed, x.layer4, x.held_scopes, x.root_causes, x.evidence, v_run
    from pg_temp.aer_prov x
  on conflict (provider_id) do update set provider_name = excluded.provider_name, country = excluded.country, provider_type = excluded.provider_type, eligible = true,
         previous_disposition = case when c.disposition <> excluded.disposition then c.disposition else c.previous_disposition end,
         disposition_since = case when c.disposition <> excluded.disposition then now() else c.disposition_since end,
         disposition = excluded.disposition, discovery_state = excluded.discovery_state, extraction_state = excluded.extraction_state, admission_state = excluded.admission_state,
         consumer_resolvable = excluded.consumer_resolvable, priority_tier = excluded.priority_tier, priority_rank = excluded.priority_rank, courses_eligible = excluded.courses_eligible,
         sources = excluded.sources, sources_read = excluded.sources_read, sources_failed = excluded.sources_failed, runs_held = excluded.runs_held, runs_failed = excluded.runs_failed,
         matrix_active = excluded.matrix_active, matrix_other = excluded.matrix_other, course_req_active = excluded.course_req_active, course_req_proposed = excluded.course_req_proposed,
         layer4 = excluded.layer4, held_scopes = excluded.held_scopes, root_causes = excluded.root_causes, evidence = excluded.evidence, last_run_id = v_run, updated_at = now();
  get diagnostics v_qn = row_count;
  v_pop := jsonb_build_object(
    'by_country', (select coalesce(jsonb_object_agg(b->>'country', jsonb_build_object('eligible', (select count(*) from pg_temp.aer_prov x where x.country = b->>'country'),
                     'baseline', (b->>'providers')::int, 'delta', (select count(*) from pg_temp.aer_prov x where x.country = b->>'country') - (b->>'providers')::int)), '{}'::jsonb)
                     from jsonb_array_elements(coalesce(security.toolset_setting('pipeline', 'aer.baseline_eligible'), '[]'::jsonb)) b),
    'eligible', (select count(*) from pg_temp.aer_prov),
    'first_run', v_first,
    'joined', case when v_first then null else v_joined end, 'left', v_left,
    'dispositions', (select coalesce(jsonb_object_agg(z.disposition, z.n), '{}'::jsonb) from (select x.disposition, count(*) n from pg_temp.aer_prov x group by 1) z));

  -- 5 alerts through the existing Platform health issues and alert job (one issue per check; recovery when it clears)
  select count(*) into v_p0 from pipeline.aer_gap_findings g where g.state <> 'resolved' and g.severity = 'P0';
  select d.consumer_n into v_today from pipeline.aer_coverage_daily d where d.day = v_day and d.country = 'ALL';
  select d.consumer_n into v_prev from pipeline.aer_coverage_daily d where d.day < v_day and d.country = 'ALL' order by d.day desc limit 1;
  if v_alerts and v_p0 > 0 then
    insert into pipeline.platform_issues as i (check_key, severity, area, title, detail)
    values ('aer:p0', 'critical', 'admission', left('Academic entry requirements: ' || v_p0 || ' critical consumer data finding(s)', 300),
            jsonb_build_object('findings', v_p0, 'root_causes', (select jsonb_object_agg(z.root_cause, z.n) from (select g.root_cause, count(*) n from pipeline.aer_gap_findings g
                                 where g.state <> 'resolved' and g.severity = 'P0' group by 1) z),
                               'next_step', 'Quarantine the rows named on Coverage & completeness › Academic entry requirements and send them through Layer 4',
                               'resolve', 'Coverage & completeness › Attributes › Academic entry requirements'))
    on conflict (check_key) where resolved_at is null do update set severity = excluded.severity, title = excluded.title, detail = excluded.detail,
      last_seen = now(), occurrences = i.occurrences + 1;
  else
    update pipeline.platform_issues set resolved_at = now() where check_key = 'aer:p0' and resolved_at is null;
  end if;
  if v_alerts and v_prev is not null and v_prev - coalesce(v_today, 0) >= v_reg then
    insert into pipeline.platform_issues as i (check_key, severity, area, title, detail)
    values ('aer:regression', 'critical', 'admission', left('Academic entry requirements: consumer-resolvable providers fell from ' || v_prev || ' to ' || coalesce(v_today, 0), 300),
            jsonb_build_object('yesterday', v_prev, 'today', v_today, 'threshold', v_reg,
                               'next_step', 'Find the providers that stopped resolving on Coverage & completeness › Academic entry requirements',
                               'resolve', 'Coverage & completeness › Attributes › Academic entry requirements'))
    on conflict (check_key) where resolved_at is null do update set title = excluded.title, detail = excluded.detail, last_seen = now(), occurrences = i.occurrences + 1;
  else
    update pipeline.platform_issues set resolved_at = now() where check_key = 'aer:regression' and resolved_at is null;
  end if;

  -- 6 the Monday report through the existing alert delivery (off until the destination is confirmed, D-A7); once a week
  v_week := date_trunc('week', now() at time zone 'Australia/Sydney')::date;  -- fixed: Monday-to-Sunday weeks
  if coalesce((security.toolset_setting('pipeline', 'aer.weekly_email_enabled') #>> '{}')::boolean, false)
     and extract(isodow from now() at time zone 'Australia/Sydney') = 1
     and extract(hour from now() at time zone 'Australia/Sydney') >= security.pipeline_num_v1('aer.weekly_send_hour', 8) then
    v_weekly := security.aer_weekly_text_v1(security.aer_weekly_section_v1(v_week - 7));  -- fixed: the week just ended
    perform security.platform_alerts_add_v1(null, 'aer:weekly', 'raised', 'info', '[StudySearch] AER weekly report, week of ' || to_char(v_week - 7, 'DD Mon YYYY'),
                                            v_weekly, 'aer:weekly:' || v_week::text);
  end if;

  -- 7 the health page row and the run record
  update pipeline.platform_health_checks set status = case when v_p0 > 0 or exists (select 1 from pipeline.platform_issues p where p.check_key = 'aer:regression' and p.resolved_at is null)
                                                          then 'critical' else 'ok' end,
         detail = jsonb_build_object('open', (select jsonb_object_agg(z.severity, z.n) from (select g.severity, count(*) n from pipeline.aer_gap_findings g where g.state <> 'resolved' group by 1) z),
                                     'consumer_providers', v_today, 'run_id', v_run), checked_at = now()
   where key = 'aer';
  v_out := jsonb_build_object('run_id', v_run, 'manifests', v_man, 'found', v_found, 'opened', v_new, 'observed', v_obs, 'resolved', v_res, 'reopened', v_reo,
                              'open', coalesce((select jsonb_object_agg(z.severity, z.n) from (select g.severity, count(*) n from pipeline.aer_gap_findings g where g.state <> 'resolved' group by 1) z), '{}'::jsonb),
                              'held_back', greatest(0, (select count(*) from pg_temp.aer_cur c where not exists (select 1 from pipeline.aer_gap_findings g where g.fingerprint = c.fingerprint))),
                              'day', v_day, 'queue_rows', v_qn, 'population', v_pop);
  update pipeline.aer_reconcile_runs set finished_at = now(), result = v_out where id = v_run;
  return v_out;
end $_$;


ALTER FUNCTION "security"."aer_reconcile_v1"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_reconcile_v1"("p_limit" integer) IS 'CF-247 AER Phase B (mandate §11, §14 hourly; B3): job aer-reconcile. Read-only over the AER data (sources, runs, rows, Layer 4, course outcomes): writes only the AER assurance tables, the aer:* Platform health issues and the aer health row. Manifests from stored runs; findings deduplicated by fingerprint; resolved only with closure evidence; reopened when found again; the daily four-measure snapshot; P0 and regression issues for the existing alert job; the Monday report when aer.weekly_email_enabled is on. No AI, no fetch. Single flight.';



CREATE OR REPLACE FUNCTION "security"."aer_recovery_report_v1"("p_since" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with s as (select s.*, fe.cost_usd, fe.evidence_id ev from pipeline.aer_read_supersessions s left join pipeline.field_enrich_items fe on fe.id = s.enrich_item_id where s.requested_at >= p_since),
       rep as (select s.id from s where s.state = 'refused' and exists (select 1 from pipeline.aer_read_supersessions p left join pipeline.field_enrich_items pf on pf.id = p.enrich_item_id
                 where p.old_item_id = s.old_item_id and p.state = 'refused' and p.requested_at < s.requested_at and pf.evidence_id is not distinct from s.ev)),
       w as (select * from pipeline.work_items where lane = 'aer_technical' and work_kind = 'l4_item')
  select jsonb_build_object('since', p_since,
    'corrected_reads_asked', (select count(*) from s), 'unique_items', (select count(distinct old_item_id) from s),
    'replaced', (select count(*) from s where s.state = 'superseded'), 'refused', (select count(*) from s where s.state = 'refused'),
    'waiting', (select count(*) from s where s.state = 'requested'), 'repeats_on_unchanged_copy', (select count(*) from rep),
    'ai_cost_usd', (select round(coalesce(sum(s.cost_usd), 0), 4) from s),
    'holds_by_class', (select jsonb_object_agg(k, n) from (select coalesce(w.unresolved_blocker->>'class', w.failure_class) k, count(*) n from w where w.stage <> 'done' group by 1) z),
    'holds_without_next', (select count(*) from w where w.stage in ('parked', 'retry_wait', 'deferred', 'quarantined') and coalesce(w.unresolved_blocker->>'next_action', '') = ''),
    'duplicates', (select count(*) from w where w.failure_class = 'duplicate' and w.stage = 'parked'),
    'human', (select count(*) from w where w.stage = 'awaiting_review' or w.failure_class = 'aer_human_input'),
    'deterministic_parked', (select count(*) from w where w.failure_class in ('aer_row_limit', 'aer_unchanged_evidence') and w.stage = 'parked'),
    'eligible_for_a_read', (select count(*) from w where w.failure_class = 'aer_reread_eligible' and w.stage <> 'done'),
    'recovered', (select count(*) from w where w.recovered_at >= p_since),
    'review_ready_replacements', (select count(*) from s join pipeline.layer4_review_items n on n.id = s.new_item_id where n.status = 'pending'),
    'active_rows_gained', (select count(*) from catalogue.course_entry_requirements x where x.status = 'active' and x.updated_at >= p_since
                            and x.provenance->>'review_item_id' in (select s.new_item_id::text from s where s.new_item_id is not null)),
    'published_courses_gained', (select count(distinct x.course_id) from catalogue.course_entry_requirements x join search.course_documents d on d.course_id = x.course_id
                                  where x.status = 'active' and x.updated_at >= p_since and x.provenance->>'review_item_id' in (select s.new_item_id::text from s where s.new_item_id is not null)))
$$;


ALTER FUNCTION "security"."aer_recovery_report_v1"("p_since" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_recovery_rule_v1"("p_item" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.layer4_review_items; x pipeline.layer4_item_readiness; rt jsonb; v_cls text; v_rep jsonb; v_pid uuid; v_pg record; v_iv record; v_lock boolean := false; v_lockd text;
        v_busy text; v_set_at timestamptz; v_rev numeric := security.pipeline_num_v1('layer4.reader_revision', 1); v_class text; v_next text; v_at timestamptz;
        v_auth text; v_why text; v_last record; v_moved boolean := false; v_active boolean := true; v_tick timestamptz; v_need int := 0; v_rlim int; v_now int;
begin
  select * into r from pipeline.layer4_review_items where id = p_item;
  if r.id is null or r.status <> 'pending' or r.field_code not in ('course_entry_first_read', 'entry_matrix_first_run', 'entry_matrix_change') then
    return jsonb_build_object('item', p_item, 'class', 'closed', 'technical', false);
  end if;
  select * into x from pipeline.layer4_item_readiness where item_id = p_item;
  -- every record exists before it is read (a record not yet assigned cannot be referenced)
  select null::text url, null::uuid evidence_id into v_pg;
  select null::uuid id, null::text state, null::text outcome, null::timestamptz requested_at, null::timestamptz closed_at into v_last;
  rt := security.aer_route_v1(r.field_code, x.gate); v_cls := rt->>'class';
  -- the settings that change a read (layer4.reread_change_keys): when the newest of them changed
  select max(t.updated_at) into v_set_at from pipeline.platform_toolset_settings t
   where t.toolset_key = 'pipeline' and exists (select 1 from jsonb_array_elements_text(coalesce((select w.value from pipeline.platform_toolset_settings w
          where w.toolset_key = 'pipeline' and w.key = 'layer4.reread_change_keys'), '["entry.%", "layer4.reader_revision"]'::jsonb)) k where t.key like k);
  v_tick := date_trunc('hour', now()) + interval '13 minutes';  -- fixed: aer-scheduled-read runs at minute 13 (its cron schedule)
  if v_tick <= now() then v_tick := v_tick + interval '1 hour'; end if;  -- fixed: the next hourly run
  if r.field_code = 'course_entry_first_read' then
    select c.provider_id, c.lifecycle_status = 'active' act into v_pid, v_active from catalogue.courses c where c.id = r.entity_id;
    select pg.url, pg.evidence_id into v_pg from pipeline.coverage_course_pages pg where pg.course_id = r.entity_id;
    v_moved := v_pg.url is distinct from r.proposed_value->>'url';
    v_lock := exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = r.entity_id and l.field = 'entry_requirements');
    -- 9 Nov 2026 (AER lock agreement): the locks D-R2 refuses a corrected read for (setting entry.supersede_lock_fields, read the same way as in D-R2)
    v_lockd := (select string_agg(l.field, ', ' order by l.field) from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = r.entity_id
                   and l.field in (select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'entry.supersede_lock_fields'), '[]'::jsonb))));
    v_busy := case when exists (select 1 from pipeline.aer_read_supersessions s where s.old_item_id = p_item and s.state = 'requested') then 'a corrected read of this item is waiting for the reader'
                   when exists (select 1 from pipeline.field_enrich_items f where f.course_id = r.entity_id and f.field = 'entry_requirements' and f.state in ('queued', 'waiting', 'ai', 'leased'))
                     then 'a read of this course is in progress' end;
    v_rep := security.layer4_reread_repeat_v1(p_item);
    -- 7 Nov 2026 (AER technical holds): what a row-limit cut needs to be read whole, and the limit it was cut under
    v_need := greatest(coalesce((r.proposed_value->>'rows')::int, 0) + coalesce((x.gate->>'rows_cut')::int, 0),
                       coalesce((select max(jsonb_array_length(e.value->'rows_read')) from pipeline.field_enrich_items e
                                  where e.course_id = r.entity_id and e.field = 'entry_requirements' and e.value ? 'rows_read'), 0));
    v_rlim := greatest(coalesce((r.proposed_value->>'limit')::int, 0),
                       coalesce((select max((e.value->>'limit')::int) from pipeline.field_enrich_items e
                                  where e.course_id = r.entity_id and e.field = 'entry_requirements' and e.value ? 'limit'), 0));
    v_now := security.course_entry_max_rows_v1(v_pid);
    select s.id, s.state, s.outcome, s.requested_at, s.closed_at into v_last from pipeline.aer_read_supersessions s where s.old_item_id = p_item order by s.requested_at desc limit 1;
  else
    v_pid := r.entity_id; v_rep := jsonb_build_object('repeat', false);
  end if;
  select i.id, i.missing_fact, i.status into v_iv from pipeline.layer4_interventions i
   where i.status in ('ai_pending', 'awaiting_input', 'resuming')
     and (i.entity = p_item::text or (r.field_code <> 'course_entry_first_read' and i.provider_id = v_pid and i.lane = 'aer_source' and i.missing_fact = 'aer_read_held'))
   order by i.id desc limit 1;
  v_class := case
    when x.gate is null then 'unchecked'
    when r.field_code = 'course_entry_first_read' and (not coalesce(v_active, true) or v_moved) then 'stale'
    when v_cls = 'complete' then 'ready'
    when rt->>'route' in ('review_except', 'matrix_except') then 'decision'
    when v_lock then 'human_assisted'
    when v_busy is not null then 'transient'
    when v_iv.id is not null then 'human_assisted'
    when rt->>'route' in ('identity', 'matrix_source') then 'human_assisted'
    when v_last.state = 'refused' and coalesce(v_last.outcome, '') ilike '%proof does not admit%' and coalesce((v_rep->>'repeat')::boolean, false) then 'human_assisted'
    -- 7 Nov 2026 (AER technical holds): only a row limit that now fits the read, above the limit it was cut under, makes a cut read eligible
    when v_cls = 'row_limit' and v_now >= v_need and v_now > coalesce(nullif(v_rlim, 0), (r.proposed_value->>'rows')::int, 0) then 'changed_conditions'
    when v_cls = 'row_limit' then 'row_limit'
    when v_cls = 'drops_uncovered' and coalesce((v_rep->>'repeat')::boolean, false) and coalesce((v_rep->>'row_limit')::boolean, false) then 'row_limit'
    when v_cls = 'drops_uncovered' and coalesce((v_rep->>'repeat')::boolean, false) then 'unchanged_evidence'
    when v_cls = 'drops_uncovered' and v_last.state = 'refused' then 'changed_conditions'
    when v_cls = 'drops_uncovered' and v_pg.evidence_id is null then 'human_assisted'
    when v_cls = 'drops_uncovered' then 'reread_eligible'
    else 'human_assisted' end;
  -- 9 Nov 2026 (AER lock agreement): D-R2 refuses a corrected read while the course has a manual lock on a field of entry.supersede_lock_fields, so the rule does not
  -- make such a read eligible (the lock is not removed or bypassed). Only the two eligible classes change; v_lockd is kept only when it changed the class.
  if v_lockd is not null and v_class in ('reread_eligible', 'changed_conditions') then v_class := 'human_assisted'; else v_lockd := null; end if;
  v_auth := case when v_class = 'row_limit' then 'a row limit of at least ' || greatest(v_need, 1) || ' for this university (entry.max_rows_by_provider, Platform Admin)' end;
  v_why := case v_class
    when 'row_limit' then 'the page has more requirements than the row limit (' || coalesce(security.pipeline_num_v1('entry.max_rows_per_course', 6)::text, '6')
                          || '); a read under the same limit is cut again' || coalesce('; ' || (v_rep->>'why'), '')
    when 'unchanged_evidence' then v_rep->>'why'
    when 'transient' then v_busy
    when 'stale' then case when not coalesce(v_active, true) then 'the course is no longer active' else 'the course is now bound to another page: a new first read, not a correction' end
    when 'human_assisted' then case when v_lock then 'the course''s entry requirements are locked by hand'
                                    when v_lockd is not null then 'a manual lock on the course''s ' || v_lockd || ' stops a corrected read (D-R2, entry.supersede_lock_fields)'
                                    when v_iv.id is not null then 'Human input needed item ' || v_iv.id || ' (' || v_iv.missing_fact || ') waits for a person'
                                    when rt->>'route' = 'identity' or coalesce(v_last.outcome, '') ilike '%proof does not admit%' then 'the stored page is not proven to be this course''s own page'
                                    when rt->>'route' = 'matrix_source' then 'the university''s matrix source dropped published rows or values'
                                    else 'the page has no stored copy to read again' end
    else null end;
  v_next := case v_class
    when 'ready' then 'a person decides it in Layer 4'
    when 'decision' then 'a person leaves out the named rows (Approve except) or rejects the read in Layer 4'
    when 'unchecked' then 'job layer4-readiness gates it (never-gated items first)'
    when 'stale' then 'a person rejects the read; the course is read again from its bound page'
    when 'transient' then 'wait for the read in progress; checked again with bounded retries'
    when 'row_limit' then 'the Platform Admin sets a row limit for this university; the item is reconsidered by itself when an entry setting changes'
    when 'unchanged_evidence' then 'none until the stored copy, the reader (layer4.reader_revision) or an entry setting changes; then reconsidered by itself'
    when 'changed_conditions' then 'one corrected read by the scheduled entry reading (aer-scheduled-read), within its daily cap'
    when 'reread_eligible' then 'one corrected read by the scheduled entry reading (aer-scheduled-read), within its daily cap'
    when 'human_assisted' then case when v_lock then 'a Platform Admin lifts the lock, or the read is left'
                                    when v_lockd is not null then 'a person rejects or decides the waiting read in Layer 4, or a Platform Admin lifts the lock (a lock is never bypassed)'
                                    when v_iv.id is not null then 'answer Human input needed item ' || v_iv.id
                                    when rt->>'route' = 'matrix_source' then 'Human-assisted recovery''s provider-level item for the source (aer_read_held), then the matrix re-read'
                                    when v_pg.evidence_id is null and r.field_code = 'course_entry_first_read' and v_cls = 'drops_uncovered' then 'the course page is read again (a stored copy is kept), then a corrected read'
                                    else 'job layer4-interventions raises one item asking which programme the page belongs to (aer_course_identity)' end end;
  v_at := case when v_class in ('reread_eligible', 'changed_conditions') then v_tick
               when v_class = 'unchecked' then date_trunc('hour', now()) + case when extract(minute from now()) < 22 then interval '22 minutes' when extract(minute from now()) < 52 then interval '52 minutes' else interval '82 minutes' end  -- fixed: layer4-readiness runs at :22 and :52
               when v_class = 'transient' then now() + make_interval(mins => security.work_backoff_minutes_v1(1)::int) end;
  return jsonb_build_object('item', p_item, 'field_code', r.field_code, 'provider_id', v_pid, 'class', v_class, 'gate_class', v_cls, 'route', rt->>'route',
    'technical', v_class not in ('ready', 'decision', 'closed'), 'eligible', v_class in ('reread_eligible', 'changed_conditions'),
    'deterministic', v_class in ('row_limit', 'unchanged_evidence'),
    'last_attempt', case when v_last.id is not null then jsonb_build_object('request', v_last.id, 'state', v_last.state, 'outcome', v_last.outcome,
                         'at', coalesce(v_last.closed_at, v_last.requested_at)) end,
    'evidence_used', v_rep->>'evidence_used', 'evidence_now', coalesce(v_pg.evidence_id::text, v_rep->>'evidence_now'), 'reader_revision', v_rev,
    'settings_changed_at', v_set_at, 'settings_changed', v_rep->'settings_changed', 'next_action', v_next, 'next_at', v_at, 'authority', v_auth,
    'retry_prohibited', case when v_class in ('row_limit', 'unchanged_evidence') then coalesce(v_why, 'deterministic') end, 'why', v_why,
    'intervention', v_iv.id, 'rows_needed', case when v_need > 0 then v_need end, 'row_limit_read_under', nullif(v_rlim, 0), 'row_limit_now', v_now,
    'condition_key', md5(concat_ws('|', v_class, coalesce(v_pg.evidence_id::text, '-'), v_rev::text, coalesce(v_set_at::text, '-'), coalesce(v_iv.id::text, '-'),
                                   coalesce(v_last.id::text || ':' || v_last.state, '-'), coalesce(v_cls, '-'), v_lock::text, coalesce(v_busy, '-'), v_lockd)));
end $$;


ALTER FUNCTION "security"."aer_recovery_rule_v1"("p_item" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_recovery_rule_v1"("p_item" "uuid") IS 'CF-247 AER recovery rule: the recovery class of one waiting AER item, from existing records. A course with a manual lock on a field of entry.supersede_lock_fields (the locks D-R2 refuses a corrected read for) is human_assisted, never eligible, so the held step does not scan it and the measure does not count it (9 Nov 2026).';



CREATE OR REPLACE FUNCTION "security"."aer_replay_apply_v1"("p_item" "uuid", "p_plan" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare p jsonb := coalesce(p_plan, security.aer_replay_plan_v1(p_item)); r pipeline.layer4_review_items; v_job uuid; v_enrich bigint; v_sup uuid; v_res text; v_new uuid; v_state text;
begin
  if not coalesce((p->>'ok')::boolean, false) then return jsonb_build_object('item', p_item, 'applied', false, 'why', p->>'why'); end if;
  -- live: pipeline.admin_jobs.requested_by is not null; the job is the platform's own, so it is requested by the system identity (the same one the other scheduled jobs use)
  if security.system_actor_id() is null then return jsonb_build_object('item', p_item, 'applied', false, 'why', 'no system identity (security.system_actor_id) to request the replay job'); end if;
  select * into r from pipeline.layer4_review_items where id = p_item for update;
  insert into pipeline.admin_jobs(kind, lane, state, title, args, progress, requested_by, reason, scope)
  values ('enrich_fields', 'enrich', 'done', left('Entry requirements · replay of the stored read of item ' || p_item, 200),
          jsonb_build_object('replay', true, 'entry_read', true, 'ai', false, 'scraper', false, 'provider_ids', jsonb_build_array(p->>'provider_id'), 'course_ids', jsonb_build_array(p->>'course_id'),
                             'fields', jsonb_build_array('entry_requirements')),
          jsonb_build_object('done', 1, 'total', 1), security.system_actor_id(), 'Replay of stored read for Layer 4 item ' || p_item || ' (no AI read): ' || (p->>'source'), '1 course')
  returning id into v_job;
  insert into pipeline.field_enrich_items(job_id, provider_id, course_id, field, state, reason)
  values (v_job, (p->>'provider_id')::uuid, (p->>'course_id')::uuid, 'entry_requirements', 'skipped', 'replay of a stored read: no AI')
  returning id into v_enrich;
  insert into pipeline.aer_read_supersessions(old_item_id, course_id, source_url, old_evidence_id, enrich_item_id, job_id, requested_by, reason)
  values (p_item, r.entity_id, r.proposed_value->>'url', r.evidence_id, v_enrich, v_job, null,
          left('Replay of the stored read (no AI): ' || (p->>'source') || '; ' || jsonb_array_length(p->'rows') || ' requirement(s)', 500))
  returning id into v_sup;
  v_res := security.enrich_entry_record_v1(v_enrich, jsonb_build_object('model', 'stored-read-replay', 'worker', 'aer_replay', 'prompt_version', 'none',
             'value', jsonb_build_object('rows', p->'rows', 'dropped', p->'dropped', 'coverage', jsonb_build_object('basis', 'stored read replay', 'complete', true))));
  select s.state, s.new_item_id into v_state, v_new from pipeline.aer_read_supersessions s where s.id = v_sup;
  return jsonb_build_object('item', p_item, 'applied', v_state = 'superseded', 'result', v_res, 'request', v_sup, 'state', v_state, 'new_item', v_new, 'rows', jsonb_array_length(p->'rows'),
                            'why', case when v_state <> 'superseded' then (select s.outcome from pipeline.aer_read_supersessions s where s.id = v_sup) end);
end $$;


ALTER FUNCTION "security"."aer_replay_apply_v1"("p_item" "uuid", "p_plan" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_replay_apply_v1"("p_item" "uuid", "p_plan" "jsonb") IS 'CF-247 AER technical holds (7 Nov 2026): puts a waiting course read back together from stored records and passes it through security.enrich_entry_record_v1 (E13, D-R2). No AI read. A person still decides the new item.';



CREATE OR REPLACE FUNCTION "security"."aer_replay_plan_v1"("p_item" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.layer4_review_items; g record; f record; pgp record; v_rows jsonb; v_drop jsonb; v_extra jsonb; v_rest jsonb; v_all jsonb; v_n int; v_lim int; v_chk jsonb;
        v_conf numeric := security.pipeline_num_v1('entry.min_confidence', 0.8); v_cc text; v_src text; v_busy text; v_ev timestamptz;
begin
  select * into r from pipeline.layer4_review_items where id = p_item;
  if r.id is null or r.status <> 'pending' or r.field_code <> 'course_entry_first_read' then return jsonb_build_object('item', p_item, 'ok', false, 'why', 'not a waiting course entry read'); end if;
  select c.provider_id, c.lifecycle_status = 'active' act into g from catalogue.courses c where c.id = r.entity_id;
  if g.provider_id is null or not g.act then return jsonb_build_object('item', p_item, 'ok', false, 'why', 'the course is no longer active'); end if;
  select pg.url, pg.evidence_id into pgp from pipeline.coverage_course_pages pg where pg.course_id = r.entity_id;
  if pgp.url is null or pgp.url is distinct from r.proposed_value->>'url' then return jsonb_build_object('item', p_item, 'ok', false, 'why', 'the course is bound to another page: a new first read, not a recovery'); end if;
  v_busy := case when exists (select 1 from pipeline.aer_read_supersessions s where s.old_item_id = p_item and s.state = 'requested') then 'a corrected read of this item is waiting for the reader'
                 when exists (select 1 from pipeline.field_enrich_items e where e.course_id = r.entity_id and e.field = 'entry_requirements' and e.state in ('queued', 'waiting', 'ai', 'leased'))
                   then 'a read of this course is in progress' end;
  if v_busy is not null then return jsonb_build_object('item', p_item, 'ok', false, 'why', v_busy); end if;
  select e.captured_at into v_ev from pipeline.evidence_artifacts e where e.id = pgp.evidence_id;
  -- the newest stored read that kept its rows and was read after this copy of the page was captured
  select e.id, e.value into f from pipeline.field_enrich_items e
   where e.course_id = r.entity_id and e.field = 'entry_requirements' and e.value ? 'rows_read' and jsonb_array_length(e.value->'rows_read') > 0
     and (e.evidence_id is not distinct from (select pg.evidence_id from pipeline.coverage_course_pages pg where pg.course_id = r.entity_id)
          or (e.evidence_id is null and (v_ev is null or e.updated_at >= v_ev)))
   order by e.updated_at desc limit 1;
  if f.id is not null then
    v_src := 'stored read ' || f.id; v_rows := f.value->'rows_read'; v_drop := coalesce(f.value->'dropped', '[]'::jsonb);
  else
    v_src := 'the waiting read';
    select coalesce(jsonb_agg(jsonb_build_object('kind', x.kind, 'quote', x.quote, 'description', x.description, 'confidence', x.confidence, 'min_grade', x.min_grade,
                                                 'min_entry_score', x.min_entry_score, 'min_entry_score_basis', x.min_entry_score_basis, 'benchmark_band', x.benchmark_band) order by x.created_at, x.id), '[]'::jsonb)
      into v_rows from catalogue.course_entry_requirements x where x.provenance->>'review_item_id' = p_item::text and x.status = 'proposed';
    v_drop := coalesce(r.proposed_value->'dropped', '[]'::jsonb);
    if jsonb_array_length(v_rows) = 0 then return jsonb_build_object('item', p_item, 'ok', false, 'why', 'the waiting read keeps no row and no stored read exists'); end if;
  end if;
  -- the rows set aside only for the row limit or an unprinted score basis, once each
  select coalesce(jsonb_agg(jsonb_build_object('kind', d->>'kind', 'quote', d->>'quote', 'description', d->>'quote', 'confidence', v_conf)), '[]'::jsonb) into v_extra
    from (select distinct on (lower(regexp_replace(coalesce(d1->>'quote', ''), '[^[:alnum:]]', '', 'g'))) d1 d from jsonb_array_elements(v_drop) d1
           where d1->>'reason' in ('over_row_limit', 'score_without_basis') and length(coalesce(d1->>'quote', '')) >= 4 and (d1->>'kind') is not null
             and not exists (select 1 from jsonb_array_elements(v_rows) k
                               where lower(regexp_replace(coalesce(k->>'quote', ''), '[^[:alnum:]]', '', 'g')) = lower(regexp_replace(coalesce(d1->>'quote', ''), '[^[:alnum:]]', '', 'g')))
           order by lower(regexp_replace(coalesce(d1->>'quote', ''), '[^[:alnum:]]', '', 'g'))) z;
  select coalesce(jsonb_agg(d), '[]'::jsonb) into v_rest from jsonb_array_elements(v_drop) d where d->>'reason' not in ('over_row_limit', 'score_without_basis');
  v_all := v_rows || v_extra; v_n := jsonb_array_length(v_all); v_lim := security.course_entry_max_rows_v1(g.provider_id); v_cc := security.coverage_country(g.provider_id);
  -- the audience the reader would give each row (its own rule: the quote's own words)
  select coalesce(jsonb_agg(x || jsonb_build_object('audience',
           case when coalesce(x->>'quote', '') ~* '\m(international|overseas)\M' then 'international'
                when coalesce(x->>'quote', '') ~* '(\mVCE\M|\mATAR\M|\mVTAC\M|\mSTAT\M|Australian Year 12)' then 'domestic'
                when v_cc = 'NZ' and coalesce(x->>'quote', '') ~* '(\mNCEA\M|University Entrance|\mUE\M)' then 'domestic' else 'all' end)), '[]'::jsonb)
    into v_all from jsonb_array_elements(v_all) x;
  v_chk := security.course_entry_correction_check_v1(p_item, r.entity_id, pgp.url, v_all, v_rest);
  return jsonb_build_object('item', p_item, 'ok', v_n <= v_lim and coalesce((v_chk->>'ok')::boolean, false),
    'why', case when v_n > v_lim then format('the read has %s requirements and the row limit is %s: entry.max_rows_by_provider for this university needs at least %s', v_n, v_lim, v_n)
                when not coalesce((v_chk->>'ok')::boolean, false) then v_chk->>'why' end,
    'source', v_src, 'provider_id', g.provider_id, 'course_id', r.entity_id, 'rows', v_all, 'dropped', v_rest, 'rows_needed', v_n, 'row_limit', v_lim,
    'check_ok', coalesce((v_chk->>'ok')::boolean, false),
    'condition_key', md5(concat_ws('|', v_src, v_n::text, v_lim::text, jsonb_array_length(v_rest)::text, coalesce(v_chk->>'why', ''), coalesce(f.id::text, ''))));
end $$;


ALTER FUNCTION "security"."aer_replay_plan_v1"("p_item" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_replay_plan_v1"("p_item" "uuid") IS 'CF-247 AER technical holds (7 Nov 2026): the rows a waiting course read would have if put back together from stored records, the row limit they need and the verdict of the D-R2 check on them. Stable; writes nothing.';



CREATE OR REPLACE FUNCTION "security"."aer_replay_v1"("p_preview" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; p jsonb; a jsonb; v_scan int := security.pipeline_num_v1('aer.replay_scan', 60)::int; v_batch int := security.pipeline_num_v1('batch.aer_replay', 10)::int;
        v_per int := security.pipeline_num_v1('aer.replay_per_provider', 5)::int; v_left int := security.pipeline_num_v1('aer.replay_daily_max', 100)::int
                     - (select count(*) from pipeline.aer_read_supersessions s where s.reason like 'Replay of the stored read%' and s.requested_at > now() - interval '1 day');  -- fixed: the daily cap is counted over the last 24 hours
        v_done int := 0; v_judged int := 0; v_can int := 0; v_wait int := 0; v_out jsonb := '[]'::jsonb; v_byp jsonb := '{}'::jsonb; v_key text; v_mx jsonb; v_new uuid[] := '{}'; v_rd jsonb;
begin
  if not p_preview and security.pipeline_num_v1('aer.replay_on', 1) < 1 then return jsonb_build_object('held', 'aer.replay_on is 0'); end if;
  begin v_mx := security.aer_matrix_rank_repair_v1(p_preview);
  exception when others then v_mx := jsonb_build_object('error', left(sqlerrm, 200));
  end;
  for r in select i.id, c.provider_id from pipeline.layer4_review_items i
             join pipeline.layer4_item_readiness x on x.item_id = i.id
             join catalogue.courses c on c.id = i.entity_id
             left join pipeline.aer_replay_checks k on k.item_id = i.id
            where i.status = 'pending' and i.field_code = 'course_entry_first_read' and x.gate is not null and not coalesce((x.gate->>'complete')::boolean, false)
              and jsonb_array_length(coalesce(x.gate->'shared_page', '[]'::jsonb)) = 0
              and (jsonb_array_length(coalesce(x.gate->'drops_uncovered', '[]'::jsonb)) > 0 or coalesce((x.gate->>'rows_cut')::int, 0) > 0)
            order by k.checked_at nulls first, i.created_at, i.id limit v_scan loop
    p := security.aer_replay_plan_v1(r.id); v_judged := v_judged + 1; v_key := p->>'condition_key';
    if coalesce((p->>'ok')::boolean, false) then
      v_can := v_can + 1;
      if not p_preview and v_done < v_batch and v_left > v_done and coalesce((v_byp->>(r.provider_id::text))::int, 0) < v_per then
        begin
          a := security.aer_replay_apply_v1(r.id, p);
        exception when others then a := jsonb_build_object('item', r.id, 'applied', false, 'why', left(sqlerrm, 200));
        end;
        if a->>'new_item' is not null then v_new := v_new || (a->>'new_item')::uuid; end if;  -- 8 Nov 2026 (lane aer2): the new item is assessed for readiness below
        v_done := v_done + 1; v_byp := jsonb_set(v_byp, array[r.provider_id::text], to_jsonb(coalesce((v_byp->>(r.provider_id::text))::int, 0) + 1));
        v_out := v_out || jsonb_build_array(a);
      else v_wait := v_wait + 1; end if;
    end if;
    if not p_preview then
      insert into pipeline.aer_replay_checks(item_id, condition_key, checked_at, ok, why, rows_needed, row_limit, outcome)
      values (r.id, coalesce(v_key, '-'), now(), coalesce((p->>'ok')::boolean, false), left(p->>'why', 500), (p->>'rows_needed')::int, (p->>'row_limit')::int,
              case when jsonb_array_length(v_out) > 0 and v_out->-1->>'item' = r.id::text then left(coalesce(v_out->-1->>'result', 'not applied: ' || (v_out->-1->>'why')), 200) end)
      on conflict (item_id) do update set condition_key = excluded.condition_key, checked_at = excluded.checked_at, ok = excluded.ok, why = excluded.why,
             rows_needed = excluded.rows_needed, row_limit = excluded.row_limit, outcome = excluded.outcome;
    elsif coalesce((p->>'ok')::boolean, false) then
      v_out := v_out || jsonb_build_array(jsonb_build_object('item', r.id, 'would_replace', true, 'rows', p->'rows_needed'));
    end if;
  end loop;
  -- 8 Nov 2026 (lane aer2): the items this run created are classified now (security.layer4_readiness_items_v1, the readiness run's own steps); a failure here is reported, never undoes the replay
  if not p_preview and cardinality(v_new) > 0 then
    begin v_rd := security.layer4_readiness_items_v1(v_new);
    exception when others then v_rd := jsonb_build_object('error', left(sqlerrm, 200));
    end;
  end if;
  return jsonb_build_object('preview', p_preview, 'judged', v_judged, 'can_be_recovered', v_can, 'replaced', case when p_preview then 0 else v_done end, 'waiting_for_room', v_wait, 'results', v_out, 'matrix_rank_repair', v_mx, 'readiness', v_rd);
end $$;


ALTER FUNCTION "security"."aer_replay_v1"("p_preview" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_replay_v1"("p_preview" boolean) IS 'CF-247 AER technical holds (7 Nov 2026): job aer-replay. Replaces waiting course reads that can be put back together from stored records and pass E13 and D-R2; no AI read; a person decides each new item. aer.replay_on = 0 stops it.';



CREATE OR REPLACE FUNCTION "security"."aer_reread_v1"("p_source_id" "uuid", "p_reason" "text", "p_actor" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_src pipeline.entry_matrix_sources%rowtype; v_run pipeline.entry_matrix_runs%rowtype; v_mime text; v_rows int := 0; v_items int := 0; v_n int;
        v_reason text := btrim(coalesce(p_reason, ''));
begin
  if length(v_reason) < 5 then raise exception 'give a reason (kept in the history)' using errcode = '22023'; end if;
  select * into v_src from pipeline.entry_matrix_sources where id = p_source_id for update;
  if v_src.id is null then raise exception 'source not found'; end if;
  if not security.entry_matrix_enabled_v1(v_src.provider_id) then raise exception 'this provider is outside the reading scope (entry.providers)' using errcode = '22023'; end if;
  if not security.ai_use_allowed_v1('entry_matrix') then raise exception 'AI reading is stopped (AI limits); nothing was asked' using errcode = '22023'; end if;
  -- W28 (29 Oct 2026): the run on the newest stored copy (the source's current content_hash), else the latest run; older copies keep their history
  select * into v_run from pipeline.entry_matrix_runs where source_id = v_src.id
   order by (content_hash is not distinct from v_src.content_hash) desc, created_at desc, id desc limit 1;
  if v_run.id is null then raise exception 'this source has not been read yet; it is read by the scheduled job' using errcode = '22023'; end if;
  if v_run.state in ('queued', 'leased') then raise exception 'a read of this source is already waiting or running' using errcode = '22023'; end if;
  if v_src.status in ('found', 'reading') then raise exception 'this page is waiting to be fetched again; its read follows' using errcode = '22023'; end if;
  if v_run.state = 'failed' and v_run.error like 'held_unparsed%' then
    raise exception 'this source is held as unreadable (%); only a reader change under change control reads it again', left(v_run.error, 120) using errcode = '22023'; end if;

  select e.mime_type into v_mime from pipeline.evidence_artifacts e where e.id = v_src.evidence_id;
  if v_mime = 'text/markdown' and v_src.url !~* '\.pdf($|[?#])' then
    -- 29 Oct 2026: a markdown copy cannot be quoted row by row; the page is fetched again and kept as its own HTML (worker v0.50.2)
    if v_src.status = 'robots_disallowed' then raise exception 'this page is disallowed by the site''s robots.txt; it is not fetched again' using errcode = '22023'; end if;
    update catalogue.provider_entry_matrix m set status = 'superseded', status_reason = 'read again as HTML: ' || v_reason, updated_at = now()
     where m.status = 'proposed' and m.run_id in (select r.id from pipeline.entry_matrix_runs r where r.source_id = v_src.id);
    get diagnostics v_rows = row_count;
    update pipeline.layer4_review_items li set status = 'superseded'
     where li.status = 'pending' and li.id in (select r.review_item_id from pipeline.entry_matrix_runs r where r.source_id = v_src.id);
    get diagnostics v_items = row_count;
    -- read_at cleared: a source never read since passes the central refresh interval only (svc_fc_spend, #722), as for the 29 Oct refetch (#730)
    update pipeline.entry_matrix_sources set status = 'found', attempts = 0, error = null, read_at = null, updated_at = now() where id = v_src.id;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('entry_matrix', 'refetch_html', 'pipeline.entry_matrix_sources',
            jsonb_build_object('source', v_src.id, 'markdown_evidence', v_src.evidence_id, 'rows_superseded', v_rows, 'items_superseded', v_items, 'reason', v_reason), p_actor);
    return jsonb_build_object('ok', true, 'refetch', true, 'rows_superseded', v_rows, 'items_superseded', v_items);
  end if;

  -- W28: runs on older stored copies are not read again. Their proposed rows, then their still-pending item, are superseded; decided items stay
  update catalogue.provider_entry_matrix m set status = 'superseded', status_reason = 'older stored copy; read again on the newest copy: ' || v_reason, updated_at = now()
   where m.status = 'proposed' and m.run_id in (select r.id from pipeline.entry_matrix_runs r left join pipeline.layer4_review_items li on li.id = r.review_item_id
                                                 where r.source_id = v_src.id and r.id <> v_run.id and (li.id is null or li.status = 'pending'));
  get diagnostics v_rows = row_count;
  update pipeline.layer4_review_items li set status = 'superseded'
   where li.status = 'pending' and li.id in (select r.review_item_id from pipeline.entry_matrix_runs r where r.source_id = v_src.id and r.id <> v_run.id);
  get diagnostics v_items = row_count;

  if v_run.state = 'done' then
    -- the newest copy's run only: rows first, then the item (its trigger then finds no proposed rows left), result kept, re-queued
    update catalogue.provider_entry_matrix set status = 'superseded', status_reason = 'read again: ' || v_reason, updated_at = now()
     where run_id = v_run.id and status = 'proposed';
    get diagnostics v_n = row_count; v_rows := v_rows + v_n;
    if v_run.review_item_id is not null then
      update pipeline.layer4_review_items set status = 'superseded' where id = v_run.review_item_id and status = 'pending';
      get diagnostics v_n = row_count; v_items := v_items + v_n;
    end if;
    update pipeline.entry_matrix_runs
       set previous_results = previous_results || jsonb_build_array(jsonb_build_object('result', result, 'rows_admitted', rows_admitted,
             'rows_dropped', rows_dropped, 'cost_usd', cost_usd, 'model', model_code, 'review_item_id', review_item_id, 'done_at', done_at,
             'reread_at', now(), 'reason', v_reason, 'state', state, 'error', error, 'attempts_used', attempts, 'earlier_index', jsonb_array_length(previous_results))),
           state = 'queued', attempts = 0, leased_until = null, result = null, rows_admitted = 0, rows_dropped = 0, review_item_id = null,
           error = null, done_at = null, updated_at = now()
     where id = v_run.id;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('entry_matrix', 'reread', 'pipeline.entry_matrix_runs',
            jsonb_build_object('sources', jsonb_build_array(v_src.id), 'runs', 1, 'run', v_run.id, 'content_hash', v_run.content_hash,
                               'rows_superseded', v_rows, 'items_superseded', v_items, 'reason', v_reason), p_actor);
    return jsonb_build_object('ok', true, 'runs', 1, 'run', v_run.id, 'rows_superseded', v_rows, 'items_superseded', v_items);
  end if;
  update pipeline.entry_matrix_runs set previous_results = previous_results || jsonb_build_array(jsonb_build_object('held', v_run.error like 'held_%',
           'reason', 'read again from the workspace: ' || v_reason, 'error', left(coalesce(v_run.error, ''), 300), 'attempt', attempts, 'model', model_code, 'at', now(), 'result', result)),
         state = 'queued', attempts = 0, leased_until = null, error = null, updated_at = now()
   where id = v_run.id;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('entry_matrix', 'reread_failed', 'pipeline.entry_matrix_runs', jsonb_build_object('source', v_src.id, 'run', v_run.id, 'rows_superseded', v_rows, 'items_superseded', v_items, 'reason', v_reason), p_actor);
  return jsonb_build_object('ok', true, 'runs', 1, 'run', v_run.id, 'rows_superseded', v_rows, 'items_superseded', v_items);
end $_$;


ALTER FUNCTION "security"."aer_reread_v1"("p_source_id" "uuid", "p_reason" "text", "p_actor" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_reread_v1"("p_source_id" "uuid", "p_reason" "text", "p_actor" "uuid") IS 'CF-247 AER W12: one source read again (or fetched again as HTML when its stored copy is markdown); called by public.admin_aer after the Platform Admin check, and by approved programme migrations. Owner only. W28 (29 Oct 2026): only the run on the newest stored copy (the source''s current content_hash) is read again; runs on older copies keep their history, and their proposed rows and pending Layer 4 item are superseded.';



CREATE OR REPLACE FUNCTION "security"."aer_resolver_coverage_v1"("p_countries" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with cc as (select upper(x) cc from unnest(coalesce(p_countries, array(select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'aer.coverage_countries'), '[]'::jsonb))))) x),
  lv as (select l.id, array_remove(array[l.id] || array(select l2.id from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'entry.level_equivalents'), '[]'::jsonb)) p
                                                          join ref.study_levels l2 on l2.short_code = split_part(p, '=', 2) where split_part(p, '=', 1) = l.short_code), null) ids
           from ref.study_levels l),
  c as (select co.id, co.provider_id, lv.ids from catalogue.courses co join lv on lv.id = co.study_level_id
         where co.lifecycle_status = 'active' and co.open_to_international is not false),
  -- rule 4: a provider minimum with a printed minimum and a stated scale, per provider, country and the levels it applies to
  pm as (select m.provider_id, m.country_code, array_agg(distinct x) levels
           from catalogue.provider_entry_matrix m
           cross join lateral unnest(array_remove(array[m.study_level_id], null) || coalesce(security.entry_label_levels_v1(m.level_label), '{}'::uuid[])) x
          where m.status = 'active' and m.course_id is null and m.matrix_kind = 'provider_minimum' and m.min_grade is not null and m.grade_scale is distinct from 'none'
          group by 1, 2),
  -- rule 2: a course row for the country
  cm as (select distinct m.course_id, m.country_code from catalogue.provider_entry_matrix m
          where m.status = 'active' and m.course_id is not null and m.min_grade is not null and m.grade_scale is distinct from 'none'),
  -- rule 1: a course override for international applicants, for this country or every country, with a minimum
  co as (select r.course_id, k.iso_alpha2 country_code from catalogue.course_entry_requirements r left join ref.countries k on k.id = r.country_id
          where r.status = 'active' and r.kind = 'override' and r.audience in ('international', 'all') and (r.min_grade is not null or r.min_entry_score is not null)),
  per as (select cc.cc, count(*) filter (where exists (select 1 from co where co.course_id = c.id and (co.country_code is null or co.country_code = cc.cc))
                                               or exists (select 1 from cm where cm.course_id = c.id and cm.country_code = cc.cc)
                                               or exists (select 1 from pm where pm.provider_id = c.provider_id and pm.country_code = cc.cc and pm.levels && c.ids)) covered
            from cc cross join c group by cc.cc)
  select jsonb_build_object('courses', (select count(*) from c),
           'courses_with_any', (select count(*) from c where exists (select 1 from co where co.course_id = c.id) or exists (select 1 from cm where cm.course_id = c.id)
                                                           or exists (select 1 from pm where pm.provider_id = c.provider_id and pm.levels && c.ids)),
           'providers_with_table', (select count(distinct provider_id) from pm),
           'by_country', (select jsonb_object_agg(per.cc, per.covered order by per.cc) from per),
           'rules', 'course override, course row, provider minimum at the course level or an equivalent; band ladders not counted (lower bound of entry_resolve_v1)')
$$;


ALTER FUNCTION "security"."aer_resolver_coverage_v1"("p_countries" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_resolver_coverage_v1"("p_countries" "text"[]) IS 'AER coverage (Decision 276): active international courses with a published minimum per applicant country under resolver rules 1, 2 and 4 (lower bound of entry_resolve_v1)';



CREATE OR REPLACE FUNCTION "security"."aer_review_kinds_v1"() RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select array['entry_matrix_first_run', 'entry_matrix_change', 'course_entry_first_read']::text[]
$$;


ALTER FUNCTION "security"."aer_review_kinds_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_review_kinds_v1"() IS 'CF-247 A1-A3 (30 Oct 2026): the Layer 4 kinds that take the AER review path only (Platform Admin, one at a time, never in bulk).';



CREATE OR REPLACE FUNCTION "security"."aer_review_lineage_v1"("p_item" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_review_items%rowtype; r pipeline.entry_matrix_runs%rowtype;
begin
  select * into i from pipeline.layer4_review_items where id = p_item;
  if i.id is null or not (i.field_code = any (security.aer_review_kinds_v1())) then raise exception 'not an AER review item' using errcode = '22023'; end if;
  if i.field_code = 'course_entry_first_read' then
    return jsonb_build_object('review_item_id', i.id, 'kind', i.field_code, 'course_id', i.entity_id, 'enrich_item_id', i.proposed_value->'item_id',
      'source_url', i.proposed_value->>'url', 'evidence_id', i.evidence_id,
      'proposed_row_ids', (select coalesce(jsonb_agg(x.id order by x.id), '[]'::jsonb) from catalogue.course_entry_requirements x
                            where x.provenance->>'review_item_id' = p_item::text and x.status = 'proposed'),
      'row_evidence_ids', (select coalesce(jsonb_agg(distinct x.evidence_id), '[]'::jsonb) from catalogue.course_entry_requirements x
                            where x.provenance->>'review_item_id' = p_item::text and x.status = 'proposed' and x.evidence_id is not null),
      'row_content_hashes', (select coalesce(jsonb_agg(distinct e.content_hash), '[]'::jsonb) from catalogue.course_entry_requirements x
                              join pipeline.evidence_artifacts e on e.id = x.evidence_id
                              where x.provenance->>'review_item_id' = p_item::text and x.status = 'proposed' and e.content_hash is not null));
  end if;
  select * into r from pipeline.entry_matrix_runs where review_item_id = p_item;
  return jsonb_build_object('review_item_id', i.id, 'kind', i.field_code, 'provider_id', i.entity_id, 'run_id', r.id, 'source_id', r.source_id,
    'source_url', coalesce((select s.url from pipeline.entry_matrix_sources s where s.id = r.source_id), i.proposed_value->>'url'),
    'content_hash', r.content_hash, 'model', r.model_code, 'run_done_at', r.done_at, 'rows_dropped', r.rows_dropped,
    'completeness', jsonb_build_object('status', r.result->'completeness'->>'status', 'matched', r.result->'completeness'->'matched',
                                       'required', case when r.id is not null then security.entry_completeness_required_v1(r.provider_id) end),
    'proposed_row_ids', (select coalesce(jsonb_agg(m.id order by m.id), '[]'::jsonb) from catalogue.provider_entry_matrix m
                          where r.id is not null and m.run_id = r.id and m.status = 'proposed'),
    'row_evidence_ids', (select coalesce(jsonb_agg(distinct m.evidence_id), '[]'::jsonb) from catalogue.provider_entry_matrix m
                          where r.id is not null and m.run_id = r.id and m.status = 'proposed' and m.evidence_id is not null),
    'row_content_hashes', (select coalesce(jsonb_agg(distinct m.content_hash), '[]'::jsonb) from catalogue.provider_entry_matrix m
                            where r.id is not null and m.run_id = r.id and m.status = 'proposed' and m.content_hash is not null));
end $$;


ALTER FUNCTION "security"."aer_review_lineage_v1"("p_item" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_review_lineage_v1"("p_item" "uuid") IS 'CF-247 A1 (30 Oct 2026): the lineage of a waiting AER item (item, run, source, stored copy hash, waiting row ids), recorded with every AER decision. Owner only.';



CREATE OR REPLACE FUNCTION "security"."aer_review_packet_v1"("p_item" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.layer4_review_items; x pipeline.layer4_item_readiness; g jsonb; v_gsrc text; v_pid uuid; v_course record; v_ev record; v_rt jsonb;
        v_n int := security.pipeline_num_v1('aer.review_packet_rows', 30)::int; v_prop jsonb; v_act jsonb; v_nprop int; v_nact int; v_locks jsonb;
        v_rec text; v_ex jsonb; v_aud jsonb; v_owner jsonb; v_pos jsonb; v_cons jsonb; v_run record; v_conf jsonb; v_d4 boolean; v_set jsonb;
begin
  select * into r from pipeline.layer4_review_items where id = p_item;
  if r.id is null or r.field_code not in ('course_entry_first_read', 'entry_matrix_first_run', 'entry_matrix_change') then return null; end if;
  select * into x from pipeline.layer4_item_readiness where item_id = p_item;
  -- both kinds' records exist before either is read (a record not yet assigned cannot be referenced)
  select null::uuid id, null::uuid source_id, null::int rows_admitted, null::int rows_dropped, null::text url into v_run;
  select null::uuid id, null::uuid provider_id, null::text title, null::text course_code, null::text publication_status, null::text level, null::text country into v_course;
  if x.gate_checked_at is not null and x.gate_checked_at > now() - make_interval(mins => security.pipeline_num_v1('layer4.readiness_recheck_minutes', 120)::int) then
    g := x.gate; v_gsrc := 'stored (job layer4-readiness, ' || to_char(x.gate_checked_at at time zone 'Australia/Melbourne', 'DD Mon HH24:MI') || ')';
  elsif r.field_code = 'course_entry_first_read' then
    g := security.course_entry_gate_v1(p_item); v_gsrc := 'checked now';
  else
    select m.id into v_run from pipeline.entry_matrix_runs m where m.review_item_id = p_item order by m.created_at desc limit 1;
    g := case when v_run.id is not null then security.entry_matrix_gate_v1(v_run.id, '{}'::uuid[]) end; v_gsrc := 'checked now';
  end if;
  v_rt := security.aer_route_v1(r.field_code, g);
  if r.field_code = 'course_entry_first_read' then
    select c.id, c.provider_id, coalesce(c.display_title, c.canonical_title) title, c.course_code, c.publication_status, sl.name level, k.iso_alpha2 country
      into v_course
      from catalogue.courses c left join ref.study_levels sl on sl.id = c.study_level_id
      left join catalogue.providers p on p.id = c.provider_id left join ref.countries k on k.id = p.country_id
     where c.id = r.entity_id;
    v_pid := v_course.provider_id;
    select count(*), coalesce(jsonb_agg(jsonb_build_object('id', z.id, 'kind', z.kind, 'audience', z.audience, 'min_grade', z.min_grade, 'min_value', z.min_value,
             'scale', z.grade_scale, 'min_score', z.min_entry_score, 'basis', z.min_entry_score_basis, 'quote', z.quote, 'confidence', z.confidence) order by z.kind, z.id)
             filter (where z.n <= v_n), '[]'::jsonb)
      into v_nprop, v_prop
      from (select q.*, row_number() over (order by q.kind, q.id) n from catalogue.course_entry_requirements q
             where q.provenance->>'review_item_id' = p_item::text and q.status = 'proposed') z;
    select count(*), coalesce(jsonb_agg(jsonb_build_object('id', z.id, 'kind', z.kind, 'audience', z.audience, 'min_score', z.min_entry_score, 'quote', z.quote,
             'reader', z.provenance->>'reader') order by z.kind, z.id) filter (where z.n <= v_n), '[]'::jsonb)
      into v_nact, v_act
      from (select q.*, row_number() over (order by q.kind, q.id) n from catalogue.course_entry_requirements q where q.course_id = r.entity_id and q.status = 'active') z;
    v_d4 := exists (select 1 from catalogue.course_entry_requirements q where q.course_id = r.entity_id and q.status = 'active' and q.provenance->>'reader' = 'enrich_ai');
    select coalesce(jsonb_agg(distinct q.audience), '[]'::jsonb) into v_aud from catalogue.course_entry_requirements q
     where q.provenance->>'review_item_id' = p_item::text and q.status = 'proposed';
    select coalesce(jsonb_agg(jsonb_build_object('field', l.field, 'mode', l.mode, 'since', l.set_at)), '[]'::jsonb) into v_locks
      from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = r.entity_id
       and l.field in (select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'entry.supersede_lock_fields'), '["entry_requirements"]'::jsonb)));
    v_ex := (select coalesce(jsonb_agg(distinct e), '[]'::jsonb) from (
               select o->>'id' e from jsonb_array_elements(coalesce(g->'other_programme', '[]'::jsonb)) o
               union all select o->>'id' from jsonb_array_elements(coalesce(g->'not_requirement', '[]'::jsonb)) o
               union all select o->>'id' from jsonb_array_elements(coalesce(g->'audience', '[]'::jsonb)) o) z where e is not null);
    v_conf := jsonb_strip_nulls(jsonb_build_object(
      'rows about another programme', nullif(jsonb_array_length(coalesce(g->'other_programme', '[]'::jsonb)), 0),
      'rows that are not entry requirements', nullif(jsonb_array_length(coalesce(g->'not_requirement', '[]'::jsonb)), 0),
      'domestic rows stored for everyone', nullif(jsonb_array_length(coalesce(g->'audience', '[]'::jsonb)), 0),
      'active rows this approval replaces', nullif(case when v_d4 then (select count(*) from catalogue.course_entry_requirements q where q.course_id = r.entity_id and q.status = 'active' and q.provenance->>'reader' = 'enrich_ai') end, 0),
      'manual locks', nullif(jsonb_array_length(v_locks), 0)));
    v_rec := case
      when v_rt->>'route' = 'review' and jsonb_array_length(v_locks) > 0 then 'Reject the read or leave it: the course has a manual lock on its entry requirements'
      when v_rt->>'route' = 'review' then 'Approve all rows (every check passes)'
      when v_rt->>'route' = 'review_except' and v_d4 then 'Reject the read: Approve except is held (D4) while the course has active entry rows, and some waiting rows must be left out'
      when v_rt->>'route' = 'review_except' then 'Approve except: leave out ' || jsonb_array_length(v_ex) || ' row(s) ' || v_ex::text
      else 'Do not approve: technical recovery (' || (v_rt->>'route') || ')' end;
    v_cons := jsonb_build_object(
      'approve', case when v_rt->>'route' in ('review', 'review_except') then
        format('%s waiting row(s) become active%s; %s active row(s) from earlier reads are superseded; the course''s entry requirements then show on the website (public.website_v2_course "entry")%s',
               v_nprop - case when v_rt->>'route' = 'review_except' then jsonb_array_length(v_ex) else 0 end,
               case when v_rt->>'route' = 'review_except' then ' and ' || jsonb_array_length(v_ex) || ' are kept inactive' else '' end,
               case when v_d4 then (select count(*) from catalogue.course_entry_requirements q where q.course_id = r.entity_id and q.status = 'active' and q.provenance->>'reader' = 'enrich_ai') else 0 end,
               case when coalesce(v_course.publication_status, '') <> 'published' then ' once the course is published (it is ' || coalesce(v_course.publication_status, 'unknown') || ')' else '' end)
        else 'refused: the completeness gate (E13) holds an incomplete read; nothing would change' end,
      'reject', format('%s waiting row(s) are quarantined (inactive); the read is closed as not admitted; the course can be read again after aer.schedule_retry_days (%s days)',
               v_nprop, security.pipeline_num_v1('aer.schedule_retry_days', 30)));
  else
    v_pid := r.entity_id;
    select m.id, m.source_id, m.rows_admitted, m.rows_dropped, s.url into v_run from pipeline.entry_matrix_runs m left join pipeline.entry_matrix_sources s on s.id = m.source_id
     where m.review_item_id = p_item order by m.created_at desc limit 1;
    select count(*), coalesce(jsonb_agg(jsonb_build_object('country', z.country_code, 'level', z.level_label, 'qualification', z.qualification_name, 'min_grade', z.min_grade,
             'scale', z.grade_scale, 'audience', z.audience, 'quote', z.quote) order by z.country_code, z.id) filter (where z.n <= v_n), '[]'::jsonb)
      into v_nprop, v_prop
      from (select q.*, row_number() over (order by q.country_code, q.id) n from catalogue.provider_entry_matrix q where q.run_id = v_run.id and q.status = 'proposed') z;
    select count(*) into v_nact from catalogue.provider_entry_matrix q where q.provider_id = v_pid and q.status = 'active';
    select coalesce(jsonb_agg(distinct q.audience), '[]'::jsonb) into v_aud from catalogue.provider_entry_matrix q where q.run_id = v_run.id and q.status = 'proposed';
    v_locks := '[]'::jsonb; v_act := '[]'::jsonb; v_conf := '{}'::jsonb;
    v_rec := case v_rt->>'route' when 'review' then 'Approve the run (every check passes)'
                                 when 'matrix_except' then 'Approve except the rows the check names, or reject the run'
                                 else 'Do not approve: technical recovery (' || (v_rt->>'route') || ')' end;
    v_cons := jsonb_build_object('approve', case when v_rt->>'route' in ('review', 'matrix_except') then v_nprop || ' row(s) become the university''s active entry matrix rows (public.website_v2_provider "entry_matrix")'
                                                 else 'refused: the completeness gate (D-R3) holds an incomplete run; nothing would change' end,
                                 'reject', v_nprop || ' row(s) are not admitted; the source is read again when it changes or is due');
  end if;
  select ev.id, ev.captured_at, ev.source_url into v_ev from pipeline.evidence_artifacts ev where ev.id = r.evidence_id;
  select coalesce(jsonb_agg(jsonb_build_object('owner', o.owner, 'scope', o.scope, 'since', o.since)), '[]'::jsonb) into v_owner
    from pipeline.layer4_review_owners o where o.provider_id = v_pid and o.field_code = r.field_code and o.closed_at is null;
  -- the university's settlement (stored records only, never a gate per row): this item's class and its place among the ready items
  with st as (select * from security.aer_settlement_v1(v_pid)),
       o as (select st.item_id, row_number() over (order by st.created_at, st.item_id) n, count(*) over () t from st where st.settlement = 'ready' and st.field_code = r.field_code)
  select (select jsonb_build_object('settlement', st.settlement, 'why', st.why, 'next_action', st.next_action, 'route', st.route, 'tries', st.tries,
                                    'last_refusal', st.last_refusal, 'rows_read', st.rows_read) from st where st.item_id = p_item),
         jsonb_build_object('ready_at_university', coalesce((select max(t) from o), 0), 'position', (select n from o where o.item_id = p_item),
           'next_ready', (select o2.item_id from o o2 where o2.n = coalesce((select n from o where o.item_id = p_item), 0) + 1))
    into v_set, v_pos;
  return jsonb_build_object('item', p_item, 'field_code', r.field_code, 'provider_id', v_pid,
    'provider', (select coalesce(p.display_name, p.canonical_name) from catalogue.providers p where p.id = v_pid),
    'course', case when r.field_code = 'course_entry_first_read' then jsonb_build_object('id', v_course.id, 'title', v_course.title, 'code', v_course.course_code,
                   'qualification', v_course.level, 'country', v_course.country, 'publication', v_course.publication_status) end,
    'source', case when r.field_code <> 'course_entry_first_read' then jsonb_build_object('run_id', v_run.id, 'url', v_run.url, 'rows_dropped', v_run.rows_dropped) end,
    'audiences', v_aud,
    'evidence', jsonb_build_object('evidence_id', r.evidence_id, 'captured_at', v_ev.captured_at, 'url', coalesce(v_ev.source_url, r.proposed_value->>'url')),
    'proposed', jsonb_build_object('count', v_nprop, 'rows', v_prop), 'active', jsonb_build_object('count', v_nact, 'rows', v_act), 'locks', v_locks,
    'gate', jsonb_build_object('source', v_gsrc, 'complete', coalesce((g->>'complete')::boolean, false), 'reasons', coalesce(g->'reasons', '[]'::jsonb)),
    'conflicts', v_conf, 'route', v_rt, 'exclude_row_ids', coalesce(v_ex, '[]'::jsonb), 'recommended', v_rec, 'consequences', v_cons,
    'owner', v_owner, 'queue', v_pos, 'settlement', v_set);
end $$;


ALTER FUNCTION "security"."aer_review_packet_v1"("p_item" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_review_read_v1"("p_item" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rank int := coalesce(security.current_role_rank(), 0); i pipeline.layer4_review_items%rowtype; r pipeline.entry_matrix_runs%rowtype; v_rows jsonb;
begin
  if auth.uid() is null or v_rank < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
  select * into i from pipeline.layer4_review_items where id = p_item;
  if i.id is null or not (i.field_code = any (security.aer_review_kinds_v1())) then raise exception 'not an AER review item' using errcode = '22023'; end if;
  if i.field_code = 'course_entry_first_read' then
    select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'status', x.status, 'status_reason', x.status_reason, 'kind', x.kind, 'audience', x.audience,
             'description', x.description, 'min_grade', x.min_grade, 'scale', x.grade_scale, 'score', x.min_entry_score, 'basis', x.min_entry_score_basis,
             'band', x.benchmark_band, 'quote', x.quote, 'evidence_id', x.evidence_id) order by x.kind, x.created_at, x.id), '[]'::jsonb)
      into v_rows from catalogue.course_entry_requirements x where x.provenance->>'review_item_id' = p_item::text;
  else
    select * into r from pipeline.entry_matrix_runs where review_item_id = p_item;
    select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'status', m.status, 'status_reason', m.status_reason, 'country', m.country_code,
             'level', m.level_label, 'qualification', m.qualification_name, 'course', m.course_label, 'course_linked', m.course_id is not null, 'band', m.benchmark_band, 'min_grade', m.min_grade, 'scale', m.grade_scale,
             'quote', m.quote, 'evidence_id', m.evidence_id, 'content_hash', m.content_hash) order by m.country_code, m.level_label, m.qualification_name, m.id), '[]'::jsonb)
      into v_rows from catalogue.provider_entry_matrix m
     where (r.id is not null and m.run_id = r.id) or m.provenance->'aer_exclusion'->>'review_item_id' = p_item::text;
  end if;
  return jsonb_build_object('review_item_id', i.id, 'kind', i.field_code, 'status', i.status, 'can_decide', v_rank >= 6,
    'provider_id', (select case when li.entity_type = 'provider' then li.entity_id end from pipeline.layer4_review_items li where li.id = p_item),
    'lineage', security.aer_review_lineage_v1(p_item), 'rows', v_rows,
    -- E13: a course entry read's completeness (rows cut by the row limit, rows about another programme, a shared page); approval is held while incomplete
    'completeness_gate', case when i.field_code = 'course_entry_first_read' then security.course_entry_gate_v1(i.id)
                              -- D-R3: a matrix run's whole-read completeness; approval is held while incomplete
                              else security.entry_matrix_gate_v1((select x.id from pipeline.entry_matrix_runs x where x.review_item_id = i.id)) end,
    -- D-R2: the read this item replaced (with the reviewer's diff), and for a replaced item the item that replaced it
    'supersedes', i.proposed_value->'supersedes',
    'superseded_by', (select jsonb_build_object('review_item_id', s.new_item_id, 'at', s.closed_at, 'reason', s.reason) from pipeline.aer_read_supersessions s
                       where s.old_item_id = i.id and s.state = 'superseded' order by s.closed_at desc limit 1),
    'evidence_id', coalesce(i.evidence_id, (select (v->>'evidence_id')::uuid from jsonb_array_elements(v_rows) v where v->>'evidence_id' is not null limit 1)),
    'decision', (select jsonb_build_object('action', d.action, 'reason', d.reason, 'at', d.created_at, 'exclude_row_ids', d.final_value->'exclude_row_ids')
                   from pipeline.layer4_decisions d where d.review_item_id = i.id order by d.created_at desc limit 1));
end $$;


ALTER FUNCTION "security"."aer_review_read_v1"("p_item" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_review_read_v1"("p_item" "uuid") IS 'CF-247 A1 (30 Oct 2026): one AER Layer 4 item for the reviewer: its rows with quotes and statuses, lineage, stored copy and whether the reader may decide (Platform Admin, A3). Curator and above.';



CREATE OR REPLACE FUNCTION "security"."aer_review_readiness_load_v1"("p_rows" "jsonb", "p_source" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare x jsonb; v_ok int := 0; v_skip jsonb := '[]'::jsonb; li record;
begin
  if coalesce(btrim(p_source), '') = '' then raise exception 'name the classification source (document and date)'; end if;
  for x in select * from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) loop
    if x->>'readiness' not in ('review_ready', 'reader_correction_required', 'evidence_required', 'superseded_invalid', 'awaiting_human_review') then
      v_skip := v_skip || jsonb_build_object('item', x->>'review_item_id', 'why', 'unknown readiness class'); continue; end if;
    if x->>'root_cause' is not null and not exists (select 1 from pipeline.aer_gap_root_causes rc where rc.code = x->>'root_cause') then
      v_skip := v_skip || jsonb_build_object('item', x->>'review_item_id', 'why', 'unknown root cause'); continue; end if;
    select i.id, i.status, i.field_code, i.entity_type, i.entity_id into li from pipeline.layer4_review_items i where i.id = nullif(x->>'review_item_id', '')::uuid;
    if li.id is null or li.status <> 'pending' or li.field_code not in ('entry_matrix_first_run', 'entry_matrix_change', 'course_entry_first_read') then
      v_skip := v_skip || jsonb_build_object('item', x->>'review_item_id', 'why', 'not a pending AER Layer 4 item'); continue; end if;
    insert into pipeline.aer_review_readiness as z (review_item_id, field_code, entity_type, entity_id, provider_id, readiness, root_cause, reason, evidence, basis, source, item_status)
    values (li.id, li.field_code, li.entity_type, li.entity_id,
            coalesce((select r.provider_id from pipeline.entry_matrix_runs r where r.review_item_id = li.id limit 1),
                     (select c.provider_id from catalogue.courses c where c.id = li.entity_id), li.entity_id),
            x->>'readiness', x->>'root_cause', left(x->>'reason', 500), coalesce(x->'evidence', '{}'::jsonb), 'classification', left(p_source, 300), li.status)
    on conflict (review_item_id) do update set readiness = excluded.readiness, root_cause = excluded.root_cause, reason = excluded.reason, evidence = excluded.evidence,
           basis = 'classification', source = excluded.source, classified_at = now(), updated_at = now()
     where z.settled_at is null;
    v_ok := v_ok + 1;
  end loop;
  return jsonb_build_object('loaded', v_ok, 'skipped', v_skip);
end $$;


ALTER FUNCTION "security"."aer_review_readiness_load_v1"("p_rows" "jsonb", "p_source" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_review_readiness_load_v1"("p_rows" "jsonb", "p_source" "text") IS 'CF-247 AER Layer 4 review readiness (mandate 16:33 §9): loads a classification ([{review_item_id, readiness, root_cause, reason, evidence}]) for pending AER items only, naming its source; refuses unknown classes, unknown root causes and settled or non-AER items. Changes no Layer 4 item. Run by the Platform Admin.';



CREATE OR REPLACE FUNCTION "security"."aer_review_ready_v1"("p_provider" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("item_id" "uuid", "field_code" "text", "provider_id" "uuid", "created_at" timestamp with time zone, "settlement" "text", "route" "text", "review_class" "text", "ready" boolean, "exception_rows" integer, "url_locked" boolean, "duplicate_of" "uuid", "readiness" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with s as (select * from security.aer_settlement_v1(p_provider)),
       lf as (select security.pipeline_list_v1('entry.supersede_lock_fields', '["entry_requirements", "course_url", "official_url"]'::jsonb) f),
       w as (select s.item_id, s.field_code, s.provider_id, s.created_at, s.settlement, s.route, i.entity_type, i.entity_id, x.readiness, x.gate,
                    first_value(i.id) over (partition by i.entity_id, i.field_code, case when i.field_code = 'course_entry_first_read' then null else i.proposed_value->>'url' end
                                            order by i.created_at, i.id) first_id
               from s join pipeline.layer4_review_items i on i.id = s.item_id left join pipeline.layer4_item_readiness x on x.item_id = i.id)
  select w.item_id, w.field_code, w.provider_id, w.created_at, w.settlement, w.route,
         case w.settlement when 'ready' then (case when w.route = 'review' then 'complete' else 'approve_except' end) else w.settlement end,
         w.settlement = 'ready',
         coalesce((select sum(jsonb_array_length(g.v))::int from jsonb_each(coalesce(w.gate, '{}'::jsonb)) g(k, v)
                    where jsonb_typeof(g.v) = 'array' and g.k = any (case when w.route = 'matrix_except' then array['flagged', 'same_identity']
                                                                          else array['audience', 'not_requirement', 'other_programme', 'joined'] end)), 0),
         w.entity_type = 'course' and exists (select 1 from pipeline.manual_locks l, lf where l.entity = 'course' and l.entity_id = w.entity_id and l.field = any (lf.f)),
         case when w.first_id <> w.item_id then w.first_id end,
         w.readiness
    from w
$$;


ALTER FUNCTION "security"."aer_review_ready_v1"("p_provider" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_route_v1"("p_field" "text", "p_gate" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with g as (select p_gate g, security.aer_e13_class_v1(p_gate) c,
                    coalesce((select string_agg(x, ' ') from jsonb_array_elements_text(coalesce(p_gate->'reasons', '[]'::jsonb)) x), '') rs,
                    coalesce((select array_agg(distinct d->>'reason') from jsonb_array_elements(coalesce(p_gate->'drops_uncovered', '[]'::jsonb)) d), '{}') dr)
  select case
    when p_gate is null then jsonb_build_object('class', 'unchecked', 'route', 'awaiting_gate', 'person', false,
           'remedy', 'job layer4-readiness gates it (never-gated items first, layer4.gate_batch a run)')
    when p_field <> 'course_entry_first_read' then
      case when coalesce((g->>'complete')::boolean, false) then jsonb_build_object('class', 'complete', 'route', 'review', 'person', true, 'remedy', 'a person decides (Approve or Reject the run)')
           when rs ~* '(dropped [0-9]+ published row|no printed scale|without a scale|not printed in its quote|column left out)' then
             jsonb_build_object('class', 'matrix_held', 'route', 'matrix_source', 'person', true,
               'remedy', 'the source''s missing rows, scales or country mapping: Human-assisted recovery''s provider-level intervention (aer_read_held), then the matrix re-read')
           else jsonb_build_object('class', 'matrix_held', 'route', 'matrix_except', 'person', true, 'remedy', 'a person leaves out the rows the check names (Approve except), or rejects the run') end
    when c = 'complete' then jsonb_build_object('class', c, 'route', 'review', 'person', true, 'remedy', 'a person decides (Approve all rows or Reject the read)')
    when c = 'row_level' then jsonb_build_object('class', c, 'route', 'review_except', 'person', true, 'remedy', 'a person leaves out the named rows (Approve except) or rejects the read')
    when c = 'row_limit' and coalesce((g->>'rows_cut')::int, 0) >= security.pipeline_num_v1('aer.row_limit_matrix_rows', 30) then
      jsonb_build_object('class', c, 'route', 'source_is_matrix', 'person', false, 'authority', true,
        'remedy', 'the page is a qualification table: map it as the university''s entry matrix source (identity and source mapping), not a higher row limit')
    when c = 'row_limit' then jsonb_build_object('class', c, 'route', 'row_limit', 'person', false, 'authority', true,
        'remedy', 'a row boundary for the university (entry.max_rows_by_provider, Platform Admin), then a corrected read; a re-read with the same limit cuts the same rows')
    when c = 'shared_page' then jsonb_build_object('class', c, 'route', 'identity', 'person', true,
        'remedy', 'confirm which programme the stored page belongs to (aer_course_identity); never an extraction retry')
    when c = 'drops_uncovered' then jsonb_build_object('class', c,
        'route', case when 'score_without_basis' = any (dr) then 'missing_scale' when 'quote_not_on_page' = any (dr) then 'quote_association' else 'low_confidence' end,
        'person', false, 'reasons', to_jsonb(dr),
        'remedy', 'a corrected read from the stored copy (E13 recovery, pilot) when it has not been refused on that copy; otherwise the dropped rows with their quotations and scale from a person (aer_read_rows_missing)')
    else jsonb_build_object('class', c, 'route', 'unknown', 'person', true, 'remedy', 'see the gate reasons') end
  from g
$$;


ALTER FUNCTION "security"."aer_route_v1"("p_field" "text", "p_gate" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_row_v1"("p_kind" "text", "p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when p_kind = 'matrix' then (
    select jsonb_build_object('kind', 'matrix', 'id', m.id, 'provider_id', m.provider_id, 'provider_name', coalesce(p.display_name, p.canonical_name),
      'country', m.country_code, 'country_name', k.name, 'level_label', m.level_label, 'level_code', l.short_code, 'level_name', l.name,
      'matrix_kind', m.matrix_kind, 'qualification', m.qualification_name, 'band', m.benchmark_band, 'min_grade', m.min_grade, 'min_value', m.min_value,
      'scale', m.grade_scale, 'conditions', m.conditions, 'audience', m.audience, 'edition', m.edition, 'intake_year', m.intake_year, 'as_at', m.as_at,
      'valid_to', m.valid_to, 'status', m.status, 'status_reason', m.status_reason, 'withdrawal_reason', m.withdrawal_reason, 'quote', m.quote,
      'source_url', m.source_url, 'source_id', m.source_id, 'evidence_id', m.evidence_id, 'confidence', m.confidence, 'version', m.version,
      'course_id', m.course_id, 'course_code', c.course_code, 'course_title', c.canonical_title, 'manual', m.provenance->>'reader' = 'manual',
      'provenance', m.provenance, 'run_id', m.run_id, 'run_state', r.state, 'run_error', left(r.error, 200), 'review_item_id', r.review_item_id,
      'review_status', li.status, 'created_at', m.created_at, 'updated_at', m.updated_at)
      from catalogue.provider_entry_matrix m join catalogue.providers p on p.id = m.provider_id left join ref.countries k on k.id = m.country_id
      left join ref.study_levels l on l.id = m.study_level_id left join catalogue.courses c on c.id = m.course_id
      left join pipeline.entry_matrix_runs r on r.id = m.run_id left join pipeline.layer4_review_items li on li.id = r.review_item_id
     where m.id = p_id)
  else (
    select jsonb_build_object('kind', 'course', 'id', x.id, 'course_id', x.course_id, 'course_title', c.canonical_title, 'course_code', c.course_code,
      'provider_id', c.provider_id, 'provider_name', coalesce(p.display_name, p.canonical_name), 'requirement_kind', x.kind, 'audience', x.audience,
      'country', k.iso_alpha2, 'country_name', k.name, 'description', x.description, 'min_grade', x.min_grade, 'min_value', x.min_value, 'scale', x.grade_scale,
      'min_entry_score', x.min_entry_score, 'min_entry_score_basis', x.min_entry_score_basis, 'band', x.benchmark_band, 'quote', x.quote,
      'source_url', x.source_url, 'evidence_id', x.evidence_id, 'confidence', x.confidence, 'as_at', x.as_at, 'status', x.status, 'status_reason', x.status_reason,
      'manual', x.provenance->>'reader' = 'manual', 'provenance', x.provenance, 'review_item_id', li.id, 'review_status', li.status,
      'created_at', x.created_at, 'updated_at', x.updated_at)
      from catalogue.course_entry_requirements x join catalogue.courses c on c.id = x.course_id join catalogue.providers p on p.id = c.provider_id
      left join ref.countries k on k.id = x.country_id
      left join pipeline.layer4_review_items li on li.id = nullif(x.provenance->>'review_item_id', '')::uuid
     where x.id = p_id) end
$$;


ALTER FUNCTION "security"."aer_row_v1"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_row_v1"("p_kind" "text", "p_id" "uuid") IS 'CF-247 AER workspace: one provider-matrix or course-requirement row as the workspace shows it.';



CREATE OR REPLACE FUNCTION "security"."aer_run_cause_v1"("p_state" "text", "p_error" "text", "p_completeness" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_state = 'failed' then case
      when p_error ~* '^held_unparsed: not a country table: no country' then 'non_country_heading'
      when p_error ~* '^held_unparsed: not a country table' then 'requirement_type_columns'
      when p_error ~* '^held_incomplete' then 'reader_omission'
      when p_error ~* '^held_unparsed: no printed scale' then 'unscaled_column'
      when p_error ~* '^held_unparsed: PDF' then 'pdf_table_layout'
      when p_error ~* '^held:' then 'policy_hold'
      else 'extraction_failed' end
    when p_state = 'done' and p_completeness = 'incomplete' then 'reader_omission'
    when p_state = 'done' and p_completeness = 'unparsed' then 'manifest_unparsed'
  end
$$;


ALTER FUNCTION "security"."aer_run_cause_v1"("p_state" "text", "p_error" "text", "p_completeness" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_run_shape_v1"("p_state" "text", "p_error" "text", "p_completeness" "text", "p_basis" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_error ~* '^held_unparsed: not a country table: no country' then 'qualification_page'
    when p_error ~* '^held_unparsed: not a country table' then 'requirement_table'
    when p_error ~* '^held_unparsed: PDF' or p_basis ~* 'pdf' then 'pdf_table'
    when p_error ~* '^held:' then 'policy_hold'
    when p_error ~* '^held_unparsed' or p_completeness = 'unparsed' then 'unparsed'
    when p_completeness in ('complete', 'incomplete') then 'country_table'
    when p_completeness = 'not_applicable' then 'no_table'
    else 'unknown' end
$$;


ALTER FUNCTION "security"."aer_run_shape_v1"("p_state" "text", "p_error" "text", "p_completeness" "text", "p_basis" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_schedule_active_v1"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from cron.job j where j.jobname = 'aer-scheduled-read' and j.active)
$$;


ALTER FUNCTION "security"."aer_schedule_active_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_schedule_active_v1"() IS 'CF-247 scheduled AER reading: true while job aer-scheduled-read is switched on. Then eligibility rules replace the fixed entry.providers list (security.entry_matrix_enabled_v1) and the job owns the due entry-page refresh (security.entry_matrix_fire_v1).';



CREATE OR REPLACE FUNCTION "security"."aer_schedule_country_v1"("p_country" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with o as (select btrim(split_part(x, '=', 2)) why from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'aer.schedule_countries_off'), '[]'::jsonb)) x
              where upper(btrim(split_part(x, '=', 1))) = upper(p_country) limit 1)
  select jsonb_build_object('country', upper(p_country),
           'on', coalesce(security.toolset_setting('pipeline', 'aer.schedule_countries'), '[]'::jsonb) ? upper(p_country) and not exists (select 1 from o),
           'reason', case when exists (select 1 from o) then coalesce(nullif((select why from o), ''), 'switched off')
                          when not coalesce(security.toolset_setting('pipeline', 'aer.schedule_countries'), '[]'::jsonb) ? upper(p_country) then 'not in the countries switched on' end)
$$;


ALTER FUNCTION "security"."aer_schedule_country_v1"("p_country" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_schedule_country_v1"("p_country" "text") IS 'CF-247 scheduled AER reading: is a country switched on for scheduled entry reading (aer.schedule_countries, less aer.schedule_countries_off), with the reason when off.';



CREATE OR REPLACE FUNCTION "security"."aer_schedule_courses_v1"("p_limit" integer, "p_all" boolean DEFAULT false) RETURNS TABLE("course_id" "uuid", "provider_id" "uuid", "country" "text", "provider_name" "text", "tier" integer, "turn" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with s as (select make_interval(days => security.pipeline_num_v1('aer.schedule_retry_days', 30)::int) retry,
                    security.pipeline_num_v1('aer.schedule_per_provider', 5) per,
                    coalesce(security.toolset_setting('pipeline', 'aer.retry_now_error_pattern') #>> '{}', '') refused),
  c as (select p.* from security.aer_course_population_v1() p cross join s
         where not exists (select 1 from catalogue.course_entry_requirements x where x.course_id = p.course_id and x.status in ('active', 'proposed'))
           and not exists (select 1 from pipeline.layer4_review_items r where r.entity_id = p.course_id and r.field_code = 'course_entry_first_read' and r.status = 'pending')
           and not exists (select 1 from pipeline.field_enrich_items f where f.course_id = p.course_id and f.field = 'entry_requirements'
                             and (f.state in ('queued', 'waiting', 'ai', 'leased', 'review')
                                  -- 13 Nov 2026: a read the AI provider refused (aer.retry_now_error_pattern) was not read, so it does not wait for the retry interval
                                  or (f.updated_at > now() - s.retry and not (f.state = 'failed' and s.refused <> '' and coalesce(f.reason, '') ~* s.refused))))
           and not exists (select 1 from pipeline.enrichment_flags fl where fl.entity = 'course' and fl.entity_key = p.course_id::text and fl.field = 'entry_requirements'
                             and fl.reason_code = 'enrich_no_value' and fl.state in ('raised', 'counting'))),
  r as (select c.*, row_number() over (partition by c.provider_id order by c.title, c.course_id) turn from c)
  select r.course_id, r.provider_id, r.country, r.provider_name, r.tier, r.turn
    from r cross join s
   where p_all or r.turn <= s.per
   order by r.turn, r.tier, r.provider_name, r.provider_id
   limit p_limit
$$;


ALTER FUNCTION "security"."aer_schedule_courses_v1"("p_limit" integer, "p_all" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_schedule_courses_v1"("p_limit" integer, "p_all" boolean) IS 'CF-247 scheduled AER reading: the courses of the entry-reading population (security.aer_course_population_v1) due a scheduled read: no requirement held, nothing waiting or in progress, not tried within aer.schedule_retry_days, no open no-value hold; providers take turns (aer.schedule_per_provider). Read-only.';



CREATE OR REPLACE FUNCTION "security"."aer_schedule_held_v1"("p_limit" integer) RETURNS TABLE("item_id" "uuid", "course_id" "uuid", "provider_id" "uuid", "country" "text", "eligible" boolean, "outcome" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_scan int := security.pipeline_num_v1('aer.schedule_held_scan', 40)::int;
        v_retry interval := make_interval(days => security.pipeline_num_v1('aer.schedule_held_retry_days', 14)::int);
        v_tries int := security.pipeline_num_v1('aer.schedule_held_max_tries', 2)::int;
        r record; g jsonb; v_chk jsonb; v_n int := 0;
begin
  if coalesce(p_limit, 0) <= 0 then return; end if;
  -- 4 Nov 2026 (AER throughput, mandate 08:16 §8): while E13 recovery is on it owns corrected reads of held items, within its own budget
  if security.pipeline_num_v1('aer.e13_recover_on', 0) >= 1 then return; end if;
  for r in select i.id, i.entity_id, c.provider_id pid, e.country cc, pg.url
             from pipeline.layer4_review_items i
             join catalogue.courses c on c.id = i.entity_id
             join security.aer_eligible_v1() e on e.provider_id = c.provider_id
             left join pipeline.coverage_course_pages pg on pg.course_id = i.entity_id
             left join pipeline.aer_schedule_checks k on k.item_id = i.id
            where i.field_code = 'course_entry_first_read' and i.status = 'pending'
              and (security.aer_schedule_country_v1(e.country)->>'on')::boolean
              and not exists (select 1 from pipeline.aer_read_supersessions s where s.old_item_id = i.id and (s.state = 'requested' or s.requested_at > now() - v_retry))
              and (select count(*) from pipeline.aer_read_supersessions s where s.old_item_id = i.id) < v_tries
              and not exists (select 1 from pipeline.work_items w where w.lane = 'aer_technical' and w.entity = i.id::text and w.work_kind = 'l4_item'
                                and w.failure_class in ('aer_row_limit', 'aer_unchanged_evidence', 'aer_human_input', 'aer_stale', 'duplicate') and w.stage in ('parked', 'awaiting_review'))
            -- 4 Nov 2026 20:02 (v2.15.473 first run): items the shared rule last made eligible first, so the scan is not spent on holds it never reads
            order by coalesce((select case w.unresolved_blocker->>'class' when 'reread_eligible' then 0 when 'changed_conditions' then 1 end from pipeline.work_items w
                                where w.lane = 'aer_technical' and w.entity = i.id::text and w.work_kind = 'l4_item' and w.failure_class = 'aer_reread_eligible'
                                  and w.stage <> 'done' limit 1), 2),
                     k.checked_at nulls first, i.created_at, i.id
            limit v_scan loop
    item_id := r.id; course_id := r.entity_id; provider_id := r.pid; country := r.cc; eligible := false;
    g := security.course_entry_gate_v1(r.id);
    if g is null or coalesce((g->>'complete')::boolean, false) then outcome := 'complete';
    elsif jsonb_array_length(coalesce(g->'shared_page', '[]'::jsonb)) > 0 then outcome := 'shared page: for a person';
    -- 11 Nov 2026 (F-AER.02 self-healing): a read cut at the row limit goes to the shared recovery rule like every other hold; it is read again only when the
    -- rule makes it eligible (the limit was raised since the read: changed_conditions), otherwise it waits with the rule's class (row_limit) and next action below
    elsif coalesce((g->>'rows_cut')::int, 0) = 0 and jsonb_array_length(coalesce(g->'drops_uncovered', '[]'::jsonb)) = 0 then outcome := 'held only for rows a person leaves out';
    -- 4 Nov 2026 (mandate 16:32 §4-§5): only a read the shared rule makes eligible is read again (never a refusal on an unchanged copy or a
    -- row-limit cut under the same limit); the others are recorded with their class
    elsif not coalesce((security.aer_recovery_rule_v1(r.id)->>'eligible')::boolean, false) then
      outcome := left('held, not read again: ' || coalesce(security.aer_recovery_rule_v1(r.id)->>'class', '?') || ' (' || coalesce(security.aer_recovery_rule_v1(r.id)->>'next_action', '') || ')', 300);
    else
      v_chk := security.course_entry_correction_check_v1(r.id, r.entity_id, r.url);
      if coalesce((v_chk->>'ok')::boolean, false) then
        if v_n < p_limit then eligible := true; outcome := 'held: read again (D-R2)'; v_n := v_n + 1; else outcome := 'held: next run'; end if;
      else outcome := left('held, not correctable: ' || coalesce(v_chk->>'why', ''), 300); end if;
    end if;
    return next;
  end loop;
end $$;


ALTER FUNCTION "security"."aer_schedule_held_v1"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_schedule_held_v1"("p_limit" integer) IS 'CF-247 scheduled AER reading (b): waiting course reads held as incomplete, each checked by the E13 gate and the shared recovery rule (security.aer_recovery_rule_v1); a read is eligible to be read again (D-R2) only when the rule makes it eligible and the correction check passes. A read cut at the row limit follows the same rule (F-AER.02, 11 Nov 2026): read again only when the limit was raised since the read.';



CREATE OR REPLACE FUNCTION "security"."aer_schedule_tick_v1"("p_preview" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_batch int := security.pipeline_num_v1('batch.aer_schedule_courses', 20)::int;
        v_daymax int := security.pipeline_num_v1('aer.schedule_daily_max', 200)::int;
        v_heldmax int := security.pipeline_num_v1('batch.aer_schedule_held', 10)::int;
        v_l4max int := security.pipeline_num_v1('aer.schedule_layer4_max', 600)::int;
        v_mxmax int := security.pipeline_num_v1('batch.aer_schedule_matrix', 4)::int;
        v_cost numeric := security.course_entry_cost_v1(); v_owner uuid; v_used int; v_l4 int; v_prog int; v_bp boolean; v_room int;
        v_ai text; v_aim text; v_bal numeric; v_floor numeric; v_why text; v_reason text; v_orank int; v_orole text;
        r record; v_job uuid; v_res jsonb; v_held jsonb := '[]'::jsonb; v_new jsonb := '[]'::jsonb; v_mx jsonb := '[]'::jsonb; v_skip jsonb := '[]'::jsonb;
        v_checked jsonb := '[]'::jsonb; v_nh int := 0; v_nn int := 0; v_nm int := 0; v_fc int := 0; v_est numeric;
        v_fair boolean := security.pipeline_num_v1('wc.aer_fair_on', 0) >= 1; v_rr jsonb; v_tech jsonb; v_parked int := 0;
        -- 11 Nov 2026 (F-AER.02 self-healing): corrected reads have their own 24-hour allowance, apart from new reads
        v_cmax int := security.pipeline_num_v1('aer.schedule_correction_daily_max', 100)::int; v_cused int := 0; v_croom int := 0;
begin
  if not p_preview and not pg_try_advisory_xact_lock(hashtext('cf247:aer-scheduled-read')) then  -- fixed: one run at a time
    return jsonb_build_object('skipped', 'another run is in progress');
  end if;
  -- run-as (mandate 13:09 D6: only the identity and role permissions the platform already defines): the job runs as the database role cron uses,
  -- through these security-definer functions; each read is asked in the name of the owner of the platform's standing enrichment
  -- (pipeline.field_gap_queue_control.owner, Coverage › Attributes, Fill the gaps; the same owner the gap queue and enrichment plans use), and only
  -- while that owner holds an active, unexpired role at the rank Read next batch requires (admin_aer course_batch). Nothing is granted here.
  -- 12 Nov 2026 (F-AER.02): a corrected read the reader skipped before reading records nothing; close it as refused so its item is not blocked
  if not p_preview then perform security.aer_supersession_settle_v1(); end if;
  select c.owner into v_owner from pipeline.field_gap_queue_control c where c.id = 1;
  select ro.rank, ro.code into v_orank, v_orole from security.user_roles ur join security.roles ro on ro.code = ur.role_code
   where ur.user_id = v_owner and (ur.expires_at is null or ur.expires_at > now()) and ro.status = 'active' order by ro.rank desc limit 1;
  select coalesce(sum(x.course_reads), 0), coalesce(sum(x.corrections), 0) into v_used, v_cused from pipeline.aer_schedule_runs x
   where x.ran_at > now() - interval '1 day';  -- fixed: the daily cap is counted over the last 24 hours
  select count(*) into v_l4 from pipeline.layer4_review_items i where i.status = 'pending' and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run');
  select count(*) into v_prog from pipeline.field_enrich_items f where f.field = 'entry_requirements' and f.state in ('queued', 'waiting', 'ai', 'leased');
  -- 10 Nov 2026 (AER source recovery): a hold the technical lane has parked with its reason (row limit, human input, duplicate, stale read) waits for a setting, a person or another copy of the page;
  -- it is not a decision a reviewer can make, so it does not use the capacity (security.aer_parked_items_v1). The limit itself is unchanged. With wc.aer_fair_on the count below is replaced as before.
  select count(*) into v_parked from security.aer_parked_items_v1();
  v_bp := v_l4 - v_parked + v_prog >= v_l4max;
  -- 4 Nov 2026 (SS-021 F4, IQ-00128; wc.aer_fair_on): the same limit (aer.schedule_layer4_max, never raised or bypassed) counts distinct
  -- review-ready decisions and distinct reads in progress (security.work_review_room_v1, category aer); technically held and duplicate items
  -- are recorded for bounded technical recovery below, not counted
  if v_fair then
    v_rr := security.work_review_room_v1('aer');
    v_bp := coalesce((v_rr->>'room')::numeric, 0) <= 0;
  end if;
  v_room := greatest(0, least(v_batch, v_daymax - v_used));
  v_croom := greatest(0, least(v_heldmax, v_cmax - v_cused));
  v_ai := security.ai_use_refusal_v1('enrich_fields');
  v_aim := security.ai_use_refusal_v1('entry_matrix');
  select o.remaining_usd into v_bal from pipeline.layer3_openrouter_observations o where o.kind = 'credits' order by o.observed_at desc limit 1;
  v_floor := coalesce((security.toolset_setting('openrouter', 'credit_floor_usd'))::text::numeric, 0);
  v_why := case when v_owner is null then 'no owner to run as (Coverage › Attributes, Fill the gaps)'
                when coalesce(v_orank, 0) < 6 then 'the owner it runs as does not hold the Platform Admin role that Read next batch requires'  -- fixed: the rank admin_aer course_batch requires
                when v_ai is not null then 'AI reading is stopped (AI limits): ' || v_ai
                when v_room = 0 and v_croom = 0 and (v_daymax <= v_used or v_cmax <= v_cused) then 'the daily cap is reached'
                when v_room = 0 and v_croom = 0 then 'no course reads a run'
                when v_bal is not null and v_bal - (v_room + v_croom) * v_cost < v_floor then 'the estimate would take the OpenRouter balance below its floor (Toolsets & limits)' end;

  if v_why is null then
    -- (b) held reads first, through D-R2: they replace the waiting item, so they also run under back-pressure
    for r in select * from security.aer_schedule_held_v1(v_croom) loop
      v_checked := v_checked || jsonb_build_object('item_id', r.item_id, 'outcome', r.outcome);
      continue when not r.eligible;
      if p_preview then
        v_held := v_held || jsonb_build_object('item_id', r.item_id, 'course_id', r.course_id, 'provider_id', r.provider_id, 'country', r.country); v_nh := v_nh + 1;
        continue;
      end if;
      begin
        v_res := security.course_entry_correction_v1(r.item_id, v_owner,
                   'Scheduled entry reading (job aer-scheduled-read): the waiting read dropped printed requirements that no row covers; read again from the same stored page');
        v_held := v_held || jsonb_build_object('item_id', r.item_id, 'course_id', r.course_id, 'provider_id', r.provider_id, 'country', r.country, 'job_id', v_res->>'job_id');
        v_nh := v_nh + 1;
      exception when others then
        v_skip := v_skip || jsonb_build_object('item_id', r.item_id, 'why', left(sqlerrm, 300));
      end;
    end loop;
    -- (a) new course reads by eligibility rules, unless Layer 4 is full
    if not v_bp and v_room > 0 then
      -- 4 Nov 2026 (SS-021 F4, wc.aer_fair_on): university by university within its share and the new-university reserve (security.aer_fair_courses_v1)
      for r in select * from security.aer_schedule_courses_v1(v_room * 2) where not v_fair  -- fixed: twice the room, so courses the item gate holds can be passed over
               union all select * from security.aer_fair_courses_v1(v_room) where v_fair loop
        exit when v_nn >= v_room;
        if security.enrich_item_held_v1(r.course_id, 'entry_requirements') then
          v_skip := v_skip || jsonb_build_object('course_id', r.course_id, 'why', 'held by the item gate'); continue;
        end if;
        if p_preview then
          v_new := v_new || jsonb_build_object('course_id', r.course_id, 'provider_id', r.provider_id, 'provider', r.provider_name, 'country', r.country); v_nn := v_nn + 1;
          continue;
        end if;
        begin
          v_job := security.course_entry_read_enqueue_v1(r.course_id, v_owner,
                     'Scheduled entry reading (job aer-scheduled-read): eligible course with no entry requirement held');
          v_new := v_new || jsonb_build_object('course_id', r.course_id, 'provider_id', r.provider_id, 'provider', r.provider_name, 'country', r.country, 'job_id', v_job);
          v_nn := v_nn + 1;
          if v_fair then
            perform security.work_item_report_v1('aer', r.course_id::text, 'entry_read', 'claimed', jsonb_build_object('provider_id', r.provider_id, 'field', 'entry_requirements', 'owner', 'aer-scheduled-read'));
            perform security.work_item_report_v1('aer', r.course_id::text, 'entry_read', 'succeeded', jsonb_build_object('provider_id', r.provider_id, 'field', 'entry_requirements', 'outcome', 'succeeded_with_result'));
          end if;
        exception when others then
          v_skip := v_skip || jsonb_build_object('course_id', r.course_id, 'why', left(sqlerrm, 300));
        end;
      end loop;
    end if;
  end if;

  -- (c) due entry pages fetched again (own lane and guard), unless Layer 4 is full
  -- 4 Nov 2026 (SS-021 F4, wc.aer_fair_on): a refresh is gated by the count only when its university has a matrix item waiting (a refresh that
  -- could raise or duplicate a review item); other due refreshes go ahead within batch.aer_schedule_matrix and the AI guard
  if (not v_bp or v_fair) and v_aim is null and v_mxmax > 0 then
    for r in select s.id, s.provider_id, s.read_via from pipeline.entry_matrix_sources s
              where s.status = 'read' and s.read_via <> 'stored'
                and (not v_bp or not exists (select 1 from pipeline.layer4_review_items i where i.status = 'pending' and i.field_code = 'entry_matrix_first_run'
                                                                                          and i.entity_id = s.provider_id))
                and s.read_at < now() - make_interval(days => security.pipeline_num_v1('entry.matrix_refresh_days', 30)::int)
                and security.entry_matrix_enabled_v1(s.provider_id)
              order by s.read_at, s.id limit v_mxmax loop
      if not p_preview then
        update pipeline.entry_matrix_sources f set status = 'found', attempts = 0, updated_at = now() where f.id = r.id and f.status = 'read';
      end if;
      v_mx := v_mx || jsonb_build_object('source_id', r.id, 'provider_id', r.provider_id, 'read_via', r.read_via);
      v_nm := v_nm + 1;
      if r.read_via = 'firecrawl' then v_fc := v_fc + 1; end if;
    end loop;
  end if;

  v_est := round((v_nh + v_nn) * v_cost, 4);
  -- 4 Nov 2026 (SS-021 F4): technically held and duplicate entry items are recorded for bounded technical recovery (records only; isolated)
  if not p_preview then
    begin
      v_tech := security.aer_technical_recovery_v1();
    exception when others then v_tech := jsonb_build_object('error', left(sqlerrm, 200));
    end;
  end if;
  if not p_preview then
    insert into pipeline.aer_schedule_checks(item_id, checked_at, outcome)
    select (c->>'item_id')::uuid, now(), c->>'outcome' from jsonb_array_elements(v_checked) c
    on conflict (item_id) do update set checked_at = excluded.checked_at, outcome = excluded.outcome;
    insert into pipeline.aer_schedule_runs(course_reads, corrections, matrix_pages, layer4_waiting, in_progress, back_pressure, used_before, room, refusal, estimate_usd, detail)
    values (v_nn, v_nh, v_nm, v_l4, v_prog, v_bp, v_used, v_room, v_why, v_est,
            jsonb_build_object('held', v_held, 'new', v_new, 'matrix', v_mx, 'skipped', v_skip, 'checked', jsonb_array_length(v_checked),
                               'fair', v_fair, 'room_ready', v_rr, 'technical', v_tech, 'parked_not_counted', v_parked,
                               'corrections_used_24h', v_cused, 'corrections_daily_max', v_cmax, 'corrections_room', v_croom));
  end if;
  return jsonb_build_object('preview', p_preview, 'course_reads', v_nn, 'corrections', v_nh, 'matrix_pages', v_nm, 'firecrawl_credits_estimate', v_fc,
    'estimate_usd', v_est, 'cost_per_course_usd', round(v_cost, 5), 'layer4_waiting', v_l4, 'in_progress', v_prog, 'layer4_max', v_l4max, 'back_pressure', v_bp,
    'used_24h', v_used, 'daily_max', v_daymax, 'room', v_room, 'refusal', v_why, 'matrix_refusal', case when v_aim is not null then 'AI reading is stopped (AI limits): ' || v_aim end,
    'balance_usd', v_bal, 'floor_usd', v_floor, 'runs_as', jsonb_build_object('owner', v_owner, 'role', v_orole, 'rank', v_orank, 'source', 'pipeline.field_gap_queue_control.owner'),
    'checked', v_checked, 'held', v_held, 'new', v_new, 'matrix', v_mx, 'skipped', v_skip)
    || jsonb_build_object('fair', v_fair, 'room_ready', v_rr, 'technical', v_tech, 'parked_not_counted', v_parked,
                            'corrections_used_24h', v_cused, 'corrections_daily_max', v_cmax, 'corrections_room', v_croom);
end $$;


ALTER FUNCTION "security"."aer_schedule_tick_v1"("p_preview" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_schedule_tick_v1"("p_preview" boolean) IS 'CF-247 scheduled AER reading: job aer-scheduled-read. Held course reads read again through D-R2, new course reads by eligibility rules (security.course_entry_read_enqueue_v1), due entry pages fetched again; bounded by the run size and the daily cap, the AI lanes and the OpenRouter floor, and Layer 4 back-pressure. With true: what the run would ask, nothing written.';



CREATE OR REPLACE FUNCTION "security"."aer_settlement_v1"("p_provider" "uuid") RETURNS TABLE("item_id" "uuid", "field_code" "text", "created_at" timestamp with time zone, "provider_id" "uuid", "cls" "text", "route" "text", "settlement" "text", "why" "text", "next_action" "text", "tries" integer, "last_refusal" "text", "rows_read" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with b as (
    select i.id, i.field_code, i.created_at, i.entity_type, i.entity_id, coalesce(c.provider_id, case when i.entity_type = 'provider' then i.entity_id end) pid, y.gate,
           c.lifecycle_status, pg.url pg_url, pg.evidence_id pg_ev, i.proposed_value->>'url' read_url,
           exists (select 1 from pipeline.manual_locks l where i.entity_type = 'course' and l.entity = 'course' and l.entity_id = i.entity_id and l.field = 'entry_requirements') locked,
           (select count(*)::int from pipeline.aer_read_supersessions s where s.old_item_id = i.id) tries,
           (select s.outcome from pipeline.aer_read_supersessions s where s.old_item_id = i.id and s.state = 'refused' order by s.requested_at desc limit 1) refusal,
           (select jsonb_array_length(coalesce(fe.value->'rows_read', '[]'::jsonb))::int from pipeline.aer_read_supersessions s join pipeline.field_enrich_items fe on fe.id = s.enrich_item_id
             where s.old_item_id = i.id order by s.requested_at desc limit 1) rows_read
      from pipeline.layer4_review_items i
      left join pipeline.layer4_item_readiness y on y.item_id = i.id
      left join catalogue.courses c on i.entity_type = 'course' and c.id = i.entity_id
      left join pipeline.coverage_course_pages pg on i.entity_type = 'course' and pg.course_id = i.entity_id
     where i.status = 'pending' and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run', 'entry_matrix_change')
       and (p_provider is null or coalesce(c.provider_id, case when i.entity_type = 'provider' then i.entity_id end) = p_provider)),
  r as (select b.*, security.aer_route_v1(b.field_code, b.gate) rt from b)
  select r.id, r.field_code, r.created_at, r.pid, coalesce(r.rt->>'class', 'unchecked'),
         case when r.rt->>'class' = 'drops_uncovered' and r.refusal ilike '%row limit%' then 'row_limit_stored'
              when r.rt->>'class' = 'drops_uncovered' and r.refusal ilike '%proof does not admit%' then 'identity' else r.rt->>'route' end,
         z.settlement, z.why, z.next_action, r.tries, r.refusal, r.rows_read
    from r cross join lateral (select * from (values (
      case when r.entity_type = 'course' and (coalesce(r.lifecycle_status, 'active') <> 'active' or r.pg_url is distinct from r.read_url) then 'stale'
           when r.gate is null then 'recoverable'
           when r.locked then 'needs_input'
           when r.rt->>'route' in ('review', 'review_except', 'matrix_except') then 'ready'
           when r.rt->>'class' = 'drops_uncovered' and r.tries = 0 and r.pg_ev is not null then 'recoverable'
           else 'needs_input' end,
      case when r.entity_type = 'course' and coalesce(r.lifecycle_status, 'active') <> 'active' then 'the course is no longer active'
           when r.entity_type = 'course' and r.pg_url is distinct from r.read_url then 'the course is now bound to another page: a new first read, not a correction'
           when r.gate is null then 'not yet checked by the completeness gate'
           when r.locked then 'the course''s entry requirements are locked by hand'
           when r.rt->>'route' = 'review' then 'every check passes'
           when r.rt->>'route' in ('review_except', 'matrix_except') then 'rows a person leaves out'
           when r.rt->>'class' = 'drops_uncovered' and r.refusal ilike '%row limit%' then 'the corrected read kept every printed requirement (' || coalesce(r.rows_read, 0) || ' rows) but is over the row limit; a re-read gives the same result'
           when r.rt->>'class' = 'drops_uncovered' and r.refusal ilike '%proof does not admit%' then 'the page''s identity proof does not admit entry requirements'
           when r.rt->>'class' = 'drops_uncovered' and r.tries = 0 and r.pg_ev is not null then 'printed requirements were dropped; a corrected read from the stored copy has not been tried'
           when r.rt->>'class' = 'drops_uncovered' and r.pg_ev is null then 'printed requirements were dropped and there is no stored copy to read again'
           when r.rt->>'class' = 'drops_uncovered' then 'the corrected read was refused on the same stored copy (' || coalesce(r.refusal, 'no reason') || '): the reader repeats itself on unchanged evidence'
           else coalesce(r.gate->'reasons'->>0, r.rt->>'remedy') end,
      case when r.entity_type = 'course' and (coalesce(r.lifecycle_status, 'active') <> 'active' or r.pg_url is distinct from r.read_url) then 'Reject the read (it no longer describes the course''s bound page)'
           when r.gate is null then 'job layer4-readiness gates it (never-gated items first)'
           when r.locked then 'leave it, or a Platform Admin lifts the lock'
           when r.rt->>'route' = 'review' then 'decide it in Layer 4: Approve all rows or Reject the read'
           when r.rt->>'route' in ('review_except', 'matrix_except') then 'decide it in Layer 4: Approve except the named rows, or Reject'
           when r.rt->>'class' = 'drops_uncovered' and r.refusal ilike '%row limit%' then 'a row boundary for the university (entry.max_rows_by_provider, Platform Admin); no new re-read until then'
           when r.rt->>'class' = 'drops_uncovered' and r.refusal ilike '%proof does not admit%' then 'confirm the course''s page (aer_course_identity)'
           when r.rt->>'class' = 'drops_uncovered' and r.tries = 0 and r.pg_ev is not null then 'one corrected read from the stored copy (E13 recovery pilot, or Re-read from stored evidence)'
           when r.rt->>'class' = 'drops_uncovered' then 'a person enters the dropped rows with their quotations (aer_read_rows_missing); no further re-read of this copy'
           when r.rt->>'route' in ('row_limit', 'source_is_matrix') then r.rt->>'remedy'
           when r.rt->>'route' = 'identity' then 'confirm which programme the page belongs to (aer_course_identity)'
           else coalesce(r.rt->>'remedy', 'see the gate reasons') end)) v(settlement, why, next_action)) z
$$;


ALTER FUNCTION "security"."aer_settlement_v1"("p_provider" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_source_check_v1"("p_provider" "uuid", "p_url" "text", "p_classes" "text"[], "p_how" "text" DEFAULT 'url'::"text", "p_sha" "text" DEFAULT NULL::"text", "p_bytes" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_url text := trim(coalesce(p_url, '')); p record; s record; v_ph text; v_sh text; v_ev uuid; v_bad text[]; v_pdf boolean; v_render boolean; v_on boolean; v_max numeric;
        c_classes constant text[] := array['country_table', 'international_qualification', 'national_qualification', 'undergraduate', 'postgraduate', 'course_specific'];  -- fixed: the classes of Platform Admin decision D3
begin
  if coalesce(p_how, '') not in ('url', 'pdf_upload') then return jsonb_build_object('ok', false, 'rule', 'how_unknown', 'reason', 'Attach an address or upload a PDF.'); end if;
  select x.id, coalesce(x.display_name, x.canonical_name) name, x.website into p from catalogue.providers x where x.id = p_provider;
  if p.id is null then return jsonb_build_object('ok', false, 'rule', 'provider_not_found', 'reason', 'Choose a provider.'); end if;
  if v_url !~* '^https?://[^/\s]+' then return jsonb_build_object('ok', false, 'rule', 'url_invalid', 'reason', 'Give the full address where the provider publishes it (https://...).'); end if;
  if p_classes is null or cardinality(p_classes) = 0 then return jsonb_build_object('ok', false, 'rule', 'class_required', 'reason', 'Choose at least one class.'); end if;
  v_bad := array(select unnest(p_classes) except select unnest(c_classes));
  if cardinality(v_bad) > 0 then return jsonb_build_object('ok', false, 'rule', 'class_unknown', 'reason', 'Unknown class: ' || array_to_string(v_bad, ', ')); end if;
  v_ph := security.site_host_v1(p.website); v_sh := security.site_host_v1(v_url);
  if v_ph is null then return jsonb_build_object('ok', false, 'rule', 'provider_no_website', 'reason', 'The provider has no website on record: record it on the provider first, so ownership can be checked.'); end if;
  if security.third_party_host_v1(v_url) then return jsonb_build_object('ok', false, 'rule', 'directory_site', 'reason', format('%s is a directory or third-party site, not the provider''s own.', v_sh)); end if;
  if v_sh is null or not (v_sh = v_ph or v_sh like '%.' || v_ph) then
    return jsonb_build_object('ok', false, 'rule', 'not_official_host', 'reason', format('The address is on %s, not on the provider''s own website %s (or a subdomain of it).', coalesce(v_sh, '?'), v_ph)); end if;
  select x.id, x.provider_id, x.status, x.read_at, x.content_hash, x.evidence_id, x.attempts into s from pipeline.entry_matrix_sources x where x.url = v_url order by (x.provider_id = p_provider) desc limit 1;
  if s.id is not null and s.provider_id <> p_provider then return jsonb_build_object('ok', false, 'rule', 'source_of_another_provider', 'reason', 'This address is another provider''s entry source.'); end if;
  if p_how = 'pdf_upload' then
    if coalesce(p_sha, '') !~ '^[0-9a-f]{64}$' then return jsonb_build_object('ok', false, 'rule', 'file_required', 'reason', 'Choose the PDF file.'); end if;
    v_max := security.pipeline_num_v1('entry.pdf_max_bytes', 20000000);
    if p_bytes is not null and p_bytes > v_max then return jsonb_build_object('ok', false, 'rule', 'file_too_large', 'reason', format('The file is %s MB; the most the reader takes is %s MB (entry.pdf_max_bytes).', round(p_bytes / 1048576.0, 1), round(v_max / 1048576.0, 1))); end if;
    select e.id into v_ev from pipeline.evidence_artifacts e where e.content_hash = p_sha and e.source_url = v_url limit 1;
  end if;
  v_pdf := p_how = 'pdf_upload' or v_url ~* '\.pdf($|[?#])';
  v_render := not v_pdf and coalesce(security.toolset_setting('pipeline', 'entry.render_hosts'), '[]'::jsonb) ? lower(substring(v_url from '^https?://(?:www\.)?([^/:?#]+)'));
  v_on := security.pipeline_num_v1('entry.matrix_enabled', 0) >= 1 and (not v_pdf or security.pipeline_num_v1('entry.pdf_enabled', 0) >= 1);
  return jsonb_build_object('ok', true, 'provider', p.name, 'host', v_sh, 'official_host', v_ph, 'ownership', 'official_host',
    'reuse', case when v_ev is not null then 'stored_copy' when s.id is not null then 'source' end, 'source_id', s.id, 'source_status', s.status, 'last_read', s.read_at,
    'reader', case when v_pdf then 'Entry matrix reader: PDF tables (ruled cells)' when v_render then 'Entry matrix reader: rendered page' else 'Entry matrix reader: web page tables' end,
    'reader_exists', true, 'reading_on', v_on,
    'machine_admission', case when p_how = 'pdf_upload' then 'Never: an uploaded copy is decided by a person in Layer 4.' else 'Possible only when every condition of decision D1 holds; otherwise a person decides in Layer 4.' end,
    'next_action', case when not v_on then 'Reading is switched off (entry.matrix_enabled or entry.pdf_enabled): the source waits.'
                        when v_ev is not null then 'This file is already stored for this address: its read is not repeated.'
                        when s.id is not null and s.status = 'read' and p_how = 'url' then 'Already a source and read: the current copy is not read again (use Read again to fetch a new copy).'
                        when s.id is not null and s.status in ('failed', 'inactive') and p_how = 'url' then 'Already a source that stopped: attaching asks the fetch again.'
                        when s.id is not null and s.status = 'robots_disallowed' and p_how = 'url' then 'The site does not allow this address to be fetched: upload the PDF instead.'
                        when p_how = 'pdf_upload' then 'The file is stored as this source''s copy and read once; its rows go to Layer 4.'
                        else 'Added to the sources: fetched and read by the next entry-matrix-read run; its rows go to Layer 4.' end);
end $_$;


ALTER FUNCTION "security"."aer_source_check_v1"("p_provider" "uuid", "p_url" "text", "p_classes" "text"[], "p_how" "text", "p_sha" "text", "p_bytes" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_source_check_v1"("p_provider" "uuid", "p_url" "text", "p_classes" "text"[], "p_how" "text", "p_sha" "text", "p_bytes" bigint) IS 'CF-247 F-AER.04 D3: checks an entry-requirements source a person attaches: ownership (provider''s own website host), classes, reuse of an existing source or stored copy, the existing reader, whether reading is on.';



CREATE OR REPLACE FUNCTION "security"."aer_source_class_v1"("p_provider" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 AER missing-university strategy §E: a report classification, never a status value. From the AER reconcile disposition
  -- (pipeline.aer_provider_coverage) and the source inventory: no_source, source_found (a verified source not yet attached), read_held,
  -- awaiting_layer4, active, course_only, evidenced_non_publication.
  select case
    when c.disposition is null or c.disposition = 'not_discovered' then
      -- a source attached since the last AER reconcile, or a verified source not yet attached
      case when exists (select 1 from pipeline.entry_matrix_sources s where s.provider_id = p_provider)
             or exists (select 1 from pipeline.aer_source_inventory i where i.provider_id = p_provider and i.url is not null
                          and i.outcome in ('verified_attachable', 'verified_general_only', 'verified_rendered_only'))
           then 'source_found' else 'no_source' end
    when c.disposition in ('source_held', 'reader_failed') then 'read_held'
    when c.disposition = 'awaiting_layer4' then 'awaiting_layer4'
    when c.disposition = 'active_verified' then 'active'
    when c.disposition = 'course_only' then 'course_only'
    when c.disposition in ('source_not_published_evidenced', 'not_applicable_evidenced') then 'evidenced_non_publication'
    else c.disposition end
  from (select 1) one left join pipeline.aer_provider_coverage c on c.provider_id = p_provider
$$;


ALTER FUNCTION "security"."aer_source_class_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_source_class_v1"("p_provider" "uuid") IS 'CF-247 AER missing-university strategy §E: report classification of a provider''s AER coverage (no_source, source_found, read_held, awaiting_layer4, active, course_only, evidenced_non_publication) from pipeline.aer_provider_coverage and pipeline.aer_source_inventory. Not a status value. Read-only.';



CREATE OR REPLACE FUNCTION "security"."aer_source_discover_report_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with last as (select distinct on (provider_id) * from pipeline.aer_source_discover_requests order by provider_id, requested_at desc),
  tries as (select provider_id, count(*) filter (where outcome in ('no_entry_page', 'course_pages_found', 'failed')) n from pipeline.aer_source_discover_requests group by 1)
  select jsonb_build_object('contract', 'aer-source-discover-report-v1', 'as_at', now(), 'on', security.pipeline_num_v1('aer.source_discover_on', 0) >= 1,
    'requests_by_outcome', (select coalesce(jsonb_object_agg(coalesce(outcome, 'open'), n), '{}'::jsonb) from (select outcome, count(*) n from pipeline.aer_source_discover_requests group by 1) z),
    'providers_asked', (select count(distinct provider_id) from pipeline.aer_source_discover_requests),
    'providers_with_entry_source_now', (select count(distinct q.provider_id) from pipeline.aer_source_discover_requests q where exists (select 1 from pipeline.entry_matrix_sources m where m.provider_id = q.provider_id)),
    'credits_24h', (select coalesce(sum(u.units), 0) from pipeline.coverage_vendor_usage u where u.at > now() - make_interval(hours => 24) and security.fc_purpose_group_v1(u.purpose) = 'central'
                      and exists (select 1 from pipeline.aer_source_discover_requests q where q.provider_id = u.provider_id and u.at >= q.requested_at)), -- fixed: report window
    'exceptions', (select coalesce(jsonb_agg(jsonb_build_object('provider_id', l.provider_id, 'provider', coalesce(p.display_name, p.canonical_name), 'website', p.website, 'tries', t.n,
                                   'last_outcome', l.outcome, 'last_at', l.outcome_at,
                                   'next_action', 'A person adds the entry-requirements page (public.admin_entry_matrix_seed) or confirms the provider has none.') order by p.canonical_name), '[]'::jsonb)
                     from last l join tries t on t.provider_id = l.provider_id join catalogue.providers p on p.id = l.provider_id
                    where t.n >= security.pipeline_num_v1('aer.source_discover_max_tries', 3) and not exists (select 1 from pipeline.entry_matrix_sources m where m.provider_id = l.provider_id)))
$$;


ALTER FUNCTION "security"."aer_source_discover_report_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_source_discover_report_v1"() IS 'CF-247 F-AER.01 (read only): requests job aer-source-discover made and their outcomes, credits used in 24 hours, providers that now have an entry source, and the exception queue (tries used up, no entry page).';



CREATE OR REPLACE FUNCTION "security"."aer_source_discover_v1"("p_preview" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_cap numeric := security.pipeline_num_v1('aer.source_discover_credits_per_day', 200); v_recheck int := security.pipeline_num_v1('aer.source_discover_recheck_days', 30)::int;
        v_tries int := security.pipeline_num_v1('aer.source_discover_max_tries', 3)::int; v_per numeric; v_used numeric; v_room int; v_settled int := 0; v_asked int := 0; r record; v_out text; v_cr numeric;
begin
  if security.pipeline_num_v1('aer.source_discover_on', 0) < 1 then return jsonb_build_object('on', false); end if;
  -- (a) settle open requests from what the search recorded
  for r in select q.id, q.provider_id, q.requested_at, s.state, s.searched_at, s.requested_at s_req, s.evidence, s.found, s.updated_at s_upd
             from pipeline.aer_source_discover_requests q left join pipeline.provider_central_search s on s.provider_id = q.provider_id
            where q.outcome is null loop
    v_out := case when exists (select 1 from pipeline.entry_matrix_sources m where m.provider_id = r.provider_id) then 'entry_source_found'
                  when r.searched_at is not null and r.searched_at >= r.requested_at then
                       case when exists (select 1 from pipeline.coverage_course_pages g where g.provider_id = r.provider_id and g.status = 'bound') then 'course_pages_found' else 'no_entry_page' end
                  -- 12 Nov 2026 (F-AER.04): a refusal or an error settles the request only when it was recorded after the request (never the 22 Oct evidence)
                  when r.s_req is null and r.evidence ? 'refusal' and r.s_upd >= r.requested_at then 'refused'
                  when (r.state = 'failed' or (r.evidence ? 'error' and r.s_req is null)) and r.s_upd >= r.requested_at then 'failed'
                  else null end;
    if v_out is not null and not p_preview then
      select coalesce(sum(u.units), 0) into v_cr from pipeline.coverage_vendor_usage u
       where u.provider_id = r.provider_id and u.at >= r.requested_at and security.fc_purpose_group_v1(u.purpose) = 'central';
      update pipeline.aer_source_discover_requests set outcome = v_out, outcome_at = now(), credits = v_cr,
             detail = detail || jsonb_build_object('search_state', r.state, 'searched_at', r.searched_at, 'evidence', r.evidence,
                                                   'entry_suggestions', (select count(*) from jsonb_array_elements(coalesce(r.found, '[]'::jsonb)) e where e->>'kind' = 'entry_requirements'))
       where id = r.id;
      v_settled := v_settled + 1;
    end if;
  end loop;
  -- (b) credits the asked providers used in the last 24 hours, and the measured average a provider
  select coalesce(sum(u.units), 0) into v_used from pipeline.coverage_vendor_usage u
   where u.at > now() - make_interval(hours => 24) and security.fc_purpose_group_v1(u.purpose) = 'central' -- fixed: the daily limit counts the last 24 hours
     and exists (select 1 from pipeline.aer_source_discover_requests q where q.provider_id = u.provider_id and u.at >= q.requested_at);
  select coalesce(round(sum(units) / nullif(count(distinct provider_id), 0), 1), 4) into v_per from pipeline.coverage_vendor_usage where purpose = 'central_map';
  v_per := greatest(v_per, 1);
  -- requests still open are planned at the average too
  v_used := v_used + v_per * (select count(*) from pipeline.aer_source_discover_requests q where q.outcome is null
                                and not exists (select 1 from pipeline.coverage_vendor_usage u where u.provider_id = q.provider_id and u.at >= q.requested_at));
  v_room := greatest(0, floor((v_cap - v_used) / v_per))::int;
  -- (c) ask the central-page search for that many more providers with nothing stored
  for r in select n.provider_id from security.aer_no_source_route_v1() n
             join catalogue.providers p on p.id = n.provider_id
            where n.route = 'nothing_stored' and p.website ~* '^https?://' and not security.third_party_host_v1(p.website)
              and not exists (select 1 from pipeline.aer_source_discover_requests q where q.provider_id = n.provider_id
                                and (q.outcome is null or (q.outcome in ('no_entry_page', 'course_pages_found', 'failed') and q.outcome_at > now() - make_interval(days => v_recheck))
                                     or (q.outcome = 'refused' and q.outcome_at > now() - make_interval(hours => 24)))) -- fixed: a refusal is asked again after a day
              and (select count(*) from pipeline.aer_source_discover_requests q where q.provider_id = n.provider_id and q.outcome in ('no_entry_page', 'course_pages_found', 'failed')) < v_tries
            order by (select count(*) from catalogue.courses c where c.provider_id = n.provider_id and c.lifecycle_status = 'active') desc, n.provider_id
            limit v_room loop
    if not p_preview then
      insert into pipeline.provider_central_search(provider_id, state, requested_at, attempts, updated_at) values (r.provider_id, 'queued', now(), 0, now())
      on conflict (provider_id) do update set state = case when pipeline.provider_central_search.state = 'leased' and pipeline.provider_central_search.leased_until > now() then pipeline.provider_central_search.state else 'queued' end,
             requested_at = now(), attempts = 0, updated_at = now();
      insert into pipeline.aer_source_discover_requests(provider_id, detail) values (r.provider_id, jsonb_build_object('planned_credits', v_per, 'route', 'nothing_stored'));
    end if;
    v_asked := v_asked + 1;
  end loop;
  return jsonb_build_object('on', true, 'preview', p_preview, 'settled', v_settled, 'asked', v_asked, 'credits_used_24h_or_planned', v_used, 'credits_per_provider', v_per, 'cap', v_cap)
         || jsonb_build_object('campaign', security.aer_discovery_campaign_ask_v1(p_preview));
end $$;


ALTER FUNCTION "security"."aer_source_discover_v1"("p_preview" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_source_discover_v1"("p_preview" boolean) IS 'CF-247 F-AER.01: one run of job aer-source-discover: settles earlier requests from what the central-page search recorded, then asks the search to look for entry pages for more providers with nothing stored, within aer.source_discover_credits_per_day (measured). Makes no Firecrawl call itself; preview = true changes nothing.';



CREATE OR REPLACE FUNCTION "security"."aer_source_inventory_verify_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 AER missing-university strategy: passed when every inventory source marked for attachment is in pipeline.entry_matrix_sources
  -- (the paste file has been applied) and has been read (status read, a stored copy hash).
  with a as (select i.provider_id, i.url, s.id source_id, s.status, s.content_hash from pipeline.aer_source_inventory i
               left join pipeline.entry_matrix_sources s on s.provider_id = i.provider_id and s.url = i.url where i.attach)
  select jsonb_build_object('passed', count(*) > 0 and count(*) filter (where a.source_id is null) = 0 and count(*) filter (where a.status <> 'read' or a.content_hash is null) = 0,
    'measure', jsonb_build_object('to_attach', count(*), 'attached', count(a.source_id), 'read', count(*) filter (where a.status = 'read' and a.content_hash is not null)),
    'evidence', jsonb_build_object('issue', p_issue, 'at', now(), 'not_attached', coalesce(jsonb_agg(a.url) filter (where a.source_id is null), '[]'::jsonb)))
    from a
$$;


ALTER FUNCTION "security"."aer_source_inventory_verify_v1"("p_issue" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_source_inventory_verify_v1"("p_issue" bigint) IS 'CF-247 AER missing-university strategy: verify of remedy aer_source_attach (the inventory sources marked for attachment are in pipeline.entry_matrix_sources and read). Returns {passed, measure, evidence}. Read-only.';



CREATE OR REPLACE FUNCTION "security"."aer_supersession_settle_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_n int := 0;
begin
  for r in select s.id, e.id e_id, e.reason
             from pipeline.aer_read_supersessions s left join pipeline.field_enrich_items e on e.id = s.enrich_item_id
            where s.state = 'requested' and s.enrich_item_id is not null
              and (e.id is null or (e.state = 'skipped' and e.updated_at < now() - interval '10 minutes'))  -- fixed: the read's claim timer
            for update of s skip locked loop
    perform security.aer_read_supersession_close_v1(r.id, 'refused',
      case when r.e_id is null then 'the corrected read was not made: its read no longer exists'
           else 'the corrected read was not made: ' || coalesce(nullif(btrim(r.reason), ''), 'skipped by the reader') end, null, null);
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;


ALTER FUNCTION "security"."aer_supersession_settle_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_supersession_settle_v1"() IS 'CF-247 F-AER.02: closes as refused every corrected read (aer_read_supersessions) whose read was skipped before reading or is gone, with the reader''s reason, so its waiting item is not blocked. Run by security.aer_schedule_tick_v1.';



CREATE OR REPLACE FUNCTION "security"."aer_technical_recovery_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int := security.pipeline_num_v1('wc.tick_batch', 500)::int; r record; v_t int := 0; v_d int := 0; v_ok int := 0; v_e13 jsonb; ru jsonb; v_res jsonb;
        v_same int := 0; v_by jsonb := '{}'::jsonb; v_pol text;
begin
  if security.pipeline_num_v1('wc.on', 1) < 1 then return jsonb_build_object('held', 'wc.on is 0'); end if;
  for r in select i.id, i.entity_id, i.entity_type, i.field_code, c.provider_id, w.stage, w.evidence_version, w.next_eligible_at
             from pipeline.layer4_review_items i join pipeline.layer4_item_readiness x on x.item_id = i.id
             left join catalogue.courses c on i.entity_type = 'course' and c.id = i.entity_id
             join pipeline.work_review_categories rc on rc.category = 'aer'
             left join pipeline.work_items w on w.lane = 'aer_technical' and w.entity = i.id::text and w.work_kind = 'l4_item'
            where i.status = 'pending' and i.field_code = any (rc.field_codes) and x.readiness = 'technical_blocked'
              and coalesce(w.failure_class, '') <> 'duplicate'
            order by i.created_at, i.id limit v_n loop
    ru := security.aer_recovery_rule_v1(r.id);
    -- an unchanged condition is not reported again (it is waiting for something that has not happened); a due retry or recheck is
    if r.evidence_version is not distinct from ru->>'condition_key' and not (r.stage in ('retry_wait', 'deferred', 'eligible') and coalesce(r.next_eligible_at, now()) <= now()) then
      v_same := v_same + 1; continue;
    end if;
    v_pol := case ru->>'class' when 'row_limit' then 'aer_row_limit' when 'unchanged_evidence' then 'aer_unchanged_evidence' when 'reread_eligible' then 'aer_reread_eligible'
                               when 'changed_conditions' then 'aer_reread_eligible' when 'stale' then 'aer_stale' when 'transient' then 'transient' else 'aer_human_input' end;
    if ru->>'class' in ('decision', 'ready') or (ru->>'class' = 'human_assisted' and (ru->>'intervention') is not null) then
      v_res := security.work_item_report_v1('aer_technical', r.id::text, 'l4_item', 'review', jsonb_build_object(
                 'review_ref', case when (ru->>'intervention') is not null then 'intervention:' || (ru->>'intervention') else 'layer4:' || r.id end,
                 'owner', 'aer-scheduled-read', 'field', r.field_code, 'provider_id', coalesce(r.provider_id, case when r.entity_type = 'provider' then r.entity_id end),
                 'evidence_version', ru->>'condition_key'));
    else
      v_res := security.work_item_report_v1('aer_technical', r.id::text, 'l4_item', 'failed', jsonb_build_object(
                 'class', v_pol, 'owner', 'aer-scheduled-read', 'field', r.field_code,
                 'provider_id', coalesce(r.provider_id, case when r.entity_type = 'provider' then r.entity_id end),
                 'message', ru->>'class' || ': ' || coalesce(ru->>'why', ru->>'next_action'), 'evidence', ru - 'condition_key', 'evidence_version', ru->>'condition_key'));
    end if;
    -- §5: the hold keeps its blocker, next action and time, and why an identical retry is prohibited
    update pipeline.work_items w set unresolved_blocker = coalesce(w.unresolved_blocker, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
             'class', ru->>'class', 'next_action', ru->>'next_action', 'next_at', ru->'next_at', 'authority', ru->>'authority',
             'retry_prohibited', ru->>'retry_prohibited', 'intervention', ru->'intervention', 'last_attempt', ru->'last_attempt',
             'evidence_used', ru->>'evidence_used', 'evidence_now', ru->>'evidence_now', 'reader_revision', ru->'reader_revision', 'at', now())),
           evidence_version = ru->>'condition_key', updated_at = now()
     where w.lane = 'aer_technical' and w.entity = r.id::text and w.work_kind = 'l4_item';
    v_by := jsonb_set(v_by, array[ru->>'class'], to_jsonb(coalesce((v_by->>(ru->>'class'))::int, 0) + 1));
    v_t := v_t + 1;
  end loop;
  for r in select z.* from (
             select i.id, i.entity_id, i.entity_type, i.field_code, c.provider_id,
                    first_value(i.id) over (partition by i.entity_id, i.field_code order by i.created_at, i.id) keep,
                    row_number() over (partition by i.entity_id, i.field_code order by i.created_at, i.id) rn
               from pipeline.layer4_review_items i left join catalogue.courses c on i.entity_type = 'course' and c.id = i.entity_id
               join pipeline.work_review_categories rc on rc.category = 'aer'
              where i.status = 'pending' and i.field_code = any (rc.field_codes)) z
            where z.rn > 1 and not exists (select 1 from pipeline.work_items w where w.lane = 'aer_technical' and w.entity = z.id::text and w.work_kind = 'l4_item'
                                                                              and w.failure_class = 'duplicate' and w.stage = 'parked')
            limit v_n loop
    perform security.work_item_report_v1('aer_technical', r.id::text, 'l4_item', 'failed', jsonb_build_object(
              'class', 'duplicate', 'owner', 'aer-scheduled-read', 'field', r.field_code,
              'provider_id', coalesce(r.provider_id, case when r.entity_type = 'provider' then r.entity_id end),
              'message', 'duplicate of the older waiting item', 'evidence', jsonb_build_object('kept_item', r.keep)));
    update pipeline.work_items w set unresolved_blocker = coalesce(w.unresolved_blocker, '{}'::jsonb) || jsonb_build_object('class', 'duplicate',
             'next_action', 'none: the older waiting item ' || r.keep || ' is the one decided', 'retry_prohibited', 'a duplicate is never worked separately')
     where w.lane = 'aer_technical' and w.entity = r.id::text and w.work_kind = 'l4_item';
    v_d := v_d + 1;
  end loop;
  -- duplicates parked before this change get the same next action (IQ-00232)
  update pipeline.work_items w set unresolved_blocker = coalesce(w.unresolved_blocker, '{}'::jsonb) || jsonb_build_object('class', 'duplicate',
           'next_action', 'none: the older waiting item ' || coalesce(w.evidence->-1->'evidence'->>'kept_item', 'of the same course') || ' is the one decided',
           'retry_prohibited', 'a duplicate is never worked separately')
   where w.lane = 'aer_technical' and w.work_kind = 'l4_item' and w.failure_class = 'duplicate' and w.stage = 'parked' and coalesce(w.unresolved_blocker->>'next_action', '') = '';
  for r in select w.entity from pipeline.work_items w
            where w.lane = 'aer_technical' and w.work_kind = 'l4_item' and w.stage <> 'done'
              and not exists (select 1 from pipeline.layer4_review_items i left join pipeline.layer4_item_readiness x on x.item_id = i.id
                               where i.id::text = w.entity and i.status = 'pending'
                                 and (case when w.failure_class = 'duplicate' then true else x.readiness = 'technical_blocked' end))
            limit v_n loop
    perform security.work_item_report_v1('aer_technical', r.entity, 'l4_item', 'succeeded', jsonb_build_object('outcome', 'succeeded_with_result'));
    v_ok := v_ok + 1;
  end loop;
  begin
    v_e13 := security.aer_e13_recover_v1(false);
  exception when others then v_e13 := jsonb_build_object('error', left(sqlerrm, 200));
  end;
  return jsonb_build_object('technical_checked', v_t, 'unchanged', v_same, 'by_class', v_by, 'duplicates_parked', v_d, 'recovered', v_ok, 'e13_recover', v_e13);
end $$;


ALTER FUNCTION "security"."aer_technical_recovery_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_title_identity_courses_v1"() RETURNS TABLE("course_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  with s as (select security.pipeline_num_v1('aer.title_identity_on', 0) >= 1 on_,
                    coalesce(security.toolset_setting('pipeline', 'aer.eligible_countries'), '[]'::jsonb) cc,
                    coalesce(security.toolset_setting('pipeline', 'aer.title_identity_bases'), '[]'::jsonb) bases,
                    security.pipeline_num_v1('aer.title_identity_min_margin', 0.1) margin,
                    coalesce(security.l4_shared_hosts_v1(), '{}'::text[]) shared),
  b as (select distinct on (g.course_id) g.course_id, g.provider_id, g.url, g.score, g.runner_up, g.candidates, g.identity_basis
          from pipeline.coverage_course_pages g cross join s where s.on_ and g.status = 'bound' and s.bases ? coalesce(g.identity_basis, '')
         order by g.course_id, g.bound_at desc nulls last),
  c as (select b.*, x.canonical_title, l.code lvl, security.site_host_v1(b.url) host,
               coalesce(nullif(btrim(b.candidates->>'h1'), ''), nullif(btrim(split_part(coalesce(b.candidates->>'page_title', ''), ' | ', 1)), '')) h1
          from b join catalogue.courses x on x.id = b.course_id and x.lifecycle_status = 'active'
          join catalogue.providers p on p.id = x.provider_id left join ref.countries k on k.id = p.country_id
          join ref.study_levels l on l.id = x.study_level_id cross join s
         where s.cc ? coalesce(k.iso_alpha2, '')),
  h as (select pr.provider_id, security.provider_hosts_v1(pr.provider_id) hosts from (select distinct provider_id from c) pr),
  d as (select c.*, regexp_replace(lower(coalesce(c.canonical_title, '')), '[^a-z0-9]+', '', 'g') tn, regexp_replace(lower(coalesce(c.h1, '')), '[^a-z0-9]+', '', 'g') hn,
               case when c.lvl in ('bachelor', 'bachelor_honours') then '\mbachelor' when c.lvl like 'masters%' then '\mmaster'
                    when c.lvl = 'graduate_certificate' then '\mgraduate certificate' when c.lvl = 'graduate_diploma' then '\mgraduate diploma'
                    when c.lvl = 'advanced_diploma' then '\madvanced diploma' when c.lvl = 'diploma' then '\mdiploma' when c.lvl = 'associate_degree' then '\massociate degree'
                    when c.lvl = 'certificate_i' then '\mcertificate i\M' when c.lvl = 'certificate_ii' then '\mcertificate ii\M'
                    when c.lvl = 'certificate_iii' then '\mcertificate iii\M' when c.lvl = 'certificate_iv' then '\mcertificate iv\M'
                    when c.lvl = 'doctorate' then '\m(doctor|phd)' when c.lvl = 'foundation' then '\mfoundation' end kw -- fixed: the same credential words as security.aer_title_identity_ok_v1
          from c join h on h.provider_id = c.provider_id cross join s
         where c.host is not null and exists (select 1 from unnest(h.hosts) hh where c.host = hh or c.host like '%.' || hh)
           and not (c.host = any (s.shared))
           and (c.runner_up is null or coalesce(c.score, 0) - c.runner_up >= s.margin))
  select d.course_id from d
   where d.h1 is not null and length(d.tn) >= 6 -- fixed: as in security.aer_title_identity_ok_v1
     and (d.hn = d.tn or (right(d.hn, length(d.tn)) = d.tn and left(d.hn, length(d.hn) - length(d.tn)) ~ '^[a-z]{0,5}[0-9]{2,8}[a-z]{0,2}$')) -- fixed: as in security.aer_title_identity_ok_v1
     and d.kw is not null and lower(d.h1) ~ d.kw
     and not (d.lvl = 'diploma' and lower(d.h1) ~ '\m(graduate|advanced) diploma')
     and not exists (select 1 from pipeline.coverage_course_pages o where o.url = d.url and o.status = 'bound' and o.provider_id <> d.provider_id)
     and not exists (select 1 from pipeline.coverage_course_pages o join catalogue.courses oc on oc.id = o.course_id and oc.lifecycle_status = 'active'
                      where o.url = d.url and o.status = 'bound' and o.course_id <> d.course_id)
$_$;


ALTER FUNCTION "security"."aer_title_identity_courses_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_title_identity_courses_v1"() IS 'CF-247 F-AER.01 (read only, set-based): every course whose title-matched bound page passes the own-site title and study-level rule; the same rule as security.aer_title_identity_ok_v1, for the AER population.';



CREATE OR REPLACE FUNCTION "security"."aer_title_identity_ok_v1"("p_course" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare c record; g pipeline.coverage_course_pages%rowtype; v_host text; v_hosts text[]; v_h1 text; v_tn text; v_hn text; v_lvl text; v_kw text; v_margin numeric;
begin
  if security.pipeline_num_v1('aer.title_identity_on', 0) < 1 then return jsonb_build_object('ok', false, 'why', 'switch_off'); end if;
  select x.id, x.provider_id, x.canonical_title, x.lifecycle_status, l.code lvl_code, k.iso_alpha2 cc into c
    from catalogue.courses x join catalogue.providers p on p.id = x.provider_id left join ref.countries k on k.id = p.country_id left join ref.study_levels l on l.id = x.study_level_id
   where x.id = p_course;
  if c.id is null or c.lifecycle_status <> 'active' then return jsonb_build_object('ok', false, 'why', 'course_not_active'); end if;
  if not coalesce(security.toolset_setting('pipeline', 'aer.eligible_countries'), '[]'::jsonb) ? coalesce(c.cc, '') then return jsonb_build_object('ok', false, 'why', 'country_not_in_scope'); end if;
  if c.lvl_code is null then return jsonb_build_object('ok', false, 'why', 'no_study_level'); end if;
  select * into g from pipeline.coverage_course_pages p where p.course_id = p_course and p.status = 'bound' order by p.bound_at desc nulls last limit 1;
  if g.course_id is null then return jsonb_build_object('ok', false, 'why', 'no_bound_page'); end if;
  if not coalesce(security.toolset_setting('pipeline', 'aer.title_identity_bases'), '[]'::jsonb) ? coalesce(g.identity_basis, '') then
    return jsonb_build_object('ok', false, 'why', 'basis_not_title', 'basis', g.identity_basis);
  end if;
  -- own verified site, not a shared host, no other provider at this address
  v_host := security.site_host_v1(g.url); v_hosts := security.provider_hosts_v1(c.provider_id);
  if v_host is null or not exists (select 1 from unnest(v_hosts) h where v_host = h or v_host like '%.' || h) then
    return jsonb_build_object('ok', false, 'why', 'not_own_site', 'host', v_host, 'provider_hosts', to_jsonb(v_hosts));
  end if;
  if v_host = any (coalesce(security.l4_shared_hosts_v1(), '{}'::text[])) then return jsonb_build_object('ok', false, 'why', 'shared_host', 'host', v_host); end if;
  if exists (select 1 from pipeline.coverage_course_pages o where o.url = g.url and o.status = 'bound' and o.provider_id <> c.provider_id) then
    return jsonb_build_object('ok', false, 'why', 'cross_provider_page');
  end if;
  if exists (select 1 from pipeline.coverage_course_pages o join catalogue.courses oc on oc.id = o.course_id and oc.lifecycle_status = 'active'
              where o.url = g.url and o.status = 'bound' and o.course_id <> p_course) then
    return jsonb_build_object('ok', false, 'why', 'page_bound_to_another_course');
  end if;
  -- unique and unambiguous
  v_margin := case when g.runner_up is null then null else coalesce(g.score, 0) - g.runner_up end;
  if v_margin is not null and v_margin < security.pipeline_num_v1('aer.title_identity_min_margin', 0.1) then
    return jsonb_build_object('ok', false, 'why', 'ambiguous_match', 'score', g.score, 'runner_up', g.runner_up);
  end if;
  -- the page heading equals the course title (letters and digits only; a leading course code allowed)
  v_h1 := coalesce(nullif(btrim(g.candidates->>'h1'), ''), nullif(btrim(split_part(coalesce(g.candidates->>'page_title', ''), ' | ', 1)), ''));
  if v_h1 is null then return jsonb_build_object('ok', false, 'why', 'no_page_heading'); end if;
  v_tn := regexp_replace(lower(coalesce(c.canonical_title, '')), '[^a-z0-9]+', '', 'g');
  v_hn := regexp_replace(lower(v_h1), '[^a-z0-9]+', '', 'g');
  if length(v_tn) < 6 then return jsonb_build_object('ok', false, 'why', 'generic_title'); end if; -- fixed: a title of under six letters is too generic to identify a course
  if not (v_hn = v_tn or (right(v_hn, length(v_tn)) = v_tn and left(v_hn, length(v_hn) - length(v_tn)) ~ '^[a-z]{0,5}[0-9]{2,8}[a-z]{0,2}$')) then -- fixed: the shape of a leading course code (e.g. CHC52025, DHY5)
    return jsonb_build_object('ok', false, 'why', 'title_mismatch', 'h1', v_h1, 'title', c.canonical_title);
  end if;
  -- the heading names the course's study level (credential words)
  v_lvl := c.lvl_code;
  v_kw := case
            when v_lvl in ('bachelor', 'bachelor_honours') then '\mbachelor'
            when v_lvl like 'masters%' then '\mmaster'
            when v_lvl = 'graduate_certificate' then '\mgraduate certificate'
            when v_lvl = 'graduate_diploma' then '\mgraduate diploma'
            when v_lvl = 'advanced_diploma' then '\madvanced diploma'
            when v_lvl = 'diploma' then '\mdiploma'
            when v_lvl = 'associate_degree' then '\massociate degree'
            when v_lvl = 'certificate_i' then '\mcertificate i\M'
            when v_lvl = 'certificate_ii' then '\mcertificate ii\M'
            when v_lvl = 'certificate_iii' then '\mcertificate iii\M'
            when v_lvl = 'certificate_iv' then '\mcertificate iv\M'
            when v_lvl = 'doctorate' then '\m(doctor|phd)'
            when v_lvl = 'foundation' then '\mfoundation'
            else null end; -- fixed: credential words of ref.study_levels; a level with no credential word cannot be proved from a heading
  if v_kw is null then return jsonb_build_object('ok', false, 'why', 'level_not_provable', 'level', v_lvl); end if;
  if lower(v_h1) !~ v_kw then return jsonb_build_object('ok', false, 'why', 'level_mismatch', 'level', v_lvl, 'h1', v_h1); end if;
  if v_lvl = 'diploma' and lower(v_h1) ~ '\m(graduate|advanced) diploma' then return jsonb_build_object('ok', false, 'why', 'level_mismatch', 'level', v_lvl, 'h1', v_h1); end if;
  return jsonb_build_object('ok', true, 'rule', 'aer-title-identity-v1', 'basis', g.identity_basis, 'url', g.url, 'host', v_host, 'h1', v_h1, 'level', v_lvl,
                            'score', g.score, 'runner_up', g.runner_up);
end $_$;


ALTER FUNCTION "security"."aer_title_identity_ok_v1"("p_course" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_title_identity_ok_v1"("p_course" "uuid") IS 'CF-247 F-AER.01 (read only): whether a course''s title-matched bound page may be used for entry requirements: own verified provider host (not shared, no other provider or course at the address), unique match (margin aer.title_identity_min_margin), heading equals the course title, heading names the study level. Answers why it refused; the evidence when it passes. Off while aer.title_identity_on is 0.';



CREATE OR REPLACE FUNCTION "security"."aer_v2_identity_fixture_report_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'cases', count(*),
    'bound', count(*) filter (where rule_decision = 'bound'),
    'bound_correct', count(*) filter (where rule_decision = 'bound' and gold_label = 'this_course'),
    'incorrect_bindings', count(*) filter (where rule_decision = 'bound' and gold_label <> 'this_course'),
    'held_this_course', count(*) filter (where rule_decision = 'held' and gold_label = 'this_course'),
    'held_not_this_course', count(*) filter (where rule_decision = 'held' and gold_label <> 'this_course'),
    'by_stratum', (select jsonb_object_agg(stratum, x) from (select stratum, jsonb_build_object('cases', count(*), 'bound', count(*) filter (where rule_decision = 'bound'),
                     'gold_this_course', count(*) filter (where gold_label = 'this_course')) x from pipeline.aer_v2_identity_fixture group by stratum) s),
    'held_reasons', (select jsonb_object_agg(rule_reason, n) from (select rule_reason, count(*) n from pipeline.aer_v2_identity_fixture where rule_decision = 'held' group by 1) h))
  from pipeline.aer_v2_identity_fixture
$$;


ALTER FUNCTION "security"."aer_v2_identity_fixture_report_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_v2_identity_fixture_report_v1"() IS 'AER v2 stored-page identity: precision of the settle rule on its 200-case fixture (incorrect_bindings must be 0), recall on the gold this_course cases, by stratum and held reason.';



CREATE OR REPLACE FUNCTION "security"."aer_v2_identity_settle_check_v1"("p_course" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare g record; v_chk jsonb; v_twin boolean; v_shared boolean; v_nt text; v_heads text; v_host text; v_own_code boolean;
begin
  select p.course_id, p.provider_id, p.url, p.status, p.read_status, p.identity_basis, p.basis, p.evidence_id,
         p.candidates->>'page_title' page_title, p.candidates->>'h1' h1, a.storage_path, a.content_hash, co.canonical_title, co.course_code, co.lifecycle_status
    into g
    from pipeline.coverage_course_pages p join catalogue.courses co on co.id = p.course_id
    left join pipeline.evidence_artifacts a on a.id = p.evidence_id
   where p.course_id = p_course;
  if g.course_id is null then return jsonb_build_object('decision', 'held', 'reason', 'no_page'); end if;
  if g.status <> 'ambiguous' then return jsonb_build_object('decision', 'held', 'reason', 'not_ambiguous'); end if;
  if g.lifecycle_status <> 'active' then return jsonb_build_object('decision', 'held', 'reason', 'course_not_active'); end if;
  if coalesce(g.basis, '') = 'manual' then return jsonb_build_object('decision', 'held', 'reason', 'manual_binding'); end if;
  if g.read_status is distinct from 'read' or g.identity_basis is null then return jsonb_build_object('decision', 'held', 'reason', 'no_identity_proof'); end if;
  if g.storage_path is null then return jsonb_build_object('decision', 'held', 'reason', 'not_stored'); end if;
  if not security.coverage_identity_allowed(g.provider_id, g.identity_basis, 'official_url') then return jsonb_build_object('decision', 'held', 'reason', 'proof_not_allowed'); end if;
  -- prior decisions: any rejection or block of this page for this course, a hold, and any course link a person decided or is to decide
  if exists (select 1 from pipeline.page_rejections x where x.course_id = g.course_id and x.url = g.url)
     or exists (select 1 from pipeline.course_page_blocks k where k.course_id = g.course_id and k.url = g.url) then
    return jsonb_build_object('decision', 'held', 'reason', 'page_rejected_before');
  end if;
  if security.course_held_v1(g.course_id) or security.no_page_hold_v1(g.course_id) then return jsonb_build_object('decision', 'held', 'reason', 'course_held'); end if;
  if exists (select 1 from pipeline.layer4_review_items i where i.entity_type = 'course' and i.entity_id = g.course_id and i.field_code = 'official_course_url'
              and (i.status = 'pending' or exists (select 1 from pipeline.layer4_decisions d where d.review_item_id = i.id and d.actor_id is not null))) then
    return jsonb_build_object('decision', 'held', 'reason', 'person_course_link');
  end if;
  -- the page is on the provider's own host (its website, an approved alias or extra domain), not another sub-site
  v_host := regexp_replace(coalesce(security.reference_host_of(g.url), ''), '^www\.', '');
  if not (v_host = any (security.provider_hosts_v1(g.provider_id))) then return jsonb_build_object('decision', 'held', 'reason', 'host_not_provider_site'); end if;
  -- the page's own heading names exactly this course; no package or pathway page; no other course's CRICOS code in the heading
  v_heads := coalesce(g.page_title, '') || ' ' || coalesce(g.h1, '');
  if v_heads ~* '\m(package|pathway)\M' then return jsonb_build_object('decision', 'held', 'reason', 'package_or_pathway_page'); end if;
  if exists (select 1 from regexp_matches(upper(v_heads), '\m([0-9]{6}[A-Z])\M', 'g') m where m[1] <> upper(coalesce(g.course_code, ''))) then
    return jsonb_build_object('decision', 'held', 'reason', 'other_code_in_heading');
  end if;
  if not security.aer_v2_title_names_course_v1(g.page_title, g.h1, g.canonical_title) then return jsonb_build_object('decision', 'held', 'reason', 'heading_not_course_title'); end if;
  -- the independent binding check (E16) on the same page, title and proof
  v_chk := security.course_page_check_v1(g.course_id, g.url, g.page_title, g.identity_basis);
  if coalesce(v_chk->>'verdict', '') <> 'pass' then
    return jsonb_build_object('decision', 'held', 'reason', 'e16_' || coalesce(v_chk->>'rule', v_chk->>'verdict', 'unknown'), 'e16', v_chk);
  end if;
  -- one catalogue course: the course's own code in the page heading or address tells same-title courses apart; otherwise no other active course of the
  -- provider has the same title and no other course holds the page
  v_own_code := length(coalesce(g.course_code, '')) >= 4 and (upper(v_heads || ' ' || g.url) ~ ('\m' || upper(g.course_code) || '\M'));
  v_nt := regexp_replace(lower(replace(g.canonical_title, '&', ' and ')), '[^a-z0-9]+', ' ', 'g');
  v_twin := exists (select 1 from catalogue.courses c2 where c2.provider_id = g.provider_id and c2.id <> g.course_id and c2.lifecycle_status = 'active'
                     and regexp_replace(lower(replace(c2.canonical_title, '&', ' and ')), '[^a-z0-9]+', ' ', 'g') = v_nt);
  v_shared := exists (select 1 from pipeline.coverage_course_pages g2 where g2.url = g.url and g2.course_id <> g.course_id);
  if not v_own_code and (v_twin or v_shared) then
    return jsonb_build_object('decision', 'held', 'reason', case when v_twin then 'same_title_course' else 'page_shared' end, 'e16', v_chk);
  end if;
  return jsonb_build_object('decision', 'bound', 'reason', case when v_own_code then 'own_code_in_heading' else 'unique_title_' || g.identity_basis end,
                            'e16', v_chk, 'url', g.url, 'evidence_id', g.evidence_id, 'content_hash', g.content_hash, 'identity_basis', g.identity_basis);
end $$;


ALTER FUNCTION "security"."aer_v2_identity_settle_check_v1"("p_course" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_v2_identity_settle_check_v1"("p_course" "uuid") IS 'AER v2 stored-page identity (design §10.2): whether an ambiguous stored page may be bound to its course: the page''s own identity proof (allowed for the country); no earlier rejection, hold or person course-link decision; the provider''s own host; the page title or heading is exactly the course title, with no package, pathway or other course code; the E16 check passes; and one catalogue course (own code in the heading or address, or no same-title course and no other course on the page). Writes nothing.';



CREATE OR REPLACE FUNCTION "security"."aer_v2_identity_settle_v1"("p_apply" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_on boolean := security.pipeline_num_v1('aer.v2_identity_settle_on', 0) >= 1;
        v_batch int := security.pipeline_num_v1('batch.aer_v2_identity_settle', 1000)::int;
        v_t0 timestamptz := clock_timestamp(); r record; v jsonb; v_after text; v_dec text; v_out jsonb := '{}'::jsonb; v_n int := 0;
        v_mode text := case when p_apply then 'apply' else 'dry_run' end;
begin
  if p_apply and not v_on then return jsonb_build_object('on', false); end if;
  for r in
    select p.course_id, p.provider_id, p.url, p.evidence_id, p.identity_basis
      from pipeline.coverage_course_pages p join catalogue.courses co on co.id = p.course_id
     where p.status = 'ambiguous' and p.read_status = 'read' and p.identity_basis is not null and coalesce(p.basis, '') <> 'manual' and co.lifecycle_status = 'active'
       -- a page decided in the last day with the same evidence is not looked at again until it changes
       and not exists (select 1 from pipeline.aer_v2_identity_settlements s where s.course_id = p.course_id and s.url = p.url and s.mode = 'apply'
                         and s.evidence_id is not distinct from p.evidence_id and s.decided_at > now() - interval '1 day')  -- fixed: a held page is looked at again daily
     order by (p.provider_id in (select e.provider_id from security.aer_eligible_v1() e)) desc, p.course_id
     limit v_batch
  loop
    exit when clock_timestamp() - v_t0 > interval '45 seconds';  -- fixed: a run stays inside the job's time
    v := security.aer_v2_identity_settle_check_v1(r.course_id);
    v_dec := v->>'decision';
    if v_dec = 'bound' and p_apply then
      update pipeline.coverage_course_pages set status = 'bound', leased_until = null where course_id = r.course_id and url = r.url and status = 'ambiguous';
      select status into v_after from pipeline.coverage_course_pages where course_id = r.course_id;
      if v_after is distinct from 'bound' then v_dec := 'refused_by_guard'; end if;
    end if;
    insert into pipeline.aer_v2_identity_settlements(course_id, provider_id, url, evidence_id, content_hash, identity_basis, prior_status, decision, reason, e16, rule_version, mode)
    values (r.course_id, r.provider_id, r.url, r.evidence_id, v->>'content_hash', r.identity_basis, 'ambiguous',
            case when v_dec = 'bound' and not p_apply then 'held' else v_dec end,
            case when v_dec = 'bound' and not p_apply then 'dry_run_would_bind:' || (v->>'reason') else v->>'reason' end,
            v->'e16', 'aer-v2-identity-settle-v1', v_mode);
    v_n := v_n + 1;
    v_out := jsonb_set(v_out, array[v_dec], to_jsonb(coalesce((v_out->>v_dec)::int, 0) + 1));
  end loop;
  return jsonb_build_object('on', v_on, 'mode', v_mode, 'checked', v_n, 'outcomes', v_out, 'ms', (extract(epoch from clock_timestamp() - v_t0) * 1000)::int);
end $$;


ALTER FUNCTION "security"."aer_v2_identity_settle_v1"("p_apply" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_v2_identity_settle_v1"("p_apply" boolean) IS 'AER v2 stored-page identity (design §10.2), job aer-v2-identity-settle: binds ambiguous stored pages that pass security.aer_v2_identity_settle_check_v1, through the binding trigger (E16 again), and records every decision in pipeline.aer_v2_identity_settlements. Off (aer.v2_identity_settle_on 0) it does nothing; p_apply false records what it would do.';



CREATE OR REPLACE FUNCTION "security"."aer_v2_sample_refresh_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_t0 timestamptz := clock_timestamp(); v_in int; v_out int;
begin
  insert into pipeline.aer_v2_sample as t(course_id, lane, priority, provider_country, sample_rank, in_sample, refreshed_at)
  with cfg as materialized (select security.pipeline_num_v1('aer.v2_shadow_sample', 2000) sample_size),
  pri as (select x.id, x.ord from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'aer.v2_shadow_priority_providers'), '[]'::jsonb)) with ordinality x(id, ord)),
  pool as (select c.id course_id, pri.ord priority, e.country provider_country
             from catalogue.courses c
             join security.aer_eligible_v1() e on e.provider_id = c.provider_id
             join pipeline.coverage_course_pages g on g.course_id = c.id and g.status = 'bound'
             join pipeline.evidence_artifacts a on a.id = g.evidence_id and a.storage_path is not null
             left join pri on pri.id = c.provider_id::text
            where c.lifecycle_status = 'active' and c.open_to_international is not false),
  lab as materialized (select distinct l.course_id from pipeline.aer_labelled_rows_v1 l where l.course_id is not null),
  -- lane 0: courses whose v1 read waits in Layer 4 held as gate_incomplete (one pass over the decisions, newest per item)
  gi as materialized (select distinct l.course_id from (
                        select distinct on (a.review_item_id) a.review_item_id, a.reason_code, i.entity_id course_id
                          from pipeline.layer4_review_items i join pipeline.aer_machine_admissions a on a.review_item_id = i.id
                         where i.field_code = 'course_entry_first_read' and i.status = 'pending' and i.entity_type = 'course'
                         order by a.review_item_id, a.updated_at desc) l
                       where l.reason_code = 'gate_incomplete'),
  laned as (select pool.*, case when exists (select 1 from gi where gi.course_id = pool.course_id) then 0
                                when exists (select 1 from lab where lab.course_id = pool.course_id) then 1
                                when pool.priority is not null then 2 else 3 end lane from pool),
  ranked as (select laned.*, row_number() over (partition by laned.lane order by laned.priority nulls last, md5(laned.course_id::text)) lane_rank from laned),
  sample as (select ranked.*, row_number() over (order by (ranked.lane = 3), (ranked.lane > 0), ranked.lane_rank, ranked.lane) sample_rank from ranked)
  select s.course_id, s.lane, s.priority, s.provider_country, s.sample_rank, true, now() from sample s cross join cfg where s.sample_rank <= cfg.sample_size
      -- 14 Nov 2026: the unlabelled probe courses (aer.v2_shadow_probe_courses), measured by verifier pass rate only
      or s.course_id::text in (select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'aer.v2_shadow_probe_courses'), '[]'::jsonb)))
  on conflict (course_id) do update set lane = excluded.lane, priority = excluded.priority, provider_country = excluded.provider_country,
                                        sample_rank = excluded.sample_rank, in_sample = true, refreshed_at = excluded.refreshed_at;
  get diagnostics v_in = row_count;
  update pipeline.aer_v2_sample t set in_sample = false, refreshed_at = now() where t.in_sample and t.refreshed_at < now();
  get diagnostics v_out = row_count;
  return jsonb_build_object('in_sample', v_in, 'left_sample', v_out,
                            'lanes', (select jsonb_object_agg(z.lane, z.n) from (select s.lane, count(*) n from pipeline.aer_v2_sample s where s.in_sample group by 1) z),
                            'ms', (extract(epoch from clock_timestamp() - v_t0) * 1000)::int);
end $$;


ALTER FUNCTION "security"."aer_v2_sample_refresh_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_v2_sample_refresh_v1"() IS 'AER v2 reader: rebuilds pipeline.aer_v2_sample (the ranked course sample: gate_incomplete reads first, then courses with a person''s decision, priority providers, the rest), outside the worker''s call. Marks courses that left the sample, never deletes.';



CREATE OR REPLACE FUNCTION "security"."aer_v2_shadow_candidates_v1"("p_version" "text", "p_limit" integer) RETURNS TABLE("course_id" "uuid", "provider_id" "uuid", "title" "text", "level" "text", "provider" "text", "provider_country" "text", "url" "text", "evidence_id" "uuid", "content_hash" "text", "storage_path" "text", "priority" bigint, "sample_rank" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- 14 Nov 2026 (Platform Admin item 1): reads the stored sample (pipeline.aer_v2_sample, built by security.aer_v2_sample_refresh_v1) in rank order;
  -- only the current page and the tries rule are looked up per course, so the call stays well inside the worker's 8 s statement limit
  with cfg as materialized (select security.pipeline_num_v1('aer.v2_shadow_tries', 2) tries,
                            coalesce(security.toolset_setting('pipeline', 'aer.retry_now_error_pattern') #>> '{}', '') refused),
  done as materialized (select r.course_id from pipeline.aer_v2_shadow_results r cross join cfg where r.prompt_version = p_version
                         group by r.course_id, cfg.tries having count(*) filter (where r.error is null) > 0 or count(*) filter (where r.error is null or cfg.refused = '' or r.error !~* cfg.refused) >= cfg.tries)
  select c.id, c.provider_id, c.canonical_title, sl.name, coalesce(p.display_name, p.canonical_name), s.provider_country,
         g.url, a.id, a.content_hash, a.storage_path, s.priority, s.sample_rank::bigint
    from pipeline.aer_v2_sample s
    join catalogue.courses c on c.id = s.course_id and c.lifecycle_status = 'active'
    join catalogue.providers p on p.id = c.provider_id
    join pipeline.coverage_course_pages g on g.course_id = c.id and g.status = 'bound'
    join pipeline.evidence_artifacts a on a.id = g.evidence_id and a.storage_path is not null
    left join ref.study_levels sl on sl.id = c.study_level_id
   where s.in_sample and not exists (select 1 from done where done.course_id = s.course_id)
   order by s.sample_rank
   limit greatest(coalesce(p_limit, 0), 0)
$$;


ALTER FUNCTION "security"."aer_v2_shadow_candidates_v1"("p_version" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_v2_shadow_candidates_v1"("p_version" "text", "p_limit" integer) IS 'AER v2 reader: the next courses of the stored sample (pipeline.aer_v2_sample) in rank order whose official page is bound and stored and that the prompt version has not read (a failed read is offered again until it has aer.v2_shadow_tries results). Same columns as before.';



CREATE OR REPLACE FUNCTION "security"."aer_v2_shadow_fire_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare h jsonb; v_due int; v_open int;
begin
  if security.pipeline_num_v1('aer.v2_shadow_on', 0) < 1 then return jsonb_build_object('on', false); end if;
  h := security.aer_v2_shadow_hold_v1();
  if h->>'held' is not null then return jsonb_build_object('on', true, 'held', h->>'held', 'budget', h->'budget'); end if;
  if not security.ai_use_allowed_v1('entry_matrix') then return jsonb_build_object('on', true, 'ai', security.ai_use_refusal_v1('entry_matrix')); end if;
  -- 14 Nov 2026: the sample is rebuilt here (no statement limit), never in the worker's call
  if coalesce((select max(s.refreshed_at) from pipeline.aer_v2_sample s), '-infinity') < now() - make_interval(mins => security.pipeline_num_v1('aer.v2_sample_refresh_minutes', 60)::int) then
    perform security.aer_v2_sample_refresh_v1();
  end if;
  select count(*) into v_due from security.aer_v2_shadow_candidates_v1(h->'version'->>'version', 1) x;
  if v_due = 0 then return jsonb_build_object('on', true, 'version', h->'version'->>'version', 'due', 0, 'note', 'the sample is read'); end if;
  select count(*) into v_open from pipeline.edge_request_log l where l.function_name = 'coverage-sweep' and l.mode = 'aer_v2_shadow' and l.created_at > now() - interval '4 minutes'  -- fixed: fire guard
     and not exists (select 1 from net._http_response r where r.id = l.request_id);
  if v_open > 0 then return jsonb_build_object('on', true, 'open', v_open); end if;
  perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'aer_v2_shadow', 'limit', security.pipeline_num_v1('batch.aer_v2_shadow', 20)::int));
  return jsonb_build_object('on', true, 'version', h->'version'->>'version', 'sent', 1, 'budget', h->'budget');
end $$;


ALTER FUNCTION "security"."aer_v2_shadow_fire_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_v2_shadow_fire_v1"() IS 'AER v2 step 1 (job aer-v2-shadow): calls worker mode aer_v2_shadow while aer.v2_shadow_on is 1, the trial budget and daily share allow and sample courses are unread; does nothing while off';



CREATE OR REPLACE FUNCTION "security"."aer_v2_shadow_hold_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v record; v_rt jsonb := security.ai_route_v1('entry_requirements_v2_shadow'); v_spent numeric; v_today numeric; v_budget numeric := security.pipeline_num_v1('aer.v2_shadow_budget_usd', 20);
        v_daily numeric := security.pipeline_num_v1('aer.v2_shadow_daily_usd', 3);
begin
  select x.version, x.system_text, x.system_sha256, x.model, x.quote_max_chars, x.answer_contract, x.input_format, x.routing, x.params into v
    from pipeline.aer_prompt_versions x where x.purpose = 'course_page' and x.status = 'trial' order by x.created_at desc limit 1;
  select coalesce(sum(r.cost_usd), 0),
         coalesce(sum(r.cost_usd) filter (where r.created_at >= date_trunc('day', now() at time zone 'utc') at time zone 'utc'), 0)  -- fixed: the UTC day, as the AI ledger counts it
    into v_spent, v_today from pipeline.aer_v2_shadow_results r;
  return jsonb_build_object(
    'held', case when security.pipeline_num_v1('aer.v2_shadow_on', 0) < 1 then 'switched off (aer.v2_shadow_on)'
                 when v.version is null then 'no trial prompt version'
                 when coalesce((v_rt->>'held')::boolean, true) then coalesce(v_rt->>'held_reason', 'the route is held')  -- 13 Nov 2026: the route's switch, cap and the daily ceiling
                 when v_spent >= v_budget then format('trial budget reached: US$%s of US$%s (aer.v2_shadow_budget_usd)', round(v_spent, 4), v_budget)
                 when v_today >= v_daily then format('daily share reached: US$%s of US$%s today (aer.v2_shadow_daily_usd)', round(v_today, 4), v_daily) end,
    'version', case when v.version is not null then jsonb_build_object('version', v.version, 'system_text', v.system_text, 'system_sha256', v.system_sha256,
                                                                        'model', v_rt->>'model', 'models', v_rt->'models', 'quote_max_chars', v.quote_max_chars,
                                                                        'answer_contract', v.answer_contract, 'input_format', v.input_format, 'routing', v.routing, 'params', v.params) end,  -- the model is the route's; the prompt text and its sha are the version's
    'budget', jsonb_build_object('usd', v_budget, 'spent', v_spent, 'daily_usd', v_daily, 'today', v_today));
end $_$;


ALTER FUNCTION "security"."aer_v2_shadow_hold_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_v2_shadow_hold_v1"() IS 'AER v2 step 1: why the shadow reader is held now (switch, trial version, total budget, daily share), or null, with the trial version';



CREATE OR REPLACE FUNCTION "security"."aer_v2_shadow_report_v1"("p_version" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with v as (select coalesce(p_version, (select x.version from pipeline.aer_prompt_versions x where x.purpose = 'course_page' and x.status = 'trial' order by x.created_at desc limit 1)) version),
  res as (select r.* from pipeline.aer_v2_shadow_results r join v on v.version = r.prompt_version),
  ok as (select res.* from res where res.error is null),
  rec as (select ok.id, ok.course_id, x.r, ok.checks -> (x.i::int - 1) c
            from ok cross join lateral jsonb_array_elements(ok.records) with ordinality x(r, i)),
  pq as (select rec.course_id, rec.r->>'min_grade' g, q->>'text' t from rec cross join lateral jsonb_array_elements(coalesce(rec.r->'quotes', '[]'::jsonb)) q
          where coalesce((rec.c->>'pass')::boolean, false)),
  lab as (select l.label, l.course_id, l.min_grade, l.quote,
                 exists (select 1 from pq where pq.course_id = l.course_id
                           and ((length(security.aer_flat_v1(l.quote)) >= 12 and length(security.aer_flat_v1(pq.t)) >= 12  -- fixed: the shortest quote compared
                                 and (strpos(security.aer_flat_v1(l.quote), security.aer_flat_v1(pq.t)) > 0 or strpos(security.aer_flat_v1(pq.t), security.aer_flat_v1(l.quote)) > 0))
                                or (security.aer_flat_v1(l.min_grade) <> '' and security.aer_flat_v1(l.min_grade) = security.aer_flat_v1(pq.g)))) matched
            from pipeline.aer_labelled_rows_v1 l where l.source_kind = 'course_page' and l.course_id in (select ok.course_id from ok)),
  agg as (select count(*) records, count(*) filter (where coalesce((c->>'pass')::boolean, false)) passed,
                 count(*) filter (where coalesce((c->>'has_target')::boolean, false)) with_target,
                 count(*) filter (where coalesce((c->>'has_target')::boolean, false) and coalesce((c->>'pass')::boolean, false)) passed_with_target,
                 count(*) filter (where coalesce((c->>'has_minimum')::boolean, false)) with_minimum,
                 count(*) filter (where r->>'audience' = 'domestic') domestic
            from rec)
  select jsonb_build_object(
    'prompt_version', (select v.version from v),
    'model', (select x.model from pipeline.aer_prompt_versions x join v on v.version = x.version),
    'pages_read', (select count(*) from ok),
    'pages_failed', (select count(*) from res where res.error is not null),
    'failures', (select coalesce(jsonb_object_agg(k, n), '{}'::jsonb) from (select split_part(res.error, ':', 1) k, count(*) n from res where res.error is not null group by 1) z),
    'pages_with_records', (select count(*) from ok where jsonb_array_length(ok.records) > 0),
    'records', agg.records, 'records_passed', agg.passed,
    'pass_rate', case when agg.records > 0 then round(agg.passed::numeric / agg.records, 3) end,
    'records_per_page', case when (select count(*) from ok) > 0 then round(agg.records::numeric / (select count(*) from ok), 2) end,
    'share_with_country_or_qualification', case when agg.records > 0 then round(agg.with_target::numeric / agg.records, 3) end,
    'passed_with_country_or_qualification', agg.passed_with_target,
    'share_with_minimum', case when agg.records > 0 then round(agg.with_minimum::numeric / agg.records, 3) end,
    'domestic_records', agg.domestic,
    'courses_with_passed_country_or_qualification', (select count(distinct rec.course_id) from rec where coalesce((rec.c->>'pass')::boolean, false) and coalesce((rec.c->>'has_target')::boolean, false)),
    'applicant_countries', (select coalesce(jsonb_object_agg(cc, n), '{}'::jsonb) from (select upper(rec.r->>'applicant_country') cc, count(*) n from rec
                             where rec.r->>'applicant_country' is not null and coalesce((rec.c->>'pass')::boolean, false) group by 1) z),
    'verifier_failure_reasons', (select coalesce(jsonb_object_agg(k, n), '{}'::jsonb) from (select x k, count(*) n from rec cross join lateral jsonb_array_elements_text(coalesce(rec.c->'reasons', '[]'::jsonb)) x group by 1) z),
    'seen_not_mapped', (select count(*) from ok cross join lateral jsonb_array_elements(ok.seen_not_mapped) s),
    'seen_not_mapped_on_page', (select count(*) from ok cross join lateral jsonb_array_elements(ok.seen_not_mapped) s where coalesce((s->>'on_page')::boolean, false)),
    'cost_usd', (select round(coalesce(sum(res.cost_usd), 0), 4) from res),
    'cost_per_page_usd', case when (select count(*) from res) > 0 then (select round(sum(res.cost_usd) / count(*), 5) from res) end,
    'labelled_agreement', jsonb_build_object(
      'courses_with_labels', (select count(distinct lab.course_id) from lab),
      'accepted_rows', (select count(*) from lab where lab.label = 'accepted'),
      'accepted_found', (select count(*) from lab where lab.label = 'accepted' and lab.matched),
      'accepted_found_share', (select case when count(*) > 0 then round(count(*) filter (where lab.matched)::numeric / count(*), 3) end from lab where lab.label = 'accepted'),
      'rejected_rows', (select count(*) from lab where lab.label = 'rejected'),
      'rejected_reproduced', (select count(*) from lab where lab.label = 'rejected' and lab.matched),
      'basis', 'a passed v2 record of the same course whose quote contains, or is contained in, the labelled quote, or whose minimum is the same as printed'))
  from agg
$$;


ALTER FUNCTION "security"."aer_v2_shadow_report_v1"("p_version" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_v2_shadow_report_v1"("p_version" "text") IS 'AER v2 step 1: the shadow trial report: pass rate, records a page, share with an applicant country or qualification, verifier failure reasons, cost, and agreement with the labelled set (course pages) for the same courses';



CREATE OR REPLACE FUNCTION "security"."aer_v2_title_names_course_v1"("p_page_title" "text", "p_h1" "text", "p_course_title" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare v_t text; v_nl text; v_h1 text; v_ti text; v_parts text[]; v_head text;
begin
  v_t := btrim(regexp_replace(lower(replace(coalesce(p_course_title, ''), '&', ' and ')), '[^a-z0-9]+', ' ', 'g'));
  if v_t = '' then return false; end if;
  v_nl := btrim(regexp_replace(v_t, '\s*level \d{1,2}$', ''));
  -- entities decoded, a leading national or provider code set aside, then normalised
  v_h1 := regexp_replace(regexp_replace(regexp_replace(regexp_replace(coalesce(p_h1, ''), '&(#8211|#8212|ndash|mdash);', '-', 'gi'), '&(#39|#8217|rsquo|lsquo);', '''', 'gi'), '&amp;', '&', 'gi'), '&nbsp;', ' ', 'gi');
  v_ti := regexp_replace(regexp_replace(regexp_replace(regexp_replace(coalesce(p_page_title, ''), '&(#8211|#8212|ndash|mdash);', '-', 'gi'), '&(#39|#8217|rsquo|lsquo);', '''', 'gi'), '&amp;', '&', 'gi'), '&nbsp;', ' ', 'gi');
  -- a heading that repeats the site name after "|" (some sites print the page title as the heading) is read up to the "|"
  v_h1 := btrim(regexp_replace(lower(replace(regexp_replace(btrim(split_part(v_h1, '|', 1)), '^(?:[A-Z]{2,6}[0-9]{3,6}[A-Z]?|[0-9]{5}NAT)\s*[-–—:|]?\s+', ''), '&', ' and ')), '[^a-z0-9]+', ' ', 'g'));
  -- 1. the main heading is the course title
  if v_h1 <> '' and (v_h1 = v_t or v_h1 = v_nl) then return true; end if;
  -- 2. a heading that is the course title plus more words names a stream, major or campus of it: not this course
  if v_h1 <> '' and (v_h1 like v_t || ' %' or v_h1 like v_nl || ' %') then return false; end if;
  -- 3. the page title: its first part before "|", which may carry the site name after one dash; brackets must be whole and nothing may stand between
  v_head := btrim(split_part(v_ti, '|', 1));
  v_parts := regexp_split_to_array(v_head, '\s+[–—-]\s+');
  if cardinality(v_parts) > 2 then return false; end if;
  v_head := btrim(v_parts[1]);
  if length(v_head) - length(replace(v_head, '(', '')) <> length(v_head) - length(replace(v_head, ')', '')) then return false; end if;
  v_head := btrim(regexp_replace(lower(replace(regexp_replace(v_head, '^(?:[A-Z]{2,6}[0-9]{3,6}[A-Z]?|[0-9]{5}NAT)\s*[-–—:|]?\s+', ''), '&', ' and ')), '[^a-z0-9]+', ' ', 'g'));
  return v_head <> '' and (v_head = v_t or v_head = v_nl);
end $_$;


ALTER FUNCTION "security"."aer_v2_title_names_course_v1"("p_page_title" "text", "p_h1" "text", "p_course_title" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_v2_title_names_course_v1"("p_page_title" "text", "p_h1" "text", "p_course_title" "text") IS 'AER v2 stored-page identity: true when the main heading is exactly the course title, or (with no heading that adds a stream, major or campus to it) the first part of the page title is, with at most the site name after one dash and whole brackets; a leading national or provider code is set aside and a trailing "(Level N)" may be left off.';



CREATE OR REPLACE FUNCTION "security"."aer_v3_eval_gold_v1"("p_set" bigint, "p_example" bigint) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'accepted', coalesce(jsonb_agg(jsonb_build_object('min_grade', g.min_grade, 'quote', g.quote, 'country', g.country)) filter (where g.label = 'accepted'), '[]'::jsonb),
    'rejected', coalesce(jsonb_agg(jsonb_build_object('min_grade', g.min_grade, 'quote', g.quote, 'country', g.country)) filter (where g.label = 'rejected'), '[]'::jsonb))
    from pipeline.aer_v3_eval_gold g where g.set_id = p_set and g.example_id = p_example
$$;


ALTER FUNCTION "security"."aer_v3_eval_gold_v1"("p_set" bigint, "p_example" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_v3_eval_gold_v1"("p_set" bigint, "p_example" bigint) IS 'AER v3 benchmark: the frozen gold rows of an example in a set (accepted rows to find, rejected rows never to reproduce).';



CREATE OR REPLACE FUNCTION "security"."aer_v3_eval_pair_v1"("p_base" "jsonb", "p_set" bigint, "p_example" bigint, "p_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_gold jsonb := security.aer_v3_eval_gold_v1(p_set, p_example); v_min numeric := security.pipeline_num_v1('ai_eval.aer_v3_min_recall_pct', 100);
        v_passed jsonb; v_acc int; v_found int; v_repro int; v_recall numeric; v_failed int; v_ok boolean;
begin
  v_ok := coalesce((p_base->>'answered')::boolean, false) and p_base->>'error' is null and jsonb_typeof(p_value->'records') = 'array';
  -- checks are in record order (aer-v2.ts aerV3Verify); a record without its check counts as failed
  select count(*) filter (where not coalesce((p_value->'checks'->(e.i::int - 1)->>'pass')::boolean, false)) into v_failed
    from jsonb_array_elements(coalesce(p_value->'records', '[]'::jsonb)) with ordinality e(rec, i);
  select coalesce(jsonb_agg(r.rec), '[]'::jsonb) into v_passed
    from (select e.rec from jsonb_array_elements(coalesce(p_value->'records', '[]'::jsonb)) with ordinality e(rec, i)
           where coalesce((p_value->'checks'->(e.i::int - 1)->>'pass')::boolean, false)) r;
  v_acc := jsonb_array_length(v_gold->'accepted');
  select count(*) into v_found from jsonb_array_elements(v_gold->'accepted') g where exists (select 1 from jsonb_array_elements(v_passed) r where security.aer_v3_row_found_v1(g, r));
  select count(*) into v_repro from jsonb_array_elements(v_gold->'rejected') g where exists (select 1 from jsonb_array_elements(v_passed) r where security.aer_v3_row_found_v1(g, r));
  v_recall := case when v_acc > 0 then round(100.0 * v_found / v_acc, 2) end;
  return p_base || jsonb_build_object(
    'verdict', case when not v_ok then null when v_repro > 0 then 'accept'
                    when p_base->>'label' in ('accept', 'correct') and v_acc > 0 and v_recall >= v_min then 'accept' else 'no_value' end,
    'value', case when not v_ok then null
                  when v_repro > 0 then case when p_base->>'label' = 'reject' then p_base->'rejected' else jsonb_build_object('aer', 'reproduced a rejected row') end
                  when p_base->>'label' in ('accept', 'correct') and v_acc > 0 and v_recall >= v_min then p_base->'expected' end,
    'quote_on_page', v_ok and v_failed = 0 and jsonb_array_length(v_passed) > 0,
    'aer', jsonb_build_object('gold_accepted', v_acc, 'found', v_found, 'recall_pct', v_recall, 'reproduced_rejected', v_repro,
                              'passed', jsonb_array_length(v_passed), 'failed', v_failed));
end $$;


ALTER FUNCTION "security"."aer_v3_eval_pair_v1"("p_base" "jsonb", "p_set" bigint, "p_example" bigint, "p_value" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_v3_eval_pair_v1"("p_base" "jsonb", "p_set" bigint, "p_example" bigint, "p_value" "jsonb") IS 'AER v3 benchmark: turns one multi-record AER answer into the framework''s scoring pair (right: enough accepted gold rows found by passed records and no rejected row reproduced; a reproduced rejected row is a false positive; source integrity: every record passed the v3 verifier).';



CREATE OR REPLACE FUNCTION "security"."aer_v3_eval_subject_v1"("p_example" bigint) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  with x as (select x.*, case when x.field like 'entry_matrix%' then 'matrix' when x.entity = 'course_entry' then 'row' else 'course' end scope,
                    case when x.entity = 'course_entry' then (select c.course_id from catalogue.course_entry_requirements c where c.id = x.entity_id)
                         when x.entity = 'course' then x.entity_id end course_id,
                    coalesce(x.evidence_id, case when x.entity = 'course_entry' then (select c.evidence_id from catalogue.course_entry_requirements c where c.id = x.entity_id) end) ev
               from pipeline.ai_eval_examples x where x.id = p_example)
  select jsonb_build_object('example_id', x.id, 'scope', x.scope, 'label', x.label, 'course_id', x.course_id,
           'provider_id', coalesce(co.provider_id, case when x.entity = 'provider' then x.entity_id end),
           'evidence_id', x.ev, 'storage_path', a.storage_path, 'content_hash', a.content_hash,
           'review_item_id', substring(x.input_ref from '[0-9a-f-]{36}$'), 'row_id', case when x.scope = 'row' then x.entity_id end,
           'title', coalesce(co.canonical_title, 'Entry requirements (institution page)'),
           'provider', coalesce(p.display_name, p.canonical_name), 'provider_country', security.coverage_country(coalesce(co.provider_id, case when x.entity = 'provider' then x.entity_id end)),
           'level', (select sl.name from ref.study_levels sl where sl.id = co.study_level_id), 'url', a.source_url)
    from x left join catalogue.courses co on co.id = x.course_id
    left join catalogue.providers p on p.id = coalesce(co.provider_id, case when x.entity = 'provider' then x.entity_id end)
    left join pipeline.evidence_artifacts a on a.id = x.ev
$_$;


ALTER FUNCTION "security"."aer_v3_eval_subject_v1"("p_example" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_v3_eval_subject_v1"("p_example" bigint) IS 'AER v3 benchmark: an example''s subject (course, course row or provider page), its frozen stored page and the course record the reader is given.';



CREATE OR REPLACE FUNCTION "security"."aer_v3_eval_version_v1"("p_version" bigint) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce((select v.spec->>'answer_contract' = 'aer-v2-answer-v3' from pipeline.ai_instruction_versions v where v.id = p_version), false)
$$;


ALTER FUNCTION "security"."aer_v3_eval_version_v1"("p_version" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_v3_eval_version_v1"("p_version" bigint) IS 'AER v3 benchmark: whether an instruction version answers with the AER v2 answer contract v3 (multi-record, [B#] quotes); such runs are leased only by worker mode aer_v3_eval.';



CREATE OR REPLACE FUNCTION "security"."aer_v3_flat_v1"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  -- the verifier's canonical form (aer-v2.ts aerFlat): lower case, NFKD, letters and digits only
  select regexp_replace(normalize(lower(coalesce(p, '')), NFKD), '[^a-z0-9]+', '', 'g')
$$;


ALTER FUNCTION "security"."aer_v3_flat_v1"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_v3_qualification_evidence_v1"("p_run" bigint, "p_metrics" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_model text; v_strata jsonb;
begin
  select x.*, v.version ver, p.code proposal, p.acceptance_criteria crit into r
    from pipeline.ai_eval_runs x join pipeline.ai_instruction_versions v on v.id = x.version_id left join pipeline.ai_improvement_proposals p on p.id = x.proposal_id where x.id = p_run;
  select m.code into v_model from pipeline.ai_model_catalogue m where m.model_identifier = r.model_identifier;
  if v_model is null then return jsonb_build_object('recorded', false, 'why', 'model not in the catalogue'); end if;
  select jsonb_object_agg(z.stratum, z.m) into v_strata from (
    select m.stratum, security.ai_eval_metrics_v1(jsonb_agg(security.aer_v3_eval_pair_v1(jsonb_build_object(
             'label', x.label, 'expected', x.expected, 'rejected', x.rejected, 'needs_quote', true, 'tier', x.tier, 'answered', a.example_id is not null,
             'verdict', a.verdict, 'value', a.value, 'quote_on_page', a.quote_on_page, 'error', a.error, 'cost_usd', a.cost_usd, 'tokens_in', a.tokens_in, 'tokens_out', a.tokens_out),
             m.set_id, x.id, a.value))) m
      from pipeline.ai_eval_set_members m join pipeline.ai_eval_examples x on x.id = m.example_id
      left join pipeline.ai_eval_answers a on a.run_id = p_run and a.example_id = x.id
     where m.set_id = r.set_id group by m.stratum) z;
  insert into pipeline.ai_route_qualifications as q(service_code, model_code, prompt_version, status, provisional, evidence, evidence_detail, note, changed_at)
  values ('entry_requirements_v2_shadow', v_model, 'aer-v2-course-v3', 'pending', false,
          format('ai_eval run %s (%s, set %s): accuracy %s%%, false positives %s of %s, source integrity %s%%', p_run, r.ver, r.set_id,
                 p_metrics->>'accuracy_pct', p_metrics->>'false_positives', p_metrics->>'examples', p_metrics->>'source_integrity_pct'),
          jsonb_build_object('run', p_run, 'proposal', r.proposal, 'version', r.ver, 'set', r.set_id, 'metrics', p_metrics, 'strata', v_strata, 'criteria', r.crit),
          'Benchmark evidence recorded; qualifying the model is the Platform Admin''s decision (a qualification never switches a service on).', now())
  on conflict (service_code, model_code) do update
     set prompt_version = excluded.prompt_version, evidence = excluded.evidence, evidence_detail = excluded.evidence_detail, note = excluded.note, changed_at = now(),
         status = case when q.status = 'qualified' then q.status else 'pending' end;
  return jsonb_build_object('recorded', true, 'model', v_model, 'strata', v_strata);
end $$;


ALTER FUNCTION "security"."aer_v3_qualification_evidence_v1"("p_run" bigint, "p_metrics" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_v3_qualification_evidence_v1"("p_run" bigint, "p_metrics" "jsonb") IS 'AER v3 benchmark: writes a scored run as evidence on pipeline.ai_route_qualifications (entry_requirements_v2_shadow, prompt aer-v2-course-v3), status pending at most; never qualifies a model.';



CREATE OR REPLACE FUNCTION "security"."aer_v3_row_found_v1"("p_gold" "jsonb", "p_rec" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select security.aer_v3_flat_v1(p_gold->>'min_grade') = security.aer_v3_flat_v1(p_rec->>'min_grade')
     and length(security.aer_v3_flat_v1(p_rec->>'exact_quote')) >= 4 and length(security.aer_v3_flat_v1(p_gold->>'quote')) >= 4  -- fixed: the verifier's quote floor
     and (position(security.aer_v3_flat_v1(p_rec->>'exact_quote') in security.aer_v3_flat_v1(p_gold->>'quote')) > 0
          or position(security.aer_v3_flat_v1(p_gold->>'quote') in security.aer_v3_flat_v1(p_rec->>'exact_quote')) > 0)
     and (p_gold->>'country' is null or upper(coalesce(p_rec->>'applicant_country', '')) = upper(p_gold->>'country'))
$$;


ALTER FUNCTION "security"."aer_v3_row_found_v1"("p_gold" "jsonb", "p_rec" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."aer_weekly_markdown_v1"("p_week_start" "date" DEFAULT NULL::"date") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_ws date := coalesce(p_week_start, date_trunc('week', now() at time zone 'Australia/Sydney')::date - 7);  -- fixed: the week just ended (Monday to Sunday)
        v jsonb;
begin
  v := security.aer_weekly_section_v1(v_ws);
  return '# AER weekly report, week of ' || to_char(v_ws, 'DD Mon YYYY') || E'\n\n'
      || 'Generated ' || to_char(now() at time zone 'Australia/Sydney', 'DD Mon YYYY HH24:MI') || ' (Sydney) from the StudySearch database (security.aer_weekly_section_v1). '
      || 'The same report is on Coverage & completeness › Attributes › Academic entry requirements.' || E'\n\n'
      || (select string_agg('- ' || l, E'\n') from unnest(string_to_array(security.aer_weekly_text_v1(v), E'\n')) l) || E'\n\n'
      || '## Root causes' || E'\n\n| Root cause | Severity | Providers | Findings | Next action | Owner |\n|---|---|---:|---:|---|---|\n'
      || coalesce((select string_agg(format('| %s | %s | %s | %s | %s | %s |', z->>'label', z->>'severity', z->>'providers', z->>'findings', z->>'next_action', z->>'owner_role'), E'\n')
                    from jsonb_array_elements(v->'top_root_causes') z), '| none | | | | | |') || E'\n\n'
      || '## Layer 4 review readiness (pending AER items)' || E'\n\n'
      || coalesce((select string_agg(format('- %s: %s', x.key, x.value), E'\n') from jsonb_each_text(v->'readiness') x), '- none') || E'\n\n'
      || '```json' || E'\n' || jsonb_pretty(v) || E'\n```\n';
end $$;


ALTER FUNCTION "security"."aer_weekly_markdown_v1"("p_week_start" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_weekly_markdown_v1"("p_week_start" "date") IS 'CF-247 AER weekly report (D-A7, Platform Admin 2 Nov 2026 ~16:40): the Markdown copy committed each Monday by the aer-weekly-report workflow (aer-weekly-snapshot branch, docs/platform/aer-weekly/YYYY-MM-DD.md). Read-only; executable by the read-only role, as the watchdog is.';



CREATE OR REPLACE FUNCTION "security"."aer_weekly_section_v1"("p_week_start" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_end date := p_week_start + 6; v_now record; v_before record; v jsonb;  -- fixed: Monday-to-Sunday weeks
begin
  select * into v_now from pipeline.aer_coverage_daily d where d.country = 'ALL' and d.day <= v_end order by d.day desc limit 1;
  select * into v_before from pipeline.aer_coverage_daily d where d.country = 'ALL' and d.day < p_week_start order by d.day desc limit 1;
  v := jsonb_build_object(
    'week_start', p_week_start, 'as_of', v_now.day,
    'eligible', v_now.eligible,
    'measures', case when v_now.day is null then null else jsonb_build_object(
      'discovery', jsonb_build_object('n', v_now.discovery_n, 'of', v_now.eligible, 'prior_week', v_before.discovery_n),
      'extraction', jsonb_build_object('n', v_now.extraction_n, 'of', v_now.eligible, 'prior_week', v_before.extraction_n),
      'admission', jsonb_build_object('n', v_now.admission_n, 'of', v_now.eligible, 'prior_week', v_before.admission_n),
      'consumer', jsonb_build_object('n', v_now.consumer_n, 'of', v_now.eligible, 'prior_week', v_before.consumer_n)) end,
    'open', jsonb_build_object('P0', v_now.open_p0, 'P1', v_now.open_p1, 'P2', v_now.open_p2),
    'changes', (select jsonb_build_object('opened', count(*) filter (where x.event = 'opened'), 'resolved', count(*) filter (where x.event = 'resolved'),
                                          'reopened', count(*) filter (where x.event = 'reopened'))
                  from pipeline.aer_gap_events x where (x.at at time zone 'Australia/Sydney')::date between p_week_start and v_end),
    'top_root_causes', (select coalesce(jsonb_agg(z order by z.providers desc, z.code), '[]'::jsonb) from (
                          select rc.code, rc.label, rc.severity, rc.owner_role, rc.next_action, count(distinct g.provider_id) providers, count(*) findings
                            from pipeline.aer_gap_findings g join pipeline.aer_gap_root_causes rc on rc.code = g.root_cause
                           where g.state <> 'resolved' group by rc.code, rc.label, rc.severity, rc.owner_role, rc.next_action
                           order by count(distinct g.provider_id) desc, rc.code limit 5) z),
    'no_progress_providers', (select count(distinct g.provider_id) from pipeline.aer_gap_findings g where g.state <> 'resolved' and g.severity in ('P0', 'P1')
                               and (g.first_seen at time zone 'Australia/Sydney')::date < p_week_start),
    'recovered', (select coalesce(jsonb_agg(jsonb_build_object('root_cause', g.root_cause, 'scope', g.scope_label, 'provider_id', g.provider_id)), '[]'::jsonb)
                    from pipeline.aer_gap_events x join pipeline.aer_gap_findings g on g.id = x.finding_id
                   where x.event = 'resolved' and g.scope_kind in ('country', 'qualification') and (x.at at time zone 'Australia/Sydney')::date between p_week_start and v_end),
    'postgraduate', v_now.detail->'postgraduate',
    'layer4_pending', v_now.detail->'layer4_pending',
    'readiness', (select coalesce(jsonb_object_agg(z.readiness, z.n), '{}'::jsonb) from (select r.readiness, count(*) n from pipeline.aer_review_readiness r
                    where r.settled_at is null group by 1) z),
    'spend_usd', (select coalesce(sum(l.cost_usd), 0) from pipeline.ai_spend_ledger l where l.lane = 'entry_matrix' and l.source <> 'opening'
                   and (l.at at time zone 'Australia/Sydney')::date between p_week_start and v_end),
    'next_work', 'Hourly reconciliation (aer-reconcile); Phase C reader and qualification work; Phase E discovery waves once approved',
    'decisions', (select coalesce(jsonb_agg(distinct rc.label), '[]'::jsonb) from pipeline.aer_gap_findings g join pipeline.aer_gap_root_causes rc on rc.code = g.root_cause
                   where g.state <> 'resolved' and rc.owner_role = 'Platform Admin'));
  return v;
exception when others then
  return jsonb_build_object('week_start', p_week_start, 'error', left(sqlerrm, 300));
end $$;


ALTER FUNCTION "security"."aer_weekly_section_v1"("p_week_start" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."aer_weekly_section_v1"("p_week_start" "date") IS 'CF-247 AER Phase B (mandate §14 weekly): the AER section of the weekly report: the four measures against the prior week, open P0/P1/P2, opened/resolved/reopened, top root causes, providers with no progress, recovered country and qualification scopes, postgraduate coverage, Layer 4 workload, entry-matrix AI spend and decisions for the Platform Admin.';



CREATE OR REPLACE FUNCTION "security"."aer_weekly_text_v1"("p" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select concat_ws(E'\n',
    'Eligible AU/NZ providers: ' || coalesce(p->>'eligible', 'not measured'),
    'Source discovery: ' || coalesce(p#>>'{measures,discovery,n}', '-') || ' (prior week ' || coalesce(p#>>'{measures,discovery,prior_week}', '-') || ')',
    'Extraction: ' || coalesce(p#>>'{measures,extraction,n}', '-') || ' (prior week ' || coalesce(p#>>'{measures,extraction,prior_week}', '-') || ')',
    'Verified admission: ' || coalesce(p#>>'{measures,admission,n}', '-') || ' (prior week ' || coalesce(p#>>'{measures,admission,prior_week}', '-') || ')',
    'Consumer-resolvable: ' || coalesce(p#>>'{measures,consumer,n}', '-') || ' (prior week ' || coalesce(p#>>'{measures,consumer,prior_week}', '-') || ')',
    'Open findings: P0 ' || coalesce(p#>>'{open,P0}', '0') || ', P1 ' || coalesce(p#>>'{open,P1}', '0') || ', P2 ' || coalesce(p#>>'{open,P2}', '0'),
    'This week: ' || coalesce(p#>>'{changes,opened}', '0') || ' opened, ' || coalesce(p#>>'{changes,resolved}', '0') || ' resolved, ' || coalesce(p#>>'{changes,reopened}', '0') || ' reopened',
    'Top root causes: ' || coalesce((select string_agg((z->>'label') || ' (' || (z->>'providers') || ' providers)', '; ') from jsonb_array_elements(p->'top_root_causes') z), 'none'),
    'Layer 4 workload: ' || coalesce((p->'layer4_pending')::text, '{}') || '; readiness ' || coalesce((p->'readiness')::text, '{}'),
    'Entry-matrix AI spend: US$' || coalesce(p->>'spend_usd', '0'),
    'Decisions for the Platform Admin: ' || coalesce((select string_agg(x, '; ') from jsonb_array_elements_text(p->'decisions') x), 'none'),
    'Details: Coverage & completeness › Attributes › Academic entry requirements.')
$_$;


ALTER FUNCTION "security"."aer_weekly_text_v1"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ai_canary_judge_v1"("p_proposal" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare p record; v_c jsonb; v_b jsonb; v jsonb; v_n int;
begin
  perform set_config('cf247.ai_eval_path', 'on', true);
  select * into p from pipeline.ai_improvement_proposals where id = p_proposal for update;
  with j as (
    select c.arm, jsonb_build_object('label', x.label, 'expected', x.expected, 'rejected', x.rejected, 'needs_quote', f.needs_quote, 'tier', x.tier, 'answered', true,
                                     'verdict', c.verdict, 'value', c.value, 'quote_on_page', c.quote_on_page, 'error', c.error, 'cost_usd', c.cost_usd,
                                     'tokens_in', c.tokens_in, 'tokens_out', c.tokens_out) pair
      from pipeline.ai_canary_assignments c
      join lateral (select * from pipeline.ai_eval_examples x where x.entity_id = c.entity_id and x.family = c.family and x.tier = 'person' and x.active
                       and x.decided_at > c.answered_at order by x.decided_at limit 1) x on true
      join pipeline.ai_eval_families f on f.code = x.family
     where c.proposal_id = p.id and c.answered_at is not null)
  select security.ai_eval_metrics_v1((select coalesce(jsonb_agg(pair), '[]') from j where arm = 'candidate')),
         security.ai_eval_metrics_v1((select coalesce(jsonb_agg(pair), '[]') from j where arm = 'current')),
         (select count(*) from j where arm = 'candidate') into v_c, v_b, v_n;
  if v_n < security.pipeline_num_v1('ai_eval.canary_min_judged', 20) then
    return jsonb_build_object('proposal', p.code, 'verdict', 'canary running', 'judged', v_n);
  end if;
  v := security.ai_eval_verdict_v1(v_b, v_c, p.acceptance_criteria) || jsonb_build_object('candidate', v_c, 'current', v_b, 'judged', v_n, 'at', now());
  if (v->>'passed')::boolean then
    update pipeline.ai_improvement_proposals set actual_results = actual_results || jsonb_build_object('canary', v || jsonb_build_object('verdict', 'passed canary')) where id = p.id;
    return jsonb_build_object('proposal', p.code, 'verdict', 'passed canary') || v;
  end if;
  perform security.ai_proposal_rollback_v1(p.id, 'canary failed: ' || case when jsonb_array_length(v->'regressions') > 0 then 'regression in ' || (v->>'regressions') else 'no measurable benefit' end, v);
  return jsonb_build_object('proposal', p.code, 'verdict', 'rolled back') || v;
end $$;


ALTER FUNCTION "security"."ai_canary_judge_v1"("p_proposal" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ai_canary_pick_v1"("p_code" "text", "p_item_key" "text", "p_family" "text" DEFAULT NULL::"text", "p_entity_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_cur record; p record; a record; v_bucket int;
begin
  perform set_config('cf247.ai_eval_path', 'on', true);
  select id, version, body_md5, model_identifier into v_cur from pipeline.ai_instruction_versions where code = p_code and status = 'current';
  if security.pipeline_num_v1('ai_eval.canary_on', 0) <> 1 then
    return jsonb_build_object('version_id', v_cur.id, 'version', v_cur.version, 'model', v_cur.model_identifier, 'canary', false, 'why', 'canary off');
  end if;
  select pr.* into p from pipeline.ai_improvement_proposals pr join pipeline.ai_instruction_versions cv on cv.id = pr.candidate_version_id
   where pr.status = 'canary' and cv.code = p_code order by pr.id limit 1;
  if not found then return jsonb_build_object('version_id', v_cur.id, 'version', v_cur.version, 'model', v_cur.model_identifier, 'canary', false, 'why', 'no candidate in canary'); end if;
  select * into a from pipeline.ai_canary_assignments where proposal_id = p.id and item_key = p_item_key;
  if not found then
    v_bucket := abs(hashtext(p.code || ':' || p_item_key)) % 100;
    insert into pipeline.ai_canary_assignments(proposal_id, item_key, family, entity_id, arm, version_id)
    select p.id, p_item_key, coalesce(p_family, p.family), p_entity_id,
           case when v_bucket < security.pipeline_num_v1('ai_eval.canary_share_pct', 5)
                 and (select count(*) from pipeline.ai_canary_assignments c where c.proposal_id = p.id and c.arm = 'candidate'
                        and c.assigned_at >= date_trunc('day', now() at time zone 'Australia/Sydney') at time zone 'Australia/Sydney')
                     < security.pipeline_num_v1('ai_eval.canary_max_items_per_day', 50)
                then 'candidate' else 'current' end,
           case when v_bucket < security.pipeline_num_v1('ai_eval.canary_share_pct', 5)
                 and (select count(*) from pipeline.ai_canary_assignments c where c.proposal_id = p.id and c.arm = 'candidate'
                        and c.assigned_at >= date_trunc('day', now() at time zone 'Australia/Sydney') at time zone 'Australia/Sydney')
                     < security.pipeline_num_v1('ai_eval.canary_max_items_per_day', 50)
                then p.candidate_version_id else v_cur.id end
    returning * into a;
  end if;
  return (select jsonb_build_object('version_id', v.id, 'version', v.version, 'model', v.model_identifier, 'body', case when a.arm = 'candidate' then v.body end,
                                    'canary', a.arm = 'candidate', 'proposal', p.code) from pipeline.ai_instruction_versions v where v.id = a.version_id);
end $$;


ALTER FUNCTION "security"."ai_canary_pick_v1"("p_code" "text", "p_item_key" "text", "p_family" "text", "p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ai_central_settings_trg"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if coalesce(current_setting('cf247.ai_route_sync', true), '') <> 'on' and (to_jsonb(new)->>'model_identifier' is distinct from to_jsonb(old)->>'model_identifier' or to_jsonb(new)->'chain' is distinct from to_jsonb(old)->'chain') then
    raise exception 'the model is chosen on Models & services (each service has its own route); it can no longer be set here' using errcode = '23514';
  end if;
  return new;
end $$;


ALTER FUNCTION "security"."ai_central_settings_trg"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ai_central_sync_v1"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare m record; v_chain text[];
begin
  -- display copies only: nothing chooses a model from them any more
  perform set_config('cf247.ai_route_sync', 'on', true);
  select x->>'code' code, x->>'model_identifier' model_identifier into m from jsonb_array_elements(security.ai_route_v1('calendar_reading')->'models') with ordinality t(x, o) order by o limit 1;
  if m.code is not null then
    update pipeline.central_ai_settings s set model_code = m.code, model_identifier = m.model_identifier, changed_at = now(),
           reason = 'copy of the intake calendar route (Models & services)' where s.id = 1 and s.model_identifier is distinct from m.model_identifier;
  end if;
  select array_agg(x->>'code' order by o) into v_chain from jsonb_array_elements(security.ai_route_v1('scholarship_extraction')->'models') with ordinality t(x, o);
  if v_chain is not null then
    update pipeline.scholarship_ai_extract_settings s set chain = v_chain, changed_at = now(), reason = 'copy of the scholarship route (Models & services)'
     where s.id = 1 and s.chain is distinct from v_chain;
  end if;
  -- pipeline.scholarship_ai_models: every allowed model has a row (scholarship_ai_queue.model_code refers to it); the first model of the
  -- scholarship route is 'active' and the others 'candidate'. A copy of the route: it switches nothing on (AI admission has its own switch).
  insert into pipeline.scholarship_ai_models (code, label, model_identifier, status, sort)
  select c.code, c.label, c.model_identifier, 'candidate', c.sort from pipeline.ai_model_catalogue c
   where c.status = 'allowed' and not exists (select 1 from pipeline.scholarship_ai_models x where x.code = c.code);
  if v_chain is not null then
    update pipeline.scholarship_ai_models x set status = 'candidate' where x.status = 'active' and x.code <> v_chain[1];
    update pipeline.scholarship_ai_models x set status = 'active', activated_at = now(), reason = 'first model of the scholarship route (Models & services)'
     where x.code = v_chain[1] and x.status <> 'active';
  end if;
  perform set_config('cf247.ai_route_sync', 'off', true);
end $$;


ALTER FUNCTION "security"."ai_central_sync_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ai_enrich_routes_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_rt jsonb; v_routes jsonb := '{}'::jsonb; v_held jsonb := '{}'::jsonb; v_off jsonb := '[]'::jsonb; v_lim jsonb := '[]'::jsonb; v_except jsonb := '[]'::jsonb;
        v_off_rest boolean := false; v_lim_rest boolean := false; v_top jsonb; v_top_free jsonb; v_f jsonb;
begin
  for r in select * from pipeline.ai_service_routes x where x.lane = 'enrich_fields' order by x.sort, x.service_code loop
    v_rt := security.ai_route_v1(r.service_code);
    v_routes := v_routes || jsonb_build_object(r.service_code, v_rt);
    v_f := r.ledger_match #> '{where,field}';
    if v_f is null then v_except := coalesce(r.ledger_match #> '{where_not,field}', '[]'::jsonb); end if;
    if (v_rt->>'held')::boolean then
      v_held := v_held || jsonb_build_object(r.service_code, v_rt->>'held_reason');
      if not coalesce((v_rt->>'on_demand_exempt')::boolean, false) then
        if v_f is not null then v_off := v_off || v_f; else v_off_rest := true; end if;
      else
        if v_f is not null then v_lim := v_lim || v_f; else v_lim_rest := true; end if;
      end if;
    elsif v_top_free is null and r.service_code <> 'course_entry_requirements' then v_top_free := v_rt;
    end if;
    if v_top is null and r.service_code <> 'course_entry_requirements' and v_rt->>'model' is not null then v_top := v_rt; end if;
  end loop;
  return jsonb_build_object('routes', v_routes, 'held', v_held, 'off_fields', v_off, 'off_rest', v_off_rest, 'limit_fields', v_lim, 'limit_rest', v_lim_rest,
                            'rest_except', v_except, 'on_demand_providers', to_jsonb(security.ai_on_demand_providers_v1('course_description')),
                            'top', coalesce(v_top_free, v_top, v_routes->'course_description', '{}'::jsonb));
end $$;


ALTER FUNCTION "security"."ai_enrich_routes_v1"() OWNER TO "postgres";


