CREATE OR REPLACE FUNCTION "security"."alert_delivery_output_v1"("p_batch" "uuid", "p_md5" "text", "p_items" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int; v_via text := 'scheduled task (generated, receipt unverified)';
begin
  update pipeline.alert_delivery_batches set transport_state = 'generated', generated_at = now(), output_md5 = p_md5, output_items = p_items
   where batch_id = p_batch and transport_state = 'leased';
  get diagnostics n = row_count;
  if n = 1 then
    with g as (update pipeline.alert_delivery_attempts set state = 'generated' where batch_id = p_batch and state = 'leased' returning alert_source, alert_id)
    , pf as (update pipeline.platform_alerts a set status = 'sent', sent_at = now(), sent_via = v_via, lease_until = null
              where a.status in ('pending', 'sending') and a.id in (select alert_id from g where alert_source = 'platform') returning 1)
    update pipeline.queue_watch_alerts q set sent_at = now(), sent_via = v_via where q.sent_at is null and q.id in (select alert_id from g where alert_source = 'queue_watch');
  end if;
  return jsonb_build_object('batch_id', p_batch, 'recorded', n = 1, 'receipt', 'unverified (the channel exposes no acknowledgement)');
end $$;


ALTER FUNCTION "security"."alert_delivery_output_v1"("p_batch" "uuid", "p_md5" "text", "p_items" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."alert_delivery_receipt_v1"("p_batch" "uuid", "p_confirmed" boolean, "p_channels" "text"[] DEFAULT '{}'::"text"[], "p_actor" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare b pipeline.alert_delivery_batches%rowtype; n int := 0; v_unv text := 'scheduled task (generated, receipt unverified)';
begin
  if p_actor is null or length(p_actor) = 0 then raise exception 'actor required'; end if;
  select * into b from pipeline.alert_delivery_batches where batch_id = p_batch for update;
  if not found then raise exception 'unknown batch'; end if;
  if b.receipt_state in ('confirmed', 'not_received') then return jsonb_build_object('batch_id', p_batch, 'unchanged', true, 'receipt_state', b.receipt_state); end if;
  update pipeline.alert_delivery_batches set receipt_state = case when p_confirmed then 'confirmed' else 'not_received' end, receipt_channels = coalesce(p_channels, '{}'),
         receipt_by = p_actor, receipt_at = now(), receipt_note = left(p_note, 500) where batch_id = p_batch;
  if p_confirmed then
    with g as (update pipeline.alert_delivery_attempts set state = 'acknowledged' where batch_id = p_batch and state in ('leased', 'generated') returning alert_source, alert_id)
    , pf as (update pipeline.platform_alerts a set sent_via = 'scheduled task (receipt confirmed)' where a.sent_via = v_unv and a.id in (select alert_id from g where alert_source = 'platform') returning 1)
    update pipeline.queue_watch_alerts q set sent_via = 'scheduled task (receipt confirmed)' where q.sent_via = v_unv and q.id in (select alert_id from g where alert_source = 'queue_watch');
  else
    -- reported not received: release for a bounded retry and put back only the rows this lifecycle marked generated-unverified
    with g as (update pipeline.alert_delivery_attempts set state = 'released', released_at = now(), release_reason = 'not received (' || p_actor || ')' where batch_id = p_batch and state in ('leased', 'generated') returning alert_source, alert_id)
    , pf as (update pipeline.platform_alerts a set status = 'pending', sent_at = null, sent_via = null, next_attempt_at = now() where a.sent_via = v_unv and a.id in (select alert_id from g where alert_source = 'platform') returning 1)
    update pipeline.queue_watch_alerts q set sent_at = null, sent_via = null where q.sent_via = v_unv and q.id in (select alert_id from g where alert_source = 'queue_watch');
  end if;
  select count(*) into n from pipeline.alert_delivery_attempts where batch_id = p_batch;
  return jsonb_build_object('batch_id', p_batch, 'receipt_state', case when p_confirmed then 'confirmed' else 'not_received' end, 'alerts', n);
end $$;


ALTER FUNCTION "security"."alert_delivery_receipt_v1"("p_batch" "uuid", "p_confirmed" boolean, "p_channels" "text"[], "p_actor" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."alert_delivery_status_v1"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'channel_limitation', 'scheduled-task push and email expose no transport acknowledgement or receipt signal; generated means a message was written, not delivered',
    'unverified', (select count(*) from pipeline.alert_delivery_attempts where state = 'generated'),
    'unverified_overdue', (select count(*) from pipeline.alert_delivery_attempts a join pipeline.alert_delivery_batches b using (batch_id)
        where a.state = 'generated' and b.generated_at < now() - make_interval(hours => security.pipeline_num_v1('alerts.receipt_wait_hours', 4)::int)),
    'critical_unacknowledged', (select count(*) from pipeline.alert_delivery_attempts a join pipeline.platform_alerts p on a.alert_source = 'platform' and p.id = a.alert_id
        where a.state = 'generated' and p.severity = 'critical' and p.kind <> 'recovered'),
    'acknowledged', (select count(*) from pipeline.alert_delivery_attempts where state = 'acknowledged'),
    'released', (select count(*) from pipeline.alert_delivery_attempts where state = 'released'),
    'retries_exhausted', (select count(*) from (select alert_source, alert_id from pipeline.alert_delivery_attempts group by 1, 2
        having count(*) >= security.pipeline_num_v1('alerts.max_attempts', 5)::int and bool_and(state = 'released')) z),
    'last_receipt_confirmed_at', (select max(receipt_at) from pipeline.alert_delivery_batches where receipt_state = 'confirmed'));
$$;


ALTER FUNCTION "security"."alert_delivery_status_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."alert_delivery_take_v1"("p_purpose" "text" DEFAULT 'alerts'::"text", "p_test_ref" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_batch uuid; v_max int := security.pipeline_num_v1('alerts.digest_max_items', 15)::int; v_att int := security.pipeline_num_v1('alerts.max_attempts', 5)::int;
        v_retry numeric := security.pipeline_num_v1('alerts.retry_minutes', 10); v_alerts jsonb := '[]'::jsonb; v_left int := 0;
begin
  if p_purpose not in ('alerts', 'test') then raise exception 'purpose must be alerts or test'; end if;
  -- a run that took alerts and never generated its message has died: release them (no notification was produced, so no duplicate risk)
  update pipeline.alert_delivery_attempts a set state = 'released', released_at = now(), release_reason = 'lease expired before the message was generated'
   where a.state = 'leased' and exists (select 1 from pipeline.alert_delivery_batches b where b.batch_id = a.batch_id and b.lease_until < now() and b.transport_state = 'leased');
  update pipeline.alert_delivery_batches set transport_state = 'expired' where transport_state = 'leased' and lease_until < now();
  -- a critical alert is acknowledged when its issue is acknowledged or resolved in Platform health
  update pipeline.alert_delivery_attempts a set state = 'acknowledged'
   where a.state = 'generated' and a.alert_source = 'platform' and exists (select 1 from pipeline.platform_alerts p join pipeline.platform_issues i on i.id = p.issue_id
          where p.id = a.alert_id and (i.acknowledged_at is not null or i.resolved_at is not null));
  if p_purpose = 'test' then
    insert into pipeline.alert_delivery_batches(purpose, test_ref, lease_until) values ('test', coalesce(p_test_ref, 'TEST-' || to_char(now(), 'YYYYMMDDHH24MISS')), now() + interval '15 minutes') returning batch_id into v_batch;  -- fixed: delivery lease
    return jsonb_build_object('batch_id', v_batch, 'purpose', 'test', 'count', 0, 'alerts', '[]'::jsonb, 'note', 'notification-only test: no alert is taken or changed');
  end if;
  insert into pipeline.alert_delivery_batches(purpose, lease_until) values ('alerts', now() + interval '15 minutes') returning batch_id into v_batch;  -- fixed: delivery lease
  with cand as (
    select 'platform'::text src, p.id, p.created_at ts, n.n + 1 attempt_no, jsonb_build_object('source', 'platform', 'id', p.id, 'kind', p.kind, 'severity', p.severity, 'title', p.title, 'body', p.body, 'raised_at', p.created_at) j
      from pipeline.platform_alerts p
      cross join lateral (select count(*)::int n, max(x.released_at) last_rel from pipeline.alert_delivery_attempts x where x.alert_source = 'platform' and x.alert_id = p.id) n
     where p.status = 'pending' and p.next_attempt_at <= now()
       and not exists (select 1 from pipeline.alert_delivery_attempts x where x.alert_source = 'platform' and x.alert_id = p.id and x.state in ('leased', 'generated', 'acknowledged'))
       and n.n < v_att and (n.last_rel is null or n.last_rel + make_interval(mins => (v_retry * power(2, greatest(n.n - 1, 0)))::int) <= now())
    union all
    select 'queue_watch', q.id, q.raised_at, n.n + 1, jsonb_build_object('source', 'queue_watch', 'id', q.id, 'queue', q.key, 'state', q.state, 'title', q.title, 'body', q.body, 'raised_at', q.raised_at)
      from pipeline.queue_watch_alerts q
      cross join lateral (select count(*)::int n, max(x.released_at) last_rel from pipeline.alert_delivery_attempts x where x.alert_source = 'queue_watch' and x.alert_id = q.id) n
     where q.channel = 'notify' and q.sent_at is null
       and not exists (select 1 from pipeline.alert_delivery_attempts x where x.alert_source = 'queue_watch' and x.alert_id = q.id and x.state in ('leased', 'generated', 'acknowledged'))
       and n.n < v_att and (n.last_rel is null or n.last_rel + make_interval(mins => (v_retry * power(2, greatest(n.n - 1, 0)))::int) <= now())
  ), pick as (select * from cand order by ts, src, id limit v_max),
  ins as (insert into pipeline.alert_delivery_attempts(batch_id, alert_source, alert_id, attempt_no) select v_batch, src, id, attempt_no from pick on conflict do nothing returning alert_source, alert_id, attempt_id, attempt_no)
  select coalesce(jsonb_agg(pick.j || jsonb_build_object('attempt_id', ins.attempt_id, 'attempt_no', ins.attempt_no) order by pick.ts, pick.src, pick.id), '[]'::jsonb) into v_alerts
    from pick join ins on ins.alert_source = pick.src and ins.alert_id = pick.id;
  select count(*) into v_left from (select 1 from pipeline.platform_alerts p where p.status = 'pending'
       and not exists (select 1 from pipeline.alert_delivery_attempts x where x.alert_source = 'platform' and x.alert_id = p.id and x.state in ('leased', 'generated', 'acknowledged'))
       and (select count(*) from pipeline.alert_delivery_attempts x where x.alert_source = 'platform' and x.alert_id = p.id) < v_att
     union all select 1 from pipeline.queue_watch_alerts q where q.channel = 'notify' and q.sent_at is null
       and not exists (select 1 from pipeline.alert_delivery_attempts x where x.alert_source = 'queue_watch' and x.alert_id = q.id and x.state in ('leased', 'generated', 'acknowledged'))
       and (select count(*) from pipeline.alert_delivery_attempts x where x.alert_source = 'queue_watch' and x.alert_id = q.id) < v_att) z;
  update pipeline.alert_delivery_batches set items = jsonb_array_length(v_alerts) where batch_id = v_batch;
  return jsonb_build_object('batch_id', v_batch, 'purpose', 'alerts', 'count', jsonb_array_length(v_alerts), 'alerts', v_alerts, 'still_waiting', greatest(v_left - jsonb_array_length(v_alerts), 0),
           'next', 'write the message, then select security.alert_delivery_output_v1(batch_id, md5 of the message, item count). The message is generated, not delivered: receipt stays unverified.');
end $$;


ALTER FUNCTION "security"."alert_delivery_take_v1"("p_purpose" "text", "p_test_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."api_field_dictionary_drift_v1"("p_surface" "text", "p_endpoint" "text", "p_response" "jsonb", "p_version" "text" DEFAULT 'v3'::"text") RETURNS TABLE("field_path" "text", "seen_type" "text", "dictionary_type" "text", "issue" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with recursive walk(path, val) as (
    select ''::text, p_response
    union all
    select c.path, c.val
    from walk w, lateral (
      select case when w.path = '' then e.key else w.path || '.' || e.key end, e.value
      from jsonb_each(case when jsonb_typeof(w.val) = 'object' then w.val else '{}'::jsonb end) e
      union all
      select w.path || '[]', a.value
      from jsonb_array_elements(case when jsonb_typeof(w.val) = 'array' then w.val else '[]'::jsonb end) a
    ) c(path, val)
  ), seen as (
    select w.path,
           case jsonb_typeof(w.val)
             when 'null' then null
             when 'boolean' then 'boolean'
             when 'object' then 'object'
             when 'number' then 'number'
             when 'string' then 'string'
             when 'array' then case
               when exists (select 1 from jsonb_array_elements(w.val) x where jsonb_typeof(x) = 'object') then 'array<object>'
               when exists (select 1 from jsonb_array_elements(w.val) x where jsonb_typeof(x) <> 'null') then 'array<string>'
               else 'array' end
           end t
    from walk w
    where w.path <> '' and w.path not like '%[]' -- an array's elements are described by the array's own type (array<string>, array<object>)
  ), agg as (
    select s.path, string_agg(distinct s.t, '/' order by s.t) types, bool_or(s.t is null) has_null from seen s group by s.path
  )
  select * from (
    select a.path, a.types, d.data_type,
           case
             when d.id is null then 'not in dictionary'
             when d.deprecated_in is not null then 'deprecated in ' || d.deprecated_in
             when a.has_null and not d.is_nullable then 'null where the dictionary says not nullable'
             when a.types is null then null
             when exists (
               select 1 from unnest(string_to_array(a.types, '/')) t
               where not (t = d.data_type
                          or (t = 'number' and d.data_type = 'integer')
                          or (t = 'string' and d.data_type in ('date', 'timestamptz'))
                          or (t = 'array' and d.data_type like 'array<%'))
             ) then 'type differs'
           end issue
    from agg a
    left join ref.api_field_dictionary d
      on d.api_surface = p_surface and d.version = p_version and d.endpoint = p_endpoint and d.field_path = a.path
  ) r
  where r.issue is not null
  order by 1;
$$;


ALTER FUNCTION "security"."api_field_dictionary_drift_v1"("p_surface" "text", "p_endpoint" "text", "p_response" "jsonb", "p_version" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."api_field_dictionary_drift_v1"("p_surface" "text", "p_endpoint" "text", "p_response" "jsonb", "p_version" "text") IS 'REQ-76: lists paths of one live API v3 response that ref.api_field_dictionary does not hold, holds as deprecated, or holds with another JSON type. Empty means the dictionary matches the response.';



CREATE OR REPLACE FUNCTION "security"."api_field_dictionary_sync_v1"("p_version" "text", "p_release" "text", "p_fields" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_bad text;
  v_ins int := 0;
  v_upd int := 0;
  v_dep int := 0;
  v_total int;
begin
  if coalesce(btrim(p_version), '') = '' or coalesce(btrim(p_release), '') = '' then
    raise exception 'INVALID_INPUT: version and release are required' using errcode = '22023';
  end if;
  if p_fields is null or jsonb_typeof(p_fields) <> 'array' or jsonb_array_length(p_fields) = 0 then
    raise exception 'INVALID_INPUT: fields must be a non-empty list' using errcode = '22023';
  end if;

  -- every entry must be complete and valid before anything is written
  select format('entry %s: %s', i, why) into v_bad
  from (
    select i, case
      when jsonb_typeof(f) <> 'object' then 'not an object'
      when coalesce(f->>'api_surface', '') not in ('website', 'zoho', 'shared') then 'api_surface must be website, zoho or shared'
      when coalesce(btrim(f->>'endpoint'), '') = '' then 'endpoint is required'
      when coalesce(btrim(f->>'field_path'), '') = '' then 'field_path is required'
      when coalesce(f->>'data_type', '') not in ('string', 'integer', 'number', 'boolean', 'date', 'timestamptz', 'object', 'array<string>', 'array<object>') then 'data_type ' || coalesce(f->>'data_type', 'missing') || ' is not allowed'
      when jsonb_typeof(f->'is_nullable') is distinct from 'boolean' then 'is_nullable must be true or false'
      when f ? 'allowed_values' and jsonb_typeof(f->'allowed_values') not in ('array', 'null') then 'allowed_values must be a list'
      when f ? 'req_ids' and jsonb_typeof(f->'req_ids') not in ('array', 'null') then 'req_ids must be a list'
      when coalesce(btrim(f->>'description'), '') = '' then 'description is required'
    end why
    from jsonb_array_elements(p_fields) with ordinality as e(f, i)
  ) x
  where why is not null
  order by i
  limit 1; -- fixed: report the first bad entry only

  if v_bad is null then
    select format('%s %s %s is listed twice', s, ep, fp) into v_bad
    from (select f->>'api_surface' s, f->>'endpoint' ep, f->>'field_path' fp from jsonb_array_elements(p_fields) f) d
    group by s, ep, fp having count(*) > 1
    limit 1; -- fixed: report the first duplicate only
  end if;
  if v_bad is not null then
    raise exception 'INVALID_INPUT: %', v_bad using errcode = '22023';
  end if;

  with src as (
    select f->>'api_surface' api_surface, btrim(f->>'endpoint') endpoint, btrim(f->>'field_path') field_path, f->>'data_type' data_type,
           (f->>'is_nullable')::boolean is_nullable,
           case when jsonb_typeof(f->'allowed_values') = 'array' then f->'allowed_values' end allowed_values,
           coalesce(array(select jsonb_array_elements_text(case when jsonb_typeof(f->'req_ids') = 'array' then f->'req_ids' else '[]'::jsonb end) order by 1), '{}') req_ids,
           nullif(btrim(f->>'source_table'), '') source_table, nullif(btrim(f->>'source_column'), '') source_column, btrim(f->>'description') description,
           case when f ? 'example_value' and jsonb_typeof(f->'example_value') <> 'null' then f->'example_value' end example_value,
           coalesce(nullif(btrim(f->>'introduced_in'), ''), 'v3.0') introduced_in
    from jsonb_array_elements(p_fields) f
  ), up as (
    insert into ref.api_field_dictionary as d (api_surface, version, endpoint, field_path, data_type, is_nullable, allowed_values, req_ids, source_table,
                                               source_column, description, example_value, introduced_in)
    select api_surface, p_version, endpoint, field_path, data_type, is_nullable, allowed_values, req_ids, source_table, source_column, description,
           example_value, introduced_in
    from src
    on conflict (api_surface, version, endpoint, field_path) do update
      set data_type = excluded.data_type, is_nullable = excluded.is_nullable, allowed_values = excluded.allowed_values, req_ids = excluded.req_ids,
          source_table = excluded.source_table, source_column = excluded.source_column, description = excluded.description,
          example_value = excluded.example_value, introduced_in = excluded.introduced_in, deprecated_in = null, updated_at = now()
      where (d.data_type, d.is_nullable, d.allowed_values, d.req_ids, d.source_table, d.source_column, d.description, d.example_value, d.introduced_in, d.deprecated_in)
            is distinct from
            (excluded.data_type, excluded.is_nullable, excluded.allowed_values, excluded.req_ids, excluded.source_table, excluded.source_column,
             excluded.description, excluded.example_value, excluded.introduced_in, null::text)
    returning (xmax = 0) inserted
  )
  select count(*) filter (where inserted), count(*) filter (where not inserted) into v_ins, v_upd from up;

  -- a field the list no longer carries, for a surface the list covers, is marked deprecated (never deleted)
  with covered as (select distinct f->>'api_surface' s from jsonb_array_elements(p_fields) f),
  listed as (select f->>'api_surface' s, btrim(f->>'endpoint') ep, btrim(f->>'field_path') fp from jsonb_array_elements(p_fields) f),
  gone as (
    update ref.api_field_dictionary d set deprecated_in = p_release, updated_at = now()
    where d.version = p_version and d.deprecated_in is null and d.api_surface in (select s from covered)
      and not exists (select 1 from listed l where l.s = d.api_surface and l.ep = d.endpoint and l.fp = d.field_path)
    returning 1
  )
  select count(*) into v_dep from gone;

  v_total := jsonb_array_length(p_fields);
  return jsonb_build_object('version', p_version, 'release', p_release, 'fields', v_total, 'inserted', v_ins, 'updated', v_upd,
                            'unchanged', v_total - v_ins - v_upd, 'deprecated', v_dep);
end;
$$;


ALTER FUNCTION "security"."api_field_dictionary_sync_v1"("p_version" "text", "p_release" "text", "p_fields" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."api_field_dictionary_sync_v1"("p_version" "text", "p_release" "text", "p_fields" "jsonb") IS 'REQ-76: idempotent load of ref.api_field_dictionary from the reviewed field list (docs/api/v3/field-dictionary.json). Writes only changed fields; a field dropped from the list is marked deprecated_in, never deleted.';



CREATE OR REPLACE FUNCTION "security"."api_key_stats_v1"("p_key_name" "text", "p_since" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb; v_end timestamptz; v_start timestamptz; v_full jsonb;
begin
  select jsonb_build_object(
    'calls', count(*),
    'ok', count(*) filter (where r.status < 400),
    'client_errors', count(*) filter (where r.status >= 400 and r.status < 500 and r.status <> 429),
    'rate_limited', count(*) filter (where r.status = 429),
    'server_errors', count(*) filter (where r.status >= 500),
    'success_rate', case when count(*) > 0 then round(100.0 * count(*) filter (where r.status < 400) / count(*), 1) end,
    'bytes', coalesce(sum(r.bytes), 0),
    'avg_bytes', round(avg(r.bytes)),
    'max_bytes', max(r.bytes),
    'items', coalesce(sum(r.items), 0),
    'avg_ms', round(avg(r.elapsed_ms)),
    'p95_ms', round(percentile_cont(0.95) within group (order by r.elapsed_ms)),
    'max_ms', max(r.elapsed_ms),
    'first_call_at', min(r.at),
    'last_call_at', max(r.at),
    'last_ok_at', max(r.at) filter (where r.status < 400),
    'last_error_at', max(r.at) filter (where r.status >= 400),
    'last_error_code', (array_agg(r.error_code order by r.at desc) filter (where r.status >= 400))[1],
    'full_load_pages', count(*) filter (where r.action like 'sync\_full%' and r.status < 400),
    'full_load_bytes', coalesce(sum(r.bytes) filter (where r.action like 'sync\_full%' and r.status < 400), 0),
    'full_loads_completed', count(*) filter (where r.action = 'sync_full_end' and r.status < 400),
    'delta_calls', count(*) filter (where r.action = 'sync_delta' and r.status < 400),
    'delta_items', coalesce(sum(r.items) filter (where r.action = 'sync_delta' and r.status < 400), 0),
    'delta_bytes', coalesce(sum(r.bytes) filter (where r.action = 'sync_delta' and r.status < 400), 0),
    'last_delta_at', max(r.at) filter (where r.action = 'sync_delta' and r.status < 400),
    'exports', count(*) filter (where r.action = 'export' and r.status < 400),
    'export_bytes', coalesce(sum(r.bytes) filter (where r.action = 'export' and r.status < 400), 0),
    'searches', count(*) filter (where r.action = 'search' and r.status < 400),
    'previous_key_calls', (select count(*) from pipeline.api_requests p where p.key_name = p_key_name || '#previous' and p.at >= p_since),
    'previous_key_last_at', (select max(p.at) from pipeline.api_requests p where p.key_name = p_key_name || '#previous'))
    into v
    from pipeline.api_requests r where r.key_name = p_key_name and r.at >= p_since;
  -- the last completed full load (any time in the kept log): when it started and finished, pages, items, size
  select max(r.at) into v_end from pipeline.api_requests r where r.key_name = p_key_name and r.action = 'sync_full_end' and r.status < 400;
  if v_end is not null then
    select coalesce(max(r.at), v_end) into v_start from pipeline.api_requests r
     where r.key_name = p_key_name and r.action = 'sync_full_start' and r.status < 400 and r.at <= v_end
       and r.at > coalesce((select max(e.at) from pipeline.api_requests e where e.key_name = p_key_name and e.action = 'sync_full_end' and e.status < 400 and e.at < v_end), '-infinity');
    select jsonb_build_object('started_at', v_start, 'finished_at', v_end, 'pages', count(*), 'items', coalesce(sum(r.items), 0), 'bytes', coalesce(sum(r.bytes), 0),
                              'seconds', round(extract(epoch from v_end - v_start)))
      into v_full from pipeline.api_requests r
     where r.key_name = p_key_name and r.action like 'sync\_full%' and r.status < 400 and r.at between v_start and v_end;
  end if;
  return v || jsonb_build_object('last_full_load', v_full,
    'last_full_load_started_at', (select max(r.at) from pipeline.api_requests r where r.key_name = p_key_name and r.action = 'sync_full_start' and r.status < 400));
end $$;


ALTER FUNCTION "security"."api_key_stats_v1"("p_key_name" "text", "p_since" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."api_usage_refresh_v1"("p_trigger" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare t timestamptz := clock_timestamp(); v_roll jsonb; v_n int := 0; k record; p record; v_ms int; v_res jsonb;
begin
  if coalesce(p_trigger, '') not in ('daily', 'on_demand') then raise exception 'INVALID_INPUT: trigger' using errcode = '22023'; end if;
  v_roll := security.api_usage_rollup_v1();
  for k in select key_name from private.api_keys loop
    for p in select * from (values ('24h', interval '1 day'), ('7d', interval '7 days'), ('30d', interval '30 days')) x(period, span) loop  -- fixed: the three periods the screen shows
      insert into pipeline.api_usage_summary(key_name, period, computed_at, stats)
      values (k.key_name, p.period, now(), security.api_key_stats_v1(k.key_name, now() - p.span))
      on conflict (key_name, period) do update set computed_at = excluded.computed_at, stats = excluded.stats;
      v_n := v_n + 1;
    end loop;
  end loop;
  v_ms := round(extract(epoch from clock_timestamp() - t) * 1000);
  v_res := v_roll || jsonb_build_object('summary_rows', v_n);
  insert into pipeline.api_usage_refreshes(trigger, by_user, elapsed_ms, result) values (p_trigger, auth.uid(), v_ms, v_res);
  return v_res || jsonb_build_object('at', now(), 'trigger', p_trigger, 'elapsed_ms', v_ms);
end $$;


ALTER FUNCTION "security"."api_usage_refresh_v1"("p_trigger" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."api_usage_rollup_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int; v_del int;
begin
  insert into pipeline.api_usage_daily(day, platform, api_version, key_name, action, calls, ok, client_errors, rate_limited, server_errors, avg_ms, p95_ms, max_ms, items, bytes, first_at, last_at)
  select (r.at at time zone 'Australia/Melbourne')::date, r.platform, r.api_version, coalesce(r.key_name, '(no key)'), coalesce(r.action, '(none)'),
         count(*), count(*) filter (where r.status < 400), count(*) filter (where r.status >= 400 and r.status < 500 and r.status <> 429),
         count(*) filter (where r.status = 429), count(*) filter (where r.status >= 500),
         round(avg(r.elapsed_ms)), round(percentile_cont(0.95) within group (order by r.elapsed_ms)), max(r.elapsed_ms),
         sum(coalesce(r.items, 0)), sum(coalesce(r.bytes, 0)), min(r.at), max(r.at)
    from pipeline.api_requests r
   where r.at >= date_trunc('day', now() at time zone 'Australia/Melbourne') at time zone 'Australia/Melbourne' - make_interval(days => 1)  -- fixed: today and yesterday (Melbourne) are summed again each run
   group by 1, 2, 3, 4, 5
  on conflict (day, platform, api_version, key_name, action) do update set calls = excluded.calls, ok = excluded.ok, client_errors = excluded.client_errors,
     rate_limited = excluded.rate_limited, server_errors = excluded.server_errors, avg_ms = excluded.avg_ms, p95_ms = excluded.p95_ms, max_ms = excluded.max_ms,
     items = excluded.items, bytes = excluded.bytes, first_at = excluded.first_at, last_at = excluded.last_at;
  get diagnostics v_n = row_count;
  update private.api_keys k set last_used_at = x.last_at
    from (select key_name, max(at) last_at from pipeline.api_requests where key_name is not null group by 1) x
   where x.key_name = k.key_name and (k.last_used_at is null or k.last_used_at < x.last_at);
  delete from pipeline.api_requests where at < now() - make_interval(days => security.pipeline_num_v1('zoho.log_keep_days', 90)::int);
  get diagnostics v_del = row_count;
  return jsonb_build_object('summary_rows', v_n, 'log_rows_removed', v_del);
end $$;


ALTER FUNCTION "security"."api_usage_rollup_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."api_v3_daily_admittance_v1"("p_date" "date" DEFAULT NULL::"date") RETURNS TABLE("field" "text", "req_ids" "text", "snapshot_date" "date", "admitted" bigint, "yesterday_admitted" bigint, "daily_admitted_gain" bigint, "eligible" bigint, "pct" numeric, "computed_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with d as (select coalesce(p_date, (select max(f.snapshot_date) from pipeline.field_coverage_daily f)) t),
  m(field, req_ids, ord) as (values
    ('v3_study_load', 'REQ-52', 1), ('v3_empty_reason', 'REQ-53', 2), ('v3_campus_primary', 'REQ-75 (D-4)', 3), ('v3_accreditations', 'REQ-57 (D-3)', 4),
    ('v3_grade_normalised', 'REQ-19', 5), ('v3_destination', 'REQ-65, REQ-67, REQ-68', 6), ('official_url', 'core', 7), ('description', 'core', 8),
    ('academic_entry', 'core', 9), ('english', 'core', 10), ('intakes', 'core', 11), ('provider_tuition', 'core', 12), ('registered_tuition', 'core', 13),
    ('p_entry_matrix', 'core', 14), ('p_registrations', 'core', 15)),
  td as (select f.field, sum(f.filled) filled, sum(f.total) total, max(f.computed_at) at from pipeline.field_coverage_daily f, d where f.snapshot_date = d.t group by f.field),
  yd as (select f.field, sum(f.filled) filled from pipeline.field_coverage_daily f, d where f.snapshot_date = d.t - 1 group by f.field)
  select m.field, m.req_ids, (select t from d), td.filled, yd.filled, td.filled - yd.filled, td.total,
         round(100.0 * td.filled / nullif(td.total, 0), 1), td.at
    from m left join td on td.field = m.field left join yd on yd.field = m.field
   order by m.ord
$$;


ALTER FUNCTION "security"."api_v3_daily_admittance_v1"("p_date" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."api_v3_daily_admittance_v1"("p_date" "date") IS 'CF-247 API v3 daily admittance (Platform Admin 16 Nov 2026 20:17): per field, admitted today, admitted yesterday, daily admitted gain, eligible total and share, from pipeline.field_coverage_daily. Read by the Telemetry sheet tab API_v3_Daily_Admittance and the 08:15 report.';



CREATE OR REPLACE FUNCTION "security"."api_v3_field_coverage_v1"() RETURNS TABLE("country_code" "text", "field" "text", "total" bigint, "filled" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with ap as (
    select p.id, security.coverage_country(p.id) cc
      from catalogue.providers p
     where coalesce(p.lifecycle_status, 'active') = 'active'
       and exists (select 1 from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active')),
  ac as (
    select c.id, ap.cc, c.study_load, c.empty_reason_code
      from catalogue.courses c join ap on ap.id = c.provider_id
     where c.lifecycle_status = 'active')
  select cc, 'v3_study_load', count(*), count(*) filter (where study_load is not null) from ac group by cc
  union all
  select cc, 'v3_empty_reason', count(*), count(*) filter (where empty_reason_code is not null)
    from ac where not exists (select 1 from catalogue.course_campuses k where k.course_id = ac.id) group by cc
  union all
  select ap.cc, 'v3_campus_primary', count(*), count(*) filter (where exists (select 1 from catalogue.campuses k where k.provider_id = ap.id and k.is_primary))
    from ap where exists (select 1 from catalogue.campuses k where k.provider_id = ap.id and k.status = 'active') group by ap.cc
  union all
  select ap.cc, 'v3_accreditations', count(*), count(*) filter (where exists (select 1 from catalogue.provider_accreditations a where a.provider_id = ap.id and a.status = 'active'))
    from ap group by ap.cc
  union all
  select ap.cc, 'v3_grade_normalised', count(*), 0::bigint  -- PR E: admitted rows from the normalisation table
    from catalogue.provider_entry_matrix m join ap on ap.id = m.provider_id where m.status = 'active' group by ap.cc
  union all
  select 'AU', 'v3_destination', count(*), count(*) filter (where e.status = 'published' and e.terms_status = 'approved')
    from (select edition_id from destination.study_rules union all select edition_id from destination.city_profiles
          union all select edition_id from destination.career_outcomes) d
    left join destination.editions e on e.id = d.edition_id
  union all
  select ap.cc, 'p_entry_matrix', count(*), count(*) filter (where exists (select 1 from catalogue.provider_entry_matrix m where m.provider_id = ap.id and m.status = 'active'))
    from ap group by ap.cc
  union all
  select ap.cc, 'p_registrations', count(*), count(*) filter (where exists (select 1 from catalogue.provider_registrations r where r.provider_id = ap.id))
    from ap group by ap.cc
$$;


ALTER FUNCTION "security"."api_v3_field_coverage_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."api_v3_field_coverage_v1"() IS 'CF-247 API v3 daily admittance (Platform Admin 16 Nov 2026 20:17): total and admitted per country for the API v3 and request-register fields; recorded daily into pipeline.field_coverage_daily by security.field_coverage_record_v1.';



CREATE OR REPLACE FUNCTION "security"."apply_provider_fee_profiles_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue'
    AS $$
declare n int; b int;
begin
  with m as (
    select w.id, pf.rule_code, pf.resolved_basis
    from pipeline.layer3_work_items w
    join catalogue.courses c on c.id=w.entity_id
    join pipeline.provider_fee_profiles pf on pf.provider_id=c.provider_id and pf.active and pf.review_by>=current_date
    join pipeline.evidence_artifacts e on e.id=w.evidence_id
    join pipeline.layer3_interpretations i on i.id=w.interpretation_id
    where w.task_class='provider_current_tuition_validation'
      and w.status in ('pending','layer4_required')
      and w.candidate_context->'provider_current_tuition'->>'basis' in ('annual_or_indicative_requires_validation', pf.resolved_basis)
      and coalesce(w.candidate_context->'provider_current_tuition'->>'audience','')=pf.audience
      and e.source_url ~* pf.page_url_pattern
      and coalesce(i.evidence_quotes::text,'') !~* pf.exclusion_pattern
      and not (w.candidate_context ? 'provider_fee_rule'))
  update pipeline.layer3_work_items w
  set candidate_context = jsonb_set(jsonb_set(w.candidate_context,'{provider_current_tuition,basis}',to_jsonb(m.resolved_basis)),
                                    '{provider_current_tuition,basis_source}',to_jsonb('provider_fee_rule:'||m.rule_code))
                          || jsonb_build_object('provider_fee_rule',m.rule_code,'provider_fee_rule_applied_at',now()),
      updated_at=now()
  from m where w.id=m.id;
  get diagnostics n = row_count;
  update pipeline.layer3_work_items w
  set candidate_context = jsonb_set(w.candidate_context,'{provider_current_tuition,basis_source}',to_jsonb('provider_fee_rule:'||(w.candidate_context->>'provider_fee_rule'))),
      updated_at=now()
  where w.candidate_context ? 'provider_fee_rule'
    and not (w.candidate_context->'provider_current_tuition' ? 'basis_source')
    and w.status in ('pending','layer4_required');
  get diagnostics b = row_count;
  return jsonb_build_object('applied',n,'stamped',b);
end $$;


ALTER FUNCTION "security"."apply_provider_fee_profiles_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."au_publish_eligibility_v1"() RETURNS TABLE("provider_id" "uuid", "provider_name" "text", "provider_type" "text", "cricos_code" "text", "registration_status" "text", "registration_valid_to" "date", "courses_active" integer, "courses_listed" integer, "courses_not_listed" integer, "site_status" "text", "site_pages_kept" integer, "site_mapped_at" timestamp with time zone, "website" "text", "verdict" "text", "cause" "text", "owner" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with ed as (
    select p.created_at from pipeline.layer1_run_plans p
     where p.source_id = 'b5680d74-49c5-49a5-b198-a625f3e3fdcf' and p.course_hash is distinct from 'seen-tracking'
     order by p.created_at desc limit 1
  ), pv as (
    select p.id, coalesce(nullif(p.display_name, ''), p.canonical_name) nm, t.code ptype, p.website,
           (select upper(pr.registration_code) from catalogue.provider_registrations pr where pr.provider_id = p.id and lower(pr.registration_scheme) = 'cricos' order by pr.checked_at desc nulls last limit 1) code,
           (select pr.status from catalogue.provider_registrations pr where pr.provider_id = p.id and lower(pr.registration_scheme) = 'cricos' order by (pr.status = 'ended'), pr.checked_at desc nulls last limit 1) rstatus,
           (select max(pr.valid_to) from catalogue.provider_registrations pr where pr.provider_id = p.id and lower(pr.registration_scheme) = 'cricos' and pr.status = 'ended') rvalid_to,
           count(c.id)::int act,
           count(c.id) filter (where s.seen_at >= (select created_at from ed))::int listed
      from catalogue.providers p
      join ref.countries k on k.id = p.country_id and k.iso_alpha2 = 'AU'
      left join ref.provider_types t on t.id = p.provider_type_id
      left join catalogue.courses c on c.provider_id = p.id and c.lifecycle_status = 'active'
      left join catalogue.course_registrations cr on cr.course_id = c.id and lower(cr.scheme) = 'cricos'
      left join pipeline.layer1_register_row_state s on s.source_id = 'b5680d74-49c5-49a5-b198-a625f3e3fdcf' and s.record_key = upper(cr.registration_code)
     where p.publication_status = 'unpublished' and p.lifecycle_status = 'active'
     group by p.id, t.code
  )
  select pv.id, pv.nm, pv.ptype, pv.code, coalesce(pv.rstatus, 'none'), pv.rvalid_to, pv.act, pv.listed, pv.act - pv.listed,
         coalesce(d.status, 'not_checked'), coalesce(d.kept_count, 0), d.mapped_at, pv.website,
         case when coalesce(pv.rstatus, '') = 'ended' or pv.listed < security.pipeline_num_v1('publish.eligible_min_current_courses', 1) then 'hold'
              when d.status = 'mapped' and coalesce(d.kept_count, 0) >= security.pipeline_num_v1('publish.eligible_min_site_pages', 1) then 'publish'
              else 'hold' end,
         case when coalesce(pv.rstatus, '') = 'ended' then 'CRICOS registration ended (no course on the register since ' || coalesce(to_char(pv.rvalid_to, 'DD Mon YYYY'), '?') || ')'
              when pv.listed < security.pipeline_num_v1('publish.eligible_min_current_courses', 1) then 'no course on the current register edition'
              when d.status = 'mapped' and coalesce(d.kept_count, 0) >= security.pipeline_num_v1('publish.eligible_min_site_pages', 1) then 'registered and site answers'
              when d.status = 'mapped' then 'site answered but no course page kept'
              when d.status = 'failed' then 'site gave no course pages'
              when d.status = 'no_website' then 'no website on record'
              else 'site not checked yet' end,
         case when coalesce(pv.rstatus, '') = 'ended' or pv.listed < security.pipeline_num_v1('publish.eligible_min_current_courses', 1) then 'Register (Layer 1): nothing to publish'
              when d.status = 'mapped' and coalesce(d.kept_count, 0) >= security.pipeline_num_v1('publish.eligible_min_site_pages', 1) then 'Platform Admin: publish paste'
              when d.status = 'failed' or d.status = 'mapped' then 'Discovery review (site check)'
              when d.status = 'no_website' then 'Website check (find the provider''s site)'
              else 'Discovery (site not checked yet)' end
    from pv left join pipeline.coverage_provider_discovery d on d.provider_id = pv.id
$$;


ALTER FUNCTION "security"."au_publish_eligibility_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."au_publish_eligibility_v1"() IS 'CF-247 AU completion week (Platform Admin 26 Oct 2026 17:01): read-only; each unpublished active AU provider, eligible to publish (CRICOS registration current with courses on the register edition, and its site answers) or held with a named cause and owner';



CREATE OR REPLACE FUNCTION "security"."au_regional_class"("p_state" "text", "p_postcode" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $_$
  with x as (select upper(btrim(p_state)) st, case when btrim(coalesce(p_postcode,'')) ~ '^\d{4}$' then btrim(p_postcode)::int end pc),
  r as (select g.category, g.metro_area from ref.au_regional_postcode_ranges g, x where g.state_code=x.st and x.pc between g.pc_from and g.pc_to order by g.category limit 1)
  select case
    when x.st is null or x.st !~ '^AU-' or x.pc is null then null
    when x.st='AU-ACT' then jsonb_build_object('category',2,'metro_area','Canberra')
    when x.st='AU-NT' or x.pc=2899 then jsonb_build_object('category',3,'metro_area',null)
    when exists (select 1 from r) then (select jsonb_build_object('category',r.category,'metro_area',r.metro_area) from r)
    when x.st in ('AU-WA','AU-SA','AU-TAS') then jsonb_build_object('category',3,'metro_area',null)
    when x.st='AU-NSW' then jsonb_build_object('category',1,'metro_area','Sydney')
    when x.st='AU-VIC' then jsonb_build_object('category',1,'metro_area','Melbourne')
    when x.st='AU-QLD' then jsonb_build_object('category',1,'metro_area','Brisbane')
  end from x
$_$;


ALTER FUNCTION "security"."au_regional_class"("p_state" "text", "p_postcode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."au_state_from_postcode_v1"("p_postcode" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select case when p_postcode !~ '^\d{4}$' then null
              when p_postcode ~ '^(26[0-1]\d|29[0-2]\d|02\d\d)$' then 'ACT'
              when p_postcode ~ '^(1|2)' then 'NSW' when p_postcode ~ '^(3|8)' then 'VIC' when p_postcode ~ '^(4|9)' then 'QLD'
              when p_postcode ~ '^5' then 'SA' when p_postcode ~ '^6' then 'WA' when p_postcode ~ '^7' then 'TAS' when p_postcode ~ '^0[89]' then 'NT' end
$_$;


