CREATE OR REPLACE FUNCTION "security"."autonomy_audit_v1"("p_hours" integer DEFAULT 24) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare s timestamptz := now() - make_interval(hours => p_hours); v_book text[] := array['supersede_into_owner', 'confirm_condition_cleared', 'reclose_stale_reopen']; v_prog jsonb;
begin
  begin v_prog := security.pipeline_progress_table_v1(p_hours); exception when others then v_prog := jsonb_build_object('error', left(sqlerrm, 200)); end;
  return jsonb_build_object('window_hours', p_hours, 'since', s, 'categories', jsonb_build_array(
    jsonb_build_object('category', 'detected_automatically', 'value', (select count(*) from pipeline.integration_issues i where i.detected_at >= s and i.validation_layer <> 'manual'),
      'detail', jsonb_build_object('raised_by_hand', (select count(*) from pipeline.integration_issues i where i.detected_at >= s and i.validation_layer = 'manual'))),
    jsonb_build_object('category', 'diagnosed_automatically', 'value', (select count(*) from pipeline.integration_issues i where (i.diagnosis->>'at')::timestamptz >= s
                                                                         and coalesce(i.diagnosis->>'root_cause', 'unclassified') <> 'unclassified'),
      'detail', jsonb_build_object('unclassified', (select count(*) from pipeline.integration_issues i where (i.diagnosis->>'at')::timestamptz >= s
                                                     and coalesce(i.diagnosis->>'root_cause', 'unclassified') = 'unclassified'))),
    jsonb_build_object('category', 'remedied_automatically', 'value', (select count(*) from pipeline.ops_remedy_runs r join pipeline.ops_remedies m on m.code = r.remedy_code
                                                                        where r.started_at >= s and m.authority = 'auto' and r.remedy_code <> all (v_book) and r.result in ('acted', 'verified', 'verify_failed')),
      'detail', jsonb_build_object('bookkeeping_runs', (select count(*) from pipeline.ops_remedy_runs r where r.started_at >= s and r.remedy_code = any (v_book)),
                                   'by_remedy', (select coalesce(jsonb_object_agg(z.k, z.n), '{}'::jsonb) from (select r.remedy_code || '/' || r.result k, count(*) n from pipeline.ops_remedy_runs r
                                                  where r.started_at >= s and r.remedy_code <> all (v_book) group by 1) z))),
    jsonb_build_object('category', 'verified_automatically', 'value', (select count(*) from pipeline.ops_remedy_runs r where r.started_at >= s and r.result = 'verified' and r.remedy_code <> all (v_book)),
      'detail', jsonb_build_object('closed_by_controller', (select count(*) from pipeline.integration_issue_events e where e.at >= s and e.kind = 'closed' and e.actor in ('ops-controller', 'first-run-verify')),
                                   'bookkeeping_verified', (select count(*) from pipeline.ops_remedy_runs r where r.started_at >= s and r.result = 'verified' and r.remedy_code = any (v_book)))),
    jsonb_build_object('category', 'claude_engineering', 'value', (select count(distinct x.release) from security.ops_releases_v1() x where x.at >= s and x.source = 'migration'),
      'detail', jsonb_build_object('basis', 'migrations applied (releases built by Claude)',
        'issue_steps_by_integration_controller', (select count(*) from pipeline.integration_issue_events e where e.at >= s and e.kind in ('status', 'closed')
                                                   and (e.actor ilike '%integration%controller%' or e.actor ilike 'claude%')))),
    jsonb_build_object('category', 'platform_admin_authority', 'value', (select count(*) from pipeline.admin_control_events c where c.created_at >= s
                                                                          and (c.actor is not null or (c.area = 'layer4' and c.action like 'rule\_%'))),
      'detail', jsonb_build_object('basis', 'pastes, decisions and approved rule runs recorded in admin_control_events',
        'open_awaiting_decision', (select count(*) from pipeline.integration_issues i where i.status <> 'closed' and i.superseded_by is null and i.ops_state = 'needs_decision'))),
    jsonb_build_object('category', 'layer4_human_decision', 'value', (select count(*) from pipeline.layer4_decisions d where d.created_at >= s and d.actor_id is not null)
                                                                     + (select count(*) from pipeline.scholarship_ai_reviews r where r.decided_at >= s and r.decided_by is not null),
      'detail', jsonb_build_object('layer4', (select coalesce(jsonb_object_agg(z.a, z.n), '{}'::jsonb) from (select d.action a, count(*) n from pipeline.layer4_decisions d
                                               where d.created_at >= s and d.actor_id is not null group by 1) z),
                                   'scholarship_reviews', (select count(*) from pipeline.scholarship_ai_reviews r where r.decided_at >= s and r.decided_by is not null)))),
    'results', v_prog - 'scholarship_scope');
end $$;


ALTER FUNCTION "security"."autonomy_audit_v1"("p_hours" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."award_register_check"("p_child" "uuid", "p_parent" "uuid") RETURNS "text"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with st as (select same_year_tolerance sy, lagged_tolerance lg from pipeline.award_link_settings where id = 1),
       c as (select f.amount / nullif(co.duration_value, 0) * 52 py, f.amount a, co.duration_value w, extract(year from coalesce(f.source_snapshot_at::date, f.valid_from))::int ry from catalogue.courses co
               left join catalogue.course_fees f on f.course_id = co.id and f.fee_type = 'tuition' and f.basis = 'registered_total_course' and f.status = 'active' and f.audience in ('international', 'all') and f.amount > 0
              where co.id = p_child and co.duration_unit = 'weeks' order by f.valid_from desc nulls last limit 1),
       p as (select f.amount / nullif(co.duration_value, 0) * 52 py, f.amount a, co.duration_value w from catalogue.courses co
               left join catalogue.course_fees f on f.course_id = co.id and f.fee_type = 'tuition' and f.basis = 'registered_total_course' and f.status = 'active' and f.audience in ('international', 'all') and f.amount > 0
              where co.id = p_parent and co.duration_unit = 'weeks' order by f.valid_from desc nulls last limit 1),
       a as (select f.amount an, f.fee_year fy from catalogue.course_fees f where f.course_id = p_parent and f.fee_type = 'provider_current_tuition' and f.status = 'active' and f.audience = 'international' and f.amount > 0 order by f.fee_year desc nulls last, f.updated_at desc nulls last limit 1),
       d as (select c.py, c.a, c.w, c.ry, p.py ppy, p.a pa, p.w pw, a.an, a.fy, st.sy, st.lg,
                    case when a.an is not null then c.py / a.an - 1 when p.py is not null then c.py / p.py - 1 end diff,
                    case when a.an is not null and (a.fy is null or c.ry is null or a.fy <= c.ry) then st.sy else st.lg end below_ok
               from (select 1) one left join c on true left join p on true left join a on true cross join st)
  select case when security.is_double_degree_title((select canonical_title from catalogue.courses where id = p_parent)) then array['fail', 'parent is a double degree']
              when d.py is null then array['none', 'the award has no registered total']
              when d.an is null and d.ppy is null then array['none', 'the parent has no current fee and no registered total']
              when d.diff >= -d.below_ok and d.diff <= d.sy then
                   array['pass', 'register ' || round(d.a) || ' over ' || d.w || ' weeks = ' || round(d.py) || ' a year, ' || round(d.diff * 100, 1) || '% against ' || case when d.an is not null then 'the parent fee ' || round(d.an) || ' (' || d.fy || ')' else 'the parent register ' || round(d.pa) || ' over ' || d.pw || ' weeks' end || ' (allowed -' || round(d.below_ok * 100, 1) || '% to +' || round(d.sy * 100, 1) || '%)']
              else array['fail', 'register ' || round(d.a) || ' over ' || d.w || ' weeks = ' || round(d.py) || ' a year is ' || round(d.diff * 100, 1) || '% off ' || case when d.an is not null then 'the parent fee ' || round(d.an) || ' (' || d.fy || ')' else 'the parent register ' || round(d.pa) || ' over ' || d.pw || ' weeks' end || ' (allowed -' || round(d.below_ok * 100, 1) || '% to +' || round(d.sy * 100, 1) || '%)'] end
    from d
$$;


ALTER FUNCTION "security"."award_register_check"("p_child" "uuid", "p_parent" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."better_page_revert_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; n int := 0;
begin
  for r in
    select pg.course_id, pg.provider_id, pg.url,
           (select x.old_url from pipeline.page_link_repairs x where x.course_id = pg.course_id and x.reason = 'firecrawl search: page with the fields the adapter reads' order by x.id desc limit 1) old_url
      from pipeline.coverage_course_pages pg
     where pg.basis = 'firecrawl_upgrade' and pg.read_status = 'identity_mismatch'
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = pg.course_id and k.field = 'official_url')
  loop
    continue when r.old_url is null or r.old_url = r.url;
    insert into pipeline.page_link_repairs(course_id, provider_id, old_url, new_url, reason)
      values (r.course_id, r.provider_id, r.url, r.old_url, 'better page refused by the identity check: earlier page bound again');
    update pipeline.coverage_course_pages set url = r.old_url, basis = 'better_page_reverted', status = 'bound', bound_at = now(), read_status = null, read_at = null, http_status = null, fetched_via = null, identity_basis = null, evidence_id = null, candidates = null, leased_until = null, read_attempts = 0, next_read_at = now() where course_id = r.course_id and basis = 'firecrawl_upgrade';
    n := n + 1;
  end loop;
  return n;
end $$;


ALTER FUNCTION "security"."better_page_revert_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."bind_match_scope_refresh_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int;
begin
  insert into pipeline.bind_match_scope(provider_id, why, unbound)
  select x.provider_id, x.why, x.unbound from (
    select c.provider_id, case when exists (select 1 from pipeline.firecrawl_targets t where t.provider_id = c.provider_id and t.included) then 'tranche override' else 'top by courses without a page' end why,
           count(*) unbound, row_number() over (order by count(*) desc) rn,
           bool_or(exists (select 1 from pipeline.firecrawl_targets t where t.provider_id = c.provider_id and t.included)) ovr
      from catalogue.courses c join catalogue.providers p on p.id = c.provider_id join ref.countries k on k.id = p.country_id
     where c.lifecycle_status = 'active' and k.iso_alpha2 = 'AU'
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = c.provider_id)
       and not exists (select 1 from catalogue.course_links l where l.course_id = c.id and l.link_type = 'official_course' and l.status = 'active')
       and not security.enrich_focus_v1(c.provider_id)
     group by c.provider_id) x
   where x.ovr or x.rn <= security.pipeline_num_v1('bind.match_scope_top_n', 100)
  on conflict (provider_id) do update set why = excluded.why, unbound = excluded.unbound, refreshed_at = now();
  get diagnostics v_n = row_count;
  return v_n;
end $$;


ALTER FUNCTION "security"."bind_match_scope_refresh_v1"() OWNER TO "postgres";


