CREATE OR REPLACE FUNCTION "security"."ca_dli_apply_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_yes int := 0; v_clear int := 0;
begin
  with dli as (
    select distinct on (i.provider_id) i.provider_id, i.identifier
      from catalogue.provider_identifiers i
     where i.scheme = 'ircc_dli' and (i.valid_to is null or i.valid_to > now())
     order by i.provider_id, i.is_primary desc nulls last, i.verified_at desc nulls last),
  m as (
    select p.id,
           case when d.provider_id is not null then true end val,
           case when d.provider_id is not null then 'IRCC Designated Learning Institution (DLI ' || d.identifier || ')' end basis
      from catalogue.providers p
      left join dli d on d.provider_id = p.id
     where security.coverage_country(p.id) = 'CA'
       and (p.enrols_international is null or coalesce(p.enrols_international_basis, '') like 'IRCC Designated Learning Institution%')),
  u as (update catalogue.providers p set enrols_international = m.val, enrols_international_basis = m.basis
          from m where p.id = m.id and (p.enrols_international is distinct from m.val or p.enrols_international_basis is distinct from m.basis)
        returning m.val)
  select count(*) filter (where val), count(*) filter (where val is null) into v_yes, v_clear from u;
  if v_yes + v_clear > 0 then
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('layer1', 'ca_dli_apply', 'CA', jsonb_build_object('set_yes', v_yes, 'cleared', v_clear, 'rule', 'IRCC DLI: Platform Admin 20 Oct 2026 "All DLIs Yes"'), null);
  end if;
  return jsonb_build_object('set_yes', v_yes, 'cleared', v_clear);
end $$;


ALTER FUNCTION "security"."ca_dli_apply_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."ca_dli_apply_v1"() IS 'CF-247 20 Oct 2026: Canadian international-enrolment flag from the IRCC DLI number (Platform Admin "All DLIs Yes")';



CREATE OR REPLACE FUNCTION "security"."calendar_dated_periods_v1"("p_provider" "uuid") RETURNS TABLE("proposal_id" "uuid", "period" "text", "kind" "text", "year" integer, "month" integer, "day" integer, "on_date" "date", "rolling_text" "text", "quote" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with cal as (
    -- the latest approved calendar only (as security.enrich_parse_intake_periods_v1)
    select p.id, p.proposal from pipeline.provider_policy_proposals p
     where p.provider_id = p_provider and p.kind = 'intake_calendar' and p.status = 'approved'
     order by p.decided_at desc nulls last, p.created_at desc limit 1),
  per as (select cal.id, lower(btrim(e->>'period')) period, e from cal, jsonb_array_elements(coalesce(cal.proposal->'periods', '[]'::jsonb)) e),
  -- calendar-dates-v1: the parser's own dated starts and deadlines
  given as (
    select per.id, per.period, k.kind, nullif(x->>'year', '')::int y, nullif(x->>'month', '')::int m, nullif(x->>'day', '')::int d, x->>'quote' q
      from per, lateral (values ('start', per.e->'starts'), ('deadline', per.e->'deadlines')) k(kind, arr), jsonb_array_elements(coalesce(k.arr, '[]'::jsonb)) x
     where jsonb_typeof(k.arr) = 'array'),
  -- calendars approved before calendar-dates-v1: the start quotes the approved proposal holds (the first date in the quote, as the parser
  -- read it; the year only when printed in the same quote)
  quoted as (
    select per.id, per.period, 'start'::text kind, q,
           regexp_match(q, '(?:\m(\d{1,2})(?:st|nd|rd|th)?\s+(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\M|\m(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\s+(\d{1,2})(?:st|nd|rd|th)?\M)(?:,?\s+(20\d\d))?', 'i') d
      from per, jsonb_array_elements_text(coalesce(per.e->'quotes', '[]'::jsonb)) q
     where not (per.e ? 'starts')
       -- a stored quote about exams, census, results or a break is never a start date (live: "Supplementary exams start from | Tuesday 2 July 2024")
       and q !~* '\m(exams?|examinations?|supplementary|census|results|holidays?|break|recess|graduation|enrolment|withdraw\w*)\M'),
  quoted_dates as (
    select z.id, z.period, z.kind, coalesce(nullif(z.d[5], '')::int, (regexp_match(z.q, '\m(20\d\d)\M'))[1]::int) y,
           (array_position(array['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'], lower(left(coalesce(z.d[2], z.d[3]), 3))))::int m,
           -- a day range ("18 – 20 January 2027", live): which day the period starts is not certain, so no day (the year still counts)
           case when z.q !~ '\m\d{1,2}(st|nd|rd|th)?\s*[–—-]\s*\d{1,2}(st|nd|rd|th)?\s+[A-Za-z]' then coalesce(z.d[1], z.d[4])::int end d, z.q
      from quoted z where z.d is not null),
  quoted_kept as (
    -- a quoted start counts only for a month the approved proposal lists for that period
    select q.* from quoted_dates q join per on per.id = q.id and per.period = q.period
     where per.e->'months' @> to_jsonb(q.m)),
  dated as (select * from given union all select * from quoted_kept)
  select a.id, a.period, a.kind, a.y, a.m, a.d,
         case when a.y is not null and a.d between 1 and extract(day from (make_date(a.y, a.m, 1) + interval '1 month - 1 day'))::int  -- fixed: the last day of the month
              then make_date(a.y, a.m, a.d) end,
         null::text, left(a.q, 300)
    from dated a where a.m between 1 and 12
  union all
  select per.id, per.period, 'rolling', null, null, null, null, left(r, 300), left(r, 300)
    from per, jsonb_array_elements_text(coalesce(per.e->'deadline_rolling', '[]'::jsonb)) r
$$;


ALTER FUNCTION "security"."calendar_dated_periods_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."calendar_dated_periods_v1"("p_provider" "uuid") IS 'CF-247 intake dates (Platform Admin 2 Nov 2026 11:10 §2): the dated starts, dated deadlines and rolling-deadline wording of the provider''s latest approved academic calendar, from the parser''s calendar-dates-v1 fields or, for calendars approved before it, from the approved proposal''s stored start quotes (the year only when printed in the same quote). No date is formed without a printed day and year.';



CREATE OR REPLACE FUNCTION "security"."calendar_dated_periods_v2"("p_provider" "uuid") RETURNS TABLE("proposal_id" "uuid", "period" "text", "kind" "text", "year" integer, "month" integer, "day" integer, "on_date" "date", "rolling_text" "text", "quote" "text", "applies_to" "text", "meaning" "text", "url" "text", "evidence_id" "uuid", "year_ok" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select d.proposal_id, security.calendar_period_canonical_v1(d.period), d.kind, d.year, d.month, d.day, d.on_date, d.rolling_text, d.quote, d.applies_to, d.meaning, s.url, s.evidence_id,
         -- the year is printed in the quote, or in the heading the reader quoted for it (year_quote, on the page)
         d.year is not null and (d.quote ~ ('\m' || d.year || '\M') or coalesce(d.year_quote, '') ~ ('\m' || d.year || '\M'))
    from security.calendar_sources_v1(p_provider) s, lateral security.calendar_proposal_dates_v1(s.proposal_id) d
   where s.used
$$;


ALTER FUNCTION "security"."calendar_dated_periods_v2"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."calendar_dated_periods_v2"("p_provider" "uuid") IS 'CF-247 (decision 5 Nov 2026, defect D4): the dated periods of every main teaching calendar of a university (each document''s latest approved reading), with its document; replaces calendar_dated_periods_v1 (latest approved calendar only) in the intake date step.';



CREATE OR REPLACE FUNCTION "security"."calendar_default_intakes_apply_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security', 'search'
    AS $$
declare r record; v_ok int := 0; v_err int := 0; v_last text; v_courses uuid[] := '{}';
  v_names text[] := array['January','February','March','April','May','June','July','August','September','October','November','December'];
begin
  for r in
    with prov as (
      select distinct x.provider_id, security.calendar_default_months(x.provider_id) months, pv.canonical_name ~* '\muniversity\M' uni
        from pipeline.provider_policy_proposals x join catalogue.providers pv on pv.id = x.provider_id join ref.countries k on k.id = pv.country_id
       where x.kind = 'intake_calendar' and x.status = 'approved' and k.iso_alpha2 in (select jsonb_array_elements_text(s3.value) from pipeline.platform_toolset_settings s3 where s3.toolset_key = 'pipeline' and s3.key = 'calendar.countries')),
    cal as (
      select p.provider_id, p.months, p.uni, s.evidence_id, s.url, s.content_hash
        from prov p join lateral (select f.evidence_id, f.url, f.content_hash from pipeline.provider_fact_sources f
                                   where f.provider_id = p.provider_id and f.kind = 'intake_calendar' and f.evidence_id is not null and f.content_hash is not null
                                   order by (f.found_via = 'manual') desc, f.rank limit 1) s on true
       where cardinality(p.months) > 0)
    select c.id course_id, cal.provider_id, cal.months, cal.evidence_id, cal.url, cal.content_hash
      from cal join catalogue.courses c on c.provider_id = cal.provider_id
     where c.lifecycle_status = 'active'
       -- 19 Oct 2026 (Platform Admin "Undergraduate only"): a university's courses only at the study levels in calendar.university_levels
       and (not cal.uni or exists (select 1 from ref.study_levels sl where sl.id = c.study_level_id and sl.code in (select jsonb_array_elements_text(s2.value) from pipeline.platform_toolset_settings s2 where s2.toolset_key = 'pipeline' and s2.key = 'calendar.university_levels')))
       and exists (select 1 from catalogue.course_links l where l.course_id = c.id and l.link_type = 'official_course' and l.status = 'active')
       and not exists (select 1 from catalogue.course_intakes i where i.course_id = c.id)
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = c.id and k.field = 'intakes')
       and not exists (select 1 from pipeline.layer4_review_items l where l.entity_id = c.id and l.field_code = 'course_intake' and l.status = 'pending' and l.proposed_value is not null)
     limit 500
  loop
    begin
      perform security.coverage_apply_course_v1(r.course_id, security.coverage_sweep_source(r.provider_id), r.evidence_id, r.url, r.content_hash,
        jsonb_build_object('intakes', (select jsonb_agg(jsonb_build_object('intake_label', v_names[m], 'source_intake_key', 'calendar_default:' || r.course_id || ':' || lower(v_names[m]))) from unnest(r.months) m)));
      v_ok := v_ok + 1; v_courses := v_courses || r.course_id;
    exception when others then v_err := v_err + 1; v_last := left(sqlerrm, 200);
    end;
  end loop;
  if v_ok > 0 then
    insert into search.enrichment_source_gates(projection_code, domain_code, source_id, gate_status, approval_ref, approved_at, created_at, updated_at)
    select distinct 'courses', 'course_intake', security.coverage_sweep_source(c.provider_id), 'approved', 'CF-CHG-20260915-247; Decision 241 (college intakes from the approved calendar)', now(), now(), now()
      from catalogue.courses c where c.id = any(v_courses)
       and not exists (select 1 from search.enrichment_source_gates g where g.projection_code = 'courses' and g.domain_code = 'course_intake' and g.source_id = security.coverage_sweep_source(c.provider_id));
    perform search.refresh_course_enrichment_scoped_v1(v_courses, true);
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('calendar', 'default_intakes', 'Intakes from the approved calendar for college courses whose page names none', jsonb_build_object('courses', v_ok, 'refused', v_err, 'decision', 'Decision 241'), '63ba56cb-48d4-4169-98c2-7c4d1f72925b');
  end if;
  return jsonb_build_object('filled', v_ok, 'refused', v_err, 'last_error', v_last);
end $$;


ALTER FUNCTION "security"."calendar_default_intakes_apply_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."calendar_default_months"("p_provider_id" "uuid") RETURNS integer[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- when the Platform Admin set the months by hand, only those count (a parsed document approved as well adds nothing)
  with m as (
    select coalesce((select jsonb_object_agg(e->>'period', (e->'months'->>0)::int)
                       from (select x.proposal from pipeline.provider_policy_proposals x where x.provider_id = p_provider_id and x.kind = 'intake_calendar' and x.status = 'approved' and x.style = 'by_hand' order by x.decided_at desc nulls last limit 1) h,
                            jsonb_array_elements(coalesce(h.proposal->'periods', '[]'::jsonb)) e
                      where jsonb_typeof(e->'months') = 'array' and jsonb_array_length(e->'months') = 1),
                    security.calendar_period_months(p_provider_id)) cal),
  kinds as (select k.kind, k.ord from (values ('trimester', 1), ('semester', 2), ('term', 3), ('session', 4), ('study_period', 5), ('teaching_period', 6)) k(kind, ord)),
  first_kind as (select k.kind from kinds k, m where (m.cal ? (k.kind || ' 1')) order by k.ord limit 1),
  picked as (
    select (m.cal ->> (f.kind || ' 1'))::int m1, (m.cal ->> (f.kind || ' 2'))::int m2 from m, first_kind f)
  select case when p.m1 is null then '{}'::int[] when p.m2 is null or p.m2 = p.m1 then array[p.m1] else array[p.m1, p.m2] end from picked p
$$;


ALTER FUNCTION "security"."calendar_default_months"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."calendar_period_canonical_v1"("p_period" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  with w as (select regexp_replace(regexp_replace(lower(btrim(coalesce(p_period, ''))), '\s+', ' ', 'g'), '\m(one)\M', '1', 'g') a),
  x as (select regexp_replace(regexp_replace(a, '\m(two)\M', '2', 'g'), '\m(three)\M', '3', 'g') b from w)
  select case
    when b ~ '^(teaching period|study period|tp) ?t ?[1-6]$' then 'term ' || substring(b from '([1-6])$')
    when b ~ '^t[1-6]$' then 'term ' || substring(b from '([1-6])$')
    when b ~ '^(teaching period|study period) ?s ?[1-3]$' or b ~ '^s[1-3]$' or b ~ '^sem\.? ?[1-3]$' then 'semester ' || substring(b from '([1-3])$')
    when b ~ '^tri\.? ?[1-3]$' then 'trimester ' || substring(b from '([1-3])$')
    else b end
  from x
$_$;


ALTER FUNCTION "security"."calendar_period_canonical_v1"("p_period" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."calendar_period_canonical_v1"("p_period" "text") IS 'CF-247 (direction 5 Nov 2026 15:50 §2): one name for equivalent official period labels (Teaching period T1, T1, Term one -> term 1; Teaching period S1, Sem 1, Semester one -> semester 1; Tri 2 -> trimester 2); sub-periods such as T1A keep their own name.';



CREATE OR REPLACE FUNCTION "security"."calendar_period_months"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_object_agg(s.period, s.start_month), '{}'::jsonb) from (
    select distinct on (e->>'period') e->>'period' as period, (e->'months'->>0)::int as start_month
      from pipeline.provider_policy_proposals x, jsonb_array_elements(coalesce(x.proposal->'periods', '[]'::jsonb)) e
     where x.provider_id = p_provider_id and x.kind = 'intake_calendar' and x.status = 'approved'
       and jsonb_typeof(e->'months') = 'array' and jsonb_array_length(e->'months') = 1
     order by e->>'period', (x.style = 'by_hand') desc nulls last, x.decided_at desc nulls last) s
$$;


ALTER FUNCTION "security"."calendar_period_months"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."calendar_proposal_dates_v1"("p_proposal_id" "uuid") RETURNS TABLE("proposal_id" "uuid", "period" "text", "kind" "text", "year" integer, "month" integer, "day" integer, "on_date" "date", "rolling_text" "text", "quote" "text", "applies_to" "text", "meaning" "text", "year_quote" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  with cal as (select p.id, p.proposal from pipeline.provider_policy_proposals p where p.id = p_proposal_id),
  per as (select cal.id, lower(btrim(e->>'period')) period, e from cal, jsonb_array_elements(coalesce(cal.proposal->'periods', '[]'::jsonb)) e),
  given as (
    select per.id, per.period, k.kind, nullif(x->>'year', '')::int y, nullif(x->>'month', '')::int m, nullif(x->>'day', '')::int d, x->>'quote' q,
           x->>'applies_to' applies_to, x->>'meaning' meaning, x->>'year_quote' year_quote
      from per, lateral (values ('start', per.e->'starts'), ('deadline', per.e->'deadlines')) k(kind, arr), jsonb_array_elements(coalesce(k.arr, '[]'::jsonb)) x
     where jsonb_typeof(k.arr) = 'array'
       -- decision §1: only a teaching start is a commencement (never orientation, enrolment or a deadline)
       and (k.kind = 'deadline' or coalesce(x->>'meaning', 'teaching_start') = 'teaching_start')),
  quoted as (
    select per.id, per.period, 'start'::text kind, q, per.e->'years' yrs,
           regexp_match(q, '(?:\m(\d{1,2})(?:st|nd|rd|th)?\s+(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\M|\m(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\s+(\d{1,2})(?:st|nd|rd|th)?\M)(?:,?\s+(20\d\d))?', 'i') d,
           -- the text of the first date itself (the same alternatives, in the same order), to split the quote before and after it
           (regexp_match(q, '(\m\d{1,2}(?:st|nd|rd|th)?\s+(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\M|\m(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\s+\d{1,2}(?:st|nd|rd|th)?\M)', 'i'))[1] dtxt
      from per, jsonb_array_elements_text(coalesce(per.e->'quotes', '[]'::jsonb)) q
     where not (per.e ? 'starts')
       and q !~* '\m(exams?|examinations?|supplementary|census|results|holidays?|break|recess|graduation|enrolment|withdraw\w*|orientation)\M'),
  cut as (
    select z.*, left(z.q, position(z.dtxt in z.q) - 1) head, substr(z.q, position(z.dtxt in z.q) + length(z.dtxt)) tail
      from quoted z where z.d is not null and z.dtxt is not null),
  rng as (
    -- "<start> - <end> <year>": the end date of a simple range and the year printed after it (an optional weekday before the end date)
    select c.*, regexp_match(c.tail, '^\s*(?:-|–|—|to|until)\s*(?:(?:mon|tue|wed|thu|fri|sat|sun)[a-z]*\.?,?\s+)?(?:(\d{1,2})(?:st|nd|rd|th)?\s+(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)|(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\s+(\d{1,2})(?:st|nd|rd|th)?)\M,?\s+(20\d\d)\M(.*)$', 'is') rg
      from cut c),
  yr as (
    select r.*, nullif(r.d[5], '')::int y_after,
           nullif(substring(r.head from '.*\m(20\d\d)\M'), '')::int y_head,
           r.rg[5]::int y_end,
           -- a range that ends after the year-end starts in the year before the printed one; nothing else follows the end date (no second date, no other year)
           case when r.rg is not null and r.rg[6] !~* '\m20\d\d\M'
                     and r.rg[6] !~* '\m(jan(uary)?|feb(ruary)?|mar(ch)?|apr(il)?|may|jun(e)?|jul(y)?|aug(ust)?|sep(t(ember)?)?|oct(ober)?|nov(ember)?|dec(ember)?)\M'
                then case when array_position(array['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'], lower(left(coalesce(r.rg[2], r.rg[3]), 3)))
                              >= array_position(array['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'], lower(left(coalesce(r.d[2], r.d[3]), 3)))
                          then r.rg[5]::int else r.rg[5]::int - 1 end end y_range
      from rng r),
  pick as (select y.*, coalesce(y.y_after, y.y_head, y.y_range) y_raw from yr y),
  quoted_dates as (
    select p.id, p.period, p.kind,
           -- the reader's own years for the period must list it: a year the reader never found for this period is not taken
           case when p.y_raw is not null and (coalesce(jsonb_array_length(case when jsonb_typeof(p.yrs) = 'array' then p.yrs end), 0) = 0 or p.yrs @> to_jsonb(p.y_raw)) then p.y_raw end y,
           (array_position(array['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'], lower(left(coalesce(p.d[2], p.d[3]), 3))))::int m,
           -- a day range ("18 – 20 January 2027"): which day the period starts is not certain, so no day (the year still counts)
           case when p.q !~ '\m\d{1,2}(st|nd|rd|th)?\s*[–—-]\s*\d{1,2}(st|nd|rd|th)?\s+[A-Za-z]' then coalesce(p.d[1], p.d[4])::int end d, p.q,
           null::text applies_to, null::text meaning,
           case when p.y_after is null and p.y_head is null and p.y_range is not null then 'range ending ' || p.y_end || ': the start falls in ' || p.y_range end year_quote
      from pick p),
  quoted_kept as (
    select q.* from quoted_dates q join per on per.id = q.id and per.period = q.period where per.e->'months' @> to_jsonb(q.m)),
  dated as (select * from given union all select * from quoted_kept)
  select a.id, a.period, a.kind, a.y, a.m, a.d,
         case when a.y is not null and a.d between 1 and extract(day from (make_date(a.y, a.m, 1) + interval '1 month - 1 day'))::int  -- fixed: the last day of the month
              then make_date(a.y, a.m, a.d) end,
         null::text, left(a.q, 300), a.applies_to, a.meaning, left(a.year_quote, 300)
    from dated a where a.m between 1 and 12
  union all
  select per.id, per.period, 'rolling', null, null, null, null, left(r, 300), left(r, 300), null, null, null
    from per, jsonb_array_elements_text(coalesce(per.e->'deadline_rolling', '[]'::jsonb)) r
$_$;


ALTER FUNCTION "security"."calendar_proposal_dates_v1"("p_proposal_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."calendar_proposal_dates_v1"("p_proposal_id" "uuid") IS 'CF-247 (P0 IQ-00313, 8 Nov 2026): the dated starts and deadlines of one approved calendar reading. A quote read without a starts array takes the year printed straight after its date, else the last year printed before it, else (a simple range "<start> - <end> <year>") the year of the end less one when the range wraps the year-end; a year printed after several dates, or one the reader''s own years for the period do not list, is never taken for the first date. The basis of a range-derived year is kept in year_quote.';



CREATE OR REPLACE FUNCTION "security"."calendar_qualify_check_v1"("p_proposal_id" "uuid") RETURNS TABLE("proposal_id" "uuid", "provider_id" "uuid", "fact_source_id" "uuid", "qualifies" boolean, "reason" "text", "detail" "jsonb", "refreshable" boolean, "edition_year" integer, "evidence_id" "uuid", "content_hash" "text", "captured_at" timestamp with time zone, "source_url" "text", "quotes" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  with cfg as (
    select security.pipeline_num_v1('central.calendar_qualify_min_starts', 2)::int min_starts,
           security.pipeline_num_v1('central.calendar_qualify_max_series', 4)::int max_series,
           security.pipeline_num_v1('central.calendar_qualify_max_families', 3)::int max_fam,
           security.pipeline_num_v1('central.calendar_qualify_max_evidence_age_days', 120)::int max_age,
           security.pipeline_num_v1('intake_dates.max_months_ahead', 18)::int ahead,
           (now() at time zone 'Australia/Melbourne')::date today,  -- fixed: the Australian calendar day
           array(select lower(btrim(w)) from jsonb_array_elements_text(case when jsonb_typeof(security.toolset_setting('pipeline', 'central.calendar_qualify_blocked_words')) = 'array' then security.toolset_setting('pipeline', 'central.calendar_qualify_blocked_words') else '[]'::jsonb end) w where btrim(w) <> '') blocked,
           array(select lower(btrim(w)) from jsonb_array_elements_text(case when jsonb_typeof(security.toolset_setting('pipeline', 'central.calendar_qualify_required_words')) = 'array' then security.toolset_setting('pipeline', 'central.calendar_qualify_required_words') else '[]'::jsonb end) w where btrim(w) <> '') required,
           array(select lower(btrim(w)) from jsonb_array_elements_text(case when jsonb_typeof(security.toolset_setting('pipeline', 'central.calendar_qualify_blocked_period_words')) = 'array' then security.toolset_setting('pipeline', 'central.calendar_qualify_blocked_period_words') else '[]'::jsonb end) w where btrim(w) <> '') pblocked,
           -- 13 Nov 2026 (Platform Admin, Massey): event words a main teaching calendar may also name in its address or title (an exam period), and the
           -- teaching-start wording every start must be quoted with for such a page to be read as a teaching calendar; empty lists: no page is let through
           array(select lower(btrim(w)) from jsonb_array_elements_text(case when jsonb_typeof(security.toolset_setting('pipeline', 'central.calendar_qualify_shared_event_words')) = 'array' then security.toolset_setting('pipeline', 'central.calendar_qualify_shared_event_words') else '[]'::jsonb end) w where btrim(w) <> '') shared,
           array(select lower(btrim(w)) from jsonb_array_elements_text(case when jsonb_typeof(security.toolset_setting('pipeline', 'central.calendar_qualify_teaching_start_words')) = 'array' then security.toolset_setting('pipeline', 'central.calendar_qualify_teaching_start_words') else '[]'::jsonb end) w where btrim(w) <> '') tstart,
           array(select lower(btrim(w)) from jsonb_array_elements_text(case when jsonb_typeof(security.toolset_setting('pipeline', 'binding.provider_host_aliases')) = 'array' then security.toolset_setting('pipeline', 'binding.provider_host_aliases') else '[]'::jsonb end) w where btrim(w) <> '') aliases),
  p as (
    select x.id pid, x.provider_id, x.fact_source_id, x.parser, x.url, x.status, x.proposal, x.content_hash,
           coalesce(x.evidence_id, f.evidence_id) evid, f.title ftitle, pr.stable_key, pr.website,
           regexp_replace(lower(coalesce(substring(x.url from '^https?://([^/?#:]+)'), '')), '^www\.', '') host,
           lower(x.url || ' ' || coalesce(f.title, '')) hay
      from pipeline.provider_policy_proposals x
      join pipeline.provider_fact_sources f on f.id = x.fact_source_id
      join catalogue.providers pr on pr.id = x.provider_id
     where x.id = p_proposal_id and x.kind = 'intake_calendar'),
  ev as (select e.id, e.captured_at, e.content_hash from pipeline.evidence_artifacts e join p on e.id = p.evid),
  own as (
    select array(select distinct z.h from (
             select regexp_replace(lower(coalesce(substring(p.website from '^https?://([^/?#:]+)'), '')), '^www\.', '') h
             union all select regexp_replace(lower(btrim(w)), '^www\.', '')
                         from unnest(cfg.aliases) e, lateral regexp_split_to_table(substr(e, strpos(e, '=') + 1), '\s+') w
                        where split_part(e, '=', 1) = lower(p.stable_key)
             union all select regexp_replace(lower(d.domain), '^(https?://)?(www\.)?', '') from pipeline.provider_extra_domains d where d.provider_id = p.provider_id and d.state = 'approved') z
            where z.h <> '') hosts
      from p, cfg),
  d as materialized (
    select x.period, x.on_date, x.year, x.quote, x.year_quote, k.pkey,
           x.year is not null and (x.quote ~ ('\m' || x.year || '\M') or coalesce(x.year_quote, '') ~ ('\m' || x.year || '\M')) year_ok
      from p, security.calendar_proposal_dates_v1(p.pid) x,
           lateral (select btrim(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(lower(coalesce(x.period, '')), '\(.*$', ''), '[_*]+', ' ', 'g'), '^\s*(19|20)\d\d\s*[-–—:]?\s*', ''), '\s+(19|20)\d\d\s*$', ''), '\s+', ' ', 'g')) pkey) k
     where x.kind = 'start' and x.on_date is not null),
  win as (select d.*, regexp_replace(d.pkey, '\s*\d+$', '') fam from d, cfg where d.year_ok and d.on_date >= cfg.today and d.on_date < cfg.today + make_interval(months => cfg.ahead)),
  a as (
    select security.calendar_period_canonical_v1(k.pkey) pk, x.year, x.on_date
      from p, cfg, security.calendar_dated_periods_v2(p.provider_id) x,
           lateral (select btrim(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(lower(coalesce(x.period, '')), '\(.*$', ''), '[_*]+', ' ', 'g'), '^\s*(19|20)\d\d\s*[-–—:]?\s*', ''), '\s+(19|20)\d\d\s*$', ''), '\s+', ' ', 'g')) pkey) k
     where x.kind = 'start' and x.on_date is not null and x.year_ok
       -- an approved calendar of a structurally wrong page (for example a college that is another provider) is not a calendar to be contradicted
       and not exists (select 1 from unnest(cfg.blocked) w where position(w in lower(x.url)) > 0 and not (w = any (cfg.shared)))),
  h as (
    select security.calendar_period_canonical_v1(lower(btrim(e->>'period'))) pk,
           array(select m::int from jsonb_array_elements_text(case when jsonb_typeof(e->'months') = 'array' then e->'months' else '[]'::jsonb end) m) months
      from p, pipeline.provider_policy_proposals x, jsonb_array_elements(case when jsonb_typeof(x.proposal->'periods') = 'array' then x.proposal->'periods' else '[]'::jsonb end) e
     where x.provider_id = p.provider_id and x.kind = 'intake_calendar' and x.status = 'approved' and x.style = 'by_hand'),
  wd as (select e.before_value->>'start_date' s from pipeline.course_intake_date_events e, p where e.provider_id = p.provider_id and e.outcome = 'withdrawn' and e.before_value->>'start_date' is not null),
  fam as (select w.fam, extract(year from w.on_date)::int y, count(distinct w.on_date) n from win w group by 1, 2),
  yr as (select y, count(distinct fam) n from fam group by y),
  f as (
    select p.pid, p.provider_id, p.fact_source_id, p.status, p.url, p.host, p.hay, cfg.*, own.hosts,
           (select z.id from pipeline.provider_policy_proposals z
             where z.provider_id = p.provider_id and z.kind = 'intake_calendar' and z.status = 'rejected' and z.id <> p.pid
               and (z.decided_by is not null or z.decision_note ilike 'platform admin%' or z.decision_note ilike 'withdrawn:%')
               and (z.fact_source_id = p.fact_source_id or regexp_replace(lower(z.url), '^https?://(www\.)?|/+$', '', 'g') = regexp_replace(lower(p.url), '^https?://(www\.)?|/+$', '', 'g'))
             order by z.decided_at desc nulls last limit 1) rej_id,
           exists (select 1 from pipeline.manual_locks l where l.entity = 'provider' and l.entity_id = p.provider_id and l.field in ('intakes', 'intake_calendar', 'calendar')) locked,
           exists (select 1 from unnest(own.hosts) o where p.host = o or p.host like '%.' || o) host_ok,
           security.calendar_scope_v1(p.proposal, p.url, p.parser) scope,
           (select w from unnest(cfg.blocked) w where position(w in p.hay) > 0
              -- 13 Nov 2026 (Platform Admin, Massey): a calendar that also lists exam dates is not refused for naming them when every start it gives
              -- in the window is quoted as a teaching start; application, add/drop, refund, orientation and exam dates are never starts
              and not (w = any (cfg.shared) and exists (select 1 from win)
                       and not exists (select 1 from win w2 where not exists (select 1 from unnest(cfg.tstart) t where position(t in lower(coalesce(w2.quote, ''))) > 0)))
            order by w limit 1) bword,
           exists (select 1 from unnest(cfg.required) w where position(w in p.hay) > 0) required_ok,
           (select w from unnest(cfg.pblocked) w, d where position(w in d.pkey) > 0 order by w limit 1) pword,
           (select count(*) from d) n_all,
           (select count(*) from d where d.year_ok) n_proved,
           (select count(*) from d where d.year_ok and d.on_date >= cfg.today) n_future,
           (select count(distinct w.on_date) from win w) n_win,
           (select min(d.on_date) from d where d.on_date::text in (select s from wd)
               or exists (select 1 from pipeline.intake_date_rejections r where r.provider_id = p.provider_id and (r.start_date = d.on_date or (r.quote is not null and r.quote = d.quote and r.year is not distinct from d.year)))) bad_date,
           coalesce((select max(n) from fam), 0) max_seen_series,
           coalesce((select max(n) from yr), 0) max_seen_fam,
           (select w.pkey || ' ' || w.year from win w join a on a.pk = security.calendar_period_canonical_v1(w.pkey) and a.year = w.year
             where not exists (select 1 from a a2 where a2.pk = a.pk and a2.year = a.year and a2.on_date = w.on_date) order by w.on_date limit 1) contradiction,
           (select w.pkey || ' ' || w.year from win w join h on h.pk = security.calendar_period_canonical_v1(w.pkey)
             where not (extract(month from w.on_date)::int = any (h.months)) order by w.on_date limit 1) hand_contradiction,
           exists (select 1 from win w where not exists (select 1 from a where a.pk = security.calendar_period_canonical_v1(w.pkey) and a.year = w.year)) has_new_value,
           (select e.id from ev e) ev_id, (select e.captured_at from ev e) ev_at, (select e.content_hash from ev e) ev_hash,
           (select max(w.year) from win w) edition_year
      from p, cfg, own),
  r as (
    select f.*,
      case
        when f.status is distinct from 'proposed' then 'not_a_proposed_calendar'
        when coalesce(cardinality(f.blocked), 0) = 0 or coalesce(cardinality(f.required), 0) = 0 or coalesce(cardinality(f.pblocked), 0) = 0 then 'qualifier_settings_missing'
        when f.rej_id is not null then 'platform_admin_rejected_address'
        when f.locked then 'provider_locked_by_hand'
        when not f.host_ok then 'host_not_provider_website'
        when f.scope <> 'main_teaching' then 'excluded_by_calendar_scope'
        when f.bword is not null then 'blocked_word'
        when not f.required_ok then 'not_a_calendar_page'
        when f.pword is not null then 'non_main_period'
        when f.ev_id is null then 'no_evidence'
        when f.n_all = 0 then 'no_dated_starts'
        when f.n_proved = 0 then 'year_not_proved'
        when f.n_win < f.min_starts and f.n_future = 0 then 'edition_not_current'
        when f.n_win < f.min_starts and f.n_win = 0 then 'starts_beyond_window'
        when f.n_win < f.min_starts then 'too_few_starts'
        when f.ev_at < now() - make_interval(days => f.max_age) then 'evidence_stale'
        when f.bad_date is not null then 'rejected_or_withdrawn_value'
        when f.max_seen_series > f.max_series then 'scope_check_series'
        when f.max_seen_fam > f.max_fam then 'scope_check_families'
        when f.hand_contradiction is not null then 'contradicts_hand_set_calendar'
        when f.contradiction is not null then 'contradicts_approved_calendar'
        when not f.has_new_value then 'adds_no_new_value'
        else 'qualifies' end code
      from f)
  select r.pid, r.provider_id, r.fact_source_id, r.code = 'qualifies', r.code,
         jsonb_strip_nulls(jsonb_build_object('host', r.host, 'own_hosts', to_jsonb(r.hosts), 'scope', r.scope, 'word', r.bword, 'period_word', r.pword,
           'starts_in_window', r.n_win, 'starts_proved', r.n_proved, 'starts_all', r.n_all, 'min_starts', r.min_starts, 'months_ahead', r.ahead,
           'max_series_seen', r.max_seen_series, 'max_families_seen', r.max_seen_fam, 'rejected_by', r.rej_id, 'rejected_value', r.bad_date,
           'contradiction', coalesce(r.hand_contradiction, r.contradiction), 'evidence_captured_at', r.ev_at)),
         r.code in ('edition_not_current', 'evidence_stale'),
         r.edition_year, r.ev_id, coalesce(r.ev_hash, (select p.content_hash from p)), r.ev_at, r.url,
         (select jsonb_agg(jsonb_build_object('period', z.pkey, 'date', z.on_date, 'quote', left(z.quote, 200)) order by z.on_date)
            from (select distinct on (w.on_date, w.pkey) w.pkey, w.on_date, w.quote from win w order by w.on_date, w.pkey limit 12) z)  -- fixed: the first twelve starts are kept as the audit quote
    from r
$_$;


ALTER FUNCTION "security"."calendar_qualify_check_v1"("p_proposal_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."calendar_qualify_check_v1"("p_proposal_id" "uuid") IS 'CF-247 F-INT.01/SRC-01 (9 Nov 2026): the verdict of one proposed intake_calendar reading for approval by rule (writes nothing): qualifies, or the first failing reason (not_a_proposed_calendar, qualifier_settings_missing, platform_admin_rejected_address, provider_locked_by_hand, host_not_provider_website, excluded_by_calendar_scope, blocked_word, not_a_calendar_page, non_main_period, no_evidence, no_dated_starts, year_not_proved, edition_not_current, starts_beyond_window, too_few_starts, evidence_stale, rejected_or_withdrawn_value, scope_check_series, scope_check_families, contradicts_hand_set_calendar, contradicts_approved_calendar, adds_no_new_value). refreshable is true for edition_not_current and evidence_stale only (every structural check before them passed). Reads the dates only through security.calendar_proposal_dates_v1 and security.calendar_dated_periods_v2.';



CREATE OR REPLACE FUNCTION "security"."calendar_qualify_dry_run_v1"() RETURNS TABLE("proposal_id" "uuid", "provider_id" "uuid", "provider" "text", "url" "text", "parser" "text", "qualifies" boolean, "reason" "text", "detail" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select x.id, x.provider_id, pr.display_name, x.url, x.parser, c.qualifies, c.reason, c.detail
    from pipeline.provider_policy_proposals x join catalogue.providers pr on pr.id = x.provider_id, lateral security.calendar_qualify_check_v1(x.id) c
   where x.kind = 'intake_calendar' and x.status = 'proposed'
   order by pr.display_name, x.url
$$;


ALTER FUNCTION "security"."calendar_qualify_dry_run_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."calendar_qualify_dry_run_v1"() IS 'CF-247 F-INT.01/SRC-01 (9 Nov 2026): read-only dry run of the calendar qualification route over every proposed intake_calendar reading: provider, address, whether it would qualify and the exact reason otherwise. Writes nothing; works with the switch off.';



CREATE OR REPLACE FUNCTION "security"."calendar_qualify_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_batch int := security.pipeline_num_v1('batch.calendar_qualify', 25)::int;
  v_refresh int := security.pipeline_num_v1('batch.calendar_qualify_refresh', 1)::int;
  v_days int := security.pipeline_num_v1('intake_dates.revisit_days', 14)::int;
  v_fp text; r record; c record; v_set text; v_before jsonb; v_after jsonb; v_sup int; v_note text;
  v_exam int := 0; v_ok int := 0; v_held int := 0; v_asked int := 0; v_by jsonb := '{}'::jsonb; t0 timestamptz := clock_timestamp();
  v_rule constant text := 'calendar-qualify-v1';  -- fixed: the name of the rule recorded with every decision
begin
  if security.pipeline_num_v1('central.calendar_qualify_main_teaching', 0) <> 1 then return jsonb_build_object('off', true); end if;
  if not pg_try_advisory_xact_lock(hashtext('cf247.calendar_qualify')) then return jsonb_build_object('skipped', 'another run is in progress'); end if;
  v_fp := md5(coalesce((select string_agg(s.key || '=' || (s.value)::text, ';' order by s.key) from pipeline.platform_toolset_settings s
                         where s.toolset_key = 'pipeline' and (s.key like 'central.calendar_qualify%' or s.key in ('central.calendar_excluded_words', 'intake_dates.max_months_ahead', 'binding.provider_host_aliases'))), '') || v_rule);
  begin
    for r in
      select x.id
        from pipeline.provider_policy_proposals x
        left join pipeline.calendar_qualify_decisions q on q.proposal_id = x.id
       where x.kind = 'intake_calendar' and x.status = 'proposed'
         and (q.proposal_id is null or q.settings_fp <> v_fp or q.next_check_at <= now()
              -- the approved or rejected readings of the provider, its rejected values or its withdrawn values changed since the verdict (index lookups, no scan)
              or exists (select 1 from pipeline.provider_policy_proposals z where z.provider_id = x.provider_id and z.kind = 'intake_calendar' and z.status in ('approved', 'rejected') and z.decided_at > q.decided_at)
              or exists (select 1 from pipeline.intake_date_rejections j where j.provider_id = x.provider_id and j.rejected_at > q.decided_at)
              or exists (select 1 from pipeline.course_intake_date_events e where e.provider_id = x.provider_id and e.outcome = 'withdrawn' and e.run_at > q.decided_at))
       order by (q.proposal_id is not null), q.decided_at nulls first, x.created_at, x.id
       limit v_batch
    loop
      v_exam := v_exam + 1;
      select * into c from security.calendar_qualify_check_v1(r.id);
      if c.proposal_id is null then continue; end if;
      v_set := security.calendar_set_v1(c.provider_id);
      v_by := jsonb_set(v_by, array[c.reason], to_jsonb(coalesce((v_by->>c.reason)::int, 0) + 1));
      if c.qualifies then
        select jsonb_build_object('status', x.status, 'decided_by', x.decided_by, 'decided_at', x.decided_at, 'decision_note', x.decision_note) into v_before
          from pipeline.provider_policy_proposals x where x.id = c.proposal_id;
        v_note := left(format('Machine decision (rule %s, not a person): official main teaching calendar of the provider''s own website, edition %s, %s teaching starts with the year quoted, no contradiction with an approved calendar, no rejected or withdrawn value (%s)',
                              v_rule, c.edition_year, jsonb_array_length(coalesce(c.quotes, '[]'::jsonb)), c.source_url), 500);
        update pipeline.provider_policy_proposals set status = 'approved', decided_by = null, decided_at = now(), decision_note = v_note, updated_at = now()
         where id = c.proposal_id and status = 'proposed';
        select jsonb_build_object('status', x.status, 'decided_by', x.decided_by, 'decided_at', x.decided_at, 'decision_note', x.decision_note) into v_after
          from pipeline.provider_policy_proposals x where x.id = c.proposal_id;
        -- another reading of the same document is closed, as the checked-AI approval does; another document is never closed
        update pipeline.provider_policy_proposals
           set status = 'superseded', decided_at = now(), updated_at = now(), decision_note = 'Closed: another reading of this document was approved by rule (' || c.source_url || ')'
         where provider_id = c.provider_id and kind = 'intake_calendar' and status = 'proposed' and id <> c.proposal_id and fact_source_id = c.fact_source_id;
        get diagnostics v_sup = row_count;
        insert into pipeline.calendar_qualify_decisions as q(proposal_id, provider_id, fact_source_id, rule, verdict, reason, detail, actor, decided_at, settings_fp, cal_set, next_check_at,
                 evidence_id, content_hash, captured_at, edition_year, source_url, quotes, before_state, after_state, approved_at)
        values (c.proposal_id, c.provider_id, c.fact_source_id, v_rule, 'approved', c.reason, c.detail || jsonb_build_object('superseded_readings', v_sup), 'system:' || v_rule, now(), v_fp, v_set, null,
                c.evidence_id, c.content_hash, c.captured_at, c.edition_year, c.source_url, c.quotes, v_before, v_after, now())
        on conflict (proposal_id) do update set rule = excluded.rule, verdict = excluded.verdict, reason = excluded.reason, detail = excluded.detail, actor = excluded.actor,
                 decided_at = excluded.decided_at, settings_fp = excluded.settings_fp, cal_set = excluded.cal_set, next_check_at = null, evidence_id = excluded.evidence_id,
                 content_hash = excluded.content_hash, captured_at = excluded.captured_at, edition_year = excluded.edition_year, source_url = excluded.source_url,
                 quotes = excluded.quotes, before_state = excluded.before_state, after_state = excluded.after_state, approved_at = excluded.approved_at,
                 withdrawn_at = null, withdrawn_by = null, withdrawn_reason = null;
        insert into pipeline.admin_control_events(area, action, target, detail, actor)
        values ('policies', 'approve_machine', 'intake_calendar: ' || c.source_url,
                jsonb_build_object('decision', 'F-INT.01/SRC-01 9 Nov 2026: calendar qualification by rule (setting central.calendar_qualify_main_teaching)', 'rule', v_rule, 'actor_kind', 'system',
                                   'actor', 'system:' || v_rule, 'proposal_id', c.proposal_id, 'provider_id', c.provider_id, 'edition_year', c.edition_year, 'content_hash', c.content_hash,
                                   'captured_at', c.captured_at, 'before', v_before, 'after', v_after, 'quotes', c.quotes), null);
        v_ok := v_ok + 1;
      else
        insert into pipeline.calendar_qualify_decisions as q(proposal_id, provider_id, fact_source_id, rule, verdict, reason, detail, actor, decided_at, settings_fp, cal_set, next_check_at,
                 evidence_id, content_hash, captured_at, edition_year, source_url, quotes)
        values (c.proposal_id, c.provider_id, c.fact_source_id, v_rule, 'held', c.reason, c.detail, 'system:' || v_rule, now(), v_fp, v_set, now() + make_interval(days => v_days),
                c.evidence_id, c.content_hash, c.captured_at, c.edition_year, c.source_url, c.quotes)
        on conflict (proposal_id) do update set rule = excluded.rule, verdict = excluded.verdict, reason = excluded.reason, detail = excluded.detail, actor = excluded.actor,
                 decided_at = excluded.decided_at, settings_fp = excluded.settings_fp, cal_set = excluded.cal_set, next_check_at = excluded.next_check_at, evidence_id = excluded.evidence_id,
                 content_hash = excluded.content_hash, captured_at = excluded.captured_at, edition_year = excluded.edition_year, source_url = excluded.source_url, quotes = excluded.quotes
          where q.verdict <> 'withdrawn';
        v_held := v_held + 1;
      end if;
    end loop;
    -- bounded refresh of a stale edition through the existing acquisition ladder (same eligibility, budget and once-per-address rule as public.svc_calendar_refresh_v1)
    if v_refresh > 0 and not exists (select 1 from pipeline.calendar_refresh_requests q where q.status = 'requested') then
      declare v_budget numeric := security.pipeline_num_v1('central.calendar_refresh_credit_budget', 40);
              v_each numeric := security.pipeline_num_v1('central.calendar_refresh_credits_per_read', 5);
              v_age int := security.pipeline_num_v1('central.calendar_refresh_min_age_days', 7)::int;
              v_spent numeric; v_res numeric; z record;
      begin
        select coalesce(sum(greatest(q.credit_estimate, coalesce(q.credits_used, 0))), 0) into v_spent from pipeline.calendar_refresh_requests q;
        for z in
          select f.id, f.provider_id, f.url, f.evidence_id, f.content_hash, f.read_at, q.reason
            from pipeline.calendar_qualify_decisions q
            join pipeline.provider_fact_sources f on f.id = q.fact_source_id
           where q.verdict = 'held' and q.reason in ('edition_not_current', 'evidence_stale')
             and f.kind = 'intake_calendar' and f.evidence_id is not null and f.status not in ('found', 'reading') and f.decided_by is null and f.decision is null
             and not exists (select 1 from pipeline.provider_policy_proposals p where p.fact_source_id = f.id and p.status = 'approved'
                               and (p.decided_by is not null or p.parser = 'set by hand' or coalesce(p.proposal->>'scope', '') not in ('', 'main_teaching')))
             and security.calendar_scope_v1('{}'::jsonb, f.url, null) = 'main_teaching'
             and coalesce(f.read_at, f.updated_at) < now() - make_interval(days => v_age)
             and not exists (select 1 from pipeline.calendar_refresh_requests rq where rq.url = f.url)
           order by q.decided_at, f.id
           limit v_refresh
        loop
          v_res := greatest(v_each, coalesce((select max(c2.credits_used) from pipeline.firecrawl_calls c2 where c2.url = z.url), 0));
          exit when v_spent + v_res > v_budget;
          insert into pipeline.calendar_refresh_requests(fact_source_id, provider_id, url, reader_version, reason, old_evidence_id, old_content_hash, old_read_at, credit_estimate)
          values (z.id, z.provider_id, z.url, (select max(s.reader) from pipeline.calendar_reread_state s where s.fact_source_id = z.id),
                  format('qualification route: %s (the qualified edition is past or its stored copy is older than the limit)', z.reason), z.evidence_id, z.content_hash, z.read_at, v_res)
          on conflict do nothing;
          update pipeline.provider_fact_sources set status = 'found', attempts = 0, updated_at = now() where id = z.id;
          v_spent := v_spent + v_res; v_asked := v_asked + 1;
        end loop;
      end;
    end if;
  exception when others then
    insert into pipeline.calendar_qualify_runs(examined, approved, held, by_reason, refresh_asked, ms, error)
    values (v_exam, v_ok, v_held, v_by, v_asked, (extract(epoch from clock_timestamp() - t0) * 1000)::int, left(sqlerrm, 500));  -- fixed: milliseconds in a second
    return jsonb_build_object('error', left(sqlerrm, 200));
  end;
  if v_exam > 0 or v_asked > 0 then
    insert into pipeline.calendar_qualify_runs(examined, approved, held, by_reason, refresh_asked, ms)
    values (v_exam, v_ok, v_held, v_by, v_asked, (extract(epoch from clock_timestamp() - t0) * 1000)::int);  -- fixed: milliseconds in a second
  end if;
  return jsonb_build_object('examined', v_exam, 'approved', v_ok, 'held', v_held, 'by_reason', v_by, 'refresh_asked', v_asked);
end $$;


ALTER FUNCTION "security"."calendar_qualify_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."calendar_qualify_v1"() IS 'CF-247 F-INT.01/SRC-01 (9 Nov 2026): the calendar qualification route. Off (central.calendar_qualify_main_teaching = 0, the default): returns at once, writes nothing. On: checks up to batch.calendar_qualify proposed intake_calendar readings (never checked, changed inputs or due), approves the qualifying ones as a machine decision (decided_by null, actor system:calendar-qualify-v1) with evidence and before/after, holds the others with the exact reason, and hands a stale edition to the existing refresh within its credit budget. Called by security.policy_auto_approve_v1 (job policy-auto-approve). A failure is recorded in pipeline.calendar_qualify_runs and never stops the other approvals.';



CREATE OR REPLACE FUNCTION "security"."calendar_qualify_withdraw_v1"("p_proposal" "uuid", "p_reason" "text", "p_actor" "uuid", "p_withdraw_values" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare q pipeline.calendar_qualify_decisions%rowtype; x pipeline.provider_policy_proposals%rowtype; v_batch int := security.pipeline_num_v1('batch.calendar_qualify_withdraw', 50)::int;
        v_ids uuid[]; v_total int; i uuid; v_res jsonb := '[]'::jsonb; v_done int := 0; v_before jsonb;
begin
  if coalesce(btrim(p_reason), '') = '' or length(btrim(p_reason)) < 8 then raise exception 'give the reason for the withdrawal' using errcode = '22023'; end if;  -- fixed: a reason of a few words
  select * into q from pipeline.calendar_qualify_decisions where proposal_id = p_proposal for update;
  if q.proposal_id is null or q.verdict not in ('approved', 'withdrawn') then raise exception 'this reading was not approved by the qualification route' using errcode = '22023'; end if;
  select * into x from pipeline.provider_policy_proposals where id = p_proposal for update;
  if q.verdict = 'approved' then
    v_before := jsonb_build_object('status', x.status, 'decided_by', x.decided_by, 'decision_note', x.decision_note);
    -- rejected by a person: the rejection memory keeps the route from approving this address again; the calendar set changes, so the rows are looked at again
    update pipeline.provider_policy_proposals set status = 'rejected', decided_by = p_actor, decided_at = now(), decision_note = left('Withdrawn: ' || btrim(p_reason), 500), updated_at = now() where id = p_proposal;
    update pipeline.calendar_qualify_decisions set verdict = 'withdrawn', withdrawn_at = now(), withdrawn_by = p_actor, withdrawn_reason = left(btrim(p_reason), 500), next_check_at = null where proposal_id = p_proposal;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('policies', 'withdraw_machine_approval', 'intake_calendar: ' || x.url,
            jsonb_build_object('rule', q.rule, 'proposal_id', p_proposal, 'provider_id', x.provider_id, 'reason', left(btrim(p_reason), 500), 'before', v_before, 'content_hash', q.content_hash), p_actor);
  end if;
  select array_agg(d.intake_id order by d.intake_id), count(*) into v_ids, v_total from pipeline.course_intake_dates d
   where d.proposal_id = p_proposal and d.outcome = 'filled';
  if p_withdraw_values and coalesce(v_total, 0) > 0 then
    foreach i in array v_ids loop
      exit when v_done >= v_batch;
      v_res := v_res || security.intake_date_withdraw_v1(i, 'Calendar withdrawn: ' || btrim(p_reason), p_actor::text, false);
      v_done := v_done + 1;
    end loop;
    insert into pipeline.manual_locks(entity, entity_id, field, mode, set_by, set_at)
    select distinct 'course', (e->>'course_id')::uuid, 'intakes', 'value', p_actor, now() from jsonb_array_elements(v_res) e where (e->>'withdrawn')::boolean
    on conflict (entity, entity_id, field) do nothing;
  end if;
  return jsonb_build_object('proposal_id', p_proposal, 'withdrawn', true, 'values_admitted', coalesce(v_total, 0), 'values_withdrawn_now', (select count(*) from jsonb_array_elements(v_res) e where (e->>'withdrawn')::boolean),
                            'values_remaining', greatest(coalesce(v_total, 0) - v_done, 0));
end $$;


ALTER FUNCTION "security"."calendar_qualify_withdraw_v1"("p_proposal" "uuid", "p_reason" "text", "p_actor" "uuid", "p_withdraw_values" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."calendar_qualify_withdraw_v1"("p_proposal" "uuid", "p_reason" "text", "p_actor" "uuid", "p_withdraw_values" boolean) IS 'CF-247 F-INT.01/SRC-01 (9 Nov 2026): withdraws a calendar the qualification route approved: the reading becomes rejected by the named person (the route never approves that address again), the decision row records who, when and why, the calendar leaves the calendar set, and the intake values it admitted are withdrawn through the existing security.intake_date_withdraw_v1 (at most batch.calendar_qualify_withdraw a call; the call reports the rest and is repeated; each course is held by a lock, as the governed withdrawal does).';



CREATE OR REPLACE FUNCTION "security"."calendar_reader_findings_record_v1"("p_fact_source" "uuid", "p_provider" "uuid", "p_parsed" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int := 0;
begin
  if p_parsed is null or coalesce(p_parsed->>'parser', '') not like '%calendar-v2%' then return 0; end if;
  insert into pipeline.calendar_reader_findings as t(provider_id, fact_source_id, code, detail, example)
  select p_provider, p_fact_source, x->>'code', coalesce(x->>'detail', ''), left(x->>'example', 400)
    from jsonb_array_elements(coalesce(p_parsed->'findings', '[]'::jsonb)) x where coalesce(x->>'code', '') <> ''
  on conflict (provider_id, fact_source_id, code, detail) do update set times = t.times + 1, last_seen = now(), example = excluded.example, resolved_at = null;
  get diagnostics v_n = row_count;
  update pipeline.calendar_reader_findings f set resolved_at = now()
   where f.fact_source_id = p_fact_source and f.resolved_at is null
     and not exists (select 1 from jsonb_array_elements(coalesce(p_parsed->'findings', '[]'::jsonb)) x where x->>'code' = f.code and coalesce(x->>'detail', '') = f.detail);
  update pipeline.calendar_reread_state set state = 'read_by_ai', reason = coalesce(p_parsed->>'scope', 'read'), last_at = now() where fact_source_id = p_fact_source;
  return v_n;
end $$;


ALTER FUNCTION "security"."calendar_reader_findings_record_v1"("p_fact_source" "uuid", "p_provider" "uuid", "p_parsed" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."calendar_reader_findings_record_v1"("p_fact_source" "uuid", "p_provider" "uuid", "p_parsed" "jsonb") IS 'CF-247 (decision 5 Nov 2026 §7): records the findings of a calendar-v2 read (opened, repeated or resolved) and marks the document read by the AI.';



CREATE OR REPLACE FUNCTION "security"."calendar_reader_notes_v1"("p_provider" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select nullif(string_agg('- ' || f.code || ': ' || coalesce(f.detail, '') || coalesce(' (example: ' || left(f.example, 160) || ')', ''), E'\n' order by f.last_seen desc), '')
    from (select * from pipeline.calendar_reader_findings f where f.provider_id = p_provider and f.resolved_at is null
           order by f.last_seen desc limit security.pipeline_num_v1('reading.calendar_notes_max', 5)::int) f
$$;


ALTER FUNCTION "security"."calendar_reader_notes_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."calendar_reader_notes_v1"("p_provider" "uuid") IS 'CF-247 (decision 5 Nov 2026 §7): the newest open calendar reader findings of a university, given to the next AI read of its calendars as notes.';



CREATE OR REPLACE FUNCTION "security"."calendar_reread_relevant_v1"() RETURNS TABLE("provider_id" "uuid", "missing" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select c.provider_id, count(*)::int
    from catalogue.course_intakes i join catalogue.courses c on c.id = i.course_id
   where i.status = 'active' and c.lifecycle_status = 'active' and (i.start_date is null or i.intake_year is null)
     and c.provider_id in (select (e->>'id')::uuid from jsonb_array_elements(security.intake_ui_scopes_v1()) e)
   group by c.provider_id
$$;


ALTER FUNCTION "security"."calendar_reread_relevant_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."calendar_reread_relevant_v1"() IS 'CF-247 (mandate 5 Nov 2026 §8): the universities of the intake scope (top Australian universities) whose intake rows still miss a year or start date, with how many; the calendar re-read and refresh read only their calendars.';



CREATE OR REPLACE FUNCTION "security"."calendar_reread_relevant_v2"() RETURNS TABLE("provider_id" "uuid", "missing" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select c.provider_id, count(*)::int
    from catalogue.course_intakes i join catalogue.courses c on c.id = i.course_id
    join catalogue.providers pv on pv.id = c.provider_id join ref.countries k on k.id = pv.country_id
   where i.status = 'active' and c.lifecycle_status = 'active' and (i.start_date is null or i.intake_year is null)
     and k.iso_alpha2 in (select jsonb_array_elements_text(case when jsonb_typeof(security.toolset_setting('pipeline', 'calendar.countries')) = 'array'
                                                                 then security.toolset_setting('pipeline', 'calendar.countries') else '[]'::jsonb end))
   group by c.provider_id
$$;


ALTER FUNCTION "security"."calendar_reread_relevant_v2"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."calendar_reread_relevant_v2"() IS 'CF-247 F-INT (Platform Admin 10 Nov 2026; Decisions 273, 274): every provider in calendar.countries whose active intake rows still miss a year or start date, with how many. The calendar re-read of stored copies reads their calendars (no Firecrawl). security.calendar_reread_relevant_v1 (the 5 Nov pilot scope) still bounds the Firecrawl refresh until Decision 273''s safeguards.';



CREATE OR REPLACE FUNCTION "security"."calendar_scope_v1"("p_proposal" "jsonb", "p_url" "text", "p_parser" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when p_parser = 'set by hand' then 'main_teaching'
    when coalesce(p_proposal->>'scope', '') not in ('', 'main_teaching') then p_proposal->>'scope'
    when exists (select 1 from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'central.calendar_excluded_words'), '[]'::jsonb)) w
                  where lower(coalesce(p_url, '')) like '%' || lower(w) || '%') then 'excluded_by_address'
    else 'main_teaching' end
$$;


ALTER FUNCTION "security"."calendar_scope_v1"("p_proposal" "jsonb", "p_url" "text", "p_parser" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."calendar_scope_v1"("p_proposal" "jsonb", "p_url" "text", "p_parser" "text") IS 'CF-247 (decision 5 Nov 2026 §2): the scope of an approved calendar reading: set by hand = main teaching; the reader''s scope when it gave one; excluded_by_address when the address has a word of central.calendar_excluded_words; else main teaching.';



CREATE OR REPLACE FUNCTION "security"."calendar_set_by_hand"("p_provider_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from pipeline.provider_policy_proposals x where x.provider_id = p_provider_id and x.kind = 'intake_calendar' and x.status = 'approved' and x.style = 'by_hand')
$$;


ALTER FUNCTION "security"."calendar_set_by_hand"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."calendar_set_v1"("p_provider" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when count(*) filter (where s.used) = 0 then 'none:' || count(*)
              else md5(string_agg(s.proposal_id::text || ':' || s.parser, ',' order by s.proposal_id) filter (where s.used)) end
    from security.calendar_sources_v1(p_provider) s
$$;


ALTER FUNCTION "security"."calendar_set_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."calendar_set_v1"("p_provider" "uuid") IS 'CF-247 (decision 5 Nov 2026 §8): the fingerprint of the calendar readings a university''s intake dates use (each reading and its parser), or none:<n set aside>; a change makes every row of the university eligible again.';



CREATE OR REPLACE FUNCTION "security"."calendar_sources_v1"("p_provider" "uuid") RETURNS TABLE("proposal_id" "uuid", "fact_source_id" "uuid", "url" "text", "evidence_id" "uuid", "parser" "text", "decided_at" timestamp with time zone, "scope" "text", "used" boolean, "set_aside_reason" "text", "proposal" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with latest as (
    select distinct on (coalesce(p.fact_source_id::text, p.url)) p.id, p.fact_source_id, p.url, p.evidence_id, p.parser, p.decided_at, p.proposal
      from pipeline.provider_policy_proposals p
     where p.provider_id = p_provider and p.kind = 'intake_calendar' and p.status = 'approved'
     order by coalesce(p.fact_source_id::text, p.url), p.decided_at desc nulls last, p.created_at desc)
  select l.id, l.fact_source_id, l.url, l.evidence_id, l.parser, l.decided_at, s.scope,
         s.scope = 'main_teaching' and not coalesce(y.latest < extract(year from (now() at time zone 'Australia/Melbourne'))::int, false),  -- fixed: the calendar year in Australia
         case when s.scope = 'excluded_by_address' then 'the address names another campus, college, exchange or pathway calendar'
              when s.scope <> 'main_teaching' then 'the reader found this calendar is ' || replace(s.scope, '_', ' ')
              -- direction 5 Nov 2026 15:50 §2: an obsolete edition never supplies a current or future commencement, or a period name
              when y.latest < extract(year from (now() at time zone 'Australia/Melbourne'))::int then 'obsolete edition: its latest proved teaching start is in ' || y.latest end,
         l.proposal
    from latest l, lateral (select security.calendar_scope_v1(l.proposal, l.url, l.parser) scope) s,
         lateral (select max(d.year) latest from security.calendar_proposal_dates_v1(l.id) d
                   where d.kind = 'start' and d.year is not null and (d.quote ~ ('\m' || d.year || '\M') or coalesce(d.year_quote, '') ~ ('\m' || d.year || '\M'))) y
$$;


ALTER FUNCTION "security"."calendar_sources_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."calendar_sources_v1"("p_provider" "uuid") IS 'CF-247 (decision 5 Nov 2026 §2; direction 5 Nov 2026 15:50 §2): each calendar document of a university with its latest approved reading, its scope and whether intake dates use it: set aside with a reason when it is not the main teaching calendar or is an obsolete edition (its latest proved teaching start is before the current year); nothing replaced or deleted.';



CREATE OR REPLACE FUNCTION "security"."campus_primary_apply_v1"("p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_n int := 0; v_several int := 0; v_none int := 0; v_kept int := 0;
begin
  if auth.uid() is not null and coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  create temp table if not exists _cpa (provider_id uuid, campus_id uuid, n int, has_primary boolean) on commit drop;
  truncate _cpa;
  insert into _cpa
  select p.id, (array_agg(k.id order by k.id))[1], count(k.id),
         exists (select 1 from catalogue.campuses x where x.provider_id = p.id and x.is_primary)
    from catalogue.providers p
    left join catalogue.campuses k
      on k.provider_id = p.id and k.status = 'active'
     and lower(regexp_replace(btrim(k.address_line1), '\s+', ' ', 'g')) = lower(regexp_replace(btrim(p.address_line1), '\s+', ' ', 'g'))
     and btrim(coalesce(k.postcode, '')) = btrim(coalesce(p.postcode, ''))
   where nullif(btrim(p.address_line1), '') is not null
     and exists (select 1 from catalogue.provider_registrations r where r.provider_id = p.id and r.registration_scheme = 'cricos')
   group by p.id;
  select count(*) filter (where n = 1 and not has_primary), count(*) filter (where n > 1), count(*) filter (where n = 0), count(*) filter (where has_primary)
    into v_n, v_several, v_none, v_kept from _cpa;
  if p_apply and v_n > 0 then
    update catalogue.campuses k set is_primary = true, primary_basis = 'cricos_head_office'
      from _cpa c where c.n = 1 and not c.has_primary and k.id = c.campus_id and k.is_primary is distinct from true;
    get diagnostics v_n = row_count;
    insert into pipeline.admin_control_events (area, action, target, detail, actor)
    values ('api_v3', 'campus_primary_apply', 'catalogue.campuses.is_primary',
            jsonb_build_object('basis', 'cricos_head_office', 'marked', v_n, 'several', v_several, 'no_match', v_none, 'already_primary', v_kept), auth.uid());
  end if;
  return jsonb_build_object('applied', p_apply, 'marked', v_n, 'several_matches', v_several, 'no_match', v_none, 'already_primary', v_kept);
end;
$$;


ALTER FUNCTION "security"."campus_primary_apply_v1"("p_apply" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."campus_primary_apply_v1"("p_apply" boolean) IS 'CF-247 API v3 PR A (REQ-75, D-4): marks the one active campus matching a CRICOS provider''s registered address as primary (basis cricos_head_office); never changes a provider that already has a primary campus. Count-only unless p_apply; audited.';



CREATE OR REPLACE FUNCTION "security"."campus_regional_class_refresh_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'ref', 'security'
    AS $$
declare n int;
begin
  insert into pipeline.campus_regional_class(campus_id,state_code,postcode,category,category_name,metro_area,computed_at)
  select k.id, st.code, k.postcode, (c->>'category')::smallint,
         case (c->>'category')::int when 1 then 'Major city' when 2 then 'City or major regional centre' when 3 then 'Regional centre or other regional area' end,
         c->>'metro_area', now()
    from catalogue.campuses k left join ref.subdivisions s on s.id=k.subdivision_id
    -- CF-247 15 Oct 2026: when the register state disagrees with the postcode and the campus address names the postcode's state, the address wins
    cross join lateral (select case when security.au_state_from_postcode_v1(k.postcode) is not null and s.code is distinct from 'AU-' || security.au_state_from_postcode_v1(k.postcode)
                                     and concat_ws(' ', k.name, k.address_line1, k.address_line2) ~* ('\m' || security.au_state_from_postcode_v1(k.postcode) || '\M')
                                    then 'AU-' || security.au_state_from_postcode_v1(k.postcode) else s.code end code) st
    cross join lateral (select security.au_regional_class(st.code,k.postcode) c) z
  on conflict (campus_id) do update set state_code=excluded.state_code, postcode=excluded.postcode, category=excluded.category,
         category_name=excluded.category_name, metro_area=excluded.metro_area, computed_at=now()
   where pipeline.campus_regional_class.postcode is distinct from excluded.postcode or pipeline.campus_regional_class.state_code is distinct from excluded.state_code
      or pipeline.campus_regional_class.category is distinct from excluded.category;
  get diagnostics n=row_count;
  return jsonb_build_object('changed',n);
end $$;


