CREATE OR REPLACE FUNCTION "security"."cdesc_known_strip_v1"("p_text" "text", "p_title" "text", "p_provider" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare t text := coalesce(p_text, ''); x text;
begin
  -- the course's own title and provider (and the provider without Pty Ltd, Limited, Ltd or Inc) are taken out of a sentence, as whole phrases, before its tests;
  -- fixed: a name shorter than 4 characters is left in (an acronym such as MBA is also a common word in a sentence)
  foreach x in array array[p_title, p_provider, regexp_replace(coalesce(p_provider, ''), '\s+(pty\.?\s+ltd\.?|limited|ltd\.?|inc\.?)$', '', 'i')] loop
    continue when length(btrim(coalesce(x, ''))) < 4;
    t := regexp_replace(t, '(^|[^[:alnum:]])' || regexp_replace(btrim(x), '([.+*?^$(){}|/\\\[\]-])', '\\\1', 'g') || '(?![[:alnum:]])', '\1', 'gi');
  end loop;
  return t;
end $_$;


ALTER FUNCTION "security"."cdesc_known_strip_v1"("p_text" "text", "p_title" "text", "p_provider" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_known_strip_v1"("p_text" "text", "p_title" "text", "p_provider" "text") IS 'CF-247 F-CDESC (20261112190000): the course''s title and provider taken out of a description sentence before its tests (verified catalogue facts, never claims)';



CREATE OR REPLACE FUNCTION "security"."cdesc_learner_word_ok_v1"("p_word" "text", "p_text" "text", "p_quote" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare w text := lower(btrim(coalesce(p_word, ''))); v_t text := lower(coalesce(p_text, '')); v_q text := lower(coalesce(p_quote, '')); v_verb text;
begin
  if w = '' or w !~ '^[a-z]+$' then return false; end if; -- fixed: a plain word only, so it can sit inside the pattern below
  if not exists (select 1 from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'enrich.course_description_learner_words'), '[]'::jsonb)) x where lower(btrim(x)) = w) then return false; end if;
  if not security.pdesc_has_term_v1(p_text, w) or security.pdesc_has_term_v1(p_quote, w) then return false; end if;
  -- the quote must speak to the reader: a second-person pronoun, or a clause that opens with the verb the sentence gives the word ("Learn about ..." for "Students learn about ...")
  v_verb := substring(v_t from ('\m' || w || '\s+(?:(?:will|can|may|could|should|also|then)\s+)*([a-z]{3,})\M'));
  if v_verb in ('for', 'the', 'and', 'who', 'are', 'from', 'with', 'into', 'that', 'their', 'have', 'has', 'was', 'were', 'not') then v_verb := null; end if; -- fixed: function words are not a verb
  if v_q !~ '\myou(r|rs|rself)?\M' and (v_verb is null or v_q !~ ('(^|[.:;!?]\s*)' || v_verb || '\M')) then return false; end if;
  -- a population statement is not a stand-in for "you"
  return v_t !~ ('([0-9][0-9,.]*\s+([a-z-]+\s+)?' || w || '|' || w || '\s+(from\s+(over|more|across|around)|come|choose|rate|say|report|achieve|graduate|who|are|have|often|typically|usually|consistently|regularly)|(international|former|past|successful|our|alumni|graduate|all|many|most|other|some|top|best|brightest|talented|gifted|enrolled|current)\s+' || w
                 || '|of\s+' || w || '|' || w || '''?s?\s+(satisfaction|outcomes|success))');
end $_$;


ALTER FUNCTION "security"."cdesc_learner_word_ok_v1"("p_word" "text", "p_text" "text", "p_quote" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_learner_word_ok_v1"("p_word" "text", "p_text" "text", "p_quote" "text") IS 'CF-247 F-CDESC: true when the claim word is in enrich.course_description_learner_words, the sentence holds it, its quote does not (the page says "you"), and the sentence states no population (a figure beside it, our/international/former/all/top/current students, students from over ..., students who/are/have ..., of students, student satisfaction), and the quote speaks to the reader (you / your, or a clause that opens with the verb the sentence gives the word). Read only.';



