COMMENT ON FUNCTION "security"."cdesc_machine_fail_v1"("p_rule" "text", "p_reason" "text", "p_next" "text", "p_transient" boolean) IS 'CF-247 F-CDESC: the shape of a decline by the machine rule (reason code, reason, exact next action, whether it is worth looking at again soon).';



CREATE OR REPLACE FUNCTION "security"."cdesc_machine_ids_v1"("p_ids" "uuid"[]) RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v uuid[]; v_rel regclass := to_regclass('pipeline.course_description_machine_admissions');
begin
  -- the ledger exists once the machine admission change is applied (20261110060000): course_id, outcome ('admitted' | 'declined') and withdrawn_at.
  -- Not there, or not that shape: unknown (null), which the screen shows as "not known", never as "no machine admission".
  if v_rel is null or (select count(*) from pg_attribute a where a.attrelid = v_rel and a.attname in ('course_id', 'outcome', 'withdrawn_at') and not a.attisdropped) <> 3 then return null; end if;
  -- only a live admission counts: a declined row, or an admission a person later withdrew, is not "Machine-admitted" (a declined course a person then approved is "Human decision")
  execute 'select coalesce(array_agg(distinct m.course_id), ''{}''::uuid[]) from pipeline.course_description_machine_admissions m where m.course_id = any ($1) and m.outcome = ''admitted'' and m.withdrawn_at is null' into v using p_ids;
  return v;
end $_$;


ALTER FUNCTION "security"."cdesc_machine_ids_v1"("p_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."cdesc_machine_text_check_v1"("p_provider" "uuid", "p_text" "text", "p_sentences" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_s jsonb; v_t text; v_norm text := regexp_replace(lower(btrim(coalesce(p_text, ''))), '\s+', ' ', 'g');
begin
  if jsonb_typeof(p_sentences) is distinct from 'array' or jsonb_array_length(p_sentences) = 0
     or v_norm is distinct from (select regexp_replace(lower(string_agg(btrim(x->>'text'), ' ' order by o)), '\s+', ' ', 'g') from jsonb_array_elements(p_sentences) with ordinality e(x, o)) then
    -- no quote speaks for this text: the shared policy runs on it as it is
    return security.pdesc_machine_text_check_ctx_v1(p_provider, p_text, '{}', p_sentences);
  end if;
  select jsonb_agg(jsonb_set(x, '{text}', to_jsonb(security.cdesc_scrub_sentence_v1(x->>'text', x->>'quote'))) order by o),
         string_agg(btrim(security.cdesc_scrub_sentence_v1(x->>'text', x->>'quote')), ' ' order by o)
    into v_s, v_t from jsonb_array_elements(p_sentences) with ordinality e(x, o);
  return security.pdesc_machine_text_check_ctx_v1(p_provider, v_t, '{}', v_s);
end $$;


ALTER FUNCTION "security"."cdesc_machine_text_check_v1"("p_provider" "uuid", "p_text" "text", "p_sentences" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_machine_text_check_v1"("p_provider" "uuid", "p_text" "text", "p_sentences" "jsonb") IS 'CF-247 F-CDESC: the shared machine wording policy (security.pdesc_machine_text_check_ctx_v1: every list and the figures rule, unchanged) applied to a course description after security.cdesc_scrub_sentence_v1 has set aside what is not a claim. Returns null when the wording is admitted, else the first refused word, figure or markup. Read only.';



