    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select btrim(regexp_replace(lower(coalesce(p_text, '')), '[^a-z0-9]+', ' ', 'g'))
$$;


ALTER FUNCTION "security"."cdesc_norm_v1"("p_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_norm_v1"("p_text" "text") IS 'CF-247 F-CDESC: a description with case, punctuation and spacing removed, for the exact-duplicate test across the catalogue (md5 of this is indexed beside catalogue.courses).';



CREATE OR REPLACE FUNCTION "security"."cdesc_on_demand_v1"("p_action" "text", "p_args" "jsonb", "p_rank" integer, "p_uid" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  a jsonb := coalesce(p_args, '{}'::jsonb);
  v_mode text := lower(btrim(coalesce(a->>'mode', '')));
  v_ids uuid[] := array(select distinct x::uuid from jsonb_array_elements_text(case when jsonb_typeof(a->'course_ids') = 'array' then a->'course_ids' else '[]'::jsonb end) x);
  v_pids uuid[] := array(select distinct x::uuid from jsonb_array_elements_text(case when jsonb_typeof(a->'provider_ids') = 'array' then a->'provider_ids' else '[]'::jsonb end) x);
  v_max int := security.pipeline_num_v1('run_now.pilot_cap', 20)::int;
  v_cap int := security.pipeline_num_v1('enrich.course_text_items_per_day', 500)::int;
  v_vmax constant int := 10; -- fixed: the read-back calls public.website_v2_course for each course (about 255 ms each), so ten stay inside the 8 second request limit
  v_used int; v_room int; v_scope text; v_limit int; v_reason text; v_key text; v_given boolean; v_job uuid; v_n int; v_total int; v_elig int;
  v_blocks jsonb; v_sel uuid[]; v_providers uuid[]; v_flags bigint[]; f bigint; v_title text; v_usd numeric; v_rows jsonb; v_missing uuid[]; v_ex pipeline.admin_jobs%rowtype; v_ptitle text; v_zoho jsonb;
  r record; v_web jsonb; v_wst text; v_zst text; v_wnote text; v_znote text;
begin
  if p_action = 'verify' then
    if coalesce(p_rank, 0) < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
    if cardinality(v_ids) = 0 then raise exception 'choose the courses to check'; end if;
    if cardinality(v_ids) > v_vmax then raise exception 'check at most % courses at a time', v_vmax; end if;
    v_zoho := coalesce((select s.value from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'zoho.sync_countries'), '["AU"]'::jsonb); -- fixed: the Zoho feed's own default country (security.zoho_sync_item_v1)
    v_rows := '[]'::jsonb;
    for r in select co.id, nullif(btrim(co.description), '') descr, k.iso_alpha2::text cc, d.course_stable_key sk
               from catalogue.courses co join catalogue.providers pr on pr.id = co.provider_id join ref.countries k on k.id = pr.country_id
               left join lateral (select d0.course_stable_key from search.course_documents d0 where d0.course_id = co.id limit 1) d on true
              where co.id = any (v_ids) order by co.id loop
      v_wst := null; v_zst := null; v_wnote := null; v_znote := null;
      if r.descr is null then
        v_wst := 'not_applicable'; v_wnote := 'The catalogue holds no description, so there is nothing to carry.';
        v_zst := 'not_applicable'; v_znote := v_wnote;
      else
        if r.sk is null then v_wst := 'pending'; v_wnote := 'The course is not in the published search set yet.';
        else
          begin
            v_web := public.website_v2_course(r.sk);
            v_wst := case when v_web->'item'->>'description' is null then 'missing' when v_web->'item'->>'description' = r.descr then 'matched' else 'differs' end;
            v_wnote := case v_wst when 'matched' then 'The Website API returns the same words as the catalogue.' when 'missing' then 'The Website API returns no description for this course.' else 'The Website API returns different words from the catalogue.' end;
          exception when others then
            v_wst := 'unknown'; v_wnote := 'The read-back failed: ' || left(sqlerrm, 160); -- fixed: the length of an error shown to a person
          end;
        end if;
        if not (v_zoho ? r.cc) then v_zst := 'not_applicable'; v_znote := 'The country is not synced to Zoho (zoho.sync_countries).';
        elsif r.sk is null then v_zst := 'pending'; v_znote := 'The course is not in the published search set yet.';
        else
          select case when z.item_key is null then 'pending' when z.item ? 'description' then (case when z.item->>'description' = r.descr then 'matched' else 'differs' end) else 'not_carried' end
            into v_zst from (select 1) one left join pipeline.zoho_sync_items z on z.entity = 'course' and z.item_key = r.sk and z.removed_at is null;
          v_znote := case v_zst when 'pending' then 'The course is not in the Zoho course feed yet.' when 'matched' then 'The Zoho course item holds the same words.'
                                when 'differs' then 'The Zoho course item holds different words.' else 'The Zoho course item has no description field, so Zoho does not receive it from this feed.' end;
        end if;
      end if;
      v_rows := v_rows || jsonb_build_array(jsonb_build_object('course_id', r.id, 'stable_key', r.sk, 'country', r.cc,
        'catalogue', jsonb_build_object('state', case when r.descr is null then 'missing' else 'present' end, 'chars', length(r.descr)),
        'website', jsonb_build_object('state', v_wst, 'note', v_wnote), 'zoho', jsonb_build_object('state', v_zst, 'note', v_znote),
        'http', jsonb_build_object('state', 'not_checked', 'note', 'The database cannot call the website. The release check reads the Website API over HTTP; until it has, this is not checked, neither passed nor failed.')));
    end loop;
    return jsonb_build_object('verified_at', now(), 'courses', v_rows, 'missing', to_jsonb(array(select x from unnest(v_ids) x where x not in (select (e->>'course_id')::uuid from jsonb_array_elements(v_rows) e))),
      'summary', jsonb_build_object(
        'website', (select coalesce(jsonb_object_agg(s, n), '{}'::jsonb) from (select e->'website'->>'state' s, count(*) n from jsonb_array_elements(v_rows) e group by 1) z),
        'zoho', (select coalesce(jsonb_object_agg(s, n), '{}'::jsonb) from (select e->'zoho'->>'state' s, count(*) n from jsonb_array_elements(v_rows) e group by 1) z)));
  end if;

  if p_action = 'description_tasks' then
    if coalesce(p_rank, 0) < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
    -- the saved record of the on-demand tasks (newest first; one screen's list), so the person finds the task and its outcome after closing the browser; optionally only the tasks that held one course
    return jsonb_build_object('tasks', coalesce((select jsonb_agg(t.x order by t.created_at desc) from (
      select j.created_at, jsonb_build_object('id', j.id, 'title', j.title, 'state', j.state, 'progress', j.progress, 'reason', j.reason, 'created_at', j.created_at, 'finished_at', j.finished_at,
               'mode', j.args->>'mode', 'scope', j.args->>'scope', 'requested_by', j.requested_by,
               'by_state', (select coalesce(jsonb_object_agg(z.s, z.n), '{}'::jsonb) from (select e.state s, count(*) n from pipeline.field_enrich_items e where e.job_id = j.id group by 1) z),
               'described_now', (select count(*) from pipeline.field_enrich_items e join catalogue.courses c on c.id = e.course_id where e.job_id = j.id and nullif(btrim(c.description), '') is not null)) x
        from pipeline.admin_jobs j
       where j.kind = 'enrich_fields' and j.args->>'on_demand' = 'true'
         and (cardinality(v_ids) = 0 or exists (select 1 from pipeline.field_enrich_items e where e.job_id = j.id and e.course_id = any (v_ids)))
       order by j.created_at desc limit 10) t), '[]'::jsonb)); -- fixed: one screen's list of tasks
  end if;

  -- preview and start
  if p_action not in ('preview', 'start') then raise exception 'unknown action %', p_action using errcode = '22023'; end if;
  if v_mode not in ('fill', 'recheck') then raise exception 'choose Fill description or Recheck description'; end if;
  if cardinality(v_ids) > 0 and cardinality(v_pids) > 0 then raise exception 'choose courses or one university, not both'; end if;
  if cardinality(v_ids) > 0 then
    v_scope := 'courses';
    if cardinality(v_ids) > v_max then raise exception 'choose at most % courses at a time (Pipeline settings > Run now: most courses in a cohort)', v_max; end if;
  elsif cardinality(v_pids) = 1 then
    v_scope := 'university';
  else
    raise exception 'choose up to % courses, or one university', v_max;
  end if;

  if p_action = 'start' then
    if coalesce(p_rank, 0) < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
    v_reason := btrim(coalesce(a->>'reason', ''));
    if length(v_reason) < 4 then raise exception 'give a reason (it is kept with the task)'; end if;
    v_given := nullif(btrim(coalesce(a->>'idempotency_key', '')), '') is not null;
    v_key := left(coalesce(nullif(btrim(coalesce(a->>'idempotency_key', '')), ''),
                'cdesc:' || v_mode || ':' || md5(coalesce((select string_agg(x::text, ',' order by x) from unnest(case when v_scope = 'courses' then v_ids else v_pids end) x), ''))), 120); -- fixed: a key's length
    -- Locks come BEFORE the selection, so what is chosen is what is true when the items are written. A request for one university takes that university's lock exclusively; a request for chosen
    -- courses takes each course's lock exclusively and each of their universities' locks shared (so two course requests in one university run side by side, but a university request waits for
    -- them and they wait for it). Always taken providers first, then courses, in sorted order, so two requests can never wait on each other. The standing queue takes no lock: see the header.
    perform pg_advisory_xact_lock(hashtextextended('cdesc_on_demand:' || v_key, 0));
    if v_scope = 'university' then
      perform pg_advisory_xact_lock(hashtextextended('cdesc_provider:' || v_pids[1]::text, 0));
    else
      for r in select distinct co.provider_id pid from catalogue.courses co where co.id = any (v_ids) order by 1 loop
        perform pg_advisory_xact_lock_shared(hashtextextended('cdesc_provider:' || r.pid::text, 0));
      end loop;
      for r in select x from unnest(v_ids) x order by 1 loop
        perform pg_advisory_xact_lock(hashtextextended('cdesc_course:' || r.x::text, 0));
      end loop;
    end if;
    select * into v_ex from pipeline.admin_jobs j where j.kind = 'enrich_fields' and j.args->>'idempotency_key' = v_key and (v_given or j.state in ('queued', 'running')) order by j.created_at desc limit 1;
    if v_ex.id is not null then
      if v_ex.args->>'mode' is distinct from v_mode or v_ex.args->>'scope' is distinct from v_scope then
        raise exception 'this idempotency key was already used for a different request (% / %); use a new key', v_ex.args->>'mode', v_ex.args->>'scope';
      end if;
      return jsonb_build_object('job_id', v_ex.id, 'items', (select count(*) from pipeline.field_enrich_items e where e.job_id = v_ex.id), 'repeat', true, 'mode', v_mode, 'scope', v_scope, 'idempotency_key', v_key);
    end if;
  end if;

  -- the day's room under the standing queue's own ceiling (items already made today for the description, by any route)
  select v_cap - count(*) into v_used from pipeline.field_enrich_items e where e.field = 'description' and e.created_at > now() - interval '1 day'; -- fixed: the cap is a day's
  v_room := greatest(v_used, 0); -- v_used is what is left of the day's ceiling
  v_limit := case when v_scope = 'courses' then least(v_max, v_room) else v_room end; -- an on-demand request never takes more readings than the day's ceiling leaves

  create temporary table if not exists pg_temp.cdesc_sel (course_id uuid, provider_id uuid, block text, ord int, flags bigint[], payload jsonb) on commit drop;
  truncate pg_temp.cdesc_sel;
  insert into pg_temp.cdesc_sel(course_id, provider_id, block, ord, flags, payload)
  select s.course_id, s.provider_id, case v_mode when 'fill' then s.fill_block else s.recheck_block end,
         row_number() over (order by (s.last_item_id is not null), s.last_attempt_at nulls first, s.course_id),
         s.release_flag_ids,
         to_jsonb(s) || jsonb_build_object('fill_info', security.cdesc_block_info_v1(s.fill_block), 'recheck_info', security.cdesc_block_info_v1(s.recheck_block))
    from security.cdesc_state_v1(case when v_scope = 'courses' then v_ids end, case when v_scope = 'university' then v_pids[1] end) s;

  v_total := (select count(*) from pg_temp.cdesc_sel);
  -- back-pressure as the standing queue has it (enrich.course_description_pending_global_max, 0 = off): no new readings while that many descriptions already wait for a person in Layer 4
  if coalesce(security.pipeline_num_v1('enrich.course_description_pending_global_max', 0), 0) > 0
     and (select count(*) from pipeline.layer4_review_items q where q.entity_type = 'course' and q.field_code = 'course_description_first_read' and q.status = 'pending')
         >= security.pipeline_num_v1('enrich.course_description_pending_global_max', 0) then
    update pg_temp.cdesc_sel set block = 'review_backlog' where block is null;
  end if;
  v_elig := (select count(*) from pg_temp.cdesc_sel where block is null);
  v_missing := array(select x from unnest(v_ids) x where x not in (select course_id from pg_temp.cdesc_sel));
  -- a request queues the first v_limit eligible courses (never-tried first, then the oldest attempt); the rest wait for the next request
  update pg_temp.cdesc_sel set block = 'daily_capacity' where block is null and ord > 0
     and (select count(*) from pg_temp.cdesc_sel x where x.block is null and x.ord <= pg_temp.cdesc_sel.ord) > v_limit;
  v_blocks := (select coalesce(jsonb_object_agg(k, n), '{}'::jsonb) from (select block k, count(*) n from pg_temp.cdesc_sel where block is not null group by 1) z);
  v_n := (select count(*) from pg_temp.cdesc_sel where block is null);
  v_usd := nullif((security.enrich_unit_costs_v1()->>'enrich_usd_per_item')::numeric, 0);

  if p_action = 'preview' then
    if coalesce(p_rank, 0) < 3 then raise exception 'Curator role or above required' using errcode = '42501'; end if;
    return jsonb_build_object('mode', v_mode, 'scope', v_scope, 'selected', case when v_scope = 'courses' then cardinality(v_ids) end, 'missing', to_jsonb(v_missing),
      'total', v_total, 'eligible', v_elig, 'to_queue', v_n, 'left_for_later', v_elig - v_n, 'blocked', v_blocks,
      'blocked_info', (select coalesce(jsonb_object_agg(k, security.cdesc_block_info_v1(k)), '{}'::jsonb) from jsonb_object_keys(v_blocks) k),
      'limit', jsonb_build_object('courses_per_request', v_max, 'room_today', v_room, 'items_per_day', v_cap),
      'estimate', jsonb_build_object('items', v_n, 'usd_per_item', v_usd, 'usd', case when v_usd is null then null else round(v_n * v_usd, 4) end, 'scraper_credits', 0),
      'courses', case when v_scope = 'courses' then (select coalesce(jsonb_agg(z.payload || jsonb_build_object('block', z.block, 'block_info', security.cdesc_block_info_v1(z.block), 'will_queue', z.block is null) order by z.ord), '[]'::jsonb) from pg_temp.cdesc_sel z)
                     else (select coalesce(jsonb_agg(z.payload || jsonb_build_object('block', z.block, 'block_info', security.cdesc_block_info_v1(z.block), 'will_queue', z.block is null) order by z.ord), '[]'::jsonb)
                             from (select * from pg_temp.cdesc_sel order by (block is not null), ord limit v_max) z) end);
  end if;

  -- start (rank, reason, key, locks and the repeat check were done before the selection)
  if v_n = 0 then
    raise exception 'nothing to queue: %', coalesce((select string_agg(coalesce(security.cdesc_block_info_v1(k)->>'label', k) || ' (' || n || ')', '; ' order by n desc) from (select block k, count(*) n from pg_temp.cdesc_sel where block is not null group by 1) z), 'no course found');
  end if;
  v_sel := array(select course_id from pg_temp.cdesc_sel where block is null order by ord);
  v_providers := array(select distinct provider_id from pg_temp.cdesc_sel where block is null);
  v_ptitle := case when v_scope = 'university' then (select coalesce(pr.display_name, pr.canonical_name) from catalogue.providers pr where pr.id = v_pids[1]) end;
  v_title := left((case v_mode when 'fill' then 'Fill description' else 'Recheck description' end) || ' · ' || case when v_scope = 'university' then coalesce(v_ptitle, 'university') || ' · ' || v_n || ' course(s)'
                                                                                                                     else v_n || ' course(s)' end, 200); -- fixed: the title column's length (as Enrich fields)
  insert into pipeline.admin_jobs(kind, lane, state, title, args, progress, requested_by, reason, scope)
  values ('enrich_fields', 'enrich', 'queued', v_title,
          jsonb_build_object('countries', '[]'::jsonb, 'provider_ids', to_jsonb(v_providers), 'fields', jsonb_build_array('description'), 'ai', true, 'scraper', false,
                             'on_demand', true, 'mode', v_mode, 'scope', v_scope, 'course_ids', case when v_scope = 'courses' then to_jsonb(v_sel) else '[]'::jsonb end,
                             'idempotency_key', v_key, 'requested_courses', case when v_scope = 'courses' then cardinality(v_ids) else v_total end),
          jsonb_build_object('done', 0, 'total', 0), p_uid, v_reason, case when v_scope = 'university' then coalesce(v_ptitle, '1 university') else v_n || ' courses' end)
  returning id into v_job;
  -- recheck: the counting flag (the standing queue's wait) of each chosen course's description is released as a person's release, in the flag history, so the engine's own gate lets the item in
  if v_mode = 'recheck' then
    for f in select unnest(flags) from pg_temp.cdesc_sel where block is null and flags is not null loop
      perform security.flag_release_v1(f, p_uid::text, 'person', 'Recheck description requested: ' || v_reason, jsonb_build_object('job_id', v_job), false);
    end loop;
  end if;
  insert into pipeline.field_enrich_items(job_id, provider_id, course_id, field)
  select v_job, s.provider_id, s.course_id, 'description' from pg_temp.cdesc_sel s where s.block is null order by s.ord on conflict do nothing;
  select count(*) into v_n from pipeline.field_enrich_items where job_id = v_job;
  if v_n = 0 then raise exception 'nothing was queued (the engine''s own gate holds every chosen course); nothing was changed'; end if;
  update pipeline.admin_jobs set progress = jsonb_build_object('done', 0, 'total', v_n) where id = v_job;
  insert into pipeline.admin_job_events(job_id, note, detail) values (v_job, v_n || ' item(s) to settle', jsonb_build_object('mode', v_mode, 'scope', v_scope, 'reason', v_reason));
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('enrich_fields', 'on_demand_' || v_mode, v_job::text, jsonb_build_object('job_id', v_job, 'items', v_n, 'scope', v_scope, 'reason', v_reason, 'blocked', v_blocks, 'idempotency_key', v_key), p_uid);
  return jsonb_build_object('job_id', v_job, 'items', v_n, 'repeat', false, 'mode', v_mode, 'scope', v_scope, 'blocked', v_blocks, 'left_for_later', v_elig - v_n, 'idempotency_key', v_key);
end $$;


ALTER FUNCTION "security"."cdesc_on_demand_v1"("p_action" "text", "p_args" "jsonb", "p_rank" integer, "p_uid" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_on_demand_v1"("p_action" "text", "p_args" "jsonb", "p_rank" integer, "p_uid" "uuid") IS 'CF-247 F-CDESC.06: preview, start and verify of Fill description / Recheck description through the Enrich fields task engine (called by public.admin_enrich_fields).';



CREATE OR REPLACE FUNCTION "security"."cdesc_page_kind_v1"("p_url" "text", "p_title" "text", "p_basis" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_path text; v_segs text[]; v_n int; v_tok text[]; v_ta text[]; v_st text[]; v_good boolean[]; v_i int; v_clean text; v_dis int;
        -- fixed: the names a university gives its institution-level pages and its course tabs (structure of the web, not an operating value)
        v_inst constant text := '^(about-us|aboutus|about-(?!(this|the|your|our)-(course|program|programme|degree|qualification|unit|study)s?(-|$))[a-z0-9-]+|[a-z0-9-]+-about-us|who-we-are|why-(study|choose|come|join|learn)-(with|at|in)-[a-z0-9-]+|why-us|our-(story|history|values|university|college|institute|mission|vision|people|campus|campuses)(-[a-z0-9-]+)?|facts-(and|n|&)-figures|facts-figures|at-a-glance|(university|college|institute)-(overview|profile|facts)[a-z0-9-]*)$';
        v_amb constant text := '^(about|overview|about-(this|the|your)-(course|program|programme|degree|qualification))$';
        -- fixed: award words and joining words never identify a subject; a word of fewer than four letters never does either (of, in, and, the ...)
        v_award constant text[] := array['bachelor', 'master', 'masters', 'doctor', 'diploma', 'certificate', 'graduate', 'postgraduate', 'honours', 'associate'];
        v_stop constant text[] := array['bachelor', 'master', 'masters', 'doctor', 'diploma', 'certificate', 'graduate', 'postgraduate', 'honours', 'associate', 'degree', 'advanced', 'with', 'level', 'course', 'program', 'programme'];
        -- fixed: a segment that names a faculty, school or department (a part of the university) is not a course
        v_fac constant text[] := array['faculty', 'faculties', 'school', 'schools', 'department', 'departments', 'dept', 'college', 'colleges', 'institute', 'centre', 'center', 'division', 'campus', 'university'];
begin
  if nullif(btrim(coalesce(p_url, '')), '') is null then return 'no_bound_page'; end if;
  v_path := lower(regexp_replace(split_part(split_part(btrim(p_url), '#', 1), '?', 1), '^[a-z][a-z0-9+.-]*://[^/]*', ''));
  v_segs := array(select regexp_replace(x, '\.(html?|shtml|aspx?|php|jsp|cfm)$', '') from regexp_split_to_table(v_path, '/') with ordinality t(x, o) where x <> '' order by o);
  v_n := coalesce(array_length(v_segs, 1), 0);
  while v_n > 1 and v_segs[v_n] in ('index', 'default', 'home') loop v_segs := v_segs[1 : v_n - 1]; v_n := v_n - 1; end loop;
  if v_n = 0 then return 'no_course_in_address'; end if;
  if exists (select 1 from unnest(v_segs) x where x ~ v_inst) then return 'university_about_page'; end if;
  -- a bare about / overview anywhere but at the end is a parent section of the university
  for v_i in 1 .. v_n - 1 loop
    if v_segs[v_i] ~ v_amb then return 'university_about_page'; end if;
  end loop;
  if v_segs[v_n] !~ v_amb and p_basis is distinct from 'host_page' then return null; end if;
  -- the course title: its distinctive subject words and its award words
  v_clean := regexp_replace(regexp_replace(lower(coalesce(p_title, '')), 'level\s*\d+', ' ', 'g'), '[^a-z0-9]+', ' ', 'g');
  v_tok := array(select distinct w from regexp_split_to_table(v_clean, ' ') w where length(w) >= 4 and not (w = any (v_stop))); -- fixed: a word of fewer than four letters never identifies a subject
  v_ta := array(select distinct w from regexp_split_to_table(v_clean, ' ') w where w = any (v_award));
  v_dis := coalesce(array_length(v_tok, 1), 0);
  v_good := array_fill(false, array[v_n]);
  for v_i in 1 .. v_n loop
    continue when v_segs[v_i] ~ v_amb;
    v_st := array(select w from regexp_split_to_table(v_segs[v_i], '[-_]+') w where w <> '');
    -- the segment names the course: all the distinctive title words (word-set containment), an award word of the title if it has one, and no faculty / school / department word the title does not carry
    v_good[v_i] := v_dis > 0 and v_tok <@ v_st and (cardinality(v_ta) = 0 or v_ta && v_st)
                   and not exists (select 1 from unnest(v_st) w where w = any (v_fac) and not (w = any (v_tok)));
  end loop;
  if v_segs[v_n] ~ v_amb then
    if v_n >= 2 and v_good[v_n - 1] then return null; end if;
    return 'university_about_page';
  end if;
  if true = any (v_good) then return null; end if;
  return 'host_page_no_course_evidence';
end $_$;


ALTER FUNCTION "security"."cdesc_page_kind_v1"("p_url" "text", "p_title" "text", "p_basis" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_page_kind_v1"("p_url" "text", "p_title" "text", "p_basis" "text") IS 'CF-247 F-CDESC: null when the address of a bound page is a page about the course; no_bound_page (no address, fails closed), no_course_in_address, university_about_page for an institution-level About / Overview / Who we are / Our story / Facts and figures address or a parent /about/ section, host_page_no_course_evidence for a page proved only by its host with no course in the address. Read only.';



CREATE OR REPLACE FUNCTION "security"."cdesc_parked_other_v1"("p_item" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- the machine has declined this waiting item for good for a reason that is not a duplicate: it cannot be admitted, so it does not hold up a twin
  select exists (select 1 from pipeline.course_description_machine_admissions d where d.review_item_id = p_item and d.outcome = 'declined' and d.withdrawn_at is null and not d.transient and d.reason_code not like 'duplicate\_%')
$$;


ALTER FUNCTION "security"."cdesc_parked_other_v1"("p_item" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_parked_other_v1"("p_item" "uuid") IS 'CF-247 F-CDESC: true when the machine rule has declined the waiting item for good for a reason other than a duplicate (it cannot be admitted, so it must not hold up a twin with the same wording). Read only.';



CREATE OR REPLACE FUNCTION "security"."cdesc_points_back_v1"("p_text" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  -- fixed: a structural test of the grammar (a sentence that opens with a pronoun, a connecting word, "the program" or a quote or bracket), not a tunable limit
  select btrim(coalesce(p_text, '')) ~* '^\s*(((this|these|that|those|it|its|they|their|them|he|she|his|her|such|both|also|however|therefore|thus|moreover|furthermore|additionally|in addition|as a result|another|alternatively|further|and|which|here|each|but|or|so|yet|then|instead|otherwise|similarly|likewise|meanwhile|for example|for instance|in particular|the (program|programme|course|degree|qualification|major))\M)|["''“‘(\[«])'
      -- 13 Nov 2026 (QA of this change): openers the first list misses, and "<subject> then ..."
      or btrim(coalesce(p_text, '')) ~* '^\s*((as such|building on|finally|afterwards|afterward|subsequently|in turn|lastly|secondly|thirdly)\M|\S+\s+then\M)'
$$;


ALTER FUNCTION "security"."cdesc_points_back_v1"("p_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_points_back_v1"("p_text" "text") IS 'Course description subset recovery: true when a sentence opens by pointing back to the sentence before it (pronoun, connecting word, "the program", "<subject> then", quote or bracket). The one definition used by security.cdesc_subset_plan_v1.';



CREATE OR REPLACE FUNCTION "security"."cdesc_prompt_supersede_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_max int := security.pipeline_num_v1('layer4.reconcile_batch', 200)::int; v_ver text := security.cdesc_prompt_version_v1(); v_stamp text := security.course_description_machine_policy_stamp_v1();
        r record; v_n int := 0;
begin
  -- a first course description waiting in Layer 4 that an earlier prompt made, and that the machine rule declined for good, waits for nothing a person can usefully decide:
  -- it is superseded (decided_before: the machine decided it) and its reading is read again with the released prompt. A locked course is never touched.
  for r in select q.id, q.entity_id, q.evidence_id, q.layer3_state->>'prompt' pr,
                  case when coalesce(q.proposed_value->>'item_id', '') ~ '^\d+$' then (q.proposed_value->>'item_id')::bigint end item_id
             from pipeline.layer4_review_items q
            where q.entity_type = 'course' and q.field_code = 'course_description_first_read' and q.status = 'pending'
              and coalesce(q.layer3_state->>'prompt', '') <> v_ver
              -- declined for good under the CURRENT policy (the same test as security.cdesc_provider_slots_v1): an item the new checks have not looked at yet waits for them
              and exists (select 1 from pipeline.course_description_machine_admissions d where d.review_item_id = q.id and d.outcome = 'declined' and d.withdrawn_at is null and not d.transient
                             and d.policy_stamp = v_stamp)
              and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = q.entity_id and k.field in ('description', 'course_description', 'all'))
            order by q.created_at limit v_max
            for update of q skip locked loop
    update pipeline.layer4_review_items set status = 'superseded', decided_at = now(),
           change_control_ref = left(coalesce(change_control_ref, '') || ' | superseded: decided_before (declined for good by cdesc-machine-v2; read again with ' || v_ver || ')', 400)
     where id = r.id and status = 'pending';
    continue when not found;
    insert into pipeline.layer4_supersessions(item_id, field_code, entity_type, entity_id, reason, covered_by_item, evidence, mode)
    values (r.id, 'course_description_first_read', 'course', r.entity_id, 'decided_before', null,
            jsonb_build_object('by', 'cdesc-prompt-supersede', 'machine_outcome', 'declined', 'prompt_before', r.pr, 'prompt_after', v_ver, 'evidence_id', r.evidence_id), 'reconcile');
    if to_regclass('pipeline.layer4_item_readiness') is not null then
      execute 'update pipeline.layer4_item_readiness set item_status = ''superseded'', readiness = ''closed'', classified_at = now() where item_id = $1' using r.id;
    end if;
    -- security.course_description_review_trg_v1 has set the reading skipped ("not admitted in Layer 4 (superseded)"); it is marked to be read again
    update pipeline.field_enrich_items e set reason = left('superseded: declined for good under ' || coalesce(r.pr, 'an unrecorded prompt') || '; read again with ' || v_ver, 300), updated_at = now()
     where e.field = 'description' and e.course_id = r.entity_id and e.state = 'skipped' and (e.id = r.item_id or e.value->>'review_item_id' = r.id::text);
    v_n := v_n + 1;
  end loop;
  return jsonb_build_object('superseded', v_n, 'prompt', v_ver, 'batch', v_max);
end $_$;


ALTER FUNCTION "security"."cdesc_prompt_supersede_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_prompt_supersede_v1"() IS 'CF-247 F-CDESC (20261112170000): supersedes first course descriptions an earlier prompt made that the machine declined for good, so they are read again with cdesc-source-grounded-v1 (job course-description-machine)';



CREATE OR REPLACE FUNCTION "security"."cdesc_prompt_version_v1"() RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select 'cdesc-source-grounded-v3'::text  -- fixed: the code identity of the released course description prompt (course-text.ts CDESC_PROMPT_VERSION), not an operational value
$$;


ALTER FUNCTION "security"."cdesc_prompt_version_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_prompt_version_v1"() IS 'CF-247 F-CDESC (20261112170000): the released course description prompt version; a held or superseded reading made by another prompt is read again once';



CREATE OR REPLACE FUNCTION "security"."cdesc_provider_slots_v1"("p_provider" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- the places a provider still has for first descriptions waiting in Layer 4: enrich.course_description_pending_max less the waiting items the machine has NOT declined for good under the current policy (those wait for a person and take no place a reading could use)
  select security.pipeline_num_v1('enrich.course_description_pending_max', 10)::int - count(*)::int
    from pipeline.layer4_review_items q join catalogue.courses c on c.id = q.entity_id
   where q.entity_type = 'course' and q.field_code = 'course_description_first_read' and q.status = 'pending' and c.provider_id = p_provider
     and not exists (select 1 from pipeline.course_description_machine_admissions d where d.review_item_id = q.id and d.outcome = 'declined' and d.withdrawn_at is null and not d.transient
                        and d.policy_stamp = security.course_description_machine_policy_stamp_v1())
$$;


ALTER FUNCTION "security"."cdesc_provider_slots_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_provider_slots_v1"("p_provider" "uuid") IS 'CF-247 F-CDESC: the places a provider has left for first course descriptions waiting in Layer 4: enrich.course_description_pending_max less the waiting items that the machine rule has not already declined for good under the current policy stamp. Read only.';



CREATE OR REPLACE FUNCTION "security"."cdesc_reading_provenance_v1"("p_item" bigint, "p_value" "jsonb", "p_l3" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_m text; v_p text; v_w text; a jsonb;
begin
  -- 1. recorded on the Layer 4 item
  v_m := nullif(btrim(p_l3->>'model'), ''); v_p := nullif(btrim(p_l3->>'prompt'), ''); v_w := nullif(btrim(p_l3->>'worker'), '');
  if v_m is not null and v_p is not null then return jsonb_build_object('model', v_m, 'prompt', v_p, 'worker', v_w, 'from', 'layer4_item'); end if;
  -- 2. recorded on the reading itself (held readings, from this change on)
  v_m := nullif(btrim(p_value->'reader'->>'model'), ''); v_p := nullif(btrim(p_value->'reader'->>'prompt'), ''); v_w := nullif(btrim(p_value->'reader'->>'worker'), '');
  if v_m is not null and v_p is not null then return jsonb_build_object('model', v_m, 'prompt', v_p, 'worker', v_w, 'from', 'reading'); end if;
  -- 3. the AI answer stored for this reading, only when it holds exactly the sentences the reading holds (the same reading, not another attempt)
  select x.answer into a from pipeline.enrich_ai_answers x
   where x.item_id = p_item and nullif(btrim(x.answer->>'model'), '') is not null and nullif(btrim(x.answer->>'prompt_version'), '') is not null
     and x.answer->'value'->'sentences' is not null and x.answer->'value'->'sentences' = p_value->'sentences'
   order by x.id desc limit 1;
  if a is not null then return jsonb_build_object('model', a->>'model', 'prompt', a->>'prompt_version', 'worker', nullif(btrim(a->>'worker'), ''), 'from', 'ai_answer'); end if;
  return jsonb_build_object('from', 'none');
end $$;


ALTER FUNCTION "security"."cdesc_reading_provenance_v1"("p_item" bigint, "p_value" "jsonb", "p_l3" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_reading_provenance_v1"("p_item" bigint, "p_value" "jsonb", "p_l3" "jsonb") IS 'CF-247 F-CDESC: the model, prompt version and worker that made a course description reading: from the Layer 4 item, else the reading, else the stored AI answer that holds exactly the reading''s sentences; otherwise none (the machine rule then declines the item as reader_unrecorded). Read only.';



CREATE OR REPLACE FUNCTION "security"."cdesc_recheck_held_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_stamp text := security.course_description_machine_policy_stamp_v1(); v_cap int := security.pipeline_num_v1('enrich.course_text_items_per_day', 500)::int; -- derived: never more in a run than the platform reads in a day
        v_days int := security.pipeline_num_v1('gaps.recheck_days', 60)::int; v_t0 timestamptz := clock_timestamp(); v_prov jsonb; v_chk jsonb; v_res text; v_looked int := 0; v_noprov int := 0; v_replayed int := 0; v_to_l4 int := 0; v_promoted int := 0; v_p uuid;
begin
  if security.pipeline_num_v1('enrich.course_description_machine_on', 0) < 1 then return jsonb_build_object('on', false); end if;
  -- (a) a reading held by a check is looked at again once for each policy stamp: where the live text check now passes and the reader is provable, the one record function takes it as the reader would have
  for r in select e.id, e.course_id, e.value, e.quote from pipeline.field_enrich_items e
            where e.field = 'description' and e.state = 'skipped' and e.reason like 'held: %' and e.course_id is not null and jsonb_typeof(e.value->'sentences') = 'array'
              and e.value->>'recheck_stamp' is distinct from v_stamp and e.updated_at > now() - make_interval(days => v_days)
            order by e.id limit v_cap loop
    exit when clock_timestamp() - v_t0 > make_interval(secs => 20); -- fixed: stays well inside the 120 s statement time-out of the job, with the settle and the follow-up that come after
    v_looked := v_looked + 1;
    begin
      v_prov := security.cdesc_reading_provenance_v1(r.id, r.value);
      v_chk := security.course_description_check_v1(r.course_id, r.value);
      if nullif(v_prov->>'model', '') is null or nullif(v_prov->>'prompt', '') is null then
        v_noprov := v_noprov + 1;
        update pipeline.field_enrich_items set value = value || jsonb_build_object('recheck_stamp', v_stamp) where id = r.id; -- noted; updated_at stays, so the queue's own timing is not moved
      elsif not coalesce((v_chk->>'ok')::boolean, false) then
        update pipeline.field_enrich_items set value = value || jsonb_build_object('recheck_stamp', v_stamp) where id = r.id;
      else
        v_res := security.enrich_course_text_record_v1(r.id, jsonb_build_object('value', r.value || jsonb_build_object('recheck_stamp', v_stamp), 'quote', r.quote,
                                                            'model', v_prov->>'model', 'prompt_version', v_prov->>'prompt', 'worker', v_prov->>'worker'));
        v_replayed := v_replayed + 1; if v_res = 'review' then v_to_l4 := v_to_l4 + 1; end if;
      end if;
    exception when others then null; -- one reading never stops the rest; it is looked at again on the next stamp
    end;
  end loop;
  -- (b) held first-admission readings take the places that are free (declined descriptions no longer fill them)
  for v_p in select distinct e.provider_id from pipeline.field_enrich_items e
              where e.field = 'description' and e.state = 'skipped' and e.reason like 'held\_first\_admission:%' and e.provider_id is not null order by 1 loop
    exit when clock_timestamp() - v_t0 > make_interval(secs => 25); -- fixed: with (a) it stays inside the time box above
    begin v_promoted := v_promoted + security.course_description_promote_held_v1(v_p); exception when others then null; end;
  end loop;
  return jsonb_build_object('on', true, 'looked_at', v_looked, 'no_provable_reader', v_noprov, 'replayed', v_replayed, 'to_layer4', v_to_l4, 'promoted_into_free_places', v_promoted);
end $$;


ALTER FUNCTION "security"."cdesc_recheck_held_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_recheck_held_v1"() IS 'CF-247 F-CDESC: part of the job course-description-machine. (a) Each reading held by a text check is looked at again once per policy stamp with the live check; one that now passes, whose reader is provable and that is still on the course''s bound page goes through the one record function (identity, lock, cap, Layer 4, then the machine rule) exactly as a fresh reading. (b) Held first-admission readings take the provider places that are free. No AI call, no spend; nothing is admitted here (the machine rule does that). Needs enrich.course_description_machine_on = 1.';



CREATE OR REPLACE FUNCTION "security"."cdesc_refers_back_v1"("p_text" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  -- fixed: a structural test of the grammar: the sentence opens by pointing back (security.cdesc_points_back_v1) or refers to something earlier inside it
  select security.cdesc_points_back_v1(p_text) or security.cdesc_refers_within_v1(p_text)
$$;


ALTER FUNCTION "security"."cdesc_refers_back_v1"("p_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_refers_back_v1"("p_text" "text") IS 'Course description shortening: true when a sentence refers back to an earlier one (it opens by pointing back, or says these, those, such or this about something other than the course). Used only to decide which sentences go together when a size-only reading is shortened.';



CREATE OR REPLACE FUNCTION "security"."cdesc_refers_within_v1"("p_text" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  -- fixed: a structural test of the grammar: the sentence says "these", "those", "such" (not "such as") or "this" (not "this course", "this program" and the
  -- like, which mean the course itself) anywhere in it. What it refers to may be any earlier sentence, not only the one before
  select coalesce(p_text, '') ~* '\m(these|those)\M|\msuch\s+(?!\s|as\M)|\mthis\s+(?!\s|(course|program|programme|qualification|degree|diploma|certificate|award|major|specialisation|specialization|master|bachelor|unit|subject)\M)'
$$;


ALTER FUNCTION "security"."cdesc_refers_within_v1"("p_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_refers_within_v1"("p_text" "text") IS 'Course description shortening: true when a sentence says these, those, such or this about something other than the course, anywhere in it. Used only to decide which sentences may be set aside when a size-only reading is shortened.';



CREATE OR REPLACE FUNCTION "security"."cdesc_scrub_sentence_v1"("p_text" "text", "p_quote" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare t text := coalesce(p_text, ''); w text;
begin
  -- "leading" as a verb or direction is not a ranking
  t := regexp_replace(t, '\mleading\s+(to|into|towards?|teams?|people|others|(a|the)\s+teams?|and\s+(managing|supervising|motivating))\M', ' ', 'gi');
  t := regexp_replace(t, '\mteam[- ]leading\M', ' ', 'gi');
  -- programme structure, not a claim: points, paper codes, levels, years of study
  t := regexp_replace(t, '\m[0-9]+(\s*-\s*|\s+)(credit\s+)?points?\M', ' ', 'gi');
  -- a paper code of 4 or 5 letters (CHHE 701) only in a sentence that names a paper, course, unit, subject or module and holds no money: never a currency code beside an amount (AUD 250)
  if t ~* '\m(papers?|courses?|units?|subjects?|modules?)\M'
     and t !~* '(\$|\m(fees?|costs?|costing|prices?|priced|tuition|dollars?|payable|charges?|scholarships?)\M|\m(aud|usd|nzd|eur|gbp|cad|sgd|cny|jpy|inr|hkd|chf)\s?[0-9])' then
    t := regexp_replace(t, '\m[A-Z]{4,5}\s?[0-9]{3}\M', ' ', 'g'); -- fixed: an ISO currency code is always 3 letters, so a paper code is 4 or 5 letters and a 3-letter prefix is never set aside
  end if;
  t := regexp_replace(t, '\m[0-9]{3}-level\M', ' ', 'gi');
  t := regexp_replace(t, '\m(year|level)\s+[0-9]\M', ' ', 'gi');
  -- a word the course may keep when the sentence's own on-page quote holds it
  for w in select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'enrich.course_description_supported_words'), '[]'::jsonb)) loop
    if w ~ '^[A-Za-z]+$' and security.pdesc_has_term_v1(p_quote, w) then t := regexp_replace(t, '\m' || w || '\M', ' ', 'gi'); end if;
  end loop;
  -- the learner word
  for w in select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'enrich.course_description_learner_words'), '[]'::jsonb)) loop
    if security.cdesc_learner_word_ok_v1(w, p_text, p_quote) then t := regexp_replace(t, '\m' || lower(w) || '\M', ' ', 'gi'); end if;
  end loop;
  return t;
end $_$;


ALTER FUNCTION "security"."cdesc_scrub_sentence_v1"("p_text" "text", "p_quote" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_scrub_sentence_v1"("p_text" "text", "p_quote" "text") IS 'CF-247 F-CDESC: the sentence with the parts that are not claims set aside before the shared wording policy reads it: leading as a verb (to / into / towards / teams / people / others / a team), programme structure (N points, 100-level, Year 1, and a paper code of 4 or 5 letters only in a sentence that names a paper, course, unit, subject or module with no money word, $ or currency code beside a number; a 3-letter prefix is never set aside), a supported word (enrich.course_description_supported_words) and the learner word. Used only to TEST the wording; the sentence that is stored and published is never changed. Read only.';



CREATE OR REPLACE FUNCTION "security"."cdesc_sentence_fault_v1"("p_text" "text", "p_quote" "text", "p_on_page" boolean, "p_claim" "jsonb", "p_mkt" "jsonb", "p_min_support" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare t text := btrim(coalesce(p_text, '')); v_sup numeric;
        v_run int := security.pipeline_num_v1('enrich.course_description_copy_run_words', 10)::int;
        v_gen jsonb := coalesce(security.toolset_setting('pipeline', 'enrich.course_description_generic_phrases'), '[]'::jsonb); v_sw text[]; v_qw text; i int;
begin
  -- the per-sentence tests of the course description check, in the order the check runs them; null when the sentence passes
  if coalesce(p_on_page, false) is false or nullif(btrim(coalesce(p_quote, '')), '') is null then
    return jsonb_build_object('rule', 'quote_not_on_page', 'reason', 'a sentence''s words are not on the course page: ' || left(t, 120));
  end if;
  if exists (select 1 from jsonb_array_elements_text(p_mkt) w where security.pdesc_has_term_v1(t, w) and not security.pdesc_has_term_v1(p_quote, w)) then
    return jsonb_build_object('rule', 'unsupported_marketing', 'reason', 'a marketing word that is not in the quote: ' || left(t, 120));
  end if;
  if exists (select 1 from jsonb_array_elements_text(p_claim) w where security.pdesc_has_term_v1(t, w) and not security.pdesc_has_term_v1(p_quote, w) and not security.cdesc_learner_word_ok_v1(w, t, p_quote)) then
    return jsonb_build_object('rule', 'unsupported_claim', 'reason', 'a ranking, outcome or accreditation claim that is not in the quote: ' || left(t, 120));
  end if;
  -- cdesc-source-grounded-v1 (CF-247 F-CDESC, 12 Nov 2026): a stock phrase that says nothing about this course is held, whatever the page says
  if exists (select 1 from jsonb_array_elements_text(v_gen) w where security.pdesc_has_term_v1(t, w)) then
    return jsonb_build_object('rule', 'generic_phrase', 'reason', 'a generic phrase that says nothing specific about this course: ' || left(t, 120));
  end if;
  -- a sentence that does not end as a sentence is a fragment: held, never cut or completed (Platform Admin 2 Nov 2026 23:24)
  if t !~ '[.!?]["'')\]’”]*$' or t ~ '(\.\.\.|…)["'')\]’”]*$' then
    return jsonb_build_object('rule', 'incomplete_sentence', 'reason', 'a sentence is not complete (it would be published as a fragment): ' || left(t, 120));
  end if;
  v_sup := security.pdesc_support_v1(t, p_quote);
  if v_sup < p_min_support then
    return jsonb_build_object('rule', 'unsupported_sentence', 'checks', jsonb_build_object('support', v_sup), 'reason', 'a sentence is not supported by its quote (' || v_sup || '): ' || left(t, 120));
  end if;
  -- cdesc-source-grounded-v1: a run of v_run words of the sentence, in order, in its source passage is the page's text, not an original description (0 = off)
  if v_run > 0 then
    v_sw := array(select w from regexp_split_to_table(lower(t), '[^a-z0-9]+') w where w <> '');
    v_qw := ' ' || array_to_string(array(select w from regexp_split_to_table(lower(coalesce(p_quote, '')), '[^a-z0-9]+') w where w <> ''), ' ') || ' ';
    for i in 1 .. coalesce(array_length(v_sw, 1), 0) - v_run + 1 loop
      if position(' ' || array_to_string(v_sw[i:i + v_run - 1], ' ') || ' ' in v_qw) > 0 then
        return jsonb_build_object('rule', 'copied_sentence', 'checks', jsonb_build_object('copy_run_words', v_run),
          'reason', 'a sentence repeats ' || v_run || ' or more words of the page in order (copied, not an original description): ' || left(t, 120));
      end if;
    end loop;
  end if;
  return null;
end $_$;


ALTER FUNCTION "security"."cdesc_sentence_fault_v1"("p_text" "text", "p_quote" "text", "p_on_page" boolean, "p_claim" "jsonb", "p_mkt" "jsonb", "p_min_support" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_sentence_fault_v1"("p_text" "text", "p_quote" "text", "p_on_page" boolean, "p_claim" "jsonb", "p_mkt" "jsonb", "p_min_support" numeric) IS 'CF-247 F-CDESC: the one definition of the per-sentence tests of the course description check (quote on the page, marketing word, claim word with the learner word, complete sentence, support by the quote). Returns null when the sentence passes, else {rule, reason, checks}. Used by security.course_description_check_with_v1 and by the subset recovery. Read only.';



CREATE OR REPLACE FUNCTION "security"."cdesc_sentence_substance_v1"("p_text" "text", "p_quote" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  -- fixed: words of four or more letters compared on their first five, the rule of security.pdesc_support_v1 (a count of supported words, not a share)
  select count(*)::int from (select distinct left(w, 5) w from regexp_split_to_table(lower(coalesce(p_text, '')), '[^a-z0-9]+') w where length(w) >= 4) s
   where s.w in (select left(q, 5) from regexp_split_to_table(lower(coalesce(p_quote, '')), '[^a-z0-9]+') q where length(q) >= 4)
$$;


ALTER FUNCTION "security"."cdesc_sentence_substance_v1"("p_text" "text", "p_quote" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_sentence_substance_v1"("p_text" "text", "p_quote" "text") IS 'Course description shortening: how many distinct words of a sentence (four or more letters, compared on their first five) are also in its own quote. Used only to choose which whole sentence is set aside when a reading is over its size limits.';



CREATE OR REPLACE FUNCTION "security"."cdesc_state_v1"("p_course_ids" "uuid"[], "p_provider" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("course_id" "uuid", "provider_id" "uuid", "title" "text", "provider" "text", "active" boolean, "has_description" boolean, "state" "text", "source_ready" boolean, "source_reason" "text", "source_url" "text", "evidence_id" "uuid", "page_read_at" timestamp with time zone, "page_next_read_at" timestamp with time zone, "last_item_id" bigint, "last_state" "text", "last_reason" "text", "last_attempt_at" timestamp with time zone, "last_job_id" "uuid", "held_kind" "text", "locked" boolean, "hidden" boolean, "waiting_for_person" boolean, "rejected_same_evidence" boolean, "machine_admitted" boolean, "human_decision" boolean, "next_retry_at" timestamp with time zone, "fill_block" "text", "recheck_block" "text", "release_flag_ids" bigint[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with p as (select security.pipeline_num_v1('gaps.recheck_days', 60)::int days, security.cdesc_machine_ids_v1(p_course_ids) mach),
  c as (
    select co.id, co.provider_id, co.canonical_title ttl, co.lifecycle_status = 'active' act, nullif(btrim(co.description), '') is not null has_d
      from catalogue.courses co
     where (p_course_ids is not null and co.id = any (p_course_ids))
        or (p_provider is not null and co.provider_id = p_provider and co.lifecycle_status = 'active' and nullif(btrim(co.description), '') is null)),
  pg as (select g.course_id, g.url, g.status, g.read_status, g.identity_basis, g.evidence_id, g.read_at, g.next_read_at
           from pipeline.coverage_course_pages g where g.course_id in (select c0.id from c c0)),
  li as (select distinct on (e.course_id) e.course_id, e.id, e.state, e.reason, e.updated_at, e.evidence_id, e.job_id
           from pipeline.field_enrich_items e where e.field = 'description' and e.course_id in (select c0.id from c c0) order by e.course_id, e.id desc),
  fl as (select f.entity_key::uuid course_id,
                bool_or(f.state = 'raised' and f.reason_code = 'manual_hold') manual,
                bool_or(f.state = 'raised' and f.reason_code in ('enrich_no_value', 'manual_hold')) raised,
                -- the standing queue's wait (security.enrich_item_held_v1): a counting flag younger than gaps.recheck_days, unless the page was read again with new content since
                bool_or(f.state = 'counting' and f.reason_code = 'enrich_no_value' and f.flagged_at > now() - make_interval(days => p.days)
                        and not (pg0.evidence_id is not null and pg0.evidence_id::text is distinct from f.input_mark and pg0.read_at > f.flagged_at)) counting_any,
                array_agg(f.id) filter (where f.state = 'counting' and f.reason_code = 'enrich_no_value') counting_ids
           from pipeline.enrichment_flags f cross join p left join pg pg0 on pg0.course_id::text = f.entity_key
          where f.entity = 'course' and f.field in ('description', '') and f.entity_key in (select c0.id::text from c c0) group by f.entity_key),
  l4 as (select r.entity_id course_id, bool_or(r.status = 'pending') pending, bool_or(r.status in ('approved', 'edited_approved')) approved,
                array_agg(r.evidence_id) filter (where r.status = 'rejected' and r.evidence_id is not null) rejected_ev
           from pipeline.layer4_review_items r
          where r.entity_type = 'course' and r.field_code = 'course_description_first_read' and r.entity_id in (select c0.id from c c0) group by r.entity_id)
  select c.id, c.provider_id, c.ttl, coalesce(pr.display_name, pr.canonical_name), c.act, c.has_d, h.state,
         q.sr, q.sreason, pg.url, pg.evidence_id, pg.read_at, pg.next_read_at,
         li.id, li.state, li.reason, li.updated_at, li.job_id,
         case when coalesce(fl.manual, false) then 'manual_hold' when coalesce(fl.raised, false) then 'raised' when coalesce(fl.counting_any, false) then 'counting'
              when li.reason like 'held\_first\_admission%' then 'held_first_admission' when li.reason like 'held:%' then 'check' end,
         q.lk, q.hd, b.wait_person, b.rej, case when p.mach is null then null else c.id = any (p.mach) end, coalesce(l4.approved, false),
         case when c.has_d or not c.act or q.hd then null
              when not q.sr then pg.next_read_at
              when li.id is null or pg.read_at > li.updated_at then null
              else li.updated_at + make_interval(days => p.days) end,
         coalesce(b.cb, case when li.id is not null and not (li.state = 'filled' or li.reason = 'provider unpublished' or li.updated_at < now() - make_interval(days => p.days) or pg.read_at > li.updated_at)
                             then 'recent_attempt' when coalesce(fl.counting_any, false) then 'recent_attempt' end),
         coalesce(b.cb, case when li.state in ('skipped', 'failed') then null else 'nothing_to_recheck' end),
         fl.counting_ids
    from c cross join p
    left join catalogue.providers pr on pr.id = c.provider_id
    left join pg on pg.course_id = c.id left join li on li.course_id = c.id left join fl on fl.course_id = c.id left join l4 on l4.course_id = c.id
    cross join lateral (select exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = c.id and k.field in ('description', 'course_description', 'all')) lk,
                               exists (select 1 from security.provider_hidden_v1 hh where hh.provider_id = c.provider_id) hd,
                               -- the standing queue's source rule (bound, or ambiguous with an identity proof, read, evidence) and the country rule the record step applies
                               (pg.course_id is not null and pg.evidence_id is not null and pg.status in ('bound', 'ambiguous') and pg.read_status = 'read' and pg.identity_basis is not null
                                and security.coverage_identity_allowed(c.provider_id, pg.identity_basis, 'description')) sr,
                               case when pg.course_id is null then 'no_page' when pg.status = 'mismatch' then 'page_mismatch' when pg.status not in ('bound', 'ambiguous') then 'page_not_bound'
                                    when pg.read_status is distinct from 'read' then 'page_not_read' when pg.evidence_id is null then 'no_evidence' when pg.identity_basis is null then 'no_identity_proof'
                                    when not security.coverage_identity_allowed(c.provider_id, pg.identity_basis, 'description') then 'identity_not_admitted' end sreason) q
    cross join lateral (select (li.state = 'review' or coalesce(l4.pending, false)) wait_person,
                               (l4.rejected_ev is not null and pg.evidence_id = any (l4.rejected_ev)) rej) b0
    cross join lateral (select b0.wait_person, coalesce(b0.rej, false) rej,
                               case when not c.act then 'not_active' when c.has_d then 'already_has_description' when q.lk then 'locked' when q.hd then 'provider_hidden' when not q.sr then 'no_source'
                                    when b0.wait_person then 'waiting_for_person' when li.state in ('queued', 'waiting', 'ai', 'leased') then 'in_flight'
                                    when coalesce(b0.rej, false) then 'rejected_same_evidence' when coalesce(fl.raised, false) then 'held_for_person'
                                    when li.reason like 'held\_first\_admission%' then 'held_first_admission'
                                    when (li.state = 'skipped' and li.evidence_id is not distinct from pg.evidence_id
                                          and li.reason in ('the page does not state it', 'the same page copy was read for this before and did not state it'))
                                         or security.field_absence_unchanged_v1(c.id, 'description', pg.evidence_id) then 'same_page_not_stated' end cb) b
    cross join lateral (select case when c.has_d then (case when p.mach is not null and c.id = any (p.mach) then 'machine_admitted' when coalesce(l4.approved, false) then 'human_decision' else 'present' end)
                                    when not c.act then 'inactive' when q.lk then 'locked' when b0.wait_person then 'ai_read' when li.state in ('queued', 'waiting', 'ai', 'leased') then 'queued'
                                    when not q.sr then 'missing' when li.state = 'failed' then 'failed'
                                    when li.state = 'skipped' and li.reason in ('the page does not state it', 'the same page copy was read for this before and did not state it') then 'not_stated'
                                    when li.state = 'skipped' then 'held' else 'source_ready' end state) h;
$$;


ALTER FUNCTION "security"."cdesc_state_v1"("p_course_ids" "uuid"[], "p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_state_v1"("p_course_ids" "uuid"[], "p_provider" "uuid") IS 'CF-247 F-CDESC.06: where each course''s description stands (page, last Enrich fields item, flags, locks, Layer 4, machine ledger) and why Fill and Recheck would leave it out. Read only.';



CREATE OR REPLACE FUNCTION "security"."cdesc_subset_plan_v1"("p_course" "uuid", "p_provider" "uuid", "p_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_s jsonb := coalesce(p_value->'sentences', '[]'::jsonb); n int; i int; s jsonb; f jsonb; t text; v_pol text;
        v_min int := greatest(1, security.pipeline_num_v1('enrich.course_description_min_sentences', 1)::int); v_max int := security.pipeline_num_v1('enrich.course_description_max_sentences', 4)::int;
        v_maxc int := security.pipeline_num_v1('enrich.course_description_max_chars', 700)::int; v_sup numeric := security.pipeline_num_v1('pdesc.support_min_share', 0.6);
        v_claim jsonb := coalesce(security.toolset_setting('pipeline', 'enrich.course_description_claim_words'), security.toolset_setting('pipeline', 'pdesc.claim_words'), '[]'::jsonb);
        v_mkt jsonb := coalesce(security.toolset_setting('pipeline', 'enrich.course_description_marketing_words'), security.toolset_setting('pipeline', 'pdesc.superlatives'), '[]'::jsonb);
        v_fault text[]; v_kept int[] := '{}'; v_drop jsonb := '[]'::jsonb; v_len int := 0; v_add int; v_over boolean; v_sents jsonb := '[]'::jsonb; v_chk jsonb; v_orig text; v_page text; v_title text; v_prov text; v_cnt int; v_tot int; v_first int; v_victim int; v_c int; v_bc int; v_p boolean; v_bp boolean; v_rc int; v_rl int; v_f boolean; v_bf boolean;
begin
  if jsonb_typeof(v_s) is distinct from 'array' or jsonb_array_length(v_s) = 0 then return jsonb_build_object('ok', false, 'rule', 'no_sentences', 'reason', 'the reading holds no sentences'); end if;
  n := jsonb_array_length(v_s); v_fault := array_fill(null::text, array[n]);
  -- 0. the bound page must be a page about this course (an institution-level About page never stands in for it)
  select coalesce(security.cdesc_page_kind_v1(g.url, c.canonical_title, g.identity_basis), 'ok') into v_page from pipeline.coverage_course_pages g join catalogue.courses c on c.id = g.course_id where g.course_id = p_course limit 1;
  if not found then v_page := 'no_bound_page'; end if; -- fails closed: no bound page row is no proof of the page
  if v_page <> 'ok' then return jsonb_build_object('ok', false, 'rule', v_page, 'reason', 'the bound page is not a page about this course (' || v_page || ')'); end if;
  -- 1. the sentences that fail a per-sentence test or the machine wording policy. The course's own title and provider are left out of a sentence's tests, exactly as the check does
  --    (security.course_description_check_with_v1), so a sentence the check would refuse is set aside here and not carried into the remainder
  select c.canonical_title, coalesce(p.display_name, p.canonical_name) into v_title, v_prov from catalogue.courses c left join catalogue.providers p on p.id = c.provider_id where c.id = p_course;
  for i in 1 .. n loop
    s := v_s->(i - 1);
    f := security.cdesc_sentence_fault_v1(security.cdesc_known_strip_v1(s->>'text', v_title, v_prov), s->>'quote', coalesce((s->>'on_page')::boolean, false), v_claim, v_mkt, v_sup);
    -- a ten-word run of the page is copied wording whether or not it runs through the course's title: the copy test is also run on the sentence as written
    if f is null then
      f := security.cdesc_sentence_fault_v1(s->>'text', s->>'quote', coalesce((s->>'on_page')::boolean, false), v_claim, v_mkt, v_sup);
      if f->>'rule' is distinct from 'copied_sentence' then f := null; end if;
    end if;
    if f is not null then v_fault[i] := f->>'rule';
    else
      v_pol := security.cdesc_machine_text_check_v1(p_provider, s->>'text', jsonb_build_array(s));
      if v_pol is not null then v_fault[i] := 'policy_' || split_part(v_pol, ':', 1); end if;
    end if;
  end loop;
  -- 1b. a passing sentence that opens by pointing back to the sentence before it, which is set aside, is set aside with it (it would be published as a fragment of it).
  --     In order, so a chain is followed. Only sentences are removed: what is kept is unchanged and goes through the same full check below
  for i in 2 .. n loop
    if v_fault[i] is null and v_fault[i - 1] is not null and security.cdesc_points_back_v1(v_s->(i - 1)->>'text') then v_fault[i] := 'depends_on_dropped_sentence'; end if;
  end loop;
  -- 1c. (Platform Admin 13 Nov 2026 12:16, conditional approval) a reading whose ONLY fault is its size (no sentence failed a test) and that is over the sentence or
  --     character limit is shortened by whole sentences, never inside one. Each pass looks at every kept sentence but the first (it says what the course is) together
  --     with the sentences after it that refer back to it (security.cdesc_refers_back_v1: they would dangle, so they go with it), and sets aside the choice that
  --     (a) by itself brings the reading within the limits, before one that does not, then (b) loses least course-specific substance
  --     (security.cdesc_sentence_substance_v1), the later sentence on a tie. A choice that would remove a sentence about a qualification, registration, recognition,
  --     pathway, placement or entry condition is never taken, nor one that a later kept sentence may refer to (security.cdesc_refers_within_v1): if only such
  --     choices are left, nothing more is set aside and the reading stays held below.
  --     Repeated until the reading fits. A reading that cannot fit stays held. A reading with a failing sentence AND a size problem is outside the approval:
  --     it is not shortened here and stays held (over_length_needs_decision).
  if not exists (select 1 from unnest(v_fault) x(f) where x.f is not null) then
    loop
      select count(*), coalesce(sum(length(btrim(coalesce(v_s->(k - 1)->>'text', '')))), 0) + greatest(count(*) - 1, 0), min(k) into v_cnt, v_tot, v_first from generate_series(1, n) k where v_fault[k] is null;
      exit when v_cnt <= 1 or (v_cnt <= v_max and v_tot <= v_maxc);
      v_victim := null;
      for k in reverse n .. v_first + 1 loop
        continue when v_fault[k] is not null;
        v_c := 0; v_p := false; v_rc := 0; v_rl := 0; i := k;
        loop
          v_c := v_c + security.cdesc_sentence_substance_v1(v_s->(i - 1)->>'text', v_s->(i - 1)->>'quote');
          v_rc := v_rc + 1; v_rl := v_rl + length(btrim(coalesce(v_s->(i - 1)->>'text', ''))) + 1;
          -- fixed: a structural test of what a sentence is about (a qualification, registration, recognition, pathway, placement or entry condition), not a tunable limit
          v_p := v_p or coalesce(v_s->(i - 1)->>'text', '') ~* '\m(regist|licen|qualif|recogni|endors|certif|accredit|pathway|eligib|pre-?requisit|placement|practicum|internship|admission|entry requirement|must (hold|have|be|complete))';
          i := i + 1;
          exit when i > n or v_fault[i] is not null or not security.cdesc_refers_back_v1(v_s->(i - 1)->>'text');
        end loop;
        -- a later sentence that stays and says "these", "those", "such" or "this" may refer to this choice: the choice is then not taken (as a protected one)
        v_p := v_p or exists (select 1 from generate_series(i, n) j where v_fault[j] is null and security.cdesc_refers_within_v1(v_s->(j - 1)->>'text'));
        -- does the reading still not fit once this choice is set aside
        v_f := not (v_cnt - v_rc <= v_max and v_tot - v_rl <= v_maxc);
        if v_victim is null or (v_p, v_f, v_c) < (v_bp, v_bf, v_bc) then v_victim := k; v_bp := v_p; v_bf := v_f; v_bc := v_c; end if;
      end loop;
      -- only protected choices are left: nothing more is set aside, the reading stays held
      exit when v_victim is null or v_bp;
      v_fault[v_victim] := 'over_limit';
      for i in v_victim + 1 .. n loop
        exit when v_fault[i] is not null or not security.cdesc_refers_back_v1(v_s->(i - 1)->>'text');
        v_fault[i] := 'depends_on_dropped_sentence';
      end loop;
    end loop;
  end if;
  -- 2. every sentence that passes and was not set aside for size is kept, in its original order. No sentence is ever cut inside: a reading that cannot be brought within the limits by whole sentences stays held
  for i in 1 .. n loop
    s := v_s->(i - 1); t := btrim(coalesce(s->>'text', ''));
    if v_fault[i] is not null then v_drop := v_drop || jsonb_build_object('index', i, 'text', t, 'cause', v_fault[i]); continue; end if;
    v_add := length(t) + case when cardinality(v_kept) > 0 then 1 else 0 end;
    v_kept := v_kept || i; v_len := v_len + v_add; v_sents := v_sents || s;
  end loop;
  v_over := cardinality(v_kept) > v_max or v_len > v_maxc;
  if jsonb_array_length(v_drop) = 0 then
    if v_over then return jsonb_build_object('ok', false, 'rule', 'over_length_needs_decision', 'reason', 'every sentence passes; the reading is over the set sentence or character limit and cannot be brought within it by setting whole sentences aside without losing a protected sentence; it is held whole'); end if;
    return jsonb_build_object('ok', false, 'rule', 'nothing_to_drop', 'reason', 'every sentence passes: dropping sentences cannot change the outcome');
  end if;
  if cardinality(v_kept) < v_min then return jsonb_build_object('ok', false, 'rule', 'remainder_below_minimum', 'reason', cardinality(v_kept) || ' sentence(s) are left, fewer than the set minimum', 'dropped', v_drop); end if;
  -- 2a. (13 Nov 2026, read of 20 recovered descriptions) the opening sentence says what the course is. A remainder without it reads as a fragment
  --     ("Assessment includes written tasks ..."), so a reading whose first sentence was set aside is not recovered: it stays held
  if not (1 = any (v_kept)) then return jsonb_build_object('ok', false, 'rule', 'opening_sentence_dropped', 'reason', 'the opening sentence, which says what the course is, was set aside; what is left would read as a fragment, so the reading is held whole', 'dropped', v_drop); end if;
  if v_over then return jsonb_build_object('ok', false, 'rule', 'over_length_needs_decision', 'reason', 'the reading is still over the set sentence or character limit (a reading with a failing sentence is not shortened; a size-only reading could not be brought within it by whole sentences); it is held whole', 'dropped', v_drop); end if;
  -- 3. a kept sentence that points back to the sentence before it, which was set aside for a fault, would be published as a fragment of it (the opener list is wider than pronouns: QA, 10 Nov 2026)
  for i in 2 .. n loop
    continue when not (i = any (v_kept)) or v_fault[i - 1] is null;
    -- fixed: a structural test of the grammar (a sentence that opens with a pronoun, a connecting word, "the program" or a quote or bracket), not a tunable limit
    if security.cdesc_points_back_v1(v_s->(i - 1)->>'text') then
      return jsonb_build_object('ok', false, 'rule', 'depends_on_dropped_sentence', 'reason', 'sentence ' || i || ' opens by pointing back to sentence ' || (i - 1) || ', which is set aside', 'dropped', v_drop);
    end if;
  end loop;
  -- 4. the remainder goes through the SAME full check and the machine wording policy
  v_chk := security.course_description_check_v1(p_course, p_value || jsonb_build_object('sentences', v_sents));
  if not coalesce((v_chk->>'ok')::boolean, false) then return jsonb_build_object('ok', false, 'rule', 'remainder_' || coalesce(v_chk->>'rule', 'failed'), 'reason', v_chk->>'reason', 'dropped', v_drop); end if;
  v_pol := security.cdesc_machine_text_check_v1(p_provider, v_chk->>'text', v_sents);
  if v_pol is not null then return jsonb_build_object('ok', false, 'rule', 'remainder_policy_' || split_part(v_pol, ':', 1), 'reason', v_pol, 'dropped', v_drop); end if;
  select string_agg(btrim(x->>'text'), ' ' order by o) into v_orig from jsonb_array_elements(v_s) with ordinality e(x, o);
  return jsonb_build_object('ok', true, 'text', v_chk->>'text', 'sentences', v_sents, 'check', v_chk,
    'subset', jsonb_build_object('rule', 'subset_of_reading', 'original_count', n, 'kept_count', cardinality(v_kept), 'kept', to_jsonb(v_kept), 'dropped', v_drop,
                                 'original', jsonb_build_object('sentences', v_s, 'text', v_orig, 'check', p_value->'check')));
end $$;


ALTER FUNCTION "security"."cdesc_subset_plan_v1"("p_course" "uuid", "p_provider" "uuid", "p_value" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_subset_plan_v1"("p_course" "uuid", "p_provider" "uuid", "p_value" "jsonb") IS 'CF-247 F-CDESC: the deterministic subtractive plan for a course description reading. Only the sentences that fail a per-sentence test (security.cdesc_sentence_fault_v1) or the machine wording policy are set aside; every other sentence is kept in its original order; nothing is reworded, added or cut, and nothing is dropped for length (a reading over the limits stays held: over_length_needs_decision). A kept sentence that opens by pointing back to a set-aside sentence is not used. The remainder must pass the same full check (security.course_description_check_v1) and the wording policy. Returns {ok, text, sentences, check, subset} or {ok false, rule, reason}. Read only.';



CREATE OR REPLACE FUNCTION "security"."cdesc_subset_recover_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare r record; v_stamp text := security.course_description_machine_policy_stamp_v1(); v_cap int := security.pipeline_num_v1('enrich.course_text_items_per_day', 500)::int; -- derived: never more in a run than the platform reads in a day (as the replay)
        v_days int := security.pipeline_num_v1('gaps.recheck_days', 60)::int; v_t0 timestamptz := clock_timestamp(); v_dl timestamptz; v_dl_a timestamptz; v_tb boolean := false; v_prov jsonb; v_plan jsonb; v_sub jsonb; v_val jsonb; v_res text; v_why text; v_msg text; v_adm jsonb; v_slots jsonb := '{}'::jsonb; v_n int;
        v_looked int := 0; v_rec_a int := 0; v_rec_b int := 0; v_by jsonb := '{}'::jsonb; v_no jsonb := '{}'::jsonb; v_full int := 0; v_item uuid;
begin
  if security.pipeline_num_v1('enrich.course_description_machine_on', 0) < 1 then return jsonb_build_object('on', false); end if;
  -- fixed: the whole subset step ends 45 s after it began or 60 s after the job began, whichever comes first (13 Nov 2026: the job now runs every two minutes and a recovered reading is admitted inside this step, so the step has the larger share; the settle after it still stops 85 s into the job, inside the 120 s statement time-out)
  v_dl := least(v_t0 + make_interval(secs => 45), statement_timestamp() + make_interval(secs => 60));
  -- fixed: part (a) may use 60 % of that time box, so part (b) is never starved behind it (what part (a) leaves is part (b)'s)
  v_dl_a := v_t0 + (v_dl - v_t0) * 0.6;
  -- (a) a reading held by the reader's own check: the latest reading of an active course that has no description
  for r in select e.id, e.course_id, e.value, e.quote, c.provider_id, btrim(split_part(e.reason, ':', 2)) cause
             from pipeline.field_enrich_items e join catalogue.courses c on c.id = e.course_id
            where e.field = 'description' and e.state = 'skipped' and e.reason ~ '^held: (sentence_count|length|unsupported_claim|quote_not_on_page|unsupported_sentence|unsupported_marketing|incomplete_sentence|copied_sentence|generic_phrase):'
              and jsonb_typeof(e.value->'sentences') = 'array' and c.lifecycle_status = 'active' and nullif(btrim(c.description), '') is null
              and e.updated_at > now() - make_interval(days => v_days)
              and e.id = (select max(x.id) from pipeline.field_enrich_items x where x.course_id = e.course_id and x.field = 'description')
              and coalesce(e.value->'subset_attempt'->>'stamp', '') <> v_stamp
            order by e.id limit v_cap loop
    if clock_timestamp() > v_dl_a then v_tb := true; exit; end if;
    v_looked := v_looked + 1; v_why := null; v_sub := null;
    -- the provider's places (enrich.course_description_pending_max): a provider whose places are all taken is left for a later run (nothing is written, so it is not marked)
    if not v_slots ? r.provider_id::text then v_slots := v_slots || jsonb_build_object(r.provider_id::text, security.cdesc_provider_slots_v1(r.provider_id)); end if;
    if (v_slots->>r.provider_id::text)::int <= 0 then v_full := v_full + 1; continue; end if;
    if security.course_description_trusted_v1(r.provider_id) then continue; end if; -- a provider whose first descriptions a person approved is written by the existing trusted route, not by the machine rule
    begin
      v_prov := security.cdesc_reading_provenance_v1(r.id, r.value);
      if nullif(v_prov->>'model', '') is null or nullif(v_prov->>'prompt', '') is null then v_why := 'reader_unrecorded';
      else
        v_plan := security.cdesc_subset_plan_v1(r.course_id, r.provider_id, r.value);
        if not coalesce((v_plan->>'ok')::boolean, false) then v_why := coalesce(v_plan->>'rule', 'plan_failed');
        else
          v_sub := (v_plan->'subset') || jsonb_build_object('cause', r.cause, 'stamp', v_stamp, 'at', now());
          begin
            v_val := (r.value - 'subset_attempt' - 'check') || jsonb_build_object('sentences', v_plan->'sentences', 'subset_of_reading', v_sub);
            v_res := security.enrich_course_text_record_v1(r.id, jsonb_build_object('value', v_val, 'quote', r.quote, 'model', v_prov->>'model', 'prompt_version', v_prov->>'prompt', 'worker', v_prov->>'worker'));
            if v_res is distinct from 'review' then raise exception 'cdesc_subset:record_%', coalesce(v_res, 'nothing'); end if;
            -- recording the waiting item runs the machine rule on it (the trigger of the reading); the subset stands only if that admitted it
            if not exists (select 1 from catalogue.courses c where c.id = r.course_id and c.description = v_plan->>'text') then
              select a.reason_code into v_why from pipeline.course_description_machine_admissions a
               where a.review_item_id = (select (f.value->>'review_item_id')::uuid from pipeline.field_enrich_items f where f.id = r.id) and a.outcome = 'declined' order by a.id desc limit 1;
              raise exception 'cdesc_subset:machine_%', coalesce(v_why, 'not_admitted');
            end if;
            v_rec_a := v_rec_a + 1; v_by := jsonb_set(v_by, array[r.cause], to_jsonb(coalesce((v_by->>r.cause)::int, 0) + 1)); v_why := 'recovered';
          exception when others then
            get stacked diagnostics v_msg = message_text;
            v_why := case when v_msg like 'cdesc_subset:%' then substr(v_msg, length('cdesc_subset:') + 1) else 'error' end; -- the sub-transaction is rolled back: nothing of the attempt stays
          end;
        end if;
      end if;
    exception when others then v_why := 'error';
    end;
    if v_why is distinct from 'recovered' then
      v_no := jsonb_set(v_no, array[v_why], to_jsonb(coalesce((v_no->>v_why)::int, 0) + 1));
      update pipeline.field_enrich_items set value = value || jsonb_build_object('subset_attempt', jsonb_build_object('stamp', v_stamp, 'result', v_why, 'at', now())) where id = r.id and state = 'skipped'; -- noted for this policy stamp; updated_at stays, so the queue's own timing is not moved
    end if;
  end loop;
  -- (b) a waiting first description that the machine declined for its wording (or a check that changed): the item and its reading are rewritten to the subset, and the machine rule decides
  for r in select i.id item_id, i.entity_id course_id, c.provider_id, f.id rid, f.value, d.reason_code cause, i.proposed_value
             from pipeline.layer4_review_items i
             join catalogue.courses c on c.id = i.entity_id and c.lifecycle_status = 'active' and nullif(btrim(c.description), '') is null
             join pipeline.course_description_machine_admissions d on d.review_item_id = i.id and d.outcome = 'declined' and d.withdrawn_at is null and not d.transient and d.policy_stamp = v_stamp
                  and (d.reason_code like 'policy\_%' or d.reason_code like 'check\_%') and d.reason_code not in ('check_duplicate_other_course', 'check_not_stated')
             join pipeline.field_enrich_items f on f.id = case when coalesce(i.proposed_value->>'item_id', '') ~ '^\d+$' then (i.proposed_value->>'item_id')::bigint end and f.state = 'review' and f.course_id = i.entity_id
            where i.entity_type = 'course' and i.field_code = 'course_description_first_read' and i.status = 'pending' and jsonb_typeof(f.value->'sentences') = 'array'
              and coalesce(f.value->'subset_attempt'->>'stamp', '') <> v_stamp
            order by i.created_at, i.id limit v_cap loop
    if clock_timestamp() > v_dl then v_tb := true; exit; end if;
    v_looked := v_looked + 1; v_why := null;
    begin
      v_plan := security.cdesc_subset_plan_v1(r.course_id, r.provider_id, r.value);
      if not coalesce((v_plan->>'ok')::boolean, false) then v_why := coalesce(v_plan->>'rule', 'plan_failed');
      else
        v_sub := (v_plan->'subset') || jsonb_build_object('cause', r.cause, 'stamp', v_stamp, 'at', now());
        begin
          update pipeline.field_enrich_items set value = (value - 'subset_attempt') || jsonb_build_object('sentences', v_plan->'sentences', 'text', v_plan->>'text', 'check', v_plan->'check', 'subset_of_reading', v_sub) where id = r.rid and state = 'review';
          update pipeline.layer4_review_items set proposed_value = proposed_value || jsonb_build_object('description', v_plan->>'text', 'checks', v_plan->'check'->'checks',
                   'sentences', (select jsonb_agg(jsonb_build_object('text', x->>'text', 'quote', x->>'quote') order by o) from jsonb_array_elements(v_plan->'sentences') with ordinality e(x, o)),
                   'subset_of_reading', (v_sub - 'original') || jsonb_build_object('original_proposal', jsonb_build_object('description', r.proposed_value->>'description', 'sentences', r.proposed_value->'sentences')))
           where id = r.item_id and status = 'pending';
          v_adm := security.course_description_machine_admit_v1(r.item_id, 'subset_of_reading');
          if not coalesce((v_adm->>'ok')::boolean, false) then raise exception 'cdesc_subset:machine_%', coalesce(v_adm->>'rule', 'not_admitted'); end if;
          v_rec_b := v_rec_b + 1; v_by := jsonb_set(v_by, array[r.cause], to_jsonb(coalesce((v_by->>r.cause)::int, 0) + 1)); v_why := 'recovered';
        exception when others then
          get stacked diagnostics v_msg = message_text;
          v_why := case when v_msg like 'cdesc_subset:%' then substr(v_msg, length('cdesc_subset:') + 1) else 'error' end; -- rolled back: the item and its reading are as they were
        end;
      end if;
    exception when others then v_why := 'error';
    end;
    if v_why is distinct from 'recovered' then
      v_no := jsonb_set(v_no, array[v_why], to_jsonb(coalesce((v_no->>v_why)::int, 0) + 1));
      update pipeline.field_enrich_items set value = value || jsonb_build_object('subset_attempt', jsonb_build_object('stamp', v_stamp, 'result', v_why, 'at', now())) where id = r.rid and state = 'review';
    end if;
  end loop;
  return jsonb_build_object('on', true, 'looked_at', v_looked, 'recovered_held_readings', v_rec_a, 'recovered_waiting_items', v_rec_b, 'recovered_by_cause', v_by, 'not_recovered_by_reason', v_no, 'provider_places_full', v_full, 'time_box_reached', v_tb);
end $_$;


ALTER FUNCTION "security"."cdesc_subset_recover_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cdesc_subset_recover_v1"() IS 'Course descriptions: recovers a reading stuck on a few sentences by setting those sentences aside (a size-only reading is shortened by whole sentences under security.cdesc_subset_plan_v1 step 1c; no sentence is ever cut inside) and passing the rest to the same check and machine rule. Looks at readings held by the reader''s check (including copied_sentence and generic_phrase) and at waiting items the machine declined for wording. Time box 45 s, ending 60 s into the job.';



CREATE OR REPLACE FUNCTION "security"."central_ai_enqueue_v1"("p_provider" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int;
begin
  if not coalesce((select s.enabled from pipeline.central_ai_settings s where s.id = 1), false) then return 0; end if;
  insert into pipeline.central_ai_queue(fact_source_id, provider_id, kind, content_hash)
  select f.id, f.provider_id, f.kind, f.content_hash from pipeline.provider_fact_sources f
    join pipeline.evidence_artifacts e on e.id = f.evidence_id and e.storage_path is not null
   where f.provider_id = p_provider and f.kind in ('english_policy', 'intake_calendar') and f.status in ('read', 'parsed', 'no_values')
     and (f.kind <> 'english_policy' or security.english_provider_in_scope_v1(f.provider_id))  -- CF-247 6 Nov 2026 (decision D1): English pages only for the provider types in scope
     and not exists (select 1 from pipeline.provider_policy_proposals pp where pp.fact_source_id = f.id and pp.status in ('proposed', 'approved'))
     and not exists (select 1 from pipeline.central_ai_queue q where q.fact_source_id = f.id and (q.state in ('queued', 'leased') or q.content_hash is not distinct from f.content_hash))
  on conflict do nothing;
  get diagnostics v_n = row_count;
  return v_n;
end $$;


ALTER FUNCTION "security"."central_ai_enqueue_v1"("p_provider" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."central_ai_fire_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_open int; v_max int; v_due int; v_sent int := 0;
begin
  -- v2.15.258: in Stop at limits, not past the daily guard or below the credit floor
  if not security.ai_use_allowed_v1('central_ai') then return 0; end if;
  select calls_at_once into v_max from pipeline.central_ai_settings where id = 1 and enabled;
  select count(*) into v_due from pipeline.central_ai_queue q where (q.state = 'queued' or (q.state = 'leased' and q.leased_until < now())) and q.attempts < 3;
  if v_due = 0 or coalesce(v_max, 0) = 0 then return 0; end if;
  select count(*) into v_open from pipeline.edge_request_log l where l.function_name = 'coverage-sweep' and l.mode = 'central_ai' and l.created_at > now() - interval '3 minutes'
     and not exists (select 1 from net._http_response r where r.id = l.request_id);
  while v_open + v_sent < v_max and v_sent * 6 < v_due loop
    perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'central_ai', 'limit', 6));
    v_sent := v_sent + 1;
  end loop;
  return v_sent;
end $$;


ALTER FUNCTION "security"."central_ai_fire_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."central_pages_attach_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_att int := 0; v_q int := 0; v_re int := 0; v_ns int := 0; v_max int := security.pipeline_num_v1('central.attach_per_kind', 3)::int; r record;
begin
  -- a university with no approved English rule gets its best suggested central English page not yet tried
  insert into pipeline.provider_fact_sources(provider_id, kind, url, title, rank, found_via, status)
  select x.provider_id, 'english_policy', x.url, left(x.title, 200), 5, 'search', 'found'
    from (select s.provider_id, e->>'url' url, e->>'title' title,
                 row_number() over (partition by s.provider_id order by (e->>'score')::numeric desc) rn
            from pipeline.provider_central_search s cross join lateral jsonb_array_elements(coalesce(s.found, '[]'::jsonb)) e
           where e->>'kind' = 'english_policy' and coalesce((e->>'score')::numeric, 0) >= security.pipeline_num_v1('central.min_suggest_score', 4)
             and e->>'url' ~ '^https?://'
             and not exists (select 1 from pipeline.provider_fact_sources f where f.provider_id = s.provider_id and f.kind = 'english_policy' and f.url = e->>'url')) x
   where x.rn = 1
     and not exists (select 1 from pipeline.provider_policy_proposals pp where pp.provider_id = x.provider_id and pp.kind = 'english_policy' and pp.status in ('approved', 'proposed'))
     and not exists (select 1 from pipeline.provider_fact_sources f where f.provider_id = x.provider_id and f.kind = 'english_policy' and f.status in ('found', 'reading'))
     and (select count(*) from pipeline.provider_fact_sources f where f.provider_id = x.provider_id and f.kind = 'english_policy') < v_max
     and exists (select 1 from catalogue.courses c where c.provider_id = x.provider_id and c.lifecycle_status = 'active')
     and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = x.provider_id)
     and security.english_provider_in_scope_v1(x.provider_id)  -- CF-247 6 Nov 2026 (decision D1): central.english_provider_types, shipped with today's scope (every type)
  on conflict (provider_id, kind, url) do nothing;
  get diagnostics v_att = row_count;
  -- a university with no approved rule and no suggested central English page left is searched again (job central-find)
  update pipeline.provider_central_search s set state = 'queued', attempts = 0, leased_until = null, updated_at = now()
   where s.provider_id in (
     select s2.provider_id from pipeline.provider_central_search s2
      where s2.state in ('done', 'failed') and s2.updated_at < now() - make_interval(days => security.pipeline_num_v1('central.research_days', 7)::int)
        and not exists (select 1 from pipeline.provider_policy_proposals pp where pp.provider_id = s2.provider_id and pp.kind = 'english_policy' and pp.status in ('approved', 'proposed'))
        and not exists (select 1 from jsonb_array_elements(coalesce(s2.found, '[]'::jsonb)) e
                         where e->>'kind' = 'english_policy' and coalesce((e->>'score')::numeric, 0) >= security.pipeline_num_v1('central.min_suggest_score', 4)
                           and not exists (select 1 from pipeline.provider_fact_sources f where f.provider_id = s2.provider_id and f.kind = 'english_policy' and f.url = e->>'url'))
        and not exists (select 1 from pipeline.provider_fact_sources f where f.provider_id = s2.provider_id and f.kind = 'english_policy' and f.status in ('found', 'reading'))
        and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = s2.provider_id)
        and security.english_provider_in_scope_v1(s2.provider_id)
        and exists (select 1 from catalogue.courses c where c.provider_id = s2.provider_id and c.lifecycle_status = 'active')
      order by (select count(*) from catalogue.courses c2 where c2.provider_id = s2.provider_id and c2.lifecycle_status = 'active') desc
      limit greatest(0, security.pipeline_num_v1('central.research_per_run', 30)::int - (select count(*) from pipeline.provider_central_search q where q.state in ('queued', 'leased'))::int));
  get diagnostics v_re = row_count;
  -- CF-247 6 Nov 2026 (decision D3): the search for providers that have no central English page yet is built and SWITCHED OFF (central.english_search_non_university = 0).
  -- When a person switches it on, up to batch.english_search_non_university providers a run are queued for the existing provider-facts job, which searches inside the
  -- provider's own website and the Firecrawl daily share for central pages. Nothing is queued while the switch is 0.
  if security.pipeline_num_v1('central.english_search_non_university', 0) = 1 then
    insert into pipeline.provider_fact_search(provider_id, kind)
    select p.id, 'english_policy'
      from catalogue.providers p left join ref.provider_types pt on pt.id = p.provider_type_id
     where coalesce(pt.code, '') <> 'university' and coalesce(btrim(p.website), '') ~* '^https?://'
       and security.english_provider_in_scope_v1(p.id)
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id)
       and exists (select 1 from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active')
       and not exists (select 1 from pipeline.provider_fact_search fs where fs.provider_id = p.id and fs.kind = 'english_policy')
       and not exists (select 1 from pipeline.provider_fact_sources f where f.provider_id = p.id and f.kind = 'english_policy')
       and not exists (select 1 from pipeline.provider_policy_proposals pp where pp.provider_id = p.id and pp.kind = 'english_policy' and pp.status in ('approved', 'proposed'))
     order by (select count(*) from catalogue.courses c2 where c2.provider_id = p.id and c2.lifecycle_status = 'active') desc, p.id
     limit security.pipeline_num_v1('batch.english_search_non_university', 10)::int
    on conflict (provider_id, kind) do nothing;
    get diagnostics v_ns = row_count;
  end if;
  -- read central English pages go to the pinned AI (the database checks each quote; policy-auto-approve decides)
  for r in select distinct f.provider_id from pipeline.provider_fact_sources f
            where f.kind = 'english_policy' and f.status in ('read', 'parsed', 'no_values')
              and not exists (select 1 from pipeline.provider_policy_proposals pp where pp.provider_id = f.provider_id and pp.kind = 'english_policy' and pp.status = 'approved') loop
    v_q := v_q + security.central_ai_enqueue_v1(r.provider_id);
  end loop;
  return jsonb_build_object('attached', v_att, 'searched_again', v_re, 'queued_for_ai', v_q, 'search_queued', v_ns);
end $$;


ALTER FUNCTION "security"."central_pages_attach_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."cf093_park_exhausted_discovery_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security', 'catalogue'
    AS $$
declare
  v_preview uuid;
  v_profile uuid;
  v_binding pipeline.scheduler_workflow_async_bindings%rowtype;
  v_retry_max integer:=3;
  v_exhausted integer:=0;
  v_total integer:=0;
  v_unresolved uuid[]:='{}'::uuid[];
  v_source uuid;
  v_l3_profile uuid;
  v_rr uuid;
  v_course uuid;
begin
  if new.job_type<>'layer2_discovery' or new.status not in ('failed','completed','cancelled','blocked','succeeded','success') then return new; end if;
  begin v_preview:=nullif(new.payload->>'scheduler_preview_token','')::uuid; exception when others then v_preview:=null; end;
  begin v_profile:=nullif(new.payload->>'profile_id','')::uuid; exception when others then v_profile:=null; end;
  if v_preview is null or v_profile is null then return new; end if;

  select * into v_binding from pipeline.scheduler_workflow_async_bindings b
  where b.preview_token=v_preview and b.profile_id=v_profile for update;
  if not found or v_binding.status<>'active' then return new; end if;

  begin
    select greatest(coalesce(nullif(pv.configuration#>>'{retry,max_attempts}','')::integer,3),1)
    into v_retry_max from pipeline.layer2_source_profile_versions pv where pv.id=v_binding.profile_version_id;
  exception when others then v_retry_max:=3; end;
  v_retry_max:=coalesce(v_retry_max,3);

  select coalesce(array_agg(c order by c),'{}'::uuid[]) into v_unresolved
  from unnest(v_binding.discovery_course_ids) c
  where not exists(
    select 1 from pipeline.layer2_course_discovery_candidates dc
    join pipeline.layer2_provider_attempts pa on pa.id=dc.provider_attempt_id
    join pipeline.jobs j on j.id=pa.job_id
    where dc.course_id=c
      and dc.source_profile_version_id=v_binding.profile_version_id
      and dc.selected=true
      and nullif(dc.discovered_url,'') is not null
      and dc.created_at>=v_binding.activated_at
      and coalesce(j.payload->>'scheduler_preview_token','')=v_preview::text
  );
  v_total:=cardinality(v_unresolved);
  if v_total<=0 then return new; end if;

  with attempts as (
    select (r->>'course_id')::uuid course_id,count(*)::integer n
    from pipeline.jobs j cross join lateral jsonb_array_elements(coalesce(j.result->'results','[]'::jsonb)) r
    where j.job_type='layer2_discovery'
      and j.payload->>'scheduler_preview_token'=v_preview::text
      and j.payload->>'profile_id'=v_profile::text
      and nullif(r->>'course_id','') is not null
      and (r->>'course_id')::uuid=any(v_unresolved)
      and r->>'status' in ('failed','candidate')
    group by (r->>'course_id')::uuid
  )
  select count(*)::integer into v_exhausted from attempts where n>=v_retry_max;
  if v_exhausted<v_total then return new; end if;

  select source_id into v_source from pipeline.layer2_source_profiles where id=v_profile;
  select id into v_l3_profile from pipeline.layer3_model_profiles
  where enabled and not paused and 'official_course_url'=any(allowed_task_classes)
    and coalesce((quality_benchmark->>'pass')::boolean,false)=true
  order by updated_at desc,id limit 1;

  foreach v_course in array v_unresolved loop
    select id into v_rr from pipeline.refresh_requests
    where requested_layer=3 and entity_type='course' and entity_id=v_course
      and revalidation_ref='CF093-DISCOVERY-PARK:'||v_preview::text||':'||v_course::text limit 1;
    if v_rr is null then
      insert into pipeline.refresh_requests(
        requested_layer,country_code,source_profile_id,entity_type,entity_id,reason,trigger_type,status,
        requested_by,change_control_ref,source_id,evidence_id,layer3_profile_id,revalidation_ref,schedule_error
      ) values(
        3,'AU',v_profile,'course',v_course,
        'Layer 2 URL discovery exhausted Firecrawl/ZenRows; park for governed Layer 3 when course-specific Evidence is available',
        'manual_governed','blocked',v_binding.actor_id,'CF-CHG-20260910-093',v_source,null,v_l3_profile,
        'CF093-DISCOVERY-PARK:'||v_preview::text||':'||v_course::text,
        'Layer 3 is evidence-gated; no course-specific retained Evidence was produced by bounded discovery'
      ) returning id into v_rr;
    end if;
    if not exists(
      select 1 from pipeline.layer4_review_items li
      where li.entity_type='course' and li.entity_id=v_course and li.field_code='official_course_url'
        and li.status='pending' and li.layer2_state->>'scheduler_preview_token'=v_preview::text
    ) then
      insert into pipeline.layer4_review_items(
        entity_type,entity_id,field_code,evidence_id,layer3_interpretation_id,before_value,proposed_value,
        layer2_state,layer3_state,status,escalation_reason,change_control_ref
      ) values(
        'course',v_course,'official_course_url',null,null,null,null,
        jsonb_build_object('status','scraper_exhausted','scheduler_preview_token',v_preview,'source_profile_id',v_profile,
          'retry_max_attempts',v_retry_max,'route','firecrawl_then_zenrows','canonical_mutation_authorised',false),
        jsonb_build_object('status','blocked_pending_evidence','refresh_request_id',v_rr,'profile_id',v_l3_profile,
          'reason','Layer 3 requires governed course-specific Evidence; none was retained by bounded URL discovery'),
        'pending','Firecrawl/ZenRows URL discovery exhausted. Do not perfect site-specific gatekeeper mechanics; resolve through governed Layer 3 when Evidence is available or Layer 4 human review.','CF-CHG-20260910-093'
      );
    end if;
  end loop;

  update pipeline.scheduler_workflow_async_bindings
  set status='handoff_started',handoff_started_at=coalesce(handoff_started_at,now())
  where preview_token=v_preview and profile_id=v_profile and status='active';
  return new;
end
$$;


ALTER FUNCTION "security"."cf093_park_exhausted_discovery_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."cf245_admit_official_url_record_v1"("p_source_record_id" "uuid", "p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'ref', 'search'
    AS $$ declare r pipeline.course_fact_source_records%rowtype; v_provider uuid; v_course uuid; v_url text; v_existing boolean:=false; v_gate boolean:=false; begin if current_user not in('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if; select * into r from pipeline.course_fact_source_records where id=p_source_record_id; if not found then return jsonb_build_object('ok',false,'eligible',false,'reason','source_record_not_found'); end if; if r.evidence_id is null then return jsonb_build_object('ok',true,'eligible',false,'reason','evidence_required'); end if; if coalesce((r.parsed_payload->>'identity_match')::boolean,false)=false then return jsonb_build_object('ok',true,'eligible',false,'reason','identity_mismatch'); end if; if coalesce((r.parsed_payload->>'regulatory_code_seen')::boolean,false)=false then return jsonb_build_object('ok',true,'eligible',false,'reason','regulatory_code_not_seen'); end if; v_url:=nullif(btrim(r.parsed_payload->>'official_course_url'),''); if v_url is null then return jsonb_build_object('ok',true,'eligible',false,'reason','official_url_not_resolved'); end if; if v_url is distinct from r.source_url then return jsonb_build_object('ok',true,'eligible',false,'reason','official_url_evidence_url_mismatch'); end if; if v_url !~ '^https?://' then return jsonb_build_object('ok',true,'eligible',false,'reason','official_url_invalid_scheme'); end if; select pr.provider_id into v_provider from catalogue.provider_registrations pr join catalogue.providers p on p.id=pr.provider_id join ref.countries c on c.id=p.country_id where trim(c.iso_alpha2)='AU' and lower(pr.registration_scheme)='cricos' and upper(btrim(pr.registration_code))=upper(btrim(r.provider_cricos)) and coalesce(pr.status,'active') not in('inactive','cancelled','archived') order by pr.checked_at desc nulls last limit 1; if v_provider is null then return jsonb_build_object('ok',true,'eligible',false,'reason','provider_cricos_not_resolved'); end if; select cr.course_id into v_course from catalogue.course_registrations cr join catalogue.courses c on c.id=cr.course_id where c.provider_id=v_provider and lower(cr.scheme)='cricos' and upper(btrim(cr.registration_code))=upper(btrim(r.course_cricos)) limit 1; if v_course is null then return jsonb_build_object('ok',true,'eligible',false,'reason','course_cricos_not_resolved'); end if; if security.layer4_entity_or_parent_blocked('course',v_course,'operational') then return jsonb_build_object('ok',true,'eligible',false,'reason','layer4_operational_block'); end if; if not exists(select 1 from pipeline.course_fact_source_qualifications q where q.source_id=r.source_id and q.provider_cricos=upper(btrim(r.provider_cricos)) and q.qualification_status in('qualified','bounded') and 'official_course_url'=any(q.admitted_domains)) then return jsonb_build_object('ok',true,'eligible',false,'reason','source_not_qualified_for_official_url'); end if; select exists(select 1 from search.enrichment_source_gates sg where sg.projection_code='courses' and sg.domain_code='official_course_url' and sg.source_id=r.source_id and sg.gate_status='approved') into v_gate; if not v_gate then return jsonb_build_object('ok',true,'eligible',false,'reason','search_source_gate_not_approved'); end if; select exists(select 1 from catalogue.course_links l where l.course_id=v_course and l.link_type='official_course' and l.url=v_url and l.status='active') into v_existing; if not p_apply then return jsonb_build_object('ok',true,'eligible',true,'course_id',v_course,'url',v_url,'would_change',not v_existing,'search_admission_eligible',true); end if; insert into catalogue.course_links(course_id,link_type,url,audience,label,is_primary,status,source_id,evidence_id,confidence,last_verified_at,updated_at) values(v_course,'official_course',v_url,'international','Official provider course page',false,'active',r.source_id,r.evidence_id,1,now(),now()) on conflict(course_id,link_type,url) do update set audience=excluded.audience,label=excluded.label,status='active',source_id=excluded.source_id,evidence_id=excluded.evidence_id,confidence=1,last_verified_at=now(),updated_at=now(); insert into pipeline.layer2_field_admissions(source_record_id,course_id,source_id,evidence_id,field_key,status,reason_code,candidate_payload,canonical_changed,search_admission_eligible) values(r.id,v_course,r.source_id,r.evidence_id,'official_course_url',case when v_existing then 'unchanged' else 'admitted' end,case when v_existing then 'already_active_same_url' else 'qualified_exact_cricos_evidence_match' end,jsonb_build_object('url',v_url),not v_existing,true) on conflict(source_record_id,field_key) do update set status=excluded.status,reason_code=excluded.reason_code,candidate_payload=excluded.candidate_payload,canonical_changed=excluded.canonical_changed,search_admission_eligible=excluded.search_admission_eligible,decided_at=now(); return jsonb_build_object('ok',true,'eligible',true,'applied',true,'course_id',v_course,'url',v_url,'canonical_changed',not v_existing,'search_admission_eligible',true); end $$;


ALTER FUNCTION "security"."cf245_admit_official_url_record_v1"("p_source_record_id" "uuid", "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."cf245_admit_official_url_wave_v1"("p_batch_id" "uuid", "p_limit" integer DEFAULT 25, "p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline'
    AS $$ declare r record; v jsonb; v_checked int:=0; v_eligible int:=0; v_changed int:=0; v_reasons jsonb:='{}'::jsonb; v_reason text; begin if current_user not in('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if; for r in select distinct l.source_record_id from pipeline.layer2_enrichment_operational_ledger_v1 l where l.batch_id=p_batch_id and l.source_record_id is not null and not exists(select 1 from pipeline.layer2_field_admissions a where a.source_record_id=l.source_record_id and a.field_key='official_course_url' and a.status in('admitted','unchanged')) order by l.source_record_id limit greatest(1,least(coalesce(p_limit,25),100)) loop v_checked:=v_checked+1; v:=security.cf245_admit_official_url_record_v1(r.source_record_id,p_apply); if coalesce((v->>'eligible')::boolean,false) then v_eligible:=v_eligible+1; end if; if coalesce((v->>'canonical_changed')::boolean,false) then v_changed:=v_changed+1; end if; v_reason:=coalesce(v->>'reason',case when coalesce((v->>'eligible')::boolean,false) then 'eligible' else 'unknown' end); v_reasons:=jsonb_set(v_reasons,array[v_reason],to_jsonb(coalesce((v_reasons->>v_reason)::int,0)+1),true); end loop; return jsonb_build_object('ok',true,'batch_id',p_batch_id,'apply',p_apply,'checked',v_checked,'eligible',v_eligible,'canonical_changed',v_changed,'reasons',v_reasons,'change_control_ref','CF-CHG-20260915-245'); end $$;


ALTER FUNCTION "security"."cf245_admit_official_url_wave_v1"("p_batch_id" "uuid", "p_limit" integer, "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."companion_sync_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare n int;
begin
  with t as (
    select g.course_id, c.provider_id, case when c.url_replace is not null then regexp_replace(g.url, c.url_pattern, c.url_replace)  -- 22 Oct 2026: an address made from the bound page (Sydney data file)
                else regexp_replace(g.url, '/+$', '') || c.suffix end url
      from pipeline.uni_adapter_companions c
      join catalogue.courses co on co.provider_id = c.provider_id and co.lifecycle_status = 'active'
      join pipeline.coverage_course_pages g on g.course_id = co.id and g.status = 'bound'
     where g.url ~ c.url_pattern),
  up as (
    insert into pipeline.course_companion_pages(course_id, provider_id, url)
    select course_id, provider_id, url from t
    on conflict (course_id) do update set url = excluded.url, status = 'due', "values" = '{}'::jsonb, read_attempts = 0, next_read_at = now(), updated_at = now()
     where pipeline.course_companion_pages.url <> excluded.url
    returning 1)
  select count(*) into n from up;
  return n;
end $_$;


ALTER FUNCTION "security"."companion_sync_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."component_layer_v1"("p_kind" "text", "p_name" "text", "p_area" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select case
    when p_area in ('Layer 1 register') then 'L1 register'
    when p_area in ('Course pages', 'Layer 2 reading', 'Scholarships') then 'L2 read'
    when p_area in ('Layer 3 AI') then 'L3 interpret'
    when p_area in ('Admission') then 'L4 admit'
    when p_area in ('Search and API') then 'Website API'
    when p_area in ('Reports', 'Platform upkeep') then 'Platform'
    when lower(p_name) ~ '(^|[._-])layer1|register|cricos|nzqa|teqsa|qilt|prisms|statcan|ranking|^ref\.' then 'L1 register'
    when lower(p_name) ~ '(^|[._-])layer3|(^|[._-])ai([._-]|$)|_ai_|central_ai' then 'L3 interpret'
    when lower(p_name) ~ '(^|[._-])layer4|admit|admission|review|publish|exit_award|block' then 'L4 admit'
    when lower(p_name) ~ '(^|[._-])layer2|coverage|firecrawl|course_link|adapter|central|enrich|scholarship|onboarding|discover|site|campus|page' then 'L2 read'
    when lower(p_name) ~ 'website|wix|zoho|^search\.|^api\.|^publishing\.' then 'Website API'
    when lower(p_name) ~ '^catalogue\.' then 'Catalogue'
    else 'Platform' end
$_$;


ALTER FUNCTION "security"."component_layer_v1"("p_kind" "text", "p_name" "text", "p_area" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."component_register_ingest_v1"("p" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_edge int := 0; v_screens int := 0; v_used int := 0; v_gone int := 0;
begin
  -- from the component-register workflow: edge functions and screens in the repository, and edge function calls in the last day (logs)
  insert into pipeline.component_register(kind, name, layer, purpose)
  select 'edge_function', e->>'name', security.component_layer_v1('edge_function', e->>'name', null), nullif(e->>'purpose', '')
    from jsonb_array_elements(coalesce(p->'edge_functions', '[]'::jsonb)) e
  on conflict (kind, name) do update set purpose = coalesce(excluded.purpose, pipeline.component_register.purpose), updated_at = now(),
         status = case when pipeline.component_register.status = 'retired' then 'active' else pipeline.component_register.status end;
  get diagnostics v_edge = row_count;
  insert into pipeline.component_register(kind, name, layer, area, purpose)
  select 'screen', s->>'name', security.component_layer_v1('screen', s->>'name', null), s->>'page', nullif(s->>'purpose', '')
    from jsonb_array_elements(coalesce(p->'screens', '[]'::jsonb)) s
  on conflict (kind, name) do update set area = excluded.area, purpose = coalesce(excluded.purpose, pipeline.component_register.purpose), updated_at = now(),
         status = case when pipeline.component_register.status = 'retired' then 'active' else pipeline.component_register.status end;
  get diagnostics v_screens = row_count;
  update pipeline.component_register r set last_used_at = greatest(r.last_used_at, (c->>'last')::timestamptz),
         usage = r.usage || jsonb_build_object('calls_last_day', (c->>'calls')::bigint, 'measured_at', now()), updated_at = now()
    from jsonb_array_elements(coalesce(p->'edge_calls', '[]'::jsonb)) c
   where r.kind = 'edge_function' and r.name = c->>'name';
  get diagnostics v_used = row_count;
  if jsonb_array_length(coalesce(p->'edge_functions', '[]'::jsonb)) > 0 then
    update pipeline.component_register r set status = 'retired', note = coalesce(r.note || '; ', '') || 'not in the repository ' || to_char(now(), 'YYYY-MM-DD'), updated_at = now()
     where r.kind = 'edge_function' and r.status <> 'retired'
       and not exists (select 1 from jsonb_array_elements(p->'edge_functions') e where e->>'name' = r.name);
    get diagnostics v_gone = row_count;
  end if;
  return jsonb_build_object('edge_functions', v_edge, 'screens', v_screens, 'edge_used', v_used, 'edge_gone', v_gone);
end $$;


ALTER FUNCTION "security"."component_register_ingest_v1"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."component_register_markdown_v1"() RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- the generated document: summary by layer and status, then every component (newest hygiene check first)
  select '# StudySearch – Component register (generated)' || E'\n\n'
      || '**Generated:** ' || to_char(now() at time zone 'Australia/Melbourne', 'DD Mon YYYY HH24:MI') || ' Melbourne, from `pipeline.component_register` (Decision 260). Do not edit by hand.' || E'\n\n'
      || '## Summary' || E'\n\n| Layer | Kind | Active | Retiring | Retired |\n|---|---|---|---|---|\n'
      || coalesce((select string_agg(format('| %s | %s | %s | %s | %s |', layer, kind, a, ri, rd), E'\n' order by layer, kind)
                   from (select layer, kind, count(*) filter (where status = 'active') a, count(*) filter (where status = 'retiring') ri, count(*) filter (where status = 'retired') rd
                           from pipeline.component_register group by 1, 2) x), '')
      || E'\n\n## Latest hygiene check\n\n'
      || coalesce((select '```' || E'\n' || jsonb_pretty(h.summary) || E'\n```' from pipeline.hygiene_reports h order by h.at desc limit 1), 'None yet.')
      || E'\n\n## Components\n\n| Kind | Name | Layer | Status | Purpose | Last used | Size | Replaces / replaced by | Note |\n|---|---|---|---|---|---|---|---|---|\n'
      || coalesce((select string_agg(format('| %s | `%s` | %s | %s | %s | %s | %s | %s | %s |', r.kind, r.name, r.layer, r.status,
                          replace(left(coalesce(r.purpose, ''), 160), '|', '/'), coalesce(to_char(r.last_used_at, 'YYYY-MM-DD'), ''),
                          coalesce(pg_size_pretty(r.size_bytes), ''), concat_ws(' / ', nullif(array_to_string(r.replaces, ', '), ''), r.replaced_by),
                          replace(coalesce(r.note, ''), '|', '/')), E'\n' order by r.layer, r.kind, r.name)
                   from pipeline.component_register r), '') || E'\n'
$$;


ALTER FUNCTION "security"."component_register_markdown_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."component_register_sync_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_jobs int; v_tables int; v_gone int;
begin
  -- jobs: the job catalogue gives the area and purpose (G1)
  insert into pipeline.component_register(kind, name, layer, area, purpose, status, note)
  select 'job', j.jobname, security.component_layer_v1('job', j.jobname, c.area), c.area, coalesce(c.label || coalesce(': ' || c.description, ''), 'Not in the job catalogue'),
         'active', case when c.jobname is null then 'not catalogued' when not j.active then 'switched off' end
    from cron.job j left join pipeline.automation_catalogue c on c.jobname = j.jobname
  on conflict (kind, name) do update set area = excluded.area, purpose = excluded.purpose, note = excluded.note, updated_at = now(),
         layer = case when pipeline.component_register.layer = 'Platform' then excluded.layer else pipeline.component_register.layer end,
         status = case when pipeline.component_register.status = 'retired' then 'active' else pipeline.component_register.status end;
  get diagnostics v_jobs = row_count;
  -- tables and views in the platform's schemas: purpose from the table comment, size from the catalogue
  insert into pipeline.component_register(kind, name, layer, purpose, size_bytes)
  select case c.relkind when 'v' then 'view' when 'm' then 'view' else 'table' end, n.nspname || '.' || c.relname,
         security.component_layer_v1('table', n.nspname || '.' || c.relname, null), obj_description(c.oid, 'pg_class'),
         case when c.relkind in ('r', 'p', 'm') then pg_total_relation_size(c.oid) end
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where c.relkind in ('r', 'p', 'v', 'm')
     and n.nspname not in ('pg_catalog', 'information_schema', 'cron', 'net', 'extensions', 'graphql', 'graphql_public', 'pgbouncer', 'pgsodium', 'pgsodium_masks',
                           'realtime', 'storage', 'supabase_functions', 'supabase_migrations', 'vault', 'auth', 'pg_toast')
     and n.nspname not like 'pg_temp%' and n.nspname not like 'pg_toast%'
     and not c.relispartition
  on conflict (kind, name) do update set purpose = coalesce(excluded.purpose, pipeline.component_register.purpose), size_bytes = excluded.size_bytes, updated_at = now(),
         status = case when pipeline.component_register.status = 'retired' then 'active' else pipeline.component_register.status end;
  get diagnostics v_tables = row_count;
  -- what no longer exists is marked retired (kept in the register)
  update pipeline.component_register r set status = 'retired', note = coalesce(r.note || '; ', '') || 'gone ' || to_char(now(), 'YYYY-MM-DD'), updated_at = now()
   where r.status <> 'retired' and (
         (r.kind = 'job' and not exists (select 1 from cron.job j where j.jobname = r.name))
      or (r.kind in ('table', 'view') and to_regclass(r.name) is null));
  get diagnostics v_gone = row_count;
  return jsonb_build_object('jobs', v_jobs, 'tables_and_views', v_tables, 'gone', v_gone);
end $$;


ALTER FUNCTION "security"."component_register_sync_v1"() OWNER TO "postgres";


