CREATE OR REPLACE FUNCTION "security"."country_scope_gate_v1"("p_apply" boolean DEFAULT true, "p_country" "text" DEFAULT 'CA'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "statement_timeout" TO '120s'
    AS $$
declare
  v_tag text := (select max(s.scope_tag) from pipeline.country_scope_levels s where s.country_code = p_country);
  v_cap int := security.pipeline_num_v1('batch.country_scope_gate', 1000)::int;
  v_fresh interval := make_interval(days => security.pipeline_num_v1('country_scope.page_fresh_days', 180)::int);
  v_hide int := 0; v_show int := 0; v_hide_n int; v_show_n int;
begin
  if v_tag is null then return jsonb_build_object('country', p_country, 'note', 'no scope levels for this country'); end if;
  create temp table if not exists _scope_hide(course_id uuid, level text, rule text) on commit drop;
  create temp table if not exists _scope_show(course_id uuid, level text, rule text) on commit drop;
  truncate _scope_hide; truncate _scope_show;
  -- hide: active, level missing or out of scope, and not waiting for its page to be read for a credential
  insert into _scope_hide
  select c.id, sl.code, case when c.study_level_id is null then 'no_level' else 'level_out_of_scope' end
    from catalogue.courses c
    join catalogue.providers p on p.id = c.provider_id
    left join ref.study_levels sl on sl.id = c.study_level_id
   where c.lifecycle_status = 'active' and security.coverage_country(c.provider_id) = p_country
     and not exists (select 1 from pipeline.country_scope_levels s where s.country_code = p_country and s.study_level_code = sl.code)
     and not exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = c.id and l.field = 'lifecycle_status')
     and (c.study_level_id is not null or not exists (select 1 from pipeline.coverage_course_pages pg where pg.course_id = c.id and pg.read_status = 'read' and pg.evidence_id is not null
                       and not exists (select 1 from pipeline.course_credential_reads r where r.course_id = c.id and r.evidence_id = pg.evidence_id and r.outcome <> 'leased')));
  -- show: inactive, level in scope, provider a DLI, own page read recently, and nothing else retired it
  insert into _scope_show
  select c.id, sl.code, 'level_in_scope'
    from catalogue.courses c
    join catalogue.providers p on p.id = c.provider_id and p.enrols_international is true and coalesce(p.lifecycle_status, 'active') = 'active'
    join ref.study_levels sl on sl.id = c.study_level_id
    join pipeline.country_scope_levels s on s.country_code = p_country and s.study_level_code = sl.code
    join pipeline.coverage_course_pages pg on pg.course_id = c.id and pg.read_status = 'read' and pg.status = 'bound' and pg.read_at > now() - v_fresh
                     and (pg.basis is distinct from 'programme_list' or security.programme_provider_approved_v1(c.provider_id))  -- 22 Oct 2026: a programme list course waits for a person's approval
   where c.lifecycle_status = 'inactive' and security.coverage_country(c.provider_id) = p_country
     and not exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = c.id and l.field = 'lifecycle_status')
     and not exists (select 1 from pipeline.layer1_course_retirements r where r.course_id = c.id and r.reactivated_at is null)
     and not exists (select 1 from pipeline.enrichment_flags f where f.entity = 'course' and f.entity_key = c.id::text and f.state = 'raised' and f.reason_code = 'not_offered');
  select count(*) into v_hide_n from _scope_hide; select count(*) into v_show_n from _scope_show;
  if p_apply then
    with h as (select x.* from _scope_hide x order by x.course_id limit v_cap),
         u as (update catalogue.courses c set lifecycle_status = 'inactive', updated_at = now() from h where c.id = h.course_id and c.lifecycle_status = 'active' returning c.id, h.level, h.rule),
         l as (insert into pipeline.course_scope_changes(course_id, from_status, to_status, scope_tag, rule, study_level_code) select u.id, 'active', 'inactive', v_tag, u.rule, u.level from u returning 1)
    select count(*) into v_hide from l;
    with s as (select x.* from _scope_show x order by x.course_id limit greatest(0, v_cap - v_hide)),
         u as (update catalogue.courses c set lifecycle_status = 'active', updated_at = now() from s where c.id = s.course_id and c.lifecycle_status = 'inactive' returning c.id, s.level, s.rule),
         l as (insert into pipeline.course_scope_changes(course_id, from_status, to_status, scope_tag, rule, study_level_code) select u.id, 'inactive', 'active', v_tag, u.rule, u.level from u returning 1)
    select count(*) into v_show from l;
    if v_hide + v_show > 0 then
      insert into search.refresh_requests(requested_by) values ('country scope gate ' || p_country || ' (' || v_tag || '): ' || v_hide || ' hidden, ' || v_show || ' shown');
    end if;
  end if;
  return jsonb_build_object('country', p_country, 'scope', v_tag, 'would_hide', v_hide_n, 'would_show', v_show_n, 'hidden', v_hide, 'shown', v_show, 'applied', p_apply,
    'hide_by_rule', (select coalesce(jsonb_object_agg(rule, n), '{}'::jsonb) from (select rule, count(*) n from _scope_hide group by 1) z),
    'show_by_level', (select coalesce(jsonb_object_agg(level, n), '{}'::jsonb) from (select level, count(*) n from _scope_show group by 1) z));
end $$;


ALTER FUNCTION "security"."country_scope_gate_v1"("p_apply" boolean, "p_country" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_adapter_rank_v1"("p_state" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select array_position(array['failed', 'held', 'processing', 'ready', 'completed', 'not_configured'], p_state)
$$;


ALTER FUNCTION "security"."course_adapter_rank_v1"("p_state" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_adapter_state_from_v1"("p_has_adapter" boolean, "p_enabled" boolean, "p_admit" boolean, "p_leased" boolean, "p_page_status" "text", "p_read_status" "text", "p_last_result" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when not coalesce(p_has_adapter, false) then 'not_configured'
    when coalesce(p_leased, false) then 'processing'
    when not (coalesce(p_enabled, false) and coalesce(p_admit, false)) then 'held'
    when p_last_result is not null and p_last_result <> 'read' then 'failed'
    when p_read_status is not null and p_read_status <> 'read' then 'failed'
    when p_last_result is not null then 'completed'
    when p_page_status is distinct from 'bound' then 'held'
    else 'ready' end
$$;


ALTER FUNCTION "security"."course_adapter_state_from_v1"("p_has_adapter" boolean, "p_enabled" boolean, "p_admit" boolean, "p_leased" boolean, "p_page_status" "text", "p_read_status" "text", "p_last_result" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_adapter_state_from_v1"("p_has_adapter" boolean, "p_enabled" boolean, "p_admit" boolean, "p_leased" boolean, "p_page_status" "text", "p_read_status" "text", "p_last_result" "text") IS 'CF-247 Course Catalogue columns (mandate 5 Nov 2026 17:31 §3): a course''s adapter status from the provider adapter (exists, enabled, admitting), its course page (being read, bound, read status) and its latest adapter result: not_configured, processing, held, failed, completed, ready. Completed is never inferred from an adapter existing.';



CREATE OR REPLACE FUNCTION "security"."course_adapter_state_v1"("p_course_id" "uuid", "p_provider_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE
    AS $$
  select security.course_adapter_state_from_v1(u.provider_id is not null, u.enabled, u.admit, p.leased_until > now(), p.status, p.read_status,
           (select r.before_read_status from pipeline.uni_adapter_results r where r.course_id = p_course_id order by r.at desc, r.id desc limit 1))
    from (select 1) one
    left join pipeline.uni_adapters u on u.provider_id = p_provider_id
    left join pipeline.coverage_course_pages p on p.course_id = p_course_id
$$;


ALTER FUNCTION "security"."course_adapter_state_v1"("p_course_id" "uuid", "p_provider_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_adapter_state_v1"("p_course_id" "uuid", "p_provider_id" "uuid") IS 'CF-247 Course Catalogue columns (mandate 5 Nov 2026 17:31 §3): a course''s adapter status (security.course_adapter_state_from_v1) read from the adapter tables.';



CREATE OR REPLACE FUNCTION "security"."course_admissions_v1"() RETURNS TABLE("course_id" "uuid", "at" timestamp with time zone, "field" "text", "source" "text", "evidence_id" "uuid", "before" "jsonb", "after" "jsonb", "rule" "text")
    LANGUAGE "sql" STABLE
    AS $$
  select i.course_id, i.updated_at, i.field, coalesce(i.source, 'enrich_fields'), i.evidence_id, null::jsonb,
         case when jsonb_typeof(i.value) = 'object' then i.value - 'text' - 'check' else i.value end, 'Enrich fields'::text
    from pipeline.field_enrich_items i
   where i.state = 'filled' and i.course_id is not null and not exists (select 1 from pipeline.enrich_value_retractions x where x.item_id = i.id)
  union all
  select a.course_id, a.at, a.field, 'adapter_overwrite', a.evidence_id, a.before, a.after, 'Adapter overwrite'
    from pipeline.adapter_overwrite_changes a where a.before is distinct from a.after
  union all
  select l.course_id, l.decided_at, l.field_key, 'layer2_admission', l.evidence_id, null, l.candidate_payload, l.change_control_ref
    from pipeline.layer2_field_admissions l where l.status = 'admitted' and l.canonical_changed
  union all
  select k.entity_id, k.decided_at, k.field_code, 'layer4_approval', null, null, null, 'Layer 4 decision ' || k.decision_id::text
    from pipeline.layer4_admission_checks k where k.entity_type = 'course' and k.admitted
  union all
  select e.course_id, e.run_at, 'intakes', 'intake_dates', e.calendar_evidence_id, e.before_value, e.after_value, coalesce(e.rule, 'Intake dates')
    from pipeline.course_intake_date_events e where e.outcome = 'filled'
  union all
  select m.entity_id, m.at, coalesce(m.field, m.action), 'manual', null, m.before, m.after, coalesce(m.reason, 'Set by hand')
    from pipeline.manual_edit_log m where m.entity = 'course' and m.action in ('set_official_url', 'set_tuition')
$$;


ALTER FUNCTION "security"."course_admissions_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_admissions_v1"() IS 'CF-247 Course Catalogue columns (mandate 5 Nov 2026 17:31 §4): every admission of a course value from the admission ledgers (field items filled and not retracted, adapter overwrites that changed the value, Layer 2 admissions that changed the canonical value, Layer 4 approvals confirmed admitted, intake dates filled, official page or tuition set by hand). The one definition of Last data admitted: its column, its detail and its sort.';



CREATE OR REPLACE FUNCTION "security"."course_completeness_build_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
declare v jsonb;
begin
  truncate pipeline.course_completeness;
  insert into pipeline.course_completeness(course_id,provider_id,tier,attributes,admitted,accounted,completeness,accounted_pct,missing,country_code)
  select course_id, max(provider_id::text)::uuid, max(tier), count(*) filter (where state<>'no_reader') /* 24 Oct 2026: attributes the platform can read; fully complete = all of them admitted */,
         count(*) filter (where state='admitted'),
         count(*) filter (where state in ('admitted','candidate','in_review','awaiting_l3','not_on_page','blocked')),
         round(100.0*count(*) filter (where state='admitted')/count(*),1),
         round(100.0*count(*) filter (where state in ('admitted','candidate','in_review','awaiting_l3','not_on_page','blocked'))/count(*),1),
         coalesce(array_agg(attribute order by attribute) filter (where state<>'admitted'),'{}'),
         max(country_code)
    from pipeline.course_attribute_coverage group by course_id;
  delete from pipeline.completeness_daily where snapshot_date=current_date;
  insert into pipeline.completeness_daily(snapshot_date,scope,scope_id,courses,completeness,accounted_pct,fully_complete)
  select current_date,'platform',null,count(*),round(avg(completeness),1),round(avg(accounted_pct),1),count(*) filter (where admitted=attributes) from pipeline.course_completeness
  union all
  select current_date,'provider',provider_id,count(*),round(avg(completeness),1),round(avg(accounted_pct),1),count(*) filter (where admitted=attributes) from pipeline.course_completeness where provider_id is not null group by provider_id;
  -- Decision 213: one row per country; provider rows carry their country
  insert into pipeline.completeness_daily(snapshot_date,scope,scope_id,courses,completeness,accounted_pct,fully_complete,country_code)
  select current_date,'country:'||country_code,null,count(*),round(avg(completeness),1),round(avg(accounted_pct),1),count(*) filter (where admitted=attributes),country_code
    from pipeline.course_completeness group by country_code;
  update pipeline.completeness_daily x set country_code = (select max(c.country_code) from pipeline.course_completeness c where c.provider_id = x.scope_id)
   where x.snapshot_date = current_date and x.scope = 'provider';
  select to_jsonb(d) - 'scope_id' into v from pipeline.completeness_daily d where snapshot_date=current_date and scope='platform';
  return v;
end $$;


ALTER FUNCTION "security"."course_completeness_build_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_completeness_v1"("p_course" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select round(((exists(select 1 from catalogue.course_registrations r where r.course_id = c.id))::int
          + (c.duration_value is not null or exists(select 1 from catalogue.course_academic_options a where a.course_id = c.id))::int
          + (exists(select 1 from catalogue.course_fees cf where cf.course_id = c.id and coalesce(cf.status, 'active') = 'active'))::int
          + (exists(select 1 from catalogue.course_intakes ci where ci.course_id = c.id and coalesce(ci.status, 'active') = 'active'))::int
          + (exists(select 1 from catalogue.course_english_requirements er where er.course_id = c.id and coalesce(er.status, 'active') = 'active'))::int
          + (c.description is not null and length(trim(c.description)) > 0)::int) * 100.0 / 6.0, 2)
    from catalogue.courses c where c.id = p_course
$$;


ALTER FUNCTION "security"."course_completeness_v1"("p_course" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_completeness_v1"("p_course" "uuid") IS 'CF-247 Course catalogue (20261113153000): a course''s completeness score as courses_page shows it, for the completeness sort of the filtered path';



CREATE OR REPLACE FUNCTION "security"."course_coverage_build_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'ref', 'security'
    AS $$
declare v_n int; v_t0 timestamptz:=clock_timestamp();
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  create temp table _c on commit drop as
    select co.id course_id, co.provider_id, co.duration_value, co.study_level_id, co.primary_field_id, co.delivery_mode, co.open_to_international,
           nullif(btrim(co.description),'') is not null has_description, k.iso_alpha2::text country_code
      from catalogue.courses co join catalogue.providers p on p.id=co.provider_id join ref.countries k on k.id=p.country_id
     where co.lifecycle_status='active'; -- Decision 213: every country
  create temp table _tier on commit drop as
    select provider_id, case when rk<=10 then 'top_10' when rk<=40 then 'top_11_40' when rk<=100 then 'top_41_100' else 'rest' end tier
      from (select provider_id, row_number() over (partition by min(country_code) order by count(*) desc, provider_id) rk from _c group by provider_id) x; -- tiers within each country
  create temp table _site on commit drop as
    select t.provider_id from _tier t join catalogue.providers p on p.id=t.provider_id
     where nullif(btrim(p.website),'') is not null or exists(select 1 from pipeline.provider_discovery_links l where l.provider_id=t.provider_id);
  create temp table _found on commit drop as
    select distinct course_id from pipeline.layer2_course_discovery_candidates where selected and course_id is not null;
  create temp table _read on commit drop as
    select entity_id course_id, bool_or(status in ('resolved_l2','layer3_required')) read_ok, bool_or(status='blocked') blocked
      from pipeline.layer2_run_items where entity_type='course' group by entity_id;
  create temp table _sw on commit drop as
    select course_id, status, read_status, identity_basis,
           (read_status='read' and identity_basis='cricos_code') verified,
           coalesce((candidates->'fee'->>'value') is not null,false) c_tuition,
           coalesce(candidates->'english' ? 'ielts_overall' or candidates->'english' ? 'pte_overall' or candidates->'english' ? 'toefl_overall',false) c_english,
           coalesce(jsonb_array_length(candidates->'intakes')>0,false) c_intakes
      from pipeline.coverage_course_pages;
  -- AER v2 step 0 (Decision 276): admitted entry requirements count for academic_entry (resolver rules 1, 2 and 4)
  create temp table _aer_cov on commit drop as select x.course_id from security.aer_covered_courses_v1() x;
  create temp table _val on commit drop as
    select c.course_id,
      exists(select 1 from catalogue.course_links l where l.course_id=c.course_id and l.status='active' and l.link_type='official_course') url,
      exists(select 1 from catalogue.course_fees f where f.course_id=c.course_id and f.status='active' and f.fee_type='provider_current_tuition') tuition,
      exists(select 1 from catalogue.course_english_requirements e where e.course_id=c.course_id and e.status='active') english,
      exists(select 1 from catalogue.course_intakes i where i.course_id=c.course_id and coalesce(i.status,'active')='active') intakes,
      exists(select 1 from catalogue.course_fees f where f.course_id=c.course_id and f.status='active' and f.fee_type='tuition') reg_tuition,
      exists(select 1 from catalogue.course_campuses cc where cc.course_id=c.course_id) campus,
      -- CF-247 21 Oct 2026: the other course fields of the field register
      exists(select 1 from catalogue.course_campuses cc join catalogue.campuses k on k.id=cc.campus_id where cc.course_id=c.course_id and nullif(btrim(k.city),'') is not null) campus_city,
      exists(select 1 from catalogue.course_intakes i where i.course_id=c.course_id and coalesce(i.status,'active')='active' and i.application_deadline is not null) deadline,
      (exists(select 1 from catalogue.course_academic_options a where a.course_id=c.course_id) or exists(select 1 from _aer_cov x where x.course_id=c.course_id)) academic
    from _c c;
  create temp table _l4 on commit drop as
    select entity_id course_id, case when field_code in ('official_course_url') then 'official_url'
                                     when field_code in ('provider_current_tuition_validation','provider_current_tuition') then 'provider_tuition'
                                     when field_code ilike '%english%' then 'english' when field_code ilike '%intake%' then 'intakes' end attribute
      from pipeline.layer4_review_items where entity_type='course' and status='pending'
    union
    select entity_id, case when task_class='provider_current_tuition_validation' then 'provider_tuition' when task_class ilike '%english%' then 'english'
                           when task_class ilike '%intake%' then 'intakes' when task_class ilike '%url%' then 'official_url' end
      from pipeline.layer3_work_items where entity_type='course' and status='layer4_required';
  create temp table _l3 on commit drop as
    select entity_id course_id, case when task_class='provider_current_tuition_validation' then 'provider_tuition' when task_class ilike '%english%' then 'english'
                                     when task_class ilike '%intake%' then 'intakes' when task_class ilike '%url%' then 'official_url' end attribute
      from pipeline.layer3_work_items where entity_type='course' and status in ('pending','reserved','failed','retry');
  -- CF-247 21 Oct 2026: where the Enrich fields work is for each course and field (the latest item, any task)
  create temp table _ei on commit drop as
    select distinct on (course_id, field) course_id, field, state from pipeline.field_enrich_items where course_id is not null order by course_id, field, id desc;
  create temp table _reg on commit drop as select field attribute, reader from pipeline.field_register where level='course' and active;
  -- CF-247 Release B (D2): the open absence of each course field and the state its class shows
  create temp table _ab on commit drop as
    select a.course_id, a.field, a.absence_class, k.coverage_state,
           a.field = any (array(select jsonb_array_elements_text(case when jsonb_typeof(security.toolset_setting('pipeline','absence.coverage_fields'))='array'
                                                                      then security.toolset_setting('pipeline','absence.coverage_fields') else '[]'::jsonb end))) by_class
      from pipeline.course_field_absence a join pipeline.field_absence_classes k on k.code=a.absence_class where a.resolved_at is null;

  truncate pipeline.course_attribute_coverage;
  insert into pipeline.course_attribute_coverage(course_id,provider_id,attribute,state,tier,computed_at,country_code,absence_class)
  select c.course_id, c.provider_id, a.attribute,
    case
      when a.l1 then case when a.has then 'admitted' else 'missing_l1' end
      when a.has then 'admitted'
      when g.reader='none' then 'no_reader'
      when g.reader='enrich' and ei.state in ('queued','waiting','ai','leased') then 'in_queue'
      when g.reader='enrich' and ei.state='review' then 'in_review'
      when g.reader='enrich' and ei.state in ('skipped','failed') and ab.by_class
        then coalesce(ab.coverage_state, case when r.blocked or sw.read_status in ('blocked','robots_disallowed') then 'blocked'
                                              when f.course_id is not null or v.url or sw.status='bound' or sw.verified or r.read_ok then 'page_found'
                                              when s.provider_id is not null then 'site_known' else 'no_website' end)
      when g.reader='enrich' and ei.state in ('skipped','failed') then 'not_on_page'
      when g.reader='enrich' then case when r.blocked or sw.read_status in ('blocked','robots_disallowed') then 'blocked'
                                       when f.course_id is not null or v.url or sw.status='bound' or sw.verified or r.read_ok then 'page_found'
                                       when s.provider_id is not null then 'site_known' else 'no_website' end
      when exists(select 1 from _l4 x where x.course_id=c.course_id and x.attribute=a.attribute) then 'in_review'
      when exists(select 1 from _l3 x where x.course_id=c.course_id and x.attribute=a.attribute) then 'awaiting_l3'
      when sw.verified and (a.attribute='official_url' or (a.attribute='provider_tuition' and sw.c_tuition) or (a.attribute='english' and sw.c_english) or (a.attribute='intakes' and sw.c_intakes)) then 'candidate'
      when r.read_ok or sw.verified then 'not_on_page'
      when r.blocked or sw.read_status in ('blocked','robots_disallowed') then 'blocked'
      when f.course_id is not null or v.url or sw.status='bound' then 'page_found'
      when s.provider_id is not null then 'site_known'
      else 'no_website' end,
    t.tier, now(), c.country_code, case when not a.has then ab.absence_class end
  from _c c join _val v using (course_id) join _tier t using (provider_id)
  left join _read r using (course_id) left join _found f using (course_id) left join _sw sw using (course_id) left join _site s on s.provider_id=c.provider_id
  cross join lateral (values
    ('official_url', v.url, false), ('provider_tuition', v.tuition, false), ('english', v.english, false), ('intakes', v.intakes, false),
    -- register (Layer 1) values in Australia only; registered tuition is a CRICOS value and is not counted elsewhere
    ('registered_tuition', v.reg_tuition, true), ('duration', c.duration_value is not null, c.country_code='AU'), ('campus', v.campus, c.country_code='AU'),
    ('level', c.study_level_id is not null, false), ('field_of_study', c.primary_field_id is not null, false),
    ('delivery', nullif(btrim(c.delivery_mode),'') is not null, false), ('campus_city', v.campus_city, false),
    ('international', c.open_to_international is not null, false), ('deadline', v.deadline, false), ('academic_entry', v.academic, false),
    ('description', c.has_description, false)) a(attribute, has, l1)
  join _reg g on g.attribute=a.attribute
  left join _ei ei on ei.course_id=c.course_id and ei.field=case a.attribute when 'campus_city' then 'campus' else a.attribute end
  left join _ab ab on ab.course_id=c.course_id and ab.field=a.attribute
  where a.attribute<>'registered_tuition' or c.country_code='AU';
  get diagnostics v_n=row_count;

  delete from pipeline.course_coverage_daily where snapshot_date=current_date;
  insert into pipeline.course_coverage_daily(snapshot_date,attribute,state,tier,courses)
  select current_date, attribute, state, tier, count(*) from pipeline.course_attribute_coverage where country_code='AU' group by 2,3,4;
  -- Decision 213: daily counts by country
  update pipeline.course_coverage_daily_by_country set courses = 0, computed_at = now() where snapshot_date = current_date;
  insert into pipeline.course_coverage_daily_by_country(snapshot_date,country_code,attribute,state,tier,courses)
  select current_date, country_code, attribute, state, tier, count(*) from pipeline.course_attribute_coverage group by 2,3,4,5
  on conflict (snapshot_date,country_code,attribute,state,tier) do update set courses = excluded.courses, computed_at = now();
  return jsonb_build_object('rows',v_n,'courses',(select count(*) from _c),'ms',round(extract(epoch from clock_timestamp()-v_t0)*1000));
end $$;


ALTER FUNCTION "security"."course_coverage_build_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_coverage_snapshot_refresh_v1"("p_force" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare
  v_t0 timestamptz := clock_timestamp();
  v_min int := greatest(security.pipeline_num_v1('snapshot.course_coverage_min_interval_minutes', 10)::int, 1);
  v_src timestamptz; v_cc timestamptz; v_fs timestamptz; v_n int;
  v_h pipeline.course_coverage_snapshot%rowtype;
begin
  if not pg_try_advisory_xact_lock(hashtext('cf247:course_coverage_snapshot')) then  -- fixed: the one-builder lock (W34)
    return jsonb_build_object('skipped', 'busy');
  end if;
  perform set_config('lock_timeout', '2000', true);  -- fixed: technical safety, never queue behind an hourly source build (the next run retries)
  begin
    select max(x.computed_at) into v_src from pipeline.course_attribute_coverage x;
    select max(c.computed_at) into v_cc from pipeline.course_completeness c;
    select max(s.computed_at) into v_fs from pipeline.course_field_source s;
  exception when lock_not_available then
    return jsonb_build_object('skipped', 'source_build_running');
  end;
  select * into v_h from pipeline.course_coverage_snapshot where id = 1;
  if found and not coalesce(p_force, false) then
    if v_h.source_computed_at is not distinct from v_src and v_h.completeness_computed_at is not distinct from v_cc
       and v_h.field_sources_at is not distinct from v_fs then
      update pipeline.course_coverage_snapshot set checked_at = now() where id = 1;
      return jsonb_build_object('skipped', 'current', 'generated_at', v_h.generated_at);
    end if;
    if v_h.generated_at > now() - make_interval(mins => v_min) then
      return jsonb_build_object('skipped', 'min_interval', 'generated_at', v_h.generated_at);
    end if;
  end if;
  delete from pipeline.course_coverage_totals;
  insert into pipeline.course_coverage_totals(kind, provider_id, tier, country_code, attribute, state, admitted, attributes, n, sum_completeness, sum_accounted, max_computed_at)
  select 'group', g.provider_id, g.tier, g.country_code, null::text, null::text, null::int, null::int, count(*)::bigint, null::numeric, null::numeric, null::timestamptz
    from (select distinct x.course_id, x.provider_id, x.tier, x.country_code from pipeline.course_attribute_coverage x) g
   group by g.provider_id, g.tier, g.country_code
  union all
  select 'attr', x.provider_id, x.tier, x.country_code, x.attribute, x.state, null, null, count(*), null, null, null
    from pipeline.course_attribute_coverage x group by x.provider_id, x.tier, x.country_code, x.attribute, x.state
  union all
  select 'completeness', c.provider_id, c.tier, c.country_code, null, null, c.admitted, c.attributes, count(*), sum(c.completeness), sum(c.accounted_pct), max(c.computed_at)
    from pipeline.course_completeness c group by c.provider_id, c.tier, c.country_code, c.admitted, c.attributes
  union all
  select 'source', s.provider_id, s.tier, s.country_code, 'intakes', s.intakes_src, null, null, count(*), null, null, null
    from pipeline.course_field_source s group by s.provider_id, s.tier, s.country_code, s.intakes_src
  union all
  select 'source', s.provider_id, s.tier, s.country_code, 'english', s.english_src, null, null, count(*), null, null, null
    from pipeline.course_field_source s group by s.provider_id, s.tier, s.country_code, s.english_src
  union all
  select 'source', s.provider_id, s.tier, s.country_code, 'fee', s.fee_src, null, null, count(*), null, null, null
    from pipeline.course_field_source s group by s.provider_id, s.tier, s.country_code, s.fee_src;
  get diagnostics v_n = row_count;
  insert into pipeline.course_coverage_snapshot(id, generated_at, checked_at, source_computed_at, completeness_computed_at, field_sources_at, total_rows, build_ms)
  values (1, now(), now(), v_src, v_cc, v_fs, v_n, round(extract(epoch from clock_timestamp() - v_t0) * 1000)::int)
  on conflict (id) do update set generated_at = excluded.generated_at, checked_at = excluded.checked_at, source_computed_at = excluded.source_computed_at,
    completeness_computed_at = excluded.completeness_computed_at, field_sources_at = excluded.field_sources_at, total_rows = excluded.total_rows, build_ms = excluded.build_ms;
  return jsonb_build_object('rows', v_n, 'ms', round(extract(epoch from clock_timestamp() - v_t0) * 1000));
end $$;


ALTER FUNCTION "security"."course_coverage_snapshot_refresh_v1"("p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_deadline_in_quote_v1"("p_date" "date", "p_quote" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  -- P0 deadline semantics (Admin #382, 6 Nov 2026): a printed commencement date is
  -- not an application closing date. The closing cue and the only full date must
  -- be in the same clause. Ambiguous multi-date clauses wait for better evidence.
  with grammar as (
    select '(jan(uary)?|feb(ruary)?|mar(ch)?|apr(il)?|may|jun(e)?|jul(y)?|aug(ust)?|sep(t(ember)?)?|oct(ober)?|nov(ember)?|dec(ember)?)'::text mon
  ), dates as (
    select extract(year from p_date)::int::text y, extract(month from p_date)::int::text m, extract(day from p_date)::int::text d,
           (array['jan(uary)?','feb(ruary)?','mar(ch)?','apr(il)?','may','jun(e)?','jul(y)?','aug(ust)?','sep(t(ember)?)?','oct(ober)?','nov(ember)?','dec(ember)?'])[extract(month from p_date)::int] mon
  ), patterns as (
    select '\m(0?' || d || '(st|nd|rd|th)?\s+' || dates.mon || '\.?\s*,?\s*' || y
           || '|' || dates.mon || '\.?\s+0?' || d || '(st|nd|rd|th)?\s*,?\s*' || y
           || '|0?' || d || '[/.-]0?' || m || '[/.-]' || y || '|' || y || '-0?' || m || '-0?' || d || ')\M' target,
           '\m([0-9]{1,2}(st|nd|rd|th)?\s+' || grammar.mon || '\.?\s*,?\s*[0-9]{4}'
           || '|' || grammar.mon || '\.?\s+[0-9]{1,2}(st|nd|rd|th)?\s*,?\s*[0-9]{4}'
           || '|[0-9]{1,2}[/.-][0-9]{1,2}[/.-][0-9]{4}|[0-9]{4}-[0-9]{1,2}-[0-9]{1,2})\M' full_date
      from dates cross join grammar
  ), clauses as (
    select lower(t) t from regexp_split_to_table(coalesce(p_quote, ''), E'[;\n\r]+|[.!?]\\s+(?=[A-Za-z])') t
  )
  select coalesce(p_date is not null and exists (
    select 1 from clauses c cross join patterns p
     where c.t ~ p.target
       and c.t ~ '(\mapplications?\M.*\m(close[sd]?|closing|due|deadlines?)\M|\mapplication\s+deadlines?\M|\mclosing\s+date\M|\mapply\s+(by|before)\M|\mapplications?\M.*\m(received|submitted)\s+(by|before)\M|\mintakes?\M.*\mcloses?\M)'
       and c.t !~ '\m(not|never|fees?|payments?|deposits?|scholarships?|exams?|census)\M'
       and c.t !~ '\m(starts?|starting|commencements?|commences?|commencing|begins?|beginning)\M'
       and c.t !~ ('\mintakes?[[:space:]:]+' || p.target)
       and (select count(*) from regexp_matches(c.t, p.full_date, 'g')) = 1
  ), false)
$$;


ALTER FUNCTION "security"."course_deadline_in_quote_v1"("p_date" "date", "p_quote" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_deadline_in_quote_v1"("p_date" "date", "p_quote" "text") IS 'CF-247 P0 Admin #382 (6 Nov 2026): an application closing cue and exactly one full matching date in the same clause are required; commencement, opening, fee/scholarship deadlines, negation and ambiguous multiple dates are refused. Existing quote identity, intake match, locks and admission windows still apply.';



CREATE OR REPLACE FUNCTION "security"."course_deadline_intake_match_v1"("p_label" "text", "p_year" integer, "p_text" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  with n as (select lower(btrim(coalesce(p_label, ''))) l,
                    regexp_replace(regexp_replace(regexp_replace(regexp_replace(lower(coalesce(p_text, '')), '\mone\M', '1', 'g'), '\mtwo\M', '2', 'g'), '\mthree\M', '3', 'g'), '\s+', ' ', 'g') t)
  select n.l <> '' and n.t <> ''
     and case when n.l ~ '^(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*$' then n.t ~ ('\m' || left(n.l, 3))
              else n.t ~ ('\m' || regexp_replace(n.l, '([^a-z0-9 ])', '\\\1', 'g') || '\M') end
     and (p_year is null or n.t !~ '\m(19|20)\d\d\M' or n.t ~ ('\m' || p_year || '\M'))
    from n
$_$;


ALTER FUNCTION "security"."course_deadline_intake_match_v1"("p_label" "text", "p_year" integer, "p_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_deadline_intake_match_v1"("p_label" "text", "p_year" integer, "p_text" "text") IS 'CF-247 Workstream C (3 Nov 2026): whether the page''s intake wording names an intake (its month, or its period words such as Semester 1; a year in the wording must be the intake''s year).';



CREATE OR REPLACE FUNCTION "security"."course_description_capacity_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with s as (
    select security.pipeline_num_v1('layer4.lifecycle_report_days', 7) days, security.pipeline_num_v1('layer4.target_days', 7) target,
           security.layer4_pace_v1() -> 'course_description_first_read' pace, security.pipeline_num_v1('layer4.pace_default_minutes', 3) dflt,
           security.pipeline_num_v1('enrich.course_description_pending_global_max', 0) gmax),
  c as (select class, count(*) n from security.course_description_reconcile_v1(null, false, 0) group by class),
  held as (select count(*) n from pipeline.field_enrich_items e where e.field = 'description' and e.state = 'skipped' and e.reason like 'held_first_admission:%'),
  q as (
    select count(*) filter (where i.status = 'pending') pending,
           count(*) filter (where i.created_at > now() - make_interval(days => s.days::int)) arrived,
           count(*) filter (where i.status in ('approved', 'edited_approved', 'rejected', 'more_evidence', 'returned_layer2', 'returned_layer3') and i.decided_at > now() - make_interval(days => s.days::int) and not exists (select 1 from pipeline.layer4_decisions md where md.review_item_id = i.id and md.layer2_state->>'actor_kind' = 'machine')) decided,
           count(*) filter (where i.status in ('approved', 'edited_approved') and not exists (select 1 from pipeline.layer4_decisions md where md.review_item_id = i.id and md.layer2_state->>'actor_kind' = 'machine')) approved_ever,
           count(*) filter (where i.status in ('approved', 'edited_approved') and exists (select 1 from pipeline.layer4_decisions md where md.review_item_id = i.id and md.layer2_state->>'actor_kind' = 'machine')) approved_by_machine,
           min(i.created_at) filter (where i.status = 'pending') oldest
      from pipeline.layer4_review_items i cross join s where i.entity_type = 'course' and i.field_code = 'course_description_first_read'),
  m as (select s.*, coalesce((s.pace ->> 'minutes')::numeric, s.dflt) mins, case when s.pace is null then 'default' else coalesce(s.pace ->> 'basis', 'default') end basis,
               q.pending, q.arrived, q.decided, q.approved_ever, q.approved_by_machine, q.oldest, h.n held_first, coalesce((select n from c where class = 'ready'), 0) ready
          from s cross join q cross join held h)
  select jsonb_build_object(
    'note', 'Measurement only. A person decides every description; this plans the reviewer time and decides nothing.',
    'pending', m.pending, 'ready', m.ready, 'not_ready', m.pending - m.ready, 'held_first_readings_behind_the_provider_cap', m.held_first,
    'would_wait_for_a_person_after_the_cap_frees', m.pending + m.held_first, 'oldest_waiting', m.oldest,
    'window_days', m.days, 'arrived_in_window', m.arrived, 'arriving_a_day', round(m.arrived / nullif(m.days, 0), 1),
    'decided_in_window', m.decided, 'decided_a_day', round(m.decided / nullif(m.days, 0), 1), 'approved_ever', m.approved_ever, 'approved_by_machine', m.approved_by_machine,
    'minutes_an_item', m.mins, 'pace_basis', m.basis,
    'hours_to_clear_waiting', round(m.pending * m.mins / 60.0, 1),
    'hours_to_clear_waiting_and_held', round((m.pending + m.held_first) * m.mins / 60.0, 1),
    'target_days', m.target,
    'items_a_day_to_clear_waiting_in_target', ceil(m.pending / nullif(m.target, 0)),
    'items_a_day_needed_incl_arrivals', ceil(m.pending / nullif(m.target, 0) + m.arrived / nullif(m.days, 0)),
    'reviewer_hours_a_day_needed', round((m.pending / nullif(m.target, 0) + m.arrived / nullif(m.days, 0)) * m.mins / 60.0, 1),
    'days_to_clear_at_current_decisions', case when m.decided > 0 then round(m.pending / (m.decided / nullif(m.days, 0)), 1) end,
    'back_pressure', jsonb_build_object('global_max', m.gmax, 'on', m.gmax > 0, 'waiting_now', m.pending, 'new_readings_paused', m.gmax > 0 and m.pending >= m.gmax))
  from m
$$;


ALTER FUNCTION "security"."course_description_capacity_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_description_capacity_v1"() IS 'CF-247 C-DESC (8 Nov 2026): review capacity for the course descriptions waiting in Layer 4 (pending, ready, held first readings, arrivals and decisions a day, minutes an item from the Layer 4 pace, hours and items a day to clear within the Layer 4 target, back-pressure state). Read only: decides nothing.';



CREATE OR REPLACE FUNCTION "security"."course_description_check_v1"("p_course" "uuid", "p_result" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 course descriptions (6 Nov 2026): the check is security.course_description_check_with_v1 with the course word lists from settings
  select security.course_description_check_with_v1(p_course, p_result, null, null)
$$;


ALTER FUNCTION "security"."course_description_check_v1"("p_course" "uuid", "p_result" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_description_check_v1"("p_course" "uuid", "p_result" "jsonb") IS 'CF-247 Workstream C (3 Nov 2026): the course description checks (the provider description rules): sentence count, every quote on the page, no unquoted marketing word or claim, complete sentences, each sentence supported by its quote, length within the settings (held, never cut), not another course''s words.';



CREATE OR REPLACE FUNCTION "security"."course_description_check_with_v1"("p_course" "uuid", "p_result" "jsonb", "p_claim_words" "jsonb", "p_marketing_words" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_s jsonb := coalesce(p_result->'sentences', '[]'::jsonb); v_n int; v_text text; s jsonb; t text; v_sup numeric; v_f jsonb; v_other record; v_pid uuid;
        v_min_sup numeric := security.pipeline_num_v1('pdesc.support_min_share', 0.6); v_dup numeric := security.pipeline_num_v1('pdesc.duplicate_share', 0.8);
        v_checks jsonb; v_words text[]; v_title text; v_prov text;
        v_claim jsonb := coalesce(p_claim_words, security.toolset_setting('pipeline', 'enrich.course_description_claim_words'), security.toolset_setting('pipeline', 'pdesc.claim_words'), '[]'::jsonb);
        v_mkt jsonb := coalesce(p_marketing_words, security.toolset_setting('pipeline', 'enrich.course_description_marketing_words'), security.toolset_setting('pipeline', 'pdesc.superlatives'), '[]'::jsonb);
begin
  select c.provider_id, c.canonical_title, coalesce(p.display_name, p.canonical_name) into v_pid, v_title, v_prov
    from catalogue.courses c left join catalogue.providers p on p.id = c.provider_id where c.id = p_course;
  v_n := jsonb_array_length(v_s);
  v_text := (select string_agg(btrim(x->>'text'), ' ' order by o) from jsonb_array_elements(v_s) with ordinality e(x, o));
  v_checks := jsonb_build_object('sentences', v_n, 'chars', length(coalesce(v_text, '')));
  if coalesce((p_result->>'about_course')::boolean, false) is false or v_n = 0 then
    return jsonb_build_object('ok', false, 'rule', 'not_stated', 'checks', v_checks, 'reason', 'the page does not state it');
  end if;
  if v_n < security.pipeline_num_v1('enrich.course_description_min_sentences', 1) or v_n > security.pipeline_num_v1('enrich.course_description_max_sentences', 4) then
    return jsonb_build_object('ok', false, 'rule', 'sentence_count', 'checks', v_checks, 'reason', v_n || ' sentence(s), outside the set range');
  end if;
  for s in select x from jsonb_array_elements(v_s) x loop
    -- the per-sentence tests are security.cdesc_sentence_fault_v1 (the one definition, also used to find the sentences a subset recovery sets aside)
    -- 12 Nov 2026 (QA of #1049): the course's own title and provider are verified facts, not claims: they are left out of the sentence's tests (never added to the quote)
    v_f := security.cdesc_sentence_fault_v1(security.cdesc_known_strip_v1(s->>'text', v_title, v_prov), s->>'quote', coalesce((s->>'on_page')::boolean, false), v_claim, v_mkt, v_min_sup);
    if v_f is not null then
      return jsonb_build_object('ok', false, 'rule', v_f->>'rule', 'checks', v_checks || coalesce(v_f->'checks', '{}'::jsonb), 'reason', v_f->>'reason');
    end if;
  end loop;
  if length(v_text) < security.pipeline_num_v1('enrich.course_description_min_chars', 80) or length(v_text) > security.pipeline_num_v1('enrich.course_description_max_chars', 700) then
    return jsonb_build_object('ok', false, 'rule', 'length', 'checks', v_checks, 'reason', length(v_text) || ' characters, outside the set range (held whole, never cut)');
  end if;
  -- boilerplate: the same words as another course of the provider (held, or waiting in Layer 4)
  -- CF-247 IQ-00053 residual: the new text is split into words once, and each other text inline, by the rule of security.pdesc_words_v1 and
  -- security.pdesc_similarity_v1 (distinct lower-case words of 3 or more letters or digits; shared words over all words of both)
  v_words := security.pdesc_words_v1(v_text);
  select z.course_id, z.sim into v_other from (
    select x.course_id, case when cardinality(v_words) = 0 or cardinality(x.wb) = 0 then 0
                             else round(k.n::numeric / (cardinality(v_words) + cardinality(x.wb) - k.n), 4) end sim
      from (select x0.course_id, array(select distinct w from regexp_split_to_table(lower(coalesce(x0.d, '')), '[^a-z0-9]+') w where length(w) >= 3) wb from (
      select c.id course_id, c.description d, c.updated_at at from catalogue.courses c
       where c.provider_id = v_pid and c.id <> p_course and nullif(btrim(c.description), '') is not null
      union all
      select r.entity_id, r.proposed_value->>'description', r.created_at from pipeline.layer4_review_items r join catalogue.courses c on c.id = r.entity_id
       where r.entity_type = 'course' and r.field_code = 'course_description_first_read' and r.status = 'pending' and c.provider_id = v_pid and r.entity_id <> p_course
      order by 3 desc limit security.pipeline_num_v1('enrich.course_description_duplicate_window', 500)::int) x0) x
      cross join lateral (select count(*) n from unnest(v_words) w where w = any (x.wb)) k) z
   where z.sim >= v_dup order by z.sim desc limit 1;
  if v_other.course_id is not null then
    return jsonb_build_object('ok', false, 'rule', 'duplicate_other_course', 'checks', v_checks || jsonb_build_object('duplicate_of', v_other.course_id, 'similarity', v_other.sim),
      'reason', 'the same words as another course''s description (' || v_other.sim || '): text that is not about this course');
  end if;
  return jsonb_build_object('ok', true, 'rule', 'ok', 'text', v_text, 'checks', v_checks, 'reason', null);
end $$;


ALTER FUNCTION "security"."course_description_check_with_v1"("p_course" "uuid", "p_result" "jsonb", "p_claim_words" "jsonb", "p_marketing_words" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_description_claim_eval_v1"("p_words" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_list jsonb := coalesce(security.toolset_setting('pipeline', 'enrich.course_description_claim_words'), security.toolset_setting('pipeline', 'pdesc.claim_words'), '[]'::jsonb);
        v_cap int := security.pipeline_num_v1('enrich.course_description_report_max', 500)::int; v_ex int := security.pipeline_num_v1('enrich.course_description_examples', 3)::int;
        v_days int := security.pipeline_num_v1('enrich.course_description_held_days', 7)::int; v_out jsonb := '[]'::jsonb; w text; v_rest jsonb; v_one jsonb;
begin
  -- the window of this evaluation is the held-reasons window; the word list is the course list; every other rule runs again on each reading
  for w in select x from jsonb_array_elements_text(coalesce(p_words, v_list)) x loop
    select coalesce(jsonb_agg(x), '[]'::jsonb) into v_rest from jsonb_array_elements_text(v_list) x where x <> w;
    with items as (
      select f.id, f.course_id, f.value from pipeline.field_enrich_items f
       where f.field = 'description' and f.state = 'skipped' and f.reason like 'held: unsupported\_claim%' and f.updated_at >= now() - make_interval(days => v_days)
       order by f.updated_at desc limit v_cap),
    hit as (
      select i.id, i.course_id, i.value,
             (select s->>'text' from jsonb_array_elements(coalesce(i.value->'sentences', '[]'::jsonb)) s where security.pdesc_has_term_v1(s->>'text', w) and not security.pdesc_has_term_v1(s->>'quote', w) limit 1) txt,
             (select s->>'quote' from jsonb_array_elements(coalesce(i.value->'sentences', '[]'::jsonb)) s where security.pdesc_has_term_v1(s->>'text', w) and not security.pdesc_has_term_v1(s->>'quote', w) limit 1) qt,
             (select count(distinct x) from jsonb_array_elements_text(v_list) x, jsonb_array_elements(coalesce(i.value->'sentences', '[]'::jsonb)) s
               where security.pdesc_has_term_v1(s->>'text', x) and not security.pdesc_has_term_v1(s->>'quote', x)) n_words
        from items i),
    h2 as (select hit.* from hit where hit.txt is not null),
    r as (select h2.*, security.course_description_check_with_v1(h2.course_id, h2.value, v_rest, null) chk, coalesce(h2.qt ~* '\m(you|your)\M', false) reader from h2)
    select jsonb_build_object('word', w, 'held', count(*), 'only_this_word', count(*) filter (where r.n_words = 1),
             'passes_every_other_rule_without_it', count(*) filter (where (r.chk->>'ok')::boolean),
             'next_rule', coalesce((select jsonb_object_agg(z.rule, z.n) from (select r2.chk->>'rule' rule, count(*) n from r r2 where not (r2.chk->>'ok')::boolean group by 1) z), '{}'::jsonb),
             'quote_addresses_the_reader', count(*) filter (where r.reader),
             -- suggestions for a person to judge, not a ruling: the page says "you" where the sentence says the word (suggested harmless) or it does not (suggested a real claim)
             'suggested_harmless', coalesce((select jsonb_agg(jsonb_build_object('text', e.txt, 'quote', e.qt)) from (select r3.txt, r3.qt from r r3 where r3.reader order by r3.id limit v_ex) e), '[]'::jsonb),
             'suggested_claim', coalesce((select jsonb_agg(jsonb_build_object('text', e.txt, 'quote', e.qt)) from (select r3.txt, r3.qt from r r3 where not r3.reader order by r3.id limit v_ex) e), '[]'::jsonb))
      into v_one from r;
    if coalesce((v_one->>'held')::int, 0) > 0 then v_out := v_out || jsonb_build_array(v_one); end if;
  end loop;
  return jsonb_build_object('window_days', v_days, 'evaluated_up_to', v_cap, 'words', v_out,
    'note', 'Evaluation only. Removing a word is a Platform Admin decision made as a recorded setting change; every other rule still applies after it.');
end $$;


ALTER FUNCTION "security"."course_description_claim_eval_v1"("p_words" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_description_held_reasons_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with span as (select make_interval(days => security.pipeline_num_v1('enrich.course_description_held_days', 7)::int) s),
  words as (select w from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'enrich.course_description_claim_words'), security.toolset_setting('pipeline', 'pdesc.claim_words'), '[]'::jsonb)) w),
  f as (select x.* from pipeline.field_enrich_items x, span where x.field = 'description' and x.updated_at >= now() - span.s),
  held as (select f.id, f.value, f.value->'check'->>'rule' rule, nullif(f.value->'check'->'checks'->>'chars', '')::int chars, nullif(f.value->'check'->'checks'->>'sentences', '')::int sentences
             from f where f.state = 'skipped' and f.reason like 'held: %'),
  passed as (select f.* from f where f.state in ('review', 'filled') or (f.state = 'skipped' and f.reason like 'held\_first\_admission:%')),
  claim as (
    select words.w word, h.id from held h cross join lateral jsonb_array_elements(coalesce(h.value->'sentences', '[]'::jsonb)) s cross join words
     where h.rule = 'unsupported_claim' and security.pdesc_has_term_v1(s->>'text', words.w) and not security.pdesc_has_term_v1(s->>'quote', words.w)
     group by words.w, h.id)
  select jsonb_build_object(
    'days', (select extract(day from span.s) from span),
    'readings', (select count(*) from passed) + (select count(*) from held),
    'passed_every_check', (select count(*) from passed),
    'held_by_a_check', (select count(*) from held),
    'by_rule', coalesce((select jsonb_object_agg(z.rule, z.n) from (select coalesce(held.rule, 'unknown') rule, count(*) n from held group by 1) z), '{}'::jsonb),
    'too_long_chars', (select jsonb_build_object('held', count(*), 'median', percentile_cont(0.5) within group (order by held.chars), 'p90', percentile_cont(0.9) within group (order by held.chars), 'max', max(held.chars))
                         from held where held.rule = 'length'),
    'too_many_sentences', coalesce((select jsonb_object_agg(z.sentences::text, z.n) from (select held.sentences, count(*) n from held where held.rule = 'sentence_count' group by 1) z), '{}'::jsonb),
    'claim_words', coalesce((select jsonb_object_agg(z.word, z.n) from (select claim.word, count(*) n from claim group by 1) z), '{}'::jsonb),
    'failed', coalesce((select jsonb_object_agg(z.why, z.n) from (select left(coalesce(f.reason, 'no reason recorded'), 80) why, count(*) n from f where f.state = 'failed' group by 1) z), '{}'::jsonb),
    'ai_cost_usd', (select round(coalesce(sum(f.cost_usd), 0)::numeric, 4) from f),
    'ai_cost_per_passing_reading_usd', (select round((coalesce(sum(f.cost_usd), 0) / nullif((select count(*) from passed), 0))::numeric, 5) from f),
    'reask', jsonb_build_object('attempted', (select count(*) from f where f.value ? 'reask'),
                                'now_within_limits', (select count(*) from passed where passed.value ? 'reask'),
                                'still_held', (select count(*) from held h where h.value ? 'reask')),
    'reask_max', security.pipeline_num_v1('enrich.course_description_reask_max', 0))
$$;


ALTER FUNCTION "security"."course_description_held_reasons_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_description_items_v1"("p_provider" "uuid" DEFAULT NULL::"uuid", "p_offset" integer DEFAULT 0, "p_sample" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with r as (
    select q.* from security.course_description_reconcile_v1(p_provider, p_provider is not null, security.pipeline_num_v1('enrich.course_description_report_max', 500)::int) q
     where q.class = 'ready' and (not coalesce(p_sample, false) or q.item_id in (select s.item_id from security.course_description_sample_ids_v1() s))),
  pg as (select r.* from r order by r.created_at, r.item_id limit security.pipeline_num_v1('layer4.inbox_page_size', 25)::int offset greatest(coalesce(p_offset, 0), 0))
  select jsonb_build_object(
    'total', (select count(*) from r),
    'offset', greatest(coalesce(p_offset, 0), 0), 'limit', security.pipeline_num_v1('layer4.inbox_page_size', 25)::int,
    'items', coalesce((select jsonb_agg(jsonb_build_object(
        'kind', 'provider_description', 'ref', pg.item_id::text, 'provider_id', pg.provider_id, 'provider', coalesce(pv.display_name, pv.canonical_name), 'subject', pg.course_title,
        'why', coalesce(nullif(i.escalation_reason, ''), 'Needs a decision'), 'created_at', pg.created_at, 'ready', true,
        'detail', jsonb_strip_nulls(jsonb_build_object('field_code', i.field_code, 'course_id', pg.course_id, 'course_code', c.course_code,
                    'code_label', case when pg.country = 'AU' then 'CRICOS' else 'Course code' end,
                    'before', i.before_value, 'proposed', i.proposed_value, 'evidence_id', i.evidence_id, 'captured_at', ev.captured_at, 'source_url', ev.source_url,
                    'reask', pg.reask, 'in_sample', pg.item_id in (select s.item_id from security.course_description_sample_ids_v1() s),
                    -- the stored reading checked again now, so a card says when its rules have moved since it was proposed
                    'rules_now', case when pg.rechecked then jsonb_build_object('ok', true) else
                                  (select jsonb_build_object('ok', coalesce((z.v->>'ok')::boolean, false), 'rule', z.v->>'rule', 'reason', z.v->>'reason')
                                     from (select security.course_description_check_v1(pg.course_id, e.value) v) z) end)))
        order by pg.created_at, pg.item_id)
      from pg join pipeline.layer4_review_items i on i.id = pg.item_id
      join catalogue.courses c on c.id = pg.course_id
      left join catalogue.providers pv on pv.id = pg.provider_id
      left join pipeline.field_enrich_items e on e.id = pg.enrich_item
      left join pipeline.evidence_artifacts ev on ev.id = i.evidence_id), '[]'::jsonb))
$$;


ALTER FUNCTION "security"."course_description_items_v1"("p_provider" "uuid", "p_offset" integer, "p_sample" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_description_machine_admit_v1"("p_item" "uuid", "p_via" "text" DEFAULT 'settle'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare i pipeline.layer4_review_items%rowtype; c catalogue.courses%rowtype; v jsonb; v_text text; v_after text; v_pub jsonb; v_shown text; v_cc text; v_dec uuid; v_reason text; v_msg text; v_stamp text; v_next text; v_tr boolean; v_sub jsonb;
        v_sys uuid := 'c0ffee00-0000-4000-8000-000000000150'; -- fixed: the system automation account that records Decision 263 rule decisions
        v_rule constant text := 'cdesc-machine-v2'; v_ref constant text := 'CF-247 F-CDESC; Platform Admin decision 10 Nov 2026 (course descriptions: source-verified machine admission)';
        v_days int := security.pipeline_num_v1('gaps.recheck_days', 60)::int; -- derived: a decline is looked at again after the days the queue reads a course again
begin
  if security.pipeline_num_v1('enrich.course_description_machine_on', 0) < 1 then return jsonb_build_object('ok', false, 'rule', 'machine_admission_off'); end if;
  select * into i from pipeline.layer4_review_items where id = p_item for update;
  if i.id is null or i.entity_type <> 'course' or i.field_code <> 'course_description_first_read' then return jsonb_build_object('ok', false, 'rule', 'not_a_course_description_item'); end if;
  if i.status <> 'pending' then return jsonb_build_object('ok', false, 'rule', 'item_not_pending', 'status', i.status); end if;
  select * into c from catalogue.courses where id = i.entity_id for update;
  v_stamp := security.course_description_machine_policy_stamp_v1();
  v := security.course_description_machine_check_v1(p_item);
  if coalesce((v->>'ok')::boolean, false) then
    v_text := v->>'text';
    -- a reading that carries a subset (security.cdesc_subset_recover_v1): the admission says so, in its own via and in its reason
    select f.value->'subset_of_reading' into v_sub from pipeline.field_enrich_items f where f.id = (v->>'reading_item_id')::bigint;
    if v_sub is not null then p_via := 'subset_of_reading'; v_sub := v_sub - 'original'; end if;
    begin
      -- the one write, proved on the row: a guard that put the old text back (a hand lock) must stop the admission, not leave an audit that says it was published
      update catalogue.courses set description = v_text, updated_at = now() where id = c.id and nullif(btrim(description), '') is null;
      select nullif(btrim(x.description), '') into v_after from catalogue.courses x where x.id = c.id;
      if v_after is distinct from v_text then raise exception 'cdesc:description_not_written:the catalogue kept the earlier text (a lock or guard put it back)'; end if;
      -- the consumer read-back (read only): what the website function returns for this course now
      begin v_pub := public.website_v2_course(c.stable_key); exception when others then v_pub := null; end;
      v_shown := v_pub->'item'->>'description';
      v_cc := case when v_pub is null then 'error' when v_pub ? 'error' then 'not_in_feed' when v_shown = v_text then 'matched' when nullif(btrim(v_shown), '') is null then 'lag' else 'mismatch' end;
      if v_cc = 'mismatch' then raise exception 'cdesc:consumer_mismatch:the website function shows different text for this course after the write'; end if;
      update pipeline.layer4_review_items set status = 'approved', decided_at = now() where id = i.id and status = 'pending';
      v_reason := format('Auto (%s, %s): description read from the course''s own stored page %s (content hash %s); right course and page (identity proof and a margin of at least 0.1 over the runner-up), the quote results the worker stored for each sentence, the sentence, length, support and duplicate checks and the wording policy checked again at admission (the page was not read again). Not a person''s decision.',
                         v_rule, coalesce(p_via, 'settle'), coalesce(v->>'source_url', ''), left(coalesce(v->>'content_hash', ''), 12)); -- fixed: a short hash prefix is shown for reading, the full hash is stored
      if v_sub is not null then
        v_reason := v_reason || format(' Subset of the reading: %s of its %s sentences were kept in their original order; set aside: %s. Nothing was reworded, added or cut; the original reading, its quotes and its history are kept.',
                                       v_sub->>'kept_count', v_sub->>'original_count', coalesce((select string_agg('sentence ' || (d->>'index') || ' (' || (d->>'cause') || ')', ', ' order by (d->>'index')::int) from jsonb_array_elements(v_sub->'dropped') d), 'none'));
      end if;
      insert into pipeline.layer4_decisions (review_item_id, action, actor_id, reason, before_value, proposed_value, final_value, evidence_id, layer2_state, layer3_state, change_control_ref)
      values (i.id, 'approve', v_sys, v_reason, i.before_value, i.proposed_value, i.proposed_value, i.evidence_id,
              coalesce(i.layer2_state, '{}'::jsonb) || jsonb_build_object('machine_rule', v_rule, 'actor_kind', 'machine', 'via', coalesce(p_via, 'settle')) || case when v_sub is not null then jsonb_build_object('subset_of_reading', v_sub) else '{}'::jsonb end, coalesce(i.layer3_state, '{}'::jsonb), v_ref) returning id into v_dec;
      insert into pipeline.admin_control_events (area, action, target, detail, actor)
      values ('layer4', 'inbox_decide', i.id::text, jsonb_build_object('kind', 'course_description', 'ref', i.id::text, 'choice', 'approve', 'reason', v_reason, 'course_id', c.id, 'provider_id', c.provider_id,
              'auto', true, 'machine_rule', v_rule, 'actor_kind', 'machine', 'decision_id', v_dec, 'field_code', i.field_code, 'consumer_check', v_cc), v_sys);
      insert into pipeline.search_refresh_signals (entity_type, entity_id, review_decision_id, reason, change_control_ref)
      values ('course', c.id, v_dec, 'Accepted machine-rule Layer 4 canonical change: ' || v_reason, v_ref);
      insert into pipeline.course_description_machine_admissions (course_id, provider_id, review_item_id, reading_item_id, rule, outcome, reason_code, reason, policy_stamp, before_description, after_description, text_md5,
             evidence_id, content_hash, source_url, storage_path, model, prompt_version, worker, checks, recovery, consumer_check, consumer_checked_at, actor)
      values (c.id, c.provider_id, i.id, (v->>'reading_item_id')::bigint, v_rule, 'admitted', 'admitted', v_reason, v_stamp, null, v_text, v->>'text_md5',
              i.evidence_id, v->>'content_hash', v->>'source_url', v->>'storage_path', v->>'model', v->>'prompt_version', v->>'worker',
              coalesce(v->'checks', '{}'::jsonb) || jsonb_build_object('decision_id', v_dec, 'via', coalesce(p_via, 'settle'), 'source_recheck', v->>'source_recheck', 'captured_at', v->>'captured_at') || case when v_sub is not null then jsonb_build_object('subset_of_reading', v_sub) else '{}'::jsonb end,
              'Withdraw with public.admin_course_description_machine_withdraw_v1(course, reason) (Platform Admin): puts the empty description back if no person changed it and no lock was added since.',
              v_cc, now(), v_sys);
      return jsonb_build_object('ok', true, 'rule', v_rule, 'course_id', c.id, 'decision_id', v_dec, 'description_chars', length(v_text), 'consumer_check', v_cc);
    exception when others then
      get stacked diagnostics v_msg = message_text;
      v := security.cdesc_machine_fail_v1(case when v_msg like 'cdesc:%' then split_part(v_msg, ':', 2) else 'admission_error' end,
                                          case when v_msg like 'cdesc:%' then split_part(v_msg, ':', 3) else left(v_msg, 300) end, -- fixed: display width of the stored reason text
                                          'Nothing was written; the item still waits. A person decides in Layer 4, or the next run tries again.', v_msg not like 'cdesc:%' or v_msg like 'cdesc:consumer_mismatch:%'); -- a feed that disagrees is read again after an hour
    end;
  end if;
  -- declined: the item stays waiting with the exact reason on it; recorded once for the item and refreshed
  v_next := coalesce(v->>'next_action', 'A person decides in Layer 4.'); v_tr := coalesce((v->>'transient')::boolean, false);
  v_reason := coalesce(v->>'reason', 'The machine rule did not admit this.');
  insert into pipeline.course_description_machine_admissions (course_id, provider_id, review_item_id, reading_item_id, rule, outcome, reason_code, reason, next_action, transient, retry_after, policy_stamp, text_md5, evidence_id, actor)
  values (c.id, c.provider_id, i.id, case when coalesce(i.proposed_value->>'item_id', '') ~ '^\d+$' then (i.proposed_value->>'item_id')::bigint end, v_rule, 'declined', v->>'rule', v_reason, v_next, v_tr,
          now() + case when v_tr then make_interval(hours => 1) else make_interval(days => v_days) end, -- fixed: a transient decline is looked at again after an hour
          v_stamp, md5(coalesce(i.proposed_value->>'description', '')), i.evidence_id, v_sys)
  on conflict (review_item_id) where outcome = 'declined' do update set rule = excluded.rule, reason_code = excluded.reason_code, reason = excluded.reason, next_action = excluded.next_action, transient = excluded.transient,
         retry_after = excluded.retry_after, policy_stamp = excluded.policy_stamp, text_md5 = excluded.text_md5, evidence_id = excluded.evidence_id, created_at = now();
  update pipeline.layer4_review_items set escalation_reason = left('Machine rule ' || v_rule || ' did not admit this: ' || (v->>'rule') || '. ' || regexp_replace(coalesce(escalation_reason, ''), '^Machine rule [^:]*: [a-z0-9_]+\. ', ''), 1000) -- fixed: the item's reason column shows its first 1000 characters
   where id = i.id and coalesce(escalation_reason, '') not like 'Machine rule ' || v_rule || ' did not admit this: ' || (v->>'rule') || '.%';
  return jsonb_build_object('ok', false, 'rule', v->>'rule', 'reason', v_reason, 'next_action', v_next);
end $_$;


ALTER FUNCTION "security"."course_description_machine_admit_v1"("p_item" "uuid", "p_via" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_description_machine_admit_v1"("p_item" "uuid", "p_via" "text") IS 'CF-247 F-CDESC machine admission of one first course description (rule cdesc-machine-v1): needs the switch on; checks the safe class again under the row locks (from the stored reading and the stored page evidence; the page is not read again), writes the one description, reads it back from the catalogue and from the website function, settles the Layer 4 item as a machine decision under the system automation account and records the ledger row. Declines (item stays waiting, exact reason and next action on it and in the ledger) rather than guess. Never calls the human decision procedure.';



CREATE OR REPLACE FUNCTION "security"."course_description_machine_check_v1"("p_item" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare i pipeline.layer4_review_items%rowtype; c catalogue.courses%rowtype; p catalogue.providers%rowtype; g pipeline.coverage_course_pages%rowtype; e pipeline.evidence_artifacts%rowtype; f pipeline.field_enrich_items%rowtype;
        sc pipeline.course_description_source_checks%rowtype;
        v_rule constant text := 'cdesc-machine-v2'; v_fid bigint; v_text text; v_md5 text; v_chk jsonb; v_pol text; v_sents jsonb; v_share numeric; v_win int; v_words text[]; v_dup record; v_other uuid; v_recheck text := 'not_run'; v_kind text; v_pk text; v_prov jsonb; v_many boolean := false;
        v_days int := security.pipeline_num_v1('gaps.recheck_days', 60)::int; -- derived: a stored page older than the days after which the queue reads the course again is not trusted
begin
  select * into i from pipeline.layer4_review_items where id = p_item;
  if i.id is null or i.entity_type <> 'course' or i.field_code <> 'course_description_first_read' then
    return security.cdesc_machine_fail_v1('not_a_course_description_item', 'This is not a waiting first course description.', 'Nothing to do.'); end if;
  if i.status <> 'pending' then return security.cdesc_machine_fail_v1('item_not_pending', 'The item is already decided (' || i.status || ').', 'Nothing to do.'); end if;
  select * into c from catalogue.courses where id = i.entity_id;
  if c.id is null or c.lifecycle_status <> 'active' then
    return security.cdesc_machine_fail_v1('course_not_active', 'The course is not active.', 'Leave it; the retire job settles proposals for courses that are no longer active.'); end if;
  select * into p from catalogue.providers where id = c.provider_id;
  if p.id is null or p.lifecycle_status <> 'active' or exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id) or security.provider_lifecycle_held_v1(p.id) then
    return security.cdesc_machine_fail_v1('provider_not_live', 'The provider is hidden, held or not active.', 'A person decides in Layer 4 once the provider is live again.'); end if;
  if nullif(btrim(c.description), '') is not null then
    return security.cdesc_machine_fail_v1('description_already_held', 'The course already has a description.', 'The machine rule admits a first description only; the proposal is superseded by the retire job or rejected by a person.'); end if;
  if nullif(btrim(i.before_value->>'description'), '') is not null then
    return security.cdesc_machine_fail_v1('before_value_not_empty', 'The proposal was made over an earlier description.', 'A person decides in Layer 4.'); end if;
  if exists (select 1 from pipeline.layer4_review_items o where o.entity_type = 'course' and o.entity_id = c.id and o.field_code = i.field_code and o.status = 'pending' and o.id <> i.id) then
    return security.cdesc_machine_fail_v1('another_pending_item', 'The course has another waiting description.', 'A person decides which one in Layer 4.'); end if;
  -- hand lock and hold
  if exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = c.id and l.field in ('description', 'course_description', 'all')) then
    return security.cdesc_machine_fail_v1('manual_lock', 'The description is locked by hand.', 'Release the lock first; a person decides.'); end if;
  if exists (select 1 from pipeline.enrichment_flags fl where fl.reason_code = 'manual_hold' and fl.state <> 'released'
              and ((fl.entity = 'course' and fl.entity_key = c.id::text) or (fl.entity = 'provider' and fl.entity_key = p.id::text))) then
    return security.cdesc_machine_fail_v1('manual_hold', 'A person put a hold on the course or its provider.', 'Release the hold first; a person decides.'); end if;
  -- rejection memory: by course, by page, by text, and a withdrawn machine admission. Person decisions only (cdesc-machine-v2, 16 Nov 2026): 'superseded' is the platform's own decision
  if exists (select 1 from pipeline.layer4_review_items o where o.entity_type = 'course' and o.entity_id = c.id and o.field_code = i.field_code and o.status not in ('pending', 'approved', 'edited_approved', 'superseded')) then
    return security.cdesc_machine_fail_v1('rejected_before_course', 'A person decided against an earlier description for this course.', 'A person decides in Layer 4.'); end if;
  if exists (select 1 from pipeline.course_description_machine_admissions a where a.course_id = c.id and a.outcome = 'admitted' and a.withdrawn_at is not null) then
    return security.cdesc_machine_fail_v1('withdrawn_awaiting_person', 'A machine description for this course was withdrawn.', 'A person decides in Layer 4.'); end if;
  if i.evidence_id is not null and exists (select 1 from pipeline.layer4_review_items o where o.field_code = i.field_code and o.evidence_id = i.evidence_id and o.id <> i.id and o.status not in ('pending', 'approved', 'edited_approved', 'superseded')) then
    return security.cdesc_machine_fail_v1('rejected_before_page', 'A person decided against a description read from this same stored page.', 'A person decides in Layer 4.'); end if;
  v_text := nullif(btrim(i.proposed_value->>'description'), '');
  if v_text is null then return security.cdesc_machine_fail_v1('no_description', 'The proposal has no description.', 'A person decides in Layer 4.'); end if;
  v_md5 := md5(security.cdesc_norm_v1(v_text));
  if exists (select 1 from pipeline.layer4_review_items o where o.field_code = i.field_code and o.id <> i.id and o.status not in ('pending', 'approved', 'edited_approved', 'superseded')
               and md5(security.cdesc_norm_v1(o.proposed_value->>'description')) = v_md5) then
    return security.cdesc_machine_fail_v1('rejected_before_text', 'A person decided against this same wording for another course.', 'A person decides in Layer 4.'); end if;
  -- the right course and the right page
  select * into g from pipeline.coverage_course_pages where course_id = c.id;
  if g.course_id is null then return security.cdesc_machine_fail_v1('binding_missing', 'The course has no bound page.', 'The queue binds the page again.', true); end if;
  if g.status = 'ambiguous' then return security.cdesc_machine_fail_v1('binding_ambiguous', 'The page is bound to the course only ambiguously (more than one candidate).', 'A person decides in Layer 4, or the binding is settled first.'); end if;
  if g.status <> 'bound' then return security.cdesc_machine_fail_v1('binding_' || g.status, 'The course page is ' || g.status || ', not bound.', 'The queue binds the page again.', true); end if;
  if g.provider_id is distinct from c.provider_id then return security.cdesc_machine_fail_v1('binding_other_provider', 'The bound page belongs to another provider.', 'A person decides in Layer 4.'); end if;
  if g.read_status is distinct from 'read' then return security.cdesc_machine_fail_v1('page_not_read', 'The bound page is not marked read.', 'The queue reads the page again.', true); end if;
  if not security.coverage_identity_allowed(c.provider_id, g.identity_basis, 'description') then
    return security.cdesc_machine_fail_v1('identity_not_allowed', 'The page''s proof (' || coalesce(g.identity_basis, 'none') || ') does not admit a description for this country.', 'A person decides in Layer 4.'); end if;
  -- how firmly the page was matched to this course: an AI match, or a runner-up page scoring close to the chosen one, is not a clear identity
  -- a page bound by the course's own CRICOS code on the page (Decision 265) is a code proof, not a score contest: the margin does not apply to it while no other course is bound to the same address
  if g.basis = 'ai_match' or (g.score is not null and g.runner_up is not null and g.score - g.runner_up < 0.1
                              and not (g.basis = 'cricos_code_on_page' and not exists (select 1 from pipeline.coverage_course_pages g2 where g2.provider_id = g.provider_id and g2.course_id <> g.course_id
                                                                                                                       and (g2.url = g.url or lower(regexp_replace(regexp_replace(g2.url, '[?#].*$', ''), '/+$', '')) = lower(regexp_replace(regexp_replace(g.url, '[?#].*$', ''), '/+$', ''))
                                                                                                                            or (g2.evidence_id is not null and g2.evidence_id = g.evidence_id))))) then -- fixed: a margin under 0.1 between the chosen page and the runner-up is not a clear match; no setting exists for it and none is added (10 Nov 2026 05:40 rule)
    return security.cdesc_machine_fail_v1('identity_margin_thin', 'The page was matched by an AI match or by a score under 0.1 above the next candidate (' || coalesce(g.basis, 'no basis') || ', score ' || coalesce(g.score::text, 'none') || ', runner-up ' || coalesce(g.runner_up::text, 'none') || ').', 'A person decides in Layer 4.'); end if;
  if g.evidence_id is distinct from i.evidence_id then
    return security.cdesc_machine_fail_v1('evidence_moved', 'The course''s bound page copy changed after this description was read.', 'The queue reads the new copy; the old proposal is superseded or decided by a person.', true); end if;
  if i.proposed_value->>'source_url' is distinct from g.url then
    return security.cdesc_machine_fail_v1('page_url_changed', 'The page address the description was read from is no longer the bound address.', 'A person decides in Layer 4.'); end if;
  -- the kind of page: a requirements, entry, fees, how-to-apply or programme-structure page is not a course overview, so its text is not a description of the course
  select seg.s into v_kind from regexp_split_to_table(lower(regexp_replace(split_part(split_part(coalesce(g.url, ''), '#', 1), '?', 1), '^[a-z][a-z0-9+.-]*://[^/]*', '')), '/') seg(s)
   where seg.s ~ '^(entry|entry-requirements|admission-requirements|requirements|fees|tuition-fees|how-to-apply|programme-structure|program-structure|course-structure)$' limit 1; -- fixed: the page kinds a person decides (10 Nov 2026); a quality rule, no setting exists and none is added
  if v_kind is not null then
    return security.cdesc_machine_fail_v1('wrong_page_kind', 'The description was read from a page whose address has the part "' || v_kind || '" (' || coalesce(g.url, 'no address') || '), so it is not the course overview.', 'A person decides in Layer 4.'); end if;
  -- the page must be a page about THIS course: not a university About / Overview page, not a page with no address (security.cdesc_page_kind_v1)
  v_pk := security.cdesc_page_kind_v1(g.url, c.canonical_title, g.identity_basis);
  if v_pk is not null then
    return security.cdesc_machine_fail_v1('wrong_page_kind', 'The bound page is not a page about this course (' || v_pk || '; ' || coalesce(g.url, 'no address') || ').', 'A person decides in Layer 4.'); end if;
  v_fid := case when coalesce(i.proposed_value->>'item_id', '') ~ '^\d+$' then (i.proposed_value->>'item_id')::bigint end;
  select * into f from pipeline.field_enrich_items where id = v_fid;
  if f.id is null or f.field <> 'description' then return security.cdesc_machine_fail_v1('reading_missing', 'The reading behind the proposal is not available.', 'A person decides in Layer 4.'); end if;
  if f.course_id is distinct from c.id then return security.cdesc_machine_fail_v1('reading_other_course', 'The reading belongs to another course.', 'A person decides in Layer 4.'); end if;
  if f.state <> 'review' then return security.cdesc_machine_fail_v1('reading_not_current', 'The reading is in state ' || f.state || ', not waiting.', 'A person decides in Layer 4.'); end if;
  if f.evidence_id is distinct from i.evidence_id then return security.cdesc_machine_fail_v1('reading_other_evidence', 'The reading was made on a different page copy than the proposal names.', 'A person decides in Layer 4.'); end if;
  if nullif(btrim(f.value->>'text'), '') is distinct from v_text then return security.cdesc_machine_fail_v1('text_changed', 'The proposal text differs from the reading it came from.', 'A person decides in Layer 4.'); end if;
  -- the reader: recorded on the item, else on the reading, else the stored AI answer that holds exactly this reading's sentences
  v_prov := security.cdesc_reading_provenance_v1(f.id, f.value, i.layer3_state);
  if nullif(v_prov->>'model', '') is null or nullif(v_prov->>'prompt', '') is null then
    return security.cdesc_machine_fail_v1('reader_unrecorded', 'The reader''s model or prompt version is not recorded.', 'A person decides in Layer 4.'); end if;
  -- the stored page: immutable lineage, present, recent
  select * into e from pipeline.evidence_artifacts where id = i.evidence_id;
  if e.id is null or nullif(btrim(e.storage_path), '') is null or nullif(btrim(e.content_hash), '') is null then
    return security.cdesc_machine_fail_v1('page_not_stored', 'The stored page copy has no object or content hash.', 'The queue reads the course page again.', true); end if;
  if position(e.content_hash in e.storage_path) = 0 then
    return security.cdesc_machine_fail_v1('lineage_hash_mismatch', 'The stored object''s address does not carry the evidence content hash.', 'A person decides in Layer 4.'); end if;
  if not exists (select 1 from storage.objects o where o.bucket_id = 'evidence' and o.name = e.storage_path) then
    return security.cdesc_machine_fail_v1('object_missing', 'The stored page object is not in storage.', 'The queue reads the course page again.', true); end if;
  if coalesce(e.captured_at, e.created_at) < now() - make_interval(days => v_days) then
    return security.cdesc_machine_fail_v1('evidence_stale', 'The stored page was captured more than ' || v_days || ' days ago.', 'The queue reads the page again; the description is checked on the new copy.', true); end if;
  -- optional independent re-read of the page (nothing writes this table yet): the latest row for this evidence, if there is one
  select * into sc from pipeline.course_description_source_checks s where s.evidence_id = e.id and s.course_id = c.id order by s.checked_at desc limit 1;
  if sc.id is not null then
    if sc.result <> 'confirmed' then return security.cdesc_machine_fail_v1('source_recheck_failed', 'A re-read of the stored page did not confirm the quotes (' || sc.result || ').', 'The queue reads the course page again; a person decides if it persists.', true); end if;
    -- a confirmation counts only if it is recent and it read the very object the evidence names
    if sc.checked_at < now() - make_interval(days => v_days) or sc.content_hash_read is distinct from e.content_hash then
      return security.cdesc_machine_fail_v1('source_recheck_unusable', 'The recorded re-read of the page is older than ' || v_days || ' days or read a different copy (hash read ' || coalesce(left(sc.content_hash_read, 12), 'none') || ', evidence hash ' || left(e.content_hash, 12) || ').', 'Read the page again; a person decides meanwhile.', true); end if;
    v_recheck := 'confirmed';
  end if;
  -- every sentence: the on_page result the worker stored for each quote, supported, complete, in range (the live check, run again now on the stored reading; the page is not read again here)
  v_chk := security.course_description_check_v1(c.id, f.value);
  if not coalesce((v_chk->>'ok')::boolean, false) then
    return security.cdesc_machine_fail_v1('check_' || coalesce(v_chk->>'rule', 'failed'), coalesce(v_chk->>'reason', 'The text check refused it.'), 'A person decides in Layer 4.'); end if;
  if v_chk->>'text' is distinct from v_text then return security.cdesc_machine_fail_v1('text_changed', 'The checked text differs from the proposal.', 'A person decides in Layer 4.'); end if;
  -- the admission policy: claims, ranking, accreditation, outcomes, campus words, markup and figures
  v_sents := coalesce(f.value->'sentences', '[]'::jsonb);
  v_pol := security.cdesc_machine_text_check_v1(p.id, v_text, v_sents);
  if v_pol is not null then
    return security.cdesc_machine_fail_v1('policy_' || split_part(v_pol, ':', 1), 'The wording has a word, figure or markup the admission policy does not admit (' || v_pol || ').', 'A person decides in Layer 4.'); end if;
  -- catalogue-wide duplicates: exact (any course, described or waiting) and near (other providers; this provider is covered by the live check above)
  select d.id into v_other from catalogue.courses d where d.id <> c.id and nullif(btrim(d.description), '') is not null and md5(security.cdesc_norm_v1(d.description)) = v_md5 limit 1;
  if v_other is not null then
    return security.cdesc_machine_fail_v1('duplicate_exact_described', 'Another course already holds exactly this wording (shared qualification wording).', 'A person decides in Layer 4.'); end if;
  -- a twin that waits is only a reason to wait when it is OLDER and can still be admitted; otherwise two courses with the same wording would decline each other for good
  -- wording that waits at three or more different providers is shared training-package wording: nothing is tie-broken, every waiting twin blocks as before
  select count(distinct c3.provider_id) >= 3 into v_many from pipeline.layer4_review_items o3 join catalogue.courses c3 on c3.id = o3.entity_id
   where o3.field_code = i.field_code and o3.status = 'pending' and md5(security.cdesc_norm_v1(o3.proposed_value->>'description')) = v_md5;
  select o.entity_id into v_other from pipeline.layer4_review_items o where o.field_code = i.field_code and o.status = 'pending' and o.entity_id <> c.id and md5(security.cdesc_norm_v1(o.proposed_value->>'description')) = v_md5
     and (v_many or ((o.created_at, o.id) < (i.created_at, i.id) and not security.cdesc_parked_other_v1(o.id))) limit 1;
  if v_other is not null then
    return security.cdesc_machine_fail_v1('duplicate_exact_waiting', 'Another waiting description has exactly this wording (shared qualification wording).', 'A person decides in Layer 4.'); end if;
  v_share := security.pipeline_num_v1('pdesc.duplicate_share', 0.8); v_win := security.pipeline_num_v1('enrich.course_description_duplicate_window', 500)::int; v_words := security.pdesc_words_v1(v_text);
  select z.course_id, z.sim into v_dup from (
    select x.course_id, round(k.n::numeric / (cardinality(v_words) + cardinality(x.wb) - k.n), 4) sim
      from (select x0.course_id, array(select distinct w from regexp_split_to_table(lower(coalesce(x0.d, '')), '[^a-z0-9]+') w where length(w) >= 3) wb
              from (select * from (select r.entity_id course_id, r.proposed_value->>'description' d from pipeline.layer4_review_items r join catalogue.courses c2 on c2.id = r.entity_id
                                    where r.field_code = i.field_code and (r.status in ('approved', 'edited_approved') or (r.status = 'pending' and (v_many or ((r.created_at, r.id) < (i.created_at, i.id) and not security.cdesc_parked_other_v1(r.id))))) and r.entity_id <> c.id and c2.provider_id <> c.provider_id
                                    order by r.created_at desc limit v_win) w1
                    union all -- and the descriptions the catalogue holds for other providers (however they arrived), newest first, within the same window
                    select * from (select d2.id course_id, d2.description d from catalogue.courses d2
                                    where nullif(btrim(d2.description), '') is not null and d2.id <> c.id and d2.provider_id <> c.provider_id
                                    order by d2.updated_at desc limit v_win) w2) x0) x
      cross join lateral (select count(*) n from unnest(v_words) w where w = any (x.wb)) k
     where cardinality(v_words) > 0 and cardinality(x.wb) > 0) z
   where z.sim >= v_share order by z.sim desc limit 1;
  if v_dup.course_id is not null then
    return security.cdesc_machine_fail_v1('duplicate_near_other_provider', 'The wording is almost the same as another provider''s course description (' || v_dup.sim || ').', 'A person decides in Layer 4.'); end if;
  return jsonb_build_object('ok', true, 'rule', v_rule, 'course_id', c.id, 'provider_id', p.id, 'review_item_id', i.id, 'reading_item_id', f.id, 'text', v_text, 'text_md5', md5(v_text),
    'evidence_id', e.id, 'content_hash', e.content_hash, 'storage_path', e.storage_path, 'source_url', g.url, 'captured_at', coalesce(e.captured_at, e.created_at),
    'model', v_prov->>'model', 'prompt_version', v_prov->>'prompt', 'worker', v_prov->>'worker', 'source_recheck', v_recheck,
    'checks', coalesce(v_chk->'checks', '{}'::jsonb) || jsonb_build_object('identity_basis', g.identity_basis, 'binding', g.status, 'policy', 'ok'));
end $_$;


ALTER FUNCTION "security"."course_description_machine_check_v1"("p_item" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_description_machine_check_v1"("p_item" "uuid") IS 'CF-247 F-CDESC machine rule cdesc-machine-v1, the safe class (read only): for one waiting first course description, ok with the evidence it rests on, or the exact reason code and next action: course and provider live, description still empty, no hand lock, hold or earlier rejection (by course, page or wording), the page bound (not ambiguous), read, identity allowed, matched with a margin of at least 0.1 over the runner-up (a margin under 0.1 declines) and not by AI match, unchanged, stored with its content hash in the object address, present in storage and recent (gaps.recheck_days), the quote results the worker stored for each sentence and the support, length and in-provider duplicate checks (the live text check, run again on the stored reading; the page itself is not read again), the admission policy for claims and figures, no exact duplicate anywhere in the catalogue, no near duplicate (word overlap at pdesc.duplicate_share) among other providers'' waiting or approved proposals and described courses within the comparison window enrich.course_description_duplicate_window (older text or a paraphrase is not caught), and an optional recorded re-read of the page (a failed one declines; a confirmed one counts only if recent and for the same content hash). Changes nothing.';



CREATE OR REPLACE FUNCTION "security"."course_description_machine_consumer_recheck_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_pub jsonb; v_shown text; v_cc text; v_n int := 0; v_ok int := 0; v_t0 timestamptz := clock_timestamp();
        v_cap int := security.pipeline_num_v1('enrich.course_text_items_per_day', 500)::int; v_days int := security.pipeline_num_v1('gaps.recheck_days', 60)::int; -- derived
begin
  if security.pipeline_num_v1('enrich.course_description_machine_on', 0) < 1 then return jsonb_build_object('on', false); end if;
  for r in select a.id, a.after_description, c.stable_key from pipeline.course_description_machine_admissions a join catalogue.courses c on c.id = a.course_id
            where a.outcome = 'admitted' and a.withdrawn_at is null and a.consumer_check is distinct from 'matched'
              and (a.consumer_checked_at is null or a.consumer_checked_at < now() - case when a.consumer_check = 'not_in_feed' then make_interval(days => v_days) else make_interval(hours => 1) end) -- fixed: a lag is read again after an hour
            order by a.consumer_checked_at nulls first limit v_cap loop
    exit when clock_timestamp() - v_t0 > make_interval(secs => 15) -- fixed: a follow-up, not the main work of the run
      or clock_timestamp() - statement_timestamp() > make_interval(secs => 100); -- fixed (11 Nov 2026): and never past 100 s into the job's statement (its limit is 120 s)
    begin v_pub := public.website_v2_course(r.stable_key); exception when others then v_pub := null; end;
    v_shown := v_pub->'item'->>'description';
    v_cc := case when v_pub is null then 'error' when v_pub ? 'error' then 'not_in_feed' when v_shown = r.after_description then 'matched' when nullif(btrim(v_shown), '') is null then 'lag' else 'mismatch' end;
    update pipeline.course_description_machine_admissions set consumer_check = v_cc, consumer_checked_at = now() where id = r.id;
    v_n := v_n + 1; if v_cc = 'matched' then v_ok := v_ok + 1; end if;
  end loop;
  return jsonb_build_object('on', true, 'rechecked', v_n, 'matched', v_ok);
end $$;


ALTER FUNCTION "security"."course_description_machine_consumer_recheck_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_description_machine_consumer_recheck_v1"() IS 'CF-247 F-CDESC: reads the website function again for machine-admitted descriptions whose read-back was a lag, an error or not in the feed, and records what it shows (matched, lag, mismatch, not_in_feed, error). Read only against the consumer API.';



CREATE OR REPLACE FUNCTION "security"."course_description_machine_policy_stamp_v1"() RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- a fingerprint of every setting the rule reads, so a declined item is looked at again when (and only when) the policy changes
  select md5('cdesc-machine-v2|' || coalesce(string_agg(s.key || '=' || s.value::text, '|' order by s.key), ''))
    from pipeline.platform_toolset_settings s
   where s.toolset_key = 'pipeline' and (s.key like 'enrich.course_description\_%' escape '\' and s.key <> 'enrich.course_description_machine_on'
         or s.key in ('pdesc.claim_words', 'pdesc.superlatives', 'pdesc.evidence_claim_words', 'pdesc.machine_refused_words', 'pdesc.machine_refused_words_fr', 'pdesc.machine_neutral_words',
                      'pdesc.machine_numbers_allowed', 'pdesc.founded_year_min', 'pdesc.support_min_share', 'pdesc.duplicate_share', 'gaps.recheck_days'))
$$;


ALTER FUNCTION "security"."course_description_machine_policy_stamp_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_description_machine_policy_stamp_v1"() IS 'CF-247 F-CDESC: md5 of every setting the machine rule reads (not its own switch). A declined item is evaluated again when the stamp changed, when the decline is transient, or after gaps.recheck_days.';



CREATE OR REPLACE FUNCTION "security"."course_description_machine_report_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('contract', 'course-description-machine-report-v1', 'as_at', now(), 'switch_on', security.pipeline_num_v1('enrich.course_description_machine_on', 0) >= 1,
    'admitted', (select count(*) from pipeline.course_description_machine_admissions where outcome = 'admitted' and withdrawn_at is null),
    'admitted_24h', (select count(*) from pipeline.course_description_machine_admissions where outcome = 'admitted' and withdrawn_at is null and created_at > now() - make_interval(hours => 24)), -- fixed: report window
    'admitted_7d', (select count(*) from pipeline.course_description_machine_admissions where outcome = 'admitted' and withdrawn_at is null and created_at > now() - make_interval(days => 7)), -- fixed: report window
    'withdrawn', (select count(*) from pipeline.course_description_machine_admissions where outcome = 'admitted' and withdrawn_at is not null),
    'admitted_by_provider', (select count(distinct provider_id) from pipeline.course_description_machine_admissions where outcome = 'admitted' and withdrawn_at is null),
    'website', (select coalesce(jsonb_object_agg(k, n), '{}'::jsonb) from (select coalesce(consumer_check, 'unchecked') k, count(*) n from pipeline.course_description_machine_admissions where outcome = 'admitted' and withdrawn_at is null group by 1) z),
    'declined_by_reason', (select coalesce(jsonb_object_agg(k, n), '{}'::jsonb) from (select d.reason_code k, count(*) n from pipeline.course_description_machine_admissions d
                             join pipeline.layer4_review_items li on li.id = d.review_item_id and li.status = 'pending' where d.outcome = 'declined' group by 1) z),
    'waiting_items', (select count(*) from pipeline.layer4_review_items where field_code = 'course_description_first_read' and entity_type = 'course' and status = 'pending'))
$$;


ALTER FUNCTION "security"."course_description_machine_report_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_description_machine_report_v1"() IS 'CF-247 F-CDESC scoreboard (read only): machine-admitted course descriptions (total, 24 hours, 7 days, providers, withdrawn), their Website read-back state, why waiting items were declined, and how many items wait.';



CREATE OR REPLACE FUNCTION "security"."course_description_machine_run_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_a jsonb; v_b jsonb; v_h jsonb; v_s jsonb; v_p jsonb;
begin
  if security.pipeline_num_v1('enrich.course_description_machine_on', 0) < 1 then return jsonb_build_object('on', false); end if;
  -- one failure never stops the run: each part reports its own error
  -- cdesc-source-grounded-v1 (CF-247 F-CDESC, 12 Nov 2026): waiting descriptions an earlier prompt made that the machine declined for good are superseded and read again
  begin v_p := security.cdesc_prompt_supersede_v1(); exception when others then v_p := jsonb_build_object('error', sqlerrm); end;
  begin v_h := security.cdesc_recheck_held_v1(); exception when others then v_h := jsonb_build_object('error', sqlerrm); end;
  begin v_s := security.cdesc_subset_recover_v1(); exception when others then v_s := jsonb_build_object('error', sqlerrm); end;
  begin v_a := security.course_description_machine_settle_v1(); exception when others then v_a := jsonb_build_object('error', sqlerrm); end;
  begin v_b := security.course_description_machine_consumer_recheck_v1(); exception when others then v_b := jsonb_build_object('error', sqlerrm); end;
  return jsonb_build_object('on', true, 'prompt', v_p, 'held', v_h, 'subset', v_s, 'settle', v_a, 'consumer', v_b);
end $$;


ALTER FUNCTION "security"."course_description_machine_run_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_description_machine_run_v1"() IS 'CF-247 F-CDESC: one run of the catalogued job course-description-machine: settle the waiting first course descriptions, then follow up the Website read-backs that lagged. Does nothing while enrich.course_description_machine_on is 0.';



CREATE OR REPLACE FUNCTION "security"."course_description_machine_settle_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_res jsonb; v_ok int := 0; v_no int := 0; v_err int := 0; v_t0 timestamptz := clock_timestamp(); v_stamp text := security.course_description_machine_policy_stamp_v1();
        v_cap int := security.pipeline_num_v1('enrich.course_text_items_per_day', 500)::int; -- derived: never more in a run than the platform reads in a day
begin
  if security.pipeline_num_v1('enrich.course_description_machine_on', 0) < 1 then return jsonb_build_object('on', false); end if;
  for r in select li.id from pipeline.layer4_review_items li
             left join pipeline.course_description_machine_admissions d on d.review_item_id = li.id and d.outcome = 'declined'
            where li.field_code = 'course_description_first_read' and li.entity_type = 'course' and li.status = 'pending'
              and (d.id is null or d.policy_stamp is distinct from v_stamp or d.retry_after <= now())
            order by (d.id is not null), li.created_at, li.id limit v_cap loop
    exit when clock_timestamp() - v_t0 > make_interval(secs => 40) -- fixed: stays well inside the 120 s statement time-out of a job; the rest is taken next run
      or clock_timestamp() - statement_timestamp() > make_interval(secs => 85); -- fixed (11 Nov 2026): and never past 85 s into the job's statement, whatever ran before it, so the read-back and the run end well inside 120 s
    begin
      v_res := security.course_description_machine_admit_v1(r.id, 'settle');
      if coalesce((v_res->>'ok')::boolean, false) then v_ok := v_ok + 1; else v_no := v_no + 1; end if;
    exception when others then v_err := v_err + 1;
    end;
  end loop;
  return jsonb_build_object('on', true, 'admitted', v_ok, 'left_for_a_person', v_no, 'errors', v_err);
end $$;


ALTER FUNCTION "security"."course_description_machine_settle_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_description_machine_settle_v1"() IS 'CF-247 F-CDESC: checks the waiting first course descriptions against the machine rule, undecided items first, as many as a 40 second time box and enrich.course_text_items_per_day allow; those that pass are admitted and settled as machine decisions, the rest stay for a person with the reason on the item. A declined item is looked at again when the policy changed, when the decline was transient, or after gaps.recheck_days.';



CREATE OR REPLACE FUNCTION "security"."course_description_machine_shadow_v1"("p_limit" integer DEFAULT NULL::integer, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v jsonb; v_lim int := coalesce(p_limit, 200); -- fixed: a report page, the evaluation is the bounded cost
        v_by jsonb := '{}'::jsonb; v_ok int := 0; v_n int := 0; v_sample jsonb := '[]'::jsonb; v_total int; v_prov jsonb := '{}'::jsonb; v_held int; v_held_policy int; hr record;
begin
  select count(*) into v_total from pipeline.layer4_review_items li where li.field_code = 'course_description_first_read' and li.entity_type = 'course' and li.status = 'pending';
  for r in select li.id, li.entity_id from pipeline.layer4_review_items li where li.field_code = 'course_description_first_read' and li.entity_type = 'course' and li.status = 'pending'
            order by li.created_at, li.id limit v_lim offset greatest(coalesce(p_offset, 0), 0) loop
    v := security.course_description_machine_check_v1(r.id);
    v_n := v_n + 1;
    if (v->>'ok')::boolean then
      v_ok := v_ok + 1;
      if jsonb_array_length(v_sample) < 5 then v_sample := v_sample || jsonb_build_array(jsonb_build_object('review_item_id', r.id, 'course_id', r.entity_id, 'chars', length(v->>'text'))); end if;
    else
      v_by := jsonb_set(v_by, array[v->>'rule'], to_jsonb(coalesce((v_by->>(v->>'rule'))::int, 0) + 1));
    end if;
  end loop;
  -- readings held at the provider's waiting cap: not yet items; counted, and how many pass the wording policy alone
  select count(*) into v_held from pipeline.field_enrich_items e where e.field = 'description' and e.state = 'skipped' and e.reason like 'held_first_admission:%' and nullif(btrim(e.value->>'text'), '') is not null;
  select count(*) into v_held_policy from pipeline.field_enrich_items e where e.field = 'description' and e.state = 'skipped' and e.reason like 'held_first_admission:%' and nullif(btrim(e.value->>'text'), '') is not null
     and security.pdesc_machine_text_check_ctx_v1(e.provider_id, e.value->>'text', '{}', coalesce(e.value->'sentences', '[]'::jsonb)) is null;
  return jsonb_build_object('contract', 'course-description-machine-shadow-v1', 'rule', 'cdesc-machine-v2', 'as_at', now(), 'switch_on', security.pipeline_num_v1('enrich.course_description_machine_on', 0) >= 1,
    'waiting_items', v_total, 'examined', v_n, 'offset', greatest(coalesce(p_offset, 0), 0), 'would_admit', v_ok, 'stay_for_a_person', v_n - v_ok, 'by_reason', v_by, 'sample_would_admit', v_sample,
    'held_readings', jsonb_build_object('count', v_held, 'pass_wording_policy', v_held_policy, 'note', 'held at the provider''s waiting cap; promoted to items by the existing promote-held step as room appears, then evaluated like any waiting item'),
    'next_offset', case when greatest(coalesce(p_offset, 0), 0) + v_n < v_total then greatest(coalesce(p_offset, 0), 0) + v_n end);
end $$;


ALTER FUNCTION "security"."course_description_machine_shadow_v1"("p_limit" integer, "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_description_machine_shadow_v1"("p_limit" integer, "p_offset" integer) IS 'CF-247 F-CDESC shadow report (read only, changes nothing, works with the switch off): runs the safe-class evaluator over the waiting first course descriptions (a page of p_limit from p_offset, 200 by default) and returns how many would be admitted, why the rest stay for a person (reason codes), a sample, and the held readings. Page through with next_offset.';



CREATE OR REPLACE FUNCTION "security"."course_description_machine_trg_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_item uuid;
begin
  if pg_trigger_depth() > 5 then return null; end if; -- fixed: a bound on nested trigger chains (promote-held inside an admission); the job takes the rest
  if security.pipeline_num_v1('enrich.course_description_machine_on', 0) < 1 then return null; end if;
  -- 11 Nov 2026 (CF-247 F-CDESC throughput): a reading recorded through the API (the AI worker's svc_enrich_ai_record, many answers in one call under the API statement time-out) is not admitted inside that call:
  -- a time-out there is not caught below and cancelled every answer of the call. The job course-description-machine admits it (settle, undecided items first). Readings the job itself records are admitted here as before.
  if nullif(current_setting('request.method', true), '') is not null then return null; end if;
  v_item := case when coalesce(new.value->>'review_item_id', '') ~ '^[0-9a-f-]{36}$' then (new.value->>'review_item_id')::uuid end;
  if v_item is null then return null; end if;
  begin perform security.course_description_machine_admit_v1(v_item, 'fresh_reading');
  exception when others then null; -- the reading stays waiting for a person (or the next run); recording it never fails
  end;
  return null;
end $_$;


ALTER FUNCTION "security"."course_description_machine_trg_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_description_machine_trg_v1"() IS 'CF-247 F-CDESC: after a course description reading reaches Layer 4 (state review), admits it at once under the machine rule while enrich.course_description_machine_on is 1, when the job records it (subset recovery, held recheck). A reading recorded through the API (the AI worker) is left waiting and admitted by the job course-description-machine (settle) on its next run, so the worker''s recording call never waits on the admission. Off: does nothing. Errors are swallowed; the reading stays waiting.';



CREATE OR REPLACE FUNCTION "security"."course_description_machine_withdraw_v1"("p_course" "uuid", "p_reason" "text", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a pipeline.course_description_machine_admissions%rowtype; v_now text; v_after text; v_dec uuid;
begin
  if p_actor is null or p_actor = 'c0ffee00-0000-4000-8000-000000000150'::uuid then raise exception 'the person who withdraws must be named'; end if; -- fixed: the system automation account (Decision 263) is not a person
  if nullif(btrim(p_reason), '') is null then raise exception 'give a reason (kept in the log)'; end if;
  select * into a from pipeline.course_description_machine_admissions where course_id = p_course and outcome = 'admitted' and withdrawn_at is null for update;
  if a.id is null then return jsonb_build_object('ok', false, 'rule', 'no_live_machine_admission'); end if;
  select nullif(btrim(c.description), '') into v_now from catalogue.courses c where c.id = p_course for update;
  if v_now is distinct from a.after_description then return jsonb_build_object('ok', false, 'rule', 'description_changed_since_admission', 'reason', 'A person changed the description since the machine admitted it; it is kept.'); end if;
  if exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = p_course and l.field in ('description', 'course_description', 'all')) then
    return jsonb_build_object('ok', false, 'rule', 'manual_lock', 'reason', 'The description has been locked by hand since the machine admitted it; it is kept. Release the lock first.'); end if;
  v_dec := nullif(a.checks->>'decision_id', '')::uuid;
  if v_dec is null then raise exception 'the admission has no decision to point the search refresh at'; end if;
  update catalogue.courses set description = a.before_description, updated_at = now() where id = p_course;
  select nullif(btrim(c.description), '') into v_after from catalogue.courses c where c.id = p_course;
  if v_after is distinct from nullif(btrim(a.before_description), '') then raise exception 'withdraw_not_applied: the catalogue kept the description; nothing was changed'; end if;
  update pipeline.course_description_machine_admissions set withdrawn_at = now(), withdrawn_by = p_actor, withdrawn_reason = btrim(p_reason) where id = a.id;
  insert into pipeline.admin_control_events (area, action, target, detail, actor)
  values ('layer4', 'cdesc_machine_withdraw', p_course::text, jsonb_build_object('admission_id', a.id, 'review_item_id', a.review_item_id, 'rule', a.rule, 'before', a.before_description, 'after', a.after_description, 'reason', btrim(p_reason), 'withdrawn_by', p_actor), p_actor);
  -- production keeps ONE search refresh signal for each decision (UNIQUE review_decision_id): the signal the admission queued is queued again for the same decision
  insert into pipeline.search_refresh_signals as s (entity_type, entity_id, review_decision_id, reason, change_control_ref)
  values ('course', p_course, v_dec, 'Machine course description withdrawn: ' || btrim(p_reason), 'CF-247 F-CDESC withdrawal')
  on conflict (review_decision_id) do update set status = case when s.status = 'processing' then s.status else 'queued' end, completed_at = null, reason = excluded.reason, change_control_ref = excluded.change_control_ref;
  return jsonb_build_object('ok', true, 'course_id', p_course, 'admission_id', a.id, 'restored', a.before_description, 'withdrawn_by', p_actor);
end $$;


ALTER FUNCTION "security"."course_description_machine_withdraw_v1"("p_course" "uuid", "p_reason" "text", "p_actor" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_description_machine_withdraw_v1"("p_course" "uuid", "p_reason" "text", "p_actor" "uuid") IS 'CF-247 F-CDESC rollback of one machine-admitted course description: restores the earlier (empty) text if no person changed it since and no hand lock was added, proves the row changed, records the named person and why, queues the search refresh again on the admission''s own decision, and holds the course out of further automatic admission until a person decides. One course at a time. Not callable from the app; use public.admin_course_description_machine_withdraw_v1.';



CREATE OR REPLACE FUNCTION "security"."course_description_pack_v1"("p_provider" "uuid" DEFAULT NULL::"uuid", "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  with cfg as (
    select coalesce(security.toolset_setting('pipeline', 'enrich.course_description_claim_words'), security.toolset_setting('pipeline', 'pdesc.claim_words'), '[]'::jsonb) claim,
           coalesce(security.toolset_setting('pipeline', 'enrich.course_description_marketing_words'), security.toolset_setting('pipeline', 'pdesc.superlatives'), '[]'::jsonb) mkt),
  r as (select q.* from security.course_description_reconcile_v1(p_provider, false, 0) q where q.class = 'ready'),
  t as (
    select r.*, i.escalation_reason, i.before_value, i.proposed_value, i.evidence_id ev_id, c.course_code, pv.display_name pname, pv.canonical_name pcanon,
           btrim(i.proposed_value ->> 'description') d, md5(btrim(i.proposed_value ->> 'description')) h
      from r join pipeline.layer4_review_items i on i.id = r.item_id join catalogue.courses c on c.id = r.course_id left join catalogue.providers pv on pv.id = r.provider_id),
  same as (select h, count(*) n from t group by h),
  pub as (select md5(btrim(c.description)) h, count(*) n from catalogue.courses c where nullif(btrim(c.description), '') is not null group by 1),
  held as (select e.provider_id, count(*) n from pipeline.field_enrich_items e where e.field = 'description' and e.state = 'skipped' and e.reason like 'held_first_admission:%' group by 1),
  pc as (select provider_id, count(*) n from t group by 1),
  f as (
    select t.*, coalesce(hd.n, 0) unlock, pc.n in_university,
           (coalesce(same.n, 1) - 1) + coalesce(pub.n, 0) shared_n,
           exists (select 1 from jsonb_array_elements_text(cfg.claim) w where security.pdesc_has_term_v1(t.d, w)) has_claim,
           exists (select 1 from jsonb_array_elements_text(cfg.mkt) w where security.pdesc_has_term_v1(t.d, w)) has_mkt,
           t.d ~ '(\$|AUD|NZD|CAD)|\m(19|20)[0-9]{2}\M' has_fact
      from t cross join cfg left join same on same.h = t.h left join pub on pub.h = t.h left join held hd on hd.provider_id = t.provider_id left join pc on pc.provider_id = t.provider_id),
  g as (
    select f.*, array_remove(array[case when shared_n > 0 then 'same_words_elsewhere' end, case when has_claim then 'claim_word' end,
                                    case when has_mkt then 'marketing_word' end, case when has_fact then 'money_or_year' end], null) flags
      from f),
  o as (
    select g.*, dense_rank() over (order by g.unlock desc, g.in_university desc, coalesce(g.pname, g.pcanon), g.provider_id) prank,
           row_number() over (order by g.unlock desc, g.in_university desc, coalesce(g.pname, g.pcanon), g.provider_id, cardinality(g.flags), g.created_at, g.item_id) rn
      from g),
  pg as (select o.* from o where o.rn > greatest(coalesce(p_offset, 0), 0) and o.rn <= greatest(coalesce(p_offset, 0), 0) + security.pipeline_num_v1('layer4.inbox_page_size', 25)::int)
  select jsonb_build_object(
    'total', (select count(*) from o), 'offset', greatest(coalesce(p_offset, 0), 0), 'limit', security.pipeline_num_v1('layer4.inbox_page_size', 25)::int,
    'order', 'universities whose decision frees the most held readings first, then the larger queue; within a university the items with no flag first, then oldest',
    'items', coalesce((select jsonb_agg(jsonb_build_object(
        'kind', 'provider_description', 'ref', pg.item_id::text, 'provider_id', pg.provider_id, 'provider', coalesce(pg.pname, pg.pcanon), 'subject', pg.course_title,
        'why', coalesce(nullif(pg.escalation_reason, ''), 'Needs a decision'), 'created_at', pg.created_at, 'ready', true,
        'detail', jsonb_strip_nulls(jsonb_build_object('field_code', 'course_description_first_read', 'course_id', pg.course_id, 'course_code', pg.course_code,
                    'code_label', case when pg.country = 'AU' then 'CRICOS' else 'Course code' end,
                    'before', pg.before_value, 'proposed', pg.proposed_value, 'evidence_id', pg.ev_id, 'captured_at', ev.captured_at, 'source_url', ev.source_url,
                    'reask', pg.reask,
                    'pack', jsonb_build_object('flags', to_jsonb(pg.flags), 'flag_count', cardinality(pg.flags), 'same_words_on_other_courses', pg.shared_n,
                                               'held_readings_this_decision_can_free', pg.unlock, 'waiting_in_university', pg.in_university, 'university_rank', pg.prank))))
        order by pg.rn)
      from pg left join pipeline.evidence_artifacts ev on ev.id = pg.ev_id), '[]'::jsonb))
$_$;


ALTER FUNCTION "security"."course_description_pack_v1"("p_provider" "uuid", "p_offset" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_description_pack_v1"("p_provider" "uuid", "p_offset" integer) IS 'CF-247 C-DESC (8 Nov 2026): the course descriptions waiting for a person, ordered for review (universities whose decision frees the most held first readings first; within a university, items with no flag first) with objective flags (same words on other courses, claim word, marketing word, money or year). Read only: no flag decides, rejects or approves anything; every check of the admission path is unchanged.';



CREATE OR REPLACE FUNCTION "security"."course_description_promote_held_v1"("p_provider" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_n int := 0; v_slots int; v_chk jsonb; v_review uuid; v_text text;
begin
  if p_provider is null or security.pipeline_num_v1('enrich.course_description_promote_held_on', 1) < 1 then return 0; end if;
  if security.course_description_trusted_v1(p_provider) then return 0; end if;
  v_slots := security.cdesc_provider_slots_v1(p_provider);
  if v_slots <= 0 then return 0; end if;
  for r in select e.id, e.course_id, e.value, e.quote, g.evidence_id, g.url, g.identity_basis, g.provider_id
             from pipeline.field_enrich_items e join pipeline.coverage_course_pages g on g.course_id = e.course_id
            where e.provider_id = p_provider and e.field = 'description' and e.state = 'skipped' and e.reason like 'held_first_admission:%'
              and nullif(btrim(e.value->>'text'), '') is not null and e.evidence_id is not distinct from g.evidence_id
            order by e.id
              for update of e skip locked loop
    exit when v_n >= v_slots;
    continue when not security.coverage_identity_allowed(r.provider_id, r.identity_basis, 'description');
    continue when exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = r.course_id and l.field in ('description', 'course_description', 'all'));
    continue when exists (select 1 from catalogue.courses c where c.id = r.course_id and nullif(btrim(c.description), '') is not null);
    continue when exists (select 1 from pipeline.layer4_review_items q where q.entity_type = 'course' and q.entity_id = r.course_id
                           and q.field_code = 'course_description_first_read' and q.status = 'pending');
    v_chk := security.course_description_check_v1(r.course_id, r.value);
    continue when not coalesce((v_chk->>'ok')::boolean, false);
    v_text := v_chk->>'text';
    insert into pipeline.layer4_review_items(entity_type, entity_id, field_code, evidence_id, before_value, proposed_value, layer2_state, layer3_state, status, escalation_reason, change_control_ref)
    values ('course', r.course_id, 'course_description_first_read', r.evidence_id, jsonb_build_object('description', null),
            jsonb_build_object('description', v_text, 'item_id', r.id, 'source_url', r.url, 'checks', v_chk->'checks',
                               'sentences', (select jsonb_agg(jsonb_build_object('text', s->>'text', 'quote', s->>'quote') order by o) from jsonb_array_elements(r.value->'sentences') with ordinality e(s, o))),
            jsonb_build_object('source', 'course description reader', 'page', r.url, 'identity_basis', r.identity_basis),
            jsonb_build_object('item_id', r.id, 'held_first_admission', true) || jsonb_strip_nulls(jsonb_build_object('model', security.cdesc_reading_provenance_v1(r.id, r.value)->>'model', 'prompt', security.cdesc_reading_provenance_v1(r.id, r.value)->>'prompt', 'worker', security.cdesc_reading_provenance_v1(r.id, r.value)->>'worker')),
            'pending', 'Course description read from the course''s own page. This is one of the provider''s first course descriptions, so a person approves it as read or rejects it.',
            'CF-CHG-20260915-247')
    returning id into v_review;
    update pipeline.field_enrich_items set state = 'review', reason = null, value = r.value || jsonb_build_object('review_item_id', v_review, 'promoted_from', 'held_first_admission'), updated_at = now()
     where id = r.id;
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;


ALTER FUNCTION "security"."course_description_promote_held_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_description_promote_held_v1"("p_provider" "uuid") IS 'CF-247 (7 Nov 2026): after a person decides one of a provider''s course descriptions in Layer 4, the provider''s held_first_admission readings (same bound page, every check run again, not locked, description empty) take the freed places in the queue, up to enrich.course_description_pending_max. Queues for a person only: no admission, no AI call.';



CREATE OR REPLACE FUNCTION "security"."course_description_reconcile_v1"("p_provider" "uuid" DEFAULT NULL::"uuid", "p_recheck" boolean DEFAULT false, "p_cap" integer DEFAULT NULL::integer) RETURNS TABLE("item_id" "uuid", "provider_id" "uuid", "country" "text", "course_id" "uuid", "course_title" "text", "created_at" timestamp with time zone, "class" "text", "why" "text", "enrich_item" bigint, "rule" "text", "checks" "jsonb", "reask" "jsonb", "rechecked" boolean, "evidence_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  with p as (
    select r.id, r.entity_id, r.evidence_id, r.created_at,
           case when coalesce(r.proposed_value->>'item_id', '') ~ '^\d+$' then (r.proposed_value->>'item_id')::bigint end eid
      from pipeline.layer4_review_items r
     where r.status = 'pending' and r.entity_type = 'course' and r.field_code = 'course_description_first_read'),
  j as (
    select p.*, c.provider_id pid, c.lifecycle_status, nullif(btrim(c.description), '') now_desc, coalesce(nullif(c.display_title, ''), c.canonical_title) title,
           k.iso_alpha2::text country, g.evidence_id bound, e.value ev, e.id enrich_id,
           exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = c.id and l.field in ('description', 'course_description', 'all')) locked,
           row_number() over (order by p.created_at, p.id) rn
      from p join catalogue.courses c on c.id = p.entity_id
      left join catalogue.providers pv on pv.id = c.provider_id
      left join ref.countries k on k.id = pv.country_id
      left join pipeline.coverage_course_pages g on g.course_id = c.id
      left join pipeline.field_enrich_items e on e.id = p.eid
     where p_provider is null or c.provider_id = p_provider),
  s as (
    select j.*, case when j.lifecycle_status is distinct from 'active' then 'course_inactive'
                     when j.now_desc is not null then 'already_filled'
                     when j.locked then 'locked'
                     when j.bound is distinct from j.evidence_id then 'page_changed'
                     when j.ev is null or jsonb_typeof(j.ev->'sentences') is distinct from 'array' or jsonb_array_length(j.ev->'sentences') = 0 then 'no_reading'
                end static_class,
           coalesce(p_recheck, false) and (p_cap is null or j.rn <= p_cap) do_check
      from j)
  select s.id, s.pid, s.country, s.entity_id, s.title, s.created_at,
         case when s.static_class is not null then s.static_class
              when z.chk is not null and not coalesce((z.chk->>'ok')::boolean, false) then 'fails_now' else 'ready' end,
         case s.static_class when 'course_inactive' then 'The course is no longer active.'
                             when 'already_filled' then 'The course already has a description, so this proposal cannot be approved as read.'
                             when 'locked' then 'The description is locked by hand.'
                             when 'page_changed' then 'The stored page this was read from is no longer the course''s bound page; it is read again with the new copy.'
                             when 'no_reading' then 'The AI reading behind this proposal is not stored, so its checks cannot be shown.'
                             else case when z.chk is not null and not coalesce((z.chk->>'ok')::boolean, false) then 'No longer passes the checks: ' || (z.chk->>'rule') || ': ' || coalesce(z.chk->>'reason', '')
                                       else 'A person can decide this as read.' end end,
         s.enrich_id, z.chk->>'rule', z.chk->'checks', s.ev->'reask', z.chk is not null, s.evidence_id
    from s left join lateral (select security.course_description_check_v1(s.entity_id, s.ev) chk where s.static_class is null and s.do_check) z on true
$_$;


ALTER FUNCTION "security"."course_description_reconcile_v1"("p_provider" "uuid", "p_recheck" boolean, "p_cap" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_description_release_held_v1"("p_provider" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_n int := 0; v_k int;
begin
  if p_provider is null or not security.course_description_trusted_v1(p_provider) then return 0; end if;
  for r in select e.id, e.course_id, e.value->>'text' txt from pipeline.field_enrich_items e join pipeline.coverage_course_pages g on g.course_id = e.course_id
            where e.provider_id = p_provider and e.field = 'description' and e.state = 'skipped' and e.reason like 'held_first_admission:%'
              and nullif(btrim(e.value->>'text'), '') is not null and e.evidence_id is not distinct from g.evidence_id
            for update of e skip locked loop
    if exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = r.course_id and l.field in ('description', 'course_description', 'all')) then continue; end if;
    -- the checks are run again (another course may have taken the same words since)
    if not coalesce((security.course_description_check_v1(r.course_id, (select e.value from pipeline.field_enrich_items e where e.id = r.id))->>'ok')::boolean, false) then continue; end if;
    update catalogue.courses set description = r.txt, updated_at = now() where id = r.course_id and nullif(btrim(description), '') is null;
    get diagnostics v_k = row_count;
    update pipeline.field_enrich_items set state = case when v_k > 0 then 'filled' else 'skipped' end, reason = case when v_k > 0 then null else 'already filled' end,
           value = value || jsonb_build_object('admitted', 'held, admitted once the provider''s first descriptions were approved'), updated_at = now() where id = r.id;
    v_n := v_n + v_k;
  end loop;
  if v_n > 0 then
    insert into search.refresh_requests(requested_by) select 'AI reader (course description, deadline)'
     where not exists (select 1 from search.refresh_requests q where q.processed_at is null and q.requested_by = 'AI reader (course description, deadline)');
  end if;
  return v_n;
end $$;


ALTER FUNCTION "security"."course_description_release_held_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_description_release_held_v1"("p_provider" "uuid") IS 'CF-247 Workstream C (3 Nov 2026): once a provider''s first course descriptions are approved in Layer 4, its descriptions held while they waited (same bound page, checks passed again) are admitted.';



CREATE OR REPLACE FUNCTION "security"."course_description_retire_stale_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_on boolean := security.pipeline_num_v1('enrich.course_description_stale_supersede_on', 0) >= 1; r record; v_n int := 0; v_ex int := 0; v_by jsonb := '{}'::jsonb; v_reason text;
        v_max int := security.pipeline_num_v1('layer4.reconcile_batch', 200)::int;
begin
  -- 15 Nov 2026 (job governance quick win 1): the two classes this job retires, read directly with the rules of the course description
  -- reconcile (a course no longer active first, then a course that already has a description). Reading them through the reconcile also ran
  -- the full course description check on every waiting proposal, which this job never uses.
  for r in select i.id item_id, c.id course_id,
                  case when c.lifecycle_status is distinct from 'active' then 'course_inactive' else 'already_filled' end class,
                  i.field_code, i.entity_type, i.entity_id, i.evidence_id
             from pipeline.layer4_review_items i join catalogue.courses c on c.id = i.entity_id
            where i.status = 'pending' and i.entity_type = 'course' and i.field_code = 'course_description_first_read'
              and (c.lifecycle_status is distinct from 'active' or nullif(btrim(c.description), '') is not null)
            order by i.created_at limit v_max loop
    v_ex := v_ex + 1;
    v_reason := case r.class when 'course_inactive' then 'entity_retired' else 'covered_by_active' end;
    v_by := v_by || jsonb_build_object(v_reason, coalesce((v_by ->> v_reason)::int, 0) + 1);
    continue when not v_on;
    update pipeline.layer4_review_items set status = 'superseded', decided_at = now(),
           change_control_ref = left(coalesce(change_control_ref, '') || ' | superseded: ' || v_reason || ' (course description proposal can no longer be approved)', 400)
     where id = r.item_id and status = 'pending';
    continue when not found;
    insert into pipeline.layer4_supersessions(item_id, field_code, entity_type, entity_id, reason, covered_by_item, evidence, mode)
    values (r.item_id, r.field_code, r.entity_type, r.entity_id, v_reason, null,
            jsonb_build_object('class', r.class, 'evidence_id', r.evidence_id, 'by', 'course-description-stale-retire'), 'reconcile');
    if to_regclass('pipeline.layer4_item_readiness') is not null then
      execute 'update pipeline.layer4_item_readiness set item_status = ''superseded'', readiness = ''closed'', classified_at = now() where item_id = $1' using r.item_id;
    end if;
    v_n := v_n + 1;
  end loop;
  return jsonb_build_object('on', v_on, 'examined', v_ex, 'superseded', v_n, 'by_reason', v_by);
end $_$;


ALTER FUNCTION "security"."course_description_retire_stale_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_description_retire_stale_v1"() IS 'CF-247 C-DESC (8 Nov 2026): while enrich.course_description_stale_supersede_on is 1, a waiting course description proposal whose course is no longer active (entity_retired) or already has a description (covered_by_active) is superseded and recorded in pipeline.layer4_supersessions. Never approves or rejects; page-changed and locked proposals stay with a person. Off: counts only.';



CREATE OR REPLACE FUNCTION "security"."course_description_review_trg_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_item bigint := case when coalesce(new.proposed_value->>'item_id', '') ~ '^\d+$' then (new.proposed_value->>'item_id')::bigint end; v_pid uuid;
begin
  if v_item is not null then
    update pipeline.field_enrich_items set state = case when new.status in ('approved', 'edited_approved') then 'filled' else 'skipped' end,
           reason = case when new.status in ('approved', 'edited_approved') then null else 'not admitted in Layer 4 (' || new.status || ')' end, updated_at = now()
     where id = v_item and state = 'review';
  end if;
  select c.provider_id into v_pid from catalogue.courses c where c.id = new.entity_id;
  if new.status in ('approved', 'edited_approved') then
    perform security.course_description_release_held_v1(v_pid);
    insert into search.refresh_requests(requested_by) select 'AI reader (course description, deadline)'
     where not exists (select 1 from search.refresh_requests q where q.processed_at is null and q.requested_by = 'AI reader (course description, deadline)');
  end if;
  perform security.course_description_promote_held_v1(v_pid);
  return null;
end $_$;


ALTER FUNCTION "security"."course_description_review_trg_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_description_review_trg_v1"() IS 'CF-247 Workstream C (3 Nov 2026): trigger layer4_review_items_course_description: a decided course description settles its Enrich fields item (filled, or skipped with the decision); an approval admits the provider''s held descriptions once it is trusted; any decision lets the provider''s held readings take the freed place in the queue (7 Nov 2026).';



CREATE OR REPLACE FUNCTION "security"."course_description_sample_ids_v1"() RETURNS TABLE("item_id" "uuid", "country" "text", "pick" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with strata as (select upper(x) code from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'enrich.course_description_sample_countries'), '[]'::jsonb)) x),
  ranked as (select el.item_id, el.country, row_number() over (partition by el.country order by md5(el.item_id::text)) rn
               from security.course_description_sample_pool_v1() el where el.country in (select code from strata))
  select ranked.item_id, ranked.country, ranked.rn::int from ranked
   where ranked.rn <= security.pipeline_num_v1('enrich.course_description_sample_' || lower(ranked.country), 0)
$$;


ALTER FUNCTION "security"."course_description_sample_ids_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_description_sample_pool_v1"() RETURNS TABLE("item_id" "uuid", "country" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- every course description item a person has decided or can decide now (not superseded, not stale), with its provider's country
  select r.id, k.iso_alpha2::text
    from pipeline.layer4_review_items r join catalogue.courses c on c.id = r.entity_id
    join catalogue.providers pv on pv.id = c.provider_id join ref.countries k on k.id = pv.country_id
   where r.entity_type = 'course' and r.field_code = 'course_description_first_read' and r.status <> 'superseded'
     and (r.status <> 'pending' or r.id in (select q.item_id from security.course_description_reconcile_v1(null, true, security.pipeline_num_v1('enrich.course_description_report_max', 500)::int) q where q.class = 'ready'))
$$;


ALTER FUNCTION "security"."course_description_sample_pool_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_description_sample_report_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  with ids as (select * from security.course_description_sample_ids_v1()),
  pool as (select p.country, count(*) n from security.course_description_sample_pool_v1() p group by 1),
  strata as (select upper(x) code, o from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'enrich.course_description_sample_countries'), '[]'::jsonb)) with ordinality t(x, o)),
  claim as (select w from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'enrich.course_description_claim_words'), security.toolset_setting('pipeline', 'pdesc.claim_words'), '[]'::jsonb)) w),
  dcn as (select distinct on (d.review_item_id) d.review_item_id, d.action, d.reason, coalesce(d.layer2_state->>'actor_kind', '') = 'machine' by_machine from pipeline.layer4_decisions d order by d.review_item_id, d.created_at desc),
  rws as (
    select ids.item_id, ids.country, ids.pick, i.status, dcn.action, dcn.reason, coalesce(dcn.by_machine, false) by_machine,
           case when i.status in ('rejected', 'more_evidence', 'returned_layer2', 'returned_layer3')
                then coalesce(substring(dcn.reason from '^\s*\[(identity|support|marketing|fragment|other)\]'), 'unclassified') end reason_class,
           coalesce(pv.display_name, pv.canonical_name) provider, coalesce(nullif(c.display_title, ''), c.canonical_title) course, g.identity_basis, g.url page_url,
           i.proposed_value->>'description' description,
           (select min(security.pdesc_support_v1(s->>'text', s->>'quote')) from jsonb_array_elements(coalesce(i.proposed_value->'sentences', '[]'::jsonb)) s) min_support,
           (select coalesce(jsonb_agg(distinct claim.w), '[]'::jsonb) from claim, jsonb_array_elements(coalesce(i.proposed_value->'sentences', '[]'::jsonb)) s where security.pdesc_has_term_v1(s->>'text', claim.w)) claims,
           case when e.value is null then null else security.course_description_check_v1(c.id, e.value) end rules_now
      from ids join pipeline.layer4_review_items i on i.id = ids.item_id
      join catalogue.courses c on c.id = i.entity_id left join catalogue.providers pv on pv.id = c.provider_id
      left join pipeline.coverage_course_pages g on g.course_id = c.id
      left join pipeline.field_enrich_items e on e.id = case when coalesce(i.proposed_value->>'item_id', '') ~ '^\d+$' then (i.proposed_value->>'item_id')::bigint end
      left join dcn on dcn.review_item_id = i.id)
  select jsonb_build_object(
    'strata', coalesce((select jsonb_agg(jsonb_build_object('country', strata.code, 'wanted', security.pipeline_num_v1('enrich.course_description_sample_' || lower(strata.code), 0),
                          'eligible', coalesce(pool.n, 0), 'selected', (select count(*) from rws where rws.country = strata.code),
                          'shortfall', greatest(0, security.pipeline_num_v1('enrich.course_description_sample_' || lower(strata.code), 0) - (select count(*) from rws where rws.country = strata.code))) order by strata.o)
                          from strata left join pool on pool.country = strata.code), '[]'::jsonb),
    'selected', (select count(*) from rws),
    'pending', (select count(*) from rws where rws.status = 'pending'),
    'approved', (select count(*) from rws where rws.status in ('approved', 'edited_approved') and not rws.by_machine),
    'approved_by_machine', (select count(*) from rws where rws.status in ('approved', 'edited_approved') and rws.by_machine),
    'rejected', (select count(*) from rws where rws.reason_class is not null),
    'approval_share_of_decided', (select round((count(*) filter (where rws.status in ('approved', 'edited_approved') and not rws.by_machine))::numeric / nullif(count(*) filter (where rws.status <> 'pending' and not rws.by_machine), 0), 3) from rws),
    'rejected_by_class', coalesce((select jsonb_object_agg(z.reason_class, z.n) from (select rws.reason_class, count(*) n from rws where rws.reason_class is not null group by 1) z), '{}'::jsonb),
    'reviewer_disagreement', jsonb_build_object(
        'passed_every_check_but_rejected', (select count(*) from rws where rws.reason_class is not null),
        'approved_but_rules_now_fail', (select count(*) from rws where rws.status in ('approved', 'edited_approved') and not rws.by_machine and rws.rules_now is not null and not coalesce((rws.rules_now->>'ok')::boolean, false))),
    'claim_support', jsonb_build_object('with_claim_words_in_quote', (select count(*) from rws where jsonb_array_length(rws.claims) > 0), 'lowest_sentence_support', (select min(rws.min_support) from rws)),
    'rows', coalesce((select jsonb_agg(jsonb_build_object('ref', rws.item_id, 'country', rws.country, 'provider', rws.provider, 'course', rws.course, 'status', rws.status,
                        'reason_class', rws.reason_class, 'reason', rws.reason, 'min_support', rws.min_support, 'claims', rws.claims, 'identity_basis', rws.identity_basis,
                        'page_url', rws.page_url, 'description', rws.description, 'rules_now', rws.rules_now) order by rws.country, rws.pick) from rws), '[]'::jsonb),
    'note', 'A measurement of what the checks let through, decided by a person in Layer 4. It is not an authority to bypass Layer 4 and does not change enrich.course_description_review_first.')
$_$;


ALTER FUNCTION "security"."course_description_sample_report_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_description_summary_v1"("p_provider" "uuid" DEFAULT NULL::"uuid", "p_recheck" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with r as (select * from security.course_description_reconcile_v1(p_provider, p_recheck, security.pipeline_num_v1('enrich.course_description_report_max', 500)::int)),
  cls as (select r.class, count(*) n from r group by 1),
  cty as (select coalesce(r.country, '?') country, count(*) n, count(*) filter (where r.class = 'ready') ready from r group by 1),
  l4 as (
    select i.id, i.status, c.id course_id, i.proposed_value->>'description' d, nullif(btrim(c.description), '') cur, exists (select 1 from pipeline.layer4_decisions md where md.review_item_id = i.id and md.layer2_state->>'actor_kind' = 'machine') by_machine
      from pipeline.layer4_review_items i join catalogue.courses c on c.id = i.entity_id
     where i.entity_type = 'course' and i.field_code = 'course_description_first_read' and (p_provider is null or c.provider_id = p_provider)),
  fe as (select f.* from pipeline.field_enrich_items f where f.field = 'description' and (p_provider is null or f.provider_id = p_provider))
  select jsonb_build_object(
    'provider_id', p_provider,
    'pending', (select count(*) from r),
    'by_class', coalesce((select jsonb_object_agg(cls.class, cls.n) from cls), '{}'::jsonb),
    'by_country', coalesce((select jsonb_object_agg(cty.country, jsonb_build_object('pending', cty.n, 'ready', cty.ready)) from cty), '{}'::jsonb),
    'rechecked', (select count(*) from r where r.rechecked),
    'oldest', (select min(r.created_at) from r),
    -- the four measures, never mixed: an AI reading waiting in Layer 4 is neither admitted nor published
    'proposed_in_layer4', (select count(*) from l4 where l4.status = 'pending'),
    'waiting_behind_provider_cap', (select count(*) from fe where fe.state = 'skipped' and fe.reason like 'held\_first\_admission:%'),
    'admitted_by_person', (select count(*) from l4 where l4.status in ('approved', 'edited_approved') and not l4.by_machine and l4.cur is not distinct from nullif(btrim(l4.d), '')),
    'admitted_by_machine', (select count(*) from l4 where l4.status in ('approved', 'edited_approved') and l4.by_machine and l4.cur is not distinct from nullif(btrim(l4.d), '')),
    'admitted_without_a_person', (select count(*) from fe where fe.state = 'filled' and coalesce(fe.value->>'admitted', '') <> ''),
    'published_to_the_website', (select count(distinct l4.course_id) from l4 join search.course_documents sd on sd.course_id = l4.course_id
                                   where l4.status in ('approved', 'edited_approved') and l4.cur is not distinct from nullif(btrim(l4.d), '') and nullif(btrim(sd.description), '') = l4.cur
                                     and sd.publication_status = 'published'
                                     and not exists (select 1 from security.layer4_search_blocked_courses b where b.course_id = l4.course_id)),
    'decided', (select jsonb_object_agg(z.status, z.n) from (select l4.status, count(*) n from l4 group by 1) z),
    'limits', jsonb_build_object('min_sentences', security.pipeline_num_v1('enrich.course_description_min_sentences', 1), 'max_sentences', security.pipeline_num_v1('enrich.course_description_max_sentences', 4),
                                 'min_chars', security.pipeline_num_v1('enrich.course_description_min_chars', 80), 'max_chars', security.pipeline_num_v1('enrich.course_description_max_chars', 700)),
    'reask_max', security.pipeline_num_v1('enrich.course_description_reask_max', 0),
    'review_first', security.pipeline_num_v1('enrich.course_description_review_first', 100000),
    'note', 'Measurement only. A person admits every description in Layer 4 except those the machine rule admits (counted apart as admitted_by_machine); nothing here admits, decides or changes a setting.')
$$;


