CREATE OR REPLACE FUNCTION "security"."course_empty_reason_apply_v1"("p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_set int := 0; v_cleared int := 0; v_by jsonb;
begin
  if auth.uid() is not null and coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  create temp table if not exists _cer (course_id uuid, code text) on commit drop;
  truncate _cer;
  insert into _cer
  select c.id,
         case when c.delivery_mode = 'online' then 'online_only_no_campus'
              when a.state = 'not_on_page' then 'not_published_by_provider'
              when a.state in ('in_review', 'in_queue', 'candidate', 'awaiting_l3') then 'pending_extraction'
              when a.state = 'missing_l1' then 'not_listed_on_register'
              when a.state in ('site_known', 'no_website', 'page_found', 'blocked') then 'source_unavailable'
         end
    from catalogue.courses c
    left join pipeline.course_attribute_coverage a on a.course_id = c.id and a.attribute = 'campus'
   where c.lifecycle_status = 'active'
     and not exists (select 1 from catalogue.course_campuses k where k.course_id = c.id);
  select jsonb_object_agg(coalesce(code, 'left_null'), n) into v_by from (select code, count(*) n from _cer group by 1) z;
  if p_apply then
    update catalogue.courses c set empty_reason_code = e.code
      from _cer e where c.id = e.course_id and e.code is not null and c.empty_reason_code is distinct from e.code;
    get diagnostics v_set = row_count;
    update catalogue.courses c set empty_reason_code = null
     where c.empty_reason_code is not null
       and (c.lifecycle_status <> 'active' or exists (select 1 from catalogue.course_campuses k where k.course_id = c.id));
    get diagnostics v_cleared = row_count;
    insert into pipeline.admin_control_events (area, action, target, detail, actor)
    values ('api_v3', 'course_empty_reason_apply', 'catalogue.courses.empty_reason_code',
            jsonb_build_object('set', v_set, 'cleared', v_cleared, 'by_code', v_by), auth.uid());
  end if;
  return jsonb_build_object('applied', p_apply, 'set', v_set, 'cleared', v_cleared, 'by_code', v_by);
end;
$$;


ALTER FUNCTION "security"."course_empty_reason_apply_v1"("p_apply" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_empty_reason_apply_v1"("p_apply" boolean) IS 'CF-247 API v3 PR A (REQ-53): the reason an active course has no campus, from stored evidence only (delivery mode online; the campus reading state); clears the reason when a campus exists. Count-only unless p_apply; audited.';



CREATE OR REPLACE FUNCTION "security"."course_entry_batch_v1"("p_provider" "uuid", "p_size" integer, "p_reason" "text", "p_actor" "uuid", "p_preview" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_max int := security.pipeline_num_v1('entry.course_batch_size', 50)::int; v_n int; v_ids uuid[]; v_cost numeric := security.course_entry_cost_v1();
        v_bal numeric; v_floor numeric; v_est numeric; v_job uuid; v_reason text := btrim(coalesce(p_reason, '')); v_prov jsonb; v_wait int;
begin
  v_n := greatest(1, least(coalesce(p_size, v_max), v_max));
  select array_agg(z.course_id order by z.prio, z.title, z.course_id), jsonb_object_agg(z.pname, z.k) into v_ids, v_prov from (
    select q.course_id, q.prio, q.title, coalesce(p.display_name, p.canonical_name) pname, count(*) over (partition by q.provider_id) k
      from (select el.* from security.course_entry_eligible_v1() el
             where (p_provider is null or el.provider_id = p_provider)
               and not exists (select 1 from pipeline.field_enrich_items f where f.course_id = el.course_id and f.field = 'entry_requirements')
             order by el.prio, el.title, el.course_id limit v_n) q
      join catalogue.providers p on p.id = q.provider_id) z;
  v_est := round(coalesce(array_length(v_ids, 1), 0) * v_cost, 4);
  select o.remaining_usd into v_bal from pipeline.layer3_openrouter_observations o where o.kind = 'credits' order by o.observed_at desc limit 1;
  v_floor := coalesce((security.toolset_setting('openrouter', 'credit_floor_usd'))::text::numeric, 0);
  select count(*) into v_wait from pipeline.field_enrich_items f where f.field = 'entry_requirements' and f.state in ('queued', 'waiting', 'ai', 'leased');
  if p_preview then
    return jsonb_build_object('preview', true, 'courses', coalesce(array_length(v_ids, 1), 0), 'providers', coalesce(v_prov, '{}'::jsonb), 'estimate_usd', v_est,
      'cost_per_course_usd', round(v_cost, 5), 'balance_usd', v_bal, 'floor_usd', v_floor, 'batch_size', v_max, 'waiting', v_wait,
      'refusal', case when coalesce(array_length(v_ids, 1), 0) = 0 then 'no course is left to read for this choice'
                      when v_wait > 0 then 'an earlier course read is still waiting; the next batch follows it'
                      when not security.ai_use_allowed_v1('enrich_fields') then 'AI reading is stopped (AI limits)'
                      when v_bal is not null and v_bal - v_est < v_floor then 'the estimate would take the OpenRouter balance below its floor (Toolsets & limits)' end);
  end if;
  if length(v_reason) < 5 then raise exception 'give a reason (kept in the history)' using errcode = '22023'; end if;
  if coalesce(array_length(v_ids, 1), 0) = 0 then raise exception 'no course is left to read for this choice' using errcode = '22023'; end if;
  if v_wait > 0 then raise exception 'an earlier course read is still waiting (% courses); the next batch follows it', v_wait using errcode = '22023'; end if;
  if not security.ai_use_allowed_v1('enrich_fields') then raise exception 'AI reading is stopped (AI limits); nothing was asked' using errcode = '22023'; end if;
  if v_bal is not null and v_bal - v_est < v_floor then
    raise exception 'the estimate (US$%) would take the OpenRouter balance (US$%) below its floor (US$%); nothing was asked', v_est, round(v_bal, 2), v_floor using errcode = '22023'; end if;
  insert into pipeline.admin_jobs(kind, lane, state, title, args, progress, requested_by, reason, scope)
  values ('enrich_fields', 'enrich', 'queued', left('Entry requirements · ' || array_length(v_ids, 1) || ' courses', 200),
          jsonb_build_object('read_now', true, 'entry_read', true, 'entry_batch', true, 'countries', '[]'::jsonb,
                             'provider_ids', (select jsonb_agg(distinct c.provider_id) from catalogue.courses c where c.id = any (v_ids)), 'course_ids', to_jsonb(v_ids),
                             'fields', jsonb_build_array('entry_requirements'), 'ai', true, 'scraper', false, 'estimate_usd', v_est),
          jsonb_build_object('done', 0, 'total', array_length(v_ids, 1)), p_actor, v_reason, array_length(v_ids, 1) || ' courses')
  returning id into v_job;
  insert into pipeline.field_enrich_items(job_id, provider_id, course_id, field, state)
  select v_job, c.provider_id, c.id, 'entry_requirements', 'queued' from catalogue.courses c where c.id = any (v_ids)
  on conflict do nothing;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('entry_requirements', 'course_batch', v_job::text, jsonb_build_object('courses', array_length(v_ids, 1), 'providers', v_prov, 'estimate_usd', v_est, 'reason', v_reason), p_actor);
  return jsonb_build_object('ok', true, 'job_id', v_job, 'courses', array_length(v_ids, 1), 'providers', v_prov, 'estimate_usd', v_est);
end $_$;


ALTER FUNCTION "security"."course_entry_batch_v1"("p_provider" "uuid", "p_size" integer, "p_reason" "text", "p_actor" "uuid", "p_preview" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_entry_batch_v1"("p_provider" "uuid", "p_size" integer, "p_reason" "text", "p_actor" "uuid", "p_preview" boolean) IS 'CF-247 AER course-level programme (29 Oct 2026): preview, then one bounded Enrich fields task of never-read eligible courses (entry.course_batch_size), refused while a course read waits, when AI is stopped, or below the OpenRouter credit floor. Platform Admin through public.admin_aer(''course_batch''), or an approved programme migration. Owner only.';



CREATE OR REPLACE FUNCTION "security"."course_entry_correction_check_v1"("p_item" "uuid", "p_course" "uuid", "p_url" "text", "p_rows" "jsonb" DEFAULT NULL::"jsonb", "p_dropped" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o pipeline.layer4_review_items%rowtype; v_why text[] := '{}'; v_chk jsonb; v_shared jsonb; v_diff jsonb;
begin
  select * into o from pipeline.layer4_review_items where id = p_item;
  if o.id is null or o.field_code <> 'course_entry_first_read' then return jsonb_build_object('ok', false, 'why', 'not a course entry read'); end if;
  if o.status <> 'pending' then v_why := v_why || format('the read no longer waits (%s)', o.status); end if;
  if o.entity_id is distinct from p_course then v_why := v_why || 'another course'::text; end if;
  if exists (select 1 from pipeline.layer4_decisions d where d.review_item_id = o.id) then v_why := v_why || 'a person has decided it'::text; end if;
  if o.claimed_at is not null and o.claimed_at > now() - make_interval(mins => security.pipeline_num_v1('entry.supersede_claim_minutes', 60)::int) then
    v_why := v_why || 'a reviewer claimed it'::text;
  end if;
  if exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = p_course
               and l.field in (select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'entry.supersede_lock_fields'), '[]'::jsonb)))) then
    v_why := v_why || 'the course has a manual lock'::text;
  end if;
  if p_url is null or p_url is distinct from o.proposed_value->>'url' then
    v_why := v_why || format('the course''s bound page (%s) is not the page of the waiting read (%s): a new first read, not a correction', coalesce(p_url, 'none'), coalesce(o.proposed_value->>'url', 'none'));
  end if;
  if p_rows is not null then
    v_chk := security.course_entry_read_check_v1(p_rows, p_dropped);
    v_shared := security.course_entry_shared_page_v1(p_course);
    if jsonb_array_length(p_rows) = 0 then v_why := v_why || 'the corrected read has no row'::text; end if;
    if exists (select 1 from jsonb_array_elements(coalesce(p_dropped, '[]'::jsonb)) d where d->>'reason' in ('over_row_limit', 'other_programme')) then
      v_why := v_why || 'the corrected read cut or set aside rows'::text;
    end if;
    if jsonb_array_length(v_chk->'drops_uncovered') > 0 then v_why := v_why || format('the corrected read still drops %s printed requirement(s)', jsonb_array_length(v_chk->'drops_uncovered')); end if;
    if jsonb_array_length(v_chk->'not_requirement') > 0 then v_why := v_why || format('%s row(s) are not entry requirements', jsonb_array_length(v_chk->'not_requirement')); end if;
    if jsonb_array_length(v_chk->'audience') > 0 then v_why := v_why || format('%s domestic row(s) stored for everyone', jsonb_array_length(v_chk->'audience')); end if;
    if jsonb_array_length(v_shared) > 0 then v_why := v_why || 'the page is shared with another programme'::text; end if;
    -- the reviewer's diff: a row is the same when kind, audience, quote (letters and digits), score and basis are the same
    with oldr as (select x.kind, x.audience, x.quote, x.min_entry_score sc, x.min_entry_score_basis b,
                         x.kind || '|' || x.audience || '|' || lower(regexp_replace(coalesce(x.quote, ''), '[^[:alnum:]]', '', 'g')) || '|' || coalesce(x.min_entry_score::text, '') || '|' || lower(coalesce(x.min_entry_score_basis, '')) k
                    from catalogue.course_entry_requirements x where x.provenance->>'review_item_id' = o.id::text),
         newr as (select y->>'kind' kind, y->>'audience' audience, y->>'quote' quote, y->>'min_entry_score' sc, y->>'min_entry_score_basis' b,
                         (y->>'kind') || '|' || (y->>'audience') || '|' || lower(regexp_replace(coalesce(y->>'quote', ''), '[^[:alnum:]]', '', 'g')) || '|' || coalesce((y->>'min_entry_score')::numeric::text, '') || '|' || lower(coalesce(y->>'min_entry_score_basis', '')) k
                    from jsonb_array_elements(p_rows) y)
    select jsonb_build_object(
      'added', (select coalesce(jsonb_agg(jsonb_build_object('kind', n.kind, 'audience', n.audience, 'score', n.sc, 'basis', n.b, 'quote', left(n.quote, 200))), '[]'::jsonb) from newr n where not exists (select 1 from oldr x where x.k = n.k)),
      'removed', (select coalesce(jsonb_agg(jsonb_build_object('kind', x.kind, 'audience', x.audience, 'score', x.sc, 'basis', x.b, 'quote', left(x.quote, 200))), '[]'::jsonb) from oldr x where not exists (select 1 from newr n where n.k = x.k)),
      'unchanged', (select count(*) from newr n where exists (select 1 from oldr x where x.k = n.k)),
      'dropped_before', (select coalesce(jsonb_object_agg(k, c), '{}'::jsonb) from (select d->>'reason' k, count(*) c from jsonb_array_elements(coalesce(o.proposed_value->'dropped', '[]'::jsonb)) d group by 1) z),
      'dropped_after', (select coalesce(jsonb_object_agg(k, c), '{}'::jsonb) from (select d->>'reason' k, count(*) c from jsonb_array_elements(coalesce(p_dropped, '[]'::jsonb)) d group by 1) z),
      'old_evidence_id', o.evidence_id)
      into v_diff;
  end if;
  return jsonb_build_object('ok', cardinality(v_why) = 0, 'why', array_to_string(v_why, '; '), 'reasons', to_jsonb(v_why), 'check', v_chk, 'diff', v_diff);
end $$;


ALTER FUNCTION "security"."course_entry_correction_check_v1"("p_item" "uuid", "p_course" "uuid", "p_url" "text", "p_rows" "jsonb", "p_dropped" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_entry_correction_check_v1"("p_item" "uuid", "p_course" "uuid", "p_url" "text", "p_rows" "jsonb", "p_dropped" "jsonb") IS 'CF-247 D-R2: may a corrected read replace this waiting course entry read? Same course and bound page, still waiting, no decision, no recent claim, no manual lock (entry.supersede_lock_fields); with the corrected rows, also complete (security.course_entry_read_check_v1, no cut, no shared page) and the reviewer''s diff.';



CREATE OR REPLACE FUNCTION "security"."course_entry_correction_v1"("p_item" "uuid", "p_actor" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o pipeline.layer4_review_items%rowtype; g record; v_chk jsonb; v_job uuid; v_enrich bigint; v_id uuid;
begin
  if length(btrim(coalesce(p_reason, ''))) < 5 then raise exception 'give a reason (kept in the record)'; end if;
  select * into o from pipeline.layer4_review_items where id = p_item for update;
  if o.id is null then raise exception 'no such Layer 4 item'; end if;
  select pg.url, pg.evidence_id into g from pipeline.coverage_course_pages pg where pg.course_id = o.entity_id;
  v_chk := security.course_entry_correction_check_v1(p_item, o.entity_id, g.url);
  if not (v_chk->>'ok')::boolean then raise exception 'No corrected read (D-R2): %. Nothing was changed', v_chk->>'why' using errcode = '55000'; end if;
  if exists (select 1 from pipeline.aer_read_supersessions s where s.old_item_id = p_item and s.state = 'requested') then
    raise exception 'No corrected read (D-R2): a corrected read of this item is already asked for. Nothing was changed' using errcode = '55000';
  end if;
  if exists (select 1 from pipeline.field_enrich_items f where f.course_id = o.entity_id and f.field = 'entry_requirements' and f.state in ('queued', 'waiting', 'ai', 'leased')) then
    raise exception 'No corrected read (D-R2): a read of this course is already in progress. Nothing was changed' using errcode = '55000';
  end if;
  v_job := security.course_entry_read_enqueue_v1(o.entity_id, p_actor, 'Corrected read (D-R2) of Layer 4 item ' || p_item || ': ' || btrim(p_reason));
  select f.id into v_enrich from pipeline.field_enrich_items f where f.job_id = v_job and f.course_id = o.entity_id and f.field = 'entry_requirements';
  insert into pipeline.aer_read_supersessions(old_item_id, course_id, source_url, old_evidence_id, enrich_item_id, job_id, requested_by, reason)
  values (p_item, o.entity_id, g.url, o.evidence_id, v_enrich, v_job, p_actor, btrim(p_reason)) returning id into v_id;
  return jsonb_build_object('request_id', v_id, 'job_id', v_job, 'enrich_item_id', v_enrich, 'review_item_id', p_item);
end $$;


ALTER FUNCTION "security"."course_entry_correction_v1"("p_item" "uuid", "p_actor" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_entry_correction_v1"("p_item" "uuid", "p_actor" "uuid", "p_reason" "text") IS 'CF-247 D-R2: asks for a corrected read of a waiting course entry read from the same bound page (stored page, security.course_entry_read_enqueue_v1); the read replaces the waiting item only when complete. Owner only (a governed migration or paste); nothing is approved.';



CREATE OR REPLACE FUNCTION "security"."course_entry_cost_v1"() RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- the measured average once 20 course reads have cost something; the setting until then
  select case when count(*) >= 20 then avg(f.cost_usd) else security.pipeline_num_v1('entry.course_read_cost_usd', 0.005) end  -- fixed: 20 reads before the average is trusted
    from pipeline.field_enrich_items f where f.field = 'entry_requirements' and coalesce(f.cost_usd, 0) > 0
$$;


