    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 mandate 3 Nov 2026 13:09 D6: the same eligibility rules as the scheduled reading (security.aer_course_population_v1), not a fixed list
  select p.course_id, p.provider_id, p.prio, p.title from security.aer_course_population_v1() p
$$;


