COMMENT ON FUNCTION "security"."course_entry_eligible_v1"() IS 'CF-247 AER course-level programme (29 Oct 2026): courses whose stored official page and strong identity admit an entry-requirements read (B1), in the plan''s priority order. Owner only.';



CREATE OR REPLACE FUNCTION "security"."course_entry_gate_v1"("p_item" "uuid", "p_exclude" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.layer4_review_items%rowtype; v_drop jsonb; v_cut int; v_joined jsonb; v_other jsonb; v_shared jsonb; v_why text[] := '{}'; v_chk jsonb; v_n int;
begin
  select * into r from pipeline.layer4_review_items where id = p_item;
  if r.id is null or r.field_code <> 'course_entry_first_read' then return null; end if;
  v_drop := coalesce(r.proposed_value->'dropped',
                     (select f.value->'dropped' from pipeline.field_enrich_items f where f.id = nullif(r.proposed_value->>'item_id', '')::bigint), '[]'::jsonb);
  select count(*) into v_cut from jsonb_array_elements(v_drop) d where d->>'reason' = 'over_row_limit';
  select coalesce(jsonb_agg(jsonb_build_object('kind', d->>'kind', 'quote', d->>'quote')), '[]'::jsonb) into v_joined
    from jsonb_array_elements(v_drop) d where d->>'reason' = 'over_row_limit' and security.course_entry_joined_v1(d->>'quote', d->>'kind');
  select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'names', n.v, 'quote', x.quote) order by x.kind, x.id), '[]'::jsonb) into v_other
    from catalogue.course_entry_requirements x cross join lateral (select security.course_entry_variant_v1(x.course_id, x.quote) v) n
   where x.provenance->>'review_item_id' = p_item::text and x.status = 'proposed' and not (x.id = any (coalesce(p_exclude, '{}'::uuid[]))) and n.v is not null;
  v_shared := security.course_entry_shared_page_v1(r.entity_id);
  -- D-R3 (Platform Admin 2 Nov 2026 23:24): the read-level checks on the rows that would be admitted
  v_chk := security.course_entry_read_check_v1(
    (select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'kind', x.kind, 'audience', x.audience, 'quote', x.quote)), '[]'::jsonb)
       from catalogue.course_entry_requirements x
      where x.provenance->>'review_item_id' = p_item::text and x.status = 'proposed' and not (x.id = any (coalesce(p_exclude, '{}'::uuid[])))), v_drop);
  if v_cut > 0 then
    v_why := v_why || format('the reader cut %s requirement(s) on this page at its row limit, so the read is incomplete: reject it', v_cut);
  end if;
  if jsonb_array_length(v_joined) > 0 then
    v_why := v_why || format('%s of the cut requirement(s) belong to a requirement that was kept (for example "%s")', jsonb_array_length(v_joined), left(v_joined->0->>'quote', 80));
  end if;
  if jsonb_array_length(v_other) > 0 then
    v_why := v_why || format('%s waiting row(s) are about another programme (%s): leave them out with Approve except, or reject the read',
                             jsonb_array_length(v_other), (select string_agg(distinct o->>'names', ', ') from jsonb_array_elements(v_other) o));
  end if;
  if jsonb_array_length(v_shared) > 0 then
    v_why := v_why || format('the stored page is also the page of %s other programme(s) (%s), so its rows cannot be told apart by programme: reject the read',
                             jsonb_array_length(v_shared), (select string_agg(t, ', ') from (select jsonb_array_elements_text(v_shared) t limit 3) z)
                             || case when jsonb_array_length(v_shared) > 3 then ', …' else '' end);
  end if;
  v_n := jsonb_array_length(v_chk->'drops_uncovered');
  if v_n > 0 then
    v_why := v_why || format('the reader dropped %s printed requirement(s) that no waiting row covers (%s), so the read is incomplete: replace it with a corrected read, or reject it',
                             v_n, (select string_agg(k || ' ' || c, ', ') from (select d->>'reason' k, count(*) c from jsonb_array_elements(v_chk->'drops_uncovered') d group by 1 order by 1) z));
  end if;
  if jsonb_array_length(v_chk->'not_requirement') > 0 then
    v_why := v_why || format('%s waiting row(s) are not entry requirements (course description, progression, credit, a pointer or an English note): leave them out with Approve except',
                             jsonb_array_length(v_chk->'not_requirement'));
  end if;
  if jsonb_array_length(v_chk->'audience') > 0 then
    v_why := v_why || format('%s waiting row(s) name a domestic route but are stored for %s: leave them out with Approve except',
                             jsonb_array_length(v_chk->'audience'), (select string_agg(distinct a->>'audience', ' or ') from jsonb_array_elements(v_chk->'audience') a));
  end if;
  return jsonb_build_object('rule', 'E13', 'complete', cardinality(v_why) = 0, 'rows_cut', v_cut, 'joined', v_joined, 'other_programme', v_other,
                            'shared_page', v_shared, 'drops_uncovered', v_chk->'drops_uncovered', 'drops_covered', v_chk->'drops_covered',
                            'not_requirement', v_chk->'not_requirement', 'audience', v_chk->'audience', 'reasons', to_jsonb(v_why));
end $$;


ALTER FUNCTION "security"."course_entry_gate_v1"("p_item" "uuid", "p_exclude" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_entry_gate_v1"("p_item" "uuid", "p_exclude" "uuid"[]) IS 'CF-247 E13: whole-read completeness of a Layer 4 course entry item: rows cut by the row limit (joined conditions named), waiting rows about another programme (less the rows left out), and a stored page shared with a differently named programme (entry.shared_page_hold). complete=false holds approval.';



CREATE OR REPLACE FUNCTION "security"."course_entry_joined_v1"("p_quote" "text", "p_kind" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(security.toolset_setting('pipeline', 'entry.joined_condition_kinds'), '[]'::jsonb) ? coalesce(p_kind, '')
      or exists (select 1 from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'entry.joined_condition_words'), '[]'::jsonb)) w
                  where btrim(w) <> ''
                    and lower(regexp_replace(btrim(coalesce(p_quote, '')), '^[^[:alnum:]]+', '')) ~ ('^' || regexp_replace(lower(btrim(w)), '([^[:alnum:] ])', '\\\1', 'g') || '\M'))
$$;


ALTER FUNCTION "security"."course_entry_joined_v1"("p_quote" "text", "p_kind" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_entry_joined_v1"("p_quote" "text", "p_kind" "text") IS 'CF-247 E13: true when a course entry row''s quote starts with a joining word (entry.joined_condition_words) or its kind is in entry.joined_condition_kinds.';



CREATE OR REPLACE FUNCTION "security"."course_entry_max_rows_v1"("p_provider" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  select coalesce(
    (select split_part(e, '=', 2)::int
       from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'entry.max_rows_by_provider'), '[]'::jsonb)) e
       join pipeline.platform_toolset_settings s on s.toolset_key = 'pipeline' and s.key = 'entry.max_rows_per_course'
      where btrim(split_part(e, '=', 1)) = p_provider::text and btrim(split_part(e, '=', 2)) ~ '^[0-9]+$'
        and split_part(e, '=', 2)::numeric between coalesce(s.min_value, split_part(e, '=', 2)::numeric) and coalesce(s.max_value, split_part(e, '=', 2)::numeric)
      limit 1),
    security.pipeline_num_v1('entry.max_rows_per_course', 6)::int)
$_$;


ALTER FUNCTION "security"."course_entry_max_rows_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_entry_max_rows_v1"("p_provider" "uuid") IS 'CF-247 E13: the row limit of a course entry read: the provider''s value in entry.max_rows_by_provider when it lies within the range of entry.max_rows_per_course, otherwise entry.max_rows_per_course.';



CREATE OR REPLACE FUNCTION "security"."course_entry_programme_v1"("p_can_batch" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_cost numeric := security.course_entry_cost_v1(); v_rows jsonb; v_bal numeric; v_floor numeric;
begin
  select o.remaining_usd into v_bal from pipeline.layer3_openrouter_observations o where o.kind = 'credits' order by o.observed_at desc limit 1;
  v_floor := coalesce((security.toolset_setting('openrouter', 'credit_floor_usd'))::text::numeric, 0);
  with el as (select * from security.course_entry_eligible_v1()),
  scope as (select el.provider_id pid, min(el.prio) o from el group by el.provider_id),  -- CF-247 D6 (3 Nov 2026): the providers the eligibility rules give
  it as (select f.course_id, bool_or(f.state in ('queued', 'waiting', 'ai', 'leased')) waiting, bool_or(f.state = 'review') review,
                bool_or(f.state = 'filled') filled, bool_or(f.state = 'skipped') skipped, sum(coalesce(f.cost_usd, 0)) cost
           from pipeline.field_enrich_items f where f.field = 'entry_requirements' group by f.course_id),
  rq as (select x.course_id, count(*) filter (where x.status = 'proposed') proposed, count(*) filter (where x.status = 'active') active,
                count(*) filter (where x.status in ('inactive', 'unverified')) held from catalogue.course_entry_requirements x group by x.course_id),
  per as (select scope.pid, scope.o, coalesce(p.display_name, p.canonical_name) provider_name, k.iso_alpha2 country,
                 count(el.course_id) eligible,
                 count(el.course_id) filter (where it.course_id is not null and not it.waiting) read,
                 count(el.course_id) filter (where it.waiting) waiting,
                 count(el.course_id) filter (where coalesce(rq.proposed, 0) > 0) in_layer4,
                 coalesce(sum(rq.proposed), 0) proposed_rows,
                 count(el.course_id) filter (where coalesce(rq.active, 0) > 0) admitted,
                 coalesce(sum(rq.active), 0) active_rows,
                 count(el.course_id) filter (where it.course_id is not null and not it.waiting and coalesce(rq.proposed, 0) = 0 and coalesce(rq.active, 0) = 0) no_rows,
                 count(el.course_id) filter (where it.course_id is null) remaining,
                 coalesce(sum(it.cost), 0) spent
            from scope join catalogue.providers p on p.id = scope.pid left join ref.countries k on k.id = p.country_id
            left join el on el.provider_id = scope.pid left join it on it.course_id = el.course_id left join rq on rq.course_id = el.course_id
           group by scope.pid, scope.o, p.display_name, p.canonical_name, k.iso_alpha2)
  select coalesce(jsonb_agg(jsonb_build_object('provider_id', pid, 'provider_name', provider_name, 'country', country, 'eligible', eligible, 'read', read, 'waiting', waiting,
           'in_layer4', in_layer4, 'proposed_rows', proposed_rows, 'admitted', admitted, 'active_rows', active_rows, 'no_rows', no_rows, 'remaining', remaining,
           'spent_usd', round(spent, 4), 'estimate_remaining_usd', round(remaining * v_cost, 2)) order by o), '[]'::jsonb) into v_rows from per;
  return jsonb_build_object('providers', v_rows, 'cost_per_course_usd', round(v_cost, 5),
    'cost_basis', case when (select count(*) from pipeline.field_enrich_items f where f.field = 'entry_requirements' and coalesce(f.cost_usd, 0) > 0) >= 20 then 'measured' else 'setting' end,
    'batch_size', security.pipeline_num_v1('entry.course_batch_size', 50)::int, 'balance_usd', v_bal, 'floor_usd', v_floor,
    'countries', (select coalesce(jsonb_agg(cc order by cc), '[]'::jsonb) from unnest(security.catalogue_country_codes_v1()) cc  -- CF-247 D6: the countries switched on
                   where (security.aer_schedule_country_v1(cc)->>'on')::boolean and coalesce(security.toolset_setting('pipeline', 'aer.eligible_countries'), '[]'::jsonb) ? cc),
    'ai_allowed', security.ai_use_allowed_v1('enrich_fields'),
    'waiting', (select count(*) from pipeline.field_enrich_items f where f.field = 'entry_requirements' and f.state in ('queued', 'waiting', 'ai', 'leased')),
    'can_batch', p_can_batch);
end $$;


ALTER FUNCTION "security"."course_entry_programme_v1"("p_can_batch" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_entry_programme_v1"("p_can_batch" boolean) IS 'CF-247 AER course-level programme (29 Oct 2026): per-provider eligible, read, waiting, Layer 4, admitted, no-row and remaining courses, cost and balance. Read through public.admin_aer(''course_programme''). Owner only.';



CREATE OR REPLACE FUNCTION "security"."course_entry_read_check_v1"("p_rows" "jsonb", "p_dropped" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with s as (select coalesce(security.toolset_setting('pipeline', 'entry.gate_hold_reasons'), '[]'::jsonb) hold,
                    coalesce(security.toolset_setting('pipeline', 'entry.nonrequirement_patterns'), '[]'::jsonb) pat,
                    coalesce(security.toolset_setting('pipeline', 'entry.domestic_audience_words'), '[]'::jsonb) dom,
                    security.pipeline_num_v1('entry.gate_cover_chars', 40)::int n, security.pipeline_num_v1('entry.gate_cover_min_chars', 12)::int m),
  r as (select x, lower(regexp_replace(coalesce(x->>'quote', ''), '[^[:alnum:]]', '', 'g')) fq from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) x),
  d as (select y, lower(regexp_replace(coalesce(y->>'quote', ''), '[^[:alnum:]]', '', 'g')) fq
          from jsonb_array_elements(coalesce(p_dropped, '[]'::jsonb)) y, s where s.hold ? coalesce(y->>'reason', '')),
  dc as (select d.y, exists (select 1 from r, s where length(d.fq) >= s.m and strpos(r.fq, left(d.fq, s.n)) > 0) cov from d)
  select jsonb_build_object(
    'drops_uncovered', (select coalesce(jsonb_agg(jsonb_build_object('reason', y->>'reason', 'kind', y->>'kind', 'quote', left(y->>'quote', 160))), '[]'::jsonb) from dc where not cov),
    'drops_covered', (select count(*) from dc where cov),
    'not_requirement', (select coalesce(jsonb_agg(jsonb_build_object('id', r.x->>'id', 'quote', left(r.x->>'quote', 160))), '[]'::jsonb) from r, s
                         where exists (select 1 from jsonb_array_elements_text(s.pat) p where btrim(p) <> '' and coalesce(r.x->>'quote', '') ~* p)),
    'audience', (select coalesce(jsonb_agg(jsonb_build_object('id', r.x->>'id', 'audience', r.x->>'audience', 'quote', left(r.x->>'quote', 160))), '[]'::jsonb) from r, s
                  where coalesce(r.x->>'audience', 'all') <> 'domestic'
                    and exists (select 1 from jsonb_array_elements_text(s.dom) w where btrim(w) <> '' and coalesce(r.x->>'quote', '') ~* w)))
$$;


ALTER FUNCTION "security"."course_entry_read_check_v1"("p_rows" "jsonb", "p_dropped" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_entry_read_check_v1"("p_rows" "jsonb", "p_dropped" "jsonb") IS 'CF-247 D-R3/E13 extension: the read-level checks of a course entry read: dropped minimums (entry.gate_hold_reasons) no kept row covers, rows that are not entry requirements (entry.nonrequirement_patterns), and domestic routes stored for everyone (entry.domestic_audience_words).';



CREATE OR REPLACE FUNCTION "security"."course_entry_read_enqueue_v1"("p_course" "uuid", "p_by" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_job uuid; c record;
begin
  select x.id, x.provider_id, x.canonical_title into c from catalogue.courses x where x.id = p_course;
  -- a person (or the decided slice) asked, with a reason: an earlier "no value" hold on this field is released so the read is not refused
  update pipeline.enrichment_flags f set state = 'released', released_at = now(), released_by = p_by, release_kind = 'person',
         release_reason = 'Entry requirements read: ' || p_reason, updated_at = now()
   where f.entity = 'course' and f.entity_key = p_course::text and f.reason_code = 'enrich_no_value' and f.state in ('raised', 'counting') and f.field = 'entry_requirements';
  insert into pipeline.admin_jobs(kind, lane, state, title, args, progress, requested_by, reason, scope)
  values ('enrich_fields', 'enrich', 'queued', left('Entry requirements · ' || c.canonical_title, 200),
          jsonb_build_object('read_now', true, 'entry_read', true, 'countries', '[]'::jsonb, 'provider_ids', jsonb_build_array(c.provider_id), 'course_ids', jsonb_build_array(c.id),
                             'fields', jsonb_build_array('entry_requirements'), 'ai', true, 'scraper', false),
          jsonb_build_object('done', 0, 'total', 1), p_by, p_reason, '1 course')
  returning id into v_job;
  insert into pipeline.field_enrich_items(job_id, provider_id, course_id, field, state) values (v_job, c.provider_id, c.id, 'entry_requirements', 'queued') on conflict do nothing;
  if not exists (select 1 from pipeline.field_enrich_items f where f.job_id = v_job) then raise exception 'the entry requirements item was refused by the item gate'; end if;
  return v_job;
end $$;


ALTER FUNCTION "security"."course_entry_read_enqueue_v1"("p_course" "uuid", "p_by" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_entry_read_enqueue_v1"("p_course" "uuid", "p_by" "uuid", "p_reason" "text") IS 'CF-247 Track C Step B (B1): one Enrich fields task with one entry_requirements item for one course (stored page only); releases the field''s earlier no-value hold first.';



CREATE OR REPLACE FUNCTION "security"."course_entry_review_apply_v1"("p_item" "uuid", "p_action" "text", "p_final" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.layer4_review_items%rowtype; v_ex uuid[]; v_on int := 0; v_off int := 0; v_sup int := 0; v_enrich bigint; v_gate jsonb;
begin
  select * into r from pipeline.layer4_review_items where id = p_item;
  if r.id is null or r.field_code <> 'course_entry_first_read' then raise exception 'not a course entry review item'; end if;
  v_enrich := nullif(r.proposed_value->>'item_id', '')::bigint;
  if p_action = 'approve' then
    v_ex := coalesce(array(select jsonb_array_elements_text(coalesce(p_final->'exclude_row_ids', '[]'::jsonb))::uuid), '{}');
    -- E13 (Platform Admin 2 Nov 2026 05:18): an incomplete read never reaches approval. Rows cut by the row limit (a joined condition among
    -- them named), a waiting row about another programme that is not left out, or a page shared with another programme hold the whole
    -- decision; nothing is changed
    v_gate := security.course_entry_gate_v1(p_item, v_ex);
    if v_gate is not null and not coalesce((v_gate->>'complete')::boolean, true) then
      raise exception 'Held (E13, incomplete read): %. Nothing was changed',
        (select string_agg(w, '; ') from jsonb_array_elements_text(v_gate->'reasons') w) using errcode = '55000';
    end if;
    -- D4 (Platform Admin 30 Oct 2026 08:45): course rows have no identity key, so an excluded row cannot be matched to the active row it would
    -- replace; Approve except on a course that already has active rows holds the whole decision rather than guess
    if cardinality(v_ex) > 0 and exists (select 1 from catalogue.course_entry_requirements x
                                         where x.course_id = r.entity_id and x.status = 'active' and x.provenance->>'reader' = 'enrich_ai') then
      raise exception 'Held (decision D4): course % has % active entry requirement rows and course rows have no identity to match an excluded row to the row it would replace; nothing was changed. Use Approve all rows if every waiting row is right, or Reject the read',
        r.entity_id, (select count(*) from catalogue.course_entry_requirements x where x.course_id = r.entity_id and x.status = 'active' and x.provenance->>'reader' = 'enrich_ai')
        using errcode = '55000';
    end if;
    update catalogue.course_entry_requirements x set status = 'superseded', status_reason = 'replaced by Layer 4 item ' || p_item, updated_at = now()
     where x.course_id = r.entity_id and x.status = 'active' and x.provenance->>'reader' = 'enrich_ai';
    get diagnostics v_sup = row_count;
    -- A1: an excluded row stays unadmitted and identifiable: inactive, its reason names the item and the reviewer, provenance keeps the record
    update catalogue.course_entry_requirements x set status = 'inactive',
           status_reason = 'excluded by approve except (Layer 4 item ' || p_item::text || ', reviewer ' || coalesce(p_final->>'reviewer', 'unknown') || '): ' || coalesce(p_reason, ''),
           provenance = coalesce(x.provenance, '{}'::jsonb) || jsonb_build_object('aer_exclusion', jsonb_build_object('review_item_id', p_item,
             'enrich_item_id', v_enrich, 'evidence_id', x.evidence_id, 'reviewer', p_final->>'reviewer', 'reason', p_reason, 'at', now(), 'decision', 'approve_except (A1)')),
           updated_at = now()
     where x.provenance->>'review_item_id' = p_item::text and x.status = 'proposed' and x.id = any (v_ex);
    get diagnostics v_off = row_count;
    update catalogue.course_entry_requirements x set status = 'active', status_reason = null, updated_at = now()
     where x.provenance->>'review_item_id' = p_item::text and x.status = 'proposed';
    get diagnostics v_on = row_count;
    update pipeline.field_enrich_items set state = 'filled', updated_at = now() where id = v_enrich and state = 'review';
  else
    update catalogue.course_entry_requirements x set status = 'inactive', status_reason = 'quarantined (' || p_action || '): ' || coalesce(p_reason, ''), updated_at = now()
     where x.provenance->>'review_item_id' = p_item::text and x.status = 'proposed';
    get diagnostics v_off = row_count;
    update pipeline.field_enrich_items set state = 'skipped', reason = 'Layer 4 ' || p_action || ' (not admitted)', updated_at = now() where id = v_enrich and state = 'review';
  end if;
  return jsonb_build_object('course_entry_review', p_item, 'admitted', v_on, 'quarantined', v_off, 'superseded', v_sup);
end $$;


ALTER FUNCTION "security"."course_entry_review_apply_v1"("p_item" "uuid", "p_action" "text", "p_final" "jsonb", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_entry_review_apply_v1"("p_item" "uuid", "p_action" "text", "p_final" "jsonb", "p_reason" "text") IS 'CF-247 Track C Step B (B1): a Layer 4 decision on course_entry_first_read admits the read''s rows (approve; edit-and-approve may exclude rows) or makes them inactive.';



CREATE OR REPLACE FUNCTION "security"."course_entry_review_trg_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.status in ('rejected', 'more_evidence', 'returned_layer2', 'returned_layer3', 'superseded') then
    perform security.course_entry_review_apply_v1(new.id, new.status, null, 'Layer 4 ' || new.status);
  end if;
  return new;
end $$;


ALTER FUNCTION "security"."course_entry_review_trg_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_entry_shared_page_v1"("p_course" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(distinct c2.canonical_title), '[]'::jsonb)
    from pipeline.coverage_course_pages g1
    join catalogue.courses c1 on c1.id = g1.course_id
    join pipeline.coverage_course_pages g2 on g2.url = g1.url and g2.course_id <> g1.course_id
    join catalogue.courses c2 on c2.id = g2.course_id
   where g1.course_id = p_course
     and lower(regexp_replace(regexp_replace(c2.canonical_title, '\(Level [0-9]+\)', '', 'gi'), '[^[:alnum:]]', '', 'g'))
         <> lower(regexp_replace(regexp_replace(c1.canonical_title, '\(Level [0-9]+\)', '', 'gi'), '[^[:alnum:]]', '', 'g'))
     and security.pipeline_num_v1('entry.shared_page_hold', 1) >= 1 and security.pipeline_num_v1('entry.variant_check', 1) >= 1
     and not (coalesce(security.toolset_setting('pipeline', 'entry.variant_check_off_providers'), '[]'::jsonb) ? c1.provider_id::text)
     -- CF-247 (8 Nov 2026): a binding the identity check refused (status mismatch) is not a claim on the page. The relaxation is for a course whose own binding the identity check
     -- accepted on a strong basis and which has no hand lock; every other course keeps the old rule (all statuses count).
     and (g2.status = any (array(select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'entry.shared_page_count_statuses'), '["bound", "ambiguous"]'::jsonb))))
          or g1.status is distinct from 'bound'
          or not (coalesce(security.toolset_setting('pipeline', 'entry.shared_page_own_bases'), '[]'::jsonb) ? coalesce(g1.identity_basis, ''))
          or exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = g1.course_id and l.field in ('official_url', 'course_url')))
$$;


ALTER FUNCTION "security"."course_entry_shared_page_v1"("p_course" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_entry_shared_page_v1"("p_course" "uuid") IS 'CF-247 E13 (factored out by D-R2; 8 Nov 2026 edit): the differently named programmes whose stored page is also this course''s page (entry.shared_page_hold). A binding the identity check refused (mismatch) does not count for a course that is itself bound on a strong identity basis and has no hand lock (entry.shared_page_count_statuses, entry.shared_page_own_bases).';



CREATE OR REPLACE FUNCTION "security"."course_entry_variant_v1"("p_course" "uuid", "p_quote" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  with aw as (select btrim(split_part(e, '=', 1)) abbr, btrim(split_part(e, '=', 2)) long
                from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'entry.award_abbreviations'), '[]'::jsonb)) e
               where btrim(split_part(e, '=', 1)) <> '' and btrim(split_part(e, '=', 2)) <> ''),
  -- the course's own programme: title without bracketed parts, its credit value in brackets, its award and the capitals of its field
  c as (select x.provider_id, btrim(coalesce(p_quote, '')) q, btrim(regexp_replace(x.canonical_title, '\s*\([^)]*\)', '', 'g')) base,
               substring(x.canonical_title from '\(([0-9]{2,3})(?:\s*(?:[Cc]redits?|[Pp]oints?))?\)') credit
          from catalogue.courses x
         where x.id = p_course and btrim(coalesce(p_quote, '')) <> '' and security.pipeline_num_v1('entry.variant_check', 1) >= 1
           and not (coalesce(security.toolset_setting('pipeline', 'entry.variant_check_off_providers'), '[]'::jsonb) ? x.provider_id::text)),
  own as (select c.*, a.abbr award, (select string_agg(upper(left(w, 1)), '' order by n) from regexp_split_to_table(coalesce(a.field, ''), '\s+') with ordinality t(w, n)
                                     where w <> '' and lower(w) not in ('of', 'in', 'and', '&', 'the', 'with', 'for')) init
            from c left join lateral (select aw.abbr, btrim(regexp_replace(substr(c.base, length(aw.long) + 1), '^\s*(of|in)\s+', '', 'i')) field
                                        from aw where lower(c.base) like lower(aw.long) || ' %' order by length(aw.long) desc limit 1) a on true),
  -- where a quote names the programme it is about
  cand as (select 1 k, 'subject' mode, btrim((regexp_match(own.q, '(?:entry|admission)\s+requirements?\s+(?:for|of)\s+(?:the\s+)?(.*)$', 'i'))[1]) t from own
           union all select 2, 'subject', btrim((regexp_match(own.q, '^an?\s+(.*)\s+applicants?\M', 'i'))[1]) from own
           union all select 3, 'heading', own.q from own),
  -- 1. an abbreviation: award short form, then the capitals of the field, then the credit
  r1 as (select cand.k, nm.name || coalesce(' (' || nm.credit || ')', '') v
           from own cross join cand
           cross join lateral (select substring(cand.t from '^([A-Z][A-Za-z]*[A-Z][A-Za-z]*)') name,
                                      substring(cand.t from '^[A-Za-z]+\s*\(([0-9]{2,3})(?:\s*(?:[Cc]redits?|[Pp]oints?))?\)') credit) nm
           join lateral (select aw.abbr, regexp_replace(substr(nm.name, length(aw.abbr) + 1), '[^A-Z]', '', 'g') rest
                           from aw where left(nm.name, length(aw.abbr)) = aw.abbr and length(nm.name) > length(aw.abbr) order by length(aw.abbr) desc limit 1) ab on true
          where cand.t is not null and own.award is not null
            and (cand.mode <> 'heading' or cand.t ~ '^[A-Z][A-Za-z]*[A-Z][A-Za-z]*(\s*\([^)]*\))?(\s*(,|and|&)\s*[A-Z][A-Za-z]*[A-Z][A-Za-z]*(\s*\([^)]*\))?)*\s+[A-Z]')
            and (ab.abbr <> own.award or (own.init is not null and ab.rest <> '' and ab.rest <> own.init)
                 or (nm.credit is not null and own.credit is not null and nm.credit <> own.credit))),
  -- 2. a programme title of the same provider (the longest that fits decides; the course's own title with the same credit is not another)
  r2 as (select cand.k, (select z.t || coalesce(' (' || z.credit || ')', '')
                           from (select y.t, substring(substr(cand.t, length(y.t) + 1) from '^\s*\(([0-9]{2,3})(?:\s*(?:[Cc]redits?|[Pp]oints?))?\)') credit
                                   from (select distinct btrim(regexp_replace(s.canonical_title, '\s*\([^)]*\)', '', 'g')) t
                                           from catalogue.courses s where s.provider_id = own.provider_id) y
                                  where y.t <> '' and left(lower(cand.t), length(y.t)) = lower(y.t)
                                    and exists (select 1 from aw where lower(y.t) like lower(aw.long) || ' %')
                                    and (cand.mode <> 'heading' or substr(cand.t, length(y.t) + 1) ~ '^\s*(\([^)]*\))?\s+[A-Z]')
                                    and (cand.mode <> 'subject' or substr(cand.t, length(y.t) + 1) ~ '^(\s*\([^)]*\))?([^[:alnum:]]|$)')
                                  order by length(y.t) desc, y.t limit 1) z
                          where lower(z.t) <> lower(own.base) or (z.credit is not null and own.credit is not null and z.credit <> own.credit)) v
           from cand cross join own where cand.t is not null)
  select coalesce((select v from r1 order by k limit 1), (select v from r2 where v is not null order by k limit 1))
$_$;


ALTER FUNCTION "security"."course_entry_variant_v1"("p_course" "uuid", "p_quote" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_entry_variant_v1"("p_course" "uuid", "p_quote" "text") IS 'CF-247 E13: the other programme (sibling variant) a course entry quote is about, or null when it is the course''s own or the check does not apply (entry.variant_check, entry.variant_check_off_providers, entry.award_abbreviations).';



CREATE OR REPLACE FUNCTION "security"."course_fee_dedupe_v1"("p_apply" boolean DEFAULT false, "p_course_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'search', 'pipeline'
    AS $$
declare v_list jsonb; v_n int := 0; v_courses uuid[];
begin
  with a as (
    select f.*, security.course_fee_rank_key(f) rk,
           count(*) over (partition by f.course_id, f.audience, f.fee_type, f.amount) n
    from catalogue.course_fees f
    where f.fee_type='provider_current_tuition' and f.status='active'
      and (p_course_ids is null or f.course_id = any(p_course_ids))),
  r as (select a.*, row_number() over (partition by course_id, audience, fee_type, amount order by rk desc) pos from a where n>1)
  select jsonb_agg(jsonb_build_object('course',(select course_code from catalogue.courses c where c.id=r.course_id),
            'keep', pos=1, 'amount', amount, 'year', fee_year, 'basis', basis, 'origin',
            case when notes like 'CF-247 provider rule admission%' then 'provider rule' when notes ilike '%layer 3%' then 'Layer 3 AI' else 'other' end)
          order by course_id, pos),
         array_agg(distinct course_id)
  into v_list, v_courses from r;
  if p_apply and v_courses is not null then
    with a as (
      select f.id, row_number() over (partition by f.course_id, f.audience, f.fee_type, f.amount order by security.course_fee_rank_key(f) desc) pos,
             count(*) over (partition by f.course_id, f.audience, f.fee_type, f.amount) n
      from catalogue.course_fees f
      where f.fee_type='provider_current_tuition' and f.status='active' and f.course_id = any(v_courses))
    update catalogue.course_fees f set status='superseded', updated_at=now(),
           notes = f.notes || ' | superseded by one-current-tuition rule (Decision 132) ' || to_char(now(),'YYYY-MM-DD')
    from a where a.id=f.id and a.n>1 and a.pos>1;
    get diagnostics v_n = row_count;
    update catalogue.course_fees f set basis=pf.resolved_basis, updated_at=now(),
           notes = f.notes || ' | basis set to the approved provider rule wording (' || pf.rule_code || ', Decision 132)'
    from catalogue.courses c
    join pipeline.provider_fee_profiles pf on pf.provider_id=c.provider_id and pf.active
    where c.id=f.course_id and f.course_id = any(v_courses) and f.status='active'
      and f.fee_type='provider_current_tuition' and f.audience=pf.audience
      and f.basis='annual' and pf.resolved_basis<>'annual';
    perform search.refresh_course_enrichment_scoped_v1(v_courses, true);
  end if;
  return jsonb_build_object('mode',case when p_apply then 'apply' else 'proof' end,'courses',coalesce(cardinality(v_courses),0),'superseded',v_n,'rows',coalesce(v_list,'[]'::jsonb));
end $$;


ALTER FUNCTION "security"."course_fee_dedupe_v1"("p_apply" boolean, "p_course_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_fee_identity_gate_tg"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_ident text; v_url text; v_cc text; v_pid uuid;
begin
  if new.fee_type is distinct from 'provider_current_tuition' or new.status is distinct from 'active' then return new; end if;
  if tg_op = 'UPDATE' and old.status = 'active' and old.amount is not distinct from new.amount and old.fee_year is not distinct from new.fee_year then return new; end if;
  if coalesce(current_setting('cf.manual_edit', true), '') = 'on' or auth.uid() is not null then return new; end if;
  if security.pipeline_num_v1('fees.identity_gate_on', 1) < 1 then return new; end if;
  select p.identity_basis, p.url, k.iso_alpha2, c.provider_id into v_ident, v_url, v_cc, v_pid
    from pipeline.coverage_course_pages p
    join catalogue.courses c on c.id = p.course_id
    join catalogue.providers pr on pr.id = c.provider_id join ref.countries k on k.id = pr.country_id
   where p.course_id = new.course_id and p.status = 'bound' and coalesce(p.basis, '') <> 'manual' and p.identity_basis is not null
     and p.identity_basis <> 'manual' and not security.coverage_identity_allowed(c.provider_id, p.identity_basis, 'tuition') limit 1;
  if v_ident is null then return new; end if;
  new.status := 'unverified';
  if not exists (select 1 from pipeline.layer4_review_items l where l.entity_type = 'course' and l.entity_id = new.course_id and l.field_code = 'provider_current_tuition' and l.status = 'pending') then
    insert into pipeline.layer4_review_items(entity_type, entity_id, field_code, evidence_id, before_value, proposed_value, layer2_state, layer3_state, status, escalation_reason, change_control_ref)
    values ('course', new.course_id, 'provider_current_tuition', new.evidence_id, null,
            jsonb_build_object('amount', new.amount, 'currency', new.currency_code, 'basis', new.basis, 'fee_year', new.fee_year, 'page', v_url),
            jsonb_build_object('source', 'identity_basis_reverify', 'state', 'quarantined', 'country', v_cc, 'identity_basis', v_ident, 'page', v_url, 'gate', 'table'),
            '{}'::jsonb, 'pending',
            'quarantined at the write: the course page was bound with a ' || v_ident || ' proof, which the ' || v_cc || ' tuition policy does not accept; re-binding the page under the country''s rule re-admits the fee',
            'CF-CHG-20260915-247 gate hotfix 26 Oct 2026 (identity gate at the table)');
  end if;
  return new;
end $$;


ALTER FUNCTION "security"."course_fee_identity_gate_tg"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_fee_identity_gate_tg"() IS 'CF-247 gate hotfix (Platform Admin 26 Oct 2026 19:27): every writer of an international provider fee passes the country tuition identity check at the table; a person''s own write and the manual-edit flag are exempt';



CREATE OR REPLACE FUNCTION "security"."course_fee_one_current_trg"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue'
    AS $$
begin
  if new.fee_type='provider_current_tuition' and new.status='active' then
    perform security.course_fee_dedupe_v1(true, array[new.course_id]);
  end if;
  return null;
end $$;


