CREATE OR REPLACE FUNCTION "security"."course_link_backlog_report_v1"("p_provider" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with w as (select i.id, c.provider_id, coalesce(p.short_name, p.canonical_name) prov, security.course_link_route_class_v1(i.id) v
               from pipeline.layer4_review_items i join catalogue.courses c on c.id = i.entity_id left join catalogue.providers p on p.id = c.provider_id
              where i.status = 'pending' and i.field_code = 'official_course_url' and i.entity_type = 'course' and (p_provider is null or c.provider_id = p_provider)),
  per as (select prov, jsonb_object_agg(cls, n) by_class, sum(n) n from (select prov, v->>'class' cls, count(*) n from w group by 1, 2) z group by prov)
  select jsonb_build_object(
    'pending', (select count(*) from w),
    'by_group', (select coalesce(jsonb_object_agg(g, n), '{}'::jsonb) from (select coalesce(v->>'group', '-') g, count(*) n from w group by 1) z),
    'by_class', (select coalesce(jsonb_object_agg(k, n), '{}'::jsonb) from (select v->>'class' k, count(*) n from w group by 1) z),
    'automatically_resolved_7d', (select count(*) from pipeline.layer4_supersessions s where s.field_code = 'official_course_url' and s.reversed_at is null and s.at > now() - make_interval(days => security.pipeline_num_v1('layer4.lifecycle_report_days', 7)::int))
                                 + (select count(*) from pipeline.layer4_review_items i where i.field_code = 'official_course_url' and i.status = 'superseded' and i.decided_at > now() - make_interval(days => security.pipeline_num_v1('layer4.lifecycle_report_days', 7)::int)
                                      and i.change_control_ref like '%Decision 179 (Platform Admin 3 Nov 2026 20:29): moved to Course page needed%'),
    'technical_holds', (select count(*) from w where v->>'group' = 'B'),
    'human_input', (select count(*) from w where v->>'group' = 'D'),
    'review_ready', (select count(*) from w where v->>'group' = 'C'),
    'decided_7d', (select count(*) from pipeline.layer4_decisions d join pipeline.layer4_review_items i on i.id = d.review_item_id
                    where i.field_code = 'official_course_url' and d.created_at > now() - make_interval(days => security.pipeline_num_v1('layer4.lifecycle_report_days', 7)::int)),
    'admitted_7d', (select count(*) from pipeline.layer4_decisions d join pipeline.layer4_review_items i on i.id = d.review_item_id
                     where i.field_code = 'official_course_url' and d.action in ('approve', 'edit') and d.created_at > now() - make_interval(days => security.pipeline_num_v1('layer4.lifecycle_report_days', 7)::int)),
    'per_university', (select coalesce(jsonb_object_agg(prov, jsonb_build_object('pending', n, 'by_class', by_class)), '{}'::jsonb) from per))
$$;


ALTER FUNCTION "security"."course_link_backlog_report_v1"("p_provider" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_link_bind_v1"("p_course_id" "uuid", "p_provider_id" "uuid", "p_url" "text", "p_basis" "text") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  insert into pipeline.coverage_course_pages(course_id, provider_id, url, basis, status, bound_at, next_read_at, read_attempts)
  select p_course_id, p_provider_id, p_url, p_basis, 'bound', now(), now(), 0
   where not security.page_refused_v1(p_course_id, p_url)  -- S1: rejections and blocks
  on conflict (course_id) do update set url = excluded.url, basis = excluded.basis, status = 'bound', bound_at = now(),
         score = null, runner_up = null, read_status = null, read_at = null, http_status = null, fetched_via = null,
         identity_basis = null, evidence_id = null, candidates = null, leased_until = null, read_attempts = 0, next_read_at = now()
   where pipeline.coverage_course_pages.status <> 'bound' or pipeline.coverage_course_pages.basis in ('cricos_search','title_search')
      or exists (select 1 from pipeline.page_refind r where r.course_id = pipeline.coverage_course_pages.course_id and r.state = 'open');  -- 19 Oct 2026: an open re-find may replace a bound page
$$;


ALTER FUNCTION "security"."course_link_bind_v1"("p_course_id" "uuid", "p_provider_id" "uuid", "p_url" "text", "p_basis" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_link_hold_basis_v1"("p_course" "uuid", "p_link_type" "text", "p_url" "text", "p_source" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_norm text := security.course_link_norm_v1(p_url); v_status text; v_r jsonb;
begin
  if p_course is null or coalesce(btrim(p_url), '') = '' then return null; end if;
  select l.status into v_status from catalogue.course_links l where l.course_id = p_course and l.link_type = p_link_type and l.url = p_url;
  -- an active link is never held: a re-read of the shown page goes on as before
  if v_status = 'active' then return null; end if;
  -- superseded or retired: the address itself was set aside (a person, the link tranche, a Layer 4 decision or rule, an award clean-up)
  if v_status in ('inactive', 'deprecated') then
    return jsonb_build_object('route', case v_status when 'deprecated' then 'retired' else 'superseded' end, 'status', v_status);
  end if;
  -- a new spelling of a page set aside (La Trobe '#/overview?studentType=int': the same page under security.course_link_norm_v1)
  if v_status is null then
    select jsonb_build_object('route', case l.status when 'deprecated' then 'retired' else 'superseded' end, 'same_page_as', l.url, 'status', l.status) into v_r
      from catalogue.course_links l
     where l.course_id = p_course and l.link_type = p_link_type and l.status in ('inactive', 'deprecated') and security.course_link_norm_v1(l.url) = v_norm
     limit 1;
    if v_r is not null then return v_r; end if;
  end if;
  -- retired: written from a retired source
  if p_source is not null and exists (select 1 from pipeline.sources s where s.id = p_source and s.status = 'retired') then
    return jsonb_build_object('route', 'retired', 'source_id', p_source);
  end if;
  if p_link_type is distinct from 'official_course' then return null; end if;
  -- held: an open binding remediation hold (SS-007, E16 containment)
  if security.course_held_v1(p_course) then return jsonb_build_object('route', 'held', 'hold', 'course_remediation_holds'); end if;
  -- held: a link that is not active waits while a Layer 4 course-link review is pending on the course
  if v_status is not null then
    select jsonb_build_object('route', 'held', 'layer4_item', i.id, 'status', v_status) into v_r
      from pipeline.layer4_review_items i
     where i.entity_id = p_course and i.field_code = 'official_course_url' and i.status = 'pending' and i.entity_type = 'course'
     limit 1;
    if v_r is not null then return v_r; end if;
  end if;
  -- rejected: a page rejection or block for the course at the same page
  select jsonb_build_object('route', 'rejected', 'page_rejection', r.source, 'rejected_at', r.rejected_at) into v_r
    from pipeline.page_rejections r where r.course_id = p_course and security.course_link_norm_v1(r.url) = v_norm limit 1;
  if v_r is not null then return v_r; end if;
  select jsonb_build_object('route', 'rejected', 'page_block', b.reason, 'blocked_at', b.created_at) into v_r
    from pipeline.course_page_blocks b where b.course_id = p_course and security.course_link_norm_v1(b.url) = v_norm limit 1;
  if v_r is not null then return v_r; end if;
  -- rejected: a Layer 4 decision kept the page we hold instead of this one, and no later decision approved it
  select jsonb_build_object('route', 'rejected', 'layer4_item', i.id, 'decided_at', i.decided_at) into v_r
    from pipeline.layer4_review_items i
   where i.entity_id = p_course and i.field_code = 'official_course_url' and i.status = 'rejected' and i.entity_type = 'course'
     and security.course_link_norm_v1(coalesce(i.proposed_value->>'course_url', i.proposed_value->>'url')) = v_norm
     and not exists (select 1 from pipeline.layer4_review_items a
                      where a.entity_id = p_course and a.field_code = 'official_course_url' and a.status in ('approved', 'edited_approved') and a.entity_type = 'course'
                        and security.course_link_norm_v1(coalesce(a.proposed_value->>'course_url', a.proposed_value->>'url')) = v_norm
                        and coalesce(a.decided_at, a.created_at) > coalesce(i.decided_at, i.created_at))
   order by i.decided_at desc nulls last limit 1;
  if v_r is not null then return v_r; end if;
  -- superseded: a later approved Layer 4 decision replaced this page with another one
  select jsonb_build_object('route', 'superseded', 'layer4_item', i.id, 'decided_at', i.decided_at) into v_r
    from pipeline.layer4_review_items i
   where i.entity_id = p_course and i.field_code = 'official_course_url' and i.status = 'approved' and i.entity_type = 'course'
     and jsonb_typeof(i.before_value) = 'array'
     and exists (select 1 from jsonb_array_elements_text(i.before_value) b where security.course_link_norm_v1(b) = v_norm)
     and security.course_link_norm_v1(coalesce(i.proposed_value->>'course_url', i.proposed_value->>'url')) <> v_norm
     and not exists (select 1 from pipeline.layer4_review_items a
                      where a.entity_id = p_course and a.field_code = 'official_course_url' and a.status in ('approved', 'edited_approved') and a.entity_type = 'course'
                        and security.course_link_norm_v1(coalesce(a.proposed_value->>'course_url', a.proposed_value->>'url')) = v_norm
                        and coalesce(a.decided_at, a.created_at) > coalesce(i.decided_at, i.created_at))
   order by i.decided_at desc nulls last limit 1;
  return v_r;
end $$;


ALTER FUNCTION "security"."course_link_hold_basis_v1"("p_course" "uuid", "p_link_type" "text", "p_url" "text", "p_source" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_link_hold_basis_v1"("p_course" "uuid", "p_link_type" "text", "p_url" "text", "p_source" "uuid") IS 'IQ-00043 (Platform Admin 3 Nov 2026 08:44 §5): why a course link address must not become active again (route superseded, retired, rejected or held, with its basis), or null. An active link is never held. Addresses compare under security.course_link_norm_v1 (query kept).';



CREATE OR REPLACE FUNCTION "security"."course_link_norm_v1"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select regexp_replace(regexp_replace(regexp_replace(regexp_replace(lower(btrim(coalesce(p, ''))), '^https?://(www\.)?', ''), '#.*$', ''), '/+(\?|$)', '\1'), '\?$', '')
$_$;


ALTER FUNCTION "security"."course_link_norm_v1"("p" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_link_norm_v1"("p" "text") IS 'IQ-00043: a course link address for comparison (lower case, no scheme, www, fragment or trailing slash; the query kept, as it names the page on query-addressed catalogues).';



CREATE OR REPLACE FUNCTION "security"."course_link_pick_v1"("p_provider_id" "uuid", "p_urls" "text"[]) RETURNS "text"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $_$
  with pat as (select ord, e->>'re' re, replace(e->>'rep','{year}',extract(year from now())::int::text) rep
                 from pipeline.course_link_recipes r, jsonb_array_elements(r.patterns) with ordinality x(e, ord)
                where r.provider_id = p_provider_id and r.active),
       u as (select case when url ~* '\.(php|aspx?|cfm|jsp)\?' then regexp_replace(url, '#.*$', '') else regexp_replace(url, '[?#].*$', '') end url, i from unnest(p_urls) with ordinality y(url, i) where url is not null),
       m as (select pat.ord, u.i, regexp_replace(u.url, pat.re, pat.rep) cand from pat join u on u.url ~ pat.re),
       d as (select cand, min(ord*1000+i) k from m group by cand)
  select coalesce(array_agg(cand order by k), '{}') from d
$_$;


ALTER FUNCTION "security"."course_link_pick_v1"("p_provider_id" "uuid", "p_urls" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_link_reactivated_v1"() RETURNS TABLE("course_id" "uuid", "link_id" "uuid", "url" "text", "route" "text", "basis" "jsonb", "link_updated_at" timestamp with time zone, "source_type" "text", "shown_url" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with human as (select s.id from pipeline.sources s where s.source_type in ('layer4_human_review', 'manual', 'manual_entry', 'admin_manual')),
  ev as (
    -- links a governed tranche set inactive (made_inactive) or contained (before[].link_id)
    select x::uuid link_id, e.id event_id, e.action, e.created_at
      from pipeline.admin_control_events e cross join lateral jsonb_array_elements_text(e.detail->'made_inactive') x
     where e.target = 'catalogue.course_links' and jsonb_typeof(e.detail->'made_inactive') = 'array'
    union all
    select (b->>'link_id')::uuid, e.id, e.action, e.created_at
      from pipeline.admin_control_events e cross join lateral jsonb_array_elements(e.detail->'before') b
     where e.action = 'e16_course_link_containment' and jsonb_typeof(e.detail->'before') = 'array' and b ? 'link_id'
  ),
  found as (
    select l.course_id, l.id link_id, l.url, case when ev.action = 'e16_course_link_containment' then 'held' else 'superseded' end route,
           jsonb_build_object('event', ev.event_id, 'action', ev.action, 'at', ev.created_at) basis, l.updated_at, l.source_id
      from ev join catalogue.course_links l on l.id = ev.link_id
     where l.status = 'active' and l.updated_at > ev.created_at and not exists (select 1 from human hu where hu.id = l.source_id)
    union all
    -- a page a Layer 4 decision or a page rejection set aside, active again from a background source after the decision
    select l.course_id, l.id, l.url, 'rejected', jsonb_build_object('layer4_item', i.id, 'decided_at', i.decided_at), l.updated_at, l.source_id
      from pipeline.layer4_review_items i
      join catalogue.course_links l on l.course_id = i.entity_id and l.link_type = 'official_course' and l.status = 'active'
     where i.entity_type = 'course' and i.field_code = 'official_course_url' and i.status = 'rejected' and i.decided_at is not null
       and security.course_link_norm_v1(l.url) = security.course_link_norm_v1(coalesce(i.proposed_value->>'course_url', i.proposed_value->>'url'))
       and l.updated_at > i.decided_at and not exists (select 1 from human hu where hu.id = l.source_id)
       and not exists (select 1 from pipeline.layer4_review_items a
                        where a.entity_id = i.entity_id and a.field_code = 'official_course_url' and a.status in ('approved', 'edited_approved') and a.entity_type = 'course'
                          and security.course_link_norm_v1(coalesce(a.proposed_value->>'course_url', a.proposed_value->>'url')) = security.course_link_norm_v1(l.url)
                          and coalesce(a.decided_at, a.created_at) > i.decided_at)
    union all
    select l.course_id, l.id, l.url, 'rejected', jsonb_build_object('page_rejection', r.source, 'rejected_at', r.rejected_at), l.updated_at, l.source_id
      from pipeline.page_rejections r
      join catalogue.course_links l on l.course_id = r.course_id and l.link_type = 'official_course' and l.status = 'active'
     where security.course_link_norm_v1(l.url) = security.course_link_norm_v1(r.url) and l.updated_at > r.rejected_at
       and not exists (select 1 from human hu where hu.id = l.source_id)
    union all
    select l.course_id, l.id, l.url, 'held', jsonb_build_object('remediation_hold', h.id, 'held_at', h.held_at), l.updated_at, l.source_id
      from pipeline.course_remediation_holds h
      join catalogue.course_links l on l.course_id = h.course_id and l.link_type = 'official_course' and l.status = 'active'
     where h.lifted_at is null and security.course_link_norm_v1(l.url) = security.course_link_norm_v1(h.url) and l.updated_at > h.held_at
  )
  select distinct on (f.link_id) f.course_id, f.link_id, f.url, f.route, f.basis, f.updated_at, s.source_type, d.official_course_url
    from found f left join pipeline.sources s on s.id = f.source_id left join search.course_documents d on d.course_id = f.course_id
   order by f.link_id, f.route
   limit security.pipeline_num_v1('course_link.reactivated_list_max', 2000)::int
$$;


ALTER FUNCTION "security"."course_link_reactivated_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_link_reactivated_v1"() IS 'IQ-00043 (Platform Admin 3 Nov 2026 08:44 §5): read-only reconciliation listing. Active official links whose address a governed tranche set inactive or contained (admin_control_events made_inactive, E16 before[]), a Layer 4 decision rejected, a page rejection refused, or an open remediation hold holds, and that a background (non-person) source made active after that decision. With the shown link (search.course_documents). At most course_link.reactivated_list_max rows.';



CREATE OR REPLACE FUNCTION "security"."course_link_reactivation_guard_trg_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_basis jsonb; v_new boolean; v_iq jsonb;
begin
  if new.status is distinct from 'active' then return new; end if;
  if TG_OP = 'UPDATE' and old.status = 'active' and old.url = new.url then return new; end if;
  -- a person decides: the course record, the link editor and paste files set cf.manual_edit; a Layer 4 reviewer is signed in
  if coalesce(current_setting('cf.manual_edit', true), '') = 'on' or auth.uid() is not null then return new; end if;
  if security.pipeline_num_v1('course_link.reactivation_guard', 1) < 1 then return new; end if;
  v_basis := security.course_link_hold_basis_v1(new.course_id, new.link_type, new.url, new.source_id);
  if v_basis is null then return new; end if;
  -- the attempt is evidence; the link stays as it was
  begin
    insert into pipeline.course_link_rediscoveries as d(course_id, link_id, link_type, url, url_norm, route, basis, attempted, writer, source_id, evidence_id)
    values (new.course_id,
            case when TG_OP = 'UPDATE' then old.id
                 else (select l.id from catalogue.course_links l where l.course_id = new.course_id and l.link_type = new.link_type and l.url = new.url) end,
            new.link_type, new.url, security.course_link_norm_v1(new.url), v_basis->>'route', v_basis,
            lower(TG_OP), left(coalesce(nullif(current_setting('application_name', true), ''), current_user::text), 120), new.source_id, new.evidence_id)
    on conflict (course_id, link_type, url, route) do update
      set last_seen_at = now(), seen_count = d.seen_count + 1, basis = excluded.basis, attempted = excluded.attempted, writer = excluded.writer,
          source_id = excluded.source_id, evidence_id = excluded.evidence_id, link_id = coalesce(excluded.link_id, d.link_id)
    returning (d.xmax = 0) into v_new;
    if v_new and to_regprocedure('security.integration_issue_upsert_v1(jsonb,text)') is not null then
      begin
        execute 'select security.integration_issue_upsert_v1($1, $2)' into v_iq
          using jsonb_build_object('fingerprint', 'course-link:reactivation-held',
                  'title', 'A background writer tried to make a replaced, rejected or held course link active again (held)',
                  'layer', 'Catalogue', 'subsystem', 'course-links', 'workstream', 'A4', 'severity', 'P2', 'root_cause_class', 'code_defect',
                  'validation_layer', 'V4', 'source', 'trigger reactivation_guard',
                  'failure', 'A background writer tried to re-activate ' || new.url || ' (' || (v_basis->>'route') || '); the link was left as it was',
                  'expected', 'Background readers record a rediscovered page as evidence only; a person decides whether a replaced, rejected or held page comes back',
                  'course_ids', jsonb_build_array(new.course_id),
                  'evidence', jsonb_build_object('basis', v_basis, 'url', new.url, 'writer', current_setting('application_name', true), 'table', 'pipeline.course_link_rediscoveries')),
                'reactivation-guard';
      exception when others then null;  -- fixed: the queue never stops a writer; the rediscovery row is the record
      end;
    end if;
  exception when others then null;  -- fixed: the evidence row never stops a writer; the link is still held below
  end;
  if TG_OP = 'UPDATE' then return old; end if;
  return null;
end $_$;


ALTER FUNCTION "security"."course_link_reactivation_guard_trg_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_link_reactivation_guard_trg_v1"() IS 'IQ-00043 (Platform Admin 3 Nov 2026 08:44 §5): trigger reactivation_guard on catalogue.course_links. A background writer never makes a superseded, retired, rejected or held address active (security.course_link_hold_basis_v1): an update keeps the old row, an insert is not made, and the attempt is recorded in pipeline.course_link_rediscoveries. A person (cf.manual_edit on, or signed in) decides. Switch: course_link.reactivation_guard.';



CREATE OR REPLACE FUNCTION "security"."course_link_reconcile_v1"("p_provider" "uuid", "p_limit" integer, "p_apply" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v jsonb; v2 jsonb; v_seen int := 0; v_sup int := 0; v_link int := 0; v_by jsonb := '{}'::jsonb; v_grp jsonb := '{}'::jsonb;
        v_rules jsonb := '{}'::jsonb; v_conv jsonb; v_d179 int := 0; v_skip int := 0; v_lock int; v_cls text;
begin
  if auth.uid() is not null and coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if p_provider is null then raise exception 'one university at a time: give its provider id' using errcode = '22023'; end if;
  for r in select i.id from pipeline.layer4_review_items i join catalogue.courses c on c.id = i.entity_id
            where i.status = 'pending' and i.field_code = 'official_course_url' and i.entity_type = 'course' and c.provider_id = p_provider
            order by i.created_at, i.id
            limit least(greatest(coalesce(p_limit, 0), 0), security.pipeline_num_v1('layer4.course_link_reconcile_batch', 500)::int) loop
    v_seen := v_seen + 1;
    v := security.course_link_route_class_v1(r.id);
    v_cls := v->>'class';
    v_by := jsonb_set(v_by, array[v_cls], to_jsonb(coalesce((v_by->>v_cls)::int, 0) + 1));
    v_grp := jsonb_set(v_grp, array[coalesce(v->>'group', '-')], to_jsonb(coalesce((v_grp->>coalesce(v->>'group', '-'))::int, 0) + 1));
    if v->>'action' = 'convert_d179' then v_d179 := v_d179 + 1; end if;
    if v->>'action' = 'rule_d263' then v_rules := jsonb_set(v_rules, array[v->>'rule'], to_jsonb(coalesce((v_rules->>(v->>'rule'))::int, 0) + 1)); end if;
    continue when not coalesce(p_apply, false) or v->>'action' not in ('supersede', 'link_evidence');
    -- the item, locked; one another reviewer holds is skipped, never waited for; then classified again
    begin
      v_lock := null;
      select 1 into v_lock from pipeline.layer4_review_items i where i.id = r.id and i.status = 'pending' and i.claimed_at is null and i.assigned_to is null for update nowait;
    exception when lock_not_available then v_lock := null;
    end;
    if v_lock is null then v_skip := v_skip + 1; continue; end if;
    v2 := security.course_link_route_class_v1(r.id);
    if v2->>'class' is distinct from v_cls then v_skip := v_skip + 1; continue; end if;
    if v2->>'action' = 'supersede' then
      update pipeline.layer4_review_items set status = 'superseded', decided_at = now(),
             change_control_ref = coalesce(change_control_ref || '; ', '') || 'CF-247 Course Link reconciliation (mandate 4 Nov 2026 16:32 §3): superseded (' || v_cls || ')'
       where id = r.id and status = 'pending';
      insert into pipeline.layer4_supersessions(item_id, field_code, entity_type, entity_id, reason, covered_by_item, evidence, mode)
      select i.id, i.field_code, i.entity_type, i.entity_id, v_cls, nullif(v2->'evidence'->>'covered_by_item', '')::uuid,
             (v2->'evidence') || jsonb_build_object('route', 'course_link_reconcile_v1', 'authority', v2->>'authority'), 'reconcile'
        from pipeline.layer4_review_items i where i.id = r.id;
      update pipeline.layer4_item_readiness set item_status = 'superseded', readiness = 'closed', classified_at = now() where item_id = r.id;
      v_sup := v_sup + 1;
    elsif v2->>'action' = 'link_evidence' then
      update pipeline.layer4_review_items set evidence_id = nullif(v2->'evidence'->'stored_copy'->>'id', '')::uuid
       where id = r.id and status = 'pending' and evidence_id is null and nullif(v2->'evidence'->'stored_copy'->>'id', '') is not null;
      if found then v_link := v_link + 1; end if;
    end if;
  end loop;
  -- Decision 179: the existing conversion, with its own checks (claimed, held page when raised or now, refusal recorded) and its own audit
  if v_d179 > 0 then
    v_conv := security.course_page_needed_convert_v1(p_provider, least(greatest(coalesce(p_limit, 0), 0), security.pipeline_num_v1('layer4.course_link_reconcile_batch', 500)::int), coalesce(p_apply, false));
  end if;
  if coalesce(p_apply, false) then
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('layer4', 'course_link_reconcile', p_provider::text,
            jsonb_build_object('examined', v_seen, 'by_class', v_by, 'by_group', v_grp, 'superseded', v_sup, 'evidence_linked', v_link, 'skipped', v_skip,
                               'page_needed_converted', v_conv, 'rule_d263_ready', v_rules, 'authority', 'mandate 4 Nov 2026 16:32 §3; Decision 179; Decision 263 (count only)'), auth.uid());
  end if;
  return jsonb_build_object('apply', coalesce(p_apply, false), 'provider_id', p_provider, 'examined', v_seen, 'by_class', v_by, 'by_group', v_grp,
                            'superseded', v_sup, 'evidence_linked', v_link, 'skipped', v_skip, 'page_needed', jsonb_build_object('classified', v_d179, 'convert', v_conv),
                            'rule_d263_ready', v_rules,
                            'next', case when v_rules <> '{}'::jsonb then 'approved rule items: security.layer4_course_link_rule_execute_v1(rule, n, true)' end);
end $$;


ALTER FUNCTION "security"."course_link_reconcile_v1"("p_provider" "uuid", "p_limit" integer, "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_link_reverse_enqueue_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v int;
begin
  insert into pipeline.course_link_reverse(url, provider_id)
  select distinct regexp_replace(u.url, '#.*$', ''), u.provider_id
    from pipeline.coverage_provider_urls u join pipeline.course_link_recipes rc on rc.provider_id = u.provider_id and rc.active
   where exists (select 1 from jsonb_array_elements(rc.patterns) e where regexp_replace(u.url, '[?#].*$', '') ~ (e->>'re'))
     and not exists (select 1 from pipeline.coverage_course_pages p where p.provider_id = u.provider_id and p.status = 'bound' and p.url = u.url)
  on conflict (url) do nothing;
  get diagnostics v = row_count;
  return v;
end $_$;


ALTER FUNCTION "security"."course_link_reverse_enqueue_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_link_reverse_tick_v1"("p_batch" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; n_done int := 0; n_bound int := 0; n_sent int := 0;
begin
  -- 1. Store the CRICOS codes printed on each page read.
  for r in select x.url, h.status_code, h.content from pipeline.course_link_reverse x join net._http_response h on h.id = x.req_id where x.state = 'sent' loop
    n_done := n_done + 1;
    if r.status_code = 200 and r.content is not null then
      update pipeline.course_link_reverse set state = 'done', done_at = now(),
             codes = array(select distinct m[1] from regexp_matches(upper(r.content), '(?:^|[^0-9A-Z])([0-9]{6}[0-9A-Z])(?![0-9A-Z])', 'g') m)
       where url = r.url;
    else
      update pipeline.course_link_reverse set state = 'error', done_at = now() where url = r.url;
    end if;
  end loop;
  update pipeline.course_link_reverse set state = 'queued'
   where state = 'sent' and sent_at < now() - interval '20 minutes' and not exists (select 1 from net._http_response h where h.id = req_id);

  -- 2. For universities whose pages are all read: bind a course still being searched for when its code is on exactly
  --    one page, and that page shows no more than three of the university's codes.
  for r in with done_prov as (select provider_id from pipeline.course_link_reverse group by provider_id
                               having bool_and(state in ('done','error')) and bool_or(state = 'done')),
                pc as (select x.provider_id, x.url, co.id course_id, co.course_code
                         from pipeline.course_link_reverse x join done_prov using (provider_id)
                         join catalogue.courses co on co.provider_id = x.provider_id and co.lifecycle_status = 'active' and co.course_code = any(x.codes)
                        where x.state = 'done'),
                per_page as (select url, count(*) n from pc group by url),
                per_code as (select course_id, count(distinct url) n from pc group by course_id)
           select pc.provider_id, pc.url, pc.course_id from pc join per_page pp using (url) join per_code pk using (course_id)
             join pipeline.course_link_search s on s.course_id = pc.course_id and s.state in ('queued','none','error')
            where pp.n <= 3 and pk.n = 1 loop
    update pipeline.course_link_search set state = 'found', candidates = to_jsonb(array[r.url]), cand_idx = 1, bound_url = r.url, done_at = now()
     where course_id = r.course_id;
    perform security.course_link_bind_v1(r.course_id, r.provider_id, r.url, 'cricos_search');
    update pipeline.course_link_reverse set bound = bound + 1 where url = r.url;
    n_bound := n_bound + 1;
  end loop;

  -- 3. Read the next pages, universities in turn.
  for r in select x.url from pipeline.course_link_reverse x where x.state = 'queued'
            order by row_number() over (partition by x.provider_id order by x.url) limit greatest(1, least(coalesce(p_batch, 30), 60)) loop
    update pipeline.course_link_reverse set state = 'sent', sent_at = now(),
           req_id = net.http_get(r.url, headers := jsonb_build_object('user-agent', 'Mozilla/5.0 (compatible; StudySearchBot/1.0)'), timeout_milliseconds := 30000)
     where url = r.url;
    n_sent := n_sent + 1;
  end loop;
  return jsonb_build_object('read', n_done, 'bound', n_bound, 'sent', n_sent);
end $$;


ALTER FUNCTION "security"."course_link_reverse_tick_v1"("p_batch" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_link_route_class_v1"("p_item" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare i pipeline.layer4_review_items; c record; v_src text; v_rule_l2 text; v_url text; v_key text; v_nheld int; v_held text;
        v_act text[]; v_act_keys text[]; v_refused boolean; v_ref_reason text; v_lock boolean; v_bind record; v_res jsonb; v_older uuid;
        r pipeline.layer4_course_link_rules; w record; v_copy uuid; v_copy_row record; v_site text; v_psite text; v_alias boolean; v_ev jsonb;
        v_d179 text := 'Decision 179 (Platform Admin 3 Nov 2026 20:29; admin nz-enrichment-brief/2026-11-03-layer4-course-link-growth-review.md, decision 1) and decision pack 2150 item 3 (approved ready 4 Nov 07:05: one university at a time through security.course_page_needed_convert_v1, review pause per university)';
        v_close text := 'Platform Admin mandate 4 Nov 2026 16:32 §3 (close superseded and repeated items with a recorded reason; not an admission); reason as security.layer4_resolution_for_v1';
begin
  select * into i from pipeline.layer4_review_items x where x.id = p_item;
  if i.id is null or i.status <> 'pending' or i.field_code <> 'official_course_url' or i.entity_type <> 'course' then
    return jsonb_build_object('item', p_item, 'group', null, 'class', 'not_a_waiting_course_link');
  end if;
  select k.id, k.course_code, k.lifecycle_status, k.provider_id, p.lifecycle_status plife, p.stable_key, p.website, cy.iso_alpha2 country
    into c from catalogue.courses k left join catalogue.providers p on p.id = k.provider_id left join ref.countries cy on cy.id = p.country_id where k.id = i.entity_id;
  v_src := coalesce(i.layer2_state->>'source', '');
  v_rule_l2 := coalesce(i.layer2_state->>'rule', '');
  v_url := security.layer4_item_page_v1(i.field_code, i.proposed_value, i.layer2_state);
  v_key := security.layer4_url_key_v1(v_url);
  v_nheld := case when jsonb_typeof(i.before_value) = 'array' then jsonb_array_length(i.before_value) else 0 end;
  v_held := case when v_nheld > 0 then i.before_value->>0 end;
  select array_agg(l.url order by l.is_primary desc, l.url), array_agg(security.layer4_url_key_v1(l.url) order by l.is_primary desc, l.url) into v_act, v_act_keys
    from catalogue.course_links l where l.course_id = i.entity_id and l.link_type = 'official_course' and l.status = 'active';
  select true, x.reason into v_refused, v_ref_reason from pipeline.page_rejections x
   where x.course_id = i.entity_id and security.layer4_url_key_v1(x.url) = v_key order by x.rejected_at desc nulls last limit 1;
  v_refused := coalesce(v_refused, false);
  v_lock := exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = i.entity_id and l.field in ('official_url', 'course_url'));
  select g.url, g.basis, g.identity_basis into v_bind from pipeline.coverage_course_pages g where g.course_id = i.entity_id;
  v_copy := coalesce(i.evidence_id, security.layer4_stored_copy_v1(v_url));
  select e.id, e.captured_at, e.metadata->>'identity_basis' basis, e.metadata->>'course_id' course into v_copy_row from pipeline.evidence_artifacts e where e.id = v_copy;
  v_site := security.course_link_site_v1(split_part(coalesce(v_key, ''), '/', 1));
  v_psite := security.course_link_site_v1(regexp_replace(regexp_replace(lower(coalesce(c.website, '')), '^https?://(www\.)?', ''), '/.*$', ''));
  v_alias := exists (select 1 from unnest(security.pipeline_list_v1('binding.provider_host_aliases', '[]'::jsonb)) a(v)
                      where split_part(a.v, '=', 1) = c.stable_key
                        and v_site = any (array(select security.course_link_site_v1(h) from unnest(string_to_array(split_part(a.v, '=', 2), ' ')) h)));
  v_ev := jsonb_build_object('source', v_src, 'rule', nullif(v_rule_l2, ''), 'proposed', v_url, 'held_when_raised', i.before_value, 'active_pages', to_jsonb(v_act),
            'proposed_refused', v_refused, 'refusal_reason', v_ref_reason, 'manual_lock', v_lock, 'binding', case when v_bind.url is null then null else
            jsonb_build_object('url', v_bind.url, 'basis', v_bind.basis, 'identity_basis', v_bind.identity_basis) end,
            'stored_copy', case when v_copy_row.id is null then null else jsonb_build_object('id', v_copy_row.id, 'captured_at', v_copy_row.captured_at,
            'identity_basis', v_copy_row.basis, 'read_for_this_course', v_copy_row.course = i.entity_id::text, 'linked', i.evidence_id is not null) end,
            'course_code', c.course_code, 'country', c.country, 'official_site', v_psite, 'proposed_site', v_site, 'raised_at', i.created_at);

  if i.claimed_at is not null or i.assigned_to is not null then
    return jsonb_build_object('item', i.id, 'group', 'C', 'class', 'claimed', 'action', 'keep', 'authority', null,
      'reason', 'A reviewer has claimed this item.', 'recommended', null, 'evidence', v_ev);
  end if;
  if exists (select 1 from pipeline.layer4_supersessions s where s.item_id = i.id and s.reversed_at is not null) then
    return jsonb_build_object('item', i.id, 'group', 'C', 'class', 'reopened_by_admin', 'action', 'keep', 'authority', null,
      'reason', 'The Platform Admin put this item back after the platform settled it, so a person decides it.', 'recommended', null, 'evidence', v_ev);
  end if;
  -- A: closes under the existing settlement reasons (never an approval or a refusal)
  if c.id is null or c.lifecycle_status is distinct from 'active' or c.plife is distinct from 'active' then
    return jsonb_build_object('item', i.id, 'group', 'A', 'class', 'entity_retired', 'action', 'supersede', 'authority', v_close,
      'reason', 'The course or its provider is no longer active, so its page is no longer asked for.', 'recommended', null,
      'evidence', v_ev || jsonb_build_object('course_status', coalesce(c.lifecycle_status, 'missing'), 'provider_status', coalesce(c.plife, 'missing')));
  end if;
  select o.id into v_older from pipeline.layer4_review_items o
   where o.entity_type = 'course' and o.entity_id = i.entity_id and o.field_code = 'official_course_url' and o.status = 'pending' and o.id <> i.id
     and (o.created_at, o.id) < (i.created_at, i.id) and security.layer4_url_key_v1(security.layer4_item_page_v1(o.field_code, o.proposed_value, o.layer2_state)) is not distinct from v_key
   order by o.created_at, o.id limit 1;
  if v_older is not null then
    return jsonb_build_object('item', i.id, 'group', 'A', 'class', 'duplicate_pending', 'action', 'supersede', 'authority', v_close,
      'reason', 'An earlier waiting item asks the same question about the same page.', 'recommended', null, 'evidence', v_ev || jsonb_build_object('covered_by_item', v_older));
  end if;
  v_res := security.layer4_resolution_for_v1(i.id, i.entity_type, i.entity_id, i.field_code, i.proposed_value, i.layer2_state, i.evidence_id, i.created_at);
  if v_res->>'reason' = 'decided_before' then
    return jsonb_build_object('item', i.id, 'group', 'A', 'class', 'decided_before', 'action', 'supersede', 'authority', v_close,
      'reason', 'The same page was decided for this course before, and this item brings no new evidence.', 'recommended', null,
      'evidence', v_ev || jsonb_build_object('covered_by_item', v_res->'covered_by_item', 'earlier', v_res->'evidence'));
  end if;
  if v_lock or v_bind.basis = 'manual' then
    return jsonb_build_object('item', i.id, 'group', 'C', 'class', 'manual_binding', 'action', 'keep', 'authority', null,
      'reason', 'The course''s page was set by hand. The platform never changes it.', 'recommended', 'Keep the page we hold. Change it only on the course record.', 'evidence', v_ev);
  end if;
  if v_src = 'binding check' and v_nheld = 0 then
    if coalesce(cardinality(v_act), 0) = 0 and v_refused then
      return jsonb_build_object('item', i.id, 'group', 'A', 'class', 'page_needed_d179', 'action', 'convert_d179', 'authority', v_d179,
        'reason', 'The page found was refused by the binding check and the course has no page. The course goes to Course page needed; the refusal stays recorded.',
        'recommended', null, 'evidence', v_ev);
    elsif coalesce(cardinality(v_act), 0) > 0 and v_refused and not (v_key = any (v_act_keys)) then
      return jsonb_build_object('item', i.id, 'group', 'C', 'class', 'refused_page_course_has_page', 'action', 'keep', 'authority', null,
        'reason', 'The page found was refused by the binding check; the course has since got another page.',
        'recommended', 'Refuse this proposal (the course keeps its current page).', 'evidence', v_ev);
    elsif not v_refused then
      return jsonb_build_object('item', i.id, 'group', 'B', 'class', 'refusal_not_recorded', 'action', 'record_refusal', 'authority', null,
        'reason', 'The binding check raised this item but its refusal is not recorded.', 'recommended', null, 'evidence', v_ev);
    end if;
  end if;
  if v_key = any (coalesce(v_act_keys, '{}')) and not v_refused and v_rule_l2 not in ('address_year', 'e16_unclear')
     and v_src not in ('housekeeping H13', 'e16 unclear') then
    return jsonb_build_object('item', i.id, 'group', 'A', 'class', 'covered_by_active', 'action', 'supersede', 'authority', v_close,
      'reason', 'The proposed page is already the course''s page.', 'recommended', null, 'evidence', v_ev);
  end if;
  -- an approved Decision 263 rule university: only its validator decides
  select * into r from pipeline.layer4_course_link_rules x where x.provider_id = c.provider_id and i.escalation_reason ilike x.reason_like order by x.code limit 1;
  if r.code is not null then
    select x.pass, x.reasons into w from security.layer4_course_link_rule_validate_v1(r.code, i.id) x;
    if coalesce(w.pass, false) then
      return jsonb_build_object('item', i.id, 'group', 'A', 'class', 'rule_d263_pass', 'action', 'rule_d263', 'rule', r.code, 'authority', r.approval_ref,
        'reason', 'The approved rule for this university covers this item and every check passes.', 'recommended', case r.choice when 'keep' then 'Keep the page we hold' else 'Use the new page' end,
        'evidence', v_ev);
    end if;
    return jsonb_build_object('item', i.id, 'group', 'C', 'class', 'rule_d263_fail', 'action', 'keep', 'rule', r.code, 'authority', null,
      'reason', 'This university has an approved rule, but this item does not pass it: ' || coalesce(array_to_string(w.reasons, '; '), 'not in the rule''s scope') || '.',
      'recommended', 'Decide by hand: ' || case r.choice when 'keep' then 'keep the page we hold if it is this course''s own page' else 'use the new page if it is this course''s own page' end || '.',
      'evidence', v_ev || jsonb_build_object('rule_reasons', to_jsonb(w.reasons)));
  end if;
  -- B: technical, before a person is asked
  if i.evidence_id is null then
    if v_copy is not null then
      return jsonb_build_object('item', i.id, 'group', 'B', 'class', 'evidence_not_linked', 'action', 'link_evidence', 'authority', 'layer4.evidence_link_on (records only; mandate 3 Nov 20:47 §5)',
        'reason', 'A stored copy of the proposed page exists but is not linked to the card.', 'recommended', null, 'evidence', v_ev);
    end if;
    return jsonb_build_object('item', i.id, 'group', 'B', 'class', 'evidence_missing', 'action', 'read_page', 'authority', null,
      'reason', 'No stored copy of the proposed page is held, so the card cannot show the page.', 'recommended', null, 'evidence', v_ev);
  end if;
  -- C: a person decides
  if v_refused and v_key = any (coalesce(v_act_keys, '{}')) then
    return jsonb_build_object('item', i.id, 'group', 'C', 'class', 'active_page_refused', 'action', 'keep', 'authority', null,
      'reason', 'The binding check refused the page this course shows: ' || coalesce(v_ref_reason, 'not proved to be this course''s page') || '.',
      'recommended', 'Check the page. If it is not this course''s own page, Enter the correct page; otherwise keep it.', 'evidence', v_ev);
  end if;
  if v_site is not null and v_psite is not null and v_site <> v_psite and not v_alias then
    return jsonb_build_object('item', i.id, 'group', 'C', 'class', 'off_domain', 'action', 'keep', 'authority', null,
      'reason', 'The proposed page is on ' || v_site || ', not on the provider''s site ' || v_psite || '.',
      'recommended', 'Keep the page we hold unless the provider confirms this site is its own.', 'evidence', v_ev);
  end if;
  if v_src = 'binding check' then
    return jsonb_build_object('item', i.id, 'group', 'C', 'class', 'held_page_dispute', 'action', 'keep', 'authority', null,
      'reason', 'A new page was found but refused by the binding check: ' || coalesce(v_ref_reason, 'not proved to be this course''s page') || '. The course keeps its page.',
      'recommended', 'Keep the page we hold.', 'evidence', v_ev);
  elsif v_src = 'coverage sweep' then
    return jsonb_build_object('item', i.id, 'group', 'C', 'class', 'cricos_page_differs', 'action', 'keep', 'authority', null,
      'reason', 'The page that shows this course''s code is a different address from the page we hold.',
      'recommended', case when v_copy_row.basis in ('cricos_code', 'nzqa_code') and v_copy_row.course = i.entity_id::text and coalesce(v_bind.identity_basis, '') not in ('cricos_code', 'nzqa_code')
                          then 'Use the new page: its stored copy shows this course''s code and the page we hold was not bound by the code.'
                          else 'Keep the page we hold unless the new page is this course''s own page.' end, 'evidence', v_ev);
  elsif v_src = 'housekeeping H13' or v_rule_l2 = 'address_year' then
    return jsonb_build_object('item', i.id, 'group', 'C', 'class', 'old_year_address', 'action', 'keep', 'authority', null,
      'reason', 'The page we show has an old year in its address and may be an archived handbook.',
      'recommended', 'Keep it if it is still the current page; otherwise Enter the current page.', 'evidence', v_ev);
  elsif v_src = 'housekeeping H05' then
    return jsonb_build_object('item', i.id, 'group', 'C', 'class', 'record_names_other_page', 'action', 'keep', 'authority', null,
      'reason', 'The course record names a different page from the one we show.', 'recommended', 'Use the new page if it is this course''s own page; otherwise keep the page we hold.', 'evidence', v_ev);
  elsif v_src = 'e16 unclear' or v_rule_l2 = 'e16_unclear' then
    return jsonb_build_object('item', i.id, 'group', 'C', 'class', 'e16_unclear', 'action', 'keep', 'authority', null,
      'reason', 'The course holds two pages and this one does not name the award.', 'recommended', 'Keep the page that names this course''s award.', 'evidence', v_ev);
  end if;
  return jsonb_build_object('item', i.id, 'group', 'C', 'class', 'other', 'action', 'keep', 'authority', null,
    'reason', coalesce(i.escalation_reason, 'A person decides this page.'), 'recommended', null, 'evidence', v_ev);
end $_$;


ALTER FUNCTION "security"."course_link_route_class_v1"("p_item" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_link_search_cap_reason_v1"() RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_cap int := security.pipeline_num_v1('search.daily_picked_cap', 100)::int; v_n int;
        v_day timestamptz := date_trunc('day', now() at time zone 'UTC') at time zone 'UTC';  -- fixed: the UTC day the picker counts
begin
  -- SS-014 P2 (2 Nov 2026): the picker's own day count; null while there is room
  select count(*) into v_n from pipeline.course_link_search where sent_at >= v_day;
  if v_cap - v_n > 0 then return null; end if;
  -- over the cap the picker still takes a person's running Find course pages task: that is not a pause
  if security.pipeline_num_v1('search.person_task_bypass', 1) >= 1
     and exists (select 1 from security.course_link_search_eligible_v1() e where security.link_search_person_task_v1(e.provider_id, e.course_id)) then return null; end if;
  return format('Paused: daily cap. %s of %s courses picked today (setting search.daily_picked_cap, counted per UTC day); picking resumes at %s', v_n, v_cap,
                to_char((v_day + interval '1 day') at time zone 'Australia/Melbourne', 'DD Mon HH24:MI'));  -- fixed: the next UTC day
end $$;


ALTER FUNCTION "security"."course_link_search_cap_reason_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_link_search_cap_reason_v1"() IS 'SS-014 P2 (2 Nov 2026): why course page search is paused by its configured day''s cap (search.daily_picked_cap), or null; the watchdog''s course_page_search cap_sql';



CREATE OR REPLACE FUNCTION "security"."course_link_search_eligible_v1"() RETURNS TABLE("course_id" "uuid", "provider_id" "uuid", "requested" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- SS-014 P2 (2 Nov 2026): the queued searches public.svc_course_link_search_next would pick, by its own conditions in its own order, without
  -- its per-call size, its Firecrawl budget checks (the watchdog shows those as the tool's state) and the day's picked-courses cap
  -- (security.course_link_search_cap_reason_v1).
  with prov as materialized (
    select q.provider_id,
           security.enrich_focus_v1(q.provider_id) focus,
           security.site_few_course_pages_v1(q.provider_id) few,
           security.site_not_checked_v1(q.provider_id) unchecked,
           exists (select 1 from pipeline.provider_onboarding o
                    where o.provider_id = q.provider_id and o.source in ('backfill', 'new_provider')
                      and not exists (select 1 from pipeline.firecrawl_search_resumes r where r.provider_id = q.provider_id and r.resumed_at > o.created_at)) bulk,
           (q.provider_id = any (array(select x.provider_id from security.fc_search_stopped_v1() x))) stopped
      from (select distinct s0.provider_id from pipeline.course_link_search s0 where s0.state = 'queued') q
      join pipeline.course_link_recipes rc on rc.provider_id = q.provider_id and rc.active
     where not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = q.provider_id)
       and (not coalesce((security.firecrawl_setting('target_only') #>> '{}')::boolean, true)
            or exists (select 1 from pipeline.firecrawl_target_cache tc where tc.provider_id = q.provider_id and tc.included))
       and not security.third_party_host_v1('https://' || rc.search_domain)
       and not exists (select 1 from catalogue.providers px, pipeline.platform_toolset_settings sk
                        where px.id = q.provider_id and sk.toolset_key = 'pipeline' and sk.key = 'search.skip_providers' and sk.value ? px.stable_key)),
  v as (select security.pipeline_num_v1('search.person_task_bypass', 1) >= 1 person)
  select s.course_id, s.provider_id, s.requested_at is not null
    from pipeline.course_link_search s join prov pv on pv.provider_id = s.provider_id
    join catalogue.courses c on c.id = s.course_id
    cross join v
   where s.state = 'queued'
     and security.search_stop_gate_v1(s.provider_id, s.course_id, pv.stopped) is null
     and (pv.focus or s.requested_at is not null)
     and case when s.requested_at is not null and (not pv.bulk or (v.person and security.link_search_person_task_v1(s.provider_id, s.course_id))) then true
              when pv.few or pv.unchecked then false
              else security.site_list_match_done_v1(s.course_id, s.provider_id) end
$$;


ALTER FUNCTION "security"."course_link_search_eligible_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_link_search_eligible_v1"() IS 'SS-014 P2 (2 Nov 2026): the queued course page searches the picker (svc_course_link_search_next) would pick, cap and budget aside; read by the watchdog''s course_page_search count';



CREATE OR REPLACE FUNCTION "security"."course_link_search_enqueue_v1"("p_provider_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v int;
begin
  insert into pipeline.course_link_search(course_id, provider_id)
  select c.id, c.provider_id
    from catalogue.courses c join pipeline.course_link_recipes r on r.provider_id = c.provider_id and r.active
    left join pipeline.coverage_course_pages p on p.course_id = c.id
   where c.lifecycle_status = 'active' and c.course_code ~ '^[0-9]{6}[0-9A-Z]$'
     and (p_provider_id is null or c.provider_id = p_provider_id)
     and (p.course_id is null or p.status = 'mismatch' or (p.status = 'ambiguous' and p.read_status is not null))
  on conflict (course_id) do nothing;
  get diagnostics v = row_count;
  return v;
end $_$;


ALTER FUNCTION "security"."course_link_search_enqueue_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_link_search_tick_v1"("p_batch" integer DEFAULT 40) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare r record; v_urls text[]; v_c text[]; v_cap numeric; v_on boolean; v_used numeric; v_key text; v_dom text;
        n_harvest int := 0; n_found int := 0; n_moved int := 0; n_sent int := 0; v_next text;
        -- 4 Nov 2026 (SS-021 F9, IQ-00134; wc.link_search_continuity_on): per-search isolation, re-send when due, a send cap
        v_wc_on boolean := security.pipeline_num_v1('wc.link_search_continuity_on', 1) >= 1; v_wc_max int := security.pipeline_num_v1('wc.link_search_max_attempts', 3)::int;
        v_wc jsonb; v_wc_state text; v_wc_msg text; n_failed int := 0; n_resent int := 0; n_capped int := 0;
begin
  select enabled, monthly_credit_cap into v_on, v_cap from pipeline.course_link_search_settings where id = 1;

  -- 1. Collect finished searches.
  for r in select s.*, h.status_code, h.content from pipeline.course_link_search s join net._http_response h on h.id = s.req_id
            where s.state = 'sent' loop
    n_harvest := n_harvest + 1;
    begin
    if r.status_code = 200 and left(r.content, 1) = '{' then
      perform public.svc_coverage_usage(2, 'course_link_search', r.provider_id, r.query);
      v_urls := array(select e->>'url' from jsonb_array_elements(coalesce((r.content::jsonb)->'data', '[]'::jsonb)) e);
      v_c := security.course_link_pick_v1(r.provider_id, v_urls);
      if cardinality(v_c) > 0 then
        update pipeline.course_link_search set state = 'found', results = to_jsonb(v_urls), candidates = to_jsonb(v_c), cand_idx = 1,
               bound_url = v_c[1], done_at = now() where course_id = r.course_id;
        perform security.course_link_bind_v1(r.course_id, r.provider_id, v_c[1], case r.stage when 'cricos' then 'cricos_search' else 'title_search' end);
        n_found := n_found + 1;
      elsif r.stage = 'cricos' then
        update pipeline.course_link_search set stage = 'title', state = 'queued', results = to_jsonb(v_urls), attempts = 0 where course_id = r.course_id;
      else
        update pipeline.course_link_search set state = 'none', results = to_jsonb(v_urls), done_at = now() where course_id = r.course_id;
      end if;
    else
      update pipeline.course_link_search set attempts = attempts + 1, state = case when attempts + 1 >= v_wc_max then 'error' else 'queued' end,
             results = jsonb_build_object('http_status', r.status_code, 'body', left(r.content, 300)) where course_id = r.course_id;
    end if;
    if v_wc_on and exists (select 1 from pipeline.work_items w where w.lane = 'course_link_search' and w.entity = r.course_id::text and w.work_kind = 'search' and w.stage <> 'done') then
      perform security.work_item_report_v1('course_link_search', r.course_id::text, 'search', 'succeeded', jsonb_build_object('provider_id', r.provider_id, 'outcome', 'succeeded_with_result'));
    end if;
    exception when others then
      -- one bad answer body or bind refusal sets back only this search (recorded with its class); off: the run stops as before
      if not v_wc_on then raise; end if;
      get stacked diagnostics v_wc_state = returned_sqlstate, v_wc_msg = message_text;
      perform security.work_item_report_v1('course_link_search', r.course_id::text, 'search', 'failed', jsonb_build_object('provider_id', r.provider_id,
                'owner', 'course-link-search', 'sqlstate', v_wc_state, 'message', v_wc_msg, 'evidence', jsonb_build_object('step', 'harvest', 'http_status', r.status_code)));
      update pipeline.course_link_search set attempts = attempts + 1, state = case when attempts + 1 >= v_wc_max then 'error' else 'queued' end,
             results = jsonb_build_object('error', left(v_wc_msg, 300), 'http_status', r.status_code) where course_id = r.course_id;
      if r.attempts + 1 >= v_wc_max then perform security.link_search_park_v1(r.course_id, r.attempts + 1); n_capped := n_capped + 1; end if;
      n_failed := n_failed + 1;
    end;
  end loop;
  if not v_wc_on then
  -- searches with no response after 20 minutes are sent again
  update pipeline.course_link_search set state = 'queued', attempts = attempts + 1
   where state = 'sent' and sent_at < now() - interval '20 minutes' and not exists (select 1 from net._http_response h where h.id = req_id);
  else
    -- 4 Nov 2026 (SS-021 F9): an unanswered search is recorded once per send (class search_unanswered), re-sent only when its work item is due
    -- again, and ends in error after wc.link_search_max_attempts sends
    for r in select s.course_id, s.provider_id, s.attempts, s.sent_at, w.last_attempt_at wla
               from pipeline.course_link_search s
               left join pipeline.work_items w on w.lane = 'course_link_search' and w.entity = s.course_id::text and w.work_kind = 'search'
              where s.state = 'sent' and s.sent_at < now() - make_interval(mins => security.pipeline_num_v1('wc.link_search_resend_minutes', 20)::int)
                and not exists (select 1 from net._http_response h where h.id = s.req_id)
              order by s.sent_at limit security.pipeline_num_v1('wc.tick_batch', 500)::int loop
      begin
        if r.wla is null or r.sent_at > r.wla then
          v_wc := security.work_item_report_v1('course_link_search', r.course_id::text, 'search', 'failed', jsonb_build_object('provider_id', r.provider_id,
                    'owner', 'course-link-search', 'class', 'search_unanswered', 'message', 'no search answer within the wait',
                    'evidence', jsonb_build_object('sent_at', r.sent_at, 'sends', r.attempts + 1)));
          update pipeline.course_link_search set attempts = attempts + 1,
                 state = case when r.attempts + 1 >= v_wc_max then 'error' when not coalesce((v_wc->>'recorded')::boolean, false) then 'queued' else state end,
                 results = case when r.attempts + 1 >= v_wc_max then jsonb_build_object('error', 'no search answer after ' || (r.attempts + 1) || ' send(s)') else results end
           where course_id = r.course_id and state = 'sent';
          if r.attempts + 1 >= v_wc_max then perform security.link_search_park_v1(r.course_id, r.attempts + 1); n_capped := n_capped + 1; end if;
        elsif security.work_item_eligible_v1('course_link_search', r.course_id::text, 'search') then
          update pipeline.course_link_search set state = 'queued' where course_id = r.course_id and state = 'sent';
          n_resent := n_resent + 1;
        end if;
      exception when others then n_failed := n_failed + 1;
      end;
    end loop;
  end if;

  -- 2. Pages the reader could not confirm move to the next candidate, then to the title search.
  for r in select s.*, p.status pstatus, p.read_status, p.read_attempts from pipeline.course_link_search s
             join pipeline.coverage_course_pages p on p.course_id = s.course_id and p.url = s.bound_url
            where s.state = 'found' and (p.status = 'mismatch' or (p.read_status in ('fetch_failed','blocked','robots_disallowed') and (p.read_attempts >= 2 or p.http_status in (404, 410)))) loop
    begin
    if r.cand_idx < jsonb_array_length(r.candidates) then
      v_next := r.candidates->>r.cand_idx;
      update pipeline.course_link_search set cand_idx = cand_idx + 1, bound_url = v_next where course_id = r.course_id;
      perform security.course_link_bind_v1(r.course_id, r.provider_id, v_next, case r.stage when 'cricos' then 'cricos_search' else 'title_search' end);
    elsif r.stage = 'cricos' then
      update pipeline.course_link_search set stage = 'title', state = 'queued', attempts = 0, done_at = null where course_id = r.course_id;
    else
      update pipeline.course_link_search set state = 'none', done_at = now() where course_id = r.course_id;
    end if;
    n_moved := n_moved + 1;
    exception when others then
      if not v_wc_on then raise; end if;
      get stacked diagnostics v_wc_state = returned_sqlstate, v_wc_msg = message_text;
      perform security.work_item_report_v1('course_link_search', r.course_id::text, 'search', 'failed', jsonb_build_object('provider_id', r.provider_id,
                'owner', 'course-link-search', 'sqlstate', v_wc_state, 'message', v_wc_msg, 'evidence', jsonb_build_object('step', 'move_on', 'bound_url', r.bound_url)));
      n_failed := n_failed + 1;
    end;
  end loop;
  update pipeline.course_link_search s set state = 'verified' from pipeline.coverage_course_pages p
   where s.state = 'found' and p.course_id = s.course_id and p.url = s.bound_url and p.status = 'bound' and p.identity_basis is not null;

  -- 2b. Decision 217: courses without a CRICOS code whose earlier page was read again and is not theirs are searched by title.
  insert into pipeline.course_link_search(course_id, provider_id, stage, state, queued_at)
  select p.course_id, p.provider_id, 'title', 'queued', now()
    from pipeline.coverage_course_pages p join catalogue.courses c on c.id = p.course_id and c.lifecycle_status = 'active'
   where p.status = 'mismatch' and p.basis not in ('cricos_search', 'title_search')
     and coalesce(c.course_code, '') !~ '^[0-9]{6}[0-9A-Z]$'
     and exists (select 1 from pipeline.course_link_recipes rc where rc.provider_id = p.provider_id and rc.active)
     and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.provider_id)  -- v2.15.237: paused while the provider is unpublished or archived
     and not exists (select 1 from pipeline.course_link_search s where s.course_id = p.course_id)
     and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = p.course_id and k.field = 'official_url')
   limit 200
  on conflict (course_id) do nothing;

  -- 2c. Decision 252: pages from the Serper search pass, after the reader.
  perform security.search_pass_advance_v1();

  -- 3. Send the next batch, inside the monthly credit cap.
  select coalesce(sum(units), 0) into v_used from pipeline.coverage_vendor_usage where purpose = 'course_link_search' and at >= date_trunc('month', now());
  if v_on and coalesce((select x.send_via from pipeline.course_link_search_settings x where x.id = 1), 'pg_net') = 'pg_net' and v_used + 2 * p_batch <= v_cap then
    v_key := public.svc_coverage_firecrawl()->>'secret';
    if v_key is not null then
      for r in select s.course_id, s.provider_id, s.stage, c.course_code, c.canonical_title, rc.search_domain
                 from pipeline.course_link_search s join catalogue.courses c on c.id = s.course_id
                 join pipeline.course_link_recipes rc on rc.provider_id = s.provider_id and rc.active
                 left join pipeline.provider_priority pp on pp.provider_id = s.provider_id
                where s.state = 'queued' and not security.course_held_v1(s.course_id)
                  and (not v_wc_on or security.work_item_eligible_v1('course_link_search', s.course_id::text, 'search')) and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = s.provider_id)  -- v2.15.237: paused while the provider is unpublished or archived
                order by (s.requested_at is null), (s.stage <> 'cricos'), row_number() over (partition by s.provider_id order by md5(s.course_id::text)), coalesce(pp.rank, 100000)
                limit greatest(1, least(coalesce(p_batch, 40), 100)) loop
        v_dom := case r.stage when 'cricos' then '"' || r.course_code || '" site:' || r.search_domain
                                         else '"' || replace(regexp_replace(r.canonical_title, '\s*\(\s*Level\s+\d{1,2}\s*\)\s*$', '', 'i'), '"', '') || '" site:' || r.search_domain end;
        update pipeline.course_link_search set state = 'sent', sent_at = now(), query = v_dom,
               req_id = net.http_post(url := 'https://api.firecrawl.dev/v1/search',
                          headers := jsonb_build_object('Authorization', 'Bearer ' || v_key, 'Content-Type', 'application/json'),
                          body := jsonb_build_object('query', v_dom, 'limit', 5), timeout_milliseconds := 60000)
         where course_id = r.course_id;
        n_sent := n_sent + 1;
      end loop;
    end if;
  end if;
  return jsonb_build_object('collected', n_harvest, 'found', n_found, 'moved_on', n_moved, 'sent', n_sent, 'credits_this_month', v_used, 'cap', v_cap,
                            'failed', n_failed, 'resent', n_resent, 'capped', n_capped);
end $_$;


