    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from pipeline.provider_course_lists l where l.provider_id = p_provider and l.status = 'read' and l.links_found > 0)
$$;


ALTER FUNCTION "security"."course_list_read_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_list_read_v1"("p_provider" "uuid") IS 'CF-247 22 Oct 2026: the provider has a course list page that was read with links.';



CREATE OR REPLACE FUNCTION "security"."course_list_with_extras_v1"("p_page" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    AS $$
  select case when jsonb_typeof(p_page -> 'items') is distinct from 'array' then p_page else
    p_page || jsonb_build_object('items', coalesce((
      select jsonb_agg(it.v || coalesce(x.extras, '{}'::jsonb) || coalesce(dsc.v, '{}'::jsonb) order by it.o)
        from jsonb_array_elements(p_page -> 'items') with ordinality it(v, o)
        left join security.course_list_extras_v1(array(select nullif(coalesce(j ->> 'id', j ->> 'course_id'), '')::uuid from jsonb_array_elements(p_page -> 'items') j)) x
          on x.course_id = nullif(coalesce(it.v ->> 'id', it.v ->> 'course_id'), '')::uuid
        -- 12 Nov 2026 (Platform Admin, Course catalogue): the description itself (shown as wrapped text) and when the description reader last wrote it
        left join lateral (select jsonb_build_object('description_text', c.description,
                                  'description_updated_at', (select e.updated_at from pipeline.field_enrich_items e where e.course_id = c.id and e.field = 'description' and e.state = 'filled'
                                                               and btrim(e.value ->> 'text') = btrim(c.description) order by e.updated_at desc limit 1)) v
                             from catalogue.courses c where c.id = nullif(coalesce(it.v ->> 'id', it.v ->> 'course_id'), '')::uuid) dsc on true), '[]'::jsonb),
      'columns_profile', 'course_columns_v1') end
$$;


ALTER FUNCTION "security"."course_list_with_extras_v1"("p_page" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_list_with_extras_v1"("p_page" "jsonb") IS 'CF-247 Course Catalogue columns (mandate 5 Nov 2026 17:31): merges security.course_list_extras_v1 into each item of a courses_page result, keeping the items'' order and every existing field.';



CREATE OR REPLACE FUNCTION "security"."course_page_check_v1"("p_course" "uuid", "p_url" "text", "p_title" "text" DEFAULT NULL::"text", "p_identity" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  with s as (
    select coalesce(security.toolset_setting('pipeline', 'binding.level_patterns'), '[]'::jsonb) lv,
           coalesce(security.toolset_setting('pipeline', 'binding.variant_markers'), '[]'::jsonb) vm,
           coalesce(security.toolset_setting('pipeline', 'binding.name_stop_words'), '[]'::jsonb) sw,
           coalesce(security.toolset_setting('pipeline', 'binding.shared_page_patterns'), '[]'::jsonb) sp,
           coalesce(security.toolset_setting('pipeline', 'binding.domestic_page_patterns'), '[]'::jsonb) dp,
           coalesce(security.toolset_setting('pipeline', 'binding.international_page_patterns'), '[]'::jsonb) ip,
           coalesce(security.toolset_setting('pipeline', 'binding.identity_exceptions'), '[]'::jsonb) ex,
           coalesce(security.toolset_setting('pipeline', 'binding.award_page_evidence'), '[]'::jsonb) ae,
           coalesce(security.toolset_setting('pipeline', 'binding.provider_host_aliases'), '[]'::jsonb) ha,
           security.pipeline_num_v1('binding.name_min_tokens', 2) min_tok,
           security.pipeline_num_v1('binding.name_stem_chars', 5)::int stem,
           security.pipeline_num_v1('binding.shared_page_min_other_courses', 2) min_other,
           security.pipeline_num_v1('binding.handbook_max_age_years', 2) max_age,
           security.pipeline_num_v1('binding.sibling_tail_abbrev_max_chars', 4)::int abbrev_max),
  c as (
    select co.id, co.provider_id, pr.stable_key pkey, co.canonical_title ctitle, security.course_title_key(co.canonical_title) tk,
           lower(co.canonical_title) || ' ' || coalesce(replace(sl.code, '_', ' '), '') ltext, co.course_url,
           co.open_to_international, co.open_to_domestic,
           regexp_replace(lower(coalesce(substring(pr.website from '^https?://([^/?#:]+)'), '')), '^www\.', '') phost
      from catalogue.courses co join catalogue.providers pr on pr.id = co.provider_id left join ref.study_levels sl on sl.id = co.study_level_id
     where co.id = p_course),
  u as (
    select lower(coalesce(p_url, '')) url,
           lower(coalesce(substring(p_url from '^https?://[^/?#]+(/[^?#]*)'), '/')) path,
           regexp_replace(lower(coalesce(substring(p_url from '^https?://([^/?#:]+)'), '')), '^www\.', '') host,
           lower(coalesce(substring(p_url from '#(.*)$'), '')) frag,
           lower(coalesce(nullif(btrim(p_title), ''),
             (select coalesce(nullif(g.candidates->>'page_title', ''), g.candidates->>'h1') from pipeline.coverage_course_pages g join c on g.provider_id = c.provider_id
               where (g.url = p_url or g.candidates->>'final_url' = p_url
                      -- 12 Nov 2026 (F-INT, E16): the same page with or without its trailing slash, or the same path on another of the provider's own hosts
                      or g.url = any ((select security.course_page_url_variants_v1(co.provider_id, p_url) from catalogue.courses co where co.id = p_course)::text[]))
                      and g.read_status = 'read'
                 and coalesce(nullif(g.candidates->>'page_title', ''), g.candidates->>'h1') is not null limit 1), '')) title),
  x as (
    select u.*,
           coalesce((select string_agg(seg, ' ' order by o) from (select seg, o from unnest(array_remove(string_to_array(u.path, '/'), '')) with ordinality q(seg, o) order by o desc limit 2) z), '') tail,
           coalesce((select seg from unnest(array_remove(string_to_array(u.path, '/'), '')) with ordinality q(seg, o) order by o desc limit 1), '') lastseg
      from u),
  t as (
    select x.*, c.*,
           btrim(regexp_replace(x.tail || ' ' || x.title, '[^a-z0-9]+', ' ', 'g')) tail_text,
           -- the award variant is judged on the page's own segment and title only, not on a section of the site (higher-degrees-by-research)
           btrim(regexp_replace(x.lastseg || ' ' || x.title, '[^a-z0-9]+', ' ', 'g')) var_text,
           regexp_split_to_array(x.path || ' ' || x.frag || ' ' || x.title, '[^a-z0-9]+') tokens,
           regexp_replace(x.lastseg, '[^a-z0-9]+', '-', 'g') slug
      from x, c),
  k as (
    select coalesce(array_agg(distinct lower(v)) filter (where v ~ '[A-Za-z]' and v ~ '[0-9]'), '{}') own
      from (select co.course_code v from catalogue.courses co where co.id = p_course
            union all select i.identifier from catalogue.course_identifiers i where i.course_id = p_course
            union all select o.vet_national_code from catalogue.course_regulatory_observations o where o.course_id = p_course and o.vet_national_code is not null) z),
  lv as (
    select array(select distinct split_part(e, '=', 1) from s, t, jsonb_array_elements_text(s.lv) e where t.ltext ~* substr(e, strpos(e, '=') + 1) order by 1) course_lv,
           array(select distinct split_part(e, '=', 1) from s, t, jsonb_array_elements_text(s.lv) e where (t.path || ' ' || t.title) ~* substr(e, strpos(e, '=') + 1) order by 1) page_lv),
  vm as (
    select array(select e from s, t, jsonb_array_elements_text(s.vm) e where t.var_text ~* e and not t.ltext ~* e) page_only,
           (select substring(t.var_text from '([0-9]{2,3}) ?(credit|point|pt)') from t) page_credit,
           (select substring(t.ltext from '([0-9]{2,3}) ?(credit|point|pt)') from t) course_credit),
  nm as (
    -- fixed: words of one or two letters carry no programme name
    select array(select distinct w from s, t, regexp_split_to_table(t.tail_text, '[^a-z]+') w where length(w) >= 3 and not s.sw ? w) page_tok,
           array(select distinct w from s, t, regexp_split_to_table(lower(t.ctitle), '[^a-z]+') w where length(w) >= 3 and not s.sw ? w) course_tok),
  yr as (
    select (select max(m[1]::int) from t, regexp_matches(t.path, '/((?:19|20)[0-9]{2})(?=/|$)', 'g') m) page_year,
           (select max(m[1]::int) from (select l.url from catalogue.course_links l where l.course_id = p_course and l.link_type = 'official_course' and l.status = 'active'
                                         union all select c.course_url from c
                                         union all select g.url from pipeline.coverage_course_pages g where g.course_id = p_course and g.status in ('bound', 'ambiguous')) z(url),
                   regexp_matches(lower(regexp_replace(coalesce(z.url, ''), '^https?://[^/?#]+', '')), '/((?:19|20)[0-9]{2})(?=/|$)', 'g') m) cur_year),
  sh as (
    select count(*) n_other, count(*) filter (where security.course_title_key(o.canonical_title) <> c.tk) n_diff
      from c join pipeline.coverage_course_pages g on g.provider_id = c.provider_id and g.course_id <> c.id and g.status in ('bound', 'ambiguous')
                                    and split_part(g.url, '#', 1) = split_part(p_url, '#', 1)  -- a section of a page is still that page
      join catalogue.courses o on o.id = g.course_id and o.lifecycle_status = 'active'),
  sib as (
    select (select o.canonical_title from t, catalogue.courses o
             where o.provider_id = t.provider_id and o.id <> t.id and o.lifecycle_status = 'active' and security.course_title_key(o.canonical_title) <> t.tk
               and replace(security.course_title_key(o.canonical_title), ' ', '-') = any (array(select left(t.slug, n) from generate_series(0, length(t.slug)) n))
               and t.slug like replace(security.course_title_key(o.canonical_title), ' ', '-') || '%'
               and length(security.course_title_key(o.canonical_title)) > case when t.slug like replace(t.tk, ' ', '-') || '%' then length(t.tk) else 0 end
               -- 16 Nov 2026 (finder false positives): not a sibling when the rest of the address names this course (a word of this course's
               -- title the sibling lacks, and no other word longer than binding.sibling_tail_abbrev_max_chars): double degrees, Dean's Scholar
               and not (exists (select 1 from regexp_split_to_table(substr(t.slug, length(replace(security.course_title_key(o.canonical_title), ' ', '-')) + 1), '[^a-z0-9]+') w
                                 where w <> '' and w = any (regexp_split_to_array(security.course_title_key(replace(t.ctitle, '''', '')), ' '))
                                   and not w = any (regexp_split_to_array(security.course_title_key(replace(o.canonical_title, '''', '')), ' ')))
                        and not exists (select 1 from regexp_split_to_table(substr(t.slug, length(replace(security.course_title_key(o.canonical_title), ' ', '-')) + 1), '[^a-z0-9]+') w
                                 where length(w) > (select s.abbrev_max from s)
                                   and not w = any (regexp_split_to_array(security.course_title_key(replace(t.ctitle, '''', '')), ' '))))
             order by length(o.canonical_title) desc limit 1) other_title),
  cp as (
    select (select k2.name from t, catalogue.campuses k2
             where k2.provider_id = t.provider_id and k2.status = 'active' and btrim(coalesce(k2.name, '')) <> ''
               and exists (select 1 from catalogue.course_campuses cc where cc.course_id = t.id)
               and not exists (select 1 from catalogue.course_campuses cc where cc.course_id = t.id and cc.campus_id = k2.id)
               and position(' ' || security.course_title_key(k2.name) || ' ' in ' ' || t.tail_text || ' ') > 0
               and position(security.course_title_key(k2.name) in t.tk) = 0
               -- 16 Nov 2026 (finder false positives): a campus named like the provider is the provider's own name in page titles, not another campus
               and not exists (select 1 from catalogue.providers p2, unnest(array[p2.canonical_name, p2.display_name, p2.short_name]) pn(nm)
                                where p2.id = t.provider_id and btrim(coalesce(pn.nm, '')) <> ''
                                  and position(' ' || security.course_title_key(k2.name) || ' ' in ' ' || security.course_title_key(pn.nm) || ' ') > 0)
               and not exists (select 1 from catalogue.course_campuses cc join catalogue.campuses k3 on k3.id = cc.campus_id
                                where cc.course_id = t.id and position(' ' || security.course_title_key(k3.name) || ' ' in ' ' || t.tail_text || ' ') > 0)
             limit 1) other_campus),
  ev as (
    select
      -- the provider's own hosts: its website, its approved other websites (binding.provider_host_aliases) and its extra course domains
      (t.host <> '' and not exists (select 1 from unnest(array[t.phost]
                                         || array(select regexp_split_to_table(lower(btrim(substr(e, strpos(e, '=') + 1))), '\s+') from s, jsonb_array_elements_text(s.ha) e
                                                   where split_part(e, '=', 1) = t.pkey)
                                         || array(select regexp_replace(lower(d.domain), '^(https?://)?(www\.)?', '') from pipeline.provider_extra_domains d where d.provider_id = t.provider_id)) h(b)
                                     where h.b <> '' and (t.host = h.b or t.host like '%.' || h.b))
       and exists (select 1 from catalogue.providers o, lateral (select regexp_replace(lower(coalesce(substring(o.website from '^https?://([^/?#:]+)'), '')), '^www\.', '') b) ob
                    where o.id <> t.provider_id and o.lifecycle_status = 'active' and ob.b <> '' and (t.host = ob.b or t.host like '%.' || ob.b))) other_provider,
      (t.open_to_international is true and t.open_to_domestic is not true and exists (select 1 from s, jsonb_array_elements_text(s.dp) e where t.url ~* e)) domestic_page,
      (t.open_to_domestic is true and t.open_to_international is false and exists (select 1 from s, jsonb_array_elements_text(s.ip) e where t.url ~* e)) international_page,
      (exists (select 1 from s, jsonb_array_elements_text(s.sp) e where t.path ~* e) or sh.n_other >= s.min_other) shared,
      (t.tokens && k.own) own_code,
      exists (select 1 from catalogue.course_identifiers i where i.provider_id = t.provider_id and i.course_id <> t.id and lower(i.identifier) = any (t.tokens)
                 and i.identifier ~ '[A-Za-z]' and i.identifier ~ '[0-9]' and not lower(i.identifier) = any (k.own)) other_code,
      -- the page names this course's own section or award (title, code or section), needed for an approved exception
      (t.tokens && k.own
       or position(' ' || t.tk || ' ' in ' ' || security.course_title_key(t.frag || ' ' || t.title) || ' ') > 0
       or (t.frag <> '' and security.course_title_key(t.frag) = t.tk)
       ) names_course,
      -- an exit or nested award on its parent course's page: programme-specific evidence only (binding.award_page_evidence), never a title match
      ((s.ae ? 'page_names_award'
        and (exists (select 1 from pipeline.coverage_course_pages g where g.provider_id = t.provider_id and g.url = p_url and g.course_id <> t.id
                       and position(' ' || t.tk || ' ' in ' ' || security.course_title_key(g.candidates->'adapter_extra'->>'exit_awards') || ' ') > 0)
             or exists (select 1 from pipeline.course_exit_awards a where a.child_course_id = t.id and a.page_url = p_url and a.active and a.link_type = 'exit_award'
                          and a.evidence_id is not null and position(' ' || t.tk || ' ' in ' ' || security.course_title_key(a.printed) || ' ') > 0)))
       or (s.ae ? 'recorded_by_hand'
           and exists (select 1 from pipeline.course_exit_awards a where a.child_course_id = t.id and a.page_url = p_url and a.active and a.set_by = 'hand' and a.evidence_id is not null))) award_evidence,
      (select array_agg(distinct split_part(e, '|', 2)) from s, jsonb_array_elements_text(s.ex) e
        where split_part(e, '|', 1) = t.provider_id::text and p_url ~* substr(e, length(split_part(e, '|', 1)) + length(split_part(e, '|', 2)) + 3)) exceptions,
      (cardinality(lv.page_lv) > 0 and cardinality(lv.course_lv) > 0 and not lv.page_lv && lv.course_lv) other_level,
      (cardinality(vm.page_only) > 0 or (vm.page_credit is not null and vm.course_credit is not null and vm.page_credit <> vm.course_credit)) other_variant,
      (cardinality(nm.page_tok) >= s.min_tok and cardinality(nm.course_tok) > 0
       and not exists (select 1 from unnest(nm.page_tok) a, unnest(nm.course_tok) b where left(a, s.stem) = left(b, s.stem))) other_name,
      (p_identity is not null
       or exists (select 1 from pipeline.coverage_course_pages g where g.course_id = t.id and (g.url = p_url or g.candidates->>'final_url' = p_url
                                                        or g.url = any ((select security.course_page_url_variants_v1(co.provider_id, p_url) from catalogue.courses co where co.id = p_course)::text[]))
                    and g.read_status = 'read' and g.identity_basis is not null)
       or (t.course_url = p_url and exists (select 1 from pipeline.manual_locks m where m.entity = 'course' and m.entity_id = t.id and m.field in ('official_url', 'course_url')))
       or exists (select 1 from catalogue.course_links l join pipeline.sources so on so.id = l.source_id
                   where l.course_id = t.id and l.url = p_url and l.link_type = 'official_course' and l.status = 'active' and so.source_type in ('layer4_human_review', 'manual_entry'))) proved,
      t.host, t.title, lv.course_lv, lv.page_lv, vm.page_only, vm.page_credit, vm.course_credit, yr.page_year, yr.cur_year, sh.n_other, sh.n_diff,
      sib.other_title, cp.other_campus, s.max_age
    from t, s, k, lv, vm, nm, yr, sh, sib, cp),
  v as (
    select ev.*,
      case
        when ev.host is null then array['refuse', 'no_course', 'the course is not in the catalogue']
        when ev.other_provider then array['refuse', 'provider', 'the page is on another provider''s website (' || ev.host || ')']
        when ev.page_year < ev.cur_year then array['refuse', 'older_year', 'the page is the ' || ev.page_year || ' handbook entry, and this course already has a ' || ev.cur_year || ' page']
        when ev.page_year < extract(year from now())::int - ev.max_age then array['refuse', 'old_year', 'the page is the ' || ev.page_year || ' handbook entry, older than the handbook years allowed']
        when ev.domestic_page then array['refuse', 'audience', 'the page is for domestic students, and this course is for international students']
        when ev.international_page then array['refuse', 'audience', 'the page is for international students, and this course is for domestic students']
        when ev.shared and ev.award_evidence then array['pass', 'award_on_parent_page', 'the page of the longer course, which names this award as available within it']
        when ev.shared and ev.names_course and 'shared_page' = any (coalesce(ev.exceptions, '{}')) then array['pass', 'exception_shared_page', 'an approved shared page that names this course''s own section']
        when ev.shared then array['refuse', 'shared_page', 'the page is shared by several courses, or is a fee, application or course list page, and nothing on it shows this course''s own section']
        when ev.own_code then array['pass', 'own_code', 'the page address or title shows this course''s own code']
        when ev.other_code then array['refuse', 'other_code', 'the page address or title shows another course''s code']
        when ev.other_level and ev.award_evidence then array['pass', 'award_on_parent_page', 'the page of the longer course, which names this award as available within it']
        when ev.other_level and ev.names_course and 'nested_award' = any (coalesce(ev.exceptions, '{}')) then array['pass', 'exception_nested_award', 'an approved page of the longer course that names this award']
        when ev.other_level then array['refuse', 'level', 'the page is for another qualification level (' || array_to_string(ev.page_lv, ', ') || '), not this course''s (' || array_to_string(ev.course_lv, ', ') || ')']
        when ev.other_variant then array['refuse', 'variant', 'the page is for another version of the award (' || coalesce(nullif(array_to_string(ev.page_only, ', '), ''), ev.page_credit || ' credit points') || ')']
        when ev.other_title is not null then array['refuse', 'sibling', 'the page address is another course''s at this provider (' || ev.other_title || ')']
        when ev.other_name then array['refuse', 'name', 'the page address and title do not name this programme']
        when ev.other_campus is not null then array['refuse', 'campus', 'the page is for another campus (' || ev.other_campus || ')']
        when ev.proved then array['pass', 'identity_proof', 'nothing on the page contradicts the course, and its identity is proved']
        else array['unproven', 'unproven', 'nothing on the page proves yet that it is this course''s own page']
      end r
    from ev right join (select 1) one on true)
  select jsonb_build_object('verdict', v.r[1], 'rule', v.r[2], 'reason', v.r[3], 'url', p_url,
           'checks', jsonb_strip_nulls(jsonb_build_object('course_levels', to_jsonb(v.course_lv), 'page_levels', to_jsonb(v.page_lv), 'variants', to_jsonb(v.page_only),
             'page_year', v.page_year, 'course_year', v.cur_year, 'other_courses_on_page', v.n_other, 'other_titles_on_page', v.n_diff,
             'other_course', v.other_title, 'other_campus', v.other_campus, 'exceptions', to_jsonb(v.exceptions), 'names_course', v.names_course,
             'own_code', v.own_code, 'award_evidence', v.award_evidence, 'proved', v.proved, 'title', nullif(v.title, ''))))
    from v
$_$;


ALTER FUNCTION "security"."course_page_check_v1"("p_course" "uuid", "p_url" "text", "p_title" "text", "p_identity" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_page_check_v1"("p_course" "uuid", "p_url" "text", "p_title" "text", "p_identity" "text") IS 'CF-247 E16-1 (Platform Admin 2 Nov 2026 07:21): is this page the course''s own page? verdict pass, refuse or unproven, with the rule and a plain reason. Used by the binding guard, the award-link lane, the AI reader''s page choice and the search projection. Settings binding.*.';



CREATE OR REPLACE FUNCTION "security"."course_page_key_v1"("p_course" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247: the state of the course's page that its proof depends on (a new read, binding or identity changes the key)
  select md5(concat_ws('|', g.status, g.read_status, g.identity_basis, g.evidence_id, g.url, g.candidates->>'final_url', g.candidates->>'page_title', g.candidates->>'h1'))
    from pipeline.coverage_course_pages g where g.course_id = p_course
$$;


ALTER FUNCTION "security"."course_page_key_v1"("p_course" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_page_needed_add_v1"("p_course" "uuid", "p_url" "text", "p_reason" "text", "p_lane" "text", "p_evidence" "uuid", "p_item" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_prov uuid;
begin
  select c.provider_id into v_prov from catalogue.courses c where c.id = p_course;
  if v_prov is null then return 'nothing'; end if;
  insert into pipeline.course_page_needed as n(course_id, provider_id, refused, last_refused_url, last_refused_reason, last_refused_lane, last_refused_evidence, last_refused_at, converted_items)
  values (p_course, v_prov, 1, p_url, p_reason, p_lane, p_evidence, now(), case when p_item is null then '{}'::uuid[] else array[p_item] end)
  on conflict (course_id) do update set refused = n.refused + 1, last_refused_url = excluded.last_refused_url, last_refused_reason = excluded.last_refused_reason,
     last_refused_lane = excluded.last_refused_lane, last_refused_evidence = coalesce(excluded.last_refused_evidence, n.last_refused_evidence), last_refused_at = now(),
     converted_items = case when p_item is null or p_item = any (n.converted_items) then n.converted_items else n.converted_items || p_item end,
     state = case when n.state = 'search_requested' then 'open' else n.state end, updated_at = now();
  return 'page_needed';
end $$;


ALTER FUNCTION "security"."course_page_needed_add_v1"("p_course" "uuid", "p_url" "text", "p_reason" "text", "p_lane" "text", "p_evidence" "uuid", "p_item" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_page_needed_convert_v1"("p_provider" "uuid", "p_limit" integer, "p_apply" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_seen int := 0; v_moved int := 0; v_skip jsonb := '{}'::jsonb; v_why text;
begin
  if auth.uid() is not null and coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if p_provider is null then raise exception 'one university at a time: give its provider id' using errcode = '22023'; end if;
  for r in select i.id, i.entity_id, i.before_value, i.layer2_state, i.claimed_at, i.assigned_to, i.evidence_id, i.escalation_reason,
                  security.layer4_item_page_v1(i.field_code, i.proposed_value, i.layer2_state) url
             from pipeline.layer4_review_items i join catalogue.courses c on c.id = i.entity_id
            where i.status = 'pending' and i.field_code = 'official_course_url' and i.entity_type = 'course' and c.provider_id = p_provider
              and i.layer2_state->>'source' = 'binding check'
            order by i.created_at, i.id limit least(greatest(coalesce(p_limit, 0), 0), security.pipeline_num_v1('layer4.page_needed_convert_batch', 500)::int) loop
    v_seen := v_seen + 1;
    v_why := case
      when r.claimed_at is not null or r.assigned_to is not null then 'claimed_by_reviewer'
      when jsonb_typeof(r.before_value) = 'array' and jsonb_array_length(r.before_value) > 0 then 'held_page_when_raised'
      when exists (select 1 from catalogue.course_links l where l.course_id = r.entity_id and l.link_type = 'official_course' and l.status = 'active') then 'held_page_now'
      when not exists (select 1 from pipeline.page_rejections x where x.course_id = r.entity_id and security.layer4_url_key_v1(x.url) = security.layer4_url_key_v1(r.url)) then 'refusal_not_recorded'
    end;
    if v_why is not null then v_skip := jsonb_set(v_skip, array[v_why], to_jsonb(coalesce((v_skip->>v_why)::int, 0) + 1)); continue; end if;
    if p_apply then
      update pipeline.layer4_review_items set status = 'superseded', decided_at = now(),
             change_control_ref = coalesce(change_control_ref || '; ', '') || 'Decision 179 (Platform Admin 3 Nov 2026 20:29): moved to Course page needed (refused page, no held page)'
       where id = r.id and status = 'pending';
      if not found then continue; end if;
      perform security.course_page_needed_add_v1(r.entity_id, r.url, r.escalation_reason, r.layer2_state->>'lane', r.evidence_id, r.id);
    end if;
    v_moved := v_moved + 1;
  end loop;
  if p_apply then
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('layer4', 'page_needed_convert', p_provider::text, jsonb_build_object('examined', v_seen, 'moved', v_moved, 'kept_in_layer4', v_skip), auth.uid());
  end if;
  return jsonb_build_object('apply', p_apply, 'provider_id', p_provider, 'examined', v_seen, 'moved', v_moved, 'kept_in_layer4', v_skip);
end $$;


ALTER FUNCTION "security"."course_page_needed_convert_v1"("p_provider" "uuid", "p_limit" integer, "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_page_needed_decide_v1"("p_course" "uuid", "p_choice" "text", "p_value" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare n pipeline.course_page_needed; v_r jsonb; v_url text := nullif(btrim(coalesce(p_value, '')), '');
begin
  select * into n from pipeline.course_page_needed where course_id = p_course for update;
  if n.course_id is null or n.state <> 'open' then raise exception 'this course is no longer on the Course page needed list' using errcode = 'P0002'; end if;
  if p_choice = 'add_page' then
    v_r := public.admin_course_edit(p_course, 'set_official_url', jsonb_build_object('url', v_url, 'reason', 'Course page needed: ' || p_reason));
    update pipeline.course_page_needed set state = 'page_added', decided_by = auth.uid(), decided_at = now(),
           decision = jsonb_build_object('choice', p_choice, 'url', v_url, 'reason', p_reason), updated_at = now() where course_id = p_course;
  elsif p_choice = 'search_again' then
    if n.searches_requested >= security.pipeline_num_v1('layer4.page_needed_search_max', 3) then
      raise exception 'another search was already asked for % times for this course: add the page or record that none exists', n.searches_requested;
    end if;
    insert into pipeline.course_link_search as s(course_id, provider_id, stage, state, attempts, requested_at)
    values (p_course, n.provider_id, 'cricos', 'queued', 0, now())
    on conflict (course_id) do update set stage = 'cricos', state = 'queued', attempts = 0, done_at = null, requested_at = now();
    update pipeline.course_page_needed set state = 'search_requested', searches_requested = searches_requested + 1, decided_by = auth.uid(), decided_at = now(),
           decision = jsonb_build_object('choice', p_choice, 'reason', p_reason), updated_at = now() where course_id = p_course;
    v_r := jsonb_build_object('requeued', true, 'searches_requested', n.searches_requested + 1);
  elsif p_choice = 'no_page' then
    if v_url is null or v_url !~* '^https://[^\s/]+\.[^\s]+$' then raise exception 'give the address (https://…) that shows the course has no page of its own'; end if;
    if length(btrim(coalesce(p_reason, ''))) < 10 then raise exception 'say what that page shows (kept as the evidence)'; end if;
    insert into pipeline.course_no_page as x(course_id, provider_id, kind, state, basis, decided_at, updated_at)
    values (p_course, n.provider_id, 'no_page', 'confirmed',
            jsonb_build_object('source', 'course_page_needed', 'evidence_url', v_url, 'evidence_copy', security.layer4_stored_copy_v1(v_url), 'reason', p_reason, 'by', auth.uid()), now(), now())
    on conflict (course_id) do update set kind = 'no_page', state = 'confirmed', basis = x.basis || excluded.basis, decided_at = now(), updated_at = now()
     where x.state in ('proposed', 'rejected', 'reopened');
    if not found then raise exception 'this course already has a no-page or conjoint record that a person decided; open the course instead'; end if;
    update pipeline.course_page_needed set state = 'no_page_exists', decided_by = auth.uid(), decided_at = now(),
           decision = jsonb_build_object('choice', p_choice, 'evidence_url', v_url, 'reason', p_reason), updated_at = now() where course_id = p_course;
    v_r := jsonb_build_object('no_page', 'confirmed', 'evidence_url', v_url);
  else
    raise exception 'choice % is not handled on the Course page needed list', p_choice;
  end if;
  return coalesce(v_r, '{}'::jsonb) || jsonb_build_object('course_id', p_course, 'state', (select state from pipeline.course_page_needed where course_id = p_course));
end $_$;


ALTER FUNCTION "security"."course_page_needed_decide_v1"("p_course" "uuid", "p_choice" "text", "p_value" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_page_needed_settle_v1"("p_limit" integer DEFAULT NULL::integer, "p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_max int := security.pipeline_num_v1('layer4.page_needed_convert_batch', 500)::int; v_lim int; v_no int := 0; v_added int := 0;
begin
  if auth.uid() is not null and coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  v_lim := least(greatest(coalesce(p_limit, v_max), 0), v_max);
  with c as (
    select n.course_id,
           case when exists (select 1 from catalogue.course_links l where l.course_id = n.course_id and l.link_type = 'official_course' and l.status = 'active') then 'page_added'
                when exists (select 1 from pipeline.course_no_page x where x.course_id = n.course_id and x.kind = 'no_page' and x.state in ('confirmed', 'confirmed_auto')) then 'no_page_exists'
           end to_state
      from pipeline.course_page_needed n
     where n.state = 'open'
     order by n.created_at, n.course_id),
  pick as (select * from c where to_state is not null limit v_lim),
  upd as (
    update pipeline.course_page_needed n
       set state = p.to_state, decided_by = null, decided_at = now(), updated_at = now(),
           decision = jsonb_build_object('choice', 'settled_by_rule', 'rule', 'cpn-settle-v1',
                                         'basis', case p.to_state when 'page_added' then 'the course holds an active official course link'
                                                                  else 'pipeline.course_no_page holds a confirmed absence' end)
      from pick p
     where p_apply and n.course_id = p.course_id and n.state = 'open'
    returning n.state)
  select coalesce((select count(*) filter (where to_state = 'no_page_exists') from pick), 0),
         coalesce((select count(*) filter (where to_state = 'page_added') from pick), 0)
    into v_no, v_added;
  if p_apply and v_no + v_added > 0 then
    insert into pipeline.admin_control_events (area, action, target, detail, actor)
    values ('layer4', 'course_page_needed_settle', 'pipeline.course_page_needed',
            jsonb_build_object('rule', 'cpn-settle-v1', 'no_page_exists', v_no, 'page_added', v_added, 'limit', v_lim), auth.uid());
  end if;
  return jsonb_build_object('rule', 'cpn-settle-v1', 'applied', p_apply, 'no_page_exists', v_no, 'page_added', v_added, 'limit', v_lim,
                            'open_after', (select count(*) from pipeline.course_page_needed where state = 'open'));
end;
$$;


ALTER FUNCTION "security"."course_page_needed_settle_v1"("p_limit" integer, "p_apply" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_page_needed_settle_v1"("p_limit" integer, "p_apply" boolean) IS 'CF-247 Layer 4 (Platform Admin 16 Nov 2026 20:14): settles open Course page needed entries whose outcome is on record (confirmed no-page record -> no_page_exists; active official link -> page_added). Deterministic, no search; p_apply false counts only; audited.';



CREATE OR REPLACE FUNCTION "security"."course_page_proven_v1"("p_course" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 (integrator, 3 Nov 2026 11:23 evidence): the course has a page the Enrich fields reader will read: the reader's own rule in
  -- security.enrich_fields_slice_v1 (bound, or ambiguous with an identity proof; read with an identity proof; not refused by
  -- security.course_page_check_v1 while binding.identity_check is on). Otherwise its items are skipped as "no proven course page (E16)".
  select exists (select 1 from pipeline.coverage_course_pages g join pipeline.evidence_artifacts e on e.id = g.evidence_id
                  where g.course_id = p_course and g.status in ('bound', 'ambiguous') and (g.status = 'bound' or g.identity_basis is not null)
                    and g.read_status = 'read' and g.identity_basis is not null and e.storage_path is not null
                    and (security.pipeline_num_v1('binding.identity_check', 1) < 1
                         or security.course_page_check_v1(p_course, coalesce(nullif(g.candidates->>'final_url', ''), g.url),
                                                          coalesce(nullif(g.candidates->>'page_title', ''), g.candidates->>'h1'), g.identity_basis)->>'verdict' <> 'refuse'))
$$;


ALTER FUNCTION "security"."course_page_proven_v1"("p_course" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_page_rebind_v1"("p_course_id" "uuid", "p_url" "text", "p_basis" "text", "p_reason" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_old text; v_pid uuid;
begin
  select provider_id into v_pid from catalogue.courses where id = p_course_id;
  if v_pid is null then return 'unknown course'; end if;
  if exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = p_course_id and l.field in ('official_url', 'course_url')) then return 'locked'; end if;
  if exists (select 1 from pipeline.course_page_blocks b where b.course_id = p_course_id and b.url = p_url) then return 'blocked'; end if;
  select url into v_old from pipeline.coverage_course_pages where course_id = p_course_id;
  insert into pipeline.coverage_course_pages(course_id, provider_id, url, basis, status, bound_at, next_read_at, read_attempts)
  values (p_course_id, v_pid, p_url, p_basis, 'bound', now(), now(), 0)
  on conflict (course_id) do update set url = excluded.url, basis = excluded.basis, status = 'bound', bound_at = now(),
         score = null, runner_up = null, read_status = null, read_at = null, http_status = null, fetched_via = null,
         identity_basis = null, evidence_id = null, candidates = null, leased_until = null, read_attempts = 0, next_read_at = now();
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('coverage', 'rebind', 'course: ' || p_course_id, jsonb_build_object('course_id', p_course_id, 'old_url', v_old, 'new_url', p_url, 'basis', p_basis, 'reason', p_reason), null);
  return case when v_old is not distinct from p_url then 'read again' else 'relinked' end;
end $$;


ALTER FUNCTION "security"."course_page_rebind_v1"("p_course_id" "uuid", "p_url" "text", "p_basis" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_page_rule_v1"("p_held" "text", "p_prop" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $_$
  -- Decision 263: which page wins when the coverage sweep proposes a different official course page; null = a person decides
  select case
    when p_prop is null or p_held is null then null
    when security.reference_url_has_use(p_prop, 'not_course_page') then 'keep:the proposed page is a course directory or search site, not the provider''s own site'
    when p_prop ~* '(^https?://handbook\.|programs-courses\.uq\.edu\.au)' and p_held !~* '(^https?://handbook\.|programs-courses\.uq\.edu\.au)'
      then 'keep:the provider''s course page stays official; the handbook page is a reference page'
    when p_prop ~* '(course-not-found|/index\.html$|find-a-study-option\.html$|/areas-of-study/|/postgraduate\.html$|/scholarships/|-minor/?$|/dom/?$)'
      then 'keep:the proposed page is a listing, not-found, scholarship, minor or domestic-only page'
    -- CF-247 20 Oct 2026 (Platform Admin "What we hold is correct"): a major or specialisation page of the course held
    when regexp_replace(rtrim(p_held, '/'), '/[^/]*$', '') = regexp_replace(rtrim(p_prop, '/'), '/[^/]*$', '')
         and lower(regexp_replace(rtrim(p_prop, '/'), '^.*/', '')) like lower(regexp_replace(rtrim(p_held, '/'), '^.*/', '')) || '-%'
      then 'keep:the proposed page is a major or specialisation of the course page held'
    when p_held ~* '^https?://handbook\.' and p_prop !~* '^https?://handbook\.'
         and substring(p_held from '^https?://handbook\.([^/]+)') = regexp_replace(substring(p_prop from '^https?://([^/]+)'), '^www\.', '')
      then 'take:the held page is the handbook; the provider''s course page showing the CRICOS code becomes official'
    when p_prop like rtrim(p_held, '/') || '/%' then 'take:the held page is a listing; the course''s own page under it becomes official'
    when substring(p_held from '^https?://([^/]+)') = substring(p_prop from '^https?://([^/]+)')
         and (regexp_match(p_held, '/(20[0-9]{2})/'))[1] < (regexp_match(p_prop, '/(20[0-9]{2})/'))[1]
         and lower(regexp_replace(rtrim(p_held, '/'), '^.*/', '')) = lower(regexp_replace(rtrim(p_prop, '/'), '^.*/', ''))
      then 'take:the same program code in a newer handbook year'
    else null end
$_$;


ALTER FUNCTION "security"."course_page_rule_v1"("p_held" "text", "p_prop" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_page_url_variants_v1"("p_provider" "uuid", "p_url" "text") RETURNS "text"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with u as (
    select regexp_replace(lower(coalesce(substring(p_url from '^https?://([^/?#:]+)'), '')), '^www\.', '') host,
           coalesce(substring(p_url from '^https?://[^/?#]+(/[^#]*)'), '/') pth),
  own as (
    select distinct h from (
      select regexp_replace(lower(coalesce(substring(pr.website from '^https?://([^/?#:]+)'), '')), '^www\.', '') h from catalogue.providers pr where pr.id = p_provider
      union all
      select regexp_split_to_table(lower(btrim(substr(e, strpos(e, '=') + 1))), '\s+')
        from catalogue.providers pr, jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'binding.provider_host_aliases'), '[]'::jsonb)) e
       where pr.id = p_provider and split_part(e, '=', 1) = pr.stable_key
      union all
      select regexp_replace(lower(d.domain), '^(https?://)?(www\.)?', '') from pipeline.provider_extra_domains d where d.provider_id = p_provider) z
    where h <> ''),
  base as (
    select rtrim(p_url, '/') b
    union all
    select pre || o.h || rtrim(u.pth, '/') from u, own o, unnest(array['https://', 'https://www.']) pre
     where u.host <> '' and exists (select 1 from own o2 where o2.h = u.host))
  select array(select distinct v from base, unnest(array[b, b || '/']) v where b <> '' order by 1)
$$;


ALTER FUNCTION "security"."course_page_url_variants_v1"("p_provider" "uuid", "p_url" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_page_url_variants_v1"("p_provider" "uuid", "p_url" "text") IS 'E16 title lookup (12 Nov 2026): a course address with and without its trailing slash and, on the provider''s own hosts, the same path on each own host.';



CREATE OR REPLACE FUNCTION "security"."course_recognition_delivery_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  with d as (select d.course_id, d.country_code from search.course_documents d where d.country_code in ('AU', 'NZ')),
  x as (select d.course_id, d.country_code,
               bool_or(r.scheme = 'cricos' and s.url is not null and (r.valid_to is null or r.valid_to > current_date)) served,
               bool_or(r.scheme = 'cricos' and r.valid_to is not null and r.valid_to <= current_date) dates_bad,
               bool_or(r.scheme = 'cricos' and s.url is null) no_source,
               bool_or(r.scheme = 'nzqa') nzqa
          from d left join catalogue.course_registrations r on r.course_id = d.course_id and r.status = 'active' and r.scheme in ('cricos', 'nzqa')
          left join pipeline.sources s on s.id = r.source_id and s.status = 'active'
         group by 1, 2)
  select jsonb_build_object(
    'au', jsonb_build_object('searchable', count(*) filter (where country_code = 'AU'),
            'served', count(*) filter (where country_code = 'AU' and served),
            'held_dates_inconsistent', count(*) filter (where country_code = 'AU' and not coalesce(served, false) and dates_bad),
            'held_source_missing', count(*) filter (where country_code = 'AU' and not coalesce(served, false) and not coalesce(dates_bad, false) and no_source),
            'no_registration', count(*) filter (where country_code = 'AU' and served is null)),
    'nz', jsonb_build_object('searchable', count(*) filter (where country_code = 'NZ'),
            'with_nzqa_code', count(*) filter (where country_code = 'NZ' and nzqa),
            'served', 0, 'held_reason', 'NZQA course listing not yet captured at course grain (RM4A)'),
    'next_action', 'F-DISC: reconcile active CRICOS registrations whose end date has passed; RM4A: capture a course-grain NZQF listing')
    into v from x;
  return v;
exception when others then
  return jsonb_build_object('known', false, 'reason', left(sqlerrm, 200));
end $$;


ALTER FUNCTION "security"."course_recognition_delivery_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_recognition_delivery_v1"() IS 'CF-247 RM1A-1 (O29): course recognition coverage for the Data Delivery screen (public.admin_course_recognition_delivery). Read only, about 0.2 s.';



CREATE OR REPLACE FUNCTION "security"."course_recognition_item_v1"("p_item" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_course uuid; v_rec jsonb;
begin
  if p_item is null or jsonb_typeof(p_item) <> 'object' then return p_item; end if;
  select d.course_id into v_course from search.course_documents d
   where lower(d.course_stable_key) = lower(p_item->>'course_id') and d.course_stable_key is not null limit 1;
  if v_course is not null then
    select x.recognition into v_rec from security.course_recognition_v1(array[v_course]) x;
  end if;
  return p_item || jsonb_build_object('recognition', coalesce(v_rec, '[]'::jsonb));
end $$;


ALTER FUNCTION "security"."course_recognition_item_v1"("p_item" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_recognition_item_v1"("p_item" "jsonb") IS 'CF-247 RM1A-1 (O29): a Website v3 course item with recognition[] added ([] when none is admitted); nothing else changed.';



CREATE OR REPLACE FUNCTION "security"."course_recognition_v1"("p_course_ids" "uuid"[]) RETURNS TABLE("course_id" "uuid", "recognition" "jsonb", "held_reason" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select u.id,
         coalesce(jsonb_agg(jsonb_build_object(
             'scheme', 'CRICOS', 'code', r.registration_code, 'status', 'registered',
             'authority', 'Australian Government (CRICOS)', 'source_url', s.url,
             'evidence_date', to_char((e.captured_at at time zone 'Australia/Melbourne')::date, 'YYYY-MM-DD'),     -- the stored register file behind this row
             'checked_on', to_char((s.last_success_at at time zone 'Australia/Melbourne')::date, 'YYYY-MM-DD'))  -- the register's last successful check
           order by r.registration_code)
           filter (where r.id is not null and s.url is not null and (r.valid_to is null or r.valid_to > current_date)), '[]'::jsonb),
         case when bool_or(r.id is not null and r.valid_to is not null and r.valid_to <= current_date) then 'registration_dates_inconsistent'
              when bool_or(r.id is not null and s.url is null) then 'registration_source_missing' end
    from unnest(p_course_ids) u(id)
    left join catalogue.course_registrations r on r.course_id = u.id and r.scheme = 'cricos' and r.status = 'active'
    left join pipeline.sources s on s.id = r.source_id and s.status = 'active'
    left join pipeline.evidence_artifacts e on e.id = r.evidence_id
   where u.id is not null
   group by u.id
$$;


ALTER FUNCTION "security"."course_recognition_v1"("p_course_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_recognition_v1"("p_course_ids" "uuid"[]) IS 'CF-247 RM1A-1 (O29): CRICOS course recognition for the given courses, with a held reason; read by Website API v3 course and the Admin Recognition views. Read only.';



CREATE OR REPLACE FUNCTION "security"."course_relink_fair_run_v1"("p_left" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_left int := greatest(1, coalesce(p_left, 1)); v_start timestamptz := clock_timestamp(); v_budget numeric := security.pipeline_num_v1('wc.relink_run_seconds', 60);
        v_each numeric := security.pipeline_num_v1('wc.relink_university_seconds', 20);
        r record; v_r jsonb; v_prov int := 0; v_err int := 0; v_slow int := 0; v_stopped text; v_state text; v_msg text; v_t0 timestamptz; v_moved int;
begin
  for r in select * from security.course_relink_order_v1() loop
    if v_left <= 0 then v_stopped := 'batch'; exit; end if;
    if extract(epoch from clock_timestamp() - v_start) >= v_budget then v_stopped := 'time_budget'; exit; end if;
    v_t0 := clock_timestamp();
    perform set_config('cf247.relink_deadline', least(v_start + make_interval(secs => v_budget::float8), v_t0 + make_interval(secs => v_each::float8))::text, true);
    begin
      v_r := security.course_relink_provider_v1(r.provider_id, v_left);
      v_moved := coalesce((v_r->>'trying')::int, 0) + coalesce((v_r->>'absent')::int, 0);
      v_left := v_left - v_moved;
      v_prov := v_prov + 1;
      if v_moved = 0 and v_r->>'stopped' = 'deadline' then
        v_slow := v_slow + 1;
        perform security.work_item_report_v1('course_relink', r.provider_id::text, 'relink', 'failed',
                  jsonb_build_object('provider_id', r.provider_id, 'owner', 'course-relink', 'class', 'transient',
                                     'message', 'no course settled within the university''s time (wc.relink_university_seconds)',
                                     'evidence', jsonb_build_object('pages', r.pages, 'seconds', round(extract(epoch from clock_timestamp() - v_t0)::numeric, 1))));
      else
        perform security.work_item_report_v1('course_relink', r.provider_id::text, 'relink', 'succeeded',
                  jsonb_build_object('provider_id', r.provider_id, 'owner', 'course-relink',
                                     'outcome', case when v_moved > 0 then 'succeeded_with_result' else 'succeeded_no_movement' end));
      end if;
    exception
      when query_canceled then
        -- last resort: the statement limit fired inside this university; its work is rolled back, the others' is kept, and the run ends here
        get stacked diagnostics v_state = returned_sqlstate, v_msg = message_text;
        v_err := v_err + 1;
        perform security.work_item_report_v1('course_relink', r.provider_id::text, 'relink', 'failed',
                  jsonb_build_object('provider_id', r.provider_id, 'owner', 'course-relink', 'class', 'transient', 'sqlstate', v_state, 'message', v_msg,
                                     'evidence', jsonb_build_object('pages', r.pages, 'seconds', round(extract(epoch from clock_timestamp() - v_t0)::numeric, 1))));
        v_stopped := 'statement_timeout';
        exit;
      when others then
        get stacked diagnostics v_state = returned_sqlstate, v_msg = message_text;
        v_err := v_err + 1;
        perform security.work_item_report_v1('course_relink', r.provider_id::text, 'relink', 'failed',
                  jsonb_build_object('provider_id', r.provider_id, 'owner', 'course-relink', 'sqlstate', v_state, 'message', v_msg, 'evidence', jsonb_build_object('pages', r.pages)));
    end;
  end loop;
  perform set_config('cf247.relink_deadline', '', true);
  return jsonb_build_object('providers', v_prov, 'failed', v_err, 'slow', v_slow, 'stopped', v_stopped, 'seconds', round(extract(epoch from clock_timestamp() - v_start)::numeric, 1));
end $$;


ALTER FUNCTION "security"."course_relink_fair_run_v1"("p_left" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_relink_order_v1"() RETURNS TABLE("provider_id" "uuid", "pages" bigint, "pos" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select z.provider_id, z.pages, (row_number() over (order by z.la nulls first, z.pages desc, z.provider_id))::int from (
    select p.provider_id, count(*) pages, max(w.last_attempt_at) la
      from pipeline.coverage_course_pages p
      left join pipeline.work_items w on w.lane = 'course_relink' and w.entity = p.provider_id::text and w.work_kind = 'relink'
     where p.read_status = any (security.course_relink_statuses_v1()) and not exists (select 1 from pipeline.course_relink x where x.course_id = p.course_id and not (x.state = 'absent' and x.rule < 2 and x.reason like 'no address%') and not security.source_proof_relink_asked_v1(x.course_id, coalesce(x.decided_at, x.started_at)))
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.provider_id)
     group by 1) z
   where security.work_item_eligible_v1('course_relink', z.provider_id::text, 'relink')
   order by 3
$$;


ALTER FUNCTION "security"."course_relink_order_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_relink_provider_v1"("p_provider_id" "uuid", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_forms jsonb; v_share numeric; v_try int := 0; v_absent int := 0; r record; v_c text[]; v_s text[];
        -- 3 Nov 2026 (SS-021 relink isolation): the university's addresses and swap titles, prepared once a university (not once a course)
        v_u text[]; v_ut text[]; v_useg text[]; v_usl text[]; v_utn text[]; v_ou text[]; v_oc uuid[]; v_ok1 text[]; v_ok2 text[]; v_sl text[];
        v_deadline timestamptz := nullif(current_setting('cf247.relink_deadline', true), '')::timestamptz; v_stopped text;
        v_cap int := security.pipeline_num_v1('relink.urls_per_university', 50000)::int;
        v_min int := security.pipeline_num_v1('relink.pattern_min_pages', 10)::int;
begin
  -- the university's address forms, learnt from its own verified pages: each form with enough pages, and the study level it serves
  with g as (select replace(lower(g.url), s.slug, '{slug}') tpl, c.study_level_id lvl, s.slug
               from pipeline.coverage_course_pages g join catalogue.courses c on c.id = g.course_id
               cross join lateral (select regexp_replace(regexp_replace(lower(c.canonical_title), '[^a-z0-9]+', '-', 'g'), '(^-|-$)', '', 'g') slug) s
              where g.provider_id = p_provider_id and g.status = 'bound' and g.read_status = 'read' and g.identity_basis is not null),
  t as (select tpl, count(*) n from g where length(slug) > 5 and strpos(tpl, '{slug}') > 0 group by 1 having count(*) >= v_min)
  select coalesce(jsonb_agg(jsonb_build_object('tpl', t.tpl, 'n', t.n, 'levels',
           (select coalesce(jsonb_agg(distinct g2.lvl), '[]'::jsonb) from g g2 where g2.tpl = t.tpl and g2.lvl is not null)) order by t.n desc), '[]'::jsonb),
         coalesce(sum(t.n), 0)::numeric / nullif((select count(*) from g), 0)
    into v_forms, v_share from t;
  if coalesce(v_share, 0) < security.pipeline_num_v1('relink.pattern_min_share', 0.5) then v_forms := '[]'::jsonb; end if;
  -- 3 Nov 2026 (SS-021 relink isolation, live 22:04 and 22:14 AEDT): the stored address lists were read, and every address's last part and the
  -- course title's address forms worked out, once for every course (addresses x courses regular expressions in one statement), so one large
  -- university passed the 120-second statement limit and the whole run rolled back. They are prepared once here (at most
  -- relink.urls_per_university addresses), and each course compares plain text.
  select array_agg(l.url order by l.url, l.title), array_agg(l.title order by l.url, l.title),
         array_agg(security.course_relink_url_seg_v1(l.url) order by l.url, l.title),
         array_agg(regexp_replace(substring(lower(l.url) from '/([^/?#]+)/?(?:[?#].*)?$'), '\.html?$', '') order by l.url, l.title),
         array_agg(lower(btrim(split_part(split_part(coalesce(l.title, ''), ' | ', 1), ' - ', 1))) order by l.url, l.title)
    into v_u, v_ut, v_useg, v_usl, v_utn
    from (select distinct u.url, u.title from (
            select pu.url, pu.title from pipeline.coverage_provider_urls pu where pu.provider_id = p_provider_id
            union select dl.url, dl.anchor_text from pipeline.provider_discovery_links dl where dl.provider_id = p_provider_id) u
           order by u.url, u.title limit v_cap) l;
  select array_agg(o.url), array_agg(o.course_id),
         array_agg(regexp_replace(regexp_replace(lower(coalesce(o.candidates->>'h1', '')), '&#?[a-z0-9]+;', ' ', 'g'), '[^a-z0-9]+', '', 'g')),
         array_agg(regexp_replace(regexp_replace(split_part(split_part(split_part(lower(coalesce(o.candidates->>'page_title', '')), ' | ', 1), ' – ', 1), ' - ', 1), '&#?[a-z0-9]+;', ' ', 'g'), '[^a-z0-9]+', '', 'g'))
    into v_ou, v_oc, v_ok1, v_ok2
    from pipeline.coverage_course_pages o where o.provider_id = p_provider_id and o.read_status = 'identity_mismatch';
  for r in
    select p.course_id, p.url old_url, c.study_level_id lvl, regexp_replace(regexp_replace(lower(c.canonical_title), '[^a-z0-9]+', '-', 'g'), '(^-|-$)', '', 'g') slug,
           regexp_replace(lower(c.canonical_title), '[^a-z0-9]+', '', 'g') nt, c.canonical_title ttl
      from pipeline.coverage_course_pages p join catalogue.courses c on c.id = p.course_id and c.lifecycle_status = 'active'
     where p.provider_id = p_provider_id and p.read_status = any (security.course_relink_statuses_v1())
       and not exists (select 1 from pipeline.course_relink x where x.course_id = p.course_id
                        and not (x.state = 'absent' and x.rule < 2 and x.reason like 'no address%') and not security.source_proof_relink_asked_v1(x.course_id, coalesce(x.decided_at, x.started_at)))
     order by p.course_id
     limit greatest(1, p_limit)
  loop
    -- 3 Nov 2026 (SS-021 relink isolation): stop between courses at the university's deadline (set by security.course_relink_fair_run_v1)
    if v_deadline is not null and clock_timestamp() >= v_deadline then v_stopped := 'deadline'; exit; end if;
    v_sl := security.course_relink_slugs_v1(r.ttl);
    select array_agg(z.url order by z.rk), array_agg(z.src order by z.rk) into v_c, v_s from (
      select distinct on (security.course_relink_url_norm_v1(q.url)) q.url, q.src, q.rk from (
        -- another course's refused page whose title is exactly this course's title
        select o.url, 'page_swap' src, 1::numeric rk from unnest(v_ou, v_oc, v_ok1, v_ok2) o(url, course_id, k1, k2)
         where o.course_id <> r.course_id and length(r.nt) > 8 and r.nt in (o.k1, o.k2)
        union all
        -- address forms: those used by verified pages of the same study level first, then by number of pages
        select replace(fm.form->>'tpl', '{slug}', r.slug), 'url_pattern',
               2 + (case when r.lvl is not null and (fm.form->'levels') @> to_jsonb(r.lvl) then 0 else 0.5 end) + fm.ord / 1000.0
          from jsonb_array_elements(v_forms) with ordinality fm(form, ord) where length(r.slug) > 5
           -- 22 Oct 2026 (NZ review fix 3): address guesses only in relink.url_pattern_countries
           and security.coverage_country(p_provider_id) in (select jsonb_array_elements_text(sx.value) from pipeline.platform_toolset_settings sx
                                                             where sx.toolset_key = 'pipeline' and sx.key = 'relink.url_pattern_countries')
        union all
        select l.url, 'url_list', 3 from unnest(v_u, v_usl) l(url, sl)
         where length(r.slug) > 10 and l.sl = r.slug
        union all
        -- CF-247 ops B (S5, relink.slug_variants_on): title forms (diacritics, apostrophes, "&", "(Level n)", bracketed qualifiers) and stored page titles
        select l.url, 'url_list_variant', 3.5 from unnest(v_u, v_useg, v_utn) l(url, seg, tn)
         where security.pipeline_num_v1('relink.slug_variants_on', 0) >= 1
           and (l.seg = any (v_sl) or (length(r.ttl) > 10 and l.tn = lower(btrim(r.ttl))))
        union all
        -- CF-247 ops B (S8, relink.year_current_on): the refused page's address with the current handbook year
        select security.course_relink_year_url_v1(r.old_url), 'url_year', 2.4
         where security.pipeline_num_v1('relink.year_current_on', 0) >= 1 and security.course_relink_year_url_v1(r.old_url) is not null
        union all
        -- CF-247 ops B (S7, relink.stored_search_reuse_on): candidates a previous course-page search found and did not try (paid evidence, stored)
        select su.u, 'stored_search', 4 + su.o / 1000.0
          from unnest(security.course_relink_stored_untried_v1(r.course_id)) with ordinality su(u, o)
         where security.pipeline_num_v1('relink.stored_search_reuse_on', 0) >= 1) q
      where q.url is not null
        and security.course_relink_url_norm_v1(q.url) is distinct from security.course_relink_url_norm_v1(r.old_url)  -- CF-247 ops B (S6): the refused page in another spelling is not a candidate
        and not exists (select 1 from pipeline.course_page_blocks b where b.course_id = r.course_id and security.course_relink_url_norm_v1(b.url) = security.course_relink_url_norm_v1(q.url))
        and not exists (select 1 from pipeline.page_rejections pr where pr.course_id = r.course_id and security.course_relink_url_norm_v1(pr.url) = security.course_relink_url_norm_v1(q.url))
      order by security.course_relink_url_norm_v1(q.url), q.rk) z;
    if coalesce(cardinality(v_c), 0) = 0 then
      insert into pipeline.course_relink(course_id, provider_id, old_url, pattern, state, reason, decided_at, rule)
      values (r.course_id, p_provider_id, r.old_url, v_forms->0->>'tpl', 'absent', 'no address from the university''s address forms or stored lists', now(), 2)
      on conflict (course_id) do update set pattern = excluded.pattern, reason = excluded.reason, decided_at = now(), rule = 2;
      update pipeline.course_link_search set state = 'none', done_at = coalesce(done_at, now()) where course_id = r.course_id and state = 'queued' and requested_at is null;
      v_absent := v_absent + 1;
    else
      v_c := v_c[1:3]; v_s := v_s[1:3];  -- fixed: at most three candidates a course
      insert into pipeline.course_relink(course_id, provider_id, old_url, candidates, sources, pattern, state, rule)
      values (r.course_id, p_provider_id, r.old_url, to_jsonb(v_c), to_jsonb(v_s), v_forms->0->>'tpl', 'trying', 2)
      on conflict (course_id) do update set candidates = excluded.candidates, sources = excluded.sources, pattern = excluded.pattern, state = 'trying',
             reason = null, decided_at = null, started_at = now(), rule = 2;
      insert into pipeline.course_link_search(course_id, provider_id, stage, state, candidates, cand_idx, bound_url, queued_at, done_at)
      values (r.course_id, p_provider_id, 'title', 'found', to_jsonb(v_c), 1, v_c[1], now(), null)
      on conflict (course_id) do update set stage = 'title', state = 'found', candidates = excluded.candidates, cand_idx = 1, bound_url = excluded.bound_url,
             results = null, attempts = 0, done_at = null;
      perform security.course_link_bind_v1(r.course_id, p_provider_id, v_c[1], v_s[1]);
      v_try := v_try + 1;
    end if;
  end loop;
  return jsonb_build_object('forms', jsonb_array_length(v_forms), 'trying', v_try, 'absent', v_absent, 'stopped', v_stopped);
end $_$;


ALTER FUNCTION "security"."course_relink_provider_v1"("p_provider_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_relink_slugs_v1"("p_title" "text") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  -- CF-247 ops B (S5): the address forms of a course title: as written; without diacritics and apostrophes, "&" read as "and" and an NZ
  -- "(Level n)" removed; the same without any bracketed qualifier; and, for register titles, without a trailing campus code (" - UBCO"), the
  -- word "degree", a repeated last phrase ("Civil Engineering Civil Engineering"), with "Field: Award" read as "Award Field". Forms of 10
  -- letters or fewer are left out (too general).
  with t as (select lower(coalesce(p_title, '')) t0),
  n as (select t0, regexp_replace(regexp_replace(replace(regexp_replace(translate(t0, 'āēīōūàáâäãçèéêëìíîïñòóôöõùúûüý', 'aeiouaaaaaceeeeiiiinooooouuuuy'),
                 '[''’`]', '', 'g'), '&', ' and '), '\s*\(level [0-9]+\)', '', 'g'), '\s+', ' ', 'g') t1 from t),
  m as (select n.*, btrim(regexp_replace(regexp_replace(regexp_replace(t1, '\s+-\s+[a-z]{2,6}$', ''), '\([^)]*\)|\mdegree\M', '', 'g'), '\s+', ' ', 'g')) t2 from n),
  r as (select m.*, regexp_replace(t2, '(\m[a-z0-9 ]+\M) \1$', '\1') t3, regexp_replace(t2, '^([^:]+):\s*(.+)$', '\2 \1') t4 from m),
  s as (select regexp_replace(regexp_replace(t0, '[^a-z0-9]+', '-', 'g'), '(^-|-$)', '', 'g') s0,
               regexp_replace(regexp_replace(t1, '[^a-z0-9]+', '-', 'g'), '(^-|-$)', '', 'g') s1,
               regexp_replace(regexp_replace(regexp_replace(t1, '\([^)]*\)', '', 'g'), '[^a-z0-9]+', '-', 'g'), '(^-|-$)', '', 'g') s2,
               regexp_replace(regexp_replace(t3, '[^a-z0-9]+', '-', 'g'), '(^-|-$)', '', 'g') s3,
               regexp_replace(regexp_replace(t4, '[^a-z0-9]+', '-', 'g'), '(^-|-$)', '', 'g') s4 from r)
  select coalesce(array_agg(distinct x) filter (where length(x) > 10), '{}') from s, unnest(array[s.s0, s.s1, s.s2, s.s3, s.s4]) x  -- fixed: the length relink has used since 18 Oct
$_$;


ALTER FUNCTION "security"."course_relink_slugs_v1"("p_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_relink_statuses_v1"() RETURNS "text"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 ops B (S3): the refused page states course-relink tries (setting relink.statuses)
  select coalesce((select array(select jsonb_array_elements_text(s.value)) from pipeline.platform_toolset_settings s
                    where s.toolset_key = 'pipeline' and s.key = 'relink.statuses' and jsonb_typeof(s.value) = 'array'), array['identity_mismatch'])
$$;


ALTER FUNCTION "security"."course_relink_statuses_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_relink_stored_untried_v1"("p_course" "uuid") RETURNS "text"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 ops B (S7): addresses a previous course-page search found for the course but did not try (paid evidence already stored), never a
  -- page already rejected or blocked for the course
  select coalesce(array_agg(z.u order by z.o), '{}') from (
    select c.u, c.o from pipeline.course_link_search s cross join lateral jsonb_array_elements_text(case when jsonb_typeof(s.candidates) = 'array' then s.candidates else '[]'::jsonb end) with ordinality c(u, o)
     where s.course_id = p_course and s.state in ('none', 'error', 'verified') and c.o > coalesce(s.cand_idx, 0)
       and not exists (select 1 from pipeline.page_rejections pr where pr.course_id = p_course and security.course_relink_url_norm_v1(pr.url) = security.course_relink_url_norm_v1(c.u))
       and not exists (select 1 from pipeline.course_page_blocks b where b.course_id = p_course and security.course_relink_url_norm_v1(b.url) = security.course_relink_url_norm_v1(c.u))) z
$$;


ALTER FUNCTION "security"."course_relink_stored_untried_v1"("p_course" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_relink_tick_v1"("p_batch" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_left int := greatest(1, coalesce(p_batch, 200)); v_pid uuid; v_r jsonb; v_found int; v_absent int; v_prov int := 0;
begin
  perform security.page_refind_settle_v1();  -- 19 Oct 2026: re-finds on a provider's current website
  -- settle: a candidate the reader accepted, or every candidate refused
  update pipeline.course_relink x set state = 'found', decided_at = now(), result_url = s.bound_url, reason = 'the reader confirmed the page'
    from pipeline.course_link_search s where x.state = 'trying' and s.course_id = x.course_id and s.state = 'verified';
  get diagnostics v_found = row_count;
  update pipeline.course_relink x set state = 'absent', decided_at = now(), reason = 'every candidate address was refused by the reader or did not answer'
    from pipeline.course_link_search s where x.state = 'trying' and s.course_id = x.course_id and s.state in ('none', 'error');
  get diagnostics v_absent = row_count;
  -- 3 Nov 2026 (SS-021 work continuity §4, wc.relink_fair_on): universities in turn, each isolated, within the run's time budget
  if security.pipeline_num_v1('wc.relink_fair_on', 0) >= 1 then
    return jsonb_build_object('found', v_found, 'absent', v_absent) || security.course_relink_fair_run_v1(v_left);
  end if;
  -- next universities with refused pages not yet relinked
  for v_pid in select p.provider_id from pipeline.coverage_course_pages p
                where p.read_status = any (security.course_relink_statuses_v1()) and not exists (select 1 from pipeline.course_relink x where x.course_id = p.course_id and not (x.state = 'absent' and x.rule < 2 and x.reason like 'no address%') and not security.source_proof_relink_asked_v1(x.course_id, coalesce(x.decided_at, x.started_at)))
                  and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.provider_id)
                group by 1 order by count(*) desc loop
    exit when v_left <= 0;
    v_r := security.course_relink_provider_v1(v_pid, v_left);
    v_left := v_left - (v_r->>'trying')::int - (v_r->>'absent')::int;
    v_prov := v_prov + 1;
  end loop;
  return jsonb_build_object('found', v_found, 'absent', v_absent, 'providers', v_prov);
end $$;


ALTER FUNCTION "security"."course_relink_tick_v1"("p_batch" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_relink_url_norm_v1"("p_url" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  -- CF-247 ops B (S6): one form of an address for comparison: lower case, no scheme, no www, no fragment, no tracking parameters, no index
  -- page, no trailing slash
  select nullif(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(
           lower(btrim(coalesce(p_url, ''))), '#.*$', ''), '^[a-z]+://(www\.)?', ''), '[?&](utm_[a-z]+|gclid|fbclid)=[^&]*', '', 'g'),
           '/(index|default)\.(html?|aspx?|php)$', ''), '/+$', ''), '')
$_$;


ALTER FUNCTION "security"."course_relink_url_norm_v1"("p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_relink_url_seg_v1"("p_url" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  -- CF-247 ops B (S5): the last part of an address, without query, fragment, trailing slash or page suffix
  select regexp_replace(coalesce(substring(lower(coalesce(p_url, '')) from '/([^/?#]+)/?(?:[?#].*)?$'), ''), '\.(html?|aspx?|php)$', '')
$_$;


ALTER FUNCTION "security"."course_relink_url_seg_v1"("p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_relink_year_url_v1"("p_url" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $_$
  -- CF-247 ops B (S8): the address with an older handbook year in its path moved to the current year (null when it has none, or it is current)
  select case when y is not null and y < extract(year from now())::int
              then regexp_replace(p_url, '/' || y::text || '(/|$)', '/' || extract(year from now())::int::text || '\1') end
    from (select (substring(coalesce(p_url, '') from '/((?:19|20)[0-9]{2})(?:/|$)'))::int y) z
$_$;


ALTER FUNCTION "security"."course_relink_year_url_v1"("p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_roadmap_item_v1"("p_item" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_course uuid; v_rec jsonb; v_codes jsonb;
begin
  if p_item is null or jsonb_typeof(p_item) <> 'object' then return p_item; end if;
  select d.course_id into v_course from search.course_documents d
   where lower(d.course_stable_key) = lower(p_item->>'course_id') and d.course_stable_key is not null limit 1;
  if v_course is not null then
    select x.recognition into v_rec from security.course_recognition_v1(array[v_course]) x;
    select x.field_of_study_codes into v_codes from security.course_field_codes_v1(array[v_course]) x;
  end if;
  return p_item || jsonb_build_object('recognition', coalesce(v_rec, '[]'::jsonb), 'field_of_study_codes', coalesce(v_codes, '[]'::jsonb));
end $$;


