CREATE OR REPLACE FUNCTION "security"."course_search_paid_cap_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_cap numeric; v_used numeric; v_hold text; v_picked bigint;
        v_day timestamptz := date_trunc('day', now() at time zone 'UTC') at time zone 'UTC';
        v_month timestamptz := date_trunc('month', now()) + interval '1 month';  -- fixed: the month roll-over
begin
  select s.monthly_credit_cap into v_cap from pipeline.course_link_search_settings s where s.id = 1;
  select coalesce(sum(u.units), 0) into v_used from pipeline.coverage_vendor_usage u where u.purpose = 'course_link_search' and u.at >= date_trunc('month', now());
  if v_cap is not null and v_used + 2 > v_cap then  -- fixed: one search's credits, as the picker counts them
    return jsonb_build_object('code', 'month_cap', 'words', 'this month''s course search credits are used', 'resumes_at', v_month);
  end if;
  v_hold := security.lane_paid_hold_v1('course_link_search');
  if v_hold is not null then
    return jsonb_build_object('code', 'paid_hold', 'words', v_hold, 'resumes_at', case when v_hold ~* 'month|reserve' then v_month else v_day + interval '1 day' end);  -- fixed: the day roll-over
  end if;
  select count(*) into v_picked from pipeline.course_link_search s where s.sent_at >= v_day;
  if v_picked >= security.pipeline_num_v1('search.daily_picked_cap', 100) then
    return jsonb_build_object('code', 'daily_cap', 'words', 'today''s course search cap (' || security.pipeline_num_v1('search.daily_picked_cap', 100)::int || ' courses) is reached',
                              'picked', v_picked, 'resumes_at', v_day + interval '1 day');  -- fixed: the UTC day roll-over of the cap
  end if;
  return null;
end $$;


ALTER FUNCTION "security"."course_search_paid_cap_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."course_study_load_stage1_v1"("p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_set int := 0; v_by jsonb;
begin
  if auth.uid() is not null and coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  create temp table if not exists _csl (course_id uuid, load text, evidence_id uuid) on commit drop;
  truncate _csl;
  insert into _csl
  select r.course_id,
         case when r.ft and r.pt then 'both' when r.ft then 'full_time' else 'part_time' end,
         r.evidence_id
    from (select f.course_id,
                 bool_or(lower(f.quote) ~ '\mfull[- ]?time\M' and lower(f.quote) !~ '\mfull[- ]?time[- ]equivalent') ft,
                 bool_or(lower(f.quote) ~ '\mpart[- ]?time\M' and lower(f.quote) !~ '\mpart[- ]?time (work|job|jobs|employment)\M') pt,
                 (array_agg(f.evidence_id order by f.updated_at desc nulls last, f.id desc)
                    filter (where (lower(f.quote) ~ '\mfull[- ]?time\M' or lower(f.quote) ~ '\mpart[- ]?time\M') and f.evidence_id is not null))[1] evidence_id
            from pipeline.field_enrich_items f
            join catalogue.courses c on c.id = f.course_id and c.lifecycle_status = 'active'
           where f.state = 'filled' and f.field in ('duration', 'intakes', 'delivery') and f.quote is not null
           group by f.course_id) r
   where r.ft or r.pt;
  select jsonb_object_agg(load, n) into v_by from (select load, count(*) n from _csl group by 1) z;
  if p_apply then
    update catalogue.courses c set study_load = s.load, study_load_source = 'provider_page', study_load_evidence_id = s.evidence_id
      from _csl s
     where c.id = s.course_id
       and coalesce(c.study_load_source, 'provider_page') = 'provider_page'
       and (c.study_load, c.study_load_source, c.study_load_evidence_id) is distinct from (s.load, 'provider_page', s.evidence_id);
    get diagnostics v_set = row_count;
    insert into pipeline.admin_control_events (area, action, target, detail, actor)
    values ('api_v3', 'course_study_load_stage1', 'catalogue.courses.study_load',
            jsonb_build_object('set', v_set, 'by_load', v_by, 'source', 'provider_page'), auth.uid());
  end if;
  return jsonb_build_object('applied', p_apply, 'set', v_set, 'by_load', v_by);
end;
$$;


ALTER FUNCTION "security"."course_study_load_stage1_v1"("p_apply" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_study_load_stage1_v1"("p_apply" boolean) IS 'CF-247 API v3 PR B (REQ-52 stage 1): study load from the verbatim page quote of a filled duration, intakes or delivery reading (full-time, part-time or both); never from delivery mode; never changes a register or manual value. Count-only unless p_apply; audited.';



