CREATE OR REPLACE FUNCTION "security"."course_url_fill_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_batch int := greatest(100, least(security.pipeline_num_v1('batch.course_url_fill', 2000)::int, 5000));
        v_rate jsonb; v_retracted int := 0; v_emptied int := 0; v_filled int := 0; v_refilled int := 0; v_by jsonb; v_now timestamptz := clock_timestamp();
        -- Workstream E (Platform Admin 2 Nov 2026 23:24): a course with a pending Layer 4 course-link review is left for the reviewer
        v_respect boolean := security.pipeline_num_v1('course_url.fill_respects_layer4', 1) = 1;
        v_skipped int := 0; v_skip_ids uuid[] := '{}'; v_iq jsonb;
begin
  if security.pipeline_num_v1('course_url.fill_enabled', 1) <> 1 then
    return jsonb_build_object('skipped', 'course_url.fill_enabled is 0');
  end if;
  -- guard 4: pause when too many recent fills were taken back
  v_rate := security.course_url_retraction_30d_v1();
  if (v_rate->>'filled')::int >= security.pipeline_num_v1('course_url.retraction_min_fills', 50) and coalesce((v_rate->>'retraction_pct')::numeric, 0) > security.pipeline_num_v1('course_url.max_retraction_pct', 5) then
    update pipeline.platform_toolset_settings set value = '0'::jsonb, reason = 'paused by the fill job: ' || (v_rate->>'retraction_pct') || '% of the last 30 days'' fills were taken back (limit ' || (v_rate->>'max_pct') || '%)', updated_at = now()
      where toolset_key = 'pipeline' and key = 'course_url.fill_enabled';
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('catalogue', 'course_url_fill_paused', 'course_url.fill_enabled', v_rate, null);
    return jsonb_build_object('paused', v_rate);
  end if;
  -- guard 3: take back fills whose binding changed (page no longer bound, or a different copy)
  with gone as (
    update pipeline.course_url_fills u
       set retracted_at = now(),
           retract_reason = case when p.course_id is null or p.status <> 'bound' then 'page no longer bound' else 'binding changed' end
      from pipeline.course_url_fills x
      left join pipeline.coverage_course_pages p on p.course_id = x.course_id
     where u.course_id = x.course_id and x.retracted_at is null
       and (p.course_id is null or p.status <> 'bound' or p.evidence_id is distinct from x.evidence_id)
    returning u.course_id, u.url)
  , emptied as (
    update catalogue.courses c set course_url = null, updated_at = now()
      from gone g
     where c.id = g.course_id and c.course_url = g.url
       and not exists (select 1 from pipeline.manual_locks m where m.entity = 'course' and m.entity_id = c.id and m.field = 'course_url')
    returning c.id)
  select (select count(*) from gone), (select count(*) from emptied) into v_retracted, v_emptied;
  -- guard 5 (2 Nov 2026 23:24): count the courses that qualify but have a pending Layer 4 course-link review; they are not filled
  if v_respect then
    select count(*), coalesce(array_agg(c.id order by c.id), '{}') into v_skipped, v_skip_ids
      from catalogue.courses c
      join catalogue.providers pr on pr.id = c.provider_id
      join ref.countries k on k.id = pr.country_id
      join pipeline.coverage_course_pages p on p.course_id = c.id
     where c.lifecycle_status = 'active' and c.course_url is null
       and p.status = 'bound' and p.identity_basis is not null and p.read_status = 'read' and p.evidence_id is not null
       and coalesce(nullif(p.candidates->>'final_url', ''), p.url) ~* '^https?://'
       and security.coverage_identity_allowed(p.provider_id, p.identity_basis, 'official_url')
       and k.iso_alpha2 in (select jsonb_array_elements_text(s.value) from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'course_url.fill_countries')
       and not exists (select 1 from pipeline.manual_locks m where m.entity = 'course' and m.entity_id = c.id and m.field = 'course_url')
       and not exists (select 1 from pipeline.course_url_fills x where x.course_id = c.id and x.retracted_at is null)
       and c.id in (select i.entity_id from pipeline.layer4_review_items i
                     where i.entity_type = 'course' and i.field_code = 'official_course_url' and i.status = 'pending' and i.entity_id is not null);
  end if;
  -- guards 1 and 2: fill empty links from proven bindings, in the countries allowed, never a locked course
  with f as (
    select c.id course_id, coalesce(nullif(p.candidates->>'final_url', ''), p.url) url, p.evidence_id, p.identity_basis, k.iso_alpha2 cc
      from catalogue.courses c
      join catalogue.providers pr on pr.id = c.provider_id
      join ref.countries k on k.id = pr.country_id
      join pipeline.coverage_course_pages p on p.course_id = c.id
     where c.lifecycle_status = 'active' and c.course_url is null
       and p.status = 'bound' and p.identity_basis is not null and p.read_status = 'read' and p.evidence_id is not null
       and coalesce(nullif(p.candidates->>'final_url', ''), p.url) ~* '^https?://'
       and security.coverage_identity_allowed(p.provider_id, p.identity_basis, 'official_url')  -- the country's own proofs for the official link (an NZ page labelled cricos_code waits for 8a)
       and k.iso_alpha2 in (select jsonb_array_elements_text(s.value) from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'course_url.fill_countries')
       and not exists (select 1 from pipeline.manual_locks m where m.entity = 'course' and m.entity_id = c.id and m.field = 'course_url')
       and not exists (select 1 from pipeline.course_url_fills x where x.course_id = c.id and x.retracted_at is null)
       and c.id not in (select i.entity_id from pipeline.layer4_review_items i
                         where v_respect and i.entity_type = 'course' and i.field_code = 'official_course_url' and i.status = 'pending' and i.entity_id is not null)
     order by (k.iso_alpha2 = 'NZ') desc, c.id
     limit v_batch),
  ins as (
    insert into pipeline.course_url_fills(course_id, url, evidence_id, identity_basis, filled_at, retracted_at, retract_reason)
    select course_id, url, evidence_id, identity_basis, v_now, null, null from f
    on conflict (course_id) do update set url = excluded.url, evidence_id = excluded.evidence_id, identity_basis = excluded.identity_basis, filled_at = v_now, retracted_at = null, retract_reason = null
    returning course_id, (xmax <> 0) again),
  upd as (
    update catalogue.courses c set course_url = f.url, updated_at = now() from f where c.id = f.course_id and c.course_url is null
    returning c.id)
  select (select count(*) from upd), (select count(*) from ins where again) into v_filled, v_refilled;
  select coalesce(jsonb_object_agg(cc, n), '{}'::jsonb) into v_by
    from (select k.iso_alpha2 cc, count(*) n from pipeline.course_url_fills x join catalogue.courses c on c.id = x.course_id join catalogue.providers pr on pr.id = c.provider_id join ref.countries k on k.id = pr.country_id
           where x.filled_at = v_now group by 1) z;
  if v_skipped > 0 and to_regprocedure('security.integration_issue_upsert_v1(jsonb,text)') is not null then
    -- one integration-queue issue by fingerprint (an unchanged problem updates that row, never a duplicate); a queue error never stops the fill
    begin
      execute 'select security.integration_issue_upsert_v1($1, $2)' into v_iq
        using jsonb_build_object('fingerprint', 'course-url-fill:skipped-pending-layer4',
                'title', 'Course link fill waits for pending Layer 4 course-link reviews',
                'layer', 'Catalogue', 'subsystem', 'course-url-fill', 'workstream', 'A4', 'severity', 'P2', 'root_cause_class', 'human_decision',
                'validation_layer', 'V4', 'source', 'job course-url-fill',
                'failure', v_skipped || ' course(s) qualify for a course link from their proven page but have a pending Layer 4 course-link review, so the fill left them',
                'expected', 'Layer 4 decides the course page first; the next nightly fill writes the link once no course-link review is pending',
                'course_ids', to_jsonb(v_skip_ids),
                'evidence', jsonb_build_object('skipped_pending_layer4', v_skipped, 'run_at', v_now, 'setting', 'course_url.fill_respects_layer4')),
              'course-url-fill';
    exception when others then
      v_iq := jsonb_build_object('error', left(sqlerrm, 300));
    end;
  end if;
  if v_filled > 0 or v_retracted > 0 or v_skipped > 0 then
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('catalogue', 'course_url_filled', 'courses.course_url',
            jsonb_build_object('filled', v_filled, 'refilled', v_refilled, 'by_country', v_by, 'retracted', v_retracted, 'emptied', v_emptied, 'batch', v_batch,
                               'skipped_pending_layer4', v_skipped, 'respects_layer4', v_respect, 'integration_queue', v_iq), null);
  end if;
  if v_filled > 0 or v_emptied > 0 then
    insert into search.refresh_requests(requested_by) values ('course_url fill (' || v_filled || ' filled, ' || v_emptied || ' emptied)');
  end if;
  return jsonb_build_object('filled', v_filled, 'refilled', v_refilled, 'by_country', v_by, 'retracted', v_retracted, 'emptied', v_emptied, 'rate', v_rate,
                            'skipped_pending_layer4', v_skipped, 'respects_layer4', v_respect, 'integration_queue', v_iq);
end $_$;


ALTER FUNCTION "security"."course_url_fill_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_url_fill_v1"() IS 'nightly: fills an empty course_url from the course''s proven own page (five guards: proven binding only, manual locks honoured, re-fill on binding change, pauses above the 30-day retraction limit, waits while a Layer 4 course-link review is pending (course_url.fill_respects_layer4)); NZ brief item 5 Option A; Workstream E 2 Nov 2026 23:24';



CREATE OR REPLACE FUNCTION "security"."course_url_retraction_30d_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with f as (select retracted_at, retract_reason from pipeline.course_url_fills where filled_at > now() - interval '30 days')
  select jsonb_build_object(
    'filled', count(*),
    'retracted', count(*) filter (where retracted_at is not null),
    'retraction_pct', round(100.0 * count(*) filter (where retracted_at is not null) / nullif(count(*), 0), 2),
    'by_reason', (select coalesce(jsonb_object_agg(coalesce(retract_reason, 'kept'), n), '{}'::jsonb) from (select retract_reason, count(*) n from f group by 1) r),
    'max_pct', security.pipeline_num_v1('course_url.max_retraction_pct', 5),
    'enabled', security.pipeline_num_v1('course_url.fill_enabled', 1) = 1)
  from f
$$;


ALTER FUNCTION "security"."course_url_retraction_30d_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."course_url_retraction_30d_v1"() IS 'course_url fills in the last 30 days, how many were taken back and why (NZ brief item 5 guard 4); read by the fill job and the hourly report';



CREATE OR REPLACE FUNCTION "security"."course_years_from_text"("p_text" "text") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare
  s text := lower(coalesce(p_text, ''));
  u text := '(years?|yrs?|months?|weeks?|semesters?|trimesters?)';
  m text[]; n numeric; y numeric;
begin
  if s ~ '^\s*[0-9]+(\.[0-9]+)?\s*$' then n := btrim(s)::numeric; return case when n > 0 and n <= 10 then n end; end if;
  s := regexp_replace(s, '(up to\s*)?[0-9]+(\.[0-9]+)?\s*' || u || '\s*,?\s*(of\s+)?part[ -]time', ' ', 'g');
  s := regexp_replace(s, 'up to\s*[0-9]+(\.[0-9]+)?\s*' || u, ' ', 'g');
  s := regexp_replace(s, 'part[ -]time[^0-9]{0,40}[0-9]+(\.[0-9]+)?\s*' || u, ' ', 'g');
  if s ~ '[0-9](\.[0-9]+)?\s*(–|—|-|to)\s*[0-9]' then return null; end if;
  if s ~ ('[0-9]\s*' || u || '[^0-9]{0,60}\mor\M[^0-9]{0,30}[0-9]+(\.[0-9]+)?\s*' || u) then return null; end if;
  m := regexp_match(s, '([0-9]+(?:\.[0-9]+)?)\s*' || u);
  if m is null then return null; end if;
  n := m[1]::numeric;
  y := case when m[2] ~ '^month' then n / 12 when m[2] ~ '^week' then n / 52 when m[2] ~ '^semester' then n / 2 when m[2] ~ '^trimester' then n / 3 else n end;
  if m[2] ~ '^(year|yr)' then
    m := regexp_match(s, '[0-9]+(?:\.[0-9]+)?\s*(?:years?|yrs?)\s*(?:and\s*)?([0-9]+)\s*months?');
    if m is not null then y := y + m[1]::numeric / 12; end if;
  end if;
  y := round(y, 2);
  return case when y > 0 and y <= 10 then y end;
end $_$;


ALTER FUNCTION "security"."course_years_from_text"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_admission_apply_v1"("p_limit" integer DEFAULT 300, "p_extractor" "text" DEFAULT 'coverage-sweep-v0.5.4'::"text", "p_attributes" "text"[] DEFAULT ARRAY['official_url'::"text", 'english'::"text"]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security', 'search'
    AS $$
declare r record; v_src uuid; v_ok int:=0; v_err int:=0; v_l4 int:=0; v_courses uuid[]:='{}'; v_before jsonb; v_after jsonb; v_payload jsonb; v_last text;
        v_auto int:=0; v_item uuid; v_sys uuid := 'c0ffee00-0000-4000-8000-000000000150'; v_rule text;  -- fixed: the system automation account (Decision 263)
        v_lock int := 0; v_held int := 0; v_skip int := 0; v_stop boolean := false;
        v_cap int := greatest(1, security.pipeline_num_v1('admit.item_error_limit', 25)::int);
        v_recheck interval := make_interval(hours => security.pipeline_num_v1('admit.refused_recheck_hours', 24)::int);
begin
  drop table if exists _adm;
  create temp table _adm on commit drop as select * from security.coverage_admission_plan_v1(p_extractor) where action in ('write','differs') and attribute=any(p_attributes);
  if not exists (select 1 from _adm) then return jsonb_build_object('written',0,'layer4',0); end if;

  -- IQ-00067 (Platform Admin 3 Nov 2026 15:52 §9): a course whose page, English requirement or intakes were set by hand is never offered to
  -- apply. Its rows are held with the named reason manual_lock (pipeline.coverage_admission_holds) and leave the batch: not written, not raised
  -- to Layer 4, not decided by rule. The lock rule itself (security.layer4_course_link_apply_impl) is unchanged.
  insert into pipeline.coverage_admission_holds as h(course_id, attribute, proposed_md5, proposed, page_url, plan_action, reason, detail)
  select distinct on (a.course_id, a.attribute, md5(a.proposed::text)) a.course_id, a.attribute, md5(a.proposed::text), a.proposed, a.page_url, a.action,
         'manual_lock', jsonb_build_object('lock_fields', k.f, 'current', a.current)
    from _adm a cross join lateral (select array_agg(l.field order by l.field) f from pipeline.manual_locks l
                                     where l.entity = 'course' and l.entity_id = a.course_id and l.field = any (security.coverage_admission_lock_fields_v1(a.attribute))) k
   where k.f is not null
  on conflict (course_id, attribute, proposed_md5) do update
     set last_seen_at = now(), seen_count = h.seen_count + 1, reason = excluded.reason, detail = excluded.detail, plan_action = excluded.plan_action;
  get diagnostics v_lock = row_count; delete from _adm a where exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = a.course_id
                                      and l.field = any (security.coverage_admission_lock_fields_v1(a.attribute)));
  -- IQ-00067: a proposal the apply refused waits admit.refused_recheck_hours before it is tried again, unless it changes
  v_skip := 0; delete from _adm a where exists (select 1 from pipeline.coverage_admission_holds h where h.course_id = a.course_id and h.attribute = a.attribute
                                      and h.proposed_md5 = md5(a.proposed::text) and h.reason = 'apply_refused' and h.last_seen_at > now() - v_recheck);
  get diagnostics v_skip = row_count;
  if not exists (select 1 from _adm) then
    return jsonb_build_object('written',0,'layer4',0,'held_manual_lock',v_lock,'refused_waiting',v_skip);
  end if;

  insert into pipeline.course_fact_source_qualifications(source_id,country_id,source_key,source_class,authority_name,provider_cricos,admitted_domains,mapping_strategy,evidence_strategy,qualification_status,notes,metadata)
  select distinct on (s.id) s.id, s.country_id, 'au_'||lower(a.provider_cricos)||'_coverage_sweep','provider_first_party',
         coalesce(p.display_name,p.canonical_name), upper(a.provider_cricos), array['official_course_url','english_requirement','intake'],
         'course page accepted only when it prints the course''s CRICOS code',
         'page stored gzipped as evidence with its SHA-256; values written only where the course has none',
         'bounded','Decision 163 admission rule (Platform Admin 29 Sep 2026)',
         jsonb_build_object('decision','Decision 163','apply_admitted',true,'search_admitted',true,'identity_authority',false,'change_control_ref','CF-CHG-20260915-247')
    from _adm a join catalogue.providers p on p.id=a.provider_id
    cross join lateral (select security.coverage_sweep_source(a.provider_id) id) x
    join pipeline.sources s on s.id=x.id
   where a.action='write' and a.provider_cricos is not null
     and not exists (select 1 from pipeline.course_fact_source_qualifications q where q.source_id=s.id and q.provider_cricos=upper(a.provider_cricos));

  insert into search.enrichment_source_gates(projection_code,domain_code,source_id,gate_status,approval_ref,approved_at,created_at,updated_at)
  select distinct 'courses', d, security.coverage_sweep_source(a.provider_id), 'approved',
         'CF-CHG-20260915-247; Decision 163 admission rule; Platform Admin approval 29 Sep 2026 09:56 IST', now(), now(), now()
    from _adm a cross join unnest(array_remove(array['official_course_url', case when 'english'=any(p_attributes) then 'course_english' end, case when 'intakes'=any(p_attributes) then 'course_intake' end],null)) d
   where a.action='write'
     and not exists (select 1 from search.enrichment_source_gates g where g.projection_code='courses' and g.domain_code=d and g.source_id=security.coverage_sweep_source(a.provider_id));

  v_before:=security.consumer_api_snapshot_v1();
  for r in select a.course_id, a.provider_id, a.provider_cricos, a.course_cricos, a.evidence_id, a.content_hash, a.page_url,
                  jsonb_object_agg(a.attribute, a.proposed) props
             from _adm a where a.action='write'
            group by 1,2,3,4,5,6,7 order by md5(a.course_id::text||clock_timestamp()::text) limit greatest(1,least(coalesce(p_limit,300),1000)) loop
    v_payload:='{}'::jsonb;
    if r.props ? 'official_url' then v_payload:=v_payload||jsonb_build_object('course_url',r.props->'official_url'->>'course_url','link_type','official_course','audience','international'); end if;
    if r.props ? 'english' and not security.uni_adapter_excluded(r.course_id, 'english') then v_payload:=v_payload||jsonb_build_object('english_requirements',r.props->'english'->'english_requirements'); end if;
    if r.props ? 'intakes' and not security.uni_adapter_excluded(r.course_id, 'intakes') then v_payload:=v_payload||jsonb_build_object('intakes',r.props->'intakes'->'intakes'); end if;
    begin
      if r.provider_cricos is null or r.course_cricos is null then
        perform security.coverage_apply_course_v1(r.course_id, security.coverage_sweep_source(r.provider_id), r.evidence_id, r.page_url, r.content_hash, v_payload);
      else
      perform public.svc_coursefacts_apply_record(security.coverage_sweep_source(r.provider_id), r.evidence_id, r.provider_cricos, r.course_cricos,
              'coverage:'||r.course_id, r.page_url, r.content_hash, v_payload, true);
      end if;
      v_ok:=v_ok+1; v_courses:=v_courses||r.course_id;
    exception when others then v_err:=v_err+1; v_last:=left(sqlerrm,200);
      -- IQ-00067: the refused item is held with its reason and the batch goes on, up to admit.item_error_limit refusals a run
      perform security.coverage_admission_hold_v1(r.course_id, r.props, r.page_url, 'write', 'apply_refused',
                jsonb_build_object('error', left(sqlerrm, 500), 'sqlstate', sqlstate));
      v_held := v_held + 1;
      if v_held >= v_cap then v_stop := true; end if;
    end;
    exit when v_stop;
  end loop;

  -- Decision 263: differing values; a proposal decided before is not raised again; official course pages are decided by rule where a rule applies
  for r in select a.*, case a.attribute when 'official_url' then 'official_course_url' when 'english' then 'course_english' else 'course_intake' end fc
             from _adm a
            where a.action='differs'
              and not exists (select 1 from pipeline.layer4_review_items i where i.entity_type='course' and i.entity_id=a.course_id and i.status='pending'
                                and i.field_code=case a.attribute when 'official_url' then 'official_course_url' when 'english' then 'course_english' else 'course_intake' end)
              -- CF-247 15 Oct (waste rules): the same proposal is not raised again while an identical one was superseded within the window (it was raised 144 times a day)
              and not exists (select 1 from pipeline.layer4_review_items i where i.entity_type='course' and i.entity_id=a.course_id and i.status='superseded'
                                and i.field_code=case a.attribute when 'official_url' then 'official_course_url' when 'english' then 'course_english' else 'course_intake' end
                                and i.proposed_value=a.proposed and i.decided_at > now() - make_interval(days => security.pipeline_num_v1('waste.flipflop_window_days', 7)::int))
              -- Decision 263: a proposal a person or a rule decided is never raised again
              and not exists (select 1 from pipeline.layer4_review_items i where i.entity_type='course' and i.entity_id=a.course_id
                                and i.status in ('rejected','approved','edited_approved')
                                and i.field_code=case a.attribute when 'official_url' then 'official_course_url' when 'english' then 'course_english' else 'course_intake' end
                                and i.proposed_value=a.proposed) loop
    exit when v_stop;
    begin
    v_rule := case when r.attribute = 'official_url' then security.course_page_rule_v1(r.current->>0, r.proposed->>'course_url') end;
    -- 24 Oct 2026 (UI audit Phase 0): a "take" rule never applies a plain http:// address (the link apply refuses it and the whole
    -- batch failed, every run since 23 Oct 11:40 UTC); the row waits for a person instead, like any row no rule decides
    if v_rule like 'take:%' and coalesce(r.proposed->>'course_url', '') !~* '^https://' then v_rule := null; end if;
    -- IQ-00043 (Platform Admin 3 Nov 2026 08:44 §5): a rule never takes a page that was replaced, rejected or held; the row waits for a person
    if v_rule like 'take:%' and security.course_link_hold_basis_v1(r.course_id, 'official_course', r.proposed->>'course_url', null) is not null then v_rule := null; end if;
    insert into pipeline.layer4_review_items(entity_type,entity_id,field_code,evidence_id,before_value,proposed_value,layer2_state,layer3_state,status,escalation_reason,change_control_ref,decided_at)
    values ('course', r.course_id, r.fc, r.evidence_id, r.current, r.proposed, jsonb_build_object('source','coverage sweep','page',r.page_url), '{}'::jsonb,
            case when v_rule like 'keep:%' then 'rejected' when v_rule like 'take:%' then 'approved' else 'pending' end,
            case r.attribute
              when 'official_url' then 'The course page that shows this course''s CRICOS code is a different address from the official page we hold. Please check which page is current.'
              when 'english' then 'The course page gives a different English score from the one we hold. Please check the page and confirm the requirement.'
              else 'The course page lists different intake months from the ones we hold. Please check the page and confirm the intakes.' end,
            case when v_rule is null then 'CF-CHG-20260915-247' else 'CF-CHG-20260915-247; Decision 263 (decided by rule)' end,
            case when v_rule is not null then now() end)
    returning id into v_item;
    if v_rule is null then
      v_l4 := v_l4 + 1;
    else
      if v_rule like 'take:%' then
        perform security.layer4_course_link_apply_impl(v_sys, v_item, jsonb_build_object('url', r.proposed->>'course_url'), 'Rule: ' || substring(v_rule from 6));
        v_courses := v_courses || r.course_id;
      end if;
      insert into pipeline.layer4_decisions(review_item_id,action,actor_id,reason,before_value,proposed_value,final_value,evidence_id,layer2_state,layer3_state,change_control_ref)
      values (v_item, case when v_rule like 'take:%' then 'approve' else 'reject' end, v_sys, 'Decided by rule (Decision 263): ' || substring(v_rule from 6),
              r.current, r.proposed, case when v_rule like 'take:%' then r.proposed end, r.evidence_id,
              jsonb_build_object('source','coverage sweep','page',r.page_url), '{}'::jsonb, 'CF-CHG-20260915-247; Decision 263 (decided by rule)');
      v_auto := v_auto + 1;
    end if;
    exception when others then
      -- IQ-00067 (Platform Admin 3 Nov 2026 15:52 §9): one item never aborts the batch. Its Layer 4 item, link and decision roll back together;
      -- the item is held with the refusal named, and the batch goes on, up to admit.item_error_limit refusals a run
      v_err := v_err + 1; v_last := left(sqlerrm, 200);
      perform security.coverage_admission_hold_v1(r.course_id, jsonb_build_object(r.attribute, r.proposed), r.page_url, 'differs', 'apply_refused',
                jsonb_build_object('error', left(sqlerrm, 500), 'sqlstate', sqlstate, 'rule', v_rule, 'current', r.current));
      v_held := v_held + 1;
      if v_held >= v_cap then v_stop := true; end if;
    end;
  end loop;

  if cardinality(v_courses)>0 then
    perform search.refresh_course_enrichment_scoped_v1(v_courses,true);
    v_after:=security.consumer_api_snapshot_v1();
    insert into pipeline.consumer_api_baselines(label,snapshot) values
      ('before coverage admission batch ('||cardinality(v_courses)||' courses, Decision 163)',v_before),
      ('after coverage admission batch ('||cardinality(v_courses)||' courses, Decision 163)',v_after);
  end if;
  return jsonb_build_object('written',v_ok,'errors',v_err,'last_error',v_last,'layer4',v_l4,'decided_by_rule',v_auto,
                            'held_manual_lock',v_lock,'held_refused',v_held,'refused_waiting',v_skip,'stopped_at_limit',v_stop);
end $$;


ALTER FUNCTION "security"."coverage_admission_apply_v1"("p_limit" integer, "p_extractor" "text", "p_attributes" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_admission_gated_v1"("p_key" "text", "p_limit" integer, "p_extractor" "text", "p_attributes" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare m pipeline.job_input_marks%rowtype; v_in timestamptz := security.admit_input_mark_v1(); v jsonb; v_more boolean;
        v_full int := security.pipeline_num_v1('waste.admit_full_check_hours', 6)::int;
begin
  insert into pipeline.job_input_marks(job_key) values (p_key) on conflict do nothing;
  select * into m from pipeline.job_input_marks where job_key = p_key for update;
  if not coalesce((m.last_result->>'more')::boolean, true) and m.last_input_at is not null and v_in <= m.last_input_at
     and m.last_full_at > now() - make_interval(hours => v_full) then
    update pipeline.job_input_marks set runs_skipped = runs_skipped + 1, last_run_at = now() where job_key = p_key;
    return jsonb_build_object('skipped', 'no new input');
  end if;
  v := security.coverage_admission_apply_v1(p_limit, p_extractor, p_attributes);
  v_more := coalesce((v->>'written')::int, 0) >= p_limit or coalesce((v->>'stopped_at_limit')::boolean, false);  -- IQ-00067: stopped at the refusal limit
  update pipeline.job_input_marks set last_input_at = v_in, last_full_at = now(), last_run_at = now(), last_result = v || jsonb_build_object('more', v_more),
         runs_done = runs_done + 1 where job_key = p_key;
  return v;
end $$;


ALTER FUNCTION "security"."coverage_admission_gated_v1"("p_key" "text", "p_limit" integer, "p_extractor" "text", "p_attributes" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_admission_hold_v1"("p_course" "uuid", "p_props" "jsonb", "p_page" "text", "p_action" "text", "p_reason" "text", "p_detail" "jsonb") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- IQ-00067: hold each attribute of an admission item with its reason (p_props: attribute -> proposed value); one row a course, field and proposal
  insert into pipeline.coverage_admission_holds as h(course_id, attribute, proposed_md5, proposed, page_url, plan_action, reason, detail)
  select p_course, k.key, md5(k.value::text), k.value, p_page, p_action, p_reason, coalesce(p_detail, '{}'::jsonb) from jsonb_each(p_props) k
  on conflict (course_id, attribute, proposed_md5) do update
     set last_seen_at = now(), seen_count = h.seen_count + 1, reason = excluded.reason, detail = excluded.detail, plan_action = excluded.plan_action, page_url = excluded.page_url
$$;


ALTER FUNCTION "security"."coverage_admission_hold_v1"("p_course" "uuid", "p_props" "jsonb", "p_page" "text", "p_action" "text", "p_reason" "text", "p_detail" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_admission_lock_fields_v1"("p_attribute" "text") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  -- IQ-00067: the manual_locks fields that hold an admission attribute (the link apply's own lock fields for the page, plus a whole-record lock)
  select case p_attribute
    when 'official_url' then array['official_url', 'course_url', 'all']
    when 'english' then array['english', 'english_requirements', 'all']
    when 'intakes' then array['intakes', 'intake', 'all']
    else array['all'] end
$$;


ALTER FUNCTION "security"."coverage_admission_lock_fields_v1"("p_attribute" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_admission_plan_v1"("p_extractor" "text" DEFAULT 'coverage-sweep-v0.5.3'::"text") RETURNS TABLE("course_id" "uuid", "provider_id" "uuid", "provider_cricos" "text", "course_cricos" "text", "evidence_id" "uuid", "content_hash" "text", "page_url" "text", "attribute" "text", "action" "text", "proposed" "jsonb", "current" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security'
    AS $$
  with pg as (
    select p.course_id, p.provider_id, p.url, p.evidence_id, p.candidates c, e.content_hash, p.identity_basis ib,
           (select pr.registration_code from catalogue.provider_registrations pr where pr.provider_id=p.provider_id and lower(pr.registration_scheme)='cricos' and coalesce(pr.status,'active') not in ('inactive','cancelled','archived') order by pr.checked_at desc nulls last limit 1) pc,
           (select cr.registration_code from catalogue.course_registrations cr where cr.course_id=p.course_id and lower(cr.scheme)='cricos' limit 1) cc
      from pipeline.coverage_course_pages p join pipeline.evidence_artifacts e on e.id=p.evidence_id
      join catalogue.courses co on co.id=p.course_id and co.lifecycle_status='active'
     where p.read_status='read' and security.coverage_identity_allowed(p.provider_id, p.identity_basis, null) and p.candidates->>'extractor'=p_extractor
       and not security.layer4_entity_or_parent_blocked('course',p.course_id,'operational')
       and not security.course_held_v1(p.course_id)),  -- SS-007 (1 Nov 2026): a course under an open binding remediation hold is never admitted from its page
  url as (
    select pg.*, 'official_url'::text attribute,
           jsonb_build_object('course_url',coalesce(nullif(pg.c->>'final_url',''),pg.url)) proposed,
           (select jsonb_agg(l.url) from catalogue.course_links l where l.course_id=pg.course_id and l.link_type='official_course' and l.status='active') cur
      from pg where security.coverage_identity_allowed(pg.provider_id, pg.ib, 'official_url')),
  eng as (
    select pg.*, 'english'::text attribute,
           jsonb_build_object('english_requirements',
             (select jsonb_agg(x) from (
                select jsonb_build_object('test_code','IELTS','overall_score',(pg.c->'english'->>'ielts_overall')::numeric,
                         'component_scores',case when pg.c->'english' ? 'ielts_min_band' then jsonb_build_object('listening',(pg.c->'english'->>'ielts_min_band')::numeric,'reading',(pg.c->'english'->>'ielts_min_band')::numeric,'writing',(pg.c->'english'->>'ielts_min_band')::numeric,'speaking',(pg.c->'english'->>'ielts_min_band')::numeric) else '{}'::jsonb end,
                         'notes','Course page (CRICOS code on page), coverage sweep') x where pg.c->'english' ? 'ielts_overall'
                union all select jsonb_build_object('test_code','PTE','overall_score',(pg.c->'english'->>'pte_overall')::numeric,'notes','Course page (CRICOS code on page), coverage sweep') where pg.c->'english' ? 'pte_overall'
                union all select jsonb_build_object('test_code','TOEFL_IBT','overall_score',(pg.c->'english'->>'toefl_overall')::numeric,'notes','Course page (CRICOS code on page), coverage sweep') where pg.c->'english' ? 'toefl_overall') q)) proposed,
           (select jsonb_agg(jsonb_build_object('test',t.code,'overall',r.overall_score)) from catalogue.course_english_requirements r join ref.english_tests t on t.id=r.english_test_id where r.course_id=pg.course_id and r.status='active') cur
      from pg where pg.c->'english' ?| array['ielts_overall','pte_overall','toefl_overall'] and security.coverage_identity_allowed(pg.provider_id, pg.ib, 'english') and (coalesce(pg.c->>'english_by','')<>'adapter' or exists (select 1 from pipeline.uni_adapters u where u.provider_id=pg.provider_id and u.enabled and u.admit and 'english' = any (u.admit_fields)))),
  itk as (
    select pg.*, 'intakes'::text attribute,
           jsonb_build_object('intakes',(select jsonb_agg(jsonb_build_object('intake_label',m,'source_intake_key',lower(pg.cc)||':current:'||lower(m))) from jsonb_array_elements_text(pg.c->'intakes') mm(m))) proposed,
           (select jsonb_agg(i.intake_label) from catalogue.course_intakes i where i.course_id=pg.course_id and coalesce(i.status,'active')='active') cur
      from pg where jsonb_array_length(coalesce(pg.c->'intakes','[]'))>0 and security.coverage_identity_allowed(pg.provider_id, pg.ib, 'intakes') and pg.c->>'intakes_by'='adapter' and exists (select 1 from pipeline.uni_adapters u where u.provider_id=pg.provider_id and u.enabled and u.admit and 'intakes' = any (u.admit_fields))),
  allx as (select * from url union all select * from eng union all select * from itk)
  select a.course_id, a.provider_id, a.pc, a.cc, a.evidence_id, a.content_hash, a.url, a.attribute,
         case
           when (a.pc is null or a.cc is null) and security.coverage_country(a.provider_id) = 'AU' then 'unresolved'
           when a.cur is null then 'write'
           when a.attribute='official_url' and exists (select 1 from jsonb_array_elements_text(a.cur) k(v) where security.coverage_norm_url(k.v)=security.coverage_norm_url(a.proposed->>'course_url')) then 'same'
           when a.attribute='english' and not exists (
                  select 1 from jsonb_array_elements(a.proposed->'english_requirements') r(p)
                   where not exists (select 1 from jsonb_array_elements(a.cur) k(v) where k.v->>'test'=p->>'test_code' and (k.v->>'overall')::numeric=(p->>'overall_score')::numeric)
                     and exists (select 1 from jsonb_array_elements(a.cur) k(v) where k.v->>'test'=p->>'test_code')) then 'same'
           when a.attribute='intakes' and not exists (
                  select 1 from jsonb_array_elements(a.proposed->'intakes') r(p)
                   where not exists (select 1 from jsonb_array_elements_text(a.cur) k(v) where k.v ilike '%'||(p->>'intake_label')||'%')) then 'same'
           else 'differs' end,
         a.proposed, a.cur
    from allx a
$$;


ALTER FUNCTION "security"."coverage_admission_plan_v1"("p_extractor" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_admit_recheck_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_before jsonb; v_n int;
begin
  select jsonb_object_agg(m.job_key, jsonb_build_object('last_full_at', m.last_full_at, 'last_result', m.last_result)) into v_before
    from pipeline.job_input_marks m where m.job_key in ('coverage-admit', 'coverage-admit-intakes');
  update pipeline.job_input_marks set last_full_at = null where job_key in ('coverage-admit', 'coverage-admit-intakes') and last_full_at is not null;
  get diagnostics v_n = row_count;
  return jsonb_build_object('ok', true, 'changed', v_n, 'evidence', jsonb_build_object('issue', p_issue, 'marks_before', v_before));
end $$;


ALTER FUNCTION "security"."coverage_admit_recheck_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_admit_recheck_verify_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_at timestamptz; m record;
begin
  select max(r.started_at) into v_at from pipeline.ops_remedy_runs r where r.issue_id = p_issue and r.remedy_code = 'coverage_admit_recheck';
  select * into m from pipeline.job_input_marks where job_key = 'coverage-admit';
  return jsonb_build_object('passed', v_at is not null and m.last_full_at is not null and m.last_full_at > v_at,
    'measure', jsonb_build_object('acted_at', v_at, 'last_full_at', m.last_full_at, 'last_result', m.last_result),
    'evidence', jsonb_build_object('held_manual_lock', (select count(*) from pipeline.coverage_admission_holds h where h.reason = 'manual_lock' and h.last_seen_at >= coalesce(v_at, now())),
                                   'held_refused', (select count(*) from pipeline.coverage_admission_holds h where h.reason = 'apply_refused' and h.last_seen_at >= coalesce(v_at, now()))));
end $$;


ALTER FUNCTION "security"."coverage_admit_recheck_verify_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_ai_match_prepare_v1"("p_providers" integer DEFAULT 4, "p_courses" integer DEFAULT 300) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security'
    AS $_$
declare r record; v jsonb := '[]'::jsonb; v_n int; v_cap int := security.retry_cap_v1('ai_match');  -- CF-247 15 Oct: attempts worth making (Waste rules)
begin
  for r in
    with pv as materialized (select distinct co0.provider_id pid from catalogue.courses co0 where co0.lifecycle_status = 'active'),
    scope as materialized (  -- 31 Oct 2026 (StudySearch F1): the provider checks once per provider, not once per active course
      select pv.pid from pv
       where security.enrich_focus_v1(pv.pid)  -- CF-247 15 Oct: focus providers only (Waste rules)
          or security.course_list_read_v1(pv.pid)  -- 22 Oct 2026: and any provider with a read course list page
          or security.bind_match_scope_v1(pv.pid)),  -- SP-1: tranche overrides and the top Australian providers by courses without a page
    missing as (
      select co.provider_id, count(*) n
        from catalogue.courses co
        left join pipeline.coverage_course_pages p on p.course_id = co.id
       where co.lifecycle_status = 'active'
         and co.provider_id in (select s.pid from scope s)  -- focus, read course list, or SP-1 bind scope (scope above)
         and (p.course_id is null or p.status = 'mismatch')
         and not security.no_page_hold_v1(co.id) and not security.course_held_v1(co.id)  -- SS-007: remediation hold; SP-1: recorded no page / conjoint, until a newer map
         and not exists (select 1 from pipeline.coverage_ai_match q where q.course_id = co.id and (q.state in ('ready', 'leased')
                           or (q.state = 'no_candidates' and security.page_match_bonus_v1(co.id, co.provider_id) = 0)))
         and ((select count(*) from pipeline.coverage_ai_match q where q.course_id = co.id) < v_cap
              or security.page_match_bonus_v1(co.id, co.provider_id) = 1)  -- 22 Oct 2026: one more after each course list read, whatever the earlier count
       group by 1)
    select m.provider_id, m.n from missing m
     where exists (select 1 from pipeline.coverage_provider_urls u where u.provider_id = m.provider_id)
     order by coalesce((select pp.rank from pipeline.provider_priority pp where pp.provider_id = m.provider_id), 100000), m.n desc
     limit greatest(1, least(p_providers, 500))
  loop
    insert into pipeline.coverage_ai_match(course_id, provider_id, attempt, state, candidates)
    with c as (
      select co.id course_id, lower(coalesce(co.course_code, '')) code,
             security.coverage_text_tokens(regexp_replace(co.canonical_title, '\(\s*level\s+\d+\s*\)', '', 'i')) tok,
             (select count(*) from pipeline.coverage_ai_match q where q.course_id = co.id) prev
        from catalogue.courses co
        left join pipeline.coverage_course_pages p on p.course_id = co.id
       where co.provider_id = r.provider_id and co.lifecycle_status = 'active'
         and (p.course_id is null or p.status = 'mismatch')
         and not security.no_page_hold_v1(co.id) and not security.course_held_v1(co.id)  -- SS-007: remediation hold; SP-1: recorded no page / conjoint, until a newer map
         and not exists (select 1 from pipeline.coverage_ai_match q where q.course_id = co.id and (q.state in ('ready', 'leased')
                           or (q.state = 'no_candidates' and security.page_match_bonus_v1(co.id, co.provider_id) = 0)))
         and ((select count(*) from pipeline.coverage_ai_match q where q.course_id = co.id) < v_cap
              or security.page_match_bonus_v1(co.id, co.provider_id) = 1)
       order by coalesce(co.open_to_international, false) desc, co.id
       limit greatest(1, least(p_courses, 1000))),
    tried as (
      select p.course_id, p.url from pipeline.coverage_course_pages p join c using (course_id)
      union select q.course_id, q.chosen_url from pipeline.coverage_ai_match q join c using (course_id) where q.chosen_url is not null
                union select x.course_id, x.url from pipeline.page_rejections x join c using (course_id) /* 24 Oct 2026: rejected pages are never candidates */
                union select b.course_id, b.url from pipeline.course_page_blocks b join c using (course_id) /* S1: blocked pages neither */),
    u as (
      select url, title, tokens, title_tokens, cardinality(tokens) ns, cardinality(title_tokens) nt
        from pipeline.coverage_provider_urls where provider_id = r.provider_id
         and url !~* '/(inherent-requirements|entry-requirements|admission-requirements|english-requirements|fees?|tuition-fees?|scholarships?|apply|how-to-apply|applying|careers?|credit|recognition-of-prior-learning|timetables?|news|events?|stories|blog|alumni|contact|faqs?)(/|$)'
         and url !~* '\.(pdf|jpe?g|png|gif|svg|docx?|xlsx?|zip)(\?|$)'),
    ct as (select course_id, cardinality(tok) nc, t from c, unnest(tok) t),
    ut as (select url, ns n, t from u, unnest(tokens) t union all select url, nt, t from u, unnest(title_tokens) t),
    m as (select ct.course_id, ut.url, max(ct.nc) nc, max(ut.n) nu, count(*) hits from ct join ut using (t) group by 1, 2),
    s as (select m.course_id, m.url, max(2.0 * hits / nullif(nc + nu, 0)) sc from m group by 1, 2
          union all
          select c.course_id, u.url, 2.0 from c join u on length(c.code) >= 6 and position(c.code in lower(u.url)) > 0),
    best as (select s.course_id, s.url, max(s.sc) sc from s where not exists (select 1 from tried t where t.course_id = s.course_id and t.url = s.url) group by 1, 2),
    rk as (select b.*, row_number() over (partition by b.course_id order by b.sc desc, length(b.url)) n from best b)
    select c.course_id, r.provider_id, c.prev + 1,
           case when count(rk.url) < greatest(1, security.pipeline_num_v1('ai_match.min_candidates', 2)::int) then 'no_candidates' else 'ready' end,
           coalesce(jsonb_agg(jsonb_build_object('url', rk.url, 'title', left(coalesce(u.title, ''), 160)) order by rk.n) filter (where rk.url is not null), '[]'::jsonb)
      from c left join rk on rk.course_id = c.course_id and rk.n <= 25
      left join u on u.url = rk.url
     group by c.course_id, c.prev;
    get diagnostics v_n = row_count;
    v := v || jsonb_build_object('provider_id', r.provider_id, 'prepared', v_n);
  end loop;
  return v;
end $_$;


ALTER FUNCTION "security"."coverage_ai_match_prepare_v1"("p_providers" integer, "p_courses" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_apply_course_v1"("p_course_id" "uuid", "p_source_id" "uuid", "p_evidence_id" "uuid", "p_url" "text", "p_hash" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c record; r jsonb; v_test uuid; v_key text; v_links int := 0; v_intakes int := 0; v_english int := 0; v_fees int := 0; v_cur text; v_floor numeric; v_ident text; v_ident_url text; v_cc text;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select co.id, co.provider_id, lower(coalesce(nullif(btrim(co.course_code), ''), co.id::text)) code, a.currency_code
    into c from catalogue.courses co join catalogue.providers p on p.id = co.provider_id
    join pipeline.coverage_admission_countries a on a.country_id = p.country_id and a.active
   where co.id = p_course_id;
  if c.id is null then raise exception 'course not found or its country has no admission rule'; end if;
  if security.layer4_entity_or_parent_blocked('course', p_course_id, 'operational') then raise exception 'course operationally blocked by Layer 4' using errcode = '42501'; end if;
  if p_source_id is null or p_evidence_id is null or coalesce(btrim(p_url), '') = '' or coalesce(btrim(p_hash), '') = '' then raise exception 'source, evidence, page and hash required'; end if;

  if nullif(btrim(p_payload->>'course_url'), '') is not null then
    insert into catalogue.course_links(course_id, link_type, url, audience, label, is_primary, status, source_id, evidence_id, confidence, last_verified_at, updated_at)
    values (p_course_id, 'official_course', btrim(p_payload->>'course_url'), 'international', 'Official provider course page', false, 'active', p_source_id, p_evidence_id, 1, now(), now())
    on conflict (course_id, link_type, url) do update set status = 'active', source_id = excluded.source_id, evidence_id = excluded.evidence_id,
           confidence = 1, last_verified_at = now(), updated_at = now();
    -- IQ-00043: a link held by the reactivation guard (trigger reactivation_guard) or a lock is not counted as applied
    v_links := case when exists (select 1 from catalogue.course_links l where l.course_id = p_course_id and l.link_type = 'official_course'
                                    and l.url = btrim(p_payload->>'course_url') and l.status = 'active') then 1 else 0 end;
  end if;
  for r in select value from jsonb_array_elements(coalesce(p_payload->'intakes', '[]'::jsonb)) loop
    if nullif(btrim(r->>'intake_label'), '') is null then raise exception 'intake_label required'; end if;
    v_key := coalesce(nullif(r->>'source_intake_key', ''), c.code || ':' || coalesce(r->>'intake_year', 'current') || ':' || lower(r->>'intake_label'));
    insert into catalogue.course_intakes as ci(course_id, intake_year, intake_label, start_date, status, source_id, evidence_id, confidence, source_intake_key)
    values (p_course_id, nullif(r->>'intake_year', '')::int, r->>'intake_label', nullif(r->>'start_date', '')::date, 'active', p_source_id, p_evidence_id, 1, v_key)
    on conflict (course_id, source_id, source_intake_key) where source_id is not null and source_intake_key is not null
    -- 2 Nov 2026 (intake dates): a write without a year keeps the held year, start date and deadline; an older year never replaces a later one
    do update set intake_year = case when excluded.intake_year is null or excluded.intake_year < ci.intake_year then ci.intake_year else excluded.intake_year end,
                  intake_label = excluded.intake_label,
                  start_date = case when excluded.intake_year > ci.intake_year then excluded.start_date when excluded.intake_year < ci.intake_year then ci.start_date
                                    else coalesce(excluded.start_date, ci.start_date) end,
                  application_deadline = case when excluded.intake_year > ci.intake_year then null else ci.application_deadline end,
                  status = 'active',
                  evidence_id = excluded.evidence_id, confidence = 1;
    v_intakes := v_intakes + 1;
  end loop;
  for r in select value from jsonb_array_elements(coalesce(p_payload->'english_requirements', '[]'::jsonb)) loop
    select id into v_test from ref.english_tests where code = upper(btrim(r->>'test_code')) limit 1;
    if v_test is null then raise exception 'english test not seeded: %', r->>'test_code'; end if;
    insert into catalogue.course_english_requirements(course_id, english_test_id, overall_score, component_scores, notes, source_id, evidence_id, confidence,
                                                      source_requirement_key, status, last_verified_at)
    values (p_course_id, v_test, nullif(r->>'overall_score', '')::numeric, coalesce(r->'component_scores', '{}'::jsonb), r->>'notes', p_source_id, p_evidence_id, 1,
            coalesce(nullif(r->>'source_requirement_key', ''), c.code || ':' || upper(btrim(r->>'test_code'))), 'active', now())
    on conflict (course_id, english_test_id) do update set overall_score = excluded.overall_score, component_scores = excluded.component_scores,
           notes = excluded.notes, source_id = excluded.source_id, evidence_id = excluded.evidence_id, confidence = 1,
           source_requirement_key = excluded.source_requirement_key, status = 'active', last_verified_at = now();
    v_english := v_english + 1;
  end loop;
  if p_payload ? 'fee_amount' then
    v_cur := coalesce(nullif(btrim(p_payload->>'currency_code'), ''), c.currency_code);
    if v_cur is distinct from c.currency_code then raise exception 'fee currency % does not match the country currency %', v_cur, c.currency_code; end if;
    if nullif(p_payload->>'fee_amount', '')::numeric is null or (p_payload->>'fee_amount')::numeric <= 0 then raise exception 'positive fee amount required'; end if;
    -- 23 Oct 2026 (NZ brief C3): below the country floor the fee is quarantined (status review, Layer 4 item), never admitted silently
    v_floor := security.fee_below_floor_v1(p_course_id, (p_payload->>'fee_amount')::numeric, nullif(btrim(p_payload->>'fee_basis'), ''));
    -- 24 Oct 2026 (R1, apply-time identity check): a fee for a course whose bound page carries a proof the country's tuition policy does not
    -- accept is never admitted live, whatever the caller checked: written unverified with one Layer 4 row (source identity_basis_reverify).
    -- Manual bindings are exempt. A page re-bound under the country's rule re-admits the fee through this same path.
    select p.identity_basis, p.url, k.iso_alpha2 into v_ident, v_ident_url, v_cc
      from pipeline.coverage_course_pages p join catalogue.providers pr on pr.id = p.provider_id join ref.countries k on k.id = pr.country_id
     where p.course_id = p_course_id and p.status = 'bound' and coalesce(p.basis, '') <> 'manual' and p.identity_basis is not null
       and p.identity_basis <> 'manual' and not security.coverage_identity_allowed(c.provider_id, p.identity_basis, 'tuition') limit 1;
    if v_ident is not null then
      if not exists (select 1 from pipeline.layer4_review_items l where l.entity_type = 'course' and l.entity_id = p_course_id and l.field_code = 'provider_current_tuition' and l.status = 'pending') then
        insert into pipeline.layer4_review_items(entity_type, entity_id, field_code, evidence_id, before_value, proposed_value, layer2_state, layer3_state, status, escalation_reason, change_control_ref)
        values ('course', p_course_id, 'provider_current_tuition', p_evidence_id, null,
                jsonb_build_object('amount', (p_payload->>'fee_amount')::numeric, 'currency', v_cur, 'basis', nullif(btrim(p_payload->>'fee_basis'), ''), 'page', p_url),
                jsonb_build_object('source', 'identity_basis_reverify', 'state', 'quarantined', 'country', v_cc, 'identity_basis', v_ident, 'page', v_ident_url), '{}'::jsonb, 'pending',
                'quarantined at the write: the course page was bound with a ' || v_ident || ' proof, which the ' || v_cc || ' tuition policy does not accept; re-binding the page under the country''s rule re-admits the fee',
                'CF-CHG-20260915-247 R1 apply-time identity check');
      end if;
      v_floor := coalesce(v_floor, -1);  /* fixed: a sentinel that keeps the fee unverified through the same write below; never shown */
    end if;
    insert into catalogue.course_fees(course_id, fee_year, audience, fee_type, amount, currency_code, basis, notes, source_id, evidence_id, confidence,
                                      source_fee_key, status, last_verified_at, source_snapshot_at, updated_at)
    values (p_course_id, nullif(p_payload->>'fee_year', '')::int, 'international', 'provider_current_tuition', (p_payload->>'fee_amount')::numeric, v_cur,
            nullif(btrim(p_payload->>'fee_basis'), ''), p_payload->>'fee_notes', p_source_id, p_evidence_id, 1,
            c.code || ':international:' || coalesce(p_payload->>'fee_year', 'current') || ':' || coalesce(nullif(btrim(p_payload->>'fee_basis'), ''), 'tuition'),
            case when v_floor is not null then 'unverified' else 'active' end, now(), now(), now())
    on conflict (course_id, source_id, source_fee_key) where source_id is not null and source_fee_key is not null
    do update set amount = excluded.amount, currency_code = excluded.currency_code, basis = excluded.basis, fee_year = excluded.fee_year,
                  evidence_id = excluded.evidence_id, confidence = 1, status = case when v_floor is not null then 'unverified' else 'active' end, last_verified_at = now(), source_snapshot_at = now(), updated_at = now();
    if v_floor is not null then
      if v_floor <> -1 and not exists (select 1 from pipeline.layer4_review_items l where l.entity_type = 'course' and l.entity_id = p_course_id and l.field_code = 'provider_current_tuition' and l.status = 'pending') then
        insert into pipeline.layer4_review_items(entity_type, entity_id, field_code, evidence_id, before_value, proposed_value, layer2_state, layer3_state, status, escalation_reason, change_control_ref)
        values ('course', p_course_id, 'provider_current_tuition', p_evidence_id, null,
                jsonb_build_object('amount', (p_payload->>'fee_amount')::numeric, 'currency', v_cur, 'basis', nullif(btrim(p_payload->>'fee_basis'), ''), 'page', p_url),
                jsonb_build_object('page', p_url, 'source', 'fee floor', 'state', 'quarantined'), '{}'::jsonb, 'pending',
                'international fee below the country floor (' || v_cur || ' ' || to_char(v_floor, 'FM999,999,999') || ' a year): ' || v_cur || ' ' || to_char((p_payload->>'fee_amount')::numeric, 'FM999,999,999.00'),
                'CF-CHG-20260915-247 NZ brief C3');
      end if;
      v_fees := 0;
    else
      v_fees := 1;
    end if;
  end if;
  return jsonb_build_object('course_id', p_course_id, 'links_applied', v_links, 'intakes_applied', v_intakes, 'english_applied', v_english, 'fees_applied', v_fees, 'fee_quarantined', v_floor is not null and v_floor <> -1, 'fee_quarantined_identity', v_ident is not null,
                            'link_held', nullif(btrim(p_payload->>'course_url'), '') is not null and v_links = 0);
end $$;


ALTER FUNCTION "security"."coverage_apply_course_v1"("p_course_id" "uuid", "p_source_id" "uuid", "p_evidence_id" "uuid", "p_url" "text", "p_hash" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_bind_tick_v1"("p_limit" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare r record; v jsonb:='[]'::jsonb;
begin
  for r in select provider_id from pipeline.coverage_provider_discovery
            where mapped_at is not null and (bound_at is null or bound_at<mapped_at)
              and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = coverage_provider_discovery.provider_id)  -- v2.15.237: paused while the provider is unpublished or archived
            order by mapped_at limit greatest(1,least(p_limit,50)) loop
    v:=v||jsonb_build_object('provider_id',r.provider_id,'result',security.coverage_bind_v2(r.provider_id));
  end loop;
  return v;
end $$;


ALTER FUNCTION "security"."coverage_bind_tick_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_bind_v1"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security'
    AS $$
declare v_bound int; v_amb int;
begin
  with c as (
    select co.id course_id, lower(co.course_code) code, security.coverage_text_tokens(co.canonical_title) tok
      from catalogue.courses co where co.provider_id=p_provider_id and co.lifecycle_status='active'),
  s as (
    select c.course_id, u.url,
           greatest(
             2.0*(select count(*) from unnest(c.tok) t where t=any(u.tokens))/nullif(cardinality(c.tok)+cardinality(u.tokens),0),
             2.0*(select count(*) from unnest(c.tok) t where t=any(u.title_tokens))/nullif(cardinality(c.tok)+cardinality(u.title_tokens),0)) sc0,
           c.code is not null and length(c.code)>=6 and (position(c.code in lower(u.url))>0 or position(c.code in lower(coalesce(u.title,'')))>0) by_code
      from c join pipeline.coverage_provider_urls u on u.provider_id=p_provider_id and (u.tokens && c.tok or u.title_tokens && c.tok
           or (c.code is not null and length(c.code)>=6 and (position(c.code in lower(u.url))>0 or position(c.code in lower(coalesce(u.title,'')))>0)))),
  s2 as (select course_id, url, case when by_code then 1.0 else coalesce(sc0,0) end sc, by_code from s),
  r as (select course_id, url, sc, by_code, row_number() over (partition by course_id order by sc desc, length(url)) rk,
               lead(sc) over (partition by course_id order by sc desc, length(url)) nxt from s2),
  best as (select course_id, url, sc, coalesce(nxt,0) nxt, by_code from r where rk=1 and sc>=0.6)
  insert into pipeline.coverage_course_pages(course_id,provider_id,url,score,runner_up,basis,status,bound_at,next_read_at)
  select course_id, p_provider_id, url, round(sc,3), round(nxt,3),
         case when by_code then 'cricos_code' else 'title_match' end,
         case when by_code or (sc>=0.8 and sc-nxt>=0.1) then 'bound' else 'ambiguous' end, now(), now()
    from best
  on conflict (course_id) do update set url=excluded.url, score=excluded.score, runner_up=excluded.runner_up, basis=excluded.basis,
         status=excluded.status, bound_at=now(), read_status=case when pipeline.coverage_course_pages.url is distinct from excluded.url then null else pipeline.coverage_course_pages.read_status end,
         next_read_at=case when pipeline.coverage_course_pages.url is distinct from excluded.url then now() else pipeline.coverage_course_pages.next_read_at end
   where not (pipeline.coverage_course_pages.status='bound' and excluded.status<>'bound');
  select count(*) filter (where status='bound'), count(*) filter (where status='ambiguous') into v_bound, v_amb from pipeline.coverage_course_pages where provider_id=p_provider_id;
  return jsonb_build_object('bound',v_bound,'ambiguous',v_amb);
end $$;


ALTER FUNCTION "security"."coverage_bind_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_bind_v2"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security'
    AS $_$
declare v_bound int; v_amb int;
begin
  drop table if exists _cb_c, _cb_u, _cb_s, _cb_best;
  create temp table _cb_c on commit drop as
    select co.id course_id, lower(co.course_code) code, security.coverage_text_tokens(co.canonical_title) tok
      from catalogue.courses co where co.provider_id=p_provider_id and co.lifecycle_status='active';
  create temp table _cb_u on commit drop as
    select url, title, tokens, title_tokens, cardinality(tokens) ns, cardinality(title_tokens) nt
      from pipeline.coverage_provider_urls where provider_id=p_provider_id
       and url !~* '/(inherent-requirements|entry-requirements|admission-requirements|english-requirements|fees?|tuition-fees?|scholarships?|apply|how-to-apply|applying|careers?|pathways?|credit|recognition-of-prior-learning|timetables?|news|events?|stories|blog|alumni|research|contact|faqs?)(/|$)';
  create temp table _cb_s on commit drop as
    with ct as (select course_id, cardinality(tok) nc, t from _cb_c, unnest(tok) t),
         ut as (select url, 's' k, ns n, t from _cb_u, unnest(tokens) t union all select url, 't', nt, t from _cb_u, unnest(title_tokens) t),
         m as (select ct.course_id, ut.url, ut.k, max(ct.nc) nc, max(ut.n) nu, count(*) hits from ct join ut using (t) group by 1,2,3)
    select course_id, url, max(2.0*hits/nullif(nc+nu,0)) sc, false by_code from m group by 1,2
    union all
    select c.course_id, u.url, 1.0, true from _cb_c c join _cb_u u
      on c.code is not null and length(c.code)>=6 and (position(c.code in lower(u.url))>0 or position(c.code in lower(coalesce(u.title,'')))>0);
  create temp table _cb_best on commit drop as
    with s as (select course_id, url, max(sc) sc, bool_or(by_code) by_code from _cb_s group by 1,2),
         rc as (select *, row_number() over (partition by course_id order by sc desc, length(url)) rk_c,
                          lead(sc) over (partition by course_id order by sc desc, length(url)) nxt_c,
                          row_number() over (partition by url order by sc desc) rk_u,
                          lead(sc) over (partition by url order by sc desc) nxt_u from s)
    select course_id, url, sc, coalesce(nxt_c,0) nxt, by_code,
           by_code or (sc>=0.8 and sc-coalesce(nxt_c,0)>=0.1 and rk_u=1 and sc-coalesce(nxt_u,0)>=0.1) or (sc>=0.999 and coalesce(nxt_c,0)<0.999 and rk_u=1 and coalesce(nxt_u,0)<0.999) mutual
      from rc where rk_c=1 and sc>=0.6;
  insert into pipeline.coverage_course_pages(course_id,provider_id,url,score,runner_up,basis,status,bound_at,next_read_at)
  select course_id, p_provider_id, url, round(sc,3), round(nxt,3), case when by_code then (case security.coverage_country(p_provider_id) when 'AU' then 'cricos_code' when 'NZ' then 'nzqa_code' else 'adapter_code' end) else 'title_match' end,
         case when mutual then 'bound' else 'ambiguous' end, now(), now()
    from _cb_best where not security.page_refused_v1(course_id, url)  -- S1: the site-map binder skips refused pages
  on conflict (course_id) do update set url=excluded.url, score=excluded.score, runner_up=excluded.runner_up, basis=excluded.basis,
         status=excluded.status, bound_at=now(),
         read_status=case when pipeline.coverage_course_pages.url is distinct from excluded.url then null else pipeline.coverage_course_pages.read_status end,
         next_read_at=case when pipeline.coverage_course_pages.url is distinct from excluded.url then now() else pipeline.coverage_course_pages.next_read_at end
   where (pipeline.coverage_course_pages.status not in ('mismatch') or pipeline.coverage_course_pages.url is distinct from excluded.url)
     and coalesce(pipeline.coverage_course_pages.basis,'') not in ('cricos_search','title_search','manual','ai_match')
     -- W31 (30 Oct 2026): a page the reader has proved with a code or manual proof is never re-scored on title tokens (unless refused)
     and not (pipeline.coverage_course_pages.read_status = 'read'
              and pipeline.coverage_course_pages.identity_basis in ('cricos_code','nzqa_code','adapter_code','manual')
              and not security.page_refused_v1(pipeline.coverage_course_pages.course_id, pipeline.coverage_course_pages.url));
  -- courses whose earlier binding no longer holds (page gone or no longer a mutual best) are released
  update pipeline.coverage_course_pages p set status='ambiguous'
   where p.provider_id=p_provider_id and p.status='bound' and coalesce(p.basis,'') in ('title_match','cricos_code','nzqa_code','adapter_code')  -- W31: rows this binder bound
     and not (p.read_status = 'read' and p.identity_basis in ('cricos_code','nzqa_code','adapter_code','manual') and not security.page_refused_v1(p.course_id, p.url))
     and not exists(select 1 from _cb_best b where b.course_id=p.course_id and b.url=p.url and b.mutual);
  update pipeline.coverage_provider_discovery set bound_at=now() where provider_id=p_provider_id;
  select count(*) filter (where status='bound'), count(*) filter (where status='ambiguous') into v_bound, v_amb from pipeline.coverage_course_pages where provider_id=p_provider_id;
  return jsonb_build_object('bound',v_bound,'ambiguous',v_amb);
end $_$;


ALTER FUNCTION "security"."coverage_bind_v2"("p_provider_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."coverage_bind_v2"("p_provider_id" "uuid") IS 'CF-247 site-map binder: binds a provider''s active courses to pages of its mapped site by course code or title tokens. W31 (30 Oct 2026): a page the reader has proved with a code or manual proof (identity_basis cricos_code, nzqa_code, adapter_code, manual) is never re-scored, demoted or released by a re-map unless refused; the release step only releases rows this binder bound.';



CREATE OR REPLACE FUNCTION "security"."coverage_completeness_state"("p_state" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select case p_state
    when 'admitted' then 'present'
    when 'not_on_page' then 'source_null'
    when 'missing_l1' then 'source_null'
    when 'candidate' then 'ambiguous'
    when 'awaiting_l3' then 'ambiguous'
    when 'in_review' then 'ambiguous'
    else 'not_yet_enriched' end
$$;


ALTER FUNCTION "security"."coverage_completeness_state"("p_state" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_country"("p_provider_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select k.iso_alpha2::text from catalogue.providers p join ref.countries k on k.id = p.country_id where p.id = p_provider_id
$$;


ALTER FUNCTION "security"."coverage_country"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_due_v1"("p_domain" "text", "p_limit" integer DEFAULT NULL::integer) RETURNS TABLE("provider_id" "uuid", "why" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 workstream C (mandate 15:52 §8 "incremental, driven by source or catalogue changes plus periodic broad checks"): the providers a
  -- coverage-reconcile run looks at, at most batch.coverage_reconcile: first those never reconciled or whose sources or records changed since they
  -- were last reconciled, then those with an open discrepancy not rechecked within coverage.discrepancy_recheck_hours (largest shortfall first),
  -- then those not looked at within coverage.broad_check_hours (oldest first). Read-only.
  with s as (select greatest(1, coalesce(p_limit, security.pipeline_num_v1('batch.coverage_reconcile', 300)::int)) lim,
                    make_interval(hours => security.pipeline_num_v1('coverage.discrepancy_recheck_hours', 6)::int) recheck,
                    make_interval(hours => security.pipeline_num_v1('coverage.broad_check_hours', 24)::int) broad),
  l as (select r.provider_id, r.computed_at, r.shortfall, cardinality(r.gaps) > 0 gapped from pipeline.coverage_provider_reconciliation r
         where r.domain = p_domain and r.disposition <> 'out_of_scope'),
  w as (select coalesce(min(l.computed_at), '-infinity') since from l),
  pop as (select x.provider_id from security.aer_eligible_v1() x where p_domain = 'aer'
          union
          -- AER: also every provider of a provider-level type in an AER country, so one the eligibility rule leaves out is still reconciled
          select p.id from catalogue.providers p join ref.countries k on k.id = p.country_id join ref.provider_types t on t.id = p.provider_type_id
           where p_domain = 'aer' and p.lifecycle_status = 'active' and p.publication_status = 'published'
             and k.iso_alpha2::text in (select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'aer.eligible_countries'), '[]'::jsonb)))
             and t.code in (select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'coverage.provider_level_types'), '[]'::jsonb)))
          union
          select p.id from catalogue.providers p join ref.countries k on k.id = p.country_id
           where p_domain = 'scholarship' and k.scholarship_ingestion_enabled and p.lifecycle_status = 'active' and p.publication_status = 'published'),
  -- change signals since the oldest reconciliation (indexed timestamps only; no full read of the records)
  ch as (select x.provider_id, max(x.at) at from (
           select c.provider_id, greatest(c.found_at, c.read_at, c.admitted_at) at from pipeline.scholarship_page_candidates c, w where p_domain = 'scholarship' and greatest(c.found_at, c.read_at, c.admitted_at) > w.since
           union all select x.provider_id, x.updated_at from scholarship.scholarships x, w where p_domain = 'scholarship' and x.updated_at > w.since
           union all select l.provider_id, l.read_at from pipeline.scholarship_listing_pages l, w where p_domain = 'scholarship' and l.read_at > w.since
           union all select r.provider_id, r.last_seen_at from scholarship.register_listings r, w where p_domain = 'scholarship' and r.provider_id is not null and r.last_seen_at > w.since
           union all select d.provider_id, greatest(d.updated_at, d.settled_at) from pipeline.scholarship_discovery_providers d, w where p_domain = 'scholarship' and greatest(d.updated_at, d.settled_at) > w.since
           union all select x.provider_id, x.updated_at from pipeline.entry_matrix_sources x, w where p_domain = 'aer' and x.updated_at > w.since
           union all select i.provider_id, i.recorded_at from pipeline.aer_source_inventory i, w where p_domain = 'aer' and i.recorded_at > w.since
           union all select m.provider_id, m.updated_at from catalogue.provider_entry_matrix m, w where p_domain = 'aer' and m.updated_at > w.since
           union all select c.provider_id, r.updated_at from catalogue.course_entry_requirements r join catalogue.courses c on c.id = r.course_id, w where p_domain = 'aer' and r.updated_at > w.since
           union all select a.provider_id, a.updated_at from pipeline.aer_provider_coverage a, w where p_domain = 'aer' and a.updated_at > w.since) x
         where x.provider_id is not null group by 1),
  c as (select pop.provider_id,
               case when l.provider_id is null then 0 when ch.at > l.computed_at then 1 when l.gapped and l.computed_at < now() - s.recheck then 2
                    when l.computed_at < now() - s.broad then 3 end grp,
               case when l.provider_id is null then 'new' when ch.at > l.computed_at then 'changed' when l.gapped and l.computed_at < now() - s.recheck then 'discrepancy'
                    when l.computed_at < now() - s.broad then 'broad' end why,
               coalesce(l.shortfall, 0) shortfall, l.computed_at
          from pop cross join s left join l on l.provider_id = pop.provider_id left join ch on ch.provider_id = pop.provider_id)
  select c.provider_id, c.why from c cross join s where c.grp is not null
   order by c.grp, c.shortfall desc, c.computed_at nulls first, c.provider_id limit (select lim from s)
$$;


ALTER FUNCTION "security"."coverage_due_v1"("p_domain" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."coverage_due_v1"("p_domain" "text", "p_limit" integer) IS 'CF-247 workstream C: the providers one coverage-reconcile run looks at (batch.coverage_reconcile): new or changed since last reconciled first, then open discrepancies due a recheck (coverage.discrepancy_recheck_hours, largest shortfall first), then the periodic broad check (coverage.broad_check_hours). Read-only.';



CREATE OR REPLACE FUNCTION "security"."coverage_fetch_area_v1"("p_action" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_rank int := security.current_role_rank(); v_country text := upper(coalesce(p_args->>'country', ''));
  v_type text := coalesce(nullif(p_args->>'scope_type', ''), 'country'); v_id uuid := nullif(p_args->>'scope_id', '')::uuid;
  v_q text := lower(nullif(btrim(coalesce(p_args->>'query', '')), '')); v_off int := greatest(coalesce((p_args->>'offset')::int, 0), 0);
  v_kind text; v_target uuid; v_label text; n_pin int := 0; n_new int := 0; n_site int := 0; n_map int := 0; n_search int := 0; n_read int := 0; v_items jsonb; v_total int;
begin
  if auth.uid() is null or v_rank < 4 then raise exception 'Pipeline Operator role or above required' using errcode = '42501'; end if;
  if p_action = 'options' then
    return jsonb_build_object('countries', coalesce((select jsonb_agg(jsonb_build_object('code', x.code, 'name', x.name, 'providers', x.pn, 'courses', x.cn) order by x.cn desc) from (
      select k.iso_alpha2::text code, k.name, count(distinct c.provider_id) pn, count(*) cn
        from catalogue.courses c join catalogue.providers p on p.id = c.provider_id join ref.countries k on k.id = p.country_id
       where c.lifecycle_status = 'active' group by 1, 2) x), '[]'::jsonb));
  end if;
  if v_country !~ '^[A-Z]{2}$' then raise exception 'choose a country'; end if;
  if v_type not in ('country','state','university') then raise exception 'choose a country, state or university'; end if;
  if v_type <> 'country' and v_id is null and p_action in ('preview','start') then raise exception 'choose a %', case v_type when 'state' then 'state' else 'university' end; end if;
  if p_action = 'scope_page' then
    if coalesce(p_args->>'kind', '') = 'state' then
      select coalesce(jsonb_agg(jsonb_build_object('value', q.id, 'label', q.name, 'meta', q.code) order by lower(q.name)), '[]'::jsonb), max(q.total)
        into v_items, v_total
        from (select sd.id, sd.name, sd.code, count(*) over () total from ref.subdivisions sd join ref.countries k on k.id = sd.country_id
               where k.iso_alpha2 = v_country and (v_q is null or lower(sd.name || ' ' || coalesce(sd.code, '')) like '%' || v_q || '%')
                 and exists (select 1 from catalogue.providers p where p.subdivision_id = sd.id
                              and exists (select 1 from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active'))
               order by lower(sd.name) limit 10 offset v_off) q; -- fixed: page size of the area list (display)
    else
      select coalesce(jsonb_agg(jsonb_build_object('value', q.id, 'label', q.name,
               'meta', q.courses || ' courses · ' || case when q.dstatus = 'mapped' then 'site found, ' || q.read_pages || ' pages read'
                                                          when q.dstatus = 'no_website' then 'no website found yet'
                                                          when q.dstatus = 'failed' then 'site map failed'
                                                          when q.dstatus = 'pending' then 'site waiting to be mapped'
                                                          else 'not in the sweep yet' end) order by lower(q.name)), '[]'::jsonb), max(q.total)
        into v_items, v_total
        from (select p.id, coalesce(p.display_name, p.canonical_name) name, count(*) over () total,
                     (select count(*) from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active') courses,
                     (select d.status from pipeline.coverage_provider_discovery d where d.provider_id = p.id) dstatus,
                     (select count(*) from pipeline.coverage_course_pages g where g.provider_id = p.id and g.read_status = 'read') read_pages
                from catalogue.providers p join security.coverage_scope_providers(v_country, case when nullif(p_args->>'state_id', '') is null then 'country' else 'state' end, nullif(p_args->>'state_id', '')::uuid) s on s.provider_id = p.id
               where v_q is null or lower(coalesce(p.display_name, '') || ' ' || p.canonical_name) like '%' || v_q || '%'
               order by lower(coalesce(p.display_name, p.canonical_name)) limit 10 offset v_off) q; -- fixed: page size of the area list (display)
    end if;
    return jsonb_build_object('items', v_items, 'total', coalesce(v_total, 0), 'offset', v_off, 'has_more', v_off + jsonb_array_length(v_items) < coalesce(v_total, 0));
  end if;
  if p_action = 'preview' then
    return security.coverage_scope_summary(v_country, v_type, v_id) || jsonb_build_object('country', v_country, 'scope_type', v_type, 'scope_id', v_id);
  end if;
  if p_action <> 'start' then raise exception 'unknown action'; end if;

  -- 1. first in the sweep: the same priority pins as Scheduled jobs › Priority
  v_kind := case v_type when 'university' then 'provider' else v_type end;
  v_target := case when v_type = 'country' then (select k.id from ref.countries k where k.iso_alpha2 = v_country) else v_id end;
  v_label := security.priority_pin_label(v_kind, v_target)->>'label';
  if v_label is null then raise exception 'not found'; end if;
  insert into pipeline.priority_pins(kind, target_id, sort, note, created_by)
  values (v_kind, v_target, coalesce((select min(sort) from pipeline.priority_pins), 1) - 1, 'Fetch an area', auth.uid())
  on conflict (kind, target_id) do update set sort = (select min(sort) from pipeline.priority_pins) - 1;
  get diagnostics n_pin = row_count;
  perform security.provider_priority_refresh_v1();
  -- 2. providers not yet in the sweep join it
  insert into pipeline.coverage_provider_discovery(provider_id, website, status, attempts, updated_at)
  select p.id, nullif(btrim(p.website), ''), case when nullif(btrim(p.website), '') is null then 'no_website' else 'pending' end, 0, now()
    from catalogue.providers p join security.coverage_scope_providers(v_country, v_type, v_id) s on s.provider_id = p.id
  on conflict (provider_id) do nothing;
  get diagnostics n_new = row_count;
  -- 3. site search again where the site was not found; failed site maps retried
  update pipeline.coverage_provider_discovery d set site_searched_at = null, leased_until = null, updated_at = now()
    from security.coverage_scope_providers(v_country, v_type, v_id) s
   where d.provider_id = s.provider_id and d.status = 'no_website' and d.site_searched_at is not null;
  get diagnostics n_site = row_count;
  update pipeline.coverage_provider_discovery d set status = 'pending', attempts = 0, next_due_at = null, last_error = null, leased_until = null, updated_at = now()
    from security.coverage_scope_providers(v_country, v_type, v_id) s
   where d.provider_id = s.provider_id and d.status = 'failed';
  get diagnostics n_map = row_count;
  -- 4. a page search for active courses with no page (a search that found nothing is repeated only after 7 days)
  insert into pipeline.course_link_search(course_id, provider_id, stage, state, queued_at)
  select c.id, c.provider_id, case when c.course_code ~ '^[0-9]{6}[0-9A-Z]$' then 'cricos' else 'title' end, 'queued', now()
    from catalogue.courses c join security.coverage_scope_providers(v_country, v_type, v_id) s on s.provider_id = c.provider_id
   where c.lifecycle_status = 'active'
     and exists (select 1 from pipeline.course_link_recipes r where r.provider_id = c.provider_id and r.active)
     and not exists (select 1 from pipeline.coverage_course_pages g where g.course_id = c.id and g.status <> 'mismatch')
  on conflict (course_id) do update set state = 'queued', stage = excluded.stage, queued_at = now(), sent_at = null, done_at = null
   where pipeline.course_link_search.state = 'none' and coalesce(pipeline.course_link_search.done_at, pipeline.course_link_search.queued_at) < now() - make_interval(days => security.pipeline_num_v1('coverage.link_search_retry_days', 7)::int);
  get diagnostics n_search = row_count;
  -- 5. found pages not yet read are read now
  update pipeline.coverage_course_pages g set next_read_at = now(), read_attempts = 0
    from security.coverage_scope_providers(v_country, v_type, v_id) s
   where g.provider_id = s.provider_id and g.status in ('bound','ambiguous') and g.read_status is distinct from 'read'
     and coalesce(g.leased_until, '-infinity') < now();
  get diagnostics n_read = row_count;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('fetch_area', 'start', v_label, p_args || jsonb_build_object('pinned', n_pin, 'joined', n_new, 'site_search_again', n_site, 'site_map_retry', n_map,
          'page_searches_queued', n_search, 'pages_to_read_now', n_read), auth.uid());
  return security.coverage_scope_summary(v_country, v_type, v_id) || jsonb_build_object('country', v_country, 'scope_type', v_type, 'scope_id', v_id, 'label', v_label,
    'started', jsonb_build_object('joined', n_new, 'site_search_again', n_site, 'site_map_retry', n_map, 'page_searches_queued', n_search, 'pages_to_read_now', n_read));
end $_$;


ALTER FUNCTION "security"."coverage_fetch_area_v1"("p_action" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_identity_allowed"("p_provider_id" "uuid", "p_basis" "text", "p_attr" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when p_basis in ('cricos_code', 'cricos_code_on_page', 'cricos_search') and not exists (select 1 from catalogue.providers p0 join ref.countries k0 on k0.id = p0.country_id where p0.id = p_provider_id and k0.iso_alpha2 = 'AU') then false -- 24 Oct 2026: a CRICOS proof exists only in Australia -- fixed: the register is Australian
            when p_basis in ('adapter_code', 'adapter_title')
                   -- 23 Oct 2026 (Platform Admin 12:40): in the countries of identity.adapter_title_countries an adapter title match counts
                   -- like an exact title for the fields its country list names, whatever the adapter admits
                   and not (p_basis = 'adapter_title' and p_attr is not null
                            and exists (select 1 from catalogue.providers p2 join ref.countries k2 on k2.id = p2.country_id
                                         where p2.id = p_provider_id and k2.iso_alpha2 in (select jsonb_array_elements_text(s.value) from pipeline.platform_toolset_settings s
                                                                                            where s.toolset_key = 'pipeline' and s.key = 'identity.adapter_title_countries')))
                   and not exists (select 1 from pipeline.uni_adapters u where u.provider_id = p_provider_id and u.enabled and u.admit and (p_attr is null or p_attr not in ('intakes', 'english', 'tuition') or (case p_attr when 'tuition' then 'fee' else p_attr end) = any (u.admit_fields))) then false
         else coalesce((
    select case when p_attr is null
                then exists (select 1 from jsonb_each(a.identities) e, jsonb_array_elements_text(e.value) b where b = p_basis)
                else coalesce(a.identities->p_attr ? p_basis, false) end
      from catalogue.providers p join pipeline.coverage_admission_countries a on a.country_id = p.country_id and a.active
     where p.id = p_provider_id), false) end
$$;


ALTER FUNCTION "security"."coverage_identity_allowed"("p_provider_id" "uuid", "p_basis" "text", "p_attr" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_investigation_verify_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_fp text; v_dom text; v_key text; v_prov uuid; v_gap text; v_ids uuid[]; m jsonb; v_left int;
begin
  select i.fingerprint, i.provider_ids into v_fp, v_ids from pipeline.integration_issues i where i.id = p_issue;
  if v_fp is null or v_fp not like 'coverage:%' then return jsonb_build_object('passed', false, 'measure', null, 'evidence', jsonb_build_object('error', 'not a coverage issue', 'issue', p_issue)); end if;
  v_dom := split_part(v_fp, ':', 2); v_key := split_part(v_fp, ':', 3); v_gap := nullif(split_part(v_fp, ':', 4), '');
  if v_gap is null then
    v_prov := v_key::uuid;
    if v_dom = 'scholarship' then select jsonb_build_object('gaps', to_jsonb(c.gaps), 'disposition', c.disposition, 'measures', c.measures) into m from security.scholarship_coverage_v1(array[v_prov]) c;
    else select jsonb_build_object('gaps', to_jsonb(c.gaps), 'disposition', c.disposition, 'measures', c.measures) into m from security.aer_coverage_v1(array[v_prov]) c; end if;
    return jsonb_build_object('passed', m is not null and jsonb_array_length(m->'gaps') = 0, 'measure', m,
                              'evidence', jsonb_build_object('issue', p_issue, 'provider_id', v_prov, 'in_population', m is not null, 'at', now()));
  end if;
  if v_dom = 'scholarship' then select count(*) into v_left from security.scholarship_coverage_v1(v_ids) c where true and v_gap = any (c.gaps);
  else select count(*) into v_left from security.aer_coverage_v1(v_ids) c where true and v_gap = any (c.gaps); end if;
  return jsonb_build_object('passed', v_left = 0, 'measure', jsonb_build_object('providers', cardinality(v_ids), 'still_with_gap', v_left),
                            'evidence', jsonb_build_object('issue', p_issue, 'gap', v_gap, 'country', v_key, 'at', now()));
end $$;


ALTER FUNCTION "security"."coverage_investigation_verify_v1"("p_issue" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."coverage_investigation_verify_v1"("p_issue" bigint) IS 'CF-247 workstream C: verify of remedy coverage_investigation: the provider (or every provider of a grouped issue) no longer has the coverage gap. Returns {passed, measure, evidence}. Read-only.';



CREATE OR REPLACE FUNCTION "security"."coverage_kv_v1"("p_key" "text") RETURNS TABLE("k" "text", "v" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- a pipeline list setting of 'name=value' entries as rows
  select btrim(split_part(x, '=', 1)), btrim(substr(x, strpos(x, '=') + 1))
    from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', p_key), '[]'::jsonb)) x where strpos(x, '=') > 1
$$;


ALTER FUNCTION "security"."coverage_kv_v1"("p_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."coverage_kv_v1"("p_key" "text") IS 'CF-247 workstream C: a pipeline list setting of name=value entries (coverage.sch_category_levels, coverage.sch_category_patterns, coverage.aer_pathways) as rows. Read-only.';



CREATE OR REPLACE FUNCTION "security"."coverage_norm_url"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $_$
  select rtrim(regexp_replace(regexp_replace(lower(coalesce(p,'')),'^https?://(www\.)?',''),'[?#].*$',''),'/')
$_$;


ALTER FUNCTION "security"."coverage_norm_url"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_page_refused_host_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_new_evidence boolean := false; v_chk jsonb;
begin
  -- 31 Oct 2026 (StudySearch SS-007): a course under a binding remediation hold keeps its binding until a person lifts the hold
  if tg_op = 'UPDATE' and new.status in ('bound', 'ambiguous') and security.course_held_v1(new.course_id)
     and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = new.course_id and k.field = 'official_url') then
    return old;
  end if;
  if new.status in ('bound', 'ambiguous') and security.refused_host(new.url)
     and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = new.course_id and k.field = 'official_url') then
    new.status := 'mismatch'; new.read_status := 'refused_host'; new.identity_basis := null; new.next_read_at := null;
  -- 21 Oct 2026 (Platform Admin "Go on with task 3"): never a course page (setting pages.not_course_patterns)
  elsif new.status in ('bound', 'ambiguous') and security.not_course_page_v1(new.url)
     and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = new.course_id and k.field = 'official_url') then
    new.status := 'mismatch'; new.read_status := 'not_course_page'; new.identity_basis := null; new.next_read_at := null;
  end if;
  -- 2 Nov 2026 (E16-1, Platform Admin 07:21): the page must not contradict this course (security.course_page_check_v1), whichever lane binds
  -- it. Checked when a page is bound or re-bound, when it is first read, or when its identity proof changes; a page set by hand is not.
  if new.status in ('bound', 'ambiguous') and coalesce(new.basis, '') <> 'manual' and security.pipeline_num_v1('binding.identity_check', 1) >= 1
     and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = new.course_id and k.field in ('official_url', 'course_url')) then
    if tg_op = 'INSERT' then
      v_new_evidence := true;
    else
      v_new_evidence := new.url is distinct from old.url or old.status not in ('bound', 'ambiguous') or new.identity_basis is distinct from old.identity_basis
                        or (new.read_status = 'read' and old.read_status is distinct from 'read');
    end if;
    -- a page already rejected or blocked for this course (pipeline.page_rejections, pipeline.course_page_blocks) is refused by every lane
    if v_new_evidence and security.page_refused_v1(new.course_id, new.url) then
      new.status := 'mismatch'; new.read_status := 'page_refused'; new.identity_basis := null; new.next_read_at := null;
      v_new_evidence := false;
    end if;
    if v_new_evidence then
      v_chk := security.course_page_check_v1(new.course_id, coalesce(nullif(new.candidates->>'final_url', ''), new.url),
                                             coalesce(nullif(new.candidates->>'page_title', ''), new.candidates->>'h1'), new.identity_basis);
      if v_chk->>'verdict' = 'refuse' then
        perform security.binding_refusal_route_v1(new.course_id, new.url, v_chk, coalesce(new.basis, 'unknown'), new.evidence_id);
        new.status := 'mismatch'; new.read_status := 'identity_refused'; new.identity_basis := null; new.next_read_at := null;
      end if;
    end if;
  end if;
  return new;
end $$;


ALTER FUNCTION "security"."coverage_page_refused_host_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_read_eligible_v1"() RETURNS TABLE("course_id" "uuid", "provider_id" "uuid", "due_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- SS-014 P2 (2 Nov 2026): the pages public.svc_coverage_read_next takes now, by its own conditions (hidden providers and leased pages left
  -- out), without its per-call size. due_at: when the page became due (for the stall age).
  select p.course_id, p.provider_id, coalesce(p.next_read_at, p.bound_at)
    from pipeline.coverage_course_pages p
   where p.status in ('bound','ambiguous') and coalesce(p.next_read_at,now())<=now() and coalesce(p.leased_until,'-infinity')<now() and p.read_attempts<3
     and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.provider_id)
$$;


ALTER FUNCTION "security"."coverage_read_eligible_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."coverage_read_eligible_v1"() IS 'SS-014 P2 (2 Nov 2026): the course pages the reader (svc_coverage_read_next) would take now; read by the health check''s coverage page reading rule and the watchdog''s course_page_read count';



CREATE OR REPLACE FUNCTION "security"."coverage_reconcile_v1"("p_domain" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_new_max int := greatest(0, security.pipeline_num_v1('coverage.investigations_per_run', 25)::int);
        v_issues boolean := security.scholarship_flag_v1('coverage.investigations_on', true);
        v_dom text; r record; v_fp text; v_new int := 0; v_upd int := 0; v_wait int := 0; v_grp int := 0; v_out jsonb := '{}'::jsonb;
        v_ledger int; v_gone int; v_ids uuid[]; v_why jsonb;
begin
  if not security.scholarship_flag_v1('coverage.reconcile_on', true) then return jsonb_build_object('on', false); end if;
  perform pg_advisory_xact_lock(hashtext('cf247:coverage_reconcile'));  -- fixed: one run at a time
  create temp table if not exists cov_now(provider_id uuid, country text, provider_name text, provider_type text, disposition text, measures jsonb,
                                          categories jsonb, gaps text[], shortfall int) on commit drop;
  create temp table if not exists cov_due(provider_id uuid, why text) on commit drop;
  for v_dom in select unnest(array['scholarship', 'aer']) loop
    continue when p_domain is not null and p_domain <> v_dom;
    truncate pg_temp.cov_now;
    truncate pg_temp.cov_due;
    insert into pg_temp.cov_due select * from security.coverage_due_v1(v_dom, null);
    select coalesce(array_agg(x.provider_id), '{}') into v_ids from pg_temp.cov_due x;
    select coalesce(jsonb_object_agg(x.why, x.n), '{}'::jsonb) into v_why from (select x.why, count(*) n from pg_temp.cov_due x group by 1) x;
    if cardinality(v_ids) > 0 then
      if v_dom = 'scholarship' then insert into pg_temp.cov_now select * from security.scholarship_coverage_v1(v_ids);
      else insert into pg_temp.cov_now select * from security.aer_coverage_v1(v_ids); end if;
    end if;
    insert into pipeline.coverage_provider_reconciliation as l(domain, provider_id, country, provider_name, provider_type, disposition, measures, categories, gaps, shortfall, computed_at)
    select v_dom, c.provider_id, c.country, c.provider_name, c.provider_type, c.disposition, c.measures, c.categories, c.gaps, c.shortfall, now() from pg_temp.cov_now c
    on conflict (domain, provider_id) do update set country = excluded.country, provider_name = excluded.provider_name, provider_type = excluded.provider_type,
           previous_disposition = case when l.disposition is distinct from excluded.disposition then l.disposition else l.previous_disposition end,
           disposition_since = case when l.disposition is distinct from excluded.disposition then now() else l.disposition_since end,
           disposition = excluded.disposition, measures = excluded.measures, categories = excluded.categories, gaps = excluded.gaps,
           shortfall = excluded.shortfall, computed_at = now();
    get diagnostics v_ledger = row_count;
    -- a provider looked at that has left the population is marked, never removed
    update pipeline.coverage_provider_reconciliation l set previous_disposition = l.disposition, disposition = 'out_of_scope', disposition_since = now(), computed_at = now()
     where l.domain = v_dom and l.provider_id = any (v_ids) and l.disposition <> 'out_of_scope' and not exists (select 1 from pg_temp.cov_now c where c.provider_id = l.provider_id);
    get diagnostics v_gone = row_count;
    v_new := 0; v_upd := 0; v_wait := 0; v_grp := 0;
    if v_issues then
      -- one investigation per provider: provider-level types, or any provider whose sources list what is missing
      for r in select c.* from pg_temp.cov_now c
                where cardinality(c.gaps) > 0 and ((c.measures->>'provider_level')::boolean or coalesce((c.measures->>'anchor')::int, 0) > 0)
                  and (v_dom = 'aer' or c.gaps && array['zero_scholarships', 'under_represented', 'not_searched']
                       or exists (select 1 from unnest(c.gaps) x where x like 'category_missing:%' or x like 'fields_incomplete:%'))
                order by c.shortfall desc, c.provider_id loop
        v_fp := 'coverage:' || v_dom || ':' || r.provider_id;
        if not exists (select 1 from pipeline.integration_issues i where i.fingerprint = v_fp) then
          if v_new >= v_new_max then v_wait := v_wait + 1; continue; end if;
          v_new := v_new + 1;
        else v_upd := v_upd + 1; end if;
        perform security.integration_issue_upsert_v1(jsonb_build_object(
          'fingerprint', v_fp,
          'title', left(case v_dom when 'scholarship' then 'Scholarship coverage' else 'Entry requirement coverage' end || ': ' || coalesce(r.provider_name, r.provider_id::text)
                   || ' (' || coalesce(r.country, '?') || ') ' || r.disposition || ': ' || array_to_string(r.gaps, ', '), 300),
          'layer', 'Coverage', 'subsystem', case v_dom when 'scholarship' then 'scholarships' else 'entry requirements' end,
          'provider_ids', jsonb_build_array(r.provider_id), 'country_codes', jsonb_build_array(r.country),
          'failure', case v_dom when 'scholarship' then
                       'Sources list ' || coalesce(r.measures->>'anchor', '0') || ' scholarship(s); the catalogue holds ' || coalesce(r.measures->>'admitted', '0')
                       || ' (' || coalesce(r.measures->>'published', '0') || ' published, ' || coalesce(r.measures->>'held', '0') || ' held), '
                       || coalesce(r.measures->>'candidates_pending', '0') || ' candidate(s) waiting, ' || coalesce(r.measures->>'candidates_rejected', '0') || ' rejected. Gaps: '
                       || array_to_string(r.gaps, ', ')
                     else coalesce(r.measures->>'sources', '0') || ' entry-requirement source(s), ' || coalesce(r.measures->>'matrix_active', '0') || ' active and '
                       || coalesce(r.measures->>'matrix_proposed', '0') || ' proposed matrix rows; ' || coalesce(r.measures->>'courses_req_any', '0') || ' of '
                       || coalesce(r.measures->>'courses_with_page', '0') || ' courses with a bound page have requirements; intakes on ' || coalesce(r.measures->>'courses_intake', '0')
                       || ' and deadlines on ' || coalesce(r.measures->>'courses_deadline', '0') || ' of ' || coalesce(r.measures->>'courses', '0') || ' active courses. Gaps: '
                       || array_to_string(r.gaps, ', ') end,
          'expected', 'Provider coverage reconciles with what its sources list; each gap has a recovery route or an evidenced reason (P0 mandates 3 Nov 2026 §5, §8).',
          'source', 'coverage-reconcile', 'validation_layer', 'V4', 'root_cause_class', 'data_drift',
          'severity', case when r.disposition = 'zero' and (r.measures->>'provider_level')::boolean then 'P1'
                           when 'outside_aer_population' = any (r.gaps) and (r.measures->>'provider_level')::boolean then 'P1' else 'P2' end,
          'workstream', 'A2',
          'evidence', jsonb_build_object('coverage', jsonb_build_object('domain', v_dom, 'disposition', r.disposition, 'gaps', to_jsonb(r.gaps), 'measures', r.measures,
                                         'categories', r.categories, 'shortfall', r.shortfall, 'at', now())),
          'correlation_key', 'coverage:' || v_dom || ':' || coalesce(r.country, '?'),
          'remedy_code', 'coverage_investigation',
          'diagnosis', jsonb_build_object('root_cause', case v_dom when 'scholarship' then case when 'zero_scholarships' = any (r.gaps) then 'sch_zero_scholarships'
                                                                                              when 'under_represented' = any (r.gaps) then 'sch_under_represented'
                                                                                              when exists (select 1 from unnest(r.gaps) x where x like 'category_missing:%') then 'sch_category_missing'
                                                                                              when 'not_searched' = any (r.gaps) then 'sch_provider_not_searched'
                                                                                              else 'sch_fields_incomplete' end
                                                                   else case when 'outside_aer_population' = any (r.gaps) then 'aer_provider_outside_population'
                                                                             when 'no_source' = any (r.gaps) then 'aer_source_missing'
                                                                             when r.gaps <@ array['intake_gap', 'deadline_gap'] then 'aer_intake_deadline_gap'
                                                                             else 'aer_dimension_gap' end end,
                                          'confidence', 0.9, 'method', 'source-listing reconciliation (security.' || v_dom || '_coverage_v1)', 'at', now(),
                                          'evidence', jsonb_build_array(r.measures))), 'coverage-reconcile');
        update pipeline.coverage_provider_reconciliation l set issue_fingerprint = v_fp where l.domain = v_dom and l.provider_id = r.provider_id and l.issue_fingerprint is distinct from v_fp;
      end loop;
      -- the long tail, grouped per country and gap (from the ledger, so a partial run does not shrink the group)
      for r in select l.country, g.gap, array_agg(l.provider_id order by l.shortfall desc, l.provider_id) ids, count(*) n
                 from pipeline.coverage_provider_reconciliation l cross join lateral unnest(l.gaps) g(gap)
                where l.domain = v_dom and l.disposition <> 'out_of_scope' and not coalesce((l.measures->>'provider_level')::boolean, false)
                  and (coalesce((l.measures->>'anchor')::int, 0) = 0 and g.gap in ('no_source', 'intake_gap', 'deadline_gap', 'course_level_gap', 'domestic_only_source')
                       or g.gap = 'admission_policy')
                  and exists (select 1 from pg_temp.cov_now c where c.country is not distinct from l.country and g.gap = any (c.gaps))
                group by 1, 2 loop
        v_grp := v_grp + 1;
        perform security.integration_issue_upsert_v1(jsonb_build_object(
          'fingerprint', 'coverage:' || v_dom || ':' || coalesce(r.country, '?') || ':' || r.gap,
          'title', left(case v_dom when 'scholarship' then 'Scholarship coverage' else 'Entry requirement coverage' end || ': ' || r.n || ' other ' || coalesce(r.country, '?')
                   || ' providers with ' || r.gap, 300),
          'layer', 'Coverage', 'subsystem', case v_dom when 'scholarship' then 'scholarships' else 'entry requirements' end,
          'provider_ids', to_jsonb(r.ids), 'country_codes', jsonb_build_array(r.country),
          'failure', r.n || ' providers outside the provider-level types share the gap ' || r.gap || ' (grouped, not one issue each).',
          'expected', 'Each provider has a recovery route or an evidenced reason (P0 mandate 3 Nov 2026 §5; mandate 2 Nov 2026 §9 "one consolidated engineering issue").',
          'source', 'coverage-reconcile', 'validation_layer', 'V4', 'root_cause_class', 'data_drift', 'severity', 'P2', 'workstream', 'A2',
          'evidence', jsonb_build_object('coverage', jsonb_build_object('domain', v_dom, 'gap', r.gap, 'providers', r.n, 'at', now())),
          'correlation_key', 'coverage:' || v_dom || ':' || coalesce(r.country, '?'), 'remedy_code', 'coverage_investigation'), 'coverage-reconcile');
      end loop;
    end if;
    v_out := v_out || jsonb_build_object(v_dom, jsonb_build_object('looked_at', cardinality(v_ids), 'why', v_why, 'ledger_rows', v_ledger, 'out_of_scope', v_gone,
      'dispositions', (select coalesce(jsonb_object_agg(x.disposition, x.n), '{}'::jsonb) from (select c.disposition, count(*) n from pg_temp.cov_now c group by 1) x),
      'investigations_new', v_new, 'investigations_updated', v_upd, 'investigations_waiting', v_wait, 'groups', v_grp));
  end loop;
  return jsonb_build_object('on', true, 'issues_on', v_issues, 'at', now()) || v_out;
end $$;


ALTER FUNCTION "security"."coverage_reconcile_v1"("p_domain" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."coverage_reconcile_v1"("p_domain" "text") IS 'CF-247 workstream C (P0 mandates 3 Nov 2026 §5/§12 and §8): job coverage-reconcile. Incremental: the providers security.coverage_due_v1 names (changed, discrepant, periodic broad check; batch.coverage_reconcile a run). Keeps the provider coverage ledger (pipeline.coverage_provider_reconciliation) for scholarships and AER and opens or updates one provider-level coverage investigation per provider and domain (coverage.investigations_on, coverage.investigations_per_run). Read-only over the catalogue; no read, spend, admission or publication.';



CREATE OR REPLACE FUNCTION "security"."coverage_scope_providers"("p_country" "text", "p_type" "text", "p_id" "uuid") RETURNS TABLE("provider_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select p.id from catalogue.providers p join ref.countries k on k.id = p.country_id
   where k.iso_alpha2 = upper(p_country)
     and exists (select 1 from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active')
     and case coalesce(p_type, 'country')
           when 'country' then true
           when 'university' then p.id = p_id
           when 'state' then p.subdivision_id = p_id or exists (
             select 1 from catalogue.courses c join catalogue.course_campuses cc on cc.course_id = c.id
               join catalogue.campuses cam on cam.id = cc.campus_id
              where c.provider_id = p.id and c.lifecycle_status = 'active' and cam.subdivision_id = p_id)
           else false end
$$;


ALTER FUNCTION "security"."coverage_scope_providers"("p_country" "text", "p_type" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."coverage_scope_summary"("p_country" "text", "p_type" "text", "p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with sp as (select provider_id from security.coverage_scope_providers(p_country, p_type, p_id)),
  co as (select c.id, c.provider_id from catalogue.courses c join sp on sp.provider_id = c.provider_id where c.lifecycle_status = 'active'),
  di as (select d.* from pipeline.coverage_provider_discovery d join sp on sp.provider_id = d.provider_id),
  pg as (select g.* from pipeline.coverage_course_pages g join co on co.id = g.course_id),
  cv as (select a.attribute, count(*) filter (where a.state = 'admitted') n from pipeline.course_attribute_coverage a join co on co.id = a.course_id
          where a.attribute in ('official_url','english','intakes','provider_tuition') group by 1)
  select jsonb_build_object(
    'providers', (select count(*) from sp),
    'courses', (select count(*) from co),
    'sites', jsonb_build_object(
       'known', (select count(*) from di where di.status in ('mapped','pending') and di.website is not null),
       'mapped', (select count(*) from di where di.status = 'mapped'),
       'not_found', (select count(*) from di where di.status = 'no_website' and di.site_searched_at is not null),
       'to_search', (select count(*) from di where di.status = 'no_website' and di.site_searched_at is null),
       'failed', (select count(*) from di where di.status = 'failed'),
       'not_queued', (select count(*) from sp where not exists (select 1 from di where di.provider_id = sp.provider_id))),
    'pages', jsonb_build_object(
       'found', (select count(*) from pg where pg.status in ('bound','ambiguous')),
       'read', (select count(*) from pg where pg.read_status = 'read'),
       'to_read', (select count(*) from pg where pg.status in ('bound','ambiguous') and pg.read_status is distinct from 'read'),
       'not_this_course', (select count(*) from pg where pg.status = 'mismatch'),
       'no_page', (select count(*) from co where not exists (select 1 from pg where pg.course_id = co.id))),
    'searches_waiting', (select count(*) from pipeline.course_link_search s join co on co.id = s.course_id where s.state in ('queued','sent')),
    'facts', coalesce((select jsonb_object_agg(attribute, n) from cv), '{}'::jsonb),
    'facts_built_at', (select max(computed_at) from pipeline.course_attribute_coverage),
    'first_in_sweep', exists (select 1 from pipeline.priority_pins x where x.kind = case coalesce(p_type,'country') when 'university' then 'provider' else coalesce(p_type,'country') end
                               and x.target_id = case when coalesce(p_type,'country') = 'country' then (select k.id from ref.countries k where k.iso_alpha2 = upper(p_country)) else p_id end))
$$;


