CREATE OR REPLACE FUNCTION "security"."cricos_identity_conflict_v1"("p_course" "uuid", "p_url" "text", "p_text_sha" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with me as (select c.id, c.provider_id, c.course_code from catalogue.courses c where c.id = p_course),
       o as (select g.course_id, c2.course_code code,
                    case when security.layer4_url_key_v1(g.url) = security.layer4_url_key_v1(p_url) then 'same address' else 'same page text' end how
               from me join pipeline.coverage_course_pages g on g.provider_id = me.provider_id
               join catalogue.courses c2 on c2.id = g.course_id
              where g.course_id <> me.id and g.identity_basis = 'cricos_code' and g.status in ('bound', 'ambiguous') and c2.lifecycle_status = 'active'
                and c2.course_code is distinct from me.course_code
                and (security.layer4_url_key_v1(g.url) = security.layer4_url_key_v1(p_url)
                     or (nullif(p_text_sha, '') is not null and g.candidates->>'text_sha' = p_text_sha)))
  select jsonb_build_object('conflict', exists (select 1 from o),
                            'courses', coalesce((select jsonb_agg(jsonb_build_object('course_id', o.course_id, 'code', o.code, 'how', o.how) order by o.code) from o), '[]'::jsonb))
$$;


ALTER FUNCTION "security"."cricos_identity_conflict_v1"("p_course" "uuid", "p_url" "text", "p_text_sha" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."cricos_identity_guard_evaluate_v1"("p_provider" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with tb as (select x from unnest(security.pipeline_list_v1('binding.title_identity_bases', '[]'::jsonb)) x),
  g as (select g.course_id, g.provider_id, g.url, g.basis, g.identity_basis ib, g.evidence_id, g.candidates->>'text_sha' sha, security.layer4_url_key_v1(g.url) k,
               c.course_code, c.lifecycle_status life
          from pipeline.coverage_course_pages g join catalogue.courses c on c.id = g.course_id
         where g.status in ('bound', 'ambiguous') and (p_provider is null or g.provider_id = p_provider)),
  proved as (select provider_id, k, sha, course_id, course_code from g where ib = 'cricos_code' and life = 'active'),
  cand as (select g.* from g where g.life = 'active' and g.ib in (select x from tb) and coalesce(g.basis, '') <> 'manual'
             and not exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = g.course_id and l.field in ('official_url', 'course_url'))),
  -- two equality joins (an address join and a page-text join), not one join on either: the planner can hash each
  pair as (select c.course_id, p.course_code other_code, p.course_id other_course, 'same address' how, 1 o
             from cand c join proved p on p.provider_id = c.provider_id and p.k = c.k
            where p.course_id <> c.course_id and p.course_code is distinct from c.course_code
           union all
           select c.course_id, p.course_code, p.course_id, 'same page text', 2
             from cand c join proved p on p.provider_id = c.provider_id and p.sha = c.sha
            where c.sha is not null and p.course_id <> c.course_id and p.course_code is distinct from c.course_code),
  hit as (select distinct on (c.course_id) c.*, x.other_code, x.other_course, x.how
            from pair x join cand c using (course_id)
           order by c.course_id, x.o, x.other_code),
  shared as (select g.k from g group by g.k having count(distinct g.course_id) > 1),
  sl as (select g.*, (select e.metadata->>'course_id' from pipeline.evidence_artifacts e where e.id = g.evidence_id) ev_course from g join shared using (k))
  select jsonb_build_object(
    'switch_on', security.pipeline_num_v1('binding.cricos_identity_guard_on', 0) >= 1,
    'provider_id', p_provider,
    'would_refuse', jsonb_build_object('bindings', (select count(*) from hit), 'addresses', (select count(distinct k) from hit),
                                      'providers', (select count(distinct provider_id) from hit),
                                      'by_how', (select coalesce(jsonb_object_agg(how, n), '{}'::jsonb) from (select how, count(*) n from hit group by 1) z),
                                      'by_identity_basis', (select coalesce(jsonb_object_agg(ib, n), '{}'::jsonb) from (select ib, count(*) n from hit group by 1) z),
                                      'by_provider', (select coalesce(jsonb_agg(jsonb_build_object('provider_id', provider_id, 'name', (select coalesce(p.display_name, p.canonical_name) from catalogue.providers p where p.id = z.provider_id), 'bindings', n) order by n desc), '[]'::jsonb)
                                                        from (select provider_id, count(*) n from hit group by 1) z),
                                      'sample', (select coalesce(jsonb_agg(jsonb_build_object('course_id', course_id, 'code', course_code, 'url', url, 'identity_basis', ib,
                                                                                               'page_proves', other_code, 'other_course_id', other_course, 'how', how) order by course_code), '[]'::jsonb)
                                                   from (select * from hit order by course_code limit security.pipeline_num_v1('binding.cricos_guard_sample', 50)::int) s)),
    'shared_pages', jsonb_build_object('links', (select count(*) from sl), 'addresses', (select count(distinct k) from sl),
                                       'copies_read_for_another_course', (select count(*) from sl where ev_course is not null and ev_course <> course_id::text)),
    'note', 'Read only. The guard acts on a binding when it is bound, re-bound or its identity changes; bindings that do not change are not re-checked by it.')
$$;


ALTER FUNCTION "security"."cricos_identity_guard_evaluate_v1"("p_provider" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."cricos_identity_guard_trg_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_c jsonb; v_codes text;
begin
  if security.pipeline_num_v1('binding.cricos_identity_guard_on', 0) < 1 then return new; end if;
  if new.status not in ('bound', 'ambiguous') or coalesce(new.basis, '') = 'manual'
     or not (coalesce(new.identity_basis, '') = any (security.pipeline_list_v1('binding.title_identity_bases', '[]'::jsonb))) then return new; end if;
  if tg_op = 'UPDATE' and new.url is not distinct from old.url and new.status is not distinct from old.status and new.identity_basis is not distinct from old.identity_basis then
    return new;
  end if;
  if exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = new.course_id and k.field in ('official_url', 'course_url')) then return new; end if;
  v_c := security.cricos_identity_conflict_v1(new.course_id, coalesce(nullif(new.candidates->>'final_url', ''), new.url), new.candidates->>'text_sha');
  if not coalesce((v_c->>'conflict')::boolean, false) then return new; end if;
  select string_agg(x->>'code', ', ') into v_codes from jsonb_array_elements(v_c->'courses') x;
  perform security.binding_refusal_route_v1(new.course_id, new.url,
            jsonb_build_object('verdict', 'refuse', 'rule', 'cricos_identity',
                               'reason', 'the page states the CRICOS code of another course (' || v_codes || '), and this course matched it by title only', 'checks', v_c),
            coalesce(new.basis, 'unknown'), new.evidence_id);
  new.status := 'mismatch'; new.read_status := 'cricos_identity_refused'; new.identity_basis := null; new.next_read_at := null;
  return new;
end $$;


ALTER FUNCTION "security"."cricos_identity_guard_trg_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."cricos_peo_fire_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
begin
  if not exists (select 1 from catalogue.providers p
                  where p.lifecycle_status = 'active'
                    and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id)
                    and exists (select 1 from catalogue.provider_registrations r where r.provider_id = p.id and lower(r.registration_scheme) = 'cricos' and r.registration_code ~* '^[0-9]{5}[A-Z]$')
                    and exists (select 1 from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active')
                    and not exists (select 1 from pipeline.provider_contact_checks k where k.provider_id = p.id and k.kind = 'regulatory_peo'
                                      and (k.checked_at > now() - make_interval(days => security.pipeline_num_v1('recheck.cricos_contact_days', 180)::int) and k.outcome <> 'budget'
                                           or k.checked_at > now() - interval '1 hour'))) then  -- fixed: a check in flight (as the picker)
    return 0;
  end if;
  perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'cricos_peo', 'limit', security.pipeline_num_v1('batch.cricos_peo', 2)::int));
  return 1;
end $_$;


ALTER FUNCTION "security"."cricos_peo_fire_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."cron_field_match_v1"("p_field" "text", "p_value" integer, "p_min" integer, "p_max" integer) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v_part text; v_range text; v_step int; v_lo int; v_hi int;
begin
  foreach v_part in array string_to_array(p_field, ',') loop
    v_step := 1; v_range := v_part;
    if position('/' in v_part) > 0 then v_range := split_part(v_part, '/', 1); v_step := split_part(v_part, '/', 2)::int; end if;
    if v_range = '*' then v_lo := p_min; v_hi := p_max;
    elsif position('-' in v_range) > 0 then v_lo := split_part(v_range, '-', 1)::int; v_hi := split_part(v_range, '-', 2)::int;
    else v_lo := v_range::int; v_hi := case when position('/' in v_part) > 0 then p_max else v_lo end;
    end if;
    if p_max = 6 and v_hi = 7 then  -- fixed: cron day of week 7 is Sunday
      if p_value = 0 and (7 - v_lo) % v_step = 0 and v_lo <= 7 then return true; end if;
    end if;
    if p_value between v_lo and v_hi and (p_value - v_lo) % v_step = 0 then return true; end if;
  end loop;
  return false;
end $$;


ALTER FUNCTION "security"."cron_field_match_v1"("p_field" "text", "p_value" integer, "p_min" integer, "p_max" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."cron_field_matches_v1"("p_field" "text", "p_value" integer, "p_min" integer, "p_max" integer) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v_part text; v_range text; v_step int; v_a int; v_b int;
begin
  foreach v_part in array string_to_array(p_field, ',') loop
    v_range := split_part(v_part, '/', 1);
    v_step := coalesce(nullif(split_part(v_part, '/', 2), '')::int, 1);
    if v_range = '*' then v_a := p_min; v_b := p_max;
    elsif v_range like '%-%' then v_a := split_part(v_range, '-', 1)::int; v_b := split_part(v_range, '-', 2)::int;
    else v_a := v_range::int; v_b := case when v_part like '%/%' then p_max else v_a end;
    end if;
    if p_value between v_a and v_b and (p_value - v_a) % v_step = 0 then return true; end if;
  end loop;
  return false;
end $$;


ALTER FUNCTION "security"."cron_field_matches_v1"("p_field" "text", "p_value" integer, "p_min" integer, "p_max" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."cron_matches_v1"("p_schedule" "text", "p_at" timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare v_f text[] := regexp_split_to_array(btrim(p_schedule), '\s+'); v_t timestamp := p_at at time zone 'UTC'; v_dow int; v_dom_ok boolean; v_dow_ok boolean;
begin
  if coalesce(array_length(v_f, 1), 0) <> 5 then return false; end if;  -- an interval schedule ('30 seconds') is not a cron expression
  if not security.cron_field_matches_v1(v_f[1], extract(minute from v_t)::int, 0, 59)
     or not security.cron_field_matches_v1(v_f[2], extract(hour from v_t)::int, 0, 23)
     or not security.cron_field_matches_v1(v_f[4], extract(month from v_t)::int, 1, 12) then
    return false;
  end if;
  v_dow := extract(dow from v_t)::int;
  v_dom_ok := security.cron_field_matches_v1(v_f[3], extract(day from v_t)::int, 1, 31);
  v_dow_ok := security.cron_field_matches_v1(v_f[5], v_dow, 0, 7) or (v_dow = 0 and security.cron_field_matches_v1(v_f[5], 7, 0, 7));
  -- cron: when both day of month and day of week are restricted, either may match
  if v_f[3] <> '*' and v_f[5] <> '*' then return v_dom_ok or v_dow_ok; end if;
  return v_dom_ok and v_dow_ok;
end $$;


ALTER FUNCTION "security"."cron_matches_v1"("p_schedule" "text", "p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."cron_next_run_v1"("p_schedule" "text", "p_after" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare f text[] := regexp_split_to_array(btrim(coalesce(p_schedule, '')), '\s+'); v_t timestamp; v_end timestamp; v_dom_any boolean; v_dow_any boolean; v_dom boolean; v_dow boolean;
begin
  if cardinality(f) <> 5 then return null; end if;
  v_t := date_trunc('minute', p_after at time zone 'UTC') + interval '1 minute';  -- fixed: the next whole minute
  v_end := v_t + make_interval(hours => security.pipeline_num_v1('frv.next_run_search_hours', 48)::int);
  v_dom_any := f[3] = '*'; v_dow_any := f[5] = '*';
  while v_t < v_end loop
    if security.cron_field_match_v1(f[4], extract(month from v_t)::int, 1, 12) then
      v_dom := security.cron_field_match_v1(f[3], extract(day from v_t)::int, 1, 31);
      v_dow := security.cron_field_match_v1(f[5], extract(dow from v_t)::int, 0, 6);
      if (case when v_dom_any or v_dow_any then v_dom and v_dow else v_dom or v_dow end)
         and security.cron_field_match_v1(f[2], extract(hour from v_t)::int, 0, 23) then
        if security.cron_field_match_v1(f[1], extract(minute from v_t)::int, 0, 59) then return v_t at time zone 'UTC'; end if;
        v_t := v_t + interval '1 minute';  -- fixed: minute steps within a matching hour
      else
        v_t := date_trunc('hour', v_t) + interval '1 hour';  -- fixed: skip a non-matching hour
      end if;
    else
      v_t := date_trunc('hour', v_t) + interval '1 hour';  -- fixed: skip a non-matching month hour by hour (bounded by the search window)
    end if;
  end loop;
  return null;
end $$;


ALTER FUNCTION "security"."cron_next_run_v1"("p_schedule" "text", "p_after" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."cron_run_outcome_v1"("p_jobname" "text", "p_status" "text", "p_message" "text", "p_start" timestamp with time zone) RETURNS "text"
    LANGUAGE "sql" STABLE
    AS $$
  select case when p_status = 'failed' and p_message = 'job canceled'
               and exists (select 1 from pipeline.enrichment_flag_events e join pipeline.enrichment_flags f on f.id = e.flag_id
                            where f.entity = 'job' and f.entity_key = p_jobname and e.action in ('raised', 're_raised')
                              and e.at between p_start - interval '30 seconds' and p_start + interval '5 seconds')  -- fixed: the pause and the cancelled start fall within seconds
              then 'paused' else p_status end
$$;


ALTER FUNCTION "security"."cron_run_outcome_v1"("p_jobname" "text", "p_status" "text", "p_message" "text", "p_start" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."cron_run_outcome_v1"("p_jobname" "text", "p_status" "text", "p_message" "text", "p_start" timestamp with time zone) IS 'StudySearch SS-004 (1 Nov 2026): the outcome of a scheduled run for health and target T1: a run pg_cron reports as "job canceled" within seconds of the flag unit pausing that job for idleness is paused, not failed; every other status is returned unchanged. Inlined (no settings), schema-qualified.';



CREATE OR REPLACE FUNCTION "security"."current_role_rank"() RETURNS smallint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'security', 'auth'
    AS $$
select coalesce(max(r.rank),0)::smallint
from security.user_roles ur join security.roles r on r.code=ur.role_code
where ur.user_id=auth.uid() and (ur.expires_at is null or ur.expires_at>now()) and r.status='active'
$$;


ALTER FUNCTION "security"."current_role_rank"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_delivery_aer_progress_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_day timestamptz := now() - interval '24 hours';  -- fixed: the screen's 24-hour window
        v_m jsonb;
begin
  v_m := security.aer_discovery_metrics_v1();
  return jsonb_build_object(
    'campaign', (v_m - 'spare' - 'by_outcome') || jsonb_build_object('spare_room', v_m->'spare'->'room', 'spare_why', v_m->'spare'->>'why',
                  'state', (select c.state from pipeline.aer_discovery_campaigns c order by c.id desc limit 1),
                  'credit_cap', security.pipeline_num_v1('aer.discovery_campaign_credit_cap', 10000)),
    'machine', jsonb_build_object(
      'course', jsonb_build_object('mode', security.pipeline_num_v1('aer.machine_mode', 0),
                  'admitted', (select count(*) from pipeline.aer_machine_admissions a where a.mode = 'admit' and a.outcome = 'admitted' and a.withdrawn_at is null),
                  'admitted_24h', (select count(*) from pipeline.aer_machine_admissions a where a.mode = 'admit' and a.outcome = 'admitted' and a.withdrawn_at is null and a.created_at >= v_day)),
      'matrix', jsonb_build_object('mode', security.pipeline_num_v1('aer.matrix_machine_mode', 0),
                  'admitted', (select count(*) from pipeline.aer_matrix_machine_admissions a where a.mode = 'admit' and a.outcome = 'admitted' and a.withdrawn_at is null),
                  'admitted_24h', (select count(*) from pipeline.aer_matrix_machine_admissions a where a.mode = 'admit' and a.outcome = 'admitted' and a.withdrawn_at is null and a.created_at >= v_day),
                  'providers', (select count(distinct a.provider_id) from pipeline.aer_matrix_machine_admissions a where a.mode = 'admit' and a.outcome = 'admitted' and a.withdrawn_at is null),
                  'shadow', (select count(*) from pipeline.aer_matrix_machine_admissions a where a.mode = 'shadow'),
                  'shadow_would_admit', (select count(*) from pipeline.aer_matrix_machine_admissions a where a.mode = 'shadow' and a.outcome = 'would_admit'),
                  'validation', (select jsonb_build_object('passed', v.passed, 'at', v.validated_at) from pipeline.aer_matrix_machine_validations v order by v.validated_at desc limit 1),
                  'declines', (select coalesce(jsonb_agg(jsonb_build_object('reason', z.r, 'n', z.n) order by z.n desc), '[]'::jsonb)
                                 from (select left(a.reason, 120) r, count(*) n from pipeline.aer_matrix_machine_admissions a where a.outcome = 'declined' and a.created_at >= v_day group by 1 order by 2 desc limit 6) z))),
    'corrected_reads', jsonb_build_object('open', (select count(*) from pipeline.aer_read_supersessions s where s.state = 'requested'),
                  'refused_24h', (select count(*) from pipeline.aer_read_supersessions s where s.state = 'refused' and s.closed_at >= v_day),
                  'replaced_24h', (select count(*) from pipeline.aer_read_supersessions s where s.state = 'superseded' and s.closed_at >= v_day)),
    'gains_24h', jsonb_build_object('course_rows', (select count(*) from catalogue.course_entry_requirements r where r.status = 'active' and r.updated_at >= v_day),
                  'matrix_rows', (select count(*) from catalogue.provider_entry_matrix r where r.status = 'active' and r.updated_at >= v_day),
                  'qualification_rows', (select count(*) from catalogue.provider_qualification_requirements r where r.status = 'active' and r.updated_at >= v_day),
                  'providers_with_new_matrix', (select count(distinct r.provider_id) from catalogue.provider_entry_matrix r where r.status = 'active' and r.updated_at >= v_day)),
    'failures', jsonb_build_object('sources_not_fetched', (select count(*) from pipeline.entry_matrix_sources s where s.status in ('failed', 'robots_disallowed')),
                  'sources_blocked', (select coalesce(jsonb_object_agg(z.e, z.n), '{}'::jsonb) from (select coalesce(s.error, s.status) e, count(*) n from pipeline.entry_matrix_sources s where s.status in ('failed', 'robots_disallowed') group by 1) z),
                  'reads_held_unreadable', (select count(*) from pipeline.entry_matrix_runs r where r.state = 'failed')));
exception when others then
  return jsonb_build_object('known', false, 'reason', left(sqlerrm, 200));
end $$;


ALTER FUNCTION "security"."data_delivery_aer_progress_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."data_delivery_aer_progress_v1"() IS 'CF-247 F-AER.04 (delivery item 6): AER discovery campaign, machine admission, corrected reads, 24-hour gains and failures, for the Data Delivery screen (public.admin_aer_delivery_progress). Read only.';



CREATE OR REPLACE FUNCTION "security"."data_delivery_aer_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_max int := security.pipeline_num_v1('aer.schedule_layer4_max', 600)::int; -- derived: the limit the scheduled reading tests (same setting and default)
begin
  return (
  with pc as (select * from pipeline.aer_provider_coverage where eligible),
  cov as (select jsonb_build_object(
            'eligible', count(*), 'with_source', count(*) filter (where sources > 0), 'source_read', count(*) filter (where sources_read > 0),
            'with_active_rows', count(*) filter (where matrix_active > 0 or course_req_active > 0),
            'waiting_for_layer4', count(*) filter (where course_req_proposed > 0 or coalesce((layer4->>'matrix_pending')::int, 0) > 0 or coalesce((layer4->>'course_awaiting_review')::int, 0) > 0),
            'active_course_rows', coalesce(sum(course_req_active), 0), 'active_matrix_rows', coalesce(sum(matrix_active), 0),
            'proposed_course_rows', coalesce(sum(course_req_proposed), 0), 'counted_at', max(updated_at)) j from pc),
  bycc as (select coalesce(jsonb_agg(jsonb_build_object('cc', x.country, 'eligible', x.n, 'with_active_rows', x.a, 'with_source', x.s) order by x.country), '[]'::jsonb) j
             from (select country, count(*) n, count(*) filter (where matrix_active > 0 or course_req_active > 0) a, count(*) filter (where sources > 0) s from pc group by 1) x),
  disp as (select coalesce(jsonb_object_agg(x.disposition, x.n), '{}'::jsonb) j from (select disposition, count(*) n from pc group by 1) x),
  gaps as (select coalesce(jsonb_agg(jsonb_build_object('route', x.route, 'providers', x.n, 'courses_waiting', x.c, 'parked', x.p, 'example_reason', x.r, 'next_action', x.a) order by x.n desc), '[]'::jsonb) j
             from (select coalesce(f.evidence->>'route', 'not_classified') route, count(*) n, sum(coalesce((f.evidence->>'courses_waiting')::int, 0)) c,
                          bool_or(coalesce((f.evidence->>'parked')::boolean, false)) p, min(f.evidence->>'reason') r, min(f.evidence->>'next_action') a
                     from pipeline.aer_gap_findings f where f.root_cause = 'no_source' and f.state <> 'resolved' group by 1) x),
  other as (select coalesce(jsonb_agg(jsonb_build_object('cause', x.root_cause, 'findings', x.n) order by x.n desc), '[]'::jsonb) j
              from (select root_cause, count(*) n from pipeline.aer_gap_findings where state <> 'resolved' and root_cause <> 'no_source' group by 1) x),
  prk as (select coalesce(jsonb_agg(jsonb_build_object('class', x.failure_class, 'items', x.n, 'providers', x.pv, 'reason', x.r, 'next_action', x.a) order by x.n desc), '[]'::jsonb) j, coalesce(sum(x.n), 0) total
            from (select failure_class, count(*) n, count(distinct provider_id) pv, min(reason) r, min(next_action) a from security.aer_parked_items_v1() group by 1) x),
  lastrun as (select coalesce((select to_jsonb(x) from (select ran_at, course_reads, corrections, matrix_pages, layer4_waiting, in_progress, back_pressure, room, refusal, detail->'parked_not_counted' parked_not_counted
                                           from pipeline.aer_schedule_runs order by ran_at desc limit 1) x), '{}'::jsonb) j),
  jobs as (select coalesce(jsonb_agg(jsonb_build_object('job', c.jobname, 'active', c.active, 'schedule', c.schedule, 'next_run', case when c.active then security.cron_next_run_v1(c.schedule, now()) end) order by c.jobname), '[]'::jsonb) j
             from cron.job c where c.jobname in ('aer-scheduled-read', 'aer-source-stored-find', 'entry-matrix-read', 'aer-replay')),
  sf as (select jsonb_build_object('switch_on', security.pipeline_num_v1('aer.source_stored_find_on', 0) >= 1, 'providers_checked', count(*), 'sources_attached', coalesce(sum(attached), 0), 'last_checked_at', max(checked_at)) j,
                coalesce(security.pipeline_num_v1('aer.source_stored_find_on', 0) >= 1, false) on_ from pipeline.aer_source_stored_find),
  srcs as (select coalesce(jsonb_object_agg(x.status, x.n), '{}'::jsonb) j, coalesce(sum(x.n), 0) total from (select status, count(*) n from pipeline.entry_matrix_sources group by 1) x),
  rv as (select coalesce(jsonb_object_agg(x.readiness, x.n), '{}'::jsonb) j from (select readiness, count(*) n from pipeline.aer_review_readiness where settled_at is null group by 1) x),
  stored_waiting as (select coalesce(sum((g->>'providers')::int), 0) n from gaps, jsonb_array_elements(gaps.j) g where g->>'route' = 'source_page_stored'),
  -- 10 Nov 2026 (AER read now): reviewer-ready packets against active approved rows, from the stored completeness gate and the proposed rows (never a gate per item)
  pk as (select * from security.aer_pending_packets_v1(null, null)),
  pf as (select count(*) rows, count(*) filter (where x.country <> 'not_stated' and x.qualification <> 'not_stated' and x.grade <> 'not_stated' and x.scale <> 'not_stated' and x.applicability <> 'not_stated' and x.source_page <> 'not_stated' and x.year <> 'not_stated') complete,
                jsonb_strip_nulls(jsonb_build_object('country', nullif(count(*) filter (where x.country = 'not_stated'), 0), 'qualification', nullif(count(*) filter (where x.qualification = 'not_stated'), 0), 'grade', nullif(count(*) filter (where x.grade = 'not_stated'), 0),
                  'scale', nullif(count(*) filter (where x.scale = 'not_stated'), 0), 'applicability', nullif(count(*) filter (where x.applicability = 'not_stated'), 0), 'source_page', nullif(count(*) filter (where x.source_page = 'not_stated'), 0),
                  'year', nullif(count(*) filter (where x.year = 'not_stated'), 0))) ns
           from security.aer_packet_rows_v1(null) x join pk on pk.item_id = x.item_id and pk.packet_state = 'reviewer_ready'),
  rvw as (select jsonb_build_object('known', true, 'pending', (select count(*) from pk), 'classified_at', (select max(classified_at) from pk),
            'reviewer_ready', (select count(*) from pk where packet_state = 'reviewer_ready'), 'technical_hold', (select count(*) from pk where packet_state = 'technical_hold'),
            'needs_input', (select count(*) from pk where packet_state = 'needs_input'), 'not_checked', (select count(*) from pk where packet_state = 'not_checked'),
            'by_kind', (select coalesce(jsonb_object_agg(z.field_code, jsonb_build_object('pending', z.n, 'reviewer_ready', z.r)), '{}'::jsonb) from (select field_code, count(*) n, count(*) filter (where packet_state = 'reviewer_ready') r from pk group by 1) z),
            'ready_rows', (select jsonb_build_object('rows', pf.rows, 'every_fact_stated', pf.complete, 'with_a_fact_not_stated', pf.rows - pf.complete, 'not_stated', pf.ns) from pf),
            'active_rows', jsonb_build_object('matrix', (select count(*) from catalogue.provider_entry_matrix where status = 'active'), 'course', (select count(*) from catalogue.course_entry_requirements where status = 'active')),
            'decided', (select jsonb_build_object('approved', count(*) filter (where i.status in ('approved', 'edited_approved')), 'rejected', count(*) filter (where i.status = 'rejected'), 'last_decided_at', max(i.decided_at))
                          from pipeline.layer4_review_items i where i.field_code = any (security.aer_review_kinds_v1()) and i.status in ('approved', 'edited_approved', 'rejected')),
            'on_demand', (select jsonb_build_object('requests_24h', count(*), 'last_request_at', max(e.created_at), 'queued_24h', count(*) filter (where e.detail->>'outcome' = 'queued')) from pipeline.admin_control_events e where e.area = 'aer_read_now' and e.created_at > now() - interval '1 day')) j),
  blk as (select coalesce(jsonb_agg(v.t), '[]'::jsonb) j
            from lastrun, sf, stored_waiting, lateral (values
              (case when lastrun.j->>'refusal' is not null then 'Scheduled entry reading is refused: ' || (lastrun.j->>'refusal') end),
              (case when coalesce((lastrun.j->>'back_pressure')::boolean, false)
                    then 'Layer 4 is full for entry requirements: ' || (lastrun.j->>'layer4_waiting') || ' items waiting against the limit of ' || v_max || ' (parked holds not counted: ' || coalesce(lastrun.j->>'parked_not_counted', 'not counted by this run') || '); no new course read starts until decisions are made' end),
              (case when not sf.on_ and stored_waiting.n > 0 then stored_waiting.n || ' providers have a stored entry page that waits for the switch Entry pages from stored links' end)) v(t)
           where v.t is not null)
  select jsonb_build_object('known', true, 'counted_at', now(), 'unit', 'providers', 'coverage', cov.j, 'by_country', bycc.j, 'dispositions', disp.j,
           'sources', jsonb_build_object('total', srcs.total, 'by_status', srcs.j, 'stored_find', sf.j),
           'gaps', gaps.j, 'other_findings', other.j, 'parked', jsonb_build_object('items', prk.total, 'by_rule', prk.j),
           'layer4_readiness', rv.j, 'reviewer', rvw.j, 'last_run', lastrun.j, 'jobs', jobs.j, 'blockers', blk.j)
    from cov, bycc, disp, gaps, other, prk, lastrun, jobs, sf, srcs, rv, rvw, blk);
exception when others then
  return jsonb_build_object('known', false, 'reason', left(sqlerrm, 200));
end $$;


ALTER FUNCTION "security"."data_delivery_aer_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."data_delivery_aer_v1"() IS 'CF-247 AER Data Delivery (Platform Admin 10 Nov 2026): eligible providers, providers with a source and with active rows, active and proposed rows, sources by status and attached by the stored-link step, the remaining gaps by route with the next action, parked holds by rule with the exact reason, other findings, readiness for Layer 4, the last run and the next run of each AER job, and the active blockers. Read only, counted live; called by security.data_delivery_v1 for the stream aer as the key aer_sources.';



CREATE OR REPLACE FUNCTION "security"."data_delivery_cdesc_flow_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_cap int := security.pipeline_num_v1('enrich.course_text_items_per_day', 500)::int; v_pmax int := security.pipeline_num_v1('enrich.course_description_pending_max', 10)::int;
        v_on boolean := security.pipeline_num_v1('enrich.course_description_machine_on', 0) >= 1; v_stamp text := security.course_description_machine_policy_stamp_v1();
        v_day int; v_full int; v_parked int; v_el jsonb; v_blocker text; v_info jsonb := security.cdesc_job_info_v1(); v_dec jsonb; v_held jsonb; v_gain jsonb; v_last timestamptz; v_lastd timestamptz;
begin
  -- the eligible denominator and where each course is: active, no description, a stored, read, identity-proved page (the rule the standing queue uses)
  select jsonb_build_object('active_courses', (select count(*) from catalogue.courses where lifecycle_status = 'active'),
                            'without_description', count(*), 'never_read', count(*) filter (where z.state is null),
                            'waiting_in_layer4', count(*) filter (where z.state = 'review'),
                            'held_behind_provider_cap', count(*) filter (where z.state = 'skipped' and z.reason like 'held\_first\_admission:%'),
                            'held_by_a_check', count(*) filter (where z.state = 'skipped' and z.reason like 'held: %'),
                            'read_other', count(*) filter (where z.state is not null and z.state <> 'review' and not (z.state = 'skipped' and (z.reason like 'held\_first\_admission:%' or z.reason like 'held: %'))))
    into v_el
    from (select m.cid, l.state, l.reason from (select c.id cid from catalogue.courses c where c.lifecycle_status = 'active' and nullif(btrim(c.description), '') is null
                                                   and exists (select 1 from pipeline.coverage_course_pages g where g.course_id = c.id and g.evidence_id is not null and g.status in ('bound', 'ambiguous') and g.read_status = 'read' and g.identity_basis is not null)) m
            left join lateral (select e.state, e.reason from pipeline.field_enrich_items e where e.course_id = m.cid and e.field = 'description' order by e.id desc limit 1) l on true) z;
  select count(*) into v_day from pipeline.field_enrich_items e join pipeline.admin_jobs j on j.id = e.job_id
   where e.field = 'description' and e.created_at > now() - interval '1 day' and coalesce((j.args->>'standing')::boolean, false); -- fixed: the cap is a day's
  select count(*) into v_full from (select c.provider_id from pipeline.layer4_review_items q join catalogue.courses c on c.id = q.entity_id
                                     where q.entity_type = 'course' and q.field_code = 'course_description_first_read' and q.status = 'pending'
                                       and not exists (select 1 from pipeline.course_description_machine_admissions d where d.review_item_id = q.id and d.outcome = 'declined' and d.withdrawn_at is null and not d.transient and d.policy_stamp = v_stamp)
                                     group by 1 having count(*) >= v_pmax) z;
  select count(*) into v_parked from pipeline.layer4_review_items q where q.entity_type = 'course' and q.field_code = 'course_description_first_read' and q.status = 'pending'
     and exists (select 1 from pipeline.course_description_machine_admissions d where d.review_item_id = q.id and d.outcome = 'declined' and d.withdrawn_at is null and not d.transient and d.policy_stamp = v_stamp);
  select coalesce(jsonb_agg(jsonb_build_object('code', k, 'n', n) order by n desc, k), '[]'::jsonb) into v_dec
    from (select d.reason_code k, count(*) n from pipeline.course_description_machine_admissions d join pipeline.layer4_review_items q on q.id = d.review_item_id and q.status = 'pending' where d.outcome = 'declined' and d.withdrawn_at is null group by 1) z;
  select coalesce(jsonb_agg(jsonb_build_object('code', k, 'n', n) order by n desc, k), '[]'::jsonb) into v_held
    from (select case when f.reason like 'held\_first\_admission:%' then 'held_first_admission' else btrim(split_part(f.reason, ':', 2)) end k, count(*) n from pipeline.field_enrich_items f
           where f.field = 'description' and f.state = 'skipped' and (f.reason like 'held: %' or f.reason like 'held\_first\_admission:%') group by 1) z;
  select jsonb_build_object('admitted_24h', count(*) filter (where a.outcome = 'admitted' and a.withdrawn_at is null and a.created_at > now() - interval '1 day'),   -- fixed: report windows
                            'admitted_7d', count(*) filter (where a.outcome = 'admitted' and a.withdrawn_at is null and a.created_at > now() - interval '7 days'),
                            'withdrawn_7d', count(*) filter (where a.outcome = 'admitted' and a.withdrawn_at is not null and a.created_at > now() - interval '7 days'),
                            'retained_total', count(*) filter (where a.outcome = 'admitted' and a.withdrawn_at is null)),
         max(a.created_at) filter (where a.outcome = 'admitted'), max(a.created_at) filter (where a.outcome = 'declined')
    into v_gain, v_last, v_lastd from pipeline.course_description_machine_admissions a;
  v_blocker := case when not v_on then 'The automatic admission switch is off (Settings, Course descriptions: automatic admission).'
                    when v_day >= v_cap then format('The daily reading cap is used up: %s of %s reads today (Settings, enrich.course_text_items_per_day). Admissions are limited by how many courses are read a day.', v_day, v_cap)
                    when v_full > 0 then format('%s universities have every place taken by descriptions that wait for a person (enrich.course_description_pending_max); their further readings are held.', v_full)
                    else null end;
  return jsonb_build_object('known', true, 'counted_at', now(), 'unit', 'courses', 'eligible', v_el, 'gain', v_gain,
    'declined_by_cause', v_dec, 'held_by_cause', v_held, 'subset', security.data_delivery_cdesc_subset_v1(),
    'reads', jsonb_build_object('today', v_day, 'daily_cap', v_cap, 'universities_with_all_places_taken', v_full, 'parked_for_a_person', v_parked),
    'run', jsonb_build_object('automatic_admission_on', v_on, 'last_admission_at', v_last, 'last_decline_at', v_lastd, 'schedule', v_info->>'schedule'),
    'blocker', v_blocker);
exception when others then
  return jsonb_build_object('known', false, 'reason', 'The flow counts could not be read: ' || sqlerrm);
end $$;


ALTER FUNCTION "security"."data_delivery_cdesc_flow_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."data_delivery_cdesc_flow_v1"() IS 'CF-247 F-CDESC: read-only figures for the course description stages in Data Delivery: the eligible denominator (active, no description, a stored read identity-proved page) and where each course is, retained admissions in 24 hours and 7 days, every decline and hold by cause, reads today against enrich.course_text_items_per_day, universities with every place taken, the last admission, the job schedule and the active blocker. A count that cannot be made returns known false, never 0.';



CREATE OR REPLACE FUNCTION "security"."data_delivery_cdesc_stages_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_top int := security.pipeline_num_v1('data_delivery.reasons_shown', 3)::int; -- derived: the existing Data Delivery setting, how many exact reasons a stream lists
begin
  return (
  with l4 as (select i.id, i.status, i.entity_id from pipeline.layer4_review_items i where i.entity_type = 'course' and i.field_code = 'course_description_first_read'),
       led as (select a.course_id, a.review_item_id, a.outcome, a.reason_code, a.reason, a.created_at, a.withdrawn_at, a.consumer_check from pipeline.course_description_machine_admissions a),
       live_m as (select l.course_id, coalesce(l.consumer_check, 'not_checked') chk from led l where l.outcome = 'admitted' and l.withdrawn_at is null),
       declined as (select l.reason_code, l.reason, l.created_at from led l join l4 on l4.id = l.review_item_id where l.outcome = 'declined' and l4.status = 'pending'),
       top as (select d.reason_code code, count(*) n, (array_agg(d.reason order by d.created_at desc))[1] example from declined d group by 1 order by 2 desc, 1 limit v_top),
       described as (select c.id from catalogue.courses c where nullif(btrim(c.description), '') is not null),
       shown as (select d.course_id from search.course_documents d where not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = d.provider_id) and not exists (select 1 from security.layer4_search_blocked_courses b where b.course_id = d.course_id)), -- served to the Website: every course document whose provider is not hidden and that Layer 4 does not block; the course's own publication_status is not what the Website reads
       held as (select count(*) filter (where f.reason like 'held\_first\_admission:%') behind_cap, count(*) filter (where f.reason like 'held: %') by_check
                  from pipeline.field_enrich_items f where f.field = 'description' and f.state = 'skipped'),
       zl as (select z.item ? 'description' has_key from pipeline.zoho_sync_items z where z.entity = 'course' and z.removed_at is null order by z.seq desc limit 1)
  select jsonb_build_object(
    'known', true, 'counted_at', now(), 'unit', 'courses',
    'source', jsonb_build_object('proposals_from_a_stored_page', (select count(*) from pipeline.layer4_review_items i where i.entity_type = 'course' and i.field_code = 'course_description_first_read' and i.evidence_id is not null)),
    'proposal', jsonb_build_object('waiting_in_layer4', (select count(*) from l4 where l4.status = 'pending'),
                                   'held_behind_provider_cap', (select behind_cap from held), 'held_by_a_check', (select by_check from held)),
    'flow', security.data_delivery_cdesc_flow_v1(),
    'validation', jsonb_build_object('not_yet_checked_by_machine', (select count(*) from l4 where l4.status = 'pending' and not exists (select 1 from led l where l.review_item_id = l4.id)),
                                     'declined_by_machine', (select count(*) from declined),
                                     'top_decline_reasons', coalesce((select jsonb_agg(jsonb_build_object('code', t.code, 'n', t.n, 'example', t.example) order by t.n desc, t.code) from top t), '[]'::jsonb)),
    'admitted', jsonb_build_object('by_machine', (select count(*) from live_m),
                                   'by_person', (select count(*) from l4 where l4.status in ('approved', 'edited_approved')
                                                    and not exists (select 1 from pipeline.layer4_decisions md where md.review_item_id = l4.id and md.layer2_state->>'actor_kind' = 'machine')),
                                   'withdrawn', (select count(*) from led where outcome = 'admitted' and withdrawn_at is not null),
                                   'described_courses', (select count(*) from described),
                                   'described_other_route', (select count(*) from described d where d.id not in (select course_id from live_m) and d.id not in (select l4.entity_id from l4 where l4.status in ('approved', 'edited_approved')))),
    'consumers', jsonb_build_object('website_published', (select count(*) from described d where d.id in (select course_id from shown)),
                                    'unpublished_course', (select count(*) from described d where d.id not in (select course_id from shown)),
                                    'machine_readback', jsonb_build_object('matched', (select count(*) from live_m where chk = 'matched'), 'lag', (select count(*) from live_m where chk = 'lag'),
                                                                           'not_in_feed', (select count(*) from live_m where chk = 'not_in_feed'), 'error', (select count(*) from live_m where chk = 'error'),
                                                                           'not_checked', (select count(*) from live_m where chk not in ('matched', 'lag', 'not_in_feed', 'error'))),
                                    'zoho', coalesce((select case when zl.has_key then jsonb_build_object('known', false, 'reason', 'The Zoho course feed now carries a description field, but how many reach Zoho is not counted yet.')
                                                         else jsonb_build_object('known', false, 'reason', 'The latest course item in the Zoho course feed has no description field, so a course description does not reach Zoho. Nothing is counted for it.') end from zl),
                                                    jsonb_build_object('known', false, 'reason', 'The Zoho course feed holds no course item, so nothing is counted for it.'))))
  );
exception when others then
  -- a count that cannot be made is shown as such, never as 0, and does not stop the rest of Data Delivery
  return jsonb_build_object('known', false, 'reason', 'The stage counts could not be read: ' || sqlerrm);
end $$;


ALTER FUNCTION "security"."data_delivery_cdesc_stages_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."data_delivery_cdesc_stages_v1"() IS 'CF-247 F-CDESC visible results (Platform Admin 10 Nov 2026): the course description stages counted live and exactly for Data Delivery (read only): stored-page proposals, waiting and held readings, the machine rule''s declines with the top reasons, admitted by the machine rule and by a person kept apart, withdrawn, described courses, the Website published status, unpublished courses and the machine read-back. Called by security.data_delivery_v1 for the stream cdesc.';



CREATE OR REPLACE FUNCTION "security"."data_delivery_cdesc_subset_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_stamp text := security.course_description_machine_policy_stamp_v1(); v_by jsonb; v_no jsonb; v_g jsonb;
begin
  select jsonb_build_object('retained_total', count(*) filter (where a.withdrawn_at is null),
                            'admitted_24h', count(*) filter (where a.withdrawn_at is null and a.created_at > now() - interval '1 day'),   -- fixed: report windows
                            'admitted_7d', count(*) filter (where a.withdrawn_at is null and a.created_at > now() - interval '7 days'),   -- fixed: report windows
                            'withdrawn_total', count(*) filter (where a.withdrawn_at is not null)) into v_g
    from pipeline.course_description_machine_admissions a where a.outcome = 'admitted' and a.checks ? 'subset_of_reading';
  select coalesce(jsonb_agg(jsonb_build_object('code', k, 'n', n) order by n desc, k), '[]'::jsonb) into v_by
    from (select a.checks->'subset_of_reading'->>'cause' k, count(*) n from pipeline.course_description_machine_admissions a
           where a.outcome = 'admitted' and a.withdrawn_at is null and a.checks ? 'subset_of_reading' group by 1) z;
  select coalesce(jsonb_agg(jsonb_build_object('code', k, 'n', n) order by n desc, k), '[]'::jsonb) into v_no
    from (select e.value->'subset_attempt'->>'result' k, count(*) n from pipeline.field_enrich_items e
           where e.field = 'description' and e.state in ('skipped', 'review') and e.value->'subset_attempt'->>'stamp' = v_stamp group by 1) z;
  return jsonb_build_object('known', true, 'counted_at', now(), 'unit', 'courses', 'recovered', v_g, 'recovered_by_cause', v_by, 'not_recovered_by_reason', v_no);
exception when others then
  return jsonb_build_object('known', false, 'reason', 'The subset recovery counts could not be read: ' || sqlerrm);
end $$;


ALTER FUNCTION "security"."data_delivery_cdesc_subset_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."data_delivery_cdesc_subset_v1"() IS 'CF-247 F-CDESC: read-only figures for the subset recovery of course readings in Data Delivery: descriptions admitted by subset (kept, 24 hours, 7 days, withdrawn) by the cause that held the reading, and the readings still held or waiting by the reason the last attempt of this policy stamp gave. A count that cannot be made returns known false, never 0.';



CREATE OR REPLACE FUNCTION "security"."data_delivery_consumer_v1"("p_reading" "jsonb", "p_side" "text", "p_stale" integer, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_reading is null then jsonb_build_object('known', false, 'reason', coalesce(p_reason, 'Not measured for this stream'))
    when jsonb_typeof(p_reading->'rows') is distinct from 'array' then jsonb_build_object('known', false, 'reason', 'Could not be counted: ' || coalesce(p_reading->>'error', 'no result')) || security.data_delivery_meta_v1(p_reading, p_stale)
    else (select case when coalesce(bool_and(case p_side when 'w' then x.w_matched else x.z_matched end is not null), false)
            then jsonb_build_object('known', true, 'expected', sum(x.expected),
                   'matched', sum(case p_side when 'w' then x.w_matched else x.z_matched end), 'pending', sum(case p_side when 'w' then x.w_pending else x.z_pending end),
                   'missing', sum(case p_side when 'w' then x.w_missing else x.z_missing end), 'not_applicable', sum(case p_side when 'w' then x.w_not_served else x.z_not_served end))
                 || security.data_delivery_meta_v1(p_reading, p_stale)
            else jsonb_build_object('known', false, 'reason', coalesce(p_reason, 'Not measured for this stream')) end
          from jsonb_to_recordset(p_reading->'rows') as x(cc text, expected bigint, w_matched bigint, w_pending bigint, w_missing bigint, w_not_served bigint,
                                                           z_matched bigint, z_pending bigint, z_missing bigint, z_not_served bigint)) end
$$;


ALTER FUNCTION "security"."data_delivery_consumer_v1"("p_reading" "jsonb", "p_side" "text", "p_stale" integer, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_delivery_intake_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_short int := security.pipeline_num_v1('data_delivery.net_short_hours', 24)::int;  -- derived: the existing Data Delivery settings (the same two windows the stream's gain uses)
        v_long int := security.pipeline_num_v1('data_delivery.net_long_hours', 168)::int;
        v_apply boolean := coalesce(security.toolset_setting('pipeline', 'intake_dates.apply_enabled') #>> '{}', 'false') in ('true', '1');   -- fixed: a stored true or 1 is on
        v_page boolean := security.pipeline_num_v1('intake_dates.page_date_admit', 0) >= 1;
        v_out jsonb;
begin
  with act as (select i.id, i.course_id, i.evidence_id, i.intake_label, i.start_date, i.application_deadline
                 from catalogue.course_intakes i join catalogue.courses c on c.id = i.course_id where i.status = 'active' and c.lifecycle_status = 'active'),
       dec as (select d.intake_id, d.outcome, d.reason, d.failure_class, d.publication_state, d.publication_checked_at from pipeline.course_intake_dates d),
       den as (select count(*) total, count(*) filter (where a.start_date is not null) exact_start, count(*) filter (where a.application_deadline is not null) with_deadline,
                      count(*) filter (where a.start_date is null) undated,
                      count(*) filter (where a.start_date is null and d.intake_id is not null) undated_eligible,
                      count(*) filter (where a.start_date is null and d.intake_id is null) undated_no_decision
                 from act a left join dec d on d.intake_id = a.id),
       ev as (select e.intake_id, e.rule, e.outcome, e.run_at, e.reason, e.failure_class, (e.after_value->>'start_date')::date sd, (e.after_value->>'application_deadline')::date dl,
                     (e.before_value->>'start_date')::date bsd, (e.before_value->>'application_deadline')::date bdl
                from pipeline.course_intake_date_events e where e.run_at > now() - make_interval(hours => greatest(v_short, v_long)) and e.outcome in ('filled', 'withdrawn', 'skipped')),
       evh as (select e.*, case when e.outcome = 'filled' and e.sd is not null then exists (select 1 from catalogue.course_intakes i where i.id = e.intake_id and i.start_date = e.sd) end held_sd,
                      case when e.outcome = 'filled' and e.dl is not null then exists (select 1 from catalogue.course_intakes i where i.id = e.intake_id and i.application_deadline = e.dl) end held_dl from ev e),
       adm as (select w.h, a.* from (values (v_short), (v_long)) w(h) cross join lateral (
                 select count(*) filter (where e.outcome = 'filled') gross, count(*) filter (where e.outcome = 'withdrawn') withdrawn,
                        count(distinct e.intake_id) filter (where e.outcome = 'filled' and e.sd is not null and e.bsd is null) new_start,
                        count(distinct e.intake_id) filter (where e.outcome = 'filled' and e.sd is not null and e.bsd is null and e.held_sd) retained_start,
                        count(distinct e.intake_id) filter (where e.outcome = 'filled' and e.dl is not null and e.bdl is null) new_deadline,
                        count(distinct e.intake_id) filter (where e.outcome = 'filled' and e.dl is not null and e.bdl is null and e.held_dl) retained_deadline
                   from evh e where e.run_at > now() - make_interval(hours => w.h)) a),
       byrule as (select e.rule, count(*) filter (where e.outcome = 'filled') filled, count(*) filter (where e.outcome = 'withdrawn') withdrawn
                    from ev e where e.run_at > now() - make_interval(hours => v_short) and e.outcome in ('filled', 'withdrawn') group by 1),
       cls as (select 'now'::text scope, d.intake_id, d.reason, d.failure_class, a.course_id, a.evidence_id, a.intake_label, a.start_date from dec d join act a on a.id = d.intake_id where d.outcome = 'skipped'
               union all
               select 'win', e.intake_id, e.reason, e.failure_class, null, null, null, null from ev e where e.outcome = 'skipped' and e.run_at > now() - make_interval(hours => v_short)),
       cl as (select c.scope, c.intake_id, c.course_id, c.evidence_id, c.intake_label, c.start_date,
                     case when c.failure_class = 'course_identity_unresolved' or c.reason like '%(E16%' or c.reason like 'page refused for this course%' then 'identity'
                          when c.reason like 'no stored reading of the page%' then 'no_page_reading'
                          when c.reason like '%(month only)%' then 'month_only'
                          when c.reason like '%page does not show the audience%' or c.reason like '%no approved main calendar start is on that day%' then 'page_only_unproven'
                          when c.failure_class in ('academic_year_unproven', 'stale_calendar_edition', 'waiting_for_next_academic_year') or c.reason like '%which is past%' then 'waiting_for_period'
                          when c.failure_class = 'wrong_institution_or_campus' or c.reason like 'no valid academic calendar%' or c.reason like 'the named period does not start in this month%' then 'calendar_source'
                          when c.failure_class in ('admission_held', 'course_level_exception') then 'person_decision'
                          else 'other' end k from cls c),
       cl2 as (select c.scope, c.intake_id, case when c.scope = 'now' and c.k = 'month_only' and c.start_date is null and security.intake_page_date_hint_v1(c.course_id, c.evidence_id, c.intake_label) then 'page_date_waiting' else c.k end k from cl c),
       sk as (select c.scope, c.k, count(*) n from cl2 c group by 1, 2),
       skw as (select count(*) events, count(distinct c.intake_id) intakes from cl2 c where c.scope = 'win'),
       pub as (select coalesce(d.publication_state, 'not_checked') st, count(*) n from dec d where d.outcome in ('filled', 'nothing_new') group by 1),
       pubm as (select max(d.publication_checked_at) last_checked from dec d),
       last as (select (select max(e.run_at) from pipeline.course_intake_date_events e where e.outcome = 'filled') last_admitted_at, (select max(e.run_at) from pipeline.course_intake_date_events e) last_processed_at),
       bl as (select jsonb_agg(q.b order by (q.b->>'ord')::int) j from (
                select jsonb_build_object('ord', 1, 'code', 'job_off', 'kind', 'technical', 'n', null, 'text', 'The intake job is switched off (intake_dates.apply_enabled), so nothing is admitted until the Platform Admin switches it on.') b where not v_apply
                union all select jsonb_build_object('ord', 2, 'code', 'page_route_off', 'kind', 'technical', 'n', (select n from sk where scope = 'now' and k = 'page_date_waiting'),
                                                   'text', 'The page-date route is off (intake_dates.page_date_admit), so dates the stored pages print are not admitted.') where v_apply and not v_page
                union all select jsonb_build_object('ord', 3, 'code', 'page_only_unproven', 'kind', 'decision', 'n', s.n, 'text', 'The page prints one date that no approved calendar start shares and the audience is not shown. Held for the Platform Admin''s audience rule.') from sk s where s.scope = 'now' and s.k = 'page_only_unproven'
                union all select jsonb_build_object('ord', 4, 'code', 'identity', 'kind', 'source', 'n', s.n, 'text', 'The page is not proved to be the course''s own (E16). Held until the course identity is proved.') from sk s where s.scope = 'now' and s.k = 'identity'
                union all select jsonb_build_object('ord', 5, 'code', 'no_page_reading', 'kind', 'source', 'n', s.n, 'text', 'No stored reading of the course page. The page has to be read before a date can be taken from it.') from sk s where s.scope = 'now' and s.k = 'no_page_reading'
                union all select jsonb_build_object('ord', 6, 'code', 'calendar_source', 'kind', 'source', 'n', s.n, 'text', 'The provider''s calendar is set aside, or does not start the named period in that month. Needs a corrected or approved calendar.') from sk s where s.scope = 'now' and s.k = 'calendar_source'
                union all select jsonb_build_object('ord', 7, 'code', 'no_calendar', 'kind', 'source', 'n', (select undated_no_decision from den), 'text', 'The provider has no approved calendar, so the plan does not look at these intakes yet.') where (select undated_no_decision from den) > 0) q)
  select jsonb_build_object(
    'known', true, 'counted_at', now(), 'unit', 'intakes',
    'denominator', (select jsonb_build_object('active_intakes', total, 'exact_start', exact_start, 'with_deadline', with_deadline, 'undated', undated, 'undated_eligible', undated_eligible, 'undated_no_decision', undated_no_decision,
                                              'eligible', exact_start + undated_eligible) from den),
    'admissions', jsonb_build_object(
      'windows', (select jsonb_agg(jsonb_build_object('hours', a.h, 'gross', a.gross, 'withdrawn', a.withdrawn, 'net', a.gross - a.withdrawn, 'new_start', a.new_start, 'retained_start', a.retained_start,
                                                      'new_deadline', a.new_deadline, 'retained_deadline', a.retained_deadline) order by a.h) from adm a),
      'by_rule', (select coalesce(jsonb_agg(jsonb_build_object('rule', r.rule, 'filled', r.filled, 'withdrawn', r.withdrawn) order by r.filled desc, r.rule), '[]'::jsonb) from byrule r),
      'last_admitted_at', (select last_admitted_at from last), 'last_processed_at', (select last_processed_at from last)),
    'skipped', jsonb_build_object(
      'now', (select coalesce(jsonb_agg(jsonb_build_object('k', s.k, 'n', s.n) order by s.n desc, s.k), '[]'::jsonb) from sk s where s.scope = 'now'),
      'window_hours', v_short, 'window_events', (select events from skw), 'window_intakes', (select intakes from skw),
      'window', (select coalesce(jsonb_agg(jsonb_build_object('k', s.k, 'n', s.n) order by s.n desc, s.k), '[]'::jsonb) from sk s where s.scope = 'win')),
    'publication', jsonb_build_object('by_state', (select coalesce(jsonb_agg(jsonb_build_object('state', p.st, 'n', p.n) order by p.n desc, p.st), '[]'::jsonb) from pub p), 'last_checked_at', (select last_checked from pubm)),
    'switches', jsonb_build_object('apply_enabled', v_apply, 'page_date_admit', v_page),
    'blockers', coalesce((select j from bl), '[]'::jsonb)) into v_out;
  return v_out;
exception when others then
  return jsonb_build_object('known', false, 'reason', 'the intake delivery counts could not be made: ' || sqlerrm);
end
$$;


ALTER FUNCTION "security"."data_delivery_intake_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."data_delivery_intake_v1"() IS 'CF-247 F-INT Data Delivery (Platform Admin 10 Nov 2026): the intake stream''s eligible denominator, new and retained admissions in the stream''s two windows, the skipped outcomes by cause (month-only kept apart from the ones a run can still take), the consumer publication state of the decisions and the blockers. Read only, counted live; called by security.data_delivery_v1 for the stream int only, as the key intake_delivery.';



CREATE OR REPLACE FUNCTION "security"."data_delivery_meta_v1"("p_reading" "jsonb", "p_stale" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('measured_at', p_reading->>'measured_at', 'took_ms', p_reading->'took_ms',
    'age_minutes', round(extract(epoch from now() - (p_reading->>'measured_at')::timestamptz) / 60),
    'stale', (p_reading->>'measured_at')::timestamptz < now() - make_interval(mins => p_stale) or p_reading->>'error' is not null,
    'count_error', p_reading->>'error', 'count_failed_at', p_reading->>'failed_at')
$$;


ALTER FUNCTION "security"."data_delivery_meta_v1"("p_reading" "jsonb", "p_stale" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_delivery_net_v1"("p_reading" "jsonb", "p_hours" integer, "p_stale" integer, "p_empty_reason" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_reading is null then jsonb_build_object('known', false, 'window_hours', p_hours, 'reason', 'Not counted yet (the first count runs within minutes of release)')
    when jsonb_typeof(p_reading->'rows') is distinct from 'array' then jsonb_build_object('known', false, 'window_hours', p_hours, 'reason', 'Could not be counted: ' || coalesce(p_reading->>'error', 'no result')) || security.data_delivery_meta_v1(p_reading, p_stale)
    else (select jsonb_build_object('known', true, 'window_hours', p_hours,
              -- admitted is known only when the stream's ledger holds at least one dated event: with none, 0 would be a guess, not a count
              'admitted_known', min(x.since) is not null,
              'admitted_reason', case when min(x.since) is null then coalesce(p_empty_reason, 'No dated admission is recorded in this stream''s ledger yet, so a count of 0 would not be true') end,
              'added', case when min(x.since) is not null then coalesce(sum(x.added), 0) end,
              'removed', case when min(x.since) is not null and bool_and(x.removed is not null) then sum(x.removed) end,
              'removed_known', min(x.since) is not null and coalesce(bool_and(x.removed is not null), false),
              'net', case when min(x.since) is not null and bool_and(x.removed is not null) then coalesce(sum(x.added), 0) - sum(x.removed) end,
              'processed', case when bool_and(x.processed is not null) then sum(x.processed) end,
              'last_added_at', max(x.last_added_at), 'since', min(x.since),
              'partial', min(x.since) is null or min(x.since) > now() - make_interval(hours => p_hours))
            || security.data_delivery_meta_v1(p_reading, p_stale)
          from jsonb_to_recordset(p_reading->'rows') as x(cc text, added bigint, removed bigint, processed bigint, last_added_at timestamptz, since timestamptz)) end
$$;


ALTER FUNCTION "security"."data_delivery_net_v1"("p_reading" "jsonb", "p_hours" integer, "p_stale" integer, "p_empty_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_delivery_parts_v1"("p_lane" "text", "p_parts" "text"[], "p_stale" integer, "p_top" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with u as (
    select x.ord, split_part(split_part(x.spec, '=', 1), ':', 1) as sk, nullif(split_part(split_part(x.spec, '=', 1), ':', 2), '') as rsn, nullif(split_part(x.spec, '=', 2), '') as lbl from unnest(p_parts) with ordinality x(spec, ord)),
  p as (
    select u.ord, u.rsn, u.lbl, st.key, st.title, st.kind, r.reasons, r.oldest_at, coalesce(t.measured_at, r.measured_at) as at, coalesce(t.measure_error, r.error) as err,
           case when st.transition_key is not null then case when t.measure_error is null then t.input_eligible end else r.n end as stage_n
      from u join pipeline.lane_funnel_stages st on st.lane = p_lane and st.key = u.sk
      left join pipeline.progress_transitions t on t.key = st.transition_key
      left join pipeline.lane_funnel_readings r on r.lane = st.lane and r.stage_key = st.key),
  q as (
    select p.*, case when p.rsn is null then p.stage_n when p.stage_n is null and p.reasons is null then null
                     else coalesce((select sum((e->>'n')::numeric) from jsonb_array_elements(coalesce(p.reasons, '[]'::jsonb)) e where e->>'reason' = p.rsn), 0) end as n
      from p),
  rs as (
    select e->>'reason' as reason, (e->>'n')::numeric as n, q.title as stage, e->>'oldest' as oldest_at
      from q cross join lateral jsonb_array_elements(q.reasons) e where q.rsn is null and q.kind in ('held', 'blocked') and q.reasons is not null and (e->>'n')::numeric > 0
    union all
    select coalesce(q.lbl, q.rsn, q.title), q.n, q.title, q.oldest_at::text from q
     where q.n > 0 and (q.rsn is not null or q.reasons is null or q.kind not in ('held', 'blocked')))
  select jsonb_build_object('known', coalesce(bool_or(q.n is not null), false), 'n', sum(q.n), 'partial', coalesce(bool_or(q.n is null), false),
      'parts', coalesce(jsonb_agg(jsonb_build_object('stage', q.key, 'title', case when q.rsn is null then q.title else coalesce(q.lbl, q.title || ': ' || q.rsn) end, 'kind', q.kind, 'n', q.n,
               'oldest_at', q.oldest_at, 'measured_at', q.at, 'stale', coalesce(q.at < now() - make_interval(mins => p_stale), false), 'error', q.err) order by q.ord), '[]'::jsonb),
      'reasons', (select coalesce(jsonb_agg(jsonb_build_object('reason', z.reason, 'n', z.n, 'stage', z.stage, 'oldest_at', z.oldest_at) order by z.n desc, z.reason), '[]'::jsonb)
                    from (select * from rs order by n desc, reason limit greatest(coalesce(p_top, 0), 0)) z))
    from q
$$;


ALTER FUNCTION "security"."data_delivery_parts_v1"("p_lane" "text", "p_parts" "text"[], "p_stale" integer, "p_top" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_delivery_pdesc_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_top int := security.pipeline_num_v1('data_delivery.reasons_shown', 3)::int; -- derived: the existing Data Delivery setting, how many exact reasons a stream lists
        v_cap numeric := security.pipeline_num_v1('pdesc.ai_usd_max', 1); -- the ceiling the reserve function tests (same setting, same default)
        v_daily numeric := (security.toolset_setting('openrouter', 'guard_provider_description') #>> '{}')::numeric; -- the daily guard the reserve function also tests; null = the setting is not held, shown as Not measured
        v_on boolean := security.pipeline_num_v1('pdesc.registry_upgrade_on', 0) >= 1;
begin
  return (
  with led as (select coalesce(sum(l.cost_usd), 0) usd, coalesce(sum(l.calls), 0) calls,
                      coalesce(sum(l.cost_usd) filter (where l.at >= date_trunc('day', now() at time zone 'UTC') at time zone 'UTC'), 0) today -- fixed: the UTC day the reserve function's daily guard uses
                 from pipeline.ai_spend_ledger l where l.lane = 'provider_description' and l.source <> 'opening'),
       res as (select coalesce(sum(r.reserved_usd), 0) usd, count(*) n from pipeline.provider_description_reads r where r.reserved_usd > 0),
       stl as (select count(*) n, coalesce(sum((r.checks->'reservation_settlement'->>'settled_usd')::numeric), 0) usd from pipeline.provider_description_reads r where r.checks ? 'reservation_settlement'),
       live as (select a.provider_id, a.tier, a.read_id, a.created_at from pipeline.provider_description_machine_admissions a where a.outcome = 'admitted' and a.withdrawn_at is null),
       closed as (select distinct a.provider_id from pipeline.provider_description_machine_admissions a where a.outcome = 'admitted' and a.withdrawn_at is not null and a.tier = 'registry_factual'),
       up as (select l.provider_id from live l join closed c on c.provider_id = l.provider_id where l.tier <> 'registry_factual'),
       ai as (select r.provider_id from pipeline.provider_description_reads r join live l on l.read_id = r.id and l.provider_id = r.provider_id and l.tier <> 'registry_factual' where r.state = 'admitted' and r.rule = 'missing'),
       uq as (select count(*) n from pipeline.provider_description_reads r where r.state = 'queued' and security.provider_description_basic_profile_v1(r.provider_id) is not null),
       uh as (select coalesce(nullif(btrim(r.rule), ''), 'no rule recorded') rule, r.reason, r.updated_at
                from pipeline.provider_description_reads r join live l on l.provider_id = r.provider_id and l.tier = 'registry_factual'
               where r.state = 'held' and r.created_at > l.created_at),
       uht as (select h.rule, count(*) n, (array_agg(h.reason order by h.updated_at desc))[1] example from uh h group by 1 order by 2 desc, 1 limit v_top)
  select jsonb_build_object(
    'known', true, 'counted_at', now(), 'unit', 'providers',
    'ai', jsonb_build_object(
        'ceiling_usd', v_cap, 'spent_usd', (select usd from led), 'calls', (select calls from led),
        'reserved_usd', (select usd from res), 'reserved_reads', (select n from res),
        'remaining_usd', greatest(0, v_cap - (select usd from led) - (select usd from res)),
        'today_usd', (select today from led), 'daily_guard_usd', v_daily,
        'daily_remaining_usd', case when v_daily is null then null else greatest(0, v_daily - (select today from led) - (select usd from res)) end,
        'settled_estimated_reads', (select n from stl), 'settled_estimated_usd', (select usd from stl)),
    'admitted', jsonb_build_object(
        'ai_first_description', (select count(*) from ai where ai.provider_id not in (select provider_id from up)),
        'ai_upgrade', (select count(*) from ai where ai.provider_id in (select provider_id from up)),
        'registry_fact', (select count(*) from live where tier = 'registry_factual'),
        'by_person', (select count(*) from pipeline.layer4_review_items i where i.entity_type = 'provider' and i.field_code = 'provider_description' and i.status in ('approved', 'edited_approved')
                        and not exists (select 1 from pipeline.provider_description_machine_admissions m where m.review_item_id = i.id and m.outcome = 'admitted')),
        'withdrawn', (select count(*) from pipeline.provider_description_machine_admissions a where a.outcome = 'admitted' and a.withdrawn_at is not null and not exists (select 1 from live l where l.provider_id = a.provider_id))),
    'upgrade', jsonb_build_object(
        'lane_on', v_on, 'admitted', (select count(*) from up), 'basic_profiles_held', (select count(*) from live where tier = 'registry_factual'),
        'queued_reads', (select n from uq), 'held_reads', (select count(*) from uh),
        'top_hold_rules', coalesce((select jsonb_agg(jsonb_build_object('rule', t.rule, 'n', t.n, 'example', t.example) order by t.n desc, t.rule) from uht t), '[]'::jsonb)),
    -- sentence-subset recovery (migration 20261110210000): readings recovered by leaving out the sentences the text rule refuses, and the readings still declined, by cause
    'subset_recovery', jsonb_build_object(
        'recovered', (select count(*) from pipeline.provider_description_machine_admissions a where a.outcome = 'admitted' and a.withdrawn_at is null and a.checks ? 'subset_of_reading'),
        'recovered_ever', (select count(*) from pipeline.provider_description_machine_admissions a where a.outcome = 'admitted' and a.checks ? 'subset_of_reading'),
        'sentences_left_out', (select coalesce(sum(jsonb_array_length(a.checks->'subset_of_reading'->'dropped')), 0) from pipeline.provider_description_machine_admissions a where a.outcome = 'admitted' and a.checks ? 'subset_of_reading'),
        'waiting_items', (select count(*) from pipeline.layer4_review_items i where i.entity_type = 'provider' and i.field_code = 'provider_description' and i.status = 'pending'),
        'still_declined', (select count(*) from pipeline.layer4_review_items i join pipeline.provider_description_machine_admissions d on d.review_item_id = i.id and d.outcome = 'declined'
                            where i.entity_type = 'provider' and i.field_code = 'provider_description' and i.status = 'pending'),
        'causes', (select count(distinct z.cause) from (select case when d.checks->'subset_recovery'->>'result' is not null and d.checks->'subset_recovery'->>'result' <> 'adopted' then 'subset: ' || (d.checks->'subset_recovery'->>'result')
                                                                    else coalesce(substring(d.reason from '\(([a-z_]+)'), 'other') end cause
                                                          from pipeline.layer4_review_items i join pipeline.provider_description_machine_admissions d on d.review_item_id = i.id and d.outcome = 'declined'
                                                         where i.entity_type = 'provider' and i.field_code = 'provider_description' and i.status = 'pending') z),
        'still_declined_by_cause', coalesce((select jsonb_agg(jsonb_build_object('cause', c.cause, 'n', c.n, 'example', c.example) order by c.n desc, c.cause)
                                               from (select z.cause, count(*) n, (array_agg(z.reason order by z.created_at desc))[1] example
                                                       from (select case when d.checks->'subset_recovery'->>'result' is not null and d.checks->'subset_recovery'->>'result' <> 'adopted' then 'subset: ' || (d.checks->'subset_recovery'->>'result')
                                                                         else coalesce(substring(d.reason from '\(([a-z_]+)'), 'other') end cause, d.reason, d.created_at
                                                               from pipeline.layer4_review_items i join pipeline.provider_description_machine_admissions d on d.review_item_id = i.id and d.outcome = 'declined'
                                                              where i.entity_type = 'provider' and i.field_code = 'provider_description' and i.status = 'pending') z
                                                      group by z.cause order by 2 desc, 1 limit v_top) c), '[]'::jsonb))));
exception when others then
  -- a count that cannot be made is shown as such, never as 0, and does not stop the rest of Data Delivery
  return jsonb_build_object('known', false, 'reason', 'The provider AI and upgrade counts could not be read: ' || sqlerrm);
end
$$;


ALTER FUNCTION "security"."data_delivery_pdesc_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."data_delivery_pdesc_v1"() IS 'CF-247 F-PDESC Data Delivery (Platform Admin 10 Nov 2026): the provider-description lane''s AI spend, reservations, remaining allowance (ceiling pdesc.ai_usd_max and the daily guard), estimated settlements, descriptions admitted by the AI from an official page (first descriptions and upgrades), by the registry-fact route and by a person, and the Basic to Enriched upgrade (upgraded, queued upgrade reads, held upgrade reads by rule), counted live and read only. Called by security.data_delivery_v1 for the stream pdesc as the key provider_ai.';



CREATE OR REPLACE FUNCTION "security"."data_delivery_refresh_v1"("p_force" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  m record; v_rows jsonb; v_t0 timestamptz; v_start timestamptz := clock_timestamp();
  v_every int := security.pipeline_num_v1('data_delivery.refresh_minutes', 10)::int;
  v_batch int := security.pipeline_num_v1('data_delivery.measures_per_run', 8)::int;
  v_budget int := security.pipeline_num_v1('data_delivery.run_budget_seconds', 30)::int;
  v_short int := security.pipeline_num_v1('data_delivery.net_short_hours', 24)::int;
  v_long int := security.pipeline_num_v1('data_delivery.net_long_hours', 168)::int;
  v_hist int := security.pipeline_num_v1('data_delivery.run_history_hours', 48)::int;
  v_done int := 0; v_failed int := 0; v_jobs_done boolean := false; v_hist_due boolean;
begin
  if security.pipeline_num_v1('data_delivery.on', 1) < 1 and not p_force then return jsonb_build_object('skipped', 'switched off (data_delivery.on)'); end if;
  if not pg_try_advisory_xact_lock(hashtext('data_delivery_refresh')) then return jsonb_build_object('skipped', 'another count is running'); end if;
  -- the scheduler history of the primary jobs: ONE grouped scan of cron.job_run_details here, in the background, so the screen's read never scans it
  select coalesce(p_force or r.measured_at is null or coalesce(r.failed_at, r.measured_at) < now() - make_interval(mins => v_every), true) into v_hist_due
    from (select 1) one left join pipeline.data_delivery_job_runs r on r.singleton;
  if v_hist_due and to_regnamespace('cron') is not null then
    v_t0 := clock_timestamp();
    begin
      with want as (
        select c.jobid, c.jobname from cron.job c
         where c.jobname = 'data-delivery' or c.jobname in (select unnest(x.primary_jobs) from pipeline.data_delivery_streams x)),
      h as (
        select d.jobid, max(d.start_time) as last_start, (array_agg(d.end_time order by d.start_time desc))[1] as last_end, (array_agg(d.status order by d.start_time desc))[1] as last_status,
               (array_agg(left(d.return_message, 240) order by d.start_time desc))[1] as last_message, max(d.start_time) filter (where d.status = 'succeeded') as last_success,
               count(*) filter (where d.start_time > now() - make_interval(hours => v_short)) as runs,
               count(*) filter (where d.start_time > now() - make_interval(hours => v_short) and d.status = 'failed') as failed,
               count(*) filter (where d.start_time > now() - make_interval(hours => v_short) and d.status = 'succeeded') as succeeded,
               bool_or(d.status in ('running', 'starting')) as running
          from cron.job_run_details d where d.jobid in (select jobid from want) and d.start_time > now() - make_interval(hours => greatest(v_hist, v_short)) group by d.jobid)
      select coalesce(jsonb_object_agg(w.jobname, jsonb_build_object('last_start', h.last_start, 'last_end', h.last_end, 'last_status', h.last_status, 'last_message', h.last_message,
               'last_success', h.last_success, 'runs', coalesce(h.runs, 0), 'failed', coalesce(h.failed, 0), 'succeeded', coalesce(h.succeeded, 0), 'running', coalesce(h.running, false))), '{}'::jsonb)
        into v_rows from want w left join h on h.jobid = w.jobid;
      insert into pipeline.data_delivery_job_runs as r(singleton, measured_at, runs, took_ms, error, failed_at)
        values (true, clock_timestamp(), v_rows, (extract(epoch from clock_timestamp() - v_t0) * 1000)::int, null, null)
        on conflict (singleton) do update set measured_at = excluded.measured_at, runs = excluded.runs, took_ms = excluded.took_ms, error = null, failed_at = null;
      v_jobs_done := true;
    exception when others then
      insert into pipeline.data_delivery_job_runs as r(singleton, measured_at, runs, took_ms, error, failed_at)
        values (true, clock_timestamp(), null, (extract(epoch from clock_timestamp() - v_t0) * 1000)::int, left(sqlerrm, 300), clock_timestamp())
        on conflict (singleton) do update set took_ms = excluded.took_ms, error = excluded.error, failed_at = excluded.failed_at;
    end;
  end if;
  for m in
    select d.stream, d.measure, d.sql, d.hours from (
      select s.stream, k.measure,
             case k.measure when 'coverage' then s.coverage_sql when 'net_short' then s.net_sql when 'net_long' then s.net_sql else s.consumer_sql end as sql,
             case k.measure when 'net_long' then v_long else v_short end as hours, s.sort
        from pipeline.data_delivery_streams s cross join (values ('coverage'), ('net_short'), ('net_long'), ('consumer')) k(measure)) d
      left join pipeline.data_delivery_readings r on r.stream = d.stream and r.measure = d.measure
     -- a measure is due when it was last counted (or last failed) longer ago than the count-again time: a failing heavy measure backs off to the same interval, it is not re-run every minute
     where d.sql is not null and (p_force or r.measured_at is null or coalesce(r.failed_at, r.measured_at) < now() - make_interval(mins => v_every))
     order by r.measured_at nulls first, d.sort, d.measure
     limit v_batch
  loop
    v_t0 := clock_timestamp();
    begin
      v_rows := security.lane_funnel_eval_v1(m.sql, m.hours);
      insert into pipeline.data_delivery_readings as r(stream, measure, measured_at, rows, took_ms, error, failed_at)
        values (m.stream, m.measure, clock_timestamp(), v_rows, (extract(epoch from clock_timestamp() - v_t0) * 1000)::int, null, null)
        on conflict (stream, measure) do update set measured_at = excluded.measured_at, rows = excluded.rows, took_ms = excluded.took_ms, error = null, failed_at = null;
      v_done := v_done + 1;
    exception when others then
      -- a failed count never overwrites the last good one: rows and measured_at stay, the error and its time are added (the screen shows the figures as Stale with the error)
      insert into pipeline.data_delivery_readings as r(stream, measure, measured_at, rows, took_ms, error, failed_at)
        values (m.stream, m.measure, clock_timestamp(), null, (extract(epoch from clock_timestamp() - v_t0) * 1000)::int, left(sqlerrm, 300), clock_timestamp())
        on conflict (stream, measure) do update set took_ms = excluded.took_ms, error = excluded.error, failed_at = excluded.failed_at;
      v_failed := v_failed + 1;
    end;
    exit when clock_timestamp() - v_start > make_interval(secs => v_budget);  -- the run stops starting new counts once its budget is spent; the rest stay due for the next run
  end loop;
  return jsonb_build_object('counted', v_done, 'failed', v_failed, 'jobs_summarised', v_jobs_done);
end $$;


ALTER FUNCTION "security"."data_delivery_refresh_v1"("p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_delivery_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  s record; v_out jsonb := '[]'::jsonb;
  v_short int := security.pipeline_num_v1('data_delivery.net_short_hours', 24)::int;
  v_long int := security.pipeline_num_v1('data_delivery.net_long_hours', 168)::int;
  v_stale int := security.pipeline_num_v1('data_delivery.stale_after_minutes', 30)::int;
  v_hist int := security.pipeline_num_v1('data_delivery.run_history_hours', 48)::int;
  v_top int := security.pipeline_num_v1('data_delivery.reasons_shown', 3)::int;
  v_ui int := security.pipeline_num_v1('data_delivery.ui_refresh_seconds', 60)::int;
  v_runs jsonb; v_r jsonb; v_cov jsonb; v_ns jsonb; v_nl jsonb; v_w jsonb; v_z jsonb; v_q jsonb; v_h jsonb; v_speed jsonb; v_jobs jsonb; v_job_sum jsonb; v_flags jsonb; v_rec jsonb;
  v_hrs numeric; v_ok int; v_bad int; v_last_status text; v_open int; v_remedy_ok int; v_remedy_bad int; v_remedy_last timestamptz; v_issue_refs jsonb; v_off boolean; v_active int; v_total int;
  v_hint text; v_qtxt text; v_hc jsonb; v_hc_at timestamptz; v_hc_err text; v_hc_failed timestamptz; v_hc_ok boolean; v_stalled boolean; v_paused text; v_every int := security.pipeline_num_v1('data_delivery.refresh_minutes', 10)::int; v_oldest timestamptz; v_newest timestamptz; v_errors int; v_rd jsonb; v_job jsonb; v_sw text[]; v_sw_all int;
begin
  -- a count is marked stale only after at least two count-again times, so a setting cannot make every figure permanently Stale
  v_stale := greatest(v_stale, 2 * v_every);  -- fixed: a safety floor of twice the count-again time, not an operating value
  -- the scheduler history comes from the cache written by job data-delivery (no scan of the scheduler's run history here); the job rows themselves (active, schedule) are read live, they are few
  select r.runs, r.measured_at, r.error, r.failed_at into v_hc, v_hc_at, v_hc_err, v_hc_failed from pipeline.data_delivery_job_runs r where r.singleton;
  select coalesce(jsonb_object_agg(w.jobname, jsonb_build_object('runs', 0, 'failed', 0, 'succeeded', 0, 'running', false) || coalesce(v_hc->w.jobname, '{}'::jsonb)
      || jsonb_build_object('active', w.active, 'schedule', w.schedule, 'next_run', case when w.active then security.cron_next_run_v1(w.schedule, now()) end)), '{}'::jsonb)
    into v_runs from cron.job w
   where w.jobname = 'data-delivery' or w.jobname in (select unnest(x.primary_jobs) from pipeline.data_delivery_streams x);
  v_hc_ok := coalesce(jsonb_typeof(v_hc) = 'object', false);

  for s in select d.*, l.switch_keys, l.issue_refs, l.title as lane_title from pipeline.data_delivery_streams d join pipeline.lane_funnel_lanes l on l.lane = d.lane order by d.sort, d.stream loop
    select coalesce(jsonb_object_agg(r.measure, jsonb_build_object('rows', r.rows, 'measured_at', r.measured_at, 'took_ms', r.took_ms, 'error', r.error, 'failed_at', r.failed_at)), '{}'::jsonb)
      into v_r from pipeline.data_delivery_readings r where r.stream = s.stream;
    -- coverage: n of N, and the country split
    v_cov := case
      when v_r->'coverage' is null then jsonb_build_object('known', false, 'reason', coalesce(s.not_measured->>'coverage', 'Not counted yet (the first count runs within minutes of release)'))
      when jsonb_typeof(v_r->'coverage'->'rows') is distinct from 'array' then jsonb_build_object('known', false, 'reason', 'Could not be counted: ' || coalesce(v_r->'coverage'->>'error', 'no result')) || security.data_delivery_meta_v1(v_r->'coverage', v_stale)
      else (select jsonb_build_object('known', true, 'n', coalesce(sum(x.n), 0), 'total', case when coalesce(bool_and(x.total is not null), false) then sum(x.total) end,
                'total_reason', case when not coalesce(bool_and(x.total is not null), false) then coalesce(s.not_measured->>'coverage_total', 'The total is not measured') end,
                'pct', case when coalesce(bool_and(x.total is not null), false) and sum(x.total) > 0 then round(100.0 * sum(x.n) / sum(x.total), 1) end,
                'by_country', coalesce(jsonb_agg(jsonb_build_object('cc', x.cc, 'n', x.n, 'total', x.total) order by x.cc), '[]'::jsonb))
              || security.data_delivery_meta_v1(v_r->'coverage', v_stale)
              from jsonb_to_recordset(v_r->'coverage'->'rows') as x(cc text, n bigint, total bigint)) end;
    -- a stream with no net SELECT has no dated admission ledger: its admitted count is unknown (never 0), with the reason
    v_ns := case when s.net_sql is null then jsonb_build_object('known', false, 'window_hours', v_short, 'reason', coalesce(s.not_measured->>'net', 'Admissions are not counted for this stream'))
                 else security.data_delivery_net_v1(v_r->'net_short', v_short, v_stale, s.not_measured->>'net_empty') end;
    v_nl := case when s.net_sql is null then jsonb_build_object('known', false, 'window_hours', v_long, 'reason', coalesce(s.not_measured->>'net', 'Admissions are not counted for this stream'))
                 else security.data_delivery_net_v1(v_r->'net_long', v_long, v_stale, s.not_measured->>'net_empty') end;
    if (v_ns->>'known')::boolean and not (v_ns->>'removed_known')::boolean then v_ns := v_ns || jsonb_build_object('removed_reason', coalesce(s.not_measured->>'net_removed', 'Removals are not recorded for this stream')); end if;
    if (v_nl->>'known')::boolean and not (v_nl->>'removed_known')::boolean then v_nl := v_nl || jsonb_build_object('removed_reason', coalesce(s.not_measured->>'net_removed', 'Removals are not recorded for this stream')); end if;
    v_w := security.data_delivery_consumer_v1(v_r->'consumer', 'w', v_stale, s.not_measured->>'website');
    v_z := security.data_delivery_consumer_v1(v_r->'consumer', 'z', v_stale, s.not_measured->>'zoho');
    if (v_w->>'known')::boolean and s.not_measured ? 'website_pending' then v_w := v_w || jsonb_build_object('pending_reason', s.not_measured->>'website_pending'); end if;
    if (v_z->>'known')::boolean and s.not_measured ? 'zoho_pending' then v_z := v_z || jsonb_build_object('pending_reason', s.not_measured->>'zoho_pending'); end if;
    v_q := case when cardinality(s.queue_parts) = 0 then jsonb_build_object('known', false, 'reason', coalesce(s.not_measured->>'queue', 'No queue is recorded for this stream'))
                else security.data_delivery_parts_v1(s.lane, s.queue_parts, v_stale, 0) end;
    v_h := case when cardinality(s.hold_parts) = 0 then jsonb_build_object('known', false, 'reason', coalesce(s.not_measured->>'holds', 'No holds are recorded for this stream'))
                else security.data_delivery_parts_v1(s.lane, s.hold_parts, v_stale, v_top) end;
    if cardinality(s.hold_parts) > 0 and s.not_measured ? 'holds_by_cause' then v_h := v_h || jsonb_build_object('causes_reason', s.not_measured->>'holds_by_cause'); end if;
    -- speed: items per hour over the stated window (the ledger span when the ledger is younger than the window)
    if not (v_ns->>'known')::boolean then
      v_speed := jsonb_build_object('known', false, 'reason', coalesce(s.not_measured->>'speed', v_ns->>'reason'));
    elsif v_ns->>'processed' is null then
      v_speed := jsonb_build_object('known', false, 'reason', coalesce(s.not_measured->>'speed', 'Processing speed is not recorded for this stream'));
    else
      v_hrs := case when (v_ns->>'partial')::boolean and v_ns->>'since' is not null then greatest(extract(epoch from now() - (v_ns->>'since')::timestamptz) / 3600.0, 1) else v_short end;  -- fixed: at least one hour, so a young ledger is not divided by zero
      v_speed := jsonb_build_object('known', true, 'processed', (v_ns->>'processed')::numeric, 'window_hours', round(v_hrs, 1), 'per_hour', round((v_ns->>'processed')::numeric / v_hrs, 1), 'basis', s.speed_basis);
    end if;
    -- primary jobs: last and next run
    select coalesce(jsonb_agg(coalesce(v_runs->j.jobname, '{}'::jsonb) || jsonb_build_object('job', j.jobname, 'scheduled', v_runs ? j.jobname) order by j.ord), '[]'::jsonb)
      into v_jobs from unnest(s.primary_jobs) with ordinality j(jobname, ord);
    select jsonb_build_object('last_run_at', max((x->>'last_start')::timestamptz), 'next_run_at', min((x->>'next_run')::timestamptz) filter (where (x->>'active')::boolean),
             'runs', coalesce(sum((x->>'runs')::int), 0), 'succeeded', coalesce(sum((x->>'succeeded')::int), 0), 'failed', coalesce(sum((x->>'failed')::int), 0),
             'last_status', (array_agg(x->>'last_status' order by (x->>'last_start')::timestamptz desc nulls last))[1],
             'last_message', (array_agg(x->>'last_message' order by (x->>'last_start')::timestamptz desc nulls last))[1],
             'active', count(*) filter (where (x->>'active')::boolean), 'total', count(*),
             'history_hours', v_hist, 'known', v_hc_ok and count(*) filter (where x->>'last_start' is not null) > 0,
             'history_measured_at', v_hc_at, 'history_error', v_hc_err,
             'history_stale', v_hc_at is null or v_hc_at < now() - make_interval(mins => v_stale) or v_hc_err is not null,
             'reason', case when count(*) = 0 then 'No primary job is named for this stream'
                            when not v_hc_ok then 'The run history is not counted yet (the first count runs within minutes of release)' || coalesce(': ' || v_hc_err, '')
                            when count(*) filter (where x->>'last_start' is not null) = 0 then 'No run of ' || string_agg(x->>'job', ', ') || ' in the last ' || v_hist || ' hours of scheduler history' end)
      into v_job_sum from jsonb_array_elements(v_jobs) x;
    -- recovery: lane switch, open issues of the lane, automatic remedy runs in the short window
    -- 10 Nov 2026 (AER read now): a stream is OFF only when every switch of its lane that exists is off; one optional recovery route that is off (for example a deliberately paused pilot) is named, it does not turn the whole stream off
    select coalesce(array_agg(k.key order by k.key) filter (where (st.value #>> '{}') in ('0', 'false')), '{}'::text[]), count(*) filter (where st.key is not null) into v_sw, v_sw_all from unnest(s.switch_keys) k(key)
      left join pipeline.platform_toolset_settings st on st.toolset_key = 'pipeline' and st.key = k.key;
    v_off := cardinality(v_sw) > 0 and cardinality(v_sw) = v_sw_all;
    select count(*) filter (where i.status <> 'closed'), coalesce(jsonb_agg(i.issue_ref order by i.issue_ref) filter (where i.status <> 'closed'), '[]'::jsonb)
      into v_open, v_issue_refs from pipeline.integration_issues i where i.issue_ref = any(s.issue_refs);
    select count(*) filter (where rr.result in ('acted', 'verified')), count(*) filter (where rr.result in ('refused_authority', 'verify_failed')), max(rr.started_at)
      into v_remedy_ok, v_remedy_bad, v_remedy_last
      from pipeline.ops_remedy_runs rr join pipeline.integration_issues i on i.id = rr.issue_id
     where i.issue_ref = any(s.issue_refs) and rr.started_at > now() - make_interval(hours => v_short);
    v_active := coalesce((v_job_sum->>'active')::int, 0); v_total := coalesce((v_job_sum->>'total')::int, 0);
    v_last_status := v_job_sum->>'last_status';
    v_ok := coalesce((v_job_sum->>'succeeded')::int, 0); v_bad := coalesce((v_job_sum->>'failed')::int, 0);
    v_hint := v_h->'reasons'->0->>'reason';
    v_qtxt := case when (v_q->>'known')::boolean is not true then 'queue not counted'
                   when coalesce((v_q->>'n')::numeric, 0) = 0 then 'queue empty, nothing is waiting'
                   else (case when (v_q->>'partial')::boolean then 'at least ' else '' end) || (v_q->>'n') || ' waiting' end;
    -- a primary job that is paused or not scheduled is named: a stream must not read healthy while one of its jobs does not run
    select string_agg(x->>'job' || case when (x->>'scheduled')::boolean then ' is paused' else ' is not scheduled' end, '; ' order by x->>'job') into v_paused
      from jsonb_array_elements(v_jobs) x where not coalesce((x->>'active')::boolean, false);
    -- a stalled stream: its job ran OK in the window, the admitted count is known and 0, and something is waiting (or the queue is not counted)
    v_stalled := v_ok > 0 and coalesce((v_ns->>'admitted_known')::boolean, false) and coalesce((v_ns->>'added')::numeric, 0) = 0
                 and not ((v_q->>'known')::boolean and coalesce((v_q->>'n')::numeric, 0) = 0);
    v_rec := jsonb_build_object(
      'state', case when v_off then 'off' when v_paused is not null then 'paused' when v_last_status = 'failed' then 'failing' when v_open > 0 and v_remedy_ok > 0 then 'recovering'
                    when v_open > 0 then 'needs_attention' when v_total = 0 then 'unknown' when v_stalled then 'stalled' else 'healthy' end,
      'text', case when v_off then 'A switch for this stream is off, so nothing retries until it is switched on'
                   when v_paused is not null then 'Paused: ' || v_paused || ', so that work does not run until it is switched on'
                   when v_last_status = 'failed' then 'The last run failed; the job retries at its next scheduled run' || coalesce(' (' || to_char((v_job_sum->>'next_run_at')::timestamptz at time zone 'Australia/Melbourne', 'DD Mon HH24:MI') || ' Melbourne)', '')
                   when v_open > 0 and v_remedy_ok > 0 then v_open || ' open issue(s); automatic remedies acted ' || v_remedy_ok || ' time(s) in the window'
                   when v_open > 0 then v_open || ' open issue(s) and no automatic remedy has acted in the window'
                   when v_total = 0 then 'No primary job is named, so recovery is not measured'
                   when v_stalled then 'Stalled: the job ran OK ' || v_ok || ' time(s) in ' || v_short || ' h but admitted nothing (' || v_qtxt || '); it retries on schedule, and nothing is changing'
                   else 'No open issues; the scheduled job retries on its next run' || case when cardinality(v_sw) > 0 then '. Switched off, so these routes do not run: ' || array_to_string(v_sw, ', ') else '' end end,
      'switches_off', to_jsonb(v_sw), 'open_issues', v_open, 'issue_refs', v_issue_refs, 'remedy_acted', v_remedy_ok, 'remedy_refused', v_remedy_bad, 'last_remedy_at', v_remedy_last,
      'window_hours', v_short);
    -- a green job that admitted nothing (or whose admissions cannot be counted) is flagged
    v_flags := '[]'::jsonb;
    if v_ok > 0 and coalesce((v_ns->>'admitted_known')::boolean, false) and coalesce((v_ns->>'added')::numeric, 0) = 0 then
      -- a green job that admitted nothing is always shown; it reads as information, not an alarm, when nothing was waiting
      v_flags := v_flags || jsonb_build_array(jsonb_build_object('code', 'green_no_admission',
        'severity', case when (v_q->>'known')::boolean and coalesce((v_q->>'n')::numeric, 0) = 0 then 'info' else 'warn' end,
        'queue_empty', (v_q->>'known')::boolean and coalesce((v_q->>'n')::numeric, 0) = 0,
        'text', 'Ran OK ' || v_ok || ' time(s) in ' || v_short || ' h, admitted nothing; ' || v_qtxt || coalesce('; top hold: ' || v_hint, '')));
    elsif v_ok > 0 and not coalesce((v_ns->>'admitted_known')::boolean, false) then
      v_flags := v_flags || jsonb_build_array(jsonb_build_object('code', 'green_admission_unknown', 'severity', 'warn',
        'text', 'Ran OK ' || v_ok || ' time(s) in ' || v_short || ' h; what it admitted is unknown (' || coalesce(v_ns->>'admitted_reason', v_ns->>'reason', 'not counted') || '); ' || v_qtxt));
    end if;
    if v_bad > 0 then v_flags := v_flags || jsonb_build_array(jsonb_build_object('code', 'job_failing', 'severity', 'bad', 'text', v_bad || ' failed run(s) in ' || v_short || ' h')); end if;
    if (v_cov->>'known')::boolean is not true or (v_ns->>'known')::boolean is not true or not coalesce((v_ns->>'admitted_known')::boolean, false) then
      v_flags := v_flags || jsonb_build_array(jsonb_build_object('code', 'measure_unknown', 'severity', 'info', 'text', 'A headline measure could not be counted; see the reason in the cell'));
    end if;
    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'stream', s.stream, 'title', s.title, 'unit', s.unit, 'net_unit', coalesce(s.net_unit, s.unit), 'consumer_unit', coalesce(s.consumer_unit, s.unit), 'what', s.what, 'lane', s.lane, 'net_basis', s.net_basis, 'drill', s.drill,
      'coverage', v_cov, 'net_short', v_ns, 'net_long', v_nl, 'website', v_w, 'zoho', v_z, 'queue', v_q, 'holds', v_h, 'speed', v_speed,
      'jobs', v_job_sum || jsonb_build_object('list', v_jobs), 'recovery', v_rec, 'flags', v_flags,
      'stages', case when s.stream = 'cdesc' then security.data_delivery_cdesc_stages_v1() end,
      'provider_ai', case when s.stream = 'pdesc' then security.data_delivery_pdesc_v1() end,
      'intake_delivery', case when s.stream = 'int' then security.data_delivery_intake_v1() end,
      'aer_sources', case when s.stream = 'aer' then security.data_delivery_aer_v1() end,
      'stale', coalesce((v_cov->>'stale')::boolean, false) or coalesce((v_ns->>'stale')::boolean, false) or coalesce((v_w->>'stale')::boolean, false)));
  end loop;
  select min(r.measured_at), max(r.measured_at), count(*) filter (where r.error is not null) into v_oldest, v_newest, v_errors from pipeline.data_delivery_readings r;
  v_job := coalesce(v_runs->'data-delivery', jsonb_build_object('scheduled', false));
  return jsonb_build_object('at', now(), 'timezone', 'Australia/Melbourne', 'ui_refresh_seconds', v_ui, 'stale_after_minutes', v_stale,
    'windows', jsonb_build_object('short_hours', v_short, 'long_hours', v_long),
    'snapshot', jsonb_build_object('oldest_measured_at', v_oldest, 'newest_measured_at', v_newest, 'failed_measures', coalesce(v_errors, 0), 'job', v_job),
    'provider_filters_available', to_regprocedure('security.admin_providers_page_v3(jsonb)') is not null,
    'streams', v_out,
    'meaning', jsonb_build_object('net', 'admitted minus withdrawn, from the stream''s own ledger timestamps in the window',
      'unknown', 'Unknown or Not measured means the figure is not counted here; it is never shown as 0',
      'green', 'a job the scheduler reports as succeeded says nothing about data; the flag shows when it admitted nothing'));
end $$;


ALTER FUNCTION "security"."data_delivery_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_quality_campus_base"("p_country_code" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "entity_name" "text", "stable_key" "text", "provider_id" "uuid", "provider_name" "text", "country_code" "text", "source_id" "uuid", "evidence_id" "uuid", "last_verified_at" timestamp with time zone, "updated_at" timestamp with time zone, "publication_status" "text", "identity_ok" boolean, "geography_present" boolean, "evidence_count" integer, "channel_state_count" integer, "channel_published_count" integer, "channel_rejected_count" integer, "channel_distinct_status_count" integer, "review_domains" "text"[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'ref', 'pipeline', 'workflow', 'publishing', 'auth'
    AS $$
with scope as (
 select ca.*,co.iso_alpha2::text country_code,coalesce(p.display_name,p.canonical_name) provider_name
 from catalogue.campuses ca join catalogue.providers p on p.id=ca.provider_id join ref.countries co on co.id=ca.country_id
 where (p_country_code is null and co.iso_alpha2 in ('AU','NZ')) or (p_country_code is not null and co.iso_alpha2=upper(p_country_code))
), ev as (
 select el.entity_id,count(distinct el.evidence_id)::int evidence_count,(array_agg(el.evidence_id order by el.updated_at desc))[1] evidence_id
 from pipeline.evidence_entity_links el join scope s on s.id=el.entity_id where el.entity_type='campus' group by el.entity_id
), pub as (
 select es.entity_id,count(*)::int state_count,count(*) filter(where lower(es.publication_status)='published')::int published_count,
 count(*) filter(where lower(es.publication_status)='rejected')::int rejected_count,count(distinct lower(es.publication_status))::int distinct_status_count
 from publishing.entity_states es join scope s on s.id=es.entity_id group by es.entity_id
), rev as (
 select q.entity_id,array_agg(distinct lower(q.domain)) filter(where q.status in ('open','queued','pending','in_review')) review_domains
 from workflow.review_queue q join scope s on s.id=q.entity_id group by q.entity_id
)
select s.id,s.name,s.stable_key,s.provider_id,s.provider_name,s.country_code,s.source_id,coalesce(s.evidence_id,ev.evidence_id),s.last_verified_at,s.updated_at,s.publication_status,
 (s.stable_key is not null and btrim(s.stable_key)<>'' and s.name is not null and btrim(s.name)<>'' and s.provider_id is not null and s.country_id is not null),
 (s.subdivision_id is not null or coalesce(nullif(btrim(s.city),''),null) is not null or coalesce(nullif(btrim(s.address_line1),''),null) is not null or (s.latitude is not null and s.longitude is not null)),
 coalesce(ev.evidence_count,case when s.evidence_id is not null then 1 else 0 end),coalesce(pub.state_count,0),coalesce(pub.published_count,0),coalesce(pub.rejected_count,0),coalesce(pub.distinct_status_count,0),coalesce(rev.review_domains,'{}'::text[])
from scope s left join ev on ev.entity_id=s.id left join pub on pub.entity_id=s.id left join rev on rev.entity_id=s.id
$$;


ALTER FUNCTION "security"."data_quality_campus_base"("p_country_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_quality_course_base"("p_country_code" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "entity_name" "text", "stable_key" "text", "provider_id" "uuid", "provider_name" "text", "country_code" "text", "source_id" "uuid", "evidence_id" "uuid", "last_verified_at" timestamp with time zone, "updated_at" timestamp with time zone, "publication_status" "text", "identity_ok" boolean, "registration_count" integer, "campus_count" integer, "has_delivery" boolean, "taxonomy_complete" boolean, "taxonomy_ambiguous" boolean, "taxonomy_rejected" boolean, "reg_fee_count" integer, "reg_fee_value_count" integer, "reg_fee_zero_count" integer, "reg_fee_positive_count" integer, "reg_fee_source_id" "uuid", "reg_fee_evidence_id" "uuid", "provider_fee_count" integer, "provider_fee_value_count" integer, "provider_fee_zero_count" integer, "provider_fee_positive_count" integer, "provider_fee_suppressed" boolean, "provider_fee_rejected" boolean, "provider_fee_source_id" "uuid", "provider_fee_evidence_id" "uuid", "has_url" boolean, "url_suppressed" boolean, "url_rejected" boolean, "url_source_id" "uuid", "url_evidence_id" "uuid", "intake_count" integer, "intake_suppressed" boolean, "intake_rejected" boolean, "intake_source_id" "uuid", "intake_evidence_id" "uuid", "english_count" integer, "english_suppressed" boolean, "english_rejected" boolean, "english_source_id" "uuid", "english_evidence_id" "uuid", "scholarship_include_count" integer, "scholarship_exclude_count" integer, "evidence_count" integer, "search_projected" boolean, "search_status" "text", "channel_state_count" integer, "channel_published_count" integer, "channel_rejected_count" integer, "channel_distinct_status_count" integer, "review_domains" "text"[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'ref', 'scholarship', 'pipeline', 'workflow', 'search', 'publishing', 'auth'
    AS $$
with scope as materialized (
  select c.id,c.provider_id,c.stable_key,c.canonical_title,c.display_title,c.course_code,c.course_url,c.delivery_mode,
    c.study_level_id,c.primary_field_id,c.canonical_source_id,c.last_verified_at,c.updated_at,c.publication_status,
    co.iso_alpha2::text as country_code,coalesce(p.display_name,p.canonical_name) as provider_name
  from catalogue.courses c
  join catalogue.providers p on p.id=c.provider_id
  join ref.countries co on co.id=p.country_id
  where (p_country_code is null and co.iso_alpha2 in ('AU','NZ'))
     or (p_country_code is not null and co.iso_alpha2=upper(p_country_code))
), reg as (
  select r.course_id,
    count(*) filter(where coalesce(r.status,'active')='active')::int active_count,
    (array_agg(r.source_id order by r.valid_from desc nulls last,r.id) filter(where r.source_id is not null))[1] source_id,
    (array_agg(r.evidence_id order by r.valid_from desc nulls last,r.id) filter(where r.evidence_id is not null))[1] evidence_id
  from catalogue.course_registrations r join scope s on s.id=r.course_id group by r.course_id
), campus as (
  select cc.course_id,count(*)::int campus_count,
    bool_or(coalesce(nullif(btrim(cc.delivery_mode),''),null) is not null) has_delivery,
    (array_agg(cc.source_id order by cc.is_primary desc,cc.campus_id) filter(where cc.source_id is not null))[1] source_id,
    (array_agg(cc.evidence_id order by cc.is_primary desc,cc.campus_id) filter(where cc.evidence_id is not null))[1] evidence_id
  from catalogue.course_campuses cc join scope s on s.id=cc.course_id group by cc.course_id
), tax as (
  select o.course_id,
    bool_or(lower(o.mapping_status) in ('review_required','ambiguous')) filter(where o.status='current') ambiguous,
    bool_or(lower(o.mapping_status)='rejected') filter(where o.status='current') rejected
  from catalogue.course_study_level_observations o join scope s on s.id=o.course_id group by o.course_id
), fee as (
  select f.course_id,
    count(*) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active')::int reg_count,
    count(*) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active' and f.amount is not null)::int reg_values,
    count(*) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active' and f.amount=0)::int reg_zero,
    count(*) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active' and f.amount>0)::int reg_positive,
    (array_agg(f.source_id order by f.source_snapshot_at desc nulls last,f.created_at desc) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and f.source_id is not null))[1] reg_source_id,
    (array_agg(f.evidence_id order by f.source_snapshot_at desc nulls last,f.created_at desc) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and f.evidence_id is not null))[1] reg_evidence_id,
    count(*) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active')::int provider_count,
    count(*) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount is not null)::int provider_values,
    count(*) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount=0)::int provider_zero,
    count(*) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount>0)::int provider_positive,
    bool_or(lower(coalesce(f.status,''))='suppressed') filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course') provider_suppressed,
    bool_or(lower(coalesce(f.status,''))='rejected') filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course') provider_rejected,
    (array_agg(f.source_id order by f.source_snapshot_at desc nulls last,f.created_at desc) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and f.source_id is not null))[1] provider_source_id,
    (array_agg(f.evidence_id order by f.source_snapshot_at desc nulls last,f.created_at desc) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and f.evidence_id is not null))[1] provider_evidence_id
  from catalogue.course_fees f join scope s on s.id=f.course_id group by f.course_id
), link as (
  select l.course_id,
    count(*) filter(where lower(coalesce(l.status,'active'))='active')::int active_count,
    bool_or(lower(coalesce(l.status,''))='suppressed') suppressed,
    bool_or(lower(coalesce(l.status,''))='rejected') rejected,
    (array_agg(l.source_id order by l.is_primary desc,l.updated_at desc) filter(where l.source_id is not null))[1] source_id,
    (array_agg(l.evidence_id order by l.is_primary desc,l.updated_at desc) filter(where l.evidence_id is not null))[1] evidence_id
  from catalogue.course_links l join scope s on s.id=l.course_id where l.link_type = 'official_course' group by l.course_id
), intake as (
  select i.course_id,count(*) filter(where lower(coalesce(i.status,'active'))='active')::int active_count,
    bool_or(lower(coalesce(i.status,''))='suppressed') suppressed,
    bool_or(lower(coalesce(i.status,''))='rejected') rejected,
    (array_agg(i.source_id order by i.intake_year desc nulls last,i.start_date desc nulls last,i.id) filter(where i.source_id is not null))[1] source_id,
    (array_agg(i.evidence_id order by i.intake_year desc nulls last,i.start_date desc nulls last,i.id) filter(where i.evidence_id is not null))[1] evidence_id
  from catalogue.course_intakes i join scope s on s.id=i.course_id group by i.course_id
), english as (
  select e.course_id,count(*) filter(where lower(coalesce(e.status,'active'))='active')::int active_count,
    bool_or(lower(coalesce(e.status,''))='suppressed') suppressed,
    bool_or(lower(coalesce(e.status,''))='rejected') rejected,
    (array_agg(e.source_id order by e.last_verified_at desc nulls last,e.id) filter(where e.source_id is not null))[1] source_id,
    (array_agg(e.evidence_id order by e.last_verified_at desc nulls last,e.id) filter(where e.evidence_id is not null))[1] evidence_id
  from catalogue.course_english_requirements e join scope s on s.id=e.course_id group by e.course_id
), sch_course as (
  select sc.course_id,count(*) filter(where coalesce(sc.include_exclude,'include')='include')::int include_count,
    count(*) filter(where coalesce(sc.include_exclude,'include')='exclude')::int exclude_count
  from scholarship.scopes sc join scope s on s.id=sc.course_id where sc.course_id is not null group by sc.course_id
), sch_provider as (
  select sc.provider_id,count(*) filter(where coalesce(sc.include_exclude,'include')='include')::int include_count,
    count(*) filter(where coalesce(sc.include_exclude,'include')='exclude')::int exclude_count
  from scholarship.scopes sc join (select distinct provider_id from scope) p on p.provider_id=sc.provider_id
  where sc.scope_type='provider' and sc.provider_id is not null group by sc.provider_id
), ev as (
  select el.entity_id,count(distinct el.evidence_id)::int evidence_count,
    (array_agg(el.evidence_id order by el.updated_at desc))[1] evidence_id
  from pipeline.evidence_entity_links el join scope s on s.id=el.entity_id
  where el.entity_type='course' group by el.entity_id
), pub as (
  select es.entity_id,count(*)::int state_count,
    count(*) filter(where lower(es.publication_status)='published')::int published_count,
    count(*) filter(where lower(es.publication_status)='rejected')::int rejected_count,
    count(distinct lower(es.publication_status))::int distinct_status_count
  from publishing.entity_states es join scope s on s.id=es.entity_id group by es.entity_id
), rev as (
  select q.entity_id,array_agg(distinct lower(q.domain)) filter(where q.status in ('open','queued','pending','in_review')) review_domains
  from workflow.review_queue q join scope s on s.id=q.entity_id group by q.entity_id
)
select s.id,coalesce(s.display_title,s.canonical_title),s.stable_key,s.provider_id,s.provider_name,s.country_code,
  coalesce(s.canonical_source_id,reg.source_id),coalesce(ev.evidence_id,reg.evidence_id),s.last_verified_at,s.updated_at,s.publication_status,
  (s.stable_key is not null and btrim(s.stable_key)<>'' and s.canonical_title is not null and btrim(s.canonical_title)<>'' and s.course_code is not null and btrim(s.course_code)<>'' and s.provider_id is not null),
  coalesce(reg.active_count,0),coalesce(campus.campus_count,0),coalesce(campus.has_delivery,false) or coalesce(nullif(btrim(s.delivery_mode),''),null) is not null,
  (s.study_level_id is not null and s.primary_field_id is not null),coalesce(tax.ambiguous,false),coalesce(tax.rejected,false),
  coalesce(fee.reg_count,0),coalesce(fee.reg_values,0),coalesce(fee.reg_zero,0),coalesce(fee.reg_positive,0),fee.reg_source_id,fee.reg_evidence_id,
  coalesce(fee.provider_count,0),coalesce(fee.provider_values,0),coalesce(fee.provider_zero,0),coalesce(fee.provider_positive,0),coalesce(fee.provider_suppressed,false),coalesce(fee.provider_rejected,false),fee.provider_source_id,fee.provider_evidence_id,
  (coalesce(nullif(btrim(s.course_url),''),null) is not null or coalesce(link.active_count,0)>0),coalesce(link.suppressed,false),coalesce(link.rejected,false),coalesce(link.source_id,s.canonical_source_id),coalesce(link.evidence_id,ev.evidence_id),
  coalesce(intake.active_count,0),coalesce(intake.suppressed,false),coalesce(intake.rejected,false),intake.source_id,intake.evidence_id,
  coalesce(english.active_count,0),coalesce(english.suppressed,false),coalesce(english.rejected,false),english.source_id,english.evidence_id,
  coalesce(sch_course.include_count,0)+coalesce(sch_provider.include_count,0),coalesce(sch_course.exclude_count,0)+coalesce(sch_provider.exclude_count,0),coalesce(ev.evidence_count,0),
  (d.course_id is not null),d.publication_status,
  coalesce(pub.state_count,0),coalesce(pub.published_count,0),coalesce(pub.rejected_count,0),coalesce(pub.distinct_status_count,0),
  coalesce(rev.review_domains,'{}'::text[])
from scope s
left join reg on reg.course_id=s.id
left join campus on campus.course_id=s.id
left join tax on tax.course_id=s.id
left join fee on fee.course_id=s.id
left join link on link.course_id=s.id
left join intake on intake.course_id=s.id
left join english on english.course_id=s.id
left join sch_course on sch_course.course_id=s.id
left join sch_provider on sch_provider.provider_id=s.provider_id
left join ev on ev.entity_id=s.id
left join search.course_documents d on d.course_id=s.id
left join pub on pub.entity_id=s.id
left join rev on rev.entity_id=s.id
$$;


ALTER FUNCTION "security"."data_quality_course_base"("p_country_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_quality_exceptions_impl"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'ref', 'scholarship', 'pipeline', 'workflow', 'search', 'publishing'
    SET "work_mem" TO '128MB'
    AS $$
declare
 v_entity text:=lower(coalesce(nullif(p_args->>'entity_type',''),'course'));
 v_domain text:=lower(coalesce(nullif(p_args->>'domain',''),'identity_completeness'));
 v_state text:=lower(nullif(p_args->>'state',''));
 v_country text:=nullif(upper(btrim(coalesce(p_args->>'country_code',''))),'');
 v_query text:=nullif(btrim(coalesce(p_args->>'query','')),'');
 v_limit int:=least(greatest(coalesce(nullif(p_args->>'limit','')::int,50),1),200);
 v_offset int:=greatest(coalesce(nullif(p_args->>'offset','')::int,0),0);
 v_result jsonb;
begin
 if v_entity='course' then
  with scope as (
   select c.id,coalesce(c.display_title,c.canonical_title) entity_name,c.stable_key,c.provider_id,coalesce(p.display_name,p.canonical_name) provider_name,
    co.iso_alpha2::text country_code,c.canonical_source_id,c.last_verified_at,c.updated_at,c.publication_status,c.course_code,c.course_url,c.delivery_mode,c.study_level_id,c.primary_field_id
   from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
   where (v_country is null and co.iso_alpha2 in ('AU','NZ') or v_country is not null and co.iso_alpha2=v_country)
    and (v_query is null or c.canonical_title ilike '%'||v_query||'%' or coalesce(c.display_title,'') ilike '%'||v_query||'%' or coalesce(p.display_name,p.canonical_name,'') ilike '%'||v_query||'%' or c.stable_key ilike '%'||v_query||'%' or coalesce(c.course_code,'') ilike '%'||v_query||'%')
  ), classified as (
   select c.*,
    case v_domain
     when 'identity_completeness' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when c.stable_key is not null and btrim(c.stable_key)<>'' and c.entity_name is not null and btrim(c.entity_name)<>'' and c.course_code is not null and btrim(c.course_code)<>'' and c.provider_id is not null then 'present' else 'source_null' end
     when 'regulatory_completeness' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when exists(select 1 from catalogue.course_registrations r where r.course_id=c.id and coalesce(r.status,'active')='active') then 'present' else 'source_null' end
     when 'geography_delivery' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when exists(select 1 from catalogue.course_campuses cc where cc.course_id=c.id) and (coalesce(nullif(btrim(c.delivery_mode),''),null) is not null or exists(select 1 from catalogue.course_campuses cc where cc.course_id=c.id and coalesce(nullif(btrim(cc.delivery_mode),''),null) is not null)) then 'present'
      when c.country_code='AU' and not exists(select 1 from catalogue.course_campuses cc where cc.course_id=c.id) then 'source_null' else 'not_yet_enriched' end
     when 'taxonomy' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) or exists(select 1 from catalogue.course_study_level_observations o where o.course_id=c.id and o.status='current' and lower(o.mapping_status) in ('review_required','ambiguous')) then 'ambiguous'
      when exists(select 1 from catalogue.course_study_level_observations o where o.course_id=c.id and o.status='current' and lower(o.mapping_status)='rejected') then 'rejected'
      when c.study_level_id is not null and c.primary_field_id is not null then 'present' when c.country_code='AU' then 'source_null' else 'not_yet_enriched' end
     when 'regulatory_fee' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when c.country_code<>'AU' then 'not_applicable'
      when exists(select 1 from catalogue.course_fees f where f.course_id=c.id and f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active' and f.amount>0) then 'present'
      when exists(select 1 from catalogue.course_fees f where f.course_id=c.id and f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active' and f.amount=0) then 'zero'
      else 'source_null' end
     when 'provider_current_fee' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when exists(select 1 from catalogue.course_fees f where f.course_id=c.id and f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount>0) then 'present'
      when exists(select 1 from catalogue.course_fees f where f.course_id=c.id and f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount=0) then 'zero'
      when exists(select 1 from catalogue.course_fees f where f.course_id=c.id and f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount is null) then 'source_null'
      when exists(select 1 from catalogue.course_fees f where f.course_id=c.id and f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and lower(coalesce(f.status,''))='rejected') then 'rejected'
      when exists(select 1 from catalogue.course_fees f where f.course_id=c.id and f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and lower(coalesce(f.status,''))='suppressed') then 'suppressed'
      else 'not_yet_enriched' end
     when 'course_url' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when coalesce(nullif(btrim(c.course_url),''),null) is not null or exists(select 1 from catalogue.course_links l where l.link_type = 'official_course' and l.course_id=c.id and lower(coalesce(l.status,'active'))='active') then 'present'
      when exists(select 1 from catalogue.course_links l where l.link_type = 'official_course' and l.course_id=c.id and lower(coalesce(l.status,''))='rejected') then 'rejected'
      when exists(select 1 from catalogue.course_links l where l.link_type = 'official_course' and l.course_id=c.id and lower(coalesce(l.status,''))='suppressed') then 'suppressed'
      else 'not_yet_enriched' end
     when 'intake' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when exists(select 1 from catalogue.course_intakes i where i.course_id=c.id and lower(coalesce(i.status,'active'))='active') then 'present'
      when exists(select 1 from catalogue.course_intakes i where i.course_id=c.id and lower(coalesce(i.status,''))='rejected') then 'rejected'
      when exists(select 1 from catalogue.course_intakes i where i.course_id=c.id and lower(coalesce(i.status,''))='suppressed') then 'suppressed'
      else 'not_yet_enriched' end
     when 'english_requirement' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when exists(select 1 from catalogue.course_english_requirements e where e.course_id=c.id and lower(coalesce(e.status,'active'))='active') then 'present'
      when exists(select 1 from catalogue.course_english_requirements e where e.course_id=c.id and lower(coalesce(e.status,''))='rejected') then 'rejected'
      when exists(select 1 from catalogue.course_english_requirements e where e.course_id=c.id and lower(coalesce(e.status,''))='suppressed') then 'suppressed'
      else 'not_yet_enriched' end
     when 'scholarship' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when exists(select 1 from scholarship.scopes s where coalesce(s.include_exclude,'include')='include' and (s.course_id=c.id or (s.scope_type='provider' and s.provider_id=c.provider_id))) then 'present'
      when exists(select 1 from scholarship.scopes s where coalesce(s.include_exclude,'include')='exclude' and (s.course_id=c.id or (s.scope_type='provider' and s.provider_id=c.provider_id))) then 'not_applicable'
      else 'not_yet_enriched' end
     when 'evidence' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when exists(select 1 from pipeline.evidence_entity_links el where el.entity_type='course' and el.entity_id=c.id) then 'present' else 'not_yet_enriched' end
     when 'verification_freshness' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when c.last_verified_at is null or c.last_verified_at<now()-make_interval(days => security.pipeline_num_v1('data_quality.stale_after_days', 180)::int) then 'stale' else 'present' end
     when 'search_admission' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when exists(select 1 from search.course_documents d where d.course_id=c.id) then 'present' else 'not_yet_enriched' end
     when 'publication_readiness' then case
      when exists(select 1 from workflow.review_queue q where q.entity_id=c.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review')) then 'ambiguous'
      when (select count(distinct lower(es.publication_status)) from publishing.entity_states es where es.entity_id=c.id)>1 then 'ambiguous'
      when lower(coalesce(c.publication_status,''))='rejected' or exists(select 1 from publishing.entity_states es where es.entity_id=c.id and lower(es.publication_status)='rejected') then 'rejected'
      when lower(coalesce(c.publication_status,''))='published' or exists(select 1 from publishing.entity_states es where es.entity_id=c.id and lower(es.publication_status)='published') then 'present'
      else 'not_yet_enriched' end
     else null end state
   from scope c
  ), filtered as (
   select c.* from classified c where c.state is not null
    and ((v_state is not null and c.state=v_state) or (v_state is null and c.state in ('source_null','suppressed','not_yet_enriched','stale','ambiguous','rejected')))
  ), numbered as (select f.*,count(*) over() total_count from filtered f), paged0 as (
   select * from numbered order by case state when 'rejected' then 1 when 'ambiguous' then 2 when 'source_null' then 3 when 'suppressed' then 4 when 'stale' then 5 else 6 end,lower(entity_name),id limit v_limit offset v_offset
  ), paged as (
   select p.*,
    coalesce(
      case v_domain
       when 'regulatory_fee' then (select f.source_id from catalogue.course_fees f where f.course_id=p.id and f.basis='registered_total_course' and f.fee_type='tuition' and f.source_id is not null order by f.source_snapshot_at desc nulls last,f.created_at desc limit 1)
       when 'provider_current_fee' then (select f.source_id from catalogue.course_fees f where f.course_id=p.id and f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and f.source_id is not null order by f.source_snapshot_at desc nulls last,f.created_at desc limit 1)
       when 'course_url' then (select l.source_id from catalogue.course_links l where l.link_type = 'official_course' and l.course_id=p.id and l.source_id is not null order by l.is_primary desc,l.updated_at desc limit 1)
       when 'intake' then (select i.source_id from catalogue.course_intakes i where i.course_id=p.id and i.source_id is not null order by i.intake_year desc nulls last,i.start_date desc nulls last limit 1)
       when 'english_requirement' then (select e.source_id from catalogue.course_english_requirements e where e.course_id=p.id and e.source_id is not null order by e.last_verified_at desc nulls last limit 1)
       else null end,
      p.canonical_source_id,
      (select r.source_id from catalogue.course_registrations r where r.course_id=p.id and r.source_id is not null order by r.valid_from desc nulls last limit 1)
    ) domain_source_id,
    coalesce(
      case v_domain
       when 'regulatory_fee' then (select f.evidence_id from catalogue.course_fees f where f.course_id=p.id and f.basis='registered_total_course' and f.fee_type='tuition' and f.evidence_id is not null order by f.source_snapshot_at desc nulls last,f.created_at desc limit 1)
       when 'provider_current_fee' then (select f.evidence_id from catalogue.course_fees f where f.course_id=p.id and f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and f.evidence_id is not null order by f.source_snapshot_at desc nulls last,f.created_at desc limit 1)
       when 'course_url' then (select l.evidence_id from catalogue.course_links l where l.link_type = 'official_course' and l.course_id=p.id and l.evidence_id is not null order by l.is_primary desc,l.updated_at desc limit 1)
       when 'intake' then (select i.evidence_id from catalogue.course_intakes i where i.course_id=p.id and i.evidence_id is not null order by i.intake_year desc nulls last,i.start_date desc nulls last limit 1)
       when 'english_requirement' then (select e.evidence_id from catalogue.course_english_requirements e where e.course_id=p.id and e.evidence_id is not null order by e.last_verified_at desc nulls last limit 1)
       else null end,
      (select el.evidence_id from pipeline.evidence_entity_links el where el.entity_type='course' and el.entity_id=p.id order by el.updated_at desc limit 1),
      (select r.evidence_id from catalogue.course_registrations r where r.course_id=p.id and r.evidence_id is not null order by r.valid_from desc nulls last limit 1)
    ) domain_evidence_id
   from paged0 p
  )
  select jsonb_build_object('items',coalesce(jsonb_agg(jsonb_build_object(
    'entity_id',p.id,'entity_type','course','entity_name',p.entity_name,'stable_key',p.stable_key,'provider_id',p.provider_id,'provider_name',p.provider_name,'country_code',p.country_code,
    'domain',v_domain,'state',p.state,'source_id',p.domain_source_id,'source_label',src.label,'evidence_id',p.domain_evidence_id,
    'review_id',(select q.id from workflow.review_queue q where q.entity_id=p.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review') order by q.priority desc,q.created_at limit 1),
    'last_verified_at',p.last_verified_at,'updated_at',p.updated_at,'context',jsonb_build_object('canonical_publication',p.publication_status)
   ) order by lower(p.entity_name)),'[]'::jsonb),'total',coalesce(max(p.total_count),0),'limit',v_limit,'offset',v_offset,'entity_type','course','domain',v_domain,'state',v_state)
  into v_result from paged p left join pipeline.sources src on src.id=p.domain_source_id;
  return v_result;
 elsif v_entity='provider' then
  with classified as (
   select p.*,case v_domain when 'identity_completeness' then case when v_domain=any(p.review_domains) then 'ambiguous' when p.identity_ok then 'present' else 'source_null' end when 'regulatory_completeness' then case when v_domain=any(p.review_domains) then 'ambiguous' when p.registration_count>0 then 'present' else 'source_null' end when 'geography_delivery' then case when v_domain=any(p.review_domains) then 'ambiguous' when p.geography_present then 'present' else 'not_yet_enriched' end when 'evidence' then case when v_domain=any(p.review_domains) then 'ambiguous' when p.evidence_count>0 then 'present' else 'not_yet_enriched' end when 'verification_freshness' then case when v_domain=any(p.review_domains) then 'ambiguous' when p.last_verified_at is null or p.last_verified_at<now()-make_interval(days => security.pipeline_num_v1('data_quality.stale_after_days', 180)::int) then 'stale' else 'present' end when 'publication_readiness' then case when v_domain=any(p.review_domains) then 'ambiguous' when p.channel_rejected_count>0 or lower(coalesce(p.publication_status,''))='rejected' then 'rejected' when p.channel_distinct_status_count>1 then 'ambiguous' when p.channel_published_count>0 or lower(coalesce(p.publication_status,''))='published' then 'present' else 'not_yet_enriched' end else null end state from security.data_quality_provider_base(v_country) p
  ), filtered as (select p.* from classified p where p.state is not null and ((v_state is not null and p.state=v_state) or (v_state is null and p.state in ('source_null','suppressed','not_yet_enriched','stale','ambiguous','rejected'))) and (v_query is null or p.entity_name ilike '%'||v_query||'%' or p.stable_key ilike '%'||v_query||'%')), numbered as (select f.*,count(*) over() total_count from filtered f), paged as (select * from numbered order by lower(entity_name),id limit v_limit offset v_offset)
  select jsonb_build_object('items',coalesce(jsonb_agg(jsonb_build_object('entity_id',p.id,'entity_type','provider','entity_name',p.entity_name,'stable_key',p.stable_key,'country_code',p.country_code,'domain',v_domain,'state',p.state,'source_id',p.source_id,'source_label',src.label,'evidence_id',p.evidence_id,'review_id',(select q.id from workflow.review_queue q where q.entity_id=p.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review') order by q.priority desc,q.created_at limit 1),'last_verified_at',p.last_verified_at,'updated_at',p.updated_at) order by lower(p.entity_name)),'[]'::jsonb),'total',coalesce(max(p.total_count),0),'limit',v_limit,'offset',v_offset,'entity_type','provider','domain',v_domain,'state',v_state) into v_result from paged p left join pipeline.sources src on src.id=p.source_id; return v_result;
 elsif v_entity='campus' then
  with classified as (
   select c.*,case v_domain when 'identity_completeness' then case when v_domain=any(c.review_domains) then 'ambiguous' when c.identity_ok then 'present' else 'source_null' end when 'geography_delivery' then case when v_domain=any(c.review_domains) then 'ambiguous' when c.geography_present then 'present' else 'source_null' end when 'evidence' then case when v_domain=any(c.review_domains) then 'ambiguous' when c.evidence_count>0 then 'present' else 'not_yet_enriched' end when 'verification_freshness' then case when v_domain=any(c.review_domains) then 'ambiguous' when c.last_verified_at is null or c.last_verified_at<now()-make_interval(days => security.pipeline_num_v1('data_quality.stale_after_days', 180)::int) then 'stale' else 'present' end when 'publication_readiness' then case when v_domain=any(c.review_domains) then 'ambiguous' when c.channel_rejected_count>0 or lower(coalesce(c.publication_status,''))='rejected' then 'rejected' when c.channel_distinct_status_count>1 then 'ambiguous' when c.channel_published_count>0 or lower(coalesce(c.publication_status,''))='published' then 'present' else 'not_yet_enriched' end else null end state from security.data_quality_campus_base(v_country) c
  ), filtered as (select c.* from classified c where c.state is not null and ((v_state is not null and c.state=v_state) or (v_state is null and c.state in ('source_null','suppressed','not_yet_enriched','stale','ambiguous','rejected'))) and (v_query is null or c.entity_name ilike '%'||v_query||'%' or c.provider_name ilike '%'||v_query||'%' or c.stable_key ilike '%'||v_query||'%')), numbered as (select f.*,count(*) over() total_count from filtered f), paged as (select * from numbered order by lower(entity_name),id limit v_limit offset v_offset)
  select jsonb_build_object('items',coalesce(jsonb_agg(jsonb_build_object('entity_id',p.id,'entity_type','campus','entity_name',p.entity_name,'stable_key',p.stable_key,'provider_id',p.provider_id,'provider_name',p.provider_name,'country_code',p.country_code,'domain',v_domain,'state',p.state,'source_id',p.source_id,'source_label',src.label,'evidence_id',p.evidence_id,'review_id',(select q.id from workflow.review_queue q where q.entity_id=p.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review') order by q.priority desc,q.created_at limit 1),'last_verified_at',p.last_verified_at,'updated_at',p.updated_at) order by lower(p.entity_name)),'[]'::jsonb),'total',coalesce(max(p.total_count),0),'limit',v_limit,'offset',v_offset,'entity_type','campus','domain',v_domain,'state',v_state) into v_result from paged p left join pipeline.sources src on src.id=p.source_id; return v_result;
 elsif v_entity='scholarship' then
  with classified as (
   select s.*,case v_domain when 'identity_completeness' then case when v_domain=any(s.review_domains) then 'ambiguous' when s.identity_ok then 'present' else 'source_null' end when 'scholarship' then case when v_domain=any(s.review_domains) then 'ambiguous' when s.semantic_present then 'present' else 'not_yet_enriched' end when 'evidence' then case when v_domain=any(s.review_domains) then 'ambiguous' when s.evidence_count>0 then 'present' else 'not_yet_enriched' end when 'verification_freshness' then case when v_domain=any(s.review_domains) then 'ambiguous' else 'not_yet_enriched' end when 'publication_readiness' then case when v_domain=any(s.review_domains) then 'ambiguous' when s.channel_rejected_count>0 or lower(coalesce(s.publication_status,''))='rejected' then 'rejected' when s.channel_distinct_status_count>1 then 'ambiguous' when s.channel_published_count>0 or lower(coalesce(s.publication_status,''))='published' then 'present' else 'not_yet_enriched' end else null end state from security.data_quality_scholarship_base(v_country) s
  ), filtered as (select s.* from classified s where s.state is not null and ((v_state is not null and s.state=v_state) or (v_state is null and s.state in ('source_null','suppressed','not_yet_enriched','stale','ambiguous','rejected'))) and (v_query is null or s.entity_name ilike '%'||v_query||'%' or coalesce(s.provider_name,'') ilike '%'||v_query||'%' or s.stable_key ilike '%'||v_query||'%')), numbered as (select f.*,count(*) over() total_count from filtered f), paged as (select * from numbered order by lower(entity_name),id limit v_limit offset v_offset)
  select jsonb_build_object('items',coalesce(jsonb_agg(jsonb_build_object('entity_id',p.id,'entity_type','scholarship','entity_name',p.entity_name,'stable_key',p.stable_key,'provider_id',p.provider_id,'provider_name',p.provider_name,'country_code',p.country_code,'domain',v_domain,'state',p.state,'source_id',p.source_id,'source_label',src.label,'evidence_id',p.evidence_id,'review_id',(select q.id from workflow.review_queue q where q.entity_id=p.id and lower(q.domain)=v_domain and q.status in ('open','queued','pending','in_review') order by q.priority desc,q.created_at limit 1),'updated_at',p.updated_at) order by lower(p.entity_name)),'[]'::jsonb),'total',coalesce(max(p.total_count),0),'limit',v_limit,'offset',v_offset,'entity_type','scholarship','domain',v_domain,'state',v_state) into v_result from paged p left join pipeline.sources src on src.id=p.source_id; return v_result;
 else raise exception 'unsupported data quality entity type: %',v_entity using errcode='22023'; end if;
end
$$;


ALTER FUNCTION "security"."data_quality_exceptions_impl"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_quality_overview_cached"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$
declare
  v_country text:=nullif(upper(btrim(coalesce(p_args->>'country_code',''))),'');
  v_scope text;
  v_row security.data_quality_overview_snapshots%rowtype;
  v_reason text;
begin
  if v_country is not null and not (v_country = any(security.catalogue_country_codes_v1())) then
    raise exception 'unsupported Data Quality country scope: %',v_country using errcode='22023';
  end if;
  v_scope:=coalesce(v_country,'AU+NZ');
  select * into v_row from security.data_quality_overview_snapshots where scope_code=v_scope;
  if not found and v_country is not null then
    -- stored snapshots: AU+NZ, AU and NZ (the snapshot table's check). Another catalogue country is computed when opened (Canada about 2 s).
    return security.data_quality_overview_impl(jsonb_build_object('country_code',v_country))
      || jsonb_build_object('scope_countries',to_jsonb(security.catalogue_country_codes_v1()),
           'snapshot',jsonb_build_object('scope_code',v_country,'computed_at',now(),'refresh_mode','computed_when_opened','live_drilldown',true));
  end if;
  if not found then
    raise exception 'Data Quality overview snapshot unavailable for scope %',v_scope using errcode='55000';
  end if;
  v_reason:=coalesce(v_row.payload#>>'{policy,reason}','Domain readiness is reported by governed domain.')
    ||' Aggregate snapshot computed at '||v_row.computed_at::text
    ||'; refreshed off-peak daily and after explicit post-ingestion refresh; exception drill-down is live.';
  return jsonb_set(v_row.payload,'{policy,reason}',to_jsonb(v_reason),true)
    || jsonb_build_object('scope_countries',to_jsonb(security.catalogue_country_codes_v1()),'snapshot',jsonb_build_object('scope_code',v_row.scope_code,'computed_at',v_row.computed_at,'compute_duration_ms',v_row.compute_duration_ms,'refresh_interval_minutes',1440,'refresh_mode','off_peak_daily_plus_explicit_post_ingestion','live_drilldown',true));
end
$$;


ALTER FUNCTION "security"."data_quality_overview_cached"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_quality_overview_impl"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'ref', 'scholarship', 'pipeline', 'workflow', 'search', 'publishing'
    SET "work_mem" TO '128MB'
    AS $$
with params as (select nullif(upper(btrim(coalesce(p_args->>'country_code',''))),'') country_code),
course_scope as materialized (
 select c.id,c.provider_id,c.stable_key,c.canonical_title,c.course_code,c.course_url,c.delivery_mode,c.study_level_id,c.primary_field_id,c.last_verified_at,c.publication_status,
        co.iso_alpha2::text country_code
 from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
 where (((select country_code from params) is null and co.iso_alpha2 in ('AU','NZ')) or co.iso_alpha2=(select country_code from params))
), course_reg as (select r.course_id,count(*) filter(where coalesce(r.status,'active')='active')::int n from catalogue.course_registrations r join course_scope c on c.id=r.course_id group by r.course_id),
course_geo as (select cc.course_id,count(*)::int n,bool_or(coalesce(nullif(btrim(cc.delivery_mode),''),null) is not null) has_delivery from catalogue.course_campuses cc join course_scope c on c.id=cc.course_id group by cc.course_id),
course_tax as (select o.course_id,bool_or(lower(o.mapping_status) in ('review_required','ambiguous')) filter(where o.status='current') ambiguous,bool_or(lower(o.mapping_status)='rejected') filter(where o.status='current') rejected from catalogue.course_study_level_observations o join course_scope c on c.id=o.course_id group by o.course_id),
reg_fee as (select f.course_id,count(*) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active')::int n,count(*) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active' and f.amount is not null)::int values_n,count(*) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active' and f.amount=0)::int zeros,count(*) filter(where f.basis='registered_total_course' and f.fee_type='tuition' and coalesce(f.status,'active')='active' and f.amount>0)::int positives from catalogue.course_fees f join course_scope c on c.id=f.course_id group by f.course_id),
provider_fee as (select f.course_id,count(*) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active')::int n,count(*) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount is not null)::int values_n,count(*) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount=0)::int zeros,count(*) filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course' and coalesce(f.status,'active')='active' and f.amount>0)::int positives,bool_or(lower(coalesce(f.status,''))='suppressed') filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course') suppressed,bool_or(lower(coalesce(f.status,''))='rejected') filter(where f.fee_type='provider_current_tuition' and f.basis is distinct from 'registered_total_course') rejected from catalogue.course_fees f join course_scope c on c.id=f.course_id group by f.course_id),
course_link as (select l.course_id,count(*) filter(where lower(coalesce(l.status,'active'))='active')::int n,bool_or(lower(coalesce(l.status,''))='suppressed') suppressed,bool_or(lower(coalesce(l.status,''))='rejected') rejected from catalogue.course_links l join course_scope c on c.id=l.course_id where l.link_type = 'official_course' group by l.course_id),
course_intake as (select i.course_id,count(*) filter(where lower(coalesce(i.status,'active'))='active')::int n,bool_or(lower(coalesce(i.status,''))='suppressed') suppressed,bool_or(lower(coalesce(i.status,''))='rejected') rejected from catalogue.course_intakes i join course_scope c on c.id=i.course_id group by i.course_id),
course_english as (select e.course_id,count(*) filter(where lower(coalesce(e.status,'active'))='active')::int n,bool_or(lower(coalesce(e.status,''))='suppressed') suppressed,bool_or(lower(coalesce(e.status,''))='rejected') rejected from catalogue.course_english_requirements e join course_scope c on c.id=e.course_id group by e.course_id),
sch_course as (select sc.course_id,count(*) filter(where coalesce(sc.include_exclude,'include')='include')::int inc,count(*) filter(where coalesce(sc.include_exclude,'include')='exclude')::int exc from scholarship.scopes sc join course_scope c on c.id=sc.course_id where sc.course_id is not null group by sc.course_id),
sch_provider as (select sc.provider_id,count(*) filter(where coalesce(sc.include_exclude,'include')='include')::int inc,count(*) filter(where coalesce(sc.include_exclude,'include')='exclude')::int exc from scholarship.scopes sc join (select distinct provider_id from course_scope) p on p.provider_id=sc.provider_id where sc.scope_type='provider' and sc.provider_id is not null group by sc.provider_id),
course_ev as (select el.entity_id,count(distinct el.evidence_id)::int n from pipeline.evidence_entity_links el join course_scope c on c.id=el.entity_id where el.entity_type='course' group by el.entity_id),
course_pub as (select es.entity_id,count(*)::int n,count(*) filter(where lower(es.publication_status)='published')::int published,count(*) filter(where lower(es.publication_status)='rejected')::int rejected,count(distinct lower(es.publication_status))::int statuses from publishing.entity_states es join course_scope c on c.id=es.entity_id group by es.entity_id),
course_rev as (select q.entity_id,array_agg(distinct lower(q.domain)) filter(where q.status in ('open','queued','pending','in_review')) domains from workflow.review_queue q join course_scope c on c.id=q.entity_id group by q.entity_id),
course_flags as materialized (
 select c.*,
  (c.stable_key is not null and btrim(c.stable_key)<>'' and c.canonical_title is not null and btrim(c.canonical_title)<>'' and c.course_code is not null and btrim(c.course_code)<>'' and c.provider_id is not null) identity_ok,
  coalesce(r.n,0) reg_n,coalesce(g.n,0) campus_n,(coalesce(g.has_delivery,false) or coalesce(nullif(btrim(c.delivery_mode),''),null) is not null) has_delivery,
  (c.study_level_id is not null and c.primary_field_id is not null) taxonomy_complete,coalesce(t.ambiguous,false) taxonomy_ambiguous,coalesce(t.rejected,false) taxonomy_rejected,
  coalesce(rf.n,0) reg_fee_n,coalesce(rf.values_n,0) reg_fee_values,coalesce(rf.zeros,0) reg_fee_zero,coalesce(rf.positives,0) reg_fee_positive,
  coalesce(pf.n,0) provider_fee_n,coalesce(pf.values_n,0) provider_fee_values,coalesce(pf.zeros,0) provider_fee_zero,coalesce(pf.positives,0) provider_fee_positive,coalesce(pf.suppressed,false) provider_fee_suppressed,coalesce(pf.rejected,false) provider_fee_rejected,
  (coalesce(nullif(btrim(c.course_url),''),null) is not null or coalesce(cl.n,0)>0) has_url,coalesce(cl.suppressed,false) url_suppressed,coalesce(cl.rejected,false) url_rejected,
  coalesce(ci.n,0) intake_n,coalesce(ci.suppressed,false) intake_suppressed,coalesce(ci.rejected,false) intake_rejected,
  coalesce(ce.n,0) english_n,coalesce(ce.suppressed,false) english_suppressed,coalesce(ce.rejected,false) english_rejected,
  coalesce(sc.inc,0)+coalesce(sp.inc,0) scholarship_inc,coalesce(sc.exc,0)+coalesce(sp.exc,0) scholarship_exc,
  coalesce(ev.n,0) evidence_n,(sd.course_id is not null) search_projected,
  coalesce(cp.n,0) channel_n,coalesce(cp.published,0) channel_published,coalesce(cp.rejected,0) channel_rejected,coalesce(cp.statuses,0) channel_statuses,
  coalesce(rv.domains,'{}'::text[]) review_domains
 from course_scope c left join course_reg r on r.course_id=c.id left join course_geo g on g.course_id=c.id left join course_tax t on t.course_id=c.id left join reg_fee rf on rf.course_id=c.id left join provider_fee pf on pf.course_id=c.id left join course_link cl on cl.course_id=c.id left join course_intake ci on ci.course_id=c.id left join course_english ce on ce.course_id=c.id left join sch_course sc on sc.course_id=c.id left join sch_provider sp on sp.provider_id=c.provider_id left join course_ev ev on ev.entity_id=c.id left join search.course_documents sd on sd.course_id=c.id left join course_pub cp on cp.entity_id=c.id left join course_rev rv on rv.entity_id=c.id
),
provider_scope as materialized (select p.id,p.stable_key,p.canonical_name,p.country_id,p.subdivision_id,p.primary_city,p.address_line1,p.last_verified_at,p.publication_status,co.iso_alpha2::text country_code from catalogue.providers p join ref.countries co on co.id=p.country_id where (((select country_code from params) is null and co.iso_alpha2 in ('AU','NZ')) or co.iso_alpha2=(select country_code from params))),
provider_reg as (select r.provider_id,count(*) filter(where coalesce(r.status,'active')='active')::int n from catalogue.provider_registrations r join provider_scope p on p.id=r.provider_id group by r.provider_id),
provider_ev as (select el.entity_id,count(distinct el.evidence_id)::int n from pipeline.evidence_entity_links el join provider_scope p on p.id=el.entity_id where el.entity_type='provider' group by el.entity_id),
provider_pub as (select es.entity_id,count(*)::int n,count(*) filter(where lower(es.publication_status)='published')::int published,count(*) filter(where lower(es.publication_status)='rejected')::int rejected,count(distinct lower(es.publication_status))::int statuses from publishing.entity_states es join provider_scope p on p.id=es.entity_id group by es.entity_id),
provider_rev as (select q.entity_id,array_agg(distinct lower(q.domain)) filter(where q.status in ('open','queued','pending','in_review')) domains from workflow.review_queue q join provider_scope p on p.id=q.entity_id group by q.entity_id),
provider_flags as materialized (select p.*,(p.stable_key is not null and btrim(p.stable_key)<>'' and p.canonical_name is not null and btrim(p.canonical_name)<>'' and p.country_id is not null) identity_ok,coalesce(r.n,0) reg_n,(p.subdivision_id is not null or coalesce(nullif(btrim(p.primary_city),''),null) is not null or coalesce(nullif(btrim(p.address_line1),''),null) is not null) geography_present,coalesce(e.n,0) evidence_n,coalesce(pb.n,0) channel_n,coalesce(pb.published,0) channel_published,coalesce(pb.rejected,0) channel_rejected,coalesce(pb.statuses,0) channel_statuses,coalesce(rv.domains,'{}'::text[]) review_domains from provider_scope p left join provider_reg r on r.provider_id=p.id left join provider_ev e on e.entity_id=p.id left join provider_pub pb on pb.entity_id=p.id left join provider_rev rv on rv.entity_id=p.id),
campus_scope as materialized (select ca.id,ca.stable_key,ca.name,ca.provider_id,ca.country_id,ca.subdivision_id,ca.city,ca.address_line1,ca.latitude,ca.longitude,ca.evidence_id,ca.last_verified_at,ca.publication_status,co.iso_alpha2::text country_code from catalogue.campuses ca join ref.countries co on co.id=ca.country_id where (((select country_code from params) is null and co.iso_alpha2 in ('AU','NZ')) or co.iso_alpha2=(select country_code from params))),
campus_ev as (select el.entity_id,count(distinct el.evidence_id)::int n from pipeline.evidence_entity_links el join campus_scope c on c.id=el.entity_id where el.entity_type='campus' group by el.entity_id),
campus_pub as (select es.entity_id,count(*)::int n,count(*) filter(where lower(es.publication_status)='published')::int published,count(*) filter(where lower(es.publication_status)='rejected')::int rejected,count(distinct lower(es.publication_status))::int statuses from publishing.entity_states es join campus_scope c on c.id=es.entity_id group by es.entity_id),
campus_rev as (select q.entity_id,array_agg(distinct lower(q.domain)) filter(where q.status in ('open','queued','pending','in_review')) domains from workflow.review_queue q join campus_scope c on c.id=q.entity_id group by q.entity_id),
campus_flags as materialized (select c.*,(c.stable_key is not null and btrim(c.stable_key)<>'' and c.name is not null and btrim(c.name)<>'' and c.provider_id is not null and c.country_id is not null) identity_ok,(c.subdivision_id is not null or coalesce(nullif(btrim(c.city),''),null) is not null or coalesce(nullif(btrim(c.address_line1),''),null) is not null or (c.latitude is not null and c.longitude is not null)) geography_present,coalesce(e.n,case when c.evidence_id is not null then 1 else 0 end) evidence_n,coalesce(pb.n,0) channel_n,coalesce(pb.published,0) channel_published,coalesce(pb.rejected,0) channel_rejected,coalesce(pb.statuses,0) channel_statuses,coalesce(rv.domains,'{}'::text[]) review_domains from campus_scope c left join campus_ev e on e.entity_id=c.id left join campus_pub pb on pb.entity_id=c.id left join campus_rev rv on rv.entity_id=c.id),
scholarship_scope as materialized (select s.id,s.stable_key,s.name,s.provider_id,s.description,s.source_url,s.evidence_id,s.publication_status,coalesce(pc.iso_alpha2::text,sc.iso_alpha2::text) country_code from scholarship.scholarships s left join catalogue.providers p on p.id=s.provider_id left join ref.countries pc on pc.id=p.country_id left join pipeline.sources src on src.id=s.source_id left join ref.countries sc on sc.id=src.country_id where ((((select country_code from params) is null) and coalesce(pc.iso_alpha2::text,sc.iso_alpha2::text) in ('AU','NZ')) or coalesce(pc.iso_alpha2::text,sc.iso_alpha2::text)=(select country_code from params))),
sch_scope as (select sc.scholarship_id,count(*) filter(where coalesce(sc.include_exclude,'include')='include')::int inc from scholarship.scopes sc join scholarship_scope s on s.id=sc.scholarship_id group by sc.scholarship_id),
sch_ev as (select el.entity_id,count(distinct el.evidence_id)::int n from pipeline.evidence_entity_links el join scholarship_scope s on s.id=el.entity_id where el.entity_type='scholarship' group by el.entity_id),
sch_pub as (select es.entity_id,count(*)::int n,count(*) filter(where lower(es.publication_status)='published')::int published,count(*) filter(where lower(es.publication_status)='rejected')::int rejected,count(distinct lower(es.publication_status))::int statuses from publishing.entity_states es join scholarship_scope s on s.id=es.entity_id group by es.entity_id),
sch_rev as (select q.entity_id,array_agg(distinct lower(q.domain)) filter(where q.status in ('open','queued','pending','in_review')) domains from workflow.review_queue q join scholarship_scope s on s.id=q.entity_id group by q.entity_id),
sch_flags as materialized (select s.*,(s.stable_key is not null and btrim(s.stable_key)<>'' and s.name is not null and btrim(s.name)<>'') identity_ok,(coalesce(nullif(btrim(s.description),''),null) is not null and coalesce(nullif(btrim(s.source_url),''),null) is not null and s.evidence_id is not null and (coalesce(ss.inc,0)>0 or s.provider_id is null)) semantic_present,coalesce(e.n,case when s.evidence_id is not null then 1 else 0 end) evidence_n,coalesce(pb.n,0) channel_n,coalesce(pb.published,0) channel_published,coalesce(pb.rejected,0) channel_rejected,coalesce(pb.statuses,0) channel_statuses,coalesce(rv.domains,'{}'::text[]) review_domains from scholarship_scope s left join sch_scope ss on ss.scholarship_id=s.id left join sch_ev e on e.entity_id=s.id left join sch_pub pb on pb.entity_id=s.id left join sch_rev rv on rv.entity_id=s.id),
all_states as (
 select 'course'::text entity_type,v.domain,v.state from course_flags c cross join lateral (values
  ('identity_completeness',case when 'identity_completeness'=any(c.review_domains) then 'ambiguous' when c.identity_ok then 'present' else 'source_null' end),
  ('regulatory_completeness',case when 'regulatory_completeness'=any(c.review_domains) then 'ambiguous' when c.reg_n>0 then 'present' else 'source_null' end),
  ('geography_delivery',case when 'geography_delivery'=any(c.review_domains) then 'ambiguous' when c.campus_n>0 and c.has_delivery then 'present' when c.country_code='AU' and c.campus_n=0 then 'source_null' else 'not_yet_enriched' end),
  ('taxonomy',case when 'taxonomy'=any(c.review_domains) or c.taxonomy_ambiguous then 'ambiguous' when c.taxonomy_rejected then 'rejected' when c.taxonomy_complete then 'present' when c.country_code='AU' then 'source_null' else 'not_yet_enriched' end),
  ('regulatory_fee',case when 'regulatory_fee'=any(c.review_domains) then 'ambiguous' when c.country_code<>'AU' then 'not_applicable' when c.reg_fee_n=0 or c.reg_fee_values=0 then 'source_null' when c.reg_fee_positive>0 then 'present' when c.reg_fee_zero>0 then 'zero' else 'source_null' end),
  ('provider_current_fee',case when 'provider_current_fee'=any(c.review_domains) then 'ambiguous' when c.provider_fee_rejected then 'rejected' when c.provider_fee_suppressed and c.provider_fee_n=0 then 'suppressed' when c.provider_fee_n=0 then 'not_yet_enriched' when c.provider_fee_values=0 then 'source_null' when c.provider_fee_positive>0 then 'present' when c.provider_fee_zero>0 then 'zero' else 'source_null' end),
  ('course_url',case when 'course_url'=any(c.review_domains) then 'ambiguous' when c.url_rejected then 'rejected' when c.url_suppressed and not c.has_url then 'suppressed' when c.has_url then 'present' else 'not_yet_enriched' end),
  ('intake',case when 'intake'=any(c.review_domains) then 'ambiguous' when c.intake_rejected then 'rejected' when c.intake_suppressed and c.intake_n=0 then 'suppressed' when c.intake_n>0 then 'present' else 'not_yet_enriched' end),
  ('english_requirement',case when 'english_requirement'=any(c.review_domains) then 'ambiguous' when c.english_rejected then 'rejected' when c.english_suppressed and c.english_n=0 then 'suppressed' when c.english_n>0 then 'present' else 'not_yet_enriched' end),
  ('scholarship',case when 'scholarship'=any(c.review_domains) then 'ambiguous' when c.scholarship_inc>0 then 'present' when c.scholarship_exc>0 then 'not_applicable' else 'not_yet_enriched' end),
  ('evidence',case when 'evidence'=any(c.review_domains) then 'ambiguous' when c.evidence_n>0 then 'present' else 'not_yet_enriched' end),
  ('verification_freshness',case when 'verification_freshness'=any(c.review_domains) then 'ambiguous' when c.last_verified_at is null or c.last_verified_at<now()-make_interval(days => security.pipeline_num_v1('data_quality.stale_after_days', 180)::int) then 'stale' else 'present' end),
  ('search_admission',case when 'search_admission'=any(c.review_domains) then 'ambiguous' when c.search_projected then 'present' else 'not_yet_enriched' end),
  ('publication_readiness',case when 'publication_readiness'=any(c.review_domains) then 'ambiguous' when c.channel_rejected>0 or lower(coalesce(c.publication_status,''))='rejected' then 'rejected' when c.channel_statuses>1 then 'ambiguous' when c.channel_published>0 or lower(coalesce(c.publication_status,''))='published' then 'present' else 'not_yet_enriched' end)
 ) v(domain,state)
 union all select 'provider',v.domain,v.state from provider_flags p cross join lateral (values
  ('identity_completeness',case when 'identity_completeness'=any(p.review_domains) then 'ambiguous' when p.identity_ok then 'present' else 'source_null' end),
  ('regulatory_completeness',case when 'regulatory_completeness'=any(p.review_domains) then 'ambiguous' when p.reg_n>0 then 'present' else 'source_null' end),
  ('geography_delivery',case when 'geography_delivery'=any(p.review_domains) then 'ambiguous' when p.geography_present then 'present' else 'not_yet_enriched' end),
  ('evidence',case when 'evidence'=any(p.review_domains) then 'ambiguous' when p.evidence_n>0 then 'present' else 'not_yet_enriched' end),
  ('verification_freshness',case when 'verification_freshness'=any(p.review_domains) then 'ambiguous' when p.last_verified_at is null or p.last_verified_at<now()-make_interval(days => security.pipeline_num_v1('data_quality.stale_after_days', 180)::int) then 'stale' else 'present' end),
  ('publication_readiness',case when 'publication_readiness'=any(p.review_domains) then 'ambiguous' when p.channel_rejected>0 or lower(coalesce(p.publication_status,''))='rejected' then 'rejected' when p.channel_statuses>1 then 'ambiguous' when p.channel_published>0 or lower(coalesce(p.publication_status,''))='published' then 'present' else 'not_yet_enriched' end)
 ) v(domain,state)
 union all select 'campus',v.domain,v.state from campus_flags c cross join lateral (values
  ('identity_completeness',case when 'identity_completeness'=any(c.review_domains) then 'ambiguous' when c.identity_ok then 'present' else 'source_null' end),
  ('geography_delivery',case when 'geography_delivery'=any(c.review_domains) then 'ambiguous' when c.geography_present then 'present' else 'source_null' end),
  ('evidence',case when 'evidence'=any(c.review_domains) then 'ambiguous' when c.evidence_n>0 then 'present' else 'not_yet_enriched' end),
  ('verification_freshness',case when 'verification_freshness'=any(c.review_domains) then 'ambiguous' when c.last_verified_at is null or c.last_verified_at<now()-make_interval(days => security.pipeline_num_v1('data_quality.stale_after_days', 180)::int) then 'stale' else 'present' end),
  ('publication_readiness',case when 'publication_readiness'=any(c.review_domains) then 'ambiguous' when c.channel_rejected>0 or lower(coalesce(c.publication_status,''))='rejected' then 'rejected' when c.channel_statuses>1 then 'ambiguous' when c.channel_published>0 or lower(coalesce(c.publication_status,''))='published' then 'present' else 'not_yet_enriched' end)
 ) v(domain,state)
 union all select 'scholarship',v.domain,v.state from sch_flags s cross join lateral (values
  ('identity_completeness',case when 'identity_completeness'=any(s.review_domains) then 'ambiguous' when s.identity_ok then 'present' else 'source_null' end),
  ('scholarship',case when 'scholarship'=any(s.review_domains) then 'ambiguous' when s.semantic_present then 'present' else 'not_yet_enriched' end),
  ('evidence',case when 'evidence'=any(s.review_domains) then 'ambiguous' when s.evidence_n>0 then 'present' else 'not_yet_enriched' end),
  ('verification_freshness',case when 'verification_freshness'=any(s.review_domains) then 'ambiguous' else 'not_yet_enriched' end),
  ('publication_readiness',case when 'publication_readiness'=any(s.review_domains) then 'ambiguous' when s.channel_rejected>0 or lower(coalesce(s.publication_status,''))='rejected' then 'rejected' when s.channel_statuses>1 then 'ambiguous' when s.channel_published>0 or lower(coalesce(s.publication_status,''))='published' then 'present' else 'not_yet_enriched' end)
 ) v(domain,state)
), defs(domain,label,sort_order,definition,authority) as (values
 ('identity_completeness','Identity completeness',10,'Stable governed identity fields required to resolve the entity without title/name inference.','Layer 1 canonical identity'),('regulatory_completeness','Regulatory completeness',20,'Current authoritative registration/Layer 1 regulatory presence; country-specific authority is preserved.','CRICOS / NZQA Layer 1'),('geography_delivery','Geography / delivery',30,'Provider/Campus geography and Course delivery relationships remain distinct. AU CRICOS source-absent Course Locations are not synthesised.','Layer 1 location authority / later enrichment'),('taxonomy','Taxonomy',40,'Governed Study Level and Field mappings; ambiguous/rejected source mappings remain exceptions.','Governed reference taxonomy'),('regulatory_fee','Regulatory fee',50,'AU CRICOS registered total-course tuition only. NZ has no CRICOS-equivalent fee dimension in the accepted Layer 1 contract.','CRICOS regulatory source'),('provider_current_fee','Current Provider fee',60,'Current Provider-published fee observations remain separate from CRICOS registered total-course fees.','Layer 2 Provider first-party source'),('course_url','Course URL',70,'Official Course URL/link enrichment; absence before a successful enrichment is not treated as source-null.','Layer 2 Provider first-party source'),('intake','Intake',80,'Provider-current intake observations with suppression/rejection retained distinctly.','Layer 2 Provider first-party source'),('english_requirement','English requirement',90,'Provider-current English entry requirements with suppression/rejection retained distinctly.','Layer 2 Provider first-party source'),('scholarship','Scholarship',100,'Relational Scholarship applicability; no scholarship relationship is not treated as a canonical Course defect.','Layer 2 Scholarship sources'),('evidence','Evidence',110,'Presence of governed evidence lineage for the canonical/enrichment entity.','Evidence workspace / source snapshots'),('verification_freshness','Verification / freshness',120,'Explicit verification timestamps only; missing or older-than-180-day verification is stale. Scholarship verification is not inferred from updated_at.','Canonical verification semantics'),('search_admission','Search admission',130,'Presence in the governed Search projection; this does not imply enrichment admission or publication.','Search course-v2 projection'),('publication_readiness','Publication readiness',140,'Recorded canonical/channel publication progression; no channel state is not invented as published.','Canonical + publishing channel state')),
agg as (select entity_type,domain,count(*)::bigint scope_count,count(*) filter(where state<>'not_applicable')::bigint applicable_count,count(*) filter(where state in ('present','zero'))::bigint ready_count,count(*) filter(where state in ('source_null','suppressed','not_yet_enriched','stale','ambiguous','rejected'))::bigint attention_count,jsonb_build_object('present',count(*) filter(where state='present'),'source_null',count(*) filter(where state='source_null'),'not_applicable',count(*) filter(where state='not_applicable'),'zero',count(*) filter(where state='zero'),'suppressed',count(*) filter(where state='suppressed'),'not_yet_enriched',count(*) filter(where state='not_yet_enriched'),'stale',count(*) filter(where state='stale'),'ambiguous',count(*) filter(where state='ambiguous'),'rejected',count(*) filter(where state='rejected')) states from all_states group by entity_type,domain),
metrics as (select a.*,d.label,d.sort_order,d.definition,d.authority,case when a.applicable_count=0 then null else round(a.ready_count*100.0/a.applicable_count,2) end readiness_pct from agg a join defs d using(domain))
select jsonb_build_object('scope',jsonb_build_object('country_code',(select country_code from params),'default_scope',case when (select country_code from params) is null then 'AU+NZ' else (select country_code from params) end,'as_of',now()),'policy',jsonb_build_object('composite_score','not_exposed','reason','Cross-domain equal weighting conflates regulatory authority, enrichment coverage, Search admission and publication state. Domain readiness is reported instead.','ready_states',jsonb_build_array('present','zero'),'excluded_from_denominator',jsonb_build_array('not_applicable')),'state_vocabulary',jsonb_build_array('present','source_null','not_applicable','zero','suppressed','not_yet_enriched','stale','ambiguous','rejected'),'metrics',coalesce((select jsonb_agg(jsonb_build_object('entity_type',entity_type,'domain',domain,'label',label,'scope_count',scope_count,'applicable_count',applicable_count,'ready_count',ready_count,'attention_count',attention_count,'readiness_pct',readiness_pct,'states',states,'definition',definition,'authority',authority) order by sort_order,entity_type) from metrics),'[]'::jsonb))
$$;


ALTER FUNCTION "security"."data_quality_overview_impl"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_quality_provider_base"("p_country_code" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "entity_name" "text", "stable_key" "text", "country_code" "text", "source_id" "uuid", "evidence_id" "uuid", "last_verified_at" timestamp with time zone, "updated_at" timestamp with time zone, "publication_status" "text", "identity_ok" boolean, "registration_count" integer, "geography_present" boolean, "evidence_count" integer, "channel_state_count" integer, "channel_published_count" integer, "channel_rejected_count" integer, "channel_distinct_status_count" integer, "review_domains" "text"[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'ref', 'pipeline', 'workflow', 'publishing', 'auth'
    AS $$
with scope as (
  select p.*,co.iso_alpha2::text country_code
  from catalogue.providers p join ref.countries co on co.id=p.country_id
  where (p_country_code is null and co.iso_alpha2 in ('AU','NZ')) or (p_country_code is not null and co.iso_alpha2=upper(p_country_code))
), reg as (
  select r.provider_id,count(*) filter(where coalesce(r.status,'active')='active')::int active_count,
    (array_agg(r.source_id order by r.checked_at desc nulls last,r.id) filter(where r.source_id is not null))[1] source_id,
    (array_agg(r.evidence_id order by r.checked_at desc nulls last,r.id) filter(where r.evidence_id is not null))[1] evidence_id
  from catalogue.provider_registrations r join scope s on s.id=r.provider_id group by r.provider_id
), ev as (
  select el.entity_id,count(distinct el.evidence_id)::int evidence_count,(array_agg(el.evidence_id order by el.updated_at desc))[1] evidence_id
  from pipeline.evidence_entity_links el join scope s on s.id=el.entity_id where el.entity_type='provider' group by el.entity_id
), pub as (
  select es.entity_id,count(*)::int state_count,count(*) filter(where lower(es.publication_status)='published')::int published_count,
    count(*) filter(where lower(es.publication_status)='rejected')::int rejected_count,count(distinct lower(es.publication_status))::int distinct_status_count
  from publishing.entity_states es join scope s on s.id=es.entity_id group by es.entity_id
), rev as (
  select q.entity_id,array_agg(distinct lower(q.domain)) filter(where q.status in ('open','queued','pending','in_review')) review_domains
  from workflow.review_queue q join scope s on s.id=q.entity_id group by q.entity_id
)
select s.id,coalesce(s.display_name,s.canonical_name),s.stable_key,s.country_code,coalesce(s.canonical_source_id,reg.source_id),coalesce(ev.evidence_id,reg.evidence_id),
 s.last_verified_at,s.updated_at,s.publication_status,
 (s.stable_key is not null and btrim(s.stable_key)<>'' and s.canonical_name is not null and btrim(s.canonical_name)<>'' and s.country_id is not null),
 coalesce(reg.active_count,0),
 (s.subdivision_id is not null or coalesce(nullif(btrim(s.primary_city),''),null) is not null or coalesce(nullif(btrim(s.address_line1),''),null) is not null),
 coalesce(ev.evidence_count,0),coalesce(pub.state_count,0),coalesce(pub.published_count,0),coalesce(pub.rejected_count,0),coalesce(pub.distinct_status_count,0),coalesce(rev.review_domains,'{}'::text[])
from scope s left join reg on reg.provider_id=s.id left join ev on ev.entity_id=s.id left join pub on pub.entity_id=s.id left join rev on rev.entity_id=s.id
$$;


ALTER FUNCTION "security"."data_quality_provider_base"("p_country_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_quality_quarantine_impl"("p_args" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'scholarship', 'pipeline', 'ref'
    AS $$
declare
  v_entity text:=lower(nullif(btrim(coalesce(p_args->>'entity_type','')),''));
  v_country text:=upper(nullif(btrim(coalesce(p_args->>'country_code','')),''));
  v_query text:=nullif(btrim(coalesce(p_args->>'query','')),'');
  v_limit int:=least(greatest(coalesce(nullif(p_args->>'limit','')::int,50),1),200);
  v_offset int:=greatest(coalesce(nullif(p_args->>'offset','')::int,0),0);
  v_result jsonb;
begin
  if v_entity is not null and v_entity not in ('provider','course','campus','scholarship','provider_contact') then
    raise exception 'unsupported quarantine entity type' using errcode='22023';
  end if;

  with entities as (
    select 'provider'::text entity_type,p.id entity_id,coalesce(p.display_name,p.canonical_name) entity_name,
           p.id provider_id,coalesce(p.display_name,p.canonical_name) provider_name,co.iso_alpha2::text country_code
    from catalogue.providers p join ref.countries co on co.id=p.country_id
    union all
    select 'course',c.id,coalesce(c.display_title,c.canonical_title),p.id,coalesce(p.display_name,p.canonical_name),co.iso_alpha2::text
    from catalogue.courses c join catalogue.providers p on p.id=c.provider_id join ref.countries co on co.id=p.country_id
    union all
    select 'campus',ca.id,ca.name,p.id,coalesce(p.display_name,p.canonical_name),co.iso_alpha2::text
    from catalogue.campuses ca join catalogue.providers p on p.id=ca.provider_id join ref.countries co on co.id=p.country_id
    union all
    select 'scholarship',s.id,s.name,p.id,coalesce(p.display_name,p.canonical_name),co.iso_alpha2::text
    from scholarship.scholarships s left join catalogue.providers p on p.id=s.provider_id left join ref.countries co on co.id=p.country_id
    union all
    select 'provider_contact',o.id,coalesce(nullif(btrim(o.full_name),''),nullif(btrim(o.job_title),''),'Provider contact'),p.id,
           coalesce(p.display_name,p.canonical_name),co.iso_alpha2::text
    from pipeline.provider_contact_observations o join catalogue.providers p on p.id=o.provider_id join ref.countries co on co.id=p.country_id
  ), effective as (
    select e.*,
      db.id direct_decision_id,db.reason_code direct_reason_code,db.comment direct_comment,db.review_at direct_review_at,db.expires_at direct_expires_at,db.created_at direct_created_at,
      pb.id provider_decision_id,pb.reason_code provider_reason_code,pb.comment provider_comment,pb.review_at provider_review_at,pb.expires_at provider_expires_at,pb.created_at provider_created_at
    from entities e
    left join security.layer4_active_blocks db
      on db.entity_type=e.entity_type and db.entity_id=e.entity_id and db.block_scope='data_quality_quarantine'
    left join security.layer4_active_blocks pb
      on e.entity_type<>'provider' and e.provider_id is not null
     and pb.entity_type='provider' and pb.entity_id=e.provider_id and pb.block_scope='data_quality_quarantine'
    where db.id is not null or pb.id is not null
  ), filtered as (
    select *,count(*) over() total_count
    from effective
    where (v_entity is null or entity_type=v_entity)
      and (v_country is null or country_code=v_country)
      and (v_query is null or entity_name ilike '%'||v_query||'%' or coalesce(provider_name,'') ilike '%'||v_query||'%')
  ), paged as (
    select * from filtered
    order by entity_type,lower(entity_name),entity_id
    limit v_limit offset v_offset
  )
  select jsonb_build_object(
    'items',coalesce(jsonb_agg(jsonb_build_object(
      'entity_type',entity_type,'entity_id',entity_id,'entity_name',entity_name,
      'provider_id',provider_id,'provider_name',provider_name,'country_code',country_code,
      'direct_quarantine',direct_decision_id is not null,
      'inherited_provider_quarantine',provider_decision_id is not null,
      'effective_decision_id',coalesce(direct_decision_id,provider_decision_id),
      'reason_code',coalesce(direct_reason_code,provider_reason_code),
      'comment',coalesce(direct_comment,provider_comment),
      'review_at',coalesce(direct_review_at,provider_review_at),
      'expires_at',coalesce(direct_expires_at,provider_expires_at),
      'created_at',coalesce(direct_created_at,provider_created_at)
    ) order by entity_type,lower(entity_name),entity_id),'[]'::jsonb),
    'total',coalesce(max(total_count),0),
    'limit',v_limit,'offset',v_offset,
    'entity_type',v_entity,'country_code',v_country,
    'scope','data_quality_quarantine'
  ) into v_result
  from paged;

  return coalesce(v_result,jsonb_build_object(
    'items','[]'::jsonb,'total',0,'limit',v_limit,'offset',v_offset,
    'entity_type',v_entity,'country_code',v_country,'scope','data_quality_quarantine'
  ));
end $$;


ALTER FUNCTION "security"."data_quality_quarantine_impl"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."data_quality_scholarship_base"("p_country_code" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "entity_name" "text", "stable_key" "text", "provider_id" "uuid", "provider_name" "text", "country_code" "text", "source_id" "uuid", "evidence_id" "uuid", "updated_at" timestamp with time zone, "publication_status" "text", "identity_ok" boolean, "semantic_present" boolean, "evidence_count" integer, "channel_state_count" integer, "channel_published_count" integer, "channel_rejected_count" integer, "channel_distinct_status_count" integer, "review_domains" "text"[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'scholarship', 'catalogue', 'ref', 'pipeline', 'workflow', 'publishing', 'auth'
    AS $$
with scope as (
 select s.*,coalesce(p.display_name,p.canonical_name) provider_name,coalesce(pc.iso_alpha2::text,sc.iso_alpha2::text) country_code
 from scholarship.scholarships s
 left join catalogue.providers p on p.id=s.provider_id
 left join ref.countries pc on pc.id=p.country_id
 left join pipeline.sources src on src.id=s.source_id
 left join ref.countries sc on sc.id=src.country_id
 where ((p_country_code is null and coalesce(pc.iso_alpha2::text,sc.iso_alpha2::text) in ('AU','NZ'))
    or (p_country_code is not null and coalesce(pc.iso_alpha2::text,sc.iso_alpha2::text)=upper(p_country_code)))
), scp as (
 select sc.scholarship_id,count(*) filter(where coalesce(sc.include_exclude,'include')='include')::int include_count
 from scholarship.scopes sc join scope s on s.id=sc.scholarship_id group by sc.scholarship_id
), ev as (
 select el.entity_id,count(distinct el.evidence_id)::int evidence_count,(array_agg(el.evidence_id order by el.updated_at desc))[1] evidence_id
 from pipeline.evidence_entity_links el join scope s on s.id=el.entity_id where el.entity_type='scholarship' group by el.entity_id
), pub as (
 select es.entity_id,count(*)::int state_count,count(*) filter(where lower(es.publication_status)='published')::int published_count,
 count(*) filter(where lower(es.publication_status)='rejected')::int rejected_count,count(distinct lower(es.publication_status))::int distinct_status_count
 from publishing.entity_states es join scope s on s.id=es.entity_id group by es.entity_id
), rev as (
 select q.entity_id,array_agg(distinct lower(q.domain)) filter(where q.status in ('open','queued','pending','in_review')) review_domains
 from workflow.review_queue q join scope s on s.id=q.entity_id group by q.entity_id
)
select s.id,s.name,s.stable_key,s.provider_id,s.provider_name,s.country_code,s.source_id,coalesce(s.evidence_id,ev.evidence_id),s.updated_at,s.publication_status,
 (s.stable_key is not null and btrim(s.stable_key)<>'' and s.name is not null and btrim(s.name)<>''),
 (coalesce(nullif(btrim(s.description),''),null) is not null and coalesce(nullif(btrim(s.source_url),''),null) is not null and s.evidence_id is not null and (coalesce(scp.include_count,0)>0 or s.provider_id is null)),
 coalesce(ev.evidence_count,case when s.evidence_id is not null then 1 else 0 end),coalesce(pub.state_count,0),coalesce(pub.published_count,0),coalesce(pub.rejected_count,0),coalesce(pub.distinct_status_count,0),coalesce(rev.review_domains,'{}'::text[])
from scope s left join scp on scp.scholarship_id=s.id left join ev on ev.entity_id=s.id left join pub on pub.entity_id=s.id left join rev on rev.entity_id=s.id
$$;


ALTER FUNCTION "security"."data_quality_scholarship_base"("p_country_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."delivery_mode_from_location"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with a as (select lower(coalesce(p_text, '')) s),
       b as (select s ~ '(\monline\M|\mon-line\M|\mremote\M|\mdistance\M|\mexternal\M|off[ -]campus)' o,
                    regexp_replace(s, '(university of [a-z]+ online|[a-z]+ online|\monline\M|\mon-line\M|\mremote\M|\mdistance\M|\mexternal\M|off[ -]campus|learning|study|and|or|only|campus(es)?|location(s)?|[^a-z])', ' ', 'g') rest from a)
  select case when btrim(p_text) = '' or p_text is null then null
              when o and length(btrim(rest)) >= 3 then 'on_campus_and_online'
              when o then 'online'
              when length(btrim(rest)) >= 3 then 'on_campus'
              else null end
  from b
$$;


ALTER FUNCTION "security"."delivery_mode_from_location"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."delivery_mode_from_text"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with a0 as (select lower(coalesce(p_text, '')) s),
       a1 as (select regexp_replace(s, '(online\s*-\s*no\M|online[^.]{0,40}only for non-international[^.]{0,120}|not offered online|\(includes blended\)|distance\s*\((?:assessment|recognition) of prior learning[^)]{0,60}\))', ' ', 'g') s from a0),
       a2 as (select regexp_replace(s, '(online with (?:some )?(?:face[ -]to[ -]face|on[ -]?campus|block)|mixed attendance mode|virtual classroom)', ' blended ', 'g') s from a1),
       a2b as (select regexp_replace(s, '([0-9]+\s*(?:hours?|hrs?|%)[^.]{0,40}(?:face[ -]to[ -]face|classroom|on[ -]?campus|in[ -]person)[^.]{0,80}[0-9]+\s*(?:hours?|hrs?|%)[^.]{0,40}(?:online|distance)|(?:face[ -]to[ -]face|classroom|on[ -]?campus|in[ -]person)[^.]{0,20}[0-9]+\s*(?:hours?|hrs?|%)[^.]{0,80}(?:online|distance)[^.]{0,20}[0-9]+\s*(?:hours?|hrs?|%))', ' blended ', 'g') s from a2),
       a3 as (select regexp_replace(regexp_replace(s, '\mon-line\M', 'online', 'g'), '\mexternal\M', ' distance ', 'g') s from a2b),
       a4 as (select regexp_replace(regexp_replace(s, '(study(ing)? from home|\mfrom home\M)', ' online ', 'g'), '(\mclassroom\M|\min[ -]class\M|\monsite\M|\mon-site\M|residential (?:seminars?|blocks?|study)|\mnoho\M)', ' on campus ', 'g') s from a3),
       b as (select regexp_replace(s, 'off[ -]campus', ' distance ', 'g') s from a4),
       c as (select s ~ '(100% online|\monline\M|\mdistance\M)' o, s ~ '(on[ -]?campus|face[ -]to[ -]face|in[ -]person|\mcampus\M)' k, s ~ '(blended|mixed mode|multi[ -]?modal|hybrid)' m from b)
  select case when o and k then 'on_campus_and_online'
              when m then 'blended'
              when o then 'online'
              when k then 'on_campus'
              else null end
  from c
$$;


ALTER FUNCTION "security"."delivery_mode_from_text"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."delivery_mode_read_v1"("p" "text", "p_provider" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare t text := coalesce(p, ''); w record;
begin
  if btrim(t) = '' then return null; end if;
  -- the university's own phrases first, then phrases for every university; each becomes the plain words of its mode
  for w in select d.phrase, d.mode from pipeline.delivery_wording d where d.active and (d.provider_id = p_provider or d.provider_id is null)
            order by (d.provider_id is null), length(d.phrase) desc loop
    t := regexp_replace(t, regexp_replace(w.phrase, '([.*+?^${}()|\[\]\\])', '\\\1', 'g'),
                        case w.mode when 'on_campus' then 'on campus' when 'online' then 'online' when 'blended' then 'blended' else 'on campus or online' end, 'gi');
  end loop;
  return security.enrich_parse_delivery_v1(t);
end $_$;


ALTER FUNCTION "security"."delivery_mode_read_v1"("p" "text", "p_provider" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."destination_edition_guard_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.status = 'published' and new.terms_status is distinct from 'approved' then
    raise exception using errcode = 'check_violation',
      message = format('DESTINATION_TERMS_NOT_APPROVED: edition %s cannot be published while its terms are %s (REQ-68)', new.id, new.terms_status);
  end if;
  return new;
end $$;


ALTER FUNCTION "security"."destination_edition_guard_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."destination_edition_publish_v1"("p_edition" "uuid", "p_actor" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v destination.editions%rowtype; v_rows int; v_old uuid;
begin
  select * into v from destination.editions x where x.id = p_edition for update;
  if not found then raise exception using errcode = '22023', message = 'INVALID_INPUT: edition not found'; end if;
  if v.status not in ('draft', 'in_review') then
    raise exception using errcode = '22023', message = format('INVALID_INPUT: a %s edition cannot be published', v.status);
  end if;
  if v.terms_status is distinct from 'approved' then
    raise exception using errcode = 'check_violation',
      message = format('DESTINATION_TERMS_NOT_APPROVED: edition %s cannot be published while its terms are %s (REQ-68)', v.id, v.terms_status);
  end if;
  v_rows := case v.domain
    when 'study_rules' then (select count(*) from destination.study_rules r where r.edition_id = v.id)
    when 'city_profiles' then (select count(*) from destination.city_profiles r where r.edition_id = v.id)
    else (select count(*) from destination.career_outcomes r where r.edition_id = v.id) end;
  if v_rows = 0 then raise exception using errcode = '22023', message = 'INVALID_INPUT: an edition with no rows cannot be published'; end if;
  update destination.editions x set status = 'superseded',
         effective_to = case when x.effective_to is null and v.effective_from > x.effective_from then v.effective_from - 1 else x.effective_to end
   where x.country_id = v.country_id and x.domain = v.domain and x.status = 'published' and x.id <> v.id
  returning x.id into v_old;
  update destination.editions x set status = 'published', approved_by = coalesce(p_actor, x.approved_by), approved_at = now() where x.id = v.id;
  return jsonb_build_object('edition_id', v.id, 'status', 'published', 'rows', v_rows, 'superseded', v_old);
end $$;


ALTER FUNCTION "security"."destination_edition_publish_v1"("p_edition" "uuid", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."destination_edition_set_terms_v1"("p_edition" "uuid", "p_terms" "text", "p_actor" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v destination.editions%rowtype;
begin
  if p_terms not in ('approved', 'pending', 'restricted') then
    raise exception using errcode = '22023', message = 'INVALID_INPUT: terms must be approved, pending or restricted';
  end if;
  select * into v from destination.editions x where x.id = p_edition for update;
  if not found then raise exception using errcode = '22023', message = 'INVALID_INPUT: edition not found'; end if;
  update destination.editions x
     set terms_status = p_terms,
         status = case when x.status = 'published' and p_terms <> 'approved' then 'in_review' else x.status end,
         approved_by = case when p_terms = 'approved' then coalesce(p_actor, x.approved_by) else x.approved_by end
   where x.id = p_edition;
  return (select jsonb_build_object('edition_id', x.id, 'status', x.status, 'terms_status', x.terms_status) from destination.editions x where x.id = p_edition);
end $$;


ALTER FUNCTION "security"."destination_edition_set_terms_v1"("p_edition" "uuid", "p_terms" "text", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."destination_import_v1"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  e jsonb := p_payload->'edition';
  v_cc text := upper(btrim(coalesce(e->>'country_code', '')));
  v_country uuid; v_domain text := btrim(coalesce(e->>'domain', '')); v_label text := btrim(coalesce(e->>'edition_label', ''));
  v_ed destination.editions%rowtype; v_new_edition boolean := false; v_edition_changed boolean := false;
  r jsonb; i int; v_ins int := 0; v_upd int := 0; v_total int := 0; v_was_insert boolean; v_city uuid;
  v_terms text := coalesce(nullif(btrim(e->>'terms_status'), ''), 'pending');
begin
  if jsonb_typeof(e) is distinct from 'object' then raise exception using errcode = '22023', message = 'INVALID_INPUT: edition must be an object'; end if;
  if p_payload ? 'rows' and jsonb_typeof(p_payload->'rows') <> 'array' then raise exception using errcode = '22023', message = 'INVALID_INPUT: rows must be a list'; end if;
  if v_domain not in ('study_rules', 'city_profiles', 'career_outcomes') then
    raise exception using errcode = '22023', message = 'INVALID_INPUT: domain must be study_rules, city_profiles or career_outcomes';
  end if;
  if v_label = '' then raise exception using errcode = '22023', message = 'INVALID_INPUT: edition_label is required'; end if;
  select c.id into v_country from ref.countries c where c.iso_alpha2 = v_cc;
  if v_country is null then raise exception using errcode = '22023', message = format('INVALID_INPUT: unknown country_code %s', v_cc); end if;
  if v_terms not in ('pending', 'restricted') then
    raise exception using errcode = '22023', message = 'INVALID_INPUT: an import sets terms_status pending or restricted; approval is a separate decision';
  end if;
  if nullif(btrim(e->>'source_url'), '') is null or nullif(btrim(e->>'source_owner'), '') is null or nullif(btrim(e->>'attribution_text'), '') is null
     or nullif(btrim(e->>'effective_from'), '') is null then
    raise exception using errcode = '22023', message = 'INVALID_INPUT: source_url, source_owner, attribution_text and effective_from are required';
  end if;

  select * into v_ed from destination.editions x where x.country_id = v_country and x.domain = v_domain and x.edition_label = v_label for update;
  if found then
    if v_ed.status in ('published', 'superseded') then
      raise exception using errcode = '22023',
        message = format('INVALID_INPUT: edition %s is %s and fixed; import it under a new edition_label', v_label, v_ed.status);
    end if;
    update destination.editions x set effective_from = (e->>'effective_from')::date, effective_to = nullif(e->>'effective_to', '')::date,
           source_url = btrim(e->>'source_url'), source_owner = btrim(e->>'source_owner'), attribution_text = btrim(e->>'attribution_text'),
           last_checked_at = now()
     where x.id = v_ed.id
       and (x.effective_from, x.effective_to, x.source_url, x.source_owner, x.attribution_text)
           is distinct from ((e->>'effective_from')::date, nullif(e->>'effective_to', '')::date, btrim(e->>'source_url'), btrim(e->>'source_owner'), btrim(e->>'attribution_text'));
    v_edition_changed := found;
  else
    insert into destination.editions(country_id, domain, edition_label, effective_from, effective_to, status, source_url, source_owner, attribution_text, terms_status)
    values (v_country, v_domain, v_label, (e->>'effective_from')::date, nullif(e->>'effective_to', '')::date, 'draft',
            btrim(e->>'source_url'), btrim(e->>'source_owner'), btrim(e->>'attribution_text'), v_terms)
    returning * into v_ed;
    v_new_edition := true;
  end if;

  for r, i in select x, o::int from jsonb_array_elements(coalesce(p_payload->'rows', '[]'::jsonb)) with ordinality t(x, o) loop
    v_total := v_total + 1;
    if jsonb_typeof(r) <> 'object' then raise exception using errcode = '22023', message = format('INVALID_INPUT: row %s is not an object', i); end if;
    begin
      if v_domain = 'study_rules' then
        insert into destination.study_rules as t(edition_id, country_id, visa_subclass, visa_name, application_fee_amount, fee_currency, financial_capacity_annual,
               work_hours_fortnight, work_hours_notes, post_study_work_years_min, post_study_work_years_max, processing_time_days_min, processing_time_days_max,
               application_channels, concessions, admission_tests_note, source_url)
        values (v_ed.id, v_country, btrim(r->>'visa_subclass'), btrim(r->>'visa_name'), (r->>'application_fee_amount')::numeric, upper(btrim(r->>'fee_currency')),
               (r->>'financial_capacity_annual')::numeric, (r->>'work_hours_fortnight')::int, r->>'work_hours_notes',
               (r->>'post_study_work_years_min')::numeric, (r->>'post_study_work_years_max')::numeric,
               (r->>'processing_time_days_min')::int, (r->>'processing_time_days_max')::int,
               coalesce(r->'application_channels', '[]'::jsonb), coalesce(r->'concessions', '{}'::jsonb), r->>'admission_tests_note',
               coalesce(nullif(btrim(r->>'source_url'), ''), v_ed.source_url))
        on conflict (edition_id, country_id, visa_subclass) do update set
               visa_name = excluded.visa_name, application_fee_amount = excluded.application_fee_amount, fee_currency = excluded.fee_currency,
               financial_capacity_annual = excluded.financial_capacity_annual, work_hours_fortnight = excluded.work_hours_fortnight,
               work_hours_notes = excluded.work_hours_notes, post_study_work_years_min = excluded.post_study_work_years_min,
               post_study_work_years_max = excluded.post_study_work_years_max, processing_time_days_min = excluded.processing_time_days_min,
               processing_time_days_max = excluded.processing_time_days_max, application_channels = excluded.application_channels,
               concessions = excluded.concessions, admission_tests_note = excluded.admission_tests_note, source_url = excluded.source_url,
               last_checked_at = now()
         where (t.visa_name, t.application_fee_amount, t.fee_currency, t.financial_capacity_annual, t.work_hours_fortnight, t.work_hours_notes,
                t.post_study_work_years_min, t.post_study_work_years_max, t.processing_time_days_min, t.processing_time_days_max,
                t.application_channels, t.concessions, t.admission_tests_note, t.source_url)
               is distinct from
               (excluded.visa_name, excluded.application_fee_amount, excluded.fee_currency, excluded.financial_capacity_annual, excluded.work_hours_fortnight,
                excluded.work_hours_notes, excluded.post_study_work_years_min, excluded.post_study_work_years_max, excluded.processing_time_days_min,
                excluded.processing_time_days_max, excluded.application_channels, excluded.concessions, excluded.admission_tests_note, excluded.source_url)
        returning (xmax = 0) into v_was_insert;
      elsif v_domain = 'city_profiles' then
        if nullif(btrim(r->>'city_name'), '') is null then raise exception using errcode = '22023', message = 'city_name is required'; end if;
        v_city := coalesce(nullif(r->>'city_id', '')::uuid, md5('city:' || v_cc || ':' || lower(btrim(r->>'city_name')))::uuid);
        insert into destination.city_profiles as t(edition_id, city_id, country_id, city_name, subdivision_code, population, population_year, population_source,
               climate_baseline, living_cost, cost_currency, source_url)
        values (v_ed.id, v_city, v_country, btrim(r->>'city_name'), nullif(btrim(r->>'subdivision_code'), ''), (r->>'population')::int, (r->>'population_year')::int,
               r->>'population_source', coalesce(r->'climate_baseline', '{}'::jsonb), coalesce(r->'living_cost', '{}'::jsonb), upper(btrim(r->>'cost_currency')),
               coalesce(nullif(btrim(r->>'source_url'), ''), v_ed.source_url))
        on conflict (edition_id, city_id) do update set
               city_name = excluded.city_name, subdivision_code = excluded.subdivision_code, population = excluded.population,
               population_year = excluded.population_year, population_source = excluded.population_source, climate_baseline = excluded.climate_baseline,
               living_cost = excluded.living_cost, cost_currency = excluded.cost_currency, source_url = excluded.source_url, last_checked_at = now()
         where (t.city_name, t.subdivision_code, t.population, t.population_year, t.population_source, t.climate_baseline, t.living_cost, t.cost_currency, t.source_url)
               is distinct from
               (excluded.city_name, excluded.subdivision_code, excluded.population, excluded.population_year, excluded.population_source,
                excluded.climate_baseline, excluded.living_cost, excluded.cost_currency, excluded.source_url)
        returning (xmax = 0) into v_was_insert;
      else
        insert into destination.career_outcomes as t(edition_id, country_id, occupation_code, occupation_title, study_area_code, skill_shortage_status, median_salary,
               salary_currency, salary_period, employment_rate_pct, job_outlook_rating, outlook_horizon_years, source_url)
        values (v_ed.id, v_country, btrim(r->>'occupation_code'), btrim(r->>'occupation_title'), nullif(btrim(r->>'study_area_code'), ''),
               nullif(btrim(r->>'skill_shortage_status'), ''), (r->>'median_salary')::numeric, upper(btrim(r->>'salary_currency')),
               coalesce(nullif(btrim(r->>'salary_period'), ''), 'annual'), (r->>'employment_rate_pct')::numeric, r->>'job_outlook_rating',
               (r->>'outlook_horizon_years')::int, coalesce(nullif(btrim(r->>'source_url'), ''), v_ed.source_url))
        on conflict (edition_id, country_id, occupation_code) do update set
               occupation_title = excluded.occupation_title, study_area_code = excluded.study_area_code, skill_shortage_status = excluded.skill_shortage_status,
               median_salary = excluded.median_salary, salary_currency = excluded.salary_currency, salary_period = excluded.salary_period,
               employment_rate_pct = excluded.employment_rate_pct, job_outlook_rating = excluded.job_outlook_rating,
               outlook_horizon_years = excluded.outlook_horizon_years, source_url = excluded.source_url, last_checked_at = now()
         where (t.occupation_title, t.study_area_code, t.skill_shortage_status, t.median_salary, t.salary_currency, t.salary_period, t.employment_rate_pct,
                t.job_outlook_rating, t.outlook_horizon_years, t.source_url)
               is distinct from
               (excluded.occupation_title, excluded.study_area_code, excluded.skill_shortage_status, excluded.median_salary, excluded.salary_currency,
                excluded.salary_period, excluded.employment_rate_pct, excluded.job_outlook_rating, excluded.outlook_horizon_years, excluded.source_url)
        returning (xmax = 0) into v_was_insert;
      end if;
    exception
      when check_violation or not_null_violation or invalid_text_representation or numeric_value_out_of_range or datetime_field_overflow
           or invalid_datetime_format or string_data_right_truncation or invalid_parameter_value then
        raise exception using errcode = '22023', message = format('INVALID_INPUT: row %s: %s', i, sqlerrm);
    end;
    if found then
      if v_was_insert then v_ins := v_ins + 1; else v_upd := v_upd + 1; end if;
    end if;
  end loop;

  return jsonb_build_object('edition_id', v_ed.id, 'country_code', v_cc, 'domain', v_domain, 'edition_label', v_label,
    'edition', case when v_new_edition then 'created' when v_edition_changed then 'updated' else 'unchanged' end,
    'status', (select x.status from destination.editions x where x.id = v_ed.id), 'terms_status', (select x.terms_status from destination.editions x where x.id = v_ed.id),
    'rows', v_total, 'inserted', v_ins, 'updated', v_upd, 'unchanged', v_total - v_ins - v_upd);
end $$;


ALTER FUNCTION "security"."destination_import_v1"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."destination_row_guard_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare v_status text; v_country uuid; v_domain text;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    select e.status into v_status from destination.editions e where e.id = old.edition_id;
    if v_status in ('published', 'superseded') then
      raise exception using errcode = 'check_violation',
        message = format('DESTINATION_EDITION_FIXED: rows of a %s edition cannot change; import a new edition', v_status);
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  select e.status, e.country_id, e.domain into v_status, v_country, v_domain from destination.editions e where e.id = new.edition_id;
  if v_status in ('published', 'superseded') then
    raise exception using errcode = 'check_violation',
      message = format('DESTINATION_EDITION_FIXED: rows of a %s edition cannot change; import a new edition', v_status);
  end if;
  if new.country_id is distinct from v_country then
    raise exception using errcode = 'check_violation', message = 'DESTINATION_COUNTRY_MISMATCH: a row''s country must be its edition''s country';
  end if;
  if v_domain is distinct from tg_table_name then
    raise exception using errcode = 'check_violation',
      message = format('DESTINATION_DOMAIN_MISMATCH: edition domain %s does not hold %s rows', v_domain, tg_table_name);
  end if;
  return new;
end $$;


ALTER FUNCTION "security"."destination_row_guard_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."double_degree_same_group_v1"("p_title" "text", "p_grp" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  -- a double degree whose every award is in the same group as the course (for example Bachelor of Arts / Bachelor of Laws, both undergraduate)
  select p_grp is not null and coalesce((
    select count(*) >= 2 and bool_and(case when m[1] in ('bachelor', 'associate degree') then 'undergraduate'
                                           when m[1] in ('master', 'graduate certificate', 'graduate diploma') then 'postgraduate' else 'other' end = p_grp)
      from regexp_matches(lower(coalesce(p_title, '')), '(bachelor|associate degree|master|graduate certificate|graduate diploma|diploma|doctor)', 'g') m), false)
$$;


ALTER FUNCTION "security"."double_degree_same_group_v1"("p_title" "text", "p_grp" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."english_gap_funnel_v1"() RETURNS TABLE("layer" "text", "cause_key" "text", "who_acts" "text", "courses" bigint, "providers" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'ref', 'security'
    AS $$
  -- Every lifecycle-active course without an active English requirement, classified on the policy route (rule_cause) and the course-page route (page_cause), then one primary cause.
  -- Policy route: the provider's stage from security.english_policy_status_v1 (queried per stage so that no stage is cut at its row limit), and for a provider with an approved
  -- policy the plan of security.provider_english_plan_v1 for the course. Course-page route: the course's page binding and read status, and the last English item of the AI reader.
  with m as (
    select c.id course_id, c.provider_id from catalogue.courses c
     where c.lifecycle_status = 'active'
       and not exists (select 1 from catalogue.course_english_requirements r where r.course_id = c.id and r.status = 'active')),
  hid as (select h.provider_id from security.provider_hidden_v1 h),
  st as (select x.provider_id, x.stage
           from unnest(array['approved', 'group_proposed', 'rule_proposed', 'rejected', 'page_read_no_rule', 'page_not_stored', 'weak_candidates_only', 'mapped_no_page', 'not_mapped']) s(stage),
                lateral security.english_policy_status_v1(null, s.stage, 1000) x),  -- fixed: the status read's own display cap, applied per stage
  pl as (
    select distinct on (z.course_id) z.course_id, z.outcome, z.reason
      from (select x.course_id, x.outcome, x.reason
              from pipeline.provider_policy_proposals p, lateral security.provider_english_plan_v1(p.id) x
             where p.kind = 'english_policy' and p.status = 'approved') z
     order by z.course_id, (z.outcome = 'write') desc, (z.outcome <> 'held') desc),
  refused as (
    select distinct fs.provider_id from pipeline.provider_fact_sources fs
     where fs.kind = 'english_policy' and fs.status = 'failed' and security.provider_fact_refusal_v1(fs.parse_summary->>'error')),
  pg as (select g.course_id, g.status, g.read_status, (g.evidence_id is not null) stored from pipeline.coverage_course_pages g),
  li as (select distinct on (i.course_id) i.course_id, i.state from pipeline.field_enrich_items i where i.field = 'english' order by i.course_id, i.updated_at desc),
  cov as (select a.course_id, a.state from pipeline.course_attribute_coverage a where a.attribute = 'english'),
  j as (
    select m.course_id, m.provider_id, (h.provider_id is not null) hidden, st.stage, pl.outcome, pl.reason, (r.provider_id is not null) refused,
           pg.status pstatus, pg.read_status, pg.stored, li.state lstate, cov.state cstate
      from m left join hid h on h.provider_id = m.provider_id left join st on st.provider_id = m.provider_id left join pl on pl.course_id = m.course_id
           left join refused r on r.provider_id = m.provider_id left join pg on pg.course_id = m.course_id left join li on li.course_id = m.course_id
           left join cov on cov.course_id = m.course_id),
  k as (
    select j.*,
      case when j.hidden then 'provider_not_published'
           when j.stage = 'group_proposed' then 'faculty_table_awaiting_person'
           when j.stage = 'rule_proposed' then 'policy_reading_awaiting_person'
           when j.stage = 'approved' and j.outcome = 'write' then 'default_ready_to_apply'
           when j.stage = 'approved' and j.outcome = 'other_value' then 'default_blocked_by_withdrawn_reading'
           when j.stage = 'approved' and j.outcome = 'differs' then 'withdrawn_reading_differs_from_default'
           when j.stage = 'approved' and j.outcome = 'set_by_hand' then 'manual_lock'
           when j.stage = 'approved' and j.outcome = 'in_review' then 'in_layer4_review'
           when j.stage = 'approved' and j.outcome = 'waiting' then 'course_page_waiting'
           when j.stage = 'approved' and j.outcome = 'held' then 'policy_held:' || case
                when j.reason like 'level not covered%' then 'level_not_covered'
                when j.reason like 'the policy gives no default%' then 'no_default_for_level'
                when j.reason like 'research degree%' then 'research_degree'
                when j.reason like 'named in the policy%' then 'named_in_policy'
                when j.reason like 'double degree%' then 'double_degree'
                when j.reason like 'exit award%' then 'exit_award'
                when j.reason like 'study level unknown%' then 'level_unknown'
                else 'other' end
           when j.stage = 'approved' then 'policy_no_plan_row'
           when j.stage = 'rejected' then 'policy_rejected'
           when j.stage = 'page_read_no_rule' then 'central_page_read_no_values'
           when j.stage = 'page_not_stored' and j.refused then 'central_page_refused_not_retried'
           when j.stage = 'page_not_stored' then 'central_page_not_stored'
           when j.stage = 'weak_candidates_only' then 'central_candidates_weak'
           when j.stage = 'mapped_no_page' then 'central_site_mapped_no_page'
           when j.stage = 'not_mapped' then 'central_site_not_mapped'
           else 'rule_unclassified' end rule_cause,
      case when j.lstate = 'failed' then 'english_read_failed_not_retried'
           when j.pstatus = 'mismatch' then 'page_for_another_course'
           when j.pstatus = 'ambiguous' then 'page_identity_ambiguous'
           when j.pstatus = 'bound' and j.read_status = 'read' and j.stored then 'page_read_no_english_stated'
           when j.pstatus is not null and j.read_status is distinct from 'read' then 'page_unreadable:' || coalesce(j.read_status, 'not_read')
           when j.pstatus is not null then 'page_read_not_stored'
           when j.cstate = 'no_website' then 'no_website'
           else 'no_course_page' end page_cause
      from j),
  p as (
    select k.*,
      -- the primary cause: what a person or the platform can act on first, then what the policy holds, then what the page says
      case when k.rule_cause = 'provider_not_published' then k.rule_cause
           when k.rule_cause in ('faculty_table_awaiting_person', 'policy_reading_awaiting_person', 'default_ready_to_apply', 'default_blocked_by_withdrawn_reading', 'withdrawn_reading_differs_from_default', 'manual_lock', 'in_layer4_review', 'course_page_waiting') then k.rule_cause
           when k.page_cause = 'english_read_failed_not_retried' then k.page_cause
           when k.rule_cause = 'central_page_refused_not_retried' then k.rule_cause
           when k.rule_cause like 'policy_held:%' then k.rule_cause
           when k.page_cause in ('page_for_another_course', 'page_identity_ambiguous') or k.page_cause like 'page_unreadable:%' or k.page_cause = 'page_read_not_stored' then k.page_cause
           when k.page_cause = 'page_read_no_english_stated' then k.page_cause
           when k.rule_cause in ('central_page_read_no_values', 'central_page_not_stored', 'central_candidates_weak', 'central_site_mapped_no_page', 'central_site_not_mapped', 'policy_rejected', 'policy_no_plan_row') then k.rule_cause
           else k.page_cause end primary_cause
      from k),
  u as (
    select 'primary'::text layer, p.primary_cause cause_key, count(*) courses, count(distinct p.provider_id) providers from p group by 2
    union all select 'rule', p.rule_cause, count(*), count(distinct p.provider_id) from p group by 2
    union all select 'page', p.page_cause, count(*), count(distinct p.provider_id) from p group by 2)
  select u.layer, u.cause_key,
         case when u.cause_key = 'provider_not_published' then 'not_published'
              when u.cause_key in ('faculty_table_awaiting_person', 'policy_reading_awaiting_person', 'default_blocked_by_withdrawn_reading', 'manual_lock', 'in_layer4_review', 'policy_rejected', 'policy_no_plan_row', 'rule_unclassified', 'withdrawn_reading_differs_from_default') then 'person'
              when u.cause_key in ('default_ready_to_apply', 'course_page_waiting', 'central_page_not_stored', 'central_candidates_weak', 'central_site_not_mapped', 'central_site_mapped_no_page', 'no_course_page', 'page_unreadable:not_read', 'page_read_not_stored') then 'automatic'
              when u.cause_key in ('central_page_refused_not_retried', 'english_read_failed_not_retried', 'page_unreadable:fetch_failed', 'page_unreadable:needs_render', 'page_unreadable:blocked') then 'spend'
              when u.cause_key like 'policy_held:%' then 'policy'
              when u.cause_key in ('central_page_read_no_values', 'page_read_no_english_stated', 'no_website', 'page_unreadable:robots_disallowed', 'page_unreadable:too_thin') then 'source'
              when u.cause_key in ('page_for_another_course', 'page_identity_ambiguous') then 'person'
              else 'person' end,
         u.courses, u.providers
    from u
$$;


ALTER FUNCTION "security"."english_gap_funnel_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."english_gap_funnel_v1"() IS 'CF-247 ENG 8 Nov 2026: why an active course has no English requirement; layers primary (one cause per course), rule (policy route) and page (course-page route). Read-only.';



CREATE OR REPLACE FUNCTION "security"."english_group_match_v1"("p_proposal" "jsonb", "p_title" "text", "p_field_path" "text", "p_grp" "text") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  -- the course groups of a policy that a person has bound to a course: the group's level fits the course's level group, and the course's field of education sits under one of the
  -- binding's fields (the field itself or any field below it), or its title matches the binding's pattern. Only a binding with a person recorded (bound_by) counts.
  select coalesce(jsonb_agg(jsonb_build_object('group_name', g->>'group_name', 'level', g->>'level', 'reqs', g->'reqs')), '[]'::jsonb)
    from jsonb_array_elements(case when jsonb_typeof(p_proposal->'group_bindings') = 'array' then p_proposal->'group_bindings' else '[]'::jsonb end) b
    join lateral jsonb_array_elements(case when jsonb_typeof(p_proposal->'groups') = 'array' then p_proposal->'groups' else '[]'::jsonb end) g
      on g->>'group_name' = b->>'group_name' and coalesce(g->>'level', '') = coalesce(b->>'level', '')
   where coalesce(b->>'bound_by', '') <> ''
     and jsonb_typeof(g->'reqs') = 'array' and jsonb_array_length(g->'reqs') > 0
     and (coalesce(b->>'level', '') = '' or b->>'level' = p_grp)
     and (exists (select 1 from jsonb_array_elements_text(case when jsonb_typeof(b->'field_paths') = 'array' then b->'field_paths' else '[]'::jsonb end) fp
                   where p_field_path is not null and (p_field_path = fp or left(p_field_path, length(fp) + 1) = fp || '/'))
          or (coalesce(b->>'title_regex', '') <> '' and p_title ~* (b->>'title_regex')))
$$;


ALTER FUNCTION "security"."english_group_match_v1"("p_proposal" "jsonb", "p_title" "text", "p_field_path" "text", "p_grp" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."english_group_match_v1"("p_proposal" "jsonb", "p_title" "text", "p_field_path" "text", "p_grp" "text") IS 'CF-247 English requirements (6 Nov 2026 D2): the person-bound course groups of an English policy that apply to a course (level, field of education path, title pattern). Pure; used by provider_english_plan_v1.';



CREATE OR REPLACE FUNCTION "security"."english_level_apply_all_v1"("p_apply" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare p uuid; v jsonb := '{}'::jsonb;
begin
  for p in select distinct provider_id from pipeline.provider_policy_proposals
            where kind = 'english_policy' and status = 'approved' and jsonb_typeof(proposal->'levels') = 'object' loop
    v := v || jsonb_build_object(p::text, security.english_level_apply_v1(p, p_apply));
  end loop;
  return v;
end $$;


ALTER FUNCTION "security"."english_level_apply_all_v1"("p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."english_level_apply_v1"("p_provider_id" "uuid", "p_apply" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare x pipeline.provider_policy_proposals%rowtype; r record; v_lv jsonb; v_write jsonb; v_tests text[]; v_src uuid; v_name text; v_out int;
        v_written int := 0; v_same int := 0; v_own_differs int := 0; v_own int := 0; v_held int := 0; v_withdrawn int := 0; v_unknown jsonb := '{}'::jsonb;
        v_courses uuid[] := '{}'; v_err int := 0; v_last text; v_label text; v_k text; v_how text; v_rule text;
        v_day text := to_char(now() at time zone 'Australia/Melbourne', 'FMDD Mon YYYY');
begin
  -- the approved English policy in force that names levels (Decision 262 keeps one in force per level; the latest decision wins here)
  select * into x from pipeline.provider_policy_proposals
   where provider_id = p_provider_id and kind = 'english_policy' and status = 'approved' and jsonb_typeof(proposal->'levels') = 'object'
   order by decided_at desc nulls last limit 1;
  if x.id is null then return jsonb_build_object('skipped', 'no approved English policy with levels'); end if;
  if x.evidence_id is null or coalesce(x.content_hash, '') = '' then return jsonb_build_object('skipped', 'the policy page has no stored evidence'); end if;
  v_src := security.coverage_sweep_source(x.provider_id);
  select coalesce(p.display_name, p.canonical_name) into v_name from catalogue.providers p where p.id = x.provider_id;
  for r in
    select co.id course_id, co.canonical_title title, security.english_level_group(sl.code) grp,
           -- Decision 265: the level the course page names, else the one its companion page names (Melbourne's entry requirements page)
           case when coalesce(g.candidates->'adapter_extra'->>'english_level', '') <> '' then g.candidates->'adapter_extra'->>'english_level'
                when cp.status = 'read' then nullif(cp.values->>'english_level', '') end raw,
           case when coalesce(g.candidates->'adapter_extra'->>'english_level', '') <> '' then g.url else cp.url end page_url,
           exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = co.id and l.field in ('english', 'english_requirements', 'course_english')) locked,
           exists (select 1 from pipeline.layer4_review_items i where i.entity_type = 'course' and i.entity_id = co.id and i.field_code = 'course_english' and i.status = 'pending') in_review
      from catalogue.courses co
      join pipeline.coverage_course_pages g on g.course_id = co.id
      left join pipeline.course_companion_pages cp on cp.course_id = co.id
      left join ref.study_levels sl on sl.id = co.study_level_id
     where co.provider_id = x.provider_id and co.lifecycle_status = 'active' and g.read_status = 'read'
  loop
    v_k := security.english_level_key(r.raw); v_how := format('named on the course page (%s)', r.page_url);
    -- Decision 265: no level named on a page: the policy's course group rules, in order (title pattern, and study level group when given)
    if v_k is null then
      select q->>'level', q->>'group_name' into v_k, v_rule
        from jsonb_array_elements(coalesce(x.proposal->'level_rules', '[]'::jsonb)) with ordinality t(q, n)
       where r.title ~* (q->>'title_regex')
         and (jsonb_typeof(q->'groups') is distinct from 'array' or r.grp in (select jsonb_array_elements_text(q->'groups')))
       order by n limit 1;
      if v_k is null then continue; end if;
      v_k := security.english_level_key(v_k); v_how := format('for this course group ("%s")', v_rule);
    end if;
    v_lv := x.proposal->'levels'->v_k;
    v_label := coalesce(x.proposal->'level_names'->>v_k, btrim(coalesce(r.raw, v_k)));
    if jsonb_typeof(v_lv) is distinct from 'array' or jsonb_array_length(v_lv) = 0 then
      v_unknown := jsonb_set(v_unknown, array[coalesce(v_k, '?')], to_jsonb(coalesce((v_unknown->>coalesce(v_k, '?'))::int, 0) + 1)); continue;
    end if;
    if r.locked or r.in_review then v_held := v_held + 1; continue; end if;
    -- the course page prints its own score for a test of the level, and it differs: the page has its own requirement (an accreditation
    -- standard, for example), so the level is not used for this course and rows this rule wrote before are withdrawn
    if exists (select 1 from jsonb_array_elements(v_lv) q
                join ref.english_tests t on t.code = upper(q->>'test_code')
                join catalogue.course_english_requirements e on e.course_id = r.course_id and e.english_test_id = t.id and e.status = 'active'
               where coalesce(e.source_requirement_key, '') not like 'policy:%' and e.overall_score <> (q->>'overall_score')::numeric) then
      v_own_differs := v_own_differs + 1;
      if p_apply then
        with w as (
          update catalogue.course_english_requirements e set status = 'withdrawn', last_verified_at = now(),
                 notes = coalesce(e.notes, '') || format(' Withdrawn %s: the course page prints its own English score, which differs from level "%s" (Decision 264).', v_day, v_label)
           where e.course_id = r.course_id and e.status = 'active' and e.source_requirement_key like 'policy:%' and e.notes like 'English level %Decision 264%'
          returning e.course_id)
        select count(*) into v_out from w;
        v_withdrawn := v_withdrawn + v_out;
        if v_out > 0 then v_courses := v_courses || r.course_id; end if;
      end if;
      continue;
    end if;
    v_tests := array(select upper(q->>'test_code') from jsonb_array_elements(v_lv) q);
    -- the course's own reading (any key that is not a policy's) is never replaced
    v_own := v_own + (select count(*) from jsonb_array_elements(v_lv) q
                       where exists (select 1 from catalogue.course_english_requirements e join ref.english_tests t on t.id = e.english_test_id
                                      where e.course_id = r.course_id and t.code = upper(q->>'test_code') and e.status = 'active'
                                        and coalesce(e.source_requirement_key, '') not like 'policy:%'))::int;
    select coalesce(jsonb_agg(jsonb_build_object(
             'test_code', upper(q->>'test_code'), 'overall_score', q->'overall_score', 'component_scores', coalesce(q->'component_scores', '{}'::jsonb),
             'source_requirement_key', 'policy:' || x.id || ':' || lower(q->>'test_code'),
             'notes', format('English level "%s" %s; scores for that level from %s''s English language requirements (%s), approved by a Platform Admin (Decision 264, 265).',
                             v_label, v_how, v_name, x.url))), '[]'::jsonb)
      into v_write
      from jsonb_array_elements(v_lv) q
     where upper(q->>'test_code') in (select t.code from ref.english_tests t where t.status = 'active')
       and not exists (select 1 from catalogue.course_english_requirements e join ref.english_tests t on t.id = e.english_test_id
                        where e.course_id = r.course_id and t.code = upper(q->>'test_code') and e.status = 'active'
                          and (coalesce(e.source_requirement_key, '') not like 'policy:%'
                               or (e.source_requirement_key = 'policy:' || x.id || ':' || lower(q->>'test_code')
                                   and e.overall_score is not distinct from (q->>'overall_score')::numeric  -- a level may give skill minimums only (no overall)
                                   and e.component_scores = coalesce(q->'component_scores', '{}'::jsonb)
                                   and e.notes like 'English level %Decision 264%')));
    if jsonb_array_length(v_write) = 0 then v_same := v_same + 1; continue; end if;
    if not p_apply then v_written := v_written + 1; continue; end if;
    begin
      perform security.coverage_apply_course_v1(r.course_id, v_src, x.evidence_id, x.url, x.content_hash, jsonb_build_object('english_requirements', v_write));
      -- policy rows for tests this level does not give are withdrawn (kept, not deleted)
      with w as (
        update catalogue.course_english_requirements e set status = 'withdrawn', last_verified_at = now(),
               notes = coalesce(e.notes, '') || format(' Withdrawn %s: the course page names English level "%s", which does not give this test (Decision 264).', v_day, v_label)
          from ref.english_tests t
         where t.id = e.english_test_id and e.course_id = r.course_id and e.status = 'active'
           and e.source_requirement_key like 'policy:%' and t.code <> all (v_tests)
        returning 1)
      select count(*) into v_out from w;
      v_withdrawn := v_withdrawn + v_out;
      v_written := v_written + 1; v_courses := v_courses || r.course_id;
    exception when others then v_err := v_err + 1; v_last := left(sqlerrm, 200);
    end;
  end loop;
  if cardinality(v_courses) > 0 then
    insert into search.enrichment_source_gates(projection_code, domain_code, source_id, gate_status, approval_ref, approved_at, created_at, updated_at)
    select 'courses', 'course_english', v_src, 'approved', 'CF-CHG-20260915-247; Decision 227 (English from the provider''s policy, approved by a Platform Admin)', now(), now(), now()
     where not exists (select 1 from search.enrichment_source_gates g where g.projection_code = 'courses' and g.domain_code = 'course_english' and g.source_id = v_src);
    perform search.refresh_course_enrichment_scoped_v1(v_courses, true);
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('policies', 'english_levels', 'english_policy: ' || x.url,
            jsonb_build_object('proposal_id', x.id, 'provider_id', x.provider_id, 'courses', cardinality(v_courses), 'withdrawn_rows', v_withdrawn,
                               'unknown_levels', v_unknown, 'decision', 264), null);
  end if;
  update pipeline.provider_policy_proposals
     set apply_summary = coalesce(apply_summary, '{}'::jsonb) || jsonb_build_object('levels', jsonb_build_object(
           'courses_written', v_written, 'unchanged', v_same, 'own_reading_tests', v_own, 'own_differs', v_own_differs, 'held', v_held, 'withdrawn_rows', v_withdrawn,
           'unknown_levels', v_unknown, 'refused', v_err, 'last_error', v_last, 'checked_at', now(), 'applied', p_apply)), updated_at = now()
   where id = x.id and p_apply;
  return jsonb_build_object('policy', x.id, 'courses_written', v_written, 'unchanged', v_same, 'own_reading_tests', v_own, 'own_differs', v_own_differs, 'own_differs', v_own_differs, 'held', v_held,
                            'withdrawn_rows', v_withdrawn, 'unknown_levels', v_unknown, 'refused', v_err, 'last_error', v_last);
end $$;


ALTER FUNCTION "security"."english_level_apply_v1"("p_provider_id" "uuid", "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."english_level_group"("p_code" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case when p_code in ('bachelor', 'bachelor_honours', 'associate_degree') then 'undergraduate'
              when p_code in ('graduate_certificate', 'graduate_diploma', 'masters', 'masters_coursework', 'masters_extended') then 'postgraduate'
              when p_code in ('doctorate', 'masters_research') then 'research' end
$$;


ALTER FUNCTION "security"."english_level_group"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."english_level_key"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select nullif(btrim(regexp_replace(regexp_replace(regexp_replace(lower(coalesce(p, '')), '[“”"''’‘`:;,()]', ' ', 'g'), '\s+', ' ', 'g'), '(\d)\.0(?![0-9])', '\1', 'g')), '')
$$;


ALTER FUNCTION "security"."english_level_key"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."english_policy_in_force_all_v1"("p_apply" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_pid uuid; v jsonb; v_out jsonb := '[]'::jsonb; v_moved int := 0; v_l4 int := 0; v_closed int := 0; v_levels int := 0;
begin
  for v_pid in
    select pp.provider_id from pipeline.provider_policy_proposals pp, jsonb_object_keys(coalesce(pp.proposal->'defaults', '{}'::jsonb)) lv
     where pp.kind = 'english_policy' and pp.status = 'approved' and lv in ('undergraduate', 'postgraduate', 'research')
       and jsonb_typeof(pp.proposal->'defaults'->lv) = 'array' and jsonb_array_length(pp.proposal->'defaults'->lv) > 0
     group by pp.provider_id, lv having count(*) > 1
  loop
    if exists (select 1 from jsonb_array_elements(v_out) o where o->>'provider_id' = v_pid::text) then continue; end if;
    v := security.english_policy_in_force_v1(v_pid, p_apply);
    v_out := v_out || (v || jsonb_build_object('provider', (select canonical_name from catalogue.providers where id = v_pid)));
    v_levels := v_levels + (v->>'levels')::int; v_moved := v_moved + (v->>'rows_moved')::int; v_l4 := v_l4 + (v->>'layer4')::int; v_closed := v_closed + (v->>'closed')::int;
  end loop;
  if p_apply and jsonb_array_length(v_out) > 0 then
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('policies', 'in_force', 'english_policy', jsonb_build_object('decision', 'Decision 262', 'universities', jsonb_array_length(v_out), 'levels', v_levels,
            'rows_moved', v_moved, 'layer4', v_l4, 'closed', v_closed, 'items', v_out), null);
  end if;
  return jsonb_build_object('universities', jsonb_array_length(v_out), 'levels', v_levels, 'rows_moved', v_moved, 'layer4', v_l4, 'closed', v_closed, 'items', v_out);
end $$;


ALTER FUNCTION "security"."english_policy_in_force_all_v1"("p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."english_policy_in_force_v1"("p_provider_id" "uuid", "p_apply" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; d record; c record; p pipeline.provider_policy_proposals%rowtype;
        v_items jsonb := '[]'::jsonb; v_stripped jsonb := '[]'::jsonb; v_moved int := 0; v_l4 int := 0; v_closed int := 0; v_l4_courses uuid[] := '{}';
        v_day text := to_char(now() at time zone 'Australia/Melbourne', 'FMDD Mon YYYY');
        v_ref text := 'CF-CHG-20260915-247; Decision 262 (one English policy in force per university and level)';
begin
  for r in
    with docs as (
      select pp.id, lv, pp.decided_at,
             pp.url !~* '(/courses?/|english-for-academic|/bengaluru/)' page_ok,
             not exists (select 1 from jsonb_array_elements(pp.proposal->'defaults'->lv) e where coalesce(e->>'quote', '') = '') quoted,
             (select count(*) from catalogue.course_english_requirements cr join catalogue.courses co on co.id = cr.course_id
                left join ref.study_levels sl on sl.id = co.study_level_id
               where cr.source_requirement_key like 'policy:' || pp.id || ':%' and cr.status = 'active' and security.english_level_group(sl.code) = lv) rows_lv
        from pipeline.provider_policy_proposals pp, jsonb_object_keys(coalesce(pp.proposal->'defaults', '{}'::jsonb)) lv
       where pp.provider_id = p_provider_id and pp.kind = 'english_policy' and pp.status = 'approved'
         and lv in ('undergraduate', 'postgraduate', 'research')
         and jsonb_typeof(pp.proposal->'defaults'->lv) = 'array' and jsonb_array_length(pp.proposal->'defaults'->lv) > 0)
    select docs.lv, array_agg(docs.id order by docs.page_ok desc, docs.quoted desc, docs.rows_lv desc, docs.decided_at desc nulls last) ids
      from docs group by docs.lv having count(*) > 1
  loop
    select * into p from pipeline.provider_policy_proposals where id = r.ids[1];
    for d in select * from pipeline.provider_policy_proposals where id = any (r.ids[2:]) loop
      for c in select cr.id rid, cr.course_id, t.code test, cr.overall_score v
                 from catalogue.course_english_requirements cr join ref.english_tests t on t.id = cr.english_test_id
                 join catalogue.courses co on co.id = cr.course_id left join ref.study_levels sl on sl.id = co.study_level_id
                where cr.source_requirement_key like 'policy:' || d.id || ':%' and cr.status = 'active'
                  and security.english_level_group(sl.code) = r.lv and cr.notes like 'Default for %' loop
        if exists (select 1 from jsonb_array_elements(p.proposal->'defaults'->r.lv) e where e->>'test_code' = c.test and (e->>'overall_score')::numeric = c.v) then
          if p_apply then
            update catalogue.course_english_requirements
               set source_requirement_key = 'policy:' || p.id || ':' || lower(c.test), evidence_id = coalesce(p.evidence_id, evidence_id), last_verified_at = now(),
                   notes = notes || format(' In force from %s: %s (one English policy per university and level).', v_day, p.url)
             where id = c.rid;
          end if;
          v_moved := v_moved + 1;
        elsif not c.course_id = any (v_l4_courses) then
          v_l4_courses := v_l4_courses || c.course_id;
          if p_apply and not exists (select 1 from pipeline.layer4_review_items i where i.entity_type = 'course' and i.entity_id = c.course_id
                                                                                 and i.field_code = 'course_english' and i.status = 'pending') then
            insert into pipeline.layer4_review_items(entity_type, entity_id, field_code, evidence_id, before_value, proposed_value, layer2_state, layer3_state,
                                                     status, escalation_reason, change_control_ref, created_at)
            values ('course', c.course_id, 'course_english', p.evidence_id,
                    (select coalesce(jsonb_agg(jsonb_build_object('test', t2.code, 'overall', x.overall_score) order by t2.code), '[]'::jsonb)
                       from catalogue.course_english_requirements x join ref.english_tests t2 on t2.id = x.english_test_id where x.course_id = c.course_id and x.status = 'active'),
                    jsonb_build_object('english_requirements', (select jsonb_agg(jsonb_build_object('test_code', e->>'test_code', 'overall_score', (e->>'overall_score')::numeric,
                                         'component_scores', coalesce(e->'component_scores', '{}'::jsonb), 'notes', 'From the English policy in force: ' || p.url))
                                                                from jsonb_array_elements(p.proposal->'defaults'->r.lv) e)),
                    jsonb_build_object('page', p.url, 'source', 'English policy in force', 'superseded_policy', d.url),
                    '{}'::jsonb, 'pending',
                    format('This university had two approved English policies for %s courses. This course holds %s %s from %s; the policy now in force (%s) gives %s. Please confirm which is right.',
                           r.lv, c.test, c.v, d.url, p.url,
                           (select string_agg((e->>'test_code') || ' ' || (e->>'overall_score'), ', ') from jsonb_array_elements(p.proposal->'defaults'->r.lv) e)),
                    v_ref, now());
            v_l4 := v_l4 + 1;
          end if;
        end if;
      end loop;
      if p_apply then
        update pipeline.provider_policy_proposals
           set proposal = jsonb_set(proposal #- array['defaults', r.lv], '{superseded_defaults}',
                 coalesce(proposal->'superseded_defaults', '{}'::jsonb) || jsonb_build_object(r.lv, jsonb_build_object('defaults', proposal->'defaults'->r.lv,
                   'in_force', p.id, 'url', p.url, 'at', now()))),
               plan_at = null, updated_at = now()
         where id = d.id;
      end if;
      v_stripped := v_stripped || jsonb_build_object('id', d.id, 'level', r.lv);
      v_items := v_items || jsonb_build_object('level', r.lv, 'in_force', jsonb_build_object('id', p.id, 'url', p.url, 'parser', p.parser),
                                               'gives_up', jsonb_build_object('id', d.id, 'url', d.url, 'parser', d.parser));
    end loop;
  end loop;
  -- a policy left with no level is closed
  select count(*) into v_closed from pipeline.provider_policy_proposals pp
   where pp.provider_id = p_provider_id and pp.kind = 'english_policy' and pp.status = 'approved'
     and not exists (select 1 from jsonb_object_keys(coalesce(pp.proposal->'defaults', '{}'::jsonb)) k
                      where k in ('undergraduate', 'postgraduate', 'research')
                        and jsonb_typeof(pp.proposal->'defaults'->k) = 'array' and jsonb_array_length(pp.proposal->'defaults'->k) > 0
                        and not exists (select 1 from jsonb_array_elements(v_stripped) s where s->>'id' = pp.id::text and s->>'level' = k))
     and exists (select 1 from jsonb_array_elements(v_stripped) s where s->>'id' = pp.id::text);
  if p_apply and v_closed > 0 then
    update pipeline.provider_policy_proposals pp
       set status = 'superseded', decided_at = now(), updated_at = now(),
           decision_note = format('Closed %s: one English policy in force per university and level (Decision 262); its levels are held by another approved policy.', v_day)
     where pp.provider_id = p_provider_id and pp.kind = 'english_policy' and pp.status = 'approved'
       and pp.proposal->'superseded_defaults' is not null
       and not exists (select 1 from jsonb_object_keys(coalesce(pp.proposal->'defaults', '{}'::jsonb)) k
                        where jsonb_typeof(pp.proposal->'defaults'->k) = 'array' and jsonb_array_length(pp.proposal->'defaults'->k) > 0);
  end if;
  return jsonb_build_object('provider_id', p_provider_id, 'levels', jsonb_array_length(v_items), 'rows_moved', v_moved,
                            'layer4', case when p_apply then v_l4 else cardinality(v_l4_courses) end, 'closed', v_closed, 'items', v_items);
end $$;


ALTER FUNCTION "security"."english_policy_in_force_v1"("p_provider_id" "uuid", "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."english_policy_status_v1"("p_provider" "uuid" DEFAULT NULL::"uuid", "p_stage" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 200) RETURNS TABLE("provider_id" "uuid", "provider" "text", "country" "text", "provider_type" "text", "active_courses" bigint, "missing_courses" bigint, "in_scope" boolean, "stage" "text", "why" "text", "pages_tried" "jsonb", "last_reading" "jsonb", "group_count" integer, "bound_groups" integer, "next_try" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'ref', 'security'
    AS $$
  with base as (
    select p.id, coalesce(p.display_name, p.canonical_name) nm, k.iso_alpha2 cc, pt.code ptc, count(c.id) ac,
           count(c.id) filter (where not exists (select 1 from catalogue.course_english_requirements r where r.course_id = c.id and r.status = 'active')) mc
      from catalogue.providers p
      join catalogue.courses c on c.provider_id = p.id and c.lifecycle_status = 'active'
      left join ref.countries k on k.id = p.country_id
      left join ref.provider_types pt on pt.id = p.provider_type_id
     where (p_provider is null or p.id = p_provider) and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id)
     group by p.id, p.display_name, p.canonical_name, k.iso_alpha2, pt.code),
  f as (
    select b.*,
      (select count(*) from pipeline.provider_policy_proposals pp where pp.provider_id = b.id and pp.kind = 'english_policy' and pp.status = 'approved') ap,
      (select count(*) from pipeline.provider_policy_proposals pp where pp.provider_id = b.id and pp.kind = 'english_policy' and pp.status = 'proposed') pr,
      (select count(*) from pipeline.provider_policy_proposals pp where pp.provider_id = b.id and pp.kind = 'english_policy' and pp.status in ('proposed', 'approved')
          and jsonb_array_length(case when jsonb_typeof(pp.proposal->'groups') = 'array' then pp.proposal->'groups' else '[]'::jsonb end) > 0) pg,
      (select count(*) from pipeline.provider_policy_proposals pp where pp.provider_id = b.id and pp.kind = 'english_policy' and pp.status = 'rejected') rj,
      (select coalesce(sum(jsonb_array_length(case when jsonb_typeof(pp.proposal->'groups') = 'array' then pp.proposal->'groups' else '[]'::jsonb end)), 0) from pipeline.provider_policy_proposals pp
         where pp.provider_id = b.id and pp.kind = 'english_policy' and pp.status in ('proposed', 'approved'))::int gc,
      (select coalesce(sum(jsonb_array_length(case when jsonb_typeof(pp.proposal->'group_bindings') = 'array' then pp.proposal->'group_bindings' else '[]'::jsonb end)), 0) from pipeline.provider_policy_proposals pp
         where pp.provider_id = b.id and pp.kind = 'english_policy' and pp.status in ('proposed', 'approved'))::int bg,
      (select count(*) from pipeline.provider_fact_sources fs where fs.provider_id = b.id and fs.kind = 'english_policy') srcs,
      (select count(*) from pipeline.provider_fact_sources fs where fs.provider_id = b.id and fs.kind = 'english_policy' and fs.status in ('read', 'parsed', 'no_values') and fs.evidence_id is not null) stored,
      cs.state cstate, cs.updated_at cat,
      (select count(*) from jsonb_array_elements(coalesce(cs.found, '[]'::jsonb)) e where e->>'kind' = 'english_policy') cands,
      (select count(*) from jsonb_array_elements(coalesce(cs.found, '[]'::jsonb)) e where e->>'kind' = 'english_policy'
          and coalesce((e->>'score')::numeric, 0) >= security.pipeline_num_v1('central.min_suggest_score', 4)) strong
      from base b left join pipeline.provider_central_search cs on cs.provider_id = b.id),
  s as (
    select f.*, case when f.ap > 0 then 'approved' when f.pg > 0 then 'group_proposed' when f.pr > 0 then 'rule_proposed' when f.rj > 0 then 'rejected'
                     when f.stored > 0 then 'page_read_no_rule' when f.srcs > 0 then 'page_not_stored' when f.cands > 0 and f.strong = 0 then 'weak_candidates_only'
                     when f.cstate = 'done' then 'mapped_no_page' else 'not_mapped' end st from f)
  select s.id, s.nm, s.cc, s.ptc, s.ac, s.mc, security.english_provider_in_scope_v1(s.id), s.st,
         case when not security.english_provider_in_scope_v1(s.id) and s.st not in ('approved', 'group_proposed', 'rule_proposed') then 'Not searched: this provider type is outside central.english_provider_types'
              when s.st = 'approved' then 'An approved English policy covers this provider; ' || s.mc || ' of its courses still have no English requirement (levels or groups the policy does not cover, courses it names, research and double degrees stay held)'
              when s.st = 'group_proposed' then 'A faculty or course-group table was read: waiting for a Platform Admin to approve it and bind each group to courses'
              when s.st = 'rule_proposed' then 'A policy reading is waiting for approval'
              when s.st = 'rejected' then 'The last reading was rejected: ' || coalesce((select left(pp.decision_note, 160) from pipeline.provider_policy_proposals pp where pp.provider_id = s.id and pp.kind = 'english_policy' and pp.status = 'rejected' order by pp.decided_at desc nulls last limit 1), 'no reason recorded')
              when s.st = 'page_read_no_rule' then 'A page was read and gave no usable values (' || coalesce((select pp.style from pipeline.provider_policy_proposals pp where pp.provider_id = s.id and pp.kind = 'english_policy' order by pp.created_at desc limit 1), 'no reading recorded') || '); it is read again from the stored copy when the policy parser changes'
              when s.st = 'page_not_stored' then 'A page was found but its copy is not stored yet'
              when s.st = 'weak_candidates_only' then 'Only weak candidate pages were found (below the minimum score of ' || security.pipeline_num_v1('central.min_suggest_score', 4) || ')'
              when s.st = 'mapped_no_page' then 'Site mapped on ' || to_char(s.cat at time zone 'Australia/Melbourne', 'FMDD Mon YYYY') || '; no English page was found'
              else 'Site not mapped yet' end,
         coalesce((select jsonb_agg(jsonb_build_object('url', fs.url, 'status', fs.status, 'attempts', fs.attempts, 'found_via', fs.found_via, 'read_at', fs.read_at) order by fs.rank, fs.created_at) from pipeline.provider_fact_sources fs where fs.provider_id = s.id and fs.kind = 'english_policy'), '[]'::jsonb),
         (select jsonb_build_object('parser', pp.parser, 'status', pp.status, 'style', pp.style, 'at', pp.created_at, 'note', left(pp.decision_note, 200)) from pipeline.provider_policy_proposals pp
           where pp.provider_id = s.id and pp.kind = 'english_policy' order by pp.created_at desc limit 1),
         s.gc, s.bg,
         case when s.st in ('group_proposed', 'rule_proposed') then 'needs a person'
              when s.st in ('mapped_no_page', 'not_mapped', 'weak_candidates_only') then
                case when s.cat is null then 'at the next central-find run' else to_char((s.cat + make_interval(days => security.pipeline_num_v1('central.research_days', 7)::int)) at time zone 'Australia/Melbourne', 'FMDD Mon YYYY') end
              when s.st = 'page_read_no_rule' then 'at the next policy-add-tests run after the parser changes'
              when s.st = 'approved' then 'when its pages change' else 'at the next central-attach run' end
    from s where (p_stage is null or s.st = p_stage)
   order by s.mc desc, s.nm limit greatest(1, least(coalesce(p_limit, 200), 1000));  -- fixed: display cap for one panel read
$$;


ALTER FUNCTION "security"."english_policy_status_v1"("p_provider" "uuid", "p_stage" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."english_policy_status_v1"("p_provider" "uuid", "p_stage" "text", "p_limit" integer) IS 'CF-247 English requirements (6 Nov 2026 §5): one row per published provider with active courses: stage on the English policy route, pages tried, last reading, why there is no rule, group counts and the next try. Persisted records only.';



CREATE OR REPLACE FUNCTION "security"."english_provider_in_scope_v1"("p_provider" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'ref'
    AS $$
  with s as (select coalesce((select t.value from pipeline.platform_toolset_settings t where t.toolset_key = 'pipeline' and t.key = 'central.english_provider_types'), '["*"]'::jsonb) v)
  select exists (select 1 from s, jsonb_array_elements_text(case when jsonb_typeof(s.v) = 'array' then s.v else '["*"]'::jsonb end) t
                  where t = '*' or t = (select pt.code from catalogue.providers p join ref.provider_types pt on pt.id = p.provider_type_id where p.id = p_provider))
$$;


ALTER FUNCTION "security"."english_provider_in_scope_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."english_provider_in_scope_v1"("p_provider" "uuid") IS 'CF-247 English requirements (6 Nov 2026 D1): whether the provider''s type is in setting central.english_provider_types (["*"] is every type). Read by the central English route.';



CREATE OR REPLACE FUNCTION "security"."english_table_plan_v1"("p_provider_cricos" "text", "p_programs" "jsonb", "p_minimum" "jsonb") RETURNS TABLE("course_id" "uuid", "course_cricos" "text", "title" "text", "study_level" "text", "plan" "text", "reason" "text", "program" "text", "requirements" "jsonb", "existing" "jsonb", "comparison" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'ref', 'security'
    AS $$
declare v_provider uuid; v_aliases jsonb; v_double text;
begin
  select s.provider_id, coalesce(s.metadata->'aliases','{}'::jsonb), s.metadata->>'double_degree_rule' into v_provider, v_aliases, v_double from pipeline.sources s
   where s.source_type='provider_english_requirements' and s.metadata->>'provider_cricos'=upper(btrim(p_provider_cricos)) limit 1;
  if v_provider is null then raise exception 'no English requirements source for provider %', p_provider_cricos; end if;
  return query
  with t1 as materialized (
    select e->>'name' name, coalesce(e->>'section','coursework') section, e->'requirements' reqs,
           coalesce(v_aliases->>security.english_title_key(e->>'name'), security.english_title_key(e->>'name')) k
      from jsonb_array_elements(coalesce(p_programs,'[]'::jsonb)) e),
  t1t as materialized (select t1.*, security.english_title_tokens(t1.k) tok from t1),
  c as materialized (
    select co.id, co.canonical_title t, security.english_title_key(co.canonical_title) k, sl.code lvl,
           (select min(upper(btrim(cr.registration_code))) from catalogue.course_registrations cr where cr.course_id=co.id and lower(cr.scheme)='cricos') cricos,
           (select coalesce(jsonb_object_agg(et.code, r.overall_score),'{}'::jsonb) from catalogue.course_english_requirements r join ref.english_tests et on et.id=r.english_test_id
             where r.course_id=co.id and r.status='active') ex
      from catalogue.courses co left join ref.study_levels sl on sl.id=co.study_level_id
     where co.provider_id=v_provider and co.lifecycle_status='active'),
  ct as materialized (select c.*, security.english_title_tokens(c.k) tok from c),
  m as materialized (
    select ct.*,
           (select jsonb_agg(jsonb_build_object('name',t1.name,'reqs',t1.reqs)) from t1 where t1.k=ct.k) exact,
           exists(select 1 from t1t where t1t.k<>ct.k and (position(t1t.k in ct.k)>0
                  or (select count(*) from unnest(ct.tok) u where u = any(t1t.tok))::numeric / nullif(greatest(cardinality(ct.tok),cardinality(t1t.tok)),0) >= 0.75)) close
      from ct),
  p as materialized (
    select m.*,
      case when m.exact is not null and (select count(distinct x->'reqs') from jsonb_array_elements(m.exact) x)>1 then 'held'
           when m.exact is not null then 'table1'
           when m.lvl='non_aqf_award' or m.lvl is null then 'held'
           when m.t ~* 'exit award' then 'held'
           when m.lvl in ('doctorate','masters_research') then 'held'
           when m.k ~ '/' or m.k ~ ' and (bachelor|master|doctor|graduate|diploma|associate) (of|in) ' then 'held'
           when m.close then 'held'
           else 'minimum' end pl,
      case when m.exact is not null and (select count(distinct x->'reqs') from jsonb_array_elements(m.exact) x)>1 then 'conflicting Table 1 entries for one name'
           when m.exact is not null then null
           when m.lvl is null then 'study level unknown'
           when m.lvl='non_aqf_award' then 'not an award program'
           when m.t ~* 'exit award' then 'exit award only: not an admission program'
           when m.lvl in ('doctorate','masters_research') then 'research degree: Table 1 research rule is not tied to a named program'
           when m.k ~ '/' or m.k ~ ' and (bachelor|master|doctor|graduate|diploma|associate) (of|in) ' then 'double degree: the policy has no double-degree rule'
           when m.close then 'close to a Table 1 program name: review'
           else null end rs
      from m),
  dd as materialized (
    select p.id, comp.ord, btrim(comp.c) c,
           (select t1.reqs from t1 where t1.k=btrim(comp.c) limit 1) t1reqs,
           (select t1.name from t1 where t1.k=btrim(comp.c) limit 1) t1name,
           exists(select 1 from p p2 where p2.k=btrim(comp.c) and p2.pl='minimum') single_min
      from p, regexp_split_to_table(p.k,'/| and (?=(bachelor|master|doctor|graduate|diploma|associate) (of|in) )') with ordinality comp(c,ord)
     where p.rs='double degree: the policy has no double-degree rule'),
  ddr as materialized (
    select dd.id,
           bool_and(dd.t1reqs is not null or dd.single_min) all_known,
           string_agg(dd.c,'; ' order by dd.ord) filter (where dd.t1reqs is null and not dd.single_min) unknown,
           count(distinct dd.t1reqs) n_t1,
           (array_agg(dd.t1reqs order by dd.ord) filter (where dd.t1reqs is not null))[1] reqs,
           string_agg(dd.t1name,' + ' order by dd.ord) filter (where dd.t1name is not null) t1names
      from dd group by dd.id),
  q as materialized (
    select p.*,
      case when ddr.id is null then p.pl
           when not ddr.all_known or ddr.n_t1>1 then 'held'
           when v_double='higher_component_v1' then case when ddr.n_t1=1 then 'table1' else 'minimum' end
           else 'held' end pl2,
      case when ddr.id is null then p.rs
           when not ddr.all_known then 'double degree: component not recognised ('||ddr.unknown||')'
           when ddr.n_t1>1 then 'double degree: components carry different Table 1 requirements'
           when v_double='higher_component_v1' then 'double degree: higher component ('||case when ddr.n_t1=1 then 'Table 1: '||ddr.t1names else 'minimum' end||')'
           else 'double degree trial: would take '||case when ddr.n_t1=1 then 'Table 1 ('||ddr.t1names||')' else 'the minimum' end end rs2,
      case when ddr.id is null then case when p.pl='table1' then p.exact->0->>'name' end
           when ddr.all_known and ddr.n_t1=1 then ddr.t1names end prog2,
      case when ddr.id is null then case when p.pl='table1' then p.exact->0->'reqs' when p.pl='minimum' then p_minimum end
           when ddr.all_known and ddr.n_t1<=1 then coalesce(ddr.reqs,p_minimum) end reqs2
      from p left join ddr on ddr.id=p.id)
  select q.id, q.cricos, q.t, q.lvl, q.pl2, q.rs2, q.prog2, q.reqs2, q.ex,
         case when q.reqs2 is null then null
              when q.ex='{}'::jsonb then 'none'
              when exists(select 1 from jsonb_array_elements(q.reqs2) r
                           where q.ex ? (r->>'test_code') and (q.ex->>(r->>'test_code'))::numeric<>(r->>'overall_score')::numeric) then 'differs'
              when exists(select 1 from jsonb_array_elements(q.reqs2) r where q.ex ? (r->>'test_code')) then 'agrees'
              else 'other_tests_only' end
    from q;
end $$;


ALTER FUNCTION "security"."english_table_plan_v1"("p_provider_cricos" "text", "p_programs" "jsonb", "p_minimum" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."english_title_key"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
  select btrim(regexp_replace(regexp_replace(regexp_replace(
           replace(regexp_replace(lower(coalesce(p,'')),'\(\s*\d+\s+units(\s+and\s+\d+\s+units)?\s*\)','','g'),'&',' and '),
           '[^a-z0-9/]+',' ','g'),' ?/ ?','/','g'),'\s+',' ','g'))
$$;


ALTER FUNCTION "security"."english_title_key"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."english_title_overlap"("a" "text", "b" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
  with x as (select distinct t from unnest(regexp_split_to_array(a,'[ /]+')) t where t not in ('of','and','in','the','')),
       y as (select distinct t from unnest(regexp_split_to_array(b,'[ /]+')) t where t not in ('of','and','in','the',''))
  select coalesce((select count(*) from x join y using (t))::numeric / nullif(greatest((select count(*) from x),(select count(*) from y)),0),0)
$$;


ALTER FUNCTION "security"."english_title_overlap"("a" "text", "b" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."english_title_tokens"("p" "text") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
  select coalesce(array_agg(distinct t),'{}') from unnest(regexp_split_to_array(coalesce(p,''),'[ /]+')) t where t not in ('of','and','in','the','')
$$;


ALTER FUNCTION "security"."english_title_tokens"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_ai_fire_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_open int; v_max int := security.pipeline_num_v1('enrich.ai_calls_at_once', 2)::int; v_due int; v_sent int := 0;
begin
  if not security.ai_use_allowed_v1('enrich_fields') then return 0; end if;
  select count(*) into v_due from pipeline.field_enrich_items where state = 'ai' or (state = 'leased' and leased_until < now());
  if v_due = 0 then return 0; end if;
  select count(*) into v_open from pipeline.edge_request_log l where l.function_name = 'coverage-sweep' and l.mode = 'enrich_ai' and l.created_at > now() - make_interval(mins => 3)
     and not exists (select 1 from net._http_response r where r.id = l.request_id);
  while v_open + v_sent < v_max and v_sent * 10 < v_due loop
    perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'enrich_ai', 'limit', security.pipeline_num_v1('enrich.ai_items_per_call', 30)::int,
                                                                       'concurrency', security.pipeline_num_v1('enrich.ai_pages_at_once', 3)::int));
    v_sent := v_sent + 1;
  end loop;
  return v_sent;
end $$;


ALTER FUNCTION "security"."enrich_ai_fire_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_apply_v1"("p_item" bigint) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.field_enrich_items%rowtype; v_n int := 0; v_lock boolean;
begin
  select * into i from pipeline.field_enrich_items where id = p_item for update;
  if i.id is null or i.value is null then return 'nothing'; end if;
  v_lock := exists (select 1 from pipeline.manual_locks l where l.entity = case when i.course_id is null then 'provider' else 'course' end
                     and l.entity_id = coalesce(i.course_id, i.provider_id) and l.field in (i.field, 'all'));
  if v_lock then
    update pipeline.field_enrich_items set state = 'skipped', reason = 'locked by hand', updated_at = now() where id = i.id; return 'locked';
  end if;
  if i.field = 'duration' then
    update catalogue.courses set duration_value = (i.value->>'value')::numeric, duration_unit = i.value->>'unit', updated_at = now()
     where id = i.course_id and duration_value is null;
  elsif i.field = 'level' then
    update catalogue.courses set study_level_id = (i.value->>'level_id')::uuid, updated_at = now() where id = i.course_id and study_level_id is null;
  elsif i.field = 'delivery' then
    update catalogue.courses set delivery_mode = i.value->>'mode', updated_at = now() where id = i.course_id and nullif(btrim(delivery_mode), '') is null;
  elsif i.field = 'field_of_study' then
    update catalogue.courses set primary_field_id = (i.value->>'field_id')::uuid, updated_at = now() where id = i.course_id and primary_field_id is null;
  elsif i.field = 'international' then
    update catalogue.courses set open_to_international = (i.value->>'open')::boolean, updated_at = now() where id = i.course_id and open_to_international is null;
  elsif i.field = 'provider_address' then
    update catalogue.providers set address_line1 = left(i.value->>'street', 200), postcode = coalesce(postcode, left(i.value->>'postcode', 20)),
           primary_city = coalesce(nullif(btrim(primary_city), ''), left(i.value->>'city', 120)), updated_at = now()
     where id = i.provider_id and nullif(btrim(address_line1), '') is null;
  elsif i.field in ('english', 'intakes') and i.course_id is not null then
    -- 23 Oct 2026 (Platform Admin 10:25): the AI reading of the course page, admitted like a page reading
    declare g record; v_src uuid; v_payload jsonb;
    begin
      select pg.provider_id, pg.identity_basis, pg.url, pg.evidence_id, e.content_hash, coalesce(e.source_url, pg.url) src_url into g
        from pipeline.coverage_course_pages pg left join pipeline.evidence_artifacts e on e.id = pg.evidence_id where pg.course_id = i.course_id;
      if exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = i.course_id
                   and l.field in (case i.field when 'english' then 'english_requirements' else 'intake' end, i.field, 'all')) then
        update pipeline.field_enrich_items set state = 'skipped', reason = 'locked by hand', updated_at = now() where id = i.id; return 'locked';
      end if;
      if g.provider_id is null or not security.coverage_identity_allowed(g.provider_id, g.identity_basis, i.field) then
        update pipeline.field_enrich_items set state = 'skipped', reason = 'the page''s proof (' || coalesce(g.identity_basis, 'none') || ') does not admit ' || i.field || ' for this country', updated_at = now() where id = i.id;
        return 'not_admitted';
      end if;
      if (i.field = 'english' and exists (select 1 from catalogue.course_english_requirements x where x.course_id = i.course_id and coalesce(x.status, 'active') = 'active'))
         or (i.field = 'intakes' and exists (select 1 from catalogue.course_intakes x where x.course_id = i.course_id and x.status = 'active')) then
        update pipeline.field_enrich_items set state = 'skipped', reason = 'already filled', updated_at = now() where id = i.id; return 'already';
      end if;
      v_src := security.coverage_sweep_source(g.provider_id);
      insert into search.enrichment_source_gates(projection_code, domain_code, source_id, gate_status, approval_ref, approved_at, created_at, updated_at)
      select 'courses', case i.field when 'english' then 'course_english' else 'course_intake' end, v_src, 'approved',
             'CF-CHG-20260915-247, Platform Admin 23 Oct 2026 10:25 (AI reader for every attribute; page proof admitted by country)', now(), now(), now()
       where not exists (select 1 from search.enrichment_source_gates x where x.projection_code = 'courses' and x.domain_code = case i.field when 'english' then 'course_english' else 'course_intake' end and x.source_id = v_src);
      v_payload := case i.field
        when 'english' then jsonb_build_object('english_requirements', jsonb_build_array(jsonb_build_object('test_code', 'IELTS', 'overall_score', (i.value->>'overall')::numeric,
                 'component_scores', case when i.value->>'band' is null then '{}'::jsonb else jsonb_build_object('listening', (i.value->>'band')::numeric, 'reading', (i.value->>'band')::numeric, 'writing', (i.value->>'band')::numeric, 'speaking', (i.value->>'band')::numeric) end,
                 'notes', left('AI reading of the course page: ' || coalesce(i.quote, ''), 300))))
        else jsonb_build_object('intakes', (select jsonb_agg(jsonb_build_object('intake_label', m, 'source_intake_key', lower(i.course_id::text) || ':ai:' || lower(m))) from jsonb_array_elements_text(i.value->'months') m)) end;
      perform security.coverage_apply_course_v1(i.course_id, v_src, coalesce(i.evidence_id, g.evidence_id), g.src_url, g.content_hash, v_payload);
      -- 23 Oct 2026 11:25: no per-value search refresh (it ran past the worker call's time limit); one open request instead
      insert into search.refresh_requests(requested_by) select 'AI reader (English, intakes)'
       where not exists (select 1 from search.refresh_requests q where q.processed_at is null and q.requested_by = 'AI reader (English, intakes)');
    end;
    -- the row count below says whether the value is now held
    update pipeline.field_enrich_items set updated_at = now() where id = i.id
       and ((i.field = 'english' and exists (select 1 from catalogue.course_english_requirements x where x.course_id = i.course_id and coalesce(x.status, 'active') = 'active'))
         or (i.field = 'intakes' and exists (select 1 from catalogue.course_intakes x where x.course_id = i.course_id and x.status = 'active')));
  elsif i.field = 'campus_region' then
    insert into pipeline.city_regions(country_id, city_key, city, subdivision_id, source, item_id)
    select p.country_id, lower(btrim(x->>'city')), btrim(x->>'city'), s.id, 'ai', i.id
      from jsonb_array_elements(coalesce(i.value->'cities', '[]'::jsonb)) x
      join catalogue.providers p on p.id = i.provider_id
      join ref.subdivisions s on s.country_id = p.country_id and s.name = x->>'region'
    on conflict (country_id, city_key) do nothing;
    update catalogue.campuses c set subdivision_id = r.subdivision_id, updated_at = now()
      from pipeline.city_regions r
     where c.subdivision_id is null and c.country_id = r.country_id and lower(btrim(c.city)) = r.city_key
       and c.provider_id = i.provider_id;
  elsif i.field = 'campus' and i.course_id is not null then
    insert into catalogue.course_campuses(course_id, campus_id, delivery_mode, is_primary, evidence_id)
    select i.course_id, (x->>'campus_id')::uuid, coalesce((select nullif(btrim(c.delivery_mode), '') from catalogue.courses c where c.id = i.course_id and c.delivery_mode in ('on_campus', 'blended', 'on_campus_and_online')), 'on_campus'),
           row_number() over () = 1, i.evidence_id
      from jsonb_array_elements(i.value->'campuses') x
     where not exists (select 1 from catalogue.course_campuses cc where cc.course_id = i.course_id and cc.campus_id = (x->>'campus_id')::uuid)
    on conflict do nothing;
  end if;
  get diagnostics v_n = row_count;
  update pipeline.field_enrich_items set state = case when v_n > 0 then 'filled' else 'skipped' end,
         reason = case when v_n > 0 then reason else coalesce(reason, 'already filled') end, updated_at = now() where id = i.id;
  return case when v_n > 0 then 'filled' else 'already' end;
end $$;


ALTER FUNCTION "security"."enrich_apply_v1"("p_item" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_campus_link_v1"("p_job" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_ids jsonb; v_linked int := 0;
begin
  for r in select c.id, c.quote, l.state list_state, coalesce(l.value->'admitted', '[]'::jsonb) admitted
             from pipeline.field_enrich_items c
             join pipeline.field_enrich_items l on l.job_id = c.job_id and l.provider_id = c.provider_id and l.field = 'campus_list'
            where c.job_id = p_job and c.field = 'campus' and c.course_id is not null and c.state = 'waiting' and c.quote is not null
              and l.state in ('filled', 'review', 'skipped', 'failed') loop
    select coalesce(jsonb_agg(jsonb_build_object('campus_id', a->>'campus_id', 'name', a->>'name')), '[]'::jsonb) into v_ids
      from jsonb_array_elements(r.admitted) a
     where exists (select 1 from jsonb_array_elements_text(coalesce(a->'raw', '[]'::jsonb)) rw where lower(r.quote) like '%' || lower(rw) || '%');
    if jsonb_array_length(v_ids) > 0 then
      update pipeline.field_enrich_items set value = jsonb_build_object('campuses', v_ids), updated_at = now() where id = r.id;
      if security.enrich_apply_v1(r.id) = 'filled' then v_linked := v_linked + 1; end if;
    elsif r.list_state = 'filled' then
      update pipeline.field_enrich_items set state = 'review', reason = 'the campus named on the page is not in the admitted list', updated_at = now() where id = r.id;
    else
      update pipeline.field_enrich_items set state = 'skipped', reason = 'no campus list was admitted for the university', updated_at = now() where id = r.id;
    end if;
  end loop;
  return v_linked;
end $$;


ALTER FUNCTION "security"."enrich_campus_link_v1"("p_job" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_campus_list_apply_v1"("p_item" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.field_enrich_items%rowtype; x jsonb; v_cid uuid; v_min int := security.pipeline_num_v1('enrich.campus_min_pages', 2)::int;
        v_admitted jsonb := '[]'::jsonb; v_review jsonb := '[]'::jsonb; v_pages int; v_country uuid; v_sub uuid; v_cc text; v_pcity text; r record; v_ids jsonb; v_linked int := 0;
begin
  select * into i from pipeline.field_enrich_items where id = p_item for update;
  select p.country_id, p.subdivision_id, k.iso_alpha2::text, p.primary_city into v_country, v_sub, v_cc, v_pcity
    from catalogue.providers p join ref.countries k on k.id = p.country_id where p.id = i.provider_id;
  for x in select * from jsonb_array_elements(coalesce(i.value->'campuses', '[]'::jsonb)) loop
    -- agreement: the course pages that name this campus (its raw names) are counted from the job's own campus items
    select count(*) into v_pages from pipeline.field_enrich_items c
     where c.job_id = i.job_id and c.provider_id = i.provider_id and c.field = 'campus' and c.course_id is not null
       and exists (select 1 from jsonb_array_elements_text(coalesce(x->'raw', '[]'::jsonb)) rw where lower(c.quote) like '%' || lower(rw) || '%');
    select ca.id into v_cid from catalogue.campuses ca where ca.provider_id = i.provider_id and lower(ca.name) = lower(x->>'name') limit 1;
    -- 23 Oct 2026: a campus the university already has (active) is linked from one course page that names it; a new campus needs v_min pages
    if v_pages < 1 or (v_pages < v_min and not exists (select 1 from catalogue.campuses ca where ca.id = v_cid and ca.status = 'active')) then
      v_cid := null; v_review := v_review || (x || jsonb_build_object('pages', v_pages)); continue;
    end if;
    if v_cid is null then
      insert into catalogue.campuses(stable_key, provider_id, name, country_id, subdivision_id, city, address_line1, postcode, status, publication_status, evidence_id)
      values ('campus:studysearch:' || i.provider_id || ':' || regexp_replace(lower(x->>'name'), '[^a-z0-9]+', '-', 'g'), i.provider_id, left(x->>'name', 160), v_country,
              -- v2.15.276 O1: the provider's region only where it is proven for this campus (Canada: the province; elsewhere the provider's own city)
              case when v_cc = 'CA' or (nullif(btrim(x->>'city'), '') is not null and lower(btrim(x->>'city')) = lower(btrim(coalesce(v_pcity, '')))) then v_sub end,
              left(nullif(x->>'city', ''), 120), left(nullif(x->>'street', ''), 200), left(nullif(x->>'postcode', ''), 20), 'active', 'published', i.evidence_id)
      on conflict (stable_key) do update set updated_at = now()
      returning id into v_cid;
    end if;
    v_admitted := v_admitted || (x || jsonb_build_object('campus_id', v_cid, 'pages', v_pages));
  end loop;
  update pipeline.field_enrich_items set state = case when jsonb_array_length(v_admitted) > 0 then 'filled' when jsonb_array_length(v_review) > 0 then 'review' else 'skipped' end,
         value = value || jsonb_build_object('admitted', v_admitted, 'to_review', v_review),
         reason = case when jsonb_array_length(v_review) > 0 then jsonb_array_length(v_review) || ' campus name(s) named on too few course pages: a person decides' else reason end, updated_at = now()
   where id = i.id;
  return jsonb_build_object('admitted', jsonb_array_length(v_admitted), 'review', jsonb_array_length(v_review));
end $$;


ALTER FUNCTION "security"."enrich_campus_list_apply_v1"("p_item" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_course_field_missing_v1"("p_course" "uuid", "p_field" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce((select case p_field
           when 'campus' then not exists (select 1 from catalogue.course_campuses x where x.course_id = c.id)
           when 'duration' then c.duration_value is null when 'level' then c.study_level_id is null
           when 'delivery' then nullif(btrim(c.delivery_mode), '') is null when 'field_of_study' then c.primary_field_id is null
           when 'international' then c.open_to_international is null
           when 'english' then not exists (select 1 from catalogue.course_english_requirements x where x.course_id = c.id and coalesce(x.status, 'active') = 'active')
           when 'intakes' then not exists (select 1 from catalogue.course_intakes x where x.course_id = c.id and x.status = 'active')
           when 'description' then nullif(btrim(c.description), '') is null
           when 'deadline' then security.enrich_deadline_missing_v1(c.id)
           else false end
     from catalogue.courses c where c.id = p_course and c.lifecycle_status = 'active'), false)
$$;


ALTER FUNCTION "security"."enrich_course_field_missing_v1"("p_course" "uuid", "p_field" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."enrich_course_field_missing_v1"("p_course" "uuid", "p_field" "text") IS 'CF-247 Release B (3 Nov 2026): whether an active course is missing a field, by the standing gap queue''s rules (field_gap_scan_v1; description and deadline as enrich_course_text_gaps_v1).';



CREATE OR REPLACE FUNCTION "security"."enrich_course_text_gaps_v1"("p_fields" "text"[]) RETURNS TABLE("provider_id" "uuid", "course_id" "uuid", "field" "text", "pri" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_cap int := security.pipeline_num_v1('enrich.course_text_items_per_day', 500)::int; v_days int := security.pipeline_num_v1('gaps.recheck_days', 60)::int;
        f text; v_room int; v_gmax int := security.pipeline_num_v1('enrich.course_description_pending_global_max', 0)::int;
        v_pmax int := security.pipeline_num_v1('enrich.course_description_pending_max', 10)::int; v_stamp text := security.course_description_machine_policy_stamp_v1();
begin
  foreach f in array array['description', 'deadline'] loop
    continue when not (f = any (coalesce(p_fields, '{}'::text[])));
    -- back-pressure (CF-247 C-DESC 8 Nov 2026): no new description readings while v_gmax descriptions already wait for a person (0 = off)
    continue when f = 'description' and v_gmax > 0
      and (select count(*) from pipeline.layer4_review_items q where q.entity_type = 'course' and q.field_code = 'course_description_first_read' and q.status = 'pending') >= v_gmax;
    select v_cap - count(*) into v_room from pipeline.field_enrich_items e join pipeline.admin_jobs j on j.id = e.job_id
     where e.field = f and e.created_at > now() - interval '1 day' and coalesce((j.args->>'standing')::boolean, false);  -- fixed: the cap is a day's
    continue when coalesce(v_room, 0) <= 0;
    return query
      with miss as (
        select c.id cid, c.provider_id pid from catalogue.courses c
         where c.lifecycle_status = 'active'
           and case f when 'description' then nullif(btrim(c.description), '') is null else security.enrich_deadline_missing_v1(c.id) end
           -- read from the stored page only: the slice's rule (bound, or ambiguous with an identity proof, read)
           and exists (select 1 from pipeline.coverage_course_pages g where g.course_id = c.id and g.evidence_id is not null and g.status in ('bound', 'ambiguous')
                         and g.read_status = 'read' and g.identity_basis is not null)),
      last as (
        select distinct on (e.course_id) e.course_id cid, e.state, e.updated_at, e.reason,
               -- a reading held behind the provider's places that never recorded which model and prompt made it, and has no stored answer that proves it: it is read once more so the reader is recorded (the machine rule admits only a provable reader)
               (e.reason like 'held\_first\_admission:%' and nullif(e.value->'reader'->>'model', '') is null
                and not exists (select 1 from pipeline.enrich_ai_answers a where a.item_id = e.id and nullif(a.answer->>'model', '') is not null and nullif(a.answer->>'prompt_version', '') is not null
                                  and a.answer->'value'->'sentences' = e.value->'sentences')) unproven,
               -- cdesc-source-grounded-v1 (CF-247 F-CDESC, 12 Nov 2026): a description reading held by a check, or superseded in Layer 4, that an earlier prompt made is read once more with the released prompt
               -- (a reading held behind the provider's places passed its checks: it follows a decision through course_description_promote_held_v1 and is not read again here)
               -- 12 Nov 2026 (first-cycle check of #1047): a reading superseded in Layer 4, or marked reread: (a reading the worker mis-recorded, read again on a recorded decision), is read again whatever prompt made it
               (f = 'description' and e.state = 'skipped' and ((e.reason like 'held%' and e.reason not like 'held\_first\_admission:%'
                and coalesce(e.value->>'prompt_version', e.value->'reader'->>'prompt', '') <> security.cdesc_prompt_version_v1()) or e.reason like 'superseded:%' or e.reason like 'reread:%')) old_prompt
          from pipeline.field_enrich_items e where e.field = f and e.course_id in (select m.cid from miss m) order by e.course_id, e.id desc),
      -- a university whose every place for a first description is taken by a description that waits for a person (and that the machine has not declined for good) gets no new reading until one is decided
      full_p as (
        select c.provider_id pid from pipeline.layer4_review_items q join catalogue.courses c on c.id = q.entity_id
         where f = 'description' and q.entity_type = 'course' and q.field_code = 'course_description_first_read' and q.status = 'pending'
           and not exists (select 1 from pipeline.course_description_machine_admissions d where d.review_item_id = q.id and d.outcome = 'declined' and d.withdrawn_at is null and not d.transient and d.policy_stamp = v_stamp)
         group by 1 having count(*) >= v_pmax and not security.course_description_trusted_v1(c.provider_id)),
      pick as (
        select m.pid, m.cid, case when coalesce(l.unproven, false) then 0 when l.state is null or coalesce(l.old_prompt, false) then 1
                                  when exists (select 1 from pipeline.coverage_course_pages g where g.course_id = m.cid and g.read_at > l.updated_at) then 0 else 2 end pri
          from miss m left join last l on l.cid = m.cid
         where not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = m.cid and k.field in (f, 'all'))
           and coalesce(l.state, '') not in ('queued', 'waiting', 'ai', 'leased', 'review')
           and (l.state is null or l.state = 'filled' or l.reason = 'provider unpublished' or coalesce(l.unproven, false) or coalesce(l.old_prompt, false) or l.updated_at < now() - make_interval(days => v_days)
                or exists (select 1 from pipeline.coverage_course_pages g where g.course_id = m.cid and g.read_at > l.updated_at))
           and not security.enrich_item_held_v1(m.cid, f)
           and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = m.pid)
           and not exists (select 1 from full_p fp where fp.pid = m.pid))
      select z.pid, z.cid, f, z.pri
        from (select p.pid, p.cid, p.pri, row_number() over (partition by p.pid, p.pri order by p.cid) rn from pick p) z
       order by z.pri, z.rn, z.cid
       limit v_room;
  end loop;
end $$;


ALTER FUNCTION "security"."enrich_course_text_gaps_v1"("p_fields" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."enrich_course_text_gaps_v1"("p_fields" "text"[]) IS 'CF-247 Workstream C (3 Nov 2026): course description and application deadline gaps for the standing gap queue: active courses with a stored page, the queue''s rules (locks, holds, unpublished providers, recheck days, in progress), at most enrich.course_text_items_per_day new standing items a day for each field.';



CREATE OR REPLACE FUNCTION "security"."enrich_course_text_record_v1"("p_item" bigint, "p_r" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare i pipeline.field_enrich_items%rowtype; g record; v_chk jsonb; v_text text; v_review uuid; v_pid uuid; v_n int := 0; x jsonb; it record;
        v_date date; v_kept jsonb := '[]'::jsonb; v_dl jsonb := '[]'::jsonb; v_why text; v_max_before int := security.pipeline_num_v1('intake_dates.deadline_max_days_before', 366)::int;
        v_targets uuid[]; v_one uuid; v_kinds text[];
begin
  select * into i from pipeline.field_enrich_items where id = p_item for update;
  if i.id is null or i.course_id is null or i.field not in ('description', 'deadline') then return 'nothing'; end if;
  select pg.provider_id, pg.identity_basis, pg.url, pg.evidence_id, e.captured_at into g
    from pipeline.coverage_course_pages pg left join pipeline.evidence_artifacts e on e.id = pg.evidence_id where pg.course_id = i.course_id;
  if g.provider_id is null or not security.coverage_identity_allowed(g.provider_id, g.identity_basis, i.field) then
    update pipeline.field_enrich_items set state = 'skipped', reason = 'the page''s proof (' || coalesce(g.identity_basis, 'none') || ') does not admit ' || i.field || ' for this country',
           value = p_r->'value', updated_at = now() where id = i.id;
    return 'not_admitted';
  end if;
  -- only the course's own page: the stored copy read is the copy bound to the course now
  if i.evidence_id is distinct from g.evidence_id then
    update pipeline.field_enrich_items set state = 'skipped', reason = 'the copy read is no longer the course''s bound page (it is read again with the new copy)', value = p_r->'value', updated_at = now() where id = i.id;
    return 'not_admitted';
  end if;
  if exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = i.course_id
               and l.field in (i.field, case i.field when 'deadline' then 'intake' else 'course_description' end, 'all')) then
    update pipeline.field_enrich_items set state = 'skipped', reason = 'locked by hand', value = p_r->'value', updated_at = now() where id = i.id;
    return 'locked';
  end if;
  select c.provider_id into v_pid from catalogue.courses c where c.id = i.course_id;

  if i.field = 'description' then
    if exists (select 1 from catalogue.courses c where c.id = i.course_id and nullif(btrim(c.description), '') is not null) then
      update pipeline.field_enrich_items set state = 'skipped', reason = 'already filled', value = p_r->'value', updated_at = now() where id = i.id; return 'already';
    end if;
    v_chk := security.course_description_check_v1(i.course_id, p_r->'value');
    if not coalesce((v_chk->>'ok')::boolean, false) then
      update pipeline.field_enrich_items set state = 'skipped', value = coalesce(p_r->'value', '{}'::jsonb) || jsonb_build_object('check', v_chk, 'reader', jsonb_build_object('model', p_r->>'model', 'prompt', p_r->>'prompt_version', 'worker', p_r->>'worker')),
             reason = left(case when v_chk->>'rule' = 'not_stated' then coalesce(nullif(p_r->>'reason', ''), 'the page does not state it')
                                else 'held: ' || (v_chk->>'rule') || ': ' || (v_chk->>'reason') end, 300), updated_at = now()
       where id = i.id;
      return case when v_chk->>'rule' = 'not_stated' then 'not_stated' else 'held' end;
    end if;
    v_text := v_chk->>'text';
    if security.course_description_trusted_v1(v_pid) then
      update catalogue.courses set description = v_text, updated_at = now() where id = i.course_id and nullif(btrim(description), '') is null;
      get diagnostics v_n = row_count;
      update pipeline.field_enrich_items set state = case when v_n > 0 then 'filled' else 'skipped' end, reason = case when v_n > 0 then null else 'already filled' end,
             value = p_r->'value' || jsonb_build_object('text', v_text, 'check', v_chk, 'admitted', 'checks (provider''s first descriptions approved in Layer 4)'),
             quote = left(coalesce(p_r->>'quote', i.quote), 300), updated_at = now() where id = i.id;
      insert into search.refresh_requests(requested_by) select 'AI reader (course description, deadline)'
       where v_n > 0 and not exists (select 1 from search.refresh_requests q where q.processed_at is null and q.requested_by = 'AI reader (course description, deadline)');
      return case when v_n > 0 then 'filled' else 'already' end;
    end if;
    -- Layer 4 on first admission: at most enrich.course_description_pending_max of the provider's wait at once; the rest keep their reading
    -- the provider's places: pending_max less the waiting descriptions the machine has not already declined for good (those wait for a person and take no place a reading could use)
    if security.cdesc_provider_slots_v1(v_pid) <= 0 then
      update pipeline.field_enrich_items set state = 'skipped', reason = 'held_first_admission: the provider''s first descriptions wait in Layer 4; admitted once they are approved',
             value = p_r->'value' || jsonb_build_object('text', v_text, 'check', v_chk, 'reader', jsonb_build_object('model', p_r->>'model', 'prompt', p_r->>'prompt_version', 'worker', p_r->>'worker')), quote = left(coalesce(p_r->>'quote', i.quote), 300), updated_at = now() where id = i.id;
      return 'held_first_admission';
    end if;
    insert into pipeline.layer4_review_items(entity_type, entity_id, field_code, evidence_id, before_value, proposed_value, layer2_state, layer3_state, status, escalation_reason, change_control_ref)
    values ('course', i.course_id, 'course_description_first_read', g.evidence_id, jsonb_build_object('description', null),
            jsonb_build_object('description', v_text, 'item_id', i.id, 'source_url', g.url, 'checks', v_chk->'checks',
                               'sentences', (select jsonb_agg(jsonb_build_object('text', s->>'text', 'quote', s->>'quote') order by o) from jsonb_array_elements(p_r->'value'->'sentences') with ordinality e(s, o))),
            jsonb_build_object('source', 'course description reader', 'page', g.url, 'identity_basis', g.identity_basis),
            jsonb_build_object('item_id', i.id, 'model', p_r->>'model', 'prompt', p_r->>'prompt_version', 'worker', p_r->>'worker'),
            'pending', 'Course description read from the course''s own page. This is one of the provider''s first course descriptions, so a person approves it as read or rejects it.',
            'CF-CHG-20260915-247')
    returning id into v_review;
    update pipeline.field_enrich_items set state = 'review', reason = null, value = p_r->'value' || jsonb_build_object('text', v_text, 'check', v_chk, 'review_item_id', v_review),
           quote = left(coalesce(p_r->>'quote', i.quote), 300), updated_at = now() where id = i.id;
    return 'review';
  end if;

  -- deadline: explicit dates only, tied to an intake the page names (or the course's only active intake)
  if not exists (select 1 from catalogue.course_intakes x where x.course_id = i.course_id and x.status = 'active') then
    update pipeline.field_enrich_items set state = 'skipped', reason = 'no active intake to hold a deadline', value = p_r->'value', updated_at = now() where id = i.id; return 'not_admitted';
  end if;
  for x in select * from jsonb_array_elements(coalesce(p_r->'value'->'deadlines', '[]'::jsonb)) loop
    v_why := null; v_targets := '{}'; v_date := null;
    if x->>'kind' <> 'date' then v_why := coalesce(x->>'kind', 'not_stated');
    elsif not coalesce((x->>'on_page')::boolean, false) then v_why := 'quote_not_on_page';
    elsif coalesce(x->>'date', '') !~ '^\d{4}-\d{2}-\d{2}$' then v_why := 'no_full_date';
    else
      begin v_date := (x->>'date')::date; exception when others then v_date := null; end;
      if v_date is null then v_why := 'no_full_date';
      elsif not security.course_deadline_in_quote_v1(v_date, x->>'quote') then v_why := 'date_not_in_quote';
      end if;
    end if;
    if v_why is null then
      if nullif(btrim(x->>'intake'), '') is null then
        select array_agg(ci.id) into v_targets from catalogue.course_intakes ci where ci.course_id = i.course_id and ci.status = 'active';
        if cardinality(v_targets) <> 1 then v_why := 'not_tied_to_one_intake'; v_targets := '{}'; end if;
      else
        select coalesce(array_agg(ci.id), '{}') into v_targets from catalogue.course_intakes ci
         where ci.course_id = i.course_id and ci.status = 'active' and security.course_deadline_intake_match_v1(ci.intake_label, ci.intake_year, x->>'intake');
        if cardinality(v_targets) = 0 then v_why := 'intake_not_matched'; end if;
      end if;
    end if;
    v_dl := v_dl || (x || jsonb_build_object('outcome', coalesce(v_why, 'kept'), 'intake_ids', to_jsonb(v_targets)));
    if v_why is null then
      foreach v_one in array v_targets loop v_kept := v_kept || jsonb_build_object('intake_id', v_one, 'date', v_date, 'quote', x->>'quote'); end loop;
    end if;
  end loop;
  -- per intake: one date only (two different dates for one intake are held), within the intake's window, never over a deadline held
  for it in select ci.id, ci.start_date, ci.intake_year, ci.application_deadline, array_agg(distinct (k->>'date')::date) dates, min(k->>'quote') quote
              from jsonb_array_elements(v_kept) k join catalogue.course_intakes ci on ci.id = (k->>'intake_id')::uuid group by 1, 2, 3, 4 loop
    if cardinality(it.dates) > 1 then v_dl := v_dl || jsonb_build_object('intake_ids', jsonb_build_array(it.id), 'outcome', 'conflicting_dates'); continue; end if;
    v_date := it.dates[1];
    if it.application_deadline is not null then continue; end if;
    if (it.start_date is not null and (v_date > it.start_date or v_date < it.start_date - v_max_before))
       or (it.start_date is null and it.intake_year is not null and (v_date < make_date(it.intake_year - 1, 1, 1) or v_date > make_date(it.intake_year, 12, 31))) then
      v_dl := v_dl || jsonb_build_object('intake_ids', jsonb_build_array(it.id), 'outcome', 'outside_intake_window', 'date', v_date); continue;
    end if;
    update catalogue.course_intakes set application_deadline = v_date where id = it.id and application_deadline is null;
    if found then v_n := v_n + 1; end if;
  end loop;
  v_kinds := array(select distinct d->>'outcome' from jsonb_array_elements(v_dl) d);
  update pipeline.field_enrich_items set state = case when v_n > 0 then 'filled' else 'skipped' end,
         value = jsonb_build_object('deadlines', v_dl, 'applied', v_n),
         quote = left(coalesce((select k->>'quote' from jsonb_array_elements(v_kept) k limit 1), p_r->>'quote', i.quote), 300),
         reason = case when v_n > 0 then null
                       when cardinality(v_kinds) = 0 or v_kinds <@ array['not_stated'] then coalesce(nullif(p_r->>'reason', ''), 'the page does not state it')
                       when v_kinds <@ array['rolling', 'not_stated'] then 'the page says applications are rolling (no date to hold)'
                       when 'kept' = any (v_kinds) then 'already filled or outside the intake''s dates'
                       else left('held: ' || array_to_string(v_kinds, ', '), 300) end,
         updated_at = now()
   where id = i.id;
  if v_n > 0 then
    insert into search.refresh_requests(requested_by) select 'AI reader (course description, deadline)'
     where not exists (select 1 from search.refresh_requests q where q.processed_at is null and q.requested_by = 'AI reader (course description, deadline)');
  end if;
  return case when v_n > 0 then 'filled' else 'not_admitted' end;
end $_$;


ALTER FUNCTION "security"."enrich_course_text_record_v1"("p_item" bigint, "p_r" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."enrich_course_text_record_v1"("p_item" bigint, "p_r" "jsonb") IS 'CF-247 Workstream C (3 Nov 2026): admits an Enrich fields reading of a course description (checks, then Layer 4 for a provider''s first descriptions) or of application deadlines (explicit dates in the quote, tied to an intake, within its dates). Only into catalogue.courses.description and catalogue.course_intakes.application_deadline when empty; never over a lock.';



CREATE OR REPLACE FUNCTION "security"."enrich_coverage_snapshot_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_at timestamptz := date_trunc('minute', now()); v int;
begin
  insert into pipeline.enrich_coverage_snapshots(at, country_code, field, courses, filled)
  select v_at, s.cc, f.field, count(*),
         count(*) filter (where case f.field when 'campus' then s.has_campus when 'duration' then s.duration_value is not null when 'level' then s.study_level_id is not null
                                           when 'delivery' then nullif(btrim(s.delivery_mode), '') is not null when 'field_of_study' then s.primary_field_id is not null
                                           when 'international' then s.open_to_international is not null
                                           when 'english' then s.has_english when 'intakes' then s.has_intakes
                                           when 'description' then s.has_description when 'deadline' then s.has_deadline else false end)
    from (select k.iso_alpha2::text cc, c.duration_value, c.study_level_id, c.delivery_mode, c.primary_field_id, c.open_to_international,
                 exists (select 1 from catalogue.course_campuses x where x.course_id = c.id) has_campus,
                 exists (select 1 from catalogue.course_english_requirements x where x.course_id = c.id and coalesce(x.status, 'active') = 'active') has_english,
                 exists (select 1 from catalogue.course_intakes x where x.course_id = c.id and x.status = 'active') has_intakes,
                 nullif(btrim(c.description), '') is not null has_description,
                 exists (select 1 from catalogue.course_intakes x where x.course_id = c.id and x.status = 'active' and x.application_deadline is not null) has_deadline
            from catalogue.courses c join catalogue.providers p on p.id = c.provider_id join ref.countries k on k.id = p.country_id
           where c.lifecycle_status = 'active') s
   cross join (select e.field from security.enrich_fields_v1() e where e.level = 'course') f
   group by s.cc, f.field
  on conflict do nothing;
  get diagnostics v = row_count;
  insert into pipeline.enrich_coverage_snapshots(at, country_code, field, courses, filled)
  select v_at, k.iso_alpha2::text, 'provider_address', count(*), count(*) filter (where nullif(btrim(p.address_line1), '') is not null)
    from catalogue.providers p join ref.countries k on k.id = p.country_id
   where coalesce(p.lifecycle_status, 'active') = 'active' and exists (select 1 from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active')
   group by k.iso_alpha2
  on conflict do nothing;
  return v;
end $$;


ALTER FUNCTION "security"."enrich_coverage_snapshot_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_deadline_missing_v1"("p_course" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from catalogue.course_intakes x where x.course_id = p_course and x.status = 'active')
     and not exists (select 1 from catalogue.course_intakes x where x.course_id = p_course and x.status = 'active' and x.application_deadline is not null)
$$;


ALTER FUNCTION "security"."enrich_deadline_missing_v1"("p_course" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."enrich_deadline_missing_v1"("p_course" "uuid") IS 'CF-247 Workstream C (3 Nov 2026): a course''s application deadline is missing when it has active intakes and none has a deadline (the coverage rule).';



CREATE OR REPLACE FUNCTION "security"."enrich_entry_record_v1"("p_item" bigint, "p_r" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare i pipeline.field_enrich_items%rowtype; g record; x jsonb; v_in int := 0; v_drop jsonb := coalesce(p_r->'value'->'dropped', '[]'::jsonb);
        v_notes jsonb := '[]'::jsonb; v_max int; v_conf numeric := security.pipeline_num_v1('entry.min_confidence', 0.8); v_kind text; v_q text; v_d text;
        v_score numeric; v_basis text; v_band text; v_aud text; v_c numeric; v_review uuid; v_ids uuid[] := '{}'; v_id uuid; v_other text;
        v_keep jsonb := '[]'::jsonb; v_n int; v_joined int; v_sup pipeline.aer_read_supersessions%rowtype; v_old pipeline.layer4_review_items%rowtype; v_chk jsonb;
begin
  select * into i from pipeline.field_enrich_items where id = p_item for update;
  if i.id is null or i.course_id is null then return 'nothing'; end if;
  -- D-R2: a corrected read asked for a waiting item (security.course_entry_correction_v1)
  select * into v_sup from pipeline.aer_read_supersessions s where s.enrich_item_id = i.id and s.state = 'requested' for update;
  select pg.provider_id, pg.identity_basis, pg.url, pg.evidence_id, e.captured_at, security.coverage_country(pg.provider_id) cc into g
    from pipeline.coverage_course_pages pg left join pipeline.evidence_artifacts e on e.id = pg.evidence_id where pg.course_id = i.course_id;
  if g.provider_id is null or not (security.coverage_identity_allowed(g.provider_id, g.identity_basis, 'entry_requirements') or coalesce((security.aer_title_identity_ok_v1(i.course_id)->>'ok')::boolean, false)) then -- 20261111040000: own-site title and level match
    update pipeline.field_enrich_items set state = 'skipped', reason = 'the page''s proof (' || coalesce(g.identity_basis, 'none') || ') does not admit entry requirements for this country', updated_at = now() where id = i.id;
    if v_sup.id is not null then perform security.aer_read_supersession_close_v1(v_sup.id, 'refused', 'the page''s proof does not admit entry requirements', null, null); end if;
    return 'not_admitted';
  end if;
  if jsonb_array_length(coalesce(p_r->'value'->'rows', '[]'::jsonb)) = 0 then
    update pipeline.field_enrich_items set state = 'skipped', reason = coalesce(nullif(p_r->>'reason', ''), 'the page does not state it'), value = jsonb_build_object('dropped', v_drop, 'coverage', p_r->'value'->'coverage'), updated_at = now() where id = i.id;
    if v_sup.id is not null then perform security.aer_read_supersession_close_v1(v_sup.id, 'refused', 'the corrected read states no requirement', null, null); end if;
    return 'not_stated';
  end if;
  -- an earlier read of this course still waits for a person: nothing is proposed twice
  -- D-R2: only the read asked to correct it may pass the waiting read (and only when complete, checked below before any row is written)
  if exists (select 1 from pipeline.layer4_review_items r where r.entity_type = 'course' and r.entity_id = i.course_id and r.field_code = 'course_entry_first_read' and r.status = 'pending'
               and (v_sup.id is null or r.id <> v_sup.old_item_id)) then
    update pipeline.field_enrich_items set state = 'skipped', reason = 'an earlier read of this course waits in Layer 4', updated_at = now() where id = i.id;
    if v_sup.id is not null then perform security.aer_read_supersession_close_v1(v_sup.id, 'refused', 'another read of this course waits in Layer 4', null, null); end if;
    return 'already';
  end if;
  -- E13: the course's row limit (entry.max_rows_per_course, or the provider's own value in entry.max_rows_by_provider)
  v_max := security.course_entry_max_rows_v1(g.provider_id);
  for x in select * from jsonb_array_elements(p_r->'value'->'rows') loop
    v_kind := x->>'kind'; v_q := left(btrim(coalesce(x->>'quote', '')), 300); v_d := left(btrim(coalesce(x->>'description', '')), 500);
    v_c := case when x->>'confidence' ~ '^[0-9.]+$' then (x->>'confidence')::numeric end;
    v_score := case when x->>'min_entry_score' ~ '^[0-9]+(\.[0-9]+)?$' then (x->>'min_entry_score')::numeric end;
    v_basis := nullif(btrim(coalesce(x->>'min_entry_score_basis', '')), '');
    v_band := nullif(btrim(coalesce(x->>'benchmark_band', '')), '');
    if v_kind is null or v_kind not in ('prior_qualification', 'minimum_grade', 'subject_prerequisite', 'portfolio_interview', 'work_experience', 'override', 'general_note') then
      v_drop := v_drop || jsonb_build_object('reason', 'kind_unknown', 'kind', v_kind, 'quote', v_q); continue;
    end if;
    if length(v_q) < 4 then v_drop := v_drop || jsonb_build_object('reason', 'no_quote', 'kind', v_kind); continue; end if;
    if coalesce(v_c, 0) < v_conf then v_drop := v_drop || jsonb_build_object('reason', 'low_confidence', 'kind', v_kind, 'quote', v_q); continue; end if;
    -- the English requirement is its own field: a row about an English test or English proficiency is never stored here (B1 rule)
    if (v_q || ' ' || v_d) ~* '(\mielts\M|\mtoefl\M|\mpte\M|\mduolingo\M|cambridge english|\moet\M|english language (requirement|proficiency|test)|english proficiency)' then
      v_drop := v_drop || jsonb_build_object('reason', 'english_duplicate', 'kind', v_kind, 'quote', v_q); continue;
    end if;
    -- no numeric score without its basis: both the number and the basis words are printed in the quote (B1 rule)
    if v_score is not null and (v_basis is null or strpos(lower(regexp_replace(v_q, '\s+', ' ', 'g')), lower(regexp_replace(v_basis, '\s+', ' ', 'g'))) = 0
                                or not exists (select 1 from regexp_matches(v_q, '([0-9]+(\.[0-9]+)?)', 'g') m where m[1]::numeric = v_score)) then
      -- 7 Nov 2026 (AER technical holds): the requirement is printed and verified, only its number has no printed basis: keep the requirement, store no number
      v_notes := v_notes || jsonb_build_object('note', 'score_without_basis', 'score', v_score, 'basis', v_basis, 'quote', v_q);
      v_score := null; v_basis := null;
    end if;
    if v_score is null then v_basis := null; end if;
    -- a band only when the quote prints it exactly; never derived (Platform Admin 28 Oct 2026: no ATAR-to-band mapping)
    if v_band is not null and strpos(lower(v_q), lower(v_band)) = 0 then
      v_notes := v_notes || jsonb_build_object('note', 'band_not_printed', 'band', v_band, 'quote', v_q); v_band := null;
    end if;
    -- audience from the quote's own words; international applicability is never inferred
    v_aud := case when v_q ~* '\m(international|overseas)\M' then 'international'
                  when v_q ~* '(\mVCE\M|\mATAR\M|\mVTAC\M|\mSTAT\M|Australian Year 12)' then 'domestic'
                  -- CF-247 AER NZ (Platform Admin mandate 29 Oct 2026 12:23 B4): NZ school-leaver routes, never inferred to apply internationally
                  when g.cc = 'NZ' and v_q ~* '(\mNCEA\M|University Entrance|\mUE\M)' then 'domestic' else 'all' end;
    -- E13: a row about another programme (a sibling variant on a combined page) is not this course's and does not count towards the limit
    v_other := security.course_entry_variant_v1(i.course_id, v_q);
    if v_other is not null then v_drop := v_drop || jsonb_build_object('reason', 'other_programme', 'kind', v_kind, 'quote', v_q, 'names', v_other); continue; end if;
    -- 7 Nov 2026 (AER technical holds): the same requirement printed twice is one row (it counts once towards the row limit)
    if exists (select 1 from jsonb_array_elements(v_keep) k where k->>'kind' = v_kind
                 and lower(regexp_replace(coalesce(k->>'quote', ''), '[^[:alnum:]]', '', 'g')) = lower(regexp_replace(v_q, '[^[:alnum:]]', '', 'g'))) then continue; end if;
    v_keep := v_keep || jsonb_build_object('kind', v_kind, 'audience', v_aud, 'description', coalesce(nullif(v_d, ''), v_q), 'min_grade', nullif(btrim(coalesce(x->>'min_grade', '')), ''),
                                           'min_entry_score', v_score, 'min_entry_score_basis', v_basis, 'benchmark_band', v_band, 'quote', v_q, 'confidence', v_c);
  end loop;
  v_n := jsonb_array_length(v_keep);
  -- E13 (Platform Admin 2 Nov 2026 05:18): a read with more rows than its limit is held whole, never proposed in part (the rule the reader
  -- already applies to cut answers and unread slices). Every row read is kept on the item; the rows past the limit are recorded as dropped.
  if v_n > v_max then
    select count(*) filter (where security.course_entry_joined_v1(k->>'quote', k->>'kind')) into v_joined from jsonb_array_elements(v_keep) with ordinality t(k, o) where o > v_max;
    select v_drop || coalesce(jsonb_agg(jsonb_build_object('reason', 'over_row_limit', 'kind', k->>'kind', 'quote', k->>'quote') order by o), '[]'::jsonb) into v_drop
      from jsonb_array_elements(v_keep) with ordinality t(k, o) where o > v_max;
    update pipeline.field_enrich_items set state = 'skipped',
           reason = left(format('held_partial: over_row_limit: the page has %s requirements and the limit is %s%s; nothing proposed (E13)', v_n, v_max,
                                case when v_joined > 0 then format(', %s of those past the limit joined to an earlier requirement', v_joined) else '' end), 300),
           value = jsonb_build_object('held', 'over_row_limit', 'limit', v_max, 'rows_read', v_keep, 'dropped', v_drop, 'notes', v_notes, 'coverage', p_r->'value'->'coverage'),
           updated_at = now() where id = i.id;
    if v_sup.id is not null then perform security.aer_read_supersession_close_v1(v_sup.id, 'refused', 'the corrected read was cut at the row limit (E13)', null, null); end if;
    return 'held_partial';
  end if;
  -- D-R2 (Platform Admin 2 Nov 2026 23:24): the corrected read replaces the waiting one only when it is complete and the waiting one is still
  -- undecided, unclaimed and unlocked; then, in this transaction, the waiting item becomes 'superseded' (its rows are quarantined by the trigger)
  if v_sup.id is not null then
    select * into v_old from pipeline.layer4_review_items where id = v_sup.old_item_id for update;
    v_chk := security.course_entry_correction_check_v1(v_sup.old_item_id, i.course_id, g.url, v_keep, v_drop);
    if not coalesce((v_chk->>'ok')::boolean, false) then
      update pipeline.field_enrich_items set state = 'skipped', reason = left('corrected read refused (D-R2): ' || (v_chk->>'why'), 300),
             value = jsonb_build_object('rows_read', v_keep, 'dropped', v_drop, 'notes', v_notes, 'coverage', p_r->'value'->'coverage', 'supersession', v_sup.id), updated_at = now()
       where id = i.id;
      perform security.aer_read_supersession_close_v1(v_sup.id, 'refused', v_chk->>'why', null, v_chk->'diff');
      return 'not_admitted';
    end if;
    update pipeline.layer4_review_items set status = 'superseded', decided_at = now() where id = v_old.id and status = 'pending';
  end if;
  for x in select * from jsonb_array_elements(v_keep) loop
    insert into catalogue.course_entry_requirements(course_id, kind, audience, description, min_grade, min_entry_score, min_entry_score_basis, benchmark_band,
                                                    quote, source_url, evidence_id, confidence, as_at, status, provenance)
    values (i.course_id, x->>'kind', x->>'audience', x->>'description', x->>'min_grade', (x->>'min_entry_score')::numeric, x->>'min_entry_score_basis', x->>'benchmark_band',
            x->>'quote', g.url, coalesce(i.evidence_id, g.evidence_id), (x->>'confidence')::numeric, coalesce(g.captured_at::date, current_date), 'proposed',
            jsonb_build_object('reader', 'enrich_ai', 'field', 'entry_requirements', 'item_id', i.id, 'job_id', i.job_id, 'model', p_r->>'model',
                               'worker', p_r->>'worker', 'prompt', p_r->>'prompt_version'))
    returning id into v_id;
    v_ids := v_ids || v_id; v_in := v_in + 1;
  end loop;
  if v_in = 0 then
    update pipeline.field_enrich_items set state = 'skipped', reason = 'no row met the admission rules', value = jsonb_build_object('dropped', v_drop, 'notes', v_notes, 'coverage', p_r->'value'->'coverage'), updated_at = now() where id = i.id;
    if v_sup.id is not null then perform security.aer_read_supersession_close_v1(v_sup.id, 'refused', 'no row of the corrected read met the admission rules', null, null); end if;
    return 'not_admitted';
  end if;
  insert into pipeline.layer4_review_items(entity_type, entity_id, field_code, evidence_id, before_value, proposed_value, layer2_state, layer3_state,
                                           status, escalation_reason, change_control_ref)
  values ('course', i.course_id, 'course_entry_first_read', coalesce(i.evidence_id, g.evidence_id),
          jsonb_build_object('active_rows', (select count(*) from catalogue.course_entry_requirements r where r.course_id = i.course_id and r.status = 'active')),
          jsonb_build_object('item_id', i.id, 'url', g.url, 'rows', v_in, 'limit', v_max, 'dropped', v_drop, 'notes', v_notes,
            'sample', (select jsonb_agg(jsonb_build_object('id', r.id, 'kind', r.kind, 'audience', r.audience, 'description', r.description, 'min_entry_score', r.min_entry_score,
                                         'min_entry_score_basis', r.min_entry_score_basis, 'benchmark_band', r.benchmark_band, 'quote', r.quote) order by r.kind)
                         from catalogue.course_entry_requirements r where r.id = any (v_ids))),
          jsonb_build_object('source', 'course entry reader', 'page', g.url, 'identity_basis', g.identity_basis),
          jsonb_build_object('item_id', i.id, 'model', p_r->>'model'),
          'pending', 'Course entry requirements first read: a person admits the rows before any is active (Track C Step B)', 'CF-CHG-20260915-247')
  returning id into v_review;
  if v_sup.id is not null then
    -- D-R2: the new item carries the reviewer's diff and names the read it replaced; nothing is approved
    update pipeline.layer4_review_items set proposed_value = proposed_value || jsonb_build_object('supersedes', coalesce(v_chk->'diff', '{}'::jsonb)
             || jsonb_build_object('review_item_id', v_sup.old_item_id, 'request_id', v_sup.id, 'reason', v_sup.reason, 'requested_by', v_sup.requested_by,
                                   'new_evidence_id', coalesce(i.evidence_id, g.evidence_id)))
     where id = v_review;
    perform security.aer_read_supersession_close_v1(v_sup.id, 'superseded', null, v_review, v_chk->'diff');
  end if;
  update catalogue.course_entry_requirements set provenance = provenance || jsonb_build_object('review_item_id', v_review) where id = any (v_ids);
  update pipeline.field_enrich_items set state = 'review', reason = null, quote = left((select r.quote from catalogue.course_entry_requirements r where r.id = v_ids[1]), 300),
         value = jsonb_build_object('rows', v_in, 'limit', v_max, 'review_item_id', v_review, 'dropped', v_drop, 'notes', v_notes, 'coverage', p_r->'value'->'coverage'), updated_at = now() where id = i.id;
  return 'review';
end $_$;


ALTER FUNCTION "security"."enrich_entry_record_v1"("p_item" bigint, "p_r" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."enrich_entry_record_v1"("p_item" bigint, "p_r" "jsonb") IS 'CF-247 Track C Step B (B1): admits a course page''s entry-requirement rows as proposed under the B1 rules (quote, basis, band printed, no English duplicate, audience from the quote; NZ NCEA/University Entrance routes are domestic, 29 Oct 2026 B4) and opens Layer 4 course_entry_first_read.';



CREATE OR REPLACE FUNCTION "security"."enrich_fallback_v1"("p_item" bigint) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.field_enrich_items%rowtype; v jsonb; q text; c record;
begin
  select * into i from pipeline.field_enrich_items where id = p_item;
  if i.id is null or i.course_id is null then return false; end if;
  if i.field = 'campus' then
    select k.id, k.name into c from catalogue.campuses k
     where k.provider_id = i.provider_id and coalesce(k.status, 'active') = 'active'
       and (select count(*) from catalogue.campuses k2 where k2.provider_id = i.provider_id and coalesce(k2.status, 'active') = 'active') = 1;
    if c.id is not null then
      v := jsonb_build_object('campuses', jsonb_build_array(jsonb_build_object('campus_id', c.id, 'name', c.name)));
      q := 'The provider has one campus: ' || c.name;
    end if;
  elsif i.field = 'international' then
    if exists (select 1 from catalogue.course_fees f where f.course_id = i.course_id and f.audience = 'international' and coalesce(f.status, 'active') = 'active') then
      v := jsonb_build_object('open', true); q := 'An international fee is on record for this course';
    elsif exists (select 1 from catalogue.course_registrations r where r.course_id = i.course_id and lower(r.scheme) = 'cricos' and coalesce(r.status, 'active') = 'active') then
      v := jsonb_build_object('open', true); q := 'Registered on CRICOS (courses for overseas students)';
    elsif exists (select 1 from catalogue.providers p where p.id = i.provider_id and p.enrols_international = false) then
      v := jsonb_build_object('open', false); q := 'The provider does not enrol international students';
    end if;
  end if;
  if v is null then return false; end if;
  update pipeline.field_enrich_items set value = v, quote = left(q, 300), source = 'provider_facts', reason = 'provider-level fact (the course page did not state it)', updated_at = now()
   where id = i.id;
  perform security.enrich_apply_v1(i.id);
  return true;
end $$;


ALTER FUNCTION "security"."enrich_fallback_v1"("p_item" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."enrich_fallback_v1"("p_item" bigint) IS 'CF-247 22 Oct 2026: fills campus (the provider''s only campus) or international (international fee or CRICOS registration; provider not enrolling) when the course page is silent; source provider_facts.';



CREATE OR REPLACE FUNCTION "security"."enrich_fields_estimate_v1"("p_cc" "text"[], "p_pids" "uuid"[], "p_fields" "text"[], "p_ai" boolean, "p_scraper" boolean) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with scope as (
    select c.id, c.provider_id, c.duration_value, c.study_level_id, c.delivery_mode, c.primary_field_id, c.open_to_international
      from catalogue.courses c join catalogue.providers p on p.id = c.provider_id join ref.countries k on k.id = p.country_id
     where c.lifecycle_status = 'active' and (cardinality(p_cc) = 0 or k.iso_alpha2::text = any (p_cc)) and (cardinality(p_pids) = 0 or c.provider_id = any (p_pids))),
  miss as (
    select s.id, s.provider_id, f.x field, exists (select 1 from security.provider_hidden_v1 h where h.provider_id = s.provider_id) hidden
      from scope s cross join unnest(p_fields) f(x)
     where f.x not in ('provider_address', 'campus_region', 'campus_list')
       and case f.x when 'campus' then not exists (select 1 from catalogue.course_campuses x where x.course_id = s.id)
                    when 'duration' then s.duration_value is null when 'level' then s.study_level_id is null
                    when 'delivery' then nullif(btrim(s.delivery_mode), '') is null when 'field_of_study' then s.primary_field_id is null
                    when 'international' then s.open_to_international is null
                    when 'english' then not exists (select 1 from catalogue.course_english_requirements x where x.course_id = s.id and coalesce(x.status, 'active') = 'active')
                    when 'intakes' then not exists (select 1 from catalogue.course_intakes x where x.course_id = s.id and x.status = 'active') else false end),
  m as (select m0.*, (not m0.hidden and security.enrich_item_in_flight_v1(m0.provider_id, m0.id, m0.field)) in_task from miss m0),
  u as (select coalesce((security.enrich_unit_costs_v1()->>'enrich_usd_per_item')::numeric, 0) usd)
  select jsonb_build_object('estimate', jsonb_build_object(
    'items', (select count(*) from m where not hidden and not in_task),
    'in_task', (select count(*) from m where in_task),
    'unpublished', (select count(*) from m where hidden),
    'usd_per_item', u.usd,
    'usd', case when p_ai then round((select count(*) from m where not hidden and not in_task) * u.usd, 4) else 0 end,
    'credits_max', case when p_scraper then (select count(distinct m2.id) from m m2 where not m2.hidden and not m2.in_task
                                               and not exists (select 1 from pipeline.coverage_course_pages g where g.course_id = m2.id and g.evidence_id is not null)) else 0 end))
    from u
$$;


ALTER FUNCTION "security"."enrich_fields_estimate_v1"("p_cc" "text"[], "p_pids" "uuid"[], "p_fields" "text"[], "p_ai" boolean, "p_scraper" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."enrich_fields_estimate_v1"("p_cc" "text"[], "p_pids" "uuid"[], "p_fields" "text"[], "p_ai" boolean, "p_scraper" boolean) IS 'CF-247 3 Nov 2026 (Platform Admin 09:32 §3 "Estimate new Firecrawl/AI expenditure"): what Enrich fields Start would queue for a scope (course fields), the items another open task holds, the items of unpublished providers, the AI estimate (items x the average AI cost of an item in the last 30 days, security.enrich_unit_costs_v1) and the most scraper credits (one read for each course without a stored page, only when new reads are allowed).';



CREATE OR REPLACE FUNCTION "security"."enrich_fields_slice_v1"("p_id" "uuid", "p_items" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare j pipeline.admin_jobs%rowtype; it record; v_src text; v_srcs text[]; v_ai boolean; v_scr boolean; v_x jsonb; v_txt text; v_val jsonb;
        v_done int := 0; v_batch int := greatest(coalesce(p_items, 0), 1) * security.pipeline_num_v1('batch.enrich_fields', 400)::int / 10;
        v_cc text; v_path text; v_ev uuid; v_settled boolean; v_left int;
begin
  select * into j from pipeline.admin_jobs where id = p_id for no key update;  -- CF-247 IQ-00053: the enrich_ai record checks its task row (FOR KEY SHARE) while this runs
  v_ai := coalesce((j.args->>'ai')::boolean, true); v_scr := coalesce((j.args->>'scraper')::boolean, false);
  -- v2.15.275 hotfix: an item that has used its AI tries and is no longer being worked on is settled as failed, so the task can finish
  update pipeline.field_enrich_items e set state = 'failed', leased_until = null, updated_at = now(),
         reason = coalesce(e.reason, 'no answer could be recorded after ' || e.attempts || ' tries')
   where e.job_id = p_id and e.attempts >= 3 and (e.state = 'ai' or (e.state = 'leased' and e.leased_until < now()));
  -- items waiting for a requested page: move on when the page arrived, skip when the wait is over
  update pipeline.field_enrich_items e set state = 'queued', updated_at = now()
   where e.job_id = p_id and e.state = 'waiting' and e.field <> 'campus'
     and exists (select 1 from pipeline.coverage_course_pages g where g.course_id = e.course_id and g.evidence_id is not null and g.read_at >= e.updated_at);
  update pipeline.field_enrich_items e set state = 'skipped', reason = 'the requested page read did not arrive in time', updated_at = now()
   where e.job_id = p_id and e.state = 'waiting' and e.field <> 'campus'
     and e.updated_at < now() - make_interval(hours => security.pipeline_num_v1('enrich.wait_page_hours', 6)::int);
  for it in select e.*, k.iso_alpha2::text cc from pipeline.field_enrich_items e join catalogue.providers p on p.id = e.provider_id join ref.countries k on k.id = p.country_id
             where e.job_id = p_id and e.state = 'queued' order by e.id limit v_batch for update of e skip locked loop
    v_settled := false; v_srcs := security.field_sources_for_v1(it.cc, case when it.field = 'campus_list' then 'campus' else it.field end);
    foreach v_src in array v_srcs loop
      continue when v_src = any (it.tried);
      continue when v_src in ('ai_stored', 'ai_title') and not v_ai;
      continue when v_src = 'scraper' and not v_scr;
      -- CF-247 21 Oct 2026: the standing Fill the gaps task asks for new page reads only within its daily limit
      continue when v_src = 'scraper' and coalesce((j.args->>'standing')::boolean, false) and not security.gap_scraper_room_v1();
      update pipeline.field_enrich_items set tried = tried || v_src where id = it.id;
      if v_src = 'adapter' and it.course_id is not null then
        -- 18 Oct 2026 (Decision 267 follow-up 3): the current page reading first, the Apply history for what it lacks
        select coalesce((select r.fields->'extra' from pipeline.uni_adapter_results r where r.course_id = it.course_id order by r.at desc limit 1), '{}'::jsonb)
               || coalesce((select g.candidates->'adapter_extra' from pipeline.coverage_course_pages g
                             where g.course_id = it.course_id and g.read_status = 'read' and g.identity_basis is not null), '{}'::jsonb)
          into v_x;
        v_txt := nullif(btrim(case it.field when 'campus' then coalesce(v_x->>'campus', v_x->>'location') when 'duration' then v_x->>'duration'
                                            when 'level' then v_x->>'study_level' when 'delivery' then v_x->>'mode' when 'international' then v_x->>'student_type' end), '');
        if v_txt is null then continue; end if;
        v_ev := (select g.evidence_id from pipeline.coverage_course_pages g where g.course_id = it.course_id);
        v_val := case it.field when 'duration' then security.enrich_parse_duration_v1(v_txt)
                               when 'level' then (select jsonb_build_object('level_id', l) from (select security.enrich_parse_level_v1(v_txt) l) z where l is not null)
                               when 'delivery' then (select jsonb_build_object('mode', m) from (select security.delivery_mode_read_v1(left(v_txt, 300), it.provider_id) m) z where m is not null)
                               when 'international' then case when v_txt ~* 'international' then jsonb_build_object('open', true) end
                               else null end;
        if it.field = 'campus' then
          -- the campus text waits for the university's campus list
          update pipeline.field_enrich_items set state = 'waiting', source = 'adapter', quote = left(v_txt, 300), evidence_id = v_ev, updated_at = now() where id = it.id;
          v_settled := true; exit;
        end if;
        if v_val is null then continue; end if;
        update pipeline.field_enrich_items set source = 'adapter', value = v_val, quote = left(v_txt, 300), evidence_id = v_ev, updated_at = now() where id = it.id;
        perform security.enrich_apply_v1(it.id); v_settled := true; exit;
      elsif v_src = 'institution_rule' and it.field = 'international' then
        if it.cc = 'CA' and exists (select 1 from catalogue.provider_identifiers i where i.provider_id = it.provider_id and i.scheme = 'ircc_dli') then
          update pipeline.field_enrich_items set source = 'institution_rule', value = jsonb_build_object('open', true),
                 quote = 'Listed by IRCC as a designated learning institution (DLI ' || (select i.identifier from catalogue.provider_identifiers i where i.provider_id = it.provider_id and i.scheme = 'ircc_dli' limit 1) || ')', updated_at = now()
           where id = it.id;
          perform security.enrich_apply_v1(it.id); v_settled := true; exit;
        end if;
      elsif v_src = 'ai_stored' then
        if it.field = 'provider_address' then
          select e.storage_path, e.id into v_path, v_ev from pipeline.evidence_artifacts e join pipeline.sources s on s.id = e.source_id
           where s.provider_id = it.provider_id and e.evidence_type in ('provider_contact_html_snapshot', 'enrich_home_page') and e.storage_path is not null order by e.created_at desc limit 1;
        elsif it.field = 'campus_list' then
          v_path := null; v_ev := null;  -- the list is made from the campus names, with the contact page when one is stored
          select e.storage_path, e.id into v_path, v_ev from pipeline.evidence_artifacts e join pipeline.sources s on s.id = e.source_id
           where s.provider_id = it.provider_id and e.evidence_type in ('provider_contact_html_snapshot', 'enrich_home_page') and e.storage_path is not null order by e.created_at desc limit 1;
          update pipeline.field_enrich_items set state = 'ai', source = 'ai_stored', storage_path = v_path, evidence_id = v_ev, updated_at = now() where id = it.id;
          v_settled := true; exit;
        else
          -- 23 Oct 2026: only the course's own page: bound, or ambiguous with an identity proof; never a page found to be another course's
          select e.storage_path, e.id into v_path, v_ev from pipeline.coverage_course_pages g join pipeline.evidence_artifacts e on e.id = g.evidence_id
           where g.course_id = it.course_id and g.status in ('bound', 'ambiguous') and (g.status = 'bound' or g.identity_basis is not null)
             -- 2 Nov 2026 (E16-1): only a page that was read with an identity proof and that the course page check does not refuse
             and g.read_status = 'read' and g.identity_basis is not null
             and (security.pipeline_num_v1('binding.identity_check', 1) < 1
                  or security.course_page_check_v1(it.course_id, coalesce(nullif(g.candidates->>'final_url', ''), g.url),
                                                   coalesce(nullif(g.candidates->>'page_title', ''), g.candidates->>'h1'), g.identity_basis)->>'verdict' <> 'refuse');
          if v_path is null then
            update pipeline.field_enrich_items
               set reason = case when exists (select 1 from pipeline.coverage_course_pages g where g.course_id = it.course_id and g.status = 'mismatch')
                                 then 'no correct course page: the page found is for another course'
                                 else 'no proven course page: the page found is not proved to be this course''s (E16)' end
             where id = it.id and exists (select 1 from pipeline.coverage_course_pages g where g.course_id = it.course_id);
          end if;
        end if;
        if v_path is null then continue; end if;
        -- 22 Oct 2026 (NZ review fix 4): the same stored page copy did not state this field before: not asked again
        if it.course_id is not null and v_ev is not null and not coalesce((j.args->>'read_now')::boolean, false) and (security.field_absence_unchanged_v1(it.course_id, it.field, v_ev) or exists (
             select 1 from pipeline.field_enrich_items o where o.course_id = it.course_id and o.field = it.field and o.evidence_id = v_ev and o.id <> it.id
                and o.state = 'skipped' and o.reason in ('the page does not state it', 'the page names no campus', 'only a site-wide line mentions international', 'no campus named on the page'))) then
          -- CF-247 Release B (D2): or a verified negative on a copy with the same content (security.field_absence_unchanged_v1)
          update pipeline.field_enrich_items set reason = 'the same page copy was read for this before and did not state it' where id = it.id;
          continue;
        end if;
        update pipeline.field_enrich_items set state = 'ai', source = 'ai_stored', storage_path = v_path, evidence_id = v_ev, updated_at = now() where id = it.id;
        perform security.enrich_siblings_v1(it.id);  -- CF-247 Release B (§6 priority 2): the course's other missing fields from the same copy
        v_settled := true; exit;
      elsif v_src = 'ai_title' and it.course_id is not null then
        update pipeline.field_enrich_items set state = 'ai', source = 'ai_title', updated_at = now() where id = it.id;
        v_settled := true; exit;
      elsif v_src = 'ai_city' and it.field = 'campus_region' then
        -- 23 Oct 2026: known city regions first; the AI is asked only for cities still without one
        perform security.campus_regions_apply_v1();
        if not exists (select 1 from catalogue.campuses k where k.provider_id = it.provider_id and k.status = 'active' and k.subdivision_id is null and nullif(btrim(k.city), '') is not null) then
          update pipeline.field_enrich_items set state = 'filled', reason = 'every campus city has a region', updated_at = now() where id = it.id;
          v_settled := true; exit;
        end if;
        update pipeline.field_enrich_items set state = 'ai', source = 'ai_city', updated_at = now() where id = it.id;
        v_settled := true; exit;
      elsif v_src = 'scraper' then
        if it.field = 'provider_address' then
          if exists (select 1 from catalogue.providers p where p.id = it.provider_id and p.website ~* '^https?://' and not security.third_party_host_v1(p.website)) then
            update pipeline.field_enrich_items set state = 'ai', source = 'scraper', storage_path = null, updated_at = now() where id = it.id;
            v_settled := true; exit;
          end if;
        elsif it.course_id is not null and exists (select 1 from pipeline.coverage_course_pages g where g.course_id = it.course_id and g.url ~* '^https?://') then
          update pipeline.coverage_course_pages set next_read_at = now() where course_id = it.course_id and coalesce(next_read_at, 'infinity') > now();
          update pipeline.field_enrich_items set state = 'waiting', reason = 'course page asked to be read', updated_at = now() where id = it.id;
          v_settled := true; exit;
        end if;
      end if;
    end loop;
    -- 22 Oct 2026 (fix 4): a provider-level or registered fact before skipping
    if not v_settled and not security.enrich_fallback_v1(it.id) then
      update pipeline.field_enrich_items set state = 'skipped', reason = coalesce(reason, 'no allowed source had a value'), updated_at = now() where id = it.id and state = 'queued';
    end if;
    v_done := v_done + 1;
  end loop;
  -- a university's campus list goes to the AI once its course campus items have all been read
  update pipeline.field_enrich_items l set state = 'queued', updated_at = now()
   where l.job_id = p_id and l.field = 'campus_list' and l.state = 'waiting'
     and not exists (select 1 from pipeline.field_enrich_items c where c.job_id = p_id and c.provider_id = l.provider_id and c.field = 'campus' and c.state in ('queued', 'ai', 'leased'));
  perform security.enrich_campus_link_v1(p_id);
  -- course campus items whose page named no campus: nothing to link
  update pipeline.field_enrich_items c set state = 'skipped', reason = 'no campus named on the page', updated_at = now()
   where c.job_id = p_id and c.field = 'campus' and c.state = 'waiting' and c.quote is null;
  if exists (select 1 from pipeline.field_enrich_items where job_id = p_id and (state = 'ai' or (state = 'leased' and leased_until < now() and attempts < 3))) then perform security.enrich_ai_fire_v1(); end if;  -- CF-247 IQ-00053: an expired lease is fired again
  select count(*) into v_left from pipeline.field_enrich_items where job_id = p_id and state in ('queued', 'waiting', 'ai', 'leased');
  update pipeline.admin_jobs set progress = (select jsonb_build_object('done', count(*) filter (where state in ('filled', 'review', 'skipped', 'failed')), 'total', count(*),
                                                   'worker', security.enrich_worker_health_v1(), 'phase', case when v_left = 0 then 'finishing' when count(*) filter (where state in ('ai', 'leased')) > 0 then 'reading with AI' else 'settling stored values' end)
                                               from pipeline.field_enrich_items where job_id = p_id),
         result = (select jsonb_build_object('by_field', jsonb_object_agg(f, s), 'cost_usd', (select round(coalesce(sum(cost_usd), 0), 4) from pipeline.field_enrich_items where job_id = p_id))
                     from (select field f, jsonb_object_agg(state, n) s from (select field, state, count(*) n from pipeline.field_enrich_items where job_id = p_id group by 1, 2) z group by field) y),
         updated_at = now()
   where id = p_id;
  -- v2.15.276 O1: the values reach the website once the task finishes
  if v_left = 0 then insert into search.refresh_requests(requested_by) values ('enrich fields task ' || left(p_id::text, 8) || ' finished'); end if;
  return v_left = 0;
end $$;


ALTER FUNCTION "security"."enrich_fields_slice_v1"("p_id" "uuid", "p_items" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_fields_v1"() RETURNS TABLE("field" "text", "label" "text", "level" "text", "sources" "text"[], "sort" integer)
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select * from (values
    ('campus', 'Campus (with the campus list)', 'course', array['adapter', 'ai_stored'], 1),
    ('duration', 'Duration', 'course', array['adapter', 'ai_stored'], 2),
    ('level', 'Study level', 'course', array['adapter', 'ai_title'], 3),
    ('delivery', 'Delivery mode', 'course', array['adapter', 'ai_stored'], 4),
    ('field_of_study', 'Field of study', 'course', array['ai_title'], 5),
    ('international', 'Open to international students', 'course', array['institution_rule', 'adapter', 'ai_stored'], 6),
    ('provider_address', 'Provider street address', 'provider', array['ai_stored', 'scraper'], 7),
    -- 23 Oct 2026 (Platform Admin 10:25): English, intakes and campus regions too
    ('english', 'English requirement (IELTS)', 'course', array['ai_stored'], 8),
    ('intakes', 'Intakes (start months)', 'course', array['ai_stored'], 9),
    ('campus_region', 'Campus region (state)', 'provider', array['ai_city'], 10),
    -- 3 Nov 2026 (CF-247 Workstream C, Platform Admin 09:32): course description and application deadline from the course page
    ('description', 'Course description', 'course', array['ai_stored', 'scraper'], 11),
    ('deadline', 'Application deadline', 'course', array['ai_stored', 'scraper'], 12)) v(field, label, level, sources, sort)
$$;


ALTER FUNCTION "security"."enrich_fields_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_focus_refresh_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_top int := security.pipeline_num_v1('enrich.focus_top_n', 50)::int; v_n int;
begin
  insert into pipeline.enrich_focus_providers(provider_id, rank, gaps, in_focus, set_at)
  select g.provider_id, g.rk, g.gaps, g.rk <= v_top, now()
    from (select d.provider_id, (count(*) filter (where not d.has_english) + count(*) filter (where not d.has_intake))::int gaps,
                 row_number() over (partition by d.country_code order by count(*) filter (where not d.has_english) + count(*) filter (where not d.has_intake) desc, d.provider_id)::int rk
            from search.course_documents d
           where d.country_code = any (security.pipeline_list_v1('enrich.focus_countries', '["AU"]')) and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = d.provider_id)
           group by d.provider_id, d.country_code) g  -- CF-247 3 Nov 2026: focus countries from the setting, ranked within each country
  on conflict (provider_id) do update set rank = excluded.rank, gaps = excluded.gaps, in_focus = excluded.in_focus, set_at = now();
  update pipeline.enrich_focus_providers f set in_focus = false, set_at = now()
   where f.in_focus and f.set_at < now();  -- providers not ranked in this refresh
  select count(*) into v_n from pipeline.enrich_focus_providers where in_focus;
  return v_n;
end $$;


ALTER FUNCTION "security"."enrich_focus_refresh_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_focus_v1"("p_provider_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- page search runs for every provider when the setting is 0, for providers outside Australia, and for the Australian focus providers
  -- CF-247 19 Oct 2026: and for a provider in a re-find wave (Layer 2 > Build adapter, wave named "refind-...")
  -- CF-247 20 Oct 2026: never for a provider held because its course pages could not be found (until a person releases it)
  select not security.flag_provider_held_v1(p_provider_id, array['course_pages_not_found'])
     and (security.pipeline_num_v1('enrich.focus_top_n', 50) = 0
      -- CF-247 3 Nov 2026 (direction 09:32 §7): the countries limited to their focus providers are a setting
      or coalesce(security.coverage_country(p_provider_id), '') <> all (security.pipeline_list_v1('enrich.focus_countries', '["AU"]'))
      or exists (select 1 from pipeline.enrich_focus_providers f where f.provider_id = p_provider_id and f.in_focus)
      or exists (select 1 from pipeline.adapter_builds b where b.provider_id = p_provider_id and b.wave like 'refind-%'))
$$;


ALTER FUNCTION "security"."enrich_focus_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_item_held_v1"("p_course" "uuid", "p_field" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- 31 Oct 2026 (StudySearch D5a): a course whose page binding is a mismatch is held until a page is bound again (0 of 11,332 such items filled in 4 days)
  select exists (select 1 from pipeline.coverage_course_pages g where g.course_id = p_course and g.status = 'mismatch' and coalesce(g.basis, '') <> 'manual')
      or exists (select 1 from pipeline.enrichment_flags f
                  where f.entity = 'course' and f.entity_key = p_course::text and f.field in (p_field, '')
                    and ((f.state = 'raised' and f.reason_code in ('enrich_no_value', 'manual_hold'))
                         or (f.state = 'counting' and f.reason_code = 'enrich_no_value'
                             and f.flagged_at > now() - make_interval(days => security.pipeline_num_v1('gaps.recheck_days', 60)::int)
                             and not exists (select 1 from pipeline.coverage_course_pages g where g.course_id = p_course and g.evidence_id is not null
                                               and g.evidence_id::text is distinct from f.input_mark and g.read_at > f.flagged_at))))
$$;


ALTER FUNCTION "security"."enrich_item_held_v1"("p_course" "uuid", "p_field" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_item_in_flight_v1"("p_provider" "uuid", "p_course" "uuid", "p_field" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- the standing gap queue's rule (security.field_gap_queue_tick_v1): the latest item of this course (or university) and field is being
  -- worked on, or waits for a person
  select coalesce(case when p_course is not null
    then (select e.state in ('queued', 'waiting', 'ai', 'leased', 'review') from pipeline.field_enrich_items e
           where e.course_id = p_course and e.field = p_field and e.provider_id = p_provider order by e.id desc limit 1)
    else (select e.state in ('queued', 'waiting', 'ai', 'leased', 'review') from pipeline.field_enrich_items e
           where e.course_id is null and e.provider_id = p_provider and e.field = p_field order by e.id desc limit 1) end, false)
$$;


ALTER FUNCTION "security"."enrich_item_in_flight_v1"("p_provider" "uuid", "p_course" "uuid", "p_field" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."enrich_item_in_flight_v1"("p_provider" "uuid", "p_course" "uuid", "p_field" "text") IS 'CF-247 3 Nov 2026 (Platform Admin 09:32 §6): true when the latest Enrich fields item of this course (or university, course null) and field is queued, waiting, with AI, leased or for review. Manual tasks, retries and the standing queue leave such items to the task that holds them.';



CREATE OR REPLACE FUNCTION "security"."enrich_parse_delivery_v1"("p" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare t text := lower(coalesce(p, '')); v_dom boolean; tok text; v_modes text[] := '{}'; v_m text;
begin
  if btrim(t) = '' then return null; end if;
  -- online that is for domestic students only does not apply to international students
  v_dom := t ~ '(online|distance)[^.]{0,80}(only|available)[^.]{0,40}(domestic|non[- ]?international|australian|new zealand|canadian|local)'
        or t ~ 'not (available|offered) (to|for) international';
  -- a mix inside one course: a share or hours each way
  if (t ~ '\d+(\.\d+)?\s*%[^|;]{0,40}(face|campus|class|person|onsite|on-site)' or t ~ '(face|campus|class|person)[^|;%]{0,20}\d+(\.\d+)?\s*%')
     and t ~ '(online|distance|remote|virtual)' then return 'blended'; end if;
  if t ~ '\d+(\.\d+)?\s*(hours?|hrs?)' and t ~ '(face|campus|class|person|onsite)' and t ~ '(online|distance|remote|virtual)' then return 'blended'; end if;
  -- otherwise each listed item is one mode; two or more different modes are a choice
  foreach tok in array regexp_split_to_array(t, '\s*(,|\||/|;|\mor\M)\s*') loop
    v_m := case
      when tok ~ '(blended|hybrid|mixed[- ]mode|multi[- ]?modal)' then 'blended'
      when tok ~ '(online|distance|remote)[^.]{0,25}(with|plus|and)[^.]{0,25}(face[- ]to[- ]face|on[- ]?campus|onsite|on-site|in[- ]person|block|residential|intensive)' then 'blended'
      when tok ~ '(face[- ]to[- ]face|on[- ]?campus)\s*\+\s*online' then 'blended'
      when tok ~ '(on[- ]?campus|\mcampus\M|face[- ]to[- ]face|in[- ]class|in[- ]person|classroom|internal)' and tok ~ '(online|distance|external|remote)' and not v_dom then 'both'
      when tok ~ '(on[- ]?campus|\mcampus\M|face[- ]to[- ]face|in[- ]class|in[- ]person|classroom|internal)' then 'on_campus'
      when tok ~ '(100\s*%\s*online|fully online|online|distance|external|remote)' and not v_dom then 'online'
      else null end;
    if v_m is not null and not v_m = any (v_modes) then v_modes := v_modes || v_m; end if;
  end loop;
  if cardinality(v_modes) = 0 then return case when v_dom and t ~ '(on[- ]?campus|face[- ]to[- ]face|in[- ]class|in[- ]person)' then 'on_campus' end; end if;
  if cardinality(v_modes) > 1 or v_modes[1] = 'both' then return 'on_campus_and_online'; end if;
  return v_modes[1];
end $$;


ALTER FUNCTION "security"."enrich_parse_delivery_v1"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_parse_duration_v1"("p" "text") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case when m is null then null else jsonb_build_object('value', m[1]::numeric,
           'unit', case when m[3] ~* '^(year|yr)' then 'years' when m[3] ~* '^month' then 'months' when m[3] ~* '^week' then 'weeks'
                        when m[3] ~* '^(semester|trimester|term)' then 'semesters' end) end
    from (select regexp_match(coalesce(p, ''), '(\d+(?:\.\d+)?)\s*(-\s*\d+(?:\.\d+)?\s*|to\s*\d+(?:\.\d+)?\s*)?(years?|yrs?|months?|weeks?|semesters?|trimesters?|terms?)\M', 'i') m) x
$$;


ALTER FUNCTION "security"."enrich_parse_duration_v1"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_parse_english_v1"("p_text" "text", "p_quote" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare v_n numeric[]; v_o numeric; v_b numeric;
begin
  if p_quote !~* 'ielts' then return null; end if;
  v_n := array(select m[1]::numeric from regexp_matches(coalesce(p_text, ''), '([4-9](?:\.[05])?)', 'g') m);
  if cardinality(v_n) = 0 then return null; end if;
  v_o := v_n[1]; v_b := case when cardinality(v_n) > 1 and v_n[2] <= v_n[1] then v_n[2] end;
  -- the overall score must be in the quote as written (6.5, or 6 / 6.0)
  if not (p_quote ~ ('(^|[^0-9.])' || replace(v_o::text, '.', '\.') || '([^0-9]|$)') or (v_o = trunc(v_o) and p_quote ~ ('(^|[^0-9.])' || trunc(v_o)::text || '(\.0)?([^0-9.]|$)'))) then return null; end if;
  return jsonb_build_object('overall', v_o, 'band', v_b);
end $_$;


ALTER FUNCTION "security"."enrich_parse_english_v1"("p_text" "text", "p_quote" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_parse_intake_periods_v1"("p_provider" "uuid", "p_text" "text", "p_quote" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_t text; v_q text; v_months int[] := '{}'; per jsonb; v_name text; v_rx text;
begin
  -- "Semester One", "semester 1", "S1", "Trimester Two" are compared as "semester 1", "trimester 2"
  v_t := regexp_replace(regexp_replace(regexp_replace(regexp_replace(lower(coalesce(p_text, '')), '\mone\M|\mfirst\M', '1', 'g'), '\mtwo\M|\msecond\M', '2', 'g'), '\mthree\M|\mthird\M', '3', 'g'), '\s+', ' ', 'g');
  v_q := regexp_replace(regexp_replace(regexp_replace(regexp_replace(lower(coalesce(p_quote, '')), '\mone\M|\mfirst\M', '1', 'g'), '\mtwo\M|\msecond\M', '2', 'g'), '\mthree\M|\mthird\M', '3', 'g'), '\s+', ' ', 'g');
  for per in
    -- the latest approved calendar only
    select x from (select p.proposal from pipeline.provider_policy_proposals p where p.provider_id = p_provider and p.kind = 'intake_calendar' and p.status = 'approved'
                    order by p.decided_at desc nulls last, p.created_at desc limit 1) l, jsonb_array_elements(coalesce(l.proposal->'periods', '[]'::jsonb)) x
  loop
    v_name := lower(btrim(per->>'period'));
    continue when v_name !~ '^(semester|trimester|term|quarter|block) [0-9]$';
    v_rx := '\m' || split_part(v_name, ' ', 1) || '\s*' || split_part(v_name, ' ', 2) || '\M';
    if v_t ~ v_rx and v_q ~ v_rx then
      -- a period with several dates (move-in, orientation, classes) starts in its last month
      v_months := v_months || (select max(m::int) from jsonb_array_elements_text(coalesce(per->'months', '[]'::jsonb)) m);
    end if;
  end loop;
  if cardinality(v_months) = 0 then return null; end if;
  return jsonb_build_object('months', (select jsonb_agg(to_char(make_date(2000, m, 1), 'FMMonth') order by m) from (select distinct unnest(v_months) m) z where m between 1 and 12),
                            'from', 'university calendar');
end $_$;


ALTER FUNCTION "security"."enrich_parse_intake_periods_v1"("p_provider" "uuid", "p_text" "text", "p_quote" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_parse_intakes_v1"("p_text" "text", "p_quote" "text") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case when count(*) > 0 then jsonb_build_object('months', jsonb_agg(m.label order by m.n)) end
    from (values (1, 'January'), (2, 'February'), (3, 'March'), (4, 'April'), (5, 'May'), (6, 'June'), (7, 'July'), (8, 'August'),
                 (9, 'September'), (10, 'October'), (11, 'November'), (12, 'December')) m(n, label)
   where coalesce(p_text, '') ~* ('\m' || left(m.label, 3)) and coalesce(p_quote, '') ~* ('\m' || left(m.label, 3))
     and not security.intake_month_negated_v1(p_quote, m.n)  -- 23:24: "excluding January & December" names no January or December intake
$$;


ALTER FUNCTION "security"."enrich_parse_intakes_v1"("p_text" "text", "p_quote" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_parse_level_v1"("p" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select sl.id from ref.study_levels sl
   where sl.short_code = (case when p is null or length(p) > 60 then null
                               when p ~* '(ph\.?d|doctor)' then 'DR'
                               when p ~* 'master' then 'MA'
                               when p ~* 'graduate diploma|post-?graduate diploma' then 'GD'
                               when p ~* 'graduate certificate|post-?graduate certificate' then 'GC'
                               when p ~* 'honours' then 'BH'
                               when p ~* 'bachelor|baccalaur|degree' then 'BA'
                               when p ~* 'associate' then 'AS'
                               when p ~* 'advanced diploma' then 'AD'
                               when p ~* 'diploma|dipl[oô]me' then 'DP'
                               when p ~* 'certificate|certificat' then 'CT' end)
   limit 1
$$;


ALTER FUNCTION "security"."enrich_parse_level_v1"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_plan_auto_note_v1"("p" "jsonb", "p_room" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_out text; v_why text;
begin
  v_out := case when p->>'auto' = 'off' then 'off' when p->>'auto' = 'full' then 'full'
                when coalesce((p->>'started')::int, 0) > 0 then 'created'
                when coalesce((p->>'considered')::int, 0) = 0 then 'nothing_eligible'
                when coalesce((p->>'replan_capped')::int, 0) > 0 then 'replan_cap'
                when coalesce((p->>'nothing_to_do')::int, 0) > 0 then 'nothing_to_do' else 'not_created' end;
  v_why := case v_out when 'off' then 'automatic plans are switched off (Enrichment plans › automatic)'
                      when 'full' then 'open automatic plans are at plans.auto_open_max'
                      when 'created' then (p->>'started') || ' plan(s) created, ' || coalesce(p->>'replanned', '0') || ' of them re-plans'
                      when 'nothing_eligible' then 'no university was due: never planned, past plans.redo_days, missing values grown, new evidence or a step that can run again'
                      when 'replan_cap' then 'universities due only for an early re-plan, and plans.replan_per_hour is used'
                      when 'nothing_to_do' then 'the universities due had no step to run for unchanged inputs (recorded in enrich_plan_noop)'
                      else 'universities were considered but none was created' end;
  insert into pipeline.enrich_plan_auto_runs(outcome, created, replanned, nothing_to_do, considered, replan_capped, open_plans, room, reason, detail)
  values (v_out, coalesce((p->>'started')::int, 0), coalesce((p->>'replanned')::int, 0), coalesce((p->>'nothing_to_do')::int, 0), coalesce((p->>'considered')::int, 0),
          coalesce((p->>'replan_capped')::int, 0), (p->>'open')::int, p_room, v_why, p);
  return p || jsonb_build_object('outcome', v_out, 'reason', v_why);
exception when others then
  raise notice 'automatic planner run not recorded: %', sqlerrm;
  return p;
end $$;


ALTER FUNCTION "security"."enrich_plan_auto_note_v1"("p" "jsonb", "p_room" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_plan_auto_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c pipeline.enrich_plan_control%rowtype; v_open int; v_room int; v_n int := 0; q record; v_plan jsonb; v_steps jsonb;
        v_redo int := security.pipeline_num_v1('plans.redo_days', 14)::int;
        -- 3 Nov 2026 (Platform Admin 09:32 §4): a university whose missing values grew since its last automatic plan is planned again before
        -- plans.redo_days, at most plans.replan_per_hour an hour (0 = off), never sooner than plans.replan_min_days after that plan
        v_re_max int := security.pipeline_num_v1('plans.replan_per_hour', 0)::int;
        v_re_rise int := security.pipeline_num_v1('plans.replan_min_new_gaps', 5)::int;
        v_re_days int := security.pipeline_num_v1('plans.replan_min_days', 2)::int;
        -- 3 Nov 2026 (Platform Admin P0 mandate 10:44 §3 Agent A): also re-plan on new verified evidence and on steps that can run again
        -- (each 0 = off), longest-waiting first (0 = the earlier order), and leave a university with a recent Run now to it
        v_on_ev boolean := security.pipeline_num_v1('plans.replan_on_evidence', 0) > 0;
        v_on_rt boolean := security.pipeline_num_v1('plans.replan_on_retry', 0) > 0;
        v_fair boolean := security.pipeline_num_v1('plans.fair_order', 0) > 0;
        v_defer boolean := security.pipeline_num_v1('plans.run_now_supersedes_auto', 1) > 0;
        -- 10 Nov 2026 (IQ-00355): a university whose plan has no step to run is remembered (enrich_plan_noop) and not looked at again for this many hours
        v_noop_wait int := security.pipeline_num_v1('plans.noop_wait_hours', 24)::int;
        v_re_used int; v_re int := 0; v_is_re boolean; v_in jsonb; v_why text[]; v_fp text; v_same int := 0; v_gaps boolean; v_ev boolean; v_rt jsonb; v_seen int := 0; v_capped int := 0;
begin
  select * into c from pipeline.enrich_plan_control where id = 1;
  if not coalesce(c.auto_enabled, false) then return security.enrich_plan_auto_note_v1(jsonb_build_object('auto', 'off')); end if;  -- CF-247 ops D: every run recorded
  select count(*) into v_open from pipeline.enrich_plan_runs where mode = 'auto' and state in ('queued', 'running');
  v_room := least(security.pipeline_num_v1('plans.auto_open_max', 20)::int - v_open, security.pipeline_num_v1('plans.auto_per_run', 10)::int);
  if v_room <= 0 then return security.enrich_plan_auto_note_v1(jsonb_build_object('auto', 'full', 'open', v_open), v_room); end if;
  select count(*) into v_re_used from pipeline.enrich_plan_runs
   where mode = 'auto' and estimate ? 'replan_of' and created_at > now() - make_interval(hours => 1);  -- fixed: the re-plan cap is a count per hour
  for q in select z.* from (
           select x.*, l.id last_id, l.created_at last_at, l.missing_then, a.id any_id, a.created_at any_at, a.steps any_steps, a.estimate->>'fingerprint' any_fp,
                  i.v inputs, i.fp inputs_fp,
                  case when l.id is null then 0 when l.created_at <= now() - make_interval(days => v_redo) then 1 else 2 end tier
             from security.enrich_plan_priority_v1() x
             left join lateral (select r.id, r.created_at, (r.estimate->>'missing')::numeric missing_then from pipeline.enrich_plan_runs r
                                 where r.provider_id = x.provider_id and r.mode = 'auto' order by r.created_at desc limit 1) l on true
             left join lateral (select r.id, r.created_at, r.steps, r.estimate from pipeline.enrich_plan_runs r
                                 where r.provider_id = x.provider_id order by r.created_at desc limit 1) a on true
             -- the evidence and retry inputs, read only for universities held inside plans.redo_days and only when those re-plans are on
             -- the inputs of a university held inside plans.redo_days, read only when early re-plans are on, with their fingerprint
             left join lateral (select i0.v, md5(jsonb_build_object('missing', x.missing, 'evidence_at', i0.v->'evidence_at', 'central_at', i0.v->'central_at',
                                                                    'retry', i0.v->'retry_steps')::text) fp
                                  from (select security.enrich_plan_inputs_v1(x.provider_id) v) i0
                                 where v_re_max > 0 and l.id is not null and l.created_at > now() - make_interval(days => v_redo)
                                   -- CF-247 ops D (IQ-00064, plans.retry_ignores_min_days): also read once the latest plan has a step that can run
                                   -- again; its own plans.retry_after_hours wait (security.enrich_plan_inputs_v1), the fingerprint and the cap still apply
                                   and (a.created_at <= now() - make_interval(days => v_re_days)
                                        or (v_on_rt and security.pipeline_num_v1('plans.retry_ignores_min_days', 0) >= 1
                                            and exists (select 1 from jsonb_array_elements(coalesce(a.steps, '[]'::jsonb)) s0
                                                         where s0->>'status' in ('failed', 'stopped', 'cancelled', 'timed_out', 'skipped'))))) i on true
            where not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = x.provider_id)  -- 22 Oct 2026 (Platform Admin 11:42): unpublished providers wait; publishing them again brings them back
              and not exists (select 1 from pipeline.enrich_plan_runs r where r.provider_id = x.provider_id and r.state in ('queued', 'running'))
              and (l.id is null
                   or (l.created_at <= now() - make_interval(days => v_redo) and not (v_defer and a.created_at > now() - make_interval(days => v_re_days)))
                   or (v_re_max > 0 and l.created_at <= now() - make_interval(days => v_re_days) and a.created_at <= now() - make_interval(days => v_re_days)
                       and x.missing >= l.missing_then + v_re_rise)
                   or (v_on_ev and ((i.v->>'evidence_new')::int > 0 or (i.v->>'central_new')::boolean)
                       and a.created_at <= now() - make_interval(days => v_re_days))  -- CF-247 ops D: evidence re-plans keep plans.replan_min_days
                   or (v_on_rt and jsonb_array_length(i.v->'retry_steps') > 0))
              -- an early re-plan of unchanged inputs: not the inputs of the latest run, nor inputs already found to need nothing
              and (i.fp is null or (i.fp is distinct from a.estimate->>'fingerprint'
                                    and not exists (select 1 from pipeline.enrich_plan_noop n where n.provider_id = x.provider_id and n.fingerprint = i.fp)))
              -- 10 Nov 2026 (IQ-00355): a university that is not an early re-plan (never planned, or due again) and was found to need nothing is not looked at again
              -- for plans.noop_wait_hours; it must not hold a place in the candidate window every hour while universities that can be planned wait behind it
              and (i.fp is not null or not exists (select 1 from pipeline.enrich_plan_noop n where n.provider_id = x.provider_id and n.at > now() - make_interval(hours => v_noop_wait)))) z
            order by case when v_fair then z.tier else 0 end,
                     (z.last_id is null or z.last_at <= now() - make_interval(days => v_redo)) desc,
                     (z.country in (select jsonb_array_elements_text(coalesce(s.value, '[]'::jsonb)) from pipeline.platform_toolset_settings s
                                     where s.toolset_key = 'pipeline' and s.key = 'plans.priority_countries')) desc,
                     case when v_fair then z.any_at end asc nulls first,
                     z.missing desc, z.best_rank nulls last limit v_room * 3 loop
    exit when v_n >= v_room;
    v_seen := v_seen + 1;
    v_is_re := q.last_id is not null and q.last_at > now() - make_interval(days => v_redo);
    if v_is_re and v_re_used + v_re >= v_re_max then v_capped := v_capped + 1; continue; end if;
    v_plan := security.enrich_plan_v1(q.provider_id);
    v_steps := (select coalesce(jsonb_agg(x || jsonb_build_object('status', 'pending')), '[]'::jsonb) from jsonb_array_elements(v_plan->'steps') x where not coalesce((x->>'running')::boolean, false));
    v_in := coalesce(q.inputs, security.enrich_plan_inputs_v1(q.provider_id));
    v_why := '{}';
    if v_is_re then
      v_gaps := q.last_at <= now() - make_interval(days => v_re_days) and q.missing >= q.missing_then + v_re_rise;
      v_ev := v_on_ev and ((v_in->>'evidence_new')::int > 0 or (v_in->>'central_new')::boolean) and q.any_at <= now() - make_interval(days => v_re_days);
      v_rt := case when v_on_rt then coalesce(v_in->'retry_steps', '[]'::jsonb) else '[]'::jsonb end;
      if v_gaps then v_why := v_why || 'gaps'::text; end if;
      if v_ev then v_why := v_why || 'evidence'::text; end if;
      if jsonb_array_length(v_rt) > 0 then v_why := v_why || 'retry'::text; end if;
      -- a step the latest run finished, whose inputs did not change, is not done again
      v_steps := (select coalesce(jsonb_agg(x), '[]'::jsonb) from jsonb_array_elements(v_steps) x
                   where v_rt ? (x->>'step')
                      or (v_gaps and x->>'step' in ('pages', 'fields'))
                      or (v_ev and x->>'step' = 'fields')
                      or not exists (select 1 from jsonb_array_elements(coalesce(q.any_steps, '[]'::jsonb)) s where s->>'step' = x->>'step'));
    end if;
    -- the input fingerprint (missing values, verified evidence, central pages, retryable steps)
    v_fp := coalesce(q.inputs_fp, md5(jsonb_build_object('missing', q.missing, 'evidence_at', v_in->'evidence_at', 'central_at', v_in->'central_at',
                                                         'retry', v_in->'retry_steps')::text));
    if jsonb_array_length(v_steps) = 0 or (select bool_and(coalesce((x->>'person')::boolean, false)) from jsonb_array_elements(v_steps) x) then
      -- nothing to do for these inputs: an early re-plan is not looked at again until they change; any other university not for plans.noop_wait_hours
      -- (10 Nov 2026, IQ-00355: recorded for every university, not only for a re-plan)
      insert into pipeline.enrich_plan_noop as n(provider_id, fingerprint, at) values (q.provider_id, v_fp, now())
      on conflict (provider_id) do update set fingerprint = excluded.fingerprint, at = excluded.at;
      v_same := v_same + 1;
      continue;
    end if;
    insert into pipeline.enrich_plan_runs(provider_id, mode, steps, estimate, requested_by, reason)
    values (q.provider_id, 'auto', v_steps, jsonb_build_object('credits', v_plan->'est_credits', 'usd', v_plan->'est_usd', 'missing', q.missing, 'fingerprint', v_fp,
                                                               'inputs', v_in - 'last_state' - 'since')
              || case when v_is_re then jsonb_build_object('replan_of', q.last_id, 'missing_then', q.missing_then, 'replan_why', to_jsonb(v_why), 'after_run', q.any_id) else '{}'::jsonb end, c.owner,
            case when v_is_re then 'Automatic enrichment plan (' || array_to_string(array_remove(array[
                   case when 'gaps' = any (v_why) then 'missing values grew from ' || q.missing_then || ' to ' || q.missing || ' since the last plan' end,
                   case when 'evidence' = any (v_why) then 'new verified evidence since the last plan' end,
                   case when 'retry' = any (v_why) then 'steps that can run again: ' || (select string_agg(t, ', ') from jsonb_array_elements_text(v_rt) t) end], null), '; ') || '): '
                 else 'Automatic enrichment plan (most missing first): ' end || c.reason)
    on conflict do nothing;
    if found then v_n := v_n + 1; if v_is_re then v_re := v_re + 1; end if; end if;
  end loop;
  return security.enrich_plan_auto_note_v1(jsonb_build_object('auto', 'on', 'started', v_n, 'replanned', v_re, 'nothing_to_do', v_same, 'open', v_open + v_n,
                                                         'considered', v_seen, 'replan_capped', v_capped), v_room);
end $$;


ALTER FUNCTION "security"."enrich_plan_auto_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_plan_cancel_steps_v1"("p_run" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.enrich_plan_runs%rowtype; s jsonb; i int; v_claims text := current_setting('request.jwt.claims', true); v_note text; v_steps jsonb;
        v_tasks jsonb := '[]'::jsonb; v_n int := 0;
begin
  select * into r from pipeline.enrich_plan_runs where id = p_run;
  if r.id is null then return jsonb_build_object('steps_cancelled', 0, 'tasks', v_tasks); end if;
  v_steps := r.steps;
  for i in 0 .. coalesce(jsonb_array_length(r.steps), 0) - 1 loop
    s := r.steps->i;
    continue when coalesce(s->>'status', '') not in ('pending', 'waiting', 'running');
    v_note := 'cancelled with the run: ' || p_reason;
    if s->>'status' = 'running' and nullif(s->'ref'->>'id', '') is not null and s->'ref'->>'kind' in ('job', 'onboarding') then
      begin
        -- the task was started as the person behind the run (security.enrich_plan_start_step_v1); it is cancelled the same way, through its own control
        perform set_config('request.jwt.claims', json_build_object('sub', coalesce(case when s->'ref'->>'kind' = 'job' then
                   (select j.requested_by from pipeline.admin_jobs j where j.id = (s->'ref'->>'id')::uuid) end, r.requested_by), 'role', 'authenticated')::text, true);
        if s->'ref'->>'kind' = 'job' then
          perform public.admin_jobs('cancel', jsonb_build_object('id', s->'ref'->>'id', 'reason', 'Enrichment plan cancelled: ' || p_reason));
        else
          perform public.admin_provider_onboarding('stop', jsonb_build_object('ids', jsonb_build_array(s->'ref'->>'id'), 'reason', 'Enrichment plan cancelled: ' || p_reason));
        end if;
        v_note := 'task cancelled with the run: ' || p_reason;
        v_tasks := v_tasks || jsonb_build_object('step', s->>'step', 'kind', s->'ref'->>'kind', 'id', s->'ref'->>'id', 'cancelled', true);
      exception when others then
        v_note := 'the task could not be cancelled (' || left(sqlerrm, 200) || '); see Task manager';
        v_tasks := v_tasks || jsonb_build_object('step', s->>'step', 'kind', s->'ref'->>'kind', 'id', s->'ref'->>'id', 'cancelled', false, 'error', left(sqlerrm, 200));
      end;
      perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
    end if;
    v_steps := jsonb_set(v_steps, array[i::text], s || jsonb_build_object('status', 'cancelled', 'note', v_note, 'finished_at', now()));
    v_n := v_n + 1;
  end loop;
  update pipeline.enrich_plan_runs set steps = v_steps, updated_at = now() where id = p_run;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('enrich_plan', 'cancel', r.provider_id::text, jsonb_build_object('run', p_run, 'reason', p_reason, 'steps_cancelled', v_n, 'tasks', v_tasks), auth.uid());
  return jsonb_build_object('steps_cancelled', v_n, 'tasks', v_tasks);
end $$;


ALTER FUNCTION "security"."enrich_plan_cancel_steps_v1"("p_run" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."enrich_plan_cancel_steps_v1"("p_run" "uuid", "p_reason" "text") IS 'CF-247 3 Nov 2026 (Platform Admin 09:32 §3 "Cancel safely"): the pending, waiting and running steps of a cancelled plan run become cancelled; each running step''s task is cancelled through its own control (admin_jobs cancel, provider onboarding stop) as the person behind the run, the way the step started it. Each outcome is on the step and in admin_control_events.';



CREATE OR REPLACE FUNCTION "security"."enrich_plan_inputs_v1"("p_provider" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with a as (select r.id, r.state, r.steps, r.created_at, coalesce(r.finished_at, r.created_at) base from pipeline.enrich_plan_runs r
              where r.provider_id = p_provider order by r.created_at desc limit 1)
  select jsonb_build_object(
    'last_run', a.id, 'last_state', a.state, 'last_at', a.created_at, 'since', a.base,
    'evidence_at', ev.at, 'evidence_new', coalesce(ev.n, 0),
    'central_at', cs.searched_at, 'central_new', coalesce(cs.searched_at > a.base, false),
    'retry_steps', coalesce(rt.steps, '[]'::jsonb))
    from (select 1) one
    left join a on true
    -- verified course pages: bound, read, with stored evidence (index provider_id, read_at)
    left join lateral (select max(g.read_at) at, count(*) filter (where g.read_at > a.base) n from pipeline.coverage_course_pages g
                        where g.provider_id = p_provider and g.evidence_id is not null and g.read_status = 'read') ev on true
    left join lateral (select s.searched_at from pipeline.provider_central_search s where s.provider_id = p_provider and s.state = 'done') cs on true
    -- steps of the latest run (not one a person cancelled) whose failure cause has cleared, each retried a bounded number of times
    left join lateral (select jsonb_agg(distinct s->>'step') steps from jsonb_array_elements(case when a.state = 'cancelled' then '[]'::jsonb else a.steps end) s
       where ((s->>'status' = 'skipped' and coalesce(s->>'note', '') like 'no room in the % share%'
               and security.fc_budget_left_v1(case s->>'group' when 'course_search' then 'course_link_search' when 'scholarships' then 'sch_scrape' when 'reads' then 'scrape' when 'central' then 'central_map' else 'other' end)
                   >= least(coalesce((s->>'est_credits')::numeric, 0), security.fc_setting_num_v1('daily_share_' || (s->>'group'), 0)))
          or (s->>'status' in ('failed', 'stopped', 'cancelled')
              and coalesce((s->>'finished_at')::timestamptz, a.base) <= now() - make_interval(hours => security.pipeline_num_v1('plans.retry_after_hours', 6)::int)
              -- a cause that time does not clear (too few pages, no website, not a search target ...) waits for new evidence or gaps
              and not exists (select 1 from pipeline.platform_toolset_settings w cross join lateral jsonb_array_elements_text(coalesce(w.value, '[]'::jsonb)) k(t)
                               where w.toolset_key = 'pipeline' and w.key = 'plans.retry_waits_for_change' and position(lower(k.t) in lower(coalesce(s->>'note', ''))) > 0))
          or (s->>'status' = 'timed_out'
              and case s->'ref'->>'kind'
                    when 'job' then exists (select 1 from pipeline.admin_jobs j where j.id = nullif(s->'ref'->>'id', '')::uuid and j.state in ('failed', 'cancelled'))
                    when 'onboarding' then exists (select 1 from pipeline.provider_onboarding o where o.id = nullif(s->'ref'->>'id', '')::uuid and o.status in ('stopped', 'cancelled'))
                    else true end))
         and (select count(*) from pipeline.enrich_plan_runs r2 cross join lateral jsonb_array_elements(r2.steps) s2
               where r2.provider_id = p_provider and r2.created_at > now() - make_interval(days => security.pipeline_num_v1('plans.redo_days', 14)::int)
                 and s2->>'step' = s->>'step' and s2->>'status' in ('failed', 'stopped', 'cancelled', 'timed_out', 'skipped'))
             < security.pipeline_num_v1('plans.step_retry_max', 3)) rt on true
$$;


ALTER FUNCTION "security"."enrich_plan_inputs_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."enrich_plan_inputs_v1"("p_provider" "uuid") IS 'CF-247 3 Nov 2026 (Platform Admin P0 mandate 10:44 §3 Agent A): what an early re-plan of a university depends on, against its latest plan run of any mode: new verified evidence since that run finished (course pages read with stored evidence; central pages searched), and the steps that became retryable (share has room again; failed, stopped or cancelled step after plans.retry_after_hours; timed-out step whose task ended failed or cancelled), each at most plans.step_retry_max unfinished ends in plans.redo_days. Read-only.';



CREATE OR REPLACE FUNCTION "security"."enrich_plan_needs_person_v1"("p_run" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select nullif(string_agg(z.m, '; ' order by z.o), '')
    from (
      select e.o, case
        when e.s->>'status' = 'stopped' and e.s->>'step' = 'adapter' then
          'Adapter: ' || case ob.stop_reason
            when 'nothing_ready' then 'built, but no field passed its check'
                 || coalesce(' (' || (select string_agg(k || ' ' || v, ', ' order by k) from jsonb_each_text(ob.result->'held') x(k, v)) || ')', '')
            when 'too_few_pages' then 'too few course pages found to build it'
            when 'no_website' then 'no website on record'
            when 'approve_central' then 'shared pages (fees, entry) waiting for approval'
            else 'stopped' || coalesce(' (' || ob.stop_reason || ')', '') end
        when e.s->>'status' in ('failed', 'cancelled', 'timed_out', 'skipped') then
          coalesce(e.s->>'label', e.s->>'step') || ': ' || replace(e.s->>'status', '_', ' ') || coalesce(', ' || nullif(e.s->>'note', ''), '')
        when e.s->>'status' = 'person' and exists (select 1 from pipeline.provider_onboarding o2 where o2.provider_id = r.provider_id and o2.status = 'waiting_admit') then
          'Adapter ready to admit (Layer 2/3 › Universities)'
        end m
        from pipeline.enrich_plan_runs r
        cross join lateral jsonb_array_elements(r.steps) with ordinality e(s, o)
        left join pipeline.provider_onboarding ob on e.s->'ref'->>'kind' = 'onboarding' and ob.id = nullif(e.s->'ref'->>'id', '')::uuid
       where r.id = p_run) z
   where z.m is not null
$$;


ALTER FUNCTION "security"."enrich_plan_needs_person_v1"("p_run" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_plan_orphans_issue_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb := security.enrich_plan_orphans_v1(); r record;
begin
  if (v->>'orphans')::int > 0 then
    perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'enrich_plan_orphans',
      'title', 'Enrichment plan tasks running without a live plan', 'layer', 'Layer 2', 'subsystem', 'pipeline.enrich_plan_runs',
      'failure', (v->>'orphans') || ' task(s) started by plan steps are still open while no open plan run has them (' ||
                 (select string_agg(k || ' ' || n, ', ') from jsonb_each_text(v->'by_cause') e(k, n)) || ')',
      'expected', 'Every task a plan step started belongs to an open plan run, or ends with it (cancel, supersede)',
      'source', 'integration-validate (plan lifecycle)', 'validation_layer', 'V4', 'provider_ids', v->'provider_ids',
      'evidence', jsonb_build_object('orphans', v->'orphans', 'by_cause', v->'by_cause', 'sample', v->'tasks'),
      'severity', 'P1', 'root_cause_class', 'unclassified', 'workstream', 'A7'), 'integration-validate');
    for r in select i.id from pipeline.integration_issues i where i.fingerprint = 'enrich_plan_orphans' and i.status <> 'closed' loop
      perform security.integration_alert_sync_v1(r.id, true);
    end loop;
  else
    for r in select i.id, i.status, i.condition_cleared_at from pipeline.integration_issues i where i.fingerprint = 'enrich_plan_orphans' and i.status <> 'closed' loop
      if r.condition_cleared_at is null then
        update pipeline.integration_issues set condition_cleared_at = now() where id = r.id;
        insert into pipeline.integration_issue_events(issue_id, kind, from_status, to_status, actor, note)
        values (r.id, 'not_observed', r.status, r.status, 'integration-validate', 'condition no longer observed; close after production verification');
      end if;
      perform security.integration_alert_sync_v1(r.id, false);
    end loop;
  end if;
  return jsonb_build_object('enrich_plan_orphans', v->'orphans');
end $$;


ALTER FUNCTION "security"."enrich_plan_orphans_issue_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."enrich_plan_orphans_issue_v1"() IS 'CF-247 3 Nov 2026 (Platform Admin P0 mandate 10:44 §3 Agent A): job integration-validate raises the integration issue enrich_plan_orphans (P1, A7 Scheduling) while security.enrich_plan_orphans_v1 finds plan tasks without a live plan, and marks it cleared when it no longer does.';



CREATE OR REPLACE FUNCTION "security"."enrich_plan_orphans_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with live as (select s->'ref'->>'kind' kind, s->'ref'->>'id' id from pipeline.enrich_plan_runs r cross join lateral jsonb_array_elements(r.steps) s
                 where r.state in ('queued', 'running') and s->>'status' = 'running' and nullif(s->'ref'->>'id', '') is not null),
  jobs as (select 'job' kind, j.id, j.kind task, j.state status, j.created_at, nullif(j.args->>'plan_run', '')::uuid run_id from pipeline.admin_jobs j
            where j.state not in ('done', 'failed', 'cancelled') and j.args ? 'plan_run'
              and not exists (select 1 from live where live.kind = 'job' and live.id = j.id::text)),
  onb as (select distinct on (o.id) 'onboarding' kind, o.id, 'provider_onboarding' task, o.status, o.created_at, r.id run_id
            from pipeline.enrich_plan_runs r cross join lateral jsonb_array_elements(r.steps) s
            join pipeline.provider_onboarding o on o.id = nullif(s->'ref'->>'id', '')::uuid
           where s->'ref'->>'kind' = 'onboarding' and r.created_at > now() - make_interval(days => security.pipeline_num_v1('plans.orphan_lookback_days', 30)::int)
             and o.status not in ('done', 'cancelled', 'stopped', 'waiting_admit', 'scholarships')
             and not exists (select 1 from live where live.kind = 'onboarding' and live.id = o.id::text)
           order by o.id, r.created_at desc),
  t as (select t0.*, r.state run_state, r.provider_id,
               (select s->>'status' from jsonb_array_elements(r.steps) s where s->'ref'->>'id' = t0.id::text limit 1) step_status
          from (select * from jobs union all select * from onb) t0 left join pipeline.enrich_plan_runs r on r.id = t0.run_id),
  c as (select t.*, case when t.run_state is null then 'plan run missing' when t.run_state = 'cancelled' then 'plan cancelled'
                         when t.step_status = 'timed_out' then 'step timed out, task carries on' when t.run_state in ('done', 'failed') then 'plan finished'
                         else 'not a running step of its plan' end cause from t)
  select jsonb_build_object('orphans', (select count(*) from c),
    'by_cause', (select coalesce(jsonb_object_agg(cause, n), '{}'::jsonb) from (select cause, count(*) n from c group by cause) z),
    'provider_ids', (select coalesce(jsonb_agg(distinct provider_id), '[]'::jsonb) from c where provider_id is not null),
    'tasks', (select coalesce(jsonb_agg(jsonb_build_object('kind', kind, 'id', id, 'task', task, 'status', status, 'run', run_id, 'run_state', run_state,
                                                            'step_status', step_status, 'cause', cause) order by created_at), '[]'::jsonb)
                from (select * from c order by created_at limit 50) z))
$$;


ALTER FUNCTION "security"."enrich_plan_orphans_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."enrich_plan_orphans_v1"() IS 'CF-247 3 Nov 2026 (Platform Admin P0 mandate 10:44 §3 Agent A "No orphaned work"): plan tasks still open without a live plan: admin_jobs carrying a plan_run, and provider onboarding a plan step started in plans.orphan_lookback_days, that no queued or running plan run has as a running step; by cause (plan cancelled, plan finished, step timed out, run missing). Read-only.';



CREATE OR REPLACE FUNCTION "security"."enrich_plan_priority_v1"() RETURNS TABLE("provider_id" "uuid", "name" "text", "country" "text", "courses" bigint, "missing" bigint, "best_rank" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select a.provider_id, max(coalesce(p.display_name, p.canonical_name)), max(a.country_code), count(distinct a.course_id),
         count(*) filter (where a.state <> 'admitted'),
         (select min(coalesce(o.rank_low, o.rank_exact)) from ranking.observation_provider_links l join ranking.observations o on o.id = l.observation_id where l.provider_id = a.provider_id)
    from pipeline.course_attribute_coverage a join pipeline.field_register r on r.field = a.attribute and r.reader in ('coverage', 'enrich')
    join catalogue.providers p on p.id = a.provider_id
   where not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = a.provider_id)
   group by a.provider_id
  having count(*) filter (where a.state <> 'admitted') > 0
$$;


ALTER FUNCTION "security"."enrich_plan_priority_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_plan_start_step_v1"("p_run" "uuid", "p_step" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.enrich_plan_runs%rowtype; v jsonb; v_o record; v_fields jsonb;
begin
  select * into r from pipeline.enrich_plan_runs where id = p_run;
  -- 3 Nov 2026 (Platform Admin P0 mandate 10:44 §3 Agent A): a run that was cancelled, superseded or has finished starts no further step
  if r.id is null or r.state not in ('queued', 'running') then raise exception 'the plan run is %; no further step starts', coalesce(r.state, 'missing'); end if;
  -- the step runs as the person behind the run, with that person's role checks
  perform set_config('request.jwt.claims', json_build_object('sub', r.requested_by, 'role', 'authenticated')::text, true);
  if p_step = 'site' then
    v := public.admin_jobs('start', jsonb_build_object('kind', 'provider_fill', 'from', 'Enrichment plan', 'args', jsonb_build_object('provider_id', r.provider_id)));
    return jsonb_build_object('kind', 'job', 'id', v->>'id');
  elsif p_step = 'pages' then
    v := public.admin_jobs('start', jsonb_build_object('kind', 'course_page_find', 'from', 'Enrichment plan', 'args', jsonb_build_object('provider_id', r.provider_id)));
    return jsonb_build_object('kind', 'job', 'id', v->>'id');
  elsif p_step = 'scholarships' then
    v := public.admin_jobs('start', jsonb_build_object('kind', 'scholarship_provider_scan', 'from', 'Enrichment plan', 'args', jsonb_build_object('provider_ids', jsonb_build_array(r.provider_id))));
    return jsonb_build_object('kind', 'job', 'id', v->>'id');
  elsif p_step = 'fields' then
    v := public.admin_enrich_fields('start', jsonb_build_object('provider_ids', jsonb_build_array(r.provider_id), 'fields', to_jsonb(array(select e.field from security.enrich_fields_v1() e where e.field <> 'provider_address')),
                                    'ai', true, 'scraper', true, 'reason', 'Enrichment plan (' || r.mode || '): ' || r.reason));
    return jsonb_build_object('kind', 'job', 'id', v->>'job_id', 'items', v->'items');
  elsif p_step = 'adapter' then
    select o.id, o.status into v_o from pipeline.provider_onboarding o where o.provider_id = r.provider_id order by o.created_at desc limit 1;
    if v_o.status = 'stopped' then
      v := public.admin_provider_onboarding('retry', jsonb_build_object('ids', jsonb_build_array(v_o.id), 'reason', 'Enrichment plan (' || r.mode || '): ' || r.reason));
    elsif v_o.status is null or v_o.status in ('done', 'cancelled') then
      v := public.admin_provider_onboarding('start', jsonb_build_object('provider_ids', jsonb_build_array(r.provider_id), 'reason', 'Enrichment plan (' || r.mode || '): ' || r.reason));
    end if;
    return jsonb_build_object('kind', 'onboarding', 'id', (select o.id from pipeline.provider_onboarding o where o.provider_id = r.provider_id order by o.created_at desc limit 1));
  end if;
  raise exception 'unknown step %', p_step;
end $$;


ALTER FUNCTION "security"."enrich_plan_start_step_v1"("p_run" "uuid", "p_step" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_plan_tick_v1"("p_run" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.enrich_plan_runs%rowtype; s jsonb; i int; v_ref jsonb; v_dep jsonb; v_state text; v_done int := 0; v_started int := 0; v_room numeric; v_note text; v_track text; v_work jsonb;
        v_wait int := security.pipeline_num_v1('plans.step_wait_hours', 48)::int; v_max int := security.pipeline_num_v1('plans.step_max_hours', 24)::int;
begin
  for r in select * from pipeline.enrich_plan_runs where state in ('queued', 'running') and (p_run is null or id = p_run)
              and (mode <> 'auto' or not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = pipeline.enrich_plan_runs.provider_id))  -- 22 Oct 2026 (Platform Admin 11:42): automatic plans of unpublished providers wait; Run now plans carry on
            order by created_at for update skip locked loop
    if r.state = 'queued' then
      update pipeline.enrich_plan_runs set state = 'running', started_at = now(), updated_at = now(), fields_before = security.enrich_provider_fields_v1(r.provider_id) where id = r.id;
      r.state := 'running';
    end if;
    -- the first step not finished
    if not exists (select 1 from jsonb_array_elements(r.steps) x where x->>'status' in ('pending', 'waiting', 'running')) then
      update pipeline.enrich_plan_runs set state = 'done', finished_at = now(), updated_at = now(), fields_after = security.enrich_provider_fields_v1(r.provider_id),
             needs_person = security.enrich_plan_needs_person_v1(r.id),
             actual = jsonb_build_object(
               -- CF-247 IQ-00066: moved, not_needed or no_movement; CF-247 ops D: from what the steps' tasks actually moved (ops.outcome_on)
               'outcome', coalesce(case when security.pipeline_num_v1('ops.outcome_on', 0) >= 1 then security.plan_outcome_compute_v1(r.id, true)->>'legacy' end,
                                   security.plan_run_outcome_v1(r.steps)),
               'credits', (select coalesce(sum(x.units), 0) from pipeline.coverage_vendor_usage x where x.provider_id = r.provider_id and x.at between r.started_at and now()),
               'credits_on_demand', (select coalesce(sum(x.units), 0) from pipeline.coverage_vendor_usage x where x.on_demand_run = r.id),
               'usd', round(coalesce((select sum(e.cost_usd) from pipeline.field_enrich_items e where e.provider_id = r.provider_id and e.updated_at between r.started_at and now()), 0)
                          + coalesce((select sum(d.cost_usd) from pipeline.uni_adapter_drafts d where d.provider_id = r.provider_id and d.created_at between r.started_at and now()), 0)
                          + coalesce((select sum(x.cost_usd) from pipeline.scholarship_ai_extractions x where x.provider_id = r.provider_id and x.at between r.started_at and now()), 0), 4))
       where id = r.id;
      perform security.plan_outcome_record_v1(r.id, 'at_close');  -- CF-247 ops D: the plan's explicit outcome (outcome columns only)
      insert into search.refresh_requests(requested_by) values ('enrichment plan ' || left(r.id::text, 8) || ' finished');
      v_done := v_done + 1; continue;
    end if;
    -- v2.15.308 (Platform Admin 21 Oct 2026 "Two tracks + more credits"): Fill missing fields (stored pages and AI) runs on its own track,
    -- beside the website, course-page, adapter and scholarship steps; each run starts or checks the next step of each track.
    foreach v_track in array array['ai', 'fc'] loop
    i := (select min(o - 1) from jsonb_array_elements(r.steps) with ordinality e(x, o)
           where x->>'status' in ('pending', 'waiting', 'running') and case when x->>'step' = 'fields' then 'ai' else 'fc' end = v_track);
    continue when i is null;
    s := r.steps->i;
    if s->>'status' in ('pending', 'waiting') then
      v_note := null;
      -- CF-247 IQ-00066 (plans.step_needs_work_on): whether the step's scope has eligible work now
      v_work := case when security.pipeline_num_v1('plans.step_needs_work_on', 0) >= 1 and not coalesce((s->>'person')::boolean, false)
                     then security.plan_step_work_v1(r.provider_id, s->>'step') end;
      -- CF-247 ops D (P0 mandate 15:37 §7 dependency sequencing, IQ-00064): whether the step's input is still being produced; it waits at most
      -- plans.step_wait_hours (counted from when it was first deferred), then goes ahead as before
      v_dep := security.plan_step_dependency_v1(r.id, s);
      if v_dep is not null and coalesce((s->'deferred'->>'since')::timestamptz, now()) < now() - make_interval(hours => v_wait) then v_dep := null; end if;
      if (s->>'person')::boolean then
        v_state := 'person';  -- a person's step: shown, not waited for
      elsif (select x.state from pipeline.enrich_plan_runs x where x.id = r.id) not in ('queued', 'running') then
        v_state := 'cancelled'; v_note := 'the run is no longer open; the step was not started';  -- 3 Nov 2026 (P0 mandate 10:44 §3 Agent A)
      elsif nullif(s->>'blocked', '') is not null and exists (select 1 from catalogue.providers p where p.id = r.provider_id and nullif(btrim(p.website), '') is null) then
        v_state := 'skipped'; v_note := s->>'blocked';
      elsif not coalesce((v_work->>'work')::boolean, true) then
        -- CF-247 IQ-00066: no eligible work now: the step is not needed (no task is started), with the reason
        v_state := 'not_needed'; v_note := left('Not needed: ' || coalesce(v_work->>'reason', 'no eligible work'), 300);
      elsif v_dep is not null then
        -- CF-247 ops D: deferred_dependency, with the reason (no task is started, so nothing is queued or paid twice)
        v_state := 'waiting'; v_note := left('Deferred: ' || (v_dep->>'reason'), 300);
      elsif r.mode = 'auto' and s->>'group' not in ('none') and coalesce((s->>'est_credits')::numeric, 0) > 0
            and security.fc_budget_left_v1(case s->>'group' when 'course_search' then 'course_link_search' when 'scholarships' then 'sch_scrape' when 'reads' then 'scrape' when 'central' then 'central_map' else 'other' end)
                < least((s->>'est_credits')::numeric, security.fc_setting_num_v1('daily_share_' || (s->>'group'), 0)) then
        -- automatic: wait for room in the toolset share
        v_state := case when coalesce((s->>'waiting_since')::timestamptz, now()) < now() - make_interval(hours => v_wait) then 'skipped' else 'waiting' end;
        v_note := case when v_state = 'skipped' then 'no room in the ' || (s->>'group') || ' share for ' || v_wait || ' hours' else 'waiting for room in the ' || (s->>'group') || ' share' end;
      else
        begin
          v_ref := security.enrich_plan_start_step_v1(r.id, s->>'step');
          v_state := 'running'; v_started := v_started + 1;
          -- v2.15.307: the task says it belongs to this plan (Task manager shows "Enrichment plan (automatic)")
          if v_ref->>'kind' = 'job' and nullif(v_ref->>'id', '') is not null then
            update pipeline.admin_jobs set args = args || jsonb_build_object('plan_run', r.id, 'plan_mode', r.mode),
                   reason = 'Enrichment plan (' || case r.mode when 'auto' then 'automatic' else 'Run now' end || '): ' || coalesce(reason, '')
             where id = (v_ref->>'id')::uuid;
          end if;
        exception when others then
          v_state := 'failed'; v_note := left(sqlerrm, 300);
        end;
      end if;
      update pipeline.enrich_plan_runs set updated_at = now(),
             steps = jsonb_set(steps, array[i::text], ((steps->i) - 'deferred') || jsonb_build_object('status', v_state, 'note', v_note)
                       || case when v_state = 'running' then jsonb_build_object('ref', v_ref, 'started_at', now()) else '{}'::jsonb end
                       || case when v_state = 'waiting' and v_dep is null and not (steps->i ? 'waiting_since') then jsonb_build_object('waiting_since', now()) else '{}'::jsonb end
                       || case when v_state = 'waiting' and v_dep is not null then jsonb_build_object('deferred', v_dep || jsonb_build_object('since', coalesce(steps->i->'deferred'->'since', to_jsonb(now())))) else '{}'::jsonb end
                       || case when v_state in ('person', 'skipped', 'failed', 'not_needed') then jsonb_build_object('finished_at', now()) else '{}'::jsonb end
                       || case when v_state = 'not_needed' then jsonb_build_object('not_needed', v_work) else '{}'::jsonb end)
       where id = r.id;
    elsif s->>'status' = 'running' then
      v_state := case
        when s->'ref'->>'kind' = 'job' then (select case when j.state = 'done' and security.pipeline_num_v1('tasks.lane_hold_on', 0) >= 1  -- CF-247 IQ-00064: done with work unfinished is not done
                                                                   and j.kind = any (security.pipeline_list_v1('tasks.hold_kinds', '["course_page_find", "scholarship_provider_scan", "provider_fill"]'))
                                                                   and jsonb_typeof(j.result->'done') = 'number' and jsonb_typeof(j.result->'total') = 'number'
                                                                   and (j.result->>'done')::numeric < (j.result->>'total')::numeric then 'failed'
                                                    when j.state in ('done') then 'done'
                                                    when j.state = 'cancelled' and j.result->>'end_state' = 'not_needed' then 'not_needed'  -- CF-247 IQ-00066
                                                    when j.state in ('failed', 'cancelled') then j.state end
                                               from pipeline.admin_jobs j where j.id = (s->'ref'->>'id')::uuid)
        when s->'ref'->>'kind' = 'onboarding' then (select case when o.status in ('waiting_admit', 'done', 'scholarships') then 'done' when o.status = 'stopped' then 'stopped' when o.status = 'cancelled' then 'cancelled' end
                                                      from pipeline.provider_onboarding o where o.id = (s->'ref'->>'id')::uuid) end;
      if v_state is null and (s->>'started_at')::timestamptz < now() - make_interval(hours => v_max)
         -- CF-247 IQ-00064: not while its task of tasks.hold_kinds is open (that task is bounded by tasks.lane_hold_max_hours)
         and not (s->'ref'->>'kind' = 'job' and security.pipeline_num_v1('tasks.lane_hold_on', 0) >= 1
                  and exists (select 1 from pipeline.admin_jobs j where j.id = (s->'ref'->>'id')::uuid and j.state in ('queued', 'running')
                                 and j.kind = any (security.pipeline_list_v1('tasks.hold_kinds', '["course_page_find", "scholarship_provider_scan", "provider_fill"]')))) then
        v_state := 'timed_out'; end if;
      if v_state is not null then
        update pipeline.enrich_plan_runs set updated_at = now(),
               steps = jsonb_set(steps, array[i::text], (steps->i) || jsonb_build_object('status', v_state, 'finished_at', now(),
                         'note', case v_state when 'stopped' then 'onboarding stopped: ' || coalesce((select o.stop_reason from pipeline.provider_onboarding o where o.id = (s->'ref'->>'id')::uuid), '')
                                              -- CF-247 IQ-00066: a task ended not needed gives the step its reason
                                              when 'not_needed' then (select left(coalesce(j.result->>'note', 'Not needed'), 300) from pipeline.admin_jobs j where j.id = (s->'ref'->>'id')::uuid)
                                              when 'timed_out' then 'still running after ' || v_max || ' hours; the task carries on'
                                              -- CF-247 IQ-00064: a failed or cancelled task's reason is the step's note
                                              when 'failed' then case when s->'ref'->>'kind' = 'job' and security.pipeline_num_v1('tasks.lane_hold_on', 0) >= 1 then
                                                (select left(case when j.state = 'done' then 'ended done with ' || ((j.result->>'total')::numeric - (j.result->>'done')::numeric) || ' of '
                                                                                             || (j.result->>'total') || ' items unprocessed (IQ-00064): ' else '' end
                                                             || coalesce(nullif(j.error, ''), j.result->>'note', 'the task ' || j.state), 300)
                                                   from pipeline.admin_jobs j where j.id = (s->'ref'->>'id')::uuid) end
                                              when 'cancelled' then case when s->'ref'->>'kind' = 'job' and security.pipeline_num_v1('tasks.lane_hold_on', 0) >= 1 then
                                                (select left(coalesce(nullif(j.error, ''), j.result->>'note', 'the task was cancelled'), 300) from pipeline.admin_jobs j where j.id = (s->'ref'->>'id')::uuid) end end))
         where id = r.id;
      end if;
      if security.pipeline_num_v1('tasks.lane_hold_on', 0) >= 1 and s->'ref'->>'kind' = 'job' then
        if v_state in ('failed', 'timed_out', 'cancelled') then
          -- CF-247 IQ-00064: an ended step keeps its remaining items and its restart eligibility
          update pipeline.enrich_plan_runs x set steps = jsonb_set(x.steps, array[i::text], (x.steps->i) - 'held'
                   || jsonb_build_object('restart', security.plan_step_restart_v1(x.steps->i))
                   || coalesce((select jsonb_build_object('remaining', (j.result->>'total')::numeric - (j.result->>'done')::numeric) from pipeline.admin_jobs j
                                 where j.id = (s->'ref'->>'id')::uuid and jsonb_typeof(j.result->'done') = 'number' and jsonb_typeof(j.result->'total') = 'number'
                                   and (j.result->>'done')::numeric < (j.result->>'total')::numeric), '{}'::jsonb))
           where x.id = r.id;
        elsif v_state is null then
          -- CF-247 IQ-00064: a running step shows its task's hold (reason, remaining items, checkpoint, when it resumes or gives up)
          update pipeline.enrich_plan_runs x set updated_at = now(), steps = jsonb_set(x.steps, array[i::text],
                   case when j.result ? 'held' then (x.steps->i) || jsonb_build_object('held', j.result->'held', 'remaining', j.result->'unprocessed', 'note', j.result->>'note')
                        else (x.steps->i) - 'held' - 'remaining' || case when x.steps->i->>'note' like 'Held:%' then jsonb_build_object('note', null) else '{}'::jsonb end end)
            from pipeline.admin_jobs j
           where x.id = r.id and j.id = (s->'ref'->>'id')::uuid and (x.steps->i->'held') is distinct from (j.result->'held');
        end if;
      end if;
    end if;
    end loop;  -- tracks
  end loop;
  return jsonb_build_object('finished', v_done, 'started', v_started);
end $$;


ALTER FUNCTION "security"."enrich_plan_tick_v1"("p_run" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_plan_v1"("p_provider" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare p record; c jsonb := security.enrich_unit_costs_v1(); f jsonb := security.enrich_provider_fields_v1(p_provider); v_steps jsonb := '[]'::jsonb;
        v_courses int; v_site boolean; v_contact boolean; v_central timestamptz; v_url_missing int; v_onb record; v_ad record; v_items int; v_nopage int;
        v_sch int; v_sch_scan timestamptz; v_work jsonb; v_held jsonb := '[]'::jsonb; v_empty jsonb; v_stalled jsonb;
begin
  select pr.id, coalesce(pr.display_name, pr.canonical_name) name, security.coverage_country(pr.id) cc, nullif(btrim(pr.website), '') website,
         nullif(btrim(pr.phone), '') is not null or nullif(btrim(pr.email), '') is not null has_contact
    into p from catalogue.providers pr where pr.id = p_provider;
  if p.id is null then return null; end if;
  select count(*) into v_courses from catalogue.courses c2 where c2.provider_id = p_provider and c2.lifecycle_status = 'active';
  select s.searched_at into v_central from pipeline.provider_central_search s where s.provider_id = p_provider and s.state = 'done';
  -- 1 website, contacts and central pages
  if p.website is null or not p.has_contact or v_central is null or v_central < now() - interval '30 days' then  -- fixed: the central-page refresh interval (central_refresh_days) is 30
    v_steps := v_steps || jsonb_build_object('step', 'site', 'label', 'Website, contacts and central pages',
      'why', case when p.website is null then 'No website known' when v_central is null then 'Central pages (fees, English, calendar) never searched'
                  when v_central < now() - interval '30 days' then 'Central pages last searched ' || to_char(v_central, 'DD Mon YYYY') else 'No public phone or email' end,
      'fields', jsonb_build_array('p_website', 'p_contact', 'provider_tuition', 'english', 'intakes'), 'est_credits', c->'site_credits', 'est_usd', 0, 'group', 'other');
  end if;
  -- 2 course pages
  v_url_missing := coalesce((f->'official_url'->>'missing')::int, 0);
  if v_url_missing > 0 then
    v_steps := v_steps || jsonb_build_object('step', 'pages', 'label', 'Find course pages',
      'why', v_url_missing || ' of ' || v_courses || ' courses have no course page', 'fields', jsonb_build_array('official_url'),
      'est_credits', round(v_url_missing * (c->>'search_credits_per_course')::numeric, 0), 'est_usd', 0, 'group', 'course_search',
      'blocked', case when p.website is null then 'Needs a website first (step 1)' end);
  end if;
  -- 3 adapter (onboarding) and 4 admit
  select a.enabled, a.admit, coalesce(jsonb_array_length(to_jsonb(a.admit_fields)), 0) n into v_ad from pipeline.uni_adapters a where a.provider_id = p_provider;
  select o.status, o.stop_reason into v_onb from pipeline.provider_onboarding o where o.provider_id = p_provider order by o.created_at desc limit 1;
  if not coalesce(v_ad.admit, false) then
    if v_onb.status = 'waiting_admit' then
      v_steps := v_steps || jsonb_build_object('step', 'admit', 'label', 'Admit the adapter', 'why', 'The adapter passed; a person admits it on Layer 2/3 › Universities',
        'fields', jsonb_build_array('provider_tuition', 'english', 'intakes', 'duration'), 'est_credits', 0, 'est_usd', 0, 'group', 'none', 'person', true);
    else
      v_steps := v_steps || jsonb_build_object('step', 'adapter', 'label', 'Build the adapter (onboarding)',
        'why', case when v_onb.status is null then 'No adapter yet' when v_onb.status = 'stopped' then 'Onboarding stopped: ' || replace(coalesce(v_onb.stop_reason, 'unknown'), '_', ' ')
                    when v_onb.status in ('done', 'cancelled') then 'No admitting adapter' else 'Onboarding running: ' || v_onb.status end,
        'fields', jsonb_build_array('provider_tuition', 'english', 'intakes', 'duration', 'campus'), 'est_credits', c->'adapter_credits', 'est_usd', c->'adapter_usd', 'group', 'reads',
        'running', v_onb.status is not null and v_onb.status not in ('done', 'cancelled', 'stopped', 'waiting_admit'),
        'blocked', case when p.website is null then 'Needs a website first (step 1)' end);
    end if;
  end if;
  -- 5 fields Enrich fields fills
  select count(*) into v_items from (
    select 1 from catalogue.courses c3 cross join unnest(array['campus', 'duration', 'level', 'delivery', 'field_of_study', 'international']) x(fld)
     where c3.provider_id = p_provider and c3.lifecycle_status = 'active'
       and case x.fld when 'campus' then not exists (select 1 from catalogue.course_campuses k where k.course_id = c3.id)
                      when 'duration' then c3.duration_value is null when 'level' then c3.study_level_id is null
                      when 'delivery' then nullif(btrim(c3.delivery_mode), '') is null when 'field_of_study' then c3.primary_field_id is null
                      else c3.open_to_international is null end
       and not security.enrich_item_held_v1(c3.id, x.fld)) z;  -- held: tried on the same page already (until the page changes or gaps.recheck_days)
  if v_items > 0 then
    select count(*) into v_nopage from catalogue.courses c4 where c4.provider_id = p_provider and c4.lifecycle_status = 'active'
       and not exists (select 1 from pipeline.coverage_course_pages g where g.course_id = c4.id and g.evidence_id is not null);
    v_steps := v_steps || jsonb_build_object('step', 'fields', 'label', 'Fill missing fields (stored pages, AI, new reads)',
      'why', v_items || ' missing values in duration, delivery, campus, level, field of study or international not yet tried on the current page',
      'fields', jsonb_build_array('duration', 'delivery', 'campus', 'campus_city', 'level', 'field_of_study', 'international'),
      'est_credits', least(v_nopage, v_items), 'est_usd', round(v_items * (c->>'enrich_usd_per_item')::numeric, 3), 'group', 'reads');
  end if;
  -- 6 scholarships
  select count(*) into v_sch from scholarship.scholarships s where s.provider_id = p_provider and s.lifecycle_status = 'active';
  select max(j.created_at) into v_sch_scan from pipeline.admin_jobs j where j.kind = 'scholarship_provider_scan' and j.scope = p_provider::text;
  if v_sch = 0 and (v_sch_scan is null or v_sch_scan < now() - interval '30 days') then  -- fixed: the scholarship cap period is 30 days
    -- CF-247 IQ-00066 (plans.step_needs_work_on): proposed only when the scan has eligible work now; otherwise listed as not proposed, with why
    v_work := case when security.pipeline_num_v1('plans.step_needs_work_on', 0) >= 1 then security.plan_step_work_v1(p_provider, 'scholarships') end;
    if not coalesce((v_work->>'work')::boolean, true) then
      v_held := v_held || jsonb_build_object('step', 'scholarships', 'label', 'Find and read scholarships', 'code', v_work->>'code', 'reason', v_work->>'reason');
    else
    v_steps := v_steps || jsonb_build_object('step', 'scholarships', 'label', 'Find and read scholarships',
      'why', case when v_sch_scan is null then 'No scholarships and never searched' else 'No scholarships; last searched ' || to_char(v_sch_scan, 'DD Mon YYYY') end,
      'fields', jsonb_build_array('p_scholarships'), 'est_credits', c->'scholarship_credits', 'est_usd', c->'scholarship_usd', 'group', 'scholarships',
      'blocked', case when p.website is null then 'Needs a website first (step 1)' end);
    end if;
  end if;
  -- CF-247 ops D (P0 mandate 15:37 §7, IQ-00066): repeated empty cycles. The automatic planner (no person behind the call) is not offered
  -- the steps of a university whose last plans.empty_cycles_max plans moved no data and nothing changed since (security.plan_empty_cycles_v1);
  -- they are listed under not_proposed with the reason. A person's Run now sees the steps and the notice.
  -- CF-247 ENG IQ-00072 (8 Nov 2026): the automatic planner is not offered "Find course pages" and "Build the adapter" of a university whose onboarding is stuck and unchanged
  -- (security.plan_stalled_onboarding_v1); they are listed under not_proposed with the reason. The other steps and a person's Run now are unchanged.
  v_stalled := security.plan_stalled_onboarding_v1(p_provider);
  if v_stalled is not null and auth.uid() is null and exists (select 1 from jsonb_array_elements(v_steps) x where x->>'step' in ('pages', 'adapter')) then
    v_held := v_held || (select jsonb_agg(jsonb_build_object('step', x->>'step', 'label', x->>'label', 'code', 'onboarding_stalled', 'reason', v_stalled->>'reason')) from jsonb_array_elements(v_steps) x where x->>'step' in ('pages', 'adapter'));
    v_steps := coalesce((select jsonb_agg(x) from jsonb_array_elements(v_steps) x where x->>'step' not in ('pages', 'adapter')), '[]'::jsonb);
  end if;
  v_empty := security.plan_empty_cycles_v1(p_provider, (select coalesce(sum((v->>'missing')::int), 0) from jsonb_each(f) e(k, v)));
  if v_empty is not null and auth.uid() is null and jsonb_array_length(v_steps) > 0 then
    v_held := v_held || (select jsonb_agg(jsonb_build_object('step', x->>'step', 'label', x->>'label', 'code', 'repeated_empty', 'reason', v_empty->>'reason')) from jsonb_array_elements(v_steps) x);
    v_steps := '[]'::jsonb;
  end if;
  return jsonb_build_object('provider_id', p.id, 'name', p.name, 'country', p.cc, 'website', p.website,
    'courses', (select count(*) from catalogue.courses c5 where c5.provider_id = p_provider and c5.lifecycle_status = 'active'),
    'fields', f, 'missing', (select coalesce(sum((v->>'missing')::int), 0) from jsonb_each(f) e(k, v)),
    'steps', v_steps, 'not_proposed', v_held, 'empty_cycles', v_empty,
    'est_credits', (select coalesce(sum((x->>'est_credits')::numeric), 0) from jsonb_array_elements(v_steps) x),
    'est_usd', (select coalesce(round(sum((x->>'est_usd')::numeric), 3), 0) from jsonb_array_elements(v_steps) x),
    'unit_costs', c,
    'open_run', (select to_jsonb(r) - 'steps' || jsonb_build_object('steps', r.steps) from pipeline.enrich_plan_runs r where r.provider_id = p_provider and r.state in ('queued', 'running')));
end $$;


ALTER FUNCTION "security"."enrich_plan_v1"("p_provider" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_provider_fields_v1"("p_provider" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- filled and missing values per field for one university (the hourly coverage build), fields with a reader only
  select coalesce(jsonb_object_agg(a.attribute, jsonb_build_object('filled', a.f, 'missing', a.m)), '{}'::jsonb)
    from (select x.attribute, count(*) filter (where x.state = 'admitted') f, count(*) filter (where x.state <> 'admitted') m
            from pipeline.course_attribute_coverage x join pipeline.field_register r on r.field = x.attribute and r.reader in ('coverage', 'enrich')
           where x.provider_id = p_provider group by 1) a
$$;


ALTER FUNCTION "security"."enrich_provider_fields_v1"("p_provider" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_siblings_v1"("p_item" bigint) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.field_enrich_items%rowtype; j pipeline.admin_jobs%rowtype; v_cc text; v_fields text[]; v_auto boolean; f text; v_n int := 0; v_k int;
        v_max int := greatest(1, security.pipeline_num_v1('enrich.multi_field_max_per_page', 8)::int);
        v_text_cap int := security.pipeline_num_v1('enrich.course_text_items_per_day', 500)::int;
begin
  if security.pipeline_num_v1('enrich.multi_field_on', 1) < 1 then return 0; end if;
  select * into i from pipeline.field_enrich_items where id = p_item;
  if i.id is null or i.course_id is null or i.source is distinct from 'ai_stored' or i.storage_path is null or i.state <> 'ai' then return 0; end if;
  select * into j from pipeline.admin_jobs where id = i.job_id;
  select k.iso_alpha2::text into v_cc from catalogue.providers p join ref.countries k on k.id = p.country_id where p.id = i.provider_id;
  v_auto := coalesce((j.args->>'standing')::boolean, false) or coalesce(j.args->>'plan_mode' = 'auto', false);
  v_fields := array(select jsonb_array_elements_text(case when jsonb_typeof(security.toolset_setting('pipeline', 'enrich.multi_field_fields')) = 'array'
                                                          then security.toolset_setting('pipeline', 'enrich.multi_field_fields') else '[]'::jsonb end));
  -- a task a person started keeps to the fields they chose
  if not v_auto then
    v_fields := array(select x from unnest(v_fields) x where x = any (array(select jsonb_array_elements_text(case when jsonb_typeof(j.args->'fields') = 'array' then j.args->'fields' else '[]'::jsonb end))));
  end if;
  foreach f in array v_fields loop
    exit when v_n >= v_max;
    continue when f = i.field;
    continue when not exists (select 1 from security.enrich_fields_v1() e where e.field = f and e.level = 'course' and 'ai_stored' = any (e.sources));
    continue when not ('ai_stored' = any (coalesce(security.field_sources_for_v1(v_cc, f), '{}'::text[])));
    continue when not security.enrich_course_field_missing_v1(i.course_id, f);
    continue when exists (select 1 from pipeline.manual_locks lk where lk.entity = 'course' and lk.entity_id = i.course_id and lk.field in (f, 'all'));
    continue when exists (select 1 from pipeline.field_enrich_items o where o.job_id = i.job_id and o.provider_id = i.provider_id and o.course_id = i.course_id and o.field = f);
    continue when security.enrich_item_in_flight_v1(i.provider_id, i.course_id, f);
    -- D2: an open absence that is not due again, or a verified negative on this very content, is not read again
    continue when exists (select 1 from pipeline.course_field_absence a where a.course_id = i.course_id and a.field = f and a.resolved_at is null)
                  and not security.field_absence_due_v1(i.course_id, f, i.evidence_id);
    continue when security.field_absence_unchanged_v1(i.course_id, f, i.evidence_id);
    -- the reader's own rule: the same copy did not state it before (enrich_fields_slice_v1)
    continue when exists (select 1 from pipeline.field_enrich_items o where o.course_id = i.course_id and o.field = f and o.evidence_id = i.evidence_id and o.state = 'skipped'
                            and o.reason in ('the page does not state it', 'the page names no campus', 'only a site-wide line mentions international', 'no campus named on the page'));
    -- description and deadline: the standing daily limit counts these too
    continue when f in ('description', 'deadline') and v_auto and coalesce(j.args->>'standing', 'false') = 'true'
                  and (select count(*) from pipeline.field_enrich_items e join pipeline.admin_jobs j2 on j2.id = e.job_id
                        where e.field = f and e.created_at > now() - interval '1 day' and coalesce((j2.args->>'standing')::boolean, false)) >= v_text_cap;  -- fixed: the cap is a day's
    insert into pipeline.field_enrich_items(job_id, provider_id, course_id, field, state, source, tried, storage_path, evidence_id)
    values (i.job_id, i.provider_id, i.course_id, f, 'ai', 'ai_stored', array['ai_stored'], i.storage_path, i.evidence_id)
    on conflict do nothing;
    get diagnostics v_k = row_count;  -- the item gate (held courses) may refuse it
    if v_k > 0 then
      v_n := v_n + 1;
      if f = 'campus' then  -- a campus is linked through the university's campus list, as in the standing queue
        insert into pipeline.field_enrich_items(job_id, provider_id, course_id, field, state) values (i.job_id, i.provider_id, null, 'campus_list', 'waiting') on conflict do nothing;
      end if;
    end if;
  end loop;
  return v_n;
end $$;


ALTER FUNCTION "security"."enrich_siblings_v1"("p_item" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."enrich_siblings_v1"("p_item" bigint) IS 'CF-247 Release B (mandate 3 Nov 2026 13:09 §6 priority 2): when the reader takes a course''s stored page for one field, adds the course''s other missing fields (enrich.multi_field_fields, at most enrich.multi_field_max_per_page) to the same task on the same copy: the country''s source rules, locks, holds, items in progress, open absences not yet due, verified negatives on the same content, a person''s chosen fields and the standing daily limit for description and deadline are kept. Called by enrich_fields_slice_v1.';



CREATE OR REPLACE FUNCTION "security"."enrich_unit_costs_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- what each kind of step actually used, last 30 days (estimates follow the platform, nothing is typed in)
  -- 10 Nov 2026 (IQ-00355): the usage rows are summed per purpose and provider FIRST and the purpose group is worked out on those few rows, not on every one of
  -- the ~110,000 rows of the window (the same figures, about thirty times faster); the automatic planner calls this once for every university it looks at
  with a as (select x.purpose, x.provider_id, sum(x.units) units, count(*) n from pipeline.coverage_vendor_usage x where x.at > now() - interval '30 days' group by x.purpose, x.provider_id),  -- fixed: estimate window
       u as (select security.fc_purpose_group_v1(a.purpose) g, a.purpose, a.units, a.n, a.provider_id from a)
  select jsonb_build_object(
    'site_credits', round(coalesce((select sum(units) / nullif(count(distinct provider_id), 0) from u where g in ('other', 'central')), 0), 1),
    'search_credits_per_course', round(coalesce((select sum(units) / nullif(sum(n), 0) from u where purpose = 'course_link_search'), 0), 2),
    'adapter_credits', round(coalesce((select sum(units) / nullif(count(distinct provider_id), 0) from u where g = 'reads'), 0), 1),
    'scholarship_credits', round(coalesce((select sum(units) / nullif(count(distinct provider_id), 0) from u where g = 'scholarships'), 0), 1),
    'enrich_usd_per_item', coalesce((select round(avg(coalesce(e.cost_usd, 0)), 5) from pipeline.field_enrich_items e where e.updated_at > now() - interval '30 days' and e.state in ('filled', 'skipped', 'review', 'failed')), 0),
    'adapter_usd', coalesce((select round(sum(d.cost_usd) / nullif(count(distinct d.provider_id), 0), 4) from pipeline.uni_adapter_drafts d where d.created_at > now() - interval '30 days'), 0),
    'scholarship_usd', coalesce((select round(sum(s.cost_usd) / nullif(count(distinct s.provider_id), 0), 4) from pipeline.scholarship_ai_extractions s where s.at > now() - interval '30 days'), 0))
$$;


ALTER FUNCTION "security"."enrich_unit_costs_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrich_worker_health_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
           'window_minutes', security.pipeline_num_v1('integration.hidden_error_window_minutes', 120)::int,
           'calls', count(*),
           'ok', count(*) filter (where r.id is not null and not coalesce(f.failed, false)),
           'failed', count(*) filter (where r.id is not null and coalesce(f.failed, false)),
           'in_flight', count(*) filter (where r.id is null and l.created_at >= now() - interval '3 minutes'),   -- fixed: the open-call window security.enrich_ai_fire_v1 uses
           'no_answer_recorded', count(*) filter (where r.id is null and l.created_at < now() - interval '3 minutes'))
    from pipeline.edge_request_log l
    left join net._http_response r on r.id = l.request_id
    left join lateral (select (coalesce(r.status_code, 0) >= 400 or r.timed_out is true or r.error_msg is not null
                               or (coalesce(r.status_code, 0) < 300 and left(r.content, 2000) ~ '"ok"\s*:\s*false')) failed) f on true   -- the integration yield check's test
   where l.function_name = 'coverage-sweep' and l.mode = 'enrich_ai'
     and l.created_at > now() - make_interval(mins => security.pipeline_num_v1('integration.hidden_error_window_minutes', 120)::int) $$;


ALTER FUNCTION "security"."enrich_worker_health_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."enrich_worker_health_v1"() IS 'CF-247 IQ-00053: the enrich_ai worker calls of the last integration.hidden_error_window_minutes minutes: ok, failed, in flight, no recorded answer. Read-only; shown in the Enrich task progress.';



CREATE OR REPLACE FUNCTION "security"."enrichment_flags_first_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  new.first_flagged_at := case when tg_op = 'INSERT' then coalesce(new.first_flagged_at, new.flagged_at)
                               else coalesce(old.first_flagged_at, new.first_flagged_at, old.flagged_at, new.flagged_at) end;
  return new;
end $$;


ALTER FUNCTION "security"."enrichment_flags_first_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrichment_flags_log_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if coalesce(current_setting('cf.flag_fn', true), '') = '1' then return null; end if;  -- the flag functions write their own history
  if tg_op = 'INSERT' then
    insert into pipeline.enrichment_flag_events(flag_id, action, actor, actor_kind, reason, evidence)
    values (new.id, case when new.state = 'raised' then 'raised' else 'released' end, coalesce(new.source, 'unknown'), 'auto', new.reason, new.evidence);
  elsif new.state is distinct from old.state then
    insert into pipeline.enrichment_flag_events(flag_id, action, actor, actor_kind, reason, evidence)
    values (new.id, case new.state when 'raised' then 're_raised' when 'released' then 'released' else 'counted' end, coalesce(new.source, 'unknown'), 'auto', new.reason, new.evidence);
  end if;
  return null;
end $$;


ALTER FUNCTION "security"."enrichment_flags_log_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrichment_flags_refresh_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tail int := 0; v_nf int := 0; v_cap int := security.retry_cap_v1('ai_match'); v_on boolean := security.pipeline_num_v1('enrich.focus_top_n', 50) > 0; v_off int := 0;
begin
  -- Australian courses of providers outside the focus list that still lack a course page, English or intakes: not searched further
  if v_on then
    insert into pipeline.enrichment_flags(entity, entity_key, provider_id, field, reason_code, reason, source)
    with pv as materialized (select distinct d0.provider_id pid from search.course_documents d0 where d0.country_code = 'AU'),
    fp as materialized (select pv.pid from pv where not security.enrich_focus_v1(pv.pid))  -- 31 Oct 2026 (StudySearch F1): once per provider, not once per course
    select 'course', d.course_id::text, d.provider_id, 'course_page', 'outside_focus',
           'Not searched further: the provider is outside the top Australian providers by gaps (Pipeline settings › Waste rules); register data only', 'waste-guard'
      from search.course_documents d
     where d.country_code = 'AU' and (d.official_course_url is null or not d.has_english or not d.has_intake)
       and d.provider_id in (select fp.pid from fp)
    on conflict (entity, entity_key, field, reason_code) do update set cleared_at = null where pipeline.enrichment_flags.cleared_at is not null;
    get diagnostics v_tail = row_count;
  end if;
  with pv as materialized (select distinct f0.provider_id pid from pipeline.enrichment_flags f0
                             where f0.reason_code = 'outside_focus' and f0.cleared_at is null and f0.provider_id is not null),
  fp as materialized (select pv.pid from pv where security.enrich_focus_v1(pv.pid))  -- 31 Oct 2026 (F1): once per provider
  update pipeline.enrichment_flags f set cleared_at = now()
   where f.reason_code = 'outside_focus' and f.cleared_at is null
     and (not v_on or (case when f.provider_id is null then security.enrich_focus_v1(f.provider_id) else f.provider_id in (select fp.pid from fp) end));
  -- courses whose page was not found after the useful AI attempts
  insert into pipeline.enrichment_flags(entity, entity_key, provider_id, field, reason_code, reason, source)
  with pv as materialized (select distinct q0.provider_id pid from pipeline.coverage_ai_match q0),
  so as materialized (select pv.pid from pv where not security.course_search_off_v1(pv.pid))  -- 31 Oct 2026 (F1): once per provider, not once per AI-match row
  select 'course', q.course_id::text, max(q.provider_id::text)::uuid, 'official_url', 'page_not_found',
         format('No course page found after %s AI attempt(s) (no further candidates, or later attempts rarely succeed: Pipeline settings › Waste rules)', count(*)), 'waste-guard'
    from pipeline.coverage_ai_match q
   where not exists (select 1 from pipeline.coverage_course_pages p where p.course_id = q.course_id and p.status = 'bound')
     and q.provider_id in (select so.pid from so)  -- 22 Oct 2026 (NZ review fix 8): the provider flag covers these
   group by q.course_id
  having (count(*) >= v_cap or bool_or(q.state = 'no_candidates')) and bool_and(q.state in ('none', 'no_candidates', 'error'))
  on conflict (entity, entity_key, field, reason_code) do nothing;
  get diagnostics v_nf = row_count;
  update pipeline.enrichment_flags f set cleared_at = now()
   where f.reason_code = 'page_not_found' and f.cleared_at is null
     and exists (select 1 from pipeline.coverage_course_pages p where p.course_id::text = f.entity_key and p.status = 'bound');
  -- 22 Oct 2026 (NZ review fix 8): one flag on the provider when course search is off for it, instead of one per course
  insert into pipeline.enrichment_flags(entity, entity_key, provider_id, field, reason_code, reason, source)
  select 'provider', p.id::text, p.id, 'course_page', 'course_pages_not_listed',
         'Course pages are not searched: the provider''s own site lists too few course pages, or its programmes have none (Pipeline settings › Course pages). Add pages by hand or use Search again.', 'waste-guard'
    from catalogue.providers p
   where exists (select 1 from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active')
     and security.course_search_off_v1(p.id)
  on conflict (entity, entity_key, field, reason_code) do update set cleared_at = null where pipeline.enrichment_flags.cleared_at is not null;
  get diagnostics v_off = row_count;
  update pipeline.enrichment_flags f set cleared_at = now()
   where f.reason_code = 'course_pages_not_listed' and f.cleared_at is null and not security.course_search_off_v1(f.provider_id);
  with pv as materialized (select distinct f0.provider_id pid from pipeline.enrichment_flags f0
                             where f0.reason_code = 'page_not_found' and f0.entity = 'course' and f0.cleared_at is null and f0.provider_id is not null),
  so as materialized (select pv.pid from pv where security.course_search_off_v1(pv.pid))  -- 31 Oct 2026 (F1): once per provider
  update pipeline.enrichment_flags f set cleared_at = now()
   where f.reason_code = 'page_not_found' and f.entity = 'course' and f.cleared_at is null
     and (case when f.provider_id is null then security.course_search_off_v1(f.provider_id) else f.provider_id in (select so.pid from so) end);
  -- 22 Oct 2026 (Platform Admin 13:28, fix 1): providers in the check-first countries without a site map get one (pending) before any search
  insert into pipeline.coverage_provider_discovery(provider_id, website, status)
  select p.id, p.website, 'pending' from catalogue.providers p
   where p.lifecycle_status = 'active' and p.publication_status = 'published' and nullif(btrim(p.website), '') is not null
     and not security.third_party_host_v1(p.website) and security.site_not_checked_v1(p.id)
     and exists (select 1 from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active')
  on conflict (provider_id) do nothing;
  -- fix 3: pages whose site refuses automated reading (robots.txt) are listed for a person, one flag per provider
  insert into pipeline.enrichment_flags(entity, entity_key, provider_id, field, reason_code, reason, source)
  select 'provider', g.provider_id::text, g.provider_id, 'course_page', 'pages_refuse_reading',
         format('%s course page(s) on this site refuse automated reading (robots.txt); add them by hand on each course', count(*)), 'waste-guard'
    from pipeline.coverage_course_pages g where g.status = 'bound' and g.read_status = 'robots_disallowed' group by g.provider_id
  on conflict (entity, entity_key, field, reason_code) do update set cleared_at = null, reason = excluded.reason
   where pipeline.enrichment_flags.cleared_at is not null or pipeline.enrichment_flags.reason is distinct from excluded.reason;
  update pipeline.enrichment_flags f set cleared_at = now()
   where f.reason_code = 'pages_refuse_reading' and f.cleared_at is null
     and not exists (select 1 from pipeline.coverage_course_pages g where g.provider_id = f.provider_id and g.status = 'bound' and g.read_status = 'robots_disallowed');
  return jsonb_build_object('outside_focus', v_tail, 'page_not_found', v_nf, 'course_pages_not_listed', v_off);
end $$;


ALTER FUNCTION "security"."enrichment_flags_refresh_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."enrichment_flags_sync_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if coalesce(current_setting('cf.flag_fn', true), '') = '1' then new.updated_at := now(); return new; end if;  -- the flag functions keep their own state
  if tg_op = 'INSERT' then
    new.state := case when new.cleared_at is null then 'raised' else 'released' end;
    if new.state = 'released' then new.released_at := new.cleared_at; new.release_kind := 'auto'; new.released_by := new.source; end if;
  elsif new.cleared_at is distinct from old.cleared_at then
    if new.cleared_at is null then
      if old.release_kind = 'person' then new.cleared_at := old.cleared_at; return new; end if;  -- a person's release stands against automatic re-raising
      new.state := 'raised'; new.tries := old.tries + 1; new.released_at := null;
    else
      new.state := 'released'; new.released_at := new.cleared_at; new.release_kind := coalesce(new.release_kind, 'auto'); new.released_by := coalesce(new.released_by, new.source);
    end if;
  end if;
  new.updated_at := now();
  return new;
end $$;


ALTER FUNCTION "security"."enrichment_flags_sync_v1"() OWNER TO "postgres";


