COMMENT ON FUNCTION "security"."entry_completeness_required_v1"("p_provider" "uuid") IS 'CF-247 AER v1.1: whether a provider''s entry-matrix reads must pass the source-anchored completeness guard (setting entry.completeness_providers).';



CREATE OR REPLACE FUNCTION "security"."entry_course_label_levels_v1"("p" "text") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select array(select distinct l from (
    select unnest(case when k ~ '\mbachelor\M' then array['BA', 'BH'] end) l
    union all select unnest(case when k ~ '\mmaster\M' then array['MA', 'MC', 'MR', 'ME'] end)
    union all select unnest(case when k ~ '\mdoctor\M' then array['DR', 'PD'] end)
    union all select unnest(case when k ~ '\mgraduate diploma\M' then array['GD'] end)
    union all select unnest(case when k ~ '\mgraduate certificate\M' then array['GC'] end)) z where l is not null)
  from (select security.entry_course_title_key_v1(p) k) x
$$;


ALTER FUNCTION "security"."entry_course_label_levels_v1"("p" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."entry_course_label_levels_v1"("p" "text") IS 'F-AER.08: the study levels (ref.study_levels.short_code) a printed course label names (Bachelor: BA, BH; Master: MA, MC, MR, ME; Doctor: DR, PD; Graduate diploma, certificate)';



CREATE OR REPLACE FUNCTION "security"."entry_course_link_suggest_v1"("p_link" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare l catalogue.entry_course_links%rowtype; v_cand jsonb;
        v_n int := security.pipeline_num_v1('aer.course_link_candidates', 5)::int; v_min numeric := security.pipeline_num_v1('aer.course_link_candidate_min_overlap', 0.5);
begin
  select * into l from catalogue.entry_course_links where id = p_link for update;
  if l.id is null or l.state <> 'unresolved' then return coalesce(l.candidates, '[]'::jsonb); end if;
  -- the provider's courses whose titles share most words with the label: suggestions for a person, never a link
  select coalesce(jsonb_agg(jsonb_build_object('course_id', z.id, 'title', z.canonical_title, 'code', z.course_code, 'level', z.short_code, 'overlap', round(z.o, 2),
                                               'why', case when z.k = l.label_key then 'same title, another course' else 'shares title words' end) order by z.o desc, z.canonical_title), '[]'::jsonb)
    into v_cand
    from (select c.id, c.canonical_title, c.course_code, s.short_code, k.k,
                 (select count(*) from (select unnest(string_to_array(k.k, ' ')) intersect select unnest(string_to_array(l.label_key, ' '))) i)::numeric
                 / greatest((select count(*) from (select unnest(string_to_array(k.k, ' ')) union select unnest(string_to_array(l.label_key, ' '))) u), 1) o
            from catalogue.courses c left join ref.study_levels s on s.id = c.study_level_id
            cross join lateral (select security.entry_course_title_key_v1(c.canonical_title) k) k
           where c.provider_id = l.provider_id and c.lifecycle_status = 'active'
           order by 6 desc limit v_n) z
   where z.o >= v_min or z.k = l.label_key;
  update catalogue.entry_course_links set candidates = v_cand, evidence = evidence || jsonb_build_object('suggested_at', now()) where id = l.id;
  return v_cand;
end $$;


ALTER FUNCTION "security"."entry_course_link_suggest_v1"("p_link" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."entry_course_link_suggest_v1"("p_link" "uuid") IS 'F-AER.08 decision 2 step 3: suggested catalogue courses for an unresolved course label (shared title words; suggestions only), made when a person opens it in Layer 4';



CREATE OR REPLACE FUNCTION "security"."entry_course_link_tg"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.course_id is null and nullif(btrim(new.course_label), '') is not null then
    new.course_id := security.entry_course_link_v1(new.provider_id, new.course_label, new.conditions->>'cricos_code', new.source_id, new.quote);
  end if;
  return new;
end $$;


ALTER FUNCTION "security"."entry_course_link_tg"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."entry_course_link_v1"("p_provider" "uuid", "p_label" "text", "p_cricos" "text" DEFAULT NULL::"text", "p_source" "uuid" DEFAULT NULL::"uuid", "p_quote" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_key text := security.entry_course_title_key_v1(p_label); l catalogue.entry_course_links%rowtype; v_ids uuid[]; v_code text; v_levels text[]; v_method text;
begin
  if p_provider is null or v_key is null then return null; end if;
  -- the stored decision first (one index lookup): a confirmed link is reused, a person's "no catalogue course" stands
  select * into l from catalogue.entry_course_links where provider_id = p_provider and label_key = v_key;
  if l.state = 'confirmed' then return l.course_id; end if;
  if l.state = 'rejected' then return null; end if;
  if security.pipeline_num_v1('aer.course_link_on', 1) < 1 then return null; end if;
  v_code := upper(btrim(coalesce(p_cricos, '')));
  -- an unresolved label is looked at again only when its code differs or the provider's catalogue changed since
  if l.state = 'unresolved' and v_code = coalesce(l.cricos_code, '')
     and not exists (select 1 from catalogue.courses c where c.provider_id = p_provider and c.updated_at > l.updated_at) then return null; end if;
  -- 1 the CRICOS code printed on the row, at this provider, one active course
  if v_code ~ '^[0-9]{6}[0-9A-Z]$' then
    v_ids := array(select c.id from catalogue.courses c where c.provider_id = p_provider and c.lifecycle_status = 'active' and upper(btrim(c.course_code)) = v_code);
    if cardinality(v_ids) = 1 then v_method := 'cricos'; end if;
  end if;
  -- 2 the exact title (canonical or display) at this provider, at a level the label names, one active course (courses_title_key_ix, courses_display_title_key_ix)
  v_levels := security.entry_course_label_levels_v1(p_label);
  if v_method is null and cardinality(v_levels) > 0 then
    v_ids := array(select c.id from catalogue.courses c join ref.study_levels s on s.id = c.study_level_id
                    where c.provider_id = p_provider and c.lifecycle_status = 'active' and s.short_code = any (v_levels)
                      and (security.entry_course_title_key_v1(c.canonical_title) = v_key or security.entry_course_title_key_v1(c.display_title) = v_key));
    if cardinality(v_ids) = 1 then v_method := 'title'; end if;
  end if;
  if v_method is not null then
    insert into catalogue.entry_course_links as x (provider_id, label_key, course_label, course_id, state, method, cricos_code, evidence)
    values (p_provider, v_key, left(p_label, 300), v_ids[1], 'confirmed', v_method, nullif(v_code, ''), jsonb_build_object('source_id', p_source, 'quote', left(p_quote, 300)))
    on conflict (provider_id, label_key) do update set course_id = excluded.course_id, state = 'confirmed', method = excluded.method, cricos_code = excluded.cricos_code,
       evidence = excluded.evidence, candidates = '[]'::jsonb, updated_at = now();
    return v_ids[1];
  end if;
  -- 3 no single match: waits for a person; suggestions are made when the label is opened in Layer 4 (security.entry_course_link_suggest_v1)
  insert into catalogue.entry_course_links as x (provider_id, label_key, course_label, state, method, cricos_code, candidates, evidence)
  values (p_provider, v_key, left(p_label, 300), 'unresolved', 'none', nullif(v_code, ''), '[]'::jsonb, jsonb_build_object('source_id', p_source, 'quote', left(p_quote, 300)))
  on conflict (provider_id, label_key) do update set state = 'unresolved', cricos_code = excluded.cricos_code, candidates = '[]'::jsonb, evidence = excluded.evidence, updated_at = now();
  return null;
end $_$;


ALTER FUNCTION "security"."entry_course_link_v1"("p_provider" "uuid", "p_label" "text", "p_cricos" "text", "p_source" "uuid", "p_quote" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."entry_course_link_v1"("p_provider" "uuid", "p_label" "text", "p_cricos" "text", "p_source" "uuid", "p_quote" "text") IS 'F-AER.08 decision 2: the catalogue course of a printed course label (the stored decision; else CRICOS code; else exact title and level, one course only); null when unresolved. Suggestions are made in Layer 4.';



CREATE OR REPLACE FUNCTION "security"."entry_course_payload_v1"("p_course" "uuid", "p_country" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with r as (select * from catalogue.course_entry_requirements x where x.course_id = p_course and x.status = 'active'),
  s as (select r.min_entry_score, r.min_entry_score_basis from r where r.kind = 'minimum_grade' and r.min_entry_score is not null
         order by (r.audience = 'international') desc, r.updated_at desc limit 1)
  select jsonb_build_object(
    'min_score', (select s.min_entry_score from s),
    'min_score_basis', (select s.min_entry_score_basis from s),
    -- StudySearch D4 (31 Oct 2026): every admitted entry score as printed, additive; min_score and min_score_basis are unchanged
    'min_scores', coalesce((select jsonb_agg(jsonb_build_object('score', m.min_entry_score, 'basis', m.min_entry_score_basis, 'audience', m.audience,
                      'scale', m.grade_scale, 'quote', m.quote, 'source_url', m.source_url, 'as_at', m.as_at)
                    order by case m.audience when 'international' then 0 when 'all' then 1 else 2 end, m.min_entry_score_basis, m.min_entry_score, m.quote)
                  from (select distinct on (r.audience, r.min_entry_score_basis, r.min_entry_score, r.quote) r.* from r where r.min_entry_score is not null
                         order by r.audience, r.min_entry_score_basis, r.min_entry_score, r.quote, r.updated_at desc) m), '[]'::jsonb),
    'benchmark_band', (select r.benchmark_band from r where r.benchmark_band is not null and r.audience in ('international', 'all') order by r.updated_at desc limit 1),
    'prerequisites', coalesce((select jsonb_agg(jsonb_build_object('text', r.description, 'quote', r.quote) order by r.created_at) from r where r.kind = 'subject_prerequisite'), '[]'::jsonb),
    'selection_tasks', coalesce((select jsonb_agg(jsonb_build_object('text', r.description, 'quote', r.quote) order by r.created_at) from r where r.kind = 'portfolio_interview'), '[]'::jsonb),
    'requirements_note', (select string_agg(r.description, ' · ' order by r.created_at) from r where r.kind in ('override', 'general_note', 'prior_qualification', 'work_experience')),
    'resolution', case when p_country is null then null else security.entry_resolve_v1(p_course, p_country) end)
$$;


ALTER FUNCTION "security"."entry_course_payload_v1"("p_course" "uuid", "p_country" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."entry_course_payload_v1"("p_course" "uuid", "p_country" "text") IS 'CF-247 Track C Step B (B2): the course payload''s entry object from active course rows, with the five-rule resolution for a country.';



CREATE OR REPLACE FUNCTION "security"."entry_course_title_key_v1"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select nullif(btrim(regexp_replace(regexp_replace(lower(
           regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(coalesce(p, ''),
             '[\^*#†‡]+', ' ', 'g'),
             '\(level [0-9]+\)', ' ', 'gi'),
             '\mB\M\.?(\s)', 'Bachelor of\1', 'g'),
             '\mM\M\.?(\s)', 'Master of\1', 'g'),
             '\mHons\M', 'Honours', 'g'),
             '[/&]', ' and ', 'g'),
             '\mof\s+of\M', 'of', 'gi')),
           '[^a-z0-9]+', ' ', 'g'), '\s+', ' ', 'g')), '')
$$;


ALTER FUNCTION "security"."entry_course_title_key_v1"("p" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."entry_course_title_key_v1"("p" "text") IS 'F-AER.08: a course title in one comparable form (B/M abbreviations, Hons, / and &, footnote marks, "(Level n)"); used only for an exact comparison';



CREATE OR REPLACE FUNCTION "security"."entry_label_levels_v1"("p_label" "text") RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- every level a published label names, each part mapped with the existing mapping (security.entry_level_map_v1)
  select coalesce(array_agg(distinct z.l) filter (where z.l is not null), '{}'::uuid[])
    from (select security.entry_level_map_v1(btrim(part)) l
            from regexp_split_to_table(coalesce(p_label, ''), '\s*(/|,|&|\mand\M|\mor\M)\s*', 'i') part
          union all select security.entry_level_map_v1(p_label)) z
$$;


ALTER FUNCTION "security"."entry_label_levels_v1"("p_label" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."entry_label_levels_v1"("p_label" "text") IS 'CF-247 AER W19 (29 Oct 2026): every study level a published matrix level label names ("Diploma/Associate degrees" gives diploma and associate degree), mapped part by part with security.entry_level_map_v1. Used by the resolver and Resolution inspection.';



CREATE OR REPLACE FUNCTION "security"."entry_level_map_v1"("p_label" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select l.id from ref.study_levels l
   where l.code = case
     when p_label ~* 'phd|doctor' then 'doctorate'
     when p_label ~* 'master|postgrad' then 'masters'
     when p_label ~* 'graduate diploma' then 'graduate_diploma'
     when p_label ~* 'graduate certificate' then 'graduate_certificate'
     when p_label ~* 'associate degree' then 'associate_degree'
     when p_label ~* 'bachelor|degree|undergrad' then 'bachelor'
     when p_label ~* 'advanced diploma' then 'advanced_diploma'
     when p_label ~* 'diploma' then 'diploma'
     when p_label ~* 'foundation|pathway' then 'foundation'
     when p_label ~* 'certificate' then 'certificate'
   end
$$;


ALTER FUNCTION "security"."entry_level_map_v1"("p_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."entry_matrix_attach_allowed_v1"("p_provider" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- security.entry_matrix_enabled_v1 without its "an entry page is already recorded" clause: that clause made the first page of a provider impossible to attach
  select security.pipeline_num_v1('entry.matrix_enabled', 0) >= 1
     and exists (select 1 from catalogue.providers p join ref.countries k on k.id = p.country_id
                  where p.id = p_provider
                    and coalesce(security.toolset_setting('pipeline', 'entry.countries'), '["AU","NZ"]'::jsonb) ? k.iso_alpha2::text)
     and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p_provider)
     and (case when security.aer_schedule_active_v1()
               then exists (select 1 from security.aer_eligible_v1() e where e.provider_id = p_provider and (security.aer_schedule_country_v1(e.country)->>'on')::boolean)
               else jsonb_array_length(coalesce(security.toolset_setting('pipeline', 'entry.providers'), '[]'::jsonb)) = 0
                    or coalesce(security.toolset_setting('pipeline', 'entry.providers'), '[]'::jsonb) ? p_provider::text end)
$$;


ALTER FUNCTION "security"."entry_matrix_attach_allowed_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."entry_matrix_attach_allowed_v1"("p_provider" "uuid") IS 'CF-247 (7 Nov 2026): whether a provider may be given an entry-requirements page: the rule of security.entry_matrix_enabled_v1 without the clause that an entry page is already recorded. Used by security.entry_matrix_attach_v1 and security.entry_source_stored_find_v1.';



CREATE OR REPLACE FUNCTION "security"."entry_matrix_attach_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int := 0; v_max int := security.pipeline_num_v1('entry.attach_per_provider', 3)::int;
begin
  if security.pipeline_num_v1('entry.matrix_enabled', 0) < 1 then return 0; end if;
  insert into pipeline.entry_matrix_sources(provider_id, url, title, rank, found_via)
  -- 13 Nov 2026: ranked as before, then only new pages within the rank limit for a provider with room; the allowed check once per provider
  with x as materialized (
         select s.provider_id, e->>'url' url, left(e->>'title', 200) title,
                row_number() over (partition by s.provider_id order by (e->>'score')::numeric desc, length(e->>'url')) rn
           from pipeline.provider_central_search s, jsonb_array_elements(coalesce(s.found, '[]'::jsonb)) e
          where e->>'kind' = 'entry_requirements' and e->>'url' ~ '^https?://'
            and coalesce((e->>'score')::numeric, 0) >= security.pipeline_num_v1('central.min_suggest_score', 4)),
       n as materialized (
         select x.* from x
          where x.rn <= v_max
            and not exists (select 1 from pipeline.entry_matrix_sources m where m.provider_id = x.provider_id and m.url = x.url)
            and (select count(*) from pipeline.entry_matrix_sources m where m.provider_id = x.provider_id) < v_max),
       ok as materialized (select p.provider_id from (select distinct n.provider_id from n) p where security.entry_matrix_attach_allowed_v1(p.provider_id))
  select n.provider_id, n.url, n.title, n.rn, 'search' from n join ok on ok.provider_id = n.provider_id
  on conflict (provider_id, url) do nothing;
  get diagnostics v_n = row_count;
  return v_n;
end $$;


ALTER FUNCTION "security"."entry_matrix_attach_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."entry_matrix_enabled_v1"("p_provider" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select security.pipeline_num_v1('entry.matrix_enabled', 0) >= 1
     and exists (select 1 from catalogue.providers p join ref.countries k on k.id = p.country_id
                  where p.id = p_provider
                    and coalesce(security.toolset_setting('pipeline', 'entry.countries'), '["AU","NZ"]'::jsonb) ? k.iso_alpha2::text)
     and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p_provider)
     -- AU completion week step 6 (26 Oct 2026): only the providers in entry.providers, when that list is not empty
     -- CF-247 scheduled entry reading (3 Nov 2026): while job aer-scheduled-read is on, eligibility rules replace that list: an AER-eligible provider
     -- (security.aer_eligible_v1) of a country switched on for scheduled reading (security.aer_schedule_country_v1) with an entry page recorded
     and (case when security.aer_schedule_active_v1()
               then exists (select 1 from security.aer_eligible_v1() e where e.provider_id = p_provider and (security.aer_schedule_country_v1(e.country)->>'on')::boolean)
                    and exists (select 1 from pipeline.entry_matrix_sources s where s.provider_id = p_provider)
               else jsonb_array_length(coalesce(security.toolset_setting('pipeline', 'entry.providers'), '[]'::jsonb)) = 0
                    or coalesce(security.toolset_setting('pipeline', 'entry.providers'), '[]'::jsonb) ? p_provider::text end)
$$;


ALTER FUNCTION "security"."entry_matrix_enabled_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."entry_matrix_enabled_v1"("p_provider" "uuid") IS 'CF-247 Track C: the entry matrix reader works on this provider (entry.matrix_enabled on, country in entry.countries, provider published).';



CREATE OR REPLACE FUNCTION "security"."entry_matrix_enqueue_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int;
begin
  insert into pipeline.entry_matrix_runs(provider_id, source_id, content_hash)
  select s.provider_id, s.id, coalesce(s.content_hash, s.evidence_id::text)
    from pipeline.entry_matrix_sources s
   where s.status = 'read' and s.evidence_id is not null and security.entry_matrix_enabled_v1(s.provider_id)
  on conflict (source_id, content_hash) do nothing;
  get diagnostics v_n = row_count;
  return v_n;
end $$;


ALTER FUNCTION "security"."entry_matrix_enqueue_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."entry_matrix_fire_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_att int := 0; v_ref int := 0; v_st int := 0; v_q int := 0; v_due int; v_open int; v_sent int := 0;
begin
  if security.pipeline_num_v1('entry.matrix_enabled', 0) < 1 then return jsonb_build_object('enabled', false); end if;
  v_att := security.entry_matrix_attach_v1();
  -- AER Step B (29 Oct 2026): while PDF tables are read, a parked PDF source of a provider in scope is fetched like any page
  if security.pipeline_num_v1('entry.pdf_enabled', 0) >= 1 then
    update pipeline.entry_matrix_sources f set status = 'found', attempts = 0, error = null, updated_at = now()
     where f.status = 'pdf_step_b' and security.entry_matrix_enabled_v1(f.provider_id);
  end if;
  -- an entry page read longer ago than entry.matrix_refresh_days is fetched again (read again with AI only if it changed)
  update pipeline.entry_matrix_sources f set status = 'found', attempts = 0, updated_at = now()
   where f.status = 'read' and f.read_via <> 'stored'
     and f.read_at < now() - make_interval(days => security.pipeline_num_v1('entry.matrix_refresh_days', 30)::int)
     and security.entry_matrix_enabled_v1(f.provider_id)
     and not security.aer_schedule_active_v1();  -- CF-247 (3 Nov 2026): while job aer-scheduled-read is on it refreshes due pages in bounded batches
  get diagnostics v_ref = row_count;
  v_st := security.entry_matrix_use_stored_v1();
  v_q := security.entry_matrix_enqueue_v1();
  -- 29 Oct 2026: a run whose lease ran out on its last try is closed as failed (the worker stopped without reporting back)
  update pipeline.entry_matrix_runs r set state = 'failed', leased_until = null, updated_at = now(),
         error = left('stopped after ' || r.attempts || ' tries without a reply: ' || coalesce(r.error, 'no error recorded'), 400)
   where r.state = 'leased' and r.leased_until < now() and r.attempts >= security.pipeline_num_v1('entry.matrix_attempts', 3);
  if not security.ai_use_allowed_v1('entry_matrix') then return jsonb_build_object('attached', v_att, 'refetch', v_ref, 'stored', v_st, 'queued', v_q, 'ai', 'stopped'); end if;
  select count(*) into v_due from pipeline.entry_matrix_runs r where (r.state = 'queued' or (r.state = 'leased' and r.leased_until < now()))
     and r.attempts < security.pipeline_num_v1('entry.matrix_attempts', 3);
  v_due := v_due + (select count(*) from pipeline.entry_matrix_sources s where s.status = 'found' and security.entry_matrix_enabled_v1(s.provider_id));
  select count(*) into v_open from pipeline.edge_request_log l where l.function_name = 'coverage-sweep' and l.mode = 'entry_ai' and l.created_at > now() - interval '4 minutes'  -- fixed: fire guard
     and not exists (select 1 from net._http_response h where h.id = l.request_id);
  if v_due > 0 and v_open = 0 then
    perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'entry_ai', 'limit', security.pipeline_num_v1('batch.entry_matrix', 4)::int));
    v_sent := 1;
  end if;
  return jsonb_build_object('attached', v_att, 'refetch', v_ref, 'stored', v_st, 'queued', v_q, 'due', v_due, 'sent', v_sent);
end $$;


ALTER FUNCTION "security"."entry_matrix_fire_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."entry_matrix_gate_v1"("p_run" "uuid", "p_exclude" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.entry_matrix_runs%rowtype; s pipeline.entry_matrix_sources%rowtype; v_ex uuid[] := coalesce(p_exclude, '{}'::uuid[]);
        v_why text[] := '{}'; v_fix boolean := true; v_rows int; v_wait int; v_lost jsonb; v_cov int; v_missing jsonb; v_flag jsonb; v_dup jsonb; v_qc int;
        v_n int := security.pipeline_num_v1('entry.gate_cover_chars', 40)::int; v_m int := security.pipeline_num_v1('entry.gate_cover_min_chars', 12)::int;
        v_ignore jsonb := coalesce(security.toolset_setting('pipeline', 'entry.matrix_gate_ignore_reasons'), '[]'::jsonb);
        v_rank text := (select string_agg('(' || w || ')', '|') from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'entry.matrix_rank_words'), '[]'::jsonb)) w where btrim(w) <> '');
        v_score text := (select string_agg('(' || w || ')', '|') from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'entry.matrix_score_words'), '[]'::jsonb)) w where btrim(w) <> '');
begin
  select * into r from pipeline.entry_matrix_runs where id = p_run;
  if r.id is null then return null; end if;
  if security.pipeline_num_v1('entry.matrix_gate', 1) < 1 then
    return jsonb_build_object('rule', 'D-R3', 'complete', true, 'off', true, 'reasons', '[]'::jsonb);
  end if;
  select * into s from pipeline.entry_matrix_sources where id = r.source_id;
  -- the read is of the source's current stored copy and finished
  if r.state is distinct from 'done' then v_why := v_why || format('the read has not finished (%s)', coalesce(r.state, 'no state')); v_fix := false; end if;
  if s.id is null or r.content_hash is distinct from s.content_hash then
    v_why := v_why || 'the read is not of the source''s current stored copy: read the current copy before deciding'::text; v_fix := false;
  end if;
  -- the reader's own verdict, where it made one
  if coalesce(r.result->'completeness'->>'status', 'not_applicable') not in ('not_applicable', 'complete') then
    v_why := v_why || format('the reader''s completeness check did not pass (%s)', r.result->'completeness'->>'status'); v_fix := false;
  end if;
  -- rows changed since the read: every row the read proposed still waits (admitted or left out by the reviewer)
  select count(*) filter (where m.status = 'proposed'), count(*) filter (where m.status = 'proposed' and not (m.id = any (v_ex))) into v_wait, v_rows
    from catalogue.provider_entry_matrix m where m.run_id = r.id;
  if v_wait is distinct from coalesce(r.rows_admitted, 0) then
    v_why := v_why || format('%s row(s) wait but the read proposed %s: rows changed since the read', v_wait, coalesce(r.rows_admitted, 0)); v_fix := false;
  end if;
  -- dropped published rows that no admitted row covers (left out rows do not cover anything)
  with a as (select lower(regexp_replace(coalesce(m.quote, ''), '[^[:alnum:]]', '', 'g')) fq, m.country_code
               from catalogue.provider_entry_matrix m where m.run_id = r.id and m.status = 'proposed' and not (m.id = any (v_ex))),
       d as (select x, lower(regexp_replace(coalesce(x->>'quote', ''), '[^[:alnum:]]', '', 'g')) fq
               from jsonb_array_elements(coalesce(r.result->'dropped', '[]'::jsonb)) x where not (v_ignore ? coalesce(x->>'reason', ''))),
       dc as (select d.x, exists (select 1 from a where length(d.fq) >= v_m and strpos(a.fq, left(d.fq, v_n)) > 0) cov from d)
  select coalesce(jsonb_agg(jsonb_build_object('reason', x->>'reason', 'country', x->>'country', 'quote', left(x->>'quote', 120))) filter (where not cov), '[]'::jsonb),
         count(*) filter (where cov),
         coalesce((select jsonb_agg(distinct dc2.x->>'country') from dc dc2 where not dc2.cov and coalesce(dc2.x->>'country', '') <> ''
                     and not exists (select 1 from a where a.country_code = upper(dc2.x->>'country'))), '[]'::jsonb)
    into v_lost, v_cov, v_missing from dc;
  if jsonb_array_length(v_lost) > 0 then
    v_why := v_why || format('the reader dropped %s published row(s) that no admitted row covers (%s)%s, so the read is incomplete: replace it with a corrected read, or reject it',
                             jsonb_array_length(v_lost),
                             (select string_agg(k || ' ' || c, ', ') from (select l->>'reason' k, count(*) c from jsonb_array_elements(v_lost) l group by 1 order by 1) z),
                             case when jsonb_array_length(v_missing) > 0 then '; left with no row at all: ' || (select string_agg(c, ', ' order by c) from jsonb_array_elements_text(v_missing) c) else '' end);
    v_fix := false;
  end if;
  -- row-level problems (each can be left out with Approve except)
  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'why', w.why) order by m.id), '[]'::jsonb) into v_flag
    from catalogue.provider_entry_matrix m
    cross join lateral (select array(select (regexp_matches(coalesce(m.quote, ''), '[0-9]+(?:\.[0-9]+)?', 'g'))[1]) nums) n
    cross join lateral (select case
        when m.provider_id is distinct from r.provider_id or m.source_id is distinct from r.source_id or m.content_hash is distinct from r.content_hash
          then 'another provider, source or stored copy'
        -- F-AER.08 (12 Nov 2026, decision 1): every course minimum belongs to exactly one catalogue course
        when m.course_label is not null and m.course_id is null and security.pipeline_num_v1('aer.course_link_on', 1) >= 1
          then 'the course is not linked to a catalogue course (Layer 4 course links)'
        when btrim(coalesce(m.qualification_name, '')) = '' or (v_rank is not null and m.qualification_name ~* v_rank) or (v_score is not null and m.qualification_name ~* v_score)
          then 'qualification named by a column label'
        when m.grade_scale = 'rank' and v_score is not null and coalesce(m.quote, '') ~* v_score
          then 'the provider''s rank is stored as the qualification''s minimum'
        when v_rank is not null and v_score is not null and coalesce(m.min_grade, '') ~* v_rank and coalesce(m.quote, '') ~* v_score
          then 'the provider''s rank is stored as the qualification''s minimum'
        -- a ladder quote printing the rank and the score: the minimum is the score's own cell (the second number when the rank is printed first)
        when v_rank is not null and v_score is not null and m.min_value is not null and coalesce(m.quote, '') ~* v_rank and coalesce(m.quote, '') ~* v_score
             and cardinality(n.nums) = 2
             and m.min_value <> (case when strpos(lower(m.quote), lower(substring(m.quote from '(?i)(' || v_rank || ')')))
                                         < strpos(lower(m.quote), lower(substring(m.quote from '(?i)(' || v_score || ')'))) then n.nums[2] else n.nums[1] end)::numeric
          then 'the provider''s rank is stored as the qualification''s minimum'
        when coalesce(m.benchmark_band, '') <> '' and ((v_rank is not null and m.benchmark_band ~* v_rank) or (v_score is not null and m.benchmark_band ~* v_score))
          then 'the band holds label text, not a band'
        when m.min_value is not null and (coalesce(m.grade_scale, 'none') = 'none' or strpos(coalesce(m.quote, ''), trim_scale(m.min_value)::text) = 0)
          then 'the value has no scale or is not printed in its quote'
        when length(regexp_replace(coalesce(m.quote, ''), '[^[:alnum:]]', '', 'g')) < v_m / 2
          then 'the quote is too short to prove the row'
        end why) w
   where m.run_id = r.id and m.status = 'proposed' and not (m.id = any (v_ex)) and w.why is not null;
  if jsonb_array_length(v_flag) > 0 then
    v_why := v_why || format('%s waiting row(s) cannot be admitted as read (%s): leave them out with Approve except, or replace the read with a corrected one',
                             jsonb_array_length(v_flag), (select string_agg(k || ' ' || c, '; ') from (select f->>'why' k, count(*) c from jsonb_array_elements(v_flag) f group by 1 order by 1) z));
  end if;
  -- F-AER.08 (12 Nov 2026): a qualification minimum printed for one course waits until that course is linked (it is never admitted as the provider's)
  if security.pipeline_num_v1('aer.course_link_on', 1) >= 1 then
    select count(*) into v_qc from catalogue.provider_qualification_requirements q where q.run_id = r.id and q.status = 'proposed' and q.course_label is not null and q.course_id is null and not (q.id = any (v_ex));
    if v_qc > 0 then
      v_why := v_why || format('%s qualification row(s) belong to a course not linked to a catalogue course: link the course in Layer 4 course links, then decide', v_qc); v_fix := false;
    end if;
  end if;
  select coalesce(jsonb_agg(g.ids), '[]'::jsonb) into v_dup
    from (select jsonb_agg(m.id order by m.id) ids from catalogue.provider_entry_matrix m
           where m.run_id = r.id and m.status = 'proposed' and not (m.id = any (v_ex)) group by m.row_hash having count(*) > 1) g;
  if jsonb_array_length(v_dup) > 0 then
    v_why := v_why || format('%s group(s) of waiting rows share one identity (%s rows): leave out all but one of each, or replace the read with a corrected one',
                             jsonb_array_length(v_dup), (select sum(jsonb_array_length(g)) from jsonb_array_elements(v_dup) g));
  end if;
  return jsonb_build_object('rule', 'D-R3', 'complete', cardinality(v_why) = 0, 'rows', v_rows, 'waiting', v_wait, 'read_rows', r.rows_admitted,
                            'dropped_lost', v_lost, 'dropped_covered', v_cov, 'countries_missing', v_missing, 'flagged', v_flag, 'same_identity', v_dup,
                            'except_fixable', v_fix, 'no_table', coalesce(r.result->>'outcome', '') = 'no_requirements_table',
                            'reasons', to_jsonb(v_why));
end $$;


ALTER FUNCTION "security"."entry_matrix_gate_v1"("p_run" "uuid", "p_exclude" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."entry_matrix_gate_v1"("p_run" "uuid", "p_exclude" "uuid"[]) IS 'CF-247 D-R3: whole-read completeness of a provider entry-matrix run (current copy, reader verdict, rows changed, dropped rows no admitted row covers and the countries left with none, column-label qualifications, rank stored as minimum, label bands, values without scale or not printed, short quotes, shared identities, foreign rows). complete=false holds approval (entry.matrix_gate).';



CREATE OR REPLACE FUNCTION "security"."entry_matrix_identity_tg"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- RMIT band fix (26 Oct 2026): the level label is one of the row's condition keys (two levels can map to one study level)
  new.row_hash := security.entry_matrix_row_hash_v1(new.provider_id, new.course_id, new.country_code, new.study_level_id, new.benchmark_band, new.qualification_name,
    (case when jsonb_typeof(new.conditions) = 'array' then new.conditions else '[]'::jsonb end)
    || case when nullif(btrim(new.level_label), '') is not null then jsonb_build_array(jsonb_build_object('key', 'level: ' || btrim(new.level_label))) else '[]'::jsonb end
    -- F-AER.08 (12 Nov 2026): the printed course (a stream of one catalogue course has its own minimum)
    || case when nullif(btrim(new.course_label), '') is not null then jsonb_build_array(jsonb_build_object('key', 'course: ' || btrim(new.course_label))) else '[]'::jsonb end);
  if tg_op = 'INSERT' then
    new.version := coalesce(new.version, 1);
  elsif new.row_hash is not distinct from old.row_hash
        and (new.min_grade, new.min_value, new.grade_scale, new.conditions, new.routes, new.qualification_name, new.quote, new.edition)
            is distinct from (old.min_grade, old.min_value, old.grade_scale, old.conditions, old.routes, old.qualification_name, old.quote, old.edition) then
    new.version := coalesce(old.version, 1) + 1;  -- same identity, changed content: a delta
  end if;
  return new;
end $$;


ALTER FUNCTION "security"."entry_matrix_identity_tg"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."entry_matrix_identity_tg"() IS 'CF-247 AER v1.1: fills row_hash on every insert and update of catalogue.provider_entry_matrix; a content change under the same identity bumps version';



CREATE OR REPLACE FUNCTION "security"."entry_matrix_payload_v1"("p_provider" "uuid", "p_country" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('course_code', k.course_code)) || jsonb_build_object(
           'country', m.country_code, 'study_level', m.level_label, 'qualification', m.qualification_name, 'min_grade', m.min_grade,
           'scale', case when m.min_grade is null then 'none' else m.grade_scale end, 'band', m.benchmark_band, 'conditions', m.conditions, 'as_at', m.as_at, /* CF-247 D5 (decision A4): additive; true stated scale, false printed grade with no stated scale, null case by case */ 'scale_stated', case when m.min_grade is null or m.grade_scale = 'none' then null else m.grade_scale is not null end)
           order by m.country_code, m.level_label, m.benchmark_band, m.qualification_name), '[]'::jsonb)
    from catalogue.provider_entry_matrix m left join catalogue.courses k on k.id = m.course_id
   where m.provider_id = p_provider and m.status = 'active' and (p_country is null or m.country_code = upper(p_country))
$$;


ALTER FUNCTION "security"."entry_matrix_payload_v1"("p_provider" "uuid", "p_country" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."entry_matrix_payload_v1"("p_provider" "uuid", "p_country" "text") IS 'CF-247 Track C Step B (B2): the provider payload''s entry_matrix from active matrix rows, optionally one country. D5 (30 Oct 2026): each item carries scale_stated (true stated scale, false printed grade with no stated scale, null case by case).';



CREATE OR REPLACE FUNCTION "security"."entry_matrix_payload_v3"("p_provider" "uuid", "p_country" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- security.entry_matrix_payload_v1 with quote and source_url on each item (same rows, order and values)
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('course_code', k.course_code)) || jsonb_build_object(
           'country', m.country_code, 'study_level', m.level_label, 'qualification', m.qualification_name, 'min_grade', m.min_grade,
           'scale', case when m.min_grade is null then 'none' else m.grade_scale end, 'band', m.benchmark_band, 'conditions', m.conditions, 'as_at', m.as_at,
           'scale_stated', case when m.min_grade is null or m.grade_scale = 'none' then null else m.grade_scale is not null end,
           'quote', m.quote, 'source_url', m.source_url)
           order by m.country_code, m.level_label, m.benchmark_band, m.qualification_name), '[]'::jsonb)
    from catalogue.provider_entry_matrix m left join catalogue.courses k on k.id = m.course_id
   where m.provider_id = p_provider and m.status = 'active' and (p_country is null or m.country_code = upper(p_country))
$$;


ALTER FUNCTION "security"."entry_matrix_payload_v3"("p_provider" "uuid", "p_country" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."entry_matrix_payload_v3"("p_provider" "uuid", "p_country" "text") IS 'Website API v3 O20 (build brief WP-1.5): the provider entry matrix as entry_matrix_payload_v1 plus quote and source_url on each item.';



CREATE OR REPLACE FUNCTION "security"."entry_matrix_review_apply_v1"("p_item" "uuid", "p_action" "text", "p_final" "jsonb", "p_reason" "text", "p_run" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.entry_matrix_runs%rowtype; v_ex uuid[]; v_on int := 0; v_off int := 0; v_sup int := 0; v_map jsonb; v_ret int := 0; v_gate jsonb;
        v_qon int := 0; v_qoff int := 0; v_qsup int := 0;  -- 12 Nov 2026 (F-AER.03): qualification rows of the read
begin
  if p_item is not null then select * into r from pipeline.entry_matrix_runs where review_item_id = p_item;
  else select * into r from pipeline.entry_matrix_runs where id = p_run; end if;
  if r.id is null then raise exception 'no entry matrix run for this review item'; end if;
  -- D-R3 (Platform Admin 2 Nov 2026 23:24): a person's approval (Approve, Approve except, or confirming "no matrix published here") is refused,
  -- with nothing changed, while the whole read cannot be shown complete (security.entry_matrix_gate_v1); Reject and the automatic path are unchanged
  if p_action = 'approve' and p_item is not null then
    v_gate := security.entry_matrix_gate_v1(r.id, coalesce(array(select jsonb_array_elements_text(coalesce(p_final->'exclude_row_ids', '[]'::jsonb))::uuid), '{}'));
    if v_gate is not null and not coalesce((v_gate->>'complete')::boolean, true) then
      raise exception 'Held (D-R3, incomplete read): %. Nothing was changed',
        (select string_agg(w, '; ') from jsonb_array_elements_text(v_gate->'reasons') w) using errcode = '55000';
    end if;
  end if;
  -- Step C (29 Oct 2026): a rendered page with no requirements table; approval confirms "no matrix published here" and changes no row
  if r.rows_admitted = 0 and r.result->>'outcome' = 'no_requirements_table' then
    return jsonb_build_object('entry_matrix_run', r.id, 'admitted', 0, 'quarantined', 0, 'superseded', 0, 'outcome', 'no_requirements_table', 'decision', p_action);
  end if;
  if p_action = 'approve' then
    v_ex := coalesce(array(select jsonb_array_elements_text(coalesce(p_final->'exclude_row_ids', '[]'::jsonb))::uuid), '{}');
    -- RMIT band fix (26 Oct 2026): rows of one run that share an identity (a lost band or level) are never admitted
    if exists (select 1 from catalogue.provider_entry_matrix m where m.run_id = r.id and m.status = 'proposed' and not (m.id = any(v_ex))
                group by m.row_hash having count(*) > 1) then
      -- D4 C1 (Platform Admin 30 Oct 2026 08:45): conflicting approved replacements hold the whole decision
      raise exception 'Held (decision D4): entry matrix run %: approved rows % share one identity, so it is not clear which replaces the active value; nothing was changed. Leave out all but one of them, or Reject the read', r.id,
        (select string_agg(g.ids, '; ') from (select '[' || string_agg(m.id::text, ', ' order by m.id) || ']' ids from catalogue.provider_entry_matrix m
                                                where m.run_id = r.id and m.status = 'proposed' and not (m.id = any(v_ex)) group by m.row_hash having count(*) > 1) g)
        using errcode = '23505';
    end if;
    -- completeness guard (26 Oct 2026): a read that has not passed it is never admitted
    if coalesce(r.result->'completeness'->>'status', 'missing') in ('incomplete', 'unparsed')
       or (security.entry_completeness_required_v1(r.provider_id) and coalesce(r.result->'completeness'->>'status', 'missing') <> 'complete') then
      raise exception 'entry matrix run %: the read has not passed the completeness guard (%); nothing admitted', r.id,
        coalesce(r.result->'completeness'->>'status', 'no verdict') using errcode = '23514';
    end if;
    -- complete admission (26 Oct 2026), with A1 (Platform Admin 30 Oct 2026 06:53): under the guard the whole complete read is accounted for;
    -- every row it matched still waits, and is admitted or explicitly excluded by the reviewer (Approve except), never silently lost
    if security.entry_completeness_required_v1(r.provider_id)
       and (select count(*) from catalogue.provider_entry_matrix m where m.run_id = r.id and m.status = 'proposed')
           is distinct from nullif(r.result->'completeness'->>'matched', '')::int then
      raise exception 'entry matrix run %: % rows wait but the complete read matched %; every row of a complete read is admitted or explicitly excluded', r.id,
        (select count(*) from catalogue.provider_entry_matrix m where m.run_id = r.id and m.status = 'proposed'),
        coalesce(r.result->'completeness'->>'matched', '?') using errcode = '23514';
    end if;
    -- D4 C2: an approved row whose identity is already active on a row this decision does not replace holds the whole decision
    if exists (select 1 from catalogue.provider_entry_matrix p join catalogue.provider_entry_matrix a on a.row_hash = p.row_hash and a.status = 'active' and a.id <> p.id
                where p.run_id = r.id and p.status = 'proposed' and not (p.id = any(v_ex))
                  and not coalesce(a.provider_id = r.provider_id and a.source_id = r.source_id and a.run_id is distinct from r.id, false)) then
      raise exception 'Held (decision D4): entry matrix run %: approved row(s) have the identity of an active row this decision does not replace (%); nothing was changed. Leave the row(s) out, or Reject the read and escalate', r.id,
        (select string_agg('approved ' || p.id || ' = active ' || a.id || ' (source ' || coalesce(a.source_id::text, 'none') || ')', '; ' order by p.id)
           from catalogue.provider_entry_matrix p join catalogue.provider_entry_matrix a on a.row_hash = p.row_hash and a.status = 'active' and a.id <> p.id
          where p.run_id = r.id and p.status = 'proposed' and not (p.id = any(v_ex))
            and not coalesce(a.provider_id = r.provider_id and a.source_id = r.source_id and a.run_id is distinct from r.id, false))
        using errcode = '23505';
    end if;
    if cardinality(v_ex) = 0 then
    update catalogue.provider_entry_matrix m set status = 'superseded', status_reason = 'replaced by run ' || r.id, updated_at = now()
     where m.provider_id = r.provider_id and m.source_id = r.source_id and m.status = 'active' and m.run_id is distinct from r.id;
    get diagnostics v_sup = row_count;
    else
      -- D4 (Platform Admin 30 Oct 2026 08:45): under Approve except an earlier active row of this source is superseded only when an approved
      -- waiting row has its identity (row_hash); an active row whose replacement was excluded, or that the new read does not carry, stays
      -- active and is not written to. The map is taken before anything changes and is returned for the decision's event.
      v_map := jsonb_build_object(
        'replaced', (select coalesce(jsonb_agg(jsonb_build_object('active_row_id', a.id, 'replaced_by_row_id', p.id) order by a.id), '[]'::jsonb)
                       from catalogue.provider_entry_matrix a join catalogue.provider_entry_matrix p
                         on p.run_id = r.id and p.status = 'proposed' and not (p.id = any(v_ex)) and p.row_hash = a.row_hash
                      where a.provider_id = r.provider_id and a.source_id = r.source_id and a.status = 'active' and a.run_id is distinct from r.id),
        'retained_excluded', (select coalesce(jsonb_agg(jsonb_build_object('active_row_id', a.id, 'excluded_row_id', x.id) order by a.id, x.id), '[]'::jsonb)
                       from catalogue.provider_entry_matrix a join catalogue.provider_entry_matrix x
                         on x.run_id = r.id and x.status = 'proposed' and x.id = any(v_ex) and x.row_hash = a.row_hash
                      where a.provider_id = r.provider_id and a.source_id = r.source_id and a.status = 'active' and a.run_id is distinct from r.id
                        and not exists (select 1 from catalogue.provider_entry_matrix p where p.run_id = r.id and p.status = 'proposed'
                                          and not (p.id = any(v_ex)) and p.row_hash = a.row_hash)),
        'retained_not_in_read', (select coalesce(jsonb_agg(a.id order by a.id), '[]'::jsonb)
                       from catalogue.provider_entry_matrix a
                      where a.provider_id = r.provider_id and a.source_id = r.source_id and a.status = 'active' and a.run_id is distinct from r.id
                        and not exists (select 1 from catalogue.provider_entry_matrix p where p.run_id = r.id and p.status = 'proposed' and p.row_hash = a.row_hash)));
      v_ret := (select count(distinct v->>'active_row_id') from jsonb_array_elements(v_map->'retained_excluded') v)
             + jsonb_array_length(v_map->'retained_not_in_read');
      update catalogue.provider_entry_matrix m set status = 'superseded', status_reason = 'replaced by run ' || r.id,
             provenance = coalesce(m.provenance, '{}'::jsonb) || jsonb_build_object('aer_supersede', jsonb_build_object('review_item_id', coalesce(p_item, r.review_item_id),
               'run_id', r.id, 'replaced_by_row_id', p.id, 'decision', 'approve_except (D4)', 'at', now())),
             updated_at = now()
        from catalogue.provider_entry_matrix p
       where p.run_id = r.id and p.status = 'proposed' and not (p.id = any(v_ex)) and p.row_hash = m.row_hash
         and m.provider_id = r.provider_id and m.source_id = r.source_id and m.status = 'active' and m.run_id is distinct from r.id;
      get diagnostics v_sup = row_count;
    end if;
    -- A1: an excluded row stays unadmitted and identifiable: inactive, its reason names the item and the reviewer, provenance keeps the record
    update catalogue.provider_entry_matrix m set status = 'inactive',
           status_reason = 'excluded by approve except (Layer 4 item ' || coalesce(p_item, r.review_item_id)::text || ', reviewer ' || coalesce(p_final->>'reviewer', 'unknown') || '): ' || coalesce(p_reason, ''),
           provenance = coalesce(m.provenance, '{}'::jsonb) || jsonb_build_object('aer_exclusion', jsonb_build_object('review_item_id', coalesce(p_item, r.review_item_id),
             'run_id', r.id, 'content_hash', m.content_hash, 'reviewer', p_final->>'reviewer', 'reason', p_reason, 'at', now(), 'decision', 'approve_except (A1)',
             -- D4: the active row this excluded proposal would have replaced, kept active and unchanged (null when an approved row replaced it)
             'retains_active_row_id', (select a.id from catalogue.provider_entry_matrix a where a.row_hash = m.row_hash and a.status = 'active'
                                         and a.provider_id = r.provider_id and a.source_id = r.source_id and a.run_id is distinct from r.id),
             'retains_active_row_hash', (select a.row_hash from catalogue.provider_entry_matrix a where a.row_hash = m.row_hash and a.status = 'active'
                                         and a.provider_id = r.provider_id and a.source_id = r.source_id and a.run_id is distinct from r.id))),
           updated_at = now()
     where m.run_id = r.id and m.status = 'proposed' and m.id = any(v_ex);
    get diagnostics v_off = row_count;
    update catalogue.provider_entry_matrix m set status = 'active', status_reason = null, updated_at = now()
     where m.run_id = r.id and m.status = 'proposed';
    get diagnostics v_on = row_count;
    -- 12 Nov 2026 (F-AER.03): the read's qualification rows follow the same decision: a row left out stays out; an earlier active row of this source for the same
    -- qualification is replaced by the approved one; the rest become active
    update catalogue.provider_qualification_requirements q set status = 'inactive',
           status_reason = 'excluded by approve except (Layer 4 item ' || coalesce(p_item, r.review_item_id)::text || '): ' || coalesce(p_reason, ''), updated_at = now()
     where q.run_id = r.id and q.status = 'proposed' and q.id = any(v_ex);
    update catalogue.provider_qualification_requirements a set status = 'superseded', status_reason = 'replaced by run ' || r.id, updated_at = now()
     where a.provider_id = r.provider_id and a.source_id = r.source_id and a.status = 'active' and a.run_id is distinct from r.id
       and exists (select 1 from catalogue.provider_qualification_requirements p where p.run_id = r.id and p.status = 'proposed' and p.qualification_code = a.qualification_code);
    get diagnostics v_qsup = row_count;
    update catalogue.provider_qualification_requirements q set status = 'active', status_reason = null, updated_at = now() where q.run_id = r.id and q.status = 'proposed';
    get diagnostics v_qon = row_count;
  else
    update catalogue.provider_entry_matrix m set status = 'inactive', status_reason = 'quarantined (' || p_action || '): ' || coalesce(p_reason, ''), updated_at = now()
     where m.run_id = r.id and m.status = 'proposed';
    get diagnostics v_off = row_count;
    update catalogue.provider_qualification_requirements q set status = 'inactive', status_reason = 'quarantined (' || p_action || '): ' || coalesce(p_reason, ''), updated_at = now()
     where q.run_id = r.id and q.status = 'proposed';
    get diagnostics v_qoff = row_count;
  end if;
  return jsonb_build_object('entry_matrix_run', r.id, 'admitted', v_on, 'quarantined', v_off, 'superseded', v_sup)
         || jsonb_build_object('qualification_admitted', v_qon, 'qualification_quarantined', v_qoff, 'qualification_superseded', v_qsup)
         || case when v_map is not null then jsonb_build_object('retained', v_ret, 'supersede_map', v_map) else '{}'::jsonb end;  -- D4 audit
end $$;


ALTER FUNCTION "security"."entry_matrix_review_apply_v1"("p_item" "uuid", "p_action" "text", "p_final" "jsonb", "p_reason" "text", "p_run" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."entry_matrix_review_trg_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.status in ('rejected', 'more_evidence', 'returned_layer2', 'returned_layer3', 'superseded') then
    perform security.entry_matrix_review_apply_v1(new.id, new.status, null, 'Layer 4 ' || new.status);
  end if;
  return new;
end $$;


ALTER FUNCTION "security"."entry_matrix_review_trg_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."entry_matrix_row_hash_v1"("p_provider" "uuid", "p_course" "uuid", "p_country" "text", "p_level" "uuid", "p_band" "text", "p_qualification" "text", "p_conditions" "jsonb") RETURNS character
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select encode(sha256(convert_to(
    p_provider::text || '|' || coalesce(p_course::text, '') || '|' || coalesce(upper(p_country), '') || '|' || coalesce(p_level::text, '') || '|' ||
    coalesce(p_band, '') || '|' ||
    coalesce((select string_agg(k, '|' order by k)
                from (select distinct lower(btrim(coalesce(e->>'board', e->>'era', e->>'key'))) k
                        from jsonb_array_elements(case when jsonb_typeof(p_conditions) = 'array' then p_conditions else '[]'::jsonb end) e
                       where jsonb_typeof(e) = 'object' and nullif(btrim(coalesce(e->>'board', e->>'era', e->>'key')), '') is not null
                      union
                      select lower(btrim(p_qualification)) where nullif(btrim(p_qualification), '') is not null) z), ''),
    'UTF8')), 'hex')::char(64)
$$;


ALTER FUNCTION "security"."entry_matrix_row_hash_v1"("p_provider" "uuid", "p_course" "uuid", "p_country" "text", "p_level" "uuid", "p_band" "text", "p_qualification" "text", "p_conditions" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."entry_matrix_row_hash_v1"("p_provider" "uuid", "p_course" "uuid", "p_country" "text", "p_level" "uuid", "p_band" "text", "p_qualification" "text", "p_conditions" "jsonb") IS 'CF-247 AER v1.1 (Platform Admin 26 Oct 2026 21:50): stable row identity of an entry-matrix row: provider, course, country, level, band and the sorted condition keys (board / era names and the row''s qualification), not their grade values';



CREATE OR REPLACE FUNCTION "security"."entry_matrix_use_stored_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_n int;
begin
  with c as (select s.id, (select a.id from pipeline.evidence_artifacts a
                            where a.source_url = s.url and a.storage_path is not null
                              -- AER Step B (29 Oct 2026): a PDF source takes only a stored PDF
                              and (s.url !~* '\.pdf($|[?#])' or a.mime_type = 'application/pdf')
                              -- 29 Oct 2026: an entry source takes no markdown copy (its tables cannot be read row by row)
                              and a.mime_type is distinct from 'text/markdown'
                              and coalesce(a.captured_at, a.created_at) > now() - make_interval(days => security.pipeline_num_v1('entry.matrix_refresh_days', 30)::int)
                            order by coalesce(a.captured_at, a.created_at) desc limit 1) eid
                from pipeline.entry_matrix_sources s where s.status = 'found' and security.entry_matrix_enabled_v1(s.provider_id))
  update pipeline.entry_matrix_sources s set status = 'read', read_via = 'stored', evidence_id = e.id, content_hash = coalesce(e.content_hash, e.id::text),
         read_at = now(), error = null, updated_at = now()
    from c join pipeline.evidence_artifacts e on e.id = c.eid
   where s.id = c.id;
  get diagnostics v_n = row_count;
  return v_n;
end $_$;


ALTER FUNCTION "security"."entry_matrix_use_stored_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."entry_rendered_note_v1"("p_run" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.entry_matrix_runs%rowtype; f pipeline.entry_matrix_sources%rowtype; v_first boolean; v_item uuid;
begin
  select * into r from pipeline.entry_matrix_runs where id = p_run;
  select * into f from pipeline.entry_matrix_sources where id = r.source_id;
  if r.id is null or f.id is null or r.review_item_id is not null then return r.review_item_id; end if;
  v_first := not exists (select 1 from catalogue.provider_entry_matrix m where m.provider_id = r.provider_id and m.status = 'active');
  insert into pipeline.layer4_review_items(entity_type, entity_id, field_code, evidence_id, before_value, proposed_value, layer2_state, layer3_state,
                                           status, escalation_reason, change_control_ref)
  values ('provider', r.provider_id, case when v_first then 'entry_matrix_first_run' else 'entry_matrix_change' end, f.evidence_id,
          jsonb_build_object('active_rows', (select count(*) from catalogue.provider_entry_matrix m where m.provider_id = r.provider_id and m.status = 'active')),
          jsonb_build_object('run_id', r.id, 'url', f.url, 'rows', 0, 'outcome', 'no_requirements_table', 'rendered', true,
                             'dropped', jsonb_array_length(coalesce(r.result->'dropped', '[]'::jsonb)), 'sample', '[]'::jsonb),
          jsonb_build_object('source', 'entry matrix reader (rendered page)', 'page', f.url, 'entry_matrix_source_id', f.id),
          jsonb_build_object('run_id', r.id, 'model', r.model_code),
          'pending',
          'Rendered page read: no requirements table found. Approve to confirm the provider publishes no matrix on this page (the website then says "contact the provider"); reject if the page does show one. No row is admitted or replaced either way.',
          'CF-CHG-20260915-247')
  returning id into v_item;
  update pipeline.entry_matrix_runs set review_item_id = v_item, result = coalesce(result, '{}'::jsonb) || jsonb_build_object('outcome', 'no_requirements_table'), updated_at = now()
   where id = r.id;
  return v_item;
end $$;


ALTER FUNCTION "security"."entry_rendered_note_v1"("p_run" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."entry_rendered_note_v1"("p_run" "uuid") IS 'CF-247 AER Step C (29 Oct 2026): a rendered entry page read with no requirements table opens one Layer 4 note (existing entry_matrix_first_run / entry_matrix_change vocabulary, no rows). Owner only.';



CREATE OR REPLACE FUNCTION "security"."entry_resolve_v1"("p_course" "uuid", "p_country" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare c record; v_cc text := upper(btrim(coalesce(p_country, ''))); v_levels uuid[]; v_band text; v_rows jsonb; v_note text;
begin
  if v_cc !~ '^[A-Z]{2}$' or not exists (select 1 from ref.countries k where k.iso_alpha2 = v_cc) then
    raise exception 'INVALID_INPUT: edu_country must be a known ISO 3166 alpha-2 country code' using errcode = '22023';
  end if;
  select x.id, x.provider_id, x.study_level_id, l.short_code into c from catalogue.courses x left join ref.study_levels l on l.id = x.study_level_id where x.id = p_course;
  if c.id is null then raise exception 'INVALID_INPUT: course not found' using errcode = '22023'; end if;
  -- the course's level and the matrix levels the setting treats as the same (entry.level_equivalents, "BH=BA")
  v_levels := array_remove(array[c.study_level_id] || array(
                select l2.id from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'entry.level_equivalents'), '[]'::jsonb)) p
                  join ref.study_levels l2 on l2.short_code = split_part(p, '=', 2)
                 where split_part(p, '=', 1) = c.short_code), null);
  -- 1 a course override (audience international or all; this country or none)
  select jsonb_agg(jsonb_build_object('text', r.description, 'min_grade', r.min_grade, 'min_score', r.min_entry_score, 'min_score_basis', r.min_entry_score_basis,
                                      'quote', r.quote, 'as_at', r.as_at, 'case_by_case', r.min_grade is null and r.min_entry_score is null, /* CF-247 D5: course-page rows hold no scale */ 'scale_stated', null::boolean) order by r.created_at)
    into v_rows from catalogue.course_entry_requirements r left join ref.countries k on k.id = r.country_id
   where r.course_id = c.id and r.status = 'active' and r.kind = 'override' and r.audience in ('international', 'all') and (r.country_id is null or k.iso_alpha2 = v_cc);
  if v_rows is not null then
    return jsonb_build_object('country', v_cc, 'step', 1, 'rule', 'course_override', 'rows', v_rows,
      'outcome', case when exists (select 1 from jsonb_array_elements(v_rows) z where not (z->>'case_by_case')::boolean) then 'minimum_published' else 'case_by_case' end);
  end if;
  -- 2 a per-course matrix row for the country; 3 the band ladder; 4 the provider minimum (active rows only, never proposed or quarantined)
  for i in 2 .. 4 loop
    if i = 3 then
      select r.benchmark_band into v_band from catalogue.course_entry_requirements r
       where r.course_id = c.id and r.status = 'active' and r.benchmark_band is not null and r.audience in ('international', 'all') order by r.updated_at desc limit 1;
      if v_band is null then continue; end if;
    end if;
    select jsonb_agg(jsonb_build_object('qualification', m.qualification_name, 'study_level', m.level_label, 'min_grade', m.min_grade, 'scale', m.grade_scale,
                                        'band', m.benchmark_band, 'conditions', m.conditions, 'quote', m.quote, 'as_at', m.as_at, 'edition', m.edition,
                                        'case_by_case', m.min_grade is null or m.grade_scale is not distinct from 'none', /* CF-247 D5 (decision A4): additive; true stated scale, false printed grade with no stated scale, null case by case */ 'scale_stated', case when m.min_grade is null or m.grade_scale = 'none' then null else m.grade_scale is not null end) order by m.qualification_name, m.level_label)
      into v_rows from catalogue.provider_entry_matrix m
     where m.provider_id = c.provider_id and m.status = 'active' and m.country_code = v_cc
       and case i when 2 then m.course_id = c.id
                  when 3 then m.course_id is null and m.matrix_kind = 'band_ladder' and m.benchmark_band = v_band and (m.study_level_id = any (v_levels) or security.entry_label_levels_v1(m.level_label) && v_levels)
                  else m.course_id is null and m.matrix_kind = 'provider_minimum' and (m.study_level_id = any (v_levels) or security.entry_label_levels_v1(m.level_label) && v_levels) end;
    if v_rows is not null then
      return jsonb_build_object('country', v_cc, 'step', i, 'rule', case i when 2 then 'course_country_row' when 3 then 'band_ladder' else 'provider_minimum' end,
        'band', case when i = 3 then v_band end, 'rows', v_rows,
        'outcome', case when exists (select 1 from jsonb_array_elements(v_rows) z where not (z->>'case_by_case')::boolean) then 'minimum_published' else 'case_by_case' end);
    end if;
  end loop;
  -- 5 nothing published applies: contact the provider (never invented). Say why a band table could not be used.
  v_note := case
    when v_band is null and exists (select 1 from catalogue.provider_entry_matrix m where m.provider_id = c.provider_id and m.status = 'active' and m.country_code = v_cc
                                       and m.matrix_kind = 'band_ladder' and (m.study_level_id = any (v_levels) or security.entry_label_levels_v1(m.level_label) && v_levels))
      then 'The provider publishes a band table for this country, but the course page prints no band to enter it with.'
    when v_band is not null then 'The course band ' || v_band || ' has no published row for this country and level.'
    when exists (select 1 from catalogue.provider_entry_matrix m where m.provider_id = c.provider_id and m.status = 'active' and m.country_code = v_cc)
      then 'The provider publishes rows for this country, none for this course''s level.'
    else 'No published requirement for this country.' end;
  return jsonb_build_object('country', v_cc, 'step', 5, 'rule', 'contact_provider', 'outcome', 'contact_provider', 'rows', '[]'::jsonb, 'note', v_note,
    'contact', (select p.website from catalogue.providers p where p.id = c.provider_id));
end $_$;


ALTER FUNCTION "security"."entry_resolve_v1"("p_course" "uuid", "p_country" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."entry_resolve_v1"("p_course" "uuid", "p_country" "text") IS 'CF-247 Track C Step B: the five-rule entry resolution (course override → per-course country row → band ladder → provider minimum → contact the provider) over active rows; case by case kept; pure lookup. D5 (30 Oct 2026): each row carries scale_stated (null for course-page rows and case by case).';



CREATE OR REPLACE FUNCTION "security"."entry_source_score_v1"("p_url" "text", "p_title" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  -- fixed: the same page-type rules and score as the worker's central.ts (strong 6 in the address, 4 in the link text, weak 1.5; a small provider's top-level entry page 4.5; +2 international; -0.5 PDF; +0.2 a level for a short address)
  with x as (
    select lower(replace(coalesce(substring(p_url from '^https?://[^/?#]+(/[^?#]*)'), '/'), '%20', ' ')) path,
           lower(coalesce(substring(p_url from '(\?[^#]*)'), '')) qs, lower(coalesce(p_title, '')) title),
  y as (
    select x.*, cardinality(array_remove(string_to_array(x.path, '/'), '')) depth,
           (x.path ~ 'country[-_ ]?equivalen|academic[-_ ]?(equivalen|entry[-_ ]?requirements?|requirements)|international[-_ ]?(and[-_ ]?overseas[-_ ]?)?qualifications|overseas[-_ ]?qualifications|qualifications?[-_ ]?(by[-_ ]?country|equivalen)|admission[-_ ]?by[-_ ]?country|entry[-_ ]?requirements?[-_ ]?(by[-_ ]?country|for[-_ ]?international)|international[-_ ]?(academic[-_ ]?)?entry[-_ ]?requirements?|minimum[-_ ]?entry[-_ ]?score') strong_path,
           (x.title ~ 'country[-_ ]?equivalen|academic[-_ ]?(equivalen|entry[-_ ]?requirements?|requirements)|international[-_ ]?(and[-_ ]?overseas[-_ ]?)?qualifications|overseas[-_ ]?qualifications|qualifications?[-_ ]?(by[-_ ]?country|equivalen)|admission[-_ ]?by[-_ ]?country|entry[-_ ]?requirements?[-_ ]?(by[-_ ]?country|for[-_ ]?international)|international[-_ ]?(academic[-_ ]?)?entry[-_ ]?requirements?|minimum[-_ ]?entry[-_ ]?score') strong_title,
           (x.path ~ '(entry|admission)[-_ ]?requirements?' or x.title ~ '(entry|admission)[-_ ]?requirements?') weak,
           -- an English-language requirements page is the English rule, not the academic entry matrix
           ((x.path || ' ' || x.title) ~ 'english|ielts|language[-_ ]?requirements?') english,
           ((x.path || x.qs) ~ '/(news|events?|blog|stories|media|staff|people|profiles?|search|login|signin|tags?|category|careers?|jobs|research|alumni|giving|donate|library|shop|cart|wp-admin|feed|residence|housing|accommodation|insurance|medical|parking|workshops?|pubs|publications)(/|$)|refund|extension|request[-_ ]?form|meals?|events[-_ ]?calendar|\.(jpe?g|png|gif|svg|zip|docx?|xlsx?|pptx?)$|[?&](page|s|q)=') noise,
           ((x.path || ' ' || x.title) ~ 'international|overseas|\yintl\y') intl,
           (x.path ~ '\.pdf$') pdf
      from x)
  select case when english or noise or not (strong_path or strong_title or weak) then null
              else round(greatest(case when strong_path then 6 when strong_title then 4 else 1.5 end,
                                  case when depth <= 2 and path ~ '^/((international|study|apply|admissions?|students?)/)?(entry|admissions?)[-_]?requirements?(/|$)' then 4.5 else 0 end)
                         + (case when intl then 2 else 0 end) - (case when pdf then 0.5 else 0 end) + greatest(0, 5 - depth) * 0.2, 1) end
    from y
$_$;


ALTER FUNCTION "security"."entry_source_score_v1"("p_url" "text", "p_title" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."entry_source_score_v1"("p_url" "text", "p_title" "text") IS 'CF-247 (7 Nov 2026): the score the worker (coverage-sweep central.ts, kind entry_requirements) gives a link as a provider''s international entry-requirements page, from its address and link text; null when it is not a candidate (English page, noise, no entry-requirements wording). 3 and above is a suggestion; central.min_suggest_score decides what is attached.';



CREATE OR REPLACE FUNCTION "security"."entry_source_stored_find_v1"("p_limit" integer DEFAULT NULL::integer, "p_apply" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_limit int := coalesce(p_limit, security.pipeline_num_v1('batch.aer_source_stored_find', 200)::int);
  v_max int := security.pipeline_num_v1('entry.attach_per_provider', 3)::int;
  v_min numeric := greatest(security.pipeline_num_v1('central.min_suggest_score', 4), 3);  -- fixed: the worker never suggests a page that scores under 3
  v_days int := security.pipeline_num_v1('aer.source_stored_find_recheck_days', 14)::int;
  r record; v_c jsonb; v_links int; v_cands int; v_weak int; v_best_url text; v_best_score numeric; v_shared boolean; v_pick jsonb; v_att int; v_out text;
  v_tally jsonb := '{}'::jsonb; v_looked int := 0; v_sources int := 0; v_preview jsonb := '[]'::jsonb;
begin
  if p_apply and security.pipeline_num_v1('aer.source_stored_find_on', 0) < 1 then return jsonb_build_object('on', false); end if;
  if security.pipeline_num_v1('entry.matrix_enabled', 0) < 1 then return jsonb_build_object('on', false, 'reason', 'the entry matrix reader is off (entry.matrix_enabled)'); end if;
  for r in
    select p.id provider_id, security.site_host_v1(p.website) ph
      from security.aer_eligible_v1() e join catalogue.providers p on p.id = e.provider_id
     where not exists (select 1 from pipeline.entry_matrix_sources s where s.provider_id = p.id)
       and coalesce(btrim(p.website), '') ~* '^https?://' and not security.third_party_host_v1(p.website)
       and not exists (select 1 from pipeline.aer_source_stored_find f where f.provider_id = p.id and (f.outcome = 'attached' or f.checked_at > now() - make_interval(days => v_days)))
     order by (select count(*) from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active') desc, p.id
  loop
    -- the eligibility rule is judged one provider at a time, only as far as the run needs (it rebuilds the eligible set on every call)
    if v_looked >= v_limit then exit; end if;
    if not security.entry_matrix_attach_allowed_v1(r.provider_id) then continue; end if;
    v_looked := v_looked + 1;
    select count(distinct lower(regexp_replace(regexp_replace(u.url, '^https?://(www\.)?', ''), '/+$', ''))) into v_links
      from (select l.url from pipeline.coverage_provider_urls l where l.provider_id = r.provider_id
            union all select l.url from pipeline.provider_discovery_links l where l.provider_id = r.provider_id) u;
    -- only the links that can be an entry-requirements page are scored, each once (a provider can hold 18,000 links); own website host (or a sub-domain) only; one row an address
    select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) into v_c from (
      select distinct on (kk.k) u.url, u.title, u.src, u.pages, u.score,
             coalesce(security.site_host_v1(u.url) = r.ph or right(security.site_host_v1(u.url), length(r.ph) + 1) = '.' || r.ph, false) ownhost
        from (select z.*, security.entry_source_score_v1(z.url, z.title) score
                from (select l.url, l.title, 'coverage_provider_urls' src, 1 pages from pipeline.coverage_provider_urls l where l.provider_id = r.provider_id
                      union all select l.url, l.anchor_text, 'provider_discovery_links', coalesce(l.pages, 1) from pipeline.provider_discovery_links l where l.provider_id = r.provider_id) z
               where (z.url || ' ' || coalesce(z.title, '')) ~* 'entr|equivalen|qualif|academic|admission') u,  -- fixed: every page rule needs one of these words, so this only skips links that cannot score
             lateral (select lower(regexp_replace(regexp_replace(u.url, '^https?://(www\.)?', ''), '/+$', '')) k) kk
       where u.score is not null
       order by kk.k, u.score desc, u.pages desc, length(u.url), u.url) q;
    select count(*) filter (where x.score >= v_min and x.ownhost), count(*) filter (where x.score is not null and x.ownhost and x.score < v_min)
      into v_cands, v_weak from jsonb_to_recordset(v_c) as x(url text, title text, src text, pages int, score numeric, ownhost boolean);
    select x.url, x.score into v_best_url, v_best_score from jsonb_to_recordset(v_c) as x(url text, title text, src text, pages int, score numeric, ownhost boolean)
     where x.score is not null and x.ownhost order by x.score desc, length(x.url), x.url limit 1;
    v_shared := exists (select 1 from catalogue.providers o where o.id <> r.provider_id and o.lifecycle_status = 'active' and security.site_host_v1(o.website) = r.ph);
    v_att := 0; v_pick := '[]'::jsonb;
    v_out := case when v_links = 0 then 'no_link_material' when v_cands = 0 then 'no_entry_candidate' when v_shared then 'host_shared' else 'attached' end;
    if v_out = 'attached' then
      select coalesce(jsonb_agg(jsonb_build_object('url', t.url, 'title', t.title, 'score', t.score, 'source', t.src, 'pages', t.pages, 'rank', t.rn) order by t.rn), '[]'::jsonb) into v_pick
        from (select x.*, row_number() over (order by x.score desc, length(x.url), x.url) rn from jsonb_to_recordset(v_c) as x(url text, title text, src text, pages int, score numeric, ownhost boolean)
               where x.score >= v_min and x.ownhost) t where t.rn <= v_max;
      if p_apply then
        insert into pipeline.entry_matrix_sources(provider_id, url, title, rank, found_via)
        select r.provider_id, e->>'url', left(e->>'title', 200), (e->>'rank')::int, 'search' from jsonb_array_elements(v_pick) e
        on conflict (provider_id, url) do nothing;
        get diagnostics v_att = row_count;
        v_sources := v_sources + v_att;
      end if;
    end if;
    v_tally := jsonb_set(v_tally, array[v_out], to_jsonb(coalesce((v_tally->>v_out)::int, 0) + 1));
    if not p_apply and v_out = 'attached' then v_preview := v_preview || jsonb_build_object('provider_id', r.provider_id, 'pick', v_pick); end if;
    if p_apply then
      insert into pipeline.aer_source_stored_find(provider_id, checked_at, outcome, links, candidates, best_url, best_score, attached, detail)
      values (r.provider_id, now(), v_out, v_links, v_cands, v_best_url, v_best_score, v_att,
              jsonb_build_object('below_threshold', v_weak, 'host_shared', v_shared, 'min_score', v_min, 'picked', v_pick))
      on conflict (provider_id) do update set checked_at = excluded.checked_at, outcome = excluded.outcome, links = excluded.links, candidates = excluded.candidates,
        best_url = excluded.best_url, best_score = excluded.best_score, attached = excluded.attached, detail = excluded.detail;
    end if;
  end loop;
  return jsonb_build_object('on', true, 'apply', p_apply, 'looked_at', v_looked, 'sources_attached', v_sources, 'outcomes', v_tally) || case when p_apply then '{}'::jsonb else jsonb_build_object('would_attach', v_preview) end;
end $_$;


ALTER FUNCTION "security"."entry_source_stored_find_v1"("p_limit" integer, "p_apply" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."entry_source_stored_find_v1"("p_limit" integer, "p_apply" boolean) IS 'CF-247 (7 Nov 2026): job aer-source-stored-find. For AER-eligible providers with no entry-requirements page, scores the links the platform already stored (provider_discovery_links, coverage_provider_urls) with the worker''s entry_requirements page rules, keeps those on the provider''s own website host (not a host another active provider also uses), and attaches the best (entry.attach_per_provider) as found_via search for the existing reader. Records every provider looked at, with the reason (pipeline.aer_source_stored_find). Fetches nothing, spends nothing. apply false measures without writing. Off until aer.source_stored_find_on is 1.';



CREATE OR REPLACE FUNCTION "security"."evidence_row_entity_links"("p_table" "text", "p_row" "jsonb") RETURNS TABLE("entity_type" "text", "entity_id" "uuid", "provider_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'scholarship'
    AS $$
declare v_course uuid; v_provider uuid; v_campus uuid; v_scholarship uuid;
begin
  v_course:=nullif(p_row->>'course_id','')::uuid; v_provider:=nullif(p_row->>'provider_id','')::uuid; v_campus:=nullif(p_row->>'campus_id','')::uuid; v_scholarship:=nullif(p_row->>'scholarship_id','')::uuid;
  if p_table='catalogue.campuses' then return query select 'campus'::text,nullif(p_row->>'id','')::uuid,v_provider; return;
  elsif p_table='catalogue.provider_associations' then return query select 'provider'::text,nullif(p_row->>'from_provider_id','')::uuid,nullif(p_row->>'from_provider_id','')::uuid; return query select 'provider'::text,nullif(p_row->>'to_provider_id','')::uuid,nullif(p_row->>'to_provider_id','')::uuid; return;
  elsif p_table like 'catalogue.provider_%' then if v_provider is not null then return query select 'provider'::text,v_provider,v_provider; end if; return;
  elsif p_table='catalogue.student_flow_observations' then if v_course is not null then select c.provider_id into v_provider from catalogue.courses c where c.id=v_course; return query select 'course'::text,v_course,v_provider; elsif v_provider is not null then return query select 'provider'::text,v_provider,v_provider; end if; return;
  elsif p_table like 'catalogue.course_%' then if v_course is not null then if v_provider is null then select c.provider_id into v_provider from catalogue.courses c where c.id=v_course; end if; return query select 'course'::text,v_course,v_provider; end if; if v_campus is not null then return query select 'campus'::text,v_campus,v_provider; end if; return;
  elsif p_table='scholarship.scholarships' then v_scholarship:=nullif(p_row->>'id','')::uuid; if v_scholarship is not null then return query select 'scholarship'::text,v_scholarship,v_provider; end if; return;
  elsif p_table='scholarship.scopes' then if v_scholarship is not null then if v_provider is null then select s.provider_id into v_provider from scholarship.scholarships s where s.id=v_scholarship; end if; return query select 'scholarship'::text,v_scholarship,v_provider; end if; if v_course is not null then select c.provider_id into v_provider from catalogue.courses c where c.id=v_course; return query select 'course'::text,v_course,v_provider; end if; if v_campus is not null then return query select 'campus'::text,v_campus,v_provider; end if; if nullif(p_row->>'provider_id','') is not null then return query select 'provider'::text,nullif(p_row->>'provider_id','')::uuid,nullif(p_row->>'provider_id','')::uuid; end if; return;
  elsif p_table like 'scholarship.%' then if v_scholarship is not null then if v_provider is null then select s.provider_id into v_provider from scholarship.scholarships s where s.id=v_scholarship; end if; return query select 'scholarship'::text,v_scholarship,v_provider; end if; return;
  end if; return;
end $$;


