CREATE OR REPLACE FUNCTION "security"."fc_billed_today_v1"() RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with o as (select v.observed_at, v.remaining_units, v.period_end from pipeline.vendor_credit_observations v
               join pipeline.layer2_acquisition_providers p on p.id = v.provider_id and p.provider_key = 'firecrawl'
              where v.observed_at > security.fc_day_start_v1() - interval '1 hour'),
       l as (select * from o order by observed_at desc limit 1),
       f as (select o.* from o, l where o.period_end = l.period_end order by o.observed_at limit 1)
  select coalesce(greatest(0, (select remaining_units from f) - (select remaining_units from l)), 0)
$$;


ALTER FUNCTION "security"."fc_billed_today_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fc_budget_left_v1"("p_purpose" "text") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_grp text := security.fc_purpose_group_v1(p_purpose); v_used numeric; v_left numeric; v_room numeric;
begin
  -- Decision 5 E-8 F2 (2 Nov 2026): nothing is left on any path once the monthly plan limit is reached
  if security.fc_month_refusal_v1(1) is not null then return 0; end if;
  if not coalesce((select (s.value #>> '{}')::boolean from pipeline.platform_toolset_settings s where s.toolset_key = 'firecrawl' and s.key = 'daily_budget_on'), false) then return 1000000; end if;
  -- CF-247 21 Oct 2026: on-demand spends (manual enrichment plan runs) have their own allowance and do not use up the automatic budget
  if security.fc_billed_today_v1() - security.fc_on_demand_today_v1() >= security.fc_setting_num_v1('daily_budget_total', 15000) then return 0; end if;
  select coalesce(sum(x.units), 0) into v_used from pipeline.coverage_vendor_usage x where x.at >= security.fc_day_start_v1() and security.fc_purpose_group_v1(x.purpose) = v_grp and x.on_demand_run is null and x.on_demand_request is null;
  v_left := greatest(0, security.fc_setting_num_v1('daily_share_' || v_grp, 0) - v_used);
  -- CF-247 priority floor (Platform Admin 8 Nov 2026, Firecrawl priority order): course page search, the lowest priority, does not spend the last credits on the plan. It may
  -- spend only the room above the floor (security.fc_priority_room_v1: null when the floor is off or no balance is fresh); every other group is unchanged.
  if v_grp = 'course_search' then
    v_room := security.fc_priority_room_v1();
    if v_room is not null then return case when v_room < 1 then 0 else least(v_left, v_room) end; end if;  -- fixed: one credit, the smallest spend
  end if;
  return v_left;
end $$;


ALTER FUNCTION "security"."fc_budget_left_v1"("p_purpose" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fc_budget_status_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with g(grp, label, sort) as (values ('course_search', 'Finding course pages', 1), ('reads', 'Reading pages', 2), ('scholarships', 'Scholarships', 3), ('central', 'Central pages', 4), ('other', 'Other', 5)),
       u as (select security.fc_purpose_group_v1(x.purpose) grp, sum(x.units) used from pipeline.coverage_vendor_usage x where x.at >= security.fc_day_start_v1() group by 1),
       r as (select f.grp, sum(f.n) n from pipeline.firecrawl_budget_refusals f where f.day = (now() at time zone 'Australia/Melbourne')::date group by 1)
  select jsonb_build_object(
    'on', coalesce((select (s.value #>> '{}')::boolean from pipeline.platform_toolset_settings s where s.toolset_key = 'firecrawl' and s.key = 'daily_budget_on'), false),
    'day_start', security.fc_day_start_v1(), 'total', security.fc_setting_num_v1('daily_budget_total', 15000), 'billed_today', security.fc_billed_today_v1(),
    'used_today', (select coalesce(sum(used), 0) from u),
    'groups', (select jsonb_agg(jsonb_build_object('group', g.grp, 'label', g.label, 'share', security.fc_setting_num_v1('daily_share_' || g.grp, 0),
                                                   'used', coalesce(u.used, 0), 'refused', coalesce(r.n, 0)) order by g.sort)
                 from g left join u on u.grp = g.grp left join r on r.grp = g.grp))
$$;


