CREATE OR REPLACE FUNCTION "security"."fc_priority_room_v1"() RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_floor numeric := security.fc_setting_num_v1('priority_floor_course_search', 0);  -- fixed: a missing setting means the floor is off
        v_est numeric;
begin
  if v_floor <= 0 then return null; end if;  -- fixed: 0 switches the floor off
  v_est := security.fc_vendor_estimate_v1();
  if v_est is null then return null; end if;
  return v_est - v_floor;
end $$;


ALTER FUNCTION "security"."fc_priority_room_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."fc_priority_room_v1"() IS 'CF-247 priority floor (8 Nov 2026): estimated plan credits less firecrawl / priority_floor_course_search; null when the floor is off or no balance is fresh. Read by security.fc_budget_left_v1 (course_search group), public.svc_fc_spend and security.lane_paid_hold_v1.';



CREATE OR REPLACE FUNCTION "security"."fc_provider_tier_v1"("p_provider_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 scholarship recovery F10: the course threshold of the order is the setting scholarship_tier_courses (was the literal 30)
  -- CF-247 scholarships beyond universities: a listed pilot provider is first while either proposal is on
  select case when exists (select 1 from pipeline.onboarding_pilot o where o.provider_id = p_provider_id and o.cohort = 'au-top-2026-10-12') then 0
              when security.scholarship_pilot_member_v1(p_provider_id)
                   and (security.scholarship_flag_v1('scholarship.non_university_admission', false) or security.scholarship_flag_v1('scholarship.legitimacy_checks_on', false)) then 0
              when security.coverage_country(p_provider_id) is distinct from 'AU' then 2
              when security.fc_courses_v1(p_provider_id) >= security.fc_setting_num_v1('scholarship_tier_courses', 30) then 1 else 3 end
$$;


ALTER FUNCTION "security"."fc_provider_tier_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fc_purpose_group_v1"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case when p = 'course_link_search' then 'course_search'
              when p in ('provider_description', 'provider_description_on_demand') then 'pdesc'  -- 20261110254000: provider descriptions have their own daily share
              when p like 'sch\_%' then 'scholarships'
              when p in ('central_map', 'central_scrape', 'central_entry_search') or p like 'provider\_facts%' then 'central'
              when p in ('scrape', 'fc_read', 'fc_probe', 'site_hint', 'adapter_builder', 'list_scrape') or p like 'fcx\_%' then 'reads'
              else 'other' end
$$;


ALTER FUNCTION "security"."fc_purpose_group_v1"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fc_sch_cap_since_v1"("p_provider_id" "uuid") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- D16 (31 Oct 2026): PL/pgSQL so its query plans are kept for the session; same rule as the SQL version
  return greatest(now() - interval '30 days',  -- fixed: the per-university cap window, unchanged from the SQL version
                  coalesce((select max(o.picked_at) from pipeline.onboarding_pilot o where o.provider_id = p_provider_id), '-infinity'::timestamptz),
                  coalesce((select max(po.started_at) from pipeline.provider_onboarding po where po.provider_id = p_provider_id), '-infinity'::timestamptz));
end $$;


ALTER FUNCTION "security"."fc_sch_cap_since_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fc_sch_eligible_v1"("p_provider_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- CF-247 scholarship recovery P2 (proposed, off until the Platform Admin switches scholarship.legitimacy_checks_on): evidence-based legitimacy
  -- instead of the course minimum; CF-247 scholarships beyond universities (decision 3 Nov 2026 08:44 §4): the pilot providers only while
  -- scholarship.pilot_only is on
  if security.scholarship_flag_v1('scholarship.legitimacy_checks_on', false) and security.scholarship_pilot_scope_v1(p_provider_id) then
    return security.scholarship_legitimacy_v1(p_provider_id);
  end if;
  -- D16 (31 Oct 2026): PL/pgSQL so its query plans are kept for the session; same rule as the SQL version
  return security.coverage_country(p_provider_id) is distinct from 'AU' or security.fc_courses_v1(p_provider_id) >= security.fc_setting_num_v1('scholarship_min_courses', 30);
end $$;


ALTER FUNCTION "security"."fc_sch_eligible_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fc_sch_held_v1"("p_provider_id" "uuid", "p_discovery" boolean) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- D16 (31 Oct 2026): PL/pgSQL so its query plans are kept for the session; same rule as the SQL version
  return coalesce((select (s.value #>> '{}')::boolean from pipeline.platform_toolset_settings s where s.toolset_key = 'firecrawl' and s.key = 'daily_budget_on'), false)
     and ((p_discovery and not security.fc_sch_eligible_v1(p_provider_id))
          or (select coalesce(sum(x.units), 0) from pipeline.coverage_vendor_usage x where x.provider_id = p_provider_id and x.purpose like 'sch\_%' and x.at > security.fc_sch_cap_since_v1(p_provider_id))
             >= security.fc_setting_num_v1('scholarship_cap_per_uni', 150));
end $$;


