CREATE OR REPLACE FUNCTION "security"."fc_scrape_profile_check_v1"("p" "jsonb", "p_name" "text") RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare e text[] := '{}'; k text; f jsonb; a jsonb; c jsonb; v_formats text[] := array['markdown', 'rawHtml', 'html', 'links', 'screenshot'];
        v_keys text[] := array['name', 'about', 'formats', 'onlyMainContent', 'includeTags', 'excludeTags', 'maxAgeMs', 'waitFor', 'timeout', 'actions', 'screenshotFullPage', 'crawl'];
        v_actions text[] := array['click', 'wait', 'scroll', 'press', 'write'];
        v_tag text := '^[a-zA-Z][a-zA-Z0-9-]{0,40}$|^[.#][A-Za-z0-9_-]{1,60}$';
begin
  if p is null or jsonb_typeof(p) <> 'object' then return array[p_name || ': not a profile']; end if;
  for k in select jsonb_object_keys(p) loop
    if not k = any (v_keys) then
      e := e || case when k = 'onlyCleanContent' then p_name || ': onlyCleanContent is never sent (an AI pass over the page)' else p_name || ': ' || k || ' is not a profile setting' end;
    end if;
  end loop;
  if (case when jsonb_typeof(p->'formats') = 'array' then jsonb_array_length(p->'formats') = 0 else true end) then e := e || (p_name || ': choose at least one format');
  else
    for f in select jsonb_array_elements(p->'formats') loop
      if (case when jsonb_typeof(f) = 'string' then not (f #>> '{}') = any (v_formats) else true end) then
        e := e || (p_name || ': format ' || coalesce(f #>> '{}', f::text) || ' is never sent (only markdown, rawHtml, html, links, screenshot)');
      end if;
    end loop;
    if (select count(distinct x) from jsonb_array_elements(p->'formats') x) <> jsonb_array_length(p->'formats') then e := e || (p_name || ': a format is named twice'); end if;
    if not exists (select 1 from jsonb_array_elements_text(p->'formats') x where x in ('markdown', 'rawHtml', 'html', 'links')) then
      e := e || (p_name || ': a screenshot alone is not a page read; add markdown, rawHtml, html or links');
    end if;
  end if;
  if p ? 'onlyMainContent' and jsonb_typeof(p->'onlyMainContent') <> 'boolean' then e := e || (p_name || ': onlyMainContent is yes or no'); end if;
  foreach k in array array['includeTags', 'excludeTags'] loop
    if p ? k and not security.fc_str_list_ok_v1(p->k, 40, v_tag, 61) then
      e := e || (p_name || ': ' || k || ' is a list of tag names or .class/#id selectors');
    end if;
  end loop;
  -- fixed: Firecrawl API bounds (maxAge at most 30 days here, waitFor 0 to 60,000 ms, timeout 1,000 to 300,000 ms)
  if coalesce(jsonb_typeof(p->'maxAgeMs'), 'null') <> 'null' and not security.fc_int_in_v1(p->'maxAgeMs', 0, 2592000000) then
    e := e || (p_name || ': the Firecrawl copy age is 0 to 30 days'); end if;
  if coalesce(jsonb_typeof(p->'waitFor'), 'null') <> 'null' and not security.fc_int_in_v1(p->'waitFor', 0, 60000) then
    e := e || (p_name || ': wait after load is 0 to 60,000 ms'); end if;
  if coalesce(jsonb_typeof(p->'timeout'), 'null') <> 'null' and not security.fc_int_in_v1(p->'timeout', 1000, 300000) then
    e := e || (p_name || ': time allowed is 1,000 to 300,000 ms'); end if;
  if security.fc_int_in_v1(p->'waitFor', 0, 60000) and security.fc_int_in_v1(p->'timeout', 1000, 300000) and (p->>'waitFor')::numeric >= (p->>'timeout')::numeric then
    e := e || (p_name || ': wait after load must be shorter than the time allowed'); end if;
  if coalesce(jsonb_typeof(p->'actions'), 'null') <> 'null' then
    if (case when jsonb_typeof(p->'actions') = 'array' then jsonb_array_length(p->'actions') > 20 else true end) then e := e || (p_name || ': actions are a list of at most 20 steps');
    else
      for a in select jsonb_array_elements(p->'actions') loop
        if jsonb_typeof(a) <> 'object' or not coalesce(a->>'type', '') = any (v_actions) then
          e := e || (p_name || ': action ' || coalesce(a->>'type', a::text) || ' is not allowed (only click, wait, scroll, press, write)');
        end if;
      end loop;
    end if;
  end if;
  if p ? 'screenshotFullPage' and jsonb_typeof(p->'screenshotFullPage') <> 'boolean' then e := e || (p_name || ': full-page screenshot is yes or no'); end if;
  if p ? 'crawl' then
    c := p->'crawl';
    if jsonb_typeof(c) <> 'object' then e := e || (p_name || ': crawl options are a set of values');
    else
      for k in select jsonb_object_keys(c) loop
        if not k = any (array['limit', 'maxDiscoveryDepth', 'includePaths', 'excludePaths', 'sitemap']) then
          e := e || (p_name || ': crawl ' || k || ' is not a crawl option (maxDiscoveryDepth, not maxDepth)'); end if;
      end loop;
      if c ? 'limit' and not security.fc_int_in_v1(c->'limit', 1, 1000) then
        e := e || (p_name || ': crawl pages at most is 1 to 1,000'); end if;  -- fixed: a sanity bound on a checked-only option (no lane crawls)
      if c ? 'maxDiscoveryDepth' and not security.fc_int_in_v1(c->'maxDiscoveryDepth', 0, 10) then
        e := e || (p_name || ': crawl link depth is 0 to 10'); end if;
      foreach k in array array['includePaths', 'excludePaths'] loop
        if c ? k and not security.fc_str_list_ok_v1(c->k, 50, null, 200) then
          e := e || (p_name || ': crawl ' || k || ' is a list of path patterns'); end if;
      end loop;
      if c ? 'sitemap' and not coalesce(c->>'sitemap', '') = any (array['include', 'skip', 'only']) then e := e || (p_name || ': crawl site map is include, skip or only'); end if;
    end if;
  end if;
  return e;
end $_$;


ALTER FUNCTION "security"."fc_scrape_profile_check_v1"("p" "jsonb", "p_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."fc_scrape_profile_check_v1"("p" "jsonb", "p_name" "text") IS 'CF-247 Firecrawl format profiles: every problem with one scrape profile, in words (empty when it can be saved and sent). Formats only markdown, rawHtml, html, links, screenshot; onlyCleanContent and every other key refused. The same rules as checkProfile in coverage-sweep/firecrawl.ts.';



CREATE OR REPLACE FUNCTION "security"."fc_scrape_profiles_check_v1"("p_profiles" "jsonb", "p_lanes" "jsonb", "p_overrides" "jsonb") RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare e text[] := '{}'; k text; v jsonb; o jsonb;
begin
  if p_profiles is null or jsonb_typeof(p_profiles) <> 'object' or p_profiles = '{}'::jsonb then e := e || 'profiles: at least one profile'::text;
  else
    for k, v in select * from jsonb_each(p_profiles) loop
      if k !~ '^[a-z][a-z0-9_]{0,40}$' or k = 'lane_own' then e := e || ('profile name ' || k || ' is not allowed'); end if;
      e := e || security.fc_scrape_profile_check_v1(v, k);
    end loop;
  end if;
  if p_lanes is not null and jsonb_typeof(p_lanes) <> 'object' then e := e || 'lanes: a set of lane and profile';
  else
    for k, v in select * from jsonb_each(coalesce(p_lanes, '{}'::jsonb)) loop
      if jsonb_typeof(v) <> 'string' or ((v #>> '{}') <> 'lane_own' and not coalesce(p_profiles ? (v #>> '{}'), false)) then
        e := e || ('lane ' || k || ': profile ' || coalesce(v #>> '{}', v::text) || ' does not exist'); end if;
    end loop;
  end if;
  if p_overrides is not null and jsonb_typeof(p_overrides) <> 'array' then e := e || 'overrides: a list';
  else
    for o in select jsonb_array_elements(coalesce(p_overrides, '[]'::jsonb)) loop
      if coalesce(o->>'provider_id', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' or coalesce(o->>'lane', '') = ''
         or not (o->>'profile' = 'lane_own' or coalesce(p_profiles ? (o->>'profile'), false)) then
        e := e || ('override for ' || coalesce(o->>'provider_id', '?') || ': needs a university, a lane and an existing profile');
      end if;
    end loop;
  end if;
  return e;
end $_$;


ALTER FUNCTION "security"."fc_scrape_profiles_check_v1"("p_profiles" "jsonb", "p_lanes" "jsonb", "p_overrides" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."fc_scrape_profiles_check_v1"("p_profiles" "jsonb", "p_lanes" "jsonb", "p_overrides" "jsonb") IS 'CF-247 Firecrawl format profiles: every problem with the whole set (profiles, lane map, provider overrides), in words. The same rules as checkProfiles in coverage-sweep/firecrawl.ts; a set the worker finds wrong is not used (each lane then sends its own request).';



CREATE OR REPLACE FUNCTION "security"."fc_search_stopped_for_v1"("p_provider" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with w as (select greatest(now() - make_interval(days => security.fc_setting_num_v1('search_stop_window_days', 7)::int),
                             coalesce((select max(r.resumed_at) from pipeline.firecrawl_search_resumes r where r.provider_id = p_provider), '-infinity'::timestamptz)) since)
  select
    -- too many searches with no page read since (search_stop_after in search_stop_window_days)
    (select count(*) from pipeline.coverage_vendor_usage x, w
      where x.provider_id = p_provider and x.purpose = 'course_link_search' and x.at > w.since and x.at < now() - interval '1 hour')  -- fixed: searches still in flight are not counted
      >= security.fc_setting_num_v1('search_stop_after', 30)
    and not exists (select 1 from pipeline.coverage_course_pages pg, w where pg.provider_id = p_provider and pg.read_at > w.since and pg.status = 'bound' and pg.read_status = 'read')
  or
    -- the latest search.wrong_in_row_stop title-search pages that were read were all the wrong page
    coalesce((select count(*) >= security.pipeline_num_v1('search.wrong_in_row_stop', 20)::int and count(*) filter (where y.status = 'bound' and y.read_status = 'read') = 0
                from (select pg.status, pg.read_status from pipeline.coverage_course_pages pg, w
                       where pg.provider_id = p_provider and pg.basis = 'title_search' and pg.read_at is not null and pg.bound_at > w.since
                       order by pg.bound_at desc limit security.pipeline_num_v1('search.wrong_in_row_stop', 20)::int) y), false)
  or
    -- held by the Platform Admin for an adapter check
    exists (select 1 from pipeline.firecrawl_search_holds h where h.provider_id = p_provider
             and not exists (select 1 from pipeline.firecrawl_search_resumes r where r.provider_id = h.provider_id and r.resumed_at > h.held_at))
$$;


ALTER FUNCTION "security"."fc_search_stopped_for_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."fc_search_stopped_for_v1"("p_provider" "uuid") IS 'CF-247 22 Oct 2026: security.fc_search_stopped_v1 for one provider (used by every course-search spend).';



CREATE OR REPLACE FUNCTION "security"."fc_search_stopped_v1"() RETURNS TABLE("provider_id" "uuid", "searches" bigint, "since" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with s as (
  with w as (select u.provider_id, greatest(now() - make_interval(days => security.fc_setting_num_v1('search_stop_window_days', 7)::int), coalesce(max(r.resumed_at), '-infinity'::timestamptz)) since
               from (select distinct x.provider_id from pipeline.coverage_vendor_usage x where x.purpose = 'course_link_search' and x.at > now() - make_interval(days => security.fc_setting_num_v1('search_stop_window_days', 7)::int)) u
               left join pipeline.firecrawl_search_resumes r on r.provider_id = u.provider_id group by u.provider_id)
  select w.provider_id, count(*) searches, w.since
    from w join pipeline.coverage_vendor_usage x on x.provider_id = w.provider_id and x.purpose = 'course_link_search' and x.at > w.since and x.at < now() - interval '1 hour' -- fixed: searches still in flight are not counted
   where not exists (select 1 from pipeline.coverage_course_pages pg where pg.provider_id = w.provider_id and pg.read_at > w.since and pg.status = 'bound' and pg.read_status = 'read')
   group by w.provider_id, w.since
  having count(*) >= security.fc_setting_num_v1('search_stop_after', 30))
  select s.provider_id, s.searches, s.since from s
  union all
  -- 21 Oct 2026: the latest search.wrong_in_row_stop title-search pages that were read were all the wrong page (until Search again)
  select z.provider_id, z.n, z.since from (
    select y.provider_id, count(*) n, min(y.bound_at) since, count(*) filter (where y.status = 'bound' and y.read_status = 'read') good
      from (select pg.provider_id, pg.status, pg.read_status, pg.bound_at,
                   row_number() over (partition by pg.provider_id order by pg.bound_at desc) rn
              from pipeline.coverage_course_pages pg
             where pg.basis = 'title_search' and pg.read_at is not null
               and pg.bound_at > now() - make_interval(days => security.fc_setting_num_v1('search_stop_window_days', 7)::int)
               and pg.bound_at > coalesce((select max(r.resumed_at) from pipeline.firecrawl_search_resumes r where r.provider_id = pg.provider_id), '-infinity'::timestamptz)) y
     where y.rn <= security.pipeline_num_v1('search.wrong_in_row_stop', 20)::int
     group by y.provider_id) z
   where z.n >= security.pipeline_num_v1('search.wrong_in_row_stop', 20)::int and z.good = 0
     and z.provider_id not in (select s2.provider_id from s s2)
  union all
  -- v2.15.265: held by the Platform Admin for an adapter check, until Search again
  select h.provider_id, 0::bigint, h.held_at from pipeline.firecrawl_search_holds h
   where not exists (select 1 from pipeline.firecrawl_search_resumes r where r.provider_id = h.provider_id and r.resumed_at > h.held_at)
     and h.provider_id not in (select s2.provider_id from s s2)
$$;


ALTER FUNCTION "security"."fc_search_stopped_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fc_setting_num_v1"("p_key" "text", "p_default" numeric) RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce((select (s.value #>> '{}')::numeric from pipeline.platform_toolset_settings s where s.toolset_key = 'firecrawl' and s.key = p_key), p_default)
$$;


