CREATE OR REPLACE FUNCTION "security"."fc_spend_host_v1"("p_url" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case when p_url ~* '(^|\s)site:\S+' then regexp_replace(substring(lower(p_url) from 'site:([^\s/]+)'), '^www\.', '')
              when p_url ~* '^https?://' then regexp_replace(substring(lower(p_url) from '^https?://([^/:?#]+)'), '^www\.', '')
              else null end
$$;


ALTER FUNCTION "security"."fc_spend_host_v1"("p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fc_str_list_ok_v1"("v" "jsonb", "n" integer, "pattern" "text", "max_len" integer) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case when jsonb_typeof(v) = 'array' then jsonb_array_length(v) <= n
              and not exists (select 1 from jsonb_array_elements(v) x
                               where case when jsonb_typeof(x) = 'string' then length(x #>> '{}') not between 1 and max_len or (pattern is not null and (x #>> '{}') !~ pattern) else true end)
         else false end
$$;


ALTER FUNCTION "security"."fc_str_list_ok_v1"("v" "jsonb", "n" integer, "pattern" "text", "max_len" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fc_vendor_estimate_v1"() RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare p pipeline.layer2_acquisition_providers%rowtype; v_unit numeric; v_rem numeric; v_at timestamptz;
begin
  select * into p from pipeline.layer2_acquisition_providers x where x.provider_key = 'firecrawl';
  if p.id is null then return null; end if;
  select o.remaining_units, o.observed_at into v_rem, v_at from pipeline.vendor_credit_observations o
   where o.provider_id = p.id and o.observed_at > now() - interval '2 hours'  -- fixed: the freshness layer2_provider_budget_status trusts (Decision 253)
   order by o.observed_at desc limit 1;
  if v_at is null then return null; end if;
  v_unit := coalesce(nullif(p.request_template->>'fixed_credit_units', '')::numeric, 1);
  return greatest(v_rem
    - coalesce((select sum(u.units) from pipeline.coverage_vendor_usage u where u.acquisition_provider_id = p.id and u.at > v_at), 0)
    - (select count(*)::numeric * v_unit from pipeline.layer2_provider_attempts a where a.acquisition_provider_id = p.id and a.started_at > v_at), 0);
end $$;


ALTER FUNCTION "security"."fc_vendor_estimate_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."fc_vendor_estimate_v1"() IS 'CF-247 priority floor (8 Nov 2026): estimated Firecrawl credits left on the plan (vendor balance read in the last 2 hours less use and provider attempts since), the same estimate security.fc_month_refusal_v1 uses; null when no balance was read in the last 2 hours.';



CREATE OR REPLACE FUNCTION "security"."fee_admitted_recheck_settle_tg"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_fee uuid; v_n int := 0;
begin
  if new.release_kind is distinct from 'person' or security.pipeline_num_v1('fees.recheck_keep_withdraws_on', 1) < 1 then return null; end if;
  v_fee := case when new.evidence->>'fee_id' ~ '^[0-9a-f-]{36}$' then (new.evidence->>'fee_id')::uuid end;
  if v_fee is null then return null; end if;
  update catalogue.course_fees set status = 'inactive', valid_to = current_date, updated_at = now(),
         notes = coalesce(notes, '') || ' | Withdrawn ' || to_char(now(), 'YYYY-MM-DD') || ': Layer 4 re-check item ' || new.id || ' kept the CRICOS total (' || coalesce(new.released_by, 'a person') || ')'
   where id = v_fee and status = 'active' and fee_type = 'provider_current_tuition' and amount = (new.evidence->>'amount')::numeric
     and course_id::text = new.entity_key;
  get diagnostics v_n = row_count;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('fees', 'recheck_keep', 'catalogue.course_fees ' || left(v_fee::text, 8),
          jsonb_build_object('issue', 'IQ-00111', 'flag_id', new.id, 'fee_id', v_fee, 'withdrawn', v_n, 'released_by', new.released_by, 'release_reason', new.release_reason,
                             'why_not', case when v_n = 0 then 'the fee is no longer the same active value (confirmed or replaced on the course, or locked)' end), null);
  if v_n > 0 then
    perform scholarship.refresh_course_financial_calculations(new.entity_key::uuid, null);
    insert into search.refresh_requests(requested_by) values ('fee re-check ' || new.id);
  end if;
  return null;
end $_$;


ALTER FUNCTION "security"."fee_admitted_recheck_settle_tg"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."fee_admitted_recheck_settle_tg"() IS 'CF-247 IQ-00111 D12: when a person releases a fee_ai_recheck item (Keep the CRICOS total), the AI fee it names is withdrawn if still the same active value (fees.recheck_keep_withdraws_on).';



CREATE OR REPLACE FUNCTION "security"."fee_admitted_recheck_v1"("p_fee" "uuid", "p_reason" "text", "p_actor" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare f catalogue.course_fees%rowtype; v_c catalogue.courses%rowtype; v_ev jsonb; v_id bigint; v_why text; v_prior jsonb;
begin
  if length(btrim(coalesce(p_reason, ''))) < 10 then raise exception 'give the reason for the re-check' using errcode = '22023'; end if;
  select * into f from catalogue.course_fees where id = p_fee;
  if f.id is null or f.fee_type <> 'provider_current_tuition' or f.status <> 'active' or coalesce(f.notes, '') not like '%AI fee reader (%' then
    return jsonb_build_object('fee_id', p_fee, 'raised', false, 'why', 'not an active AI fee reader value');
  end if;
  if exists (select 1 from pipeline.manual_locks m where m.entity = 'course' and m.entity_id = f.course_id) then
    return jsonb_build_object('fee_id', p_fee, 'raised', false, 'why', 'the course has a manual value; it is never re-checked automatically');
  end if;
  if exists (select 1 from pipeline.enrichment_flags x where x.entity = 'course' and x.entity_key = f.course_id::text and x.field = 'fee_ai_recheck') then
    return jsonb_build_object('fee_id', p_fee, 'raised', false, 'why', 'this course already has a re-check item (raised or decided)');
  end if;
  select * into v_c from catalogue.courses where id = f.course_id;
  select coalesce(jsonb_agg(jsonb_build_object('flag_id', x.id, 'state', x.state, 'flagged_at', x.flagged_at, 'released_at', x.released_at, 'released_by', x.released_by,
                                               'release_kind', x.release_kind, 'reason', x.reason, 'release_reason', x.release_reason) order by x.flagged_at), '[]'::jsonb)
    into v_prior from pipeline.enrichment_flags x
   where x.entity = 'course' and x.entity_key = f.course_id::text and x.reason_code = 'fee_crosscheck';
  v_ev := jsonb_build_object(
    'fee_id', f.id, 'amount', f.amount, 'currency', f.currency_code, 'fee_year', f.fee_year, 'basis', f.basis, 'admitted_at', f.created_at, 'notes', f.notes,
    'evidence_id', f.evidence_id,
    'source_url', (select e.source_url from pipeline.evidence_artifacts e where e.id = f.evidence_id),
    'captured_at', (select e.captured_at from pipeline.evidence_artifacts e where e.id = f.evidence_id),
    'quote', (select x.quote from pipeline.fee_reader_rows x where x.course_id = f.course_id and x.outcome = 'admitted' order by x.created_at desc limit 1),
    'cricos_total', (select r.amount from catalogue.course_fees r where r.course_id = f.course_id and r.fee_type = 'tuition' and r.basis = 'registered_total_course'
                       and r.status = 'active' order by r.created_at desc limit 1),
    'exclusion', (select jsonb_build_object('reason', e.reason, 'set_at', e.set_at) from pipeline.uni_adapter_exclusions e where e.course_id = f.course_id and e.field = 'fee' and e.active),
    'earlier_decisions', v_prior, 'raised_reason', p_reason, 'route', 'security.fee_admitted_recheck_v1');
  v_why := 'Re-check an admitted AI fee: ' || coalesce(f.currency_code, '') || ' ' || to_char(f.amount, 'FM999,999,990.00') || coalesce(' for ' || f.fee_year, '')
        || ' is active, but a person decided earlier: ' || coalesce((select left(e->>'release_reason', 160) from jsonb_array_elements(v_prior) e where e->>'state' = 'released' order by e->>'released_at' desc limit 1), 'no earlier decision')
        || '. Confirm it on the course, or keep the CRICOS total (the AI fee is withdrawn). ' || p_reason;
  perform set_config('cf.flag_fn', '1', true);
  insert into pipeline.enrichment_flags(entity, entity_key, provider_id, field, reason_code, reason, source, kind, state, raised_by_kind, evidence)
  values ('course', f.course_id::text, v_c.provider_id, 'fee_ai_recheck', 'fee_crosscheck', left(v_why, 1000), 'fee-reader-recheck', 'hard', 'raised', 'person', v_ev)
  returning id into v_id;
  insert into pipeline.enrichment_flag_events(flag_id, action, actor, actor_kind, reason, evidence) values (v_id, 'raised', coalesce(p_actor, 'unknown'), 'person', left(v_why, 1000), v_ev);
  perform set_config('cf.flag_fn', '', true);
  return jsonb_build_object('fee_id', p_fee, 'raised', true, 'flag_id', v_id, 'course_id', f.course_id);
end $$;


ALTER FUNCTION "security"."fee_admitted_recheck_v1"("p_fee" "uuid", "p_reason" "text", "p_actor" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."fee_admitted_recheck_v1"("p_fee" "uuid", "p_reason" "text", "p_actor" "text") IS 'CF-247 IQ-00111 D12: raise one "Fee fails the check" Layer 4 item to re-check an admitted AI fee, with its evidence and earlier decisions (new flag of field fee_ai_recheck; decided items are never changed). Service role or Platform Admin paste only.';



CREATE OR REPLACE FUNCTION "security"."fee_below_floor_v1"("p_course_id" "uuid", "p_amount" numeric, "p_basis" "text") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- the floor when the fee is below it (annual or indicative-annual basis only; a null basis is never checked), else null
  select a.min_annual_international
    from catalogue.courses c join catalogue.providers p on p.id = c.provider_id
    join pipeline.coverage_admission_countries a on a.country_id = p.country_id
   where c.id = p_course_id and p_basis in ('annual', 'indicative_annual') and a.min_annual_international is not null and p_amount < a.min_annual_international
$$;


ALTER FUNCTION "security"."fee_below_floor_v1"("p_course_id" "uuid", "p_amount" numeric, "p_basis" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fee_course_pages_enqueue_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v int := 0; v2 int := 0; rq record; v_hash text;
begin
  if security.pipeline_num_v1('fees.course_pages', 1) < 1 then return 0; end if;
  -- a) requests from the course page, first in line, once the page was read after the request (a fee held does not stop them)
  for rq in
    select q.course_id, g.provider_id, g.evidence_id, g.identity_basis, e.content_hash, k.iso_alpha2 cc, g.read_at, q.requested_at
      from pipeline.fee_course_requests q
      join pipeline.coverage_course_pages g on g.course_id = q.course_id
      left join pipeline.evidence_artifacts e on e.id = g.evidence_id and e.storage_path is not null
      join catalogue.providers p on p.id = g.provider_id join ref.countries k on k.id = p.country_id
     where q.queued_at is null
     for update of q skip locked
  loop
    if rq.read_at is null or rq.read_at < rq.requested_at or rq.evidence_id is null then
      if rq.requested_at < now() - make_interval(hours => security.pipeline_num_v1('enrich.wait_page_hours', 6)::int) then
        update pipeline.fee_course_requests set queued_at = now(), outcome = 'page_not_read' where course_id = rq.course_id;
      end if;
      continue;
    end if;
    if not security.coverage_identity_allowed(rq.provider_id, rq.identity_basis, 'tuition')
       or rq.cc not in (select jsonb_array_elements_text(s.value) from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'fees.countries') then
      update pipeline.fee_course_requests set queued_at = now(), outcome = 'not_admitted' where course_id = rq.course_id;
      continue;
    end if;
    -- CF-247 IQ-00111: a request for a course whose page fee is kept out (fee hold or fee-check exclusion) is closed as held, not read
    if security.pipeline_num_v1('fees.respect_holds_on', 1) >= 1 and security.fee_reader_hold_v1(rq.course_id) is not null then
      update pipeline.fee_course_requests set queued_at = now(), outcome = 'held' where course_id = rq.course_id;
      continue;
    end if;
    v_hash := coalesce(rq.content_hash, rq.evidence_id::text);
    update pipeline.fee_reader_queue set state = 'queued', attempts = 0, leased_until = null, error = null, priority = 1
     where course_id = rq.course_id and content_hash = v_hash and state <> 'leased';
    if not found then
      insert into pipeline.fee_reader_queue(fact_source_id, course_id, provider_id, evidence_id, content_hash, priority)
      select rq.evidence_id, rq.course_id, rq.provider_id, rq.evidence_id, v_hash, 1
       where not exists (select 1 from pipeline.fee_reader_queue x where x.fact_source_id = rq.evidence_id and x.content_hash = v_hash);
    end if;
    update pipeline.fee_course_requests set queued_at = now(), outcome = 'queued' where course_id = rq.course_id;
    v2 := v2 + 1;
  end loop;

  -- b) course pages that show one international fee, or an adapter fee excluded for the course, for a course with no fee held
  insert into pipeline.fee_reader_queue(fact_source_id, course_id, provider_id, evidence_id, content_hash)
  select g.evidence_id, g.course_id, g.provider_id, g.evidence_id, coalesce(e.content_hash, g.evidence_id::text)
    from pipeline.coverage_course_pages g
    join pipeline.evidence_artifacts e on e.id = g.evidence_id and e.storage_path is not null
    join catalogue.courses c on c.id = g.course_id and c.lifecycle_status = 'active'
    join catalogue.providers p on p.id = g.provider_id join ref.countries k on k.id = p.country_id
   where g.status = 'bound' and g.read_status = 'read'
     and ((g.candidates->'fee'->'candidates' @> '[{"international": true}]'::jsonb and security.coverage_tuition_target_v1(g.candidates->'fee') is not null)
          or (g.candidates->>'fee_by' = 'adapter' and nullif(g.candidates->'fee'->>'value', '') is not null and security.uni_adapter_excluded(g.course_id, 'fee')))
     and k.iso_alpha2 in (select jsonb_array_elements_text(s.value) from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'fees.countries')
     and security.coverage_identity_allowed(g.provider_id, g.identity_basis, 'tuition')
     and not (security.pipeline_num_v1('fees.respect_holds_on', 1) >= 1 and security.fee_reader_hold_v1(g.course_id) is not null)  -- CF-247 IQ-00111
     and not exists (select 1 from catalogue.course_fees f where f.course_id = g.course_id and f.fee_type = 'provider_current_tuition' and f.status = 'active')
     and not exists (select 1 from pipeline.layer4_review_items r where r.entity_id = g.course_id and r.field_code = 'provider_current_tuition_validation' and r.status = 'pending')
     and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = g.provider_id)
     and not exists (select 1 from pipeline.fee_reader_queue q where q.course_id = g.course_id and q.content_hash = coalesce(e.content_hash, g.evidence_id::text))
   order by g.read_at desc
   limit security.pipeline_num_v1('fees.course_pages_per_tick', 40)::int
  on conflict do nothing;
  get diagnostics v = row_count;
  return v + v2;
end $$;


ALTER FUNCTION "security"."fee_course_pages_enqueue_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fee_crosscheck_guard_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_pct numeric := security.pipeline_num_v1('admit.fee_crosscheck_pct', 25); r record; v_n int := 0; v_reason text;
begin
  -- an adapter fee not yet held is compared with the CRICOS registered course total; one too far off is held back (adapter exclusion) and flagged
  for r in
    select x.course_id, x.provider_id, x.fee, x.months, x.reg from (
      select pg.course_id, pg.provider_id, (pg.candidates->'fee'->>'value')::numeric fee, d.regulatory_tuition_amount reg,
             case co.duration_unit when 'months' then co.duration_value when 'weeks' then co.duration_value * 12 / 52.0 when 'years' then co.duration_value * 12 end months
        from pipeline.coverage_course_pages pg
        join pipeline.uni_adapters u on u.provider_id = pg.provider_id and u.enabled and u.admit and 'fee' = any (u.admit_fields)
        join catalogue.courses co on co.id = pg.course_id and co.lifecycle_status = 'active'
        join search.course_documents d on d.course_id = pg.course_id
       where pg.read_status = 'read' and pg.candidates->>'fee_by' = 'adapter' and (pg.candidates->'fee'->>'value') ~ '^[0-9]+(\.[0-9]+)?$'
         and d.regulatory_tuition_basis = 'registered_total_course' and d.regulatory_tuition_amount > 0
         and not d.has_provider_current_tuition
         and not exists (select 1 from pipeline.uni_adapter_exclusions e where e.course_id = pg.course_id and e.field = 'fee')) x
     where x.months >= 12 and abs(x.fee * x.months / 12.0 - x.reg) > v_pct / 100.0 * x.reg
  loop
    v_reason := format('automatic: the fee read (%s a year, %s months) is more than %s%% from the CRICOS registered course total (%s); held back for review (CF-247 15 Oct 2026)',
                       r.fee, round(r.months), v_pct, r.reg);
    insert into pipeline.uni_adapter_exclusions(course_id, field, provider_id, active, reason) values (r.course_id, 'fee', r.provider_id, true, v_reason)
    on conflict (course_id, field) do nothing;
    insert into pipeline.enrichment_flags(entity, entity_key, provider_id, field, reason_code, reason, source)
    values ('course', r.course_id::text, r.provider_id, 'fee', 'fee_crosscheck', v_reason, 'adapter-overwrite')
    on conflict (entity, entity_key, field, reason_code) do nothing;
    v_n := v_n + 1;
  end loop;
  return v_n;
end $_$;


ALTER FUNCTION "security"."fee_crosscheck_guard_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fee_evidence_own_site_v1"("p_evidence_id" "uuid", "p_course_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when ea.id is null then false
              when h is null then true
              when not (h = any(security.l4_shared_hosts_v1())) then true
              else coalesce(h = ph or h like '%.' || ph, false) end
    from (select 1) one
    left join pipeline.evidence_artifacts ea on ea.id = p_evidence_id
    left join lateral (select substring(ea.source_url from '^https?://(?:www\.)?([^/:?#]+)') h) a on true
    left join lateral (select substring(p.website from '^https?://(?:www\.)?([^/:?#]+)') ph
                         from catalogue.courses c join catalogue.providers p on p.id = c.provider_id where c.id = p_course_id) b on true
$$;


