CREATE OR REPLACE FUNCTION "security"."fee_period_settle_v1"("p_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_rule text; v_quote text; v_wording int := 0; v_short int := 0; v_left int := 0; v_ids uuid[] := '{}';
  yr constant text := '(per\s+(year|annum|academic\s+year)|a\s+year\M|\mannual(ly)?\M|\myearly\M|\m1\s*(yr|year)\M|\mone\s+year\M|\m(first|1st)[- ]year\M|\mp\.?a\.?\M|/\s*(year|yr)\M|each\s+year|full[- ]time\s+year)';
  other constant text := '(per\s+(semester|trimester|term|unit|subject|credit|study\s+period|session)|\m(semester|trimester)s?\M|\mtotal\M|\m(whole|entire|full)\s+(course|program|programme|degree)\M)';
begin
  if current_user not in ('postgres', 'service_role') and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required' using errcode = '42501'; end if;
  for r in select fl.id, fl.entity_id, fl.record_id, coalesce(fl.detail->>'quotes', '') q, c.duration_value dv, lower(coalesce(c.duration_unit, '')) du
             from pipeline.data_flags fl join catalogue.courses c on c.id = fl.entity_id
             join catalogue.course_fees fe on fe.id = fl.record_id and fe.status = 'active'
            where fl.status = 'open' and fl.flag_code = 'tuition_period_assumed_annual'
            order by fl.created_at limit greatest(1, least(coalesce(p_limit, 500), 2000))
            for update of fl skip locked loop
    v_rule := null; v_quote := null;
    if r.q ~* other then v_left := v_left + 1; continue; end if;
    if r.q ~* yr then v_rule := 'per_year_wording'; v_quote := substring(r.q from '(?i)([^"]{0,80}' || yr || '[^"]{0,40})');
    elsif (r.du in ('week', 'weeks') and r.dv <= 52) or (r.du in ('month', 'months') and r.dv <= 12) or (r.du in ('year', 'years') and r.dv <= 1) then
      v_rule := 'course_one_year_or_less';
    end if;
    if v_rule is null then v_left := v_left + 1; continue; end if;
    update catalogue.course_fees set last_verified_at = now(), updated_at = now(),
           notes = coalesce(notes, '') || case v_rule when 'per_year_wording' then ' | period confirmed per year from the page wording (automatic check, Decision 218)'
                                                 else ' | course runs a year or less, so per year equals the whole course (automatic check, Decision 218)' end
     where id = r.record_id;
    update pipeline.data_flags set status = 'confirmed', resolved_at = now(), resolved_by = null,
           resolution = jsonb_build_object('action', 'confirm', 'by', 'automatic period check', 'rule', v_rule, 'quote', v_quote,
                                           'duration', case when v_rule = 'course_one_year_or_less' then r.dv || ' ' || r.du end, 'decision', 'Decision 218')
     where id = r.id;
    if v_rule = 'per_year_wording' then v_wording := v_wording + 1; else v_short := v_short + 1; end if;
    v_ids := v_ids || r.entity_id;
  end loop;
  if cardinality(v_ids) > 0 then perform search.refresh_course_enrichment_scoped_v1(v_ids, true); end if;
  return jsonb_build_object('confirmed_by_wording', v_wording, 'confirmed_short_course', v_short, 'left_for_a_person', v_left);
end $$;


ALTER FUNCTION "security"."fee_period_settle_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fee_plausibility_check_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ymin numeric := security.pipeline_num_v1('fees.guard_year_min', 1990); v_ymax numeric := security.pipeline_num_v1('fees.guard_year_max', 2040);
  v_old int := security.pipeline_num_v1('fees.guard_year_old_gap', 2)::int; v_ahead int := security.pipeline_num_v1('fees.guard_year_ahead', 3)::int;
  v_min_years numeric := security.pipeline_num_v1('fees.guard_total_min_years', 1.4); v_pct numeric := security.pipeline_num_v1('fees.guard_total_match_pct', 2);
  v_sample int := security.pipeline_num_v1('fees.guard_sample', 25)::int;
  v_year int := extract(year from now() at time zone 'Australia/Melbourne')::int;  -- fixed: the platform's calendar year
  r record; v_out jsonb := '{}'::jsonb;
begin
  if security.pipeline_num_v1('fees.guard_on', 1) < 1 then return jsonb_build_object('skipped', 'fees.guard_on is 0'); end if;
  for r in
    with live as (
      select f.id, f.course_id, f.amount, f.currency_code, f.basis, f.fee_year, f.notes
        from catalogue.course_fees f
       where f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.audience = 'international'),
    hit as (
      select 'fee_amount_is_a_year'::text reason, l.id, l.course_id, l.amount, l.fee_year from live l
       where l.basis in ('annual', 'indicative_annual', 'total_indicative') and l.amount = trunc(l.amount) and l.amount between v_ymin and v_ymax
      union all
      select 'fee_ai_on_held_course', l.id, l.course_id, l.amount, l.fee_year from live l
       where l.notes like '%AI fee reader (%' and security.fee_reader_hold_v1(l.course_id) is not null
         and (security.fee_reader_hold_v1(l.course_id) like 'a fee check hold%'
              or exists (select 1 from pipeline.uni_adapter_exclusions e where e.course_id = l.course_id and e.field = 'fee' and e.active and e.set_at < (select x.created_at from catalogue.course_fees x where x.id = l.id)))
      union all
      select 'fee_year_out_of_range', l.id, l.course_id, l.amount, l.fee_year from live l
       where l.fee_year is not null and (l.fee_year < v_year - v_old or l.fee_year > v_year + v_ahead)
      union all
      select 'fee_annual_equals_registered_total', l.id, l.course_id, l.amount, l.fee_year from live l
        join catalogue.courses c on c.id = l.course_id
        join lateral (select t.amount from catalogue.course_fees t where t.course_id = l.course_id and t.fee_type = 'tuition' and t.basis = 'registered_total_course' and t.status = 'active'
                       order by t.created_at desc limit 1) reg on true
       where l.basis in ('annual', 'indicative_annual') and reg.amount > 0 and abs(l.amount - reg.amount) <= reg.amount * v_pct / 100.0
         and (case c.duration_unit when 'weeks' then c.duration_value / 52.0 when 'months' then c.duration_value / 12.0 when 'years' then c.duration_value end) >= v_min_years)  -- fixed: calendar conversions
    select reason, count(*) n,
           (select jsonb_agg(x) from (select jsonb_build_object('fee', h2.id, 'course', h2.course_id, 'amount', h2.amount, 'year', h2.fee_year) x from hit h2
                                       where h2.reason = hit.reason order by h2.id limit v_sample) s) sample
      from hit group by reason
  loop
    v_out := v_out || jsonb_build_object(r.reason, jsonb_build_object('count', r.n, 'sample', r.sample));
  end loop;
  -- one flag per reason: raised with the count and a sample while any row matches, released when none does
  for r in select * from (values ('fee_amount_is_a_year', 'hard', 'an active provider fee whose amount is a calendar year (the adapter read a year as the fee)'),
                                 ('fee_ai_on_held_course', 'hard', 'an active AI fee reader fee on a course whose page fee a fee check keeps out (IQ-00111)'),
                                 ('fee_year_out_of_range', 'soft', 'an active provider fee with a fee year far from this year'),
                                 ('fee_annual_equals_registered_total', 'soft', 'an annual provider fee equal to the registered whole-course total of a multi-year course')) v(reason, kind, what) loop
    if coalesce((v_out->r.reason->>'count')::int, 0) > 0 then
      insert into pipeline.enrichment_flags(entity, entity_key, field, reason_code, reason, source, kind, state, raised_by_kind, evidence)
      values ('fees', 'plausibility', '', r.reason,
              format('%s fees: %s. The guard changes no fee; withdrawal is a Platform Admin paste (docs/paste/FEE-*).', v_out->r.reason->>'count', r.what), 'fee-plausibility-guard', r.kind, 'raised', 'auto',
              jsonb_build_object('count', (v_out->r.reason->>'count')::int, 'sample', v_out->r.reason->'sample'))
      on conflict (entity, entity_key, field, reason_code) do update
        set reason = excluded.reason, evidence = excluded.evidence, flagged_at = now(), cleared_at = null, state = 'raised', kind = excluded.kind;
    else
      update pipeline.enrichment_flags set cleared_at = now(), state = 'released', released_at = now(), release_kind = 'auto', release_reason = 'No active fee matches this reason'
       where entity = 'fees' and entity_key = 'plausibility' and field = '' and reason_code = r.reason and state = 'raised';
    end if;
  end loop;
  return jsonb_build_object('checked_at', now(), 'counts', v_out);
end $$;


ALTER FUNCTION "security"."fee_plausibility_check_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."fee_plausibility_check_v1"() IS 'CF-247 FEE (8 Nov 2026): read-only daily guard on active international provider_current_tuition fees; raises or clears one fee-plausibility flag per reason with row keys. Changes no fee.';



CREATE OR REPLACE FUNCTION "security"."fee_reader_decided_v1"("p_course" "uuid", "p_amount" numeric) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  -- the latest ruling of a person on this figure for this course, or null (also null while fees.respect_decisions_on is 0)
  select jsonb_build_object('item', d.id, 'status', d.status, 'decided_at', d.decided_at, 'amount', (d.proposed_value->>'amount')::numeric)
    from pipeline.layer4_review_items d
   where security.pipeline_num_v1('fees.respect_decisions_on', 0) >= 1
     and d.entity_id = p_course and d.field_code = 'provider_current_tuition_validation' and d.status in ('rejected', 'approved', 'edited_approved')
     and d.decided_at > now() - make_interval(days => security.pipeline_num_v1('fees.decision_memory_days', 90)::int)
     and (d.proposed_value->>'amount') ~ '^[0-9]+(\.[0-9]+)?$'
     -- fixed: rounding floor of 1 (the reader's own tolerance for the same figure, as in svc_fee_ai_record)
     and abs((d.proposed_value->>'amount')::numeric - p_amount) <= greatest(1, p_amount * security.pipeline_num_v1('fees.decision_same_pct', 1) / 100.0)
   order by d.decided_at desc limit 1
$_$;


ALTER FUNCTION "security"."fee_reader_decided_v1"("p_course" "uuid", "p_amount" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."fee_reader_decided_v1"("p_course" "uuid", "p_amount" numeric) IS 'CF-247 IQ-00040: the latest Layer 4 ruling (rejected, approved, edited_approved) of a person on the same fee figure for a course within fees.decision_memory_days, or null; null while fees.respect_decisions_on is 0.';



CREATE OR REPLACE FUNCTION "security"."fee_reader_finding_v1"("p_provider" "uuid", "p_source" "uuid", "p_kind" "text", "p_key" "text", "p_detail" "jsonb") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  insert into pipeline.fee_reader_findings(provider_id, fact_source_id, kind, key, detail)
  values (p_provider, p_source, p_kind, left(coalesce(p_key, ''), 200), coalesce(p_detail, '{}'::jsonb))
  on conflict (provider_id, kind, key) do update set times = pipeline.fee_reader_findings.times + 1, last_seen = now(), detail = excluded.detail,
         fact_source_id = coalesce(excluded.fact_source_id, pipeline.fee_reader_findings.fact_source_id), resolved_at = null
$$;


ALTER FUNCTION "security"."fee_reader_finding_v1"("p_provider" "uuid", "p_source" "uuid", "p_kind" "text", "p_key" "text", "p_detail" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fee_reader_hold_v1"("p_course" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 IQ-00111: why the AI fee reader may not admit a page fee for this course now, or null. A raised fee check hold (Layer 4 decides); an
  -- active fee exclusion from a fee-check decision (the person decided the page figure is not the annual fee, e.g. "keep the CRICOS total");
  -- any active fee exclusion while fees.respect_all_exclusions_on is on.
  select case
    when exists (select 1 from pipeline.enrichment_flags fl where fl.entity = 'course' and fl.entity_key = p_course::text and fl.field = 'fee'
                    and fl.reason_code = 'fee_crosscheck' and fl.state = 'raised')
      then 'a fee check hold is raised for this course; Layer 4 decides'
    when exists (select 1 from pipeline.uni_adapter_exclusions e where e.course_id = p_course and e.field = 'fee' and e.active)
     and exists (select 1 from pipeline.enrichment_flags fl where fl.entity = 'course' and fl.entity_key = p_course::text and fl.field = 'fee' and fl.reason_code = 'fee_crosscheck')
      then 'the page fee is excluded for this course by a fee check decision'
    when security.pipeline_num_v1('fees.respect_all_exclusions_on', 0) >= 1
     and exists (select 1 from pipeline.uni_adapter_exclusions e where e.course_id = p_course and e.field = 'fee' and e.active)
      then 'the page fee is excluded for this course'
  end
$$;


ALTER FUNCTION "security"."fee_reader_hold_v1"("p_course" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."fee_reader_hold_v1"("p_course" "uuid") IS 'CF-247 IQ-00111: the reason the AI fee reader keeps a page fee out for a course (raised fee check hold, fee-check exclusion, or any fee exclusion with fees.respect_all_exclusions_on), or null.';



CREATE OR REPLACE FUNCTION "security"."fee_reader_in_scope_v1"("p_provider" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1 from catalogue.providers p join ref.countries k on k.id = p.country_id left join ref.provider_types t on t.id = p.provider_type_id
     where p.id = p_provider
       and k.iso_alpha2 in (select jsonb_array_elements_text(s.value) from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'fees.countries')
       and coalesce(t.code, 'other') in (select jsonb_array_elements_text(s.value) from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'fees.provider_types')
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id))
$$;


ALTER FUNCTION "security"."fee_reader_in_scope_v1"("p_provider" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fee_reader_tick_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_added int := 0; v_queued int := 0; v_rejected int := 0; v_fired int := 0;
        v_max int := security.pipeline_num_v1('fees.max_pages_per_provider', 12)::int;
begin
  -- 23 Oct 2026: the job is called each minute and runs every fees.run_every_minutes minutes
  if (extract(epoch from date_trunc('minute', now())) / 60)::bigint % greatest(security.pipeline_num_v1('fees.run_every_minutes', 2)::int, 1) <> 0 then
    return jsonb_build_object('skipped', 'not this minute');
  end if;
  -- 1 fee pages suggested by the central-page search, for providers in scope
  insert into pipeline.provider_fact_sources(provider_id, kind, url, title, rank, found_via, status)
  select x.provider_id, 'fee_schedule', x.url, left(x.title, 200), 5, 'search', 'found'
    from (select s.provider_id, e->>'url' url, e->>'title' title, row_number() over (partition by s.provider_id order by (e->>'score')::numeric desc) rn
            from pipeline.provider_central_search s cross join lateral jsonb_array_elements(coalesce(s.found, '[]'::jsonb)) e
           where e->>'kind' = 'fee_schedule' and coalesce((e->>'score')::numeric, 0) >= security.pipeline_num_v1('fees.min_suggest_score', 4)
             and security.fee_reader_in_scope_v1(s.provider_id)) x
   where x.rn <= v_max and x.url ~ '^https?://'
     and (select count(*) from pipeline.provider_fact_sources f where f.provider_id = x.provider_id and f.kind = 'fee_schedule') < v_max
  on conflict (provider_id, kind, url) do nothing;
  get diagnostics v_added = row_count;

  -- 2 queue every stored fee page version not read yet; a new version of a page read before is a finding
  insert into pipeline.fee_reader_queue(fact_source_id, provider_id, content_hash)
  select f.id, f.provider_id, f.content_hash
    from pipeline.provider_fact_sources f join pipeline.evidence_artifacts e on e.id = f.evidence_id
   where f.kind = 'fee_schedule' and f.content_hash is not null and e.storage_path is not null and f.status in ('read', 'no_values', 'parsed')
     and security.fee_reader_in_scope_v1(f.provider_id)
  on conflict (fact_source_id, content_hash) do nothing;
  get diagnostics v_queued = row_count;
  perform security.fee_reader_finding_v1(q.provider_id, q.fact_source_id, 'page_changed', q.fact_source_id::text, jsonb_build_object('url', f.url))
     from pipeline.fee_reader_queue q join pipeline.provider_fact_sources f on f.id = q.fact_source_id
    where q.state = 'queued' and q.created_at > now() - interval '15 minutes'  -- fixed: the tick runs every 10 minutes
      and exists (select 1 from pipeline.fee_reader_queue o where o.fact_source_id = q.fact_source_id and o.content_hash <> q.content_hash and o.state = 'done');

  -- 3 rows a person rejected or corrected in Layer 4 are findings the reader learns from
  with r as (
    select l.entity_id course_id, fr.provider_id, fr.qualification, l.status decision
      from pipeline.layer4_review_items l
      join pipeline.fee_reader_rows fr on fr.course_id = l.entity_id and fr.outcome = 'review'
     where l.field_code = 'provider_current_tuition_validation' and l.status in ('rejected', 'edited_approved') and l.layer2_state->>'source' = 'fee reader'
       and l.decided_at > now() - interval '1 day')  -- fixed: look-back longer than the 10-minute tick
  select count(*) into v_rejected from (
    select security.fee_reader_finding_v1(r.provider_id, null, 'rejected', r.course_id::text,
             jsonb_build_object('qualification', r.qualification, 'decision', r.decision)) from r) z;

  -- 2b course pages that show one international fee for a course with no fee held (CF-247 23 Oct 2026)
  v_queued := v_queued + security.fee_course_pages_enqueue_v1();

  -- 4 the worker, while there is work and AI budget
  if exists (select 1 from pipeline.fee_reader_queue q where q.state = 'queued' or (q.state = 'leased' and q.leased_until < now()))
     -- 4 Nov 2026 (SS-021 F9, IQ-00134; wc.fee_item_claims_on): each page is claimed on its own (public.svc_fee_ai_next leases per page, skip
     -- locked), so the worker is called while fewer than wc.fee_live_leases_max pages are leased, not only when no lease is live anywhere
     and (case when security.pipeline_num_v1('wc.fee_item_claims_on', 0) >= 1
               then (select count(*) from pipeline.fee_reader_queue q where q.state = 'leased' and q.leased_until > now()) < security.pipeline_num_v1('wc.fee_live_leases_max', 6)
               else not exists (select 1 from pipeline.fee_reader_queue q where q.state = 'leased' and q.leased_until > now()) end)
     and security.ai_use_allowed_v1('fee_ai') then
    perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'fee_ai', 'limit', security.pipeline_num_v1('fees.pages_per_run', 3)::int, 'concurrency', security.pipeline_num_v1('fees.concurrency', 4)::int));
    v_fired := 1;
  end if;
  return jsonb_build_object('pages_added', v_added, 'queued', v_queued, 'rejected_seen', v_rejected, 'worker', v_fired);
end $$;


ALTER FUNCTION "security"."fee_reader_tick_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fee_reader_yearly_v1"("p_row" "jsonb", "p_country" "text", "p_course" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare pr pipeline.fee_country_profiles%rowtype; v_units int := security.fee_row_units_v1(p_row); v_amt numeric := nullif(p_row->>'amount_min', '')::numeric;
        v_q text := coalesce(p_row->>'quote', ''); v_kind text; v_load numeric; v_years numeric; v_whole boolean; v_per numeric; v_method text; v_how text;
        v_hold text; v_implied numeric; v_tol numeric := security.pipeline_num_v1('fees.units_agreement_pct', 20) / 100.0; v_word text;
begin
  if coalesce(v_units, 0) <= 0 or coalesce(v_amt, 0) <= 0 then return null; end if;
  select * into pr from pipeline.fee_country_profiles where country_code = p_country;
  v_kind := case when p_row->>'units_kind' in ('units', 'credit_points') then p_row->>'units_kind'
                 when v_q ~* '(credit\s*points?|\mpoints?\M|\mcredits?\M|\muoc\M|\mcp\M)' then 'credit_points'
                 when v_q ~* '\m(units?|subjects?|modules?)\M' then 'units' end;
  v_word := coalesce(replace(v_kind, '_', ' '), 'points or units');
  v_load := case when nullif(p_row->>'full_time_load', '')::numeric > 0 then (p_row->>'full_time_load')::numeric end;
  v_years := case when nullif(p_row->>'course_years', '')::numeric > 0 then (p_row->>'course_years')::numeric end;
  if v_years is null then
    select case c.duration_unit when 'weeks' then c.duration_value / 52.0 when 'months' then c.duration_value / 12.0 when 'years' then c.duration_value end  -- fixed: calendar conversions
      into v_years from catalogue.courses c where c.id = p_course;
    if v_years <= 0 then v_years := null; end if;
  end if;
  v_whole := coalesce(case when p_row->>'whole_course' in ('true', 'false') then (p_row->>'whole_course')::boolean end, false)
          or v_q ~* '(\m(full|total|entire|whole)\M[^|]{0,40}\m(course|degree|program|programme|qualification)\M|\mto complete\M)';
  if v_load is not null then
    v_method := 'page_load'; v_per := v_amt / v_units * v_load;
    v_how := 'yearly figure from ' || v_amt || ' for ' || v_units || ' ' || v_word || ' (the page gives ' || v_load || ' a full-time year)';
  elsif v_kind is not null and v_kind = pr.units_are and pr.full_time_units_a_year > 0 then
    v_load := pr.full_time_units_a_year; v_method := 'country_profile'; v_per := v_amt / v_units * v_load;
    v_how := 'yearly figure from ' || v_amt || ' for ' || v_units || ' ' || v_word || ' (a full-time year is ' || v_load || ' ' || coalesce(pr.unit_name, v_word) || ')';
  elsif v_whole and v_years >= 1 then
    v_method := 'course_length'; v_per := v_amt / v_years;
    v_how := 'yearly figure from ' || v_amt || ' for the whole course over ' || round(v_years, 2) || ' years';
  end if;
  if v_load is not null then
    v_implied := v_units / v_load;
    if v_years is not null and (v_whole or v_implied > 1) and abs(v_implied - v_years) > v_tol * greatest(v_years, 1) then
      v_hold := v_units || ' ' || v_word || ' at ' || v_load || ' a year is ' || round(v_implied, 2) || ' years, but the course is ' || round(v_years, 2) || ' years';
      if v_years >= 1 then
        v_method := 'course_length'; v_per := v_amt / v_years;
        v_how := 'yearly figure from ' || v_amt || ' over the course length of ' || round(v_years, 2) || ' years';
      end if;
    end if;
  elsif v_per is null then
    v_hold := case when v_whole and v_years is not null
                   then v_amt || ' is the whole fee of a course of ' || round(v_years, 2) || ' years and the page gives no full-time load'
                   else 'the page does not say what the ' || v_units || ' ' || v_word || ' are or what a full-time year is' end;
    v_method := 'published'; v_per := v_amt;
    v_how := 'published figure ' || v_amt || ' for ' || v_units || ' ' || v_word || ', not converted';
  end if;
  return jsonb_build_object('yearly', round(v_per, 2),
    'basis', case when v_hold is null and v_load is not null and v_units = v_load then 'annual' else 'indicative_annual' end,
    'unit', case when v_hold is null and v_load is not null and v_units = v_load then 'per_year' else 'per_course' end,
    'method', v_method, 'how', v_how, 'hold', v_hold, 'units_kind', v_kind, 'full_time_load', v_load, 'course_years', round(v_years, 2));
end $$;


ALTER FUNCTION "security"."fee_reader_yearly_v1"("p_row" "jsonb", "p_country" "text", "p_course" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."fee_reader_yearly_v1"("p_row" "jsonb", "p_country" "text", "p_course" "uuid") IS 'CF-247 IQ-00111: the yearly figure of an AI fee row for a stated count of points, credits or units, how it was made, and why it is held when it is not clear. Used by public.svc_fee_ai_record while fees.units_load_fix_on is on.';



CREATE OR REPLACE FUNCTION "security"."fee_row_units_v1"("p_row" "jsonb") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  -- CF-247 22 Oct 2026: points or credits a fee row's amount is for, from the quote ("$19,929.84 (for 60 points)", "$27,300 (60 points)",
  -- "$41,859.67 for 120 credits"); never for a per-term row or a quote that says per point / per credit / per paper
  select case
    when coalesce(p_row->>'unit', '') = 'per_term' then null
    when coalesce(p_row->>'quote', '') ~* '(\m(per|each)\s+(point|credit|paper)\M|/\s*(point|credit|paper)\M)' then null
    else nullif(coalesce(
      (select m[1]::int from regexp_match(coalesce(p_row->>'quote', ''), '\d[\d,]*(?:\.\d{1,2})?\s*\(\s*(?:for\s+)?(\d{1,3})\s*(?:points?|credits?|pts)\M', 'i') m),
      (select m[1]::int from regexp_match(coalesce(p_row->>'quote', ''), '\d[\d,]*(?:\.\d{1,2})?\s+for\s+(\d{1,3})\s*(?:points?|credits?|pts)\M', 'i') m),
      case when p_row->>'unit' = 'per_course' and coalesce(p_row->>'units_covered', '') ~ '^\d{1,3}(\.0+)?$' then (p_row->>'units_covered')::numeric::int end), 0)
  end
$_$;


ALTER FUNCTION "security"."fee_row_units_v1"("p_row" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."fee_row_units_v1"("p_row" "jsonb") IS 'CF-247 22 Oct 2026: points or credits a fee row''s amount covers, from its quote or the reader''s units_covered for a whole-course fee; null when not stated.';



CREATE OR REPLACE FUNCTION "security"."fee_rule_matches"("p_provider_id" "uuid", "p_phrase" "text", "p_url_pattern" "text" DEFAULT NULL::"text") RETURNS TABLE("course_id" "uuid", "evidence_id" "uuid", "url" "text", "amount" numeric, "fee_year" integer, "matched_text" "text", "amounts" integer, "has_fee" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $_$
  with q as (select regexp_replace(btrim(p_phrase), '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') ph),
  m as (
    select g.course_id, g.evidence_id, g.url, x.ctx, q.ph,
           regexp_match(x.ctx, '(?i)' || q.ph || '((?:[^$0-9]|20[2-3][0-9]){0,30}?)(?:A\$|AUD\s*\$?|\$)\s*([0-9]{1,3}(?:,[0-9]{3})+|[0-9]{4,6})(?![0-9]|,[0-9])') mm
      from q, pipeline.coverage_course_pages g
      cross join lateral (select distinct c->>'context' ctx from jsonb_array_elements(coalesce(g.candidates->'fee'->'candidates', '[]'::jsonb)) c) x
     where g.provider_id = p_provider_id and g.read_status = 'read' and g.identity_basis in ('cricos_code','manual') and g.evidence_id is not null
       and (p_url_pattern is null or g.url ~* p_url_pattern)),
  hit as (select *, coalesce(substring(mm[1] from '(20[2-3][0-9])'), substring(ctx from '(?i)(20[2-3][0-9])[^0-9$]{0,6}' || ph))::int yr from m where mm is not null)
  select h.course_id, min(h.evidence_id::text)::uuid, min(h.url),
         min(replace(h.mm[2], ',', '')::numeric), min(h.yr),
         min(left(btrim(coalesce(h.yr::text || ' ', '') || btrim(p_phrase) || h.mm[1] || '$' || h.mm[2]), 200)),
         count(distinct h.mm[2])::int,
         exists (select 1 from catalogue.course_fees f where f.course_id = h.course_id and f.fee_type = 'provider_current_tuition' and f.status = 'active')
    from hit h group by h.course_id
$_$;


ALTER FUNCTION "security"."fee_rule_matches"("p_provider_id" "uuid", "p_phrase" "text", "p_url_pattern" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fee_rule_run_v1"("p_rule_id" bigint, "p_apply" boolean, "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.fee_wording_rules%rowtype; m record; v_src uuid; v_fee uuid; n_ok int := 0; n_amb int := 0; n_has int := 0; n_locked int := 0;
        v_courses uuid[] := '{}'; v_op bigint;
begin
  select * into r from pipeline.fee_wording_rules where id = p_rule_id;
  if r.id is null then raise exception 'rule not found'; end if;
  for m in select * from security.fee_rule_matches(r.provider_id, r.phrase, r.url_pattern) loop
    if m.amounts > 1 then n_amb := n_amb + 1; continue; end if;
    if m.has_fee then n_has := n_has + 1; continue; end if;
    if exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = m.course_id and l.field = 'tuition') then n_locked := n_locked + 1; continue; end if;
    if not p_apply then n_ok := n_ok + 1; continue; end if;
    select source_id into v_src from pipeline.evidence_artifacts where id = m.evidence_id;
    v_fee := null;
    insert into catalogue.course_fees(course_id, fee_year, audience, fee_type, amount, currency_code, basis, notes, source_id, evidence_id, confidence, source_fee_key, status, last_verified_at, source_snapshot_at, updated_at)
    values (m.course_id, m.fee_year, 'international', 'provider_current_tuition', m.amount, 'AUD', r.basis,
            format('CF-247 Layer 4 fee wording rule #%s (%s)', r.id, r.label), v_src, m.evidence_id, 1,
            'fee-rule:' || r.id || ':' || coalesce(m.fee_year::text, '') || ':' || r.basis, 'active', now(), now(), now())
    on conflict (course_id, source_id, source_fee_key) where source_id is not null and source_fee_key is not null do nothing
    returning id into v_fee;
    if v_fee is null then n_has := n_has + 1; continue; end if;
    update pipeline.layer4_review_items set status = 'superseded', decided_at = now(),
           escalation_reason = format('Settled by Layer 4 fee wording rule #%s (%s)', r.id, r.label)
     where entity_type = 'course' and entity_id = m.course_id and field_code = 'provider_current_tuition_validation' and status in ('pending','returned_layer3');
    update pipeline.layer3_work_items set status = 'admitted', completed_at = now(), last_error = null, updated_at = now()
     where entity_id = m.course_id and task_class = 'provider_current_tuition_validation' and status in ('pending','layer4_required','failed','no_candidate','rejected');
    insert into pipeline.fee_rule_admissions(rule_id, course_id, course_fee_id, amount, fee_year, basis, matched_text)
    values (r.id, m.course_id, v_fee, m.amount, m.fee_year, r.basis, m.matched_text);
    v_courses := v_courses || m.course_id; n_ok := n_ok + 1;
  end loop;
  if p_apply then
    update pipeline.fee_wording_rules set last_run_at = now(), admitted = admitted + n_ok where id = r.id;
    if n_ok > 0 then
      insert into pipeline.layer4_mass_operations(target_kind, action, actor_id, group_key, reason, before_count, affected_count, result, change_control_ref)
      values ('course_tuition', 'fee_wording_rule_run', coalesce(p_actor, r.approved_by, r.created_by), jsonb_build_object('rule_id', r.id, 'provider_id', r.provider_id, 'phrase', r.phrase),
              format('Fee wording rule #%s: %s', r.id, r.label), n_ok + n_amb + n_has + n_locked, n_ok,
              jsonb_build_object('admitted', n_ok, 'ambiguous', n_amb, 'already_had_fee', n_has, 'entered_by_hand', n_locked), 'CF-CHG-20260915-247');
      perform search.refresh_course_enrichment_scoped_v1(v_courses, true);
    end if;
  end if;
  return jsonb_build_object('mode', case when p_apply then 'run' else 'preview' end, 'admitted', n_ok, 'ambiguous', n_amb, 'already_had_fee', n_has, 'entered_by_hand', n_locked);
end $$;


ALTER FUNCTION "security"."fee_rule_run_v1"("p_rule_id" bigint, "p_apply" boolean, "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fee_rules_run_active_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v jsonb := '[]'::jsonb;
begin
  for r in select id from pipeline.fee_wording_rules where status = 'active' order by id loop
    v := v || jsonb_build_object('rule', r.id, 'result', security.fee_rule_run_v1(r.id, true, null));
  end loop;
  return v;
end $$;


ALTER FUNCTION "security"."fee_rules_run_active_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fee_schedule_settle_flags_v1"("p_source_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_same int := 0; v_period int := 0; v_courses uuid[] := '{}';
begin
  for r in
    with sched as (
      select fr.provider_id, fr.course_code, fr.amount, fr.fee_year, s.id source_id,
             min(fr.amount) over (partition by fr.source_id, fr.course_code) amin, max(fr.amount) over (partition by fr.source_id, fr.course_code) amax,
             row_number() over (partition by fr.provider_id, fr.course_code order by fr.fee_year desc nulls last, s.decided_at desc) pick
        from pipeline.provider_fee_rows fr join pipeline.provider_fact_sources s on s.id = fr.source_id
       where s.decision = 'approved' and fr.current and fr.basis = 'annual' and (p_source_id is null or s.id = p_source_id))
    select f.id flag_id, f.entity_id course_id, fe.id fee_id, fe.amount, sc.amount sched_amount, sc.fee_year, sc.source_id
      from pipeline.data_flags f
      join catalogue.course_fees fe on fe.id = f.record_id and fe.status = 'active'
      join catalogue.courses c on c.id = f.entity_id
      join sched sc on sc.provider_id = c.provider_id and sc.course_code = upper(btrim(c.course_code)) and sc.pick = 1 and sc.amin = sc.amax
     where f.status = 'open' and f.flag_code = 'tuition_period_assumed_annual'
     for update of f
  loop
   begin
    if r.amount = r.sched_amount then
      update catalogue.course_fees set fee_year = coalesce(fee_year, r.fee_year), last_verified_at = now(), updated_at = now(),
             notes = coalesce(notes, '') || format(' | per year confirmed by the approved fee schedule (%s) %s', coalesce(r.fee_year::text, 'year not stated'), to_char(now(), 'DD Mon YYYY'))
       where id = r.fee_id;
      update pipeline.data_flags set status = 'confirmed', resolved_at = now(),
             resolution = jsonb_build_object('action', 'confirmed_by_fee_schedule', 'source_id', r.source_id, 'fee_year', r.fee_year, 'schedule_amount', r.sched_amount)
       where id = r.flag_id;
      v_same := v_same + 1; v_courses := v_courses || r.course_id;
    elsif r.amount > 0 and r.sched_amount / r.amount between 0.85 and 1.15 then
      update catalogue.course_fees set last_verified_at = now(), updated_at = now(),
             notes = coalesce(notes, '') || format(' | per year supported by the approved fee schedule (%s a year in %s) %s', r.sched_amount, coalesce(r.fee_year::text, 'year not stated'), to_char(now(), 'DD Mon YYYY'))
       where id = r.fee_id;
      update pipeline.data_flags set status = 'confirmed', resolved_at = now(),
             resolution = jsonb_build_object('action', 'period_confirmed_by_fee_schedule', 'source_id', r.source_id, 'fee_year', r.fee_year, 'schedule_amount', r.sched_amount)
       where id = r.flag_id;
      v_period := v_period + 1; v_courses := v_courses || r.course_id;
    end if;
   exception when others then null; -- a value locked by hand is left for a person
   end;
  end loop;
  if cardinality(v_courses) > 0 then perform search.refresh_course_enrichment_scoped_v1(v_courses, true); end if;
  return jsonb_build_object('confirmed_same_fee', v_same, 'confirmed_period', v_period);
end $$;


ALTER FUNCTION "security"."fee_schedule_settle_flags_v1"("p_source_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fee_suggest_phrase"("p_ctx" "text", "p_amount" numeric) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare a text := to_char(p_amount, 'FM999,999,999'); p int; pre text; tail text;
begin
  p := strpos(coalesce(p_ctx, ''), a);
  if p = 0 then return null; end if;
  pre := left(p_ctx, p - 1);
  pre := regexp_replace(pre, '(A\$|AUD\s*\$?|\$)\s*$', '');
  pre := regexp_replace(pre, '[\s:*>-]*$', '');
  pre := regexp_replace(pre, '\s*(20[2-3][0-9])(\s+(are|is))?$', '');
  tail := right(pre, 60);
  if tail ~ '20[2-3][0-9]' then tail := regexp_replace(tail, '^.*20[2-3][0-9]\s*', ''); else tail := regexp_replace(tail, '^\S*\s+', ''); end if;
  if position('. ' in tail) > 0 and length(regexp_replace(tail, '^.*\.\s+', '')) >= 12 then tail := regexp_replace(tail, '^.*\.\s+', ''); end if;
  tail := btrim(regexp_replace(tail, '\s+', ' ', 'g'));
  if length(tail) < 8 or tail !~ '[A-Za-z]{3}' then return null; end if;
  return tail;
end $_$;


ALTER FUNCTION "security"."fee_suggest_phrase"("p_ctx" "text", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fee_title_similarity_v1"("a" "text", "b" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  -- share of the course title's words found in the fee row's words (qualification and subject together)
  select case when cardinality(security.fee_title_words_v1(b)) = 0 then 0
              else round(cardinality(array(select unnest(security.fee_title_words_v1(b)) intersect select unnest(security.fee_title_words_v1(a))))::numeric
                         / cardinality(security.fee_title_words_v1(b)), 3) end
$$;


ALTER FUNCTION "security"."fee_title_similarity_v1"("a" "text", "b" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."fee_title_words_v1"("p" "text") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(array(select distinct w from regexp_split_to_table(lower(regexp_replace(coalesce(p, ''), '\(level [0-9]+\)|&#[0-9]+;|[^a-zA-Z0-9 ]', ' ', 'g')), '\s+') w
                  where length(w) > 1 and w not in ('of', 'in', 'and', 'the', 'with', 'for', 'level', 'honours', 'hons')), '{}')
$$;


ALTER FUNCTION "security"."fee_title_words_v1"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."field_absence_classify_v1"("p_item" bigint) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.field_enrich_items%rowtype; r record; k pipeline.field_absence_classes%rowtype; v_class text; v_conf numeric; v_stored boolean; v_next timestamptz;
        v_reader text := nullif(current_setting('cf247.reader_version', true), '');
begin
  select * into i from pipeline.field_enrich_items where id = p_item;
  if i.id is null or i.course_id is null then return null; end if;
  if i.state in ('filled', 'review') then
    update pipeline.course_field_absence set resolved_at = now(), item_id = i.id where course_id = i.course_id and field = i.field and resolved_at is null;
    return 'resolved';
  end if;
  if i.state not in ('skipped', 'failed') then return null; end if;
  v_stored := exists (select 1 from pipeline.coverage_course_pages g where g.course_id = i.course_id and g.evidence_id is not null and g.read_status = 'read');
  select x.* into r from pipeline.field_absence_rules x
   where x.active and (x.fields is null or i.field = any (x.fields)) and (x.item_states is null or i.state = any (x.item_states))
     and (x.sources is null or coalesce(i.source, '') = any (x.sources)) and (x.stored_page is null or x.stored_page = v_stored)
     and coalesce(i.reason, '') ~* x.reason_pattern
   order by x.priority, x.id limit 1;
  if r.id is not null and r.absence_class is null then return 'kept'; end if;
  v_class := coalesce(r.absence_class, 'evidence_pending'); v_conf := coalesce(r.confidence, 0.2);
  -- evidence-aware refinements
  if v_class = 'not_on_this_page' and security.field_absence_other_page_v1(i.course_id, i.field) then v_class := 'on_other_stored_page'; end if;
  if v_class in ('not_on_this_page', 'on_other_stored_page') and i.field = 'campus'
     and exists (select 1 from catalogue.courses c where c.id = i.course_id and c.delivery_mode = 'online') then v_class := 'not_applicable'; end if;
  select * into k from pipeline.field_absence_classes where code = v_class;
  -- D3: only a stored page that a reader read makes a negative; a source or adapter that returned nothing never does
  if k.verified_negative and (i.source is distinct from 'ai_stored' or i.evidence_id is null) then
    v_class := case when v_stored then 'evidence_pending' else 'needs_source_discovery' end; v_conf := least(v_conf, 0.3);
    select * into k from pipeline.field_absence_classes where code = v_class;
  end if;
  v_next := case k.reeval_trigger when 'date' then now() + make_interval(hours => security.pipeline_num_v1('absence.pending_recheck_hours', 24)::int)
                                  when 'none' then now() end;
  insert into pipeline.course_field_absence as a (course_id, field, absence_class, evidence_id, content_hash, reader_version, confidence, reason, next_eligible_at, reeval_trigger, item_id, classified_at, resolved_at)
  values (i.course_id, i.field, v_class, i.evidence_id, (select e.content_hash from pipeline.evidence_artifacts e where e.id = i.evidence_id),
          left(coalesce(v_reader, coalesce(i.source, 'none') || ' (no reader)'), 200), v_conf, left(i.reason, 300), v_next, k.reeval_trigger, i.id, now(), null)
  on conflict (course_id, field) do update set absence_class = excluded.absence_class, evidence_id = excluded.evidence_id, content_hash = excluded.content_hash,
         reader_version = excluded.reader_version, confidence = excluded.confidence, reason = excluded.reason, next_eligible_at = excluded.next_eligible_at,
         reeval_trigger = excluded.reeval_trigger, item_id = excluded.item_id, classified_at = now(), resolved_at = null;
  return v_class;
end $$;


ALTER FUNCTION "security"."field_absence_classify_v1"("p_item" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."field_absence_classify_v1"("p_item" bigint) IS 'CF-247 Release B (D2, D3): records why a settled Enrich fields item left its course field empty (pipeline.field_absence_rules, then evidence: another stored reading, online-only campus, and a negative only from a stored page a reader read), or resolves the record when a value is filled or sent to Layer 4.';



CREATE OR REPLACE FUNCTION "security"."field_absence_d1_decision_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "statement_timeout" TO '30s'
    AS $_$
declare v_since timestamptz := now() - make_interval(days => security.pipeline_num_v1('recovery.d1_history_days', 60)::int);
        v_read numeric; v_read_ok numeric; h jsonb; v_rows jsonb;
begin
  select coalesce(avg(f.credits_used) filter (where f.outcome like 'read_%'), security.pipeline_num_v1('recovery.d1_read_credits', 1)),
         coalesce(avg((f.outcome = 'read_course_page')::int), 0) into v_read, v_read_ok
    from pipeline.firecrawl_calls f where f.use_case = 'read_page' and f.at >= v_since;
  with fc as (select f.course_id, count(*) calls, sum(f.credits_used) cr, bool_or(f.outcome = 'found_on_provider_site') found,
                     count(distinct f.at::date) days
                from pipeline.firecrawl_calls f where f.use_case = 'find_page' and f.at >= v_since and f.course_id is not null group by 1),
  j as (select fc.*, coalesce(s.stage, 'title') stage, s.state = 'verified' verified from fc left join pipeline.course_link_search s on s.course_id = fc.course_id)
  select jsonb_object_agg(z.k, z.v) into h from (
    select j.stage k, jsonb_build_object('courses', count(*), 'credits_per_course', round(avg(j.cr), 2), 'found_rate', round(avg(j.found::int), 3),
                                         'verified_rate', round(avg(coalesce(j.verified, false)::int), 3)) v from j group by j.stage
    union all
    select 'repeat', jsonb_build_object('courses', count(*), 'credits_per_course', round(avg(j.cr), 2), 'found_rate', round(avg(j.found::int), 3),
                                        'verified_rate', round(avg(coalesce(j.verified, false)::int), 3)) from j where j.days > 1) z;
  with c as (select fr.*, case when c.course_code ~ '^[0-9]{6}[0-9A-Z]$' then 'cricos' else 'title' end stage  -- fixed: the CRICOS code form
               from pipeline.field_absence_recovery fr join catalogue.courses c on c.id = fr.course_id
              where fr.state in ('needs_paid_discovery', 'needs_paid_research', 'needs_authorised_read')),
  k as (select c.state, c.stage, count(*) n,
               case when c.state = 'needs_authorised_read' then v_read_ok  -- the page is known: the measured share of page reads that read a course page
                    when c.state = 'needs_paid_research' then coalesce((h->'repeat'->>'verified_rate')::numeric, 0)
                    else coalesce((h->c.stage->>'verified_rate')::numeric, 0) end vr,
               case when c.state = 'needs_authorised_read' then v_read
                    when c.state = 'needs_paid_research' then coalesce((h->'repeat'->>'credits_per_course')::numeric, (h->c.stage->>'credits_per_course')::numeric, 0)
                                                              + coalesce((h->'repeat'->>'found_rate')::numeric, 0) * v_read
                    else coalesce((h->c.stage->>'credits_per_course')::numeric, 0) + coalesce((h->c.stage->>'found_rate')::numeric, 0) * v_read end cpc,
               case when c.state = 'needs_authorised_read' then v_read_ok else coalesce((h->(case when c.state = 'needs_paid_research' then 'repeat' else c.stage end)->>'found_rate')::numeric, 0) end fr,
               count(distinct c.provider_id) providers
          from c group by c.state, c.stage)
  select coalesce(jsonb_agg(jsonb_build_object('state', k.state, 'stage', k.stage, 'courses', k.n, 'providers', k.providers,
           'credits_per_course', round(k.cpc, 2), 'credits_total', round(k.n * k.cpc), 'expected_found', round(k.n * k.fr), 'expected_verified', round(k.n * k.vr),
           'credits_per_verified', case when k.vr > 0 then round(k.cpc / k.vr, 1) end) order by k.state, k.stage), '[]'::jsonb) into v_rows from k;
  return jsonb_build_object('at', now(), 'history_since', v_since, 'history', h, 'read_credits_per_page', round(v_read, 2), 'read_course_page_rate', round(v_read_ok, 3), 'rows', v_rows,
    'cohort', (select coalesce(jsonb_object_agg(z.state, z.n), '{}'::jsonb) from (select fr.state, count(*) n from pipeline.field_absence_recovery fr group by 1) z),
    'paid_search_enabled', security.pipeline_num_v1('proof.search_per_run', 0) > 0);
end $_$;


ALTER FUNCTION "security"."field_absence_d1_decision_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."field_absence_due_v1"("p_course" "uuid", "p_field" "text", "p_ev" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with a as (select * from pipeline.course_field_absence a where a.course_id = p_course and a.field = p_field and a.resolved_at is null),
  cur as (select coalesce(p_ev, (select g.evidence_id from pipeline.coverage_course_pages g where g.course_id = p_course and g.read_status = 'read')) ev),
  h as (select cur.ev, (select e.content_hash from pipeline.evidence_artifacts e where e.id = cur.ev) hash from cur)
  select case when not exists (select 1 from a) then true
    else (select case a.reeval_trigger
            when 'page_change' then h.ev is not null and case when h.hash is not null and a.content_hash is not null then h.hash <> a.content_hash else h.ev is distinct from a.evidence_id end
            when 'new_page' then h.ev is not null
            when 'identity_change' then h.ev is distinct from a.evidence_id
                                     or exists (select 1 from pipeline.course_page_proofs y where y.course_id = p_course and y.proven and y.checked_at > a.classified_at)
            when 'intake_added' then exists (select 1 from catalogue.course_intakes x where x.course_id = p_course and x.status = 'active')
                                  or (h.ev is not null and h.ev is distinct from a.evidence_id)
            when 'date' then coalesce(a.next_eligible_at <= now(), true)
            else true end
          from a, h) end
$$;


ALTER FUNCTION "security"."field_absence_due_v1"("p_course" "uuid", "p_field" "text", "p_ev" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."field_absence_due_v1"("p_course" "uuid", "p_field" "text", "p_ev" "uuid") IS 'CF-247 Release B (D2): whether a course field''s open absence is due again: a changed copy (content hash), a new stored page, a resolved page identity, an added intake, or its date (pipeline.field_absence_classes.reeval_trigger).';



CREATE OR REPLACE FUNCTION "security"."field_absence_other_page_v1"("p_course" "uuid", "p_field" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with x as (select coalesce((select r.fields->'extra' from pipeline.uni_adapter_results r where r.course_id = p_course order by r.at desc limit 1), '{}'::jsonb)
                    || coalesce((select g.candidates->'adapter_extra' from pipeline.coverage_course_pages g where g.course_id = p_course), '{}'::jsonb) e,
                    (select g.candidates from pipeline.coverage_course_pages g where g.course_id = p_course) c)
  select coalesce(case p_field
           when 'campus' then nullif(btrim(coalesce(x.e->>'campus', x.e->>'location')), '') is not null
           when 'duration' then nullif(btrim(x.e->>'duration'), '') is not null
           when 'delivery' then nullif(btrim(x.e->>'mode'), '') is not null
           when 'international' then nullif(btrim(x.e->>'student_type'), '') is not null
           when 'intakes' then jsonb_typeof(x.c->'intakes') = 'array' and jsonb_array_length(x.c->'intakes') > 0
           when 'english' then coalesce(x.c->'english' ? 'ielts_overall', false)
           else false end, false)
    from x
$$;


ALTER FUNCTION "security"."field_absence_other_page_v1"("p_course" "uuid", "p_field" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."field_absence_other_page_v1"("p_course" "uuid", "p_field" "text") IS 'CF-247 Release B (D2): another stored reading of the course (its latest adapter reading or the page reading''s candidates) holds a value for the field: on_other_stored_page, not a negative.';



CREATE OR REPLACE FUNCTION "security"."field_absence_recovery_action_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_before jsonb := security.field_absence_recovery_measure_v1(); v_r jsonb;
begin
  v_r := security.field_absence_recovery_refresh_v1();
  return jsonb_build_object('ok', true, 'changed', coalesce((v_r->>'state_changes')::int, 0) + coalesce((v_r->>'entered')::int, 0),
                            'evidence', jsonb_build_object('issue', p_issue, 'before', v_before, 'refresh', v_r));
end $$;


ALTER FUNCTION "security"."field_absence_recovery_action_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."field_absence_recovery_classify_v1"("p_courses" "uuid"[]) RETURNS TABLE("course_id" "uuid", "provider_id" "uuid", "state" "text", "step" integer, "free_routes" "text"[], "fingerprint" "text", "searched_before" boolean, "search_credits" numeric, "filled" integer, "open_absences" integer, "detail" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rl text[] := security.course_relink_statuses_v1();
        v_blocked text[] := coalesce((select array(select jsonb_array_elements_text(s.value)) from pipeline.platform_toolset_settings s
                                       where s.toolset_key = 'pipeline' and s.key = 'recovery.read_blocked_statuses' and jsonb_typeof(s.value) = 'array'),
                                     array['fetch_failed', 'needs_render', 'blocked', 'robots_disallowed', 'too_thin']);
        v_tries int := greatest(1, security.pipeline_num_v1('recovery.read_tries', 3)::int);
        v_refused text[] := array['identity_mismatch', 'identity_refused', 'page_refused', 'refused_host', 'not_course_page'];  -- fixed: the refusal states the reader and the E16 check write
begin
  return query
  -- the paid course-page searches already made, read once (pipeline.firecrawl_calls has no course index)
  with fc as materialized (
    select f.course_id, sum(f.credits_used) cr from pipeline.firecrawl_calls f
     where f.use_case = 'find_page' and f.course_id = any (p_courses) group by f.course_id),
  b as materialized (
    select c.id cid, c.provider_id pid, c.canonical_title, g.status gstatus, g.read_status, coalesce(g.read_attempts, 0) ra, g.url page_url,
           coalesce(pp.proven, false) proven, pp.page_key, s.state sstate, x.state rstate, coalesce(jsonb_array_length(case when jsonb_typeof(x.candidates) = 'array' then x.candidates end), 0) rcands,
           q.state qstate,
           exists (select 1 from pipeline.layer4_review_items i where i.entity_id = c.id and i.field_code = 'official_course_url' and i.status = 'pending') l4,
           exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = c.id and k.field in ('official_url', 'course_url', 'all')) locked,
           coalesce(fc.cr, 0) paid, fc.course_id is not null paid_before,
           security.course_relink_stored_untried_v1(c.id) stored,
           security.course_relink_slugs_v1(c.canonical_title) slugs
      from unnest(p_courses) u(id) join catalogue.courses c on c.id = u.id
      left join pipeline.coverage_course_pages g on g.course_id = c.id
      left join pipeline.course_page_proofs pp on pp.course_id = c.id
      left join pipeline.course_link_search s on s.course_id = c.id
      left join pipeline.course_relink x on x.course_id = c.id
      left join pipeline.source_proof_requests q on q.course_id = c.id
      left join fc on fc.course_id = c.id),
  -- the provider's stored addresses, read once per provider (crawl lists and discovery links), keyed by last part and by stored title
  u as materialized (
    select l.provider_id, l.url, security.course_relink_url_seg_v1(l.url) seg,
           lower(btrim(split_part(split_part(coalesce(l.title, ''), ' | ', 1), ' - ', 1))) tnorm
      from (select pu.provider_id, pu.url, pu.title from pipeline.coverage_provider_urls pu where pu.provider_id in (select distinct b.pid from b)
            union select dl.provider_id, dl.url, dl.anchor_text from pipeline.provider_discovery_links dl where dl.provider_id in (select distinct b.pid from b)) l),
  hit as (
    select b.cid, u.url from b cross join lateral unnest(b.slugs) bs(slug) join u on u.provider_id = b.pid and u.seg = bs.slug
    union
    select b.cid, u.url from b join u on u.provider_id = b.pid and u.tnorm = lower(btrim(b.canonical_title)) where length(b.canonical_title) > 10),
  lm as (
    select b.cid, array_agg(distinct h.url order by h.url) urls
      from b join hit h on h.cid = b.cid
     where security.course_relink_url_norm_v1(h.url) is distinct from security.course_relink_url_norm_v1(b.page_url)
       and not exists (select 1 from pipeline.page_rejections pr where pr.course_id = b.cid and security.course_relink_url_norm_v1(pr.url) = security.course_relink_url_norm_v1(h.url))
       and not exists (select 1 from pipeline.course_relink x where x.course_id = b.cid and jsonb_typeof(x.candidates) = 'array'
                         and exists (select 1 from jsonb_array_elements_text(x.candidates) xc where security.course_relink_url_norm_v1(xc) = security.course_relink_url_norm_v1(h.url)))
     group by b.cid),
  f as (
    select b.*, coalesce(lm.urls, '{}') list_urls, security.course_relink_year_url_v1(b.page_url) year_url,
           (select count(*) from pipeline.field_enrich_items e join pipeline.field_absence_recovery fr on fr.course_id = e.course_id
             where e.course_id = b.cid and e.state in ('filled', 'review') and e.updated_at > fr.entered_at)::int filled,
           (select count(*) from pipeline.course_field_absence a where a.course_id = b.cid and a.resolved_at is null)::int open_abs
      from b left join lm on lm.cid = b.cid),
  r as (
    select f.*, array_remove(array[
             case when f.read_status = any (v_rl) and f.rstate is null then 'relink_capacity' end,
             case when f.read_status = any (v_refused) and not f.read_status = any (v_rl) and f.rstate is null then 'relink_refused_status' end,
             case when cardinality(f.stored) > 0 then 'stored_search' end,
             case when cardinality(f.list_urls) > 0 then 'provider_list' end,
             case when f.year_url is not null and f.read_status = any (v_refused) then 'canonical_year' end], null) routes
      from f)
  select r.cid, r.pid,
         case when r.proven then 'recovered_free'
              when r.l4 then 'waiting_layer4'
              when r.locked then 'locked'
              when r.rstate = 'trying' or r.sstate in ('queued', 'found') or r.qstate = 'queued'
                   or (r.gstatus in ('bound', 'ambiguous') and coalesce(r.read_status, '') in ('', 'deferred', 'fetch_failed', 'needs_render', 'blocked') and r.ra < v_tries) then 'waiting_current_work'
              when 'relink_capacity' = any (r.routes) then 'free_route_capacity'
              when 'relink_refused_status' = any (r.routes) then 'free_route_refused_status'
              when 'stored_search' = any (r.routes) then 'free_route_stored_search'
              when 'provider_list' = any (r.routes) then 'free_route_provider_list'
              when 'canonical_year' = any (r.routes) then 'free_route_canonical_year'
              when r.gstatus in ('bound', 'ambiguous') and r.read_status = any (v_blocked) then 'needs_authorised_read'
              when r.paid_before then 'needs_paid_research'
              else 'needs_paid_discovery' end,
         case when r.proven then null
              when 'relink_capacity' = any (r.routes) or 'relink_refused_status' = any (r.routes) then 2
              when 'canonical_year' = any (r.routes) and not ('stored_search' = any (r.routes) or 'provider_list' = any (r.routes)) then 3
              when 'provider_list' = any (r.routes) then 4
              when 'stored_search' = any (r.routes) then 6
              when r.gstatus in ('bound', 'ambiguous') and r.read_status = any (v_blocked) then 6
              else 8 end,
         r.routes,
         md5(concat_ws('|', r.page_key, array_to_string(r.stored, ' '), array_to_string(r.list_urls, ' '), r.year_url)),  -- inputs only: a lane's own outcome never re-triggers it
         r.paid_before, r.paid, r.filled, r.open_abs,
         jsonb_build_object('read_status', r.read_status, 'page_status', r.gstatus, 'relink', r.rstate, 'search', r.sstate,
                            'stored_candidates', cardinality(r.stored), 'list_candidates', cardinality(r.list_urls), 'year_url', r.year_url)
    from r;
end $$;


ALTER FUNCTION "security"."field_absence_recovery_classify_v1"("p_courses" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."field_absence_recovery_measure_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('at', now(),
    'cohort', (select count(*) from pipeline.field_absence_recovery),
    'cohort_proven', (select count(*) from pipeline.field_absence_recovery fr join pipeline.course_page_proofs pp on pp.course_id = fr.course_id and pp.proven),
    'cohort_recovered', (select count(*) from pipeline.field_absence_recovery fr where fr.state = 'recovered_free'),
    'cohort_filled', (select coalesce(sum(fr.filled_since_entry), 0) from pipeline.field_absence_recovery fr),
    'needs_paid', (select count(*) from pipeline.field_absence_recovery fr where fr.state in ('needs_paid_discovery', 'needs_paid_research')),
    'proven_pages', (select count(*) from pipeline.course_page_proofs pp where pp.proven))
$$;


ALTER FUNCTION "security"."field_absence_recovery_measure_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."field_absence_recovery_refresh_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int := greatest(1, security.pipeline_num_v1('recovery.cohort_refresh_per_run', 3000)::int);
        v_t0 timestamptz := clock_timestamp(); v_in int; v_ids uuid[]; v_chg int := 0; v_rec int := 0; v_states jsonb;
begin
  insert into pipeline.field_absence_recovery(course_id, provider_id, entered_route, detail)
  select q.course_id, q.provider_id, q.route || case when q.route = 'relink' then ':' || q.state else '' end, jsonb_build_object('entered_from', q.detail)
    from pipeline.source_proof_requests q join catalogue.courses c on c.id = q.course_id
   where q.route in ('no_route', 'exhausted') or (q.route = 'relink' and q.state = 'held')
      or (q.route = 'relink' and q.state = 'done' and q.outcome in ('relink_absent', 'not_taken'))  -- relinked again and still no page
  on conflict (course_id) do nothing;
  get diagnostics v_in = row_count;
  v_ids := array(select fr.course_id from pipeline.field_absence_recovery fr order by fr.refreshed_at nulls first, fr.course_id limit v_n);
  with o as (select fr.course_id, fr.state, fr.recovered_at from pipeline.field_absence_recovery fr where fr.course_id = any (v_ids)),
  k as (select * from security.field_absence_recovery_classify_v1(v_ids)),
  u as (
    update pipeline.field_absence_recovery fr set
           state = k.state, step = k.step, free_routes = k.free_routes,
           state_changed_at = case when fr.state is distinct from k.state then now() else fr.state_changed_at end,
           fingerprint_changed_at = case when fr.fingerprint is distinct from k.fingerprint then now() else fr.fingerprint_changed_at end,
           fingerprint = k.fingerprint, searched_before = k.searched_before, search_credits = k.search_credits,
           recovered_at = case when k.state = 'recovered_free' then coalesce(fr.recovered_at, now()) else fr.recovered_at end,
           filled_since_entry = k.filled, open_absences = k.open_absences, detail = fr.detail || k.detail, refreshed_at = now()
      from k where fr.course_id = k.course_id
    returning fr.course_id, fr.state)
  select count(*) filter (where o.state is distinct from u.state), count(*) filter (where u.state = 'recovered_free' and o.recovered_at is null) into v_chg, v_rec
    from u join o on o.course_id = u.course_id;
  select coalesce(jsonb_object_agg(z.state, z.n), '{}'::jsonb) into v_states from (select fr.state, count(*) n from pipeline.field_absence_recovery fr group by 1) z;
  insert into pipeline.field_absence_recovery_runs(outcome, entered, refreshed, state_changes, recovered, states, ms)
  values (case when cardinality(v_ids) = 0 then 'idle' else 'done' end, v_in, cardinality(v_ids), v_chg, v_rec, v_states,
          (extract(epoch from clock_timestamp() - v_t0) * 1000)::int);  -- fixed: milliseconds
  return jsonb_build_object('entered', v_in, 'refreshed', cardinality(v_ids), 'state_changes', v_chg, 'recovered', v_rec, 'states', v_states,
                            'ms', (extract(epoch from clock_timestamp() - v_t0) * 1000)::int);  -- fixed: milliseconds
end $$;


ALTER FUNCTION "security"."field_absence_recovery_refresh_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."field_absence_recovery_verify_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_before jsonb; v_after jsonb := security.field_absence_recovery_measure_v1(); v_dp int; v_df int;
begin
  select coalesce(x.before, x.evidence->'before') into v_before from pipeline.ops_remedy_runs x
   where x.issue_id = p_issue and x.remedy_code like 'rem_source_recovery%' order by x.started_at, x.id limit 1;
  if v_before is null or v_before->>'cohort_proven' is null then
    return jsonb_build_object('passed', false, 'measure', jsonb_build_object('after', v_after), 'evidence', 'no baseline: the remedy has not run for this issue');
  end if;
  v_dp := (v_after->>'cohort_proven')::int - (v_before->>'cohort_proven')::int;
  v_df := (v_after->>'cohort_filled')::int - (v_before->>'cohort_filled')::int;
  return jsonb_build_object('passed', v_dp > 0 or v_df > 0,
    'measure', jsonb_build_object('before', v_before, 'after', v_after, 'proven_delta', v_dp, 'filled_delta', v_df),
    'evidence', case when v_dp > 0 or v_df > 0 then format('%s cohort pages proven and %s fields filled since the first run', v_dp, v_df)
                     else 'no cohort page proven and no field filled since the first run' end);
end $$;


ALTER FUNCTION "security"."field_absence_recovery_verify_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."field_absence_unchanged_v1"("p_course" "uuid", "p_field" "text", "p_ev" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select p_ev is not null and exists (
    select 1 from pipeline.course_field_absence a join pipeline.field_absence_classes k on k.code = a.absence_class
     where a.course_id = p_course and a.field = p_field and a.resolved_at is null and k.verified_negative
       and coalesce(a.confidence, 0) >= security.pipeline_num_v1('absence.verified_min_confidence', 0.7)
       and (a.evidence_id = p_ev or (a.content_hash is not null and a.content_hash = (select e.content_hash from pipeline.evidence_artifacts e where e.id = p_ev))))
$$;


ALTER FUNCTION "security"."field_absence_unchanged_v1"("p_course" "uuid", "p_field" "text", "p_ev" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."field_absence_unchanged_v1"("p_course" "uuid", "p_field" "text", "p_ev" "uuid") IS 'CF-247 Release B (D2): the copy about to be read (the same evidence, or one with the same content hash) was read for the field and the field was a verified negative: not read again.';



CREATE OR REPLACE FUNCTION "security"."field_backlog_v1"("p_country" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "statement_timeout" TO '20s'
    AS $$
declare v_c text := nullif(upper(btrim(p_country)), '');
        v_d1 timestamptz := now() - interval '24 hours';  -- fixed: the mandate's 24-hour window
        v_d7 timestamptz := now() - interval '7 days';    -- fixed: the mandate's 7-day window
        v_rh numeric := greatest(1, security.pipeline_num_v1('backlog.rate_window_hours', 168));
        v_ns text[] := coalesce((select array(select jsonb_array_elements_text(s.value)) from pipeline.platform_toolset_settings s
                                  where s.toolset_key = 'pipeline' and s.key = 'backlog.not_stated_reasons' and jsonb_typeof(s.value) = 'array'), '{}'::text[]);
        v_rs timestamptz; v_course jsonb; v_prov jsonb; v_rows jsonb := '[]'::jsonb; v_proof jsonb; r record; v_t0 timestamptz := clock_timestamp();
begin
  v_rs := now() - make_interval(hours => v_rh::int);
  -- course fields: one pass over the missing values in the coverage cache
  with fm(attribute, field, enrich, l4, label, sort) as (values
         ('description', 'course_description', 'description', array['course_description_first_read'], 'Course description', 1),
         ('deadline', 'application_deadline', 'deadline', array[]::text[], 'Application deadline', 2),
         ('intakes', 'intakes', 'intakes', array[]::text[], 'Intake dates', 4),
         ('academic_entry', 'aer_course', 'entry_requirements', array['course_entry_first_read'], 'Academic entry (course level)', 5),
         ('provider_tuition', 'fees', null, array['provider_current_tuition', 'provider_current_tuition_validation'], 'Fees', 7),
         ('english', 'english', 'english', array['course_english'], 'English requirements', 8),
         ('campus', 'campus', 'campus', array[]::text[], 'Campus', 9),
         ('delivery', 'delivery', 'delivery', array[]::text[], 'Delivery mode', 10),
         ('duration', 'duration', 'duration', array[]::text[], 'Duration', 11)),
  pg as materialized (
    select g.course_id,
           (g.status in ('bound', 'ambiguous') and g.read_status = 'read' and g.identity_basis is not null and e.storage_path is not null
            and not exists (select 1 from pipeline.course_page_proofs y where y.course_id = g.course_id and not y.proven)) stored
      from pipeline.coverage_course_pages g left join pipeline.evidence_artifacts e on e.id = g.evidence_id),
  miss as materialized (
    select a.course_id, a.attribute, a.state from pipeline.course_attribute_coverage a
     where a.attribute in (select fm.attribute from fm) and a.state <> 'admitted' and (v_c is null or a.country_code = v_c)
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = a.provider_id)),
  skipped as materialized (
    select distinct on (e.course_id, e.field) e.course_id, e.field, e.state, e.reason from pipeline.field_enrich_items e
     where e.course_id is not null and e.field in (select fm.enrich from fm where fm.enrich is not null)
     order by e.course_id, e.field, e.id desc),
  l4 as materialized (   -- pending Layer 4 items per course and field (a hash join; an exists per row took 14 s on production)
    select distinct i.entity_id course_id, fm.field from pipeline.layer4_review_items i join fm on i.field_code = any (fm.l4) where i.status = 'pending'),
  aer as materialized (select o.course_id, o.outcome from pipeline.aer_course_outcomes o),
  cls as (
    select fm.field, case
             when m.state in ('in_review', 'awaiting_l3') or l4.course_id is not null
                  or (m.attribute = 'academic_entry' and x.outcome = 'awaiting_review') then 'layer4'
             when m.state in ('not_on_page', 'no_website') or (s.state = 'skipped' and s.reason like any (array(select x || '%' from unnest(v_ns) x))) or (m.attribute = 'academic_entry' and x.outcome = 'no_requirement_published') then 'not_supported'
             when coalesce(pg.stored, false) then 'stored'
             else 'acquire' end k
      from miss m join fm on fm.attribute = m.attribute
      left join pg on pg.course_id = m.course_id
      left join skipped s on s.course_id = m.course_id and s.field = fm.enrich
      left join aer x on m.attribute = 'academic_entry' and x.course_id = m.course_id
      left join l4 on l4.course_id = m.course_id and l4.field = fm.field
     where not (m.attribute = 'academic_entry' and coalesce(x.outcome, '') = 'excluded'))   -- out of the AER engine's scope (aer.eligible_countries, provider rules)
  select coalesce(jsonb_object_agg(z.field, z.o), '{}'::jsonb) into v_course from (
    select fm.field, jsonb_build_object('label', fm.label, 'sort', fm.sort, 'level', 'course', 'eligible', count(c.k), 'waiting_layer4', count(*) filter (where c.k = 'layer4'),
                                       'not_supported', count(*) filter (where c.k = 'not_supported'), 'stored_source', count(*) filter (where c.k = 'stored'),
                                       'requires_acquisition', count(*) filter (where c.k = 'acquire')) o
      from fm left join cls c on c.field = fm.field group by fm.field, fm.label, fm.sort) z;

  -- processed and admitted (course fields read by Enrich fields: its items; AER: course entry rows; fees: the fee reader and its rows)
  for r in
    with pc as materialized (select p.id provider_id from catalogue.providers p join ref.countries k on k.id = p.country_id where v_c is null or k.iso_alpha2 = v_c),
    ef as (select case e.field when 'description' then 'course_description' when 'deadline' then 'application_deadline' when 'entry_requirements' then 'aer_course' else e.field end field,
                  count(*) filter (where e.updated_at > v_d1 and e.state in ('filled', 'review', 'skipped', 'failed')) p1, count(*) filter (where e.updated_at > v_d1 and e.state = 'filled') a1,
                  count(*) filter (where e.state in ('filled', 'review', 'skipped', 'failed')) p7, count(*) filter (where e.state = 'filled') a7,
                  0::bigint ar
             from pipeline.field_enrich_items e where e.updated_at > v_d7 and e.course_id is not null and e.provider_id in (select pc.provider_id from pc)
              and e.field in ('description', 'deadline', 'intakes', 'english', 'campus', 'delivery', 'duration', 'entry_requirements') group by 1),
    efr as (select case e.field when 'description' then 'course_description' when 'deadline' then 'application_deadline' when 'entry_requirements' then 'aer_course' else e.field end field, count(*) ar
              from pipeline.field_enrich_items e where e.updated_at > v_rs and e.state = 'filled' and e.course_id is not null and e.provider_id in (select pc.provider_id from pc)
               and e.field in ('description', 'deadline', 'intakes', 'english', 'campus', 'delivery', 'duration', 'entry_requirements') group by 1),
    aer as (select 'aer_course'::text field, count(distinct x.course_id) filter (where x.updated_at > v_d1) p1, count(distinct x.course_id) filter (where x.updated_at > v_d1 and x.status = 'active') a1,
                   count(distinct x.course_id) p7, count(distinct x.course_id) filter (where x.status = 'active') a7,
                   (select count(distinct y.course_id) from catalogue.course_entry_requirements y join catalogue.courses cy on cy.id = y.course_id
                     where y.updated_at > v_rs and y.status = 'active' and cy.provider_id in (select pc.provider_id from pc)) ar
              from catalogue.course_entry_requirements x join catalogue.courses c on c.id = x.course_id
             where x.updated_at > v_d7 and c.provider_id in (select pc.provider_id from pc)),
    fee as (select 'fees'::text field,
                   (select count(*) from pipeline.fee_reader_queue q where q.finished_at > v_d1 and q.provider_id in (select pc.provider_id from pc)) p1,
                   count(distinct f.course_id) filter (where f.created_at > v_d1) a1,
                   (select count(*) from pipeline.fee_reader_queue q where q.finished_at > v_d7 and q.provider_id in (select pc.provider_id from pc)) p7,
                   count(distinct f.course_id) a7,
                   (select count(distinct f2.course_id) from catalogue.course_fees f2 join catalogue.courses c2 on c2.id = f2.course_id
                     where f2.created_at > v_rs and coalesce(f2.status, 'active') = 'active' and f2.basis is distinct from 'registered_total_course'
                       and c2.provider_id in (select pc.provider_id from pc)) ar
              from catalogue.course_fees f join catalogue.courses c on c.id = f.course_id
             where f.created_at > v_d7 and coalesce(f.status, 'active') = 'active' and f.basis is distinct from 'registered_total_course' and c.provider_id in (select pc.provider_id from pc))
    select ef.field, ef.p1, ef.a1, ef.p7, ef.a7, coalesce(efr.ar, 0) ar from ef left join efr on efr.field = ef.field where ef.field <> 'aer_course'
    union all select * from aer union all select * from fee
  loop
    v_course := jsonb_set(v_course, array[r.field], coalesce(v_course->r.field, '{}'::jsonb)
                 || jsonb_build_object('processed_24h', r.p1, 'admitted_24h', r.a1, 'processed_7d', r.p7, 'admitted_7d', r.a7, 'admitted_in_rate_window', r.ar), true);
  end loop;

  -- provider fields: provider description, scholarships, rankings (active, published providers with active courses)
  with pv as materialized (
    select p.id, nullif(btrim(p.description), '') is null no_desc, t.code ptype
      from catalogue.providers p join ref.countries k on k.id = p.country_id left join ref.provider_types t on t.id = p.provider_type_id
     where (v_c is null or k.iso_alpha2 = v_c)
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id)
       and exists (select 1 from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active')),
  d as (select pv.id, case
             when exists (select 1 from pipeline.provider_description_reads dr where dr.provider_id = pv.id and dr.state in ('proposed', 'held'))
                  or exists (select 1 from pipeline.layer4_review_items i where i.entity_id = pv.id and i.field_code = 'provider_description' and i.status = 'pending') then 'layer4'
             when nullif(btrim((select p.website from catalogue.providers p where p.id = pv.id)), '') is null then 'not_supported'
             when exists (select 1 from pipeline.provider_description_reads dr where dr.provider_id = pv.id and dr.evidence_id is not null) then 'stored'
             else 'acquire' end k
          from pv where pv.no_desc),
  s as (select pv.id, case
             when exists (select 1 from pipeline.scholarship_page_candidates c where c.provider_id = pv.id and c.admit_status = 'matched_held') then 'layer4'
             when exists (select 1 from pipeline.scholarship_discovery_providers x where x.provider_id = pv.id and x.status in ('empty', 'directory_site')) then 'not_supported'
             when exists (select 1 from pipeline.scholarship_page_candidates c where c.provider_id = pv.id and c.storage_path is not null and c.admit_status is null) then 'stored'
             else 'acquire' end k
          from pv where not exists (select 1 from scholarship.scholarships x where x.provider_id = pv.id and x.lifecycle_status = 'active')),
  -- rankings live in schema ranking (read by public.website_v2_provider_rankings): the latest accepted edition of each active system
  le as materialized (select distinct on (e.system_id) e.id, e.system_id, sy.code, e.edition_year from ranking.editions e join ranking.systems sy on sy.id = e.system_id
                       where sy.active and e.status = 'accepted' order by e.system_id, e.edition_year desc),
  uni as materialized (   -- published universities (the API's provider scope), whether or not they have active courses
    select p.id from catalogue.providers p join ref.countries k on k.id = p.country_id join ref.provider_types t on t.id = p.provider_type_id
     where t.code = 'university' and (v_c is null or k.iso_alpha2 = v_c) and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id)),
  held as materialized (select distinct l.provider_id, le.code from ranking.observation_provider_links l join ranking.observations o on o.id = l.observation_id
                          join le on le.id = o.edition_id where l.provider_id in (select uni.id from uni)),
  rk as (select u.id, case
             when exists (select 1 from held h where h.provider_id = u.id) then 'held'
             when exists (select 1 from ranking.provider_mappings m where m.provider_id = u.id and m.status = 'candidate') then 'layer4'
             when exists (select 1 from ranking.provider_mappings m where m.provider_id = u.id and m.status = 'accepted')
                  or exists (select 1 from ranking.observation_provider_links l where l.provider_id = u.id) then 'stored'
             else 'acquire' end k
           from uni u)
  select jsonb_build_object(
    'provider_description', jsonb_build_object('label', 'Provider description', 'sort', 3, 'level', 'provider',
        'eligible', (select count(*) from d), 'waiting_layer4', (select count(*) from d where k = 'layer4'), 'not_supported', (select count(*) from d where k = 'not_supported'),
        'stored_source', (select count(*) from d where k = 'stored'), 'requires_acquisition', (select count(*) from d where k = 'acquire'),
        'processed_24h', (select count(*) from pipeline.provider_description_reads dr where dr.updated_at > v_d1 and dr.provider_id in (select pv.id from pv)),
        'admitted_24h', (select count(*) from pipeline.provider_description_reads dr where dr.published_at > v_d1 and dr.provider_id in (select pv.id from pv)),
        'processed_7d', (select count(*) from pipeline.provider_description_reads dr where dr.updated_at > v_d7 and dr.provider_id in (select pv.id from pv)),
        'admitted_7d', (select count(*) from pipeline.provider_description_reads dr where dr.published_at > v_d7 and dr.provider_id in (select pv.id from pv)),
        'admitted_in_rate_window', (select count(*) from pipeline.provider_description_reads dr where dr.published_at > v_rs and dr.provider_id in (select pv.id from pv))),
    'scholarships', jsonb_build_object('label', 'Scholarships (providers with none)', 'sort', 6, 'level', 'provider',
        'eligible', (select count(*) from s), 'waiting_layer4', (select count(*) from s where k = 'layer4'), 'not_supported', (select count(*) from s where k = 'not_supported'),
        'stored_source', (select count(*) from s where k = 'stored'), 'requires_acquisition', (select count(*) from s where k = 'acquire'),
        'processed_24h', (select count(*) from pipeline.scholarship_page_candidates c where c.read_at > v_d1 and c.provider_id in (select pv.id from pv)),
        'admitted_24h', (select count(*) from pipeline.scholarship_page_candidates c where c.admitted_at > v_d1 and c.admit_status = 'admitted' and c.provider_id in (select pv.id from pv)),
        'processed_7d', (select count(*) from pipeline.scholarship_page_candidates c where c.read_at > v_d7 and c.provider_id in (select pv.id from pv)),
        'admitted_7d', (select count(*) from pipeline.scholarship_page_candidates c where c.admitted_at > v_d7 and c.admit_status = 'admitted' and c.provider_id in (select pv.id from pv)),
        'admitted_in_rate_window', (select count(*) from pipeline.scholarship_page_candidates c where c.admitted_at > v_rs and c.admit_status = 'admitted' and c.provider_id in (select pv.id from pv))),
    'rankings', jsonb_build_object('label', 'Rankings (published universities not in the latest edition)', 'sort', 12, 'level', 'provider',
        'universities', (select count(*) from rk), 'held', (select count(*) from rk where k = 'held'),
        'held_by_system', coalesce((select jsonb_object_agg(z.code, z.n) from (select h.code, count(*) n from held h group by 1) z), '{}'::jsonb),
        'latest_editions', coalesce((select jsonb_object_agg(le.code, le.edition_year) from le), '{}'::jsonb),
        'eligible', (select count(*) from rk where k <> 'held'), 'waiting_layer4', (select count(*) from rk where k = 'layer4'), 'not_supported', 0,
        'stored_source', (select count(*) from rk where k = 'stored'), 'requires_acquisition', (select count(*) from rk where k = 'acquire'),
        'processed_24h', (select count(*) from ranking.manual_imports i where i.uploaded_at > v_d1),
        'admitted_24h', (select count(distinct l.provider_id) from ranking.observation_provider_links l where l.created_at > v_d1 and l.provider_id in (select uni.id from uni)),
        'processed_7d', (select count(*) from ranking.manual_imports i where i.uploaded_at > v_d7),
        'admitted_7d', (select count(distinct l.provider_id) from ranking.observation_provider_links l where l.created_at > v_d7 and l.provider_id in (select uni.id from uni)),
        'admitted_in_rate_window', (select count(distinct l.provider_id) from ranking.observation_provider_links l where l.created_at > v_rs and l.provider_id in (select uni.id from uni)),
        'note', nullif(concat_ws('; ', 'processed = ranking files imported; admitted = universities newly linked to an observation',
                  (select 'active systems with no accepted edition: ' || string_agg(sy.code, ', ') from ranking.systems sy where sy.active and not exists (select 1 from le where le.system_id = sy.id))), '')))
    into v_prov;

  -- rows with the measured rate and forecast (no rate, no forecast)
  for r in select e.key, e.value v from jsonb_each(v_course || v_prov) e loop
    v_rows := v_rows || (r.v || jsonb_build_object('field', r.key,
      'processed_24h', coalesce((r.v->>'processed_24h')::bigint, 0), 'admitted_24h', coalesce((r.v->>'admitted_24h')::bigint, 0),
      'processed_7d', coalesce((r.v->>'processed_7d')::bigint, 0), 'admitted_7d', coalesce((r.v->>'admitted_7d')::bigint, 0),
      'accepted_per_hour', round(coalesce((r.v->>'admitted_in_rate_window')::numeric, 0) / v_rh, 3),
      'forecast_hours', case when coalesce((r.v->>'admitted_in_rate_window')::numeric, 0) > 0
                             then round(greatest(0, (r.v->>'eligible')::numeric - (r.v->>'not_supported')::numeric) / ((r.v->>'admitted_in_rate_window')::numeric / v_rh)) end,
      'forecast_at', case when coalesce((r.v->>'admitted_in_rate_window')::numeric, 0) > 0
                          then now() + make_interval(secs => (greatest(0, (r.v->>'eligible')::numeric - (r.v->>'not_supported')::numeric) / ((r.v->>'admitted_in_rate_window')::numeric / v_rh) * 3600)::double precision) end));
  end loop;
  select coalesce(jsonb_agg(x order by (x->>'sort')::int), '[]'::jsonb) into v_rows from jsonb_array_elements(v_rows) x;

  -- the source-proof lane
  v_proof := jsonb_build_object(
    'waiting_for_page_proof', (select count(*) from pipeline.course_page_proofs y where not y.proven),
    'requests', coalesce((select jsonb_object_agg(z.k, z.n) from (select q.route || ':' || q.state k, count(*) n from pipeline.source_proof_requests q group by 1) z), '{}'::jsonb),
    'settled_24h', (select count(*) from pipeline.source_proof_requests q where q.settled_at > v_d1),
    'outcomes_24h', coalesce((select jsonb_object_agg(z.o, z.n) from (select q.outcome o, count(*) n from pipeline.source_proof_requests q where q.settled_at > v_d1 group by 1) z), '{}'::jsonb),
    'free_per_run', security.pipeline_num_v1('proof.feed_per_run', 50), 'paid_search_per_run', security.pipeline_num_v1('proof.search_per_run', 0));
  return jsonb_build_object('at', now(), 'country', v_c, 'rate_window_hours', v_rh, 'fields', v_rows, 'source_proof', v_proof,
                            'coverage_cache_at', (select max(a.computed_at) from pipeline.course_attribute_coverage a where a.attribute = 'intakes'),
                            'ms', (extract(epoch from clock_timestamp() - v_t0) * 1000)::int);  -- fixed: milliseconds
end $$;


ALTER FUNCTION "security"."field_backlog_v1"("p_country" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."field_coverage_record_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v int;
begin
  insert into pipeline.field_coverage_daily(snapshot_date, country_code, field, total, filled)
  select (now() at time zone 'Australia/Melbourne')::date, a.country_code, a.attribute, count(*), count(*) filter (where a.state = 'admitted')  -- fixed: the day is Melbourne's
    from pipeline.course_attribute_coverage a group by 2, 3
  union all
  select (now() at time zone 'Australia/Melbourne')::date, x.country_code, x.field, x.total, x.filled from security.provider_field_coverage_v1() x
  union all  -- 16 Nov 2026: API v3 and request-register fields (security.api_v3_field_coverage_v1)
  select (now() at time zone 'Australia/Melbourne')::date, v.country_code, v.field, v.total, v.filled from security.api_v3_field_coverage_v1() v
  on conflict (snapshot_date, country_code, field) do update set total = excluded.total, filled = excluded.filled, computed_at = now();
  get diagnostics v = row_count;
  delete from pipeline.field_coverage_daily where snapshot_date < current_date - 120;  -- fixed: history kept 120 days (derived figures, rebuilt hourly)
  return v;
end $$;


ALTER FUNCTION "security"."field_coverage_record_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."field_crosscheck_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_new int; v_closed int; v_tol numeric := security.pipeline_num_v1('crosscheck.duration_tolerance_pct', 10);
begin
  -- the latest adapter reading of each course page (the same reading Enrich fields uses), compared with the held value
  drop table if exists _cc;
  create temp table _cc on commit drop as
  select y.id, y.provider_id, y.field, y.held_value, y.page_value, 'adapter'::text source, left(y.txt, 300) quote, y.ev
    from (
      select x.id, x.provider_id, f.field, f.held_value, f.page_value, f.txt, x.ev, f.differs
        from (select c.id, c.provider_id, c.duration_value, c.duration_unit, c.study_level_id, c.delivery_mode,
                     (select g.evidence_id from pipeline.coverage_course_pages g where g.course_id = c.id) ev,
                     coalesce((select r.fields->'extra' from pipeline.uni_adapter_results r where r.course_id = c.id order by r.at desc limit 1), '{}'::jsonb)
                     || coalesce((select g.candidates->'adapter_extra' from pipeline.coverage_course_pages g
                                   where g.course_id = c.id and g.read_status = 'read' and g.identity_basis is not null), '{}'::jsonb) ex
                from catalogue.courses c where c.lifecycle_status = 'active' offset 0) x  -- 3 Nov 2026: each course's readings once (inlined, they ran again for every use: 60 s)
        cross join lateral (
          select 'duration' field, jsonb_build_object('value', x.duration_value, 'unit', x.duration_unit) held_value, d page_value, x.ex->>'duration' txt,
                 abs(w1 - w2) * 100 > v_tol * greatest(w1, w2) differs
            from (select security.enrich_parse_duration_v1(nullif(btrim(x.ex->>'duration'), '')) d offset 0) p,
                 lateral (select case x.duration_unit when 'years' then x.duration_value * 52 when 'months' then x.duration_value * 52 / 12 when 'weeks' then x.duration_value end w1,
                                 case p.d->>'unit' when 'years' then (p.d->>'value')::numeric * 52 when 'months' then (p.d->>'value')::numeric * 52 / 12 when 'weeks' then (p.d->>'value')::numeric end w2) w
           where p.d is not null and x.duration_value is not null and w.w1 > 0 and w.w2 > 0
             and coalesce(x.ex->>'duration', '') !~* '\d\s*(-|–|to|or)\s*\d'
          union all
          select 'level', jsonb_build_object('level_id', x.study_level_id, 'name', (select l.name from ref.study_levels l where l.id = x.study_level_id)),
                 jsonb_build_object('level_id', p.l, 'name', (select l.name from ref.study_levels l where l.id = p.l)), x.ex->>'study_level', p.l <> x.study_level_id
            from (select security.enrich_parse_level_v1(nullif(btrim(x.ex->>'study_level'), '')) l offset 0) p
           where p.l is not null and x.study_level_id is not null
          union all
          select 'delivery', jsonb_build_object('mode', x.delivery_mode), jsonb_build_object('mode', p.m), x.ex->>'mode', p.m <> x.delivery_mode
            from (select security.delivery_mode_read_v1(left(nullif(btrim(x.ex->>'mode'), ''), 300), x.provider_id) m offset 0) p
           where p.m is not null and nullif(btrim(x.delivery_mode), '') is not null) f
       where x.ex <> '{}'::jsonb) y
   where y.differs
     and not exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = y.id and l.field in (y.field, 'all'))
  ;
  insert into pipeline.field_crosscheck_findings(course_id, provider_id, field, held_value, page_value, source, quote, evidence_id)
  select c.id, c.provider_id, c.field, c.held_value, c.page_value, c.source, c.quote, c.ev from _cc c
  on conflict (course_id, field, page_value) do nothing;
  get diagnostics v_new = row_count;
  -- CF-247 21 Oct 2026 (delivery reader): an open finding that no longer differs (the held value or the page reading changed) closes itself
  update pipeline.field_crosscheck_findings f set state = 'resolved', decided_at = now(), note = 'no longer differs: the held value or the page reading changed'
   where f.state = 'open' and not exists (select 1 from _cc c where c.id = f.course_id and c.field = f.field and c.page_value = f.page_value);
  get diagnostics v_closed = row_count;
  return jsonb_build_object('new', v_new, 'resolved', v_closed, 'open', (select count(*) from pipeline.field_crosscheck_findings where state = 'open'));
end $$;


ALTER FUNCTION "security"."field_crosscheck_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."field_enrich_items_absence_trg_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.course_id is null or new.state is not distinct from old.state then return null; end if;
  if new.state in ('filled', 'review', 'skipped', 'failed') then perform security.field_absence_classify_v1(new.id); end if;
  return null;
end $$;


ALTER FUNCTION "security"."field_enrich_items_absence_trg_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."field_enrich_items_absence_trg_v1"() IS 'CF-247 Release B (D2, D3): trigger field_enrich_items_absence: classifies each settled course item (security.field_absence_classify_v1).';



CREATE OR REPLACE FUNCTION "security"."field_enrich_items_flag_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare f record;
begin
  if new.course_id is null or new.state is not distinct from old.state then return null; end if;
  if new.state = 'skipped' and coalesce(new.reason, '') ~* '(does not state|names no campus|quote is not on the page|site-wide line|not classified)' then
    perform security.flag_raise_v1('course', new.course_id::text, new.provider_id, new.field, 'enrich_no_value', 'Enrich fields: ' || new.reason, 'soft', 'enrich-fields', 'auto',
      jsonb_build_object('job_id', new.job_id, 'item_id', new.id, 'source', new.source, 'tried', new.tried, 'cost_usd', new.cost_usd, 'evidence_id', new.evidence_id),
      coalesce(new.evidence_id::text, new.storage_path), null);
  elsif new.state = 'filled' then
    for f in select id from pipeline.enrichment_flags where entity = 'course' and entity_key = new.course_id::text and field = new.field and reason_code = 'enrich_no_value' and state <> 'released' loop
      perform security.flag_release_v1(f.id, 'enrich-fields', 'auto', 'Value found by Enrich fields', jsonb_build_object('job_id', new.job_id, 'item_id', new.id), false);
    end loop;
  end if;
  return null;
end $$;


ALTER FUNCTION "security"."field_enrich_items_flag_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."field_enrich_items_gate_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.course_id is null then return new; end if;
  -- held, or tried on the same input less than gaps.recheck_days ago: not queued (CF-247 21 Oct 2026: the hold is security.enrich_item_held_v1)
  if security.enrich_item_held_v1(new.course_id, new.field) then return null; end if;
  return new;
end $$;


ALTER FUNCTION "security"."field_enrich_items_gate_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."field_gap_queue_due_v1"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with l as (select r.run_at, r.outcome, r.items from pipeline.field_gap_queue_runs r order by r.id desc limit 1),
  k as (select c.cursor_course_id from pipeline.field_gap_queue_checkpoint c where c.id = 1)
  select not exists (select 1 from pipeline.admin_jobs j where j.kind = 'enrich_fields' and coalesce((j.args->>'standing')::boolean, false) and j.state in ('queued', 'running', 'paused'))
     and (not exists (select 1 from l)
          or ((select l.run_at from l) <= now() - make_interval(mins => security.pipeline_num_v1('gaps.advance_minutes', 60)::int) + interval '5 minutes'  -- fixed: the hourly job starts a few seconds either side
              and ((select k.cursor_course_id from k) is not null or (select l.outcome from l) in ('done', 'held')
                   or (select l.run_at from l) <= now() - make_interval(mins => security.pipeline_num_v1('gaps.idle_rerun_minutes', 360)::int) + interval '5 minutes'))) -- fixed: as above
$$;


ALTER FUNCTION "security"."field_gap_queue_due_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."field_gap_queue_due_v1"() IS 'CF-247 Release B (mandate 3 Nov 2026 13:09 §6 priority 5): whether job field-gap-queue (checked hourly) starts its next batch: no standing task open, gaps.advance_minutes since the last run, and the pass unfinished or the last run found work, or gaps.idle_rerun_minutes since a run that found nothing.';



CREATE OR REPLACE FUNCTION "security"."field_gap_queue_run_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb; v_t0 timestamptz := clock_timestamp(); v_scan jsonb; v_out text; v_hold text; v_q text;
begin
  v := security.field_gap_queue_tick_v1();
  v_scan := v->'scan'; v_q := v->>'queue';
  v_out := case when v_q = 'started' then 'done' when v_q = 'off' then 'switched_off' when v_q = 'previous run still open' then 'held'
                when v_scan is not null and not coalesce((v_scan->>'cycle_complete')::boolean, true) then 'held'
                when v_scan->'waiting_for_page_proof' <> '{}'::jsonb then 'held'
                else 'idle' end;
  v_hold := case when v_q = 'previous run still open' then 'previous_run_open' when v_q = 'off' then 'queue_off'
                 when v_out = 'held' and not coalesce((v_scan->>'cycle_complete')::boolean, true) then 'scan_continues'
                 when v_out = 'held' then 'waiting_for_page_proof' when v_out = 'idle' then 'nothing_due' end;
  insert into pipeline.field_gap_queue_runs(outcome, hold_reason, items, scanned, cycle, cursor_from, cursor_to, cycle_complete, job_id, ms, detail)
  values (v_out, v_hold, coalesce((v->>'items')::int, 0), coalesce((v_scan->>'scanned')::int, 0), (v_scan->>'cycle')::int,
          (v_scan->>'cursor_from')::uuid, (v_scan->>'cursor_to')::uuid, (v_scan->>'cycle_complete')::boolean, (v->>'job_id')::uuid,
          (extract(epoch from clock_timestamp() - v_t0) * 1000)::int, v - 'crosscheck');  -- fixed: milliseconds
  return v || jsonb_build_object('outcome', v_out, 'hold_reason', v_hold);
end $$;


ALTER FUNCTION "security"."field_gap_queue_run_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."field_gap_queue_tick_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c pipeline.field_gap_queue_control%rowtype; v_job uuid; v_n int; v_x jsonb; v_fields text[];
        v_days int := security.pipeline_num_v1('gaps.recheck_days', 60)::int; v_cap int := security.pipeline_num_v1('gaps.items_per_run', 30000)::int;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' and coalesce(security.current_role_rank(), 0) < 4 then
    raise exception 'Pipeline Operator role or above required' using errcode = '42501';
  end if;
  v_x := jsonb_build_object('crosscheck', security.field_crosscheck_v1());
  select * into c from pipeline.field_gap_queue_control where id = 1;
  if not coalesce(c.enabled, false) then return v_x || jsonb_build_object('queue', 'off'); end if;
  if exists (select 1 from pipeline.admin_jobs j where j.kind = 'enrich_fields' and coalesce((j.args->>'standing')::boolean, false) and j.state in ('queued', 'running', 'paused')) then
    return v_x || jsonb_build_object('queue', 'previous run still open');
  end if;
  v_fields := array(select f.field from security.enrich_fields_v1() f);
  perform security.campus_regions_apply_v1();  -- 23 Oct 2026: a city whose region is known needs no AI
  drop table if exists _gap;
  create temp table _gap(provider_id uuid, course_id uuid, field text, pri int) on commit drop;
  -- CF-247 P0 mandate 3 Nov 2026 §3 Agent C: the same selection in bounded slices from a durable checkpoint (security.field_gap_scan_v1); the
  -- single statement over every course timed out in 2 of 4 runs and kept nothing
  v_x := v_x || jsonb_build_object('scan', security.field_gap_scan_v1(v_fields, v_days, v_cap));
  -- CF-247 Workstream C (3 Nov 2026): course description and application deadline, at most enrich.course_text_items_per_day a day each
  insert into _gap select t.provider_id, t.course_id, t.field, t.pri from security.enrich_course_text_gaps_v1(v_fields) t;
  delete from _gap g where g.course_id is not null and security.enrich_item_held_v1(g.course_id, g.field);  -- the item gate would not queue it
  delete from _gap g where exists (select 1 from security.provider_hidden_v1 h where h.provider_id = g.provider_id);  -- 22 Oct 2026 (Platform Admin 11:42): unpublished providers wait; publishing them again brings them back
  select count(*) into v_n from _gap;
  if v_n = 0 then return v_x || jsonb_build_object('queue', 'nothing due'); end if;
  insert into pipeline.admin_jobs(kind, lane, state, title, args, progress, requested_by, reason, scope)
  values ('enrich_fields', 'enrich-standing', 'queued', 'Fill the gaps · all countries (standing)',
          jsonb_build_object('countries', to_jsonb(security.catalogue_country_codes_v1()), 'provider_ids', '[]'::jsonb, 'fields', to_jsonb(v_fields),
                             'ai', true, 'scraper', true, 'standing', true),
          jsonb_build_object('done', 0, 'total', 0), c.owner, 'Standing gap queue (job field-gap-queue): ' || c.reason, 'All countries')
  returning id into v_job;
  insert into pipeline.field_enrich_items(job_id, provider_id, course_id, field) select v_job, g.provider_id, g.course_id, g.field from _gap g on conflict do nothing;
  insert into pipeline.field_enrich_items(job_id, provider_id, course_id, field, state)
  select distinct v_job, e.provider_id, null::uuid, 'campus_list', 'waiting' from pipeline.field_enrich_items e where e.job_id = v_job and e.field = 'campus'
  on conflict do nothing;
  select count(*) into v_n from pipeline.field_enrich_items where job_id = v_job;
  update pipeline.admin_jobs set progress = jsonb_build_object('done', 0, 'total', v_n) where id = v_job;
  insert into pipeline.admin_job_events(job_id, note, detail) values (v_job, v_n || ' item(s) to settle (standing gap queue)',
    (select jsonb_object_agg(field, n) from (select field, count(*) n from pipeline.field_enrich_items where job_id = v_job group by 1) z));
  return v_x || jsonb_build_object('queue', 'started', 'job_id', v_job, 'items', v_n);
end $$;


ALTER FUNCTION "security"."field_gap_queue_tick_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."field_gap_scan_v1"("p_fields" "text"[], "p_days" integer, "p_cap" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare k pipeline.field_gap_queue_checkpoint%rowtype; v_t0 timestamptz := clock_timestamp();
        v_slice int := greatest(1, security.pipeline_num_v1('gaps.scan_courses_per_slice', 500)::int);
        v_secs numeric := security.pipeline_num_v1('gaps.scan_seconds', 45);
        v_cf text[] := array(select x from unnest(p_fields) x where x not in ('provider_address', 'campus_list', 'campus_region'));
        v_from uuid; v_last uuid; v_ids uuid[]; v_have int := 0; v_n int; v_scanned int := 0; v_slices int := 0; v_stop text; v_wrapped boolean := false;
        v_start_cycle boolean; v_wait jsonb := '{}'::jsonb; v_cut uuid;
        v_free text[] := coalesce((select array(select jsonb_array_elements_text(s.value)) from pipeline.platform_toolset_settings s
                                    where s.toolset_key = 'pipeline' and s.key = 'gaps.page_free_sources' and jsonb_typeof(s.value) = 'array'), array['ai_title', 'ai_city', 'institution_rule']);
        v_pf text[];
begin
  -- the fields read only from the course's own page (none of their sources works without it)
  v_pf := case when security.pipeline_num_v1('gaps.page_proof_on', 1) >= 1
               then array(select f.field from security.enrich_fields_v1() f where f.field = any (v_cf) and not (f.sources && v_free)) else '{}'::text[] end;
  create temp table if not exists _gap_cand(provider_id uuid, course_id uuid, field text, pri int, waiting boolean not null default false) on commit drop;
  insert into pipeline.field_gap_queue_checkpoint(id) values (1) on conflict (id) do nothing;
  select * into k from pipeline.field_gap_queue_checkpoint where id = 1 for update;
  v_from := k.cursor_course_id; v_last := k.cursor_course_id; v_start_cycle := k.cursor_course_id is null;
  loop
    if v_last is null and (v_start_cycle or v_wrapped) then
      -- a new pass: provider-level fields once, at its start (the tick's own rules)
      k.cycle := k.cycle + 1; k.cycle_started_at := now(); k.cycle_scanned := 0; k.cycle_found := 0; k.cycle_waiting_proof := '{}'::jsonb; v_start_cycle := false;
      insert into _gap
      select m.provider_id, null::uuid, m.field, case when l.state is null then 1 else 2 end
        from (select p.id provider_id, 'provider_address'::text field from catalogue.providers p
               where 'provider_address' = any (p_fields) and nullif(btrim(p.address_line1), '') is null and coalesce(p.lifecycle_status, 'active') = 'active'
                 and exists (select 1 from catalogue.courses c3 where c3.provider_id = p.id and c3.lifecycle_status = 'active')
              union all
              select p.id, 'campus_region' from catalogue.providers p
               where 'campus_region' = any (p_fields) and coalesce(p.lifecycle_status, 'active') = 'active'
                 and exists (select 1 from catalogue.campuses c4 where c4.provider_id = p.id and c4.status = 'active' and c4.subdivision_id is null and nullif(btrim(c4.city), '') is not null)) m
        left join lateral (select e.state, e.updated_at, e.reason from pipeline.field_enrich_items e
                            where e.course_id is null and e.field = m.field and e.provider_id = m.provider_id order by e.id desc limit 1) l on true
       where not exists (select 1 from pipeline.manual_locks lk where lk.entity = 'provider' and lk.entity_id = m.provider_id and lk.field in (m.field, 'all'))
         and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = m.provider_id)
         and coalesce(l.state, '') not in ('queued', 'waiting', 'ai', 'leased', 'review')
         and (l.state is null or l.state = 'filled' or l.reason = 'provider unpublished' or l.updated_at < now() - make_interval(days => p_days))
       limit greatest(p_cap - v_have, 0);
      get diagnostics v_n = row_count;
      v_have := v_have + v_n; k.cycle_found := k.cycle_found + v_n;
    end if;
    if v_have >= p_cap then v_stop := 'cap'; exit; end if;
    if clock_timestamp() - v_t0 > make_interval(secs => v_secs) then v_stop := 'time'; exit; end if;
    v_ids := array(select c.id from catalogue.courses c where c.lifecycle_status = 'active' and (v_last is null or c.id > v_last) order by c.id limit v_slice);
    if cardinality(v_ids) = 0 then
      v_last := null;
      -- the pass ended; with nothing found in this run, one more pass from the start (once), so nothing found means a whole pass
      if v_have = 0 and not v_wrapped and v_from is not null then v_wrapped := true; continue; end if;
      v_stop := 'end'; exit;
    end if;
    truncate _gap_cand;
    insert into _gap_cand(provider_id, course_id, field, pri)
    select m.provider_id, m.course_id, m.field,
           case when l.state is null then 1
                when exists (select 1 from pipeline.coverage_course_pages g where g.course_id = m.course_id and g.read_at > l.updated_at) then 0
                else 2 end
      from (select c2.id course_id, c2.provider_id, f.x field
              from catalogue.courses c2 cross join unnest(v_cf) f(x)
             where c2.id = any (v_ids)
               and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = c2.provider_id)  -- unpublished providers wait (the tick's own rule, applied before the cap)
               and case f.x when 'campus' then not exists (select 1 from catalogue.course_campuses x where x.course_id = c2.id)
                            when 'duration' then c2.duration_value is null when 'level' then c2.study_level_id is null
                            when 'delivery' then nullif(btrim(c2.delivery_mode), '') is null when 'field_of_study' then c2.primary_field_id is null
                            when 'international' then c2.open_to_international is null
                            when 'english' then not exists (select 1 from catalogue.course_english_requirements x where x.course_id = c2.id and coalesce(x.status, 'active') = 'active')
                            when 'intakes' then not exists (select 1 from catalogue.course_intakes x where x.course_id = c2.id and x.status = 'active') else false end) m
      left join lateral (select e.state, e.updated_at, e.reason from pipeline.field_enrich_items e
                          where e.course_id = m.course_id and e.field = m.field and e.provider_id = m.provider_id order by e.id desc limit 1) l on true
     where not exists (select 1 from pipeline.manual_locks lk where lk.entity = 'course' and lk.entity_id = m.course_id and lk.field in (m.field, 'all'))
       and coalesce(l.state, '') not in ('queued', 'waiting', 'ai', 'leased', 'review')   -- being worked on, or waiting for a person
       and (l.state is null or l.state = 'filled'                                          -- never tried, or filled and since emptied
            or l.reason = 'provider unpublished'                                           -- skipped while unpublished, published again
            or l.updated_at < now() - make_interval(days => p_days)                        -- not stated: checked again after the set days
            or exists (select 1 from pipeline.coverage_course_pages g where g.course_id = m.course_id and g.read_at > l.updated_at));  -- or once the page is read again
    -- a page-only field of a course with no proven page waits for page proof (the proof is checked once per course)
    if cardinality(v_pf) > 0 then
      -- the proof is costly (about 14 ms a course on production, 3 Nov 2026): kept per course and page state, checked again only when the
      -- page changes or after gaps.proof_recheck_days
      insert into pipeline.course_page_proofs as x (course_id, page_key, proven, checked_at)
      select d.course_id, security.course_page_key_v1(d.course_id), security.course_page_proven_v1(d.course_id), now()
        from (select distinct c2.course_id from _gap_cand c2 where c2.field = any (v_pf)) d
       where not exists (select 1 from pipeline.course_page_proofs y where y.course_id = d.course_id and y.page_key is not distinct from security.course_page_key_v1(d.course_id)
                           and y.checked_at > now() - make_interval(days => security.pipeline_num_v1('gaps.proof_recheck_days', 7)::int))
      on conflict (course_id) do update set page_key = excluded.page_key, proven = excluded.proven, checked_at = excluded.checked_at;
      update _gap_cand c set waiting = true
       where c.field = any (v_pf) and not coalesce((select y.proven from pipeline.course_page_proofs y where y.course_id = c.course_id), false);
    end if;
    insert into _gap
    select c.provider_id, c.course_id, c.field, c.pri from _gap_cand c where not c.waiting
     order by c.course_id, c.field
     limit greatest(p_cap - v_have, 0);
    get diagnostics v_n = row_count;
    -- counted up to where this run stops in the slice (a course checked again next run is counted then)
    v_cut := case when v_have + v_n >= p_cap then (select g.course_id from _gap g where g.course_id = any (v_ids) order by g.course_id desc limit 1) end;
    select v_wait || coalesce(jsonb_object_agg(z.field, z.n + coalesce((v_wait->>z.field)::int, 0)), '{}'::jsonb) into v_wait
      from (select c.field, count(*) n from _gap_cand c where c.waiting and (v_cut is null or c.course_id < v_cut) group by 1) z;
    v_have := v_have + v_n; k.cycle_found := k.cycle_found + v_n; v_scanned := v_scanned + cardinality(v_ids); v_slices := v_slices + 1;
    if v_have >= p_cap then
      -- the cap was reached inside this slice: resume after the last course taken whole (the boundary course is checked again; what was taken
      -- from it is then in progress and is not taken twice)
      v_last := (select x from unnest(v_ids) x where x < (select g.course_id from _gap g where g.course_id = any (v_ids) order by g.course_id desc limit 1) order by x desc limit 1);
      if v_last is null then v_last := k.cursor_course_id; end if;
      k.cycle_scanned := k.cycle_scanned + cardinality(v_ids);
      v_stop := 'cap'; exit;
    end if;
    v_last := v_ids[cardinality(v_ids)];
    k.cycle_scanned := k.cycle_scanned + cardinality(v_ids);
  end loop;
  k.cycle_waiting_proof := k.cycle_waiting_proof || coalesce((select jsonb_object_agg(e.key, (e.value #>> '{}')::int + coalesce((k.cycle_waiting_proof->>e.key)::int, 0)) from jsonb_each(v_wait) e), '{}'::jsonb);
  update pipeline.field_gap_queue_checkpoint set cycle = k.cycle, cycle_started_at = k.cycle_started_at, cursor_course_id = v_last,
         cycle_scanned = k.cycle_scanned, cycle_found = k.cycle_found, cycle_waiting_proof = k.cycle_waiting_proof, last_run_at = now(), updated_at = now()
   where id = 1;
  return jsonb_build_object('cycle', k.cycle, 'cursor_from', v_from, 'cursor_to', v_last, 'scanned', v_scanned, 'slices', v_slices, 'found', v_have,
                            'stopped', v_stop, 'cycle_complete', v_last is null, 'wrapped', v_wrapped, 'waiting_for_page_proof', v_wait,
                            'ms', (extract(epoch from clock_timestamp() - v_t0) * 1000)::int);  -- fixed: milliseconds
end $$;


ALTER FUNCTION "security"."field_gap_scan_v1"("p_fields" "text"[], "p_days" integer, "p_cap" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."field_sources_for_v1"("p_country" "text", "p_field" "text") RETURNS "text"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce((select r.sources from pipeline.field_source_rules r where r.country_code = upper(coalesce(p_country, '')) and r.field = p_field),
                  (select r.sources from pipeline.field_source_rules r where r.country_code = 'ALL' and r.field = p_field), '{}'::text[])
$$;


ALTER FUNCTION "security"."field_sources_for_v1"("p_country" "text", "p_field" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."field_stalled_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with s as (select security.pipeline_num_v1('stall.days', 7)::int d, security.pipeline_num_v1('stall.min_points', 1) mp, security.pipeline_num_v1('stall.country_gap_points', 30) gp),
  today as (select max(snapshot_date) t from pipeline.field_coverage_daily),
  cur as (select x.country_code cc, x.field, x.total, x.filled, round(100.0 * x.filled / nullif(x.total, 0), 1) pct
            from pipeline.field_coverage_daily x, today where x.snapshot_date = today.t and x.total > 0),
  ago as (select distinct on (x.country_code, x.field) x.country_code cc, x.field, x.snapshot_date, round(100.0 * x.filled / nullif(x.total, 0), 1) pct
            from pipeline.field_coverage_daily x, today, s where x.snapshot_date <= today.t - s.d and x.total > 0
           order by x.country_code, x.field, x.snapshot_date desc),
  best as (select field, max(pct) pct, (array_agg(cc order by pct desc))[1] cc from cur group by field),
  cause as (select z.country_code cc, z.attribute field, jsonb_object_agg(z.c, z.n) counts, (array_agg(z.c order by z.n desc))[1] main
              from (select a.country_code, a.attribute,
                           case when a.state = 'not_on_page' then 'not_stated' when a.state = 'in_queue' then 'in_queue'
                                when a.state in ('in_review', 'candidate', 'awaiting_l3') then 'in_review' when a.state in ('page_found', 'blocked') then 'not_read'
                                when a.state in ('site_known', 'no_website') then 'no_page' when a.state = 'missing_l1' then 'register' when a.state = 'no_reader' then 'no_reader' end c,
                           count(*) n
                      from pipeline.course_attribute_coverage a where a.state <> 'admitted' group by 1, 2, 3) z
             group by 1, 2),
  rows as (
    select c.cc, c.field, r.label, r.reader, r.level, c.total, c.filled, c.pct, r.target_pct target, g.pct pct_ago, g.snapshot_date ago_date,
           round(c.pct - g.pct, 1) moved, b.cc best_cc, b.pct best_pct,
           case when r.reader = 'none' then 'no_reader'
                when g.pct is not null and c.pct - g.pct < s.mp then 'flat'
                when b.pct - c.pct >= s.gp then 'behind' end reason,
           case when r.reader = 'none' then 'no_reader' when r.level = 'provider' then 'provider' else coalesce(k.main, 'not_read') end main_cause,
           k.counts
      from cur c join pipeline.field_register r on r.field = c.field and r.active and r.target_pct > 0
      cross join s left join ago g on g.cc = c.cc and g.field = c.field left join best b on b.field = c.field
      left join cause k on k.cc = c.cc and k.field = c.field
     where c.pct < r.target_pct)
  select coalesce(jsonb_agg(jsonb_build_object(
           'country', r.cc, 'field', r.field, 'label', r.label, 'reader', r.reader, 'level', r.level, 'total', r.total, 'filled', r.filled, 'pct', r.pct,
           'target', r.target, 'pct_ago', r.pct_ago, 'ago_date', r.ago_date, 'moved', r.moved, 'days', (select d from s), 'best_country', r.best_cc, 'best_pct', r.best_pct,
           'reason', r.reason, 'cause', r.main_cause, 'causes', r.counts,
           'can_fill', r.field in ('level', 'field_of_study', 'duration', 'delivery', 'campus', 'campus_city', 'international', 'p_address', 'description', 'deadline'),
           'action', case
              when r.reason = 'no_reader' then 'Nothing reads this field yet: a reader is a build task. Set the target to 0 until it exists, so the field is not raised.'
              when r.main_cause = 'in_queue' then 'Being filled now by Fill the gaps or an Enrich fields task: check again after the run.'
              when r.main_cause = 'in_review' then 'Waiting for a person: Layer 4 › Inbox, and For review in the Enrich fields task results.'
              when r.main_cause = 'register' then 'The register does not give it: check the register run on Layer 1 Register.'
              when r.main_cause = 'not_stated' and r.reader = 'enrich' then 'The course pages read do not state it. Add a central page or an adapter rule for the universities below (Layer 2/3 › Universities › Builder), then Release holds and fill; or lower the target if the universities do not publish it.'
              when r.main_cause = 'not_stated' then 'The course pages read do not state it. Add a central page or an adapter rule for the universities below (Layer 2/3 › Universities › Builder); or lower the target if the universities do not publish it.'
              when r.main_cause in ('not_read', 'no_page') and r.reader = 'enrich' then 'Pages not read for this field yet: Fill now starts an Enrich fields task for it in this country (AI on, new page reads within the daily limits).'
              when r.main_cause in ('not_read', 'no_page') then 'Course pages not found or not read: check course-page search for the universities below on Layer 2/3 › Operations and Universities.'
              when r.field = 'p_address' then 'Fill now reads each provider''s contact or home page for its street address.'
              else 'Provider field: open the providers missing it on Providers and add it, or lower the target.' end,
           'top_providers', case when r.level = 'course' then (
              select coalesce(jsonb_agg(jsonb_build_object('id', t.provider_id, 'name', t.name, 'missing', t.n) order by t.n desc), '[]'::jsonb) from (
                select a.provider_id, max(coalesce(p.display_name, p.canonical_name)) name, count(*) n from pipeline.course_attribute_coverage a join catalogue.providers p on p.id = a.provider_id
                 where a.country_code = r.cc and a.attribute = r.field and a.state <> 'admitted' group by 1 order by 3 desc limit 5) t) end)
         order by r.cc, case r.reason when 'flat' then 1 when 'behind' then 2 when 'no_reader' then 3 else 4 end, r.target - r.pct desc), '[]'::jsonb)
    from rows r
$$;


ALTER FUNCTION "security"."field_stalled_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."firecrawl_acceptance_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  p pipeline.layer2_acquisition_providers%rowtype; o pipeline.vendor_credit_observations%rowtype; v_est numeric; v_room numeric; v_floor numeric; v_status jsonb;
  v_win int := security.pipeline_num_v1('lane_funnel.gain_window_hours', 24)::int;
  v_days int := security.pipeline_num_v1('lane_funnel.firecrawl_days', 7)::int;
  v_job jsonb; v_groups jsonb; v_hist jsonb; v_purposes jsonb; v_groupuse jsonb; v_period_start timestamptz;
begin
  select * into p from pipeline.layer2_acquisition_providers x where x.provider_key = 'firecrawl';
  if p.id is not null then
    select * into o from pipeline.vendor_credit_observations x where x.provider_id = p.id order by x.observed_at desc limit 1;
  end if;
  v_est := security.fc_vendor_estimate_v1();
  v_room := security.fc_priority_room_v1();
  v_floor := security.fc_setting_num_v1('priority_floor_course_search', 0);
  v_status := security.fc_budget_status_v1();
  v_period_start := nullif(o.raw->>'billing_period_start', '')::timestamptz;
  select jsonb_build_object('job', 'firecrawl-credit', 'schedule', c.schedule, 'active', c.active,
      'next_run', case when c.active then security.cron_next_run_v1(c.schedule, now()) end,
      'last_start', r.start_time, 'last_status', r.status, 'last_message', left(r.return_message, 240))
    into v_job from cron.job c
    left join lateral (select d.start_time, d.status, d.return_message from cron.job_run_details d where d.jobid = c.jobid order by d.start_time desc limit 1) r on true
   where c.jobname = 'firecrawl-credit';
  -- the daily share left per group is the Controller's own function (security.fc_budget_left_v1), asked with one purpose of each group
  select coalesce(jsonb_agg(g || jsonb_build_object('left', security.fc_budget_left_v1(case g->>'group' when 'course_search' then 'course_link_search' when 'reads' then 'scrape'
                       when 'scholarships' then 'sch_scrape' when 'central' then 'central_map' else 'other_purpose' end)) order by ord), '[]'::jsonb) into v_groups  -- fixed: one purpose of each group, to ask the budget function
    from jsonb_array_elements(v_status->'groups') with ordinality t(g, ord);
  select coalesce(jsonb_agg(jsonb_build_object('day', d.day, 'group', d.grp, 'credits', d.units) order by d.day desc, d.grp), '[]'::jsonb) into v_hist from (
    select (u.at at time zone 'Australia/Melbourne')::date as day, security.fc_purpose_group_v1(u.purpose) as grp, sum(u.units) as units
      from pipeline.coverage_vendor_usage u where u.at >= security.fc_day_start_v1() - make_interval(days => v_days - 1) and u.on_demand_run is null group by 1, 2) d;
  select coalesce(jsonb_agg(jsonb_build_object('group', x.grp, 'credits_window', x.w, 'credits_period', x.pr, 'on_demand_window', x.od) order by x.grp), '[]'::jsonb) into v_groupuse from (
    select security.fc_purpose_group_v1(u.purpose) grp, sum(u.units) filter (where u.at > now() - make_interval(hours => v_win)) w,
           sum(u.units) filter (where v_period_start is not null and u.at >= v_period_start) pr, sum(u.units) filter (where u.at > now() - make_interval(hours => v_win) and u.on_demand_run is not null) od
      from pipeline.coverage_vendor_usage u where u.at > coalesce(v_period_start, now() - make_interval(hours => v_win)) - make_interval(hours => v_win) group by 1) x;
  select coalesce(jsonb_agg(jsonb_build_object('purpose', x.purpose, 'group', x.grp, 'credits_window', x.units, 'calls_window', x.n, 'last_at', x.last_at) order by x.units desc), '[]'::jsonb) into v_purposes from (
    select u.purpose, security.fc_purpose_group_v1(u.purpose) grp, sum(u.units) units, count(*) n, max(u.at) last_at
      from pipeline.coverage_vendor_usage u where u.at > now() - make_interval(hours => v_win) group by 1, 2) x;
  return jsonb_build_object('at', now(), 'unit', 'credits', 'note', 'Credits are counted by the platform; the vendor bill is not shown here and credits are not money.',
    'allowance', jsonb_build_object('plan_credits', o.plan_units, 'monthly_limit_credits', nullif(p.billing_config->>'monthly_vendor_units_limit', '')::numeric,
        'stop_at_remaining_credits', nullif(p.billing_config->>'stop_at_vendor_units_remaining', '')::numeric, 'plan_tier', p.billing_config->>'plan_tier',
        'period_start', v_period_start, 'period_end', o.period_end),
    'vendor', jsonb_build_object('remaining_credits', o.remaining_units, 'read_at', o.observed_at, 'age_minutes', case when o.observed_at is not null then round(extract(epoch from now() - o.observed_at) / 60) end,
        'fresh', v_est is not null, 'estimated_now_credits', v_est, 'used_since_reading_credits', case when v_est is not null then greatest(o.remaining_units - v_est, 0) end,
        'above_plan', case when o.remaining_units is not null and o.plan_units is not null then o.remaining_units > o.plan_units end),
    'sync', coalesce(v_job, jsonb_build_object('job', 'firecrawl-credit', 'scheduled', false)),
    'floor', jsonb_build_object('setting', 'firecrawl / priority_floor_course_search', 'credits', v_floor, 'applies', v_room is not null, 'room_credits', v_room,
        'under_floor', case when v_room is not null then v_room < 0 end, 'switched_off', v_floor <= 0),
    'daily', jsonb_build_object('budget_on', v_status->'on', 'total_credits', v_status->'total', 'billed_today', v_status->'billed_today', 'used_today', v_status->'used_today',
        'day_start', v_status->'day_start', 'groups', v_groups, 'days', v_hist, 'days_shown', v_days),
    'usage', jsonb_build_object('window_hours', v_win, 'by_group', v_groupuse, 'by_purpose', v_purposes));
end $$;


ALTER FUNCTION "security"."firecrawl_acceptance_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."firecrawl_backlog_v1"("p_use_case" "text") RETURNS TABLE("course_id" "uuid", "provider_id" "uuid", "country" "text", "url" "text", "input" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_statuses text[]; v_retry boolean; v_like text; v_skip text;
begin
  select coalesce(array_agg(e), '{}') into v_statuses from jsonb_array_elements_text(coalesce(security.firecrawl_setting('read_statuses'), '[]'::jsonb)) e;
  v_retry := coalesce((security.firecrawl_setting('find_retry_refused') #>> '{}')::boolean, false);
  v_like := coalesce(nullif(btrim(security.firecrawl_setting('read_url_pattern') #>> '{}'), ''), '.');
  v_skip := nullif(btrim(coalesce(security.firecrawl_setting('read_skip_url_pattern') #>> '{}', '')), '');
  if p_use_case = 'read_page' then
    return query
    select pg.course_id, pg.provider_id, t.country, pg.url,
           jsonb_build_object('course', coalesce(c.display_title, c.canonical_title), 'code', c.course_code, 'page_status', pg.status, 'earlier_read', pg.read_status, 'earlier_http', pg.http_status)
    from security.firecrawl_targets_fast() t
    join pipeline.coverage_course_pages pg on pg.provider_id = t.provider_id
    join catalogue.courses c on c.id = pg.course_id
    where t.included and c.lifecycle_status = 'active' and pg.status in ('bound', 'ambiguous') and pg.read_status = any(v_statuses)
      and pg.url is not null and coalesce(pg.http_status, 0) not in (404, 410) and pg.evidence_id is null
      and pg.url ~* v_like and (v_skip is null or pg.url !~* v_skip);
  elsif p_use_case = 'find_page' then
    return query
    select c.id, t.provider_id, t.country, null::text,
           jsonb_build_object('course', coalesce(c.display_title, c.canonical_title), 'code', c.course_code, 'provider', t.name, 'domain', t.domain,
                              'earlier_url', pg.url, 'earlier_status', pg.status,
                              'refind', coalesce(pg.status in ('bound', 'ambiguous'), false))
    from security.firecrawl_targets_fast() t
    join catalogue.courses c on c.provider_id = t.provider_id
    left join pipeline.coverage_course_pages pg on pg.course_id = c.id
    where t.included and t.domain is not null and c.lifecycle_status = 'active'
      and (pg.course_id is null or pg.status not in ('bound', 'ambiguous')
           or (pg.read_status = any(v_statuses) and pg.evidence_id is null and (pg.url !~* v_like or (v_skip is not null and pg.url ~* v_skip))))
      and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = c.id and k.field = 'official_url')
      and (pg.read_status is not distinct from 'refused_host'
           or not exists (select 1 from pipeline.search_pass_links l where l.course_id = c.id and (l.state in ('found', 'verified') or (l.state = 'none' and not v_retry))));
  end if;
end $$;


ALTER FUNCTION "security"."firecrawl_backlog_v1"("p_use_case" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."firecrawl_credit_observe_tick_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare r record; v jsonb; n int := 0; fc jsonb := public.svc_coverage_firecrawl(); v_pid uuid; v_req bigint;
begin
  for r in select q.req_id, q.provider_id, x.status_code, x.content from pipeline.vendor_credit_requests q
             join net._http_response x on x.id = q.req_id where not q.collected loop
    update pipeline.vendor_credit_requests set collected = true where req_id = r.req_id;
    begin v := r.content::jsonb; exception when others then v := null; end;
    if r.status_code = 200 and (v->'data'->>'remaining_credits') ~ '^[0-9]+(\.[0-9]+)?$' then
      insert into pipeline.vendor_credit_observations(provider_id, remaining_units, plan_units, period_end, raw)
      values (r.provider_id, (v->'data'->>'remaining_credits')::numeric, nullif(v->'data'->>'plan_credits', '')::numeric,
              nullif(v->'data'->>'billing_period_end', '')::timestamptz, v->'data');
      n := n + 1;
    end if;
  end loop;
  update pipeline.vendor_credit_requests set collected = true where not collected and sent_at < now() - interval '30 minutes';
  v_pid := nullif(fc->'budget_status'->>'provider_id', '')::uuid;
  if v_pid is not null and fc->>'secret' is not null then
    v_req := net.http_get(url := 'https://api.firecrawl.dev/v1/team/credit-usage',
               headers := jsonb_build_object('Authorization', 'Bearer ' || (fc->>'secret')), timeout_milliseconds := 30000);
    insert into pipeline.vendor_credit_requests(req_id, provider_id) values (v_req, v_pid);
  end if;
  return jsonb_build_object('collected', n, 'sent', v_req);
end $_$;


ALTER FUNCTION "security"."firecrawl_credit_observe_tick_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."firecrawl_credits_report_v1"("p_hours" integer DEFAULT 24) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with since as (select now() - make_interval(hours => greatest(1, least(coalesce(p_hours, 24), 720))) t),
  u as (select x.provider_id, sum(x.units) units,
               sum(x.units) filter (where security.fc_purpose_group_v1(x.purpose) = 'course_search') course_search,
               sum(x.units) filter (where security.fc_purpose_group_v1(x.purpose) = 'reads') reads,
               sum(x.units) filter (where security.fc_purpose_group_v1(x.purpose) = 'scholarships') scholarships,
               sum(x.units) filter (where security.fc_purpose_group_v1(x.purpose) = 'central') central,
               sum(x.units) filter (where security.fc_purpose_group_v1(x.purpose) = 'other') other
          from pipeline.coverage_vendor_usage x, since where x.at > since.t group by 1),
  pg as (select p.provider_id,
                count(*) filter (where p.fetched_via = 'firecrawl' and p.status = 'bound' and p.read_status = 'read') fc_ok,
                count(*) filter (where p.fetched_via = 'firecrawl' and not (p.status = 'bound' and p.read_status = 'read')) fc_wrong,
                count(*) filter (where p.fetched_via is distinct from 'firecrawl' and p.status = 'bound' and p.read_status = 'read') direct_ok
           from pipeline.coverage_course_pages p, since where p.read_at > since.t group by 1),
  st as (select * from security.fc_search_stopped_v1()),
  rows as (select coalesce(u.provider_id, pg.provider_id, st.provider_id) provider_id, coalesce(u.units, 0) units, coalesce(u.course_search, 0) course_search, coalesce(u.reads, 0) reads,
                  coalesce(u.scholarships, 0) scholarships, coalesce(u.central, 0) central, coalesce(u.other, 0) other,
                  coalesce(pg.fc_ok, 0) fc_ok, coalesce(pg.fc_wrong, 0) fc_wrong, coalesce(pg.direct_ok, 0) direct_ok, st.provider_id is not null stopped, st.searches stopped_searches
             from u full join pg on pg.provider_id = u.provider_id full join st on st.provider_id = coalesce(u.provider_id, pg.provider_id)
            where coalesce(u.provider_id, pg.provider_id, st.provider_id) is not null),
  rated as (select r.*, r.fc_ok + r.direct_ok correct,
                   case when r.course_search + r.reads > 0 and r.fc_ok + r.direct_ok > 0 then round((r.course_search + r.reads) / (r.fc_ok + r.direct_ok)::numeric, 1) end per_correct,
                   case when r.stopped then 'search_stopped'
                        when r.course_search + r.reads >= 100 and r.fc_ok + r.direct_ok = 0 then 'no_pages'
                        when r.fc_wrong >= 20 and r.fc_wrong > r.fc_ok then 'mostly_wrong'
                        when r.scholarships >= 300 then 'scholarships_high' end flag
              from rows r)
  select jsonb_build_object('generated_at', now(), 'hours', greatest(1, least(coalesce(p_hours, 24), 720)), 'budget', security.fc_budget_status_v1(),
    'totals', (select jsonb_build_object('units', coalesce(sum(units), 0), 'course_search', coalesce(sum(course_search), 0), 'reads', coalesce(sum(reads), 0),
                       'scholarships', coalesce(sum(scholarships), 0), 'central', coalesce(sum(central), 0), 'other', coalesce(sum(other), 0),
                       'fc_ok', coalesce(sum(fc_ok), 0), 'fc_wrong', coalesce(sum(fc_wrong), 0), 'direct_ok', coalesce(sum(direct_ok), 0),
                       'universities', count(*) filter (where units > 0), 'flagged', count(*) filter (where flag is not null), 'stopped', count(*) filter (where stopped)) from rated),
    'universities', (select coalesce(jsonb_agg(jsonb_build_object('provider_id', z.provider_id, 'name', coalesce(pr.display_name, pr.canonical_name), 'country', security.coverage_country(z.provider_id),
                        'units', z.units, 'course_search', z.course_search, 'reads', z.reads, 'scholarships', z.scholarships, 'central', z.central, 'other', z.other,
                        'fc_ok', z.fc_ok, 'fc_wrong', z.fc_wrong, 'direct_ok', z.direct_ok, 'correct', z.correct, 'per_correct', z.per_correct,
                        'flag', z.flag, 'stopped', z.stopped, 'stopped_searches', z.stopped_searches) order by z.units desc, z.correct desc), '[]'::jsonb)
                       from (select * from rated where units > 0 or stopped order by units desc limit 150) z left join catalogue.providers pr on pr.id = z.provider_id))
$$;


ALTER FUNCTION "security"."firecrawl_credits_report_v1"("p_hours" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."firecrawl_panel_refresh_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int;
begin
  -- CF-247 15 Oct: never at the same time as the target refresh (they deadlocked on the target cache)
  if not pg_try_advisory_xact_lock(hashtext('cf247:firecrawl_targets_refresh')) then return 0; end if;
  with c as (
    select t.provider_id, jsonb_build_object('courses', count(*),
           'confirmed', count(*) filter (where pg.status = 'bound' and pg.read_status = 'read' and pg.identity_basis is not null),
           'unreadable', count(*) filter (where pg.status in ('bound', 'ambiguous') and pg.read_status in ('needs_render', 'blocked', 'fetch_failed', 'too_thin', 'robots_disallowed')),
           'no_page', count(*) filter (where pg.course_id is null or pg.status not in ('bound', 'ambiguous')),
           'adapter_confirmed', count(*) filter (where pg.read_status = 'read' and pg.identity_basis in ('adapter_code', 'adapter_title')),
           'waiting_read', count(*) filter (where pg.status = 'bound' and (pg.read_status is null or pg.read_status = 'needs_render')),
           'intakes', count(*) filter (where exists (select 1 from catalogue.course_intakes i where i.course_id = cc.id and coalesce(i.status, 'active') = 'active')),
           'english', count(*) filter (where exists (select 1 from catalogue.course_english_requirements e where e.course_id = cc.id and coalesce(e.status, 'active') = 'active')),
           'any_fee', count(*) filter (where exists (select 1 from catalogue.course_fees f where f.course_id = cc.id and coalesce(f.audience, '') ~* 'int'))) s
    from pipeline.firecrawl_target_cache t join catalogue.courses cc on cc.provider_id = t.provider_id and cc.lifecycle_status = 'active'
    left join pipeline.coverage_course_pages pg on pg.course_id = cc.id
    where t.name is not null
    group by t.provider_id
  )
  update pipeline.firecrawl_target_cache t set stats = c.s, stats_at = now() from c where c.provider_id = t.provider_id;
  get diagnostics n = row_count;
  insert into pipeline.firecrawl_panel_figures(id, backlog, refreshed_at)
    values (1, jsonb_build_object('read_page', (select count(*) from security.firecrawl_backlog_v1('read_page')), 'find_page', (select count(*) from security.firecrawl_backlog_v1('find_page'))), now())
  on conflict (id) do update set backlog = excluded.backlog, refreshed_at = now() where pipeline.firecrawl_panel_figures.id = 1;
  return n;
end $$;


