CREATE OR REPLACE FUNCTION "security"."firecrawl_upgrade_run_v1"("p_provider_id" "uuid", "p_query" "text", "p_page_pattern" "text", "p_cap" numeric, "p_reason" "text", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_settings jsonb; v_run uuid; v_n int; v_budget jsonb; v_domain text;
begin
  if length(btrim(coalesce(p_reason, ''))) < 4 then raise exception 'give a reason (kept in the log)'; end if;
  if not security.uni_adapter_pattern_ok(p_page_pattern) or coalesce(p_page_pattern, '') = '' then raise exception 'the page pattern cannot be read'; end if;
  if exists (select 1 from pipeline.firecrawl_runs r where r.use_case = 'find_page' and r.status = 'running') then raise exception 'a Find pages run is still open. Let it finish or stop it first'; end if;
  v_budget := security.layer2_provider_budget_status((select p.id from pipeline.layer2_acquisition_providers p where p.provider_key = 'firecrawl'), 1);
  if not coalesce((v_budget->>'allowed')::boolean, false) then raise exception 'Firecrawl is at its reserve'; end if;
  select coalesce(jsonb_object_agg(s.key, s.value), '{}'::jsonb) into v_settings from pipeline.platform_toolset_settings s where s.toolset_key = 'firecrawl';
  v_settings := v_settings || jsonb_build_object('find_query', to_jsonb(p_query));
  v_domain := (select c.domain from pipeline.firecrawl_target_cache c where c.provider_id = p_provider_id);
  insert into pipeline.firecrawl_runs(use_case, settings, reason, requested_by, credits_cap) values ('find_page', v_settings, p_reason, p_actor, p_cap) returning id into v_run;
  insert into pipeline.firecrawl_run_items(run_id, course_id, provider_id, country, url, input)
    select v_run, pg.course_id, pg.provider_id, k.iso_alpha2::text, null,
           jsonb_build_object('course', coalesce(c.display_title, c.canonical_title), 'code', c.course_code, 'provider', coalesce(p.display_name, p.canonical_name), 'domain', v_domain,
                              'upgrade', true, 'upgrade_pattern', p_page_pattern, 'earlier_url', pg.url, 'earlier_status', pg.read_status, 'refind', true)
      from pipeline.coverage_course_pages pg join catalogue.courses c on c.id = pg.course_id and c.lifecycle_status = 'active'
      join catalogue.providers p on p.id = pg.provider_id join ref.countries k on k.id = p.country_id
     where pg.provider_id = p_provider_id and pg.url !~* p_page_pattern
       and not exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = pg.course_id and l.field = 'official_url')
     order by pg.course_id;
  get diagnostics v_n = row_count;
  update pipeline.firecrawl_runs set items = v_n, status = case when v_n = 0 then 'done' else 'running' end, finished_at = case when v_n = 0 then now() end where id = v_run;
  insert into pipeline.admin_control_events(area, action, target, detail, actor) values ('toolsets', 'firecrawl_run_start', 'find_page', jsonb_build_object('run_id', v_run, 'items', v_n, 'credits_cap', p_cap, 'upgrade_pattern', p_page_pattern, 'query', p_query, 'provider_id', p_provider_id, 'reason', p_reason), p_actor);
  if v_n > 0 then perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'fc_run', 'run_id', v_run)); end if;
  return jsonb_build_object('run_id', v_run, 'items', v_n);
end $$;


ALTER FUNCTION "security"."firecrawl_upgrade_run_v1"("p_provider_id" "uuid", "p_query" "text", "p_page_pattern" "text", "p_cap" numeric, "p_reason" "text", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."first_run_verify_jobs_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.release_job_verifications; d record; v_max bigint; v_hi bigint; v_scan int := security.pipeline_num_v1('frv.runs_scan', 5000)::int;
        v_grace int := security.pipeline_num_v1('frv.grace_minutes', 20)::int; v_dead int := security.pipeline_num_v1('frv.verify_deadline_hours', 24)::int;
        m jsonb; z jsonb; v_status text; v_reason text; v_res jsonb; v_cls pipeline.recovery_error_classes; i pipeline.integration_issues; t pipeline.progress_transitions;
        v_n jsonb := jsonb_build_object('found_runs', 0, 'verified', 0, 'failed', 0, 'awaiting', 0, 'unverified_raised', 0);
begin
  select max(x.runid) into v_max from cron.job_run_details x;
  -- 1 the first run of each awaiting job
  for r in select * from pipeline.release_job_verifications where status = 'awaiting_first_run' and first_runid is null and jobid is not null order by id loop
    v_hi := least(v_max, coalesce(r.scan_from_runid, v_max - v_scan) + v_scan);
    select x.runid, x.status, x.start_time, x.end_time, x.return_message into d from cron.job_run_details x
     where x.runid > coalesce(r.scan_from_runid, v_max - v_scan) and x.runid <= v_hi and x.jobid = r.jobid and x.start_time >= r.deployed_at
     order by x.runid limit 1;
    if d.runid is not null and d.status in ('succeeded', 'failed') then
      update pipeline.release_job_verifications set first_runid = d.runid, first_run_at = d.start_time, first_run_status = d.status,
             first_run_message = left(d.return_message, 1000), scan_from_runid = d.runid, checked_at = now() where id = r.id;
      v_n := jsonb_set(v_n, '{found_runs}', to_jsonb((v_n->>'found_runs')::int + 1));
    elsif d.runid is not null then
      update pipeline.release_job_verifications set scan_from_runid = d.runid - 1, checked_at = now(), status_reason = 'first run in progress (run ' || d.runid || ')' where id = r.id;
    else
      update pipeline.release_job_verifications set scan_from_runid = v_hi, checked_at = now() where id = r.id;
      if v_hi = v_max and r.expected_first_run is not null and now() > r.expected_first_run + make_interval(mins => v_grace) then
        update pipeline.release_job_verifications set status = 'failed_first_run', first_run_status = 'did_not_run',
               status_reason = 'no run started by ' || (r.expected_first_run + make_interval(mins => v_grace)) || ' (expected ' || r.expected_first_run || ')' where id = r.id;
      end if;
    end if;
  end loop;
  -- 2 judge the first runs found
  for r in select * from pipeline.release_job_verifications where status = 'awaiting_first_run' and first_runid is not null order by id loop
    v_status := 'awaiting_first_run'; v_reason := r.status_reason; m := null; z := null;
    if r.first_run_status = 'failed' then
      v_status := 'failed_first_run'; v_reason := 'first run ' || r.first_runid || ' failed: ' || left(coalesce(r.first_run_message, ''), 200);
    elsif r.transition_key is null then
      v_reason := 'first run ' || r.first_runid || ' succeeded; no output measure is named for this job';
    else
      select * into t from pipeline.progress_transitions where key = r.transition_key;
      m := security.progress_measure_v1(r.transition_key, r.first_run_at);
      z := security.progress_zero_reason_v1(r.transition_key, m);
      if coalesce((m->>'created')::numeric, 0) >= coalesce(r.expected_min_output, 0) and coalesce((m->>'created')::numeric, 0) > 0 then
        if t.next_key is null or coalesce((m->>'downstream')::numeric, 0) > 0 or coalesce((m->>'admitted')::numeric, 0) > 0 or coalesce((m->>'published')::numeric, 0) > 0 then
          v_status := 'operationally_verified'; v_reason := 'first run ' || r.first_runid || ' succeeded; ' || (m->>'created') || ' created, ' || coalesce(m->>'downstream', '0') || ' queued downstream';
        else
          v_reason := 'output created but nothing is eligible downstream yet (' || coalesce(t.next_key, '') || ')';
        end if;
      elsif coalesce(r.expected_min_output, 0) = 0 or z->>'reason' in ('no_eligible_work', 'correctly_excluded') then
        v_status := 'operationally_verified'; v_reason := 'first run ' || r.first_runid || ' succeeded with a justified zero: ' || coalesce(z->>'reason', 'none expected');
      elsif z->>'reason' in ('cap_reached', 'blocked_authority') then
        v_reason := 'first run ' || r.first_runid || ' succeeded but is held: ' || (z->>'reason') || ' (' || left(coalesce(z->>'detail', ''), 160) || ')';
      elsif coalesce((m->>'created')::numeric, 0) > 0 then
        v_reason := 'first run ' || r.first_runid || ' created ' || (m->>'created') || ' of ' || r.expected_min_output || ' expected';
      else
        v_status := 'failed_first_run'; v_reason := 'first run ' || r.first_runid || ' succeeded but created nothing with eligible work: ' || left(coalesce(z->>'detail', ''), 200);
      end if;
    end if;
    update pipeline.release_job_verifications set status = v_status, status_reason = v_reason, checked_at = now(),
           actual_output = (m->>'created')::numeric, output_measure = m, downstream_eligible = (m->>'downstream')::numeric, zero_reason = z->>'reason',
           verified_at = case when v_status = 'operationally_verified' then now() end where id = r.id;
  end loop;
  -- 3 outcomes: issues for failed first runs; verified fixes; unverified past the deadline
  for r in select * from pipeline.release_job_verifications where checked_at >= now() - make_interval(mins => 1) or (status = 'failed_first_run' and issue_id is null) order by id loop
    if r.status = 'failed_first_run' and r.issue_id is null then
      v_cls := security.recovery_error_class_v1(r.first_run_message);
      v_res := security.integration_issue_upsert_v1(jsonb_build_object(
        'fingerprint', case when r.first_run_status = 'failed' then 'job_failed:' || r.jobname else 'first_run:' || r.jobname end,
        'title', 'Release ' || r.release || ': scheduled job "' || r.jobname || '" failed its first production run', 'layer', 'Release', 'subsystem', 'scheduled jobs',
        'failure', r.status_reason, 'expected', 'The first scheduled run after the release completes, creates its expected output and makes downstream work eligible',
        'source', 'first-run-verify', 'validation_layer', 'V3', 'severity', 'P1', 'root_cause_class', coalesce(v_cls.root_cause_class, 'unclassified'), 'workstream', 'A8',
        'evidence', jsonb_build_object('first_run', jsonb_build_object('release', r.release, 'job', r.jobname, 'runid', r.first_runid, 'at', r.first_run_at,
                    'status', r.first_run_status, 'message', left(r.first_run_message, 500), 'expected_first_run', r.expected_first_run, 'error_class', v_cls.error_class)),
        'observed_at', coalesce(r.first_run_at, now())), 'first-run-verify');
      update pipeline.release_job_verifications set issue_id = (v_res->>'id')::bigint where id = r.id;
      if v_res->>'action' <> 'created' and v_res->>'status' <> 'closed' then  -- an existing issue: the first-run evidence goes on it with a history line
        perform security.integration_issue_transition_v1((v_res->>'id')::bigint, null, 'first-run-verify', 'Release ' || r.release || ': first run of ' || r.jobname || ' failed: '
          || left(r.status_reason, 300), jsonb_build_object('evidence', jsonb_build_object('first_run', jsonb_build_object('release', r.release, 'job', r.jobname, 'runid', r.first_runid,
          'at', r.first_run_at, 'status', r.first_run_status, 'message', left(r.first_run_message, 500), 'error_class', v_cls.error_class))));
      end if;
      select * into i from pipeline.integration_issues where id = (v_res->>'id')::bigint;
      -- a fix that was deployed failed its first run: back to remediation with the new evidence (the canonical issue, when this one is superseded)
      if i.superseded_by is not null then select * into i from pipeline.integration_issues where id = i.superseded_by; end if;
      if i.status in ('integration_testing', 'deployed', 'production_verification') then
        perform security.integration_issue_transition_v1(i.id, 'in_progress', 'first-run-verify',
          'Release ' || r.release || ': the first scheduled run of ' || r.jobname || ' failed again (run ' || coalesce(r.first_runid::text, 'none') || '): ' || left(coalesce(r.first_run_message, r.status_reason), 300),
          jsonb_build_object('evidence', jsonb_build_object('first_run_failed', jsonb_build_object('release', r.release, 'runid', r.first_runid, 'message', left(r.first_run_message, 500)))));
        update pipeline.integration_issues set remediation_status = 'returned', remediation_checkpoint_at = now(),
               remediation_evidence = coalesce(remediation_evidence, '{}'::jsonb) || jsonb_build_object('returned_by', r.release, 'runid', r.first_runid) where id = i.id;
      end if;
      v_n := jsonb_set(v_n, '{failed}', to_jsonb((v_n->>'failed')::int + 1));
    elsif r.status = 'operationally_verified' and r.verified_at >= now() - make_interval(mins => 1) then
      for i in select * from pipeline.integration_issues x where x.status <> 'closed' and x.remediation_status in ('fix_released', 'awaiting_first_run', 'returned', 'engineering_open')
                 and (x.fingerprint = 'job_failed:' || r.jobname or x.remediation_evidence->>'job' = r.jobname) loop
        update pipeline.integration_issues set remediation_status = 'verified', remediation_checkpoint_at = null,
               remediation_evidence = coalesce(remediation_evidence, '{}'::jsonb) || jsonb_build_object('verified_by', r.release, 'runid', r.first_runid, 'output', r.actual_output) where id = i.id;
        perform security.integration_issue_transition_v1(i.id, null, 'first-run-verify', 'Release ' || r.release || ': first scheduled run ' || r.first_runid || ' of ' || r.jobname
          || ' operationally verified (' || coalesce(r.status_reason, '') || ')', '{}'::jsonb);
        if security.pipeline_num_v1('recovery.close_on_verified_on', 0) >= 1 then
          perform security.integration_issue_close_v1(i.id, 'first-run-verify', jsonb_build_object('outcome', 'passed', 'checked_at', now(),
            'reference', 'pipeline.release_job_verifications#' || r.id, 'evidence', 'Release ' || r.release || ': first scheduled run ' || r.first_runid || ' of ' || r.jobname
            || ' succeeded and was operationally verified: ' || coalesce(r.status_reason, '')));
        end if;
      end loop;
      v_n := jsonb_set(v_n, '{verified}', to_jsonb((v_n->>'verified')::int + 1));
    end if;
  end loop;
  for r in select * from pipeline.release_job_verifications where status = 'awaiting_first_run' and deployed_at < now() - make_interval(hours => v_dead) loop
    v_res := security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'first_run:' || r.jobname,
      'title', 'Release ' || r.release || ': job "' || r.jobname || '" still not operationally verified after ' || v_dead || ' h', 'layer', 'Release', 'subsystem', 'scheduled jobs',
      'failure', coalesce(r.status_reason, 'awaiting its first run'), 'expected', 'A released job is operationally verified, or its block is owned with a next checkpoint',
      'source', 'first-run-verify', 'validation_layer', 'V3', 'severity', 'P2', 'root_cause_class', 'unclassified', 'workstream', 'A8', 'assignee', 'engineering',
      'evidence', jsonb_build_object('first_run', jsonb_build_object('release', r.release, 'job', r.jobname, 'status_reason', r.status_reason, 'active_at_deploy', r.active_at_deploy,
                  'expected_first_run', r.expected_first_run, 'zero_reason', r.zero_reason))), 'first-run-verify');
    if r.issue_id is null then update pipeline.release_job_verifications set issue_id = (v_res->>'id')::bigint where id = r.id; end if;
    v_n := jsonb_set(v_n, '{unverified_raised}', to_jsonb((v_n->>'unverified_raised')::int + 1));
  end loop;
  -- 4 each release's operational state on its deploy check
  update pipeline.integration_deploy_checks c set operational_status = s.st, operational_checked_at = now()
    from (select v.deploy_check_id id, case when bool_or(v.status = 'failed_first_run') then 'failed_first_run' when bool_or(v.status = 'awaiting_first_run') then 'awaiting_first_run'
                 else 'operationally_verified' end st from pipeline.release_job_verifications v where v.deploy_check_id is not null group by 1) s
   where c.id = s.id and c.operational_status is distinct from s.st;
  select count(*) into v_max from pipeline.release_job_verifications where status = 'awaiting_first_run';
  return v_n || jsonb_build_object('awaiting', v_max);
end $$;


ALTER FUNCTION "security"."first_run_verify_jobs_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."first_run_verify_tick_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb := '{}'::jsonb; v_r jsonb;
begin
  if not pg_try_advisory_xact_lock(hashtext('cf247:first-run-verify')) then return jsonb_build_object('busy', true); end if;  -- fixed: one check at a time
  if security.pipeline_num_v1('frv.on', 1) >= 1 then
    begin v_r := security.first_run_verify_jobs_v1(); exception when others then v_r := jsonb_build_object('error', left(sqlerrm, 300)); end;
    v := v || jsonb_build_object('first_runs', v_r);
  end if;
  begin v_r := security.progress_read_v1(); exception when others then v_r := jsonb_build_object('error', left(sqlerrm, 300)); end;
  v := v || jsonb_build_object('progress', v_r);
  begin v_r := security.recovery_link_duplicates_v1(); exception when others then v_r := jsonb_build_object('error', left(sqlerrm, 300)); end;
  v := v || jsonb_build_object('link', v_r);
  begin v_r := security.recovery_route_engineering_v1(); exception when others then v_r := jsonb_build_object('error', left(sqlerrm, 300)); end;
  v := v || jsonb_build_object('route', v_r);
  -- recovery knowledge (direction 4 Nov 2026 18:08 §2-§3): outcomes, blocks and readings, isolated
  begin v_r := security.ops_learning_tick_v1(); exception when others then v_r := jsonb_build_object('error', left(sqlerrm, 300)); end;
  v := v || jsonb_build_object('learn', v_r);
  return v;
end $$;


ALTER FUNCTION "security"."first_run_verify_tick_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."flag_jobs_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare j record; f pipeline.enrichment_flags; v_n int; v_work int; v_since timestamptz; v_until timestamptz; v jsonb := '[]'::jsonb;
        v_need int := security.pipeline_num_v1('flag.empty_calls_to_pause', 30)::int;
        -- SS-014 D14 (2 Nov 2026): only calls old enough to have answered are counted; the call still under way is never one of the last runs
        v_answered timestamptz := now() - make_interval(secs => security.pipeline_num_v1('flag.answer_wait_seconds', 120));
        v_never text[] := coalesce((select array(select jsonb_array_elements_text(s.value)) from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'flag.never_pause_modes'), '{}');
begin
  for j in select c.jobid, c.jobname, c.active, (regexp_match(c.command, $re$'mode',\s*'([a-z_0-9]+)'$re$))[1] mode
             from cron.job c where c.command like '%svc_pilot_submit_nonce(''coverage-sweep''%' loop
    continue when j.mode is null or j.mode = any (v_never);
    select * into f from pipeline.enrichment_flags x where x.entity = 'job' and x.entity_key = j.jobname and x.field = '' and x.reason_code = 'idle_paused';
    if j.active and (f.id is null or f.state <> 'raised') then
      select count(*), count(*) filter (where coalesce(security.worker_call_work_v1(r.content), 1) > 0), min(l.created_at), max(l.created_at) into v_n, v_work, v_since, v_until
        from (select l2.* from pipeline.edge_request_log l2 where l2.function_name = 'coverage-sweep' and l2.mode = j.mode and l2.created_at > coalesce(f.released_at, '-infinity') and l2.created_at <= v_answered
               order by l2.created_at desc limit v_need) l
        join net._http_response r on r.id = l.request_id where r.status_code = 200;
      if v_n >= v_need and v_work = 0
         and not (security.pipeline_num_v1('tasks.lane_hold_on', 0) >= 1 and security.lane_task_waiting_v1(j.mode)) then  -- CF-247 IQ-00064: a lane a task waits for is held, not idle
        perform cron.alter_job(j.jobid, active := false);
        perform security.flag_raise_v1('job', j.jobname, null, '', 'idle_paused', format('Paused: its last %s runs found nothing to do (worker mode %s)', v_n, j.mode), 'hard', 'flag-recheck', 'auto',
          jsonb_build_object('mode', j.mode, 'runs', v_n, 'with_work', 0, 'from', v_since, 'to', v_until),
          null, now() + least(make_interval(hours => coalesce(security.flag_list_num_v1('flag.job_recheck_hours', coalesce(f.checks, 0)), 6)),
                                 make_interval(mins => security.pipeline_num_v1('tick.backoff_max_minutes', 15)::int)));  /* R1 Q2 (24 Oct 2026): never longer than the backoff cap */
        v := v || jsonb_build_object('paused', j.jobname);
      end if;
    elsif not j.active and f.state = 'raised' and f.reason_code = 'idle_paused' and (f.next_check_at <= now() or security.worker_mode_waiting_v1(j.mode)
                                                                                or (security.pipeline_num_v1('tasks.lane_hold_on', 0) >= 1 and security.lane_task_waiting_v1(j.mode)))  -- 19 Oct: on again when work is waiting
          and not security.job_held_off_v1(j.jobname) then  -- CF-247 IQ-00060: never a job a person or a governed restore switched off (jobs.held_off)
      perform security.flag_release_v1(f.id, 'flag-recheck', 'auto', 'Trial run: switched on again to look for new work', jsonb_build_object('mode', j.mode, 'check', f.checks + 1), true);
      v := v || jsonb_build_object('trial', j.jobname);
    end if;
  end loop;
  return v;
end $_$;


ALTER FUNCTION "security"."flag_jobs_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."flag_list_num_v1"("p_key" "text", "p_n" integer) RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- the n-th step of a back-off list setting (0-based); past the end, the last step
  select ((s.value -> least(greatest(p_n, 0), jsonb_array_length(s.value) - 1)) #>> '{}')::numeric::int
    from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = p_key and jsonb_typeof(s.value) = 'array' and jsonb_array_length(s.value) > 0
$$;


ALTER FUNCTION "security"."flag_list_num_v1"("p_key" "text", "p_n" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."flag_provider_held_v1"("p_provider_id" "uuid", "p_codes" "text"[]) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from pipeline.enrichment_flags f where f.provider_id = p_provider_id and f.entity = 'provider' and f.state = 'raised'
                   and (f.reason_code = any (p_codes) or f.reason_code = 'manual_hold'))
$$;


ALTER FUNCTION "security"."flag_provider_held_v1"("p_provider_id" "uuid", "p_codes" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."flag_raise_v1"("p_entity" "text", "p_key" "text", "p_provider_id" "uuid", "p_field" "text", "p_code" "text", "p_reason" "text", "p_kind" "text", "p_actor" "text", "p_actor_kind" "text", "p_evidence" "jsonb", "p_input_mark" "text", "p_next_check" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare f pipeline.enrichment_flags; v_state text; v_action text; v_tries int; v_soft int := security.pipeline_num_v1('flag.soft_tries', 2)::int;
begin
  perform set_config('cf.flag_fn', '1', true);
  select * into f from pipeline.enrichment_flags x where x.entity = p_entity and x.entity_key = p_key and x.field = coalesce(p_field, '') and x.reason_code = p_code for update;
  if not found then
    v_state := case when p_kind = 'hard' or v_soft <= 1 then 'raised' else 'counting' end;
    insert into pipeline.enrichment_flags(entity, entity_key, provider_id, field, reason_code, reason, source, kind, state, tries, evidence, next_check_at, input_mark, raised_by_kind, cleared_at)
    values (p_entity, p_key, p_provider_id, coalesce(p_field, ''), p_code, p_reason, p_actor, p_kind, v_state, 1, coalesce(p_evidence, '{}'::jsonb), p_next_check, p_input_mark, p_actor_kind,
            case when v_state = 'raised' then null else now() end)
    returning * into f;
    v_action := case v_state when 'raised' then 'raised' else 'counted' end;
  elsif f.state = 'raised' then
    update pipeline.enrichment_flags set reason = p_reason, evidence = coalesce(p_evidence, evidence), input_mark = coalesce(p_input_mark, input_mark),
           next_check_at = coalesce(p_next_check, next_check_at) where id = f.id;
    v_state := 'raised';  -- already held: evidence refreshed, no new history line
  else
    v_tries := case when f.state = 'counting' then f.tries + 1 else 1 end;
    v_state := case when p_kind = 'hard' or v_tries >= v_soft then 'raised' else 'counting' end;
    update pipeline.enrichment_flags set reason = p_reason, source = p_actor, kind = p_kind, state = v_state, tries = v_tries, evidence = coalesce(p_evidence, '{}'::jsonb),
           next_check_at = p_next_check, input_mark = coalesce(p_input_mark, input_mark), raised_by_kind = p_actor_kind, flagged_at = now(),
           cleared_at = case when v_state = 'raised' then null else coalesce(cleared_at, now()) end,
           released_at = case when v_state = 'raised' then null else released_at end
     where id = f.id;
    v_action := case when v_state = 'counting' then 'counted' when f.state = 'released' then 're_raised' else 'raised' end;
  end if;
  if v_action is not null then
    insert into pipeline.enrichment_flag_events(flag_id, action, actor, actor_kind, reason, evidence) values (f.id, v_action, p_actor, p_actor_kind, p_reason, coalesce(p_evidence, '{}'::jsonb));
  end if;
  perform set_config('cf.flag_fn', '', true);
  return jsonb_build_object('id', f.id, 'state', v_state);
end $$;


ALTER FUNCTION "security"."flag_raise_v1"("p_entity" "text", "p_key" "text", "p_provider_id" "uuid", "p_field" "text", "p_code" "text", "p_reason" "text", "p_kind" "text", "p_actor" "text", "p_actor_kind" "text", "p_evidence" "jsonb", "p_input_mark" "text", "p_next_check" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."flag_recheck_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare f record; v_jobs jsonb; v_due int := 0; v_changed int := 0; v_sites int; v_req bigint;
begin
  -- Pipeline Maintenance Mode (15 Nov 2026): while paused, nothing is released and no job is switched on
  if security.maintenance_hold_v1() then return jsonb_build_object('maintenance', 'paused'); end if;
  v_jobs := security.flag_jobs_v1();
  -- held until a date (central pages not due, no budget today, logo looked for again): released when the date comes
  for f in select id, reason_code, checks from pipeline.enrichment_flags where state = 'raised' and next_check_at <= now() and reason_code in ('central_not_due', 'central_budget', 'logo_not_found') loop
    perform security.flag_release_v1(f.id, 'flag-recheck', 'auto', 'Due again: released on its recheck date', jsonb_build_object('check', f.checks + 1), true);
    v_due := v_due + 1;
  end loop;
  -- held course fields whose course page was read again with new content: released
  for f in select x.id from pipeline.enrichment_flags x
            where x.state = 'raised' and x.entity = 'course' and x.reason_code = 'enrich_no_value'
              and exists (select 1 from pipeline.coverage_course_pages g where g.course_id = x.entity_key::uuid and g.evidence_id is not null
                            and g.evidence_id::text is distinct from x.input_mark and g.read_at > x.flagged_at)
            limit security.pipeline_num_v1('batch.flag_change_scan', 2000)::int loop
    perform security.flag_release_v1(f.id, 'flag-recheck', 'auto', 'Input changed: the course page was read again with new content', '{}'::jsonb, false);
    v_changed := v_changed + 1;
  end loop;
  -- held providers whose website is due a free check: the worker reads their home page directly (no Firecrawl, no AI)
  select count(*) into v_sites from pipeline.enrichment_flags where state = 'raised' and reason_code = 'site_unreachable' and next_check_at <= now();
  if v_sites > 0 then
    v_req := pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'flag_check', 'limit', security.pipeline_num_v1('batch.flag_check', 20)::int));
  end if;
  return jsonb_build_object('jobs', v_jobs, 'released_due', v_due, 'released_changed', v_changed, 'sites_due', v_sites);
end $$;


ALTER FUNCTION "security"."flag_recheck_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."flag_release_v1"("p_id" bigint, "p_actor" "text", "p_actor_kind" "text", "p_reason" "text", "p_evidence" "jsonb", "p_keep_checks" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare f pipeline.enrichment_flags; v_q text;
begin
  perform set_config('cf.flag_fn', '1', true);
  update pipeline.enrichment_flags set state = 'released', cleared_at = now(), released_at = now(), released_by = p_actor, release_kind = p_actor_kind, release_reason = p_reason,
         tries = 0, checks = case when p_keep_checks then checks + 1 else 0 end, next_check_at = null
   where id = p_id and state <> 'released' returning * into f;
  if not found then perform set_config('cf.flag_fn', '', true); return null; end if;
  insert into pipeline.enrichment_flag_events(flag_id, action, actor, actor_kind, reason, evidence) values (f.id, 'released', p_actor, p_actor_kind, p_reason, coalesce(p_evidence, '{}'::jsonb));
  v_q := security.flag_requeue_v1(f.id);
  if v_q is not null then
    insert into pipeline.enrichment_flag_events(flag_id, action, actor, actor_kind, reason, evidence) values (f.id, 'requeued', p_actor, p_actor_kind, 'Back in the queue: ' || v_q, '{}'::jsonb);
  end if;
  perform set_config('cf.flag_fn', '', true);
  return jsonb_build_object('id', f.id, 'state', 'released', 'requeued', v_q);
end $$;


ALTER FUNCTION "security"."flag_release_v1"("p_id" bigint, "p_actor" "text", "p_actor_kind" "text", "p_reason" "text", "p_evidence" "jsonb", "p_keep_checks" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."flag_requeue_v1"("p_id" bigint) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare f pipeline.enrichment_flags; v_jobid bigint;
begin
  select * into f from pipeline.enrichment_flags where id = p_id;
  if f.reason_code in ('logo_not_found', 'site_unreachable') or (f.entity = 'provider' and f.reason_code = 'manual_hold') then
    update pipeline.provider_logo_finds set status = 'queued', updated_at = now() where provider_id = f.provider_id and status in ('not_found', 'failed');
    update pipeline.provider_central_search set state = 'queued', attempts = 0, leased_until = null, updated_at = now()
     where provider_id = f.provider_id and state in ('queued', 'failed') and f.reason_code <> 'logo_not_found';
    return case when f.reason_code = 'logo_not_found' then 'logo finder' else 'logo finder and central pages' end;
  elsif f.reason_code in ('central_not_due', 'central_budget') then
    update pipeline.provider_central_search set state = 'queued', attempts = 0, leased_until = null, updated_at = now() where provider_id = f.provider_id;
    return 'central pages';
  elsif f.entity = 'provider' and f.reason_code = 'course_pages_not_found' then
    -- CF-247 20 Oct 2026: released by a person: onboarding again from the website step, and its site mapped again
    update pipeline.provider_onboarding ob set status = 'website', stop_reason = null, step_started_at = now(), job_id = null,
           note = 'Released by a person (course pages not found); starting again from the website.', updated_at = now()
     where ob.id = (select o2.id from pipeline.provider_onboarding o2 where o2.provider_id = f.provider_id order by o2.created_at desc limit 1)
       and ob.status in ('stopped', 'done', 'cancelled');
    update pipeline.coverage_provider_discovery set status = 'pending', attempts = 0, next_due_at = now(), leased_until = null, updated_at = now()
     where provider_id = f.provider_id;
    return 'onboarding and site discovery';
  elsif f.entity = 'job' and f.reason_code in ('idle_paused', 'manual_hold') then
    select jobid into v_jobid from cron.job where jobname = f.entity_key;
    -- Pipeline Maintenance Mode (15 Nov 2026): a job is not switched on while the pipeline is paused
    if v_jobid is not null and security.maintenance_hold_v1() then
      raise exception 'The pipeline is paused for maintenance: no job is switched on until Resume Pipeline (Automations)' using errcode = '55000';
    end if;
    if v_jobid is not null then perform cron.alter_job(v_jobid, active := true); end if;
    update pipeline.job_idle_watch set paused_at = null, resumed_at = now() where jobname = f.entity_key;
    return 'job switched on';
  elsif f.entity = 'course' then
    return 'the next Enrich fields task includes it';
  end if;
  return null;
end $$;


ALTER FUNCTION "security"."flag_requeue_v1"("p_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."flag_tool_summary_v1"("p_provider" "uuid", "p_course" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when p_course is null then
    jsonb_build_object(
      'scope', 'provider',
      'since', (select min(u.snapshot_date) from pipeline.toolset_use_daily u where u.provider_id = p_provider),
      'site_map', (select jsonb_build_object('status', d.status, 'pages', d.url_count, 'course_pages', d.kept_count, 'how', d.method)
                     from pipeline.coverage_provider_discovery d where d.provider_id = p_provider),
      'tools', coalesce((select jsonb_agg(jsonb_build_object('tool', z.tool, 'used', z.used, 'ok', z.ok, 'failed', z.failed, 'credits', z.credits, 'cost_usd', round(z.cost, 3))
                                          order by array_position(array['course_search','page_reads','ai_page_match','ai_field_reader','fee_reader','scholarship_ai','other_credits','flags_raised'], z.tool))
                           from (select u.tool, sum(u.used) used, sum(u.ok) ok, sum(u.failed) failed, sum(u.credits) credits, sum(u.cost_usd) cost
                                   from pipeline.toolset_use_daily u where u.provider_id = p_provider group by u.tool) z), '[]'::jsonb))
  else
    jsonb_build_object(
      'scope', 'course',
      'tools', (select coalesce(jsonb_agg(e), '[]'::jsonb) from jsonb_array_elements(jsonb_build_array(
        (select jsonb_build_object('tool', 'course_search', 'used', coalesce(s.attempts, 0), 'ok', case when s.state in ('found', 'verified') then 1 else 0 end,
                                   'failed', case when s.state = 'none' then 1 else 0 end, 'note', s.state)
           from pipeline.course_link_search s where s.course_id = p_course),
        (select jsonb_build_object('tool', 'ai_page_match', 'used', count(*),
                                   'ok', count(*) filter (where q.state = 'chosen' and exists (select 1 from pipeline.coverage_course_pages g where g.course_id = q.course_id and g.url = q.chosen_url and g.status = 'bound' and g.read_status = 'read')),
                                   'failed', count(*) filter (where q.state in ('none', 'no_candidates', 'error')), 'cost_usd', round(coalesce(sum(q.cost_usd), 0), 4),
                                   'note', string_agg(distinct q.state, ', '))
           from pipeline.coverage_ai_match q where q.course_id = p_course having count(*) > 0),
        (select jsonb_build_object('tool', 'page_reads', 'used', g.read_attempts, 'ok', case when g.status = 'bound' and g.read_status = 'read' then 1 else 0 end,
                                   'failed', case when g.status = 'mismatch' or g.read_status in ('fetch_failed', 'blocked', 'needs_render', 'robots_disallowed') then 1 else 0 end,
                                   'note', g.basis || ' · ' || g.status || coalesce(' · ' || g.read_status, ''))
           from pipeline.coverage_course_pages g where g.course_id = p_course),
        (select jsonb_build_object('tool', 'ai_field_reader', 'used', count(*), 'ok', count(*) filter (where e.state = 'filled'),
                                   'failed', count(*) filter (where e.state in ('skipped', 'failed')), 'cost_usd', round(coalesce(sum(e.cost_usd), 0), 4))
           from pipeline.field_enrich_items e where e.course_id = p_course having count(*) > 0))) e where e <> 'null'::jsonb))
  end
$$;


ALTER FUNCTION "security"."flag_tool_summary_v1"("p_provider" "uuid", "p_course" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."flag_tool_summary_v1"("p_provider" "uuid", "p_course" "uuid") IS 'CF-247 22 Oct 2026: the toolset used on a provider (from pipeline.toolset_use_daily, and its site map) or a course (searches, AI page match, page read, Enrich fields) before it was flagged; shown with each flag on Layer 2/3 › Flags.';



CREATE OR REPLACE FUNCTION "security"."gap_causes_run_meta_v1"("p_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when r.started_at is null then jsonb_build_object('recorded', false, 'stale', p_at is null or now() - p_at > make_interval(mins => security.pipeline_num_v1('gaps.causes_stale_after_minutes', 75)::int),
                                                               'stale_after_minutes', security.pipeline_num_v1('gaps.causes_stale_after_minutes', 75))
    else jsonb_build_object('recorded', true, 'started_at', r.started_at, 'finished_at', r.finished_at, 'rows', r.item_count,
      'age_seconds', greatest(round(extract(epoch from now() - r.finished_at)), 0)::int,
      'stale', now() - r.finished_at > make_interval(mins => security.pipeline_num_v1('gaps.causes_stale_after_minutes', 75)::int),
      'stale_after_minutes', security.pipeline_num_v1('gaps.causes_stale_after_minutes', 75)) end
    from (select 1) one left join lateral (select g.* from pipeline.gap_cause_runs g where g.at = p_at order by g.finished_at desc limit 1) r on true
$$;


ALTER FUNCTION "security"."gap_causes_run_meta_v1"("p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."gap_causes_run_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_start timestamptz := clock_timestamp(); v_rows int; v_end timestamptz;
begin
  v_rows := security.gap_causes_snapshot_v1();
  v_end := clock_timestamp();
  insert into pipeline.gap_cause_runs(started_at, at, finished_at, item_count, source) values (v_start, date_trunc('hour', now()), v_end, coalesce(v_rows, 0), 'job')
  on conflict (started_at) do nothing;
  delete from pipeline.gap_cause_runs where started_at < now() - make_interval(days => security.pipeline_num_v1('gaps.cause_keep_days', 14)::int);
  return jsonb_build_object('rows', v_rows, 'started_at', v_start, 'finished_at', v_end);
end $$;


ALTER FUNCTION "security"."gap_causes_run_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."gap_causes_snapshot_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_at timestamptz := date_trunc('hour', now()); v int; v_stopped uuid[] := array(select x.provider_id from security.fc_search_stopped_v1() x);
        v_render text[] := array(select jsonb_array_elements_text(s.value) from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'pages.render_countries');
        v_fee_cc text[] := array(select jsonb_array_elements_text(s.value) from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'fees.countries');
begin
  delete from pipeline.gap_cause_snapshots where at < now() - make_interval(days => security.pipeline_num_v1('gaps.cause_keep_days', 14)::int);
  delete from pipeline.gap_cause_snapshots where at = v_at;  -- run again within the hour: the latest wins
  -- set-based: each lookup is read once (the hourly run must stay well inside the statement time limit)
  create temp table _gc on commit drop as
    select c.id, c.provider_id, k.iso_alpha2::text cc, c.duration_value, c.study_level_id, c.delivery_mode, c.primary_field_id, c.open_to_international,
           g.status gs, g.read_status rs, g.identity_basis ib, case when s.state = 'queued' and s.provider_id = any (v_stopped) then 'stopped' else s.state end ls
      from catalogue.courses c join catalogue.providers p on p.id = c.provider_id join ref.countries k on k.id = p.country_id
      left join pipeline.coverage_course_pages g on g.course_id = c.id
      left join pipeline.course_link_search s on s.course_id = c.id
     where c.lifecycle_status = 'active'
       and (p.publication_status is not distinct from 'published' and coalesce(p.lifecycle_status, 'active') = 'active');
  create temp table _gh on commit drop as
    select course_id id, 'official_page' attr from catalogue.course_links where link_type = 'official_course' and status = 'active'
    union select course_id, 'fee' from catalogue.course_fees where audience = 'international' and status = 'active'
    union select course_id, 'english' from catalogue.course_english_requirements where coalesce(status, 'active') = 'active'
    union select course_id, 'intakes' from catalogue.course_intakes where status = 'active'
    union select course_id, 'campus' from catalogue.course_campuses
    union select cc.course_id, 'campus_region' from catalogue.course_campuses cc join catalogue.campuses k on k.id = cc.campus_id where k.subdivision_id is not null
    union select cc.course_id, 'campus_city' from catalogue.course_campuses cc join catalogue.campuses k on k.id = cc.campus_id where nullif(btrim(k.city), '') is not null;
  create index on _gh(id, attr);
  create temp table _gi on commit drop as
    select distinct on (course_id, field) course_id id, field attr, state from pipeline.field_enrich_items where course_id is not null order by course_id, field, id desc;
  create index on _gi(id, attr);
  create temp table _gf on commit drop as
    select distinct entity_key id, field attr from pipeline.enrichment_flags where entity = 'course' and reason_code = 'enrich_no_value' and state in ('raised', 'counting');
  create index on _gf(id, attr);
  create temp table _gfee on commit drop as
    select q.course_id id,
           bool_or(q.state in ('queued', 'leased')) queued, bool_or(q.state = 'done') done,
           bool_or(exists (select 1 from pipeline.fee_reader_rows r where r.queue_id = q.id and r.outcome in ('domestic', 'not_yearly'))) no_intl
      from pipeline.fee_reader_queue q where q.course_id is not null group by q.course_id;
  create temp table _greview on commit drop as
    select distinct entity_id id from pipeline.layer4_review_items where field_code = 'provider_current_tuition_validation' and status = 'pending';
  create temp table _grule on commit drop as
    select k.provider_id, k.kind,
           case when bool_or(x.status = 'approved') then 'approved' when bool_or(x.status = 'proposed') then 'waiting for approval'
                when bool_or(x.status in ('no_values', 'rejected')) then 'gives no values' else 'not found' end state
      from (select distinct provider_id from _gc) g
      cross join lateral (values (g.provider_id, 'english_policy'), (g.provider_id, 'intake_calendar')) k(provider_id, kind)
      left join pipeline.provider_policy_proposals x on x.provider_id = k.provider_id and x.kind = k.kind and x.status in ('approved', 'proposed', 'no_values', 'rejected')
     group by k.provider_id, k.kind;
  -- 23 Oct 2026 12:40: a rule not found or giving no values is automatic while suggested central pages are left to try
  update _grule r set state = r.state || ' (more central pages to try)'
   where r.kind = 'english_policy' and r.state in ('not found', 'gives no values')
     and exists (select 1 from pipeline.provider_central_search s cross join lateral jsonb_array_elements(coalesce(s.found, '[]'::jsonb)) e
                  where s.provider_id = r.provider_id and e->>'kind' = 'english_policy' and coalesce((e->>'score')::numeric, 0) >= security.pipeline_num_v1('central.min_suggest_score', 4)
                    and not exists (select 1 from pipeline.provider_fact_sources f where f.provider_id = s.provider_id and f.kind = 'english_policy' and f.url = e->>'url'))
     and (select count(*) from pipeline.provider_fact_sources f where f.provider_id = r.provider_id and f.kind = 'english_policy') < security.pipeline_num_v1('central.attach_per_kind', 3);
  update _grule r set state = r.state || ' (central page being read)'
   where r.kind = 'english_policy' and r.state in ('not found', 'gives no values')
     and (exists (select 1 from pipeline.provider_fact_sources f where f.provider_id = r.provider_id and f.kind = 'english_policy' and f.status in ('found', 'reading'))
          or exists (select 1 from pipeline.central_ai_queue q where q.provider_id = r.provider_id and q.kind = 'english_policy' and q.state in ('queued', 'leased')));
  update _grule r set state = r.state || ' (central page search queued)'
   where r.kind = 'english_policy' and r.state in ('not found', 'gives no values')
     and exists (select 1 from pipeline.provider_central_search s where s.provider_id = r.provider_id and s.state in ('queued', 'leased'));
  create temp table _gm on commit drop as
    select c.*, x.attr
      from _gc c cross join unnest(array['official_page', 'fee', 'english', 'intakes', 'campus', 'campus_region', 'duration', 'delivery', 'level', 'field_of_study', 'international']) x(attr)
     where case x.attr when 'duration' then c.duration_value is null when 'delivery' then nullif(btrim(c.delivery_mode), '') is null
                       when 'level' then c.study_level_id is null when 'field_of_study' then c.primary_field_id is null
                       when 'international' then c.open_to_international is null
                       else not exists (select 1 from _gh h where h.id = c.id and h.attr = x.attr) end;
  create temp table _gid on commit drop as
    select d.provider_id, d.ib, d.attr, security.coverage_identity_allowed(d.provider_id, d.ib, case d.attr when 'fee' then 'tuition' when 'official_page' then 'official_url' else d.attr end) ok
      from (select distinct provider_id, ib, attr from _gm where attr in ('official_page', 'fee', 'english', 'intakes')) d;
  insert into pipeline.gap_cause_snapshots(at, country_code, attribute, cause, action, automatic, courses)
  with e as (
    select m.*, i.state item_state, (f.id is not null) no_value, coalesce(idn.ok, true) id_ok, fe.queued fee_queued, fe.done fee_done, fe.no_intl fee_no_intl,
           (rv.id is not null) in_review,
           (select r.state from _grule r where r.provider_id = m.provider_id and r.kind = 'english_policy') eng_rule,
           (select r.state from _grule r where r.provider_id = m.provider_id and r.kind = 'intake_calendar') cal_rule, exists (select 1 from _gh h where h.id = m.id and h.attr = 'campus') has_campus,
           exists (select 1 from _gh h where h.id = m.id and h.attr = 'campus_city') has_city
      from _gm m
      left join _gi i on i.id = m.id and i.attr = m.attr
      left join _gf f on f.id = m.id::text and f.attr = m.attr
      left join _gid idn on idn.provider_id = m.provider_id and idn.ib is not distinct from m.ib and idn.attr = m.attr
      left join _gfee fe on fe.id = m.id and m.attr = 'fee'
      left join _greview rv on rv.id = m.id and m.attr = 'fee'),
  z as (
    select e.cc, e.attr,
      case
        when e.attr = 'campus_region' and not e.has_campus then 'no campus yet'
        when e.attr = 'campus_region' and not e.has_city then 'campus has no city'
        when e.attr = 'campus_region' then 'campus city has no region yet'
        when e.attr in ('level', 'field_of_study') and e.item_state in ('queued', 'waiting', 'ai', 'leased') then 'AI reading queued'
        when e.attr in ('level', 'field_of_study') and e.no_value then 'AI: the title gives no value'
        when e.attr in ('level', 'field_of_study') then 'not tried yet'
        when (e.gs is null or e.gs <> 'bound') and exists (select 1 from pipeline.course_no_page np where np.course_id = e.id and np.state in ('confirmed', 'confirmed_auto')) then 'no page: not published by the provider'
        when (e.gs is null or e.gs <> 'bound') and exists (select 1 from pipeline.course_no_page np where np.course_id = e.id and np.state = 'conjoint') then 'no page: conjoint or double degree (no page of its own)'
        when (e.gs is null or e.gs <> 'bound') and exists (select 1 from pipeline.coverage_provider_discovery d where d.provider_id = e.provider_id and d.status = 'failed' and coalesce(d.url_count, 0) = 0) then 'no page: provider site not answering'
        when e.gs is null or e.gs <> 'bound' then case when e.ls = 'stopped' then 'no page: web search stopped for this university' when e.ls = 'queued' then 'no page: web search queued' when e.ls = 'none' then 'no page: search and AI page match found none' else 'no page found' end
        when e.rs is distinct from 'read' then 'page not read: ' || coalesce(e.rs, 'not yet')
        when e.attr in ('official_page', 'fee', 'english', 'intakes') and not e.id_ok then 'page proof (' || coalesce(e.ib, 'none') || ') not admitted for this field'
        when e.attr = 'official_page' then 'page read, address not admitted yet'
        when e.attr = 'fee' and e.in_review then 'fee waiting in review'
        when e.attr = 'fee' and coalesce(e.fee_queued, false) then 'fee reader queued'
        when e.attr = 'fee' and not (e.cc = any (v_fee_cc)) then 'fee reader not on for this country'
        when e.attr = 'fee' and coalesce(e.fee_no_intl, false) then 'page shows no international yearly fee'
        when e.attr = 'fee' and coalesce(e.fee_done, false) then 'fee reader found no fee on the page'
        when e.attr = 'fee' then 'page shows no single international fee to the reader'
        when e.item_state in ('queued', 'waiting', 'ai', 'leased') then 'AI reading queued'
        when e.no_value and e.attr = 'english' then 'AI: page gives no IELTS; university English rule ' || coalesce(e.eng_rule, 'not found')
        when e.no_value and e.attr = 'intakes' then 'AI: page gives no start dates; university calendar ' || coalesce(e.cal_rule, 'not found')
        when e.no_value then 'AI: the page does not state it'
        else 'not tried yet' end cause
      from e)
  select v_at, z.cc, z.attr, z.cause,
         case
           when z.cause = 'no page: web search stopped for this university' then 'none: the automatic search stopped (wrong pages in a row); Search again or a person''s Find course pages task'
           when z.cause like 'no page: web search queued' then 'web search for the course page (job link-search)'
           when z.cause = 'no page: not published by the provider' then 'none: recorded (Layer 4 first run per provider, then the 60% rule); re-opened when a later map or a person finds a page'
           when z.cause = 'no page: conjoint or double degree (no page of its own)' then 'conjoint rule (Layer 4 first run per provider); binding to the parent page comes with SP-2'
           when z.cause = 'no page: provider site not answering' then 'discovery re-tries on its schedule; a person can correct the website or add a course domain'
           when z.cause like 'no page%' then 'AI page match and the university course source finder (jobs coverage-ai-match, source-find)'
           when z.cause = 'page not read: needs_render' and z.cc = any (v_render) then 'read through the scraper (pages.render_countries)'
           when z.cause = 'page not read: needs_render' then 'none: the scraper is not on for this country (pages.render_countries)'
           when z.cause in ('page not read: robots_disallowed') then 'none: the site does not allow reading'
           when z.cause like 'page not read: identity_mismatch' then 'search again for the right page'
           when z.cause like 'page not read%' then 'read again later (job coverage-read)'
           when z.cause like 'page proof%' then 'none: Settings › Identify the page decides which proofs admit this field'
           when z.cause = 'page read, address not admitted yet' then 'admission job coverage-admit'
           when z.cause = 'fee waiting in review' then 'a person decides in Layer 4'
           when z.cause = 'fee reader queued' then 'AI fee reader (job fee-reader)'
           when z.cause = 'fee reader not on for this country' then 'none: add the country to Fee reader: countries'
           when z.cause like 'page shows no%' or z.cause = 'fee reader found no fee on the page' then 'fee schedule pages of the university (AI fee reader)'
           when z.cause = 'AI reading queued' then 'AI reader (Enrich fields)'
           when z.cause like 'AI:%(central page search queued)' then 'central page search, then AI reading and approval (jobs central-find, central-attach)'
           when z.cause like 'AI:%(central page being read)' then 'central page read by AI and approved when every score is quoted (jobs provider-facts, central-ai, policy-auto-approve)'
           when z.cause like 'AI:%(more central pages to try)' then 'next suggested central page read by AI and approved when every score is quoted (jobs central-attach, central-ai, policy-auto-approve)'
           when z.cause like 'AI:%approved' then 'none: the university rule covers other study levels; the rule needs this course''s level'
           when z.cause like 'AI:%waiting for approval' then 'a person approves the university rule (Layer 4 › Attributes)'
           when z.cause like 'AI:%gives no values' then 'none: the central page read gives no values; the right central page is needed (Adapter builder › central page)'
           when z.cause like 'AI:%not found' then 'none: no central page found; add it (Adapter builder › central page)'
           when z.cause like 'AI:%' then 'read again when the page changes'
           when z.cause = 'no campus yet' then 'AI reader campus, then the region'
           when z.cause = 'campus has no city' then 'none: the campus record needs its city'
           when z.cause = 'campus city has no region yet' then 'AI reader campus region (Fill the gaps)'
           else 'AI reader (Fill the gaps, job field-gap-queue)' end,
         not (z.cause like 'page proof%' or z.cause in ('page not read: robots_disallowed', 'fee reader not on for this country', 'campus has no city', 'fee waiting in review', 'no page: web search stopped for this university')
              or (z.cause = 'page not read: needs_render' and not (z.cc = any (v_render)))
              or (z.cause like 'AI:%' and z.cause not like '%(more central pages to try)' and z.cause not like '%(central page being read)' and z.cause not like '%(central page search queued)' and (z.cause like '%approved' or z.cause like '%waiting for approval' or z.cause like '%gives no values' or z.cause like '%not found'))),
         count(*)
    from z group by z.cc, z.attr, z.cause;
  get diagnostics v = row_count;
  return v;
end $$;


ALTER FUNCTION "security"."gap_causes_snapshot_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."gap_scraper_room_v1"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- new page reads asked for by standing Fill the gaps tasks since midnight (Melbourne), against the daily limit
  select (select count(*) from pipeline.field_enrich_items e join pipeline.admin_jobs j on j.id = e.job_id
           where j.kind = 'enrich_fields' and coalesce((j.args->>'standing')::boolean, false) and 'scraper' = any (e.tried)
             and e.updated_at >= (date_trunc('day', now() at time zone 'Australia/Melbourne') at time zone 'Australia/Melbourne'))  -- fixed: the day rolls over at Melbourne midnight
         < security.pipeline_num_v1('gaps.scraper_reads_per_day', 200)
$$;


ALTER FUNCTION "security"."gap_scraper_room_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."governed_aer_close_snapshot_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c_rmit constant uuid := '8e1adb6c-e069-43db-9584-bd054255e702';
  c_scope_open constant jsonb := '["9d22a19e-c3f7-4012-b738-17bc0b481e7f", "1719c3ba-1ddf-483e-935e-c750124ba99c", "8e1adb6c-e069-43db-9584-bd054255e702"]';
  c_scope_closed constant jsonb := '["9d22a19e-c3f7-4012-b738-17bc0b481e7f", "1719c3ba-1ddf-483e-935e-c750124ba99c"]';
  -- the six runs of the recovery, their settled outcome, and each run's cumulative cost when the recovery opened (verified 27 Oct 21:51)
  c_runs constant jsonb := '[
    {"slug":"norway","run":"88e17723-1d6e-4b68-8678-ecef98d66e21","state":"failed","error":"held_unparsed: no printed scale%","cost_at_open":0.0077756},
    {"slug":"qatar","run":"e07eeaf5-f805-42d4-9976-d6a5ed9ff398","state":"done","item":"9adbeada-af55-40e8-95dc-4f4fe97cb5fe","cost_at_open":0},
    {"slug":"singapore","run":"b4aecc1c-47a5-495d-9a9b-5d19c6854209","state":"done","item":"bcd9f55b-43fd-4c5b-9e6a-ae85c68ed8bf","cost_at_open":0.0060744},
    {"slug":"sri-lanka","run":"10995ef9-c95e-4cf1-9d83-a1deb2857344","state":"done","item":"8a803c95-8d0a-4743-b79b-155085a1f0d1","cost_at_open":0.0037492},
    {"slug":"thailand","run":"494bcd84-9914-43f1-8c0e-8f59c6baafc3","state":"done","item":"f56bd767-9a19-44ba-855a-748f47aec009","cost_at_open":0.0034708},
    {"slug":"united-kingdom","run":"04349c2b-2192-4a9f-9865-0611870d8c3d","state":"failed","error":"held_incomplete:%","cost_at_open":0.0081736}]';
  -- left as they are: Vietnam held for PR B, Nigeria, the three non-country (D2) pages
  c_untouched constant jsonb := '[
    {"slug":"vietnam","run":"33eba77e-ba83-4ffa-bd1b-267ffe6aa14c","error":"held: AER PR B%"},
    {"slug":"nigeria","run":"0bcdf776-7107-4ab1-9f28-858a54f90b90","error":"held_incomplete:%"},
    {"slug":"foundation-equivalencies","run":"e47e8cdb-9432-416a-bd61-eaba26951dde","error":"held_unparsed:%"},
    {"slug":"global-assessment-certificate","run":"a3a8b518-1aa2-42e0-8ef9-457336109c1d","error":"held_unparsed:%"},
    {"slug":"international-baccalaureate","run":"5004850f-b526-474d-9cd7-374f5fc99588","error":"held_unparsed:%"}]';
  -- the lane's functions as they were when the recovery ran (a changed function means the state may differ from what was approved)
  c_md5 constant jsonb := '{"public.svc_entry_matrix_next(integer)":"f992b7fc20bfce4d27c0e7bbee4256a3",
    "public.svc_entry_matrix_record(uuid,jsonb,numeric,text)":"e1a130e278ff535e33eade3c2e0b9aa2",
    "public.admin_entry_matrix_reread(uuid[],text)":"ca394b60216ef06dfc2ce9db265e8efe",
    "security.entry_matrix_enabled_v1(uuid)":"15fc1b28e855be2d4234057527a1a086",
    "security.entry_matrix_fire_v1()":"dd985f9ab6b51bddbf5e97d1f7d83143",
    "security.entry_matrix_enqueue_v1()":"d3b562ff4bcace32bf24d308473739ed"}';
  c_active constant int := 343; c_quarantined constant int := 20; c_proposed constant int := 37;  -- fixed: preconditions of this one action
  v_scope jsonb; v_runs jsonb := '[]'; v_unt jsonb := '[]'; v_md5 jsonb := '{}'; v_checks jsonb := '[]'; x jsonb; r record; k text;
  v_ok boolean := true; v_cost numeric := 0; v_n int; v_active int; v_q int; v_prop int; v_sup int; v_items int; v_open_at timestamptz; v_due timestamptz; v_done_at timestamptz;
begin
  select value into v_scope from pipeline.platform_toolset_settings where toolset_key = 'pipeline' and key = 'entry.providers';
  select created_at into v_open_at from pipeline.admin_control_events where id = 22141 and action = 'recovery_open_paste';
  for x in select * from jsonb_array_elements(c_runs) loop
    select er.*, i.status item_status into r from pipeline.entry_matrix_runs er left join pipeline.layer4_review_items i on i.id = er.review_item_id where er.id = (x->>'run')::uuid;
    v_runs := v_runs || jsonb_build_array(jsonb_build_object('slug', x->>'slug', 'run', x->>'run', 'state', r.state, 'attempts', r.attempts, 'error', r.error,
      'completeness', r.result->'completeness'->>'status', 'matched', (r.result->'completeness'->>'matched')::int, 'expected', (r.result->'completeness'->>'expected')::int,
      'review_item', r.review_item_id, 'item_status', r.item_status, 'cost_usd', r.cost_usd,
      'cost_since_open', round(coalesce(r.cost_usd, 0) - (x->>'cost_at_open')::numeric, 7),
      'ok', r.state = x->>'state' and (x->>'error' is null or coalesce(r.error, '') like x->>'error') and (x->>'item' is null or (r.review_item_id::text = x->>'item' and r.item_status = 'pending'))));
    v_cost := v_cost + coalesce(r.cost_usd, 0) - (x->>'cost_at_open')::numeric;
  end loop;
  for x in select * from jsonb_array_elements(c_untouched) loop
    select * into r from pipeline.entry_matrix_runs where id = (x->>'run')::uuid;
    v_unt := v_unt || jsonb_build_array(jsonb_build_object('slug', x->>'slug', 'state', r.state, 'error', left(r.error, 120), 'ok', r.state = 'failed' and coalesce(r.error, '') like x->>'error'));
  end loop;
  -- A5 (30 Oct 2026), Option A: once the action has run, later change control may change these functions; c_md5 stays as the record
  select max(finished_at) into v_done_at from pipeline.admin_jobs where kind = 'governed_action' and args->>'action' = 'aer_pr_a_recovery_close' and state = 'done';
  for k in select jsonb_object_keys(c_md5) loop
    v_md5 := v_md5 || jsonb_build_object(k, md5(pg_get_functiondef(k::regprocedure)));
  end loop;
  select count(*) filter (where status = 'active'), count(*) filter (where status = 'unverified' and provenance->>'aer_flag' = 'quarantined'),
         count(*) filter (where status = 'proposed'), count(*) filter (where status = 'superseded')
    into v_active, v_q, v_prop, v_sup from catalogue.provider_entry_matrix where provider_id = c_rmit;
  select count(*) into v_items from pipeline.layer4_review_items i where i.id in (select (e->>'item')::uuid from jsonb_array_elements(c_runs) e where e ? 'item') and i.status = 'pending';
  select count(*) into v_n from pipeline.entry_matrix_runs where provider_id = c_rmit and state in ('queued', 'leased');
  select min(read_at) + make_interval(days => security.pipeline_num_v1('entry.matrix_refresh_days', 30)::int) into v_due
    from pipeline.entry_matrix_sources where provider_id = c_rmit and read_via <> 'stored';
  v_checks := jsonb_build_array(
    jsonb_build_object('check', 'The recovery being closed was opened (event 22141)', 'expected', 'opened 27 Oct 2026 21:50', 'actual', coalesce(to_char(v_open_at at time zone 'Australia/Sydney', 'DD Mon YYYY HH24:MI'), 'not found'), 'ok', v_open_at is not null),
    jsonb_build_object('check', 'RMIT is in the reading scope (UTS, WSU and RMIT)', 'expected', c_scope_open, 'actual', v_scope, 'ok', v_scope = c_scope_open),
    jsonb_build_object('check', 'The six runs have settled as recorded', 'expected', 6, 'actual', (select count(*) from jsonb_array_elements(v_runs) e where (e->>'ok')::boolean), 'ok', (select bool_and((e->>'ok')::boolean) from jsonb_array_elements(v_runs) e)),
    jsonb_build_object('check', 'No RMIT run is queued or being read', 'expected', 0, 'actual', v_n, 'ok', v_n = 0),
    jsonb_build_object('check', 'RMIT active rows', 'expected', c_active, 'actual', v_active, 'ok', v_active = c_active),
    jsonb_build_object('check', 'RMIT quarantined rows', 'expected', c_quarantined, 'actual', v_q, 'ok', v_q = c_quarantined),
    jsonb_build_object('check', 'RMIT proposed rows (in Layer 4 review)', 'expected', c_proposed, 'actual', v_prop, 'ok', v_prop = c_proposed),
    jsonb_build_object('check', 'Their four Layer 4 items are pending', 'expected', 4, 'actual', v_items, 'ok', v_items = 4),
    jsonb_build_object('check', 'Vietnam, Nigeria and the three D2 pages are held as they were', 'expected', 5, 'actual', (select count(*) from jsonb_array_elements(v_unt) e where (e->>'ok')::boolean), 'ok', (select bool_and((e->>'ok')::boolean) from jsonb_array_elements(v_unt) e)),
    case when v_done_at is null or v_md5 = c_md5
      then jsonb_build_object('check', 'The entry-reading functions are unchanged since the recovery ran', 'expected', c_md5, 'actual', v_md5, 'ok', v_md5 = c_md5)
      else jsonb_build_object('check', 'The entry-reading functions are unchanged since the recovery ran', 'expected', c_md5, 'actual', v_md5, 'ok', true,
             'note', 'action completed ' || to_char(v_done_at at time zone 'Australia/Sydney', 'DD Mon YYYY HH24:MI') || '; functions changed since by later change control') end);
  select bool_and((e->>'ok')::boolean) into v_ok from jsonb_array_elements(v_checks) e;
  return jsonb_build_object('action', 'aer_pr_a_recovery_close', 'ok', coalesce(v_ok, false), 'checks', v_checks, 'runs', v_runs, 'untouched', v_unt,
    'counts', jsonb_build_object('active', v_active, 'proposed', v_prop, 'quarantined', v_q, 'superseded', v_sup, 'items_pending', v_items),
    'cost_usd_since_open', round(v_cost, 4), 'cost_basis', 'each run''s cost now, less its cost when the recovery opened (verified 27 Oct 2026 21:51)',
    'scope', jsonb_build_object('now', v_scope, 'after', c_scope_closed, 'open', c_scope_open), 'refresh_due', v_due, 'opened_at', v_open_at);
end $$;


ALTER FUNCTION "security"."governed_aer_close_snapshot_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."governed_aer_close_snapshot_v1"() IS 'CF-247 Decision 268: live state and preconditions of the governed closure of the AER PR A recovery (read only). A5 (30 Oct 2026, Option A): the recorded function md5s are kept; once the action is done, a later change to those functions is reported as completed, not as a failed precondition.';



CREATE OR REPLACE FUNCTION "security"."har_aer_admitted_v1"("p_provider" "uuid", "p_since" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with a as (select (select count(*) from catalogue.provider_entry_matrix m where m.provider_id = p_provider and m.status = 'active' and m.updated_at >= p_since)
                  + (select count(*) from catalogue.course_entry_requirements x join catalogue.courses c on c.id = x.course_id
                      where c.provider_id = p_provider and x.status = 'active' and x.updated_at >= p_since) n)
  select jsonb_build_object('admitted', a.n > 0, 'active_since_input', a.n,
           'published', a.n > 0 and to_regprocedure('public.website_v2_provider(text)') is not null
                        and coalesce(jsonb_array_length(case when jsonb_typeof(public.website_v2_provider((select p.stable_key from catalogue.providers p where p.id = p_provider))->'item'->'entry_matrix') = 'array'
                                                             then public.website_v2_provider((select p.stable_key from catalogue.providers p where p.id = p_provider))->'item'->'entry_matrix' end), 0) > 0)
    from a
$$;


ALTER FUNCTION "security"."har_aer_admitted_v1"("p_provider" "uuid", "p_since" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_aer_generate_v1"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_res jsonb; v_n int := 0; v_rep int := 0; v_skip int := 0; v_per int := security.pipeline_num_v1('har.generate_per_provider_max', 2)::int;
        v_look timestamptz := now() - make_interval(hours => security.pipeline_num_v1('har.aer_empty_read_lookback_hours', 48)::int);
begin
  for r in
    with followed as (select x::uuid pid, n from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'coverage.aer_priority_providers'), '[]'::jsonb)) with ordinality z(x, n)),
    rd as (select s.provider_id, count(*) filter (where s.status = 'read') nread from pipeline.entry_matrix_sources s group by 1),
    -- course reads of the window made after the university's newest course entry row (CDU: 8 reads since 3 Nov, the last 6 with no row)
    reads0 as (select (e->>'provider_id')::uuid pid, a.ran_at, e->>'course_id' course
                 from pipeline.aer_schedule_runs a cross join lateral jsonb_array_elements(case when jsonb_typeof(a.detail->'new') = 'array' then a.detail->'new' else '[]'::jsonb end) e
                where a.ran_at >= v_look and e ? 'provider_id'),
    reads as (select q.pid, count(*) n, min(q.ran_at) first_at, jsonb_agg(distinct q.course) courses
                from reads0 q
               where q.ran_at > coalesce((select max(x.created_at) from catalogue.course_entry_requirements x join catalogue.courses c on c.id = x.course_id where c.provider_id = q.pid), '-infinity'::timestamptz)
               group by 1),
    cand as (
      select i.provider_id, i.provider_id::text entity, null::uuid course_id,
             case i.outcome when 'blocked_site' then 'aer_source_missing' when 'unverified_link' then 'aer_document_unverified' else 'aer_rendered_only' end cls,
             greatest(1, coalesce(jsonb_array_length(case when jsonb_typeof(i.evidence->'tried') = 'array' then i.evidence->'tried' end), 1)) attempts,
             i.outcome || '|' || coalesce(i.url, '') || '|' || i.id sig,
             jsonb_build_object('official_links', to_jsonb(array_remove(array[i.url, i.evidence->>'landing'], null)),
                                'stored_copies', case when i.evidence ? 'stored_copy' then jsonb_build_array(i.evidence->'stored_copy') else '[]'::jsonb end,
                                'quotes', coalesce(case when jsonb_typeof(i.evidence->'quotes') = 'array' then i.evidence->'quotes' end,
                                                   case when i.evidence ? 'landing_quote' then jsonb_build_array(i.evidence->'landing_quote') end, '[]'::jsonb),
                                'attempts', coalesce(case when jsonb_typeof(i.evidence->'tried') = 'array' then i.evidence->'tried' end, '[]'::jsonb)
                                            || jsonb_build_array(jsonb_build_object('method', i.evidence->>'method', 'at', i.evidence->>'fetched', 'outcome', i.outcome, 'shape', i.shape)),
                                'conflicts', case when i.boundary is not null then jsonb_build_array(i.boundary) else '[]'::jsonb end) ev,
             jsonb_build_object('summary', 'No entry-requirement source of this university could be read automatically',
                                'attempted', jsonb_build_array('free discovery on the official site (' || coalesce(i.evidence->>'method', 'read') || ')', 'stored copies checked'),
                                'why_stopped', i.shape, 'impact', 'none of its courses can show international entry requirements') issue,
             case when i.evidence ? 'next' then jsonb_build_object('note', i.evidence->>'next') end suggested
        from pipeline.aer_source_inventory i
       where i.outcome in ('blocked_site', 'unverified_link', 'verified_rendered_only') and coalesce((select rd.nread from rd where rd.provider_id = i.provider_id), 0) = 0
      union all
      select c.provider_id, c.provider_id::text, null, 'aer_source_missing',
             coalesce((c.evidence->>'discovery_attempts')::int, case when c.discovery_state <> 'not_discovered' then 1 else 0 end),
             'ledger|' || c.disposition || '|' || coalesce(c.discovery_state, ''),
             jsonb_build_object('official_links', '[]'::jsonb, 'stored_copies', '[]'::jsonb, 'quotes', '[]'::jsonb,
                                'attempts', jsonb_build_array(jsonb_build_object('discovery', c.discovery_state, 'since', c.disposition_since)), 'conflicts', '[]'::jsonb),
             jsonb_build_object('summary', 'No entry-requirement source has been found for this provider', 'attempted', jsonb_build_array('automatic discovery: ' || coalesce(c.discovery_state, 'none')),
                                'why_stopped', 'no official requirements page was identified', 'impact', c.courses_eligible || ' eligible course(s) without entry requirements'),
             null::jsonb
        from pipeline.aer_provider_coverage c
       where c.eligible and c.disposition = 'not_discovered' and c.sources = 0
         and not exists (select 1 from pipeline.aer_source_inventory i where i.provider_id = c.provider_id)
      union all
      select c.provider_id, c.provider_id::text, null, 'aer_read_held', greatest(1, coalesce(c.runs_held, 0) + coalesce(c.runs_failed, 0)),
             'held|' || c.disposition || '|' || coalesce(c.last_run_id::text, '') || '|' || c.sources_read || '|' || c.sources_failed,
             jsonb_build_object('official_links', coalesce((select jsonb_agg(s.url order by s.rank) from pipeline.entry_matrix_sources s where s.provider_id = c.provider_id), '[]'::jsonb),
                                'stored_copies', coalesce((select jsonb_agg(s.evidence_id) from pipeline.entry_matrix_sources s where s.provider_id = c.provider_id and s.evidence_id is not null), '[]'::jsonb),
                                'quotes', '[]'::jsonb, 'attempts', jsonb_build_array(jsonb_build_object('runs_held', c.runs_held, 'runs_failed', c.runs_failed, 'root_causes', to_jsonb(c.root_causes))),
                                'conflicts', coalesce(c.held_scopes, '[]'::jsonb)),
             jsonb_build_object('summary', 'The read of this university''s entry-requirement source is held', 'attempted', jsonb_build_array('matrix reads and re-reads', 'completeness gates'),
                                'why_stopped', c.disposition || ': ' || coalesce(array_to_string(c.root_causes, ', '), 'see the held runs'), 'impact', 'its matrix rows cannot be admitted'),
             null::jsonb
        from pipeline.aer_provider_coverage c where c.eligible and c.disposition in ('source_held', 'reader_failed')
      union all
      select rr.pid, rr.pid::text, null, 'aer_empty_read', rr.n::int, 'empty|' || rr.n || '|' || rr.courses::text,
             jsonb_build_object('official_links', coalesce((select jsonb_agg(s.url) from pipeline.entry_matrix_sources s where s.provider_id = rr.pid), '[]'::jsonb), 'stored_copies', '[]'::jsonb,
                                'quotes', '[]'::jsonb, 'attempts', jsonb_build_array(jsonb_build_object('course_reads', rr.n, 'since', rr.first_at, 'courses', rr.courses)), 'conflicts', '[]'::jsonb),
             jsonb_build_object('summary', rr.n || ' course read(s) of this university found no entry requirement', 'attempted', jsonb_build_array('scheduled course reads (aer-scheduled-read)'),
                                'why_stopped', 'the course pages read do not state international entry requirements', 'impact', 'its courses stay without entry requirements'),
             null::jsonb
        from reads rr
       where not exists (select 1 from catalogue.course_entry_requirements x join catalogue.courses c on c.id = x.course_id where c.provider_id = rr.pid and x.created_at >= rr.first_at)
      union all
      select w.provider_id, w.entity, li.entity_id, 'aer_course_identity', greatest(w.total_attempts, 1), 'shared|' || coalesce(w.failure_fingerprint, ''),
             jsonb_build_object('official_links', '[]'::jsonb, 'stored_copies', case when li.evidence_id is not null then jsonb_build_array(li.evidence_id) else '[]'::jsonb end,
                                'quotes', '[]'::jsonb, 'attempts', w.evidence, 'conflicts', jsonb_build_array(w.evidence->-1->'evidence')),
             jsonb_build_object('summary', 'The course read is held: its page is shared with another programme', 'attempted', jsonb_build_array('course read', 'completeness gate (E13)'),
                                'why_stopped', w.evidence->-1->>'message', 'impact', 'the course''s entry requirement cannot be reviewed'),
             null::jsonb
        from pipeline.work_items w join pipeline.layer4_review_items li on li.id::text = w.entity
       where w.lane = 'aer_technical' and w.stage in ('parked', 'quarantined') and w.evidence::text ~* '(shared_page|another programme|other_programme)'),
    ranked as (select c.*, coalesce(f.n, 1000000) fo, coalesce(k.courses_eligible, 0) ce,
                      md5(c.cls || '|' || c.sig) fp, row_number() over (partition by c.provider_id order by c.cls) pn
                 from cand c left join followed f on f.pid = c.provider_id left join pipeline.aer_provider_coverage k on k.provider_id = c.provider_id
                where not exists (select 1 from pipeline.layer4_interventions x where x.lane = (select l.lane from pipeline.layer4_intervention_classes l where l.code = c.cls)
                                    and x.entity = c.entity and x.missing_fact = c.cls
                                    and (x.status in ('ai_pending', 'awaiting_input', 'resuming') and x.fingerprint = md5(c.cls || '|' || c.sig)
                                         or x.closed_fingerprint = md5(c.cls || '|' || c.sig))))
    select rk.*, coalesce(p.display_name, p.short_name, p.canonical_name) pname from ranked rk join catalogue.providers p on p.id = rk.provider_id
     where rk.pn <= v_per order by rk.fo, rk.ce desc, rk.provider_id, rk.cls limit greatest(coalesce(p_limit, 0), 0)
  loop
    v_res := security.layer4_intervention_raise_v1(jsonb_build_object('class', r.cls, 'entity', r.entity, 'provider_id', r.provider_id, 'course_id', r.course_id,
               'subject', r.pname || ': ' || (select l.title from pipeline.layer4_intervention_classes l where l.code = r.cls), 'attempts', r.attempts, 'signature', r.sig,
               'issue', r.issue, 'evidence', r.ev, 'suggested', r.suggested,
               'resume_target', case when r.cls = 'aer_course_identity' then jsonb_build_object('operation', 'AER technical check of the held item',
                                                                                                    'work_item', jsonb_build_object('lane', 'aer_technical', 'entity', r.entity, 'kind', 'l4_item'))
                                     else jsonb_build_object('operation', 'entry-matrix-read and the scheduled course reader') end));
    if coalesce((v_res->>'raised')::boolean, false) then v_n := v_n + 1; elsif coalesce((v_res->>'repeat')::boolean, false) then v_rep := v_rep + 1; else v_skip := v_skip + 1; end if;
  end loop;
  return jsonb_build_object('raised_or_changed', v_n, 'repeats', v_rep, 'not_raised', v_skip);
end $$;


ALTER FUNCTION "security"."har_aer_generate_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_aer_item_generate_v1"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_res jsonb; v_n int := 0; v_rep int := 0; v_skip int := 0; v_per int := security.pipeline_num_v1('har.generate_per_provider_max', 2)::int;
        v_tries int := security.pipeline_num_v1('aer.schedule_held_max_tries', 2)::int;
begin
  for r in
    with h as (
      select i.id, i.entity_id, i.evidence_id, i.created_at, c.provider_id, coalesce(c.display_title, c.canonical_title) title, y.gate,
             security.aer_route_v1(i.field_code, y.gate) rt, pg.evidence_id page_ev, (pg.evidence_id is not null and pg.url = i.proposed_value->>'url') stored,
             (select count(*) from pipeline.aer_read_supersessions s where s.old_item_id = i.id) tries,
             exists (select 1 from pipeline.aer_read_supersessions s left join pipeline.field_enrich_items fe on fe.id = s.enrich_item_id
                      where s.old_item_id = i.id and s.state = 'refused' and (fe.evidence_id is null or fe.evidence_id = pg.evidence_id)) refused_same,
             (select s.outcome from pipeline.aer_read_supersessions s where s.old_item_id = i.id and s.state = 'refused' order by s.requested_at desc limit 1) refusal
        from pipeline.layer4_review_items i join pipeline.layer4_item_readiness y on y.item_id = i.id
        join catalogue.courses c on c.id = i.entity_id left join pipeline.coverage_course_pages pg on pg.course_id = i.entity_id
       where i.status = 'pending' and i.field_code = 'course_entry_first_read' and y.gate is not null),
    cand as (
      select h.*, case when h.rt->>'route' = 'identity' then 'aer_course_identity' else 'aer_read_rows_missing' end cls
        from h where h.rt->>'route' = 'identity'
          -- mandate 16:32 §4: rows from a person resume the same corrected read of the same copy (security.har_aer_item_resume_v1), which the
          -- reader refuses again; these holds wait for a changed copy, reader or setting (security.aer_recovery_rule_v1) instead
          or (false and h.rt->>'route' in ('missing_scale', 'quote_association', 'low_confidence') and (not coalesce(h.stored, false) or h.refused_same or h.tries >= v_tries)
              -- direction 12:16 §3-§4: a read refused for the row limit kept every printed requirement; rows from a person would resume the same
              -- refused read, so it waits for the row boundary (authority) instead
              and coalesce(h.refusal, '') not ilike '%row limit%' and coalesce(h.refusal, '') not ilike '%proof does not admit%')),
    ranked as (select c.*, row_number() over (partition by c.provider_id order by c.created_at, c.id) pn from cand c
                where not exists (select 1 from pipeline.layer4_interventions x where x.entity = c.id::text and x.missing_fact = c.cls
                                    and x.status in ('ai_pending', 'awaiting_input', 'resuming') and x.fingerprint = md5(c.cls || '|' || md5(coalesce(c.gate::text, '') || '|' || coalesce(c.page_ev::text, '')))))
    select * from ranked where pn <= v_per order by pn, created_at, id limit greatest(coalesce(p_limit, 0), 0)
  loop
    v_res := security.layer4_intervention_raise_v1(jsonb_build_object('class', r.cls, 'entity', r.id::text, 'provider_id', r.provider_id, 'course_id', r.entity_id,
      'field', 'entry_requirements', 'attempts', 99,
      'subject', r.title || ': ' || case r.cls when 'aer_course_identity' then 'confirm the course this page belongs to' else 'dropped requirements to enter' end,
      'signature', md5(coalesce(r.gate::text, '') || '|' || coalesce(r.page_ev::text, '')),
      'issue', jsonb_build_object('summary', 'The read is held: ' || coalesce(r.gate->'reasons'->>0, r.rt->>'route'),
                                  'attempted', jsonb_build_array('AI course read', 'completeness gate (E13)') || case when r.tries > 0 then jsonb_build_array(r.tries || ' corrected read(s) from the stored copy') else '[]'::jsonb end,
                                  'why_stopped', case when r.cls = 'aer_course_identity' then 'the stored page is also another programme''s page'
                                                      when not coalesce(r.stored, false) then 'no stored copy of the same page to read again'
                                                      when r.refused_same then 'the corrected read was refused on the same stored copy (the reader gives the same result on unchanged evidence)'
                                                      else 'out of corrected-read tries' end,
                                  'impact', 'the course''s accurate rows cannot be admitted while the read is incomplete'),
      'evidence', jsonb_build_object('stored_copies', case when r.evidence_id is not null then jsonb_build_array(r.evidence_id) else '[]'::jsonb end,
                                     'quotes', coalesce((select jsonb_agg(d->'quote') from jsonb_array_elements(coalesce(r.gate->'drops_uncovered', '[]'::jsonb)) d where nullif(d->>'quote', '') is not null), '[]'::jsonb),
                                     'conflicts', coalesce(r.gate->'reasons', '[]'::jsonb), 'attempts', jsonb_build_array(jsonb_build_object('route', r.rt->>'route', 'tries', r.tries))),
      'resume_target', jsonb_build_object('operation', case when r.cls = 'aer_course_identity' then 'AER technical check of the held item' else 'corrected read of the course by the existing reader (D-R2)' end,
                                          'work_item', jsonb_build_object('lane', 'aer_technical', 'entity', r.id::text, 'kind', 'l4_item')),
      'review_item', r.id::text));
    if coalesce((v_res->>'raised')::boolean, false) then v_n := v_n + 1;
      update pipeline.layer4_interventions set resume_target = resume_target || jsonb_build_object('review_item', r.id::text) where id = (v_res->>'id')::bigint;
    elsif coalesce((v_res->>'repeat')::boolean, false) then v_rep := v_rep + 1; else v_skip := v_skip + 1; end if;
  end loop;
  return jsonb_build_object('raised_or_changed', v_n, 'repeats', v_rep, 'not_raised', v_skip);
end $$;


ALTER FUNCTION "security"."har_aer_item_generate_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_aer_item_recheck_v1"("p_id" bigint) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- cleared when no held read of the item or case is still pending (decided, or replaced by another route)
  select jsonb_build_object('cleared', not exists (select 1 from pipeline.layer4_review_items r where r.status = 'pending'
           and (r.id::text = i.entity or r.id in (select a.review_item_id from pipeline.layer4_aer_recovery_actions a where a.intervention_id = i.id))))
    from pipeline.layer4_interventions i where i.id = p_id
$$;


ALTER FUNCTION "security"."har_aer_item_recheck_v1"("p_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_aer_item_resume_v1"("p_id" bigint, "p_action" "text", "p_norm" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_interventions; v_items uuid[]; v_it uuid; v_ok int := 0; v_no jsonb := '[]'::jsonb; v_res jsonb;
begin
  select * into i from pipeline.layer4_interventions where id = p_id;
  if p_norm->>'field' = 'source_url' and coalesce((p_norm->>'document')::boolean, false) then
    insert into pipeline.entry_matrix_sources as s(provider_id, url, title, rank, found_via, status)
    values (i.provider_id, p_norm->>'url', left('Layer 4 intervention ' || i.id || ': ' || i.subject, 300), 1, 'manual', 'found')
    on conflict (provider_id, url) do nothing;
  end if;
  v_items := case when i.entity like '%|case:%'
                  then array(select a.review_item_id from pipeline.layer4_aer_recovery_actions a join pipeline.layer4_review_items r on r.id = a.review_item_id
                              where a.intervention_id = i.id and r.status = 'pending' group by 1)
                  else array[i.entity::uuid] end;
  foreach v_it in array coalesce(v_items, '{}') loop
    begin
      if (select r.field_code from pipeline.layer4_review_items r where r.id = v_it) = 'course_entry_first_read' then
        v_res := security.course_entry_correction_v1(v_it, i.resolved_by, 'Human input needed ' || i.id || ': ' || coalesce(i.supplied->>'reason', 'input given'));
      else
        v_res := security.aer_reread_v1((select x.source_id from pipeline.entry_matrix_runs x where x.review_item_id = v_it order by x.created_at desc limit 1),
                                        'Human input needed ' || i.id, i.resolved_by);
      end if;
      v_ok := v_ok + 1;
    exception when others then v_no := v_no || jsonb_build_array(jsonb_build_object('item', v_it, 'refused', left(sqlerrm, 200)));
    end;
  end loop;
  return jsonb_build_object('scheduled', v_ok > 0 or (p_norm->>'field' = 'source_url' and coalesce((p_norm->>'document')::boolean, false)),
                            'operation', 'corrected read of ' || v_ok || ' held read(s) by the existing reader', 'refused', v_no);
end $$;


ALTER FUNCTION "security"."har_aer_item_resume_v1"("p_id" bigint, "p_action" "text", "p_norm" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_aer_item_validate_v1"("p_id" bigint, "p_action" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_interventions; v jsonb; j jsonb; e jsonb; v_drop jsonb; v_bad int := 0;
begin
  select * into i from pipeline.layer4_interventions where id = p_id;
  if p_action in ('attach_document', 'provide_url') then
    v := security.har_official_url_v1(p_payload->>'value', i.provider_id);
    if not coalesce((v->>'ok')::boolean, false) then return jsonb_build_object('valid', false, 'request', v->>'reason'); end if;
    return jsonb_build_object('valid', true, 'normalised', jsonb_build_object('field', 'source_url', 'url', v->>'url', 'document', (v->>'document')::boolean, 'stored_copy', v->>'stored_copy'));
  end if;
  begin j := (p_payload->>'value')::jsonb; exception when others then j := null; end;
  if j is null or jsonb_typeof(j) <> 'array' or jsonb_array_length(j) = 0 then
    return jsonb_build_object('valid', false, 'request', 'Enter the dropped requirements as rows: each with what it requires, its minimum if any, and the sentence from the official page.');
  end if;
  -- every dropped quotation of the held read(s), not only those shown on the card
  v_drop := coalesce((select jsonb_agg(q) from (
              select jsonb_array_elements(security.layer4_aer_recovery_state_v1(x.id)->'missing_quotes') q
                from pipeline.layer4_review_items x
               where x.id::text = i.entity or x.id in (select a.review_item_id from pipeline.layer4_aer_recovery_actions a where a.intervention_id = i.id)) z), '[]'::jsonb);
  for e in select x from jsonb_array_elements(j) x loop
    if not security.har_quote_ok_v1(e->>'quote') or coalesce(e->>'requirement', '') = '' then v_bad := v_bad + 1; continue; end if;
    if not exists (select 1 from jsonb_array_elements_text(v_drop) q
                    where position(lower(regexp_replace(e->>'quote', '\s+', ' ', 'g')) in lower(regexp_replace(q, '\s+', ' ', 'g'))) > 0
                       or position(lower(regexp_replace(q, '\s+', ' ', 'g')) in lower(regexp_replace(e->>'quote', '\s+', ' ', 'g'))) > 0) then v_bad := v_bad + 1; end if;
  end loop;
  if v_bad > 0 then
    return jsonb_build_object('valid', false, 'request', v_bad || ' row(s) have no requirement or a quotation that is not one the reader dropped from the official page. Copy the sentence exactly from the page.');
  end if;
  return jsonb_build_object('valid', true, 'normalised', jsonb_build_object('field', 'entry_rows', 'rows', j, 'quote', j->0->>'quote'));
end $$;


ALTER FUNCTION "security"."har_aer_item_validate_v1"("p_id" bigint, "p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_aer_item_verify_v1"("p_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_interventions; v_items uuid[]; v_pending int; v_refused text;
begin
  select * into i from pipeline.layer4_interventions where id = p_id;
  v_items := case when i.entity like '%|case:%' then array(select a.review_item_id from pipeline.layer4_aer_recovery_actions a where a.intervention_id = i.id group by 1)
                  else array[i.entity::uuid] end;
  select count(*) into v_pending from pipeline.layer4_review_items r where r.id = any (v_items) and r.status = 'pending';
  if v_pending = 0 and cardinality(v_items) > 0 then return jsonb_build_object('state', 'succeeded', 'outcome', 'read_replaced'); end if;
  -- a corrected read asked for since the input and refused, with no other read of the item still asked for
  select s.outcome into v_refused from pipeline.aer_read_supersessions s where s.old_item_id = any (v_items) and s.state = 'refused' and s.requested_at >= coalesce(i.input_at, i.created_at)
     and not exists (select 1 from pipeline.aer_read_supersessions t where t.old_item_id = s.old_item_id and t.state = 'requested')
   order by s.requested_at desc limit 1;
  if v_refused is not null then
    return jsonb_build_object('state', 'failed', 'request', 'The corrected read was not used (' || v_refused || '). Give the official document, or correct the rows against the page.');
  end if;
  return jsonb_build_object('state', 'pending', 'evidence', v_pending || ' held read(s) still waiting');
end $$;


ALTER FUNCTION "security"."har_aer_item_verify_v1"("p_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_aer_recheck_v1"("p_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_interventions; v boolean;
begin
  select * into i from pipeline.layer4_interventions where id = p_id;
  v := case
    when i.missing_fact in ('aer_source_missing', 'aer_document_unverified', 'aer_rendered_only') then
      exists (select 1 from pipeline.entry_matrix_sources s where s.provider_id = i.provider_id and s.status = 'read')
    when i.missing_fact = 'aer_empty_read' then
      exists (select 1 from catalogue.course_entry_requirements x join catalogue.courses c on c.id = x.course_id
               where c.provider_id = i.provider_id and x.status in ('proposed', 'active') and x.created_at >= i.created_at)
      -- F-AER.09 (11 Nov 2026): or the provider's own country table is live
      or exists (select 1 from catalogue.provider_entry_matrix m where m.provider_id = i.provider_id and m.status = 'active')
    when i.missing_fact = 'aer_read_held' then
      not exists (select 1 from pipeline.aer_provider_coverage a where a.provider_id = i.provider_id and a.disposition in ('source_held', 'reader_failed'))
    when i.missing_fact = 'aer_course_identity' then
      not exists (select 1 from pipeline.work_items w where w.id = i.work_item_id and w.stage in ('parked', 'quarantined', 'awaiting_review'))
           and not exists (select 1 from pipeline.layer4_review_items r where r.id::text = i.entity and r.status = 'pending')
    else false end;
  return jsonb_build_object('cleared', coalesce(v, false), 'condition', (select c.recheck_condition from pipeline.layer4_intervention_classes c where c.code = i.missing_fact));
end $$;


ALTER FUNCTION "security"."har_aer_recheck_v1"("p_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_aer_resume_v1"("p_id" bigint, "p_action" "text", "p_norm" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_interventions; v_sid uuid;
begin
  select * into i from pipeline.layer4_interventions where id = p_id;
  if p_norm ? 'url' then
    insert into pipeline.entry_matrix_sources as s(provider_id, url, title, rank, found_via, status)
    values (i.provider_id, p_norm->>'url', left('Layer 4 intervention ' || i.id || ': ' || i.subject, 300), 1, 'manual', 'found')
    on conflict (provider_id, url) do update set status = 'found', error = null, attempts = 0, updated_at = now()
     where s.status in ('failed', 'inactive', 'robots_disallowed')
    returning s.id into v_sid;
    if v_sid is null then select x.id into v_sid from pipeline.entry_matrix_sources x where x.provider_id = i.provider_id and x.url = p_norm->>'url'; end if;
    return jsonb_build_object('scheduled', true, 'operation', 'entry-matrix-read reads the attached source' || case when p_norm->>'stored_copy' is not null then ' from its stored copy (no new read bought)' else '' end,
                              'source_id', v_sid, 'stored_copy', p_norm->>'stored_copy');
  elsif p_norm ? 'course_id' then
    return jsonb_build_object('scheduled', true, 'operation', 'the held AER item returns to its technical check with the course confirmed', 'course_id', p_norm->>'course_id');
  elsif p_norm ? 'scope' then
    return jsonb_build_object('scheduled', true, 'operation', case p_norm->>'scope' when 'course_specific' then 'the scheduled course reader reads this university''s courses'
                                                                   else 'the university-wide rule is recorded with its quotation for the reader' end, 'scope', p_norm->>'scope');
  end if;
  return jsonb_build_object('scheduled', false, 'held', 'nothing to resume for this input');
end $$;


ALTER FUNCTION "security"."har_aer_resume_v1"("p_id" bigint, "p_action" "text", "p_norm" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_aer_validate_v1"("p_id" bigint, "p_action" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_interventions; v jsonb; v_val text := btrim(coalesce(p_payload->>'value', '')); j jsonb; s record; v_c record;
begin
  select * into i from pipeline.layer4_interventions where id = p_id;
  if p_action in ('provide_url', 'attach_document', 'select_source') then
    v := security.har_official_url_v1(v_val, i.provider_id);
    if not coalesce((v->>'ok')::boolean, false) then return jsonb_build_object('valid', false, 'request', v->>'reason'); end if;
    select x.status, x.attempts, x.error into s from pipeline.entry_matrix_sources x where x.provider_id = i.provider_id and x.url = v->>'url';
    if found and s.status in ('failed', 'robots_disallowed') and s.attempts >= security.pipeline_num_v1('entry.matrix_attempts', 3) and v->>'stored_copy' is null then
      return jsonb_build_object('valid', false, 'request', 'This address was read before and could not be read (' || coalesce(s.error, s.status) || '). Give another official address or the document itself, or return the item to technical recovery.');
    end if;
    return jsonb_build_object('valid', true, 'normalised', jsonb_build_object('field', 'source_url', 'url', v->>'url', 'document', (v->>'document')::boolean, 'stored_copy', v->>'stored_copy'));
  elsif p_action = 'confirm_scope' then
    begin j := v_val::jsonb; exception when others then j := jsonb_build_object('scope', v_val); end;
    if jsonb_typeof(j) <> 'object' then j := jsonb_build_object('scope', v_val); end if;
    if coalesce(j->>'scope', '') not in ('university_wide', 'course_specific') then
      return jsonb_build_object('valid', false, 'request', 'Say whether the requirement is university_wide or course_specific, with the official sentence that says so.');
    end if;
    if not security.har_quote_ok_v1(coalesce(j->>'quote', p_payload->>'quote')) then
      return jsonb_build_object('valid', false, 'request', 'Add the sentence from the official page that shows the scope (a quotation, so it can be checked).');
    end if;
    return jsonb_build_object('valid', true, 'normalised', jsonb_build_object('field', 'scope', 'scope', j->>'scope', 'quote', coalesce(j->>'quote', p_payload->>'quote')));
  elsif p_action = 'confirm_identity' then
    select c.id, c.course_code into v_c from catalogue.courses c
     where c.provider_id = i.provider_id and c.lifecycle_status = 'active' and (upper(c.course_code) = upper(v_val) or c.id::text = v_val) limit 1;
    if not found then return jsonb_build_object('valid', false, 'request', 'No active course of this university has the code or id "' || left(v_val, 60) || '". Give the course code shown on the course record.'); end if;
    return jsonb_build_object('valid', true, 'normalised', jsonb_build_object('field', 'course_id', 'course_id', v_c.id, 'course_code', v_c.course_code));
  end if;
  return jsonb_build_object('valid', false, 'request', 'This action is not used for entry requirements; choose one of the offered actions.');
end $$;


ALTER FUNCTION "security"."har_aer_validate_v1"("p_id" bigint, "p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_aer_verify_v1"("p_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_interventions; s record; m record; v_adm jsonb; v_rows int;
begin
  select * into i from pipeline.layer4_interventions where id = p_id;
  v_adm := security.har_aer_admitted_v1(i.provider_id, coalesce(i.input_at, i.created_at));
  if i.supplied ? 'url' then
    select x.id, x.status, x.error into s from pipeline.entry_matrix_sources x where x.provider_id = i.provider_id and x.url = i.supplied->>'url';
    if not found then return jsonb_build_object('state', 'failed', 'request', 'The source was not attached; give the address again.'); end if;
    if s.status in ('failed', 'robots_disallowed') then
      return jsonb_build_object('state', 'failed', 'request', 'The address could not be read (' || coalesce(s.error, s.status) || '). Give another official address or the document, or return the item to technical recovery.', 'evidence', s.error);
    end if;
    select r.state, r.error, r.review_item_id into m from pipeline.entry_matrix_runs r where r.source_id = s.id order by r.created_at desc limit 1;
    if found and m.state = 'done' then
      return v_adm || jsonb_build_object('state', 'succeeded', 'outcome', case when m.review_item_id is not null then 'read_in_layer4' else 'read_recorded' end, 'review_item_id', m.review_item_id);
    elsif found and m.state = 'failed' then
      return jsonb_build_object('state', 'failed', 'request', 'The source was read but the read is held (' || coalesce(m.error, 'failed') || '). Select another official source or return the item to technical recovery.', 'evidence', m.error);
    end if;
    return jsonb_build_object('state', 'pending', 'evidence', 'source ' || s.status);
  end if;
  select count(*) into v_rows from catalogue.course_entry_requirements x join catalogue.courses c on c.id = x.course_id
   where c.provider_id = i.provider_id and x.status in ('proposed', 'active') and x.created_at >= coalesce(i.input_at, i.created_at);
  if v_rows > 0 then return v_adm || jsonb_build_object('state', 'succeeded', 'outcome', 'course_rows_proposed', 'rows', v_rows); end if;
  if i.missing_fact = 'aer_course_identity' and exists (select 1 from pipeline.work_items w where w.id = i.work_item_id and w.stage = 'done') then
    return v_adm || jsonb_build_object('state', 'succeeded', 'outcome', 'held_item_recovered');
  end if;
  return jsonb_build_object('state', 'pending', 'evidence', 'no course entry row since the input');
end $$;


ALTER FUNCTION "security"."har_aer_verify_v1"("p_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_ai_proposals_v1"("p_id" bigint, "p_answer" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_interventions; p jsonb; v_ok jsonb := '[]'::jsonb; v_no jsonb := '[]'::jsonb; v_u jsonb;
begin
  select * into i from pipeline.layer4_interventions where id = p_id;
  for p in select x from jsonb_array_elements(case when jsonb_typeof(p_answer->'proposals') = 'array' then p_answer->'proposals' else '[]'::jsonb end) x loop
    if nullif(p->>'url', '') is not null then
      v_u := security.har_official_url_v1(p->>'url', i.provider_id);
      if not coalesce((v_u->>'ok')::boolean, false) then v_no := v_no || jsonb_build_array(p || jsonb_build_object('refused', v_u->>'reason')); continue; end if;
      if v_u->>'stored_copy' is null and position(p->>'url' in i.evidence::text) = 0
         and not exists (select 1 from pipeline.evidence_artifacts e where e.source_url = p->>'url') then
        v_no := v_no || jsonb_build_array(p || jsonb_build_object('refused', 'the address is not in any evidence the platform holds (an AI may not invent an address)')); continue;
      end if;
    end if;
    if p->>'kind' in ('value', 'scope', 'identity') and not security.har_quote_ok_v1(p->>'quote') then
      v_no := v_no || jsonb_build_array(p || jsonb_build_object('refused', 'no quotation from the official page')); continue;
    end if;
    v_ok := v_ok || jsonb_build_array(p);
  end loop;
  return jsonb_build_object('validated', v_ok, 'refused', v_no);
end $$;


ALTER FUNCTION "security"."har_ai_proposals_v1"("p_id" bigint, "p_answer" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_ai_tick_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_on boolean := security.pipeline_num_v1('har.ai_escalate_on', 0) >= 1 and security.pipeline_num_v1('ops.ai_diagnosis_on', 0) >= 1;
        v_model text := security.har_text_v1('har.ai_escalation_model', ''); v_refusal text; v_q int := 0; v_t int := 0; v_s int := 0; v_issue bigint; v_req bigint;
        v_p jsonb; v_best jsonb; v_lim int := security.pipeline_num_v1('batch.har_verify', 200)::int;
begin
  v_refusal := case when not v_on then 'the stronger-model step is off (har.ai_escalate_on or ops.ai_diagnosis_on is 0)'
                    when v_model = '' then 'no escalation model is pinned (har.ai_escalation_model)'
                    else security.ai_use_refusal_v1('ops_diagnose') end;
  for r in select i.* from pipeline.layer4_interventions i where i.status = 'ai_pending' order by i.updated_at limit v_lim loop
    if r.ai_analysis ? 'request_id' then
      select to_jsonb(q) into v_p from pipeline.ops_ai_diagnosis_requests q where q.id = (r.ai_analysis->>'request_id')::bigint;
      if v_p->>'state' = 'answered' then
        v_p := v_p || jsonb_build_object('checked', security.har_ai_proposals_v1(r.id, v_p->'answer'));
        select x into v_best from jsonb_array_elements(v_p->'checked'->'validated') x
         where coalesce((x->>'confidence')::numeric, 0) >= security.pipeline_num_v1('har.ai_min_confidence', 0.7) order by (x->>'confidence')::numeric desc limit 1;
        update pipeline.layer4_interventions set status = 'awaiting_input', updated_at = now(),
               ai_analysis = r.ai_analysis || jsonb_build_object('model', v_p->>'model', 'answered_at', v_p->>'answered_at', 'analysis', v_p->'answer'->>'analysis',
                             'confidence', v_p->'answer'->'confidence', 'uncertainty', v_p->'answer'->'uncertainty', 'validated', v_p->'checked'->'validated', 'refused', v_p->'checked'->'refused'),
               recommended = recommended || case when v_best is not null then jsonb_build_object('suggested', v_best || jsonb_build_object('from', 'AI, validated against official evidence; not a decision')) else '{}'::jsonb end
         where id = r.id;
        perform security.har_event_v1(r.id, 'ai_answered', '{}'::jsonb, v_p->'checked', 'ai_pending', 'awaiting_input');
        v_t := v_t + 1;
      elsif v_p->>'state' = 'refused' or r.updated_at < now() - make_interval(hours => security.pipeline_num_v1('har.ai_wait_hours', 6)::int) then
        update pipeline.layer4_interventions set status = 'awaiting_input', ai_analysis = r.ai_analysis || jsonb_build_object('skipped', 'the AI request was refused or late'), updated_at = now() where id = r.id;
        perform security.har_event_v1(r.id, 'ai_skipped', '{}'::jsonb, jsonb_build_object('state', v_p->>'state'), 'ai_pending', 'awaiting_input');
        v_s := v_s + 1;
      end if;
    elsif v_refusal is not null or v_q >= greatest(0, security.pipeline_num_v1('har.ai_requests_per_day', 10)
                                        - (select count(*) from pipeline.layer4_intervention_events e where e.action = 'ai_requested' and e.at >= date_trunc('day', now()))) then
      update pipeline.layer4_interventions set status = 'awaiting_input', ai_analysis = coalesce(r.ai_analysis, '{}'::jsonb) || jsonb_build_object('skipped', coalesce(v_refusal, 'the day''s escalation requests are used')),
             updated_at = now() where id = r.id;
      perform security.har_event_v1(r.id, 'ai_skipped', '{}'::jsonb, jsonb_build_object('reason', coalesce(v_refusal, 'daily requests used')), 'ai_pending', 'awaiting_input');
      v_s := v_s + 1;
    else
      v_issue := coalesce(r.integration_issue_id, security.har_class_issue_v1(r.lane, r.missing_fact, 'stronger-model escalation'));
      insert into pipeline.ops_ai_diagnosis_requests(issue_id, context, model, note)
      values (v_issue, jsonb_build_object('contract', 'har_intervention_v1', 'intervention_id', r.id, 'model', v_model, 'class', r.missing_fact, 'subject', r.subject,
                'question', r.required_input->>'ask', 'issue', r.issue, 'evidence', r.evidence,
                'instructions', 'Use only the evidence given. Never invent an address, score, eligibility, fee or decision. Propose an address only if it appears in the evidence; give a quotation for every value.',
                'answer_schema', jsonb_build_object('analysis', 'text', 'confidence', '0..1', 'uncertainty', 'text',
                                                    'proposals', '[{kind: url|value|scope|identity, url, value, quote, confidence}]')),
              v_model, 'human-assisted recovery escalation') returning id into v_req;
      update pipeline.layer4_interventions set integration_issue_id = v_issue, ai_analysis = coalesce(r.ai_analysis, '{}'::jsonb) || jsonb_build_object('request_id', v_req, 'model', v_model),
             updated_at = now() where id = r.id;
      perform security.har_event_v1(r.id, 'ai_requested', '{}'::jsonb, jsonb_build_object('request_id', v_req, 'model', v_model), 'ai_pending', 'ai_pending');
      v_q := v_q + 1;
    end if;
  end loop;
  return jsonb_build_object('requested', v_q, 'taken', v_t, 'skipped', v_s, 'held', v_refusal);
end $$;


ALTER FUNCTION "security"."har_ai_tick_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_cap_v1"("p" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case when jsonb_typeof(p) = 'array' then coalesce((select jsonb_agg(e order by n) from jsonb_array_elements(p) with ordinality z(e, n)
                                                             where n <= security.pipeline_num_v1('har.evidence_items_max', 5)), '[]'::jsonb)
              else coalesce(p, '[]'::jsonb) end
$$;


ALTER FUNCTION "security"."har_cap_v1"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_class_issue_v1"("p_lane" "text", "p_class" "text", "p_reason" "text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c pipeline.layer4_intervention_classes; v_n int; v_old timestamptz; v_provs uuid[]; v_res jsonb;
begin
  select * into c from pipeline.layer4_intervention_classes where code = p_class;
  select count(*), min(created_at), array_agg(distinct provider_id) filter (where provider_id is not null) into v_n, v_old, v_provs
    from pipeline.layer4_interventions where lane = p_lane and missing_fact = p_class and status in ('ai_pending', 'awaiting_input', 'resuming');
  v_res := security.integration_issue_upsert_v1(jsonb_build_object(
    'fingerprint', 'har:' || p_lane || ':' || p_class, 'severity', 'P2', 'layer', 'Platform', 'subsystem', 'human-assisted recovery: ' || p_lane,
    'title', 'Human input needed: ' || c.title || ' (' || v_n || ' open)',
    'failure', v_n || ' intervention(s) of class ' || p_class || ' in lane ' || p_lane || ' wait for human input or verification; oldest since ' || coalesce(v_old::text, '-') || '. ' || coalesce(p_reason, ''),
    'expected', 'A reviewer supplies the missing input in Layer 4 (Human input needed) and the platform resumes the work by itself.',
    'source', 'layer4-interventions', 'validation_layer', 'V3', 'root_cause_class', 'human_decision', 'workstream', 'A10',
    'provider_ids', to_jsonb(coalesce(v_provs[1:50], '{}'::uuid[])),
    'evidence', jsonb_build_object('lane', p_lane, 'class', p_class, 'open', v_n, 'oldest', v_old, 'reason', p_reason)), 'layer4-interventions');
  return (v_res->>'id')::bigint;
end $$;


ALTER FUNCTION "security"."har_class_issue_v1"("p_lane" "text", "p_class" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_event_v1"("p_id" bigint, "p_action" "text", "p_payload" "jsonb", "p_result" "jsonb", "p_before" "text", "p_after" "text") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  insert into pipeline.layer4_intervention_events(intervention_id, actor, actor_label, role_rank, action, payload, result, status_before, status_after)
  values (p_id, auth.uid(), coalesce((select u.email from auth.users u where u.id = auth.uid()), case when auth.uid() is null then 'system: job layer4-interventions' else auth.uid()::text end),
          case when auth.uid() is not null then security.current_role_rank() end, p_action, coalesce(p_payload, '{}'::jsonb), coalesce(p_result, '{}'::jsonb), p_before, p_after)
$$;


