CREATE OR REPLACE FUNCTION "security"."har_official_url_v1"("p_url" "text", "p_provider" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_url text := btrim(coalesce(p_url, ''));
begin
  if v_url !~* '^https://[^\s/]+\.[^\s]+$' then return jsonb_build_object('ok', false, 'reason', 'give the full official address, starting https://'); end if;
  if coalesce(security.third_party_host_v1(v_url), false) then
    return jsonb_build_object('ok', false, 'reason', 'this address is on a search, social or directory site; give the address on the provider''s own website');
  end if;
  if p_provider is null or not coalesce(security.url_on_provider_sites(v_url, p_provider), false) then
    return jsonb_build_object('ok', false, 'reason', 'this address is not on the provider''s own website; give the page on its official site');
  end if;
  return jsonb_build_object('ok', true, 'url', v_url, 'document', v_url ~* '\.(pdf|docx?)($|[?#])', 'stored_copy', security.layer4_stored_copy_v1(v_url));
end $_$;


ALTER FUNCTION "security"."har_official_url_v1"("p_url" "text", "p_provider" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_quote_ok_v1"("p_quote" "text") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select length(btrim(coalesce(p_quote, ''))) >= security.pipeline_num_v1('har.quote_min_chars', 20)
$$;


ALTER FUNCTION "security"."har_quote_ok_v1"("p_quote" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_sch_generate_v1"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_res jsonb; v_n int := 0; v_rep int := 0; v_skip int := 0; v_per int := security.pipeline_num_v1('har.generate_per_provider_max', 2)::int;
begin
  for r in
    with cand as (
      select x.*, x.provider_id::text || '|' || x.item_key entity,
             case x.state when 'source_not_discovered' then 'sch_source_missing' when 'international_unresolved' then 'sch_international_unresolved' else 'sch_ownership_conflict' end cls,
             case when x.state = 'source_not_discovered' and x.item_key = 'provider' then case when coalesce(x.evidence->>'discovery', 'never queued') <> 'never queued' then 1 else 0 end
                  else 1 end attempts,
             x.state || '|' || coalesce(x.reason, '') || '|' || x.evidence::text sig
        from pipeline.scholarship_coverage_items x
       where x.present and x.state in ('source_not_discovered', 'international_unresolved', 'ownership_conflict')
         and coalesce(security.scholarship_admission_provider_ok_v1(x.provider_id), false)
         -- F-SCH.01 (12 Nov 2026): while the eligibility reader is on, an eligibility case goes to a person only once the reader has read it and found no
         -- sentence (or its read failed); a proven sentence is the admission rule's to act on, not a person's
         and (x.state <> 'international_unresolved' or security.pipeline_num_v1('sch_elig.on', 0) < 1
              or exists (select 1 from pipeline.scholarship_eligibility_reads e where x.item_key = 'cand:' || e.candidate_id::text
                          and (e.state = 'failed' or (e.state = 'done' and e.outcome = 'silent'))))),
    ranked as (select c.*, row_number() over (partition by c.provider_id order by c.first_seen, c.item_key) pn from cand c
                where not exists (select 1 from pipeline.layer4_interventions i where i.lane = 'sch_coverage' and i.entity = c.entity and i.missing_fact = c.cls
                                    and (i.status in ('ai_pending', 'awaiting_input', 'resuming') and i.fingerprint = md5(c.cls || '|' || c.sig) or i.closed_fingerprint = md5(c.cls || '|' || c.sig))))
    select rk.*, coalesce(p.display_name, p.short_name, p.canonical_name) pname from ranked rk join catalogue.providers p on p.id = rk.provider_id
     where rk.pn <= v_per order by rk.first_seen, rk.provider_id, rk.item_key limit greatest(coalesce(p_limit, 0), 0)
  loop
    v_res := security.layer4_intervention_raise_v1(jsonb_build_object('class', r.cls, 'entity', r.entity, 'provider_id', r.provider_id,
               'subject', r.pname || ': ' || coalesce(r.evidence->>'name', r.evidence->>'title', r.evidence->>'item', (select l.title from pipeline.layer4_intervention_classes l where l.code = r.cls)),
               'attempts', r.attempts, 'signature', r.sig,
               'issue', jsonb_build_object('summary', (select l.title from pipeline.layer4_intervention_classes l where l.code = r.cls), 'attempted', jsonb_build_array(coalesce(r.recovery, 'scholarship coverage classification'), r.reason),
                                           'why_stopped', r.reason, 'impact', 'the provider''s scholarships cannot be admitted or published from this case'),
               'evidence', jsonb_build_object('official_links', to_jsonb(array_remove(array[r.evidence->>'url', r.evidence->>'page', r.evidence->>'listing'], null)),
                                              'stored_copies', case when r.evidence->>'evidence_id' is not null then jsonb_build_array(r.evidence->>'evidence_id') else '[]'::jsonb end,
                                              'quotes', '[]'::jsonb, 'attempts', jsonb_build_array(jsonb_build_object('reason', r.reason, 'ai', r.evidence->'ai', 'discovery', r.evidence->'discovery')),
                                              'conflicts', case when r.state = 'ownership_conflict' then jsonb_build_array(jsonb_build_object('host', r.evidence->>'host', 'listed_under', r.evidence->>'listed_under')) else '[]'::jsonb end),
               'suggested', case when r.state = 'source_not_discovered' and r.evidence->>'page' is not null and coalesce(security.url_on_provider_sites(r.evidence->>'page', r.provider_id), false)
                                 then jsonb_build_object('url', r.evidence->>'page', 'from', 'the scholarship register (not yet verified)') end,
               'resume_target', jsonb_build_object('operation', 'scholarship readers', 'work_item', jsonb_build_object('lane', 'sch_coverage', 'entity', r.provider_id::text, 'kind', 'state:' || r.state))));
    if coalesce((v_res->>'raised')::boolean, false) then v_n := v_n + 1; elsif coalesce((v_res->>'repeat')::boolean, false) then v_rep := v_rep + 1; else v_skip := v_skip + 1; end if;
  end loop;
  return jsonb_build_object('raised_or_changed', v_n, 'repeats', v_rep, 'not_raised', v_skip);
end $$;


ALTER FUNCTION "security"."har_sch_generate_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_sch_recheck_v1"("p_id" bigint) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('cleared', not exists (select 1 from pipeline.scholarship_coverage_items x
            where x.provider_id = i.provider_id and x.item_key = split_part(i.entity, '|', 2) and x.present
              and x.state = case i.missing_fact when 'sch_source_missing' then 'source_not_discovered' when 'sch_international_unresolved' then 'international_unresolved'
                                                else 'ownership_conflict' end))
    from pipeline.layer4_interventions i where i.id = p_id
$$;


ALTER FUNCTION "security"."har_sch_recheck_v1"("p_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_sch_resume_v1"("p_id" bigint, "p_action" "text", "p_norm" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare i pipeline.layer4_interventions; v_id bigint; v_cand bigint;
begin
  select * into i from pipeline.layer4_interventions where id = p_id;
  if p_norm->>'field' = 'source_url' then
    insert into pipeline.scholarship_listing_pages as l(provider_id, url, url_norm, source, active, status, next_read_at, added_by, added_at)
    values (i.provider_id, p_norm->>'url', security.scholarship_url_norm(p_norm->>'url'), 'manual', true, 'waiting', now(), auth.uid(), now())
    on conflict (provider_id, url_norm) do update set source = 'manual', active = true, status = 'waiting', next_read_at = now()
     where l.source = 'suggested' or not l.active or l.status = 'failed'
    returning l.id into v_id;
    if v_id is null then select x.id into v_id from pipeline.scholarship_listing_pages x where x.provider_id = i.provider_id and x.url_norm = security.scholarship_url_norm(p_norm->>'url'); end if;
    return jsonb_build_object('scheduled', true, 'operation', 'the scholarship listing reader reads the page', 'listing_id', v_id);
  elsif p_norm->>'field' = 'audience' then
    v_cand := case when i.entity ~ '\|cand:[0-9]+$' then substring(i.entity from '\|cand:([0-9]+)$')::bigint end;
    if v_cand is null then return jsonb_build_object('scheduled', false, 'held', 'no candidate page to read again'); end if;
    update pipeline.scholarship_page_candidates set requested_at = now() where id = v_cand;
    return jsonb_build_object('scheduled', found, 'operation', 'the candidate page is read again (Read again); your quotation is kept as evidence', 'candidate_id', v_cand);
  elsif p_norm->>'field' = 'search_again' then
    update pipeline.scholarship_discovery_providers set next_discover_at = now() where provider_id = i.provider_id;
    return jsonb_build_object('scheduled', found, 'operation', 'scholarship discovery looks at the provider again within its caps');
  elsif p_norm ? 'owner_provider_id' then
    return jsonb_build_object('scheduled', true, 'operation', 'ownership decision recorded for the scholarship coverage lane (pipeline.layer4_intervention_values)');
  end if;
  return jsonb_build_object('scheduled', false, 'held', 'nothing to resume for this input');
end $_$;


ALTER FUNCTION "security"."har_sch_resume_v1"("p_id" bigint, "p_action" "text", "p_norm" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_sch_validate_v1"("p_id" bigint, "p_action" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_interventions; v jsonb; v_val text := btrim(coalesce(p_payload->>'value', '')); j jsonb; v_pid uuid[];
begin
  select * into i from pipeline.layer4_interventions where id = p_id;
  if p_action in ('provide_url', 'select_source') then
    v := security.har_official_url_v1(v_val, i.provider_id);
    if not coalesce((v->>'ok')::boolean, false) then return jsonb_build_object('valid', false, 'request', v->>'reason'); end if;
    return jsonb_build_object('valid', true, 'normalised', jsonb_build_object('field', 'source_url', 'url', v->>'url', 'stored_copy', v->>'stored_copy'));
  elsif p_action = 'search_again' then
    return jsonb_build_object('valid', true, 'normalised', jsonb_build_object('field', 'search_again'));
  elsif p_action in ('confirm_scope', 'correct_value') then
    begin j := v_val::jsonb; exception when others then j := jsonb_build_object('audience', v_val); end;
    if jsonb_typeof(j) <> 'object' then j := jsonb_build_object('audience', v_val); end if;
    if coalesce(j->>'audience', '') not in ('international', 'domestic_only') then
      return jsonb_build_object('valid', false, 'request', 'Say whether international students may apply (international) or not (domestic_only), with the sentence from the official page.');
    end if;
    if not security.har_quote_ok_v1(coalesce(j->>'quote', p_payload->>'quote')) then
      return jsonb_build_object('valid', false, 'request', 'Add the sentence from the official page that says who may apply (a quotation, so it can be checked).');
    end if;
    return jsonb_build_object('valid', true, 'normalised', jsonb_build_object('field', 'audience', 'audience', j->>'audience', 'quote', coalesce(j->>'quote', p_payload->>'quote'),
                                                                              'url', i.evidence->'official_links'->>0));
  elsif p_action = 'confirm_identity' then
    v_pid := array(select p.id from catalogue.providers p where p.lifecycle_status = 'active'
                    and (p.id::text = v_val or lower(coalesce(p.display_name, p.canonical_name)) = lower(v_val)) limit 2);
    if coalesce(array_length(v_pid, 1), 0) <> 1 then
      return jsonb_build_object('valid', false, 'request', 'Give the owning provider''s id or exact name (' || coalesce(array_length(v_pid, 1), 0) || ' active provider(s) match).');
    end if;
    return jsonb_build_object('valid', true, 'normalised', jsonb_build_object('field', 'owner_provider_id', 'owner_provider_id', v_pid[1]));
  end if;
  return jsonb_build_object('valid', false, 'request', 'This action is not used for scholarships; choose one of the offered actions.');
end $$;


ALTER FUNCTION "security"."har_sch_validate_v1"("p_id" bigint, "p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_sch_value_generate_v1"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_res jsonb; v_n int := 0; v_rep int := 0; v_skip int := 0; v_err int := 0; v_last text;
        v_per int := security.pipeline_num_v1('har.generate_per_provider_max', 2)::int;
begin
  for r in
    with cand as (
      select x.provider_id, x.item_key, x.reason, x.first_seen, (x.evidence->>'scholarship_id')::uuid sid, x.provider_id::text || '|' || x.item_key entity
        from pipeline.scholarship_coverage_items x
       where x.present and x.state = 'admitted_not_published' and x.evidence->'missing' = '["no stated award value"]'::jsonb
         and coalesce(security.scholarship_admission_provider_ok_v1(x.provider_id), false)),
    c2 as (
      select c.*, s.name, s.source_url, s.award_value_text, sp.read_status, sp.read_at, sp.evidence_id,
             c.sid::text || '|' || coalesce(s.award_value_text, '') sig
        from cand c join scholarship.scholarships s on s.id = c.sid
        left join pipeline.scholarship_pages sp on sp.scholarship_id = c.sid
       where s.lifecycle_status = 'active' and s.publication_status <> 'published'
         -- the automated attempt first: a page the reader has not read yet waits for the reader and takes no slot
         and sp.read_status = 'read'
         and not exists (select 1 from pipeline.manual_locks k where k.entity = 'scholarship' and k.entity_id = s.id and k.field in ('award_amount', 'award_percentage', 'award_value_type'))
         and not exists (select 1 from pipeline.scholarship_ai_reviews rv where rv.scholarship_id = s.id and rv.status = 'pending')
         and not exists (select 1 from pipeline.layer4_review_items l where l.entity_type = 'scholarship' and l.entity_id = s.id and l.status = 'pending')),
    ranked as (
      select c2.*, row_number() over (partition by c2.provider_id order by c2.first_seen, c2.item_key) pn from c2
       where not exists (select 1 from pipeline.layer4_interventions i where i.lane = 'sch_value' and i.entity = c2.entity and i.missing_fact = 'sch_value_missing'
                           and (i.status in ('ai_pending', 'awaiting_input', 'resuming') or i.closed_fingerprint = md5('sch_value_missing|' || c2.sig))))
    select rk.*, coalesce(p.display_name, p.short_name, p.canonical_name) pname from ranked rk join catalogue.providers p on p.id = rk.provider_id
     where rk.pn <= v_per order by rk.first_seen, rk.provider_id, rk.item_key limit greatest(coalesce(p_limit, 0), 0)
  loop
    begin
      v_res := security.layer4_intervention_raise_v1(jsonb_build_object('class', 'sch_value_missing', 'entity', r.entity, 'provider_id', r.provider_id, 'field', 'award_value',
                 'subject', r.pname || ': ' || coalesce(r.name, 'scholarship'),
                 'attempts', case when r.read_status = 'read' then 1 else 0 end, 'signature', r.sig,
                 'issue', jsonb_build_object('summary', 'Admitted, but not published: the award value is stated only in words',
                                             'attempted', jsonb_build_array('scholarship page read (' || coalesce(r.read_status, 'not read') || coalesce(', ' || to_char(r.read_at, 'DD Mon YYYY'), '') || ')',
                                                                            'publishing checks: no stated award value'),
                                             'why_stopped', 'the page gives no amount or percentage the publishing check can use',
                                             'impact', 'the scholarship is in the catalogue but never reaches the website or Zoho'),
                 'evidence', jsonb_build_object('official_links', to_jsonb(array_remove(array[r.source_url], null)),
                                                'stored_copies', case when r.evidence_id is not null then jsonb_build_array(r.evidence_id) else '[]'::jsonb end,
                                                'quotes', case when nullif(btrim(coalesce(r.award_value_text, '')), '') is not null then jsonb_build_array(r.award_value_text) else '[]'::jsonb end,
                                                'attempts', jsonb_build_array(jsonb_build_object('reason', r.reason)), 'conflicts', '[]'::jsonb),
                 'suggested', case when nullif(btrim(coalesce(r.award_value_text, '')), '') is not null
                                   then jsonb_build_object('value_text', r.award_value_text, 'from', 'the value as the page words it (held on the record; not a number)') end,
                 'resume_target', jsonb_build_object('operation', 'apply the value as the reviewer''s edit; scholarship-auto-publish publishes',
                                                     'work_item', jsonb_build_object('lane', 'sch_value', 'entity', r.entity, 'kind', 'value'))));
      if coalesce((v_res->>'raised')::boolean, false) then v_n := v_n + 1; elsif coalesce((v_res->>'repeat')::boolean, false) then v_rep := v_rep + 1; else v_skip := v_skip + 1; end if;
    exception when others then
      v_err := v_err + 1; v_last := left(r.entity || ': ' || sqlerrm, 300);
    end;
  end loop;
  return jsonb_build_object('raised_or_changed', v_n, 'repeats', v_rep, 'not_raised', v_skip, 'errors', v_err, 'error_last', v_last);
end $$;


ALTER FUNCTION "security"."har_sch_value_generate_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_sch_value_recheck_v1"("p_id" bigint) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 IQ-00264: cleared without a person when the case is no longer an admitted scholarship held only by its award value
  select jsonb_build_object('cleared', not exists (select 1 from pipeline.scholarship_coverage_items x
            where x.provider_id = i.provider_id and x.item_key = split_part(i.entity, '|', 2) and x.present
              and x.state = 'admitted_not_published' and x.evidence->'missing' = '["no stated award value"]'::jsonb))
    from pipeline.layer4_interventions i where i.id = p_id
$$;


ALTER FUNCTION "security"."har_sch_value_recheck_v1"("p_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_sch_value_resume_v1"("p_id" bigint, "p_action" "text", "p_norm" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_interventions; v_sid uuid := nullif(p_norm->>'scholarship_id', '')::uuid; v jsonb;
begin
  select * into i from pipeline.layer4_interventions where id = p_id;
  if security.pipeline_num_v1('sch_cov.value_apply_on', 1) < 1 then
    return jsonb_build_object('scheduled', false, 'held', 'sch_cov.value_apply_on is 0: the value is kept as a proposal (pipeline.layer4_intervention_values)');
  end if;
  begin
    v := public.admin_scholarship_edit(v_sid, 'set_core', jsonb_build_object('field', case p_norm->>'kind' when 'percentage' then 'award_percentage' else 'award_amount' end,
                                                                             'value', p_norm->>'value',
                                                                             'reason', left('Layer 4 › Human input needed (intervention ' || p_id || '): ' || coalesce(p_norm->>'quote', ''), 500)));
  exception when others then
    return jsonb_build_object('scheduled', false, 'held', left('the scholarship edit refused the value: ' || sqlerrm, 300));
  end;
  return jsonb_build_object('scheduled', true, 'operation', 'the value is your locked edit of the scholarship; the hourly publishing run publishes it when every check passes',
                            'scholarship_id', v_sid, 'value_label', v->>'value_label');
end $$;


ALTER FUNCTION "security"."har_sch_value_resume_v1"("p_id" bigint, "p_action" "text", "p_norm" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_sch_value_validate_v1"("p_id" bigint, "p_action" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare i pipeline.layer4_interventions; v_sid uuid; j jsonb; v_val text := btrim(coalesce(p_payload->>'value', '')); v_kind text; v_num numeric; v_quote text;
begin
  select * into i from pipeline.layer4_interventions where id = p_id;
  if p_action not in ('enter_value', 'correct_value') then
    return jsonb_build_object('valid', false, 'request', 'This action is not used for award values; enter the value or confirm that the page states none.');
  end if;
  v_sid := substring(i.entity from '\|sch:([0-9a-f-]{36})$')::uuid;
  if not exists (select 1 from scholarship.scholarships s where s.id = v_sid and s.lifecycle_status = 'active' and s.publication_status <> 'published') then
    return jsonb_build_object('valid', false, 'request', 'The scholarship is no longer waiting for publication; nothing to enter.');
  end if;
  if exists (select 1 from pipeline.manual_locks k where k.entity = 'scholarship' and k.entity_id = v_sid and k.field in ('award_amount', 'award_percentage', 'award_value_type')) then
    return jsonb_build_object('valid', false, 'request', 'A person has already set this value on the scholarship record; change it there.');
  end if;
  begin j := v_val::jsonb; exception when others then j := null; end;
  if j is null or jsonb_typeof(j) <> 'object' then
    j := case when v_val ~ '^[0-9]+(\.[0-9]+)?\s*%$' then jsonb_build_object('percentage', regexp_replace(v_val, '\s*%$', ''))
              when replace(replace(v_val, ',', ''), '$', '') ~ '^[0-9]+(\.[0-9]+)?$' then jsonb_build_object('amount', replace(replace(v_val, ',', ''), '$', ''))
              else '{}'::jsonb end;
  end if;
  v_kind := case when j ? 'percentage' then 'percentage' when j ? 'amount' then 'fixed_amount' end;
  if v_kind is null or coalesce(j->>'percentage', j->>'amount') !~ '^[0-9]+(\.[0-9]+)?$' then
    return jsonb_build_object('valid', false, 'request', 'Enter the value as an amount (for example 5000) or a percentage (for example 25%), with the sentence from the official page.');
  end if;
  v_num := coalesce(j->>'percentage', j->>'amount')::numeric;
  if v_num <= 0 or (v_kind = 'percentage' and v_num > 100) then
    return jsonb_build_object('valid', false, 'request', 'An amount must be above 0; a percentage must be above 0 and at most 100.');
  end if;
  v_quote := coalesce(j->>'quote', p_payload->>'quote');
  if not security.har_quote_ok_v1(v_quote) then
    return jsonb_build_object('valid', false, 'request', 'Add the sentence from the official page that states the value (a quotation, so it can be checked).');
  end if;
  return jsonb_build_object('valid', true, 'normalised', jsonb_build_object('field', 'award_value', 'kind', v_kind, 'value', v_num, 'quote', v_quote,
                                                                              'scholarship_id', v_sid, 'url', i.evidence->'official_links'->>0));
end $_$;


ALTER FUNCTION "security"."har_sch_value_validate_v1"("p_id" bigint, "p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_sch_value_verify_v1"("p_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare i pipeline.layer4_interventions; v_sid uuid; s record; v_missing text[];
begin
  select * into i from pipeline.layer4_interventions where id = p_id;
  v_sid := substring(i.entity from '\|sch:([0-9a-f-]{36})$')::uuid;
  select x.publication_status, x.lifecycle_status into s from scholarship.scholarships x where x.id = v_sid;
  if not found or s.lifecycle_status <> 'active' then return jsonb_build_object('state', 'failed', 'request', 'The scholarship is no longer active.'); end if;
  if s.publication_status = 'published' then
    if api.website_v2_scholarship_item(v_sid) is not null then
      return jsonb_build_object('state', 'succeeded', 'outcome', 'published_consumer_verified', 'admitted', true, 'published', true);
    end if;
    return jsonb_build_object('state', 'pending', 'evidence', 'published; the website read-back does not return it yet');
  end if;
  select x.missing into v_missing from security.scholarship_publishability_for_v1(array[v_sid]) x;
  if coalesce(cardinality(v_missing), 0) > 0 and not ('no stated award value' = any (v_missing)) then
    return jsonb_build_object('state', 'failed', 'request', 'The value is applied, but publishing is still held by: ' || array_to_string(v_missing, '; ') || '.');
  end if;
  return jsonb_build_object('state', 'pending', 'evidence', coalesce('still failing: ' || array_to_string(v_missing, '; '), 'waiting for the hourly publishing run'));
end $_$;


ALTER FUNCTION "security"."har_sch_value_verify_v1"("p_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."har_sch_verify_v1"("p_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_interventions; v_pid uuid; v_key text; l record; v_adm int;
begin
  select * into i from pipeline.layer4_interventions where id = p_id;
  v_pid := i.provider_id; v_key := split_part(i.entity, '|', 2);
  select count(*) into v_adm from pipeline.scholarship_page_candidates c where c.provider_id = v_pid and c.admitted_at >= coalesce(i.input_at, i.created_at);
  if i.supplied ? 'owner_provider_id' then return jsonb_build_object('state', 'succeeded', 'outcome', 'decision_recorded'); end if;
  if i.supplied->>'field' = 'source_url' then
    select x.status, x.read_at, x.error into l from pipeline.scholarship_listing_pages x where x.provider_id = v_pid and x.url_norm = security.scholarship_url_norm(i.supplied->>'url');
    if found and l.status = 'failed' then
      return jsonb_build_object('state', 'failed', 'request', 'The page could not be read (' || coalesce(l.error, 'failed') || '). Give another page on the provider''s site.');
    end if;
    if found and l.status = 'read' and l.read_at >= coalesce(i.input_at, i.created_at) then
      return jsonb_build_object('state', 'succeeded', 'outcome', 'listing_read', 'admitted', v_adm > 0);
    end if;
  end if;
  if not exists (select 1 from pipeline.scholarship_coverage_items x where x.provider_id = v_pid and x.item_key = v_key and x.present
                   and x.state = case i.missing_fact when 'sch_source_missing' then 'source_not_discovered' when 'sch_international_unresolved' then 'international_unresolved'
                                                     else 'ownership_conflict' end) then
    return jsonb_build_object('state', 'succeeded', 'outcome', 'coverage_state_moved', 'admitted', v_adm > 0);
  end if;
  return jsonb_build_object('state', 'pending', 'evidence', 'the coverage case is still ' || i.missing_fact);
end $$;


