CREATE OR REPLACE FUNCTION "security"."har_work_item_v1"("p_id" bigint, "p_event" "text", "p_detail" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_interventions; v_wi jsonb;
begin
  select * into i from pipeline.layer4_interventions where id = p_id;
  v_wi := i.resume_target->'work_item';
  if v_wi is null then return; end if;
  if p_event = 'decided' and exists (select 1 from pipeline.layer4_interventions x where x.id <> i.id and x.status in ('ai_pending', 'awaiting_input')
                                       and x.resume_target->'work_item' = v_wi) then return; end if;
  perform security.work_item_report_v1(v_wi->>'lane', v_wi->>'entity', v_wi->>'kind', p_event, coalesce(p_detail, '{}'::jsonb));
end $$;


ALTER FUNCTION "security"."har_work_item_v1"("p_id" bigint, "p_event" "text", "p_detail" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."health_hourly_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_at timestamptz := date_trunc('hour', now()); v_hour timestamptz := now() - interval '1 hour'; v_day timestamptz := now() - interval '24 hours';
        v_latest jsonb; v_hour_ago jsonb; v_day_ago jsonb; v_cc text; v_n int := 0; v_target numeric := security.pipeline_num_v1('health.headline_target', 0);
        v_pages int; v_values int; v_movers jsonb := '[]'::jsonb; v_b_now int; v_b_prev int; v_l4_now int; v_l4_prev int; r record;
        v_growth numeric := security.pipeline_num_v1('health.growth_pct', 20); v_drop numeric := security.pipeline_num_v1('health.binding_drop_pct', 10);
        v_stuck numeric := security.pipeline_num_v1('health.stuck_hours', 4); v_burn numeric := security.pipeline_num_v1('health.burn_warn_pct', 80);
begin
  select data into v_latest from pipeline.stats_15m order by at desc limit 1;
  select data into v_hour_ago from pipeline.stats_15m where at <= v_hour order by at desc limit 1;
  select data into v_day_ago from pipeline.stats_15m where at <= v_day order by at desc limit 1;

  -- headline: pages read (ledger, mode read) and values admitted (field counts up over the hour, every country)
  select coalesce(sum(items), 0) into v_pages from pipeline.mode_outcome_ledger where mode = 'read' and run_at > v_hour;
  select coalesce(sum(greatest(0, (v_latest->'countries'->c->'now'->>f)::int - coalesce((v_hour_ago->'countries'->c->'now'->>f)::int, (v_latest->'countries'->c->'now'->>f)::int))), 0) into v_values
    from jsonb_object_keys(coalesce(v_latest->'countries', '{}'::jsonb)) c, unnest(array['fee', 'english', 'intakes', 'official_page', 'campus', 'delivery', 'duration']) f;
  insert into pipeline.health_snapshots(at, country, metric, value) values (v_at, 'ALL', 'headline',
    jsonb_build_object('pages_read', v_pages, 'values_admitted', v_values, 'target_24h', v_target,
                       'pace_24h', (select coalesce(sum((value->>'pages_read')::int + (value->>'values_admitted')::int), 0) from pipeline.health_snapshots where metric = 'headline' and at > v_day) + v_pages + v_values,
                       'target_set', v_target > 0))
  on conflict (at, country, metric) do update set value = excluded.value; v_n := v_n + 1;

  -- fields_delta per country: the hour and the day, from the 15-minute stats
  for v_cc in select jsonb_object_keys(coalesce(v_latest->'countries', '{}'::jsonb)) loop
    insert into pipeline.health_snapshots(at, country, metric, value) values (v_at, v_cc, 'fields_delta',
      jsonb_build_object('now', v_latest->'countries'->v_cc->'now',
        'hour', (select jsonb_object_agg(k, (v_latest->'countries'->v_cc->'now'->>k)::int - coalesce((v_hour_ago->'countries'->v_cc->'now'->>k)::int, (v_latest->'countries'->v_cc->'now'->>k)::int)) from jsonb_object_keys(v_latest->'countries'->v_cc->'now') k),
        'day', (select jsonb_object_agg(k, (v_latest->'countries'->v_cc->'now'->>k)::int - coalesce((v_day_ago->'countries'->v_cc->'now'->>k)::int, (v_latest->'countries'->v_cc->'now'->>k)::int)) from jsonb_object_keys(v_latest->'countries'->v_cc->'now') k)))
    on conflict (at, country, metric) do update set value = excluded.value; v_n := v_n + 1;
    -- a field count that fell over the day beyond the growth share is a negative mover (the cause is in admin_control_events or a migration of the window)
    for r in select k, (v_latest->'countries'->v_cc->'now'->>k)::int now_v, (v_day_ago->'countries'->v_cc->'now'->>k)::int prev_v from jsonb_object_keys(v_latest->'countries'->v_cc->'now') k loop
      if r.prev_v > 0 and r.now_v < r.prev_v * (1 - v_growth / 100) then
        v_movers := v_movers || jsonb_build_object('kind', 'field_fell', 'country', v_cc, 'field', r.k, 'from', r.prev_v, 'to', r.now_v, 'window', jsonb_build_array(v_day, now()),
                                                   'look_in', 'pipeline.admin_control_events and supabase_migrations.schema_migrations applied in the window');
      end if;
    end loop;
  end loop;

  -- lane_wait and ledger
  insert into pipeline.health_snapshots(at, country, metric, value) values (v_at, 'ALL', 'lane_wait', (select coalesce(jsonb_agg(to_jsonb(w)), '[]'::jsonb) from security.lane_queue_wait_v1(1) w))
  on conflict (at, country, metric) do update set value = excluded.value; v_n := v_n + 1;
  insert into pipeline.health_snapshots(at, country, metric, value) values (v_at, 'ALL', 'ledger',
    (select coalesce(jsonb_object_agg(mode, jsonb_build_object('calls', calls, 'items', items, 'ok', ok, 'failed', failed, 'avg_ms', avg_ms)), '{}'::jsonb)
       from (select mode, count(*) calls, sum(items) items, sum(ok) ok, sum(failed) failed, round(avg(ms)) avg_ms from pipeline.mode_outcome_ledger where run_at > v_hour group by mode) z))
  on conflict (at, country, metric) do update set value = excluded.value; v_n := v_n + 1;

  -- idle: every watched queue that is not simply moving, with its why-idle line
  insert into pipeline.health_snapshots(at, country, metric, value) values (v_at, 'ALL', 'idle',
    (select coalesce(jsonb_agg(jsonb_build_object('queue', w.key, 'label', w.label, 'state', s.state, 'waiting', s.pending, 'why', security.lane_why_idle_v1(w.key)) order by w.sort), '[]'::jsonb)
       from pipeline.queue_watch w join pipeline.queue_watch_state s on s.key = w.key where w.enabled and (s.state <> 'moving' or coalesce(array_length(s.jobs_paused, 1), 0) > 0 or coalesce(s.done_window, 0) = 0)))
  on conflict (at, country, metric) do update set value = excluded.value; v_n := v_n + 1;
  -- a lane with work waiting and no progress for health.stuck_hours is a negative mover
  for r in select w.key, s.pending, s.last_progress from pipeline.queue_watch w join pipeline.queue_watch_state s on s.key = w.key
            where w.enabled and coalesce(s.pending, 0) > 0 and coalesce(s.last_progress, '-infinity') < now() - make_interval(hours => v_stuck::int) loop
    v_movers := v_movers || jsonb_build_object('kind', 'lane_no_progress', 'queue', r.key, 'waiting', r.pending, 'last_progress', r.last_progress, 'why', security.lane_why_idle_v1(r.key));
  end loop;

  -- bound_empty per country: a bound page with a stored copy, read more than health.bound_empty_hours ago, whose course holds no fee, English score or intake
  for r in select k.iso_alpha2 cc, count(*) n
             from pipeline.coverage_course_pages p join pipeline.evidence_artifacts e on e.id = p.evidence_id and e.storage_path is not null
             join catalogue.providers pr on pr.id = p.provider_id join ref.countries k on k.id = pr.country_id
            where p.status = 'bound' and p.read_status = 'read' and p.read_at < now() - make_interval(hours => security.pipeline_num_v1('health.bound_empty_hours', 12)::int)
              and not exists (select 1 from catalogue.course_fees f where f.course_id = p.course_id and f.status = 'active' and f.audience = 'international')
              and not exists (select 1 from catalogue.course_english_requirements q where q.course_id = p.course_id and q.status = 'active')
              and not exists (select 1 from catalogue.course_intakes i where i.course_id = p.course_id and i.status = 'active')
            group by 1 loop
    insert into pipeline.health_snapshots(at, country, metric, value) values (v_at, r.cc, 'bound_empty', jsonb_build_object('pages', r.n, 'after_hours', security.pipeline_num_v1('health.bound_empty_hours', 12)))
    on conflict (at, country, metric) do update set value = excluded.value; v_n := v_n + 1;
  end loop;

  -- binding rate and Layer 4 growth over the day against the day before
  select count(*) filter (where bound_at > v_day), count(*) filter (where bound_at between v_day - interval '24 hours' and v_day) into v_b_now, v_b_prev from pipeline.coverage_course_pages where bound_at > v_day - interval '24 hours';
  if v_b_prev > 0 and v_b_now < v_b_prev * (1 - v_drop / 100) then
    v_movers := v_movers || jsonb_build_object('kind', 'binding_rate_fell', 'from', v_b_prev, 'to', v_b_now);
  end if;
  select count(*) filter (where created_at > v_day), count(*) filter (where created_at between v_day - interval '24 hours' and v_day) into v_l4_now, v_l4_prev from pipeline.layer4_review_items where created_at > v_day - interval '24 hours';
  if v_l4_now > greatest(10, v_l4_prev * (1 + v_growth / 100)) then
    v_movers := v_movers || jsonb_build_object('kind', 'layer4_grew', 'from', v_l4_prev, 'to', v_l4_now, 'pending_total', (select count(*) from pipeline.layer4_review_items where status = 'pending'));
  end if;
  insert into pipeline.health_snapshots(at, country, metric, value) values (v_at, 'ALL', 'negative_movers', v_movers)
  on conflict (at, country, metric) do update set value = excluded.value; v_n := v_n + 1;

  -- budget burn from the latest 15-minute stats
  insert into pipeline.health_snapshots(at, country, metric, value) values (v_at, 'ALL', 'budget_burn',
    jsonb_build_object(
      'firecrawl', (select jsonb_agg(jsonb_build_object('group', g->>'group', 'used', (g->>'used')::numeric, 'share', (g->>'share')::numeric,
                                                        'warn', (g->>'share')::numeric > 0 and (g->>'used')::numeric >= (g->>'share')::numeric * v_burn / 100))
                      from jsonb_array_elements(coalesce(v_latest->'firecrawl'->'groups', '[]'::jsonb)) g),
      'ai', (select jsonb_agg(jsonb_build_object('use', a->>'use', 'spent_usd', (a->>'spent_usd')::numeric, 'guard_usd', (a->>'guard_usd')::numeric,
                                                 'warn', (a->>'guard_usd')::numeric > 0 and (a->>'spent_usd')::numeric >= (a->>'guard_usd')::numeric * v_burn / 100))
               from jsonb_array_elements(coalesce(v_latest->'ai', '[]'::jsonb)) a),
      'warn_pct', v_burn))
  on conflict (at, country, metric) do update set value = excluded.value; v_n := v_n + 1;

  return jsonb_build_object('at', v_at, 'rows', v_n, 'pages_read', v_pages, 'values_admitted', v_values, 'negative_movers', jsonb_array_length(v_movers));
end $$;


ALTER FUNCTION "security"."health_hourly_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."health_hourly_v1"() IS 'R3: hourly delta rollup into pipeline.health_snapshots (headline, fields_delta, lane_wait, ledger, idle, bound_empty, negative_movers, budget_burn); read by the hourly report';



CREATE OR REPLACE FUNCTION "security"."health_latest_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_object_agg(country || ':' || metric, value), '{}'::jsonb) from pipeline.health_snapshots where at = (select max(at) from pipeline.health_snapshots)
$$;


ALTER FUNCTION "security"."health_latest_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."host_pages_apply_v1"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_done int := 0;
begin
  if not exists (select 1 from pipeline.uni_adapters u where u.provider_id = p_provider_id and u.enabled and u.admit and 'host_pages' = any (u.admit_fields)) then
    return jsonb_build_object('ok', false, 'note', 'host pages are not admitted for this university'); end if;
  for r in
    select h.course_id, h.host_course_id, h.host_url from pipeline.course_host_pages h
     where h.provider_id = p_provider_id and h.active and h.link_type = 'shared_page' and coalesce(h.register_check, 'none') <> 'fail'
       and exists (select 1 from pipeline.coverage_course_pages pg where pg.course_id = h.course_id and pg.url = h.host_url and pg.read_status = 'identity_mismatch')
       and exists (select 1 from pipeline.coverage_course_pages hp where hp.course_id = h.host_course_id and hp.url = h.host_url and hp.read_status = 'read' and hp.identity_basis is not null)
  loop
    update pipeline.coverage_course_pages pg set read_status = 'read', identity_basis = 'host_page', candidates = case when pg.candidates ? 'adapter_extra' then pg.candidates else coalesce(pg.candidates, '{}'::jsonb) || coalesce((select jsonb_build_object('adapter_extra', hp.candidates->'adapter_extra') from pipeline.coverage_course_pages hp where hp.course_id = r.host_course_id and hp.candidates ? 'adapter_extra'), '{}'::jsonb) end, evidence_id = coalesce(pg.evidence_id, (select hp.evidence_id from pipeline.coverage_course_pages hp where hp.course_id = r.host_course_id)) where pg.course_id = r.course_id and pg.url = r.host_url;
    update pipeline.course_host_pages set applied_at = now() where course_id = r.course_id;
    v_done := v_done + 1;
  end loop;
  return jsonb_build_object('ok', true, 'confirmed', v_done);
end $$;


ALTER FUNCTION "security"."host_pages_apply_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."host_pages_detect_v1"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_shared int; v_double int; v_gone int; v_r record; v_chk text[];
begin
  -- shared_page: the course's page failed the identity check, but the same page is confirmed for another course of
  -- the university whose title is the start of this course's title (majors, research disciplines).
  with cand as (
    select ch.id child_id, hp.course_id host_id, pg.url, hp.evidence_id, hc.canonical_title host_title, ch.canonical_title child_title
      from pipeline.coverage_course_pages pg join catalogue.courses ch on ch.id = pg.course_id and ch.lifecycle_status = 'active'
      join pipeline.coverage_course_pages hp on hp.url = pg.url and hp.provider_id = pg.provider_id and hp.course_id <> pg.course_id and hp.read_status = 'read' and hp.identity_basis is not null
      join catalogue.courses hc on hc.id = hp.course_id and hc.lifecycle_status = 'active'
     where pg.provider_id = p_provider_id and pg.read_status = 'identity_mismatch' and pg.http_status = 200
       and not security.is_double_degree_title(ch.canonical_title)
       and (security.course_title_key(ch.canonical_title) = security.course_title_key(hc.canonical_title)
            or lower(ch.canonical_title) like lower(hc.canonical_title) || ' (%')
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = ch.id and k.field in ('official_url', 'course_url'))),
  one as (select distinct on (child_id) * from cand order by child_id, length(host_title) desc, host_id),
  ins as (
    insert into pipeline.course_host_pages(course_id, provider_id, link_type, host_course_id, host_url, basis, printed, evidence_id, reason)
    select child_id, p_provider_id, 'shared_page', host_id, url, 'title', left(child_title || ' on the page of ' || host_title, 300), evidence_id, 'the same page is confirmed for the host course'
      from one
    on conflict (course_id) do update set host_course_id = excluded.host_course_id, host_url = excluded.host_url, printed = excluded.printed, evidence_id = excluded.evidence_id, set_at = now() where pipeline.course_host_pages.set_by = 'detector'
    returning 1)
  select count(*) into v_shared from ins;
  for v_r in select h.course_id, h.host_course_id from pipeline.course_host_pages h where h.provider_id = p_provider_id and h.link_type = 'shared_page' loop
    v_chk := security.award_register_check(v_r.course_id, v_r.host_course_id);
    update pipeline.course_host_pages set register_check = v_chk[1], check_detail = v_chk[2] where course_id = v_r.course_id;
  end loop;
  -- double_degree: a double degree bound to a page that was read but not confirmed, and not shared with another course
  with cand as (
    select ch.id child_id, pg.url, pg.evidence_id, ch.canonical_title
      from pipeline.coverage_course_pages pg join catalogue.courses ch on ch.id = pg.course_id and ch.lifecycle_status = 'active'
     where pg.provider_id = p_provider_id and pg.read_status = 'identity_mismatch' and pg.http_status = 200
       and security.is_double_degree_title(ch.canonical_title)
       and not exists (select 1 from pipeline.coverage_course_pages p2 where p2.url = pg.url and p2.course_id <> pg.course_id)
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = ch.id and k.field in ('official_url', 'course_url'))),
  ins as (
    insert into pipeline.course_host_pages(course_id, provider_id, link_type, host_url, basis, printed, evidence_id, reason)
    select child_id, p_provider_id, 'double_degree', url, 'bound page', left(canonical_title || ' bound to ' || url, 300), evidence_id, 'read but the identity was not confirmed: confirm by hand'
      from cand
    on conflict (course_id) do update set host_url = excluded.host_url, printed = excluded.printed, evidence_id = excluded.evidence_id, set_at = now() where pipeline.course_host_pages.set_by = 'detector'
    returning 1)
  select count(*) into v_double from ins;
  -- no_public_page: the bound page is gone (404 twice or more)
  with cand as (
    select ch.id child_id, pg.url, ch.canonical_title
      from pipeline.coverage_course_pages pg join catalogue.courses ch on ch.id = pg.course_id and ch.lifecycle_status = 'active'
     where pg.provider_id = p_provider_id and pg.read_status = 'fetch_failed' and pg.http_status = 404 and coalesce(pg.read_attempts, 0) >= 2
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = ch.id and k.field in ('official_url', 'course_url'))),
  ins as (
    insert into pipeline.course_host_pages(course_id, provider_id, link_type, host_url, basis, printed, reason)
    select child_id, p_provider_id, 'no_public_page', url, '404', left(canonical_title || ': ' || url || ' is gone', 300), 'the page returned 404 twice or more: record no public page by hand'
      from cand
    on conflict (course_id) do update set host_url = excluded.host_url, printed = excluded.printed, set_at = now() where pipeline.course_host_pages.set_by = 'detector'
    returning 1)
  select count(*) into v_gone from ins;
  return jsonb_build_object('shared_page', v_shared, 'double_degree', v_double, 'no_public_page', v_gone);
end $$;


ALTER FUNCTION "security"."host_pages_detect_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."host_pages_hourly_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u record; v jsonb := '[]'::jsonb;
begin
  for u in select a.provider_id from pipeline.uni_adapters a where a.enabled and a.admit and 'host_pages' = any (a.admit_fields) loop
    v := v || jsonb_build_array(jsonb_build_object('provider_id', u.provider_id, 'found', security.host_pages_detect_v1(u.provider_id), 'apply', security.host_pages_apply_v1(u.provider_id)));
  end loop;
  return v;
end $$;


ALTER FUNCTION "security"."host_pages_hourly_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."housekeeping_daily_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_limit int := security.pipeline_num_v1('batch.housekeeping_rows', 400000)::int; v_nonces int := 0; v_log int := 0;
begin
  delete from pipeline.pilot_edge_nonces where id in (
    select n.id from pipeline.pilot_edge_nonces n
     where n.expires_at < now() - make_interval(days => security.pipeline_num_v1('retention.nonce_keep_days', 1)::int)
     limit v_limit);
  get diagnostics v_nonces = row_count;
  delete from cron.job_run_details where runid in (
    select d.runid from cron.job_run_details d
     where d.start_time < now() - make_interval(days => security.pipeline_num_v1('retention.job_log_keep_days', 3)::int)
     limit v_limit);
  get diagnostics v_log = row_count;
  if v_nonces + v_log > 0 then
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('retention', 'housekeeping', 'housekeeping-daily', jsonb_build_object('request_codes', v_nonces, 'job_log', v_log), null);
  end if;
  return jsonb_build_object('request_codes', v_nonces, 'job_log', v_log);
end $$;


ALTER FUNCTION "security"."housekeeping_daily_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."hygiene_check_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_idle int := security.pipeline_num_v1('hygiene.idle_days', 14)::int; v_since timestamptz; v_then timestamptz; f jsonb := '{}'::jsonb; s jsonb; v_sync jsonb;
begin
  v_sync := security.component_register_sync_v1();
  -- counters now
  insert into pipeline.component_usage_snapshots(at, kind, name, reads, writes)
  select now(), 'table', t.schemaname || '.' || t.relname, coalesce(t.seq_scan, 0) + coalesce(t.idx_scan, 0), t.n_tup_ins + t.n_tup_upd + t.n_tup_del
    from pg_stat_user_tables t
  union all
  select now(), 'index', i.schemaname || '.' || i.indexrelname, i.idx_scan, null from pg_stat_user_indexes i
  on conflict do nothing;
  -- the latest snapshot at least the idle time old
  v_since := now() - make_interval(days => v_idle);
  select max(x.at) into v_then from pipeline.component_usage_snapshots x where x.at <= v_since;
  if v_then is not null then
    f := f || jsonb_build_object('unused_tables', coalesce((select jsonb_agg(jsonb_build_object('name', n.name, 'size', pg_size_pretty(coalesce(r.size_bytes, 0))) order by r.size_bytes desc nulls last)
          from pipeline.component_usage_snapshots n join pipeline.component_usage_snapshots o on o.kind = n.kind and o.name = n.name and o.at = v_then
          left join pipeline.component_register r on r.kind = 'table' and r.name = n.name
         where n.kind = 'table' and n.at = (select max(at) from pipeline.component_usage_snapshots) and n.reads = o.reads and n.writes = o.writes), '[]'::jsonb),
      'unused_indexes', coalesce((select jsonb_agg(jsonb_build_object('name', n.name, 'size', pg_size_pretty(pg_relation_size(to_regclass(n.name)))))
          from pipeline.component_usage_snapshots n join pipeline.component_usage_snapshots o on o.kind = n.kind and o.name = n.name and o.at = v_then
          join pg_index x on x.indexrelid = to_regclass(n.name)
         where n.kind = 'index' and n.at = (select max(at) from pipeline.component_usage_snapshots) and n.reads = o.reads and not x.indisprimary and not x.indisunique), '[]'::jsonb));
  end if;
  f := f || jsonb_build_object(
    'edge_functions_not_called', coalesce((select jsonb_agg(r.name order by r.name) from pipeline.component_register r
         where r.kind = 'edge_function' and r.status = 'active' and (r.last_used_at is null or r.last_used_at < v_since) and r.registered_at < v_since), '[]'::jsonb),
    'jobs_not_catalogued', coalesce((select jsonb_agg(j.jobname) from cron.job j where not exists (select 1 from pipeline.automation_catalogue c where c.jobname = j.jobname)), '[]'::jsonb),
    'jobs_switched_off', coalesce((select jsonb_agg(j.jobname) from cron.job j where not j.active), '[]'::jsonb),
    'tables_without_rls', coalesce((select jsonb_agg(n.nspname || '.' || c.relname order by 1) from pg_class c join pg_namespace n on n.oid = c.relnamespace
         where c.relkind in ('r', 'p') and not c.relrowsecurity and not c.relispartition
           and n.nspname in ('public', 'pipeline', 'catalogue', 'search', 'scholarship', 'api', 'publishing', 'ref', 'security', 'workflow', 'ranking', 'private')), '[]'::jsonb),
    'definer_functions_without_search_path', coalesce((select jsonb_agg(n.nspname || '.' || p.proname order by 1) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
         where p.prosecdef and p.proconfig is null and n.nspname in ('public', 'pipeline', 'catalogue', 'search', 'scholarship', 'api', 'publishing', 'security')), '[]'::jsonb),
    'public_functions_open_to_anon', coalesce((select jsonb_agg(p.proname order by 1) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
         where n.nspname = 'public' and p.prosecdef and has_function_privilege('anon', p.oid, 'execute')), '[]'::jsonb),
    'tables_without_purpose', (select count(*) from pipeline.component_register r where r.kind = 'table' and r.status = 'active' and r.purpose is null),
    'ready_to_drop', coalesce((select jsonb_agg(jsonb_build_object('kind', r.kind, 'name', r.name, 'replaced_by', r.replaced_by, 'since', r.retire_after)) from pipeline.component_register r
         where r.status = 'retiring' and r.retire_after <= current_date), '[]'::jsonb));
  s := jsonb_build_object('sync', v_sync, 'compared_with', v_then,
    'unused_tables', jsonb_array_length(coalesce(f->'unused_tables', '[]'::jsonb)), 'unused_indexes', jsonb_array_length(coalesce(f->'unused_indexes', '[]'::jsonb)),
    'edge_functions_not_called', jsonb_array_length(f->'edge_functions_not_called'), 'jobs_not_catalogued', jsonb_array_length(f->'jobs_not_catalogued'),
    'tables_without_rls', jsonb_array_length(f->'tables_without_rls'), 'definer_functions_without_search_path', jsonb_array_length(f->'definer_functions_without_search_path'),
    'public_functions_open_to_anon', jsonb_array_length(f->'public_functions_open_to_anon'), 'ready_to_drop', jsonb_array_length(f->'ready_to_drop'),
    'tables_without_purpose', f->'tables_without_purpose');
  insert into pipeline.hygiene_reports(summary, findings) values (s, f);
  return s;
end $$;


ALTER FUNCTION "security"."hygiene_check_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."important_date_queue_targeted_refresh_impl"("p_important_date_id" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_d pipeline.important_dates%rowtype; v_id uuid;
begin
  if auth.uid() is null or security.current_role_rank()<3 then
    raise exception 'curator role required' using errcode='42501';
  end if;
  if length(trim(coalesce(p_reason,'')))<5 then raise exception 'refresh reason required'; end if;
  select * into v_d from pipeline.important_dates where id=p_important_date_id and status='active';
  if not found then raise exception 'active important date not found'; end if;
  if v_d.refresh_layer is null then raise exception 'important date has no governed refresh layer'; end if;
  if v_d.source_id is null and v_d.source_profile_id is null and v_d.entity_id is null then
    raise exception 'country-wide important date cannot trigger ingestion';
  end if;
  insert into pipeline.refresh_requests(
    requested_layer,country_code,source_id,source_profile_id,entity_type,entity_id,reason,
    trigger_type,important_date_id,requested_by,change_control_ref
  ) values (
    v_d.refresh_layer,v_d.country_code,v_d.source_id,v_d.source_profile_id,v_d.entity_type,v_d.entity_id,
    trim(p_reason),'important_date',v_d.id,auth.uid(),v_d.change_control_ref
  ) returning id into v_id;
  return v_id;
end $$;


