CREATE OR REPLACE FUNCTION "security"."intake_course_applicability_v1"("p_raw" "text", "p_month" integer, "p_year" integer, "p_cal" "jsonb", "p_month_only" boolean, "p_periods" "text"[] DEFAULT NULL::"text"[], "p_period_text" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_names text[] := array['january','february','march','april','may','june','july','august','september','october','november','december'];
        v_cur int := extract(year from (now() at time zone 'Australia/Melbourne'))::int;  -- fixed: the calendar year in Australia
        v_offered int[] := '{}'; v_missing text[]; f text; k int; v_y int; v_per text; v_w text;
begin
  -- a named study period (the course page names the calendar's own period, e.g. "Term 1"): the page must state it as the course's own
  -- offering, never only in a personal account or with a past year ("I commenced in Term 1 2023")
  if not p_month_only and p_periods is not null then
    -- the period text as the plan reads it (security.intake_period_text_v1: "Semester Two" -> semester 2, lists expanded)
    foreach f in array regexp_split_to_array(lower(coalesce(p_period_text, p_raw, '')), '(\.\s|[;\n]|\s\|\s|\|\|)') loop
      continue when f ~ '\m(i|we|my|our)\M (have |had )?(commenced|started|began|joined|enrolled|studied|completed)\M';
      foreach v_per in array p_periods loop
        continue when f !~ ('\m' || regexp_replace(v_per, '[ _-]+', '[ _-]*', 'g') || '\M');
        v_y := (regexp_match(f, '\m' || regexp_replace(v_per, '[ _-]+', '[ _-]*', 'g') || '\M,? (20\d\d)\M'))[1]::int;
        if v_y is null or v_y >= v_cur then return null; end if;
      end loop;
    end loop;
    return 'the course page does not state ' || array_to_string(p_periods, ', ') || ' as its own intake (offering evidence missing: only a personal account or a past year)';
  end if;
  -- each statement of the page wording (split at sentence ends, line breaks, list separators and the ' | ' that joins stored snippets)
  foreach f in array regexp_split_to_array(lower(coalesce(p_raw, '')), '(\.\s|[;\n]|\s\|\s|\|\|)') loop
    -- an offering: intake, start, entry or study-period wording; never a personal account
    continue when f !~ '\m(intakes?|commenc\w*|starts?|entry|offered|available|admissions?|semesters?|terms?|trimesters?|sessions?|begins?)\M'
               or f ~ '\m(i|we|my|our)\M (have |had )?(commenced|started|began|joined|enrolled|studied|completed)\M';
    for k in 1 .. 12 loop
      -- the month's full name or its abbreviation only (never "marketing" or "junior"); "may" only where it is a month ("May intake",
      -- "January, May, August", "May 2027"), never the verb ("students may start")
      v_w := '(?:' || v_names[k] || '|' || left(v_names[k], 3) || case when k = 9 then '|sept' else '' end || ')\.?';
      continue when k = any (v_offered) or f !~ ('\m' || v_w || '\M')
                 or (k = 5 and f !~ '\mmay\M\s*(,|\)|/|&|$|\d|20\d\d|intakes?|and\M|or\M|start|semester|term|session)' and f !~ '(,|/|&|\mand|\mor|\(|intakes?:?)\s*may\M');
      -- never a month of a past year ("February 2023")
      v_y := (regexp_match(f, '\m' || v_w || ',? (20\d\d)\M'))[1]::int;
      if v_y is null or v_y >= v_cur then v_offered := array_append(v_offered, k); end if;
    end loop;
  end loop;
  if not (p_month = any (v_offered)) then
    return 'the course page does not state ' || initcap(v_names[p_month]) || ' as an intake (offering evidence missing: no intake, start, entry or study period statement for this month, or only a personal account or a past year)';
  end if;
  if p_month_only then
    -- a month-only match: every month the course offers must start in that academic year of the main calendars, or another calendar applies
    select array_agg(initcap(v_names[o]) order by o) into v_missing from unnest(v_offered) o
     where not exists (select 1 from jsonb_to_recordset(p_cal) s(kind text, year int, month int, year_ok boolean) where s.kind = 'start' and s.month = o and s.year = p_year and s.year_ok);
    if v_missing is not null then
      return 'the course''s intakes (' || (select string_agg(initcap(v_names[o]), ', ' order by o) from unnest(v_offered) o) || ') do not all start in the university''s ' || p_year
             || ' main teaching calendar (no start in ' || array_to_string(v_missing, ', ') || '): another academic calendar applies';
    end if;
  end if;
  return null;
end $_$;


ALTER FUNCTION "security"."intake_course_applicability_v1"("p_raw" "text", "p_month" integer, "p_year" integer, "p_cal" "jsonb", "p_month_only" boolean, "p_periods" "text"[], "p_period_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_course_applicability_v1"("p_raw" "text", "p_month" integer, "p_year" integer, "p_cal" "jsonb", "p_month_only" boolean, "p_periods" "text"[], "p_period_text" "text") IS 'CF-247 (direction 5 Nov 2026 sections 1 and 2; F-INT 9 Nov 2026): the course page must state the intake as its own offering (intake, start, entry or study-period wording; never a personal account or a month of a past year), and a month-only match needs a calendar that applies to the course. The month pattern is a non-capturing group, so a printed year after a month ("February 2027") is read as the year.';



CREATE OR REPLACE FUNCTION "security"."intake_date_withdraw_v1"("p_intake" "uuid", "p_reason" "text", "p_actor" "text", "p_hold" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare d pipeline.course_intake_dates%rowtype; i catalogue.course_intakes%rowtype; v_before jsonb; v_after jsonb; v_adm_before jsonb; v_adm_after jsonb; v_year int; v_start date; v_dl date; v_pub jsonb;
begin
  if coalesce(btrim(p_reason), '') = '' or length(btrim(p_reason)) < 8 then raise exception 'give the reason for the withdrawal' using errcode = '22023'; end if;  -- fixed: a reason of a few words, as the other admin writes
  select * into d from pipeline.course_intake_dates where intake_id = p_intake for update;
  -- IQ-00313: the admission from its own record (the latest filled event no later withdrawal undid); a later run may have re-decided the row
  select e.before_value, e.after_value into v_adm_before, v_adm_after from pipeline.course_intake_date_events e
   where e.intake_id = p_intake and e.outcome = 'filled'
     and not exists (select 1 from pipeline.course_intake_date_events w where w.intake_id = p_intake and w.outcome = 'withdrawn' and w.id > e.id)
   order by e.id desc limit 1;
  if d.intake_id is null or v_adm_after is null then
    return jsonb_build_object('intake_id', p_intake, 'withdrawn', false, 'why', 'no value admitted by the intake-dates process for this intake');
  end if;
  if exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = d.course_id and k.field in ('intakes', 'intake')) then
    return jsonb_build_object('intake_id', p_intake, 'withdrawn', false, 'why', 'the intakes are locked by hand');
  end if;
  select * into i from catalogue.course_intakes where id = p_intake for update;
  -- only the fields this process set, and only while the catalogue still holds the value it admitted
  v_year := case when v_adm_before->>'year' is null and v_adm_after->>'year' is not null and i.intake_year is not distinct from (v_adm_after->>'year')::int then null else i.intake_year end;
  v_start := case when v_adm_before->>'start_date' is null and v_adm_after->>'start_date' is not null and i.start_date is not distinct from (v_adm_after->>'start_date')::date then null else i.start_date end;
  v_dl := case when v_adm_before->>'application_deadline' is null and v_adm_after->>'application_deadline' is not null
                    and i.application_deadline is not distinct from (v_adm_after->>'application_deadline')::date then null else i.application_deadline end;
  v_before := jsonb_build_object('year', i.intake_year, 'start_date', i.start_date, 'application_deadline', i.application_deadline);
  v_after := jsonb_build_object('year', v_year, 'start_date', v_start, 'application_deadline', v_dl);
  if v_before = v_after then
    return jsonb_build_object('intake_id', p_intake, 'withdrawn', false, 'why', 'the catalogue no longer holds the value this process admitted');
  end if;
  update catalogue.course_intakes set intake_year = v_year, start_date = v_start, application_deadline = v_dl where id = p_intake;
  update pipeline.course_intake_dates set outcome = 'skipped', reason = left('withdrawn: ' || btrim(p_reason), 500), start_precision = 'month',
         after_value = v_after, applied_at = now(), publication_state = null, publication_checked_at = null, publication_attempts = 0, next_action = 'human_decision_required'
   where intake_id = p_intake;
  insert into pipeline.course_intake_date_events(intake_id, course_id, provider_id, run_at, rule, outcome, reason, next_action, calendar_set, proposal_id, periods, start_precision,
                                                 deadline_kind, before_value, after_value, page_quote, start_quote, deadline_quote, calendar_url, calendar_evidence_id, bounded)
  values (p_intake, d.course_id, d.provider_id, now(), 'withdrawal', 'withdrawn', left('withdrawn: ' || btrim(p_reason) || ' (by ' || coalesce(p_actor, 'unknown') || ')', 500),
          'human_decision_required', d.calendar_set, d.proposal_id, d.periods, 'month', d.deadline_kind, v_before, v_after, d.page_quote, d.start_quote, d.deadline_quote,
          d.calendar_url, d.calendar_evidence_id, false);
  -- the existing hold: the course's intakes are locked as they now are, so no automated lane fills them again until a person lifts the lock
  if p_hold then
    insert into pipeline.manual_locks(entity, entity_id, field, mode, set_by, set_at)
    values ('course', d.course_id, 'intakes', 'value', case when p_actor ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then p_actor::uuid end, now())
    on conflict (entity, entity_id, field) do nothing;
  end if;
  perform search.refresh_course_enrichment_scoped_v1(array[d.course_id], true);
  select jsonb_agg(e) into v_pub from search.course_documents cd, jsonb_array_elements(case when jsonb_typeof(cd.intake_options) = 'array' then cd.intake_options else '[]'::jsonb end) e
   where cd.course_id = d.course_id and e->>'label' = i.intake_label;
  return jsonb_build_object('intake_id', p_intake, 'course_id', d.course_id, 'withdrawn', true, 'held', p_hold, 'before', v_before, 'after', v_after, 'website_source', coalesce(v_pub, '[]'::jsonb),
    'website_verified', not exists (select 1 from jsonb_array_elements(coalesce(v_pub, '[]'::jsonb)) e
                                     where e->>'start_date' is distinct from v_start::text or e->>'year' is distinct from v_year::text));
end $_$;


ALTER FUNCTION "security"."intake_date_withdraw_v1"("p_intake" "uuid", "p_reason" "text", "p_actor" "text", "p_hold" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_date_withdraw_v1"("p_intake" "uuid", "p_reason" "text", "p_actor" "text", "p_hold" boolean) IS 'CF-247 (direction 5 Nov 2026 15:50 §1, P0 IQ-00313; provenance 5 Nov 2026 16:47): withdraws a value the intake-dates process admitted, taken from the admission''s own record (the latest filled event no later withdrawal undid): reverts only the fields it set, only while the catalogue still holds them, never under a manual lock; the decision row becomes a course-level exception and, with p_hold (the default), the course''s intakes are held by the existing manual lock (mode value) until a person lifts it, a withdrawn event is appended (nothing earlier is changed or deleted), the projection is refreshed and the Website API v2 source is read back.';



CREATE OR REPLACE FUNCTION "security"."intake_dates_apply_v1"("p_limit" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- 4 Nov 2026 (Run now): the body is security.intake_dates_apply_v1(integer, uuid[]); no selector is the scheduled job, as before
  return security.intake_dates_apply_v1(p_limit, null::uuid[]);
end $$;


ALTER FUNCTION "security"."intake_dates_apply_v1"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_dates_apply_v1"("p_limit" integer) IS 'CF-247 intake dates (Platform Admin 2 Nov 2026 11:10 §2): job intake-dates-apply. Off unless pipeline setting intake_dates.apply_enabled is true. Applies security.intake_dates_plan_v1 to at most batch.intake_dates_apply rows, fills only empty columns, records each row in pipeline.course_intake_dates (once per approved calendar) and refreshes the search projection for the courses changed.';



CREATE OR REPLACE FUNCTION "security"."intake_dates_apply_v1"("p_limit" integer, "p_course_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_on boolean := coalesce((security.toolset_setting('pipeline', 'intake_dates.apply_enabled') #>> '{}')::boolean, false);
        v_filled int := 0; v_seen int := 0; v_courses uuid[] := '{}'; p record; v_n int; v_prov int := 0; v_by jsonb := '{}'::jsonb;
begin
  if not v_on then return jsonb_build_object('enabled', false, 'filled', 0); end if;
  perform pg_advisory_xact_lock(hashtext('cf247 intake dates apply'));  -- fixed: one run at a time
  -- 23:24 provenance: values filled before the page wording was kept get it now (as stored now), with the approved calendar's document
  update pipeline.course_intake_dates d
     set page_quote = coalesce(left(security.intake_page_wording_v1(d.course_id, i.evidence_id, e.source_url), 600), ''),
         calendar_evidence_id = cal.evidence_id, calendar_url = cal.url
    from catalogue.course_intakes i left join pipeline.evidence_artifacts e on e.id = i.evidence_id, pipeline.provider_policy_proposals cal
   where d.intake_id in (select d2.intake_id from pipeline.course_intake_dates d2 where d2.outcome = 'filled' and d2.calendar_url is null
                            and (p_course_ids is null or d2.course_id = any (p_course_ids))
                          limit security.pipeline_num_v1('batch.intake_dates_apply', 200)::int)
     and i.id = d.intake_id and cal.id = d.proposal_id;
  get diagnostics v_prov = row_count;
  -- CF-247 intake recovery (decision 5 Nov 2026): plan v3; every decision is also appended to pipeline.course_intake_date_events
  for p in select * from security.intake_dates_plan_v3(p_course_ids, p_limit) loop
    v_seen := v_seen + 1;
    if p.outcome = 'filled' then
      update catalogue.course_intakes i
         set intake_year = coalesce(i.intake_year, p.new_year), start_date = coalesce(i.start_date, p.new_start),
             application_deadline = coalesce(i.application_deadline, p.new_deadline)
       where i.id = p.intake_id and i.status = 'active'
         and (i.intake_year is null or i.intake_year = coalesce(p.new_year, i.intake_year));
      get diagnostics v_n = row_count;  -- 0 when a lock or the same-month guard kept the row as it was
      if v_n = 1 then v_filled := v_filled + 1; v_courses := v_courses || p.course_id; end if;
    end if;
    insert into pipeline.course_intake_dates(intake_id, course_id, provider_id, proposal_id, outcome, reason, periods, start_precision, deadline_kind, deadline_text,
                                             start_quote, deadline_quote, before_value, after_value, applied_at, page_quote, calendar_evidence_id, calendar_url, rule,
                                             calendar_set, inputs_fp, next_action, next_revisit_at)
    select p.intake_id, p.course_id, p.provider_id, p.proposal_id,
           case when p.outcome = 'filled' and v_n = 0 then 'skipped' else p.outcome end,
           case when p.outcome = 'filled' and v_n = 0 then 'kept by a lock or the same-month guard' else p.reason end,
           p.periods, p.start_precision, p.deadline_kind, p.deadline_text, p.start_quote, p.deadline_quote, p.before_value,
           (select jsonb_build_object('year', i.intake_year, 'start_date', i.start_date, 'application_deadline', i.application_deadline) from catalogue.course_intakes i where i.id = p.intake_id), now(),
           p.page_quote, p.calendar_evidence_id, p.calendar_url, p.rule, p.calendar_set, p.inputs_fp,
           case when p.outcome = 'filled' and v_n = 0 then 'human_decision_required' else p.next_action end,
           case when p.outcome = 'filled' and v_n = 0 then null else p.next_revisit_at end
    on conflict (intake_id) do update set proposal_id = excluded.proposal_id, outcome = excluded.outcome, reason = excluded.reason, periods = excluded.periods,
           start_precision = excluded.start_precision, deadline_kind = excluded.deadline_kind, deadline_text = excluded.deadline_text, start_quote = excluded.start_quote,
           deadline_quote = excluded.deadline_quote, before_value = excluded.before_value, after_value = excluded.after_value, applied_at = excluded.applied_at,
           page_quote = excluded.page_quote, calendar_evidence_id = excluded.calendar_evidence_id, calendar_url = excluded.calendar_url, rule = excluded.rule,
           calendar_set = excluded.calendar_set, inputs_fp = excluded.inputs_fp, next_action = excluded.next_action, next_revisit_at = excluded.next_revisit_at;
    insert into pipeline.course_intake_date_events(intake_id, course_id, provider_id, rule, outcome, reason, next_action, next_revisit_at, calendar_set, proposal_id, periods,
                                                   start_precision, deadline_kind, before_value, after_value, page_quote, start_quote, deadline_quote, calendar_url, calendar_evidence_id, bounded)
    select d.intake_id, d.course_id, d.provider_id, d.rule, d.outcome, d.reason, d.next_action, d.next_revisit_at, d.calendar_set, d.proposal_id, d.periods,
           d.start_precision, d.deadline_kind, d.before_value, d.after_value, d.page_quote, d.start_quote, d.deadline_quote, d.calendar_url, d.calendar_evidence_id, p_course_ids is not null
      from pipeline.course_intake_dates d where d.intake_id = p.intake_id;
    v_by := jsonb_set(v_by, array[coalesce(case when p.outcome = 'filled' and v_n = 0 then 'human_decision_required' else p.next_action end, 'unclassified')],
                      to_jsonb(coalesce((v_by->>coalesce(case when p.outcome = 'filled' and v_n = 0 then 'human_decision_required' else p.next_action end, 'unclassified'))::int, 0) + 1));
    v_n := null;
  end loop;
  if cardinality(v_courses) > 0 then
    -- 11 Nov 2026 (F-INT): never wait for the search-document writer. search-refresh-requested (every 10 minutes) holds it for 1-2 minutes and started at the
    -- same second as this job (10:26, 11:26): the apply waited, hit the statement time-out and rolled back every planned row. When the writer is busy the
    -- courses go to the search refresh queue instead (search.refresh_requests, processed by that job's next run).
    if pg_try_advisory_xact_lock(hashtext('cf247:search_course_documents_writer')) then  -- fixed: the one writer lock (W27)
      perform search.refresh_course_enrichment_scoped_v1((select array_agg(distinct x) from unnest(v_courses) x), true);
    else
      insert into search.refresh_requests(requested_by)
      values ('intake dates apply: ' || coalesce(cardinality((select array_agg(distinct x) from unnest(v_courses) x)), 0) || ' courses (search writer busy)');
    end if;
  end if;
  return jsonb_build_object('enabled', true, 'looked_at', v_seen, 'filled', v_filled, 'provenance_completed', v_prov, 'courses', coalesce(cardinality((select array_agg(distinct x) from unnest(v_courses) x)), 0),
                            'bounded', p_course_ids is not null, 'selected_courses', coalesce(cardinality(p_course_ids), 0), 'by_next_action', v_by);
end $$;


ALTER FUNCTION "security"."intake_dates_apply_v1"("p_limit" integer, "p_course_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_dates_apply_v1"("p_limit" integer, "p_course_ids" "uuid"[]) IS 'CF-247 intake dates, job intake-dates-apply with a bounded course selector (Platform Admin 4 Nov 2026 20:05 §3): the job''s body, with the selected courses passed to security.intake_dates_plan_v2. A null selector is the scheduled job. Called by security.intake_dates_apply_v1(integer) and by Run now (security.job_run_now_v1).';



CREATE OR REPLACE FUNCTION "security"."intake_dates_plan_v1"("p_course_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_limit" integer DEFAULT NULL::integer) RETURNS TABLE("intake_id" "uuid", "course_id" "uuid", "provider_id" "uuid", "proposal_id" "uuid", "outcome" "text", "reason" "text", "periods" "text"[], "new_year" integer, "new_start" "date", "new_deadline" "date", "start_precision" "text", "deadline_kind" "text", "deadline_text" "text", "start_quote" "text", "deadline_quote" "text", "before_value" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_today date := (now() at time zone 'Australia/Melbourne')::date;  -- fixed: the calendar day in Australia (month roll-over)
  v_max_before int := security.pipeline_num_v1('intake_dates.deadline_max_days_before', 366)::int;
  v_limit int := coalesce(p_limit, security.pipeline_num_v1('batch.intake_dates_apply', 200)::int);
  r record; v_m int; v_prop uuid; v_year int; v_starts date[]; v_start date; v_pers text[]; v_sq text; v_dl date[]; v_dq text; v_roll text; v_url text; v_chk jsonb; v_pq text; v_named text[];
begin
  for r in
    select i.id, i.course_id, c.provider_id, i.intake_label, i.intake_year, i.start_date, i.application_deadline, i.evidence_id
      from catalogue.course_intakes i join catalogue.courses c on c.id = i.course_id
     where i.status = 'active' and c.lifecycle_status = 'active'
       and (p_course_ids is null or i.course_id = any (p_course_ids))
       and (i.intake_year is null or i.start_date is null or i.application_deadline is null)
       and exists (select 1 from pipeline.provider_policy_proposals p where p.provider_id = c.provider_id and p.kind = 'intake_calendar' and p.status = 'approved')
       -- each row once for each approved calendar
       and not exists (select 1 from pipeline.course_intake_dates d where d.intake_id = i.id
                          and d.proposal_id is not distinct from (select p.id from pipeline.provider_policy_proposals p where p.provider_id = c.provider_id and p.kind = 'intake_calendar' and p.status = 'approved'
                                                                   order by p.decided_at desc nulls last, p.created_at desc limit 1))
     order by i.course_id, i.id
     limit v_limit
  loop
    intake_id := r.id; course_id := r.course_id; provider_id := r.provider_id; periods := null; new_year := null; new_start := null; new_deadline := null;
    start_precision := null; deadline_kind := null; deadline_text := null; start_quote := null; deadline_quote := null; reason := null;
    before_value := jsonb_build_object('year', r.intake_year, 'start_date', r.start_date, 'application_deadline', r.application_deadline);
    select p.id into v_prop from pipeline.provider_policy_proposals p where p.provider_id = r.provider_id and p.kind = 'intake_calendar' and p.status = 'approved'
     order by p.decided_at desc nulls last, p.created_at desc limit 1;
    proposal_id := v_prop;
    v_m := array_position(array['january','february','march','april','may','june','july','august','september','october','november','december'], lower(btrim(r.intake_label)));
    -- the guards: a person's lock or hold, and the E16 page check on the page the month came from
    if exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = r.course_id and k.field in ('intakes', 'intake')) then
      outcome := 'skipped'; reason := 'intakes locked by hand'; return next; continue;
    end if;
    if security.course_held_v1(r.course_id) then outcome := 'skipped'; reason := 'course held'; return next; continue; end if;
    if v_m is null then outcome := 'skipped'; reason := 'intake is not a month'; return next; continue; end if;
    select e.source_url into v_url from pipeline.evidence_artifacts e where e.id = r.evidence_id;
    if v_url is null then outcome := 'skipped'; reason := 'no page behind the intake'; return next; continue; end if;
    if security.page_refused_v1(r.course_id, v_url) then outcome := 'skipped'; reason := 'page refused for this course'; return next; continue; end if;
    v_chk := security.course_page_check_v1(r.course_id, v_url, null, null);
    if v_chk->>'verdict' is distinct from 'pass' then
      outcome := 'skipped'; reason := 'page not proved to be the course''s own (E16 ' || coalesce(v_chk->>'verdict', 'no verdict') || ')'; return next; continue;
    end if;
    -- Named period only (Platform Admin 2 Nov 2026 ~14:50): the period must be named in the stored reading of the page that gave the intake:
    -- the page reader's intake quotes for that address, or the AI reading whose evidence is the intake's (its verbatim quote). No month-to-period inference.
    select lower(string_agg(z.t, ' | ')) into v_pq from (
      select x t from pipeline.coverage_course_pages g,
             jsonb_array_elements_text(case when jsonb_typeof(g.candidates->'intake_context') = 'array' then g.candidates->'intake_context' else '[]'::jsonb end) x
       where g.course_id = r.course_id and (g.url = v_url or g.candidates->>'final_url' = v_url)
      union all
      select f.quote from pipeline.field_enrich_items f
       where f.course_id = r.course_id and f.field = 'intakes' and f.state = 'filled' and f.evidence_id = r.evidence_id and nullif(btrim(f.quote), '') is not null) z;
    -- "Semester One", "first semester" and "semester 1" are the same period (as security.enrich_parse_intake_periods_v1)
    v_pq := regexp_replace(regexp_replace(regexp_replace(coalesce(v_pq, ''), '\mone\M|\mfirst\M', '1', 'g'), '\mtwo\M|\msecond\M', '2', 'g'), '\mthree\M|\mthird\M', '3', 'g');
    select array_agg(distinct s.period) into v_named from security.calendar_dated_periods_v1(r.provider_id) s
     where s.kind = 'start' and s.period ~ '^[a-z][a-z _-]*[0-9]+$'
       and v_pq ~ ('\m' || regexp_replace(s.period, '[ _-]+', '[ _-]*', 'g') || '\M');
    if v_named is null then
      outcome := 'skipped'; start_precision := 'month';
      reason := case when v_pq = '' then 'no stored reading of the page''s intake wording (month only)'
                     else 'the course page names no study period of the calendar (month only)' end;
      return next; continue;
    end if;
    -- the next start of a named period in this month, on or after today; its year printed in the period's calendar quote or on the page
    select min(s.year) into v_year from security.calendar_dated_periods_v1(r.provider_id) s
     where s.kind = 'start' and s.period = any (v_named) and s.month = v_m and s.year is not null
       and (s.quote ~ ('\m' || s.year || '\M') or v_pq ~ ('\m' || s.year || '\M'))
       and (s.on_date >= v_today or (s.on_date is null and make_date(s.year, s.month, 1) >= date_trunc('month', v_today)::date))
       and (r.intake_year is null or s.year = r.intake_year);
    if v_year is null then
      outcome := 'skipped';
      reason := case when r.intake_year is not null then 'the calendar prints no start of the named period in the intake''s own year'
                     when exists (select 1 from security.calendar_dated_periods_v1(r.provider_id) s where s.kind = 'start' and s.period = any (v_named) and s.month = v_m
                                     and s.year is not null and (s.quote ~ ('\m' || s.year || '\M') or v_pq ~ ('\m' || s.year || '\M')))
                       then 'the named period''s starts in this month are past'
                     when exists (select 1 from security.calendar_dated_periods_v1(r.provider_id) s where s.kind = 'start' and s.period = any (v_named) and s.month = v_m)
                       then 'the year of the named period is not printed (month only)'
                     else 'the named period does not start in this month' end;
      start_precision := 'month'; return next; continue;
    end if;
    select array_agg(distinct s.on_date) filter (where s.on_date is not null), array_agg(distinct s.period), min(s.quote)
      into v_starts, v_pers, v_sq
      from security.calendar_dated_periods_v1(r.provider_id) s where s.kind = 'start' and s.period = any (v_named) and s.month = v_m and s.year = v_year
       and (s.quote ~ ('\m' || s.year || '\M') or v_pq ~ ('\m' || s.year || '\M'));
    periods := v_pers; start_quote := v_sq;
    v_start := case when cardinality(v_starts) = 1 then v_starts[1] end;
    start_precision := case when v_start is not null then 'day' else 'year' end;
    if cardinality(v_starts) > 1 then reason := 'two start days in this month: year only'; end if;
    -- the deadline of the matched period(s): one dated "applications close" before the start
    select array_agg(distinct s.on_date), min(s.quote) into v_dl, v_dq
      from security.calendar_dated_periods_v1(r.provider_id) s
     where s.kind = 'deadline' and s.period = any (v_pers) and s.on_date is not null
       and s.on_date <= coalesce(v_start, make_date(v_year, v_m, 1)) and s.on_date >= coalesce(v_start, make_date(v_year, v_m, 1)) - v_max_before;
    select min(s.rolling_text) into v_roll from security.calendar_dated_periods_v1(r.provider_id) s where s.kind = 'rolling' and s.period = any (v_pers);
    if cardinality(v_dl) = 1 then deadline_kind := 'date'; new_deadline := v_dl[1]; deadline_quote := v_dq;
    elsif v_roll is not null then deadline_kind := 'rolling'; deadline_text := v_roll; deadline_quote := v_roll;
    else deadline_kind := 'not_stated'; end if;
    -- only empty columns are filled
    new_year := case when r.intake_year is null then v_year end;
    new_start := case when r.start_date is null then v_start end;
    new_deadline := case when r.application_deadline is null then new_deadline end;
    outcome := case when new_year is not null or new_start is not null or new_deadline is not null then 'filled' else 'nothing_new' end;
    return next;
  end loop;
end $_$;


ALTER FUNCTION "security"."intake_dates_plan_v1"("p_course_ids" "uuid"[], "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_dates_plan_v1"("p_course_ids" "uuid"[], "p_limit" integer) IS 'CF-247 intake dates (Platform Admin 2 Nov 2026 11:10 §2): read-only plan of what each active month intake row would gain from the provider''s approved calendar (year, start date, deadline), with the reason when it gains nothing. E16 page check, manual locks and holds respected; only empty columns; never another year. Settings intake_dates.deadline_max_days_before, batch.intake_dates_apply.';



CREATE OR REPLACE FUNCTION "security"."intake_dates_plan_v2"("p_course_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_limit" integer DEFAULT NULL::integer) RETURNS TABLE("intake_id" "uuid", "course_id" "uuid", "provider_id" "uuid", "proposal_id" "uuid", "outcome" "text", "reason" "text", "periods" "text"[], "new_year" integer, "new_start" "date", "new_deadline" "date", "start_precision" "text", "deadline_kind" "text", "deadline_text" "text", "start_quote" "text", "deadline_quote" "text", "before_value" "jsonb", "page_quote" "text", "calendar_evidence_id" "uuid", "calendar_url" "text", "rule" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_lists boolean := security.pipeline_num_v1('intake_dates.name_period_lists', 0) = 1;
  v_rule constant text := case when v_lists then 'named-period-pairs-v2' else 'named-period-v2' end;  -- fixed: the name of this rule in the record, by mode
  v_today date := (now() at time zone 'Australia/Melbourne')::date;  -- fixed: the calendar day in Australia (month roll-over)
  v_max_before int := security.pipeline_num_v1('intake_dates.deadline_max_days_before', 366)::int;
  v_limit int := coalesce(p_limit, security.pipeline_num_v1('batch.intake_dates_apply', 200)::int);
  r record; v_m int; v_prop uuid; v_year int; v_starts date[]; v_start date; v_pers text[]; v_sq text; v_dl date[]; v_dq text; v_roll text; v_url text; v_chk jsonb;
  v_raw text; v_pq text; v_named text[];
begin
  for r in
    select i.id, i.course_id, c.provider_id, i.intake_label, i.intake_year, i.start_date, i.application_deadline, i.evidence_id
      from catalogue.course_intakes i join catalogue.courses c on c.id = i.course_id
     where i.status = 'active' and c.lifecycle_status = 'active'
       and (p_course_ids is null or i.course_id = any (p_course_ids))
       and (i.intake_year is null or i.start_date is null or i.application_deadline is null)
       and exists (select 1 from pipeline.provider_policy_proposals p where p.provider_id = c.provider_id and p.kind = 'intake_calendar' and p.status = 'approved')
       -- each row once for each approved calendar under this rule; a row an earlier rule filled is not looked at again for that calendar
       and not exists (select 1 from pipeline.course_intake_dates d where d.intake_id = i.id
                          and d.proposal_id is not distinct from (select p.id from pipeline.provider_policy_proposals p where p.provider_id = c.provider_id and p.kind = 'intake_calendar' and p.status = 'approved'
                                                                   order by p.decided_at desc nulls last, p.created_at desc limit 1)
                          and (d.rule is not distinct from v_rule or d.outcome = 'filled'))
     order by i.course_id, i.id
     limit v_limit
  loop
    intake_id := r.id; course_id := r.course_id; provider_id := r.provider_id; periods := null; new_year := null; new_start := null; new_deadline := null;
    start_precision := null; deadline_kind := null; deadline_text := null; start_quote := null; deadline_quote := null; reason := null;
    page_quote := null; calendar_evidence_id := null; calendar_url := null; rule := v_rule;
    before_value := jsonb_build_object('year', r.intake_year, 'start_date', r.start_date, 'application_deadline', r.application_deadline);
    select p.id, p.evidence_id, p.url into v_prop, calendar_evidence_id, calendar_url from pipeline.provider_policy_proposals p
     where p.provider_id = r.provider_id and p.kind = 'intake_calendar' and p.status = 'approved'
     order by p.decided_at desc nulls last, p.created_at desc limit 1;
    proposal_id := v_prop;
    v_m := array_position(array['january','february','march','april','may','june','july','august','september','october','november','december'], lower(btrim(r.intake_label)));
    -- the guards: a person's lock or hold, and the E16 page check on the page the month came from
    if exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = r.course_id and k.field in ('intakes', 'intake')) then
      outcome := 'skipped'; reason := 'intakes locked by hand'; return next; continue;
    end if;
    if security.course_held_v1(r.course_id) then outcome := 'skipped'; reason := 'course held'; return next; continue; end if;
    if v_m is null then outcome := 'skipped'; reason := 'intake is not a month'; return next; continue; end if;
    select e.source_url into v_url from pipeline.evidence_artifacts e where e.id = r.evidence_id;
    if v_url is null then outcome := 'skipped'; reason := 'no page behind the intake'; return next; continue; end if;
    if security.page_refused_v1(r.course_id, v_url) then outcome := 'skipped'; reason := 'page refused for this course'; return next; continue; end if;
    v_chk := security.course_page_check_v1(r.course_id, v_url, null, null);
    if v_chk->>'verdict' is distinct from 'pass' then
      outcome := 'skipped'; reason := 'page not proved to be the course''s own (E16 ' || coalesce(v_chk->>'verdict', 'no verdict') || ')'; return next; continue;
    end if;
    -- Named period only (Platform Admin 2 Nov 2026 ~14:50): the period must be named in the stored reading of the page that gave the intake;
    -- explicit pairs and lists (23:24) count only with intake_dates.name_period_lists at 1. No month-to-period inference; a label alone gives no date.
    v_raw := security.intake_page_wording_v1(r.course_id, r.evidence_id, v_url);
    page_quote := left(v_raw, 600);
    -- a month the page only excludes ("throughout the year excluding January & December") is not an intake: nothing is filled for it
    if security.intake_month_negated_v1(v_raw, v_m) then
      outcome := 'skipped'; reason := 'the page excludes this month (listed for withdrawal)'; return next; continue;
    end if;
    v_pq := security.intake_period_text_v1(v_raw, v_lists);
    select array_agg(distinct s.period) into v_named from security.calendar_dated_periods_v1(r.provider_id) s
     where s.kind = 'start' and s.period ~ '^[a-z][a-z _-]*[0-9]+$'
       and v_pq ~ ('\m' || regexp_replace(s.period, '[ _-]+', '[ _-]*', 'g') || '\M');
    if v_named is null then
      outcome := 'skipped'; start_precision := 'month';
      reason := case when coalesce(v_raw, '') = '' then 'no stored reading of the page''s intake wording (month only)'
                     else 'the course page names no study period of the calendar (month only)' end;
      return next; continue;
    end if;
    -- the next start of a named period in this month, on or after today; its year printed in the period's calendar quote or on the page
    select min(s.year) into v_year from security.calendar_dated_periods_v1(r.provider_id) s
     where s.kind = 'start' and s.period = any (v_named) and s.month = v_m and s.year is not null
       and (s.quote ~ ('\m' || s.year || '\M') or v_pq ~ ('\m' || s.year || '\M'))
       and (s.on_date >= v_today or (s.on_date is null and make_date(s.year, s.month, 1) >= date_trunc('month', v_today)::date))
       and (r.intake_year is null or s.year = r.intake_year);
    if v_year is null then
      outcome := 'skipped';
      reason := case when r.intake_year is not null then 'the calendar prints no start of the named period in the intake''s own year'
                     when exists (select 1 from security.calendar_dated_periods_v1(r.provider_id) s where s.kind = 'start' and s.period = any (v_named) and s.month = v_m
                                     and s.year is not null and (s.quote ~ ('\m' || s.year || '\M') or v_pq ~ ('\m' || s.year || '\M')))
                       then 'the named period''s starts in this month are past'
                     when exists (select 1 from security.calendar_dated_periods_v1(r.provider_id) s where s.kind = 'start' and s.period = any (v_named) and s.month = v_m)
                       then 'the year of the named period is not printed (month only)'
                     else 'the named period does not start in this month' end;
      start_precision := 'month'; return next; continue;
    end if;
    select array_agg(distinct s.on_date) filter (where s.on_date is not null), array_agg(distinct s.period), min(s.quote)
      into v_starts, v_pers, v_sq
      from security.calendar_dated_periods_v1(r.provider_id) s where s.kind = 'start' and s.period = any (v_named) and s.month = v_m and s.year = v_year
       and (s.quote ~ ('\m' || s.year || '\M') or v_pq ~ ('\m' || s.year || '\M'));
    periods := v_pers; start_quote := v_sq;
    v_start := case when cardinality(v_starts) = 1 then v_starts[1] end;
    start_precision := case when v_start is not null then 'day' else 'year' end;
    if cardinality(v_starts) > 1 then reason := 'two start days in this month: year only'; end if;
    -- the deadline of the matched period(s): one dated "applications close" before the start
    select array_agg(distinct s.on_date), min(s.quote) into v_dl, v_dq
      from security.calendar_dated_periods_v1(r.provider_id) s
     where s.kind = 'deadline' and s.period = any (v_pers) and s.on_date is not null
       and s.on_date <= coalesce(v_start, make_date(v_year, v_m, 1)) and s.on_date >= coalesce(v_start, make_date(v_year, v_m, 1)) - v_max_before;
    select min(s.rolling_text) into v_roll from security.calendar_dated_periods_v1(r.provider_id) s where s.kind = 'rolling' and s.period = any (v_pers);
    if cardinality(v_dl) = 1 then deadline_kind := 'date'; new_deadline := v_dl[1]; deadline_quote := v_dq;
    elsif v_roll is not null then deadline_kind := 'rolling'; deadline_text := v_roll; deadline_quote := v_roll;
    else deadline_kind := 'not_stated'; end if;
    -- only empty columns are filled
    new_year := case when r.intake_year is null then v_year end;
    new_start := case when r.start_date is null then v_start end;
    new_deadline := case when r.application_deadline is null then new_deadline end;
    outcome := case when new_year is not null or new_start is not null or new_deadline is not null then 'filled' else 'nothing_new' end;
    return next;
  end loop;
end $_$;


ALTER FUNCTION "security"."intake_dates_plan_v2"("p_course_ids" "uuid"[], "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_dates_plan_v2"("p_course_ids" "uuid"[], "p_limit" integer) IS 'CF-247 intake dates, named period only (Platform Admin 2 Nov 2026 ~14:50), with explicit pairs and lists only when intake_dates.name_period_lists is 1 (23:24, off by default): read-only plan of what each active month intake would gain from the approved calendar, with the page wording and calendar document behind each value, or the reason it gains nothing. Replaces security.intake_dates_plan_v1.';



CREATE OR REPLACE FUNCTION "security"."intake_dates_plan_v3"("p_course_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_limit" integer DEFAULT NULL::integer) RETURNS TABLE("intake_id" "uuid", "course_id" "uuid", "provider_id" "uuid", "proposal_id" "uuid", "outcome" "text", "reason" "text", "periods" "text"[], "new_year" integer, "new_start" "date", "new_deadline" "date", "start_precision" "text", "deadline_kind" "text", "deadline_text" "text", "start_quote" "text", "deadline_quote" "text", "before_value" "jsonb", "page_quote" "text", "calendar_evidence_id" "uuid", "calendar_url" "text", "rule" "text", "calendar_set" "text", "inputs_fp" "text", "next_action" "text", "next_revisit_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_lists boolean := security.pipeline_num_v1('intake_dates.name_period_lists', 0) = 1;
  v_unique boolean := security.pipeline_num_v1('intake_dates.month_unique_match', 0) = 1;
  -- Decision 271 (Rule B): providers listed here take the nearest main-teaching start (security.intake_nearest_start_v1); empty: none
  v_near uuid[] := coalesce((select array_agg(x::uuid) from pipeline.platform_toolset_settings s, jsonb_array_elements_text(s.value) x
                              where s.toolset_key = 'pipeline' and s.key = 'intake_dates.nearest_start_providers' and jsonb_typeof(s.value) = 'array'), '{}');
  v_near_days int := security.pipeline_num_v1('intake_dates.nearest_start_days', 35)::int;
  -- 13 Nov 2026 (Platform Admin decision, Intake Process Record §14): providers listed here take a named period's next start in the intake's month even when
  -- another named period starts sooner (Canterbury, Massey: "Semester 1 or 2 (February or July)"); empty: none
  v_next uuid[] := coalesce((select array_agg(x::uuid) from pipeline.platform_toolset_settings s, jsonb_array_elements_text(s.value) x
                              where s.toolset_key = 'pipeline' and s.key = 'intake_dates.next_cycle_period_providers' and jsonb_typeof(s.value) = 'array'), '{}');
  v_settings text := 'lists=' || v_lists::text || ';unique=' || v_unique::text || ';rules=fair-evidence-1';
  v_today date := (now() at time zone 'Australia/Melbourne')::date;  -- fixed: the calendar day in Australia (month roll-over)
  v_max_before int := security.pipeline_num_v1('intake_dates.deadline_max_days_before', 366)::int;
  v_limit int := coalesce(p_limit, security.pipeline_num_v1('batch.intake_dates_apply', 200)::int);
  -- direction 5 Nov 2026 15:50 §3: rows taken round by round, this many a university a round (focus rank first within a round)
  v_share int := greatest(1, security.pipeline_num_v1('intake_dates.provider_share', 25)::int);
  -- Platform Admin 5 Nov 2026 18:00: the approved pilot (run_now.cohort_top_au_universities) takes up to this many rows of each batch
  v_pilot uuid[] := case when p_course_ids is null then (select coalesce(array_agg((e->>'id')::uuid), '{}') from jsonb_array_elements(security.intake_ui_scopes_v1()) e) else '{}' end;
  v_pilot_rows int := floor(coalesce(p_limit, security.pipeline_num_v1('batch.intake_dates_apply', 200)::int) * least(100, greatest(0, security.pipeline_num_v1('intake_dates.pilot_batch_share', 60))) / 100.0)::int;
  -- P0 IQ-00313: a calendar date is taken only within this many months of today
  v_ahead int := greatest(1, security.pipeline_num_v1('intake_dates.max_months_ahead', 18)::int);
  v_page_admit boolean := security.pipeline_num_v1('intake_dates.page_date_admit', 0) = 1;  -- F-INT D1: a date printed on the course page, default off
  v_pd jsonb;
  r record; v_m int; v_year int; v_starts date[]; v_start date; v_pers text[]; v_sq text; v_dl date[]; v_dq text; v_roll text; v_url text; v_chk jsonb;
  v_raw text; v_pq text; v_named text[]; v_cal jsonb := '[]'::jsonb; v_cal_provider uuid; v_n int; v_page_dates date[]; v_intl boolean;
begin
  for r in
    with prov as materialized (
      select distinct c.provider_id from catalogue.course_intakes i join catalogue.courses c on c.id = i.course_id
       where i.status = 'active' and c.lifecycle_status = 'active' and (p_course_ids is null or i.course_id = any (p_course_ids))
         and (i.intake_year is null or i.start_date is null or i.application_deadline is null)
         and exists (select 1 from pipeline.provider_policy_proposals p where p.provider_id = c.provider_id and p.kind = 'intake_calendar' and p.status = 'approved')),
    -- direction 5 Nov 2026 15:50 §3: when each university was last served, so a round that does not fit the batch starts with the one waiting longest
    sets as materialized (select prov.provider_id, security.calendar_set_v1(prov.provider_id) s,
                                 (select max(d.applied_at) from pipeline.course_intake_dates d where d.provider_id = prov.provider_id) served from prov)
    select q.id, q.course_id, q.provider_id, q.intake_label, q.intake_year, q.start_date, q.application_deadline, q.evidence_id, q.course_url, q.cal_set, q.fp, q.pdready, q.pdsfx from (
    select q0.*, row_number() over (partition by q0.pilot order by q0.rnd, q0.served nulls first, q0.frank nulls last, q0.provider_id, q0.course_id, q0.id) pilot_seq from (
    select i.id, i.course_id, c.provider_id, i.intake_label, i.intake_year, i.start_date, i.application_deadline, i.evidence_id, c.course_url, sets.s cal_set,
           security.intake_inputs_fp_v1(sets.s, i.evidence_id, c.course_url, v_settings || case when c.provider_id = any (v_near) then ';near=' || v_near_days else '' end || case when c.provider_id = any (v_next) then ';nextcycle=1' else '' end) fp, pd.ready pdready, pd.sfx pdsfx,
           ceil(row_number() over (partition by c.provider_id, pd.ready order by i.course_id, i.id)::numeric / v_share) rnd, sets.served, f.rank frank, c.provider_id = any (v_pilot) pilot
      from catalogue.course_intakes i join catalogue.courses c on c.id = i.course_id join sets on sets.provider_id = c.provider_id
      -- F-INT (10 Nov 2026): while intake_dates.page_date_admit is 1, an undated intake whose stored wording prints a dated candidate for its month is looked at now and taken first
      -- (a row the page route has already filled keeps the suffix, so its fingerprint is the same before and after the fill and it is not looked at again for that)
      cross join lateral (select r0.ready, r0.ready or (v_page_admit and i.start_date is not null and exists (select 1 from pipeline.course_intake_dates k0 where k0.intake_id = i.id and k0.rule = 'page-date-v1')) as sfx
                            from (select case when v_page_admit and i.start_date is null then security.intake_page_date_hint_v1(i.course_id, i.evidence_id, i.intake_label) else false end as ready) r0) pd
      left join pipeline.enrich_focus_providers f on f.provider_id = c.provider_id and f.in_focus
     where i.status = 'active' and c.lifecycle_status = 'active'
       and (p_course_ids is null or i.course_id = any (p_course_ids))
       and (i.intake_year is null or i.start_date is null or i.application_deadline is null)
       -- decision §7.9, §8: looked at again only when an input changed or the row's revisit time passed
       and not exists (select 1 from pipeline.course_intake_dates d where d.intake_id = i.id
                          and d.inputs_fp is not distinct from security.intake_inputs_fp_v1(sets.s, i.evidence_id, c.course_url, v_settings || case when c.provider_id = any (v_near) then ';near=' || v_near_days else '' end || case when c.provider_id = any (v_next) then ';nextcycle=1' else '' end || ';wording=' || security.intake_wording_fp_v1(i.course_id, i.evidence_id) || case when pd.sfx then ';pagedate=1' else '' end)
                          and (d.next_revisit_at is null or d.next_revisit_at > now()))
    ) q0) q
     -- the pilot's reserved rows first, then every other provider (focus first, longest waiting first), then any pilot rows beyond its share
     order by case when q.pdready then 0 when q.pilot and q.pilot_seq <= v_pilot_rows then 1 when not q.pilot then 2 else 3 end,
              q.rnd, (q.frank is null), q.served nulls first, q.frank nulls last, q.provider_id, q.course_id, q.id  -- focus universities first within a round (direction 5 Nov 2026 15:50 §3)
     limit v_limit
  loop
    intake_id := r.id; course_id := r.course_id; provider_id := r.provider_id; periods := null; new_year := null; new_start := null; new_deadline := null;
    outcome := null; start_precision := null; deadline_kind := null; deadline_text := null; start_quote := null; deadline_quote := null; reason := null; proposal_id := null;
    page_quote := null; calendar_evidence_id := null; calendar_url := null; rule := 'calendar-v3'; calendar_set := r.cal_set; inputs_fp := security.intake_inputs_fp_v1(r.cal_set, r.evidence_id, r.course_url, v_settings || case when r.provider_id = any (v_near) then ';near=' || v_near_days else '' end || case when r.provider_id = any (v_next) then ';nextcycle=1' else '' end || ';wording=' || security.intake_wording_fp_v1(r.course_id, r.evidence_id) || case when r.pdsfx then ';pagedate=1' else '' end);
    before_value := jsonb_build_object('year', r.intake_year, 'start_date', r.start_date, 'application_deadline', r.application_deadline);
    if v_cal_provider is distinct from r.provider_id then
      -- P0 IQ-00313: a calendar value recorded as rejected is never used again (provider, reading, quote, year)
      v_cal := coalesce((select jsonb_agg(to_jsonb(s)) from security.calendar_dated_periods_v2(r.provider_id) s
                          where not exists (select 1 from pipeline.intake_date_rejections j
                                             where j.provider_id = r.provider_id and j.proposal_id is not distinct from s.proposal_id
                                               and j.quote is not distinct from s.quote and j.year is not distinct from s.year)), '[]'::jsonb);
      v_cal_provider := r.provider_id;
    end if;
    -- a university whose approved calendars are all set aside, or give nothing, has no valid calendar
    if r.cal_set like 'none:%' then
      outcome := 'skipped';
      reason := case when split_part(r.cal_set, ':', 2)::int > 0 then 'no valid academic calendar: the approved calendars are set aside (not the main teaching calendar)'
                     else 'no valid academic calendar' end;
      next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := security.intake_revisit_at_v1(next_action);
      return next; continue;
    end if;
    v_m := array_position(array['january','february','march','april','may','june','july','august','september','october','november','december'], lower(btrim(r.intake_label)));
    if exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = r.course_id and k.field in ('intakes', 'intake')) then
      outcome := 'skipped'; reason := 'intakes locked by hand';
    elsif security.course_held_v1(r.course_id) then outcome := 'skipped'; reason := 'course held';
    elsif v_m is null then outcome := 'skipped'; reason := 'intake is not a month';
    end if;
    if outcome = 'skipped' then
      next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := security.intake_revisit_at_v1(next_action); return next; outcome := null; continue;
    end if;
    select e.source_url into v_url from pipeline.evidence_artifacts e where e.id = r.evidence_id;
    if v_url is null then reason := 'no page behind the intake';
    elsif security.page_refused_v1(r.course_id, v_url) then reason := 'page refused for this course';
    else
      v_chk := security.course_page_check_v1(r.course_id, v_url, null, null);
      if v_chk->>'verdict' is distinct from 'pass' then reason := 'page not proved to be the course''s own (E16 ' || coalesce(v_chk->>'verdict', 'no verdict') || ')'; end if;
    end if;
    if reason is not null then
      outcome := 'skipped'; next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := security.intake_revisit_at_v1(next_action);
      return next; outcome := null; continue;
    end if;
    v_raw := security.intake_page_wording_v1(r.course_id, r.evidence_id, v_url);
    page_quote := left(v_raw, 600);
    if security.intake_month_negated_v1(v_raw, v_m) then
      outcome := 'skipped'; reason := 'the page excludes this month (listed for withdrawal)';
      next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := null; return next; outcome := null; continue;
    end if;
    v_pq := security.intake_period_text_canonical_v1(security.intake_period_text_v1(v_raw, v_lists));
    select array_agg(distinct s.period) into v_named
      from jsonb_to_recordset(v_cal) s(period text, kind text)
     where s.kind = 'start' and s.period ~ '^[a-z][a-z _-]*[0-9]+$' and v_pq ~ ('\m' || regexp_replace(s.period, '[ _-]+', '[ _-]*', 'g') || '\M');
    -- F-INT D1 (setting intake_dates.page_date_admit, default off): where the calendar route finds no named study period, the single full date the course page
    -- prints for this month is admitted when it is corroborated (security.intake_page_date_v1) and the course-specific offering gate passes
    if v_page_admit and v_named is null and r.start_date is null and coalesce(v_raw, '') <> '' then
      v_pd := security.intake_page_date_v1(r.provider_id, r.id, r.course_id, r.evidence_id, v_url, v_m, r.intake_year, v_cal, v_today, v_ahead);
      if (v_pd->>'admit')::boolean then
        v_start := (v_pd->>'date')::date; v_year := extract(year from v_start)::int;
        reason := security.intake_course_applicability_v1(coalesce(v_pd->>'gate', v_raw), v_m, v_year, v_cal, false, null, null);
        if reason is null then
          rule := 'page-date-v1'; start_precision := 'day'; start_quote := v_pd->>'quote'; deadline_kind := 'not_stated';
          periods := case when jsonb_typeof(v_pd->'periods') = 'array' then array(select jsonb_array_elements_text(v_pd->'periods')) end;
          proposal_id := nullif(v_pd->>'proposal_id', '')::uuid;
          calendar_url := coalesce(v_pd->>'calendar_url', v_url); calendar_evidence_id := coalesce(nullif(v_pd->>'calendar_evidence_id', '')::uuid, r.evidence_id);
          new_year := case when r.intake_year is null then v_year end; new_start := v_start;
          outcome := 'filled';
          next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := security.intake_revisit_at_v1(next_action);
          return next; outcome := null; continue;
        end if;
        outcome := 'skipped'; start_precision := 'month'; start_quote := null;
        next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := security.intake_revisit_at_v1(next_action);
        return next; outcome := null; continue;
      elsif v_pd->>'skip' is not null and not v_unique then   -- with the unique-month path on (intake_dates.month_unique_match) a page that is not admitted falls through to it, as before
        outcome := 'skipped'; start_precision := 'month'; reason := v_pd->>'skip';
        next_action := case when reason like 'withdrawn:%' then 'human_decision_required' else security.intake_next_action_v1(outcome, reason, false) end;
        next_revisit_at := case when reason like 'withdrawn:%' then null else security.intake_revisit_at_v1(next_action) end;
        return next; outcome := null; continue;
      end if;
    end if;
    -- F-INT (10 Nov 2026): a row that already holds its start date and year (admitted from the course page or the calendar) and whose page names no period has nothing new to add; it is kept
    -- as nothing_new with the rule, quote and source it was admitted with, not overwritten as skipped (that erased the quote of an admitted date the next time its fingerprint changed)
    if v_named is null and r.start_date is not null and r.intake_year is not null then
      select d.rule, d.start_quote, d.proposal_id, d.calendar_url, d.calendar_evidence_id, d.periods into rule, start_quote, proposal_id, calendar_url, calendar_evidence_id, periods
        from pipeline.course_intake_dates d where d.intake_id = r.id and d.outcome in ('filled', 'nothing_new');
      rule := coalesce(rule, 'calendar-v3'); outcome := 'nothing_new'; start_precision := 'day'; deadline_kind := 'not_stated';
      next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := null;   -- nothing to look at again until an input changes (the fingerprint)
      return next; outcome := null; continue;
    end if;
    if v_named is null then
      if coalesce(v_raw, '') = '' then
        outcome := 'skipped'; start_precision := 'month'; reason := 'no stored reading of the page''s intake wording (month only)';
        next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := null; return next; outcome := null; continue;
      end if;
      -- Decision 271 (Rule B), listed providers only (intake_dates.nearest_start_providers): the one main-teaching start in the stated month, else the one
      -- within intake_dates.nearest_start_days after it; the withdrawn-value and course offering checks apply as on the page-date route
      if r.provider_id = any (v_near) then
        v_pd := security.intake_nearest_start_v1(r.course_id, r.id, v_m, r.intake_year, v_raw, v_cal, v_today, v_ahead, v_near_days);
        if coalesce((v_pd->>'admit')::boolean, false) then
          v_start := (v_pd->>'date')::date; v_year := extract(year from v_start)::int;
          if exists (select 1 from pipeline.course_intake_date_events w where w.intake_id = r.id and w.outcome = 'withdrawn'
                        and (w.before_value->>'start_date')::date is not distinct from v_start) then
            outcome := 'skipped'; start_precision := 'month';
            reason := 'withdrawn: this value was rejected earlier and is not admitted again (a person decides)';
            next_action := 'human_decision_required'; next_revisit_at := null; return next; outcome := null; continue;
          end if;
          reason := security.intake_course_applicability_v1(v_raw, v_m, coalesce((v_pd->>'target_year')::int, v_year), v_cal, false, null, null);
          if reason is null then
            rule := 'calendar-v3-nearest-start'; start_precision := 'day'; start_quote := v_pd->>'quote'; deadline_kind := 'not_stated';
            periods := case when v_pd->>'period' is not null then array[v_pd->>'period'] end;
            proposal_id := nullif(v_pd->>'proposal_id', '')::uuid;
            calendar_url := v_pd->>'calendar_url'; calendar_evidence_id := nullif(v_pd->>'calendar_evidence_id', '')::uuid;
            new_year := case when r.intake_year is null then v_year end; new_start := v_start;
            outcome := 'filled';
            next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := security.intake_revisit_at_v1(next_action);
            return next; outcome := null; continue;
          end if;
          outcome := 'skipped'; start_precision := 'month'; start_quote := null;
          next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := security.intake_revisit_at_v1(next_action);
          return next; outcome := null; continue;
        end if;
        outcome := 'skipped'; start_precision := 'month'; reason := coalesce(v_pd->>'skip', 'the course page names no study period of the calendar (month only)');
        next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := security.intake_revisit_at_v1(next_action);
        return next; outcome := null; continue;
      end if;
      if not v_unique then
        outcome := 'skipped'; start_precision := 'month'; reason := 'the course page names no study period of the calendar (month only)';
        next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := null; return next; outcome := null; continue;
      end if;
      -- decision §3: the month takes the date only when exactly one eligible teaching start falls in that month of the intake's year
      select min(s.year) into v_year from jsonb_to_recordset(v_cal) s(kind text, year int, month int, on_date date, year_ok boolean)
       where s.kind = 'start' and s.month = v_m and s.year is not null
         and (s.year_ok or v_pq ~ ('\m' || s.year || '\M'))
         and (s.on_date >= v_today or (s.on_date is null and make_date(s.year, s.month, 1) >= date_trunc('month', v_today)::date))
         and (r.intake_year is null or s.year = r.intake_year);
      if v_year is null then
        outcome := 'skipped'; start_precision := 'month';
        reason := case when r.intake_year is not null then 'the calendar prints no start in this month of the intake''s own year (month only)'
                       when exists (select 1 from jsonb_to_recordset(v_cal) s(kind text, month int, year int, year_ok boolean) where s.kind = 'start' and s.month = v_m and s.year_ok)
                         then 'the calendar''s starts in this month are past (month only)'
                       when exists (select 1 from jsonb_to_recordset(v_cal) s(kind text, month int) where s.kind = 'start' and s.month = v_m)
                         then 'the calendar does not print the year of its start in this month (month only)'
                       else 'the calendar has no future start in this month (month only)' end;
        next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := security.intake_revisit_at_v1(next_action);
        return next; outcome := null; continue;
      end if;
      -- one entry per period (its dated start when any calendar dates it); two periods, or two dates, are ambiguous
      select count(distinct coalesce(z.pd::text, z.period)), array_agg(distinct z.period) into v_n, v_named
        from (select s.period, min(s.on_date) pd from jsonb_to_recordset(v_cal) s(kind text, period text, year int, month int, on_date date, year_ok boolean)
               where s.kind = 'start' and s.month = v_m and s.year = v_year and (s.year_ok or v_pq ~ ('\m' || s.year || '\M')) group by s.period) z;
      if v_n > 1 then
        outcome := 'skipped'; start_precision := 'month'; periods := v_named;
        reason := 'several study periods start in this month (month only)';
        next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := null; return next; outcome := null; continue;
      end if;
      rule := 'calendar-v3-unique-month';
    end if;
    -- the next start of the period(s) in this month, on or after today, in the intake's own year when it holds one
    select min(s.year) into v_year from jsonb_to_recordset(v_cal) s(kind text, period text, year int, month int, on_date date, year_ok boolean)
     where s.kind = 'start' and s.period = any (v_named) and s.month = v_m and s.year is not null
       and (s.year_ok or v_pq ~ ('\m' || s.year || '\M'))
       and (s.on_date >= v_today or (s.on_date is null and make_date(s.year, s.month, 1) >= date_trunc('month', v_today)::date))
       and (r.intake_year is null or s.year = r.intake_year);
    if v_year is null then
      outcome := 'skipped'; start_precision := 'month';
      reason := case when r.intake_year is not null then 'the calendar prints no start of the named period in the intake''s own year'
                     when exists (select 1 from jsonb_to_recordset(v_cal) s(kind text, period text, year int, month int, year_ok boolean) where s.kind = 'start' and s.period = any (v_named)
                                     and s.month = v_m and s.year is not null and (s.year_ok or v_pq ~ ('\m' || s.year || '\M')))
                       then 'the named period''s starts in this month are past'
                     when exists (select 1 from jsonb_to_recordset(v_cal) s(kind text, period text, month int) where s.kind = 'start' and s.period = any (v_named) and s.month = v_m)
                       then 'the year of the named period is not printed (month only)'
                     else 'the named period does not start in this month' end;
      next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := security.intake_revisit_at_v1(next_action);
      return next; outcome := null; continue;
    end if;
    -- 11 Nov 2026 (F-INT): the named period's next start must be the one in this month. When the period starts sooner in another month (Monash "Semester one
    -- (February)": Semester 1 = 1 Mar 2027, its February start is 28 Feb 2028), a later year's start in this month is never taken. A provider listed for Rule B
    -- takes the nearest start by Rule B (Decision 271); any other is held.
    select min(s.on_date) into v_start from jsonb_to_recordset(v_cal) s(kind text, period text, on_date date, year_ok boolean)
     where s.kind = 'start' and s.period = any (v_named) and s.year_ok and s.on_date >= v_today and s.on_date < make_date(v_year, v_m, 1)
       -- §14: for a listed provider only a named period that itself starts in this month is checked, so Semester 1 starting sooner in February
       -- does not hold the July intake of Semester 2 (a period that starts sooner in another month still holds it, as for Monash)
       and (not (r.provider_id = any (v_next))
            or exists (select 1 from jsonb_to_recordset(v_cal) s2(kind text, period text, month int, year_ok boolean)
                        where s2.kind = 'start' and s2.period = s.period and s2.month = v_m and s2.year_ok));
    -- §14 item 4: an offering the course page ties to other years is never rolled into the next year's start
    if v_start is null and r.provider_id = any (v_next) and v_year > extract(year from v_today)::int
       and exists (select 1 from jsonb_to_recordset(v_cal) s3(kind text, period text, on_date date, year_ok boolean)
                    where s3.kind = 'start' and s3.period = any (v_named) and s3.year_ok and s3.on_date >= v_today and s3.on_date < make_date(v_year, v_m, 1))
       and coalesce(v_raw, '') ~ '\m20\d\d\M' and coalesce(v_raw, '') !~ ('\m' || v_year || '\M') then
      outcome := 'skipped'; start_precision := 'month'; periods := v_named; start_quote := null;
      reason := 'the course page names only other years for its intakes: the ' || v_year || ' start in this month is not taken (month only)';
      next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := security.intake_revisit_at_v1(next_action);
      return next; outcome := null; continue;
    end if;
    if v_start is not null then
      if r.provider_id = any (v_near) then
        v_pd := security.intake_nearest_start_v1(r.course_id, r.id, v_m, r.intake_year, v_raw, v_cal, v_today, v_ahead, v_near_days);
        if coalesce((v_pd->>'admit')::boolean, false)
           and not exists (select 1 from pipeline.course_intake_date_events w where w.intake_id = r.id and w.outcome = 'withdrawn'
                              and (w.before_value->>'start_date')::date is not distinct from (v_pd->>'date')::date) then
          reason := security.intake_course_applicability_v1(v_raw, v_m, coalesce((v_pd->>'target_year')::int, extract(year from (v_pd->>'date')::date)::int), v_cal, false, null, null);
          if reason is null then
            v_start := (v_pd->>'date')::date; v_year := extract(year from v_start)::int;
            rule := 'calendar-v3-nearest-start'; start_precision := 'day'; start_quote := v_pd->>'quote'; deadline_kind := 'not_stated';
            periods := case when v_pd->>'period' is not null then array[v_pd->>'period'] end;
            proposal_id := nullif(v_pd->>'proposal_id', '')::uuid;
            calendar_url := v_pd->>'calendar_url'; calendar_evidence_id := nullif(v_pd->>'calendar_evidence_id', '')::uuid;
            new_year := case when r.intake_year is null then v_year end; new_start := v_start;
            outcome := 'filled';
            next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := security.intake_revisit_at_v1(next_action);
            return next; outcome := null; continue;
          end if;
        end if;
      end if;
      outcome := 'skipped'; start_precision := 'month'; periods := v_named; start_quote := null;
      reason := 'the named period starts sooner in another month (' || v_start || '): a later year''s start in this month is not taken (month only)';
      next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := security.intake_revisit_at_v1(next_action);
      return next; outcome := null; continue;
    end if;
    -- P0 IQ-00313: the next dated start must lie within the horizon (intake_dates.max_months_ahead); a later one is a later cycle whose year is not proved
    if make_date(v_year, v_m, 1) > (date_trunc('month', v_today) + make_interval(months => v_ahead))::date then
      outcome := 'skipped'; start_precision := 'month';
      reason := 'the year of the named period is not printed for the next cycle: its next dated start is more than ' || v_ahead || ' months away (month only)';
      next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := security.intake_revisit_at_v1(next_action);
      return next; outcome := null; continue;
    end if;
    select array_agg(distinct s.on_date) filter (where s.on_date is not null), array_agg(distinct s.period), min(s.quote), min(s.proposal_id::text)::uuid, min(s.url), min(s.evidence_id::text)::uuid
      into v_starts, v_pers, v_sq, proposal_id, calendar_url, calendar_evidence_id
      from jsonb_to_recordset(v_cal) s(proposal_id uuid, kind text, period text, year int, month int, on_date date, quote text, url text, evidence_id uuid, year_ok boolean)
     where s.kind = 'start' and s.period = any (v_named) and s.month = v_m and s.year = v_year and (s.year_ok or v_pq ~ ('\m' || s.year || '\M'));
    periods := v_pers; start_quote := v_sq;
    v_start := case when cardinality(v_starts) = 1 then v_starts[1] end;
    -- P0 IQ-00313: a value withdrawn from this intake (the withdrawn event's before_value is the rejected value) is not admitted to it again
    if exists (select 1 from pipeline.course_intake_date_events w
                where w.intake_id = r.id and w.outcome = 'withdrawn'
                  and (w.before_value->>'year')::int is not distinct from v_year and (w.before_value->>'start_date')::date is not distinct from v_start) then
      outcome := 'skipped'; start_precision := 'month'; start_quote := null;
      reason := 'withdrawn: this value was rejected earlier and is not admitted again (a person decides)';
      next_action := 'human_decision_required'; next_revisit_at := null;
      return next; outcome := null; continue;
    end if;
    -- decision §3: no more specific course-level date may contradict it (a full date of this month and year printed on the course page)
    select array_agg(distinct make_date(v_year, v_m, m[1]::int)) into v_page_dates
      from regexp_matches(coalesce(v_raw, ''), '\m(\d{1,2})(?:st|nd|rd|th)?(?:\s+|-)' || (array['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'])[v_m] || '[a-z]*(?:,?\s+|-)' || v_year || '\M', 'gi') m
     where m[1]::int between 1 and 28 or (m[1]::int <= extract(day from (make_date(v_year, v_m, 1) + interval '1 month - 1 day'))::int);  -- fixed: the last day of the month
    if v_page_dates is not null and (v_start is null or not (v_start = all (v_page_dates))) then
      outcome := 'skipped'; start_precision := 'month';
      reason := 'the course page gives its own start date for this intake (' || array_to_string(v_page_dates, ', ') || ')';
      next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := null; return next; outcome := null; continue;
    end if;
    -- direction 5 Nov 2026 15:50 §1, §2: the course page must offer this intake, and a month-only match needs a calendar that applies to the course
    reason := security.intake_course_applicability_v1(v_raw, v_m, v_year, v_cal, rule = 'calendar-v3-unique-month', case when rule <> 'calendar-v3-unique-month' then v_pers end, v_pq);
    if reason is not null then
      outcome := 'skipped'; start_precision := 'month'; periods := v_pers; start_quote := null;
      next_action := security.intake_next_action_v1(outcome, reason, false); next_revisit_at := security.intake_revisit_at_v1(next_action);
      return next; outcome := null; continue;
    end if;
    start_precision := case when v_start is not null then 'day' else 'year' end;
    if cardinality(v_starts) > 1 then reason := 'two start days in this month: year only'; end if;
    -- the deadline of the matched period(s): one dated closing date before the start; one for international applicants first
    select bool_or(s.applies_to = 'international') into v_intl from jsonb_to_recordset(v_cal) s(kind text, period text, on_date date, applies_to text)
     where s.kind = 'deadline' and s.period = any (v_pers) and s.on_date is not null
       and s.on_date <= coalesce(v_start, make_date(v_year, v_m, 1)) and s.on_date >= coalesce(v_start, make_date(v_year, v_m, 1)) - v_max_before;
    select array_agg(distinct s.on_date), min(s.quote) into v_dl, v_dq
      from jsonb_to_recordset(v_cal) s(kind text, period text, on_date date, quote text, applies_to text)
     where s.kind = 'deadline' and s.period = any (v_pers) and s.on_date is not null
       and coalesce(s.applies_to, 'unstated') in ('international', 'all', 'unstated')
       and (not coalesce(v_intl, false) or s.applies_to = 'international')
       and s.on_date <= coalesce(v_start, make_date(v_year, v_m, 1)) and s.on_date >= coalesce(v_start, make_date(v_year, v_m, 1)) - v_max_before;
    select min(s.rolling_text) into v_roll from jsonb_to_recordset(v_cal) s(kind text, period text, rolling_text text) where s.kind = 'rolling' and s.period = any (v_pers);
    if cardinality(v_dl) = 1 then deadline_kind := 'date'; new_deadline := v_dl[1]; deadline_quote := v_dq;
    elsif v_roll is not null then deadline_kind := 'rolling'; deadline_text := v_roll; deadline_quote := v_roll;
    else deadline_kind := 'not_stated'; end if;
    new_year := case when r.intake_year is null then v_year end;
    new_start := case when r.start_date is null then v_start end;
    new_deadline := case when r.application_deadline is null then new_deadline end;
    outcome := case when new_year is not null or new_start is not null or new_deadline is not null then 'filled' else 'nothing_new' end;
    next_action := security.intake_next_action_v1(outcome, reason,
                     coalesce(r.intake_year, new_year) is not null and coalesce(r.start_date, new_start) is not null and coalesce(r.application_deadline, new_deadline) is not null);
    next_revisit_at := security.intake_revisit_at_v1(next_action);
    return next; outcome := null;
  end loop;
end $_$;


ALTER FUNCTION "security"."intake_dates_plan_v3"("p_course_ids" "uuid"[], "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_dates_plan_v3"("p_course_ids" "uuid"[], "p_limit" integer) IS 'CF-247 intake dates plan v3 (decisions 5 Nov 2026; P0 IQ-00313, 8 Nov 2026; F-INT 9 and 10 Nov 2026): the horizon (intake_dates.max_months_ahead), calendar values listed in pipeline.intake_date_rejections are not used, a withdrawn value is not admitted again; a row held for evidence is looked at again from stored inputs and the inputs fingerprint holds the page wording; while intake_dates.page_date_admit is 1 a corroborated date printed on the course page is admitted where the calendar route finds no named study period (rule page-date-v1), an undated intake whose stored wording prints a dated candidate for its month is looked at now (its fingerprint holds pagedate=1) and taken first in the batch, and a row that already holds its start date and year and whose page names no period is kept as nothing_new with its stored rule and quote.';



CREATE OR REPLACE FUNCTION "security"."intake_failure_class_trg_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c record; v_year int; v_month int;
begin
  select i.intake_year, array_position(array['january','february','march','april','may','june','july','august','september','october','november','december'], lower(btrim(i.intake_label)))
    into v_year, v_month from catalogue.course_intakes i where i.id = new.intake_id;
  select * into c from security.intake_failure_class_v1(new.outcome, new.reason, new.next_action = 'complete', new.deadline_kind, new.provider_id, v_year, v_month);
  new.failure_class := c.failure_class; new.deterministic := c.deterministic; new.revisit_trigger := c.revisit_trigger;
  new.evidence_year := coalesce((new.after_value->>'year')::int, v_year);
  new.reader := (select p.parser from pipeline.provider_policy_proposals p where p.id = new.proposal_id);
  new.related_case := case when c.failure_class in ('wrong_institution_or_campus', 'no_valid_calendar_source', 'stale_calendar_edition', 'academic_year_unproven')
                             then 'calendar:' || coalesce(new.calendar_evidence_id::text, new.provider_id::text)
                           when c.failure_class = 'course_identity_unresolved' then 'course:' || new.course_id end;
  -- mandate §9: an unchanged deterministic failure is never repeated on a timer; only a change of its inputs brings it back
  if c.deterministic then
    -- F-INT 9 Nov 2026: the four actions that stored evidence can change are looked at again on the revisit timer (setting intake_dates.revisit_stored_inputs);
    -- every other deterministic failure still waits for a change of its inputs only
    new.next_revisit_at := case when security.intake_revisit_stored_inputs_v1(new.next_action) then security.intake_revisit_at_v1(new.next_action) end;
  elsif c.failure_class in ('admission_held', 'course_level_exception') and new.next_revisit_at is null then
    new.next_revisit_at := now() + make_interval(days => security.pipeline_num_v1('intake_dates.revisit_days', 14)::int);
  end if;
  return new;
end $$;


ALTER FUNCTION "security"."intake_failure_class_trg_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_failure_class_trg_v1"() IS 'CF-247 (decision 5 Nov 2026 section 9; F-INT 9 Nov 2026): classifies each intake decision. A deterministic failure has no revisit time (an unchanged failure is never repeated on a timer) except evidence_ambiguous, reader_correction_needed, calendar_needs_correction and human_decision_required, which are looked at again from stored inputs after intake_dates.revisit_days while intake_dates.revisit_stored_inputs is on. A held or exception class without a time gets the revisit time as before.';



CREATE OR REPLACE FUNCTION "security"."intake_failure_class_v1"("p_outcome" "text", "p_reason" "text", "p_complete" boolean, "p_deadline_kind" "text", "p_provider" "uuid", "p_intake_year" integer, "p_month" integer) RETURNS TABLE("failure_class" "text", "deterministic" boolean, "revisit_trigger" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_latest int; v_target int := coalesce(p_intake_year, extract(year from (now() at time zone 'Australia/Melbourne'))::int + 1);  -- fixed: the calendar year in Australia
        v_key text := 'cf247.intake_cal_' || replace(coalesce(p_provider::text, 'none'), '-', ''); v_cal jsonb;
begin
  if p_outcome in ('filled', 'nothing_new') then
    if p_complete then return; end if;
    if p_deadline_kind = 'not_stated' then
      failure_class := 'missing_application_deadline_evidence'; deterministic := true; revisit_trigger := 'the calendar or the course page prints a closing date'; return next; return;
    end if;
    return;
  end if;
  failure_class := case
    when p_reason in ('intakes locked by hand', 'course held', 'kept by a lock or the same-month guard') then 'admission_held'
    -- direction 5 Nov 2026 15:50 §1: offering evidence missing, a governed withdrawal, another academic calendar
    when p_reason like 'the course page does not state % as %intake (offering evidence missing%' or p_reason like 'withdrawn:%' then 'course_level_exception'
    when p_reason like 'the course''s intakes (%) do not all start in%' then 'wrong_institution_or_campus'
    when p_reason like 'no valid academic calendar%set aside%' then 'wrong_institution_or_campus'
    when p_reason like 'no valid academic calendar%' then 'no_valid_calendar_source'
    when p_reason in ('no page behind the intake', 'page refused for this course') or p_reason like 'page not proved%' then 'course_identity_unresolved'
    when p_reason like 'no stored reading of the page%' then 'calendar_interpretation_failed'
    when p_reason like 'the calendar does not print the year%' or p_reason like 'the year of the named period is not printed%' then 'academic_year_unproven'
    when p_reason like 'several study periods start%' or p_reason like 'two start days%' then 'multiple_periods_match'
    when p_reason like 'the course page gives its own start date%' or p_reason like 'the page excludes this month%' or p_reason = 'intake is not a month' then 'course_level_exception'
    when p_reason like 'the course page names no study period%' or p_reason = 'the named period does not start in this month' then 'no_matching_commencement_period'
    when p_reason like '%past%' or p_reason like 'the calendar has no future start%' or p_reason like 'the calendar prints no start%' then 'waiting'
    else 'calendar_interpretation_failed' end;
  if failure_class = 'waiting' then
    -- a start in this month whose year is not proved (none printed, or claimed for the intake's year without evidence): the year is unproven;
    -- else no proved edition reaches the intake's year: the edition is stale; else the next start is a later year's
    -- the university's dated starts, read once a transaction (a run classifies many rows of one university)
    v_cal := nullif(current_setting(v_key, true), '')::jsonb;
    if v_cal is null then
      v_cal := jsonb_build_object('latest', (select max(s.year) from security.calendar_dated_periods_v2(p_provider) s where s.kind = 'start' and s.year_ok),
                                  'unproven', coalesce((select jsonb_agg(distinct jsonb_build_object('m', s.month, 'y', s.year)) from security.calendar_dated_periods_v2(p_provider) s
                                                         where s.kind = 'start' and not coalesce(s.year_ok, false)), '[]'::jsonb));
      perform set_config(v_key, v_cal::text, true);
    end if;
    if exists (select 1 from jsonb_array_elements(v_cal->'unproven') u where (u->>'m')::int = p_month and (u->>'y' is null or (u->>'y')::int = p_intake_year)) then
      failure_class := 'academic_year_unproven';
    else
      v_latest := (v_cal->>'latest')::int;
      failure_class := case when v_latest is null then 'academic_year_unproven' when v_latest < v_target then 'stale_calendar_edition' else 'waiting_for_next_academic_year' end;
    end if;
  end if;
  -- a lock, a hold or a person's decision is not an input of the fingerprint, so those rows are looked at again on the revisit timer
  deterministic := failure_class not in ('course_identity_unresolved', 'waiting_for_next_academic_year', 'consumer_publication_failed', 'admission_held', 'course_level_exception');
  revisit_trigger := case failure_class
    when 'admission_held' then 'the revisit date (a removed lock or hold is seen then)'
    when 'wrong_institution_or_campus' then 'the main campus teaching calendar is approved'
    when 'no_valid_calendar_source' then 'an official main teaching calendar is approved'
    when 'course_identity_unresolved' then 'the course page is proved (Course Link) or the revisit date'
    when 'calendar_interpretation_failed' then 'the calendar reader or the stored page changes'
    when 'academic_year_unproven' then 'the calendar reader or the stored calendar changes'
    when 'stale_calendar_edition' then 'a newer calendar edition is stored (calendar refresh or provider facts)'
    when 'multiple_periods_match' then 'the course page names its period, or the calendar changes'
    when 'course_level_exception' then 'the course page changes, or the revisit date (a person''s decision is seen then)'
    when 'no_matching_commencement_period' then 'the course page or the calendar changes'
    when 'waiting_for_next_academic_year' then 'the revisit date (intake_dates.revisit_days)' end;
  return next;
end $$;


ALTER FUNCTION "security"."intake_failure_class_v1"("p_outcome" "text", "p_reason" "text", "p_complete" boolean, "p_deadline_kind" "text", "p_provider" "uuid", "p_intake_year" integer, "p_month" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_failure_class_v1"("p_outcome" "text", "p_reason" "text", "p_complete" boolean, "p_deadline_kind" "text", "p_provider" "uuid", "p_intake_year" integer, "p_month" integer) IS 'CF-247 (mandate 5 Nov 2026 §9): the durable failure class of an intake date decision (no valid calendar source, stale calendar edition, wrong institution or campus, course identity unresolved, calendar interpretation failed, academic year unproven, no matching commencement period, multiple periods match, course-level exception, missing application deadline evidence, admission held, waiting for next academic year; consumer publication failed is set by the publication check), whether it is deterministic, and the change that brings it back.';



CREATE OR REPLACE FUNCTION "security"."intake_inputs_fp_v1"("p_set" "text", "p_evidence" "uuid", "p_course_url" "text", "p_settings" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$ select md5(coalesce(p_set, '') || '|' || coalesce(p_evidence::text, '') || '|' || coalesce(p_course_url, '') || '|' || coalesce(p_settings, '')) $$;


ALTER FUNCTION "security"."intake_inputs_fp_v1"("p_set" "text", "p_evidence" "uuid", "p_course_url" "text", "p_settings" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_inputs_fp_v1"("p_set" "text", "p_evidence" "uuid", "p_course_url" "text", "p_settings" "text") IS 'CF-247 (decision 5 Nov 2026 §7.9, §8): the inputs an intake row was decided on (calendar set and reader, page evidence, course page, decision settings); a row is not looked at again while they are unchanged and its revisit time has not passed.';



CREATE OR REPLACE FUNCTION "security"."intake_month_negated_v1"("p_text" "text", "p_month" integer) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with x as (
    select lower(coalesce(p_text, '')) t,
           '\m' || left((array['january','february','march','april','may','june','july','august','september','october','november','december'])[p_month], 3) || '[a-z]*\M' mon)
  -- the excluding clause is the word and at most two months joined by "and", "&", "or" or a comma ("except June and December", "(Except December)");
  -- a month followed by a further month list ("Except January February March ...") is ambiguous and is not read as excluded
  select p_month between 1 and 12 and x.t ~ x.mon
         and regexp_replace(x.t, '\m(exclud(e|es|ed|ing)|except(ing)?|other than|apart from|but not|not (offered|available|run)|no (intakes?|entry|start))\M\s*(in|during)?\s*\(?\s*(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*(\s*(,|&|\mand\M|\mor\M)\s*(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*)?\M(?!\s+(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\M)', ' ', 'g') !~ x.mon
    from x
$$;


ALTER FUNCTION "security"."intake_month_negated_v1"("p_text" "text", "p_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."intake_nearest_start_shadow_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_today date := (now() at time zone 'Australia/Melbourne')::date;  -- fixed: the calendar day in Australia (month roll-over)
  v_window int := security.pipeline_num_v1('intake_dates.nearest_start_days', 35)::int;
  v_ahead int := greatest(1, security.pipeline_num_v1('intake_dates.max_months_ahead', 18)::int);
  v_words text[] := coalesce((select array(select jsonb_array_elements_text(s.value)) from pipeline.platform_toolset_settings s
                               where s.toolset_key = 'pipeline' and s.key = 'central.calendar_qualify_blocked_period_words'), '{}');
  v jsonb;
begin
  delete from pipeline.intake_nearest_start_shadow;
  with rows as (
    select d.intake_id, d.course_id, d.provider_id, d.page_quote, i.intake_year,
           coalesce(l.code, '') in ('doctorate', 'masters_research') as research,
           array_position(array['january','february','march','april','may','june','july','august','september','october','november','december'], lower(btrim(i.intake_label))) as m
      from pipeline.course_intake_dates d join catalogue.course_intakes i on i.id = d.intake_id
      join catalogue.courses co on co.id = d.course_id left join ref.study_levels l on l.id = co.study_level_id
     where d.start_precision = 'month' and i.start_date is null
       and d.reason = 'the course page names no study period of the calendar (month only)'),
  provs as (select distinct provider_id from rows),
  cal as (
    select p.provider_id, s.period, s.on_date, s.quote, s.proposal_id
      from provs p cross join lateral security.calendar_dated_periods_v2(p.provider_id) s
     where s.kind = 'start' and s.year_ok and s.on_date is not null
       and s.on_date >= v_today and s.on_date < (v_today + make_interval(months => v_ahead))
       and not exists (select 1 from unnest(v_words) w where s.period ilike '%' || w || '%')
       -- audit 11 Nov 2026: a calendar line that is an application, census, orientation or enrolment date is never a teaching start (TAFE SA "applications open")
       and coalesce(s.quote, '') !~* '(applications?\s+(open|close)|census|orientation|o-?week|enrol)'
       and not exists (select 1 from pipeline.intake_date_rejections j where j.provider_id = p.provider_id and j.proposal_id is not distinct from s.proposal_id
                          and j.quote is not distinct from s.quote and j.year is not distinct from extract(year from s.on_date)::int)),
  y as (
    select r.*, coalesce(r.intake_year,
             case when make_date(extract(year from v_today)::int, r.m, 1) >= date_trunc('month', v_today)::date
                  then extract(year from v_today)::int else extract(year from v_today)::int + 1 end) as y0
      from rows r where r.m is not null),
  c as (
    select y.*,
           (select array_agg(distinct k.on_date order by k.on_date) from cal k where k.provider_id = y.provider_id
               and k.on_date >= make_date(y.y0, y.m, 1) and k.on_date < (make_date(y.y0, y.m, 1) + interval '1 month')::date) as s1,
           (select array_agg(distinct k.on_date order by k.on_date) from cal k where k.provider_id = y.provider_id
               and k.on_date >= (make_date(y.y0, y.m, 1) + interval '1 month')::date and k.on_date <= make_date(y.y0, y.m, 1) + v_window) as s2
      from y),
  o as (
    select c.*,
           case when cardinality(c.s1) = 1 then 'in_month' when c.s1 is null and cardinality(c.s2) = 1 then 'next_start' end as path,
           case when cardinality(c.s1) = 1 then c.s1[1] when c.s1 is null and cardinality(c.s2) = 1 then c.s2[1] end as cand,
           coalesce(c.s1, c.s2) as cands
      from c),
  g as (   -- a course whose two stated months would take the same date is ambiguous
    select o.*, count(*) over (partition by o.course_id, o.cand) as same_date_months from o)
  insert into pipeline.intake_nearest_start_shadow(intake_id, course_id, provider_id, stated_month, intake_year, target_year, outcome, path, candidate_date, candidate_dates,
                                                    period, calendar_quote, calendar_proposal_id, page_quote)
  select g.intake_id, g.course_id, g.provider_id, g.m, g.intake_year, g.y0,
         case when g.research then 'research_degree'   -- audit 11 Nov 2026: a research degree is not dated from the coursework calendar (Deakin PhD -> Trimester 2)
              when g.page_quote ~* '(rolling|flexible|continuous|any ?time|multiple intakes|throughout the year)' then 'rolling'
              when g.cand is null and g.cands is null then 'no_start'
              when g.cand is null then 'ambiguous'
              when g.same_date_months > 1 then 'ambiguous'
              when exists (select 1 from regexp_matches(coalesce(g.page_quote, ''),
                             '(\d{1,2})(?:st|nd|rd|th)?[\s-]+(' || (array['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'])[g.m] || ')[a-z]*', 'gi') x
                           where x[1]::int <> extract(day from g.cand)::int) then 'page_date_differs'
              else 'would_fill' end,
         g.path, g.cand, g.cands,
         (select k.period from cal k where k.provider_id = g.provider_id and k.on_date = g.cand order by k.period limit 1),
         (select k.quote from cal k where k.provider_id = g.provider_id and k.on_date = g.cand order by k.period limit 1),
         (select k.proposal_id from cal k where k.provider_id = g.provider_id and k.on_date = g.cand order by k.period limit 1),
         left(g.page_quote, 300)
    from g;
  select jsonb_build_object('computed_at', now(), 'window_days', v_window,
           'by_outcome', coalesce((select jsonb_object_agg(t.k, t.n) from (select outcome || coalesce(':' || path, '') k, count(*) n from pipeline.intake_nearest_start_shadow group by 1) t), '{}'::jsonb))
    into v;
  return v;
end
$$;


ALTER FUNCTION "security"."intake_nearest_start_shadow_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_nearest_start_shadow_v1"() IS 'CF-247 F-INT Rule B shadow (Decision 271): recomputes pipeline.intake_nearest_start_shadow. Writes only that table; admits nothing.';



CREATE OR REPLACE FUNCTION "security"."intake_nearest_start_v1"("p_course" "uuid", "p_intake" "uuid", "p_month" integer, "p_year" integer, "p_raw" "text", "p_cal" "jsonb", "p_today" "date", "p_ahead" integer, "p_days" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_names text[] := array['january','february','march','april','may','june','july','august','september','october','november','december'];
  v_words text[] := coalesce((select array(select jsonb_array_elements_text(s.value)) from pipeline.platform_toolset_settings s
                               where s.toolset_key = 'pipeline' and s.key = 'central.calendar_qualify_blocked_period_words'), '{}');
  v_y0 int; v_s1 date[]; v_s2 date[]; v_cand date; v_path text; o record; v_other date; v_bad text[] := '{}'; v_same text[] := '{}'; v_pd int[]; v_row record;
begin
  if exists (select 1 from catalogue.courses c join ref.study_levels l on l.id = c.study_level_id where c.id = p_course and l.code in ('doctorate', 'masters_research')) then
    return jsonb_build_object('admit', false, 'skip', 'a research degree is not dated from the coursework calendar (month only)');
  end if;
  -- 11 Nov 2026 (F-INT, RMIT switch-on): a level named in intake_dates.nearest_start_hold_levels (the vocational and pathway courses of a dual-sector
  -- university, which follow their own calendar) is not dated from the main teaching calendar
  if exists (select 1 from catalogue.courses c join ref.study_levels l on l.id = c.study_level_id where c.id = p_course
               and l.code in (select jsonb_array_elements_text(s.value) from pipeline.platform_toolset_settings s
                               where s.toolset_key = 'pipeline' and s.key = 'intake_dates.nearest_start_hold_levels' and jsonb_typeof(s.value) = 'array')) then
    return jsonb_build_object('admit', false, 'skip', 'a vocational or pathway course is not dated from the main teaching calendar (month only)');
  end if;
  if coalesce(p_raw, '') ~* '(rolling|flexible|continuous|any ?time|multiple intakes|throughout the year)' then
    return jsonb_build_object('admit', false, 'skip', 'rolling or flexible intakes: no calendar date (month only)');
  end if;
  -- the candidate start of one month: one start in the month, else one within p_days after the 1st
  for o in select x.m, coalesce(case when x.m = p_month then p_year end,
                                case when make_date(extract(year from p_today)::int, x.m, 1) >= date_trunc('month', p_today)::date
                                     then extract(year from p_today)::int else extract(year from p_today)::int + 1 end) as y
             from (select p_month as m union
                   select array_position(v_names, lower(btrim(i.intake_label))) from catalogue.course_intakes i
                    where i.course_id = p_course and i.status = 'active' and i.id <> p_intake and array_position(v_names, lower(btrim(i.intake_label))) is not null) x
            order by (x.m <> p_month), x.m loop
    select array_agg(distinct s.on_date order by s.on_date) filter (where s.on_date < (make_date(o.y, o.m, 1) + interval '1 month')::date),
           array_agg(distinct s.on_date order by s.on_date) filter (where s.on_date >= (make_date(o.y, o.m, 1) + interval '1 month')::date)
      into v_s1, v_s2
      from jsonb_to_recordset(p_cal) s(kind text, period text, on_date date, year_ok boolean, quote text)
     where s.kind = 'start' and s.year_ok and s.on_date is not null and s.on_date >= p_today
       and s.on_date < (p_today + make_interval(months => p_ahead))
       and s.on_date >= make_date(o.y, o.m, 1) and s.on_date <= make_date(o.y, o.m, 1) + p_days
       and not exists (select 1 from unnest(v_words) w where s.period ilike '%' || w || '%')
       and coalesce(s.quote, '') !~* '(applications?\s+(open|close)|census|orientation|o-?week|enrol)';
    if o.m = p_month then
      v_y0 := o.y;
      if cardinality(v_s1) > 1 or (v_s1 is null and cardinality(v_s2) > 1) then
        return jsonb_build_object('admit', false, 'skip', 'several study periods start in or just after this month (month only)');
      end if;
      v_cand := coalesce(v_s1[1], v_s2[1]); v_path := case when v_s1 is not null then 'in_month' else 'next_start' end;
      if v_cand is null then
        return jsonb_build_object('admit', false, 'skip', 'no main-teaching calendar start in this month or within ' || p_days || ' days after it (month only)');
      end if;
    else
      v_other := case when cardinality(v_s1) = 1 then v_s1[1] when v_s1 is null and cardinality(v_s2) = 1 then v_s2[1] end;
      if v_other is null then v_bad := v_bad || initcap(v_names[o.m]);
      elsif v_other = v_cand then v_same := v_same || initcap(v_names[o.m]); end if;
    end if;
  end loop;
  if cardinality(v_same) > 0 then
    return jsonb_build_object('admit', false, 'skip', 'two of the course''s intake months (' || initcap(v_names[p_month]) || ', ' || array_to_string(v_same, ', ') || ') would take the same calendar start (month only)');
  end if;
  if cardinality(v_bad) > 0 then
    return jsonb_build_object('admit', false, 'skip', 'the course''s other intakes (' || array_to_string(v_bad, ', ') || ') have no single main-teaching start: another academic calendar applies (month only)');
  end if;
  -- a full date of the stated month printed on the course page that differs holds the row
  select array_agg(distinct m[1]::int) into v_pd from regexp_matches(coalesce(p_raw, ''), '\m(\d{1,2})(?:st|nd|rd|th)?(?:\s+|-)' || left(v_names[p_month], 3) || '[a-z]*', 'gi') m;
  if v_pd is not null and not (extract(day from v_cand)::int = all (v_pd)) then
    return jsonb_build_object('admit', false, 'skip', 'the course page gives its own start date for this intake');
  end if;
  select s.period, s.quote, s.proposal_id, s.url, s.evidence_id into v_row
    from jsonb_to_recordset(p_cal) s(kind text, period text, on_date date, year_ok boolean, quote text, proposal_id uuid, url text, evidence_id uuid)
   where s.kind = 'start' and s.year_ok and s.on_date = v_cand
     and not exists (select 1 from unnest(v_words) w where s.period ilike '%' || w || '%')
     and coalesce(s.quote, '') !~* '(applications?\s+(open|close)|census|orientation|o-?week|enrol)'
   order by s.period limit 1;
  return jsonb_build_object('admit', true, 'date', v_cand, 'path', v_path, 'target_year', v_y0, 'period', v_row.period, 'quote', v_row.quote,
                            'proposal_id', v_row.proposal_id, 'calendar_url', v_row.url, 'calendar_evidence_id', v_row.evidence_id);
end
$$;


ALTER FUNCTION "security"."intake_nearest_start_v1"("p_course" "uuid", "p_intake" "uuid", "p_month" integer, "p_year" integer, "p_raw" "text", "p_cal" "jsonb", "p_today" "date", "p_ahead" integer, "p_days" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_nearest_start_v1"("p_course" "uuid", "p_intake" "uuid", "p_month" integer, "p_year" integer, "p_raw" "text", "p_cal" "jsonb", "p_today" "date", "p_ahead" integer, "p_days" integer) IS 'CF-247 F-INT Rule B (Decision 271) for one intake: the one main-teaching calendar start in the stated month, else the one within intake_dates.nearest_start_days after it, with the course-level, research, rolling and page-date checks. Used by security.intake_dates_plan_v3 for providers in intake_dates.nearest_start_providers only.';



CREATE OR REPLACE FUNCTION "security"."intake_negated_months_v1"("p_provider" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("intake_id" "uuid", "course_id" "uuid", "provider_id" "uuid", "intake_label" "text", "source_intake_key" "text", "page_url" "text", "page_wording" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select i.id, i.course_id, c.provider_id, i.intake_label, i.source_intake_key, e.source_url, left(w.t, 400)
    from catalogue.course_intakes i join catalogue.courses c on c.id = i.course_id
    left join pipeline.evidence_artifacts e on e.id = i.evidence_id
    cross join lateral (select security.intake_page_wording_v1(i.course_id, i.evidence_id, e.source_url) t) w
   where i.status = 'active' and (p_provider is null or c.provider_id = p_provider)
     and w.t ~* '\m(exclud(e|es|ed|ing)|except(ing)?|other than|apart from|but not|not (in|during|available|offered|run)|no (intakes?|entry|start) in)\M'
     and security.intake_month_negated_v1(w.t, array_position(array['january','february','march','april','may','june','july','august','september','october','november','december'], lower(btrim(i.intake_label))))
$$;


ALTER FUNCTION "security"."intake_negated_months_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_negated_months_v1"("p_provider" "uuid") IS 'CF-247 intake wording (Platform Admin 2 Nov 2026 23:24): active month intakes whose own stored page wording mentions the month only to exclude it (UWA "Throughout the year excluding January & December"). Read-only; the withdrawal is the paste file PASTE-20261103-intake-excluded-months-withdrawal.sql, run after approval.';



CREATE OR REPLACE FUNCTION "security"."intake_next_action_v1"("p_outcome" "text", "p_reason" "text", "p_complete" boolean) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when p_outcome in ('filled', 'nothing_new') and p_complete then 'complete'
    when p_outcome in ('filled', 'nothing_new') then 'awaiting_official_calendar'
    when p_reason in ('intakes locked by hand', 'course held', 'kept by a lock or the same-month guard') then 'human_decision_required'
    when p_reason like 'no valid academic calendar%set aside%' then 'calendar_needs_correction'
    when p_reason like 'no valid academic calendar%' then 'awaiting_official_calendar'
    when p_reason in ('no page behind the intake', 'page refused for this course') or p_reason like 'page not proved%' then 'course_identity_unresolved'
    when p_reason like 'no stored reading of the page%' or p_reason like 'the calendar does not print the year%' then 'reader_correction_needed'
    when p_reason like '%past%' or p_reason like 'the calendar has no future start%' or p_reason like 'the calendar prints no start%'
      or p_reason like 'the year of the named period is not printed%' then 'waiting_for_next_academic_year'
    when p_reason like 'the course page gives its own start date%' then 'human_decision_required'
    else 'evidence_ambiguous' end
$$;


ALTER FUNCTION "security"."intake_next_action_v1"("p_outcome" "text", "p_reason" "text", "p_complete" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_next_action_v1"("p_outcome" "text", "p_reason" "text", "p_complete" boolean) IS 'CF-247 (decision 5 Nov 2026 §8): the next-action class of an intake date decision: complete, awaiting official calendar, calendar needs correction, course identity unresolved, evidence ambiguous, reader correction needed, human decision required, waiting for next academic year (budget or operational limit and not published by provider are given by the process results).';



CREATE OR REPLACE FUNCTION "security"."intake_page_date_hint_v1"("p_course" "uuid", "p_evidence" "uuid", "p_label" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_m int := array_position(array['january','february','march','april','may','june','july','august','september','october','november','december'], lower(btrim(p_label)));
        v_full text; v_mon text;
begin
  if v_m is null then return false; end if;
  v_full := (array['january','february','march','april','may','june','july','august','september','october','november','december'])[v_m];
  v_mon := '(?:' || v_full || '|' || left(v_full, 3) || case when v_m = 9 then '|sept' else '' end || ')';
  -- the snippets security.intake_page_wording_v1 joins: the page reader's intake_context items of the course and the filled intakes quotes of the evidence
  return exists (
    select 1 from (select x from pipeline.coverage_course_pages g,
                          jsonb_array_elements_text(case when jsonb_typeof(g.candidates->'intake_context') = 'array' then g.candidates->'intake_context' else '[]'::jsonb end) x
                    where g.course_id = p_course
                   union all
                   select f.quote from pipeline.field_enrich_items f
                    where f.course_id = p_course and f.field = 'intakes' and f.state = 'filled' and f.evidence_id = p_evidence and nullif(btrim(f.quote), '') is not null) z(x)
     where z.x ~* ('\m\d{1,2}(?:st|nd|rd|th)?(?:\s+|-)' || v_mon || '\.?(?:,?\s+|-)20\d\d\M')
        or z.x ~* ('\m' || v_mon || '\.?\s+\d{1,2}(?:st|nd|rd|th)?,?\s+20\d\d\M')
        or (z.x ~ '\m20\d\d\s*:' and z.x ~* ('\m\d{1,2}(?:st|nd|rd|th)?\s+' || v_mon || '\M')));
end
$$;


ALTER FUNCTION "security"."intake_page_date_hint_v1"("p_course" "uuid", "p_evidence" "uuid", "p_label" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_page_date_hint_v1"("p_course" "uuid", "p_evidence" "uuid", "p_label" "text") IS 'CF-247 F-INT (10 Nov 2026): true when the stored wording of a course (the intake_context snippets of its page and the filled intakes quotes of the evidence, the text security.intake_page_date_v1 reads) prints a dated candidate for the intake month: day month year, month day year, or a year heading with days and months under it. A superset test: it decides nothing and admits nothing. Used by security.intake_dates_plan_v3 only while intake_dates.page_date_admit is 1, to look at such an intake now and to take it first.';



CREATE OR REPLACE FUNCTION "security"."intake_page_date_v1"("p_provider" "uuid", "p_intake" "uuid", "p_course" "uuid", "p_evidence" "uuid", "p_url" "text", "p_month" integer, "p_intake_year" integer, "p_cal" "jsonb", "p_today" "date", "p_ahead" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_full text := (array['january','february','march','april','may','june','july','august','september','october','november','december'])[p_month];
  v_mon text := '(?:' || v_full || '|' || left(v_full, 3) || case when p_month = 9 then '|sept' else '' end || ')';
  v_label text := '\m(start dates?|starts?|starting|commenc\w*|intakes?|teaching periods?|study periods?|semester|trimester|term|session|key dates)\M';
  v_other text := '\m(deadlines?|clos(e|es|ing|ed)|apply by|applications? (close|due)|census|orientation|enrolments?|results?|exams?|examinations?|graduation|holidays?|break|recess)\M';
  v_dom text := '\m(domestic|local|australian|permanent residents?|onshore|new zealand|nz)\M';
  v_name text := initcap(v_full);
  v_pat text; v_ap_label boolean := false; v_ap_intl boolean := false; v_ap_note text;
  e text; sent text; m record; d date; v_y int; v_day int; v_last int; v_dates date[] := '{}'; v_range boolean := false;
  v_quote text; v_adapter boolean; v_own boolean; v_q_adapter boolean := false; v_q_note text;
  v_p record; v_route text; v_hits jsonb := '[]'::jsonb; h jsonb; v_cand date[]; v_fut date[]; v_pos int;
  v_f1 text := '(?:(\d{1,2})(?:st|nd|rd|th)?\s*(?:-|–|—|to|until)\s*)?(\m(\d{1,2})(?:st|nd|rd|th)?(?:\s+|-)' || v_mon || '\.?(?:,?\s+|-)(20\d\d)\M(?!\s*:))';  -- day month year; a year followed by a colon is the heading of a list ("2027: 11 Jan, 1 Mar"), not the year of the date before it
  v_f2 text := '(\m' || v_mon || '\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(20\d\d)\M(?!\s*:))';                                       -- month day, year ("March 1, 2027", "February 1st 2027")
  v_f3 text := '(20\d\d)\s*:\s*((?:\d{1,2}(?:st|nd|rd|th)?\s+[A-Za-z]{3,9}\.?\s*[,|]?\s*)+)';                                       -- a year heading and the days and months listed under it ("2027: 11 Jan, 1 Mar")
  v_f3t text := '(\d{1,2})(?:st|nd|rd|th)?\s+' || v_mon || '\M';
begin
  if p_month is null then return jsonb_build_object('admit', false); end if;
  -- the university's page adapter: its start-date pattern names the page section it reads (the section label of a stored "adapter pattern:" snippet) and,
  -- when it is anchored on international admissions, the audience of every date it returns
  select a.patterns->>'intakes' into v_pat from pipeline.uni_adapters a where a.provider_id = p_provider and a.enabled;
  if v_pat is not null then
    v_ap_intl := right(v_pat, 60) ~* 'international';
    v_ap_label := v_pat ~* v_label or v_ap_intl;
    v_ap_note := coalesce((regexp_match(v_pat, '(open for international admissions|international admissions)', 'i'))[1], (regexp_match(v_pat, v_label, 'i'))[1]);
  end if;
  -- 1 the full dates of the intake's month, with their year, in the stored snippets of the page (never in a sentence about a closing date, census or exam)
  for e in
    select x from (select x from pipeline.coverage_course_pages g,
                          jsonb_array_elements_text(case when jsonb_typeof(g.candidates->'intake_context') = 'array' then g.candidates->'intake_context' else '[]'::jsonb end) x
                    where g.course_id = p_course and (g.url = p_url or g.candidates->>'final_url' = p_url)
                   union
                   select f.quote from pipeline.field_enrich_items f
                    where f.course_id = p_course and f.field = 'intakes' and f.state = 'filled' and f.evidence_id = p_evidence and nullif(btrim(f.quote), '') is not null) z(x)
     order by 1
  loop
    v_adapter := e ~* '^\s*adapter pattern:';
    foreach sent in array regexp_split_to_array(e, '(\.\s+|;|\n)') loop
      continue when sent ~* v_other;
      for m in
        select 'dmy' f, x[3] dd, x[4] yy, x[2] txt, x[1] rg from regexp_matches(sent, v_f1, 'gi') x
        union all select 'mdy', x[2], x[3], x[1], null from regexp_matches(sent, v_f2, 'gi') x
        union all select 'yh', t[1], b[1], b[2], null from regexp_matches(sent, v_f3, 'g') b, regexp_matches(b[2], v_f3t, 'gi') t
      loop
        if m.rg is not null then v_range := true; continue; end if;
        v_day := m.dd::int; v_y := m.yy::int;
        v_last := extract(day from (make_date(v_y, p_month, 1) + make_interval(months => 1) - make_interval(days => 1)))::int;
        continue when v_day not between 1 and v_last;
        d := make_date(v_y, p_month, v_day);
        -- the section label before the date (a page label, or the adapter's own for an "adapter pattern:" snippet)
        v_pos := greatest(position(m.txt in e) - 1, 0);
        v_own := left(e, v_pos) ~* v_label;
        v_hits := v_hits || jsonb_build_object('d', d, 'e', e, 'ad', v_adapter, 'own', v_own, 'lab', v_own or (v_adapter and v_ap_label));
      end loop;
    end loop;
  end loop;
  if v_range then return jsonb_build_object('admit', false, 'skip', 'the course page prints a range of days for ' || v_name || ' (page date not admitted)'); end if;
  select coalesce(array_agg(distinct (z->>'d')::date), '{}') into v_dates from jsonb_array_elements(v_hits) z;
  if cardinality(v_dates) = 0 then return jsonb_build_object('admit', false); end if;     -- no full date of this month: the calendar route decides as before
  -- the dates of the intake's own year when it holds one (a date of another year is not its date)
  v_cand := case when p_intake_year is null then v_dates else coalesce((select array_agg(x order by x) from unnest(v_dates) x where extract(year from x)::int = p_intake_year), '{}') end;
  if cardinality(v_cand) = 0 then
    return jsonb_build_object('admit', false, 'skip', 'the course page prints ' || v_dates[1] || ' but the intake is for ' || p_intake_year || ' (page date not admitted)');
  end if;
  -- the dates still to come inside the horizon: a page that lists this month for several years (a past date and the next one) names one upcoming date, as the calendar route reads it; two upcoming dates are ambiguous
  v_fut := coalesce((select array_agg(x order by x) from unnest(v_cand) x where x >= p_today and make_date(extract(year from x)::int, p_month, 1) <= (date_trunc('month', p_today) + make_interval(months => p_ahead))::date), '{}');
  if cardinality(v_fut) = 0 then
    d := v_cand[cardinality(v_cand)];
    if d < p_today then return jsonb_build_object('admit', false, 'skip', 'the course page prints ' || d || ', which is past (page date not admitted)'); end if;
    return jsonb_build_object('admit', false, 'skip', 'the course page prints ' || d || ', more than ' || p_ahead || ' months away (page date not admitted)');
  end if;
  if cardinality(v_fut) > 1 then
    return jsonb_build_object('admit', false, 'skip', 'the course page prints several different ' || v_name || ' dates (' || array_to_string(v_fut, ', ') || '): page date not admitted');
  end if;
  d := v_fut[1]; v_y := extract(year from d)::int;
  -- the quote: the first stored snippet that prints this date with a section label before it; a snippet whose only label is the adapter's gives way to a page snippet that has one
  for h in select z from jsonb_array_elements(v_hits) z where (z->>'d')::date = d loop
    if (h->>'lab')::boolean and (v_quote is null or (v_q_adapter and not (h->>'ad')::boolean)) then
      v_quote := h->>'e'; v_q_adapter := (h->>'ad')::boolean and not (h->>'own')::boolean;
    end if;
  end loop;
  -- 2 a rejected value, or a value withdrawn from this intake, is never admitted again
  if exists (select 1 from pipeline.intake_date_rejections j where j.provider_id = p_provider and j.start_date = d) then
    return jsonb_build_object('admit', false, 'skip', 'the course page prints ' || d || ', a value recorded as rejected for this university (page date not admitted)');
  end if;
  if exists (select 1 from pipeline.course_intake_date_events w where w.intake_id = p_intake and w.outcome = 'withdrawn'
              and (w.before_value->>'year')::int is not distinct from v_y and (w.before_value->>'start_date')::date is not distinct from d) then
    return jsonb_build_object('admit', false, 'skip', 'withdrawn: this value was rejected earlier and is not admitted again (a person decides)');
  end if;
  -- 3 the quote carries its section label before the date
  if v_quote is null then
    return jsonb_build_object('admit', false, 'skip', 'the course page prints ' || d || ' without a section label (start dates, intake, semester ...) before it: page date not admitted');
  end if;
  -- 4 corroboration: P1 an approved main teaching calendar start on that day; P2 the audience is shown (the page names international students only, or the
  -- page adapter reads international admissions only); otherwise P3, page only, not admitted
  select (array_agg(distinct s.proposal_id::text))[1]::uuid proposal_id, array_agg(distinct s.period) periods, min(s.url) url, (array_agg(distinct s.evidence_id::text))[1]::uuid evidence_id into v_p
    from jsonb_to_recordset(p_cal) s(proposal_id uuid, kind text, period text, on_date date, url text, evidence_id uuid, year_ok boolean)
   where s.kind = 'start' and s.on_date = d and coalesce(s.year_ok, false) and s.period !~* '\m(pathway|foundation)\M'
     and not exists (select 1 from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'central.calendar_excluded_words'), '[]'::jsonb)) w where lower(coalesce(s.url, '')) like '%' || lower(w) || '%');
  if v_p.proposal_id is not null then v_route := 'P1';
  elsif (v_quote ~* '^\s*adapter pattern:' and v_ap_intl) or (v_quote !~* '^\s*adapter pattern:' and v_quote ~* '\minternational\M' and v_quote !~* v_dom) then v_route := 'P2';
  else
    return jsonb_build_object('admit', false, 'skip', 'the course page prints ' || d || ' but no approved main calendar start is on that day and the page does not show the audience (page only): not admitted');
  end if;
  v_q_note := case when v_quote ~* '^\s*adapter pattern:' and v_ap_note is not null then ' [section label read by the university''s page adapter: ' || v_ap_note || ']' else '' end;
  -- the offering-evidence gate reads the page wording; the dates of an adapter snippet carry no word of their own ("15 February 2027"), so the adapter's section
  -- label is the statement: the one admitted date, labelled as the adapter reads it (a snippet with a label of its own on the page is read as printed)
  return jsonb_build_object('admit', true, 'date', d, 'quote', left(v_quote, 600) || v_q_note, 'route', v_route, 'proposal_id', v_p.proposal_id, 'periods', to_jsonb(v_p.periods),
                            'calendar_url', v_p.url, 'calendar_evidence_id', v_p.evidence_id,
                            'gate', case when v_q_adapter then 'intake dates read by the university''s page adapter (' || coalesce(v_ap_note, 'start dates') || '): ' || to_char(d, 'FMDD FMMonth YYYY') end);
end $$;


ALTER FUNCTION "security"."intake_page_date_v1"("p_provider" "uuid", "p_intake" "uuid", "p_course" "uuid", "p_evidence" "uuid", "p_url" "text", "p_month" integer, "p_intake_year" integer, "p_cal" "jsonb", "p_today" "date", "p_ahead" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_page_date_v1"("p_provider" "uuid", "p_intake" "uuid", "p_course" "uuid", "p_evidence" "uuid", "p_url" "text", "p_month" integer, "p_intake_year" integer, "p_cal" "jsonb", "p_today" "date", "p_ahead" integer) IS 'CF-247 F-INT D1 (9 Nov 2026), extraction extended 10 Nov 2026: reads the stored course page snippets (the text security.intake_page_wording_v1 reads) for the dates printed for the intake month (day month year; month day year; the days and months listed under a year heading; a year followed by a colon is a heading, never the year of the date before it). Of those, only the dates of the intake own year (when it holds one), still to come and inside the months-ahead limit count; exactly one is admitted, and only when it is not rejected or withdrawn, is quoted with its section label, and is corroborated by an approved main teaching calendar start on that day (P1) or by the audience shown (P2). Page only (P3) is never admitted, a day without a year is never admitted. Returns jsonb: admit, date, quote, route, proposal_id, periods, calendar_url, calendar_evidence_id, or skip with the reason. Used by security.intake_dates_plan_v3 only when intake_dates.page_date_admit is 1.';



CREATE OR REPLACE FUNCTION "security"."intake_page_wording_v1"("p_course" "uuid", "p_evidence" "uuid", "p_url" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_gurl text; v_final text; v_ctx jsonb; v_match boolean := false; v_page text; v_fill text;
begin
  -- the course's stored page (one row a course)
  select g.url, g.candidates->>'final_url', g.candidates->'intake_context' into v_gurl, v_final, v_ctx
    from pipeline.coverage_course_pages g where g.course_id = p_course;
  if found then
    if v_gurl = p_url or v_final = p_url then v_match := true;
    -- 12 Nov 2026 (F-INT): the same page with or without its trailing slash, or on another of the provider's own hosts (looked up only when needed)
    elsif v_gurl = any ((select security.course_page_url_variants_v1(co.provider_id, p_url) from catalogue.courses co where co.id = p_course)::text[]) then v_match := true;
    end if;
  end if;
  if v_match then
    v_page := (select string_agg(x, ' | ') from jsonb_array_elements_text(case when jsonb_typeof(v_ctx) = 'array' then v_ctx else '[]'::jsonb end) x);
  end if;
  v_fill := (select string_agg(f.quote, ' | ') from pipeline.field_enrich_items f
              where f.course_id = p_course and f.field = 'intakes' and f.state = 'filled' and f.evidence_id = p_evidence and nullif(btrim(f.quote), '') is not null);
  return case when v_page is null then v_fill when v_fill is null then v_page else v_page || ' | ' || v_fill end;
end
$$;


ALTER FUNCTION "security"."intake_page_wording_v1"("p_course" "uuid", "p_evidence" "uuid", "p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."intake_period_text_canonical_v1"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select regexp_replace(regexp_replace(regexp_replace(regexp_replace(lower(coalesce(p_text, '')),
           '\m(teaching period|study period) ?t ?([1-6])\M', 'term \2', 'g'),
           '\mt([1-6])\M', 'term \1', 'g'),
           '\m((teaching period|study period) ?s ?|s|sem\.? ?)([1-3])\M', 'semester \3', 'g'),
           '\mtri\.? ?([1-3])\M', 'trimester \1', 'g')
$$;


ALTER FUNCTION "security"."intake_period_text_canonical_v1"("p_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_period_text_canonical_v1"("p_text" "text") IS 'CF-247 (direction 5 Nov 2026 15:50 §2): the course page''s period wording with the same canonical names as the calendar (security.calendar_period_canonical_v1): Teaching period T1 and T1 -> term 1; S1, Sem 1 -> semester 1; Tri 2 -> trimester 2.';



CREATE OR REPLACE FUNCTION "security"."intake_period_text_v1"("p_text" "text", "p_lists" boolean) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with t as (
    -- "Semester One", "first semester" and "semester 1" are the same period (as security.enrich_parse_intake_periods_v1)
    select regexp_replace(regexp_replace(regexp_replace(lower(coalesce(p_text, '')), '\mone\M|\mfirst\M', '1', 'g'), '\mtwo\M|\msecond\M', '2', 'g'), '\mthree\M|\mthird\M', '3', 'g') t)
  select t.t || case when p_lists then coalesce(' | ' || (
    -- intake_dates.name_period_lists at 1 only: "semester 1 and 2", "semesters 1 & 2", "trimester 1, 2 and 3", "terms 1 or 2": each period named; single digits only ("term 1, 2027" is term 1)
    select string_agg(m[1] || ' ' || n, ' | ')
      from regexp_matches(t.t, '\m(semester|trimester|term|study period|teaching period|session|block|quarter)s?\s*([0-9](?:\s*(?:,|&|\mand\M|\mor\M|/)\s*[0-9])+)\M', 'g') m,
           regexp_split_to_table(m[2], '\s*(?:,|&|\mand\M|\mor\M|/)\s*') n), '') else '' end
    from t
$$;


ALTER FUNCTION "security"."intake_period_text_v1"("p_text" "text", "p_lists" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."intake_progress_alerts_v1"("p_status" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int := security.pipeline_num_v1('intake_progress.monopoly_runs', 3)::int; v_pct numeric := security.pipeline_num_v1('intake_progress.monopoly_share_pct', 80);
        v_runs timestamptz[]; v_rows int; v_top record; v_pending_other int; v_pub int; v_rep jsonb; v_out jsonb := '[]'::jsonb; v_cal jsonb;
        sel pipeline.progress_transitions; adm pipeline.progress_transitions; pub pipeline.progress_transitions; v_last_ok timestamptz;
begin
  select * into sel from pipeline.progress_transitions where key = 'intake_selection';
  select * into adm from pipeline.progress_transitions where key = 'intake_admission';
  select * into pub from pipeline.progress_transitions where key = 'intake_publication';
  select max(e.run_at) into v_last_ok from pipeline.course_intake_date_events e where e.outcome = 'filled';
  -- generic: zero yield is the admission transition's technical zero (eligible rows decided, nothing admitted, for progress.stall_hours)
  v_out := v_out || jsonb_build_object('code', 'zero_yield', 'label', 'Zero yield: rows decided, nothing admitted', 'raised_by', 'progress observer', 'fingerprint', 'stall:intake_admission',
    'tripped', coalesce(adm.stalled, false), 'zero_reason', adm.zero_reason, 'affected', coalesce(adm.input_eligible, 0),
    'evidence', jsonb_build_object('measured_at', adm.measured_at, 'decided', adm.input_processed, 'admitted', adm.output_admitted, 'by_class', adm.rejected_reasons, 'detail', adm.zero_detail),
    'last_success_stage', case when v_last_ok is not null then 'last value admitted ' || to_char(v_last_ok at time zone 'Australia/Sydney', 'DD Mon HH24:MI') else 'no value admitted yet' end,
    'next_action', 'Open the failure list: rows held by a lock need the lock reviewed; reader or publication failures go to the integration queue owner.');
  v_out := v_out || jsonb_build_object('code', 'job_overdue', 'label', 'Intake job overdue, stalled or not deciding rows', 'raised_by', 'progress observer', 'fingerprint', 'stall:intake_selection',
    'tripped', p_status->>'state' in ('stalled', 'failed') or coalesce(sel.stalled, false), 'zero_reason', sel.zero_reason,
    'affected', coalesce(sel.input_eligible, 0),
    'evidence', jsonb_build_object('state', p_status->>'state', 'last_run', p_status->'last_run', 'transition_stalled', sel.stalled, 'detail', sel.zero_detail),
    'last_success_stage', coalesce('last successful run ' || to_char((p_status->>'last_success')::timestamptz at time zone 'Australia/Sydney', 'DD Mon HH24:MI'), 'no successful run recorded'),
    'next_action', 'Open Scheduled jobs › Automations › Intake dates apply: read the last run message; resume only through the existing control.');
  v_out := v_out || jsonb_build_object('code', 'publication_stalled', 'label', 'Admitted values not reaching the Website API source', 'raised_by', 'progress observer', 'fingerprint', 'stall:intake_publication',
    'tripped', coalesce(pub.stalled, false), 'zero_reason', pub.zero_reason, 'affected', coalesce(pub.input_eligible, 0),
    'evidence', jsonb_build_object('checked', pub.input_processed, 'published', pub.output_published, 'not_published', pub.output_rejected, 'detail', pub.zero_detail),
    'last_success_stage', 'admission', 'next_action', 'Check the publication check (job process-results) and the Website API v2 projection.');
  -- intake checks: a partial publication mismatch (the transition still advances, so the observer cannot see it)
  select count(*) into v_pub from pipeline.course_intake_dates d where d.publication_state = 'consumer_publication_failed';
  v_out := v_out || jsonb_build_object('code', 'publication_mismatch', 'label', 'Some admitted values not in the Website API source', 'raised_by', 'intake checks', 'fingerprint', 'intake-progress:publication-mismatch',
    'tripped', v_pub > 0 and not coalesce(pub.stalled, false), 'affected', v_pub,
    'evidence', jsonb_build_object('rows', v_pub, 'retries', security.pipeline_num_v1('retry.intake_publication_checks', 3)),
    'last_success_stage', 'admission', 'next_action', 'The publication check retries; if it stays, verify the course in Website API v2 and route it to the integration queue owner.');
  -- intake checks: one provider monopolising the recent scheduled runs (the contract has no provider dimension)
  select coalesce(array_agg(run_at order by run_at desc), '{}') into v_runs from (
    select distinct e.run_at from pipeline.course_intake_date_events e where not e.bounded and e.outcome <> 'withdrawn' order by e.run_at desc limit v_n) r;
  select count(*) into v_rows from pipeline.course_intake_date_events e where e.run_at = any (v_runs) and e.outcome <> 'withdrawn';
  select e.provider_id, count(*) n, (select coalesce(p.display_name, p.canonical_name) from catalogue.providers p where p.id = e.provider_id) name into v_top
    from pipeline.course_intake_date_events e where e.run_at = any (v_runs) and e.outcome <> 'withdrawn' group by e.provider_id order by count(*) desc limit 1;
  select count(*) into v_pending_other from jsonb_array_elements(security.intake_ui_scopes_v1()) s
   where (s->>'id')::uuid is distinct from v_top.provider_id
     and exists (select 1 from catalogue.course_intakes i join catalogue.courses c on c.id = i.course_id
                  where c.provider_id = (s->>'id')::uuid and i.status = 'active' and c.lifecycle_status = 'active'
                    and (i.intake_year is null or i.start_date is null or i.application_deadline is null)
                    and not exists (select 1 from pipeline.course_intake_dates d where d.intake_id = i.id));
  v_out := v_out || jsonb_build_object('code', 'monopoly', 'label', 'One university monopolising processing', 'raised_by', 'intake checks', 'fingerprint', 'intake-progress:monopoly',
    'tripped', v_rows > 0 and v_top.n * 100.0 / v_rows >= v_pct and v_pending_other > 0 and cardinality(v_runs) >= v_n,
    'affected', coalesce(v_top.n, 0),
    'evidence', jsonb_build_object('provider_id', v_top.provider_id, 'university', v_top.name, 'share_pct', case when v_rows > 0 then round(v_top.n * 100.0 / v_rows, 1) end,
                                   'pilot_universities_waiting', v_pending_other, 'runs', to_jsonb(v_runs)),
    'last_success_stage', 'selection (the intake plan)', 'next_action', 'Check the provider and pilot shares (Settings › Pipeline settings › Intake dates); the scheduler itself is not changed here.');
  -- intake checks: a deterministic failure decided again although its evidence, reader and settings are demonstrably unchanged (mandate 12:44 §9;
  -- Platform Admin 5 Nov 2026 22:46: legitimate rechecks after a governed setting change, a reader revision or a source update are excluded, and a
  -- repeat whose earlier inputs cannot be established is unverified_repeat, shown but never raised)
  v_rep := security.intake_progress_repeats_v1();
  v_out := v_out || jsonb_build_object('code', 'repeated_deterministic', 'label', 'Deterministic failures repeated with unchanged inputs', 'raised_by', 'intake checks', 'fingerprint', 'intake-progress:repeated-deterministic',
    'tripped', (v_rep->>'confirmed')::int > 0, 'affected', (v_rep->>'confirmed')::int, 'evidence', v_rep, 'last_success_stage', 'classification',
    'next_action', 'An unchanged deterministic failure should wait for its input to change: report the confirmed rows to the intake owner (P0 rule). Unverified repeats are a diagnostic only.');
  -- shown only (routed by their existing mechanisms)
  v_out := v_out || jsonb_build_object('code', 'stale_calendar', 'label', 'Calendar editions stale', 'raised_by', 'shown only',
    'affected', (select count(*) from pipeline.course_intake_dates d where d.failure_class = 'stale_calendar_edition'),
    'tripped', exists (select 1 from pipeline.course_intake_dates d where d.failure_class = 'stale_calendar_edition'),
    'evidence', jsonb_build_object('class', 'stale_calendar_edition'), 'last_success_stage', 'calendar reading',
    'next_action', 'Calendar refresh (job calendar-reread) asks for newer editions within its credit budget; universities without a usable calendar are flagged by process-results.');
  v_out := v_out || jsonb_build_object('code', 'human_decisions', 'label', 'Pending human decisions', 'raised_by', 'shown only',
    'affected', coalesce((p_status->'held'->>'person_required')::int, 0), 'tripped', coalesce((p_status->'held'->>'person_required')::int, 0) > 0,
    'evidence', jsonb_build_object('rows', p_status->'held'->'person_required'), 'last_success_stage', 'classification',
    'next_action', 'Review blockers: Layer 4 Review and the integration queue.');
  v_out := v_out || jsonb_build_object('code', 'budget', 'label', 'Firecrawl budget for calendar refresh reached', 'raised_by', 'shown only',
    'tripped', coalesce((p_status->'usage'->>'firecrawl_credits_counted')::numeric >= (p_status->'usage'->>'firecrawl_budget')::numeric, false),
    'affected', coalesce((p_status->'usage'->>'firecrawl_credits_counted')::numeric, 0),
    'evidence', jsonb_build_object('counted', p_status->'usage'->'firecrawl_credits_counted', 'budget', p_status->'usage'->'firecrawl_budget'),
    'last_success_stage', 'calendar refresh', 'next_action', 'A Platform Admin decides whether to raise central.calendar_refresh_credit_budget.');
  select jsonb_agg(jsonb_build_object('university', a->>'university', 'before', (b->>'calendars_valid')::int, 'now', (a->>'calendars_valid')::int)) into v_cal
    from (select r.summary from pipeline.process_results r where r.process_key = 'intake-dates' order by r.measured_at desc limit 1) n, jsonb_array_elements(n.summary->'universities') a,
         (select r.summary from pipeline.process_results r where r.process_key = 'intake-dates' order by r.measured_at desc offset 1 limit 1) o, jsonb_array_elements(o.summary->'universities') b
   where a->>'provider_id' = b->>'provider_id' and (a->>'calendars_valid') is distinct from (b->>'calendars_valid');
  v_out := v_out || jsonb_build_object('code', 'source_coverage', 'label', 'Valid calendars changed since the previous measurement', 'raised_by', 'shown only',
    'tripped', v_cal is not null, 'affected', coalesce(jsonb_array_length(v_cal), 0), 'evidence', coalesce(v_cal, '[]'::jsonb), 'last_success_stage', 'measurement',
    'next_action', 'Open the university in Process results to see which calendar was added or set aside.');
  -- the open integration issue of each fingerprint (one condition, one issue)
  return (select jsonb_agg(a || jsonb_build_object('issue', (select jsonb_build_object('ref', i.issue_ref, 'status', i.status, 'cleared', i.condition_cleared_at is not null)
                                                              from pipeline.integration_issues i where i.fingerprint = a->>'fingerprint' and i.status <> 'closed')) order by o)
            from jsonb_array_elements(v_out) with ordinality x(a, o));
end $$;


ALTER FUNCTION "security"."intake_progress_alerts_v1"("p_status" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_progress_alerts_v1"("p_status" "jsonb") IS 'CF-247 Automation Progress (decision 16:36 §5, §6; 20:03): the intake alert conditions, one fingerprint each, with affected count, evidence, last successful stage, next action and the open issue: zero yield, job not deciding rows and publication stalled (raised by the generic progress observer as stall:intake_*); a partial publication mismatch, one provider monopolising and repeated deterministic failures (raised by the intake checks as intake-progress:*); stale calendars, pending human decisions, refresh budget and calendar coverage change (shown; routed by their existing mechanisms). Read only.';



CREATE OR REPLACE FUNCTION "security"."intake_progress_checks_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_alerts jsonb := security.intake_progress_alerts_v1(security.intake_progress_status_v1(0)); a jsonb; v_iss jsonb; v_out jsonb := '{}'::jsonb;
begin
  for a in select * from jsonb_array_elements(v_alerts) loop
    continue when a->>'raised_by' <> 'intake checks';
    if (a->>'tripped')::boolean then
      v_iss := security.integration_issue_upsert_v1(jsonb_build_object(
        'fingerprint', a->>'fingerprint', 'title', 'Intake dates: ' || (a->>'label'), 'layer', 'Layer 2', 'subsystem', 'intake-dates', 'severity', 'P2', 'workstream', 'A8',
        'validation_layer', 'V4', 'source', 'first-run-verify (intake checks)',
        'root_cause_class', case a->>'code' when 'repeated_deterministic' then 'code_defect' else 'unclassified' end,
        'failure', format('%s: %s affected. Last successful stage: %s.', a->>'label', a->>'affected', a->>'last_success_stage'),
        'expected', a->>'next_action', 'evidence', jsonb_build_object('alert', a - 'issue'), 'observed_at', now(),
        'provider_ids', case when a->'evidence'->>'provider_id' is not null then jsonb_build_array(a->'evidence'->>'provider_id') else '[]'::jsonb end), 'first-run-verify');
      v_out := v_out || jsonb_build_object(a->>'code', v_iss->>'issue_ref');
    else
      update pipeline.integration_issues i set condition_cleared_at = now()
       where i.fingerprint = a->>'fingerprint' and i.condition_cleared_at is null and i.status <> 'closed';
    end if;
  end loop;
  return v_out;
end $$;


ALTER FUNCTION "security"."intake_progress_checks_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_progress_checks_v1"() IS 'CF-247 Automation Progress (decision 16:36 §5, §6; 20:03): the intake conditions the generic progress contract cannot express (one provider monopolising, a partial publication mismatch, a deterministic failure repeated unchanged), raised through security.integration_issue_upsert_v1 with fingerprint intake-progress:<code> (P2, A8) and cleared with condition_cleared_at. Run by security.progress_read_v1 (job first-run-verify); writes nothing else.';



CREATE OR REPLACE FUNCTION "security"."intake_progress_failures_v1"("p_class" "text", "p_provider" "uuid", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- 16:36 §3E: every failure or hold, from the current state of each intake row (pipeline.course_intake_dates)
  with f as (select d.*, coalesce(d.failure_class, case when d.publication_state = 'consumer_publication_failed' then 'consumer_publication_failed' else 'not_classified_yet' end) cls,
                    (d.failure_class in ('course_level_exception', 'admission_held', 'wrong_institution_or_campus', 'no_valid_calendar_source')
                     or d.next_action in ('human_decision_required', 'calendar_needs_correction')) person
               from pipeline.course_intake_dates d
              where (d.outcome <> 'filled' or d.failure_class is not null or d.publication_state = 'consumer_publication_failed'))
  select jsonb_build_object(
    'classes', (select coalesce(jsonb_agg(jsonb_build_object('class', c.cls, 'rows', c.n, 'universities', c.u, 'person_required', c.p, 'deterministic', c.det) order by c.n desc), '[]'::jsonb)
                  from (select f.cls, count(*) n, count(distinct f.provider_id) u, count(*) filter (where f.person) p, bool_and(coalesce(f.deterministic, false)) det from f group by f.cls) c),
    'total', (select count(*) from f),
    'shown_limit', p_limit,
    'rows', (select coalesce(jsonb_agg(x order by x->>'last_attempt' desc), '[]'::jsonb) from (
       select jsonb_build_object('intake_id', f.intake_id, 'course_id', f.course_id, 'provider_id', f.provider_id,
         'university', (select coalesce(p.display_name, p.canonical_name) from catalogue.providers p where p.id = f.provider_id),
         'course_title', (select coalesce(c.display_title, c.canonical_title) from catalogue.courses c where c.id = f.course_id),
         'course_url', (select c.course_url from catalogue.courses c where c.id = f.course_id),
         'intake', (select i.intake_label || coalesce(' ' || i.intake_year, '') from catalogue.course_intakes i where i.id = f.intake_id),
         'class', f.cls, 'outcome', f.outcome, 'next_action', f.next_action,
         'reason', coalesce(f.reason, case when f.publication_state = 'consumer_publication_failed' then 'admitted, but the value is not in the Website API v2 source (publication check)'
                                           when f.failure_class = 'missing_application_deadline_evidence' then 'admitted without an application deadline: no closing date is printed for it'
                                           else 'no reason recorded' end),
         'evidence_version', jsonb_build_object('calendar_set', f.calendar_set, 'evidence_year', f.evidence_year, 'reader', f.reader, 'rule', f.rule,
                                                'inputs', left(f.inputs_fp, 12), 'calendar_url', f.calendar_url, 'calendar_evidence_id', f.calendar_evidence_id),
         'last_attempt', f.applied_at, 'next_revisit_at', f.next_revisit_at, 'revisit_trigger', f.revisit_trigger, 'related_case', f.related_case,
         'publication_state', f.publication_state,
         'issue', (select jsonb_build_object('ref', i.issue_ref, 'status', i.status, 'severity', i.severity) from pipeline.integration_issues i
                    where i.status <> 'closed' and (f.course_id = any (i.course_ids) or (f.related_case is not null and i.correlation_key = f.related_case))
                    order by i.severity, i.id limit 1),
         'automatic', case when f.publication_state = 'consumer_publication_failed' then 'checked again by the next publication check'
                           when f.deterministic then 'looked at again when its input changes: ' || coalesce(f.revisit_trigger, 'a change of calendar, reader, page or settings')
                           when f.next_revisit_at is not null then 'looked at again on its revisit date'
                           else 'not scheduled' end,
         'auto_recover', coalesce(f.publication_state = 'consumer_publication_failed' or f.deterministic or f.next_revisit_at is not null, false),
         'person_required', f.person) x
       from f where (p_class is null or f.cls = p_class) and (p_provider is null or f.provider_id = p_provider)
       order by f.applied_at desc limit p_limit) y))
$$;


ALTER FUNCTION "security"."intake_progress_failures_v1"("p_class" "text", "p_provider" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_progress_failures_v1"("p_class" "text", "p_provider" "uuid", "p_limit" integer) IS 'CF-247 Automation Progress (decision 16:36 §3E): every failed or held intake row by class (with universities and how many need a person), and the newest rows with category, exact reason, university and course, evidence version, last attempt, next action, next revisit or trigger, open integration issue, whether the platform recovers automatically and whether a person must act. Read only.';



CREATE OR REPLACE FUNCTION "security"."intake_progress_repeats_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- Platform Admin 5 Nov 2026 22:46: each deterministic refusal of the last day that repeats the same failure class of the same intake row is classified
  -- from existing records only, in this order:
  --   excluded_source_update   the calendar set, calendar document, approved reading, periods, evidence year or course page wording differ between the two decisions;
  --   excluded_reader_revision the reader or rule differ, or a release that changed an intake or calendar function was deployed between them
  --                            (pipeline.integration_deploy_checks.result->functions);
  --   excluded_setting_change  an intake_dates.* or run_now.* setting was changed between them: the Settings audit (pipeline.admin_control_events)
  --                            or, for a change written without an audit row, the setting's last-changed time (platform_toolset_settings.updated_at);
  --   unverified_repeat        the inputs of the later decision cannot be established and the earlier one shows no difference (no calendar set, page
  --                            wording or rule on both), or a release between them does not record the functions it changed; a gap on only one
  --                            of the two decisions is a difference and counts as a source update (also never raised);
  --   confirmed                otherwise: evidence, reader and settings demonstrably unchanged.
  with ev as (select e.intake_id, e.run_at, e.failure_class, e.calendar_set, e.calendar_evidence_id, e.proposal_id, e.periods, e.evidence_year, e.page_quote, e.reader, e.rule,
                     p.run_at p_at, p.calendar_set p_set, p.calendar_evidence_id p_doc, p.proposal_id p_prop, p.periods p_periods, p.evidence_year p_year, p.page_quote p_quote,
                     p.reader p_reader, p.rule p_rule, p.next_revisit_at p_revisit
                from pipeline.course_intake_date_events e
                cross join lateral (select x.* from pipeline.course_intake_date_events x
                                     where x.intake_id = e.intake_id and x.run_at < e.run_at and x.failure_class = e.failure_class order by x.run_at desc limit 1) p
               where e.run_at >= now() - make_interval(days => 1) and e.deterministic and e.outcome = 'skipped'),  -- fixed: the one-day check named by decision 16:36 §6
  -- materialised (10 Nov 2026): this list is tested once for every repeated row; written inline it was computed again for each row (a scan of the whole control log for 287 rows, 5.9 s)
  st as materialized (select a.created_at at from pipeline.admin_control_events a
          where a.area in ('toolsets', 'settings') and a.action in ('setting', 'change') and a.target ~ '^(pipeline\.)?(intake_dates|run_now)\.'
            and a.created_at >= (select min(ev.p_at) from ev)
         -- a change written without an audit row (for example by a release) is still seen through the setting's own last-changed time
         union all
         select s.updated_at from pipeline.platform_toolset_settings s
          where s.toolset_key = 'pipeline' and s.key ~ '^(intake_dates|run_now)\.' and s.updated_at >= (select min(ev.p_at) from ev)),
  rel as (select r.since at, exists (select 1 from jsonb_array_elements(case when jsonb_typeof(r.result->'functions') = 'array' then r.result->'functions' else '[]'::jsonb end) f
                                      where f->>'function' ~ '^security\.(intake_|calendar_)') intake_fn,
                 coalesce(jsonb_typeof(r.result->'functions') = 'array', false) known
            from pipeline.integration_deploy_checks r where r.since >= (select min(ev.p_at) from ev)),
  k as (select ev.*, case
          when ev.calendar_set is distinct from ev.p_set or ev.calendar_evidence_id is distinct from ev.p_doc or ev.proposal_id is distinct from ev.p_prop
               or ev.periods is distinct from ev.p_periods or ev.evidence_year is distinct from ev.p_year or ev.page_quote is distinct from ev.p_quote then 'excluded_source_update'
          when ev.reader is distinct from ev.p_reader or ev.rule is distinct from ev.p_rule
               or exists (select 1 from rel where rel.at > ev.p_at and rel.at < ev.run_at and rel.intake_fn) then 'excluded_reader_revision'
          when exists (select 1 from st where st.at > ev.p_at and st.at < ev.run_at) then 'excluded_setting_change'
          -- F-INT 9 Nov 2026: the earlier decision set a revisit time and this look is on or after it: a scheduled look, not an unchanged repeat
          when ev.p_revisit is not null and ev.run_at >= ev.p_revisit then 'excluded_scheduled_revisit'
          when ev.calendar_set is null or ev.page_quote is null or ev.rule is null
               or exists (select 1 from rel where rel.at > ev.p_at and rel.at < ev.run_at and not rel.known) then 'unverified_repeat'
          else 'confirmed' end status from ev)
  select jsonb_build_object(
    'confirmed', (select count(distinct k.intake_id) from k where k.status = 'confirmed'),
    'excluded_source_update', (select count(distinct k.intake_id) from k where k.status = 'excluded_source_update'),
    'excluded_reader_revision', (select count(distinct k.intake_id) from k where k.status = 'excluded_reader_revision'),
    'excluded_setting_change', (select count(distinct k.intake_id) from k where k.status = 'excluded_setting_change'),
    'excluded_scheduled_revisit', (select count(distinct k.intake_id) from k where k.status = 'excluded_scheduled_revisit'),
    'unverified_repeat', (select count(distinct k.intake_id) from k where k.status = 'unverified_repeat'),
    'examples', (select coalesce(jsonb_agg(jsonb_build_object('status', z.status, 'intake_id', z.intake_id, 'class', z.failure_class, 'decided', z.run_at, 'earlier', z.p_at)), '[]'::jsonb)
                   from (select distinct on (k.status) k.* from k order by k.status, k.run_at desc) z))
$$;


ALTER FUNCTION "security"."intake_progress_repeats_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_progress_repeats_v1"() IS 'CF-247 Automation Progress (Platform Admin 5 Nov 2026 22:46): the deterministic refusals of the last day that repeat an earlier refusal of the same intake row, classified from existing records (decision history, reader and rule, Settings audit in pipeline.admin_control_events and each setting''s updated_at, release records in pipeline.integration_deploy_checks) as confirmed, excluded (source update, reader revision, setting change) or unverified_repeat. Only confirmed repeats are raised. Read only.';



CREATE OR REPLACE FUNCTION "security"."intake_progress_runs_v1"("p_since" timestamp with time zone, "p_until" timestamp with time zone, "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_job bigint := (select j.jobid from cron.job j where j.jobname = 'intake-dates-apply'); v_cron jsonb;
begin
  -- the job's recent runs, newest first by run id (bounded: the primary key is read backwards)
  select coalesce(jsonb_agg(jsonb_build_object('runid', d.runid, 'status', d.status, 'start', d.start_time, 'end', d.end_time) order by d.runid desc), '[]'::jsonb) into v_cron
    from (select d.* from cron.job_run_details d where d.jobid = v_job order by d.runid desc limit p_limit * 2) d;
  return (with r as (select distinct e.run_at from pipeline.course_intake_date_events e where e.run_at >= p_since and e.run_at <= p_until order by e.run_at desc limit p_limit)
    select coalesce(jsonb_agg(x order by x->>'run_at' desc), '[]'::jsonb) from (
      select jsonb_build_object('run_at', r.run_at,
        'kind', case when bool_and(e.outcome = 'withdrawn') then 'withdrawal' when bool_or(e.bounded) then 'run_now' else 'scheduled' end,
        'cron_run', case when not bool_or(e.bounded) and not bool_and(e.outcome = 'withdrawn') then
                      (select c from jsonb_array_elements(v_cron) c where (c->>'start')::timestamptz <= r.run_at order by (c->>'start')::timestamptz desc limit 1) end,
        'selected', count(*) filter (where e.outcome <> 'withdrawn'), 'courses', count(distinct e.course_id), 'providers', count(distinct e.provider_id),
        'evidence_found', count(*) filter (where e.outcome <> 'withdrawn' and e.page_quote is not null),
        'validated', count(*) filter (where e.outcome = 'filled' or e.failure_class = 'admission_held'), 'admitted', count(*) filter (where e.outcome = 'filled'),
        'published', count(*) filter (where e.outcome = 'filled' and e.publication_state = 'published'), 'held', count(*) filter (where e.outcome = 'skipped'),
        'withdrawn', count(*) filter (where e.outcome = 'withdrawn'),
        'by_provider', (select coalesce(jsonb_agg(jsonb_build_object('provider_id', b.provider_id, 'university', b.name, 'rows', b.n, 'admitted', b.a) order by b.n desc), '[]'::jsonb)
                          from (select e2.provider_id, coalesce(p.display_name, p.canonical_name) name, count(*) n, count(*) filter (where e2.outcome = 'filled') a
                                  from pipeline.course_intake_date_events e2 left join catalogue.providers p on p.id = e2.provider_id
                                 where e2.run_at = r.run_at group by 1, 2) b)) x
        from r join pipeline.course_intake_date_events e on e.run_at = r.run_at group by r.run_at) z);
end $$;


ALTER FUNCTION "security"."intake_progress_runs_v1"("p_since" timestamp with time zone, "p_until" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_progress_runs_v1"("p_since" timestamp with time zone, "p_until" timestamp with time zone, "p_limit" integer) IS 'CF-247 Automation Progress (decision 16:36 §3B, §3D): each intake run in the window (one run = one decision time in pipeline.course_intake_date_events): kind (scheduled, governed Run Now, withdrawal), the matching intake-dates-apply cron run id and status, its funnel and its rows by provider. Read only.';



CREATE OR REPLACE FUNCTION "security"."intake_progress_status_v1"("p_rank" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare j record; c record; v_last record; v_ok timestamptz; v_obs record; v_state text; v_next timestamptz; v_m int; v_latest timestamptz; v_run jsonb; v_day jsonb;
        v_stall int := security.pipeline_num_v1('intake_progress.stall_minutes', 90)::int; v_meas jsonb; v_rec jsonb; v_meas_at timestamptz; v_on boolean; v_retiring boolean;
begin
  select * into j from cron.job x where x.jobname = 'intake-dates-apply';
  select * into c from pipeline.automation_catalogue x where x.jobname = 'intake-dates-apply';
  select d.runid, d.status, d.start_time, d.end_time, left(d.return_message, 300) message into v_last from cron.job_run_details d where d.jobid = j.jobid order by d.runid desc limit 1;
  select d.start_time into v_ok from cron.job_run_details d where d.jobid = j.jobid and d.status = 'succeeded' order by d.runid desc limit 1;
  select d.runid, d.status, d.start_time into v_obs from cron.job_run_details d where d.jobid = (select x.jobid from cron.job x where x.jobname = 'first-run-verify') order by d.runid desc limit 1;
  v_on := coalesce((security.toolset_setting('pipeline', 'intake_dates.apply_enabled') #>> '{}')::boolean, false);
  v_retiring := exists (select 1 from pipeline.component_register r where r.kind = 'job' and r.name = 'intake-dates-apply' and r.status in ('retiring', 'retired'));
  v_state := case when j.jobid is null then 'missing' when not j.active then 'paused' when not v_on then 'switched_off'
                  when v_last.status in ('running', 'starting') then 'running' when v_last.status = 'failed' then 'failed'
                  when v_last.start_time is null or v_last.start_time < now() - make_interval(mins => v_stall) then 'stalled' else 'waiting' end;
  if j.schedule ~ '^\d{1,2} \* \* \* \*$' then  -- an hourly schedule: the next minute past the hour
    v_m := split_part(j.schedule, ' ', 1)::int;
    v_next := date_trunc('hour', now()) + make_interval(mins => v_m);
    if v_next <= now() then v_next := v_next + make_interval(hours => 1); end if;  -- fixed: cron hour arithmetic
  end if;
  select max(e.run_at) into v_latest from pipeline.course_intake_date_events e where e.outcome <> 'withdrawn';
  v_run := case when v_latest is not null then security.intake_progress_window_v1(v_latest, v_latest) end;
  v_day := security.intake_progress_window_v1(now() - make_interval(days => 1), now());  -- fixed: the 24-hour rate named by decision 16:36 §3A
  select r.summary, r.measured_at into v_meas, v_meas_at from pipeline.process_results r where r.process_key = 'intake-dates' order by r.measured_at desc limit 1;
  select r.summary into v_rec from pipeline.process_results r where r.process_key = 'intake-recovery' order by r.measured_at desc limit 1;
  return jsonb_build_object(
    'as_at', now(), 'job', 'intake-dates-apply', 'label', coalesce(c.label, 'Intake dates apply'), 'state', v_state, 'schedule', j.schedule, 'active', j.active, 'apply_enabled', v_on,
    'last_run', case when v_last.runid is not null then jsonb_build_object('runid', v_last.runid, 'status', v_last.status, 'started_at', v_last.start_time, 'finished_at', v_last.end_time,
                       'message', case when v_last.status <> 'succeeded' then v_last.message end) end,
    'running_run', case when v_state = 'running' then v_last.runid end,
    'last_success', v_ok, 'next_run', v_next, 'stall_minutes', v_stall,
    'current_university', case when v_state = 'running' then 'not recorded until the run commits (a run is one transaction)' end,
    'batch', security.pipeline_num_v1('batch.intake_dates_apply', 200), 'provider_share', security.pipeline_num_v1('intake_dates.provider_share', 25),
    'pilot_share_pct', security.pipeline_num_v1('intake_dates.pilot_batch_share', 60),
    'scope', (select coalesce(jsonb_agg(e->>'name' order by o), '[]'::jsonb) from jsonb_array_elements(security.intake_ui_scopes_v1()) with ordinality s(e, o)),
    'latest_run', v_run, 'latest_run_admitted_nothing', coalesce((v_run->>'admitted')::int = 0, false),
    'rate_per_hour_24h', round(coalesce((v_day->>'selected')::numeric, 0) / 24, 1),  -- fixed: per hour over the 24-hour window
    'last_24h', v_day,
    'pending', jsonb_build_object('never_examined', (v_meas->'totals'->>'never_examined')::int, 'measured_at', v_meas_at,
       'revisit_due', (select count(*) from pipeline.course_intake_dates d where d.next_revisit_at <= now())),
    'held', (select jsonb_build_object('held', count(*), 'timed_revisit', count(*) filter (where d.next_revisit_at is not null),
                                       'waiting_for_change', count(*) filter (where d.deterministic),
                                       'person_required', count(*) filter (where d.failure_class in ('course_level_exception', 'admission_held', 'wrong_institution_or_campus', 'no_valid_calendar_source')
                                                                          or d.next_action in ('human_decision_required', 'calendar_needs_correction')))
               from pipeline.course_intake_dates d where d.outcome = 'skipped'),
    'usage', jsonb_build_object('ai_cost_usd', (select sum((u->>'ai_cost_usd_7_days')::numeric) from jsonb_array_elements(coalesce(v_meas->'universities', '[]'::jsonb)) u),
       'ai_window_days', security.pipeline_num_v1('process_results.window_days', 7), 'firecrawl_credits_used', (v_rec->'refresh'->>'credits_used')::numeric,
       'firecrawl_credits_counted', (v_rec->'refresh'->>'credits_counted')::numeric, 'firecrawl_budget', (v_rec->'refresh'->>'budget')::numeric),
    -- decision 20:03: the generic progress observer (job first-run-verify) watches the intake chain
    'observer', jsonb_build_object('job', 'first-run-verify', 'last_run', v_obs.start_time, 'status', v_obs.status,
       'window_hours', security.pipeline_num_v1('progress.window_hours', 24), 'stall_hours', security.pipeline_num_v1('progress.stall_hours', 6),
       'transitions', (select coalesce(jsonb_agg(jsonb_build_object('key', t.key, 'title', t.title, 'measured_at', t.measured_at, 'eligible', t.input_eligible, 'processed', t.input_processed,
                         'created', t.output_created, 'admitted', t.output_admitted, 'published', t.output_published, 'zero_reason', t.zero_reason, 'zero_detail', t.zero_detail,
                         'stalled', t.stalled, 'stalled_since', t.stalled_since, 'measure_error', t.measure_error,
                         'issue', (select i.issue_ref from pipeline.integration_issues i where i.id = t.issue_id and i.status <> 'closed')) order by t.step), '[]'::jsonb)
                         from pipeline.progress_transitions t where t.chain = 'intake')),
    'controls', jsonb_build_object('job', 'intake-dates-apply', 'control_rank', greatest(5, coalesce(c.control_rank, 6)), 'retiring', v_retiring,
       'can_pause_resume', j.jobid is not null and p_rank >= greatest(5, coalesce(c.control_rank, 6)) and (not v_retiring or j.active),
       'can_run_now', p_rank >= 4, 'can_measure', p_rank >= 4));
end $_$;


ALTER FUNCTION "security"."intake_progress_status_v1"("p_rank" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_progress_status_v1"("p_rank" integer) IS 'CF-247 Automation Progress (decision 16:36 §3A, §4): the intake-dates-apply job now: enabled, paused, switched off, running, waiting, failed or stalled (last start older than intake_progress.stall_minutes), last and running run id, last success, next run, batch, provider and pilot shares, scope, latest run funnel (and whether it admitted nothing), rate, pending work, held work, AI and Firecrawl use from the saved measurements, the generic progress observer''s readings of the intake chain, and which existing controls the caller''s role may use. Read only.';



CREATE OR REPLACE FUNCTION "security"."intake_progress_universities_v1"("p_since" timestamp with time zone, "p_until" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- 16:36 §3C: one row per university; a university not selected in the window is not_processed, one selected with no row reaching validation is zero_eligible
  with sc as (select (x.e->>'id')::uuid id, x.e->>'name' name, x.ord from jsonb_array_elements(security.intake_ui_scopes_v1()) with ordinality x(e, ord)),
  m as (select (u->>'provider_id')::uuid id, (u->>'never_examined')::int never_examined
          from (select r.summary from pipeline.process_results r where r.process_key = 'intake-dates' order by r.measured_at desc limit 1) s,
               jsonb_array_elements(coalesce(s.summary->'universities', '[]'::jsonb)) u),
  w as (select e.provider_id, count(*) filter (where e.outcome <> 'withdrawn') sel, count(distinct e.course_id) filter (where e.outcome <> 'withdrawn') courses,
               count(*) filter (where e.outcome = 'filled' or e.failure_class = 'admission_held') validated, count(*) filter (where e.outcome = 'filled') admitted,
               count(*) filter (where e.outcome = 'filled' and e.publication_state = 'published') published, count(*) filter (where e.outcome = 'skipped') held,
               count(*) filter (where e.outcome = 'withdrawn') withdrawn, count(distinct e.run_at) filter (where e.outcome <> 'withdrawn') runs
          from pipeline.course_intake_date_events e where e.run_at >= p_since and e.run_at <= p_until group by e.provider_id),
  ids as (select sc.id, true pilot, sc.ord, 0::bigint sel from sc
          union all select w.provider_id, false, null, w.sel from w where w.provider_id not in (select id from sc)),
  pick as (select * from ids order by pilot desc, ord, sel desc, id limit security.pipeline_num_v1('intake_progress.university_rows', 60)::int)
  select coalesce(jsonb_agg(x order by (x->>'pilot')::boolean desc, (x->>'ord')::int nulls last, (x->>'selected')::int desc, x->>'university'), '[]'::jsonb) from (
    select jsonb_build_object('provider_id', pick.id, 'pilot', pick.pilot, 'ord', pick.ord,
      'university', coalesce((select sc.name from sc where sc.id = pick.id), (select coalesce(p.display_name, p.canonical_name) from catalogue.providers p where p.id = pick.id)),
      'state', case when coalesce(w.sel, 0) = 0 then 'not_processed' when w.validated = 0 then 'zero_eligible' when w.admitted > 0 then 'admitted' else 'eligible_not_admitted' end,
      'selected', coalesce(w.sel, 0), 'courses', coalesce(w.courses, 0), 'runs', coalesce(w.runs, 0), 'eligible', coalesce(w.validated, 0),
      'admitted', coalesce(w.admitted, 0), 'published', coalesce(w.published, 0), 'held', coalesce(w.held, 0), 'withdrawn', coalesce(w.withdrawn, 0),
      'never_examined', m.never_examined,
      'revisit_due', (select count(*) from pipeline.course_intake_dates d where d.provider_id = pick.id and d.next_revisit_at <= now()),
      'pending', case when m.never_examined is not null then m.never_examined + (select count(*) from pipeline.course_intake_dates d where d.provider_id = pick.id and d.next_revisit_at <= now()) end,
      'held_now', (select count(*) from pipeline.course_intake_dates d where d.provider_id = pick.id and d.outcome = 'skipped'),
      'last_run', (select max(e.run_at) from pipeline.course_intake_date_events e where e.provider_id = pick.id and e.outcome <> 'withdrawn'),
      'next_revisit', (select min(d.next_revisit_at) from pipeline.course_intake_dates d where d.provider_id = pick.id and d.next_revisit_at > now())) x
    from pick left join w on w.provider_id = pick.id left join m on m.id = pick.id) y
$$;


ALTER FUNCTION "security"."intake_progress_universities_v1"("p_since" timestamp with time zone, "p_until" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_progress_universities_v1"("p_since" timestamp with time zone, "p_until" timestamp with time zone) IS 'CF-247 Automation Progress (decision 16:36 §3C): one row per pilot university (security.intake_ui_scopes_v1) and per other provider processed in the window: state (not_processed: not selected in the window; zero_eligible: selected and evaluated, no row reached validation), selected, eligible (validated), admitted, published, held, withdrawn, pending (never examined at the latest measurement plus revisits due), last run and next revisit. Read only.';



CREATE OR REPLACE FUNCTION "security"."intake_progress_window_v1"("p_since" timestamp with time zone, "p_until" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- 16:36 §3B: the ten-step funnel from persisted decisions; selected = admitted + nothing new + refused or held (reconciles row for row)
  with e as (select e.* from pipeline.course_intake_date_events e where e.run_at >= p_since and e.run_at <= p_until)
  select jsonb_build_object('since', p_since, 'until', p_until,
    'runs', count(distinct e.run_at) filter (where e.outcome <> 'withdrawn'),
    'scheduled_runs', count(distinct e.run_at) filter (where e.outcome <> 'withdrawn' and not e.bounded),
    'run_now_runs', count(distinct e.run_at) filter (where e.outcome <> 'withdrawn' and e.bounded),
    'withdrawal_actions', count(distinct e.run_at) filter (where e.outcome = 'withdrawn'),
    'selected', count(*) filter (where e.outcome <> 'withdrawn'),
    'selected_courses', count(distinct e.course_id) filter (where e.outcome <> 'withdrawn'),
    'examined', count(*) filter (where e.outcome <> 'withdrawn' and (e.reason is not null or e.outcome in ('filled', 'nothing_new'))),
    'evidence_found', count(*) filter (where e.outcome <> 'withdrawn' and e.page_quote is not null),
    'dates_extracted', count(*) filter (where e.outcome <> 'withdrawn' and (e.start_quote is not null or e.deadline_quote is not null or e.outcome = 'filled')),
    'dates_validated', count(*) filter (where e.outcome = 'filled' or e.failure_class = 'admission_held'),
    'admitted', count(*) filter (where e.outcome = 'filled'),
    'published', count(*) filter (where e.outcome = 'filled' and e.publication_state = 'published'),
    'publication_failed', count(*) filter (where e.outcome = 'filled' and e.publication_state = 'consumer_publication_failed'),
    'provider_not_published', count(*) filter (where e.outcome = 'filled' and e.publication_state in ('provider_not_published', 'course_not_in_consumer_source')),
    'publication_not_checked', count(*) filter (where e.outcome = 'filled' and e.publication_state is null),
    'nothing_new', count(*) filter (where e.outcome = 'nothing_new'),
    'refused_or_held', count(*) filter (where e.outcome = 'skipped'),
    'awaiting_revisit', count(*) filter (where e.outcome = 'skipped' and e.next_revisit_at is not null),
    'waiting_for_change', count(*) filter (where e.outcome = 'skipped' and e.deterministic),
    'withdrawn', count(*) filter (where e.outcome = 'withdrawn'),
    'net_gain', count(*) filter (where e.outcome = 'filled') - count(*) filter (where e.outcome = 'withdrawn'),
    'classes', (select coalesce(jsonb_object_agg(k, n), '{}'::jsonb) from (select coalesce(x.failure_class, 'not_classified_yet') k, count(*) n from e x
                 where x.outcome = 'skipped' group by 1) c))
  from e
$$;


ALTER FUNCTION "security"."intake_progress_window_v1"("p_since" timestamp with time zone, "p_until" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_progress_window_v1"("p_since" timestamp with time zone, "p_until" timestamp with time zone) IS 'CF-247 Automation Progress (decision 5 Nov 2026 16:36 §3B, §3D): the intake funnel over a window of persisted decisions (pipeline.course_intake_date_events): selected, examined, evidence found, dates extracted, validated, admitted, published, refused or held, awaiting revisit, withdrawn and net gain. Read only.';



CREATE OR REPLACE FUNCTION "security"."intake_projection_reconcile_v1"("p_course_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v jsonb; h text; it pipeline.website_sync_items%rowtype; zt pipeline.zoho_sync_items%rowtype; v_out jsonb;
begin
  if coalesce(cardinality(p_course_ids), 0) = 0 then return '[]'::jsonb; end if;
  -- the Website scan's own lock (waits for a scan that is running, then no scan interleaves with this transaction)
  perform pg_advisory_xact_lock(hashtext('website-sync-check'));
  for r in select w.item_key, w.ref_id from pipeline.website_sync_items w where w.entity = 'course' and w.ref_id = any (p_course_ids) order by w.item_key loop
    v := security.website_sync_item_v1('course', r.ref_id, r.item_key);
    h := case when v is null then null else md5((v - 'generated_at' - 'freshness')::text) end;
    select * into it from pipeline.website_sync_items where entity = 'course' and item_key = r.item_key;
    -- the transitions of security.website_sync_check_v1, for stored items only (a new item is created by the scan)
    if v is null then
      if it.removed_at is null then
        update pipeline.website_sync_items set removed_at = now(), hash = null, item = null, seq = nextval('pipeline.website_sync_seq'), seq_at = now() where entity = 'course' and item_key = r.item_key;
      end if;
    elsif it.removed_at is not null then
      update pipeline.website_sync_items set removed_at = null, hash = h, item = v, ref_id = r.ref_id, seq = nextval('pipeline.website_sync_seq'), seq_at = now() where entity = 'course' and item_key = r.item_key;
    elsif it.hash is null then
      update pipeline.website_sync_items set hash = h, item = v, ref_id = r.ref_id where entity = 'course' and item_key = r.item_key;
    elsif it.hash <> h then
      update pipeline.website_sync_items set hash = h, item = v, ref_id = r.ref_id, seq = nextval('pipeline.website_sync_seq'), seq_at = now() where entity = 'course' and item_key = r.item_key;
    elsif it.item is null then
      update pipeline.website_sync_items set item = v where entity = 'course' and item_key = r.item_key;
    end if;
  end loop;
  -- the Zoho scan reads the stored Website item, so it follows the Website step
  perform pg_advisory_xact_lock(hashtext('zoho-sync-check'));
  for r in select z.item_key, z.ref_id from pipeline.zoho_sync_items z where z.entity = 'course' and z.ref_id = any (p_course_ids) order by z.item_key loop
    v := security.zoho_sync_item_v1('course', r.ref_id, r.item_key);
    h := case when v is null then null else md5((v - 'generated_at' - 'freshness')::text) end;
    select * into zt from pipeline.zoho_sync_items where entity = 'course' and item_key = r.item_key;
    if v is null then
      if zt.removed_at is null then
        update pipeline.zoho_sync_items set removed_at = now(), hash = null, item = null, seq = nextval('pipeline.zoho_sync_seq'), seq_at = now() where entity = 'course' and item_key = r.item_key;
      end if;
    elsif zt.removed_at is not null then
      update pipeline.zoho_sync_items set removed_at = null, hash = h, item = v, ref_id = r.ref_id, seq = nextval('pipeline.zoho_sync_seq'), seq_at = now() where entity = 'course' and item_key = r.item_key;
    elsif zt.hash is null then
      update pipeline.zoho_sync_items set hash = h, item = v, ref_id = r.ref_id where entity = 'course' and item_key = r.item_key;
    elsif zt.hash <> h then
      update pipeline.zoho_sync_items set hash = h, item = v, ref_id = r.ref_id, seq = nextval('pipeline.zoho_sync_seq'), seq_at = now() where entity = 'course' and item_key = r.item_key;
    elsif zt.item is null then
      update pipeline.zoho_sync_items set item = v where entity = 'course' and item_key = r.item_key;
    end if;
  end loop;
  -- what the stored items now show for each course: its intakes (label, year, start date)
  select coalesce(jsonb_agg(jsonb_build_object('course_id', c.id,
           'website', (select jsonb_agg(jsonb_build_object('label', e->>'label', 'year', e->>'year', 'start_date', e->>'start_date') order by e->>'label')
                         from pipeline.website_sync_items w, jsonb_array_elements(coalesce(w.item->'intakes', '[]'::jsonb)) e where w.entity = 'course' and w.ref_id = c.id and w.removed_at is null),
           'zoho', (select jsonb_agg(jsonb_build_object('label', e->>'label', 'year', e->>'year', 'start_date', e->>'start_date') order by e->>'label')
                      from pipeline.zoho_sync_items z, jsonb_array_elements(coalesce(z.item->'intakes', '[]'::jsonb)) e where z.entity = 'course' and z.ref_id = c.id and z.removed_at is null)) order by c.id), '[]'::jsonb)
    into v_out from unnest(p_course_ids) c(id);
  return v_out;
end $$;


ALTER FUNCTION "security"."intake_projection_reconcile_v1"("p_course_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_projection_reconcile_v1"("p_course_ids" "uuid"[]) IS 'CF-247 P0 IQ-00313 (8 Nov 2026): re-evaluates the stored Website item and then the stored Zoho item of the named courses with the scans'' own builders, transition rules and advisory locks (security.website_sync_check_v1, security.zoho_sync_check_v1), so a corrected intake leaves both stored items without waiting for the next pass. Returns the intakes (label, year, start date) each stored item now holds. Changes no consumer API object.';



CREATE OR REPLACE FUNCTION "security"."intake_publication_check_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_state text; n_pub int := 0; n_fail int := 0; n_off int := 0;
begin
  for r in
    select d.intake_id, d.course_id, d.provider_id, i.intake_label, i.intake_year, i.start_date, i.application_deadline
      from pipeline.course_intake_dates d join catalogue.course_intakes i on i.id = d.intake_id
     where d.outcome = 'filled' and d.applied_at is not null
       and (d.publication_checked_at is null or d.publication_checked_at < d.applied_at
            or (d.publication_state = 'consumer_publication_failed' and d.publication_attempts < security.pipeline_num_v1('retry.intake_publication_checks', 3)))
     order by d.publication_checked_at nulls first, d.applied_at
     limit security.pipeline_num_v1('batch.intake_publication_check', 500)::int
  loop
    v_state := case
      when exists (select 1 from security.provider_hidden_v1 h where h.provider_id = r.provider_id) then 'provider_not_published'
      when not exists (select 1 from search.course_documents cd where cd.course_id = r.course_id) then 'course_not_in_consumer_source'
      when exists (select 1 from search.course_documents cd, jsonb_array_elements(case when jsonb_typeof(cd.intake_options) = 'array' then cd.intake_options else '[]'::jsonb end) e
                    where cd.course_id = r.course_id and e->>'label' = r.intake_label
                      and e->>'year' is not distinct from r.intake_year::text
                      and e->>'start_date' is not distinct from r.start_date::text
                      and e->>'application_deadline' is not distinct from r.application_deadline::text) then 'published'
      else 'consumer_publication_failed' end;
    update pipeline.course_intake_dates set publication_state = v_state, publication_checked_at = now(),
           publication_attempts = case when v_state = 'consumer_publication_failed' then publication_attempts + 1 else 0 end,
           failure_class = case when v_state = 'consumer_publication_failed' then 'consumer_publication_failed' else failure_class end,
           deterministic = case when v_state = 'consumer_publication_failed' then false else deterministic end,
           revisit_trigger = case when v_state = 'consumer_publication_failed' then 'the next publication check (after the next projection refresh)' else revisit_trigger end
     where intake_id = r.intake_id;
    update pipeline.course_intake_date_events e set publication_state = v_state, publication_checked_at = now()
     where e.id = (select max(x.id) from pipeline.course_intake_date_events x where x.intake_id = r.intake_id and x.outcome = 'filled');
    if v_state = 'published' then n_pub := n_pub + 1; elsif v_state in ('provider_not_published', 'course_not_in_consumer_source') then n_off := n_off + 1; else n_fail := n_fail + 1; end if;
  end loop;
  return jsonb_build_object('published', n_pub, 'consumer_publication_failed', n_fail, 'not_in_consumer_source', n_off);
end $$;


ALTER FUNCTION "security"."intake_publication_check_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_publication_check_v1"() IS 'CF-247 (mandate 5 Nov 2026 §6): every admitted intake value compared with the Website API v2 source (search.course_documents.intake_options, read only): published, provider not published (the Published switch decides), or consumer publication failed (a durable class, checked again next run). Run by jobs intake-dates-apply and process-results.';



CREATE OR REPLACE FUNCTION "security"."intake_revisit_at_v1"("p_next_action" "text") RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when p_next_action in ('awaiting_official_calendar', 'course_identity_unresolved', 'waiting_for_next_academic_year', 'budget_or_operational_limit', 'ready_for_scheduled_recovery')
              or security.intake_revisit_stored_inputs_v1(p_next_action)
              then now() + make_interval(days => security.pipeline_num_v1('intake_dates.revisit_days', 14)::int) end
$$;


ALTER FUNCTION "security"."intake_revisit_at_v1"("p_next_action" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_revisit_at_v1"("p_next_action" "text") IS 'CF-247 (decision 5 Nov 2026 section 8; F-INT 9 Nov 2026): when a waiting row is looked at again without a change (intake_dates.revisit_days after now). The waiting actions awaiting_official_calendar, course_identity_unresolved, waiting_for_next_academic_year, budget_or_operational_limit and ready_for_scheduled_recovery, and, while intake_dates.revisit_stored_inputs is on, evidence_ambiguous, reader_correction_needed, calendar_needs_correction and human_decision_required.';



CREATE OR REPLACE FUNCTION "security"."intake_revisit_backfill_undo_v1"("p_batch" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_restored int := 0; v_skipped int := 0; v_total int; v_status text;
begin
  perform 1 from pipeline.intake_revisit_backfill_batches b where b.batch_id = p_batch for update;
  if not found then raise exception 'revisit backfill batch % is not recorded', p_batch using errcode = '22023'; end if;
  -- a row goes back only while it holds exactly the value this backfill set; a row decided again since (a new time) or changed in any other way keeps what it has
  with l as (select g.intake_id, g.previous_next_revisit_at from pipeline.intake_revisit_backfill_log g where g.batch_id = p_batch and g.undone_at is null order by g.intake_id),
  u as (
    update pipeline.course_intake_dates d set next_revisit_at = l.previous_next_revisit_at
      from l, pipeline.intake_revisit_backfill_log g
     where g.batch_id = p_batch and g.intake_id = l.intake_id and d.intake_id = l.intake_id and d.next_revisit_at is not distinct from g.new_next_revisit_at
    returning d.intake_id)
  update pipeline.intake_revisit_backfill_log g set undone_at = now(), undo_outcome = case when u.intake_id is not null then 'restored' else 'skipped_changed' end
    from l left join u on u.intake_id = l.intake_id
   where g.batch_id = p_batch and g.intake_id = l.intake_id;
  select count(*) filter (where undo_outcome = 'restored'), count(*) filter (where undo_outcome = 'skipped_changed'), count(*)
    into v_restored, v_skipped, v_total from pipeline.intake_revisit_backfill_log where batch_id = p_batch;
  v_status := case when v_skipped = 0 then 'undone' else 'partly_undone' end;
  update pipeline.intake_revisit_backfill_batches b set status = v_status, undone_at = now(), rows_restored = v_restored, rows_skipped = v_skipped where b.batch_id = p_batch;
  return jsonb_build_object('batch', p_batch, 'status', v_status, 'rows_in_batch', v_total, 'restored', v_restored, 'skipped_changed_since', v_skipped);
end $$;


ALTER FUNCTION "security"."intake_revisit_backfill_undo_v1"("p_batch" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_revisit_backfill_undo_v1"("p_batch" "uuid") IS 'CF-247 F-INT D3 forward fix (9 Nov 2026): puts back the previous next_revisit_at of the rows a revisit-time backfill batch changed, only for rows that still hold exactly the value the backfill set; a row that has changed since is left as it is and recorded as skipped_changed. Not run automatically; the Platform Admin calls public.admin_intake_revisit_backfill_undo_v1. Running it again changes nothing.';



CREATE OR REPLACE FUNCTION "security"."intake_revisit_stored_inputs_v1"("p_next_action" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select p_next_action in ('evidence_ambiguous', 'reader_correction_needed', 'calendar_needs_correction', 'human_decision_required')
         and security.pipeline_num_v1('intake_dates.revisit_stored_inputs', 0) = 1
$$;


ALTER FUNCTION "security"."intake_revisit_stored_inputs_v1"("p_next_action" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_revisit_stored_inputs_v1"("p_next_action" "text") IS 'CF-247 F-INT (9 Nov 2026): true when a row held with this next action is looked at again from its stored inputs on the revisit timer (setting intake_dates.revisit_stored_inputs, off by default). The four actions: evidence_ambiguous, reader_correction_needed, calendar_needs_correction, human_decision_required.';



CREATE OR REPLACE FUNCTION "security"."intake_rule_b_qualify_one_v1"("p_provider" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_list jsonb := coalesce((select s.value from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'intake_dates.nearest_start_providers'
                            and jsonb_typeof(s.value) = 'array'), '[]'::jsonb);
  v_listed boolean;
  v_limit int := security.pipeline_num_v1('intake_dates.rule_b_qualify_row_limit', 3000)::int;
  v_min int := security.pipeline_num_v1('intake_dates.rule_b_qualify_min_rows', 5)::int;
  v_names text[] := array['january','february','march','april','may','june','july','august','september','october','november','december'];
  v_hold text[] := array['doctorate', 'masters_research'] || coalesce((select array(select jsonb_array_elements_text(s.value)) from pipeline.platform_toolset_settings s
                            where s.toolset_key = 'pipeline' and s.key = 'intake_dates.nearest_start_hold_levels' and jsonb_typeof(s.value) = 'array'), '{}');
  v_m jsonb;
  v_reasons text[] := '{}';
  v_quality_fail boolean := false;
begin
  v_listed := v_list ? p_provider::text;
  -- the trial: the university on the list, the live planner, then always rolled back (sqlstate CF001); only the measures leave the block
  begin
    if not v_listed then
      update pipeline.platform_toolset_settings set value = v_list || jsonb_build_array(p_provider::text)
       where toolset_key = 'pipeline' and key = 'intake_dates.nearest_start_providers';
    end if;
    with t as (
      select p.*, i.intake_label, array_position(v_names, lower(btrim(i.intake_label))) mon, l.code lvl, coalesce(c.display_title, c.canonical_title) title
        from security.intake_dates_plan_v3((select array_agg(c2.id) from catalogue.courses c2 where c2.provider_id = p_provider and c2.lifecycle_status = 'active'), v_limit) p
        join catalogue.course_intakes i on i.id = p.intake_id
        join catalogue.courses c on c.id = p.course_id
        left join ref.study_levels l on l.id = c.study_level_id),
    rb as (select * from t where t.outcome = 'filled' and t.rule = 'calendar-v3-nearest-start'),
    admitted as (select i.intake_label, i.start_date from pipeline.course_intake_dates d join catalogue.course_intakes i on i.id = d.intake_id
                  where d.provider_id = p_provider and d.outcome = 'filled' and d.rule = 'calendar-v3-nearest-start' and i.start_date is not null),
    alld as (select rb.intake_label, rb.new_start d from rb union all select a.intake_label, a.start_date from admitted a),
    per as (select z.intake_label, count(*) nd, jsonb_object_agg(z.d::text, z.n) dates
              from (select alld.intake_label, alld.d, count(*) n from alld group by 1, 2) z group by 1)
    select jsonb_build_object(
      'looked', (select count(*) from t),
      'rule_b_rows', (select count(*) from rb),
      'other_rows', (select count(*) from t where t.outcome = 'filled' and t.rule is distinct from 'calendar-v3-nearest-start'),
      'wording_missing', (select count(*) from rb where rb.mon is null
                            or security.intake_course_applicability_v1(rb.page_quote, rb.mon, extract(year from rb.new_start)::int, '[]'::jsonb, false) is not null),
      'held_level_dated', (select count(*) from rb where rb.lvl = any (v_hold)),
      'calendar_missing', (select count(*) from rb where rb.calendar_url is null),
      'months_with_two_dates', coalesce((select jsonb_agg(per.intake_label) from per where per.nd > 1), '[]'::jsonb),
      'dates', coalesce((select jsonb_object_agg(per.intake_label, per.dates) from per), '{}'::jsonb),
      'sample', coalesce((select jsonb_agg(x) from (select jsonb_build_object('course', rb.title, 'intake', rb.intake_label, 'date', rb.new_start,
                                                               'page', right(rb.page_quote, 160), 'calendar', left(rb.start_quote, 160), 'calendar_url', rb.calendar_url) x
                                                      from rb order by md5(rb.intake_id::text) limit 6) s), '[]'::jsonb))
      into v_m;
    raise exception using errcode = 'CF001', message = 'cf247 rule b trial rolled back';
  exception when sqlstate 'CF001' then
    null;  -- the trial is undone; v_m keeps the measures
  end;
  if (v_m->>'wording_missing')::int > 0 then v_quality_fail := true;
    v_reasons := v_reasons || format('%s dates have page wording that does not state the month as an intake', v_m->>'wording_missing'); end if;
  if (v_m->>'held_level_dated')::int > 0 then v_quality_fail := true;
    v_reasons := v_reasons || format('%s vocational, pathway or research courses would be dated', v_m->>'held_level_dated'); end if;
  if (v_m->>'calendar_missing')::int > 0 then v_quality_fail := true;
    v_reasons := v_reasons || format('%s dates have no calendar evidence', v_m->>'calendar_missing'); end if;
  if jsonb_array_length(v_m->'months_with_two_dates') > 0 then v_quality_fail := true;
    v_reasons := v_reasons || ('an intake month maps to more than one date: ' || (select string_agg(x, ', ') from jsonb_array_elements_text(v_m->'months_with_two_dates') x)); end if;
  if not v_listed and (v_m->>'rule_b_rows')::int < v_min then
    v_reasons := v_reasons || format('nothing worth adding: %s dates (fewest to qualify: %s)', v_m->>'rule_b_rows', v_min); end if;
  return v_m || jsonb_build_object('listed', v_listed, 'quality_fail', v_quality_fail, 'reasons', to_jsonb(v_reasons),
    'status', case when v_listed and v_quality_fail then 'paused' when v_listed then 'listed' when cardinality(v_reasons) = 0 then 'qualified' else 'held' end);
end $$;


ALTER FUNCTION "security"."intake_rule_b_qualify_one_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_rule_b_qualify_one_v1"("p_provider" "uuid") IS 'CF-247 F-INT (11 Nov 2026): one rolled-back Rule B trial for a university (the live planner with the university on the nearest-start list) and its checks. Writes nothing.';



CREATE OR REPLACE FUNCTION "security"."intake_rule_b_qualify_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_batch int := security.pipeline_num_v1('batch.intake_rule_b_qualify', 1)::int;
  v_hours int := security.pipeline_num_v1('intake_dates.rule_b_requalify_hours', 24)::int;
  v_pause boolean := coalesce((security.toolset_setting('pipeline', 'intake_dates.rule_b_auto_pause') #>> '{}')::boolean, true);
  v_list jsonb; v_after jsonb; r record; v_m jsonb; v_done int := 0; v_out jsonb := '[]'::jsonb;
begin
  perform pg_advisory_xact_lock(hashtext('cf247 rule b qualify'));  -- fixed: one run at a time
  -- every university with an intake calendar, and every listed one, has a row
  insert into pipeline.intake_rule_b_qualifications(provider_id)
  select distinct d.provider_id from pipeline.course_intake_dates d where d.calendar_set is not null
  union
  select x::uuid from pipeline.platform_toolset_settings s, jsonb_array_elements_text(case when jsonb_typeof(s.value) = 'array' then s.value else '[]'::jsonb end) x
   where s.toolset_key = 'pipeline' and s.key = 'intake_dates.nearest_start_providers' and x ~ '^[0-9a-f-]{36}$'
  on conflict (provider_id) do nothing;
  for r in select q.provider_id from pipeline.intake_rule_b_qualifications q
            where q.requested_at is not null or q.checked_at is null or q.checked_at < now() - make_interval(hours => v_hours)
            order by (q.requested_at is null), q.requested_at, q.checked_at nulls first
            limit v_batch loop
    begin
      v_m := security.intake_rule_b_qualify_one_v1(r.provider_id);
      update pipeline.intake_rule_b_qualifications q set
        status = case when v_m->>'status' = 'paused' and not v_pause then 'listed' else v_m->>'status' end,
        checked_at = now(), requested_at = null, rule_b_rows = (v_m->>'rule_b_rows')::int, other_rows = (v_m->>'other_rows')::int, looked = (v_m->>'looked')::int,
        checks = jsonb_build_object('wording_missing', v_m->'wording_missing', 'held_level_dated', v_m->'held_level_dated', 'calendar_missing', v_m->'calendar_missing',
                                    'months_with_two_dates', v_m->'months_with_two_dates'),
        reasons = array(select jsonb_array_elements_text(v_m->'reasons')), dates = v_m->'dates', sample = v_m->'sample', last_error = null,
        paused_at = case when v_m->>'status' = 'paused' and v_pause then now() else q.paused_at end, updated_at = now()
       where q.provider_id = r.provider_id;
      -- a listed university that fails a quality check is taken off the list (a stop, never a start)
      if v_m->>'status' = 'paused' and v_pause then
        select s.value into v_list from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'intake_dates.nearest_start_providers' for update;
        v_after := coalesce((select jsonb_agg(x) from jsonb_array_elements(v_list) x where x #>> '{}' <> r.provider_id::text), '[]'::jsonb);
        update pipeline.platform_toolset_settings set value = v_after,
               reason = left('Rule B qualification job: taken off after a failed check: ' || array_to_string(array(select jsonb_array_elements_text(v_m->'reasons')), '; '), 500), updated_at = now()
         where toolset_key = 'pipeline' and key = 'intake_dates.nearest_start_providers';
        insert into pipeline.admin_control_events(area, action, target, detail, actor)
        values ('toolsets', 'setting', 'pipeline.intake_dates.nearest_start_providers',
                jsonb_build_object('before', v_list, 'after', v_after, 'reason', 'intake-rule-b-qualify: failed check', 'checks', v_m - 'sample' - 'dates'), null);
        perform security.flag_raise_v1('provider', r.provider_id::text, r.provider_id, 'intakes', 'rule_b_paused',
          'Rule B paused for this university: ' || array_to_string(array(select jsonb_array_elements_text(v_m->'reasons')), '; '), 'hard', 'intake-rule-b-qualify', 'auto',
          v_m - 'sample', null, null);
      end if;
      v_out := v_out || jsonb_build_object('provider_id', r.provider_id, 'status', v_m->>'status', 'rule_b_rows', v_m->'rule_b_rows');
    exception when others then
      update pipeline.intake_rule_b_qualifications q set status = 'error', checked_at = now(), requested_at = null, last_error = left(sqlerrm, 500), updated_at = now()
       where q.provider_id = r.provider_id;
      v_out := v_out || jsonb_build_object('provider_id', r.provider_id, 'status', 'error', 'error', left(sqlerrm, 200));
    end;
    v_done := v_done + 1;
  end loop;
  return jsonb_build_object('tried', v_done, 'results', v_out);
end $_$;


ALTER FUNCTION "security"."intake_rule_b_qualify_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_rule_b_qualify_v1"() IS 'CF-247 F-INT (11 Nov 2026): job intake-rule-b-qualify. Tries requested and due universities (batch.intake_rule_b_qualify) and records the result; takes a failing listed university off the nearest-start list when intake_dates.rule_b_auto_pause is on. Never adds a university.';



CREATE OR REPLACE FUNCTION "security"."intake_start_date_status_v1"("p_intake_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when i.start_date is not null then 'known'
    when d.intake_id is null then
      case when exists (select 1 from pipeline.provider_policy_proposals pp
                         where pp.provider_id = c.provider_id and pp.kind = 'intake_calendar' and pp.status = 'approved')
           then 'not_yet_read' else 'no_official_calendar' end
    when d.reason ~* 'rolling|flexible start|start any ?time' then 'rolling'
    when d.next_action in ('human_decision_required', 'complete') then 'held_for_review'
    when d.next_action in ('calendar_needs_correction', 'awaiting_official_calendar') then 'no_official_calendar'
    when d.next_action = 'course_identity_unresolved' or d.reason ~* 'not proved to be the course''s own' then 'course_page_not_verified'
    when d.next_action = 'waiting_for_next_academic_year' then
      case when d.reason ~* 'does not state .* as (an|its own) intake' then 'not_on_course_page' else 'next_year_calendar_pending' end
    when d.next_action = 'reader_correction_needed' then 'not_yet_read'
    when d.reason ~* 'vocational or pathway|research degree' then 'own_calendar'
    when d.reason ~* 'names no study period' then 'month_only'
    else 'conflicting_evidence' end
  from catalogue.course_intakes i
  join catalogue.courses c on c.id = i.course_id
  left join pipeline.course_intake_dates d on d.intake_id = i.id
  where i.id = p_intake_id
$$;


ALTER FUNCTION "security"."intake_start_date_status_v1"("p_intake_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_start_date_status_v1"("p_intake_id" "uuid") IS 'R28 (Decision 277): why an intake has or has not an exact start date; closed list; read by Website API v3 only.';



CREATE OR REPLACE FUNCTION "security"."intake_ui_preview_v1"("p_scope" "text", "p_size" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare s jsonb; body jsonb; signature text; expires timestamptz;
begin
 s:=security.intake_ui_selection_v1(p_scope,p_size);
 expires:=now()+make_interval(secs=>security.pipeline_num_v1('run_now.preview_seconds',600)::int);
 body:=jsonb_build_object('scope',p_scope,'size',p_size,'requester',auth.uid(),'expires_at',expires,'fingerprint',encode(extensions.digest(s::text,'sha256'),'hex'));
 select encode(extensions.hmac(body::text,secret,'sha256'),'hex') into signature from pipeline.intake_ui_signing_key;
 return s||jsonb_build_object('as_at',now(),'expires_at',expires,'token',jsonb_build_object('body',body,'signature',signature)::text);
end $$;


ALTER FUNCTION "security"."intake_ui_preview_v1"("p_scope" "text", "p_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."intake_ui_scopes_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'active_courses',n) order by n desc,md5(id::text)),'[]')
 from (select p.id,coalesce(p.display_name,p.canonical_name) name,count(c.id) n
 from catalogue.providers p join ref.countries co on co.id=p.country_id and co.iso_alpha2='AU'
 join ref.provider_types t on t.id=p.provider_type_id and t.code='university'
 join catalogue.courses c on c.provider_id=p.id and c.lifecycle_status='active'
 where p.lifecycle_status='active' group by p.id,2 order by count(c.id) desc,md5(p.id::text)
 limit security.pipeline_num_v1('run_now.cohort_top_au_universities',10)::int) u
$$;


ALTER FUNCTION "security"."intake_ui_scopes_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."intake_ui_selection_v1"("p_scope" "text", "p_size" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare unis jsonb:=security.intake_ui_scopes_v1(); ids uuid[]; result jsonb; cap integer:=security.pipeline_num_v1('run_now.pilot_cap',20)::int;
begin
 if p_size is null or p_size<1 or p_size>cap then raise exception 'cohort size must be between 1 and %',cap; end if;
 if p_scope is null or not (p_scope='top-au' or exists(select 1 from jsonb_array_elements(unis) u where u->>'id'=p_scope)) then
   raise exception 'invalid scope: select within the approved top Australian universities'; end if;
 ids:=array(select c.id from catalogue.courses c where c.lifecycle_status='active' and c.provider_id in
   (select (u->>'id')::uuid from jsonb_array_elements(unis) u where p_scope='top-au' or u->>'id'=p_scope));
 with all_plan as materialized(
 select p.* from jsonb_array_elements(unis) u
 cross join lateral security.intake_dates_plan_v3(
 array(select c.id from catalogue.courses c where c.provider_id=(u->>'id')::uuid and c.lifecycle_status='active'),
 least(greatest(1,security.pipeline_num_v1('run_now.preview_rows_per_university',5)::int),greatest(1,security.pipeline_num_v1('run_now.cohort_scan_rows',1500)::int / greatest(jsonb_array_length(unis),1)))) p),
 plan as materialized(select * from all_plan where p_scope='top-au' or provider_id::text=p_scope),
 f as(select * from plan where outcome='filled'),
 c as(select course_id,min(provider_id::text)::uuid provider_id,
 array_remove(array[case when bool_or(new_year is not null) then 'year' end,case when bool_or(new_start is not null) then 'start_date' end,case when bool_or(new_deadline is not null) then 'application_deadline' end],null) fills,
 string_agg(distinct coalesce(start_precision,'-')||'/'||coalesce(deadline_kind,'-'),'+' order by coalesce(start_precision,'-')||'/'||coalesce(deadline_kind,'-')) pattern,
 jsonb_agg(jsonb_build_object('intake_id',intake_id,'proposal_id',proposal_id,'calendar_evidence_id',calendar_evidence_id,'calendar_url',calendar_url,
 'page_url',(select e.source_url from catalogue.course_intakes i join pipeline.evidence_artifacts e on e.id=i.evidence_id where i.id=intake_id),'periods',periods,'page_quote',page_quote,'start_quote',start_quote,'deadline_quote',deadline_quote,'deadline_kind',deadline_kind,
 'before',before_value,'planned',jsonb_build_object('year',new_year,'start_date',new_start,'application_deadline',new_deadline),'rule',rule) order by intake_id) at_selection
 from f group by course_id),
 r as(select c.*,row_number() over(partition by provider_id order by cardinality(fills) desc,md5(course_id::text)) rp,
 row_number() over(partition by pattern order by cardinality(fills) desc,md5(course_id::text)) rq from c),
 pick as(select r.*,row_number() over(order by rp,rq,cardinality(fills) desc,md5(course_id::text)) n from r)
 select jsonb_build_object('scope',p_scope,'size',p_size,'cap',cap,'scan_rows',security.pipeline_num_v1('run_now.cohort_scan_rows',1500),
 'universities',(select jsonb_agg(u||jsonb_build_object(
 'scan_limit',least(greatest(1,security.pipeline_num_v1('run_now.preview_rows_per_university',5)::int),greatest(1,security.pipeline_num_v1('run_now.cohort_scan_rows',1500)::int / greatest(jsonb_array_length(unis),1))),
 'rows_planned',(select count(*) from all_plan where provider_id=(u->>'id')::uuid),
 'eligible_courses',(select count(distinct course_id) from all_plan where provider_id=(u->>'id')::uuid and outcome='filled'),
 'eligible_values',(select count(*) from all_plan where provider_id=(u->>'id')::uuid and outcome='filled')) order by (u->>'active_courses')::int desc,md5(u->>'id')) from jsonb_array_elements(unis) u),'scope_courses',cardinality(ids),'rows_planned',(select count(*) from plan),
 'eligible_courses',(select count(distinct course_id) from f),'rows_eligible',(select count(*) from f),
 'skipped_by_reason',(select coalesce(jsonb_object_agg(reason,n),'{}') from(select coalesce(reason,outcome) reason,count(*) n from plan where outcome<>'filled' group by 1) x),
 'rule','Existing intake-dates-plan-v3 filled outcome: official stored page and approved calendar; independent equal-share scan per university; most missing fields first, round-robin universities and evidence patterns; no scope widening',
 'courses',coalesce((select jsonb_agg(jsonb_build_object('course_id',p.course_id,'provider_id',p.provider_id,'pick',p.n,'pattern',p.pattern,'fills',p.fills,
 'course_title',coalesce(cc.display_title,cc.canonical_title),'provider_name',coalesce(pp.display_name,pp.canonical_name),'course_url',cc.course_url,
 'eligibility_reason','The existing intake plan found supported missing values from the stored course wording and an approved calendar; its manual-lock, same-month and admission guards remain authoritative.',
 'at_selection',p.at_selection) order by p.n) from pick p join catalogue.courses cc on cc.id=p.course_id join catalogue.providers pp on pp.id=p.provider_id where p.n<=p_size),'[]')) into result;
 return result;
end $$;


ALTER FUNCTION "security"."intake_ui_selection_v1"("p_scope" "text", "p_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."intake_ui_values_match_v1"("p_after" "jsonb", "p_items" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
 select case when jsonb_typeof(p_items)='array' then exists(
 select 1 from jsonb_array_elements(p_items) i where not exists(
 select 1 from jsonb_each(p_after) a where a.value<>'null'::jsonb and i->>a.key is distinct from p_after->>a.key)) else null end
$$;


ALTER FUNCTION "security"."intake_ui_values_match_v1"("p_after" "jsonb", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."intake_wording_fp_v1"("p_course" "uuid", "p_evidence" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  return md5(coalesce((select string_agg(s, '|' order by s)
                         from (select distinct s from unnest(string_to_array(
                                 security.intake_page_wording_v1(p_course, p_evidence, (select e.source_url from pipeline.evidence_artifacts e where e.id = p_evidence)), ' | ')) s) z), ''));
end
$$;


ALTER FUNCTION "security"."intake_wording_fp_v1"("p_course" "uuid", "p_evidence" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."intake_wording_fp_v1"("p_course" "uuid", "p_evidence" "uuid") IS 'CF-247 F-INT (9 Nov 2026): md5 of the stored intake wording of a course page (security.intake_page_wording_v1, the same text the plan reads), order-insensitive. Part of the intake inputs fingerprint, so a page read again with new intake wording is looked at again and an unchanged page is not.';



CREATE OR REPLACE FUNCTION "security"."integration_alert_sync_v1"("p_issue" bigint, "p_observed" boolean, "p_actor" "text" DEFAULT 'integration-validate'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.integration_issues; v_key text;
begin
  select * into r from pipeline.integration_issues where id = p_issue;
  if not found then return; end if;
  v_key := 'integration:' || left(r.fingerprint, 200);
  if p_observed and r.severity = 'P0' and r.status <> 'closed' then
    insert into pipeline.platform_issues as i (check_key, severity, area, title, detail)
    values (v_key, 'critical', 'integration', left(r.issue_ref || ' ' || r.title, 300),
            jsonb_build_object('issue', r.issue_ref, 'fingerprint', r.fingerprint, 'workstream', r.workstream, 'next_step', left(r.expected, 300),
                               'resolve', 'Platform health › Integration queue'))
    on conflict (check_key) where resolved_at is null do update set last_seen = now(), occurrences = i.occurrences + 1;
    if r.alert_check_key is null then
      update pipeline.integration_issues set alert_check_key = v_key where id = r.id;
      insert into pipeline.integration_issue_events(issue_id, kind, actor, note) values (r.id, 'alert_opened', p_actor, v_key);
    end if;
  elsif r.alert_check_key is not null then
    update pipeline.platform_issues set resolved_at = now() where check_key = r.alert_check_key and resolved_at is null;
    if found then insert into pipeline.integration_issue_events(issue_id, kind, actor, note) values (r.id, 'alert_resolved', p_actor, 'condition no longer observed'); end if;
  end if;
end $$;


ALTER FUNCTION "security"."integration_alert_sync_v1"("p_issue" bigint, "p_observed" boolean, "p_actor" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."integration_deploy_check_v1"("p_release" "text", "p_migrations" "jsonb", "p_functions" "jsonb" DEFAULT '{}'::"jsonb", "p_since" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_jobs" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_since timestamptz := coalesce(p_since, now() - interval '30 minutes');  -- fixed: default window when the caller gives no deploy time
        v_scan int := security.pipeline_num_v1('integration.failed_runs_scan', 5000)::int;
        m record; f record; j record; v_live text; v_norm text; v_mig jsonb := '[]'::jsonb; v_fn jsonb := '[]'::jsonb; v_jobs jsonb := '[]'::jsonb;
        v_fail jsonb; v_http int := 0; v_ok boolean := true; v_issues text[] := '{}'; v_res jsonb; v_missing text[]; v_n int;
begin
  if coalesce(btrim(p_release), '') = '' then raise exception 'name the release' using errcode = '22023'; end if;
  -- migrations: applied, and the applied text is the file
  for m in select x->>'version' version, x->>'md5' md5 from jsonb_array_elements(coalesce(p_migrations, '[]'::jsonb)) x loop
    -- the raw text, and the text with carriage returns and trailing newlines removed (SS-015 Gate A F7: 11 versions differ only in those)
    select md5(array_to_string(s.statements, '')), md5(rtrim(replace(array_to_string(s.statements, ''), E'\r', ''), E'\n')) into v_live, v_norm
      from supabase_migrations.schema_migrations s where s.version = m.version;
    v_mig := v_mig || jsonb_build_object('version', m.version, 'expected', m.md5, 'live', v_live, 'live_normalised', v_norm,
                                         'ok', v_live is not null and m.md5 in (v_live, v_norm));
    if v_live is null or m.md5 not in (v_live, v_norm) then
      v_ok := false;
      v_res := security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'v3_migration:' || m.version,
        'title', 'Migration ' || m.version || ' ' || case when v_live is null then 'is not applied' else 'differs from its file' end, 'layer', 'Release',
        'subsystem', 'supabase_migrations.schema_migrations', 'failure', case when v_live is null then 'not in the applied migrations' else 'applied md5 ' || v_live || ', file md5 ' || m.md5 end,
        'expected', 'The deployed migration is the reviewed file, byte for byte', 'source', 'release ' || p_release, 'validation_layer', 'V3',
        'evidence', jsonb_build_object('release', p_release, 'version', m.version, 'expected', m.md5, 'live', v_live), 'severity', 'P1',
        'root_cause_class', 'deployment_drift', 'workstream', 'A8'), 'release controller');
      v_issues := v_issues || (v_res->>'issue_ref');
    end if;
  end loop;
  -- functions: live definition md5 against the expected one
  for f in select e.key sig, e.value #>> '{}' md5 from jsonb_each(coalesce(p_functions, '{}'::jsonb)) e loop
    v_live := null;
    begin v_live := md5(pg_get_functiondef(f.sig::regprocedure)); exception when others then v_live := null; end;
    v_fn := v_fn || jsonb_build_object('function', f.sig, 'expected', f.md5, 'live', v_live, 'ok', v_live is not null and v_live = f.md5);
    if v_live is null or v_live <> f.md5 then
      v_ok := false;
      v_res := security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'v3_function:' || f.sig,
        'title', 'Function ' || f.sig || ' ' || case when v_live is null then 'is missing' else 'differs from the release' end, 'layer', 'Release', 'subsystem', f.sig,
        'failure', case when v_live is null then 'not found live' else 'live md5 ' || v_live || ', expected ' || f.md5 end,
        'expected', 'The live definition is the one the release built and tested', 'source', 'release ' || p_release, 'validation_layer', 'V3',
        'evidence', jsonb_build_object('release', p_release, 'expected', f.md5, 'live', v_live), 'severity', 'P1', 'root_cause_class', 'deployment_drift', 'workstream', 'A8'), 'release controller');
      v_issues := v_issues || (v_res->>'issue_ref');
    end if;
  end loop;
  -- scheduled job compatibility: every function a job calls exists (by schema and name)
  for j in select c.jobname, c.command from cron.job c where c.active and (p_jobs is null or c.jobname = any (p_jobs)) loop
    select coalesce(array_agg(distinct x[1] || '.' || x[2]), '{}') into v_missing
      from regexp_matches(j.command, '([a-z_][a-z0-9_]*)\.([a-z_][a-z0-9_]*)\s*\(', 'g') x
     where x[1] not in ('cron', 'net', 'pg_catalog', 'extensions', 'vault')
       and not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = x[1] and p.proname = x[2]);
    if cardinality(v_missing) > 0 then
      v_ok := false;
      v_jobs := v_jobs || jsonb_build_object('job', j.jobname, 'missing', to_jsonb(v_missing));
      v_res := security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'v3_job:' || j.jobname,
        'title', 'Scheduled job ' || j.jobname || ' calls a function that does not exist', 'layer', 'Scheduling', 'subsystem', 'cron',
        'failure', 'missing: ' || array_to_string(v_missing, ', '), 'expected', 'Every active job calls functions that exist after the deploy',
        'source', 'release ' || p_release, 'validation_layer', 'V3', 'evidence', jsonb_build_object('release', p_release, 'missing', to_jsonb(v_missing)),
        'severity', 'P1', 'root_cause_class', 'deployment_drift', 'workstream', 'A7'), 'release controller');
      v_issues := v_issues || (v_res->>'issue_ref');
    end if;
  end loop;
  -- errors since the deploy
  select coalesce(jsonb_object_agg(x.jobname, x.n), '{}'::jsonb) into v_fail
    from (select c.jobname, count(*) n from (select d.jobid, d.status, d.start_time from cron.job_run_details d order by d.runid desc limit v_scan) d
            join cron.job c on c.jobid = d.jobid where d.status = 'failed' and d.start_time >= v_since group by c.jobname) x;
  begin
    execute 'select count(*) from net._http_response h where h.created >= $1 and (h.status_code >= 500 or h.timed_out or h.error_msg is not null)' into v_http using v_since;
  exception when others then v_http := null;
  end;
  select coalesce(sum(e.value::int), 0) into v_n from jsonb_each_text(v_fail) e;
  if v_n > 0 or coalesce(v_http, 0) > 0 then
    v_ok := false;
    v_res := security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'v3_errors:' || p_release,
      'title', 'Errors after release ' || p_release, 'layer', 'Release', 'subsystem', 'cron and pg_net',
      'failure', v_n || ' failed scheduler run(s) and ' || coalesce(v_http::text, 'unknown') || ' failed HTTP call(s) since ' || v_since,
      'expected', 'No new failures after a deploy', 'source', 'release ' || p_release, 'validation_layer', 'V3',
      'evidence', jsonb_build_object('release', p_release, 'since', v_since, 'failed_runs', v_fail, 'http_errors', v_http), 'severity', 'P2',
      'root_cause_class', 'unclassified', 'workstream', 'A7'), 'release controller');
    v_issues := v_issues || (v_res->>'issue_ref');
  end if;
  v_res := jsonb_build_object('release', p_release, 'ok', v_ok, 'since', v_since, 'migrations', v_mig, 'functions', v_fn, 'jobs_incompatible', v_jobs,
                              'failed_runs', v_fail, 'http_errors', v_http, 'issues', to_jsonb(v_issues));
  insert into pipeline.integration_deploy_checks(release, since, ok, result, issues) values (p_release, v_since, v_ok, v_res, v_issues);
  return v_res;
end $_$;


ALTER FUNCTION "security"."integration_deploy_check_v1"("p_release" "text", "p_migrations" "jsonb", "p_functions" "jsonb", "p_since" timestamp with time zone, "p_jobs" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."integration_deploy_check_v1"("p_release" "text", "p_migrations" "jsonb", "p_functions" "jsonb", "p_since" timestamp with time zone, "p_jobs" "text"[]) IS 'CF-247 mandate §4 V3: after each deploy the release controller records migration md5 against the file, function md5s, job compatibility and errors since the deploy; mismatches open integration issues';



CREATE OR REPLACE FUNCTION "security"."integration_issue_allowed_v1"("p_check" "text", "p_value" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce((select p_value = any (array(select m[1] from regexp_matches(pg_get_constraintdef(c.oid), '''([^'']*)''', 'g') m))
                     from pg_constraint c where c.conrelid = 'pipeline.integration_issues'::regclass and c.conname = p_check), true)
$$;


ALTER FUNCTION "security"."integration_issue_allowed_v1"("p_check" "text", "p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."integration_issue_close_v1"("p_issue" bigint, "p_actor" "text", "p_verification" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.integration_issues; v_from text;
begin
  if coalesce(btrim(p_actor), '') = '' then raise exception 'name who verified the fix' using errcode = '22023'; end if;
  if p_verification is null or jsonb_typeof(p_verification) <> 'object' or coalesce(p_verification->>'outcome', '') <> 'passed'
     or length(btrim(coalesce(p_verification->>'evidence', ''))) < 20
     or (coalesce(p_verification->>'checked_at', '') = '' and coalesce(p_verification->>'reference', '') = '') then
    raise exception 'closing needs production verification evidence: outcome passed, what was checked (evidence) and when or where (checked_at or reference)' using errcode = '22023';
  end if;
  select * into r from pipeline.integration_issues where id = p_issue for update;
  if not found then raise exception 'no integration issue %', p_issue using errcode = 'P0002'; end if;
  if r.status = 'closed' then return jsonb_build_object('id', r.id, 'issue_ref', r.issue_ref, 'status', 'closed', 'already', true); end if;
  v_from := r.status;
  update pipeline.integration_issues i set status = 'closed', closed_at = now(), verification_outcome = 'passed', verification_evidence = p_verification,
         verified_at = coalesce((p_verification->>'checked_at')::timestamptz, now()), verified_by = p_actor, updated_at = now()
   where i.id = p_issue returning * into r;
  insert into pipeline.integration_issue_events(issue_id, kind, from_status, to_status, actor, note, detail)
  values (r.id, 'closed', v_from, 'closed', p_actor, left(p_verification->>'evidence', 500), p_verification);
  -- a P0 alert issue still open on Platform health closes with it (platform-alerts sends the one recovery notice)
  if r.alert_check_key is not null then
    update pipeline.platform_issues set resolved_at = now() where check_key = r.alert_check_key and resolved_at is null;
    if found then insert into pipeline.integration_issue_events(issue_id, kind, actor, note) values (r.id, 'alert_resolved', p_actor, 'closed'); end if;
  end if;
  return jsonb_build_object('id', r.id, 'issue_ref', r.issue_ref, 'status', 'closed', 'from', v_from);
end $$;


ALTER FUNCTION "security"."integration_issue_close_v1"("p_issue" bigint, "p_actor" "text", "p_verification" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."integration_issue_severity_v1"("p_issue" bigint, "p_severity" "text", "p_reason" "text", "p_authority" "text", "p_evidence" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.integration_issues; v_min int := security.pipeline_num_v1('recovery.severity_reason_min_chars', 30)::int; v_dec jsonb;
begin
  if p_severity not in ('P0', 'P1', 'P2') then raise exception 'severity must be P0, P1 or P2' using errcode = '22023'; end if;
  if length(btrim(coalesce(p_reason, ''))) < v_min then raise exception 'give an evidence-based reason of at least % characters', v_min using errcode = '22023'; end if;
  if length(btrim(coalesce(p_authority, ''))) < 5 then raise exception 'name the decision authority (who decided, and the decision)' using errcode = '22023'; end if;
  if p_evidence is null or jsonb_typeof(p_evidence) <> 'object' or p_evidence = '{}'::jsonb then raise exception 'give the evidence (an object)' using errcode = '22023'; end if;
  select * into r from pipeline.integration_issues where id = p_issue for update;
  if not found then raise exception 'no integration issue %', p_issue using errcode = 'P0002'; end if;
  if r.status = 'closed' then raise exception '% is closed: a closed issue keeps its severity (reopen it through its own evidence first)', r.issue_ref using errcode = '22023'; end if;
  if r.severity = p_severity then return jsonb_build_object('id', r.id, 'issue_ref', r.issue_ref, 'severity', r.severity, 'changed', false); end if;
  v_dec := jsonb_build_object('from', r.severity, 'to', p_severity, 'reason', btrim(p_reason), 'authority', btrim(p_authority), 'evidence', p_evidence, 'at', now(),
                              'direction', case when p_severity < r.severity then 'raised' else 'lowered' end);
  update pipeline.integration_issues set severity = p_severity, severity_decided_at = now(), severity_decided_by = btrim(p_authority), severity_decision = v_dec,
         evidence = evidence || jsonb_build_object('severity_decisions', coalesce(evidence->'severity_decisions', '[]'::jsonb) || jsonb_build_array(v_dec)), updated_at = now()
   where id = r.id;
  insert into pipeline.integration_issue_events(issue_id, kind, from_status, to_status, actor, note, detail)
  values (r.id, case when p_severity < r.severity then 'escalated' else 'updated' end, r.status, r.status, btrim(p_authority),
          'Severity ' || r.severity || ' -> ' || p_severity || ' (governed decision): ' || left(btrim(p_reason), 400), jsonb_build_object('severity_decision', v_dec));
  return jsonb_build_object('id', r.id, 'issue_ref', r.issue_ref, 'from', r.severity, 'severity', p_severity, 'changed', true, 'status', r.status);
end $$;


ALTER FUNCTION "security"."integration_issue_severity_v1"("p_issue" bigint, "p_severity" "text", "p_reason" "text", "p_authority" "text", "p_evidence" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."integration_issue_severity_v1"("p_issue" bigint, "p_severity" "text", "p_reason" "text", "p_authority" "text", "p_evidence" "jsonb") IS 'CF-247 direction 4 Nov 2026 10:00 §10: governed severity change with reason, authority, evidence and a history event; never closes or recreates';



CREATE OR REPLACE FUNCTION "security"."integration_issue_transition_v1"("p_issue" bigint, "p_to" "text", "p_actor" "text", "p_note" "text" DEFAULT NULL::"text", "p_patch" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.integration_issues; v_from text;
        v_next jsonb := '{"detected": ["triaged", "assigned", "in_progress"], "triaged": ["assigned", "in_progress"], "assigned": ["in_progress", "triaged"],
                          "in_progress": ["code_ready", "triaged", "assigned"], "code_ready": ["integration_testing", "in_progress"],
                          "integration_testing": ["deployed", "in_progress", "triaged"], "deployed": ["production_verification", "in_progress", "triaged"],
                          "production_verification": ["in_progress", "triaged"], "reopened": ["triaged", "assigned", "in_progress"]}'::jsonb;
begin
  if coalesce(btrim(p_actor), '') = '' then raise exception 'name who is changing the issue' using errcode = '22023'; end if;
  select * into r from pipeline.integration_issues where id = p_issue for update;
  if not found then raise exception 'no integration issue %', p_issue using errcode = 'P0002'; end if;
  v_from := r.status;
  if p_to = 'closed' then raise exception 'an issue is closed only with verification evidence (security.integration_issue_close_v1)' using errcode = '22023'; end if;
  if p_to is not null and p_to <> v_from then
    if not coalesce(v_next->v_from ? p_to, false) then raise exception 'an issue cannot move from % to %', v_from, p_to using errcode = '22023'; end if;
    if p_to in ('in_progress', 'triaged') and v_from in ('code_ready', 'integration_testing', 'deployed', 'production_verification') and length(btrim(coalesce(p_note, ''))) < 10 then
      raise exception 'failed validation returns the issue with its new evidence: describe what failed' using errcode = '22023';
    end if;
  end if;
  if p_patch ? 'severity' and p_patch->>'severity' not in ('P0', 'P1', 'P2') then raise exception 'severity must be P0, P1 or P2' using errcode = '22023'; end if;
  update pipeline.integration_issues i set
    status = coalesce(nullif(p_to, ''), i.status),
    severity = coalesce(p_patch->>'severity', i.severity), workstream = coalesce(p_patch->>'workstream', i.workstream),
    root_cause_class = coalesce(p_patch->>'root_cause_class', i.root_cause_class), impact = coalesce(p_patch->>'impact', i.impact),
    assignee = coalesce(p_patch->>'assignee', i.assignee), fix_commit = coalesce(p_patch->>'fix_commit', i.fix_commit),
    fix_migration = coalesce(p_patch->>'fix_migration', i.fix_migration), deployed_version = coalesce(p_patch->>'deployed_version', i.deployed_version),
    aer_root_cause_ref = coalesce(nullif(p_patch->>'aer_root_cause_ref', ''), i.aer_root_cause_ref),
    blocked_by = case when p_patch ? 'blocked_by' then coalesce((select array_agg(x::bigint) from jsonb_array_elements_text(p_patch->'blocked_by') x), '{}') else i.blocked_by end,
    depends_on = case when p_patch ? 'depends_on' then coalesce((select array_agg(x) from jsonb_array_elements_text(p_patch->'depends_on') x), '{}') else i.depends_on end,
    evidence = i.evidence || coalesce(p_patch->'evidence', '{}'::jsonb),
    verification_outcome = case when p_to in ('in_progress', 'triaged') and v_from in ('integration_testing', 'deployed', 'production_verification') then 'failed' else i.verification_outcome end,
    updated_at = now()
   where i.id = p_issue returning * into r;
  insert into pipeline.integration_issue_events(issue_id, kind, from_status, to_status, actor, note, detail)
  values (r.id, case when r.status <> v_from then 'status' else 'updated' end, v_from, r.status, p_actor, p_note, coalesce(p_patch, '{}'::jsonb));
  return jsonb_build_object('id', r.id, 'issue_ref', r.issue_ref, 'from', v_from, 'status', r.status);
end $$;


ALTER FUNCTION "security"."integration_issue_transition_v1"("p_issue" bigint, "p_to" "text", "p_actor" "text", "p_note" "text", "p_patch" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."integration_issue_upsert_v1"("p" "jsonb", "p_actor" "text" DEFAULT 'integration-validate'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_fp text := btrim(coalesce(p->>'fingerprint', ''));
        v_max int := security.pipeline_num_v1('integration.entity_ids_max', 500)::int;
        v_sev text := coalesce(nullif(p->>'severity', ''), 'P2');
        v_prov uuid[] := coalesce((select array_agg(distinct x::uuid) from jsonb_array_elements_text(coalesce(p->'provider_ids', '[]'::jsonb)) x), '{}');
        v_course uuid[] := coalesce((select array_agg(distinct x::uuid) from jsonb_array_elements_text(coalesce(p->'course_ids', '[]'::jsonb)) x), '{}');
        v_cc text[] := coalesce((select array_agg(distinct upper(x)) from jsonb_array_elements_text(coalesce(p->'country_codes', '[]'::jsonb)) x), '{}');
        v_refs text[] := coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(p->'evidence_refs', '[]'::jsonb)) x), '{}');
        v_deps text[] := coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(p->'depends_on', '[]'::jsonb)) x), '{}');
        v_blk bigint[];
        r pipeline.integration_issues; v_new_prov uuid[]; v_new_course uuid[]; v_more boolean; v_action text; v_status text;
        v_rcc text; v_ws text; v_vl text; v_unmapped jsonb := '{}'::jsonb;
begin
  if v_fp = '' then raise exception 'an integration issue needs a fingerprint' using errcode = '22023'; end if;
  if v_sev not in ('P0', 'P1', 'P2') then raise exception 'severity must be P0, P1 or P2' using errcode = '22023'; end if;
  select coalesce(array_agg(i.id), '{}') into v_blk from pipeline.integration_issues i
   where i.fingerprint in (select jsonb_array_elements_text(coalesce(p->'blocked_by_fingerprints', '[]'::jsonb)));
  perform pg_advisory_xact_lock(hashtext('cf247:integration_issue:' || v_fp));  -- fixed: one writer per fingerprint
  select * into r from pipeline.integration_issues i where i.fingerprint = v_fp for update;
  if not found then
    v_status := coalesce(nullif(p->>'status', ''), 'detected');
    if v_status not in ('detected', 'triaged', 'assigned', 'in_progress') then raise exception 'a new issue starts as detected, triaged, assigned or in_progress' using errcode = '22023'; end if;
    -- 4 Nov 2026 (SS-021 F2, IQ-00077): a root cause class, workstream or validation layer the queue's checks refuse is mapped (unclassified, A10,
    -- manual) and the value sent is kept in evidence.unmapped, so a reporting job's own issue write never aborts its run
    v_rcc := coalesce(nullif(p->>'root_cause_class', ''), 'unclassified');
    v_ws := coalesce(nullif(p->>'workstream', ''), 'A10');
    v_vl := coalesce(nullif(p->>'validation_layer', ''), 'manual');
    if not security.integration_issue_allowed_v1('integration_issues_root_cause_class_check', v_rcc) then
      v_unmapped := v_unmapped || jsonb_build_object('root_cause_class', v_rcc); v_rcc := 'unclassified'; end if;
    if not security.integration_issue_allowed_v1('integration_issues_workstream_check', v_ws) then
      v_unmapped := v_unmapped || jsonb_build_object('workstream', v_ws); v_ws := 'A10'; end if;
    if not security.integration_issue_allowed_v1('integration_issues_validation_layer_check', v_vl) then
      v_unmapped := v_unmapped || jsonb_build_object('validation_layer', v_vl); v_vl := 'manual'; end if;
    if v_unmapped <> '{}'::jsonb then v_unmapped := jsonb_build_object('unmapped', v_unmapped); end if;
    insert into pipeline.integration_issues(fingerprint, title, layer, subsystem, provider_ids, course_ids, country_codes, entities_truncated, failure, expected,
           detection_source, validation_layer, evidence, evidence_refs, root_cause_class, severity, impact, workstream, blocked_by, depends_on, status, assignee,
           fix_commit, fix_migration, aer_root_cause_ref, detected_at, last_observed_at)
    values (v_fp, left(coalesce(p->>'title', v_fp), 300), coalesce(nullif(p->>'layer', ''), 'Platform'), p->>'subsystem',
           v_prov[1:v_max], v_course[1:v_max], v_cc, cardinality(v_prov) > v_max or cardinality(v_course) > v_max,
           coalesce(nullif(p->>'failure', ''), 'not stated'), coalesce(nullif(p->>'expected', ''), 'not stated'),
           coalesce(nullif(p->>'source', ''), p_actor), v_vl, coalesce(p->'evidence', '{}'::jsonb) || v_unmapped, v_refs,
           v_rcc, v_sev, p->>'impact', v_ws, v_blk, v_deps,
           v_status, p->>'assignee', p->>'fix_commit', p->>'fix_migration', nullif(p->>'aer_root_cause_ref', ''),
           coalesce((p->>'detected_at')::timestamptz, now()), now())
    returning * into r;
    insert into pipeline.integration_issue_events(issue_id, kind, to_status, actor, note, detail)
    values (r.id, 'detected', r.status, p_actor, left(r.failure, 500), jsonb_build_object('severity', r.severity, 'workstream', r.workstream, 'source', r.detection_source,
            'providers', cardinality(v_prov), 'courses', cardinality(v_course), 'evidence', r.evidence));
    return jsonb_build_object('id', r.id, 'issue_ref', r.issue_ref, 'action', 'created', 'status', r.status, 'severity', r.severity);
  end if;

  select coalesce(array_agg(x), '{}') into v_new_prov from unnest(v_prov) x where not x = any(r.provider_ids);
  select coalesce(array_agg(x), '{}') into v_new_course from unnest(v_course) x where not x = any(r.course_ids);
  v_more := r.entities_truncated or cardinality(r.provider_ids) + cardinality(v_new_prov) > v_max or cardinality(r.course_ids) + cardinality(v_new_course) > v_max;

  if r.status = 'closed' and coalesce((p->>'observed_at')::timestamptz, now()) <= r.closed_at then
    -- P0 IQ-00067 (3 Nov 2026 16:51): evidence observed at or before the close (a trailing 24-hour count, an old failed run) is not a
    -- recurrence: the issue stays closed and unchanged
    return jsonb_build_object('id', r.id, 'issue_ref', r.issue_ref, 'action', 'closed_evidence_before_close', 'status', r.status,
                              'observed_at', coalesce((p->>'observed_at')::timestamptz, now()), 'closed_at', r.closed_at);
  end if;
  if r.status = 'closed' then
    -- §5: the same issue after closure reopens the original row as a regression
    update pipeline.integration_issues i set status = 'reopened', regression_count = i.regression_count + 1, reopened_at = now(), retry_count = i.retry_count + 1,
           last_observed_at = now(), condition_cleared_at = null, verification_outcome = 'regressed',
           severity = case when v_sev < i.severity and i.severity_decided_at is null then v_sev else i.severity end,
           provider_ids = (i.provider_ids || v_new_prov)[1:v_max], course_ids = (i.course_ids || v_new_course)[1:v_max], entities_truncated = v_more,
           country_codes = (select coalesce(array_agg(distinct c), '{}') from unnest(i.country_codes || v_cc) c),
           evidence = i.evidence || coalesce(p->'evidence', '{}'::jsonb), evidence_refs = (select coalesce(array_agg(distinct e), '{}') from unnest(i.evidence_refs || v_refs) e),
           updated_at = now()
     where i.id = r.id returning * into r;
    insert into pipeline.integration_issue_events(issue_id, kind, from_status, to_status, actor, note, detail)
    values (r.id, 'reopened_regression', 'closed', 'reopened', p_actor, left(coalesce(p->>'failure', r.failure), 500),
            jsonb_build_object('regression_count', r.regression_count, 'evidence', coalesce(p->'evidence', '{}'::jsonb), 'new_providers', cardinality(v_new_prov), 'new_courses', cardinality(v_new_course),
                               'observed_at', coalesce((p->>'observed_at')::timestamptz, now()), 'closed_at', r.closed_at));
    return jsonb_build_object('id', r.id, 'issue_ref', r.issue_ref, 'action', 'reopened', 'status', r.status, 'severity', r.severity, 'regression_count', r.regression_count);
  end if;

  v_action := case when v_sev < r.severity and r.severity_decided_at is null then 'escalated' when cardinality(v_new_prov) + cardinality(v_new_course) > 0 then 'observed'
                   when r.condition_cleared_at is not null then 'observed_again' else 'unchanged' end;
  update pipeline.integration_issues i set retry_count = i.retry_count + 1, last_observed_at = now(), condition_cleared_at = null,
         severity = case when v_sev < i.severity and i.severity_decided_at is null then v_sev else i.severity end,
         provider_ids = (i.provider_ids || v_new_prov)[1:v_max], course_ids = (i.course_ids || v_new_course)[1:v_max], entities_truncated = v_more,
         country_codes = case when v_cc <@ i.country_codes then i.country_codes else (select coalesce(array_agg(distinct c), '{}') from unnest(i.country_codes || v_cc) c) end,
         evidence = case when v_action = 'unchanged' then i.evidence else i.evidence || coalesce(p->'evidence', '{}'::jsonb) end,
         updated_at = case when v_action = 'unchanged' then i.updated_at else now() end
   where i.id = r.id returning * into r;
  if v_action <> 'unchanged' then
    insert into pipeline.integration_issue_events(issue_id, kind, from_status, to_status, actor, note, detail)
    values (r.id, v_action, r.status, r.status, p_actor, null, jsonb_build_object('severity', r.severity, 'new_providers', cardinality(v_new_prov), 'new_courses', cardinality(v_new_course),
            'evidence', coalesce(p->'evidence', '{}'::jsonb)));
  end if;
  return jsonb_build_object('id', r.id, 'issue_ref', r.issue_ref, 'action', v_action, 'status', r.status, 'severity', r.severity, 'retry_count', r.retry_count);
end $$;


ALTER FUNCTION "security"."integration_issue_upsert_v1"("p" "jsonb", "p_actor" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."integration_issue_upsert_v1"("p" "jsonb", "p_actor" "text") IS 'CF-247 mandate §3/§5: create or update an integration issue by fingerprint; unchanged problems are not duplicated; a recurrence after Closed reopens as a regression';



CREATE OR REPLACE FUNCTION "security"."integration_l4_pending_v1"("p_max" integer) RETURNS TABLE("id" "uuid", "entity_type" "text", "entity_id" "uuid", "field_code" "text", "proposed_value" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select i.id, i.entity_type, i.entity_id, i.field_code, i.proposed_value, i.created_at from pipeline.layer4_review_items i
   where i.status = 'pending' order by i.created_at desc limit p_max
$$;


ALTER FUNCTION "security"."integration_l4_pending_v1"("p_max" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."integration_mode_guard_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if coalesce(current_setting('cf247.integration_mode_path', true), '') <> 'on' then
    raise exception 'the operating mode is changed only by the Integration Controller (security.integration_mode_set_v1)' using errcode = '42501';
  end if;
  return new;
end $$;


ALTER FUNCTION "security"."integration_mode_guard_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."integration_mode_set_v1"("p_mode" integer, "p_controller" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_old int; v_open int;
begin
  if p_mode not in (1, 2) then raise exception 'the operating mode is 1 (Active Remediation) or 2 (Steady-State Monitoring)' using errcode = '22023'; end if;
  if length(btrim(coalesce(p_controller, ''))) < 3 or length(btrim(coalesce(p_reason, ''))) < 10 then
    raise exception 'name the Integration Controller and give the reason (kept in the audit log)' using errcode = '22023';
  end if;
  select mode into v_old from pipeline.integration_operating_mode where id = 1 for update;
  if p_mode = 2 then
    select count(*) into v_open from pipeline.integration_issues where status <> 'closed' and severity in ('P0', 'P1');
    if v_open > 0 then raise exception 'Mode 2 needs programme acceptance: % P0/P1 integration issue(s) are still open', v_open using errcode = '22023'; end if;
  end if;
  perform set_config('cf247.integration_mode_path', 'on', true);
  insert into pipeline.integration_operating_mode as m(id, mode, set_by, set_at, reason) values (1, p_mode, p_controller, now(), p_reason)
  on conflict (id) do update set mode = excluded.mode, set_by = excluded.set_by, set_at = excluded.set_at, reason = excluded.reason;
  perform set_config('cf247.integration_mode_path', '', true);
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('integration', 'operating_mode', 'pipeline.integration_operating_mode', jsonb_build_object('from', v_old, 'to', p_mode, 'set_by', p_controller, 'reason', p_reason), null);
  return jsonb_build_object('from', v_old, 'mode', p_mode, 'set_by', p_controller);
end $$;


ALTER FUNCTION "security"."integration_mode_set_v1"("p_mode" integer, "p_controller" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."integration_validate_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_t0 timestamptz := clock_timestamp(); v_ok text[] := '{}'; v_seen text[] := '{}'; v_out jsonb := '{}'::jsonb; v_err jsonb := '{}'::jsonb;
        v_scan int := security.pipeline_num_v1('integration.failed_runs_scan', 5000)::int;
        v_back interval := make_interval(hours => security.pipeline_num_v1('integration.first_run_lookback_hours', 24)::int);
        v_lease interval := make_interval(mins => security.pipeline_num_v1('integration.lease_stale_minutes', 60)::int);
        v_draft interval := make_interval(hours => security.pipeline_num_v1('integration.draft_stuck_hours', 24)::int);
        v_l4max int := security.pipeline_num_v1('integration.l4_pending_max', 5000)::int;
        v_inmax int := security.pipeline_num_v1('integration.inactive_courses_max', 20000)::int;
        s pipeline.integration_validate_state; r record; v_n bigint; v_m bigint; v_id bigint; v_ts timestamptz; v_res jsonb; v_num numeric; v_num2 numeric;
        v_pend int := 0; v_trunc boolean := false; v_res2 jsonb;
begin
  -- 0. Platform health and queue-watch output: their open issues (not this queue's own P0 rows) ----------------------------------------
  begin
    v_n := 0;
    -- P0 IQ-00067: when the evidence was observed: a scheduler failure by its job's last failed run (a 24-hour count stays open long after);
    -- other health issues by their last observation
    for r in select p.check_key, p.severity, p.area, p.title, p.detail, p.first_seen,
                    case when p.check_key like 'cron:failed:%'
                         then coalesce((select max(x.start_time) from (select d.jobid, d.status, d.start_time from cron.job_run_details d order by d.runid desc limit v_scan) x
                                          join cron.job j on j.jobid = x.jobid where j.jobname = substr(p.check_key, 13) and x.status = 'failed'), p.first_seen)
                         else p.last_seen end observed_at
               from pipeline.platform_issues p
              where p.resolved_at is null and p.severity in ('critical', 'warning') and p.check_key not like 'integration:%' loop
      v_res := security.integration_issue_upsert_v1(jsonb_build_object(
        'fingerprint', case when r.check_key like 'cron:failed:%' then 'job_failed:' || substr(r.check_key, 13) else 'health:' || r.check_key end,
        'title', r.title, 'layer', case when r.area in ('scheduled jobs', 'edge functions') then 'Scheduling' when r.area = 'search/API' then 'Search/API'
                                        when r.area in ('coverage sweep', 'scholarships') then 'Layer 2' else 'Platform' end,
        'subsystem', r.area, 'failure', r.title, 'expected', coalesce(r.detail->>'next_step', 'The Platform health check passes'),
        'source', case when r.check_key like 'queue_watch%' then 'queue-watch' else 'platform-health' end, 'validation_layer', 'V4',
        'evidence', jsonb_build_object('platform_issue', r.check_key, 'first_seen', r.first_seen, 'detail', r.detail), 'observed_at', r.observed_at,
        'severity', case r.severity when 'critical' then 'P1' else 'P2' end, 'root_cause_class', 'unclassified',
        'workstream', case when r.check_key like 'queue_watch%' or r.area in ('scheduled jobs', 'edge functions') then 'A7' when r.area = 'search/API' then 'A8'
                           when r.area in ('coverage sweep', 'scholarships') then 'A2' else 'A9' end), 'integration-validate');
      v_seen := v_seen || (case when r.check_key like 'cron:failed:%' then 'job_failed:' || substr(r.check_key, 13) else 'health:' || r.check_key end);
      v_n := v_n + 1;
    end loop;
    v_ok := v_ok || 'health'::text; v_out := v_out || jsonb_build_object('health', v_n);
  exception when others then v_err := v_err || jsonb_build_object('health', left(sqlerrm, 300));
  end;

  -- 1. failed job runs, newer than the last run looked at (newest runs only) ------------------------------------------------------------
  begin
    select * into s from pipeline.integration_validate_state where check_key = 'job_failed';
    v_m := null; v_n := 0;
    for r in with d as (select x.runid, x.jobid, x.status, x.start_time, x.return_message from cron.job_run_details x order by x.runid desc limit v_scan)
             select j.jobname, count(*) n, max(d.runid) last_runid, max(d.start_time) last_at, (array_agg(left(d.return_message, 300) order by d.runid desc))[1] msg
               from d join cron.job j on j.jobid = d.jobid
              where d.status = 'failed' and d.runid > coalesce(s.watermark_id, 0) and (s.watermark_id is not null or d.start_time >= now() - v_back)
              group by j.jobname loop
      perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'job_failed:' || r.jobname,
        'title', 'Scheduled job ' || r.jobname || ' has failed runs', 'layer', 'Scheduling', 'subsystem', 'cron', 'failure', r.n || ' failed run(s) of ' || r.jobname || ', the last at ' || r.last_at || ': ' || coalesce(r.msg, 'no message'),
        'expected', 'Every run of an active scheduled job succeeds (target T1: 0 failed runs a day)', 'source', 'integration-validate', 'validation_layer', 'V4',
        'evidence', jsonb_build_object('failed_runs', r.n, 'last_runid', r.last_runid, 'last_at', r.last_at, 'message', r.msg), 'observed_at', r.last_at, 'severity', 'P1',
        'root_cause_class', 'unclassified', 'workstream', 'A7'), 'integration-validate');
      v_seen := v_seen || ('job_failed:' || r.jobname); v_n := v_n + 1;
    end loop;
    select max(x.runid) into v_m from (select runid from cron.job_run_details order by runid desc limit 1) x;
    insert into pipeline.integration_validate_state as t(check_key, last_run_at, watermark_id, last_found) values ('job_failed', now(), v_m, v_n)
    on conflict (check_key) do update set last_run_at = now(), watermark_id = coalesce(excluded.watermark_id, t.watermark_id), last_found = excluded.last_found, last_error = null;
    v_ok := v_ok || 'job_failed'::text; v_out := v_out || jsonb_build_object('job_failed', v_n);
  exception when others then v_err := v_err || jsonb_build_object('job_failed', left(sqlerrm, 300));
  end;

  -- 2. stale leases in the watched work tables ------------------------------------------------------------------------------------------
  begin
    v_n := 0;
    for r in select w.* from pipeline.integration_lease_watch w loop
      begin
        execute format('select count(*), min(%1$I) from %2$s where %3$s and %1$I < now() - $1', r.lease_column, r.table_name, r.leased_predicate) into v_m, v_ts using v_lease;
      exception when others then
        v_err := v_err || jsonb_build_object('stale_lease:' || r.table_name, left(sqlerrm, 200)); v_m := 0;
        v_seen := v_seen || ('stale_lease:' || r.table_name);  -- not read: its open issue is not taken as cleared
      end;
      if v_m > 0 then
        perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'stale_lease:' || r.table_name,
          'title', 'Stale leases in ' || r.table_name, 'layer', 'Scheduling', 'subsystem', r.table_name,
          'failure', v_m || ' item(s) still leased more than ' || security.pipeline_num_v1('integration.lease_stale_minutes', 60) || ' minutes after the lease ended (oldest lease end ' || v_ts || ')',
          'expected', 'An expired lease is reclaimed by the next claim or released', 'source', 'integration-validate', 'validation_layer', 'V4',
          'evidence', jsonb_build_object('items', v_m, 'oldest_lease_end', v_ts, 'predicate', r.leased_predicate), 'severity', 'P1', 'root_cause_class', 'queue_or_lease',
          'workstream', r.workstream), 'integration-validate');
        v_seen := v_seen || ('stale_lease:' || r.table_name); v_n := v_n + 1;
      end if;
    end loop;
    v_ok := v_ok || 'stale_lease'::text; v_out := v_out || jsonb_build_object('stale_lease', v_n);
  exception when others then v_err := v_err || jsonb_build_object('stale_lease', left(sqlerrm, 300));
  end;

  -- 3. adapter drafts stuck in capture or proposal ----------------------------------------------------------------------------------
  begin
    v_n := 0;
    for r in select d.status, count(*) n, array_agg(distinct d.provider_id) prov, min(d.updated_at) oldest
               from pipeline.uni_adapter_drafts d where d.status in ('capturing', 'proposing') and d.updated_at < now() - v_draft group by d.status loop
      perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'draft_stuck:' || r.status,
        'title', 'Adapter drafts stuck in ' || r.status, 'layer', 'Adapters', 'subsystem', 'pipeline.uni_adapter_drafts',
        'failure', r.n || ' draft(s) in ' || r.status || ' unchanged since ' || r.oldest, 'expected', 'A draft moves on from ' || r.status || ' (captured, proposed or error) within '
          || security.pipeline_num_v1('integration.draft_stuck_hours', 24) || ' hours',
        'source', 'integration-validate', 'validation_layer', 'V4', 'provider_ids', to_jsonb(r.prov), 'evidence', jsonb_build_object('drafts', r.n, 'oldest_update', r.oldest),
        'severity', 'P2', 'root_cause_class', 'queue_or_lease', 'workstream', 'A3'), 'integration-validate');
      v_seen := v_seen || ('draft_stuck:' || r.status); v_n := v_n + 1;
    end loop;
    v_ok := v_ok || 'draft_stuck'::text; v_out := v_out || jsonb_build_object('draft_stuck', v_n);
  exception when others then v_err := v_err || jsonb_build_object('draft_stuck', left(sqlerrm, 300));
  end;

  -- 4-6, 9. Layer 4: pending items (newest first, bounded) -----------------------------------------------------------------------------
  begin
    select count(*) into v_pend from security.integration_l4_pending_v1(v_l4max);
    v_trunc := v_pend >= v_l4max;
    -- duplicates: more than one pending item for the same entity and field
    v_n := 0;
    for r in select p.field_code, count(*) groups, sum(p.n) items, array_agg(p.entity_id) ents, bool_or(p.entity_type = 'course') is_course
               from (select entity_type, entity_id, field_code, count(*) n from security.integration_l4_pending_v1(v_l4max) group by 1, 2, 3 having count(*) > 1) p group by p.field_code loop
      perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'l4_duplicate:' || r.field_code,
        'title', 'Duplicate pending Layer 4 items (' || r.field_code || ')', 'layer', 'Layer 4', 'subsystem', 'pipeline.layer4_review_items',
        'failure', r.items || ' pending items in ' || r.groups || ' group(s) share the same entity and field', 'expected', 'At most one pending item per entity and field',
        'source', 'integration-validate', 'validation_layer', 'V4', 'course_ids', case when r.is_course then to_jsonb(r.ents) else '[]'::jsonb end,
        'provider_ids', case when r.is_course then '[]'::jsonb else to_jsonb(r.ents) end,
        'evidence', jsonb_build_object('groups', r.groups, 'items', r.items, 'pending_examined', v_pend, 'partly_checked', v_trunc), 'severity', 'P1', 'root_cause_class', 'code_defect', 'workstream', 'A4'), 'integration-validate');
      v_seen := v_seen || ('l4_duplicate:' || r.field_code); v_n := v_n + 1;
    end loop;
    v_out := v_out || jsonb_build_object('l4_duplicate', v_n);
    -- orphans: the entity is gone, not active, or belongs to an archived provider
    v_n := 0;
    for r in select p.field_code, count(*) n, array_agg(p.entity_id) filter (where p.entity_type = 'course') courses,
                    array_agg(coalesce(c.provider_id, p.entity_id)) filter (where pr.id is not null or p.entity_type = 'provider') provs
               from security.integration_l4_pending_v1(v_l4max) p
               left join catalogue.courses c on p.entity_type = 'course' and c.id = p.entity_id
               left join catalogue.providers pr on pr.id = case when p.entity_type = 'course' then c.provider_id when p.entity_type = 'provider' then p.entity_id end
              where (p.entity_type = 'course' and (c.id is null or c.lifecycle_status is distinct from 'active' or pr.lifecycle_status is distinct from 'active'))
                 or (p.entity_type = 'provider' and (pr.id is null or pr.lifecycle_status is distinct from 'active'))
              group by p.field_code loop
      perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'l4_orphan:' || r.field_code,
        'title', 'Orphan pending Layer 4 items (' || r.field_code || ')', 'layer', 'Layer 4', 'subsystem', 'pipeline.layer4_review_items',
        'failure', r.n || ' pending item(s) whose course or provider is missing, not active or archived', 'expected', 'Retirement supersedes the pending items of retired entities (§6, §7)',
        'source', 'integration-validate', 'validation_layer', 'V4', 'course_ids', coalesce(to_jsonb(r.courses), '[]'::jsonb), 'provider_ids', coalesce(to_jsonb(r.provs), '[]'::jsonb),
        'evidence', jsonb_build_object('items', r.n, 'pending_examined', v_pend, 'partly_checked', v_trunc), 'severity', 'P1', 'root_cause_class', 'lifecycle_leak', 'workstream', 'A5'), 'integration-validate');
      v_seen := v_seen || ('l4_orphan:' || r.field_code); v_n := v_n + 1;
    end loop;
    v_out := v_out || jsonb_build_object('l4_orphan', v_n);
    -- regenerated: a pending item proposing what was already decided for the same entity and field (keyed by the new index)
    v_n := 0;
    for r in select p.field_code, count(*) n, array_agg(p.entity_id) ents, bool_or(p.entity_type = 'course') is_course
               from security.integration_l4_pending_v1(v_l4max) p
              where exists (select 1 from pipeline.layer4_review_items d where d.entity_id = p.entity_id and d.field_code = p.field_code and d.status <> 'pending'
                              and d.decided_at is not null and d.decided_at < p.created_at and d.proposed_value is not distinct from p.proposed_value)
              group by p.field_code loop
      perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'l4_regenerated:' || r.field_code,
        'title', 'Layer 4 items regenerated after a decision (' || r.field_code || ')', 'layer', 'Layer 4', 'subsystem', 'pipeline.layer4_review_items',
        'failure', r.n || ' pending item(s) propose the same value for the same entity and field as an item already decided',
        'expected', 'A decided proposal is not raised again (Decision 263); fix the generator, not the reviews (§10)',
        'source', 'integration-validate', 'validation_layer', 'V4', 'course_ids', case when r.is_course then to_jsonb(r.ents) else '[]'::jsonb end,
        'provider_ids', case when r.is_course then '[]'::jsonb else to_jsonb(r.ents) end,
        'evidence', jsonb_build_object('items', r.n, 'pending_examined', v_pend, 'partly_checked', v_trunc), 'severity', 'P1', 'root_cause_class', 'code_defect', 'workstream', 'A4'), 'integration-validate');
      v_seen := v_seen || ('l4_regenerated:' || r.field_code); v_n := v_n + 1;
    end loop;
    v_out := v_out || jsonb_build_object('l4_regenerated', v_n);
    v_ok := v_ok || array['l4_duplicate', 'l4_orphan', 'l4_regenerated']::text[];
  exception when others then v_err := v_err || jsonb_build_object('layer4', left(sqlerrm, 300));
  end;
  v_out := v_out || jsonb_build_object('pending_examined', v_pend);

  -- 9. (own block) course-url-fill against pending official_course_url items
  begin
    with p as (select q.entity_id, min(q.created_at) first_pending from security.integration_l4_pending_v1(v_l4max) q
                where q.field_code = 'official_course_url' and q.entity_type = 'course' group by q.entity_id)
    select count(*), coalesce(jsonb_agg(f.course_id), '[]'::jsonb), max(f.filled_at) into v_m, v_res, v_ts
      from p join pipeline.course_url_fills f on f.course_id = p.entity_id and f.retracted_at is null and f.filled_at > p.first_pending;
    if v_m > 0 then
      perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'course_url_fill:pending_official_course_url',
        'title', 'course-url-fill wrote course_url while an official_course_url Layer 4 item was pending', 'layer', 'Catalogue', 'subsystem', 'security.course_url_fill_v1 (job course-url-fill)',
        'failure', v_m || ' course(s) whose course_url was filled after a pending official_course_url item was raised for them (last fill ' || v_ts || ')',
        'expected', 'course-url-fill skips (or reports) a course with a pending official_course_url item; Layer 4 decides the page',
        'source', 'integration-validate', 'validation_layer', 'V4', 'course_ids', v_res,
        'evidence', jsonb_build_object('courses', v_m, 'last_fill', v_ts, 'found_live', '2 Nov 2026 16:07-16:47, housekeeping disposition §6 (H05 drift)'),
        'evidence_refs', jsonb_build_array('admin docs/platform/nz-enrichment-brief/2026-11-02-housekeeping-disposition.md §6'),
        'severity', 'P1', 'root_cause_class', 'code_defect', 'workstream', 'A2'), 'integration-validate');
      v_seen := v_seen || 'course_url_fill:pending_official_course_url'::text;
    end if;
    v_ok := v_ok || 'course_url_fill'::text; v_out := v_out || jsonb_build_object('course_url_fill', v_m);
  exception when others then v_err := v_err || jsonb_build_object('course_url_fill', left(sqlerrm, 300));
  end;

  -- 7. work (Firecrawl spend) for archived providers, since the last ledger row looked at ------------------------------------------------
  begin
    select * into s from pipeline.integration_validate_state where check_key = 'archived_provider_work';
    select count(*), coalesce(sum(u.units), 0), coalesce(jsonb_agg(distinct u.provider_id), '[]'::jsonb), max(u.id), max(u.at)
      into v_m, v_num, v_res, v_id, v_ts
      from catalogue.providers pr
      join pipeline.coverage_vendor_usage u on u.provider_id = pr.id and u.at >= coalesce(s.watermark_at, now() - v_back) and u.id > coalesce(s.watermark_id, 0)
     where pr.lifecycle_status is distinct from 'active';
    if v_m > 0 then
      perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'archived_provider_work:firecrawl',
        'title', 'Firecrawl spent on archived providers', 'layer', 'Layer 2', 'subsystem', 'pipeline.coverage_vendor_usage',
        'failure', v_m || ' Firecrawl call(s), ' || v_num || ' credit(s), for archived providers since the last check',
        'expected', 'No discovery, scraping or reading for an archived provider (§7)', 'source', 'integration-validate', 'validation_layer', 'V4', 'provider_ids', v_res,
        'evidence', jsonb_build_object('calls', v_m, 'credits', v_num, 'last_at', v_ts), 'severity', 'P1', 'root_cause_class', 'lifecycle_leak', 'workstream', 'A5'), 'integration-validate');
      v_seen := v_seen || 'archived_provider_work:firecrawl'::text;
    end if;
    insert into pipeline.integration_validate_state as t(check_key, last_run_at, watermark_id, watermark_at, last_found)
    values ('archived_provider_work', now(), coalesce(v_id, s.watermark_id, (select max(id) from pipeline.coverage_vendor_usage)), now(), v_m)
    on conflict (check_key) do update set last_run_at = now(), watermark_id = excluded.watermark_id, watermark_at = excluded.watermark_at, last_found = excluded.last_found, last_error = null;
    v_ok := v_ok || 'archived_provider_work'::text; v_out := v_out || jsonb_build_object('archived_provider_work', v_m);
  exception when others then v_err := v_err || jsonb_build_object('archived_provider_work', left(sqlerrm, 300));
  end;

  -- 8. archived providers and inactive courses visible in search (the documents the website and Zoho read) --------------------------------
  begin
    select count(*), coalesce(jsonb_agg(distinct d.provider_id), '[]'::jsonb), coalesce(jsonb_agg(d.course_id), '[]'::jsonb)
      into v_m, v_res, v_res2
      from catalogue.providers pr join search.course_documents d on d.provider_id = pr.id and d.publication_status = 'published'
     where pr.lifecycle_status is distinct from 'active';
    if v_m > 0 then
      perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'search_leak:archived_provider',
        'title', 'Archived providers'' courses are published in search', 'layer', 'Search/API', 'subsystem', 'search.course_documents',
        'failure', v_m || ' published search document(s) belong to archived providers', 'expected', 'No active consumer search record for an archived provider (§7)',
        'source', 'integration-validate', 'validation_layer', 'V4', 'provider_ids', v_res, 'course_ids', v_res2, 'evidence', jsonb_build_object('documents', v_m),
        'severity', 'P0', 'root_cause_class', 'lifecycle_leak', 'workstream', 'A5'), 'integration-validate');
      v_seen := v_seen || 'search_leak:archived_provider'::text;
    end if;
    v_out := v_out || jsonb_build_object('search_leak_archived_provider', v_m);
    select count(*), coalesce(jsonb_agg(d.course_id), '[]'::jsonb), coalesce(jsonb_agg(distinct d.provider_id), '[]'::jsonb) into v_m, v_res, v_res2
      from (select c.id from catalogue.courses c where c.lifecycle_status is distinct from 'active' limit v_inmax) c
      join search.course_documents d on d.course_id = c.id and d.publication_status = 'published';
    if v_m > 0 then
      perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'search_leak:inactive_course',
        'title', 'Courses that are not active are published in search', 'layer', 'Search/API', 'subsystem', 'search.course_documents',
        'failure', v_m || ' published search document(s) belong to courses that are not active', 'expected', 'Retired or inactive courses leave search at the next refresh',
        'source', 'integration-validate', 'validation_layer', 'V4', 'course_ids', v_res, 'provider_ids', v_res2, 'evidence', jsonb_build_object('documents', v_m),
        'severity', 'P0', 'root_cause_class', 'lifecycle_leak', 'workstream', 'A8'), 'integration-validate');
      v_seen := v_seen || 'search_leak:inactive_course'::text;
    end if;
    v_ok := v_ok || 'search_leak'::text; v_out := v_out || jsonb_build_object('search_leak_inactive_course', v_m);
  exception when others then v_err := v_err || jsonb_build_object('search_leak', left(sqlerrm, 300));
  end;

  -- 10. unexpected Firecrawl or AI spend: today's ledgers against the settings ---------------------------------------------------------
  begin
    v_num := security.fc_billed_today_v1();
    if coalesce((security.toolset_setting('firecrawl', 'daily_budget_on') #>> '{}')::boolean, false)
       and v_num > security.fc_setting_num_v1('daily_budget_total', 25000) then
      perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'spend:firecrawl_day',
        'title', 'Firecrawl spend above the daily budget', 'layer', 'Platform', 'subsystem', 'pipeline.coverage_vendor_usage',
        'failure', v_num || ' credits billed today against a daily budget of ' || security.fc_setting_num_v1('daily_budget_total', 25000),
        'expected', 'Billed credits stay within the daily budget while it is on', 'source', 'integration-validate', 'validation_layer', 'V4',
        'evidence', jsonb_build_object('billed_today', v_num, 'budget', security.fc_setting_num_v1('daily_budget_total', 25000)), 'severity', 'P1', 'root_cause_class', 'budget', 'workstream', 'A7'), 'integration-validate');
      v_seen := v_seen || 'spend:firecrawl_day'::text;
    end if;
    select coalesce(sum(t.spent), 0) into v_num2 from security.ai_spend_today_v1() t;
    if v_num2 > security.pipeline_num_v1('budgets.ai_daily_ceiling_usd', 14) then
      perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'spend:ai_day',
        'title', 'AI spend above the daily ceiling', 'layer', 'Platform', 'subsystem', 'pipeline.ai_spend_ledger',
        'failure', 'US$' || round(v_num2, 2) || ' spent today against a ceiling of US$' || security.pipeline_num_v1('budgets.ai_daily_ceiling_usd', 14),
        'expected', 'AI spend stays within budgets.ai_daily_ceiling_usd', 'source', 'integration-validate', 'validation_layer', 'V4',
        'evidence', jsonb_build_object('spent_today_usd', v_num2, 'ceiling_usd', security.pipeline_num_v1('budgets.ai_daily_ceiling_usd', 14)), 'severity', 'P1', 'root_cause_class', 'budget', 'workstream', 'A7'), 'integration-validate');
      v_seen := v_seen || 'spend:ai_day'::text;
    end if;
    v_ok := v_ok || 'spend'::text; v_out := v_out || jsonb_build_object('firecrawl_today', v_num, 'ai_today_usd', v_num2);
  exception when others then v_err := v_err || jsonb_build_object('spend', left(sqlerrm, 300));
  end;

  -- 11. condition cleared / alerts: open issues of the checks that ran ---------------------------------------------------------------
  for r in select i.id, i.fingerprint, i.condition_cleared_at, i.status from pipeline.integration_issues i
            where i.status <> 'closed' and split_part(i.fingerprint, ':', 1) = any (v_ok) loop
    if r.fingerprint = any (v_seen) then
      perform security.integration_alert_sync_v1(r.id, true);
    else
      if r.condition_cleared_at is null then
        update pipeline.integration_issues set condition_cleared_at = now() where id = r.id;
        insert into pipeline.integration_issue_events(issue_id, kind, from_status, to_status, actor, note)
        values (r.id, 'not_observed', r.status, r.status, 'integration-validate', 'condition no longer observed; close after production verification');
      end if;
      perform security.integration_alert_sync_v1(r.id, false);
    end if;
  end loop;

  v_out := v_out || jsonb_build_object('ran', to_jsonb(v_ok), 'errors', v_err, 'observed', cardinality(v_seen), 'ms', round(extract(epoch from clock_timestamp() - v_t0) * 1000));
  insert into pipeline.integration_validate_state as t(check_key, last_run_at, last_found, last_ms, last_error, detail)
  values ('run', now(), cardinality(v_seen), round(extract(epoch from clock_timestamp() - v_t0) * 1000)::int, nullif(v_err::text, '{}'), v_out)
  on conflict (check_key) do update set last_run_at = now(), last_found = excluded.last_found, last_ms = excluded.last_ms, last_error = excluded.last_error, detail = excluded.detail;
  return v_out;
end $_$;


ALTER FUNCTION "security"."integration_validate_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."integration_validate_v1"() IS 'CF-247 mandate §4 V4 (job integration-validate): Platform health and queue-watch output, failed job runs, stale leases, stuck adapter drafts, Layer 4 duplicates, orphans and regenerations, course-url-fill against pending official_course_url items, work for archived providers, archived or inactive records in search, spend against settings; each feeds the integration queue by fingerprint; P0 through the existing platform-alerts path';



CREATE OR REPLACE FUNCTION "security"."integration_yield_checks_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_win interval := make_interval(mins => security.pipeline_num_v1('integration.hidden_error_window_minutes', 120)::int);
        v_minf int := security.pipeline_num_v1('integration.hidden_error_min_failures', 3)::int;
        v_share numeric := security.pipeline_num_v1('integration.hidden_error_min_share', 25);
        v_zy interval := make_interval(hours => security.pipeline_num_v1('integration.zero_yield_hours', 6)::int);
        v_zmin int := security.pipeline_num_v1('integration.zero_yield_min_calls', 6)::int;
        v_att int := security.pipeline_num_v1('integration.provider_failed_attempts_min', 3)::int;
        v_pmin int := security.pipeline_num_v1('integration.provider_failed_pages_min', 10)::int;
        v_keep interval := make_interval(hours => security.pipeline_num_v1('integration.bucket_keep_hours', 72)::int);
        v_back interval := make_interval(hours => security.pipeline_num_v1('integration.first_run_lookback_hours', 24)::int);
        v_watch text[] := security.pipeline_list_v1('integration.watched_modes', '["provider_description", "enrich_ai"]');
        v_wmin int := security.pipeline_num_v1('integration.watched_mode_min_failures', 1)::int; v_cap text; v_capped jsonb := '{}'::jsonb;
        s pipeline.integration_validate_state; r record; v_ok text[] := '{}'; v_seen text[] := '{}'; v_err jsonb := '{}'::jsonb; v_out jsonb := '{}'::jsonb;
        v_id bigint; v_n int; v_m int; v_wait boolean; v_res jsonb; v_fp text;
begin
  -- 1. edge responses past the watermark -> hourly tallies per function and mode
  begin
    select * into s from pipeline.integration_validate_state where check_key = 'yield_edge';
    with h as (select x.id, x.created, x.status_code, x.timed_out, x.error_msg, left(x.content, 2000) content  -- fixed: only the head of an answer is read
                 from net._http_response x
                where x.created >= coalesce(s.watermark_at - interval '10 minutes', now() - v_win) and x.id > coalesce(s.watermark_id, 0)),  -- fixed: slack for rows written by longer transactions
         e as (select h.id, coalesce(l.function_name, 'unattributed') || ':' || coalesce(l.mode, '') k, date_trunc('hour', h.created) b,
                      (coalesce(h.status_code, 0) >= 400 or h.timed_out is true or h.error_msg is not null
                       or (coalesce(h.status_code, 0) < 300 and h.content ~ '"ok"\s*:\s*false')) failed,
                      left(coalesce(h.error_msg, coalesce(h.status_code::text, 'no status') || ' ' || coalesce(h.content, '')), 200) sample
                 from h left join pipeline.edge_request_log l on l.slot = (h.id % 50000)::int and l.request_id = h.id)  -- fixed: the request log is a ring of 50,000 slots
    insert into pipeline.integration_yield_buckets as t(kind, key, bucket, calls, failures, sample)
    select 'edge', e.k, e.b, count(*), count(*) filter (where e.failed), (array_agg(e.sample order by e.id desc) filter (where e.failed))[1]
      from e group by e.k, e.b
    on conflict (kind, key, bucket) do update set calls = t.calls + excluded.calls, failures = t.failures + excluded.failures, sample = coalesce(excluded.sample, t.sample);
    select max(x.id) into v_id from net._http_response x where x.created >= coalesce(s.watermark_at - interval '10 minutes', now() - v_win) and x.id > coalesce(s.watermark_id, 0);  -- fixed: same slack
    insert into pipeline.integration_validate_state as t(check_key, last_run_at, watermark_id, watermark_at) values ('yield_edge', now(), v_id, now())
    on conflict (check_key) do update set last_run_at = now(), watermark_id = coalesce(excluded.watermark_id, t.watermark_id),
      watermark_at = case when excluded.watermark_id is null then t.watermark_at else now() end, last_error = null;
    -- hidden worker errors over the window
    v_n := 0;
    for r in select b.key, sum(b.calls) calls, sum(b.failures) failures, (array_agg(b.sample order by b.bucket desc) filter (where b.sample is not null))[1] sample
               from pipeline.integration_yield_buckets b where b.kind = 'edge' and b.bucket >= date_trunc('hour', now() - v_win) group by b.key loop
      -- CF-247 3 Nov 2026 (direction 09:32 §5; IQ-00053, IQ-00055): a watched mode opens its issue on its first failed answers in the window
      if (r.failures >= v_minf and r.failures * 100 >= v_share * r.calls) or (r.failures >= v_wmin and split_part(r.key, ':', 2) = any (v_watch)) then
        v_fp := 'hidden_worker_error:' || r.key;
        perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', v_fp,
          'title', 'Worker ' || r.key || ' answers with errors while its job counts as succeeded', 'layer', 'Scheduling', 'subsystem', r.key,
          'failure', r.failures || ' of ' || r.calls || ' answer(s) failed in the last ' || security.pipeline_num_v1('integration.hidden_error_window_minutes', 120)
                     || ' minutes (HTTP 4xx/5xx, time-out, transport error or "ok": false); last: ' || coalesce(r.sample, 'no sample'),
          'expected', 'A scheduled call that reaches the worker does its work; the job''s succeeded status is not taken as success',
          'source', 'integration-validate (yield checks)', 'validation_layer', 'V4',
          'evidence', jsonb_build_object('calls', r.calls, 'failed', r.failures, 'sample', r.sample),
          'severity', 'P1', 'root_cause_class', 'unclassified', 'workstream', 'A7'), 'integration-validate');
        v_seen := v_seen || v_fp; v_n := v_n + 1;
      end if;
    end loop;
    v_ok := v_ok || 'hidden_worker_error'::text; v_out := v_out || jsonb_build_object('hidden_worker_error', v_n);
  exception when others then v_err := v_err || jsonb_build_object('hidden_worker_error', left(sqlerrm, 300));
  end;

  -- 2. worker ledger past the watermark -> hourly tallies per mode; persistent zero yield
  begin
    select * into s from pipeline.integration_validate_state where check_key = 'yield_ledger';
    insert into pipeline.integration_yield_buckets as t(kind, key, bucket, calls, failures, items, ok)
    select 'ledger', l.mode, date_trunc('hour', l.run_at), count(*), sum(l.failed), sum(l.items), sum(l.ok)
      from pipeline.mode_outcome_ledger l
     where l.id > coalesce(s.watermark_id, 0) and l.run_at >= coalesce(s.watermark_at - interval '10 minutes', now() - v_back)  -- fixed: slack for rows written by longer transactions
     group by l.mode, date_trunc('hour', l.run_at)
    on conflict (kind, key, bucket) do update set calls = t.calls + excluded.calls, failures = t.failures + excluded.failures, items = t.items + excluded.items, ok = t.ok + excluded.ok;
    select max(l.id) into v_id from pipeline.mode_outcome_ledger l where l.id > coalesce(s.watermark_id, 0) and l.run_at >= coalesce(s.watermark_at - interval '10 minutes', now() - v_back);  -- fixed: same slack
    insert into pipeline.integration_validate_state as t(check_key, last_run_at, watermark_id, watermark_at) values ('yield_ledger', now(), v_id, now())
    on conflict (check_key) do update set last_run_at = now(), watermark_id = coalesce(excluded.watermark_id, t.watermark_id),
      watermark_at = case when excluded.watermark_id is null then t.watermark_at else now() end, last_error = null;
    v_n := 0;
    for r in select b.key, sum(b.calls) calls, sum(b.items) items, sum(b.ok) ok, sum(b.failures) failures
               from pipeline.integration_yield_buckets b where b.kind = 'ledger' and b.bucket >= date_trunc('hour', now() - v_zy) group by b.key loop
      if r.calls >= v_zmin and r.ok = 0 then
        v_wait := false;
        if r.failures = 0 and r.items = 0 then v_wait := coalesce(security.worker_mode_waiting_v1(r.key), false); end if;
        -- CF-247 IQ-00048 follow-up: no failure in the window and the picker held by its own daily cap is idle, not zero yield
        v_cap := case when r.failures = 0 then security.worker_mode_capped_v1(r.key) end;
        if v_cap is not null then v_capped := v_capped || jsonb_build_object(r.key, v_cap); end if;
        if v_cap is null and (r.failures > 0 or r.items > 0 or v_wait) then
          v_fp := 'zero_yield:' || r.key;
          perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', v_fp,
            'title', 'Worker mode ' || r.key || ': calls with no work done', 'layer', 'Scheduling', 'subsystem', 'coverage-sweep mode ' || r.key,
            'failure', r.calls || ' call(s) in ' || security.pipeline_num_v1('integration.zero_yield_hours', 6) || ' hours, 0 items done, ' || r.items || ' taken, '
                       || r.failures || ' failed' || case when v_wait then ', work waiting' else '' end,
            'expected', 'A lane with work waiting finishes items; an idle lane is paused by the flag unit',
            'source', 'integration-validate (yield checks)', 'validation_layer', 'V4',
            'evidence', jsonb_build_object('calls', r.calls, 'items', r.items, 'ok', r.ok, 'failed', r.failures, 'work_waiting', v_wait),
            'severity', case when r.failures > 0 then 'P1' else 'P2' end, 'root_cause_class', 'unclassified', 'workstream', 'A7'), 'integration-validate');
          v_seen := v_seen || v_fp; v_n := v_n + 1;
        end if;
      end if;
    end loop;
    v_ok := v_ok || 'zero_yield'::text; v_out := v_out || jsonb_build_object('zero_yield', v_n, 'idle_by_cap', v_capped);
  exception when others then v_err := v_err || jsonb_build_object('zero_yield', left(sqlerrm, 300));
  end;

  -- 3. incomplete pagination (course lists) and incomplete whole reads (entry matrices)
  begin
    select count(*), coalesce(jsonb_agg(distinct c.provider_id), '[]'::jsonb), coalesce(sum(substring(c.reason from '\((\d+) course addresses\)')::int - c.links_found), 0)
      into v_n, v_res, v_m
      from pipeline.provider_course_lists c
     where c.status = 'read' and substring(c.reason from '\((\d+) course addresses\)')::int > coalesce(c.links_found, 0);
    if v_n > 0 then
      perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'incomplete_pagination:course_lists',
        'title', 'Course lists read fewer course addresses than they list', 'layer', 'Layer 2', 'subsystem', 'pipeline.provider_course_lists (course_list_read)',
        'failure', v_n || ' course list(s) marked read with ' || v_m || ' listed course address(es) not reached (pages or a cap left out)',
        'expected', 'A course list is read to its last page, or its shortfall is recorded as partial', 'source', 'integration-validate (yield checks)', 'validation_layer', 'V4',
        'provider_ids', v_res, 'evidence', jsonb_build_object('lists', v_n, 'addresses_missing', v_m), 'severity', 'P2', 'root_cause_class', 'code_defect', 'workstream', 'A2'), 'integration-validate');
      v_seen := v_seen || 'incomplete_pagination:course_lists'::text;
    end if;
    select count(*), coalesce(jsonb_agg(distinct m.provider_id), '[]'::jsonb) into v_n, v_res
      from pipeline.entry_matrix_runs m where m.state = 'failed' and (m.error like 'held_incomplete%' or m.error like 'held_partial%');
    if v_n > 0 then
      perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'incomplete_read:entry_matrix',
        'title', 'Entry-matrix reads held as incomplete', 'layer', 'AER', 'subsystem', 'pipeline.entry_matrix_runs',
        'failure', v_n || ' run(s) held_incomplete or held_partial (a table column, slice or published minimum left out)',
        'expected', 'Whole-read completeness is shown before any row is admitted (direction 23:24 §1 AER D-R3)', 'source', 'integration-validate (yield checks)', 'validation_layer', 'V4',
        'provider_ids', v_res, 'evidence', jsonb_build_object('runs', v_n), 'severity', 'P2', 'root_cause_class', 'code_defect', 'workstream', 'A3'), 'integration-validate');
      v_seen := v_seen || 'incomplete_read:entry_matrix'::text;
    end if;
    v_ok := v_ok || array['incomplete_pagination', 'incomplete_read']::text[];
  exception when others then v_err := v_err || jsonb_build_object('incomplete', left(sqlerrm, 300));
  end;

  -- 4. repeated failed attempts per provider
  begin
    select count(*), coalesce(jsonb_agg(x.provider_id order by x.n desc), '[]'::jsonb), coalesce(max(x.n), 0) into v_n, v_res, v_m
      from (select p.provider_id, count(*) n from pipeline.coverage_course_pages p
             where p.read_status in ('fetch_failed', 'blocked') and p.read_attempts >= v_att group by p.provider_id having count(*) >= v_pmin) x;
    if v_n > 0 then
      perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'provider_failed_attempts:course_pages',
        'title', 'Providers whose course pages keep failing', 'layer', 'Layer 2', 'subsystem', 'pipeline.coverage_course_pages',
        'failure', v_n || ' provider(s) each have at least ' || v_pmin || ' course pages failing (fetch_failed or blocked) after ' || v_att || ' or more attempts (most: ' || v_m || ')',
        'expected', 'A provider whose pages keep failing gets a different acquisition route or is flagged for a person, not retried as before',
        'source', 'integration-validate (yield checks)', 'validation_layer', 'V4', 'provider_ids', v_res,
        'evidence', jsonb_build_object('providers', v_n, 'most_pages', v_m), 'severity', 'P2', 'root_cause_class', 'external', 'workstream', 'A2'), 'integration-validate');
      v_seen := v_seen || 'provider_failed_attempts:course_pages'::text;
    end if;
    select count(*), coalesce(jsonb_agg(d.provider_id), '[]'::jsonb) into v_n, v_res
      from pipeline.scholarship_discovery_providers d where d.status = 'failed' and d.attempts >= v_att;
    if v_n > 0 then
      perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'provider_failed_attempts:scholarship_discovery',
        'title', 'Scholarship discovery keeps failing for some providers', 'layer', 'Layer 2', 'subsystem', 'pipeline.scholarship_discovery_providers',
        'failure', v_n || ' provider(s) failed scholarship discovery ' || v_att || ' or more times', 'expected', 'Discovery succeeds or the provider is flagged with a cause',
        'source', 'integration-validate (yield checks)', 'validation_layer', 'V4', 'provider_ids', v_res, 'evidence', jsonb_build_object('providers', v_n),
        'severity', 'P2', 'root_cause_class', 'unclassified', 'workstream', 'A2'), 'integration-validate');
      v_seen := v_seen || 'provider_failed_attempts:scholarship_discovery'::text;
    end if;
    for r in select f.reason_code, count(*) n, jsonb_agg(f.provider_id) prov from pipeline.enrichment_flags f
              where f.entity = 'provider' and f.state = 'raised' and f.cleared_at is null and f.tries >= v_att group by f.reason_code loop
      v_fp := 'provider_failed_attempts:flag:' || r.reason_code;
      perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', v_fp,
        'title', 'Providers flagged ' || r.reason_code || ' after repeated tries', 'layer', 'Layer 2', 'subsystem', 'pipeline.enrichment_flags',
        'failure', r.n || ' provider(s) still flagged ' || r.reason_code || ' after ' || v_att || ' or more tries', 'expected', 'The flag clears or a person decides',
        'source', 'integration-validate (yield checks)', 'validation_layer', 'V4', 'provider_ids', r.prov, 'evidence', jsonb_build_object('providers', r.n),
        'severity', 'P2', 'root_cause_class', 'external', 'workstream', 'A2'), 'integration-validate');
      v_seen := v_seen || v_fp;
    end loop;
    v_ok := v_ok || 'provider_failed_attempts'::text;
  exception when others then v_err := v_err || jsonb_build_object('provider_failed_attempts', left(sqlerrm, 300));
  end;

  -- 4b. CF-247 IQ-00064 (mandate 3 Nov 2026 13:09 §3.8): a plan step or task that ended done with work unfinished
  begin
    select count(*), coalesce(jsonb_agg(distinct u.provider_id) filter (where u.provider_id is not null), '[]'::jsonb), coalesce(sum(u.unprocessed), 0)::int
      into v_n, v_res, v_m from security.plan_unfinished_done_v1() u;
    if v_n > 0 then
      perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'plan_unfinished_done:plans',
        'title', 'Plan steps or tasks ended done with work unfinished', 'layer', 'Scheduling', 'subsystem', 'enrichment plans and tasks (enrich_plan_tick_v1, admin_job_watch_v1)',
        'failure', v_n || ' plan step(s) or task(s) in the last ' || security.pipeline_num_v1('tasks.unfinished_lookback_days', 7) || ' days ended done with ' || v_m || ' item(s) not processed',
        'expected', 'A step or task with work left is held, carries on when its lane has room, and ends failed with a reason if it cannot (IQ-00064)',
        'source', 'integration-validate (yield checks)', 'validation_layer', 'V4', 'provider_ids', v_res,
        'evidence', jsonb_build_object('items', v_n, 'unprocessed', v_m, 'sample', (select jsonb_agg(to_jsonb(x)) from (select * from security.plan_unfinished_done_v1() limit 10) x)),
        'severity', 'P1', 'root_cause_class', 'code_defect', 'workstream', 'A7'), 'integration-validate');
      v_seen := v_seen || 'plan_unfinished_done:plans'::text;
    end if;
    v_ok := v_ok || 'plan_unfinished_done'::text; v_out := v_out || jsonb_build_object('plan_unfinished_done', v_n);
  exception when others then v_err := v_err || jsonb_build_object('plan_unfinished_done', left(sqlerrm, 300));
  end;

  -- 5. condition cleared for the checks that ran; P0 alert path (none of these is P0 today)
  for r in select i.id, i.fingerprint, i.condition_cleared_at, i.status from pipeline.integration_issues i
            where i.status <> 'closed' and split_part(i.fingerprint, ':', 1) = any (v_ok) loop
    if r.fingerprint = any (v_seen) then
      perform security.integration_alert_sync_v1(r.id, true);
    else
      if r.condition_cleared_at is null then
        update pipeline.integration_issues set condition_cleared_at = now() where id = r.id;
        insert into pipeline.integration_issue_events(issue_id, kind, from_status, to_status, actor, note)
        values (r.id, 'not_observed', r.status, r.status, 'integration-validate', 'condition no longer observed; close after production verification');
      end if;
      perform security.integration_alert_sync_v1(r.id, false);
    end if;
  end loop;

  delete from pipeline.integration_yield_buckets b where b.bucket < now() - v_keep;
  return v_out || jsonb_build_object('ran', to_jsonb(v_ok), 'errors', v_err, 'observed', cardinality(v_seen));
end $$;


ALTER FUNCTION "security"."integration_yield_checks_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."integration_yield_checks_v1"() IS 'Platform Admin direction 2 Nov 2026 23:24 §3 (job integration-validate): hidden worker errors under succeeded jobs, persistent zero yield, incomplete pagination and whole reads, repeated failed attempts per provider; each feeds the integration queue by fingerprint';



CREATE OR REPLACE FUNCTION "security"."is_double_degree_title"("p" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select lower(coalesce(p, '')) ~ '( / |/| and bachelor| and master| and diploma|\mdouble\M|\mdual\M|\mcombined\M)'
$$;


ALTER FUNCTION "security"."is_double_degree_title"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."job_held_off_v1"("p_job" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 IQ-00060: the job is on jobs.held_off (switched off by a person or a governed restore), so nothing switches it on by itself
  select coalesce((select s.value ? p_job from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'jobs.held_off'
                     and jsonb_typeof(s.value) = 'array'), false)
$$;


ALTER FUNCTION "security"."job_held_off_v1"("p_job" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."job_idle_flag_person_release_v1"("p_job" "text", "p_reason" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare f record; v_n int := 0;
begin
  -- D14 (31 Oct 2026): a person switching a job on releases that job's automatic idle-pause flag; the audit row is kept in
  -- pipeline.enrichment_flag_events, and the flag unit's idle guard applies to the job again. No other job is touched.
  for f in select x.id from pipeline.enrichment_flags x
            where x.entity = 'job' and x.entity_key = p_job and x.field = '' and x.reason_code = 'idle_paused' and x.cleared_at is null and coalesce(x.state, 'raised') = 'raised' loop
    perform security.flag_release_v1(f.id, coalesce(auth.uid()::text, 'person'), 'person', 'Switched on by a person on Automations: ' || left(coalesce(p_reason, ''), 200),
                                     jsonb_build_object('source', 'Automations', 'decision', 'D14'), true);
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;


ALTER FUNCTION "security"."job_idle_flag_person_release_v1"("p_job" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."job_movement_v1"("p_job" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare j pipeline.admin_jobs%rowtype; v_t0 timestamptz; v_t1 timestamptz; v_a int := 0; v_b int := 0; v_c int := 0; v_pid uuid;
begin
  select * into j from pipeline.admin_jobs x where x.id = p_job;
  if j.id is null then return null; end if;
  v_t0 := coalesce(j.started_at, j.created_at); v_t1 := coalesce(j.finished_at, now());
  if j.kind = 'enrich_fields' then
    select count(*) filter (where e.state = 'filled'), count(*) filter (where e.state = 'review') into v_a, v_b from pipeline.field_enrich_items e where e.job_id = p_job;
    return jsonb_build_object('moved', v_a + v_b > 0, 'basis', 'field_enrich_items', 'filled', v_a, 'review', v_b);
  elsif j.kind = 'course_page_find' then
    if jsonb_typeof(j.result->'found') = 'number' then v_a := (j.result->>'found')::int;
    else
      select count(*) into v_a from pipeline.course_link_search s
       where s.course_id = any (array(select x::uuid from jsonb_array_elements_text(coalesce(j.args->'course_ids', '[]'::jsonb)) x))
         and s.state in ('found', 'verified') and s.done_at between v_t0 and v_t1;
    end if;
    return jsonb_build_object('moved', v_a > 0, 'basis', 'course_link_search', 'pages_found', v_a, 'not_found', coalesce((j.result->>'not_found')::int, 0));
  elsif j.kind in ('scholarship_provider_scan', 'scholarship_course_check', 'scholarship_reread') then
    v_a := coalesce((j.result->>'new_scholarships')::int, 0); v_b := coalesce((j.result->>'became')::int, 0); v_c := coalesce((j.result->>'links_changed')::int, 0);
    return jsonb_build_object('moved', v_a + v_b + v_c > 0, 'basis', 'scholarships', 'new_scholarships', v_a, 'became', v_b, 'links_changed', v_c);
  elsif j.kind = 'provider_fill' then
    v_pid := nullif(j.args->>'provider_id', '')::uuid;
    select count(*) into v_a from pipeline.provider_contact_checks k where k.provider_id = v_pid and k.checked_at between v_t0 and v_t1 and k.outcome = 'found';
    select count(*) into v_b from pipeline.provider_central_search s where s.provider_id = v_pid and s.searched_at between v_t0 and v_t1 and coalesce(jsonb_array_length(s.found), 0) > 0;
    select count(*) into v_c from pipeline.coverage_provider_discovery d join catalogue.providers p on p.id = d.provider_id
     where d.provider_id = v_pid and d.site_searched_at between v_t0 and v_t1 and nullif(btrim(p.website), '') is not null;
    return jsonb_build_object('moved', v_a + v_b + v_c > 0, 'basis', 'provider_facts', 'contacts_found', v_a, 'central_found', v_b, 'website_found', v_c);
  elsif j.kind in ('scholarship_ai_qualify', 'scholarship_ai_backfill') then
    select count(*) filter (where coalesce((e.applied->>'admitted')::boolean, false)), count(*) filter (where e.verdict = 'scholarship') into v_a, v_b
      from pipeline.scholarship_ai_extractions e where e.job_id = p_job;
    return jsonb_build_object('moved', case when j.kind = 'scholarship_ai_backfill' then v_a > 0 else v_b > 0 end, 'basis', 'scholarship_ai_extractions', 'admitted', v_a, 'scholarships', v_b);
  elsif j.kind = 'qualify_adapters' then
    return jsonb_build_object('moved', coalesce((j.result->>'passing')::int, 0) > 0, 'basis', 'adapters', 'passing', coalesce((j.result->>'passing')::int, 0));
  end if;
  return jsonb_build_object('moved', coalesce((j.result->>'done')::numeric, 0) > 0 or (j.state = 'done' and not (j.result ? 'done')), 'basis', 'progress',
                            'done', j.result->'done', 'total', j.result->'total');
end $$;


ALTER FUNCTION "security"."job_movement_v1"("p_job" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."job_outcome_compute_v1"("p_job" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare j pipeline.admin_jobs%rowtype; v_mv jsonb; v_out text; v_code text; v_moved boolean; v_unf boolean;
begin
  select * into j from pipeline.admin_jobs x where x.id = p_job;
  if j.id is null then return null; end if;
  if j.state in ('queued', 'running', 'paused') then
    if j.result ? 'held' then
      v_code := coalesce(j.result->'held'->>'code', 'waiting_turn');
      return jsonb_build_object('outcome', security.ops_hold_outcome_v1(v_code), 'moved', null,
                                'detail', jsonb_build_object('provisional', true, 'state', j.state, 'hold', v_code, 'reason', j.result->'held'->>'reason'));
    end if;
    return jsonb_build_object('outcome', null, 'moved', null, 'detail', null);
  end if;
  v_mv := security.job_movement_v1(p_job);
  v_moved := coalesce((v_mv->>'moved')::boolean, false);
  v_unf := j.state = 'done' and j.kind = any (security.pipeline_list_v1('tasks.hold_kinds', '["course_page_find", "scholarship_provider_scan", "provider_fill"]'))
           and jsonb_typeof(j.result->'done') = 'number' and jsonb_typeof(j.result->'total') = 'number' and (j.result->>'done')::numeric < (j.result->>'total')::numeric;
  v_code := coalesce(j.result->'held'->>'code', j.result->'blocked'->>'code');
  v_out := case
    when j.state = 'cancelled' and j.result->>'end_state' = 'not_needed' then 'not_needed'
    when j.state = 'cancelled' then case when v_moved then 'succeeded_with_result' else 'not_needed' end
    when j.state = 'failed' and j.result->>'end_state' = 'failed' then
      case when security.ops_hold_outcome_v1(coalesce(v_code, 'waiting_turn')) in ('blocked_policy', 'blocked_evidence') then security.ops_hold_outcome_v1(v_code) else 'failed_retryable' end
    when j.state = 'failed' then case when security.ops_error_retryable_v1(j.error) then 'failed_retryable' else 'failed_remediation' end
    when v_unf then 'failed_retryable'
    when v_moved then 'succeeded_with_result'
    else 'succeeded_no_movement' end;
  return jsonb_build_object('outcome', v_out, 'moved', v_moved,
    'detail', jsonb_build_object('state', j.state, 'end_state', j.result->>'end_state', 'movement', v_mv, 'hold', v_code,
                                 'unprocessed', case when v_unf then (j.result->>'total')::numeric - (j.result->>'done')::numeric end,
                                 'cancelled_by_person', j.state = 'cancelled' and coalesce(j.result->>'end_state', '') <> 'not_needed',
                                 'error', left(j.error, 300)));
end $$;


ALTER FUNCTION "security"."job_outcome_compute_v1"("p_job" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."job_outcome_record_v1"("p_job" "uuid", "p_basis" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb; v_cur text;
begin
  if security.pipeline_num_v1('ops.outcome_on', 0) < 1 then return null; end if;
  v := security.job_outcome_compute_v1(p_job);
  if v is null then return null; end if;
  -- an open task that is no longer held keeps its provisional outcome (outcome_detail.provisional) until it ends: workstream A's
  -- security.job_outcome_set_v1 takes a code, not null (interface request: accept null to clear a provisional outcome)
  if v->>'outcome' is null then return null; end if;
  select j.outcome into v_cur from pipeline.admin_jobs j where j.id = p_job;
  if v_cur is not distinct from v->>'outcome' and p_basis = 'held' then return v_cur; end if;
  perform security.job_outcome_set_v1(p_job, v->>'outcome', coalesce(v->'detail', '{}'::jsonb) || jsonb_build_object('basis', p_basis, 'at', now()));
  return v->>'outcome';
exception when others then
  raise notice 'job outcome not recorded for %: %', p_job, sqlerrm;
  return null;
end $$;


ALTER FUNCTION "security"."job_outcome_record_v1"("p_job" "uuid", "p_basis" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."job_outcome_set_v1"("p_job" "uuid", "p_outcome" "text", "p_detail" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not exists (select 1 from pipeline.ops_outcome_codes c where c.code = p_outcome) then
    raise exception 'unknown job outcome % (pipeline.ops_outcome_codes)', p_outcome using errcode = '22023';
  end if;
  update pipeline.admin_jobs set outcome = p_outcome, outcome_detail = coalesce(p_detail, '{}'::jsonb) where id = p_job;
  if not found then raise exception 'no job %', p_job using errcode = 'P0002'; end if;
end $$;


ALTER FUNCTION "security"."job_outcome_set_v1"("p_job" "uuid", "p_outcome" "text", "p_detail" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."job_outcomes_v1"("p_hours" integer) RETURNS TABLE("mode" "text", "jobs" "text"[], "calls" integer, "succeeded" integer, "idle" integer, "zero_work_error" integer, "failed" integer, "last_outcome" "text", "last_at" timestamp with time zone, "last_good_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select l.mode,
         (select array_agg(j.jobname order by j.jobname) from cron.job j where j.command ~ ('''mode'',\s*''' || l.mode || '''') or j.command ~ ('"mode"\s*:\s*"' || l.mode || '"')),
         count(*)::int, count(*) filter (where l.outcome = 'succeeded')::int, count(*) filter (where l.outcome = 'idle')::int,
         count(*) filter (where l.outcome = 'zero_work_error')::int, count(*) filter (where l.outcome = 'failed')::int,
         (array_agg(l.outcome order by l.run_at desc, l.id desc))[1], max(l.run_at), max(l.run_at) filter (where l.outcome in ('succeeded', 'idle'))
    from pipeline.mode_outcome_ledger l
   where l.run_at > now() - make_interval(hours => greatest(p_hours, 1))
   group by l.mode
$$;


ALTER FUNCTION "security"."job_outcomes_v1"("p_hours" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."job_run_now_v1"("p_job" "text", "p_reason" "text", "p_args" "jsonb", "p_requester" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_cap int := security.pipeline_num_v1('run_now.pilot_cap', 20)::int;
        v_id uuid := gen_random_uuid(); v_key text := nullif(btrim(coalesce(p_args->>'idempotency_key', '')), '');
        v_cohort pipeline.run_now_cohorts%rowtype; v_ids uuid[]; v_rank int; v_cat pipeline.automation_catalogue%rowtype;
        v_prev pipeline.admin_jobs%rowtype; v_why text; v_res jsonb; v_start timestamptz := clock_timestamp(); v_calls int; v_by jsonb; v_holder jsonb;
        v_err text; v_title text;
begin
  if p_requester is null then raise exception 'a requester is required'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;
  if v_key is not null then
    select * into v_prev from pipeline.admin_jobs where kind = 'job_run_now' and args->>'idempotency_key' = v_key;
    if found then return jsonb_build_object('run_id', v_prev.id, 'state', v_prev.state, 'repeat', true, 'result', v_prev.result); end if;
  end if;
  select * into v_cat from pipeline.automation_catalogue where jobname = p_job;
  select coalesce(max(r.rank), 0) into v_rank from security.user_roles ur join security.roles r on r.code = ur.role_code
   where ur.user_id = p_requester and (ur.expires_at is null or ur.expires_at > now()) and r.status = 'active';
  select * into v_cohort from pipeline.run_now_cohorts where id = nullif(p_args->>'cohort_id', '')::uuid;
  v_ids := array(select m.course_id from pipeline.run_now_cohort_members m where m.cohort_id = v_cohort.id order by m.pick);
  v_why := case
    when not (p_job = any (array(select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'run_now.jobs'), '[]'::jsonb))))) then 'job is not on the Run now list'
    when v_cat.jobname is null then 'job is not catalogued'
    when v_rank < greatest(coalesce(v_cat.control_rank, 6), 1) then 'requester rank ' || v_rank || ' is below the job''s rank ' || coalesce(v_cat.control_rank, 6)
    when not exists (select 1 from cron.job j where j.jobname = p_job) then 'job is not scheduled'
    when exists (select 1 from cron.job j where j.jobname = p_job and not j.active) then 'job is paused'
    when p_job = 'intake-dates-apply' and not coalesce((security.toolset_setting('pipeline', 'intake_dates.apply_enabled') #>> '{}')::boolean, false) then 'job switch is off (Intake dates: on)'
    when p_job <> 'intake-dates-apply' then 'no bounded runner for this job'
    when v_cohort.id is null then 'a cohort_id is required'
    when v_cohort.job <> p_job then 'cohort belongs to job ' || v_cohort.job
    when coalesce(cardinality(v_ids), 0) = 0 then 'cohort has no courses'
    when cardinality(v_ids) > v_cap then 'cohort has ' || cardinality(v_ids) || ' courses, over the cap of ' || v_cap
    when not pg_try_advisory_xact_lock(hashtext('cf247 intake dates apply')) then 'a run of this job is in progress'  -- the job's own lock, tried, never waited for
  end;
  v_title := 'Run now: ' || coalesce(v_cat.label, p_job) || coalesce(' (' || v_cohort.label || ')', '');
  if v_why is not null then
    if v_why = 'a run of this job is in progress' then
      select jsonb_build_object('pid', a.pid, 'since', a.query_start, 'query', left(a.query, 160)) into v_holder
        from pg_catalog.pg_locks l join pg_catalog.pg_stat_activity a on a.pid = l.pid
       where l.locktype = 'advisory' and l.granted and l.objid = (hashtext('cf247 intake dates apply')::bigint & 4294967295)::oid and a.pid <> pg_backend_pid() limit 1;
    end if;
    insert into pipeline.admin_jobs(id, kind, lane, state, title, args, result, requested_by, reason, created_at, started_at, updated_at, finished_at, scope, outcome)
    values (v_id, 'job_run_now', 'run_now', 'cancelled', v_title || ' (refused)',
            jsonb_strip_nulls(jsonb_build_object('job', p_job, 'cohort_id', v_cohort.id, 'idempotency_key', v_key)),
            jsonb_strip_nulls(jsonb_build_object('refused', v_why, 'in_flight', v_holder)), p_requester, btrim(p_reason), v_start, v_start, clock_timestamp(), clock_timestamp(),
            'cohort:' || coalesce(v_cohort.id::text, '-'), 'blocked_policy');
    return jsonb_strip_nulls(jsonb_build_object('run_id', v_id, 'state', 'refused', 'refused', v_why, 'in_flight', v_holder));
  end if;
  begin
    v_res := security.intake_dates_apply_v1(security.pipeline_num_v1('batch.intake_dates_apply', 200)::int, v_ids);
  exception when others then
    get stacked diagnostics v_err = message_text;
  end;
  -- vendor calls made while it ran (the job reads stored readings only; any call here is unexpected spend)
  select count(*) into v_calls from pipeline.edge_request_log l where l.created_at >= v_start;
  select coalesce(jsonb_object_agg(k, n), '{}'::jsonb) into v_by from (
    select d.outcome || coalesce(': ' || d.reason, '') k, count(*) n from pipeline.course_intake_dates d
     where d.course_id = any (v_ids) and d.applied_at = now() group by 1) x;
  v_res := coalesce(v_res, '{}'::jsonb) || jsonb_build_object(
    'processed', coalesce((v_res->>'looked_at')::int, 0), 'admitted', coalesce((v_res->>'filled')::int, 0),
    'skipped', coalesce((v_res->>'looked_at')::int, 0) - coalesce((v_res->>'filled')::int, 0), 'failed', case when v_err is null then 0 else 1 end,
    'by_outcome', v_by, 'vendor_calls', v_calls, 'cohort_id', v_cohort.id, 'courses', cardinality(v_ids), 'error', v_err);
  insert into pipeline.admin_jobs(id, kind, lane, state, title, args, result, error, requested_by, reason, created_at, started_at, updated_at, finished_at, scope, outcome)
  values (v_id, 'job_run_now', 'run_now', case when v_err is null then 'done' else 'failed' end, v_title,
          jsonb_strip_nulls(jsonb_build_object('job', p_job, 'cohort_id', v_cohort.id, 'idempotency_key', v_key, 'courses', cardinality(v_ids))),
          v_res, v_err, p_requester, btrim(p_reason), v_start, v_start, clock_timestamp(), clock_timestamp(), 'cohort:' || v_cohort.id, case when v_err is not null then 'failed_retryable' when coalesce((v_res->>'admitted')::int, 0) > 0 then 'succeeded_with_result' else 'succeeded_no_movement' end);
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('run_now', case when v_err is null then 'ran' else 'failed' end, p_job, jsonb_build_object('task', v_id, 'cohort_id', v_cohort.id, 'result', v_res), p_requester);
  return jsonb_build_object('run_id', v_id, 'state', case when v_err is null then 'done' else 'failed' end, 'started_at', v_start, 'finished_at', clock_timestamp()) || v_res;
end $$;


ALTER FUNCTION "security"."job_run_now_v1"("p_job" "text", "p_reason" "text", "p_args" "jsonb", "p_requester" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."job_run_now_v1"("p_job" "text", "p_reason" "text", "p_args" "jsonb", "p_requester" "uuid") IS 'CF-247 Run now (Platform Admin 4 Nov 2026 20:05 §3): runs an allowlisted (run_now.jobs), catalogued, scheduled and unpaused job at once on a fixed cohort (run_now.pilot_cap) through the job''s own function and rules; rank as catalogued; reason required; one run at a time (the job''s own advisory lock, tried); idempotency key; records requester, reason, start, finish and counts as a pipeline.admin_jobs row of kind job_run_now. Never takes SQL text.';



CREATE OR REPLACE FUNCTION "security"."json_schema_problems_v1"("p_schema" "jsonb", "p_value" "jsonb", "p_path" "text") RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v_out text[] := '{}'; v_type text := p_schema->>'type'; v_key text; v_el jsonb;
begin
  if v_type is not null and not (
       (v_type = 'object' and jsonb_typeof(p_value) = 'object') or (v_type = 'array' and jsonb_typeof(p_value) = 'array')
    or (v_type = 'string' and jsonb_typeof(p_value) = 'string') or (v_type in ('number', 'integer') and jsonb_typeof(p_value) = 'number')
    or (v_type = 'boolean' and jsonb_typeof(p_value) = 'boolean') or (v_type = 'null' and jsonb_typeof(p_value) = 'null')) then
    return array[p_path || ': expected ' || v_type || ', got ' || coalesce(jsonb_typeof(p_value), 'nothing')];
  end if;
  if p_schema ? 'enum' and not exists (select 1 from jsonb_array_elements(p_schema->'enum') e where e = p_value) then
    v_out := v_out || (p_path || ': not one of ' || (p_schema->'enum')::text);
  end if;
  if v_type = 'object' then
    for v_key in select jsonb_array_elements_text(coalesce(p_schema->'required', '[]'::jsonb)) loop
      if not (p_value ? v_key) then v_out := v_out || (p_path || '.' || v_key || ': required'); end if;
    end loop;
    for v_key in select jsonb_object_keys(p_value) loop
      if p_schema->'properties' ? v_key then
        v_out := v_out || security.json_schema_problems_v1(p_schema->'properties'->v_key, p_value->v_key, p_path || '.' || v_key);
      elsif (p_schema->>'additionalProperties') = 'false' then
        v_out := v_out || (p_path || '.' || v_key || ': not allowed');
      end if;
    end loop;
  elsif v_type = 'array' and p_schema ? 'items' then
    for v_el in select jsonb_array_elements(p_value) loop
      v_out := v_out || security.json_schema_problems_v1(p_schema->'items', v_el, p_path || '[]');
    end loop;
  end if;
  return v_out;
end $$;


ALTER FUNCTION "security"."json_schema_problems_v1"("p_schema" "jsonb", "p_value" "jsonb", "p_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."jsonb_int_v1"("p" "jsonb") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  -- a count in a worker answer: a number is read as a number, a list as its length, anything else as nothing
  select case jsonb_typeof(p) when 'number' then (p #>> '{}')::numeric::int when 'array' then jsonb_array_length(p) end
$$;


ALTER FUNCTION "security"."jsonb_int_v1"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."jsonb_or_null_v1"("p" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin return p::jsonb; exception when others then return null; end $$;


ALTER FUNCTION "security"."jsonb_or_null_v1"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."l4_rule6_apply_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_kept_hand int := 0; v_done int := 0; v_itk int := 0; v_en int := 0; v_fee int := 0; v_ln int := 0; n int; v_courses uuid[] := '{}'; v_res jsonb;
begin
  for r in select c.course_id, c.provider_id, c.url, c.course_code, c.found, c.codes
             from pipeline.rule6_page_checks c
            where c.checked_at is not null and c.found is not true and c.action is null loop
    if exists (select 1 from pipeline.manual_locks m where m.entity = 'course' and m.entity_id = r.course_id and m.field in ('official_url', 'course_url')) then
      update pipeline.rule6_page_checks set action = 'kept: page chosen by hand', acted_at = now() where course_id = r.course_id;
      v_kept_hand := v_kept_hand + 1; continue;
    end if;
    if not exists (select 1 from pipeline.coverage_course_pages p where p.course_id = r.course_id and p.url = r.url) then
      update pipeline.rule6_page_checks set action = 'skipped: no longer bound to this page', acted_at = now() where course_id = r.course_id;
      continue;
    end if;
    insert into pipeline.course_page_blocks(course_id, url, reason)
    values (r.course_id, r.url, 'Rule 6 (8 Oct 2026): page named for another course and the course''s own CRICOS code is not on it') on conflict do nothing;
    update pipeline.coverage_course_pages set status = 'mismatch', read_status = 'identity_mismatch', leased_until = null where course_id = r.course_id;
    update catalogue.course_intakes i set status = 'withdrawn'
     where i.course_id = r.course_id and i.status = 'active' and i.source_id is not null
       and i.evidence_id in (select e.id from pipeline.evidence_artifacts e where e.source_url = r.url);
    get diagnostics n = row_count; v_itk := v_itk + n;
    update catalogue.course_english_requirements q set status = 'withdrawn'
     where q.course_id = r.course_id and coalesce(q.status, 'active') = 'active' and q.source_id is not null
       and q.evidence_id in (select e.id from pipeline.evidence_artifacts e where e.source_url = r.url);
    get diagnostics n = row_count; v_en := v_en + n;
    update catalogue.course_fees f set status = 'superseded', updated_at = now()
     where f.course_id = r.course_id and f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.source_id is not null
       and f.evidence_id in (select e.id from pipeline.evidence_artifacts e where e.source_url = r.url);
    get diagnostics n = row_count; v_fee := v_fee + n;
    update catalogue.course_links l set status = 'inactive'
     where l.course_id = r.course_id and l.status = 'active' and l.url = r.url and l.source_id is not null;
    get diagnostics n = row_count; v_ln := v_ln + n;
    insert into pipeline.course_link_search(course_id, provider_id, stage, state, queued_at)
    values (r.course_id, r.provider_id, case when r.course_code is not null then 'cricos' else 'title' end, 'queued', now())
    on conflict (course_id) do update set stage = excluded.stage, state = 'queued', attempts = 0, query = null, req_id = null, results = null,
           candidates = null, cand_idx = 0, bound_url = null, queued_at = now(), sent_at = null, done_at = null;
    update pipeline.rule6_page_checks set action = 'unbound and sent back to page finding', acted_at = now() where course_id = r.course_id;
    v_done := v_done + 1; v_courses := v_courses || r.course_id;
  end loop;
  if cardinality(v_courses) > 0 then perform search.refresh_course_enrichment_scoped_v1(v_courses, true); end if;
  v_res := jsonb_build_object('unbound', v_done, 'kept_hand_chosen', v_kept_hand, 'intakes_withdrawn', v_itk, 'english_withdrawn', v_en,
                              'fees_superseded', v_fee, 'links_inactive', v_ln);
  insert into pipeline.layer4_rule_runs(rule, raised) values ('unclear_identity', v_res);
  return v_res;
end $$;


ALTER FUNCTION "security"."l4_rule6_apply_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."l4_rule_fee_year_align_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_year int := extract(year from now())::int; v_fees int; v_items int; v_conf int; v_new int; v_old int; v_courses uuid[]; v_r jsonb;
begin
  create temporary table rule3_all on commit drop as
    select f.id, f.course_id, f.audience, ea.captured_at,
           (select g.id from catalogue.course_fees g where g.course_id = f.course_id and g.fee_type = 'provider_current_tuition' and g.audience = f.audience
               and g.status = 'active' and g.fee_year = v_year and g.id <> f.id
             order by g.updated_at desc nulls last limit 1) other_id
      from catalogue.course_fees f join pipeline.evidence_artifacts ea on ea.id = f.evidence_id
     where f.status = 'active' and f.fee_type = 'provider_current_tuition' and f.fee_year is null and f.amount > 0
       and extract(year from ea.captured_at)::int = v_year
       and not exists (select 1 from pipeline.manual_locks m where m.entity = 'course' and m.entity_id = f.course_id and m.field in ('tuition', 'fee', 'fees'));
  select count(*) filter (where other_id is not null) into v_conf from rule3_all;

  -- same-year conflicts: newest evidence wins (a this-year fee with no evidence counts as older)
  create temporary table rule3_conf on commit drop as
    select a.id, a.course_id, a.other_id,
           (a.captured_at > coalesce((select eg.captured_at from catalogue.course_fees g join pipeline.evidence_artifacts eg on eg.id = g.evidence_id where g.id = a.other_id), '-infinity'::timestamptz)) yearless_newer
      from rule3_all a where a.other_id is not null;
  update catalogue.course_fees g
     set status = 'superseded', updated_at = now(),
         notes = concat_ws(' | ', nullif(g.notes, ''), 'Rule 3 (8 Oct 2026): superseded by a newer course page reading for ' || v_year || ' (newest evidence wins)')
   where g.id in (select other_id from rule3_conf where yearless_newer);
  get diagnostics v_new = row_count;
  update catalogue.course_fees f
     set status = 'superseded', updated_at = now(),
         notes = concat_ws(' | ', nullif(f.notes, ''), 'Rule 3 (8 Oct 2026): no year on the page; the ' || v_year || ' fee on record has newer evidence, so it stays (newest evidence wins)')
   where f.id in (select id from rule3_conf where not yearless_newer);
  get diagnostics v_old = row_count;

  create temporary table rule3_fees on commit drop as
    select id, course_id, audience from rule3_all where other_id is null
    union all select c.id, c.course_id, null from rule3_conf c where c.yearless_newer;
  create temporary table rule3_closed on commit drop as
    select course_id from rule3_all;

  update catalogue.course_fees f
     set fee_year = v_year, updated_at = now(),
         notes = concat_ws(' | ', nullif(f.notes, ''), 'Rule 3 (8 Oct 2026): no year on the page; evidence captured in ' || v_year || ', so aligned to ' || v_year || ' without review')
   where f.id in (select id from rule3_fees);
  get diagnostics v_fees = row_count;

  update pipeline.layer4_review_items i
     set status = 'superseded', decided_at = now(),
         escalation_reason = i.escalation_reason || ' Closed by Rule 3 (8 Oct 2026): evidence captured in ' || v_year || ', fee aligned to ' || v_year || ' (where another ' || v_year || ' fee was on record, the newest evidence wins); no review needed.'
   where i.status = 'pending' and i.entity_type = 'course' and i.field_code = 'provider_current_tuition_validation'
     and i.escalation_reason like 'No fee year on record%'
     and i.entity_id in (select course_id from rule3_closed);
  get diagnostics v_items = row_count;

  select coalesce(array_agg(distinct course_id), '{}') into v_courses from rule3_closed;
  if cardinality(v_courses) > 0 then perform search.refresh_course_enrichment_scoped_v1(v_courses, true); end if;

  v_r := jsonb_build_object('year', v_year, 'fees_aligned', v_fees, 'items_closed', v_items, 'same_year_conflicts', v_conf, 'conflict_yearless_newer_won', v_new, 'conflict_dated_fee_kept', v_old);
  insert into pipeline.layer4_rule_runs(rule, raised) values ('fee_year_align', v_r);
  return v_r;
end $$;


ALTER FUNCTION "security"."l4_rule_fee_year_align_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."l4_rule_low_agreement_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a record; q jsonb; v_add text[]; v_done jsonb := '[]'::jsonb; v_checked int := 0; v_country text;
begin
  for a in select u.provider_id, u.admit, u.admit_fields from pipeline.uni_adapters u where u.enabled order by u.provider_id loop
    v_checked := v_checked + 1;
    q := security.adapter_qualify_one_v1(a.provider_id, 0.5, 0.9);
    select k.iso_alpha2 into v_country from catalogue.providers p left join ref.countries k on k.id = p.country_id where p.id = a.provider_id;
    v_add := array(
      select x.k from jsonb_each(coalesce(q->'fields', '{}'::jsonb)) x(k, v)
       where x.k in ('intakes', 'english', 'fee', 'delivery')
         and (x.v->>'read_share')::numeric >= 0.5 and (x.v->>'agree_share')::numeric < 0.9
         and not (a.admit and x.k = any(coalesce(a.admit_fields, '{}')))
         and not (x.k = 'fee' and v_country = 'CA')
         and not exists (select 1 from pipeline.l4_rule4_holds h where h.provider_id = a.provider_id and h.field = x.k)
       order by x.k);
    if cardinality(v_add) > 0 then
      update pipeline.uni_adapters u
         set admit = true,
             admit_fields = array(select distinct f from unnest(case when a.admit then coalesce(a.admit_fields, '{}') else '{}'::text[] end || v_add) f order by f),
             admit_reason = 'Rule 4 (daily): low agreement, page wins - ' || array_to_string(v_add, ', ') || ' admitted', admit_changed_at = now()
       where u.provider_id = a.provider_id;
      insert into pipeline.admin_control_events(area, action, target, detail, actor)
      values ('toolsets', 'uni_adapter_admit', a.provider_id::text,
              jsonb_build_object('admit', true, 'fields', (select to_jsonb(u.admit_fields) from pipeline.uni_adapters u where u.provider_id = a.provider_id),
                                 'reason', 'Rule 4 (daily): low agreement, page wins', 'rule', 'rule_4', 'qualify', q->'fields'), null);
      perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'adapter_apply', 'provider_id', a.provider_id));
      v_done := v_done || jsonb_build_object('provider_id', a.provider_id, 'fields', to_jsonb(v_add));
    end if;
  end loop;
  insert into pipeline.layer4_rule_runs(rule, raised) values ('low_agreement', jsonb_build_object('adapters_checked', v_checked, 'admitted', v_done));
  return jsonb_build_object('adapters_checked', v_checked, 'admitted', jsonb_array_length(v_done));
end $$;


ALTER FUNCTION "security"."l4_rule_low_agreement_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."l4_rule_unofficial_source_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_i int; v_e int; v_l int; v_hosts text[]; v_r jsonb;
begin
  select array(select distinct h from (
      select substring(pg.url from '^https?://(?:www\.)?([^/:?#]+)') h from pipeline.coverage_course_pages pg
       group by 1 having count(distinct pg.provider_id) >= 3
      union
      select jsonb_array_elements_text(coalesce((select e.detail->'hosts' from pipeline.retention_estimates e where e.category = 'directory_urls'), '[]'::jsonb))) x where h is not null)
    into v_hosts;

  create temporary table rule_pages on commit drop as
    select pg.course_id, pg.provider_id, pg.url, pg.evidence_id, substring(pg.url from '^https?://(?:www\.)?([^/:?#]+)') host
      from pipeline.coverage_course_pages pg join catalogue.providers p on p.id = pg.provider_id
     where pg.evidence_id is not null and substring(pg.url from '^https?://(?:www\.)?([^/:?#]+)') = any(v_hosts)
       and (p.website is null or not (
             substring(pg.url from '^https?://(?:www\.)?([^/:?#]+)') = substring(p.website from '^https?://(?:www\.)?([^/:?#]+)')
             or substring(pg.url from '^https?://(?:www\.)?([^/:?#]+)') like '%.' || substring(p.website from '^https?://(?:www\.)?([^/:?#]+)')));

  insert into pipeline.layer4_review_items(entity_type, entity_id, field_code, evidence_id, before_value, proposed_value, status, escalation_reason, change_control_ref)
  select 'course', d.course_id, 'course_intake', d.evidence_id, jsonb_agg(distinct i.intake_label),
         jsonb_build_object('intakes', jsonb_agg(distinct jsonb_build_object('intake_label', i.intake_label, 'source_intake_key', null))), 'pending',
         format('Rule 1, source is not the provider''s own site: read from %s (%s), a site shared by several providers. The register confirms the course; confirm the intakes on the provider''s own course page. Approve keeps them as they are; the value stays shown until decided.', d.host, d.url),
         'CF-CHG-20260915-247'
    from rule_pages d join catalogue.course_intakes i on i.course_id = d.course_id and i.evidence_id = d.evidence_id and i.status = 'active'
   where not exists (select 1 from pipeline.layer4_review_items r where r.entity_type = 'course' and r.entity_id = d.course_id and r.field_code = 'course_intake'
                       and (r.status = 'pending' or r.evidence_id = d.evidence_id))
   group by d.course_id, d.evidence_id, d.host, d.url;
  get diagnostics v_i = row_count;

  insert into pipeline.layer4_review_items(entity_type, entity_id, field_code, evidence_id, before_value, proposed_value, status, escalation_reason, change_control_ref)
  select 'course', d.course_id, 'course_english', d.evidence_id, jsonb_agg(jsonb_build_object('test', t.code, 'overall', e.overall_score)),
         jsonb_build_object('english_requirements', jsonb_agg(jsonb_build_object('notes', 'Shared-site page, kept after review', 'test_code', t.code, 'overall_score', e.overall_score, 'component_scores', coalesce(e.component_scores, '{}'::jsonb)))), 'pending',
         format('Rule 1, source is not the provider''s own site: read from %s (%s), a site shared by several providers. The register confirms the course; confirm the English requirement on the provider''s own course page. Approve keeps it as it is; the value stays shown until decided.', d.host, d.url),
         'CF-CHG-20260915-247'
    from rule_pages d join catalogue.course_english_requirements e on e.course_id = d.course_id and e.evidence_id = d.evidence_id and e.status = 'active'
    join ref.english_tests t on t.id = e.english_test_id
   where not exists (select 1 from pipeline.layer4_review_items r where r.entity_type = 'course' and r.entity_id = d.course_id and r.field_code = 'course_english'
                       and (r.status = 'pending' or r.evidence_id = d.evidence_id))
   group by d.course_id, d.evidence_id, d.host, d.url;
  get diagnostics v_e = row_count;

  insert into pipeline.layer4_review_items(entity_type, entity_id, field_code, evidence_id, before_value, proposed_value, status, escalation_reason, change_control_ref)
  select distinct on (d.course_id) 'course', d.course_id, 'official_course_url', d.evidence_id, jsonb_build_array(l.url), jsonb_build_object('course_url', l.url), 'pending',
         format('Rule 1, source is not the provider''s own site: the official course page on record is on %s, a site shared by several providers. Find the provider''s own course page and edit the address, or reject. The link stays shown until decided.', d.host),
         'CF-CHG-20260915-247'
    from rule_pages d join catalogue.course_links l on l.course_id = d.course_id and l.url = d.url and l.status = 'active'
   where not exists (select 1 from pipeline.layer4_review_items r where r.entity_type = 'course' and r.entity_id = d.course_id and r.field_code = 'official_course_url'
                       and (r.status = 'pending' or r.evidence_id = d.evidence_id))
   order by d.course_id, l.is_primary desc;
  get diagnostics v_l = row_count;

  v_r := jsonb_build_object('hosts', to_jsonb(v_hosts), 'intake_items', v_i, 'english_items', v_e, 'course_link_items', v_l);
  insert into pipeline.layer4_rule_runs(rule, raised) values ('unofficial_source', v_r);
  return v_r;
end $$;


ALTER FUNCTION "security"."l4_rule_unofficial_source_v1"() OWNER TO "postgres";


