CREATE OR REPLACE FUNCTION "security"."lane_funnel_eval_v1"("p_sql" "text", "p_window_hours" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_sql text; v_rows jsonb;
begin
  -- STABLE: a write inside the statement (even in a CTE) is refused by the database itself; the checks below refuse it earlier, in words
  v_sql := replace(btrim(coalesce(p_sql, ''), E' \n\t\r;'), '{window}', format('make_interval(hours => %s)', greatest(coalesce(p_window_hours, 1), 1)));  -- fixed: at least one hour
  if v_sql !~* '^\s*(select|with)\s' or position(';' in v_sql) > 0
     or v_sql ~* '\m(insert|update|delete|truncate|drop|alter|create|grant|revoke|copy|call|execute|pg_sleep|set_config|dblink|lo_import)\M' then
    raise exception 'lane funnel: a stage must be one read-only SELECT (no semicolon, no write keyword)';
  end if;
  execute format('select coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) from (%s) t', v_sql) into v_rows;
  return v_rows;
end $$;


ALTER FUNCTION "security"."lane_funnel_eval_v1"("p_sql" "text", "p_window_hours" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."lane_funnel_job_runs_refresh_v1"("p_force" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_every int := security.pipeline_num_v1('lane_funnel.job_runs_refresh_seconds', 45)::int;
  v_win int := security.pipeline_num_v1('lane_funnel.gain_window_hours', 24)::int;
  v_hist int := security.pipeline_num_v1('lane_funnel.run_history_hours', 48)::int;
  v_t0 timestamptz; v_rows jsonb; v_due boolean;
begin
  if to_regnamespace('cron') is null then return jsonb_build_object('refreshed', false, 'skipped', 'no scheduler'); end if;
  -- due: never summarised, older than the setting, made for another window (a changed window is picked up at once), or the last try failed and its wait is over
  select coalesce(p_force or r.measured_at is null or coalesce(r.failed_at, r.measured_at) < now() - make_interval(secs => v_every)
                  or r.window_hours is distinct from v_win or r.history_hours is distinct from v_hist, true)
    into v_due from (select 1) one left join pipeline.lane_funnel_job_runs r on r.singleton;
  if not v_due then return jsonb_build_object('refreshed', false, 'skipped', 'not due'); end if;
  v_t0 := clock_timestamp();
  begin
    -- ONE pass over the scheduler history for every job of every lane; the run in progress (this one, when job lane-funnel calls it) is not counted as the job's last attempt
    with want as (select distinct j.jobname from pipeline.lane_funnel_lanes l cross join lateral unnest(l.jobs) j(jobname)),
    ids as (select c.jobid, w.jobname from want w join cron.job c on c.jobname = w.jobname),
    h as (
      select d.jobid, max(d.start_time) as last_start, (array_agg(d.end_time order by d.start_time desc))[1] as last_end, (array_agg(d.status order by d.start_time desc))[1] as last_status,
             (array_agg(left(d.return_message, 240) order by d.start_time desc))[1] as last_message,  -- fixed: the scheduler's message is cut so a summary row stays small
             max(d.start_time) filter (where d.status = 'succeeded') as last_success,
             count(*) filter (where d.start_time > now() - make_interval(hours => v_win)) as runs,
             count(*) filter (where d.start_time > now() - make_interval(hours => v_win) and d.status = 'failed') as failed,
             count(*) filter (where d.start_time > now() - make_interval(hours => v_win) and d.status = 'succeeded') as succeeded,
             bool_or(d.status in ('running', 'starting')) as running
        from cron.job_run_details d
       where d.jobid in (select i.jobid from ids i) and d.start_time > now() - make_interval(hours => v_hist) and d.job_pid is distinct from pg_backend_pid()
       group by d.jobid)
    select coalesce(jsonb_object_agg(w.jobname, jsonb_build_object('last_start', h.last_start, 'last_end', h.last_end, 'last_status', h.last_status, 'last_message', h.last_message,
             'last_success', h.last_success, 'runs', coalesce(h.runs, 0), 'failed', coalesce(h.failed, 0), 'succeeded', coalesce(h.succeeded, 0), 'running', coalesce(h.running, false))), '{}'::jsonb)
      into v_rows from want w left join ids i on i.jobname = w.jobname left join h on h.jobid = i.jobid;
    insert into pipeline.lane_funnel_job_runs as r(singleton, measured_at, window_hours, history_hours, jobs, took_ms, error, failed_at)
      values (true, clock_timestamp(), v_win, v_hist, v_rows,
              (extract(epoch from clock_timestamp() - v_t0) * 1000)::int,  -- fixed: seconds to milliseconds
              null, null)
      on conflict (singleton) do update set measured_at = excluded.measured_at, window_hours = excluded.window_hours, history_hours = excluded.history_hours, jobs = excluded.jobs,
                                            took_ms = excluded.took_ms, error = null, failed_at = null;
    return jsonb_build_object('refreshed', true, 'jobs', (select count(*) from jsonb_object_keys(v_rows)));
  exception when others then
    -- a failed summary never overwrites the last good one: its rows and time stay, the error and its time are added (the read marks the history stale)
    insert into pipeline.lane_funnel_job_runs as r(singleton, measured_at, window_hours, history_hours, jobs, took_ms, error, failed_at)
      values (true, clock_timestamp(), v_win, v_hist, null,
              (extract(epoch from clock_timestamp() - v_t0) * 1000)::int,  -- fixed: seconds to milliseconds
              left(sqlerrm, 300),  -- fixed: an error text is cut so the row stays small
              clock_timestamp())
      on conflict (singleton) do update set took_ms = excluded.took_ms, error = excluded.error, failed_at = excluded.failed_at;
    return jsonb_build_object('refreshed', false, 'error', left(sqlerrm, 300));  -- fixed: an error text is cut so the answer stays small
  end;
end $$;


ALTER FUNCTION "security"."lane_funnel_job_runs_refresh_v1"("p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."lane_funnel_refresh_v1"("p_force" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  s record; v_rows jsonb; v_t0 timestamptz; v_prev text := current_setting('statement_timeout');
  v_every int := security.pipeline_num_v1('lane_funnel.refresh_minutes', 15)::int;
  v_win int := security.pipeline_num_v1('lane_funnel.gain_window_hours', 24)::int;
  v_to int := security.pipeline_num_v1('lane_funnel.stage_timeout_seconds', 20)::int;
  v_hist int := security.pipeline_num_v1('lane_funnel.history_minutes', 60)::int;
  v_keep int := security.pipeline_num_v1('lane_funnel.keep_days', 30)::int;
  v_done int := 0; v_failed int := 0; v_n numeric; v_old timestamptz; v_gain numeric; v_reasons jsonb;
begin
  if security.pipeline_num_v1('lane_funnel.on', 1) < 1 and not p_force then return jsonb_build_object('skipped', 'switched off (lane_funnel.on)'); end if;
  if not pg_try_advisory_xact_lock(hashtext('lane_funnel_refresh')) then return jsonb_build_object('skipped', 'another count is running'); end if;
  perform set_config('statement_timeout', (v_to * 1000)::text, true);  -- fixed: the setting is in seconds, the database wants milliseconds
  for s in select st.lane, st.key, st.count_sql from pipeline.lane_funnel_stages st where st.count_sql is not null order by st.lane, st.step loop
    if not p_force and exists (select 1 from pipeline.lane_funnel_readings r where r.lane = s.lane and r.stage_key = s.key and r.error is null
                                  and r.measured_at > now() - make_interval(mins => v_every)) then continue; end if;
    v_t0 := clock_timestamp();
    begin
      v_rows := security.lane_funnel_eval_v1(s.count_sql, v_win);
      if jsonb_array_length(v_rows) = 0 then v_n := 0; v_old := null; v_gain := null; v_reasons := null;
      elsif v_rows->0 ? 'reason' then
        select coalesce(sum((x->>'n')::numeric), 0), min((x->>'oldest')::timestamptz), sum((x->>'gain')::numeric) into v_n, v_old, v_gain from jsonb_array_elements(v_rows) x;
        v_reasons := v_rows;
      else
        v_n := (v_rows->0->>'n')::numeric; v_old := (v_rows->0->>'oldest')::timestamptz; v_gain := (v_rows->0->>'gain')::numeric; v_reasons := null;
      end if;
      insert into pipeline.lane_funnel_readings as r(lane, stage_key, measured_at, n, oldest_at, gain, reasons, took_ms, error)
        values (s.lane, s.key, clock_timestamp(), v_n, v_old, v_gain, v_reasons, (extract(epoch from clock_timestamp() - v_t0) * 1000)::int, null)
        on conflict (lane, stage_key) do update set measured_at = excluded.measured_at, n = excluded.n, oldest_at = excluded.oldest_at, gain = excluded.gain,
          reasons = excluded.reasons, took_ms = excluded.took_ms, error = null;
      v_done := v_done + 1;
    exception when others then
      insert into pipeline.lane_funnel_readings as r(lane, stage_key, measured_at, n, oldest_at, gain, reasons, took_ms, error)
        values (s.lane, s.key, clock_timestamp(), null, null, null, null, (extract(epoch from clock_timestamp() - v_t0) * 1000)::int, left(sqlerrm, 300))
        on conflict (lane, stage_key) do update set measured_at = excluded.measured_at, n = null, oldest_at = null, gain = null, reasons = null, took_ms = excluded.took_ms, error = excluded.error;
      v_failed := v_failed + 1;
    end;
  end loop;
  insert into pipeline.lane_funnel_history(lane, stage_key, measured_at, n, gain)
    select r.lane, r.stage_key, r.measured_at, r.n, r.gain from pipeline.lane_funnel_readings r
     where r.n is not null and not exists (select 1 from pipeline.lane_funnel_history h where h.lane = r.lane and h.stage_key = r.stage_key and h.measured_at > now() - make_interval(mins => v_hist))
    on conflict do nothing;
  delete from pipeline.lane_funnel_history where measured_at < now() - make_interval(days => v_keep);
  -- the scheduler history of the lane jobs, summarised in one pass for the lane funnel read, at the END of the run (after the stage counts, so it is as recent as the run can make it).
  -- Its own handler records a failure of the summary; this block makes sure that nothing it does can stop the run: the stage counts above are already written.
  begin
    perform security.lane_funnel_job_runs_refresh_v1(p_force);
  exception when others then
    raise warning 'lane funnel job history summary failed: %', left(sqlerrm, 300);  -- fixed: an error text is cut so the log line stays short
  end;
  perform set_config('statement_timeout', v_prev, true);
  return jsonb_build_object('counted', v_done, 'failed', v_failed);
end $$;


ALTER FUNCTION "security"."lane_funnel_refresh_v1"("p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."lane_funnel_v1"("p_lane" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  l record; v_out jsonb := '[]'::jsonb; v_lane jsonb; v_jobs jsonb; v_sw jsonb; v_set jsonb; v_stages jsonb; v_issues jsonb; v_budget jsonb;
  v_win int := security.pipeline_num_v1('lane_funnel.gain_window_hours', 24)::int;
  v_hist int := security.pipeline_num_v1('lane_funnel.run_history_hours', 48)::int;
  v_stale int := security.pipeline_num_v1('lane_funnel.stale_after_minutes', 45)::int;
  v_max int := security.pipeline_num_v1('lane_funnel.settings_shown_max', 60)::int;
  v_fc jsonb := security.fc_budget_status_v1();
  -- how old the job-history summary may be before it is marked stale, in seconds: the longer of the setting and two looks of job lane-funnel plus a grace, so allowed settings never leave it stale for good
  v_jr_stale_after int := greatest(security.pipeline_num_v1('lane_funnel.job_runs_stale_minutes', 5)::int * 60,  -- fixed: minutes to seconds
                                   2 * greatest(security.pipeline_num_v1('lane_funnel.job_runs_refresh_seconds', 45)::int, 60) + 30);  -- fixed: job lane-funnel looks once a minute (its schedule), so a summary is made again at most every second look; two looks and 30 s of grace before it is called stale
  v_jr jsonb; v_jr_at timestamptz; v_jr_err text; v_jr_win int; v_jr_hist int; v_jr_failed timestamptz; v_jr_stale boolean; v_jh_state text;
  v_active int; v_jobs_n int; v_failing int; v_green int; v_eligible numeric; v_transfer numeric; v_transfer_known boolean; v_published numeric;
  v_verdict text; v_off_switch boolean; v_unknown_switch boolean;
begin
  -- the scheduler history of the lane jobs is read from the summary that job lane-funnel keeps at the end of each run (security.lane_funnel_job_runs_refresh_v1), not from the
  -- scheduler's run table: that table has no index on (job, time), so the old two scans per job per lane read 82 thousand rows each time
  select r.jobs, r.measured_at, r.error, r.window_hours, r.history_hours, r.failed_at into v_jr, v_jr_at, v_jr_err, v_jr_win, v_jr_hist, v_jr_failed
    from pipeline.lane_funnel_job_runs r where r.singleton;
  -- stale: older than its threshold, a failed last summary, one made for another window, or none; a stale or missing summary is never shown as current (the lane verdict says unknown)
  v_jr_stale := v_jr is null or v_jr_at < now() - make_interval(secs => v_jr_stale_after) or v_jr_err is not null or v_jr_win is distinct from v_win or v_jr_hist is distinct from v_hist;
  for l in select * from pipeline.lane_funnel_lanes x where p_lane is null or x.lane = p_lane order by x.sort, x.lane loop
    -- jobs: schedule, state, next run, last attempt and result over the scheduler history, first-run verification of the newest release
    select coalesce(jsonb_agg(jb order by jb->>'job'), '[]'::jsonb) into v_jobs from (
      select jsonb_build_object('job', j.jobname, 'label', a.label, 'schedule', c.schedule, 'active', c.active, 'scheduled', c.jobid is not null, 'control_rank', coalesce(a.control_rank, 6),
          'next_run', case when c.jobid is not null and c.active then security.cron_next_run_v1(c.schedule, now()) end,
          'running', coalesce(g.running, false), 'runs', coalesce(g.runs, 0), 'failed', coalesce(g.failed, 0), 'succeeded', coalesce(g.succeeded, 0),
          'last_start', g.last_start, 'last_end', g.last_end, 'last_status', g.last_status, 'last_message', g.last_message,
          'last_success', g.last_success, 'history_known', coalesce(jsonb_typeof(v_jr -> j.jobname) = 'object', false),
          'first_run', (select jsonb_build_object('release', v.release, 'status', v.status, 'first_run_status', v.first_run_status, 'first_run_at', v.first_run_at,
                                                  'expected_first_run', v.expected_first_run, 'actual_output', v.actual_output, 'reason', left(v.status_reason, 200))
                          from pipeline.release_job_verifications v where v.jobname = j.jobname order by v.registered_at desc limit 1)) jb
        from unnest(l.jobs) j(jobname)
        left join pipeline.automation_catalogue a on a.jobname = j.jobname
        left join cron.job c on c.jobname = j.jobname
        left join lateral (select x.* from jsonb_to_record(case when jsonb_typeof(v_jr -> j.jobname) = 'object' then v_jr -> j.jobname end)
                             as x(last_start timestamptz, last_end timestamptz, last_status text, last_message text, last_success timestamptz,
                                  runs integer, failed integer, succeeded integer, running boolean)) g on true) q;
    select count(*) filter (where (x->>'active')::boolean), count(*), count(*) filter (where (x->>'failed')::int > 0),
           count(*) filter (where (x->>'active')::boolean and (x->>'succeeded')::int > 0 and (x->>'failed')::int = 0)
      into v_active, v_jobs_n, v_failing, v_green from jsonb_array_elements(v_jobs) x;
    -- switches: a pipeline setting that is 1 / true is on, 0 / false is off, a missing setting is unknown
    select coalesce(jsonb_agg(jsonb_build_object('key', k.key, 'label', s.label, 'value', s.value, 'on', case when s.key is null then null else (s.value #>> '{}') in ('1', 'true') end) order by k.ord), '[]'::jsonb)
      into v_sw from unnest(l.switch_keys) with ordinality k(key, ord) left join pipeline.platform_toolset_settings s on s.toolset_key = 'pipeline' and s.key = k.key;
    select bool_or(x->'on' = 'false'::jsonb), bool_or(x->'on' = 'null'::jsonb) into v_off_switch, v_unknown_switch from jsonb_array_elements(v_sw) x;
    select coalesce(jsonb_agg(jsonb_build_object('key', s.key, 'label', s.label, 'help', s.help, 'value', s.value, 'unit', s.unit, 'min', s.min_value, 'max', s.max_value, 'section', s.section,
                                                 'used_by', s.used_by, 'updated_at', s.updated_at, 'reason', s.reason) order by s.sort, s.key), '[]'::jsonb) into v_set
      from (select x.* from pipeline.platform_toolset_settings x where x.toolset_key = 'pipeline'
              and exists (select 1 from unnest(l.setting_prefixes) p where left(x.key, length(p)) = p) order by x.sort, x.key limit v_max) s;
    -- stages
    select coalesce(jsonb_agg(sg order by (sg->>'step')::int), '[]'::jsonb) into v_stages from (
      select jsonb_build_object('step', st.step, 'key', st.key, 'title', st.title, 'kind', st.kind, 'what', st.what, 'drill', st.drill,
          'source', case when st.transition_key is not null then 'progress contract' else 'counted' end,
          'n', case when t.key is not null then t.input_eligible else r.n end,
          'oldest_at', case when t.key is not null then null else r.oldest_at end,
          'gain', case when t.key is not null then case st.kind when 'admitted' then t.output_admitted when 'published' then t.output_published else t.output_created end else r.gain end,
          'processed', case when t.key is not null then t.input_processed end,
          'created', case when t.key is not null then t.output_created end,
          'reasons', case when t.key is not null then nullif(jsonb_strip_nulls(jsonb_build_object('rejected', t.rejected_reasons, 'parked', t.parked_next_actions)), '{}'::jsonb) else r.reasons end,
          'zero_reason', t.zero_reason, 'zero_detail', t.zero_detail, 'stalled', coalesce(t.stalled, false), 'last_advanced_at', t.last_advanced_at,
          'window_start', t.window_start,
          'measured_at', case when t.key is not null then t.measured_at else r.measured_at end,
          'stale', coalesce(case when t.key is not null then t.measured_at else r.measured_at end < now() - make_interval(mins => v_stale), false),
          'error', case when t.key is not null then t.measure_error else r.error end,
          'took_ms', r.took_ms,
          'n_prev', (select h.n from pipeline.lane_funnel_history h where h.lane = st.lane and h.stage_key = st.key and h.measured_at <= now() - make_interval(hours => v_win)
                      order by h.measured_at desc limit 1)) sg
        from pipeline.lane_funnel_stages st
        left join pipeline.progress_transitions t on t.key = st.transition_key
        left join pipeline.lane_funnel_readings r on r.lane = st.lane and r.stage_key = st.key
       where st.lane = l.lane) q;
    -- verdict: a green job, a stage transfer and published data are three different things
    select sum((x->>'n')::numeric) filter (where x->>'kind' in ('eligible', 'queued', 'review_ready')),
           sum((x->>'gain')::numeric) filter (where x->>'kind' = 'admitted'), bool_or(x->>'gain' is not null) filter (where x->>'kind' = 'admitted'),
           sum((x->>'gain')::numeric) filter (where x->>'kind' = 'published')
      into v_eligible, v_transfer, v_transfer_known, v_published from jsonb_array_elements(v_stages) x;
    -- the state of the job history behind this lane's job results: unknown (no summary, or a job of the lane that is on is not in it), stale (older than its threshold, failed, other window) or current
    v_jh_state := case when v_jobs_n = 0 then 'current'
                       when v_jr is null or exists (select 1 from jsonb_array_elements(v_jobs) x where (x->>'active')::boolean and not (x->>'history_known')::boolean) then 'unknown'
                       when v_jr_stale then 'stale' else 'current' end;
    v_verdict := case
      when v_jobs_n = 0 and not exists (select 1 from jsonb_array_elements(v_sw) x) then 'unknown'
      when coalesce(v_off_switch, false) or (v_jobs_n > 0 and v_active = 0) then 'off'
      -- a verdict that rests on job results is not given from a history that is unknown or stale (all-zero counts would read as idle or transferring, an old failure as failing)
      when v_jh_state <> 'current' then 'unknown'
      when v_failing > 0 then 'failing'
      when exists (select 1 from jsonb_array_elements(v_stages) x where (x->>'stalled')::boolean) then 'stalled'
      when coalesce(v_transfer, 0) > 0 or coalesce(v_published, 0) > 0 then 'transferring'
      when v_green > 0 and coalesce(v_eligible, 0) > 0 and coalesce(v_transfer_known, false) then 'green_no_transfer'
      when v_green > 0 and not coalesce(v_transfer_known, false) and coalesce(v_published, 0) = 0 then 'green_transfer_unknown'
      else 'idle' end;
    select coalesce(jsonb_agg(jsonb_build_object('ref', i.issue_ref, 'title', i.title, 'status', i.status, 'severity', i.severity) order by i.issue_ref), '[]'::jsonb) into v_issues
      from pipeline.integration_issues i where i.issue_ref = any(l.issue_refs);
    v_budget := case when l.budget_group is null then null else (
      select jsonb_build_object('group', l.budget_group, 'label', g->>'label', 'share_today', (g->>'share')::numeric, 'used_today', (g->>'used')::numeric, 'refused_today', (g->>'refused')::numeric,
                                'credits_window', coalesce((select sum(u.units) from pipeline.coverage_vendor_usage u where u.at > now() - make_interval(hours => v_win) and security.fc_purpose_group_v1(u.purpose) = l.budget_group), 0),
                                'unit', 'credits', 'shared', 'the group is shared by every lane that reads with it')
        from jsonb_array_elements(v_fc->'groups') g where g->>'group' = l.budget_group) end;
    v_lane := jsonb_build_object('lane', l.lane, 'title', l.title, 'what', l.what, 'screen', l.screen, 'review_kinds', to_jsonb(l.review_kinds), 'verdict', v_verdict,
      'job_history_state', v_jh_state,
      'jobs', v_jobs, 'jobs_active', v_active, 'jobs_total', v_jobs_n, 'jobs_failing', v_failing, 'jobs_green', v_green, 'switches', v_sw, 'settings', v_set, 'stages', v_stages, 'issues', v_issues,
      'budget', v_budget, 'transfer_24h', v_transfer, 'published_24h', v_published);
    v_out := v_out || jsonb_build_array(v_lane);
  end loop;
  return jsonb_build_object('at', now(), 'window_hours', v_win, 'lanes', v_out,
    -- how fresh the job history is: a summary older than its threshold, a failed last summary, or one made for another window is stale, never shown as current
    'job_history', jsonb_build_object('known', v_jr is not null, 'measured_at', v_jr_at, 'age_seconds', case when v_jr_at is not null then round(extract(epoch from now() - v_jr_at)) end,
      'stale', v_jr_stale,
      'error', v_jr_err, 'failed_at', v_jr_failed, 'window_hours', v_jr_win, 'history_hours', v_jr_hist, 'stale_after_seconds', v_jr_stale_after),
    'meaning', jsonb_build_object('green_job', 'the scheduler reports the job as succeeded; it says nothing about data',
      'stage_transfer', 'items that moved into the admitted stage in the window (a new value held in the catalogue)',
      'published', 'items that reached the consumer-visible stage in the window'));
end $$;


ALTER FUNCTION "security"."lane_funnel_v1"("p_lane" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."lane_paid_hold_v1"("p_purpose" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v text;
begin
  if p_purpose is null then return null; end if;
  v := security.fc_month_refusal_v1(1);  -- fixed: one credit, the smallest spend
  if v is not null then return 'budget_held: ' || v; end if;
  if security.fc_budget_left_v1(p_purpose) < 1 then  -- fixed: one credit, the smallest spend
    -- CF-247 priority floor (8 Nov 2026): course page search waits while the plan's balance is kept for higher-priority work
    if security.fc_purpose_group_v1(p_purpose) = 'course_search' and coalesce(security.fc_priority_room_v1(), 1) < 1 then  -- fixed: one credit, the smallest spend
      return 'budget_held: Firecrawl balance kept for higher-priority work (priority floor ' || security.fc_setting_num_v1('priority_floor_course_search', 0)::bigint || ' credits)';
    end if;
    return 'budget_held: no room left in today''s Firecrawl share for ' || security.fc_purpose_group_v1(p_purpose);
  end if;
  return null;
end $$;


ALTER FUNCTION "security"."lane_paid_hold_v1"("p_purpose" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."lane_queue_wait_v1"("p_hours" integer DEFAULT 24) RETURNS TABLE("lane" "text", "finished" bigint, "p50_min" numeric, "p90_min" numeric, "max_min" numeric, "waiting" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with w as (
    select 'fee_reader' lane, extract(epoch from (q.finished_at - q.created_at)) / 60 m from pipeline.fee_reader_queue q where q.finished_at > now() - make_interval(hours => p_hours)
    union all
    select 'enrich_fields', extract(epoch from (i.updated_at - i.created_at)) / 60 from pipeline.field_enrich_items i where i.updated_at > now() - make_interval(hours => p_hours) and i.state in ('filled', 'skipped', 'review', 'applied')
    union all
    select 'course_page_read', extract(epoch from (p.read_at - p.next_read_at)) / 60 from pipeline.coverage_course_pages p where p.read_at > now() - make_interval(hours => p_hours) and p.next_read_at is not null and p.read_at >= p.next_read_at
    union all
    select 'ai_page_match', extract(epoch from (q.decided_at - q.created_at)) / 60 from pipeline.coverage_ai_match q where q.decided_at > now() - make_interval(hours => p_hours)
    union all
    select 'course_page_search', extract(epoch from (s.done_at - coalesce(s.requested_at, s.queued_at))) / 60 from pipeline.course_link_search s where s.done_at > now() - make_interval(hours => p_hours)
    union all
    select 'central_ai', extract(epoch from (q.done_at - q.created_at)) / 60 from pipeline.central_ai_queue q where q.done_at > now() - make_interval(hours => p_hours)),
  q as (
    select 'fee_reader' lane, count(*) n from pipeline.fee_reader_queue where state = 'queued'
    union all select 'enrich_fields', count(*) from pipeline.field_enrich_items where state = 'queued'
    union all select 'course_page_read', count(*) from pipeline.coverage_course_pages p where p.status in ('bound', 'ambiguous') and coalesce(p.next_read_at, now()) <= now() and p.read_attempts < 3
    union all select 'ai_page_match', count(*) from pipeline.coverage_ai_match where state = 'ready'
    union all select 'course_page_search', count(*) from pipeline.course_link_search where state = 'queued'
    union all select 'central_ai', count(*) from pipeline.central_ai_queue where state = 'queued')
  select q.lane, count(w.m) finished, round(percentile_cont(0.5) within group (order by w.m)::numeric, 1), round(percentile_cont(0.9) within group (order by w.m)::numeric, 1), round(max(w.m)::numeric, 1), max(q.n)
    from q left join w on w.lane = q.lane group by q.lane order by q.lane
$$;


ALTER FUNCTION "security"."lane_queue_wait_v1"("p_hours" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."lane_queue_wait_v1"("p_hours" integer) IS 'R1 Q3: queue wait (minutes, p50/p90/max) and rows waiting per reader lane over the last p_hours, from the queues'' timestamps';



CREATE OR REPLACE FUNCTION "security"."lane_status_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_since timestamptz := now() - make_interval(mins => security.pipeline_num_v1('lanes.status_window_minutes', 60)::int);
        v_day timestamptz := security.fc_day_start_v1(); v jsonb := '[]'::jsonb; r record; v_led jsonb; k pipeline.field_gap_queue_checkpoint%rowtype;
        v_last pipeline.field_gap_queue_runs%rowtype;
begin
  for r in select * from (values ('stored_evidence', 'Stored evidence and direct reads', 1), ('paid_acquisition', 'New paid pages (Firecrawl)', 2),
                                 ('ai_extraction', 'AI extraction', 3)) x(lane, label, sort) loop
    select jsonb_build_object('calls', count(*), 'processed', coalesce(sum(y.ok) filter (where y.lane_outcome = 'done'), 0),
             'failed', count(*) filter (where y.lane_outcome = 'failed'),
             'held', coalesce((select jsonb_object_agg(z.o, z.n) from (select y2.lane_outcome o, count(*) n from pipeline.mode_outcome_ledger y2 join pipeline.worker_mode_lanes l2 on l2.mode = y2.mode
                                                                     where l2.lane = r.lane and y2.run_at > v_since and y2.lane_outcome in ('budget_held', 'source_limit', 'switched_off') group by 1) z), '{}'::jsonb),
             'hold_reasons', coalesce((select jsonb_agg(distinct left(y3.hold_reason, 160)) from pipeline.mode_outcome_ledger y3 join pipeline.worker_mode_lanes l3 on l3.mode = y3.mode
                                        where l3.lane = r.lane and y3.run_at > v_since and y3.lane_outcome in ('budget_held', 'source_limit', 'switched_off', 'failed')), '[]'::jsonb),
             'idle', count(*) filter (where y.lane_outcome = 'idle'))
      into v_led
      from pipeline.mode_outcome_ledger y join pipeline.worker_mode_lanes l on l.mode = y.mode
     where l.lane = r.lane and y.run_at > v_since;
    v := v || (jsonb_build_object('lane', r.lane, 'label', r.label, 'window_since', v_since) || v_led || case r.lane
      when 'stored_evidence' then jsonb_build_object(
        'eligible', jsonb_build_object(
          'course_pages_due', (select count(*) from pipeline.coverage_course_pages p where p.status in ('bound', 'ambiguous') and coalesce(p.next_read_at, now()) <= now() and p.read_attempts < 3)),  -- fixed: the read picker's own try limit
        'live_hold', null, 'cost', jsonb_build_object('firecrawl_credits_today', 0, 'ai_usd_today', 0))
      when 'paid_acquisition' then jsonb_build_object(
        'eligible', jsonb_build_object(
          'course_searches_queued', (select count(*) from pipeline.course_link_search s where s.state = 'queued'),
          'central_searches_queued', (select count(*) from pipeline.provider_central_search s where s.state = 'queued'),
          'scholarship_listings_due', (select count(*) from pipeline.scholarship_listing_pages s where s.active and s.source <> 'suggested' and coalesce(s.next_read_at, now()) <= now()),
          'scholarship_items_waiting_for_a_page', (select count(*) from pipeline.scholarship_ai_queue q where q.state = 'queued' and q.next_try_at <= now() and q.attempts < 3  -- fixed: the AI reader's own try limit
                                                     and not security.scholarship_ai_has_copy_v1(q.id))),
        'live_hold', (select jsonb_object_agg(p.purpose, security.lane_paid_hold_v1(p.purpose)) from (values ('scrape'), ('course_link_search'), ('central_map'), ('map'), ('sch_scrape')) p(purpose)),
        'cost', jsonb_build_object('firecrawl_credits_today', (select coalesce(sum(u.units), 0) from pipeline.coverage_vendor_usage u where u.at >= v_day),
                                   'firecrawl_credits_window', (select coalesce(sum(u.units), 0) from pipeline.coverage_vendor_usage u where u.at > v_since)))
      else jsonb_build_object(
        'eligible', jsonb_build_object(
          'enrich_items_waiting', (select count(*) from pipeline.field_enrich_items e where e.state = 'ai'),
          'scholarship_items_due', (select count(*) from pipeline.scholarship_ai_queue q where q.state = 'queued' and q.next_try_at <= now() and q.attempts < 3),  -- fixed: the AI reader's own try limit
          'fee_pages_queued', (select count(*) from pipeline.fee_reader_queue q where q.state = 'queued'),
          'central_pages_queued', (select count(*) from pipeline.central_ai_queue q where q.state = 'queued'),
          'provider_descriptions_queued', (select count(*) from pipeline.provider_description_reads d where d.state = 'queued')),
        'live_hold', (select jsonb_object_agg(a.use, security.ai_use_refusal_v1(a.use)) from (values ('enrich_fields'), ('fee_ai'), ('scholarship_ai'), ('central_ai'), ('provider_description')) a(use)),
        'cost', jsonb_build_object('ai_usd_today', (select coalesce(round(sum(a.cost_usd), 4), 0) from pipeline.ai_spend_ledger a where a.at >= v_day),
                                   'ai_usd_window', (select coalesce(round(sum(a.cost_usd), 4), 0) from pipeline.ai_spend_ledger a where a.at > v_since))) end);
  end loop;
  -- Layer 4 admission: waiting for a person, decided in the window
  v := v || jsonb_build_object('lane', 'layer4_admission', 'label', 'Layer 4 admission', 'window_since', v_since,
          'eligible', jsonb_build_object('pending', (select count(*) from pipeline.layer4_review_items i where i.status = 'pending')),
          'processed', (select count(*) from pipeline.layer4_review_items i where i.decided_at > v_since),
          'failed', 0, 'held', '{}'::jsonb, 'live_hold', null, 'cost', jsonb_build_object('firecrawl_credits_today', 0, 'ai_usd_today', 0));
  -- the standing gap queue: its checkpoint and its runs
  select * into k from pipeline.field_gap_queue_checkpoint where id = 1;
  select * into v_last from pipeline.field_gap_queue_runs order by run_at desc, id desc limit 1;
  v := v || jsonb_build_object('lane', 'gap_queue', 'label', 'Standing gap queue', 'window_since', v_since,
          'eligible', jsonb_build_object('pass', k.cycle, 'pass_started_at', k.cycle_started_at, 'courses_checked_in_pass', k.cycle_scanned,
                                         'gaps_found_in_pass', k.cycle_found, 'pass_complete', k.cursor_course_id is null,
                                         'waiting_for_page_proof_in_pass', coalesce((select sum((e.value #>> '{}')::int) from jsonb_each(k.cycle_waiting_proof) e), 0),
                                         'waiting_for_page_proof_by_field', coalesce(k.cycle_waiting_proof, '{}'::jsonb)),
          'processed', (select coalesce(sum(g.items), 0) from pipeline.field_gap_queue_runs g where g.run_at > v_since),
          'failed', 0,
          'held', coalesce((select jsonb_object_agg(z.h, z.n) from (select g.hold_reason h, count(*) n from pipeline.field_gap_queue_runs g where g.run_at > v_since and g.outcome = 'held' group by 1) z), '{}'::jsonb),
          'last_run', case when v_last.id is not null then jsonb_build_object('at', v_last.run_at, 'outcome', v_last.outcome, 'hold_reason', v_last.hold_reason,
                                                                               'items', v_last.items, 'scanned', v_last.scanned, 'ms', v_last.ms) end,
          'live_hold', null, 'cost', jsonb_build_object('firecrawl_credits_today', 0, 'ai_usd_today', 0));
  return jsonb_build_object('at', now(), 'lanes', v);
end $$;


ALTER FUNCTION "security"."lane_status_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."lane_task_waiting_v1"("p_mode" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 IQ-00064: a queued or running task (a person's, or an enrichment plan step's) still has work queued for this worker lane
  select case p_mode
    when 'link_search' then exists (select 1 from pipeline.admin_jobs j
                                     cross join lateral jsonb_array_elements_text(coalesce(j.args->'course_ids', '[]'::jsonb)) c(id)
                                     join pipeline.course_link_search s on s.course_id = c.id::uuid and s.state = 'queued'
                                    where j.kind = 'course_page_find' and j.state in ('queued', 'running'))
    else false end
$$;


ALTER FUNCTION "security"."lane_task_waiting_v1"("p_mode" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."lane_task_waiting_v1"("p_mode" "text") IS 'CF-247 IQ-00064: true while a queued or running task (a person''s or an enrichment plan step''s) has work queued for the worker lane (link_search: Find course pages courses still queued); the idle guard does not pause such a lane (tasks.lane_hold_on)';



CREATE OR REPLACE FUNCTION "security"."lane_why_idle_v1"("p_key" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when s.key is null then null
    when coalesce(array_length(s.jobs_paused, 1), 0) > 0 then
      'Paused by the idle guard (' || array_to_string(s.jobs_paused, ', ') || ')'
      || coalesce(' since ' || to_char(f.flagged_at at time zone 'Australia/Melbourne', 'DD Mon HH24:MI'), '')
      || coalesce('; tried again by ' || to_char(f.next_check_at at time zone 'Australia/Melbourne', 'DD Mon HH24:MI'), '') || ', or as soon as work waits'
    when s.state = 'failing' then 'Failing: ' || coalesce(s.reason, 'most tries in the last hour failed')
    when s.state = 'stuck' then 'Stuck: ' || coalesce(s.reason, 'work waiting and nothing finishing')
    when s.state = 'out_of_toolset' then 'A tool is out: ' || array_to_string(s.tools_out, ', ')
    when s.state = 'waiting' then 'Waiting for today''s budget: ' || array_to_string(s.tools_waiting, ', ')
    when s.state = 'nothing_left' then 'Nothing left to try: ' || coalesce(s.reason, '')
    when coalesce(s.pending, 0) > 0 and coalesce(s.done_window, 0) = 0 then
      s.pending || ' waiting and nothing finished in the last window: a gate is holding the lane' || coalesce(' (' || w.retry_label || ')', '')
    when coalesce(s.pending, 0) = 0 and w.upstream_key is not null then
      'Nothing waiting; fed by ' || u.label || ' (' || coalesce(us.pending, 0) || ' waiting there, ' || coalesce(us.state, 'not checked') || ')'
    when coalesce(s.pending, 0) = 0 then 'Nothing waiting'
    else null end
  from pipeline.queue_watch w
  left join pipeline.queue_watch_state s on s.key = w.key
  left join pipeline.queue_watch u on u.key = w.upstream_key
  left join pipeline.queue_watch_state us on us.key = w.upstream_key
  left join lateral (select x.flagged_at, x.next_check_at from pipeline.enrichment_flags x
                      where x.entity = 'job' and x.reason_code = 'idle_paused' and x.state = 'raised' and x.entity_key = any (s.jobs_paused)
                      order by x.flagged_at desc limit 1) f on true
  where w.key = p_key
$$;


ALTER FUNCTION "security"."lane_why_idle_v1"("p_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."lane_why_idle_v1"("p_key" "text") IS 'R1 Q4: one plain line per queue saying why it is idle (paused and when tried again, nothing waiting and who feeds it, gated, failing, nothing left)';



CREATE OR REPLACE FUNCTION "security"."layer1_auto_ingest_tick_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare rec record; v_queued int:=0; v_skipped jsonb:='[]'::jsonb; v_run jsonb;
begin
  for rec in
    select o.source_id, o.variance_decision, o.last_source_hash, o.previous_accepted_hash
      from pipeline.layer1_source_operations o
     where o.auto_ingest and o.active and not o.paused
       and o.last_source_hash is not null and o.last_source_hash is distinct from o.previous_accepted_hash
       and coalesce(o.verification_status,'') in ('passed','warning')
       and (o.next_verification_at is null or o.next_verification_at>now())
       and not exists (select 1 from pipeline.layer1_run_queue q where q.source_id=o.source_id and q.status in ('queued','running'))
       -- do not retry a hash that an automatic run already failed on; a person decides
       and not exists (select 1 from pipeline.layer1_run_queue q where q.source_id=o.source_id and q.source_hash=o.last_source_hash
                         and q.status in ('failed','blocked') and q.requested_by='c0ffee00-0000-4000-8000-000000000150')
  loop
    -- v2.15.246 (Fix 2): when the last two runs started by a change found nothing new, changed or departed, this source's change
    -- check is not reliable (its page differs on every read); it waits for its due date (Platform Admin: due date + file changed)
    if (select count(*) from (select coalesce(p.new_count, 0) + coalesce(p.changed_count, 0) + coalesce(p.departed_count, 0) d
                                from pipeline.layer1_run_plans p join pipeline.layer1_run_queue q on q.id = p.run_id
                               where p.source_id = rec.source_id and q.status = 'completed' order by p.created_at desc limit 2) z where z.d = 0) = 2
       and exists (select 1 from pipeline.layer1_run_queue q join pipeline.layer1_source_operations o on o.source_id = q.source_id
                    where q.source_id = rec.source_id and q.status = 'completed'
                      and q.completed_at > now() - make_interval(days => coalesce(o.ingestion_cadence_days, 30))) then
      v_skipped:=v_skipped||jsonb_build_object('source_id',rec.source_id,'reason','the last two change-started runs found nothing different; waiting for the due date');
      continue;
    end if;
    if rec.variance_decision is distinct from 'pass' then
      v_skipped:=v_skipped||jsonb_build_object('source_id',rec.source_id,'reason','variance '||coalesce(rec.variance_decision,'unknown'));
      continue;
    end if;
    v_run:=security.layer1_queue_system_run_v1(rec.source_id,'apply',0,null,'Automatic ingestion: the register changed and the record count is within the pass band');
    v_queued:=v_queued+1;
  end loop;
  return jsonb_build_object('queued',v_queued,'skipped',v_skipped,'at',now());
end $$;


