CREATE OR REPLACE FUNCTION "security"."layer2_onboarding_snapshot_refresh_v1"("p_with_candidates" integer DEFAULT 150) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue'
    AS $$
declare t0 timestamptz := clock_timestamp(); v_n int;
begin
  create temp table _w on commit drop as
    select b.country_code, c.provider_id, count(*)::int waiting
    from pipeline.au_nz_enrichment_backlog_v1 b join catalogue.courses c on c.id=b.course_id
    where b.field_key='official_course_url' and b.backlog_state='awaiting_source_profile_qualification'
    group by 1,2;
  delete from pipeline.layer2_onboarding_snapshot s where not exists (select 1 from _w where _w.provider_id=s.provider_id);
  insert into pipeline.layer2_onboarding_snapshot(provider_id,country_code,courses_waiting,rank_no,candidates,computed_at)
  select provider_id, country_code, waiting, rn,
         case when rn <= p_with_candidates then security.layer2_catalogue_candidates_v1(provider_id, 5) else '[]'::jsonb end, now()
  from (select _w.*, row_number() over (partition by country_code order by waiting desc, provider_id) rn from _w) x
  on conflict (provider_id) do update set country_code=excluded.country_code, courses_waiting=excluded.courses_waiting,
    rank_no=excluded.rank_no, candidates=excluded.candidates, computed_at=excluded.computed_at;
  get diagnostics v_n = row_count;
  return jsonb_build_object('providers',v_n,'ms',round(extract(epoch from clock_timestamp()-t0)*1000));
end $$;


ALTER FUNCTION "security"."layer2_onboarding_snapshot_refresh_v1"("p_with_candidates" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer2_operational_alerts_read"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'public'
    AS $$
declare v_rank integer; v_result jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;

  with alerts as (
    select
      'critical'::text severity,
      'stuck_run'::text code,
      'Layer 2 managed run is stale'::text title,
      ('Run '||b.id::text||' exceeded its '||coalesce(ep.stale_after_minutes,30)||'-minute heartbeat threshold.')::text message,
      b.profile_id,
      b.id run_id,
      null::uuid provider_id,
      coalesce(b.heartbeat_at,b.updated_at,b.started_at,b.created_at) occurred_at
    from pipeline.layer2_run_batches b
    join pipeline.layer2_execution_policies ep on ep.profile_id=b.profile_id
    where b.status='running'
      and coalesce(b.heartbeat_at,b.updated_at,b.started_at,b.created_at)
          < now()-make_interval(mins=>coalesce(ep.stale_after_minutes,30))

    union all

    select
      'warning','paused_profile','Layer 2 Course profile is paused',
      (coalesce(cp.canonical_name,s.label,p.profile_key)||' is paused; scheduled/discovery execution is blocked until explicitly resumed.'),
      p.id,null::uuid,null::uuid,p.updated_at
    from pipeline.layer2_source_profiles p
    join pipeline.sources s on s.id=p.source_id
    left join catalogue.providers cp on cp.id=s.provider_id
    where p.domain='course_facts' and p.enabled and p.paused

    union all

    select
      'warning','blocked_items','Layer 2 run items are blocked',
      (count(*)::text||' Layer 2 item(s) are blocked and require source or route review.'),
      null::uuid,null::uuid,null::uuid,max(updated_at)
    from pipeline.layer2_run_items
    where status='blocked'
    having count(*)>0

    union all

    select
      'warning','provider_failure_streak','Acquisition provider has repeated failures',
      (ap.display_name||' has '||x.failure_count||' failures/blocks in its latest 10 attempts.'),
      null::uuid,null::uuid,ap.id,x.latest_at
    from pipeline.layer2_acquisition_providers ap
    cross join lateral (
      select count(*) filter(where z.status in ('failed','error','blocked')) failure_count,
             max(z.created_at) latest_at
      from (
        select a.status,a.created_at
        from pipeline.layer2_provider_attempts a
        where a.acquisition_provider_id=ap.id
        order by a.created_at desc
        limit 10
      ) z
    ) x
    where ap.enabled and x.failure_count>=5

    union all

    select
      'warning','provider_quota_reserve','Acquisition provider is near quota reserve',
      (ap.display_name||' has '||q.remaining_units||' unit(s) remaining; configured stop reserve is '||q.stop_units||'.'),
      null::uuid,null::uuid,ap.id,q.latest_at
    from pipeline.layer2_acquisition_providers ap
    cross join lateral (
      select
        nullif(a.metrics#>>'{budget_at_start,remaining_after_planned}','')::numeric remaining_units,
        coalesce(nullif(ap.billing_config->>'stop_at_vendor_units_remaining','')::numeric,0) stop_units,
        a.created_at latest_at
      from pipeline.layer2_provider_attempts a
      where a.acquisition_provider_id=ap.id
        and a.metrics#>>'{budget_at_start,remaining_after_planned}' is not null
      order by a.created_at desc
      limit 1
    ) q
    where ap.enabled
      and q.remaining_units is not null
      and q.remaining_units <= q.stop_units + greatest(50,q.stop_units*0.2)
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'severity',severity,'code',code,'title',title,'message',message,
    'profile_id',profile_id,'run_id',run_id,'provider_id',provider_id,'occurred_at',occurred_at
  ) order by case severity when 'critical' then 1 when 'warning' then 2 else 3 end, occurred_at desc),'[]'::jsonb)
  into v_result
  from alerts;

  return v_result;
end $$;


ALTER FUNCTION "security"."layer2_operational_alerts_read"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer2_provider_budget_status"("p_provider_id" "uuid", "p_planned_units" numeric DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline'
    AS $$
declare
  v_provider pipeline.layer2_acquisition_providers%rowtype;
  v_limit numeric;
  v_stop numeric:=0;
  v_unit numeric:=1;
  v_used numeric:=0;
  v_remaining numeric;
  v_allowed boolean:=true;
begin
  select * into v_provider from pipeline.layer2_acquisition_providers where id=p_provider_id;
  if not found then raise exception 'Layer 2 provider not found' using errcode='22023'; end if;
  begin v_limit:=nullif(v_provider.billing_config->>'monthly_vendor_units_limit','')::numeric; exception when invalid_text_representation then v_limit:=null; end;
  begin v_stop:=coalesce(nullif(v_provider.billing_config->>'stop_at_vendor_units_remaining','')::numeric,0); exception when invalid_text_representation then v_stop:=0; end;
  begin v_unit:=coalesce(nullif(v_provider.request_template->>'fixed_credit_units','')::numeric,1); exception when invalid_text_representation then v_unit:=1; end;
  if v_limit is null then
    return jsonb_build_object('provider_id',p_provider_id,'provider_key',v_provider.provider_key,'bounded',false,'planned_units',greatest(coalesce(p_planned_units,v_unit),0),'allowed',true);
  end if;
  select count(*)::numeric*v_unit into v_used
  from pipeline.layer2_provider_attempts
  where acquisition_provider_id=p_provider_id
    and started_at>=date_trunc('month',now())
    and started_at<date_trunc('month',now())+interval '1 month'; v_used:=v_used+coalesce((select sum(u.units) from pipeline.coverage_vendor_usage u where u.acquisition_provider_id=p_provider_id and u.at>=date_trunc('month',now()) and u.at<date_trunc('month',now())+interval '1 month'),0);
  v_remaining:=greatest(v_limit-v_used,0);
  -- the vendor's own balance (read every 15 minutes) less what the platform used since, when lower
  -- Decision 253: Firecrawl's own balance is the authority when read in the last 2 hours.
  v_remaining:=coalesce((select greatest(o.remaining_units
      - coalesce((select sum(u.units) from pipeline.coverage_vendor_usage u where u.acquisition_provider_id=p_provider_id and u.at>o.observed_at),0)
      - (select count(*)::numeric*v_unit from pipeline.layer2_provider_attempts a where a.acquisition_provider_id=p_provider_id and a.started_at>o.observed_at),0)
    from pipeline.vendor_credit_observations o where o.provider_id=p_provider_id and o.observed_at>now()-interval '2 hours'
    order by o.observed_at desc limit 1), v_remaining);
  v_allowed:=(v_remaining-greatest(coalesce(p_planned_units,v_unit),0))>=v_stop;
  return jsonb_build_object(
    'provider_id',p_provider_id,'provider_key',v_provider.provider_key,'bounded',true,
    'period_start',date_trunc('month',now()),'period_end',date_trunc('month',now())+interval '1 month',
    'limit_units',v_limit,'used_units',v_used,'remaining_units',v_remaining,
    'planned_units',greatest(coalesce(p_planned_units,v_unit),0),'remaining_after_planned',greatest(v_remaining-greatest(coalesce(p_planned_units,v_unit),0),0),
    'stop_at_remaining_units',v_stop,'allowed',v_allowed,
    'no_silent_paid_fallback',coalesce((v_provider.billing_config->>'no_silent_paid_fallback')::boolean,false)
  );
end
$$;


ALTER FUNCTION "security"."layer2_provider_budget_status"("p_provider_id" "uuid", "p_planned_units" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer2_provider_effective_cost_usd"("p_billing" "jsonb", "p_units" numeric DEFAULT 1) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$
declare v_direct numeric;v_plan numeric;v_included numeric;v_per_request numeric;begin
 if p_billing is null or jsonb_typeof(p_billing)<>'object' then return null;end if;
 if coalesce(upper(p_billing->>'currency'),'USD')<>'USD' then return null;end if;
 v_direct:=nullif(p_billing->>'unit_cost_usd','')::numeric;
 if v_direct is not null then return round(v_direct*greatest(coalesce(p_units,1),0),8);end if;
 v_plan:=nullif(p_billing->>'plan_cost_usd','')::numeric;
 v_included:=nullif(p_billing->>'included_units','')::numeric;
 v_per_request:=coalesce(nullif(p_billing->>'units_per_request','')::numeric,1);
 if v_plan is null or v_included is null or v_included<=0 then return null;end if;
 return round((v_plan/v_included)*v_per_request*greatest(coalesce(p_units,1),0),8);
exception when invalid_text_representation then return null;end$$;


ALTER FUNCTION "security"."layer2_provider_effective_cost_usd"("p_billing" "jsonb", "p_units" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer2_provider_has_secret_keys"("p_value" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$
declare k text;v jsonb;begin
 if p_value is null then return false;end if;
 if jsonb_typeof(p_value)='object' then
  for k,v in select key,value from jsonb_each(p_value) loop
   if lower(replace(k,'-','_')) in ('secret','password','token','access_token','refresh_token','bearer_token','api_key','authorization','cookie','client_secret','private_key') then return true;end if;
   if security.layer2_provider_has_secret_keys(v) then return true;end if;
  end loop;
 elsif jsonb_typeof(p_value)='array' then
  for v in select value from jsonb_array_elements(p_value) loop if security.layer2_provider_has_secret_keys(v) then return true;end if;end loop;
 end if;return false;end$$;


ALTER FUNCTION "security"."layer2_provider_has_secret_keys"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer2_provider_sanitise_json"("p_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$
declare k text;v jsonb;result jsonb;begin
 if p_value is null then return null;end if;
 if jsonb_typeof(p_value)='object' then result:='{}'::jsonb;for k,v in select key,value from jsonb_each(p_value) loop if lower(replace(k,'-','_')) not in ('secret','password','token','access_token','refresh_token','bearer_token','api_key','authorization','cookie','client_secret','private_key') then result:=result||jsonb_build_object(k,security.layer2_provider_sanitise_json(v));end if;end loop;return result;
 elsif jsonb_typeof(p_value)='array' then select coalesce(jsonb_agg(security.layer2_provider_sanitise_json(value)),'[]'::jsonb) into result from jsonb_array_elements(p_value);return result;
 end if;return p_value;end$$;


ALTER FUNCTION "security"."layer2_provider_sanitise_json"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer2_run_item_job_lineage_stamp"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare v_lineage jsonb;
begin
  if new.job_id is null then return new; end if;
  v_lineage:=security.layer2_lineage_for_job(new.job_id);
  if v_lineage is null then return new; end if;

  update pipeline.jobs
  set payload=coalesce(payload,'{}'::jsonb)||jsonb_build_object('layer2_lineage',v_lineage)
  where id=new.job_id;

  update pipeline.evidence_artifacts
  set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('layer2_lineage',v_lineage)
  where job_id=new.job_id;

  return new;
end $$;


ALTER FUNCTION "security"."layer2_run_item_job_lineage_stamp"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer2_sanitise_config"("p_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'security'
    AS $_$
declare
  v_type text;
  v_result jsonb;
  v_key text;
  v_item jsonb;
begin
  if p_value is null then return null; end if;
  v_type:=jsonb_typeof(p_value);
  if v_type='object' then
    v_result:='{}'::jsonb;
    for v_key,v_item in select key,value from jsonb_each(p_value) loop
      if lower(v_key) ~ '^(secret|password|token|api[_-]?key|authorization|cookie|client[_-]?secret)$' then
        continue;
      end if;
      v_result:=v_result||jsonb_build_object(v_key,security.layer2_sanitise_config(v_item));
    end loop;
    return v_result;
  elsif v_type='array' then
    select coalesce(jsonb_agg(security.layer2_sanitise_config(value)),'[]'::jsonb) into v_result from jsonb_array_elements(p_value);
    return v_result;
  end if;
  return p_value;
end
$_$;


ALTER FUNCTION "security"."layer2_sanitise_config"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer2_scheduler_discovery_context_v1"("p_preview_token" "uuid", "p_profile_id" "uuid", "p_course_ids" "uuid"[], "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_binding pipeline.scheduler_workflow_async_bindings%rowtype; v_ctx jsonb; v_courses jsonb; v_resolved jsonb; v_requested uuid[]; v_requested_count integer:=0;
begin
 if current_user not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;
 if p_preview_token is null or p_profile_id is null then raise exception 'scheduler preview/profile binding required' using errcode='22023'; end if;
 select coalesce(array_agg(distinct x order by x),'{}'::uuid[]) into v_requested from unnest(coalesce(p_course_ids,'{}'::uuid[])) x; v_requested_count:=cardinality(v_requested);
 if v_requested_count=0 or v_requested_count>1000 then raise exception 'bounded course_ids required' using errcode='22023'; end if;
 select * into v_binding from pipeline.scheduler_workflow_async_bindings b where b.preview_token=p_preview_token and b.profile_id=p_profile_id for update;
 if not found then raise exception 'scheduler async binding not found' using errcode='22023'; end if;
 if v_binding.status<>'active' then raise exception 'scheduler async binding is not active' using errcode='22023'; end if;
 if v_binding.execution_expires_at is null or v_binding.execution_expires_at<=now() then raise exception 'scheduler async execution binding expired' using errcode='22023'; end if;
 if not (v_binding.discovery_course_ids @> v_requested) then raise exception 'requested discovery chunk is outside the exact Preview-bound set' using errcode='22023'; end if;
 select public.layer2_runtime_context(p_profile_id) into v_ctx;
 if v_ctx is null or v_ctx->>'domain'<>'course_facts' then raise exception 'course_facts profile required' using errcode='22023'; end if;
 if nullif(v_ctx->>'version_id','')::uuid<>v_binding.profile_version_id then raise exception 'profile version changed after Preview' using errcode='22023'; end if;
 with requested as (select unnest(v_requested) course_id), resolved as (
  select r.course_id from requested r where exists(select 1 from pipeline.layer2_course_discovery_candidates d where d.course_id=r.course_id and d.source_profile_version_id=v_binding.profile_version_id and d.selected=true and nullif(d.discovered_url,'') is not null and d.created_at>=v_binding.activated_at)
 ), unresolved as (select r.course_id from requested r where not exists(select 1 from resolved x where x.course_id=r.course_id)), bounded as (
  select c.id,c.canonical_title,c.display_title,c.course_code from unresolved u join catalogue.courses c on c.id=u.course_id join pipeline.sources s on s.provider_id=c.provider_id join pipeline.layer2_source_profiles lp on lp.source_id=s.id and lp.id=p_profile_id order by c.canonical_title,c.id limit least(greatest(coalesce(p_limit,50),1),50)
 )
 select coalesce((select jsonb_agg(to_jsonb(b) order by b.canonical_title,b.id) from bounded b),'[]'::jsonb),coalesce((select jsonb_agg(r.course_id order by r.course_id) from resolved r),'[]'::jsonb) into v_courses,v_resolved;
 return jsonb_build_object('runtime',v_ctx,'courses',v_courses,'scheduler_preview_token',p_preview_token,'requested_count',v_requested_count,'resolved_course_ids',v_resolved,'resolved_count',jsonb_array_length(v_resolved),'historical_dispositions_are_retryable',true);
end
$$;


ALTER FUNCTION "security"."layer2_scheduler_discovery_context_v1"("p_preview_token" "uuid", "p_profile_id" "uuid", "p_course_ids" "uuid"[], "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer2_validate_profile_config"("p_config" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$
declare v_errors jsonb:='[]'::jsonb;v_method text:=coalesce(p_config->>'acquisition_method','');
v_target text:=coalesce(p_config->>'target_entity_type','');v_text text:=lower(p_config::text);
begin
 if v_method not in ('website','course_catalogue','course_detail','fee_schedule','intake_calendar','english_requirements','scholarship_catalogue','document','structured_api','json_endpoint','csv_feed','xlsx_feed','sitemap','search_endpoint','other_deterministic') then v_errors:=v_errors||jsonb_build_array('unsupported acquisition_method'); end if;
 if v_target not in ('provider','course','campus','scholarship','provider_asset','provider_outcome','student_flow','course_fact','mixed') then v_errors:=v_errors||jsonb_build_array('unsupported target_entity_type'); end if;
 if coalesce(p_config->>'base_domain','')='' and coalesce(p_config->>'discovery_url','')='' then v_errors:=v_errors||jsonb_build_array('base_domain or discovery_url is required'); end if;
 if coalesce((p_config->>'timeout_seconds')::integer,30)<1 or coalesce((p_config->>'timeout_seconds')::integer,30)>120 then v_errors:=v_errors||jsonb_build_array('timeout_seconds must be between 1 and 120'); end if;
 if coalesce((p_config->>'concurrency')::integer,1)<1 or coalesce((p_config->>'concurrency')::integer,1)>20 then v_errors:=v_errors||jsonb_build_array('concurrency must be between 1 and 20'); end if;
 if coalesce((p_config->>'max_payload_mb')::integer,10)<1 or coalesce((p_config->>'max_payload_mb')::integer,10)>100 then v_errors:=v_errors||jsonb_build_array('max_payload_mb must be between 1 and 100'); end if;
 if v_text ~ '"(secret|password|token|api[_-]?key|authorization|cookie|client[_-]?secret)"[[:space:]]*:' then v_errors:=v_errors||jsonb_build_array('secret-like configuration keys are prohibited; use server-side secret references only'); end if;
 if coalesce(p_config->>'evidence_required','true')<>'true' then v_errors:=v_errors||jsonb_build_array('Layer 2 evidence_required must be true'); end if;
 return jsonb_build_object('valid',jsonb_array_length(v_errors)=0,'errors',v_errors,'validated_at',now());
exception when others then return jsonb_build_object('valid',false,'errors',jsonb_build_array('configuration type validation failed'),'validated_at',now());
end $$;


ALTER FUNCTION "security"."layer2_validate_profile_config"("p_config" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer2_wave_parent_stamp"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'ref', 'security'
    AS $$
declare
  v_terminal uuid;
  v_root uuid;
begin
  v_terminal := null;  -- CF-247 20 Oct 2026 (D11): Layer 2 scale qualification runs retired; a wave request is its own parent

  if v_terminal is not null then
    v_root:=security.layer2_qualification_root(v_terminal);
  end if;

  update pipeline.layer2_scope_wave_requests
  set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
    'parent_run_id',coalesce(v_root,new.id),
    'parent_run_kind',case when v_root is null then 'scope_wave_request' else 'qualification_root' end,
    'qualification_terminal_run_id',v_terminal,
    'scope_wave_request_id',new.id,
    'lineage_version','a26-v1'
  )
  where id=new.id;
  return new;
end $$;


