    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
  select case p_task when 'provider_intake_validation' then 'layer3-intake-route' when 'provider_english_validation' then 'layer3-english-route'
                     when 'provider_current_tuition_validation' then 'layer3-tuition-dispatch' end
$$;


ALTER FUNCTION "security"."layer3_task_job"("p_task" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer3_tier_evidence"("p_task" "text", "p_profile" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
  select jsonb_build_object('cases',count(*),'right',count(*) filter (where h.outcome in ('exact','exact_not_stated')),
           'wrong',count(*) filter (where h.outcome='wrong_admitted'),'cost_per_call_usd',round(avg(h.cost_usd),6),
           'right_pct',case when count(*)>0 then round(100.0*count(*) filter (where h.outcome in ('exact','exact_not_stated'))/count(*),1) end,
           'eligible',count(*)>=30 and count(*) filter (where h.outcome='wrong_admitted')=0 and count(*) filter (where h.outcome in ('exact','exact_not_stated'))::numeric/nullif(count(*),0)>=0.80)
    from pipeline.layer3_holdout_results h join pipeline.layer3_holdout_cases c on c.id=h.case_id
   where h.profile_id=p_profile and c.task_class=p_task
$$;


ALTER FUNCTION "security"."layer3_tier_evidence"("p_task" "text", "p_profile" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer3_tuition_admit_assumed_annual_v1"("p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'catalogue', 'security', 'search', 'ref'
    AS $$
declare r record; v_cand jsonb; v_amount numeric; v_cur text; v_year int; v_key text; v_fee uuid; v_ok int:=0; v_skip int:=0; v_ids uuid[]:='{}';
begin
  if current_user not in ('postgres','service_role') and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required' using errcode='42501'; end if;
  for r in
    select w.id wid, w.entity_id course_id, w.evidence_id, w.interpretation_id, l.id l4id, i.confidence, i.aggregator_response_model model, i.evidence_quotes q,
           coalesce(case when jsonb_typeof(l.layer3_state->'candidate_value')='object' then l.layer3_state->'candidate_value' end, i.candidate_value) cv,
           p.deterministic_validators dv, c.course_code, e.source_id, pg.url
      from pipeline.layer3_work_items w
      join pipeline.layer3_interpretations i on i.id=w.interpretation_id
      join pipeline.layer3_model_profiles p on p.id=i.profile_id
      join pipeline.layer4_review_items l on l.layer3_interpretation_id=i.id and l.status='pending' and l.field_code='provider_current_tuition_validation'
      left join catalogue.courses c on c.id=w.entity_id
      left join pipeline.evidence_artifacts e on e.id=w.evidence_id
      left join pipeline.coverage_course_pages pg on pg.course_id=w.entity_id and pg.evidence_id=w.evidence_id
     where w.task_class='provider_current_tuition_validation' and w.status='layer4_required'
       and coalesce((i.validator_result->>'candidate_bound')::boolean,false)
       and coalesce(i.evidence_quotes::text,'') !~* '(loan|\mcap\M|student contribution|commonwealth supported|\mcsp\M|deposit|application fee|enrolment fee|amenities)'
       and not exists (select 1 from catalogue.course_fees x where x.course_id=w.entity_id and x.fee_type='provider_current_tuition' and x.status='active' and x.audience='international')
       and coalesce(i.evidence_quotes::text,'') !~* '(\mtotal\M|\m(whole|entire|full)\s+(course|program|programme|degree)\M|\mper\s+(semester|trimester|term|unit|subject|credit|study\s+period|session|course)\M|\mcourse\s+fee\M)'
       and ( i.validator_result->'errors' = '["Evidence quote does not explicitly support the resolved tuition basis"]'::jsonb
          or (coalesce(jsonb_array_length(i.validator_result->'errors'),0)=0 and l.layer3_state->>'admission_hold' like 'basis % is not allowed') )
     order by w.updated_at limit greatest(1,least(coalesce(p_limit,100),500))
     for update of w skip locked
  loop
    v_cand:=r.cv; v_amount:=nullif(v_cand->>'amount','')::numeric; v_cur:=upper(nullif(btrim(coalesce(v_cand->>'currency_code',v_cand->>'currency')),''));
    v_year:=nullif(v_cand->>'fee_year','')::int;
    if v_amount is null or v_amount<=0 or v_amount>coalesce(nullif(r.dv->>'amount_max','')::numeric,250000)
       or lower(coalesce(v_cand->>'audience',''))<>'international' or v_cur not in ('AUD','NZD','CAD')
       or coalesce(r.confidence,0)<coalesce(nullif(r.dv->>'review_confidence_min','')::numeric,0.9)
       or r.course_code is null or r.source_id is null then v_skip:=v_skip+1; continue; end if;
    v_key:=lower(upper(btrim(r.course_code))||':international:'||coalesce(v_year::text,'current')||':annual');
    v_fee:=null;
    insert into catalogue.course_fees(course_id,fee_year,audience,fee_type,amount,currency_code,basis,notes,source_id,evidence_id,confidence,campus_id,source_fee_key,status,last_verified_at,source_snapshot_at,updated_at)
    values (r.course_id,v_year,'international','provider_current_tuition',v_amount,v_cur,'annual',
            format('CF-247 Layer 3 admission; period not stated on the page, assumed per year (flagged for confirmation); interpretation %s; model %s',r.interpretation_id,coalesce(r.model,'unknown')),
            r.source_id,r.evidence_id,r.confidence,null,v_key,'active',now(),now(),now())
    on conflict(course_id,source_id,source_fee_key) where source_id is not null and source_fee_key is not null do nothing
    returning id into v_fee;
    if v_fee is null then v_skip:=v_skip+1; continue; end if;   -- a fee is already held for this key: stays with a person
    insert into pipeline.data_flags(entity_type,entity_id,field_code,record_id,flag_code,detail)
    values ('course',r.course_id,'provider_current_tuition',v_fee,'tuition_period_assumed_annual',
            jsonb_build_object('amount',v_amount,'currency',v_cur,'fee_year',v_year,'page_url',r.url,'quotes',r.q,'model',r.model,'interpretation_id',r.interpretation_id))
    on conflict do nothing;
    update pipeline.layer4_review_items set status='superseded', decided_at=now(),
           escalation_reason='Admitted as per year under the Platform Admin rule (29 Sep 2026): the page does not state the period; flagged for an operator to confirm or edit.'
     where id=r.l4id;
    update pipeline.layer3_work_items set status='admitted', completed_at=now(), updated_at=now(), last_error='admitted: period not stated, assumed per year (flagged)' where id=r.wid;
    v_ok:=v_ok+1; v_ids:=v_ids||r.course_id;
  end loop;
  if cardinality(v_ids)>0 then perform search.refresh_course_enrichment_scoped_v1(v_ids,true); end if;
  return jsonb_build_object('admitted_assumed_annual',v_ok,'left_for_review',v_skip);
end $$;


ALTER FUNCTION "security"."layer3_tuition_admit_assumed_annual_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer3_tuition_admit_validated_v1"("p_limit" integer DEFAULT 25) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'catalogue', 'security', 'search', 'ref'
    AS $_$
declare
  v_caller text; r record; v_hold text; v_plain text; v_fee_label text; v_key text; v_min numeric; v_cand jsonb;
  v_amount numeric; v_cur text; v_basis text; v_year int; v_aud text; v_fee uuid;
  v_ex_amount numeric; v_ex_cur text; v_course_ids uuid[] := '{}';
  v_admitted int := 0; v_already int := 0; v_held int := 0; v_refresh jsonb; v_items jsonb := '[]'::jsonb;
begin
  v_caller := coalesce(nullif(current_setting('request.jwt.claim.role',true),''),nullif(current_setting('request.jwt.role',true),''),session_user);
  if v_caller not in ('service_role','postgres') then raise exception 'service_role required' using errcode='42501'; end if;

  for r in
    select w.id wid, w.entity_id course_id, w.evidence_id, w.interpretation_id,
           i.candidate_value cv, i.confidence, i.validator_result vr, i.aggregator_response_model model,
           p.deterministic_validators dv, c.course_code, e.source_id
    from pipeline.layer3_work_items w
    join pipeline.layer3_interpretations i on i.id = w.interpretation_id
    join pipeline.layer3_model_profiles p on p.id = i.profile_id
    left join catalogue.courses c on c.id = w.entity_id
    left join pipeline.evidence_artifacts e on e.id = w.evidence_id
    where w.task_class = 'provider_current_tuition_validation' and w.status = 'validated'
    order by w.completed_at nulls last, w.id
    limit least(greatest(coalesce(p_limit,25),1),100)
    for update of w skip locked
  loop
    v_hold := null; v_cand := r.cv;
    v_min := coalesce(nullif(r.dv->>'review_confidence_min','')::numeric, 0.9);
    v_amount := nullif(v_cand->>'amount','')::numeric;
    v_cur := upper(nullif(btrim(coalesce(v_cand->>'currency_code', v_cand->>'currency')),''));
    v_basis := nullif(btrim(v_cand->>'basis'),'');
    v_year := nullif(v_cand->>'fee_year','')::int;
    v_aud := lower(coalesce(nullif(btrim(v_cand->>'audience'),''),''));
    v_plain := null;
    v_fee_label := case when v_amount is null then 'the fee'
                  else case coalesce(v_cur,'') when 'AUD' then 'A$' when 'NZD' then 'NZ$' else coalesce(v_cur||' ','') end
                       || to_char(v_amount,'FM999,999,999.##') end;
    v_fee_label := rtrim(v_fee_label,'.');

    if v_cand is null or jsonb_typeof(v_cand) <> 'object' then v_hold := 'no candidate value'; v_plain := 'The AI''s answer was empty, so nothing could be recorded. Please check the page and confirm the fee.';
    elsif coalesce((r.vr->>'valid')::boolean,false) is not true or coalesce((r.vr->>'candidate_bound')::boolean,false) is not true then v_hold := 'validator result is not valid and candidate-bound'; v_plain := format('The AI''s answer for %s didn''t pass the automatic checks. Please check the page and confirm the fee.', v_fee_label);
    elsif r.confidence is null or r.confidence < v_min then v_hold := format('confidence %s is below the admission threshold %s', r.confidence, v_min); v_plain := format('The AI was only %s%% confident that %s is the annual international tuition fee (%s%% is needed). Please check the page.', round(coalesce(r.confidence,0)*100), v_fee_label, round(v_min*100));
    elsif v_amount is null or v_amount <= 0 then v_hold := 'amount is not positive'; v_plain := 'The fee amount wasn''t a valid positive number. Please check the page and enter the correct fee.';
    elsif v_aud <> 'international' then v_hold := 'audience is not international'; v_plain := format('%s isn''t clearly a fee for international students. Please confirm who this fee applies to.', v_fee_label);
    elsif r.dv ? 'allowed_currencies' and not (r.dv->'allowed_currencies' ? coalesce(v_cur,'')) then v_hold := format('currency %s is not allowed', v_cur); v_plain := format('The fee on the page (%s) isn''t in Australian or New Zealand dollars, so it can''t be recorded automatically. Please confirm the fee.', v_fee_label);
    elsif r.dv ? 'allowed_basis' and not (r.dv->'allowed_basis' ? coalesce(v_basis,'')) then v_hold := format('basis %s is not allowed', v_basis); v_plain := format('We can''t tell whether %s is charged per year. Please confirm whether it is an annual fee.', v_fee_label);
    elsif r.dv ? 'amount_max' and v_amount > (r.dv->>'amount_max')::numeric then v_hold := 'amount is above the profile ceiling'; v_plain := format('%s is higher than the usual maximum, so it needs a person to check it. Please confirm the fee.', v_fee_label);
    elsif r.course_code is null then v_hold := 'course code unavailable'; v_plain := format('We couldn''t identify the course record for this fee. Please check the course before confirming %s.', v_fee_label);
    elsif r.source_id is null then v_hold := 'Evidence has no source'; v_plain := format('The saved page isn''t linked to a known source, so %s can''t be recorded automatically. Please check the page and confirm the fee.', v_fee_label);
    elsif not exists(select 1 from ref.currencies where code = v_cur) then v_hold := format('currency %s is not seeded', v_cur); v_plain := format('%s isn''t set up as a currency yet. Please review %s manually.', coalesce(v_cur,'This currency'), v_fee_label);
    end if;

    if v_hold is null then
      -- same fee key convention as the Layer 2 writer (svc_coursefacts_apply_record)
      v_key := lower(upper(btrim(r.course_code))||':'||v_aud||':'||coalesce(v_year::text,'current')||':'||coalesce(v_basis,'tuition'));
      v_fee := null;
      insert into catalogue.course_fees(course_id,fee_year,audience,fee_type,amount,currency_code,basis,notes,source_id,evidence_id,confidence,campus_id,source_fee_key,status,last_verified_at,source_snapshot_at,updated_at)
      values (r.course_id,v_year,v_aud,'provider_current_tuition',v_amount,v_cur,v_basis,
              format('CF-247 Layer 3 admission; interpretation %s; model %s', r.interpretation_id, coalesce(r.model,'unknown')),
              r.source_id,r.evidence_id,r.confidence,null,v_key,'active',now(),now(),now())
      on conflict(course_id,source_id,source_fee_key) where source_id is not null and source_fee_key is not null do nothing
      returning id into v_fee;
      if v_fee is null then
        select amount, currency_code into v_ex_amount, v_ex_cur from catalogue.course_fees
        where course_id = r.course_id and source_id = r.source_id and source_fee_key = v_key;
        if v_ex_amount = v_amount and btrim(v_ex_cur) = v_cur then
          update pipeline.layer3_work_items set status='admitted', completed_at=now(), updated_at=now(),
            last_error='admitted: identical fee already present' where id = r.wid;
          v_already := v_already + 1;
          v_items := v_items || jsonb_build_object('work_item_id', r.wid, 'result', 'already_present');
          continue;
        end if;
        v_hold := format('conflicts with existing fee %s %s for the same key', v_ex_amount, v_ex_cur); v_plain := format('A different fee (%s%s) is already recorded for this course from the same source, so %s wasn''t added. Please decide which one is correct.', case btrim(v_ex_cur) when 'AUD' then 'A$' when 'NZD' then 'NZ$' else btrim(v_ex_cur)||' ' end, to_char(v_ex_amount,'FM999,999,999'), v_fee_label);
      end if;
    end if;

    if v_hold is not null then
      -- CF-247: every hold reaches the Layer 4 queue with a plain-English reason;
      -- the technical reason stays in layer3_state and on the work item.
      insert into pipeline.layer4_review_items(entity_type, entity_id, field_code, evidence_id, layer3_interpretation_id,
        layer2_state, layer3_state, status, escalation_reason, change_control_ref)
      values ('course', r.course_id, 'provider_current_tuition_validation', r.evidence_id, r.interpretation_id,
        '{}'::jsonb, jsonb_build_object('admission_hold', v_hold, 'candidate_value', r.cv, 'confidence', r.confidence),
        'pending', coalesce(v_plain, format('The AI''s answer for %s couldn''t be recorded automatically. Please check the page and confirm the fee.', v_fee_label)),
        'CF-CHG-20260915-247');
      update pipeline.layer3_work_items set status='layer4_required', updated_at=now(),
        last_error=left('admission held for human review: '||v_hold,500) where id = r.wid;
      v_held := v_held + 1;
      v_items := v_items || jsonb_build_object('work_item_id', r.wid, 'result', 'held', 'reason', v_hold);
      continue;
    end if;

    update pipeline.layer3_work_items set status='admitted', completed_at=now(), updated_at=now(), last_error=null where id = r.wid;
    v_admitted := v_admitted + 1;
    v_course_ids := v_course_ids || r.course_id;
    v_items := v_items || jsonb_build_object('work_item_id', r.wid, 'result', 'admitted', 'course_fee_id', v_fee, 'amount', v_amount, 'currency', v_cur, 'basis', v_basis);
  end loop;

  if v_admitted > 0 then v_refresh := search.refresh_course_enrichment_scoped_v1(v_course_ids, true); end if;
  return jsonb_build_object('ok', true, 'admitted', v_admitted, 'already_present', v_already, 'held_for_review', v_held,
    'projection_refreshed', v_refresh is not null, 'items', v_items, 'change_control_ref', 'CF-CHG-20260915-247');
end $_$;


ALTER FUNCTION "security"."layer3_tuition_admit_validated_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_ack_headline_v1"("p_choice" "text", "p_n" "jsonb", "p_d" "jsonb", "p_at" timestamp with time zone) RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  -- observation 4 Nov 2026 13:00 §3: the Platform Admin's wording for one action, chosen from what the server did (never before it confirmed
  -- it); the same words on the reply (security.layer4_action_ack_v1) and, after Refresh, on the card (security.layer4_lifecycle_one_v1)
  with z as (select security.l4_time_v1(p_at)->>'hm' v_hm)
  select case
    when p_d ? 'navigated' then 'Opened ' || case p_d->>'navigated' when 'course' then 'the course' when 'builder' then 'the adapter builder' else coalesce(p_d->>'navigated', 'another screen') end
                                || ' — ' || v_hm || ': the item closes when the work there is saved'
    when p_n->>'outcome' in ('refused', 'already_requested') and p_d ? 'repeat_of' and p_d->>'refused' = 'already tried on this stop' then 'Not tried again — the same stop, nothing changed'
    when p_n->>'outcome' = 'already_requested' and p_d->'existing' ? 'event' then 'Already sent — the first decision stands'
    when p_n->>'outcome' = 'already_requested' and p_d ? 'existing' then 'Already queued — existing request retained'
    when p_n->>'outcome' in ('refused', 'already_requested') and (p_d ? 'repeat_of' or coalesce((p_d->>'unchanged')::boolean, false)) then 'Recovery refused — unchanged evidence and reader'
    when p_n->>'outcome' = 'deferred' then 'Recovery deferred — ' || case when coalesce(p_n->>'reason', '') ~* 'daily' then 'daily limit reached' else coalesce(p_n->>'reason', 'a limit is reached') end
    when p_n->>'outcome' = 'queued' and p_choice = 'reread_stored' then 'Recovery queued — ' || v_hm
    when p_n->>'outcome' = 'already_requested' then 'Already requested — ' || coalesce(p_d->>'current_state', 'recorded')
    when p_n->>'outcome' = 'human_input' then 'Human input needed' || coalesce(' — item ' || (p_n->>'intervention_id'), '') || ' — ' || v_hm
    when p_n->>'outcome' = 'queued' then 'Queued — ' || v_hm
    when p_n->>'outcome' = 'completed' then 'Done — ' || v_hm
    when p_n->>'outcome' = 'refused' then 'Refused — ' || coalesce(p_n->>'reason', 'see the reason')
    when p_n->>'outcome' = 'incomplete' then 'Still incomplete — ' || coalesce(p_n->>'reason', 'more input is needed')
    else 'Accepted — ' || v_hm end
    from z
$$;


ALTER FUNCTION "security"."layer4_ack_headline_v1"("p_choice" "text", "p_n" "jsonb", "p_d" "jsonb", "p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_ack_normalise_v1"("p_kind" "text", "p_choice" "text", "p_ok" boolean, "p_result" "jsonb", "p_request" "text", "p_outcome" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  -- the normalised result of one Layer 4 action, from the reply or from its audit row (p_ok null: read from the result):
  -- accepted | refused | deferred | queued | already_requested | completed | incomplete | human_input, with the reason and the permitted alternative
  with x as (select coalesce(p_result, '{}'::jsonb) r, coalesce(p_result->'detail', p_result, '{}'::jsonb) d),
       o as (select case
         when x.r ? 'repeat' or x.d ? 'repeat' then 'already_requested'
         when coalesce(x.r->>'still_waiting', '') = 'true' and p_choice in ('approve', 'approve_except', 'reject', 'keep', 'use', 'enter', 'refuse', 'publish', 'not_international',
              'not_scholarship', 'duplicate', 'archive', 'archive_course', 'closed', 'merged', 'reviewed', 'report_fixed', 'report_not_changed', 'has_page', 'parent', 'no_page') then 'incomplete'
         when x.d ? 'navigated' then 'accepted'
         when (x.d ? 'refused' or x.d ? 'held' or p_ok is false) and coalesce(p_request, x.d->>'refused', x.d->>'held', '') ~* '(daily (cap|limit)|limit reached|back-pressure|AI limits|budget)'
              and coalesce(p_request, x.d->>'refused', '') !~* 'row limit' then 'deferred'
         when p_ok is false and (x.d ? 'refused' or x.d ? 'held') then 'refused'
         when p_ok is null and (x.d ? 'refused' or x.d ? 'held') then 'refused'
         when p_kind = 'intervention' and coalesce(x.r->>'ok', '') = 'false' then 'incomplete'
         when p_ok is false then 'refused'
         when p_kind = 'intervention' and x.r->>'status' = 'resuming' then 'queued'
         when p_kind = 'intervention' and x.r->>'status' in ('not_published', 'returned_technical') then 'completed'
         when p_kind = 'intervention' then 'accepted'
         when nullif(x.r->>'intervention_id', '') is not null or (x.d ? 'raised' and nullif(x.d->>'id', '') is not null) then 'human_input'
         when x.d ? 'request_id' or x.d ? 'job_id' or x.d ? 'enrich_item_id' then 'queued'
         when p_choice = 'wait' or p_outcome->>'class' = 'deferred' then 'accepted'
         when p_outcome->>'class' in ('admitted', 'applied', 'reconciled') then 'completed'
         when p_outcome->>'class' = 'downstream' then 'queued'
         when p_choice in ('rebuild', 'retry', 'website', 'search_again', 'add_page') then 'queued'
         when p_choice in ('approve', 'approve_except', 'reject', 'keep', 'use', 'enter', 'refuse', 'publish', 'not_international', 'not_scholarship', 'duplicate',
                           'archive', 'archive_course', 'closed', 'merged', 'reviewed', 'report_fixed', 'report_not_changed', 'has_page', 'parent', 'no_page', 'cricos_only', 'release') then 'completed'
         else 'accepted' end k from x)
  select jsonb_build_object('outcome', o.k,
    'reason', coalesce(p_request, case when o.k = 'incomplete' and coalesce(x.r->>'still_waiting', '') = 'true' then 'sent, but the item is still waiting: the decision was not applied' end, x.d->>'refused', x.d->>'held', case when o.k = 'already_requested' then 'already requested' end),
    'alternative', case when o.k in ('refused', 'deferred', 'already_requested', 'incomplete') and p_kind <> 'aer_review' and x.d->>'alternative' is not null then x.d->>'alternative'
                        when o.k in ('refused', 'deferred', 'already_requested', 'incomplete') then
                     case when p_kind = 'aer_review' then coalesce(x.d->>'alternative', 'Open human input with the dropped requirements, or Request official evidence')
                          when p_kind = 'intervention' then 'Correct the input as asked, or Return to technical recovery'
                          else 'Choose another permitted action, or leave the item pending with its reason' end end,
    'intervention_id', coalesce(x.r->'intervention_id', case when x.d ? 'raised' then x.d->'id' end))
    from x, o
$$;


ALTER FUNCTION "security"."layer4_ack_normalise_v1"("p_kind" "text", "p_choice" "text", "p_ok" boolean, "p_result" "jsonb", "p_request" "text", "p_outcome" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_action_ack_v1"("p_kind" "text", "p_ref" "text", "p_reply" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n jsonb; v_at timestamptz; v_lc jsonb; v_d jsonb := coalesce(p_reply->'result'->'detail', p_reply->'result', '{}'::jsonb); v_hm text; v_head text;
begin
  v_n := security.layer4_ack_normalise_v1(p_kind, p_reply->>'choice', (p_reply->>'ok')::boolean, p_reply->'result', p_reply->>'request', p_reply->'outcome');
  select x.created_at into v_at from pipeline.admin_control_events x where x.id = nullif(p_reply->>'event_id', '')::bigint;
  v_lc := security.layer4_lifecycle_one_v1(p_kind, p_ref, false);
  v_hm := security.l4_time_v1(coalesce(v_at, now()))->>'hm';
  v_head := security.layer4_ack_headline_v1(p_reply->>'choice', v_n, v_d, coalesce(v_at, now()));
  return p_reply || jsonb_build_object('ack', v_n || jsonb_build_object('headline', v_head, 'ref', case when p_reply ? 'event_id' then 'audit #' || (p_reply->>'event_id') end,
    'at', security.l4_time_v1(coalesce(v_at, now())), 'returns', p_reply->>'returns',
    'next', coalesce(v_lc->'next'->>'text', case when v_lc->>'open' = 'false' then 'nothing: the item is ' || lower(v_lc->>'stage_label') end),
    'stage', v_lc->>'stage', 'stage_label', v_lc->>'stage_label'));
end $$;


ALTER FUNCTION "security"."layer4_action_ack_v1"("p_kind" "text", "p_ref" "text", "p_reply" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_adapter_field_v1"("p_field_code" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case p_field_code when 'course_intake' then 'intakes' when 'course_english' then 'english' when 'provider_current_tuition_validation' then 'fee' end
$$;


ALTER FUNCTION "security"."layer4_adapter_field_v1"("p_field_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_admission_check_v1"("p_decision" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare d pipeline.layer4_decisions; i pipeline.layer4_review_items; v_key text; v_link record; v_doc record; v_n int; v_m int; v_txt text;
        v_lock boolean; v_life text; v_young boolean;
begin
  select * into d from pipeline.layer4_decisions where id = p_decision;
  select * into i from pipeline.layer4_review_items where id = d.review_item_id;
  if d.id is null or i.id is null or d.action not in ('approve', 'edit_and_approve') then
    return jsonb_build_object('result', 'not_applicable', 'reason', 'not an approval');
  end if;
  v_young := d.created_at > now() - make_interval(mins => security.pipeline_num_v1('layer4.verify_wait_minutes', 90)::int);
  -- a later approval of the same question replaced this one
  if exists (select 1 from pipeline.layer4_decisions x join pipeline.layer4_review_items y on y.id = x.review_item_id
              where y.entity_id = i.entity_id and y.field_code = i.field_code and x.action in ('approve', 'edit_and_approve') and x.created_at > d.created_at
                and security.layer4_scope_key_v1(y.field_code, y.layer2_state, y.proposed_value) = security.layer4_scope_key_v1(i.field_code, i.layer2_state, i.proposed_value)) then
    return jsonb_build_object('result', 'superseded_later', 'reason', 'a later approval of the same question');
  end if;
  if i.entity_type = 'course' then
    select c.lifecycle_status into v_life from catalogue.courses c where c.id = i.entity_id;
    if v_life is distinct from 'active' then return jsonb_build_object('result', 'not_applicable', 'reason', 'course ' || coalesce(v_life, 'missing')); end if;
    select s.official_course_url, s.description, s.has_provider_current_tuition, s.generated_at into v_doc from search.course_documents s where s.course_id = i.entity_id;
  end if;
  if i.field_code = 'official_course_url' then
    v_key := security.layer4_url_key_v1(coalesce(case jsonb_typeof(d.final_value) when 'string' then d.final_value #>> '{}' when 'object' then coalesce(d.final_value->>'url', d.final_value->>'course_url') end,
                                                 case jsonb_typeof(i.proposed_value) when 'string' then i.proposed_value #>> '{}' when 'object' then coalesce(i.proposed_value->>'url', i.proposed_value->>'course_url') end));
    select l.id, l.status, l.is_primary, l.created_at, l.updated_at into v_link from catalogue.course_links l
     where l.course_id = i.entity_id and l.link_type = 'official_course' and security.layer4_url_key_v1(l.url) = v_key order by (l.status = 'active') desc, l.updated_at desc limit 1;
    v_lock := exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = i.entity_id and l.field in ('official_url', 'course_url'));
    if v_link.id is null or v_link.status <> 'active' then
      return jsonb_build_object('result', 'not_admitted', 'admitted', false,
        'reason', case when v_lock then 'manual_lock_kept' when v_link.id is null then 'link_missing' else 'link_' || v_link.status end,
        'detail', jsonb_build_object('url_key', v_key, 'manual_lock', v_lock, 'link_status', v_link.status, 'shown_url', v_doc.official_course_url));
    end if;
    if v_doc.generated_at is null then
      return jsonb_build_object('result', case when v_young then 'waiting' else 'admitted_not_published' end, 'admitted', true, 'published', false, 'reason', 'no_projection_row',
                                'lag_seconds', round(extract(epoch from v_link.updated_at - d.created_at)));
    end if;
    if security.layer4_url_key_v1(v_doc.official_course_url) is distinct from v_key then
      return jsonb_build_object('result', case when v_young then 'waiting' else 'admitted_not_published' end, 'admitted', true, 'published', false,
        'reason', case when v_lock then 'manual_lock_shown' else 'projection_shows_another_page' end, 'lag_seconds', round(extract(epoch from v_link.updated_at - d.created_at)),
        'detail', jsonb_build_object('shown_url', v_doc.official_course_url, 'primary', v_link.is_primary, 'projection_at', v_doc.generated_at));
    end if;
    return jsonb_build_object('result', 'admitted_published', 'admitted', true, 'published', true, 'lag_seconds', round(extract(epoch from v_link.updated_at - d.created_at)),
                              'detail', jsonb_build_object('primary', v_link.is_primary));
  elsif i.field_code = 'provider_current_tuition_validation' then
    -- security.layer4_tuition_apply_impl names the item in the fee's notes (provider_current_tuition goes through the scalar path: not checked here)
    select count(*) filter (where f.status = 'active'), count(*) into v_n, v_m from catalogue.course_fees f
     where f.course_id = i.entity_id and position(i.id::text in coalesce(f.notes, '')) > 0;
    if v_n = 0 then
      return jsonb_build_object('result', case when v_m > 0 then 'superseded_later' else 'not_admitted' end, 'admitted', false,
                                'reason', case when v_m > 0 then 'fee_replaced' else 'fee_missing' end);
    end if;
    if not coalesce(v_doc.has_provider_current_tuition, false) then
      return jsonb_build_object('result', case when v_young then 'waiting' else 'admitted_not_published' end, 'admitted', true, 'published', false, 'reason', 'projection_has_no_fee');
    end if;
    return jsonb_build_object('result', 'admitted_published', 'admitted', true, 'published', true);
  elsif i.field_code = 'course_entry_first_read' then
    -- rows later replaced (superseded) or withdrawn by a later decision (inactive, not quarantined: E14 withdrew 105 rows on 2 Nov 2026)
    select count(*) filter (where x.status = 'active'),
           count(*) filter (where x.status = 'superseded' or (x.status = 'inactive' and coalesce(x.status_reason, '') not like 'quarantined%' and coalesce(x.status_reason, '') not like 'excluded by the reviewer%'))
      into v_n, v_m from catalogue.course_entry_requirements x
     where x.course_id = i.entity_id and x.provenance->>'review_item_id' = i.id::text;
    return case when v_n > 0 then jsonb_build_object('result', 'admitted', 'admitted', true, 'reason', 'not projected (read by the entry resolver)', 'detail', jsonb_build_object('active_rows', v_n))
                when v_m > 0 then jsonb_build_object('result', 'superseded_later', 'admitted', false, 'reason', 'rows_replaced_or_withdrawn', 'detail', jsonb_build_object('rows', v_m))
                else jsonb_build_object('result', 'not_admitted', 'admitted', false, 'reason', 'no_active_row') end;
  elsif i.field_code in ('entry_matrix_first_run', 'entry_matrix_change') then
    select count(*) filter (where m.status = 'active'),
           count(*) filter (where m.status = 'superseded' or (m.status = 'inactive' and coalesce(m.status_reason, '') not like 'quarantined%' and coalesce(m.status_reason, '') not like 'excluded by the reviewer%'))
      into v_n, v_m from catalogue.provider_entry_matrix m
     where m.provider_id = i.entity_id and m.run_id = nullif(i.proposed_value->>'run_id', '')::uuid;
    return case when v_n > 0 then jsonb_build_object('result', 'admitted', 'admitted', true, 'reason', 'not projected (read by the entry resolver)', 'detail', jsonb_build_object('active_rows', v_n))
                when v_m > 0 then jsonb_build_object('result', 'superseded_later', 'admitted', false, 'reason', 'rows_replaced_or_withdrawn')
                else jsonb_build_object('result', 'not_admitted', 'admitted', false, 'reason', 'no_active_row') end;
  elsif i.field_code = 'course_description_first_read' then
    select nullif(btrim(c.description), '') into v_txt from catalogue.courses c where c.id = i.entity_id;
    if v_txt is distinct from nullif(btrim(i.proposed_value->>'description'), '') then
      return jsonb_build_object('result', 'not_admitted', 'admitted', false, 'reason', case when v_txt is null then 'description_missing' else 'description_differs' end);
    end if;
    if nullif(btrim(v_doc.description), '') is distinct from v_txt then
      return jsonb_build_object('result', case when v_young then 'waiting' else 'admitted_not_published' end, 'admitted', true, 'published', false, 'reason', 'projection_shows_other_text');
    end if;
    return jsonb_build_object('result', 'admitted_published', 'admitted', true, 'published', true);
  elsif i.field_code = 'provider_description' then
    select nullif(btrim(p.description), '') into v_txt from catalogue.providers p where p.id = i.entity_id;
    return case when v_txt is not null and exists (select 1 from pipeline.provider_description_reads r where r.review_item_id = i.id and r.state = 'admitted')
                then jsonb_build_object('result', 'admitted', 'admitted', true, 'reason', 'read by the provider endpoint directly')
                else jsonb_build_object('result', 'not_admitted', 'admitted', false, 'reason', 'description_not_admitted') end;
  elsif i.field_code in ('no_page_first_run', 'conjoint_rule_first_run') then
    return case when exists (select 1 from pipeline.no_page_trust t where t.review_item_id = i.id and t.decided_at is not null)
                then jsonb_build_object('result', 'admitted', 'admitted', true, 'reason', 'provider rule recorded')
                else jsonb_build_object('result', 'not_admitted', 'admitted', false, 'reason', 'rule_not_recorded') end;
  end if;
  return jsonb_build_object('result', 'not_checked', 'reason', 'no admission check for ' || i.field_code);
end $$;


ALTER FUNCTION "security"."layer4_admission_check_v1"("p_decision" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_admission_record_v1"("p_decision" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb := security.layer4_admission_check_v1(p_decision); d record;
begin
  select x.id, x.created_at, r.id rid, r.field_code, r.entity_type, r.entity_id into d
    from pipeline.layer4_decisions x join pipeline.layer4_review_items r on r.id = x.review_item_id where x.id = p_decision;
  if d.id is null then return null; end if;
  insert into pipeline.layer4_admission_checks as c(decision_id, review_item_id, field_code, entity_type, entity_id, decided_at, result, reason, admitted, published, lag_seconds, detail)
  values (d.id, d.rid, d.field_code, d.entity_type, d.entity_id, d.created_at, v->>'result', v->>'reason', (v->>'admitted')::boolean, (v->>'published')::boolean,
          (v->>'lag_seconds')::numeric, coalesce(v->'detail', '{}'::jsonb))
  on conflict (decision_id) do update set result = excluded.result, reason = excluded.reason, admitted = excluded.admitted, published = excluded.published,
     lag_seconds = coalesce(excluded.lag_seconds, c.lag_seconds), detail = excluded.detail, checked_at = now(), checks = c.checks + 1;
  return v->>'result';
end $$;


ALTER FUNCTION "security"."layer4_admission_record_v1"("p_decision" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_aer_owner_claim_v1"("p_provider" "uuid", "p_owner" "text", "p_basis" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_other text; v_n int := 0; f text;
begin
  if p_owner not in ('claude', 'chatgpt', 'engineering') then raise exception 'owner must be claude, chatgpt or engineering' using errcode = '22023'; end if;
  if length(btrim(coalesce(p_basis, ''))) < 5 then raise exception 'give the basis of the claim'; end if;
  select string_agg(distinct o.owner, ', ') into v_other from pipeline.layer4_review_owners o
   where o.provider_id = p_provider and o.closed_at is null and o.owner <> p_owner and o.field_code in ('course_entry_first_read', 'entry_matrix_first_run', 'entry_matrix_change');
  if v_other is not null then return jsonb_build_object('claimed', false, 'reason', 'held by ' || v_other); end if;
  foreach f in array array['course_entry_first_read', 'entry_matrix_first_run', 'entry_matrix_change'] loop
    insert into pipeline.layer4_review_owners(provider_id, field_code, owner, scope, basis, since, note)
    select p_provider, f, p_owner, 'AER review queue', btrim(p_basis), now(), 'direction 4 Nov 2026 10:00 §3'
     where not exists (select 1 from pipeline.layer4_review_owners o where o.provider_id = p_provider and o.field_code = f and o.owner = p_owner and o.closed_at is null);
    get diagnostics v_n = row_count;
  end loop;
  return jsonb_build_object('claimed', true, 'owner', p_owner, 'provider_id', p_provider);
end $$;


ALTER FUNCTION "security"."layer4_aer_owner_claim_v1"("p_provider" "uuid", "p_owner" "text", "p_basis" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_aer_queue_v1"("p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with s as (select * from security.aer_settlement_v1(nullif(p_args->>'provider_id', '')::uuid)),
       r as (select * from s where s.settlement = 'ready'),
       f as (select x::uuid pid, n from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'coverage.aer_priority_providers'), '[]'::jsonb)) with ordinality z(x, n)),
       u as (select r.provider_id pid, count(*) ready, count(*) filter (where r.route <> 'review') except_n, min(r.created_at) oldest from r group by 1),
       own as (select o.provider_id, jsonb_agg(jsonb_build_object('owner', o.owner, 'field_code', o.field_code, 'scope', o.scope)) owners
                 from pipeline.layer4_review_owners o where o.closed_at is null and o.field_code in ('course_entry_first_read', 'entry_matrix_first_run', 'entry_matrix_change') group by 1),
       pg as (select r.* from r where p_args ? 'provider_id' order by r.created_at, r.item_id
               limit security.pipeline_num_v1('layer4.inbox_page_size', 25)::int offset greatest(coalesce((p_args->>'offset')::int, 0), 0))
  select jsonb_build_object(
    'ready', (select count(*) from r), 'by_settlement', (select jsonb_object_agg(z.settlement, z.n) from (select s.settlement, count(*) n from s group by 1) z),
    'universities', coalesce((select jsonb_agg(jsonb_build_object('provider_id', u.pid, 'name', coalesce(p.display_name, p.canonical_name), 'ready', u.ready,
                      'approve_except', u.except_n, 'oldest', u.oldest, 'followed', f.n is not null, 'owners', coalesce(own.owners, '[]'::jsonb))
                      order by f.n nulls last, u.ready desc, coalesce(p.display_name, p.canonical_name))
                 from u left join f on f.pid = u.pid left join own on own.provider_id = u.pid left join catalogue.providers p on p.id = u.pid), '[]'::jsonb),
    'items', case when p_args ? 'provider_id' then coalesce((select jsonb_agg(jsonb_build_object('kind', 'aer_review', 'ref', pg.item_id::text, 'provider_id', pg.provider_id,
                      'provider', coalesce(pv.display_name, pv.canonical_name), 'subject', coalesce(c.display_title, c.canonical_title, 'Entry requirements'),
                      'why', coalesce(nullif(i.escalation_reason, ''), 'Needs a decision'), 'created_at', pg.created_at, 'route', pg.route, 'ready', true,
                      'detail', jsonb_strip_nulls(jsonb_build_object('field_code', pg.field_code, 'course_id', c.id, 'course_code', c.course_code, 'code_label', 'CRICOS',
                                                 'evidence_id', i.evidence_id, 'captured_at', ev.captured_at, 'source_url', ev.source_url)))
                      order by pg.created_at, pg.item_id)
                 from pg join pipeline.layer4_review_items i on i.id = pg.item_id
                 left join catalogue.courses c on i.entity_type = 'course' and c.id = i.entity_id
                 left join catalogue.providers pv on pv.id = pg.provider_id
                 left join pipeline.evidence_artifacts ev on ev.id = i.evidence_id), '[]'::jsonb) end,
    'offset', greatest(coalesce((p_args->>'offset')::int, 0), 0), 'limit', security.pipeline_num_v1('layer4.inbox_page_size', 25)::int)
$$;


ALTER FUNCTION "security"."layer4_aer_queue_v1"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_aer_recovery_decide_v1"("p_ref" "text", "p_choice" "text", "p_value" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare st jsonb; v_reason text := btrim(coalesce(p_reason, '')); a pipeline.layer4_aer_recovery_actions; v_res jsonb; v_iv jsonb; v_next text; v_ws text;
        v_ok boolean := true; v_req text; v_ev bigint; v_id bigint; v_wi jsonb; v_class text; v_ent text; v_ai boolean; v_rep jsonb; v_now text; v_outcome text;
        v_osup pipeline.aer_read_supersessions; v_oiv pipeline.layer4_interventions; v_ofe pipeline.field_enrich_items;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode = '42501'; end if;
  if security.current_role_rank() < 4 then raise exception 'your role cannot take this action (it needs rank 4)' using errcode = '42501'; end if;
  if p_choice not in ('reread_stored', 'request_evidence', 'ai_analyse', 'open_intervention') then raise exception 'unknown recovery choice %', p_choice using errcode = '22023'; end if;
  if length(v_reason) < 5 then raise exception 'give a reason (kept with the recovery)'; end if;
  st := security.layer4_aer_recovery_state_v1(p_ref::uuid);
  if st is null or not exists (select 1 from pipeline.layer4_review_items r where r.id = p_ref::uuid and r.status = 'pending') then
    raise exception 'this item is no longer waiting (someone may have decided it)'; end if;
  v_rep := case when p_choice = 'reread_stored' and st->>'field_code' = 'course_entry_first_read' then security.layer4_reread_repeat_v1(p_ref::uuid) end;
  select * into a from pipeline.layer4_aer_recovery_actions x where x.review_item_id = p_ref::uuid and x.choice = p_choice and x.problem_fingerprint = st->>'problem_fingerprint';
  -- observation 13:00 §6: a repeated click while the operation is queued or running returns that operation, whoever asked for it (a reviewer,
  -- the scheduled reading or human input), and starts nothing
  if p_choice = 'reread_stored' then
    select * into v_osup from pipeline.aer_read_supersessions x where x.old_item_id = p_ref::uuid and x.state = 'requested' order by x.requested_at desc limit 1;
    if v_osup.id is null then
      select * into v_ofe from pipeline.field_enrich_items f where f.course_id = (st->>'course_id')::uuid and f.field = 'entry_requirements' and f.state in ('queued', 'waiting', 'ai', 'leased')
       order by f.id desc limit 1;
    else
      select * into v_ofe from pipeline.field_enrich_items f where f.id = v_osup.enrich_item_id;
    end if;
  else
    select * into v_oiv from pipeline.layer4_interventions i where i.lane = 'aer_item' and i.status in ('ai_pending', 'awaiting_input', 'resuming')
       and (i.entity = p_ref or i.entity = (st->>'provider_id') || '|case:' || (st->>'case_key')) order by i.id desc limit 1;
  end if;
  if v_osup.id is not null or v_ofe.id is not null or v_oiv.id is not null then
    v_outcome := 'already_requested'; v_ok := false;
    v_res := jsonb_build_object('repeat', true, 'existing', jsonb_strip_nulls(jsonb_build_object('request', v_osup.id, 'enrich_item', v_ofe.id, 'job', coalesce(v_osup.job_id, v_ofe.job_id),
                                  'intervention_id', v_oiv.id, 'asked_at', coalesce(v_osup.requested_at, v_ofe.created_at, v_oiv.created_at),
                                  'state', coalesce(case when v_ofe.state in ('leased', 'ai') then 'running' when v_ofe.id is not null then 'queued' end, v_oiv.status))),
                                'recorded', a.id, 'intervention_id', v_oiv.id);
    v_req := 'Already queued — existing request retained: ' ||
             case when v_oiv.id is not null then 'Human input needed item ' || v_oiv.id || ' (' || replace(v_oiv.status, '_', ' ') || ', opened ' || (security.l4_time_v1(v_oiv.created_at)->>'text') || ')'
                  else coalesce('request ' || left(v_osup.id::text, 8) || ', ', '') || 'enrich item ' || v_ofe.id || ' (' ||
                       case when v_ofe.state in ('leased', 'ai') then 'running' else 'queued' end || ', asked ' || (security.l4_time_v1(coalesce(v_osup.requested_at, v_ofe.created_at))->>'text') || ')' end || '.';
  elsif a.id is not null then
    -- already requested: the original action and where it stands now
    v_now := case when p_choice = 'reread_stored' then
                    (select case s.state when 'requested' then 'waiting for the reader'
                                         when 'superseded' then 'complete: a new read replaced this one'
                                         else 'the reader refused it at ' || coalesce(security.l4_time_v1(s.closed_at)->>'text', '?') || ': ' || coalesce(s.outcome, 'refused') end
                       from pipeline.aer_read_supersessions s where s.id::text = a.result->>'request_id')
                  else (select 'Human input needed item ' || i.id || ' is ' || replace(i.status, '_', ' ') from pipeline.layer4_interventions i where i.id = a.intervention_id) end;
    v_outcome := 'already_requested';
    v_res := jsonb_build_object('repeat', true, 'recorded', a.id, 'recorded_at', a.at, 'next_operation', a.next_operation, 'intervention_id', a.intervention_id,
                                'current_state', v_now, 'alternative', v_rep->>'alternative', 'unchanged', coalesce((v_rep->>'repeat')::boolean, false));
    v_ok := false;
    v_req := 'Already requested: recovery action ' || a.id || ' at ' || (security.l4_time_v1(a.at)->>'text') || '. Now: ' || coalesce(v_now, a.next_operation, 'recorded') || '.'
             || case when coalesce((v_rep->>'repeat')::boolean, false) then ' Reading the same stored copy again would be refused the same way. Instead: ' || (v_rep->>'alternative') || '.' else '' end;
  else
    v_wi := jsonb_build_object('lane', 'aer_technical', 'entity', p_ref, 'kind', 'l4_item');
    if coalesce((v_rep->>'repeat')::boolean, false) then
      -- a deterministic repeat: nothing is read, the refusal is recorded with its reason and the permitted alternative
      v_ok := false; v_outcome := 'refused';
      v_req := 'Not read again: ' || (v_rep->>'why') || '. Instead: ' || (v_rep->>'alternative') || '.';
      v_res := jsonb_build_object('refused', 'deterministic repeat of corrected read ' || (v_rep->>'request'), 'repeat_of', v_rep->>'request', 'alternative', v_rep->>'alternative');
    elsif p_choice = 'reread_stored' then
      begin
        if st->>'field_code' = 'course_entry_first_read' then
          v_res := security.course_entry_correction_v1(p_ref::uuid, auth.uid(), 'Layer 4 recovery: ' || v_reason);
        else
          v_res := security.aer_reread_v1((st->>'source_id')::uuid, 'Layer 4 recovery: ' || v_reason, auth.uid());
        end if;
        v_next := 'the existing reader reads the stored page again; the new read replaces this one only through the same gates';
      exception when others then
        v_ok := false; v_req := sqlerrm || '. Choose Request official evidence or Open human input instead.'; v_res := jsonb_build_object('refused', sqlerrm);
      end;
    else
      v_ai := p_choice = 'ai_analyse';
      if v_ai and not (security.pipeline_num_v1('har.ai_escalate_on', 0) >= 1 and security.pipeline_num_v1('ops.ai_diagnosis_on', 0) >= 1 and security.har_text_v1('har.ai_escalation_model', '') <> '') then
        v_ok := false; v_req := 'The stronger-model step is switched off (har.ai_escalate_on, ops.ai_diagnosis_on, har.ai_escalation_model). Choose Open human input instead.';
        v_res := jsonb_build_object('held', 'AI step off');
      else
        v_class := case p_choice when 'request_evidence' then 'aer_read_evidence' else 'aer_read_rows_missing' end;
        v_ent := case p_choice when 'request_evidence' then (st->>'provider_id') || '|case:' || (st->>'case_key') else p_ref end;
        v_iv := security.layer4_intervention_raise_v1(jsonb_build_object('class', v_class, 'entity', v_ent, 'provider_id', st->>'provider_id', 'course_id', st->>'course_id',
                  'subject', coalesce((select coalesce(c.display_title, c.canonical_title) from catalogue.courses c where c.id = (st->>'course_id')::uuid), 'Entry requirements') || ': ' ||
                             case v_class when 'aer_read_evidence' then 'official evidence needed' else 'dropped requirements to enter' end,
                  'attempts', 99, 'signature', case v_class when 'aer_read_evidence' then st->>'case_key' else st->>'problem_fingerprint' end,
                  'issue', jsonb_build_object('summary', 'The read is held: ' || (st->>'case_label'), 'attempted', jsonb_build_array('AI course read', 'completeness gate'),
                                              'why_stopped', st->'reasons'->>0, 'impact', 'the course''s accurate rows cannot be admitted while the read is incomplete'),
                  'evidence', jsonb_build_object('stored_copies', case when st->>'evidence_id' is not null then jsonb_build_array(st->>'evidence_id') else '[]'::jsonb end,
                                                 'quotes', st->'missing_quotes', 'attempts', jsonb_build_array(jsonb_build_object('corrected_read', st->'corrected_read')),
                                                 'conflicts', st->'reasons'),
                  'resume_target', jsonb_build_object('operation', 'corrected read of the course by the existing reader (D-R2)', 'work_item', v_wi),
                  'review_item', p_ref));
        v_id := (v_iv->>'id')::bigint;
        if v_id is null then v_ok := false; v_req := 'No Human input needed item could be opened: ' || coalesce(v_iv->>'reason', 'refused'); end if;
        -- ai_analyse sends the new item to the stronger model first; open_intervention and request_evidence go straight to a person
        update pipeline.layer4_interventions set status = case when v_ai then 'ai_pending' else 'awaiting_input' end,
               resume_target = resume_target || jsonb_build_object('review_item', p_ref) where id = v_id and status in ('ai_pending', 'awaiting_input');
        v_next := case when v_id is null then null when v_ai then 'the stronger model analyses the failure once, then the item waits for a person'
                       else 'Human input needed item ' || v_id || ' waits for a person; the course is read again by itself when the input checks out' end;
        v_res := v_iv;
      end if;
    end if;
    select w.stage into v_ws from pipeline.work_items w where w.lane = 'aer_technical' and w.entity = p_ref and w.work_kind = 'l4_item';
    insert into pipeline.layer4_aer_recovery_actions(review_item_id, case_key, choice, problem_fingerprint, reason, affected_rows, missing_quotes, previous_evidence, reviewer,
                work_item_status, next_operation, intervention_id, result)
    select p_ref::uuid, st->>'case_key', p_choice, case when v_ok then st->>'problem_fingerprint' else st->>'problem_fingerprint' || ':refused:' || md5(coalesce(v_req, '')) || ':' || now() end,
           v_reason, st->'waiting_rows', st->'missing_quotes',
           jsonb_build_object('evidence_id', st->>'evidence_id', 'corrected_read', st->'corrected_read', 'reasons', st->'reasons'), auth.uid(), coalesce(v_ws, 'none'),
           coalesce(v_next, v_req), v_id, coalesce(v_res, '{}'::jsonb)
    returning * into a;
  end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('layer4', 'inbox_decide', 'aer_review:' || p_ref, jsonb_build_object('kind', 'aer_review', 'ref', p_ref, 'choice', p_choice, 'value', p_value, 'reason', v_reason,
          'provider_id', st->>'provider_id', 'recovery_action', a.id, 'result', v_res), auth.uid()) returning id into v_ev;
  return jsonb_build_object('ok', v_ok, 'kind', 'aer_review', 'choice', p_choice, 'ref', p_ref, 'event_id', v_ev, 'request', v_req,
    'returns', case when v_ok then v_next end, 'result', jsonb_build_object('recovery_action', a.id, 'next_operation', a.next_operation, 'work_item_status', a.work_item_status,
                                                                          'intervention_id', a.intervention_id, 'detail', v_res));
end $$;


ALTER FUNCTION "security"."layer4_aer_recovery_decide_v1"("p_ref" "text", "p_choice" "text", "p_value" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_aer_recovery_detail_v1"("p_ref" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare st jsonb := security.layer4_aer_recovery_state_v1(p_ref::uuid); v_last record; v_iv pipeline.layer4_interventions; v_rec text; v_case jsonb; v_ai boolean;
        v_busy text; v_rep jsonb; v_repeat boolean;
begin
  if st is null then return jsonb_build_object('sections', '[]'::jsonb, 'actions', '[]'::jsonb); end if;
  select * into v_last from pipeline.layer4_aer_recovery_actions a where a.review_item_id = p_ref::uuid order by a.id desc limit 1;
  select * into v_iv from pipeline.layer4_interventions i where i.lane = 'aer_item' and i.status in ('ai_pending', 'awaiting_input', 'resuming')
     and (i.entity = p_ref or i.entity = (st->>'provider_id') || '|case:' || (st->>'case_key')) order by i.id desc limit 1;
  v_ai := security.pipeline_num_v1('har.ai_escalate_on', 0) >= 1 and security.pipeline_num_v1('ops.ai_diagnosis_on', 0) >= 1 and security.har_text_v1('har.ai_escalation_model', '') <> '';
  v_busy := case when st->'corrected_read'->>'state' = 'requested' then 'a corrected read of this item is already asked for'
                 when exists (select 1 from pipeline.field_enrich_items f where f.course_id = (st->>'course_id')::uuid and f.field = 'entry_requirements' and f.state in ('queued', 'waiting', 'ai', 'leased'))
                   then 'a read of this course is in progress' end;
  v_rep := case when st->>'field_code' = 'course_entry_first_read' then security.layer4_reread_repeat_v1(p_ref::uuid) else jsonb_build_object('repeat', false) end;
  v_repeat := coalesce((v_rep->>'repeat')::boolean, false);
  v_rec := case when (st->>'complete')::boolean then 'none: the read is complete'
                when v_iv.id is not null then 'answer the open Human input needed item (ref ' || v_iv.id || ')'
                when v_busy is not null then 'wait: ' || v_busy
                -- mandate 16:32 §4, §7: after an identical refusal the honest next step is the row-limit decision or a changed copy, reader or setting
                when v_repeat and coalesce((v_rep->>'row_limit')::boolean, false) then 'row_limit_decision'
                when v_repeat then 'wait_for_change'
                when coalesce((st->>'stored_copy')::boolean, false) and coalesce(st->'corrected_read'->>'state', '') <> 'superseded'
                     and not exists (select 1 from pipeline.layer4_aer_recovery_actions a where a.review_item_id = p_ref::uuid and a.choice = 'reread_stored') then 'reread_stored'
                when not coalesce((st->>'stored_copy')::boolean, false) then 'request_evidence'
                else 'open_intervention' end;
  -- CF-247 hotfix (Platform Admin report 4 Nov 11:13): the case list no longer runs the completeness gate for every waiting read of the
  -- university (0.8 s each; RMIT has 303, so the card's detail timed out and its recovery choices never loaded). The card names the other
  -- waiting reads of the same university and kind, cheaply; the case itself is still formed by its key when Request official evidence is chosen.
  select jsonb_build_object('count', count(*), 'first', coalesce(jsonb_agg(jsonb_build_object('ref', z.id, 'subject', z.subject) order by z.created_at)
           filter (where z.rn <= security.pipeline_num_v1('har.aer_case_items_max', 20)), '[]'::jsonb)) into v_case
    from (select li.id, li.created_at, coalesce(c.display_title, c.canonical_title) subject, row_number() over (order by li.created_at) rn
            from pipeline.layer4_review_items li join catalogue.courses c on c.id = li.entity_id
           where li.status = 'pending' and li.field_code = st->>'field_code' and li.id <> p_ref::uuid
             and (st->>'course_id') is not null and c.provider_id = (st->>'provider_id')::uuid) z;
  return jsonb_build_object('sections', jsonb_build_array(
      jsonb_build_object('key', 'recovery', 'title', 'Recovery', 'body', jsonb_strip_nulls(jsonb_build_object(
        'Waiting rows', jsonb_array_length(st->'waiting_rows'), 'Dropped requirements', jsonb_array_length(st->'dropped'),
        'Dropped without a row (quotations)', jsonb_array_length(st->'missing_quotes'), 'Why the read is held', st->'reasons',
        'Recommended recovery', v_rec, 'Or decide', case when v_repeat and (v_rep->>'row_limit')::boolean then 'a row limit for this university (Platform Admin, entry.max_rows_by_provider)' end,
        'Human input needed', case when v_rec in ('open_intervention', 'request_evidence') or v_iv.id is not null then 'yes'
                                   when v_rec = 'row_limit_decision' then 'no: the Platform Admin decides a row limit for this university (entry.max_rows_by_provider)'
                                   when v_rec = 'wait_for_change' then 'no: typed rows would resume the same refused read' else 'not yet' end,
        'Owner', case when v_iv.id is not null then v_iv.assigned_to when v_rec = 'reread_stored' then 'the entry reader (automatic)'
                      when v_rec = 'row_limit_decision' then 'Platform Admin' when v_rec = 'wait_for_change' then 'the platform (reconsidered when the copy, reader or setting changes)' else 'Layer 4 reviewer' end,
        'Next automatic attempt', case when v_busy is not null then 'the requested read' when v_iv.id is not null then coalesce(security.l4_time_v1(v_iv.next_action_at)->>'text', 'when the input is given') else 'none until a recovery is chosen' end,
        'Last attempt', case when v_last.id is not null then v_last.choice || ' at ' || (security.l4_time_v1(v_last.at)->>'text') || ': ' || coalesce(v_last.next_operation, '') end,
        'Last attempt status', coalesce(st->'corrected_read'->>'state', v_last.work_item_status)))),
      jsonb_build_object('key', 'corrected_read', 'title', 'Last corrected read', 'body', jsonb_strip_nulls(jsonb_build_object(
        'Requested', v_rep->'requested'->>'text', 'Requested by', v_rep->>'requested_by', 'Reader result', case v_rep->>'state' when 'requested' then 'waiting for the reader'
                                                                                                            when 'superseded' then 'complete: a new read replaced this one' else v_rep->>'outcome' end,
        'Result at', v_rep->'closed'->>'text', 'Stored copy read', v_rep->>'evidence_used', 'Refusals on this copy', v_rep->'refused_on_this_copy',
        'Same read again', case when v_repeat then 'not offered: ' || (v_rep->>'why') end, 'Instead', case when v_repeat then v_rep->>'alternative' end))),
      jsonb_build_object('key', 'case', 'title', 'Recovery case', 'body', jsonb_build_object('Case', st->>'case_label', 'Other waiting reads of this university and kind', v_case))),
    'actions', jsonb_build_array(
      jsonb_build_object('key', 'reread_stored', 'allowed', v_busy is null and not (st->>'complete')::boolean and not v_repeat,
                         'why', coalesce(v_busy, case when v_repeat then (v_rep->>'why') || '. ' || (v_rep->>'alternative') end)),
      jsonb_build_object('key', 'request_evidence', 'allowed', v_iv.id is null, 'why', case when v_iv.id is not null then 'a Human input needed item is already open (ref ' || v_iv.id || ')' end),
      jsonb_build_object('key', 'ai_analyse', 'allowed', v_ai and v_iv.id is null,
                         'why', case when not v_ai then 'the stronger-model step is off (har.ai_escalate_on, ops.ai_diagnosis_on or no pinned model)'
                                     when v_iv.id is not null then 'a Human input needed item is already open (ref ' || v_iv.id || ')' end),
      jsonb_build_object('key', 'open_intervention', 'allowed', v_iv.id is null and not v_repeat, 'recommended', v_rec = 'open_intervention',
                         'why', case when v_iv.id is not null then 'a Human input needed item is already open (ref ' || v_iv.id || ')'
                                     when v_repeat then 'typed rows would resume the same corrected read of the same copy, which the reader refuses: ' || (v_rep->>'alternative') end)));
end $$;


ALTER FUNCTION "security"."layer4_aer_recovery_detail_v1"("p_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_aer_recovery_kind_v1"() RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select '{"choices": [
     {"key": "reread_stored", "label": "Re-read from stored evidence", "returns": "The existing reader reads the page again from its stored copy (no new paid read where a copy exists); the new read replaces this one only through the same gates"},
     {"key": "request_evidence", "label": "Request official evidence", "returns": "One Human input needed item asks for the official page or document for this case; when it is given, the course is read again by itself"},
     {"key": "ai_analyse", "label": "Ask AI to analyse the failure", "returns": "The pinned stronger model looks at this failure once (within the AI limits) and proposes rows with quotations; a proposal is checked and only suggested"},
     {"key": "open_intervention", "label": "Open human input", "returns": "One Human input needed item asks for the dropped requirements as rows with quotations; when they check out, the course is read again by itself"}]}'::jsonb
$$;


ALTER FUNCTION "security"."layer4_aer_recovery_kind_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_aer_recovery_state_v1"("p_item" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.layer4_review_items; g jsonb; v_run uuid; v_src uuid; v_pid uuid; v_drop jsonb := '[]'::jsonb; v_rows jsonb; v_case text; v_sup record;
begin
  select * into r from pipeline.layer4_review_items where id = p_item;
  -- F-AER.07 (11 Nov 2026): the corrected-read record exists before either branch reads it (a provider-table item never sets it)
  select null::text state, null::text outcome, null::timestamptz requested_at, null::uuid new_item_id into v_sup;
  if r.id is null or r.field_code not in ('course_entry_first_read', 'entry_matrix_first_run', 'entry_matrix_change') then return null; end if;
  if r.field_code = 'course_entry_first_read' then
    select c.provider_id into v_pid from catalogue.courses c where c.id = r.entity_id;
    g := security.course_entry_gate_v1(r.id, '{}'::uuid[]);
    v_drop := coalesce(r.proposed_value->'dropped', (select f.value->'dropped' from pipeline.field_enrich_items f where f.id = nullif(r.proposed_value->>'item_id', '')::bigint), '[]'::jsonb);
    select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'quote', x.quote) order by x.id), '[]'::jsonb) into v_rows
      from catalogue.course_entry_requirements x where x.provenance->>'review_item_id' = r.id::text and x.status = 'proposed';
    select s.state, s.outcome, s.requested_at, s.new_item_id into v_sup from pipeline.aer_read_supersessions s where s.old_item_id = r.id order by s.requested_at desc limit 1;
  else
    select x.id, x.source_id, x.provider_id into v_run, v_src, v_pid from pipeline.entry_matrix_runs x where x.review_item_id = r.id order by x.created_at desc limit 1;
    g := case when v_run is not null then security.entry_matrix_gate_v1(v_run, '{}'::uuid[]) end;
    select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'quote', m.quote) order by m.id), '[]'::jsonb) into v_rows
      from catalogue.provider_entry_matrix m where m.run_id = v_run and m.status = 'proposed';
  end if;
  v_case := coalesce(v_pid::text, '-') || '|' || r.field_code || '|' || left(regexp_replace(coalesce(g->'reasons'->>0, 'incomplete'), '[0-9]+', '#', 'g'), 80);
  return jsonb_build_object('item', r.id, 'field_code', r.field_code, 'course_id', case when r.entity_type = 'course' then r.entity_id end, 'provider_id', v_pid,
    'run_id', v_run, 'source_id', v_src, 'complete', coalesce((g->>'complete')::boolean, false), 'reasons', coalesce(g->'reasons', '[]'::jsonb), 'gate', g,
    'waiting_rows', v_rows, 'dropped', v_drop,
    'missing_quotes', (select coalesce(jsonb_agg(d->'quote'), '[]'::jsonb) from jsonb_array_elements(v_drop) d where nullif(d->>'quote', '') is not null),
    'evidence_id', r.evidence_id, 'stored_copy', r.evidence_id is not null or exists (select 1 from pipeline.coverage_course_pages p where p.course_id = r.entity_id and p.evidence_id is not null),
    'corrected_read', case when v_sup.state is not null then jsonb_build_object('state', v_sup.state, 'outcome', v_sup.outcome, 'at', v_sup.requested_at, 'new_item', v_sup.new_item_id) end,
    'case_key', md5(v_case), 'case_label', left(coalesce(g->'reasons'->>0, 'incomplete read'), 160),
    'problem_fingerprint', md5(coalesce(g::text, '') || '|' || coalesce(r.evidence_id::text, '') || '|' || v_drop::text));
end $$;


ALTER FUNCTION "security"."layer4_aer_recovery_state_v1"("p_item" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_aer_review_detail_v1"("p_ref" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare p jsonb; h jsonb; v_sec jsonb;
begin
  p := security.aer_review_packet_v1(p_ref::uuid);
  if p is null then return jsonb_build_object('sections', '[]'::jsonb, 'actions', '[]'::jsonb); end if;
  begin
    h := security.layer4_aer_recovery_detail_v1(p_ref);
  exception when others then
    h := jsonb_build_object('sections', jsonb_build_array(jsonb_build_object('key', 'recovery', 'title', 'Recovery', 'body', jsonb_build_object('Not available', left(sqlerrm, 200)))),
                            'actions', '[]'::jsonb);
  end;
  v_sec := jsonb_build_array(
    -- direction 12:16 §7: a readable summary first: what this item is, why, and the next action
    jsonb_build_object('key', 'summary', 'title', 'Summary', 'body', jsonb_strip_nulls(jsonb_build_object(
      'Class', case p->'settlement'->>'settlement' when 'ready' then 'Ready for a decision' when 'recoverable' then 'Technically held: an automatic recovery remains'
                                                 when 'needs_input' then 'Needs evidence, input or a decision' when 'stale' then 'Stale: no longer a valid read' end,
      'Failure', case when p->'settlement'->>'settlement' <> 'ready' then p->'settlement'->>'why' end,
      'Next action', p->'settlement'->>'next_action',
      'Corrected reads so far', nullif((p->'settlement'->>'tries')::int, 0)))),
    jsonb_build_object('key', 'review', 'title', 'Review', 'body', jsonb_strip_nulls(jsonb_build_object(
      'University', p->>'provider', 'Course', p->'course'->>'title', 'Course code', p->'course'->>'code', 'Qualification', p->'course'->>'qualification',
      'Country', p->'course'->>'country', 'Source', p->'source'->>'url', 'Audience', p->'audiences', 'Stored copy', p->'evidence',
      'Recommended decision', p->>'recommended', 'If approved', p->'consequences'->>'approve', 'If rejected', p->'consequences'->>'reject',
      'Owner', case when jsonb_array_length(p->'owner') = 0 then 'no one has claimed this university and kind' else (p->'owner')::text end,
      'Queue', case when (p->'queue'->>'position') is not null then (p->'queue'->>'position') || ' of ' || (p->'queue'->>'ready_at_university') || ' ready at this university'
                    else 'not reviewer-ready: ' || (p->'route'->>'route') || ' (' || (p->'queue'->>'ready_at_university') || ' ready at this university)' end,
      'Next ready item', p->'queue'->>'next_ready'))),
    jsonb_build_object('key', 'checks', 'title', 'Completeness and conflicts', 'body', jsonb_strip_nulls(jsonb_build_object(
      'Gate', case when (p->'gate'->>'complete')::boolean then 'complete' else 'held' end, 'Checked', p->'gate'->>'source', 'Reasons', p->'gate'->'reasons',
      'Conflicts', nullif(p->'conflicts', '{}'::jsonb), 'Rows to leave out', nullif(p->'exclude_row_ids', '[]'::jsonb),
      'Route', p->'route'->>'route', 'Remedy', p->'route'->>'remedy'))),
    jsonb_build_object('key', 'facts', 'title', 'Facts the page states', 'body', (security.aer_packet_facts_v1(p_ref::uuid))->'section'),
    jsonb_build_object('key', 'rows', 'title', 'Proposed rows (' || (p->'proposed'->>'count') || ')', 'body', p->'proposed'->'rows'),
    jsonb_build_object('key', 'active', 'title', 'Active rows (' || (p->'active'->>'count') || ')', 'body', p->'active'->'rows'));
  if jsonb_array_length(p->'locks') > 0 then v_sec := v_sec || jsonb_build_array(jsonb_build_object('key', 'locks', 'title', 'Manual locks', 'body', p->'locks')); end if;
  return jsonb_build_object('sections', v_sec || coalesce(h->'sections', '[]'::jsonb), 'actions', coalesce(h->'actions', '[]'::jsonb), 'packet', p);
end $$;


ALTER FUNCTION "security"."layer4_aer_review_detail_v1"("p_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_aer_university_summary_v1"("p_provider" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with s as (select * from security.aer_settlement_v1(p_provider))
  select jsonb_build_object('provider_id', p_provider,
    'pending', (select count(*) from s), 'review_ready', (select count(*) from s where s.settlement = 'ready'),
    'technically_held', (select count(*) from s where s.settlement = 'recoverable'), 'human_input_required', (select count(*) from s where s.settlement = 'needs_input'),
    'stale', (select count(*) from s where s.settlement = 'stale'), 'unresolved', (select count(*) from s where s.settlement <> 'ready'),
    'human_input_open', (select count(*) from pipeline.layer4_interventions x where x.provider_id = p_provider and x.lane in ('aer_item', 'aer_course', 'aer_source')
                          and x.status in ('ai_pending', 'awaiting_input', 'resuming')),
    'admitted_courses', (select count(distinct q.course_id) from catalogue.course_entry_requirements q join catalogue.courses c on c.id = q.course_id
                          where c.provider_id = p_provider and q.status = 'active'),
    'admitted_matrix_rows', (select count(*) from catalogue.provider_entry_matrix m where m.provider_id = p_provider and m.status = 'active'),
    'by_route', (select jsonb_object_agg(z.route, z.n) from (select coalesce(s.route, 'unchecked') route, count(*) n from s group by 1) z))
$$;


