CREATE OR REPLACE FUNCTION "security"."layer4_arrival_guard_trg_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_res jsonb;
begin
  if new.status is distinct from 'pending' or security.pipeline_num_v1('layer4.arrival_guard_on', 0) < 1
     or not (new.field_code = any (security.pipeline_list_v1('layer4.platform_kinds', '[]'::jsonb))) then
    return new;
  end if;
  new.id := coalesce(new.id, gen_random_uuid());
  v_res := security.layer4_resolution_for_v1(new.id, new.entity_type, new.entity_id, new.field_code, new.proposed_value, new.layer2_state, new.evidence_id, coalesce(new.created_at, now()));
  if v_res is null then return new; end if;
  new.status := 'superseded';
  new.decided_at := now();
  new.change_control_ref := coalesce(new.change_control_ref || '; ', '') || 'CF-247 L4 readiness: settled on arrival (' || (v_res->>'reason') || ')';
  insert into pipeline.layer4_supersessions(item_id, field_code, entity_type, entity_id, reason, covered_by_item, evidence, mode)
  values (new.id, new.field_code, new.entity_type, new.entity_id, v_res->>'reason', nullif(v_res->>'covered_by_item', '')::uuid, coalesce(v_res->'evidence', '{}'::jsonb), 'arrival');
  return new;
end $$;


ALTER FUNCTION "security"."layer4_arrival_guard_trg_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_batch_decide_v1_impl"("p_item_ids" "uuid"[], "p_action" "text", "p_reason" "text", "p_confirmation" "text", "p_batch_label" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_actor uuid:=auth.uid(); v_ids uuid[]; v_n int; v_kinds int; v_not_pending int; v_field text; v_entity text; v_res jsonb; v_results jsonb:='[]'::jsonb; v_id uuid; v_op uuid;
begin
  if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
  if security.current_role_rank()<4 then raise exception 'Pipeline Operator role is required for batch decisions' using errcode='42501'; end if;
  if p_action not in ('approve','reject','request_more_evidence','return_layer2','return_layer3') then raise exception 'this action cannot be applied as a batch'; end if;
  if length(trim(coalesce(p_reason,'')))<8 then raise exception 'a batch reason of at least 8 characters is required'; end if;
  select array_agg(distinct x) into v_ids from unnest(p_item_ids) x where x is not null;
  v_n := coalesce(cardinality(v_ids),0);
  if v_n<2 then raise exception 'a batch needs at least 2 items'; end if;
  if v_n>100 then raise exception 'a batch can hold at most 100 items'; end if;
  if trim(coalesce(p_confirmation,'')) <> upper(p_action)||' '||v_n then
    raise exception 'confirmation must exactly match "%"', upper(p_action)||' '||v_n;
  end if;
  select count(*) filter (where status<>'pending'), count(distinct (entity_type,field_code)), min(field_code), min(entity_type)
    into v_not_pending, v_kinds, v_field, v_entity
  from pipeline.layer4_review_items where id = any(v_ids);
  if (select count(*) from pipeline.layer4_review_items where id=any(v_ids)) <> v_n then raise exception 'some items were not found'; end if;
  if v_not_pending>0 then raise exception '% item(s) in this batch have already been decided; refresh and preview again', v_not_pending; end if;
  if v_kinds<>1 then raise exception 'a batch must contain one kind of item'; end if;
  -- CF-247 A2 (Platform Admin 30 Oct 2026 06:53): AER items are never decided in a batch; the batch is skipped and counted, nothing is decided
  -- CF-247 P1 (Platform Admin 2 Nov 2026 14:50): university descriptions are decided one at a time in the Inbox; the batch is skipped and counted
  if v_field = 'provider_description' then
    return jsonb_build_object('ok',false,'decided',0,'skipped_aer',0,'skipped_description',v_n,'action',p_action,'reason','one_at_a_time',
      'message',v_n||' university description(s) skipped: each is approved or rejected on its own in the Inbox');
  end if;
  if v_field = any (security.aer_review_kinds_v1()) then
    return jsonb_build_object('ok',false,'decided',0,'skipped_aer',v_n,'action',p_action,'reason','aer_review_path_only',
      'message',v_n||' AER item(s) skipped: AER items are decided one at a time in the AER review path (decision A2)');
  end if;
  if exists(select 1 from pipeline.layer4_review_items where id=any(v_ids) and assigned_to is not null and assigned_to<>v_actor and claimed_at > now()-interval '30 minutes') then
    raise exception '% item(s) in this batch are being reviewed by someone else; untick them or try later', (select count(*) from pipeline.layer4_review_items where id=any(v_ids) and assigned_to is not null and assigned_to<>v_actor and claimed_at > now()-interval '30 minutes');
  end if;
  if p_action='approve' and v_entity<>'course' then raise exception 'only course facts can be approved in a batch'; end if;

  foreach v_id in array v_ids loop
    v_res := security.layer4_review_decide_impl(v_id, p_action, trim(p_reason), null);
    v_results := v_results || jsonb_build_array(jsonb_build_object('review_item_id',v_id,'decision_id',v_res->>'decision_id','status',v_res->>'status'));
  end loop;

  insert into pipeline.layer4_mass_operations(target_kind,action,actor_id,group_key,reason,before_count,affected_count,result,change_control_ref)
  values ('review_batch',p_action,v_actor,jsonb_build_object('batch_label',p_batch_label,'entity_type',v_entity,'field_code',v_field,'item_ids',to_jsonb(v_ids)),
          trim(p_reason),v_n,jsonb_array_length(v_results),jsonb_build_object('decisions',v_results),'CF-CHG-20260915-247')
  returning id into v_op;
  return jsonb_build_object('ok',true,'mass_operation_id',v_op,'decided',jsonb_array_length(v_results),'action',p_action,'skipped_aer',0);
end $$;


ALTER FUNCTION "security"."layer4_batch_decide_v1_impl"("p_item_ids" "uuid"[], "p_action" "text", "p_reason" "text", "p_confirmation" "text", "p_batch_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_block_state_read"("p_entity_type" "text", "p_entity_id" "uuid", "p_block_scope" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_rank int;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  if v_rank<3 then raise exception 'curator role required' using errcode='42501'; end if;
  if not security.layer4_entity_exists(p_entity_type,p_entity_id) then
    raise exception 'entity not found' using errcode='22023';
  end if;
  if p_block_scope is not null and p_block_scope not in ('operational','publication','search','data_quality_quarantine') then
    raise exception 'invalid block scope' using errcode='22023';
  end if;

  return coalesce((
    with latest as (
      select distinct on(block_scope)
        id,block_scope,event_type,reason_code,comment,actor_id,actor_email,
        expires_at,review_at,created_at
      from pipeline.layer4_block_decisions
      where entity_type=p_entity_type and entity_id=p_entity_id
        and (p_block_scope is null or block_scope=p_block_scope)
      order by block_scope,created_at desc,id desc
    )
    select jsonb_build_object(
      'entity_type',p_entity_type,'entity_id',p_entity_id,
      'states',coalesce(jsonb_agg(jsonb_build_object(
        'scope',block_scope,
        'blocked',event_type='block' and (expires_at is null or expires_at>now()),
        'event_type',event_type,'reason_code',reason_code,'comment',comment,
        'actor_id',actor_id,'actor_email',actor_email,
        'expires_at',expires_at,'review_at',review_at,'created_at',created_at
      ) order by block_scope),'[]'::jsonb)
    ) from latest
  ),jsonb_build_object('entity_type',p_entity_type,'entity_id',p_entity_id,'states','[]'::jsonb));
end $$;


ALTER FUNCTION "security"."layer4_block_state_read"("p_entity_type" "text", "p_entity_id" "uuid", "p_block_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_blockers_v1"("p_item" "uuid", "p_gate" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare i pipeline.layer4_review_items; v_b jsonb := '[]'::jsonb; v_url text; v_ev pipeline.evidence_artifacts; v_gate jsonb; v_n int; v_now text; v_route text;
        v_aer boolean;
begin
  select * into i from pipeline.layer4_review_items where id = p_item;
  if i.id is null then return null; end if;
  v_aer := i.field_code in ('course_entry_first_read', 'entry_matrix_first_run', 'entry_matrix_change');
  if i.field_code = 'official_course_url' then
    v_url := btrim(coalesce(case jsonb_typeof(i.proposed_value) when 'string' then i.proposed_value #>> '{}' when 'object' then coalesce(i.proposed_value->>'url', i.proposed_value->>'course_url') end, ''));
    if exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = i.entity_id and l.field in ('official_url', 'course_url')) then
      v_b := v_b || jsonb_build_object('code', 'manual_lock', 'why', 'the course''s page was set by hand on the course record', 'repair', 'course record (a person changes the page there, or keeps it)');
    end if;
    if v_url !~* '^https://[a-z0-9.-]+\.[a-z]{2,}(/[^\s]*)?$' then
      v_b := v_b || jsonb_build_object('code', 'invalid_link', 'why', 'the proposed page is not a full https:// address', 'repair', 'link repair (course page relink)', 'url', v_url);
    elsif to_regprocedure('security.reference_url_has_use(text,text)') is not null and security.reference_url_has_use(v_url, 'not_course_page') then
      v_b := v_b || jsonb_build_object('code', 'invalid_link', 'why', 'the proposed page is on a search, social or course-listing site', 'repair', 'link repair (course page relink)', 'url', v_url);
    end if;
  elsif i.field_code = 'course_description_first_read' then
    if exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = i.entity_id and l.field in ('description', 'course_description', 'all')) then
      v_b := v_b || jsonb_build_object('code', 'manual_lock', 'why', 'the description was set by hand', 'repair', 'course record');
    end if;
    select nullif(btrim(c.description), '') into v_now from catalogue.courses c where c.id = i.entity_id;
    if v_now is distinct from nullif(btrim(i.before_value->>'description'), '') then
      v_b := v_b || jsonb_build_object('code', 'value_moved', 'why', 'the description changed since this was proposed', 'repair', 'course description reader (read again)');
    end if;
  elsif i.field_code = 'provider_description' then
    if exists (select 1 from pipeline.manual_locks l where l.entity = 'provider' and l.entity_id = i.entity_id and l.field in ('description', 'p_description', 'all')) then
      v_b := v_b || jsonb_build_object('code', 'manual_lock', 'why', 'the description was set by hand', 'repair', 'provider record');
    end if;
  end if;
  if i.field_code in ('provider_current_tuition_validation', 'course_description_first_read', 'course_entry_first_read', 'entry_matrix_first_run', 'provider_description') then
    if i.evidence_id is null or not exists (select 1 from pipeline.evidence_artifacts e where e.id = i.evidence_id and (i.field_code <> 'provider_current_tuition_validation' or e.source_id is not null)) then
      v_b := v_b || jsonb_build_object('code', 'evidence_missing', 'why', 'there is no stored page (with its source) for this proposal', 'repair', 'the reader of this kind (read again)');
    end if;
  end if;
  if i.evidence_id is not null then
    select * into v_ev from pipeline.evidence_artifacts e where e.id = i.evidence_id;
    if v_ev.valid_to < now() or exists (select 1 from pipeline.evidence_artifacts n where n.supersedes_evidence_id = i.evidence_id) then
      v_b := v_b || jsonb_build_object('code', 'evidence_stale', 'why', 'a newer copy of the page is stored, or this copy is past its validity', 'repair', 'the reader of this kind (read the newer copy)');
    end if;
  end if;
  if i.field_code = 'course_entry_first_read' then
    select count(*) into v_n from catalogue.course_entry_requirements x
     where x.course_id = i.entity_id and x.status = 'proposed' and x.provenance->>'review_item_id' = i.id::text;
    if v_n = 0 then
      v_b := v_b || jsonb_build_object('code', 'nothing_to_admit', 'why', 'no waiting row is left on this read', 'repair', 'course entry reader (D-R2 replacement read)');
    end if;
    if p_gate and to_regprocedure('security.course_entry_gate_v1(uuid,uuid[])') is not null then
      v_gate := security.course_entry_gate_v1(i.id, '{}'::uuid[]);
    end if;
  elsif i.field_code in ('entry_matrix_first_run', 'entry_matrix_change') then
    if p_gate and to_regprocedure('security.entry_matrix_gate_v1(uuid,uuid[])') is not null and nullif(i.proposed_value->>'run_id', '') is not null then
      v_gate := security.entry_matrix_gate_v1((i.proposed_value->>'run_id')::uuid, '{}'::uuid[]);
    end if;
  end if;
  if v_gate is not null and not coalesce((v_gate->>'complete')::boolean, true) then
    v_b := v_b || jsonb_build_object('code', 'completeness_gate', 'why', coalesce(v_gate->'reasons'->>0, 'the completeness gate holds this read'),
                                     'repair', case when i.field_code = 'course_entry_first_read' then 'course entry reader (D-R2 replacement read)' else 'entry matrix reader (re-read)' end,
                                     'rule', v_gate->>'rule');
  end if;
  v_route := case when jsonb_array_length(v_b) > 0 then 'repair:' || (v_b->0->>'code')
                  when v_aer then 'review:platform_admin' else 'review:curator' end;
  return jsonb_build_object('blockers', v_b, 'route', v_route, 'gate', v_gate);
end $_$;


ALTER FUNCTION "security"."layer4_blockers_v1"("p_item" "uuid", "p_gate" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_card_evidence_v1"("p_kind" "text", "p_ref" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare o pipeline.provider_onboarding; f pipeline.enrichment_flags; v_web text; v_courses int; rd record; v jsonb;
begin
  if p_kind in ('website_needed', 'too_few_pages', 'nothing_ready', 'central_to_approve', 'onboarding_failed') then
    select * into o from pipeline.provider_onboarding x where x.id = p_ref::uuid;
    if o.id is null then return null; end if;
    select p.website, (select count(*) from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active') into v_web, v_courses
      from catalogue.providers p where p.id = o.provider_id;
    v := jsonb_strip_nulls(jsonb_build_object('Website', coalesce(o.result->>'website', v_web), 'Active courses', v_courses,
      'Courses in the run', o.result->'courses', 'Pages read', o.result->'pages_read', 'AI attempts', o.result->'ai_attempts',
      'Fields ready', case when jsonb_typeof(o.result->'ready') = 'array' then jsonb_array_length(o.result->'ready') end,
      'Why each field is held', case when jsonb_typeof(o.result->'held') = 'object' then o.result->'held' end,
      'Central pages', o.result->'central_pages', 'Stop', o.stop_reason, 'Note', o.note,
      'Runs stopped the same way', (select count(*) from pipeline.provider_onboarding y where y.provider_id = o.provider_id and y.status = 'stopped' and y.stop_reason = o.stop_reason)));
    return v;
  elsif p_kind in ('pages_not_found', 'site_down', 'fee_check', 'not_offered', 'not_on_site') then
    select * into f from pipeline.enrichment_flags x where x.id = case when p_ref ~ '^[0-9]+$' then p_ref::bigint end;
    if f.id is null then return null; end if;
    return jsonb_strip_nulls(jsonb_build_object('Site', coalesce(f.evidence->>'site', f.evidence->>'page_url'), 'How it was looked for', f.evidence->>'method',
      'Addresses found', f.evidence->'addresses', 'Pages read', f.evidence->'pages_read', 'Tried', nullif(f.evidence->'tried', '[]'::jsonb),
      'Discovery', f.evidence->>'discovery', 'Checks so far', f.checks, 'Tries so far', f.tries, 'Next automatic check', security.l4_time_v1(f.next_check_at)->>'text'));
  elsif p_kind in ('course_link', 'aer_review', 'provider_description', 'no_page_first_run', 'conjoint_first_run') and p_ref ~ '^[0-9a-f-]{36}$' then
    select r.readiness, r.route, r.resolution into rd from pipeline.layer4_item_readiness r where r.item_id = p_ref::uuid;
    if rd.route in ('platform:decided_before', 'platform:duplicate_pending', 'platform:covered_by_active') then
      return jsonb_build_object('Settled before', jsonb_strip_nulls(jsonb_build_object('Why', replace(substr(rd.route, 10), '_', ' '),
        'Covered by item', rd.resolution->>'covered_by_item', 'Decision', rd.resolution->>'decision', 'Decided', security.l4_time_v1((rd.resolution->>'decided_at')::timestamptz)->>'text',
        'Rule that may settle it', 'security.layer4_reconcile_v1 (layer4.reconcile_supersede_on ' ||
           case when security.pipeline_num_v1('layer4.reconcile_supersede_on', 0) >= 1 then 'on)' else 'off: a person decides until it is switched on)' end)));
    end if;
  end if;
  return null;
end $_$;


ALTER FUNCTION "security"."layer4_card_evidence_v1"("p_kind" "text", "p_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_card_group_v1"("p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  -- the group of the cards on screen, keyed 'kind:ref', from the stored groups only, with whether a person is needed, what moves the item and
  -- the evidence held (§7 questions 3 and 4). A card not grouped yet, or whose input changed since, shows C "not grouped yet"
  with k as (select distinct x->>'kind' kind, x->>'ref' ref from jsonb_array_elements(case when jsonb_typeof(p_items) = 'array' then p_items else '[]'::jsonb end) x
              where x ? 'kind' and x ? 'ref' limit security.pipeline_num_v1('layer4.lifecycle_batch_max', 50)::int),
       g as (select k.kind, k.ref, x.grp, x.cls, x.rule, x.next_action, x.classified_at,
                    x.kind is null or x.state <> 'waiting' or (rd.classified_at is not null and rd.classified_at > x.input_at) or (iv.updated_at is not null and iv.updated_at > x.input_at) pending
               from k left join pipeline.layer4_item_groups x on x.kind = k.kind and x.ref = k.ref
               left join pipeline.layer4_item_readiness rd on k.kind in ('course_link', 'aer_review', 'provider_description', 'no_page_first_run', 'conjoint_first_run')
                    and rd.item_id = case when k.ref ~ '^[0-9a-f-]{36}$' then k.ref::uuid end
               left join pipeline.layer4_interventions iv on k.kind = 'intervention' and iv.id = case when k.ref ~ '^[0-9]+$' then k.ref::bigint end)
  select coalesce(jsonb_object_agg(g.kind || ':' || g.ref, jsonb_strip_nulls(jsonb_build_object(
           'group', case when g.pending then 'C' else g.grp end, 'class', case when g.pending then 'not_grouped_yet' else g.cls end, 'rule', case when not g.pending then g.rule end,
           'group_label', case when g.pending then 'Ready for my decision (not grouped yet)' when g.grp = 'A' then 'Settled by an existing rule' when g.grp = 'B' then 'Technical recovery'
                               when g.grp = 'C' then 'Ready for my decision' else 'Information needed from me' end,
           'person_needed', case when g.pending then 'treated as a decision until job layer4-groups groups it' when g.grp = 'A' then 'no: an existing rule may settle it'
                                 when g.grp = 'B' then 'not yet: the platform is recovering it' when g.grp = 'C' then 'yes: a decision' else 'yes: information only a person can give' end,
           'grouped_at', security.l4_time_v1(g.classified_at), 'evidence', security.layer4_card_evidence_v1(g.kind, g.ref)))), '{}'::jsonb)
    from g
$_$;


ALTER FUNCTION "security"."layer4_card_group_v1"("p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_cl_group_call_v1"("p_item" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v jsonb;
begin
  if to_regprocedure('security.course_link_route_class_v1(uuid)') is null then return jsonb_build_object('grp', 'C', 'cls', 'course_link:router_missing'); end if;
  execute 'select security.course_link_route_class_v1($1)' into v using p_item;
  return case when v->>'group' in ('A', 'B', 'C', 'D')
              then jsonb_build_object('grp', v->>'group', 'cls', 'course_link:' || coalesce(v->>'class', 'routed'),
                                      'rule', case when v->>'group' = 'A' then coalesce(v->>'authority', v->>'action') end, 'action', v->>'action', 'reason', v->>'reason')
              else jsonb_build_object('grp', 'C', 'cls', 'course_link:not_routed') end;
exception when others then return jsonb_build_object('grp', 'C', 'cls', 'course_link:router_failed');
end $_$;


ALTER FUNCTION "security"."layer4_cl_group_call_v1"("p_item" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_claim_v1_impl"("p_review_item_id" "uuid", "p_release" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_actor uuid:=auth.uid(); v_item pipeline.layer4_review_items%rowtype; v_active boolean;
begin
  if v_actor is null or security.current_role_rank()<3 then raise exception 'curator role required' using errcode='42501'; end if;
  select * into v_item from pipeline.layer4_review_items where id=p_review_item_id for update;
  if not found then raise exception 'review item not found'; end if;
  v_active := v_item.assigned_to is not null and v_item.claimed_at is not null and v_item.claimed_at > now()-interval '30 minutes';
  if p_release then
    if v_item.assigned_to = v_actor then update pipeline.layer4_review_items set assigned_to=null, claimed_at=null where id=v_item.id; end if;
    return jsonb_build_object('ok',true,'released',v_item.assigned_to = v_actor);
  end if;
  if v_item.status<>'pending' then return jsonb_build_object('ok',false,'reason','already decided'); end if;
  if v_active and v_item.assigned_to<>v_actor then
    return jsonb_build_object('ok',false,'reason','claimed','claimed_by',(select email from auth.users where id=v_item.assigned_to),
      'minutes_left',ceil(extract(epoch from (v_item.claimed_at+interval '30 minutes'-now()))/60));
  end if;
  update pipeline.layer4_review_items set assigned_to=v_actor, claimed_at=now() where id=v_item.id;
  return jsonb_build_object('ok',true,'claimed',true);
end $$;


ALTER FUNCTION "security"."layer4_claim_v1_impl"("p_review_item_id" "uuid", "p_release" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_clean_quote"("q" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $_$
  -- "Fees[A$60952](https://...)Duration" -> "Fees A$60952 Duration"
  select nullif(btrim(regexp_replace(regexp_replace(coalesce(q,''), '\[([^\]]*)\]\([^)]*\)', ' \1 ', 'g'), '\s+', ' ', 'g')),'')
$_$;


ALTER FUNCTION "security"."layer4_clean_quote"("q" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_course_description_apply_v1"("p_actor" "uuid", "p_item_id" "uuid", "p_value" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_review_items%rowtype; v_text text; v_now text; v_shown text;
begin
  select * into i from pipeline.layer4_review_items where id = p_item_id;
  if i.id is null or i.entity_type <> 'course' or i.field_code <> 'course_description_first_read' then raise exception 'not a course description item' using errcode = '22023'; end if;
  -- approved as read: an edited description has no quote for its new words (reject it; the page is read again later)
  if p_value is distinct from i.proposed_value then raise exception 'a description is approved as read, with every sentence quoted from the page; reject it instead of editing' using errcode = '22023'; end if;
  v_text := nullif(btrim(i.proposed_value->>'description'), '');
  if v_text is null then raise exception 'the proposal has no description' using errcode = '22023'; end if;
  if i.evidence_id is null then raise exception 'the proposal has no stored page' using errcode = '22023'; end if;
  if exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = i.entity_id and l.field in ('description', 'course_description', 'all')) then
    raise exception 'the description is locked by hand' using errcode = '22023';
  end if;
  select nullif(btrim(c.description), '') into v_now from catalogue.courses c where c.id = i.entity_id for update;
  if v_now is distinct from nullif(btrim(i.before_value->>'description'), '') then raise exception 'the description changed since this was proposed; reject this item' using errcode = '22023'; end if;
  update catalogue.courses set description = v_text, updated_at = now() where id = i.entity_id;
  select c.description into v_shown from catalogue.courses c where c.id = i.entity_id;  -- the column public.website_v2_course reads
  return jsonb_build_object('course_id', i.entity_id, 'description_chars', length(v_text), 'held', v_shown = v_text, 'evidence_id', i.evidence_id, 'actor', p_actor);
end $$;


ALTER FUNCTION "security"."layer4_course_description_apply_v1"("p_actor" "uuid", "p_item_id" "uuid", "p_value" "jsonb", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."layer4_course_description_apply_v1"("p_actor" "uuid", "p_item_id" "uuid", "p_value" "jsonb", "p_reason" "text") IS 'CF-247 Workstream C (3 Nov 2026): a Layer 4 approval of a course description, as read (never edited), writes catalogue.courses.description when it is unchanged since the proposal and not locked.';



CREATE OR REPLACE FUNCTION "security"."layer4_course_english_apply_impl"("p_actor" "uuid", "p_item_id" "uuid", "p_value" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_item pipeline.layer4_review_items%rowtype; x jsonb; v_test uuid; v_n int := 0; v_src uuid;
begin
  select * into v_item from pipeline.layer4_review_items where id = p_item_id;
  if v_item.entity_type <> 'course' then raise exception 'English requirements apply to courses only'; end if;
  if jsonb_typeof(p_value->'english_requirements') <> 'array' or jsonb_array_length(p_value->'english_requirements') = 0 then
    raise exception 'enter at least one English test score, then approve';
  end if;
  select id into v_src from pipeline.sources where source_type = 'layer4_human_review' limit 1;
  for x in select e from jsonb_array_elements(p_value->'english_requirements') e loop
    select id into v_test from ref.english_tests where code = upper(btrim(coalesce(x->>'test_code', x->>'test')));
    if v_test is null then raise exception 'unknown English test %', coalesce(x->>'test_code', x->>'test'); end if;
    if coalesce(x->>'overall_score', x->>'overall', '') !~ '^[0-9]+(\.[0-9]+)?$' then raise exception 'enter an overall score for %', coalesce(x->>'test_code', x->>'test'); end if;
    insert into catalogue.course_english_requirements(course_id, english_test_id, overall_score, component_scores, notes, source_id, evidence_id, confidence,
                                                      source_requirement_key, status, last_verified_at)
    values (v_item.entity_id, v_test, coalesce(x->>'overall_score', x->>'overall')::numeric, coalesce(x->'component_scores', x->'components', '{}'::jsonb),
            'Layer 4 decision: ' || p_reason, v_src, v_item.evidence_id, 1, 'l4:' || v_item.id || ':' || lower(coalesce(x->>'test_code', x->>'test')), 'active', now())
    on conflict (course_id, english_test_id) do update set overall_score = excluded.overall_score, component_scores = excluded.component_scores, notes = excluded.notes,
           source_id = excluded.source_id, evidence_id = excluded.evidence_id, confidence = 1, source_requirement_key = excluded.source_requirement_key,
           status = 'active', last_verified_at = now();
    v_n := v_n + 1;
  end loop;
  insert into pipeline.manual_locks(entity, entity_id, field, mode, set_by) values ('course', v_item.entity_id, 'english', 'value', p_actor)
  on conflict (entity, entity_id, field) do update set mode = excluded.mode, set_by = excluded.set_by, set_at = now();
  perform search.refresh_course_enrichment_scoped_v1(array[v_item.entity_id], true);
  return jsonb_build_object('tests_written', v_n, 'search_refreshed', true);
end $_$;


ALTER FUNCTION "security"."layer4_course_english_apply_impl"("p_actor" "uuid", "p_item_id" "uuid", "p_value" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_course_link_apply_impl"("p_actor" "uuid", "p_item_id" "uuid", "p_value" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'pipeline', 'search'
    AS $_$
declare v_item pipeline.layer4_review_items%rowtype; v_url text; v_host text; v_link uuid; v_retired int := 0;
begin
  select * into v_item from pipeline.layer4_review_items where id=p_item_id;
  if v_item.entity_type<>'course' then raise exception 'course links apply to courses only'; end if;
  -- CF-247 17 Oct 2026: the proposed page may be stored as url or course_url
  v_url := btrim(coalesce(case jsonb_typeof(p_value) when 'string' then p_value#>>'{}' when 'object' then coalesce(p_value->>'url', p_value->>'course_url') end,
                          case jsonb_typeof(v_item.proposed_value) when 'string' then v_item.proposed_value#>>'{}' when 'object' then coalesce(v_item.proposed_value->>'url', v_item.proposed_value->>'course_url') end,''));
  if v_url='' then raise exception 'enter the official course page link, then approve'; end if;
  if v_url !~* '^https://[a-z0-9.-]+\.[a-z]{2,}(/[^\s]*)?$' then raise exception 'the link must be a full https:// web address'; end if;
  v_host := lower(substring(v_url from '^https://([^/]+)'));
  if security.reference_url_has_use(v_url, 'not_course_page') then
    raise exception 'use the provider''s own course page, not a search, social or course-listing site (%)', v_host;
  end if;
  -- E15 (Platform Admin 1 Nov 2026 22:01): a page set by hand is changed on the course record; the lock guard skipped this row silently
  if exists (select 1 from pipeline.manual_locks l where l.entity='course' and l.entity_id=v_item.entity_id and l.field in ('official_url','course_url')) then
    raise exception 'this course''s page was set by hand on the course record: change it there (course detail, official page), or keep the page we hold';
  end if;
  -- E15: the approved page replaces the course's other official pages (inactive, kept for history), so the course has one course page
  update catalogue.course_links set status='inactive',is_primary=false,updated_at=now()
   where course_id=v_item.entity_id and link_type='official_course' and status='active' and url<>v_url;
  get diagnostics v_retired = row_count;
  insert into catalogue.course_links(course_id,link_type,url,audience,label,is_primary,status,source_id,evidence_id,confidence,last_verified_at,updated_at)
  values (v_item.entity_id,'official_course',v_url,'international','Official provider course page (confirmed by reviewer)',true,'active',(select id from pipeline.sources where source_type='layer4_human_review' limit 1),v_item.evidence_id,1,now(),now())
  on conflict(course_id,link_type,url) do update set label=excluded.label,status='active',is_primary=true,source_id=excluded.source_id,confidence=1,last_verified_at=now(),updated_at=now()
  returning id into v_link;
  -- E15: a guard that skips the row leaves no link; the decision is refused rather than recorded as applied
  if v_link is null then raise exception 'the course page was not saved (a guard on the course''s links refused it); nothing was changed'; end if;
  -- E15: the course record follows the approved page, as a page set on the course record does
  update catalogue.courses set course_url=v_url,updated_at=now() where id=v_item.entity_id and course_url is distinct from v_url;
  perform search.refresh_course_enrichment_scoped_v1(array[v_item.entity_id], true);
  return jsonb_build_object('course_link_id',v_link,'url',v_url,'search_refreshed',true,'superseded_links',v_retired);
end $_$;


ALTER FUNCTION "security"."layer4_course_link_apply_impl"("p_actor" "uuid", "p_item_id" "uuid", "p_value" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_course_link_refusal_check_v1"("p_item" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("item_id" "uuid", "course_id" "uuid", "reason_group" "text", "page_url" "text", "audit_sample" boolean, "pass" boolean, "reasons" "text"[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with it as (
    select i.id, i.entity_id, i.claimed_at, i.assigned_to, i.escalation_reason r,
           security.layer4_item_page_v1(i.field_code, i.proposed_value, i.layer2_state) url
      from pipeline.layer4_review_items i
     where i.status = 'pending' and i.field_code = 'official_course_url' and i.entity_type = 'course'
       and i.escalation_reason like 'The page found automatically was not linked: %'
       and (p_item is null or i.id = p_item)),
  g as (
    select it.*,
           case when it.r ilike any (array['%the page address is another course''s at this provider%', '%the page address or title shows another course''s code%',
                                           '%the page is another programme''s page%']) then 'A'
                when it.r ilike '%the page is for another qualification level%' then 'B'
                when it.r ilike '%the page is for another version of the award%' then 'C'
                when it.r ilike any (array['%the page is the % handbook entry%', '%the page is another award or an older handbook year%']) then 'D'
                when it.r ilike '%the page is for another campus%' then 'E' end grp,
           security.layer4_url_key_v1(it.url) k
      from it),
  e as (
    select g.*, c.lifecycle_status,
           exists (select 1 from pipeline.page_rejections pr where pr.course_id = g.entity_id and security.layer4_url_key_v1(pr.url) = g.k) refused,
           exists (select 1 from catalogue.course_links l where l.course_id = g.entity_id and l.link_type = 'official_course' and l.status = 'active'
                      and security.layer4_url_key_v1(l.url) = g.k) live,
           exists (select 1 from pipeline.manual_locks ml where ml.entity = 'course' and ml.entity_id = g.entity_id and ml.field in ('official_url', 'course_url')) locked,
           exists (select 1 from pipeline.layer4_review_owners o where o.provider_id = c.provider_id and o.field_code = 'official_course_url'
                      and o.owner = 'chatgpt' and o.closed_at is null) parallel
      from g join catalogue.courses c on c.id = g.entity_id
     where g.grp is not null),
  v as (
    select e.*,
           -- fixed: 28 bits of the item id's md5 choose the audit sample (stable for the item; the share itself is the setting)
           (('x' || substr(md5(e.id::text), 1, 7))::bit(28)::int % 100) < security.pipeline_num_v1('layer4.link_refusal_audit_pct', 5) aud,
           array_remove(array[
             case when e.claimed_at is not null or e.assigned_to is not null then 'claimed by a reviewer' end,
             case when e.url is null then 'no proposed page' end,
             case when e.lifecycle_status is distinct from 'active' then 'course not active' end,
             case when not e.refused then 'the finder''s refusal of this page is not recorded for the course' end,
             case when e.live then 'the proposed page is the course''s active official page (a person decides)' end,
             case when e.locked then 'manual lock on the official page' end,
             case when e.parallel then 'university owned by the parallel reviewer (ownership register)' end], null) why
      from e)
  select v.id, v.entity_id, v.grp, v.url, v.aud, coalesce(cardinality(v.why), 0) = 0, v.why from v order by v.id
$$;


ALTER FUNCTION "security"."layer4_course_link_refusal_check_v1"("p_item" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."layer4_course_link_refusal_check_v1"("p_item" "uuid") IS 'CF-247 rule l4-link-refusal-v1 (Platform Admin 16 Nov 2026 16:47 AEDT): for each waiting official_course_url item whose hold reason names negative evidence (another course, level, award version, handbook year or campus), whether the rule may close it, its reason group, whether it is in the audit sample, and why not. Read only.';



CREATE OR REPLACE FUNCTION "security"."layer4_course_link_refusal_rule_v1"("p_limit" integer, "p_apply" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v record; w record; v_run bigint; v_res jsonb; v_reason text; v_prev text; v_lock int;
        v_n int := 0; v_ok int := 0; v_would int := 0; v_aud int := 0; v_fail int := 0; v_left int := 0; v_by jsonb := '{}'::jsonb; v_grp jsonb := '{}'::jsonb; v_why text;
        v_sys uuid := 'c0ffee00-0000-4000-8000-000000000150';  -- fixed: the system automation account that records rule decisions (Decision 263)
        v_caller uuid := auth.uid(); v_t0 timestamptz := clock_timestamp();
        v_on boolean := security.pipeline_num_v1('layer4.link_refusal_rule_on', 0) >= 1;
        v_batch int := least(greatest(coalesce(p_limit, 0), 0), security.pipeline_num_v1('layer4.link_refusal_batch', 200)::int);
        v_budget numeric := security.pipeline_num_v1('layer4.link_refusal_time_budget_s', 7);
        v_ref text := 'Platform Admin 16 Nov 2026 16:47 AEDT (report docs/platform/layer4-clearance-and-model-benchmark-2026-11-16.md section 3.2 option 1)';
        v_label jsonb := '{"A": "another course''s page", "B": "another qualification level", "C": "another version of the award", "D": "an older handbook year", "E": "another campus"}'::jsonb;
begin
  if v_caller is not null and coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  if coalesce(p_apply, false) and not v_on then raise exception 'layer4.link_refusal_rule_on is 0: the rule only counts' using errcode = 'P0001'; end if;
  insert into pipeline.layer4_link_refusal_runs(apply, invoked_by, approval_ref) values (coalesce(p_apply, false), v_caller, v_ref) returning id into v_run;
  for v in select c.item_id from security.layer4_course_link_refusal_check_v1(null) c
            where c.pass and not exists (select 1 from pipeline.layer4_link_refusal_run_items ri join pipeline.layer4_link_refusal_runs rr on rr.id = ri.run_id
                                          where ri.item_id = c.item_id and ri.outcome = 'audit_sample' and rr.apply)
            order by c.audit_sample desc, c.item_id limit v_batch loop
    if clock_timestamp() - v_t0 > make_interval(secs => v_budget) then v_left := v_left + 1; continue; end if;
    v_n := v_n + 1;
    begin
      begin
        select 1 into v_lock from pipeline.layer4_review_items i where i.id = v.item_id and i.status = 'pending' for update nowait;
      exception when lock_not_available then
        raise exception using errcode = 'P0001', message = 'l4lr:another reviewer is deciding this item';
      end;
      if v_lock is null then raise exception using errcode = 'P0001', message = 'l4lr:no longer waiting'; end if;
      v_lock := null;
      w := null;
      select x.item_id, x.course_id, x.reason_group, x.page_url, x.audit_sample, x.pass, x.reasons into w from security.layer4_course_link_refusal_check_v1(v.item_id) x;
      if w.item_id is null then raise exception using errcode = 'P0001', message = 'l4lr:no longer in the rule''s scope'; end if;
      if not w.pass then raise exception using errcode = 'P0001', message = 'l4lr:' || array_to_string(w.reasons, '; '); end if;
      v_grp := jsonb_set(v_grp, array[w.reason_group], to_jsonb(coalesce((v_grp->>w.reason_group)::int, 0) + 1));
      if w.audit_sample then
        insert into pipeline.layer4_link_refusal_run_items(run_id, item_id, course_id, reason_group, outcome) values (v_run, v.item_id, w.course_id, w.reason_group, 'audit_sample');
        if coalesce(p_apply, false) then
          update pipeline.layer4_review_items set change_control_ref = coalesce(change_control_ref || '; ', '') || 'audit sample of rule l4-link-refusal-v1 (a person decides)'
           where id = v.item_id and status = 'pending';
        end if;
        v_aud := v_aud + 1;
        continue;
      end if;
      if not coalesce(p_apply, false) then
        insert into pipeline.layer4_link_refusal_run_items(run_id, item_id, course_id, reason_group, outcome) values (v_run, v.item_id, w.course_id, w.reason_group, 'would_decide');
        v_would := v_would + 1;
        continue;
      end if;
      v_reason := left(format('[rule l4-link-refusal-v1] Refuse this proposal: the course-link finder showed this page is for %s, and its refusal for this course is on record. Nothing is linked; any page the course holds stays. Approved by %s',
                              v_label->>w.reason_group, v_ref), 1000);
      v_prev := current_setting('request.jwt.claim.sub', true);
      perform set_config('request.jwt.claim.sub', v_sys::text, true);
      begin
        v_res := security.layer4_course_link_refuse_v1(v.item_id, v_reason);
      exception when others then
        perform set_config('request.jwt.claim.sub', coalesce(v_prev, ''), true);
        raise;
      end;
      perform set_config('request.jwt.claim.sub', coalesce(v_prev, ''), true);
      insert into pipeline.layer4_link_refusal_run_items(run_id, item_id, course_id, reason_group, outcome, decision_id)
      values (v_run, v.item_id, w.course_id, w.reason_group, 'decided', nullif(v_res->>'decision_id', '')::uuid);
      v_ok := v_ok + 1;
    exception when others then
      v_why := case when sqlerrm like 'l4lr:%' then substr(sqlerrm, 6) else 'decision refused: ' || left(sqlerrm, 300) end;
      insert into pipeline.layer4_link_refusal_run_items(run_id, item_id, outcome, reasons) values (v_run, v.item_id, 'failed', string_to_array(v_why, '; '))
      on conflict (run_id, item_id) do update set outcome = 'failed', reasons = excluded.reasons, decision_id = null;
      v_by := jsonb_set(v_by, array[left(v_why, 120)], to_jsonb(coalesce((v_by->>left(v_why, 120))::int, 0) + 1));
      v_fail := v_fail + 1;
    end;
  end loop;
  update pipeline.layer4_link_refusal_runs set examined = v_n, decided = v_ok, would_decide = v_would, audit_sample = v_aud, failed = v_fail,
         result = jsonb_build_object('by_group', v_grp, 'failed_by_reason', v_by, 'not_reached', v_left, 'seconds', round(extract(epoch from clock_timestamp() - v_t0)::numeric, 1))
   where id = v_run;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('layer4', case when coalesce(p_apply, false) then 'rule_execute' else 'rule_count' end, 'l4-link-refusal-v1',
          jsonb_build_object('run_id', v_run, 'examined', v_n, 'decided', v_ok, 'would_decide', v_would, 'audit_sample', v_aud, 'failed', v_fail, 'not_reached', v_left,
                             'by_group', v_grp, 'failed_by_reason', v_by, 'approval_ref', v_ref), v_caller);
  return jsonb_build_object('run_id', v_run, 'rule', 'l4-link-refusal-v1', 'apply', coalesce(p_apply, false), 'examined', v_n, 'decided', v_ok, 'would_decide', v_would,
                            'audit_sample', v_aud, 'failed', v_fail, 'not_reached', v_left, 'by_group', v_grp, 'failed_by_reason', v_by);
end $$;


ALTER FUNCTION "security"."layer4_course_link_refusal_rule_v1"("p_limit" integer, "p_apply" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."layer4_course_link_refusal_rule_v1"("p_limit" integer, "p_apply" boolean) IS 'CF-247 rule l4-link-refusal-v1 (Platform Admin 16 Nov 2026 16:47 AEDT, report section 3.2 option 1): closes waiting official_course_url items the course-link finder already refused on negative evidence, through Refuse this proposal under the system automation account; the audit sample stays for a person. p_apply false counts only; apply needs layer4.link_refusal_rule_on.';



CREATE OR REPLACE FUNCTION "security"."layer4_course_link_refuse_v1"("p_item" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_review_items; v_url text;
begin
  select * into i from pipeline.layer4_review_items where id = p_item;
  if i.id is null or i.status <> 'pending' then raise exception 'this item is no longer waiting (someone may have decided it)'; end if;
  if i.field_code <> 'official_course_url' or i.entity_type <> 'course' then raise exception 'this item is a fee, not a proposed page: use its own choices'; end if;
  v_url := security.layer4_item_page_v1(i.field_code, i.proposed_value, i.layer2_state);
  if v_url is not null then
    insert into pipeline.page_rejections(course_id, url, provider_id, evidence_id, source, reason, signals, rejected_by)
    select i.entity_id, v_url, c.provider_id, i.evidence_id, 'layer4_refuse', left(p_reason, 500), jsonb_build_object('review_item_id', i.id), auth.uid()
      from catalogue.courses c where c.id = i.entity_id
    on conflict (course_id, url) do nothing;
  end if;
  return public.layer4_review_decide(p_item, 'reject', p_reason, null);
end $$;


ALTER FUNCTION "security"."layer4_course_link_refuse_v1"("p_item" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_course_link_rule_execute_v1"("p_rule" "text", "p_limit" integer, "p_apply" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.layer4_course_link_rules; v record; w record; v_run bigint; v_res jsonb; v_reason text; v_prev text; v_n int := 0; v_ok int := 0; v_would int := 0; v_fail int := 0;
        v_sys uuid := 'c0ffee00-0000-4000-8000-000000000150';  -- fixed: the system automation account that records Decision 263 rule decisions
        v_caller uuid := auth.uid(); v_lock int; v_by jsonb := '{}'::jsonb; v_why text; v_t0 timestamptz := clock_timestamp(); v_left int := 0;
begin
  if v_caller is not null and coalesce(security.current_role_rank(), 0) < 6 then raise exception 'Platform Admin role required' using errcode = '42501'; end if;
  select * into r from pipeline.layer4_course_link_rules where code = p_rule;
  if r.code is null then raise exception 'no approved rule %', p_rule using errcode = 'P0002'; end if;
  insert into pipeline.layer4_course_link_rule_runs(rule, apply, invoked_by, approval_ref) values (r.code, coalesce(p_apply, false), v_caller, r.approval_ref) returning id into v_run;
  -- the rule's waiting items, ids only (validation is per item, below): items no run of this rule has looked at first, then the longest since
  for v in select i.id item_id from pipeline.layer4_review_items i join catalogue.courses c on c.id = i.entity_id
            where c.provider_id = r.provider_id and i.status = 'pending' and i.field_code = 'official_course_url' and i.escalation_reason ilike r.reason_like
            order by (select max(ri.at) from pipeline.layer4_course_link_rule_run_items ri join pipeline.layer4_course_link_rule_runs rr on rr.id = ri.run_id
                       where ri.item_id = i.id and rr.rule = r.code) asc nulls first, i.id
            limit least(greatest(coalesce(p_limit, 0), 0), security.pipeline_num_v1('layer4.rule_execute_batch', 50)::int) loop
    -- the call's time budget: items not reached stay waiting and come first next time
    if clock_timestamp() - v_t0 > make_interval(secs => security.pipeline_num_v1('layer4.rule_execute_time_budget_s', 5)) then v_left := v_left + 1; continue; end if;
    v_n := v_n + 1;
    begin
      -- the item, locked for this decision; one another reviewer holds is skipped
      begin
        select 1 into v_lock from pipeline.layer4_review_items i where i.id = v.item_id and i.status = 'pending' for update nowait;
      exception when lock_not_available then
        raise exception using errcode = 'P0001', message = 'l4rule:another reviewer is deciding this item';
      end;
      if v_lock is null then raise exception using errcode = 'P0001', message = 'l4rule:no longer waiting'; end if;
      v_lock := null;
      -- validated again, on its own, now
      w := null;
      select x.item_id, x.pass, x.reasons, x.course_id, x.target_url, x.proposed_url into w from security.layer4_course_link_rule_validate_v1(r.code, v.item_id) x;
      if w.item_id is null then raise exception using errcode = 'P0001', message = 'l4rule:no longer in the rule''s scope'; end if;
      if not w.pass then raise exception using errcode = 'P0001', message = 'l4rule:' || array_to_string(w.reasons, '; '); end if;
      if not coalesce(p_apply, false) then
        insert into pipeline.layer4_course_link_rule_run_items(run_id, item_id, course_id, outcome, action) values (v_run, v.item_id, w.course_id, 'would_decide',
               case when r.choice = 'keep' then 'reject' when w.target_url is distinct from w.proposed_url then 'edit_and_approve' else 'approve' end);
        v_would := v_would + 1;
        continue;
      end if;
      v_reason := left(format('[rule %s] %s. %s: %s. Approved by %s (%s)', r.code,
                              case r.choice when 'keep' then 'Keep the page we hold' else 'Use the new page' end, 'Decision 263 logged rule, validated item by item',
                              coalesce(w.target_url, ''), r.approved_by, r.approval_ref), 1000);
      -- the existing decision path, under the system automation account (Decision 263), then the caller's identity again
      v_prev := current_setting('request.jwt.claim.sub', true);
      perform set_config('request.jwt.claim.sub', v_sys::text, true);
      begin
        -- the address the validator returned is the one written: an edited approval when it differs from the proposed value (http:// given https://)
        v_res := security.layer4_review_decide_impl(v.item_id,
                   case when r.choice = 'keep' then 'reject' when w.target_url is distinct from w.proposed_url then 'edit_and_approve' else 'approve' end, v_reason,
                   case when r.choice <> 'keep' and w.target_url is distinct from w.proposed_url then jsonb_build_object('course_url', w.target_url) end);
      exception when others then
        perform set_config('request.jwt.claim.sub', coalesce(v_prev, ''), true);
        raise;
      end;
      perform set_config('request.jwt.claim.sub', coalesce(v_prev, ''), true);
      insert into pipeline.layer4_course_link_rule_run_items(run_id, item_id, course_id, outcome, decision_id, action)
      values (v_run, v.item_id, w.course_id, 'decided', nullif(v_res->>'decision_id', '')::uuid, v_res->>'action');
      v_ok := v_ok + 1;
    exception when others then
      v_why := case when sqlerrm like 'l4rule:%' then substr(sqlerrm, 8) else 'decision refused: ' || left(sqlerrm, 300) end;
      insert into pipeline.layer4_course_link_rule_run_items(run_id, item_id, outcome, reasons) values (v_run, v.item_id, 'failed', string_to_array(v_why, '; '))
      on conflict (run_id, item_id) do update set outcome = 'failed', reasons = excluded.reasons, decision_id = null, action = null;
      v_by := jsonb_set(v_by, array[left(v_why, 120)], to_jsonb(coalesce((v_by->>left(v_why, 120))::int, 0) + 1));
      v_fail := v_fail + 1;
    end;
  end loop;
  update pipeline.layer4_course_link_rule_runs set examined = v_n, decided = v_ok, would_decide = v_would, failed = v_fail,
         result = jsonb_build_object('failed_by_reason', v_by, 'not_reached', v_left, 'seconds', round(extract(epoch from clock_timestamp() - v_t0)::numeric, 1)) where id = v_run;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('layer4', case when coalesce(p_apply, false) then 'rule_execute' else 'rule_count' end, r.code,
          jsonb_build_object('run_id', v_run, 'examined', v_n, 'decided', v_ok, 'would_decide', v_would, 'failed', v_fail, 'not_reached', v_left, 'failed_by_reason', v_by, 'approval_ref', r.approval_ref), v_caller);
  return jsonb_build_object('run_id', v_run, 'rule', r.code, 'apply', coalesce(p_apply, false), 'examined', v_n, 'decided', v_ok, 'would_decide', v_would, 'failed', v_fail, 'not_reached', v_left,
                            'failed_by_reason', v_by, 'approval_ref', r.approval_ref);
end $$;


ALTER FUNCTION "security"."layer4_course_link_rule_execute_v1"("p_rule" "text", "p_limit" integer, "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_course_link_rule_validate_v1"("p_rule" "text", "p_item" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("rule" "text", "item_id" "uuid", "course_id" "uuid", "course_code" "text", "choice" "text", "held_url" "text", "proposed_url" "text", "target_url" "text", "pass" boolean, "reasons" "text"[], "detail" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  with rule as (select * from pipeline.layer4_course_link_rules r where r.code = p_rule),
  own as (select bool_or(o.owner = 'claude') claude, bool_or(o.owner = 'chatgpt') chatgpt from pipeline.layer4_review_owners o, rule
           where o.provider_id = rule.provider_id and o.field_code = 'official_course_url' and o.closed_at is null),
  it as (
    select i.id item_id, i.entity_id course_id, i.claimed_at, i.assigned_to, i.status, i.before_value, i.layer2_state, i.escalation_reason,
           security.layer4_url_key_v1(case when jsonb_typeof(i.before_value) = 'array' then i.before_value->>0 end) held_key,
           case when jsonb_typeof(i.before_value) = 'array' then i.before_value->>0 end held_url,
           security.layer4_url_key_v1(coalesce(i.proposed_value->>'course_url', i.proposed_value->>'url')) prop_key,
           coalesce(i.proposed_value->>'course_url', i.proposed_value->>'url') prop_url,
           case when jsonb_typeof(i.before_value) = 'array' then jsonb_array_length(i.before_value) else 0 end n_held
      from pipeline.layer4_review_items i join catalogue.courses c on c.id = i.entity_id join rule on c.provider_id = rule.provider_id
     where i.status = 'pending' and i.field_code = 'official_course_url' and i.escalation_reason ilike rule.reason_like and (p_item is null or i.id = p_item)),
  m as (
    select it.*, rule.code, rule.choice, rule.identity_bases, rule.strict,
           it.held_key ~ rule.held_regex and it.prop_key = regexp_replace(it.held_key, rule.held_regex, rule.proposed_replace) pattern_ok,
           case when rule.choice = 'keep' then it.held_url else it.prop_url end target_url,
           case when rule.choice = 'keep' then it.held_key else it.prop_key end target_key
      from it cross join rule),
  e as materialized (
    select m.*, c.lifecycle_status, c.course_code, c.open_to_international, k.iso_alpha2 country,
           (select jsonb_build_object('id', ev.id, 'captured_at', ev.captured_at, 'course_id', ev.metadata->>'course_id', 'identity_basis', ev.metadata->>'identity_basis')
              from pipeline.evidence_artifacts ev
             where lower(ev.source_url) = any (array['https://' || m.target_key, 'https://' || m.target_key || '/', 'https://www.' || m.target_key, 'https://www.' || m.target_key || '/',
                                                     'http://' || m.target_key, 'http://' || m.target_key || '/', 'http://www.' || m.target_key, 'http://www.' || m.target_key || '/'])
             order by (ev.metadata->>'course_id' = m.course_id::text) desc, ev.captured_at desc nulls last limit 1) copy,
           (select array_agg(security.layer4_url_key_v1(l.url) order by l.url) from catalogue.course_links l
             where l.course_id = m.course_id and l.link_type = 'official_course' and l.status = 'active') active_keys,
           (select g.basis from pipeline.coverage_course_pages g where g.course_id = m.course_id) binding_basis,
           exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = m.course_id and l.field in ('official_url', 'course_url')) locked,
           exists (select 1 from pipeline.page_rejections r where r.course_id = m.course_id and security.layer4_url_key_v1(r.url) = m.target_key) target_refused,
           case when m.strict then security.layer4_rule_level_v1(m.course_id, m.target_url) end chk
      from m join catalogue.courses c on c.id = m.course_id
      left join catalogue.providers p on p.id = c.provider_id left join ref.countries k on k.id = p.country_id),
  lv as (
    select e.*,
           coalesce((select array_agg(x) from jsonb_array_elements_text(case when jsonb_typeof(e.chk->'checks'->'course_levels') = 'array' then e.chk->'checks'->'course_levels' else '[]'::jsonb end) x), '{}') course_lv,
           coalesce((select array_agg(x) from jsonb_array_elements_text(case when jsonb_typeof(e.chk->'checks'->'page_levels') = 'array' then e.chk->'checks'->'page_levels' else '[]'::jsonb end) x), '{}') page_lv
      from e),
  v as (
    select lv.*, array_remove(array[
             case when lv.claimed_at is not null or lv.assigned_to is not null then 'claimed by a reviewer' end,
             case when coalesce((select chatgpt from own), false) then 'university owned by the parallel reviewer (ownership register)' end,
             case when not coalesce((select claude from own), false) then 'no ownership row for the Integration Controller (ownership register)' end,
             case when lv.n_held <> 1 then 'not exactly one page held (' || lv.n_held || ')' end,
             case when not coalesce(lv.pattern_ok, false) then 'addresses do not follow the approved pattern' end,
             case when lv.lifecycle_status is distinct from 'active' then 'course not active' end,
             case when lv.copy is null then 'no stored copy of the ' || case when lv.choice = 'keep' then 'held' else 'proposed' end || ' page' end,
             case when lv.copy is not null and lv.copy->>'course_id' is distinct from lv.course_id::text then 'stored copy was read for another course' end,
             case when lv.copy is not null and not (coalesce(lv.copy->>'identity_basis', '') = any (lv.identity_bases)) then 'stored copy identity basis ' || coalesce(lv.copy->>'identity_basis', 'none') || ' is not an exact-course basis' end,
             case when lv.open_to_international is false then 'course not open to international students' end,
             case when lv.country = 'AU' and coalesce(lv.course_code, '') !~ '^[0-9]{6}[0-9A-Z]$' then 'no CRICOS code on the course record' end,
             case when lv.active_keys is distinct from array[lv.held_key] then 'active official page is no longer exactly the held page' end,
             case when lv.binding_basis = 'manual' then 'page binding was set by hand' end,
             case when lv.locked then 'manual lock on the official page' end,
             case when lv.choice = 'use' and lv.target_refused then 'the proposed page was refused for this course' end,
             case when lv.strict and (cardinality(lv.course_lv) = 0 or cardinality(lv.page_lv) = 0 or not (lv.course_lv && lv.page_lv))
                  then 'course level not verified on the page (course ' || coalesce(nullif(array_to_string(lv.course_lv, ','), ''), 'unknown') || ', page ' || coalesce(nullif(array_to_string(lv.page_lv, ','), ''), 'none') || ')' end,
             case when lv.strict and lv.copy is not null and (lv.copy->>'captured_at')::timestamptz < now() - make_interval(days => security.pipeline_num_v1('layer4.rule_evidence_max_age_days', 90)::int)
                  then 'stored copy is older than ' || security.pipeline_num_v1('layer4.rule_evidence_max_age_days', 90) || ' days' end,
             -- fixed: the course-link apply's own address rule (security.layer4_course_link_apply_impl), checked before any decision
             case when lv.choice = 'use' and regexp_replace(coalesce(lv.target_url, ''), '^(https?://)?', 'https://', 'i') !~* '^https://[a-z0-9.-]+\.[a-z]{2,}(/[^\s]*)?$'
                  then 'the proposed page is not a full web address (' || coalesce(lv.target_url, 'none') || ')' end], null) reasons
      from lv)
  select v.code, v.item_id, v.course_id, v.course_code, v.choice, v.held_url, v.prop_url, case when v.choice = 'use' then regexp_replace(v.target_url, '^(https?://)?', 'https://', 'i') else v.target_url end, coalesce(cardinality(v.reasons), 0) = 0, v.reasons,
         jsonb_build_object('stored_copy', v.copy, 'active_pages', to_jsonb(v.active_keys), 'binding_basis', v.binding_basis, 'country', v.country, 'claimed_at', v.claimed_at,
                            'course_levels', to_jsonb(v.course_lv), 'page_levels', to_jsonb(v.page_lv), 'page_check', v.chk->>'verdict')
    from v order by v.course_code, v.item_id
$_$;


ALTER FUNCTION "security"."layer4_course_link_rule_validate_v1"("p_rule" "text", "p_item" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_course_scalar_resolve_impl"("p_actor" "uuid", "p_course_id" "uuid", "p_field_code" "text", "p_value" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'pipeline', 'auth'
    AS $$
declare v_overlay jsonb; v_prior jsonb; v_prev_id uuid; v_resolution_id uuid;
begin
  if p_field_code not in ('course_description','official_course_url','delivery_mode','duration') then
    raise exception 'field is not enabled for scalar Layer 4 editing' using errcode='22023';
  end if;
  v_prior:=security.layer4_underlying_value('course',p_course_id,p_field_code);
  v_overlay:=security.layer4_override_apply_impl(
    p_actor,'course',p_course_id,p_field_code,p_value,'human_resolution',p_reason,'{}'::uuid[],'{}'::jsonb
  );
  select id into v_prev_id from pipeline.layer4_course_field_resolutions
   where course_id=p_course_id and field_code=p_field_code and status='applied'
   order by created_at desc limit 1;
  if v_prev_id is not null then
    update pipeline.layer4_course_field_resolutions set status='superseded' where id=v_prev_id;
  end if;
  insert into pipeline.layer4_course_field_resolutions(
    course_id,field_code,prior_value,resolved_value,resolution_reason,actor_id,supersedes_id
  ) values (
    p_course_id,p_field_code,v_prior,p_value,trim(p_reason),p_actor,v_prev_id
  ) returning id into v_resolution_id;
  return v_overlay||jsonb_build_object('resolution_id',v_resolution_id,'legacy_resolution_bridge',true,'canonical_changed',false,'search_changed',false);
end $$;


ALTER FUNCTION "security"."layer4_course_scalar_resolve_impl"("p_actor" "uuid", "p_course_id" "uuid", "p_field_code" "text", "p_value" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_decide_guard_v1"("p_kind" "text", "p_ref" "text", "p_choice" "text", "p_pid" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare e record; v_upd timestamptz;
begin
  select x.id, x.created_at into e from pipeline.admin_control_events x
   where x.area = 'layer4' and x.action = 'inbox_decide' and x.target = p_kind || ':' || p_ref and x.detail->>'choice' = p_choice
     and x.created_at > now() - make_interval(secs => security.pipeline_num_v1('layer4.duplicate_decision_seconds', 120)::int)
     and coalesce(x.detail->'result'->>'still_waiting', 'false') <> 'true'
   order by x.id desc limit 1;
  if e.id is not null then
    return jsonb_build_object('repeat', true, 'existing', jsonb_build_object('event', e.id, 'at', e.created_at),
      'request', 'Already sent: the same decision was recorded at ' || (security.l4_time_v1(e.created_at)->>'text') || ' (audit #' || e.id || '); it was not taken again.');
  end if;
  if p_choice = any (security.pipeline_list_v1('layer4.once_only_choices', '["retry", "rebuild", "release"]'::jsonb)) and p_pid is not null then
    select x.id, x.created_at into e from pipeline.admin_control_events x
     where x.area = 'layer4' and x.action = 'inbox_decide' and x.detail->>'kind' = p_kind and x.detail->>'choice' = p_choice and x.detail->>'provider_id' = p_pid::text
     order by x.id desc limit 1;
    select p.updated_at into v_upd from catalogue.providers p where p.id = p_pid;
    if e.id is not null and (v_upd is null or v_upd <= e.created_at) then
      return jsonb_build_object('refused', 'already tried on this stop', 'repeat_of', e.id,
        'request', 'Not tried again: ' || replace(p_choice, '_', ' ') || ' was already taken for this university at ' || (security.l4_time_v1(e.created_at)->>'text') || ' (audit #' || e.id
                   || ') and it stopped the same way; nothing about the university has changed since. It is tried at most once.',
        'alternative', case p_kind when 'nothing_ready' then 'Open the adapter in the builder to correct its patterns and qualify again, or CRICOS data only'
                                   when 'onboarding_failed' then 'Build by hand in the adapter builder'
                                   when 'pages_not_found' then 'Add page addresses in the builder, or change the website'
                                   else 'Choose another action, or leave the item with its reason' end);
    end if;
  end if;
  return null;
end $$;


ALTER FUNCTION "security"."layer4_decide_guard_v1"("p_kind" "text", "p_ref" "text", "p_choice" "text", "p_pid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_decision_outcome_v1"("p_kind" "text", "p_choice" "text", "p_result" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_status text := p_result->>'status'; v_rows jsonb; v_aer jsonb; v_entity uuid; v_url text; v_ok boolean;
begin
  if p_kind = 'aer_review' and p_result ? 'review_item_id' then
    v_aer := public.layer4_aer_review_read((p_result->>'review_item_id')::uuid);
    select jsonb_object_agg(s, n) into v_rows
      from (select case when x->>'status' = 'inactive' and coalesce(x->>'status_reason', '') like 'excluded by %' then 'excluded' else x->>'status' end s, count(*) n
              from jsonb_array_elements(coalesce(v_aer->'rows', '[]'::jsonb)) x group by 1) q;
    v_rows := coalesce(v_rows, '{}'::jsonb);
    return jsonb_build_object('class', case when v_status = 'rejected' then 'reconciled' when coalesce((v_rows->>'active')::int, 0) > 0 then 'admitted'
                                            when coalesce((v_rows->>'proposed')::int, 0) > 0 then 'downstream' else 'pending_check' end,
                              'status', v_status, 'decision_id', p_result->>'decision_id', 'rows', v_rows, 'destination', 'entry_requirements');
  elsif p_result ? 'decision_id' then
    if v_status = 'rejected' then
      return jsonb_build_object('class', 'reconciled', 'status', v_status, 'decision_id', p_result->>'decision_id');
    elsif p_kind = 'course_link' and exists (select 1 from pipeline.layer4_review_items r where r.id = (p_result->>'review_item_id')::uuid
                                                and r.field_code = 'provider_current_tuition_validation') then
      -- SS-016 fee check (1 Nov 2026): the fee written for this review item by security.layer4_tuition_apply_impl
      select jsonb_build_object('amount', f.amount, 'currency', f.currency_code, 'fee_year', f.fee_year, 'basis', f.basis, 'course_fee_id', f.id)
        into v_rows from catalogue.course_fees f
       where f.notes like 'CF-247 Layer 4 human decision; review item ' || (p_result->>'review_item_id') || ';%' and f.status = 'active'
       order by f.updated_at desc limit 1;
      return jsonb_build_object('class', case when v_rows is not null then 'admitted' else 'pending_check' end, 'verified', v_rows is not null,
                                'status', v_status, 'decision_id', p_result->>'decision_id', 'fee', v_rows, 'destination', 'course_fees');
    elsif p_kind = 'course_link' then
      v_url := case jsonb_typeof(p_result->'final_value') when 'string' then p_result->>'final_value' else p_result->'final_value'->>'course_url' end;
      select r.entity_id into v_entity from pipeline.layer4_review_items r where r.id = (p_result->>'review_item_id')::uuid and r.entity_type = 'course';
      v_ok := v_url is not null and exists (select 1 from catalogue.course_links l where l.course_id = v_entity and l.link_type = 'official_course' and l.status = 'active'
                                                  and lower(rtrim(l.url, '/')) = lower(rtrim(v_url, '/')));
      return jsonb_build_object('class', case when v_ok then 'applied' else 'pending_check' end, 'verified', v_ok, 'status', v_status,
                                'decision_id', p_result->>'decision_id', 'value', v_url, 'course_id', v_entity, 'destination', 'course');
    end if;
    return jsonb_build_object('class', 'applied', 'status', v_status, 'decision_id', p_result->>'decision_id');
  elsif p_kind = 'course_link' then  -- a held fee: the page entered is read again; the fee is re-admitted only after that read
    return jsonb_build_object('class', 'downstream', 'note', 'the page is read again; its fee is admitted only after that read');
  elsif p_choice = 'wait' then
    return jsonb_build_object('class', 'deferred');
  elsif p_choice in ('rebuild', 'retry', 'cricos_only', 'website') then
    return jsonb_build_object('class', 'downstream');
  elsif p_choice in ('archive', 'archive_course') then
    return jsonb_build_object('class', 'applied');
  elsif p_kind = 'held_scholarship' then
    return jsonb_build_object('class', case when p_choice = 'publish' then 'admitted' else 'reconciled' end);
  elsif p_choice in ('release', 'keep') then
    return jsonb_build_object('class', 'reconciled', 'note', p_result->>'requeued');
  end if;
  return jsonb_build_object('class', 'reconciled');
end $$;


ALTER FUNCTION "security"."layer4_decision_outcome_v1"("p_kind" "text", "p_choice" "text", "p_result" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."layer4_decision_outcome_v1"("p_kind" "text", "p_choice" "text", "p_result" "jsonb") IS 'UR-06 (1 Nov 2026): what a Layer 4 decision actually did, read back from its destination: admitted, applied, reconciled, downstream, deferred or pending_check; AER row counts; course link verified active.';



CREATE OR REPLACE FUNCTION "security"."layer4_drain_judge_v1"("p_item_id" "uuid", "p_attempts" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_max int := security.pipeline_num_v1('layer4.drain_max_attempts', 3)::int;
        v_own_trigger text[] := array['course_description_first_read', 'course_entry_first_read', 'entry_matrix_first_run', 'entry_matrix_change',
                                      'no_page_first_run', 'conjoint_rule_first_run', 'provider_description',
                                      'official_course_url'];  -- fixed: reviews a person decides (own trigger; v1.0.1: the course's own page is a person's choice)
        v_refused text[] := array['page_refused', 'not_course_page', 'identity_mismatch', 'identity_refused', 'blocked', 'refused_host',
                                  'robots_disallowed'];  -- fixed: page check results that a read again cannot change
        r record; v_page record; v_att int := coalesce(p_attempts, 0);
        v_verdict text; v_action text; v_detail jsonb := null; v_dead boolean := false;
begin
  select i.id, i.entity_type, i.entity_id, i.field_code, i.created_at into r from pipeline.layer4_review_items i where i.id = p_item_id;
  if r.id is null then return null; end if;
  select c.read_status, c.http_status, c.read_at into v_page from pipeline.coverage_course_pages c
   where r.entity_type = 'course' and c.course_id = r.entity_id;
  if exists (select 1 from pipeline.layer4_review_items j where j.entity_type = r.entity_type and j.entity_id = r.entity_id
              and j.field_code is not distinct from r.field_code and j.created_at > r.created_at and j.status in ('pending', 'approved', 'edited_approved')) then
    v_verdict := 'superseded_by_newer'; v_action := 'mark superseded';
  elsif r.entity_type = 'course' and v_page.read_status is not null
        and (v_page.http_status in (404, 410) or (v_page.http_status >= 500 and v_att >= 1)) then  -- fixed: HTTP gone; a 5xx still there after this job's read again
    v_verdict := 'page_gone'; v_action := 'return to Layer 2';
    v_detail := jsonb_build_object('read_status', v_page.read_status, 'http_status', v_page.http_status);
  elsif r.entity_type = 'course' and v_page.read_status is not null and v_page.http_status >= 500 then  -- fixed: HTTP server error
    if v_att >= v_max then v_verdict := 'dead_letter'; v_action := 'none: reads again used up'; v_dead := true;
    else v_verdict := 'read_again'; v_action := 'read the course page again (server error)'; end if;
    v_detail := jsonb_build_object('read_status', v_page.read_status, 'http_status', v_page.http_status);
  elsif r.entity_type = 'course' and v_page.read_status is not null
        and (v_page.read_status = any (v_refused) or v_page.http_status in (401, 403, 406, 429)) then  -- fixed: HTTP refusals (the page exists)
    v_verdict := 'needs_person'; v_action := 'none: the page exists but is refused or is not this course';
    v_detail := jsonb_build_object('page_check', v_page.read_status, 'http_status', v_page.http_status);
  elsif r.entity_type = 'course' and v_page.read_status is not null and (v_page.read_at is null or v_page.read_at < r.created_at) then
    if v_att >= v_max then v_verdict := 'dead_letter'; v_action := 'none: reads again used up'; v_dead := true;
    else v_verdict := 'read_again'; v_action := 'read the course page again'; end if;
  else
    v_verdict := 'needs_person'; v_action := 'none: the page was read again and the item still waits for a person';
  end if;
  if r.field_code = any (v_own_trigger) or r.field_code ilike 'entry%' or r.field_code ilike 'aer%' then
    if v_verdict <> 'needs_person' then v_detail := coalesce(v_detail, '{}'::jsonb) || jsonb_build_object('would', v_verdict); end if;
    v_verdict := 'left_for_person'; v_action := 'none: this review is decided by a person'; v_dead := false;
  end if;
  return jsonb_build_object('verdict', v_verdict, 'action', v_action, 'detail', v_detail, 'dead_letter', v_dead);
end $$;


ALTER FUNCTION "security"."layer4_drain_judge_v1"("p_item_id" "uuid", "p_attempts" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."layer4_drain_judge_v1"("p_item_id" "uuid", "p_attempts" integer) IS 'CF-247 worker v1.0.1: the verdict job layer4-drain records for one pending Layer 4 item, given how many reads again it has asked for. Page gone only for 404/410, or a 5xx still there after a read again; a refused, blocked or wrong page needs a person; official_course_url and the reviews with their own trigger are left for a person. Reads only.';



CREATE OR REPLACE FUNCTION "security"."layer4_drain_tick_v1"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_on boolean := security.pipeline_num_v1('layer4.drain_on', 0) = 1;
        v_age int := security.pipeline_num_v1('layer4.drain_min_age_days', 7)::int;
        v_hours int := security.pipeline_num_v1('layer4.drain_cooldown_hours', 24)::int;
        r record; j jsonb; v_verdict text; v_action text; v_applied boolean; v_attempts int; v_next timestamptz; v_dead timestamptz; v_detail jsonb;
        v_out jsonb := '{}'::jsonb;
begin
  for r in
    select i.id, d.attempts d_attempts
      from pipeline.layer4_review_items i
      left join pipeline.layer4_drain_state d on d.item_id = i.id
     where i.status = 'pending' and i.created_at < now() - make_interval(days => v_age)
       and (d.item_id is null or (d.next_at <= now() and d.dead_letter_at is null))
     order by i.created_at
     limit greatest(1, coalesce(p_limit, 1))
  loop
    v_applied := false; v_attempts := coalesce(r.d_attempts, 0);
    j := security.layer4_drain_judge_v1(r.id, v_attempts);
    v_verdict := j->>'verdict'; v_action := j->>'action'; v_detail := case when jsonb_typeof(j->'detail') = 'object' then j->'detail' end;
    v_dead := case when (j->>'dead_letter')::boolean then now() end;
    v_next := now() + make_interval(hours => v_hours);
    if v_on then
      begin
        if v_verdict = 'superseded_by_newer' then
          update pipeline.layer4_review_items set status = 'superseded', decided_at = now() where id = r.id and status = 'pending';
          v_applied := found;
        elsif v_verdict = 'page_gone' then
          update pipeline.layer4_review_items set status = 'returned_layer2', decided_at = now() where id = r.id and status = 'pending';
          v_applied := found;
        elsif v_verdict = 'read_again' then
          update pipeline.coverage_course_pages c set next_read_at = now()
            from pipeline.layer4_review_items i
           where i.id = r.id and c.course_id = i.entity_id and (c.leased_until is null or c.leased_until < now());
          v_applied := found;
          if v_applied then v_attempts := v_attempts + 1; v_next := now() + make_interval(hours => v_hours * power(2, v_attempts - 1)::int); end if;
        end if;
      exception when others then
        v_applied := false; v_detail := coalesce(v_detail, '{}'::jsonb) || jsonb_build_object('error', left(sqlerrm, 200));
      end;
    end if;
    insert into pipeline.layer4_drain_state as s (item_id, verdict, action, applied, attempts, first_at, last_at, next_at, dead_letter_at, detail)
    values (r.id, v_verdict, v_action, v_applied, v_attempts, now(), now(), v_next, v_dead, v_detail)
    on conflict (item_id) do update set verdict = excluded.verdict, action = excluded.action, applied = excluded.applied, attempts = excluded.attempts,
      last_at = excluded.last_at, next_at = excluded.next_at, dead_letter_at = coalesce(s.dead_letter_at, excluded.dead_letter_at), detail = excluded.detail;
    v_out := jsonb_set(v_out, array[v_verdict], to_jsonb(coalesce((v_out->>v_verdict)::int, 0) + 1));
  end loop;
  return jsonb_build_object('acting', v_on, 'verdicts', v_out);
end $$;


ALTER FUNCTION "security"."layer4_drain_tick_v1"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."layer4_drain_tick_v1"("p_limit" integer) IS 'CF-247 worker v1.0.1: job layer4-drain. Looks at up to p_limit pending Layer 4 items older than layer4.drain_min_age_days and records the verdict of security.layer4_drain_judge_v1 in pipeline.layer4_drain_state; acts on it (superseded, returned to Layer 2, read again with an exponential cooldown, then a dead letter) only when layer4.drain_on is 1. Never changes an item a person decides (official_course_url and the reviews with their own trigger).';



CREATE OR REPLACE FUNCTION "security"."layer4_effective_entity_read"("p_entity_type" "text", "p_entity_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_rows jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select coalesce(jsonb_agg(security.layer4_effective_field_read(r.entity_type,p_entity_id,r.field_code) order by r.display_label),'[]'::jsonb)
  into v_rows
  from pipeline.layer4_field_registry r
  where r.entity_type=p_entity_type and r.enabled;
  return jsonb_build_object(
    'entity_type',p_entity_type,'entity_id',p_entity_id,
    'fields',coalesce(v_rows,'[]'::jsonb),
    'active_override_count',(
      select count(*) from (
        select distinct on (field_code) field_code,event_type
        from pipeline.layer4_override_decisions
        where entity_type=p_entity_type and entity_id=p_entity_id
        order by field_code,created_at desc,id desc
      ) q where event_type='apply'
    )
  );
end $$;


ALTER FUNCTION "security"."layer4_effective_entity_read"("p_entity_type" "text", "p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_effective_field_read"("p_entity_type" "text", "p_entity_id" "uuid", "p_field_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_rank int; v_reg pipeline.layer4_field_registry%rowtype; v_last pipeline.layer4_override_decisions%rowtype; v_underlying jsonb; v_effective jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  select * into v_reg from pipeline.layer4_field_registry where entity_type=p_entity_type and field_code=p_field_code and enabled;
  if not found then return null; end if;
  v_underlying:=security.layer4_underlying_value(p_entity_type,p_entity_id,p_field_code);
  select * into v_last from pipeline.layer4_override_decisions
   where entity_type=p_entity_type and entity_id=p_entity_id and field_code=p_field_code
   order by created_at desc,id desc limit 1;
  v_effective:=case when found and v_last.event_type='apply' then v_last.override_value else v_underlying end;
  return jsonb_build_object(
    'field_code',p_field_code,'display_label',v_reg.display_label,'value_kind',v_reg.value_kind,
    'editability_class',v_reg.editability_class,'min_role_rank',v_reg.min_role_rank,
    'can_edit',(v_reg.editability_class<>'immutable' and v_rank>=v_reg.min_role_rank),
    'underlying_value',v_underlying,'effective_value',v_effective,
    'effective_source',case when found and v_last.event_type='apply' then 'L4' else 'UNDERLYING' end,
    'override_id',case when found then v_last.id else null end,
    'override_event',case when found then v_last.event_type else null end,
    'actor_id',case when found then v_last.actor_id else null end,
    'actor_email',case when found then v_last.actor_email else null end,
    'edited_at',case when found then v_last.created_at else null end,
    'reason_code',case when found then v_last.reason_code else null end,
    'comment',case when found then v_last.comment else null end,
    'upstream_changed',case when found and v_last.event_type='apply' then v_underlying is distinct from v_last.underlying_value else false end,
    'history_count',(select count(*) from pipeline.layer4_override_decisions d where d.entity_type=p_entity_type and d.entity_id=p_entity_id and d.field_code=p_field_code)
  );
end $$;


ALTER FUNCTION "security"."layer4_effective_field_read"("p_entity_type" "text", "p_entity_id" "uuid", "p_field_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_entity_blocked"("p_entity_type" "text", "p_entity_id" "uuid", "p_block_scope" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
  select coalesce((
    select d.event_type='block' and (d.expires_at is null or d.expires_at>now())
    from pipeline.layer4_block_decisions d
    where d.entity_type=p_entity_type and d.entity_id=p_entity_id and d.block_scope=p_block_scope
    order by d.created_at desc,d.id desc
    limit 1
  ),false)
$$;


ALTER FUNCTION "security"."layer4_entity_blocked"("p_entity_type" "text", "p_entity_id" "uuid", "p_block_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_entity_exists"("p_entity_type" "text", "p_entity_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'scholarship', 'pipeline'
    AS $$
  select case p_entity_type
    when 'course' then exists(select 1 from catalogue.courses where id=p_entity_id)
    when 'provider' then exists(select 1 from catalogue.providers where id=p_entity_id)
    when 'campus' then exists(select 1 from catalogue.campuses where id=p_entity_id)
    when 'scholarship' then exists(select 1 from scholarship.scholarships where id=p_entity_id)
    when 'provider_contact' then exists(select 1 from pipeline.provider_contact_observations where id=p_entity_id)
    when 'provider_contact_import_row' then exists(select 1 from pipeline.provider_contact_import_rows where id=p_entity_id)
    else false
  end
$$;


ALTER FUNCTION "security"."layer4_entity_exists"("p_entity_type" "text", "p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_entity_or_parent_blocked"("p_entity_type" "text", "p_entity_id" "uuid", "p_block_scope" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'catalogue', 'scholarship', 'pipeline'
    AS $$
declare v_type text:=lower(btrim(coalesce(p_entity_type,''))); v_provider uuid;
begin
  if p_block_scope not in ('operational','publication','search','data_quality_quarantine') then
    raise exception 'invalid block scope' using errcode='22023';
  end if;
  if exists(
    select 1 from security.layer4_active_blocks b
    where b.entity_type=v_type and b.entity_id=p_entity_id and b.block_scope=p_block_scope
  ) then return true; end if;

  if v_type='course' then
    select provider_id into v_provider from catalogue.courses where id=p_entity_id;
  elsif v_type='campus' then
    select provider_id into v_provider from catalogue.campuses where id=p_entity_id;
  elsif v_type='scholarship' then
    select provider_id into v_provider from scholarship.scholarships where id=p_entity_id;
  elsif v_type='provider_contact' then
    select provider_id into v_provider from pipeline.provider_contact_observations where id=p_entity_id;
  end if;

  return v_provider is not null and exists(
    select 1 from security.layer4_active_blocks b
    where b.entity_type='provider' and b.entity_id=v_provider and b.block_scope=p_block_scope
  );
end $$;


ALTER FUNCTION "security"."layer4_entity_or_parent_blocked"("p_entity_type" "text", "p_entity_id" "uuid", "p_block_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_evidence_backfill_v1"("p_limit" integer, "p_apply" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_ev uuid; v_seen int := 0; v_link int := 0; v_none int := 0; v_by jsonb := '{}'::jsonb;
begin
  for r in select i.id, i.field_code, i.proposed_value, i.layer2_state from pipeline.layer4_review_items i
            where i.status = 'pending' and i.evidence_id is null and i.field_code = any (security.pipeline_list_v1('layer4.evidence_link_kinds', '[]'::jsonb))
            order by i.created_at, i.id limit least(greatest(coalesce(p_limit, 0), 0), security.pipeline_num_v1('layer4.evidence_backfill_batch', 500)::int) loop
    v_seen := v_seen + 1;
    v_ev := security.layer4_stored_copy_v1(security.layer4_item_page_v1(r.field_code, r.proposed_value, r.layer2_state));
    if v_ev is null then v_none := v_none + 1; continue; end if;
    v_by := jsonb_set(v_by, array[r.field_code], to_jsonb(coalesce((v_by->>r.field_code)::int, 0) + 1));
    if p_apply then
      update pipeline.layer4_review_items set evidence_id = v_ev where id = r.id and status = 'pending' and evidence_id is null;
      if found then v_link := v_link + 1; end if;
    end if;
  end loop;
  if p_apply then
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('layer4', 'evidence_backfill', 'pipeline.layer4_review_items', jsonb_build_object('examined', v_seen, 'linked', v_link, 'no_copy', v_none, 'by_kind', v_by), auth.uid());
  end if;
  return jsonb_build_object('apply', p_apply, 'examined', v_seen, 'linkable', v_seen - v_none, 'linked', v_link, 'no_copy', v_none, 'by_kind', v_by,
                            'left', (select count(*) from pipeline.layer4_review_items i where i.status = 'pending' and i.evidence_id is null
                                       and i.field_code = any (security.pipeline_list_v1('layer4.evidence_link_kinds', '[]'::jsonb))));
end $$;


ALTER FUNCTION "security"."layer4_evidence_backfill_v1"("p_limit" integer, "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_evidence_link_trg_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.evidence_id is null and new.status = 'pending' and security.pipeline_num_v1('layer4.evidence_link_on', 1) >= 1
     and new.field_code = any (security.pipeline_list_v1('layer4.evidence_link_kinds', '[]'::jsonb)) then
    new.evidence_id := security.layer4_stored_copy_v1(security.layer4_item_page_v1(new.field_code, new.proposed_value, new.layer2_state));
  end if;
  return new;
end $$;


ALTER FUNCTION "security"."layer4_evidence_link_trg_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_fee_item_rebind_v1"("p_item" "uuid", "p_url" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_item pipeline.layer4_review_items%rowtype; v_url text := btrim(coalesce(p_url, '')); v_host text; v_dom text; v_pid uuid;
begin
  if auth.uid() is null then raise exception 'sign in required' using errcode = '42501'; end if;
  select * into v_item from pipeline.layer4_review_items where id = p_item for update;
  if v_item.id is null or v_item.status <> 'pending' then raise exception 'this item is no longer waiting (someone may have decided it)'; end if;
  if v_item.entity_type <> 'course' or v_item.field_code <> 'provider_current_tuition' then raise exception 'this choice is for a held fee only'; end if;
  if v_url !~* '^https://[^\s/]+\.[^\s]+$' then raise exception 'enter the full web address (https://…)'; end if;
  select c.provider_id into v_pid from catalogue.courses c where c.id = v_item.entity_id;
  v_host := lower(regexp_replace(substring(v_url from '^https://([^/:?#]+)'), '^www\.', ''));
  select lower(regexp_replace(substring(coalesce(p.website, '') from '^(?:https?://)?([^/:?#]+)'), '^www\.', '')) into v_dom from catalogue.providers p where p.id = v_pid;
  if coalesce(v_dom, '') <> '' and not (v_host = v_dom or v_host like '%.' || v_dom) then raise exception 'this page is not on the provider''s own website (%)', v_dom; end if;
  -- the standard path a person's page entry takes: manual binding and locks, read first in line, then the fee reader and the AI fill
  perform public.admin_course_edit(v_item.entity_id, 'set_official_url', jsonb_build_object('url', v_url, 'reason', left('Layer 4: ' || btrim(p_reason), 480)));
  update pipeline.layer4_review_items set status = 'edited_approved', decided_at = now() where id = v_item.id;
  insert into pipeline.layer4_decisions(review_item_id, action, actor_id, reason, before_value, proposed_value, final_value, evidence_id, layer2_state, layer3_state, change_control_ref)
  values (v_item.id, 'edit_and_approve', auth.uid(), btrim(p_reason), v_item.before_value, v_item.proposed_value, jsonb_build_object('course_url', v_url),
          v_item.evidence_id, v_item.layer2_state, v_item.layer3_state, coalesce(v_item.change_control_ref, 'CF-CHG-20260915-247') || '; hotfix D1 24 Oct 2026');
  return jsonb_build_object('ok', true, 'course_id', v_item.entity_id, 'url', v_url,
    'returns', 'The page is the course''s official page (a person''s value). It is read again first in line under the current page rule; the fee reader then reads it and the fee is admitted if the page states it.');
end $_$;


ALTER FUNCTION "security"."layer4_fee_item_rebind_v1"("p_item" "uuid", "p_url" "text", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."layer4_fee_item_rebind_v1"("p_item" "uuid", "p_url" "text", "p_reason" "text") IS 'hotfix D1: a held-fee Layer 4 item takes a person''s course page address through admin_course_edit set_official_url (bind, lock, read, fee reader) and is closed as edited and approved';



CREATE OR REPLACE FUNCTION "security"."layer4_flow_report_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- over layer4.lifecycle_report_days, from the existing records only: genuine admissions and publication (pipeline.layer4_admission_checks, the
  -- post-decision check), decisions that did not apply, technical recovery (corrected reads that replaced a held read; Human input needed
  -- requests resumed and verified), reroutes (Decision 179: official-link items moved to Course page needed), duplicates and other platform
  -- supersessions (pipeline.layer4_supersessions, reversals left out). Each count is separate; none is added to another.
  with p as (select make_interval(days => security.pipeline_num_v1('layer4.lifecycle_report_days', 7)::int) d)
  select jsonb_build_object('days', security.pipeline_num_v1('layer4.lifecycle_report_days', 7),
    'decisions_applied', (select count(*) from pipeline.admin_control_events e, p where e.area = 'layer4' and e.action = 'inbox_decide' and e.created_at > now() - p.d
                            and coalesce(e.detail->'result'->>'still_waiting', 'false') <> 'true' and e.detail->'result' ? 'still_waiting'),
    'decisions_not_applied', (select count(*) from pipeline.admin_control_events e, p where e.area = 'layer4' and e.action = 'inbox_decide' and e.created_at > now() - p.d
                                and e.detail->'result'->>'still_waiting' = 'true'),
    'admitted', (select count(*) from pipeline.layer4_admission_checks a, p where a.decided_at > now() - p.d and a.admitted),
    'admitted_and_published', (select count(*) from pipeline.layer4_admission_checks a, p where a.decided_at > now() - p.d and a.admitted and a.published),
    'approved_not_admitted', (select count(*) from pipeline.layer4_admission_checks a, p where a.decided_at > now() - p.d and a.result = 'not_admitted'),
    'technical_recovery', jsonb_build_object(
       'corrected_reads_replaced', (select count(*) from pipeline.aer_read_supersessions s, p where s.state = 'superseded' and s.closed_at > now() - p.d),
       'corrected_reads_refused', (select count(*) from pipeline.aer_read_supersessions s, p where s.state = 'refused' and s.closed_at > now() - p.d),
       'human_input_resumed', (select count(*) from pipeline.layer4_interventions i, p where i.resumed_at > now() - p.d),
       'human_input_verified', (select count(*) from pipeline.layer4_interventions i, p where i.verified_at > now() - p.d)),
    'reroutes', jsonb_build_object('decision_179_to_course_page_needed',
       (select count(*) from pipeline.layer4_review_items r, p where r.status = 'superseded' and r.decided_at > now() - p.d and r.field_code = 'official_course_url'
           and exists (select 1 from pipeline.course_page_needed n where r.id = any (n.converted_items)))),
    'duplicates', (select count(*) from pipeline.layer4_supersessions x, p where x.reason = 'duplicate_pending' and x.reversed_at is null and x.at > now() - p.d),
    'supersessions', (select coalesce(jsonb_object_agg(reason, n), '{}'::jsonb) from (select x.reason, count(*) n from pipeline.layer4_supersessions x, p
                        where x.reason <> 'duplicate_pending' and x.reversed_at is null and x.at > now() - p.d group by 1) z),
    'note', 'Admissions are counted only from the post-decision check (pipeline.layer4_admission_checks); reroutes, duplicates and supersessions move work between queues and are never admissions')
$$;


ALTER FUNCTION "security"."layer4_flow_report_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_group_counts_v1"("p_provider" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  -- the Inbox's three choices and group A, from the stored groups only (pipeline.layer4_item_groups; mandate 16:32 §7). One primary disposition
  -- per waiting item, so the groups sum to the items waiting (direction 18:08 §5); Human input needed requests are a separate line, never added.
  -- A row whose input changed since it was grouped counts as C until job layer4-groups groups it again ("not grouped yet")
  with g as (select x.kind, x.ref, x.item_created_at, x.rule, x.cls,
                    case when x.grp <> 'C' and ((rd.classified_at is not null and rd.classified_at > x.input_at) or (iv.updated_at is not null and iv.updated_at > x.input_at)) then 'C' else x.grp end grp,
                    (rd.classified_at is not null and rd.classified_at > x.input_at) or (iv.updated_at is not null and iv.updated_at > x.input_at) stale, x.classified_at
               from pipeline.layer4_item_groups x
               left join pipeline.layer4_item_readiness rd on x.kind in ('course_link', 'aer_review', 'provider_description', 'no_page_first_run', 'conjoint_first_run')
                    and rd.item_id = case when x.ref ~ '^[0-9a-f-]{36}$' then x.ref::uuid end
               left join pipeline.layer4_interventions iv on x.kind = 'intervention' and iv.id = case when x.ref ~ '^[0-9]+$' then x.ref::bigint end
              where x.state = 'waiting' and (p_provider is null or x.provider_id = p_provider)),
       it as (select * from g where g.kind <> 'intervention'),
       hi as (select * from g where g.kind = 'intervention')
  select jsonb_build_object(
    'groups', (select coalesce(jsonb_object_agg(grp, n), '{}'::jsonb) from (select grp, count(*) n from it group by 1) z),
    'pending', (select count(*) from it),
    'pending_review_items', (select count(*) from it where it.kind in ('course_link', 'aer_review', 'provider_description', 'no_page_first_run', 'conjoint_first_run')),
    'pending_other_items', (select count(*) from it where it.kind not in ('course_link', 'aer_review', 'provider_description', 'no_page_first_run', 'conjoint_first_run')),
    'human_input_requests', jsonb_build_object('waiting', (select count(*) from hi where hi.grp = 'D'), 'recovering', (select count(*) from hi where hi.grp <> 'D')),
    'by_kind', (select coalesce(jsonb_object_agg(grp, k), '{}'::jsonb) from (select grp, jsonb_object_agg(kind, n) k from (select grp, kind, count(*) n from it group by 1, 2) y group by 1) z),
    'oldest', (select coalesce(jsonb_object_agg(grp, o), '{}'::jsonb) from (select grp, min(item_created_at) o from it group by 1) z),
    'rules', (select coalesce(jsonb_agg(jsonb_build_object('rule', rule, 'class', cls, 'n', n) order by n desc), '[]'::jsonb)
                from (select rule, cls, count(*) n from it where grp = 'A' group by 1, 2) z),
    'waiting', (select count(*) from it), 'regrouping', (select count(*) from it where stale),
    'grouped_at', security.l4_time_v1((select max(classified_at) from pipeline.layer4_item_groups)))
$_$;


ALTER FUNCTION "security"."layer4_group_counts_v1"("p_provider" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_groups_fill_v1"("p_full" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_t0 timestamptz := clock_timestamp(); v_batch int := security.pipeline_num_v1('batch.layer4_groups', 500)::int;
        v_budget numeric := security.pipeline_num_v1('layer4.groups_fill_seconds', 30); v_keys text[]; v_done text[] := '{}'; v_n int := 0; v_closed int := 0; v_left int := 0; v_waiting int := 0;
begin
  create temp table if not exists _l4g_now (kind text, ref text, provider_id uuid, created_at timestamptz, input_at timestamptz, primary key (kind, ref)) on commit drop;
  truncate _l4g_now;
  insert into _l4g_now
  select i.kind, i.ref, i.provider_id, i.created_at,
         greatest(i.created_at, rd.classified_at, (select max(x.updated_at) from pipeline.layer4_interventions x where x.lane = 'aer_item' and x.entity = i.ref))
    from security.layer4_inbox_items_v2(null, null, null, false) i
    left join pipeline.layer4_item_readiness rd on i.kind in ('course_link', 'aer_review', 'provider_description', 'no_page_first_run', 'conjoint_first_run')
         and rd.item_id = case when i.ref ~ '^[0-9a-f-]{36}$' then i.ref::uuid end
  union all
  select 'intervention', x.id::text, x.provider_id, x.created_at, x.updated_at from pipeline.layer4_interventions x where x.status in ('ai_pending', 'awaiting_input', 'resuming')
  on conflict do nothing;
  get diagnostics v_waiting = row_count;
  update pipeline.layer4_item_groups g set state = 'closed', closed_at = now()
   where g.state = 'waiting' and not exists (select 1 from _l4g_now n where n.kind = g.kind and n.ref = g.ref);
  get diagnostics v_closed = row_count;
  loop
    v_keys := array(select n.kind || ':' || n.ref from _l4g_now n left join pipeline.layer4_item_groups g on g.kind = n.kind and g.ref = n.ref
                      where (g.kind is null or g.state <> 'waiting' or g.input_at is distinct from n.input_at or (p_full and g.classified_at < v_t0))
                        and not ((n.kind || ':' || n.ref) = any (v_done))
                      order by (g.kind is null) desc, g.classified_at nulls first, n.created_at limit v_batch);
    exit when cardinality(v_keys) = 0;
    insert into pipeline.layer4_item_groups as t(kind, ref, provider_id, item_created_at, grp, cls, rule, next_action, secondary, state, input_at, classified_at, closed_at)
    select c.kind, c.ref, coalesce(c.provider_id, n.provider_id), n.created_at, c.grp, c.cls, c.rule,
           case c.grp when 'A' then 'settled when its rule runs: ' || coalesce(c.rule, 'an existing rule') when 'B' then 'technical recovery continues by itself'
                      when 'C' then 'a person decides' else 'a person gives the missing information' end,
           coalesce(c.secondary, '[]'::jsonb), 'waiting', n.input_at, clock_timestamp(), null
      from security.layer4_groups_v1(null, null, v_keys) c join _l4g_now n on n.kind = c.kind and n.ref = c.ref
    on conflict (kind, ref) do update set provider_id = excluded.provider_id, item_created_at = excluded.item_created_at, grp = excluded.grp, cls = excluded.cls,
           rule = excluded.rule, next_action = excluded.next_action, secondary = excluded.secondary, state = 'waiting', input_at = excluded.input_at, classified_at = excluded.classified_at, closed_at = null;
    -- an item the classifier no longer lists (it left between the two reads) is not tried again in this run
    v_done := v_done || v_keys;
    v_n := v_n + cardinality(v_keys);
    exit when extract(epoch from clock_timestamp() - v_t0) >= v_budget;
  end loop;
  select count(*) into v_left from _l4g_now n left join pipeline.layer4_item_groups g on g.kind = n.kind and g.ref = n.ref
   where g.kind is null or g.state <> 'waiting' or g.input_at is distinct from n.input_at;
  return jsonb_build_object('waiting', v_waiting, 'grouped', v_n, 'closed', v_closed, 'not_grouped_yet', v_left, 'full', p_full,
                            'ms', round(extract(epoch from clock_timestamp() - v_t0) * 1000));
end $_$;


ALTER FUNCTION "security"."layer4_groups_fill_v1"("p_full" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_groups_v1"("p_provider" "uuid" DEFAULT NULL::"uuid", "p_kind" "text" DEFAULT NULL::"text", "p_keys" "text"[] DEFAULT NULL::"text"[]) RETURNS TABLE("kind" "text", "ref" "text", "provider_id" "uuid", "created_at" timestamp with time zone, "grp" "text", "cls" "text", "rule" "text", "why" "text", "secondary" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_map jsonb := coalesce((select w.value from pipeline.platform_toolset_settings w where w.toolset_key = 'pipeline' and w.key = 'layer4.group_by_kind'), '[]'::jsonb);
        v_cl boolean := security.pipeline_num_v1('layer4.groups_course_link_router_on', 1) >= 1;  -- official links: the Course Link workstream's routing
        v_rec_on boolean := security.pipeline_num_v1('layer4.reconcile_supersede_on', 0) >= 1;
begin
  return query
  with i as (select x.kind, x.ref, x.provider_id, x.created_at, x.why
               from security.layer4_inbox_items_v2(p_provider, case when p_kind = 'intervention' then '-' else p_kind end, p_keys, false) x
              where p_kind is distinct from 'intervention'),
       def as (select split_part(e, '=', 1) k, split_part(e, '=', 2) g from jsonb_array_elements_text(v_map) e),
       ri as (select i.*, r.field_code, r.entity_id, r.escalation_reason, r.before_value, r.proposed_value, rd.readiness, rd.route, rd.reasons
                from i left join pipeline.layer4_review_items r on i.kind in ('course_link', 'aer_review', 'provider_description', 'no_page_first_run', 'conjoint_first_run')
                       and r.id = case when i.ref ~ '^[0-9a-f-]{36}$' then i.ref::uuid end
                left join pipeline.layer4_item_readiness rd on rd.item_id = r.id and rd.item_status = 'pending'),
       clh as (select ri.ref, case when v_cl then security.layer4_cl_group_call_v1(ri.ref::uuid) else '{"grp": "C", "cls": "course_link:router_off"}'::jsonb end j
                 from ri where ri.field_code = 'official_course_url'),
       aiv as (select x.entity, min(x.id) id, bool_or(x.status = 'awaiting_input') waiting from pipeline.layer4_interventions x where x.lane = 'aer_item' and x.status in ('ai_pending', 'awaiting_input', 'resuming') group by 1)
  select ri.kind, ri.ref, ri.provider_id, ri.created_at,
         case when clh.j->>'grp' in ('A', 'B', 'C', 'D') then clh.j->>'grp'
              when ri.readiness = 'resolvable' then 'A' when aiv.id is not null then case when aiv.waiting then 'D' else 'B' end
              when ri.readiness = 'technical_blocked' then 'B' when ri.readiness = 'judgement_ready' then 'C'
              else coalesce((select def.g from def where def.k = ri.kind), 'C') end,
         case when clh.j->>'grp' in ('A', 'B', 'C', 'D') then coalesce(clh.j->>'cls', 'course_link')
              when ri.readiness = 'resolvable' then coalesce(ri.route, 'platform:resolvable')
              when aiv.id is not null then case when aiv.waiting then 'human_input:' else 'human_input_resuming:' end || aiv.id when ri.readiness is not null then ri.route else 'kind:' || ri.kind end,
         case when clh.j->>'grp' in ('A', 'B', 'C', 'D') then clh.j->>'rule'
              when ri.readiness = 'resolvable' then 'security.layer4_reconcile_v1 (' || case when v_rec_on then 'on' else 'off: layer4.reconcile_supersede_on' end || ')'
              end,
         ri.why,
         -- direction 18:08 §5: one primary disposition (grp, cls); every other reason that applies is secondary, never a second count
         to_jsonb(array_remove(array[
           case when clh.j is not null and ri.readiness is not null then 'readiness:' || ri.route end,
           case when clh.j is not null and clh.j->>'action' is not null then 'course_link_action:' || (clh.j->>'action') end,
           case when aiv.id is not null and (coalesce(clh.j->>'grp' in ('A', 'B', 'C', 'D'), false) or coalesce(ri.readiness = 'resolvable', false)) then 'human_input:' || aiv.id end,
           case when aiv.id is not null and not (coalesce(clh.j->>'grp' in ('A', 'B', 'C', 'D'), false) or coalesce(ri.readiness = 'resolvable', false)) and ri.readiness is not null
                then 'readiness:' || ri.route end], null))
    from ri left join aiv on aiv.entity = ri.ref left join clh on clh.ref = ri.ref
  union all
  select 'intervention', x.id::text, x.provider_id, x.created_at, case when x.status = 'awaiting_input' then 'D' else 'B' end, 'intervention:' || x.status, null,
         coalesce(x.required_input->>'ask', x.subject),
         -- a Human input needed request is work of its own, counted on its own line; the item it serves (if any) is named here
         case when x.lane = 'aer_item' then jsonb_build_array('for_item:' || x.entity) else '[]'::jsonb end
    from pipeline.layer4_interventions x
   where x.status in ('ai_pending', 'awaiting_input', 'resuming') and (p_kind is null or p_kind = 'intervention')
     and (p_provider is null or x.provider_id = p_provider) and (p_keys is null or 'intervention:' || x.id = any (p_keys));
end $_$;


ALTER FUNCTION "security"."layer4_groups_v1"("p_provider" "uuid", "p_kind" "text", "p_keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_inbox_counts_v1"("p_target_days" integer) RETURNS TABLE("kind" "text", "provider_id" "uuid", "n" bigint, "oldest" timestamp with time zone, "late" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 Layer 4 Inbox performance (4 Nov 2026): waiting items by kind and university, and how many are older than the target, with no detail built
  select i.kind, i.provider_id, count(*), min(i.created_at), count(*) filter (where i.created_at < now() - make_interval(days => p_target_days))
    from security.layer4_inbox_items_v2(null, null, null, false) i group by 1, 2
$$;


ALTER FUNCTION "security"."layer4_inbox_counts_v1"("p_target_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_inbox_hook_call_v1"("p_fn" "text", "p_arg" "jsonb", "p_ref" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v jsonb;
begin
  if p_fn is null then return null; end if;
  begin
    if p_ref is null then execute format('select %s($1)', p_fn) into v using p_arg;
    else execute format('select %s($1)', p_fn) into v using p_ref; end if;
  exception when others then
    return jsonb_build_object('error', sqlerrm);
  end;
  return v;
end $_$;


ALTER FUNCTION "security"."layer4_inbox_hook_call_v1"("p_fn" "text", "p_arg" "jsonb", "p_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_inbox_hook_counts_v1"("p_hooks" "jsonb", "p_kind" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare h jsonb; v jsonb; v_out jsonb := '[]'; v_failed jsonb := '[]';
begin
  for h in select x from jsonb_array_elements(coalesce(p_hooks->'hooks', '[]'::jsonb)) x where x->>'mode' = 'kind' and (p_kind is null or x->>'kind' = p_kind) loop
    begin
      execute format('select %s()', h->>'counts_fn') into v;
      v_out := v_out || jsonb_build_array(jsonb_build_object('kind', h->>'kind', 'order', h->'order', 'n', coalesce((v->>'n')::bigint, 0), 'oldest', v->'oldest',
                 'late', coalesce((v->>'late')::bigint, 0), 'by_provider', case when jsonb_typeof(v->'by_provider') = 'array' then v->'by_provider' else '[]'::jsonb end));
    exception when others then
      v_failed := v_failed || jsonb_build_array(jsonb_build_object('id', h->>'id', 'error', sqlerrm));
    end;
  end loop;
  return jsonb_build_object('items', v_out, 'failed', v_failed);
end $$;


ALTER FUNCTION "security"."layer4_inbox_hook_counts_v1"("p_hooks" "jsonb", "p_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_inbox_hook_fn_v1"("p_sig" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- a hook function by its full signature, only in schema security; null when it does not exist (yet)
  select p.oid::regproc::text from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace
   where p.oid = pg_catalog.to_regprocedure(p_sig) and n.nspname = 'security'
$$;


ALTER FUNCTION "security"."layer4_inbox_hook_fn_v1"("p_sig" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_inbox_hooks_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_kinds jsonb := security.layer4_inbox_kinds_v1(); v_builtin jsonb := security.layer4_inbox_kinds_v1(); h record; v_fn jsonb; v_id text; v_k jsonb; v_ch jsonb;
        v_hooks jsonb := '[]'; v_missing jsonb := '[]'; v_failed jsonb := '[]'; v_need text[];
begin
  if security.pipeline_num_v1('layer4.inbox_hooks_on', 1) <> 1 then
    return jsonb_build_object('kinds', v_kinds, 'hooks', v_hooks, 'missing', v_missing, 'failed', v_failed, 'on', false);
  end if;
  for h in select * from pipeline.layer4_inbox_kind_hooks x where x.enabled order by x.mode desc, x.kind loop
    v_id := h.kind || ':' || h.mode;
    v_fn := jsonb_build_object('kind_fn', security.layer4_inbox_hook_fn_v1(h.kind_fn), 'counts_fn', security.layer4_inbox_hook_fn_v1(h.counts_fn),
              'page_fn', security.layer4_inbox_hook_fn_v1(h.page_fn), 'detail_fn', security.layer4_inbox_hook_fn_v1(h.detail_fn), 'decide_fn', security.layer4_inbox_hook_fn_v1(h.decide_fn));
    if (h.mode = 'kind') = (v_builtin ? h.kind) then
      v_failed := v_failed || jsonb_build_array(jsonb_build_object('id', v_id, 'error', case when h.mode = 'kind' then 'a built-in kind has this key' else 'no built-in kind has this key' end));
      continue;
    end if;
    v_need := case when h.mode = 'kind' then array['kind_fn', 'counts_fn', 'page_fn', 'decide_fn'] else array['kind_fn', 'decide_fn'] end;
    if exists (select 1 from unnest(v_need) x where v_fn->>x is null) then
      v_missing := v_missing || jsonb_build_array(jsonb_build_object('id', v_id, 'missing', to_jsonb(array(select x from unnest(v_need) x where v_fn->>x is null))));
      continue;
    end if;
    begin
      execute format('select %s()', v_fn->>'kind_fn') into v_k;
    exception when others then
      v_failed := v_failed || jsonb_build_array(jsonb_build_object('id', v_id, 'error', sqlerrm)); continue;
    end;
    v_ch := (select coalesce(jsonb_agg(c || jsonb_build_object('hook', v_id) order by o), '[]'::jsonb)
               from jsonb_array_elements(case when jsonb_typeof(v_k->'choices') = 'array' then v_k->'choices' else '[]'::jsonb end) with ordinality x(c, o)
              where c ? 'key' and c ? 'label'
                and (h.mode = 'kind' or not exists (select 1 from jsonb_array_elements(v_builtin->h.kind->'choices') b where b->>'key' = c->>'key')));
    if h.mode = 'kind' then
      v_kinds := v_kinds || jsonb_build_object(h.kind, jsonb_build_object('label', coalesce(v_k->>'label', h.kind), 'order', coalesce((v_k->>'order')::int, 99),
                   'choices', v_ch, 'hook', v_id, 'detail', v_fn->>'detail_fn' is not null));
    else
      v_kinds := jsonb_set(v_kinds, array[h.kind], (v_kinds->h.kind) || jsonb_build_object('choices', (v_kinds->h.kind->'choices') || v_ch, 'extension', v_id,
                   'detail', v_fn->>'detail_fn' is not null));
    end if;
    v_hooks := v_hooks || jsonb_build_array(jsonb_build_object('id', v_id, 'kind', h.kind, 'mode', h.mode,
                 'order', coalesce((v_kinds->h.kind->>'order')::int, 99)) || v_fn);
  end loop;
  return jsonb_build_object('kinds', v_kinds, 'hooks', v_hooks, 'missing', v_missing, 'failed', v_failed, 'on', true);
end $$;


ALTER FUNCTION "security"."layer4_inbox_hooks_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_inbox_items_v1"() RETURNS TABLE("kind" "text", "ref" "text", "provider_id" "uuid", "subject" "text", "why" "text", "suggestion" "text", "created_at" timestamp with time zone, "detail" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 Layer 4 Inbox performance (4 Nov 2026): every item that needs a person, one row each, from security.layer4_inbox_items_v2
  select * from security.layer4_inbox_items_v2(null, null, null, true)
$$;


ALTER FUNCTION "security"."layer4_inbox_items_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_inbox_items_v2"("p_provider_id" "uuid" DEFAULT NULL::"uuid", "p_kind" "text" DEFAULT NULL::"text", "p_keys" "text"[] DEFAULT NULL::"text"[], "p_detail" boolean DEFAULT true) RETURNS TABLE("kind" "text", "ref" "text", "provider_id" "uuid", "subject" "text", "why" "text", "suggestion" "text", "created_at" timestamp with time zone, "detail" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  -- CF-247 Layer 4 Inbox performance (4 Nov 2026): every item that needs a person, one row each, as security.layer4_inbox_items_v1 had them.
  -- A university (p_provider_id), a kind (p_kind) or items ('kind:ref' in p_keys) are chosen inside each source before anything is built;
  -- p_detail false leaves the detail out (counts and keys only).
  with ob as (select distinct on (o.provider_id) o.* from pipeline.provider_onboarding o order by o.provider_id, o.created_at desc),
  cricos_only as (select b.provider_id from pipeline.adapter_builds b where b.wave = 'cricos-only'),
  held_pages as (select f.provider_id from pipeline.enrichment_flags f where f.entity = 'provider' and f.state = 'raised' and f.reason_code = 'course_pages_not_found')
  -- course links and other review items
  -- hotfix 26 Oct 2026: a first run for a university (no page published, conjoint rule) carries its university and its own kind
  select z.k, r.id::text, z.pid,
         coalesce(nullif(c.display_title, ''), c.canonical_title, s.name,
                  case when r.entity_type = 'provider' and r.field_code = 'no_page_first_run' then 'No page published: first run'
                       when r.entity_type = 'provider' and r.field_code = 'conjoint_rule_first_run' then 'Conjoint or double degrees: first run' end,
                  case r.field_code when 'entry_matrix_first_run' then 'Entry requirements: first read of the provider table'
                                       when 'entry_matrix_change' then 'Entry requirements: the provider table changed'
                                       when 'provider_description' then 'University description from the official page' end,
                  r.field_code),
         -- mandate 3 Nov 2026 20:47 §5: a CRICOS code is named only for Australian providers
         case when coalesce(kc.iso_alpha2, 'AU') <> 'AU' and r.escalation_reason ilike '%CRICOS%'
              then replace(replace(r.escalation_reason, 'this course''s CRICOS code', 'this course''s code'), 'CRICOS code', 'course code')
              else coalesce(nullif(r.escalation_reason, ''), 'Needs a decision') end, null::text, r.created_at,
         case when p_detail then
         jsonb_build_object('field_code', r.field_code, 'course_id', c.id, 'course_code', c.course_code, 'before', r.before_value, 'proposed', r.proposed_value,
                            'code_label', case when coalesce(kc.iso_alpha2, 'AU') = 'AU' then 'CRICOS' else 'Course code' end,
                            -- UR-05 (1 Nov 2026): the stored copy behind the item, when it was captured, and whether a newer copy of the same page exists
                            'evidence_id', r.evidence_id, 'captured_at', ev.captured_at, 'source_url', ev.source_url,
                            'newer_copy', ev.id is not null and exists (select 1 from pipeline.evidence_artifacts n where lower(n.source_url) = lower(ev.source_url) and n.captured_at > ev.captured_at)) end
    from pipeline.layer4_review_items r
    left join catalogue.courses c on r.entity_type = 'course' and c.id = r.entity_id
    left join scholarship.scholarships s on r.entity_type = 'scholarship' and s.id = r.entity_id
    cross join lateral (select case when r.entity_type = 'provider' and r.field_code = 'no_page_first_run' then 'no_page_first_run'
              when r.entity_type = 'provider' and r.field_code = 'conjoint_rule_first_run' then 'conjoint_first_run'
              when r.field_code = any (security.aer_review_kinds_v1()) then 'aer_review'  -- CF-247 A1-A3 (30 Oct 2026): the AER review path
              when r.entity_type = 'provider' and r.field_code = 'provider_description' then 'provider_description'  -- CF-247 P1 (2 Nov 2026): university descriptions
              when r.entity_type = 'course' and r.field_code = 'course_description_first_read' then 'provider_description'  -- CF-247 Workstream C (3 Nov 2026): course descriptions, the same review (approve as read or reject)
              else 'course_link' end::text k,
              coalesce(c.provider_id, s.provider_id, case when r.entity_type = 'provider' then r.entity_id end) pid) z
    left join pipeline.evidence_artifacts ev on p_detail and ev.id = r.evidence_id
    left join catalogue.providers pv on pv.id = coalesce(c.provider_id, s.provider_id)
    left join ref.countries kc on kc.id = pv.country_id
   where r.status = 'pending'
     and (p_provider_id is null or z.pid = p_provider_id) and (p_kind is null or z.k = p_kind) and (p_keys is null or z.k || ':' || r.id::text = any (p_keys))
  union all
  -- held scholarship pages, with the AI re-check
  select 'held_scholarship', r.id::text, r.provider_id,
         coalesce((select e.answer->>'name' from pipeline.scholarship_ai_extractions e where e.id = r.extraction_ids[array_upper(r.extraction_ids, 1)]), r.url),
         r.reason, r.recheck->>'why', r.created_at,
         case when p_detail then
         jsonb_build_object('url', r.url, 'recommendation', r.recheck->>'recommendation', 'audience_quote', r.recheck->>'audience_quote', 'value_quote', r.recheck->>'value_quote',
                            'extraction_id', (select e.id from pipeline.scholarship_ai_extractions e where e.id = any (r.extraction_ids) and coalesce((e.answer->>'is_scholarship')::boolean, false) order by e.id desc limit 1)) end
    from pipeline.scholarship_ai_reviews r where r.status = 'pending'
     and (p_kind is null or p_kind = 'held_scholarship') and (p_provider_id is null or r.provider_id = p_provider_id)
     and (p_keys is null or 'held_scholarship:' || r.id::text = any (p_keys))
  union all
  -- universities whose onboarding stopped and needs a person
  select z.k, ob.id::text, ob.provider_id, null, coalesce(ob.note, ob.stop_reason), null, ob.updated_at,
         case when p_detail then jsonb_build_object('stop_reason', ob.stop_reason, 'onboarding_id', ob.id) end
    from ob
    cross join lateral (select case ob.stop_reason when 'no_website' then 'website_needed' when 'too_few_pages' then 'too_few_pages' when 'nothing_ready' then 'nothing_ready'
              when 'approve_central' then 'central_to_approve' else 'onboarding_failed' end k) z
   where ob.status = 'stopped' and ob.stop_reason in ('no_website', 'too_few_pages', 'nothing_ready', 'approve_central', 'proposal_failed', 'capture_failed')
     and ob.provider_id not in (select provider_id from cricos_only)
     and not (ob.stop_reason = 'too_few_pages' and ob.provider_id in (select provider_id from held_pages))
     and (p_kind is null or z.k = p_kind) and (p_provider_id is null or ob.provider_id = p_provider_id) and (p_keys is null or z.k || ':' || ob.id::text = any (p_keys))
  union all
  -- provider holds a person lifts
  select z.k, f.id::text, f.provider_id, null, f.reason, null, f.flagged_at, case when p_detail then jsonb_build_object('flag_id', f.id, 'evidence', f.evidence) end
    from pipeline.enrichment_flags f
    cross join lateral (select case f.reason_code when 'course_pages_not_found' then 'pages_not_found' when 'site_unreachable' then 'site_down' else 'fee_check' end k) z
   where f.entity = 'provider' and f.state = 'raised'
     and (f.reason_code in ('course_pages_not_found', 'adapter_fee_fails_check')
          or (f.reason_code = 'site_unreachable' and f.flagged_at < now() - make_interval(days => security.pipeline_num_v1('layer4.site_down_days', 30)::int)))
     and (p_kind is null or z.k = p_kind) and (p_provider_id is null or f.provider_id = p_provider_id) and (p_keys is null or z.k || ':' || f.id::text = any (p_keys))
  union all
  -- course holds a person decides
  select z.k, f.id::text, coalesce(f.provider_id, c.provider_id), coalesce(nullif(c.display_title, ''), c.canonical_title), f.reason, null, f.flagged_at,
         case when p_detail then
         jsonb_build_object('flag_id', f.id, 'course_id', c.id, 'course_code', c.course_code,
                            -- mandate 3 Nov 2026 20:47 §5: the stored copy of the course's bound page, so a fee or course hold shows its evidence
                            'evidence_id', g.evidence_id, 'captured_at', gev.captured_at, 'source_url', gev.source_url) end
    -- the course by its key as written (a lower-case uuid, as c.id::text = f.entity_key matched), so its primary key is used
    from pipeline.enrichment_flags f left join catalogue.courses c on c.id = case when f.entity_key ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then f.entity_key::uuid end
    cross join lateral (select case f.reason_code when 'not_offered' then 'not_offered' when 'not_on_provider_site' then 'not_on_site' else 'fee_check' end k) z
    left join pipeline.coverage_course_pages g on p_detail and g.course_id = c.id
    left join pipeline.evidence_artifacts gev on gev.id = g.evidence_id
   where f.entity = 'course' and f.state = 'raised' and f.reason_code in ('not_offered', 'not_on_provider_site', 'fee_crosscheck')
     and (p_kind is null or z.k = p_kind) and (p_provider_id is null or coalesce(f.provider_id, c.provider_id) = p_provider_id)
     and (p_keys is null or z.k || ':' || f.id::text = any (p_keys))
  union all
  -- Decision 179 (Platform Admin 3 Nov 2026 20:29): courses that need a correct page, while open and still without an official page
  select 'course_page_needed', n.course_id::text, n.provider_id, coalesce(nullif(c.display_title, ''), c.canonical_title),
         'No page of this course has been verified. ' || n.refused || ' page' || case when n.refused = 1 then ' was' else 's were' end || ' found and refused, the last: '
           || coalesce(n.last_refused_reason, 'not proved to be this course''s page'),
         null, n.created_at,
         case when p_detail then
         jsonb_build_object('course_id', c.id, 'course_code', c.course_code, 'code_label', case when coalesce(kc.iso_alpha2, 'AU') = 'AU' then 'CRICOS' else 'Course code' end,
                            'proposed', jsonb_build_object('course_url', n.last_refused_url), 'refused', n.refused, 'lane', n.last_refused_lane, 'converted_items', to_jsonb(n.converted_items),
                            'searches_requested', n.searches_requested, 'evidence_id', n.last_refused_evidence, 'captured_at', nev.captured_at, 'source_url', nev.source_url) end
    from pipeline.course_page_needed n join catalogue.courses c on c.id = n.course_id
    left join catalogue.providers pv on pv.id = n.provider_id left join ref.countries kc on kc.id = pv.country_id
    left join pipeline.evidence_artifacts nev on p_detail and nev.id = n.last_refused_evidence
   where n.state = 'open' and c.lifecycle_status = 'active'
     and not exists (select 1 from catalogue.course_links l where l.course_id = n.course_id and l.link_type = 'official_course' and l.status = 'active')
     and (p_kind is null or p_kind = 'course_page_needed') and (p_provider_id is null or n.provider_id = p_provider_id)
     and (p_keys is null or 'course_page_needed:' || n.course_id::text = any (p_keys))
  union all
  -- counsellor reports from Zoho
  select 'counsellor_report', d.id::text, z.pid, coalesce(d.detail->>'label', d.field_code), coalesce(d.detail->>'note', 'Reported by a counsellor'), null, d.created_at,
         case when p_detail then d.detail end
    from pipeline.data_flags d
    cross join lateral (select coalesce((select c.provider_id from catalogue.courses c where d.entity_type = 'course' and c.id = d.entity_id), case when d.entity_type = 'provider' then d.entity_id end) pid) z
   where d.flag_code = 'reported' and d.status = 'open'
     and (p_kind is null or p_kind = 'counsellor_report') and (p_provider_id is null or z.pid = p_provider_id) and (p_keys is null or 'counsellor_report:' || d.id::text = any (p_keys))
  union all
  -- CF-247 20 Oct 2026: providers whose every registered course left the register (from the retired Review queue)
  select 'provider_departure', d.id::text, d.provider_id, coalesce(p.display_name, p.canonical_name),
         'Every registered course left the register (' || d.courses_retired || ' course' || case when d.courses_retired = 1 then '' else 's' end || '). Closed, merged into another provider, or still operating?',
         null, d.created_at, case when p_detail then jsonb_build_object('departure_id', d.id, 'courses_retired', d.courses_retired, 'note', d.note) end
    from pipeline.layer1_provider_departures d left join catalogue.providers p on p.id = d.provider_id where d.status = 'needs_review'
     and (p_kind is null or p_kind = 'provider_departure') and (p_provider_id is null or d.provider_id = p_provider_id)
     and (p_keys is null or 'provider_departure:' || d.id::text = any (p_keys))
$_$;


ALTER FUNCTION "security"."layer4_inbox_items_v2"("p_provider_id" "uuid", "p_kind" "text", "p_keys" "text"[], "p_detail" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_inbox_kinds_v1"() RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select '{
   "course_link": {"label": "Course link", "order": 1, "choices": [
     {"key": "keep", "label": "Keep the page we hold", "returns": "Closed; the same pair of pages is not asked again"},
     {"key": "use", "label": "Use the new page", "returns": "The new page becomes the official page (a person''s value, never overwritten); it is read again and the adapter applies"},
     {"key": "enter", "label": "Enter another address", "input": "url", "returns": "That address becomes the official page; it is read again and the adapter applies"},
     {"key": "refuse", "label": "Refuse this proposal", "returns": "Closed; this page is recorded as refused for the course and is not asked again. Any page we hold stays as it is"}]},
   "held_scholarship": {"label": "Held scholarship", "order": 2, "choices": [
     {"key": "publish", "label": "Publish", "returns": "Taken as for international students and offered; the hourly publish checks still apply"},
     {"key": "not_international", "label": "Not for international students", "reason": "The page does not say international students may apply", "returns": "Refused; the same page copy is not asked again"},
     {"key": "not_scholarship", "label": "Not a scholarship", "reason": "Not a scholarship page", "returns": "Refused; the same page copy is not asked again"},
     {"key": "duplicate", "label": "Duplicate of a published scholarship", "input": "scholarship", "returns": "Closed as a duplicate of the published scholarship you name (same provider); nothing on that scholarship changes"}]},
   "website_needed": {"label": "Website needed", "order": 3, "choices": [
     {"key": "website", "label": "Enter the website", "input": "url", "returns": "Onboarding starts again from the website: its course pages are found and read, then the adapter is built"},
     {"key": "cricos_only", "label": "CRICOS data only", "returns": "No adapter and no credits; it keeps its register data"},
     {"key": "archive", "label": "Archive the university", "rank": 5, "returns": "Unpublished and hidden from the consumer API; reviewable on Archived"}]},
   "pages_not_found": {"label": "Course pages not found", "order": 4, "choices": [
     {"key": "website", "label": "Change the website", "input": "url", "returns": "The hold is released, the site is mapped again and onboarding starts again"},
     {"key": "pages", "label": "Add page addresses", "link": "builder", "returns": "Opens the Adapter builder (2.1); release the hold here once pages are added"},
     {"key": "release", "label": "Release and try again", "rank": 4, "returns": "The hold is released; the site is mapped again and onboarding starts again"},
     {"key": "cricos_only", "label": "CRICOS data only", "returns": "Stays held; labelled CRICOS data only"}]},
   "too_few_pages": {"label": "Too few course pages", "order": 5, "choices": [
     {"key": "pages", "label": "Add page addresses", "link": "builder", "returns": "Onboarding carries on by itself once 3 pages are read"},
     {"key": "cricos_only", "label": "CRICOS data only", "returns": "No adapter and no credits; it keeps its register data"}]},
   "nothing_ready": {"label": "Adapter has nothing ready", "order": 6, "choices": [
     {"key": "adapter", "label": "Open the adapter", "link": "builder", "returns": "Fix a pattern and qualify again; what passes is admitted"},
     {"key": "rebuild", "label": "Rebuild the adapter", "rank": 5, "returns": "Onboarding builds and qualifies the adapter again; what passes is admitted, then courses are enriched and scholarships found"},
     {"key": "cricos_only", "label": "CRICOS data only", "returns": "No more work on its adapter; it keeps its register data"}]},
   "central_to_approve": {"label": "Central pages to approve", "order": 7, "choices": [
     {"key": "open", "label": "Open the central pages", "link": "builder", "returns": "Approve or refuse each page; onboarding carries on by itself"}]},
   "onboarding_failed": {"label": "Adapter proposal failed", "order": 8, "choices": [
     {"key": "retry", "label": "Try again", "rank": 5, "returns": "Onboarding starts again from the step that stopped"},
     {"key": "builder", "label": "Build by hand", "link": "builder", "returns": "Opens the Adapter builder"}]},
   "site_down": {"label": "Website not answering", "order": 9, "choices": [
     {"key": "website", "label": "Change the website", "input": "url", "returns": "The hold is released and onboarding starts again from the website"},
     {"key": "archive", "label": "Archive the university", "rank": 5, "returns": "Unpublished and hidden from the consumer API; reviewable on Archived"},
     {"key": "wait", "label": "Keep waiting", "returns": "Checked every 10 minutes as before; asked again in 30 days"}]},
   "not_offered": {"label": "Course not offered", "order": 10, "choices": [
     {"key": "archive_course", "label": "Archive the course", "rank": 5, "returns": "Unpublished and hidden from the consumer API; reviewable on Archived"},
     {"key": "keep", "label": "Keep it", "returns": "The hold is released; the course stays as it is"}]},
   "fee_check": {"label": "Fee fails the check", "order": 11, "choices": [
     {"key": "course", "label": "Open the course", "link": "course", "returns": "Enter or confirm the fee on the course"},
     {"key": "keep", "label": "Keep the CRICOS total", "returns": "The hold is released; the page fee stays out"}]},
   "counsellor_report": {"label": "Counsellor report", "order": 12, "choices": [
     {"key": "report_fixed", "label": "Fixed", "returns": "Closed as fixed with your note; Zoho shows the outcome to the counsellor"},
     {"key": "report_not_changed", "label": "Not changed", "returns": "Closed as not changed with your reason; Zoho shows it to the counsellor"},
     {"key": "course", "label": "Open the course", "link": "course", "returns": "Correct the value on the course, then close the report here"}]},
   "not_on_site": {"label": "Course not on the university''s site", "order": 13, "choices": [
     {"key": "archive_course", "label": "Archive the course", "rank": 5, "returns": "Unpublished and hidden from the consumer API; reviewable on Archived"},
     {"key": "keep", "label": "Keep it", "returns": "The hold is released; CRICOS still lists it"},
     {"key": "course", "label": "Open the course", "link": "course", "returns": "Enter its page on the course"}]},
   "no_page_first_run": {"label": "No page published: first run", "order": 15, "choices": [
     {"key": "approve", "label": "Approve: none has its own page", "returns": "The sample is recorded as no page published; at the 60% rule the university is trusted and its later cases are recorded without a person; any page found later re-opens a course"},
     {"key": "has_page", "label": "Approve, except courses that have a page", "input": "courses", "returns": "The ticked courses keep looking for their page; the others are recorded; the university is trusted only at the 60% rule"},
     {"key": "reject", "label": "Reject", "returns": "Nothing is recorded and the university is not trusted; its courses keep looking for their pages"}]},
   "conjoint_first_run": {"label": "Conjoint or double degrees: first run", "order": 16, "choices": [
     {"key": "approve", "label": "Approve: no page of their own", "returns": "The conjoint degrees of this university leave the course search, recorded as conjoint; any page found later re-opens a course"},
     {"key": "parent", "label": "Approve with their shared page", "input": "url", "returns": "Recorded as conjoint, with this address as their shared conjoint page"},
     {"key": "reject", "label": "Reject", "returns": "Nothing is recorded; the conjoint degrees keep looking for their pages"}]},
   "aer_review": {"label": "Entry requirements (AER)", "order": 17, "choices": [
     {"key": "approve", "label": "Approve all rows", "rank": 6, "returns": "Every waiting row becomes active once the identity, completeness, scale and basis checks pass; the source''s earlier rows are superseded"},
     {"key": "approve_except", "label": "Approve except…", "rank": 6, "input": "rows", "returns": "The ticked rows stay unadmitted, marked excluded with your reason; every other row becomes active once the same checks pass. An earlier active row is replaced only by an approved row with its identity; one whose replacement you leave out stays active (D4)"},
     {"key": "reject", "label": "Reject the read", "rank": 6, "returns": "No row is admitted; every waiting row is withdrawn with your reason"}]},
   "provider_description": {"label": "University description", "order": 18, "choices": [
     {"key": "approve", "label": "Approve as read", "returns": "The description is published as read from the official page (every sentence quoted from it); the website shows it from its next read"},
     {"key": "reject", "label": "Reject", "returns": "Nothing is published; the university is read again after the set wait"}]},
   "course_page_needed": {"label": "Course page needed", "order": 19, "choices": [
     {"key": "add_page", "label": "Add the page", "input": "url", "returns": "The verified page becomes the course''s official page (a person''s value, never overwritten); it is read first in line"},
     {"key": "search_again", "label": "Search again", "returns": "The course-link search looks for the page again within its own limits; the course comes back here if the next page found is refused"},
     {"key": "no_page", "label": "No page exists", "input": "url", "returns": "Recorded as no page of its own, with the address you give as evidence; searching stops until a page is found"}]},
   "provider_departure": {"label": "Provider left the register", "order": 14, "choices": [
     {"key": "closed", "label": "Closed: archive it", "rank": 6, "returns": "Archived through the clean-up workflow and hidden from the consumer API"},
     {"key": "merged", "label": "Merged into another provider", "rank": 6, "input": "provider", "returns": "Archived, and the merger recorded with its successor"},
     {"key": "reviewed", "label": "Still operating: keep it", "rank": 6, "returns": "Closed; the provider stays as it is"}]}
  }'::jsonb
$$;


ALTER FUNCTION "security"."layer4_inbox_kinds_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_intervention_inbox_counts_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with o as (select i.provider_id, i.created_at from pipeline.layer4_interventions i where i.status = 'awaiting_input')
  select jsonb_build_object('kind', 'intervention', 'n', (select count(*) from o), 'oldest', (select min(o.created_at) from o),
    'late', (select count(*) from o where o.created_at < now() - make_interval(days => security.pipeline_num_v1('layer4.target_days', 7)::int)),
    'by_provider', coalesce((select jsonb_agg(jsonb_build_object('provider_id', z.provider_id, 'n', z.n, 'oldest', z.oldest) order by z.oldest)
                               from (select o.provider_id, count(*) n, min(o.created_at) oldest from o group by 1) z), '[]'::jsonb))
$$;


ALTER FUNCTION "security"."layer4_intervention_inbox_counts_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_intervention_inbox_decide_v1"("p_ref" "text", "p_choice" "text", "p_value" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_r jsonb; v_ev bigint; v_pid uuid;
begin
  v_r := security.layer4_intervention_resolve_v1(p_ref::bigint, p_choice, jsonb_build_object('value', p_value, 'reason', p_reason));
  select provider_id into v_pid from pipeline.layer4_interventions where id = p_ref::bigint;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('layer4', 'inbox_decide', 'intervention:' || p_ref, jsonb_build_object('kind', 'intervention', 'ref', p_ref, 'choice', p_choice, 'value', p_value, 'reason', p_reason,
          'provider_id', v_pid, 'result', v_r), auth.uid()) returning id into v_ev;
  return jsonb_build_object('ok', coalesce((v_r->>'ok')::boolean, false), 'kind', 'intervention', 'choice', p_choice, 'ref', p_ref, 'event_id', v_ev, 'result', v_r,
                            'returns', v_r->>'returns', 'request', v_r->>'request');
end $$;


ALTER FUNCTION "security"."layer4_intervention_inbox_decide_v1"("p_ref" "text", "p_choice" "text", "p_value" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_intervention_inbox_detail_v1"("p_ref" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('sections', jsonb_build_array(
      jsonb_build_object('key', 'issue', 'title', 'Issue summary', 'body', jsonb_strip_nulls(jsonb_build_object(
        'What is missing', c.title, 'Record', i.subject, 'What the platform attempted', i.issue->'attempted', 'Why it could not finish', i.issue->>'why_stopped',
        'Impact', i.issue->>'impact', 'Automatic attempts', i.automated_attempts, 'Seen again unchanged', i.repeat_count, 'Reopened', i.reopen_count))),
      jsonb_build_object('key', 'evidence', 'title', 'Evidence', 'body', jsonb_strip_nulls(jsonb_build_object(
        'Official links', i.evidence->'official_links', 'Stored copies', i.evidence->'stored_copies', 'Quotations', i.evidence->'quotes',
        'Previous attempts', i.evidence->'attempts', 'Conflicts or missing information', i.evidence->'conflicts',
        'AI analysis', case when i.ai_analysis is not null then jsonb_strip_nulls(jsonb_build_object('analysis', i.ai_analysis->>'analysis', 'confidence', i.ai_analysis->'confidence',
                                                                                  'uncertainty', i.ai_analysis->'uncertainty', 'refused', i.ai_analysis->'refused', 'skipped', i.ai_analysis->'skipped')) end))),
      jsonb_build_object('key', 'recommended', 'title', 'Recommended intervention', 'body', jsonb_strip_nulls(jsonb_build_object(
        'Next best action', (select ch->>'label' from jsonb_array_elements(security.layer4_intervention_kind_v1()->'choices') ch where ch->>'key' = i.recommended->>'action'),
        'Information needed', i.required_input->>'ask', 'Still needed after the last answer', i.required_input->>'follow_up',
        'Suggested answer', i.recommended->'suggested', 'How this unblocks processing', i.recommended->>'unblocks'))),
      jsonb_build_object('key', 'resolution', 'title', 'Resolution', 'body', jsonb_strip_nulls(jsonb_build_object(
        'Status', i.status, 'Responsible', i.assigned_to, 'Work resumed on an answer', i.resume_target->>'operation', 'Escalated if unanswered by', i.escalate_at,
        'Recovery deadline', i.recover_by, 'Verified outcome', i.verified_outcome, 'Admitted', i.admitted_at, 'Published', i.published_at,
        'Audit', (select coalesce(jsonb_agg(jsonb_build_object('at', e.at, 'by', e.actor_label, 'rank', e.role_rank, 'action', e.action, 'request', e.result->>'request') order by e.id desc), '[]'::jsonb)
                    from (select * from pipeline.layer4_intervention_events e where e.intervention_id = i.id order by e.id desc
                           limit security.pipeline_num_v1('har.history_items', 3)::int) e))))),
    'actions', (select coalesce(jsonb_agg(jsonb_build_object('key', ch->>'key', 'allowed', security.current_role_rank() >= (i.allowed_actions->>(ch->>'key'))::int,
                                                             'why', case when security.current_role_rank() < (i.allowed_actions->>(ch->>'key'))::int
                                                                         then 'needs rank ' || (i.allowed_actions->>(ch->>'key')) end)), '[]'::jsonb)
                  from jsonb_array_elements(security.layer4_intervention_kind_v1()->'choices') ch where i.allowed_actions ? (ch->>'key')))
    from pipeline.layer4_interventions i join pipeline.layer4_intervention_classes c on c.code = i.missing_fact
   where i.id::text = p_ref
$$;


ALTER FUNCTION "security"."layer4_intervention_inbox_detail_v1"("p_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_intervention_inbox_page_v1"("p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with x as (select i.id, i.provider_id, i.subject, i.missing_fact, i.created_at, coalesce(i.required_input->>'follow_up', i.issue->>'why_stopped', i.issue->>'summary') why,
                    i.recommended->>'action' suggestion, i.recover_by
               from pipeline.layer4_interventions i
              where i.status = 'awaiting_input'
                and (nullif(p_args->>'provider_id', '') is null or i.provider_id = (p_args->>'provider_id')::uuid)
                and (nullif(p_args->>'after_ref', '') is null or (i.created_at, i.id) > ((p_args->>'after_at')::timestamptz, (p_args->>'after_ref')::bigint))
              order by i.created_at, i.id
              limit least(greatest(coalesce((p_args->>'limit')::int, 50), 1), 200))  -- fixed: page size bounds, as the Inbox's own
  select jsonb_build_object('kind', 'intervention',
    -- the paging contract's "before": this kind's items for the same university at or before the cursor
    'before', case when nullif(p_args->>'after_ref', '') is not null then
                (select count(*) from pipeline.layer4_interventions b where b.status = 'awaiting_input'
                    and (nullif(p_args->>'provider_id', '') is null or b.provider_id = (p_args->>'provider_id')::uuid)
                    and (b.created_at, b.id) <= ((p_args->>'after_at')::timestamptz, (p_args->>'after_ref')::bigint)) end,
    'items', coalesce(jsonb_agg(jsonb_build_object('kind', 'intervention', 'ref', x.id::text, 'provider_id', x.provider_id,
           'provider', (select coalesce(p.display_name, p.canonical_name) from catalogue.providers p where p.id = x.provider_id), 'subject', x.subject, 'why', x.why,
           'suggestion', x.suggestion, 'created_at', x.created_at, 'missing_fact', x.missing_fact,
           'late', x.created_at < now() - make_interval(days => security.pipeline_num_v1('layer4.target_days', 7)::int), 'overdue', x.recover_by < now()) order by x.created_at, x.id), '[]'::jsonb))
    from x
$$;


ALTER FUNCTION "security"."layer4_intervention_inbox_page_v1"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_intervention_kind_v1"() RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select '{"label": "Human input needed", "order": 20, "choices": [
     {"key": "provide_url", "label": "Give the official address", "input": "url", "returns": "Checked to be on the provider''s own website, then the work resumes by itself. An address is not approval to publish"},
     {"key": "attach_document", "label": "Give the document", "input": "url", "returns": "The official document is checked and read by the existing reader; what it finds is still reviewed before anything is admitted"},
     {"key": "select_source", "label": "Choose the authoritative source", "input": "url", "returns": "That source is used and read again; other sources stay as they are"},
     {"key": "enter_value", "label": "Enter the missing information", "input": "text", "returns": "Checked like an extracted value (quotation, official page, field rules) and handed to the lane''s own checks; it is a proposal, not an admitted value"},
     {"key": "correct_value", "label": "Correct the value against the quotation", "input": "text", "returns": "Your correction and its quotation are checked and handed back; the usual checks still decide"},
     {"key": "confirm_identity", "label": "Confirm the identity", "input": "text", "returns": "The provider, course or scholarship you name is checked and the work resumes for it"},
     {"key": "confirm_scope", "label": "Confirm who or what it applies to", "input": "text", "returns": "Your answer and its quotation are kept as evidence and the work resumes"},
     {"key": "search_again", "label": "Search again", "returns": "The automatic search runs again within its own limits"},
     {"key": "confirm_not_published", "label": "Confirm it is not published", "input": "url", "rank": 5, "returns": "Closed as not published, with the official page you give as evidence; asked again only if that changes"},
     {"key": "return_technical", "label": "Return to technical recovery", "returns": "The work goes back to its technical recovery; the same failure is not asked again unless it changes"},
     {"key": "reject_evidence", "label": "Reject this evidence", "returns": "The evidence or suggestion shown is refused and kept on record; the item still waits for the missing input"}]}'::jsonb
$$;


ALTER FUNCTION "security"."layer4_intervention_kind_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_intervention_raise_v1"("p" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c pipeline.layer4_intervention_classes; i pipeline.layer4_interventions; v_fp text; v_ent text := nullif(btrim(coalesce(p->>'entity', '')), '');
        v_att int := coalesce((p->>'attempts')::int, 0); v_wi jsonb; v_wid bigint; v_status text; v_was text; v_ev jsonb; v_issue jsonb; v_req jsonb; v_rec jsonb; v_res jsonb;
begin
  if security.pipeline_num_v1('har.on', 1) < 1 then return jsonb_build_object('raised', false, 'reason', 'har.on is 0'); end if;
  select * into c from pipeline.layer4_intervention_classes where code = p->>'class';
  if not found then raise exception 'unknown intervention class %', p->>'class' using errcode = '22023'; end if;
  if v_ent is null then raise exception 'an intervention needs its entity' using errcode = '22023'; end if;
  if v_att < security.har_num_v1(c.code, 'max_attempts', 1) then
    return jsonb_build_object('raised', false, 'reason', 'automated recovery has not used its attempts (' || v_att || ')');
  end if;
  v_fp := md5(c.code || '|' || coalesce(p->>'signature', (p->'evidence')::text, ''));
  v_ev := jsonb_build_object('official_links', security.har_cap_v1(p->'evidence'->'official_links'), 'stored_copies', security.har_cap_v1(p->'evidence'->'stored_copies'),
                             'quotes', security.har_cap_v1(p->'evidence'->'quotes'), 'attempts', security.har_cap_v1(p->'evidence'->'attempts'),
                             'conflicts', security.har_cap_v1(p->'evidence'->'conflicts'));
  v_issue := jsonb_build_object('summary', coalesce(p->'issue'->>'summary', c.title), 'attempted', security.har_cap_v1(p->'issue'->'attempted'),
                                'why_stopped', coalesce(p->'issue'->>'why_stopped', c.title), 'impact', p->'issue'->>'impact');
  v_req := jsonb_build_object('ask', c.required_input, 'accepts', (select jsonb_agg(k order by k) from jsonb_object_keys(c.allowed_actions) k));
  v_rec := jsonb_build_object('action', c.recommended_action, 'summary', c.required_input, 'suggested', p->'suggested', 'unblocks', c.unblocks);
  v_wi := coalesce(p->'resume_target'->'work_item', jsonb_build_object('lane', c.lane, 'entity', v_ent, 'kind', c.code));
  perform pg_advisory_xact_lock(hashtext('cf247:har:' || c.lane || ':' || v_ent || ':' || c.code));  -- fixed: one writer per intervention
  select * into i from pipeline.layer4_interventions x where x.lane = c.lane and x.entity = v_ent and x.missing_fact = c.code for update;
  if found then
    if i.status in ('ai_pending', 'awaiting_input', 'resuming') and i.fingerprint = v_fp
       or i.status not in ('ai_pending', 'awaiting_input', 'resuming') and i.closed_fingerprint = v_fp then
      update pipeline.layer4_interventions set repeat_count = repeat_count + 1, last_seen_at = now() where id = i.id;
      return jsonb_build_object('raised', false, 'id', i.id, 'repeat', true, 'status', i.status);
    end if;
    if i.status = 'resuming' then  -- the result of the resumed work decides (security.layer4_interventions_tick_v1)
      update pipeline.layer4_interventions set last_seen_at = now() where id = i.id;
      return jsonb_build_object('raised', false, 'id', i.id, 'status', i.status, 'reason', 'resumed work is being verified');
    end if;
    v_was := i.status;
    v_status := case when i.status in ('ai_pending', 'awaiting_input') then i.status
                     when c.interpretative and security.pipeline_num_v1('har.ai_escalate_on', 0) >= 1 then 'ai_pending' else 'awaiting_input' end;
    update pipeline.layer4_interventions set status = v_status, issue = v_issue, evidence = v_ev, fingerprint = v_fp, automated_attempts = v_att,
           reopen_count = reopen_count + case when i.status in ('ai_pending', 'awaiting_input') then 0 else 1 end,
           required_input = v_req, recommended = v_rec, allowed_actions = c.allowed_actions, resume_target = jsonb_build_object('operation', p->'resume_target'->>'operation', 'work_item', v_wi),
           subject = coalesce(nullif(p->>'subject', ''), subject), last_seen_at = now(), updated_at = now(),
           next_action_at = now() + make_interval(hours => security.har_num_v1(c.code, 'recheck_hours', 24)::int),
           escalate_at = case when i.status in ('ai_pending', 'awaiting_input') then escalate_at else now() + make_interval(hours => security.har_num_v1(c.code, 'escalate_after_hours', 72)::int) end,
           recover_by = case when i.status in ('ai_pending', 'awaiting_input') then recover_by else now() + make_interval(hours => security.har_num_v1(c.code, 'deadline_hours', 168)::int) end,
           escalated_at = case when i.status in ('ai_pending', 'awaiting_input') then escalated_at end
     where id = i.id returning * into i;
    perform security.har_event_v1(i.id, case when v_was in ('ai_pending', 'awaiting_input') then 'evidence_changed' else 'reopened' end,
                                  jsonb_build_object('signature', p->>'signature'), jsonb_build_object('fingerprint', v_fp), v_was, v_status);
  else
    if (select count(*) from pipeline.layer4_interventions x where x.lane = c.lane and x.status in ('ai_pending', 'awaiting_input'))
         >= security.pipeline_num_v1('har.open_max_per_lane', 150) then
      return jsonb_build_object('raised', false, 'reason', 'lane ' || c.lane || ' is at its open limit (har.open_max_per_lane)');
    end if;
    v_status := case when c.interpretative and security.pipeline_num_v1('har.ai_escalate_on', 0) >= 1 then 'ai_pending' else 'awaiting_input' end;
    insert into pipeline.layer4_interventions(lane, entity, missing_fact, provider_id, course_id, field, subject, status, issue, evidence, required_input, recommended,
                allowed_actions, resume_target, fingerprint, automated_attempts, assigned_to, next_action_at, escalate_at, recover_by)
    values (c.lane, v_ent, c.code, nullif(p->>'provider_id', '')::uuid, nullif(p->>'course_id', '')::uuid, nullif(p->>'field', ''), coalesce(nullif(p->>'subject', ''), c.title),
            v_status, v_issue, v_ev, v_req, v_rec, c.allowed_actions, jsonb_build_object('operation', p->'resume_target'->>'operation', 'work_item', v_wi), v_fp, v_att,
            security.har_text_v1('har.' || c.code || '.assigned_to', 'Layer 4 reviewer'),
            now() + make_interval(hours => security.har_num_v1(c.code, 'recheck_hours', 24)::int),
            now() + make_interval(hours => security.har_num_v1(c.code, 'escalate_after_hours', 72)::int),
            now() + make_interval(hours => security.har_num_v1(c.code, 'deadline_hours', 168)::int))
    returning * into i;
    perform security.har_event_v1(i.id, 'raised', jsonb_build_object('class', c.code, 'attempts', v_att), jsonb_build_object('fingerprint', v_fp), null, v_status);
  end if;
  -- §6: the work waits for the person without a lease or a next attempt; other work continues
  v_res := security.work_item_report_v1(v_wi->>'lane', v_wi->>'entity', v_wi->>'kind', 'review',
             jsonb_build_object('review_ref', 'intervention:' || i.id, 'provider_id', i.provider_id, 'field', i.field, 'owner', 'layer4_intervention',
                                'reason', 'waiting for human input: ' || c.title));
  select w.id into v_wid from pipeline.work_items w where w.lane = v_wi->>'lane' and w.entity = v_wi->>'entity' and w.work_kind = v_wi->>'kind';
  update pipeline.layer4_interventions set work_item_id = v_wid where id = i.id and work_item_id is distinct from v_wid;
  return jsonb_build_object('raised', true, 'id', i.id, 'status', i.status, 'work_item', v_wid);
end $$;


ALTER FUNCTION "security"."layer4_intervention_raise_v1"("p" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."layer4_intervention_raise_v1"("p" "jsonb") IS 'CF-247 human-assisted recovery (decision 06:30 §1 steps 6-8): the one way a lane asks for human input; deduplicated by (lane, entity, missing fact) and the failure''s fingerprint; links the work item (awaiting review, no lease). Lanes outside AER and scholarships call it from their own failure handling.';



CREATE OR REPLACE FUNCTION "security"."layer4_intervention_report_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with x as (select i.*, c.workstream from pipeline.layer4_interventions i join pipeline.layer4_intervention_classes c on c.code = i.missing_fact),
  w as (select x.workstream,
               count(*) filter (where x.status = 'auto_resolved') auto_resolved,
               count(*) filter (where x.status in ('ai_pending', 'awaiting_input')) human_input_needed,
               count(*) filter (where x.input_at is not null) human_resolved,
               count(*) filter (where x.resumed_at is not null) resumed,
               count(*) filter (where x.admitted_at is not null) admitted,
               count(*) filter (where x.published_at is not null) published,
               count(*) filter (where x.status in ('ai_pending', 'awaiting_input', 'resuming')) still_blocked,
               count(*) filter (where x.status = 'resolved') verified,
               count(*) filter (where x.status = 'not_published') not_published,
               count(*) filter (where x.status = 'returned_technical') returned_technical,
               count(*) filter (where x.status in ('ai_pending', 'awaiting_input', 'resuming') and x.recover_by < now()) overdue,
               round(avg(extract(epoch from x.resumed_at - x.created_at) / 60) filter (where x.resumed_at is not null), 1) avg_minutes_to_resume,
               round(avg(extract(epoch from now() - x.created_at) / 3600) filter (where x.status in ('ai_pending', 'awaiting_input', 'resuming')), 1) avg_open_age_hours,
               round(max(extract(epoch from now() - x.created_at) / 3600) filter (where x.status in ('ai_pending', 'awaiting_input', 'resuming')), 1) max_open_age_hours,
               sum(x.repeat_count) repeats_not_raised, sum(x.reopen_count) reopened
          from x group by 1)
  select jsonb_build_object('at', now(),
    'switches', jsonb_build_object('on', security.pipeline_num_v1('har.on', 1), 'aer', security.pipeline_num_v1('har.generate_aer_on', 1),
                                   'scholarships', security.pipeline_num_v1('har.generate_sch_on', 1), 'resume', security.pipeline_num_v1('har.resume_on', 1),
                                   'ai_escalation', security.pipeline_num_v1('har.ai_escalate_on', 0)),
    'workstreams', coalesce((select jsonb_agg(jsonb_build_object('workstream', w.workstream, 'automatically_resolved', w.auto_resolved, 'human_input_needed', w.human_input_needed,
                     'human_resolved', w.human_resolved, 'resumed', w.resumed, 'admitted', w.admitted, 'published', w.published, 'still_blocked', w.still_blocked,
                     'verified', w.verified, 'not_published', w.not_published, 'returned_technical', w.returned_technical, 'overdue', w.overdue,
                     'avg_minutes_to_resume', w.avg_minutes_to_resume, 'avg_open_age_hours', w.avg_open_age_hours, 'max_open_age_hours', w.max_open_age_hours,
                     'recovery_success_rate', case when w.human_resolved > 0 then round(w.verified::numeric / w.human_resolved, 3) end,
                     'repeats_not_raised', w.repeats_not_raised, 'reopened', w.reopened) order by w.workstream) from w), '[]'::jsonb),
    'open_by_class', coalesce((select jsonb_object_agg(z.missing_fact, z.n) from (select x.missing_fact, count(*) n from x where x.status in ('ai_pending', 'awaiting_input') group by 1) z), '{}'::jsonb))
$$;


ALTER FUNCTION "security"."layer4_intervention_report_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."layer4_intervention_report_v1"() IS 'CF-247 human-assisted recovery (decision 06:30 §9): the recovery metrics per workstream; a section (human_assisted_recovery) of security.ops_report_v1.';



CREATE OR REPLACE FUNCTION "security"."layer4_intervention_resolve_v1"("p_id" bigint, "p_action" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare i pipeline.layer4_interventions; c pipeline.layer4_intervention_classes; h pipeline.layer4_intervention_handlers; v_rank int; v_need int;
        v_reason text := btrim(coalesce(p_payload->>'reason', '')); v_valid jsonb; v_res jsonb; v_vid bigint; v_norm jsonb; v_out jsonb;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode = '42501'; end if;
  if security.pipeline_num_v1('har.on', 1) < 1 then raise exception 'human-assisted recovery is switched off (har.on is 0)'; end if;
  if coalesce(p_action, '') not in ('provide_url', 'attach_document', 'enter_value', 'confirm_identity', 'select_source', 'confirm_scope', 'correct_value',
                                    'search_again', 'confirm_not_published', 'return_technical', 'reject_evidence') then
    raise exception 'unknown action %', p_action using errcode = '22023';
  end if;
  v_rank := security.current_role_rank();
  select * into i from pipeline.layer4_interventions where id = p_id for update;
  if not found then raise exception 'no intervention %', p_id using errcode = 'P0002'; end if;
  if i.status <> 'awaiting_input' then raise exception 'this intervention is no longer waiting for input (%)', i.status; end if;
  if not (i.allowed_actions ? p_action) then raise exception 'this action is not offered for this intervention'; end if;
  v_need := (i.allowed_actions->>p_action)::int;
  if v_rank < v_need then raise exception 'your role cannot take this action (it needs rank %)', v_need using errcode = '42501'; end if;
  if length(v_reason) < 4 then raise exception 'give a reason (kept with the decision)'; end if;
  select * into c from pipeline.layer4_intervention_classes where code = i.missing_fact;
  select * into h from pipeline.layer4_intervention_handlers where lane = i.lane;
  if not found then raise exception 'no resume handler is registered for lane %', i.lane; end if;

  if p_action = 'return_technical' then
    update pipeline.layer4_interventions set status = 'returned_technical', closed_fingerprint = fingerprint, resolved_by = auth.uid(), input_at = now(),
           verified_outcome = 'returned_to_technical_recovery', outcome_detail = jsonb_build_object('reason', v_reason), updated_at = now() where id = i.id;
    perform security.har_work_item_v1(i.id, 'decided', '{}'::jsonb);
    perform security.har_event_v1(i.id, p_action, p_payload, '{}'::jsonb, i.status, 'returned_technical');
    return jsonb_build_object('ok', true, 'status', 'returned_technical', 'returns', 'The work goes back to its technical recovery; the same failure is not asked again unless it changes');
  elsif p_action = 'reject_evidence' then
    update pipeline.layer4_interventions set ai_analysis = coalesce(ai_analysis, '{}'::jsonb) || jsonb_build_object('rejected_by_reviewer', jsonb_build_object('at', now(), 'reason', v_reason)),
           recommended = (recommended - 'suggested') || jsonb_build_object('rejected_suggestion', recommended->'suggested'), updated_at = now() where id = i.id;
    perform security.har_event_v1(i.id, p_action, p_payload, '{}'::jsonb, i.status, i.status);
    return jsonb_build_object('ok', true, 'status', 'awaiting_input', 'returns', 'The evidence or suggestion is refused and kept on record; the item still waits for the missing input');
  elsif p_action = 'confirm_not_published' then
    v_valid := security.har_official_url_v1(p_payload->>'value', i.provider_id);
    if not coalesce((v_valid->>'ok')::boolean, false) then
      update pipeline.layer4_interventions set required_input = required_input || jsonb_build_object('follow_up', 'Evidence for "not published": ' || (v_valid->>'reason'), 'follow_up_at', now()),
             updated_at = now() where id = i.id;
      perform security.har_event_v1(i.id, 'insufficient', p_payload, v_valid, i.status, i.status);
      return jsonb_build_object('ok', false, 'status', 'awaiting_input', 'request', v_valid->>'reason');
    end if;
    insert into pipeline.layer4_intervention_values(intervention_id, lane, entity, field, value, quote, source_url, evidence_id, actor, state, state_at)
    values (i.id, i.lane, i.entity, 'not_published', jsonb_build_object('confirmed', true, 'reason', v_reason), p_payload->>'quote', v_valid->>'url',
            nullif(v_valid->>'stored_copy', '')::uuid, auth.uid(), 'proposed', now()) returning id into v_vid;
    update pipeline.layer4_interventions set status = 'not_published', closed_fingerprint = fingerprint, resolved_by = auth.uid(), input_at = now(), verified_at = now(),
           verified_outcome = 'evidenced_not_published', supplied = jsonb_build_object('value_id', v_vid, 'evidence_url', v_valid->>'url'), updated_at = now() where id = i.id;
    perform security.har_work_item_v1(i.id, 'succeeded', jsonb_build_object('outcome', 'not_needed'));
    perform security.har_event_v1(i.id, p_action, p_payload, v_valid, i.status, 'not_published');
    return jsonb_build_object('ok', true, 'status', 'not_published', 'returns', 'Recorded as not published, with your evidence; nothing is admitted or published');
  end if;

  -- the lane's validator: identity, official host, provenance, field rules, ownership
  execute format('select %s($1, $2, $3)', (h.validate_fn::oid)::regproc) into v_valid using i.id, p_action, p_payload;
  if not coalesce((v_valid->>'valid')::boolean, false) then
    update pipeline.layer4_interventions set required_input = required_input || jsonb_build_object('follow_up', coalesce(v_valid->>'request', 'the input could not be validated'), 'follow_up_at', now()),
           updated_at = now() where id = i.id;
    perform security.har_event_v1(i.id, 'insufficient', p_payload, v_valid, i.status, i.status);
    return jsonb_build_object('ok', false, 'status', 'awaiting_input', 'request', v_valid->>'request');
  end if;
  v_norm := coalesce(v_valid->'normalised', '{}'::jsonb);
  insert into pipeline.layer4_intervention_values(intervention_id, lane, entity, field, value, quote, source_url, evidence_id, actor)
  values (i.id, i.lane, i.entity, coalesce(v_norm->>'field', p_action), v_norm, v_norm->>'quote', v_norm->>'url', nullif(v_norm->>'stored_copy', '')::uuid, auth.uid())
  returning id into v_vid;
  update pipeline.layer4_interventions set status = 'resuming', supplied = v_norm || jsonb_build_object('action', p_action, 'value_id', v_vid, 'reason', v_reason),
         resolved_by = auth.uid(), input_at = now(), required_input = required_input - 'follow_up' - 'follow_up_at',
         next_action_at = now() + make_interval(hours => security.pipeline_num_v1('har.verify_after_hours', 24)::int), updated_at = now() where id = i.id;
  if security.pipeline_num_v1('har.resume_on', 1) >= 1 then
    execute format('select %s($1, $2, $3)', (h.resume_fn::oid)::regproc) into v_res using i.id, p_action, v_norm;
  else
    v_res := jsonb_build_object('scheduled', false, 'held', 'har.resume_on is 0: the valid input waits');
  end if;
  update pipeline.layer4_interventions set resumed_at = case when coalesce((v_res->>'scheduled')::boolean, false) then now() end,
         outcome_detail = jsonb_build_object('resume', v_res), updated_at = now() where id = i.id;
  perform security.har_work_item_v1(i.id, 'decided', '{}'::jsonb);  -- the dependency is resolved: the lane may take its work again
  v_out := jsonb_build_object('ok', true, 'status', 'resuming', 'validation', v_valid, 'resume', v_res, 'returns', c.unblocks);
  perform security.har_event_v1(i.id, p_action, p_payload, v_out, i.status, 'resuming');
  return v_out;
end $_$;


ALTER FUNCTION "security"."layer4_intervention_resolve_v1"("p_id" bigint, "p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."layer4_intervention_resolve_v1"("p_id" bigint, "p_action" "text", "p_payload" "jsonb") IS 'CF-247 human-assisted recovery (decision 06:30 §2, §7): the one server function behind the eleven reviewer actions on a "Human input needed" item; validates through the lane''s handler, records provenance, resumes the work; never admits or publishes; audited.';



CREATE OR REPLACE FUNCTION "security"."layer4_interventions_tick_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare h record; r record; v jsonb; v_gen jsonb := '{}'::jsonb; v_ai jsonb; v_lim int := security.pipeline_num_v1('batch.har_generate', 40)::int;
        v_vlim int := security.pipeline_num_v1('batch.har_verify', 200)::int; v_ok int := 0; v_back int := 0; v_wait int := 0; v_clear int := 0; v_esc int := 0; v_err int := 0;
        v_issue bigint; v_req text;
begin
  if security.pipeline_num_v1('har.on', 1) < 1 then return jsonb_build_object('held', 'har.on is 0'); end if;
  for h in select * from pipeline.layer4_intervention_handlers x where x.generate_fn is not null order by x.lane loop
    if h.generate_switch is not null and security.pipeline_num_v1(h.generate_switch, 0) < 1 then
      v_gen := v_gen || jsonb_build_object(h.lane, jsonb_build_object('held', h.generate_switch || ' is 0')); continue;
    end if;
    begin
      execute format('select %s($1)', (h.generate_fn::oid)::regproc) into v using v_lim;
      v_gen := v_gen || jsonb_build_object(h.lane, v);
    exception when others then v_gen := v_gen || jsonb_build_object(h.lane, jsonb_build_object('error', left(sqlerrm, 200)));
    end;
  end loop;
  begin v_ai := security.har_ai_tick_v1(); exception when others then v_ai := jsonb_build_object('error', left(sqlerrm, 200)); end;

  for r in select i.id, i.lane, i.missing_fact, i.next_action_at, i.integration_issue_id, x.verify_fn from pipeline.layer4_interventions i
             join pipeline.layer4_intervention_handlers x on x.lane = i.lane where i.status = 'resuming' order by i.updated_at limit v_vlim loop
    begin
      execute format('select %s($1)', (r.verify_fn::oid)::regproc) into v using r.id;
      if v->>'state' = 'succeeded' then
        update pipeline.layer4_interventions set status = 'resolved', closed_fingerprint = fingerprint, verified_at = now(),
               verified_outcome = coalesce(v->>'outcome', 'succeeded_with_result'),
               admitted_at = case when coalesce((v->>'admitted')::boolean, false) then coalesce(admitted_at, now()) end,
               published_at = case when coalesce((v->>'published')::boolean, false) then coalesce(published_at, now()) end,
               outcome_detail = coalesce(outcome_detail, '{}'::jsonb) || jsonb_build_object('verify', v), updated_at = now() where id = r.id;
        perform security.har_work_item_v1(r.id, 'succeeded', jsonb_build_object('outcome', 'succeeded_with_result'));
        perform security.har_event_v1(r.id, 'verified', '{}'::jsonb, v, 'resuming', 'resolved');
        if r.integration_issue_id is not null and not exists (select 1 from pipeline.layer4_interventions x where x.integration_issue_id = r.integration_issue_id
                                                                and x.status in ('ai_pending', 'awaiting_input', 'resuming')) then
          perform security.integration_issue_close_v1(r.integration_issue_id, 'layer4-interventions', jsonb_build_object('outcome', 'passed', 'checked_at', now(),
                    'evidence', 'Every intervention of this class was answered and its resumed work verified by security.layer4_interventions_tick_v1 (last: intervention ' || r.id || ').',
                    'verify', v));
        end if;
        v_ok := v_ok + 1;
      elsif v->>'state' = 'failed' or r.next_action_at < now() then
        v_req := coalesce(v->>'request', 'The input was taken, but the resumed work has not produced its result (' || coalesce(v->>'evidence', v::text) || '). Check the input or give another source.');
        update pipeline.layer4_interventions set status = 'awaiting_input', reopen_count = reopen_count + 1,
               required_input = required_input || jsonb_build_object('follow_up', left(v_req, 600), 'follow_up_at', now()),
               outcome_detail = coalesce(outcome_detail, '{}'::jsonb) || jsonb_build_object('verify', v),
               next_action_at = now() + make_interval(hours => security.har_num_v1(missing_fact, 'recheck_hours', 24)::int), updated_at = now() where id = r.id;
        perform security.har_work_item_v1(r.id, 'review', jsonb_build_object('review_ref', 'intervention:' || r.id, 'reason', 'resumed work did not produce its result'));
        perform security.har_event_v1(r.id, 'resume_failed', '{}'::jsonb, v, 'resuming', 'awaiting_input');
        if r.integration_issue_id is not null then
          v_issue := security.har_class_issue_v1(r.lane, r.missing_fact, 'resumed work failed verification (intervention ' || r.id || ')');
        end if;
        v_back := v_back + 1;
      else
        v_wait := v_wait + 1;
      end if;
    exception when others then v_err := v_err + 1;
      perform security.har_event_v1(r.id, 'verify_error', '{}'::jsonb, jsonb_build_object('error', left(sqlerrm, 300)), 'resuming', 'resuming');
    end;
  end loop;

  for r in select i.id, i.status, i.missing_fact, x.recheck_fn from pipeline.layer4_interventions i join pipeline.layer4_intervention_handlers x on x.lane = i.lane
            where i.status in ('ai_pending', 'awaiting_input') and i.next_action_at <= now() order by i.next_action_at limit v_vlim loop
    begin
      execute format('select %s($1)', (r.recheck_fn::oid)::regproc) into v using r.id;
      if coalesce((v->>'cleared')::boolean, false) then
        update pipeline.layer4_interventions set status = 'auto_resolved', closed_fingerprint = fingerprint, verified_at = now(), verified_outcome = 'cleared_without_input',
               outcome_detail = coalesce(outcome_detail, '{}'::jsonb) || jsonb_build_object('recheck', v), updated_at = now() where id = r.id;
        perform security.har_work_item_v1(r.id, 'decided', '{}'::jsonb);
        perform security.har_event_v1(r.id, 'recheck_cleared', '{}'::jsonb, v, r.status, 'auto_resolved');
        v_clear := v_clear + 1;
      else
        update pipeline.layer4_interventions set next_action_at = now() + make_interval(hours => security.har_num_v1(r.missing_fact, 'recheck_hours', 24)::int) where id = r.id;
      end if;
    exception when others then v_err := v_err + 1;
    end;
  end loop;

  for r in select i.lane, i.missing_fact from pipeline.layer4_interventions i
            where i.status in ('ai_pending', 'awaiting_input') and i.escalate_at <= now() and i.escalated_at is null group by 1, 2 loop
    begin
      v_issue := security.har_class_issue_v1(r.lane, r.missing_fact, 'unanswered past har.' || r.missing_fact || '.escalate_after_hours');
      update pipeline.layer4_interventions set escalated_at = now(), integration_issue_id = v_issue, updated_at = now()
       where lane = r.lane and missing_fact = r.missing_fact and status in ('ai_pending', 'awaiting_input') and escalate_at <= now() and escalated_at is null;
      v_esc := v_esc + 1;
    exception when others then v_err := v_err + 1;
    end;
  end loop;
  return jsonb_build_object('generated', v_gen, 'ai', v_ai, 'verified', v_ok, 'returned_to_reviewer', v_back, 'waiting_result', v_wait,
                            'cleared', v_clear, 'escalated_classes', v_esc, 'errors', v_err);
end $_$;


ALTER FUNCTION "security"."layer4_interventions_tick_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."layer4_interventions_tick_v1"() IS 'CF-247 human-assisted recovery (decision 06:30 §1, §6, §7): job layer4-interventions: raises interventions per lane (bounded, fair), runs the stronger-model step (off), verifies resumed work and closes or reopens, rechecks waiting items, escalates unanswered classes once.';



CREATE OR REPLACE FUNCTION "security"."layer4_issue_kind_v1"("p_issue" bigint) RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select split_part(i.fingerprint, ':', 2) from pipeline.integration_issues i where i.id = p_issue
$$;


ALTER FUNCTION "security"."layer4_issue_kind_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_item_lifecycle_v1"("p_kind" "text", "p_ref" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- one card, with its admission and publication checks (decision 12:24 §2)
  select security.layer4_lifecycle_one_v1(p_kind, p_ref, true)
         || coalesce(security.layer4_card_group_v1(jsonb_build_array(jsonb_build_object('kind', p_kind, 'ref', p_ref)))->(p_kind || ':' || p_ref), '{}'::jsonb)
$$;


ALTER FUNCTION "security"."layer4_item_lifecycle_v1"("p_kind" "text", "p_ref" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_item_page_v1"("p_field" "text", "p_value" "jsonb", "p_l2" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select nullif(btrim(coalesce(case jsonb_typeof(p_value) when 'string' then p_value #>> '{}' when 'object' then coalesce(p_value->>'course_url', p_value->>'url', p_value->>'page') end,
                               p_l2->>'page')), '')
$$;


ALTER FUNCTION "security"."layer4_item_page_v1"("p_field" "text", "p_value" "jsonb", "p_l2" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_items_lifecycle_v1"("p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- one page of cards ([{kind, ref}]), keyed 'kind:ref'; at most layer4.lifecycle_batch_max
  -- CF-247 mandate 16:32 §7: each card also carries its group, whether a person is needed, and its evidence (security.layer4_card_group_v1)
  select coalesce(jsonb_object_agg(z.kind || ':' || z.ref, security.layer4_lifecycle_one_v1(z.kind, z.ref, false)
                                   || coalesce(g.j->(z.kind || ':' || z.ref), '{}'::jsonb)), '{}'::jsonb)
    from (select security.layer4_card_group_v1(p_items) j) g, (select distinct x->>'kind' kind, x->>'ref' ref from jsonb_array_elements(case when jsonb_typeof(p_items) = 'array' then p_items else '[]'::jsonb end) x
           where x ? 'kind' and x ? 'ref' limit security.pipeline_num_v1('layer4.lifecycle_batch_max', 50)::int) z
$$;


ALTER FUNCTION "security"."layer4_items_lifecycle_v1"("p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_lifecycle_one_v1"("p_kind" "text", "p_ref" "text", "p_full" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int := security.pipeline_num_v1('layer4.lifecycle_history_max', 8)::int;
        r pipeline.layer4_review_items; s pipeline.aer_read_supersessions; f pipeline.field_enrich_items; w pipeline.work_items; iv pipeline.layer4_interventions;
        fl pipeline.enrichment_flags; ob pipeline.provider_onboarding; e record; v_hist jsonb := '[]'; v_last jsonb; v_rep jsonb; v_pred jsonb; v_succ jsonb;
        v_first timestamptz; v_created timestamptz; v_upd timestamptz; v_rev timestamptz; v_auto timestamptz; v_entered timestamptz; v_next timestamptz; v_next_text text;
        v_decided timestamptz; v_admitted timestamptz; v_published timestamptz; v_status text; v_stage text; v_why text; v_owner text; v_entries int := 1;
        v_requested text := 'no'; v_executed text := 'not applicable'; v_valid text := 'not applicable'; v_approved text := 'not yet'; v_adm text := 'not yet'; v_pub text := 'not yet';
        v_rows int; v_pid uuid; v_open boolean := true; v_first_ev timestamptz; v_att record; v_recovery jsonb; v_course uuid; v_poll jsonb;
begin
  -- the Inbox's own audit rows for the item (every reviewer action, accepted or refused), newest first
  for e in select x.id, x.created_at, x.actor, x.detail from pipeline.admin_control_events x
            where x.area = 'layer4' and x.target = p_kind || ':' || p_ref and x.action in ('inbox_decide', 'inbox_navigate', 'inbox_refused') order by x.id desc limit v_n loop
    v_hist := v_hist || jsonb_build_array(jsonb_build_object('at', security.l4_time_v1(e.created_at), 'by', 'reviewer', 'action', e.detail->>'choice', 'ref', 'audit #' || e.id,
                'event_id', e.id, 'reason', e.detail->>'reason',
                'result', security.layer4_ack_normalise_v1(p_kind, e.detail->>'choice', null, e.detail->'result', null, null)
                          || jsonb_build_object('headline', security.layer4_ack_headline_v1(e.detail->>'choice',
                               security.layer4_ack_normalise_v1(p_kind, e.detail->>'choice', null, e.detail->'result', null, null),
                               coalesce(e.detail->'result'->'detail', e.detail->'result', '{}'::jsonb), e.created_at))));
    v_rev := greatest(v_rev, e.created_at);
  end loop;
  select min(x.created_at) into v_first_ev from pipeline.admin_control_events x where x.area = 'layer4' and x.target = p_kind || ':' || p_ref and x.action in ('inbox_decide', 'inbox_navigate');
  v_last := v_hist->0;
  if v_last is not null then v_requested := 'yes'; end if;

  if p_kind in ('course_link', 'aer_review', 'provider_description', 'no_page_first_run', 'conjoint_first_run') then
    select * into r from pipeline.layer4_review_items where id = p_ref::uuid;
    if r.id is null then return jsonb_build_object('kind', p_kind, 'ref', p_ref, 'found', false); end if;
    v_created := r.created_at; v_entered := r.created_at; v_status := r.status; v_decided := r.decided_at; v_open := r.status = 'pending';
    v_course := case when r.entity_type = 'course' then r.entity_id end;
    v_pid := coalesce((select c.provider_id from catalogue.courses c where c.id = v_course), case when r.entity_type = 'provider' then r.entity_id end);
    v_approved := case when r.status in ('approved', 'edited_approved') then 'yes' when r.status = 'pending' then 'not yet' else 'no (' || r.status || ')' end;
    -- first entered Layer 4: the earliest item of the same record and field, and up the chain of corrected reads (never reset by a re-read)
    select min(x.created_at), count(*) into v_first, v_entries from pipeline.layer4_review_items x where x.entity_id = r.entity_id and x.field_code = r.field_code;
    v_first := least(v_first, (with recursive ch(id, d) as (select r.id, 0 union all
                                  select s2.old_item_id, ch.d + 1 from ch join pipeline.aer_read_supersessions s2 on s2.new_item_id = ch.id where ch.d < 50)  -- fixed: cycle guard
                               select min(x.created_at) from ch join pipeline.layer4_review_items x on x.id = ch.id));
    select jsonb_build_object('ref', x.old_item_id, 'relation', 'this read replaced it (superseded)', 'at', security.l4_time_v1(x.closed_at), 'request', x.id)
      into v_pred from pipeline.aer_read_supersessions x where x.new_item_id = r.id order by x.requested_at desc limit 1;
    if r.field_code = 'course_entry_first_read' then
      v_executed := 'not asked'; v_valid := 'not asked';
      -- corrected reads asked for this item (the reviewer's, the scheduled job's and recovery's)
      -- observation 13:00 §2: each corrected read with its attempt number, operation (request and enrich item), reader times, the original and
      -- replacement reads and when the replacement entered Layer 4
      for v_att in select x.*, row_number() over (order by x.requested_at) n, f2.created_at f_start, f2.updated_at f_end, f2.state f_state, f2.reason f_reason,
                          f2.evidence_id f_ev, f2.cost_usd f_cost, nr.created_at new_at
                     from pipeline.aer_read_supersessions x left join pipeline.field_enrich_items f2 on f2.id = x.enrich_item_id
                     left join pipeline.layer4_review_items nr on nr.id = x.new_item_id
                    where x.old_item_id = r.id order by x.requested_at desc limit v_n loop
        v_hist := v_hist || jsonb_build_array(jsonb_build_object('at', security.l4_time_v1(v_att.requested_at),
                    'by', case when v_att.reason ilike 'Layer 4 recovery%' then 'reviewer' when v_att.reason ilike 'Human input needed%' then 'human input' else 'automatic' end,
                    'action', 'corrected read', 'attempt', v_att.n, 'ref', 'request ' || left(v_att.id::text, 8), 'reason', v_att.reason,
                    'operation', jsonb_build_object('request', v_att.id, 'enrich_item', v_att.enrich_item_id, 'job', v_att.job_id),
                    'reader', jsonb_strip_nulls(jsonb_build_object('started', security.l4_time_v1(v_att.f_start),
                                'completed', case when v_att.state <> 'requested' then security.l4_time_v1(coalesce(v_att.closed_at, v_att.f_end)) end,
                                'state', v_att.f_state, 'detail', v_att.f_reason, 'stored_copy', v_att.f_ev, 'cost_usd', v_att.f_cost)),
                    'original_read', v_att.old_item_id, 'replacement_read', v_att.new_item_id, 're_entered', security.l4_time_v1(v_att.new_at),
                    'result', jsonb_build_object('outcome', case v_att.state when 'requested' then 'queued' when 'superseded' then 'completed' else 'failed' end,
                                                 'headline', security.layer4_recovery_headline_v1(v_att.state, v_att.outcome, v_att.requested_at),
                                                 'reason', coalesce(v_att.outcome, case v_att.state when 'superseded' then 'complete: a new read replaced this one' else 'waiting for the reader' end),
                                                 'at', security.l4_time_v1(v_att.closed_at))));
        if v_recovery is null then v_recovery := v_hist->-1; end if;
        if v_att.reason not ilike 'Layer 4 recovery%' then v_auto := greatest(v_auto, v_att.requested_at, v_att.closed_at); end if;
        v_upd := greatest(v_upd, v_att.requested_at, v_att.closed_at);
      end loop;
      select * into s from pipeline.aer_read_supersessions x where x.old_item_id = r.id order by x.requested_at desc limit 1;
      if s.id is not null then
        v_requested := 'yes';
        select * into f from pipeline.field_enrich_items x where x.id = s.enrich_item_id;
        v_executed := case when s.state <> 'requested' then 'yes, ' || coalesce(security.l4_time_v1(s.closed_at)->>'text', '') when f.state in ('leased', 'ai') then 'running' else 'waiting for the reader' end;
        v_valid := case s.state when 'superseded' then 'yes (complete)' when 'refused' then 'no: ' || coalesce(s.outcome, 'refused') else 'not yet' end;
        v_stage := case when s.state = 'requested' and f.state in ('leased', 'ai') then 'executing' when s.state = 'requested' then 'scheduled'
                        when s.state = 'refused' then 'failed' else 'completed' end;
        if s.state = 'superseded' then
          v_succ := (select jsonb_build_object('ref', s.new_item_id, 'relation', 'replaced by a corrected read', 'status', x.status, 'at', security.l4_time_v1(s.closed_at),
                                               're_entered', security.l4_time_v1(x.created_at),
                                               'complete', case when p_full then (security.course_entry_gate_v1(x.id, '{}'::uuid[])->>'complete')::boolean end)
                       from pipeline.layer4_review_items x where x.id = s.new_item_id);
        end if;
      end if;
      v_rep := security.layer4_reread_repeat_v1(r.id);
      select * into w from pipeline.work_items x where x.lane = 'aer_technical' and x.entity = p_ref and x.work_kind = 'l4_item';
      if w.id is not null then
        v_auto := greatest(v_auto, w.last_attempt_at); v_upd := greatest(v_upd, w.updated_at); v_next := w.next_eligible_at;
        if w.next_eligible_at is not null and w.next_eligible_at > now() then v_next_text := 'technical recovery tries again (' || coalesce(w.failure_class, w.stage) || ')'; end if;
      end if;
      select * into iv from pipeline.layer4_interventions x where x.lane = 'aer_item' and x.entity = p_ref and x.status in ('ai_pending', 'awaiting_input', 'resuming')
       order by x.id desc limit 1;
      if iv.id is null then
        select i.* into iv from pipeline.layer4_aer_recovery_actions a join pipeline.layer4_interventions i on i.id = a.intervention_id
         where a.review_item_id = r.id and i.status in ('ai_pending', 'awaiting_input', 'resuming') order by a.id desc limit 1;
      end if;
      if (p_full or not v_open) then
        select count(*), max(x.updated_at) into v_rows, v_admitted from catalogue.course_entry_requirements x
         where x.course_id = r.entity_id and x.provenance->>'review_item_id' = r.id::text and x.status = 'active';
        v_adm := case when v_rows > 0 then 'yes: ' || v_rows || ' row' || case when v_rows = 1 then '' else 's' end || ' active' when v_open then 'not yet' else 'no row active' end;
        select c.provider_id into v_pid from catalogue.courses c where c.id = r.entity_id;
        if v_rows > 0 and exists (select 1 from catalogue.courses c join catalogue.providers p on p.id = c.provider_id
                                    where c.id = r.entity_id and c.lifecycle_status = 'active' and p.publication_status = 'published') then
          v_pub := 'yes: course and university published'; v_published := v_admitted;
        elsif v_rows > 0 then v_pub := 'no: the course or its university is not published';
        end if;
      end if;
    elsif r.field_code in ('entry_matrix_first_run', 'entry_matrix_change') then
      select x.updated_at into v_auto from pipeline.entry_matrix_runs x where x.review_item_id = r.id order by x.created_at desc limit 1;
    elsif p_kind = 'course_link' and not v_open then
      v_adm := case when exists (select 1 from catalogue.course_links l where l.course_id = r.entity_id and l.link_type = 'official_course' and l.status = 'active')
                    then 'yes: the course''s official page is active' else 'no active official page' end;
    end if;
  elsif p_kind = 'held_scholarship' then
    for e in select x.created_at, x.status, x.decided_at, s2.publication_status from pipeline.scholarship_ai_reviews x left join scholarship.scholarships s2 on s2.id = x.scholarship_id
              where x.id = p_ref::bigint loop
      v_created := e.created_at; v_first := e.created_at; v_entered := e.created_at; v_status := e.status; v_decided := e.decided_at; v_open := e.status = 'pending';
      v_approved := case when e.status = 'pending' then 'not yet' else e.status end;
      v_pub := case when e.publication_status = 'published' then 'yes' when v_open then 'not yet' else 'no (' || coalesce(e.publication_status, 'no scholarship') || ')' end;
    end loop;
  elsif p_kind in ('website_needed', 'too_few_pages', 'nothing_ready', 'central_to_approve', 'onboarding_failed') then
    select * into ob from pipeline.provider_onboarding x where x.id = p_ref::uuid;
    v_created := ob.created_at; v_entered := ob.updated_at; v_status := ob.status; v_pid := ob.provider_id; v_auto := ob.updated_at; v_open := ob.status = 'stopped';
    select min(x.created_at), count(*) into v_first, v_entries from pipeline.provider_onboarding x where x.provider_id = ob.provider_id and x.status = 'stopped' and x.stop_reason = ob.stop_reason;
    -- what the decision started: the university's newer onboarding run
    for e in select x.id, x.status, x.created_at, x.updated_at, x.stop_reason from pipeline.provider_onboarding x
              where x.provider_id = ob.provider_id and x.created_at > ob.created_at order by x.created_at desc limit 1 loop
      v_stage := case when e.status = 'stopped' then 'failed' when e.status in ('done', 'completed', 'finished') then 'completed' else 'executing' end;
      v_auto := greatest(v_auto, e.updated_at); v_executed := e.status;
      v_why := case when e.status = 'stopped' then 'The new onboarding run stopped again: ' || coalesce(e.stop_reason, 'unknown') end;
    end loop;
  elsif p_kind in ('pages_not_found', 'site_down', 'fee_check', 'not_offered', 'not_on_site') then
    select * into fl from pipeline.enrichment_flags x where x.id = p_ref::bigint;
    -- Keep waiting moves flagged_at forward (asked again later); the first entry is the earliest of it and the first action on the item
    v_created := fl.flagged_at; v_entered := fl.flagged_at; v_status := fl.state; v_decided := fl.released_at; v_open := fl.state = 'raised';
    v_first := least(coalesce(fl.first_flagged_at, fl.flagged_at), v_first_ev); v_next := fl.next_check_at; v_auto := fl.updated_at; v_pid := fl.provider_id;
    if v_open and fl.next_check_at is not null then v_next_text := 'checked again automatically'; end if;
    if p_kind = 'site_down' and v_open then v_next_text := 'the site is checked again automatically; asked again after the waiting period'; end if;
  elsif p_kind = 'course_page_needed' then
    for e in select * from pipeline.course_page_needed x where x.course_id = p_ref::uuid loop
      v_created := e.created_at; v_first := e.created_at; v_entered := coalesce(e.last_refused_at, e.created_at); v_status := e.state; v_decided := e.decided_at;
      v_open := e.state = 'open'; v_auto := e.last_refused_at; v_upd := e.updated_at; v_pid := e.provider_id;
      if e.searches_requested > 0 and v_open then v_stage := 'scheduled'; v_next_text := 'the course-link search looks for the page again'; end if;
    end loop;
  elsif p_kind = 'counsellor_report' then
    for e in select * from pipeline.data_flags x where x.id = p_ref::uuid loop
      v_created := e.created_at; v_first := e.created_at; v_entered := e.created_at; v_status := e.status; v_decided := e.resolved_at; v_open := e.status = 'open';
    end loop;
  elsif p_kind = 'provider_departure' then
    for e in select * from pipeline.layer1_provider_departures x where x.id = p_ref::bigint loop
      v_created := e.created_at; v_first := e.created_at; v_entered := e.created_at; v_status := e.status; v_decided := e.reviewed_at; v_open := e.status = 'needs_review';
    end loop;
  elsif p_kind = 'intervention' then
    select * into iv from pipeline.layer4_interventions x where x.id = p_ref::bigint;
    v_created := iv.created_at; v_first := iv.created_at; v_entered := iv.created_at; v_status := iv.status; v_decided := iv.input_at; v_upd := iv.updated_at;
    v_open := iv.status in ('ai_pending', 'awaiting_input', 'resuming'); v_admitted := iv.admitted_at; v_published := iv.published_at;
    v_adm := case when iv.admitted_at is not null then 'yes' when v_open then 'not yet' else 'no' end;
    v_pub := case when iv.published_at is not null then 'yes' when v_open then 'not yet' else 'no' end;
    v_executed := case when iv.resumed_at is not null then 'yes, resumed' else 'not yet' end;
    v_valid := case when iv.verified_at is not null then 'yes: ' || coalesce(iv.verified_outcome, 'verified') else 'not yet' end;
    for e in select x.at, x.actor, x.action, x.status_before, x.status_after, x.result from pipeline.layer4_intervention_events x
              where x.intervention_id = iv.id and x.actor is null order by x.id desc limit v_n loop
      v_hist := v_hist || jsonb_build_array(jsonb_build_object('at', security.l4_time_v1(e.at), 'by', 'automatic', 'action', e.action,
                  'result', jsonb_build_object('outcome', coalesce(e.status_after, 'recorded'), 'reason', coalesce(e.result->>'request', e.result->>'state', e.result->>'reason'))));
      v_auto := greatest(v_auto, e.at);
    end loop;
  else
    return jsonb_build_object('kind', p_kind, 'ref', p_ref, 'found', false);
  end if;

  -- where the item stands (the shared lifecycle)
  if iv.id is not null and (p_kind = 'intervention' or v_open) and iv.status in ('ai_pending', 'awaiting_input', 'resuming') then
    v_stage := case iv.status when 'awaiting_input' then 'awaiting_input' else 'executing' end;
    v_owner := iv.assigned_to; v_next := coalesce(iv.next_action_at, v_next);
    v_next_text := case iv.status when 'awaiting_input' then 'Human input needed item ' || iv.id || ' waits for a person; the work resumes by itself when the input checks out'
                                  when 'ai_pending' then 'the stronger model analyses the failure once, then a person is asked'
                                  else 'the work resumes and is verified automatically' end;
  elsif p_kind = 'intervention' then
    v_stage := case when iv.verified_at is not null then 'verified' else 'resolved' end;
  end if;
  if not v_open then
    v_stage := case when v_status = 'superseded' then 'superseded' when v_stage in ('verified') then v_stage else 'resolved' end;
  elsif v_stage is null then
    v_stage := case v_last->'result'->>'outcome' when 'refused' then 'refused' when 'queued' then 'scheduled' when 'human_input' then 'awaiting_input'
                    when 'completed' then 'completed' when 'accepted' then 'accepted' when 'incomplete' then 'awaiting_input' else 'awaiting_decision' end;
  end if;
  v_why := coalesce(v_why, case
    when not v_open then null
    when v_stage = 'failed' and s.id is not null then 'The last corrected read was refused by the reader: ' || coalesce(s.outcome, 'refused') || '. The original read stays pending'
    when v_stage = 'awaiting_input' then 'Waiting for human input' || coalesce(' (item ' || iv.id || ')', '')
    when v_stage in ('scheduled', 'executing') then 'Waiting for the operation that was asked for'
    when v_stage = 'refused' then 'The last action was refused: ' || coalesce(v_last->'result'->>'reason', 'see the reason')
    else 'No reviewer action yet' end);
  if coalesce((v_rep->>'repeat')::boolean, false) and v_open then v_next_text := v_rep->>'alternative'; v_next := null; end if;
  if v_open and v_next_text is null then
    v_next := null;
    v_next_text := case
      when v_stage = 'scheduled' and s.id is not null then 'the entry reader reads the stored copy (job ' || left(s.job_id::text, 8) || ')'
      when v_stage = 'executing' then 'running now'
      when v_last->'result'->>'alternative' is not null and v_stage in ('refused', 'awaiting_input') then v_last->'result'->>'alternative'
      else 'a reviewer decides' end;
  end if;
  v_owner := coalesce(v_owner, case when v_stage in ('scheduled', 'executing') then 'the platform (automatic)' when v_open then 'Layer 4 reviewer' end);
  v_upd := greatest(v_upd, v_created, v_rev, v_auto, v_decided, v_entered);
  if v_open and v_stage in ('scheduled', 'executing') then
    v_poll := jsonb_build_object('every_seconds', security.pipeline_num_v1('layer4.lifecycle_poll_seconds', 15), 'max', security.pipeline_num_v1('layer4.lifecycle_poll_max', 40));
  end if;
  return jsonb_build_object('kind', p_kind, 'ref', p_ref, 'found', true, 'status', v_status, 'open', v_open, 'provider_id', v_pid, 'course_id', v_course,
    'recovery', v_recovery, 'poll', v_poll,
    'waiting', case when v_open then jsonb_build_object('hours', round(extract(epoch from now() - coalesce(v_first, v_created)) / 3600, 1),
                     'text', case when now() - coalesce(v_first, v_created) >= make_interval(days => 1)
                                  then extract(day from now() - coalesce(v_first, v_created))::int || ' d ' || extract(hour from now() - coalesce(v_first, v_created))::int || ' h'
                                  else extract(hour from now() - coalesce(v_first, v_created))::int || ' h ' || extract(minute from now() - coalesce(v_first, v_created))::int || ' min' end) end,
    'stage', v_stage,
    'stage_label', case v_stage when 'awaiting_decision' then 'Waiting for a reviewer' when 'accepted' then 'Accepted' when 'refused' then 'Refused'
                     when 'scheduled' then 'Scheduled' when 'executing' then 'Running' when 'completed' then 'Completed' when 'failed' then 'Failed: still pending'
                     when 'awaiting_input' then 'Waiting for human input' when 'verified' then 'Verified' when 'superseded' then 'Superseded' else 'Resolved' end,
    'why_pending', v_why, 'owner', v_owner,
    'next', case when v_open then jsonb_build_object('text', v_next_text, 'at', security.l4_time_v1(v_next)) end,
    'times', jsonb_strip_nulls(jsonb_build_object('first_entered', security.l4_time_v1(coalesce(v_first, v_created)), 'item_created', security.l4_time_v1(v_created),
      'last_updated', security.l4_time_v1(v_upd), 'last_reviewer_action', security.l4_time_v1(v_rev), 'last_automated_attempt', security.l4_time_v1(v_auto),
      'last_entered', security.l4_time_v1(v_entered), 'next_action', security.l4_time_v1(case when v_open then v_next end), 'decided', security.l4_time_v1(v_decided),
      'admitted', security.l4_time_v1(v_admitted), 'published', security.l4_time_v1(v_published))),
    'entries', v_entries,
    'steps', jsonb_build_object('requested', v_requested, 'executed', v_executed, 'valid', v_valid, 'approved', v_approved, 'admitted', v_adm, 'published', v_pub),
    'predecessor', v_pred, 'successor', v_succ,
    'repeat_guard', case when coalesce((v_rep->>'repeat')::boolean, false) then jsonb_build_object('action', 'reread_stored', 'why', v_rep->>'why', 'alternative', v_rep->>'alternative') end,
    'last_action', v_last,
    'history', (select coalesce(jsonb_agg(h order by (h->'at'->>'at')::timestamptz desc), '[]'::jsonb) from (select h from jsonb_array_elements(v_hist) h order by (h->'at'->>'at')::timestamptz desc limit v_n) z));
end $$;


ALTER FUNCTION "security"."layer4_lifecycle_one_v1"("p_kind" "text", "p_ref" "text", "p_full" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_lifecycle_report_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 (decision 12:24 §10): Layer 4 lifecycle measures over layer4.lifecycle_report_days, from the existing records
  with p as (select make_interval(days => security.pipeline_num_v1('layer4.lifecycle_report_days', 7)::int) d),
       ev as (select x.detail->>'kind' kind, security.layer4_ack_normalise_v1(x.detail->>'kind', x.detail->>'choice', null, x.detail->'result', null, null)->>'outcome' o
                from pipeline.admin_control_events x, p where x.area = 'layer4' and x.action = 'inbox_decide' and x.created_at > now() - p.d),
       ri as (select x.id, x.status, x.created_at, x.entity_id, x.field_code from pipeline.layer4_review_items x, p where x.created_at > now() - p.d),
       sup as (select x.*, f.evidence_id ev from pipeline.aer_read_supersessions x left join pipeline.field_enrich_items f on f.id = x.enrich_item_id, p where x.requested_at > now() - p.d)
  select jsonb_build_object('days', security.pipeline_num_v1('layer4.lifecycle_report_days', 7),
    'entered', (select count(*) from ri),
    're_entered', (select count(*) from ri where exists (select 1 from pipeline.layer4_review_items y where y.entity_id = ri.entity_id and y.field_code = ri.field_code and y.created_at < ri.created_at)),
    'waiting_human_hours', (select round(avg(extract(epoch from now() - x.created_at)) / 3600, 1) from pipeline.layer4_review_items x where x.status = 'pending'
                              and not exists (select 1 from pipeline.aer_read_supersessions s where s.old_item_id = x.id and s.state = 'requested')),
    'waiting_technical', (select count(*) from pipeline.aer_read_supersessions s where s.state = 'requested'),
    'interventions_waiting', (select count(*) from pipeline.layer4_interventions i where i.status = 'awaiting_input'),
    'actions', (select coalesce(jsonb_object_agg(o, n), '{}'::jsonb) from (select o, count(*) n from ev group by 1) z),
    'actions_by_kind', (select coalesce(jsonb_object_agg(kind, n), '{}'::jsonb) from (select kind, count(*) n from ev group by 1) z),
    'automatic_resumptions', (select count(*) from pipeline.layer4_interventions i, p where i.resumed_at > now() - p.d),
    'corrected_reads', jsonb_build_object('asked', (select count(*) from sup), 'superseded', (select count(*) from sup where state = 'superseded'),
                                           'refused', (select count(*) from sup where state = 'refused'),
                                           'repeated_no_yield', (select count(*) from sup where state = 'refused' and exists (
                                              select 1 from pipeline.aer_read_supersessions y join pipeline.field_enrich_items g on g.id = y.enrich_item_id
                                               where y.old_item_id = sup.old_item_id and y.state = 'refused' and y.requested_at < sup.requested_at and g.evidence_id is not distinct from sup.ev))),
    'verified_admissions', (select count(*) from ri where ri.status in ('approved', 'edited_approved')),
    'interventions_admitted', (select count(*) from pipeline.layer4_interventions i, p where i.admitted_at > now() - p.d),
    'interventions_published', (select count(*) from pipeline.layer4_interventions i, p where i.published_at > now() - p.d))
$$;


ALTER FUNCTION "security"."layer4_lifecycle_report_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_money_text"("p" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $_$
  select case when p is null or jsonb_typeof(p)<>'object' or nullif(p->>'amount','') is null then null else
    concat_ws(' · ',
      case upper(coalesce(p->>'currency_code',p->>'currency','')) when 'AUD' then 'A$' when 'NZD' then 'NZ$' else coalesce(nullif(upper(coalesce(p->>'currency_code',p->>'currency','')),'')||' ','') end
        || to_char((p->>'amount')::numeric,'FM999,999,999')
        || case lower(coalesce(p->>'basis','')) when 'annual' then ' per year' when 'indicative_annual' then ' per year (indicative)' when 'per_year_explicit' then ' per year'
             when 'annual_or_indicative_requires_validation' then ' (frequency not confirmed)' when '' then '' else ' ('||replace(p->>'basis','_',' ')||')' end,
      nullif(p->>'fee_year',''),
      nullif(lower(p->>'audience'),''))
  end
$_$;


ALTER FUNCTION "security"."layer4_money_text"("p" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_override_apply_impl"("p_actor" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_field_code" "text", "p_value" "jsonb", "p_reason_code" "text", "p_comment" "text" DEFAULT NULL::"text", "p_evidence_refs" "uuid"[] DEFAULT '{}'::"uuid"[], "p_approval_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_rank int:=0; v_reg pipeline.layer4_field_registry%rowtype; v_underlying jsonb;
        v_prev uuid; v_id uuid; v_email text;
begin
  if p_actor is null or p_actor<>auth.uid() then raise exception 'authenticated actor required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  select * into v_reg from pipeline.layer4_field_registry where entity_type=p_entity_type and field_code=p_field_code and enabled;
  if not found then raise exception 'field is not registered for Layer 4' using errcode='22023'; end if;
  if v_reg.editability_class='immutable' then raise exception 'field is immutable source/history and cannot be edited through Layer 4' using errcode='42501'; end if;
  if v_rank<v_reg.min_role_rank then raise exception 'insufficient role for Layer 4 field' using errcode='42501'; end if;
  if not security.layer4_entity_exists(p_entity_type,p_entity_id) then raise exception 'entity not found' using errcode='22023'; end if;
  if length(trim(coalesce(p_reason_code,'')))<3 then raise exception 'reason code required' using errcode='22023'; end if;
  perform security.layer4_validate_override_value(v_reg.value_kind,p_value);
  v_underlying:=security.layer4_underlying_value(p_entity_type,p_entity_id,p_field_code);
  select id into v_prev from pipeline.layer4_override_decisions
   where entity_type=p_entity_type and entity_id=p_entity_id and field_code=p_field_code
   order by created_at desc,id desc limit 1;
  select email into v_email from auth.users where id=p_actor;
  insert into pipeline.layer4_override_decisions(
    entity_type,entity_id,field_code,event_type,underlying_value,override_value,
    reason_code,comment,evidence_refs,actor_id,actor_email,supersedes_override_id,
    approval_context
  ) values (
    p_entity_type,p_entity_id,p_field_code,'apply',v_underlying,p_value,
    trim(p_reason_code),nullif(trim(coalesce(p_comment,'')),''),coalesce(p_evidence_refs,'{}'),
    p_actor,v_email,v_prev,coalesce(p_approval_context,'{}')
  ) returning id into v_id;
  return jsonb_build_object(
    'ok',true,'override_id',v_id,'entity_type',p_entity_type,'entity_id',p_entity_id,
    'field_code',p_field_code,'underlying_value',v_underlying,'effective_value',p_value,
    'effective_source','L4','layer',4,'publication_changed',false,'canonical_changed',false
  );
end $$;


ALTER FUNCTION "security"."layer4_override_apply_impl"("p_actor" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_field_code" "text", "p_value" "jsonb", "p_reason_code" "text", "p_comment" "text", "p_evidence_refs" "uuid"[], "p_approval_context" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_pace_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with d as (select r.field_code, extract(epoch from x.created_at - lag(x.created_at) over (partition by x.actor_id order by x.created_at)) / 60.0 gap
               from pipeline.layer4_decisions x join pipeline.layer4_review_items r on r.id = x.review_item_id
              where x.created_at > now() - make_interval(days => security.pipeline_num_v1('layer4.pace_window_days', 30)::int) and x.actor_id is not null and coalesce(x.layer2_state->>'actor_kind', '') <> 'machine'),
       k as (select d.field_code, count(*) n, percentile_cont(0.5) within group (order by d.gap) p50 from d
              where d.gap > security.pipeline_num_v1('layer4.pace_min_gap_seconds', 20) / 60.0 and d.gap <= security.pipeline_num_v1('layer4.pace_gap_minutes', 15) group by d.field_code)
  select coalesce(jsonb_object_agg(k.field_code, jsonb_build_object(
           'minutes', case when k.n >= security.pipeline_num_v1('layer4.pace_min_decisions', 5) then round(k.p50::numeric, 2) else security.pipeline_num_v1('layer4.pace_default_minutes', 3) end,
           'measured', k.n, 'basis', case when k.n >= security.pipeline_num_v1('layer4.pace_min_decisions', 5) then 'measured' else 'default' end)), '{}'::jsonb)
    from k
$$;


ALTER FUNCTION "security"."layer4_pace_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_provider_departure_decide_v1"("p_id" bigint, "p_decision" "text", "p_successor_provider_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue'
    AS $$
declare d pipeline.layer1_provider_departures; p catalogue.providers; s catalogue.providers; v_before jsonb; v_after jsonb; v_changed boolean:=false;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  if security.current_role_rank()<6 then raise exception 'Platform Admin role required' using errcode='42501'; end if;
  if p_decision not in ('closed','merged','reviewed') then raise exception 'decision must be closed, merged or reviewed' using errcode='22023'; end if;
  if length(btrim(coalesce(p_reason,'')))<8 then raise exception 'a reason of at least 8 characters is required' using errcode='22023'; end if;
  select * into d from pipeline.layer1_provider_departures where id=p_id for update;
  if not found then raise exception 'departure not found' using errcode='22023'; end if;
  if d.status<>'needs_review' then raise exception 'this departure was already decided (%)', d.status using errcode='55000'; end if;
  select * into p from catalogue.providers where id=d.provider_id for update;
  if exists (select 1 from catalogue.courses c where c.provider_id=p.id and c.lifecycle_status='active') and p_decision<>'reviewed' then
    raise exception 'the provider has active courses again; choose reviewed' using errcode='55000'; end if;
  if p_decision='merged' then
    if p_successor_provider_id is null then raise exception 'a merger needs a successor provider' using errcode='22023'; end if;
    select * into s from catalogue.providers where id=p_successor_provider_id;
    if not found or s.id=p.id then raise exception 'successor provider not valid' using errcode='22023'; end if;
    if s.country_id is distinct from p.country_id then raise exception 'successor must be in the same country' using errcode='22023'; end if;
    if s.lifecycle_status<>'active' then raise exception 'successor provider is not active' using errcode='22023'; end if;
  elsif p_successor_provider_id is not null then
    raise exception 'a successor is only recorded for a merger' using errcode='22023';
  end if;

  if p_decision in ('closed','merged') and p.lifecycle_status='active' then
    v_before:=security.consumer_api_snapshot_v1();
    -- v2.15.238 (R5): a closure or merger archives the provider through the clean-up workflow (usually already archived by Layer 1)
    perform security.provider_archive_apply_v1(p.id, 'departure_review', initcap(p_decision)||': '||btrim(p_reason), auth.uid(), true);
    v_changed:=true;
  end if;
  if p_decision='merged' then
    insert into catalogue.provider_associations(from_provider_id,to_provider_id,association_type,valid_from,status,notes)
    values(p.id, s.id, 'merged_into', current_date, 'active', left('Recorded on provider departure review: '||btrim(p_reason),500));
  end if;
  update pipeline.layer1_provider_departures set status=p_decision, successor_provider_id=p_successor_provider_id,
         note=left(coalesce(note,'')||' | Decision: '||btrim(p_reason),1000), reviewed_by=auth.uid(), reviewed_at=now()
   where id=p_id;
  if v_changed then
    v_after:=security.consumer_api_snapshot_v1();
    insert into pipeline.consumer_api_baselines(label, snapshot) values
      (format('before provider departure decision %s (%s)', p_id, p_decision), v_before),
      (format('after provider departure decision %s (%s)', p_id, p_decision), v_after);
    insert into search.refresh_requests(requested_by) values (format('provider departure %s: %s', p_id, p_decision));
  end if;
  return jsonb_build_object('id',p_id,'decision',p_decision,'provider_id',p.id,'provider_inactive',v_changed,'successor_provider_id',p_successor_provider_id);
end $$;


ALTER FUNCTION "security"."layer4_provider_departure_decide_v1"("p_id" bigint, "p_decision" "text", "p_successor_provider_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_provider_departures_read_v1"("p_status" "text" DEFAULT 'needs_review'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'ref'
    AS $$
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  if security.current_role_rank()<4 then raise exception 'Pipeline Operator role required' using errcode='42501'; end if;
  return coalesce((select jsonb_agg(x order by x->>'created_at' desc) from (
    select jsonb_build_object(
      'id',d.id,'provider_id',d.provider_id,'provider_name',coalesce(p.display_name,p.canonical_name),'country_code',co.iso_alpha2,
      'provider_status',p.lifecycle_status,'courses_retired',d.courses_retired,'status',d.status,'note',d.note,'run_id',d.run_id,
      'created_at',d.created_at,'reviewed_at',d.reviewed_at,'successor_provider_id',d.successor_provider_id,
      'successor_name',(select coalesce(s.display_name,s.canonical_name) from catalogue.providers s where s.id=d.successor_provider_id),
      'suggested_successor',(select jsonb_build_object('provider_id',s.id,'name',coalesce(s.display_name,s.canonical_name),'courses',count(*))
          from pipeline.layer1_course_retirements r join catalogue.providers s on s.id=r.successor_provider_id
         where r.provider_id=d.provider_id and r.successor_provider_id is not null group by s.id, s.display_name, s.canonical_name order by count(*) desc limit 1),
      'registrations',(select coalesce(jsonb_agg(jsonb_build_object('scheme',pr.registration_scheme,'code',pr.registration_code,'status',pr.status)),'[]'::jsonb)
          from catalogue.provider_registrations pr where pr.provider_id=d.provider_id),
      'active_courses',(select count(*) from catalogue.courses c where c.provider_id=d.provider_id and c.lifecycle_status='active')) x
    from pipeline.layer1_provider_departures d
    join catalogue.providers p on p.id=d.provider_id
    left join ref.countries co on co.id=p.country_id
    where p_status is null or p_status='all' or d.status=p_status) z),'[]'::jsonb);
end $$;


ALTER FUNCTION "security"."layer4_provider_departures_read_v1"("p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_provider_description_apply_impl"("p_actor" "uuid", "p_item_id" "uuid", "p_value" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_review_items%rowtype; v_text text; v_now text; v_pub jsonb; v_shown text; v_key text; v_check jsonb; v_read pipeline.provider_description_reads%rowtype;
begin
  select * into i from pipeline.layer4_review_items where id = p_item_id;
  if i.id is null or i.entity_type <> 'provider' or i.field_code <> 'provider_description' then raise exception 'not a provider description item' using errcode = '22023'; end if;
  if p_actor is null or not exists(select 1 from security.user_roles ur join security.roles rr on rr.code=ur.role_code where ur.user_id=p_actor and (ur.expires_at is null or ur.expires_at>now()) and rr.status='active' and rr.rank>=4) then raise exception 'authorised Layer 4 reviewer rank 4 required' using errcode='42501'; end if;
  if i.status<>'pending' then raise exception 'the provider description decision is no longer pending' using errcode='22023'; end if;
  if not security.provider_description_scope_v1(i.entity_id) or not exists(select 1 from catalogue.providers p where p.id=i.entity_id and p.lifecycle_status='active' and p.publication_status='published')
    or exists(select 1 from security.provider_hidden_v1 h where h.provider_id=i.entity_id) then raise exception 'provider is no longer active, published and eligible' using errcode='22023'; end if;
  select * into v_read from pipeline.provider_description_reads r where r.review_item_id=i.id and r.state='proposed' for update;
  if v_read.id is null or v_read.evidence_id is distinct from i.evidence_id or not exists(select 1 from pipeline.evidence_artifacts a join pipeline.sources s on s.id=a.source_id where a.id=i.evidence_id and s.provider_id=i.entity_id and a.source_url=v_read.source_url and coalesce(a.content_hash,a.id::text)=v_read.content_hash) then
    raise exception 'provider description evidence lineage changed' using errcode='22023'; end if;
  if not (security.provider_description_identity_v1(i.entity_id,v_read.source_url)->>'ok')::boolean then raise exception 'provider description identity no longer valid' using errcode='22023'; end if;
  if v_read.checks->'identity_snapshot' is not null then
    if v_read.checks->'identity_snapshot' is distinct from security.provider_description_identity_snapshot_v1(i.entity_id) then raise exception 'provider identity changed since the source read; request new verified evidence' using errcode='22023'; end if;
  else
    -- Legacy proposals retain their original history: do not fabricate a historical identity snapshot. Revalidate the current full name against their actual retained official quote.
    if not exists(select 1 from catalogue.providers p cross join lateral jsonb_array_elements(coalesce(i.proposed_value->'sentences','[]'::jsonb)) sentence
      where p.id=i.entity_id and exists(select 1 from unnest(array[p.canonical_name,p.display_name]) nm where nullif(btrim(nm),'') is not null and position(regexp_replace(lower(nm),'[^a-z0-9]+','','g') in regexp_replace(lower(sentence->>'quote'),'[^a-z0-9]+','','g'))>0)) then
      raise exception 'legacy proposal has no identity snapshot and its retained quote does not verify the current full provider name' using errcode='22023';
    end if;
    update pipeline.provider_description_reads set checks=coalesce(checks,'{}'::jsonb)||jsonb_build_object('legacy_identity_quote_revalidated_at',now(),'identity_verification','legacy official quotation revalidated against current full name; no historical snapshot inferred') where id=v_read.id;
  end if;

  v_check:=security.provider_description_validate_v1(i.entity_id,v_read.source_url,v_read.source_captured_at,jsonb_build_object('about_page',true,'sentences',i.proposed_value->'sentences'));
  if v_check->>'outcome' not in ('propose','verified') or v_check->>'text' is distinct from i.proposed_value->>'description' then raise exception 'provider description no longer passes source and factual validation: %',v_check->>'rule' using errcode='22023'; end if;
  -- approved as read: an edited description has no quote for its new words, so it is not admitted (reject, and the page is read again later)
  if p_value is distinct from i.proposed_value then raise exception 'a description is approved as read, with every sentence quoted from the page; reject it instead of editing' using errcode = '22023'; end if;
  v_text := nullif(btrim(i.proposed_value->>'description'), '');
  if v_text is null then raise exception 'the proposal has no description' using errcode = '22023'; end if;
  if i.evidence_id is null then raise exception 'the proposal has no stored page' using errcode = '22023'; end if;
  if exists (select 1 from pipeline.manual_locks l where l.entity = 'provider' and l.entity_id = i.entity_id and l.field in ('description', 'p_description', 'all')) then
    raise exception 'the description is locked by hand' using errcode = '22023';
  end if;
  select nullif(btrim(p.description), '') into v_now from catalogue.providers p where p.id = i.entity_id for update;
  if v_now is distinct from nullif(btrim(i.before_value->>'description'), '') then raise exception 'the description changed since this was proposed; reject this item' using errcode = '22023'; end if;
  update catalogue.providers set description = v_text, updated_at = now() where id = i.entity_id;
  -- verify publication: the Website API v2 provider payload is read back (a provider not published returns nothing yet)
  select p.stable_key into v_key from catalogue.providers p where p.id = i.entity_id;
  begin
    v_pub := public.website_v2_provider(v_key);
    v_shown := v_pub->'item'->>'description';
  exception when others then v_shown := null;
  end;
  update pipeline.provider_description_reads set state = 'admitted', last_verified_at = now(),
         published_at = case when v_shown = v_text then now() end, updated_at = now()
   where review_item_id = i.id;
  update pipeline.provider_description_reads set state = 'superseded', updated_at = now()
   where provider_id = i.entity_id and state = 'admitted' and review_item_id is distinct from i.id;
  return jsonb_build_object('provider_id', i.entity_id, 'description_chars', length(v_text), 'published', v_shown = v_text, 'evidence_id', i.evidence_id);
end $$;


ALTER FUNCTION "security"."layer4_provider_description_apply_impl"("p_actor" "uuid", "p_item_id" "uuid", "p_value" "jsonb", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."layer4_provider_description_apply_impl"("p_actor" "uuid", "p_item_id" "uuid", "p_value" "jsonb", "p_reason" "text") IS 'CF-247 P1 provider descriptions: Layer 4 approval of a provider_description item writes catalogue.providers.description (as read, never edited; never over a value locked by hand or changed since the proposal), marks the read admitted and checks the Website API v2 payload shows it (published_at).';



CREATE OR REPLACE FUNCTION "security"."layer4_publication_state_read"("p_entity_type" "text", "p_entity_id" "uuid", "p_target_scope" "text" DEFAULT 'governed_publication'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_last pipeline.layer4_publication_decisions%rowtype; v_rank int;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  v_rank:=security.current_role_rank();
  select * into v_last from pipeline.layer4_publication_decisions
  where entity_type=p_entity_type and entity_id=p_entity_id and target_scope=p_target_scope
  order by created_at desc,id desc limit 1;
  return jsonb_build_object(
    'target_scope',p_target_scope,
    'can_decide',(v_rank>=5),
    'effective_decision',case when found and v_last.event_type<>'revert' then v_last.event_type else 'no_override' end,
    'decision_id',case when found then v_last.id else null end,
    'actor_id',case when found then v_last.actor_id else null end,
    'actor_email',case when found then v_last.actor_email else null end,
    'decided_at',case when found then v_last.created_at else null end,
    'reason_code',case when found then v_last.reason_code else null end,
    'comment',case when found then v_last.comment else null end,
    'readiness_snapshot',case when found then v_last.readiness_snapshot else '{}'::jsonb end,
    'overridden_checks',case when found then v_last.overridden_checks else '[]'::jsonb end
  );
end $$;


ALTER FUNCTION "security"."layer4_publication_state_read"("p_entity_type" "text", "p_entity_id" "uuid", "p_target_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_readiness_item_v1"("p_item" "uuid", "p_use_gate" boolean, "p_pace" "jsonb" DEFAULT NULL::"jsonb", "p_kinds" "text"[] DEFAULT NULL::"text"[]) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_res jsonb; v_blk jsonb; v_gate jsonb; v_gate_at timestamptz; v_ready text; v_reasons text[]; v_route text;
        v_pace jsonb := coalesce(p_pace, security.layer4_pace_v1());
        v_kinds text[] := coalesce(p_kinds, security.pipeline_list_v1('layer4.platform_kinds', '[]'::jsonb));
        v_use_gate boolean := coalesce(p_use_gate, false) and exists (select 1 from pipeline.layer4_review_items z where z.id = p_item and z.field_code in ('course_entry_first_read', 'entry_matrix_first_run', 'entry_matrix_change'));
begin
  select i.id, i.entity_type, i.entity_id, i.field_code, i.created_at, x.gate, x.gate_checked_at into r
    from pipeline.layer4_review_items i left join pipeline.layer4_item_readiness x on x.item_id = i.id where i.id = p_item and i.status = 'pending';
  if not found then return false; end if;
  v_res := security.layer4_resolution_v1(r.id);
  v_blk := security.layer4_blockers_v1(r.id, v_use_gate);
  if v_use_gate then v_gate := v_blk->'gate'; v_gate_at := now();
  else
    v_gate := r.gate; v_gate_at := r.gate_checked_at;
    -- an earlier gate result that held the read still holds it until it is evaluated again
    if v_gate is not null and not coalesce((v_gate->>'complete')::boolean, true) then
      v_blk := jsonb_set(v_blk, '{blockers}', (v_blk->'blockers') || jsonb_build_object('code', 'completeness_gate', 'why', coalesce(v_gate->'reasons'->>0, 'the completeness gate holds this read'),
                         'repair', 'the reader of this kind (D-R2 replacement read)', 'rule', v_gate->>'rule', 'as_at', r.gate_checked_at));
      v_blk := jsonb_set(v_blk, '{route}', to_jsonb('repair:' || (v_blk->'blockers'->0->>'code')));
    end if;
  end if;
  if v_res is not null and r.field_code = any (v_kinds) then
    v_ready := 'resolvable'; v_reasons := array[v_res->>'reason']; v_route := 'platform:' || (v_res->>'reason');
  elsif jsonb_array_length(v_blk->'blockers') > 0 then
    v_ready := 'technical_blocked'; v_reasons := (select array_agg(distinct b->>'code') from jsonb_array_elements(v_blk->'blockers') b); v_route := v_blk->>'route';
  else
    v_ready := 'judgement_ready'; v_reasons := '{}'; v_route := v_blk->>'route';
  end if;
  insert into pipeline.layer4_item_readiness as x(item_id, entity_type, entity_id, field_code, item_created_at, item_status, readiness, reasons, route, resolution, blockers,
                                                  est_minutes, gate, gate_checked_at, classified_at)
  values (r.id, r.entity_type, r.entity_id, r.field_code, r.created_at, 'pending', v_ready, v_reasons, v_route, v_res, v_blk->'blockers',
          coalesce((v_pace->r.field_code->>'minutes')::numeric, security.pipeline_num_v1('layer4.pace_default_minutes', 3)), v_gate, v_gate_at, now())
  on conflict (item_id) do update set item_status = 'pending', readiness = excluded.readiness, reasons = excluded.reasons, route = excluded.route,
     resolution = excluded.resolution, blockers = excluded.blockers, est_minutes = excluded.est_minutes, gate = excluded.gate, gate_checked_at = excluded.gate_checked_at,
     classified_at = now();
  return v_use_gate;
end $$;


ALTER FUNCTION "security"."layer4_readiness_item_v1"("p_item" "uuid", "p_use_gate" boolean, "p_pace" "jsonb", "p_kinds" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_readiness_items_v1"("p_items" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_pace jsonb := security.layer4_pace_v1(); v_kinds text[] := security.pipeline_list_v1('layer4.platform_kinds', '[]'::jsonb);
        v_gates int := security.pipeline_num_v1('layer4.gate_batch', 20)::int; v_g int := 0; v_n int := 0; v_use boolean;
begin
  if security.pipeline_num_v1('layer4.readiness_on', 1) < 1 then return jsonb_build_object('classified', 0, 'gates', 0, 'switch', 'off'); end if;
  for r in select i.id, i.field_code, x.gate_checked_at from pipeline.layer4_review_items i left join pipeline.layer4_item_readiness x on x.item_id = i.id
            where i.id = any (coalesce(p_items, '{}'::uuid[])) and i.status = 'pending'
            order by (x.gate_checked_at is null and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run', 'entry_matrix_change')) desc, i.created_at, i.id loop
    v_use := r.field_code in ('course_entry_first_read', 'entry_matrix_first_run', 'entry_matrix_change') and v_g < v_gates
             and (r.gate_checked_at is null or r.gate_checked_at < now() - make_interval(mins => security.pipeline_num_v1('layer4.readiness_recheck_minutes', 120)::int));
    perform security.layer4_readiness_item_v1(r.id, v_use, v_pace, v_kinds);
    if v_use then v_g := v_g + 1; end if;
    v_n := v_n + 1;
  end loop;
  return jsonb_build_object('classified', v_n, 'gates', v_g);
end $$;


ALTER FUNCTION "security"."layer4_readiness_items_v1"("p_items" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_readiness_tick_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_t0 timestamptz := clock_timestamp(); r record; v_res jsonb; v_blk jsonb; v_pace jsonb := security.layer4_pace_v1(); v_kinds text[] := security.pipeline_list_v1('layer4.platform_kinds', '[]'::jsonb);
        v_gates int := security.pipeline_num_v1('layer4.gate_batch', 20)::int; v_g int := 0; v_cls int := 0; v_closed int := 0; v_chk int := 0; v_iss int := 0;
        v_rec jsonb; v_gate jsonb; v_gate_at timestamptz; v_ready text; v_reasons text[]; v_route text; v_seen text[] := '{}'; v_fp text; v_out jsonb; v_use_gate boolean;
begin
  if not pg_try_advisory_xact_lock(hashtext('cf247:layer4-readiness')) then return jsonb_build_object('busy', true); end if;  -- fixed: one run at a time
  if security.pipeline_num_v1('layer4.readiness_on', 1) >= 1 then
    -- items that stopped waiting
    update pipeline.layer4_item_readiness x set readiness = 'closed', item_status = i.status, classified_at = now()
      from pipeline.layer4_review_items i where i.id = x.item_id and x.readiness <> 'closed' and i.status <> 'pending';
    get diagnostics v_closed = row_count;
    for r in select i.id, i.entity_type, i.entity_id, i.field_code, i.created_at, x.gate, x.gate_checked_at
               from pipeline.layer4_review_items i left join pipeline.layer4_item_readiness x on x.item_id = i.id
              where i.status = 'pending'
                and (x.item_id is null or x.classified_at < now() - make_interval(mins => security.pipeline_num_v1('layer4.readiness_recheck_minutes', 120)::int)
                     or (x.gate_checked_at is null and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run', 'entry_matrix_change')))
              order by (x.gate_checked_at is null and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run', 'entry_matrix_change')) desc,
                       x.classified_at nulls first, i.created_at
              limit security.pipeline_num_v1('layer4.readiness_batch', 1000)::int loop
      v_use_gate := r.field_code in ('course_entry_first_read', 'entry_matrix_first_run', 'entry_matrix_change') and v_g < v_gates
                    and (r.gate_checked_at is null or r.gate_checked_at < now() - make_interval(mins => security.pipeline_num_v1('layer4.readiness_recheck_minutes', 120)::int));
      -- 8 Nov 2026: one item is classified by security.layer4_readiness_item_v1 (also called for the items a replay creates), not by a copy of its steps here
      perform security.layer4_readiness_item_v1(r.id, v_use_gate, v_pace, v_kinds);
      if v_use_gate then v_g := v_g + 1; end if;
      v_cls := v_cls + 1;
    end loop;
  end if;
  v_rec := security.layer4_reconcile_v1(null, case when security.pipeline_num_v1('layer4.reconcile_supersede_on', 0) >= 1
                                                   then security.pipeline_num_v1('layer4.reconcile_batch', 200)::int else 0 end);
  if security.pipeline_num_v1('layer4.verify_on', 1) >= 1 then
    for r in select x.id from pipeline.layer4_decisions x
               left join pipeline.layer4_admission_checks c on c.decision_id = x.id
              where x.action in ('approve', 'edit_and_approve')
                and x.created_at > now() - make_interval(days => security.pipeline_num_v1('layer4.verify_lookback_days', 30)::int)
                and (c.decision_id is null
                     or (c.result in ('not_admitted', 'admitted_not_published', 'waiting')
                         and c.checked_at < now() - make_interval(hours => security.pipeline_num_v1('layer4.verify_recheck_hours', 6)::int))
                     or (c.result = 'waiting' and c.checked_at < now() - make_interval(mins => security.pipeline_num_v1('layer4.verify_wait_minutes', 90)::int)))
              order by (c.decision_id is null) desc, x.created_at desc
              limit security.pipeline_num_v1('layer4.verify_batch', 300)::int loop
      perform security.layer4_admission_record_v1(r.id);
      v_chk := v_chk + 1;
    end loop;
    -- one issue per kind and reason (the latest result of approvals in the window)
    for r in select c.field_code, c.result, coalesce(c.reason, 'unknown') reason, count(*) n, array_agg(c.entity_id order by c.decided_at desc) ents,
                    array_agg(c.decision_id order by c.decided_at desc) decs, min(c.decided_at) first_at, max(c.decided_at) last_at
               from pipeline.layer4_admission_checks c
              where c.result in ('not_admitted', 'admitted_not_published')
                and c.decided_at > now() - make_interval(days => security.pipeline_num_v1('layer4.verify_lookback_days', 30)::int)
              group by 1, 2, 3 loop
      v_fp := case when r.result = 'not_admitted' then 'l4_not_admitted:' else 'l4_not_published:' end || r.field_code || ':' || r.reason;
      perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', v_fp,
        'title', case when r.result = 'not_admitted' then 'Layer 4 approvals that did not reach the catalogue (' else 'Layer 4 approvals in the catalogue but not on the website projection (' end
                 || r.field_code || ', ' || r.reason || ')',
        'layer', 'Layer 4', 'subsystem', 'pipeline.layer4_admission_checks',
        'failure', r.n || ' approval(s) saved ' || to_char(r.first_at at time zone 'Australia/Melbourne', 'DD Mon') || ' to ' || to_char(r.last_at at time zone 'Australia/Melbourne', 'DD Mon')
                   || ' are ' || replace(r.result, '_', ' ') || ' (' || r.reason || ')',
        'expected', 'An approved value is in the catalogue and in the search projection the website reads (mandate 15:37 §10, §12)',
        'source', 'layer4-readiness', 'validation_layer', 'V4',
        'course_ids', case when r.field_code not in ('entry_matrix_first_run', 'entry_matrix_change', 'no_page_first_run', 'conjoint_rule_first_run', 'provider_description') then to_jsonb(r.ents[1:500]) else '[]'::jsonb end,
        'provider_ids', case when r.field_code in ('entry_matrix_first_run', 'entry_matrix_change', 'no_page_first_run', 'conjoint_rule_first_run', 'provider_description') then to_jsonb(r.ents[1:500]) else '[]'::jsonb end,
        'evidence', jsonb_build_object('approvals', r.n, 'decisions', to_jsonb(r.decs[1:20]), 'first_decided', r.first_at, 'last_decided', r.last_at, 'result', r.result, 'reason', r.reason),
        'severity', case when r.reason = 'manual_lock_kept' then 'P2' else 'P1' end,
        'root_cause_class', case when r.reason = 'manual_lock_kept' then 'human_decision' else 'code_defect' end, 'workstream', 'A4'), 'layer4-readiness');
      v_seen := v_seen || v_fp; v_iss := v_iss + 1;
    end loop;
    for r in select x.id, x.status from pipeline.integration_issues x
              where (x.fingerprint like 'l4\_not\_admitted:%' or x.fingerprint like 'l4\_not\_published:%') and x.status <> 'closed' and x.condition_cleared_at is null
                and not (x.fingerprint = any (v_seen)) loop
      update pipeline.integration_issues set condition_cleared_at = now() where id = r.id;
      insert into pipeline.integration_issue_events(issue_id, kind, from_status, to_status, actor, note)
      values (r.id, 'not_observed', r.status, r.status, 'layer4-readiness', 'condition no longer observed; closes after verification');
    end loop;
  end if;
  v_out := jsonb_build_object('classified', v_cls, 'gates', v_g, 'closed', v_closed, 'reconcile', v_rec, 'approvals_checked', v_chk, 'issues', v_iss,
                              'switches', jsonb_build_object('readiness_on', security.pipeline_num_v1('layer4.readiness_on', 1), 'verify_on', security.pipeline_num_v1('layer4.verify_on', 1),
                                                             'arrival_guard_on', security.pipeline_num_v1('layer4.arrival_guard_on', 0), 'reconcile_supersede_on', security.pipeline_num_v1('layer4.reconcile_supersede_on', 0)),
                              'ms', round(extract(epoch from clock_timestamp() - v_t0) * 1000));
  insert into pipeline.layer4_readiness_runs(ms, result) values ((v_out->>'ms')::int, v_out);
  return v_out;
end $$;


ALTER FUNCTION "security"."layer4_readiness_tick_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_reconcile_v1"("p_kind" "text", "p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_res jsonb; v_on boolean := security.pipeline_num_v1('layer4.reconcile_supersede_on', 0) >= 1; v_n int := 0; v_ex int := 0;
        v_by jsonb := '{}'::jsonb; v_kinds text[] := security.pipeline_list_v1('layer4.platform_kinds', '[]'::jsonb);
        v_cap int := greatest(coalesce(p_limit, 0), 0);
        v_max int := greatest(security.pipeline_num_v1('layer4.reconcile_examine_max', 5000)::int, 1);
        v_cur pipeline.layer4_reconcile_cursor; v_last_at timestamptz; v_last_id uuid;
begin
  if v_cap = 0 then
    return jsonb_build_object('on', v_on, 'kind', p_kind, 'examined', 0, 'resolvable', v_by, 'superseded', 0);
  end if;
  if p_kind is null then select * into v_cur from pipeline.layer4_reconcile_cursor where id = 1; end if;
  for r in select i.id, i.field_code, i.entity_type, i.entity_id, i.created_at from pipeline.layer4_review_items i
            where i.status = 'pending' and i.field_code = any (v_kinds) and (p_kind is null or i.field_code = p_kind)
            order by (v_cur.last_created_at is not null and (i.created_at, i.id) <= (v_cur.last_created_at, v_cur.last_item_id)), i.created_at, i.id
            limit v_max loop
    v_ex := v_ex + 1;
    v_last_at := r.created_at; v_last_id := r.id;
    v_res := security.layer4_resolution_v1(r.id);
    continue when v_res is null;
    v_by := jsonb_set(v_by, array[v_res->>'reason'], to_jsonb(coalesce((v_by->>(v_res->>'reason'))::int, 0) + 1));
    continue when not v_on;
    update pipeline.layer4_review_items set status = 'superseded', decided_at = now(),
           change_control_ref = coalesce(change_control_ref || '; ', '') || 'CF-247 L4 readiness: settled by the platform (' || (v_res->>'reason') || ')'
     where id = r.id and status = 'pending';
    continue when not found;
    insert into pipeline.layer4_supersessions(item_id, field_code, entity_type, entity_id, reason, covered_by_item, evidence, mode)
    values (r.id, r.field_code, r.entity_type, r.entity_id, v_res->>'reason', nullif(v_res->>'covered_by_item', '')::uuid, coalesce(v_res->'evidence', '{}'::jsonb), 'reconcile');
    update pipeline.layer4_item_readiness set item_status = 'superseded', readiness = 'closed', classified_at = now() where item_id = r.id;
    v_n := v_n + 1;
    exit when v_n >= v_cap;
  end loop;
  if p_kind is null and v_ex > 0 then
    insert into pipeline.layer4_reconcile_cursor(id, last_created_at, last_item_id, examined, superseded, updated_at)
    values (1, v_last_at, v_last_id, v_ex, v_n, now())
    on conflict (id) do update set last_created_at = excluded.last_created_at, last_item_id = excluded.last_item_id,
                                   examined = excluded.examined, superseded = excluded.superseded, updated_at = excluded.updated_at;
  end if;
  return jsonb_build_object('on', v_on, 'kind', p_kind, 'examined', v_ex, 'resolvable', v_by, 'superseded', v_n);
end $$;


ALTER FUNCTION "security"."layer4_reconcile_v1"("p_kind" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_recovery_headline_v1"("p_state" "text", "p_outcome" "text", "p_at" timestamp with time zone) RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  -- the Platform Admin's wording (observation 4 Nov 2026 13:00 §3) for one corrected read, from its record: queued, deferred, completed and still
  -- held under E13, completed with a replacement read, or completed and not used (with the reason)
  select case
    when p_state = 'requested' then 'Recovery queued — ' || (security.l4_time_v1(p_at)->>'hm')
    when p_state = 'superseded' then 'Recovery completed — replacement read ready for review'
    when p_state = 'refused' and coalesce(p_outcome, '') ~* '(daily (cap|limit)|limit reached|back-pressure|AI limits|budget)' and coalesce(p_outcome, '') !~* 'row limit'
      then 'Recovery deferred — ' || case when p_outcome ~* 'daily' then 'daily limit reached' else p_outcome end
    when p_state = 'refused' and coalesce(p_outcome, '') ~* '(E13|row limit|still drops|has no row|not entry requirements)' then 'Recovery completed — still held under E13'
    when p_state = 'refused' then 'Recovery completed — not used: ' || coalesce(p_outcome, 'refused')
    else null end
$$;


ALTER FUNCTION "security"."layer4_recovery_headline_v1"("p_state" "text", "p_outcome" "text", "p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_refusal_search_cost_v1"("p_days" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with lanes as (select split_part(x, '=', 1) lane, split_part(x, '=', 2) purpose from unnest(security.pipeline_list_v1('layer4.refusal_lane_purposes', '[]'::jsonb)) x),
       since as (select now() - make_interval(days => greatest(coalesce(p_days, 1), 1)) t),
       ref as (select coalesce(i.layer2_state->>'lane', '-') lane, count(*) n from pipeline.layer4_review_items i, since
                where i.field_code = 'official_course_url' and i.layer2_state->>'source' = 'binding check' and i.created_at >= since.t group by 1
               union all
               select coalesce(n.last_refused_lane, '-'), count(*) from pipeline.course_page_needed n, since where n.last_refused_at >= since.t and cardinality(n.converted_items) = 0 group by 1),
       spend as (select u.purpose, sum(u.units) credits, count(*) calls from pipeline.coverage_vendor_usage u, since where u.at >= since.t group by 1)
  select jsonb_build_object('days', p_days, 'lanes', coalesce((select jsonb_agg(jsonb_build_object('lane', l.lane, 'purpose', l.purpose,
             'refusals', coalesce((select sum(r.n) from ref r where r.lane = l.lane), 0),
             'purpose_credits', coalesce((select s.credits from spend s where s.purpose = l.purpose), 0),
             'purpose_calls', coalesce((select s.calls from spend s where s.purpose = l.purpose), 0)) order by l.lane) from lanes l), '[]'::jsonb),
           'other_lanes', (select coalesce(jsonb_object_agg(r.lane, r.n), '{}'::jsonb) from (select lane, sum(n) n from ref where lane not in (select lane from lanes) group by 1) r))
$$;


ALTER FUNCTION "security"."layer4_refusal_search_cost_v1"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_remedy_recheck_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_kind text := security.layer4_issue_kind_v1(p_issue); r record; v_n int := 0; v_by jsonb := '{}'::jsonb; v_res text;
begin
  for r in select c.decision_id from pipeline.layer4_admission_checks c where c.field_code = v_kind and c.result in ('not_admitted', 'admitted_not_published', 'waiting') loop
    v_res := security.layer4_admission_record_v1(r.decision_id);
    v_by := jsonb_set(v_by, array[v_res], to_jsonb(coalesce((v_by->>v_res)::int, 0) + 1));
    v_n := v_n + 1;
  end loop;
  return jsonb_build_object('ok', true, 'changed', false, 'evidence', jsonb_build_object('kind', v_kind, 'rechecked', v_n, 'results', v_by));
end $$;


ALTER FUNCTION "security"."layer4_remedy_recheck_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_remedy_recheck_verify_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.integration_issues; v_kind text; v_reason text; v_res text; v_left int;
begin
  select * into i from pipeline.integration_issues where id = p_issue;
  v_kind := split_part(i.fingerprint, ':', 2); v_reason := split_part(i.fingerprint, ':', 3);
  v_res := case when i.fingerprint like 'l4\_not\_admitted:%' then 'not_admitted' else 'admitted_not_published' end;
  select count(*) into v_left from pipeline.layer4_admission_checks c where c.field_code = v_kind and c.result = v_res and coalesce(c.reason, 'unknown') = v_reason;
  return jsonb_build_object('passed', v_left = 0, 'measure', jsonb_build_object('condition_cleared', v_left = 0, 'failing_left', v_left, 'kind', v_kind, 'reason', v_reason),
                            'evidence', format('%s approval(s) of %s still %s (%s)', v_left, v_kind, v_res, v_reason));
end $$;


ALTER FUNCTION "security"."layer4_remedy_recheck_verify_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_remedy_settle_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_kind text := security.layer4_issue_kind_v1(p_issue); v jsonb;
begin
  if security.pipeline_num_v1('layer4.reconcile_supersede_on', 0) < 1 then
    return jsonb_build_object('ok', false, 'changed', false, 'evidence', jsonb_build_object('reason', 'layer4.reconcile_supersede_on is 0: the Platform Admin decides', 'kind', v_kind));
  end if;
  if not (v_kind = any (security.pipeline_list_v1('layer4.platform_kinds', '[]'::jsonb))) then
    return jsonb_build_object('ok', false, 'changed', false, 'evidence', jsonb_build_object('reason', v_kind || ' is not a kind the platform may settle (layer4.platform_kinds)'));
  end if;
  v := security.layer4_reconcile_v1(v_kind, security.pipeline_num_v1('layer4.reconcile_batch', 200)::int);
  return jsonb_build_object('ok', true, 'changed', (v->>'superseded')::int > 0, 'evidence', v);
end $$;


ALTER FUNCTION "security"."layer4_remedy_settle_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_remedy_settle_verify_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_kind text := security.layer4_issue_kind_v1(p_issue); v_left int; i pipeline.integration_issues;
begin
  select * into i from pipeline.integration_issues where id = p_issue;
  select count(*) into v_left from pipeline.layer4_review_items x
   where x.status = 'pending' and x.field_code = v_kind and security.layer4_resolution_v1(x.id) is not null;
  return jsonb_build_object('passed', v_left = 0,
    'measure', jsonb_build_object('condition_cleared', v_left = 0 and (i.condition_cleared_at is not null and i.last_observed_at <= i.condition_cleared_at),
                                  'waiting', v_left = 0 and not (i.condition_cleared_at is not null and i.last_observed_at <= i.condition_cleared_at),
                                  'resolvable_left', v_left, 'kind', v_kind),
    'evidence', format('%s waiting %s item(s) the platform can still settle; issue check last saw it %s', v_left, v_kind, i.last_observed_at));
end $$;


ALTER FUNCTION "security"."layer4_remedy_settle_verify_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_reread_repeat_v1"("p_item" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare s pipeline.aer_read_supersessions; v_used uuid; v_now uuid; v_cut timestamptz; v_changed jsonb; v_transient boolean; v_row boolean; v_by text;
        v_same int; v_rep boolean;
begin
  select * into s from pipeline.aer_read_supersessions x where x.old_item_id = p_item order by x.requested_at desc limit 1;
  if s.id is null then return jsonb_build_object('repeat', false, 'request', null); end if;
  select f.evidence_id into v_used from pipeline.field_enrich_items f where f.id = s.enrich_item_id;
  select g.evidence_id into v_now from pipeline.coverage_course_pages g where g.course_id = s.course_id;
  v_cut := coalesce(s.closed_at, s.requested_at);
  select coalesce(jsonb_agg(t.key order by t.key), '[]'::jsonb) into v_changed
    from pipeline.platform_toolset_settings t
   where t.toolset_key = 'pipeline' and t.updated_at > v_cut
     and exists (select 1 from jsonb_array_elements_text(coalesce((select w.value from pipeline.platform_toolset_settings w where w.toolset_key = 'pipeline' and w.key = 'layer4.reread_change_keys'),
                                                                 '["entry.%", "layer4.reader_revision"]'::jsonb)) k where t.key like k);
  v_transient := exists (select 1 from jsonb_array_elements_text(coalesce((select w.value from pipeline.platform_toolset_settings w where w.toolset_key = 'pipeline' and w.key = 'layer4.reread_transient_refusals'),
                                                                         '[]'::jsonb)) k where coalesce(s.outcome, '') ilike k);
  v_row := coalesce(s.outcome, '') ilike '%row limit%';
  v_by := case when exists (select 1 from pipeline.layer4_aer_recovery_actions a where a.review_item_id = p_item and a.result->>'request_id' = s.id::text) then 'a reviewer (Re-read from stored evidence)'
               when s.reason ilike 'Human input needed%' then 'Human input needed'
               when s.reason ilike 'Scheduled%' then 'the scheduled entry reading'
               else 'automatic recovery' end;
  select count(*) into v_same from pipeline.aer_read_supersessions x join pipeline.field_enrich_items f on f.id = x.enrich_item_id
   where x.old_item_id = p_item and x.state = 'refused' and f.evidence_id is not distinct from v_used;
  v_rep := s.state = 'refused' and not v_transient and v_used is not distinct from coalesce(v_now, v_used) and jsonb_array_length(v_changed) = 0;
  return jsonb_build_object('repeat', v_rep, 'request', s.id, 'state', s.state, 'outcome', s.outcome, 'requested_by', v_by,
    'requested', security.l4_time_v1(s.requested_at), 'closed', security.l4_time_v1(s.closed_at), 'job_id', s.job_id, 'enrich_item_id', s.enrich_item_id,
    'evidence_used', v_used, 'evidence_now', v_now, 'evidence_changed', v_used is distinct from coalesce(v_now, v_used), 'settings_changed', v_changed,
    'refused_on_this_copy', v_same, 'row_limit', v_row, 'new_item', s.new_item_id,
    'why', case when v_rep then 'the reader refused the corrected read of this stored copy at ' || coalesce(security.l4_time_v1(s.closed_at)->>'text', 'an earlier time')
                                || ' (' || coalesce(s.outcome, 'refused') || '; ' || v_same || ' refusal' || case when v_same = 1 then '' else 's' end
                                || ' on this copy). The copy, the reader and its settings have not changed since, so the same read would be refused again' end,
    'alternative', case when s.state <> 'refused' then null
                        when v_row then 'Ask the Platform Admin for a row limit for this university (Settings › Pipeline settings, entry.max_rows_by_provider); the item is reconsidered by itself when it changes. Typed rows would resume the same refused read'
                        else 'None until the stored copy, the reader (layer4.reader_revision) or an entry setting changes; the item is reconsidered by itself then. Typed rows would resume the same refused read' end);
end $$;


ALTER FUNCTION "security"."layer4_reread_repeat_v1"("p_item" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_reroute_course_v1"("p_course" "uuid", "p_field_code" "text", "p_apply" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_f text := security.layer4_adapter_field_v1(p_field_code); v_ok boolean;
begin
  if v_f is null then return false; end if;
  select true into v_ok from catalogue.courses c join pipeline.uni_adapters a on a.provider_id = c.provider_id
   where c.id = p_course and a.enabled and coalesce(a.admit, false) and (a.admit_fields is null or v_f = any (a.admit_fields))
     and exists (select 1 from pipeline.coverage_course_pages pg where pg.course_id = c.id and pg.status in ('bound', 'ambiguous'));
  if not coalesce(v_ok, false) then return false; end if;
  if p_apply then
    update pipeline.coverage_course_pages set next_read_at = now(), leased_until = null, read_attempts = 0 where course_id = p_course and status in ('bound', 'ambiguous');
  end if;
  return true;
end $$;


ALTER FUNCTION "security"."layer4_reroute_course_v1"("p_course" "uuid", "p_field_code" "text", "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_reroute_parked_courses_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int;
begin
  with x as (
    select r.id, r.entity_id, r.field_code from pipeline.layer4_review_items r
     where r.status = 'pending' and r.entity_type = 'course' and security.layer4_reroute_course_v1(r.entity_id, r.field_code, true)),
  ins as (insert into pipeline.layer4_reroutes(item_id, entity_type, entity_id, field_code, route, note) select x.id, 'course', x.entity_id, x.field_code, 'adapter', 'parked item' from x returning item_id)
  update pipeline.layer4_review_items r set status = 'superseded', decided_at = now(),
         change_control_ref = coalesce(r.change_control_ref || '; ', '') || 'CF-247 v2.15.250: rerouted to the university adapter'
    from ins where r.id = ins.item_id;
  get diagnostics v_n = row_count;
  return jsonb_build_object('rerouted', v_n);
end $$;


ALTER FUNCTION "security"."layer4_reroute_parked_courses_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_reroute_trg_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.entity_type = 'course' and new.status = 'pending' and security.layer4_reroute_course_v1(new.entity_id, new.field_code, true) then
    new.status := 'superseded'; new.decided_at := now();
    new.change_control_ref := coalesce(new.change_control_ref || '; ', '') || 'CF-247 v2.15.250: rerouted to the university adapter';
    insert into pipeline.layer4_reroutes(item_id, entity_type, entity_id, field_code, route, note) values (new.id, 'course', new.entity_id, new.field_code, 'adapter', 'on arrival');
  end if;
  return new;
end $$;


ALTER FUNCTION "security"."layer4_reroute_trg_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_resolution_for_v1"("p_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_field" "text", "p_value" "jsonb", "p_l2" "jsonb", "p_evidence" "uuid", "p_created" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_key text := security.layer4_value_key_v1(p_field, p_value); v_scope text := security.layer4_scope_key_v1(p_field, p_l2, p_value);
        v_prov uuid; v_life text; v_plife text; v_hit record; v_hash text; v_url text; v_txt text;
        v_copy boolean := security.pipeline_num_v1('layer4.same_page_new_copy_settles', 0) >= 1;
begin
  -- the Platform Admin put this item back to waiting: it is asked, never settled again by the platform
  if p_id is not null and exists (select 1 from pipeline.layer4_supersessions s where s.item_id = p_id and s.reversed_at is not null) then return null; end if;
  if p_entity_type = 'course' then
    select c.provider_id, c.lifecycle_status into v_prov, v_life from catalogue.courses c where c.id = p_entity_id;
    select p.lifecycle_status into v_plife from catalogue.providers p where p.id = v_prov;
    if v_prov is null or v_life is distinct from 'active' or v_plife is distinct from 'active' then
      return jsonb_build_object('reason', 'entity_retired', 'evidence', jsonb_build_object('course_status', coalesce(v_life, 'missing'), 'provider_status', coalesce(v_plife, 'missing')));
    end if;
  elsif p_entity_type = 'provider' then
    select p.lifecycle_status into v_plife from catalogue.providers p where p.id = p_entity_id;
    if v_plife is distinct from 'active' then
      return jsonb_build_object('reason', 'entity_retired', 'evidence', jsonb_build_object('provider_status', coalesce(v_plife, 'missing')));
    end if;
  end if;
  select i.id, i.created_at into v_hit from pipeline.layer4_review_items i
   where i.entity_id = p_entity_id and i.field_code = p_field and i.status = 'pending' and i.entity_type = p_entity_type and i.id <> coalesce(p_id, '00000000-0000-0000-0000-000000000000'::uuid)
     and (i.created_at, i.id) < (coalesce(p_created, now()), coalesce(p_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid))
     and security.layer4_scope_key_v1(i.field_code, i.layer2_state, i.proposed_value) = v_scope
     and security.layer4_value_key_v1(i.field_code, i.proposed_value) is not distinct from v_key
   order by i.created_at, i.id limit 1;
  if v_hit.id is not null then
    return jsonb_build_object('reason', 'duplicate_pending', 'covered_by_item', v_hit.id, 'evidence', jsonb_build_object('waiting_since', v_hit.created_at, 'value_key', v_key));
  end if;
  select e.content_hash, e.source_url into v_hash, v_url from pipeline.evidence_artifacts e where e.id = p_evidence;
  select i.id, i.status, i.decided_at, i.evidence_id into v_hit from pipeline.layer4_review_items i
   where i.entity_id = p_entity_id and i.field_code = p_field and i.entity_type = p_entity_type and i.status in ('approved', 'edited_approved', 'rejected')
     and i.decided_at is not null and i.decided_at < coalesce(p_created, now())
     and security.layer4_scope_key_v1(i.field_code, i.layer2_state, i.proposed_value) = v_scope
     and security.layer4_value_key_v1(i.field_code, i.proposed_value) is not distinct from v_key
     and (p_evidence is null or i.evidence_id = p_evidence
          or (v_hash is not null and v_hash = (select e.content_hash from pipeline.evidence_artifacts e where e.id = i.evidence_id))
          or (v_copy and v_url is not null and v_url = (select e.source_url from pipeline.evidence_artifacts e where e.id = i.evidence_id)))
   order by i.decided_at desc limit 1;
  if v_hit.id is not null then
    return jsonb_build_object('reason', 'decided_before', 'covered_by_item', v_hit.id,
      'evidence', jsonb_build_object('decision', v_hit.status, 'decided_at', v_hit.decided_at, 'value_key', v_key,
                                     'same_evidence', case when p_evidence is null then 'no stored page on the new item' when v_hit.evidence_id = p_evidence then 'same stored page'
                                                           when v_hash = (select e.content_hash from pipeline.evidence_artifacts e where e.id = v_hit.evidence_id) then 'same page content'
                                                           else 'same page address, newer copy' end));
  end if;
  -- CF-247 Course Link (mandate 4 Nov 2026 16:32 §3): a question about the page the course shows (refused for this course by the binding check, an
  -- old-year address, an E16 two-page case) is not settled as "already the active page"; a person answers it
  if p_field = 'official_course_url' and v_key is not null and coalesce(p_l2->>'rule', '') not in ('address_year', 'e16_unclear')
     and coalesce(p_l2->>'source', '') not in ('housekeeping H13', 'e16 unclear')
     and not exists (select 1 from pipeline.page_rejections r where r.course_id = p_entity_id and security.layer4_url_key_v1(r.url) = v_key) then
    select l.id, l.url, l.is_primary into v_hit from catalogue.course_links l
     where l.course_id = p_entity_id and l.link_type = 'official_course' and l.status = 'active' and security.layer4_url_key_v1(l.url) = v_key
     order by l.is_primary desc limit 1;
    if v_hit.id is not null then
      return jsonb_build_object('reason', 'covered_by_active', 'evidence', jsonb_build_object('course_link_id', v_hit.id, 'url', v_hit.url, 'primary', v_hit.is_primary));
    end if;
  elsif p_field in ('provider_current_tuition_validation', 'provider_current_tuition') and jsonb_typeof(p_value) = 'object' then
    select f.id, f.amount into v_hit from catalogue.course_fees f
     where f.course_id = p_entity_id and f.status = 'active' and f.fee_type = 'provider_current_tuition'
       and concat_ws('|', coalesce(f.amount::numeric(14, 2)::text, ''), coalesce(upper(f.currency_code), ''), coalesce(lower(f.basis), ''), coalesce(f.fee_year::text, ''),
                     lower(coalesce(f.audience, 'international'))) = v_key
     limit 1;
    if v_hit.id is not null then
      return jsonb_build_object('reason', 'covered_by_active', 'evidence', jsonb_build_object('course_fee_id', v_hit.id, 'value_key', v_key));
    end if;
  elsif p_field = 'course_description_first_read' then
    select nullif(btrim(c.description), '') into v_txt from catalogue.courses c where c.id = p_entity_id;
    if v_txt is not null and v_txt = nullif(btrim(p_value->>'description'), '') then
      return jsonb_build_object('reason', 'covered_by_active', 'evidence', jsonb_build_object('description_chars', length(v_txt)));
    end if;
  end if;
  return null;
end $$;


ALTER FUNCTION "security"."layer4_resolution_for_v1"("p_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_field" "text", "p_value" "jsonb", "p_l2" "jsonb", "p_evidence" "uuid", "p_created" timestamp with time zone) OWNER TO "postgres";


