CREATE OR REPLACE FUNCTION "security"."layer4_url_key_v1"("p_url" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select nullif(regexp_replace(regexp_replace(regexp_replace(lower(btrim(coalesce(p_url, ''))), '^https?://(www\.)?', ''), '#.*$', ''), '/+$', ''), '')
$_$;


