CREATE OR REPLACE FUNCTION "security"."layer4_url_query"("t" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select replace(replace(replace(replace(replace(replace(btrim(coalesce(t,'')),'%','%25'),'&','%26'),'+','%2B'),'#','%23'),'/','%2F'),' ','+')
$$;


ALTER FUNCTION "security"."layer4_url_query"("t" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_validate_override_value"("p_value_kind" "text", "p_value" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'security'
    AS $_$
declare v_text text; v_num numeric;
begin
  if p_value is null then raise exception 'override value is required' using errcode='22023'; end if;
  if p_value_kind in ('text','url','email','phone') then
    if jsonb_typeof(p_value)<>'string' then raise exception 'override value must be a JSON string' using errcode='22023'; end if;
    v_text:=trim(p_value #>> '{}');
    if v_text='' then raise exception 'override value cannot be empty' using errcode='22023'; end if;
    if p_value_kind='url' and v_text !~* '^https?://[^[:space:]]+$' then raise exception 'URL override must use http/https' using errcode='22023'; end if;
    if p_value_kind='email' and v_text !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'invalid email override' using errcode='22023'; end if;
    if p_value_kind='phone' and length(regexp_replace(v_text,'[^0-9+]','','g'))<5 then raise exception 'invalid phone override' using errcode='22023'; end if;
  elsif p_value_kind='duration' then
    if jsonb_typeof(p_value)<>'object' then raise exception 'duration override must be an object' using errcode='22023'; end if;
    v_num:=nullif(p_value->>'value','')::numeric;
    if v_num is null or v_num<=0 or nullif(trim(p_value->>'unit'),'') is null then raise exception 'duration requires positive value and unit' using errcode='22023'; end if;
  elsif p_value_kind='uuid' then
    perform (p_value #>> '{}')::uuid;
  end if;
end $_$;


ALTER FUNCTION "security"."layer4_validate_override_value"("p_value_kind" "text", "p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."layer4_value_key_v1"("p_field" "text", "p_value" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_field = 'official_course_url' then security.layer4_url_key_v1(case jsonb_typeof(p_value) when 'string' then p_value #>> '{}'
                                                                               when 'object' then coalesce(p_value->>'course_url', p_value->>'url') end)
    when p_field in ('provider_current_tuition_validation', 'provider_current_tuition') and jsonb_typeof(p_value) = 'object' then
      concat_ws('|', coalesce(nullif(p_value->>'amount', '')::numeric(14, 2)::text, ''), coalesce(upper(coalesce(p_value->>'currency_code', p_value->>'currency')), ''),
                coalesce(lower(p_value->>'basis'), ''), coalesce(p_value->>'fee_year', ''), lower(coalesce(p_value->>'audience', 'international')))
    when p_field in ('entry_matrix_first_run', 'entry_matrix_change') then p_value->>'run_id'
    when p_field in ('course_description_first_read', 'provider_description') and jsonb_typeof(p_value->'sentences') = 'array' then
      md5((select string_agg(s->>'text', ' ' order by n) from jsonb_array_elements(p_value->'sentences') with ordinality x(s, n)))
    when jsonb_typeof(p_value) = 'object' then md5((p_value - 'checks' - 'item_id' - 'read_id' - 'supersedes')::text)
    else md5(coalesce(p_value::text, 'null')) end
$$;


ALTER FUNCTION "security"."layer4_value_key_v1"("p_field" "text", "p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."lean_qualify_fire_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_due int; v_open int;
begin
  if security.pipeline_num_v1('reading.lean_qualify_on', 0) < 1 then return jsonb_build_object('on', false); end if;
  select count(*) into v_due from pipeline.lean_qualify_cases c where c.state = 'pending' and (c.leased_until is null or c.leased_until < now()) and c.attempts < 2;  -- fixed: two tries
  if v_due = 0 then return jsonb_build_object('on', true, 'due', 0, 'note', 'every qualification page is read'); end if;
  select count(*) into v_open from pipeline.edge_request_log l where l.function_name = 'coverage-sweep' and l.mode = 'lean_qualify' and l.created_at > now() - interval '3 minutes'  -- fixed: fire guard
     and not exists (select 1 from net._http_response r where r.id = l.request_id);
  if v_open >= 2 then return jsonb_build_object('on', true, 'open', v_open); end if;  -- fixed: at most two worker calls at once
  perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'lean_qualify', 'limit', security.pipeline_num_v1('batch.lean_qualify', 6)::int));
  return jsonb_build_object('on', true, 'due', v_due, 'sent', 1);
end $$;


ALTER FUNCTION "security"."lean_qualify_fire_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."lean_qualify_fire_v1"() IS 'CF-247 Lean AI Input Phase 1b-3 (job lean-qualify): calls worker mode lean_qualify while reading.lean_qualify_on is 1 and qualification pages are unread; the ceiling and route holds are enforced by public.svc_lean_qualify_next_v1.';



CREATE OR REPLACE FUNCTION "security"."lean_qualify_report_v1"("p_run" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- per field and kind: pages, reads, cost, the label found by each arm, losses and gains, false values on negatives, quote and answer
  -- checks, input tokens; and the plan's acceptance criteria (section 4) per field
  with r as (select coalesce(p_run, (select c.run_label from pipeline.lean_qualify_cases c order by c.id desc limit 1)) run),
  c as (select x.*, (x.result#>>'{arms,baseline,found}')::boolean bf, (x.result#>>'{arms,candidate,found}')::boolean cf,
               coalesce((x.result#>>'{arms,baseline,values}')::int, 0) bv, coalesce((x.result#>>'{arms,candidate,values}')::int, 0) cv,
               (x.result#>>'{arms,baseline,schema_ok}')::boolean bs, (x.result#>>'{arms,candidate,schema_ok}')::boolean cs,
               (x.result#>>'{arms,candidate,quote_ok}')::boolean cq, (x.result#>>'{arms,baseline,input_tokens}')::int bt, (x.result#>>'{arms,candidate,input_tokens}')::int ct,
               x.result#>>'{arms,baseline,skipped}' bsk, x.result#>>'{arms,candidate,skipped}' csk
          from pipeline.lean_qualify_cases x join r on r.run = x.run_label),
  f as (select c.field, c.kind, count(*) pages, count(*) filter (where c.state = 'done') read, count(*) filter (where c.state = 'failed') failed,
               count(*) filter (where c.state = 'skipped') not_clean_negative, count(*) filter (where c.state = 'pending') pending, round(sum(c.cost_usd), 4) cost_usd,
               count(*) filter (where c.bf) base_found, count(*) filter (where c.cf) cand_found,
               count(*) filter (where c.bf and not coalesce(c.cf, false)) lost, count(*) filter (where c.cf and not coalesce(c.bf, false)) won,
               count(*) filter (where c.state = 'done' and c.bv > 0) base_values, count(*) filter (where c.state = 'done' and c.cv > 0) cand_values,
               count(*) filter (where c.state = 'done' and c.csk is null) cand_reads, count(*) filter (where c.state = 'done' and c.csk is null and c.cs) cand_schema_ok,
               count(*) filter (where c.state = 'done' and c.cv > 0) cand_with_value, count(*) filter (where c.state = 'done' and c.cv > 0 and c.cq) cand_quote_ok,
               (percentile_disc(0.5) within group (order by c.bt) filter (where c.bt is not null))::int median_base_tokens,
               (percentile_disc(0.5) within group (order by c.ct) filter (where c.ct is not null))::int median_cand_tokens
          from c group by c.field, c.kind)
  select jsonb_build_object('run', (select r.run from r), 'ceiling_usd', security.pipeline_num_v1('reading.lean_qualify_ceiling_usd', 0),
    'cost_usd', (select round(coalesce(sum(c.cost_usd), 0), 4) from c), 'admitted', 0,
    'groups', coalesce((select jsonb_agg(to_jsonb(f) order by f.field, f.kind) from f), '[]'::jsonb),
    'criteria', coalesce((select jsonb_agg(jsonb_build_object('field', p.field,
        'no_loss', p.lost = 0, 'no_new_false_values', coalesce(n.cand_values, 0) <= coalesce(n.base_values, 0),
        'quotes_in_text', p.cand_with_value = p.cand_quote_ok,
        'answers_valid_99', case when p.cand_reads > 0 then round(p.cand_schema_ok::numeric / p.cand_reads, 4) >= 0.99 end,
        'fewer_tokens', p.median_cand_tokens < p.median_base_tokens, 'all_read', p.pending = 0 and coalesce(n.pending, 0) = 0)) from f p left join f n on n.field = p.field and n.kind = 'negative' where p.kind = 'positive'), '[]'::jsonb))
$$;


ALTER FUNCTION "security"."lean_qualify_report_v1"("p_run" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."lean_qualify_report_v1"("p_run" "text") IS 'CF-247 Lean AI Input Phase 1b-3: the fees and intakes qualification result per field and kind (labels found by each arm, losses, gains, false values on negatives, quote and answer checks, tokens, cost) and the plan''s acceptance criteria. Read-only.';



CREATE OR REPLACE FUNCTION "security"."lean_qualify_seed_v1"("p_run" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int := 0; v_k int; v_neg int := greatest(0, security.pipeline_num_v1('reading.lean_qualify_negatives', 100)::int);
begin
  -- positives: run phase1b-step1d-2026-11-14 cases whose label is in the reader's own text
  insert into pipeline.lean_qualify_cases (run_label, field, kind, source_ref, course_id, evidence_id, storage_path, gold)
  select p_run, x.field, 'positive', x.source_ref, x.course_id, x.evidence_id, x.storage_path, x.gold
    from pipeline.lean_section_eval_cases x
   where x.run_label = 'phase1b-step1d-2026-11-14' and x.field in ('fees', 'intakes') and x.state = 'done' and x.gold_in_current
  on conflict do nothing;
  get diagnostics v_k = row_count; v_n := v_n + v_k;
  -- fee negatives: course pages the fee reader read with an AI call and found no fee row on
  insert into pipeline.lean_qualify_cases (run_label, field, kind, source_ref, course_id, evidence_id, storage_path)
  select p_run, 'fees', 'negative', 'fee_reader_queue:' || q.id, q.course_id, q.evidence_id, e.storage_path
    from pipeline.fee_reader_queue q join pipeline.evidence_artifacts e on e.id = q.evidence_id
   where q.state = 'done' and q.rows_found = 0 and q.course_id is not null and coalesce(q.cost_usd, 0) > 0 and e.storage_path ~ '\.html'
     and not exists (select 1 from pipeline.lean_qualify_cases z where z.run_label = p_run and z.field = 'fees' and z.course_id = q.course_id)
   order by md5(q.id::text) limit v_neg
  on conflict do nothing;
  get diagnostics v_k = row_count; v_n := v_n + v_k;
  -- intakes negatives: course pages the Enrich reader said do not state the intakes (the worker keeps only pages with no start-date signal)
  insert into pipeline.lean_qualify_cases (run_label, field, kind, source_ref, course_id, evidence_id, storage_path)
  select p_run, 'intakes', 'negative', 'field_enrich_items:' || i.id, i.course_id, i.evidence_id, i.storage_path
    from pipeline.field_enrich_items i
   where i.field = 'intakes' and i.state = 'skipped' and i.reason = 'the page does not state it' and i.storage_path ~ '\.html'
     and not exists (select 1 from pipeline.lean_qualify_cases z where z.run_label = p_run and z.field = 'intakes' and z.course_id = i.course_id)
   order by md5(i.id::text) limit v_neg
  on conflict do nothing;
  get diagnostics v_k = row_count; v_n := v_n + v_k;
  return jsonb_build_object('run', p_run, 'added', v_n);
end $$;


ALTER FUNCTION "security"."lean_qualify_seed_v1"("p_run" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."lean_qualify_seed_v1"("p_run" "text") IS 'CF-247 Lean AI Input Phase 1b-3: adds one run''s qualification cases (run phase1b-step1d-2026-11-14 positives for fees and intakes; up to reading.lean_qualify_negatives negatives per field in a fixed hash order). Inserts only.';



CREATE OR REPLACE FUNCTION "security"."lean_sections_eval_fire_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_due int; v_open int;
begin
  if security.pipeline_num_v1('reading.lean_sections_eval_on', 0) < 1 then return jsonb_build_object('on', false); end if;
  select count(*) into v_due from pipeline.lean_section_eval_cases c where c.state = 'pending' and (c.leased_until is null or c.leased_until < now());
  if v_due = 0 then return jsonb_build_object('on', true, 'due', 0, 'note', 'every labelled case is read'); end if;
  select count(*) into v_open from pipeline.edge_request_log l where l.function_name = 'coverage-sweep' and l.mode = 'lean_sections_eval' and l.created_at > now() - interval '4 minutes'  -- fixed: fire guard
     and not exists (select 1 from net._http_response r where r.id = l.request_id);
  if v_open > 0 then return jsonb_build_object('on', true, 'open', v_open); end if;
  perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'lean_sections_eval', 'limit', security.pipeline_num_v1('batch.lean_sections_eval', 120)::int));
  return jsonb_build_object('on', true, 'due', v_due, 'sent', 1);
end $$;


ALTER FUNCTION "security"."lean_sections_eval_fire_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."lean_sections_eval_fire_v1"() IS 'CF-247 Lean AI Input Phase 1b step 1 (job lean-sections-eval): calls worker mode lean_sections_eval while reading.lean_sections_eval_on is 1 and labelled cases are unread; no AI, no Firecrawl; does nothing when every case is read.';



CREATE OR REPLACE FUNCTION "security"."lean_sections_eval_report_v1"("p_run" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- recall of the section selector on independent labels: of the cases whose value is on the stored page, the share held by the selected sections;
  -- beside it the share held by the first enrich.page_chars characters the current reader is sent, and the beyond-the-cut set (on the page, not in the cut)
  with r as (select coalesce(p_run, (select c.run_label from pipeline.lean_section_eval_cases c order by c.id desc limit 1)) run),
  c as (select x.* from pipeline.lean_section_eval_cases x join r on r.run = x.run_label),
  f as (select c.field, c.gold_source,
               count(*) cases, count(*) filter (where c.state = 'done') read, count(*) filter (where c.state = 'failed') failed,
               count(*) filter (where c.gold_in_page) on_page,
               count(*) filter (where c.gold_in_page and c.gold_in_selection) held_by_selection,
               count(*) filter (where c.gold_in_page and c.gold_in_first_cut) held_by_current_cut,
               count(*) filter (where c.gold_in_page and c.gold_in_lean) held_by_converted_page,
               count(*) filter (where c.gold_in_page and not coalesce(c.gold_in_first_cut, false)) beyond_cut,
               count(*) filter (where c.gold_in_page and not coalesce(c.gold_in_first_cut, false) and c.gold_in_selection) beyond_cut_held_by_selection,
               count(*) filter (where c.no_selection) no_selection,
               (percentile_disc(0.5) within group (order by least(c.page_chars, c.cut_chars)) filter (where c.state = 'done'))::int median_current_sent_chars,
               (percentile_disc(0.5) within group (order by c.page_chars) filter (where c.state = 'done'))::int median_page_chars,
               (percentile_disc(0.5) within group (order by c.selected_chars) filter (where c.state = 'done'))::int median_selected_chars,
               (percentile_disc(0.95) within group (order by c.selected_chars) filter (where c.state = 'done'))::int p95_selected_chars,
               (array_agg(c.id order by c.id) filter (where c.gold_in_page and not coalesce(c.gold_in_selection, false)))[1:20] missed_case_ids  -- fixed: examples shown
          from c group by c.field, c.gold_source)
  select jsonb_build_object('run', (select r.run from r), 'selector', (select max(c.selector) from c), 'converter', (select max(c.converter) from c),
    'ai_calls', 0, 'firecrawl_credits', 0,
    'fields', coalesce((select jsonb_agg(jsonb_build_object('field', f.field, 'labels', f.gold_source, 'cases', f.cases, 'read', f.read, 'failed', f.failed,
        'on_page', f.on_page, 'selection_recall', case when f.on_page > 0 then round(f.held_by_selection::numeric / f.on_page, 4) end,
        'current_cut_recall', case when f.on_page > 0 then round(f.held_by_current_cut::numeric / f.on_page, 4) end,
        'converted_page_recall', case when f.on_page > 0 then round(f.held_by_converted_page::numeric / f.on_page, 4) end,
        'beyond_cut', f.beyond_cut, 'beyond_cut_held_by_selection', f.beyond_cut_held_by_selection, 'no_selection', f.no_selection,
        'median_page_chars', f.median_page_chars, 'median_current_sent_chars', f.median_current_sent_chars,
        'median_selected_chars', f.median_selected_chars, 'p95_selected_chars', f.p95_selected_chars, 'missed_case_ids', to_jsonb(f.missed_case_ids))
        order by f.field, f.gold_source) from f), '[]'::jsonb))
$$;


ALTER FUNCTION "security"."lean_sections_eval_report_v1"("p_run" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."lean_sections_eval_report_v1"("p_run" "text") IS 'CF-247 Lean AI Input Phase 1b step 1: selector recall on independent labels per field and label source, against the current reader''s first-cut recall; the beyond-the-cut set; sizes; missed case ids. Read-only.';



CREATE OR REPLACE FUNCTION "security"."lean_sections_eval_seed_v1"("p_run" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int := 0; v_k int; v_per int := greatest(1, security.pipeline_num_v1('reading.lean_sections_eval_sample', 400)::int);
begin
  -- (1) entry requirements a person accepted in Layer 4, on the very stored page the person judged
  insert into pipeline.lean_section_eval_cases (run_label, field, gold_source, source_ref, course_id, evidence_id, storage_path, gold)
  select p_run, 'entry_requirements', 'aer_accepted', l.row_id::text, l.course_id, l.evidence_id, e.storage_path,
         jsonb_build_array(left(l.quote, 160))  -- fixed: the compared opening of a long quote (a quote may be cut by the reader's own limit)
    from pipeline.aer_labelled_rows_v1 l join pipeline.evidence_artifacts e on e.id = l.evidence_id
   where l.source_kind = 'course_page' and l.label = 'accepted' and length(security.aer_flat_v1(l.quote)) >= 12 and e.storage_path ~ '\.html'  -- fixed: a quote too short to identify is not a label
   order by md5(l.row_id::text) limit v_per
  on conflict do nothing;
  get diagnostics v_k = row_count; v_n := v_n + v_k;
  -- (2) values read by tested university adapters, on the course's bound stored page
  with r as (select distinct on (x.course_id) x.id, x.course_id, x.fields from pipeline.uni_adapter_results x order by x.course_id, x.at desc),
  g as (select r.id, r.course_id, p.evidence_id, e.storage_path, f.field, f.gold
          from r join pipeline.coverage_course_pages p on p.course_id = r.course_id join pipeline.evidence_artifacts e on e.id = p.evidence_id
          cross join lateral (values
            ('duration', case when length(r.fields->'extra'->>'duration') >= 3 then jsonb_build_array(r.fields->'extra'->>'duration') end),
            ('campus', case when length(r.fields->'extra'->>'campus') >= 3 then jsonb_build_array(r.fields->'extra'->>'campus') end),
            ('delivery', case when length(r.fields->'extra'->>'mode') >= 3 then jsonb_build_array(r.fields->'extra'->>'mode') end),
            ('entry_requirements', case when length(r.fields->'extra'->>'entry_requirement') >= 20 then jsonb_build_array(left(r.fields->'extra'->>'entry_requirement', 120)) end),  -- fixed: the compared opening of a long reading
            ('intakes', case when r.fields->>'intakes_by' = 'adapter' and jsonb_typeof(r.fields->'intakes') = 'array' and jsonb_array_length(r.fields->'intakes') > 0 then r.fields->'intakes' end),
            ('fees', case when jsonb_typeof(r.fields->'fee') = 'number' and (r.fields->>'fee')::numeric >= 1000 then jsonb_build_array(round((r.fields->>'fee')::numeric)::bigint::text) end)  -- fixed: an amount below this is not a yearly tuition fee
          ) f(field, gold)
         where f.gold is not null and e.storage_path ~ '\.html'),
  s as (select g.*, row_number() over (partition by g.field order by md5(g.id::text || g.field)) rn from g)
  insert into pipeline.lean_section_eval_cases (run_label, field, gold_source, source_ref, course_id, evidence_id, storage_path, gold)
  select p_run, s.field, 'adapter', s.id::text, s.course_id, s.evidence_id, s.storage_path, s.gold from s where s.rn <= v_per
  on conflict do nothing;
  get diagnostics v_k = row_count; v_n := v_n + v_k;
  return jsonb_build_object('run', p_run, 'added', v_n, 'per_field_and_source', v_per);
end $$;


ALTER FUNCTION "security"."lean_sections_eval_seed_v1"("p_run" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."lean_sections_eval_seed_v1"("p_run" "text") IS 'CF-247 Lean AI Input Phase 1b step 1: adds the labelled cases of one run (Layer 4 accepted entry-requirement rows on their judged page; tested adapter readings on the bound page), reading.lean_sections_eval_sample per field and source in a fixed hash order. Inserts only.';



CREATE OR REPLACE FUNCTION "security"."ledger_retention_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n_ledger int; n_zy int; n_h int; n_ui int; n_ai int;
begin
  delete from pipeline.mode_outcome_ledger where run_at < now() - make_interval(days => security.pipeline_num_v1('retention.mode_outcome_ledger_days', 90)::int);
  get diagnostics n_ledger = row_count;
  delete from pipeline.zero_yield_snapshots where at < now() - make_interval(days => security.pipeline_num_v1('retention.zero_yield_snapshots_days', 90)::int);
  get diagnostics n_zy = row_count;
  delete from pipeline.health_snapshots where at < now() - make_interval(days => security.pipeline_num_v1('retention.health_snapshots_days', 90)::int);
  get diagnostics n_h = row_count;
  delete from pipeline.ui_error_log where at < now() - make_interval(days => security.pipeline_num_v1('retention.ui_error_log_days', 90)::int);
  get diagnostics n_ui = row_count;
  delete from pipeline.ai_invocations where at < now() - make_interval(days => security.pipeline_num_v1('retention.ai_invocations_days', 90)::int);
  get diagnostics n_ai = row_count;
  return jsonb_build_object('mode_outcome_ledger', n_ledger, 'zero_yield_snapshots', n_zy, 'health_snapshots', n_h, 'ui_error_log', n_ui, 'ai_invocations', n_ai);
end $$;


ALTER FUNCTION "security"."ledger_retention_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."ledger_retention_v1"() IS 'daily: removes worker-ledger rows and zero-yield snapshots older than their retention settings';



CREATE OR REPLACE FUNCTION "security"."link_refresh_policy_days"("p_course_id" "uuid", "p_link_type" "text") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select r.every_days from pipeline.link_refresh_policies r
    join catalogue.courses c on c.id = p_course_id join catalogue.providers p on p.id = c.provider_id
   where r.active and r.link_type = p_link_type
     and (r.provider_id is null or r.provider_id = c.provider_id)
     and (r.country_id is null or r.country_id = p.country_id)
   order by (r.provider_id is not null) desc, (r.country_id is not null) desc
   limit 1
$$;


ALTER FUNCTION "security"."link_refresh_policy_days"("p_course_id" "uuid", "p_link_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."link_refresh_tick_v1"("p_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_lim int := greatest(1, least(coalesce(p_limit, 500), 5000)); v_reread int := 0; v_research int := 0; v_verified int := 0;
        v_unverified int := 0; v_reg int := 0; v_manual uuid; v_l4 uuid;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select id into v_manual from pipeline.sources where source_type = 'manual_entry' limit 1;
  select id into v_l4 from pipeline.sources where source_type = 'layer4_human_review' limit 1;

  -- 1. Official pages due for a re-check: the reader reads them again.
  with due as (
    select p.course_id from pipeline.coverage_course_pages p
     where p.status = 'bound' and p.read_status = 'read' and p.identity_basis is not null
       and coalesce(p.next_read_at, now()) <= now() and coalesce(p.leased_until, '-infinity') < now()
       and p.read_at < now() - make_interval(days => coalesce(security.link_refresh_policy_days(p.course_id, 'official_course'), 30))
     order by p.read_at limit v_lim)
  update pipeline.coverage_course_pages p set next_read_at = now(), read_attempts = 0 from due where p.course_id = due.course_id;
  get diagnostics v_reread = row_count;

  -- 2. Courses whose page search found nothing are searched again after their policy period.
  with due as (
    select s.course_id from pipeline.course_link_search s
     where s.state in ('none','error')
       and coalesce(s.done_at, s.queued_at) < now() - make_interval(days => coalesce(security.link_refresh_policy_days(s.course_id, 'official_course'), 30))
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = s.course_id and k.field = 'official_url')
     order by coalesce(s.done_at, s.queued_at) limit v_lim)
  update pipeline.course_link_search s set state = 'queued', stage = 'cricos', attempts = 0, done_at = null, queued_at = now()
    from due where s.course_id = due.course_id;
  get diagnostics v_research = row_count;

  -- 3. Carry each read to the catalogue link (never a link set by a person or confirmed in Layer 4).
  update catalogue.course_links l set last_verified_at = p.read_at, updated_at = now()
    from pipeline.coverage_course_pages p
   where l.link_type = 'official_course' and l.status = 'active' and p.course_id = l.course_id
     and security.coverage_norm_url(p.url) = security.coverage_norm_url(l.url)
     and p.read_status = 'read' and p.identity_basis is not null and p.read_at > coalesce(l.last_verified_at, '-infinity')
     and l.source_id is distinct from v_manual and l.source_id is distinct from v_l4;
  get diagnostics v_verified = row_count;

  with gone as (
    select l.id, l.course_id from catalogue.course_links l
      join pipeline.coverage_course_pages p on p.course_id = l.course_id and security.coverage_norm_url(p.url) = security.coverage_norm_url(l.url)
     where l.link_type = 'official_course' and l.status = 'active'
       and l.source_id is distinct from v_manual and l.source_id is distinct from v_l4
       and p.read_at > coalesce(l.last_verified_at, l.created_at)
       and p.read_status = 'fetch_failed' and p.http_status in (404, 410) and p.read_attempts >= 2
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = l.course_id and k.field = 'official_url')
     limit v_lim),
  upd as (update catalogue.course_links l set status = 'unverified', is_primary = false, updated_at = now() from gone where l.id = gone.id returning l.course_id),
  -- a page that still loads but no longer shows the course's code keeps its link; the course is searched again, and a
  -- better page found that way reaches Layer 4 as "differs" through the normal admission path.
  doubt as (
    select l.course_id from catalogue.course_links l
      join pipeline.coverage_course_pages p on p.course_id = l.course_id and security.coverage_norm_url(p.url) = security.coverage_norm_url(l.url)
     where l.link_type = 'official_course' and l.status = 'active' and p.read_status = 'identity_mismatch'
       and p.read_at > coalesce(l.last_verified_at, l.created_at)
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = l.course_id and k.field = 'official_url')
     limit v_lim),
  ins as (
    insert into pipeline.course_link_search(course_id, provider_id)
    select distinct x.course_id, c.provider_id from (select course_id from upd union select course_id from doubt) x join catalogue.courses c on c.id = x.course_id
     where exists (select 1 from pipeline.course_link_recipes r where r.provider_id = c.provider_id and r.active)
    on conflict (course_id) do update set state = 'queued', stage = 'cricos', attempts = 0, done_at = null, queued_at = now()
     where pipeline.course_link_search.state in ('none','error')
       and coalesce(pipeline.course_link_search.done_at, pipeline.course_link_search.queued_at)
           < now() - make_interval(days => coalesce(security.link_refresh_policy_days(excluded.course_id, 'official_course'), 30))
    returning 1)
  select (select count(*) from upd) into v_unverified;

  -- 4. Regulator listings for NZ courses that gained an NZQA code.
  insert into catalogue.course_links(course_id, link_type, url, label, is_primary, status, source_id, confidence)
  select r.course_id, 'regulator_listing',
         'https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=' || upper(btrim(r.registration_code)),
         'NZQA qualification listing', false, 'active',
         (select s.id from pipeline.sources s where s.url ilike 'https://www.nzqa.govt.nz/providers/%' order by s.created_at limit 1), 0.95
    from catalogue.course_registrations r join catalogue.courses c on c.id = r.course_id and c.lifecycle_status = 'active'
   where lower(r.scheme) = 'nzqa' and coalesce(r.status, 'active') = 'active' and btrim(r.registration_code) ~* '^[A-Z0-9]{3,12}$'
     and exists (select 1 from pipeline.link_portals lp where lp.code = 'nzqa' and lp.active)
     and not exists (select 1 from catalogue.course_links l where l.course_id = r.course_id and l.link_type = 'regulator_listing')
   limit v_lim
  on conflict (course_id, link_type, url) do nothing;
  get diagnostics v_reg = row_count;

  update pipeline.link_refresh_policies set last_run_at = now(),
         last_result = jsonb_build_object('reread', v_reread, 'searched_again', v_research, 'verified', v_verified, 'unverified', v_unverified, 'regulator_added', v_reg)
   where active and provider_id is null and country_id is null;
  return jsonb_build_object('reread', v_reread, 'searched_again', v_research, 'verified', v_verified, 'unverified', v_unverified, 'regulator_added', v_reg);
end $_$;


ALTER FUNCTION "security"."link_refresh_tick_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."link_search_block_v1"("p_provider" "uuid", "p_course_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_job record; v_flag record; v_on boolean; v_cap numeric; v_used numeric; v_left numeric; v_rc record; v_person boolean; v_memo text := current_setting('cf.link_search_block_totals', true);
        v_bypass boolean := security.pipeline_num_v1('search.person_task_bypass', 1) >= 1;
begin
  -- hotfix 3: one query, not one per course
  v_person := p_course_ids is not null and exists (select 1 from pipeline.admin_jobs j where j.kind = 'course_page_find' and j.state in ('queued', 'running')
                                                     and j.args->>'provider_id' = p_provider::text and j.args->'course_ids' ?| p_course_ids::text[]);
  select j.active into v_job from cron.job j where j.jobname = 'course-link-search-worker';
  select f.flagged_at, f.next_check_at into v_flag from pipeline.enrichment_flags f
   where f.entity = 'job' and f.entity_key = 'course-link-search-worker' and f.reason_code = 'idle_paused' and f.state = 'raised' order by f.flagged_at desc limit 1;
  if v_job.active is distinct from true and v_flag.flagged_at is null then
    return jsonb_build_object('code', 'lane_paused', 'words', 'The course page search lane is switched off', 'fix', 'Scheduled jobs › Automations › Find course pages (search): Resume');
  end if;
  if v_flag.flagged_at is not null then
    return jsonb_build_object('code', 'lane_idle_paused', 'words', 'The course page search lane is paused by the idle guard until ' || to_char(v_flag.next_check_at at time zone 'Australia/Melbourne', 'HH24:MI'), 'fix', 'It wakes by itself when work waits; nothing to do');
  end if;
  select s.enabled, s.monthly_credit_cap into v_on, v_cap from pipeline.course_link_search_settings s where s.id = 1;
  if not coalesce(v_on, false) then return jsonb_build_object('code', 'search_off', 'words', 'Course page search is switched off', 'fix', 'Models & services › Toolsets & limits › Firecrawl › course search'); end if;
  -- hotfix 3: the month and day totals are the same for every task in one request; worked out once per statement and reused
  if v_memo is not null and split_part(v_memo, '|', 1) = statement_timestamp()::text then
    v_used := split_part(v_memo, '|', 2)::numeric; v_left := split_part(v_memo, '|', 3)::numeric;
  else
    select coalesce(sum(u.units), 0) into v_used from pipeline.coverage_vendor_usage u where u.purpose = 'course_link_search' and u.at >= date_trunc('month', now());
    v_left := security.fc_budget_left_v1('course_link_search');
    perform set_config('cf.link_search_block_totals', statement_timestamp()::text || '|' || v_used || '|' || v_left, true);
  end if;
  if v_used + 2 > v_cap then return jsonb_build_object('code', 'month_cap', 'words', 'This month''s course search credits are used (' || v_used::int || ' of ' || v_cap::int || ')', 'fix', 'Waits for next month, or raise the monthly cap'); end if;
  if v_left < 2 then
    -- 8 Nov 2026 (lane aer2): while the priority floor is what holds it (the plan's balance is kept for higher-priority work) it does not continue tomorrow
    if coalesce(security.fc_priority_room_v1(), 2) < 2 then  -- fixed: 2 credits are one search, as this function and the picker count it
      return jsonb_build_object('code', 'day_budget', 'words', 'Course page search is paused to keep the Firecrawl balance for higher-priority work (credits kept back: ' || security.fc_setting_num_v1('priority_floor_course_search', 0)::bigint || ')',
                                'fix', 'Starts again by itself when the balance is back above the floor; the floor is set at Models & services › Toolsets & limits › Firecrawl › Credits kept back from course page search');
    end if;
    return jsonb_build_object('code', 'day_budget', 'words', 'Today''s Firecrawl share for course search is used', 'fix', 'Waits for tomorrow''s share');
  end if;
  -- R2: the day's picked-courses cap (a person's running task is not held by it)
  if not (v_bypass and v_person) and (select count(*) from pipeline.course_link_search s where s.sent_at >= (date_trunc('day', now() at time zone 'UTC') at time zone 'UTC'))
       >= security.pipeline_num_v1('search.daily_picked_cap', 100) then
    return jsonb_build_object('code', 'daily_cap', 'words', 'Today''s course search cap (' || security.pipeline_num_v1('search.daily_picked_cap', 100)::int || ' courses) is reached; searching resumes at 00:00 UTC', 'fix', 'Settings › Pipeline settings › Course search: courses a day');
  end if;
  if exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p_provider) then
    return jsonb_build_object('code', 'provider_hidden', 'words', 'The university is unpublished or archived; its searches wait', 'fix', 'Publish the university');
  end if;
  -- hotfix 3: the stop for this one university (fc_search_stopped_v1 works it out for every university)
  if security.search_stop_gate_v1(p_provider, null, null, v_person) = 'search_stopped' then  -- S1: the one stop gate
    return jsonb_build_object('code', 'search_stopped', 'words', 'The automatic search stopped for this university (wrong pages in a row, or too many searches with no page)' || case when not v_bypass then '; a person''s task waits too (search.person_task_bypass is off)' else '' end, 'fix', 'Adapter builder › Find course pages › Search again, or a person''s Find course pages task');
  end if;
  if coalesce((security.firecrawl_setting('target_only') #>> '{}')::boolean, true)
     and not exists (select 1 from pipeline.firecrawl_target_cache tc where tc.provider_id = p_provider and tc.included) then
    return jsonb_build_object('code', 'not_target', 'words', 'Firecrawl is for target universities only and this one is not a target', 'fix', 'Models & services › Toolsets & limits › Firecrawl targets');
  end if;
  select rc.search_domain into v_rc from pipeline.course_link_recipes rc where rc.provider_id = p_provider and rc.active limit 1;
  if v_rc.search_domain is null then return jsonb_build_object('code', 'no_site', 'words', 'No website is recorded to search', 'fix', 'Adapter builder step 1: the website'); end if;
  if security.third_party_host_v1('https://' || v_rc.search_domain) then return jsonb_build_object('code', 'directory_site', 'words', 'The recorded website is a course directory, not the university''s own', 'fix', 'Adapter builder step 1: change the website'); end if;
  if exists (select 1 from catalogue.providers px, pipeline.platform_toolset_settings sk
              where px.id = p_provider and sk.toolset_key = 'pipeline' and sk.key = 'search.skip_providers' and sk.value ? px.stable_key) then
    return jsonb_build_object('code', 'skipped_provider', 'words', 'This university is on the search skip list', 'fix', 'Settings › Pipeline settings › search.skip_providers');
  end if;
  return null;
end $$;


