    perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'nz_cop', 'limit', security.pipeline_num_v1('batch.nz_cop', 3)::int));
    return 1;
  end if;
  perform security.nz_cop_apply_v1();
  return 0;
end $$;


