CREATE OR REPLACE FUNCTION "security"."ops_remedy_register_v1"("p_code" "text", "p_spec" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_auth text := p_spec->>'authority'; v_treats text[]; v_fn regprocedure; v_vf regprocedure; v_tmp regprocedure; v_k text; v_new boolean; v_bad text;
begin
  if security.ops_remedy_guard_active_v1() then raise exception 'ops guard: a remedy cannot change the remedy register' using errcode = '42501'; end if;
  if coalesce(p_code, '') !~ '^[a-z][a-z0-9_]*$' then raise exception 'a remedy code is lower case letters, digits and underscores' using errcode = '22023'; end if;
  if p_spec is null or jsonb_typeof(p_spec) <> 'object' then raise exception 'remedy %: give a spec object', p_code using errcode = '22023'; end if;
  if coalesce(v_auth, '') not in ('auto', 'release', 'admin') then raise exception 'remedy %: authority must be auto, release or admin', p_code using errcode = '22023'; end if;
  if length(btrim(coalesce(p_spec->>'title', ''))) < 3 then raise exception 'remedy %: give it a title', p_code using errcode = '22023'; end if;
  v_treats := coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(p_spec->'treats', '[]'::jsonb)) x), '{}');
  if cardinality(v_treats) = 0 then raise exception 'remedy %: name the root causes it treats', p_code using errcode = '22023'; end if;
  select string_agg(t, ', ') into v_bad from unnest(v_treats) t where not exists (select 1 from pipeline.ops_root_causes r where r.code = t);
  if v_bad is not null then raise exception 'remedy %: unknown root cause(s) %', p_code, v_bad using errcode = '22023'; end if;
  foreach v_k in array array['action_fn', 'verify_fn'] loop
    if nullif(p_spec->>v_k, '') is not null then
      v_tmp := to_regprocedure(p_spec->>v_k);
      if v_tmp is null then raise exception 'remedy %: % % does not exist', p_code, v_k, p_spec->>v_k using errcode = '42883'; end if;
      if not exists (select 1 from pg_proc p join pg_language l on l.oid = p.prolang
                      where p.oid = v_tmp and p.pronargs = 1 and p.proargtypes[0] = 'bigint'::regtype and p.prorettype = 'jsonb'::regtype and l.lanname in ('sql', 'plpgsql')) then
        raise exception 'remedy %: % must be an SQL or PL/pgSQL function (p_issue bigint) returning jsonb', p_code, v_k using errcode = '22023';
      end if;
      if pg_get_functiondef(v_tmp) ~* '(set_config|cf247\.ops_remedy|session_replication_role|disable\s+trigger|ops_remedies|ops_root_causes|ops_remedy_register|ops_root_cause_register|max_value|min_value)' then
        raise exception 'remedy %: % reaches the authority boundary (guard switch, triggers, registers or settings ceilings); that is a release change, not a remedy', p_code, v_k using errcode = '42501';
      end if;
      if v_k = 'action_fn' then v_fn := v_tmp; else v_vf := v_tmp; end if;
    end if;
  end loop;
  if v_auth = 'auto' and (v_fn is null or v_vf is null) then raise exception 'remedy %: an auto remedy needs an action and a verification', p_code using errcode = '22023'; end if;
  foreach v_k in array array['max_attempts_key', 'cooldown_key'] loop
    if nullif(p_spec->>v_k, '') is not null and not exists (select 1 from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = p_spec->>v_k) then
      raise exception 'remedy %: setting % (%) does not exist', p_code, p_spec->>v_k, v_k using errcode = '22023';
    end if;
  end loop;
  v_new := not exists (select 1 from pipeline.ops_remedies where code = p_code);
  insert into pipeline.ops_remedies as r(code, title, treats, authority, action_fn, verify_fn, max_attempts_key, cooldown_key, active, notes)
  values (p_code, btrim(p_spec->>'title'), v_treats, v_auth, v_fn, v_vf, nullif(p_spec->>'max_attempts_key', ''), nullif(p_spec->>'cooldown_key', ''),
          coalesce((p_spec->>'active')::boolean, true), p_spec->>'notes')
  on conflict (code) do update set title = excluded.title, treats = excluded.treats, authority = excluded.authority, action_fn = excluded.action_fn,
     verify_fn = excluded.verify_fn, max_attempts_key = excluded.max_attempts_key, cooldown_key = excluded.cooldown_key, active = excluded.active, notes = excluded.notes;
  return jsonb_build_object('code', p_code, 'action', case when v_new then 'created' else 'replaced' end, 'authority', v_auth);
end $_$;


ALTER FUNCTION "security"."ops_remedy_register_v1"("p_code" "text", "p_spec" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ops_remedy_supersede_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.integration_issues; o pipeline.integration_issues; v_owner bigint; v_max int := security.pipeline_num_v1('integration.entity_ids_max', 500)::int;
begin
  select * into r from pipeline.integration_issues where id = p_issue;
  v_owner := security.ops_group_owner_v1(r.correlation_key);
  if v_owner is null or v_owner = p_issue then
    return jsonb_build_object('ok', false, 'changed', false, 'evidence', jsonb_build_object('reason', 'no other open issue owns this cause', 'key', r.correlation_key));
  end if;
  select * into o from pipeline.integration_issues where id = v_owner for update;
  update pipeline.integration_issues set superseded_by = v_owner, updated_at = now() where id = p_issue;
  update pipeline.integration_issues i set supersedes = (select coalesce(array_agg(distinct x), '{}') from unnest(i.supersedes || p_issue) x),
         evidence = i.evidence || jsonb_build_object('superseded', coalesce(i.evidence->'superseded', '{}'::jsonb) || jsonb_build_object(r.issue_ref,
                    jsonb_build_object('fingerprint', r.fingerprint, 'title', r.title, 'failure', left(r.failure, 500), 'evidence', r.evidence, 'detected_at', r.detected_at,
                                       'providers', cardinality(r.provider_ids), 'courses', cardinality(r.course_ids)))),
         provider_ids = (select coalesce(array_agg(distinct x), '{}') from unnest(i.provider_ids || r.provider_ids) x)[1:v_max],
         course_ids = (select coalesce(array_agg(distinct x), '{}') from unnest(i.course_ids || r.course_ids) x)[1:v_max],
         updated_at = now()
   where i.id = v_owner;
  insert into pipeline.integration_issue_events(issue_id, kind, from_status, to_status, actor, note, detail) values
    (p_issue, 'updated', r.status, r.status, 'ops-controller', 'Superseded by ' || o.issue_ref || ' (shared cause ' || r.correlation_key || ')', jsonb_build_object('superseded_by', v_owner)),
    (v_owner, 'updated', o.status, o.status, 'ops-controller', 'Supersedes ' || r.issue_ref || ' (shared cause ' || r.correlation_key || '); its evidence is carried over', jsonb_build_object('supersedes', p_issue));
  return jsonb_build_object('ok', true, 'changed', true, 'evidence', jsonb_build_object('owner', v_owner, 'owner_ref', o.issue_ref, 'key', r.correlation_key));
end $$;


ALTER FUNCTION "security"."ops_remedy_supersede_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ops_report_v1"("p_window_hours" integer DEFAULT 24) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_since timestamptz := now() - make_interval(hours => greatest(coalesce(p_window_hours, 24), 1));
        v_scan int := security.pipeline_num_v1('ops.runs_scan', 20000)::int; v_items int := security.pipeline_num_v1('ops.report_items_scan', 200000)::int;
        v_out jsonb := '{}'::jsonb; v jsonb; v_eligible int; v_resolved int; v_x jsonb; v_maxid bigint;
begin
  v_out := jsonb_build_object('window_hours', p_window_hours, 'since', v_since, 'generated_at', now(),
    'operating_mode', (select jsonb_build_object('mode', m.mode, 'set_by', m.set_by, 'set_at', m.set_at) from pipeline.integration_operating_mode m where m.id = 1),
    'controller', (select jsonb_build_object('on', security.pipeline_num_v1('ops.controller_on', 1) >= 1, 'job_active', coalesce((select j.active from cron.job j where j.jobname = 'ops-controller'), false),
                   'last_run', s.last_run_at, 'last', s.detail) from pipeline.integration_validate_state s where s.check_key = 'ops_controller'));

  -- platform health: scheduler and workers, failures, time-outs, stuck work, recovery
  begin
    with d as (select x.jobid, x.status, x.return_message, x.start_time from cron.job_run_details x
                where x.runid > (select coalesce(max(y.runid), 0) from cron.job_run_details y) - v_scan and x.start_time >= v_since)
    select jsonb_build_object('active_jobs', (select count(*) from cron.job j where j.active), 'runs', count(*), 'failed', count(*) filter (where d.status = 'failed'),
             'failed_timeouts', count(*) filter (where d.status = 'failed' and d.return_message ~* '(statement timeout|canceling statement|timed? ?out)'),
             'failing_jobs', coalesce((select jsonb_agg(jsonb_build_object('job', z.jobname, 'failed', z.n, 'last', z.msg) order by z.n desc) from (
                select j.jobname, count(*) n, (array_agg(left(split_part(d2.return_message, E'\n', 1), 160) order by d2.start_time desc))[1] msg from d d2 join cron.job j on j.jobid = d2.jobid
                 where d2.status = 'failed' group by j.jobname order by count(*) desc limit 10) z), '[]'::jsonb))
      into v from d;
    v := v || jsonb_build_object('workers', (select jsonb_build_object('calls', count(*), 'failed_calls', count(*) filter (where l.status >= 400 or coalesce(l.failed, 0) > 0),
               'items', coalesce(sum(l.items), 0), 'ok', coalesce(sum(l.ok), 0), 'zero_item_calls', count(*) filter (where coalesce(l.items, 0) = 0))
               from pipeline.mode_outcome_ledger l where l.run_at >= v_since),
             'stuck', jsonb_build_object('stale_lease_issues', (select count(*) from pipeline.integration_issues i where i.status <> 'closed' and i.fingerprint like 'stale_lease:%'),
               'stuck_draft_issues', (select count(*) from pipeline.integration_issues i where i.status <> 'closed' and i.fingerprint like 'draft_stuck:%'),
               'tasks_running_without_progress', (select count(*) from pipeline.admin_jobs j where j.state = 'running'
                  and j.updated_at < now() - make_interval(mins => security.pipeline_num_v1('integration.lease_stale_minutes', 60)::int))),
             'recovery', (select coalesce(jsonb_object_agg(z.result, z.n), '{}'::jsonb) from (select u.result, count(*) n from pipeline.ops_remedy_runs u where u.started_at >= v_since group by 1) z));
    v_out := v_out || jsonb_build_object('platform_health', v);
  exception when others then v_out := v_out || jsonb_build_object('platform_health', jsonb_build_object('error', left(sqlerrm, 200)));
  end;

  -- data improvement: missing values at the start and end of the window, values filled, courses repaired, scholarships, page identities
  begin
    select max(id) into v_maxid from pipeline.field_enrich_items;
    v := jsonb_build_object(
      'missing_values', (with s as (select min(g.at) a0, max(g.at) a1 from pipeline.gap_cause_snapshots g where g.at >= v_since)
                         select coalesce(jsonb_object_agg(x.attribute, jsonb_build_object('start', x.st, 'end', x.en, 'change', x.en - x.st)), '{}'::jsonb)
                           from (select g.attribute, sum(g.courses) filter (where g.at = s.a0) st, sum(g.courses) filter (where g.at = s.a1) en
                                   from pipeline.gap_cause_snapshots g, s where g.at in (s.a0, s.a1) group by g.attribute) x),
      'field_values', (select coalesce(jsonb_object_agg(x.field, jsonb_build_object('filled', x.f, 'to_review', x.rv, 'skipped', x.sk, 'failed', x.fa)), '{}'::jsonb)
                         from (select e.field, count(*) filter (where e.state = 'filled') f, count(*) filter (where e.state = 'review') rv,
                                      count(*) filter (where e.state = 'skipped') sk, count(*) filter (where e.state = 'failed') fa
                                 from pipeline.field_enrich_items e where e.id > coalesce(v_maxid, 0) - v_items and e.updated_at >= v_since group by e.field) x),
      'courses_repaired', (select count(distinct e.course_id) from pipeline.field_enrich_items e where e.id > coalesce(v_maxid, 0) - v_items and e.updated_at >= v_since and e.state = 'filled'),
      'scholarships_added', (select count(*) from scholarship.scholarships s where s.created_at >= v_since),
      'scholarships_published', (select count(*) from scholarship.scholarships s where s.created_at >= v_since and s.publication_status = 'published'),
      'page_identities_proven', (select count(*) from pipeline.course_page_proofs p where p.proven and p.checked_at >= v_since));
    v_out := v_out || jsonb_build_object('data_improvement', v);
  exception when others then v_out := v_out || jsonb_build_object('data_improvement', jsonb_build_object('error', left(sqlerrm, 200)));
  end;

  -- autonomy, with the scorecard metrics (acceptance mandate §17, §18)
  begin
    select count(*) filter (where c.class <> 'policy'), count(*) filter (where c.class <> 'policy' and i.status = 'closed' and i.closed_at >= v_since and i.verified_by = 'ops-controller')
      into v_eligible, v_resolved
      from pipeline.integration_issues i join pipeline.ops_root_causes c on c.code = i.diagnosis->>'root_cause'
     where (i.status <> 'closed' or i.closed_at >= v_since) and i.detected_at < now();
    v := jsonb_build_object(
      'detected', (select count(*) from pipeline.integration_issues i where i.detected_at >= v_since),
      'detected_automatically', (select count(*) from pipeline.integration_issues i where i.detected_at >= v_since and i.validation_layer in ('V3', 'V4')),
      'diagnosed', (select count(*) from pipeline.integration_issues i where (i.diagnosis->>'first_at')::timestamptz >= v_since),
      'remedies_executed', (select count(*) from pipeline.ops_remedy_runs u where u.started_at >= v_since and u.result not in ('refused_authority')),
      'remedies_verified', (select count(*) from pipeline.ops_remedy_runs u where u.result = 'verified' and (u.evidence->>'verified_at')::timestamptz >= v_since),
      'remedies_failed_verification', (select count(*) from pipeline.ops_remedy_runs u where u.result = 'verify_failed' and (u.evidence->>'verified_at')::timestamptz >= v_since),
      'closed_by_controller', (select count(*) from pipeline.integration_issues i where i.status = 'closed' and i.closed_at >= v_since and i.verified_by = 'ops-controller'),
      'reopened', (select count(*) from pipeline.integration_issue_events e where e.kind = 'reopened_regression' and e.at >= v_since),
      'needing_decisions', (select count(*) from pipeline.integration_issues i where i.status <> 'closed' and i.ops_state = 'needs_decision'),
      'needing_release', (select count(*) from pipeline.integration_issues i where i.status <> 'closed' and i.ops_state = 'needs_release'),
      'superseded_open', (select count(*) from pipeline.integration_issues i where i.status <> 'closed' and i.superseded_by is not null),
      'root_causes_open', (select coalesce(jsonb_object_agg(z.rc, z.n), '{}'::jsonb) from (select coalesce(i.diagnosis->>'root_cause', 'not diagnosed') rc, count(*) n
                            from pipeline.integration_issues i where i.status <> 'closed' group by 1) z),
      'scorecard', jsonb_build_object(
        'autonomous_resolution_pct', case when v_eligible > 0 then round(100.0 * v_resolved / v_eligible, 1) end,
        'autonomous_resolution_basis', jsonb_build_object('resolved_by_controller', v_resolved, 'eligible', v_eligible,
          'excluded_policy_evidence_approval', (select count(*) from pipeline.integration_issues i join pipeline.ops_root_causes c on c.code = i.diagnosis->>'root_cause'
                                                 where c.class = 'policy' and (i.status <> 'closed' or i.closed_at >= v_since)),
          'rule', 'eligible: issues open in the window whose diagnosed cause is not a policy, external-evidence or approval matter (those are reported separately); needs_release issues stay in the denominator'),
        'detection_to_diagnosis_minutes_median', (select round(percentile_cont(0.5) within group (order by extract(epoch from (i.diagnosis->>'first_at')::timestamptz - i.detected_at) / 60)::numeric, 1)
                                                   from pipeline.integration_issues i where (i.diagnosis->>'first_at')::timestamptz >= v_since),
        'diagnosis_to_resolution_minutes_median', (select round(percentile_cont(0.5) within group (order by extract(epoch from i.closed_at - (i.diagnosis->>'first_at')::timestamptz) / 60)::numeric, 1)
                                                    from pipeline.integration_issues i where i.status = 'closed' and i.closed_at >= v_since and i.verified_by = 'ops-controller'),
        'recurrence', jsonb_build_object('reopened_in_window', (select count(*) from pipeline.integration_issue_events e where e.kind = 'reopened_regression' and e.at >= v_since),
                                         'controller_closures_reopened', (select count(*) from pipeline.integration_issues i where i.regression_count > 0 and i.status <> 'closed'
                                                                           and exists (select 1 from pipeline.ops_remedy_runs u where u.issue_id = i.id and u.result = 'verified')))));
    v_out := v_out || jsonb_build_object('autonomy', v);
  exception when others then v_out := v_out || jsonb_build_object('autonomy', jsonb_build_object('error', left(sqlerrm, 200)));
  end;

  -- efficiency: paid work, AI, yield, avoided reads, cost per verified improvement
  begin
    v := jsonb_build_object(
      'firecrawl_credits', (select coalesce(sum(u.units), 0) from pipeline.coverage_vendor_usage u where u.at >= v_since),
      'ai_usd', (select round(coalesce(sum(a.cost_usd), 0), 2) from pipeline.ai_spend_ledger a where a.at >= v_since),
      'ai_calls', (select coalesce(sum(a.calls), 0) from pipeline.ai_spend_ledger a where a.at >= v_since),
      'paid_reads_refused_today', (select coalesce(sum(r.n), 0) from pipeline.firecrawl_budget_refusals r where r.day = (now() at time zone 'UTC')::date),
      'items_per_worker_call', (select round(coalesce(sum(l.items), 0)::numeric / nullif(count(*), 0), 2) from pipeline.mode_outcome_ledger l where l.run_at >= v_since),
      'zero_item_share_pct', (select round(100.0 * count(*) filter (where coalesce(l.items, 0) = 0) / nullif(count(*), 0), 1) from pipeline.mode_outcome_ledger l where l.run_at >= v_since));
    v := v || jsonb_build_object('usd_per_filled_value', case when coalesce(((v_out->'data_improvement'->>'courses_repaired')::int), 0) > 0
             then round((v->>'ai_usd')::numeric / (select sum((x.value->>'filled')::int) from jsonb_each(coalesce(v_out->'data_improvement'->'field_values', '{}'::jsonb)) x)::numeric, 4) end,
             'note', 'repeated paid reads and evidence-cache reuse come from workstream F (ops_cost_*) when released');
    v_out := v_out || jsonb_build_object('efficiency', v);
  exception when others then v_out := v_out || jsonb_build_object('efficiency', jsonb_build_object('error', left(sqlerrm, 200)));
  end;

  -- governance: releases, regressions, Layer 4, open policy blockers, consumer consistency
  begin
    v := jsonb_build_object(
      'releases', (select coalesce(jsonb_agg(jsonb_build_object('release', x.release, 'at', x.at, 'source', x.source) order by x.at), '[]'::jsonb) from security.ops_releases_v1() x where x.at >= v_since),
      'deploy_checks_failed', (select count(*) from pipeline.integration_deploy_checks d where d.checked_at >= v_since and not d.ok),
      'regressions_reopened', (select count(*) from pipeline.integration_issue_events e where e.kind = 'reopened_regression' and e.at >= v_since),
      'layer4', (select jsonb_build_object('pending', count(*) filter (where r.status = 'pending'),
                   'decided_in_window', count(*) filter (where r.decided_at >= v_since), 'approved_in_window', count(*) filter (where r.decided_at >= v_since and r.status in ('approved', 'edited_approved')))
                   from pipeline.layer4_review_items r where r.status = 'pending' or r.decided_at >= v_since),
      'open_policy_blockers', (select coalesce(jsonb_agg(jsonb_build_object('issue', i.issue_ref, 'title', left(i.title, 120), 'required', left(i.blocker->>'required', 300)) order by i.severity, i.id), '[]'::jsonb)
                                 from pipeline.integration_issues i where i.status <> 'closed' and i.ops_state = 'needs_decision'),
      'consumer_guard', (select jsonb_build_object('last_status', (array_agg(d.status order by d.runid desc))[1], 'last_at', max(d.start_time))
                           from cron.job_run_details d where d.runid > (select coalesce(max(y.runid), 0) from cron.job_run_details y) - v_scan
                            and d.jobid in (select j.jobid from cron.job j where j.jobname = 'consumer-api-guard')),
      'learning', case when to_regclass('pipeline.ai_instruction_versions') is not null then 'see workstream E (ai_instruction_versions)' else 'workstream E not released' end);
    v_out := v_out || jsonb_build_object('governance', v);
  exception when others then v_out := v_out || jsonb_build_object('governance', jsonb_build_object('error', left(sqlerrm, 200)));
  end;

  -- the historical cohort and the correlated groups
  begin
    v_x := security.ops_reconciliation_v1('p0-2026-11-03-detected-48');
    v_out := v_out || jsonb_build_object('reconciliation', jsonb_build_object('cohort', v_x->'cohort', 'by_end_state', v_x->'by_end_state',
               'issues', (select count(*) from pipeline.ops_baseline_cohort b where b.cohort = 'p0-2026-11-03-detected-48')),
             'groups', (select coalesce(jsonb_agg(g), '[]'::jsonb) from jsonb_array_elements(security.ops_correlation_groups_v1()) g where (g->>'open')::int > 1));
  exception when others then v_out := v_out || jsonb_build_object('reconciliation', jsonb_build_object('error', left(sqlerrm, 200)));
  end;
  -- work continuity (SS-021, mandate 3 Nov 2026 21:19 §9): lanes, blocked and parked work, recovery and authority (security.work_continuity_report_v1)
  begin
    v_out := v_out || jsonb_build_object('work_continuity', security.work_continuity_report_v1());
  exception when others then v_out := v_out || jsonb_build_object('work_continuity', jsonb_build_object('error', left(sqlerrm, 200)));
  end;
  -- human-assisted recovery (Platform Admin decision 4 Nov 2026 06:30 §9): interventions per workstream (security.layer4_intervention_report_v1)
  begin
    v_out := v_out || jsonb_build_object('human_assisted_recovery', security.layer4_intervention_report_v1());
  exception when others then v_out := v_out || jsonb_build_object('human_assisted_recovery', jsonb_build_object('error', left(sqlerrm, 200)));
  end;
  -- self-sustainability scorecard (Platform Admin mandate 4 Nov 2026 08:16 §10): the ten measures (security.self_sustainability_v1)
  begin
    v_out := v_out || jsonb_build_object('self_sustainability', security.self_sustainability_v1(p_window_hours));
  exception when others then v_out := v_out || jsonb_build_object('self_sustainability', jsonb_build_object('error', left(sqlerrm, 200)));
  end;
  return v_out;
end $$;


ALTER FUNCTION "security"."ops_report_v1"("p_window_hours" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ops_retry_cost_pause_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_c int := 0; r record;
begin
  if security.pipeline_num_v1('ops.retry_cost_pause_on', 0) < 1 then return jsonb_build_object('ok', true, 'changed', 0, 'evidence', 'switched off (ops.retry_cost_pause_on)'); end if;
  for r in select split_part(d.correlation_key, ':', 2)::uuid id, d.evidence from security.ops_lifecycle_detect_v1() d where d.root_cause = 'retry_cost_excess'
            limit greatest(1, security.pipeline_num_v1('ops.heal_batch', 200)::int) loop
    update pipeline.admin_jobs set pause_requested = true, updated_at = now() where id = r.id and state in ('queued', 'running') and not pause_requested;
    if found then
      insert into pipeline.admin_job_events(job_id, note, detail) values (r.id, 'asked to pause: items read again cost US$' || (r.evidence->>'usd') || ' (over ops.retry_cost_max_usd)', r.evidence);
      v_c := v_c + 1;
    end if;
  end loop;
  if v_c > 0 then perform security.ops_d_run_note_v1(p_issue, 'retry_cost_pause', null, null, v_c, null); end if;
  return jsonb_build_object('ok', true, 'changed', v_c, 'evidence', null);
end $_$;


ALTER FUNCTION "security"."ops_retry_cost_pause_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ops_retry_cost_verify_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('passed', n = 0, 'measure', jsonb_build_object('tasks_over', n), 'evidence', 'open tasks over the paid retry cost')
    from (select count(*) n from security.ops_lifecycle_detect_v1() d join pipeline.admin_jobs j on j.id = split_part(d.correlation_key, ':', 2)::uuid
           where d.root_cause = 'retry_cost_excess' and not j.pause_requested) z
$$;


ALTER FUNCTION "security"."ops_retry_cost_verify_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ops_root_cause_register_v1"("p_code" "text", "p_spec" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_new boolean;
begin
  if security.ops_remedy_guard_active_v1() then raise exception 'ops guard: a remedy cannot change the root-cause register' using errcode = '42501'; end if;
  if coalesce(p_code, '') !~ '^[a-z][a-z0-9_]*$' then raise exception 'a root cause code is lower case letters, digits and underscores' using errcode = '22023'; end if;
  if p_spec is null or jsonb_typeof(p_spec) <> 'object' or coalesce(p_spec->>'class', '') not in ('transient', 'data', 'rule', 'policy', 'dependency', 'capacity') then
    raise exception 'root cause %: class must be transient, data, rule, policy, dependency or capacity', p_code using errcode = '22023';
  end if;
  if length(btrim(coalesce(p_spec->>'title', ''))) < 3 then raise exception 'root cause %: give it a title', p_code using errcode = '22023'; end if;
  if p_spec ? 'detect' and jsonb_typeof(p_spec->'detect') <> 'object' then raise exception 'root cause %: detect is an object', p_code using errcode = '22023'; end if;
  v_new := not exists (select 1 from pipeline.ops_root_causes where code = p_code);
  insert into pipeline.ops_root_causes as r(code, class, title, description, detect)
  values (p_code, p_spec->>'class', btrim(p_spec->>'title'), p_spec->>'description', coalesce(p_spec->'detect', '{}'::jsonb))
  on conflict (code) do update set class = excluded.class, title = excluded.title, description = excluded.description, detect = excluded.detect;
  return jsonb_build_object('code', p_code, 'action', case when v_new then 'created' else 'replaced' end);
end $_$;


ALTER FUNCTION "security"."ops_root_cause_register_v1"("p_code" "text", "p_spec" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ops_route_v1"("p_issue" bigint, "p_diag" "jsonb", "p_reason" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.integration_issues; rc pipeline.ops_root_causes; m pipeline.ops_remedies; v_state text; v_blocker jsonb;
begin
  select * into r from pipeline.integration_issues where id = p_issue;
  select * into rc from pipeline.ops_root_causes where code = p_diag->>'root_cause';
  select x.* into m from pipeline.ops_remedies x where x.active and x.authority in ('admin', 'release') and rc.code = any (x.treats)
   order by case x.authority when 'admin' then 0 else 1 end, x.code limit 1;
  v_state := coalesce(case when p_reason like 'attempts used up%' then 'needs_release' end,
                      (select a.route_state from pipeline.ops_authority_matrix a where a.authority = m.authority), rc.detect->>'route',
                      case when rc.class = 'policy' then 'needs_decision' else 'needs_release' end);
  v_blocker := jsonb_build_object('kind', case v_state when 'needs_decision' then 'decision' else 'release' end,
    'required', coalesce(m.title, 'A change through the release gates') || ': ' || coalesce(rc.description, rc.title),
    'root_cause', rc.code, 'reason', p_reason, 'recommended', rc.detect->>'recommend', 'issue_statement', left(r.failure, 500), 'expected', left(r.expected, 300),
    'impact', jsonb_build_object('severity', r.severity, 'providers', cardinality(r.provider_ids), 'courses', cardinality(r.course_ids), 'layer', r.layer),
    'evidence', p_diag->'evidence', 'owner_workstream', r.workstream, 'at', now());
  if r.ops_state is distinct from v_state or r.blocker->>'root_cause' is distinct from rc.code then
    update pipeline.integration_issues set ops_state = v_state, remedy_code = m.code, blocker = v_blocker, updated_at = now() where id = p_issue;
    insert into pipeline.integration_issue_events(issue_id, kind, from_status, to_status, actor, note, detail)
    values (p_issue, 'updated', r.status, r.status, 'ops-controller',
            case v_state when 'needs_decision' then 'Blocked: needs a Platform Admin decision. ' else 'Blocked: needs a release. ' end || left(v_blocker->>'required', 400),
            jsonb_build_object('ops_state', v_state, 'blocker', v_blocker));
  end if;
  return v_state;
end $$;


ALTER FUNCTION "security"."ops_route_v1"("p_issue" bigint, "p_diag" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ops_scorecard_record_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_cur date := date_trunc('week', (now() at time zone 'Australia/Melbourne'))::date; v jsonb; v_old jsonb; v_out jsonb := '[]'::jsonb; w date;
begin
  -- the current week every day (so each day's job runs are kept while the scheduler still has them), and the last week once more after it ends
  foreach w in array array[v_cur - 7, v_cur] loop  -- fixed: Monday-to-Sunday weeks
    v_old := null;
    select s.scorecard into v_old from pipeline.ops_scorecards s where s.week_start = w;
    continue when w < v_cur and coalesce((v_old ->> 'complete')::boolean, false);  -- a finished week is recorded once after it ends, then kept
    v := security.ops_scorecard_v1(w, v_old);
    v := v || jsonb_build_object('aer', security.aer_weekly_section_v1(w));  -- CF-247 AER Phase B (mandate §14 weekly)
    insert into pipeline.ops_scorecards(week_start, week_end, generated_at, generated_by, scorecard)
    values (w, w + 6, now(), 'job ops-scorecard', v)
    on conflict (week_start) do update set generated_at = excluded.generated_at, generated_by = excluded.generated_by, scorecard = excluded.scorecard;
    v_out := v_out || jsonb_build_object('week_start', w, 'complete', v -> 'complete', 'met', v -> 'met', 'missed', v -> 'missed');
  end loop;
  return v_out;
end $$;


ALTER FUNCTION "security"."ops_scorecard_record_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ops_scorecard_v1"("p_week_start" "date" DEFAULT NULL::"date", "p_prior" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "statement_timeout" TO '120s'
    AS $_$
declare
  v_tz text := 'Australia/Melbourne';  -- fixed: the platform's reporting time zone
  v_ws_d date := coalesce(p_week_start, date_trunc('week', (now() at time zone 'Australia/Melbourne'))::date);
  v_ws timestamptz; v_we timestamptz; v_end timestamptz; v_complete boolean; v_days numeric;
  t1 jsonb; t2 jsonb; t3 jsonb; t4 jsonb; t5 jsonb; t6 jsonb; t7 jsonb; t8 jsonb; v_thr jsonb; v_idq jsonb; v_inc jsonb;
  v_n bigint; v_n2 bigint; v_n3 bigint; v_num numeric; v_num2 numeric; v_num3 numeric; v_x jsonb; v_ts timestamptz; v_first timestamptz;
  v_txt8 text; v_jobs jsonb; v_cov int; v_elapsed int; v_runs bigint; v_failed bigint; v_worst bigint;
begin
  v_ws := (v_ws_d::timestamp at time zone v_tz);
  v_we := ((v_ws_d + 7)::timestamp at time zone v_tz);
  v_end := least(v_we, now()); v_complete := v_we <= now();
  v_days := greatest(extract(epoch from v_end - v_ws) / 86400.0, 0.0001);

  -- T1: failed runs of active scheduled jobs, by day. The scheduler keeps about three days of run history, so the daily record keeps each
  -- day once it is fully in the log (p_prior: this week's stored scorecard) and a later run only adds or completes days.
  select min(d.start_time) into v_first from cron.job_run_details d;
  with r as (select (d.start_time at time zone v_tz)::date dy, case when d.status='failed' and d.return_message='job canceled' then security.cron_run_outcome_v1(j.jobname, d.status, d.return_message, d.start_time) else d.status end status, j.jobname from cron.job_run_details d join cron.job j on j.jobid = d.jobid
              where j.active and d.start_time >= v_ws and d.start_time < v_end)
  select coalesce(jsonb_object_agg(x.dy, jsonb_build_object('runs', x.runs, 'failed', x.failed) order by x.dy), '{}'::jsonb),
         coalesce((select jsonb_agg(jsonb_build_object('job', y.jobname, 'failed', y.n) order by y.n desc) from
                    (select r.jobname, count(*) n from r where r.status = 'failed' group by r.jobname order by count(*) desc limit 5) y), '[]'::jsonb)
    into v_x, v_jobs
    from (select r.dy, count(*) runs, count(*) filter (where r.status = 'failed') failed from r where r.dy > (v_first at time zone v_tz)::date group by r.dy) x;
  v_x := coalesce(p_prior -> 'targets' -> 'T1' -> 'by_day', '{}'::jsonb) || v_x;
  select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb), coalesce(sum((e.value ->> 'runs')::bigint), 0), coalesce(sum((e.value ->> 'failed')::bigint), 0),
         coalesce(max((e.value ->> 'failed')::bigint), 0), count(*)
    into v_x, v_runs, v_failed, v_worst, v_cov
    from jsonb_each(v_x) e where e.key::date >= v_ws_d and e.key::date < v_ws_d + 7;  -- fixed: a week is seven days
  v_elapsed := least(7, ((v_end at time zone v_tz)::date - v_ws_d) + 1);  -- fixed: a week is seven days
  t1 := jsonb_build_object('runs', v_runs, 'failed', v_failed, 'worst_day', v_worst, 'by_day', v_x, 'days_recorded', v_cov, 'failing_jobs_in_log', v_jobs,
        'target', 'At most ' || security.pipeline_num_v1('targets.job_failures_per_day', 0) || ' failed run(s) a day',
        'status', case when v_worst > security.pipeline_num_v1('targets.job_failures_per_day', 0) then 'missed' when v_cov < v_elapsed then 'not fully observed'
                       when not v_complete then 'on track so far' else 'met' end,
        'basis', case when v_cov < v_elapsed then 'incomplete: ' || v_cov || ' of ' || v_elapsed || ' days recorded (the scheduler keeps about three days of run history; the scorecard now records each day)'
                      when v_complete then 'observed for the whole week' else 'observed so far (week in progress)' end);

  -- T2: AI spend from the OpenRouter credit balance (every decrease; a top-up is not spend), and the credit
  with o as (select x.observed_at, x.remaining_usd, lag(x.remaining_usd) over (order by x.observed_at) prev from pipeline.layer3_openrouter_observations x
              where x.kind = 'credits' and x.remaining_usd is not null and x.observed_at >= v_ws - interval '1 hour' and x.observed_at < v_end),  -- fixed: one observation before the week for the first difference
       dd as (select (o.observed_at at time zone v_tz)::date dy, sum(greatest(coalesce(o.prev, o.remaining_usd) - o.remaining_usd, 0)) spend, count(*) obs from o where o.observed_at >= v_ws group by 1)
  select jsonb_build_object('spend_usd', round(coalesce(sum(spend), 0), 2), 'worst_day_usd', round(coalesce(max(spend), 0), 2),
           'spend_by_day', coalesce(jsonb_object_agg(dy, round(spend, 2) order by dy), '{}'::jsonb), 'observations', coalesce(sum(obs), 0),
           'expected_observations', round(v_days * 96))  -- fixed: the openrouter-balance job records every 15 minutes
    into t2 from dd;
  select o.remaining_usd into v_num from pipeline.layer3_openrouter_observations o where o.kind = 'credits' and o.remaining_usd is not null and o.observed_at < v_end order by o.observed_at desc limit 1;
  t2 := t2 || jsonb_build_object('credit_usd', v_num, 'ceiling_usd', security.pipeline_num_v1('budgets.ai_daily_ceiling_usd', 14), 'credit_floor_usd', security.pipeline_num_v1('targets.ai_credit_min_usd', 10),
        'target', 'At most US$' || security.pipeline_num_v1('budgets.ai_daily_ceiling_usd', 14) || ' a day; credit US$' || security.pipeline_num_v1('targets.ai_credit_min_usd', 10) || ' or more',
        'status', case when (t2->>'worst_day_usd')::numeric > security.pipeline_num_v1('budgets.ai_daily_ceiling_usd', 14) or coalesce(v_num, 0) < security.pipeline_num_v1('targets.ai_credit_min_usd', 10) then 'missed'
                       when not v_complete then 'on track so far' else 'met' end,
        'basis', case when (t2->>'observations')::numeric < 0.8 * (t2->>'expected_observations')::numeric then 'incomplete: ' || (t2->>'observations') || ' of about ' || (t2->>'expected_observations') || ' balance readings'
                      when v_complete then 'observed for the whole week' else 'observed so far (week in progress)' end);  -- fixed: 80% of readings counts as complete

  -- T3: Firecrawl
  select coalesce(sum(u.units), 0) into v_num from pipeline.coverage_vendor_usage u where u.at >= v_ws and u.at < v_end;
  select security.layer2_provider_budget_status(p.id, 0) into v_x from pipeline.layer2_acquisition_providers p where p.provider_key = 'firecrawl';
  t3 := jsonb_build_object('credits_week', v_num, 'month_used', v_x->'used_units', 'month_limit', v_x->'limit_units', 'reserve', v_x->'stop_at_remaining_units',
        'target', 'Within the monthly limit, keeping the reserve',
        'status', case when v_x is null then 'not measurable' when coalesce((v_x->>'used_units')::numeric, 0) > coalesce((v_x->>'limit_units')::numeric, 0) - coalesce((v_x->>'stop_at_remaining_units')::numeric, 0) then 'missed' else 'met' end,
        'basis', 'week credits observed; month position measured at report time');

  -- T4: futile enrichment items (the course page found is for another course)
  with f as (select (i.created_at at time zone v_tz)::date dy, count(*) n from pipeline.field_enrich_items i
              where i.created_at >= v_ws and i.created_at < v_end and i.state = 'skipped' and i.reason like 'no correct course page%' group by 1)
  select jsonb_build_object('items', coalesce(sum(n), 0), 'worst_day', coalesce(max(n), 0), 'by_day', coalesce(jsonb_object_agg(dy, n order by dy), '{}'::jsonb)) into t4 from f;
  t4 := t4 || jsonb_build_object('target', 'Under ' || security.pipeline_num_v1('targets.futile_items_per_day', 100) || ' a day',
        'status', case when (t4->>'worst_day')::int >= security.pipeline_num_v1('targets.futile_items_per_day', 100) then 'missed' when not v_complete then 'on track so far' else 'met' end,
        'basis', case when v_complete then 'observed for the whole week' else 'observed so far (week in progress)' end);

  -- T5: Layer 4 review backlog (only the current position is stored)
  select count(*) filter (where r.status = 'pending'), min(r.created_at) filter (where r.status = 'pending'),
         count(*) filter (where r.created_at >= v_ws and r.created_at < v_end), count(*) filter (where r.decided_at >= v_ws and r.decided_at < v_end)
    into v_n, v_ts, v_n2, v_n3 from pipeline.layer4_review_items r;
  v_num := round(extract(epoch from now() - v_ts) / 86400.0, 1);
  t5 := jsonb_build_object('pending_now', v_n, 'oldest_pending_days', v_num, 'oldest_pending_since', v_ts, 'created_week', v_n2, 'decided_week', v_n3,
        'target', 'Oldest pending item under ' || security.pipeline_num_v1('targets.review_oldest_days', 14) || ' days',
        'status', case when v_n = 0 or v_num < security.pipeline_num_v1('targets.review_oldest_days', 14) then 'met' else 'missed' end,
        'basis', 'measured at report time (the backlog age is not stored by day)');

  -- T6: consumer API (website and Zoho requests, contract drift)
  select count(*), count(*) filter (where a.status >= 500), count(*) filter (where a.action = 'search' and coalesce(a.items, 0) <= security.pipeline_num_v1('targets.api_search_page_size', 20)),
         percentile_cont(0.5) within group (order by a.elapsed_ms) filter (where a.action = 'search' and coalesce(a.items, 0) <= security.pipeline_num_v1('targets.api_search_page_size', 20)),
         percentile_cont(0.95) within group (order by a.elapsed_ms) filter (where a.action = 'search' and coalesce(a.items, 0) <= security.pipeline_num_v1('targets.api_search_page_size', 20)),
         percentile_cont(0.95) within group (order by a.elapsed_ms) filter (where a.action = 'search')
    into v_n, v_n2, v_n3, v_num, v_num2, v_num3 from pipeline.api_requests a where a.at >= v_ws and a.at < v_end;
  v_x := security.consumer_api_check_v1();
  t6 := jsonb_build_object('requests', v_n, 'server_errors', v_n2, 'search_requests_measured', v_n3, 'search_p50_ms', round(v_num), 'search_p95_ms', round(v_num2), 'search_p95_ms_all_sizes', round(v_num3),
        'by_platform', coalesce((select jsonb_object_agg(x.platform, x.n) from (select a.platform, count(*) n from pipeline.api_requests a where a.at >= v_ws and a.at < v_end group by 1) x), '{}'::jsonb),
        'contract_drift_now', jsonb_array_length(coalesce(v_x->'drift', '[]'::jsonb)),
        'guard_runs_failed', (select count(*) from cron.job_run_details d join cron.job j on j.jobid = d.jobid where j.jobname = 'consumer-api-guard' and d.start_time >= v_ws and d.start_time < v_end and d.status = 'failed'),
        'target', '0 server errors; no contract drift; search p95 under ' || security.pipeline_num_v1('targets.api_search_p95_ms', 3000) || ' ms for pages of ' || security.pipeline_num_v1('targets.api_search_page_size', 20),
        'status', case when v_n2 > 0 or jsonb_array_length(coalesce(v_x->'drift', '[]'::jsonb)) > 0 then 'missed'
                       when v_n3 = 0 then 'no search traffic: latency not measurable'
                       when v_num2 > security.pipeline_num_v1('targets.api_search_p95_ms', 3000) then 'missed' when not v_complete then 'on track so far' else 'met' end,
        'basis', case when v_n3 = 0 then 'errors and drift observed; no measured search requests in the window' when v_complete then 'observed for the whole week' else 'observed so far (week in progress)' end);

  -- T7: data freshness (search refresh requests; reference bundle)
  select count(*), count(*) filter (where q.processed_at is null), percentile_cont(0.5) within group (order by extract(epoch from coalesce(q.processed_at, now()) - q.requested_at) / 60),
         percentile_cont(0.95) within group (order by extract(epoch from coalesce(q.processed_at, now()) - q.requested_at) / 60), max(extract(epoch from coalesce(q.processed_at, now()) - q.requested_at) / 60),
         count(*) filter (where extract(epoch from coalesce(q.processed_at, now()) - q.requested_at) / 60 > security.pipeline_num_v1('health.search_refresh_slow_minutes', 40))
    into v_n, v_n2, v_num, v_num2, v_num3, v_n3 from search.refresh_requests q where q.requested_at >= v_ws and q.requested_at < v_end;
  select max(b.built_at) into v_ts from pipeline.consumer_reference_bundle_cache b;
  t7 := jsonb_build_object('refresh_requests', v_n, 'open', v_n2, 'wait_p50_min', round(v_num, 1), 'wait_p95_min', round(v_num2, 1), 'wait_max_min', round(v_num3, 1), 'over_target', v_n3,
        'bundle_age_hours_now', round(extract(epoch from now() - v_ts) / 3600.0, 2),
        'bundle_stale_issues', (select count(*) from pipeline.platform_issues p where p.check_key = 'reference_bundle:stale' and p.first_seen >= v_ws and p.first_seen < v_end),
        'target', 'Refresh requests processed within ' || security.pipeline_num_v1('health.search_refresh_slow_minutes', 40) || ' minutes; reference bundle under ' || security.pipeline_num_v1('targets.reference_bundle_hours', 2) || ' hours old',
        'status', case when v_n3 > 0 or (select count(*) from pipeline.platform_issues p where p.check_key = 'reference_bundle:stale' and p.first_seen >= v_ws and p.first_seen < v_end) > 0
                         or extract(epoch from now() - v_ts) / 3600.0 > security.pipeline_num_v1('targets.reference_bundle_hours', 2) then 'missed'
                       when not v_complete then 'on track so far' else 'met' end,
        'basis', case when v_complete then 'observed for the whole week' else 'observed so far (week in progress)' end);

  -- T8: releases (the database holds the migrations and contract re-baselines; suite and workflow results are on the release record)
  select count(*), max(m.version || ' ' || m.name) into v_n, v_txt8 from supabase_migrations.schema_migrations m
   where m.version >= to_char(v_ws at time zone v_tz, 'YYYYMMDD') and m.version < to_char(v_we at time zone v_tz, 'YYYYMMDD');
  t8 := jsonb_build_object('migrations_dated_in_week', v_n, 'latest_migration', v_txt8,
        'target', 'Full suite and post-merge workflows green; live checksums verified; rollback on record',
        'status', 'see the release record', 'basis', 'migrations dated in the week; suite, workflow and checksum results are recorded in the Admin release record, not in the database');

  -- report areas without a target: throughput, page identity and evidence, incidents and recovery
  v_thr := jsonb_build_object(
    'enrich_values_filled', (select count(*) from pipeline.field_enrich_items i where i.state = 'filled' and i.updated_at >= v_ws and i.updated_at < v_end),
    'enrich_values_to_review', (select count(*) from pipeline.field_enrich_items i where i.state = 'review' and i.updated_at >= v_ws and i.updated_at < v_end),
    'layer4_decided', t5->'decided_week', 'search_refreshes_processed', (select count(*) from search.refresh_requests q where q.processed_at >= v_ws and q.processed_at < v_end),
    'enrich_ai_cost_usd', (select round(coalesce(sum(i.cost_usd), 0), 2) from pipeline.field_enrich_items i where i.updated_at >= v_ws and i.updated_at < v_end));
  v_idq := jsonb_build_object(
    'course_pages_now', coalesce((select jsonb_object_agg(x.status, x.n) from (select p.status, count(*) n from pipeline.coverage_course_pages p group by 1) x), '{}'::jsonb),
    'remediation_holds_open', (select count(*) from pipeline.course_remediation_holds h where h.lifted_at is null),
    'futile_items_week', t4->'items');
  v_inc := jsonb_build_object(
    'critical_opened', (select count(*) from pipeline.platform_issues p where p.severity = 'critical' and p.first_seen >= v_ws and p.first_seen < v_end),
    'warning_opened', (select count(*) from pipeline.platform_issues p where p.severity = 'warning' and p.first_seen >= v_ws and p.first_seen < v_end),
    'critical_by_check', coalesce((select jsonb_object_agg(x.k, x.n) from (select split_part(p.check_key, ':', 1) || ':' || split_part(p.check_key, ':', 2) k, count(*) n from pipeline.platform_issues p
                                    where p.severity = 'critical' and p.first_seen >= v_ws and p.first_seen < v_end group by 1 order by 2 desc limit 8) x), '{}'::jsonb),
    'critical_minutes_to_close_median', (select round(percentile_cont(0.5) within group (order by extract(epoch from p.resolved_at - p.first_seen) / 60)) from pipeline.platform_issues p
                                          where p.severity = 'critical' and p.first_seen >= v_ws and p.first_seen < v_end and p.resolved_at is not null),
    'critical_open_now', (select count(*) from pipeline.platform_issues p where p.severity = 'critical' and p.resolved_at is null),
    'unacknowledged_open_now', (select count(*) from pipeline.platform_issues p where p.severity in ('critical', 'warning') and p.resolved_at is null and p.acknowledged_at is null),
    'alerts', coalesce((select jsonb_object_agg(x.k, x.n) from (select a.kind || ':' || a.status k, count(*) n from pipeline.platform_alerts a where a.created_at >= v_ws and a.created_at < v_end group by 1) x), '{}'::jsonb),
    'health_run_ms_median', (select round(percentile_cont(0.5) within group (order by h.duration_ms)) from pipeline.platform_health_runs h where h.started_at >= v_ws and h.started_at < v_end));

  return jsonb_build_object('week_start', v_ws_d, 'week_end', v_ws_d + 6, 'complete', v_complete, 'generated_at', now(),
    'targets', jsonb_build_object('T1', t1, 'T2', t2, 'T3', t3, 'T4', t4, 'T5', t5, 'T6', t6, 'T7', t7, 'T8', t8),
    'met', (select count(*) from jsonb_each(jsonb_build_object('T1', t1, 'T2', t2, 'T3', t3, 'T4', t4, 'T5', t5, 'T6', t6, 'T7', t7)) e where e.value->>'status' = 'met'),
    'missed', (select count(*) from jsonb_each(jsonb_build_object('T1', t1, 'T2', t2, 'T3', t3, 'T4', t4, 'T5', t5, 'T6', t6, 'T7', t7)) e where e.value->>'status' = 'missed'),
    'areas', jsonb_build_object('1_job_reliability', 'T1', '2_throughput', v_thr, '3_page_identity_and_evidence', v_idq, '4_review_backlog', 'T5',
                                '5_api_performance', 'T6', '6_ai_and_firecrawl', 'T2, T3', '7_freshness', 'T7', '8_incidents_and_recovery', v_inc));
end $_$;


ALTER FUNCTION "security"."ops_scorecard_v1"("p_week_start" "date", "p_prior" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ops_step_value_v1"("p_provider" "uuid", "p_step" "text", "p_scope" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_days int := security.pipeline_num_v1('ops_cost.history_days', 30)::int; v_since timestamptz;
        v_min int := security.pipeline_num_v1('ops_cost.min_sample', 20)::int;
        v_price numeric := security.pipeline_num_v1('ops_cost.fc_usd_per_credit', 0);
        v_fields text[]; v_courses uuid[];
        v_elig numeric := 0; v_evid numeric := 0; v_rate numeric; v_rate_basis text; v_n bigint; v_ok bigint;
        v_lane text; v_usd_call numeric := 0; v_calls numeric := 0; v_credits numeric := 0; v_ai numeric; v_usd numeric;
        v_prog jsonb; v_retry jsonb; v_exp numeric; v_like text; v_skip text; v_extra jsonb := '{}'::jsonb; v_uc jsonb;
begin
  v_since := now() - make_interval(days => v_days);
  v_fields := array(select jsonb_array_elements_text(coalesce(p_scope->'fields', '[]'::jsonb)));
  v_courses := array(select (jsonb_array_elements_text(coalesce(p_scope->'course_ids', '[]'::jsonb)))::uuid);
  v_uc := security.enrich_unit_costs_v1();  -- the plan builder's own measured credits per unit (30 days)
  if p_step not in ('pages', 'fields', 'scholarships', 'site', 'adapter') then
    raise exception 'ops_step_value_v1: unknown step % (pages, fields, scholarships, site, adapter)', p_step using errcode = '22023';
  end if;

  if p_step = 'pages' then
    v_lane := 'course_match';
    -- eligible: active courses with no bound course page and no search in flight or found
    select count(*) into v_elig from catalogue.courses c
     where c.provider_id = p_provider and c.lifecycle_status = 'active' and (cardinality(v_courses) = 0 or c.id = any (v_courses))
       and not exists (select 1 from pipeline.coverage_course_pages p where p.course_id = c.id and p.status = 'bound')
       and not exists (select 1 from pipeline.course_link_search s where s.course_id = c.id and s.state in ('queued', 'found', 'verified'));
    -- evidence held: a proven page already stored for those courses (no search needed)
    select count(distinct pp.course_id) into v_evid from pipeline.course_page_proofs pp join catalogue.courses c on c.id = pp.course_id
     where c.provider_id = p_provider and pp.proven and c.lifecycle_status = 'active' and (cardinality(v_courses) = 0 or c.id = any (v_courses))
       and not exists (select 1 from pipeline.coverage_course_pages p where p.course_id = c.id and p.status = 'bound');
    -- measured yield: searches settled in the window that found (and verified) a page, the provider's own when it has enough
    select count(*), count(*) filter (where s.state in ('found', 'verified')) into v_n, v_ok from pipeline.course_link_search s
     where s.provider_id = p_provider and s.done_at > v_since and s.state in ('none', 'found', 'verified');
    v_rate_basis := 'provider';
    if v_n < v_min then
      select count(*), count(*) filter (where s.state in ('found', 'verified')) into v_n, v_ok from pipeline.course_link_search s
       where s.done_at > v_since and s.state in ('none', 'found', 'verified');
      v_rate_basis := 'platform';
    end if;
    v_extra := jsonb_build_object('verified_rate', (select round(count(*) filter (where s.state = 'verified')::numeric / nullif(count(*), 0), 4) from pipeline.course_link_search s
                                                     where (v_rate_basis = 'platform' or s.provider_id = p_provider) and s.done_at > v_since and s.state in ('none', 'found', 'verified')));
    v_credits := greatest(v_elig - v_evid, 0) * coalesce((v_uc->>'search_credits_per_course')::numeric, 0);
    v_calls := 0;  -- AI page matching runs only for courses a search leaves unmatched; counted in its own lane
  elsif p_step = 'fields' then
    v_lane := 'enrich_fields';
    -- eligible: missing values a reader can still fill (page_found: a stored page not yet read for it; site_known: a page must be read first)
    select count(*) into v_elig from pipeline.course_attribute_coverage a join catalogue.courses c on c.id = a.course_id
     where a.provider_id = p_provider and c.lifecycle_status = 'active' and a.state in ('page_found', 'site_known')
       and (cardinality(v_fields) = 0 or a.attribute = any (v_fields)) and (cardinality(v_courses) = 0 or a.course_id = any (v_courses))
       and not security.enrich_item_held_v1(a.course_id, a.attribute);
    select count(*) into v_evid from pipeline.course_attribute_coverage a join catalogue.courses c on c.id = a.course_id
     where a.provider_id = p_provider and c.lifecycle_status = 'active' and a.state = 'page_found'
       and (cardinality(v_fields) = 0 or a.attribute = any (v_fields)) and (cardinality(v_courses) = 0 or a.course_id = any (v_courses))
       and not security.enrich_item_held_v1(a.course_id, a.attribute);
    select count(*), count(*) filter (where i.state = 'filled') into v_n, v_ok from pipeline.field_enrich_items i
     where i.provider_id = p_provider and i.updated_at > v_since and i.state in ('filled', 'skipped', 'review', 'failed') and (cardinality(v_fields) = 0 or i.field = any (v_fields));
    v_rate_basis := 'provider';
    if v_n < v_min then
      select count(*), count(*) filter (where i.state = 'filled') into v_n, v_ok from pipeline.field_enrich_items i
       where i.updated_at > v_since and i.state in ('filled', 'skipped', 'review', 'failed') and (cardinality(v_fields) = 0 or i.field = any (v_fields));
      v_rate_basis := 'platform';
    end if;
    v_calls := v_elig;
    -- a value whose page is not stored needs a page read first (one credit a page)
    v_credits := greatest(v_elig - v_evid, 0);
  elsif p_step = 'scholarships' then
    v_lane := 'scholarship_ai';
    select count(*) into v_elig from pipeline.scholarship_page_candidates c
     where c.provider_id = p_provider and c.admitted_at is null and c.admit_status is null and (c.next_read_at is null or c.next_read_at <= now());
    select count(*) into v_evid from pipeline.scholarship_page_candidates c
     where c.provider_id = p_provider and c.admitted_at is null and c.admit_status is null and c.storage_path is not null;
    select count(*), count(*) filter (where c.admitted_at is not null) into v_n, v_ok from pipeline.scholarship_page_candidates c
     where c.provider_id = p_provider and c.read_at > v_since;
    v_rate_basis := 'provider';
    if v_n < v_min then
      select count(*), count(*) filter (where c.admitted_at is not null) into v_n, v_ok from pipeline.scholarship_page_candidates c where c.read_at > v_since;
      v_rate_basis := 'platform';
    end if;
    v_calls := v_elig;
    v_credits := case when exists (select 1 from pipeline.scholarship_discovery_providers d where d.provider_id = p_provider and (d.next_discover_at is null or d.next_discover_at <= now()))
                      then coalesce((v_uc->>'scholarship_credits')::numeric, 0) else greatest(v_elig - v_evid, 0) end;
    v_extra := jsonb_build_object('eligible_for_scholarship_spend', security.fc_sch_eligible_v1(p_provider));
  else
    -- site (map the provider site) and adapter (build a course adapter): one provider-level unit; recovery is the courses still missing a page
    v_lane := case p_step when 'adapter' then 'adapter_builder' else null end;
    select count(*) into v_elig from catalogue.courses c where c.provider_id = p_provider and c.lifecycle_status = 'active'
       and not exists (select 1 from pipeline.coverage_course_pages p where p.course_id = c.id and p.status = 'bound');
    select count(*), count(*) filter (where s->>'status' = 'done') into v_n, v_ok
      from pipeline.enrich_plan_runs r, jsonb_array_elements(r.steps) s
     where r.created_at > v_since and s->>'step' = p_step and s->>'status' in ('done', 'failed', 'stopped')
       and r.provider_id = p_provider;
    v_rate_basis := 'provider';
    if v_n < 1 then
      select count(*), count(*) filter (where s->>'status' = 'done') into v_n, v_ok
        from pipeline.enrich_plan_runs r, jsonb_array_elements(r.steps) s
       where r.created_at > v_since and s->>'step' = p_step and s->>'status' in ('done', 'failed', 'stopped');
      v_rate_basis := 'platform (steps that ended done)';
    end if;
    v_calls := case when p_step = 'adapter' then 1 else 0 end;
    v_credits := coalesce((v_uc->>case p_step when 'adapter' then 'adapter_credits' else 'site_credits' end)::numeric, 0);
    v_evid := (select count(*) from pipeline.coverage_provider_urls u where u.provider_id = p_provider);
  end if;

  v_rate := case when v_n > 0 then round(v_ok::numeric / v_n, 4) else 0 end;
  -- AI US$ per call for the lane, from the ledger (opening rows carry no calls)
  if v_lane is not null then
    select coalesce(sum(l.cost_usd) / nullif(sum(l.calls), 0), 0) into v_usd_call from pipeline.ai_spend_ledger l
     where l.lane = v_lane and l.at > v_since and l.source <> 'opening';
  end if;
  v_ai := round(v_calls * v_usd_call, 4);
  v_usd := v_ai + v_credits * v_price;
  -- expected recovery: eligible records times the measured success rate of the step (for site and adapter, the courses still without a page)
  v_exp := round(v_elig * v_rate, 1);
  -- work already in progress
  select jsonb_build_object(
    'tasks', (select count(*) from pipeline.admin_jobs j where j.state in ('queued', 'running', 'paused') and j.args->>'provider_id' = p_provider::text),
    'plan_step_running', exists (select 1 from pipeline.enrich_plan_runs r, jsonb_array_elements(r.steps) s where r.provider_id = p_provider and r.state in ('queued', 'running')
                                  and s->>'step' = p_step and s->>'status' = 'running'),
    'items_in_flight', case p_step when 'fields' then (select count(*) from pipeline.field_enrich_items i where i.provider_id = p_provider and i.state in ('queued', 'waiting', 'ai', 'leased'))
                                   when 'pages' then (select count(*) from pipeline.course_link_search s where s.provider_id = p_provider and s.state = 'queued')
                                   when 'scholarships' then (select count(*) from pipeline.scholarship_ai_queue q where q.provider_id = p_provider and q.state not in ('done', 'failed'))
                                   else 0 end) into v_prog;
  -- retry spend and the previous failure for this provider and step
  select jsonb_build_object('previous_attempts', count(*), 'failed', count(*) filter (where s->>'status' in ('failed', 'stopped')),
                            'last_failure', (array_agg(coalesce(s->>'note', s#>>'{held,reason}', s#>>'{blocked,reason}', s->>'status') order by r.created_at desc)
                                              filter (where s->>'status' in ('failed', 'stopped')))[1],
                            -- what the runs in which this step failed spent (plan runs record actual spend per run, estimates per step)
                            'spent_usd', coalesce(sum((r.actual->>'usd')::numeric) filter (where s->>'status' in ('failed', 'stopped')), 0),
                            'spent_credits', coalesce(sum((r.actual->>'credits')::numeric) filter (where s->>'status' in ('failed', 'stopped')), 0),
                            'estimated_usd_of_failed_steps', coalesce(sum((s->>'est_usd')::numeric) filter (where s->>'status' in ('failed', 'stopped')), 0))
    into v_retry from pipeline.enrich_plan_runs r, jsonb_array_elements(r.steps) s
   where r.provider_id = p_provider and s->>'step' = p_step and r.created_at > v_since;
  v_like := case when v_elig = 0 then 'none' when v_rate * 100 >= security.pipeline_num_v1('ops_cost.likely_high_pct', 50) then 'high' when v_rate * 100 >= security.pipeline_num_v1('waste.retry_min_yield_pct', 15) then 'medium' else 'low' end;
  v_skip := case when v_elig = 0 then 'no eligible records'
                 when (v_prog->>'plan_step_running')::boolean then 'the same step is already running'
                 when v_exp < 1 then 'expected recovery under one record'
                 when exists (select 1 from pipeline.ops_cost_breakers b where b.code = 'cost_ineligible_scan' and b.scope_kind = 'provider' and b.scope_key = p_provider::text and b.state = 'tripped')
                   then 'the provider''s ineligible-spend breaker is tripped' end;
  return jsonb_build_object(
    'provider_id', p_provider, 'step', p_step, 'scope', p_scope, 'history_days', v_days,
    'expected_eligible', v_elig,
    'expected_recovery', jsonb_build_object('records', v_exp, 'rate', v_rate, 'basis', v_rate_basis, 'sample', v_n, 'succeeded', v_ok) || v_extra,
    'evidence_available', v_evid,
    'estimated_cost', jsonb_build_object('ai_usd', v_ai, 'ai_calls', v_calls, 'ai_usd_per_call', round(v_usd_call, 6), 'ai_lane', v_lane,
                                         'firecrawl_credits', round(v_credits, 1), 'usd_per_credit', v_price, 'usd_total', round(v_usd, 4), 'credits_priced', v_price > 0),
    'likelihood', v_like,
    'in_progress', v_prog,
    'retry', v_retry,
    'value_per_dollar', case when v_usd > 0 then round(v_exp / v_usd, 2) end,
    'value_per_credit', case when v_credits > 0 then round(v_exp / v_credits, 4) end,
    'recommend', case when v_skip is null then 'run' else 'skip' end, 'skip_reason', v_skip);
end $_$;


ALTER FUNCTION "security"."ops_step_value_v1"("p_provider" "uuid", "p_step" "text", "p_scope" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."ops_step_value_v1"("p_provider" "uuid", "p_step" "text", "p_scope" "jsonb") IS 'CF-247 workstream F (mandate §11): value estimate of a candidate plan step (eligible, expected recovery from measured yield, evidence held, AI and Firecrawl cost, likelihood, work in progress, retry spend and last failure, value per dollar); read-only; for workstream D''s planner';



CREATE OR REPLACE FUNCTION "security"."ops_task_dedupe_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_b bigint; v_c int := 0; r record;
begin
  if security.pipeline_num_v1('ops.task_dedupe_on', 0) < 1 then return jsonb_build_object('ok', true, 'changed', 0, 'evidence', 'switched off (ops.task_dedupe_on)'); end if;
  v_b := security.ops_d_detect_count_v1('task_duplicate');
  for r in select j.id, d.first from (select x.kind, coalesce(x.args->>'provider_id', x.scope) k, (array_agg(x.id order by x.created_at))[1] first
                                        from pipeline.admin_jobs x where x.state in ('queued', 'running', 'paused') and coalesce(x.args->>'provider_id', x.scope) is not null
                                       group by 1, 2 having count(*) > 1) d
             join pipeline.admin_jobs j on j.kind = d.kind and coalesce(j.args->>'provider_id', j.scope) = d.k and j.id <> d.first
            where j.state in ('queued', 'running', 'paused') and j.args ? 'plan_run' and not j.cancel_requested
            limit greatest(1, security.pipeline_num_v1('ops.heal_batch', 200)::int) loop
    update pipeline.admin_jobs set cancel_requested = true, updated_at = now() where id = r.id;
    insert into pipeline.admin_job_events(job_id, note, detail) values (r.id, 'asked to stop: the same work is already open in task ' || left(r.first::text, 8), jsonb_build_object('duplicate_of', r.first));
    v_c := v_c + 1;
  end loop;
  if v_c > 0 then perform security.ops_d_run_note_v1(p_issue, 'task_duplicate_stop', v_b, v_b - v_c, v_c, null); end if;
  return jsonb_build_object('ok', true, 'changed', v_c, 'evidence', jsonb_build_object('duplicates_before', v_b));
end $$;


ALTER FUNCTION "security"."ops_task_dedupe_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ops_task_dedupe_verify_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('passed', n = 0, 'measure', jsonb_build_object('duplicate_groups', n), 'evidence', 'open tasks of the same kind for the same provider or scope')
    from (select count(*) n from security.ops_lifecycle_detect_v1() d where d.root_cause = 'task_duplicate') z
$$;


ALTER FUNCTION "security"."ops_task_dedupe_verify_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ops_verify_cleared_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.integration_issues; v_need numeric := security.pipeline_num_v1('ops.stale_clear_hours', 6); v_h numeric; v_clear boolean;
begin
  select * into r from pipeline.integration_issues where id = p_issue;
  v_clear := r.condition_cleared_at is not null and r.last_observed_at <= r.condition_cleared_at;
  v_h := case when v_clear then round(extract(epoch from now() - r.condition_cleared_at) / 3600.0, 2) end;
  return jsonb_build_object('passed', v_clear and v_h >= v_need,
    'measure', jsonb_build_object('condition_cleared', v_clear and v_h >= v_need, 'waiting', v_clear and v_h < v_need, 'cleared_at', r.condition_cleared_at,
                                  'hours_clear', v_h, 'hours_needed', v_need, 'last_observed_at', r.last_observed_at, 'regression_count', r.regression_count),
    'evidence', case when v_clear then format('The check (%s) has not seen the condition since %s: %s hours, %s needed; last seen %s; regressions %s.',
                                             r.detection_source, r.condition_cleared_at, v_h, v_need, r.last_observed_at, r.regression_count)
                     else format('The check (%s) still sees the condition (last seen %s).', r.detection_source, r.last_observed_at) end);
end $$;


ALTER FUNCTION "security"."ops_verify_cleared_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ops_verify_owner_resolved_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.integration_issues; o pipeline.integration_issues;
begin
  select * into r from pipeline.integration_issues where id = p_issue;
  select * into o from pipeline.integration_issues where id = r.superseded_by;
  if o.id is null then return jsonb_build_object('passed', false, 'measure', jsonb_build_object('superseded_invalid', true), 'evidence', 'not linked to an owner'); end if;
  if o.status <> 'closed' then
    return jsonb_build_object('passed', false, 'measure', jsonb_build_object('waiting', true, 'owner', o.issue_ref, 'owner_status', o.status), 'evidence', o.issue_ref || ' is still open');
  end if;
  if r.last_observed_at > o.closed_at then
    return jsonb_build_object('passed', false, 'measure', jsonb_build_object('superseded_invalid', true, 'owner', o.issue_ref, 'owner_closed_at', o.closed_at, 'last_observed_at', r.last_observed_at),
                              'evidence', r.issue_ref || ' was seen again after ' || o.issue_ref || ' closed');
  end if;
  return jsonb_build_object('passed', o.verification_outcome = 'passed',
    'measure', jsonb_build_object('condition_cleared', o.verification_outcome = 'passed', 'owner', o.issue_ref, 'owner_closed_at', o.closed_at, 'owner_verification', o.verification_evidence),
    'evidence', format('Resolved by the shared correction verified on %s (closed %s): %s', o.issue_ref, o.closed_at, left(coalesce(o.verification_evidence->>'evidence', ''), 400)));
end $$;


ALTER FUNCTION "security"."ops_verify_owner_resolved_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ops_verify_stale_reopen_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb := security.ops_recurrence_v1(p_issue); v_ok boolean := coalesce((v->>'stale_reopen')::boolean, false);
begin
  return jsonb_build_object('passed', v_ok, 'measure', v || jsonb_build_object('condition_cleared', v_ok),
    'evidence', case when v_ok then format('Reopened at %s on evidence observed before the close at %s (%s); nothing observed since the close%s. The verification of the close stands.',
                                          v->>'reopened_at', v->>'closed_at', v->>'basis',
                                          case when v ? 'runs_after_close' then format(': %s run(s) of %s since, %s failed', v->>'runs_after_close', v->>'job', v->>'failed_after_close') else '' end)
                     else 'evidence observed after the close: ' || coalesce(v->>'basis', '') end);
end $$;


ALTER FUNCTION "security"."ops_verify_stale_reopen_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."own_page_value_v1"("p_course_id" "uuid", "p_field" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- the course's own page, read by an adapter cleared to admit this field, holds a value: that reading wins over a value taken from another course
  select exists (
    select 1 from pipeline.coverage_course_pages pg
      join pipeline.uni_adapters u on u.provider_id = pg.provider_id and u.enabled and u.admit and p_field = any (u.admit_fields)
     where pg.course_id = p_course_id and pg.read_status = 'read' and pg.identity_basis is not null
       and case p_field
             when 'delivery' then coalesce(security.delivery_mode_from_text(pg.candidates->'adapter_extra'->>'mode'),
                                           security.delivery_mode_from_location(coalesce(pg.candidates->'adapter_extra'->>'location', pg.candidates->'adapter_extra'->>'campus'))) is not null
             when 'intakes' then pg.candidates->>'intakes_by' = 'adapter' and jsonb_array_length(coalesce(pg.candidates->'intakes', '[]'::jsonb)) > 0
             when 'fee' then pg.candidates->>'fee_by' = 'adapter' and nullif(pg.candidates->'fee'->>'value', '') is not null
             else false end)
$$;


ALTER FUNCTION "security"."own_page_value_v1"("p_course_id" "uuid", "p_field" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."page_find_continuity_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_cap jsonb := security.course_search_paid_cap_v1();
        v_never text[] := security.pipeline_list_v1('wc.page_find_never_codes', '["skipped_provider", "directory_site"]'::jsonb);
        r record; v_code text; v_words text; v_at timestamptz; v_note text; v_end int := 0; v_park int := 0; v_rel int := 0; v_rec int := 0; v_err jsonb := '[]'::jsonb;
begin
  if security.pipeline_num_v1('wc.on', 1) < 1 then return jsonb_build_object('held', 'wc.on is 0'); end if;
  v_at := (v_cap->>'resumes_at')::timestamptz;
  for r in select j.id, nullif(j.args->>'provider_id', '')::uuid pid, j.result->'held' held, j.result->'blocked' blocked,
                  coalesce((j.result->>'unprocessed')::int, 0) n_left
             from pipeline.admin_jobs j where j.kind = 'course_page_find' and j.state = 'running'
            order by j.started_at nulls last, j.id limit security.pipeline_num_v1('wc.tick_batch', 500)::int loop
    begin
      v_code := coalesce(r.blocked->>'code', r.held->>'code');
      if r.pid is null then continue; end if;
      if r.held is not null and v_code = any (v_never) and security.pipeline_num_v1('wc.page_find_never_end_on', 1) >= 1 then
        v_words := coalesce(r.blocked->>'words', r.held->>'reason', v_code);
        perform security.work_item_report_v1('page_find', r.pid::text, 'find', 'failed', jsonb_build_object('class', 'authority', 'provider_id', r.pid,
                  'owner', 'course-page-find', 'message', 'cannot run: ' || v_words,
                  'evidence', jsonb_build_object('task', r.id, 'code', v_code, 'fix', r.blocked->>'fix', 'unprocessed', r.n_left)));
        v_note := left('Cannot run: ' || v_words || '. ' || coalesce(r.blocked->>'fix', '') || ' (' || r.n_left || ' course(s) not searched; recorded for a decision)', 500);
        update pipeline.admin_jobs set state = 'failed', error = v_note, finished_at = now(), updated_at = now(),
               result = coalesce(result, '{}'::jsonb) || jsonb_build_object('end_state', 'failed', 'note', v_note, 'blocker', jsonb_build_object('code', v_code, 'words', v_words, 'fix', r.blocked->>'fix'))
         where id = r.id and state = 'running';
        insert into pipeline.admin_job_events(job_id, note) values (r.id, v_note);
        perform security.admin_job_close_v1(r.id);
        perform security.job_outcome_set_v1(r.id, 'blocked_policy', jsonb_build_object('reason', 'cannot run', 'code', v_code, 'by', 'work-continuity-lanes'));
        v_end := v_end + 1;
      elsif r.held is not null and v_cap is not null and security.pipeline_num_v1('wc.page_find_park_on', 1) >= 1 then
        if not exists (select 1 from pipeline.work_items w where w.lane = 'page_find' and w.entity = r.pid::text and w.work_kind = 'find'
                         and w.stage = 'deferred' and w.failure_class = 'budget_exhausted' and w.next_eligible_at = v_at) then
          perform security.work_item_report_v1('page_find', r.pid::text, 'find', 'budget', jsonb_build_object('purpose', 'course_link_search', 'provider_id', r.pid,
                    'owner', 'course-page-find', 'message', 'held behind the course search cap: ' || (v_cap->>'words'),
                    'evidence', jsonb_build_object('task', r.id, 'cap', v_cap, 'held_as', v_code, 'unprocessed', r.n_left)));
          update pipeline.work_items w set next_eligible_at = v_at, updated_at = now()
           where w.lane = 'page_find' and ((w.entity = r.pid::text and w.work_kind = 'find') or (w.entity = '*lane' and w.work_kind = 'lane'))
             and w.stage in ('deferred', 'lane_paused');
          v_park := v_park + 1;
        end if;
        if security.pipeline_num_v1('wc.page_find_release_on', 0) >= 1 then
          v_note := left('Parked: ' || (v_cap->>'words') || '; resumes ' || to_char(v_at at time zone 'Australia/Melbourne', 'DD Mon HH24:MI')
                         || '. ' || r.n_left || ' course(s) stay queued for the search lane; the plan''s retry starts it again', 500);
          update pipeline.admin_jobs set state = 'failed', error = v_note, finished_at = now(), updated_at = now(),
                 result = coalesce(result, '{}'::jsonb) || jsonb_build_object('end_state', 'failed', 'note', v_note, 'parked', jsonb_build_object('cap', v_cap, 'resumes_at', v_at))
           where id = r.id and state = 'running';
          insert into pipeline.admin_job_events(job_id, note) values (r.id, v_note);
          perform security.admin_job_close_v1(r.id);
          perform security.job_outcome_set_v1(r.id, 'deferred_dependency', jsonb_build_object('reason', 'paid cap', 'cap', v_cap, 'by', 'work-continuity-lanes'));
          v_rel := v_rel + 1;
        end if;
      elsif r.held is null and exists (select 1 from pipeline.work_items w where w.lane = 'page_find' and w.entity = r.pid::text and w.work_kind = 'find'
                                         and w.failure_class = 'budget_exhausted' and w.stage <> 'done') then
        perform security.work_item_report_v1('page_find', r.pid::text, 'find', 'succeeded', jsonb_build_object('outcome', 'succeeded_with_result', 'provider_id', r.pid));
        v_rec := v_rec + 1;
      end if;
    exception when others then
      v_err := v_err || jsonb_build_object('task', r.id, 'error', left(sqlerrm, 200));
    end;
  end loop;
  return jsonb_build_object('cap', v_cap, 'ended_cannot_run', v_end, 'parked', v_park, 'released', v_rel, 'recovered', v_rec, 'errors', v_err);
end $$;


ALTER FUNCTION "security"."page_find_continuity_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."page_match_bonus_v1"("p_course" "uuid", "p_provider" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select greatest(security.course_list_bonus_v1(p_course, p_provider), security.page_rejection_bonus_v1(p_course),
                  -- SP-1: one more AI pass for a recorded course once a newer map exists (the re-open path)
                  case when exists (select 1 from pipeline.course_no_page n join pipeline.coverage_provider_discovery d on d.provider_id = n.provider_id
                                     where n.course_id = p_course and n.state in ('confirmed', 'confirmed_auto', 'conjoint') and d.mapped_at > coalesce(n.inventory_at, n.proposed_at))
                       then 1 else 0 end)
$$;


