CREATE OR REPLACE FUNCTION "security"."page_refind_settle_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rep int; v_old int;
begin
  update pipeline.page_refind r set state = 'replaced', decided_at = now(), result_url = g.url
    from pipeline.coverage_course_pages g, pipeline.course_link_search s
   where r.state = 'open' and g.course_id = r.course_id and s.course_id = r.course_id and s.state = 'verified'
     and g.status = 'bound' and g.identity_basis is not null and security.site_host_v1(g.url) like '%' || r.new_domain;
  get diagnostics v_rep = row_count;
  -- nothing passed on the current website: the old page goes back and is read again
  with back as (
    update pipeline.page_refind r set state = 'kept_old', decided_at = now(), result_url = r.old_url
      from pipeline.course_link_search s where r.state = 'open' and s.course_id = r.course_id and s.state in ('none', 'error')
    returning r.course_id, r.old_url, r.old_basis)
  update pipeline.coverage_course_pages g set url = b.old_url, basis = b.old_basis, status = 'bound', bound_at = now(), read_status = null, read_at = null,
         http_status = null, fetched_via = null, identity_basis = null, evidence_id = null, candidates = null, leased_until = null, read_attempts = 0, next_read_at = now()
    from back b where g.course_id = b.course_id and g.url <> b.old_url;
  select count(*) into v_old from pipeline.page_refind where state = 'kept_old' and decided_at > now() - interval '1 minute';  -- fixed: this run only
  return jsonb_build_object('replaced', v_rep, 'kept_old', v_old);
end $$;


ALTER FUNCTION "security"."page_refind_settle_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."page_refind_start_v1"("p_provider_id" "uuid", "p_old_domain" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_dom text; v_n int;
begin
  select rc.search_domain into v_dom from pipeline.course_link_recipes rc where rc.provider_id = p_provider_id and rc.active;
  if v_dom is null or v_dom = lower(p_old_domain) then raise exception 'the provider''s course-page search must point at its current website first'; end if;
  insert into pipeline.page_refind(course_id, provider_id, old_url, old_basis, new_domain, reason)
  select g.course_id, g.provider_id, g.url, g.basis, v_dom, p_reason
    from pipeline.coverage_course_pages g join catalogue.courses c on c.id = g.course_id and c.lifecycle_status = 'active'
   where g.provider_id = p_provider_id and g.status = 'bound' and g.read_status = 'read'
     and security.site_host_v1(g.url) = lower(p_old_domain)
  on conflict (course_id) do nothing;
  get diagnostics v_n = row_count;
  insert into pipeline.course_link_search(course_id, provider_id, stage, state, queued_at, requested_at)
  select r.course_id, r.provider_id, case when c.course_code ~ '^[0-9]{6}[0-9A-Z]$' then 'cricos' else 'title' end, 'queued', now(), now()
    from pipeline.page_refind r join catalogue.courses c on c.id = r.course_id where r.provider_id = p_provider_id and r.state = 'open'
  on conflict (course_id) do update set state = 'queued', stage = excluded.stage, attempts = 0, cand_idx = 0, candidates = null, results = null, bound_url = null,
         queued_at = now(), requested_at = now(), sent_at = null, done_at = null;
  return jsonb_build_object('courses', v_n, 'search_domain', v_dom);
end $_$;


ALTER FUNCTION "security"."page_refind_start_v1"("p_provider_id" "uuid", "p_old_domain" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."page_refused_v1"("p_course" "uuid", "p_url" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from pipeline.page_rejections r where r.course_id = p_course and r.url = p_url)
      or exists (select 1 from pipeline.course_page_blocks b where b.course_id = p_course and b.url = p_url)
$$;


ALTER FUNCTION "security"."page_refused_v1"("p_course" "uuid", "p_url" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."page_refused_v1"("p_course" "uuid", "p_url" "text") IS 'CF-247 S1 (v2.15.352): the one negative-evidence predicate - true when the page was rejected (page_rejections) or blocked (course_page_blocks) for the course; every automatic binding path asks it';



CREATE OR REPLACE FUNCTION "security"."page_rejection_bonus_v1"("p_course" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- one more AI page match for a course after each rejection of a page it was bound to
  select case when exists (select 1 from pipeline.page_rejections r where r.course_id = p_course
                             and r.rejected_at > coalesce((select max(q.created_at) from pipeline.coverage_ai_match q where q.course_id = p_course), '-infinity'::timestamptz)) then 1 else 0 end
$$;


ALTER FUNCTION "security"."page_rejection_bonus_v1"("p_course" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."page_reread_pilot_run_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_on boolean := coalesce((security.toolset_setting('pipeline', 'reread.pilot_enabled') #>> '{}')::boolean, false);
        v_max int := least(security.pipeline_num_v1('reread.pilot_daily_max', 25), 25)::int;  -- fixed: 25 a day is the approved ceiling (D13)
        v_days int := greatest(security.pipeline_num_v1('reread.pilot_min_days', 30), 30)::int;  -- fixed: never sooner than 30 days (D13)
        v_today timestamptz := ((now() at time zone 'Australia/Melbourne')::date)::timestamp at time zone 'Australia/Melbourne';
        v_rec int := 0; v_rel int := 0; v_stop text;
begin
  -- 1. a release the read lane has not attempted in 3 days is closed, and its page is exhausted again (so no later read can use Firecrawl)
  update pipeline.coverage_course_pages p set read_attempts = greatest(p.read_attempts, 3)
    from pipeline.page_reread_pilot r
   where r.course_id = p.course_id and r.outcome_at is null and r.released_at < now() - interval '3 days'  -- fixed: a release not attempted in 3 days is closed
     and (p.read_at is null or p.read_at <= r.released_at);
  -- 2. outcomes: a released page is attempted once by the read lane; record what happened
  with o as (
    update pipeline.page_reread_pilot r set outcome_at = now(), outcome_read_status = p.read_status, outcome_http = p.http_status, outcome_fetched_via = p.fetched_via,
           outcome_identity_basis = p.identity_basis, outcome_evidence = p.evidence_id is not null and p.evidence_id is distinct from (r.before_state ->> 'evidence_id')::uuid,
           layer4_items = (select count(*) from pipeline.layer4_review_items l where l.entity_id = r.course_id and l.created_at > r.released_at),
           fields_filled = (select count(*) from pipeline.field_enrich_items i where i.course_id = r.course_id and i.state = 'filled' and i.updated_at > r.released_at)
      from pipeline.coverage_course_pages p
     where p.course_id = r.course_id and r.outcome_at is null
       and ((p.read_at > r.released_at and coalesce(p.leased_until, '-infinity') < now()) or r.released_at < now() - interval '3 days')  -- fixed: a release not attempted in 3 days is closed
    returning r.course_id)
  select count(*) into v_rec from o;
  -- 3. stop conditions: Firecrawl used for a pilot page, or Layer 4 grew from one
  if exists (select 1 from pipeline.page_reread_pilot r where r.outcome_fetched_via = 'firecrawl' or coalesce(r.layer4_items, 0) > 0) then
    v_stop := 'a pilot page was read through Firecrawl or produced Layer 4 review items';
    if v_on then
      update pipeline.platform_toolset_settings set value = 'false'::jsonb, reason = 'Stopped by the pilot itself (D13): ' || v_stop, updated_at = now()
       where toolset_key = 'pipeline' and key = 'reread.pilot_enabled';
      insert into pipeline.admin_control_events(area, action, target, detail, actor)
      values ('toolsets', 'setting', 'pipeline.reread.pilot_enabled', jsonb_build_object('before', true, 'after', false, 'reason', 'D13 stop condition: ' || v_stop), null);
    end if;
    return jsonb_build_object('recorded', v_rec, 'released', 0, 'stopped', v_stop);
  end if;
  if not v_on then return jsonb_build_object('recorded', v_rec, 'released', 0, 'pilot', 'off'); end if;
  -- 4. release today's eligible pages, never more than the daily ceiling, each page once ever
  with c as (
    select p.course_id, p.provider_id, p.url, jsonb_build_object('read_status', p.read_status, 'read_at', p.read_at, 'read_attempts', p.read_attempts, 'http_status', p.http_status,
             'next_read_at', p.next_read_at, 'fetched_via', p.fetched_via, 'evidence_id', p.evidence_id, 'status', p.status) before_state
      from pipeline.coverage_course_pages p
     where p.status in ('bound', 'ambiguous') and p.read_attempts >= 3 and coalesce(p.leased_until, '-infinity') < now()
       and (p.read_status is null or p.read_status in ('fetch_failed', 'blocked'))
       and coalesce(p.read_at, p.bound_at) <= now() - make_interval(days => v_days)
       and not exists (select 1 from pipeline.page_reread_pilot r where r.course_id = p.course_id)
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.provider_id)
       and not security.course_held_v1(p.course_id)
       and not exists (select 1 from pipeline.enrichment_flags f where f.entity = 'provider' and f.provider_id = p.provider_id and f.cleared_at is null
                        and f.reason_code in ('site_unreachable', 'pages_refuse_reading', 'manual_hold'))
       and not exists (select 1 from pipeline.enrichment_flags f where f.entity = 'course' and f.entity_key = p.course_id::text and f.cleared_at is null
                        and (f.reason_code = 'manual_hold' or f.raised_by_kind = 'person'))
     order by coalesce(p.read_at, p.bound_at)
     limit greatest(v_max - (select count(*) from pipeline.page_reread_pilot r where r.released_at >= v_today), 0)),
  ins as (insert into pipeline.page_reread_pilot(course_id, provider_id, url, before_state) select c.course_id, c.provider_id, c.url, c.before_state from c returning course_id)
  update pipeline.coverage_course_pages p set read_attempts = 2, next_read_at = now(), leased_until = null from ins where p.course_id = ins.course_id;
  get diagnostics v_rel = row_count;
  return jsonb_build_object('recorded', v_rec, 'released', v_rel, 'daily_max', v_max, 'min_days', v_days);
end $$;


ALTER FUNCTION "security"."page_reread_pilot_run_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."page_reread_pilot_summary_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'released', count(*), 'attempted', count(*) filter (where r.outcome_at is not null),
    'read', count(*) filter (where r.outcome_read_status = 'read'), 'identity_proved', count(*) filter (where r.outcome_identity_basis is not null and r.outcome_read_status = 'read'),
    'new_evidence', count(*) filter (where r.outcome_evidence), 'fields_filled', coalesce(sum(r.fields_filled), 0),
    'firecrawl_reads', count(*) filter (where r.outcome_fetched_via = 'firecrawl'), 'layer4_items', coalesce(sum(r.layer4_items), 0),
    'by_outcome', coalesce((select jsonb_object_agg(x.s, x.n) from (select coalesce(r2.outcome_read_status, 'waiting') s, count(*) n from pipeline.page_reread_pilot r2 group by 1) x), '{}'::jsonb),
    'exhausted_not_yet_tried', (select count(*) from pipeline.coverage_course_pages p where p.status in ('bound', 'ambiguous') and p.read_attempts >= 3
                          and (p.read_status is null or p.read_status in ('fetch_failed', 'blocked'))
                          and not exists (select 1 from pipeline.page_reread_pilot r3 where r3.course_id = p.course_id)),
    'enabled', coalesce((security.toolset_setting('pipeline', 'reread.pilot_enabled') #>> '{}')::boolean, false))
  from pipeline.page_reread_pilot r
$$;


ALTER FUNCTION "security"."page_reread_pilot_summary_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."pdesc_about_like_patterns_v1"() RETURNS "text"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- the same address patterns security.provider_description_stored_v1 starts from (an About page name or prefix as a path part), escaped for LIKE
  select array(select '%/' || replace(replace(replace(lower(t), '\', '\\'), '%', '\%'), '_', '\_') || '%'
                 from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'pdesc.about_patterns'), '[]'::jsonb)) t
               union all
               select '%/' || replace(replace(replace(lower(t), '\', '\\'), '%', '\%'), '_', '\_') || '%'
                 from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'pdesc.about_prefixes'), '[]'::jsonb)) t where t <> '')
$$;


ALTER FUNCTION "security"."pdesc_about_like_patterns_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."pdesc_about_like_patterns_v1"() IS 'CF-247 F-PDESC QA B2: the LIKE patterns of the About-page address rule (pdesc.about_patterns and pdesc.about_prefixes), the first step of security.provider_description_stored_v1, as one list.';



CREATE OR REPLACE FUNCTION "security"."pdesc_claim_check_v1"("p_sentence" "text", "p_quote" "text", "p_term" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with t as (select btrim(regexp_replace(lower(coalesce(p_term,'')),'[^a-z0-9#%]+',' ','g')) term),
  f as (select case when t.term ~ ' ' then array[t.term] else array[t.term, t.term||'s', t.term||'es', t.term||'d', t.term||'ed'] end forms from t where t.term<>''),
  hit as (select exists(select 1 from f, unnest(f.forms) x where security.pdesc_has_term_v1(p_sentence,x)) in_sentence,
                 exists(select 1 from f, unnest(f.forms) x where security.pdesc_has_term_v1(p_quote,x)) in_quote,
                 exists(select 1 from f, unnest(f.forms) x where lower(coalesce(p_quote,'')) ~ ('(\m(no(?!\s+matter)|not(?!\s+(only|just))|never|cannot|without|nor|none|neither)\M|n''t)(\W+\w+){0,2}\W+'||x||'\M')) negated_quote,
                 exists(select 1 from f, unnest(f.forms) x where lower(coalesce(p_sentence,'')) ~ ('(\m(no(?!\s+matter)|not(?!\s+(only|just))|never|cannot|without|nor|none|neither)\M|n''t)(\W+\w+){0,2}\W+'||x||'\M')) negated_sentence)
  select case when not hit.in_sentence then null
              when not hit.in_quote then 'unsupported_claim'
              when hit.negated_quote and not hit.negated_sentence then 'claim_negated_in_source'
              end from hit
$$;


ALTER FUNCTION "security"."pdesc_claim_check_v1"("p_sentence" "text", "p_quote" "text", "p_term" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."pdesc_claim_check_v1"("p_sentence" "text", "p_quote" "text", "p_term" "text") IS 'Provider descriptions (Platform Admin 5 Nov 2026 20:03 §2): evidence-aware check of one pdesc.evidence_claim_words word. Null = not used or supported by the sentence''s own official quote (same word, plural or tense); unsupported_claim = the quote does not state it; claim_negated_in_source = the quote negates it and the sentence does not. Never a keyword-only rejection.';



CREATE OR REPLACE FUNCTION "security"."pdesc_clean_name_v1"("p_name" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- a usable provider name, or null: not empty, no web-page markup (&#039; &amp;), not a placeholder (N/A, NA, TBC ...), at least pdesc.name_min_chars letters or digits
  select case when nullif(btrim(p_name), '') is null then null
              when btrim(p_name) ~* '&#?[a-z0-9]{1,8};' then null
              when length(regexp_replace(btrim(p_name), '[^[:alnum:]]+', '', 'g')) < security.pipeline_num_v1('pdesc.name_min_chars', 3) then null
              when exists (select 1 from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'pdesc.placeholder_names'), '[]'::jsonb)) w
                            where regexp_replace(lower(w), '[^a-z0-9]+', '', 'g') <> '' and regexp_replace(lower(w), '[^a-z0-9]+', '', 'g') = regexp_replace(lower(btrim(p_name)), '[^a-z0-9]+', '', 'g')) then null
              else btrim(p_name) end
$$;


ALTER FUNCTION "security"."pdesc_clean_name_v1"("p_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."pdesc_clean_name_v1"("p_name" "text") IS 'CF-247 F-PDESC QA N8: a provider name the automatic rule can rely on (not empty, not a placeholder such as N/A or NA, no web-page markup such as &#039;, long enough), or null. The placeholder list and the length are settings.';



CREATE OR REPLACE FUNCTION "security"."pdesc_has_term_v1"("p_text" "text", "p_term" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select nullif(btrim(regexp_replace(lower(coalesce(p_term, '')), '[^a-z0-9#%]+', ' ', 'g')), '') is not null
     and position(' ' || btrim(regexp_replace(lower(coalesce(p_term, '')), '[^a-z0-9#%]+', ' ', 'g')) || ' '
                  in ' ' || regexp_replace(lower(coalesce(p_text, '')), '[^a-z0-9#%]+', ' ', 'g') || ' ') > 0
$$;


ALTER FUNCTION "security"."pdesc_has_term_v1"("p_text" "text", "p_term" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."pdesc_machine_neutral_supported_v1"("p_text" "text", "p_sentences" "jsonb") RETURNS "text"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare w text; s jsonb; v_out text[] := '{}'; v_seen boolean; v_bad boolean;
        v_norm text := regexp_replace(lower(btrim(coalesce(p_text, ''))), '\s+', ' ', 'g');
begin
  if jsonb_typeof(p_sentences) is distinct from 'array' or jsonb_array_length(p_sentences) = 0 then return v_out; end if;
  -- the text must be exactly the sentences that carry the quotes; otherwise no quote speaks for it
  if v_norm is distinct from (select regexp_replace(lower(string_agg(btrim(x->>'text'), ' ' order by o)), '\s+', ' ', 'g') from jsonb_array_elements(p_sentences) with ordinality e(x, o)) then return v_out; end if;
  for w in select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'pdesc.machine_neutral_words'), '[]'::jsonb)) loop
    v_seen := false; v_bad := false;
    for s in select x from jsonb_array_elements(p_sentences) x loop
      if security.pdesc_has_term_v1(s->>'text', w) then
        v_seen := true;
        -- the quote is the sentence's own passage, proved on the stored official page (on_page); it must hold the same word and must not negate it
        if coalesce((s->>'on_page')::boolean, false) is false or nullif(btrim(coalesce(s->>'quote', '')), '') is null
           or not security.pdesc_has_term_v1(s->>'quote', w) or security.pdesc_claim_check_v1(s->>'text', s->>'quote', w) is not null then v_bad := true; end if;
      end if;
    end loop;
    if v_seen and not v_bad then v_out := v_out || lower(w); end if;
  end loop;
  return v_out;
end $$;


ALTER FUNCTION "security"."pdesc_machine_neutral_supported_v1"("p_text" "text", "p_sentences" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."pdesc_machine_neutral_supported_v1"("p_text" "text", "p_sentences" "jsonb") IS 'CF-247 F-PDESC Directive 3 Blocker A: the words of pdesc.machine_neutral_words that the description text uses and whose every sentence is supported by its exact official quote (the quote holds the same word, does not negate it, the sentence is on_page, and the text is exactly the sentences). Empty when there are no sentences. Read only.';



CREATE OR REPLACE FUNCTION "security"."pdesc_machine_text_check_ctx_v1"("p_provider" "uuid", "p_text" "text", "p_codes" "text"[] DEFAULT '{}'::"text"[], "p_sentences" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_t text := lower(coalesce(p_text, '')); v_ok text[] := security.pdesc_machine_neutral_supported_v1(p_text, p_sentences); n text; w text; m text[]; v_year int := extract(year from now())::int; v_ymin int := security.pipeline_num_v1('pdesc.founded_year_min', 1800)::int;
        v_lists text[] := case when security.pipeline_num_v1('pdesc.prompt_on', 0) >= 1  /* 20261112034500: the prompt profile (Operating Model 3.3.1) */
          then array['pdesc.prompt_refused_words', 'pdesc.superlatives', 'pdesc.machine_refused_words']
               || case when (select count(distinct fw.word) from regexp_split_to_table(lower(coalesce(p_text, '')), '[^a-zà-ÿ]+') fw(word)
                              where fw.word in ('les', 'des', 'est', 'une', 'et', 'du', 'pour', 'dans', 'sur', 'aux', 'au', 'qui')) >= 3  -- fixed: a French text has three or more distinct French function words
                       then array['pdesc.machine_refused_words_fr'] else '{}'::text[] end
          else array['pdesc.claim_words', 'pdesc.superlatives', 'pdesc.evidence_claim_words', 'pdesc.machine_refused_words', 'pdesc.machine_refused_words_fr'] end; l text;
begin
  -- web-page markup left in the text (&#039; &amp; &nbsp;) is never admitted: the wording was not read cleanly
  if coalesce(p_text, '') ~* '&#?[a-z0-9]{1,8};' then return 'entity_encoded:page markup'; end if;
  -- the provider's own names, the verified register codes and the register's own fixed wording (which names the register, e.g. "... for Overseas Students") are not claims ("Premier Institute", "provider code 00002J")
  for n in select nm from (select p.canonical_name nm from catalogue.providers p where p.id = p_provider union all select p.display_name from catalogue.providers p where p.id = p_provider
                           union all select p.short_name from catalogue.providers p where p.id = p_provider) z where nullif(btrim(nm), '') is not null order by length(nm) desc loop
    v_t := replace(v_t, lower(n), ' ');
  end loop;
  foreach n in array coalesce(p_codes, '{}') loop
    if nullif(btrim(n), '') is not null then v_t := replace(v_t, lower(n), ' '); end if;
  end loop;
  foreach l in array v_lists loop
    for w in select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', l), '[]'::jsonb)) loop
      -- a neutral population word whose every sentence is supported by its exact official quote is not a claim here; every other list, and every other word in these two, still refuses
      if l in ('pdesc.claim_words', 'pdesc.machine_refused_words_fr') and lower(w) = any(v_ok) then continue; end if;
      if security.pdesc_has_term_v1(v_t, w) then return 'refused_word:' || w; end if;
    end loop;
  end loop;
  if security.pipeline_num_v1('pdesc.machine_numbers_allowed', 0) < 1 then
    for m in select regexp_matches(v_t, '[0-9][0-9,.]*[0-9]|[0-9]', 'g') loop
      if not (m[1] ~ '^[0-9]{4}$' and m[1]::int between v_ymin and v_year) then return 'figure:' || m[1]; end if;
    end loop;
    if v_t ~ '[0-9]\s*(%|per\s*cent|percent)' then return 'figure:percentage'; end if;
  end if;
  return null;
end
$_$;


ALTER FUNCTION "security"."pdesc_machine_text_check_ctx_v1"("p_provider" "uuid", "p_text" "text", "p_codes" "text"[], "p_sentences" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."pdesc_machine_text_check_ctx_v1"("p_provider" "uuid", "p_text" "text", "p_codes" "text"[], "p_sentences" "jsonb") IS 'CF-247 F-PDESC machine rule pdesc-machine-v1 with context: null when the description is free of page markup, claim, marketing, campus/scholarship/guarantee and the extra machine words (English and French lists) and (unless allowed) of figures other than a year in range; otherwise the first refusal. A word of pdesc.machine_neutral_words (students, staff, alumni) is not a claim when every sentence that uses it is supported by its exact official quote (security.pdesc_machine_neutral_supported_v1); with no sentences the strict rule applies. The provider''s own names and listed register codes are ignored.';



CREATE OR REPLACE FUNCTION "security"."pdesc_machine_text_check_v1"("p_provider" "uuid", "p_text" "text", "p_codes" "text"[] DEFAULT '{}'::"text"[]) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- no sentences = no quotes to check: the strict rule, as before (the register-fact profile, tier 4, has none)
  return security.pdesc_machine_text_check_ctx_v1(p_provider, p_text, p_codes, '[]'::jsonb);
end $$;


ALTER FUNCTION "security"."pdesc_machine_text_check_v1"("p_provider" "uuid", "p_text" "text", "p_codes" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."pdesc_machine_text_check_v1"("p_provider" "uuid", "p_text" "text", "p_codes" "text"[]) IS 'CF-247 F-PDESC machine rule pdesc-machine-v1, strict form (no sentences, so no neutral word is allowed): see security.pdesc_machine_text_check_ctx_v1. Used by the register-fact profile.';



CREATE OR REPLACE FUNCTION "security"."pdesc_name_forms_v1"("p_names" "text"[]) RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  -- CF-247 F-PDESC (20261112023700): the forms a provider's own name is written in, for the first-sentence check
  select coalesce(array_agg(distinct f) filter (where length(f) >= 3), '{}'::text[])
    from (select btrim(regexp_replace(replace(v, '&', ' and '), '\s+', ' ', 'g')) f
            from unnest(coalesce(p_names, '{}'::text[])) n
            cross join lateral unnest(array[n] || string_to_array(n, ',')) part
            cross join lateral (select btrim(regexp_replace(part, '\s*\([^)]*\)', '', 'g')) bare) b
            cross join lateral unnest(array[btrim(part), b.bare,
                 btrim(regexp_replace(b.bare, '(\s*,?\s+(pty\.?\s*ltd\.?|proprietary\s+limited|limited|ltd\.?|inc\.?|incorporated|llc))+\s*$', '', 'i'))]) v
           where nullif(btrim(coalesce(part, '')), '') is not null) z
$_$;


ALTER FUNCTION "security"."pdesc_name_forms_v1"("p_names" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."pdesc_name_forms_v1"("p_names" "text"[]) IS 'CF-247 F-PDESC (20261112023700): a provider''s name forms (each comma-separated name, no parenthesised part, no legal suffix, & as and) for the first-sentence check in provider_description_validate_v1.';



CREATE OR REPLACE FUNCTION "security"."pdesc_number_norm_v1"("p" "text", "p_words" boolean) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare v text := lower(coalesce(p,'')); u text[] := array['one','two','three','four','five','six','seven','eight','nine'];
 teens text[] := array['ten','eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen'];
 tens text[] := array['twenty','thirty','forty','fifty','sixty','seventy','eighty','ninety']; i int; k int;
begin
 v := regexp_replace(v, '\m(per\s?cent|percent)\M', '%', 'g');
 v := regexp_replace(v, '([0-9])[,\s   ''](?=[0-9]{3}([^0-9]|$))', '\1', 'g');
 if p_words then
  for i in 1..array_length(tens,1) loop
   for k in 1..array_length(u,1) loop
    v := regexp_replace(v, '\m'||tens[i]||'[-\s]'||u[k]||'\M', ((i+1)*10+k)::text, 'g');
   end loop;
   v := regexp_replace(v, '\m'||tens[i]||'\M', ((i+1)*10)::text, 'g');
  end loop;
  for i in 1..array_length(teens,1) loop v := regexp_replace(v, '\m'||teens[i]||'\M', (i+9)::text, 'g'); end loop;
  for i in 1..array_length(u,1) loop v := regexp_replace(v, '\m'||u[i]||'\M', i::text, 'g'); end loop;
  v := regexp_replace(v, '\mzero\M', '0', 'g');
 end if;
 return v;
end $_$;


ALTER FUNCTION "security"."pdesc_number_norm_v1"("p" "text", "p_words" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."pdesc_number_norm_v1"("p" "text", "p_words" boolean) IS 'Provider descriptions (validation 5 Nov 2026, decision 20:03 §2): number format normalisation for unsupported_numeric_claim. Never a keyword-only or format-only rejection.';



CREATE OR REPLACE FUNCTION "security"."pdesc_on_demand_due_v1"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 F-PDESC (20261112010000): a live on-demand read is due (and can still be tried)
  select exists (select 1 from pipeline.provider_description_reads x
                  where security.pdesc_on_demand_live_v1(x.checks) and x.tries < security.pipeline_num_v1('pdesc.tries', 3)
                    and ((x.state = 'queued' and x.next_try_at <= now()) or (x.state = 'reading' and x.leased_until < now())))
$$;


ALTER FUNCTION "security"."pdesc_on_demand_due_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."pdesc_on_demand_due_v1"() IS 'CF-247 F-PDESC (20261112010000): true while a Fill description read asked for within pdesc.on_demand_minutes is due.';



CREATE OR REPLACE FUNCTION "security"."pdesc_on_demand_live_v1"("p_checks" "jsonb") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 F-PDESC (20261112010000): a read's on-demand mark counts only within pdesc.on_demand_minutes of the click; after that the read is
  -- an ordinary read of the regular scan with every limit (a mark left on a requeued read gives nothing)
  select coalesce(p_checks ? 'on_demand' and (p_checks->'on_demand'->>'at')::timestamptz > now() - make_interval(mins => security.pipeline_num_v1('pdesc.on_demand_minutes', 15)::int), false)
$$;


ALTER FUNCTION "security"."pdesc_on_demand_live_v1"("p_checks" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."pdesc_on_demand_live_v1"("p_checks" "jsonb") IS 'CF-247 F-PDESC (20261112010000): true while a read''s Fill description mark is within pdesc.on_demand_minutes; every on-demand exemption uses it.';



CREATE OR REPLACE FUNCTION "security"."pdesc_present_support_v1"("p_sentence" "text", "p_quote" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select security.pdesc_support_v1(
    regexp_replace(coalesce(p_sentence,''), '\m(university|universities|college|colleges|institute|institution|polytechnic|school)\M', ' ', 'gi'),
    coalesce((select string_agg(c, ' ') from regexp_split_to_table(lower(coalesce(p_quote,'')), '[;:.!?,]|\m(today|now|currently|nowadays|but|while|whereas)\M') c
              where c !~ '\m(former|formerly|previously|renamed|closed|merged|ceased|became)\M' and c !~ 'was known as'), ''))
$$;


ALTER FUNCTION "security"."pdesc_present_support_v1"("p_sentence" "text", "p_quote" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."pdesc_present_support_v1"("p_sentence" "text", "p_quote" "text") IS 'Provider descriptions (validation 5 Nov 2026, decision 20:03 §2): pdesc_support_v1 of the sentence against the non-historic clauses of its quote; historic_claim_context holds only when this is below pdesc.support_min_share.';



CREATE OR REPLACE FUNCTION "security"."pdesc_reader_behaviour_v1"() RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- the reader that is running: one row, kept by the stamps the worker writes (pipeline.pdesc_reader_state)
  select s.version from pipeline.pdesc_reader_state s where s.singleton
$$;


ALTER FUNCTION "security"."pdesc_reader_behaviour_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."pdesc_reader_behaviour_v1"() IS 'CF-247 F-PDESC: the behaviour version of the provider-description reader that is running now (the newest stamp a worker wrote on an identity check; pipeline.pdesc_reader_state, one row). Used to offer identity holds of an earlier reader once more. Read only.';



CREATE OR REPLACE FUNCTION "security"."pdesc_reader_stamp_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- the newest stamp written by a worker is the reader that is running; unchanged when it is the same
  insert into pipeline.pdesc_reader_state(singleton, version, seen_at) values (true, new.checks->'identity'->>'reader_behavior_version', now())
  on conflict (singleton) do update set version = excluded.version, seen_at = excluded.seen_at where pipeline.pdesc_reader_state.version is distinct from excluded.version;
  return null;
end $$;


ALTER FUNCTION "security"."pdesc_reader_stamp_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."pdesc_reader_stamp_v1"() IS 'CF-247 F-PDESC: trigger function; records the reader behaviour version a worker stamped on a provider-description read as the reader that is running (pipeline.pdesc_reader_state).';



CREATE OR REPLACE FUNCTION "security"."pdesc_similarity_v1"("a" "text", "b" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with x as (select security.pdesc_words_v1(a) wa, security.pdesc_words_v1(b) wb)
  select case when cardinality(x.wa) = 0 or cardinality(x.wb) = 0 then 0
              else round((select count(*) from unnest(x.wa) w where w = any (x.wb))::numeric
                         / (select count(*) from (select unnest(x.wa) union select unnest(x.wb)) u), 4) end
    from x
$$;


ALTER FUNCTION "security"."pdesc_similarity_v1"("a" "text", "b" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."pdesc_support_v1"("p_sentence" "text", "p_quote" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with s as (select distinct left(w, 5) w from regexp_split_to_table(lower(coalesce(p_sentence, '')), '[^a-z0-9]+') w
              where length(w) >= 4 and w not in ('that', 'this', 'with', 'from', 'into', 'their', 'there', 'which', 'where', 'what', 'have', 'also', 'such', 'they', 'them', 'than', 'more', 'most', 'other', 'offers', 'offer', 'provides', 'provide')),
       q as (select distinct left(w, 5) w from regexp_split_to_table(lower(coalesce(p_quote, '')), '[^a-z0-9]+') w where length(w) >= 4)
  select case when (select count(*) from s) = 0 then 1 else round((select count(*) from s where s.w in (select w from q))::numeric / (select count(*) from s), 4) end
$$;


ALTER FUNCTION "security"."pdesc_support_v1"("p_sentence" "text", "p_quote" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."pdesc_text_rule_fingerprint_v1"() RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select md5(coalesce((select p.prosrc from pg_proc p where p.oid = to_regprocedure('security.pdesc_machine_text_check_ctx_v1(uuid,text,text[],jsonb)')), '')
          || '|' || coalesce((select p.prosrc from pg_proc p where p.oid = to_regprocedure('security.pdesc_machine_neutral_supported_v1(text,jsonb)')), '')
          || '|' || coalesce((select p.prosrc from pg_proc p where p.oid = to_regprocedure('security.provider_description_registry_profile_v1(uuid)')), '')
          || '|' || coalesce((select jsonb_object_agg(s.key, s.value order by s.key)::text from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline'
                               and s.key in ('pdesc.claim_words', 'pdesc.superlatives', 'pdesc.evidence_claim_words', 'pdesc.machine_refused_words', 'pdesc.machine_refused_words_fr', 'pdesc.machine_neutral_words', 'pdesc.machine_numbers_allowed', 'pdesc.founded_year_min')), ''))
$$;


ALTER FUNCTION "security"."pdesc_text_rule_fingerprint_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."pdesc_text_rule_fingerprint_v1"() IS 'CF-247 F-PDESC: md5 of the machine text rule (security.pdesc_machine_text_check_ctx_v1 and its neutral-word helper), the register-fact profile builder and the word-list settings it reads. The register-fact tier records it on a machine-text hold and looks at the hold again when it changes. Read only.';



