COMMENT ON FUNCTION "security"."pipeline_progress_table_v1"("p_window_hours" integer) IS 'CF-247 direction 4 Nov 2026 10:00 §11: verified progress by pipeline (read only)';



CREATE OR REPLACE FUNCTION "security"."pipeline_setting_cron_arg"("p_jobname" "text", "p_key" "text", "p_value" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_cmd text; v_json text; v_new text; v_jobid bigint;
begin
  select jobid, command into v_jobid, v_cmd from cron.job where jobname = p_jobname;
  if v_jobid is null then raise exception 'job % not found', p_jobname; end if;
  v_json := substring(v_cmd from ',''(\{.*\})''::jsonb');
  if v_json is null then raise exception 'job % has no JSON body', p_jobname; end if;
  v_new := jsonb_set(v_json::jsonb, array[p_key], to_jsonb(p_value), true)::text;
  perform cron.alter_job(job_id := v_jobid, command := replace(v_cmd, '''' || v_json || '''', '''' || v_new || ''''));
end $$;


ALTER FUNCTION "security"."pipeline_setting_cron_arg"("p_jobname" "text", "p_key" "text", "p_value" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."pipeline_yield_v1"("p_hours" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "statement_timeout" TO '20s'
    AS $$
declare v_h int := coalesce(p_hours, security.pipeline_num_v1('integration.yield_window_hours', 24)::int); v_since timestamptz; v jsonb; ef record;
begin
  v_since := now() - make_interval(hours => v_h);
  -- CF-247 3 Nov 2026 (direction 09:32 §5): the Enrich fields lane, the items of the tasks that ran in the window
  select count(*) items, count(*) filter (where i.evidence_id is not null or i.storage_path is not null) stored, count(*) filter (where i.state in ('filled', 'review', 'skipped')) settled,
         count(*) filter (where i.value is not null) valued, count(*) filter (where i.state = 'filled') filled, count(*) filter (where i.state = 'review') review,
         count(*) filter (where i.state = 'skipped') skipped, count(*) filter (where i.state = 'failed') failed
    into ef from pipeline.field_enrich_items i
   where i.job_id in (select j.id from pipeline.admin_jobs j where j.kind = 'enrich_fields' and coalesce(j.finished_at, j.updated_at) >= v_since);
  v := jsonb_build_object('window_hours', v_h, 'since', v_since, 'lanes', jsonb_build_array(
    -- scholarships
    jsonb_build_object('lane', 'scholarships', 'label', 'Scholarships', 'stages', jsonb_build_object(
      'invoked', (select jsonb_build_object('calls', count(*), 'failed_calls', count(*) filter (where l.status >= 400 or l.failed > 0)) from pipeline.mode_outcome_ledger l
                   where l.run_at >= v_since and l.mode in ('scholarship_discover', 'scholarship_listing', 'scholarship_read', 'scholarship_ai')),
      'source_accessed', (select count(*) from pipeline.scholarship_discovery_providers d where d.discovered_at >= v_since)
                         + (select count(*) from pipeline.scholarship_listing_pages p where p.read_at >= v_since),
      'pages_discovered', (select count(*) from pipeline.scholarship_page_candidates c where c.found_at >= v_since),
      'read_completely', (select count(*) from pipeline.scholarship_page_candidates c where c.read_at >= v_since and c.read_status = 'read')
                         + (select count(*) from pipeline.scholarship_pages p where p.read_at >= v_since and p.read_status = 'read'),
      'extracted', (select count(*) from pipeline.scholarship_ai_extractions e where e.at >= v_since and e.error is null),
      'accepted_or_held', (select jsonb_build_object('accepted', count(*) filter (where c.admit_status = 'admitted'), 'held', count(*) filter (where c.admit_status = 'matched_held'),
                                                     'rejected', count(*) filter (where c.admit_status in ('rejected', 'duplicate', 'withdrawn', 'skipped')))
                             from pipeline.scholarship_page_candidates c where c.admitted_at >= v_since or (c.admit_status is not null and c.read_at >= v_since)),
      'published', (select count(*) from scholarship.scholarships s where s.updated_at >= v_since and s.publication_status = 'published' and s.lifecycle_status = 'active'),
      'consumer_read_back', (select count(*) from scholarship.scholarships s where s.updated_at >= v_since and s.publication_status = 'published' and s.lifecycle_status = 'active'
                               and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = s.provider_id)))),
    -- course pages (official course links)
    jsonb_build_object('lane', 'course_pages', 'label', 'Course pages and official links', 'stages', jsonb_build_object(
      'invoked', (select jsonb_build_object('calls', count(*), 'failed_calls', count(*) filter (where l.status >= 400 or l.failed > 0)) from pipeline.mode_outcome_ledger l
                   where l.run_at >= v_since and l.mode in ('link_search', 'ai_match', 'read', 'reidentify', 'course_list_read', 'source_find', 'discover')),
      'source_accessed', (select count(*) from pipeline.coverage_course_pages p where p.read_at >= v_since),
      'pages_discovered', (select count(*) from pipeline.coverage_course_pages p where p.bound_at >= v_since),
      'read_completely', (select count(*) from pipeline.coverage_course_pages p where p.read_at >= v_since and p.read_status = 'read'),
      'extracted', (select count(*) from pipeline.coverage_course_pages p where p.l3_handoff_at >= v_since),
      'accepted_or_held', (select jsonb_build_object('accepted', count(*) filter (where k.status = 'active'), 'held', count(*) filter (where k.status = 'unverified'))
                             from catalogue.course_links k where k.link_type = 'official_course' and k.created_at >= v_since)
                          || jsonb_build_object('held_in_layer4', (select count(*) from pipeline.layer4_review_items i where i.status = 'pending' and i.field_code = 'official_course_url' and i.created_at >= v_since)),
      'published', (select count(*) from catalogue.course_links k where k.link_type = 'official_course' and k.status = 'active' and k.is_primary and k.updated_at >= v_since),
      'consumer_read_back', (select count(*) from catalogue.course_links k join search.course_documents d on d.course_id = k.course_id and d.official_course_url = k.url and d.publication_status = 'published'
                              where k.link_type = 'official_course' and k.status = 'active' and k.is_primary and k.updated_at >= v_since))),
    -- academic entry requirements (AER)
    jsonb_build_object('lane', 'aer', 'label', 'Academic entry requirements', 'stages', jsonb_build_object(
      'invoked', (select jsonb_build_object('calls', count(*), 'failed_calls', count(*) filter (where l.status >= 400 or l.failed > 0)) from pipeline.mode_outcome_ledger l
                   where l.run_at >= v_since and l.mode in ('entry_ai', 'entry_inspect')),
      'source_accessed', (select count(*) from pipeline.entry_matrix_sources m where m.read_at >= v_since),
      'pages_discovered', (select count(*) from pipeline.entry_matrix_sources m where m.created_at >= v_since),
      'read_completely', (select count(*) from pipeline.entry_matrix_runs m where m.done_at >= v_since and m.state = 'done'),
      'extracted', (select count(*) from catalogue.provider_entry_matrix x where x.created_at >= v_since) + (select count(*) from catalogue.course_entry_requirements x where x.created_at >= v_since),
      'accepted_or_held', (select jsonb_build_object('accepted', count(*) filter (where x.status = 'active'), 'held', count(*) filter (where x.status in ('proposed', 'unverified')))
                             from catalogue.provider_entry_matrix x where x.updated_at >= v_since),
      'published', (select count(*) from catalogue.provider_entry_matrix x where x.status = 'active' and x.updated_at >= v_since)
                   + (select count(*) from catalogue.course_entry_requirements x where x.status = 'active' and x.updated_at >= v_since),
      'consumer_read_back', (select count(*) from catalogue.provider_entry_matrix x where x.status = 'active' and x.updated_at >= v_since
                               and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = x.provider_id)))),
    -- university descriptions
    jsonb_build_object('lane', 'descriptions', 'label', 'University descriptions', 'stages', jsonb_build_object(
      'invoked', (select jsonb_build_object('calls', count(*), 'failed_calls', count(*) filter (where l.status >= 400 or l.failed > 0)) from pipeline.mode_outcome_ledger l
                   where l.run_at >= v_since and l.mode = 'provider_description'),
      'source_accessed', (select count(*) from pipeline.provider_description_reads r where r.source_captured_at >= v_since),
      'pages_discovered', (select count(*) from pipeline.provider_description_reads r where r.created_at >= v_since and r.source_url is not null),
      'read_completely', (select count(*) from pipeline.provider_description_reads r where r.updated_at >= v_since and r.evidence_id is not null),
      'extracted', (select count(*) from pipeline.provider_description_reads r where r.updated_at >= v_since and r.proposal is not null),
      'accepted_or_held', (select jsonb_build_object('accepted', count(*) filter (where r.state in ('admitted', 'verified')), 'held', count(*) filter (where r.state in ('proposed', 'held')),
                                                     'rejected', count(*) filter (where r.state in ('rejected', 'dead_letter')))
                             from pipeline.provider_description_reads r where r.updated_at >= v_since),
      'published', (select count(*) from pipeline.provider_description_reads r where r.published_at >= v_since),
      'consumer_read_back', (select count(*) from pipeline.provider_description_reads r join catalogue.providers p on p.id = r.provider_id
                              where r.published_at >= v_since and nullif(btrim(p.description), '') is not null and p.publication_status = 'published' and p.lifecycle_status = 'active'))),
    -- Enrich fields (worker mode enrich_ai; the standing gap queue and operator tasks). Consumer read-back is not traced per item.
    jsonb_build_object('lane', 'enrich_fields', 'label', 'Enrich fields (AI reads)', 'stages', jsonb_build_object(
      'invoked', (select jsonb_build_object('calls', count(*), 'failed_calls', count(*) filter (where l.status >= 400 or l.failed > 0)) from pipeline.mode_outcome_ledger l
                   where l.run_at >= v_since and l.mode = 'enrich_ai'),
      'source_accessed', ef.stored,
      'pages_discovered', null,
      'read_completely', ef.settled,
      'extracted', ef.valued,
      'accepted_or_held', jsonb_build_object('accepted', ef.filled, 'held', ef.review, 'not_stated', ef.skipped, 'failed', ef.failed),
      'published', ef.filled,
      'consumer_read_back', null))));
  return v;
end $$;


ALTER FUNCTION "security"."pipeline_yield_v1"("p_hours" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."place_presentable"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case when p is null then null
              when p ~ '[a-z]' or p !~ '[A-Z]' then btrim(p)
              else regexp_replace(initcap(btrim(p)),'\mMc([a-z])','Mc\1','g') end
$$;


ALTER FUNCTION "security"."place_presentable"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."plan_empty_cycles_v1"("p_provider" "uuid", "p_missing" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int := security.pipeline_num_v1('plans.empty_cycles_max', 0)::int; v_ids uuid[]; v_outs text[]; v_last record; v_in jsonb;
begin
  if v_n <= 0 then return null; end if;
  select array_agg(id order by created_at desc), array_agg(o order by created_at desc) into v_ids, v_outs
    from (select x.id, x.created_at, coalesce(x.outcome, security.plan_outcome_compute_v1(x.id)->>'outcome') o
            from pipeline.enrich_plan_runs x where x.provider_id = p_provider and x.state in ('done', 'failed', 'cancelled')
           order by x.created_at desc limit v_n) z;
  if coalesce(cardinality(v_ids), 0) < v_n then return null; end if;
  if exists (select 1 from unnest(v_outs) o join pipeline.ops_outcome_codes k on k.code = o where k.counts_as_movement) or array_position(v_outs, null) is not null then return null; end if;
  select x.id, coalesce(x.finished_at, x.created_at) at, (x.estimate->>'missing')::numeric missing into v_last from pipeline.enrich_plan_runs x where x.id = v_ids[1];
  if v_last.at < now() - make_interval(days => security.pipeline_num_v1('plans.empty_cycles_quiet_days', 14)::int) then return null; end if;
  if p_missing is not null and v_last.missing is not null and p_missing >= v_last.missing + security.pipeline_num_v1('plans.replan_min_new_gaps', 5) then return null; end if;
  v_in := security.enrich_plan_inputs_v1(p_provider);
  if coalesce((v_in->>'evidence_new')::int, 0) > 0 or coalesce((v_in->>'central_new')::boolean, false) then return null; end if;
  return jsonb_build_object('plans', to_jsonb(v_ids), 'outcomes', to_jsonb(v_outs), 'since', v_last.at,
    'reason', 'the last ' || v_n || ' plans moved no data (' || array_to_string(v_outs, ', ') || ') and no new verified evidence, central pages or missing values since '
              || to_char(v_last.at at time zone 'Australia/Melbourne', 'DD Mon HH24:MI') || '; proposed again when they change');
end $$;


ALTER FUNCTION "security"."plan_empty_cycles_v1"("p_provider" "uuid", "p_missing" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."plan_outcome_compute_v1"("p_run" "uuid", "p_final" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.enrich_plan_runs%rowtype; e jsonb; v_o text; v_m boolean; v_jo jsonb; v_steps jsonb := '[]'::jsonb; v_moved boolean := false; v_out text;
begin
  select * into r from pipeline.enrich_plan_runs x where x.id = p_run;
  if r.id is null then return null; end if;
  for e in select x from jsonb_array_elements(coalesce(r.steps, '[]'::jsonb)) x loop
    v_o := null; v_m := null;
    if e->'ref'->>'kind' = 'job' and nullif(e->'ref'->>'id', '') is not null then
      v_jo := security.job_outcome_compute_v1((e->'ref'->>'id')::uuid);
      v_o := v_jo->>'outcome'; v_m := (v_jo->>'moved')::boolean;
      if v_o is null and e->>'status' in ('failed', 'timed_out', 'cancelled') then v_o := 'failed_retryable'; end if;
    elsif e->'ref'->>'kind' = 'onboarding' then
      select case when o.status in ('waiting_admit', 'done', 'scholarships') then 'succeeded_with_result'
                  when o.status = 'stopped' then case when security.ops_hold_outcome_v1(o.stop_reason) = 'blocked_evidence' or o.stop_reason in ('too_few_pages', 'nothing_ready') then 'blocked_evidence' else 'failed_remediation' end
                  when o.status = 'cancelled' then 'not_needed' end,
             o.status in ('waiting_admit', 'done', 'scholarships')
        into v_o, v_m from pipeline.provider_onboarding o where o.id = nullif(e->'ref'->>'id', '')::uuid;
    else
      v_o := case e->>'status' when 'not_needed' then 'not_needed' when 'cancelled' then 'not_needed' when 'waiting' then 'deferred_dependency'
                  when 'skipped' then case when coalesce(e->>'note', '') like 'no room in the % share%' then 'blocked_policy'
                                           when coalesce(e->>'note', '') like 'Deferred:%' then 'deferred_dependency' else 'blocked_evidence' end
                  when 'failed' then case when security.ops_error_retryable_v1(e->>'note') then 'failed_retryable' else 'failed_remediation' end end;
    end if;
    v_moved := v_moved or coalesce(v_m, false);
    if e->>'status' <> 'person' then v_steps := v_steps || jsonb_build_object('step', e->>'step', 'status', e->>'status', 'outcome', v_o, 'moved', v_m); end if;
  end loop;
  if v_moved then v_out := 'succeeded_with_result';
  elsif r.state in ('queued', 'running') and not p_final then v_out := null;
  else
    select o into v_out from unnest(array['failed_retryable', 'failed_remediation', 'blocked_policy', 'blocked_evidence', 'deferred_dependency', 'succeeded_no_movement']) with ordinality u(o, n)
     where exists (select 1 from jsonb_array_elements(v_steps) s where s->>'outcome' = u.o) order by n limit 1;
    v_out := coalesce(v_out, case when jsonb_array_length(v_steps) > 0 and not exists (select 1 from jsonb_array_elements(v_steps) s where coalesce(s->>'outcome', '') <> 'not_needed')
                                  then 'not_needed' else 'succeeded_no_movement' end);
  end if;
  return jsonb_build_object('outcome', v_out, 'moved', v_moved, 'legacy', case when v_out is null then null when v_moved then 'moved' when v_out = 'not_needed' then 'not_needed' else 'no_movement' end,
                            'steps', v_steps);
end $$;


ALTER FUNCTION "security"."plan_outcome_compute_v1"("p_run" "uuid", "p_final" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."plan_outcome_record_v1"("p_run" "uuid", "p_basis" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  if security.pipeline_num_v1('ops.outcome_on', 0) < 1 then return null; end if;
  v := security.plan_outcome_compute_v1(p_run);
  if v is null or v->>'outcome' is null then return null; end if;
  update pipeline.enrich_plan_runs set outcome = v->>'outcome',
         outcome_detail = jsonb_build_object('moved', v->'moved', 'steps', v->'steps', 'basis', p_basis, 'at', now())
   where id = p_run and outcome is distinct from v->>'outcome';
  return v->>'outcome';
exception when others then
  raise notice 'plan outcome not recorded for %: %', p_run, sqlerrm;
  return null;
end $$;


ALTER FUNCTION "security"."plan_outcome_record_v1"("p_run" "uuid", "p_basis" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."plan_outcomes_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 IQ-00066: enrichment plans finished in plans.outcome_window_hours by outcome (a done plan with no step done moved no data), the
  -- steps that were not needed, and the tasks that ended not needed
  with w as (select now() - make_interval(hours => security.pipeline_num_v1('plans.outcome_window_hours', 24)::int) since),
  r as (select x.mode, x.state, coalesce(case when x.outcome is null then null when (select k.counts_as_movement from pipeline.ops_outcome_codes k where k.code = x.outcome) then 'moved'
                       when x.outcome = 'not_needed' then 'not_needed' else 'no_movement' end,  -- CF-247 ops D: the reconciled outcome first
                  x.actual->>'outcome', security.plan_run_outcome_v1(x.steps)) outcome, x.steps
          from pipeline.enrich_plan_runs x, w where x.finished_at >= w.since and x.state = 'done')
  select jsonb_build_object('window_since', (select since from w),
    'plans_done', (select count(*) from r),
    'moved', (select count(*) from r where outcome = 'moved'),
    'not_needed', (select count(*) from r where outcome = 'not_needed'),
    'no_movement', (select count(*) from r where outcome = 'no_movement'),
    'auto', jsonb_build_object('moved', (select count(*) from r where mode = 'auto' and outcome = 'moved'),
                               'not_needed', (select count(*) from r where mode = 'auto' and outcome = 'not_needed'),
                               'no_movement', (select count(*) from r where mode = 'auto' and outcome = 'no_movement')),
    'steps_not_needed', (select coalesce(jsonb_object_agg(k, n), '{}'::jsonb) from (select s->>'step' k, count(*) n from r, jsonb_array_elements(r.steps) s
                                                                                     where s->>'status' = 'not_needed' group by 1) z),
    'by_outcome', (select coalesce(jsonb_object_agg(o, n), '{}'::jsonb) from (select coalesce(x2.outcome, 'not reconciled') o, count(*) n from pipeline.enrich_plan_runs x2, w
                                                                            where x2.finished_at >= w.since and x2.state = 'done' group by 1) z),  -- CF-247 ops D
    'tasks_not_needed', (select count(*) from pipeline.admin_jobs j, w where j.finished_at >= w.since and j.state = 'cancelled' and j.result->>'end_state' = 'not_needed'))
$$;


ALTER FUNCTION "security"."plan_outcomes_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."plan_outcomes_v1"() IS 'CF-247 IQ-00066: enrichment plans finished in plans.outcome_window_hours by outcome (moved, not_needed, no_movement), steps not needed and tasks ended not needed; returned by public.admin_pipeline_yield as plan_outcomes';



CREATE OR REPLACE FUNCTION "security"."plan_run_outcome_v1"("p_steps" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  -- CF-247 IQ-00066: a finished plan moved data only when a step was done; a plan whose steps that ran were all not needed is not_needed
  select case when exists (select 1 from jsonb_array_elements(coalesce(p_steps, '[]'::jsonb)) x where x->>'status' = 'done') then 'moved'
              when exists (select 1 from jsonb_array_elements(coalesce(p_steps, '[]'::jsonb)) x where x->>'status' = 'not_needed')
               and not exists (select 1 from jsonb_array_elements(coalesce(p_steps, '[]'::jsonb)) x where x->>'status' not in ('not_needed', 'person')) then 'not_needed'
              else 'no_movement' end
$$;


ALTER FUNCTION "security"."plan_run_outcome_v1"("p_steps" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."plan_run_outcome_v1"("p_steps" "jsonb") IS 'CF-247 IQ-00066: a finished enrichment plan''s outcome from its steps: moved (a step done), not_needed (every step that ran was not needed) or no_movement';



CREATE OR REPLACE FUNCTION "security"."plan_stalled_onboarding_v1"("p_provider" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o record; v_quiet int := security.pipeline_num_v1('plans.stalled_onboarding_quiet_days', 30)::int;
begin
  if security.pipeline_num_v1('plans.stalled_onboarding_hold', 1) < 1 then return null; end if;
  select s.status, s.stop_reason, coalesce(s.finished_at, s.updated_at) at into o
    from pipeline.provider_onboarding s where s.provider_id = p_provider order by s.created_at desc limit 1;
  if o.status is distinct from 'stopped' or o.at is null or coalesce(o.stop_reason, '') = '' then return null; end if;
  if o.at < now() - make_interval(days => v_quiet) then return null; end if;
  if not exists (select 1 from pipeline.platform_toolset_settings w cross join lateral jsonb_array_elements_text(case when jsonb_typeof(w.value) = 'array' then w.value else '[]'::jsonb end) k(t)
                  where w.toolset_key = 'pipeline' and w.key = 'plans.retry_waits_for_change' and position(lower(k.t) in lower(o.stop_reason)) > 0) then return null; end if;
  if exists (select 1 from catalogue.courses c where c.provider_id = p_provider and c.lifecycle_status = 'active' and c.created_at > o.at) then return null; end if;
  if exists (select 1 from pipeline.coverage_course_pages g where g.provider_id = p_provider and g.evidence_id is not null and g.read_status = 'read' and g.read_at > o.at) then return null; end if;
  if exists (select 1 from pipeline.provider_central_search s where s.provider_id = p_provider and s.state = 'done' and s.searched_at > o.at) then return null; end if;
  return jsonb_build_object('stop_reason', o.stop_reason, 'stopped_at', o.at,
    'reason', 'onboarding stopped (' || replace(o.stop_reason, '_', ' ') || ') on ' || to_char(o.at at time zone 'Australia/Melbourne', 'DD Mon HH24:MI')
              || ' and no course, course page or central search has changed since; proposed again when one does, or after ' || v_quiet || ' days');
end $$;


ALTER FUNCTION "security"."plan_stalled_onboarding_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."plan_stalled_onboarding_v1"("p_provider" "uuid") IS 'CF-247 ENG IQ-00072: reason the automatic planner does not offer Find course pages and Build the adapter (stuck onboarding, nothing changed), or null.';



CREATE OR REPLACE FUNCTION "security"."plan_step_dependency_v1"("p_run" "uuid", "p_step" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.enrich_plan_runs%rowtype; v_n int; v_blk jsonb;
begin
  select * into r from pipeline.enrich_plan_runs x where x.id = p_run;
  if r.id is null or coalesce((p_step->>'person')::boolean, false) then return null; end if;
  if p_step->>'step' = 'pages' and r.mode = 'auto' and security.pipeline_num_v1('plans.lane_backlog_wait_on', 0) >= 1 then
    select count(*) into v_n from pipeline.course_link_search s where s.provider_id = r.provider_id and s.state in ('queued', 'sent');
    if v_n > 0 then
      v_blk := security.link_search_block_v1(r.provider_id, null);
      return jsonb_build_object('code', 'lane_backlog', 'outcome', 'deferred_dependency', 'queued', v_n, 'hold', v_blk->>'code',
        'reason', v_n || ' course search(es) of this provider are still queued in the course page search lane'
                  || coalesce(' (' || (v_blk->>'words') || ')', '') || '; the step starts once they are searched, so none is paid twice');
    end if;
  elsif p_step->>'step' = 'fields' and security.pipeline_num_v1('plans.step_dependency_on', 0) >= 1
        and exists (select 1 from jsonb_array_elements(r.steps) x where x->>'step' = 'pages' and x->>'status' in ('pending', 'waiting', 'running')) then
    return jsonb_build_object('code', 'step_dependency', 'outcome', 'deferred_dependency', 'after', 'pages',
                              'reason', 'waits for this plan''s Find course pages step, whose pages it reads');
  end if;
  return null;
end $$;


ALTER FUNCTION "security"."plan_step_dependency_v1"("p_run" "uuid", "p_step" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."plan_step_restart_v1"("p_step" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 IQ-00064: when the governed re-plan (security.enrich_plan_inputs_v1) may retry an ended step, or that it waits for a change
  select jsonb_build_object(
    'retry_on', security.pipeline_num_v1('plans.replan_on_retry', 0) >= 1,
    'after', coalesce((p_step->>'finished_at')::timestamptz, now()) + make_interval(hours => security.pipeline_num_v1('plans.retry_after_hours', 6)::int),
    'waits_for_change', exists (select 1 from pipeline.platform_toolset_settings w cross join lateral jsonb_array_elements_text(coalesce(w.value, '[]'::jsonb)) k(t)
                                 where w.toolset_key = 'pipeline' and w.key = 'plans.retry_waits_for_change' and position(lower(k.t) in lower(coalesce(p_step->>'note', ''))) > 0),
    'retry_max', security.pipeline_num_v1('plans.step_retry_max', 3))
$$;


ALTER FUNCTION "security"."plan_step_restart_v1"("p_step" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."plan_step_restart_v1"("p_step" "jsonb") IS 'CF-247 IQ-00064: an ended plan step''s restart eligibility as security.enrich_plan_inputs_v1 judges it (re-plan on retry on, retry after plans.retry_after_hours from the end, or waits for a change by plans.retry_waits_for_change), kept on the step';



CREATE OR REPLACE FUNCTION "security"."plan_step_work_v1"("p_provider" "uuid", "p_step" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 IQ-00066: whether an enrichment plan step has eligible work now (plans.step_needs_work_on). Scholarships answers from the
  -- scholarship reader's gates; the other steps keep their own rules in security.enrich_plan_v1 and are always answered as having work.
  select case p_step when 'scholarships' then security.scholarship_scan_work_v1(array[p_provider]) else jsonb_build_object('work', true) end
$$;


ALTER FUNCTION "security"."plan_step_work_v1"("p_provider" "uuid", "p_step" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."plan_step_work_v1"("p_provider" "uuid", "p_step" "text") IS 'CF-247 IQ-00066: whether an enrichment plan step has eligible work now, with the reason when it has none (scholarships: security.scholarship_scan_work_v1)';



CREATE OR REPLACE FUNCTION "security"."plan_unfinished_done_v1"() RETURNS TABLE("kind" "text", "run_id" "uuid", "step_no" integer, "step" "text", "job_id" "uuid", "job_kind" "text", "provider_id" "uuid", "unprocessed" numeric, "finished_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 IQ-00064: plan steps done while their task ended done with work unfinished, and tasks of tasks.hold_kinds that ended done with
  -- work unfinished after the IQ-00064 reconciliation (earlier ones were reconciled or are not plan work)
  with k as (select array(select jsonb_array_elements_text(coalesce((select s.value from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'tasks.hold_kinds'),
                                                                   '["course_page_find", "scholarship_provider_scan", "provider_fill"]'::jsonb))) kinds,
                    now() - make_interval(days => security.pipeline_num_v1('tasks.unfinished_lookback_days', 7)::int) since,
                    coalesce((select max(e.created_at) from pipeline.admin_control_events e where e.action = 'iq64_plan_step_reconcile'), '-infinity') cut),
       u as (select j.*, (j.result->>'total')::numeric - (j.result->>'done')::numeric n from pipeline.admin_jobs j, k
              where j.kind = any (k.kinds) and j.state = 'done' and jsonb_typeof(j.result->'done') = 'number' and jsonb_typeof(j.result->'total') = 'number'
                and (j.result->>'done')::numeric < (j.result->>'total')::numeric),
       st as (select 'step'::text kind, r.id run_id, (e.o - 1)::int step_no, e.x->>'step' step, u.id job_id, u.kind job_kind, r.provider_id, u.n, u.finished_at
                from pipeline.enrich_plan_runs r cross join k cross join lateral jsonb_array_elements(r.steps) with ordinality e(x, o)
                join u on u.id = nullif(e.x->'ref'->>'id', '')::uuid
               where r.created_at >= k.since and e.x->>'status' = 'done' and e.x->'ref'->>'kind' = 'job')
  select * from st
  union all
  select 'task', nullif(u.args->>'plan_run', '')::uuid, null, null, u.id, u.kind, nullif(u.args->>'provider_id', '')::uuid, u.n, u.finished_at
    from u, k where u.finished_at >= greatest(k.since, k.cut) and not exists (select 1 from st where st.job_id = u.id)
$$;


ALTER FUNCTION "security"."plan_unfinished_done_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."plan_unfinished_done_v1"() IS 'CF-247 IQ-00064: plan steps done while their task ended done with work unfinished, and tasks of tasks.hold_kinds that ended done with work unfinished after the reconciliation (last tasks.unfinished_lookback_days); the integration check plan_unfinished_done:plans';



CREATE OR REPLACE FUNCTION "security"."platform_alerts_add_v1"("p_issue_id" "uuid", "p_check_key" "text", "p_kind" "text", "p_severity" "text", "p_title" "text", "p_body" "text", "p_dedupe" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_on boolean := coalesce((security.toolset_setting('pipeline', 'alerts.delivery_enabled') #>> '{}')::boolean, false);
        v_test boolean := coalesce((security.toolset_setting('pipeline', 'alerts.test_mode') #>> '{}')::boolean, false); v_id bigint;
begin
  insert into pipeline.platform_alerts(issue_id, check_key, kind, severity, title, body, status, dedupe_key)
  values (p_issue_id, p_check_key, p_kind, p_severity,
          left(case when v_test or p_kind = 'test' then '[TEST] ' else '' end || p_title, 300), left(p_body, 1500),
          case when v_on then 'pending' else 'held' end, p_dedupe)
  on conflict (dedupe_key) do nothing returning id into v_id;
  return v_id is not null;
end $$;


ALTER FUNCTION "security"."platform_alerts_add_v1"("p_issue_id" "uuid", "p_check_key" "text", "p_kind" "text", "p_severity" "text", "p_title" "text", "p_body" "text", "p_dedupe" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_alerts_confirm_v1"("p_ids" bigint[], "p_ok" boolean DEFAULT true, "p_error" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int; v_max int := security.pipeline_num_v1('alerts.max_attempts', 5)::int; v_retry numeric := security.pipeline_num_v1('alerts.retry_minutes', 10);
begin
  if p_ok then
    update pipeline.platform_alerts set status = 'sent', sent_at = now(), lease_until = null where id = any (p_ids) and status = 'sending';
  else
    update pipeline.platform_alerts a set status = case when a.attempts >= v_max then 'failed' else 'pending' end, lease_until = null, last_error = left(coalesce(p_error, 'not delivered'), 300),
           next_attempt_at = now() + make_interval(mins => (v_retry * power(2, greatest(a.attempts - 1, 0)))::int)
     where a.id = any (p_ids) and a.status = 'sending';
  end if;
  get diagnostics v_n = row_count;
  return jsonb_build_object('updated', v_n, 'delivered', p_ok);
end $$;


ALTER FUNCTION "security"."platform_alerts_confirm_v1"("p_ids" bigint[], "p_ok" boolean, "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_alerts_evaluate_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_min int := security.pipeline_num_v1('alerts.min_severity', 3)::int;
        v_confirm int := security.pipeline_num_v1('alerts.confirm_minutes', 15)::int;
        v_cool int := security.pipeline_num_v1('alerts.cooldown_minutes', 60)::int;
        v_remind int := security.pipeline_num_v1('alerts.reminder_hours', 12)::int;
        v_max int := security.pipeline_num_v1('alerts.max_attempts', 5)::int;
        v_retry numeric := security.pipeline_num_v1('alerts.retry_minutes', 10);
        v_recover boolean := coalesce((security.toolset_setting('pipeline', 'alerts.recovery_notice') #>> '{}')::boolean, true);
        v_on boolean := coalesce((security.toolset_setting('pipeline', 'alerts.delivery_enabled') #>> '{}')::boolean, false);
        v_hook boolean := coalesce((security.toolset_setting('pipeline', 'alerts.webhook_enabled') #>> '{}')::boolean, false);
        i record; v_lkind text; v_lsev text; v_lat timestamptz; v_raised int := 0; v_esc int := 0; v_rem int := 0; v_rec int := 0; v_supp int := 0; v_exp int := 0; v_hook_out jsonb;
        v_word text; v_body text;
begin
  -- 1. a delivery not confirmed before its lease ended goes back for another try, or is marked failed after the last attempt
  update pipeline.platform_alerts a set status = case when a.attempts >= v_max then 'failed' else 'pending' end,
         last_error = coalesce(a.last_error, 'delivery not confirmed before the lease ended'), lease_until = null,
         next_attempt_at = now() + make_interval(mins => (v_retry * power(2, greatest(a.attempts - 1, 0)))::int)
   where a.status = 'sending' and a.lease_until < now() and a.net_request_id is null;
  get diagnostics v_exp = row_count;
  -- 2. open, unacknowledged issues at or above the alert severity that have stayed open long enough
  for i in select p.id, p.check_key, p.severity, p.area, p.title, p.detail, p.first_seen, p.occurrences
             from pipeline.platform_issues p
            where p.resolved_at is null and p.acknowledged_at is null
              and (case p.severity when 'critical' then 3 when 'warning' then 2 else 1 end) >= v_min
              and p.first_seen <= now() - make_interval(mins => v_confirm)
            order by p.first_seen loop
    v_lkind := null; v_lsev := null; v_lat := null;
    select a.kind, a.severity, a.created_at into v_lkind, v_lsev, v_lat from pipeline.platform_alerts a
     where a.issue_id = i.id and a.kind in ('raised', 'escalated', 'reminder') order by a.created_at desc limit 1;
    v_word := case i.severity when 'critical' then 'Critical' when 'warning' then 'Warning' else 'Notice' end;
    v_body := 'Area: ' || i.area || '. First seen ' || to_char(i.first_seen at time zone 'Australia/Melbourne', 'DD Mon HH24:MI') || ' (Melbourne), seen '
              || i.occurrences || ' time(s).' || coalesce(' Next step: ' || (i.detail ->> 'next_step'), '') || coalesce(' Where: ' || (i.detail ->> 'resolve'), '')
              || ' Acknowledge it on PIM Admin › Platform health to stop reminders.';
    if v_lkind is null then
      -- deduplication: the same check alerted within the quiet period (an issue that closed and opened again) is not alerted again
      if exists (select 1 from pipeline.platform_alerts a where a.check_key = i.check_key and a.kind in ('raised', 'escalated', 'reminder')
                  and a.created_at > now() - make_interval(mins => v_cool)) then
        v_supp := v_supp + 1; continue;
      end if;
      if security.platform_alerts_add_v1(i.id, i.check_key, 'raised', i.severity, '[StudySearch] ' || v_word || ': ' || i.title, v_body, i.id::text || ':raised') then v_raised := v_raised + 1; end if;
    elsif v_lsev <> 'critical' and i.severity = 'critical' then
      if security.platform_alerts_add_v1(i.id, i.check_key, 'escalated', i.severity, '[StudySearch] Now critical: ' || i.title, v_body, i.id::text || ':escalated') then v_esc := v_esc + 1; end if;
    elsif v_remind > 0 and v_lat < now() - make_interval(hours => v_remind) then
      if security.platform_alerts_add_v1(i.id, i.check_key, 'reminder', i.severity, '[StudySearch] Still open: ' || i.title, v_body,
                                         i.id::text || ':reminder:' || to_char(now(), 'YYYYMMDDHH24MI')) then v_rem := v_rem + 1; end if;
    end if;
  end loop;
  -- 3. one recovery notice for an alerted issue that has closed
  if v_recover then
    for i in select p.id, p.check_key, p.severity, p.title, p.first_seen, p.resolved_at from pipeline.platform_issues p
              where p.resolved_at is not null and p.resolved_at > now() - interval '1 day'  -- fixed: recovery notices look back one day
                and exists (select 1 from pipeline.platform_alerts a where a.issue_id = p.id and a.kind in ('raised', 'escalated', 'reminder'))
                and not exists (select 1 from pipeline.platform_alerts a where a.issue_id = p.id and a.kind = 'recovered') loop
      if security.platform_alerts_add_v1(i.id, i.check_key, 'recovered', 'info', '[StudySearch] Recovered: ' || i.title,
           'Closed ' || to_char(i.resolved_at at time zone 'Australia/Melbourne', 'DD Mon HH24:MI') || ' (Melbourne), open for '
           || round(extract(epoch from i.resolved_at - i.first_seen) / 60) || ' minutes. No action needed.', i.id::text || ':recovered') then v_rec := v_rec + 1; end if;
    end loop;
  end if;
  -- 4. webhook delivery, only with delivery and the webhook switched on
  if v_on and v_hook then v_hook_out := security.platform_alerts_webhook_v1(); end if;
  return jsonb_build_object('raised', v_raised, 'escalated', v_esc, 'reminders', v_rem, 'recovered', v_rec, 'suppressed', v_supp, 'lease_expired', v_exp,
                            'delivery', case when not v_on then 'off (recorded as held)' when v_hook then 'webhook' else 'scheduled task' end, 'webhook', v_hook_out);
end $$;


ALTER FUNCTION "security"."platform_alerts_evaluate_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_alerts_take_v1"("p_via" "text" DEFAULT 'scheduled task'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  if not coalesce((security.toolset_setting('pipeline', 'alerts.delivery_enabled') #>> '{}')::boolean, false) then
    return jsonb_build_object('count', 0, 'alerts', '[]'::jsonb, 'delivery', 'off: alerts are recorded on Platform health only');
  end if;
  if coalesce((security.toolset_setting('pipeline', 'alerts.webhook_enabled') #>> '{}')::boolean, false) then
    return jsonb_build_object('count', 0, 'alerts', '[]'::jsonb, 'delivery', 'webhook');
  end if;
  with t as (update pipeline.platform_alerts a set status = 'sending', attempts = a.attempts + 1, sent_via = p_via,
                    lease_until = now() + interval '15 minutes'  -- fixed: delivery lease
              where a.status = 'pending' and a.next_attempt_at <= now() returning a.*)
  select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'kind', t.kind, 'severity', t.severity, 'title', t.title, 'body', t.body, 'raised_at', t.created_at) order by t.created_at), '[]'::jsonb)
    into v from t;
  return jsonb_build_object('count', jsonb_array_length(v), 'alerts', v, 'confirm', 'select security.platform_alerts_confirm_v1(<ids>, true)');
end $$;


ALTER FUNCTION "security"."platform_alerts_take_v1"("p_via" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_alerts_webhook_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_url text; a record; r record; v_id bigint; v_sent int := 0; v_ok int := 0; v_bad int := 0;
        v_max int := security.pipeline_num_v1('alerts.max_attempts', 5)::int; v_retry numeric := security.pipeline_num_v1('alerts.retry_minutes', 10);
begin
  select s.decrypted_secret into v_url from vault.decrypted_secrets s where s.name = 'studysearch_alert_webhook_url';
  if v_url is null then return jsonb_build_object('webhook', 'no address stored'); end if;
  -- reconcile earlier posts from their pg_net responses
  for a in select x.id, x.attempts, x.net_request_id, x.lease_until from pipeline.platform_alerts x where x.status = 'sending' and x.net_request_id is not null loop
    select h.status_code, h.timed_out, h.error_msg into r from net._http_response h where h.id = a.net_request_id;
    if found and r.status_code between 200 and 299 then
      update pipeline.platform_alerts set status = 'sent', sent_at = now(), lease_until = null where id = a.id; v_ok := v_ok + 1;
    elsif found or a.lease_until < now() then
      update pipeline.platform_alerts set status = case when a.attempts >= v_max then 'failed' else 'pending' end, lease_until = null, net_request_id = null,
             last_error = coalesce('HTTP ' || r.status_code, case when r.timed_out then 'timed out' end, r.error_msg, 'no response'),
             next_attempt_at = now() + make_interval(mins => (v_retry * power(2, greatest(a.attempts - 1, 0)))::int)
       where id = a.id;
      v_bad := v_bad + 1;
    end if;
  end loop;
  for a in select x.* from pipeline.platform_alerts x where x.status = 'pending' and x.next_attempt_at <= now() order by x.created_at
            limit security.pipeline_num_v1('alerts.webhook_batch', 20)::int loop
    v_id := net.http_post(url := v_url,
              body := jsonb_build_object('text', a.title || E'\n' || a.body, 'source', 'StudySearch', 'alert_id', a.id, 'kind', a.kind, 'severity', a.severity,
                                         'check', a.check_key, 'title', a.title, 'body', a.body, 'created_at', a.created_at),
              params := '{}'::jsonb, headers := jsonb_build_object('Content-Type', 'application/json'),
              timeout_milliseconds := 5000);  -- fixed: API time-out
    update pipeline.platform_alerts set status = 'sending', sent_via = 'webhook', net_request_id = v_id, attempts = attempts + 1,
           lease_until = now() + interval '15 minutes'  -- fixed: delivery lease
     where id = a.id;
    v_sent := v_sent + 1;
  end loop;
  return jsonb_build_object('posted', v_sent, 'confirmed', v_ok, 'retrying', v_bad);
end $$;


ALTER FUNCTION "security"."platform_alerts_webhook_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_capacity_snapshot_internal"("p_environment" "text" DEFAULT 'pilot'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'storage', 'public'
    AS $_$
declare
  v_db bigint;
  v_temp_bytes bigint;
  v_temp_files bigint;
  v_obj_count bigint;
  v_obj_bytes bigint;
  v_evidence_count bigint;
  v_unlinked_raw bigint;
  v_duplicate_unlinked bigint;
  v_reconciled_orphans bigint;
  v_orphans bigint;
  v_direct_virtual_refs bigint;
  v_reconciled_legacy_refs bigint;
  v_virtual_refs bigint;
  v_failed_raw bigint;
  v_failed bigint;
  v_largest jsonb;
  v_evidence_policy jsonb;
  v_policy jsonb;
  v_severity text := 'ok';
  v_integrity_count bigint;
  v_evidence_pct numeric;
  v_prev_temp_bytes bigint;
  v_prev_observed_at timestamptz;
  v_temp_delta bigint;
begin
  if p_environment not in ('pilot','production') then
    raise exception 'invalid environment';
  end if;

  select pg_database_size(current_database()) into v_db;
  select coalesce(temp_bytes,0),coalesce(temp_files,0)
    into v_temp_bytes,v_temp_files
  from pg_stat_database where datname=current_database();

  select count(*),
         coalesce(sum(case when coalesce(metadata->>'size','') ~ '^[0-9]+$'
                           then (metadata->>'size')::bigint else 0 end),0)
    into v_obj_count,v_obj_bytes
  from storage.objects
  where bucket_id='evidence' and not is_delete_marker;

  select count(*) into v_evidence_count
  from pipeline.evidence_artifacts;

  select count(*) into v_unlinked_raw
  from storage.objects o
  where o.bucket_id='evidence'
    and not o.is_delete_marker
    and not exists (
      select 1 from pipeline.evidence_artifacts e
      where e.storage_path in (o.name, 'evidence/'||o.name)
    );

  select count(*) into v_duplicate_unlinked
  from storage.objects o
  where o.bucket_id='evidence'
    and not o.is_delete_marker
    and not exists (
      select 1 from pipeline.evidence_artifacts e
      where e.storage_path in (o.name, 'evidence/'||o.name)
    )
    and coalesce(o.metadata->>'eTag','')<>''
    and coalesce(o.metadata->>'size','') ~ '^[0-9]+$'
    and exists (
      select 1
      from storage.objects retained
      where retained.bucket_id='evidence'
        and not retained.is_delete_marker
        and retained.id<>o.id
        and retained.metadata->>'eTag'=o.metadata->>'eTag'
        and retained.metadata->>'size'=o.metadata->>'size'
        and exists (
          select 1 from pipeline.evidence_artifacts e
          where e.storage_path=retained.name or e.storage_path=('evidence/'||retained.name)
        )
    );

  select count(*) into v_reconciled_orphans
  from storage.objects o
  join pipeline.evidence_lineage_reconciliations r
    on r.target_kind='storage_object'
   and r.reconciliation_class='historical_orphan_explained'
   and r.storage_path=o.name
  where o.bucket_id='evidence'
    and not o.is_delete_marker
    and not exists (
      select 1 from pipeline.evidence_artifacts e
      where e.storage_path in (o.name, 'evidence/'||o.name)
    )
    and not (
      coalesce(o.metadata->>'eTag','')<>''
      and coalesce(o.metadata->>'size','') ~ '^[0-9]+$'
      and exists (
        select 1 from storage.objects retained
        where retained.bucket_id='evidence'
          and not retained.is_delete_marker
          and retained.id<>o.id
          and retained.metadata->>'eTag'=o.metadata->>'eTag'
          and retained.metadata->>'size'=o.metadata->>'size'
          and exists (
            select 1 from pipeline.evidence_artifacts e
            where e.storage_path=retained.name or e.storage_path=('evidence/'||retained.name)
          )
      )
    );

  v_orphans:=greatest(v_unlinked_raw-v_duplicate_unlinked-v_reconciled_orphans,0);

  select count(*) into v_direct_virtual_refs
  from pipeline.evidence_artifacts e
  where nullif(btrim(e.storage_path),'') is not null
    and e.storage_path ~ '^[A-Za-z][A-Za-z0-9+.-]*://';

  select count(*) into v_reconciled_legacy_refs
  from pipeline.evidence_artifacts e
  join pipeline.evidence_lineage_reconciliations r
    on r.target_kind='evidence_artifact'
   and r.reconciliation_class='legacy_virtual_reference'
   and r.evidence_id=e.id
  where nullif(btrim(e.storage_path),'') is not null
    and e.storage_path !~ '^[A-Za-z][A-Za-z0-9+.-]*://'
    and not exists (
      select 1 from storage.objects o
      where o.bucket_id='evidence'
        and not o.is_delete_marker
        and (o.name in (e.storage_path, regexp_replace(e.storage_path,'^evidence/','')))
    );

  v_virtual_refs:=v_direct_virtual_refs+v_reconciled_legacy_refs;

  select count(*) into v_failed_raw
  from pipeline.evidence_artifacts e
  where nullif(btrim(e.storage_path),'') is not null
    and e.storage_path !~ '^[A-Za-z][A-Za-z0-9+.-]*://'
    and not exists (
      select 1 from storage.objects o
      where o.bucket_id='evidence'
        and not o.is_delete_marker
        and (o.name in (e.storage_path, regexp_replace(e.storage_path,'^evidence/','')))
    );

  select count(*) into v_failed
  from pipeline.evidence_artifacts e
  where nullif(btrim(e.storage_path),'') is not null
    and e.storage_path !~ '^[A-Za-z][A-Za-z0-9+.-]*://'
    and not exists (
      select 1 from storage.objects o
      where o.bucket_id='evidence'
        and not o.is_delete_marker
        and (o.name in (e.storage_path, regexp_replace(e.storage_path,'^evidence/','')))
    )
    and not exists (
      select 1 from pipeline.evidence_lineage_reconciliations r
      where r.target_kind='evidence_artifact'
        and r.reconciliation_class='legacy_virtual_reference'
        and r.evidence_id=e.id
    );

  v_integrity_count:=greatest(v_orphans,v_failed);

  select coalesce(jsonb_agg(jsonb_build_object(
           'schema',schema_name,'relation',relation_name,'bytes',total_bytes
         ) order by total_bytes desc),'[]'::jsonb)
  into v_largest
  from (
    select n.nspname schema_name,c.relname relation_name,pg_total_relation_size(c.oid) total_bytes
    from pg_class c join pg_namespace n on n.oid=c.relnamespace
    where c.relkind in ('r','m')
      and n.nspname not in ('pg_catalog','information_schema')
    order by total_bytes desc
    limit 10
  ) x;

  select coalesce(to_jsonb(p),'{}'::jsonb) into v_evidence_policy
  from pipeline.evidence_capacity_policy p where id=true;

  if coalesce((v_evidence_policy->>'planning_capacity_bytes')::bigint,0)>0 then
    v_evidence_pct:=round((v_obj_bytes::numeric/(v_evidence_policy->>'planning_capacity_bytes')::numeric)*100,2);
  end if;

  select coalesce(to_jsonb(p),'{}'::jsonb) into v_policy
  from pipeline.platform_capacity_policy p where environment=p_environment;

  select cumulative_temp_bytes,observed_at
    into v_prev_temp_bytes,v_prev_observed_at
  from pipeline.platform_capacity_observations
  where environment=p_environment
  order by observed_at desc limit 1;

  if v_prev_temp_bytes is not null then
    v_temp_delta:=greatest(v_temp_bytes-v_prev_temp_bytes,0);
  end if;

  if coalesce((v_policy->>'database_critical_bytes')::bigint,9223372036854775807) <= v_db
     or coalesce((v_policy->>'integrity_critical_count')::integer,2147483647) <= v_integrity_count
     or coalesce((v_evidence_policy->>'critical_pct')::numeric,101) <= coalesce(v_evidence_pct,0)
  then v_severity:='critical';
  elsif coalesce((v_policy->>'database_high_bytes')::bigint,9223372036854775807) <= v_db
     or coalesce((v_policy->>'integrity_high_count')::integer,2147483647) <= v_integrity_count
     or coalesce((v_evidence_policy->>'high_pct')::numeric,101) <= coalesce(v_evidence_pct,0)
  then v_severity:='high';
  elsif coalesce((v_policy->>'database_warn_bytes')::bigint,9223372036854775807) <= v_db
     or coalesce((v_policy->>'integrity_warn_count')::integer,2147483647) <= v_integrity_count
     or coalesce((v_evidence_policy->>'warn_pct')::numeric,101) <= coalesce(v_evidence_pct,0)
  then v_severity:='warning';
  end if;

  return jsonb_build_object(
    'environment',p_environment,
    'observed_at',now(),
    'severity',v_severity,
    'database_bytes',v_db,
    'cumulative_temp_bytes',v_temp_bytes,
    'cumulative_temp_files',v_temp_files,
    'temp_bytes_since_previous_observation',v_temp_delta,
    'previous_observation_at',v_prev_observed_at,
    'evidence_object_count',v_obj_count,
    'evidence_object_bytes',v_obj_bytes,
    'evidence_planning_capacity_pct',v_evidence_pct,
    'evidence_artifact_count',v_evidence_count,
    'unlinked_storage_object_count_raw',v_unlinked_raw,
    'duplicate_unlinked_storage_object_count',v_duplicate_unlinked,
    'reconciled_historical_orphan_count',v_reconciled_orphans,
    'orphan_object_count',v_orphans,
    'direct_virtual_evidence_reference_count',v_direct_virtual_refs,
    'reconciled_legacy_reference_count',v_reconciled_legacy_refs,
    'virtual_evidence_reference_count',v_virtual_refs,
    'missing_storage_object_count_raw',v_failed_raw,
    'missing_storage_object_count',v_failed,
    'failed_upload_count',v_failed,
    'integrity_count_for_severity',v_integrity_count,
    'integrity_classification',jsonb_build_object(
      'raw_unlinked_storage_objects',v_unlinked_raw,
      'proven_duplicate_unlinked_objects',v_duplicate_unlinked,
      'reconciled_historical_orphans',v_reconciled_orphans,
      'unresolved_orphan_objects',v_orphans,
      'direct_virtual_or_external_evidence_references',v_direct_virtual_refs,
      'reconciled_legacy_references',v_reconciled_legacy_refs,
      'virtual_or_external_evidence_references',v_virtual_refs,
      'raw_missing_bucket_objects',v_failed_raw,
      'missing_bucket_objects',v_failed,
      'duplicate_rule','same ETag + size as an Evidence-linked object',
      'reconciliation_rule','explicit private CF-governed provenance ledger'
    ),
    'largest_relations',v_largest,
    'evidence_capacity_policy',v_evidence_policy,
    'platform_capacity_policy',v_policy,
    'backup_status','platform_api_required',
    'pitr_status','platform_api_required'
  );
end $_$;


ALTER FUNCTION "security"."platform_capacity_snapshot_internal"("p_environment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_capacity_snapshot_read"("p_environment" "text" DEFAULT 'pilot'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$
declare v_rank integer;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
  return security.platform_capacity_snapshot_internal(p_environment);
end $$;


ALTER FUNCTION "security"."platform_capacity_snapshot_read"("p_environment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_cron_field_values"("p_field" "text", "p_lo" integer, "p_hi" integer) RETURNS integer[]
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
declare part text; rng text; step int; a int; b int; acc int[]:='{}'; i int;
begin
  foreach part in array string_to_array(p_field,',') loop
    step:=1; rng:=part;
    if position('/' in part)>0 then rng:=split_part(part,'/',1); step:=split_part(part,'/',2)::int; end if;
    if rng='*' then a:=p_lo; b:=p_hi;
    elsif position('-' in rng)>0 then a:=split_part(rng,'-',1)::int; b:=split_part(rng,'-',2)::int;
    else a:=rng::int; b:=case when position('/' in part)>0 then p_hi else a end; end if;
    if step<1 then return null; end if;
    i:=a; while i<=b loop acc:=acc||i; i:=i+step; end loop;
  end loop;
  return (select array_agg(distinct x order by x) from unnest(acc) x);
end $$;


ALTER FUNCTION "security"."platform_cron_field_values"("p_field" "text", "p_lo" integer, "p_hi" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_cron_interval_seconds"("p_schedule" "text") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'security'
    AS $_$
declare f text[]; mins int[]; hrs int[]; days int[]; t int[];
begin
  if p_schedule ~* '^\s*\d+\s+seconds?\s*$' then return substring(p_schedule from '\d+')::int; end if;
  f:=regexp_split_to_array(trim(p_schedule),'\s+');
  if cardinality(f)<>5 or f[4]<>'*' then return null; end if;
  if f[3]<>'*' then return 31*86400; end if;
  if f[5]<>'*' then
    days:=security.platform_cron_field_values(f[5],0,7);
    days:=(select array_agg(distinct (d%7)) from unnest(days) d);
    return security.platform_cyclic_max_gap(days,7)*86400;
  end if;
  mins:=security.platform_cron_field_values(f[1],0,59); hrs:=security.platform_cron_field_values(f[2],0,23);
  select array_agg(h*60+m) into t from unnest(hrs) h cross join unnest(mins) m;
  return security.platform_cyclic_max_gap(t,1440)*60;
exception when others then return null;
end $_$;


ALTER FUNCTION "security"."platform_cron_interval_seconds"("p_schedule" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_cyclic_max_gap"("p_values" integer[], "p_mod" integer) RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select max(nx-x) from (select x, coalesce(lead(x) over (order by x), min(x) over ()+p_mod) nx from unnest(p_values) x) z
$$;


ALTER FUNCTION "security"."platform_cyclic_max_gap"("p_values" integer[], "p_mod" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_health_check_v1"("p_force" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security', 'public', 'catalogue', 'scholarship'
    SET "statement_timeout" TO '60s'
    AS $_$
declare
  v_t0 timestamptz:=clock_timestamp(); v_t timestamptz;
  v_found jsonb:='[]'::jsonb; v_ok text[]:='{}'; v_ms jsonb:='{}'::jsonb; v_det jsonb:='{}'::jsonb;
  v_slow_used boolean:=false; r record; v_n bigint; v_n2 bigint; v_n3 bigint; v_x jsonb; v_q jsonb; v_prev jsonb;
  v_ts timestamptz; v_ts2 timestamptz; v_num numeric; v_num2 numeric; v_txt text; v_args text; v_arr text[]; v_bool boolean;
  v_counts jsonb; v_jobs int:=0; v_fail int:=0; v_stale int:=0; v_spend numeric;
begin
  -- 4.1 scheduled jobs: failures in the last hour; active jobs not run in more than 3x their interval
  if security.platform_health_due_v1('cron',p_force) then
    v_t:=clock_timestamp();
    begin
      for r in
        with agg as (
          select d.jobid, max(d.start_time) last_run, min(d.start_time) first_run,
                 count(*) filter (where d.status='failed' and d.start_time>=now()-interval '1 hour') fails_1h,  -- fixed: health check observation window
                 count(*) filter (where d.start_time>=now()-interval '1 hour') runs_1h,  -- fixed: health check observation window
                 -- SS-014 (31 Oct 2026): a failure stays visible until the job runs cleanly again, and repeats are counted over a set window
                 count(*) filter (where d.status='failed' and d.start_time>=now()-make_interval(hours=>security.pipeline_num_v1('health.job_failure_window_hours', 24)::int)) fails_win,
                 (array_agg(d.status order by d.start_time desc))[1] last_status,
                 (array_agg(left(d.return_message,200) order by d.start_time desc) filter (where d.status='failed'))[1] last_error
            from (select d0.jobid, d0.start_time, d0.return_message, case when d0.status='failed' and d0.return_message='job canceled' then security.cron_run_outcome_v1(j0.jobname, d0.status, d0.return_message, d0.start_time) else d0.status end status  -- SS-004 (1 Nov 2026): classified only when cancelled (keeps the section at its former run time)
                  from cron.job_run_details d0 join cron.job j0 on j0.jobid=d0.jobid) d group by d.jobid)  -- SS-004 (1 Nov 2026): a run cancelled by the flag unit's idle pause is paused, not failed
        select j.jobid, j.jobname, j.schedule, security.platform_cron_interval_seconds(j.schedule) ival,
               a.last_run, coalesce(a.fails_1h,0) fails_1h, coalesce(a.runs_1h,0) runs_1h, a.last_error, coalesce(a.fails_win,0) fails_win, a.last_status,
               (select min(a2.first_run) from agg a2 where a2.jobid>j.jobid) created_before
          from cron.job j left join agg a on a.jobid=j.jobid where j.active
      loop
        v_jobs:=v_jobs+1;
        if r.fails_1h>0 or r.last_status='failed' or r.fails_win>=security.pipeline_num_v1('health.job_failure_repeat_count', 3) then
          v_fail:=v_fail+1;
          select bool_and(x.status='failed') into v_bool from (select case when d.status='failed' and d.return_message='job canceled' then security.cron_run_outcome_v1(r.jobname, d.status, d.return_message, d.start_time) else d.status end status from cron.job_run_details d where d.jobid=r.jobid order by d.start_time desc limit security.pipeline_num_v1('health.job_failure_critical_consecutive', 3)::int) x;
          v_found:=v_found||security.platform_health_issue_v1('cron:failed:'||r.jobname, case when v_bool then 'critical' else 'warning' end,
            'scheduled jobs', 'Scheduled job "'||r.jobname||'" failed '||r.fails_1h||' of '||r.runs_1h||' run(s) in the last hour'||case when r.fails_win>r.fails_1h then '; '||r.fails_win||' failure(s) in the last '||security.pipeline_num_v1('health.job_failure_window_hours', 24)::int||' hours' else '' end||case when r.last_status='failed' then '; the last run failed' else '' end,
            jsonb_build_object('job',r.jobname,'schedule',r.schedule,'failures_1h',r.fails_1h,'runs_1h',r.runs_1h,'last_error',r.last_error,'last_three_failed',coalesce(v_bool,false),'failures_window',r.fails_win,'last_status',r.last_status));
        end if;
        -- 16 Oct 2026: a job the flag unit switched on again (trial run) counts from that moment, not from its last run before the pause
        v_ts:=greatest(coalesce(r.last_run, r.created_before), (select max(f.released_at) from pipeline.enrichment_flags f where f.entity='job' and f.entity_key=r.jobname and f.field=''));
        if r.ival is not null and v_ts is not null and now()-v_ts > make_interval(secs=>3*r.ival) + interval '2 minutes' then
          v_stale:=v_stale+1;
          v_found:=v_found||security.platform_health_issue_v1('cron:stale:'||r.jobname,
            case when now()-v_ts > greatest(make_interval(secs=>12*r.ival), interval '2 hours') and r.ival<=3600 then 'critical' else 'warning' end,  -- fixed: health check observation window
            'scheduled jobs', 'Scheduled job "'||r.jobname||'" has not run '||case when r.last_run is null then 'since it was scheduled' else 'since '||to_char(r.last_run at time zone 'UTC','DD Mon HH24:MI')||' UTC' end,
            jsonb_build_object('job',r.jobname,'schedule',r.schedule,'expected_every_minutes',round(r.ival/60.0,1),'last_run',r.last_run));
        end if;
      end loop;
      v_det:=v_det||jsonb_build_object('cron',jsonb_build_object('active_jobs',v_jobs,'jobs_failing',v_fail,'jobs_overdue',v_stale));
      v_ok:=array_append(v_ok,'cron');
    exception when others then
      v_ok:=array_append(v_ok,'cron');
      v_found:=v_found||security.platform_health_issue_v1('cron:check_error','warning','scheduled jobs','The scheduled-job health check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('cron',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.2 Edge function calls made through pg_net over the last 30 minutes, grouped by function
  if security.platform_health_due_v1('edge_calls',p_force) then
    v_t:=clock_timestamp(); v_n:=0; v_n2:=0; v_q:='[]'::jsonb;
    begin
      for r in
        with resp as (
          select rr.id, rr.status_code, rr.timed_out, rr.error_msg, rr.content,
                 coalesce(c.function_name, substring(rr.content from '"workerVersion"\s*:\s*"([a-z0-9-]+?)-v[0-9]'), 'unattributed') fn,
                 (coalesce(rr.status_code,0)>=400 or rr.timed_out is true or rr.error_msg is not null) failed
            from net._http_response rr left join pipeline.platform_edge_calls c on c.id=rr.id
           where rr.created>=now()-interval '30 minutes')
        select fn, count(*) total, count(*) filter (where failed) failures, count(*) filter (where timed_out) timeouts,
               count(*) filter (where status_code=404 and (content ilike '%NOT_FOUND%' or content ilike '%function was not found%')) not_deployed,
               array_agg(distinct coalesce(status_code::text, case when timed_out then 'timeout' else 'error' end)) filter (where failed) codes,
               (array_agg(left(coalesce(content,error_msg),200) order by id desc) filter (where failed))[1] sample
          from resp group by fn order by count(*) filter (where failed) desc
      loop
        v_n:=v_n+r.total; v_n2:=v_n2+r.failures;
        if jsonb_array_length(v_q)<15 then v_q:=v_q||jsonb_build_object('function',r.fn,'calls',r.total,'failures',r.failures,'timeouts',r.timeouts); end if;
        if r.not_deployed>0 then
          v_found:=v_found||security.platform_health_issue_v1('edge_calls:not_deployed:'||r.fn,'critical','edge functions',
            'Edge function "'||r.fn||'" is called but not deployed (404, '||r.not_deployed||' call(s) in 30 minutes)',
            jsonb_build_object('function',r.fn,'calls',r.total,'not_found',r.not_deployed,'sample',r.sample));
        elsif r.failures>=2 then
          v_found:=v_found||security.platform_health_issue_v1('edge_calls:failing:'||r.fn,
            case when r.failures>=3 and r.failures=r.total then 'critical' else 'warning' end,'edge functions',
            case when r.fn='unattributed' then 'Edge function calls' else 'Edge function "'||r.fn||'"' end||': '||r.failures||' of '||r.total||' call(s) failed in the last 30 minutes'
              ||case when r.timeouts>0 then ' ('||r.timeouts||' timed out)' else '' end,
            jsonb_build_object('function',r.fn,'calls',r.total,'failures',r.failures,'timeouts',r.timeouts,'codes',to_jsonb(r.codes),'sample',r.sample));
        end if;
      end loop;
      select count(*) into v_n3 from net.http_request_queue;
      if v_n3>100 then
        v_found:=v_found||security.platform_health_issue_v1('edge_calls:queue_backlog', case when v_n3>500 then 'critical' else 'warning' end,'edge functions',
          v_n3||' outbound calls are waiting in the pg_net queue',jsonb_build_object('queued',v_n3));
      end if;
      v_det:=v_det||jsonb_build_object('edge_calls',jsonb_build_object('window_minutes',30,'calls',v_n,'failures',v_n2,'queued',v_n3,'by_function',v_q));
      v_ok:=array_append(v_ok,'edge_calls');
    exception when others then
      v_ok:=array_append(v_ok,'edge_calls');
      v_found:=v_found||security.platform_health_issue_v1('edge_calls:check_error','warning','edge functions','The Edge function call check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('edge_calls',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.3 Edge functions deployed vs expected: not queryable from the database (skipped; recently invoked list only)
  if security.platform_health_due_v1('edge_deployed',p_force) then
    v_t:=clock_timestamp();
    begin
      v_det:=v_det||jsonb_build_object('edge_deployed',jsonb_build_object(
        'note','Skipped: the live Edge function list cannot be read from the database. Compare supabase/functions in git with the live list (Supabase list_edge_functions). A call to a missing function shows here as a 404 under Edge function calls.',
        'invoked_last_24h',coalesce((select jsonb_agg(distinct function_name order by function_name) from pipeline.platform_edge_calls where created_at>=now()-interval '24 hours'),'[]'::jsonb)));  -- fixed: health check observation window
      v_ok:=array_append(v_ok,'edge_deployed');
    exception when others then null;
    end;
    v_ms:=v_ms||jsonb_build_object('edge_deployed',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.4 coverage sweep queues
  if security.platform_health_due_v1('coverage_queues',p_force) then
    v_t:=clock_timestamp(); v_q:='[]'::jsonb;
    begin
      -- SS-004 (1 Nov 2026): waiting is measured from the later of the last read and the moment the oldest waiting page became due, so a page that
      -- has only just become due after a quiet spell is not reported as hours of stall; a page left waiting still ages and goes critical
      -- SS-014 P2 (2 Nov 2026): waiting means what the reader takes (security.coverage_read_eligible_v1: hidden providers and leased pages left out)
      select greatest(max(read_at), (select min(e.due_at) from security.coverage_read_eligible_v1() e)) into v_ts from pipeline.coverage_course_pages;
      v_q:=v_q||security.platform_health_stall_v1('coverage_queues:read','coverage sweep','Coverage page reading','coverage-read',v_ts,
        $q$select count(*) from security.coverage_read_eligible_v1()$q$);  -- SS-014 P2 (2 Nov 2026): the same pages the reader takes
      select greatest(max(updated_at), (select min(coalesce(q.next_due_at, q.updated_at)) from pipeline.coverage_provider_discovery q
                                         where (q.status='pending' or (q.status in ('mapped','failed') and q.next_due_at<=now())) and q.attempts<3
                                           and security.enrich_focus_v1(q.provider_id) and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id=q.provider_id))) into v_ts from pipeline.coverage_provider_discovery;  -- SS-004 (1 Nov 2026): as above
      v_q:=v_q||security.platform_health_stall_v1('coverage_queues:discover','coverage sweep','Coverage provider discovery','coverage-discover',v_ts,
        $q$select count(*) from pipeline.coverage_provider_discovery d where (d.status='pending' or (d.status in ('mapped','failed') and d.next_due_at<=now())) and d.attempts<3 and security.enrich_focus_v1(d.provider_id) and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id=d.provider_id)$q$);
      -- re-extract has no timestamp: progress means the number of pages on an older extractor went down
      select c.candidates->>'extractor' into v_txt from pipeline.coverage_course_pages c where c.read_status='read' and c.read_at is not null order by c.read_at desc limit 1;
      select count(*) into v_n from pipeline.coverage_course_pages cp
       where cp.read_status='read' and cp.identity_basis is not null and cp.evidence_id is not null and coalesce(cp.candidates->>'extractor','')<>coalesce(v_txt,'');
      select c.detail->'reextract' into v_prev from pipeline.platform_health_checks c where c.key='coverage_queues';
      v_ts:=case when v_n=0 or v_n<coalesce((v_prev->>'pending')::bigint, v_n+1) then now() else coalesce((v_prev->>'progress_at')::timestamptz, now()) end;
      v_q:=v_q||(security.platform_health_stall_v1('coverage_queues:reextract','coverage sweep','Coverage re-extraction','coverage-reextract',v_ts,'select '||v_n)
                 ||jsonb_build_object('pending',v_n,'progress_at',v_ts,'extractor',v_txt));
      -- 16 Oct 2026: the tuition hand-off to Layer 3 is retired (Layer 3 retired for tuition on 12 Oct 2026; university adapters admit fees)
      v_q:=v_q||jsonb_build_object('queue','coverage_queues:tuition_handoff','status','retired','note','Layer 3 was retired for tuition on 12 Oct 2026; fees are admitted by university adapters');
      select coalesce(jsonb_agg(e->'issue'),'[]'::jsonb) into v_x from jsonb_array_elements(v_q) e where e ? 'issue';
      v_found:=v_found||v_x;
      v_det:=v_det||jsonb_build_object('coverage_queues',jsonb_build_object('queues',(select jsonb_agg(e-'issue') from jsonb_array_elements(v_q) e),
        'reextract',(select e-'issue'-'queue'-'status' from jsonb_array_elements(v_q) e where e->>'queue'='coverage_queues:reextract')));
      v_ok:=array_append(v_ok,'coverage_queues');
    exception when others then
      v_ok:=array_append(v_ok,'coverage_queues');
      v_found:=v_found||security.platform_health_issue_v1('coverage_queues:check_error','warning','coverage sweep','The coverage queue check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('coverage_queues',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.5 scholarship queues
  if security.platform_health_due_v1('scholarship_queues',p_force) then
    v_t:=clock_timestamp(); v_q:='[]'::jsonb;
    begin
      select max(read_at) into v_ts from pipeline.scholarship_pages;
      v_q:=v_q||security.platform_health_stall_v1('scholarship_queues:read','scholarships','Scholarship page reading','scholarship-read',v_ts,
        $q$select count(*) from pipeline.scholarship_pages p join scholarship.scholarships s on s.id=p.scholarship_id and s.lifecycle_status='active'
            where p.next_read_at<=now() and p.attempts<5 and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id=s.provider_id)
              and (p.requested_at is not null or not security.fc_sch_held_v1(s.provider_id, false))$q$);  -- 16 Oct 2026: only pages a reader can take
      -- SS-014A (31 Oct 2026): whether each provider is held by the scholarship Firecrawl rules is worked out once and shared by the candidate,
      -- discovery and held counts (it was worked out up to three times per provider, about 10 s a run); same rules, same counts
      with dp as materialized (select d.provider_id, d.website from pipeline.scholarship_discovery_providers d where d.status='pending' and d.attempts<3),
           cand as materialized (select c.provider_id, c.url from pipeline.scholarship_page_candidates c join pipeline.scholarship_discovery_providers d on d.provider_id=c.provider_id and d.priority in (0,1,3,4)
                                  where c.matched_scholarship_id is null and c.admit_status is null and c.next_read_at<=now() and c.attempts<3),
           hp as materialized (select x.provider_id, security.fc_sch_held_v1(x.provider_id, true) held from (select dp.provider_id from dp union select cand.provider_id from cand) x)
      select (select count(*) from cand join hp on hp.provider_id=cand.provider_id where not hp.held and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id=cand.provider_id)
                and not security.third_party_host_v1(cand.url) and not security.provider_sch_search_off_v1(cand.provider_id)),
             (select count(*) from dp join hp on hp.provider_id=dp.provider_id where not hp.held and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id=dp.provider_id)
                and not security.third_party_host_v1(coalesce(dp.website, '')) and not security.provider_sch_search_off_v1(dp.provider_id)),
             (select count(*) from dp join hp on hp.provider_id=dp.provider_id where hp.held)
        into v_n, v_n2, v_n3;
      select max(read_at) into v_ts from pipeline.scholarship_page_candidates;
      v_q:=v_q||security.platform_health_stall_v1('scholarship_queues:candidates','scholarships','Scholarship candidate page reading','scholarship-discover',v_ts,'select '||v_n);  -- 16 Oct 2026: only pages a reader can take
      select max(updated_at) into v_ts from pipeline.scholarship_discovery_providers;
      v_q:=v_q||security.platform_health_stall_v1('scholarship_queues:discover','scholarships','Scholarship provider discovery','scholarship-discover',v_ts,'select '||v_n2);  -- 16 Oct 2026: only providers discovery can take
      -- 16 Oct 2026: work held by the per-university cap, by policy (small Australian providers) or by settings, shown apart from stalls
      v_q:=v_q||jsonb_build_object('queue','scholarship_queues:held','status','held',
        'pages_held_by_cap',(select count(*) from pipeline.scholarship_pages p join scholarship.scholarships s on s.id=p.scholarship_id and s.lifecycle_status='active'
            where p.next_read_at<=now() and p.attempts<5 and p.requested_at is null and security.fc_sch_held_v1(s.provider_id, false)),
        'providers_not_searched',v_n3,
        'note','Held by the per-university Firecrawl cap or by the rule that small Australian providers are not searched; not a stall');
      select coalesce(jsonb_agg(e->'issue'),'[]'::jsonb) into v_x from jsonb_array_elements(v_q) e where e ? 'issue';
      v_found:=v_found||v_x;
      v_det:=v_det||jsonb_build_object('scholarship_queues',jsonb_build_object('queues',(select jsonb_agg(e-'issue') from jsonb_array_elements(v_q) e)));
      v_ok:=array_append(v_ok,'scholarship_queues');
    exception when others then
      v_ok:=array_append(v_ok,'scholarship_queues');
      v_found:=v_found||security.platform_health_issue_v1('scholarship_queues:check_error','warning','scholarships','The scholarship queue check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('scholarship_queues',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.6 Layer 2 run items, Layer 3 work items, Layer 4 review backlog
  if security.platform_health_due_v1('layer_queues',p_force) then
    v_t:=clock_timestamp(); v_q:='[]'::jsonb;
    begin
      select count(*), min(coalesce(updated_at,created_at)) into v_n, v_ts from pipeline.layer2_run_items
       where status in ('queued','discovering','acquiring','extracting') and coalesce(updated_at,created_at)<now()-interval '2 hours';  -- fixed: health check observation window
      if v_n>0 then
        v_found:=v_found||security.platform_health_issue_v1('layer_queues:layer2_stuck','warning','Layer 3',
          v_n||' Layer 2 run item(s) have not moved for more than 2 hours',jsonb_build_object('stuck',v_n,'oldest_update',v_ts));
      end if;
      v_q:=v_q||jsonb_build_object('queue','layer2_run_items','stuck_over_2h',v_n);
      select count(*), min(coalesce(reserved_at,updated_at)), (array_agg(id order by coalesce(reserved_at,updated_at)))[1:5]::text
        into v_n, v_ts, v_txt from pipeline.layer3_work_items where status in ('reserved','interpreting') and coalesce(reserved_at,updated_at)<now()-interval '1 hour';  -- fixed: health check observation window
      if v_n>0 then
        v_found:=v_found||security.platform_health_issue_v1('layer_queues:layer3_stuck','warning','Layer 3',
          v_n||' Layer 3 work item(s) stuck in reserved/interpreting for more than an hour',jsonb_build_object('stuck',v_n,'since',v_ts,'ids',v_txt));
      end if;
      select max(completed_at) into v_ts from pipeline.layer3_work_items;
      v_x:=security.platform_health_stall_v1('layer_queues:layer3_dispatch','Layer 3','Layer 3 work dispatch','layer3-tuition-dispatch',v_ts,
        $q$select count(*) from pipeline.layer3_work_items w where w.status='pending' and coalesce(w.available_at,now())<=now()$q$);
      if v_x ? 'issue' then v_found:=v_found||jsonb_build_array(v_x->'issue'); end if;
      v_q:=v_q||(v_x-'issue')||jsonb_build_object('queue','layer3_stuck_over_1h','count',v_n);
      select count(*) filter (where status='pending'), count(*) filter (where created_at>=now()-interval '24 hours'),  -- fixed: health check observation window
             count(*) filter (where decided_at>=now()-interval '24 hours'), count(*) filter (where decided_at>=now()-interval '48 hours')  -- fixed: health check observation window
        into v_n, v_n2, v_n3, v_num from pipeline.layer4_review_items;
      if v_n2-v_n3>300 and v_num=0 then
        v_found:=v_found||security.platform_health_issue_v1('layer_queues:layer4_backlog','warning','Layer 3',
          'Layer 4 review backlog grew by '||(v_n2-v_n3)||' in 24 hours with no decisions in 48 hours ('||v_n||' waiting)',
          jsonb_build_object('pending',v_n,'created_24h',v_n2,'decided_24h',v_n3,'decided_48h',v_num));
      elsif v_n2-v_n3>100 then
        v_found:=v_found||security.platform_health_issue_v1('layer_queues:layer4_backlog','info','Layer 3',
          'Layer 4 review backlog grew by '||(v_n2-v_n3)||' in 24 hours ('||v_n||' waiting)',
          jsonb_build_object('pending',v_n,'created_24h',v_n2,'decided_24h',v_n3,'decided_48h',v_num));
      end if;
      v_q:=v_q||jsonb_build_object('queue','layer4_review','pending',v_n,'created_24h',v_n2,'decided_24h',v_n3);
      v_det:=v_det||jsonb_build_object('layer_queues',jsonb_build_object('queues',v_q));
      v_ok:=array_append(v_ok,'layer_queues');
    exception when others then
      v_ok:=array_append(v_ok,'layer_queues');
      v_found:=v_found||security.platform_health_issue_v1('layer_queues:check_error','warning','Layer 3','The Layer 2 to 4 queue check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('layer_queues',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.7 consumer API snapshot (slow, hourly)
  if (p_force or not v_slow_used) and security.platform_health_due_v1('consumer_snapshot',p_force) then
    v_t:=clock_timestamp(); v_slow_used:=true;
    begin
      v_x:=security.consumer_api_snapshot_v1();
      select coalesce(array_agg(e.k order by e.k),'{}'), max((e.v->>'ms')::numeric) into v_arr, v_num
        from jsonb_each(coalesce(v_x,'{}'::jsonb)) e(k,v) where jsonb_typeof(e.v)='object' and e.v ? 'ok' and (e.v->>'ok')::boolean is not true;
      select max((e.v->>'ms')::numeric) into v_num from jsonb_each(coalesce(v_x,'{}'::jsonb)) e(k,v) where jsonb_typeof(e.v)='object' and e.v ? 'ms';
      if v_x is null then
        v_found:=v_found||security.platform_health_issue_v1('consumer_snapshot:empty','critical','search/API','The consumer API snapshot returned nothing','{}'::jsonb);
      elsif cardinality(v_arr)>0 then
        v_found:=v_found||security.platform_health_issue_v1('consumer_snapshot:failing','critical','search/API',
          'Consumer API: '||cardinality(v_arr)||' probe(s) failing ('||array_to_string(v_arr[1:5],', ')||')',jsonb_build_object('failing',to_jsonb(v_arr)));
      end if;
      v_det:=v_det||jsonb_build_object('consumer_snapshot',jsonb_build_object('probes',(select count(*) from jsonb_each(coalesce(v_x,'{}'::jsonb)) e(k,v) where jsonb_typeof(e.v)='object' and e.v ? 'ok'),
        'failing',to_jsonb(v_arr),'slowest_probe_ms',v_num,'run_ms',round(extract(epoch from clock_timestamp()-v_t)*1000)));
      v_ok:=array_append(v_ok,'consumer_snapshot');
    exception when others then
      v_ok:=array_append(v_ok,'consumer_snapshot');
      v_found:=v_found||security.platform_health_issue_v1('consumer_snapshot:check_error','critical','search/API','The consumer API snapshot failed to run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('consumer_snapshot',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.8 admission: coverage-admit applied nothing in an hour while candidates exist (the plan is evaluated at most hourly)
  if security.platform_health_due_v1('admission',p_force) then
    v_t:=clock_timestamp();
    begin
      select max(captured_at) into v_ts from pipeline.consumer_api_baselines where label like 'after coverage admission batch%';
      select c.detail into v_prev from pipeline.platform_health_checks c where c.key='admission';
      if v_ts>=now()-interval '1 hour' then  -- fixed: health check observation window
        v_det:=v_det||jsonb_build_object('admission',jsonb_build_object('last_batch',v_ts,'plan_checked_at',v_prev->'plan_checked_at','candidates',v_prev->'candidates'));
        v_ok:=array_append(v_ok,'admission');
      elsif p_force or (not v_slow_used and coalesce((v_prev->>'plan_checked_at')::timestamptz,'-infinity'::timestamptz)<now()-interval '55 minutes') then
        v_slow_used:=true;
        -- follow the live defaults of coverage_admission_apply_v1 (what the coverage-admit job runs)
        v_args:=pg_get_function_arguments('security.coverage_admission_apply_v1'::regproc);
        v_txt:=substring(v_args from 'p_extractor text DEFAULT ''([^'']+)''');
        v_arr:=array(select m[1] from regexp_matches(coalesce(substring(v_args from 'p_attributes text\[\] DEFAULT ARRAY\[(.*)\]'),''),'''([^'']+)''','g') m);
        if cardinality(v_arr)=0 then v_arr:=array['official_url','english']; end if;
        execute 'select count(*) from security.coverage_admission_plan_v1($1) where action=''write'' and attribute=any($2)' into v_n using coalesce(v_txt,'coverage-sweep-v0.5.4'), v_arr;
        if v_n>0 then
          v_found:=v_found||security.platform_health_issue_v1('admission:stalled',
            case when v_ts is null or v_ts<now()-interval '3 hours' then 'critical' else 'warning' end,'admission',  -- fixed: health check observation window
            'Coverage admission has applied nothing for over an hour while '||v_n||' value(s) are ready to write',
            jsonb_build_object('candidates',v_n,'last_batch',v_ts,'extractor',v_txt,'attributes',to_jsonb(v_arr)));
        end if;
        v_det:=v_det||jsonb_build_object('admission',jsonb_build_object('last_batch',v_ts,'plan_checked_at',now(),'candidates',v_n,'extractor',v_txt));
        v_ok:=array_append(v_ok,'admission');
      end if;
    exception when others then
      v_ok:=array_append(v_ok,'admission');
      v_found:=v_found||security.platform_health_issue_v1('admission:check_error','warning','admission','The admission check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('admission',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.9 budgets
  if security.platform_health_due_v1('budgets',p_force) then
    v_t:=clock_timestamp();
    begin
      select security.layer2_provider_budget_status(p.id,1) into v_x from pipeline.layer2_acquisition_providers p where p.provider_key='firecrawl' and p.enabled;
      if v_x is null then
        v_found:=v_found||security.platform_health_issue_v1('budgets:firecrawl_disabled','warning','budgets','Firecrawl is not enabled: coverage site maps and scholarship searches cannot use it','{}'::jsonb);
      else
        v_num:=coalesce((v_x->>'remaining_units')::numeric,0)-coalesce((v_x->>'stop_at_remaining_units')::numeric,0);
        if (v_x->>'allowed')::boolean is false or v_num<=0 then
          v_found:=v_found||security.platform_health_issue_v1('budgets:firecrawl','critical','budgets',
            'Firecrawl has reached its reserve: paid page reads and site maps have stopped until '||to_char((v_x->>'period_end')::timestamptz,'DD Mon'),
            v_x-'provider_id');
        elsif v_num<0.1*coalesce((v_x->>'limit_units')::numeric,0) then
          v_found:=v_found||security.platform_health_issue_v1('budgets:firecrawl','warning','budgets',
            'Firecrawl is close to its reserve: '||v_num||' credits left above the reserve this period',v_x-'provider_id');
        end if;
      end if;
      -- 16 Oct 2026: scholarship work has its own Firecrawl allowance, read from its setting (Scholarships settings firecrawl_cap; was written here as 3,000)
      select coalesce(sum(units),0) into v_num2 from pipeline.coverage_vendor_usage where purpose in ('sch_map','sch_search','sch_scrape');
      v_n3:=coalesce((select s.value from pipeline.scholarship_layer_settings s where s.key='firecrawl_cap'),0);
      if v_n3>0 and v_num2>=v_n3 then
        v_found:=v_found||security.platform_health_issue_v1('budgets:scholarship_firecrawl','warning','budgets',
          'Scholarship Firecrawl allowance is used up ('||v_num2||' of '||v_n3||' credits): scholarship pages are not read until it is raised',jsonb_build_object('used',v_num2,'cap',v_n3));
      elsif v_n3>0 and v_num2>=0.9*v_n3 then  -- fixed: 90% notice
        v_found:=v_found||security.platform_health_issue_v1('budgets:scholarship_firecrawl','info','budgets',
          'Scholarship Firecrawl allowance is 90% used ('||v_num2||' of '||v_n3||' credits)',jsonb_build_object('used',v_num2,'cap',v_n3));
      end if;
      -- OpenRouter: recorded spend over 24 hours against the US$5 daily ceiling (delivery plan v1.1)
      -- SS-014 (31 Oct 2026): all OpenRouter spend (enrichment, AI match, entry reads, Layer 3), measured from the credit balance; top-ups are not counted
      select coalesce((select sum(greatest(o.prev - o.remaining_usd, 0)) from (select x.remaining_usd, lag(x.remaining_usd) over (order by x.observed_at) prev
                         from pipeline.layer3_openrouter_observations x where x.kind = 'credits' and x.remaining_usd is not null and x.observed_at>=now()-interval '24 hours') o),0)  -- fixed: health check observation window
           into v_num; v_spend:=round(v_num,4);  -- CF-247 20 Oct 2026 (D11): retired benchmark and scholarship AI run tables no longer counted
      if v_num>=security.pipeline_num_v1('budgets.ai_daily_ceiling_usd', 14) then
        v_found:=v_found||security.platform_health_issue_v1('budgets:openrouter_daily','critical','budgets',
          'OpenRouter spend in the last 24 hours is US$'||round(v_num,2)||', at or over the US$'||security.pipeline_num_v1('budgets.ai_daily_ceiling_usd', 14)||' combined daily ceiling',jsonb_build_object('spend_24h_usd',round(v_num,4),'ceiling_usd',security.pipeline_num_v1('budgets.ai_daily_ceiling_usd', 14)));
      elsif v_num>=0.8*security.pipeline_num_v1('budgets.ai_daily_ceiling_usd', 14) then  -- fixed: notice at 80% of the ceiling
        v_found:=v_found||security.platform_health_issue_v1('budgets:openrouter_daily','warning','budgets',
          'OpenRouter spend in the last 24 hours is US$'||round(v_num,2)||' (80% of the US$'||security.pipeline_num_v1('budgets.ai_daily_ceiling_usd', 14)||' combined daily ceiling)',jsonb_build_object('spend_24h_usd',round(v_num,4),'ceiling_usd',security.pipeline_num_v1('budgets.ai_daily_ceiling_usd', 14)));
      end if;
      -- CF-247 worker v1.0.3 (15 Nov 2026): the OpenRouter key's own limit (job openrouter-balance reads it; a refusal records it at once)
      declare k jsonb := security.openrouter_key_room_v1();
      begin
        if coalesce((k->>'held')::boolean, false) then
          v_found:=v_found||security.platform_health_issue_v1('budgets:openrouter_key','critical','budgets',
            'The OpenRouter key has no room: about US$'||round((k->>'estimated_usd')::numeric,2)||' left of its '||coalesce(k->>'limit_reset','total')||' limit of US$'||coalesce(k->>'limit_usd','?')
            ||'. All AI work is held until the limit resets or is raised on OpenRouter',k);
        elsif (k->>'period_ceiling_usd') is not null and (k->>'limit_usd') is not null and (k->>'limit_usd')::numeric < (k->>'period_ceiling_usd')::numeric then
          v_found:=v_found||security.platform_health_issue_v1('budgets:openrouter_key','warning','budgets',
            'The OpenRouter key''s '||(k->>'limit_reset')||' limit of US$'||(k->>'limit_usd')||' is below the daily ceiling over that period (US$'||(k->>'ceiling_usd')||' x '||(k->>'period_days')
            ||' days = US$'||(k->>'period_ceiling_usd')||'): the key will stop AI work before the ceiling does',k);
        elsif not coalesce((k->>'reading')::boolean, false) then
          v_found:=v_found||security.platform_health_issue_v1('budgets:openrouter_key','warning','budgets',
            'The OpenRouter key''s limit has not been read in the last '||(k->>'max_age_minutes')||' minutes (job openrouter-balance): a key limit would not be seen before it refuses',k);
        end if;
      end;
      select count(*) into v_num from pipeline.layer3_interpretations i
       where i.created_at>=now()-interval '30 minutes' and i.validator_result::text ~ 'provider_(401|402|403|429)';
      if v_num>=5 then
        v_found:=v_found||security.platform_health_issue_v1('budgets:openrouter_refusing','critical','Layer 3',
          'OpenRouter is refusing Layer 3 calls ('||v_num||' in 30 minutes): '||coalesce((select left(i.validator_result->'errors'->>0,160)
             from pipeline.layer3_interpretations i where i.created_at>=now()-interval '30 minutes' and i.validator_result::text ~ 'provider_(401|402|403|429)' order by i.created_at desc limit 1),'see the Layer 3 work queue')||'. Check the OpenRouter key and billing.',
          jsonb_build_object('refusals_30m',v_num));
      end if;
      select o.remaining_usd into v_num from pipeline.layer3_openrouter_observations o where o.kind='credits' and o.remaining_usd is not null order by o.observed_at desc limit 1;
      if v_num is not null and v_num<=5 then
        v_found:=v_found||security.platform_health_issue_v1('budgets:openrouter_credit','critical','budgets',
          'OpenRouter credit is US$'||round(v_num,2)||': at the US$5 floor, so automated Layer 3 admission has stopped. Top up the credit.',jsonb_build_object('remaining_usd',round(v_num,2),'floor_usd',5));
      elsif v_num is not null and v_num<10 then
        v_found:=v_found||security.platform_health_issue_v1('budgets:openrouter_credit','warning','budgets',
          'OpenRouter credit is US$'||round(v_num,2)||': automated Layer 3 admission stops at US$5. Top up soon.',jsonb_build_object('remaining_usd',round(v_num,2),'floor_usd',5));
      end if;
      for r in select p.code, count(*) n, max(i.estimated_cost_usd) mx, p.cost_ceiling_usd ceil
                 from pipeline.layer3_interpretations i join pipeline.layer3_model_profiles p on p.id=i.profile_id
                where i.created_at>=now()-interval '24 hours' and coalesce(i.external_call_count,0)>0 and p.cost_ceiling_usd is not null and i.estimated_cost_usd>p.cost_ceiling_usd  -- fixed: health check observation window
                group by p.code, p.cost_ceiling_usd loop
        v_found:=v_found||security.platform_health_issue_v1('budgets:call_ceiling:'||r.code,'warning','budgets',
          r.n||' Layer 3 call(s) on "'||r.code||'" cost more than its US$'||r.ceil||' per-call ceiling in 24 hours',jsonb_build_object('profile',r.code,'calls',r.n,'max_cost_usd',r.mx,'ceiling_usd',r.ceil));
      end loop;
      v_det:=v_det||jsonb_build_object('budgets',jsonb_build_object(
        'firecrawl',case when v_x is null then null else jsonb_build_object('used',v_x->'used_units','limit',v_x->'limit_units','remaining',v_x->'remaining_units','reserve',v_x->'stop_at_remaining_units','period_end',v_x->'period_end') end,
        'scholarship_firecrawl_used',v_num2,'scholarship_firecrawl_cap',v_n3,'openrouter_credit_remaining_usd',round(v_num,4),'openrouter_spend_24h_usd',v_spend,'ai_daily_ceiling_usd',security.pipeline_num_v1('budgets.ai_daily_ceiling_usd', 14)));
      v_ok:=array_append(v_ok,'budgets');
    exception when others then
      v_ok:=array_append(v_ok,'budgets');
      v_found:=v_found||security.platform_health_issue_v1('budgets:check_error','warning','budgets','The budget check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('budgets',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.10 database size and connections
  if security.platform_health_due_v1('db_capacity',p_force) then
    v_t:=clock_timestamp();
    begin
      v_n:=pg_database_size(current_database());
      select p.database_warn_bytes, p.database_high_bytes, p.database_critical_bytes into v_n2, v_n3, v_num
        from pipeline.platform_capacity_policy p order by (p.environment='production') desc, (p.environment='pilot') desc limit 1;
      if v_num is not null and v_n>=v_num then
        v_found:=v_found||security.platform_health_issue_v1('db_capacity:size','critical','storage/DB','Database is '||pg_size_pretty(v_n)||', over the critical level of '||pg_size_pretty(v_num::bigint),jsonb_build_object('bytes',v_n,'warn',v_n2,'high',v_n3,'critical',v_num));
      elsif v_n3 is not null and v_n>=v_n3 then
        v_found:=v_found||security.platform_health_issue_v1('db_capacity:size','warning','storage/DB','Database is '||pg_size_pretty(v_n)||', over the high level of '||pg_size_pretty(v_n3),jsonb_build_object('bytes',v_n,'warn',v_n2,'high',v_n3,'critical',v_num));
      elsif v_n2 is not null and v_n>=v_n2 then
        v_found:=v_found||security.platform_health_issue_v1('db_capacity:size','info','storage/DB','Database is '||pg_size_pretty(v_n)||', over the watch level of '||pg_size_pretty(v_n2),jsonb_build_object('bytes',v_n,'warn',v_n2,'high',v_n3,'critical',v_num));
      end if;
      select count(*), count(*) filter (where state='active') into v_n2, v_n3 from pg_stat_activity where backend_type='client backend';
      v_num2:=current_setting('max_connections')::numeric;  -- 16 Oct 2026: the live limit (the profile said 60 after the move to Medium)
      v_num2:=coalesce(v_num2, current_setting('max_connections')::numeric);
      if v_n2>=0.9*v_num2 then
        v_found:=v_found||security.platform_health_issue_v1('db_capacity:connections','critical','storage/DB',v_n2||' of '||v_num2||' database connections in use',jsonb_build_object('connections',v_n2,'active',v_n3,'max',v_num2));
      elsif v_n2>=0.75*v_num2 then
        v_found:=v_found||security.platform_health_issue_v1('db_capacity:connections','warning','storage/DB',v_n2||' of '||v_num2||' database connections in use',jsonb_build_object('connections',v_n2,'active',v_n3,'max',v_num2));
      end if;
      v_det:=v_det||jsonb_build_object('db_capacity',jsonb_build_object('db_bytes',v_n,'db_size',pg_size_pretty(v_n),'connections',v_n2,'active_connections',v_n3,'max_connections',v_num2,
        'compute_size',(select compute_size from pipeline.platform_compute_profile where id=1)));
      v_ok:=array_append(v_ok,'db_capacity');
    exception when others then
      v_ok:=array_append(v_ok,'db_capacity');
      v_found:=v_found||security.platform_health_issue_v1('db_capacity:check_error','warning','storage/DB','The database capacity check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('db_capacity',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.11 search probe
  if security.platform_health_due_v1('search_probe',p_force) and (p_force or not ('consumer_snapshot'=any(v_ok))) then
    v_t:=clock_timestamp();
    begin
      v_x:=public.website_edge_course_search_v1('{}'::jsonb,1,5);
      v_num:=round(extract(epoch from clock_timestamp()-v_t)*1000);
      if v_x is null or not (v_x ? 'items') then
        v_found:=v_found||security.platform_health_issue_v1('search_probe:bad_response','critical','search/API','Course search returned an unexpected response',jsonb_build_object('ms',v_num,'keys',(select jsonb_agg(k) from jsonb_object_keys(coalesce(v_x,'{}'::jsonb)) k)));
      elsif v_num>3000 then
        v_found:=v_found||security.platform_health_issue_v1('search_probe:slow','warning','search/API','Course search took '||v_num||' ms (limit 3,000 ms)',jsonb_build_object('ms',v_num));
      end if;
      v_det:=v_det||jsonb_build_object('search_probe',jsonb_build_object('ms',v_num,'items',jsonb_array_length(coalesce(v_x->'items','[]'::jsonb))));
      v_ok:=array_append(v_ok,'search_probe');
    exception when others then
      v_ok:=array_append(v_ok,'search_probe');
      v_found:=v_found||security.platform_health_issue_v1('search_probe:check_error','critical','search/API','Course search failed',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('search_probe',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.12 reference bundle cache
  if security.platform_health_due_v1('reference_bundle',p_force) then
    v_t:=clock_timestamp();
    begin
      select max(built_at) into v_ts from pipeline.consumer_reference_bundle_cache;
      if v_ts is null or v_ts<now()-interval '6 hours' then  -- fixed: health check observation window
        v_found:=v_found||security.platform_health_issue_v1('reference_bundle:stale','critical','search/API',
          'Consumer reference bundle has not been rebuilt '||case when v_ts is null then 'at all' else 'since '||to_char(v_ts at time zone 'UTC','DD Mon HH24:MI')||' UTC' end,jsonb_build_object('built_at',v_ts));
      elsif v_ts<now()-interval '2 hours' then  -- fixed: health check observation window
        v_found:=v_found||security.platform_health_issue_v1('reference_bundle:stale','warning','search/API',
          'Consumer reference bundle is '||round(extract(epoch from now()-v_ts)/3600.0,1)||' hours old (rebuilt hourly)',jsonb_build_object('built_at',v_ts));
      end if;
      v_det:=v_det||jsonb_build_object('reference_bundle',jsonb_build_object('built_at',v_ts));
      v_ok:=array_append(v_ok,'reference_bundle');
    exception when others then
      v_ok:=array_append(v_ok,'reference_bundle');
      v_found:=v_found||security.platform_health_issue_v1('reference_bundle:check_error','warning','search/API','The reference bundle check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('reference_bundle',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.13 nightly scholarship publication review
  if security.platform_health_due_v1('scholarship_review',p_force) then
    v_t:=clock_timestamp();
    begin
      select j.jobid, j.active, j.schedule into r from cron.job j where j.jobname='scholarship-publication-review';
      if r.jobid is null or not r.active then
        v_found:=v_found||security.platform_health_issue_v1('scholarship_review:missing','warning','scholarships','The nightly scholarship publication review is not scheduled','{}'::jsonb);
        v_det:=v_det||jsonb_build_object('scholarship_review',jsonb_build_object('scheduled',false));
      else
        select max(d.start_time) filter (where d.status='succeeded'), max(d.start_time) into v_ts, v_ts2 from cron.job_run_details d where d.jobid=r.jobid;
        select d.status, left(d.return_message,200) into v_txt, v_args from cron.job_run_details d where d.jobid=r.jobid order by d.start_time desc limit 1;
        if v_txt='failed' then
          v_found:=v_found||security.platform_health_issue_v1('scholarship_review:failed','warning','scholarships','The last nightly scholarship publication review failed',jsonb_build_object('at',v_ts2,'error',v_args));
        end if;
        v_ts2:=coalesce(v_ts,(select min(d.start_time) from cron.job_run_details d where d.jobid>r.jobid));
        if v_ts2 is not null and v_ts2<now()-interval '26 hours' then  -- fixed: health check observation window
          v_found:=v_found||security.platform_health_issue_v1('scholarship_review:not_run','warning','scholarships',
            'The nightly scholarship publication review has not completed '||case when v_ts is null then 'since it was scheduled' else 'since '||to_char(v_ts at time zone 'UTC','DD Mon HH24:MI')||' UTC' end,
            jsonb_build_object('last_success',v_ts,'schedule',r.schedule));
        end if;
        v_det:=v_det||jsonb_build_object('scholarship_review',jsonb_build_object('scheduled',true,'schedule',r.schedule,'last_success',v_ts,'last_status',v_txt));
      end if;
      v_ok:=array_append(v_ok,'scholarship_review');
    exception when others then
      v_ok:=array_append(v_ok,'scholarship_review');
      v_found:=v_found||security.platform_health_issue_v1('scholarship_review:check_error','warning','scholarships','The scholarship review check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('scholarship_review',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- CF-247 21 Oct 2026: fields below target that are not moving, by country; fields with no reader; the standing queue not running
  if security.platform_health_due_v1('field_stalled',p_force) then
    v_t:=clock_timestamp();
    begin
      perform security.field_coverage_record_v1();
      v_x:=security.field_stalled_v1();
      for r in select x->>'country' cc, count(*) filter (where x->>'reason'='flat') flat, count(*) filter (where x->>'reason'='behind') behind,
                      string_agg(case when x->>'reason' in ('flat','behind') then (x->>'label')||' '||(x->>'pct')||'%' end, ', ' order by (x->>'reason'), (x->>'label')) fields,
                      jsonb_agg(jsonb_build_object('field',x->>'field','pct',x->'pct','target',x->'target','moved',x->'moved','reason',x->>'reason','cause',x->>'cause') order by x->>'field') filter (where x->>'reason' in ('flat','behind')) det
                 from jsonb_array_elements(v_x) x group by 1 loop
        if r.flat+r.behind>0 then
          v_found:=v_found||security.platform_health_issue_v1('field_stalled:'||r.cc, case when r.flat>0 then 'warning' else 'info' end, 'coverage sweep',
            coalesce((select k.name from ref.countries k where k.iso_alpha2=r.cc limit 1), r.cc)||': '||(r.flat+r.behind)||' field(s) below target and '||
            case when r.flat>0 then 'not moving' else 'behind other countries' end||' ('||r.fields||')',
            jsonb_build_object('country',r.cc,'flat',r.flat,'behind',r.behind,'fields',r.det,'resolve','Coverage › Attributes › Stalled fields'));
        end if;
      end loop;
      select string_agg(distinct x->>'label', ', ') into v_txt from jsonb_array_elements(v_x) x where x->>'reason'='no_reader';
      if v_txt is not null then
        v_found:=v_found||security.platform_health_issue_v1('field_stalled:no_reader','info','coverage sweep','Fields with a target but no reader yet: '||v_txt,
          jsonb_build_object('fields',v_txt,'resolve','Build a reader, or set the target to 0 on Coverage › Attributes'));
      end if;
      if (select enabled from pipeline.field_gap_queue_control where id=1) then
        select max(d.start_time) into v_ts from cron.job_run_details d join cron.job j on j.jobid=d.jobid where j.jobname='field-gap-queue' and d.status='succeeded';
        if not exists (select 1 from cron.job j where j.jobname='field-gap-queue' and j.active)
           or coalesce(v_ts, (select min(d.start_time) from cron.job_run_details d where d.jobid>(select j.jobid from cron.job j where j.jobname='field-gap-queue'))) < now()-make_interval(hours=>security.pipeline_num_v1('stall.queue_hours',7)::int) then
          v_found:=v_found||security.platform_health_issue_v1('field_stalled:queue','warning','coverage sweep','Fill the gaps (standing queue) is switched on but has not run since '||coalesce(to_char(v_ts at time zone 'Australia/Melbourne','DD Mon HH24:MI'),'it was scheduled'),
            jsonb_build_object('last_success',v_ts,'resolve','Scheduled jobs › field-gap-queue; Check now on Coverage › Attributes'));
        end if;
      end if;
      v_det:=v_det||jsonb_build_object('field_stalled',jsonb_build_object('flat',(select count(*) from jsonb_array_elements(v_x) x where x->>'reason'='flat'),
                                                                         'behind',(select count(*) from jsonb_array_elements(v_x) x where x->>'reason'='behind'),
                                                                         'no_reader',(select count(*) from jsonb_array_elements(v_x) x where x->>'reason'='no_reader')));
      v_ok:=array_append(v_ok,'field_stalled');
    exception when others then
      v_ok:=array_append(v_ok,'field_stalled');
      v_found:=v_found||security.platform_health_issue_v1('field_stalled:check_error','warning','coverage sweep','The stalled fields check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('field_stalled',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.15 SS-014B (31 Oct 2026): search refresh requests. Slow = waiting past the target for a known reason (the refresh gap, another
  -- writer); stalled = nothing is processing them (job missing, paused, failing or not running) or waiting past the stalled limit.
  if security.platform_health_due_v1('search_refresh',p_force) then
    v_t:=clock_timestamp();
    begin
      select count(*), min(q.requested_at) into v_n, v_ts from search.refresh_requests q where q.processed_at is null;
      select max(q.processed_at) into v_ts2 from search.refresh_requests q where q.processed_at is not null;
      v_num:=coalesce(round(extract(epoch from now()-v_ts)/60),0);
      select j.jobid, j.active, j.schedule into r from cron.job j where j.jobname='search-refresh-requested';
      v_x:=null; v_q:=null;
      select jsonb_build_object('at',d.start_time,'status',d.status,'result',left(d.return_message,200)) into v_x
        from cron.job_run_details d where d.jobid=r.jobid order by d.start_time desc limit 1;
      select jsonb_build_object('pid',a.pid,'since',coalesce(a.xact_start,a.query_start),'query',left(regexp_replace(a.query,'\s+',' ','g'),120)) into v_q
        from pg_locks l join pg_stat_activity a on a.pid=l.pid
       where l.locktype='advisory' and l.granted and l.objsubid=1 and l.objid=((hashtext('cf247:search_course_documents_writer')::bigint) & 4294967295)::oid limit 1;  -- fixed: the one writer lock (W27)
      v_txt:=case when r.jobid is null then 'job_missing' when not r.active then 'job_paused'
                  when v_x->>'status'='failed' then 'job_failing'
                  when v_x is null or (v_x->>'at')::timestamptz < now()-make_interval(secs=>3*coalesce(security.platform_cron_interval_seconds(r.schedule),600)) then 'job_not_running'  -- fixed: three missed runs
                  when v_q is not null or v_x->>'result' ilike '%another search-document writer%' then 'writer_busy'
                  when v_x->>'result' ilike '%refresh gap%' then 'refresh_gap'
                  else 'waiting_for_next_run' end;
      if v_n>0 and v_num>security.pipeline_num_v1('health.search_refresh_slow_minutes', 40) then
        v_bool:=v_num>security.pipeline_num_v1('health.search_refresh_stalled_minutes', 90) or v_txt in ('job_missing','job_paused','job_failing','job_not_running');
        v_args:=case v_txt
          when 'job_missing' then 'Schedule the job search-refresh-requested again (Automations); the requests are kept and are processed at its first run.'
          when 'job_paused' then 'Switch on the job search-refresh-requested (Automations); the requests are kept and are processed at its next run.'
          when 'job_failing' then 'Its last run failed ('||coalesce(v_x->>'result','no message')||'). Fix the error; the requests are kept and are processed at the next successful run.'
          when 'job_not_running' then 'The job is switched on but has not run since '||coalesce(to_char((v_x->>'at')::timestamptz at time zone 'Australia/Melbourne','DD Mon HH24:MI'),'it was scheduled')||'. Check the scheduler and the database connections.'
          when 'writer_busy' then 'Another search-document writer holds the writer lock'||coalesce(' since '||to_char((v_q->>'since')::timestamptz at time zone 'Australia/Melbourne','HH24:MI')||' (process '||(v_q->>'pid')||')','')||'. The requests are processed when it finishes; if it has run for over an hour, look at that writer.'
          when 'refresh_gap' then 'Automatic requests wait for the refresh gap (setting search.refresh_min_gap_minutes, '||security.pipeline_num_v1('search.refresh_min_gap_minutes', 30)||' minutes). No action unless the gap was raised by mistake.'
          else 'The job ran without processing them; they are processed at its next run. If this persists, look at its last result.' end;
        v_found:=v_found||security.platform_health_issue_v1('search_refresh:waiting', case when v_bool then 'critical' else 'warning' end, 'search/API',
          'Search refresh '||case when v_bool then 'has stalled' else 'is slow' end||': '||v_n||' request(s) waiting, the oldest for '||v_num||' minutes ('||replace(v_txt,'_',' ')||')',
          jsonb_build_object('pending',v_n,'oldest_requested_at',v_ts,'oldest_minutes',v_num,'cause',v_txt,'next_step',v_args,'last_processed_at',v_ts2,
            'job_active',coalesce(r.active,false),'last_run',v_x,'writer',v_q,
            'slow_after_minutes',security.pipeline_num_v1('health.search_refresh_slow_minutes', 40),'stalled_after_minutes',security.pipeline_num_v1('health.search_refresh_stalled_minutes', 90)));
      end if;
      v_det:=v_det||jsonb_build_object('search_refresh',jsonb_build_object('pending',v_n,'oldest_minutes',case when v_n>0 then v_num end,'last_processed_at',v_ts2,'cause',case when v_n>0 then v_txt end));
      v_ok:=array_append(v_ok,'search_refresh');
    exception when others then
      v_ok:=array_append(v_ok,'search_refresh');
      v_found:=v_found||security.platform_health_issue_v1('search_refresh:check_error','warning','search/API','The search refresh check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('search_refresh',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 4.16 SS-014C (31 Oct 2026): the alert outbox itself: deliveries that failed, and alerts nobody collects while delivery is on
  if security.platform_health_due_v1('alerts',p_force) then
    v_t:=clock_timestamp();
    begin
      select count(*) filter (where a.status='failed' and a.created_at>=now()-interval '24 hours'),  -- fixed: health check observation window
             count(*) filter (where a.status in ('pending','sending')), min(a.created_at) filter (where a.status in ('pending','sending')),
             count(*) filter (where a.status='held' and a.created_at>=now()-interval '24 hours')  -- fixed: health check observation window
        into v_n, v_n2, v_ts, v_n3 from pipeline.platform_alerts a;
      v_bool:=coalesce((security.toolset_setting('pipeline','alerts.delivery_enabled') #>> '{}')::boolean,false);
      if v_n>0 then
        v_found:=v_found||security.platform_health_issue_v1('alerts:delivery_failed','warning','scheduled jobs',
          v_n||' alert(s) could not be delivered in the last 24 hours (every attempt used)',jsonb_build_object('failed_24h',v_n,'resolve','Platform health › Alerts'));
      end if;
      if v_bool and v_n2>0 and v_ts<now()-make_interval(mins=>security.pipeline_num_v1('alerts.collect_within_minutes', 120)::int) then
        v_found:=v_found||security.platform_health_issue_v1('alerts:not_collected','critical','scheduled jobs',
          v_n2||' alert(s) have waited since '||to_char(v_ts at time zone 'Australia/Melbourne','DD Mon HH24:MI')||': the alert destination is not collecting them',
          jsonb_build_object('waiting',v_n2,'since',v_ts,'resolve','Check the alert destination (scheduled task or webhook)'));
      end if;
      v_det:=v_det||jsonb_build_object('alerts',jsonb_build_object('delivery',case when v_bool then 'on' else 'off (recorded only)' end,'waiting',v_n2,'held_24h',v_n3,'failed_24h',v_n,
        'last_sent_at',(select max(a.sent_at) from pipeline.platform_alerts a)));
      v_ok:=array_append(v_ok,'alerts');
    exception when others then
      v_ok:=array_append(v_ok,'alerts');
      v_found:=v_found||security.platform_health_issue_v1('alerts:check_error','warning','scheduled jobs','The alert outbox check could not run',jsonb_build_object('error',left(sqlerrm,300)));
    end;
    v_ms:=v_ms||jsonb_build_object('alerts',round(extract(epoch from clock_timestamp()-v_t)*1000));
  end if;

  -- 5. record issues (dedup on check_key), auto-resolve what cleared, store check status
  for r in select distinct on (x.check_key) x.check_key, x.severity, x.area, x.title, x.detail
             from jsonb_to_recordset(v_found) x(check_key text, severity text, area text, title text, detail jsonb)
            order by x.check_key, case x.severity when 'critical' then 1 when 'warning' then 2 else 3 end loop
    insert into pipeline.platform_issues as i (check_key,severity,area,title,detail)
    values (r.check_key, r.severity, r.area, left(r.title,300), coalesce(r.detail,'{}'::jsonb))
    on conflict (check_key) where resolved_at is null do update set
      severity=excluded.severity, area=excluded.area, title=excluded.title, detail=excluded.detail,
      last_seen=now(), occurrences=i.occurrences+1,
      acknowledged_at=case when (case excluded.severity when 'critical' then 1 when 'warning' then 2 else 3 end) < (case i.severity when 'critical' then 1 when 'warning' then 2 else 3 end) then null else i.acknowledged_at end,
      acknowledged_by=case when (case excluded.severity when 'critical' then 1 when 'warning' then 2 else 3 end) < (case i.severity when 'critical' then 1 when 'warning' then 2 else 3 end) then null else i.acknowledged_by end,
      acknowledged_note=case when (case excluded.severity when 'critical' then 1 when 'warning' then 2 else 3 end) < (case i.severity when 'critical' then 1 when 'warning' then 2 else 3 end) then null else i.acknowledged_note end;
  end loop;

  update pipeline.platform_issues i set resolved_at=now()
   where i.resolved_at is null and split_part(i.check_key,':',1)=any(v_ok)
     and not exists (select 1 from jsonb_array_elements(v_found) f where f->>'check_key'=i.check_key);

  update pipeline.platform_health_checks c set
    status=case when c.key='edge_deployed' then 'skipped'
                else coalesce((select case min(case f->>'severity' when 'critical' then 1 when 'warning' then 2 else 3 end) when 1 then 'critical' when 2 then 'warning' else 'ok' end
                                 from jsonb_array_elements(v_found) f where split_part(f->>'check_key',':',1)=c.key),'ok') end,
    detail=coalesce(v_det->c.key, c.detail), checked_at=now(), duration_ms=(v_ms->>c.key)::numeric::int
   where c.key=any(v_ok);

  delete from pipeline.platform_edge_calls where created_at<now()-interval '2 days';  -- fixed: health check log retention
  delete from pipeline.platform_health_runs where started_at<now()-interval '14 days';  -- fixed: health check log retention
  delete from pipeline.platform_issues where resolved_at<now()-interval '90 days';  -- fixed: health check log retention

  select jsonb_build_object('critical',count(*) filter (where severity='critical'),'warning',count(*) filter (where severity='warning'),'info',count(*) filter (where severity='info'))
    into v_counts from pipeline.platform_issues where resolved_at is null;
  insert into pipeline.platform_health_runs(started_at,duration_ms,checks_ran,check_ms,counts)
  values (v_t0, round(extract(epoch from clock_timestamp()-v_t0)*1000), v_ok, v_ms, v_counts);
  return jsonb_build_object('ran',to_jsonb(v_ok),'duration_ms',round(extract(epoch from clock_timestamp()-v_t0)*1000),'check_ms',v_ms,'open',v_counts,'found',jsonb_array_length(v_found));
end $_$;


ALTER FUNCTION "security"."platform_health_check_v1"("p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_health_due_v1"("p_key" "text", "p_force" boolean) RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
  select p_force or coalesce((select c.checked_at is null
                                  or c.checked_at <= now() - make_interval(mins=>c.cadence_minutes) + least(interval '3 minutes', make_interval(mins=>c.cadence_minutes)*0.3)
                               from pipeline.platform_health_checks c where c.key=p_key), true)
$$;


ALTER FUNCTION "security"."platform_health_due_v1"("p_key" "text", "p_force" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_health_issue_v1"("p_key" "text", "p_severity" "text", "p_area" "text", "p_title" "text", "p_detail" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$ select jsonb_build_object('check_key',p_key,'severity',p_severity,'area',p_area,'title',p_title,'detail',coalesce(p_detail,'{}'::jsonb)) $$;


ALTER FUNCTION "security"."platform_health_issue_v1"("p_key" "text", "p_severity" "text", "p_area" "text", "p_title" "text", "p_detail" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_health_stall_v1"("p_key" "text", "p_area" "text", "p_label" "text", "p_job" "text", "p_last_progress" timestamp with time zone, "p_pending_sql" "text", "p_default_interval_s" integer DEFAULT 600) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security', 'public', 'catalogue', 'scholarship'
    AS $$
declare v_int int; v_active boolean; v_warn interval; v_crit interval; v_pending bigint; v_age interval:=now()-coalesce(p_last_progress,'-infinity'::timestamptz); v_unit boolean:=false;
begin
  select security.platform_cron_interval_seconds(j.schedule), j.active into v_int, v_active from cron.job j where j.jobname=p_job;
  v_int:=coalesce(v_int,p_default_interval_s);
  v_warn:=greatest(make_interval(secs=>3*v_int), interval '15 minutes');
  v_crit:=greatest(make_interval(secs=>12*v_int), interval '2 hours');
  if v_age <= v_warn then
    return jsonb_build_object('queue',p_key,'status','moving','last_progress',p_last_progress);
  end if;
  execute p_pending_sql into v_pending;
  if coalesce(v_pending,0)=0 then
    return jsonb_build_object('queue',p_key,'status','idle','pending',0,'last_progress',p_last_progress);
  end if;
  -- SS-014 (31 Oct 2026): a job the flag unit paused because its runs found nothing is switched on again by the flag unit when work
  -- waits (security.flag_jobs_v1, security.waste_idle_guard_v1); until the critical age that is information, not a breakage
  if v_active is false then
    select true into v_unit from pipeline.enrichment_flags f
     where f.entity='job' and f.entity_key=p_job and f.field='' and f.reason_code='idle_paused' and f.cleared_at is null and coalesce(f.state,'raised')='raised' limit 1;
    v_unit:=coalesce(v_unit,false);
  end if;
  return jsonb_build_object('queue',p_key,'status','stalled','pending',v_pending,'last_progress',p_last_progress,
    'job',p_job,'job_active',coalesce(v_active,false),'paused_by_flag_unit',v_unit,'stalled_minutes',round(extract(epoch from least(v_age, interval '365 days'))/60),
    'threshold_minutes',round(extract(epoch from v_warn)/60),
    'issue',security.platform_health_issue_v1(p_key,
      case when v_age>v_crit or (coalesce(v_active,false)=false and not v_unit) then 'critical' when v_unit then 'info' else 'warning' end, p_area,
      p_label||' has stopped: '||v_pending||' waiting, nothing processed for '||
        case when p_last_progress is null then 'as long as records exist' else round(extract(epoch from v_age)/60)||' minutes' end||
        case when v_unit then ' (its job is paused because its recent runs found nothing; the flag unit switches it on again when work is waiting)' when v_active is distinct from true then ' (its scheduled job is missing or paused)' else '' end,
      jsonb_build_object('pending',v_pending,'last_progress',p_last_progress,'job',p_job,'job_active',coalesce(v_active,false),
        'threshold_minutes',round(extract(epoch from v_warn)/60))));
end $$;


ALTER FUNCTION "security"."platform_health_stall_v1"("p_key" "text", "p_area" "text", "p_label" "text", "p_job" "text", "p_last_progress" timestamp with time zone, "p_pending_sql" "text", "p_default_interval_s" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_health_state_v1"("p_detail" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline'
    AS $$
  select jsonb_build_object(
    'generated_at', now(),
    'overall', coalesce((select case min(case severity when 'critical' then 1 when 'warning' then 2 else 3 end) when 1 then 'critical' when 2 then 'warning' else 'ok' end
                           from pipeline.platform_issues where resolved_at is null and acknowledged_at is null),'ok'),
    'counts', (select jsonb_build_object('critical',count(*) filter (where severity='critical'),'warning',count(*) filter (where severity='warning'),'info',count(*) filter (where severity='info'))
                 from pipeline.platform_issues where resolved_at is null),
    'issues', coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'check_key',i.check_key,'severity',i.severity,'area',i.area,'title',i.title,
                           'detail',case when p_detail then i.detail else '{}'::jsonb end,'first_seen',i.first_seen,'last_seen',i.last_seen,
                           'occurrences',i.occurrences,'acknowledged_at',i.acknowledged_at) order by i.rk, i.last_seen desc)
                          from (select p.*, case p.severity when 'critical' then 1 when 'warning' then 2 else 3 end rk from pipeline.platform_issues p
                                 where p.resolved_at is null order by rk, p.last_seen desc limit 200) i),'[]'::jsonb),
    'checks', coalesce((select jsonb_agg(jsonb_build_object('key',c.key,'area',c.area,'label',c.label,'status',c.status,
                           'detail',case when p_detail then c.detail else '{}'::jsonb end,'checked_at',c.checked_at,'cadence_minutes',c.cadence_minutes) order by c.sort_order)
                          from pipeline.platform_health_checks c),'[]'::jsonb),
    'history', (select jsonb_agg(jsonb_build_object('day',to_char(g.d,'YYYY-MM-DD'),
                   'critical',(select count(*) from pipeline.platform_issues i where i.severity='critical' and i.first_seen<(g.d at time zone 'UTC')+interval '1 day' and coalesce(i.resolved_at,'infinity'::timestamptz)>=(g.d at time zone 'UTC')),
                   'warning',(select count(*) from pipeline.platform_issues i where i.severity='warning' and i.first_seen<(g.d at time zone 'UTC')+interval '1 day' and coalesce(i.resolved_at,'infinity'::timestamptz)>=(g.d at time zone 'UTC'))) order by g.d)
                  from generate_series(((now() at time zone 'UTC')::date-13)::timestamp,((now() at time zone 'UTC')::date)::timestamp,interval '1 day') g(d)))
$$;


ALTER FUNCTION "security"."platform_health_state_v1"("p_detail" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_health_summary_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'security'
    AS $$
declare v jsonb:=security.platform_health_state_v1(true); v_at timestamptz; v_ms int; v_lines text[]; e jsonb; v_res bigint;
begin
  select started_at, duration_ms into v_at, v_ms from pipeline.platform_health_runs order by started_at desc limit 1;
  select count(*) into v_res from pipeline.platform_issues where resolved_at>=now()-interval '24 hours';
  v_lines:=array['Platform health: '||upper(v->>'overall')||' - '||(v->'counts'->>'critical')||' critical, '||(v->'counts'->>'warning')||' warning, '||(v->'counts'->>'info')||' info open issue(s); '||v_res||' resolved in the last 24 hours.',
                 'Last health run: '||coalesce(to_char(v_at at time zone 'Asia/Kolkata','DD Mon HH24:MI')||' IST ('||v_ms||' ms)','never')||'.'];
  for e in select x from jsonb_array_elements(v->'issues') x limit 15 loop
    v_lines:=v_lines||('- ['||(e->>'severity')||'] '||(e->>'area')||': '||(e->>'title')||' (since '||to_char((e->>'first_seen')::timestamptz at time zone 'Asia/Kolkata','DD Mon HH24:MI')||' IST'
                       ||case when e->>'acknowledged_at' is not null then ', acknowledged' else '' end||')');
  end loop;
  if jsonb_array_length(v->'issues')=0 then v_lines:=v_lines||'- No open issues.'::text;
  elsif jsonb_array_length(v->'issues')>15 then v_lines:=v_lines||('- ... and '||(jsonb_array_length(v->'issues')-15)||' more.'); end if;
  return jsonb_build_object('generated_at',now(),'overall',v->'overall','counts',v->'counts','resolved_24h',v_res,'last_run_at',v_at,'last_run_ms',v_ms,
    'text',array_to_string(v_lines,E'\n'),'issues',v->'issues','checks',v->'checks');
end $$;


ALTER FUNCTION "security"."platform_health_summary_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_notices_cached_v1"("p_with_samples" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_s pipeline.admin_read_snapshots%rowtype;
begin
  select * into v_s from pipeline.admin_read_snapshots s where s.key = 'platform_notices';
  if v_s.key is null then
    -- before the first build only: read live, exactly as before W35
    return coalesce(security.platform_notices_v1(), '[]'::jsonb) || case when p_with_samples then coalesce(security.toolset_sample_notices_v1(), '[]'::jsonb) else '[]'::jsonb end;
  end if;
  return coalesce((
    select jsonb_agg(x.n order by x.o)
      from (select e.o, e.n ? 'items' had_items, it.items,
                   e.n
                   -- a notice its builder stamped "now" is still "now" (so an acknowledgement before this moment does not hide it, as before)
                   || case when (e.n->>'last_at')::timestamptz = v_s.stamp then jsonb_build_object('last_at', now()) else '{}'::jsonb end
                   || case when (e.n->>'first_at')::timestamptz = v_s.stamp then jsonb_build_object('first_at', now()) else '{}'::jsonb end
                   || case when it.items is not null and jsonb_array_length(it.items) < jsonb_array_length(e.n->'items')
                           then jsonb_build_object('items', it.items, 'count', greatest(coalesce((e.n->>'count')::int, 0) - (jsonb_array_length(e.n->'items') - jsonb_array_length(it.items)), 0))
                           else '{}'::jsonb end n
              from jsonb_array_elements(coalesce(v_s.payload->'notices', '[]'::jsonb)
                                        || case when p_with_samples then coalesce(v_s.payload->'samples', '[]'::jsonb) else '[]'::jsonb end) with ordinality e(n, o)
              left join lateral (
                -- exact drill-down: a university a person resumed since the snapshot, or a provider given a website since, leaves the list now
                select coalesce(jsonb_agg(i.v order by i.k), '[]'::jsonb) items
                  from jsonb_array_elements(e.n->'items') with ordinality i(v, k)
                 where not (e.n->>'kind' in ('search_held', 'search_stopped')
                            and exists (select 1 from pipeline.firecrawl_search_resumes r where r.provider_id = (i.v->>'provider_id')::uuid and r.resumed_at > v_s.stamp))
                   and not (e.n->>'kind' = 'no_official_site'
                            and exists (select 1 from catalogue.providers p where p.id = (i.v->>'provider_id')::uuid and nullif(btrim(p.website), '') is not null))
              ) it on jsonb_typeof(e.n->'items') = 'array') x
     where not (x.had_items and jsonb_array_length(x.items) = 0)), '[]'::jsonb);
end $$;


ALTER FUNCTION "security"."platform_notices_cached_v1"("p_with_samples" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_notices_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  w_or int := coalesce((security.toolset_setting('openrouter', 'notice_window_hours'))::text::int, 24);
  w_job int := coalesce((security.toolset_setting('scheduled_jobs', 'notice_window_hours'))::text::int, 24);
  w_edge int := coalesce((security.toolset_setting('edge_functions', 'notice_window_hours'))::text::int, 6);
  v_or_mode text := coalesce((select t.enforcement from pipeline.platform_toolsets t where t.key = 'openrouter'), 'stop');
  v jsonb := '[]'::jsonb;
begin
  -- v2.15.258 (bug 12/10-01): OpenRouter notices for the AI uses that run now (Layer 3 retired on 12 Oct 2026). Refused calls
  v := v || coalesce((select jsonb_agg(jsonb_build_object(
      'key', 'openrouter:2:refused:' || z.code, 'layer', 2, 'toolset', 'openrouter', 'kind', 'refused', 'severity', 'high',
      'title', case z.code when 'credit' then 'OpenRouter refused calls: out of credit'
                           when 'key_limit' then 'OpenRouter refused calls: the key''s own spending limit was reached'
                           when 'rate' then 'OpenRouter refused calls: rate limit'
                           else 'OpenRouter refused calls: key not accepted' end,
      'detail', format('%s AI calls in the last %s hours were refused; those pages are read again later.', z.n, w_or),
      'hint', case z.code when 'credit' then 'Top up the OpenRouter balance; the refused pages are read again by themselves.'
                          when 'key_limit' then 'The limit is set on the key at OpenRouter (Workspaces › Keys), not in StudySearch. Raise or clear it there.'
                          when 'rate' then 'Usually clears by itself; the pages are read again.'
                          else 'Check the OpenRouter key on Settings.' end,
      'count', z.n, 'first_at', z.first_at, 'last_at', z.last_at))
    from (select case when r.e ilike '%key limit%' or r.e ilike '%weekly limit%' then 'key_limit' when r.e ~ 'HTTP 402' or r.e ilike '%credit%' then 'credit'
                      when r.e ~ 'HTTP 429' then 'rate' else 'key' end code, count(*) n, min(r.at) first_at, max(r.at) last_at
          from (select x.error e, x.at from pipeline.scholarship_ai_extractions x where x.at > now() - make_interval(hours => w_or) and x.error ~ 'HTTP (40[123]|429)'
                union all
                select q.error, coalesce(q.done_at, q.created_at) from pipeline.central_ai_queue q where q.created_at > now() - make_interval(hours => w_or) and q.error ~ 'HTTP (40[123]|429)') r
          group by 1) z), '[]'::jsonb);

  -- OpenRouter balance: below the warning level, below the credit floor, or not read recently (read by the openrouter-balance job)
  v := v || coalesce((select jsonb_agg(x) from (
    select jsonb_build_object('key', 'openrouter:2:low_balance', 'layer', 2, 'toolset', 'openrouter', 'kind', 'low_balance',
      'severity', case when o.remaining_usd < coalesce((security.toolset_setting('openrouter', 'credit_floor_usd'))::text::numeric, 0) then 'high' else 'warning' end,
      'title', format('OpenRouter balance is US$%s', round(o.remaining_usd, 2)),
      'detail', case when o.remaining_usd < coalesce((security.toolset_setting('openrouter', 'credit_floor_usd'))::text::numeric, 0)
                     then format('Below the credit floor of US$%s. AI is set to %s.', security.toolset_setting('openrouter', 'credit_floor_usd'),
                                 case v_or_mode when 'observe' then 'observe only, so it keeps running until OpenRouter refuses calls' else 'stop at limits, so the scholarship AI and central pages AI have stopped' end)
                     else format('Below the warning level of US$%s. AI is set to %s.', security.toolset_setting('openrouter', 'low_balance_warn_usd'),
                                 case v_or_mode when 'observe' then 'observe only' else 'stop at limits' end) end,
      'hint', 'Top up the OpenRouter account the platform''s key uses.',
      'count', 1, 'first_at', o.observed_at, 'last_at', o.observed_at) x
    from (select * from pipeline.layer3_openrouter_observations where kind = 'credits' order by observed_at desc limit 1) o
    where o.remaining_usd < greatest(coalesce((security.toolset_setting('openrouter', 'low_balance_warn_usd'))::text::numeric, 0),
                                     coalesce((security.toolset_setting('openrouter', 'credit_floor_usd'))::text::numeric, 0))
    union all
    select jsonb_build_object('key', 'openrouter:2:not_observed', 'layer', 2, 'toolset', 'openrouter', 'kind', 'not_observed', 'severity', 'warning',
      'title', 'OpenRouter balance has not been read recently',
      'detail', format('Last reading %s.', coalesce(to_char(o.observed_at at time zone 'Australia/Melbourne', 'DD Mon YYYY HH24:MI'), 'never')),
      'hint', 'The balance is read every 15 minutes by the scheduled job "Read the OpenRouter balance" (openrouter-balance); check it in Scheduled jobs.',
      'count', 1, 'first_at', o.observed_at, 'last_at', now())
    from (select max(observed_at) observed_at from pipeline.layer3_openrouter_observations where kind = 'credits') o
    where o.observed_at is null or o.observed_at < now() - make_interval(mins => coalesce((security.toolset_setting('openrouter', 'balance_stale_minutes'))::text::int, 30))
  ) q), '[]'::jsonb);

  -- An AI use past its daily guard today (UTC day)
  v := v || coalesce((select jsonb_agg(jsonb_build_object(
      'key', 'openrouter:2:over_guard:' || g.use || ':' || to_char(now() at time zone 'UTC', 'YYYY-MM-DD'), 'layer', 2, 'toolset', 'openrouter', 'kind', 'over_guard',
      'severity', case v_or_mode when 'observe' then 'info' else 'warning' end,
      'title', format('%s spent US$%s today, past its guard of US$%s', g.label, g.spent, g.guard),
      'detail', case v_or_mode when 'observe' then 'Observe only: it keeps running. This is recorded for the top-up review.'
                     else 'Stop at limits: it has stopped until the UTC day changes (adapter proposals stop at their own allowance; course-page matching is observed only).' end,
      'hint', 'Change the guard or the mode on Models & services › OpenRouter (AI models) › Daily guards.',
      'count', 1, 'first_at', now(), 'last_at', now()))
    from security.ai_spend_today_v1() g where g.guard > 0 and g.spent >= g.guard), '[]'::jsonb);

  -- Firecrawl balance, scholarship share, course-link search cap (Layer 2)
  v := v || coalesce((select jsonb_agg(x) from (
    select jsonb_build_object('key', 'firecrawl:2:low_balance', 'layer', 2, 'toolset', 'firecrawl', 'kind', 'low_balance', 'severity', 'warning',
      'title', format('Firecrawl has %s credits left this month', o.remaining_units),
      'detail', format('Below the warning level of %s. The period ends %s.', security.toolset_setting('firecrawl', 'low_balance_warn_units'), to_char(o.period_end at time zone 'Australia/Melbourne', 'DD Mon YYYY')),
      'hint', 'Firecrawl refuses work when the month''s credits are gone. Top up the Firecrawl account (Models & services › Toolsets & limits › Firecrawl credits).', 'count', 1, 'first_at', o.observed_at, 'last_at', o.observed_at) x
    from (select v2.* from pipeline.vendor_credit_observations v2 join pipeline.layer2_acquisition_providers p on p.id = v2.provider_id and p.provider_key = 'firecrawl' order by v2.observed_at desc limit 1) o
    where o.remaining_units < coalesce((security.toolset_setting('firecrawl', 'low_balance_warn_units'))::text::numeric, 0)
    union all
    -- v2.15.262: the day's Firecrawl budget (a share, or the billed total) at 80% or more
    select jsonb_build_object('key', 'firecrawl:2:daily:' || b.grp || ':' || to_char(now() at time zone 'Australia/Melbourne', 'YYYY-MM-DD'), 'layer', 2, 'toolset', 'firecrawl', 'kind', 'daily_budget',
      'severity', case when b.used >= b.cap then 'high' else 'warning' end,
      'title', format('Firecrawl daily budget, %s: %s of %s credits used', b.label, round(b.used), round(b.cap)),
      'detail', case when b.used >= b.cap then 'Used up: this work waits until midnight, Melbourne time.' else 'At 80% or more; this work stops for the day when it is used up.' end,
      'hint', 'Raise the share under Daily budget if this work should carry on today.', 'count', 1, 'first_at', now(), 'last_at', now())
    from (select 'total' grp, 'billed today' label, (st->>'billed_today')::numeric used, (st->>'total')::numeric cap, (st->>'on')::boolean is_on from security.fc_budget_status_v1() st
          union all
          select g->>'group', g->>'label', (g->>'used')::numeric, (g->>'share')::numeric, (st->>'on')::boolean
            from security.fc_budget_status_v1() st, jsonb_array_elements(st->'groups') g) b
    where b.is_on and b.cap > 0 and b.used >= 0.8 * b.cap
    union all
    select jsonb_build_object('key', 'firecrawl:2:search_stopped', 'layer', 2, 'toolset', 'firecrawl', 'kind', 'search_stopped', 'severity', 'warning',
      'title', format('Course-page search stopped for %s universit%s', s.n, case when s.n = 1 then 'y' else 'ies' end),
      'detail', format('No correct course page after %s searches. Usually the website on record is wrong or the site hides its course pages from search.', security.fc_setting_num_v1('search_stop_after', 30)),
      'hint', 'Check the website on record (correct it on the provider if it is wrong), then press Search again.', 'count', s.n, 'first_at', now(), 'last_at', now(), 'items', s.items)
    from (select count(*) n, jsonb_agg(jsonb_build_object('provider_id', f.provider_id, 'name', coalesce(p.display_name, p.canonical_name), 'website', p.website,
                                                          'searches', f.searches) order by f.searches desc, p.canonical_name) items
            from security.fc_search_stopped_v1() f join catalogue.providers p on p.id = f.provider_id
           where f.searches > 0
             and not exists (select 1 from pipeline.firecrawl_search_holds h where h.provider_id = f.provider_id
                               and not exists (select 1 from pipeline.firecrawl_search_resumes r where r.provider_id = h.provider_id and r.resumed_at > h.held_at))) s where s.n > 0
    union all
    -- v2.15.265: course search held for an adapter check, by name
    select jsonb_build_object('key', 'firecrawl:2:search_held', 'layer', 2, 'toolset', 'firecrawl', 'kind', 'search_held', 'severity', 'warning',
      'title', format('Course-page search held for %s: %s', count(*), string_agg(coalesce(p.display_name, p.canonical_name), ', ' order by p.canonical_name)),
      'detail', string_agg(coalesce(p.display_name, p.canonical_name) || ': ' || h.reason, '; ' order by p.canonical_name),
      'hint', 'Check the university''s adapter and website, then press Search again.', 'count', count(*), 'first_at', min(h.held_at), 'last_at', now(),
      'items', jsonb_agg(jsonb_build_object('provider_id', h.provider_id, 'name', coalesce(p.display_name, p.canonical_name), 'website', p.website, 'reason', h.reason) order by p.canonical_name))
    from pipeline.firecrawl_search_holds h join catalogue.providers p on p.id = h.provider_id
   where not exists (select 1 from pipeline.firecrawl_search_resumes r where r.provider_id = h.provider_id and r.resumed_at > h.held_at)
  having count(*) > 0
    union all
    -- v2.15.265: Australian providers whose official website was searched for and not found
    select jsonb_build_object('key', 'firecrawl:2:no_official_site', 'layer', 2, 'toolset', 'firecrawl', 'kind', 'no_official_site', 'severity', 'info',
      'title', format('%s Australian providers have no official website found', count(*)),
      'detail', 'Not in the CRICOS register, TEQSA or training.gov.au, and no site showing their CRICOS code. Course pages and scholarships are not searched for them.',
      'hint', 'Enter a website if you know it: the course-page search starts within minutes. Otherwise nothing to do.', 'count', count(*), 'first_at', min(d.site_searched_at), 'last_at', max(d.site_searched_at),
      'items', jsonb_agg(jsonb_build_object('provider_id', d.provider_id, 'name', coalesce(p.display_name, p.canonical_name)) order by p.canonical_name))
    from pipeline.coverage_provider_discovery d join catalogue.providers p on p.id = d.provider_id and p.lifecycle_status = 'active'
   where d.status = 'no_website' and d.site_searched_at is not null and nullif(btrim(p.website), '') is null and security.coverage_country(d.provider_id) = 'AU'
  having count(*) > 0
    union all
    -- v2.15.265: providers sharing one website (pathway colleges on their university's site): their searches read the other's pages
    select jsonb_build_object('key', 'firecrawl:2:shared_site', 'layer', 2, 'toolset', 'firecrawl', 'kind', 'shared_site', 'severity', 'info',
      'title', format('%s providers share a website with another provider', sum(z.n)),
      'detail', 'Examples: ' || string_agg(z.host, ', ' order by z.n desc) filter (where z.rk <= 5),
      'hint', 'Usually a pathway college on its university''s site. Give the college its own website, or leave it: scholarships are not searched for providers with fewer than 30 courses.', 'count', sum(z.n), 'first_at', now(), 'last_at', now())
    from (select y.host, y.n, row_number() over (order by y.n desc, y.host) rk from (
            select security.fc_spend_host_v1(p.website) host, count(*) n from catalogue.providers p
             where p.lifecycle_status = 'active' and p.website ~* '^https?://' group by 1 having count(*) > 1) y where y.host is not null) z
  having count(*) > 0
    union all
    select jsonb_build_object('key', 'firecrawl:2:scholarship_share', 'layer', 2, 'toolset', 'firecrawl', 'kind', 'cap_reached', 'severity', 'warning',
      'title', format('Scholarship Firecrawl share: %s of %s credits used', s.used, s.cap),
      'detail', format('Fewer than the reserve of %s are left, so newly found scholarship pages that refuse a direct read are not read.', s.reserve),
      'hint', 'Raise the cap on Layer 2 › Scholarships if you want them read.', 'count', 1, 'first_at', now(), 'last_at', now())
    from (select (b->>'used')::numeric used, (b->>'cap')::numeric cap, (b->>'reserve')::numeric reserve
          from (select jsonb_build_object(
                  'used', (select coalesce(sum(u.units), 0) from pipeline.coverage_vendor_usage u where u.purpose in ('sch_map', 'sch_search', 'sch_scrape')),
                  'cap', (select s2.value from pipeline.scholarship_layer_settings s2 where s2.key = 'firecrawl_cap'),
                  'reserve', (select s2.value from pipeline.scholarship_layer_settings s2 where s2.key = 'firecrawl_reserve')) b) q) s
    where s.cap - s.used <= s.reserve
    union all
    select jsonb_build_object('key', 'firecrawl:2:course_link_cap:' || to_char(now(), 'YYYY-MM'), 'layer', 2, 'toolset', 'firecrawl', 'kind', 'cap_reached', 'severity', 'warning',
      'title', format('Course-link search used %s of its %s monthly credits', l.used, l.cap),
      'detail', 'Course-link search stops for the rest of the month.', 'hint', 'Change the monthly cap on Models & services › Toolsets & limits › Course-page search budget.',
      'count', 1, 'first_at', now(), 'last_at', now())
    from (select (select monthly_credit_cap from pipeline.course_link_search_settings limit 1) cap,
                 (select coalesce(sum(u.units), 0) from pipeline.coverage_vendor_usage u where u.purpose = 'course_link_search' and u.at >= date_trunc('month', now())) used) l
    where l.used >= l.cap
  ) q), '[]'::jsonb);

  -- Scheduled jobs that timed out or failed (the job's layer)
  v := v || coalesce((select jsonb_agg(jsonb_build_object(
      'key', 'scheduled_jobs:' || z.layer || ':' || z.kind || ':' || z.jobname, 'layer', z.layer, 'toolset', 'scheduled_jobs', 'kind', z.kind,
      'severity', case when z.n >= 5 then 'high' else 'warning' end,
      'title', case z.kind when 'timeout' then format('Job "%s" hit the database time limit %s times', z.jobname, z.n)
                           else format('Job "%s" failed %s times', z.jobname, z.n) end,
      'detail', format('In the last %s hours (%s runs in all). Last message: %s', w_job, z.runs, z.msg),
      'hint', case z.kind when 'timeout' then 'Lower the job''s batch size setting so each run finishes inside the limit.' else 'Usually clears by itself (for example a deadlock); if it repeats, the job needs a fix.' end,
      'count', z.n, 'first_at', z.first_at, 'last_at', z.last_at))
    -- (11 Oct 2026: the run history is read once, last 7 days; only the jobs that failed are ranked for "last three runs succeeded")
    from (with hist as materialized (select h.jobid, h.status, h.return_message, h.start_time, h.end_time
                                       from cron.job_run_details h where h.start_time > now() - interval '7 days'), -- fixed: run history read once, last 7 days
               fd as materialized (select * from hist where status = 'failed' and end_time > now() - make_interval(hours => w_job)),
               fj as materialized (select distinct jobid from fd),
               last3 as (select f.jobid, bool_and(t.status = 'succeeded') ok, count(*) c from fj f
                           cross join lateral (select x.status from hist x where x.jobid = f.jobid and x.status in ('succeeded', 'failed')
                                               order by x.start_time desc limit 3) t group by f.jobid),
               runs as (select x.jobid, count(*) n from hist x where x.jobid in (select jobid from fj)
                          and x.end_time > now() - make_interval(hours => w_job) group by x.jobid)
          select j.jobname, coalesce(l.layer, 2) layer,
                 case when d.return_message ilike '%statement timeout%' then 'timeout' else 'failed' end kind,
                 count(*) n, min(d.end_time) first_at, max(d.end_time) last_at, left(max(d.return_message), 140) msg,
                 max(coalesce(rn.n, 0)) runs
          from fd d join cron.job j on j.jobid = d.jobid left join pipeline.platform_job_layers l on l.jobname = j.jobname
          left join last3 l3 on l3.jobid = d.jobid left join runs rn on rn.jobid = d.jobid
          where not (coalesce(l3.ok, false) and coalesce(l3.c, 0) = 3)
          group by j.jobid, j.jobname, l.layer, 3
          having count(*) >= coalesce((security.toolset_setting('scheduled_jobs', 'min_failures'))::text::int, 1)) z), '[]'::jsonb);

  -- Edge function calls that timed out (platform)
  v := v || coalesce((select jsonb_agg(jsonb_build_object(
      'key', 'edge_functions:0:timeout', 'layer', 0, 'toolset', 'edge_functions', 'kind', 'timeout', 'severity', 'warning',
      'title', format('%s edge function calls timed out or hit the worker limit', z.n),
      'detail', format('In the last %s hours.', w_edge), 'hint', 'The worker runs too long per call; lower its per-run limit.',
      'count', z.n, 'first_at', z.first_at, 'last_at', z.last_at))
    from (select count(*) n, min(r.created) first_at, max(r.created) last_at from net._http_response r
          where r.created > now() - make_interval(hours => w_edge) and (r.timed_out or r.status_code in (504, 546))) z
    where z.n >= coalesce((security.toolset_setting('edge_functions', 'min_timeouts'))::text::int, 1)), '[]'::jsonb);

  -- v2.15.269: a running job with a number written into it (it should read a setting)
  v := v || coalesce((select jsonb_agg(jsonb_build_object('key', 'pipeline:0:fixed_value:' || c.jobname, 'layer', 0, 'toolset', 'pipeline', 'kind', 'fixed_value', 'severity', 'warning',
      'title', format('Job "%s" has a number written into it', c.jobname),
      'detail', 'Its size or limit should come from Pipeline settings, so it can be changed on screen.',
      'hint', 'Move the value to the settings register (Pipeline settings).', 'count', 1, 'first_at', now(), 'last_at', now()))
    from security.controls_check_v1() c), '[]'::jsonb);

  -- CF-247 15 Oct 2026 (waste rules): jobs paused for producing nothing, and values frozen after automatic writers disagreed
  v := v || coalesce((select jsonb_agg(jsonb_build_object('key', 'pipeline:0:waste_paused:' || w.jobname, 'layer', 0, 'toolset', 'pipeline', 'kind', 'waste_paused', 'severity', 'warning',
      'title', format('Job "%s" paused: it produced nothing', w.jobname),
      'detail', format('Paused %s: no output and nothing waiting for it. It resumes by itself when work arrives.', to_char(w.paused_at at time zone 'Australia/Melbourne', 'DD Mon HH24:MI')),
      'hint', 'Nothing to do. The time is on Pipeline settings › Waste rules.', 'count', 1, 'first_at', w.paused_at, 'last_at', w.paused_at))
    from pipeline.job_idle_watch w where w.paused_at is not null), '[]'::jsonb);
  v := v || coalesce((select jsonb_agg(jsonb_build_object('key', 'pipeline:0:waste_frozen', 'layer', 0, 'toolset', 'pipeline', 'kind', 'waste_frozen', 'severity', 'warning',
      'title', format('%s course values frozen: automatic writers kept changing them', z.n),
      'detail', 'Each changed more often than Pipeline settings › Waste rules allows; it is kept as it is and left out of automatic updates.',
      'hint', 'Check them and set the right value by hand.', 'count', z.n, 'first_at', z.f, 'last_at', z.l))
    from (select count(*) n, min(f.flagged_at) f, max(f.flagged_at) l from pipeline.enrichment_flags f where f.reason_code = 'flip_flop' and f.cleared_at is null) z where z.n > 0), '[]'::jsonb);

  -- CF-247 15 Oct 2026 (Decision 260): the latest weekly hygiene check, when it found something
  v := v || coalesce((select jsonb_agg(jsonb_build_object('key', 'pipeline:0:hygiene', 'layer', 0, 'toolset', 'pipeline', 'kind', 'hygiene', 'severity', 'warning',
      'title', format('Housekeeping: %s unused, %s security items, %s ready to drop', z.unused, z.security, z.drop),
      'detail', format('Weekly hygiene check of %s (component register, Decision 260).', to_char(z.at at time zone 'Australia/Melbourne', 'DD Mon HH24:MI')),
      'hint', 'Retire what is unused, fix the security items, and run the drop paste file for what is ready.', 'count', z.unused + z.security + z.drop, 'first_at', z.at, 'last_at', z.at))
    from (select h.at, coalesce((h.summary->>'unused_tables')::int, 0) + coalesce((h.summary->>'unused_indexes')::int, 0) + coalesce((h.summary->>'edge_functions_not_called')::int, 0) unused,
                 coalesce((h.summary->>'tables_without_rls')::int, 0) + coalesce((h.summary->>'definer_functions_without_search_path')::int, 0) + coalesce((h.summary->>'public_functions_open_to_anon')::int, 0) security,
                 coalesce((h.summary->>'ready_to_drop')::int, 0) drop
            from pipeline.hygiene_reports h order by h.at desc limit 1) z where z.unused + z.security + z.drop > 0), '[]'::jsonb);

  -- CF-247 worker v1.0.0: AI models in cooldown for a service (job ai-model-health)
  v := v || coalesce((select jsonb_agg(jsonb_build_object('key', 'openrouter:2:model_degraded:' || h.service_code || ':' || h.model, 'layer', 2, 'toolset', 'openrouter',
      'kind', 'model_degraded', 'severity', 'warning',
      'title', format('AI model failing for %s: %s', h.service_code, h.model),
      'detail', format('%s of %s attempts failed in the last %s minutes (%s empty, %s timed out); in cooldown until %s.', h.failed, h.attempts, h.window_minutes,
                       h.empty, h.timeouts, to_char(h.cooling_until at time zone 'Australia/Melbourne', 'DD Mon HH24:MI')),
      'hint', case when security.pipeline_num_v1('health.ai_reorder_on', 0) = 1 then 'Nothing to do: the model is asked after the healthy ones of the cascade until its cooldown ends.'
                   else 'Reported only (health.ai_reorder_on is 0). Check the service''s cascade on Models & services › AI.' end,
      'count', h.failed, 'first_at', h.cooling_since, 'last_at', h.checked_at))
    from pipeline.ai_model_health h where h.state = 'cooling' and h.cooling_until > now()), '[]'::jsonb);
  -- CF-247 worker v1.0.0: Layer 4 items the self-healing job could not move (dead letters)
  v := v || coalesce((select jsonb_agg(jsonb_build_object('key', 'pipeline:4:layer4_dead_letter', 'layer', 4, 'toolset', 'pipeline', 'kind', 'layer4_dead_letter', 'severity', 'warning',
      'title', format('%s Layer 4 %s', z.n, case when z.n = 1 then 'item is a dead letter' else 'items are dead letters' end),
      'detail', 'Their course page was read again as many times as layer4.drain_max_attempts allows and they still wait.',
      'hint', 'Decide them by hand in Layer 4, or fix the course page binding.', 'count', z.n, 'first_at', z.f, 'last_at', z.l))
    from (select count(*) n, min(s.dead_letter_at) f, max(s.dead_letter_at) l from pipeline.layer4_drain_state s
            join pipeline.layer4_review_items i on i.id = s.item_id and i.status = 'pending' where s.dead_letter_at is not null) z where z.n > 0), '[]'::jsonb);

  return v;
end $_$;


ALTER FUNCTION "security"."platform_notices_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_resource_observe_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'cron', 'net'
    AS $$
declare h timestamptz := date_trunc('hour', now()); h0 timestamptz := date_trunc('hour', now()) - interval '1 hour';  -- fixed: one reading per hour (the reading's own period)
  m timestamptz := date_trunc('month', now()); cp pipeline.platform_compute_profile%rowtype; r pipeline.platform_resource_observations%rowtype;
begin
  select * into cp from pipeline.platform_compute_profile where id=1;
  r.observed_at := h; r.memory_bytes := cp.memory_bytes; r.compute_size := cp.compute_size;
  r.db_bytes := pg_database_size(current_database());
  select round(100.0*sum(blks_hit)/nullif(sum(blks_hit)+sum(blks_read),0),2) into r.cache_hit_pct from pg_stat_database where datname=current_database();
  select count(*), count(*) filter (where state='active') into r.connections, r.active_connections from pg_stat_activity where backend_type='client backend';
  select count(*), count(*) filter (where status not in ('succeeded','running')), round(max(extract(epoch from coalesce(end_time, case when status in ('running','starting','sending','connecting') then now() end)-start_time))::numeric,1)
    into r.cron_runs, r.cron_failures, r.cron_max_seconds from cron.job_run_details where start_time >= h0 and start_time < h;
  select coalesce(max(c) filter (where t >= h0 and t < h and d = 1),0) into r.cron_max_concurrent from (
    select e.t, e.d, sum(e.d) over (order by e.t, e.d desc) c from (
      select b.start_time t, 1 d from cron.job_run_details b where b.start_time >= h0 - interval '1 hour' and b.start_time < h  -- fixed: runs overlapping the hour read
      union all
      select coalesce(b.end_time, case when b.status in ('running','starting','sending','connecting') then now() else b.start_time end), -1
        from cron.job_run_details b where b.start_time >= h0 - interval '1 hour' and b.start_time < h) e) z;  -- fixed: runs overlapping the hour read
  select count(*) into r.http_requests from net._http_response where created >= h0 and created < h;
  select coalesce(jsonb_agg(jsonb_build_object('provider',coalesce(ap.provider_key,'unknown'),'units',u,'cost_usd',cst)),'[]'::jsonb) into r.acquisition
    from (select ri.selected_provider_id, sum(coalesce(ri.vendor_units,0)) u, sum(coalesce(ri.vendor_cost_usd,0)) cst
          from pipeline.layer2_run_items ri where ri.completed_at >= h0 and ri.completed_at < h group by 1) x
    left join pipeline.layer2_acquisition_providers ap on ap.id=x.selected_provider_id;
  select sum(coalesce(vendor_units,0)), sum(coalesce(vendor_cost_usd,0)) into r.acquisition_units_mtd, r.acquisition_cost_mtd_usd
    from pipeline.layer2_run_items where completed_at >= m;
  -- CF-247 15 Oct 2026 (usage audit D7): Layer 3 calls from their hourly totals (same sums; layer3_interpretations is purged)
  select coalesce(sum(n),0), sum(tok), sum(cst) into r.ai_calls, r.ai_tokens, r.ai_cost_usd
    from (select k.calls n, k.tokens tok, k.cost_usd cst from pipeline.layer3_call_costs_hourly k where k.hour >= h0 and k.hour < h) z;
  select coalesce(sum(estimated_cost_usd),0) into r.ai_cost_mtd_usd
    from (select k.cost_usd estimated_cost_usd from pipeline.layer3_call_costs_hourly k where k.hour >= m) z;
  select coalesce(jsonb_agg(jsonb_build_object('table',t,'bytes',b) order by b desc),'[]'::jsonb) into r.largest_tables
    from (select n.nspname||'.'||c.relname t, pg_total_relation_size(c.oid) b from pg_class c join pg_namespace n on n.oid=c.relnamespace
          where c.relkind='r' and n.nspname not in ('pg_catalog','information_schema') order by 2 desc limit 5) z;
  insert into pipeline.platform_resource_observations select r.* on conflict (observed_at) do update set
    db_bytes=excluded.db_bytes, cache_hit_pct=excluded.cache_hit_pct, connections=excluded.connections, active_connections=excluded.active_connections,
    cron_runs=excluded.cron_runs, cron_failures=excluded.cron_failures, cron_max_seconds=excluded.cron_max_seconds, cron_max_concurrent=excluded.cron_max_concurrent,
    http_requests=excluded.http_requests, acquisition=excluded.acquisition, acquisition_units_mtd=excluded.acquisition_units_mtd, acquisition_cost_mtd_usd=excluded.acquisition_cost_mtd_usd,
    ai_calls=excluded.ai_calls, ai_tokens=excluded.ai_tokens, ai_cost_usd=excluded.ai_cost_usd, ai_cost_mtd_usd=excluded.ai_cost_mtd_usd, largest_tables=excluded.largest_tables;
  delete from pipeline.platform_resource_observations where observed_at < now() - make_interval(days => security.pipeline_num_v1('retention.resource_observations_days', 180)::int);
  return to_jsonb(r);
end $$;


ALTER FUNCTION "security"."platform_resource_observe_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."platform_watchdog_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_stale int := security.pipeline_num_v1('alerts.watchdog_stale_minutes', 30)::int;
        v_scan int := security.pipeline_num_v1('alerts.watchdog_scan_runs', 20000)::int;
        v_collect int := security.pipeline_num_v1('alerts.collect_within_minutes', 120)::int;
        v_delivery boolean := coalesce((security.toolset_setting('pipeline', 'alerts.delivery_enabled') #>> '{}')::boolean, false);
        v_problems text[] := '{}'; v_jobs jsonb := '{}'::jsonb; j record; r record; v_waiting int; v_since timestamptz;
begin
  for j in select n.name, c.jobid, c.active from unnest(array['platform-health', 'platform-alerts']) n(name) left join cron.job c on c.jobname = n.name loop
    r := null;
    select d.status, d.start_time into r
      from (select x.runid, x.jobid, x.status, x.start_time from cron.job_run_details x order by x.runid desc limit v_scan) d
     where d.jobid = j.jobid order by d.runid desc limit 1;
    v_jobs := v_jobs || jsonb_build_object(j.name, jsonb_build_object('active', j.active, 'last_start', r.start_time, 'last_status', r.status));
    if j.jobid is null then v_problems := v_problems || format('%s: the job is not scheduled', j.name);
    elsif not j.active then v_problems := v_problems || format('%s: the job is switched off', j.name);
    elsif r.start_time is null or r.start_time < now() - make_interval(mins => v_stale) then
      v_problems := v_problems || format('%s: no run started in the last %s minutes (last: %s)', j.name, v_stale,
                                         coalesce(to_char(r.start_time at time zone 'Australia/Melbourne', 'DD Mon HH24:MI'), 'none found'));
    elsif r.status not in ('succeeded', 'running', 'starting') then
      v_problems := v_problems || format('%s: the last run %s', j.name, r.status);
    end if;
  end loop;
  -- the alert-collecting step: an alert left waiting longer than alerts.collect_within_minutes means nothing is taking them
  select count(*), min(a.created_at) into v_waiting, v_since from pipeline.platform_alerts a
   where a.status = 'pending' and a.created_at < now() - make_interval(mins => v_collect);
  if v_delivery and v_waiting > 0 then
    v_problems := v_problems || format('alerts are not being collected: %s waiting since %s (longer than %s minutes)', v_waiting,
                                       to_char(v_since at time zone 'Australia/Melbourne', 'DD Mon HH24:MI'), v_collect);
  end if;
  return jsonb_build_object('ok', cardinality(v_problems) = 0, 'problems', to_jsonb(v_problems), 'checked_at', now(), 'jobs', v_jobs,
                            'alerts_waiting_too_long', v_waiting, 'delivery_enabled', v_delivery, 'stale_minutes', v_stale, 'collect_within_minutes', v_collect);
end $$;


ALTER FUNCTION "security"."platform_watchdog_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."platform_watchdog_v1"() IS 'Decision 5 E-9 W1 (2 Nov 2026): read-only health of the alert path (platform-health and platform-alerts runs, alerts waiting); read hourly by .github/workflows/platform-watchdog.yml';



CREATE OR REPLACE FUNCTION "security"."policy_auto_approve_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_sum jsonb; v_ag int; v_df int; v_ok int := 0; v_refused int := 0;
        v_max numeric := security.pipeline_num_v1('central.max_disagree_pct', 50);
        v_min int := security.pipeline_num_v1('central.min_compare', 10)::int;
        v_note text := 'Automatic: AI reading of the central page, every value quoted on the page (Platform Admin 15 Oct 2026: "Central pages, per course group", "Auto-approve checked AI proposals")';
begin
  -- CF-247 F-INT.01/SRC-01 (9 Nov 2026): official main teaching calendars are qualified by rule when central.calendar_qualify_main_teaching = 1 (default 0: returns at once);
  -- a failure is recorded in pipeline.calendar_qualify_runs inside the function and never stops the approvals below
  perform security.calendar_qualify_v1();
  if not coalesce((select (s.value #>> '{}')::boolean from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'central.auto_approve'), false) then
    return jsonb_build_object('off', true);
  end if;
  for r in select x.* from pipeline.provider_policy_proposals x
             left join pipeline.enrich_focus_providers f on f.provider_id = x.provider_id
            where x.status = 'proposed' and x.kind in ('english_policy', 'intake_calendar')
              -- CF-247 6 Nov 2026 (English requirements, decision D2): a faculty or course-group reading is never approved automatically; a person approves it and binds its groups
              and (x.kind <> 'english_policy' or jsonb_array_length(case when jsonb_typeof(x.proposal->'groups') = 'array' then x.proposal->'groups' else '[]'::jsonb end) = 0)
              and (x.parser like 'ai:%'
                   -- CF-247 decision 5 Nov 2026 §2: a deterministic dated calendar reading, only when the Platform Admin switches it on
                   or (x.kind = 'intake_calendar' and x.parser = 'provider-policy-calendar-dates-v2' and security.pipeline_num_v1('central.auto_approve_calendar_dates', 0) = 1
                       and security.calendar_scope_v1(x.proposal, x.url, x.parser) = 'main_teaching'))
              -- 23 Oct 2026 (Platform Admin 12:40): English rules for every university, not only the focus list
              and (coalesce(f.in_focus, false)
                   or (x.kind = 'english_policy' and coalesce((select (s.value #>> '{}')::boolean from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'central.auto_approve_english_all'), false)))
            order by f.rank nulls last, x.created_at loop
    if r.kind = 'english_policy' then
      v_sum := security.provider_policy_refresh_one_v1(r.id);
      v_ag := coalesce((v_sum->>'agrees')::int, 0); v_df := coalesce((v_sum->>'differs')::int, 0);
      if v_ag + v_df >= v_min and 100.0 * v_df / (v_ag + v_df) > v_max then
        insert into pipeline.enrichment_flags(entity, entity_key, provider_id, field, reason_code, reason, source)
        values ('policy', r.id::text, r.provider_id, 'english', 'policy_disagrees',
                format('Not approved automatically: %s course pages agree and %s disagree with this default; a person decides (%s)', v_ag, v_df, r.url), 'policy-auto-approve')
        on conflict (entity, entity_key, field, reason_code) do update set reason = excluded.reason, flagged_at = now(), cleared_at = null;
        v_refused := v_refused + 1;
        continue;
      end if;
    end if;
    update pipeline.provider_policy_proposals set status = 'approved', decided_by = null, decided_at = now(), decision_note = v_note, updated_at = now() where id = r.id;
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('policies', 'approve', r.kind || ': ' || r.url, jsonb_build_object('decision', 'Platform Admin 15 Oct 2026: automatic approval of checked AI readings', 'proposal_id', r.id, 'provider_id', r.provider_id), null);
    update pipeline.provider_policy_proposals
       set status = 'superseded', decided_at = now(), updated_at = now(), decision_note = 'Closed: another document for this university was approved (' || r.url || ')'
     where provider_id = r.provider_id and kind = r.kind and status = 'proposed' and id <> r.id
       and (r.kind <> 'intake_calendar' or fact_source_id is not distinct from r.fact_source_id)
       and jsonb_array_length(case when jsonb_typeof(proposal->'groups') = 'array' then proposal->'groups' else '[]'::jsonb end) = 0;  -- CF-247 6 Nov 2026: an automatic approval never closes a course-group reading a person has yet to decide (5 Nov 2026: one calendar document never closes another's)
    v_ok := v_ok + 1;
  end loop;
  return jsonb_build_object('approved', v_ok, 'refused', v_refused);
end $$;


ALTER FUNCTION "security"."policy_auto_approve_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."policy_columns_v1"() RETURNS TABLE("tbl" "text", "key_col" "text", "col" "text", "label" "text", "unit" "text")
