CREATE OR REPLACE FUNCTION "security"."pre_ai_admission_report_v1"("p_hours" integer DEFAULT 168) RETURNS TABLE("lane" "text", "reason" "text", "judged" bigint, "would_reject" bigint, "would_reject_share" numeric, "tokens_saved_estimate" bigint, "would_reject_but_admitted" bigint, "would_reject_but_spent_usd" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 pre-AI admission gate, read-only: per lane and reason over the last p_hours, how many reads the reason would have stopped, the tokens
  -- that would have saved, and the false-negative measure: would_reject_but_admitted counts reads the reason would have stopped whose answer was
  -- admitted anyway (scholarship verdict 'scholarship'; an enrichment item filled or sent to review). It must be 0 before admission.enforce.<reason>
  -- is proposed. would_reject_but_spent_usd is what those reads actually cost.
  with d as (select * from pipeline.pre_ai_admission_decisions a where a.decided_at > now() - make_interval(hours => greatest(1, p_hours))),
  r as (select d.*, unnest(case when cardinality(d.reason_codes) = 0 then array['(none)'] else d.reason_codes end) code from d),
  o as (
    select r.*,
           case when r.lane_item = 'scholarship_ai_queue' then (select x.verdict = 'scholarship' from pipeline.scholarship_ai_queue q
                     join pipeline.scholarship_ai_extractions x on x.id = q.extraction_id where q.id::text = r.item_id)
                when r.lane_item = 'field_enrich_items' then (select e.state in ('filled', 'review') from pipeline.field_enrich_items e where e.id::text = r.item_id)
           end admitted,
           case when r.lane_item = 'scholarship_ai_queue' then (select x.cost_usd from pipeline.scholarship_ai_queue q
                     join pipeline.scholarship_ai_extractions x on x.id = q.extraction_id where q.id::text = r.item_id)
                when r.lane_item = 'field_enrich_items' then (select e.cost_usd from pipeline.field_enrich_items e where e.id::text = r.item_id)
           end spent
      from r)
  select o.lane, o.code, count(*), count(*) filter (where o.would <> 'admit'), round(avg((o.would <> 'admit')::int)::numeric, 3),
         sum(o.tokens_saved_estimate)::bigint, count(*) filter (where o.would <> 'admit' and o.admitted is true),
         round(sum(o.spent) filter (where o.would <> 'admit'), 4)
    from o group by o.lane, o.code order by count(*) desc
$$;


ALTER FUNCTION "security"."pre_ai_admission_report_v1"("p_hours" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."priority_pin_label"("p_kind" "text", "p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'ref'
    AS $$
  select case p_kind
    when 'provider' then (select jsonb_build_object('label',coalesce(pr.display_name,pr.canonical_name),'detail',concat_ws(' · ',s.name,k.name),'courses',(select count(*) from catalogue.courses c where c.provider_id=pr.id and c.lifecycle_status='active'))
                            from catalogue.providers pr left join ref.subdivisions s on s.id=pr.subdivision_id left join ref.countries k on k.id=pr.country_id where pr.id=p_id)
    when 'state' then (select jsonb_build_object('label',s.name,'detail',k.name,'courses',(select count(*) from catalogue.courses c join catalogue.providers pr on pr.id=c.provider_id where pr.subdivision_id=s.id and c.lifecycle_status='active'))
                         from ref.subdivisions s left join ref.countries k on k.id=s.country_id where s.id=p_id)
    when 'country' then (select jsonb_build_object('label',k.name,'detail','Whole country','courses',(select count(*) from catalogue.courses c join catalogue.providers pr on pr.id=c.provider_id where pr.country_id=k.id and c.lifecycle_status='active'))
                           from ref.countries k where k.id=p_id)
    else (select jsonb_build_object('label',coalesce(c.display_title,c.canonical_title),'detail',concat_ws(' · ',c.course_code,coalesce(pr.display_name,pr.canonical_name)),'courses',1)
            from catalogue.courses c left join catalogue.providers pr on pr.id=c.provider_id where c.id=p_id) end
$$;


ALTER FUNCTION "security"."priority_pin_label"("p_kind" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."process_results_intake_dates_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_unis jsonb := security.intake_ui_scopes_v1(); v_today date := (now() at time zone 'Australia/Melbourne')::date;  -- fixed: the calendar day in Australia
        v_per jsonb; v_job jsonb;
begin
  with u as (select (e->>'id')::uuid id, e->>'name' name, (e->>'active_courses')::int active from jsonb_array_elements(v_unis) e),
  i as (select c.provider_id, i.* from catalogue.course_intakes i join catalogue.courses c on c.id = i.course_id
         where c.lifecycle_status = 'active' and i.status = 'active' and c.provider_id in (select id from u)),
  d as (select d.* from pipeline.course_intake_dates d join i on i.id = d.intake_id),
  cal as (select u.id provider_id, s.* from u, lateral security.calendar_sources_v1(u.id) s),
  per as (select u.id provider_id, p.* from u, lateral security.calendar_dated_periods_v2(u.id) p)
  select jsonb_agg(jsonb_build_object(
    'provider_id', u.id, 'university', u.name, 'active_courses', u.active,
    'courses_with_intakes', (select count(distinct course_id) from i where i.provider_id = u.id),
    'intake_rows', (select count(*) from i where i.provider_id = u.id),
    'course_pages_stored', (select count(distinct p.course_id) from pipeline.coverage_course_pages p where p.provider_id = u.id and p.read_status = 'read' and p.status = 'bound'),
    'calendars_approved', (select count(*) from cal where cal.provider_id = u.id),
    'calendars_valid', (select count(*) from cal where cal.provider_id = u.id and cal.used),
    'calendars_set_aside', (select coalesce(jsonb_agg(jsonb_build_object('url', cal.url, 'scope', cal.scope, 'reason', cal.set_aside_reason)), '[]'::jsonb) from cal where cal.provider_id = u.id and not cal.used),
    'calendar_latest_year', (select max(per.year) from per where per.provider_id = u.id and per.kind = 'start'),
    'calendar_freshest', (select max(cal.decided_at) from cal where cal.provider_id = u.id and cal.used),
    'future_periods', (select count(*) from per where per.provider_id = u.id and per.kind = 'start' and per.year is not null
                        and (per.on_date >= v_today or (per.on_date is null and make_date(per.year, per.month, 1) >= date_trunc('month', v_today)::date))),
    'future_dated_starts', (select count(*) from per where per.provider_id = u.id and per.kind = 'start' and per.on_date >= v_today),
    'future_deadlines', (select count(*) from per where per.provider_id = u.id and per.kind = 'deadline' and per.on_date >= v_today),
    'held', jsonb_build_object('month', (select count(*) from i where i.provider_id = u.id),
                               'year', (select count(*) from i where i.provider_id = u.id and i.intake_year is not null),
                               'start_date', (select count(*) from i where i.provider_id = u.id and i.start_date is not null),
                               'application_deadline', (select count(*) from i where i.provider_id = u.id and i.application_deadline is not null)),
    'in_website_source', jsonb_build_object(
        'year', (select count(*) from search.course_documents sd, jsonb_array_elements(case when jsonb_typeof(sd.intake_options) = 'array' then sd.intake_options else '[]'::jsonb end) o where sd.provider_id = u.id and o->>'year' is not null),
        'start_date', (select count(*) from search.course_documents sd, jsonb_array_elements(case when jsonb_typeof(sd.intake_options) = 'array' then sd.intake_options else '[]'::jsonb end) o where sd.provider_id = u.id and o->>'start_date' is not null),
        'application_deadline', (select count(*) from search.course_documents sd, jsonb_array_elements(case when jsonb_typeof(sd.intake_options) = 'array' then sd.intake_options else '[]'::jsonb end) o where sd.provider_id = u.id and o->>'application_deadline' is not null)),
    'outcomes', (select coalesce(jsonb_object_agg(k, n), '{}'::jsonb) from (select coalesce(d.next_action, 'not classified (decided before ' || 'calendar-v3)') k, count(*) n from d where d.provider_id = u.id group by 1) x),
    'reasons', (select coalesce(jsonb_agg(jsonb_build_object('next_action', next_action, 'reason', reason, 'rows', n) order by n desc), '[]'::jsonb)
                  from (select d.next_action, coalesce(d.reason, d.outcome) reason, count(*) n from d where d.provider_id = u.id and d.outcome <> 'filled' group by 1, 2) x),
    'never_examined', (select count(*) from i where i.provider_id = u.id and (i.intake_year is null or i.start_date is null or i.application_deadline is null)
                         and not exists (select 1 from pipeline.course_intake_dates d2 where d2.intake_id = i.id)),
    'last_attempt', (select max(d.applied_at) from d where d.provider_id = u.id),
    'next_revisit', (select min(d.next_revisit_at) from d where d.provider_id = u.id and d.next_revisit_at is not null),
    'waiting_for_change_only', (select count(*) from d where d.provider_id = u.id and d.next_revisit_at is null and coalesce(d.next_action, '') not in ('complete')),
    'admitted_7_days', (select jsonb_build_object('year', count(*) filter (where e.before_value->>'year' is null and e.after_value->>'year' is not null),
                                                  'start_date', count(*) filter (where e.before_value->>'start_date' is null and e.after_value->>'start_date' is not null),
                                                  'application_deadline', count(*) filter (where e.before_value->>'application_deadline' is null and e.after_value->>'application_deadline' is not null))
                          from pipeline.course_intake_date_events e where e.provider_id = u.id and e.outcome = 'filled'
                           and e.run_at > now() - make_interval(days => security.pipeline_num_v1('process_results.window_days', 7)::int)),
    'calendar_reread', (select coalesce(jsonb_object_agg(s.state, s.n), '{}'::jsonb) from (select s.state, count(*) n from pipeline.calendar_reread_state s where s.provider_id = u.id group by 1) s),
    'reader_findings_open', (select count(*) from pipeline.calendar_reader_findings f where f.provider_id = u.id and f.resolved_at is null),
    'ai_cost_usd_7_days', (select coalesce(sum(q.cost_usd), 0) from pipeline.central_ai_queue q where q.provider_id = u.id and q.kind = 'intake_calendar'
                             and q.created_at > now() - make_interval(days => security.pipeline_num_v1('process_results.window_days', 7)::int)),
    'firecrawl_credits', 0
  ) order by u.active desc) into v_per from u;
  v_job := jsonb_build_object(
    'intake_dates_apply', (select jsonb_build_object('schedule', j.schedule, 'active', j.active,
        'last_run', (select jsonb_build_object('at', r.start_time, 'status', r.status, 'message', left(r.return_message, 300)) from cron.job_run_details r where r.jobid = j.jobid order by r.start_time desc limit 1),
        'last_success', (select max(r.start_time) from cron.job_run_details r where r.jobid = j.jobid and r.status = 'succeeded'))
      from cron.job j where j.jobname = 'intake-dates-apply'),
    'calendar_reread', (select jsonb_build_object('schedule', j.schedule, 'active', j.active,
        'last_run', (select jsonb_build_object('at', r.start_time, 'status', r.status) from cron.job_run_details r where r.jobid = j.jobid order by r.start_time desc limit 1))
      from cron.job j where j.jobname = 'calendar-reread'),
    'enabled', coalesce((security.toolset_setting('pipeline', 'intake_dates.apply_enabled') #>> '{}')::boolean, false),
    'batch', security.pipeline_num_v1('batch.intake_dates_apply', 200),
    'month_unique_match', security.pipeline_num_v1('intake_dates.month_unique_match', 0),
    'revisit_days', security.pipeline_num_v1('intake_dates.revisit_days', 14));
  return jsonb_build_object('process', 'intake-dates', 'scope', 'top-au', 'measured_at', now(), 'universities', coalesce(v_per, '[]'::jsonb), 'jobs', v_job,
    'totals', jsonb_build_object(
      'active_courses', (select sum((x->>'active_courses')::int) from jsonb_array_elements(v_per) x),
      'courses_with_intakes', (select sum((x->>'courses_with_intakes')::int) from jsonb_array_elements(v_per) x),
      'course_pages_stored', (select sum((x->>'course_pages_stored')::int) from jsonb_array_elements(v_per) x),
      'calendars_valid', (select sum((x->>'calendars_valid')::int) from jsonb_array_elements(v_per) x),
      'future_periods', (select sum((x->>'future_periods')::int) from jsonb_array_elements(v_per) x),
      'intake_rows', (select sum((x->>'intake_rows')::int) from jsonb_array_elements(v_per) x),
      'held_year', (select sum((x->'held'->>'year')::int) from jsonb_array_elements(v_per) x),
      'held_start_date', (select sum((x->'held'->>'start_date')::int) from jsonb_array_elements(v_per) x),
      'held_application_deadline', (select sum((x->'held'->>'application_deadline')::int) from jsonb_array_elements(v_per) x),
      'website_start_date', (select sum((x->'in_website_source'->>'start_date')::int) from jsonb_array_elements(v_per) x),
      'never_examined', (select sum((x->>'never_examined')::int) from jsonb_array_elements(v_per) x)));
end $$;


ALTER FUNCTION "security"."process_results_intake_dates_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."process_results_intake_dates_v1"() IS 'CF-247 process accountability (decision 5 Nov 2026 §6, §10): the intake dates process for the top Australian universities, measured from saved results: eligible courses, stored pages, valid and set-aside calendars, calendar year and freshness, future periods and deadlines, held values, values in the Website API source, outcomes by next action and reason, never examined, last attempt, next revisit, admitted in the window, calendar re-read state, reader findings, AI cost; and the jobs. Read only.';



CREATE OR REPLACE FUNCTION "security"."process_results_markdown_v1"("p_summary" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select '# Process record: intake dates (generated)' || E'\n\n' ||
    '**Measured:** ' || to_char((p_summary->>'measured_at')::timestamptz at time zone 'Australia/Melbourne', 'DD Mon YYYY HH24:MI') || ' AEDT. Scope: top Australian universities by active courses. Generated by security.process_results_markdown_v1 from pipeline.process_results; the hand-written design and history are in the process record.' || E'\n\n' ||
    '| University | Active courses | Course pages stored | Valid calendars (set aside) | Future periods | Intake rows | With year | With start date | With deadline | Start dates in Website source | Never examined | Next revisit |' || E'\n' ||
    '|---|---:|---:|---|---:|---:|---:|---:|---:|---:|---:|---|' || E'\n' ||
    coalesce((select string_agg('| ' || (x->>'university') || ' | ' || (x->>'active_courses') || ' | ' || (x->>'course_pages_stored') || ' | ' || (x->>'calendars_valid') || ' (' || jsonb_array_length(x->'calendars_set_aside') || ') | ' ||
                                (x->>'future_periods') || ' | ' || (x->>'intake_rows') || ' | ' || (x->'held'->>'year') || ' | ' || (x->'held'->>'start_date') || ' | ' || (x->'held'->>'application_deadline') || ' | ' ||
                                (x->'in_website_source'->>'start_date') || ' | ' || (x->>'never_examined') || ' | ' ||
                                coalesce(to_char((x->>'next_revisit')::timestamptz at time zone 'Australia/Melbourne', 'DD Mon HH24:MI'), 'on change') || ' |', E'\n')
              from jsonb_array_elements(p_summary->'universities') x), '') || E'\n\n## What was missed, and why\n\n' ||
    coalesce((select string_agg('### ' || (x->>'university') || E'\n\n' ||
               coalesce((select string_agg('- ' || coalesce(y->>'next_action', 'not classified') || ': ' || (y->>'reason') || ' (' || (y->>'rows') || ')', E'\n')
                          from (select y from jsonb_array_elements(x->'reasons') y limit 8) z), '- nothing held') ||
               coalesce(E'\n- calendars set aside: ' || nullif((select string_agg((c->>'url') || ' (' || (c->>'scope') || ')', '; ') from jsonb_array_elements(x->'calendars_set_aside') c), ''), ''), E'\n\n')
              from jsonb_array_elements(p_summary->'universities') x), '') || E'\n'
$$;


ALTER FUNCTION "security"."process_results_markdown_v1"("p_summary" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."process_results_markdown_v1"("p_summary" "jsonb") IS 'CF-247 (decision 5 Nov 2026 §5): the intake dates process measurement as markdown for the repository (process-results workflow).';



CREATE OR REPLACE FUNCTION "security"."process_results_record_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb := security.process_results_intake_dates_v1(); v_id bigint; v_flags int := 0; x jsonb;
begin
  insert into pipeline.process_results(process_key, scope_key, measured_at, summary, markdown, measured_by)
  values ('intake-dates', 'top-au', now(), v, security.process_results_markdown_v1(v), coalesce(auth.uid()::text, 'job process-results'))
  returning id into v_id;
  -- decision §11: the observer routes a university whose calendars are set aside or give no future start to a person (existing flags)
  for x in select * from jsonb_array_elements(v->'universities') loop
    if (x->>'calendars_valid')::int = 0 or (x->>'future_periods')::int = 0 then
      insert into pipeline.enrichment_flags(entity, entity_key, provider_id, field, reason_code, reason, source, evidence)
      values ('provider', x->>'provider_id', (x->>'provider_id')::uuid, 'intake_calendar', 'calendar_needs_correction',
              format('%s: intake dates need a current main teaching calendar: %s valid, %s set aside, %s future study periods. Next action: approve the correct official calendar (Adapter builder, central pages) or check the calendar reader findings.',
                     x->>'university', x->>'calendars_valid', jsonb_array_length(x->'calendars_set_aside'), x->>'future_periods'),
              'process-results', jsonb_build_object('set_aside', x->'calendars_set_aside', 'reread', x->'calendar_reread', 'process_result_id', v_id))
      on conflict (entity, entity_key, field, reason_code) do update set reason = excluded.reason, evidence = excluded.evidence, flagged_at = now(), cleared_at = null;
      v_flags := v_flags + 1;
    else
      update pipeline.enrichment_flags set cleared_at = now() where entity = 'provider' and entity_key = x->>'provider_id' and field = 'intake_calendar'
         and reason_code = 'calendar_needs_correction' and cleared_at is null;
    end if;
  end loop;
  return jsonb_build_object('id', v_id, 'flags', v_flags, 'totals', v->'totals');
end $$;


ALTER FUNCTION "security"."process_results_record_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."process_results_record_v1"() IS 'CF-247 (decision 5 Nov 2026 §5, §11): records a dated measurement of the intake dates process (job process-results) and routes universities without a usable calendar to a person through the existing flags; nothing earlier is overwritten.';



CREATE OR REPLACE FUNCTION "security"."process_results_recovery_record_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb := security.process_results_recovery_v1(); v_id bigint;
begin
  insert into pipeline.process_results(process_key, scope_key, measured_at, summary, markdown, measured_by)
  values ('intake-recovery', 'top-au', now(), v,
          '# Process record: intake recovery (generated)' || chr(10) || chr(10) || 'Measured ' || to_char(now() at time zone 'Australia/Sydney', 'YYYY-MM-DD HH24:MI') || ' Sydney.' || chr(10) || chr(10)
          || '```json' || chr(10) || jsonb_pretty(v) || chr(10) || '```' || chr(10),
          coalesce(auth.uid()::text, 'job process-results'))
  returning id into v_id;
  return jsonb_build_object('id', v_id);
end $$;


ALTER FUNCTION "security"."process_results_recovery_record_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."process_results_recovery_record_v1"() IS 'CF-247 (mandate 5 Nov 2026 §10): records a dated intake recovery measurement (process intake-recovery); nothing earlier is overwritten.';



CREATE OR REPLACE FUNCTION "security"."process_results_recovery_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with u as (select (e->>'id')::uuid id, e->>'name' name from jsonb_array_elements(security.intake_ui_scopes_v1()) e),
  w as (select now() - make_interval(days => security.pipeline_num_v1('process_results.window_days', 7)::int) since),
  ev as (select e.* from pipeline.course_intake_date_events e, w where e.run_at >= w.since and e.provider_id in (select id from u)),
  d as (select d.* from pipeline.course_intake_dates d where d.provider_id in (select id from u)),
  -- the last run and its status of the five jobs, read from the scheduler history in one pass (it was two scans of it for each job)
  jr as (select r.jobid, max(r.start_time) last_run, (array_agg(r.status order by r.start_time desc))[1] last_status from cron.job_run_details r
          where r.jobid in (select x.jobid from cron.job x where x.jobname in ('calendar-reread', 'central-ai', 'provider-facts', 'intake-dates-apply', 'process-results')) group by r.jobid)
  select jsonb_build_object(
    'measured_at', now(), 'window_since', (select since from w),
    'admitted', (select coalesce(jsonb_agg(x order by x->>'university', x->>'year'), '[]'::jsonb) from (
       select jsonb_build_object('university', u.name, 'source_type', 'approved calendar', 'rule', ev.rule, 'year', coalesce((ev.after_value->>'year')::int, (ev.before_value->>'year')::int),
                'precision', ev.start_precision, 'admitted', count(*), 'with_start_date', count(*) filter (where ev.after_value->>'start_date' is not null),
                'with_deadline', count(*) filter (where ev.after_value->>'application_deadline' is not null),
                'published', count(*) filter (where ev.publication_state = 'published'), 'publication_failed', count(*) filter (where ev.publication_state = 'consumer_publication_failed'),
                'provider_not_published', count(*) filter (where ev.publication_state in ('provider_not_published', 'course_not_in_consumer_source')), 'not_checked', count(*) filter (where ev.publication_state is null)) x
         from ev join u on u.id = ev.provider_id where ev.outcome = 'filled'
        group by u.name, ev.rule, coalesce((ev.after_value->>'year')::int, (ev.before_value->>'year')::int), ev.start_precision) z),
    'classes', (select coalesce(jsonb_agg(x order by (x->>'rows')::int desc), '[]'::jsonb) from (
       select jsonb_build_object('university', u.name, 'class', coalesce(d.failure_class, case when d.next_action = 'complete' then 'complete' else 'not_classified_yet' end),
                'deterministic', bool_and(d.deterministic), 'rows', count(*), 'reason', min(d.reason), 'next_revisit_at', min(d.next_revisit_at), 'revisit_trigger', min(d.revisit_trigger)) x
         from d join u on u.id = d.provider_id
        group by u.name, coalesce(d.failure_class, case when d.next_action = 'complete' then 'complete' else 'not_classified_yet' end)) z),
    'refresh', jsonb_build_object(
       'budget', security.pipeline_num_v1('central.calendar_refresh_credit_budget', 40),
       'credits_counted', (select coalesce(sum(greatest(q.credit_estimate, coalesce(q.credits_used, 0))), 0) from pipeline.calendar_refresh_requests q),
       'credits_used', (select coalesce(sum(q.credits_used), 0) from pipeline.calendar_refresh_requests q),
       'requests', (select coalesce(jsonb_agg(jsonb_build_object('university', u.name, 'url', q.url, 'requested_at', q.requested_at, 'reason', q.reason, 'status', q.status,
                       'credits_used', q.credits_used, 'yield', q.yield, 'next_year_starts', q.next_year_starts) order by q.requested_at desc), '[]'::jsonb)
                      from pipeline.calendar_refresh_requests q join u on u.id = q.provider_id)),
    'reader', (select coalesce(jsonb_agg(jsonb_build_object('reader', s.reader_version, 'state', s.state, 'documents', s.n) order by s.reader_version nulls first, s.state), '[]'::jsonb)
                 from (select reader_version, state, count(*) n from pipeline.calendar_reread_state group by 1, 2) s),
    'jobs', (select coalesce(jsonb_agg(jsonb_build_object('job', j.jobname, 'schedule', j.schedule, 'last_run', (select h.last_run from jr h where h.jobid = j.jobid),
                       'last_status', (select h.last_status from jr h where h.jobid = j.jobid))), '[]'::jsonb)
               from cron.job j where j.jobname in ('calendar-reread', 'central-ai', 'provider-facts', 'intake-dates-apply', 'process-results')))
$$;


ALTER FUNCTION "security"."process_results_recovery_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."process_results_recovery_v1"() IS 'CF-247 (mandate 5 Nov 2026 §10, §16): the intake recovery measurement for the top Australian universities: values admitted in the window by university, source type, rule, year and precision with their publication state; rows by failure class with reason, next revisit and trigger; calendar refresh credits, requests and yield; documents by reader version and state; the jobs. Read only.';



CREATE OR REPLACE FUNCTION "security"."programme_create_v1"("p_apply" boolean DEFAULT true, "p_provider_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "statement_timeout" TO '120s'
    AS $$
declare
  v_cap int := security.pipeline_num_v1('batch.programme_create', 500)::int;
  v_family uuid := (select f.id from pim.attribute_families f where f.entity_type = 'course' and f.status = 'active' order by case when f.code = 'course_default' then 0 else 1 end limit 1);
  r record; v_course uuid; v_key text; v_src uuid; v_created int := 0; v_matched int := 0; v_skipped int := 0; v_n int := 0;
begin
  for r in
    select c.*, security.coverage_country(c.provider_id) cc, p.display_name pname, sl.id level_id,
           exists (select 1 from pipeline.country_scope_levels s where s.country_code = security.coverage_country(c.provider_id) and s.study_level_code = c.study_level_code) in_scope
      from pipeline.programme_candidates c
      join catalogue.providers p on p.id = c.provider_id
      left join ref.study_levels sl on sl.code = c.study_level_code
     where c.state = 'read' and (p_provider_id is null or c.provider_id = p_provider_id)
     order by c.provider_id, c.id
     limit v_cap
  loop
    v_n := v_n + 1;
    if r.study_level_code is null or not r.in_scope then
      if p_apply then update pipeline.programme_candidates set state = 'skipped', outcome = case when r.study_level_code is null then 'no_level' else 'level_out_of_scope' end, updated_at = now() where id = r.id; end if;
      v_skipped := v_skipped + 1; continue;
    end if;
    -- the university's existing course with this page, or with the same title
    select co.id into v_course from catalogue.courses co
      left join pipeline.coverage_course_pages pg on pg.course_id = co.id
     where co.provider_id = r.provider_id
       and (rtrim(pg.url, '/') = rtrim(r.url, '/') or rtrim(co.course_url, '/') = rtrim(r.url, '/')
            or security.programme_norm_v1(co.canonical_title) = security.programme_norm_v1(r.heading))
     order by (rtrim(pg.url, '/') = rtrim(r.url, '/')) desc nulls last, (co.lifecycle_status = 'active') desc, co.created_at
     limit 1;
    if v_course is not null then
      if p_apply then
        update catalogue.courses co set study_level_id = r.level_id, updated_at = now()
         where co.id = v_course and co.study_level_id is null
           and not exists (select 1 from pipeline.manual_locks l where l.entity = 'course' and l.entity_id = co.id and l.field = 'study_level_id');
        insert into pipeline.coverage_course_pages(course_id, provider_id, url, score, basis, status, identity_basis, next_read_at)
        values (v_course, r.provider_id, r.url, 1, 'programme_list', 'bound', 'exact_title', now())
        on conflict (course_id) do update set url = excluded.url, score = 1, basis = 'programme_list', status = 'bound', bound_at = now(), read_attempts = 0, next_read_at = now()
         where pipeline.coverage_course_pages.status <> 'bound';
        update pipeline.programme_candidates set state = 'matched', course_id = v_course, outcome = 'existing_course', updated_at = now() where id = r.id;
      end if;
      v_matched := v_matched + 1; continue;
    end if;
    if p_apply then
      select s.source_id into v_src from pipeline.programme_sources s where s.id = r.programme_source_id;
      if v_src is null then
        insert into pipeline.sources(source_type, provider_id, url, label, trust_rank, metadata)
        values ('institutional_catalogue', r.provider_id, (select s.url from pipeline.programme_sources s where s.id = r.programme_source_id),
                r.pname || ' programme list (university''s own site)', 50,
                jsonb_build_object('layer', '1', 'country', r.cc, 'coverage_role', 'first_party_programme_list', 'course_identity_scheme', 'programme_page_url', 'introduced', '20261022043000'))
        returning id into v_src;
        update pipeline.programme_sources set source_id = v_src where id = r.programme_source_id;
      end if;
      v_key := 'course:' || lower(r.cc) || ':programme_list:' || r.provider_id::text || ':' || md5(rtrim(r.url, '/'));
      insert into pim.entity_registry(entity_type, stable_key, family_id) values ('course', v_key, v_family)
      on conflict (stable_key) do nothing returning id into v_course;
      if v_course is null then v_skipped := v_skipped + 1; continue; end if;
      insert into catalogue.courses(id, stable_key, provider_id, canonical_title, display_title, course_url, study_level_id, lifecycle_status, publication_status, canonical_source_id, last_verified_at)
      values (v_course, v_key, r.provider_id, r.heading, r.heading, r.url, r.level_id, 'inactive', 'unpublished', v_src, now());
      insert into pipeline.coverage_course_pages(course_id, provider_id, url, score, basis, status, identity_basis, next_read_at)
      values (v_course, r.provider_id, r.url, 1, 'programme_list', 'bound', 'exact_title', now());
      update pipeline.programme_candidates set state = 'created', course_id = v_course, outcome = 'new_course', updated_at = now() where id = r.id;
    end if;
    v_created := v_created + 1;
  end loop;
  if p_apply and v_n > 0 then
    insert into pipeline.admin_control_events(area, action, target, detail)
    values ('programme_lists', 'create', coalesce(p_provider_id::text, 'all'), jsonb_build_object('created', v_created, 'matched', v_matched, 'skipped', v_skipped, 'note', 'created inactive; shown only after the programme list is approved'));
  end if;
  return jsonb_build_object('looked_at', v_n, 'created', v_created, 'matched', v_matched, 'skipped', v_skipped, 'applied', p_apply);
end $$;


