    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select btrim(regexp_replace(lower(translate(coalesce(p, ''), 'ÀÂÄÁÃÇÉÈÊËÎÏÍÌÔÖÓÒÛÜÚÙŸàâäáãçéèêëîïíìôöóòûüúùÿ’''', 'AAAAACEEEEIIIIOOOOUUUUYaaaaaceeeeiiiioooouuuuy  ')), '[^a-z0-9]+', ' ', 'g'))
$$;


