CREATE OR REPLACE FUNCTION "security"."progress_job_stage_v1"("p_job" "text", "p_area" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_job in ('provider-onboarding') then '1–7 Onboarding'
    when p_job ~ '^(course-link|coverage-read|coverage-discover|coverage-find-site|coverage-ai-match|coverage-reidentify|coverage-reextract|provider-contact|provider-facts|cricos-peo|firecrawl-)' then '2 Prepare'
    when p_job ~ '^(central-|adapter-)' and p_job <> 'adapter-overwrite' then '3–4 Adapter and central pages'
    when p_job ~ '^(adapter-overwrite|coverage-admit)' then '5 Enrich courses'
    when p_job ~ '^scholarship-(discover|listing)' then '6 Scholarship adapter'
    when p_job ~ '^scholarship-' then '7 Admit scholarships'
    when p_job ~ '(snapshot|report|summary)' then 'Reporting'
    when p_area = 'Layer 1 register' then 'Before onboarding: registers'
    when p_area in ('Search and API') then 'Delivery'
    else coalesce(p_area, 'Other') end
$$;


ALTER FUNCTION "security"."progress_job_stage_v1"("p_job" "text", "p_area" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."progress_measure_v1"("p_key" "text", "p_since" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb; v_l4max numeric := security.pipeline_num_v1('aer.schedule_layer4_max', 600);
begin
  case p_key
  when 'sch_classification' then
    select jsonb_build_object(
      'eligible', (select count(*) from pipeline.coverage_provider_reconciliation l where l.domain = 'scholarship' and l.disposition not in ('not_applicable', 'out_of_scope')),
      'providers_with_candidates', (select count(distinct c.provider_id) from pipeline.scholarship_page_candidates c),
      'providers_classified', (select count(*) from pipeline.scholarship_coverage_providers),
      'processed', (select count(*) from pipeline.scholarship_coverage_providers p where p.classified_at >= p_since),
      'created', (select count(*) from pipeline.scholarship_coverage_items i where i.present and i.classified_at >= p_since),
      'parked', (select count(*) from pipeline.scholarship_coverage_items i join pipeline.scholarship_coverage_state_codes s on s.code = i.state where i.present and not s.resolved),
      'parked_next', (select coalesce(jsonb_object_agg(z.state, z.n), '{}'::jsonb) from (select i.state, count(*) n from pipeline.scholarship_coverage_items i
                        join pipeline.scholarship_coverage_state_codes s on s.code = i.state where i.present and not s.resolved group by 1) z),
      'downstream', (select count(*) from pipeline.scholarship_coverage_items i where i.present and i.state in ('source_found_unread', 'traversal_incomplete', 'rejected_incorrectly')),
      'last_output_at', (select max(i.classified_at) from pipeline.scholarship_coverage_items i),
      'basis', 'eligible: in-scope providers of the scholarship coverage ledger (coverage_provider_reconciliation, not applicable and out of scope excluded); providers_with_candidates: providers with any candidate page ever found (the 755 read on 4 Nov, a subset, not an eligibility count); created: coverage cases classified; parked: unresolved cases by state; downstream: recoverable cases') into v;
  when 'sch_source_recovery' then
    select jsonb_build_object(
      'eligible', (select count(*) from pipeline.scholarship_coverage_items i where i.present and i.state in ('source_found_unread', 'traversal_incomplete', 'rejected_incorrectly')
                     and not exists (select 1 from pipeline.scholarship_coverage_recoveries r where r.item_key = i.item_key)),
      'processed', (select count(*) from pipeline.scholarship_coverage_recoveries r where r.at >= p_since),
      'created', (select count(*) from pipeline.scholarship_coverage_recoveries r where r.outcome = 'succeeded' and r.outcome_at >= p_since),
      'rejected', (select count(*) from pipeline.scholarship_coverage_recoveries r where r.outcome = 'failed' and r.outcome_at >= p_since),
      'rejected_reasons', jsonb_build_object('case did not move', (select count(*) from pipeline.scholarship_coverage_recoveries r where r.outcome = 'failed' and r.outcome_at >= p_since)),
      'downstream', (select count(*) from pipeline.scholarship_coverage_recoveries r where r.outcome is null),
      'last_output_at', (select max(r.outcome_at) from pipeline.scholarship_coverage_recoveries r where r.outcome = 'succeeded'),
      'basis', 'eligible: recoverable coverage cases with no recovery yet; created: recoveries whose case moved; downstream: recoveries awaiting their verification') into v;
  when 'sch_listing_traversal' then
    select jsonb_build_object(
      'eligible', (select count(*) from pipeline.scholarship_listing_pages l where l.active and coalesce(l.status, '') <> 'suggested' and (l.next_read_at is null or l.next_read_at <= now())),
      'processed', (select count(*) from pipeline.scholarship_listing_pages l where l.read_at >= p_since),
      'created', (select count(*) from pipeline.scholarship_listing_members m where m.first_seen >= p_since),
      'rejected', (select count(*) from pipeline.scholarship_listing_pages l where l.read_at >= p_since and l.error is not null),
      'rejected_reasons', (select coalesce(jsonb_object_agg(z.r, z.n), '{}'::jsonb) from (select left(l.error, 60) r, count(*) n from pipeline.scholarship_listing_pages l
                             where l.read_at >= p_since and l.error is not null group by 1 order by 2 desc limit 10) z),
      'parked', (select count(*) from pipeline.scholarship_listing_pages l where l.status = 'suggested'),
      'parked_next', jsonb_build_object('listing suggested, not yet a listing source (promote_listing, sch_cov.recover_listings_on)',
                                        (select count(*) from pipeline.scholarship_listing_pages l where l.status = 'suggested')),
      'downstream', (select count(*) from pipeline.scholarship_listing_members m where m.present and m.candidate_id is null),
      'last_output_at', (select max(m.first_seen) from pipeline.scholarship_listing_members m),
      'basis', 'eligible: active listing sources due a read; created: listing items found; parked: suggested listings; downstream: items not yet candidates') into v;
  when 'sch_candidate_matching' then
    select jsonb_build_object(
      'eligible', (select count(*) from pipeline.scholarship_listing_members m where m.present and m.candidate_id is null),
      'processed', (select count(*) from pipeline.scholarship_page_candidates c where c.found_at >= p_since),
      'created', (select count(*) from pipeline.scholarship_page_candidates c where c.found_at >= p_since),
      'downstream', (select count(*) from pipeline.scholarship_page_candidates c where c.read_status is null and c.read_at is null),
      'last_output_at', (select max(c.found_at) from pipeline.scholarship_page_candidates c),
      'basis', 'eligible: listing items not yet candidates; created: candidate pages found; downstream: candidates never read') into v;
  when 'sch_reading' then
    select jsonb_build_object(
      'eligible', (select count(*) from pipeline.scholarship_page_candidates c where c.read_at is null and (c.next_read_at is null or c.next_read_at <= now())),
      'processed', (select count(*) from pipeline.scholarship_page_candidates c where c.read_at >= p_since),
      'created', (select count(*) from pipeline.scholarship_page_candidates c where c.read_at >= p_since and c.http_status between 200 and 299),
      'rejected', (select count(*) from pipeline.scholarship_page_candidates c where c.read_at >= p_since and c.http_status is distinct from null and c.http_status not between 200 and 299),
      'rejected_reasons', (select coalesce(jsonb_object_agg(z.r, z.n), '{}'::jsonb) from (select coalesce(c.read_status, 'http ' || c.http_status) r, count(*) n
                             from pipeline.scholarship_page_candidates c where c.read_at >= p_since and c.http_status not between 200 and 299 group by 1 order by 2 desc limit 10) z),
      'downstream', (select count(*) from pipeline.scholarship_page_candidates c where c.read_at is not null and c.http_status between 200 and 299 and c.admit_status is null),
      'last_output_at', (select max(c.read_at) from pipeline.scholarship_page_candidates c where c.http_status between 200 and 299),
      'basis', 'eligible: candidates never read and due; created: pages read (HTTP 2xx); downstream: read pages awaiting an admission decision') into v;
  when 'sch_eligibility' then
    select jsonb_build_object(
      'eligible', (select count(*) from pipeline.scholarship_page_candidates c where c.read_at is not null and c.http_status between 200 and 299 and c.admit_status is null),
      'processed', (select count(*) from pipeline.scholarship_admission_log a where a.at >= p_since),
      'created', (select count(*) from pipeline.scholarship_admission_log a where a.at >= p_since and a.action = 'admitted'),
      'rejected', (select count(*) from pipeline.scholarship_admission_log a where a.at >= p_since and a.action in ('rejected', 'skipped', 'duplicate')),
      'excluded', (select count(*) from pipeline.scholarship_admission_log a where a.at >= p_since and a.action in ('skipped', 'duplicate')),
      'rejected_reasons', (select coalesce(jsonb_object_agg(z.r, z.n), '{}'::jsonb) from (select a.action || ': ' || coalesce(left(coalesce(a.detail->>'reason', a.detail->>'skip_reason',
                             a.detail->>'reasons'), 50), 'not stated') r, count(*) n from pipeline.scholarship_admission_log a
                             where a.at >= p_since and a.action in ('rejected', 'skipped', 'duplicate') group by 1 order by 2 desc limit 10) z),
      'parked', (select count(*) from pipeline.scholarship_ai_reviews r where r.status = 'pending'),
      'parked_next', jsonb_build_object('held for a person (Layer 4)', (select count(*) from pipeline.scholarship_ai_reviews r where r.status = 'pending')),
      'downstream', (select count(*) from pipeline.scholarship_ai_reviews r where r.status = 'pending'),
      'admitted', (select count(*) from pipeline.scholarship_admission_log a where a.at >= p_since and a.action = 'admitted'),
      'last_output_at', (select max(a.at) from pipeline.scholarship_admission_log a where a.action = 'admitted'),
      'basis', 'eligible: read pages with no admission decision; created/admitted: admission log admitted; excluded: skipped (directory site) and duplicates') into v;
  when 'sch_layer4' then
    select jsonb_build_object(
      'eligible', (select count(*) from pipeline.scholarship_ai_reviews r where r.status = 'pending'),
      'processed', (select count(*) from pipeline.scholarship_ai_reviews r where r.decided_at >= p_since),
      'created', (select count(*) from pipeline.scholarship_ai_reviews r where r.decided_at >= p_since and r.status = 'admitted'),
      'rejected', (select count(*) from pipeline.scholarship_ai_reviews r where r.decided_at >= p_since and r.status in ('refused', 'superseded')),
      'excluded', (select count(*) from pipeline.scholarship_ai_reviews r where r.decided_at >= p_since and r.status = 'superseded'),
      'rejected_reasons', (select coalesce(jsonb_object_agg(z.s, z.n), '{}'::jsonb) from (select r.status s, count(*) n from pipeline.scholarship_ai_reviews r
                             where r.decided_at >= p_since and r.status in ('refused', 'superseded') group by 1) z),
      'parked', (select count(*) from pipeline.scholarship_ai_reviews r where r.status = 'pending'),
      'parked_next', jsonb_build_object('a person decides in Layer 4', (select count(*) from pipeline.scholarship_ai_reviews r where r.status = 'pending')),
      'admitted', (select count(*) from pipeline.scholarship_ai_reviews r where r.decided_at >= p_since and r.status = 'admitted'),
      'last_output_at', (select max(r.decided_at) from pipeline.scholarship_ai_reviews r where r.status = 'admitted'),
      'basis', 'scholarship AI reviews held for a person: pending, admitted, refused, superseded') into v;
  when 'sch_admission' then
    select jsonb_build_object(
      'eligible', (select count(*) from pipeline.scholarship_admission_log a where a.at >= p_since and a.action = 'admitted'),
      'processed', (select count(*) from pipeline.scholarship_admission_log a where a.at >= p_since and a.action = 'admitted'),
      'created', (select count(*) from scholarship.scholarships s where s.created_at >= p_since and s.lifecycle_status = 'active'),
      'admitted', (select count(*) from scholarship.scholarships s where s.created_at >= p_since and s.lifecycle_status = 'active'),
      'downstream', (select count(*) from scholarship.scholarships s where s.lifecycle_status = 'active' and s.publication_status not in ('published', 'withdrawn')),
      'last_output_at', (select max(s.created_at) from scholarship.scholarships s where s.lifecycle_status = 'active'),
      'basis', 'admitted: active catalogue scholarships created (scholarship.scholarships, read only); downstream: active, not published, not withdrawn') into v;
  when 'sch_publication' then
    select jsonb_build_object(
      'eligible', (select count(*) from scholarship.scholarships s where s.lifecycle_status = 'active' and s.publication_status not in ('published', 'withdrawn')),
      'processed', (select count(*) from scholarship.scholarships s where s.lifecycle_status = 'active' and s.updated_at >= p_since),
      'created', (select count(*) from scholarship.scholarships s where s.lifecycle_status = 'active' and s.publication_status = 'published' and s.updated_at >= p_since),
      'published', (select count(*) from scholarship.scholarships s where s.lifecycle_status = 'active' and s.publication_status = 'published' and s.updated_at >= p_since),
      'published_total', (select count(*) from scholarship.scholarships s where s.lifecycle_status = 'active' and s.publication_status = 'published'),
      'last_output_at', (select max(s.updated_at) from scholarship.scholarships s where s.lifecycle_status = 'active' and s.publication_status = 'published'),
      'basis', 'published: active scholarships marked published and changed in the window (updated_at); consumer read-back (Website API v2, Zoho) is verified separately') into v;
  when 'aer_source_discovery' then
    select jsonb_build_object(
      'eligible', (select count(distinct g.provider_id) from pipeline.aer_gap_findings g where g.state = 'open' and g.root_cause = 'no_source'),
      'processed', (select count(*) from pipeline.aer_source_inventory s where s.recorded_at >= p_since) + (select count(*) from pipeline.entry_matrix_sources e where e.created_at >= p_since),
      'created', (select count(*) from pipeline.entry_matrix_sources e where e.created_at >= p_since),
      'parked', (select count(*) from pipeline.aer_gap_findings g where g.state = 'open' and g.root_cause = 'no_source'),
      'parked_next', (select coalesce(jsonb_object_agg(z.a, z.n), '{}'::jsonb) from (select coalesce(left(g.next_action, 60), 'no next action') a, count(*) n from pipeline.aer_gap_findings g
                        where g.state = 'open' and g.root_cause = 'no_source' group by 1 order by 2 desc limit 5) z),
      'downstream', (select count(*) from pipeline.entry_matrix_sources e where e.read_at is null and coalesce(e.status, '') <> 'failed'),
      'last_output_at', (select max(e.created_at) from pipeline.entry_matrix_sources e),
      'basis', 'eligible: providers with an open no_source AER gap; created: AER matrix sources found; downstream: sources not yet read') into v;
  when 'aer_extraction' then
    select jsonb_build_object(
      'eligible', (select count(distinct e.provider_id) from pipeline.entry_matrix_sources e where e.status = 'read'),
      'processed', coalesce((select sum(r.course_reads) from pipeline.aer_schedule_runs r where r.ran_at >= p_since), 0)
                   + (select count(*) from pipeline.entry_matrix_runs m where m.created_at >= p_since),
      'created', (select count(*) from catalogue.course_entry_requirements c where c.created_at >= p_since),
      'rejected', (select count(*) from pipeline.entry_matrix_runs m where m.created_at >= p_since and m.error is not null),
      'rejected_reasons', (select coalesce(jsonb_object_agg(z.r, z.n), '{}'::jsonb) from (select left(m.error, 60) r, count(*) n from pipeline.entry_matrix_runs m
                             where m.created_at >= p_since and m.error is not null group by 1 order by 2 desc limit 10) z),
      'downstream', (select count(*) from pipeline.layer4_review_items i where i.status = 'pending' and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run')),
      'cap', coalesce((select r.back_pressure or r.refusal is not null from pipeline.aer_schedule_runs r order by r.ran_at desc limit 1), false),
      'cap_detail', (select jsonb_build_object('ran_at', r.ran_at, 'back_pressure', r.back_pressure, 'room', r.room, 'layer4_waiting', r.layer4_waiting, 'refusal', r.refusal,
                       'layer4_limit', v_l4max) from pipeline.aer_schedule_runs r order by r.ran_at desc limit 1),
      'last_output_at', (select max(c.created_at) from catalogue.course_entry_requirements c),
      'basis', 'eligible: providers with a read AER source; processed: scheduled course reads and matrix runs; created: course entry rows proposed; cap: the last scheduled run''s back-pressure or refusal') into v;
  when 'aer_completeness' then
    select jsonb_build_object(
      'eligible', (select count(*) from catalogue.course_entry_requirements c where c.created_at >= p_since),
      'processed', (select count(*) from catalogue.course_entry_requirements c where c.created_at >= p_since),
      'created', (select count(*) from pipeline.layer4_review_items i where i.created_at >= p_since and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run')),
      'rejected', coalesce((select sum(m.rows_dropped) from pipeline.entry_matrix_runs m where m.created_at >= p_since), 0),
      'rejected_reasons', jsonb_build_object('rows dropped by the completeness gate (matrix runs)', coalesce((select sum(m.rows_dropped) from pipeline.entry_matrix_runs m where m.created_at >= p_since), 0)),
      'downstream', (select count(*) from pipeline.layer4_review_items i where i.status = 'pending' and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run')),
      'last_output_at', (select max(i.created_at) from pipeline.layer4_review_items i where i.field_code in ('course_entry_first_read', 'entry_matrix_first_run')),
      'basis', 'eligible: course entry rows proposed; created: AER Layer 4 items raised; rejected: matrix rows dropped') into v;
  when 'aer_technical_correction' then
    -- 4 Nov 2026 20:02 (v2.15.473 first run): the corrected reads of held items (D-R2, job aer-scheduled-read), not the lane's bookkeeping;
    -- eligible is what the shared rule (security.aer_recovery_rule_v1) allows a corrected read: deterministic holds are parked, not counted
    select jsonb_build_object(
      'eligible', (select count(*) from pipeline.work_items w where w.lane = 'aer_technical' and w.failure_class = 'aer_reread_eligible' and w.stage <> 'done'),
      'processed', (select count(*) from pipeline.aer_read_supersessions s where s.requested_at >= p_since),
      'created', (select count(*) from pipeline.aer_read_supersessions s where s.state = 'superseded' and s.closed_at >= p_since),
      'excluded', (select count(*) from pipeline.aer_read_supersessions s where s.state = 'refused' and s.closed_at >= p_since),
      'rejected', (select count(*) from pipeline.aer_read_supersessions s where s.state = 'refused' and s.closed_at >= p_since),
      'rejected_reasons', (select coalesce(jsonb_object_agg(z.k, z.n), '{}'::jsonb) from (select case when s.outcome ilike '%row limit%' then 'cut at the row limit'
                             when s.outcome ilike '%still drops%' then 'still drops printed requirements' else left(coalesce(s.outcome, 'refused'), 80) end k, count(*) n
                             from pipeline.aer_read_supersessions s where s.state = 'refused' and s.closed_at >= p_since group by 1) z),
      'downstream', (select count(*) from pipeline.aer_read_supersessions s join pipeline.layer4_review_items n on n.id = s.new_item_id
                      where s.state = 'superseded' and s.closed_at >= p_since),
      'in_progress', (select count(*) from pipeline.aer_read_supersessions s where s.state = 'requested'),
      'recovered', (select count(*) from pipeline.work_items w where w.lane = 'aer_technical' and w.recovered_at >= p_since),
      'cap', (select x.refusal is not null from pipeline.aer_schedule_runs x order by x.ran_at desc limit 1),
      'cap_detail', (select x.refusal from pipeline.aer_schedule_runs x order by x.ran_at desc limit 1),
      'parked', (select count(*) from pipeline.work_items w where w.lane = 'aer_technical' and w.stage = 'parked'),
      'parked_next', (select coalesce(jsonb_object_agg(z.k, z.n), '{}'::jsonb) from (select coalesce(w.failure_class, 'unclassified') || case when w.next_eligible_at is null then ' (no next time)' else '' end k,
                        count(*) n from pipeline.work_items w where w.lane = 'aer_technical' and w.stage = 'parked' group by 1) z),
      'last_output_at', (select max(s.closed_at) from pipeline.aer_read_supersessions s where s.state = 'superseded'),
      'basis', 'corrected reads of held AER items (job aer-scheduled-read): eligible = items the shared recovery rule allows a corrected read; processed = corrected reads asked; created = reads that replaced the held read; rejected = refused by the reader; parked = lane aer_technical holds by class') into v;
  when 'aer_layer4_review' then
    select jsonb_build_object(
      'eligible', (select count(*) from pipeline.layer4_review_items i where i.status = 'pending' and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run')),
      'processed', (select count(*) from pipeline.layer4_review_items i where i.decided_at >= p_since and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run')),
      'created', (select count(*) from pipeline.layer4_review_items i where i.decided_at >= p_since and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run')
                    and i.status not in ('pending', 'rejected', 'superseded', 'returned')),
      'rejected', (select count(*) from pipeline.layer4_review_items i where i.decided_at >= p_since and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run')
                     and i.status in ('rejected', 'superseded', 'returned')),
      'excluded', (select count(*) from pipeline.layer4_review_items i where i.decided_at >= p_since and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run') and i.status = 'superseded'),
      'parked', (select count(*) from pipeline.layer4_review_items i where i.status = 'pending' and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run')),
      'parked_next', jsonb_build_object('a person decides in Layer 4; reading pauses at the limit', v_l4max),
      'downstream', (select count(*) from pipeline.layer4_review_items i where i.decided_at >= p_since and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run')
                       and i.status not in ('pending', 'rejected', 'superseded', 'returned')),
      'last_output_at', (select max(i.decided_at) from pipeline.layer4_review_items i where i.field_code in ('course_entry_first_read', 'entry_matrix_first_run')
                           and i.status not in ('pending', 'rejected', 'superseded', 'returned')),
      'basis', 'Layer 4 AER items (course first read, matrix first run): pending, decided for admission, rejected or superseded') into v;
  when 'aer_active_records' then
    select jsonb_build_object(
      'eligible', (select count(*) from pipeline.layer4_review_items i where i.decided_at >= p_since and i.field_code in ('course_entry_first_read', 'entry_matrix_first_run')
                     and i.status not in ('pending', 'rejected', 'superseded', 'returned')),
      'processed', (select count(*) from catalogue.course_entry_requirements c where c.updated_at >= p_since and c.status in ('active', 'inactive')),
      'created', (select count(*) from catalogue.course_entry_requirements c where c.updated_at >= p_since and c.status = 'active'),
      'admitted', (select count(*) from catalogue.course_entry_requirements c where c.updated_at >= p_since and c.status = 'active'),
      'active_total', (select count(*) from catalogue.course_entry_requirements c where c.status = 'active'),
      'last_output_at', (select max(c.updated_at) from catalogue.course_entry_requirements c where c.status = 'active'),
      'basis', 'admitted: course entry rows made active in the window (catalogue.course_entry_requirements, read only)') into v;
  when 'aer_publication' then
    select jsonb_build_object(
      'eligible', (select count(*) from catalogue.course_entry_requirements c where c.updated_at >= p_since and c.status = 'active'),
      'processed', (select count(*) from catalogue.course_entry_requirements c where c.updated_at >= p_since and c.status = 'active'),
      'created', (select count(*) from catalogue.course_entry_requirements c join catalogue.courses k on k.id = c.course_id join catalogue.providers p on p.id = k.provider_id
                    where c.updated_at >= p_since and c.status = 'active' and p.publication_status = 'published'),
      'published', (select count(*) from catalogue.course_entry_requirements c join catalogue.courses k on k.id = c.course_id join catalogue.providers p on p.id = k.provider_id
                      where c.updated_at >= p_since and c.status = 'active' and p.publication_status = 'published'),
      'last_output_at', (select max(c.updated_at) from catalogue.course_entry_requirements c join catalogue.courses k on k.id = c.course_id join catalogue.providers p on p.id = k.provider_id
                           where c.status = 'active' and p.publication_status = 'published'),
      'basis', 'published: active entry rows of published providers, which the consumer API reads; read-back through Website API v2 and Zoho is verified separately') into v;
  -- job output contracts (pipeline.job_output_contracts; direction 4 Nov 2026 10:00 §6): created is the run's measurable output
  when 'l4_interventions' then
    select jsonb_build_object(
      'eligible', (select count(*) from pipeline.layer4_interventions i where i.status in ('ai_pending', 'awaiting_input', 'resuming') or i.created_at >= p_since),
      'interventions_created', (select count(*) from pipeline.layer4_interventions i where i.created_at >= p_since),
      'reused', (select count(*) from pipeline.layer4_interventions i where i.created_at < p_since and i.last_seen_at >= p_since),
      'resolved', (select count(*) from pipeline.layer4_interventions i where i.status in ('resolved', 'auto_resolved', 'not_published') and coalesce(i.verified_at, i.updated_at) >= p_since),
      'returned_to_recovery', (select count(*) from pipeline.layer4_interventions i where i.status = 'returned_technical' and i.updated_at >= p_since),
      'awaiting_human_input', (select count(*) from pipeline.layer4_interventions i where i.status = 'awaiting_input'),
      'processed', (select count(*) from pipeline.layer4_interventions i where i.updated_at >= p_since or i.last_seen_at >= p_since),
      'created', (select count(*) from pipeline.layer4_interventions i where i.created_at >= p_since or i.last_seen_at >= p_since
                    or (i.status in ('resolved', 'auto_resolved', 'not_published', 'returned_technical') and coalesce(i.verified_at, i.updated_at) >= p_since)),
      'downstream', (select count(*) from pipeline.layer4_interventions i where i.status = 'resuming'),
      'human_decided', (select count(*) from pipeline.layer4_intervention_events e where e.at >= p_since and e.actor is not null),
      'last_output_at', (select max(greatest(i.created_at, i.last_seen_at)) from pipeline.layer4_interventions i),
      'basis', 'created: interventions created, reused (repeat or changed evidence), resolved or returned to recovery since the run; awaiting_human_input: open now') into v;
  when 'l4_readiness' then
    select jsonb_build_object(
      'eligible', (select count(*) from pipeline.layer4_review_items i where i.status = 'pending'),
      'processed', (select count(*) from pipeline.layer4_readiness_runs r where r.at >= p_since),
      'checked', (select coalesce(sum((r.result->>'classified')::numeric), 0) from pipeline.layer4_readiness_runs r where r.at >= p_since),
      'created', (select coalesce(sum((r.result->>'classified')::numeric), 0) from pipeline.layer4_readiness_runs r where r.at >= p_since),
      'newly_classified', (select count(*) from pipeline.layer4_item_readiness x where x.classified_at >= p_since and x.item_created_at >= p_since),
      'technical_blocked', (select count(*) from pipeline.layer4_item_readiness x where x.classified_at >= p_since and x.readiness = 'technical_blocked'),
      'judgement_ready', (select count(*) from pipeline.layer4_item_readiness x where x.classified_at >= p_since and x.readiness = 'judgement_ready'),
      'superseded', (select count(*) from pipeline.layer4_supersessions s where s.at >= p_since and s.reversed_at is null),
      'downstream', (select count(*) from pipeline.layer4_item_readiness x where x.readiness = 'judgement_ready'),
      'last_output_at', (select max(r.at) from pipeline.layer4_readiness_runs r where coalesce((r.result->>'classified')::numeric, 0) > 0),
      'basis', 'checked: items classified by the runs since (layer4_readiness_runs); newly classified: items that arrived since; technical-blocked and judgement-ready: classified since; superseded: settled without a person') into v;
  when 'first_run_verify' then
    select jsonb_build_object(
      'eligible', (select count(*) from pipeline.progress_transitions),
      'processed', (select count(*) from pipeline.progress_observations o where o.measured_at >= p_since),
      'created', (select count(*) from pipeline.progress_observations o where o.measured_at >= p_since),
      'transitions_read', (select count(*) from pipeline.progress_observations o where o.measured_at >= p_since),
      'releases_judged', (select count(*) from pipeline.release_job_verifications r where r.checked_at >= p_since),
      'last_output_at', (select max(o.measured_at) from pipeline.progress_observations o),
      'basis', 'transitions read (progress_observations) and release jobs judged since the run') into v;
  -- intake dates (Platform Admin decision 5 Nov 2026 20:03: intake is one more chain of this observer; decision records of security.intake_dates_apply_v1)
  when 'intake_selection' then
    select jsonb_build_object(
      'eligible', (select count(*) from catalogue.course_intakes i join catalogue.courses c on c.id = i.course_id
                    where i.status = 'active' and c.lifecycle_status = 'active' and (i.intake_year is null or i.start_date is null or i.application_deadline is null)
                      and not exists (select 1 from pipeline.course_intake_dates d where d.intake_id = i.id and (d.next_revisit_at is null or d.next_revisit_at > now())))
                  + (select count(*) from pipeline.course_intake_dates d where d.next_revisit_at <= now()),
      'processed', (select count(*) from pipeline.course_intake_date_events e where e.run_at >= p_since and e.outcome <> 'withdrawn'),
      'created', (select count(*) from pipeline.course_intake_date_events e where e.run_at >= p_since and e.outcome <> 'withdrawn'),
      'providers', (select count(distinct e.provider_id) from pipeline.course_intake_date_events e where e.run_at >= p_since and e.outcome <> 'withdrawn'),
      'downstream', (select count(*) from pipeline.course_intake_date_events e where e.run_at >= p_since and e.outcome <> 'withdrawn'),
      'last_output_at', (select max(e.run_at) from pipeline.course_intake_date_events e where e.outcome <> 'withdrawn'),
      'basis', 'eligible: active intake rows missing a value never decided, plus decided rows whose revisit is due; created: intake rows decided by intake-dates-apply (or a governed Run Now) since') into v;
  when 'intake_admission' then
    select jsonb_build_object(
      'eligible', count(*), 'processed', count(*),
      'created', count(*) filter (where e.outcome = 'filled'), 'admitted', count(*) filter (where e.outcome = 'filled'),
      'rejected', count(*) filter (where e.outcome = 'skipped'),
      'rejected_reasons', (select coalesce(jsonb_object_agg(k, n), '{}'::jsonb) from (select coalesce(x.failure_class, 'not_classified_yet') k, count(*) n
                             from pipeline.course_intake_date_events x where x.run_at >= p_since and x.outcome = 'skipped' group by 1) r),
      -- correct exclusions: rows that lack evidence or wait for a person or a later edition (not a lock on a validated row, a reader failure or an unclassified row)
      'excluded', count(*) filter (where e.outcome = 'nothing_new' or (e.outcome = 'skipped' and e.failure_class in ('no_valid_calendar_source', 'stale_calendar_edition',
                    'wrong_institution_or_campus', 'course_identity_unresolved', 'academic_year_unproven', 'no_matching_commencement_period', 'multiple_periods_match',
                    'course_level_exception', 'missing_application_deadline_evidence', 'waiting_for_next_academic_year'))),
      'parked', count(*) filter (where e.outcome = 'skipped' and e.next_revisit_at is not null),
      'parked_next', (select coalesce(jsonb_object_agg(k, n), '{}'::jsonb) from (select coalesce(x.next_action, 'not recorded') k, count(*) n
                        from pipeline.course_intake_date_events x where x.run_at >= p_since and x.outcome = 'skipped' and x.next_revisit_at is not null group by 1) r),
      'downstream', count(*) filter (where e.outcome = 'filled' and e.publication_state is null),
      'last_output_at', (select max(x.run_at) from pipeline.course_intake_date_events x where x.outcome = 'filled'),
      'basis', 'eligible and processed: intake rows decided since; created and admitted: values admitted; rejected: refused or held, by failure class; excluded: refused for missing evidence or a person''s decision; parked: held with a revisit date')
      into v from pipeline.course_intake_date_events e where e.run_at >= p_since and e.outcome in ('filled', 'skipped', 'nothing_new');
  when 'intake_publication' then
    select jsonb_build_object(
      'eligible', (select count(*) from pipeline.course_intake_dates d where d.outcome = 'filled' and d.applied_at >= p_since),
      'processed', (select count(*) from pipeline.course_intake_dates d where d.outcome = 'filled' and d.publication_checked_at >= p_since),
      'created', (select count(*) from pipeline.course_intake_dates d where d.outcome = 'filled' and d.publication_checked_at >= p_since and d.publication_state = 'published'),
      'published', (select count(*) from pipeline.course_intake_dates d where d.outcome = 'filled' and d.publication_checked_at >= p_since and d.publication_state = 'published'),
      'rejected', (select count(*) from pipeline.course_intake_dates d where d.outcome = 'filled' and d.publication_checked_at >= p_since and d.publication_state = 'consumer_publication_failed'),
      'excluded', (select count(*) from pipeline.course_intake_dates d where d.outcome = 'filled' and d.publication_checked_at >= p_since
                     and d.publication_state in ('provider_not_published', 'course_not_in_consumer_source')),
      'downstream', (select count(*) from pipeline.course_intake_dates d where d.outcome = 'filled' and d.publication_state is null),
      'last_output_at', (select max(d.publication_checked_at) from pipeline.course_intake_dates d where d.outcome = 'filled' and d.publication_state = 'published'),
      'basis', 'eligible: values admitted since; processed: admitted values checked against the Website API v2 source since (security.intake_publication_check_v1); created and published: found there; excluded: provider not published or course not in the consumer source') into v;
  else
    raise exception 'no progress measure for transition %', p_key using errcode = '22023';
  end case;
  return v;
end $$;


ALTER FUNCTION "security"."progress_measure_v1"("p_key" "text", "p_since" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."progress_measure_v1"("p_key" "text", "p_since" timestamp with time zone) IS 'CF-247 (mandate 4 Nov 2026 08:16 §4): one transition of the progress contract counted from existing tables (read only).';



CREATE OR REPLACE FUNCTION "security"."progress_overview_v1"("p_group" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with g as (select coalesce(nullif(p_group, ''), 'all') grp, security.progress_cohort_v1(p_group) cohort),
  m as (
    select o.provider_id, o.status, o.stop_reason, o.result, security.provider_onboarding_stage_v1(o.status, o.stop_reason, o.result) stage,
           f.facts n, cp.baseline b
      from pipeline.provider_onboarding o cross join g
      left join pipeline.progress_provider_facts f on f.provider_id = o.provider_id
      left join pipeline.onboarding_pilot cp on cp.provider_id = o.provider_id and cp.cohort = g.cohort
     where g.cohort is null or cp.provider_id is not null),
  pg as (
    select count(*) filter (where c.status = 'bound' and c.read_status = 'read') correct,
           count(*) filter (where c.status = 'mismatch') wrong,
           count(*) filter (where c.read_status not in ('read', 'identity_mismatch')) failed,
           count(*) filter (where c.status = 'bound' and c.read_status = 'read' and c.fetched_via = 'firecrawl') via_firecrawl
      from pipeline.coverage_course_pages c
     where c.read_at > now() - interval '1 hour' and ((select cohort from g) is null or c.provider_id in (select provider_id from m))),
  w as (
    select count(*) n from pipeline.scholarship_page_candidates c
     where c.read_status = 'read' and c.admit_status is null and ((select cohort from g) is null or c.provider_id in (select provider_id from m)))
  select jsonb_build_object(
    'group', (select grp from g), 'at', now(), 'facts_at', (select max(at) from pipeline.progress_provider_facts),
    'universities', (select count(*) from m),
    'stages', (select jsonb_build_object(
        'provider_in', count(*) filter (where stage = 'provider_in'), 'prepare', count(*) filter (where stage = 'prepare'),
        'create_adapter', count(*) filter (where stage = 'create_adapter'), 'admit', count(*) filter (where stage = 'admit'),
        'enrich', count(*) filter (where stage = 'enrich'), 'scholarship_adapter', count(*) filter (where stage = 'scholarship_adapter'),
        'admit_scholarships', count(*) filter (where stage = 'admit_scholarships'), 'done', count(*) filter (where stage = 'done')) from m),
    'needs_person', (select count(*) from m where status = 'stopped' and stop_reason in ('nothing_ready', 'approve_central')),
    'stopped', (select count(*) from m where status = 'stopped' and stop_reason not in ('nothing_ready', 'approve_central')),
    'stop_reasons', (select coalesce(jsonb_object_agg(r, n), '{}'::jsonb) from (select stop_reason r, count(*) n from m where status = 'stopped' group by 1) x),
    'auto_admitted', (select count(*) from m where result ? 'auto_admitted'),
    'fields', (select jsonb_build_object(
        'courses', coalesce(sum((n->>'courses')::int), 0), 'intakes', coalesce(sum((n->>'intakes')::int), 0),
        'english', coalesce(sum((n->>'english')::int), 0), 'fee', coalesce(sum((n->>'fee')::int), 0), 'delivery', coalesce(sum((n->>'delivery')::int), 0),
        'courses_before', sum((b->>'courses')::int), 'intakes_before', sum((b->>'intakes')::int), 'english_before', sum((b->>'english')::int),
        'fee_before', sum((b->>'fee')::int), 'delivery_before', sum((b->>'delivery')::int)) from m),
    'scholarships', (select jsonb_build_object('found', coalesce(sum((n->>'scholarships')::int), 0), 'published', coalesce(sum((n->>'scholarships_published')::int), 0),
        'found_before', sum((b->>'scholarships')::int), 'published_before', sum((b->>'scholarships_published')::int), 'waiting_ai', (select n from w)) from m),
    'pages_hour', (select to_jsonb(pg) from pg),
    'budget', security.fc_budget_status_v1(),
    'ai_today', (select coalesce(jsonb_agg(jsonb_build_object('use', s.use, 'label', s.label, 'spent', s.spent, 'guard', s.guard)), '[]'::jsonb) from security.ai_spend_today_v1() s),
    'openrouter_usd', (select o.remaining_usd from pipeline.layer3_openrouter_observations o where o.kind = 'credits' order by o.observed_at desc limit 1))
$$;


ALTER FUNCTION "security"."progress_overview_v1"("p_group" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."progress_read_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare t pipeline.progress_transitions; m jsonb; z jsonb; v_since timestamptz := now() - make_interval(hours => security.pipeline_num_v1('progress.window_hours', 24)::int);
        v_stall_h int := security.pipeline_num_v1('progress.stall_hours', 6)::int; v_last timestamptz; v_stalled boolean; v_res jsonb; v_issue bigint;
        v_n int := 0; v_err int := 0; v_st int := 0; v_jobs jsonb; v_intake jsonb;
begin
  if security.pipeline_num_v1('progress.on', 1) < 1 then return jsonb_build_object('off', true); end if;
  -- the intake chain is read only while progress.intake_chain_on is 1 (decision 20:03; the other chains are always read)
  for t in select * from pipeline.progress_transitions x where x.chain <> 'intake' or security.pipeline_num_v1('progress.intake_chain_on', 1) >= 1 order by chain, step loop
    begin
      m := security.progress_measure_v1(t.key, v_since);
      z := security.progress_zero_reason_v1(t.key, m);
      v_last := greatest(t.last_advanced_at, case when coalesce((m->>'created')::numeric, 0) > 0 then (m->>'last_output_at')::timestamptz end);
      v_stalled := z is not null and z->>'reason' = 'technical_failure' and coalesce((m->>'eligible')::numeric, 0) > 0
                   and coalesce(v_last, '-infinity'::timestamptz) < now() - make_interval(hours => v_stall_h);
      v_issue := t.issue_id;
      if v_stalled then
        select coalesce(jsonb_agg(jsonb_build_object('job', j.jobname, 'active', j.active)), '[]'::jsonb) into v_jobs from cron.job j where j.jobname = any (t.producer_jobs);
        v_res := security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', 'stall:' || t.key,
          'title', 'Pipeline transition stalled: ' || t.chain || ' ' || lower(t.title) || ' (' || coalesce(m->>'eligible', '?') || ' eligible, nothing created for ' || v_stall_h || ' h)',
          'layer', case t.chain when 'aer' then 'AER' when 'intake' then 'Layer 2' else 'Scholarships' end, 'subsystem', 'progress contract: ' || t.key,
          'failure', coalesce(z->>'detail', 'no output') || '; last advanced ' || coalesce(v_last::text, 'never') || '; producing jobs ' || v_jobs::text,
          'expected', 'Eligible input advances to the next stage (' || coalesce(t.next_key, 'end of chain') || '), or the zero has a valid reason',
          'source', 'first-run-verify (progress contract)', 'validation_layer', 'V4', 'severity', 'P2', 'root_cause_class', 'unclassified', 'workstream', case t.chain when 'intake' then 'A8' else 'A7' end,
          'evidence', jsonb_build_object('transition', t.key, 'measures', m, 'zero_reason', z, 'jobs', v_jobs, 'window_start', v_since), 'observed_at', now()),
          'first-run-verify');
        v_issue := (v_res->>'id')::bigint; v_st := v_st + 1;
      end if;
      update pipeline.progress_transitions set measured_at = now(), window_start = v_since,
             input_eligible = (m->>'eligible')::numeric, input_processed = (m->>'processed')::numeric, output_created = (m->>'created')::numeric,
             output_rejected = (m->>'rejected')::numeric, rejected_reasons = m->'rejected_reasons', output_parked = (m->>'parked')::numeric, parked_next_actions = m->'parked_next',
             downstream_queued = (m->>'downstream')::numeric, output_admitted = (m->>'admitted')::numeric, output_published = (m->>'published')::numeric,
             last_advanced_at = v_last, zero_reason = z->>'reason', zero_detail = z->>'detail',
             stalled = v_stalled, stalled_since = case when v_stalled then coalesce(t.stalled_since, now()) end, issue_id = v_issue, measure_error = null
       where key = t.key;
      insert into pipeline.progress_observations(transition_key, window_start, measures, zero_reason, stalled) values (t.key, v_since, m || jsonb_build_object('zero', z), z->>'reason', v_stalled);
      v_n := v_n + 1;
    exception when others then
      update pipeline.progress_transitions set measure_error = left(sqlerrm, 300), measured_at = now() where key = t.key;
      v_err := v_err + 1;
    end;
  end loop;
  -- decision 5 Nov 2026 20:03: the intake conditions the transition contract cannot express (one provider monopolising, a partial publication
  -- mismatch, a deterministic failure repeated unchanged), isolated so a failure never stops the readings above
  if exists (select 1 from pipeline.progress_transitions x where x.chain = 'intake') and security.pipeline_num_v1('progress.intake_chain_on', 1) >= 1 then
    begin v_intake := security.intake_progress_checks_v1(); exception when others then v_intake := jsonb_build_object('error', left(sqlerrm, 300)); end;
  end if;
  return jsonb_build_object('read', v_n, 'errors', v_err, 'stalled', v_st, 'since', v_since) || case when v_intake is null then '{}'::jsonb else jsonb_build_object('intake', v_intake) end;
end $$;


ALTER FUNCTION "security"."progress_read_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."progress_snapshot_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int; v_g text;
begin
  insert into pipeline.progress_provider_facts(provider_id, at, facts)
  select x.provider_id, now(), security.provider_fill_counts_v1(x.provider_id)
    from (select provider_id from pipeline.provider_onboarding union select provider_id from pipeline.onboarding_pilot) x
  on conflict (provider_id) do update set at = excluded.at, facts = excluded.facts;
  get diagnostics v_n = row_count;
  foreach v_g in array array['all', 'pilot', 'top'] loop
    insert into pipeline.progress_snapshots(at, grp, data) values (now(), v_g, security.progress_overview_v1(v_g) - 'budget' - 'ai_today'
      || jsonb_build_object('billed_today', security.fc_billed_today_v1(), 'ai_spent_today', (select coalesce(sum(s.spent), 0) from security.ai_spend_today_v1() s)));
  end loop;
  delete from pipeline.progress_snapshots where at < now() - make_interval(days => security.pipeline_num_v1('retention.progress_snapshots_days', 90)::int);
  return jsonb_build_object('providers', v_n, 'at', now());
end $$;


ALTER FUNCTION "security"."progress_snapshot_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."progress_zero_reason_v1"("p_key" "text", "m" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare t pipeline.progress_transitions; v_jobs int; v_active int; v_off text[];
begin
  select * into t from pipeline.progress_transitions where key = p_key;
  if t.key is null then  -- a job output contract (pipeline.job_output_contracts)
    select c.measure_key, array[c.jobname], c.switch_keys into t.key, t.producer_jobs, t.switch_keys from pipeline.job_output_contracts c where c.measure_key = p_key;
  end if;
  if coalesce((m->>'created')::numeric, 0) > 0 then return null; end if;
  select count(*), count(*) filter (where j.active) into v_jobs, v_active from cron.job j where j.jobname = any (t.producer_jobs);
  if v_jobs > 0 and v_active = 0 then
    return jsonb_build_object('reason', 'blocked_authority', 'detail', 'producing job(s) paused: ' || array_to_string(t.producer_jobs, ', '));
  end if;
  select coalesce(array_agg(k), '{}') into v_off from unnest(t.switch_keys) k where security.pipeline_num_v1(k, 0) < 1;
  if cardinality(t.switch_keys) > 0 and cardinality(v_off) = cardinality(t.switch_keys) then
    return jsonb_build_object('reason', 'blocked_authority', 'detail', 'switched off: ' || array_to_string(v_off, ', '));
  end if;
  if coalesce((m->>'cap')::boolean, false) then return jsonb_build_object('reason', 'cap_reached', 'detail', coalesce(m->>'cap_detail', 'a valid cap')); end if;
  if coalesce((m->>'eligible')::numeric, 0) = 0 then return jsonb_build_object('reason', 'no_eligible_work', 'detail', 'nothing eligible: ' || coalesce(m->>'basis', '')); end if;
  if coalesce((m->>'processed')::numeric, 0) > 0 and coalesce((m->>'excluded')::numeric, 0) >= (m->>'processed')::numeric then
    return jsonb_build_object('reason', 'correctly_excluded', 'detail', 'every processed input was excluded by a recorded rule');
  end if;
  return jsonb_build_object('reason', 'technical_failure', 'detail', coalesce(m->>'eligible', '?') || ' eligible, ' || coalesce(m->>'processed', '0') || ' processed, nothing created');
end $$;


ALTER FUNCTION "security"."progress_zero_reason_v1"("p_key" "text", "m" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."prompt_answer_check_v1"("p_service" "text", "p_version" "text", "p_answer" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_schema jsonb; v_problems text[];
begin
  select answer_schema into v_schema from pipeline.prompt_templates where service_code = p_service and version = p_version;
  if not found then raise exception 'no prompt % %', p_service, p_version; end if;
  if v_schema is null then return jsonb_build_object('ok', null, 'problems', '[]'::jsonb, 'note', 'no answer schema captured yet'); end if;
  v_problems := security.json_schema_problems_v1(v_schema, p_answer, '$');
  return jsonb_build_object('ok', cardinality(v_problems) = 0, 'problems', to_jsonb(v_problems));
end $_$;


ALTER FUNCTION "security"."prompt_answer_check_v1"("p_service" "text", "p_version" "text", "p_answer" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."prompt_registry_parity_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'service', t.service_code, 'version', t.version, 'status', t.status, 'source', t.source,
    'system_text_matches', case
      when t.source like 'pipeline.provider_description_prompts%' then
        t.system_sha256 = (select encode(sha256(convert_to(p.system_prompt, 'UTF8')), 'hex') from pipeline.provider_description_prompts p where p.status = 'active' order by p.activated_at desc nulls last limit 1)
      when t.source like 'pipeline.scholarship_ai_prompts%' then
        t.system_sha256 = (select encode(sha256(convert_to(p.text, 'UTF8')), 'hex') from pipeline.scholarship_ai_prompts p where p.active order by p.created_at desc limit 1)
      else null end,
    'checked_by', case when t.source like 'worker code%' then 'spec s553 against the worker source (sha-256 in the worker)' else 'this report, against the active database prompt' end,
    'models_match_route', t.pinned_models = (select r.cascade from pipeline.ai_service_routes r where r.service_code = t.service_code))
    order by t.service_code, t.version), '[]'::jsonb)
  from pipeline.prompt_templates t
$$;


ALTER FUNCTION "security"."prompt_registry_parity_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."prompt_render_v1"("p_service" "text", "p_version" "text", "p_vars" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare t pipeline.prompt_templates%rowtype; v_user text; v_name text;
begin
  select * into t from pipeline.prompt_templates where service_code = p_service and version = p_version;
  if t.service_code is null then raise exception 'no prompt % %', p_service, p_version; end if;
  v_user := t.user_template;
  if v_user is not null then
    for v_name in select distinct m[1] from regexp_matches(v_user, '\{\{([a-z_]+)\}\}', 'g') m loop
      if not v_name = any(t.variables) then raise exception 'prompt % %: placeholder {{%}} is not declared', p_service, p_version, v_name; end if;
    end loop;
    foreach v_name in array t.variables loop
      if p_vars is null or not (p_vars ? v_name) then raise exception 'prompt % %: variable % is not given', p_service, p_version, v_name; end if;
      v_user := replace(v_user, '{{' || v_name || '}}', p_vars->>v_name);
    end loop;
  end if;
  return jsonb_build_object('service', t.service_code, 'version', t.version, 'system', t.system_text, 'user', v_user, 'models', to_jsonb(t.pinned_models));
end $$;


ALTER FUNCTION "security"."prompt_render_v1"("p_service" "text", "p_version" "text", "p_vars" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_adapter_status_v1"("p_provider" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    (select 'building' from pipeline.adapter_autobuilds b where b.provider_id = p_provider and b.status not in ('done', 'failed', 'stopped') limit 1),
    (select case when not u.enabled then 'off' when u.admit then 'admitting' else 'testing' end from pipeline.uni_adapters u where u.provider_id = p_provider),
    -- 22 Oct 2026 (Platform Admin 16:22): no active course means nothing for an adapter to read
    case when not exists (select 1 from catalogue.courses c where c.provider_id = p_provider and c.lifecycle_status = 'active') then 'no_courses' end,
    'none')
$$;


ALTER FUNCTION "security"."provider_adapter_status_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_adapter_status_v1"("p_provider" "uuid") IS 'CF-247 22 Oct 2026: a provider''s adapter status for the Providers list: building, admitting, testing, off or none.';



CREATE OR REPLACE FUNCTION "security"."provider_archive_apply_v1"("p_provider_id" "uuid", "p_source" "text", "p_reason" "text", "p_actor" "uuid", "p_manual" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_life text; v_pub text; v_now text; v_ad int; v_lr int; v_rv jsonb; v_id bigint;
begin
  select p.lifecycle_status, p.publication_status into v_life, v_pub from catalogue.providers p where p.id = p_provider_id for update;
  if not found then raise exception 'provider not found'; end if;
  if v_life = 'archived' then return jsonb_build_object('status', 'already_archived', 'provider_id', p_provider_id); end if;
  if p_manual then perform set_config('cf.manual_edit', 'on', true); end if;
  update catalogue.providers set lifecycle_status = 'archived', publication_status = 'unpublished', updated_at = now() where id = p_provider_id;
  select p.lifecycle_status into v_now from catalogue.providers p where p.id = p_provider_id;
  if v_now <> 'archived' then return jsonb_build_object('status', 'kept_by_hand', 'provider_id', p_provider_id); end if;
  with a as (update pipeline.uni_adapters set enabled = false, updated_at = now() where provider_id = p_provider_id and enabled returning 1) select count(*) into v_ad from a;
  with r as (update pipeline.course_link_recipes set active = false, updated_at = now() where provider_id = p_provider_id and active returning 1) select count(*) into v_lr from r;
  with i as (update pipeline.layer4_review_items x set status = 'superseded', decided_at = now()
              where x.status = 'pending' and ((x.entity_type = 'provider' and x.entity_id = p_provider_id)
                    or (x.entity_type = 'course' and x.entity_id in (select c.id from catalogue.courses c where c.provider_id = p_provider_id)))
             returning x.id)
  select coalesce(jsonb_agg(i.id), '[]'::jsonb) into v_rv from i;
  insert into pipeline.provider_archives(provider_id, source, reason, previous_lifecycle, previous_publication, cascade, archived_by)
  values (p_provider_id, p_source, left(btrim(coalesce(nullif(p_reason, ''), 'Archived')), 500), v_life, v_pub,
          jsonb_build_object('adapter_switched_off', v_ad > 0, 'link_recipe_switched_off', v_lr > 0, 'reviews_superseded', v_rv), p_actor)
  returning id into v_id;
  insert into pipeline.manual_edit_log(entity, entity_id, field, action, before, after, reason, actor)
  values ('provider', p_provider_id, 'lifecycle_status', 'archive', to_jsonb(v_life), to_jsonb('archived'::text), left(p_source || ': ' || coalesce(p_reason, ''), 500), p_actor);
  insert into search.refresh_requests(requested_by) values (format('provider %s archived (%s)', left(p_provider_id::text, 8), p_source));
  return jsonb_build_object('status', 'archived', 'provider_id', p_provider_id, 'archive_id', v_id, 'adapter_switched_off', v_ad > 0,
                            'link_recipe_switched_off', v_lr > 0, 'reviews_superseded', jsonb_array_length(v_rv));
end $$;


ALTER FUNCTION "security"."provider_archive_apply_v1"("p_provider_id" "uuid", "p_source" "text", "p_reason" "text", "p_actor" "uuid", "p_manual" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_archive_preview_v1"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'provider_id', p.id, 'name', coalesce(p.display_name, p.canonical_name), 'lifecycle_status', p.lifecycle_status, 'publication_status', p.publication_status,
    'items', jsonb_build_array(
      jsonb_build_object('key', 'hidden', 'count', null, 'effect', 'Unpublished and hidden from Wix, Zoho, the website and search, with its courses, campuses and scholarships. Records are kept.'),
      jsonb_build_object('key', 'courses', 'count', (select count(*) from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active'), 'effect', 'Active courses: hidden with the provider; each course keeps its own status, so restoring brings them back as they were.'),
      jsonb_build_object('key', 'campuses', 'count', (select count(*) from catalogue.campuses x where x.provider_id = p.id), 'effect', 'Campuses: hidden with the provider.'),
      jsonb_build_object('key', 'scholarships', 'count', (select count(*) from scholarship.scholarships s where s.provider_id = p.id and s.lifecycle_status = 'active'), 'effect', 'Scholarships: hidden with the provider.'),
      jsonb_build_object('key', 'adapter', 'count', (select count(*) from pipeline.uni_adapters a where a.provider_id = p.id and a.enabled), 'effect', 'Adapter: switched off; switched back on at restore.'),
      jsonb_build_object('key', 'link_recipe', 'count', (select count(*) from pipeline.course_link_recipes r where r.provider_id = p.id and r.active), 'effect', 'Course link search: switched off; switched back on at restore.'),
      jsonb_build_object('key', 'reviews', 'count', (select count(*) from pipeline.layer4_review_items x where x.status = 'pending'
                           and ((x.entity_type = 'provider' and x.entity_id = p.id) or (x.entity_type = 'course' and x.entity_id in (select c.id from catalogue.courses c where c.provider_id = p.id)))),
                         'effect', 'Layer 4 reviews waiting: closed as superseded; reopened at restore.'),
      jsonb_build_object('key', 'background', 'count', null, 'effect', 'Background work (page finding and reading, AI matching, link search, provider facts, scholarships, contact reads) stops picking it up.')))
    from catalogue.providers p where p.id = p_provider_id
$$;


ALTER FUNCTION "security"."provider_archive_preview_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_basis_rule_admit_v1"("p_apply" boolean DEFAULT false, "p_limit" integer DEFAULT 200) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'search'
    AS $_$
declare r record; v_text text; v_m text[]; v_basis text; v_year int; v_code text; v_source uuid; v_key text; v_fee uuid; v_review uuid;
        v_admitted int:=0; v_nomatch int:=0; v_courses uuid[]:='{}'; v_samples jsonb:='[]'::jsonb; v_amt_re text;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  for r in
    select w.id wid, w.entity_id course_id, w.evidence_id, w.interpretation_id, br.rule_code, br.fee_pattern, br.basis_map,
           (w.candidate_context->'provider_current_tuition'->>'amount')::numeric amount,
           (select f->>'context' from jsonb_array_elements(coalesce(w.candidate_context->'fee_candidates','[]'::jsonb)) f
             where jsonb_typeof(f)='object' and (f->>'amount')::numeric=(w.candidate_context->'provider_current_tuition'->>'amount')::numeric
               and coalesce((f->>'domestic')::boolean,false)=false order by (f->>'score')::numeric desc nulls last limit 1) ctx
      from pipeline.layer3_work_items w
      join catalogue.courses c on c.id=w.entity_id
      join pipeline.provider_fee_basis_rules br on br.provider_id=c.provider_id and br.active and br.review_by>=current_date
      join pipeline.evidence_artifacts e on e.id=w.evidence_id and e.source_url ~* br.page_url_pattern
     where w.task_class='provider_current_tuition_validation'
       and w.status in ('pending','layer4_required','failed','no_candidate','rejected')
       and coalesce(w.candidate_context->'provider_current_tuition'->>'audience','')='international'
       and not exists (select 1 from catalogue.course_fees f where f.course_id=w.entity_id and f.fee_type='provider_current_tuition' and f.status='active')
     limit greatest(1,least(coalesce(p_limit,200),2000))
  loop
    v_text:=security.layer4_clean_quote(r.ctx);
    v_amt_re:=replace(to_char(trunc(r.amount)::bigint,'FM999,999,999'),',',',?');
    v_m:=regexp_match(coalesce(v_text,''), replace(r.fee_pattern,'{AMOUNT}',v_amt_re)||'([^0-9,]|$)', 'i');
    if v_m is null then v_nomatch:=v_nomatch+1; continue; end if;
    v_year:=v_m[1]::int; v_basis:=r.basis_map->>lower(v_m[2]);
    if v_basis is null then v_nomatch:=v_nomatch+1; continue; end if;
    if jsonb_array_length(v_samples)<6 then v_samples:=v_samples||jsonb_build_object('amount',r.amount,'year',v_year,'basis',v_basis,'text',left(substring(v_text from '(?i)full-fee places.{0,60}'),90)); end if;
    if not p_apply then v_admitted:=v_admitted+1; continue; end if;
    select course_code into v_code from catalogue.courses where id=r.course_id;
    select source_id into v_source from pipeline.evidence_artifacts where id=r.evidence_id;
    if v_code is null or v_source is null then v_nomatch:=v_nomatch+1; continue; end if;
    v_key:=lower(upper(btrim(v_code))||':international:'||v_year||':'||v_basis);
    v_fee:=null;
    insert into catalogue.course_fees(course_id,fee_year,audience,fee_type,amount,currency_code,basis,notes,source_id,evidence_id,confidence,campus_id,source_fee_key,status,last_verified_at,source_snapshot_at,updated_at)
    values (r.course_id,v_year,'international','provider_current_tuition',r.amount,'AUD',v_basis,
            format('CF-247 provider basis rule admission (deterministic, Decision 162); rule %s; work item %s',r.rule_code,r.wid),
            v_source,r.evidence_id,1,null,v_key,'active',now(),now(),now())
    on conflict(course_id,source_id,source_fee_key) where source_id is not null and source_fee_key is not null do nothing
    returning id into v_fee;
    update pipeline.layer3_work_items set status='admitted', completed_at=now(), last_error=null, updated_at=now() where id=r.wid;
    v_review:=null;
    if r.interpretation_id is not null then
      update pipeline.layer4_review_items set status='superseded', decided_at=now() where layer3_interpretation_id=r.interpretation_id and status='pending' returning id into v_review;
    end if;
    insert into pipeline.provider_rule_admissions(work_item_id,review_item_id,course_id,course_fee_id,rule_code,amount,basis,matched_text)
    values (r.wid,v_review,r.course_id,v_fee,r.rule_code,r.amount,v_basis,left(v_text,500));
    v_courses:=v_courses||r.course_id; v_admitted:=v_admitted+1;
  end loop;
  if p_apply and cardinality(v_courses)>0 then perform search.refresh_course_enrichment_scoped_v1(v_courses,true); end if;
  return jsonb_build_object('mode',case when p_apply then 'apply' else 'proof' end,'admitted',v_admitted,'not_matched',v_nomatch,'samples',v_samples);
end $_$;


ALTER FUNCTION "security"."provider_basis_rule_admit_v1"("p_apply" boolean, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_catalogue_facts_v1"("p_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_feeds" boolean DEFAULT true) RETURNS TABLE("provider_id" "uuid", "description_filled" boolean, "admission_state" "text", "source_tier" "text", "evidence_id" "uuid", "source_url" "text", "admitted_at" timestamp with time zone, "admitted_by" "text", "reader_state" "text", "reader_rule" "text", "reader_via" "text", "reader_tries" integer, "reader_updated_at" timestamp with time zone, "last_read_ok_at" timestamp with time zone, "hold_reason" "text", "hold_rule" "text", "next_retry_at" timestamp with time zone, "l4_status" "text", "l4_at" timestamp with time zone, "l4_actor" "text", "canonical_status" "text", "website_state" "text", "zoho_state" "text", "mismatch" "text", "readback_at" timestamp with time zone, "readback_website" boolean, "readback_zoho" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "plan_cache_mode" TO 'force_custom_plan'
    AS $$
#variable_conflict use_column
  -- p_ids null = every provider; an empty array = none. p_feeds false skips the two feed candidate scans (they read every provider) and leaves
  -- website_state, zoho_state and mismatch null: the page asks for them only when a column, filter or sort needs them. Reads only; nothing is written. A provider is attributed an admission only when its
  -- catalogue description is the very text that was admitted (a later hand edit leaves it "unrecorded", never credited to the pipeline).
begin
  -- Planned with the actual p_ids and p_feeds on every call (the function is set to force_custom_plan). As a SQL function it was planned once with the arguments
  -- unknown: the planner then expected a handful of providers and chose row-by-row nested loops that took seconds when p_ids is null (every provider).
  return query
  with pv as (
    select p.id, p.stable_key, p.lifecycle_status, p.publication_status, nullif(btrim(p.description), '') descr
      from catalogue.providers p where p_ids is null or p.id = any(p_ids)
  ), lr as (
    select distinct on (r.provider_id) r.provider_id, r.id read_id, r.state, r.rule, r.reason, r.read_via, r.tries, r.next_try_at, r.evidence_id, r.source_url,
           r.review_item_id, r.created_at, r.updated_at, r.consumer_checked_at, r.consumer_checks
      from pipeline.provider_description_reads r join pv on pv.id = r.provider_id
     order by r.provider_id, r.created_at desc, r.id desc
  ), ar as (
    select distinct on (r.provider_id) r.provider_id, r.read_via, r.evidence_id, r.source_url, r.review_item_id, coalesce(r.last_verified_at, r.updated_at) at,
           r.consumer_checked_at, r.consumer_checks
      from pipeline.provider_description_reads r join pv on pv.id = r.provider_id
     where r.state in ('admitted', 'verified') and nullif(btrim(r.proposal ->> 'description'), '') = pv.descr
     order by r.provider_id, coalesce(r.last_verified_at, r.updated_at) desc, r.id desc
  ), la as (
    select a.provider_id, a.tier, a.created_at, a.evidence_id, a.source_url
      from pipeline.provider_description_machine_admissions a join pv on pv.id = a.provider_id
     where a.outcome = 'admitted' and a.withdrawn_at is null and nullif(btrim(a.after_description), '') = pv.descr
  ), ld as (
    select distinct on (a.provider_id) a.provider_id, a.tier, a.reason, a.review_item_id
      from pipeline.provider_description_machine_admissions a join pv on pv.id = a.provider_id
     where a.outcome = 'declined'
     order by a.provider_id, a.created_at desc, a.id desc
  ), okr as (
    -- a successful read is a page captured as evidence by a page read (stored, direct or Firecrawl); register-fact profiles read no page
    select r.provider_id, max(coalesce(r.source_captured_at, r.last_verified_at)) at
      from pipeline.provider_description_reads r join pv on pv.id = r.provider_id
     where r.evidence_id is not null and r.read_via is not null
     group by r.provider_id
  ), l4 as (
    select x.provider_id, ri.status, ri.decided_at,
           (select d.layer2_state ->> 'actor_kind' from pipeline.layer4_decisions d where d.review_item_id = ri.id order by d.created_at desc limit 1) actor_kind
      from (select pv.id provider_id, coalesce(lr.review_item_id, ar.review_item_id) rid from pv left join lr on lr.provider_id = pv.id left join ar on ar.provider_id = pv.id) x
      join pipeline.layer4_review_items ri on ri.id = x.rid
  ), wf as (
    select i.item_key, i.removed_at, nullif(btrim(i.item ->> 'description'), '') d from pipeline.website_sync_items i join pv on pv.stable_key = i.item_key where i.entity = 'provider'
  ), zf as (
    select i.item_key, i.removed_at, nullif(btrim(i.item ->> 'description'), '') d from pipeline.zoho_sync_items i join pv on pv.stable_key = i.item_key where i.entity = 'provider'
  ), wc as (select c.ref_id from security.website_sync_candidates_v1('provider') c where p_feeds and c.ref_id is not null),
     zc as (select c.ref_id from security.zoho_sync_candidates_v1('provider') c where p_feeds and c.ref_id is not null),
  base as (
    select pv.id provider_id, pv.descr, pv.lifecycle_status, pv.publication_status,
           lr.state lr_state, lr.rule lr_rule, lr.reason lr_reason, lr.read_via lr_via, lr.tries lr_tries, lr.next_try_at, lr.updated_at lr_updated,
           lr.evidence_id lr_evidence, lr.source_url lr_url, lr.review_item_id lr_item, lr.consumer_checked_at lr_checked, lr.consumer_checks lr_checks,
           la.tier la_tier, la.created_at la_at, la.evidence_id la_evidence, la.source_url la_url,
           ar.read_via ar_via, ar.at ar_at, ar.evidence_id ar_evidence, ar.source_url ar_url, ar.consumer_checked_at ar_checked, ar.consumer_checks ar_checks,
           ld.tier ld_tier, ld.reason ld_reason, ld.review_item_id ld_item,
           okr.at ok_at, l4.status l4_status, l4.decided_at l4_at, l4.actor_kind l4_actor,
           (la.provider_id is not null or ar.provider_id is not null) has_admission,
           (select ri2.decided_at from pipeline.layer4_review_items ri2 where ri2.id = ar.review_item_id) ar_decided,
           (wf.item_key is not null and wf.removed_at is null) w_live, wf.d w_d, (wc.ref_id is not null) w_cand,
           (zf.item_key is not null and zf.removed_at is null) z_live, zf.d z_d, (zc.ref_id is not null) z_cand
      from pv
      left join lr on lr.provider_id = pv.id
      left join ar on ar.provider_id = pv.id
      left join la on la.provider_id = pv.id
      left join ld on ld.provider_id = pv.id
      left join okr on okr.provider_id = pv.id
      left join l4 on l4.provider_id = pv.id
      left join wf on wf.item_key = pv.stable_key
      left join zf on zf.item_key = pv.stable_key
      left join wc on wc.ref_id = pv.id
      left join zc on zc.ref_id = pv.id
  ), st as (
    select b.*,
      case when b.descr is not null and b.has_admission then 'admitted'
           when b.descr is not null then 'unrecorded'
           -- a proposal waiting for its Layer 4 decision is pending, whatever the machine rule said about it: declined is a decision already taken
           when b.lr_state in ('proposed', 'queued', 'reading') and b.l4_status = 'pending' then 'pending'
           when b.lr_state = 'rejected' or b.lr_rule like 'machine\_declined%' or (b.lr_item is not null and b.lr_item = b.ld_item) then 'declined'
           when b.lr_state in ('held', 'dead_letter') then 'held'
           when b.lr_state in ('queued', 'reading', 'proposed') then 'pending'
           else 'none' end admission_state,
      -- Website feed: matched = the feed item holds the same text; pending = the feed item holds other text (the existing feed scan refreshes it);
      -- missing = the scan serves this provider but holds no item for it; not applicable = not a provider the feed serves, or nothing to publish
      case when b.descr is null then (case when b.w_live and b.w_d is not null then 'pending' else 'not_applicable' end)
           when b.w_live and b.w_d = b.descr then 'matched'
           when b.w_live then 'pending'
           when b.w_cand then 'missing'
           else 'not_applicable' end website_state,
      case when b.descr is null then (case when b.z_live and b.z_d is not null then 'pending' else 'not_applicable' end)
           when b.z_live and b.z_d = b.descr then 'matched'
           when b.z_live then 'pending'
           when b.z_cand then 'missing'
           else 'not_applicable' end zoho_state
      from base b
  )
  select s.provider_id, (s.descr is not null), s.admission_state,
         case when s.descr is not null then coalesce(s.la_tier, s.ar_via, 'unknown')
              else coalesce(s.lr_via, case when s.lr_rule in ('registry_factual', 'insufficient_verified_facts') then 'registry_factual' end, s.ld_tier) end,
         coalesce(s.la_evidence, s.ar_evidence, s.lr_evidence), coalesce(s.la_url, s.ar_url, s.lr_url),
         case when s.descr is not null then coalesce(s.la_at, s.ar_decided, s.ar_at) end,
         case when s.descr is null then null when s.la_at is not null then 'machine' when s.has_admission then 'layer4' end,
         s.lr_state, s.lr_rule, s.lr_via, s.lr_tries, s.lr_updated, s.ok_at,
         case when s.admission_state in ('held', 'declined') then coalesce(nullif(s.lr_reason, ''), s.ld_reason, s.lr_rule) end,
         case when s.admission_state in ('held', 'declined') then s.lr_rule end,
         case when s.lr_state in ('queued', 'held') then s.next_try_at end,
         s.l4_status, s.l4_at, s.l4_actor,
         case when s.descr is null then 'none' when s.lifecycle_status = 'active' and s.publication_status = 'published' then 'published' else 'unpublished' end,
         case when p_feeds then s.website_state end, case when p_feeds then s.zoho_state end,
         case when not p_feeds then null
              when s.website_state in ('pending', 'missing') and s.zoho_state in ('pending', 'missing') then 'both'
              when s.website_state in ('pending', 'missing') then 'website'
              when s.zoho_state in ('pending', 'missing') then 'zoho' else 'none' end,
         case when s.ar_checked is not null then s.ar_checked else s.lr_checked end,
         case when (case when s.ar_checked is not null then s.ar_checks else s.lr_checks end ->> 'website_verified') in ('true', 'false')
              then (case when s.ar_checked is not null then s.ar_checks else s.lr_checks end ->> 'website_verified')::boolean end,
         case when (case when s.ar_checked is not null then s.ar_checks else s.lr_checks end ->> 'zoho_verified') in ('true', 'false')
              then (case when s.ar_checked is not null then s.ar_checks else s.lr_checks end ->> 'zoho_verified')::boolean end
    from st s;
end
$$;


ALTER FUNCTION "security"."provider_catalogue_facts_v1"("p_ids" "uuid"[], "p_feeds" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_catalogue_facts_v1"("p_ids" "uuid"[], "p_feeds" boolean) IS 'CF-247 Provider Catalogue columns (directive 9 Nov 2026): per provider, read only and set-based, the description pipeline and its two consumers: populated, admission state (admitted, declined, held, pending, none, unrecorded), source tier (stored, direct, firecrawl, registry_factual, unknown), evidence and source address, when and how it was admitted, the reader''s state, last successful page read, hold reason and next retry, the Layer 4 decision state, the catalogue description''s state, and, separately, the Website feed and Zoho feed states (matched, pending, missing, not applicable) read from pipeline.website_sync_items and pipeline.zoho_sync_items for the providers the existing scans serve, with a mismatch summary. p_ids null = every provider. Presence in catalogue.providers.description is never read as consumer publication.';



CREATE OR REPLACE FUNCTION "security"."provider_contact_append_version"("p_contact_id" "uuid", "p_actor" "uuid", "p_payload" "jsonb", "p_source_class" "text", "p_source_authority" "text", "p_reason" "text", "p_import_batch_id" "uuid" DEFAULT NULL::"uuid", "p_import_row_id" "uuid" DEFAULT NULL::"uuid", "p_evidence_id" "uuid" DEFAULT NULL::"uuid", "p_source_observation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline'
    AS $_$
declare
 v_contact pipeline.provider_contacts%rowtype;v_prev pipeline.provider_contact_versions%rowtype;
 v_version_no int;v_new_id uuid;v_full_name text;v_team_name text;v_job_title text;v_functional_area text;
 v_region_scope text;v_markets text;v_email text;v_phone text;v_location text;v_verification text;v_verified_on date;
 v_source_url text;v_source_page_title text;v_source_notes text;v_hash text;v_identity text;v_payload jsonb;v_domain text;
begin
 select * into v_contact from pipeline.provider_contacts where id=p_contact_id for update;
 if not found then raise exception 'managed contact not found' using errcode='P0002'; end if;
 if v_contact.current_version_id is not null then select * into v_prev from pipeline.provider_contact_versions where id=v_contact.current_version_id; end if;

 v_full_name:=case when p_payload?'full_name' then nullif(btrim(p_payload->>'full_name'),'') else v_prev.full_name end;
 v_team_name:=case when p_payload?'team_name' then nullif(btrim(p_payload->>'team_name'),'') else v_prev.team_name end;
 v_job_title:=case when p_payload?'job_title' then nullif(btrim(p_payload->>'job_title'),'') else v_prev.job_title end;
 v_functional_area:=case when p_payload?'functional_area' then nullif(btrim(p_payload->>'functional_area'),'') else v_prev.functional_area end;
 v_region_scope:=case when p_payload?'region_scope' then nullif(btrim(p_payload->>'region_scope'),'') else v_prev.region_scope end;
 v_markets:=case when p_payload?'countries_or_markets' then nullif(btrim(p_payload->>'countries_or_markets'),'') else v_prev.countries_or_markets end;
 v_email:=case when p_payload?'work_email' then nullif(lower(btrim(p_payload->>'work_email')),'') else v_prev.work_email end;
 v_phone:=case when p_payload?'work_phone' then nullif(btrim(p_payload->>'work_phone'),'') else v_prev.work_phone end;
 v_location:=case when p_payload?'staff_location' then nullif(btrim(p_payload->>'staff_location'),'') else v_prev.staff_location end;
 v_verification:=case when p_payload?'verification_state' then nullif(lower(btrim(p_payload->>'verification_state')),'') else coalesce(v_prev.verification_state,'manual') end;
 v_verified_on:=case when p_payload?'verified_on' and nullif(btrim(p_payload->>'verified_on'),'') is not null then (p_payload->>'verified_on')::date when p_payload?'verified_on' then null else v_prev.verified_on end;
 v_source_url:=case when p_payload?'source_url' then nullif(btrim(p_payload->>'source_url'),'') else v_prev.source_url end;
 v_source_page_title:=case when p_payload?'source_page_title' then nullif(btrim(p_payload->>'source_page_title'),'') else v_prev.source_page_title end;
 v_source_notes:=case when p_payload?'source_notes' then nullif(btrim(p_payload->>'source_notes'),'') else v_prev.source_notes end;

 if v_contact.record_type='named_staff' and v_full_name is null then raise exception 'named staff contact requires full_name' using errcode='22023'; end if;
 if v_contact.record_type='team_contact' and coalesce(v_team_name,v_job_title,v_functional_area,v_email,v_phone,v_source_url) is null then raise exception 'team contact requires team/function/contact/source context' using errcode='22023'; end if;
 if coalesce(v_email,v_phone,v_job_title,v_functional_area,v_region_scope,v_source_url) is null then raise exception 'contact requires meaningful assignment/contact/source context' using errcode='22023'; end if;
 if v_email is not null then
  if v_email !~* '^[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}$' then raise exception 'invalid professional email' using errcode='22023'; end if;
  v_domain:=split_part(v_email,'@',2);
  if v_domain in ('gmail.com','googlemail.com','yahoo.com','yahoo.com.au','hotmail.com','outlook.com','live.com','icloud.com','proton.me','protonmail.com') then
   raise exception 'personal/free-mail address is not permitted for Provider Contacts' using errcode='22023';
  end if;
 end if;
 if v_source_url is not null and v_source_url !~* '^https?://' then raise exception 'source_url must be HTTP(S)' using errcode='22023'; end if;

 v_payload:=jsonb_build_object('full_name',v_full_name,'team_name',v_team_name,'job_title',v_job_title,'functional_area',v_functional_area,
  'region_scope',v_region_scope,'countries_or_markets',v_markets,'work_email',v_email,'work_phone',v_phone,'staff_location',v_location,
  'verification_state',v_verification,'verified_on',case when v_verified_on is null then null else v_verified_on::text end,
  'source_authority',p_source_authority,'source_url',v_source_url);
 v_hash:=security.provider_contact_payload_hash(v_payload);
 select coalesce(max(version_no),0)+1 into v_version_no from pipeline.provider_contact_versions where contact_id=p_contact_id;

 insert into pipeline.provider_contact_versions(contact_id,version_no,full_name,team_name,job_title,functional_area,region_scope,countries_or_markets,
  work_email,work_phone,staff_location,verification_state,verified_on,source_class,source_authority,source_url,source_page_title,source_notes,
  source_observation_id,evidence_id,import_batch_id,import_row_id,content_hash,effective_from,change_reason,created_at,created_by,metadata)
 values(p_contact_id,v_version_no,v_full_name,v_team_name,v_job_title,v_functional_area,v_region_scope,v_markets,v_email,v_phone,v_location,
  v_verification,v_verified_on,p_source_class,p_source_authority,v_source_url,v_source_page_title,v_source_notes,p_source_observation_id,
  p_evidence_id,p_import_batch_id,p_import_row_id,v_hash,now(),p_reason,now(),p_actor,jsonb_build_object('change_control','CF-CHG-20260902-080'))
 returning id into v_new_id;

 if v_contact.current_version_id is not null then update pipeline.provider_contact_versions set effective_to=now(),superseded_by=v_new_id where id=v_contact.current_version_id and effective_to is null; end if;
 v_identity:=security.provider_contact_identity_key(v_contact.record_type,v_full_name,v_job_title,v_region_scope,v_email,v_source_url);
 update pipeline.provider_contacts set current_version_id=v_new_id,identity_key=v_identity,updated_at=now(),updated_by=p_actor where id=p_contact_id;
 return v_new_id;
end $_$;


