CREATE OR REPLACE FUNCTION "security"."provider_description_basic_profile_v1"("p_provider" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- the profile the provider holds now, or null. Off (pdesc.registry_upgrade_on = 0), a text a person changed, a later admission of another tier, a withdrawal or a cleared description all give null.
  select jsonb_build_object('admission_id', a.id, 'read_id', a.read_id, 'text', a.after_description, 'admitted_at', a.created_at, 'evidence_id', a.evidence_id)
    from catalogue.providers p
    join pipeline.provider_description_machine_admissions a on a.provider_id = p.id and a.outcome = 'admitted' and a.withdrawn_at is null and a.tier = 'registry_factual'
   where p.id = p_provider
     and security.pipeline_num_v1('pdesc.registry_upgrade_on', 0) >= 1
     and nullif(btrim(p.description), '') is not null and btrim(p.description) = btrim(a.after_description)
     and exists (select 1 from pipeline.provider_description_reads r where r.id = a.read_id and r.state = 'admitted' and r.rule = 'registry_factual' and r.worker = 'registry-factual-v1')
$$;


ALTER FUNCTION "security"."provider_description_basic_profile_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_basic_profile_v1"("p_provider" "uuid") IS 'CF-247 F-PDESC P0: the register-fact profile (rule registry_factual, worker registry-factual-v1, live machine admission of tier registry_factual) a provider holds now, as {admission_id, read_id, text, admitted_at, evidence_id}, or null. Null when pdesc.registry_upgrade_on is 0, when the current text is not exactly the admitted profile text (a person changed it), or when the admission was withdrawn. One rule for "this description may still be upgraded"; locks, rejections and withdrawals are checked by security.provider_description_machine_blocked_v1.';



CREATE OR REPLACE FUNCTION "security"."provider_description_cohort_cap_v1"() RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- the one cap on a cohort: the screen's limit (capabilities.max_size) and the server's Run Now check are this same number
  select least(security.pipeline_num_v1('pdesc.queue_per_run', 10), security.pipeline_num_v1('pdesc.pending_max', 10), security.pipeline_num_v1('run_now.pilot_cap', 20), security.pipeline_num_v1('pdesc.queue_cap', 60))::int
$$;


ALTER FUNCTION "security"."provider_description_cohort_cap_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_description_consumer_read_v1"("p_consumer" "text", "p_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb; v_error text;
begin
 if p_consumer='website' then v:=public.website_v2_provider(p_key);
 elsif p_consumer='zoho' then v:=public.zoho_v2_provider(p_key);
 else raise exception 'unsupported consumer'; end if;
 return v;
exception when others then
 get stacked diagnostics v_error=message_text;
 return jsonb_build_object('error',jsonb_build_object('code',sqlstate,'message',v_error),'consumer',p_consumer);
end $$;


ALTER FUNCTION "security"."provider_description_consumer_read_v1"("p_consumer" "text", "p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_description_enqueue_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 declare v_n int; v_k int; v_t jsonb; v_cc text; v_share int; v_sel jsonb; v_up int;
begin
 if security.pipeline_num_v1('pdesc.enabled',0)<1 then return 0; end if;
 if security.pipeline_num_v1('pdesc.machine_admit_on',0)>=1 then
  -- automatic mode: each country is its own bounded queue, sized from the providers still to do and the observed rate; each looks at a bounded slice (QA B2)
  v_n:=0; v_t:=security.provider_description_throughput_v1();
  for v_cc,v_share in select e.key,e.value::int from jsonb_each_text(coalesce(v_t->'share','{}'::jsonb)) e order by e.key loop
   v_sel:=security.provider_description_selection_v1(jsonb_build_object('filter','all','size',v_share,'country',v_cc,'prefilter',true,
    'mode',case when security.pipeline_num_v1('pdesc.acquire_direct',0)>=1 then 'approved' else 'stored' end));
   insert into pipeline.provider_description_reads(provider_id)
   select (x->>'provider_id')::uuid from jsonb_array_elements(v_sel->'providers') x
   where (x->>'eligible')::boolean on conflict do nothing;
   get diagnostics v_k=row_count; v_n:=v_n+v_k;
   -- the providers looked at that cannot be read yet, and those returned, go to the back of the rotation
   insert into pipeline.provider_description_scan_marks(provider_id,scanned_at,last_reason)
   select u.pid::uuid,now(),'looked at' from (select jsonb_array_elements_text(coalesce(v_sel->'scanned','[]'::jsonb)) pid union select y->>'provider_id' from jsonb_array_elements(coalesce(v_sel->'providers','[]'::jsonb)) y) u
   on conflict (provider_id) do update set scanned_at=excluded.scanned_at,last_reason=excluded.last_reason;
  end loop;
  -- register-fact profiles with a page to read (pdesc.registry_upgrade_on): after the providers with no description, a bounded number a run
  -- the upgrade lane has its OWN bound: the queued reads of providers that hold a register-fact profile are counted against the lower of pdesc.queue_per_run and pdesc.queue_cap, and the lane tops them up to that bound each run, however many reads of providers with no description wait (they used to switch the lane off, so an upgrade was never queued)
  v_up:=case when security.pipeline_num_v1('pdesc.registry_upgrade_on',0)>=1 then (select count(*) from pipeline.provider_description_reads q where q.state='queued' and security.provider_description_basic_profile_v1(q.provider_id) is not null) end;
  if v_up is not null and v_up<least(security.pipeline_num_v1('pdesc.queue_per_run',10),security.pipeline_num_v1('pdesc.queue_cap',60)) then
   v_sel:=security.provider_description_selection_v1(jsonb_build_object('filter','all','size',least(security.pipeline_num_v1('pdesc.queue_per_run',10),security.pipeline_num_v1('pdesc.queue_cap',60))::int-v_up,'prefilter',true,'upgrade',true,
    'mode',case when security.pipeline_num_v1('pdesc.acquire_direct',0)>=1 then 'approved' else 'stored' end));
   insert into pipeline.provider_description_reads(provider_id)
   select (x->>'provider_id')::uuid from jsonb_array_elements(v_sel->'providers') x
   where (x->>'eligible')::boolean on conflict do nothing;
   get diagnostics v_k=row_count; v_n:=v_n+v_k;
   insert into pipeline.provider_description_scan_marks(provider_id,scanned_at,last_reason)
   select u.pid::uuid,now(),'looked at' from (select jsonb_array_elements_text(coalesce(v_sel->'scanned','[]'::jsonb)) pid union select y->>'provider_id' from jsonb_array_elements(coalesce(v_sel->'providers','[]'::jsonb)) y) u
   on conflict (provider_id) do update set scanned_at=excluded.scanned_at,last_reason=excluded.last_reason;
  end if;
  return v_n;
 end if;
 insert into pipeline.provider_description_reads(provider_id)
 select (x->>'provider_id')::uuid from jsonb_array_elements(security.provider_description_selection_v1(jsonb_build_object('filter','all','size',least(security.pipeline_num_v1('pdesc.queue_per_run',10),security.pipeline_num_v1('pdesc.pending_max',10),security.pipeline_num_v1('run_now.pilot_cap',20))::int,
 'mode',case when security.pipeline_num_v1('pdesc.acquire_direct',0)>=1 then 'approved' else 'stored' end))->'providers') x
 where (x->>'eligible')::boolean on conflict do nothing;
 get diagnostics v_n=row_count; return v_n;
end $$;


ALTER FUNCTION "security"."provider_description_enqueue_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_enqueue_v1"() IS 'CF-247 P1 provider descriptions: queues at most pdesc.queue_per_run providers in scope with no description, or whose description this reader admitted and last verified more than pdesc.recheck_days ago. A description entered elsewhere is never re-read; a value locked by hand is never queued; held and rejected reads wait pdesc.recheck_days; dead letters wait for a person.';



CREATE OR REPLACE FUNCTION "security"."provider_description_fill_status_v1"("p_ids" "uuid"[], "p_feeds" boolean, "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  return (
    with q as (select * from security.provider_description_quality_v1(p_ids, p_feeds)),
    lr as (
      select distinct on (r.provider_id) r.provider_id, r.id read_id, r.state, r.rule, r.reason, r.tries, r.updated_at, r.next_try_at, r.review_item_id, r.evidence_id, r.source_url, r.read_via, r.ai_calls, r.model, r.content_hash, r.source_captured_at
        from pipeline.provider_description_reads r where r.provider_id = any(p_ids) order by r.provider_id, r.created_at desc, r.id desc
    ), lt as (
      select distinct on (m.provider_id) m.provider_id, c.id cohort_id, c.state cohort_state, c.run_id, c.created_at, c.reason, (c.requested_by = p_actor) mine, c.selection->>'fill_mode' fill_mode,
             j.state run_state, j.outcome run_outcome, j.finished_at run_finished_at
        from pipeline.provider_description_cohort_members m
        join pipeline.provider_description_cohorts c on c.id = m.cohort_id
        left join pipeline.admin_jobs j on j.id = c.run_id
       where m.provider_id = any(p_ids) order by m.provider_id, c.created_at desc, c.id desc
    ), mc as (
      -- the latest machine decision of each provider (migration 20261110210000): admitted, or declined with the reason and what the sentence-subset recovery found
      select distinct on (a.provider_id) a.provider_id, a.outcome, a.tier, a.reason, a.created_at, a.review_item_id, a.checks
        from pipeline.provider_description_machine_admissions a where a.provider_id = any(p_ids) and a.withdrawn_at is null order by a.provider_id, a.created_at desc, a.id desc
    )
    select jsonb_build_object('as_at', now(), 'feeds', p_feeds, 'providers', coalesce(jsonb_agg(jsonb_build_object(
      'provider_id', p.id, 'name', coalesce(p.display_name, p.canonical_name), 'stable_key', p.stable_key, 'country', k.iso_alpha2::text, 'type', pt.code,
      'lifecycle_status', p.lifecycle_status, 'publication_status', p.publication_status,
      'description_present', q.description_filled, 'current_description', p.description, 'quality_class', q.quality_class,
      'source_tier', q.source_tier, 'admission_state', q.admission_state, 'admitted_at', q.admitted_at, 'admitted_by', q.admitted_by, 'evidence_id', coalesce(q.evidence_id, lr.evidence_id), 'source_url', coalesce(q.source_url, lr.source_url),
      'reader', jsonb_build_object('read_id', lr.read_id, 'state', lr.state, 'rule', lr.rule, 'reason', lr.reason, 'tries', lr.tries, 'updated_at', lr.updated_at, 'read_via', lr.read_via, 'ai_calls', lr.ai_calls, 'model', lr.model, 'source_captured_at', lr.source_captured_at, 'content_hash', lr.content_hash),
      'hold_reason', coalesce(q.hold_reason, case when lr.state in ('held', 'rejected', 'dead_letter') then coalesce(nullif(lr.reason, ''), lr.rule) end), 'next_retry_at', coalesce(q.next_retry_at, case when lr.state in ('queued', 'held') then lr.next_try_at end),
      'last_read_ok_at', q.last_read_ok_at, 'l4_status', q.l4_status, 'review_item_id', lr.review_item_id,
      'website_state', q.website_state, 'zoho_state', q.zoho_state, 'website_publication', q.website_publication, 'zoho_publication', q.zoho_publication, 'readback_at', q.readback_at,
      'missing_fields', to_jsonb(q.missing_fields),
      'locked', exists (select 1 from pipeline.manual_locks l where l.entity = 'provider' and l.entity_id = p.id and l.field in ('description', 'p_description', 'all')),
      'machine', case when mc.provider_id is null then null else jsonb_build_object('outcome', mc.outcome, 'tier', mc.tier, 'reason', mc.reason, 'at', mc.created_at, 'review_item_id', mc.review_item_id,
        'current_reading', mc.review_item_id is not distinct from lr.review_item_id,
        'subset', case when mc.checks ? 'subset_of_reading' then jsonb_build_object('kept_sentences', mc.checks->'subset_of_reading'->'kept_sentences', 'given_sentences', mc.checks->'subset_of_reading'->'given_sentences',
          'dropped', (select coalesce(jsonb_agg(d - 'quote'), '[]'::jsonb) from jsonb_array_elements(mc.checks->'subset_of_reading'->'dropped') d)) end,
        'subset_result', mc.checks->'subset_recovery'->>'result') end,
      'latest_task', case when lt.cohort_id is null then null else jsonb_build_object('cohort_id', lt.cohort_id, 'state', lt.cohort_state, 'run_id', lt.run_id, 'created_at', lt.created_at, 'reason', lt.reason,
        'requested_by_me', lt.mine, 'fill_mode', lt.fill_mode, 'run_state', lt.run_state, 'run_outcome', lt.run_outcome, 'run_finished_at', lt.run_finished_at) end
    ) order by coalesce(p.display_name, p.canonical_name)), '[]'::jsonb))
    from q join catalogue.providers p on p.id = q.provider_id join ref.countries k on k.id = p.country_id left join ref.provider_types pt on pt.id = p.provider_type_id
    left join lr on lr.provider_id = p.id left join lt on lt.provider_id = p.id left join mc on mc.provider_id = p.id
  );
end
$$;


ALTER FUNCTION "security"."provider_description_fill_status_v1"("p_ids" "uuid"[], "p_feeds" boolean, "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_description_fire_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_q int := 0; v_due int; v_open int; v_last timestamptz; v_pending int; v_dead int; v_cohort uuid; v_resumed int; v_sent int; v_i int;
begin
  if not pg_try_advisory_xact_lock(hashtext('cf247 provider description fire')) then return jsonb_build_object('sent',0,'reason','reader_dispatch_in_flight'); end if; -- fixed: serialize the existing job dispatch, never wait or duplicate a nonce.
  if security.pipeline_num_v1('pdesc.enabled', 0) < 1 then return jsonb_build_object('enabled', false); end if;
  -- Publication and parked proposal progress do not require another paid read. Manual Run Now never adds work outside its fixed cohort.
  if nullif(current_setting('cf.pdesc_run_now',true),'') is null then
  perform security.provider_description_publication_check_v1();
  perform security.provider_description_settle_abandoned_v1(); -- reservations that nothing is working on are settled first (an abandoned paid call is counted, never assumed free); a settled read with the held rule below goes back to the queue
  update pipeline.provider_description_reads set state='queued',tries=greatest(0,tries-1),next_try_at=now()+make_interval(mins=>security.pipeline_num_v1('pdesc.retry_minutes',360)::int),leased_until=null,updated_at=now()
  where state='held' and rule in ('source_identity_proof_missing','ai_ceiling','ai_daily_guard','ai_refused','model_pricing_unavailable','invalid_model_pricing','unrecognised_pricing_component','ai_budget_refused','existing_cost_reservation_uncertain') and reserved_usd=0;

  update pipeline.provider_description_reads r set state='held',rule='selection_changed_before_lease',reason='Provider scope, identity, manual lock or pinned source changed; inspect saved evidence before preparing another cohort',updated_at=now()
  where r.state='queued' and exists(select 1 from pipeline.provider_description_cohort_members m join pipeline.provider_description_cohorts c on c.id=m.cohort_id where m.read_id=r.id and c.state='started')
  and (not security.provider_description_scope_v1(r.provider_id)
    or exists(select 1 from pipeline.provider_description_cohort_members m join catalogue.providers p on p.id=m.provider_id where m.read_id=r.id and p.description is distinct from m.snapshot->>'current_description')
    or exists(select 1 from catalogue.providers p where p.id=r.provider_id and not (security.provider_description_identity_v1(r.provider_id,coalesce((select m.snapshot->>'source_url' from pipeline.provider_description_cohort_members m where m.read_id=r.id order by m.pick limit 1),p.website))->>'ok')::boolean)
    or exists(select 1 from pipeline.manual_locks l where l.entity='provider' and l.entity_id=r.provider_id and l.field in ('description','p_description','all'))
    or exists(select 1 from pipeline.provider_description_cohort_members m where m.read_id=r.id and m.evidence_id is not null and not exists(select 1 from pipeline.evidence_artifacts a where a.id=m.evidence_id and coalesce(a.content_hash,a.id::text)=m.snapshot->>'source_hash' and coalesce(a.captured_at,a.created_at)>now()-make_interval(days=>security.pipeline_num_v1('pdesc.source_max_age_days',365)::int) and (security.provider_description_identity_v1(r.provider_id,a.source_url)->>'ok')::boolean)));
  v_resumed:=security.provider_description_resume_v1();
  v_q := security.provider_description_enqueue_v1();
  if security.pipeline_num_v1('pdesc.machine_admit_on',0)>=1 then perform security.provider_description_machine_step_v1(); end if;
  else v_q:=0; v_resumed:=0; end if;
  select count(*) into v_dead from pipeline.provider_description_reads r where r.state = 'dead_letter';
  if not security.ai_use_allowed_v1(case when security.pdesc_on_demand_due_v1() then 'provider_description_on_demand' else 'provider_description' end) then return jsonb_build_object('queued', v_q, 'ai', 'stopped', 'dead_letter', v_dead); end if; /* 20261112010000 */
  if (select coalesce(sum(l.cost_usd), 0) from pipeline.ai_spend_ledger l where l.lane = 'provider_description' and l.source <> 'opening') >= security.pipeline_num_v1('pdesc.ai_usd_max', 1) and not security.pdesc_on_demand_due_v1() then /* 20261112010000 */
    return jsonb_build_object('queued', v_q, 'ai', 'ceiling', 'dead_letter', v_dead);
  end if;
  select count(*) into v_pending from pipeline.layer4_review_items i where i.field_code = 'provider_description' and i.status = 'pending';
  if v_pending >= security.pipeline_num_v1('pdesc.pending_max', 10) and security.pipeline_num_v1('pdesc.machine_admit_on',0)<1 then return jsonb_build_object('queued', v_q, 'review', 'full', 'pending', v_pending); end if;
  select count(*) into v_due from pipeline.provider_description_reads r
   where ((r.state = 'queued' and r.next_try_at <= now()) or (r.state = 'reading' and r.leased_until < now())) and r.tries < security.pipeline_num_v1('pdesc.tries', 3)
     and (nullif(current_setting('cf.pdesc_run_now',true),'') is null or exists(select 1 from pipeline.provider_description_cohort_members m where m.cohort_id=nullif(current_setting('cf.pdesc_run_now',true),'')::uuid and m.read_id=r.id));
  select max(l.created_at) into v_last from pipeline.edge_request_log l where l.function_name = 'coverage-sweep' and l.mode = 'provider_description'
     and l.created_at > now() - make_interval(mins => security.pipeline_num_v1('pdesc.every_minutes', 60)::int) + interval '30 seconds'; -- fixed: fire jitter, so a fire exactly one window after the last dispatch is not blocked by the milliseconds that dispatch started after its minute
  select count(*) into v_open from pipeline.edge_request_log l where l.function_name = 'coverage-sweep' and l.mode = 'provider_description' and l.created_at > now() - interval '4 minutes'  -- fixed: fire guard
     and not exists (select 1 from net._http_response h where h.id = l.request_id);
  if nullif(current_setting('cf.pdesc_run_now',true),'') is not null then v_last:=null; end if; -- Run Now bypasses frequency only; all other job guards remain.
  if v_due > 0 and v_open = 0 and v_last is null then
    if nullif(current_setting('cf.pdesc_run_now',true),'') is not null then v_cohort:=nullif(current_setting('cf.pdesc_run_now',true),'')::uuid;
    else
    select c.id into v_cohort from pipeline.provider_description_cohorts c
    where c.state='started' and exists(select 1 from pipeline.provider_description_cohort_members m join pipeline.provider_description_reads r on r.id=m.read_id where m.cohort_id=c.id and ((r.state='queued' and r.next_try_at<=now()) or (r.state='reading' and r.leased_until<now())))
    order by c.prepared_at,c.id limit 1;
    end if;
    -- automatic mode: as many worker calls as the due reads need, up to pdesc.dispatch_max (each lease is bounded by the concurrency and spend limits); otherwise one call, as before
    v_sent := case when security.pipeline_num_v1('pdesc.machine_admit_on',0)>=1 and v_cohort is null then least(security.pipeline_num_v1('pdesc.dispatch_max',3)::int, greatest(1, ceil(v_due::numeric / greatest(1, security.pipeline_num_v1('batch.provider_description', 3)))::int)) else 1 end;
    for v_i in 1 .. v_sent loop
      perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'provider_description', 'limit', security.pipeline_num_v1('batch.provider_description', 3)::int,'cohort_id',v_cohort));
    end loop;
    return jsonb_build_object('queued', v_q, 'due', v_due, 'sent', v_sent, 'dead_letter', v_dead);
  end if;
  return jsonb_build_object('queued', v_q, 'due', v_due, 'sent', 0, 'dead_letter', v_dead);
end $$;


ALTER FUNCTION "security"."provider_description_fire_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_fire_v1"() IS 'CF-247 P1 provider descriptions: job provider-description-read. While pdesc.enabled is 1: queues providers (bounded), and at most once every pdesc.every_minutes sends the worker batch.provider_description providers, inside the AI daily guard (guard_provider_description) and while fewer than pdesc.pending_max proposals wait in Layer 4.';



CREATE OR REPLACE FUNCTION "security"."provider_description_identity_snapshot_v1"("p_provider" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select jsonb_strip_nulls(jsonb_build_object('canonical_name',p.canonical_name,'display_name',p.display_name,'provider_type_id',p.provider_type_id,'country_id',p.country_id,'website',p.website))
 from catalogue.providers p where p.id=p_provider
$$;


ALTER FUNCTION "security"."provider_description_identity_snapshot_v1"("p_provider" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_description_identity_v1"("p_provider" "uuid", "p_url" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare p catalogue.providers%rowtype; v_finding text; v_other uuid;
begin
  select * into p from catalogue.providers where id = p_provider;
  if p.id is null or p.lifecycle_status <> 'active' or p.publication_status <> 'published'
     or exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p_provider)
     or security.provider_lifecycle_held_v1(p_provider) then
    return jsonb_build_object('ok', false, 'rule', 'provider_inactive', 'reason', 'The provider is not active and published, or its lifecycle is held.');
  end if;
  select f.check_code into v_finding from pipeline.provider_identity_findings f
   where f.provider_id = p_provider and f.state = 'open'
   order by f.check_code limit 1;
  if v_finding is not null then
    return jsonb_build_object('ok', false, 'rule', 'identity_' || v_finding,
      'reason', 'An existing provider identity finding requires resolution: ' || v_finding);
  end if;
  if security.provider_page_host_v1(p_provider, p_url) <> 'own' then
    return jsonb_build_object('ok', false, 'rule', 'wrong_host', 'reason', 'The source is not on an approved provider host.');
  end if;
  -- Even an own host is ambiguous when it is another current provider's primary host.
  -- Never infer that a university and similarly named college are interchangeable.
  select o.id into v_other from catalogue.providers o
   where o.id <> p_provider and o.lifecycle_status = 'active'
     and security.site_host_v1(o.website) = security.site_host_v1(p_url)
     and security.site_host_v1(p_url) is not null
   order by o.id limit 1;
  if v_other is not null then
    return jsonb_build_object('ok', false, 'rule', 'provider_host_conflict', 'conflicting_provider_id', v_other,
      'reason', 'Another active provider holds the source host; exact provider identity requires resolution.');
  end if;
  return jsonb_build_object('ok', true, 'rule', 'identity_clear');
end $$;


ALTER FUNCTION "security"."provider_description_identity_v1"("p_provider" "uuid", "p_url" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_identity_v1"("p_provider" "uuid", "p_url" "text") IS 'Provider descriptions: existing active/published, hidden and lifecycle controls; unresolved identity findings and another current provider primary host refuse extraction and admission. No identity or eligibility authority is granted.';



CREATE OR REPLACE FUNCTION "security"."provider_description_learning_trg_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_sig text; v_human boolean;
begin
 if new.rule in ('review_full','recovery_knowledge_unchanged_failure','source_identity_proof_missing','ai_ceiling','ai_daily_guard','ai_refused','model_pricing_unavailable','invalid_model_pricing','unrecognised_pricing_component','ai_budget_refused','existing_cost_reservation_uncertain') or new.state is not distinct from old.state or new.content_hash is null or new.state not in ('proposed','held','rejected','admitted','verified') then return new; end if;
 v_sig:=security.provider_description_signature_v1(new.content_hash,new.model,new.prompt_version);
 v_human:=new.state='admitted';
 perform security.ops_learning_record_v1(jsonb_build_object('code',case when v_human then 'provider_description:human_admission' else 'provider_description:official_about' end,
 'entity',new.provider_id::text,'evidence_signature',v_sig,'performed_by',case when v_human then 'layer4_human' else 'platform' end,
 'success',new.state in ('proposed','admitted','verified'),'stage_advanced',new.state in ('proposed','admitted','verified'),
 'cost_usd',case when v_human then 0 else new.cost_usd end,'expected',case when v_human then 'Authorised exact description admitted; consumer verification separate' else 'Official evidence-backed description proposal' end,
 'observed',jsonb_build_object('read_id',new.id,'state',new.state,'rule',new.rule,'review_item_id',new.review_item_id,'admitted',new.state='admitted','website_published',new.published_at is not null),
 'evidence',jsonb_build_object('evidence_id',new.evidence_id,'content_hash',new.content_hash,'model',new.model,'prompt_version',new.prompt_version,'reason',new.reason)));
 return new;
end $$;


ALTER FUNCTION "security"."provider_description_learning_trg_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_description_machine_admit_v1"("p_item_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.layer4_review_items%rowtype; v_read pipeline.provider_description_reads%rowtype; v_tier text; v_text text; v_gate jsonb; v_check jsonb; v_prof jsonb; v_now text; v_pub jsonb; v_shown text; v_key text;
        v_sys uuid := 'c0ffee00-0000-4000-8000-000000000150'; -- fixed: the system automation account that records Decision 263 rule decisions
        v_rule constant text := 'pdesc-machine-v1'; v_ref text := 'CF-247 F-PDESC; Platform Admin decision 9 Nov 2026 (source-verified machine admission, tiers 1 to 4)'; v_dec uuid; v_facts jsonb := '[]'::jsonb; v_codes jsonb := '[]'::jsonb;
        v_url text; v_hash text; v_reason text; v_decline text; v_basic jsonb; v_upg boolean := false;
        v_sent jsonb; v_sub jsonb; v_subinfo jsonb; v_try jsonb; v_gate2 jsonb; v_text0 text; -- sentence-subset recovery
begin
  if security.pipeline_num_v1('pdesc.machine_admit_on', 0) < 1 then return jsonb_build_object('ok', false, 'rule', 'machine_admission_off'); end if;
  select * into i from pipeline.layer4_review_items where id = p_item_id for update;
  if i.id is null or i.entity_type <> 'provider' or i.field_code <> 'provider_description' or i.status <> 'pending' then return jsonb_build_object('ok', false, 'rule', 'not_a_waiting_provider_description'); end if;
  select * into v_read from pipeline.provider_description_reads r where r.review_item_id = i.id and r.state = 'proposed' for update;
  v_text := nullif(btrim(i.proposed_value->>'description'), '');
  v_sent := coalesce(i.proposed_value->'sentences', '[]'::jsonb); -- the sentences the description is made of (the proposal itself is never changed)
  v_tier := coalesce(nullif(v_read.checks->>'tier', ''), v_read.read_via, i.proposed_value->>'tier');
  v_decline := null;
  -- upgrade of a register-fact profile (pdesc.registry_upgrade_on): the item's before text is the profile the provider holds now and the proposal comes from a source tier
  v_basic := security.provider_description_basic_profile_v1(i.entity_id);
  v_upg := v_basic is not null and v_tier in ('stored', 'direct', 'firecrawl') and btrim(coalesce(i.before_value->>'description', '')) = btrim(v_basic->>'text');
  if v_read.id is null then v_decline := 'no_proposed_read';
  elsif v_tier not in ('stored', 'direct', 'firecrawl', 'registry_factual') then v_decline := 'unknown_tier';
  end if;
  if v_decline is null then
    if v_tier = 'registry_factual' then
      -- rebuilt from the verified record now: the text, the register evidence and the facts must be exactly what was proposed
      v_prof := security.provider_description_registry_profile_v1(i.entity_id);
      if not coalesce((v_prof->>'ok')::boolean, false) then v_decline := 'profile_' || coalesce(v_prof->>'rule', 'not_ok');
      elsif v_prof->>'text' is distinct from v_text or (v_prof->>'evidence_id')::uuid is distinct from i.evidence_id then v_decline := 'profile_changed_since_proposed';
      elsif not exists (select 1 from catalogue.provider_registrations rr where rr.id = (v_prof->>'registration_id')::uuid and rr.provider_id = i.entity_id and rr.status = 'active' and rr.evidence_id = i.evidence_id) then v_decline := 'register_listing_changed';
      end if;
      v_facts := coalesce(v_prof->'facts', '[]'::jsonb); v_codes := coalesce(v_prof->'codes', '[]'::jsonb); v_url := v_prof->>'source_url'; v_hash := v_prof->>'source_hash';
    else
      -- the same lineage, identity and quote checks the human path makes, proved again now
      if v_read.evidence_id is distinct from i.evidence_id or not exists (select 1 from pipeline.evidence_artifacts a join pipeline.sources s on s.id = a.source_id
           where a.id = i.evidence_id and s.provider_id = i.entity_id and a.source_url = v_read.source_url and coalesce(a.content_hash, a.id::text) = v_read.content_hash) then v_decline := 'evidence_lineage_changed';
      elsif not (security.provider_description_identity_v1(i.entity_id, v_read.source_url)->>'ok')::boolean then v_decline := 'identity_' || coalesce(security.provider_description_identity_v1(i.entity_id, v_read.source_url)->>'rule', 'not_clear');
      elsif v_read.checks->'identity_snapshot' is not null and v_read.checks->'identity_snapshot' is distinct from security.provider_description_identity_snapshot_v1(i.entity_id) then v_decline := 'identity_changed_since_read';
      elsif v_read.checks->'identity_snapshot' is null and not exists (select 1 from catalogue.providers p cross join lateral jsonb_array_elements(coalesce(i.proposed_value->'sentences', '[]'::jsonb)) sentence
           where p.id = i.entity_id and exists (select 1 from unnest(array[p.canonical_name, p.display_name]) nm where nullif(btrim(nm), '') is not null
             and position(regexp_replace(lower(nm), '[^a-z0-9]+', '', 'g') in regexp_replace(lower(sentence->>'quote'), '[^a-z0-9]+', '', 'g')) > 0)) then v_decline := 'legacy_proposal_name_not_in_quote';
      else
        v_check := security.provider_description_validate_v1(i.entity_id, v_read.source_url, v_read.source_captured_at, jsonb_build_object('about_page', true, 'sentences', i.proposed_value->'sentences'));
        if v_check->>'outcome' not in ('propose', 'verified') or v_check->>'text' is distinct from v_text then v_decline := 'validation_' || coalesce(v_check->>'rule', 'changed'); end if;
      end if;
      v_url := v_read.source_url; v_hash := v_read.content_hash;
      v_facts := coalesce((select jsonb_agg(jsonb_build_object('sentence', s->>'text', 'quote', s->>'quote', 'source_url', v_read.source_url, 'source_hash', v_read.content_hash, 'evidence_id', v_read.evidence_id,
                    'captured_at', v_read.source_captured_at, 'model', v_read.model, 'prompt_version', v_read.prompt_version, 'worker', v_read.worker)) from jsonb_array_elements(coalesce(i.proposed_value->'sentences', '[]'::jsonb)) s), '[]'::jsonb);
    end if;
  end if;
  if v_decline is null then
    v_gate := security.provider_description_machine_gate_v1(i.entity_id, v_text, jsonb_build_object('tier', v_tier, 'codes', v_codes, 'sentences', case when v_tier = 'registry_factual' then '[]'::jsonb else coalesce(i.proposed_value->'sentences', '[]'::jsonb) end));
    if not (v_gate->>'ok')::boolean then v_decline := v_gate->>'rule'; v_reason := v_gate->>'reason'; end if;
  end if;
  -- Sentence-subset recovery (CF-247 F-PDESC, Platform Admin 10 Nov 2026): a reading from an official page that the text rule declined (a word or a figure, or page markup) is not parked for a person when the refusal sits in only some of its sentences.
  -- Exactly those sentences are left out (never reworded, never added to), and the SAME validation (host, About page, sentence range, character range, quote on the page for every sentence, age, duplicate guard), the SAME machine gate (lock, rejection memory,
  -- withdrawal, identity finding, name, full text check) and, for a reading without an identity snapshot, the name in a quote, are run again on what is left. The identity, host, evidence and snapshot proofs above do not depend on the sentences.
  -- If anything fails the reading stays declined exactly as before, and the ledger row says what was tried. The decision row, the ledger row and the item's layer2_state keep the original proposal (every sentence, the sentences left out and why); once admitted, the read's proposal and the item's proposed_value hold the kept description the catalogue holds, so the read-back lineage finds it.
  if v_decline in ('machine_text_refused_word', 'machine_text_figure', 'machine_text_entity_encoded') and v_tier in ('stored', 'direct', 'firecrawl') then -- fixed: the three refusals of the text rule that leaving a sentence out can remove
    v_sub := security.provider_description_subset_v1(i.entity_id, v_sent);
    v_try := jsonb_build_object('refusal', v_decline, 'reason', v_reason, 'dropped', coalesce(v_sub->'dropped', '[]'::jsonb), 'kept_sentences', jsonb_array_length(coalesce(v_sub->'kept', '[]'::jsonb)), 'given_sentences', jsonb_array_length(v_sent), 'at', now());
    if jsonb_array_length(coalesce(v_sub->'kept', '[]'::jsonb)) = 0 then v_try := v_try || jsonb_build_object('result', 'every_sentence_refused');
    elsif jsonb_array_length(coalesce(v_sub->'dropped', '[]'::jsonb)) = 0 then v_try := v_try || jsonb_build_object('result', 'no_sentence_to_leave_out');
    elsif v_read.checks->'identity_snapshot' is null and not exists (select 1 from catalogue.providers p cross join lateral jsonb_array_elements(v_sub->'kept') sentence
           where p.id = i.entity_id and exists (select 1 from unnest(array[p.canonical_name, p.display_name]) nm where nullif(btrim(nm), '') is not null
             and position(regexp_replace(lower(nm), '[^a-z0-9]+', '', 'g') in regexp_replace(lower(sentence->>'quote'), '[^a-z0-9]+', '', 'g')) > 0)) then
      v_try := v_try || jsonb_build_object('result', 'name_not_in_remaining_quotes');
    else
      v_check := security.provider_description_validate_v1(i.entity_id, v_read.source_url, v_read.source_captured_at, jsonb_build_object('about_page', true, 'sentences', v_sub->'kept'));
      if coalesce(v_check->>'outcome', '') not in ('propose', 'verified') or nullif(v_check->>'text', '') is null then
        v_try := v_try || jsonb_build_object('result', 'remainder_validation_' || coalesce(v_check->>'rule', 'changed'), 'remainder_reason', v_check->>'reason');
      else
        v_gate2 := security.provider_description_machine_gate_v1(i.entity_id, v_check->>'text', jsonb_build_object('tier', v_tier, 'codes', v_codes, 'sentences', v_sub->'kept'));
        if not coalesce((v_gate2->>'ok')::boolean, false) then
          v_try := v_try || jsonb_build_object('result', 'remainder_' || coalesce(v_gate2->>'rule', 'not_ok'), 'remainder_reason', v_gate2->>'reason');
        else
          v_text0 := v_text;
          v_subinfo := jsonb_build_object('refusal', v_decline, 'refusal_reason', v_reason, 'dropped', v_sub->'dropped', 'kept_sentences', jsonb_array_length(v_sub->'kept'), 'given_sentences', jsonb_array_length(v_sent),
                         'original_text_chars', length(v_text0), 'original_text_md5', md5(v_text0), 'original_text', v_text0, 'original_sentences', v_sent, 'original_read_id', v_read.id, 'original_evidence_id', i.evidence_id, 'source_url', v_read.source_url, 'source_hash', v_read.content_hash, 'review_item_id', i.id);
          v_sent := v_sub->'kept'; v_text := v_check->>'text'; v_gate := v_gate2; v_decline := null; v_reason := null;
          v_facts := coalesce((select jsonb_agg(jsonb_build_object('sentence', s->>'text', 'quote', s->>'quote', 'source_url', v_read.source_url, 'source_hash', v_read.content_hash, 'evidence_id', v_read.evidence_id,
                    'captured_at', v_read.source_captured_at, 'model', v_read.model, 'prompt_version', v_read.prompt_version, 'worker', v_read.worker)) from jsonb_array_elements(v_sent) s), '[]'::jsonb);
          v_try := v_try || jsonb_build_object('result', 'adopted');
        end if;
      end if;
    end if;
  end if;
  if v_decline is null and v_upg and (jsonb_array_length(v_sent) < security.pipeline_num_v1('pdesc.min_sentences', 2) or v_text = btrim(v_basic->>'text')) then v_decline := 'upgrade_too_short_or_unchanged'; end if;
  if v_decline is null and not v_upg and i.before_value->>'description' is not null and nullif(btrim(i.before_value->>'description'), '') is not null then v_decline := 'before_value_not_empty'; end if;
  if v_decline is null then
    select nullif(btrim(p.description), '') into v_now from catalogue.providers p where p.id = i.entity_id for update;
    if v_now is not null and not (v_upg and v_now = btrim(v_basic->>'text')) then v_decline := 'description_already_held'; end if;
  end if;
  if v_decline is not null then
    v_reason := coalesce(v_reason, 'The automatic rule did not admit this description (' || v_decline || '); a person decides in Layer 4.');
    insert into pipeline.provider_description_machine_admissions (provider_id, review_item_id, read_id, tier, rule, outcome, reason, evidence_id, source_url, source_hash, facts, checks, actor)
    values (i.entity_id, i.id, v_read.id, case when v_tier in ('stored', 'direct', 'firecrawl', 'registry_factual') then v_tier else 'stored' end, v_rule, 'declined', v_reason, i.evidence_id, v_read.source_url, v_read.content_hash, v_facts,
            case when v_try is not null then jsonb_build_object('subset_recovery', v_try) else '{}'::jsonb end, v_sys)
    on conflict (review_item_id) where outcome = 'declined' do update set reason = excluded.reason, tier = excluded.tier, facts = excluded.facts, created_at = now(),
            checks = (coalesce(pipeline.provider_description_machine_admissions.checks, '{}'::jsonb) - 'subset_recovery') || excluded.checks;
    update pipeline.layer4_review_items set escalation_reason = left('Machine rule ' || v_rule || ' did not admit this: ' || v_decline || '. ' || regexp_replace(coalesce(escalation_reason, ''), '^Machine rule [^.]*\. ', ''), 1000) -- fixed: the item's reason column shows its first 1000 characters
     where id = i.id and coalesce(escalation_reason, '') not like 'Machine rule ' || v_rule || ' did not admit this: ' || v_decline || '.%';
    return jsonb_build_object('ok', false, 'rule', v_decline, 'reason', v_reason);
  end if;
  -- write the one description, settle the item as a machine decision, record everything
  update catalogue.providers set description = v_text, updated_at = now() where id = i.entity_id;
  -- proved on the row: a guard that put the old text back must stop the admission, not leave an audit that says it was published
  if (select nullif(btrim(p.description), '') from catalogue.providers p where p.id = i.entity_id) is distinct from v_text then raise exception 'description_not_written: the catalogue kept the earlier text'; end if;
  -- a recovered reading: the item and the read hold the description the catalogue now holds (the kept sentences), so the approved-lineage test of the Website and Zoho read-back, the run result and the selection find it; the original proposal (every sentence, the sentences left out and why) stays in the decision row (proposed_value), the ledger row and layer2_state.subset_of_reading
  update pipeline.layer4_review_items set status = 'approved', decided_at = now(),
         proposed_value = case when v_subinfo is not null then proposed_value || jsonb_build_object('description', v_text, 'sentences', v_sent) else proposed_value end,
         layer2_state = case when v_subinfo is not null then coalesce(layer2_state, '{}'::jsonb) || jsonb_build_object('subset_of_reading', v_subinfo) else layer2_state end
   where id = i.id and status = 'pending';
  v_reason := format('Auto (%s, tier %s): %s. Not a person''s decision.', v_rule, v_tier,
                     case when v_tier = 'registry_factual' then 'built only from the verified register listing, provider record and active catalogue courses; every sentence tied to its facts'
                          else 'official page ' || coalesce(v_url, '') || ' (hash ' || left(coalesce(v_hash, ''), 12) || '); identity, evidence lineage and every sentence''s quote proved again at admission' end); -- fixed: a short hash prefix is shown for reading, the full hash is stored
  if v_subinfo is not null then
    v_reason := v_reason || format(' Sentence subset of the reading: %s of %s sentences kept, %s left out because the automatic text rule refused them; nothing was reworded or added.', v_subinfo->>'kept_sentences', v_subinfo->>'given_sentences', jsonb_array_length(v_subinfo->'dropped'));
  end if;
  insert into pipeline.layer4_decisions (review_item_id, action, actor_id, reason, before_value, proposed_value, final_value, evidence_id, layer2_state, layer3_state, change_control_ref)
  values (i.id, 'approve', v_sys, v_reason, i.before_value, i.proposed_value,
          case when v_subinfo is not null then i.proposed_value || jsonb_build_object('description', v_text, 'sentences', v_sent, 'subset_of_reading', v_subinfo) else i.proposed_value end, i.evidence_id,
          coalesce(i.layer2_state, '{}'::jsonb) || jsonb_build_object('machine_rule', v_rule, 'tier', v_tier, 'actor_kind', 'machine') || case when v_subinfo is not null then jsonb_build_object('subset_of_reading', true) else '{}'::jsonb end, coalesce(i.layer3_state, '{}'::jsonb), v_ref) returning id into v_dec;
  insert into pipeline.admin_control_events (area, action, target, detail, actor)
  values ('layer4', 'inbox_decide', i.id::text, jsonb_build_object('kind', 'provider_description', 'ref', i.id::text, 'choice', 'approve', 'reason', v_reason, 'provider_id', i.entity_id, 'auto', true,
          'machine_rule', v_rule, 'tier', v_tier, 'decision_id', v_dec, 'field_code', i.field_code, 'subset_of_reading', v_subinfo is not null), v_sys);
  select p.stable_key into v_key from catalogue.providers p where p.id = i.entity_id;
  begin v_pub := public.website_v2_provider(v_key); v_shown := v_pub->'item'->>'description'; exception when others then v_shown := null; end;
  update pipeline.provider_description_reads set state = 'admitted', last_verified_at = now(), published_at = case when v_shown = v_text then now() end, updated_at = now(),
         proposal = case when v_subinfo is not null then coalesce(proposal, '{}'::jsonb) || jsonb_build_object('description', v_text, 'sentences', v_sent) else proposal end,
         checks = coalesce(checks, '{}'::jsonb) || jsonb_build_object('machine_rule', v_rule, 'tier', v_tier, 'actor_kind', 'machine') || case when v_subinfo is not null then jsonb_build_object('subset_of_reading', v_subinfo) else '{}'::jsonb end where id = v_read.id;
  update pipeline.provider_description_reads set state = 'superseded', updated_at = now() where provider_id = i.entity_id and state = 'admitted' and id <> v_read.id;
  insert into pipeline.search_refresh_signals (entity_type, entity_id, review_decision_id, reason, change_control_ref)
  values ('provider', i.entity_id, v_dec, 'Accepted machine-rule Layer 4 canonical change: ' || v_reason, v_ref);
  if v_upg then
    -- the profile admission is closed, never deleted: its text stays as the earlier version (one live admission a provider)
    update pipeline.provider_description_machine_admissions set withdrawn_at = now(), withdrawn_by = v_sys,
           withdrawn_reason = 'Upgraded to a source-verified description from ' || coalesce(v_url, 'the official page') || '; the register-fact profile is kept in this row.'
     where id = (v_basic->>'admission_id')::uuid and outcome = 'admitted' and withdrawn_at is null;
  end if;
  insert into pipeline.provider_description_machine_admissions (provider_id, review_item_id, read_id, tier, rule, outcome, reason, before_description, after_description, evidence_id, source_url, source_hash, facts, checks, actor)
  values (i.entity_id, i.id, v_read.id, v_tier, v_rule, 'admitted', case when v_subinfo is not null then 'subset_of_reading: ' else '' end || v_reason || case when v_upg then ' Upgrade of the register-fact profile, which is kept as the earlier version.' else '' end, case when v_upg then v_basic->>'text' end, v_text, i.evidence_id, v_url, v_hash, v_facts,
          jsonb_build_object('decision_id', v_dec, 'published', v_shown = v_text, 'validation', coalesce(v_check->'checks', v_prof->'facts'),
          'neutral_words', to_jsonb(security.pdesc_machine_neutral_supported_v1(v_text, case when v_tier = 'registry_factual' then '[]'::jsonb else v_sent end)))
          || case when v_subinfo is not null then jsonb_build_object('subset_of_reading', v_subinfo) else '{}'::jsonb end, v_sys);
  if v_upg then
    update pipeline.provider_description_machine_admissions set checks = checks || jsonb_build_object('upgrade', jsonb_build_object('from_tier', 'registry_factual', 'prior_admission_id', v_basic->'admission_id', 'prior_read_id', v_basic->'read_id',
           'source_url', v_url, 'source_hash', v_hash, 'evidence_id', i.evidence_id, 'sentences', jsonb_array_length(v_sent)))
     where review_item_id = i.id and outcome = 'admitted';
  end if;
  return jsonb_build_object('ok', true, 'provider_id', i.entity_id, 'tier', v_tier, 'rule', v_rule, 'decision_id', v_dec, 'description_chars', length(v_text), 'published', v_shown = v_text, 'subset_of_reading', v_subinfo is not null);
end $$;


ALTER FUNCTION "security"."provider_description_machine_admit_v1"("p_item_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_machine_admit_v1"("p_item_id" "uuid") IS 'CF-247 F-PDESC machine admission of one provider''s FIRST description (tiers stored, direct, firecrawl, registry_factual): re-proves identity, lineage and quotes, applies the objective rule, writes the one description, settles the item under the system automation account with the machine rule and records the audit row. Never calls the human Layer 4 decision procedure. Declines (with the reason on the item and in the audit) rather than guess.';



CREATE OR REPLACE FUNCTION "security"."provider_description_machine_blocked_v1"("p_provider" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER COST 500
    SET "search_path" TO ''
    AS $$
declare p catalogue.providers%rowtype; v_find text;
begin
  select * into p from catalogue.providers where id = p_provider;
  if p.id is null then return jsonb_build_object('rule', 'provider_not_live', 'reason', 'There is no such provider.'); end if;
  if exists (select 1 from pipeline.manual_locks l where l.entity = 'provider' and l.entity_id = p.id and l.field in ('description', 'p_description', 'all')) then
    return jsonb_build_object('rule', 'manual_lock', 'reason', 'The description is locked by hand.'); end if;
  if nullif(btrim(p.description), '') is not null and security.provider_description_basic_profile_v1(p.id) is null then -- a register-fact profile is not a description held (pdesc.registry_upgrade_on); every check below still applies to it
    return jsonb_build_object('rule', 'description_already_held', 'reason', 'The provider already holds a description; the machine rule admits a first description only.'); end if;
  if nullif(btrim(p.description), '') is null and exists (select 1 from pipeline.provider_description_machine_admissions a where a.provider_id = p.id and a.outcome = 'admitted' and a.withdrawn_at is null) then
    return jsonb_build_object('rule', 'description_cleared_after_admission', 'reason', 'A machine description was admitted for this provider and the description has since been cleared by hand; a person decides the next one.'); end if;
  if exists (select 1 from pipeline.layer4_review_items li where li.entity_type = 'provider' and li.entity_id = p.id and li.field_code = 'provider_description' and li.status = 'rejected') then
    return jsonb_build_object('rule', 'prior_human_rejection', 'reason', 'A person rejected an earlier description for this provider.'); end if;
  if exists (select 1 from pipeline.provider_description_machine_admissions a where a.provider_id = p.id and a.outcome = 'admitted' and a.withdrawn_at is not null and coalesce(a.withdrawn_reason, '') not like 'Upgraded to a source-verified description%'
               and not exists (select 1 from pipeline.provider_description_machine_admissions b where b.provider_id = p.id and b.outcome = 'admitted' and b.created_at > a.withdrawn_at)) then
    return jsonb_build_object('rule', 'withdrawn_awaiting_review', 'reason', 'A machine description for this provider was withdrawn; a person decides the next one.'); end if;
  select f.check_code into v_find from pipeline.provider_identity_findings f where f.provider_id = p.id and f.state = 'open' order by f.check_code limit 1;
  if v_find is not null then return jsonb_build_object('rule', 'identity_' || v_find, 'reason', 'An open provider identity finding needs a person: ' || v_find); end if;
  if (nullif(btrim(p.canonical_name), '') is not null and security.pdesc_clean_name_v1(p.canonical_name) is null)
     or (nullif(btrim(p.display_name), '') is not null and security.pdesc_clean_name_v1(p.display_name) is null)
     or (security.pdesc_clean_name_v1(p.canonical_name) is null and security.pdesc_clean_name_v1(p.display_name) is null) then
    return jsonb_build_object('rule', 'name_not_clean', 'reason', 'A provider name is a placeholder, too short or still holds web-page markup, so the identity proof is not reliable; a person decides.'); end if;
  return null;
end $$;


ALTER FUNCTION "security"."provider_description_machine_blocked_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_machine_blocked_v1"("p_provider" "uuid") IS 'CF-247 F-PDESC QA N6/N7/N8/N11: why the automatic rule must not read or describe this provider now, or null: locked by hand, already described, a machine description admitted and since cleared by hand, an earlier human rejection, a withdrawn machine description awaiting review, an open identity finding, or a placeholder or marked-up name. Read only; the reader holds such a provider before any AI call.';



CREATE OR REPLACE FUNCTION "security"."provider_description_machine_gate_v1"("p_provider" "uuid", "p_text" "text", "p_ctx" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare p catalogue.providers%rowtype; v_sys uuid := 'c0ffee00-0000-4000-8000-000000000150'; -- fixed: the system automation account (Decision 263)
        v_bad text; v_blk jsonb; v_codes text[] := coalesce(array(select jsonb_array_elements_text(coalesce(p_ctx->'codes', '[]'::jsonb))), '{}');
begin
  if security.pipeline_num_v1('pdesc.machine_admit_on', 0) < 1 then return jsonb_build_object('ok', false, 'rule', 'machine_admission_off', 'reason', 'Automatic admission is off; a person decides in Layer 4.'); end if;
  select * into p from catalogue.providers where id = p_provider;
  if p.id is null or p.lifecycle_status <> 'active' or p.publication_status <> 'published' or exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id) or security.provider_lifecycle_held_v1(p.id) then
    return jsonb_build_object('ok', false, 'rule', 'provider_not_live', 'reason', 'The provider is not active and published, or its lifecycle is held.');
  end if;
  if not security.provider_description_scope_v1(p.id) then return jsonb_build_object('ok', false, 'rule', 'out_of_scope', 'reason', 'The provider is outside the description reader scope.'); end if;
  -- lock, description already held, cleared after a machine admission, earlier human rejection, withdrawn awaiting review, open identity finding, unusable name
  v_blk := security.provider_description_machine_blocked_v1(p.id);
  if v_blk is not null then return jsonb_build_object('ok', false, 'rule', v_blk->>'rule', 'reason', v_blk->>'reason'); end if;
  if nullif(btrim(p_text), '') is null then return jsonb_build_object('ok', false, 'rule', 'no_description', 'reason', 'There is no description text.'); end if;
  v_bad := security.pdesc_machine_text_check_ctx_v1(p.id, p_text, v_codes, coalesce(p_ctx->'sentences', '[]'::jsonb));
  if v_bad is not null then return jsonb_build_object('ok', false, 'rule', 'machine_text_' || split_part(v_bad, ':', 1), 'reason', 'The description has a word, figure or markup the automatic rule does not admit (' || v_bad || '); it is not published automatically.'); end if;
  return jsonb_build_object('ok', true, 'rule', 'pdesc-machine-v1', 'actor', v_sys);
end $$;


ALTER FUNCTION "security"."provider_description_machine_gate_v1"("p_provider" "uuid", "p_text" "text", "p_ctx" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_machine_gate_v1"("p_provider" "uuid", "p_text" "text", "p_ctx" "jsonb") IS 'CF-247 F-PDESC machine rule pdesc-machine-v1, the conditions common to every tier: switch on, provider live and in scope, then security.provider_description_machine_blocked_v1 (lock, description held, cleared after a machine admission, earlier human rejection, withdrawn awaiting review, open identity finding, unusable name) and the objective text rule. Read only.';



CREATE OR REPLACE FUNCTION "security"."provider_description_machine_report_v1"("p_detail" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_out jsonb;
begin
  select jsonb_build_object(
    'contract', 'provider-description-machine-report-v1', 'as_at', now(),
    'providers', (select jsonb_object_agg(z.cc, jsonb_build_object('providers', z.n, 'live', z.live, 'described', z.described, 'machine_admitted', z.machine, 'website_verified', z.web, 'zoho_verified', z.zoho))
                    from (select k.iso_alpha2::text cc, count(*) n, count(*) filter (where p.lifecycle_status = 'active' and p.publication_status = 'published') live,
                                 count(*) filter (where nullif(btrim(p.description), '') is not null) described,
                                 count(a.id) machine,
                                 count(*) filter (where (rd.consumer_checks->>'website_verified')::boolean) web, count(*) filter (where (rd.consumer_checks->>'zoho_verified')::boolean) zoho
                            from catalogue.providers p join ref.countries k on k.id = p.country_id
                            left join pipeline.provider_description_machine_admissions a on a.provider_id = p.id and a.outcome = 'admitted' and a.withdrawn_at is null
                            left join pipeline.provider_description_reads rd on rd.id = a.read_id
                           group by k.iso_alpha2) z),
    'tiers', (select coalesce(jsonb_object_agg(t.tier, t.n), '{}'::jsonb) from (select tier, count(*) n from pipeline.provider_description_machine_admissions where outcome = 'admitted' and withdrawn_at is null group by tier) t),
    'declined', (select coalesce(jsonb_object_agg(d.reason_key, d.n), '{}'::jsonb) from (select split_part(reason, ' (', 1) reason_key, count(*) n from pipeline.provider_description_machine_admissions where outcome = 'declined' group by 1) d),
    'holds', (select coalesce(jsonb_object_agg(h.rule, h.n), '{}'::jsonb) from (select x.rule, count(*) n from pipeline.provider_description_reads x where x.state = 'held' and (x.rule like 'machine_declined%' or x.rule = 'insufficient_verified_facts') group by x.rule) h),
    'parity', (select jsonb_build_object('admitted', count(*), 'website_verified', count(*) filter (where (rd.consumer_checks->>'website_verified')::boolean), 'zoho_verified', count(*) filter (where (rd.consumer_checks->>'zoho_verified')::boolean),
                 'not_yet_checked', count(*) filter (where rd.consumer_checked_at is null),
                 'mismatched', coalesce((select jsonb_agg(jsonb_build_object('provider_id', m.provider_id, 'website', (m.consumer_checks->>'website_verified'), 'zoho', (m.consumer_checks->>'zoho_verified')) )
                                           from (select a2.provider_id, rd2.consumer_checks from pipeline.provider_description_machine_admissions a2 join pipeline.provider_description_reads rd2 on rd2.id = a2.read_id
                                                  where a2.outcome = 'admitted' and a2.withdrawn_at is null and rd2.consumer_checked_at is not null
                                                    and not (coalesce((rd2.consumer_checks->>'website_verified')::boolean, false) and coalesce((rd2.consumer_checks->>'zoho_verified')::boolean, false)) limit greatest(coalesce(p_detail, security.pipeline_num_v1('pdesc.report_detail', 20)::int), 0)) m), '[]'::jsonb))
                 from pipeline.provider_description_machine_admissions a join pipeline.provider_description_reads rd on rd.id = a.read_id where a.outcome = 'admitted' and a.withdrawn_at is null),
    'throughput', security.provider_description_throughput_v1()) into v_out;
  return v_out;
end $$;


ALTER FUNCTION "security"."provider_description_machine_report_v1"("p_detail" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_machine_report_v1"("p_detail" integer) IS 'CF-247 F-PDESC acceptance scoreboard (read only): providers by country (live, described, machine-admitted, Website and Zoho read-back), admissions by tier, the exact holds and declines, the consumer parity mismatches and the throughput. The Website and Zoho read-back is recorded by the existing publication check on the admitted read; nothing here calls or changes a consumer API.';



CREATE OR REPLACE FUNCTION "security"."provider_description_machine_settle_pending_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_res jsonb; v_ok int := 0; v_no int := 0; v_err int := 0;
begin
  if security.pipeline_num_v1('pdesc.machine_admit_on', 0) < 1 then return jsonb_build_object('on', false); end if;
  for r in select li.id from pipeline.layer4_review_items li where li.field_code = 'provider_description' and li.entity_type = 'provider' and li.status = 'pending'
            and not exists (select 1 from pipeline.provider_description_machine_admissions a where a.review_item_id = li.id and a.outcome = 'declined' and a.created_at > now() - make_interval(hours => 1)) -- fixed: a declined item is checked again at most hourly
            order by li.created_at limit security.pipeline_num_v1('pdesc.machine_settle_per_run', 10)::int loop
    begin
      v_res := security.provider_description_machine_admit_v1(r.id);
      if (v_res->>'ok')::boolean then v_ok := v_ok + 1; else v_no := v_no + 1; end if;
    exception when others then v_err := v_err + 1;
    end;
  end loop;
  return jsonb_build_object('on', true, 'admitted', v_ok, 'left_for_a_person', v_no, 'errors', v_err);
end $$;


ALTER FUNCTION "security"."provider_description_machine_settle_pending_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_machine_settle_pending_v1"() IS 'CF-247 F-PDESC: checks the provider-description items already waiting in Layer 4 against the machine rule, a bounded number a run (pdesc.machine_settle_per_run). Those that pass are admitted and settled as machine decisions; the rest stay for a person with the reason on the item.';



CREATE OR REPLACE FUNCTION "security"."provider_description_machine_step_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_a jsonb; v_b jsonb;
begin
  -- one failure never stops the reader: each part reports its own error
  begin v_a := security.provider_description_machine_settle_pending_v1(); exception when others then v_a := jsonb_build_object('error', sqlerrm); end;
  begin v_b := security.provider_description_registry_tier_v1(); exception when others then v_b := jsonb_build_object('error', sqlerrm); end;
  return jsonb_build_object('settle', v_a, 'registry', v_b);
end $$;


ALTER FUNCTION "security"."provider_description_machine_step_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_machine_step_v1"() IS 'CF-247 F-PDESC: the machine part of one run of the existing provider-description-read job (settle waiting items, tier 4). Called by security.provider_description_fire_v1 only when pdesc.machine_admit_on is 1.';



CREATE OR REPLACE FUNCTION "security"."provider_description_machine_withdraw_v1"("p_provider" "uuid", "p_reason" "text", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a pipeline.provider_description_machine_admissions%rowtype; v_now text; v_after text; v_dec uuid;
begin
  -- the caller is the person who asked (public.admin_provider_description_machine_withdraw_v1 passes auth.uid()); the system account is never recorded as the one who withdrew
  if p_actor is null or p_actor = 'c0ffee00-0000-4000-8000-000000000150'::uuid then raise exception 'the person who withdraws must be named'; end if; -- fixed: the system automation account (Decision 263) is not a person
  if nullif(btrim(p_reason), '') is null then raise exception 'give a reason (kept in the log)'; end if;
  select * into a from pipeline.provider_description_machine_admissions where provider_id = p_provider and outcome = 'admitted' and withdrawn_at is null for update;
  if a.id is null then return jsonb_build_object('ok', false, 'rule', 'no_live_machine_admission'); end if;
  select nullif(btrim(p.description), '') into v_now from catalogue.providers p where p.id = p_provider for update;
  if v_now is distinct from a.after_description then return jsonb_build_object('ok', false, 'rule', 'description_changed_since_admission', 'reason', 'A person changed the description since the machine admitted it; it is kept.'); end if;
  -- a hand lock added since the admission keeps the text (the catalogue guard would put it back silently): refuse, and change nothing
  if exists (select 1 from pipeline.manual_locks l where l.entity = 'provider' and l.entity_id = p_provider and l.field in ('description', 'p_description', 'all')) then
    return jsonb_build_object('ok', false, 'rule', 'manual_lock', 'reason', 'The description has been locked by hand since the machine admitted it; it is kept. Release the lock first.'); end if;
  v_dec := nullif(a.checks->>'decision_id', '')::uuid;
  if v_dec is null then raise exception 'the admission has no decision to point the search refresh at'; end if;
  update catalogue.providers set description = a.before_description, updated_at = now() where id = p_provider;
  -- proved on the row, not assumed: a guard that put the old text back would leave the audit saying "restored"
  select nullif(btrim(p.description), '') into v_after from catalogue.providers p where p.id = p_provider;
  if v_after is distinct from nullif(btrim(a.before_description), '') then raise exception 'withdraw_not_applied: the catalogue kept the description; nothing was changed'; end if;
  update pipeline.provider_description_machine_admissions set withdrawn_at = now(), withdrawn_by = p_actor, withdrawn_reason = btrim(p_reason) where id = a.id;
  update pipeline.provider_description_reads set state = 'superseded', rule = 'machine_withdrawn', updated_at = now() where id = a.read_id and state in ('admitted', 'verified');
  insert into pipeline.admin_control_events (area, action, target, detail, actor)
  values ('layer4', 'pdesc_machine_withdraw', p_provider::text, jsonb_build_object('admission_id', a.id, 'review_item_id', a.review_item_id, 'tier', a.tier, 'rule', a.rule, 'before', a.before_description, 'after', a.after_description, 'reason', btrim(p_reason), 'withdrawn_by', p_actor), p_actor);
  -- production keeps ONE search refresh signal for each decision (UNIQUE review_decision_id): the signal the admission queued is queued again for the same decision, not a second row
  insert into pipeline.search_refresh_signals as s (entity_type, entity_id, review_decision_id, reason, change_control_ref)
  values ('provider', p_provider, v_dec, 'Machine description withdrawn: ' || btrim(p_reason), 'CF-247 F-PDESC withdrawal')
  on conflict (review_decision_id) do update set status = case when s.status = 'processing' then s.status else 'queued' end, completed_at = null, reason = excluded.reason, change_control_ref = excluded.change_control_ref;
  return jsonb_build_object('ok', true, 'provider_id', p_provider, 'admission_id', a.id, 'restored', a.before_description, 'withdrawn_by', p_actor);
end $$;


ALTER FUNCTION "security"."provider_description_machine_withdraw_v1"("p_provider" "uuid", "p_reason" "text", "p_actor" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_machine_withdraw_v1"("p_provider" "uuid", "p_reason" "text", "p_actor" "uuid") IS 'CF-247 F-PDESC rollback of one machine-admitted description: restores the earlier text if no person changed it since and no hand lock was added, proves the row changed, records the named person and why, queues the search refresh again on the admission''s own decision (one signal for each decision), and holds the provider out of further automatic admission until a person decides. One provider at a time. Not callable from the app; use public.admin_provider_description_machine_withdraw_v1.';



CREATE OR REPLACE FUNCTION "security"."provider_description_page_v1"("p_provider" "uuid", "p_url" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_host text := regexp_replace(lower(coalesce(substring(p_url from '^https?://([^/?#:]+)'), '')), '^www\.', '');
        v_path text := lower(coalesce(substring(p_url from '^https?://[^/?#]+(/[^?#]*)'), ''));
        v_hosts text[] := security.provider_hosts_v1(p_provider); v_main boolean; v_segs text[]; v_first text; v_n int;
begin
  if v_host = '' or security.provider_page_host_v1(p_provider, p_url) <> 'own' then
    return jsonb_build_object('ok', false, 'rule', 'wrong_host', 'main_host', false);
  end if;
  v_main := v_host = any (v_hosts);
  if not v_main and exists (select 1 from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'pdesc.refused_host_labels'), '[]'::jsonb)) l
                             where split_part(v_host, '.', 1) = lower(l)) then
    return jsonb_build_object('ok', false, 'rule', 'refused_host', 'main_host', false);
  end if;
  v_segs := array(select s from unnest(string_to_array(regexp_replace(v_path, '/+$', ''), '/')) s where s <> '');
  if cardinality(v_segs) > 0 and v_segs[1] ~ '^[a-z]{2}(-[a-z]{2})?$' then v_segs := v_segs[2:]; end if;  -- fixed: a language part (/en/, /en-au/) is not a path part
  if exists (select 1 from unnest(v_segs) s, regexp_split_to_table(s, '[-_.]+') t,
                  jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'pdesc.refused_path_words'), '[]'::jsonb)) w
              where t = lower(w) or s = lower(w)) then
    return jsonb_build_object('ok', false, 'rule', 'refused_word', 'main_host', v_main);
  end if;
  v_n := coalesce(cardinality(v_segs), 0); v_first := coalesce(v_segs[1], '');
  if v_n = 0 or v_n > security.pipeline_num_v1('pdesc.about_max_segments', 2)
     or not (exists (select 1 from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'pdesc.about_patterns'), '[]'::jsonb)) a where v_first = lower(a))
             or exists (select 1 from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'pdesc.about_prefixes'), '[]'::jsonb)) x
                         where x <> '' and left(v_first, length(x)) = lower(x) and length(v_first) > length(x))) then
    return jsonb_build_object('ok', false, 'rule', 'not_about_page', 'main_host', v_main);
  end if;
  return jsonb_build_object('ok', true, 'rule', 'about_page', 'main_host', v_main);
end $_$;


ALTER FUNCTION "security"."provider_description_page_v1"("p_provider" "uuid", "p_url" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_page_v1"("p_provider" "uuid", "p_url" "text") IS 'CF-247 P1 provider descriptions (pilot 2 Nov 2026 16:16): may this address be a description source? The provider''s own host, not a refused subdomain (pdesc.refused_host_labels); no refused word in the path (pdesc.refused_path_words); an About page name (pdesc.about_patterns, pdesc.about_prefixes) as the first path part, at most pdesc.about_max_segments parts. main_host: on the website or an approved other website itself.';



CREATE OR REPLACE FUNCTION "security"."provider_description_prompt_active_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 F-PDESC (20261112010000): the active prompt while pdesc.prompt_on is 1; null means the worker's built-in prompt v2
  select case when security.pipeline_num_v1('pdesc.prompt_on', 0) >= 1 then
    (select jsonb_build_object('version', 'provider-description-p' || p.version, 'system', p.system_prompt) from pipeline.provider_description_prompts p where p.status = 'active')
  end
$$;


ALTER FUNCTION "security"."provider_description_prompt_active_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_prompt_active_v1"() IS 'CF-247 F-PDESC (20261112010000): the active provider-description prompt and its version string, or null (built-in prompt v2) while pdesc.prompt_on is 0.';



CREATE OR REPLACE FUNCTION "security"."provider_description_publication_check_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_body jsonb; v_zoho jsonb; v_n int:=0;
begin
 for r in select d.id,d.provider_id,d.proposal,p.stable_key,p.description from pipeline.provider_description_reads d join catalogue.providers p on p.id=d.provider_id where d.state in ('admitted','verified') and p.description=d.proposal->>'description' and security.provider_description_approved_lineage_v1(p.id,p.description) is not null order by d.consumer_checked_at nulls first,d.id limit security.pipeline_num_v1('pdesc.queue_per_run',10)::int for update of d skip locked loop
  begin v_body:=public.website_v2_provider(r.stable_key); exception when others then v_body:=null; end;
  v_zoho:=security.provider_description_consumer_read_v1('zoho',r.stable_key);
  update pipeline.provider_description_reads set consumer_checked_at=now(),consumer_checks=jsonb_build_object('website_verified',coalesce(v_body->'item'->>'provider_id'=r.stable_key and v_body->'item'->>'description'=r.description and r.description=r.proposal->>'description',false),'zoho_verified',coalesce(v_zoho->'item'->>'provider_id'=r.stable_key and v_zoho->'item'->>'description'=r.description and r.description=r.proposal->>'description',false),'website_error',v_body->'error','zoho_error',v_zoho->'error','checked_at',now()),zoho_published_at=case when v_zoho->'item'->>'provider_id'=r.stable_key and v_zoho->'item'->>'description'=r.description and r.description=r.proposal->>'description' then coalesce(zoho_published_at,now()) else zoho_published_at end,published_at=case when v_body->'item'->>'description'=r.description and v_body->'item'->>'provider_id'=r.stable_key and r.description=r.proposal->>'description' then coalesce(published_at,now()) else published_at end,updated_at=now() where id=r.id;
  if v_body->'item'->>'description'=r.description and v_body->'item'->>'provider_id'=r.stable_key and r.description=r.proposal->>'description' then v_n:=v_n+1; end if;
 end loop;
 return v_n;
end $$;


ALTER FUNCTION "security"."provider_description_publication_check_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_description_publication_read_v1"("p_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- the actual consumer reads (security.provider_description_consumer_read_v1 -> the Website and Zoho provider reads), one provider at a time so a failed read never hides the rest.
  -- A consumer that answers NOT_FOUND does not serve the provider: not_served, never an error. 'feed' is what the Catalogue's own Website and Zoho state says the sync expects (verified, pending or
  -- not_applicable); the read-back is what the consumer returns now, and the two can differ.
  return (
    with f as (select ff.provider_id, ff.website_state, ff.zoho_state from security.provider_catalogue_facts_v1(p_ids, true) ff) -- one call for the whole set: it runs both feed scans once, not once a provider
    select jsonb_build_object('as_at', now(), 'providers', coalesce(jsonb_agg(jsonb_build_object('provider_id', p.id, 'name', coalesce(p.display_name, p.canonical_name),
      'catalogue', jsonb_build_object('status', case when nullif(btrim(p.description), '') is null then 'no_description' else 'present' end),
      'website', jsonb_build_object('status', case when nullif(btrim(p.description), '') is null then 'awaiting_description' when w.body->'error'->>'code' = 'NOT_FOUND' then 'not_served' when w.body ? 'error' then 'error'
                                                   when w.body->'item' is null or jsonb_typeof(w.body->'item') <> 'object' then 'not_served'
                                                   when w.body->'item'->>'provider_id' = p.stable_key and w.body->'item'->>'description' = p.description then 'verified' else 'mismatch' end,
                                   'description', w.body->'item'->>'description', 'error', w.body->'error', 'feed', security.provider_description_publication_v1(f.website_state)),
      'zoho', jsonb_build_object('status', case when nullif(btrim(p.description), '') is null then 'awaiting_description' when z.body->'error'->>'code' = 'NOT_FOUND' then 'not_served' when z.body ? 'error' then 'error'
                                                when z.body->'item' is null or jsonb_typeof(z.body->'item') <> 'object' then 'not_served'
                                                when z.body->'item'->>'provider_id' = p.stable_key and z.body->'item'->>'description' = p.description then 'verified' else 'mismatch' end,
                                 'description', z.body->'item'->>'description', 'error', z.body->'error', 'feed', security.provider_description_publication_v1(f.zoho_state))) order by coalesce(p.display_name, p.canonical_name)), '[]'::jsonb))
      from catalogue.providers p
      left join lateral (select security.provider_description_consumer_read_v1('website', p.stable_key) body where nullif(btrim(p.description), '') is not null) w on true
      left join lateral (select security.provider_description_consumer_read_v1('zoho', p.stable_key) body where nullif(btrim(p.description), '') is not null) z on true
      left join f on f.provider_id = p.id
     where p.id = any(p_ids)
  );
end
$$;


ALTER FUNCTION "security"."provider_description_publication_read_v1"("p_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_description_publication_v1"("p_state" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
  -- one consumer: matched = verified; the feed holds other text or has no item yet = pending; a consumer that does not serve the provider = not applicable (never a failure); not worked out = null
  select case p_state when 'matched' then 'verified' when 'pending' then 'pending' when 'missing' then 'pending' when 'not_applicable' then 'not_applicable' end
$$;


ALTER FUNCTION "security"."provider_description_publication_v1"("p_state" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_description_quality_class_v1"("p_filled" boolean, "p_adm" "text", "p_tier" "text", "p_reader" "text", "p_l4" "text", "p_web" "text", "p_zoho" "text", "p_feeds" boolean DEFAULT true) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
  select case
    when coalesce(p_filled, false) then
      case when p_adm = 'admitted' and p_tier = 'registry_factual' then
             case when p_reader = 'reading' then 'processing' when p_reader = 'queued' then 'queued' when p_reader = 'proposed' then 'waiting_decision' else 'basic_registry' end
           when p_adm = 'admitted' then
             case when not coalesce(p_feeds, false) or security.provider_description_publication_v1(p_web) is null or security.provider_description_publication_v1(p_zoho) is null then null
                  when 'pending' in (security.provider_description_publication_v1(p_web), security.provider_description_publication_v1(p_zoho)) then 'consumer_pending'
                  when 'verified' in (security.provider_description_publication_v1(p_web), security.provider_description_publication_v1(p_zoho)) then 'verified_published'
                  else 'enriched_admitted' end
           else 'unrecorded' end
    else
      case when p_adm = 'pending' and (p_reader = 'proposed' or p_l4 = 'pending') then 'waiting_decision'
           when p_adm = 'pending' and p_reader = 'reading' then 'processing'
           when p_adm = 'pending' then 'queued'
           when p_adm in ('held', 'declined') then 'held'
           else 'missing' end
  end
$$;


ALTER FUNCTION "security"."provider_description_quality_class_v1"("p_filled" boolean, "p_adm" "text", "p_tier" "text", "p_reader" "text", "p_l4" "text", "p_web" "text", "p_zoho" "text", "p_feeds" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_description_quality_classes_v1"() RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
  -- the order of the pipeline, from nothing to published; the Provider Catalogue sorts by it
  select array['missing', 'queued', 'processing', 'waiting_decision', 'held', 'basic_registry', 'unrecorded', 'enriched_admitted', 'consumer_pending', 'verified_published']::text[]
$$;


ALTER FUNCTION "security"."provider_description_quality_classes_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_description_quality_counts_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with q as (select * from security.provider_description_quality_v1(null, true)),
       c as (select coalesce(quality_class, 'unknown') k, count(*) n from q group by 1),
       s as (select count(*) n, min(computed_at) oldest, max(computed_at) newest from pipeline.provider_description_quality)
  select jsonb_build_object('as_at', now(), 'total', (select count(*) from q),
    'classes', coalesce((select jsonb_object_agg(k, n) from c), '{}'::jsonb),
    'with_description', (select count(*) from q where description_filled),
    'website_publication', coalesce((select jsonb_object_agg(coalesce(website_publication, 'none'), n) from (select website_publication, count(*) n from q where description_filled group by 1) w), '{}'::jsonb),
    'zoho_publication', coalesce((select jsonb_object_agg(coalesce(zoho_publication, 'none'), n) from (select zoho_publication, count(*) n from q where description_filled group by 1) z), '{}'::jsonb),
    'snapshot', (select jsonb_build_object('rows', s.n, 'oldest', s.oldest, 'newest', s.newest) from s))
$$;


ALTER FUNCTION "security"."provider_description_quality_counts_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_description_quality_refresh_v1"("p_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_ids uuid[]; v_total bigint; v_n int; v_by jsonb;
begin
  if p_ids is null then
    select coalesce(array_agg(x.id), array[]::uuid[]) into v_ids from (
      select p.id from catalogue.providers p) x;
  else
    select coalesce(array_agg(x.id), array[]::uuid[]) into v_ids from (select distinct i id from unnest(p_ids) i) x;
  end if;
  select count(*) into v_total from catalogue.providers;
  insert into pipeline.provider_description_quality as t(provider_id, quality_class, description_present, admission_state, source_tier, reader_state, reader_rule, l4_status, hold_reason, next_retry_at, last_read_ok_at,
                                                         admitted_at, website_state, zoho_state, website_publication, zoho_publication, readback_at, missing_fields, class_since, computed_at)
  select q.provider_id, q.quality_class, q.description_filled, q.admission_state, q.source_tier, q.reader_state, q.reader_rule, q.l4_status, q.hold_reason, q.next_retry_at, q.last_read_ok_at,
         q.admitted_at, q.website_state, q.zoho_state, q.website_publication, q.zoho_publication, q.readback_at, coalesce(q.missing_fields, '{}'), now(), now()
    from security.provider_description_quality_v1(v_ids, true) q where q.quality_class is not null
  on conflict (provider_id) do update set
    quality_class = excluded.quality_class, description_present = excluded.description_present, admission_state = excluded.admission_state, source_tier = excluded.source_tier,
    reader_state = excluded.reader_state, reader_rule = excluded.reader_rule, l4_status = excluded.l4_status, hold_reason = excluded.hold_reason, next_retry_at = excluded.next_retry_at,
    last_read_ok_at = excluded.last_read_ok_at, admitted_at = excluded.admitted_at, website_state = excluded.website_state, zoho_state = excluded.zoho_state,
    website_publication = excluded.website_publication, zoho_publication = excluded.zoho_publication, readback_at = excluded.readback_at, missing_fields = excluded.missing_fields,
    class_since = case when t.quality_class is distinct from excluded.quality_class then now() else t.class_since end, computed_at = now();
  get diagnostics v_n = row_count;
  select coalesce(jsonb_object_agg(k, n), '{}'::jsonb) into v_by from (select quality_class k, count(*) n from pipeline.provider_description_quality where provider_id = any(v_ids) group by 1) z;
  return jsonb_build_object('refreshed', v_n, 'asked', cardinality(v_ids), 'providers_total', v_total, 'by_class', v_by, 'as_at', now());
end
$$;


ALTER FUNCTION "security"."provider_description_quality_refresh_v1"("p_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_description_quality_v1"("p_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_feeds" boolean DEFAULT true) RETURNS TABLE("provider_id" "uuid", "quality_class" "text", "description_filled" boolean, "admission_state" "text", "source_tier" "text", "evidence_id" "uuid", "source_url" "text", "reader_state" "text", "reader_rule" "text", "reader_tries" integer, "l4_status" "text", "hold_reason" "text", "next_retry_at" timestamp with time zone, "last_read_ok_at" timestamp with time zone, "admitted_at" timestamp with time zone, "admitted_by" "text", "website_state" "text", "zoho_state" "text", "website_publication" "text", "zoho_publication" "text", "readback_at" timestamp with time zone, "missing_fields" "text"[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "plan_cache_mode" TO 'force_custom_plan'
    AS $$
#variable_conflict use_column
begin
  return query
  select f.provider_id, security.provider_description_quality_class_v1(f.description_filled, f.admission_state, f.source_tier, f.reader_state, f.l4_status, f.website_state, f.zoho_state, p_feeds),
         f.description_filled, f.admission_state, f.source_tier, f.evidence_id, f.source_url, f.reader_state, f.reader_rule, f.reader_tries, f.l4_status, f.hold_reason, f.next_retry_at, f.last_read_ok_at,
         f.admitted_at, f.admitted_by, f.website_state, f.zoho_state,
         security.provider_description_publication_v1(f.website_state), security.provider_description_publication_v1(f.zoho_state), f.readback_at, security.provider_missing_fields_v1(p)
    from security.provider_catalogue_facts_v1(p_ids, p_feeds) f join catalogue.providers p on p.id = f.provider_id;
end
$$;


ALTER FUNCTION "security"."provider_description_quality_v1"("p_ids" "uuid"[], "p_feeds" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_description_registry_profile_v1"("p_provider" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare p catalogue.providers%rowtype; reg record; tpl text; v_country text; v_type text; v_tcode text; v_region text; v_city text; v_loc text; v_name text; v_art text;
        v_levels text[]; v_fields text[]; v_max int := security.pipeline_num_v1('pdesc.registry_offerings_max', 3)::int; v_min int := security.pipeline_num_v1('pdesc.registry_min_facts', 3)::int;
        v_facts jsonb := '[]'::jsonb; v_sent jsonb := '[]'::jsonb; s1 text; s2 text; s3 text; v_text text; v_ev record; v_have text[] := '{}'; v_asof timestamptz;
begin
  select * into p from catalogue.providers where id = p_provider;
  if p.id is null then return jsonb_build_object('ok', false, 'rule', 'insufficient_verified_facts', 'reason', 'No such provider.'); end if;
  select k.name into v_country from ref.countries k where k.id = p.country_id;
  select t.code, t.name into v_tcode, v_type from ref.provider_types t where t.id = p.provider_type_id;
  select s.name into v_region from ref.subdivisions s where s.id = p.subdivision_id;
  select r.* into reg from catalogue.provider_registrations r where r.provider_id = p.id and r.status = 'active' and r.evidence_id is not null order by r.checked_at desc nulls last, r.id limit 1;
  if reg.id is null then return jsonb_build_object('ok', false, 'rule', 'insufficient_verified_facts', 'reason', 'The provider has no active register listing with stored evidence.'); end if;
  select a.id, a.source_url, a.content_hash, coalesce(a.captured_at, a.created_at) captured_at into v_ev from pipeline.evidence_artifacts a where a.id = reg.evidence_id;
  if v_ev.id is null then return jsonb_build_object('ok', false, 'rule', 'insufficient_verified_facts', 'reason', 'The register listing''s evidence is not stored.'); end if;
  select t.register_sentence into tpl from pipeline.provider_description_registry_templates t where t.scheme = reg.registration_scheme and t.active;
  if tpl is null then return jsonb_build_object('ok', false, 'rule', 'insufficient_verified_facts', 'reason', 'There is no profile wording for register scheme ' || reg.registration_scheme || '.'); end if;
  v_name := coalesce(security.pdesc_clean_name_v1(p.display_name), security.pdesc_clean_name_v1(p.canonical_name));
  if v_name is null then return jsonb_build_object('ok', false, 'rule', 'insufficient_verified_facts', 'reason', 'The provider has no usable name (a placeholder or page markup).'); end if;
  v_asof := coalesce(reg.checked_at, v_ev.captured_at);
  -- facts: each is a field of the verified record, with where it came from
  v_facts := v_facts || jsonb_build_array(jsonb_build_object('key', 'register', 'field', 'catalogue.provider_registrations', 'value', reg.registration_scheme || ' ' || reg.registration_code || ' ' || reg.status,
      'source', 'register', 'registration_id', reg.id, 'evidence_id', reg.evidence_id, 'source_url', v_ev.source_url, 'source_hash', coalesce(v_ev.content_hash, v_ev.id::text), 'as_at', v_asof));
  v_have := v_have || 'register'::text;
  if v_tcode is not null and v_tcode <> 'other' and nullif(btrim(v_type), '') is not null then
    v_facts := v_facts || jsonb_build_array(jsonb_build_object('key', 'type', 'field', 'ref.provider_types.name', 'value', v_type, 'source', 'provider_record', 'provider_id', p.id, 'as_at', coalesce(p.provider_type_set_at, p.updated_at)));
    v_have := v_have || 'type'::text;
  end if;
  v_city := nullif(btrim(p.primary_city), '');
  if v_city is not null and v_city = upper(v_city) and length(v_city) >= security.pipeline_num_v1('pdesc.city_min_chars', 4)::int then v_city := initcap(lower(v_city)); end if;
  if v_city is not null and security.pdesc_machine_text_check_v1(p.id, v_city) is not null then v_city := null; end if; -- a "campus" or other refused word is not a city
  if v_city is not null and (position('?' in v_city) > 0 or position(chr(65533) in v_city) > 0) then v_city := null; end if; -- a city that lost a character ("Whang?rei") is not stated as a place
  v_loc := nullif(concat_ws(', ', v_city, nullif(btrim(v_region), ''), nullif(btrim(v_country), '')), '');
  if (v_city is not null or nullif(btrim(v_region), '') is not null) and v_loc is not null then
    v_facts := v_facts || jsonb_build_array(jsonb_build_object('key', 'location', 'field', 'catalogue.providers.primary_city, subdivision, country', 'value', v_loc, 'source', 'provider_record', 'provider_id', p.id, 'as_at', p.updated_at));
    v_have := v_have || 'location'::text;
  end if;
  select coalesce(array_agg(x.name order by x.name), '{}') into v_levels from (select distinct sl.name from catalogue.courses c join ref.study_levels sl on sl.id = c.study_level_id
     where c.provider_id = p.id and c.lifecycle_status = 'active' and nullif(btrim(sl.name), '') is not null order by sl.name limit v_max) x;
  select coalesce(array_agg(x.name order by x.name), '{}') into v_fields from (select distinct f.name from catalogue.courses c join ref.fields_of_study f on f.id = c.primary_field_id
     where c.provider_id = p.id and c.lifecycle_status = 'active' and nullif(btrim(f.name), '') is not null order by f.name limit v_max) x;
  if coalesce(array_length(v_levels, 1), 0) > 0 then
    v_facts := v_facts || jsonb_build_array(jsonb_build_object('key', 'levels', 'field', 'catalogue.courses.study_level_id (active courses)', 'value', to_jsonb(v_levels), 'source', 'catalogue', 'provider_id', p.id, 'as_at', now()));
    v_have := v_have || 'levels'::text;
  end if;
  if coalesce(array_length(v_fields, 1), 0) > 0 then
    v_facts := v_facts || jsonb_build_array(jsonb_build_object('key', 'fields', 'field', 'catalogue.courses.primary_field_id (active courses)', 'value', to_jsonb(v_fields), 'source', 'catalogue', 'provider_id', p.id, 'as_at', now()));
    v_have := v_have || 'fields'::text;
  end if;
  if coalesce(array_length(v_have, 1), 0) < v_min then
    return jsonb_build_object('ok', false, 'rule', 'insufficient_verified_facts', 'facts_held', to_jsonb(v_have), 'facts_needed', v_min,
      'reason', format('%s verified fact(s) held (%s); %s needed for a useful, truthful profile.', coalesce(array_length(v_have, 1), 0), array_to_string(v_have, ', '), v_min));
  end if;
  -- sentences: wording only joins the verified facts
  v_art := case when v_type is null or lower(v_type) ~ '^(uni|use|eu|one|ubi)' then 'a' when lower(left(v_type, 1)) in ('a', 'e', 'i', 'o', 'u') then 'an' else 'a' end; -- "a university", "an agricultural college"
  s1 := case when 'type' = any (v_have) then v_name || ' is ' || v_art || ' ' || case when v_type ~ '^[A-Z][a-z]' then lower(left(v_type, 1)) || substr(v_type, 2) else v_type end || coalesce(' in ' || v_loc, '') || '.'
             else v_name || coalesce(' is located in ' || v_loc, ' is listed in this catalogue') || '.' end;
  s2 := replace(replace(tpl, '{name}', 'It'), '{code}', reg.registration_code);
  -- the second sentence reads "It is listed ..." / "It appears ..."; the template starts with the name, so the pronoun replaces it
  s3 := case when 'levels' = any (v_have) and 'fields' = any (v_have) then 'Its listed courses are at ' || regexp_replace(array_to_string(v_levels, ', '), ', ([^,]*)$', ' and \1') || ' levels, in fields including ' || regexp_replace(array_to_string(v_fields, ', '), ', ([^,]*)$', ' and \1') || '.'
             when 'levels' = any (v_have) then 'Its listed courses are at ' || regexp_replace(array_to_string(v_levels, ', '), ', ([^,]*)$', ' and \1') || ' levels.'
             when 'fields' = any (v_have) then 'Its listed courses are in fields including ' || regexp_replace(array_to_string(v_fields, ', '), ', ([^,]*)$', ' and \1') || '.' end;
  v_sent := jsonb_build_array(jsonb_build_object('text', s1, 'facts', (select coalesce(jsonb_agg(k), '[]'::jsonb) from unnest(array['type', 'location']) k where k = any (v_have))),
                              jsonb_build_object('text', s2, 'facts', jsonb_build_array('register')));
  if s3 is not null then v_sent := v_sent || jsonb_build_array(jsonb_build_object('text', s3, 'facts', (select coalesce(jsonb_agg(k), '[]'::jsonb) from unnest(array['levels', 'fields']) k where k = any (v_have)))); end if;
  v_text := concat_ws(' ', s1, s2, s3);
  if length(v_text) < security.pipeline_num_v1('pdesc.min_chars', 150) or jsonb_array_length(v_sent) < security.pipeline_num_v1('pdesc.min_sentences', 2) or jsonb_array_length(v_sent) > security.pipeline_num_v1('pdesc.max_sentences', 5) then
    return jsonb_build_object('ok', false, 'rule', 'insufficient_verified_facts', 'reason', 'The profile (' || length(v_text) || ' characters, ' || jsonb_array_length(v_sent) || ' sentences) is outside the description limits (pdesc.min_chars, min_sentences, max_sentences).'); end if;
  if length(v_text) > security.pipeline_num_v1('pdesc.max_chars', 900) then
    return jsonb_build_object('ok', false, 'rule', 'insufficient_verified_facts', 'reason', 'The profile is longer than the description limit (' || length(v_text) || ' characters).'); end if;
  return jsonb_build_object('ok', true, 'rule', 'registry_factual', 'tier', 'registry_factual', 'text', v_text, 'sentences', v_sent, 'facts', v_facts, 'evidence_id', reg.evidence_id, 'registration_id', reg.id,
    'source_url', v_ev.source_url, 'source_hash', coalesce(v_ev.content_hash, v_ev.id::text), 'captured_at', v_ev.captured_at, 'codes', jsonb_build_array(s2, reg.registration_code) || to_jsonb(coalesce(v_levels, '{}'::text[])) || to_jsonb(coalesce(v_fields, '{}'::text[])), 'profile_version', 'registry-profile-v1');
end $_$;


ALTER FUNCTION "security"."provider_description_registry_profile_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_registry_profile_v1"("p_provider" "uuid") IS 'CF-247 F-PDESC tier 4 (registry_factual): a short factual profile built only from the provider record, its active register listing (stored evidence) and its active catalogue courses, each sentence tied to its facts; or insufficient_verified_facts. The exact level and field labels it prints are returned with the register wording in codes (they are reference-table values, not claims); a city that lost a character is not stated. Deterministic, read only, no AI and no page read.';



CREATE OR REPLACE FUNCTION "security"."provider_description_registry_tier_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare r record; v_prof jsonb; v_gate jsonb; v_read uuid; v_item uuid; v_res jsonb; v_ok int := 0; v_held int := 0; v_err int := 0; v_msg text; v_rule text; v_fp text := security.pdesc_text_rule_fingerprint_v1();
        v_rules jsonb := coalesce(security.toolset_setting('pipeline', 'pdesc.registry_after_rules'), '[]'::jsonb); v_sys uuid := 'c0ffee00-0000-4000-8000-000000000150'; -- fixed: the system automation account (Decision 263)
begin
  if security.pipeline_num_v1('pdesc.enabled', 0) < 1 or security.pipeline_num_v1('pdesc.machine_admit_on', 0) < 1 or security.pipeline_num_v1('pdesc.registry_factual_on', 0) < 1 then return jsonb_build_object('on', false); end if;
  for r in
    with act as (select pz.country_id, count(*) n from pipeline.provider_description_machine_admissions z join catalogue.providers pz on pz.id = z.provider_id
                  where z.created_at > now() - make_interval(hours => security.pipeline_num_v1('pdesc.rate_window_hours', 3)::int) group by pz.country_id)
    select p.id from catalogue.providers p left join act on act.country_id = p.country_id
      left join lateral (select x.state, x.rule, x.updated_at, x.checks from pipeline.provider_description_reads x where x.provider_id = p.id order by x.created_at desc, x.id desc limit 1) lr on true
     where p.lifecycle_status = 'active' and p.publication_status = 'published' and nullif(btrim(p.description), '') is null and security.provider_description_scope_v1(p.id)
       and not exists (select 1 from pipeline.provider_description_reads o where o.provider_id = p.id and o.state in ('queued', 'reading', 'proposed'))
       and not exists (select 1 from pipeline.provider_description_reads h where h.provider_id = p.id and h.state = 'held' and h.checks->>'tier' = 'registry_factual' and coalesce(case when (h.checks->>'facts_needed') ~ '^[0-9]+$' then (h.checks->>'facts_needed')::numeric end, 0) <= security.pipeline_num_v1('pdesc.registry_min_facts', 3) and not (h.rule like 'machine_declined_machine_text%' and h.checks->>'text_rule' is distinct from v_fp) and h.updated_at > now() - make_interval(days => security.pipeline_num_v1('pdesc.recheck_days', 180)::int))
       and ((lr.state = 'held' and (v_rules ? lr.rule or (lr.rule like 'machine_declined_machine_text%' and lr.checks->>'tier' = 'registry_factual' and lr.checks->>'text_rule' is distinct from v_fp) or (lr.rule = 'insufficient_verified_facts' and lr.checks->>'tier' = 'registry_factual' and (lr.checks->>'facts_needed') ~ '^[0-9]+$' and (lr.checks->>'facts_needed')::numeric > security.pipeline_num_v1('pdesc.registry_min_facts', 3)))) or lr.state = 'dead_letter'
            or (lr.state is null and nullif(btrim(p.website), '') is null and security.provider_description_stored_v1(p.id) is null))
       and security.provider_description_machine_blocked_v1(p.id) is null
     order by coalesce(act.n, 0), p.id
     limit security.pipeline_num_v1('pdesc.registry_per_run', 25)::int loop
    begin
      v_prof := security.provider_description_registry_profile_v1(r.id);
      if not coalesce((v_prof->>'ok')::boolean, false) then
        insert into pipeline.provider_description_reads (provider_id, state, rule, reason, worker, prompt_version, checks, tries)
        values (r.id, 'held', 'insufficient_verified_facts', left(v_prof->>'reason', 400), 'registry-factual-v1', 'registry-profile-v1', jsonb_build_object('tier', 'registry_factual', 'facts_held', v_prof->'facts_held', 'facts_needed', v_prof->'facts_needed', 'tier_hold', true), 0); -- fixed: display width of the stored reason text
        v_held := v_held + 1; continue;
      end if;
      v_gate := security.provider_description_machine_gate_v1(r.id, v_prof->>'text', jsonb_build_object('tier', 'registry_factual', 'codes', v_prof->'codes'));
      if not (v_gate->>'ok')::boolean then
        insert into pipeline.provider_description_reads (provider_id, state, rule, reason, worker, prompt_version, checks, tries)
        values (r.id, 'held', 'machine_declined_' || (v_gate->>'rule'), left(v_gate->>'reason', 400), 'registry-factual-v1', 'registry-profile-v1', jsonb_build_object('tier', 'registry_factual', 'tier_hold', true, 'text_rule', v_fp), 0); -- fixed: display width of the stored reason text
        v_held := v_held + 1; continue;
      end if;
      insert into pipeline.provider_description_reads (provider_id, state, rule, source_url, evidence_id, content_hash, source_captured_at, worker, prompt_version, proposal, checks, tries, last_verified_at)
      values (r.id, 'proposed', 'registry_factual', v_prof->>'source_url', (v_prof->>'evidence_id')::uuid, v_prof->>'source_hash', (v_prof->>'captured_at')::timestamptz, 'registry-factual-v1', 'registry-profile-v1',
              jsonb_build_object('description', v_prof->>'text', 'facts', v_prof->'facts', 'tier', 'registry_factual'),
              jsonb_build_object('tier', 'registry_factual', 'facts', v_prof->'facts', 'profile_version', 'registry-profile-v1', 'identity_snapshot', security.provider_description_identity_snapshot_v1(r.id)), 0, now())
      returning id into v_read;
      insert into pipeline.layer4_review_items (entity_type, entity_id, field_code, evidence_id, before_value, proposed_value, layer2_state, layer3_state, status, escalation_reason, change_control_ref)
      values ('provider', r.id, 'provider_description', (v_prof->>'evidence_id')::uuid, jsonb_build_object('description', null),
              jsonb_build_object('description', v_prof->>'text', 'tier', 'registry_factual', 'facts', v_prof->'facts', 'sentences_facts', v_prof->'sentences', 'source_url', v_prof->>'source_url', 'evidence_id', v_prof->>'evidence_id', 'captured_at', v_prof->>'captured_at', 'read_id', v_read),
              jsonb_build_object('read_via', null, 'content_hash', v_prof->>'source_hash', 'source_url', v_prof->>'source_url', 'tier', 'registry_factual'),
              jsonb_build_object('worker', 'registry-factual-v1', 'prompt_version', 'registry-profile-v1', 'rule', 'registry_factual'), 'pending',
              'Register-fact profile (tier 4): built only from the verified register listing, the provider record and the active catalogue courses, no page read and no AI. Admitted by the machine rule, not by a person.',
              'CF-247 F-PDESC (Platform Admin decision 9 Nov 2026)')
      returning id into v_item;
      update pipeline.provider_description_reads set review_item_id = v_item where id = v_read;
      v_res := security.provider_description_machine_admit_v1(v_item);
      if not (v_res->>'ok')::boolean then raise exception 'machine_declined:%', v_res->>'rule'; end if;
      v_ok := v_ok + 1;
    exception when others then
      get stacked diagnostics v_msg = message_text;
      begin
        insert into pipeline.provider_description_reads (provider_id, state, rule, reason, worker, prompt_version, checks, tries)
        values (r.id, 'held', case when v_msg like 'machine_declined:%' then 'machine_declined_' || substr(v_msg, 17) else 'registry_tier_error' end, left(v_msg, 400), 'registry-factual-v1', 'registry-profile-v1', -- fixed: display width of the stored reason text
                jsonb_build_object('tier', 'registry_factual', 'tier_hold', true, 'text_rule', v_fp), 0);
      exception when others then null;
      end;
      v_err := v_err + 1;
    end;
  end loop;
  return jsonb_build_object('on', true, 'admitted', v_ok, 'held', v_held, 'errors', v_err);
end $_$;


ALTER FUNCTION "security"."provider_description_registry_tier_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_registry_tier_v1"() IS 'CF-247 F-PDESC tier 4 (registry_factual): runs the register-fact profile for providers with no page to read; a hold made at a higher facts requirement, or a machine-text hold made under another text rule (security.pdesc_text_rule_fingerprint_v1), is looked at again; every profile still passes the machine gate and the machine admission.';



CREATE OR REPLACE FUNCTION "security"."provider_description_resume_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_n int:=0; v_free int;
begin
 if security.pipeline_num_v1('pdesc.enabled',0)<1 then return 0; end if;
 if not pg_try_advisory_xact_lock(hashtext('cf247 provider description capacity')) then return 0; end if;
 select greatest(0,security.pipeline_num_v1('pdesc.pending_max',10)::int-count(*)::int) into v_free from pipeline.layer4_review_items i where i.field_code='provider_description' and i.status='pending';
 for r in select * from pipeline.provider_description_reads x where ((x.state='held' and x.rule='review_full') or (x.state='queued' and x.rule='retried' and x.proposal->>'description' is not null)) and x.evidence_id is not null order by x.updated_at,x.id limit v_free for update skip locked loop
  update pipeline.provider_description_reads set state='reading' where id=r.id;
  perform public.svc_provider_description_record(jsonb_build_array(jsonb_build_object('item_id',r.id,'stored_evidence_id',r.evidence_id,'answer',jsonb_build_object('about_page',true,'sentences',r.proposal->'sentences'))));
  v_n:=v_n+1;
 end loop;
 return v_n;
end $$;


ALTER FUNCTION "security"."provider_description_resume_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_description_review_trg_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  update pipeline.provider_description_reads set
         state = case when new.status = 'rejected' then 'rejected' when new.status in ('more_evidence', 'returned_layer2', 'returned_layer3') then 'held' when new.status = 'superseded' then 'superseded' else state end,
         rule = case when new.status in ('approved', 'edited_approved') then rule else 'layer4_' || new.status end,
         updated_at = now()
   where review_item_id = new.id and state = 'proposed' and new.status not in ('approved', 'edited_approved');
  return new;
end $$;


ALTER FUNCTION "security"."provider_description_review_trg_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_description_run_result_v1"("p_cohort" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_rows jsonb; c pipeline.provider_description_cohorts%rowtype;
begin
 select * into c from pipeline.provider_description_cohorts where id=p_cohort;
 if c.id is null then raise exception 'unknown cohort' using errcode='22023'; end if;
 select coalesce(jsonb_agg(m.snapshot || case when m.snapshot->'diagnosis'->>'request_id' is not null then jsonb_build_object('diagnosis',(m.snapshot->'diagnosis')||coalesce((select jsonb_build_object('request_status',q.state,'ai_used',q.state='answered','explanation',coalesce(q.answer->>'reasoning',m.snapshot->'diagnosis'->>'explanation'),'answer',q.answer,'model',q.model,'cost_usd',q.cost_usd,'answered_at',q.answered_at) from pipeline.ops_ai_diagnosis_requests q where q.id=(m.snapshot->'diagnosis'->>'request_id')::bigint),'{}'::jsonb)) else '{}'::jsonb end || jsonb_build_object('read_id',r.id,'approval_status',case when r.state='proposed' then 'pending human Layer 4 decision' when r.state='admitted' and lineage.approved_item_id is not null then 'authorised admission' when r.state='verified' and lineage.approved_item_id is not null then 'previously approved; source reverified' when r.state is null then m.snapshot->>'approval_status' else r.state end,'state',coalesce(r.state,m.snapshot->>'state'),'rule',r.rule,'reason',r.reason,
 'proposed_description',r.proposal->>'description','sentences',r.proposal->'sentences','checks',r.checks,'review_item_id',coalesce(r.review_item_id,lineage.approved_item_id),'review_created_at',(select li.created_at from pipeline.layer4_review_items li where li.id=coalesce(r.review_item_id,lineage.approved_item_id)),'approval_lineage_item_id',lineage.approved_item_id,'review_item_created_this_read',r.review_item_id is not null,'existing_approved_verified',r.state='verified' and lineage.approved_item_id is not null,
 'source_url',coalesce(r.source_url,m.snapshot->>'source_url'),'evidence_id',coalesce(r.evidence_id,m.evidence_id),'source_captured_at',coalesce(to_jsonb(r.source_captured_at),m.snapshot->'source_captured_at'),
 'source_hash',coalesce(r.content_hash,m.snapshot->>'source_hash'),'evidence_version',coalesce(r.content_hash,m.snapshot->>'source_hash'),'model',coalesce(r.model,m.snapshot->>'model'),'prompt_version',r.prompt_version,'worker',r.worker,'ai_calls',r.ai_calls,'reserved_usd',r.reserved_usd,'cost_uncertain',coalesce(r.reserved_usd,0)>0,'cost_usd',r.cost_usd,'tries',r.tries,'read_completed',r.read_via is not null and r.content_hash is not null,
 'current_description',p.description,'admitted',r.state='admitted','published_at',r.published_at,'zoho_published_at',r.zoho_published_at,'consumer_checked_at',r.consumer_checked_at,'consumer_checks',r.consumer_checks,'last_verified_at',r.last_verified_at,
 'publication',jsonb_build_object('catalogue',jsonb_build_object('status',case when (r.state in ('admitted','verified') and lineage.approved_item_id is not null) and p.description=r.proposal->>'description' then 'verified' when (r.state in ('admitted','verified') and lineage.approved_item_id is not null) then 'mismatch' else 'awaiting_admission' end),'website',jsonb_build_object('status',case when (r.state in ('admitted','verified') and lineage.approved_item_id is not null) and web.body->'item'->>'description'=p.description and web.body->'item'->>'provider_id'=p.stable_key and p.description=r.proposal->>'description' then 'verified' when (r.state in ('admitted','verified') and lineage.approved_item_id is not null) then 'mismatch' else 'awaiting_admission' end),'zoho',jsonb_build_object('status',case when (r.state in ('admitted','verified') and lineage.approved_item_id is not null) and zoho.body->'item'->>'description'=p.description and zoho.body->'item'->>'provider_id'=p.stable_key and p.description=r.proposal->>'description' then 'verified' when (r.state in ('admitted','verified') and lineage.approved_item_id is not null) and zoho.body?'error' then 'error' when (r.state in ('admitted','verified') and lineage.approved_item_id is not null) then 'mismatch' else 'awaiting_admission' end,'description',zoho.body->'item'->>'description','read_at',now(),'api_version',zoho.body->>'api_version','error',zoho.body->'error'),'as_at',now()),
 'website',jsonb_build_object('status',case when r.state not in ('admitted','verified') or r.state is null or lineage.approved_item_id is null then 'awaiting_admission' when web.body->'item'->>'description'=p.description and web.body->'item'->>'provider_id'=p.stable_key and p.description=r.proposal->>'description' then 'verified' else 'mismatch' end,'description',web.body->'item'->>'description','read_at',now()),
 'zoho',jsonb_build_object('status',case when r.state not in ('admitted','verified') or r.state is null or lineage.approved_item_id is null then 'awaiting_admission' when zoho.body->'item'->>'description'=p.description and zoho.body->'item'->>'provider_id'=p.stable_key and p.description=r.proposal->>'description' then 'verified' when zoho.body?'error' then 'error' else 'mismatch' end,'description',zoho.body->'item'->>'description','read_at',now(),'api_version',zoho.body->>'api_version','error',zoho.body->'error')) order by m.pick),'[]') into v_rows
 from pipeline.provider_description_cohort_members m join catalogue.providers p on p.id=m.provider_id
 left join pipeline.provider_description_reads r on r.id=m.read_id
 left join lateral(select security.provider_description_approved_lineage_v1(p.id,p.description) approved_item_id) lineage on true
 left join lateral(select security.provider_description_consumer_read_v1('website',p.stable_key) body where (r.state in ('admitted','verified') and lineage.approved_item_id is not null)) web on true
 left join lateral(select security.provider_description_consumer_read_v1('zoho',p.stable_key) body where (r.state in ('admitted','verified') and lineage.approved_item_id is not null)) zoho on true
 where m.cohort_id=c.id;
 return jsonb_build_object('cohort_id',c.id,'state',c.state,'can_run',c.state='prepared' and c.run_id is null and jsonb_array_length(v_rows)<=least(security.pipeline_num_v1('pdesc.queue_per_run',10),security.pipeline_num_v1('pdesc.pending_max',10),security.pipeline_num_v1('run_now.pilot_cap',20))::int,'reason_code',case when c.state='prepared' and c.run_id is null and jsonb_array_length(v_rows)>least(security.pipeline_num_v1('pdesc.queue_per_run',10),security.pipeline_num_v1('pdesc.pending_max',10),security.pipeline_num_v1('run_now.pilot_cap',20))::int then 'current_cap_changed' end,'selection',c.selection,'scope',c.selection,'requested_by',c.requested_by,'reason',c.reason,'created_at',c.created_at,'verified_at',c.verified_at,'last_verification',c.verification,'run_id',c.run_id,
 'providers',v_rows,'as_at',now(),'totals',jsonb_build_object('selected',jsonb_array_length(v_rows),
 'evidence_read',(select count(*) from jsonb_array_elements(v_rows) x where coalesce((x->>'read_completed')::boolean,false)),
 'proposed',(select count(*) from jsonb_array_elements(v_rows) x where x->>'state' in ('proposed','admitted','rejected')),
 'validation_failed',(select count(*) from jsonb_array_elements(v_rows) x where x->>'state' in ('held','dead_letter')),
 'layer4_created',(select count(*) from jsonb_array_elements(v_rows) x where coalesce((x->>'review_item_created_this_read')::boolean,false)),
 'human_decisions_required',(select count(*) from jsonb_array_elements(v_rows) x where x->>'state'='proposed'),
 'verified_existing',(select count(*) from jsonb_array_elements(v_rows) x where coalesce((x->>'existing_approved_verified')::boolean,false)),'admitted',(select count(*) from jsonb_array_elements(v_rows) x where x->>'state'='admitted'),
 'website_verified',(select count(*) from jsonb_array_elements(v_rows) x where x->'website'->>'status'='verified'),
 'cost_usd',(select coalesce(sum((x->>'cost_usd')::numeric),0) from jsonb_array_elements(v_rows) x),'reserved_usd',(select coalesce(sum((x->>'reserved_usd')::numeric),0) from jsonb_array_elements(v_rows) x),'actual_ai_calls',(select coalesce(sum((x->>'ai_calls')::int),0) from jsonb_array_elements(v_rows) x),
 'retries',(select count(*) from jsonb_array_elements(v_rows) x where (x->>'tries')::int>1)),
 'zoho_verified',(select count(*) from jsonb_array_elements(v_rows) x where x->'zoho'->>'status'='verified'),'runs',coalesce((select jsonb_agg(jsonb_build_object('run_id',j.id,'state',j.state,'outcome',j.outcome,'created_at',j.created_at,'started_at',j.started_at,'finished_at',j.finished_at,'result',j.result)) from pipeline.admin_jobs j where j.id=c.run_id),'[]'));
end $$;


ALTER FUNCTION "security"."provider_description_run_result_v1"("p_cohort" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_description_scope_v1"("p_provider" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1 from catalogue.providers p join ref.countries k on k.id = p.country_id left join ref.provider_types t on t.id = p.provider_type_id
     where p.id = p_provider and p.lifecycle_status = 'active'
       and coalesce(security.toolset_setting('pipeline', 'pdesc.countries'), '["AU"]'::jsonb) ? k.iso_alpha2::text
       and security.pdesc_type_in_scope_v1(t.code)
       and (jsonb_array_length(coalesce(security.toolset_setting('pipeline', 'pdesc.provider_keys'), '[]'::jsonb)) = 0
            or coalesce(security.toolset_setting('pipeline', 'pdesc.provider_keys'), '[]'::jsonb) ? lower(p.stable_key)
            or coalesce(security.toolset_setting('pipeline', 'pdesc.provider_keys'), '[]'::jsonb) ? p.stable_key))
$$;


ALTER FUNCTION "security"."provider_description_scope_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_scope_v1"("p_provider" "uuid") IS 'CF-247 P1 provider descriptions: the provider is in the reader''s scope (active; country in pdesc.countries; type in pdesc.provider_types; in pdesc.provider_keys when that list is not empty).';



CREATE OR REPLACE FUNCTION "security"."provider_description_selection_multi_v1"("p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ids uuid[]; v_cap int := security.provider_description_cohort_cap_v1(); v_fill text := coalesce(nullif(p_args->>'fill_mode', ''), 'missing'); v_id uuid;
  v_rows jsonb := '[]'::jsonb; v_one jsonb; v_f record; v_name text;
  -- the refresh of a basic profile is a Platform Admin policy switch (pdesc.registry_upgrade_on with machine admission); read here, never created here
  v_up_on boolean := security.pipeline_num_v1('pdesc.registry_upgrade_on', 0) >= 1 and security.pipeline_num_v1('pdesc.machine_admit_on', 0) >= 1;
begin
  if jsonb_typeof(p_args->'provider_ids') is distinct from 'array' then return security.provider_description_selection_v1(p_args); end if;
  select coalesce(array_agg(distinct e::uuid), array[]::uuid[]) into v_ids from jsonb_array_elements_text(p_args->'provider_ids') e;
  if cardinality(v_ids) < 1 or cardinality(v_ids) > v_cap then raise exception 'cohort size must be between 1 and %', v_cap using errcode = '22023'; end if;
  if v_fill not in ('missing', 'upgrade_basic') then raise exception 'unsupported fill mode' using errcode = '22023'; end if;
  for v_id in select unnest(v_ids) loop
    select f.description_filled, f.admission_state, f.source_tier into v_f from security.provider_catalogue_facts_v1(array[v_id], false) f;
    select coalesce(pp.display_name, pp.canonical_name) into v_name from catalogue.providers pp where pp.id = v_id;
    if v_name is null then
      v_rows := v_rows || jsonb_build_array(jsonb_build_object('provider_id', v_id, 'provider', null, 'name', null, 'eligible', false, 'eligibility_reason', 'unknown_provider', 'state', 'missing'));
    elsif exists (select 1 from pipeline.manual_locks l where l.entity = 'provider' and l.entity_id = v_id and l.field in ('description', 'p_description', 'all')) then
      v_rows := v_rows || jsonb_build_array(jsonb_build_object('provider_id', v_id, 'provider', v_name, 'name', v_name, 'eligible', false, 'eligibility_reason', 'manual_lock', 'state', case when coalesce(v_f.description_filled, false) then 'admitted' else 'missing' end));
    elsif v_fill = 'missing' and coalesce(v_f.description_filled, false) then
      v_rows := v_rows || jsonb_build_array(jsonb_build_object('provider_id', v_id, 'provider', v_name, 'name', v_name, 'eligible', false, 'eligibility_reason', 'description_already_present', 'state', 'admitted'));
    elsif v_fill = 'upgrade_basic' and not (coalesce(v_f.description_filled, false) and v_f.admission_state = 'admitted' and v_f.source_tier = 'registry_factual') then
      v_rows := v_rows || jsonb_build_array(jsonb_build_object('provider_id', v_id, 'provider', v_name, 'name', v_name, 'eligible', false, 'eligibility_reason', 'not_a_basic_registry_profile', 'state', case when coalesce(v_f.description_filled, false) then 'admitted' else 'missing' end));
    elsif v_fill = 'upgrade_basic' and not v_up_on then
      v_rows := v_rows || jsonb_build_array(jsonb_build_object('provider_id', v_id, 'provider', v_name, 'name', v_name, 'eligible', false, 'eligibility_reason', 'upgrade_switched_off', 'state', 'admitted'));
    else
      v_one := security.provider_description_selection_v1((p_args - 'provider_ids' - 'fill_mode') || jsonb_build_object('provider_id', v_id, 'size', 1,
                 'description_state', case when v_fill = 'upgrade_basic' then 'stale' else 'missing' end, 'upgrade', v_fill = 'upgrade_basic'));
      if jsonb_array_length(coalesce(v_one->'providers', '[]'::jsonb)) = 0 then
        v_rows := v_rows || jsonb_build_array(jsonb_build_object('provider_id', v_id, 'provider', v_name, 'name', v_name, 'eligible', false, 'eligibility_reason', 'not_selected_by_governed_policy', 'state', 'missing'));
      else
        v_rows := v_rows || (v_one->'providers');
      end if;
    end if;
  end loop;
  return jsonb_build_object('providers', v_rows, 'selected', (select count(*) from jsonb_array_elements(v_rows) x where (x->>'eligible')::boolean),
    'eligible', (select count(*) from jsonb_array_elements(v_rows) x where (x->>'eligible')::boolean), 'bounded', true, 'size', cardinality(v_ids), 'as_at', now(), 'fill_mode', v_fill,
    'exclusions', (select coalesce(jsonb_agg(jsonb_build_object('provider_id', x->>'provider_id', 'provider', x->>'provider', 'reason', x->>'eligibility_reason')), '[]'::jsonb) from jsonb_array_elements(v_rows) x where not (x->>'eligible')::boolean));
end
$$;


ALTER FUNCTION "security"."provider_description_selection_multi_v1"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_description_selection_v1"("p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_size int := coalesce((p_args->>'size')::int,security.pipeline_num_v1('batch.provider_description',3)::int);
 v_max int := case when security.pipeline_num_v1('pdesc.machine_admit_on',0)>=1 then security.pipeline_num_v1('pdesc.queue_cap',60)::int else least(security.pipeline_num_v1('pdesc.queue_per_run',10),security.pipeline_num_v1('pdesc.pending_max',10),security.pipeline_num_v1('run_now.pilot_cap',20))::int end;
 v_cc text := upper(nullif(btrim(p_args->>'country'),'')); v_type text := nullif(btrim(coalesce(p_args->>'provider_type',p_args->>'type')),'');
 v_provider uuid := nullif(p_args->>'provider_id','')::uuid; v_filter text := coalesce(nullif(coalesce(p_args->>'description_state',p_args->>'filter'),''),'missing');
 v_mode text := coalesce(nullif(p_args->>'mode',''),'stored'); v_rows jsonb; v_scanned jsonb; v_pat text[]:=security.pdesc_about_like_patterns_v1(); v_cur text:=security.pdesc_reader_behaviour_v1(); v_idr jsonb:=coalesce(security.toolset_setting('pipeline','pdesc.identity_reeval_rules'),'[]'::jsonb);
 -- upgrade mode (pdesc.registry_upgrade_on, argument upgrade): the list is the providers that hold a register-fact profile, not the providers with no description
 v_upg boolean := security.pipeline_num_v1('pdesc.registry_upgrade_on',0)>=1 and security.pipeline_num_v1('pdesc.machine_admit_on',0)>=1 and coalesce((p_args->>'upgrade')::boolean,false);
 -- QA B2: with prefilter (automatic mode only; the default there for the missing-description list of every caller, and always for the reader) the stored page and identity are worked out for a bounded slice of the providers that can still be read, not for the whole catalogue
 v_pre boolean := security.pipeline_num_v1('pdesc.machine_admit_on',0)>=1 and coalesce((p_args->>'prefilter')::boolean,v_filter='missing' and v_provider is null);
 v_slice int := least(security.pipeline_num_v1('pdesc.scan_max',150)::int, greatest(coalesce((p_args->>'size')::int,security.pipeline_num_v1('batch.provider_description',3)::int),1)*security.pipeline_num_v1('pdesc.scan_factor',3)::int);
begin
 if v_size < 1 or v_size > v_max then raise exception 'cohort size must be between 1 and %',v_max using errcode='22023'; end if;
 if v_mode not in ('stored','approved') then raise exception 'unsupported processing mode' using errcode='22023'; end if;
 if v_mode='approved' and security.pipeline_num_v1('pdesc.acquire_direct',0)<1 then raise exception 'acquisition has not been authorised' using errcode='42501'; end if;
 if v_filter not in ('missing','stale','failed','all') then raise exception 'unsupported description selection' using errcode='22023'; end if;
 with pre as materialized (
  select q.id from (select p.id,coalesce(m.scanned_at,'-infinity'::timestamptz) sc,(select count(*) from catalogue.courses c where c.provider_id=p.id and c.lifecycle_status='active') ac,coalesce(p.display_name,p.canonical_name) nm
   from catalogue.providers p join ref.countries k on k.id=p.country_id left join ref.provider_types t on t.id=p.provider_type_id left join pipeline.provider_description_scan_marks m on m.provider_id=p.id
   where v_pre and (v_cc is null or k.iso_alpha2=v_cc) and (v_type is null or t.code=v_type) and (v_provider is null or p.id=v_provider)
    and security.provider_description_scope_v1(p.id) and case when v_upg then security.provider_description_basic_profile_v1(p.id) is not null else nullif(btrim(p.description),'') is null end and p.publication_status='published'
    and not exists(select 1 from pipeline.provider_description_reads x where x.provider_id=p.id and x.state in ('queued','reading','proposed'))
    and (not v_upg or ((nullif(btrim(p.website),'') is not null or security.provider_description_stored_candidate_v1(p.id,v_pat))))
    and (v_mode<>'stored' or security.provider_description_stored_candidate_v1(p.id,v_pat))
   order by sc,ac desc,nm limit v_slice) q
 ), candidates as materialized (
 select p.*,k.iso_alpha2::text cc,t.code typ,
  (select count(*) from catalogue.courses c where c.provider_id=p.id and c.lifecycle_status='active') active_course_count,
  security.provider_description_stored_v1(p.id) stored_id
 from catalogue.providers p join ref.countries k on k.id=p.country_id left join ref.provider_types t on t.id=p.provider_type_id
 where (v_cc is null or k.iso_alpha2=v_cc) and (v_type is null or t.code=v_type) and (v_provider is null or p.id=v_provider)
  -- Scope is governed by the existing policy. The UI selector can narrow it, never widen it.
  and security.provider_description_scope_v1(p.id)
  and (not v_pre or p.id in (select pre.id from pre))
 ), rows as (
 select p.*,r.id last_read_id,r.state read_state,r.rule read_rule,r.reason read_reason,r.proposal,r.checks,r.review_item_id,(select li.created_at from pipeline.layer4_review_items li where li.id=r.review_item_id) review_created_at,r.model,r.cost_usd,r.tries,r.updated_at read_updated_at,r.last_verified_at read_last_verified_at,
 a.source_url,a.id evidence_id,coalesce(a.captured_at,a.created_at) source_captured_at,coalesce(a.content_hash,a.id::text) source_hash,
 case
  when v_pre and security.provider_description_machine_blocked_v1(p.id) is not null then 'machine_'||(security.provider_description_machine_blocked_v1(p.id)->>'rule')
  when p.lifecycle_status<>'active' then 'provider_inactive'
  when p.publication_status<>'published' or exists(select 1 from security.provider_hidden_v1 h where h.provider_id=p.id) then 'provider_not_published'
  when exists(select 1 from pipeline.manual_locks l where l.entity='provider' and l.entity_id=p.id and l.field in ('description','p_description','all')) then 'manual_lock'
  when nullif(btrim(p.description),'') is not null and security.provider_description_approved_lineage_v1(p.id,p.description) is null then 'manual_description'
  when nullif(btrim(p.description),'') is not null and (select z.proposal->>'description' from pipeline.provider_description_reads z where z.provider_id=p.id and z.state in ('admitted','verified') order by coalesce(z.last_verified_at,z.updated_at) desc,z.id desc limit 1) is distinct from p.description then 'manual_description_changed'
  when r.state in ('queued','reading','proposed') then 'existing_work'
  when r.state='dead_letter' then 'dead_letter_requires_retry'
  when coalesce(r.reserved_usd,0)>0 then 'cost_reservation_uncertain'
  when r.state='held' and r.rule='review_full' then 'review_capacity_parked'
  when r.state='held' and r.rule in ('source_identity_proof_missing','ai_ceiling','ai_daily_guard','ai_refused','model_pricing_unavailable','invalid_model_pricing','unrecognised_pricing_component','ai_budget_refused','existing_cost_reservation_uncertain') then 'policy_retry_parked'
  when r.state in ('held','rejected') and r.content_hash is not null and r.content_hash=coalesce(a.content_hash,a.id::text) and not (r.state='held' and coalesce(v_idr ? r.rule, false) and coalesce(r.checks->'identity'->>'reader_behavior_version','') is distinct from coalesce(v_cur,'')) and not (r.state='held' and r.rule='recovery_knowledge_unchanged_failure' and coalesce(r.ai_calls,0)=0 and coalesce(r.reserved_usd,0)=0 and a.id is not null and r.content_hash=coalesce(a.content_hash,a.id::text) and coalesce((security.ops_learning_retry_check_v1('provider_description:official_about',p.id::text,security.provider_description_signature_v1(coalesce(a.content_hash,a.id::text),(select security.ai_route_v1('provider_description')->>'model'),coalesce(r.prompt_version,'provider-description-v2')))->>'allowed')::boolean,true) and not exists(select 1 from pipeline.provider_description_reads z where z.provider_id=p.id and z.state='rejected' and z.content_hash=coalesce(a.content_hash,a.id::text))) then 'unchanged_unsuitable_evidence'
  when r.state in ('held','rejected') and r.updated_at>now()-make_interval(days=>security.pipeline_num_v1('pdesc.recheck_days',180)::int)
   and not (r.updated_at<=now()-make_interval(mins=>security.pipeline_num_v1('pdesc.retry_minutes',360)::int) and a.id is not null
            and coalesce(a.content_hash,a.id::text) is distinct from r.content_hash
            and (r.state='held' or (r.source_url is not null and not coalesce((security.provider_description_page_v1(p.id,r.source_url)->>'ok')::boolean,true)))) and not (r.state='held' and coalesce(v_idr ? r.rule, false) and coalesce(r.checks->'identity'->>'reader_behavior_version','') is distinct from coalesce(v_cur,'')) and not (r.state='held' and coalesce(r.checks ? 'identity_hold',false) and coalesce((security.provider_description_identity_v1(p.id,coalesce(a.source_url,p.website))->>'ok')::boolean,false)) and not (r.state='held' and r.rule='recovery_knowledge_unchanged_failure' and coalesce(r.ai_calls,0)=0 and coalesce(r.reserved_usd,0)=0 and a.id is not null and r.content_hash=coalesce(a.content_hash,a.id::text) and coalesce((security.ops_learning_retry_check_v1('provider_description:official_about',p.id::text,security.provider_description_signature_v1(coalesce(a.content_hash,a.id::text),(select security.ai_route_v1('provider_description')->>'model'),coalesce(r.prompt_version,'provider-description-v2')))->>'allowed')::boolean,true) and not exists(select 1 from pipeline.provider_description_reads z where z.provider_id=p.id and z.state='rejected' and z.content_hash=coalesce(a.content_hash,a.id::text))) then 'retry_wait'
  when r.state in ('admitted','verified') and r.proposal->'sentences' is not null and a.id is not null
   and security.provider_description_validate_v1(p.id,r.source_url,r.source_captured_at,jsonb_build_object('about_page',true,'sentences',r.proposal->'sentences'))->>'outcome' not in ('propose','verified')
   then case when coalesce(a.content_hash,a.id::text) is distinct from r.content_hash then 'invalid_description' else 'invalid_description_unchanged_evidence' end
  when r.state in ('admitted','verified') and nullif(btrim(p.description),'') is not null and coalesce(r.last_verified_at,r.updated_at)>now()-make_interval(days=>security.pipeline_num_v1('pdesc.recheck_days',180)::int) and not (v_upg and security.provider_description_basic_profile_v1(p.id) is not null) then 'description_current'
  when a.id is not null and not (security.provider_description_identity_v1(p.id,a.source_url)->>'ok')::boolean then security.provider_description_identity_v1(p.id,a.source_url)->>'rule'
  when a.id is not null and not coalesce((security.ops_learning_retry_check_v1('provider_description:official_about',p.id::text,security.provider_description_signature_v1(coalesce(a.content_hash,a.id::text),(select security.ai_route_v1('provider_description')->>'model'),coalesce(r.prompt_version,'provider-description-v2')))->>'allowed')::boolean,true) and not (r.state='held' and coalesce(v_idr ? r.rule, false) and coalesce(r.checks->'identity'->>'reader_behavior_version','') is distinct from coalesce(v_cur,'')) then 'recovery_knowledge_unchanged_failure'
  when v_mode='stored' and a.id is null then 'no_verified_stored_source'
  when r.state in ('admitted','verified') and nullif(btrim(p.description),'') is null then 'description_lost'
  else 'eligible' end eligibility_reason
 from candidates p left join lateral(select x.* from pipeline.provider_description_reads x where x.provider_id=p.id order by x.created_at desc,x.id desc limit 1) r on true
 left join pipeline.evidence_artifacts a on a.id=p.stored_id
 ), shaped as (
 select jsonb_build_object('provider_id',rows.id,'provider',coalesce(display_name,canonical_name),'name',coalesce(display_name,canonical_name),'stable_key',stable_key,
 'registration',coalesce((select jsonb_agg(jsonb_build_object('registration_id',pr.id,'scheme',pr.registration_scheme,'code',pr.registration_code,'status',pr.status,'valid_to',pr.valid_to,'checked_at',pr.checked_at,'source_id',pr.source_id,'evidence_id',pr.evidence_id) order by pr.registration_scheme,pr.registration_code) from catalogue.provider_registrations pr where pr.provider_id=rows.id),'[]'::jsonb),'country',cc,'type',typ,'lifecycle_status',lifecycle_status,'publication_status',publication_status,
 'active_course_count',active_course_count,'current_description',description,'proposed_description',proposal->>'description','sentences',proposal->'sentences','checks',checks,
 'source_url',source_url,'evidence_id',evidence_id,'source_hash',source_hash,'source_captured_at',source_captured_at,'source_age_days',extract(epoch from (now()-source_captured_at))/86400,
 'evidence_version',source_hash,'approval_status',case when read_state='proposed' then 'pending' else read_state end,'manual_locked',eligibility_reason='manual_lock','last_read_id',last_read_id,'state',coalesce(read_state,'missing'),'rule',read_rule,'reason',read_reason,'review_item_id',review_item_id,'review_created_at',review_created_at,
 'model',coalesce(model,(select security.ai_route_v1('provider_description')->>'model')),'cost_usd',cost_usd,'tries',tries,
 'eligible',eligibility_reason in ('eligible','invalid_description','description_lost'),'eligibility_reason',eligibility_reason,'required_approval','Individual human Layer 4 decision','last_verified_at',read_last_verified_at) row,
 eligibility_reason,active_course_count,coalesce(display_name,canonical_name) nm
 from rows where v_filter='all' or (v_filter='missing' and nullif(btrim(description),'') is null)
 or (v_filter='stale' and nullif(btrim(description),'') is not null)
 or (v_filter='failed' and read_state in ('held','dead_letter','rejected'))
 ) select coalesce(jsonb_agg(row order by eligibility_reason in ('eligible','invalid_description','description_lost') desc,active_course_count desc,nm),'[]'::jsonb),(select coalesce(jsonb_agg(z.row->>'provider_id'),'[]'::jsonb) from shaped z where z.eligibility_reason not in ('eligible','invalid_description','description_lost')) into v_rows,v_scanned
 from (select * from shaped order by eligibility_reason in ('eligible','invalid_description','description_lost') desc,active_course_count desc,nm limit v_size) b;
 return jsonb_build_object('providers',v_rows,'selected',(select count(*) from jsonb_array_elements(v_rows) x where (x->>'eligible')::boolean),
 'eligible',(select count(*) from jsonb_array_elements(v_rows) x where (x->>'eligible')::boolean),'bounded',true,'size',v_size,'scanned',case when v_pre then v_scanned end,'as_at',now(),
 'exclusions',(select coalesce(jsonb_agg(jsonb_build_object('provider_id',x->>'provider_id','reason',x->>'eligibility_reason')),'[]') from jsonb_array_elements(v_rows) x where not (x->>'eligible')::boolean));
end $$;


ALTER FUNCTION "security"."provider_description_selection_v1"("p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_description_self_heal_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_n int := 0; v_q int := 0; v_p int := 0; v_err int := 0; v_out jsonb; v_tally jsonb := '{}'::jsonb; v_fc_used int; v_fc_ok boolean;
        v_pv text := security.provider_description_prompt_active_v1()->>'version'; v_max int := greatest(0, security.pipeline_num_v1('pdesc.self_heal_requeue_per_run', 20)::int);
begin
  if not pg_try_advisory_xact_lock(hashtext('cf247 provider description self heal')) then return jsonb_build_object('skipped', 'in_flight'); end if;
  if security.pipeline_num_v1('pdesc.enabled', 0) < 1 then return jsonb_build_object('enabled', false); end if;
  -- (a) answers held only for the model's flag: the stored sentences are recorded again (the read is leased now, exactly as the reader leases it)
  for r in select x.id, x.provider_id from pipeline.provider_description_reads x
            where x.state = 'held' and x.rule = 'not_stated' and x.evidence_id is not null
              and jsonb_array_length(coalesce(x.proposal->'sentences', '[]'::jsonb)) > 0
              and not coalesce(x.checks ? 'self_heal', false)
            order by x.updated_at desc
            limit greatest(0, security.pipeline_num_v1('pdesc.self_heal_per_run', 5)::int) loop
    begin
      if exists (select 1 from pipeline.provider_description_reads o where o.provider_id = r.provider_id and o.state in ('queued', 'reading', 'proposed')) then
        update pipeline.provider_description_reads x set checks = coalesce(x.checks, '{}'::jsonb) || jsonb_build_object('self_heal', jsonb_build_object('at', now(), 'skipped', 'open_read', 'release', '20261112010000'))
         where x.id = r.id;
        v_tally := v_tally || jsonb_build_object('skipped_open_read', coalesce((v_tally->>'skipped_open_read')::int, 0) + 1);
        continue;
      end if;
      update pipeline.provider_description_reads x set state = 'reading', leased_until = now() + interval '5 minutes', -- fixed: one record call
             checks = coalesce(x.checks, '{}'::jsonb) || jsonb_build_object('description_at_lease', (select p.description from catalogue.providers p where p.id = x.provider_id),
                       'identity_snapshot', security.provider_description_identity_snapshot_v1(x.provider_id),
                       'self_heal', jsonb_build_object('at', now(), 'from_rule', 'not_stated', 'release', '20261112010000'))
       where x.id = r.id;
      v_out := public.svc_provider_description_record(jsonb_build_array((select jsonb_build_object('item_id', x.id,
                 'answer', jsonb_build_object('about_page', false, 'sentences', x.proposal->'sentences'),
                 'model', x.model, 'prompt_version', x.prompt_version, 'worker', x.worker) from pipeline.provider_description_reads x where x.id = r.id)));
      v_tally := v_tally || coalesce((select jsonb_object_agg(k, coalesce((v_tally->>k)::int, 0) + coalesce((v_out->>k)::int, 0)) from jsonb_object_keys(coalesce(v_out, '{}'::jsonb)) k), '{}'::jsonb);
      v_n := v_n + 1;
    exception when others then
      v_err := v_err + 1;  -- the sub-transaction is rolled back; the read stays as it was and is offered again next run
    end;
  end loop;
  -- (b) reads that stopped only because the Firecrawl allowance was used up go back in the queue once the window allows Firecrawl again
  select coalesce(sum(x.firecrawl_reads), 0) into v_fc_used from pipeline.provider_description_reads x
   where x.updated_at > now() - make_interval(hours => security.pipeline_num_v1('pdesc.firecrawl_window_hours', 24)::int);
  v_fc_ok := security.pipeline_num_v1('pdesc.acquire_firecrawl', 0) >= 1 and v_fc_used < security.pipeline_num_v1('pdesc.firecrawl_reads_max', 0);
  if v_fc_ok then
    for r in select distinct on (x.provider_id) x.id, x.provider_id, x.updated_at from pipeline.provider_description_reads x
              where x.state = 'held' and x.reason ilike '%Firecrawl ceiling reached%'
                and not exists (select 1 from pipeline.provider_description_reads o where o.provider_id = x.provider_id and o.state in ('queued', 'reading', 'proposed'))
              order by x.provider_id, x.updated_at desc loop
      exit when v_q >= v_max;
      begin
        update pipeline.provider_description_reads x set state = 'queued', tries = 0, next_try_at = now(), leased_until = null, rule = null,
               reason = 'put back: the Firecrawl allowance renewed (provider-description-self-heal)', updated_at = now()
         where x.id = r.id and x.state = 'held';
        v_q := v_q + 1;
      exception when others then
        v_err := v_err + 1;
      end;
    end loop;
  end if;
  -- (c) 20261112010000: the latest read of a provider still without a description, held on an AI-answer check under an older prompt version, is read
  -- again once with the active prompt (the recovery memory counts the prompt version, so the same failure is never asked twice)
  if v_pv is not null then
    for r in select l.id from (select distinct on (x.provider_id) x.id, x.provider_id, x.state, x.rule, x.prompt_version, x.updated_at
                                 from pipeline.provider_description_reads x order by x.provider_id, x.created_at desc) l
              join catalogue.providers p on p.id = l.provider_id
             where l.state = 'held' and coalesce(l.prompt_version, '') is distinct from v_pv
               and coalesce(security.toolset_setting('pipeline', 'pdesc.prompt_reoffer_rules'), '[]'::jsonb) ? l.rule
               and (nullif(btrim(p.description), '') is null or security.provider_description_basic_profile_v1(p.id) is not null)
               and not exists (select 1 from pipeline.manual_locks k where k.entity = 'provider' and k.entity_id = p.id and k.field in ('description', 'p_description', 'all'))
               and not exists (select 1 from pipeline.provider_description_reads o where o.provider_id = l.provider_id and o.state in ('queued', 'reading', 'proposed'))
             order by l.updated_at desc loop
      exit when v_p >= v_max;
      begin
        update pipeline.provider_description_reads x set state = 'queued', tries = 0, next_try_at = now(), leased_until = null, rule = null,
               reason = 'put back: a new provider-description prompt (' || v_pv || ')', updated_at = now()
         where x.id = r.id and x.state = 'held';
        v_p := v_p + 1;
      exception when others then
        v_err := v_err + 1;
      end;
    end loop;
  end if;
  return jsonb_build_object('rechecked', v_n, 'outcomes', v_tally, 'requeued_firecrawl', v_q, 'requeued_prompt', v_p, 'skipped_error', v_err, 'firecrawl_used_window', v_fc_used, 'firecrawl_open', v_fc_ok, 'prompt_version', v_pv);
end $$;


ALTER FUNCTION "security"."provider_description_self_heal_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_self_heal_v1"() IS 'CF-247 F-PDESC (20261110250000, 20261110251000, 20261112010000): job provider-description-self-heal. Re-records held not_stated reads with stored sentences (no AI), requeues reads stopped by the Firecrawl allowance once it renews, and reads failed AI answers again once for a new prompt version.';



CREATE OR REPLACE FUNCTION "security"."provider_description_settle_abandoned_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_floor numeric := security.pipeline_num_v1('pdesc.read_cost_floor_usd', 0.003); v_avg numeric; v_est numeric;
        v_bound int := greatest(1, security.pipeline_num_v1('pdesc.queue_cap', 60)::int); v_n int := 0;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required' using errcode = '42501'; end if;
  perform pg_advisory_xact_lock(hashtext('cf247 provider description spend')); -- fixed: the lock the reservation takes, so a settlement and a new reservation never see each other half done
  -- the observed cost of a read, the same expression the lease uses (svc_provider_description_next): cost over the reads that made a call
  select coalesce(sum(x.cost_usd) / nullif(count(*) filter (where x.ai_calls > 0), 0), 0) into v_avg from pipeline.provider_description_reads x;
  v_est := greatest(v_floor, v_avg);
  with a as (
    -- abandoned: a reservation that nothing is working on (not reading, or reading with a lease that has run out); a live lease is a call in flight
    select r.id from pipeline.provider_description_reads r
     where r.reserved_usd > 0 and (r.state <> 'reading' or r.leased_until is null or r.leased_until < now())
     order by r.updated_at, r.id limit v_bound for update skip locked),
  u as (
    update pipeline.provider_description_reads r
       set cost_usd = r.cost_usd + least(r.reserved_usd, v_est), -- the trigger ai_spend_capture writes the ledger row for this increase
           ai_calls = r.ai_calls + 1,
           reserved_usd = 0,
           checks = coalesce(r.checks, '{}'::jsonb) || jsonb_build_object('reservation_settlement', jsonb_build_object('basis', 'abandoned_reservation_assumed_called', 'settled_usd', least(r.reserved_usd, v_est),
                      'reserved_usd', r.reserved_usd, 'floor_usd', v_floor, 'observed_average_usd', round(v_avg, 6), 'ai_calls_before', r.ai_calls, 'state_before', r.state, 'at', now())),
           state = case when r.state = 'reading' then 'held' else r.state end,
           rule = case when r.state = 'reading' then 'existing_cost_reservation_uncertain' else r.rule end,
           reason = case when r.state = 'reading' then 'A paid read was leased and its result never recorded; its AI cost was settled at the dearer of the set floor and the observed cost of a read, and the read is offered again.' else r.reason end,
           leased_until = case when r.state = 'reading' then null else r.leased_until end,
           updated_at = now()
      from a where r.id = a.id
    returning 1)
  select count(*) into v_n from u;
  return v_n;
end $$;


ALTER FUNCTION "security"."provider_description_settle_abandoned_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_settle_abandoned_v1"() IS 'CF-247 F-PDESC: settles AI reservations that nothing is working on (reserved_usd > 0 and the read is not reading, or its lease has run out) at the dearer of pdesc.read_cost_floor_usd and the observed cost of a read, never above the reservation: cost_usd rises (ai_spend_capture writes the ledger row), ai_calls rises by one, reserved_usd becomes 0, checks.reservation_settlement records it, and an expired reading read becomes held existing_cost_reservation_uncertain so the fire requeues it. At most pdesc.queue_cap reads a run; called by security.provider_description_fire_v1; idempotent.';



CREATE OR REPLACE FUNCTION "security"."provider_description_signature_v1"("p_hash" "text", "p_model" "text", "p_prompt" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select md5(coalesce(p_hash,'')||'|'||coalesce(p_model,'')||'|'||coalesce(p_prompt,'provider-description-v2')||'|'||md5(pg_get_functiondef('security.provider_description_validate_v1(uuid,text,timestamptz,jsonb)'::regprocedure))||'|'||coalesce((select jsonb_object_agg(key,value order by key)::text from pipeline.platform_toolset_settings where toolset_key='pipeline' and key in ('pdesc.min_quote_chars','pdesc.min_sentences','pdesc.max_sentences','pdesc.min_chars','pdesc.max_chars','pdesc.support_min_share','pdesc.duplicate_share','pdesc.source_max_age_days','pdesc.verbatim_span_max_chars','pdesc.claim_words','pdesc.evidence_claim_words','pdesc.superlatives')),'')||coalesce('|'||security.pdesc_reader_behaviour_v1(),''))
$$;


ALTER FUNCTION "security"."provider_description_signature_v1"("p_hash" "text", "p_model" "text", "p_prompt" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_description_stored_candidate_v1"("p_provider" "uuid", "p_patterns" "text"[]) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER COST 10
    SET "search_path" TO ''
    AS $$
  -- a necessary condition of security.provider_description_stored_v1, in one index probe: a stored, recent copy whose address looks like an About page. The page rule and host proof still run later, on the few providers that pass.
  select exists (select 1 from pipeline.sources s join pipeline.evidence_artifacts a on a.source_id = s.id
                  where s.provider_id = p_provider and a.storage_path is not null and a.source_url ~* '^https?://'
                    and lower(a.source_url) like any (p_patterns)
                    and coalesce(a.captured_at, a.created_at) > now() - make_interval(days => security.pipeline_num_v1('pdesc.source_max_age_days', 365)::int))
$$;


ALTER FUNCTION "security"."provider_description_stored_candidate_v1"("p_provider" "uuid", "p_patterns" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_stored_candidate_v1"("p_provider" "uuid", "p_patterns" "text"[]) IS 'CF-247 F-PDESC QA B2: true when the provider has a stored, recent page copy whose address matches the given About-page patterns (security.pdesc_about_like_patterns_v1, passed in so they are read once; the cheap first half of security.provider_description_stored_v1; it never says yes to a provider the full rule would refuse for the address, and the page rule runs afterwards).';



CREATE OR REPLACE FUNCTION "security"."provider_description_stored_v1"("p_provider" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- IQ-00055 (v2.15.410 regression): the page rule passes only an address whose first path part is an About page name or starts with an
  -- About prefix, so an address without "/<name>" or "/<prefix>" anywhere cannot pass; those copies are skipped first (a LIKE with the
  -- list's own words, escaped), then the other checks run on what is left, then the page rule once per copy
  with w as (select array(select '%/' || replace(replace(replace(lower(t), '\', '\\'), '%', '\%'), '_', '\_') || '%'
                            from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'pdesc.about_patterns'), '[]'::jsonb)) t
                          union all
                          select '%/' || replace(replace(replace(lower(t), '\', '\\'), '%', '\%'), '_', '\_') || '%'
                            from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'pdesc.about_prefixes'), '[]'::jsonb)) t where t <> '') ws,
                    array(select lower(t) from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'pdesc.about_patterns'), '[]'::jsonb)) t) names,
                    array(select lower(t) from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'pdesc.about_prefixes'), '[]'::jsonb)) t where t <> '') prefixes,
                    -- the oldest capture kept, read once (it was read once per copy)
                    security.pipeline_num_v1('pdesc.about_max_segments', 2) + 1 max_parts,
                    now() - make_interval(days => security.pipeline_num_v1('pdesc.source_max_age_days', 365)::int) since),
  f as (select a.id, a.source_url, a.storage_path, a.mime_type, coalesce(a.captured_at, a.created_at) at
          from w, pipeline.sources s join pipeline.evidence_artifacts a on a.source_id = s.id
         where s.provider_id = p_provider and lower(a.source_url) like any (w.ws)
        offset 0),
  -- the page rule's About part is the first path part, or the second after a language part: one of the first two parts must be an About
  -- page name or start with an About prefix (the path is read as the page rule reads it)
  c as (select f.id, f.at, f.source_url
          from w, f cross join lateral (select z.p, regexp_match(z.p, '^/*([^/]+)(?:/+([^/]+))?') m
                                          from (select lower(coalesce(substring(f.source_url from '^https?://[^/?#]+(/[^?#]*)'), '')) p) z) g
         where f.storage_path is not null and f.source_url ~* '^https?://'
           and coalesce(f.mime_type, 'text/html') ~* 'html|markdown|text'
           and f.at > w.since
           -- at most pdesc.about_max_segments parts, and one more for a language part
           and regexp_count(g.p, '[^/]+') <= w.max_parts
           and (g.m[1] = any (w.names) or g.m[2] = any (w.names)
                or exists (select 1 from unnest(w.prefixes) x where (left(g.m[1], length(x)) = x and length(g.m[1]) > length(x))
                                                                 or (left(g.m[2], length(x)) = x and length(g.m[2]) > length(x))))
        offset 0)
  -- pilot 2 Nov 2026 16:16: the page rule (a held news article was used because "about" was one of its path parts), once per copy
  select c.id
    from c cross join lateral (select security.provider_description_page_v1(p_provider, c.source_url) pg offset 0) r
   where (r.pg->>'ok')::boolean
   order by (r.pg->>'main_host')::boolean desc, c.at desc, c.id
   limit 1
$$;


ALTER FUNCTION "security"."provider_description_stored_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_stored_v1"("p_provider" "uuid") IS 'CF-247 P1 provider descriptions: the newest stored copy of the provider''s About page that passes the page rule (security.provider_description_page_v1), main site first; a prefilter from pdesc.about_patterns and pdesc.about_prefixes skips addresses the rule cannot pass, and the rule runs once per copy (IQ-00055).';



CREATE OR REPLACE FUNCTION "security"."provider_description_subset_v1"("p_provider" "uuid", "p_sentences" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare s jsonb; v_o int := 0; v_bad text; v_kept jsonb := '[]'::jsonb; v_drop jsonb := '[]'::jsonb;
begin
  if jsonb_typeof(p_sentences) is distinct from 'array' then return null; end if;
  for s in select x from jsonb_array_elements(p_sentences) x loop
    v_o := v_o + 1;
    -- the SAME machine text check the whole description goes through, on this sentence alone with its own official quote (a neutral population word is allowed only when the quote holds it and does not negate it, as for the whole text)
    v_bad := security.pdesc_machine_text_check_ctx_v1(p_provider, s->>'text', '{}'::text[], jsonb_build_array(s));
    if v_bad is null then v_kept := v_kept || jsonb_build_array(s);
    else v_drop := v_drop || jsonb_build_array(jsonb_build_object('index', v_o, 'code', v_bad, 'text', s->>'text', 'quote', left(coalesce(s->>'quote', ''), 600))); -- fixed: the audit shows the first 600 characters of the quote; the full quote stays in the proposal
    end if;
  end loop;
  return jsonb_build_object('kept', v_kept, 'dropped', v_drop);
end $$;


ALTER FUNCTION "security"."provider_description_subset_v1"("p_provider" "uuid", "p_sentences" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_subset_v1"("p_provider" "uuid", "p_sentences" "jsonb") IS 'CF-247 F-PDESC: splits the sentences of a provider-description reading into those the machine text rule passes (kept, in order) and those it refuses (dropped: index, exact code, text, quote), by running security.pdesc_machine_text_check_ctx_v1 on each sentence alone with its own quote. Read only; never rewords, merges or adds. Used by security.provider_description_machine_admit_v1 (sentence-subset recovery).';



CREATE OR REPLACE FUNCTION "security"."provider_description_throughput_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_every numeric := security.pipeline_num_v1('pdesc.every_minutes', 60); v_target numeric := security.pipeline_num_v1('pdesc.target_hours', 12); v_batch int := security.pipeline_num_v1('batch.provider_description', 3)::int;
        v_disp int := security.pipeline_num_v1('pdesc.dispatch_max', 3)::int; v_cap int := security.pipeline_num_v1('pdesc.queue_cap', 60)::int; v_win numeric := security.pipeline_num_v1('pdesc.rate_window_hours', 3);
        v_back numeric := security.pipeline_num_v1('pdesc.backlog_hours', 2); v_by jsonb; v_total int; v_obs numeric; v_queued int; v_runs numeric; v_size int; v_room int; v_target_q int; v_share jsonb := '{}'::jsonb; c record;
begin
  select coalesce(jsonb_object_agg(z.cc, z.n), '{}'::jsonb), coalesce(sum(z.n), 0)::int into v_by, v_total from (
    select k.iso_alpha2::text cc, count(*) filter (where lr.state is null or lr.state in ('queued', 'reading')) n
      from catalogue.providers p join ref.countries k on k.id = p.country_id
      left join lateral (select x.state from pipeline.provider_description_reads x where x.provider_id = p.id order by x.created_at desc, x.id desc limit 1) lr on true
     where p.lifecycle_status = 'active' and p.publication_status = 'published' and nullif(btrim(p.description), '') is null and security.provider_description_scope_v1(p.id)
     group by k.iso_alpha2) z;
  select count(*)::numeric / v_win into v_obs from pipeline.provider_description_reads x where x.updated_at > now() - make_interval(hours => v_win::int) and x.state in ('proposed', 'admitted', 'verified', 'held', 'dead_letter', 'rejected');
  select count(*) into v_queued from pipeline.provider_description_reads x where x.state = 'queued';
  v_runs := greatest(1, floor(v_target * 60 / greatest(v_every, 1)));
  v_size := least(v_cap, greatest(1, ceil(v_total / v_runs)::int));
  v_target_q := greatest(v_batch * v_disp * security.pipeline_num_v1('pdesc.queue_floor_runs', 2)::int, ceil(v_obs * v_back)::int);
  v_room := greatest(0, v_target_q - v_queued);
  v_size := least(v_size, v_room);
  if v_total > 0 and v_size > 0 then
    for c in select key cc, value::int n from jsonb_each_text(v_by) where value::int > 0 loop
      v_share := v_share || jsonb_build_object(c.cc, least(c.n, greatest(1, ceil(v_size::numeric * c.n / v_total)::int)));
    end loop;
  end if;
  return jsonb_build_object('remaining_total', v_total, 'remaining_by_country', v_by, 'observed_per_hour', round(v_obs, 2), 'queued_now', v_queued, 'runs_in_target', v_runs,
    'enqueue_size', v_size, 'queue_target', v_target_q, 'share', v_share, 'eta_hours', case when v_obs > 0 then round(v_total / v_obs, 1) end, 'target_hours', v_target);
end $$;


ALTER FUNCTION "security"."provider_description_throughput_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_throughput_v1"() IS 'CF-247 F-PDESC: the providers still to do (never read, queued or reading) in scope by country, the observed reading rate, and the queue size and share per country the reader should add this run (remaining / runs in the target window, limited by what the observed rate can drain). Read only; every number comes from a pdesc.* setting.';



CREATE OR REPLACE FUNCTION "security"."provider_description_validate_v1"("p_provider" "uuid", "p_url" "text", "p_captured_at" timestamp with time zone, "p_result" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_host text := security.provider_page_host_v1(p_provider, p_url);
        v_s jsonb := coalesce(p_result->'sentences', '[]'::jsonb); v_n int; v_text text; s jsonb; t text;
        v_sup numeric; v_light boolean := security.pipeline_num_v1('pdesc.prompt_on', 0) >= 1; -- 20261112010000: the prompt profile
        v_min_sup numeric := case when security.pipeline_num_v1('pdesc.prompt_on', 0) >= 1 then security.pipeline_num_v1('pdesc.prompt_support_min_share', 0.5) else security.pipeline_num_v1('pdesc.support_min_share', 0.6) end;
        v_dup numeric := security.pipeline_num_v1('pdesc.duplicate_share', 0.8);
        v_current text; v_other record; v_checks jsonb := '{}'::jsonb; v_claim text;
        v_drop boolean := coalesce((p_result->>'drop_failing')::boolean, false); v_keep jsonb := '[]'::jsonb; v_dropped jsonb := '[]'::jsonb; v_bad jsonb; v_first jsonb; v_idx int := 0; v_ret jsonb;
begin
  v_n := jsonb_array_length(v_s);
  v_text := (select string_agg(btrim(x->>'text'), ' ' order by o) from jsonb_array_elements(v_s) with ordinality e(x, o));
  v_checks := jsonb_build_object('host', v_host, 'sentences', v_n, 'chars', length(coalesce(v_text, '')));
  if v_host <> 'own' then
    return jsonb_build_object('ok', false, 'outcome', 'refused', 'rule', 'wrong_host', 'checks', v_checks,
      'reason', case v_host when 'other_provider' then 'the page is on another provider''s website' when 'no_url' then 'no page address' else 'the page is not on the provider''s own website' end);
  end if;
  -- pilot 2 Nov 2026 16:16: only the provider's own About or Overview page is a description source
  if not (security.provider_description_page_v1(p_provider, p_url)->>'ok')::boolean then
    return jsonb_build_object('ok', false, 'outcome', 'refused', 'rule', security.provider_description_page_v1(p_provider, p_url)->>'rule', 'checks', v_checks,
      'reason', 'the page is not the provider''s own About or Overview page');
  end if;
  if v_n = 0 then
    return jsonb_build_object('ok', false, 'outcome', 'held', 'rule', 'not_stated', 'checks', v_checks, 'reason', 'the page does not describe the institution');
  end if;
  -- CF-247 F-PDESC (20261110250000): the model's about_page flag no longer vetoes sentences; it is recorded and every sentence rule below decides
  if coalesce((p_result->>'about_page')::boolean, false) is false then v_checks := v_checks || jsonb_build_object('about_page_flag', false); end if;
  if v_n < security.pipeline_num_v1('pdesc.min_sentences', 2) or v_n > security.pipeline_num_v1('pdesc.max_sentences', 5) then
    return jsonb_build_object('ok', false, 'outcome', 'held', 'rule', 'sentence_count', 'checks', v_checks, 'reason', v_n || ' sentence(s), outside the set range');
  end if;
  for s in select x from jsonb_array_elements(v_s) x loop
    v_idx := v_idx + 1; v_bad := null; v_claim := null;
    t := btrim(coalesce(s->>'text', ''));
    -- the sentence rules, in their order, for one sentence: the first that fails sets v_bad and leaves the pass (a single-pass loop)
    <<chk>>
    loop
      if coalesce((s->>'on_page')::boolean, false) is false or nullif(btrim(coalesce(s->>'quote', '')), '') is null then
        v_bad := jsonb_build_object('ok', false, 'outcome', 'held', 'rule', 'quote_not_on_page', 'checks', v_checks, 'reason', 'a sentence''s quote is not on the page: ' || left(t, 120)); exit chk;
      end if;
      if v_light and exists (select 1 from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'pdesc.prompt_refused_words'), '[]'::jsonb)) w where security.pdesc_has_term_v1(t, w)) then
        v_bad := jsonb_build_object('ok', false, 'outcome', 'held', 'rule', 'refused_topic', 'checks', v_checks, 'reason', 'a word a description never carries (ranking, award, outcome, promotion, fees, visas): ' || left(t, 120)); exit chk;
      end if;
      if not v_light and exists (select 1 from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'pdesc.superlatives'), '[]'::jsonb)) w
                  where security.pdesc_has_term_v1(t, w) and not security.pdesc_has_term_v1(s->>'quote', w)) then
        v_bad := jsonb_build_object('ok', false, 'outcome', 'held', 'rule', 'unsupported_marketing', 'checks', v_checks, 'reason', 'a marketing word that is not in the quote: ' || left(t, 120)); exit chk;
      end if;
      if not v_light and exists (select 1 from jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'pdesc.claim_words'), '[]'::jsonb)) w
                  where security.pdesc_has_term_v1(t, w) and not security.pdesc_has_term_v1(s->>'quote', w)) then
        v_bad := jsonb_build_object('ok', false, 'outcome', 'held', 'rule', 'unsupported_claim', 'checks', v_checks, 'reason', 'a ranking, facility, outcome or accreditation claim that is not in the quote: ' || left(t, 120)); exit chk;
      end if;
      -- Platform Admin 5 Nov 2026 20:03 §2: campus, scholarship and guarantee statements are checked against their official quote, never held by keyword alone
      select r into v_claim from (select security.pdesc_claim_check_v1(t, s->>'quote', w) r from jsonb_array_elements_text(case when v_light then '[]'::jsonb else coalesce(security.toolset_setting('pipeline', 'pdesc.evidence_claim_words'), '[]'::jsonb) end) w) z where r is not null limit 1;
      if v_claim is not null then
        v_bad := jsonb_build_object('ok', false, 'outcome', 'held', 'rule', v_claim, 'checks', v_checks, 'reason', case v_claim when 'claim_negated_in_source' then 'the official quote negates a campus, scholarship or guarantee statement that the sentence makes: ' else 'a campus, scholarship or guarantee statement that its official quote does not support: ' end || left(t, 120)); exit chk;
      end if;
      -- Platform Admin 2 Nov 2026 23:24 ("avoid cutting essential conditions or publishing fragments as complete descriptions"): a sentence
      -- that does not end as a sentence (no closing full stop, question or exclamation mark, or an ellipsis) is a fragment; the description is
      -- held, never cut or completed
      if t !~ '[.!?]["'')\]’”]*$' or t ~ '(\.\.\.|…)["'')\]’”]*$' then
        v_bad := jsonb_build_object('ok', false, 'outcome', 'held', 'rule', 'incomplete_sentence', 'checks', v_checks,
          'reason', 'a sentence is not complete (it would be published as a fragment): ' || left(t, 120)); exit chk;
      end if;
      -- Validation 5 Nov 2026 (decision 20:03 §2): numbers are compared after normalising format (80,000 = 80 000; per cent = %), and the quote's number words count (four = 4).
      if exists(select 1 from regexp_matches(security.pdesc_number_norm_v1(t,false),'[0-9]+(?:[.,][0-9]+)*','g') n where not exists(select 1 from regexp_matches(security.pdesc_number_norm_v1(s->>'quote',true),'[0-9]+(?:[.,][0-9]+)*','g') q where q[1]=n[1])) then
        v_bad := jsonb_build_object('ok',false,'outcome','held','rule','unsupported_numeric_claim','reason','A number in a factual claim does not occur in its supporting quote.','checks',v_checks); exit chk;
      end if;
      -- Quote provenance is retained separately; long verbatim spans fail the existing factual description path.
      if not v_light and exists(select 1 from generate_series(1,greatest(0,length(regexp_replace(t,'\s+',' ','g'))-security.pipeline_num_v1('pdesc.verbatim_span_max_chars',120)::int+1)) n where position(lower(substring(regexp_replace(t,'\s+',' ','g') from n for security.pipeline_num_v1('pdesc.verbatim_span_max_chars',120)::int)) in lower(regexp_replace(s->>'quote','\s+',' ','g')))>0) then
        v_bad := jsonb_build_object('ok',false,'outcome','held','rule','verbatim_passage','reason','A long official passage was copied; a concise source-grounded paraphrase is required.','checks',v_checks); exit chk;
      end if;
      if not v_light and coalesce(s->>'quote','')~* '\m(former|formerly|previously|renamed|closed|merged|ceased)\M|was known as|became'
        and t~* '\m(is|are|operates|offers)\M' and t!~* '\m(former|formerly|previously|was|were|became|renamed|closed|merged|ceased|history|founded|established|origin|since)\M'
        -- Validation 5 Nov 2026 (decision 20:03 §2): evidence-aware. Held only when the quote's present-tense part does not support the sentence,
        -- i.e. the sentence's claim is the one the quote places in the past; a historic word elsewhere in the quote never holds a supported claim.
        and security.pdesc_present_support_v1(t, s->>'quote') < v_min_sup then
        v_bad := jsonb_build_object('ok',false,'outcome','held','rule','historic_claim_context','reason','Historical source context cannot establish a present institutional identity or operation.','checks',v_checks); exit chk;
      end if;
      v_sup := security.pdesc_support_v1(t, s->>'quote');
      if v_sup < v_min_sup then
        v_bad := jsonb_build_object('ok', false, 'outcome', 'held', 'rule', 'unsupported_sentence', 'checks', v_checks || jsonb_build_object('support', v_sup),
          'reason', 'a sentence is not supported by its quote (' || v_sup || '): ' || left(t, 120)); exit chk;
      end if;
      exit chk;
    end loop chk;
    if v_bad is not null then
      -- without drop_failing (every caller except the record of a new read) the first failing sentence holds the whole answer, exactly as before
      if not v_drop then return v_bad; end if;
      v_dropped := v_dropped || jsonb_build_object('index', v_idx, 'rule', v_bad->>'rule', 'reason', left(coalesce(v_bad->>'reason', ''), 300), 'text', left(t, 300), 'quote', left(coalesce(s->>'quote', ''), 300), 'support', v_bad#>'{checks,support}');
      v_first := coalesce(v_first, v_bad);
    else
      v_keep := v_keep || jsonb_build_array(s);
    end if;
  end loop;
  -- sentence filter (the record of a new read only): the sentences that failed a rule are left out, the others are checked as a whole description below.
  -- Every kept sentence passed every sentence rule above; the count, the length, the age and the duplicate tests apply to what is kept. Fewer kept sentences than the set
  -- minimum hold the read with the rule of the first sentence that failed. The dropped sentences and why stay in checks.dropped.
  if v_drop and jsonb_array_length(v_dropped) > 0 then
    v_text := (select string_agg(btrim(x->>'text'), ' ' order by o) from jsonb_array_elements(v_keep) with ordinality e(x, o));
    v_checks := v_checks || jsonb_build_object('sentences', jsonb_array_length(v_keep), 'sentences_given', v_n, 'chars', length(coalesce(v_text, '')), 'dropped', v_dropped);
    if jsonb_array_length(v_keep) < security.pipeline_num_v1('pdesc.min_sentences', 2) then
      return v_first || jsonb_build_object('checks', v_checks);
    end if;
  end if;
  -- 20261112010000 (prompt profile): the first sentence names the provider (no description opens with "It ..." or "They ...")
  if v_light and not exists (select 1 from catalogue.providers p cross join lateral unnest(security.pdesc_name_forms_v1(array[p.canonical_name, p.display_name, p.short_name])) nm /* 20261112023700: name forms */
                              where p.id = p_provider and length(btrim(coalesce(nm, ''))) >= security.pipeline_num_v1('pdesc.name_min_chars', 3)
                                and security.pdesc_has_term_v1(replace((select btrim(x->>'text') from jsonb_array_elements(case when v_drop and jsonb_array_length(v_dropped) > 0 then v_keep else v_s end) with ordinality e(x, o) order by o limit 1), '&', ' and '), btrim(nm))) then
    return jsonb_build_object('ok', false, 'outcome', 'held', 'rule', 'first_sentence_no_name', 'checks', v_checks, 'reason', 'the first sentence does not name the provider');
  end if;
  if length(v_text) < security.pipeline_num_v1('pdesc.min_chars', 150) or length(v_text) > security.pipeline_num_v1('pdesc.max_chars', 900) then
    return jsonb_build_object('ok', false, 'outcome', 'held', 'rule', 'length', 'checks', v_checks, 'reason', length(v_text) || ' characters, outside the set range');
  end if;
  if p_captured_at is not null and p_captured_at < now() - make_interval(days => security.pipeline_num_v1('pdesc.source_max_age_days', 365)::int) then
    return jsonb_build_object('ok', false, 'outcome', 'held', 'rule', 'source_outdated', 'checks', v_checks, 'reason', 'the stored page is older than the set age');
  end if;
  -- duplicate: another provider's description held, or another provider's proposal waiting
  select z.provider_id, z.sim into v_other from (
    select f.id provider_id, security.pdesc_similarity_v1(v_text, f.description) sim from (
      -- the cheap count first (a word of the description is always a substring of it, so the count is never below the true overlap; 0.0001 covers the four-decimal rounding of the similarity): a row that cannot reach duplicate_share is not worked out
      select p.id, p.description from catalogue.providers p cross join (select security.pdesc_words_v1(v_text) wa offset 0) w
       where p.id <> p_provider and nullif(btrim(p.description), '') is not null
         and (select count(*) from unnest(w.wa) x where position(x in lower(p.description)) > 0) >= (v_dup - 0.0001) * cardinality(w.wa) -- fixed: rounding slack of pdesc_similarity_v1 (four decimals)
       offset 0) f -- offset 0: optimisation fence, so the count runs before the similarity
    union all
    select r.provider_id, security.pdesc_similarity_v1(v_text, r.proposal->>'description') from pipeline.provider_description_reads r
     where r.provider_id <> p_provider and r.state = 'proposed') z
   where z.sim >= v_dup order by z.sim desc limit 1;
  if v_other.provider_id is not null then
    return jsonb_build_object('ok', false, 'outcome', 'held', 'rule', 'duplicate_other_provider', 'checks', v_checks || jsonb_build_object('duplicate_of', v_other.provider_id, 'similarity', v_other.sim),
      'reason', 'the same as another provider''s description (' || v_other.sim || ')');
  end if;
  select nullif(btrim(p.description), '') into v_current from catalogue.providers p where p.id = p_provider;
  if v_current is not null and security.pdesc_similarity_v1(v_text, v_current) >= v_dup then
    v_ret := jsonb_build_object('ok', true, 'outcome', 'verified', 'rule', 'same_as_current', 'text', v_text,
      'checks', v_checks || jsonb_build_object('similarity_current', security.pdesc_similarity_v1(v_text, v_current)), 'reason', 'the page still supports the description held');
    if v_drop then v_ret := v_ret || jsonb_build_object('sentences', v_keep); end if;
    return v_ret;
  end if;
  v_ret := jsonb_build_object('ok', true, 'outcome', 'propose', 'rule', case when v_current is null then 'missing' else 'changed' end, 'text', v_text, 'checks', v_checks, 'reason', null);
  if v_drop then v_ret := v_ret || jsonb_build_object('sentences', v_keep); end if;
  return v_ret;
end 
$_$;


ALTER FUNCTION "security"."provider_description_validate_v1"("p_provider" "uuid", "p_url" "text", "p_captured_at" timestamp with time zone, "p_result" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."provider_description_validate_v1"("p_provider" "uuid", "p_url" "text", "p_captured_at" timestamp with time zone, "p_result" "jsonb") IS 'CF-247 P1 provider descriptions: the validation of one read (mandate §7): own host, about page, sentence count, every quote on the page, every sentence supported by its quote, no marketing words or claims unless quoted, length, source age, duplicate of another provider, same as the description held. Writes nothing.';



