CREATE OR REPLACE FUNCTION "security"."provider_presentable_name"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  with a as (select replace(replace(replace(replace(replace(coalesce(p,''),'&#039;',''''),'&#39;',''''),'&amp;','&'),'&quot;','"'),'&apos;','''') x),
       b as (select btrim(split_part(x,';',1)) x from a),
       c as (select btrim(regexp_replace(regexp_replace(x,'[\s,]+(pty\.?\s*(ltd|limited)\.?|limited|ltd\.?|incorporated|inc\.?)\s*$','','i'),'[\s,]+(pty\.?\s*(ltd|limited)\.?|limited|ltd\.?)\s*$','','i')) x from b)
  select case when p is null then null
              when c.x !~ '[a-z]' and c.x ~ '[A-Z]' then
                (select string_agg(case when w ~ '^\(?(TAFE|RMIT|UNSW|ANU|UTS|QUT|ACU|CQU|JCU|NSW|QLD|VIC|TAS|WA|SA|NT|ACT|UK|USA|ELICOS|ESL|EAP|IT|IELTS|AIBT|ICHM|MIT|KOI|SIBT|UWA|ECU|CDU|USQ|USC|SCU|CIT|AIE|AIT|ATMC|NIET|IIBIT|AIH|APIC|ACBI|ACAH|CBD|RTO|VET)\)?[,.]?$' then w
                                        when ord>1 and lower(w) in ('of','and','the','for','in','at','&','de') then lower(w)
                                        else initcap(w) end, ' ' order by ord)
                   from regexp_split_to_table(c.x,'\s+') with ordinality t(w,ord))
              else c.x end
    from c
$_$;


ALTER FUNCTION "security"."provider_presentable_name"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_priority_refresh_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'catalogue', 'ref'
    AS $$
declare v_n int;
begin
  delete from pipeline.provider_priority;
  insert into pipeline.provider_priority(provider_id,rank,active_courses,pinned_by)
  with n as (select co.provider_id, count(*) c from catalogue.courses co where co.lifecycle_status='active' group by 1),
  p as (select pr.id provider_id, n.c, k.iso_alpha2='AU' au,
          (select min(sort) from pipeline.priority_pins x where x.kind='provider' and x.target_id=pr.id) s_p,
          (select min(sort) from pipeline.priority_pins x where x.kind='state' and x.target_id=pr.subdivision_id) s_s,
          (select min(sort) from pipeline.priority_pins x where x.kind='country' and x.target_id=pr.country_id) s_c
          from catalogue.providers pr join n on n.provider_id=pr.id left join ref.countries k on k.id=pr.country_id)
  select provider_id, row_number() over (order by least(s_p,s_s,s_c) nulls last, au desc nulls last, c desc, provider_id), c,
         case when least(s_p,s_s,s_c) is null then null when least(s_p,s_s,s_c)=s_p then 'provider' when least(s_p,s_s,s_c)=s_s then 'state' else 'country' end
    from p;
  get diagnostics v_n = row_count;
  delete from pipeline.course_priority;
  insert into pipeline.course_priority(course_id,sort) select target_id, sort from pipeline.priority_pins where kind='course';
  return v_n;
end $$;


ALTER FUNCTION "security"."provider_priority_refresh_v1"() OWNER TO "postgres";


