CREATE OR REPLACE FUNCTION "security"."provider_restore_v1"("p_provider_id" "uuid", "p_note" "text", "p_actor" "uuid", "p_manual" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_life text; v_id bigint; v_prev_pub text; v_cascade jsonb; v_now text; v_rv int := 0;
begin
  select p.lifecycle_status into v_life from catalogue.providers p where p.id = p_provider_id for update;
  if not found then raise exception 'provider not found'; end if;
  if v_life = 'active' then return jsonb_build_object('status', 'already_active', 'provider_id', p_provider_id); end if;
  select a.id, a.previous_publication, a.cascade into v_id, v_prev_pub, v_cascade from pipeline.provider_archives a
   where a.provider_id = p_provider_id and a.restored_at is null for update;
  if p_manual then perform set_config('cf.manual_edit', 'on', true); end if;
  update catalogue.providers set lifecycle_status = 'active', publication_status = coalesce(v_prev_pub, 'published'), updated_at = now() where id = p_provider_id;
  select p.lifecycle_status into v_now from catalogue.providers p where p.id = p_provider_id;
  if v_now <> 'active' then return jsonb_build_object('status', 'kept_by_hand', 'provider_id', p_provider_id); end if;
  if v_id is not null then
    if coalesce((v_cascade->>'adapter_switched_off')::boolean, false) then update pipeline.uni_adapters set enabled = true, updated_at = now() where provider_id = p_provider_id; end if;
    if coalesce((v_cascade->>'link_recipe_switched_off')::boolean, false) then update pipeline.course_link_recipes set active = true, updated_at = now() where provider_id = p_provider_id; end if;
    with i as (update pipeline.layer4_review_items x set status = 'pending', decided_at = null
                where x.status = 'superseded' and x.id in (select (e #>> '{}')::uuid from jsonb_array_elements(coalesce(v_cascade->'reviews_superseded', '[]'::jsonb)) e)
               returning 1)
    select count(*) into v_rv from i;
    update pipeline.provider_archives set restored_at = now(), restored_by = p_actor, restore_note = left(p_note, 500) where id = v_id;
  end if;
  insert into pipeline.manual_edit_log(entity, entity_id, field, action, before, after, reason, actor)
  values ('provider', p_provider_id, 'lifecycle_status', 'restore', to_jsonb(v_life), to_jsonb('active'::text), left(coalesce(p_note, 'Restored'), 500), p_actor);
  insert into search.refresh_requests(requested_by) values (format('provider %s restored', left(p_provider_id::text, 8)));
  return jsonb_build_object('status', 'restored', 'provider_id', p_provider_id, 'publication_status', coalesce(v_prev_pub, 'published'), 'reviews_reopened', v_rv);
end $$;


ALTER FUNCTION "security"."provider_restore_v1"("p_provider_id" "uuid", "p_note" "text", "p_actor" "uuid", "p_manual" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_rule_admit_v1"("p_apply" boolean DEFAULT false, "p_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'catalogue', 'search'
    AS $_$
declare v_summary jsonb; v_samples jsonb; v_admitted int:=0; v_courses uuid[]:='{}'; r record; v_fee uuid; v_key text; v_code text; v_source uuid; v_review uuid;
begin
  create temp table if not exists _pra(wid uuid, course_id uuid, evidence_id uuid, interpretation_id uuid, rule_code text, amount numeric,
    basis text, excl text, fc jsonb, matched text, outcome text, fee_year int) on commit drop;
  truncate _pra;
  insert into _pra
  select w.id, w.entity_id, w.evidence_id, w.interpretation_id, pf.rule_code,
         (w.candidate_context->'provider_current_tuition'->>'amount')::numeric, pf.resolved_basis, pf.exclusion_pattern,
         (select f from jsonb_array_elements(coalesce(w.candidate_context->'fee_candidates','[]'::jsonb)) f
           where jsonb_typeof(f)='object' and (f->>'amount')::numeric=(w.candidate_context->'provider_current_tuition'->>'amount')::numeric
             and coalesce((f->>'domestic')::boolean,false)=false
           order by (f->>'score')::numeric desc nulls last limit 1),
         null, null, null
  from pipeline.layer3_work_items w
  join pipeline.provider_fee_profiles pf on pf.rule_code=w.candidate_context->>'provider_fee_rule' and pf.active and pf.review_by>=current_date
  where w.task_class='provider_current_tuition_validation'
    and w.candidate_context ? 'provider_fee_rule'
    and w.status in ('pending','layer4_required','failed','no_candidate','rejected')
    and coalesce(w.candidate_context->'provider_current_tuition'->>'audience','')='international'
  limit greatest(1,least(coalesce(p_limit,500),2000));

  update _pra set matched = security.layer4_clean_quote(fc->>'context') where fc is not null;
  update _pra set outcome = case
      when fc is null then 'no Layer 2 candidate with the exact amount (or it is domestic)'
      when lower(regexp_replace(coalesce(matched,''),'[\s,\[\]]','','g')) ~ ('fees(a|aud)?\$'||trunc(amount)::bigint::text)
       and coalesce(split_part(lower(coalesce(substring(matched from '(?i)fees\s*(?:a|aud)?\s*\$\s*[\d,\.]+(.{0,80})'),'')),'duration',1),'') !~* excl
        then 'admit'
      when lower(regexp_replace(coalesce(matched,''),'[\s,\[\]]','','g')) ~ 'approximateyearlycostoffull.?timetuition'
       and matched ~* ('(a|aud)\s*\$\s*'||replace(to_char(trunc(amount)::bigint,'FM999,999,999'),',',',?')||'([^0-9,]|$)')
       and coalesce(split_part(lower(coalesce(substring(matched from '(?i)(?:a|aud)\s*\$\s*'||replace(to_char(trunc(amount)::bigint,'FM999,999,999'),',',',?')||'(.{0,40})'),'')),'learn more',1),'') !~* excl
        then 'admit (fee explanation)'
      when lower(regexp_replace(coalesce(matched,''),'[\s,\[\]]','','g')) !~ ('fees(a|aud)?\$'||trunc(amount)::bigint::text) then 'amount not labelled "Fees" in the fee panel'
      else 'exclusion word next to the amount' end
  where true;
  update _pra set fee_year = substring(matched from '(?i)(?:a|aud)\s*\$\s*'||replace(to_char(trunc(amount)::bigint,'FM999,999,999'),',',',?')||'\s+(20[2-3][0-9])\y')::int
  where outcome='admit (fee explanation)';
  update _pra p set fee_year = null
  where outcome='admit (fee explanation)' and fee_year is not null
    and exists (select 1 from regexp_matches(p.matched,'\y(20[2-3][0-9])\y','g') m where m[1]::int <> p.fee_year);

  select jsonb_object_agg(outcome,n) into v_summary from (select outcome, count(*) n from _pra group by 1) x;
  select jsonb_agg(s) into v_samples from (select jsonb_build_object('outcome',outcome,'amount',amount,'year',fee_year,'text',left(matched,140)) s from _pra order by outcome, amount limit 6) y;

  if p_apply then
    for r in select * from _pra where outcome in ('admit','admit (fee explanation)') loop
      select course_code into v_code from catalogue.courses where id=r.course_id;
      select source_id into v_source from pipeline.evidence_artifacts where id=r.evidence_id;
      if v_code is null or v_source is null then continue; end if;
      v_key := lower(upper(btrim(v_code))||':international:'||coalesce(r.fee_year::text,'current')||':'||r.basis);
      insert into catalogue.course_fees(course_id,fee_year,audience,fee_type,amount,currency_code,basis,notes,source_id,evidence_id,confidence,campus_id,source_fee_key,status,last_verified_at,source_snapshot_at,updated_at)
      values (r.course_id,r.fee_year,'international','provider_current_tuition',r.amount,'AUD',r.basis,
              format('CF-247 provider rule admission (deterministic, Decision 106; %s); rule %s; work item %s',r.outcome,r.rule_code,r.wid),
              v_source,r.evidence_id,1,null,v_key,'active',now(),now(),now())
      on conflict(course_id,source_id,source_fee_key) where source_id is not null and source_fee_key is not null do nothing
      returning id into v_fee;
      update pipeline.layer3_work_items set status='admitted', completed_at=now(), last_error=null, updated_at=now() where id=r.wid;
      v_review := null;
      update pipeline.layer4_review_items set status='superseded', decided_at=now()
        where layer3_interpretation_id=r.interpretation_id and status='pending' returning id into v_review;
      insert into pipeline.provider_rule_admissions(work_item_id,review_item_id,course_id,course_fee_id,rule_code,amount,basis,matched_text)
      values (r.wid,v_review,r.course_id,v_fee,r.rule_code,r.amount,r.basis,left(r.matched,500));
      v_courses := v_courses || r.course_id; v_admitted := v_admitted+1;
    end loop;
    if cardinality(v_courses)>0 then perform search.refresh_course_enrichment_scoped_v1(v_courses, true); end if;
  end if;
  return jsonb_build_object('mode',case when p_apply then 'apply' else 'proof' end,'outcomes',coalesce(v_summary,'{}'::jsonb),'admitted',v_admitted,'samples',coalesce(v_samples,'[]'::jsonb));
end $_$;


ALTER FUNCTION "security"."provider_rule_admit_v1"("p_apply" boolean, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_sch_search_auto_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v int;
begin
  with ins as (
    insert into pipeline.provider_scholarship_search(provider_id, enabled, auto, reason)
    select x.provider_id, false, true, 'Only website known is a directory site'
      from (select provider_id from pipeline.scholarship_discovery_providers where security.third_party_host_v1(coalesce(website, ''))
            union select provider_id from pipeline.coverage_provider_discovery where security.third_party_host_v1(coalesce(website, ''))
            union select id from catalogue.providers where security.third_party_host_v1(coalesce(website, ''))) x
     where not exists (select 1 from pipeline.provider_scholarship_search f where f.provider_id = x.provider_id)
       and security.provider_directory_only_v1(x.provider_id)
    on conflict (provider_id) do nothing
    returning provider_id, reason)
  insert into pipeline.provider_scholarship_search_log(provider_id, enabled, auto, reason)
  select provider_id, false, true, reason from ins;
  get diagnostics v = row_count;
  return v;
end $$;


ALTER FUNCTION "security"."provider_sch_search_auto_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_sch_search_off_v1"("p_provider" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from pipeline.provider_scholarship_search f where f.provider_id = p_provider and not f.enabled)
$$;


ALTER FUNCTION "security"."provider_sch_search_off_v1"("p_provider" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_site_followups_tg"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if nullif(btrim(NEW.website), '') is null then
    if TG_OP = 'INSERT' then
      insert into pipeline.coverage_provider_discovery(provider_id, status, requested_at, updated_at) values (NEW.id, 'no_website', now(), now())
      on conflict (provider_id) do nothing;
    end if;
  elsif TG_OP = 'INSERT' or nullif(btrim(OLD.website), '') is distinct from nullif(btrim(NEW.website), '') then
    insert into pipeline.provider_central_search(provider_id, state, requested_at) values (NEW.id, 'queued', now())
    on conflict (provider_id) do update set state = 'queued', requested_at = now(), leased_until = null, updated_at = now() where pipeline.provider_central_search.state <> 'leased';
  end if;
  return null;
end $$;


ALTER FUNCTION "security"."provider_site_followups_tg"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_site_verdict_v1"("p_provider_id" "uuid", "p_url" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_host text := security.site_host_v1(p_url); v_reg text; v_label text; v_words text[]; v_init text; v_name text;
begin
  if v_host is null then return 'none'; end if;
  if security.third_party_host_v1(p_url) then return 'third_party'; end if;
  if exists (select 1 from pipeline.important_links l where l.enabled and l.retired_at is null and l.domain like '%.%'
               and l.authority_category in ('regulatory_authority', 'qualification_framework') and (v_host = l.domain or v_host like '%.' || l.domain)) then return 'regulator'; end if;
  select security.site_host_v1(p.website), regexp_replace(split_part(v_host, '.', 1), '[^a-z0-9]', '', 'g'), lower(coalesce(p.display_name, p.canonical_name, '')),
         array_remove(regexp_split_to_array(btrim(regexp_replace(lower(coalesce(p.display_name, '') || ' ' || coalesce(p.canonical_name, '') || ' ' || coalesce(p.short_name, '')), '[^a-z0-9]+', ' ', 'g')), ' '), '')
    into v_reg, v_label, v_name, v_words from catalogue.providers p where p.id = p_provider_id;
  if v_reg is not null and (v_host = v_reg or v_host like '%.' || v_reg or v_reg like '%.' || v_host) then return 'own'; end if;
  if length(coalesce(v_label, '')) >= 3 then
    if exists (select 1 from unnest(v_words) w where length(w) >= 4 and v_label like '%' || w || '%'
                 and w not in ('university','college','institute','technology','school','polytechnic','community','arts','design','australia','australian',
                               'education','training','international','group','academy','business','management','limited','trading','services','national',
                               'learning','studies','english','language','centre','center','holdings','trust','incorporated')) then return 'own'; end if;
    select string_agg(left(w, 1), '') into v_init from unnest(regexp_split_to_array(btrim(regexp_replace(v_name, '[^a-z0-9]+', ' ', 'g')), ' ')) w where w <> '' and w not in ('of','and','the','at','for','in','pty','ltd');
    if v_label = v_init then return 'own'; end if;
  end if;
  return 'unconfirmed';
end $$;


ALTER FUNCTION "security"."provider_site_verdict_v1"("p_provider_id" "uuid", "p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_task_fire_v1"("p_mode" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_body jsonb;
begin
  v_body := case p_mode when 'find_site' then '{"mode":"find_site","limit":5}'::jsonb when 'contact_page' then '{"mode":"contact_page","limit":8}'::jsonb
                         when 'central_find' then '{"mode":"central_find","limit":4}'::jsonb
                         -- hotfix D2 (24 Oct 2026): the body of job course-link-search-worker, word for word
                         when 'link_search' then jsonb_build_object('mode', 'link_search', 'limit', security.pipeline_num_v1('batch.link_search_worker', 120)::int) end;
  if v_body is null then return 0; end if;
  if p_mode = 'link_search'
     and not exists (select 1 from cron.job j where j.jobname = 'course-link-search-worker' and j.active)
     and not exists (select 1 from pipeline.enrichment_flags f where f.entity = 'job' and f.entity_key = 'course-link-search-worker' and f.reason_code = 'idle_paused' and f.state = 'raised') then
    return 0;
  end if;
  if exists (select 1 from pipeline.edge_request_log l where l.function_name = 'coverage-sweep' and l.mode = p_mode and l.created_at > now() - interval '45 seconds'
              and not exists (select 1 from net._http_response r where r.id = l.request_id)) then return 0; end if;
  perform pipeline.svc_pilot_submit_nonce('coverage-sweep', v_body);
  return 1;
end $$;


ALTER FUNCTION "security"."provider_task_fire_v1"("p_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_task_prepare_v1"("p_kind" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_pid uuid := nullif(p_args->>'provider_id', '')::uuid; v_name text; v_site text; v_ids uuid[]; v_n int := 0;
begin
  select coalesce(p.display_name, p.canonical_name), nullif(btrim(p.website), '') into v_name, v_site from catalogue.providers p where p.id = v_pid and p.lifecycle_status = 'active';
  if v_name is null then raise exception 'choose an active provider'; end if;
  if exists (select 1 from security.provider_hidden_v1 h where h.provider_id = v_pid) then raise exception 'this provider is unpublished or archived; publish or restore it first'; end if;
  if p_kind = 'provider_fill' then
    if v_site is null then
      insert into pipeline.coverage_provider_discovery(provider_id, status, requested_at, updated_at) values (v_pid, 'no_website', now(), now())
      on conflict (provider_id) do update set status = case when pipeline.coverage_provider_discovery.website is null then 'no_website' else pipeline.coverage_provider_discovery.status end,
             site_searched_at = null, leased_until = null, requested_at = now(), updated_at = now();
      -- a website already found and verified earlier is adopted straight away
      perform security.provider_website_adopt_v1(v_pid, d.website) from pipeline.coverage_provider_discovery d where d.provider_id = v_pid and d.site_source like 'search_verified_%' and d.website is not null;
      select nullif(btrim(p.website), '') into v_site from catalogue.providers p where p.id = v_pid;
    end if;
    if v_site is not null then
      insert into pipeline.provider_central_search(provider_id, state, requested_at) values (v_pid, 'queued', now())
      on conflict (provider_id) do update set state = 'queued', requested_at = now(), leased_until = null, attempts = 0, updated_at = now();
    end if;
    update pipeline.provider_contact_checks set checked_at = now() - interval '91 days', outcome = 'requested' where provider_id = v_pid and kind = 'public_general';
    return jsonb_build_object('provider_id', v_pid, 'had_website', v_site is not null, 'title', 'Fill in from website: ' || v_name, 'scope', v_pid::text);
  elsif p_kind = 'course_page_find' then
    if not exists (select 1 from pipeline.course_link_recipes x where x.provider_id = v_pid and x.active) then
      raise exception 'no website is recorded for this provider yet, so there is nowhere to search; use Fill in from website first';
    end if;
    if coalesce((security.firecrawl_setting('target_only') #>> '{}')::boolean, true)
       and not exists (select 1 from pipeline.firecrawl_target_cache tc where tc.provider_id = v_pid and tc.included) then
      raise exception 'Not started: this university is not a search target, and course page search is for target universities only (Toolsets & limits › targets).';
    end if;
    v_ids := array(select c.id from catalogue.courses c where c.provider_id = v_pid and c.lifecycle_status = 'active'
                     and (case when jsonb_typeof(p_args->'course_ids') = 'array' and jsonb_array_length(p_args->'course_ids') > 0
                               then c.id = any (array(select x::uuid from jsonb_array_elements_text(p_args->'course_ids') x))
                               else not exists (select 1 from pipeline.coverage_course_pages g where g.course_id = c.id and g.read_status = 'read') end));
    if coalesce(cardinality(v_ids), 0) = 0 then raise exception 'every course of this provider already has a read page'; end if;
    if cardinality(v_ids) > 300 then raise exception 'at most 300 courses in one task'; end if;
    insert into pipeline.course_link_search(course_id, provider_id, stage, state, queued_at, requested_at)
    select c.id, c.provider_id, case when c.course_code ~ '^[0-9]{6}[0-9A-Z]$' then 'cricos' else 'title' end, 'queued', now(), now()
      from catalogue.courses c where c.id = any (v_ids)
    on conflict (course_id) do update set state = 'queued', stage = excluded.stage, attempts = 0, cand_idx = 0, queued_at = now(), requested_at = now(), sent_at = null
     where pipeline.course_link_search.state not in ('sent');
    get diagnostics v_n = row_count;
    perform security.provider_task_fire_v1('link_search');  -- hotfix D2: forwarded on accept, not at the next minute
    return jsonb_build_object('provider_id', v_pid, 'course_ids', to_jsonb(v_ids), 'queued', v_n,
                              'title', 'Find course pages: ' || v_name || ' (' || cardinality(v_ids) || ' course' || case when cardinality(v_ids) = 1 then '' else 's' end || ')',
                              'scope', v_pid::text);
  end if;
  raise exception 'unknown provider task';
end $_$;


ALTER FUNCTION "security"."provider_task_prepare_v1"("p_kind" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_type_classify_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_out jsonb;
begin
  with p as (
    select pr.id, trim(co.iso_alpha2::text) cc
    from catalogue.providers pr join ref.countries co on co.id = pr.country_id
    where trim(co.iso_alpha2::text) in (select distinct country_code from pipeline.provider_type_rules)
      and not exists (select 1 from pipeline.manual_locks l where l.entity = 'provider' and l.entity_id = pr.id and l.field = 'provider_type_id')
  ), f as (
    select p.*,
      (select value from catalogue.provider_register_facts x where x.provider_id = p.id and x.fact_code = 'teqsa_category') teqsa_category,
      (select value from catalogue.provider_register_facts x where x.provider_id = p.id and x.fact_code = 'teqsa_status') teqsa_status,
      (select value from catalogue.provider_register_facts x where x.provider_id = p.id and x.fact_code = 'cricos_institution_type') register_type,
      (select value from catalogue.provider_register_facts x where x.provider_id = p.id and x.fact_code = 'nzqa_org_type') nz_org_type,
      security.provider_course_profile_v1(p.id) prof
    from p
  ), calc as (
    select f.id, r.result_type, r.label rule_label,
      (select t.id from ref.provider_types t where t.code = r.result_type) type_id,
      case when r.id is null then
        'No rule matched: ' || concat_ws(', ',
          case when f.cc = 'AU' then 'TEQSA ' || coalesce(f.teqsa_category || ' (' || coalesce(f.teqsa_status, '?') || ')', 'none') end,
          case when f.cc = 'AU' then 'CRICOS ' || coalesce(nullif(f.register_type, ''), 'none') end,
          case when f.cc = 'NZ' then 'NZQA ' || coalesce(nullif(f.nz_org_type, ''), 'none') end,
          case when (f.prof->>'courses')::int = 0 then 'no active courses' else
            nullif(concat_ws('/', case when (f.prof->>'vet')::boolean then 'VET' end, case when (f.prof->>'school')::boolean then 'school' end,
                      case when (f.prof->>'non_aqf_only')::boolean then 'non-AQF only' end), '') end)
      end reason
    from f
    left join lateral (
      select ru.* from pipeline.provider_type_rules ru
      where ru.enabled and ru.country_code = f.cc
        and (ru.teqsa_category is null or coalesce(f.teqsa_category, '') ~* ru.teqsa_category)
        and (ru.teqsa_status is null or coalesce(f.teqsa_status, '') ~* ru.teqsa_status)
        and (ru.register_type is null or coalesce(f.register_type, '') ~* ru.register_type)
        and (ru.nz_org_type is null or coalesce(f.nz_org_type, '') ~* ru.nz_org_type)
        and (ru.course_profile is null
             or (ru.course_profile = 'vet' and (f.prof->>'vet')::boolean)
             or (ru.course_profile = 'school_no_vet' and (f.prof->>'school')::boolean and not (f.prof->>'vet')::boolean)
             or (ru.course_profile = 'non_aqf_only' and (f.prof->>'courses')::int > 0 and (f.prof->>'non_aqf_only')::boolean))
      order by ru.position limit 1
    ) r on true
  ), set_type as (
    update catalogue.providers pr
       set provider_type_id = c.type_id, provider_type_basis = c.rule_label, provider_type_set_at = now()
      from calc c
     where pr.id = c.id and c.result_type is not null
       and (pr.provider_type_id is distinct from c.type_id or pr.provider_type_basis is distinct from c.rule_label)
    returning 1
  ), set_reason as (
    update catalogue.providers pr
       set provider_type_id = null, provider_type_basis = c.reason, provider_type_set_at = now()
      from calc c
     where pr.id = c.id and c.result_type is null
       and (pr.provider_type_id is not null or pr.provider_type_basis is distinct from c.reason)
    returning 1
  )
  select jsonb_build_object(
    'classified', (select count(*) from calc where result_type is not null),
    'no_rule', (select count(*) from calc where result_type is null),
    'by_type', (select jsonb_object_agg(coalesce(result_type, 'none'), n) from (select result_type, count(*) n from calc group by 1) z),
    'changed', (select count(*) from set_type), 'reason_updated', (select count(*) from set_reason), 'at', now())
  into v_out;
  return v_out;
end $$;


ALTER FUNCTION "security"."provider_type_classify_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_university_groups"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'ref'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('code',replace(ic.code,'au_',''),'name',ic.name) order by ic.name),'[]'::jsonb)
    from catalogue.provider_collection_memberships m join ref.institution_collections ic on ic.id=m.collection_id
   where m.provider_id=p_provider_id and m.status='active' and ic.collection_type='university_group' and ic.status='active'
     and (m.valid_to is null or m.valid_to>=current_date)
$$;


ALTER FUNCTION "security"."provider_university_groups"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_website_adopt_v1"("p_provider_id" "uuid", "p_url" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_url text := btrim(coalesce(p_url, '')); v_dom text;
begin
  if v_url !~* '^https?://[^\s/]+\.[^\s]+$' or security.third_party_host_v1(v_url) then return false; end if;
  if exists (select 1 from pipeline.manual_locks l where l.entity = 'provider' and l.entity_id = p_provider_id and l.field = 'website') then return false; end if;
  update catalogue.providers set website = v_url, updated_at = now() where id = p_provider_id and nullif(btrim(website), '') is null;
  if not found then return false; end if;
  v_dom := lower(regexp_replace(substring(v_url from '^(?:https?://)?([^/:?#]+)'), '^www\.', ''));
  if v_dom ~ '^[a-z0-9.-]+\.[a-z]{2,}$' then
    insert into pipeline.course_link_recipes(provider_id, search_domain, patterns, active, notes, updated_at)
    select p_provider_id, v_dom,
           jsonb_build_array(jsonb_build_object(
             're', '(?i)^https?://([a-z0-9-]+\.)*' || regexp_replace(v_dom, '\.', '\\.', 'g')
                   || '/(?!.*\.(pdf|docx?|xlsx?|pptx?|jpe?g|png|gif|svg|zip)$)(?!(.*/)?(news|events?|blog|staff|people|media|search|tags?|category)(/|$)).+$',
             'rep', '\&')),
           true, 'Generic recipe: any page on the provider''s own site, from a website found and verified by search; used only when the reader proves the page is the course''s (CF-247, 11 Oct 2026)', now()
    on conflict (provider_id) do update set search_domain = excluded.search_domain, patterns = excluded.patterns, active = true, notes = excluded.notes, updated_at = now()
     where not pipeline.course_link_recipes.active and pipeline.course_link_recipes.notes like 'Generic recipe%';
    insert into pipeline.course_link_search(course_id, provider_id, stage, state, queued_at)
    select c.id, c.provider_id, case when c.course_code ~ '^[0-9]{6}[0-9A-Z]$' then 'cricos' else 'title' end, 'queued', now()
      from catalogue.courses c
     where c.provider_id = p_provider_id and c.lifecycle_status = 'active'
       and exists (select 1 from pipeline.course_link_recipes x where x.provider_id = p_provider_id and x.active)
       and not exists (select 1 from pipeline.coverage_course_pages g where g.course_id = c.id)
    on conflict (course_id) do nothing;
  end if;
  insert into pipeline.provider_central_search(provider_id, state, requested_at) values (p_provider_id, 'queued', now())
  on conflict (provider_id) do update set state = 'queued', requested_at = now(), leased_until = null, updated_at = now() where pipeline.provider_central_search.state <> 'leased';
  return true;
end $_$;


ALTER FUNCTION "security"."provider_website_adopt_v1"("p_provider_id" "uuid", "p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_website_change_apply_v1"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_c pipeline.provider_website_checks%rowtype; v_url text; v_old text; v_dom text; v_old_dom text; v_extra text; v_rec pipeline.course_link_recipes%rowtype;
        v_requeued int := 0; v_old_pages int := 0; v_recipe text; v_note jsonb;
begin
  select * into v_c from pipeline.provider_website_checks c where c.id = p_id for update;
  if v_c.action <> 'change' or v_c.applied or v_c.verdict not in ('verified', 'likely') then return null; end if;
  v_url := coalesce(nullif(v_c.result->>'final_url', ''), regexp_replace(v_c.url, '^(https?://[^/?#]+).*$', '\1'));
  select nullif(btrim(p.website), '') into v_old from catalogue.providers p where p.id = v_c.provider_id;
  v_dom := security.site_host_v1(v_url);
  v_old_dom := security.site_host_v1((security.provider_website_list_v1(v_old))[1]);
  select * into v_rec from pipeline.course_link_recipes r where r.provider_id = v_c.provider_id;
  perform set_config('request.jwt.claims', jsonb_build_object('sub', v_c.requested_by::text, 'role', 'authenticated')::text, true);
  perform public.admin_provider_website_set(v_c.provider_id, v_url);
  perform set_config('request.jwt.claims', '', true);
  -- the generic recipe follows the new address; a recipe built for this provider's site by hand or by an adapter is kept
  -- (with none before, admin_provider_website_set has just created the generic one)
  if v_rec.provider_id is not null and v_dom is not null and v_rec.search_domain <> v_dom then
    if coalesce(v_rec.notes, '') like 'Generic recipe%' then
      update pipeline.course_link_recipes set search_domain = v_dom, active = true, updated_at = now(), updated_by = v_c.requested_by,
             patterns = jsonb_build_array(jsonb_build_object(
               're', '(?i)^https?://([a-z0-9-]+\.)*' || regexp_replace(v_dom, '\.', '\\.', 'g')
                     || '/(?!.*\.(pdf|docx?|xlsx?|pptx?|jpe?g|png|gif|svg|zip)$)(?!(.*/)?(news|events?|blog|staff|people|media|search|tags?|category)(/|$)).+$',
               'rep', '\&')),
             notes = 'Generic recipe: any page on the provider''s own site, from a website changed and checked in the Adapter builder (bug 18/10-01, 18 Oct 2026)'
       where provider_id = v_c.provider_id;
      v_recipe := 'moved to ' || v_dom;
    else
      v_recipe := 'kept: a recipe built for ' || v_rec.search_domain || ' (review it in step 3)';
    end if;
  else
    v_recipe := case when v_rec.provider_id is not null then 'unchanged' when exists (select 1 from pipeline.course_link_recipes r where r.provider_id = v_c.provider_id) then 'created for ' || v_dom else 'none' end;
  end if;
  -- a second site of the same provider: its pages are accepted as course pages too
  v_extra := security.site_host_v1(v_c.extra_site);
  if v_extra is not null and v_extra <> coalesce(v_dom, '') then
    update pipeline.course_link_recipes set updated_at = now(), updated_by = v_c.requested_by,
           patterns = patterns || jsonb_build_array(jsonb_build_object(
             're', '(?i)^https?://([a-z0-9-]+\.)*' || regexp_replace(v_extra, '\.', '\\.', 'g')
                   || '/(?!.*\.(pdf|docx?|xlsx?|pptx?|jpe?g|png|gif|svg|zip)$)(?!(.*/)?(news|events?|blog|staff|people|media|search|tags?|category)(/|$)).+$',
             'rep', '\&', 'extra_site', v_extra))
     where provider_id = v_c.provider_id and not (patterns::text like '%"extra_site": "' || v_extra || '"%');
  end if;
  -- searches that found nothing on the old address are tried again on the new one
  update pipeline.course_link_search s set state = 'queued', attempts = 0, query = null, results = null, candidates = null, cand_idx = null, req_id = null,
         bound_url = null, sent_at = null, done_at = null, queued_at = now(), requested_at = now()
   where s.provider_id = v_c.provider_id and s.state = 'none'
     and exists (select 1 from catalogue.courses c where c.id = s.course_id and c.lifecycle_status = 'active')
     and not exists (select 1 from pipeline.coverage_course_pages g where g.course_id = s.course_id);
  get diagnostics v_requeued = row_count;
  -- 18 Oct: every queued search of this provider counts as asked for, so it runs first and for any provider
  update pipeline.course_link_search set requested_at = now() where provider_id = v_c.provider_id and state = 'queued' and requested_at is null;
  -- a stopped or held course-page search is resumed, as Search again does
  insert into pipeline.firecrawl_search_resumes(provider_id, reason, set_by)
  values (v_c.provider_id, left('Website changed in the Adapter builder: ' || coalesce(v_c.reason, ''), 400), v_c.requested_by);
  -- Fill in from website: contacts and central pages are looked for again
  insert into pipeline.provider_central_search(provider_id, state, requested_at) values (v_c.provider_id, 'queued', now())
  on conflict (provider_id) do update set state = 'queued', requested_at = now(), leased_until = null, attempts = 0, updated_at = now();
  update pipeline.provider_contact_checks set checked_at = now() - interval '91 days', outcome = 'requested'  -- fixed: one day past the contacts re-check window, as Fill in from website does
   where provider_id = v_c.provider_id and kind = 'public_general';
  -- course pages already found on the old address are left for the relink step
  if v_old_dom is not null and v_old_dom <> coalesce(v_dom, '') then
    select count(*) into v_old_pages from pipeline.coverage_course_pages g join catalogue.courses c on c.id = g.course_id
     where c.provider_id = v_c.provider_id and security.site_host_v1(g.url) like '%' || v_old_dom;
  end if;
  v_note := jsonb_build_object('saved', v_url, 'before', v_old, 'recipe', v_recipe, 'extra_site', v_extra, 'searches_queued', v_requeued,
                               'search_resumed', true, 'contacts_and_central_pages', 'queued', 'pages_on_old_address', v_old_pages);
  update pipeline.provider_website_checks set applied = true, applied_at = now(), apply_note = v_note where id = p_id;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('provider', 'website_change', v_c.provider_id::text, v_note || jsonb_build_object('reason', v_c.reason, 'verdict', v_c.verdict, 'why', v_c.why, 'check_id', p_id, 'change', 'CF-247 bug 18/10-01'), v_c.requested_by);
  return v_note;
end $_$;


ALTER FUNCTION "security"."provider_website_change_apply_v1"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_website_check_kick_v1"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not exists (select 1 from pipeline.provider_website_checks c where c.state = 'queued' or (c.state = 'leased' and c.leased_until < now())) then return false; end if;
  perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'site_check', 'limit', security.pipeline_num_v1('batch.website_check', 5)::int));
  return true;
end $$;


ALTER FUNCTION "security"."provider_website_check_kick_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_website_list_v1"("p_website" "text") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select coalesce(array_agg(case when x ~* '^https?://' then x else 'https://' || x end order by n), '{}')
    from (select btrim(x) x, n from regexp_split_to_table(coalesce(p_website, ''), '\s*(,|;|\s+and\s+|\s)\s*') with ordinality t(x, n)) s
   where s.x ~* '^(https?://)?[a-z0-9-]+(\.[a-z0-9-]+)+(/\S*)?$'
$_$;


ALTER FUNCTION "security"."provider_website_list_v1"("p_website" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."provider_website_verdict_v1"("p_result" "jsonb", OUT "verdict" "text", OUT "why" "text") RETURNS "record"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case when not coalesce((p_result->>'answers')::boolean, false) then 'failed'
              when coalesce((p_result->>'third_party')::boolean, false) then 'failed'
              when coalesce((p_result->>'cricos_on_site')::boolean, false) or coalesce((p_result->>'register_match')::boolean, false)
                   or p_result->>'name_basis' = 'dli_number' then 'verified'
              when nullif(p_result->>'name_basis', '') is not null or coalesce((p_result->>'domain_fits')::boolean, false) then 'likely'
              else 'failed' end,
         case when not coalesce((p_result->>'answers')::boolean, false) then 'the home page did not answer' || coalesce(' (' || nullif(p_result->>'http', '') || ')', '')
              when coalesce((p_result->>'third_party')::boolean, false) then 'a third-party site (a course directory or similar), not the provider''s own'
              when coalesce((p_result->>'cricos_on_site')::boolean, false) then 'the provider''s CRICOS code ' || coalesce(p_result->>'cricos_code', '') || ' is on the home page'
              when coalesce((p_result->>'register_match')::boolean, false) then 'it is the site the register lists'
              when p_result->>'name_basis' = 'dli_number' then 'the provider''s DLI number is on the home page'
              when nullif(p_result->>'name_basis', '') is not null then 'the provider''s name is on the home page' || case when nullif(p_result->>'cricos_code', '') is not null then ', but not its CRICOS code' else '' end
              when coalesce((p_result->>'domain_fits')::boolean, false) then 'the address fits the provider''s name' || case when nullif(p_result->>'cricos_code', '') is not null then ', but its CRICOS code is not on the home page' else '' end
              else 'neither the provider''s name nor its CRICOS code is on the home page' end
$$;


ALTER FUNCTION "security"."provider_website_verdict_v1"("p_result" "jsonb", OUT "verdict" "text", OUT "why" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."queue_watch_alerts_take_v1"("p_channel" "text" DEFAULT 'notify'::"text", "p_via" "text" DEFAULT 'scheduled task'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  with t as (update pipeline.queue_watch_alerts a set sent_at = now(), sent_via = p_via
              where a.sent_at is null and a.channel = p_channel returning a.*)
  select coalesce(jsonb_agg(jsonb_build_object('queue', t.key, 'state', t.state, 'title', t.title, 'body', t.body, 'raised_at', t.raised_at) order by t.raised_at), '[]'::jsonb)
    into v from t;
  return jsonb_build_object('channel', p_channel, 'alerts', v, 'count', jsonb_array_length(v));
end $$;


ALTER FUNCTION "security"."queue_watch_alerts_take_v1"("p_channel" "text", "p_via" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."queue_watch_report_v1"("p_hours" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with h as (select now() - make_interval(hours => coalesce(p_hours, security.pipeline_num_v1('queue_watch.report_hours', 24)::int)) since)
  select jsonb_build_object(
    'since', (select since from h), 'generated_at', now(),
    'queues', (select coalesce(jsonb_agg(jsonb_build_object('queue', w.key, 'label', w.label, 'area', w.area, 'state', s.state, 'since', s.since, 'reason', s.reason,
                       'waiting', s.pending, 'finished_per_hour', s.per_hour, 'eta_hours', s.eta_hours, 'nothing_left', s.exhausted,
                       'nothing_left_is', w.exhausted_label, 'last_progress', s.last_progress) order by w.sort), '[]'::jsonb)
                 from pipeline.queue_watch w join pipeline.queue_watch_state s on s.key = w.key where w.enabled),
    'changes', (select coalesce(jsonb_agg(jsonb_build_object('queue', e.key, 'at', e.at, 'from', e.from_state, 'to', e.to_state, 'reason', e.reason) order by e.at), '[]'::jsonb)
                  from pipeline.queue_watch_events e, h where e.at >= h.since),
    'fixes', (select coalesce(jsonb_agg(jsonb_build_object('queue', f.key, 'at', f.at, 'items', f.items, 'what', f.detail->>'what') order by f.at), '[]'::jsonb)
                from pipeline.queue_watch_fixes f, h where f.at >= h.since),
    'alerts', (select coalesce(jsonb_agg(jsonb_build_object('queue', a.key, 'state', a.state, 'channel', a.channel, 'title', a.title, 'body', a.body, 'raised_at', a.raised_at, 'sent_at', a.sent_at) order by a.raised_at), '[]'::jsonb)
                 from pipeline.queue_watch_alerts a, h where a.raised_at >= h.since))
$$;


ALTER FUNCTION "security"."queue_watch_report_v1"("p_hours" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."queue_watch_run_v1"("p_fix" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "statement_timeout" TO '120s'
    AS $$
declare
  q record; v_prev record; v_t0 timestamptz := clock_timestamp(); v_t timestamptz;
  v_win interval := make_interval(mins => security.pipeline_num_v1('queue_watch.window_minutes', 60)::int);
  v_stuck_default interval := make_interval(mins => security.pipeline_num_v1('queue_watch.stuck_minutes', 120)::int);
  v_fail_pct numeric := security.pipeline_num_v1('queue_watch.fail_percent', 50);
  v_fail_min numeric := security.pipeline_num_v1('queue_watch.fail_min', 5);
  v_repeat interval := make_interval(hours => security.pipeline_num_v1('queue_watch.alert_repeat_hours', 12)::int);
  v_retry_n int := security.pipeline_num_v1('queue_watch.retry_batch', 25)::int;
  v_retry_since timestamptz := now() - make_interval(days => security.pipeline_num_v1('queue_watch.retry_days', 7)::int);
  v_retry_before timestamptz := now() - make_interval(hours => security.pipeline_num_v1('queue_watch.retry_after_hours', 6)::int);
  v_pending bigint; v_done bigint; v_failed bigint; v_exh bigint; v_last timestamptz; v_state text; v_reason text;
  v_out text[]; v_wait text[]; v_paused text[]; v_idle text[]; v_tool text; v_ts text; v_fixed int; v_err text; v_cap text;
  v_rate numeric; v_eta numeric; v_summary jsonb := '[]'::jsonb; v_fixes int := 0; v_alerts int := 0; v_changes int := 0; v_title text; v_body text;
begin
  for q in select * from pipeline.queue_watch w where w.enabled order by w.sort loop
    v_t := clock_timestamp(); v_err := null; v_out := '{}'; v_wait := '{}'; v_paused := '{}'; v_idle := '{}'; v_fixed := 0;
    v_pending := null; v_done := null; v_failed := null; v_exh := null; v_last := null; v_state := null; v_reason := null; v_cap := null;
    select * into v_prev from pipeline.queue_watch_state s where s.key = q.key;
    begin
      execute q.pending_sql into v_pending;
      execute q.progress_sql into v_last;
      execute q.done_sql into v_done using now() - v_win;
      execute q.failed_sql into v_failed using now() - v_win;
      execute q.exhausted_sql into v_exh;
      if q.cap_sql is not null then execute q.cap_sql into v_cap; end if;  -- SS-014 P2 (2 Nov 2026): a configured cap holding the queue
      foreach v_tool in array q.tools loop
        v_ts := security.queue_watch_tool_state_v1(v_tool);
        if v_ts = 'out' then v_out := v_out || v_tool; elsif v_ts = 'waiting' then v_wait := v_wait || v_tool; end if;
      end loop;
      -- a job switched off by a person (no open waste-guard flag) pauses the queue; a job paused by the waste guard does not
      select coalesce(array_agg(j.jobname) filter (where not j.active and not exists (select 1 from pipeline.enrichment_flags f where f.entity = 'job' and f.entity_key = j.jobname and f.state = 'raised')), '{}'),
             coalesce(array_agg(j.jobname) filter (where exists (select 1 from pipeline.enrichment_flags f where f.entity = 'job' and f.entity_key = j.jobname and f.state = 'raised')), '{}')
        into v_paused, v_idle
        from cron.job j where j.jobname = any(q.jobnames);
      if cardinality(q.jobnames) > 0 and cardinality(v_paused) = cardinality(q.jobnames) then
        v_state := 'paused'; v_reason := 'Switched off by a person: ' || array_to_string(v_paused, ', ');
      elsif v_pending > 0 and v_cap is not null then
        v_state := 'capped'; v_reason := v_cap;  -- SS-014 P2 (2 Nov 2026): "Paused: daily cap", not stuck; no alert, no health issue
      elsif v_pending > 0 and v_done = 0 and coalesce(v_last, '-infinity') < now() - v_stuck_default and cardinality(v_out) > 0 then
        v_state := 'out_of_toolset'; v_reason := 'Work is waiting but ' || array_to_string(v_out, ', ') || ' cannot be used until a person acts (credit or balance used up)';
      elsif v_pending > 0 and v_done = 0 and coalesce(v_last, '-infinity') < now() - v_stuck_default and cardinality(v_wait) > 0 then
        v_state := 'waiting'; v_reason := 'Today''s budget for ' || array_to_string(v_wait, ', ') || ' is used up; it carries on when the budget comes back';
      elsif v_failed >= v_fail_min and v_failed * 100.0 / greatest(1, v_failed + v_done) >= v_fail_pct then
        v_state := 'failing'; v_reason := v_failed || ' of ' || (v_failed + v_done) || ' tried in the last ' || extract(epoch from v_win)::int / 60 || ' minutes failed';
      elsif v_pending > 0 and v_done = 0 and coalesce(v_last, '-infinity') < now() - v_stuck_default then
        v_state := 'stuck'; v_reason := v_pending || ' waiting and nothing finished since ' || coalesce(to_char(v_last at time zone 'Australia/Melbourne', 'DD Mon HH24:MI'), 'it started')
          || case when cardinality(v_idle) > 0 then '; paused by the waste guard: ' || array_to_string(v_idle, ', ') else '' end;
      elsif v_pending > 0 then
        v_state := 'moving'; v_reason := null;
      elsif v_exh > 0 then
        v_state := 'nothing_left'; v_reason := v_exh || ' ' || lower(coalesce(q.exhausted_label, 'items with nothing left to try'));
      else
        v_state := 'done'; v_reason := null;
      end if;
      -- safe fix: one more try for items that gave up on a passing error, never while a tool of the queue is out or waiting
      if p_fix and q.retry_sql is not null and v_retry_n > 0 and cardinality(v_out) = 0 and cardinality(v_wait) = 0 and v_state <> 'paused' then
        execute q.retry_sql into v_fixed using v_retry_n, v_retry_since, v_retry_before;
        if coalesce(v_fixed, 0) > 0 then
          insert into pipeline.queue_watch_fixes(key, fix, items, detail) values (q.key, 'one_more_try', v_fixed, jsonb_build_object('what', q.retry_label, 'state', v_state));
          v_fixes := v_fixes + v_fixed;
          if v_state in ('nothing_left', 'done') then v_state := 'moving'; v_reason := v_fixed || ' given one more try'; v_pending := v_pending + v_fixed; end if;
        end if;
      end if;
    exception when others then
      v_err := left(sqlerrm, 300); v_state := coalesce(v_prev.state, 'moving'); v_reason := 'The watchdog could not check this queue: ' || v_err;
    end;
    v_rate := round(v_done * 60.0 / greatest(1, extract(epoch from v_win) / 60), 1);
    v_eta := case when v_pending > 0 and v_rate > 0 then round(v_pending / v_rate, 1) end;
    insert into pipeline.queue_watch_state as s(key, state, since, reason, pending, done_window, failed_window, exhausted, last_progress, per_hour, eta_hours,
                                               tools_out, tools_waiting, jobs_paused, check_ms, checked_at, error)
    values (q.key, v_state, now(), v_reason, v_pending, v_done, v_failed, v_exh, v_last, v_rate, v_eta, v_out, v_wait, v_paused || v_idle,
            round(extract(epoch from clock_timestamp() - v_t) * 1000), now(), v_err)
    on conflict (key) do update set state = excluded.state, since = case when s.state = excluded.state then s.since else now() end, reason = excluded.reason,
      pending = excluded.pending, done_window = excluded.done_window, failed_window = excluded.failed_window, exhausted = excluded.exhausted,
      last_progress = excluded.last_progress, per_hour = excluded.per_hour, eta_hours = excluded.eta_hours, tools_out = excluded.tools_out,
      tools_waiting = excluded.tools_waiting, jobs_paused = excluded.jobs_paused, check_ms = excluded.check_ms, checked_at = now(), error = excluded.error;

    if v_err is null and (v_prev.state is null or v_prev.state is distinct from v_state) then
      insert into pipeline.queue_watch_events(key, from_state, to_state, reason, detail)
      values (q.key, v_prev.state, v_state, v_reason, jsonb_build_object('pending', v_pending, 'finished_window', v_done, 'failed_window', v_failed, 'nothing_left', v_exh));
      v_changes := v_changes + 1;
    end if;

    -- alerts: Stuck and Out of toolset to phone and email (again after queue_watch.alert_repeat_hours); Done and Nothing left to try to the report
    if v_err is null then
      v_title := q.label || ': ' || case v_state when 'stuck' then 'stuck' when 'out_of_toolset' then 'out of toolset' when 'done' then 'done'
                                                 when 'nothing_left' then 'nothing left to try' else v_state end;
      v_body := coalesce(v_reason, '') || case when v_pending > 0 then ' · ' || v_pending || ' waiting' else '' end;
      if v_state in ('stuck', 'out_of_toolset')
         and not exists (select 1 from pipeline.queue_watch_alerts a where a.key = q.key and a.state = v_state and a.channel = 'notify' and a.raised_at > now() - v_repeat
                           and a.raised_at >= (select max(e.at) from pipeline.queue_watch_events e where e.key = q.key)) then
        insert into pipeline.queue_watch_alerts(key, state, channel, title, body) values (q.key, v_state, 'notify', v_title, v_body);
        v_alerts := v_alerts + 1;
      elsif v_state in ('done', 'nothing_left') and v_prev.state is distinct from v_state and v_prev.state is not null then
        insert into pipeline.queue_watch_alerts(key, state, channel, title, body) values (q.key, v_state, 'report', v_title, v_body);
      end if;
      -- Platform health issue while Stuck, Failing or Out of toolset; closed when it is not
      if v_state in ('stuck', 'failing', 'out_of_toolset') then
        insert into pipeline.platform_issues as i(check_key, severity, area, title, detail)
        values ('queue_watch:' || q.key, case when v_state = 'out_of_toolset' then 'critical' else 'warning' end,
                case when q.area = 'Scholarships' then 'scholarships' else 'coverage sweep' end, left(v_title, 300),  -- the issue areas the health page groups by
                jsonb_build_object('reason', v_reason, 'waiting', v_pending, 'last_progress', v_last, 'resolve', q.fix_at))
        on conflict (check_key) where resolved_at is null do update set severity = excluded.severity, title = excluded.title, detail = excluded.detail,
          last_seen = now(), occurrences = i.occurrences + 1;
      else
        update pipeline.platform_issues i set resolved_at = now() where i.check_key = 'queue_watch:' || q.key and i.resolved_at is null;
      end if;
    end if;
    v_summary := v_summary || jsonb_build_object('queue', q.key, 'state', v_state, 'pending', v_pending);
  end loop;

  update pipeline.platform_health_checks c set
    status = case when exists (select 1 from pipeline.queue_watch_state s where s.state = 'out_of_toolset') then 'critical'
                  when exists (select 1 from pipeline.queue_watch_state s where s.state in ('stuck', 'failing')) then 'warning' else 'ok' end,
    detail = (select jsonb_build_object('queues', count(*), 'moving', count(*) filter (where s.state = 'moving'), 'stuck', count(*) filter (where s.state = 'stuck'),
                     'failing', count(*) filter (where s.state = 'failing'), 'out_of_toolset', count(*) filter (where s.state = 'out_of_toolset'),
                     'waiting_for_budget', count(*) filter (where s.state = 'waiting'), 'nothing_left', count(*) filter (where s.state = 'nothing_left'),
                     'done', count(*) filter (where s.state = 'done'), 'paused', count(*) filter (where s.state = 'paused'), 'paused_daily_cap', count(*) filter (where s.state = 'capped'))
                from pipeline.queue_watch_state s join pipeline.queue_watch w on w.key = s.key and w.enabled),
    checked_at = now(), duration_ms = round(extract(epoch from clock_timestamp() - v_t0) * 1000)
   where c.key = 'queue_watch';
  return jsonb_build_object('queues', v_summary, 'changes', v_changes, 'alerts', v_alerts, 'fixed', v_fixes, 'ms', round(extract(epoch from clock_timestamp() - v_t0) * 1000));
end $$;


ALTER FUNCTION "security"."queue_watch_run_v1"("p_fix" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."queue_watch_tool_state_v1"("p_tool" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_kind text := split_part(p_tool, ':', 1); v_part text := split_part(p_tool, ':', 2); v_fc jsonb; v_bal numeric; v_floor numeric; v_mode text; g record;
begin
  if v_kind = 'firecrawl' then
    select c.detail->'firecrawl' into v_fc from pipeline.platform_health_checks c where c.key = 'budgets';
    if v_fc ? 'remaining' and v_fc ? 'reserve' and (v_fc->>'remaining')::numeric <= (v_fc->>'reserve')::numeric then return 'out'; end if;
    if security.fc_budget_left_v1(case v_part when 'course_search' then 'course_link_search' when 'reads' then 'scrape' when 'central' then 'central_map'
                                             when 'scholarships' then 'sch_map' else 'map' end) <= 0 then return 'waiting'; end if;
    return 'ok';
  elsif v_kind = 'ai' then
    select t.enforcement into v_mode from pipeline.platform_toolsets t where t.key = 'openrouter';
    if coalesce(v_mode, 'observe') <> 'stop' then return 'ok'; end if;
    select o.remaining_usd into v_bal from pipeline.layer3_openrouter_observations o where o.kind = 'credits' order by o.observed_at desc limit 1;  -- fixed: the latest reading
    v_floor := coalesce((security.toolset_setting('openrouter', 'credit_floor_usd'))::text::numeric, 0);
    if v_bal is not null and v_bal < v_floor then return 'out'; end if;
    select * into g from security.ai_spend_today_v1() x where x.use = v_part;
    if coalesce(g.guard, 0) > 0 and coalesce(g.spent, 0) >= g.guard then return 'waiting'; end if;
    return 'ok';
  end if;
  return 'ok';
end $$;


ALTER FUNCTION "security"."queue_watch_tool_state_v1"("p_tool" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."quoted_study_periods"("p_quotes" "text") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $_$
  select coalesce(array_agg(distinct p order by p), '{}') from (
    select regexp_replace(lower(m[1]), '^(study|teaching) period$', '\1_period') || ' ' ||
           case lower(n) when 'one' then '1' when 'two' then '2' when 'three' then '3' when 'four' then '4'
                         when 'i' then '1' when 'ii' then '2' when 'iii' then '3' else n end p
      from regexp_matches(coalesce(p_quotes, ''), '\m(semester|trimester|term|session|study period|teaching period)s?\s+(\d|one|two|three|four|iii|ii|i)\M((?:\s*(?:&|and|,|/)\s*(?:\d)\M)*)', 'gi') m
      cross join lateral unnest(array[m[2]] || coalesce((select array_agg(x[1]) from regexp_matches(coalesce(m[3], ''), '(\d)', 'g') x), '{}')) n) s
$_$;


ALTER FUNCTION "security"."quoted_study_periods"("p_quotes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ranking_country_id"("p" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select c.id from ref.countries c
   where lower(c.name) = lower(btrim(p)) or lower(c.iso_alpha2::text) = lower(btrim(p)) or lower(c.iso_alpha3::text) = lower(btrim(p))
   order by (lower(c.name) = lower(btrim(p))) desc limit 1
$$;


ALTER FUNCTION "security"."ranking_country_id"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ranking_edition_check_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_grace int := security.pipeline_num_v1('ranking.edition_grace_days', 30)::int;
        v_age int := security.pipeline_num_v1('ranking.import_max_age_days', 400)::int;
        v_cal text[] := security.pipeline_list_v1('ranking.edition_calendar', '["qs_wur:6:1", "the_wur:10:1", "arwu:8:0"]');
        r record; i record; v_month int; v_off int; v_y int; v_expect int; v_held int; v_last timestamptz; v_why text[]; v_fp text;
        v_seen text[] := '{}'; v_out jsonb := '[]'::jsonb;
begin
  if not pg_try_advisory_xact_lock(hashtext('ranking-edition-check')) then return jsonb_build_object('skipped', 'running'); end if;  -- fixed: lock key
  for r in select s.id, s.code, s.publisher_name, s.ranking_name, s.official_url from ranking.systems s where s.active order by s.code loop
    v_month := null; v_off := null; v_expect := null;
    select nullif(split_part(c, ':', 2), '')::int, coalesce(nullif(split_part(c, ':', 3), '')::int, 0) into v_month, v_off
      from unnest(v_cal) c where split_part(c, ':', 1) = r.code and split_part(c, ':', 2) ~ '^[0-9]{1,2}$' and split_part(c, ':', 3) ~ '^-?[0-9]*$' limit 1;
    if v_month between 1 and 12 then
      v_y := extract(year from now() at time zone 'UTC')::int;  -- fixed: the calendar year is counted in UTC
      v_expect := case when now() >= make_timestamptz(v_y, v_month, 1, 0, 0, 0, 'UTC') + make_interval(days => v_grace) then v_y else v_y - 1 end + v_off;
    end if;
    select max(e.edition_year) into v_held from ranking.editions e where e.system_id = r.id and e.status = 'accepted';
    select max(m.uploaded_at) into v_last from ranking.manual_imports m where m.system_id = r.id;
    v_why := '{}';
    if v_expect is not null and (v_held is null or v_held < v_expect) then
      v_why := v_why || ('edition ' || v_expect || ' is out by the publisher''s calendar; ' || coalesce('latest held ' || v_held, 'no edition held'));
    end if;
    if v_last is null or v_last < now() - make_interval(days => v_age) then
      v_why := v_why || ('last file import ' || coalesce(to_char(v_last, 'YYYY-MM-DD'), 'never') || ' (older than ' || v_age || ' days)');
    end if;
    if cardinality(v_why) > 0 then
      v_fp := 'ranking_edition:' || r.code;
      perform security.integration_issue_upsert_v1(jsonb_build_object('fingerprint', v_fp,
        'title', r.ranking_name || ': a new edition to import', 'layer', 'Layer 1', 'subsystem', 'ranking.' || r.code,
        'failure', array_to_string(v_why, '; '),
        'expected', 'The latest edition published by ' || r.publisher_name || ' is imported from its licensed file (Rankings & statistics › Datasets). The platform does not fetch or import rankings.',
        'source', 'ranking-edition-check', 'validation_layer', 'V4',
        'evidence', jsonb_build_object('system', r.code, 'expected_edition', v_expect, 'held_edition', v_held, 'last_import', v_last, 'official_url', r.official_url),
        'severity', 'P2', 'root_cause_class', 'missing_dependency', 'workstream', 'A10'), 'ranking-edition-check');
      v_seen := v_seen || v_fp;
    end if;
    v_out := v_out || jsonb_build_object('system', r.code, 'expected', v_expect, 'held', v_held, 'last_import', v_last, 'issue', cardinality(v_why) > 0);
  end loop;
  for i in select x.id, x.fingerprint, x.condition_cleared_at, x.status from pipeline.integration_issues x
            where x.status <> 'closed' and x.fingerprint like 'ranking\_edition:%' and not (x.fingerprint = any (v_seen)) loop
    if i.condition_cleared_at is null then
      update pipeline.integration_issues set condition_cleared_at = now() where id = i.id;
      insert into pipeline.integration_issue_events(issue_id, kind, from_status, to_status, actor, note)
      values (i.id, 'not_observed', i.status, i.status, 'ranking-edition-check', 'the edition is held and the import is recent; close after verification');
    end if;
  end loop;
  return jsonb_build_object('systems', v_out, 'issues', cardinality(v_seen));
end $_$;


ALTER FUNCTION "security"."ranking_edition_check_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ranking_link_apply_v1"("p_pub" "uuid", "p_provider" "uuid", "p_method" "text", "p_note" "text", "p_actor" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_pi ranking.publisher_institutions%rowtype; v_sys text; v_cur uuid; v_equiv uuid[]; v_n int := 0; o record; v_pid uuid;
begin
  select * into v_pi from ranking.publisher_institutions where id = p_pub;
  if v_pi.id is null then raise exception 'publisher institution not found'; end if;
  select code into v_sys from ranking.systems where id = v_pi.system_id;
  select provider_id into v_cur from ranking.provider_mappings where publisher_institution_id = p_pub and status = 'accepted' and valid_to is null;
  if v_cur is not null and v_cur <> p_provider then raise exception 'already linked to another provider'; end if;
  if v_cur is null then
    update ranking.provider_mappings set status = 'superseded' where publisher_institution_id = p_pub and status = 'candidate';
    insert into ranking.provider_mappings(publisher_institution_id, provider_id, mapping_method, confidence, status, reviewed_by, reviewed_at, note)
    values (p_pub, p_provider, p_method, 1.0, 'accepted', p_actor, now(), p_note);
  end if;
  v_equiv := public.svc_statistical_equivalent_provider_ids(p_provider);
  for o in select id from ranking.observations where publisher_institution_id = p_pub and provider_id is null loop
    update ranking.observations set provider_id = p_provider where id = o.id;
    foreach v_pid in array v_equiv loop
      insert into ranking.observation_provider_links(observation_id, provider_id, link_method, is_primary)
      values (o.id, v_pid, case when v_pid = p_provider then 'primary_' || p_method else 'equivalent_exact_name_or_identifier' end, v_pid = p_provider)
      on conflict do nothing;
    end loop;
    v_n := v_n + 1;
  end loop;
  insert into catalogue.provider_aliases(provider_id, alias, alias_type)
  values (p_provider, v_pi.institution_name, v_sys || '_publisher_name')
  on conflict (provider_id, alias, coalesce(locale, '')) do nothing;
  return v_n;
end $$;


ALTER FUNCTION "security"."ranking_link_apply_v1"("p_pub" "uuid", "p_provider" "uuid", "p_method" "text", "p_note" "text", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ranking_link_auto_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u record; v_ids uuid[]; v_linked int := 0; v_obs int := 0; v_cand int := 0; v_k int; v_method text;
begin
  for u in
    select pi.id, pi.institution_name, s.code sys, security.ranking_country_id(pi.country_text) cid,
           lower(regexp_replace(pi.institution_name, '[^A-Za-z0-9]+', '', 'g')) compact, security.ranking_name_key(pi.institution_name) nkey
      from ranking.publisher_institutions pi join ranking.systems s on s.id = pi.system_id
     where not exists (select 1 from ranking.provider_mappings m where m.publisher_institution_id = pi.id and m.status = 'accepted' and m.valid_to is null)
       and exists (select 1 from catalogue.providers p where p.country_id = security.ranking_country_id(pi.country_text) and p.lifecycle_status = 'active')
  loop
    v_method := null;
    -- 1. exact name
    select array_agg(p.id) into v_ids from catalogue.providers p
     where p.country_id = u.cid and p.lifecycle_status = 'active'
       and lower(regexp_replace(coalesce(p.display_name, p.canonical_name), '[^A-Za-z0-9]+', '', 'g')) = u.compact;
    if cardinality(v_ids) = 1 then v_method := 'exact_canonical_name_country'; end if;
    -- 2. exact alias
    if v_method is null then
      select array_agg(distinct p.id) into v_ids from catalogue.provider_aliases a join catalogue.providers p on p.id = a.provider_id
       where p.country_id = u.cid and p.lifecycle_status = 'active' and a.valid_to is null
         and lower(regexp_replace(a.alias, '[^A-Za-z0-9]+', '', 'g')) = u.compact;
      if cardinality(v_ids) = 1 then v_method := 'accepted_alias_country'; end if;
    end if;
    -- 3. name key, confirmed by an existing link under the same key
    if v_method is null and u.nkey <> '' then
      select array_agg(distinct x.id) into v_ids from (
        select p.id from catalogue.providers p where p.country_id = u.cid and p.lifecycle_status = 'active'
           and security.ranking_name_key(coalesce(p.display_name, p.canonical_name)) = u.nkey
        union
        select p.id from catalogue.provider_aliases a join catalogue.providers p on p.id = a.provider_id
         where p.country_id = u.cid and p.lifecycle_status = 'active' and a.valid_to is null and security.ranking_name_key(a.alias) = u.nkey) x;
      if cardinality(v_ids) = 1 and exists (
           select 1 from ranking.publisher_institutions o join ranking.provider_mappings m on m.publisher_institution_id = o.id
            where o.id <> u.id and m.status = 'accepted' and m.valid_to is null and m.provider_id = v_ids[1]
              and security.ranking_name_key(o.institution_name) = u.nkey) then
        v_method := 'name_key_confirmed';
      end if;
    end if;
    if v_method is not null then
      v_obs := v_obs + security.ranking_link_apply_v1(u.id, v_ids[1], v_method, 'Linked automatically (Decision 208 rules)', null);
      v_linked := v_linked + 1;
    else
      -- candidates for a person: providers in the same country sharing most words (at least half of all words)
      insert into ranking.provider_mappings(publisher_institution_id, provider_id, mapping_method, confidence, status, note)
      select u.id, c.id, 'suggested_shared_words', round(c.score, 2), 'candidate', 'Offered for a person to check'
        from (select p.id, (select count(*) from unnest(security.ranking_name_words(u.institution_name)) w where w = any(security.ranking_name_words(coalesce(p.display_name, p.canonical_name))))::numeric
                     / greatest(1, (select count(distinct w) from unnest(security.ranking_name_words(u.institution_name) || security.ranking_name_words(coalesce(p.display_name, p.canonical_name))) w)) score
                from catalogue.providers p where p.country_id = u.cid and p.lifecycle_status = 'active'
                 and security.ranking_name_words(coalesce(p.display_name, p.canonical_name)) && security.ranking_name_words(u.institution_name)) c
       where c.score >= 0.5
         and not exists (select 1 from ranking.provider_mappings m where m.publisher_institution_id = u.id and m.provider_id = c.id)
       order by c.score desc limit 3;
      get diagnostics v_k = row_count;
      v_cand := v_cand + v_k;
    end if;
  end loop;
  return jsonb_build_object('linked', v_linked, 'observations_linked', v_obs, 'candidates_added', v_cand, 'ran_at', now());
end $$;


ALTER FUNCTION "security"."ranking_link_auto_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ranking_name_key"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select regexp_replace(regexp_replace(regexp_replace(translate(lower(split_part(coalesce(p, ''), '|', 1)), 'àáâãäåāçćčèéêëēěìíîïīñńòóôõöøōùúûüūýÿžšœæ’', 'aaaaaaaccceeeeeeiiiiinnooooooouuuuuyyzsoa'''), '\([^)]*\)', '', 'g'), '^\s*the\s+', ''), '[^a-z0-9]+', '', 'g')
$$;


ALTER FUNCTION "security"."ranking_name_key"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."ranking_name_words"("p" "text") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(array_agg(distinct w), '{}') from regexp_split_to_table(regexp_replace(translate(lower(split_part(coalesce(p, ''), '|', 1)), 'àáâãäåāçćčèéêëēěìíîïīñńòóôõöøōùúûüūýÿžšœæ’', 'aaaaaaaccceeeeeeiiiiinnooooooouuuuuyyzsoa'''), '[^a-z0-9]+', ' ', 'g'), '\s+') w
   where length(w) > 1 and w not in ('the','of','and','at','in','for','university','universit','universite','college','institute','institut','de','du','des','la','le','les','et','school','inc','ltd','limited','campus','including')
$$;


ALTER FUNCTION "security"."ranking_name_words"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."recovery_condition_gaps_v1"("p_deep" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int := security.pipeline_num_v1('recovery.gap_sample', 10)::int; v_dead int := security.pipeline_num_v1('frv.verify_deadline_hours', 24)::int; v jsonb;
begin
  v := jsonb_build_object(
    'work_items_no_condition', jsonb_build_object(
      'count', (select count(*) from pipeline.work_items w where w.stage not in ('done') and w.entity <> '*lane' and w.next_eligible_at is null
                  and w.unresolved_blocker is null and w.escalation is null and w.review_ref is null),
      'examples', (select coalesce(jsonb_agg(jsonb_build_object('id', z.id, 'lane', z.lane, 'stage', z.stage, 'entity', z.entity)), '[]'::jsonb) from (select w.id, w.lane, w.stage, w.entity
                     from pipeline.work_items w where w.stage not in ('done') and w.entity <> '*lane' and w.next_eligible_at is null and w.unresolved_blocker is null
                      and w.escalation is null and w.review_ref is null order by w.id limit v_n) z)),
    'work_items_blocked_no_next_no_escalation', jsonb_build_object(
      'count', (select count(*) from pipeline.work_items w where w.stage not in ('done') and w.entity <> '*lane' and w.next_eligible_at is null
                  and w.unresolved_blocker is not null and w.escalation is null and w.review_ref is null),
      'by_lane', (select coalesce(jsonb_object_agg(z.k, z.n), '{}'::jsonb) from (select w.lane || '/' || coalesce(w.failure_class, '?') k, count(*) n from pipeline.work_items w
                    where w.stage not in ('done') and w.entity <> '*lane' and w.next_eligible_at is null and w.unresolved_blocker is not null and w.escalation is null
                      and w.review_ref is null group by 1) z)),
    'work_items_parked_escalated_no_next', jsonb_build_object(
      'count', (select count(*) from pipeline.work_items w where w.stage in ('parked', 'quarantined') and w.entity <> '*lane' and w.next_eligible_at is null and w.escalation is not null),
      'by_authority', (select coalesce(jsonb_object_agg(z.k, z.n), '{}'::jsonb) from (select w.lane || '/' || coalesce(w.escalation->>'as', '?') || '/IQ-' || lpad(coalesce(w.escalation->>'issue_id', '0'), 5, '0') k,
                         count(*) n from pipeline.work_items w where w.stage in ('parked', 'quarantined') and w.entity <> '*lane' and w.next_eligible_at is null
                          and w.escalation is not null group by 1) z),
      'note', 'held by an explicit blocker escalated to an issue: a recovery condition exists (the issue), but no next automatic time'),
    'issues_no_next_action', jsonb_build_object(
      'count', (select count(*) from pipeline.integration_issues i where i.status <> 'closed' and i.superseded_by is null and i.next_action_at is null
                  and i.remediation_checkpoint_at is null and i.blocker is null),
      'examples', (select coalesce(jsonb_agg(z.issue_ref), '[]'::jsonb) from (select i.issue_ref from pipeline.integration_issues i where i.status <> 'closed' and i.superseded_by is null
                     and i.next_action_at is null and i.remediation_checkpoint_at is null and i.blocker is null order by i.id limit v_n) z)),
    'release_jobs_unowned', jsonb_build_object(
      'count', (select count(*) from pipeline.release_job_verifications r where r.issue_id is null
                  and (r.status = 'failed_first_run' or (r.status = 'awaiting_first_run' and r.deployed_at < now() - make_interval(hours => v_dead))))),
    'deep', p_deep);
  if p_deep then
    v := v || jsonb_build_object(
      'field_reads_failed_no_work_item', jsonb_build_object(
        'count', (select count(*) from pipeline.field_enrich_items f where f.state = 'failed'
                    and not exists (select 1 from pipeline.work_items w where w.lane = 'ai_extraction' and w.entity = f.course_id::text || ':' || f.field)),
        'by_reason', (select coalesce(jsonb_object_agg(z.r, z.n), '{}'::jsonb) from (select coalesce(left(f.reason, 50), 'not stated') r, count(*) n from pipeline.field_enrich_items f
                        where f.state = 'failed' and not exists (select 1 from pipeline.work_items w where w.lane = 'ai_extraction' and w.entity = f.course_id::text || ':' || f.field)
                        group by 1 order by 2 desc limit v_n) z)),
      'scholarship_reads_failed', jsonb_build_object(
        'by_reason', (select coalesce(jsonb_object_agg(z.r, z.n), '{}'::jsonb) from (select coalesce(q.skip_reason, 'not stated') r, count(*) n from pipeline.scholarship_ai_queue q
                        where q.state = 'failed' group by 1 order by 2 desc limit v_n) z),
        'note', 'directory site is a correct exclusion (IQ-00132); any other reason is terminal with no work item'));
  end if;
  return v;
end $$;


