    "fingerprint" "text" NOT NULL,
    "title" "text" NOT NULL,
    "layer" "text" NOT NULL,
    "subsystem" "text",
    "provider_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
