    "fix_commit" "text",
    "fix_migration" "text",
    "deployed_version" "text",
    "verification_outcome" "text",
    "verification_evidence" "jsonb",
    "verified_at" timestamp with time zone,
    "verified_by" "text",
    "retry_count" integer DEFAULT 0 NOT NULL,
    "last_observed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "condition_cleared_at" timestamp with time zone,
    "status" "text" DEFAULT 'detected'::"text" NOT NULL,
    "assignee" "text",
    "regression_count" integer DEFAULT 0 NOT NULL,
    "reopened_at" timestamp with time zone,
    "closed_at" timestamp with time zone,
    "aer_root_cause_ref" "text",
    "alert_check_key" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "correlation_key" "text",
    "diagnosis" "jsonb",
    "remedy_code" "text",
    "remedy_attempts" integer DEFAULT 0 NOT NULL,
    "next_action_at" timestamp with time zone,
    "ops_state" "text",
    "superseded_by" bigint,
    "supersedes" bigint[] DEFAULT '{}'::bigint[] NOT NULL,
    "blocker" "jsonb",
    "ops_plan" "jsonb",
    "remediation_owner" "text",
    "remediation_status" "text",
    "remediation_checkpoint_at" timestamp with time zone,
    "remediation_evidence" "jsonb",
    "severity_decided_at" timestamp with time zone,
    "severity_decided_by" "text",
    "severity_decision" "jsonb",
    CONSTRAINT "integration_issues_fingerprint_check" CHECK (("length"("btrim"("fingerprint")) > 0)),
    CONSTRAINT "integration_issues_ops_state_check" CHECK ((("ops_state" IS NULL) OR ("ops_state" = ANY (ARRAY['diagnosed'::"text", 'remedying'::"text", 'verifying'::"text", 'verified'::"text", 'superseded'::"text", 'needs_release'::"text", 'needs_decision'::"text"])))),
    CONSTRAINT "integration_issues_remediation_status_check" CHECK ((("remediation_status" IS NULL) OR ("remediation_status" = ANY (ARRAY['engineering_open'::"text", 'fix_released'::"text", 'awaiting_first_run'::"text", 'verified'::"text", 'returned'::"text"])))),
    CONSTRAINT "integration_issues_root_cause_class_check" CHECK (("root_cause_class" = ANY (ARRAY['unclassified'::"text", 'code_defect'::"text", 'data_drift'::"text", 'job_config'::"text", 'lifecycle_leak'::"text", 'queue_or_lease'::"text", 'missing_dependency'::"text", 'governance_gap'::"text", 'external'::"text", 'budget'::"text", 'human_decision'::"text", 'deployment_drift'::"text"]))),
    CONSTRAINT "integration_issues_severity_check" CHECK (("severity" = ANY (ARRAY['P0'::"text", 'P1'::"text", 'P2'::"text"]))),
    CONSTRAINT "integration_issues_status_check" CHECK (("status" = ANY (ARRAY['detected'::"text", 'triaged'::"text", 'assigned'::"text", 'in_progress'::"text", 'code_ready'::"text", 'integration_testing'::"text", 'deployed'::"text", 'production_verification'::"text", 'closed'::"text", 'reopened'::"text"]))),
    CONSTRAINT "integration_issues_validation_layer_check" CHECK (("validation_layer" = ANY (ARRAY['V1'::"text", 'V2'::"text", 'V3'::"text", 'V4'::"text", 'manual'::"text"]))),
    CONSTRAINT "integration_issues_verification_outcome_check" CHECK (("verification_outcome" = ANY (ARRAY['passed'::"text", 'failed'::"text", 'regressed'::"text"]))),
    CONSTRAINT "integration_issues_workstream_check" CHECK (("workstream" = ANY (ARRAY['A1'::"text", 'A2'::"text", 'A3'::"text", 'A4'::"text", 'A5'::"text", 'A6'::"text", 'A7'::"text", 'A8'::"text", 'A9'::"text", 'A10'::"text"])))
);


ALTER TABLE "pipeline"."integration_issues" OWNER TO "postgres";


COMMENT ON TABLE "pipeline"."integration_issues" IS 'CF-247 continuous validation mandate (Platform Admin 2 Nov 2026 16:58) §3: the persistent integration feedback queue. One row per defect, grouped by a deterministic fingerprint (V4 checks, V3 deploy checks, Platform health and queue-watch issues, and items recorded by the Integration Controller). Repeats update last_observed_at and retry_count; a recurrence after Closed reopens the row as a regression; Closed needs production verification evidence (security.integration_issue_close_v1). aer_root_cause_ref links one AER Phase B root cause (pipeline.aer_gap_root_causes) by reference. Written only by the integration functions; read on Platform health › Integration queue (PIM Admin and above). Never read by the consumer API.';



COMMENT ON COLUMN "pipeline"."integration_issues"."correlation_key" IS 'CF-247 P0 (mandate §3): issues that share an upstream cause share this key (security.ops_correlation_key_v1); one open issue per key owns its remedies.';



COMMENT ON COLUMN "pipeline"."integration_issues"."diagnosis" IS 'CF-247 P0 (mandate §3): {root_cause, confidence 0..1, evidence[], method, at}, written by the controller''s classifier (security.ops_diagnose_v1).';



COMMENT ON COLUMN "pipeline"."integration_issues"."ops_state" IS 'CF-247 P0 (mandate 15:37 §3, §13; acceptance mandate 15:52 §6, §18): where the controller has the issue: diagnosed, remedying (an action failed; retried within attempts), verifying (acted; verified on a later run), verified (closed on evidence), superseded (by the issue that owns its shared root cause: superseded_by, with its evidence carried over; closed when that issue is verified), needs_release (blocked: a code change is the remedy, or attempts are used up) or needs_decision (blocked: a Platform Admin decision); the blocker column holds the evidence and the decision required. Beside status, whose graph is unchanged.';



COMMENT ON COLUMN "pipeline"."integration_issues"."superseded_by" IS 'CF-247 P0 (acceptance mandate 15:52 §6, §18): the issue that owns this issue''s shared root cause (same correlation key); this issue''s evidence is carried over to it (evidence.superseded) and it lists this one in supersedes.';



COMMENT ON COLUMN "pipeline"."integration_issues"."blocker" IS 'CF-247 P0 (acceptance mandate §18, §22): for needs_release or needs_decision, {kind, required, root_cause, evidence, impact, recommended, issue_statement, at}: the exact evidence and the release or external decision required.';



COMMENT ON COLUMN "pipeline"."integration_issues"."ops_plan" IS 'CF-247 P0 (acceptance mandate §6 incident intelligence): the controller''s plan: proposed corrective action (remedy), its authority (approval category), risk, the alternatives it weighed and their verified success rates.';



COMMENT ON COLUMN "pipeline"."integration_issues"."remediation_status" IS 'CF-247 (mandate 4 Nov 2026 08:16 §5): an engineering remediation''s state, set by job first-run-verify: engineering_open (a code or SQL defect, owned by remediation_owner, with its error text and run id in remediation_evidence), fix_released (a release registered a changed job for it), awaiting_first_run, verified (the fixed job''s first run was operationally verified) or returned (the fix''s first run failed; the issue went back to in_progress with the new evidence). remediation_checkpoint_at is the bounded next checkpoint.';



COMMENT ON COLUMN "pipeline"."integration_issues"."severity_decided_at" IS 'CF-247 (direction 4 Nov 2026 10:00 §10): when the severity was last set by a governed decision (security.integration_issue_severity_v1); while set, a repeat observation does not raise it again (security.integration_issue_upsert_v1). severity_decided_by is the decision authority; severity_decision holds the original and new severity, the reason and the evidence. The history is in pipeline.integration_issue_events.';



CREATE OR REPLACE FUNCTION "security"."recovery_issue_text_v1"("i" "pipeline"."integration_issues") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select concat_ws(' ', i.title, i.failure, i.subsystem, i.evidence->'detail'->>'last_error', i.evidence->>'message', i.evidence->'first_run'->>'message', i.evidence::text)
$$;


ALTER FUNCTION "security"."recovery_issue_text_v1"("i" "pipeline"."integration_issues") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."recovery_link_duplicates_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a pipeline.integration_issues; b pipeline.integration_issues; o pipeline.integration_issues; s pipeline.integration_issues; v_job text; v_cls pipeline.recovery_error_classes;
        v_max int := security.pipeline_num_v1('integration.entity_ids_max', 500)::int; v_n int := 0;
        v_rank jsonb := '{"production_verification": 7, "deployed": 6, "integration_testing": 5, "code_ready": 4, "in_progress": 3, "assigned": 2, "triaged": 1, "reopened": 1, "detected": 0}'::jsonb;
begin
  if security.pipeline_num_v1('recovery.link_on', 1) < 1 then return jsonb_build_object('off', true); end if;
  for a in select * from pipeline.integration_issues x where x.status <> 'closed' and x.superseded_by is null and x.fingerprint like 'job_failed:%'
            order by x.last_observed_at desc limit security.pipeline_num_v1('recovery.issues_per_run', 200)::int loop
    v_job := substr(a.fingerprint, 12);
    v_cls := security.recovery_error_class_v1(security.recovery_issue_text_v1(a));
    continue when v_cls.pattern is null;
    for b in select * from pipeline.integration_issues x where x.status <> 'closed' and x.superseded_by is null and x.id <> a.id and x.fingerprint not like 'job_failed:%'
               and (x.evidence->>'job' = v_job or x.evidence->'detail'->>'job' = v_job or position(v_job in concat_ws(' ', x.title, x.failure, x.subsystem)) > 0)
               and security.recovery_issue_text_v1(x) ilike v_cls.pattern
             order by x.id loop
      select * into o from pipeline.integration_issues x where x.id = a.id;  -- a may have changed in this loop
      exit when o.superseded_by is not null;
      if coalesce((v_rank->>b.status)::int, 0) > coalesce((v_rank->>o.status)::int, 0)
         or (coalesce((v_rank->>b.status)::int, 0) = coalesce((v_rank->>o.status)::int, 0) and (b.severity < o.severity or (b.severity = o.severity and (b.detected_at, b.id) < (o.detected_at, o.id)))) then
        s := o; o := b;   -- b is canonical, a is the duplicate
      else
        s := b;           -- a is canonical, b is the duplicate
      end if;
      perform 1 from pipeline.integration_issues x where x.id in (o.id, s.id) order by x.id for update;
      update pipeline.integration_issues set superseded_by = o.id, ops_state = 'superseded', next_action_at = now(), remedy_code = 'supersede_into_owner', updated_at = now() where id = s.id;
      update pipeline.integration_issues i set supersedes = (select coalesce(array_agg(distinct x), '{}') from unnest(i.supersedes || s.id) x),
             evidence = i.evidence || jsonb_build_object('superseded', coalesce(i.evidence->'superseded', '{}'::jsonb) || jsonb_build_object(s.issue_ref,
                        jsonb_build_object('fingerprint', s.fingerprint, 'title', s.title, 'failure', left(s.failure, 500), 'evidence', s.evidence, 'detected_at', s.detected_at,
                                           'providers', cardinality(s.provider_ids), 'courses', cardinality(s.course_ids), 'linked_by', 'first-run-verify', 'error_class', v_cls.error_class))),
             provider_ids = (select coalesce(array_agg(distinct x), '{}') from unnest(i.provider_ids || s.provider_ids) x)[1:v_max],
             course_ids = (select coalesce(array_agg(distinct x), '{}') from unnest(i.course_ids || s.course_ids) x)[1:v_max], updated_at = now()
       where i.id = o.id;
      insert into pipeline.integration_issue_events(issue_id, kind, from_status, to_status, actor, note, detail) values
        (s.id, 'updated', s.status, s.status, 'first-run-verify', 'Same failure as ' || o.issue_ref || ' (job ' || v_job || ', ' || v_cls.error_class || '): linked as its duplicate; closes with it',
         jsonb_build_object('superseded_by', o.id, 'job', v_job, 'error_class', v_cls.error_class, 'pattern', v_cls.pattern)),
        (o.id, 'updated', o.status, o.status, 'first-run-verify', 'Canonical issue for ' || s.issue_ref || ' (job ' || v_job || ', ' || v_cls.error_class || '); its evidence is carried over',
         jsonb_build_object('supersedes', s.id, 'job', v_job, 'error_class', v_cls.error_class));
      if exists (select 1 from pipeline.ops_remedies m where m.code = 'supersede_into_owner') then
        insert into pipeline.ops_remedy_runs(issue_id, remedy_code, finished_at, before, result, evidence)
        values (s.id, 'supersede_into_owner', now(), jsonb_build_object('status', s.status), 'acted',
                jsonb_build_object('action', jsonb_build_object('owner', o.id, 'owner_ref', o.issue_ref, 'job', v_job, 'error_class', v_cls.error_class), 'linked_by', 'first-run-verify'));
      end if;
      v_n := v_n + 1;
    end loop;
  end loop;
  return jsonb_build_object('linked', v_n);
end $$;


ALTER FUNCTION "security"."recovery_link_duplicates_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."recovery_route_engineering_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i pipeline.integration_issues; v_cls pipeline.recovery_error_classes; v_text text; v_job text; v_run text; v_err text; v_h int := security.pipeline_num_v1('recovery.engineering_checkpoint_hours', 4)::int;
        v_to text; v_rem text; v_new int := 0; v_chk int := 0; v_rep numeric;
begin
  if security.pipeline_num_v1('recovery.route_on', 1) < 1 then return jsonb_build_object('off', true); end if;
  for i in select * from pipeline.integration_issues x where x.status <> 'closed' and x.superseded_by is null
             and (x.remediation_owner is null or x.remediation_checkpoint_at <= now())
            order by x.last_observed_at desc limit security.pipeline_num_v1('recovery.issues_per_run', 200)::int loop
    v_text := security.recovery_issue_text_v1(i);
    if i.remediation_owner is null then
      v_cls := security.recovery_error_class_v1(v_text);
      continue when v_cls.pattern is null;
      if v_cls.repeat_setting is not null then
        v_rep := security.pipeline_num_v1(v_cls.repeat_setting, 3);
        continue when not (coalesce((i.evidence->'detail'->>'last_three_failed')::boolean, false) or coalesce((i.evidence->>'failed_runs')::numeric, 0) >= v_rep or i.retry_count >= v_rep);
      end if;
      v_job := coalesce(case when i.fingerprint like 'job_failed:%' then substr(i.fingerprint, 12) end, i.evidence->>'job', i.evidence->'detail'->>'job', i.evidence->'first_run'->>'job');
      v_run := coalesce(i.evidence->'first_run'->>'runid', i.evidence->>'last_runid', i.evidence->'detail'->>'last_runid');
      v_err := left(coalesce(i.evidence->'first_run'->>'message', i.evidence->'detail'->>'last_error', i.evidence->>'message', i.failure), 600);
      v_rem := case when i.status in ('integration_testing', 'deployed', 'production_verification') then 'awaiting_first_run' else 'engineering_open' end;
      v_to := case when i.status in ('detected', 'triaged', 'reopened') then 'assigned' end;
      perform security.integration_issue_transition_v1(i.id, v_to, 'first-run-verify',
        'Owned engineering remediation (' || v_cls.error_class || ': ' || v_cls.title || '); next checkpoint ' || (now() + make_interval(hours => v_h)),
        jsonb_strip_nulls(jsonb_build_object('assignee', coalesce(i.assignee, v_cls.owner),
          'root_cause_class', case when i.root_cause_class = 'unclassified' then v_cls.root_cause_class end,
          'evidence', jsonb_build_object('engineering_remediation', jsonb_build_object('error_class', v_cls.error_class, 'error', v_err, 'runid', v_run, 'job', v_job)))));
      update pipeline.integration_issues set remediation_owner = v_cls.owner, remediation_status = v_rem, remediation_checkpoint_at = now() + make_interval(hours => v_h),
             remediation_evidence = jsonb_strip_nulls(jsonb_build_object('error_class', v_cls.error_class, 'pattern', v_cls.pattern, 'error', v_err, 'runid', v_run, 'job', v_job,
                                    'routed_at', now(), 'status_at_checkpoint', coalesce(v_to, i.status)))
       where id = i.id;
      v_new := v_new + 1;
    else
      -- a checkpoint passed: record it once and set the next (a moved issue resets the baseline)
      perform security.integration_issue_transition_v1(i.id, null, 'first-run-verify',
        case when i.status = i.remediation_evidence->>'status_at_checkpoint'
             then 'Engineering checkpoint passed with no change (still ' || i.status || ', remediation ' || coalesce(i.remediation_status, '?') || '); next checkpoint '
             else 'Engineering checkpoint: moved to ' || i.status || ' (remediation ' || coalesce(i.remediation_status, '?') || '); next checkpoint ' end
          || (now() + make_interval(hours => v_h)), '{}'::jsonb);
      update pipeline.integration_issues set remediation_checkpoint_at = now() + make_interval(hours => v_h),
             remediation_evidence = coalesce(remediation_evidence, '{}'::jsonb) || jsonb_build_object('status_at_checkpoint', i.status, 'last_checkpoint', now())
       where id = i.id;
      v_chk := v_chk + 1;
    end if;
  end loop;
  return jsonb_build_object('routed', v_new, 'checkpoints', v_chk);
end $$;


ALTER FUNCTION "security"."recovery_route_engineering_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."reference_domain_matches"("p_host" "text", "p_domain" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select p_host is not null and p_domain is not null and case
    when position('.' in p_domain) > 0 then p_host = p_domain or right(p_host, length(p_domain) + 1) = '.' || p_domain
    else p_host ~ ('(^|\.)' || p_domain) end
$$;


ALTER FUNCTION "security"."reference_domain_matches"("p_host" "text", "p_domain" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."reference_host_of"("p_url" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select nullif(lower(case when p_url ~ '^[A-Za-z][A-Za-z0-9+.-]*://'
                           then substring(p_url from '^[A-Za-z][A-Za-z0-9+.-]*://(?:[^/@]*@)?([^/:?#]+)')
                           else split_part(split_part(split_part(btrim(coalesce(p_url, '')), '/', 1), '?', 1), ':', 1) end), '')
$$;


ALTER FUNCTION "security"."reference_host_of"("p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."reference_placeholder_in_use"("p_domain" "text") RETURNS bigint
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select count(*) from scholarship.scholarships s where s.lifecycle_status = 'active'
     and security.reference_domain_matches(security.reference_host_of(s.source_url), p_domain)
$$;


ALTER FUNCTION "security"."reference_placeholder_in_use"("p_domain" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."reference_url_has_use"("p_url" "text", "p_use" "text") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from pipeline.important_links l
    where l.enabled and l.retired_at is null and p_use = any(l.uses)
      and security.reference_domain_matches(security.reference_host_of(p_url), l.domain))
$$;


ALTER FUNCTION "security"."reference_url_has_use"("p_url" "text", "p_use" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."refind_wave_discovery_v1"("p_wave" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int := 0; v_new int := 0;
begin
  if p_wave is null or p_wave not like 'refind-%' then return 0; end if;
  update pipeline.coverage_provider_discovery d set status = 'pending', attempts = 0, next_due_at = now(), leased_until = null, updated_at = now(),
         last_error = coalesce(d.last_error, '') || ' | tried again for wave ' || p_wave
    from pipeline.adapter_builds b join catalogue.providers p on p.id = b.provider_id
   where b.wave = p_wave and d.provider_id = b.provider_id and nullif(p.website, '') is not null
     and (d.status = 'failed' or (d.status = 'pending' and d.attempts > 0) or coalesce(d.method, '') ~ 'map:(budget|credits_refused|credits_reserve|target_list_refused|no_firecrawl_key)');
  get diagnostics v_n = row_count;
  insert into pipeline.coverage_provider_discovery(provider_id, website, status, attempts, next_due_at, updated_at)
  select b.provider_id, p.website, 'pending', 0, now(), now()
    from pipeline.adapter_builds b join catalogue.providers p on p.id = b.provider_id
   where b.wave = p_wave and nullif(p.website, '') is not null
  on conflict (provider_id) do nothing;
  get diagnostics v_new = row_count;
  return v_n + v_new;
end $$;


ALTER FUNCTION "security"."refind_wave_discovery_v1"("p_wave" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."refind_wave_discovery_v1"("p_wave" "text") IS 'CF-247 19 Oct 2026: site discovery tried again for the providers of a re-find wave whose site was never mapped';



CREATE OR REPLACE FUNCTION "security"."refresh_data_quality_overview_snapshots"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security'
    SET "statement_timeout" TO '120s'
    SET "work_mem" TO '128MB'
    AS $$
declare
  r record;
  v_started timestamptz;
  v_finished timestamptz;
  v_payload jsonb;
  v_result jsonb := '[]'::jsonb;
begin
  for r in select * from (values
    ('AU+NZ'::text,null::text,'{}'::jsonb),
    ('AU'::text,'AU'::text,'{"country_code":"AU"}'::jsonb),
    ('NZ'::text,'NZ'::text,'{"country_code":"NZ"}'::jsonb)
  ) v(scope_code,country_code,args)
  loop
    v_started:=clock_timestamp();
    v_payload:=security.data_quality_overview_impl(r.args);
    v_finished:=clock_timestamp();
    insert into security.data_quality_overview_snapshots(scope_code,country_code,payload,computed_at,compute_duration_ms,refreshed_by)
    values(r.scope_code,r.country_code,v_payload,v_finished,round((extract(epoch from (v_finished-v_started))*1000.0)::numeric,2),current_user)
    on conflict(scope_code) do update set country_code=excluded.country_code,payload=excluded.payload,computed_at=excluded.computed_at,compute_duration_ms=excluded.compute_duration_ms,refreshed_by=excluded.refreshed_by;
    v_result:=v_result||jsonb_build_array(jsonb_build_object('scope_code',r.scope_code,'computed_at',v_finished,'compute_duration_ms',round((extract(epoch from (v_finished-v_started))*1000.0)::numeric,2)));
  end loop;
  return jsonb_build_object('snapshots',v_result,'completed_at',clock_timestamp());
end
$$;


ALTER FUNCTION "security"."refresh_data_quality_overview_snapshots"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."refresh_intelligence_overview_impl"("p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
begin
  if auth.uid() is null or security.current_role_rank()<3 then
    raise exception 'curator role required' using errcode='42501';
  end if;
  return jsonb_build_object(
   'policies',coalesce((
     select jsonb_agg(to_jsonb(x) order by x.next_due_at nulls last)
     from (
       select id,country_code,layer,source_id,source_profile_id,entity_type,entity_id,
              freshness_class,cadence_interval,next_due_at,hash_sensitive,important_date_sensitive,
              enabled,change_control_ref,updated_at
       from pipeline.refresh_policies
       order by next_due_at nulls last
       limit least(greatest(p_limit,1),250)
     ) x
   ),'[]'::jsonb),
   'requests',coalesce((
     select jsonb_agg(to_jsonb(x) order by x.created_at desc)
     from (
       select id,requested_layer,country_code,source_id,source_profile_id,entity_type,entity_id,
              evidence_id,layer3_profile_id,revalidation_ref,reason,trigger_type,important_date_id,
              status,requested_by,change_control_ref,created_at,completed_at
       from pipeline.refresh_requests
       order by created_at desc
       limit least(greatest(p_limit,1),250)
     ) x
   ),'[]'::jsonb),
   'search_signals',coalesce((
     select jsonb_agg(to_jsonb(x) order by x.created_at desc)
     from (
       select id,entity_type,entity_id,review_decision_id,reason,status,change_control_ref,created_at,completed_at
       from pipeline.search_refresh_signals
       order by created_at desc
       limit least(greatest(p_limit,1),250)
     ) x
   ),'[]'::jsonb)
  );
end $$;


ALTER FUNCTION "security"."refresh_intelligence_overview_impl"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."refresh_policy_upsert_impl"("p_id" "uuid", "p_country_code" "text", "p_layer" smallint, "p_source_profile_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_freshness_class" "text", "p_cadence_days" integer, "p_next_due_at" timestamp with time zone, "p_hash_sensitive" boolean, "p_important_date_sensitive" boolean, "p_enabled" boolean, "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$ declare v_id uuid:=coalesce(p_id,gen_random_uuid()); begin
 if auth.uid() is null or security.current_role_rank()<4 then raise exception 'pipeline operator role required' using errcode='42501'; end if;
 if length(trim(coalesce(p_reason,'')))<5 then raise exception 'governance reason required'; end if;
 if p_layer=4 and p_freshness_class<>'event-driven' then raise exception 'Layer 4 refresh policy must be event-driven'; end if;
 if p_layer in (1,2,3) and p_source_profile_id is null and p_entity_id is null then raise exception 'bounded source or entity target required'; end if;
 insert into pipeline.refresh_policies(id,country_code,layer,source_profile_id,entity_type,entity_id,freshness_class,cadence_interval,next_due_at,hash_sensitive,important_date_sensitive,enabled,change_control_ref)
 values(v_id,upper(nullif(p_country_code,'')),p_layer,p_source_profile_id,p_entity_type,p_entity_id,p_freshness_class,case when p_cadence_days is null then null else make_interval(days=>p_cadence_days) end,p_next_due_at,p_hash_sensitive,p_important_date_sensitive,p_enabled,'CF-CHG-20260825-038')
 on conflict(id) do update set country_code=excluded.country_code,layer=excluded.layer,source_profile_id=excluded.source_profile_id,entity_type=excluded.entity_type,entity_id=excluded.entity_id,freshness_class=excluded.freshness_class,cadence_interval=excluded.cadence_interval,next_due_at=excluded.next_due_at,hash_sensitive=excluded.hash_sensitive,important_date_sensitive=excluded.important_date_sensitive,enabled=excluded.enabled,change_control_ref=excluded.change_control_ref,updated_at=now(); return v_id; end $$;


ALTER FUNCTION "security"."refresh_policy_upsert_impl"("p_id" "uuid", "p_country_code" "text", "p_layer" smallint, "p_source_profile_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_freshness_class" "text", "p_cadence_days" integer, "p_next_due_at" timestamp with time zone, "p_hash_sensitive" boolean, "p_important_date_sensitive" boolean, "p_enabled" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."refresh_policy_upsert_v2_browser_bridge"("p_id" "uuid", "p_country_code" "text", "p_layer" smallint, "p_source_id" "uuid", "p_source_profile_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_freshness_class" "text", "p_cadence_days" integer, "p_next_due_at" timestamp with time zone, "p_hash_sensitive" boolean, "p_important_date_sensitive" boolean, "p_enabled" boolean, "p_reason" "text") RETURNS "uuid"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$ select security.refresh_policy_upsert_v2_impl(p_id,p_country_code,p_layer,p_source_id,p_source_profile_id,p_entity_type,p_entity_id,p_freshness_class,p_cadence_days,p_next_due_at,p_hash_sensitive,p_important_date_sensitive,p_enabled,p_reason) $$;


ALTER FUNCTION "security"."refresh_policy_upsert_v2_browser_bridge"("p_id" "uuid", "p_country_code" "text", "p_layer" smallint, "p_source_id" "uuid", "p_source_profile_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_freshness_class" "text", "p_cadence_days" integer, "p_next_due_at" timestamp with time zone, "p_hash_sensitive" boolean, "p_important_date_sensitive" boolean, "p_enabled" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."refresh_policy_upsert_v2_impl"("p_id" "uuid", "p_country_code" "text", "p_layer" smallint, "p_source_id" "uuid", "p_source_profile_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_freshness_class" "text", "p_cadence_days" integer, "p_next_due_at" timestamp with time zone, "p_hash_sensitive" boolean, "p_important_date_sensitive" boolean, "p_enabled" boolean, "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'auth'
    AS $$
declare v_id uuid := coalesce(p_id, gen_random_uuid());
begin
  if auth.uid() is null or security.current_role_rank() < 4 then
    raise exception 'pipeline operator role required' using errcode='42501';
  end if;
  if length(trim(coalesce(p_reason,''))) < 5 then raise exception 'governance reason required'; end if;
  if p_layer not between 1 and 4 then raise exception 'layer must be 1..4'; end if;
  if p_freshness_class not in ('critical','weekly','monthly','term-cycle','annual','event-driven') then
    raise exception 'invalid freshness class';
  end if;
  if p_layer = 4 and p_freshness_class <> 'event-driven' then
    raise exception 'Layer 4 refresh policy must be event-driven';
  end if;
  if p_layer in (1,2,3) and p_source_id is null and p_source_profile_id is null and p_entity_id is null then
    raise exception 'bounded source, source profile or entity target required';
  end if;
  insert into pipeline.refresh_policies(
    id,country_code,layer,source_id,source_profile_id,entity_type,entity_id,
    freshness_class,cadence_interval,next_due_at,hash_sensitive,
    important_date_sensitive,enabled,change_control_ref
  ) values (
    v_id,upper(nullif(p_country_code,'')),p_layer,p_source_id,p_source_profile_id,p_entity_type,p_entity_id,
    p_freshness_class,case when p_cadence_days is null then null else make_interval(days=>p_cadence_days) end,
    p_next_due_at,p_hash_sensitive,p_important_date_sensitive,p_enabled,'CF-CHG-20260825-038'
  )
  on conflict(id) do update set
    country_code=excluded.country_code,layer=excluded.layer,source_id=excluded.source_id,
    source_profile_id=excluded.source_profile_id,entity_type=excluded.entity_type,entity_id=excluded.entity_id,
    freshness_class=excluded.freshness_class,cadence_interval=excluded.cadence_interval,
    next_due_at=excluded.next_due_at,hash_sensitive=excluded.hash_sensitive,
    important_date_sensitive=excluded.important_date_sensitive,enabled=excluded.enabled,
    change_control_ref=excluded.change_control_ref,updated_at=now();
  return v_id;
end $$;


ALTER FUNCTION "security"."refresh_policy_upsert_v2_impl"("p_id" "uuid", "p_country_code" "text", "p_layer" smallint, "p_source_id" "uuid", "p_source_profile_id" "uuid", "p_entity_type" "text", "p_entity_id" "uuid", "p_freshness_class" "text", "p_cadence_days" integer, "p_next_due_at" timestamp with time zone, "p_hash_sensitive" boolean, "p_important_date_sensitive" boolean, "p_enabled" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."refresh_reference_bundle_cache_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline'
    AS $$
    declare t0 timestamptz := clock_timestamp(); b jsonb;
    begin
      b := security.zoho_reference_bundle_live_v1();
      insert into pipeline.consumer_reference_bundle_cache(id,bundle,built_at,build_ms)
      values (1,b,now(),round(extract(epoch from clock_timestamp()-t0)*1000))
      on conflict (id) do update set bundle=excluded.bundle, built_at=excluded.built_at, build_ms=excluded.build_ms;
      return jsonb_build_object('built_at',now(),'bytes',length(b::text));
    end $$;


ALTER FUNCTION "security"."refresh_reference_bundle_cache_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."refresh_scheduler_tick_impl"("p_now" timestamp with time zone DEFAULT "now"(), "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline'
    AS $$
declare v_policy_count int:=0; v_date_count int:=0; v_l3_count int:=0; v_expired_dates int:=0;
begin
  with due as (
    select p.*
    from pipeline.refresh_policies p
    where p.enabled
      and p.layer in (1,2,3)
      and p.freshness_class <> 'event-driven'
      and p.cadence_interval is not null
      and p.next_due_at is not null
      and p.next_due_at <= p_now
    order by p.next_due_at
    limit least(greatest(p_limit,1),500)
    for update skip locked
  ), ins as (
    insert into pipeline.refresh_requests(
      requested_layer,country_code,source_id,source_profile_id,entity_type,entity_id,
      reason,trigger_type,requested_by,change_control_ref
    )
    select d.layer,d.country_code,d.source_id,d.source_profile_id,d.entity_type,d.entity_id,
           'Governed '||d.freshness_class||' freshness policy due','freshness_expired',null,d.change_control_ref
    from due d
    where not exists (
      select 1 from pipeline.refresh_requests r
      where r.status in ('queued','running')
        and r.requested_layer=d.layer
        and r.source_id is not distinct from d.source_id
        and r.source_profile_id is not distinct from d.source_profile_id
        and r.entity_id is not distinct from d.entity_id
    )
    returning 1
  ), adv as (
    update pipeline.refresh_policies p
    set next_due_at = greatest(p.next_due_at,p_now) + p.cadence_interval, updated_at=p_now
    where p.id in (select id from due)
    returning 1
  )
  select count(*) into v_policy_count from ins;

  with target_dates as (
    select d.*,
      coalesce(d.starts_at, case when d.starts_on is null then null
        else d.starts_on::timestamp at time zone coalesce(nullif(d.timezone,''),'UTC') end) as operational_start,
      coalesce(d.ends_at, case when d.ends_on is null then null
        else (d.ends_on + 1)::timestamp at time zone coalesce(nullif(d.timezone,''),'UTC') end) as operational_end
    from pipeline.important_dates d
    where d.status='active'
      and d.refresh_layer is not null
      and (d.starts_at is not null or d.starts_on is not null)
      and (d.source_id is not null or d.source_profile_id is not null or d.entity_id is not null)
  ), due_dates as (
    select *
    from target_dates d
    where d.operational_start - d.warning_window <= p_now
      and (d.operational_end is null or d.operational_end >= p_now)
    order by d.operational_start
    limit least(greatest(p_limit,1),500)
  ), ins as (
    insert into pipeline.refresh_requests(
      requested_layer,country_code,source_id,source_profile_id,entity_type,entity_id,
      reason,trigger_type,important_date_id,requested_by,change_control_ref
    )
    select d.refresh_layer,d.country_code,d.source_id,d.source_profile_id,d.entity_type,d.entity_id,
           'Important Date warning window: '||d.title,'important_date',d.id,null,d.change_control_ref
    from due_dates d
    where not exists (
      select 1 from pipeline.refresh_requests r
      where r.important_date_id=d.id and r.status in ('queued','running','completed')
    )
    returning 1
  )
  select count(*) into v_date_count from ins;

  with expired as (
    select i.*
    from pipeline.layer3_interpretations i
    where i.status in ('validated','no_candidate')
      and i.interpretation_expires_at is not null
      and i.interpretation_expires_at <= p_now
    order by i.interpretation_expires_at
    limit least(greatest(p_limit,1),500)
  ), ins as (
    insert into pipeline.refresh_requests(
      requested_layer,entity_type,entity_id,evidence_id,layer3_profile_id,revalidation_ref,
      reason,trigger_type,requested_by,change_control_ref
    )
    select 3,i.entity_type,i.entity_id,i.evidence_id,i.profile_id,'EXPIRY:'||i.id::text,
           'Layer 3 interpretation freshness expired','freshness_expired',null,i.change_control_ref
    from expired i
    where not exists (
      select 1 from pipeline.refresh_requests r
      where r.requested_layer=3 and r.evidence_id=i.evidence_id and r.layer3_profile_id=i.profile_id
        and r.status in ('queued','running')
    )
    returning 1
  )
  select count(*) into v_l3_count from ins;

  update pipeline.important_dates
  set status='expired',updated_at=p_now
  where status='active' and expires_at is not null and expires_at<=p_now;
  get diagnostics v_expired_dates = row_count;

  return jsonb_build_object(
    'ok',true,'policy_requests_created',v_policy_count,'important_date_requests_created',v_date_count,
    'layer3_expiry_requests_created',v_l3_count,'important_dates_expired',v_expired_dates,'at',p_now
  );
end $$;


ALTER FUNCTION "security"."refresh_scheduler_tick_impl"("p_now" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


