CREATE OR REPLACE FUNCTION "security"."retention_catalogue_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_array(
    jsonb_build_object('key', 'adapter_screenshots', 'label', 'Adapter builder screenshots', 'kind', 'files', 'purge', true,
      'rule', 'Screenshots captured by the adapter builder more than 7 days ago. The stored page HTML and text blocks that proposals use are kept; the builder shows "screenshot removed".'),
    jsonb_build_object('key', 'retired_layer2', 'label', 'Retired Layer 2 tables', 'kind', 'rows', 'purge', true,
      'rule', 'Rows of the Layer 2 tables retired on 2 Oct 2026: scope wave items, scale qualification items, provider attempts, course discovery candidates and provider trial results. Run items are kept because Layer 3 work items point to them.'),
    jsonb_build_object('key', 'job_log', 'label', 'Scheduled-job run log', 'kind', 'rows', 'purge', true,
      'rule', 'Run records of scheduled jobs older than 7 days. Platform health and the job notices only use the last 24 hours.'),
    jsonb_build_object('key', 'directory_urls', 'label', 'Course-directory sitemap copies', 'kind', 'rows', 'purge', true,
      'rule', 'Sitemap addresses on third-party course directories shared by 3 or more providers, kept for providers whose own website is a different site. Addresses bound to a course are kept (they are in Layer 4 review).'),
    jsonb_build_object('key', 'evidence_audit', 'label', 'Evidence files (audit)', 'kind', 'files', 'purge', false,
      'rule', 'Count only: evidence records and files not referenced by any value, decision or pipeline record. Nothing is deleted. Run it before purging unreferenced evidence.'),
    jsonb_build_object('key', 'evidence_unreferenced', 'label', 'Unreferenced evidence', 'kind', 'files', 'purge', true,
      'rule', 'Evidence records and their files that the last completed audit found referenced nowhere, created before that audit and more than 7 days ago. Each batch is checked again just before removal; anything referenced by then is skipped. Evidence kept for 365 days by policy and ranking publisher source files are never purged. A file shared with another evidence record is kept.'))
$$;


ALTER FUNCTION "security"."retention_catalogue_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."retention_dry_run_read"("p_environment" "text" DEFAULT 'pilot'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline', 'public'
    AS $$
declare v_rank integer; v_terminal bigint; v_immutable bigint;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select security.current_role_rank() into v_rank;
  if v_rank<4 then raise exception 'pipeline_operator role required' using errcode='42501'; end if;
  if p_environment not in ('pilot','production') then raise exception 'invalid environment'; end if;

  select count(*) into v_terminal
  from pipeline.jobs
  where status in ('completed','failed','cancelled')
    and coalesce(completed_at,created_at) < now()-interval '90 days';

  select count(*) into v_immutable
  from pipeline.retention_class_policies where immutable;

  return jsonb_build_object(
    'environment',p_environment,
    'mode','dry_run_only',
    'delete_performed',false,
    'terminal_job_candidates_older_than_90d',v_terminal,
    'immutable_policy_classes',v_immutable,
    'evidence_delete_candidates',0,
    'layer4_delete_candidates',0,
    'publication_audit_delete_candidates',0,
    'rule','Any future purge requires explicit class mapping, immutable exclusions, bounded delete and post-delete integrity verification.'
  );
end $$;


ALTER FUNCTION "security"."retention_dry_run_read"("p_environment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."retention_estimate_v1"("p_cat" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_size bigint; v_rows bigint; v_bytes bigint; v_detail jsonb := '{}'::jsonb;
begin
  if p_cat = 'adapter_screenshots' then
    select coalesce(sum((o.metadata->>'size')::bigint), 0), count(*) filter (where o.created_at < now() - make_interval(days => security.pipeline_num_v1('retention.screenshot_keep_days', 7)::int) and not security.screenshot_in_open_build_v1(o.name, o.created_at)),
           coalesce(sum((o.metadata->>'size')::bigint) filter (where o.created_at < now() - make_interval(days => security.pipeline_num_v1('retention.screenshot_keep_days', 7)::int) and not security.screenshot_in_open_build_v1(o.name, o.created_at)), 0)
      into v_size, v_rows, v_bytes from storage.objects o where o.bucket_id = 'adapter-captures';
  elsif p_cat = 'retired_layer2' then
    select sum(pg_total_relation_size(t::regclass)) into v_size
      from unnest(array['pipeline.layer2_course_discovery_candidates', 'pipeline.layer2_provider_attempts']) t;  -- CF-247 15 Oct 2026: layer2_scope_wave_items retired
    v_rows := (select count(*) from pipeline.layer2_course_discovery_candidates) + (select count(*) from pipeline.layer2_provider_attempts);
    v_bytes := v_size;
    v_detail := jsonb_build_object('trial_results', 0, 'discovery_candidates', (select count(*) from pipeline.layer2_course_discovery_candidates),
      'provider_attempts', (select count(*) from pipeline.layer2_provider_attempts), 'scale_qualification_items', 0,
      'scope_wave_items', 0);
  elsif p_cat = 'job_log' then
    v_size := pg_total_relation_size('cron.job_run_details');
    select count(*) filter (where d.start_time < now() - make_interval(days => security.pipeline_num_v1('retention.job_log_keep_days', 7)::int)), count(*) into v_rows, v_bytes from cron.job_run_details d;
    v_bytes := case when v_bytes > 0 then v_size * v_rows / v_bytes else 0 end;
  elsif p_cat = 'directory_urls' then
    v_size := pg_total_relation_size('pipeline.coverage_provider_urls');
    with h as (select provider_id, substring(url from '^https?://(?:www\.)?([^/:?#]+)') host from pipeline.coverage_provider_urls),
         shared as (select host from h group by host having count(distinct provider_id) >= 3)
    select coalesce(jsonb_agg(host order by host), '[]'::jsonb) into v_detail from shared;
    v_detail := jsonb_build_object('hosts', v_detail);
    select count(*) into v_rows from pipeline.coverage_provider_urls u join catalogue.providers p on p.id = u.provider_id
     where substring(u.url from '^https?://(?:www\.)?([^/:?#]+)') in (select jsonb_array_elements_text(v_detail->'hosts'))
       and (p.website is null or p.website not ilike '%' || substring(u.url from '^https?://(?:www\.)?([^/:?#]+)') || '%')
       and not exists (select 1 from pipeline.coverage_course_pages pg where pg.url = u.url);
    v_bytes := case when (select reltuples from pg_class where oid = 'pipeline.coverage_provider_urls'::regclass) > 0
                    then (v_size * v_rows / greatest(1, (select reltuples from pg_class where oid = 'pipeline.coverage_provider_urls'::regclass)))::bigint else 0 end;
  elsif p_cat = 'evidence_audit' then
    v_size := pg_total_relation_size('pipeline.evidence_artifacts');
    select count(*), count(*) filter (where c.done_at is not null) into v_rows, v_bytes from pipeline.evidence_audit_columns c;
    v_detail := jsonb_build_object('columns', v_rows, 'columns_done', v_bytes, 'references', (select count(*) from pipeline.evidence_audit_refs),
      'evidence_records', (select count(*) from pipeline.evidence_artifacts),
      'evidence_files_bytes', (select coalesce(sum((o.metadata->>'size')::bigint), 0) from storage.objects o where o.bucket_id = 'evidence'));
    if v_rows > 0 and v_rows = v_bytes then
      select count(*), coalesce(sum((o.metadata->>'size')::bigint), 0) into v_rows, v_bytes
        from pipeline.evidence_artifacts e left join storage.objects o on o.bucket_id = 'evidence' and o.name = e.storage_path
       where not exists (select 1 from pipeline.evidence_audit_refs r where r.evidence_id = e.id);
    else
      v_rows := null; v_bytes := null;
    end if;
  elsif p_cat = 'evidence_unreferenced' then
    v_size := pg_total_relation_size('pipeline.evidence_artifacts');
    if exists (select 1 from pipeline.retention_runs r where r.category = 'evidence_audit' and r.status = 'done')
       and not exists (select 1 from pipeline.retention_runs r where r.category = 'evidence_audit' and r.status in ('queued', 'running')) then
      -- bytes: each file once, and only files no other (kept) evidence record uses
      with c as materialized (select evidence_id, storage_path from security.retention_evidence_candidates_v1()),
           f as (select distinct storage_path from c where storage_path is not null)
      select (select count(*) from c),
             coalesce((select sum((o.metadata->>'size')::bigint) from f join storage.objects o on o.bucket_id = 'evidence' and o.name = f.storage_path
                        where not exists (select 1 from pipeline.evidence_artifacts e where e.storage_path = f.storage_path
                                            and not exists (select 1 from c where c.evidence_id = e.id))), 0)
        into v_rows, v_bytes;
      v_detail := (select jsonb_build_object('audit_run', r.id, 'audit_started_at', r.started_at, 'audit_finished_at', r.finished_at)
                     from pipeline.retention_runs r where r.category = 'evidence_audit' and r.status = 'done' order by r.finished_at desc limit 1);
    else
      v_rows := null; v_bytes := null; v_detail := jsonb_build_object('note', 'Run the evidence audit first (and let it finish).');
    end if;
  else
    raise exception 'unknown category';
  end if;
  insert into pipeline.retention_estimates(category, size_bytes, purgeable_rows, purgeable_bytes, detail, measured_at)
  values (p_cat, v_size, v_rows, v_bytes, v_detail, now())
  on conflict (category) do update set size_bytes = excluded.size_bytes, purgeable_rows = excluded.purgeable_rows, purgeable_bytes = excluded.purgeable_bytes,
         detail = excluded.detail, measured_at = excluded.measured_at;
end $$;


ALTER FUNCTION "security"."retention_estimate_v1"("p_cat" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."retention_evidence_candidates_v1"() RETURNS TABLE("evidence_id" "uuid", "storage_path" "text", "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with a as (select r.started_at from pipeline.retention_runs r where r.category = 'evidence_audit' and r.status = 'done' order by r.finished_at desc limit 1)
  select e.id, e.storage_path, e.created_at
    from pipeline.evidence_artifacts e, a
   where e.created_at < least(a.started_at, now() - make_interval(days => security.pipeline_num_v1('retention.evidence_min_age_days', 7)::int))
     and coalesce(e.retention_class, '') not in ('standard_365', 'source_evidence')
     and coalesce(e.storage_path, '') not like 'regulatory/%'
     and not exists (select 1 from pipeline.evidence_audit_refs r where r.evidence_id = e.id)
$$;


ALTER FUNCTION "security"."retention_evidence_candidates_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."retention_tick_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.retention_runs%rowtype; v_n bigint := 0; v_cat text; v_hosts text[]; v_t text; v_col record; v_done int := 0;
        v_ev record; v_del int := 0; v_skip int := 0; v_q int := 0;
begin
  -- keep the estimates fresh (one category per run, oldest first)
  select c->>'key' into v_cat from jsonb_array_elements(security.retention_catalogue_v1()) c
   left join pipeline.retention_estimates e on e.category = c->>'key'
   where c->>'key' <> 'evidence_audit' and (e.measured_at is null or e.measured_at < now() - make_interval(hours => security.pipeline_num_v1('retention.estimate_refresh_hours', 1)::int))
   order by e.measured_at nulls first limit 1;
  if v_cat is not null then perform security.retention_estimate_v1(v_cat); end if;

  select * into r from pipeline.retention_runs where status in ('queued', 'running') order by created_at limit 1 for update skip locked;
  if r.id is null then return jsonb_build_object('idle', true); end if;
  begin
    if r.status = 'queued' then
      perform security.retention_estimate_v1(r.category);
      update pipeline.retention_runs set status = 'running', started_at = now(), estimate = (select to_jsonb(e) from pipeline.retention_estimates e where e.category = r.category),
             note = 'Running in small batches.', updated_at = now() where id = r.id;
      if r.category = 'evidence_audit' then
        delete from pipeline.evidence_audit_refs;
        delete from pipeline.evidence_audit_columns;
        insert into pipeline.evidence_audit_columns(tbl, col)
        select distinct format('%I.%I', n.nspname, c.relname), a.attname
          from pg_attribute a join pg_class c on c.oid = a.attrelid join pg_namespace n on n.oid = c.relnamespace
         where c.relkind = 'r' and a.attnum > 0 and not a.attisdropped and a.atttypid = 'uuid'::regtype
           and n.nspname in ('catalogue', 'pipeline', 'scholarship', 'ranking', 'workflow', 'pim', 'search')
           and (a.attname in ('evidence_id', 'evidence_artifact_id', 'source_artifact_id', 'supersedes_evidence_id') or a.attname like '%\_evidence\_id' escape '\')
           and c.relname not in ('evidence_audit_refs');
      end if;
      return jsonb_build_object('started', r.id);
    end if;

    if r.category = 'job_log' then
      delete from cron.job_run_details where runid in (select d.runid from cron.job_run_details d where d.start_time < coalesce(r.started_at, now()) - make_interval(days => security.pipeline_num_v1('retention.job_log_keep_days', 7)::int) limit security.pipeline_num_v1('batch.retention_rows', 20000)::int);
      get diagnostics v_n = row_count;
    elsif r.category = 'retired_layer2' then
      foreach v_t in array array['pipeline.layer2_course_discovery_candidates', 'pipeline.layer2_provider_attempts'] loop  -- CF-247 15 Oct 2026: layer2_scope_wave_items retired
        execute format('delete from %s where ctid = any(array(select ctid from %s limit %s))', v_t, v_t, security.pipeline_num_v1('batch.retention_layer2_rows', 5000)::int);
        get diagnostics v_n = row_count;
        exit when v_n > 0;
      end loop;
    elsif r.category = 'directory_urls' then
      select array(select jsonb_array_elements_text(coalesce(r.estimate->'detail'->'hosts', '[]'::jsonb))) into v_hosts;
      delete from pipeline.coverage_provider_urls where (provider_id, url) in (
        select u.provider_id, u.url from pipeline.coverage_provider_urls u join catalogue.providers p on p.id = u.provider_id
         where substring(u.url from '^https?://(?:www\.)?([^/:?#]+)') = any(v_hosts)
           and (p.website is null or p.website not ilike '%' || substring(u.url from '^https?://(?:www\.)?([^/:?#]+)') || '%')
           and not exists (select 1 from pipeline.coverage_course_pages pg where pg.url = u.url)
         limit security.pipeline_num_v1('batch.retention_rows', 20000)::int);
      get diagnostics v_n = row_count;
    elsif r.category = 'adapter_screenshots' then
      -- files go through Storage: hand the run to the worker; it reports back with svc_retention_files_done
      if r.note is distinct from 'Removing files through Storage.' or r.updated_at < now() - interval '10 minutes' then -- fixed: hand-over lease: work not confirmed within 10 minutes is taken back
        update pipeline.retention_runs set note = 'Removing files through Storage.', updated_at = now() where id = r.id;
        perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'retention_files', 'run_id', r.id));
      end if;
      return jsonb_build_object('handed_to_worker', r.id);
    elsif r.category = 'evidence_unreferenced' then
      -- files of the last batch still with the worker: hand them again if the worker has not reported for 10 minutes
      if exists (select 1 from pipeline.retention_file_queue q where q.run_id = r.id and q.status in ('queued', 'handed')) then
        if r.updated_at < now() - interval '10 minutes' or exists (select 1 from pipeline.retention_file_queue q where q.run_id = r.id and q.status = 'queued') then -- fixed: hand-over lease: work not confirmed within 10 minutes is taken back
          update pipeline.retention_file_queue set status = 'queued' where run_id = r.id and status = 'handed' and handed_at < now() - interval '10 minutes'; -- fixed: hand-over lease: work not confirmed within 10 minutes is taken back
          update pipeline.retention_runs set updated_at = now() where id = r.id;
          perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'retention_files', 'run_id', r.id));
        end if;
        return jsonb_build_object('handed_to_worker', r.id);
      end if;
      if not exists (select 1 from pipeline.retention_runs a where a.category = 'evidence_audit' and a.status = 'done')
         or exists (select 1 from pipeline.retention_runs a where a.category = 'evidence_audit' and a.status in ('queued', 'running')) then
        raise exception 'Run the evidence audit first and let it finish.';
      end if;
      -- next batch: candidates not yet skipped in this run
      create temporary table ev_batch on commit drop as
        select c.evidence_id id, c.storage_path from security.retention_evidence_candidates_v1() c
         where not exists (select 1 from pipeline.retention_evidence_skips s where s.run_id = r.id and s.evidence_id = c.evidence_id)
         order by c.created_at limit security.pipeline_num_v1('batch.retention_evidence', 500)::int;
      if not exists (select 1 from ev_batch) then
        perform security.retention_estimate_v1('evidence_unreferenced');
        update pipeline.retention_runs set status = 'done', finished_at = now(), updated_at = now(),
               note = format('Done: %s records and %s MB of files removed; %s skipped because they were referenced again.', removed, round(bytes / 1e6),
                             (select count(*) from pipeline.retention_evidence_skips s where s.run_id = r.id))
         where id = r.id;
        return jsonb_build_object('run', r.id, 'done', true);
      end if;
      -- re-check every reference column of the audit just before removal
      for v_col in select * from pipeline.evidence_audit_columns order by tbl, col loop
        execute format('insert into pipeline.retention_evidence_skips(run_id, evidence_id, reason) select %L::uuid, b.id, %L from pg_temp.ev_batch b where exists (select 1 from %s t where t.%I = b.id) on conflict do nothing',
                       r.id, 'referenced: ' || v_col.tbl || '.' || v_col.col, v_col.tbl, v_col.col);
      end loop;
      create temporary table ev_gone (storage_path text) on commit drop;
      for v_ev in select b.id, b.storage_path from ev_batch b
                   where not exists (select 1 from pipeline.retention_evidence_skips s where s.run_id = r.id and s.evidence_id = b.id) loop
        begin
          delete from pipeline.evidence_artifacts where id = v_ev.id;
          insert into ev_gone values (v_ev.storage_path);
          v_del := v_del + 1;
        exception when foreign_key_violation then
          insert into pipeline.retention_evidence_skips(run_id, evidence_id, reason) values (r.id, v_ev.id, 'still referenced (foreign key)') on conflict do nothing;
          v_skip := v_skip + 1;
        end;
      end loop;
      -- a file goes only when no remaining evidence record uses it
      insert into pipeline.retention_file_queue(run_id, bucket, name, size)
      select r.id, 'evidence', o.name, coalesce((o.metadata->>'size')::bigint, 0)
        from (select distinct storage_path from ev_gone where storage_path is not null) g
        join storage.objects o on o.bucket_id = 'evidence' and o.name = g.storage_path
       where not exists (select 1 from pipeline.evidence_artifacts e where e.storage_path = g.storage_path);
      get diagnostics v_q = row_count;
      update pipeline.retention_runs set removed = removed + v_del, updated_at = now(),
             note = format('Running: %s records removed, %s MB of files so far.', removed + v_del, round(bytes / 1e6)) where id = r.id;
      if v_q > 0 then perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'retention_files', 'run_id', r.id)); end if;
      return jsonb_build_object('run', r.id, 'removed', v_del, 'files_queued', v_q, 'skipped_fk', v_skip);
    elsif r.category = 'evidence_audit' then
      for v_col in select * from pipeline.evidence_audit_columns where done_at is null order by tbl, col limit security.pipeline_num_v1('retention.audit_columns_per_tick', 3)::int loop
        execute format('insert into pipeline.evidence_audit_refs(evidence_id) select distinct %I from %s where %I is not null on conflict do nothing', v_col.col, v_col.tbl, v_col.col);
        get diagnostics v_n = row_count;
        update pipeline.evidence_audit_columns set done_at = now(), rows_found = v_n where tbl = v_col.tbl and col = v_col.col;
        v_done := v_done + 1;
      end loop;
      if v_done = 0 then
        perform security.retention_estimate_v1('evidence_audit');
        update pipeline.retention_runs set status = 'done', finished_at = now(), updated_at = now(),
               removed = 0, estimate = (select to_jsonb(e) from pipeline.retention_estimates e where e.category = 'evidence_audit'),
               note = format('Audit complete: %s evidence records are not referenced anywhere (%s MB of files). Nothing was deleted.',
                             (select purgeable_rows from pipeline.retention_estimates where category = 'evidence_audit'),
                             round(coalesce((select purgeable_bytes from pipeline.retention_estimates where category = 'evidence_audit'), 0) / 1e6))
         where id = r.id;
      else
        update pipeline.retention_runs set note = format('Auditing: %s of %s reference columns done.', (select count(*) from pipeline.evidence_audit_columns where done_at is not null),
               (select count(*) from pipeline.evidence_audit_columns)), updated_at = now() where id = r.id;
      end if;
      return jsonb_build_object('audited_columns', v_done);
    end if;

    if v_n = 0 then
      perform security.retention_estimate_v1(r.category);
      update pipeline.retention_runs set status = 'done', finished_at = now(), updated_at = now(), note = format('Done: %s rows removed.', removed) where id = r.id;
    else
      update pipeline.retention_runs set removed = removed + v_n, note = format('Running: %s rows removed so far.', removed + v_n), updated_at = now() where id = r.id;
    end if;
    return jsonb_build_object('run', r.id, 'removed', v_n);
  exception when others then
    update pipeline.retention_runs set status = 'failed', error = left(sqlerrm, 500), finished_at = now(), updated_at = now() where id = r.id;
    return jsonb_build_object('failed', r.id, 'error', sqlerrm);
  end;
end $$;


ALTER FUNCTION "security"."retention_tick_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."retry_cap_v1"("p_kind" "text") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_max int := greatest(1, security.pipeline_num_v1('waste.retry_max_attempts', 3)::int);
        v_min numeric := security.pipeline_num_v1('waste.retry_min_yield_pct', 15);
        v_days int := security.pipeline_num_v1('waste.retry_window_days', 14)::int;
        v_sample int := security.pipeline_num_v1('waste.retry_min_sample', 200)::int;
        v_n bigint; v_ok bigint;
begin
  -- the most attempts worth making: attempt k is made while its recent success rate is at least the setting (or it has too few recent cases)
  if p_kind <> 'ai_match' then return v_max; end if;
  for k in 2 .. v_max loop
    -- 22 Oct 2026 (NZ review fix 7): an attempt counts as a success only when the page it chose was then read as the course's page
    select count(*), count(*) filter (where q.state = 'chosen' and exists (select 1 from pipeline.coverage_course_pages g
                                                                         where g.course_id = q.course_id and g.url = q.chosen_url and g.status = 'bound' and g.read_status = 'read')) into v_n, v_ok
      from pipeline.coverage_ai_match q
     where q.attempt = k and q.state in ('chosen', 'none') and q.decided_at > now() - make_interval(days => v_days);
    if v_n >= v_sample and 100.0 * v_ok / v_n < v_min then return k - 1; end if;
  end loop;
  return v_max;
end $$;


ALTER FUNCTION "security"."retry_cap_v1"("p_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."review_reason_key"("p_reason" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $_$
  select regexp_replace(regexp_replace(coalesce(p_reason,''),'(A\$|AUD\s?\$?|\$)\s?[0-9][0-9,]*(\.[0-9]+)?','[amount]','g'),'\m[0-9][0-9,\.]*\M','[n]','g')
$_$;


ALTER FUNCTION "security"."review_reason_key"("p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."rollup_run_target_v1"("p_code" "text", "p_tick" timestamp with time zone, "p_due" timestamp with time zone, "p_due_minutes" integer) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_t pipeline.rollup_targets; v_t0 timestamptz := clock_timestamp(); v_ms int; v_err text;
begin
  select * into v_t from pipeline.rollup_targets where target_code = p_code for update skip locked;
  if not found then return 'locked'; end if;
  if md5(v_t.call_sql) <> v_t.call_md5 then
    insert into pipeline.rollup_runs(tick_at, target_code, mode, due_at, due_minutes, started_at, finished_at, status, error)
    values (p_tick, p_code, v_t.mode, p_due, p_due_minutes, v_t0, clock_timestamp(), 'refused', 'call_sql changed since registration (md5)');
    update pipeline.rollup_targets set last_status = 'refused', last_error = 'call_sql changed since registration (md5)', updated_at = now() where target_code = p_code;
    return 'refused';
  end if;
  if v_t.mode = 'shadow' then
    insert into pipeline.rollup_runs(tick_at, target_code, mode, due_at, due_minutes, started_at, finished_at, ms, status)
    values (p_tick, p_code, 'shadow', p_due, p_due_minutes, v_t0, clock_timestamp(), 0, 'shadow_due');
    update pipeline.rollup_targets set last_due_at = p_due, last_status = 'shadow_due', updated_at = now() where target_code = p_code;
    return 'shadow_due';
  end if;
  begin
    execute v_t.call_sql;
    v_ms := round(extract(epoch from clock_timestamp() - v_t0) * 1000)::int;
    insert into pipeline.rollup_runs(tick_at, target_code, mode, due_at, due_minutes, started_at, finished_at, ms, status)
    values (p_tick, p_code, 'live', p_due, p_due_minutes, v_t0, clock_timestamp(), v_ms, 'succeeded');
    update pipeline.rollup_targets set last_due_at = p_due, last_started_at = v_t0, last_finished_at = clock_timestamp(), last_status = 'succeeded',
           last_error = null, last_ms = v_ms, updated_at = now() where target_code = p_code;
    return 'succeeded';
  exception when others then
    get stacked diagnostics v_err = message_text;
    v_ms := round(extract(epoch from clock_timestamp() - v_t0) * 1000)::int;
    insert into pipeline.rollup_runs(tick_at, target_code, mode, due_at, due_minutes, started_at, finished_at, ms, status, error)
    values (p_tick, p_code, 'live', p_due, p_due_minutes, v_t0, clock_timestamp(), v_ms, 'failed', left(v_err, 1000));
    -- a failed run counts as run (as a failed cron run does): the next run is at the next scheduled minute
    update pipeline.rollup_targets set last_due_at = p_due, last_started_at = v_t0, last_finished_at = clock_timestamp(), last_status = 'failed',
           last_error = left(v_err, 1000), last_ms = v_ms, updated_at = now() where target_code = p_code;
    return 'failed';
  end;
end $$;


ALTER FUNCTION "security"."rollup_run_target_v1"("p_code" "text", "p_tick" timestamp with time zone, "p_due" timestamp with time zone, "p_due_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."rollup_shadow_report_v1"("p_days" integer DEFAULT 7) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_from timestamptz; v_rows jsonb;
begin
  select greatest(now() - make_interval(days => p_days), min(created_at)) into v_from from pipeline.rollup_targets where rollup_group = 'A';
  select coalesce(jsonb_agg(x order by x->>'target'), '[]'::jsonb) into v_rows from (
    select jsonb_build_object(
      'target', t.target_code, 'legacy_job', t.legacy_job, 'schedule', t.schedule, 'mode', t.mode,
      -- dispatches, not minutes: after a pause (maintenance) the scheduler catches the missed minutes up once, the legacy job not at all
      'scheduler_dispatches', coalesce(s.dispatches, 0),
      'scheduler_due_minutes', coalesce(s.due, 0),
      'legacy_starts', coalesce(l.starts, 0),
      'difference', coalesce(s.dispatches, 0) - coalesce(l.starts, 0),
      'max_lag_seconds', round(coalesce(s.lag, 0)::numeric, 1),
      'collapsed_dispatches', coalesce(s.collapsed, 0),
      'matches', abs(coalesce(s.dispatches, 0) - coalesce(l.starts, 0)) <= greatest(1, ceil(extract(epoch from now() - v_from) / 86400))) x
      from pipeline.rollup_targets t
      left join lateral (select count(*) dispatches, sum(r.due_minutes) due, max(extract(epoch from r.started_at - r.due_at)) lag, count(*) filter (where r.due_minutes > 1) collapsed
                           from pipeline.rollup_runs r where r.target_code = t.target_code and r.due_at >= v_from and r.status in ('shadow_due', 'succeeded', 'failed')) s on true
      left join lateral (select count(*) starts from cron.job j join cron.job_run_details d on d.jobid = j.jobid
                          where j.jobname = t.legacy_job and d.start_time >= v_from) l on true
     where t.rollup_group = 'A') z(x);
  return jsonb_build_object('from', v_from, 'to', now(), 'targets', jsonb_array_length(v_rows),
    'all_match', not exists (select 1 from jsonb_array_elements(v_rows) e where not (e->>'matches')::boolean), 'rows', v_rows);
end $$;


ALTER FUNCTION "security"."rollup_shadow_report_v1"("p_days" integer) OWNER TO "postgres";


CREATE PROCEDURE "security"."rollup_tick_v1"()
    LANGUAGE "plpgsql"
    AS $$
declare v_t0 timestamptz := clock_timestamp(); v_tick timestamptz := date_trunc('minute', now()); v_budget int; v_finish int; v_keep int; v_back int;
        v_r record; v_el numeric; v_n int := 0;
begin
  if security.pipeline_num_v1('rollup.scheduler_on', 0) < 1 then return; end if;
  if not pg_try_advisory_lock(hashtext('cf247:rollup_tick')) then return; end if;  -- fixed: the one tick lock (a tick still running keeps the next one out)
  v_budget := security.pipeline_num_v1('rollup.tick_budget_seconds', 60)::int;
  v_finish := security.pipeline_num_v1('rollup.tick_finish_by_seconds', 100)::int;
  v_keep := security.pipeline_num_v1('rollup.keep_days', 14)::int;
  v_back := security.pipeline_num_v1('rollup.catch_up_minutes', 180)::int;
  for v_r in
    select t.target_code, t.mode, d.due_at, d.n,
           case when t.mode = 'shadow' then 0 else coalesce(e.max_ms, t.expected_ms, 0) end exp_ms
      from pipeline.rollup_targets t
      cross join lateral (
        select max(m) due_at, count(*) n
          from generate_series(greatest(coalesce(t.last_due_at + interval '1 minute', v_tick), v_tick - make_interval(mins => v_back)), v_tick, interval '1 minute') m
         where security.cron_matches_v1(t.schedule, m)) d
      left join lateral (
        select max(x.ms) max_ms from pipeline.rollup_runs x
         where x.target_code = t.target_code and x.status = 'succeeded' and x.started_at > now() - make_interval(days => v_keep)) e on true
     where t.enabled and d.due_at is not null
     order by t.priority, d.due_at, t.target_code
  loop
    v_el := extract(epoch from clock_timestamp() - v_t0);
    if v_n > 0 and (v_el > v_budget or v_el + v_r.exp_ms / 1000.0 > v_finish) then
      if v_r.mode = 'live' then
        insert into pipeline.rollup_runs(tick_at, target_code, mode, due_at, due_minutes, status)
        values (v_tick, v_r.target_code, 'live', v_r.due_at, v_r.n::int, 'deferred');
        commit;
      end if;
      continue;  -- stays due for the next tick
    end if;
    perform security.rollup_run_target_v1(v_r.target_code, v_tick, v_r.due_at, v_r.n::int);
    v_n := v_n + 1;
    commit;
  end loop;
  delete from pipeline.rollup_runs where tick_at < now() - make_interval(days => v_keep);
  commit;
  perform pg_advisory_unlock(hashtext('cf247:rollup_tick'));  -- fixed: the one tick lock
end $$;


ALTER PROCEDURE "security"."rollup_tick_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."rule6_list_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int;
begin
  with s as (select url, provider_id from pipeline.coverage_course_pages where read_status = 'read' group by 1, 2 having count(*) > 1),
  r as (select pg.url, pg.provider_id, pg.course_id, pg.evidence_id, c.display_title,
               regexp_replace(lower(c.display_title), '[^a-z]', '', 'g') t,
               regexp_replace(lower(regexp_replace(pg.url, '^https?://[^/]+', '')), '[^a-z]', '', 'g') u
          from pipeline.coverage_course_pages pg join s using (url, provider_id) join catalogue.courses c on c.id = pg.course_id
         where pg.read_status = 'read'),
  g as (select url, provider_id from r group by 1, 2 having count(distinct t) > 1),
  m as (select r.*,
               (select r2.display_title from r r2 where r2.url = r.url and r2.provider_id = r.provider_id and strpos(r2.u, r2.t) > 0 order by length(r2.t) desc limit 1) named,
               (select max(length(r2.t)) from r r2 where r2.url = r.url and r2.provider_id = r.provider_id and strpos(r2.u, r2.t) > 0) best_len
          from r join g using (url, provider_id))
  insert into pipeline.rule6_page_checks(course_id, provider_id, url, evidence_id, storage_path, course_code, named_course)
  select m.course_id, m.provider_id, m.url, m.evidence_id, e.storage_path,
         (select cr.registration_code from catalogue.course_registrations cr where cr.course_id = m.course_id and lower(cr.scheme) = 'cricos' limit 1), m.named
    from m left join pipeline.evidence_artifacts e on e.id = m.evidence_id
   where m.best_len is not null and not (strpos(m.u, m.t) > 0 and length(m.t) = m.best_len)
  on conflict (course_id) do nothing;
  get diagnostics n = row_count;
  return n;
end $$;


ALTER FUNCTION "security"."rule6_list_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."run_now_cohort_create_v1"("p_job" "text", "p_requester" "uuid", "p_reason" "text", "p_label" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_cap int := security.pipeline_num_v1('run_now.pilot_cap', 20)::int;
        v_scan int := security.pipeline_num_v1('run_now.cohort_scan_rows', 1500)::int;
        v_top int := security.pipeline_num_v1('run_now.cohort_top_au_universities', 10)::int;
        v_id uuid := gen_random_uuid(); v_rows int; v_filled_rows int; v_courses int; v_providers int; v_n int; v_unis jsonb; v_provs uuid[]; v_scope uuid[];
        v_rule constant text := 'top run_now.cohort_top_au_universities Australian universities by active courses; intake-dates-plan-v3 filled within them; most fields gained first; round-robin over universities, then evidence patterns; md5(course id) breaks ties';  -- fixed: the name of this rule in the record
begin
  if p_job is distinct from 'intake-dates-apply' then raise exception 'no cohort rule for job %', p_job; end if;
  if p_requester is null then raise exception 'a requester is required'; end if;
  if coalesce(btrim(p_reason), '') = '' then raise exception 'a reason is required'; end if;
  if not exists (select 1 from pipeline.automation_catalogue where jobname = p_job) then raise exception 'job % is not catalogued', p_job; end if;
  -- the scope (Platform Admin 4 Nov 2026 20:53: "top Australian unis with maximum courses only"): the active Australian universities
  -- (institution type 'university', country AU) with the most active courses; the cohort is never widened beyond them
  select coalesce(jsonb_agg(jsonb_build_object('provider_id', x.id, 'name', x.name, 'active_courses', x.n) order by x.n desc, md5(x.id::text)), '[]'::jsonb), array_agg(x.id)
    into v_unis, v_provs
    from (select p.id, coalesce(p.display_name, p.canonical_name) name, count(c.id) n
            from catalogue.providers p
            join ref.countries co on co.id = p.country_id and co.iso_alpha2 = 'AU'  -- fixed: the Platform Admin's scope (Australian)
            join ref.provider_types t on t.id = p.provider_type_id and t.code = 'university'  -- fixed: the Platform Admin's scope (universities)
            join catalogue.courses c on c.provider_id = p.id and c.lifecycle_status = 'active'
           where p.lifecycle_status = 'active'
           group by p.id, 2 order by count(c.id) desc, md5(p.id::text) limit v_top) x;
  v_scope := array(select c.id from catalogue.courses c where c.provider_id = any (coalesce(v_provs, '{}')) and c.lifecycle_status = 'active');
  -- one statement: the job's plan for the scope's courses (read only), the denominator, the cohort record and its members
  with plan as materialized (select * from security.intake_dates_plan_v3(v_scope, v_scan)),
  f as (select * from plan where outcome = 'filled'),
  sel as (select (select count(*) from plan) rows_planned, count(*) rows_eligible, count(distinct course_id) courses_eligible, count(distinct provider_id) providers_eligible from f),
  coh as (
    insert into pipeline.run_now_cohorts(id, job, label, selection_rule, selection, requested_by, reason)
    select v_id, p_job, coalesce(nullif(btrim(p_label), ''), 'Intake dates pilot ' || to_char(now() at time zone 'Australia/Melbourne', 'DD Mon YYYY HH24:MI')), v_rule,
           jsonb_build_object('rows_planned', sel.rows_planned, 'rows_eligible', sel.rows_eligible, 'courses_eligible', sel.courses_eligible,
                              'providers_eligible', sel.providers_eligible, 'cap', v_cap, 'scan_rows', v_scan,
                              'top_au_universities', v_top, 'scope_courses', cardinality(v_scope),
                              'universities', (select coalesce(jsonb_agg(u || jsonb_build_object('eligible_courses', (select count(distinct f.course_id) from f where f.provider_id = (u->>'provider_id')::uuid),
                                                                                    'eligible_values', (select count(*) from f where f.provider_id = (u->>'provider_id')::uuid))), '[]'::jsonb)
                                               from jsonb_array_elements(v_unis) u),
                              'skipped_by_reason',
                              (select coalesce(jsonb_object_agg(r, n), '{}'::jsonb) from (select coalesce(reason, outcome) r, count(*) n from plan where outcome <> 'filled' group by 1) x)),
           p_requester, btrim(p_reason)
      from sel returning id),
  c as (select course_id, min(provider_id::text)::uuid provider_id,
               array_remove(array[case when bool_or(new_year is not null) then 'year' end, case when bool_or(new_start is not null) then 'start_date' end,
                                  case when bool_or(new_deadline is not null) then 'application_deadline' end], null) fills,
               string_agg(distinct coalesce(start_precision, '-') || '/' || coalesce(deadline_kind, '-'), '+') pattern,
               jsonb_agg(jsonb_build_object('intake_id', intake_id, 'proposal_id', proposal_id, 'calendar_evidence_id', calendar_evidence_id, 'calendar_url', calendar_url,
                         'periods', periods, 'page_quote', page_quote, 'start_quote', start_quote, 'deadline_quote', deadline_quote, 'deadline_kind', deadline_kind,
                         'before', before_value, 'planned', jsonb_build_object('year', new_year, 'start_date', new_start, 'application_deadline', new_deadline), 'rule', rule)
                         order by intake_id) evidence
          from f group by course_id),
  r as (select c.*, row_number() over (partition by provider_id order by cardinality(fills) desc, md5(course_id::text)) rp,
               row_number() over (partition by pattern order by cardinality(fills) desc, md5(course_id::text)) rq from c),
  pick as (select r.*, row_number() over (order by rp, rq, cardinality(fills) desc, md5(course_id::text)) n from r),
  ins as (insert into pipeline.run_now_cohort_members(cohort_id, course_id, provider_id, pick, pattern, fills, evidence)
          select coh.id, pick.course_id, pick.provider_id, pick.n, pick.pattern, pick.fills, pick.evidence from pick, coh where pick.n <= v_cap returning 1)
  select (select count(*) from ins), sel.rows_planned, sel.rows_eligible, sel.courses_eligible, sel.providers_eligible
    into v_n, v_rows, v_filled_rows, v_courses, v_providers from sel;
  return jsonb_build_object('cohort_id', v_id, 'job', p_job, 'members', v_n, 'universities', (select selection->'universities' from pipeline.run_now_cohorts where id = v_id), 'cap', v_cap, 'rows_planned', v_rows, 'rows_eligible', v_filled_rows,
                            'courses_eligible', v_courses, 'providers_eligible', v_providers,
                            'providers_in_cohort', (select count(distinct provider_id) from pipeline.run_now_cohort_members where cohort_id = v_id),
                            'patterns_in_cohort', (select count(distinct pattern) from pipeline.run_now_cohort_members where cohort_id = v_id));
end $$;


ALTER FUNCTION "security"."run_now_cohort_create_v1"("p_job" "text", "p_requester" "uuid", "p_reason" "text", "p_label" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."run_now_cohort_create_v1"("p_job" "text", "p_requester" "uuid", "p_reason" "text", "p_label" "text") IS 'CF-247 Run now (Platform Admin 4 Nov 2026 20:05 §1): picks a fixed cohort of at most run_now.pilot_cap courses for job intake-dates-apply, only from the run_now.cohort_top_au_universities Australian universities with the most active courses (Platform Admin 20:53), from its own plan (security.intake_dates_plan_v2, read only) over run_now.cohort_scan_rows candidate rows of their courses; a short scope gives a smaller cohort, never a wider one; records the rule, the denominator and each member''s evidence. Never hand-picked.';



CREATE OR REPLACE FUNCTION "security"."run_now_cohort_verify_v1"("p_cohort" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c pipeline.run_now_cohorts%rowtype; m record; v_rows jsonb := '[]'; v_course jsonb; v_web jsonb; v_zoho jsonb; v_added jsonb; v_after jsonb;
        t_sel int := 0; t_elig int := 0; t_adm int := 0; t_pub int := 0; t_zoho int := 0; t_wrong int := 0; v_n int; v_p int; v_w int;
begin
  select * into c from pipeline.run_now_cohorts where id = p_cohort;
  if c.id is null then raise exception 'unknown cohort'; end if;
  for m in select * from pipeline.run_now_cohort_members where cohort_id = p_cohort order by pick loop
    t_sel := t_sel + 1;
    t_elig := t_elig + jsonb_array_length(m.evidence);
    -- values filled for this course since the cohort was picked, with the evidence the job recorded
    select coalesce(jsonb_agg(jsonb_build_object('intake_id', d.intake_id, 'before', d.before_value, 'after', d.after_value, 'periods', d.periods,
                     'page_quote', d.page_quote, 'start_quote', d.start_quote, 'deadline_quote', d.deadline_quote, 'calendar_url', d.calendar_url, 'applied_at', d.applied_at,
                     'as_planned', d.after_value = coalesce(d.before_value, '{}') || jsonb_strip_nulls((select e->'planned' from jsonb_array_elements(m.evidence) e where (e->>'intake_id')::uuid = d.intake_id)))
                     order by d.intake_id), '[]'), count(*)
      into v_added, v_n
      from pipeline.course_intake_dates d where d.course_id = m.course_id and d.outcome = 'filled' and d.applied_at >= c.created_at;
    select coalesce(jsonb_agg(jsonb_build_object('intake_id', i.id, 'label', i.intake_label, 'year', i.intake_year, 'start_date', i.start_date,
                     'application_deadline', i.application_deadline, 'status', i.status) order by i.id), '[]')
      into v_after from catalogue.course_intakes i where i.id in (select (e->>'intake_id')::uuid from jsonb_array_elements(m.evidence) e);
    begin v_web := api.website_v2_course_item(m.course_id) -> 'intakes'; exception when others then v_web := jsonb_build_object('error', sqlerrm); end;
    begin v_zoho := public.zoho_edge_course_lookup_v1(m.course_id::text); exception when others then v_zoho := jsonb_build_object('error', sqlerrm); end;
    -- a filled value is published when the website returns an intake with the same start date (or the same year where no date was filled)
    select count(*) filter (where exists (select 1 from jsonb_array_elements(case when jsonb_typeof(v_web) = 'array' then v_web else '[]' end) w
                                           where (a->'after'->>'start_date' is not null and w->>'start_date' = a->'after'->>'start_date')
                                              or (a->'after'->>'start_date' is null and w->>'year' = a->'after'->>'year'))),
           count(*) filter (where not coalesce((a->>'as_planned')::boolean, false))
      into v_p, v_w from jsonb_array_elements(v_added) a;
    t_adm := t_adm + v_n; t_pub := t_pub + v_p; t_wrong := t_wrong + v_w;
    if v_zoho ? 'error' is false and v_zoho is not null then t_zoho := t_zoho + 1; end if;
    v_rows := v_rows || jsonb_build_array(jsonb_build_object('pick', m.pick, 'course_id', m.course_id, 'provider_id', m.provider_id, 'pattern', m.pattern, 'fills', m.fills,
      'at_selection', m.evidence, 'now', v_after, 'added', v_added, 'admitted', v_n, 'published', v_p, 'not_as_planned', v_w,
      'website_intakes', v_web, 'zoho_intakes', coalesce(v_zoho->'intakes', v_zoho->'course'->'intakes', case when v_zoho ? 'error' then v_zoho end, to_jsonb('no intake field'::text))));
  end loop;
  return jsonb_build_object('cohort_id', c.id, 'job', c.job, 'label', c.label, 'rule', c.selection_rule, 'picked_at', c.created_at, 'selection', c.selection,
    'totals', jsonb_build_object('selected', t_sel, 'eligible_values', t_elig, 'admitted', t_adm, 'published', t_pub, 'not_as_planned', t_wrong, 'zoho_checked', t_zoho,
      'skipped_or_failed', (select coalesce(jsonb_object_agg(k, n), '{}'::jsonb) from (select d.outcome || coalesce(': ' || d.reason, '') k, count(*) n
                            from pipeline.course_intake_dates d join pipeline.run_now_cohort_members mm on mm.course_id = d.course_id and mm.cohort_id = c.id
                           where d.outcome <> 'filled' and d.applied_at >= c.created_at group by 1) x),
      'vendor_calls', (select coalesce(sum((j.result->>'vendor_calls')::int), 0) from pipeline.admin_jobs j where j.kind = 'job_run_now' and j.args->>'cohort_id' = c.id::text)),
    'runs', (select coalesce(jsonb_agg(jsonb_build_object('run_id', j.id, 'state', j.state, 'reason', j.reason, 'started_at', j.started_at, 'finished_at', j.finished_at,
                     'processed', j.result->'processed', 'admitted', j.result->'admitted', 'skipped', j.result->'skipped', 'failed', j.result->'failed', 'refused', j.result->'refused')
                     order by j.created_at), '[]') from pipeline.admin_jobs j where j.kind = 'job_run_now' and j.args->>'cohort_id' = c.id::text),
    'courses', v_rows);
end $$;


ALTER FUNCTION "security"."run_now_cohort_verify_v1"("p_cohort" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."run_now_cohort_verify_v1"("p_cohort" "uuid") IS 'CF-247 Run now (Platform Admin 4 Nov 2026 20:02 §6, 20:05 §4): per cohort course the evidence at selection, the values now, the rows filled since selection with their quotes, the Website API v2 read-back and Zoho where it answers; totals for the validation table. Writes nothing itself.';



CREATE OR REPLACE FUNCTION "security"."scheduler_actor_display"("p_actor" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    nullif(trim(u.raw_user_meta_data->>'full_name'),''),
    nullif(trim(u.raw_user_meta_data->>'name'),''),
    nullif(trim(u.email),''),
    case when p_actor is null then null else 'User '||left(p_actor::text,8) end
  )
  from auth.users u
  where u.id=p_actor
$$;


ALTER FUNCTION "security"."scheduler_actor_display"("p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scheduler_capture_action_actor"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_email text;
  v_display text;
begin
  if new.actor_id is not null and (new.actor_display_snapshot is null or new.actor_email_snapshot is null) then
    select
      coalesce(nullif(trim(u.raw_user_meta_data->>'full_name'),''),nullif(trim(u.raw_user_meta_data->>'name'),''),nullif(trim(u.email),''),'User '||left(u.id::text,8)),
      nullif(trim(u.email),'')
    into v_display,v_email
    from auth.users u where u.id=new.actor_id;
    new.actor_display_snapshot:=coalesce(new.actor_display_snapshot,v_display,'User '||left(new.actor_id::text,8));
    new.actor_email_snapshot:=coalesce(new.actor_email_snapshot,v_email);
  end if;
  return new;
end
$$;


ALTER FUNCTION "security"."scheduler_capture_action_actor"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scheduler_capture_policy_creator"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_email text;
  v_display text;
begin
  if new.created_by is null and v_actor is not null then
    new.created_by:=v_actor;
  end if;
  if new.created_by is not null and (new.created_by_display_snapshot is null or new.created_by_email_snapshot is null) then
    select
      coalesce(nullif(trim(u.raw_user_meta_data->>'full_name'),''),nullif(trim(u.raw_user_meta_data->>'name'),''),nullif(trim(u.email),''),'User '||left(u.id::text,8)),
      nullif(trim(u.email),'')
    into v_display,v_email
    from auth.users u where u.id=new.created_by;
    new.created_by_display_snapshot:=coalesce(new.created_by_display_snapshot,v_display,'User '||left(new.created_by::text,8));
    new.created_by_email_snapshot:=coalesce(new.created_by_email_snapshot,v_email);
  elsif new.created_by is null and new.created_by_display_snapshot is null then
    new.created_by_display_snapshot:='System / automation';
  end if;
  return new;
end
$$;


ALTER FUNCTION "security"."scheduler_capture_policy_creator"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scheduler_entity_display"("p_entity_type" "text", "p_entity_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_label text; begin
 if p_entity_id is null then return null; end if;
 case lower(coalesce(p_entity_type,''))
  when 'provider' then select coalesce(nullif(trim(p.display_name),''),nullif(trim(p.canonical_name),'')) into v_label from catalogue.providers p where p.id=p_entity_id;
  when 'course' then select coalesce(nullif(trim(c.display_title),''),nullif(trim(c.canonical_title),''),nullif(trim(c.course_code),'')) into v_label from catalogue.courses c where c.id=p_entity_id;
  when 'campus' then select nullif(trim(c.name),'') into v_label from catalogue.campuses c where c.id=p_entity_id;
  when 'scholarship' then select nullif(trim(s.name),'') into v_label from scholarship.scholarships s where s.id=p_entity_id;
  else v_label:=null;
 end case;
 return v_label;
end $$;


ALTER FUNCTION "security"."scheduler_entity_display"("p_entity_type" "text", "p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scheduler_policies_list_v1_browser_bridge"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0, "p_query" "text" DEFAULT ''::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_limit integer:=least(greatest(coalesce(p_limit,50),1),100);
  v_offset integer:=greatest(coalesce(p_offset,0),0);
  v_query text:=replace(replace(replace(lower(trim(coalesce(p_query,''))), E'\\', E'\\\\'), '%', E'\\%'), '_', E'\\_');
begin
  if auth.uid() is null or security.current_role_rank() < 3 then
    raise exception 'curator role required' using errcode='42501';
  end if;
  return jsonb_build_object(
    'total',(
      select count(*) from pipeline.refresh_policies p
      left join pipeline.sources s on s.id=p.source_id
      left join pipeline.layer2_source_profiles lp on lp.id=p.source_profile_id
      left join pipeline.sources ps on ps.id=lp.source_id
      where p.layer between 1 and 3
        and (p.source_id is not null or p.source_profile_id is not null or p.entity_id is not null)
        and (v_query=''
          or lower(coalesce(s.label,'')) like '%'||v_query||'%'
          or lower(coalesce(ps.label,'')) like '%'||v_query||'%'
          or lower(coalesce(lp.profile_key,'')) like '%'||v_query||'%'
          or lower(coalesce(lp.domain,'')) like '%'||v_query||'%'
          or lower(replace(coalesce(lp.domain,''),'_',' ')) like '%'||v_query||'%'
          or lower(coalesce(lp.acquisition_method,'')) like '%'||v_query||'%'
          or lower(coalesce(p.country_code,'')) like '%'||v_query||'%'
          or lower(coalesce(p.entity_type,'')) like '%'||v_query||'%'
          or lower(coalesce(security.scheduler_entity_display(p.entity_type,p.entity_id),'')) like '%'||v_query||'%'
          or lower(coalesce(p.entity_id::text,'')) like '%'||v_query||'%'
          or lower(coalesce(p.source_id::text,'')) like '%'||v_query||'%'
          or lower(coalesce(p.source_profile_id::text,'')) like '%'||v_query||'%'
          or lower(coalesce(p.created_by_display_snapshot,case when p.created_by is null then 'System / legacy' when exists(select 1 from auth.users au where au.id=p.created_by and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) then security.scheduler_actor_display(p.created_by) else 'Former user' end,'')) like '%'||v_query||'%'
          or (p.created_by is not null and not exists(select 1 from auth.users au where au.id=p.created_by and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) and lower('Former user — '||coalesce(p.created_by_display_snapshot,security.scheduler_actor_display(p.created_by),'unknown')) like '%'||v_query||'%')
          or lower(coalesce(p.owner_display_snapshot,case when p.owner_user_id is null then null when exists(select 1 from auth.users au where au.id=p.owner_user_id and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) then security.scheduler_actor_display(p.owner_user_id) else 'Former user' end,'')) like '%'||v_query||'%'
          or (p.owner_user_id is not null and not exists(select 1 from auth.users au where au.id=p.owner_user_id and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) and lower('Former user — '||coalesce(p.owner_display_snapshot,security.scheduler_actor_display(p.owner_user_id),'unknown')) like '%'||v_query||'%')
          or lower(coalesce(p.freshness_class,'')) like '%'||v_query||'%'
          or lower(coalesce(p.cadence_interval::text,'')) like '%'||v_query||'%'
          or lower('layer '||p.layer::text) like '%'||v_query||'%'
          or (v_query='enabled' and p.enabled)
          or (v_query='disabled' and not p.enabled))
    ),
    'items',coalesce((
      select jsonb_agg(to_jsonb(x) order by x.next_due_at nulls last,x.id) from (
        select p.id,p.country_code,p.layer,p.source_id,p.source_profile_id,p.entity_type,p.entity_id,
               p.freshness_class,p.cadence_interval,p.next_due_at,p.hash_sensitive,p.important_date_sensitive,
               p.enabled,p.change_control_ref,p.updated_at,
               coalesce(s.label,ps.label,lp.profile_key,security.scheduler_entity_display(p.entity_type,p.entity_id),case when p.entity_id is not null then initcap(replace(coalesce(p.entity_type,'entity'),'_',' ')) else null end,'Scheduled task') as task_label,
               coalesce(s.label,ps.label) as source_label,lp.profile_key as source_profile_key,lp.domain as dataset_domain,lp.acquisition_method,
               p.created_by,
               coalesce(p.created_by_display_snapshot,case when p.created_by is null then 'System / legacy' when exists(select 1 from auth.users au where au.id=p.created_by and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) then security.scheduler_actor_display(p.created_by) else 'Former user' end) as created_by_display,
               case when p.created_by is null then 'system_or_legacy' when exists(select 1 from auth.users au where au.id=p.created_by and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) then 'active' else 'former_user' end as created_by_state,
               p.owner_user_id,
               coalesce(p.owner_display_snapshot,case when p.owner_user_id is null then null when exists(select 1 from auth.users au where au.id=p.owner_user_id and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) then security.scheduler_actor_display(p.owner_user_id) else 'Former user' end) as owner_display,
               case when p.owner_user_id is null then 'unassigned' when exists(select 1 from auth.users au where au.id=p.owner_user_id and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) then 'active' else 'former_user' end as owner_state
        from pipeline.refresh_policies p
        left join pipeline.sources s on s.id=p.source_id
        left join pipeline.layer2_source_profiles lp on lp.id=p.source_profile_id
        left join pipeline.sources ps on ps.id=lp.source_id
        where p.layer between 1 and 3
          and (p.source_id is not null or p.source_profile_id is not null or p.entity_id is not null)
          and (v_query=''
            or lower(coalesce(s.label,'')) like '%'||v_query||'%'
            or lower(coalesce(ps.label,'')) like '%'||v_query||'%'
            or lower(coalesce(lp.profile_key,'')) like '%'||v_query||'%'
            or lower(coalesce(lp.domain,'')) like '%'||v_query||'%'
            or lower(replace(coalesce(lp.domain,''),'_',' ')) like '%'||v_query||'%'
            or lower(coalesce(lp.acquisition_method,'')) like '%'||v_query||'%'
            or lower(coalesce(p.country_code,'')) like '%'||v_query||'%'
            or lower(coalesce(p.entity_type,'')) like '%'||v_query||'%'
            or lower(coalesce(security.scheduler_entity_display(p.entity_type,p.entity_id),'')) like '%'||v_query||'%'
            or lower(coalesce(p.entity_id::text,'')) like '%'||v_query||'%'
            or lower(coalesce(p.source_id::text,'')) like '%'||v_query||'%'
            or lower(coalesce(p.source_profile_id::text,'')) like '%'||v_query||'%'
            or lower(coalesce(p.created_by_display_snapshot,case when p.created_by is null then 'System / legacy' when exists(select 1 from auth.users au where au.id=p.created_by and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) then security.scheduler_actor_display(p.created_by) else 'Former user' end,'')) like '%'||v_query||'%'
            or (p.created_by is not null and not exists(select 1 from auth.users au where au.id=p.created_by and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) and lower('Former user — '||coalesce(p.created_by_display_snapshot,security.scheduler_actor_display(p.created_by),'unknown')) like '%'||v_query||'%')
            or lower(coalesce(p.owner_display_snapshot,case when p.owner_user_id is null then null when exists(select 1 from auth.users au where au.id=p.owner_user_id and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) then security.scheduler_actor_display(p.owner_user_id) else 'Former user' end,'')) like '%'||v_query||'%'
            or (p.owner_user_id is not null and not exists(select 1 from auth.users au where au.id=p.owner_user_id and au.deleted_at is null and (au.banned_until is null or au.banned_until <= now())) and lower('Former user — '||coalesce(p.owner_display_snapshot,security.scheduler_actor_display(p.owner_user_id),'unknown')) like '%'||v_query||'%')
            or lower(coalesce(p.freshness_class,'')) like '%'||v_query||'%'
            or lower(coalesce(p.cadence_interval::text,'')) like '%'||v_query||'%'
            or lower('layer '||p.layer::text) like '%'||v_query||'%'
            or (v_query='enabled' and p.enabled)
            or (v_query='disabled' and not p.enabled))
        order by p.next_due_at nulls last,p.id limit v_limit offset v_offset
      ) x
    ),'[]'::jsonb)
  );
end
$$;


ALTER FUNCTION "security"."scheduler_policies_list_v1_browser_bridge"("p_limit" integer, "p_offset" integer, "p_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scheduler_policy_edit_v1_browser_bridge"("p_policy_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_cadence_days" integer, "p_next_due_at" timestamp with time zone, "p_enabled" boolean, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_policy pipeline.refresh_policies%rowtype;
  v_before jsonb;
begin
  if v_actor is null or security.current_role_rank() < 4 then raise exception 'pipeline operator role required' using errcode='42501'; end if;
  if length(trim(coalesce(p_reason,''))) < 5 then raise exception 'governance reason required' using errcode='22023'; end if;
  if p_expected_updated_at is null then raise exception 'expected policy version required' using errcode='22023'; end if;
  if p_cadence_days is null or p_cadence_days < 1 or p_cadence_days > 3650 then raise exception 'cadence days must be 1..3650' using errcode='22023'; end if;
  if p_next_due_at is null then raise exception 'next run required' using errcode='22023'; end if;
  select * into v_policy from pipeline.refresh_policies where id=p_policy_id for update;
  if not found then raise exception 'refresh policy not found' using errcode='22023'; end if;
  if v_policy.updated_at is distinct from p_expected_updated_at then raise exception 'schedule changed since it was opened; refresh and try again' using errcode='40001'; end if;
  if v_policy.layer not in (1,2,3) then raise exception 'only Layer 1..3 schedules are editable here' using errcode='22023'; end if;
  if v_policy.freshness_class='event-driven' then raise exception 'event-driven policy has no recurring schedule' using errcode='22023'; end if;
  if v_policy.source_id is null and v_policy.source_profile_id is null and v_policy.entity_id is null then raise exception 'bounded target required' using errcode='22023'; end if;
  v_before:=jsonb_build_object('cadence_interval',v_policy.cadence_interval::text,'next_due_at',v_policy.next_due_at,'enabled',v_policy.enabled,'updated_at',v_policy.updated_at,'change_control_ref',v_policy.change_control_ref);
  update pipeline.refresh_policies set cadence_interval=make_interval(days=>p_cadence_days),next_due_at=p_next_due_at,enabled=p_enabled,change_control_ref='CF-CHG-20260910-092',updated_at=now() where id=v_policy.id;
  insert into pipeline.refresh_policy_action_events(policy_id,action,reason,actor_id,change_control_ref,before_state,after_state,outcome)
  values(v_policy.id,'edit_schedule',trim(p_reason),v_actor,'CF-CHG-20260910-092',v_before,jsonb_build_object('cadence_days',p_cadence_days,'next_due_at',p_next_due_at,'enabled',p_enabled,'change_control_ref','CF-CHG-20260910-092'),'applied');
  return jsonb_build_object('ok',true,'policy_id',v_policy.id,'action','edit_schedule');
end
$$;


ALTER FUNCTION "security"."scheduler_policy_edit_v1_browser_bridge"("p_policy_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_cadence_days" integer, "p_next_due_at" timestamp with time zone, "p_enabled" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scheduler_policy_run_now_v1_browser_bridge"("p_policy_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_actor uuid := auth.uid(); v_policy pipeline.refresh_policies%rowtype; v_request_id uuid; v_existing boolean := false;
begin
  if v_actor is null or security.current_role_rank() < 4 then raise exception 'pipeline operator role required' using errcode='42501'; end if;
  if length(trim(coalesce(p_reason,''))) < 5 then raise exception 'governance reason required' using errcode='22023'; end if;
  select * into v_policy from pipeline.refresh_policies where id=p_policy_id for update;
  if not found then raise exception 'refresh policy not found' using errcode='22023'; end if;
  if not v_policy.enabled then raise exception 'enable this schedule before running it on demand' using errcode='22023'; end if;
  if v_policy.layer not in (1,2) then raise exception 'Layer 3 on-demand execution requires Evidence/profile-specific control from the Layer 3 workspace' using errcode='22023'; end if;
  if v_policy.source_id is null and v_policy.source_profile_id is null and v_policy.entity_id is null then raise exception 'bounded target required' using errcode='22023'; end if;
  select r.id into v_request_id from pipeline.refresh_requests r where r.status in ('queued','running') and r.requested_layer=v_policy.layer and r.country_code is not distinct from v_policy.country_code and r.source_id is not distinct from v_policy.source_id and r.source_profile_id is not distinct from v_policy.source_profile_id and r.entity_type is not distinct from v_policy.entity_type and r.entity_id is not distinct from v_policy.entity_id order by r.created_at desc limit 1;
  if v_request_id is null then
    insert into pipeline.refresh_requests(requested_layer,country_code,source_id,source_profile_id,entity_type,entity_id,reason,trigger_type,status,requested_by,change_control_ref)
    values(v_policy.layer,v_policy.country_code,v_policy.source_id,v_policy.source_profile_id,v_policy.entity_type,v_policy.entity_id,trim(p_reason),'manual_governed','queued',v_actor,'CF-CHG-20260910-092') returning id into v_request_id;
  else v_existing:=true; end if;
  insert into pipeline.refresh_policy_action_events(policy_id,action,reason,actor_id,change_control_ref,before_state,after_state,refresh_request_id,outcome)
  values(v_policy.id,'run_on_demand',trim(p_reason),v_actor,'CF-CHG-20260910-092',jsonb_build_object('cadence_interval',v_policy.cadence_interval::text,'next_due_at',v_policy.next_due_at,'enabled',v_policy.enabled),jsonb_build_object('policy_unchanged',true,'request_id',v_request_id),v_request_id,case when v_existing then 'existing_active' else 'queued' end);
  return jsonb_build_object('ok',true,'policy_id',v_policy.id,'request_id',v_request_id,'existing_active',v_existing,'action','run_on_demand');
end $$;


ALTER FUNCTION "security"."scheduler_policy_run_now_v1_browser_bridge"("p_policy_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_admission_provider_ok_v1"("p_provider_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select security.scholarship_university(p_provider_id)
      or (security.scholarship_flag_v1('scholarship.non_university_admission', false)
          -- CF-247 scholarships beyond universities (decision 3 Nov 2026 08:44 §4): the pilot providers only while scholarship.pilot_only is on
          and security.scholarship_pilot_scope_v1(p_provider_id)
          and exists (select 1 from catalogue.providers p join ref.provider_types t on t.id = p.provider_type_id join ref.countries k on k.id = p.country_id
                       where p.id = p_provider_id and p.lifecycle_status = 'active' and k.scholarship_ingestion_enabled
                         and t.status = 'active' and p.provider_type_basis is not null
                         and t.code in (select jsonb_array_elements_text(coalesce(security.toolset_setting('pipeline', 'scholarship.non_university_types'), '[]'::jsonb)))
                         and nullif(btrim(coalesce(p.website, '')), '') is not null and not security.third_party_host_v1(p.website)))
$$;


ALTER FUNCTION "security"."scholarship_admission_provider_ok_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_admission_withdraw_v1"("p_scholarship_id" "uuid", "p_reason" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline', 'search'
    AS $$
declare s record; v_courses uuid[];
begin
  select * into s from scholarship.scholarships where id=p_scholarship_id for update;
  if s.id is null or s.lifecycle_status<>'active' then return jsonb_build_object('withdrawn',false); end if;
  if s.publication_status='published' then return jsonb_build_object('withdrawn',false,'reason','published; left for the publication review'); end if;
  if not exists (select 1 from pipeline.scholarship_pages where scholarship_id=s.id and url_source='admitted') then return jsonb_build_object('withdrawn',false,'reason','not admitted from a provider page'); end if;
  select coalesce(array_agg(course_id),'{}') into v_courses from scholarship.course_mappings where scholarship_id=s.id and mapping_basis='sweep_level_field_scope';
  delete from scholarship.course_mappings where scholarship_id=s.id and mapping_basis='sweep_level_field_scope';
  update scholarship.scholarships set lifecycle_status='inactive', updated_at=now() where id=s.id;
  update pipeline.scholarship_page_candidates set admit_status='withdrawn', admit_reasons=array(select jsonb_array_elements_text(coalesce(p_reason->'reasons','[]'))) where admitted_scholarship_id=s.id;
  insert into pipeline.scholarship_sweep_changes(scholarship_id,field,before_value,after_value) values (s.id,'admission_withdrawn',jsonb_build_object('lifecycle_status','active'),p_reason);
  insert into pipeline.scholarship_admission_log(scholarship_id,provider_id,action,detail) values (s.id,s.provider_id,'withdrawn',p_reason);
  -- R5 (14 Nov 2026): inside svc_scholarship_ai_record (flag cf247.defer_search_refresh) the courses are queued, not refreshed in the call
  if cardinality(v_courses)>0 then
    if coalesce(current_setting('cf247.defer_search_refresh', true), '') = 'on' then
      perform search.course_refresh_request_v1(v_courses, 'scholarship_admission_withdraw_v1');
    else
      perform search.refresh_course_enrichment_scoped_v1(v_courses,true);
    end if;
  end if;
  return jsonb_build_object('withdrawn',true);
end $$;


ALTER FUNCTION "security"."scholarship_admission_withdraw_v1"("p_scholarship_id" "uuid", "p_reason" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_admit_from_provider_page_v1"("p_candidate_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline', 'catalogue', 'pim', 'security'
    AS $_$
declare c record; d record; f jsonb; v_name text; v_url text; v_norm text; v_key text; v_id uuid; v_src uuid; v_ev uuid; v_dup uuid; v_dup_sa boolean; v_apply jsonb; r jsonb;
begin
  select * into c from pipeline.scholarship_page_candidates where id=p_candidate_id for update;
  if c.id is null then return jsonb_build_object('admitted',false,'reason','no candidate'); end if;
  if c.admitted_scholarship_id is not null or c.matched_scholarship_id is not null then return jsonb_build_object('admitted',false,'reason','already handled'); end if;
  select * into d from pipeline.scholarship_discovery_providers where provider_id=c.provider_id;
  f:=c.facts; v_name:=btrim(f->'admission'->>'name'); v_url:=coalesce(c.final_url,c.url); v_norm:=security.scholarship_url_norm(v_url);
  -- CF-247 scholarship recovery F5: one award of an umbrella page ("<page>#award-<code>") is its own record, keyed by its section address
  if c.url_norm ~ '#award-[a-z]{4}[0-9]{4}$' then v_norm:=c.url_norm; end if;
  -- the rules, checked again here from the recorded page facts
  if c.read_status is distinct from 'read' or c.storage_path is null then r:=jsonb_build_object('admitted',false,'reason','page not read');
  elsif not security.scholarship_admission_provider_ok_v1(c.provider_id) /* CF-247 scholarship recovery P1 (proposed, off): universities, as before */ then r:=jsonb_build_object('admitted',false,'reason','not a university provider in a scholarship country');
  -- CF-247 scholarships beyond universities (decision 3 Nov 2026 08:44 §4, official award source): a college's page naming another body's award
  elsif not security.scholarship_university(c.provider_id) and security.scholarship_external_award_v1(v_name) then r:=jsonb_build_object('admitted',false,'reason','award of another body');
  elsif not security.url_on_provider_sites(v_url, c.provider_id) or security.reference_url_has_use(v_url, 'scholarship_placeholder') then r:=jsonb_build_object('admitted',false,'reason','not on the provider site');
  elsif coalesce(v_name,'')='' or length(v_name)<8 or v_name !~* '(scholarship|bursary|award|grant|fee (remission|reduction|waiver|discount)|tuition (discount|reduction|waiver))' then r:=jsonb_build_object('admitted',false,'reason','no named scholarship title');
  elsif coalesce((f->'admission'->>'detail_page')::boolean,false) is not true then r:=jsonb_build_object('admitted',false,'reason','not a single scholarship page');
  elsif coalesce((f->'admission'->>'international_explicit')::boolean,false) is not true or coalesce((f->>'international')::boolean,false) is not true then r:=jsonb_build_object('admitted',false,'reason','not explicitly open to international students');
  elsif coalesce((f->'admission'->>'offered')::boolean,false) is not true then r:=jsonb_build_object('admitted',false,'reason','not currently offered');
  elsif coalesce((f->'admission'->>'admit')::boolean,false) is not true then r:=jsonb_build_object('admitted',false,'reason','page rules not met');
  end if;
  if r is not null then
    update pipeline.scholarship_page_candidates set admit_status='rejected', admit_reasons=array[r->>'reason'] where id=c.id;
    insert into pipeline.scholarship_admission_log(candidate_id,provider_id,action,detail) values (c.id,c.provider_id,'rejected',r);
    return r;
  end if;
  -- already held: same page, or same name at this provider
  select s.id, security.reference_url_has_use(s.source_url, 'scholarship_placeholder') into v_dup, v_dup_sa from scholarship.scholarships s
   where s.provider_id=c.provider_id and s.lifecycle_status='active'
     and (security.scholarship_url_norm(s.source_url)=v_norm or scholarship.normalise_title(s.name)=scholarship.normalise_title(v_name)
          or exists (select 1 from scholarship.identifiers i where i.scholarship_id=s.id and i.scheme='first_party_detail_url' and security.scholarship_url_norm(i.identifier_value) in (v_norm, c.url_norm))
          or exists (select 1 from pipeline.scholarship_pages sp where sp.scholarship_id=s.id and security.scholarship_url_norm(sp.url) in (v_norm, c.url_norm)))
   order by (security.reference_url_has_use(s.source_url, 'scholarship_placeholder')) limit 1;
  if v_dup is not null then
    if v_dup_sa and not exists (select 1 from pipeline.scholarship_pages where scholarship_id=v_dup) then
      -- a held Study Australia-only scholarship named by this page's heading: step 1 match, read and confirmed by the reader
      r:=security.scholarship_page_match_v1(v_dup, c.url, 'page_heading', c.id);
      update pipeline.scholarship_page_candidates set admit_status='matched_held' where id=c.id;
      insert into pipeline.scholarship_admission_log(candidate_id,scholarship_id,provider_id,action,detail) values (c.id,v_dup,c.provider_id,'matched_held',r);
      return jsonb_build_object('admitted',false,'reason','held scholarship matched','scholarship_id',v_dup,'match',r);
    end if;
    update pipeline.scholarship_page_candidates set admit_status='duplicate', admit_reasons=array['already held'] where id=c.id;
    insert into pipeline.scholarship_admission_log(candidate_id,scholarship_id,provider_id,action,detail) values (c.id,v_dup,c.provider_id,'duplicate',jsonb_build_object('name',v_name));
    return jsonb_build_object('admitted',false,'reason','already held','scholarship_id',v_dup);
  end if;

  v_key:='scholarship:'||coalesce((select k.iso_alpha2 from catalogue.providers pp join ref.countries k on k.id=pp.country_id where pp.id=c.provider_id),'AU')||':first-party:'||replace(c.provider_id::text,'-','')||':'||md5(v_norm);
  v_id:=scholarship.deterministic_uuid(v_key);
  if exists (select 1 from scholarship.scholarships where id=v_id) then
    update pipeline.scholarship_page_candidates set admit_status='duplicate', admit_reasons=array['same stable key'] where id=c.id;
    return jsonb_build_object('admitted',false,'reason','same stable key','scholarship_id',v_id);
  end if;
  v_src:=security.coverage_sweep_source(c.provider_id);
  insert into pim.entity_registry(id,entity_type,stable_key,lifecycle_status) values (v_id,'scholarship',v_key,'active') on conflict (stable_key) do update set lifecycle_status='active', updated_at=now();
  insert into pipeline.evidence_artifacts(entity_id,source_id,evidence_type,source_url,storage_path,content_hash,mime_type,metadata,capture_version,evidence_group_key)
  values (v_id, v_src, 'scholarship_page', v_url, c.storage_path, c.content_hash, 'application/gzip',
          jsonb_build_object('worker','coverage-sweep scholarship_discover','decision','CF-247 scholarship discovery (Decision 139 sweep)','candidate_id',c.id,'extractor',f->>'extractor'), 1, 'scholarship:'||v_id)
  returning id into v_ev;
  insert into scholarship.scholarships(id,stable_key,provider_id,name,scholarship_type,audience,source_url,lifecycle_status,publication_status,source_id,evidence_id,confidence,award_value_type,updated_at)
  values (v_id,v_key,c.provider_id,left(v_name,300),'provider_scholarship','international',v_url,'active','unpublished',v_src,v_ev,0.9,'text_only',now());
  insert into scholarship.identifiers(scholarship_id,scheme,identifier_value,source_id,evidence_id,is_primary,status)
  values (v_id,'first_party_detail_url',v_url,v_src,v_ev,true,'active') on conflict do nothing;
  insert into pipeline.scholarship_acquisition_trace(provider_id,observed_title,first_party_detail_url,scholarship_id,verification_evidence_id,stage,verification_status,observed_at,verified_at,updated_at,metadata)
  values (c.provider_id,left(v_name,300),v_url,v_id,v_ev,'canonical_unpublished','verified_first_party',c.found_at,now(),now(),
          jsonb_build_object('admission','security.scholarship_admit_from_provider_page_v1','candidate_id',c.id,'candidate_source',c.source,'rule','single named scholarship detail page on the provider site, explicitly open to international students, currently offered'));
  insert into pipeline.scholarship_pages(scholarship_id,url,url_source,candidate_id,final_url,read_status,http_status,fetched_via,read_at,next_read_at,attempts,evidence_id,facts,name_check)
  values (v_id,v_url,'admitted',c.id,c.final_url,'read',c.http_status,c.fetched_via,c.read_at,now()+make_interval(days => security.pipeline_num_v1('reread.scholarship_page_days', 90)::int),0,v_ev,f,jsonb_build_object('ok',true,'basis','admitted_from_page_title','heading',v_name));
  update pipeline.scholarship_page_candidates set admit_status='admitted', admitted_scholarship_id=v_id, admitted_at=now() where id=c.id;
  insert into pipeline.scholarship_sweep_changes(scholarship_id,field,before_value,after_value,evidence_id) values (v_id,'admitted',null,jsonb_build_object('name',v_name,'url',v_url,'candidate_id',c.id),v_ev);
  v_apply:=security.scholarship_sweep_apply_v1(v_id);
  insert into pipeline.scholarship_admission_log(candidate_id,scholarship_id,provider_id,action,detail) values (c.id,v_id,c.provider_id,'admitted',jsonb_build_object('name',v_name,'url',v_url,'apply',v_apply));
  return jsonb_build_object('admitted',true,'scholarship_id',v_id,'apply',v_apply);
end $_$;


ALTER FUNCTION "security"."scholarship_admit_from_provider_page_v1"("p_candidate_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_ai_active_v1"() RETURNS TABLE("model_code" "text", "model_identifier" "text", "prompt_version" integer, "ai_admission" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- 13 Nov 2026: the first allowed model of the route scholarship_extraction reads first (it was the first of the old chain)
  select m.x->>'code', m.x->>'model_identifier', (select p.version from pipeline.scholarship_ai_prompts p where p.active order by p.version desc limit 1), s.ai_admission
    from pipeline.scholarship_ai_extract_settings s
    left join lateral (select t.x from jsonb_array_elements(security.ai_route_v1('scholarship_extraction')->'models') with ordinality t(x, o) order by t.o limit 1) m on true
   where s.id = 1
$$;


ALTER FUNCTION "security"."scholarship_ai_active_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_ai_apply_v1"("p_extraction" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare e pipeline.scholarship_ai_extractions%rowtype; v_facts jsonb; v_rule jsonb; r jsonb; v_sid uuid; v_aud text;
begin
  select * into e from pipeline.scholarship_ai_extractions where id = p_extraction;
  if e.id is null or e.error is not null or e.answer is null then return jsonb_build_object('applied', false, 'reason', 'no answer'); end if;
  v_aud := case e.answer->>'audience' when 'international' then 'international' when 'both' then 'international_and_domestic' when 'domestic' then 'domestic' else null end;
  if e.candidate_id is not null then
    select c.facts into v_rule from pipeline.scholarship_page_candidates c where c.id = e.candidate_id;
    v_facts := security.scholarship_ai_facts_v1(e.answer, e.checks, coalesce(v_rule->'rules', v_rule), e.model_code || ' / instructions v' || e.prompt_version) || jsonb_build_object('rules', coalesce(v_rule->'rules', v_rule));
    update pipeline.scholarship_page_candidates set facts = v_facts, admit_status = null, admit_reasons = null, read_status = 'read' where id = e.candidate_id and admitted_scholarship_id is null;
    if coalesce((v_facts->'admission'->>'admit')::boolean, false) then
      r := security.scholarship_admit_from_provider_page_v1(e.candidate_id);
      v_sid := (r->>'scholarship_id')::uuid;
      if coalesce((r->>'admitted')::boolean, false) and v_aud is not null then update scholarship.scholarships set audience = v_aud, updated_at = now() where id = v_sid; end if;
    else
      update pipeline.scholarship_page_candidates set admit_status = 'rejected', admit_reasons = array(select jsonb_array_elements_text(v_facts->'admission'->'reasons')) where id = e.candidate_id;
      insert into pipeline.scholarship_admission_log(candidate_id, provider_id, action, detail) values (e.candidate_id, e.provider_id, 'rejected', jsonb_build_object('by', 'ai', 'extraction', e.id, 'reasons', v_facts->'admission'->'reasons'));
      r := jsonb_build_object('admitted', false, 'reasons', v_facts->'admission'->'reasons');
    end if;
  elsif e.scholarship_id is not null then
    select sp.facts into v_rule from pipeline.scholarship_pages sp where sp.scholarship_id = e.scholarship_id;
    v_facts := security.scholarship_ai_facts_v1(e.answer, e.checks, coalesce(v_rule->'rules', v_rule), e.model_code || ' / instructions v' || e.prompt_version) || jsonb_build_object('rules', coalesce(v_rule->'rules', v_rule));
    update pipeline.scholarship_pages set facts = v_facts, read_status = 'read', evidence_id = coalesce(e.evidence_id, evidence_id) where scholarship_id = e.scholarship_id;
    if not coalesce((v_facts->'admission'->>'admit')::boolean, false) and exists (select 1 from pipeline.scholarship_pages where scholarship_id = e.scholarship_id and url_source = 'admitted') then
      r := security.scholarship_admission_withdraw_v1(e.scholarship_id, jsonb_build_object('reasons', v_facts->'admission'->'reasons', 'extractor', v_facts->>'extractor', 'by', 'ai'));
    else
      r := security.scholarship_sweep_apply_v1(e.scholarship_id);
      if v_aud is not null then update scholarship.scholarships set audience = v_aud, updated_at = now() where id = e.scholarship_id and audience is distinct from v_aud; end if;
      -- v2.15.250: an automatic hold is released when this answer passes every publish check; a hold a person made stays
      if exists (select 1 from pipeline.scholarship_publication_holds h where h.scholarship_id = e.scholarship_id and h.released_at is null and h.held_by = 'auto')
         and exists (select 1 from security.scholarship_publishability_for_v1(array[e.scholarship_id]) p where not exists (select 1 from unnest(p.missing) x where x ilike '%held%' is not true)) then
        update pipeline.scholarship_publication_holds set released_at = now(), release_note = 'AI re-read passes every publish check (v2.15.250)' where scholarship_id = e.scholarship_id;
        r := coalesce(r, '{}'::jsonb) || jsonb_build_object('auto_hold_released', true);
      end if;
    end if;
  end if;
  -- F-SCH redesign (12 Nov 2026): a version 3 answer also fills the scholarship's empty fields from its verified passages
  if coalesce(e.prompt_version, 0) >= 3 then r := coalesce(r, '{}'::jsonb) || jsonb_build_object('detail', security.scholarship_detail_apply_v1(e.id)); end if;
  update pipeline.scholarship_ai_extractions set applied = coalesce(r, '{}'::jsonb) || jsonb_build_object('at', now()) where id = e.id;
  return r;
end $$;


ALTER FUNCTION "security"."scholarship_ai_apply_v1"("p_extraction" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_ai_backfill_tick_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a record; v_ids uuid[]; v_n int; v_per int;
begin
  select * into a from security.scholarship_ai_active_v1();
  if not coalesce(a.ai_admission, false) or a.model_code is null then return jsonb_build_object('skipped', 'AI admission is off'); end if;
  select backfill_providers_per_night into v_per from pipeline.scholarship_ai_extract_settings where id = 1;
  v_ids := array(select c.provider_id from pipeline.scholarship_page_candidates c
                  where c.admit_status = 'rejected' and c.source <> 'register'
                    and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = c.provider_id)  -- 22 Oct 2026 (Platform Admin 11:42): unpublished providers wait; publishing them again brings them back
                    and not exists (select 1 from pipeline.scholarship_ai_extractions e where e.candidate_id = c.id and e.model_code = a.model_code and e.prompt_version = a.prompt_version)
                  group by c.provider_id order by count(*) desc limit v_per);
  if cardinality(v_ids) = 0 then return jsonb_build_object('done', 'every university read'); end if;
  v_n := security.scholarship_ai_enqueue_v1('admit', v_ids, null, true);
  return jsonb_build_object('providers', cardinality(v_ids), 'pages', v_n);
end $$;


ALTER FUNCTION "security"."scholarship_ai_backfill_tick_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_ai_control_read_impl"("p_country_code" "text" DEFAULT 'AU'::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 20 Oct 2026 (D11): the old scholarship AI pipeline (settings, runs) is retired; scholarships are read on Models & services › AI
  select jsonb_build_object('country_code', upper(coalesce(nullif(p_country_code, ''), 'AU')), 'retired', true,
                            'note', 'The old scholarship AI pipeline is retired (20 Oct 2026). Scholarship extraction is on Models & services › AI.')
$$;


ALTER FUNCTION "security"."scholarship_ai_control_read_impl"("p_country_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_ai_enqueue_v1"("p_run_kind" "text", "p_provider_ids" "uuid"[], "p_job" "uuid" DEFAULT NULL::"uuid", "p_known" boolean DEFAULT true) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a record; v_n int := 0; v_k int; v_gate boolean := security.pipeline_num_v1('scholarship.enqueue_directory_gate_on', 1) >= 1;
begin
  select * into a from security.scholarship_ai_active_v1();
  if a.model_code is null then return 0; end if;
  -- CF-247 4 Nov 2026 (IQ-00132): a candidate on a directory site is never queued (the worker refuses it); it is marked refused once, outcome not needed
  if v_gate then
    with d as (update pipeline.scholarship_page_candidates c set admit_status = 'skipped', admit_reasons = array['directory_site']
                where c.provider_id = any (p_provider_ids) and c.source <> 'register' and c.admitted_scholarship_id is null and c.matched_scholarship_id is null
                  and coalesce(c.admit_status, '') not in ('skipped', 'duplicate', 'admitted', 'matched_held')
                  and security.third_party_host_v1(coalesce(c.final_url, c.url))
                  and not exists (select 1 from pipeline.scholarship_ai_reviews r where r.candidate_id = c.id and r.status = 'pending')
               returning c.id, c.provider_id)
    insert into pipeline.scholarship_admission_log(candidate_id, provider_id, action, detail)
    select d.id, d.provider_id, 'skipped', jsonb_build_object('by', 'enqueue', 'reason', 'directory_site', 'outcome', 'not_needed', 'issue', 'IQ-00132') from d;
  end if;
  insert into pipeline.scholarship_ai_queue(model_code, prompt_version, run_kind, job_id, candidate_id, provider_id, url)
  select a.model_code, a.prompt_version, p_run_kind, p_job, c.id, c.provider_id, coalesce(c.final_url, c.url)
    from pipeline.scholarship_page_candidates c
   where c.provider_id = any (p_provider_ids) and c.source <> 'register' and c.admitted_scholarship_id is null and c.matched_scholarship_id is null
     and coalesce(c.admit_status, '') not in ('skipped', 'duplicate', 'admitted', 'matched_held')
     and not (v_gate and security.third_party_host_v1(coalesce(c.final_url, c.url)))
     and not exists (select 1 from pipeline.scholarship_ai_extractions e where e.candidate_id = c.id and e.model_code = a.model_code and e.prompt_version = a.prompt_version and e.error is null)
     and not exists (select 1 from pipeline.scholarship_ai_queue q where q.candidate_id = c.id and q.state in ('queued', 'leased'));
  get diagnostics v_k = row_count; v_n := v_n + v_k;
  if p_known then
    insert into pipeline.scholarship_ai_queue(model_code, prompt_version, run_kind, job_id, scholarship_id, provider_id, url)
    select a.model_code, a.prompt_version, 'reread', p_job, s.id, s.provider_id, coalesce(sp.final_url, sp.url)
      from scholarship.scholarships s join pipeline.scholarship_pages sp on sp.scholarship_id = s.id
     where s.provider_id = any (p_provider_ids) and s.lifecycle_status = 'active'
       and not (v_gate and security.third_party_host_v1(coalesce(sp.final_url, sp.url)))  -- CF-247 4 Nov 2026 (IQ-00132)
       and not exists (select 1 from pipeline.scholarship_ai_extractions e where e.scholarship_id = s.id and e.model_code = a.model_code and e.prompt_version = a.prompt_version and e.error is null)
       and not exists (select 1 from pipeline.scholarship_ai_queue q where q.scholarship_id = s.id and q.state in ('queued', 'leased'));
    get diagnostics v_k = row_count; v_n := v_n + v_k;
  end if;
  perform security.scholarship_ai_fire_v1();
  return v_n;
end $$;


ALTER FUNCTION "security"."scholarship_ai_enqueue_v1"("p_run_kind" "text", "p_provider_ids" "uuid"[], "p_job" "uuid", "p_known" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_ai_facts_v1"("p_answer" "jsonb", "p_checks" "jsonb", "p_rule" "jsonb", "p_label" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare a jsonb := coalesce(p_answer, '{}'::jsonb); k jsonb := coalesce(p_checks, '{}'::jsonb); f jsonb := case when jsonb_typeof(p_rule) = 'object' then p_rule else '{}'::jsonb end - 'criteria';
        v jsonb := a->'value'; v_val jsonb; v_aud text := a->>'audience'; v_intl boolean; v_admit boolean; v_reasons text[] := '{}';
begin
  v_intl := v_aud in ('international', 'both') and coalesce((k->>'audience')::boolean, false);
  if not coalesce((a->>'is_scholarship')::boolean, false) then v_reasons := v_reasons || 'not_a_scholarship'::text; end if;
  if not coalesce((a->>'single_scholarship')::boolean, false) then v_reasons := v_reasons || 'listing_page'::text; end if;
  if not coalesce((k->>'name')::boolean, false) then v_reasons := v_reasons || 'no_named_title'::text; end if;
  if v_aud = 'domestic' and coalesce((k->>'audience')::boolean, false) then v_reasons := v_reasons || 'domestic_only'::text;
  elsif not v_intl then v_reasons := v_reasons || 'international_not_stated'::text; end if;
  if a->>'offered' = 'no' and coalesce((k->>'offered')::boolean, false) then v_reasons := v_reasons || 'not_offered'::text; end if;
  v_admit := cardinality(v_reasons) = 0;
  if coalesce((k->>'value')::boolean, false) then
    v_val := case v->>'kind'
      when 'percentage' then jsonb_build_object('type', 'percentage', 'percentage', (v->>'percentage')::numeric, 'applies_to', 'tuition_fee', 'context', v->>'quote')
      when 'full_tuition' then jsonb_build_object('type', 'percentage', 'percentage', 100, 'applies_to', 'tuition_fee', 'context', v->>'quote')
      when 'fixed_amount' then jsonb_build_object('type', 'fixed_amount', 'amount', (v->>'amount')::numeric, 'currency', coalesce(nullif(v->>'currency', ''), 'AUD'), 'context', v->>'quote')
      when 'tiers' then jsonb_build_object('type', 'ambiguous', 'amounts', coalesce((select jsonb_agg((t->>'amount')::numeric) from jsonb_array_elements(coalesce(v->'tiers', '[]'::jsonb)) t where t->>'amount' is not null), '[]'::jsonb),
                                           'percentages', coalesce((select jsonb_agg((t->>'percentage')::numeric) from jsonb_array_elements(coalesce(v->'tiers', '[]'::jsonb)) t where t->>'percentage' is not null), '[]'::jsonb), 'context', v->>'quote')
      else null end;
  end if;
  f := f || jsonb_build_object(
    'extracted_by', 'ai', 'extractor', p_label, 'ai', jsonb_build_object('answer', a, 'checks', k),
    'admission', jsonb_build_object('name', a->>'name', 'admit', v_admit, 'reasons', to_jsonb(v_reasons), 'detail_page', coalesce((a->>'single_scholarship')::boolean, false),
                                    'international_explicit', v_intl, 'offered', coalesce(a->>'offered', 'not_stated') <> 'no', 'by', 'ai'),
    'international', v_intl, 'value', v_val,
    'eligibility_excerpt', nullif(a->>'audience_quote', ''),
    'levels', coalesce(a->'levels', '[]'::jsonb), 'levels_text', nullif(a->>'levels_quote', ''), 'levels_from', 'ai',
    'named_courses', jsonb_build_object('codes', '[]'::jsonb, 'titles', coalesce((select jsonb_agg(jsonb_build_object('title', x, 'text', 'Named on the page (AI, quote checked)')) from jsonb_array_elements_text(coalesce(k->'courses_found', '[]'::jsonb)) x), '[]'::jsonb), 'excluded', '[]'::jsonb),
    'dates', jsonb_build_object('open', case when a->>'open_date' ~ '^\d{4}-\d{2}-\d{2}$' and coalesce((k->>'dates')::boolean, false) then jsonb_build_object('date', a->>'open_date', 'text', a->>'dates_quote', 'precision', 'day') end,
                                'close', case when a->>'close_date' ~ '^\d{4}-\d{2}-\d{2}$' and coalesce((k->>'dates')::boolean, false) then jsonb_build_object('date', a->>'close_date', 'text', a->>'dates_quote', 'precision', 'day') end),
    'criteria', coalesce((select jsonb_agg(c) from jsonb_array_elements(coalesce(p_rule->'criteria', '[]'::jsonb)) c where c->>'type' <> 'student_type'), '[]'::jsonb)
                || case when v_intl then jsonb_build_array(jsonb_build_object('type', 'student_type', 'operator', 'in', 'value_codes', case when v_aud = 'both' then jsonb_build_array('international', 'domestic') else jsonb_build_array('international') end, 'text', a->>'audience_quote', 'by', 'ai'))
                        when v_aud = 'domestic' then jsonb_build_array(jsonb_build_object('type', 'student_type', 'operator', 'in', 'value_codes', jsonb_build_array('domestic'), 'text', a->>'audience_quote', 'by', 'ai'))
                        else '[]'::jsonb end);
  return f;
end $_$;


ALTER FUNCTION "security"."scholarship_ai_facts_v1"("p_answer" "jsonb", "p_checks" "jsonb", "p_rule" "jsonb", "p_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_ai_fire_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_open int; v_max int; v_due int; v_sent int := 0; v_block timestamptz; v_okat timestamptz;
begin
  -- v2.15.258: in Stop at limits, not past the daily guard or below the credit floor
  if not security.ai_use_allowed_v1('scholarship_ai') then return 0; end if;
  select calls_at_once into v_max from pipeline.scholarship_ai_extract_settings where id = 1;
  -- F-SCH.15 (13 Nov 2026): a vendor-side block (OpenRouter key limit HTTP 403, no credit HTTP 402) holds the lane to one probe call; the first
  -- success after it re-queues the items the block closed
  select max(e.at) into v_block from pipeline.scholarship_ai_extractions e
   where e.at > now() - make_interval(hours => security.pipeline_num_v1('scholarship.vendor_block_lookback_hours', 24)::int)
     and (e.error like 'HTTP 403%limit%' or e.error like 'HTTP 402%');
  if v_block is not null then
    select max(e.at) into v_okat from pipeline.scholarship_ai_extractions e where e.at > v_block and e.error is null;
    if v_okat is null then v_max := least(coalesce(v_max, 3), 1);  -- fixed: one probe call while the vendor refuses
    else perform security.scholarship_ai_vendor_requeue_v1(v_block - make_interval(hours => security.pipeline_num_v1('scholarship.vendor_block_lookback_hours', 24)::int)); end if;
  end if;
  select count(*) into v_due from pipeline.scholarship_ai_queue q where (q.state = 'queued' and q.next_try_at <= now()) or (q.state = 'leased' and q.leased_until < now());
  -- F-SCH redesign (12 Nov 2026): when nothing else is due, existing records are filled from their stored official page
  if v_due = 0 then
    v_due := security.scholarship_detail_backfill_v1(security.pipeline_num_v1('batch.sch_detail_backfill', 40)::int);
    if v_due = 0 then return 0; end if;
  end if;
  select count(*) into v_open from pipeline.edge_request_log l where l.function_name = 'coverage-sweep' and l.mode = 'scholarship_ai' and l.created_at > now() - interval '3 minutes'
     and not exists (select 1 from net._http_response r where r.id = l.request_id);
  while v_open + v_sent < coalesce(v_max, 3) and v_sent * 8 < v_due loop
    perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'scholarship_ai'));
    v_sent := v_sent + 1;
  end loop;
  return v_sent;
end $$;


ALTER FUNCTION "security"."scholarship_ai_fire_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_ai_has_copy_v1"("p_queue_id" bigint) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 lanes (3 Nov 2026): the scholarship AI item has a stored copy the worker reads without Firecrawl (the same sources, in the same
  -- order, as public.svc_scholarship_ai_next gives the worker)
  select exists (select 1 from pipeline.scholarship_ai_queue q
                  where q.id = p_queue_id and not q.fresh_read  -- CF-247 4 Nov 2026: an approved fresh read never counts a stored copy
                    and (q.storage_path is not null
                         or exists (select 1 from pipeline.scholarship_page_candidates c where c.id = q.candidate_id and c.storage_path is not null)
                         or exists (select 1 from pipeline.scholarship_pages sp join pipeline.evidence_artifacts e on e.id = sp.evidence_id where sp.scholarship_id = q.scholarship_id and e.storage_path is not null)
                         or exists (select 1 from scholarship.scholarships s join pipeline.evidence_artifacts e on e.id = s.evidence_id where s.id = q.scholarship_id and e.storage_path is not null)
                         or exists (select 1 from pipeline.scholarship_ai_extractions x where x.url = q.url and x.storage_path is not null and x.error is null
                                       and x.at > now() - make_interval(hours => security.pipeline_num_v1('waste.page_reuse_hours', 24)::int))))
$$;


ALTER FUNCTION "security"."scholarship_ai_has_copy_v1"("p_queue_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_ai_next_model_v1"("p_code" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- 13 Nov 2026: the next allowed model after p_code in the route's cascade; none (a person decides) after the last, or when p_code is not in it
  with c as (select t.x->>'code' code, t.o from jsonb_array_elements(security.ai_route_v1('scholarship_extraction')->'models') with ordinality t(x, o))
  select n.code from c n where n.o > (select c.o from c where c.code = p_code) order by n.o limit 1
$$;


ALTER FUNCTION "security"."scholarship_ai_next_model_v1"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_ai_reroute_parked_v1"("p_job" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a record; v_n int; v_s int;
begin
  select * into a from security.scholarship_ai_active_v1();
  if a.model_code is null then raise exception 'set the model chain first'; end if;
  insert into pipeline.scholarship_ai_queue(model_code, prompt_version, run_kind, job_id, scholarship_id, provider_id, url)
  select a.model_code, a.prompt_version, 'reread', p_job, s.id, s.provider_id, coalesce(sp.final_url, sp.url)
    from scholarship.scholarships s join pipeline.scholarship_pages sp on sp.scholarship_id = s.id
   where s.lifecycle_status = 'active'
     and (s.publication_status is distinct from 'published' or exists (select 1 from pipeline.scholarship_publication_holds h where h.scholarship_id = s.id and h.released_at is null))
     and not exists (select 1 from pipeline.scholarship_ai_queue q where q.scholarship_id = s.id and q.state in ('queued', 'leased'));
  get diagnostics v_n = row_count;
  with x as (
    update pipeline.layer4_review_items r set status = 'superseded', decided_at = now(),
           change_control_ref = coalesce(r.change_control_ref || '; ', '') || 'CF-247 v2.15.250: rerouted to the scholarship AI reader'
     where r.status = 'pending' and r.entity_type = 'scholarship' returning r.id, r.entity_id, r.field_code)
  insert into pipeline.layer4_reroutes(item_id, entity_type, entity_id, field_code, route, note) select x.id, 'scholarship', x.entity_id, x.field_code, 'scholarship_ai', 'parked item' from x;
  get diagnostics v_s = row_count;
  perform security.scholarship_ai_fire_v1();
  return jsonb_build_object('queued', v_n, 'layer4_items', v_s);
end $$;


ALTER FUNCTION "security"."scholarship_ai_reroute_parked_v1"("p_job" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_ai_review_apply_v1"("p_review" bigint, "p_decision" "text", "p_extraction" bigint, "p_note" "text", "p_by" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v pipeline.scholarship_ai_reviews%rowtype; e pipeline.scholarship_ai_extractions%rowtype; v_ans jsonb; v_chk jsonb; v_id bigint; r jsonb; v_pv int;
begin
  select * into v from pipeline.scholarship_ai_reviews where id = p_review for update;
  if v.id is null then raise exception 'no such review'; end if;
  if p_decision = 'admit' then
    select * into e from pipeline.scholarship_ai_extractions where id = coalesce(p_extraction,
      (select x.id from pipeline.scholarship_ai_extractions x where x.id = any (v.extraction_ids) and x.answer is not null order by coalesce((x.answer->>'is_scholarship')::boolean, false) desc, x.at desc limit 1));
    if e.id is null or e.answer is null then raise exception 'no model answer to admit; read the page again first'; end if;
    v_ans := e.answer || jsonb_build_object('is_scholarship', true, 'single_scholarship', true,
               'audience', case when e.answer->>'audience' in ('international', 'both') then e.answer->>'audience' else 'international' end,
               'audience_quote', case when e.answer->>'audience' in ('international', 'both') then e.answer->>'audience_quote' else 'Confirmed by a person in Layer 4' end,
               'offered', 'yes', 'name', coalesce(nullif(e.answer->>'name', ''), 'Scholarship'));
    v_chk := coalesce(e.checks, '{}'::jsonb) || jsonb_build_object('name', true, 'audience', true, 'offered', true, 'value', coalesce(e.answer->'value'->>'kind', 'not_stated') not in ('not_stated', 'non_monetary'),
               'levels', jsonb_array_length(coalesce(e.answer->'levels', '[]'::jsonb)) > 0, 'dates', coalesce((e.checks->>'dates')::boolean, false), 'by_person', true);
    select p.version into v_pv from pipeline.scholarship_ai_prompts p where p.active order by p.version desc limit 1;
    insert into pipeline.scholarship_ai_extractions(queue_id, model_code, model_identifier, prompt_version, run_kind, candidate_id, scholarship_id, provider_id, url, storage_path, content_hash, evidence_id, answer, checks, verdict, cost_usd, error)
    values (e.queue_id, 'person', 'person', coalesce(v_pv, e.prompt_version), 'review', v.candidate_id, v.scholarship_id, v.provider_id, v.url, coalesce(v.storage_path, e.storage_path), e.content_hash, e.evidence_id, v_ans, v_chk, 'scholarship', 0, null)
    returning id into v_id;
    r := security.scholarship_ai_apply_v1(v_id);
  elsif p_decision = 'refuse' then
    if v.candidate_id is not null then
      update pipeline.scholarship_page_candidates set admit_status = 'rejected', admit_reasons = array['refused_by_person'] where id = v.candidate_id and admitted_scholarship_id is null;
      insert into pipeline.scholarship_admission_log(candidate_id, provider_id, action, detail) values (v.candidate_id, v.provider_id, 'rejected', jsonb_build_object('by', 'person', 'review', v.id, 'note', p_note));
    end if;
    if v.scholarship_id is not null then
      insert into pipeline.scholarship_publication_holds(scholarship_id, reason, held_by, held_at)
      values (v.scholarship_id, 'Refused in Layer 4 › AI could not decide: ' || coalesce(p_note, ''), 'admin', now())
      on conflict (scholarship_id) do update set reason = excluded.reason, held_by = 'admin', held_at = now(), released_at = null, release_note = null;
    end if;
    r := jsonb_build_object('refused', true);
  else raise exception 'decide admit or refuse';
  end if;
  update pipeline.scholarship_ai_reviews set status = case when p_decision = 'admit' then 'admitted' else 'refused' end, decided_by = p_by, decided_at = now(), note = p_note,
         decision = jsonb_build_object('decision', p_decision, 'extraction', coalesce(v_id, p_extraction), 'applied', r) where id = v.id;
  return coalesce(r, '{}'::jsonb) || jsonb_build_object('review', v.id, 'decision', p_decision);
end $$;


ALTER FUNCTION "security"."scholarship_ai_review_apply_v1"("p_review" bigint, "p_decision" "text", "p_extraction" bigint, "p_note" "text", "p_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_ai_review_open_v1"("p_extraction" bigint, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare e pipeline.scholarship_ai_extractions%rowtype; v_root bigint; v_ids bigint[]; v_prev pipeline.scholarship_ai_reviews%rowtype; v_new bigint;
begin
  select * into e from pipeline.scholarship_ai_extractions where id = p_extraction;
  if e.id is null then return null; end if;
  select coalesce(q.root_id, q.id) into v_root from pipeline.scholarship_ai_queue q where q.id = e.queue_id;
  v_ids := array(select x.id from pipeline.scholarship_ai_extractions x join pipeline.scholarship_ai_queue q on q.id = x.queue_id where coalesce(q.root_id, q.id) = v_root order by x.id);
  select * into v_prev from pipeline.scholarship_ai_reviews r
   where r.status in ('admitted', 'refused') and r.url = e.url and coalesce(r.storage_path, '') = coalesce(e.storage_path, '') order by r.decided_at desc limit 1;
  if v_prev.id is not null then
    insert into pipeline.scholarship_ai_reviews(candidate_id, scholarship_id, provider_id, url, storage_path, extraction_ids, reason, status, decided_at, note, decision)
    values (e.candidate_id, e.scholarship_id, e.provider_id, e.url, e.storage_path, v_ids, p_reason, 'pending', null, null, null) returning id into v_new;
    return security.scholarship_ai_review_apply_v1(v_new, case v_prev.status when 'admitted' then 'admit' else 'refuse' end, null,
             'Same page copy as review ' || v_prev.id || ' (decided ' || to_char(v_prev.decided_at at time zone 'Australia/Melbourne', 'DD Mon YYYY') || '): ' || coalesce(v_prev.note, ''), v_prev.decided_by)
           || jsonb_build_object('exception_from', v_prev.id);
  end if;
  update pipeline.scholarship_ai_reviews set extraction_ids = v_ids, reason = p_reason, storage_path = e.storage_path
   where status = 'pending' and ((e.candidate_id is not null and candidate_id = e.candidate_id) or (e.scholarship_id is not null and scholarship_id = e.scholarship_id))
  returning id into v_new;
  if v_new is null then
    insert into pipeline.scholarship_ai_reviews(candidate_id, scholarship_id, provider_id, url, storage_path, extraction_ids, reason)
    values (e.candidate_id, e.scholarship_id, e.provider_id, e.url, e.storage_path, v_ids, p_reason) returning id into v_new;
  end if;
  return jsonb_build_object('review', v_new, 'reason', p_reason);
end $$;


ALTER FUNCTION "security"."scholarship_ai_review_open_v1"("p_extraction" bigint, "p_reason" "text") OWNER TO "postgres";


