 select coalesce(max(r.rank),0)::int from security.user_roles ur join security.roles r on r.code=ur.role_code
 where ur.user_id=auth.uid() and r.status='active' and (ur.expires_at is null or ur.expires_at>now())
$$;


ALTER FUNCTION "security"."scholarship_ai_role_rank"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_ai_scores_v1"("p_prompt" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with last as (
    select distinct on (e.model_code, e.sample_id) e.* from pipeline.scholarship_ai_extractions e
     where e.sample_id is not null and e.prompt_version = p_prompt order by e.model_code, e.sample_id, e.at desc),
  j as (
    select l.model_code, s.id, s.expected x, l.answer a, l.checks k, l.error, l.cost_usd, l.seconds,
           (coalesce((l.answer->>'is_scholarship')::boolean, false) and coalesce((l.answer->>'single_scholarship')::boolean, false)) a_sch,
           (coalesce((s.expected->>'is_scholarship')::boolean, false) and coalesce((s.expected->>'single')::boolean, true)) x_sch
      from last l join pipeline.scholarship_ai_sample s on s.id = l.sample_id and s.active)
  select coalesce(jsonb_object_agg(z.model_code, z.v), '{}'::jsonb) from (
    select j.model_code, jsonb_build_object(
      'pages', count(*), 'errors', count(*) filter (where j.error is not null),
      'scholarship_right', count(*) filter (where j.error is null and j.a_sch = j.x_sch),
      'international_checked', count(*) filter (where j.x ? 'international' and j.x_sch and j.error is null),
      'international_right', count(*) filter (where j.x ? 'international' and j.x_sch and j.error is null and ((j.a->>'audience') in ('international', 'both')) = (j.x->>'international')::boolean),
      'offered_checked', count(*) filter (where j.x ? 'offered' and j.x_sch and j.error is null),
      'offered_right', count(*) filter (where j.x ? 'offered' and j.x_sch and j.error is null and ((j.a->>'offered') <> 'no') = (j.x->>'offered')::boolean),
      'proven', count(*) filter (where j.error is null and j.a_sch and coalesce((j.k->>'name')::boolean, false)),
      'proofs_failed', count(*) filter (where j.error is null and j.a_sch and (not coalesce((j.k->>'name')::boolean, true) or not coalesce((j.k->>'audience')::boolean, true) or not coalesce((j.k->>'value')::boolean, true))),
      'cost_usd', round(coalesce(sum(j.cost_usd), 0), 4), 'cost_per_page', round(coalesce(avg(j.cost_usd), 0), 5), 'seconds_per_page', round(coalesce(avg(j.seconds), 0), 1)) v
      from j group by j.model_code) z
$$;


ALTER FUNCTION "security"."scholarship_ai_scores_v1"("p_prompt" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_ai_strip_unproven_v1"("p_answer" "jsonb", "p_checks" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select a3 from (
    select case when coalesce(a2->>'offered', 'not_stated') = 'no' and not coalesce((p_checks->>'offered')::boolean, false)
                then a2 || jsonb_build_object('offered', 'not_stated', 'offered_quote', '') else a2 end a3
      from (select case when coalesce(a1->'value'->>'kind', 'not_stated') not in ('not_stated', 'non_monetary') and not coalesce((p_checks->>'value')::boolean, false)
                        then jsonb_set(a1, '{value}', jsonb_build_object('kind', 'not_stated', 'percentage', null, 'amount', null, 'currency', null, 'tiers', '[]'::jsonb, 'quote', '')) else a1 end a2
              from (select case when coalesce(p_answer->>'audience', 'not_stated') <> 'not_stated' and not coalesce((p_checks->>'audience')::boolean, false)
                                then p_answer || jsonb_build_object('audience', 'not_stated', 'audience_quote', '') else p_answer end a1) x1) x2) x3
$$;


ALTER FUNCTION "security"."scholarship_ai_strip_unproven_v1"("p_answer" "jsonb", "p_checks" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_ai_strip_unproven_v1"("p_answer" "jsonb", "p_checks" "jsonb") IS 'F-SCH redesign 12 Nov 2026: an AI answer with its unproven stated facts (audience, value, ended) set to not_stated; unknown is not false.';



CREATE OR REPLACE FUNCTION "security"."scholarship_ai_unsettled_v1"("p_answer" "jsonb", "p_checks" "jsonb", "p_verdict" "text", "p_error" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p_error is not null then 'the model''s reply failed: ' || left(p_error, 120)
    when p_verdict = 'unproven' then 'the scholarship''s name is not on the page'
    when p_verdict = 'scholarship' and coalesce(p_answer->>'audience', 'not_stated') <> 'not_stated' and not coalesce((p_checks->>'audience')::boolean, false) then 'who it is for is not proven by a quote on the page'
    when p_verdict = 'scholarship' and coalesce(p_answer->'value'->>'kind', 'not_stated') not in ('not_stated', 'non_monetary') and not coalesce((p_checks->>'value')::boolean, false) then 'the value is not proven by a quote on the page'
    when p_verdict = 'scholarship' and p_answer->>'offered' = 'no' and not coalesce((p_checks->>'offered')::boolean, false) then '"no longer offered" is not proven by a quote on the page'
  end
$$;


ALTER FUNCTION "security"."scholarship_ai_unsettled_v1"("p_answer" "jsonb", "p_checks" "jsonb", "p_verdict" "text", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_ai_vendor_requeue_v1"("p_since" timestamp with time zone) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int;
begin
  with x as (
    select q.id from pipeline.scholarship_ai_queue q
     where q.state = 'done' and q.done_at >= p_since
       and exists (select 1 from pipeline.scholarship_ai_extractions e where e.id = q.extraction_id  -- the item's last reading
                    and (e.error like 'HTTP 403%limit%' or e.error like 'HTTP 402%'))
     order by q.id limit greatest(1, security.pipeline_num_v1('batch.sch_ai_vendor_requeue', 500)::int)
     for update skip locked)
  update pipeline.scholarship_ai_queue q set state = 'queued', attempts = 0, next_try_at = now(), done_at = null, leased_until = null
    from x where q.id = x.id;
  get diagnostics v_n = row_count;
  if v_n > 0 then
    insert into pipeline.admin_control_events(area, action, target, detail)
    values ('scholarship_ai', 'vendor_requeue', 'pipeline.scholarship_ai_queue', jsonb_build_object('requeued', v_n, 'since', p_since));
  end if;
  return v_n;
end $$;


ALTER FUNCTION "security"."scholarship_ai_vendor_requeue_v1"("p_since" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_audience_read_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline', 'security'
    AS $$
declare v_changed int := 0; v_read int := 0; v_counts jsonb;
  c_intl constant text := '\m(international students?|overseas students?|student visa|subclass 500|onshore|offshore|citizens? of (india|china|sri lanka|bangladesh|indonesia|malaysia|vietnam|nepal|pakistan|philippines|thailand|cambodia|kenya|nigeria|colombia|brazil|mexico|chile|peru|hong kong|singapore|japan|korea|taiwan|turkey|saudi|uae|iran|iraq|egypt|ghana|south africa|canada|usa|united states|uk|united kingdom|germany|france|italy|spain)|from (india|china|sri lanka|bangladesh|indonesia|malaysia|vietnam|nepal|pakistan|philippines|thailand|latin america|africa|asia|europe|the americas)|full[- ]fee[- ]paying international|global excellence|international (merit|excellence|academic))\M';
  c_dom constant text := '\m(domestic students?|australian citizens?|australian permanent residents?|permanent residen(t|cy) of australia|commonwealth supported|csp|hecs|fee[- ]help|home students?|new zealand citizens?|humanitarian visa|aboriginal|torres strait|indigenous|first nations)\M';
  c_dom_nz constant text := '\m(domestic students?|new zealand citizens?|new zealand permanent residents?|permanent residen(t|cy) of new zealand|australian citizens?|home students?|fees[- ]free|studylink|student allowance|maori|māori|pasifika)\M';
  c_dom_ca constant text := '\m(domestic students?|canadian citizens?|canadian permanent residents?|permanent residents? of canada|protected persons?|indigenous|first nations|métis|metis|inuit|osap|canada student (loans?|grants?)|residents? of (british columbia|alberta|ontario|quebec|québec|manitoba|saskatchewan|nova scotia|new brunswick))\M';
  c_both constant text := '\m(all students|domestic and international|international and domestic|regardless of (citizenship|residency|nationality)|open to all)\M';
begin
  with t as (
    select s.id, lower(coalesce(s.name,'') || ' ' || coalesce(s.description,'') || ' ' || coalesce((select string_agg(c.human_text, ' ') from scholarship.criteria c where c.scholarship_id = s.id), '')) txt,
           (select k.iso_alpha2 from catalogue.providers pp join ref.countries k on k.id = pp.country_id where pp.id = s.provider_id) cc
      from scholarship.scholarships s where s.lifecycle_status = 'active'),
  r as (
    select t.id, substring(t.txt from c_intl) p_intl, substring(t.txt from case t.cc when 'NZ' then c_dom_nz when 'CA' then c_dom_ca when 'AU' then c_dom else coalesce((select '\m(' || o.domestic_terms || ')\M' from scholarship.country_onboarding o where o.country_code = t.cc and coalesce(o.domestic_terms, '') <> ''), c_dom) end) p_dom, substring(t.txt from c_both) p_both from t),
  v as (
    select r.id, case when r.p_both is not null or (r.p_intl is not null and r.p_dom is not null) then 'international_and_domestic'
                      when r.p_intl is not null then 'international' when r.p_dom is not null then 'domestic' else 'not_stated' end audience,
           r.p_intl, r.p_dom, r.p_both from r),
  up as (
    insert into scholarship.audience_readings(scholarship_id, audience, phrase_international, phrase_domestic, phrase_both, reader_version, read_at)
    select v.id, v.audience, v.p_intl, v.p_dom, v.p_both, 'scholarship-audience-v1', now() from v
    on conflict (scholarship_id) do update set audience = excluded.audience, phrase_international = excluded.phrase_international, phrase_domestic = excluded.phrase_domestic, phrase_both = excluded.phrase_both, reader_version = excluded.reader_version, read_at = now()
    returning scholarship_id)
  select count(*) into v_read from up;
  update scholarship.scholarships s set audience = a.audience, updated_at = now() from scholarship.audience_readings a where a.scholarship_id = s.id and s.lifecycle_status = 'active' and s.audience is distinct from a.audience  and not exists (select 1 from pipeline.manual_locks k where k.entity = 'scholarship' and k.entity_id = s.id and k.field = 'audience')
    -- v2.15.249: a scholarship whose page the AI read keeps the audience the AI proved
    and not exists (select 1 from pipeline.scholarship_pages sp where sp.scholarship_id = s.id and sp.facts->>'extracted_by' = 'ai');
  get diagnostics v_changed = row_count;
  select jsonb_object_agg(x.audience, x.n) into v_counts from (select a.audience, count(*) n from scholarship.audience_readings a group by 1) x;
  if v_changed > 0 then
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('scholarships', 'audience_read', 'Audience read from each scholarship''s wording', jsonb_build_object('read', v_read, 'changed', v_changed, 'counts', v_counts, 'decision', 'Decision 244'), '63ba56cb-48d4-4169-98c2-7c4d1f72925b');
  end if;
  return jsonb_build_object('read', v_read, 'changed', v_changed, 'counts', v_counts);
end $$;


ALTER FUNCTION "security"."scholarship_audience_read_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_auto_publish_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "statement_timeout" TO '300s'
    AS $$
declare v_ids uuid[]; v_ref text; v_hold uuid[] := '{}';
begin
  -- v1.0.2 (Platform Admin 15 Nov 2026 11:22): a closed scholarship is not served, whether or not automatic publishing is on
  perform security.scholarship_expire_v1();
  if security.scholarship_setting('auto_publish', 0) < 1 then return jsonb_build_object('skipped', 'auto_publish is off'); end if;
  select coalesce(array_agg(p.scholarship_id), '{}') into v_ids
    from security.scholarship_publishability_v1() p join scholarship.scholarships s on s.id = p.scholarship_id
   where p.publishable and coalesce(s.publication_status, 'unpublished') <> 'published'
     and not exists (select 1 from security.layer4_search_blocked_scholarships b where b.scholarship_id = s.id);
  -- v2.15.248 (Platform Admin bugs 11/10-5, Fix 5): a scholarship published automatically that now fails a check is held with the
  -- reason and taken off search; it is listed in Layer 4 to release or fix. One a person published is shown as failing, not held.
  select coalesce(array_agg(p.scholarship_id), '{}') into v_hold
    from security.scholarship_publishability_v1() p join scholarship.scholarships s on s.id = p.scholarship_id
   where not p.publishable and s.publication_status = 'published'
     and not exists (select 1 from pipeline.scholarship_publication_holds h where h.scholarship_id = s.id and h.released_at is null)
     and coalesce((select b.approval_ref from pipeline.scholarship_publication_batches b where s.id = any (b.scholarship_ids) and b.kind = 'publish' order by b.created_at desc limit 1), '') like 'auto-publish%';
  v_ref := to_char(now() at time zone 'Australia/Melbourne', 'DD Mon YYYY HH24:MI');
  if cardinality(v_hold) > 0 then
    insert into pipeline.scholarship_publication_holds(scholarship_id, reason, held_by)
    select p.scholarship_id, 'Failed a check after publishing: ' || array_to_string(p.missing, '; '), 'auto' from security.scholarship_publishability_for_v1(v_hold) p
    on conflict (scholarship_id) do update set reason = excluded.reason, held_by = 'auto', held_at = now(), released_at = null, release_note = null;
    update scholarship.scholarships set publication_status = 'withdrawn', updated_at = now() where id = any (v_hold);
    insert into pipeline.scholarship_publication_batches(kind, approval_ref, scholarship_ids) values ('withdraw', 'auto-hold ' || v_ref, v_hold);
  end if;
  if cardinality(v_ids) > 0 then
    update scholarship.scholarships set publication_status = 'published', updated_at = now() where id = any (v_ids);
    insert into pipeline.scholarship_publication_batches(kind, approval_ref, scholarship_ids) values ('publish', 'auto-publish ' || v_ref, v_ids);
  end if;
  if cardinality(v_ids) + cardinality(v_hold) > 0 then
    insert into search.refresh_requests(requested_by) values ('auto-publish ' || v_ref || ': ' || cardinality(v_ids) || ' published, ' || cardinality(v_hold) || ' held');
  end if;
  return jsonb_build_object('published', cardinality(v_ids), 'held', cardinality(v_hold), 'batch', case when cardinality(v_ids) > 0 then 'auto-publish ' || v_ref end);
end $$;


ALTER FUNCTION "security"."scholarship_auto_publish_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_award_tiers_from_page_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline', 'security'
    AS $$
declare v_sch int := 0; v_tiers int := 0;
begin
  -- the value text first (the candidate set is unchanged by it), then every tier in one statement
  update scholarship.scholarships s set award_value_type = 'text_only', award_value_is_maximum = c.up_to, updated_at = now(), award_value_text = security.scholarship_tier_text(c.pcts, c.amts, c.up_to, scholarship.provider_currency(s.provider_id)) from security.scholarship_page_tier_candidates() c where c.id = s.id;
  get diagnostics v_sch = row_count;
  insert into scholarship.award_tiers(scholarship_id, tier_code, label, percentage, amount, currency_code, basis, notes, display_order, source_id, evidence_id)
  select c.id, 'page_tier_p' || o, 'Stated on the page', p, null, null, 'tuition_fee_reduction', 'One of several values stated on the provider page (Decision 245)', 100 + o, c.source_id, c.evidence_id
    from security.scholarship_page_tier_candidates() c, unnest(c.pcts) with ordinality u(p, o)
  union all
  select c.id, 'page_tier_a' || o, 'Stated on the page', null, a, scholarship.provider_currency((select x.provider_id from scholarship.scholarships x where x.id = c.id)), 'as_stated', 'One of several values stated on the provider page (Decision 245)', 200 + o, c.source_id, c.evidence_id
    from security.scholarship_page_tier_candidates() c, unnest(c.amts) with ordinality u(a, o);
  get diagnostics v_tiers = row_count;
  if v_sch > 0 then
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('scholarships', 'award_tiers_from_page', 'Award tiers recorded from pages stating several values', jsonb_build_object('scholarships', v_sch, 'tiers', v_tiers, 'decision', 'Decision 245'), '63ba56cb-48d4-4169-98c2-7c4d1f72925b');
  end if;
  return jsonb_build_object('scholarships', v_sch, 'tiers', v_tiers);
end $$;


ALTER FUNCTION "security"."scholarship_award_tiers_from_page_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_candidate_skip_v1"("p_provider_id" "uuid", "p_limit" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v int;
begin
  update pipeline.scholarship_page_candidates c set admit_status = 'skipped', admit_reasons = array['skipped: ' || r.label], read_status = coalesce(c.read_status, 'skipped'), read_at = now(), leased_until = null
    from pipeline.scholarship_skip_rules r
   where c.id in (select x.id from pipeline.scholarship_page_candidates x
                   where x.admit_status is null and x.matched_scholarship_id is null and x.source <> 'register' and x.read_status is null
                     and (p_provider_id is null or x.provider_id = p_provider_id) order by x.id desc limit greatest(p_limit, 0))
     and r.active and c.url ~* r.pattern and c.url !~* r.unless_pattern;
  get diagnostics v = row_count;
  return v;
end $$;


ALTER FUNCTION "security"."scholarship_candidate_skip_v1"("p_provider_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_closed_v1"("p_close" "date", "p_precision" "text") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  -- a closing date stated as a month or a year has passed only once that month or year has ended
  select p_close is not null and case coalesce(p_precision, 'day')
    when 'month' then (date_trunc('month', p_close) + make_interval(months => 1))::date <= current_date  -- fixed: calendar arithmetic (end of the stated month)
    when 'year' then (date_trunc('year', p_close) + make_interval(years => 1))::date <= current_date  -- fixed: calendar arithmetic (end of the stated year)
    else p_close < current_date end
$$;


ALTER FUNCTION "security"."scholarship_closed_v1"("p_close" "date", "p_precision" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_closed_v1"("p_close" "date", "p_precision" "text") IS 'CF-247 worker v1.0.2: true when a scholarship''s closing date has passed (a month or a year as stated: once it has ended).';



CREATE OR REPLACE FUNCTION "security"."scholarship_country_readiness_v1"() RETURNS TABLE("country_code" "text", "country" "text", "active_courses" bigint, "providers" bigint, "universities" bigint, "switched_on" boolean, "status" "text", "domestic_terms" boolean, "nationality_term" boolean, "registers_live" integer, "registers_planned" integer, "discovery_queued" bigint, "ready" boolean, "missing" "text"[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with c as (
    select k.id, k.iso_alpha2::text cc, k.name, k.scholarship_ingestion_enabled sw,
           (select count(*) from catalogue.courses co join catalogue.providers p on p.id = co.provider_id where p.country_id = k.id and co.lifecycle_status = 'active') courses,
           (select count(*) from catalogue.providers p where p.country_id = k.id and p.lifecycle_status = 'active') providers,
           o.status, o.domestic_terms, o.government_registers
      from ref.countries k left join scholarship.country_onboarding o on o.country_code = k.iso_alpha2
     where k.scholarship_ingestion_enabled or o.country_code is not null
        or exists (select 1 from catalogue.providers p join catalogue.courses co on co.provider_id = p.id where p.country_id = k.id and co.lifecycle_status = 'active'))
  select c.cc, c.name, c.courses, c.providers,
         (select count(*) from catalogue.providers p where p.country_id = c.id and p.lifecycle_status = 'active'
             and (security.australian_university(p.id) or jsonb_array_length(coalesce(security.provider_university_groups(p.id), '[]')) > 0
                  or (p.canonical_name ~* '\m(university|université|universite)\M' and p.canonical_name !~* '(college|pathways?|language cent|senior|theology|divinity)'))) unis,
         c.sw, coalesce(c.status, 'not listed'),
         c.cc in ('AU','NZ','CA') or coalesce(c.domestic_terms, '') <> '',
         c.cc = 'AU' or exists (select 1 from ref.nationality_terms x where x.code = c.cc),
         (select count(*)::int from scholarship.registers r where r.country_code = c.cc and r.status = 'live'),
         (select count(*)::int from scholarship.registers r where r.country_code = c.cc and r.status = 'planned'),
         (select count(*) from pipeline.scholarship_discovery_providers d join catalogue.providers p on p.id = d.provider_id where p.country_id = c.id),
         x.missing = '{}', x.missing
    from c cross join lateral (select array_remove(array[
         case when c.courses = 0 then 'no active courses in the catalogue yet' end,
         case when c.status is null then 'no onboarding entry (scholarship.country_onboarding)' end,
         case when not (c.cc in ('AU','NZ','CA') or coalesce(c.domestic_terms, '') <> '') then 'no domestic-student wording for the audience reader' end,
         case when not (c.cc = 'AU' or exists (select 1 from ref.nationality_terms x where x.code = c.cc)) then 'no nationality term for the country' end,
         case when c.courses > 0 and not exists (select 1 from catalogue.providers p where p.country_id = c.id and p.lifecycle_status = 'active'
                and (security.australian_university(p.id) or jsonb_array_length(coalesce(security.provider_university_groups(p.id), '[]')) > 0
                     or (p.canonical_name ~* '\m(university|université|universite)\M' and p.canonical_name !~* '(college|pathways?|language cent|senior|theology|divinity)')))
              then 'no university providers recognised' end,
         case when c.sw and c.courses > 0 and not exists (select 1 from pipeline.scholarship_discovery_providers d join catalogue.providers p on p.id = d.provider_id where p.country_id = c.id)
              then 'switched on but no provider queued for scholarship discovery' end
       ], null) missing) x
   order by (c.courses > 0) desc, c.cc
$$;


ALTER FUNCTION "security"."scholarship_country_readiness_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_country_watch_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_raised int := 0; v_resolved int := 0; v_keys text[] := '{}';
begin
  for r in select * from security.scholarship_country_readiness_v1() where active_courses > 0 and (not switched_on or not ready) loop
    v_keys := v_keys || ('scholarship_country:' || r.country_code);
    insert into pipeline.platform_issues as i (check_key, severity, area, title, detail)
    values ('scholarship_country:' || r.country_code, 'warning', 'scholarships',
            left(case when not r.switched_on then r.country || ' has ' || r.active_courses || ' courses but scholarships are not switched on'
                      else r.country || ': scholarships switched on but not ready' end, 300),
            jsonb_build_object('country', r.country_code, 'active_courses', r.active_courses, 'universities', r.universities,
                               'switched_on', r.switched_on, 'missing', to_jsonb(r.missing), 'registers_planned', r.registers_planned,
                               'next_steps', jsonb_build_array(
                                 'Check the domestic-student wording and government registers in scholarship.country_onboarding',
                                 'Build the planned government registers (Layer 1 record registers) for the country',
                                 'Switch the country on: admin_scholarship_country(code, true, reason) - queues its universities for discovery',
                                 'Check reporting views that list countries (data quality, Zoho reference bundle)')))
    on conflict (check_key) where resolved_at is null do update set title = excluded.title, detail = excluded.detail, last_seen = now(), occurrences = i.occurrences + 1;
    v_raised := v_raised + 1;
  end loop;
  update pipeline.platform_issues set resolved_at = now()
   where resolved_at is null and check_key like 'scholarship_country:%' and not (check_key = any(v_keys));
  get diagnostics v_resolved = row_count;
  return jsonb_build_object('raised_or_updated', v_raised, 'resolved', v_resolved, 'at', now());
end $$;


ALTER FUNCTION "security"."scholarship_country_watch_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_course_attribute_sync_v1"("p_full" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline', 'search', 'security'
    AS $$
declare v_since timestamptz; v_now timestamptz := now(); v_ids uuid[]; v_res jsonb; v_done int := 0; v_batch uuid[]; i int := 0;
begin
  select last_run_at into v_since from pipeline.scholarship_attribute_sync where id = 1;
  if p_full then
    select array_agg(distinct x) into v_ids from (
      select course_id x from scholarship.course_mappings where mapping_state = 'mapped'
      union select d.course_id from search.course_documents d where coalesce(jsonb_array_length(d.scholarship_options), 0) > 0) q;
  else
    select array_agg(distinct x) into v_ids from (
      select m.course_id x from scholarship.course_mappings m join scholarship.scholarships s on s.id = m.scholarship_id where s.updated_at > v_since
      union select fc.course_id from scholarship.course_financial_calculations fc where fc.calculated_at > v_since
      union select m.course_id from scholarship.course_mappings m join pipeline.scholarship_publication_batches b on m.scholarship_id = any(b.scholarship_ids) where b.created_at > v_since
      union select m.course_id from scholarship.course_mappings m where m.updated_at > v_since) q;
  end if;
  v_ids := coalesce(v_ids, '{}');
  while i * 2000 < cardinality(v_ids) loop
    v_batch := v_ids[i * 2000 + 1 : (i + 1) * 2000];
    v_res := search.refresh_course_enrichment_core_scoped_v1(v_batch, true);
    v_done := v_done + coalesce((v_res->>'changed')::int, 0);
    i := i + 1;
  end loop;
  v_res := jsonb_build_object('full', p_full, 'courses', cardinality(v_ids), 'changed', v_done, 'since', v_since);
  update pipeline.scholarship_attribute_sync set last_run_at = v_now, last_result = v_res where id = 1;
  return v_res;
end $$;


ALTER FUNCTION "security"."scholarship_course_attribute_sync_v1"("p_full" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_course_title_match_v1"("p_named" "text", "p_canonical" "text", "p_display" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  with n as (select regexp_replace(lower(coalesce(p_named, '')), '[^a-z0-9]+', '', 'g') named,
                    regexp_replace(lower(coalesce(p_canonical, '')), '[^a-z0-9]+', '', 'g') a,
                    regexp_replace(lower(coalesce(p_display, '')), '[^a-z0-9]+', '', 'g') b)
  select length(named) >= 8 and (named in (a, b)
         or (length(named) >= 20 and ((a <> '' and (strpos(a, named) > 0 or (length(a) >= 20 and strpos(named, a) > 0)))
                                   or (b <> '' and (strpos(b, named) > 0 or (length(b) >= 20 and strpos(named, b) > 0))))))
    from n
$$;


ALTER FUNCTION "security"."scholarship_course_title_match_v1"("p_named" "text", "p_canonical" "text", "p_display" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_coverage_classify_remedy_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_ids uuid[]; v jsonb;
begin
  select i.provider_ids into v_ids from pipeline.integration_issues i where i.id = p_issue;
  if coalesce(cardinality(v_ids), 0) = 0 then return jsonb_build_object('ok', false, 'changed', false, 'evidence', 'issue has no provider'); end if;
  v := security.scholarship_coverage_classify_v1(v_ids);
  return jsonb_build_object('ok', true, 'changed', coalesce((v->>'work_reports')::int, 0) > 0, 'evidence', v);
end $$;


ALTER FUNCTION "security"."scholarship_coverage_classify_remedy_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_coverage_classify_v1"("p_providers" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_ids uuid[]; v_now timestamptz := now(); v_esc numeric := security.pipeline_num_v1('sch_cov.escalate_after_hours', 72);
        v_re numeric := security.pipeline_num_v1('sch_cov.recheck_hours', 24); v_ver numeric := security.pipeline_num_v1('sch_cov.verify_after_hours', 48);
        r record; p record; v_sig text; v_rep jsonb; v_ev text; v_n int := 0; v_items int := 0; v_reports int := 0; v_ok int := 0; v_fail int := 0;
        v_dup int := 0; v_rerr int := 0; v_rlast text;
begin
  if p_providers is null and security.pipeline_num_v1('sch_cov.classify_on', 1) < 1 then return jsonb_build_object('ran', false, 'reason', 'sch_cov.classify_on is 0'); end if;
  if p_providers is not null then v_ids := p_providers;
  else
    select coalesce(array_agg(x.provider_id), '{}') into v_ids from (
      select l.provider_id from pipeline.coverage_provider_reconciliation l
        left join pipeline.scholarship_coverage_providers c on c.provider_id = l.provider_id
       where l.domain = 'scholarship' and l.disposition not in ('not_applicable', 'out_of_scope')
         and (c.provider_id is null or c.classified_at < v_now - make_interval(hours => security.pipeline_num_v1('sch_cov.reclassify_hours', 6)::int))
       -- F-SCH.14 (13 Nov 2026): new first; then providers whose open scholarship Layer 4 case or pending AI review waits on re-classification,
       -- or not classified within sch_cov.max_age_hours; then providers with an integration issue; then the rest, oldest first
       order by case when c.provider_id is null then 0
                     when c.classified_at < v_now - make_interval(hours => security.pipeline_num_v1('sch_cov.max_age_hours', 36)::int)
                       or exists (select 1 from pipeline.layer4_interventions i where i.provider_id = l.provider_id and i.lane like 'sch%' and i.status = 'awaiting_input')
                       or exists (select 1 from pipeline.scholarship_ai_reviews ar where ar.provider_id = l.provider_id and ar.status = 'pending') then 1  -- v1.0.2: not "r", the record variable
                     when l.issue_fingerprint is not null then 2 else 3 end,
                c.classified_at nulls first, l.provider_id
       limit security.pipeline_num_v1('batch.sch_coverage_classify', 40)::int) x;
  end if;
  if cardinality(v_ids) = 0 then return jsonb_build_object('ran', true, 'providers', 0); end if;

  create temp table if not exists sch_cov_now(provider_id uuid, item_key text, state text, reason text, evidence jsonb, recovery text) on commit drop;
  truncate sch_cov_now;
  insert into sch_cov_now select * from security.scholarship_coverage_items_v1(v_ids);
  get diagnostics v_items = row_count;
  v_dup := v_items - (select count(*) from (select distinct n.provider_id, n.item_key from sch_cov_now n) d);

  insert into pipeline.scholarship_coverage_items as i(provider_id, item_key, state, reason, evidence, recovery, owner, next_recovery_at, escalation, present, first_seen, state_since, classified_at)
  -- CF-247 fix (4 Nov 2026): a listing can list the same address twice; one row per (provider_id, item_key), the most pressing state first
  select distinct on (n.provider_id, n.item_key) n.provider_id, n.item_key, n.state, n.reason, n.evidence, case when n.state in ('rejected_incorrectly', 'traversal_incomplete') then n.recovery end, k.owner,
         case when k.resolved then null else v_now + make_interval(hours => v_re::int) end, null, true, v_now, v_now, v_now
    from sch_cov_now n join pipeline.scholarship_coverage_state_codes k on k.code = n.state
   order by n.provider_id, n.item_key, k.sort, md5(n.evidence::text)
  on conflict (provider_id, item_key) do update set
     state_since = case when i.state is distinct from excluded.state or not i.present then v_now else i.state_since end,
     state = excluded.state, reason = excluded.reason, evidence = excluded.evidence, recovery = excluded.recovery, owner = excluded.owner,
     next_recovery_at = excluded.next_recovery_at, present = true, classified_at = v_now;
  update pipeline.scholarship_coverage_items i set present = false, classified_at = v_now, next_recovery_at = null
   where i.provider_id = any (v_ids) and i.present and not exists (select 1 from sch_cov_now n where n.provider_id = i.provider_id and n.item_key = i.item_key);

  -- §9 steps 7-8: a recovery succeeded when its case moved; it failed when the case has not moved after sch_cov.verify_after_hours
  update pipeline.scholarship_coverage_recoveries x set outcome = 'succeeded', outcome_at = v_now
    from pipeline.scholarship_coverage_items i
   where x.outcome is null and i.provider_id = x.provider_id and i.item_key = x.item_key and x.provider_id = any (v_ids) and (not i.present or i.state <> x.state_before);
  get diagnostics v_ok = row_count;
  update pipeline.scholarship_coverage_recoveries x set outcome = 'failed', outcome_at = v_now
    from pipeline.scholarship_coverage_items i
   where x.outcome is null and i.provider_id = x.provider_id and i.item_key = x.item_key and x.provider_id = any (v_ids) and i.present and i.state = x.state_before
     and x.at < v_now - make_interval(hours => v_ver::int);
  get diagnostics v_fail = row_count;

  -- the escalation condition of each unresolved case
  update pipeline.scholarship_coverage_items i set escalation = jsonb_build_object('condition', k.escalate_when,
           'due_at', case k.escalate_when when 'always' then i.first_seen when 'after_hours' then i.first_seen + make_interval(hours => v_esc::int)
                                          when 'recovery_failed' then (select min(x.outcome_at) from pipeline.scholarship_coverage_recoveries x where x.item_key = i.item_key and x.outcome = 'failed') end,
           'due', case k.escalate_when when 'always' then true when 'after_hours' then i.first_seen < v_now - make_interval(hours => v_esc::int)
                                       when 'recovery_failed' then exists (select 1 from pipeline.scholarship_coverage_recoveries x where x.item_key = i.item_key and x.outcome = 'failed')
                                       else false end)
    from pipeline.scholarship_coverage_state_codes k
   where k.code = i.state and i.provider_id = any (v_ids) and i.present and not k.resolved;
  update pipeline.scholarship_coverage_items i set escalation = null
    from pipeline.scholarship_coverage_state_codes k where k.code = i.state and i.provider_id = any (v_ids) and (k.resolved or not i.present) and i.escalation is not null;

  -- the provider state and the work-continuity record
  for p in select x.id, coalesce(c.reported, '{}'::jsonb) reported,
                  (select coalesce(jsonb_object_agg(s.state, s.n), '{}'::jsonb) from (select i.state, count(*) n from pipeline.scholarship_coverage_items i
                     where i.provider_id = x.id and i.present group by 1) s) states
             from unnest(v_ids) x(id) left join pipeline.scholarship_coverage_providers c on c.provider_id = x.id loop
    v_rep := '{}'::jsonb;
    for r in select k.code, k.resolved, k.work_event, k.owner, count(i.item_key) n, bool_or(coalesce((i.escalation->>'due')::boolean, false)) due,
                    min(i.next_recovery_at) next_at, (array_agg(i.evidence order by i.first_seen))[1:3] sample, (array_agg(i.reason order by i.first_seen))[1] reason,
                    string_agg(i.item_key, ',' order by i.item_key) keys
               from pipeline.scholarship_coverage_state_codes k
               join pipeline.scholarship_coverage_items i on i.state = k.code and i.provider_id = p.id and i.present
              where not k.resolved group by k.code, k.resolved, k.work_event, k.owner loop
      v_sig := md5(r.n || '|' || r.due || '|' || r.keys);
      v_rep := v_rep || jsonb_build_object(r.code, v_sig);
      continue when p.reported->>r.code = v_sig;
      v_ev := case when r.due and r.work_event in ('dependency', 'ambiguity') then 'failed'
                   when r.work_event = 'review' then 'review' when r.work_event = 'identity' then 'failed' when r.work_event = 'ambiguity' then 'failed' else 'dependency' end;
      begin
      perform security.work_item_report_v1('sch_coverage', p.id::text, 'state:' || r.code, v_ev,
        jsonb_build_object('provider_id', p.id, 'owner', r.owner, 'field', r.code,
                           'class', case when r.work_event = 'identity' then 'identity_conflict' when r.work_event = 'ambiguity' then 'ambiguity' when r.due then 'authority' end,
                           'reason', r.code || ': ' || r.n || ' case(s); ' || coalesce(r.reason, ''), 'review_ref', 'sch_coverage:' || p.id || ':' || r.code,
                           'ref', jsonb_build_object('state', r.code, 'next_recovery_at', r.next_at, 'owner', r.owner),
                           'evidence', jsonb_build_object('cases', r.n, 'sample', to_jsonb(r.sample), 'escalation_due', r.due)));
      v_reports := v_reports + 1;
      exception when others then
        -- not recorded as reported, so the next run tries again; the cases are kept
        v_rerr := v_rerr + 1; v_rlast := left(r.code || ': ' || sqlerrm, 300); v_rep := v_rep - r.code;
      end;
    end loop;
    -- a state reported before and now resolved or gone: the work item is done
    for r in select e.key code from jsonb_each_text(p.reported) e where not v_rep ? e.key loop
      begin
        perform security.work_item_report_v1('sch_coverage', p.id::text, 'state:' || r.code, 'succeeded', jsonb_build_object('provider_id', p.id, 'outcome', 'succeeded_with_result'));
        v_reports := v_reports + 1;
      exception when others then
        v_rerr := v_rerr + 1; v_rlast := left(r.code || ': ' || sqlerrm, 300); v_rep := v_rep || jsonb_build_object(r.code, p.reported->>r.code);
      end;
    end loop;
    insert into pipeline.scholarship_coverage_providers as c(provider_id, provider_state, states, unresolved, published_verified, reported, classified_at)
    select p.id,
           coalesce((select k.code from pipeline.scholarship_coverage_state_codes k where not k.resolved and p.states ? k.code order by k.sort limit 1),
                    case when coalesce((p.states->>'published_verified')::int, 0) > 0 then 'published_verified'
                         when exists (select 1 from pipeline.scholarship_listing_pages l where l.provider_id = p.id and l.active and l.source in ('manual', 'auto')
                                                                                       and l.status = 'read' and l.page_state in ('complete', 'single')) then 'evidence_backed_none'
                         when p.states ? 'searched_none' then 'searched_none'
                         when p.states ? 'not_in_scope' then 'not_in_scope'
                         else 'source_not_discovered' end),
           p.states, (select coalesce(sum(e.value::int), 0) from jsonb_each_text(p.states) e join pipeline.scholarship_coverage_state_codes k on k.code = e.key and not k.resolved),
           coalesce((p.states->>'published_verified')::int, 0), v_rep, v_now
    on conflict (provider_id) do update set provider_state = excluded.provider_state, states = excluded.states, unresolved = excluded.unresolved,
       published_verified = excluded.published_verified, reported = excluded.reported, classified_at = v_now;
    v_n := v_n + 1;
  end loop;
  -- direction 4 Nov 2026 10:00 §6: the run's answer is kept (pg_cron discards it); a ledger write never fails the run
  begin
    insert into pipeline.scholarship_coverage_classify_runs(manual, providers, cases, work_reports, recoveries_succeeded, recoveries_failed, duplicate_cases, report_errors,
           report_error_last, result)
    values (p_providers is not null, v_n, v_items, v_reports, v_ok, v_fail, v_dup, v_rerr, v_rlast,
            jsonb_build_object('ran', true, 'providers', v_n, 'cases', v_items, 'work_reports', v_reports, 'recoveries_succeeded', v_ok, 'recoveries_failed', v_fail,
                               'duplicate_cases', v_dup, 'report_errors', v_rerr, 'report_error_last', v_rlast));
  exception when others then null;
  end;
  -- CF-247 F-SCH (13 Nov 2026): the per-provider coverage snapshot (Coverage › All providers), on the full run only
  if p_providers is null then
    begin perform security.scholarship_provider_coverage_refresh_v1();
    exception when others then raise warning 'scholarship_provider_coverage_refresh_v1: %', sqlerrm; end;
  end if;
  return jsonb_build_object('ran', true, 'providers', v_n, 'cases', v_items, 'work_reports', v_reports, 'recoveries_succeeded', v_ok, 'recoveries_failed', v_fail,
                            'duplicate_cases', v_dup, 'report_errors', v_rerr, 'report_error_last', v_rlast);
end $$;


ALTER FUNCTION "security"."scholarship_coverage_classify_v1"("p_providers" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_coverage_classify_v1"("p_providers" "uuid"[]) IS 'CF-247 (mandate 4 Nov 2026 05:08 §5, §9): job scholarship-coverage-classify. Classifies providers'' scholarship cases, verifies recoveries, records provider states and reports unresolved states into the work-continuity record (lane sch_coverage). Records only.';



CREATE OR REPLACE FUNCTION "security"."scholarship_coverage_items_v1"("p_providers" "uuid"[]) RETURNS TABLE("provider_id" "uuid", "item_key" "text", "state" "text", "reason" "text", "evidence" "jsonb", "recovery" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 (mandate 4 Nov 2026 05:08 §5): every scholarship coverage case of the providers given, in one of the 13 states, from the existing
  -- statuses. Read-only; the consumer API is only read (api.website_v2_scholarship_item) for "published and consumer-verified".
  with pv as (select p.id, coalesce(t.code, '') ptype, security.scholarship_admission_provider_ok_v1(p.id) admit_ok, security.scholarship_legal_name_ok_v1(p.id) legal_ok
                from catalogue.providers p left join ref.provider_types t on t.id = p.provider_type_id where p.id = any (p_providers)),
  lst as (select l.* from pipeline.scholarship_listing_pages l join pv on pv.id = l.provider_id),
  cands as (select c.*, coalesce(security.url_on_provider_sites(c.url, c.provider_id), false) own, security.third_party_host_v1(coalesce(c.url, '')) dir
              from pipeline.scholarship_page_candidates c join pv on pv.id = c.provider_id),
  ai as (select distinct on (e.candidate_id) e.candidate_id, e.verdict, e.answer, e.model_code, e.at from pipeline.scholarship_ai_extractions e
           join cands c on c.id = e.candidate_id where e.error is null order by e.candidate_id, e.at desc),
  rv as (select r.candidate_id, r.scholarship_id, r.id, r.reason, r.created_at from pipeline.scholarship_ai_reviews r join pv on pv.id = r.provider_id where r.status = 'pending'),
  op as (select o.candidate_id, o.id, o.host from pipeline.scholarship_owner_proposals o join pv on pv.id = o.holder_provider_id where o.state = 'proposed'),
  cs as (
    select c.provider_id, 'cand:' || c.id item_key,
           case when exists (select 1 from rv where rv.candidate_id = c.id) then 'awaiting_layer4'
                when exists (select 1 from op where op.candidate_id = c.id) then 'ownership_conflict'
                when c.admit_status is null then 'source_found_unread'
                when c.admit_reasons && array['register_retired'] and c.own and not c.dir and c.read_status is null then 'rejected_incorrectly'
                when c.admit_reasons && array['not a university provider in a scholarship country'] and (pv.admit_ok or pv.legal_ok) then 'rejected_incorrectly'
                when c.admit_reasons && array['domestic_only'] then 'domestic_only'
                when c.admit_reasons && array['past_year_only', 'not_offered'] then 'expired'
                when c.admit_reasons && array['listing_page'] and ai.verdict = 'listing' and coalesce(ai.answer->>'is_scholarship', '') = 'true'
                     and ai.answer->>'audience' in ('international', 'both', 'international_and_domestic') and c.own and not c.dir
                     and not exists (select 1 from lst l where l.provider_id = c.provider_id and l.active and l.source in ('manual', 'auto')
                                                          and l.url_norm = security.scholarship_url_norm(coalesce(c.final_url, c.url))) then 'traversal_incomplete'
                when c.admit_reasons && array['international_not_stated'] and ai.verdict = 'scholarship' and coalesce(ai.answer->>'is_scholarship', '') = 'true' then 'international_unresolved'
                else 'rejected_correctly' end state,
           case when exists (select 1 from rv where rv.candidate_id = c.id) then 'pending AI review: ' || (select rv.reason from rv where rv.candidate_id = c.id limit 1)
                when exists (select 1 from op where op.candidate_id = c.id) then 'owner proposal (directory page)'
                when c.admit_status is null then case when c.read_status is null then 'waiting for the candidate reader' else 'waiting for the AI reader' end
                when c.admit_reasons && array['register_retired'] and c.own and not c.dir and c.read_status is null then 'register_page_never_read'
                when c.admit_reasons && array['not a university provider in a scholarship country'] and (pv.admit_ok or pv.legal_ok) then 'provider_identity_name_rule'
                when c.admit_reasons && array['not a university provider in a scholarship country'] then 'admission_policy'
                else array_to_string(c.admit_reasons, ', ') end reason,
           jsonb_build_object('candidate_id', c.id, 'url', c.url, 'title', c.title, 'source', c.source, 'read_status', c.read_status, 'admit_status', c.admit_status,
                              'admit_reasons', to_jsonb(c.admit_reasons), 'stored_copy', c.storage_path is not null, 'evidence_id', c.evidence_id, 'own_site', c.own,
                              'ai', case when ai.candidate_id is not null then jsonb_build_object('verdict', ai.verdict, 'model', ai.model_code, 'at', ai.at,
                                                                                                 'audience', ai.answer->>'audience', 'is_scholarship', ai.answer->'is_scholarship',
                                                                                                 'name', ai.answer->>'name') end) evidence,
           case when exists (select 1 from rv where rv.candidate_id = c.id) or exists (select 1 from op where op.candidate_id = c.id) then null
                when c.admit_reasons && array['register_retired'] and c.own and not c.dir and c.read_status is null then 'reopen_read'
                when c.admit_reasons && array['not a university provider in a scholarship country'] and (pv.admit_ok or pv.legal_ok) and c.storage_path is not null then 'reread_stored'
                when c.admit_reasons && array['listing_page'] and ai.verdict = 'listing' and coalesce(ai.answer->>'is_scholarship', '') = 'true'
                     and ai.answer->>'audience' in ('international', 'both', 'international_and_domestic') and c.own and not c.dir then 'promote_listing' end recovery
      from cands c join pv on pv.id = c.provider_id left join ai on ai.candidate_id = c.id
     where c.admitted_scholarship_id is null and c.matched_scholarship_id is null),
  -- register entries no candidate carries (the register was retired on 11 Oct 2026; its entries are evidence of what the provider lists)
  rg as (
    select r.provider_id, 'reg:' || r.register_code || ':' || r.listing_id item_key,
           case when r.handoff_status = 'provider_page_off_provider_site' then 'ownership_conflict' else 'source_not_discovered' end state,
           case when r.handoff_status = 'provider_page_off_provider_site' then 'register_page_on_unowned_host' else 'register_entry_without_candidate: ' || coalesce(r.handoff_status, 'none') end reason,
           jsonb_build_object('register', r.register_code, 'name', r.name, 'listed_under', r.provider_name, 'page', r.website_url, 'level', r.level_text,
                              'host', lower(substring(coalesce(r.website_url, '') from '^[a-z]+://(?:www\.)?([^/:?#]+)')), 'last_seen', r.last_seen_at) evidence,
           null::text recovery
      from scholarship.register_listings r join pv on pv.id = r.provider_id
     where r.departed_at is null and r.scholarship_id is null and r.candidate_id is null),
  -- listing items with their own page on the provider's site that are neither a member nor a candidate
  li as (
    select l.provider_id, 'list:' || l.id || ':' || security.scholarship_url_norm(i->>'url') item_key, 'traversal_incomplete' state,
           case when l.page_state is null then 'listing_read_before_fan_out' else 'item_not_yet_a_candidate' end reason,
           jsonb_build_object('listing_id', l.id, 'listing', l.url, 'item', i->>'name', 'url', i->>'url', 'read_at', l.read_at, 'page_state', l.page_state, 'next_read_at', l.next_read_at) evidence,
           case when l.page_state is null then 'refresh_listing' end recovery
      from lst l cross join lateral jsonb_array_elements(case when jsonb_typeof(l.items) = 'array' then l.items else '[]'::jsonb end) i
     where l.active and l.source in ('manual', 'auto') and coalesce(i->>'url', '') ~* '^https?://'
       and coalesce(security.url_on_provider_sites(i->>'url', l.provider_id), false) and security.scholarship_url_norm(i->>'url') <> l.url_norm
       and not exists (select 1 from pipeline.scholarship_listing_members m where m.listing_id = l.id and m.item_key = 'url:' || security.scholarship_url_norm(i->>'url'))
       and not exists (select 1 from cands c where c.provider_id = l.provider_id and c.url_norm = security.scholarship_url_norm(i->>'url'))
       and not exists (select 1 from scholarship.scholarships s where s.provider_id = l.provider_id and s.lifecycle_status = 'active'
                                                              and security.scholarship_url_norm(s.source_url) = security.scholarship_url_norm(i->>'url'))),
  -- suggested listing pages nobody accepted: found, never read
  ls as (
    select l.provider_id, 'listing:' || l.id item_key, 'source_found_unread' state, 'listing_suggested_not_accepted' reason,
           jsonb_build_object('listing_id', l.id, 'url', l.url, 'source', l.source) evidence, null::text recovery
      from lst l where l.source = 'suggested' and not l.active),
  -- CF-247 IQ-00264 (4 Nov 2026): the publishing checks each unpublished scholarship fails
  sp as (select x.* from security.scholarship_publishability_for_v1(array(select s.id from scholarship.scholarships s join pv on pv.id = s.provider_id
                                                                          where s.lifecycle_status = 'active' and s.publication_status <> 'published')) x),
  sh as (
    select s.provider_id, 'sch:' || s.id item_key,
           case when s.publication_status = 'published' and api.website_v2_scholarship_item(s.id) is not null then 'published_verified'
                when s.publication_status = 'published' then 'admitted_not_published'
                when exists (select 1 from pipeline.scholarship_round_states rs where rs.scholarship_id = s.id and rs.state = 'ended') then 'expired'
                when s.audience = 'domestic' then 'domestic_only'
                when exists (select 1 from rv where rv.scholarship_id = s.id)
                  or exists (select 1 from pipeline.layer4_review_items r where r.entity_type = 'scholarship' and r.entity_id = s.id and r.status = 'pending') then 'awaiting_layer4'
                -- CF-247 IQ-00264: a person's refusal, or a person's confirmation that the page states no award value, is a decision, never re-asked
                when exists (select 1 from pipeline.scholarship_publication_holds h where h.scholarship_id = s.id and h.released_at is null and h.held_by = 'admin'
                               and (h.reason ~* '^Refused in Layer 4' or h.reason ~* '^Prize or award, not a scholarship'))
                  or exists (select 1 from pipeline.layer4_interventions v where v.lane = 'sch_value' and v.entity = s.provider_id::text || '|sch:' || s.id::text
                               and v.missing_fact = 'sch_value_missing' and v.status = 'not_published') then 'rejected_correctly'
                else 'admitted_not_published' end state,
           case when s.publication_status = 'published' and api.website_v2_scholarship_item(s.id) is null then 'published_but_not_returned_by_consumer_api'
                when s.publication_status <> 'published' then coalesce((select h.reason from pipeline.scholarship_publication_holds h where h.scholarship_id = s.id and h.released_at is null limit 1),
                                                                        (select 'a person confirmed the page states no award value' from pipeline.layer4_interventions v
                                                                          where v.lane = 'sch_value' and v.entity = s.provider_id::text || '|sch:' || s.id::text and v.status = 'not_published' limit 1),
                                                                        (select 'publishing checks: ' || array_to_string(x.missing, '; ') from sp x where x.scholarship_id = s.id and cardinality(x.missing) > 0),
                                                                        s.publication_status) end reason,
           jsonb_build_object('scholarship_id', s.id, 'name', s.name, 'publication_status', s.publication_status, 'audience', s.audience, 'page', s.source_url,
                              'missing', (select to_jsonb(x.missing) from sp x where x.scholarship_id = s.id),
                              'held_by', (select h.held_by from pipeline.scholarship_publication_holds h where h.scholarship_id = s.id and h.released_at is null limit 1)) evidence,
           null::text recovery
      from scholarship.scholarships s join pv on pv.id = s.provider_id where s.lifecycle_status = 'active'),
  -- the provider itself, when no source was found at all
  pr as (
    select pv.id provider_id, 'provider' item_key,
           -- CF-247 SCH (8 Nov 2026): a successful site map that found no scholarship page is "searched, none found"; a provider outside scholarship search by policy is "not in scope"
           case when security.pipeline_num_v1('sch_cov.scope_states_on', 1) >= 1 and dp.status = 'empty' and coalesce(dp.method, '') ~ 'map_search[(]' and coalesce(dp.method, '') !~ 'map:' then 'searched_none'
                when security.pipeline_num_v1('sch_cov.scope_states_on', 1) >= 1 and security.scholarship_scope_v1(pv.id) <> 'in_scope' then 'not_in_scope'
                else 'source_not_discovered' end state,
           'discovery ' || coalesce(dp.status, 'never queued') || coalesce(' (' || dp.settle_reason || ')', '') || coalesce(', kept ' || dp.kept_count || ' of ' || dp.url_count, '') reason,
           jsonb_build_object('discovery', dp.status, 'method', dp.method, 'kept', dp.kept_count, 'mapped', dp.url_count, 'discovered_at', dp.discovered_at,
                              'next_discover_at', dp.next_discover_at, 'admission_ok', pv.admit_ok, 'provider_type', pv.ptype,
                              'scope', security.scholarship_scope_v1(pv.id)) evidence, null::text recovery
      from pv left join pipeline.scholarship_discovery_providers dp on dp.provider_id = pv.id
     where not exists (select 1 from cands c where c.provider_id = pv.id) and not exists (select 1 from lst l where l.provider_id = pv.id and l.active)
       and not exists (select 1 from scholarship.scholarships s where s.provider_id = pv.id and s.lifecycle_status = 'active'))
  select * from cs union all select * from rg union all select * from li union all select * from ls union all select * from sh union all select * from pr
$$;


ALTER FUNCTION "security"."scholarship_coverage_items_v1"("p_providers" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_coverage_items_v1"("p_providers" "uuid"[]) IS 'CF-247 (mandate 4 Nov 2026 05:08 §5): every scholarship coverage case of the providers given in one of the 13 states (pipeline.scholarship_coverage_state_codes), with reason, evidence and the recovery that applies. Read-only.';



CREATE OR REPLACE FUNCTION "security"."scholarship_coverage_recover_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_max int := security.pipeline_num_v1('batch.sch_coverage_recover', 10)::int; v_pp int := security.pipeline_num_v1('sch_cov.recover_per_provider_max', 3)::int;
        v_on jsonb := jsonb_build_object('reopen_read', security.pipeline_num_v1('sch_cov.recover_register_pages_on', 0) >= 1,
                                         'reread_stored', security.pipeline_num_v1('sch_cov.recover_stored_reads_on', 0) >= 1,
                                         'promote_listing', security.pipeline_num_v1('sch_cov.recover_listings_on', 0) >= 1,
                                         'refresh_listing', security.pipeline_num_v1('sch_cov.recover_listings_on', 0) >= 1);
        r record; v_cid bigint; v_lid bigint; v_done int := 0; v_skip int := 0; v_per jsonb := '{}'::jsonb; v_by jsonb := '{}'::jsonb; a record; v_k int;
begin
  if not exists (select 1 from jsonb_each(v_on) e where e.value = 'true'::jsonb) then return jsonb_build_object('ran', false, 'reason', 'every recovery switch is 0', 'switches', v_on); end if;
  for r in select i.* from pipeline.scholarship_coverage_items i
            where i.present and i.recovery is not null and i.state in ('rejected_incorrectly', 'traversal_incomplete')
              and coalesce((v_on->>i.recovery)::boolean, false)
              and not exists (select 1 from pipeline.scholarship_coverage_recoveries x where x.item_key = i.item_key and x.action = i.recovery)
            order by i.first_seen, i.provider_id, i.item_key loop
    exit when v_done >= v_max;
    if coalesce((v_per->>r.provider_id::text)::int, 0) >= v_pp then continue; end if;
    if not security.scholarship_admission_provider_ok_v1(r.provider_id) or security.fc_sch_held_v1(r.provider_id, true)
       or exists (select 1 from security.provider_hidden_v1 h where h.provider_id = r.provider_id) then v_skip := v_skip + 1; continue; end if;
    v_cid := nullif(r.evidence->>'candidate_id', '')::bigint; v_lid := nullif(r.evidence->>'listing_id', '')::bigint; v_k := 0;
    if r.recovery = 'reopen_read' then
      -- one read of a page never read: back to the candidate reader (Firecrawl through svc_fc_spend, then the AI on the normal admission route)
      update pipeline.scholarship_page_candidates c set admit_status = null, admit_reasons = null, next_read_at = now(), attempts = 0, leased_until = null
       where c.id = v_cid and c.admit_status = 'rejected' and c.read_status is null and c.matched_scholarship_id is null and c.admitted_scholarship_id is null;
      get diagnostics v_k = row_count;
    elsif r.recovery = 'reread_stored' then
      -- one AI read from the stored copy (no Firecrawl: next_read_at keeps the candidate reader away); the answer takes the normal admission route
      select * into a from security.scholarship_ai_active_v1();
      if a.model_code is not null then
        update pipeline.scholarship_page_candidates c set admit_status = null, admit_reasons = null, next_read_at = 'infinity'
         where c.id = v_cid and c.admit_status = 'rejected' and c.storage_path is not null and c.matched_scholarship_id is null and c.admitted_scholarship_id is null
           and not exists (select 1 from pipeline.scholarship_ai_queue q where q.candidate_id = c.id and q.state in ('queued', 'leased'));
        get diagnostics v_k = row_count;
        if v_k > 0 then
          insert into pipeline.scholarship_ai_queue(model_code, prompt_version, run_kind, candidate_id, provider_id, url, storage_path)
          select a.model_code, a.prompt_version, 'admit', c.id, c.provider_id, coalesce(c.final_url, c.url), c.storage_path from pipeline.scholarship_page_candidates c where c.id = v_cid;
        end if;
      end if;
    elsif r.recovery = 'promote_listing' then
      -- the AI said: a listing of international scholarships on the provider's own site; it becomes a listing source (read once now, then weekly)
      insert into pipeline.scholarship_listing_pages as l(provider_id, url, url_norm, source, active, status, next_read_at, added_at)
      select c.provider_id, coalesce(c.final_url, c.url), security.scholarship_url_norm(coalesce(c.final_url, c.url)), 'auto', true, 'waiting', now(), now()
        from pipeline.scholarship_page_candidates c where c.id = v_cid and not security.third_party_host_v1(coalesce(c.final_url, c.url))
      on conflict (provider_id, url_norm) do update set source = 'auto', active = true, status = 'waiting', next_read_at = now() where l.source = 'suggested';
      get diagnostics v_k = row_count;
    elsif r.recovery = 'refresh_listing' then
      -- a listing read before its items became candidates: read once now (the recorder fans its items out)
      if not exists (select 1 from pipeline.scholarship_coverage_recoveries x where x.action = 'refresh_listing' and (x.detail->>'listing_id')::bigint = v_lid) then
        update pipeline.scholarship_listing_pages l set next_read_at = now() where l.id = v_lid and l.active and l.page_state is null and l.next_read_at > now();
        get diagnostics v_k = row_count;
      end if;
    end if;
    -- recorded whatever happened, so the same case is never tried twice
    insert into pipeline.scholarship_coverage_recoveries(provider_id, item_key, action, state_before, detail)
    values (r.provider_id, r.item_key, r.recovery, r.state, jsonb_build_object('candidate_id', v_cid, 'listing_id', v_lid, 'changed', v_k, 'reason', r.reason))
    on conflict (item_key, action) do nothing;
    if v_k > 0 then
      v_done := v_done + 1; v_per := v_per || jsonb_build_object(r.provider_id::text, coalesce((v_per->>r.provider_id::text)::int, 0) + 1);
      v_by := v_by || jsonb_build_object(r.recovery, coalesce((v_by->>r.recovery)::int, 0) + 1);
    else v_skip := v_skip + 1; end if;
  end loop;
  return jsonb_build_object('ran', true, 'actions', v_done, 'by_action', v_by, 'skipped', v_skip, 'providers', (select count(*) from jsonb_object_keys(v_per)), 'switches', v_on);
end $$;


ALTER FUNCTION "security"."scholarship_coverage_recover_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_coverage_recover_v1"() IS 'CF-247 (mandate 4 Nov 2026 05:08 §5, §9): job scholarship-coverage-recover. Bounded, once-per-case recovery (reopen_read, reread_stored, promote_listing, refresh_listing), each family behind a switch that ships off. Admits, decides and publishes nothing.';



CREATE OR REPLACE FUNCTION "security"."scholarship_coverage_report_v1"("p_provider" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 (mandate 4 Nov 2026 05:08 §5, §11): cases by state, providers by state, recoveries by action and outcome; one provider's cases when given
  select jsonb_build_object(
    'cases', (select coalesce(jsonb_object_agg(s.state, s.n), '{}'::jsonb) from (select i.state, count(*) n from pipeline.scholarship_coverage_items i
               where i.present and (p_provider is null or i.provider_id = p_provider) group by 1) s),
    'escalation_due', (select count(*) from pipeline.scholarship_coverage_items i where i.present and (i.escalation->>'due')::boolean and (p_provider is null or i.provider_id = p_provider)),
    'providers', (select coalesce(jsonb_object_agg(s.provider_state, s.n), '{}'::jsonb) from (select c.provider_state, count(*) n from pipeline.scholarship_coverage_providers c
                   where p_provider is null or c.provider_id = p_provider group by 1) s),
    'recoveries', (select coalesce(jsonb_object_agg(s.k, s.n), '{}'::jsonb) from (select x.action || ':' || coalesce(x.outcome, 'pending') k, count(*) n
                    from pipeline.scholarship_coverage_recoveries x where p_provider is null or x.provider_id = p_provider group by 1) s),
    'detail', case when p_provider is not null then (select coalesce(jsonb_agg(jsonb_build_object('key', i.item_key, 'state', i.state, 'reason', i.reason, 'owner', i.owner,
                    'next_recovery_at', i.next_recovery_at, 'escalation', i.escalation, 'recovery', i.recovery, 'evidence', i.evidence) order by i.state, i.item_key), '[]'::jsonb)
                    from pipeline.scholarship_coverage_items i where i.provider_id = p_provider and i.present) end)
$$;


ALTER FUNCTION "security"."scholarship_coverage_report_v1"("p_provider" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_coverage_row_v1"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with m as (select * from security.scholarship_listing_match_v1(p_provider_id)),
  recs as (select s.id, s.publication_status, s.source_url from scholarship.scholarships s where s.provider_id = p_provider_id and s.lifecycle_status = 'active'),
  lp as (select * from pipeline.scholarship_listing_pages l where l.provider_id = p_provider_id and l.active),
  chk as (select c.* from pipeline.scholarship_coverage_checks c where c.provider_id = p_provider_id),
  h as (select md5(coalesce(string_agg(lower(item_name), '|' order by lower(item_name)), '')) v from m)
  select jsonb_build_object(
    'provider_id', p.id, 'name', coalesce(p.display_name, p.canonical_name), 'country', (select k.iso_alpha2 from ref.countries k where k.id = p.country_id),
    'watch', exists (select 1 from pipeline.scholarship_watch w where w.provider_id = p.id and w.active),
    'listing_pages', (select count(*) from lp where lp.source <> 'suggested'),
    'suggested_pages', (select count(*) from lp where lp.source = 'suggested'),
    'listing_read_at', (select max(lp.read_at) from lp where lp.source <> 'suggested'),
    'listed', (select count(*) from m),
    'found', (select count(*) from m where m.scholarship_id is not null),
    'published', (select count(*) from m join recs r on r.id = m.scholarship_id where r.publication_status = 'published'),
    'missing', (select count(*) from m where m.scholarship_id is null),
    'records', (select count(*) from recs),
    'records_published', (select count(*) from recs where publication_status = 'published'),
    'extra', (select count(*) from recs r where not exists (select 1 from m where m.scholarship_id = r.id)),
    'checked_at', (select checked_at from chk), 'checked_by', (select u.email from chk join auth.users u on u.id = chk.checked_by),
    'state', case when not exists (select 1 from lp where lp.source <> 'suggested') then 'no_listing'
                  when not exists (select 1 from lp where lp.status = 'read') then 'waiting'
                  when not exists (select 1 from chk) then 'to_check'
                  when (select item_hash from chk) is distinct from (select v from h) then 'changed'
                  else 'checked' end)
  from catalogue.providers p where p.id = p_provider_id
$$;


ALTER FUNCTION "security"."scholarship_coverage_row_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_coverage_v1"("p_providers" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("provider_id" "uuid", "country" "text", "provider_name" "text", "provider_type" "text", "disposition" "text", "measures" "jsonb", "categories" "jsonb", "gaps" "text"[], "shortfall" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 workstream C (P0 mandates 3 Nov 2026 15:37 §5, §12 and 15:52 §8): each active, published provider of a scholarship country (or only
  -- p_providers), what its sources list against what the catalogue holds. Anchors are independent of the discovery list: the national register,
  -- listing pages and their items, a stated total, listing members. Held records are also measured for the facts a student needs (funding type,
  -- value, application dates, study level, academic and residency requirements, country-specific eligibility). Read-only.
  with s as (select security.pipeline_num_v1('coverage.sch_represented_min_pct', 50) pct, security.pipeline_num_v1('coverage.sch_listing_min_items', 5) minl,
                    security.pipeline_num_v1('coverage.sch_category_min_items', 2) minc, security.pipeline_num_v1('coverage.sch_field_min_pct', 50) fpct,
                    coalesce(security.toolset_setting('pipeline', 'coverage.provider_level_types'), '[]'::jsonb) pl,
                    coalesce(security.toolset_setting('pipeline', 'coverage.sch_gap_fields'), '[]'::jsonb) gf,
                    coalesce(security.toolset_setting('pipeline', 'coverage.sch_not_applicable_types'), '[]'::jsonb) na),
  cat as (select k cat, v pat from security.coverage_kv_v1('coverage.sch_category_patterns')),
  lev as (select k cat, unnest(string_to_array(v, '|')) code from security.coverage_kv_v1('coverage.sch_category_levels')),
  pv as (select p.id, k.iso_alpha2::text cc, coalesce(p.display_name, p.short_name, p.canonical_name) nm, t.code ptype
           from catalogue.providers p join ref.countries k on k.id = p.country_id left join ref.provider_types t on t.id = p.provider_type_id
          where k.scholarship_ingestion_enabled and p.lifecycle_status = 'active' and p.publication_status = 'published'
            and (p_providers is null or p.id = any (p_providers))),
  lp as (select l.provider_id, count(*) pages, count(*) filter (where l.read_at is not null) pages_read,
                count(*) filter (where l.page_state = 'complete' or l.completed_at is not null) pages_complete, coalesce(max(l.total_stated), 0) stated,
                coalesce(sum(case when jsonb_typeof(l.items) = 'array' then jsonb_array_length(l.items) else 0 end), 0) items
           from pipeline.scholarship_listing_pages l join pv on pv.id = l.provider_id
          where l.active and l.source in ('manual', 'auto') and not security.third_party_host_v1(coalesce(l.url, '')) group by 1),
  -- every listed name with the anchor it came from: register (name and level; the register lists awards open to international students),
  -- listing items, listing members
  ln as (select r.provider_id, 'register' src, coalesce(r.name, '') || ' ' || coalesce(r.level_text, '') txt, true intl
           from scholarship.register_listings r join pv on pv.id = r.provider_id where r.departed_at is null
         union all
         select l.provider_id, 'listing', coalesce(i->>'name', ''), coalesce(i->>'name', '') ~* 'international'
           from pipeline.scholarship_listing_pages l join pv on pv.id = l.provider_id
           cross join lateral jsonb_array_elements(case when jsonb_typeof(l.items) = 'array' then l.items else '[]'::jsonb end) i
          where l.active and l.source in ('manual', 'auto') and not security.third_party_host_v1(coalesce(l.url, ''))
         union all
         select m.provider_id, 'member', coalesce(m.name, ''), coalesce(m.name, '') ~* 'international'
           from pipeline.scholarship_listing_members m join pv on pv.id = m.provider_id where m.present),
  lc as (select ln.provider_id, cat.cat, count(*) filter (where ln.txt ~* cat.pat) n from ln cross join cat group by 1, 2),
  li as (select ln.provider_id, count(*) filter (where ln.src = 'register') reg, count(*) filter (where ln.src = 'member') members,
                count(*) filter (where ln.intl) intl from ln group by 1),
  ru as (select r.provider_id, count(*) unmatched from scholarship.register_listings r join pv on pv.id = r.provider_id
          where r.departed_at is null and r.scholarship_id is null group by 1),
  ca as (select c.provider_id, count(*) n, count(*) filter (where c.admit_status is null and c.matched_scholarship_id is null) pending,
                count(*) filter (where c.admit_status = 'rejected') rejected,
                count(*) filter (where c.admitted_scholarship_id is not null or c.matched_scholarship_id is not null) linked
           from pipeline.scholarship_page_candidates c join pv on pv.id = c.provider_id group by 1),
  ar as (select x.provider_id, count(*) archived from scholarship.scholarships x join pv on pv.id = x.provider_id where x.lifecycle_status <> 'active' group by 1),
  sc as (select x.* from scholarship.scholarships x join pv on pv.id = x.provider_id where x.lifecycle_status = 'active'),
  sf as (select sc.id, sc.provider_id,
                sc.award_value_type is not null f_funding,
                (sc.award_amount is not null or sc.award_percentage is not null or nullif(btrim(coalesce(sc.award_value_text, '')), '') is not null
                 or exists (select 1 from scholarship.award_tiers a where a.scholarship_id = sc.id)) f_value,
                (sc.application_close_date is not null or sc.application_open_date is not null
                 or exists (select 1 from scholarship.application_windows w where w.scholarship_id = sc.id and (w.opens_at is not null or w.closes_at is not null))) f_dates,
                exists (select 1 from scholarship.scopes o where o.scholarship_id = sc.id and o.study_level_id is not null) f_level,
                exists (select 1 from scholarship.criteria c where c.scholarship_id = sc.id and c.criterion_type in ('academic_minimum', 'institution_admission')) f_academic,
                (sc.audience is not null and sc.audience <> 'not_stated'
                 or exists (select 1 from scholarship.criteria c where c.scholarship_id = sc.id and c.criterion_type in ('student_type', 'nationality', 'citizenship_and_residency',
                            'citizenship_residency_restriction', 'visa_requirement'))) f_residency,
                coalesce(cardinality(sc.nationalities), 0) > 0 f_country
           from sc),
  so as (select sc.provider_id, count(*) active, count(*) filter (where sc.publication_status = 'published') published,
                count(*) filter (where sc.publication_status <> 'published' or exists (select 1 from pipeline.scholarship_publication_holds h where h.scholarship_id = sc.id and h.released_at is null)) held,
                count(*) filter (where exists (select 1 from pipeline.layer4_review_items r where r.entity_type = 'scholarship' and r.entity_id = sc.id and r.status = 'pending')) layer4,
                count(*) filter (where sc.audience in ('international', 'international_and_domestic')) intl,
                count(*) filter (where sc.audience = 'domestic') domestic
           from sc group by 1),
  sfa as (select sf.provider_id, jsonb_build_object('funding_type', count(*) filter (where f_funding), 'value', count(*) filter (where f_value),
                   'application_dates', count(*) filter (where f_dates), 'study_level', count(*) filter (where f_level),
                   'academic_requirements', count(*) filter (where f_academic), 'residency_requirements', count(*) filter (where f_residency),
                   'country_eligibility', count(*) filter (where f_country)) f from sf group by 1),
  scc as (select sc.provider_id, cat.cat,
                 count(distinct sc.id) filter (where sc.name ~* cat.pat or exists (select 1 from scholarship.scopes o join ref.study_levels sl on sl.id = o.study_level_id
                                                                                    join lev on lev.code = sl.code and lev.cat = cat.cat
                                                                                   where o.scholarship_id = sc.id and o.include_exclude is distinct from 'exclude')) n
            from sc cross join cat group by 1, 2),
  d as (select pv.*, dp.status disc, dp.settle_reason, coalesce(lp.pages, 0) pages, coalesce(lp.pages_read, 0) pages_read, coalesce(lp.pages_complete, 0) pages_complete,
               coalesce(lp.stated, 0) stated, coalesce(lp.items, 0) items, coalesce(li.reg, 0) reg, coalesce(ru.unmatched, 0) reg_unmatched, coalesce(li.members, 0) members,
               coalesce(li.intl, 0) list_intl, coalesce(ca.n, 0) cands, coalesce(ca.pending, 0) cand_pending, coalesce(ca.rejected, 0) cand_rejected, coalesce(ca.linked, 0) cand_linked,
               coalesce(so.active, 0) active, coalesce(so.published, 0) published, coalesce(so.held, 0) held, coalesce(so.layer4, 0) layer4, coalesce(ar.archived, 0) archived,
               coalesce(so.intl, 0) sch_intl, coalesce(so.domestic, 0) domestic, coalesce(sfa.f, '{}'::jsonb) fields,
               coalesce((select jsonb_object_agg(lc.cat, lc.n) from lc where lc.provider_id = pv.id), '{}'::jsonb) list_cat,
               coalesce((select jsonb_object_agg(scc.cat, scc.n) from scc where scc.provider_id = pv.id), '{}'::jsonb) sch_cat,
               coalesce(pv.ptype, '') in (select jsonb_array_elements_text(s.pl)) plevel, coalesce(pv.ptype, '') in (select jsonb_array_elements_text(s.na)) na,
               security.scholarship_admission_provider_ok_v1(pv.id) admit_ok, s.gf, s.pct, s.minl, s.minc, s.fpct
          from pv cross join s left join pipeline.scholarship_discovery_providers dp on dp.provider_id = pv.id left join lp on lp.provider_id = pv.id
          left join li on li.provider_id = pv.id left join ru on ru.provider_id = pv.id left join ca on ca.provider_id = pv.id left join so on so.provider_id = pv.id
          left join ar on ar.provider_id = pv.id left join sfa on sfa.provider_id = pv.id),
  a as (select d.*, greatest(d.reg, d.items, d.stated, d.members) anchor from d),
  g as (select a.*, case
         -- never in scope (schools), or refused by the admission rule (non-university providers while the pilot does not cover them):
         -- recorded, with the policy as the only gap, never as missing data
         when a.na then '{}'::text[]
         when not a.admit_ok and not a.plevel then case when a.anchor > 0 then array['admission_policy'] else '{}'::text[] end
         -- CF-247 IQ-00216/IQ-00219 (4 Nov 2026): a TAFE, university college or wananga outside the admission rule is blocked by policy, not missing data
         when not a.admit_ok and coalesce(a.ptype, '') <> 'university' and security.pipeline_num_v1('sch_cov.policy_disposition_on', 0) >= 1 then array['admission_policy']
         else array_remove(array[
           case when a.active = 0 and (a.plevel or a.anchor > 0) then 'zero_scholarships' end,
           case when a.anchor >= a.minl and a.active * 100 < a.pct * a.anchor then 'under_represented' end,
           case when (a.plevel or a.anchor > 0) and (a.disc is null or a.disc = 'not_eligible') then 'not_searched' end,
           case when a.pages > 0 and a.pages_complete = 0 then 'listing_partial' end,
           case when a.items > 0 and a.members = 0 then 'listing_not_fanned_out' end,
           case when a.list_intl >= a.minc and a.sch_intl = 0 then 'category_missing:international' end]
           || coalesce(array(select 'category_missing:' || e.key from jsonb_each_text(a.list_cat) e
                              where e.value::int >= a.minc and coalesce((a.sch_cat->>e.key)::int, 0) = 0 order by e.key), '{}')
           -- a fact a student needs, held for too few of the provider's scholarships (only once it holds enough to judge)
           || coalesce(array(select 'fields_incomplete:' || e.key from jsonb_each_text(a.fields) e
                              where a.active >= a.minc and a.gf ? e.key and e.value::int * 100 < a.fpct * a.active order by e.key), '{}'), null) end gaps
          from a)
  select g.id, g.cc, g.nm, g.ptype,
         case when g.na then 'not_applicable'
              when 'admission_policy' = any (g.gaps) then 'blocked_policy'
              when 'zero_scholarships' = any (g.gaps) then 'zero'
              when 'under_represented' = any (g.gaps) then 'under_represented'
              when exists (select 1 from unnest(g.gaps) x where x like 'category_missing:%') then 'category_gap'
              when 'not_searched' = any (g.gaps) then 'not_searched'
              when exists (select 1 from unnest(g.gaps) x where x like 'fields_incomplete:%') then 'fields_incomplete'
              when cardinality(g.gaps) > 0 then 'partial_listing'
              when g.anchor > 0 then 'represented'
              when g.active > 0 then 'records_without_listing'
              else 'no_evidence' end,
         jsonb_build_object('discovery', g.disc, 'discovery_reason', g.settle_reason, 'listing_pages', g.pages, 'listing_pages_read', g.pages_read,
           'listing_pages_complete', g.pages_complete, 'listing_items', g.items, 'listing_stated', g.stated, 'listing_members', g.members,
           'register', g.reg, 'register_unmatched', g.reg_unmatched, 'anchor', g.anchor, 'candidates', g.cands, 'candidates_pending', g.cand_pending,
           'candidates_rejected', g.cand_rejected, 'candidates_linked', g.cand_linked, 'admitted', g.active, 'published', g.published, 'held', g.held,
           'layer4_pending', g.layer4, 'archived', g.archived, 'international', g.sch_intl, 'domestic_only', g.domestic, 'fields', g.fields, 'provider_level', g.plevel,
           'admission_ok', g.admit_ok),
         jsonb_build_object('listed', g.list_cat || jsonb_build_object('international', g.list_intl), 'held', g.sch_cat || jsonb_build_object('international', g.sch_intl)),
         g.gaps, greatest(0, g.anchor - g.active)::int
    from g
$$;


ALTER FUNCTION "security"."scholarship_coverage_v1"("p_providers" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_coverage_v1"("p_providers" "uuid"[]) IS 'CF-247 workstream C (P0 mandates 3 Nov 2026 §5/§12 and §8): per active scholarship-country provider (or the providers given), listing and register anchors against candidates, admitted, published, held, Layer 4 and archived scholarships, by category (coverage.sch_category_levels, coverage.sch_category_patterns) and by the facts held (funding type, value, dates, study level, academic and residency requirements, country eligibility), with gaps and a disposition. Read-only.';



CREATE OR REPLACE FUNCTION "security"."scholarship_coverage_verify_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247: the issue's providers have no unresolved recoverable case (rejected incorrectly, traversal incomplete, found but unread) and none due to escalate
  with pv as (select unnest(i.provider_ids) id from pipeline.integration_issues i where i.id = p_issue),
  m as (select count(*) filter (where c.state in ('rejected_incorrectly', 'traversal_incomplete', 'source_found_unread')) recoverable,
               count(*) filter (where (c.escalation->>'due')::boolean) due, count(*) filter (where c.state = 'published_verified') published
          from pipeline.scholarship_coverage_items c join pv on pv.id = c.provider_id where c.present)
  select jsonb_build_object('passed', m.recoverable = 0 and m.due = 0, 'measure', to_jsonb(m), 'evidence', 'pipeline.scholarship_coverage_items (security.scholarship_coverage_report_v1)') from m
$$;


ALTER FUNCTION "security"."scholarship_coverage_verify_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_criteria_apply_v1"("p_scholarship_id" "uuid") RETURNS "text"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare pg record; s record; v_src uuid; v_new jsonb; v_old jsonb; v_changes text[] := '{}'; v_dur text; n int;
begin
  select * into pg from pipeline.scholarship_pages where scholarship_id = p_scholarship_id;
  select * into s from scholarship.scholarships where id = p_scholarship_id;
  if s.id is null or pg.read_status is distinct from 'read' or pg.facts is null or not (pg.facts ? 'criteria') then return v_changes; end if;
  v_src := security.coverage_sweep_source(s.provider_id);

  -- the reader's criteria, in a fixed order, compared with the sweep's active rows
  select coalesce(jsonb_agg(x order by x->>'type', x->>'value_text', x->>'value_codes'), '[]') into v_new
    from (select jsonb_build_object('type', c->>'type', 'operator', c->>'operator', 'value_text', c->>'value_text',
                 'value_number', (c->>'value_number')::numeric, 'value_codes', c->'value_codes', 'scale', (c->>'scale')::numeric) x
            from jsonb_array_elements(case when jsonb_typeof(pg.facts->'criteria') = 'array' then pg.facts->'criteria' else '[]' end) c
           where c->>'type' in ('student_type','study_stage','study_load','academic_minimum','gender','nationality','application_method')) q;
  select coalesce(jsonb_agg(x order by x->>'type', x->>'value_text', x->>'value_codes'), '[]') into v_old
    from (select jsonb_build_object('type', cr.criterion_type, 'operator', cr.operator, 'value_text', cr.value_text,
                 'value_number', cr.value_number, 'value_codes', to_jsonb(cr.value_codes), 'scale', (cr.value_json->>'scale')::numeric) x
            from scholarship.criteria cr
           where cr.scholarship_id = s.id and cr.status = 'active' and cr.value_json->>'by' = 'scholarship_sweep') q;
  if v_new is distinct from v_old then
    update scholarship.criteria set status = 'superseded'
     where scholarship_id = s.id and status = 'active' and value_json->>'by' = 'scholarship_sweep';
    insert into scholarship.criteria(scholarship_id, criterion_type, operator, value_text, value_number, value_codes, value_json,
                                     human_text, is_mandatory, machine_evaluable, status, source_id, evidence_id, confidence)
    select s.id, c->>'type', c->>'operator', c->>'value_text', (c->>'value_number')::numeric,
           case when jsonb_typeof(c->'value_codes') = 'array' then array(select jsonb_array_elements_text(c->'value_codes')) end,
           jsonb_strip_nulls(jsonb_build_object('by', 'scholarship_sweep', 'extractor', coalesce(pg.facts->>'criteria_extractor', pg.facts->>'extractor'), 'scale', (c->>'scale')::numeric)),
           left(c->>'text', 300), true, c->>'type' <> 'application_method', 'active', v_src, pg.evidence_id, 0.7
      from jsonb_array_elements(case when jsonb_typeof(pg.facts->'criteria') = 'array' then pg.facts->'criteria' else '[]' end) c
     where c->>'type' in ('student_type','study_stage','study_load','academic_minimum','gender','nationality','application_method');
    get diagnostics n = row_count;
    insert into pipeline.scholarship_sweep_changes(scholarship_id, field, before_value, after_value, evidence_id)
    values (s.id, 'criteria', v_old, v_new, pg.evidence_id);
    v_changes := v_changes || 'criteria'::text;
  end if;

  -- award duration, only where the record has none (values entered by hand or by other sources stay)
  v_dur := pg.facts->'award_scope'->>'duration';
  if s.award_duration_basis is null and v_dur in ('one_off','first_year','annual','annual_program_duration','program_duration','per_semester') then
    begin
      update scholarship.scholarships set award_duration_basis = v_dur, updated_at = now() where id = s.id;
      insert into pipeline.scholarship_sweep_changes(scholarship_id, field, before_value, after_value, evidence_id)
      values (s.id, 'award_duration_basis', null, pg.facts->'award_scope', pg.evidence_id);
      v_changes := v_changes || 'award_duration'::text;
    exception when others then null; -- a value locked by hand is left as it is
    end;
  end if;
  -- Decision 212: one stated maximum ("up to $5,000", "up to 50%") is recorded as a maximum, only where the record has no value
  declare v_val jsonb := pg.facts->'value'; na int; np int; amt numeric; pct numeric;
  begin
    if not (s.award_value_type in ('percentage','fixed_amount') and coalesce(s.award_percentage, s.award_amount) is not null)
       and v_val->>'type' = 'ambiguous' and coalesce((v_val->>'up_to')::boolean, false) and not coalesce((v_val->>'foreign_currency')::boolean, false) then
      na := jsonb_array_length(case when jsonb_typeof(v_val->'amounts') = 'array' then v_val->'amounts' else '[]' end);
      np := jsonb_array_length(case when jsonb_typeof(v_val->'percentages') = 'array' then v_val->'percentages' else '[]' end);
      amt := case when na = 1 and np = 0 then (v_val->'amounts'->>0)::numeric end;
      pct := case when np = 1 and na = 0 then (v_val->'percentages'->>0)::numeric end;
      if amt between 500 and 200000 then
        update scholarship.scholarships set award_value_type = 'fixed_amount', award_amount = amt, award_currency_code = scholarship.provider_currency(s.provider_id), award_value_is_maximum = true,
               award_value_text = coalesce(award_value_text, 'Up to ' || scholarship.money_prefix(scholarship.provider_currency(s.provider_id)) || to_char(amt, 'FM999,999,999')), evidence_id = pg.evidence_id, updated_at = now()
         where id = s.id;
      elsif pct between 5 and 100 then
        update scholarship.scholarships set award_value_type = 'percentage', award_percentage = pct, award_value_is_maximum = true,
               award_applies_to_fee_type = case when coalesce(pg.facts->'award_scope'->'applies_to', '[]') ? 'tuition_fee' then coalesce(award_applies_to_fee_type, 'tuition_fee') else award_applies_to_fee_type end,
               award_value_text = coalesce(award_value_text, 'Up to ' || pct::text || '%' || case when coalesce(pg.facts->'award_scope'->'applies_to', '[]') ? 'tuition_fee' then ' of tuition fees' else '' end),
               evidence_id = pg.evidence_id, updated_at = now()
         where id = s.id;
      end if;
      if amt between 500 and 200000 or pct between 5 and 100 then
        insert into pipeline.scholarship_sweep_changes(scholarship_id, field, before_value, after_value, evidence_id)
        values (s.id, 'award_value_maximum', jsonb_build_object('type', s.award_value_type, 'text', s.award_value_text), v_val, pg.evidence_id);
        v_changes := v_changes || 'award_value_maximum'::text;
      end if;
    end if;
  exception when others then null; -- a value locked by hand is left as it is
  end;

  return v_changes;
end $_$;


ALTER FUNCTION "security"."scholarship_criteria_apply_v1"("p_scholarship_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_detail_apply_v1"("p_extraction" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare e pipeline.scholarship_ai_extractions%rowtype; s scholarship.scholarships%rowtype; d jsonb; c jsonb; v_sid uuid; v_src uuid; v_home text;
        v_done text[] := '{}'; v_codes text[]; v_ex text[]; v_grp uuid; n int;
begin
  select * into e from pipeline.scholarship_ai_extractions where id = p_extraction;
  if e.id is null or e.error is not null or coalesce(e.prompt_version, 0) < 3 or jsonb_typeof(e.answer->'detail') <> 'object' or jsonb_typeof(e.checks->'detail') <> 'object' then
    return jsonb_build_object('applied', false, 'reason', 'no version 3 detail');
  end if;
  if security.pipeline_num_v1('sch_detail.on', 1) < 1 then return jsonb_build_object('applied', false, 'reason', 'sch_detail.on is off'); end if;
  v_sid := coalesce(e.scholarship_id, (select coalesce(pc.admitted_scholarship_id, pc.matched_scholarship_id) from pipeline.scholarship_page_candidates pc where pc.id = e.candidate_id));
  select * into s from scholarship.scholarships where id = v_sid;
  if s.id is null or s.lifecycle_status <> 'active' then return jsonb_build_object('applied', false, 'reason', 'no active scholarship'); end if;
  -- identity: the extraction must be this scholarship's own provider's evidence and name this scholarship
  if e.provider_id is distinct from s.provider_id then return jsonb_build_object('applied', false, 'reason', 'provider differs'); end if;
  if not coalesce((e.checks->>'name')::boolean, false) or e.verdict is distinct from 'scholarship' then return jsonb_build_object('applied', false, 'reason', 'scholarship not identified on the evidence'); end if;
  d := e.answer->'detail'; c := e.checks->'detail'; v_src := security.coverage_sweep_source(s.provider_id); v_home := security.coverage_country(s.provider_id);

  -- description (consumer description; only where none of use is held)
  -- 20261113066000: no description for a placeholder award (a fixed amount under the floor; fixed: a scholarship of less than 50 in any currency is a page placeholder)
  if coalesce((c->'summary'->>'ok')::boolean, false) and length(coalesce(s.description, '')) < 80
     and not (s.award_value_type = 'fixed_amount' and s.award_amount < 50)
     and not exists (select 1 from pipeline.manual_locks k where k.entity = 'scholarship' and k.entity_id = s.id and k.field = 'description') then
    begin
      update scholarship.scholarships set description = left(d->>'summary', 900), updated_at = now() where id = s.id;
      insert into pipeline.scholarship_sweep_changes(scholarship_id, field, before_value, after_value, evidence_id)
      values (s.id, 'description', to_jsonb(s.description), jsonb_build_object('by', 'sch-extract-v3', 'extraction', e.id, 'text', left(d->>'summary', 900)), e.evidence_id);
      v_done := v_done || 'description'::text;
    exception when others then null; -- a value locked by hand is left as it is
    end;
  end if;
  -- payment basis
  if coalesce((c->>'payment')::boolean, false) and s.award_duration_basis is null
     and d->>'payment_basis' in ('one_off', 'first_year', 'annual', 'annual_program_duration', 'program_duration', 'per_semester') then
    begin
      update scholarship.scholarships set award_duration_basis = d->>'payment_basis', updated_at = now() where id = s.id;
      insert into pipeline.scholarship_sweep_changes(scholarship_id, field, before_value, after_value, evidence_id)
      values (s.id, 'award_duration_basis', null, jsonb_build_object('by', 'sch-extract-v3', 'extraction', e.id, 'value', d->>'payment_basis', 'quote', left(d->>'payment_quote', 600)), e.evidence_id);
      v_done := v_done || 'award_duration_basis'::text;
    exception when others then null;
    end;
  end if;
  -- application method: application_required, automatic consideration (criterion), and the application window record
  if coalesce((c->'application'->>'method')::boolean, false) then
    if s.application_required is null and d->'application'->>'method' in ('separate_application', 'automatic_consideration') then
      begin
        update scholarship.scholarships set application_required = (d->'application'->>'method' = 'separate_application'), updated_at = now() where id = s.id;
        v_done := v_done || 'application_required'::text;
      exception when others then null;
      end;
    end if;
    if d->'application'->>'method' = 'automatic_consideration'
       and not exists (select 1 from scholarship.criteria cr where cr.scholarship_id = s.id and cr.status = 'active' and cr.criterion_type = 'application_method') then
      insert into scholarship.criteria(scholarship_id, criterion_type, operator, value_text, value_json, human_text, is_mandatory, machine_evaluable, status, source_id, evidence_id, confidence)
      values (s.id, 'application_method', 'equals', 'automatic', jsonb_build_object('by', 'sch-extract-v3', 'extraction', e.id), left(d->'application'->>'quote', 300), true, false, 'active', v_src, e.evidence_id, 0.6);
      v_done := v_done || 'automatic_consideration'::text;
    end if;
    if not exists (select 1 from scholarship.application_windows w where w.scholarship_id = s.id) then
      insert into scholarship.application_windows(scholarship_id, label, opens_at, closes_at, application_method, application_url, status, source_id, evidence_id, metadata)
      values (s.id, 'Published application', s.application_open_date, s.application_close_date, d->'application'->>'method', c->'application'->>'url', 'unknown', v_src, e.evidence_id,
              jsonb_build_object('by', 'sch-extract-v3', 'extraction', e.id, 'quote', left(d->'application'->>'quote', 600), 'rolling', c->'application'->'rolling'));
      v_done := v_done || 'application_window'::text;
    end if;
  end if;
  -- award duration (internal coverage record; not read by the consumer API)
  if coalesce((c->>'duration')::boolean, false) and not exists (select 1 from scholarship.coverage cv where cv.scholarship_id = s.id and cv.coverage_type = 'award_duration') then
    insert into scholarship.coverage(scholarship_id, coverage_type, duration_value, duration_unit, notes, source_id, evidence_id)
    values (s.id, 'award_duration', case when jsonb_typeof(d->'duration'->'value') = 'number' then (d->'duration'->>'value')::numeric end, d->'duration'->>'unit',
            left('renewable: ' || coalesce(d->'duration'->>'renewable', 'not_stated') || '; ' || coalesce(d->'duration'->>'quote', ''), 600), v_src, e.evidence_id);
    v_done := v_done || 'duration'::text;
  end if;
  -- nationality: the verified codes (the provider's own country left out, as the nationality reader does) as a criterion the reader unions in
  -- 20261113066000: only a passage that states citizenship, nationality, residence, origin or students from a country (not a testimonial or alumni line)
  if coalesce((c->'nationality'->>'proven')::boolean, false)
     and coalesce(d->'nationality'->>'quote', '') ~* '(citizen|nationals?\M|nationality|passport|residen|descent|origin|born in|(students?|applicants?|candidates?|people|those) (from|of)\M|eligible countr|following countr)'
     and coalesce(d->'nationality'->>'quote', '') !~* '(\mI am\M|\mI''m\M|awardee|alumn)'
     and not exists (select 1 from pipeline.manual_locks k where k.entity = 'scholarship' and k.entity_id = s.id and k.field = 'nationalities') then
    v_codes := array(select x from jsonb_array_elements_text(c->'nationality'->'eligible') x where x <> coalesce(v_home, 'AU') and not (x in ('AU', 'NZ') and coalesce(v_home, 'AU') in ('AU', 'NZ')) order by x);
    v_ex := array(select x from jsonb_array_elements_text(c->'nationality'->'excluded') x order by x);
    if (cardinality(v_codes) > 0 or cardinality(v_ex) > 0) and not exists (select 1 from scholarship.criteria cr where cr.scholarship_id = s.id and cr.status = 'active' and cr.criterion_type = 'nationality'
                and cr.value_json->>'by' = 'sch-extract-v3' and cr.value_codes is not distinct from v_codes and cr.value_json->'excluded' is not distinct from to_jsonb(v_ex)) then
      update scholarship.criteria set status = 'superseded' where scholarship_id = s.id and status = 'active' and criterion_type = 'nationality' and value_json->>'by' = 'sch-extract-v3';
      insert into scholarship.criteria(scholarship_id, criterion_type, operator, value_codes, value_json, human_text, is_mandatory, machine_evaluable, status, source_id, evidence_id, confidence)
      values (s.id, 'nationality', 'in', v_codes, jsonb_build_object('by', 'sch-extract-v3', 'extraction', e.id, 'role', 'eligible', 'excluded', to_jsonb(v_ex), 'regions', c->'nationality'->'regions'),
              left(d->'nationality'->>'quote', 300), true, cardinality(v_codes) > 0, 'active', v_src, e.evidence_id, 0.8);
      v_done := v_done || 'nationality'::text;
    end if;
  end if;
  -- eligibility conditions: the published passages, kept with their AND/OR group
  -- held (20261113063000): a passage listing who is not eligible, or a site-wide line, must not read as this scholarship's condition
  if false and jsonb_array_length(coalesce(c->'criteria', '[]')) > 0
     and not exists (select 1 from scholarship.criteria cr where cr.scholarship_id = s.id and cr.status = 'active' and cr.value_json->>'by' = 'sch-extract-v3' and cr.criterion_type <> 'nationality' and cr.criterion_type <> 'application_method') then
    if c->>'criteria_conjunction' in ('all', 'any') then
      insert into scholarship.criterion_groups(scholarship_id, group_code, label, conjunction, is_mandatory, source_id, evidence_id)
      values (s.id, 'sch-extract-v3:' || e.id, 'Published eligibility', c->>'criteria_conjunction', true, v_src, e.evidence_id) returning id into v_grp;
    end if;
    insert into scholarship.criteria(scholarship_id, criterion_type, operator, value_text, value_json, human_text, is_mandatory, machine_evaluable, status, source_id, evidence_id, confidence, criterion_group_id)
    select s.id, y.t, 'source_text', left(y.x->>'text', 300), jsonb_build_object('by', 'sch-extract-v3', 'extraction', e.id, 'kind', y.x->>'kind', 'source', y.x->>'source'),
           left(y.x->>'quote', 300), true, false, 'active', v_src, e.evidence_id, 0.5, v_grp
      -- every condition is kept as published wording (narrative, with its kind in value_json); the consumer API's structured study load, stage and
      -- academic minimum stay with their existing readers, whose canonical values a free-text condition must not mix with
      from (select x, 'published_eligibility_narrative'::text t
              from jsonb_array_elements(c->'criteria') x
             where x->>'kind' <> 'student_type') y  -- who may apply stays with the audience rule and the eligibility reader
     -- a record that already holds a published narrative keeps it
     where not exists (select 1 from scholarship.criteria cr where cr.scholarship_id = s.id and cr.status = 'active' and cr.criterion_type = y.t);
    get diagnostics n = row_count;
    if n > 0 then v_done := v_done || 'criteria'::text; end if;
  end if;
  v_done := v_done || security.scholarship_detail_extend_v1(e.id, s.id);  -- 20261113068000: award type, sponsor, rolling, benefits
  v_done := v_done || security.scholarship_value_from_benefits_v1(s.id);  -- 20261113335000: an empty stated value from the verified benefits
  if cardinality(v_done) > 0 then
    insert into pipeline.scholarship_sweep_changes(scholarship_id, field, before_value, after_value, evidence_id)
    values (s.id, 'detail_fill', null, jsonb_build_object('by', 'sch-extract-v3', 'extraction', e.id, 'fields', to_jsonb(v_done), 'sources', c->'sources'), e.evidence_id);
  end if;
  return jsonb_build_object('applied', cardinality(v_done) > 0, 'scholarship_id', s.id, 'fields', to_jsonb(v_done));
end $$;


ALTER FUNCTION "security"."scholarship_detail_apply_v1"("p_extraction" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_detail_apply_v1"("p_extraction" bigint) IS 'F-SCH redesign 12 Nov 2026: fills empty canonical scholarship fields from a version 3 extraction whose passages were checked against the official evidence (worker sch-extract.ts); never a locked or filled field; logged in pipeline.scholarship_sweep_changes.';



CREATE OR REPLACE FUNCTION "security"."scholarship_detail_backfill_v1"("p_limit" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a record; n int;
begin
  if security.pipeline_num_v1('sch_detail.on', 1) < 1 or coalesce(p_limit, 0) < 1 then return 0; end if;
  select * into a from security.scholarship_ai_active_v1();
  if a.model_code is null or coalesce(a.prompt_version, 0) < 3 then return 0; end if;
  insert into pipeline.scholarship_ai_queue(model_code, prompt_version, run_kind, scholarship_id, provider_id, url, storage_path)
  select a.model_code, a.prompt_version, 'detail', s.id, s.provider_id, coalesce(sp.final_url, sp.url, s.source_url), ev.storage_path
    from scholarship.scholarships s
    join pipeline.scholarship_pages sp on sp.scholarship_id = s.id
    join lateral (select x.storage_path from pipeline.evidence_artifacts x where x.id in (sp.evidence_id, s.evidence_id) and x.storage_path is not null order by (x.id = sp.evidence_id) desc limit 1) ev on true
   where s.lifecycle_status = 'active'
     and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = s.provider_id)
     and not security.third_party_host_v1(coalesce(sp.final_url, sp.url, s.source_url))
     and not exists (select 1 from pipeline.scholarship_ai_extractions x where x.scholarship_id = s.id and x.prompt_version >= 3 and x.error is null)
     and not exists (select 1 from pipeline.scholarship_ai_queue q where q.scholarship_id = s.id and (q.state in ('queued', 'leased') or (q.run_kind = 'detail' and q.prompt_version >= 3)))
   order by (s.publication_status = 'published') desc, s.updated_at desc
   limit p_limit;
  get diagnostics n = row_count;
  -- 20261113294100: long-page recovery items within the same limit
  n := n + security.scholarship_detail_recovery_queue_v1(greatest(p_limit - n, 0));
  return n;
end $$;


ALTER FUNCTION "security"."scholarship_detail_backfill_v1"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_detail_backfill_v1"("p_limit" integer) IS 'F-SCH redesign 12 Nov 2026: queues active scholarships with a stored official page and no version 3 extraction for one detail-only read (published first), when the AI reader is idle.';



CREATE OR REPLACE FUNCTION "security"."scholarship_detail_extend_v1"("p_extraction" bigint, "p_scholarship" "uuid") RETURNS "text"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare e pipeline.scholarship_ai_extractions%rowtype; d jsonb; c jsonb; v_done text[] := '{}'; v_src uuid; n int; v_pid uuid;
begin
  select * into e from pipeline.scholarship_ai_extractions where id = p_extraction;
  if e.id is null or e.error is not null or coalesce(e.prompt_version, 0) < 3 or jsonb_typeof(e.answer->'detail') <> 'object' or jsonb_typeof(e.checks->'detail') <> 'object' then return v_done; end if;
  select provider_id into v_pid from scholarship.scholarships where id = p_scholarship and lifecycle_status = 'active';
  if v_pid is null or v_pid is distinct from e.provider_id or not coalesce((e.checks->>'name')::boolean, false) or e.verdict is distinct from 'scholarship' then return v_done; end if;
  d := e.answer->'detail'; c := e.checks->'detail'; v_src := security.coverage_sweep_source(v_pid);
  insert into scholarship.award_details(scholarship_id, extraction_id, evidence_id) values (p_scholarship, e.id, e.evidence_id) on conflict (scholarship_id) do nothing;
  if coalesce((c->>'award_type')::boolean, false) and d->>'award_type' in ('scholarship','bursary','tuition_waiver','fee_discount','research_funding','grant','stipend','other') then
    update scholarship.award_details set award_type = d->>'award_type', extraction_id = e.id, evidence_id = coalesce(e.evidence_id, evidence_id), updated_at = now() where scholarship_id = p_scholarship and award_type is null;
    get diagnostics n = row_count; if n > 0 then v_done := v_done || 'award_type'::text; end if;
  end if;
  if coalesce((c->>'identity')::boolean, false) then
    update scholarship.award_details set sponsor = coalesce(sponsor, left(nullif(btrim(d->>'sponsor'), ''), 200)), programme = coalesce(programme, left(nullif(btrim(d->>'programme'), ''), 200)),
           award_code = coalesce(award_code, left(nullif(btrim(d->>'award_code'), ''), 60)), updated_at = now()
     where scholarship_id = p_scholarship and (sponsor is null or programme is null or award_code is null);
    get diagnostics n = row_count; if n > 0 then v_done := v_done || 'identity'::text; end if;
  end if;
  if jsonb_typeof(c->'application'->'rolling') = 'boolean' then
    update scholarship.award_details set application_rolling = (c->'application'->>'rolling')::boolean, updated_at = now() where scholarship_id = p_scholarship and application_rolling is null;
    get diagnostics n = row_count; if n > 0 then v_done := v_done || 'rolling'::text; end if;
  end if;
  -- verified benefits, once per scholarship from this reader
  if jsonb_array_length(coalesce(c->'benefits', '[]')) > 0
     and not exists (select 1 from scholarship.coverage cv where cv.scholarship_id = p_scholarship and cv.notes like 'sch-extract-v3:%') then
    insert into scholarship.coverage(scholarship_id, coverage_type, percentage, amount, currency_code, notes, source_id, evidence_id)
    select p_scholarship,
           case b->>'kind' when 'tuition_percentage' then 'tuition_fees' when 'tuition_amount' then 'tuition_fees' when 'full_tuition' then 'tuition_fees'
                           when 'living_allowance' then 'living_expenses' when 'health_cover' then 'overseas_student_health_cover' when 'travel' then 'travel'
                           when 'accommodation' then 'accommodation' when 'stipend' then 'stipend' when 'fixed_amount' then 'fixed_amount' when 'in_kind' then 'in_kind' else 'other' end,
           case when b->>'kind' = 'full_tuition' then 100 when jsonb_typeof(b->'percentage') = 'number' then (b->>'percentage')::numeric end,
           case when jsonb_typeof(b->'amount') = 'number' and (b->>'amount')::numeric >= 50 then (b->>'amount')::numeric end,  -- fixed: under 50 is a page placeholder (20261113066000)
           (select r.code from ref.currencies r where r.code = b->>'currency'),
           left('sch-extract-v3:' || e.id || (case when coalesce((b->>'maximum')::boolean, false) then ' (maximum)' else '' end) || ' ' || coalesce(b->>'quote', ''), 600),
           v_src, e.evidence_id
      from jsonb_array_elements(c->'benefits') b;
    get diagnostics n = row_count; if n > 0 then v_done := v_done || 'benefits'::text; end if;
  end if;
  return v_done;
end $$;


ALTER FUNCTION "security"."scholarship_detail_extend_v1"("p_extraction" bigint, "p_scholarship" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_detail_extend_v1"("p_extraction" bigint, "p_scholarship" "uuid") IS 'F-SCH redesign (12 Nov 2026): writes verified award type, sponsor, programme, award code, rolling applications (scholarship.award_details) and benefits (scholarship.coverage) from a version 3 extraction; empty fields only.';



CREATE OR REPLACE FUNCTION "security"."scholarship_detail_recovery_queue_v1"("p_limit" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a record; n int;
begin
  if security.pipeline_num_v1('sch_detail.recovery_on', 1) < 1 or coalesce(p_limit, 0) < 1 then return 0; end if;
  select * into a from security.scholarship_ai_active_v1();
  if a.model_code is null or coalesce(a.prompt_version, 0) < 3 then return 0; end if;
  insert into pipeline.scholarship_ai_queue(model_code, prompt_version, run_kind, scholarship_id, provider_id, url, storage_path, recovery)
  select a.model_code, a.prompt_version, 'detail', s.id, s.provider_id, coalesce(sp.final_url, sp.url, s.source_url), ev.storage_path, 'sectioned-v1'
    from scholarship.scholarships s
    join pipeline.scholarship_pages sp on sp.scholarship_id = s.id
    join lateral (select x.storage_path from pipeline.evidence_artifacts x where x.id in (sp.evidence_id, s.evidence_id) and x.storage_path is not null order by (x.id = sp.evidence_id) desc limit 1) ev on true
   where s.lifecycle_status = 'active'
     and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = s.provider_id)
     and not security.third_party_host_v1(coalesce(sp.final_url, sp.url, s.source_url))
     and not exists (select 1 from pipeline.scholarship_ai_extractions x where x.scholarship_id = s.id and x.prompt_version >= 3 and x.error is null)
     and exists (select 1 from pipeline.scholarship_ai_extractions x where x.scholarship_id = s.id and x.prompt_version >= 3
                  and (x.error like 'held_partial: output_truncated%' or x.error like 'no_answer%' or x.error like 'unreadable_answer%'))
     and not exists (select 1 from pipeline.scholarship_ai_queue q where q.scholarship_id = s.id and (q.state in ('queued', 'leased') or q.recovery is not null))
   order by (s.publication_status = 'published') desc, s.updated_at desc
   limit p_limit;
  get diagnostics n = row_count;
  return n;
end $$;


ALTER FUNCTION "security"."scholarship_detail_recovery_queue_v1"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_detail_recovery_queue_v1"("p_limit" integer) IS 'F-SCH long-page recovery: one sectioned-v1 detail item per active scholarship whose version 3 readings were all cut, empty or unreadable; at most once.';



CREATE OR REPLACE FUNCTION "security"."scholarship_discovery_hold_reason_v1"("p_provider" "uuid", "p_website" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 workstream C: the standing reasons public.svc_scholarship_discover_next refuses a provider (its holds, without the credit cap, which
  -- passes by itself); null when discovery can take it. Eligibility is enforced only while the Firecrawl daily budget is on, as in the picker.
  select case
    when exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p_provider) then 'unpublished'
    when security.provider_sch_search_off_v1(p_provider) then 'search_off'
    when security.third_party_host_v1(coalesce(p_website, '')) then 'directory_site'
    when coalesce((select (s.value #>> '{}')::boolean from pipeline.platform_toolset_settings s where s.toolset_key = 'firecrawl' and s.key = 'daily_budget_on'), false)
         and not security.fc_sch_eligible_v1(p_provider) then 'not_eligible' end
$$;


ALTER FUNCTION "security"."scholarship_discovery_hold_reason_v1"("p_provider" "uuid", "p_website" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_discovery_hold_reason_v1"("p_provider" "uuid", "p_website" "text") IS 'CF-247 workstream C: why scholarship discovery can never take this provider now (unpublished, search_off, directory_site, not_eligible), or null. The picker''s holds without the credit cap. Read-only.';



CREATE OR REPLACE FUNCTION "security"."scholarship_discovery_refill_v1"("p_keep" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_pri text[] := security.pipeline_list_v1('scholarship.refill_priority_countries', '["AU"]'); v_open text[] := security.pipeline_list_v1('scholarship.refill_open_countries', '["AU"]');
        v_pending int; v_added int := 0; v_tier int; v_due int; v_skip int; v_round int; v_pilot jsonb;
begin
  perform security.provider_sch_search_auto_v1();  -- v2.15.271: directory-only providers switched Off
  select count(*) into v_pending from pipeline.scholarship_discovery_providers where status in ('pending', 'deferred');
  if v_pending < p_keep then
    insert into pipeline.scholarship_discovery_providers(provider_id, website, priority, reason, status)
    select q.provider_id, q.website, case when q.cc = any (v_pri) then security.pipeline_num_v1('scholarship.refill_priority_focus', 4)::int else security.pipeline_num_v1('scholarship.refill_priority_other', 1)::int end,
           case when q.cc = any (v_pri) then 'largest_unsearched' else 'university_' || lower(q.cc) end, 'pending'  -- CF-247 3 Nov 2026 (direction 09:32 §7): countries and priorities are settings
      from (select p.id provider_id, k.iso_alpha2 cc,
                   coalesce(nullif(btrim(p.website), ''), (select nullif(btrim(d.website), '') from pipeline.coverage_provider_discovery d where d.provider_id = p.id and d.status = 'mapped')) website,
                   count(co.id) n
              from catalogue.providers p join ref.countries k on k.id = p.country_id
              left join catalogue.courses co on co.provider_id = p.id and co.lifecycle_status = 'active'
             where k.scholarship_ingestion_enabled and (co.id is not null or security.scholarship_university(p.id))  -- F-SCH 13 Nov 2026: classified universities without courses
               -- CF-247 scholarship recovery P1 (proposed, off): with non-university admission on, governed non-university providers overseas too
               and (k.iso_alpha2 = any (v_open) or security.scholarship_admission_provider_ok_v1(p.id))
               and not exists (select 1 from pipeline.scholarship_discovery_providers d where d.provider_id = p.id)
             group by p.id, p.website, k.iso_alpha2) q
     where q.website is not null
       -- v2.15.265: qualifying providers only, never a directory site; top-50, Australian 30+, overseas
       and security.fc_sch_eligible_v1(q.provider_id) and not security.third_party_host_v1(q.website)
       and not security.provider_sch_search_off_v1(q.provider_id)  -- v2.15.271
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = q.provider_id)  -- 22 Oct 2026 (Platform Admin 11:42): unpublished providers wait; publishing them again brings them back
     order by security.fc_provider_tier_v1(q.provider_id), q.n desc, q.provider_id limit greatest(0, p_keep - v_pending)
    on conflict do nothing;
    get diagnostics v_added = row_count;
  end if;
  -- CF-247 scholarships beyond universities: the pilot providers are queued, due once after the list was saved, and their stored refused pages admitted again
  v_pilot := security.scholarship_pilot_start_v1();
  -- CF-247 scholarship recovery F1: the stored processing tier, a batch an hour
  v_tier := security.scholarship_discovery_tier_refresh_v1(security.pipeline_num_v1('batch.scholarship_tier_refresh', 500)::int);
  -- F3: providers mapped before the cadence existed are due the cadence after their last map
  update pipeline.scholarship_discovery_providers set next_discover_at = coalesce(discovered_at, now()) + make_interval(days => security.pipeline_num_v1('reread.scholarship_discovery_days', 30)::int)
   where status in ('mapped', 'empty') and next_discover_at is null;
  get diagnostics v_due = row_count;
  -- F1: the address skip rules on unread candidates; F9: round states
  v_skip := security.scholarship_candidate_skip_v1(null, security.pipeline_num_v1('batch.scholarship_candidate_skip', 5000)::int);
  v_round := security.scholarship_round_state_refresh_v1(security.pipeline_num_v1('batch.scholarship_round_state', 1000)::int);
  return jsonb_build_object('pending_before', v_pending, 'added', v_added, 'pilot', v_pilot, 'tiers', v_tier, 'cadence_set', v_due, 'skipped', v_skip, 'round_states', v_round);
end $$;


ALTER FUNCTION "security"."scholarship_discovery_refill_v1"("p_keep" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_discovery_settle_remedy_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  v := security.scholarship_discovery_settle_v1(null);
  return jsonb_build_object('ok', coalesce((v->>'on')::boolean, false), 'changed', coalesce((v->>'settled')::int, 0) + coalesce((v->>'restored')::int, 0),
                            'evidence', v || jsonb_build_object('issue', p_issue));
end $$;


ALTER FUNCTION "security"."scholarship_discovery_settle_remedy_v1"("p_issue" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_discovery_settle_remedy_v1"("p_issue" bigint) IS 'CF-247 workstream C: action of remedy sch_discovery_settle (authority auto): security.scholarship_discovery_settle_v1 once. Returns {ok, changed, evidence}.';



CREATE OR REPLACE FUNCTION "security"."scholarship_discovery_settle_v1"("p_limit" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_lim int := greatest(0, coalesce(p_limit, security.pipeline_num_v1('batch.scholarship_discovery_settle', 1000)::int));
        v_hold interval := make_interval(hours => security.pipeline_num_v1('retry.scholarship_discovery_held_hours', 6)::int);
        v_reread interval := make_interval(days => security.pipeline_num_v1('reread.scholarship_discovery_days', 30)::int);
        v_settled int := 0; v_restored int := 0; v_by jsonb; v_back jsonb;
begin
  if not security.scholarship_flag_v1('scholarship.discovery_settle_on', true) then
    return jsonb_build_object('on', false, 'settled', 0, 'restored', 0);
  end if;
  with c as (
    select d.provider_id, d.status, security.scholarship_discovery_hold_reason_v1(d.provider_id, d.website) why
      from pipeline.scholarship_discovery_providers d
     where coalesce(d.leased_until, '-infinity') < now()
       and (d.status in ('pending', 'deferred') or (d.status in ('mapped', 'empty') and d.next_discover_at is not null and d.next_discover_at <= now() + v_hold))),
  pick as (select c.* from c where c.why is not null order by c.provider_id limit v_lim),
  upd as (update pipeline.scholarship_discovery_providers d set status = 'not_eligible', settled_from = pick.status, settle_reason = pick.why, settled_at = now(),
                 next_discover_at = null, leased_until = null
            from pick where d.provider_id = pick.provider_id returning pick.why)
  select count(*), coalesce(jsonb_object_agg(why, n), '{}'::jsonb) into v_settled, v_by
    from (select why, count(*) n from upd group by why) g;
  v_settled := coalesce((select sum(value::int) from jsonb_each_text(v_by)), 0);
  -- settled rows, longest unchecked first: those whose reason has cleared return; the others keep the outcome with today's reason
  with w as (
    select d.provider_id, d.settle_reason, security.scholarship_discovery_hold_reason_v1(d.provider_id, d.website) why from pipeline.scholarship_discovery_providers d
     where d.status = 'not_eligible' order by d.settled_at nulls first, d.provider_id limit v_lim),
  why as (update pipeline.scholarship_discovery_providers d set settle_reason = w.why from w
           where d.provider_id = w.provider_id and w.why is not null and w.why is distinct from w.settle_reason returning d.provider_id),
  upd as (update pipeline.scholarship_discovery_providers d set status = coalesce(d.settled_from, 'pending'),
                 next_discover_at = case when coalesce(d.settled_from, 'pending') in ('mapped', 'empty') then greatest(now(), coalesce(d.discovered_at, '-infinity') + v_reread) else now() end,
                 settle_reason = null, settled_from = null, settled_at = now()
            from w where d.provider_id = w.provider_id and w.why is null returning d.status)
  select coalesce(jsonb_object_agg(status, n), '{}'::jsonb) into v_back from (select status, count(*) n from upd group by status) g;
  v_restored := coalesce((select sum(value::int) from jsonb_each_text(v_back)), 0);
  return jsonb_build_object('on', true, 'settled', v_settled, 'settled_by_reason', v_by, 'restored', v_restored, 'restored_to', v_back,
    'waiting_takeable', (select count(*) from pipeline.scholarship_discovery_providers d where d.status in ('pending', 'deferred')),
    'not_eligible', (select count(*) from pipeline.scholarship_discovery_providers d where d.status = 'not_eligible'));
end $$;


ALTER FUNCTION "security"."scholarship_discovery_settle_v1"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_discovery_settle_v1"("p_limit" integer) IS 'CF-247 workstream C (IQ-00041, IQ-00058; P0 mandate §7, §11): job scholarship-discovery-settle. Scholarship discovery rows the picker can never take get the outcome not_eligible with the reason, and return to their status, due, when the reason clears. Switch scholarship.discovery_settle_on; size batch.scholarship_discovery_settle. No read, no spend.';



CREATE OR REPLACE FUNCTION "security"."scholarship_discovery_settle_verify_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 workstream C: verify of remedy sch_discovery_settle. Passed when no waiting discovery row (pending or deferred) belongs to a provider
  -- discovery can never take, and every row the settle mechanism parked still has its reason.
  with w as (select d.provider_id, d.status, security.scholarship_discovery_hold_reason_v1(d.provider_id, d.website) why from pipeline.scholarship_discovery_providers d
              where d.status in ('pending', 'deferred', 'not_eligible')),
  m as (select count(*) filter (where status <> 'not_eligible' and why is not null) waiting_refused,
               count(*) filter (where status <> 'not_eligible' and why is null) waiting_takeable,
               count(*) filter (where status = 'not_eligible') settled,
               count(*) filter (where status = 'not_eligible' and why is null) settled_but_takeable from w)
  select jsonb_build_object('passed', m.waiting_refused = 0 and m.settled_but_takeable = 0, 'measure', to_jsonb(m),
                            'evidence', jsonb_build_object('issue', p_issue, 'at', now(),
                              'sample', (select coalesce(jsonb_agg(x.provider_id), '[]'::jsonb) from (select w.provider_id from w where w.status <> 'not_eligible' and w.why is not null order by 1 limit 5) x)))
    from m
$$;


ALTER FUNCTION "security"."scholarship_discovery_settle_verify_v1"("p_issue" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_discovery_settle_verify_v1"("p_issue" bigint) IS 'CF-247 workstream C: verify of remedy sch_discovery_settle: no waiting discovery row of a refused provider, and no settled row whose reason has cleared. Returns {passed, measure, evidence}. Read-only.';



CREATE OR REPLACE FUNCTION "security"."scholarship_discovery_tier_refresh_v1"("p_limit" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v int;
begin
  update pipeline.scholarship_discovery_providers d set tier = security.fc_provider_tier_v1(d.provider_id)
   where d.provider_id in (select x.provider_id from pipeline.scholarship_discovery_providers x
                            where x.status in ('pending', 'deferred', 'mapped', 'empty') order by (x.tier is not null), x.updated_at limit greatest(p_limit, 0));
  get diagnostics v = row_count;
  return v;
end $$;


ALTER FUNCTION "security"."scholarship_discovery_tier_refresh_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_duplicate_close_v1"("p_review" bigint, "p_target" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r pipeline.scholarship_ai_reviews; v_t uuid; v_name text; v_res jsonb;
begin
  select * into r from pipeline.scholarship_ai_reviews where id = p_review;
  if r.id is null or r.status <> 'pending' then raise exception 'this held scholarship is no longer waiting'; end if;
  begin v_t := btrim(coalesce(p_target, ''))::uuid; exception when others then raise exception 'give the published scholarship''s id'; end;
  select s.name into v_name from scholarship.scholarships s
   where s.id = v_t and s.publication_status = 'published' and s.lifecycle_status = 'active' and s.provider_id = r.provider_id and s.id is distinct from r.scholarship_id;
  if v_name is null then raise exception 'that is not a published, active scholarship of the same provider'; end if;
  v_res := public.admin_scholarship_ai('review_decide', jsonb_build_object('review_id', p_review, 'decision', 'refuse',
             'reason', left('Duplicate of published scholarship ' || v_t || ' (' || v_name || '): ' || p_reason, 500)));
  insert into pipeline.scholarship_duplicate_closures(review_id, held_scholarship_id, duplicate_of, provider_id, reason, actor)
  values (p_review, r.scholarship_id, v_t, r.provider_id, p_reason, auth.uid());
  return jsonb_build_object('duplicate_of', v_t, 'name', v_name, 'review', v_res->'applied');
end $$;


ALTER FUNCTION "security"."scholarship_duplicate_close_v1"("p_review" bigint, "p_target" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_eligibility_apply_v1"("p_limit" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_lim int := greatest(0, coalesce(p_limit, security.pipeline_num_v1('batch.sch_eligibility_apply', 200)::int));
        v_live boolean := security.pipeline_num_v1('sch_elig.apply_on', 0) >= 1;
        v_silent boolean := security.pipeline_num_v1('sch_elig.silent_resolves', 0) >= 1;
        v_readmit boolean := security.pipeline_num_v1('sch_elig.readmit_on', 0) >= 1;  -- 20261113260000: re-admission path
        r record; v_act text; v_url text; v_only boolean; v_res jsonb; v_ev jsonb; v_by jsonb := '{}'::jsonb;
begin
  for r in select e.candidate_id, e.outcome, e.result, c.provider_id, c.admit_status, c.admit_reasons, c.facts, c.admitted_scholarship_id, c.matched_scholarship_id,
                  coalesce(c.final_url, c.url) page_url
             from pipeline.scholarship_eligibility_reads e join pipeline.scholarship_page_candidates c on c.id = e.candidate_id
            where e.state in ('done', 'failed') and e.applied is null
            order by e.read_at nulls last, e.candidate_id limit v_lim loop
    v_url := coalesce(nullif(r.result->>'source_url', ''), r.page_url);
    v_only := coalesce(r.admit_reasons, '{}'::text[]) <@ array['international_not_stated']
              and not exists (select 1 from jsonb_array_elements_text(case when jsonb_typeof(r.facts->'admission'->'reasons') = 'array' then r.facts->'admission'->'reasons' else '[]'::jsonb end) x
                               where x <> 'international_not_stated');
    v_act := case
      -- 20261113260000: a record withdrawn for a proof that was not specific, whose proof passes the current rule on the award's own page
      when r.admit_status = 'withdrawn' and coalesce(r.admit_reasons, '{}'::text[]) = array['eligibility_proof_not_specific'] and r.admitted_scholarship_id is not null
           and r.outcome = 'proven' and coalesce((r.result->>'audience_proven')::boolean, false) and r.result->>'audience' in ('international', 'both') then
        case when not coalesce(security.url_on_provider_sites(v_url, r.provider_id), false) or security.third_party_host_v1(coalesce(v_url, ''))
                  or security.scholarship_government_host_v1(v_url) then 'sentence_off_provider_site'
             when coalesce(r.result->>'source', 'page') = 'linked'
                  and (coalesce(v_url, '') !~* '(scholar|award|bursar|grant|prize|stipend|terms|condition|eligib|rules|funding|fee[-_]?waiver)'
                       or coalesce(v_url, '') ~* '(how[-_]to[-_]apply|/admissions?([-/_]|$)|apply[-_]now|/apply(/|$))') then 'linked_page_not_scholarship'
             when exists (select 1 from jsonb_array_elements_text(case when jsonb_typeof(r.facts->'admission'->'reasons') = 'array' then r.facts->'admission'->'reasons' else '[]'::jsonb end) x
                           where x <> 'international_not_stated') then 'proven_other_refusals'
             when not security.scholarship_page_names_award_v1(r.page_url, (select s.name from scholarship.scholarships s where s.id = r.admitted_scholarship_id)) then 'readmit_page_not_specific'
             when security.scholarship_readmit_blocker_v1(r.admitted_scholarship_id) is not null then 'readmit_' || security.scholarship_readmit_blocker_v1(r.admitted_scholarship_id)
             else 'readmit' end
      when r.admit_status is distinct from 'rejected' or r.admitted_scholarship_id is not null or r.matched_scholarship_id is not null then 'changed_since'
      -- 20261113065000: a sentence that also names international or overseas candidates is not a domestic-only proof
      when r.outcome = 'proven' and coalesce((r.result->>'audience_proven')::boolean, false) and r.result->>'audience' = 'domestic'
           and coalesce(r.result->>'audience_quote', '') ~* '\m(international|overseas|non[- ]?residents?)\M' then 'mixed_audience'
      when r.outcome = 'proven' and coalesce((r.result->>'audience_proven')::boolean, false) and r.result->>'audience' = 'domestic' then 'domestic'
      when r.outcome = 'proven' and coalesce((r.result->>'audience_proven')::boolean, false) and r.result->>'audience' in ('international', 'both') then
        case when not coalesce(security.url_on_provider_sites(v_url, r.provider_id), false) or security.third_party_host_v1(coalesce(v_url, ''))
                  or security.scholarship_government_host_v1(v_url) then 'sentence_off_provider_site'
             -- 20261113065000: a linked page proves only when it is about the scholarship, its terms, eligibility or funding
             when coalesce(r.result->>'source', 'page') = 'linked'
                  and (coalesce(v_url, '') !~* '(scholar|award|bursar|grant|prize|stipend|terms|condition|eligib|rules|funding|fee[-_]?waiver)'
                       or coalesce(v_url, '') ~* '(how[-_]to[-_]apply|/admissions?([-/_]|$)|apply[-_]now|/apply(/|$))') then 'linked_page_not_scholarship'
             when not v_only then 'proven_other_refusals'
             else 'admit' end
      when r.outcome = 'silent' then 'silent'
      else 'unsettled' end;
    v_ev := jsonb_build_object('audience', r.result->>'audience', 'quote', r.result->>'audience_quote', 'source', r.result->>'source', 'source_url', v_url,
                               'model', r.result->>'model', 'read_at', now(), 'by', 'security.scholarship_eligibility_apply_v1');
    if not v_live then
      update pipeline.scholarship_eligibility_reads set applied = jsonb_build_object('mode', 'shadow', 'action', v_act, 'at', now()), updated_at = now() where candidate_id = r.candidate_id;
    elsif v_act = 'domestic' then
      update pipeline.scholarship_page_candidates set admit_reasons = array_append(array_remove(coalesce(admit_reasons, '{}'::text[]), 'international_not_stated'), 'domestic_only'),
             facts = coalesce(facts, '{}'::jsonb) || jsonb_build_object('eligibility_read', v_ev) where id = r.candidate_id;
      insert into pipeline.scholarship_admission_log(candidate_id, provider_id, action, detail) values (r.candidate_id, r.provider_id, 'eligibility_domestic', v_ev);
      update pipeline.scholarship_eligibility_reads set applied = jsonb_build_object('mode', 'live', 'action', v_act, 'at', now()), updated_at = now() where candidate_id = r.candidate_id;
    elsif v_act = 'admit' then
      update pipeline.scholarship_page_candidates
         set facts = jsonb_set(jsonb_set(jsonb_set(coalesce(facts, '{}'::jsonb) || jsonb_build_object('international', true, 'eligibility_read', v_ev, 'eligibility_excerpt', left(coalesce(r.result->>'audience_quote', ''), 600)),
                                                   '{admission,international_explicit}', 'true'::jsonb, true), '{admission,admit}', 'true'::jsonb, true), '{admission,reasons}', '[]'::jsonb, true),
             admit_status = null, admit_reasons = null
       where id = r.candidate_id;
      v_res := security.scholarship_admit_from_provider_page_v1(r.candidate_id);
      update pipeline.scholarship_eligibility_reads set applied = jsonb_build_object('mode', 'live', 'action', v_act, 'admission', v_res, 'at', now()), updated_at = now() where candidate_id = r.candidate_id;
      v_act := case when coalesce((v_res->>'admitted')::boolean, false) then 'admitted' else 'admission_refused' end;
    elsif v_act = 'readmit' and not v_readmit then
      update pipeline.scholarship_eligibility_reads set applied = jsonb_build_object('mode', 'live', 'action', 'readmit_held', 'at', now()), updated_at = now() where candidate_id = r.candidate_id;
      v_act := 'readmit_held';
    elsif v_act = 'readmit' then
      v_res := security.scholarship_readmit_v1(r.candidate_id, v_ev);
      update pipeline.scholarship_eligibility_reads set applied = jsonb_build_object('mode', 'live', 'action', v_act, 'readmission', v_res, 'at', now()), updated_at = now() where candidate_id = r.candidate_id;
      v_act := case when coalesce((v_res->>'readmitted')::boolean, false) then 'readmitted' else 'readmission_refused' end;
    elsif v_act = 'silent' and v_silent then
      update pipeline.scholarship_page_candidates set admit_reasons = array_append(array_remove(coalesce(admit_reasons, '{}'::text[]), 'international_not_stated'), 'international_not_proven_after_eligibility_read'),
             facts = coalesce(facts, '{}'::jsonb) || jsonb_build_object('eligibility_read', v_ev) where id = r.candidate_id;
      insert into pipeline.scholarship_admission_log(candidate_id, provider_id, action, detail) values (r.candidate_id, r.provider_id, 'eligibility_not_proven', v_ev);
      update pipeline.scholarship_eligibility_reads set applied = jsonb_build_object('mode', 'live', 'action', 'silent_resolved', 'at', now()), updated_at = now() where candidate_id = r.candidate_id;
      v_act := 'silent_resolved';
    else
      update pipeline.scholarship_eligibility_reads set applied = jsonb_build_object('mode', 'live', 'action', v_act, 'at', now()), updated_at = now() where candidate_id = r.candidate_id;
    end if;
    v_by := v_by || jsonb_build_object(v_act, coalesce((v_by->>v_act)::int, 0) + 1);
  end loop;
  return jsonb_build_object('live', v_live, 'by_action', v_by);
end $_$;


ALTER FUNCTION "security"."scholarship_eligibility_apply_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_eligibility_enqueue_v1"("p_limit" integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_lim int := greatest(0, coalesce(p_limit, security.pipeline_num_v1('batch.sch_eligibility_enqueue', 200)::int));
        v_all boolean := security.pipeline_num_v1('sch_elig.policy_refused_too', 0) >= 1; v_n int; v_again int;
begin
  update pipeline.scholarship_eligibility_reads e set state = 'queued', outcome = null, result = null, applied = null, tries = 0, next_try_at = null,
         leased_until = null, signature = coalesce(c.content_hash, ''), queued_at = now(), updated_at = now()
    from pipeline.scholarship_page_candidates c
   where c.id = e.candidate_id and e.state in ('done', 'failed') and c.admit_status = 'rejected' and coalesce(c.content_hash, '') <> e.signature;
  get diagnostics v_again = row_count;
  -- the admission scope is decided once per provider (it is costly per row: 2,200 rows timed out in the dry run)
  with cand as materialized (
    select c.id, c.provider_id, coalesce(c.content_hash, '') sig, i.first_seen
      from pipeline.scholarship_coverage_items i
      join pipeline.scholarship_page_candidates c on c.provider_id = i.provider_id and i.item_key = 'cand:' || c.id::text
     where i.present and i.state = 'international_unresolved'
       and c.admit_status = 'rejected' and c.admitted_scholarship_id is null and c.matched_scholarship_id is null
       and not exists (select 1 from pipeline.scholarship_eligibility_reads e where e.candidate_id = c.id)
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = c.provider_id)),
  ok as materialized (
    select p.provider_id, v_all or coalesce(security.scholarship_admission_provider_ok_v1(p.provider_id), false) ok
      from (select distinct cand.provider_id from cand) p)
  insert into pipeline.scholarship_eligibility_reads(candidate_id, provider_id, signature)
  select cand.id, cand.provider_id, cand.sig from cand join ok on ok.provider_id = cand.provider_id and ok.ok
   order by cand.first_seen, cand.id
   limit v_lim
  on conflict (candidate_id) do nothing;
  get diagnostics v_n = row_count;
  return v_n + v_again;
end $$;


ALTER FUNCTION "security"."scholarship_eligibility_enqueue_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_eligibility_fire_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_q int; v_a jsonb; v_f boolean := false; v_due int;
begin
  if security.pipeline_num_v1('sch_elig.on', 0) < 1 then return jsonb_build_object('on', false); end if;
  v_q := security.scholarship_eligibility_enqueue_v1(null);
  v_a := security.scholarship_eligibility_apply_v1(null);
  select count(*) into v_due from pipeline.scholarship_eligibility_reads e
   where (e.state = 'queued' and coalesce(e.next_try_at, '-infinity') <= now()) or (e.state = 'leased' and e.leased_until < now());
  if v_due > 0 and security.ai_use_allowed_v1('scholarship_ai') then
    perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'scholarship_eligibility', 'limit', security.pipeline_num_v1('batch.sch_eligibility_read', 20)::int));
    v_f := true;
  end if;
  return jsonb_build_object('on', true, 'queued', v_q, 'applied', v_a, 'due', v_due, 'fired', v_f);
end $$;


ALTER FUNCTION "security"."scholarship_eligibility_fire_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_expire_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_ids uuid[]; v_ref text := to_char(now() at time zone 'Australia/Melbourne', 'DD Mon YYYY HH24:MI');
begin
  select coalesce(array_agg(s.id), '{}') into v_ids from scholarship.scholarships s
   where s.publication_status = 'published' and security.scholarship_closed_v1(s.application_close_date, s.application_close_precision);
  if cardinality(v_ids) > 0 then
    update scholarship.scholarships set publication_status = 'withdrawn', updated_at = now() where id = any (v_ids);
    insert into pipeline.scholarship_publication_batches(kind, approval_ref, scholarship_ids) values ('withdraw', 'auto-expire ' || v_ref, v_ids);
    insert into search.refresh_requests(requested_by) values ('auto-expire ' || v_ref || ': ' || cardinality(v_ids) || ' closed');
  end if;
  return jsonb_build_object('withdrawn', cardinality(v_ids));
end $$;


ALTER FUNCTION "security"."scholarship_expire_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_expire_v1"() IS 'CF-247 worker v1.0.2: withdraws every published scholarship whose closing date has passed (batch auto-expire, no hold), first step of job scholarship-auto-publish; a recheck that finds a current closing date makes it publishable again.';



CREATE OR REPLACE FUNCTION "security"."scholarship_external_award_v1"("p_name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from pipeline.platform_toolset_settings s, jsonb_array_elements_text(case when jsonb_typeof(s.value) = 'array' then s.value else '[]'::jsonb end) x(w)
                  where s.toolset_key = 'pipeline' and s.key = 'scholarship.external_award_patterns' and nullif(btrim(x.w), '') is not null
                    and strpos(lower(coalesce(p_name, '')), lower(x.w)) > 0)
$$;


ALTER FUNCTION "security"."scholarship_external_award_v1"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_fee_alignment_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_courses int := 0; v_refreshed int := 0;
begin
  for r in
    select distinct x.course_id from (
      select f.course_id from catalogue.course_fees f
       where f.audience = 'international' and f.fee_type = 'provider_current_tuition' and f.updated_at > now() - interval '70 minutes'
      union
      select c.course_id from pipeline.adapter_overwrite_changes c where c.field = 'fee' and c.at > now() - interval '70 minutes') x
    where exists (select 1 from scholarship.course_mappings m where m.course_id = x.course_id and m.mapping_state = 'mapped')
  loop
    v_courses := v_courses + 1;
    v_refreshed := v_refreshed + coalesce((scholarship.refresh_course_financial_calculations(r.course_id, null)->>'refreshed')::int, 0);
  end loop;
  return jsonb_build_object('courses', v_courses, 'refreshed', v_refreshed);
end $$;


ALTER FUNCTION "security"."scholarship_fee_alignment_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_flag_v1"("p_key" "text", "p_default" boolean) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce((select (s.value #>> '{}')::boolean from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = p_key), p_default)
$$;


ALTER FUNCTION "security"."scholarship_flag_v1"("p_key" "text", "p_default" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_flow_guard_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_stall_h int := security.pipeline_num_v1('sch_flow.stall_hours', 24)::int; v_aged_d int := security.pipeline_num_v1('sch_flow.aged_days', 7)::int;
        v_stall interval := make_interval(hours => v_stall_h); v_aged interval := make_interval(days => v_aged_d);
        v_cap int := security.pipeline_num_v1('har.open_max_per_lane', 150)::int;
        f jsonb := '[]'::jsonb; x jsonb; v_raised jsonb := '{}'::jsonb; v_iss jsonb; v_n int; v_m int; v_k int;
begin
  if security.pipeline_num_v1('sch_flow.on', 1) < 1 then return jsonb_build_object('on', false); end if;
  -- a. a Layer 4 lane at its cap while cases of its class wait unraised
  for x in select jsonb_build_object('lane', l.lane, 'open', l.open, 'cap', v_cap,
                    'waiting', case l.lane when 'sch_coverage' then (select count(*) from pipeline.scholarship_coverage_items i where i.present and i.state in ('international_unresolved', 'source_not_discovered', 'ownership_conflict')) - l.open
                                          else (select count(*) from pipeline.scholarship_coverage_items i where i.present and i.state = 'admitted_not_published' and i.reason ~ 'no stated award value') - l.open end)
             from (select i.lane, count(*) open from pipeline.layer4_interventions i where i.lane in ('sch_coverage', 'sch_value') and i.status in ('ai_pending', 'awaiting_input', 'resuming') group by 1) l
            where l.open >= v_cap loop
    if (x->>'waiting')::int > 0 then
      f := f || jsonb_build_object('code', 'lane_full:' || (x->>'lane'), 'severity', 'P1', 'count', (x->>'waiting')::int, 'detail', x,
             'title', format('Scholarships: Layer 4 lane %s is full (%s open, cap %s); %s cases wait unraised', x->>'lane', x->>'open', v_cap, x->>'waiting'),
             'expected', 'Cases a machine can settle are settled by a reader before Layer 4 (sch_elig.on for eligibility cases); the cap (har.open_max_per_lane) is not a queue.');
    end if;
  end loop;
  -- b. a built recovery switched off while its work waits
  for x in select jsonb_build_object('switch', s.k, 'waiting', s.n, 'what', s.what) from (values
      ('sch_elig.on', (select count(*) from pipeline.scholarship_coverage_items i where i.present and i.state = 'international_unresolved')::int, 'eligibility cases a reader could settle'),
      ('sch_cov.recover_listings_on', (select count(*) from pipeline.scholarship_listing_pages l where l.source = 'suggested' and not l.active)::int
                                     + (select count(*) from pipeline.scholarship_coverage_items i where i.present and i.state = 'traversal_incomplete')::int, 'listing pages found and never traversed'),
      ('sch_cov.recover_register_pages_on', (select count(*) from pipeline.scholarship_coverage_items i where i.present and i.state = 'rejected_incorrectly' and i.recovery = 'reopen_read')::int, 'register pages never read'),
      ('sch_cov.recover_stored_reads_on', (select count(*) from pipeline.scholarship_coverage_items i where i.present and i.state = 'rejected_incorrectly' and i.recovery = 'reread_stored')::int, 'refused pages that could be read again from their stored copy'),
      ('retry.scholarship_transient_recover_on', (select count(*) from pipeline.scholarship_ai_reviews r where r.status = 'pending' and r.reason ~* 'could not be read|statement timeout')::int, 'Layer 4 reviews that are only a failed page read')
    ) s(k, n, what)
    where s.n > 0 and security.pipeline_num_v1(s.k, 0) < 1 loop
    f := f || jsonb_build_object('code', 'recovery_off:' || (x->>'switch'), 'severity', 'P2', 'count', (x->>'waiting')::int, 'detail', x,
           'title', format('Scholarships: %s waiting while %s is 0 (%s)', x->>'waiting', x->>'switch', x->>'what'),
           'expected', format('The Platform Admin switches %s on (Settings > Pipeline settings) or records why it stays off.', x->>'switch'));
  end loop;
  -- c. coverage states no job can move: providers reported unresolved while the scholarship scope refuses them
  select count(*), count(*) filter (where exists (select 1 from pipeline.scholarship_page_candidates c where c.provider_id = p.provider_id)) into v_n, v_m
    from pipeline.scholarship_coverage_providers p
   where p.provider_state in ('source_not_discovered', 'source_found_unread', 'traversal_incomplete', 'international_unresolved', 'rejected_incorrectly', 'awaiting_layer4', 'admitted_not_published', 'ownership_conflict')
     and security.scholarship_scope_v1(p.provider_id) <> 'in_scope';
  if v_n > 0 then
    f := f || jsonb_build_object('code', 'dead_end_scope', 'severity', 'P2', 'count', v_n, 'detail', jsonb_build_object('providers', v_n, 'with_pages_found', v_m),
           'title', format('Scholarships: %s providers are reported unresolved but the scholarship scope refuses them (%s already have pages found)', v_n, v_m),
           'expected', 'The scope decision (scholarship.pilot_only, scholarship_min_courses, scholarship.refill_open_countries) admits them, or coverage reports them blocked by policy (sch_cov.policy_disposition_on).');
  end if;
  -- d. admission stalled
  select count(*) into v_k from pipeline.scholarship_coverage_items i where i.present and i.state in ('source_not_discovered', 'source_found_unread', 'traversal_incomplete', 'international_unresolved', 'rejected_incorrectly', 'awaiting_layer4');
  if v_k > 0 and not exists (select 1 from pipeline.scholarship_page_candidates c where c.found_at > now() - v_stall)
     and not exists (select 1 from pipeline.scholarship_admission_log l where l.action = 'admitted' and l.at > now() - v_stall) then
    f := f || jsonb_build_object('code', 'admission_stalled', 'severity', 'P1', 'count', v_k, 'detail', jsonb_build_object('unresolved', v_k, 'window_hours', v_stall_h),
           'title', format('Scholarships: nothing found or admitted for %s hours while %s cases are unresolved', v_stall_h, v_k),
           'expected', 'Discovery, listing and reading jobs take work every run; a job that reports success with no work while cases wait is a stall.');
  end if;
  -- d2. admission declining (F-SCH.01 activation, Platform Admin 12 Nov 2026 11:50 §5): the latest window against the daily average before it
  declare v_last int; v_avg numeric; v_days int := security.pipeline_num_v1('sch_flow.decline_window_days', 7)::int;
          v_pct numeric := security.pipeline_num_v1('sch_flow.decline_pct', 50); v_min numeric := security.pipeline_num_v1('sch_flow.decline_min_daily', 5);
  begin
    select count(*) into v_last from pipeline.scholarship_admission_log l where l.action = 'admitted' and l.at > now() - v_stall;
    select count(*)::numeric / greatest(v_days, 1) into v_avg from pipeline.scholarship_admission_log l
     where l.action = 'admitted' and l.at <= now() - v_stall and l.at > now() - v_stall - make_interval(days => v_days);
    if v_k > 0 and v_avg >= v_min and v_last < v_avg * v_pct / 100 then
      f := f || jsonb_build_object('code', 'admission_declining', 'severity', 'P2', 'count', v_last,
             'detail', jsonb_build_object('admitted_latest', v_last, 'window_hours', v_stall_h, 'daily_average_before', round(v_avg, 1), 'average_days', v_days, 'threshold_pct', v_pct),
             'title', format('Scholarships: %s admitted in the last %s hours against a daily average of %s over the %s days before', v_last, v_stall_h, round(v_avg, 1), v_days),
             'expected', 'Admission keeps pace with the recent average while cases wait; the flow guard''s other findings name the cause.');
    end if;
  end;
  -- e. cases overdue
  select count(*) into v_n from pipeline.scholarship_coverage_items i join pipeline.scholarship_coverage_state_codes s on s.code = i.state
   where i.present and not s.resolved and i.first_seen < now() - v_aged;
  if v_n > 0 then
    f := f || jsonb_build_object('code', 'cases_overdue', 'severity', 'P2', 'count', v_n, 'detail', jsonb_build_object('overdue', v_n, 'by_state',
             (select jsonb_object_agg(q.state, q.n) from (select i.state, count(*) n from pipeline.scholarship_coverage_items i join pipeline.scholarship_coverage_state_codes s on s.code = i.state
                where i.present and not s.resolved and i.first_seen < now() - v_aged group by 1) q)),
           'title', format('Scholarships: %s coverage cases unresolved for more than %s days', v_n, v_aged_d),
           'expected', 'Each unresolved state has a job that moves it; the flow guard''s other findings name the ones that do not.');
  end if;
  -- raise or refresh each finding; clear causes no longer present
  for x in select * from jsonb_array_elements(f) loop
    begin
      v_iss := security.integration_issue_upsert_v1(jsonb_build_object(
        'fingerprint', 'sch_flow:' || (x->>'code'), 'title', x->>'title', 'layer', 'Layer 2', 'subsystem', 'scholarship flow guard', 'severity', x->>'severity',
        'workstream', 'A8', 'validation_layer', 'V4', 'source', 'scholarship-flow-guard',
        'root_cause_class', case when x->>'code' like 'recovery_off:%' or x->>'code' = 'dead_end_scope' then 'human_decision' when x->>'code' like 'lane_full:%' then 'queue_or_lease' else 'job_config' end,
        'failure', x->>'title', 'expected', x->>'expected', 'evidence', x->'detail', 'observed_at', now()), 'scholarship-flow-guard');
      v_raised := v_raised || jsonb_build_object(x->>'code', v_iss->>'issue_ref');
    exception when others then v_raised := v_raised || jsonb_build_object(x->>'code', 'error: ' || left(sqlerrm, 160));
    end;
  end loop;
  update pipeline.integration_issues i set condition_cleared_at = now()
   where i.fingerprint like 'sch\_flow:%' and i.condition_cleared_at is null and i.status <> 'closed'
     and not exists (select 1 from jsonb_array_elements(f) y where 'sch_flow:' || (y->>'code') = i.fingerprint);
  insert into pipeline.scholarship_flow_checks(findings, raised) values (f, v_raised);
  return jsonb_build_object('on', true, 'findings', jsonb_array_length(f), 'raised', v_raised);
end $$;


ALTER FUNCTION "security"."scholarship_flow_guard_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_from_record_register"("p_scholarship_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from scholarship.scholarships s join scholarship.registers r on r.source_id = s.source_id and r.role = 'record'
                  where s.id = p_scholarship_id)
$$;


ALTER FUNCTION "security"."scholarship_from_record_register"("p_scholarship_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_government_host_v1"("p_url" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select coalesce(lower(substring(p_url from '^[a-z]+://([^/:?#]+)')) ~ '(^|\.)(gov|govt)(\.[a-z]{2})?$|\.gc\.ca$|(^|\.)gov\.[a-z]{2}$', false)
$_$;


ALTER FUNCTION "security"."scholarship_government_host_v1"("p_url" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_government_host_v1"("p_url" "text") IS 'F-SCH.01 (12 Nov 2026): true for a government or regulator site (gov, govt, gc.ca); a scholarship eligibility sentence read there is not a provider''s own page.';



CREATE OR REPLACE FUNCTION "security"."scholarship_held_without_page"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('scholarship_id',s.id,'name',s.name) order by s.name),'[]'::jsonb)
    from scholarship.scholarships s
   where s.provider_id=p_provider_id and s.lifecycle_status='active' and security.reference_url_has_use(s.source_url, 'scholarship_placeholder')
     and not exists (select 1 from pipeline.scholarship_pages sp where sp.scholarship_id=s.id and not (sp.url_source='discovered' and sp.read_status in ('name_mismatch','robots_disallowed','gone')))
     and not exists (select 1 from scholarship.identifiers i where i.scholarship_id=s.id and i.scheme='first_party_detail_url')
$$;


ALTER FUNCTION "security"."scholarship_held_without_page"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_job_items_sync_v1"("p_job" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_j pipeline.admin_jobs%rowtype; v_ids uuid[]; v_sch uuid[]; v_since timestamptz; v_until timestamptz; v_n int := 0; v_k int;
begin
  select * into v_j from pipeline.admin_jobs j where j.id = p_job;
  if v_j.id is null or v_j.kind not in ('scholarship_provider_scan', 'scholarship_course_check', 'scholarship_reread') then return 0; end if;
  v_ids := array(select x::uuid from jsonb_array_elements_text(coalesce(v_j.args->'providers', '[]'::jsonb)) x);
  v_sch := array(select x::uuid from jsonb_array_elements_text(coalesce(v_j.args->'scholarship_ids', '[]'::jsonb)) x);
  v_since := v_j.created_at - interval '1 minute';
  v_until := coalesce(v_j.finished_at, now()) + interval '1 minute';
  if v_j.kind = 'scholarship_provider_scan' then
    insert into pipeline.admin_job_items(job_id, provider_id, kind, ref, url, title, found_via, read_status, outcome, reasons, at)
    select p_job, d.provider_id, 'site_map', d.provider_id::text, coalesce(d.site_origin, d.website), d.method, 'site map and search', d.status,
           case when d.status = 'pending' then 'waiting' when d.status = 'failed' then 'failed' else 'mapped' end,
           array_remove(array[coalesce(d.kept_count, 0) || ' page(s) kept of ' || coalesce(d.url_count, 0) || ' address(es)', d.last_error], null), d.updated_at
      from pipeline.scholarship_discovery_providers d where d.provider_id = any (v_ids) and d.updated_at between v_since and v_until
    on conflict (job_id, kind, ref) do update set title = excluded.title, read_status = excluded.read_status, outcome = excluded.outcome, reasons = excluded.reasons, at = excluded.at, recorded_at = now();
    get diagnostics v_k = row_count; v_n := v_n + v_k;
    insert into pipeline.admin_job_items(job_id, provider_id, kind, ref, url, title, found_via, read_status, outcome, reasons, at)
    select p_job, l.provider_id, 'listing', l.id::text, l.url, 'Listing page', l.source, l.status,
           case when l.status = 'read' then 'read' when l.status = 'failed' then 'failed' else 'waiting' end,
           array_remove(array[jsonb_array_length(coalesce(l.items, '[]'::jsonb)) || ' scholarship(s) listed', l.error], null), l.read_at
      from pipeline.scholarship_listing_pages l where l.provider_id = any (v_ids) and l.active and l.read_at between v_since and v_until
    on conflict (job_id, kind, ref) do update set read_status = excluded.read_status, outcome = excluded.outcome, reasons = excluded.reasons, at = excluded.at, recorded_at = now();
    get diagnostics v_k = row_count; v_n := v_n + v_k;
    insert into pipeline.admin_job_items(job_id, provider_id, kind, ref, url, title, found_via, read_status, outcome, reasons, evidence_id, storage_path, content_hash, scholarship_id, at)
    select p_job, c.provider_id, 'candidate', c.id::text, c.url, coalesce(nullif(c.facts->>'h1', ''), nullif(c.title, ''), nullif(c.facts->>'page_title', '')),
           case c.source when 'sitemap' then 'site map' when 'map' then 'site search' when 'search' then 'web search' else c.source end, c.read_status,
           case when c.admit_status = 'admitted' then 'became_scholarship'
                when c.admit_status = 'duplicate' or c.matched_scholarship_id is not null then 'already_held'
                when c.admit_status = 'skipped' then 'skipped'
                when c.admit_status = 'rejected' then 'refused'
                when c.read_status = 'too_thin' and c.read_at >= v_since then 'too_thin'
                when c.read_at >= v_since then 'not_read'
                else 'waiting' end,
           case when c.read_status = 'too_thin' and c.admit_status is null then array['too_thin'] else c.admit_reasons end,
           coalesce(c.evidence_id, (select s.evidence_id from scholarship.scholarships s where s.id = c.admitted_scholarship_id)),
           c.storage_path, c.content_hash, coalesce(c.admitted_scholarship_id, c.matched_scholarship_id), coalesce(c.read_at, c.found_at)
      from pipeline.scholarship_page_candidates c
     where c.provider_id = any (v_ids) and c.source <> 'register'
       and (c.found_at between v_since and v_until or c.read_at between v_since and v_until or c.requested_at between v_since and v_until)
    on conflict (job_id, kind, ref) do update set title = excluded.title, read_status = excluded.read_status, outcome = excluded.outcome, reasons = excluded.reasons,
       evidence_id = excluded.evidence_id, storage_path = excluded.storage_path, content_hash = excluded.content_hash, scholarship_id = excluded.scholarship_id, at = excluded.at, recorded_at = now();
    get diagnostics v_k = row_count; v_n := v_n + v_k;
  end if;
  insert into pipeline.admin_job_items(job_id, provider_id, kind, ref, url, title, found_via, read_status, outcome, reasons, evidence_id, scholarship_id, at)
  select p_job, s.provider_id, 'page', s.id::text, sp.url, s.name, 'known scholarship page', sp.read_status,
         case when s.created_at >= v_since then 'new_record'
              when sp.read_at is null or sp.read_at < v_since then 'waiting'
              when exists (select 1 from pipeline.scholarship_sweep_changes ch where ch.scholarship_id = s.id and ch.changed_at between v_since and v_until and ch.field <> 'admitted') then 'updated'
              when sp.read_status in ('read', 'unchanged') then 'unchanged' else 'not_read' end,
         array(select distinct ch.field from pipeline.scholarship_sweep_changes ch where ch.scholarship_id = s.id and ch.changed_at between v_since and v_until and ch.field <> 'admitted' order by 1),
         sp.evidence_id, s.id, sp.read_at
    from pipeline.scholarship_pages sp join scholarship.scholarships s on s.id = sp.scholarship_id
   where s.lifecycle_status = 'active'
     and (case when v_j.kind = 'scholarship_reread' then s.id = any (v_sch) else s.provider_id = any (v_ids) end)
     and (sp.read_at between v_since and v_until or sp.requested_at between v_since and v_until or s.created_at between v_since and v_until)
  on conflict (job_id, kind, ref) do update set read_status = excluded.read_status, outcome = excluded.outcome, reasons = excluded.reasons, evidence_id = excluded.evidence_id, at = excluded.at, recorded_at = now();
  get diagnostics v_k = row_count; v_n := v_n + v_k;
  return v_n;
end $$;


ALTER FUNCTION "security"."scholarship_job_items_sync_v1"("p_job" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_job_journey_v1"("p_job" "uuid", "p_provider" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_j pipeline.admin_jobs%rowtype; v_ids uuid[]; v_next timestamptz; v_auto boolean; v_left int; v_done int; v_rate numeric; v_out jsonb;
begin
  select * into v_j from pipeline.admin_jobs j where j.id = p_job;
  if v_j.id is null then return null; end if;
  v_ids := array(select x::uuid from jsonb_array_elements_text(coalesce(v_j.args->'providers', '[]'::jsonb)) x);
  if p_provider is not null then v_ids := array(select x from unnest(v_ids) x where x = p_provider); end if;
  v_auto := security.scholarship_setting('auto_publish', 0) >= 1;
  v_next := date_trunc('hour', now()) + interval '29 minutes'; if v_next <= now() then v_next := v_next + interval '1 hour'; end if;
  select count(*) filter (where i.outcome = 'waiting'), count(*) filter (where i.outcome <> 'waiting' and i.kind in ('candidate', 'page')) into v_left, v_done
    from pipeline.admin_job_items i where i.job_id = p_job;
  v_rate := case when v_j.started_at is not null and v_done > 0 and now() > v_j.started_at + interval '30 seconds'
                 then v_done / greatest(extract(epoch from (coalesce(v_j.finished_at, now()) - v_j.started_at)) / 60.0, 0.5) end;
  with it as (select i.* from pipeline.admin_job_items i where i.job_id = p_job and (p_provider is null or i.provider_id = p_provider)),
  sch as (select distinct i.provider_id, i.scholarship_id from it i where i.scholarship_id is not null and i.outcome in ('became_scholarship', 'new_record', 'updated', 'unchanged', 'already_held')),
  pub as (select x.provider_id, s.id, s.name, s.publication_status, p.publishable, p.missing,
                 exists (select 1 from pipeline.scholarship_publication_holds h where h.scholarship_id = s.id and h.released_at is null) held
            from sch x join scholarship.scholarships s on s.id = x.scholarship_id
            cross join lateral security.scholarship_publishability_for_v1(array[s.id]) p),
  prov as (select pr.id, coalesce(pr.display_name, pr.canonical_name) name, upper(substring(pr.stable_key from '^provider:cricos:(.+)$')) code
             from catalogue.providers pr where pr.id = any (v_ids))
  select jsonb_build_object(
    'job', jsonb_build_object('id', v_j.id, 'kind', v_j.kind, 'title', v_j.title, 'state', v_j.state, 'reason', v_j.reason, 'created_at', v_j.created_at, 'started_at', v_j.started_at, 'finished_at', v_j.finished_at,
                              'requested_by', (select u.email from auth.users u where u.id = v_j.requested_by), 'credits', v_j.result->'credits'),
    'auto_publish', v_auto, 'next_publish_at', case when v_auto then v_next end,
    'eta_minutes', case when v_j.state in ('queued', 'running') and v_left > 0 then ceil(v_left / coalesce(v_rate, 8))::int end,
    'left', v_left,
    'providers', coalesce((select jsonb_agg(jsonb_build_object(
        'provider_id', pr.id, 'name', pr.name, 'code', pr.code,
        'found', jsonb_build_object('candidates', (select count(*) from it where it.provider_id = pr.id and it.kind = 'candidate'),
                                    'by', (select coalesce(jsonb_object_agg(z.v, z.n), '{}'::jsonb) from (select it.found_via v, count(*) n from it where it.provider_id = pr.id and it.kind = 'candidate' group by 1) z),
                                    'site_map', (select jsonb_build_object('outcome', it.outcome, 'method', it.title, 'note', it.reasons, 'at', it.at) from it where it.provider_id = pr.id and it.kind = 'site_map' limit 1),
                                    'listing', (select jsonb_agg(jsonb_build_object('url', it.url, 'outcome', it.outcome, 'note', it.reasons)) from it where it.provider_id = pr.id and it.kind = 'listing')),
        'read', jsonb_build_object('candidates', (select count(*) from it where it.provider_id = pr.id and it.kind = 'candidate' and it.outcome not in ('waiting', 'skipped')),
                                   'known_pages', (select count(*) from it where it.provider_id = pr.id and it.kind = 'page' and it.outcome <> 'waiting'),
                                   'credits', (select coalesce(sum(u.units), 0) from pipeline.coverage_vendor_usage u where u.provider_id = pr.id and u.purpose like 'sch\_%' and u.at between v_j.created_at and coalesce(v_j.finished_at, now()))),
        'decided', (select jsonb_build_object('became', count(*) filter (where it.outcome = 'became_scholarship'), 'already_held', count(*) filter (where it.outcome = 'already_held'),
                                              'refused', count(*) filter (where it.outcome = 'refused'), 'too_thin', count(*) filter (where it.outcome = 'too_thin'),
                                              'skipped', count(*) filter (where it.outcome = 'skipped'), 'waiting', count(*) filter (where it.outcome = 'waiting'),
                                              'not_read', count(*) filter (where it.outcome = 'not_read'))
                      from it where it.provider_id = pr.id and it.kind = 'candidate'),
        'reasons', (select coalesce(jsonb_agg(jsonb_build_object('reason', z.r, 'n', z.n) order by z.n desc, z.r), '[]'::jsonb)
                      from (select security.scholarship_reason_label_v1(r) r, count(*) n from it, unnest(it.reasons) r where it.provider_id = pr.id and it.kind = 'candidate' and it.outcome in ('refused', 'skipped', 'too_thin') group by 1) z),
        'records', (select jsonb_build_object('new', count(*) filter (where it.outcome in ('became_scholarship', 'new_record')), 'updated', count(*) filter (where it.outcome = 'updated'), 'unchanged', count(*) filter (where it.outcome = 'unchanged'))
                      from it where it.provider_id = pr.id and it.kind in ('candidate', 'page') and (it.kind = 'page' or it.outcome = 'became_scholarship')),
        'publish', jsonb_build_object(
            'published', (select count(*) from pub where pub.provider_id = pr.id and pub.publication_status = 'published' and pub.publishable),
            'next_publish', (select coalesce(jsonb_agg(jsonb_build_object('id', pub.id, 'name', pub.name) order by pub.name), '[]'::jsonb) from pub where pub.provider_id = pr.id and pub.publication_status is distinct from 'published' and pub.publishable),
            'blocked', (select coalesce(jsonb_agg(jsonb_build_object('id', pub.id, 'name', pub.name, 'held', pub.held, 'missing', pub.missing, 'status', pub.publication_status) order by pub.name), '[]'::jsonb) from pub where pub.provider_id = pr.id and not pub.publishable and pub.publication_status is distinct from 'published'),
            'failing', (select coalesce(jsonb_agg(jsonb_build_object('id', pub.id, 'name', pub.name, 'missing', pub.missing) order by pub.name), '[]'::jsonb) from pub where pub.provider_id = pr.id and pub.publication_status = 'published' and not pub.publishable)),
        'items', (select coalesce(jsonb_agg(jsonb_build_object('kind', it.kind, 'url', it.url, 'title', it.title, 'found_via', it.found_via, 'outcome', it.outcome, 'read_status', it.read_status,
                                                            'reasons', (select coalesce(jsonb_agg(security.scholarship_reason_label_v1(r)), '[]'::jsonb) from unnest(it.reasons) r),
                                                            'evidence_id', it.evidence_id, 'stored', it.storage_path is not null or it.evidence_id is not null, 'scholarship_id', it.scholarship_id, 'at', it.at)
                                         order by case it.kind when 'site_map' then 0 when 'listing' then 1 when 'candidate' then 2 else 3 end,
                                                  case it.outcome when 'became_scholarship' then 0 when 'new_record' then 0 when 'updated' then 1 when 'refused' then 2 when 'too_thin' then 3 when 'skipped' then 4 else 5 end, it.url), '[]'::jsonb)
                    from it where it.provider_id = pr.id))
      order by pr.name) from prov pr), '[]'::jsonb))
  into v_out;
  return v_out;
end $_$;


ALTER FUNCTION "security"."scholarship_job_journey_v1"("p_job" "uuid", "p_provider" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_legal_name_ok_v1"("p_provider_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 (IQ-00215): a provider whose record joins its trading names with ';' passes when its legal name (the first name) passes the existing
  -- university name test; the whole joined text is never tested here
  select exists (select 1 from catalogue.providers p join ref.countries c on c.id = p.country_id
                  where p.id = p_provider_id and c.scholarship_ingestion_enabled and p.lifecycle_status = 'active' and position(';' in coalesce(p.canonical_name, '')) > 0
                    and btrim(split_part(p.canonical_name, ';', 1)) ~* '\m(university|université|universite)\M'
                    and btrim(split_part(p.canonical_name, ';', 1)) !~* '(college|pathways?|language cent|senior|theology|divinity)')
$$;


ALTER FUNCTION "security"."scholarship_legal_name_ok_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_legitimacy_v1"("p_provider_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from catalogue.providers p join ref.provider_types t on t.id = p.provider_type_id
                  where p.id = p_provider_id and p.lifecycle_status = 'active' and p.publication_status = 'published'
                    and p.enrols_international is not false and t.status = 'active' and t.code <> 'school'
                    and nullif(btrim(coalesce(p.website, '')), '') is not null and not security.third_party_host_v1(p.website)
                    and (select count(*) from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active')
                        >= security.pipeline_num_v1('scholarship.legitimacy_min_courses', 1))
      -- F-SCH 13 Nov 2026: a classified university with its own official website, without loaded courses or a provider type yet
      or exists (select 1 from catalogue.providers p where p.id = p_provider_id and p.lifecycle_status = 'active' and p.publication_status = 'published'
                    and p.enrols_international is not false and nullif(btrim(coalesce(p.website, '')), '') is not null and not security.third_party_host_v1(p.website)
                    and security.scholarship_university(p.id))
$$;


ALTER FUNCTION "security"."scholarship_legitimacy_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_level_codes"("p_levels" "jsonb") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
  select coalesce(array_agg(distinct c),'{}') from jsonb_array_elements_text(coalesce(p_levels,'[]')) l
  cross join lateral unnest(case l
    when 'undergraduate' then array['bachelor','bachelor_honours','associate_degree']
    when 'postgraduate_coursework' then array['masters_coursework','masters_extended','masters','graduate_certificate','graduate_diploma']
    when 'research' then array['masters_research','doctorate']
    when 'postgraduate_research' then array['masters_research','doctorate']
    when 'pathway' then array['diploma','advanced_diploma','certificate_iv','non_aqf_award']
    else array[]::text[] end) c
$$;


ALTER FUNCTION "security"."scholarship_level_codes"("p_levels" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_listing_accept_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_max int := security.pipeline_num_v1('batch.sch_coverage_recover', 10)::int; v_pp int := security.pipeline_num_v1('sch_cov.recover_per_provider_max', 3)::int;
        r record; v_k int; v_done int := 0; v_skip int := 0; v_per jsonb := '{}'::jsonb; v_hold text;
begin
  if security.pipeline_num_v1('sch_cov.recover_listings_on', 0) < 1 then return jsonb_build_object('ran', false, 'reason', 'sch_cov.recover_listings_on is 0'); end if;
  v_hold := security.lane_paid_hold_v1('sch_scrape');
  if v_hold is not null then return jsonb_build_object('ran', false, 'reason', 'the scholarship Firecrawl share is held', 'hold', v_hold); end if;
  for r in select l.id, l.provider_id, l.url from pipeline.scholarship_listing_pages l
            where l.source = 'suggested' and not l.active
              and not exists (select 1 from pipeline.scholarship_coverage_recoveries x where x.item_key = 'listing:' || l.id and x.action = 'promote_listing')
            order by l.added_at, l.id loop
    exit when v_done >= v_max;
    if coalesce((v_per->>r.provider_id::text)::int, 0) >= v_pp then continue; end if;
    if not security.scholarship_admission_provider_ok_v1(r.provider_id) or security.fc_sch_held_v1(r.provider_id, true) or security.provider_sch_search_off_v1(r.provider_id)
       or exists (select 1 from security.provider_hidden_v1 h where h.provider_id = r.provider_id)
       or security.third_party_host_v1(r.url) or not coalesce(security.url_on_provider_sites(r.url, r.provider_id), false) then v_skip := v_skip + 1; continue; end if;
    update pipeline.scholarship_listing_pages l set source = 'auto', active = true, status = 'waiting', next_read_at = now()
     where l.id = r.id and l.source = 'suggested' and not l.active;
    get diagnostics v_k = row_count;
    insert into pipeline.scholarship_coverage_recoveries(provider_id, item_key, action, state_before, detail)
    values (r.provider_id, 'listing:' || r.id, 'promote_listing', 'source_found_unread', jsonb_build_object('listing_id', r.id, 'url', r.url, 'changed', v_k, 'by', 'scholarship_listing_accept_v1'))
    on conflict (item_key, action) do nothing;
    if v_k > 0 then v_done := v_done + 1; v_per := v_per || jsonb_build_object(r.provider_id::text, coalesce((v_per->>r.provider_id::text)::int, 0) + 1); end if;
  end loop;
  return jsonb_build_object('ran', true, 'accepted', v_done, 'skipped', v_skip, 'providers', (select count(*) from jsonb_object_keys(v_per)));
end $$;


ALTER FUNCTION "security"."scholarship_listing_accept_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_listing_match_v1"("p_provider_id" "uuid") RETURNS TABLE("listing_id" bigint, "item_name" "text", "item_url" "text", "scholarship_id" "uuid", "matched_by" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with items as (
    select distinct on (lower(btrim(e->>'name'))) l.id listing_id, btrim(e->>'name') item_name, nullif(btrim(e->>'url'), '') item_url
      from pipeline.scholarship_listing_pages l, jsonb_array_elements(l.items) e
     where l.provider_id = p_provider_id and l.active and l.source <> 'suggested' and coalesce(btrim(e->>'name'), '') <> ''
     order by lower(btrim(e->>'name')), (nullif(btrim(e->>'url'), '') is null), l.id),
  recs as (
    select s.id, s.name, s.publication_status, security.scholarship_series_key_v1(s.name) k,
           array_remove(array[security.scholarship_url_norm(s.source_url)]
             || array(select security.scholarship_url_norm(i.identifier_value) from scholarship.identifiers i where i.scholarship_id = s.id and i.scheme = 'first_party_detail_url')
             || array(select security.scholarship_url_norm(coalesce(sp.final_url, sp.url)) from pipeline.scholarship_pages sp where sp.scholarship_id = s.id)
             || array(select security.scholarship_url_norm(sp.url) from pipeline.scholarship_pages sp where sp.scholarship_id = s.id), null) urls
      from scholarship.scholarships s where s.provider_id = p_provider_id and s.lifecycle_status = 'active')
  select it.listing_id, it.item_name, it.item_url, m.id, m.how
    from items it
    cross join lateral (select security.scholarship_series_key_v1(it.item_name) ik, security.scholarship_url_norm(it.item_url) iu) x
    left join lateral (
      select r.id, case when x.iu is not null and x.iu = any(r.urls) then 'page' when r.k = x.ik then 'name' else 'similar name' end how
        from recs r
       -- v2.15.249 (Fix 5): a link match also needs the names to agree (VU's Medibank item linked to the Block Model page)
       where (x.iu is not null and x.iu = any(r.urls) and (r.k = x.ik or strpos(r.k, x.ik) > 0 or strpos(x.ik, r.k) > 0
              or (select count(*) from unnest(regexp_split_to_array(x.ik, '[^a-z0-9]+')) w where length(w) > 3 and w not in ('scholarship', 'scholarships', 'university', 'international') and w = any(regexp_split_to_array(r.k, '[^a-z0-9]+'))) >= 2))
          or r.k = x.ik
          or (length(x.ik) >= 15 and length(r.k) >= 15 and (strpos(r.k, x.ik) > 0 or strpos(x.ik, r.k) > 0))
       order by (x.iu is not null and x.iu = any(r.urls)) desc, (r.k = x.ik) desc, (r.publication_status = 'published') desc, r.id
       limit 1) m on true
$$;


ALTER FUNCTION "security"."scholarship_listing_match_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_mapping_decision_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare d pipeline.scholarship_scope_decisions%rowtype;
begin
  if NEW.mapping_basis is distinct from 'sweep_level_field_scope' then return NEW; end if;
  select * into d from pipeline.scholarship_scope_decisions where scholarship_id = NEW.scholarship_id;
  if d.scholarship_id is not null and not security.scholarship_scope_match(NEW.course_id, d.decision, d.filter) then return null; end if;
  return NEW;
end $$;


ALTER FUNCTION "security"."scholarship_mapping_decision_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_nationality_read_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline', 'security', 'ref', 'catalogue'
    AS $$
declare v_read int := 0; v_changed int := 0; v_with int := 0;
begin
  with t as (
    select s.id, k.iso_alpha2 study_country,
           coalesce(s.name,'') || ' ' || coalesce(s.description,'') || ' ' || coalesce((select string_agg(c.human_text, ' ') from scholarship.criteria c where c.scholarship_id = s.id), '') txt
      from scholarship.scholarships s left join catalogue.providers p on p.id = s.provider_id left join ref.countries k on k.id = p.country_id
     where s.lifecycle_status = 'active'
       and not exists (select 1 from scholarship.nationality_readings a where a.scholarship_id = s.id and a.reader_version = 'scholarship-nationality-v1' and a.read_at >= s.updated_at
                         and a.read_at >= coalesce((select max(c.created_at) from scholarship.criteria c where c.scholarship_id = s.id), '-infinity'::timestamptz))
     order by (select a.read_at from scholarship.nationality_readings a where a.scholarship_id = s.id) nulls first, s.id
     limit 150),
  m as (
    select t.id, x.code,
           coalesce(substring(t.txt from ('(?i)\m(?:citizens?|nationals?|passport holders?|permanent residents?|residents?|students?|applicants?|candidates?|scholars?) (?:of|from) (?:the )?(?:' || x.names || ')\M')),
                    substring(t.txt from ('(?i)\m(?:' || coalesce(nullif(x.demonyms, ''), 'ZZZZ') || ') (?:citizens?|nationals?|passport holders?|students?|applicants?|candidates?)\M')),
                    substring(t.txt from ('(?i)\m(?:' || x.names || ') (?:citizens?|nationals?|passport holders?)\M'))) phrase
      from t, ref.nationality_terms x
     where x.code <> coalesce(t.study_country, 'AU') and not (x.code = 'AU' and coalesce(t.study_country, 'AU') in ('AU', 'NZ')) and not (x.code = 'NZ' and t.study_country = 'AU')),
  r as (
    select t.id, coalesce((select array_agg(distinct q.code order by q.code) from (select m.code from m where m.id = t.id and m.phrase is not null
                                   union select v.c from scholarship.criteria cr, unnest(cr.value_codes) v(c)  -- F-SCH redesign: verified extraction codes
                                    where cr.scholarship_id = t.id and cr.status = 'active' and cr.criterion_type = 'nationality'
                                      and cr.value_json->>'by' = 'sch-extract-v3' and cr.value_json->>'role' = 'eligible') q), '{}'::text[]) codes,
           coalesce((select jsonb_object_agg(m.code, m.phrase) from m where m.id = t.id and m.phrase is not null), '{}'::jsonb) phrases
      from t),
  up as (
    insert into scholarship.nationality_readings(scholarship_id, codes, phrases, reader_version, read_at)
    select r.id, r.codes, r.phrases, 'scholarship-nationality-v1', now() from r
    on conflict (scholarship_id) do update set codes = excluded.codes, phrases = excluded.phrases, reader_version = excluded.reader_version, read_at = now()
    returning scholarship_id, codes)
  select count(*), count(*) filter (where cardinality(codes) > 0) into v_read, v_with from up;
  update scholarship.scholarships s set nationalities = a.codes, updated_at = now() from scholarship.nationality_readings a where a.scholarship_id = s.id and s.lifecycle_status = 'active' and s.nationalities is distinct from a.codes  and not exists (select 1 from pipeline.manual_locks k where k.entity = 'scholarship' and k.entity_id = s.id and k.field = 'nationalities');
  get diagnostics v_changed = row_count;
  if v_changed > 0 then
    insert into pipeline.admin_control_events(area, action, target, detail, actor)
    values ('scholarships', 'nationality_read', 'Nationality read from each scholarship''s wording', jsonb_build_object('read', v_read, 'with_nationality', v_with, 'changed', v_changed, 'decision', 'Decision 246'), '63ba56cb-48d4-4169-98c2-7c4d1f72925b');
  end if;
  return jsonb_build_object('read', v_read, 'with_nationality', v_with, 'changed', v_changed);
end $$;


ALTER FUNCTION "security"."scholarship_nationality_read_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_owner_check_v1"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_new int; v_done int;
begin
  update pipeline.scholarship_owner_proposals o set state = 'decided', decided_at = coalesce(r.decided_at, now()),
         decision = jsonb_build_object('status', r.status, 'note', r.note, 'decided_by', r.decided_by)
    from pipeline.scholarship_ai_reviews r where r.id = o.review_id and o.state = 'proposed' and r.status <> 'pending';
  get diagnostics v_done = row_count;
  with rv as (
    select r.id, r.candidate_id, r.provider_id, r.url, r.storage_path, r.extraction_ids, c.source, c.title, c.read_status, c.evidence_id,
           c.facts->>'h1' h1, c.facts->>'page_title' page_title,
           coalesce((select nullif(e.answer->>'name', '') from pipeline.scholarship_ai_extractions e where e.id = r.extraction_ids[array_upper(r.extraction_ids, 1)]),
                    nullif(c.facts->>'h1', ''), nullif(btrim(regexp_replace(coalesce(c.title, ''), '\s+[-|]\s+[^-|]*$', '')), ''), r.url) named
      from pipeline.scholarship_ai_reviews r left join pipeline.scholarship_page_candidates c on c.id = r.candidate_id
     where r.status = 'pending' and security.third_party_host_v1(r.url)
       and not exists (select 1 from pipeline.scholarship_owner_proposals o where o.review_id = r.id)
     order by r.id limit greatest(1, coalesce(p_limit, 1))),
  raw as (
    select p.id, btrim(regexp_replace(x, '\s+(pty\.?\s*ltd\.?|limited|ltd\.?|inc\.?)$', '', 'i')) part
      from catalogue.providers p, regexp_split_to_table(coalesce(p.display_name, '') || ',' || coalesce(p.canonical_name, ''), '\s*[,()]\s*') x
     where p.lifecycle_status = 'active'
    union select a.provider_id, a.alias from catalogue.provider_aliases a where a.valid_to is null),
  parts as (select id, part from raw union select id, btrim(regexp_replace(part, '\s+(college|university|institute|academy)$', '', 'i')) from raw),
  -- a name part must hold one distinctive word (not a place, an organisation type or a common word)
  ok as (select * from parts where length(part) >= 3 and exists (select 1 from regexp_split_to_table(lower(part), '[^a-z0-9]+') w where w <> '' and w not in (
           'the', 'of', 'and', 'for', 'international', 'australia', 'australian', 'sydney', 'melbourne', 'brisbane', 'perth', 'adelaide', 'hobart', 'darwin',
           'canberra', 'queensland', 'victoria', 'victorian', 'college', 'university', 'institute', 'academy', 'school', 'education', 'group', 'training',
           'english', 'language', 'centre', 'center', 'campus', 'nz', 'new', 'zealand', 'global', 'business', 'technology', 'management', 'studies', 'study',
           'services', 'holdings', 'trust', 'pty', 'ltd'))),
  m as (select rv.id rid, pt.id pid, max(length(pt.part)) l from rv join ok pt on pt.id <> rv.provider_id
          and security.coverage_country(pt.id) is not distinct from security.coverage_country(rv.provider_id)
          and rv.named ~* ('(^|\W)' || regexp_replace(pt.part, '([.^$*+?()\[\]{}|\\-])', '\\\1', 'g') || '(\W|$)') group by 1, 2),
  ins as (
    insert into pipeline.scholarship_owner_proposals(review_id, candidate_id, holder_provider_id, url, host, finding, named, owner_candidates, proposed_action, evidence)
    select rv.id, rv.candidate_id, rv.provider_id, rv.url, security.site_host_v1(rv.url), 'directory_page', rv.named,
           coalesce((select jsonb_agg(jsonb_build_object('provider_id', p.id, 'name', coalesce(p.display_name, p.canonical_name), 'website', p.website,
                       'holds_same_name', (select coalesce(jsonb_agg(s.id), '[]'::jsonb) from scholarship.scholarships s where s.provider_id = p.id and s.lifecycle_status = 'active'
                                             and security.scholarship_series_key_v1(s.name) = security.scholarship_series_key_v1(rv.named))) order by m.l desc)
                       from m join catalogue.providers p on p.id = m.pid where m.rid = rv.id), '[]'::jsonb),
           'refuse_from_holder',
           jsonb_build_object('holder', (select coalesce(p.display_name, p.canonical_name) from catalogue.providers p where p.id = rv.provider_id),
                              'holder_website', (select p.website from catalogue.providers p where p.id = rv.provider_id),
                              'holder_host', (select security.site_host_v1(p.website) from catalogue.providers p where p.id = rv.provider_id),
                              'page_host', security.site_host_v1(rv.url), 'directory_site', true,
                              'found_by', rv.source, 'discovery_method', (select d.method from pipeline.scholarship_discovery_providers d where d.provider_id = rv.provider_id),
                              'holder_candidates', (select count(*) from pipeline.scholarship_page_candidates c where c.provider_id = rv.provider_id),
                              'holder_candidates_on_directory_sites', (select count(*) from pipeline.scholarship_page_candidates c where c.provider_id = rv.provider_id and security.third_party_host_v1(c.url)),
                              'title', rv.title, 'page_title', rv.page_title, 'h1', rv.h1, 'read_status', rv.read_status,
                              'evidence_id', rv.evidence_id, 'storage_path', rv.storage_path, 'extraction_ids', rv.extraction_ids)
      from rv
    on conflict (review_id) do nothing
    returning 1)
  select count(*) into v_new from ins;
  return jsonb_build_object('proposed', v_new, 'decided', v_done,
                            'open', (select count(*) from pipeline.scholarship_owner_proposals where state = 'proposed'));
end $_$;


ALTER FUNCTION "security"."scholarship_owner_check_v1"("p_limit" integer) OWNER TO "postgres";


