CREATE OR REPLACE FUNCTION "security"."scholarship_page_kind_v1"("p_url" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  -- the reason the page is not the scholarship's own live page, or null
  select case
    when lower(regexp_replace(coalesce(p_url, ''), '^https?://([^/?#]+).*$', '\1')) ~ '(^|[.-])(sb[0-9]*|sandbox|staging|stage|uat|test|dev|preview)([.-]|$)'
      then 'not the provider''s live site (a test or sandbox address)'
    when lower(regexp_replace(coalesce(p_url, ''), '^https?://[^/]+', '')) ~ '(scholarships?|awards?|prizes?|bursar(y|ies))[-_](winners|recipients)(\.[a-z]+)?/?$'
      or lower(regexp_replace(coalesce(p_url, ''), '^https?://[^/]+', '')) ~ '/(congratulations|felicitations)[-_/]'
      then 'a winners or recipients page, not the scholarship'
    when lower(regexp_replace(coalesce(p_url, ''), '^https?://[^/]+', '')) ~ '(^|[/_-])(news|newsletters?|nouvelles|actualites|media-releases?|press-releases?)([/._-]|$)'
      then 'a news item or newsletter, not the scholarship page'
  end
$_$;


ALTER FUNCTION "security"."scholarship_page_kind_v1"("p_url" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_page_kind_v1"("p_url" "text") IS 'CF-247 worker v1.0.2: why a scholarship''s page is not its own live page (test or sandbox address, winners list, news item), or null.';



CREATE OR REPLACE FUNCTION "security"."scholarship_page_match_v1"("p_scholarship_id" "uuid", "p_url" "text", "p_basis" "text", "p_candidate_id" bigint DEFAULT NULL::bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline', 'security'
    AS $$
declare s record; v_site text; v_norm text:=security.scholarship_url_norm(p_url);
begin
  select * into s from scholarship.scholarships where id=p_scholarship_id for update;
  if s.id is null or s.lifecycle_status<>'active' then return jsonb_build_object('matched',false,'reason','not active'); end if;
  if not security.reference_url_has_use(coalesce(s.source_url,''), 'scholarship_placeholder') then return jsonb_build_object('matched',false,'reason','already has a provider source'); end if;
  -- a page already read for it stays, except a discovered page the reader rejected (it did not name the scholarship)
  if exists (select 1 from pipeline.scholarship_pages where scholarship_id=s.id and not (url_source='discovered' and read_status in ('name_mismatch','robots_disallowed','gone')))
    then return jsonb_build_object('matched',false,'reason','already has a page'); end if;
  select coalesce(site_origin, website) into v_site from pipeline.scholarship_discovery_providers where provider_id=s.provider_id;
  if v_site is null or not security.url_on_provider_sites(p_url, s.provider_id) or security.reference_url_has_use(p_url, 'scholarship_placeholder') then return jsonb_build_object('matched',false,'reason','not on the provider site'); end if;
  if exists (select 1 from pipeline.scholarship_pages sp where security.scholarship_url_norm(sp.url)=v_norm)
     or exists (select 1 from scholarship.scholarships x where x.id<>s.id and security.scholarship_url_norm(x.source_url)=v_norm)
     or exists (select 1 from scholarship.identifiers i where i.scheme='first_party_detail_url' and security.scholarship_url_norm(i.identifier_value)=v_norm)
    then return jsonb_build_object('matched',false,'reason','page already belongs to another scholarship'); end if;
  delete from pipeline.scholarship_pages where scholarship_id=s.id and url_source='discovered' and read_status in ('name_mismatch','robots_disallowed','gone');
  insert into pipeline.scholarship_pages(scholarship_id,url,url_source,candidate_id,next_read_at) values (s.id,p_url,'discovered',p_candidate_id,now());
  if p_candidate_id is not null then
    update pipeline.scholarship_page_candidates set matched_scholarship_id=s.id, match_basis=p_basis, matched_at=now() where id=p_candidate_id;
  end if;
  insert into pipeline.scholarship_sweep_changes(scholarship_id,field,before_value,after_value)
  values (s.id,'provider_page_matched',jsonb_build_object('source_url',s.source_url),jsonb_build_object('url',p_url,'basis',p_basis,'candidate_id',p_candidate_id));
  return jsonb_build_object('matched',true);
end $$;


ALTER FUNCTION "security"."scholarship_page_match_v1"("p_scholarship_id" "uuid", "p_url" "text", "p_basis" "text", "p_candidate_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_page_names_award_v1"("p_url" "text", "p_name" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  with seg as (select lower(regexp_replace(regexp_replace(regexp_replace(coalesce(p_url, ''), '[?#].*$', ''), '/+$', ''), '^.*/', '')) s),
  w as (select distinct t from regexp_split_to_table(lower(coalesce(p_name, '')), '[^a-z0-9]+') t
         where length(t) >= 4 and t not in ('scholarship', 'scholarships', 'award', 'awards', 'bursary', 'bursaries', 'grant', 'grants', 'prize', 'prizes',
                                            'with', 'from', 'that', 'this', 'their', 'university', 'program', 'programme'))
  select case when (select count(*) from w) = 0 then false
              else (select count(*) from w, seg where seg.s ~ ('(^|[^a-z0-9])' || w.t || '([^a-z0-9]|$)')) >= least(2, (select count(*) from w)) end
$_$;


ALTER FUNCTION "security"."scholarship_page_names_award_v1"("p_url" "text", "p_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_page_names_award_v1"("p_url" "text", "p_name" "text") IS 'F-SCH.01 re-admission: true when the last path segment of the page names the award (at least two of its distinctive words, or all when fewer).';



CREATE OR REPLACE FUNCTION "security"."scholarship_page_tier_candidates"() RETURNS TABLE("id" "uuid", "source_id" "uuid", "evidence_id" "uuid", "up_to" boolean, "pcts" numeric[], "amts" numeric[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline'
    AS $$
  with src as (
    select s.id, s.source_id, sp.evidence_id,
           coalesce((sp.facts->'value'->>'up_to')::boolean, false) up_to,
           coalesce((select array_agg(x::numeric order by x::numeric) from jsonb_array_elements_text(coalesce(sp.facts->'value'->'percentages', '[]'::jsonb)) x), '{}'::numeric[]) pcts,
           coalesce((select array_agg(x::numeric order by x::numeric) from jsonb_array_elements_text(coalesce(sp.facts->'value'->'amounts', '[]'::jsonb)) x), '{}'::numeric[]) amts
      from scholarship.scholarships s join pipeline.scholarship_pages sp on sp.scholarship_id = s.id
     where s.lifecycle_status = 'active' and (s.award_value_type is null or s.award_value_type = 'text_only')
       and sp.read_status = 'read' and sp.facts->'value'->>'type' = 'ambiguous' and coalesce((sp.facts->'value'->>'foreign_currency')::boolean, false) = false
       and not exists (select 1 from scholarship.award_tiers t where t.scholarship_id = s.id)
       and not exists (select 1 from pipeline.manual_locks k where k.entity = 'scholarship' and k.entity_id = s.id and k.field in ('award_amount', 'award_percentage', 'award_value_type', 'award_value_text')))
  select src.id, src.source_id, src.evidence_id, src.up_to, src.pcts, src.amts from src
   where cardinality(src.pcts) + cardinality(src.amts) >= 1 and cardinality(src.pcts) <= 6 and cardinality(src.amts) <= 6
$$;


ALTER FUNCTION "security"."scholarship_page_tier_candidates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_pilot_member_v1"("p_provider_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select p_provider_id is not null and exists (
    select 1 from pipeline.platform_toolset_settings s, jsonb_array_elements_text(case when jsonb_typeof(s.value) = 'array' then s.value else '[]'::jsonb end) x(id)
     where s.toolset_key = 'pipeline' and s.key = 'scholarship.pilot_provider_ids' and lower(btrim(x.id)) = p_provider_id::text)
$$;


ALTER FUNCTION "security"."scholarship_pilot_member_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_pilot_report_v1"() RETURNS TABLE("provider_id" "uuid", "provider_name" "text", "provider_type" "text", "country" "text", "listed" boolean, "in_scope" boolean, "admission_ok" boolean, "search_ok" boolean, "legitimacy_ok" boolean, "active_courses" integer, "discovery_status" "text", "discovery_attempts" integer, "candidates" integer, "pages_read" integer, "pages_failed" integer, "admitted" integer, "refused_not_university" integer, "wrong_provider" integer, "unsupported_eligibility" integer, "firecrawl_credits" numeric, "ai_usd" numeric, "stop" boolean, "stop_reasons" "text"[])
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with cfg as (
    select coalesce(security.scholarship_pilot_since_v1(), now()) since,
           security.pipeline_num_v1('scholarship.pilot_stop_wrong_provider_max', 0) wrong_max,
           security.pipeline_num_v1('scholarship.pilot_stop_unsupported_max', 0) unsup_max,
           security.pipeline_num_v1('scholarship.pilot_stop_failed_pct', 50) failed_pct,
           security.pipeline_num_v1('scholarship.pilot_stop_min_reads', 10) min_reads),
  who as (  -- the listed providers; after wider activation also every non-university provider with an admission since the pilot started
    select p.id from catalogue.providers p where security.scholarship_pilot_member_v1(p.id)
    union
    select l.provider_id from pipeline.scholarship_admission_log l, cfg
     where not security.scholarship_flag_v1('scholarship.pilot_only', true) and l.action = 'admitted' and l.at >= cfg.since
       and not security.scholarship_university(l.provider_id)),
  adm as (  -- records admitted since the pilot started, with their page facts and Layer 4 decisions
    select l.provider_id, s.id sid, s.source_url, s.provider_id rec_provider, s.audience, s.publication_status, sp.facts,
           exists (select 1 from pipeline.layer4_block_decisions b where b.entity_type = 'scholarship' and b.entity_id = s.id
                    and b.reason_code ~* 'provider') or
           exists (select 1 from pipeline.layer4_publication_decisions b where b.entity_type = 'scholarship' and b.entity_id = s.id
                    and b.reason_code ~* 'provider') l4_provider,
           exists (select 1 from pipeline.layer4_block_decisions b where b.entity_type = 'scholarship' and b.entity_id = s.id
                    and b.reason_code ~* '(eligib|audience|international|nationalit)') or
           exists (select 1 from pipeline.layer4_publication_decisions b where b.entity_type = 'scholarship' and b.entity_id = s.id
                    and b.reason_code ~* '(eligib|audience|international|nationalit)') l4_eligibility
      from pipeline.scholarship_admission_log l join who w on w.id = l.provider_id cross join cfg
      join scholarship.scholarships s on s.id = l.scholarship_id
      left join pipeline.scholarship_pages sp on sp.scholarship_id = s.id
     where l.action = 'admitted' and l.at >= cfg.since),
  rows as (
    select p.id, coalesce(p.display_name, p.canonical_name) pname, t.code tcode, k.iso_alpha2::text cc,
           security.scholarship_pilot_member_v1(p.id) listed, security.scholarship_pilot_scope_v1(p.id) in_scope,
           security.scholarship_admission_provider_ok_v1(p.id) adm_ok, security.fc_sch_eligible_v1(p.id) search_ok, security.scholarship_legitimacy_v1(p.id) legit,
           (select count(*) from catalogue.courses co where co.provider_id = p.id and co.lifecycle_status = 'active')::int courses,
           d.status dstatus, d.attempts dattempts,
           (select count(*) from pipeline.scholarship_page_candidates x where x.provider_id = p.id)::int cands,
           (select count(*) from pipeline.scholarship_page_candidates x where x.provider_id = p.id and x.read_at >= cfg.since and x.read_status = 'read')::int pread,
           (select count(*) from pipeline.scholarship_page_candidates x where x.provider_id = p.id and x.read_at >= cfg.since and x.read_status in ('failed', 'scrape_failed', 'blocked'))::int pfail,
           (select count(*) from adm a where a.provider_id = p.id)::int admitted,
           (select count(*) from pipeline.scholarship_page_candidates x where x.provider_id = p.id and x.admit_status = 'rejected'
               and 'not a university provider in a scholarship country' = any (x.admit_reasons))::int refused_nu,
           (select count(*) from adm a where a.provider_id = p.id
               and (a.rec_provider is distinct from a.provider_id or not security.url_on_provider_sites(a.source_url, a.provider_id)
                    or security.third_party_host_v1(coalesce(a.source_url, '')) or a.l4_provider))::int wrong,
           (select count(*) from adm a where a.provider_id = p.id
               -- F-SCH.01 (12 Nov 2026): international_and_domestic (or both) is open to international students; a record withdrawn by a later
               -- check is no longer live and is not counted (its page facts are the later read's, not the admitted ones)
               and a.publication_status is distinct from 'withdrawn'
               and (coalesce(a.audience, '') not in ('international', 'international_and_domestic', 'both') or a.facts is null or a.l4_eligibility
                    or coalesce((a.facts->'admission'->>'international_explicit')::boolean, false) is not true
                    or coalesce((a.facts->'admission'->>'offered')::boolean, false) is not true
                    or coalesce((a.facts->'admission'->>'detail_page')::boolean, false) is not true))::int unsup,
           (select coalesce(sum(u.units), 0) from pipeline.coverage_vendor_usage u where u.provider_id = p.id and u.purpose like 'sch\_%' and u.at >= cfg.since) fc,
           (select coalesce(sum(e.cost_usd), 0) from pipeline.scholarship_ai_extractions e where e.provider_id = p.id and e.at >= cfg.since) ai,
           cfg.*
      from who w join catalogue.providers p on p.id = w.id cross join cfg
      join ref.countries k on k.id = p.country_id left join ref.provider_types t on t.id = p.provider_type_id
      left join pipeline.scholarship_discovery_providers d on d.provider_id = p.id)
  select r.id, r.pname, r.tcode, r.cc, r.listed, r.in_scope, r.adm_ok, r.search_ok, r.legit, r.courses, r.dstatus, r.dattempts, r.cands, r.pread, r.pfail,
         r.admitted, r.refused_nu, r.wrong, r.unsup, r.fc, r.ai,
         cardinality(z.reasons) > 0, z.reasons
    from rows r cross join lateral (select array_remove(array[
           case when r.wrong > r.wrong_max then 'wrong-provider admission (' || r.wrong || ')' end,
           case when r.unsup > r.unsup_max then 'admission without eligibility evidence (' || r.unsup || ')' end,
           case when r.pread + r.pfail >= r.min_reads and r.pfail * 100.0 / (r.pread + r.pfail) > r.failed_pct
                then 'failed page reads (' || r.pfail || ' of ' || (r.pread + r.pfail) || ')' end,
           case when r.dstatus = 'failed' or coalesce(r.dattempts, 0) >= 3 then 'discovery stuck (' || coalesce(r.dstatus, '') || ')' end], null) reasons) z
   order by cardinality(z.reasons) > 0 desc, r.cc, r.pname
$$;


ALTER FUNCTION "security"."scholarship_pilot_report_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_pilot_scope_v1"("p_provider_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select not security.scholarship_flag_v1('scholarship.pilot_only', true) or security.scholarship_pilot_member_v1(p_provider_id)
$$;


ALTER FUNCTION "security"."scholarship_pilot_scope_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_pilot_since_v1"() RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select s.updated_at from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'scholarship.pilot_provider_ids'
$$;


ALTER FUNCTION "security"."scholarship_pilot_since_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_pilot_start_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_since timestamptz := security.scholarship_pilot_since_v1(); v_q int := 0; v_due int := 0; v_re int := 0; v_adm int := 0; c record; r jsonb;
begin
  if not (security.scholarship_flag_v1('scholarship.non_university_admission', false) or security.scholarship_flag_v1('scholarship.legitimacy_checks_on', false))
     or not exists (select 1 from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'scholarship.pilot_provider_ids'
                     and jsonb_typeof(s.value) = 'array' and jsonb_array_length(s.value) > 0) then
    return jsonb_build_object('pilot', false);
  end if;
  -- a listed provider without a discovery row is queued (same gates as the refill: eligible, own website, search on, published)
  insert into pipeline.scholarship_discovery_providers(provider_id, website, priority, reason, status)
  select p.id, btrim(p.website), 0, 'scholarship_pilot', 'pending'
    from catalogue.providers p join ref.countries k on k.id = p.country_id
   where security.scholarship_pilot_member_v1(p.id) and p.lifecycle_status = 'active' and k.scholarship_ingestion_enabled
     and nullif(btrim(coalesce(p.website, '')), '') is not null and not security.third_party_host_v1(p.website)
     and security.fc_sch_eligible_v1(p.id) and not security.provider_sch_search_off_v1(p.id)
     and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id)
     and not exists (select 1 from pipeline.scholarship_discovery_providers d where d.provider_id = p.id)
  on conflict do nothing;
  get diagnostics v_q = row_count;
  -- one fresh discovery after the list was saved: first in the order, due now (a held or not-yet-due row of a listed provider)
  update pipeline.scholarship_discovery_providers d set tier = security.fc_provider_tier_v1(d.provider_id), next_discover_at = now(), updated_at = now()
   where security.scholarship_pilot_member_v1(d.provider_id) and d.status in ('pending', 'deferred', 'mapped', 'empty')
     and coalesce(d.discovered_at, '-infinity') < v_since and coalesce(d.next_discover_at, '-infinity') > now();
  get diagnostics v_due = row_count;
  -- pages already read and refused only because the provider was not a university: admitted again from their stored facts
  for c in select x.id from pipeline.scholarship_page_candidates x
            where security.scholarship_pilot_member_v1(x.provider_id) and x.admit_status = 'rejected'
              and x.admit_reasons = array['not a university provider in a scholarship country'] and x.read_status = 'read'
              and x.admitted_scholarship_id is null and x.matched_scholarship_id is null
              and x.read_at > now() - make_interval(days => security.pipeline_num_v1('reread.scholarship_candidate_days', 90)::int)
              and security.scholarship_admission_provider_ok_v1(x.provider_id)
            order by x.provider_id, x.id limit greatest(0, security.pipeline_num_v1('batch.scholarship_pilot_readmit', 50)::int) loop
    r := security.scholarship_admit_from_provider_page_v1(c.id);
    v_re := v_re + 1;
    if (r->>'admitted')::boolean then v_adm := v_adm + 1; end if;
  end loop;
  return jsonb_build_object('pilot', true, 'since', v_since, 'queued', v_q, 'due', v_due, 'readmitted', v_re, 'admitted', v_adm);
end $$;


ALTER FUNCTION "security"."scholarship_pilot_start_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_pilot_stop_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  with r as (select * from security.scholarship_pilot_report_v1()),
  t as (select count(*) providers, coalesce(sum(r.admitted), 0) admitted, coalesce(sum(r.wrong_provider), 0) wrong, coalesce(sum(r.unsupported_eligibility), 0) unsup,
               coalesce(sum(r.firecrawl_credits), 0) fc, coalesce(sum(r.ai_usd), 0) ai,
               coalesce(array_agg(r.provider_name || ': ' || array_to_string(r.stop_reasons, '; ')) filter (where r.stop), '{}') provider_stops from r),
  d as (select greatest(extract(epoch from now() - coalesce(security.scholarship_pilot_since_v1(), now())) / 86400.0, 1.0) days,  -- fixed: seconds in a day
               security.fc_setting_num_v1('daily_share_scholarships', 3500) * security.pipeline_num_v1('scholarship.pilot_stop_fc_share_pct', 20) / 100.0 fc_limit,
               coalesce((select (s.value #>> '{}')::numeric from pipeline.platform_toolset_settings s where s.toolset_key = 'openrouter' and s.key = 'guard_scholarship_ai'), 0)
                 * security.pipeline_num_v1('scholarship.pilot_stop_ai_share_pct', 20) / 100.0 ai_limit)
  select jsonb_build_object('since', security.scholarship_pilot_since_v1(), 'days', round(d.days, 2), 'providers', t.providers, 'admitted', t.admitted,
           'wrong_provider', t.wrong, 'unsupported_eligibility', t.unsup,
           'firecrawl_per_day', round(t.fc / d.days, 1), 'firecrawl_limit_per_day', round(d.fc_limit, 1),
           'ai_usd_per_day', round(t.ai / d.days, 2), 'ai_limit_usd_per_day', round(d.ai_limit, 2),
           'stop', cardinality(t.provider_stops) > 0 or t.fc / d.days > d.fc_limit or t.ai / d.days > d.ai_limit,
           'reasons', to_jsonb(t.provider_stops
              || case when t.fc / d.days > d.fc_limit then array['Firecrawl ' || round(t.fc / d.days) || ' credits a day over the pilot share ' || round(d.fc_limit)] else '{}'::text[] end
              || case when t.ai / d.days > d.ai_limit then array['AI US$' || round(t.ai / d.days, 2) || ' a day over the pilot share US$' || round(d.ai_limit, 2)] else '{}'::text[] end))
    from t, d
$_$;


ALTER FUNCTION "security"."scholarship_pilot_stop_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_provider_coverage_refresh_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int;
begin
  delete from pipeline.scholarship_provider_coverage;
  insert into pipeline.scholarship_provider_coverage (provider_id, provider, country, classified_university, provider_type, website, provider_publication,
         discovery_status, discovery_method, map_urls, kept_pages, discovered_at, next_discover_at, discovery_error, search_off, search_eligible,
         candidates, candidates_read, candidates_unread, candidates_admitted, candidates_rejected, reject_reasons, n_domestic, n_intl_unknown,
         listing_pages, listing_complete, listing_failed, scholarships_active, scholarships_published, scholarships_unpublished, sample_published_sources,
         coverage_states, layer4_open, layer4_facts, ai_reviews_pending, firecrawl_credits_30d, next_retry, disposition, next_action)
  select provider_id, provider, country, classified_university, provider_type, website, provider_publication,
         discovery_status, discovery_method, map_urls, kept_pages, discovered_at, next_discover_at, discovery_error, search_off, search_eligible,
         candidates, candidates_read, candidates_unread, candidates_admitted, candidates_rejected, reject_reasons, n_domestic, n_intl_unknown,
         listing_pages, listing_complete, listing_failed, scholarships_active, scholarships_published, scholarships_unpublished, sample_published_sources,
         coverage_states, layer4_open, layer4_facts, ai_reviews_pending, firecrawl_credits_30d, next_retry, disposition, next_action
    from (
with univ as materialized (select p.id from catalogue.providers p where security.scholarship_university(p.id)),
pop as (
  select id from univ
  union select provider_id from pipeline.scholarship_discovery_providers
  union select provider_id from pipeline.scholarship_page_candidates
  union select provider_id from pipeline.scholarship_listing_pages
  union select provider_id from scholarship.scholarships where provider_id is not null),
cand as (
  select k.provider_id, count(*) n,
         count(*) filter (where k.read_status in ('read', 'too_thin')) n_read,
         count(*) filter (where k.read_status is null or k.read_status in ('pending', 'queued', 'waiting_scraper', 'failed')) n_unread,
         count(*) filter (where k.admit_status = 'admitted') n_admitted,
         count(*) filter (where k.admit_status = 'rejected') n_rejected,
         min(k.next_read_at) filter (where k.read_status is distinct from 'read') next_read
    from pipeline.scholarship_page_candidates k group by 1),
rej as (
  select provider_id, string_agg(r || ' ' || n, '; ' order by n desc) reasons,
         sum(n) filter (where r in ('domestic_only', 'eligibility_domestic')) n_domestic,
         sum(n) filter (where r in ('international_not_stated')) n_intl_unknown
    from (select provider_id, r, count(*) n from pipeline.scholarship_page_candidates, unnest(admit_reasons) r where admit_status = 'rejected' group by 1, 2) x
   group by 1),
lst as (
  select provider_id, count(*) n, count(*) filter (where completed_at is not null) n_complete, count(*) filter (where status = 'failed') n_failed
    from pipeline.scholarship_listing_pages group by 1),
sch as (
  select provider_id, count(*) filter (where lifecycle_status = 'active') n_active,
         count(*) filter (where lifecycle_status = 'active' and publication_status = 'published') n_published,
         count(*) filter (where lifecycle_status = 'active' and publication_status <> 'published') n_held,
         (array_agg(source_url order by updated_at desc) filter (where lifecycle_status = 'active' and publication_status = 'published'))[1:3] sample_published
    from scholarship.scholarships group by 1),
cov as (
  select provider_id, string_agg(state || ' ' || n, '; ' order by n desc) states, min(next_recovery_at) next_recovery
    from (select provider_id, state, count(*) n, min(next_recovery_at) next_recovery_at from pipeline.scholarship_coverage_items where present group by 1, 2) y group by 1),
l4 as (
  select split_part(entity, '|', 1)::uuid provider_id, count(*) n, string_agg(distinct missing_fact, ', ') facts
    from pipeline.layer4_interventions where lane like 'sch%' and status = 'awaiting_input' group by 1),
rv as (select provider_id, count(*) n from pipeline.scholarship_ai_reviews where status = 'pending' group by 1),
fc as (select provider_id, sum(units) units from pipeline.coverage_vendor_usage where purpose like 'sch%' and at > now() - interval '30 days' group by 1),
base as (
  select p.id provider_id, coalesce(p.display_name, p.canonical_name) provider, c.iso_alpha2 country, (p.id in (select u.id from univ u)) classified_university,
         t.code provider_type, p.website, p.publication_status provider_publication,
         d.status discovery_status, d.method discovery_method, d.url_count map_urls, d.kept_count kept_pages, d.discovered_at, d.next_discover_at,
         left(d.last_error, 160) discovery_error, security.provider_sch_search_off_v1(p.id) search_off, security.fc_sch_eligible_v1(p.id) search_eligible,
         coalesce(k.n, 0) candidates, coalesce(k.n_read, 0) candidates_read, coalesce(k.n_unread, 0) candidates_unread,
         coalesce(k.n_admitted, 0) candidates_admitted, coalesce(k.n_rejected, 0) candidates_rejected, r.reasons reject_reasons,
         coalesce(r.n_domestic, 0) n_domestic, coalesce(r.n_intl_unknown, 0) n_intl_unknown,
         coalesce(l.n, 0) listing_pages, coalesce(l.n_complete, 0) listing_complete, coalesce(l.n_failed, 0) listing_failed,
         coalesce(s.n_active, 0) scholarships_active, coalesce(s.n_published, 0) scholarships_published, coalesce(s.n_held, 0) scholarships_unpublished,
         array_to_string(s.sample_published, ' ') sample_published_sources,
         cv.states coverage_states, coalesce(i.n, 0) layer4_open, i.facts layer4_facts, coalesce(v.n, 0) ai_reviews_pending,
         coalesce(f.units, 0) firecrawl_credits_30d,
         least(d.next_discover_at, k.next_read, cv.next_recovery) next_retry
    from pop join catalogue.providers p on p.id = pop.id join ref.countries c on c.id = p.country_id
    left join ref.provider_types t on t.id = p.provider_type_id
    left join pipeline.scholarship_discovery_providers d on d.provider_id = p.id
    left join cand k on k.provider_id = p.id left join rej r on r.provider_id = p.id left join lst l on l.provider_id = p.id
    left join sch s on s.provider_id = p.id left join cov cv on cv.provider_id = p.id left join l4 i on i.provider_id = p.id
    left join rv v on v.provider_id = p.id left join fc f on f.provider_id = p.id)
select b.*,
       case when scholarships_published > 0 then 'published'
            when scholarships_active > 0 then 'admitted_not_published'
            when layer4_open > 0 or ai_reviews_pending > 0 then 'protected_hold'
            when candidates_unread > 0 or listing_failed > 0 or (listing_pages > listing_complete) then 'source_found_unprocessed'
            when candidates > 0 and n_domestic > 0 and n_domestic >= n_intl_unknown then 'current_awards_ineligible_or_domestic'
            when candidates > 0 then 'evidence_insufficient'
            when nullif(btrim(coalesce(website, '')), '') is null then 'website_unknown'
            when discovery_status in ('mapped', 'empty') then 'searched_none_evidenced'
            else 'not_yet_attempted_or_vendor_failure' end disposition,
       case when scholarships_published > 0 then 'keep re-reading on the cadence; complete fields'
            when scholarships_active > 0 then 'complete the publishing checks (value, audience, round) from the stored page'
            when layer4_open > 0 or ai_reviews_pending > 0 then 'Layer 4: ' || coalesce(layer4_facts, 'AI review question') || ' (reviewer)'
            when candidates_unread > 0 then 'read the unread candidate pages'
            when listing_failed > 0 or listing_pages > listing_complete then 'traverse the listing pages'
            when candidates > 0 and n_domestic > 0 and n_domestic >= n_intl_unknown then 'none needed while the current awards are domestic-only; re-map on the cadence'
            when candidates > 0 then 'eligibility reader on the award pages; re-map the official scholarship section'
            when nullif(btrim(coalesce(website, '')), '') is null then 'find the official website'
            when discovery_status in ('mapped', 'empty') then 're-map on the cadence; site search for the scholarship section'
            when not search_eligible then 'not eligible for scholarship search under the current rule'
            else 'map the official website' end next_action
  from base b
    ) z;
  get diagnostics v_n = row_count;
  return v_n;
end $$;


ALTER FUNCTION "security"."scholarship_provider_coverage_refresh_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_publication_review_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline', 'security'
    AS $$
declare v_ids uuid[];
begin
  select coalesce(array_agg(s.id),'{}') into v_ids
    from scholarship.scholarships s join security.scholarship_publishability_v1() p on p.scholarship_id=s.id
   where s.publication_status='published' and not p.publishable;
  if cardinality(v_ids)>0 then
    update scholarship.scholarships set publication_status='withdrawn', updated_at=now() where id=any(v_ids);
    insert into pipeline.scholarship_publication_batches(kind,approval_ref,scholarship_ids) values ('withdraw','Decision 139 automatic withdrawal',v_ids);
  end if;
  return jsonb_build_object('withdrawn',cardinality(v_ids));
end $$;


ALTER FUNCTION "security"."scholarship_publication_review_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_publish_batch_v1"("p_approval_ref" "text", "p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'pipeline', 'security'
    AS $$
declare v_ids uuid[]; v_before jsonb; v_after jsonb;
begin
  if coalesce(btrim(p_approval_ref),'')='' then raise exception 'approval reference required'; end if;
  select coalesce(array_agg(p.scholarship_id),'{}') into v_ids
    from security.scholarship_publishability_v1() p join scholarship.scholarships s on s.id=p.scholarship_id
   where p.publishable and coalesce(s.publication_status,'unpublished')<>'published'
     and not exists (select 1 from security.layer4_search_blocked_scholarships b where b.scholarship_id=s.id);
  if not p_apply or cardinality(v_ids)=0 then return jsonb_build_object('apply',p_apply,'eligible',cardinality(v_ids),'ids',to_jsonb(v_ids)); end if;
  v_before:=security.consumer_api_snapshot_v1();
  update scholarship.scholarships set publication_status='published', updated_at=now() where id=any(v_ids);
  insert into pipeline.scholarship_publication_batches(kind,approval_ref,scholarship_ids) values ('publish',p_approval_ref,v_ids);
  v_after:=security.consumer_api_snapshot_v1();
  insert into pipeline.consumer_api_baselines(label,snapshot) values
    ('before scholarship publication batch ('||cardinality(v_ids)||', Decision 139)',v_before),
    ('after scholarship publication batch ('||cardinality(v_ids)||', Decision 139)',v_after);
  return jsonb_build_object('apply',true,'published',cardinality(v_ids),'ids',to_jsonb(v_ids));
end $$;


