CREATE OR REPLACE FUNCTION "security"."scholarship_read_request_close_v1"("p_request" bigint, "p_extraction" bigint, "p_state" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare e pipeline.scholarship_ai_extractions%rowtype; r jsonb;
begin
  select * into e from pipeline.scholarship_ai_extractions where id = p_extraction;
  -- the same copy as a decided held item would repeat that decision (security.scholarship_ai_review_open_v1); a request never decides, so it is only recorded
  if exists (select 1 from pipeline.scholarship_ai_reviews x where x.status in ('admitted', 'refused') and x.url = e.url and coalesce(x.storage_path, '') = coalesce(e.storage_path, '')) then
    r := jsonb_build_object('linked', false, 'why', 'the same copy as a decided held item; not attached');
  else
    r := security.scholarship_ai_review_open_v1(p_extraction, p_reason);
  end if;
  update pipeline.scholarship_read_requests set state = p_state, finished_at = now(),
         outcome = jsonb_build_object('extraction', e.id, 'storage_path', e.storage_path, 'evidence_id', e.evidence_id, 'url', e.url, 'model', e.model_code,
                     'verdict', e.verdict, 'error', e.error, 'name', e.answer->>'name', 'audience', e.answer->>'audience', 'audience_quote', e.answer->>'audience_quote',
                     'offered', e.answer->>'offered', 'offered_quote', e.answer->>'offered_quote', 'dates_quote', e.answer->>'dates_quote',
                     'open_date', e.answer->>'open_date', 'close_date', e.answer->>'close_date', 'value', e.answer->'value', 'review', r)
   where id = p_request and state = 'queued';
  return r;
end $$;


ALTER FUNCTION "security"."scholarship_read_request_close_v1"("p_request" bigint, "p_extraction" bigint, "p_state" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_read_request_v1"("p_review" bigint, "p_fresh" boolean, "p_reason" "text", "p_approved_by" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v pipeline.scholarship_ai_reviews%rowtype; a record; v_why text; v_req bigint; v_q bigint;
        v_max int := security.pipeline_num_v1('scholarship.single_read_daily_max', 0)::int;
        v_today int;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'a single read is requested by a Platform Admin paste (postgres) only'; end if;
  if length(btrim(coalesce(p_reason, ''))) < 10 or length(btrim(coalesce(p_approved_by, ''))) < 3 or p_fresh is null then
    raise exception 'give who approved the read and when, the reason, and whether the page must be read fresh';
  end if;
  perform pg_advisory_xact_lock(hashtext('scholarship_read_request'));
  select * into v from pipeline.scholarship_ai_reviews where id = p_review for update;
  select count(*) into v_today from pipeline.scholarship_read_requests r where r.state <> 'refused'
     and r.requested_at >= (date_trunc('day', now() at time zone 'Australia/Melbourne') at time zone 'Australia/Melbourne');  -- fixed: the allowance is per Melbourne calendar day
  select * into a from security.scholarship_ai_active_v1();
  v_why := case
    when v.id is null then 'no such held item'
    when v.status <> 'pending' then 'the held item is ' || v.status
    when v.candidate_id is null and v.scholarship_id is null then 'the held item has no candidate or scholarship'
    when security.third_party_host_v1(v.url) then 'directory site: the page is not the provider''s own; decide the owner first'
    when exists (select 1 from pipeline.scholarship_owner_proposals o where o.review_id = v.id and o.state = 'proposed') then 'the owner is in question: decide the owner proposal first'
    when v.provider_id is not null and (security.provider_sch_search_off_v1(v.provider_id) or exists (select 1 from security.provider_hidden_v1 h where h.provider_id = v.provider_id))
      then 'the provider is not searched for scholarships or not published'
    when exists (select 1 from pipeline.scholarship_ai_queue q where q.state in ('queued', 'leased')
                  and ((v.candidate_id is not null and q.candidate_id = v.candidate_id) or (v.scholarship_id is not null and q.scholarship_id = v.scholarship_id)))
      then 'a read of this item is already queued'
    when a.model_code is null then 'scholarship AI is off'
    when v_today >= v_max then 'single reads are off or today''s allowance is used (scholarship.single_read_daily_max = ' || v_max || ')'
  end;
  insert into pipeline.scholarship_read_requests(review_id, candidate_id, scholarship_id, provider_id, url, fresh, reason, approved_by, state, before, outcome, finished_at)
  values (p_review, v.candidate_id, v.scholarship_id, v.provider_id, coalesce(v.url, '?'), p_fresh, btrim(p_reason), btrim(p_approved_by),
          case when v_why is null then 'queued' else 'refused' end,
          jsonb_build_object('status', v.status, 'reason', v.reason, 'extraction_ids', v.extraction_ids, 'storage_path', v.storage_path,
                             'candidate_storage_path', (select c.storage_path from pipeline.scholarship_page_candidates c where c.id = v.candidate_id)),
          case when v_why is not null then jsonb_build_object('why', v_why) end, case when v_why is not null then now() end)
  returning id into v_req;
  if v_why is not null then return jsonb_build_object('ok', false, 'request', v_req, 'why', v_why); end if;
  insert into pipeline.scholarship_ai_queue(model_code, prompt_version, run_kind, candidate_id, scholarship_id, provider_id, url, fresh_read, read_request_id)
  values (a.model_code, a.prompt_version, case when v.candidate_id is not null then 'admit' else 'reread' end, v.candidate_id,
          case when v.candidate_id is null then v.scholarship_id end, v.provider_id, v.url, p_fresh, v_req)
  returning id into v_q;
  update pipeline.scholarship_read_requests set queue_id = v_q where id = v_req;
  perform security.scholarship_ai_fire_v1();
  return jsonb_build_object('ok', true, 'request', v_req, 'queue_id', v_q, 'fresh', p_fresh, 'model', a.model_code);
end $$;


ALTER FUNCTION "security"."scholarship_read_request_v1"("p_review" bigint, "p_fresh" boolean, "p_reason" "text", "p_approved_by" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_read_request_v1"("p_review" bigint, "p_fresh" boolean, "p_reason" "text", "p_approved_by" "text") IS 'CF-247 (4 Nov 2026): the single-item read control for a held scholarship. Bounded to one held item, logged in pipeline.scholarship_read_requests, within scholarship.single_read_daily_max (0 = off). Queues one row on the normal scholarship AI path; the answer goes to Layer 4.';



CREATE OR REPLACE FUNCTION "security"."scholarship_readmit_blocker_v1"("p_scholarship" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when exists (select 1 from pipeline.manual_locks l where l.entity_id = p_scholarship)
      or exists (select 1 from pipeline.layer4_block_decisions b where b.entity_id = p_scholarship)
      or exists (select 1 from pipeline.scholarship_ai_reviews a where a.scholarship_id = p_scholarship and a.decided_by is not null
                  and coalesce(a.decision->>'decision', a.status) in ('refuse', 'refused', 'reject', 'rejected'))
      then 'human_decision'
    when s.application_close_date is not null
         and s.application_close_date < current_date - security.pipeline_num_v1('sch_elig.readmit_round_stale_days', 365)::int
         and not exists (select 1 from scholarship.application_windows w where w.scholarship_id = p_scholarship and w.closes_at >= current_date)
         and coalesce((select ad.application_rolling from scholarship.award_details ad where ad.scholarship_id = p_scholarship), false) is not true
      then 'round_closed'
    end
  from scholarship.scholarships s where s.id = p_scholarship
$$;


ALTER FUNCTION "security"."scholarship_readmit_blocker_v1"("p_scholarship" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_readmit_blocker_v1"("p_scholarship" "uuid") IS 'F-SCH re-admission guard: human_decision (manual lock, Layer 4 block, a person''s rejecting review) or round_closed (last round closed beyond sch_elig.readmit_round_stale_days, nothing open, not rolling); null when restoration may proceed.';



CREATE OR REPLACE FUNCTION "security"."scholarship_readmit_v1"("p_candidate" bigint, "p_evidence" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c record; s record; v_apply jsonb;
begin
  select * into c from pipeline.scholarship_page_candidates where id = p_candidate for update;
  if c.id is null or c.admit_status is distinct from 'withdrawn' or c.admitted_scholarship_id is null then
    return jsonb_build_object('readmitted', false, 'reason', 'not a withdrawn admission');
  end if;
  select * into s from scholarship.scholarships where id = c.admitted_scholarship_id for update;
  if s.id is null or s.lifecycle_status <> 'inactive' or s.publication_status = 'published' then
    return jsonb_build_object('readmitted', false, 'reason', 'record not withdrawn');
  end if;
  if security.scholarship_readmit_blocker_v1(s.id) is not null then
    return jsonb_build_object('readmitted', false, 'reason', security.scholarship_readmit_blocker_v1(s.id));
  end if;
  update scholarship.scholarships set lifecycle_status = 'active', updated_at = now() where id = s.id;
  update pipeline.scholarship_page_candidates set admit_status = 'admitted', admit_reasons = null,
         facts = coalesce(facts, '{}'::jsonb) || jsonb_build_object('eligibility_read', p_evidence, 'international', true) where id = c.id;
  insert into pipeline.scholarship_sweep_changes(scholarship_id, field, before_value, after_value)
  values (s.id, 'admission_readmitted', jsonb_build_object('lifecycle_status', 'inactive'), p_evidence);
  v_apply := security.scholarship_sweep_apply_v1(s.id);
  insert into pipeline.scholarship_admission_log(candidate_id, scholarship_id, provider_id, action, detail)
  values (c.id, s.id, c.provider_id, 'readmitted', p_evidence || jsonb_build_object('apply', v_apply));
  return jsonb_build_object('readmitted', true, 'scholarship_id', s.id, 'apply', v_apply);
end $$;


ALTER FUNCTION "security"."scholarship_readmit_v1"("p_candidate" bigint, "p_evidence" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_readmit_v1"("p_candidate" bigint, "p_evidence" "jsonb") IS 'F-SCH.01: re-admits a scholarship withdrawn for a proof that was not specific, once its proof is valid (the same record active again, unpublished; course links rebuilt).';



CREATE OR REPLACE FUNCTION "security"."scholarship_reason_label_v1"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when p in ('no_named_title', 'no named scholarship title', 'stored_name_not_a_title') then 'No scholarship name on the page'
    when p in ('international_not_stated', 'not explicitly open to international students') then 'Does not say international students can apply'
    when p = 'domestic_only' then 'For domestic students only'
    when p = 'past_year_only' then 'Only a past year is mentioned'
    when p = 'not_a_scholarship' then 'Not a scholarship page'
    when p = 'not_offered' then 'Not currently offered'
    when p = 'not_provider_domain' then 'Not on the university''s own website'
    when p = 'listing_page' then 'A list of scholarships, not one scholarship'
    when p = 'too_thin' then 'Too little text to read'
    when p = 'evidence_upload_failed' then 'The copy could not be stored'
    when p in ('already held', 'same stable key') then 'Already held'
    when p = 'register_retired' then 'From a retired register'
    when p like 'skipped: %' then 'Skipped: ' || substr(p, 10)
    else coalesce(p, '') end
$$;


ALTER FUNCTION "security"."scholarship_reason_label_v1"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_recheck_fire_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- then finish: a university at Admit scholarships whose held pages all have a re-check is done
  update pipeline.provider_onboarding ob set status = 'done', finished_at = now(), job_id = null,
         result = ob.result || jsonb_build_object('scholarship_admit', jsonb_build_object('rechecked', (select count(*) from pipeline.scholarship_ai_reviews r where r.provider_id = ob.provider_id and r.status = 'pending' and r.recheck->>'state' = 'done'))),
         note = format('Onboarding complete after the AI re-check: %s held scholarship pages wait for a person with a recommendation (Layer 4 › AI could not decide).',
                       (select count(*) from pipeline.scholarship_ai_reviews r where r.provider_id = ob.provider_id and r.status = 'pending')),
         updated_at = now()
   where ob.status = 'scholarships' and ob.result->>'phase' = 'scholarship_admit'
     and exists (select 1 from pipeline.scholarship_ai_reviews r where r.provider_id = ob.provider_id and r.recheck is not null)
     and not exists (select 1 from pipeline.scholarship_ai_reviews r where r.provider_id = ob.provider_id and r.status = 'pending' and coalesce(r.recheck->>'state', 'none') <> 'done')
     and ob.id = (select o2.id from pipeline.provider_onboarding o2 where o2.provider_id = ob.provider_id order by o2.created_at desc limit 1);
  if not security.ai_use_allowed_v1('scholarship_ai') then return 0; end if;
  if not exists (select 1 from pipeline.scholarship_ai_reviews r where r.status = 'pending'
                  and (r.recheck->>'state' = 'queued' or (r.recheck->>'state' = 'leased' and (r.recheck->>'leased_until')::timestamptz < now()))) then return 0; end if;
  perform pipeline.svc_pilot_submit_nonce('coverage-sweep', jsonb_build_object('mode', 'scholarship_recheck', 'limit', security.pipeline_num_v1('batch.scholarship_recheck', 12)::int));
  return 1;
end $$;


ALTER FUNCTION "security"."scholarship_recheck_fire_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_reread_cadence_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'pipeline', 'scholarship', 'security'
    AS $$
declare v_n int := 0;
begin
  update pipeline.scholarship_pages sp set next_read_at = sp.read_at + make_interval(days => security.scholarship_setting('reread_days', 30)::int) from scholarship.scholarships s where s.id = sp.scholarship_id and s.lifecycle_status = 'active' and sp.read_at is not null and (sp.next_read_at is null or sp.next_read_at > sp.read_at + make_interval(days => security.scholarship_setting('reread_days', 30)::int)) and (s.publication_status = 'published' or exists (select 1 from security.scholarship_publishability_v1() p where p.scholarship_id = s.id and p.publishable));
  get diagnostics v_n = row_count;
  return jsonb_build_object('brought_forward', v_n);
end $$;


ALTER FUNCTION "security"."scholarship_reread_cadence_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_round_state_refresh_v1"("p_limit" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v int;
begin
  insert into pipeline.scholarship_round_states as rs (scholarship_id, state, basis, open_date, close_date, evidence, decided_at)
  select s.id,
         case when pg.ended is not null then 'ended'
              when s.application_close_date is not null and s.application_close_date < current_date then 'closed_round'
              when s.application_open_date is not null and s.application_open_date > current_date then 'opening_soon'
              when s.application_close_date is not null then 'open' else 'no_dates' end,
         coalesce(pg.ended, case when s.application_close_date < current_date then 'close_date_passed'
                                 when s.application_open_date > current_date then 'opens_later'
                                 when s.application_close_date is not null then 'close_date_ahead' else 'no_dates_on_record' end),
         s.application_open_date, s.application_close_date,
         jsonb_build_object('page_status', pg.read_status, 'page_read_at', pg.read_at, 'publication', s.publication_status), now()
    from scholarship.scholarships s
    left join lateral (select sp.read_status, sp.read_at,
                              case when sp.read_status in ('gone', 'redirected_away', 'section_missing') then 'page_' || sp.read_status
                                   when sp.read_status = 'read' and (sp.facts->'admission'->>'offered') = 'false' then 'page_not_offered' end ended
                         from pipeline.scholarship_pages sp where sp.scholarship_id = s.id limit 1) pg on true
   where s.id in (select x.id from scholarship.scholarships x left join pipeline.scholarship_round_states r on r.scholarship_id = x.id
                   where x.lifecycle_status = 'active' order by r.decided_at nulls first, x.id limit greatest(p_limit, 0))
  on conflict (scholarship_id) do update set state = excluded.state, basis = excluded.basis, open_date = excluded.open_date, close_date = excluded.close_date,
     evidence = excluded.evidence, decided_at = now();
  get diagnostics v = row_count;
  return v;
end $$;


ALTER FUNCTION "security"."scholarship_round_state_refresh_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_scan_work_v1"("p_providers" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_site text; v_hold text; v_map int := 0; v_cand int := 0; v_list int := 0; v_held jsonb := '{}'::jsonb; v_due text; v_first text;
begin
  for r in select pr.id, nullif(btrim(pr.website), '') website, d.provider_id is not null has_row, d.next_discover_at, d.discovered_at, d.kept_count
             from catalogue.providers pr left join pipeline.scholarship_discovery_providers d on d.provider_id = pr.id
            where pr.id = any (coalesce(p_providers, '{}'::uuid[])) order by pr.id loop
    v_site := coalesce(r.website, (select nullif(btrim(x.website), '') from pipeline.coverage_provider_discovery x where x.provider_id = r.id and x.status = 'mapped'));
    v_hold := case when exists (select 1 from security.provider_hidden_v1 h where h.provider_id = r.id) then 'unpublished'
                   when v_site is null then 'no_website'
                   when security.provider_sch_search_off_v1(r.id) then 'search_off'
                   when security.third_party_host_v1(v_site) then 'directory_site'
                   when security.fc_sch_held_v1(r.id, true) then case when not security.fc_sch_eligible_v1(r.id) then 'not_eligible' else 'credit_cap' end end;
    if v_hold is not null then
      v_held := v_held || jsonb_build_object(v_hold, coalesce((v_held->>v_hold)::int, 0) + 1);
      continue;
    end if;
    if not r.has_row or r.next_discover_at is null or r.next_discover_at <= now() then v_map := v_map + 1;
    elsif v_due is null then
      v_due := 'site mapped for scholarships ' || coalesce(to_char(r.discovered_at at time zone 'Australia/Melbourne', 'DD Mon YYYY'), 'before') || ' ('
               || coalesce(r.kept_count, 0) || ' scholarship page(s) kept); next mapping due ' || to_char(r.next_discover_at at time zone 'Australia/Melbourne', 'DD Mon YYYY HH24:MI');
    end if;
    v_cand := v_cand + (select count(*) from pipeline.scholarship_page_candidates c
                         where c.provider_id = r.id and c.admit_status is null and c.matched_scholarship_id is null and c.source <> 'register' and c.attempts < 3
                           and (c.read_status is null or c.read_status in ('blocked', 'fetch_failed', 'too_thin', 'not_html', 'robots_disallowed', 'scrape_failed', 'waiting_scraper', 'deferred')));
    v_list := v_list + (select count(*) from pipeline.scholarship_listing_pages l where l.provider_id = r.id and l.active and not security.third_party_host_v1(coalesce(l.url, '')));
  end loop;
  v_first := (select k from jsonb_each_text(v_held) e(k, v) order by v::int desc, k limit 1);
  return jsonb_build_object('work', v_map + v_cand + v_list > 0, 'map_due', v_map, 'candidates', v_cand, 'listings', v_list, 'held', v_held,
    'code', case when v_map + v_cand + v_list > 0 then null when v_first is not null and v_due is null then v_first else 'nothing_due' end,
    'reason', case when v_map + v_cand + v_list > 0 then null
                   when v_first is not null and v_due is null then case v_first
                     when 'unpublished' then 'the provider is unpublished or archived'
                     when 'no_website' then 'no website is known'
                     when 'search_off' then 'scholarship search is switched off for this provider'
                     when 'directory_site' then 'the recorded website is a directory site'
                     when 'not_eligible' then 'not eligible for scholarship reading (the Firecrawl scholarship rules: fewer active courses than scholarship_min_courses, or outside the scholarship pilot)'
                     else 'its scholarship credit cap for the period is used' end
                   else coalesce(v_due, 'nothing is due') || '; no candidate or listing page is waiting' end);
end $$;


ALTER FUNCTION "security"."scholarship_scan_work_v1"("p_providers" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."scholarship_scan_work_v1"("p_providers" "uuid"[]) IS 'CF-247 IQ-00066: whether a scholarship scan of these providers has eligible work now (the scholarship reader''s gates, then site mapping due, candidate or listing pages waiting), with the reason when it has none';



CREATE OR REPLACE FUNCTION "security"."scholarship_scheduler_tick_impl"("p_now" timestamp with time zone DEFAULT "now"(), "p_limit" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security', 'pipeline'
    AS $$
declare
  r record;
  v_dispatch jsonb;
  v_results jsonb:='[]'::jsonb;
  v_count integer:=0;
begin
  if current_user not in('service_role','postgres') then
    raise exception 'service_role required' using errcode='42501';
  end if;

  for r in
    select s.*
    from pipeline.scholarship_etl_schedules s
    where s.enabled
      and s.next_due_at<=p_now
      and exists(
        select 1
        from pipeline.scholarship_source_qualifications q
        where q.source_key=s.source_key and q.qualification_status='qualified'
      )
    order by s.next_due_at,s.feed
    limit greatest(1,least(coalesce(p_limit,5),10))
    for update skip locked
  loop
    begin
      v_dispatch:=pipeline.svc_pilot_invoke_scholarship_edge(
        jsonb_strip_nulls(jsonb_build_object(
          'mode',r.mode,
          'feed',r.feed,
          'max_records',r.max_records,
          'page_start',r.page_start,
          'page_end',r.page_end
        ))
      );

      update pipeline.scholarship_etl_schedules
      set last_dispatched_at=p_now,
          last_request_id=nullif(v_dispatch->>'request_id','')::bigint,
          last_nonce=nullif(v_dispatch->>'nonce','')::uuid,
          last_dispatch=v_dispatch,
          last_error=null,
          next_due_at=p_now+make_interval(hours=>cadence_hours),
          updated_at=p_now
      where feed=r.feed;

      v_results:=v_results||jsonb_build_array(jsonb_build_object(
        'feed',r.feed,'status','dispatched','request_id',v_dispatch->>'request_id',
        'next_due_at',p_now+make_interval(hours=>r.cadence_hours)
      ));
      v_count:=v_count+1;
    exception when others then
      update pipeline.scholarship_etl_schedules
      set last_error=sqlerrm,next_due_at=p_now+make_interval(mins => security.pipeline_num_v1('scholarship.scheduler_retry_minutes', 60)::int),updated_at=p_now
      where feed=r.feed;
      v_results:=v_results||jsonb_build_array(jsonb_build_object('feed',r.feed,'status','failed','error',sqlerrm));
    end;
  end loop;

  return jsonb_build_object('ok',true,'dispatched_count',v_count,'results',v_results);
end $$;


ALTER FUNCTION "security"."scholarship_scheduler_tick_impl"("p_now" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_scope_apply_saved_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; n int := 0;
begin
  for r in select distinct d.scholarship_id, d.decided_by from pipeline.scholarship_scope_decisions d
             join scholarship.course_mapping_candidates c on c.scholarship_id = d.scholarship_id and c.status = 'needs_review' loop
    perform security.scholarship_scope_apply_v1(r.scholarship_id, r.decided_by); n := n + 1;
  end loop;
  return n;
end $$;


ALTER FUNCTION "security"."scholarship_scope_apply_saved_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_scope_apply_v1"("p_scholarship_id" "uuid", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare d pipeline.scholarship_scope_decisions%rowtype; n_acc int := 0; n_rej int := 0; n_removed int := 0; n_sweep int := 0;
begin
  select * into d from pipeline.scholarship_scope_decisions where scholarship_id = p_scholarship_id;
  if d.scholarship_id is null then return jsonb_build_object('applied', false); end if;
  create temp table if not exists pg_temp._ssa(candidate_id uuid, course_id uuid, evidence_id uuid, status text, ok boolean) on commit drop;
  truncate pg_temp._ssa;
  insert into pg_temp._ssa select c.id, c.course_id, c.evidence_id, c.status, security.scholarship_scope_match(c.course_id, d.decision, d.filter)
    from scholarship.course_mapping_candidates c join catalogue.courses co on co.id = c.course_id
    join scholarship.scholarships s on s.id = c.scholarship_id
   where c.scholarship_id = p_scholarship_id and co.provider_id = s.provider_id;
  insert into scholarship.course_mappings(scholarship_id, course_id, mapping_state, mapping_basis, evidence_id, mapped_by)
  select p_scholarship_id, x.course_id, 'mapped', 'scope_decision:' || d.decision, x.evidence_id, p_actor from pg_temp._ssa x where x.ok
  on conflict (scholarship_id, course_id) do update set mapping_basis = excluded.mapping_basis, mapping_state = 'mapped', mapped_by = excluded.mapped_by, updated_at = now()
   where scholarship.course_mappings.mapping_basis in ('sweep_level_field_scope') or scholarship.course_mappings.mapping_basis like 'scope_decision:%';
  delete from scholarship.course_mappings m using pg_temp._ssa x
   where m.scholarship_id = p_scholarship_id and m.course_id = x.course_id and not x.ok and m.mapping_basis like 'scope_decision:%';
  get diagnostics n_removed = row_count;
  delete from scholarship.course_mappings m
   where m.scholarship_id = p_scholarship_id and m.mapping_basis = 'sweep_level_field_scope'
     and not security.scholarship_scope_match(m.course_id, d.decision, d.filter);
  get diagnostics n_sweep = row_count;
  update scholarship.course_mapping_candidates c set status = case when x.ok then 'accepted' else 'rejected' end, updated_at = now()
    from pg_temp._ssa x where c.id = x.candidate_id and c.status is distinct from case when x.ok then 'accepted' else 'rejected' end;
  select count(*) filter (where ok), count(*) filter (where not ok) into n_acc, n_rej from pg_temp._ssa;
  update pipeline.scholarship_scope_decisions set accepted = n_acc, rejected = n_rej, last_applied_at = now() where scholarship_id = p_scholarship_id;
  return jsonb_build_object('applied', true, 'accepted', n_acc, 'rejected', n_rej, 'removed', n_removed, 'sweep_removed', n_sweep);
end $$;


ALTER FUNCTION "security"."scholarship_scope_apply_v1"("p_scholarship_id" "uuid", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_scope_match"("p_course_id" "uuid", "p_decision" "text", "p_filter" "jsonb") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case p_decision when 'all' then true when 'none' then false else
    exists (select 1 from catalogue.courses c
             where c.id = p_course_id
               and (   c.id::text in (select jsonb_array_elements_text(coalesce(p_filter->'courses', '[]'::jsonb)))
                    or (    (jsonb_array_length(coalesce(p_filter->'levels', '[]'::jsonb)) > 0 or jsonb_array_length(coalesce(p_filter->'fields', '[]'::jsonb)) > 0
                             or nullif(btrim(coalesce(p_filter->>'title', '')), '') is not null)
                        and (jsonb_array_length(coalesce(p_filter->'levels', '[]'::jsonb)) = 0
                             or c.study_level_id::text in (select jsonb_array_elements_text(p_filter->'levels')))
                        and (jsonb_array_length(coalesce(p_filter->'fields', '[]'::jsonb)) = 0
                             or security.broad_field_id(c.primary_field_id)::text in (select jsonb_array_elements_text(p_filter->'fields')))
                        and (nullif(btrim(coalesce(p_filter->>'title', '')), '') is null
                             or exists (select 1 from regexp_split_to_table(p_filter->>'title', '\s*,\s*') w
                                         where btrim(w) <> '' and coalesce(c.display_title, c.canonical_title) ilike '%' || btrim(w) || '%')))))
  end
$$;


ALTER FUNCTION "security"."scholarship_scope_match"("p_course_id" "uuid", "p_decision" "text", "p_filter" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_scope_suggest"("p_scholarship_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare v_name text; v_title text; v_levels jsonb := '[]'::jsonb; v_fields jsonb := '[]'::jsonb; v_why text[] := '{}';
begin
  select s.name into v_name from scholarship.scholarships s where s.id = p_scholarship_id;
  if v_name is null then return null; end if;
  if v_name ~* '\y(travel|conference|accommodation|hardship|emergency|relocation|prize|placement|exchange|study abroad|mobility|internship)\y' then
    return jsonb_build_object('decision', 'none', 'filter', '{}'::jsonb, 'why', 'The name suggests support that is not tied to a course''s tuition (for example travel or hardship).');
  end if;
  v_title := nullif(btrim(regexp_replace(substring(v_name from '(?:Bachelor|Master|Graduate Certificate|Graduate Diploma|Diploma|Doctor) of [A-Z][A-Za-z&'' -]+'),
                   '(\s+(Scholarship|Scholarships|Award|Awards|Prize|Bursary|Grant|Pioneers|Excellence|Top-Up|Fund))+\s*$', '', 'i')), '');
  if v_title is not null then
    return jsonb_build_object('decision', 'filter', 'filter', jsonb_build_object('title', v_title), 'why', 'The name mentions one course: ' || v_title || '.');
  end if;
  if v_name ~* '\y(research|phd|doctoral|hdr|higher degree)\y' then
    v_levels := (select jsonb_agg(id) from ref.study_levels where name in ('Doctorate / PhD','Masters Degree (Research)')); v_why := array_append(v_why, 'research degrees');
  elsif v_name ~* '\yundergraduate\y' then
    v_levels := (select jsonb_agg(id) from ref.study_levels where name in ('Bachelor','Bachelor Honours Degree','Diploma','Advanced Diploma','Associate Degree')); v_why := array_append(v_why, 'undergraduate courses');
  elsif v_name ~* '\y(postgraduate|masters|master''s)\y' then
    v_levels := (select jsonb_agg(id) from ref.study_levels where name in ('Masters Degree (Coursework)','Masters Degree (Extended)','Graduate Certificate','Graduate Diploma','Masters')); v_why := array_append(v_why, 'postgraduate coursework');
  end if;
  v_fields := (select jsonb_agg(id) from ref.fields_of_study where path ~ '^asced/[0-9]{2}$' and (
                  (path = 'asced/02' and v_name ~* '\y(IT|information technology|computing|computer|data science|cyber)\y')
               or (path = 'asced/03' and v_name ~* '\yengineering\y')
               or (path = 'asced/04' and v_name ~* '\y(architecture|built environment|building)\y')
               or (path = 'asced/06' and v_name ~* '\y(health|medicine|medical|nursing|pharmacy|dentistry|physiotherapy)\y')
               or (path = 'asced/07' and v_name ~* '\y(education|teaching)\y')
               or (path = 'asced/08' and v_name ~* '\y(business|commerce|accounting|finance|MBA|management|economics)\y')
               or (path = 'asced/09' and v_name ~* '\y(law|arts|humanities|social science|psychology)\y')
               or (path = 'asced/10' and v_name ~* '\y(creative|music|design|fine art|media)\y')
               or (path = 'asced/01' and v_name ~* '\yscience\y' and v_name !~* '\y(computer|data|social) science\y')));
  if v_fields is not null then v_why := array_append(v_why, 'the field named in the title'); end if;
  if jsonb_array_length(coalesce(v_levels, '[]'::jsonb)) > 0 or v_fields is not null then
    return jsonb_build_object('decision', 'filter', 'filter', jsonb_strip_nulls(jsonb_build_object('levels', v_levels, 'fields', v_fields)),
                              'why', 'The name points to ' || array_to_string(v_why, ' and ') || '.');
  end if;
  return jsonb_build_object('decision', 'all', 'filter', '{}'::jsonb, 'why', 'The name does not narrow it down; check the scholarship page before accepting all.');
end $_$;


ALTER FUNCTION "security"."scholarship_scope_suggest"("p_scholarship_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_scope_v1"("p_provider_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 SCH (8 Nov 2026): the same gates the discovery refill applies, named. in_scope means the refill would queue the provider (or already has).
  select case
           when p.id is null then 'unknown_provider'
           when nullif(btrim(coalesce(p.website, '')), '') is null then 'no_website'
           when security.third_party_host_v1(p.website) or dp.status = 'directory_site' then 'directory_site'
           when not coalesce(k.scholarship_ingestion_enabled, false) then 'country_not_open'
           when dp.status = 'not_eligible' then 'discovery_not_eligible'
           when not (k.iso_alpha2 = any (security.pipeline_list_v1('scholarship.refill_open_countries', '["AU"]'::jsonb))
                     or security.scholarship_admission_provider_ok_v1(p.id)) then 'country_or_type_not_admitted'
           when not exists (select 1 from catalogue.courses co where co.provider_id = p.id and co.lifecycle_status = 'active') then 'no_active_courses'
           when not security.fc_sch_eligible_v1(p.id) then 'below_course_minimum'
           else 'in_scope' end
    from (select 1) one
    left join catalogue.providers p on p.id = p_provider_id
    left join ref.countries k on k.id = p.country_id
    left join pipeline.scholarship_discovery_providers dp on dp.provider_id = p.id
$$;


ALTER FUNCTION "security"."scholarship_scope_v1"("p_provider_id" "uuid") OWNER TO "postgres";


