CREATE OR REPLACE FUNCTION "security"."scholarship_sources_report_v1"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 (4 Nov 2026): measures of the scholarship source and ownership root causes (read only)
  select jsonb_build_object(
    'held_on_directory_pages', (select count(*) from pipeline.scholarship_ai_reviews r where r.status = 'pending' and security.third_party_host_v1(r.url)),
    'held_on_directory_pages_without_proposal', (select count(*) from pipeline.scholarship_ai_reviews r where r.status = 'pending' and security.third_party_host_v1(r.url)
                                                   and not exists (select 1 from pipeline.scholarship_owner_proposals o where o.review_id = r.id)),
    'owner_proposals_open', (select count(*) from pipeline.scholarship_owner_proposals o where o.state = 'proposed'),
    'held_duplicating_active', (select count(*) from pipeline.scholarship_ai_reviews r join pipeline.scholarship_ai_extractions e on e.id = r.extraction_ids[array_upper(r.extraction_ids, 1)]
                                 where r.status = 'pending' and r.candidate_id is not null and nullif(e.answer->>'name', '') is not null
                                   and exists (select 1 from scholarship.scholarships s where s.provider_id = r.provider_id and s.lifecycle_status = 'active'
                                                and security.scholarship_series_key_v1(s.name) = security.scholarship_series_key_v1(e.answer->>'name'))),
    'staging_addresses_active', (select count(*) from scholarship.scholarships s join pipeline.scholarship_pages sp on sp.scholarship_id = s.id
                                  where s.lifecycle_status = 'active' and sp.url ~* '/staging/'),
    'staging_addresses_published', (select count(*) from scholarship.scholarships s join pipeline.scholarship_pages sp on sp.scholarship_id = s.id
                                     where s.lifecycle_status = 'active' and s.publication_status = 'published' and sp.url ~* '/staging/'),
    'directory_candidates_queueable', (select count(*) from pipeline.scholarship_page_candidates c where c.source <> 'register' and c.admitted_scholarship_id is null
                                        and c.matched_scholarship_id is null and coalesce(c.admit_status, '') not in ('skipped', 'duplicate', 'admitted', 'matched_held')
                                        and security.third_party_host_v1(coalesce(c.final_url, c.url))
                                        and not exists (select 1 from pipeline.scholarship_ai_reviews r where r.candidate_id = c.id and r.status = 'pending')),
    'held_on_staging_addresses', (select count(*) from pipeline.scholarship_ai_reviews r where r.status = 'pending' and r.url ~* '/staging/'),
    'read_requests', (select coalesce(jsonb_object_agg(state, n), '{}'::jsonb) from (select state, count(*) n from pipeline.scholarship_read_requests group by 1) x))
$$;


ALTER FUNCTION "security"."scholarship_sources_report_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_sources_verify_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare m jsonb := security.scholarship_sources_report_v1(); v_rc text; v_ok boolean;
begin
  select i.diagnosis->>'root_cause' into v_rc from pipeline.integration_issues i where i.id = p_issue;
  v_ok := case coalesce(v_rc, 'sch_held_on_directory_page')
    when 'sch_held_on_directory_page' then (m->>'held_on_directory_pages_without_proposal')::int = 0
    when 'sch_held_duplicates_active' then (m->>'held_duplicating_active')::int = 0
    when 'sch_source_staging_address' then (m->>'staging_addresses_active')::int = 0 and (m->>'held_on_staging_addresses')::int = 0
    when 'sch_enqueue_directory_site' then (m->>'directory_candidates_queueable')::int = 0
    when 'sch_held_read_reuses_old_copy' then coalesce((m->'read_requests'->>'queued')::int, 0) = 0
    else false end;
  return jsonb_build_object('passed', v_ok, 'measure', m, 'evidence', jsonb_build_object('root_cause', v_rc, 'issue', p_issue));
end $$;


ALTER FUNCTION "security"."scholarship_sources_verify_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_sweep_apply_v1"("p_scholarship_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'scholarship', 'catalogue', 'pipeline', 'security', 'search'
    AS $$
declare pg record; s record; v_codes text[]; v_fields text[]; v_old uuid[]; v_new uuid[]; v_changes text[]:='{}'; v_src uuid; f jsonb;
  v_d jsonb; v_date date; v_prec text; v_basis text; v_links jsonb; v_del uuid[]; v_add uuid[]; v_unmatched jsonb := '[]'::jsonb; v_excl uuid[] := '{}'; v_excl_text text;
  v_managed text[] := array['sweep_level_field_scope','page_named_course','explicit_provider_scope','explicit_course_scope'];
begin
  select * into pg from pipeline.scholarship_pages where scholarship_id=p_scholarship_id;
  select * into s from scholarship.scholarships where id=p_scholarship_id for update;
  if pg.read_status is distinct from 'read' or pg.facts is null or s.id is null then return jsonb_build_object('applied',false); end if;
  f:=pg.facts; v_src:=security.coverage_sweep_source(s.provider_id);

  if not (s.award_value_type in ('percentage','fixed_amount') and coalesce(s.award_percentage,s.award_amount) is not null) then
    if f->'value'->>'type'='percentage' and (f->'value'->>'percentage')::numeric between 5 and 100 then
      update scholarship.scholarships set award_value_type='percentage', award_percentage=(f->'value'->>'percentage')::numeric,
             award_applies_to_fee_type=coalesce(award_applies_to_fee_type,'tuition_fee'), award_value_text=coalesce(award_value_text,left(f->'value'->>'context',400)),
             evidence_id=pg.evidence_id, updated_at=now() where id=s.id;
      insert into pipeline.scholarship_sweep_changes(scholarship_id,field,before_value,after_value,evidence_id) values (s.id,'award_value',jsonb_build_object('type',s.award_value_type,'text',s.award_value_text),f->'value',pg.evidence_id);
      v_changes:=v_changes||'award_value'::text;
    elsif f->'value'->>'type'='fixed_amount' and (f->'value'->>'amount')::numeric > 0 then
      update scholarship.scholarships set award_value_type='fixed_amount', award_amount=(f->'value'->>'amount')::numeric, award_currency_code=scholarship.provider_currency(s.provider_id),
             award_value_text=coalesce(award_value_text,left(f->'value'->>'context',400)), evidence_id=pg.evidence_id, updated_at=now() where id=s.id;
      insert into pipeline.scholarship_sweep_changes(scholarship_id,field,before_value,after_value,evidence_id) values (s.id,'award_value',jsonb_build_object('type',s.award_value_type,'text',s.award_value_text),f->'value',pg.evidence_id);
      v_changes:=v_changes||'award_value'::text;
    end if;
  end if;

  -- v0.7.0 (11 Oct 2026): application open and close dates (the next closing round) and study start, from the page,
  -- each with its sentence kept in the page facts. A value entered by hand (manual lock) is left as it is.
  if f ? 'dates' then
    v_d := f->'dates'->'close';
    if v_d is not null and v_d <> 'null'::jsonb and not exists (select 1 from pipeline.manual_locks k where k.entity='scholarship' and k.entity_id=s.id and k.field='application_close_date') then
      v_date := coalesce((v_d->>'date')::date, ((v_d->>'month')||'-01')::date + interval '1 month' - interval '1 day'); v_prec := coalesce(v_d->>'precision','day');
      if s.application_close_date is distinct from v_date or s.application_close_precision is distinct from v_prec then
        update scholarship.scholarships set application_close_date=v_date, application_close_precision=v_prec, updated_at=now() where id=s.id;
        insert into pipeline.scholarship_sweep_changes(scholarship_id,field,before_value,after_value,evidence_id)
        values (s.id,'application_close_date',to_jsonb(s.application_close_date),v_d,pg.evidence_id);
        v_changes:=v_changes||'application_close_date'::text;
      end if;
    end if;
    v_d := f->'dates'->'open';
    if v_d is not null and v_d <> 'null'::jsonb and not exists (select 1 from pipeline.manual_locks k where k.entity='scholarship' and k.entity_id=s.id and k.field='application_open_date') then
      v_date := coalesce((v_d->>'date')::date, ((v_d->>'month')||'-01')::date); v_prec := coalesce(v_d->>'precision','day');
      if s.application_open_date is distinct from v_date or s.application_open_precision is distinct from v_prec then
        update scholarship.scholarships set application_open_date=v_date, application_open_precision=v_prec, updated_at=now() where id=s.id;
        insert into pipeline.scholarship_sweep_changes(scholarship_id,field,before_value,after_value,evidence_id)
        values (s.id,'application_open_date',to_jsonb(s.application_open_date),v_d,pg.evidence_id);
        v_changes:=v_changes||'application_open_date'::text;
      end if;
    end if;
    v_d := f->'study_start';
    if v_d is not null and v_d <> 'null'::jsonb and not exists (select 1 from pipeline.manual_locks k where k.entity='scholarship' and k.entity_id=s.id and k.field='study_start') then
      if s.study_start_label is distinct from (v_d->>'label') or s.study_start_date is distinct from (v_d->>'date')::date then
        update scholarship.scholarships set study_start_label=v_d->>'label', study_start_date=(v_d->>'date')::date, updated_at=now() where id=s.id;
        insert into pipeline.scholarship_sweep_changes(scholarship_id,field,before_value,after_value,evidence_id)
        values (s.id,'study_start',jsonb_build_object('label',s.study_start_label,'date',s.study_start_date),v_d,pg.evidence_id);
        v_changes:=v_changes||'study_start'::text;
      end if;
    end if;
  elsif s.application_close_date is null and (f->'deadline'->>'date') is not null and (f->'deadline'->>'date')::date >= current_date then
    update scholarship.scholarships set application_close_date=(f->'deadline'->>'date')::date, updated_at=now() where id=s.id;
    insert into pipeline.scholarship_sweep_changes(scholarship_id,field,before_value,after_value,evidence_id) values (s.id,'application_close_date',null,f->'deadline',pg.evidence_id);
    v_changes:=v_changes||'application_close_date'::text;
  end if;

  -- the provider page this record was read from (11 Oct 2026: no register placeholder addresses any more)
  if not exists (select 1 from scholarship.identifiers i where i.scholarship_id=s.id and i.scheme='first_party_detail_url') then
    insert into scholarship.identifiers(scholarship_id,scheme,identifier_value,source_id,evidence_id,is_primary,status)
    values (s.id,'first_party_detail_url',pg.url,v_src,pg.evidence_id,true,'active') on conflict do nothing;
    v_changes:=v_changes||'first_party_url'::text;
  end if;

  -- Decision 211: eligibility criteria and award duration from the page
  v_changes:=v_changes||security.scholarship_criteria_apply_v1(s.id);

  -- Course links from the evidence (11 Oct 2026, Platform Admin). In order:
  --  1. courses the page names (course code, or a course title matching one of the provider's own courses);
  --  2. else an English language course scholarship: the provider's English language courses;
  --  3. else the study levels and fields the page states (each link keeps the sentence they were read from);
  --  4. else none: a scholarship that names no course, level or field is not linked to courses (and can still be published).
  -- Every link carries its proof. Links made or decided by a person are never touched; search is refreshed only when links change.
  create temporary table if not exists _sch_links(course_id uuid primary key, proof jsonb) on commit drop;
  truncate _sch_links;
  -- courses the page excludes ("all undergraduate degrees, excluding the Bachelor of ...") are never linked
  if jsonb_typeof(f->'named_courses'->'excluded') = 'array' then
    select coalesce(array_agg(distinct c.id), '{}') into v_excl from catalogue.courses c
      join jsonb_array_elements(f->'named_courses'->'excluded') x
        on (x ? 'code' and upper(coalesce(c.course_code,'')) = upper(x->>'code'))
        or (x ? 'title' and security.scholarship_course_title_match_v1(x->>'title', c.canonical_title, c.display_title))
     where c.provider_id = s.provider_id;
    select string_agg(distinct coalesce(x->>'title', x->>'code'), ', ') into v_excl_text from jsonb_array_elements(f->'named_courses'->'excluded') x;
  end if;
  if jsonb_typeof(f->'named_courses') = 'object' then
    insert into _sch_links(course_id, proof)
    select distinct on (c.id) c.id, jsonb_build_object('kind', x.kind, 'named', x.named, 'text', x.txt)
      from catalogue.courses c
      join (select 'course_code' kind, nc->>'code' named, nc->>'text' txt, null::text norm from jsonb_array_elements(coalesce(f->'named_courses'->'codes','[]')) nc
            union all
            select 'course_title', nc->>'title', nc->>'text', regexp_replace(lower(nc->>'title'), '[^a-z0-9]+', '', 'g') from jsonb_array_elements(coalesce(f->'named_courses'->'titles','[]')) nc) x
        on (x.kind = 'course_code' and upper(coalesce(c.course_code,'')) = upper(x.named))
        or (x.kind = 'course_title' and security.scholarship_course_title_match_v1(x.named, c.canonical_title, c.display_title))
     where c.provider_id = s.provider_id and c.lifecycle_status = 'active' and not (c.id = any(v_excl))
     order by c.id, (x.kind = 'course_code') desc;
    select coalesce(jsonb_agg(x), '[]'::jsonb) into v_unmatched from (
      select jsonb_build_object('code', nc->>'code') x from jsonb_array_elements(coalesce(f->'named_courses'->'codes','[]')) nc
       where not exists (select 1 from catalogue.courses c where c.provider_id = s.provider_id and upper(coalesce(c.course_code,'')) = upper(nc->>'code'))
      union all
      select jsonb_build_object('title', nc->>'title') from jsonb_array_elements(coalesce(f->'named_courses'->'titles','[]')) nc
       where not exists (select 1 from catalogue.courses c where c.provider_id = s.provider_id and c.lifecycle_status = 'active'
                          and security.scholarship_course_title_match_v1(nc->>'title', c.canonical_title, c.display_title))) z;
  end if;
  if exists (select 1 from _sch_links) then
    v_basis := 'page_named_course';
  elsif f ? 'english_course' then
    v_basis := 'sweep_level_field_scope';
    insert into _sch_links(course_id, proof)
    select c.id, jsonb_build_object('kind','english_course','named',f->'english_course'->>'course','text','English language course scholarship: linked to the provider''s English language courses')
      from catalogue.courses c join ref.study_levels sl on sl.id=c.study_level_id
     where c.provider_id=s.provider_id and c.lifecycle_status='active' and sl.code='non_aqf_award' and coalesce(c.course_code,'')<>''
       and c.canonical_title ~* case f->'english_course'->>'course'
             when 'general english' then '\mgeneral english\M'
             when 'ielts preparation' then '\mielts\M'
             when 'academic english' then '(academic english|english for academic purposes|\meap\M)'
             else '(general english|academic english|english for academic purposes|\meap\M|\mielts\M|\melicos\M|english language)' end;
  else
    v_codes:=security.scholarship_level_codes(f->'levels');
    v_fields:=array(select jsonb_array_elements_text(coalesce(f->'fields','[]')));
    if jsonb_typeof(f->'levels')='array' and jsonb_array_length(f->'levels')>0 and cardinality(v_codes)=0 then
      -- 29 Oct 2026 (mandate A2): the page states levels this reader does not know; a field alone would link every level
      v_changes:=v_changes||'levels_not_recognised'::text;
    elsif cardinality(v_codes)>0 or cardinality(v_fields)>0 then
      v_basis := 'sweep_level_field_scope';
      insert into _sch_links(course_id, proof)
      select c.id, jsonb_build_object('kind','levels_fields','levels',f->'levels','fields',f->'fields',
                     'text', concat_ws(' | ', case when cardinality(v_codes)>0 then f->>'levels_text' end, case when cardinality(v_fields)>0 then f->>'fields_text' end),
                     'excluding', v_excl_text)
        from catalogue.courses c left join ref.study_levels sl on sl.id=c.study_level_id left join ref.fields_of_study fos on fos.id=c.primary_field_id
       where c.provider_id=s.provider_id and c.lifecycle_status='active' and not (c.id = any(v_excl))
         and (cardinality(v_codes)=0 or sl.code=any(v_codes))
         and (cardinality(v_fields)=0 or exists (select 1 from unnest(v_fields) fp where fos.code like fp||'%'));
    else
      v_changes:=v_changes||'no_course_named'::text;
    end if;
  end if;
  select coalesce(array_agg(m.course_id),'{}') into v_del from scholarship.course_mappings m
   where m.scholarship_id=s.id and m.mapped_by is null and m.mapping_basis=any(v_managed) and not exists (select 1 from _sch_links l where l.course_id=m.course_id);
  select coalesce(array_agg(l.course_id),'{}') into v_add from _sch_links l
   where not exists (select 1 from scholarship.course_mappings m where m.scholarship_id=s.id and m.course_id=l.course_id and m.mapping_state='mapped');
  if cardinality(v_del)>0 then
    delete from scholarship.course_mappings where scholarship_id=s.id and course_id=any(v_del) and mapped_by is null and mapping_basis=any(v_managed);
  end if;
  insert into scholarship.course_mappings(scholarship_id,course_id,mapping_state,mapping_basis,evidence_id,mapped_by,mapped_at,updated_at,proof)
  select s.id, l.course_id, 'mapped', v_basis, pg.evidence_id, null, now(), now(), l.proof from _sch_links l
  on conflict (scholarship_id,course_id) do update set mapping_basis=excluded.mapping_basis, mapping_state='mapped', evidence_id=excluded.evidence_id, proof=excluded.proof, updated_at=now()
   where scholarship.course_mappings.mapped_by is null and scholarship.course_mappings.mapping_basis=any(v_managed)
     and (scholarship.course_mappings.proof is distinct from excluded.proof or scholarship.course_mappings.mapping_basis is distinct from excluded.mapping_basis
          or scholarship.course_mappings.evidence_id is distinct from excluded.evidence_id or scholarship.course_mappings.mapping_state <> 'mapped');
  -- the study-level scope rows of this reader follow the page's levels
  delete from scholarship.scopes sc using pipeline.sources src where sc.source_id=src.id and src.source_type='provider_course_page_sweep' and sc.scope_type='study_level' and sc.scholarship_id=s.id
     and not (sc.study_level_id in (select sl.id from ref.study_levels sl where sl.code=any(coalesce(v_codes,'{}'))));
  if cardinality(coalesce(v_codes,'{}'))>0 then
    insert into scholarship.scopes(scholarship_id,scope_type,study_level_id,include_exclude,source_id,evidence_id)
    select s.id,'study_level',sl.id,'include',v_src,pg.evidence_id from ref.study_levels sl
     where sl.code=any(v_codes) and not exists (select 1 from scholarship.scopes x where x.scholarship_id=s.id and x.scope_type='study_level' and x.study_level_id=sl.id);
  end if;
  v_links := jsonb_build_object('basis', coalesce(v_basis,'none'), 'courses', (select count(*) from _sch_links), 'added', cardinality(v_add), 'removed', cardinality(v_del), 'named_not_matched', v_unmatched,
                                'excluded', cardinality(v_excl), 'excluded_named', v_excl_text);
  if cardinality(v_add)+cardinality(v_del)>0 then
    insert into pipeline.scholarship_sweep_changes(scholarship_id,field,before_value,after_value,evidence_id)
    values (s.id,'course_links',jsonb_build_object('removed',cardinality(v_del)),v_links,pg.evidence_id);
    v_changes:=v_changes||'course_links'::text;
    -- R5 (14 Nov 2026): inside svc_scholarship_ai_record (flag cf247.defer_search_refresh) the courses are queued, not refreshed in the call
    if coalesce(current_setting('cf247.defer_search_refresh', true), '') = 'on' then
      perform search.course_refresh_request_v1(array(select distinct unnest(v_add||v_del)), 'scholarship_sweep_apply_v1');
    else
      perform search.refresh_course_enrichment_scoped_v1(array(select distinct unnest(v_add||v_del)),true);
    end if;
  end if;
  update pipeline.scholarship_pages set applied_at=now(), apply_result=jsonb_build_object('changes',to_jsonb(v_changes),'links',v_links,'extractor',f->>'extractor') where scholarship_id=s.id;
  return jsonb_build_object('applied',true,'changes',to_jsonb(v_changes),'links',v_links);
end $$;


ALTER FUNCTION "security"."scholarship_sweep_apply_v1"("p_scholarship_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_task_fire_v1"("p_steps" "text"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_step text; v_mode text; v_body jsonb; v_sent int := 0;
begin
  foreach v_step in array coalesce(p_steps, '{}') loop
    v_mode := case when v_step in ('discover', 'candidates') then 'scholarship_discover' else 'scholarship_read' end;
    -- CF-247 scholarship recovery F10: the sizes are the Scholarships settings the scheduled jobs use
    v_body := case v_step
      when 'discover' then jsonb_build_object('mode', v_mode, 'phase', 'discover', 'limit', security.scholarship_setting('discover_limit', 6)::int)
      when 'candidates' then jsonb_build_object('mode', v_mode, 'phase', 'candidates', 'read_limit', security.scholarship_setting('candidate_read_limit', 30)::int)
      else jsonb_build_object('mode', v_mode, 'limit', security.scholarship_setting('read_limit', 40)::int) end;
    if not exists (select 1 from pipeline.edge_request_log l where l.function_name = 'coverage-sweep' and l.mode = v_mode and l.created_at > now() - interval '45 seconds'  -- fixed: fire guard
                    and not exists (select 1 from net._http_response r where r.id = l.request_id)) then
      perform pipeline.svc_pilot_submit_nonce('coverage-sweep', v_body);
      v_sent := v_sent + 1;
    end if;
  end loop;
  return v_sent;
end $$;


ALTER FUNCTION "security"."scholarship_task_fire_v1"("p_steps" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_task_prepare_v1"("p_kind" "text", "p_args" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_prov uuid[]; v_sch uuid[]; v_course uuid; v_before uuid[] := '{}'; v_pages int := 0; v_cands int := 0; v_title text; v_scope text; v_missing text;
begin
  if p_kind = 'scholarship_provider_scan' then
    v_prov := array(select distinct x::uuid from jsonb_array_elements_text(coalesce(p_args->'provider_ids', '[]'::jsonb)) x);
    if coalesce(cardinality(v_prov), 0) = 0 then raise exception 'choose at least one provider'; end if;
    if cardinality(v_prov) > 50 then raise exception 'at most 50 providers in one task'; end if;
    select string_agg(coalesce(p.display_name, p.canonical_name), ', ') into v_missing from catalogue.providers p
     where p.id = any (v_prov) and coalesce(nullif(btrim(p.website), ''), (select nullif(btrim(d.website), '') from pipeline.coverage_provider_discovery d where d.provider_id = p.id and d.status = 'mapped')) is null;
    if v_missing is not null then raise exception 'no website is known for %; add it on the provider first', v_missing; end if;
  elsif p_kind = 'scholarship_course_check' then
    v_course := (p_args->>'course_id')::uuid;
    select array[c.provider_id] into v_prov from catalogue.courses c where c.id = v_course;
    if v_prov is null then raise exception 'unknown course'; end if;
    v_before := array(select m.scholarship_id from scholarship.course_mappings m where m.course_id = v_course and m.mapping_state = 'mapped');
  elsif p_kind = 'scholarship_reread' then
    v_sch := array(select distinct x::uuid from jsonb_array_elements_text(coalesce(p_args->'scholarship_ids', '[]'::jsonb)) x);
    if coalesce(cardinality(v_sch), 0) = 0 then raise exception 'choose a scholarship'; end if;
    v_prov := array(select distinct s.provider_id from scholarship.scholarships s where s.id = any (v_sch));
    if not exists (select 1 from pipeline.scholarship_pages p where p.scholarship_id = any (v_sch)) then raise exception 'this scholarship has no provider page to read'; end if;
  else
    raise exception 'unknown scholarship task';
  end if;
  if exists (select 1 from security.provider_hidden_v1 h where h.provider_id = any (v_prov)) then
    raise exception 'a chosen provider is unpublished or archived; publish or restore it first';
  end if;
  if p_kind = 'scholarship_provider_scan' then
    insert into pipeline.scholarship_discovery_providers(provider_id, website, priority, reason, status, attempts, updated_at)
    select p.id, coalesce(nullif(btrim(p.website), ''), (select nullif(btrim(d.website), '') from pipeline.coverage_provider_discovery d where d.provider_id = p.id and d.status = 'mapped')), 0, 'on_demand', 'pending', 0, now()
      from catalogue.providers p where p.id = any (v_prov)
    on conflict (provider_id) do update set status = 'pending', priority = 0, attempts = 0, leased_until = null, reason = 'on_demand', updated_at = now();
    update pipeline.scholarship_page_candidates c set next_read_at = now(), attempts = 0, leased_until = null, requested_at = now()
     where c.provider_id = any (v_prov) and c.admit_status is null and c.matched_scholarship_id is null and c.source <> 'register'
       and (c.read_status is null or c.read_status in ('blocked', 'fetch_failed', 'too_thin', 'not_html', 'robots_disallowed', 'scrape_failed', 'waiting_scraper', 'deferred'));
    get diagnostics v_cands = row_count;
    -- v2.15.249 (bugs 11/10-6): with AI admission on, refused pages of the chosen providers are read again by the AI
    if exists (select 1 from pipeline.scholarship_ai_extract_settings s where s.id = 1 and s.ai_admission) then v_cands := v_cands + security.scholarship_ai_enqueue_v1('admit', v_prov, null, false); end if;
  end if;
  update pipeline.scholarship_pages p set requested_at = now(), next_read_at = now(), attempts = 0, leased_until = null
    from scholarship.scholarships s
   where s.id = p.scholarship_id and s.lifecycle_status = 'active'
     and (case when v_sch is not null then s.id = any (v_sch) else s.provider_id = any (v_prov) end);
  get diagnostics v_pages = row_count;
  if v_pages = 0 and p_kind = 'scholarship_reread' then raise exception 'this scholarship is not active, so there is no page to read; restore it first'; end if;
  if v_pages = 0 and p_kind = 'scholarship_course_check' then raise exception 'this course''s provider has no active scholarship pages yet; use Find scholarships now on the provider'; end if;
  if v_sch is null then update pipeline.scholarship_listing_pages set next_read_at = now() where active and provider_id = any (v_prov); end if;
  v_title := case p_kind
    when 'scholarship_provider_scan' then 'Find scholarships now: ' || case when cardinality(v_prov) = 1 then (select coalesce(p.display_name, p.canonical_name) from catalogue.providers p where p.id = v_prov[1]) else cardinality(v_prov) || ' providers' end
    when 'scholarship_course_check' then 'Check scholarships for ' || (select coalesce(c.display_title, c.canonical_title) || coalesce(' (' || c.course_code || ')', '') from catalogue.courses c where c.id = v_course)
    else 'Read again now: ' || case when cardinality(v_sch) = 1 then (select s.name from scholarship.scholarships s where s.id = v_sch[1]) else cardinality(v_sch) || ' scholarships' end end;
  v_scope := case p_kind
    when 'scholarship_provider_scan' then case when cardinality(v_prov) = 1 then v_prov[1]::text else 'providers:' || md5(array_to_string(array(select x::text from unnest(v_prov) x order by 1), ',')) end
    when 'scholarship_course_check' then v_course::text
    else case when cardinality(v_sch) = 1 then v_sch[1]::text else 'scholarships:' || md5(array_to_string(array(select x::text from unnest(v_sch) x order by 1), ',')) end end;
  return jsonb_build_object('providers', to_jsonb(v_prov), 'scholarship_ids', to_jsonb(coalesce(v_sch, '{}'::uuid[])), 'course_id', v_course, 'before', to_jsonb(v_before),
                            'pages', v_pages, 'candidates', v_cands, 'title', v_title, 'scope', v_scope);
end $$;


ALTER FUNCTION "security"."scholarship_task_prepare_v1"("p_kind" "text", "p_args" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_tier_text"("p_pcts" numeric[], "p_amts" numeric[], "p_up_to" boolean) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $_$
  select array_to_string(array_remove(array[
    case when cardinality(coalesce(p_pcts, '{}'::numeric[])) = 1 then p_pcts[1]::int || '% of tuition fees'
         when cardinality(coalesce(p_pcts, '{}'::numeric[])) > 1 then case when p_up_to then 'Up to ' || p_pcts[cardinality(p_pcts)]::int || '% of tuition fees (' || (select string_agg(x::int || '%', ', ') from unnest(p_pcts) x) || ' stated)'
                                                                       else p_pcts[1]::int || '% to ' || p_pcts[cardinality(p_pcts)]::int || '% of tuition fees' end end,
    case when cardinality(coalesce(p_amts, '{}'::numeric[])) = 1 then 'A$' || to_char(p_amts[1], 'FM999,999,999')
         when cardinality(coalesce(p_amts, '{}'::numeric[])) > 1 then case when p_up_to then 'Up to A$' || to_char(p_amts[cardinality(p_amts)], 'FM999,999,999') || ' (' || (select string_agg('A$' || to_char(x, 'FM999,999,999'), ', ') from unnest(p_amts) x) || ' stated)'
                                                                       else 'A$' || to_char(p_amts[1], 'FM999,999,999') || ' to A$' || to_char(p_amts[cardinality(p_amts)], 'FM999,999,999') end end
  ], null), ' or ')
$_$;


ALTER FUNCTION "security"."scholarship_tier_text"("p_pcts" numeric[], "p_amts" numeric[], "p_up_to" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_tier_text"("p_pcts" numeric[], "p_amts" numeric[], "p_up_to" boolean, "p_currency" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select array_to_string(array_remove(array[
    case when cardinality(coalesce(p_pcts, '{}'::numeric[])) = 1 then p_pcts[1]::int || '% of tuition fees'
         when cardinality(coalesce(p_pcts, '{}'::numeric[])) > 1 then case when p_up_to then 'Up to ' || p_pcts[cardinality(p_pcts)]::int || '% of tuition fees (' || (select string_agg(x::int || '%', ', ') from unnest(p_pcts) x) || ' stated)'
                                                                       else p_pcts[1]::int || '% to ' || p_pcts[cardinality(p_pcts)]::int || '% of tuition fees' end end,
    case when cardinality(coalesce(p_amts, '{}'::numeric[])) = 1 then scholarship.money_prefix(p_currency) || to_char(p_amts[1], 'FM999,999,999')
         when cardinality(coalesce(p_amts, '{}'::numeric[])) > 1 then case when p_up_to then 'Up to ' || scholarship.money_prefix(p_currency) || to_char(p_amts[cardinality(p_amts)], 'FM999,999,999') || ' (' || (select string_agg(scholarship.money_prefix(p_currency) || to_char(x, 'FM999,999,999'), ', ') from unnest(p_amts) x) || ' stated)'
                                                                       else scholarship.money_prefix(p_currency) || to_char(p_amts[1], 'FM999,999,999') || ' to ' || scholarship.money_prefix(p_currency) || to_char(p_amts[cardinality(p_amts)], 'FM999,999,999') end end
  ], null), ' or ')
$$;


ALTER FUNCTION "security"."scholarship_tier_text"("p_pcts" numeric[], "p_amts" numeric[], "p_up_to" boolean, "p_currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_transient_recover_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_max int := security.pipeline_num_v1('batch.scholarship_transient_recover', 20)::int; v_park numeric := security.pipeline_num_v1('retry.scholarship_transient_park_hours', 48);
        v_cyc int := security.pipeline_num_v1('retry.scholarship_transient_cycles_max', 1)::int; v_pp int := security.pipeline_num_v1('sch_cov.recover_per_provider_max', 3)::int;
        r record; v_k int; v_done int := 0; v_skip int := 0; v_ok int := 0; v_fail int := 0; v_per jsonb := '{}'::jsonb; v_hold text; v_class text; v_n int;
begin
  -- outcomes of earlier cycles are recorded whether or not the switch is on
  update pipeline.scholarship_read_retry_cycles y set outcome = case when c.read_status = 'read' then 'read' else 'failed_again' end, outcome_at = now()
    from pipeline.scholarship_page_candidates c
   where y.outcome is null and c.id = y.candidate_id
     and (c.read_status = 'read' or (c.attempts >= 3 and c.read_status in ('scrape_failed', 'blocked', 'gone', 'too_thin', 'not_html')));  -- fixed: 3 is the candidate reader's own attempt cap (svc_scholarship_candidate_next)
  get diagnostics v_ok = row_count;
  select count(*) filter (where outcome = 'failed_again') into v_fail from pipeline.scholarship_read_retry_cycles where outcome_at >= now() - interval '1 hour';  -- fixed: the run's own hourly window
  if security.pipeline_num_v1('retry.scholarship_transient_recover_on', 0) < 1 then return jsonb_build_object('ran', false, 'reason', 'retry.scholarship_transient_recover_on is 0', 'outcomes_recorded', v_ok); end if;
  v_hold := security.lane_paid_hold_v1('sch_scrape');
  if v_hold is not null then return jsonb_build_object('ran', false, 'reason', 'the scholarship Firecrawl share is held', 'hold', v_hold, 'outcomes_recorded', v_ok); end if;
  for r in select c.id, c.provider_id, c.url, c.http_status from pipeline.scholarship_page_candidates c
            where c.read_status = 'scrape_failed' and c.attempts >= 3 and c.admit_status is null and c.matched_scholarship_id is null and c.admitted_scholarship_id is null  -- fixed: 3 is the candidate reader's own attempt cap
              and (c.http_status is null or c.http_status in (402, 408, 425, 429, 500, 502, 503, 504, 520, 522, 524))  -- fixed: the transient HTTP classes the course-page watchdog also retries
              and coalesce(c.read_at, c.found_at) < now() - make_interval(hours => v_park::int)
              and not exists (select 1 from pipeline.scholarship_read_retry_cycles y where y.candidate_id = c.id and y.outcome is null)
            order by c.found_at, c.id loop
    exit when v_done >= v_max;
    select count(*) into v_n from pipeline.scholarship_read_retry_cycles y where y.candidate_id = r.id;
    if v_n >= v_cyc then continue; end if;
    if coalesce((v_per->>r.provider_id::text)::int, 0) >= v_pp then continue; end if;
    if security.fc_sch_held_v1(r.provider_id, true) or security.provider_sch_search_off_v1(r.provider_id) or exists (select 1 from security.provider_hidden_v1 h where h.provider_id = r.provider_id)
       or security.third_party_host_v1(r.url) or not security.scholarship_admission_provider_ok_v1(r.provider_id) then v_skip := v_skip + 1; continue; end if;
    v_class := case when r.http_status = 402 then 'budget' when r.http_status is null then 'no_answer' when r.http_status in (408, 425, 429) then 'timeout' else 'server' end;
    update pipeline.scholarship_page_candidates c set attempts = 0, next_read_at = now(), leased_until = null where c.id = r.id and c.read_status = 'scrape_failed' and c.attempts >= 3;  -- fixed: 3 is the candidate reader's own attempt cap
    get diagnostics v_k = row_count;
    if v_k > 0 then
      insert into pipeline.scholarship_read_retry_cycles(candidate_id, cycle, provider_id, reason_class, http_status) values (r.id, v_n + 1, r.provider_id, v_class, r.http_status) on conflict do nothing;
      v_done := v_done + 1; v_per := v_per || jsonb_build_object(r.provider_id::text, coalesce((v_per->>r.provider_id::text)::int, 0) + 1);
    end if;
  end loop;
  return jsonb_build_object('ran', true, 'released', v_done, 'skipped', v_skip, 'outcomes_recorded', v_ok, 'failed_again_last_hour', v_fail);
end $$;


ALTER FUNCTION "security"."scholarship_transient_recover_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."scholarship_university"("p_provider_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select security.australian_university(p_provider_id)
      or exists (select 1 from catalogue.providers p join ref.countries c on c.id = p.country_id
                  where p.id = p_provider_id and c.iso_alpha2 <> 'AU' and c.scholarship_ingestion_enabled and p.lifecycle_status = 'active'
                    and (jsonb_array_length(coalesce(security.provider_university_groups(p.id), '[]')) > 0
                         or (p.canonical_name ~* '\m(university|université|universite)\M' and p.canonical_name !~* '(college|pathways?|language cent|senior|theology|divinity)')))
      -- CF-247 IQ-00215 (4 Nov 2026): joined trading names are tested on the legal name while sch_cov.legal_name_identity_on is 1
      or (security.pipeline_num_v1('sch_cov.legal_name_identity_on', 0) >= 1 and security.scholarship_legal_name_ok_v1(p_provider_id))
$$;


