    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $_$
  select regexp_replace(regexp_replace(lower(split_part(btrim(coalesce(p_url,'')),'#',1)),'^http://','https://'),'/+$','')
$_$;


