COMMENT ON FUNCTION "security"."search_asked_by_person_v1"("p_provider" "uuid", "p_requested_at" timestamp with time zone) IS 'CF-247 22 Oct 2026: true when a course search was asked for by a person (not by bulk onboarding, unless Search again was pressed since); only such searches pass the search gates.';



CREATE OR REPLACE FUNCTION "security"."search_course_refresh_drain_v1"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_t0 timestamptz := clock_timestamp(); v_max bigint; v_ids uuid[]; r jsonb; v_rows integer;
begin
  if not pg_try_advisory_xact_lock(hashtext('cf247:search_course_documents_writer')) then  -- fixed: the one writer lock for search.course_documents (W27); never wait for it
    return jsonb_build_object('held', 'another search-document writer is running; the queued courses wait for the next run',
                              'open_courses', (select count(distinct q.course_id) from search.course_refresh_requests q where q.processed_at is null));
  end if;
  select max(q.id) into v_max from search.course_refresh_requests q where q.processed_at is null;
  if v_max is null then return jsonb_build_object('open_courses', 0); end if;
  select array_agg(z.course_id order by z.first_id) into v_ids
    from (select q.course_id, min(q.id) first_id from search.course_refresh_requests q
           where q.processed_at is null and q.id <= v_max group by q.course_id order by min(q.id) limit greatest(coalesce(p_limit, 0), 1)) z;
  r := search.refresh_course_enrichment_scoped_v1(v_ids, true);
  update search.course_refresh_requests q set processed_at = now(), result = jsonb_build_object('rows', r->'rows', 'changed', r->'changed')
   where q.processed_at is null and q.id <= v_max and q.course_id = any(v_ids);
  get diagnostics v_rows = row_count;
  return jsonb_build_object('courses', cardinality(v_ids), 'requests', v_rows, 'changed', r->'changed',
                            'open_courses', (select count(distinct q.course_id) from search.course_refresh_requests q where q.processed_at is null),
                            'ms', (extract(epoch from clock_timestamp() - v_t0) * 1000)::int);
end
$$;


ALTER FUNCTION "security"."search_course_refresh_drain_v1"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."search_course_refresh_drain_v1"("p_limit" integer) IS 'Job search-course-refresh: refreshes up to p_limit queued courses (search.course_refresh_requests, oldest first) with search.refresh_course_enrichment_scoped_v1 when the search-document writer lock is free, and stamps the requests it covered.';



CREATE OR REPLACE FUNCTION "security"."search_pass_advance_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_next text; n_ver int := 0; n_next int := 0; n_none int := 0;
begin
  update pipeline.search_pass_links l set state = 'verified', updated_at = now() from pipeline.coverage_course_pages p where l.state = 'found' and p.course_id = l.course_id and p.url = l.bound_url and p.status = 'bound' and p.identity_basis is not null;
  get diagnostics n_ver = row_count;
  for r in select l.*, p.status pstatus from pipeline.search_pass_links l join pipeline.coverage_course_pages p on p.course_id = l.course_id and p.url = l.bound_url
            where l.state = 'found' and (p.status = 'mismatch' or (p.read_status in ('fetch_failed', 'blocked', 'robots_disallowed') and (p.read_attempts >= 2 or p.http_status in (404, 410)))) loop
    if r.cand_idx < jsonb_array_length(r.candidates) then
      v_next := r.candidates->>r.cand_idx;
      insert into pipeline.page_link_repairs(course_id, provider_id, old_url, new_url, reason, run_id) values (r.course_id, r.provider_id, r.bound_url, v_next, 'search pass: next candidate after the reader refused the page', r.run_id);
      update pipeline.coverage_course_pages set url = v_next, basis = case when r.engine = 'firecrawl' then 'firecrawl_search' else 'serper_search' end, status = 'bound', bound_at = now(), read_status = null, read_at = null, http_status = null, fetched_via = null, identity_basis = null, evidence_id = null, read_attempts = 0, next_read_at = now(), leased_until = null where course_id = r.course_id and url = r.bound_url;
      update pipeline.search_pass_links set cand_idx = cand_idx + 1, bound_url = v_next, updated_at = now() where course_id = r.course_id;
      n_next := n_next + 1;
    else
      update pipeline.search_pass_links set state = 'none', updated_at = now() where course_id = r.course_id;
      n_none := n_none + 1;
    end if;
  end loop;
  return jsonb_build_object('verified', n_ver, 'next_candidate', n_next, 'none', n_none);
end $$;


ALTER FUNCTION "security"."search_pass_advance_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."search_refresh_requested_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'search'
    AS $$
declare v_ids bigint[]; r jsonb;
begin
  select array_agg(id) into v_ids from search.refresh_requests where processed_at is null;
  if v_ids is null then return jsonb_build_object('pending',0); end if;
  -- v2.15.307: requests from Enrich fields tasks and enrichment plans only: at most one full comparison every search.refresh_min_gap_minutes
  if not exists (select 1 from search.refresh_requests q where q.id = any(v_ids) and q.requested_by !~ '^(enrich fields task|enrichment plan) ')
     and exists (select 1 from search.refresh_requests q where q.processed_at > now() - make_interval(mins => security.pipeline_num_v1('search.refresh_min_gap_minutes', 30)::int)) then
    return jsonb_build_object('pending', cardinality(v_ids), 'held', 'automatic requests wait for the refresh gap');
  end if;
  if not pg_try_advisory_xact_lock(hashtext('cf247:search_course_documents_writer')) then  -- fixed: the one writer lock (W27)
    return jsonb_build_object('pending', cardinality(v_ids), 'held', 'another search-document writer is running; the requests wait for the next run');
  end if;
  r := search.refresh_course_documents_v3(true);
  update search.refresh_requests set processed_at=now(), result=jsonb_build_object('base_applied',r->'base'->'applied_rows','base_changed',r->'base'->'changed','generation',r->'base'->'generation') where id = any(v_ids);
  return jsonb_build_object('processed',cardinality(v_ids),'base_applied',r->'base'->'applied_rows');
end $$;


ALTER FUNCTION "security"."search_refresh_requested_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."search_stop_gate_v1"("p_provider" "uuid", "p_course" "uuid" DEFAULT NULL::"uuid", "p_stopped" boolean DEFAULT NULL::boolean, "p_person" boolean DEFAULT NULL::boolean) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_stopped boolean; v_person boolean;
begin
  -- the university stop, unless a person's task covers it (search.person_task_bypass)
  v_stopped := coalesce(p_stopped, security.fc_search_stopped_for_v1(p_provider));
  if v_stopped then
    v_person := security.pipeline_num_v1('search.person_task_bypass', 1) >= 1 and coalesce(p_person,
      case when p_course is not null then security.link_search_person_task_v1(p_provider, p_course)
           else exists (select 1 from pipeline.admin_jobs j where j.kind = 'course_page_find' and j.state in ('queued', 'running') and j.args->>'provider_id' = p_provider::text) end);
    if not v_person then return 'search_stopped'; end if;
  end if;
  -- SS-007 (31 Oct 2026): held for binding remediation until a person lifts the hold
  if p_course is not null and security.course_held_v1(p_course) then
    return 'remediation_hold';
  end if;
  -- SP-1: recorded as no page published by the provider, or a conjoint degree under an approved rule
  if p_course is not null and security.no_page_hold_v1(p_course) then
    return 'no_page_by_provider';
  end if;
  -- the course stop (R2): too many different pages rejected for this course
  if p_course is not null and (select count(distinct r.url) from pipeline.page_rejections r where r.course_id = p_course)
                              >= security.pipeline_num_v1('search.stop_per_course_after', 6) then
    return 'course_stopped';
  end if;
  return null;
end $$;


ALTER FUNCTION "security"."search_stop_gate_v1"("p_provider" "uuid", "p_course" "uuid", "p_stopped" boolean, "p_person" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."search_stop_gate_v1"("p_provider" "uuid", "p_course" "uuid", "p_stopped" boolean, "p_person" boolean) IS 'CF-247 S1 (v2.15.352): the one course-search stop gate (university stop with the person-task bypass, then the per-course stop) used by the picker, the credit check and the stall-cause walk';



CREATE OR REPLACE FUNCTION "security"."self_sustainability_v1"("p_window_hours" integer DEFAULT 24) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_since timestamptz := now() - make_interval(hours => p_window_hours); v_scan int := security.pipeline_num_v1('ops.runs_scan', 20000)::int;
        v_runs int; v_failed int; v_last_fail timestamptz; v_tr jsonb; v_created numeric; v_stalled int; v_justified int; v_technical int; v_noelig boolean;
        v_auto_det int; v_man_det int; v_owned int; v_unowned int; v_rem_ok int; v_rem_fail int; v_wc_rec int; v_wc_parked_no_time int;
        v_sch_adm numeric; v_aer_adm numeric; v_sch_pub numeric; v_aer_pub numeric; v_l4 int; v_int int; v_ai numeric; v_ai_cap numeric; v_fc numeric;
        v_rel jsonb; v_dc int; v_out jsonb;
begin
  select count(*), count(*) filter (where d.status = 'failed'), max(d.start_time) filter (where d.status = 'failed') into v_runs, v_failed, v_last_fail
    from (select x.status, x.start_time from cron.job_run_details x order by x.runid desc limit v_scan) d where d.start_time >= v_since;
  select coalesce(jsonb_object_agg(t.key, jsonb_build_object('created', t.output_created, 'eligible', t.input_eligible, 'zero', t.zero_reason, 'stalled', t.stalled,
           'admitted', t.output_admitted, 'published', t.output_published, 'last_advanced_at', t.last_advanced_at, 'measured_at', t.measured_at)), '{}'::jsonb),
         sum(t.output_created), count(*) filter (where t.stalled), count(*) filter (where t.zero_reason in ('no_eligible_work', 'cap_reached', 'blocked_authority', 'correctly_excluded')),
         count(*) filter (where t.zero_reason = 'technical_failure'), bool_and(t.zero_reason = 'no_eligible_work')
    into v_tr, v_created, v_stalled, v_justified, v_technical, v_noelig from pipeline.progress_transitions t;
  select count(*) filter (where i.validation_layer <> 'manual'), count(*) filter (where i.validation_layer = 'manual') into v_auto_det, v_man_det
    from pipeline.integration_issues i where i.detected_at >= v_since;
  select count(*) filter (where i.remediation_owner is not null or i.ops_state in ('verifying', 'verified', 'remedying', 'superseded')), count(*) filter (where i.remediation_owner is null and coalesce(i.assignee, '') = '' and coalesce(i.ops_state, '') not in ('verifying', 'verified', 'remedying', 'superseded'))
    into v_owned, v_unowned from pipeline.integration_issues i where i.status <> 'closed';
  select count(*) filter (where r.result = 'verified'), count(*) filter (where r.result = 'verify_failed') into v_rem_ok, v_rem_fail
    from pipeline.ops_remedy_runs r join pipeline.ops_remedies m on m.code = r.remedy_code where r.started_at >= v_since and m.authority = 'auto';
  select count(*) filter (where w.recovered_at >= v_since), count(*) filter (where w.stage = 'parked' and w.next_eligible_at is null) into v_wc_rec, v_wc_parked_no_time from pipeline.work_items w;
  select t.output_admitted into v_sch_adm from pipeline.progress_transitions t where t.key = 'sch_admission';
  select t.output_admitted into v_aer_adm from pipeline.progress_transitions t where t.key = 'aer_active_records';
  select t.output_published into v_sch_pub from pipeline.progress_transitions t where t.key = 'sch_publication';
  select t.output_published into v_aer_pub from pipeline.progress_transitions t where t.key = 'aer_publication';
  select count(*) into v_l4 from pipeline.layer4_review_items i where i.status = 'pending';
  if to_regclass('pipeline.layer4_interventions') is not null then
    execute 'select count(*) from pipeline.layer4_interventions where status = ''awaiting_input''' into v_int;
  end if;
  select coalesce(sum(l.cost_usd), 0) into v_ai from pipeline.ai_spend_ledger l where l.at >= v_since;
  v_ai_cap := security.pipeline_num_v1('budgets.ai_daily_ceiling_usd', null);
  select coalesce(sum(u.units), 0) into v_fc from pipeline.coverage_vendor_usage u where u.at >= v_since;
  select coalesce(jsonb_object_agg(z.status, z.n), '{}'::jsonb) into v_rel from (select v.status, count(*) n from pipeline.release_job_verifications v group by 1) z;
  select count(*) into v_dc from pipeline.integration_deploy_checks d where d.checked_at >= v_since;
  v_out := jsonb_build_object('window_hours', p_window_hours, 'since', v_since, 'measures', jsonb_build_array(
    jsonb_build_object('measure', 'scheduled_job_reliability', 'runs', v_runs, 'failed', v_failed, 'justified_idle_transitions', v_justified,
      'verdict', case when v_runs is null or v_runs = 0 then 'not_measured' when v_failed = 0 then 'met' else 'not_met' end, 'basis', 'cron.job_run_details (newest ops.runs_scan runs); progress zero reasons'),
    jsonb_build_object('measure', 'automatic_diagnosis', 'detected_automatically', v_auto_det, 'raised_by_hand', v_man_det, 'open_owned', v_owned, 'open_unowned', v_unowned,
      'verdict', case when v_man_det = 0 and v_unowned = 0 then 'met' else 'not_met' end, 'basis', 'integration issues by validation layer; owner, remediation owner or controller state'),
    jsonb_build_object('measure', 'automatic_recovery', 'remedies_verified', v_rem_ok, 'remedies_failed', v_rem_fail,
      'verdict', case when v_rem_ok + v_rem_fail = 0 then 'not_measured' when v_rem_fail = 0 then 'met' else 'not_met' end, 'basis', 'pipeline.ops_remedy_runs of authority auto'),
    jsonb_build_object('measure', 'queue_continuity', 'work_items_recovered', v_wc_rec, 'parked_without_next_time', v_wc_parked_no_time, 'stalled_transitions', v_stalled,
      'verdict', case when v_stalled is null then 'not_measured' when v_stalled = 0 and v_wc_parked_no_time = 0 then 'met' else 'not_met' end, 'basis', 'pipeline.work_items; pipeline.progress_transitions'),
    jsonb_build_object('measure', 'source_to_admission_yield', 'scholarships_admitted', v_sch_adm, 'aer_rows_admitted', v_aer_adm,
      'verdict', case when v_sch_adm is null and v_aer_adm is null then 'not_measured' when coalesce(v_sch_adm, 0) > 0 and coalesce(v_aer_adm, 0) > 0 then 'met' else 'not_met' end,
      'basis', 'progress transitions sch_admission and aer_active_records'),
    jsonb_build_object('measure', 'admission_to_publication_yield', 'scholarships_published', v_sch_pub, 'aer_rows_on_published_providers', v_aer_pub,
      'verdict', case when v_sch_pub is null and v_aer_pub is null then 'not_measured' else 'needs_read_back' end,
      'basis', 'progress transitions sch_publication and aer_publication; Website API v2, Wix and Zoho read-back is a separate check (consumer-api-guard and the Integration Controller)'),
    jsonb_build_object('measure', 'human_intervention', 'layer4_pending', v_l4, 'interventions_awaiting_input', v_int,
      'verdict', 'reported', 'basis', 'pipeline.layer4_review_items; pipeline.layer4_interventions when present'),
    jsonb_build_object('measure', 'spending', 'ai_usd', round(v_ai, 3), 'ai_daily_ceiling_usd', v_ai_cap, 'firecrawl_units', v_fc,
      'verdict', case when v_ai_cap is null then 'not_measured' when v_ai <= v_ai_cap * greatest(p_window_hours, 1) / 24.0 then 'met' else 'not_met' end,
      'basis', 'pipeline.ai_spend_ledger against budgets.ai_daily_ceiling_usd; pipeline.coverage_vendor_usage'),
    jsonb_build_object('measure', 'release_correctness', 'first_run_verifications', v_rel, 'deploy_checks_in_window', v_dc,
      'verdict', case when v_rel = '{}'::jsonb then 'not_measured' when coalesce((v_rel->>'failed_first_run')::int, 0) = 0 and coalesce((v_rel->>'awaiting_first_run')::int, 0) = 0 then 'met' else 'not_met' end,
      'basis', 'pipeline.release_job_verifications; pipeline.integration_deploy_checks'),
    jsonb_build_object('measure', 'unattended_operation', 'last_job_failure', v_last_fail, 'hours_since_failure', round(extract(epoch from now() - coalesce(v_last_fail, v_since)) / 3600.0, 1),
      'eligible_data_processed', coalesce(v_created, 0) > 0, 'absence_of_work_proven', coalesce(v_noelig, false),
      'verdict', case when v_last_fail is null and (coalesce(v_created, 0) > 0 or coalesce(v_noelig, false)) and coalesce(v_technical, 0) = 0 then 'met' else 'not_met' end,
      'basis', 'no failed run in the window, eligible data processed (or no eligible work proven), no technical zero')),
    'transitions', v_tr);
  -- direction 4 Nov 2026 10:00 §7 and §11: the per-pipeline table and the states with no recovery condition (each isolated)
  begin v_out := v_out || security.pipeline_progress_table_v1(p_window_hours) - 'window_hours' - 'since';
  exception when others then v_out := v_out || jsonb_build_object('pipelines', jsonb_build_object('error', left(sqlerrm, 200))); end;
  begin v_out := v_out || jsonb_build_object('recovery_gaps', security.recovery_condition_gaps_v1(false));
  exception when others then v_out := v_out || jsonb_build_object('recovery_gaps', jsonb_build_object('error', left(sqlerrm, 200))); end;
  -- direction 4 Nov 2026 18:08 §1 and §7: who achieved the outcomes, and the recovery-learning table with its baseline (each isolated)
  begin v_out := v_out || jsonb_build_object('autonomy', security.autonomy_audit_v1(p_window_hours) - 'results');
  exception when others then v_out := v_out || jsonb_build_object('autonomy', jsonb_build_object('error', left(sqlerrm, 200))); end;
  begin v_out := v_out || jsonb_build_object('recovery_learning', security.ops_learning_report_v1());
  exception when others then v_out := v_out || jsonb_build_object('recovery_learning', jsonb_build_object('error', left(sqlerrm, 200))); end;
  return v_out;
end $$;


ALTER FUNCTION "security"."self_sustainability_v1"("p_window_hours" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."self_sustainability_v1"("p_window_hours" integer) IS 'CF-247 mandate 4 Nov 2026 08:16 §10: the ten self-sustainability measures from existing records (a section of security.ops_report_v1). Read only.';



CREATE OR REPLACE FUNCTION "security"."semester_intake_apply_v1"("p_provider_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security', 'search'
    AS $$
declare r record; v_ev pipeline.evidence_artifacts%rowtype; v_ok int := 0; v_err int := 0; v_last text; v_courses uuid[] := '{}'; v_reason text;
  v_names text[] := array['January','February','March','April','May','June','July','August','September','October','November','December'];
begin
  for r in select * from security.semester_intake_plan_v1(p_provider_id) where outcome = 'answer' loop
    begin
      select * into v_ev from pipeline.evidence_artifacts where id = (select evidence_id from pipeline.layer4_review_items where id = r.review_id);
      perform security.coverage_apply_course_v1(r.course_id, security.coverage_sweep_source(r.provider_id), v_ev.id, v_ev.source_url, v_ev.content_hash,
        jsonb_build_object('intakes', (select jsonb_agg(jsonb_build_object('intake_label', v_names[m], 'source_intake_key', 'calendar:' || r.course_id || ':' || lower(v_names[m])))
                                         from unnest(r.months) m)));
      v_reason := 'Answered from the course page (' || left(r.quotes, 200) || ') and the university''s approved calendar ('
                  || (select string_agg(initcap(replace(x, '_', ' ')) || ' starts in ' || v_names[(security.calendar_period_months(r.provider_id)->>x)::int], '; ') from unnest(r.periods) x)
                  || '); Decision 228.';
      update pipeline.layer4_review_items set status = 'superseded', decided_at = now(), escalation_reason = v_reason where id = r.review_id and status = 'pending';
      v_ok := v_ok + 1; v_courses := v_courses || r.course_id;
    exception when others then v_err := v_err + 1; v_last := left(sqlerrm, 200);
    end;
  end loop;
  if v_ok > 0 then
    insert into search.enrichment_source_gates(projection_code, domain_code, source_id, gate_status, approval_ref, approved_at, created_at, updated_at)
    select distinct 'courses', 'course_intake', security.coverage_sweep_source(c.provider_id), 'approved', 'CF-CHG-20260915-247; Decision 228 (intakes from the course page and the approved calendar)', now(), now(), now()
      from catalogue.courses c where c.id = any(v_courses)
       and not exists (select 1 from search.enrichment_source_gates g where g.projection_code = 'courses' and g.domain_code = 'course_intake' and g.source_id = security.coverage_sweep_source(c.provider_id));
    perform search.refresh_course_enrichment_scoped_v1(v_courses, true);
  end if;
  return jsonb_build_object('answered', v_ok, 'refused', v_err, 'last_error', v_last);
end $$;


ALTER FUNCTION "security"."semester_intake_apply_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."semester_intake_plan_v1"("p_provider_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("review_id" "uuid", "course_id" "uuid", "provider_id" "uuid", "title" "text", "quotes" "text", "periods" "text"[], "months" integer[], "outcome" "text", "reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'catalogue', 'pipeline', 'security'
    AS $$
begin
  return query
  with r as (
    select l.id, l.entity_id cid, c.provider_id pid, c.canonical_title t,
           (select string_agg(q, ' | ') from jsonb_array_elements_text(coalesce(l.layer3_state->'answer'->'quotes', '[]'::jsonb)) q) qs
      from pipeline.layer4_review_items l join catalogue.courses c on c.id = l.entity_id
     where l.status = 'pending' and l.entity_type = 'course' and l.field_code = 'course_intake' and l.before_value is null and l.evidence_id is not null
       and (p_provider_id is null or c.provider_id = p_provider_id)),
  p as (select r.*, security.quoted_study_periods(r.qs) per, security.calendar_period_months(r.pid) cal, security.calendar_set_by_hand(r.pid) byhand from r),
  q as (
    select p.*, (select array_agg(distinct (p.cal->>x)::int order by (p.cal->>x)::int) from unnest(p.per) x where p.cal ? x) mon,
           (select count(*) from unnest(p.per) x where not p.cal ? x) missing
      from p where cardinality(p.per) > 0)
  select q.id, q.cid, q.pid, q.t, q.qs, q.per, q.mon,
         case when q.qs ~* '\m(january|february|march|april|june|july|august|september|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|sept|oct|nov|dec)\M' then 'held'
              when q.qs ~* '\m(hong kong|HK|singapore|malaysia|sarawak|dubai|mauritius|sri lanka|vietnam|china|indonesia|online)\M' then 'held'
              when q.cal = '{}'::jsonb then 'no_calendar'
              when q.missing > 0 and not (q.byhand and q.mon is not null) then 'period_unknown'
              when exists (select 1 from catalogue.course_intakes i where i.course_id = q.cid and i.status = 'active') then 'held'
              when exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = q.cid and k.field = 'intakes') then 'held'
              else 'answer' end,
         case when q.qs ~* '\m(january|february|march|april|june|july|august|september|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|sept|oct|nov|dec)\M' then 'the quotes also name months'
              when q.qs ~* '\m(hong kong|HK|singapore|malaysia|sarawak|dubai|mauritius|sri lanka|vietnam|china|indonesia|online)\M' then 'the quotes name a campus outside Australia or online study'
              when q.cal = '{}'::jsonb then 'no approved calendar for this university'
              when q.missing > 0 and not (q.byhand and q.mon is not null) then 'a period has no approved start month'
              when exists (select 1 from catalogue.course_intakes i where i.course_id = q.cid and i.status = 'active') then 'the course already has intakes'
              when exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = q.cid and k.field = 'intakes') then 'intakes set by hand'
              end
    from q;
end $$;


ALTER FUNCTION "security"."semester_intake_plan_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."settings_backup_diff_v1"("p_backup" bigint) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with b as (select * from pipeline.settings_backups where id = p_backup),
  pv as (
    select p.id, coalesce(p.display_name, p.canonical_name) name, k.iso_alpha2 country, b2.v then_status, coalesce(p.publication_status, 'unpublished') now_status, p.lifecycle_status,
           (select jsonb_build_object('at', l.at, 'by', coalesce(u.email, l.actor::text), 'action', l.action) from pipeline.manual_edit_log l left join auth.users u on u.id = l.actor
             where l.entity = 'provider' and l.entity_id = p.id and l.field = 'publication_status' order by l.at desc limit 1) last_change
      from b, jsonb_each_text(b.providers) b2(id, v)
      join catalogue.providers p on p.id = b2.id::uuid
      left join ref.countries k on k.id = p.country_id
     where b2.v is distinct from coalesce(p.publication_status, 'unpublished')),
  sv as (
    select s.toolset_key, s.key, s.label, s.section, x->'value' then_value, s.value now_value, s.reason, s.updated_at, coalesce(u.email, s.updated_by::text) updated_by
      from b, jsonb_array_elements(b.settings) x
      join pipeline.platform_toolset_settings s on s.toolset_key = x->>'toolset_key' and s.key = x->>'key'
      left join auth.users u on u.id = s.updated_by
     where s.value is distinct from x->'value')
  select jsonb_build_object(
    'backup', (select jsonb_build_object('id', id, 'taken_at', taken_at, 'kind', kind, 'counts', counts) from b),
    'providers', coalesce((select jsonb_agg(to_jsonb(pv) order by (pv.now_status = 'published') desc, pv.name) from pv), '[]'::jsonb),
    'settings', coalesce((select jsonb_agg(to_jsonb(sv) order by sv.toolset_key, sv.key) from sv), '[]'::jsonb),
    'new_settings', (select count(*) from pipeline.platform_toolset_settings s, b
                      where not exists (select 1 from jsonb_array_elements(b.settings) x where x->>'toolset_key' = s.toolset_key and x->>'key' = s.key)),
    'new_providers', (select count(*) from catalogue.providers p, b where not (b.providers ? p.id::text)))
$$;


ALTER FUNCTION "security"."settings_backup_diff_v1"("p_backup" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."settings_backup_take_v1"("p_kind" "text" DEFAULT 'daily'::"text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id bigint; v_old int := 0; v_counts jsonb;
begin
  select jsonb_build_object('providers', count(*), 'published', count(*) filter (where publication_status = 'published'),
                            'unpublished', count(*) filter (where publication_status is distinct from 'published'),
                            'settings', (select count(*) from pipeline.platform_toolset_settings))
    into v_counts from catalogue.providers;
  insert into pipeline.settings_backups(kind, taken_by, note, providers, settings, counts)
  values (p_kind, auth.uid(), left(p_note, 500),
          (select coalesce(jsonb_object_agg(p.id::text, coalesce(p.publication_status, 'unpublished')), '{}'::jsonb) from catalogue.providers p),
          (select coalesce(jsonb_agg(jsonb_build_object('toolset_key', s.toolset_key, 'key', s.key, 'value', s.value) order by s.toolset_key, s.key), '[]'::jsonb) from pipeline.platform_toolset_settings s),
          v_counts)
  returning id into v_id;
  if p_kind = 'daily' then
    delete from pipeline.settings_backups
     where taken_at < now() - make_interval(days => security.pipeline_num_v1('retention.settings_backup_days', 60)::int);
    get diagnostics v_old = row_count;
  end if;
  return jsonb_build_object('backup_id', v_id, 'counts', v_counts, 'removed', v_old);
end $$;


ALTER FUNCTION "security"."settings_backup_take_v1"("p_kind" "text", "p_note" "text") OWNER TO "postgres";


