    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select s.data - 'task_progress' from pipeline.stats_15m s order by s.at desc limit 1  -- fixed: the latest snapshot
$$;


ALTER FUNCTION "security"."stats_15m_report_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."stats_15m_v1"("p_countries" "text"[] DEFAULT ARRAY['NZ'::"text", 'CA'::"text"]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "statement_timeout" TO '120s'
    AS $_$
declare
  v_now timestamptz := now(); v_prev jsonb; v_day jsonb; v_countries jsonb := '{}'::jsonb; v_c text; v_f jsonb; v_gaps jsonb := '[]'::jsonb; v_data jsonb;
  v_slow numeric := security.pipeline_num_v1('stats.slow_call_seconds', 60);
  v_wait interval := make_interval(mins => security.pipeline_num_v1('stats.task_wait_minutes', 60)::int);
  v_flat interval := make_interval(hours => security.pipeline_num_v1('stats.flat_field_hours', 24)::int);
  v_fc jsonb; v_ai jsonb; v_calls jsonb; v_queues jsonb; v_tasks jsonb; v_old jsonb; k text;
begin
  select s.data into v_prev from pipeline.stats_15m s where s.at > v_now - interval '25 minutes' order by s.at desc limit 1;  -- fixed: the previous 15-minute snapshot
  select s.data into v_day from pipeline.stats_15m s where s.at <= v_now - interval '24 hours' order by s.at desc limit 1;  -- fixed: the same time yesterday
  select s.data into v_old from pipeline.stats_15m s where s.at <= v_now - v_flat order by s.at desc limit 1;  -- fixed: one snapshot
  foreach v_c in array p_countries loop
    v_f := security.stats_15m_fields_v1(v_c);
    v_countries := v_countries || jsonb_build_object(v_c, jsonb_build_object('now', v_f,
      'change_15m', (select jsonb_object_agg(e.key, (e.value)::numeric - coalesce((v_prev->'countries'->v_c->'now'->>e.key)::numeric, (e.value)::numeric)) from jsonb_each(v_f) e),
      'change_24h', case when v_day is null then null else (select jsonb_object_agg(e.key, (e.value)::numeric - coalesce((v_day->'countries'->v_c->'now'->>e.key)::numeric, (e.value)::numeric)) from jsonb_each(v_f) e) end));
    -- gap: a field below every course that has not moved since the snapshot stats.flat_field_hours ago
    if v_old is not null then
      for k in select e.key from jsonb_each(v_f) e where e.key <> 'courses' and (e.value)::numeric < (v_f->>'courses')::numeric
                 and (e.value)::numeric <= coalesce((v_old->'countries'->v_c->'now'->>e.key)::numeric, -1) loop
        v_gaps := v_gaps || jsonb_build_object('kind', 'field_flat', 'country', v_c, 'field', k, 'held', (v_f->>k)::numeric, 'courses', (v_f->>'courses')::numeric,
                                               'note', v_c || ' ' || k || ' has not gained a course in ' || extract(epoch from v_flat)::int / 3600 || ' hours');
      end loop;
    end if;
  end loop;

  -- Firecrawl: units in the last 15 minutes and today by share
  v_fc := security.fc_budget_status_v1() || jsonb_build_object('last_15m', (select coalesce(jsonb_object_agg(g, n), '{}'::jsonb) from (
            select security.fc_purpose_group_v1(u.purpose) g, sum(u.units) n from pipeline.coverage_vendor_usage u where u.at > v_now - interval '15 minutes' group by 1) z));  -- fixed: the 15-minute window
  for k in select x->>'group' from jsonb_array_elements(v_fc->'groups') x where (x->>'share')::numeric > 0 and ((x->>'used')::numeric >= (x->>'share')::numeric
                   or exists (select 1 from pipeline.firecrawl_budget_refusals r where r.day = (v_now at time zone 'Australia/Melbourne')::date and r.grp = x->>'group' and r.reason <> 'not_due')) loop
    v_gaps := v_gaps || (select jsonb_build_object('kind', 'firecrawl_share', 'group', x->>'group', 'used', (x->>'used')::numeric, 'share', (x->>'share')::numeric, 'refused', (x->>'refused')::numeric,
                                 'note', 'Firecrawl share "' || (x->>'label') || '": ' || (x->>'used') || ' of ' || (x->>'share') || ' used today, ' || (x->>'refused') || ' refused')
                           from jsonb_array_elements(v_fc->'groups') x where x->>'group' = k);
  end loop;

  -- AI spend today by use against its guard
  v_ai := (select coalesce(jsonb_agg(jsonb_build_object('use', a.use, 'label', a.label, 'spent_usd', a.spent, 'guard_usd', a.guard, 'calls', a.calls)), '[]'::jsonb) from security.ai_spend_today_v1() a);
  v_gaps := v_gaps || (select coalesce(jsonb_agg(jsonb_build_object('kind', 'ai_guard', 'use', a.use, 'note', 'AI guard reached for ' || a.label || ': US$' || a.spent || ' of ' || a.guard)), '[]'::jsonb)
                         from security.ai_spend_today_v1() a where coalesce(a.guard, 0) > 0 and a.spent >= a.guard);

  -- worker calls in the last 15 minutes by kind
  with r as (select l.mode, x.status_code, x.timed_out, x.error_msg, case when x.content like '{%' then (x.content::jsonb->>'ms')::numeric end ms
               from pipeline.edge_request_log l left join net._http_response x on x.id = l.request_id
              where l.function_name = 'coverage-sweep' and l.created_at > v_now - interval '15 minutes')  -- fixed: the 15-minute window
  select coalesce(jsonb_object_agg(mode, jsonb_build_object('calls', calls, 'failed', failed, 'no_answer', no_answer, 'avg_s', avg_s, 'max_s', max_s)), '{}'::jsonb) into v_calls
    from (select coalesce(r.mode, '?') mode, count(*) calls, count(*) filter (where r.status_code >= 400 or r.timed_out or r.error_msg is not null) failed,
                 count(*) filter (where r.status_code is null and r.error_msg is null) no_answer,
                 round(avg(r.ms) / 1000, 1) avg_s, round(max(r.ms) / 1000, 1) max_s from r group by 1) z;
  v_gaps := v_gaps || (select coalesce(jsonb_agg(jsonb_build_object('kind', 'worker', 'mode', e.key, 'note', 'Worker ' || e.key || ': ' || (e.value->>'failed') || ' of ' || (e.value->>'calls') || ' calls failed, slowest ' || coalesce(e.value->>'max_s', '?') || ' s')), '[]'::jsonb)
                         from jsonb_each(v_calls) e where (e.value->>'failed')::int > 0 or coalesce((e.value->>'max_s')::numeric, 0) > v_slow);

  -- watchdog states and tasks waiting
  v_queues := (select coalesce(jsonb_object_agg(s.key, jsonb_build_object('state', s.state, 'waiting', s.pending, 'per_hour', s.per_hour, 'eta_hours', s.eta_hours)), '{}'::jsonb) from pipeline.queue_watch_state s);
  v_gaps := v_gaps || (select coalesce(jsonb_agg(jsonb_build_object('kind', 'queue', 'queue', s.key, 'state', s.state, 'note', w.label || ': ' || s.state || coalesce(' (' || s.reason || ')', ''))), '[]'::jsonb)
                         from pipeline.queue_watch_state s join pipeline.queue_watch w on w.key = s.key where s.state in ('stuck', 'failing', 'out_of_toolset'));
  v_tasks := (select jsonb_build_object('running', count(*) filter (where j.state = 'running'), 'queued', count(*) filter (where j.state = 'queued'),
                     'not_moving', count(*) filter (where j.state in ('running', 'queued') and j.updated_at < v_now - v_wait),
                     'by_kind', (select coalesce(jsonb_object_agg(kind, n), '{}'::jsonb) from (select j2.kind, count(*) n from pipeline.admin_jobs j2 where j2.state in ('running', 'queued') group by 1) z))
                from pipeline.admin_jobs j);
  v_gaps := v_gaps || (select coalesce(jsonb_agg(jsonb_build_object('kind', 'task', 'id', j.id, 'note', j.title || ': no progress since ' || to_char(j.updated_at at time zone 'Australia/Melbourne', 'HH24:MI') || coalesce(' (' || (j.progress->>'phase') || ')', ''))), '[]'::jsonb)
                         from pipeline.admin_jobs j where j.state in ('running', 'queued') and coalesce((j.progress->>'done')::numeric, 0) = coalesce((select (p.data->'task_progress'->>(j.id::text))::numeric from pipeline.stats_15m p where p.at <= v_now - v_wait order by p.at desc limit 1), -1)  -- fixed: one snapshot
                           and j.created_at < v_now - v_wait);

  v_data := jsonb_build_object('at', v_now, 'countries', v_countries, 'firecrawl', v_fc, 'ai', v_ai, 'worker_calls_15m', v_calls, 'queues', v_queues, 'tasks', v_tasks,
    'task_progress', (select coalesce(jsonb_object_agg(j.id::text, coalesce((j.progress->>'done')::numeric, 0)), '{}'::jsonb) from pipeline.admin_jobs j where j.state in ('running', 'queued')),
    'gaps', v_gaps);
  insert into pipeline.stats_15m(at, data) values (v_now, v_data);
  return jsonb_build_object('at', v_now, 'gaps', jsonb_array_length(v_gaps));
end $_$;


ALTER FUNCTION "security"."stats_15m_v1"("p_countries" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."storage_prefix_audit_v1"() RETURNS TABLE("bucket" "text", "prefix" "text", "owner" "text", "objects" bigint, "bytes" bigint, "first_at" timestamp with time zone, "last_at" timestamp with time zone, "written_7d" bigint, "registered_evidence" bigint, "referenced" bigint, "unreferenced" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- CF-247 storage housekeeping, read-only: the non-evidence prefixes of the evidence bucket and the adapter-captures bucket, what their owner still
  -- references and what nothing references. It moves and removes nothing.
  with o as (
    select x.bucket_id, x.name, coalesce((x.metadata->>'size')::bigint, 0) sz, x.created_at,
           case when x.bucket_id = 'adapter-captures' then 'adapter-captures/<provider>/<draft>/'
                when x.name ~ '^layer2/[A-Z]{2}/firecrawl/' then 'layer2/<CC>/firecrawl/'
                when x.name ~ '^layer2/[A-Z]{2}/adapters/' then 'layer2/<CC>/adapters/'
                when x.name ~ '^layer2/[A-Z]{2}/companion/' then 'layer2/<CC>/companion/' end fam
      from storage.objects x
     where x.bucket_id = 'adapter-captures' or (x.bucket_id = 'evidence' and x.name ~ '^layer2/[A-Z]{2}/(firecrawl|adapters|companion)/')),
  cap as (select c->>'html_path' html_path, c->>'screenshot_path' shot_path
            from pipeline.uni_adapter_drafts d, jsonb_array_elements(case when jsonb_typeof(d.captures) = 'array' then d.captures else '[]'::jsonb end) c),
  refs as (
    select 'layer2/<CC>/companion/' fam, p.storage_path path from pipeline.course_companion_pages p where p.storage_path is not null
    union select 'layer2/<CC>/adapters/', cap.html_path from cap where cap.html_path is not null
    union select 'adapter-captures/<provider>/<draft>/', cap.shot_path from cap where cap.shot_path is not null
    union select 'layer2/<CC>/firecrawl/', r.result->>'search_path' from pipeline.firecrawl_run_items r where r.result ? 'search_path')
  select o.bucket_id, o.fam,
         case o.fam when 'layer2/<CC>/firecrawl/' then 'Firecrawl search results: pipeline.firecrawl_run_items.result->>search_path'
                    when 'layer2/<CC>/adapters/' then 'adapter builder pages: pipeline.uni_adapter_drafts.captures[].html_path'
                    when 'layer2/<CC>/companion/' then 'course companion pages: pipeline.course_companion_pages.storage_path'
                    else 'adapter builder screenshots: pipeline.uni_adapter_drafts.captures[].screenshot_path' end,
         count(*), sum(o.sz)::bigint, min(o.created_at), max(o.created_at), count(*) filter (where o.created_at > now() - interval '7 days'),  -- fixed: report window
         count(*) filter (where exists (select 1 from pipeline.evidence_artifacts e where e.storage_path = o.name)),
         count(*) filter (where exists (select 1 from refs where refs.fam = o.fam and refs.path = o.name)),
         count(*) filter (where not exists (select 1 from refs where refs.fam = o.fam and refs.path = o.name))
    from o group by o.bucket_id, o.fam order by o.bucket_id, o.fam
$$;


ALTER FUNCTION "security"."storage_prefix_audit_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."storage_size_snapshot_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_day date := (now() at time zone 'Australia/Melbourne')::date; v_tables int; v_removed int;
begin
  -- tables (and materialised views): bytes from the catalogue, rows from the planner's estimate (no table is scanned)
  insert into pipeline.storage_size_daily(day, kind, name, bytes, table_bytes, index_bytes, toast_bytes, rows_estimate)
  select v_day, 'table', n.nspname || '.' || c.relname, pg_total_relation_size(c.oid), pg_relation_size(c.oid), pg_indexes_size(c.oid),
         coalesce(pg_total_relation_size(nullif(c.reltoastrelid, 0)), 0), greatest(c.reltuples, 0)::bigint
    from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid = c.relnamespace
   where c.relkind in ('r', 'm', 'p') and n.nspname not in ('pg_catalog', 'information_schema') and n.nspname not like 'pg_toast%'
  on conflict (day, kind, name) do update set bytes = excluded.bytes, table_bytes = excluded.table_bytes, index_bytes = excluded.index_bytes,
     toast_bytes = excluded.toast_bytes, rows_estimate = excluded.rows_estimate, measured_at = now();
  get diagnostics v_tables = row_count;
  insert into pipeline.storage_size_daily(day, kind, name, bytes, table_bytes, index_bytes, toast_bytes, rows_estimate)
  select v_day, 'schema', split_part(t.name, '.', 1), sum(t.bytes), sum(t.table_bytes), sum(t.index_bytes), sum(t.toast_bytes), sum(t.rows_estimate)
    from pipeline.storage_size_daily t where t.day = v_day and t.kind = 'table' group by 3
  on conflict (day, kind, name) do update set bytes = excluded.bytes, table_bytes = excluded.table_bytes, index_bytes = excluded.index_bytes,
     toast_bytes = excluded.toast_bytes, rows_estimate = excluded.rows_estimate, measured_at = now();
  insert into pipeline.storage_size_daily(day, kind, name, bytes)
  values (v_day, 'database', 'database', pg_database_size(current_database()))
  on conflict (day, kind, name) do update set bytes = excluded.bytes, measured_at = now();
  -- buckets: the file sizes Supabase Storage records for each file
  insert into pipeline.storage_size_daily(day, kind, name, bytes, files)
  select v_day, 'bucket', o.bucket_id, coalesce(sum((o.metadata ->> 'size')::bigint), 0), count(*)
    from storage.objects o group by o.bucket_id
  on conflict (day, kind, name) do update set bytes = excluded.bytes, files = excluded.files, measured_at = now();
  delete from pipeline.storage_size_daily
   where kind = 'table' and day < v_day - security.pipeline_num_v1('storage.size_keep_days', 365)::int;
  get diagnostics v_removed = row_count;
  return jsonb_build_object('day', v_day, 'tables', v_tables, 'old_rows_removed', v_removed);
end $$;


ALTER FUNCTION "security"."storage_size_snapshot_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."studysearch_acronym_v1"("p_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v text; w text[]; s text := ''; x text;
begin
  -- the university's own short name when it is in brackets, e.g. "University of British Columbia (UBC)"
  v := (regexp_match(coalesce(p_name, ''), '\(([A-Za-z&]{2,8})\)'))[1];
  if v is not null then v := upper(regexp_replace(v, '[^A-Za-z]', '', 'g')); if length(v) between 2 and 6 then return v; end if; end if;
  w := array(select t from regexp_split_to_table(
         translate(regexp_replace(lower(coalesce(p_name, '')), '\(.*?\)', ' ', 'g'), 'éèêëàâäîïôöûüùçñ', 'eeeeaaaiioouuucn'), '[^a-z0-9]+') t
       where t <> '' and t not in ('of','the','and','for','at','in','de','du','des','la','le','les','et','d','l','pty','ltd','limited','inc','co'));
  if coalesce(array_length(w, 1), 0) >= 3 then
    foreach x in array w loop s := s || left(x, 1); end loop;
    return upper(left(s, 5));
  end if;
  -- one or two words: four letters of the distinctive word ("Humber College" HUMB, "University of Toronto" TORO)
  foreach x in array w loop
    if x not in ('university','universite','college','cegep','institute','institut','polytechnic','school','academy','centre','center',
                 'campus','international','education','technology','tafe') then return upper(left(x, 4)); end if;
  end loop;
  if coalesce(array_length(w, 1), 0) > 0 then return upper(left(w[1], 4)); end if;
  return 'UNI';
end $$;


ALTER FUNCTION "security"."studysearch_acronym_v1"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."studysearch_code_assign_v1"("p_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare r record; v_base text; v_code text; i int; v_prov int := 0; v_courses int := 0;
begin
  create temp table if not exists _ss_need (id uuid, provider_id uuid, country_id uuid, pname text, title text, level_id uuid) on commit drop;
  truncate _ss_need;
  insert into _ss_need
  select c.id, c.provider_id, p.country_id, coalesce(p.display_name, p.canonical_name), c.canonical_title, c.study_level_id
    from catalogue.courses c join catalogue.providers p on p.id = c.provider_id
   where not exists (select 1 from catalogue.course_identifiers i where i.course_id = c.id and i.scheme = 'studysearch')
     -- a printed code: one from a printed identifier type, or a code entered with no identifier behind it
     and not (nullif(btrim(c.course_code), '') is not null
              and (not exists (select 1 from catalogue.course_identifiers i where i.course_id = c.id)
                   or exists (select 1 from catalogue.course_identifiers i join ref.course_code_schemes s on s.scheme = i.scheme and s.printed
                               where i.course_id = c.id)))
   order by c.provider_id, lower(c.canonical_title), c.id
   limit greatest(coalesce(p_limit, 0), 0);
  -- university codes, unique within the country
  for r in select distinct n.provider_id, n.country_id, n.pname from _ss_need n
            where not exists (select 1 from catalogue.provider_identifiers x where x.provider_id = n.provider_id and x.scheme = 'studysearch_provider') loop
    v_base := security.studysearch_acronym_v1(r.pname); v_code := v_base; i := 1;
    while exists (select 1 from catalogue.provider_identifiers x join catalogue.providers p2 on p2.id = x.provider_id
                   where x.scheme = 'studysearch_provider' and x.identifier = v_code and p2.country_id is not distinct from r.country_id) loop
      i := i + 1; v_code := v_base || i;
    end loop;
    insert into catalogue.provider_identifiers(provider_id, scheme, identifier, country_id, issuing_authority, is_primary)
    values (r.provider_id, 'studysearch_provider', v_code, r.country_id, 'StudySearch', false);
    v_prov := v_prov + 1;
  end loop;
  insert into catalogue.course_identifiers(course_id, provider_id, scheme, identifier, country_id, issuing_authority, is_primary)
  select n.id, n.provider_id, 'studysearch',
         pc.identifier || '-' || n.lvl || '-' || lpad((coalesce(mx.m, 0) + row_number() over (partition by n.provider_id, n.lvl order by lower(n.title), n.id))::text, 3, '0'),
         n.country_id, 'StudySearch', false
    from (select x.*, security.studysearch_level_v1(x.level_id, x.title) lvl from _ss_need x) n
    join catalogue.provider_identifiers pc on pc.provider_id = n.provider_id and pc.scheme = 'studysearch_provider'
    left join lateral (select max(substring(i.identifier from '-([0-9]+)$')::int) m from catalogue.course_identifiers i
                        where i.provider_id = n.provider_id and i.scheme = 'studysearch' and i.identifier like pc.identifier || '-' || n.lvl || '-%') mx on true
  on conflict (provider_id, scheme, identifier) do nothing;
  get diagnostics v_courses = row_count;
  return jsonb_build_object('universities', v_prov, 'courses', v_courses);
end $_$;


ALTER FUNCTION "security"."studysearch_code_assign_v1"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."studysearch_level_v1"("p_level" "uuid", "p_title" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce((select sl.short_code from ref.study_levels sl where sl.id = p_level),
    case when p_title ~* '(ph\.?d|doctor)' then 'DR'
         when p_title ~* 'master|ma[iî]trise' then 'MA'
         when p_title ~* '(graduate|post-?graduate|postgrad|post-?baccalaur|post-?dipl).{0,12}(diploma|dipl[oô]me)' then 'GD'
         when p_title ~* '(graduate|post-?graduate|postgrad).{0,12}(certificate|certificat)' then 'GC'
         when p_title ~* 'bachelor|baccalaur' then 'BA'
         when p_title ~* 'advanced diploma' then 'AD'
         when p_title ~* 'diploma|dipl[oô]me|\mdec\M' then 'DP'
         when p_title ~* 'certificate|certificat|attestation|\maec\M' then 'CT'
         when p_title ~* 'degree' then 'DG'
         else 'CO' end)
$$;


ALTER FUNCTION "security"."studysearch_level_v1"("p_level" "uuid", "p_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."sync_evidence_entity_links"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$
declare v_old jsonb; v_new jsonb; v_evidence uuid; r record; v_table text:=tg_table_schema||'.'||tg_table_name;
begin
  if tg_op in ('UPDATE','DELETE') then v_old:=to_jsonb(old); v_evidence:=nullif(v_old->>'evidence_id','')::uuid; if v_evidence is not null then for r in select * from security.evidence_row_entity_links(v_table,v_old) loop perform security.adjust_evidence_entity_link(v_evidence,r.entity_type,r.entity_id,r.provider_id,-1); end loop; end if; end if;
  if tg_op in ('INSERT','UPDATE') then v_new:=to_jsonb(new); v_evidence:=nullif(v_new->>'evidence_id','')::uuid; if v_evidence is not null then for r in select * from security.evidence_row_entity_links(v_table,v_new) loop perform security.adjust_evidence_entity_link(v_evidence,r.entity_type,r.entity_id,r.provider_id,1); end loop; end if; end if;
  return case when tg_op='DELETE' then old else new end;
end $$;


ALTER FUNCTION "security"."sync_evidence_entity_links"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."sync_evidence_lineage_stats"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'security'
    AS $$
declare
  v_old jsonb;
  v_new jsonb;
  v_old_evidence uuid;
  v_new_evidence uuid;
  v_table text:=tg_table_schema||'.'||tg_table_name;
begin
  if tg_op in ('UPDATE','DELETE') then
    v_old:=to_jsonb(old);
    v_old_evidence:=nullif(v_old->>'evidence_id','')::uuid;
    perform security.adjust_evidence_lineage_stats(
      v_old_evidence,
      -1,
      case when security.evidence_row_source_null(v_table,v_old) then -1 else 0 end,
      case when security.evidence_row_rejected(v_old) then -1 else 0 end
    );
  end if;
  if tg_op in ('INSERT','UPDATE') then
    v_new:=to_jsonb(new);
    v_new_evidence:=nullif(v_new->>'evidence_id','')::uuid;
    perform security.adjust_evidence_lineage_stats(
      v_new_evidence,
      1,
      case when security.evidence_row_source_null(v_table,v_new) then 1 else 0 end,
      case when security.evidence_row_rejected(v_new) then 1 else 0 end
    );
  end if;
  return case when tg_op='DELETE' then old else new end;
end
$$;


ALTER FUNCTION "security"."sync_evidence_lineage_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."system_actor_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'auth', 'security'
    AS $$
  select u.id from auth.users u
  where u.id='c0ffee00-0000-4000-8000-000000000150' and (u.raw_app_meta_data->>'system_identity')='true'
    and exists (select 1 from security.user_roles ur join security.roles r on r.code=ur.role_code
                where ur.user_id=u.id and r.status='active' and r.rank>=4 and (ur.expires_at is null or ur.expires_at>now()))
$$;


ALTER FUNCTION "security"."system_actor_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."telemetry_layer_funnel_v1"("p_hours" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- the 24-hour (p_hours) life of course pages and field readings: pages bound to a course (L1) and read (L2), then per field the readings an AI made
  -- (L3), admitted by a rule (L4 auto: course descriptions admitted by the machine rule, other fields filled), sent to a person (L4 review), held by a
  -- check (L4 held) or failed, the catalogue change they made, the share of AI cost spent on readings held, failed or not admitted (AI waste), and
  -- admitted per AI reading (end-to-end yield).
  with w as (select now() - make_interval(hours => greatest(coalesce(p_hours, 1), 1)) t0),
  pages as (select count(*) filter (where p.bound_at >= (select t0 from w)) l1_discovered,
                   count(*) filter (where p.read_at >= (select t0 from w) and p.read_status = 'read') l2_readable_pages,
                   count(*) filter (where p.read_at >= (select t0 from w) and p.read_status is distinct from 'read') l2_not_readable
              from pipeline.coverage_course_pages p where p.bound_at >= (select t0 from w) or p.read_at >= (select t0 from w)),
  items as (select e.id, e.field, e.state, e.reason, coalesce(e.cost_usd, 0) cost,
                   e.field = 'description' and exists (select 1 from pipeline.course_description_machine_admissions a where a.reading_item_id = e.id and a.outcome = 'admitted') desc_admitted
              from pipeline.field_enrich_items e where e.updated_at >= (select t0 from w) and e.model is not null),
  f as (select field, count(*) l3, count(*) filter (where case when field = 'description' then desc_admitted else state = 'filled' end) auto_adm,
               count(*) filter (where state = 'review' and not desc_admitted) human, count(*) filter (where state = 'skipped' and reason like 'held%') held,
               count(*) filter (where state = 'failed') failed, sum(cost) cost,
               sum(cost) filter (where not (case when field = 'description' then desc_admitted else state = 'filled' end) and state <> 'review') waste
          from items group by field)
  select jsonb_build_object('window_hours', greatest(coalesce(p_hours, 1), 1), 'as_at', now(),
    'pages', (select to_jsonb(pages) from pages),
    'fields', coalesce((select jsonb_agg(jsonb_build_object('field', f.field, 'L3_ai_called', f.l3, 'L4_auto_admitted', f.auto_adm, 'L4_human_review', f.human,
        'L4_held', f.held, 'failed', f.failed, 'Catalogue_live_delta', f.auto_adm, 'ai_cost_usd', round(f.cost::numeric, 4),
        'AI_waste_pct', case when f.cost > 0 then round(100.0 * coalesce(f.waste, 0) / f.cost, 1) end,
        'end_to_end_yield_pct', case when f.l3 > 0 then round(100.0 * f.auto_adm / f.l3, 1) end) order by f.l3 desc) from f), '[]'::jsonb))
$$;


ALTER FUNCTION "security"."telemetry_layer_funnel_v1"("p_hours" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."telemetry_layer_funnel_v1"("p_hours" integer) IS 'CF-247 telemetry (Platform Admin 16 Nov 2026 12:36): pages bound and read, then per field the readings an AI made, admitted, sent to a person, held or failed, the catalogue change, AI waste and end-to-end yield, over the last p_hours. Read only; feeds the Layer_Lifecycle_Funnel tab.';



CREATE OR REPLACE FUNCTION "security"."telemetry_model_tier_v1"("p_hours" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- by AI service and model tier (primary: the first model of the service's route; retry: any later model), over the last p_hours: calls, tokens,
  -- ledger cost, and for the services whose readings are tracked per item, how many were admitted (course descriptions: an admission by the machine
  -- rule from that reading; other course fields: the reading filled), the share of first-model readings admitted, the share of second-model
  -- readings that rescued an item, and the cost of each admitted record. The account row compares OpenRouter's own figure for the last complete UTC
  -- day with the ledger for that day: spend the ledger never received (for example calls stopped part-way, HTTP 546).
  with w as (select now() - make_interval(hours => greatest(coalesce(p_hours, 1), 1)) t0),
  r as (select rt.service_code, (select c.model_identifier from pipeline.ai_model_catalogue c where c.code = rt.cascade[1]) primary_model from pipeline.ai_service_routes rt),
  inv as (select i.service_code, case when i.model = r.primary_model then 'primary' else 'retry' end tier, i.outcome, i.input_tokens, i.output_tokens, i.cost_usd
            from pipeline.ai_invocations i left join r on r.service_code = i.service_code where i.at >= (select t0 from w)),
  agg as (select coalesce(service_code, '(unnamed)') service_code, tier, count(*) calls, count(*) filter (where outcome = 'answered') answered,
                 coalesce(sum(input_tokens), 0) itok, coalesce(sum(output_tokens), 0) otok, coalesce(sum(cost_usd), 0) usd from inv group by 1, 2),
  fmap(service_code, field) as (values ('course_description', 'description'), ('course_entry_requirements', 'entry_requirements')),
  reads as (select f.service_code, case when e.model = r.primary_model then 'primary' else 'retry' end tier, count(*) n,
                   count(*) filter (where case when f.field = 'description'
                                               then exists (select 1 from pipeline.course_description_machine_admissions a where a.reading_item_id = e.id and a.outcome = 'admitted')
                                               else e.state = 'filled' end) admitted
              from pipeline.field_enrich_items e join fmap f on f.field = e.field left join r on r.service_code = f.service_code
             where e.updated_at >= (select t0 from w) and e.model is not null and e.state in ('filled', 'review', 'skipped', 'failed')
             group by 1, 2),
  utc_day as (select (date_trunc('day', now() at time zone 'UTC') - interval '1 day') d0, date_trunc('day', now() at time zone 'UTC') d1),
  gap as (select (select max(k.usage_daily) from pipeline.openrouter_key_observations k, utc_day u
                   where (k.observed_at at time zone 'UTC') >= u.d0 and (k.observed_at at time zone 'UTC') < u.d1) openrouter_usd,
                 (select coalesce(sum(i.cost_usd), 0) from pipeline.ai_invocations i, utc_day u
                   where (i.at at time zone 'UTC') >= u.d0 and (i.at at time zone 'UTC') < u.d1) ledger_usd)
  select jsonb_build_object('window_hours', greatest(coalesce(p_hours, 1), 1), 'as_at', now(), 'rows', coalesce((select jsonb_agg(jsonb_build_object(
      'service_code', a.service_code, 'model_tier', a.tier, 'calls', a.calls, 'answered', a.answered, 'input_tokens', a.itok, 'output_tokens', a.otok,
      'ledger_usd', round(a.usd::numeric, 4),
      'readings', rd.n, 'admitted', rd.admitted,
      'first_pass_admit_rate_pct', case when a.tier = 'primary' and rd.n > 0 then round(100.0 * rd.admitted / rd.n, 1) end,
      'retry_rescue_rate_pct', case when a.tier = 'retry' and a.answered > 0 and rd.n is not null then round(100.0 * rd.admitted / a.answered, 1) end,
      'cost_per_admitted_record_usd', case when rd.admitted > 0 then round((a.usd / rd.admitted)::numeric, 5) end)
      order by a.service_code, a.tier) from agg a left join reads rd on rd.service_code = a.service_code and rd.tier = a.tier), '[]'::jsonb),
    'account', (select jsonb_build_object('utc_day', (select to_char(d0, 'YYYY-MM-DD') from utc_day), 'openrouter_usd', round(g.openrouter_usd::numeric, 4),
                'ledger_usd', round(g.ledger_usd::numeric, 4), 'unlogged_546_gap_usd', round(greatest(coalesce(g.openrouter_usd, 0) - g.ledger_usd, 0)::numeric, 4)) from gap g))
$$;


ALTER FUNCTION "security"."telemetry_model_tier_v1"("p_hours" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."telemetry_model_tier_v1"("p_hours" integer) IS 'CF-247 telemetry (Platform Admin 16 Nov 2026 12:36): AI calls, tokens, cost and admission yield by service and model tier over the last p_hours, and the OpenRouter spend the ledger did not receive for the last complete UTC day. Read only; feeds the Model_Tier_&_Token_Efficiency tab.';



CREATE OR REPLACE FUNCTION "security"."third_party_host_v1"("p_url" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce((select bool_or(case when l.domain like '%.%' then h = l.domain or h like '%.' || l.domain else h ~ ('(^|\.)' || l.domain) end)
                     from pipeline.important_links l, (select security.site_host_v1(p_url) h) x
                    where x.h is not null and l.enabled and l.retired_at is null and l.domain is not null and 'not_provider_site' = any(l.uses)
                      and l.authority_category in ('third_party_directory', 'general_web', 'ranking_publisher')), false)
$$;


ALTER FUNCTION "security"."third_party_host_v1"("p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."toolset_backlog"("p_purpose" "text", "p_country" "text") RETURNS TABLE("subject_key" "text", "course_id" "uuid", "provider_id" "uuid", "input" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select 'course:' || c.id, c.id, p.id,
         jsonb_build_object('course', coalesce(c.display_title, c.canonical_title), 'code', c.course_code, 'provider', coalesce(p.display_name, p.canonical_name),
                            'domain', regexp_replace(lower(substring(p.website from '^(?:https?://)?([^/?#]+)')), '^www\.', ''), 'country', k.name,
                            'earlier_candidate', pg.url, 'earlier_status', pg.status)
  from catalogue.courses c join catalogue.providers p on p.id = c.provider_id join ref.countries k on k.id = p.country_id
  left join pipeline.coverage_course_pages pg on pg.course_id = c.id
  where p_purpose = 'find_course_page' and k.iso_alpha2 = p_country and c.lifecycle_status = 'active'
    and p.website is not null and pg.status is distinct from 'bound'
  union all
  select 'provider:' || p.id, null, p.id,
         jsonb_build_object('provider', coalesce(p.display_name, p.canonical_name), 'city', coalesce(p.primary_city, ''), 'country', k.name)
  from catalogue.providers p join ref.countries k on k.id = p.country_id
  where p_purpose = 'find_provider_site' and k.iso_alpha2 = p_country and p.website is null
    and exists (select 1 from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active')
  union all
  select 'page:' || pg.course_id, pg.course_id, pg.provider_id,
         jsonb_build_object('url', pg.url, 'course', coalesce(c.display_title, c.canonical_title), 'code', c.course_code, 'provider', coalesce(p.display_name, p.canonical_name),
                            'earlier_read', pg.read_status, 'earlier_http', pg.http_status)
  from pipeline.coverage_course_pages pg join catalogue.courses c on c.id = pg.course_id join catalogue.providers p on p.id = pg.provider_id join ref.countries k on k.id = p.country_id
  where p_purpose = 'render_page' and k.iso_alpha2 = p_country and c.lifecycle_status = 'active'
    and pg.read_status in ('needs_render', 'blocked') and pg.url is not null
$$;


ALTER FUNCTION "security"."toolset_backlog"("p_purpose" "text", "p_country" "text") OWNER TO "postgres";


