CREATE OR REPLACE FUNCTION "security"."toolset_pass_backlog"("p_country" "text") RETURNS TABLE("subject_key" "text", "course_id" "uuid", "provider_id" "uuid", "input" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select b.subject_key, b.course_id, b.provider_id, b.input
  from security.toolset_backlog('find_course_page', p_country) b
  where not exists (select 1 from pipeline.manual_locks k where k.entity = 'course' and k.entity_id = b.course_id and k.field = 'official_url')
  union all
  select 'course:' || c.id, c.id, p.id,
         jsonb_build_object('course', coalesce(c.display_title, c.canonical_title), 'code', c.course_code, 'provider', coalesce(p.display_name, p.canonical_name),
                            'domain', regexp_replace(lower(substring(p.website from '^(?:https?://)?([^/?#]+)')), '^www\.', ''), 'country', k.name,
                            'earlier_candidate', pg.url, 'earlier_status', pg.read_status, 'refind', true)
  from pipeline.coverage_course_pages pg join catalogue.courses c on c.id = pg.course_id join catalogue.providers p on p.id = pg.provider_id join ref.countries k on k.id = p.country_id
  where coalesce((security.toolset_setting('serper', 'pass_refind_unreadable') #>> '{}')::boolean, false)
    and k.iso_alpha2 = p_country and c.lifecycle_status = 'active' and p.website is not null
    and pg.status = 'bound' and pg.read_status in ('needs_render', 'blocked', 'fetch_failed') and pg.evidence_id is null
    and pg.url !~* coalesce(security.toolset_setting('serper', 'course_like_url') #>> '{}', '/course')
    and not exists (select 1 from pipeline.manual_locks k2 where k2.entity = 'course' and k2.entity_id = c.id and k2.field = 'official_url')
$$;


ALTER FUNCTION "security"."toolset_pass_backlog"("p_country" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."toolset_plan_status"("p_toolset" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_monthly boolean := coalesce((security.toolset_setting(p_toolset, 'plan_renews_monthly') #>> '{}')::boolean, false);
        v_from date; v_credits numeric := (security.toolset_setting(p_toolset, 'plan_credits') #>> '{}')::numeric;
        v_reserve numeric := coalesce((security.toolset_setting(p_toolset, 'plan_reserve') #>> '{}')::numeric, 0); v_used numeric;
begin
  begin v_from := (security.toolset_setting(p_toolset, 'plan_counted_from') #>> '{}')::date;
  exception when others then v_from := null;
  end;
  if v_monthly then v_from := greatest(coalesce(v_from, date_trunc('month', now())::date), date_trunc('month', now())::date); end if;
  select coalesce(sum(u.units), 0) into v_used from pipeline.coverage_vendor_usage u join pipeline.layer2_acquisition_providers p on p.id = u.acquisition_provider_id
   where p.provider_key = p_toolset and u.at >= coalesce(v_from, '2000-01-01'::date);
  return jsonb_build_object('name', security.toolset_setting(p_toolset, 'plan_name') #>> '{}', 'credits', v_credits, 'renews_monthly', v_monthly, 'counted_from', v_from,
    'used', v_used, 'left', case when v_credits is null then null else v_credits - v_used end, 'reserve', v_reserve,
    'max_concurrency', (security.toolset_setting(p_toolset, 'plan_max_concurrency') #>> '{}')::int,
    'at_reserve', v_credits is not null and v_credits - v_used <= v_reserve);
end $$;


ALTER FUNCTION "security"."toolset_plan_status"("p_toolset" "text") OWNER TO "postgres";


