CREATE OR REPLACE FUNCTION "security"."waste_flipflop_guard_v1"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_n int := 0; v_field text; v_reason text;
        v_max int := security.pipeline_num_v1('waste.flipflop_max_changes', 3)::int;
        v_since timestamptz := greatest(now() - make_interval(days => security.pipeline_num_v1('waste.flipflop_window_days', 7)::int),
                                        coalesce((select m.started_at from pipeline.job_input_marks m where m.job_key = 'flipflop-guard'), now()));
begin
  for r in select c.course_id, c.field, max(c.provider_id::text)::uuid provider_id, count(*) n
             from pipeline.adapter_overwrite_changes c where c.at > v_since
            group by c.course_id, c.field having count(*) > v_max loop
    v_field := case r.field when 'english_ielts' then 'english' else r.field end;
    v_reason := format('automatic: changed %s times since %s by automatic writers that disagree; kept as it is and left out of automatic updates (waste rule, CF-247 15 Oct 2026)',
                       r.n, to_char(v_since at time zone 'Australia/Melbourne', 'DD Mon HH24:MI'));
    if v_field = 'delivery' then
      insert into pipeline.uni_adapter_delivery_exclusions(course_id, provider_id, active, reason) values (r.course_id, r.provider_id, true, v_reason)
      on conflict (course_id) do nothing;
    elsif v_field in ('intakes', 'english', 'fee') then
      insert into pipeline.uni_adapter_exclusions(course_id, field, provider_id, active, reason) values (r.course_id, v_field, r.provider_id, true, v_reason)
      on conflict (course_id, field) do nothing;
    else
      continue;
    end if;
    insert into pipeline.enrichment_flags(entity, entity_key, provider_id, field, reason_code, reason, source)
    values ('course', r.course_id::text, r.provider_id, v_field, 'flip_flop', v_reason, 'waste-guard')
    on conflict (entity, entity_key, field, reason_code) do nothing;
    if found then v_n := v_n + 1; end if;
  end loop;
  return v_n;
end $$;


ALTER FUNCTION "security"."waste_flipflop_guard_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."waste_guard_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  return jsonb_build_object('idle', security.waste_idle_guard_v1(), 'frozen', security.waste_flipflop_guard_v1(), 'flags', security.enrichment_flags_refresh_v1(),
    -- CF-247 workstream F (P0 AI operations §11): the cost and yield waste checks and breakers
    'cost', security.ops_cost_guard_v1());
end $$;


ALTER FUNCTION "security"."waste_guard_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."waste_idle_guard_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare w record; v_jobid bigint; v_active boolean; v_out bigint; v_inp bigint; v jsonb := '[]'::jsonb;
        v_hours int := security.pipeline_num_v1('waste.idle_pause_hours', 24)::int;
begin
  -- Pipeline Maintenance Mode (15 Nov 2026): while paused, no job is switched off or on here
  if security.maintenance_hold_v1() then return jsonb_build_array(jsonb_build_object('maintenance', 'paused')); end if;
  for w in select * from pipeline.job_idle_watch order by jobname loop
    select j.jobid, j.active into v_jobid, v_active from cron.job j where j.jobname = w.jobname;
    continue when v_jobid is null;
    execute w.output_sql into v_out using now() - make_interval(hours => v_hours);
    execute w.input_sql into v_inp;
    update pipeline.job_idle_watch set last_checked_at = now(), last_output = v_out, last_input = v_inp where jobname = w.jobname;
    if v_active and coalesce(v_out, 0) = 0 and coalesce(v_inp, 0) = 0 and coalesce(w.resumed_at, '-infinity') < now() - make_interval(hours => v_hours) then
      perform cron.alter_job(v_jobid, active := false);
      update pipeline.job_idle_watch set paused_at = now() where jobname = w.jobname;
      insert into pipeline.enrichment_flags(entity, entity_key, field, reason_code, reason, source)
      values ('job', w.jobname, '', 'idle_paused', format('Paused: no output for %s hours and nothing waiting. %s', v_hours, coalesce(w.note, '')), 'waste-guard')
      on conflict (entity, entity_key, field, reason_code) do update set reason = excluded.reason, flagged_at = now(), cleared_at = null;
      v := v || jsonb_build_object('paused', w.jobname);
    elsif not v_active and w.paused_at is not null and coalesce(v_inp, 0) > 0 then
      -- only a job this guard paused is switched on again
      perform cron.alter_job(v_jobid, active := true);
      update pipeline.job_idle_watch set paused_at = null, resumed_at = now() where jobname = w.jobname;
      update pipeline.enrichment_flags set cleared_at = now() where entity = 'job' and entity_key = w.jobname and reason_code = 'idle_paused' and cleared_at is null;
      v := v || jsonb_build_object('resumed', w.jobname);
    end if;
  end loop;
  return v;
end $$;


ALTER FUNCTION "security"."waste_idle_guard_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."website_reference_cache_refresh_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare t0 timestamptz := clock_timestamp(); v jsonb;
begin
  v := api.website_v2_reference_build();
  insert into pipeline.website_reference_cache(id, payload, built_at, build_ms)
  values (1, v, now(), round(extract(epoch from clock_timestamp() - t0) * 1000)::int)
  on conflict (id) do update set payload = excluded.payload, built_at = excluded.built_at, build_ms = excluded.build_ms;
  return jsonb_build_object('bytes', length(v::text), 'ms', round(extract(epoch from clock_timestamp() - t0) * 1000));
end $$;


ALTER FUNCTION "security"."website_reference_cache_refresh_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."website_refusal_v1"("p_url" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  -- CF-247 IQ-00063: why a recorded website cannot be used as a site address, or null (an empty website is the no_website path, not this)
  select case
    when nullif(btrim(coalesce(p_url, '')), '') is null then null
    when btrim(p_url) ~ '\s' then 'it contains spaces'
    when btrim(p_url) !~* '^https?://' then 'it is not an http or https address'
    when substring(btrim(p_url) from '^[A-Za-z]+://([^/?#]*)') like '%@%' then 'it has a user part ("' || split_part(substring(btrim(p_url) from '^[A-Za-z]+://([^/?#]*)'), '@', 1) || '@"), as an email address does'
    when lower(substring(btrim(p_url) from '^[A-Za-z]+://([^/?#:]+)')) !~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)*\.[a-z]{2,}\.?$' then 'its host is not a domain name'
  end
$_$;


ALTER FUNCTION "security"."website_refusal_v1"("p_url" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."website_refusal_v1"("p_url" "text") IS 'CF-247 IQ-00063: why a recorded website cannot be used as a site address (not http or https, spaces, a user part as in an email address, no domain name), or null';



CREATE OR REPLACE FUNCTION "security"."website_sync_candidates_v1"("p_entity" "text") RETURNS TABLE("item_key" "text", "ref_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select k, max(r::text)::uuid from (
    select 'reference' k, null::uuid r where p_entity = 'reference'
    union all
    select p.stable_key, p.id from catalogue.providers p
     where p_entity in ('provider', 'logo', 'rankings') and p.stable_key is not null
       and p.id not in (select h.provider_id from security.provider_hidden_v1 h where h.provider_id is not null)
       and exists (select 1 from search.course_documents d where d.provider_id = p.id)
    union all
    select s.stable_key, s.id from scholarship.scholarships s where p_entity = 'scholarship' and s.stable_key is not null
    union all
    select d.course_stable_key, d.course_id from search.course_documents d where p_entity = 'course' and d.course_stable_key is not null
    union all
    select i.item_key, i.ref_id from pipeline.website_sync_items i where i.entity = p_entity and i.removed_at is null) z
  group by k
$$;


