CREATE OR REPLACE FUNCTION "security"."work_remedy_retry_parked_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_lane text := security.work_issue_lane_v1(p_issue); v_cls text; v_n int;
begin
  select split_part(i.fingerprint, ':', 3) into v_cls from pipeline.integration_issues i where i.id = p_issue;
  if v_lane is null then return jsonb_build_object('ok', false, 'changed', 0, 'evidence', 'not a work-continuity issue'); end if;
  update pipeline.work_items w set stage = 'retry_wait', attempts = 0, next_eligible_at = now() + make_interval(mins => security.work_backoff_minutes_v1(1)::int),
         recover_by = now() + make_interval(hours => security.pipeline_num_v1('wc.recover_by_hours', 48)::int), lease_until = null,
         unresolved_blocker = unresolved_blocker || jsonb_build_object('retried_by_issue', p_issue, 'retried_at', now()), updated_at = now()
   where w.lane = v_lane and w.failure_class = v_cls and w.stage = 'parked' and w.entity <> '*lane'
     and w.failure_class in (select p.failure_class from pipeline.work_recovery_policies p where p.action in ('retry_backoff', 'defer_recheck'));
  get diagnostics v_n = row_count;
  return jsonb_build_object('ok', true, 'changed', v_n, 'evidence', jsonb_build_object('lane', v_lane, 'class', v_cls, 'items_rearmed', v_n));
end $$;


ALTER FUNCTION "security"."work_remedy_retry_parked_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."work_review_ready_v1"("p_category" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with c as (select * from pipeline.work_review_categories where category = p_category),
       q as (select r.item_id, r.review_class, r.settlement, r.duplicate_of, r.readiness, r.ready
               from security.aer_review_ready_v1(null) r, c where p_category = 'aer' and r.field_code = any (c.field_codes)),
       qb as (select q.*, case when q.duplicate_of is not null then 'duplicate' when q.readiness = 'resolvable' then 'resolvable' when q.settlement = 'stale' then 'stale'
                               when q.ready and coalesce(q.readiness, '') <> 'closed' then 'ready' else 'held' end bucket from q),
       w as (select i.id, i.entity_id, i.field_code, x.readiness,
                    row_number() over (partition by i.entity_id, i.field_code order by i.created_at, i.id) rn
               from pipeline.layer4_review_items i left join pipeline.layer4_item_readiness x on x.item_id = i.id, c
              where p_category <> 'aer' and i.status = 'pending' and i.field_code = any (c.field_codes))
  select jsonb_build_object('category', p_category,
    'raw_waiting', case when p_category = 'aer' then (select count(*) from qb) else (select count(*) from w) end,
    'ready_waiting', case when p_category = 'aer' then (select count(*) from qb where bucket = 'ready')
                          else (select count(*) from w where w.rn = 1 and coalesce(w.readiness, 'judgement_ready') not in ('technical_blocked', 'resolvable', 'closed')) end,
    'approve_except', case when p_category = 'aer' then (select count(*) from qb where bucket = 'ready' and review_class = 'approve_except') else 0 end,
    'technical', case when p_category = 'aer' then (select count(*) from qb where bucket = 'held') else (select count(*) from w where w.readiness = 'technical_blocked') end,
    'stale', case when p_category = 'aer' then (select count(*) from qb where bucket = 'stale') else 0 end,
    'resolvable', case when p_category = 'aer' then (select count(*) from qb where bucket = 'resolvable') else (select count(*) from w where w.readiness = 'resolvable') end,
    'duplicates', case when p_category = 'aer' then (select count(*) from qb where bucket = 'duplicate') else (select count(*) from w where w.rn > 1) end,
    'in_progress', (select count(distinct coalesce(f.course_id, f.provider_id)) from pipeline.field_enrich_items f, c
                     where cardinality(c.in_progress_fields) > 0 and f.field = any (c.in_progress_fields) and f.state in ('queued', 'waiting', 'ai', 'leased')))
$$;


ALTER FUNCTION "security"."work_review_ready_v1"("p_category" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."work_review_room_v1"("p_category" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c pipeline.work_review_categories; v_limit numeric; v_wait int; v_prog int := 0; v_rdy jsonb;
begin
  select * into c from pipeline.work_review_categories where category = p_category;
  if not found then return jsonb_build_object('category', p_category, 'known', false, 'room', null); end if;
  v_limit := security.pipeline_num_v1(c.limit_key, null);
  select count(*) into v_wait from pipeline.layer4_review_items i where i.status = 'pending' and i.field_code = any (c.field_codes);
  if cardinality(c.in_progress_fields) > 0 then
    select count(*) into v_prog from pipeline.field_enrich_items f where f.field = any (c.in_progress_fields) and f.state in ('queued', 'waiting', 'ai', 'leased');
  end if;
  -- 4 Nov 2026 (SS-021 F4): a category whose count rule is distinct_ready, while its switch is on, counts distinct review-ready decisions and
  -- distinct reads in progress against the same limit; technically held, resolvable and duplicate items are reported, not counted
  if c.count_rule = 'distinct_ready' and c.count_switch_key is not null and security.pipeline_num_v1(c.count_switch_key, 0) >= 1 then
    v_rdy := security.work_review_ready_v1(p_category);
    return jsonb_build_object('category', p_category, 'known', true, 'limit_key', c.limit_key, 'limit', v_limit, 'count_rule', 'distinct_ready',
                              'waiting', (v_rdy->>'ready_waiting')::int, 'in_progress', (v_rdy->>'in_progress')::int, 'raw_waiting', v_wait, 'raw_in_progress', v_prog,
                              'technical', (v_rdy->>'technical')::int, 'resolvable', (v_rdy->>'resolvable')::int, 'duplicates', (v_rdy->>'duplicates')::int,
                              'room', case when v_limit is null then null else greatest(v_limit - (v_rdy->>'ready_waiting')::int - (v_rdy->>'in_progress')::int, 0) end);
  end if;
  return jsonb_build_object('category', p_category, 'known', true, 'limit_key', c.limit_key, 'limit', v_limit, 'waiting', v_wait, 'in_progress', v_prog,
                            'room', case when v_limit is null then null else greatest(v_limit - v_wait - v_prog, 0) end);
end $$;


ALTER FUNCTION "security"."work_review_room_v1"("p_category" "text") OWNER TO "postgres";


