CREATE OR REPLACE FUNCTION "security"."work_verify_recovered_v1"("p_issue" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_lane text := security.work_issue_lane_v1(p_issue); v_cls text; v_blocked int; v_done int; v_since timestamptz;
begin
  select split_part(i.fingerprint, ':', 3) into v_cls from pipeline.integration_issues i where i.id = p_issue;
  -- since the newest action on the issue (or, with none, since the issue was detected)
  select coalesce(max(u.started_at), (select i.detected_at from pipeline.integration_issues i where i.id = p_issue)) into v_since from pipeline.ops_remedy_runs u where u.issue_id = p_issue;
  select count(*) into v_blocked from pipeline.work_items w where w.lane = v_lane and w.failure_class = v_cls and w.entity <> '*lane'
     and (w.stage in ('parked', 'quarantined', 'lane_paused') or (w.stage <> 'done' and w.recover_by < now()));
  select count(*) into v_done from pipeline.work_items w where w.lane = v_lane and w.stage = 'done' and w.updated_at >= coalesce(v_since, now());
  return jsonb_build_object('passed', v_blocked = 0 and v_done > 0, 'measure', jsonb_build_object('blocked', v_blocked, 'completed_since_action', v_done),
                            'evidence', 'lane ' || coalesce(v_lane, '?') || ', class ' || coalesce(v_cls, '?') || ': ' || v_blocked || ' blocked, ' || v_done || ' completed since the action');
end $$;


ALTER FUNCTION "security"."work_verify_recovered_v1"("p_issue" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."worker_call_outcome_v1"("p_status" integer, "p_body" "jsonb", "p_items" integer, "p_ok" integer, "p_failed" integer) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  -- items that waited or were refused are not work done: a run whose every item waited for the scraper did nothing
  with w as (select coalesce(sum(case when e.key in ('waiting_scraper', 'deferred', 'credits_refused', 'scrape_failed', 'record_failed', 'blocked', 'fetch_failed') and jsonb_typeof(e.value) = 'number'
                                      then (e.value #>> '{}')::numeric end), 0) n
               from jsonb_each(coalesce(case when jsonb_typeof(p_body->'tally') = 'object' then p_body->'tally' end, '{}'::jsonb)
                               || coalesce(case when jsonb_typeof(p_body->'candidates'->'tally') = 'object' then p_body->'candidates'->'tally' end, '{}'::jsonb)) e)
  select case when coalesce(p_status, 200) >= 400 or coalesce(p_body->>'ok', 'true') = 'false' or p_body ? 'error' then 'failed'
              when coalesce(p_ok, 0) - w.n <= 0 and (coalesce(p_failed, 0) > 0 or w.n > 0
                   or coalesce(p_body::text, '') ~* '"(errors?|last_error)"\s*:\s*"|map:(budget|scholarship_share|credits_refused|credits_reserve|target_list_refused|no_firecrawl_key|timeout|[45][0-9][0-9])|credits_refused|statement timeout|section_missing') then 'zero_work_error'
              when coalesce(p_ok, 0) = 0 and coalesce(p_items, 0) = 0 then 'idle'
              when coalesce(p_ok, 0) - w.n <= 0 then 'zero_work_error'
              else 'succeeded' end
    from w
$$;


ALTER FUNCTION "security"."worker_call_outcome_v1"("p_status" integer, "p_body" "jsonb", "p_items" integer, "p_ok" integer, "p_failed" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."worker_call_work_v1"("p_content" "text") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare j jsonb;
begin
  begin j := p_content::jsonb; exception when others then return null; end;
  if jsonb_typeof(j) <> 'object' then return null; end if;
  return (select coalesce(sum(case when jsonb_typeof(v) = 'number' then (v #>> '{}')::numeric when jsonb_typeof(v) = 'array' then jsonb_array_length(v) else 0 end), 0)
            from jsonb_each(j) e(k, v) where k in ('providers', 'items', 'rows', 'found', 'read', 'searched', 'pages', 'picked', 'discover', 'applied', 'done', 'checked'));
end $$;


ALTER FUNCTION "security"."worker_call_work_v1"("p_content" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."worker_lane_call_v1"("p_mode" "text", "p_job" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_purpose text; v_hold text;
begin
  if p_mode = 'link_search' and not coalesce((select s.enabled from pipeline.course_link_search_settings s where s.id = 1), false) then return false; end if;
  if p_job is not null and security.job_held_off_v1(p_job) then return false; end if;
  if security.pipeline_num_v1('lanes.skip_held_paid_calls', 0) < 1 then return true; end if;
  select l.fc_purpose into v_purpose from pipeline.worker_mode_lanes l where l.mode = p_mode and l.lane = 'paid_acquisition';
  v_hold := security.lane_paid_hold_v1(v_purpose);
  if v_hold is null then return true; end if;
  if not exists (select 1 from pipeline.mode_outcome_ledger y where y.mode = p_mode and y.worker = 'lane-guard'
                    and y.run_at > now() - make_interval(mins => security.pipeline_num_v1('lanes.hold_note_minutes', 60)::int)) then
    insert into pipeline.mode_outcome_ledger(mode, status, ms, items, ok, failed, landed, worker, detail, outcome, lane_outcome, hold_reason)
    values (p_mode, 200, 0, 0, 0, 0, '{}'::jsonb, 'lane-guard', jsonb_build_object('skipped', 'the worker was not called'), 'idle', 'budget_held', v_hold);  -- fixed: HTTP 200, no call made
  end if;
  return false;
end $$;


ALTER FUNCTION "security"."worker_lane_call_v1"("p_mode" "text", "p_job" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."worker_lane_outcome_v1"("p_mode" "text", "p_outcome" "text", "p_body" "jsonb") RETURNS "text"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_lane text; v_purpose text; v_t text := coalesce(p_body::text, ''); v_m text[]; v_hold text;
begin
  if p_outcome is null then return array[null, null]::text[]; end if;
  select l.lane, l.fc_purpose into v_lane, v_purpose from pipeline.worker_mode_lanes l where l.mode = p_mode;
  if p_outcome = 'failed' then
    return array['failed', left(coalesce(p_body->>'error', p_body->>'reason', 'the worker answered with an error'), 300)];
  end if;
  if p_outcome = 'succeeded' then return array['done', null]::text[]; end if;
  v_m := regexp_match(v_t, '(credits_reserve|credits_refused|waiting_scraper|scholarship_share|plan_reserve|no scraper credit|target_list_refused)');
  if p_outcome = 'zero_work_error' then
    if v_m is not null and v_t !~* '"(error|errors|last_error)"\s*:\s*"|statement timeout' then
      return array[case when v_m[1] = 'target_list_refused' then 'source_limit' else 'budget_held' end, 'every item waited: ' || v_m[1]];
    end if;
    return array['failed', left(coalesce(p_body->>'error', substring(v_t from '"(?:errors?|last_error)"\s*:\s*"([^"]+)'), 'no work done, with an error in the answer'), 300)];
  end if;
  -- idle: a paid lane whose picker found nothing because its budget is held is held, not idle
  if v_lane = 'paid_acquisition' then
    v_hold := security.lane_paid_hold_v1(v_purpose);
    if v_hold is not null then return array['budget_held', v_hold]; end if;
    if p_mode = 'link_search' and (select count(*) from pipeline.course_link_search s where s.sent_at >= (date_trunc('day', now() at time zone 'UTC') at time zone 'UTC'))
                                  >= security.pipeline_num_v1('search.daily_picked_cap', 100) then
      return array['source_limit', 'today''s course-page search cap (search.daily_picked_cap) is reached'];
    end if;
  end if;
  return array['idle', coalesce(nullif(p_body->>'reason', ''), 'nothing due')];
end $$;


ALTER FUNCTION "security"."worker_lane_outcome_v1"("p_mode" "text", "p_outcome" "text", "p_body" "jsonb") OWNER TO "postgres";


