CREATE OR REPLACE FUNCTION "security"."worker_mode_waiting_v1"("p_mode" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- R1 Q2 (24 Oct 2026): one "work is waiting" test per lane the idle guard pauses; each mirrors its picker's eligibility (hidden
  -- providers left out) without leasing anything. A lane not listed answers false and waits for its capped trial.
  select case p_mode
    when 'read' then exists (select 1 from pipeline.coverage_course_pages p
                              where p.status in ('bound', 'ambiguous') and coalesce(p.next_read_at, now()) <= now() and coalesce(p.leased_until, '-infinity') < now() and p.read_attempts < 3
                                and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.provider_id))
    when 'link_search' then exists (select 1 from pipeline.course_link_search s
                              where s.state = 'queued' and s.requested_at is not null
                                and (not coalesce((security.firecrawl_setting('target_only') #>> '{}')::boolean, true)
                                     or exists (select 1 from pipeline.firecrawl_target_cache tc where tc.provider_id = s.provider_id and tc.included))
                                and (s.provider_id <> all (array(select x.provider_id from security.fc_search_stopped_v1() x))
                                     or (security.pipeline_num_v1('search.person_task_bypass', 1) >= 1 and security.link_search_person_task_v1(s.provider_id, s.course_id))))
    when 'provider_facts' then exists (select 1 from pipeline.provider_fact_sources f where f.status = 'found' and coalesce(f.attempts, 0) < 3)
    when 'ai_match' then exists (select 1 from pipeline.coverage_ai_match q
                              where (q.state = 'ready' or (q.state = 'leased' and q.leased_until < now()))
                                and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = q.provider_id))
    when 'reidentify' then exists (select 1 from pipeline.coverage_course_pages p join pipeline.evidence_artifacts e on e.id = p.evidence_id
                              where p.status = 'mismatch' and p.read_status = 'identity_mismatch' and coalesce(p.basis, '') <> 'manual' and e.storage_path is not null
                                and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.provider_id)
                                and not exists (select 1 from pipeline.page_rejections x where x.course_id = p.course_id and x.url = p.url))
    when 'discover' then exists (select 1 from pipeline.coverage_provider_discovery d
                              where (d.status = 'pending' or (d.status in ('mapped', 'failed') and d.next_due_at <= now())) and coalesce(d.leased_until, '-infinity') < now()
                                and d.attempts < 3 and security.enrich_focus_v1(d.provider_id)
                                and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = d.provider_id))
    when 'find_site' then exists (select 1 from pipeline.coverage_provider_discovery d
                              where d.status = 'no_website' and coalesce(d.site_searched_at, '-infinity') < now() - make_interval(days => security.pipeline_num_v1('retry.no_website_days', 30)::int)
                                and coalesce(d.leased_until, '-infinity') < now()
                                and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = d.provider_id))
    when 'central_find' then exists (select 1 from pipeline.provider_central_search s join catalogue.providers p on p.id = s.provider_id
                              where (s.state = 'queued' or (s.state = 'leased' and s.leased_until < now())) and s.attempts < 3 and p.lifecycle_status = 'active'
                                and p.website ~* '^https?://' and not security.third_party_host_v1(p.website)
                                and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = s.provider_id)
                                and (s.requested_at is not null or not security.flag_provider_held_v1(s.provider_id, array['central_not_due', 'central_budget', 'site_unreachable'])))
    when 'contact_page' then exists (select 1 from catalogue.providers p
                              where p.lifecycle_status = 'active' and p.website ~* '^https?://' and (p.phone is null or p.email is null) and not security.third_party_host_v1(p.website)
                                and not exists (select 1 from pipeline.provider_contact_checks k where k.provider_id = p.id and k.kind = 'public_general'
                                                 and k.checked_at > now() - make_interval(days => security.pipeline_num_v1('contact.recheck_days', 90)::int))
                                and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id)
                                and exists (select 1 from catalogue.courses c where c.provider_id = p.id and c.lifecycle_status = 'active'))
    when 'logo_find' then exists (select 1 from catalogue.providers p left join pipeline.provider_logo_finds f on f.provider_id = p.id
                              where p.lifecycle_status = 'active' and nullif(btrim(p.website), '') is not null and (f.requested_at is not null or p.publication_status = 'published')
                                and not exists (select 1 from catalogue.provider_assets a where a.provider_id = p.id and a.is_primary and a.status = 'approved' and a.asset_type in ('logo', 'logo_dark', 'logo_light'))
                                and (f.provider_id is null or f.requested_at is not null or f.status = 'queued')
                                and (f.requested_at is not null or not security.flag_provider_held_v1(p.id, array['site_unreachable', 'logo_not_found'])))
    when 'companion_read' then exists (select 1 from pipeline.course_companion_pages p
                              where p.next_read_at <= now() and (p.leased_until is null or p.leased_until < now())
                                and p.read_attempts < security.pipeline_num_v1('companion.max_attempts', 4) and p.status <> 'gone'
                                and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.provider_id))
    when 'source_find' then exists (select 1 from pipeline.source_find_runs r
                              where (r.step is not null or (r.work->>'again' = 'true' and coalesce(r.next_try_at, now()) <= now()))
                                and coalesce(r.leased_until, '-infinity') < now() and coalesce(r.work->>'test', 'false') <> 'true')
    when 'programme_read' then exists (select 1 from pipeline.programme_candidates c
                              where c.state in ('found', 'failed') and c.read_attempts < security.pipeline_num_v1('programme.read_attempts', 3)::int
                                and c.next_read_at <= now() and coalesce(c.leased_until, '-infinity') < now())
    else false end
$$;


ALTER FUNCTION "security"."worker_mode_waiting_v1"("p_mode" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."worker_mode_waiting_v1"("p_mode" "text") IS 'R1 Q2: true when the lane''s own queue holds eligible work; the flag recheck (every 10 minutes) switches a paused lane on again the moment this is true';



CREATE OR REPLACE FUNCTION "security"."worker_outcome_check_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int := security.pipeline_num_v1('worker.outcome_failed_runs', 3)::int; v_h int := security.pipeline_num_v1('worker.outcome_window_hours', 6)::int;
        r record; v_open int := 0; v_resolved int := 0;
begin
  if not pg_try_advisory_xact_lock(hashtext('worker-outcome-check')) then return jsonb_build_object('skipped', 'running'); end if;  -- fixed: lock key
  -- calls recorded before this change have no outcome yet: classified once, from what was recorded
  update pipeline.mode_outcome_ledger l set outcome = security.worker_call_outcome_v1(l.status, coalesce(l.detail, '{}'::jsonb) || jsonb_build_object('tally', l.landed), l.items, l.ok, l.failed)
   where l.outcome is null and l.run_at > now() - make_interval(hours => v_h);
  for r in select o.mode, o.jobs, (select array_agg(x.outcome order by x.run_at desc, x.id desc) from (select y.id, y.outcome, y.run_at from pipeline.mode_outcome_ledger y where y.mode = o.mode order by y.run_at desc, y.id desc limit v_n) x) last_n
             from security.job_outcomes_v1(v_h) o loop
    if cardinality(r.last_n) >= v_n and r.last_n <@ array['failed', 'zero_work_error'] then
      insert into pipeline.platform_issues as i (check_key, severity, area, title, detail)
      values ('worker:' || r.mode, 'critical', 'pipeline', left('Worker ' || r.mode || ': the last ' || v_n || ' runs did no work because of an error', 300),
              jsonb_build_object('mode', r.mode, 'jobs', to_jsonb(r.jobs), 'last_outcomes', to_jsonb(r.last_n),
                                 'last_answer', (select left(coalesce(y.detail::text, ''), 600) from pipeline.mode_outcome_ledger y where y.mode = r.mode order by y.run_at desc, y.id desc limit 1),
                                 'next_step', 'Read the last answers of this worker mode; the scheduler shows these runs as succeeded because it only posts the request'))
      on conflict (check_key) where resolved_at is null do update set title = excluded.title, detail = excluded.detail, last_seen = now(), occurrences = i.occurrences + 1;
      v_open := v_open + 1;
    elsif r.last_n[1] in ('succeeded', 'idle') then
      update pipeline.platform_issues set resolved_at = now() where check_key = 'worker:' || r.mode and resolved_at is null;
      if found then v_resolved := v_resolved + 1; end if;
    end if;
  end loop;
  return jsonb_build_object('open', v_open, 'resolved', v_resolved);
end $$;


ALTER FUNCTION "security"."worker_outcome_check_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."zero_yield_detect_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_at timestamptz := date_trunc('minute', now()); v_min int := security.pipeline_num_v1('zero_yield.min_bound', 10)::int;
        v_rate numeric := security.pipeline_num_v1('zero_yield.flag_rate_pct', 25); v_auto boolean := security.pipeline_num_v1('zero_yield.auto_reset', 0) = 1;
        v_per int := greatest(1, security.pipeline_num_v1('zero_yield.providers_per_run', 5)::int); v_batch int := greatest(10, least(security.pipeline_num_v1('zero_yield.detect_providers_per_run', 150)::int, 2000));
        r record; v_r jsonb; v_reset int := 0; v_prov int := 0; v_flag int := 0;
begin
  -- providers not measured in the last day first, a bounded number a run (the job runs hourly, so every provider is measured each day)
  for r in select x.provider_id from (select distinct p.provider_id from pipeline.coverage_course_pages p join pipeline.evidence_artifacts e on e.id = p.evidence_id and e.storage_path is not null where p.status = 'bound' and p.read_status = 'read') x
            where not exists (select 1 from pipeline.zero_yield_snapshots s where s.provider_id = x.provider_id and s.at > now() - make_interval(hours => security.pipeline_num_v1('zero_yield.redetect_hours', 23)::int))
            order by (select count(*) from pipeline.coverage_course_pages p2 where p2.provider_id = x.provider_id and p2.status = 'bound') desc
            limit v_batch loop
    insert into pipeline.zero_yield_snapshots(at, provider_id, country, bound, zero_yield, verified_wrong, rate_pct, flagged, detail)
    select v_at, z.provider_id, z.country, count(*), count(*) filter (where z.zero), count(*) filter (where z.verified_wrong),
           round(100.0 * count(*) filter (where z.zero) / count(*), 1),
           (count(*) >= v_min and 100.0 * count(*) filter (where z.zero) / count(*) >= v_rate),
           jsonb_build_object('listing', count(*) filter (where z.listing), 'not_found', count(*) filter (where z.not_found), 'off_pattern', count(*) filter (where z.pattern_share < security.pipeline_num_v1('zero_yield.off_pattern_share_max', 0.35)), 'manual', count(*) filter (where z.basis = 'manual'))
      from security.zero_yield_pages_v1(r.provider_id) z group by z.provider_id, z.country
    on conflict (at, provider_id) do nothing;
    v_prov := v_prov + 1;
  end loop;
  select count(*) into v_flag from pipeline.zero_yield_snapshots s where s.at = v_at and s.flagged;
  -- resets (when switched on) consider every flagged provider measured in the last day, most affected first
  if v_auto then
    for r in select distinct on (s.provider_id) s.provider_id, s.verified_wrong from pipeline.zero_yield_snapshots s where s.at > now() - make_interval(hours => security.pipeline_num_v1('zero_yield.redetect_hours', 23)::int) and s.flagged and s.verified_wrong > 0
               and not exists (select 1 from pipeline.admin_control_events d where d.action = 'zero_yield_reset' and d.target = s.provider_id::text and d.created_at > now() - make_interval(hours => security.pipeline_num_v1('zero_yield.redetect_hours', 23)::int))
             order by s.provider_id, s.at desc loop
      v_r := security.zero_yield_reset_v1(r.provider_id);
      v_reset := v_reset + coalesce((v_r->>'reset')::int, 0);
      update pipeline.zero_yield_snapshots s set reset = coalesce((v_r->>'reset')::int, 0) where s.provider_id = r.provider_id and s.at = (select max(at) from pipeline.zero_yield_snapshots where provider_id = r.provider_id);
      exit when (select count(*) from pipeline.admin_control_events d where d.action = 'zero_yield_reset' and d.created_at > now() - interval '1 hour') >= v_per; -- fixed: the hour that zero_yield.providers_per_run counts
    end loop;
  end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('pipeline', 'zero_yield_detect', 'zero_yield_snapshots', jsonb_build_object('at', v_at, 'providers', v_prov, 'flagged', v_flag, 'auto_reset', v_auto, 'reset', v_reset), null);
  return jsonb_build_object('at', v_at, 'providers', v_prov, 'flagged', v_flag, 'auto_reset', v_auto, 'reset', v_reset);
end $$;


ALTER FUNCTION "security"."zero_yield_detect_v1"() OWNER TO "postgres";


COMMENT ON FUNCTION "security"."zero_yield_detect_v1"() IS 'hourly: writes the per-provider zero-yield snapshot, flags providers above the rate as systematic, and (only when zero_yield.auto_reset is 1) resets the verified-wrong pages of the most affected flagged providers';



CREATE OR REPLACE FUNCTION "security"."zero_yield_pages_v1"("p_provider" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("course_id" "uuid", "provider_id" "uuid", "country" "text", "url" "text", "evidence_id" "uuid", "identity_basis" "text", "basis" "text", "canonical_title" "text", "page_title" "text", "zero" boolean, "listing" boolean, "not_found" boolean, "title_overlap" numeric, "pattern_share" numeric, "candidate_url" "text", "candidate_overlap" numeric, "verified_wrong" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
with s as (
  select security.pipeline_num_v1('zero_yield.title_overlap_min', 0.5) t_min,
         security.pipeline_num_v1('zero_yield.off_pattern_share_max', 0.35) off_max,
         security.pipeline_num_v1('zero_yield.candidate_overlap_min', 0.6) c_min,
         coalesce((select s.value #>> '{}' from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'zero_yield.listing_url_pattern'), '^$') listing_rx,
         coalesce((select s.value #>> '{}' from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'zero_yield.not_found_pattern'), '^$') nf_rx,
         coalesce((select array(select jsonb_array_elements_text(s.value)) from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'zero_yield.level_words'), '{}'::text[]) level_words),
b as materialized (
  select p.course_id, p.provider_id, k.iso_alpha2::text country, p.url, p.evidence_id, p.identity_basis, p.basis, c.canonical_title, p.candidates->>'page_title' page_title,
         regexp_replace(p.url, '^(https?://[^/]+/(?:[^/]+/){0,3}).*$', '\1') pattern,
         security.coverage_text_tokens(regexp_replace(c.canonical_title, '\(\s*level\s+\d+\s*\)', '', 'i')) ttok,
         security.coverage_text_tokens(coalesce(p.candidates->>'page_title', '')) ptok,
         (exists (select 1 from catalogue.course_fees f where f.course_id = p.course_id and f.evidence_id = p.evidence_id)
          or exists (select 1 from catalogue.course_english_requirements e where e.course_id = p.course_id and e.evidence_id = p.evidence_id)
          or exists (select 1 from catalogue.course_intakes i where i.course_id = p.course_id and i.evidence_id = p.evidence_id)) admitted,
         (exists (select 1 from pipeline.field_enrich_items i where i.course_id = p.course_id and i.evidence_id = p.evidence_id and i.state in ('filled', 'review'))) enrich_stated,
         (exists (select 1 from pipeline.field_enrich_items i where i.course_id = p.course_id and i.evidence_id = p.evidence_id)) enrich_tried,
         (exists (select 1 from pipeline.fee_reader_queue q where q.course_id = p.course_id and q.evidence_id = p.evidence_id and q.state = 'done' and coalesce(q.rows_found, 0) > 0)) fee_stated,
         (nullif(p.candidates->'fee'->>'value', '') is not null or jsonb_array_length(coalesce(p.candidates->'fee'->'candidates', '[]'::jsonb)) > 0
          or (p.candidates->'english' is not null and p.candidates->'english' <> '{}'::jsonb) or jsonb_array_length(coalesce(p.candidates->'intakes', '[]'::jsonb)) > 0) extract_stated
    from pipeline.coverage_course_pages p
    join catalogue.courses c on c.id = p.course_id and c.lifecycle_status = 'active'
    join catalogue.providers pr on pr.id = p.provider_id
    join ref.countries k on k.id = pr.country_id
    join pipeline.evidence_artifacts e on e.id = p.evidence_id and e.storage_path is not null
   where p.status = 'bound' and p.read_status = 'read' and (p_provider is null or p.provider_id = p_provider)),
share as materialized (select provider_id, pattern, count(*)::numeric / sum(count(*)) over (partition by provider_id) sh from b group by 1, 2),
z as materialized (
  select b.*, sh.sh pattern_share,
         (b.enrich_tried and not b.admitted and not b.enrich_stated and not b.fee_stated and not b.extract_stated) zero,
         (b.url ~* s.listing_rx) listing,
         (coalesce(b.page_title, '') ~* s.nf_rx) not_found,
         (select coalesce(count(*) filter (where t = any (b.ptok)), 0)::numeric / greatest(1, cardinality(b.ttok)) from unnest(b.ttok) t) title_overlap
    from b join share sh on sh.provider_id = b.provider_id and sh.pattern = b.pattern cross join s),
purl as materialized (
  -- the provider's known pages that sit on an accepted (on-pattern) address pattern, computed once
  select u.provider_id, u.url, u.tokens, u.title_tokens
    from pipeline.coverage_provider_urls u
    join share sh on sh.provider_id = u.provider_id and sh.pattern = regexp_replace(u.url, '^(https?://[^/]+/(?:[^/]+/){0,3}).*$', '\1')
    cross join s
   where sh.sh >= s.off_max and u.url !~* s.listing_rx
     and exists (select 1 from z where z.provider_id = u.provider_id and z.pattern_share < s.off_max)),
cand as materialized (
  select z.course_id, c.url, c.ov
    from z cross join s
    join lateral (
      select u.url, (select count(*) filter (where t = any (u.tokens))::numeric / greatest(1, cardinality(z.ttok)) from unnest(z.ttok) t) ov
        from purl u
       where u.provider_id = z.provider_id and u.url <> z.url and u.tokens && z.ttok
         -- a candidate naming a level the course does not (graduate diploma for a diploma, master for a bachelor) is not the course's page
         and not exists (select 1 from unnest(u.tokens) w where w = any (s.level_words) and not (w = any (z.ttok)))
         and not exists (select 1 from pipeline.page_rejections r where r.course_id = z.course_id and r.url = u.url)
       order by ov desc, length(u.url) limit 1) c on true
   where z.pattern_share < s.off_max)
select z.course_id, z.provider_id, z.country, z.url, z.evidence_id, z.identity_basis, z.basis, z.canonical_title, z.page_title,
       z.zero, z.listing, z.not_found, round(z.title_overlap, 2), round(z.pattern_share, 3), cand.url, round(cand.ov, 2),
       (coalesce(z.basis, '') <> 'manual' and ((z.zero and (z.listing or z.not_found or z.title_overlap < s.t_min)) or (z.pattern_share < s.off_max and coalesce(cand.ov, 0) >= s.c_min))) verified_wrong
  from z cross join s left join cand on cand.course_id = z.course_id
$_$;


ALTER FUNCTION "security"."zero_yield_pages_v1"("p_provider" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "security"."zero_yield_pages_v1"("p_provider" "uuid") IS 'every bound course page with a stored copy, with the zero-yield predicate (no value admitted and nothing stated by the fee, enrich and extract readers on that copy) and the verified-wrong signals (listing address, not-found title, weak title overlap, off the provider''s dominant pattern with an on-pattern candidate); zero-yield mandate 24 Oct 2026';



CREATE OR REPLACE FUNCTION "security"."zero_yield_reset_v1"("p_provider" "uuid", "p_limit" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_lim int := greatest(1, least(coalesce(p_limit, security.pipeline_num_v1('zero_yield.reset_per_provider', 50)::int), 500));
        v_age int := greatest(1, security.pipeline_num_v1('zero_yield.urls_max_age_days', 14)::int);
        v_now timestamptz := clock_timestamp(); v_n int := 0; v_links int := 0; v_refind boolean := false; v_fill jsonb;
begin
  with sel as (
    select * from security.zero_yield_pages_v1(p_provider) z where z.verified_wrong order by z.zero desc, z.title_overlap limit v_lim)
  insert into pipeline.page_rejections(course_id, url, provider_id, evidence_id, source, reason, signals, rejected_at)
  select r.course_id, r.url, r.provider_id, r.evidence_id, 'zero_yield',
         case when r.zero and r.not_found then 'zero-yield page that says not found'
              when r.zero and r.listing then 'zero-yield listing or search page'
              when r.zero then 'zero-yield page whose title does not match the course'
              else 'page off the provider''s course-page pattern while an on-pattern page matches the course' end,
         jsonb_build_object('zero', r.zero, 'listing', r.listing, 'not_found', r.not_found, 'title_overlap', r.title_overlap, 'pattern_share', r.pattern_share, 'candidate_url', r.candidate_url, 'candidate_overlap', r.candidate_overlap, 'identity_basis', r.identity_basis, 'page_title', r.page_title), v_now
    from sel r
  on conflict (course_id, url) do update set rejected_at = v_now, reason = excluded.reason, signals = excluded.signals, evidence_id = excluded.evidence_id;
  get diagnostics v_n = row_count;
  if v_n = 0 then return jsonb_build_object('provider_id', p_provider, 'reset', 0); end if;
  update pipeline.coverage_course_pages p
     set status = 'mismatch', read_status = 'identity_mismatch', leased_until = null, next_read_at = now(), read_attempts = 0
    from pipeline.page_rejections r where r.provider_id = p_provider and r.rejected_at = v_now and p.course_id = r.course_id and p.url = r.url and p.status = 'bound' and coalesce(p.basis, '') <> 'manual';
  -- the official link filled from the page is taken back by guard 3 (the fill job retracts fills whose page left bound)
  v_fill := security.course_url_fill_v1();
  v_links := coalesce((v_fill->>'retracted')::int, 0);
  -- the provider's known pages are refreshed when stale (the source finder looks again: Firecrawl map, site maps)
  if coalesce((select max(u.last_seen_at) from pipeline.coverage_provider_urls u where u.provider_id = p_provider), '-infinity'::timestamptz) < now() - make_interval(days => v_age) then
    update pipeline.source_find_runs set next_try_at = now(), step = null, leased_until = null, work = jsonb_build_object('again', true, 'reason', 'zero-yield re-acquisition') where provider_id = p_provider;
    insert into pipeline.source_find_runs(provider_id, state, next_try_at, work) values (p_provider, 'none', now(), jsonb_build_object('again', true, 'reason', 'zero-yield re-acquisition')) on conflict (provider_id) do nothing;
    v_refind := true;
  end if;
  insert into pipeline.admin_control_events(area, action, target, detail, actor)
  values ('pipeline', 'zero_yield_reset', p_provider::text,
          jsonb_build_object('reset', v_n, 'links_retracted', v_links, 'finder_asked', v_refind, 'reasons', (select jsonb_object_agg(reason, n) from (select reason, count(*) n from pipeline.page_rejections where provider_id = p_provider and rejected_at = v_now group by 1) z)), null);
  return jsonb_build_object('provider_id', p_provider, 'reset', v_n, 'links_retracted', v_links, 'finder_asked', v_refind);
end $$;


ALTER FUNCTION "security"."zero_yield_reset_v1"("p_provider" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "security"."zero_yield_reset_v1"("p_provider" "uuid", "p_limit" integer) IS 'resets the verified-wrong pages of one provider: page_rejections row, page back to mismatch / identity_mismatch (the course unbinds; the AI page match and reidentify skip the rejected page), item-5 links retracted, the source finder asked again when the provider''s known pages are stale; count-limited; manual bindings never touched';



CREATE OR REPLACE FUNCTION "security"."zoho_reference_bundle_live_v1"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'catalogue', 'ref', 'search'
    AS $_$
with provider_course_counts as (
  select provider_stable_key, count(*)::int as search_course_count
  from search.course_documents
  where country_code in ('AU','NZ','CA')
  group by provider_stable_key
),
countries as (
  select jsonb_agg(
    jsonb_build_object(
      'code', c.iso_alpha2,
      'name', c.name,
      'coverage_state', case
        when c.iso_alpha2 in ('AU','NZ') then 'live_regulatory'
        when c.iso_alpha2 = 'CA' then 'beta_limited'
        else 'not_admitted'
      end
    )
    order by case c.iso_alpha2 when 'AU' then 1 when 'NZ' then 2 when 'CA' then 3 else 99 end
  ) as items
  from ref.countries c
  where c.iso_alpha2 in ('AU','NZ','CA')
),
subdivisions as (
  select jsonb_agg(
    jsonb_build_object(
      'code', s.code,
      'name', s.name,
      'country_code', c.iso_alpha2
    )
    order by c.iso_alpha2, s.name
  ) as items
  from ref.subdivisions s
  join ref.countries c on c.id=s.country_id
  where c.iso_alpha2 in ('AU','NZ','CA')
    and coalesce(s.status,'active') = 'active'
),
providers as (
  select jsonb_agg(
    jsonb_build_object(
      'provider_id', p.stable_key,
      'name', p.canonical_name,
      'display_name', security.provider_presentable_name(p.display_name),
      'university_groups', security.provider_university_groups(p.id),
      'country_code', c.iso_alpha2,
      'website', p.website,
      'lifecycle_status', p.lifecycle_status,
      'publication_status', p.publication_status,
      'search_course_count',coalesce(pc.search_course_count,0),
      'freshness', jsonb_build_object(
        'last_verified_at', p.last_verified_at,
        'updated_at', p.updated_at
      )
    )
    order by c.iso_alpha2, lower(p.canonical_name), p.stable_key
  ) as items
  from catalogue.providers p
  join ref.countries c on c.id=p.country_id
  left join provider_course_counts pc on pc.provider_stable_key=p.stable_key
  where c.iso_alpha2 in ('AU','NZ','CA')
),
provider_counts as (
  select jsonb_object_agg(country_code, provider_count) as counts
  from (
    select c.iso_alpha2 as country_code, count(*)::int as provider_count
    from catalogue.providers p
    join ref.countries c on c.id=p.country_id
    where c.iso_alpha2 in ('AU','NZ','CA')
    group by c.iso_alpha2
  ) x
),
course_counts as (
  select jsonb_object_agg(country_code, course_count) as counts
  from (
    select d.country_code, count(*)::int as course_count
    from search.course_documents d
    where d.country_code in ('AU','NZ','CA')
    group by d.country_code
  ) x
),
study_levels as (
  select jsonb_agg(jsonb_build_object(
    'code',study_level_code,'name',initcap(replace(study_level_code,'_',' ')),
    'courses',course_count,'country_counts',country_counts
  ) order by course_count desc, study_level_code) items
  from (
    select study_level_code, sum(country_count)::int course_count,
      jsonb_object_agg(country_code,country_count) country_counts
    from (
      select study_level_code,country_code,count(*)::int country_count
      from search.course_documents
      where country_code in ('AU','NZ') and study_level_code is not null
      group by study_level_code,country_code
    ) x
    group by study_level_code
  ) y
),
study_areas as (
  select jsonb_agg(jsonb_build_object(
    'code',primary_field_code,'name',primary_field_name,'courses',course_count,'country_counts',country_counts
  ) order by course_count desc, primary_field_name) items
  from (
    select primary_field_code,max(primary_field_name) primary_field_name,sum(country_count)::int course_count,
      jsonb_object_agg(country_code,country_count) country_counts
    from (
      select primary_field_code,primary_field_name,country_code,count(*)::int country_count
      from search.course_documents
      where country_code in ('AU','NZ') and primary_field_code is not null
      group by primary_field_code,primary_field_name,country_code
    ) x
    group by primary_field_code
  ) y
),
delivery_modes as (
  select jsonb_agg(jsonb_build_object('code',mode,'name',initcap(replace(mode,'_',' ')),'courses',course_count)
                   order by course_count desc,mode) items
  from (
    select mode,count(*)::int course_count
    from search.course_documents d cross join lateral unnest(coalesce(d.delivery_modes,array[]::text[])) mode
    where d.country_code in ('AU','NZ')
    group by mode
  ) x
),
intake_years as (
  select jsonb_agg(jsonb_build_object('year',intake_year,'courses',course_count) order by intake_year) items
  from (
    select (j->>'year')::int intake_year,count(distinct d.course_stable_key)::int course_count
    from search.course_documents d cross join lateral jsonb_array_elements(coalesce(d.intake_options,'[]'::jsonb)) j
    where d.country_code in ('AU','NZ') and (j->>'year') ~ '^[0-9]+$'
    group by (j->>'year')::int
  ) x
),
intake_labels as (
  select jsonb_agg(jsonb_build_object('label',intake_label,'courses',course_count) order by course_count desc,intake_label) items
  from (
    select j->>'label' intake_label,count(distinct d.course_stable_key)::int course_count
    from search.course_documents d cross join lateral jsonb_array_elements(coalesce(d.intake_options,'[]'::jsonb)) j
    where d.country_code in ('AU','NZ') and coalesce(j->>'label','')<>''
    group by j->>'label'
  ) x
),
english_tests as (
  select jsonb_agg(jsonb_build_object('code',test_code,'name',test_name,'courses',course_count)
                   order by course_count desc,test_name) items
  from (
    select j->>'test_code' test_code,max(j->>'test_name') test_name,count(distinct d.course_stable_key)::int course_count
    from search.course_documents d cross join lateral jsonb_array_elements(coalesce(d.english_requirement_options,'[]'::jsonb)) j
    where d.country_code in ('AU','NZ') and coalesce(j->>'test_code','')<>''
    group by j->>'test_code'
  ) x
),
publication_states as (
  select jsonb_agg(jsonb_build_object('code',publication_status,'courses',course_count)
                   order by course_count desc,publication_status) items
  from (
    select publication_status,count(*)::int course_count
    from search.course_documents where country_code in ('AU','NZ')
    group by publication_status
  ) x
),
availability as (
  select jsonb_build_object(
    'total_courses',count(*)::int,
    'has_intake',count(*) filter (where has_intake)::int,
    'has_english',count(*) filter (where has_english)::int,
    'has_scholarship',count(*) filter (where has_scholarship)::int,
    'has_provider_current_tuition',count(*) filter (where has_provider_current_tuition)::int,
    'has_regulatory_tuition',count(*) filter (where has_regulatory_tuition)::int,
    'has_official_link',count(*) filter (where has_link)::int
  ) obj
  from search.course_documents where country_code in ('AU','NZ')
),
tuition_stats as (
  select jsonb_build_object(
    'provider_current_annual',jsonb_build_object(
      'min',min(provider_annual_tuition_amount) filter (where has_provider_current_tuition),
      'max',max(provider_annual_tuition_amount) filter (where has_provider_current_tuition),
      'courses',count(*) filter (where has_provider_current_tuition)
    ),
    'regulatory_total_course',jsonb_build_object(
      'min',min(regulatory_tuition_amount) filter (where has_regulatory_tuition),
      'max',max(regulatory_tuition_amount) filter (where has_regulatory_tuition),
      'courses',count(*) filter (where has_regulatory_tuition)
    )
  ) obj
  from search.course_documents where country_code in ('AU','NZ')
),
top_fields as (
  select jsonb_agg(
    jsonb_build_object('code', primary_field_code,'name', primary_field_name,'courses', course_count)
    order by course_count desc, primary_field_name
  ) as items
  from (
    select primary_field_code, primary_field_name, count(*)::int as course_count
    from search.course_documents
    where country_code in ('AU','NZ') and primary_field_name is not null
    group by primary_field_code, primary_field_name
    order by count(*) desc, primary_field_name
    limit 8
  ) x
)
select jsonb_build_object(
  'contract_version','zoho-integration-v2',
  'resource','reference_bundle',
  'generated_at',now(),
  'countries',coalesce((select items from countries),'[]'::jsonb),
  'subdivisions',coalesce((select items from subdivisions),'[]'::jsonb),
  'providers',coalesce((select items from providers),'[]'::jsonb),
  'course_filters',jsonb_build_object(
    'study_levels',coalesce((select items from study_levels),'[]'::jsonb),
    'study_areas',coalesce((select items from study_areas),'[]'::jsonb),
    'delivery_modes',coalesce((select items from delivery_modes),'[]'::jsonb),
    'intake_years',coalesce((select items from intake_years),'[]'::jsonb),
    'intake_labels',coalesce((select items from intake_labels),'[]'::jsonb),
    'english_tests',coalesce((select items from english_tests),'[]'::jsonb),
    'publication_states',coalesce((select items from publication_states),'[]'::jsonb),
    'availability',coalesce((select obj from availability),'{}'::jsonb),
    'tuition',coalesce((select obj from tuition_stats),'{}'::jsonb)
  ),
  'platform_stats',jsonb_build_object(
    'provider_counts',coalesce((select counts from provider_counts),'{}'::jsonb),
    'course_counts',coalesce((select counts from course_counts),'{}'::jsonb),
    'top_study_areas',coalesce((select items from top_fields),'[]'::jsonb)
  )
) || jsonb_build_object('university_groups', coalesce((
  select jsonb_agg(jsonb_build_object(
           'code', replace(ic.code,'au_',''), 'name', ic.name, 'official_url', ic.official_url, 'country_code', 'AU',
           'providers', (select jsonb_agg(jsonb_build_object('provider_id', pv.stable_key, 'name', security.provider_presentable_name(coalesce(pv.display_name,pv.canonical_name))) order by pv.canonical_name)
                           from catalogue.provider_collection_memberships m join catalogue.providers pv on pv.id=m.provider_id
                          where m.collection_id=ic.id and m.status='active' and (m.valid_to is null or m.valid_to>=current_date)),
           'course_count', (select count(*) from search.course_documents d join catalogue.provider_collection_memberships m on m.provider_id=d.provider_id
                             where m.collection_id=ic.id and m.status='active' and (m.valid_to is null or m.valid_to>=current_date)))
         order by ic.name)
    from ref.institution_collections ic where ic.collection_type='university_group' and ic.status='active'), '[]'::jsonb));
$_$;


ALTER FUNCTION "security"."zoho_reference_bundle_live_v1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."zoho_sync_candidates_v1"("p_entity" "text") RETURNS TABLE("item_key" "text", "ref_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with cn as (select c.id from ref.countries c
               where c.iso_alpha2 in (select jsonb_array_elements_text(coalesce((select s.value from pipeline.platform_toolset_settings s
                                       where s.toolset_key = 'pipeline' and s.key = 'zoho.sync_countries'), '["AU"]'::jsonb)))),
       pv as (select p.id, p.stable_key from catalogue.providers p
               where p.lifecycle_status = 'active' and p.stable_key is not null and p.country_id in (select id from cn)
                 and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id))
  select k, max(r::text)::uuid from (
    select pv.stable_key k, pv.id r from pv where p_entity = 'provider'
    union all
    select coalesce(k.stable_key, k.id::text), k.id from catalogue.campuses k where p_entity = 'campus' and k.provider_id in (select id from pv) and coalesce(k.status, 'active') = 'active'
    union all
    select 'pt:' || cp.id, cp.provider_id from pipeline.provider_contact_points cp where p_entity = 'contact' and cp.is_current and cp.provider_id in (select id from pv)
    union all
    select 'pc:' || pc.id, pc.provider_id from pipeline.provider_contacts pc where p_entity = 'contact' and pc.lifecycle_status = 'active' and pc.deleted_at is null and pc.provider_id in (select id from pv)
    union all
    select d.course_stable_key, d.course_id from search.course_documents d where p_entity = 'course' and d.course_stable_key is not null and d.provider_id in (select id from pv)
    union all
    select i.item_key, i.ref_id from pipeline.zoho_sync_items i where i.entity = p_entity and i.removed_at is null) z
  group by k
$$;


ALTER FUNCTION "security"."zoho_sync_candidates_v1"("p_entity" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."zoho_sync_check_v1"("p_items" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_left int := greatest(coalesce(p_items, 0), 1); e text; r record; v jsonb; h text; it pipeline.zoho_sync_items%rowtype;
        st pipeline.zoho_sync_scan%rowtype; v_lim int; v_cnt int; v_w int; v_out jsonb := '{}'::jsonb; v_new int; v_chg int; v_rem int; v_ren int; v_renew interval;
begin
  if not pg_try_advisory_xact_lock(hashtext('zoho-sync-check')) then return jsonb_build_object('skipped', 'another run is working'); end if;  -- fixed: one run at a time
  v_renew := make_interval(days => greatest(security.pipeline_num_v1('zoho.logo_link_days', 365) - security.pipeline_num_v1('zoho.logo_renew_before_days', 30), 1)::int);
  -- a pass walks the entities in order; each run carries on where the last stopped; a new pass starts when all are done
  if not exists (select 1 from pipeline.zoho_sync_scan where not done) then update pipeline.zoho_sync_scan set done = false; end if;
  foreach e in array array['provider', 'campus', 'contact', 'course'] loop
    exit when v_left <= 0;
    select * into st from pipeline.zoho_sync_scan where entity = e for update;
    continue when st.done;
    v_w := 1;  -- fixed: every Zoho item is about one course's build cost (providers and courses reuse stored items), measured 16 Oct 2026
    v_lim := greatest(ceil(v_left::numeric / v_w)::int, 1); v_cnt := 0; v_new := 0; v_chg := 0; v_rem := 0; v_ren := 0;
    for r in select c.item_key, c.ref_id from security.zoho_sync_candidates_v1(e) c
              where st.after_key is null or c.item_key > st.after_key order by c.item_key limit v_lim loop
      v_cnt := v_cnt + 1; v_left := v_left - v_w;
      v := security.zoho_sync_item_v1(e, r.ref_id, r.item_key);
      h := case when v is null then null else md5((v - 'generated_at' - 'freshness')::text) end;  -- CF-247 16 Oct 2026: freshness timestamps are not a change
      select * into it from pipeline.zoho_sync_items where entity = e and item_key = r.item_key;
      if it.item_key is null then
        if v is not null then
          insert into pipeline.zoho_sync_items(entity, item_key, ref_id, hash, seq, item) values (e, r.item_key, r.ref_id, h, nextval('pipeline.zoho_sync_seq'), v);
          v_new := v_new + 1;
        end if;
      elsif v is null then
        if it.removed_at is null then
          update pipeline.zoho_sync_items set removed_at = now(), hash = null, item = null, seq = nextval('pipeline.zoho_sync_seq'), seq_at = now() where entity = e and item_key = r.item_key;
          v_rem := v_rem + 1;
        end if;
      elsif it.removed_at is not null then
        update pipeline.zoho_sync_items set removed_at = null, hash = h, item = v, ref_id = r.ref_id, seq = nextval('pipeline.zoho_sync_seq'), seq_at = now() where entity = e and item_key = r.item_key;
        v_new := v_new + 1;
      elsif it.hash is null then
        update pipeline.zoho_sync_items set hash = h, item = v, ref_id = r.ref_id where entity = e and item_key = r.item_key;  -- first check: not a change
      elsif it.hash <> h then
        update pipeline.zoho_sync_items set hash = h, item = v, ref_id = r.ref_id, seq = nextval('pipeline.zoho_sync_seq'), seq_at = now() where entity = e and item_key = r.item_key;
        v_chg := v_chg + 1;
      elsif e = 'provider' and it.item ? 'logo' and it.seq_at < now() - v_renew then  -- a provider whose logo link is near its end is sent again
        update pipeline.zoho_sync_items set item = v, seq = nextval('pipeline.zoho_sync_seq'), seq_at = now() where entity = e and item_key = r.item_key;
        v_ren := v_ren + 1;
      elsif it.item is null then
        update pipeline.zoho_sync_items set item = v where entity = e and item_key = r.item_key;  -- CF-247 15 Oct 2026: unchanged, stored for sync
      end if;
      st.after_key := r.item_key;
    end loop;
    if v_cnt < v_lim then
      update pipeline.zoho_sync_scan set after_key = null, done = true, cycles = cycles + 1, last_cycle_at = now(), last_run_at = now(),
             last_result = jsonb_build_object('checked', v_cnt, 'new', v_new, 'changed', v_chg, 'removed', v_rem, 'renewed', v_ren) where entity = e;
    else
      update pipeline.zoho_sync_scan set after_key = st.after_key, last_run_at = now(),
             last_result = jsonb_build_object('checked', v_cnt, 'new', v_new, 'changed', v_chg, 'removed', v_rem, 'renewed', v_ren) where entity = e;
    end if;
    v_out := v_out || jsonb_build_object(e, jsonb_build_object('checked', v_cnt, 'new', v_new, 'changed', v_chg, 'removed', v_rem, 'renewed', v_ren));
  end loop;
  return v_out;
end $$;


ALTER FUNCTION "security"."zoho_sync_check_v1"("p_items" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."zoho_sync_item_v1"("p_entity" "text", "p_ref" "uuid", "p_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb; v_country boolean;
begin
  if p_ref is null then return null; end if;
  if p_entity = 'provider' then
    select exists (select 1 from catalogue.providers p join ref.countries c on c.id = p.country_id where p.id = p_ref
                    and c.iso_alpha2 in (select jsonb_array_elements_text(coalesce((select s.value from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'zoho.sync_countries'), '["AU"]'::jsonb))))
      into v_country;
    v := case when v_country then security.zoho_v2_provider_item_v1(p_ref) end;
  elsif p_entity = 'campus' then
    v := security.zoho_v2_campus_item_v1(p_ref);
    if v is not null and not (v->>'country_code' in (select jsonb_array_elements_text(coalesce((select s.value from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'zoho.sync_countries'), '["AU"]'::jsonb)))) then v := null; end if;
  elsif p_entity = 'contact' then
    v := security.zoho_v2_contact_item_v1(p_key);
  elsif p_entity = 'course' then
    -- the website's stored course item (already built by its change check), else built now; then the Zoho extras
    select w.item into v from pipeline.website_sync_items w where w.entity = 'course' and w.item_key = p_key and w.removed_at is null;
    if v is null and exists (select 1 from search.course_documents d where d.course_id = p_ref) then v := api.website_v2_course_item(p_ref, null, null); end if;
    v := security.zoho_v2_course_extra_v1(v, p_ref);
    if v is not null and not (v->>'country_code' in (select jsonb_array_elements_text(coalesce((select s.value from pipeline.platform_toolset_settings s where s.toolset_key = 'pipeline' and s.key = 'zoho.sync_countries'), '["AU"]'::jsonb)))) then v := null; end if;
  end if;
  return case when v = 'null'::jsonb then null else v end;
end $$;


ALTER FUNCTION "security"."zoho_sync_item_v1"("p_entity" "text", "p_ref" "uuid", "p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."zoho_v2_campus_item_v1"("p_campus_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'campus_id', coalesce(k.stable_key, k.id::text), 'name', k.name, 'campus_code', k.campus_code,
    'provider_id', p.stable_key, 'cricos_provider_code', security.zoho_v2_provider_cricos_v1(p.id), 'provider_name', coalesce(p.display_name, p.canonical_name),
    'address_line1', k.address_line1, 'address_line2', k.address_line2, 'city', k.city, 'postcode', k.postcode,
    'subdivision_code', (select s.code from ref.subdivisions s where s.id = k.subdivision_id),
    'country_code', (select c.iso_alpha2 from ref.countries c where c.id = coalesce(k.country_id, p.country_id)),
    'latitude', k.latitude, 'longitude', k.longitude, 'phone', k.phone, 'website', k.website,
    'metro_area', rc.metro_area, 'regional_category', rc.category,
    'course_count', (select count(*) from catalogue.course_campuses cc join catalogue.courses c on c.id = cc.course_id where cc.campus_id = k.id and c.lifecycle_status = 'active'),
    'status', coalesce(k.status, 'active'), 'updated_at', k.updated_at)
  from catalogue.campuses k join catalogue.providers p on p.id = k.provider_id
  left join pipeline.campus_regional_class rc on rc.campus_id = k.id
  where k.id = p_campus_id and p.lifecycle_status = 'active'
    and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id)
$$;


ALTER FUNCTION "security"."zoho_v2_campus_item_v1"("p_campus_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."zoho_v2_contact_item_v1"("p_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  if p_key like 'pt:%' then
    select jsonb_build_object('contact_id', p_key, 'provider_id', p.stable_key, 'cricos_provider_code', security.zoho_v2_provider_cricos_v1(p.id),
             'provider_name', coalesce(p.display_name, p.canonical_name),
             'type', case cp.kind when 'regulatory_peo' then 'head_of_institution' when 'public_general' then 'general' else cp.kind end,
             'name', cp.name, 'title', cp.title, 'team', null, 'email', cp.email, 'phone', cp.phone,
             'source', case cp.source when 'cricos' then 'CRICOS register' when 'provider_site' then 'Provider website' else cp.source end,
             'source_url', cp.source_url, 'checked_at', cp.observed_at)
      into v
      from pipeline.provider_contact_points cp join catalogue.providers p on p.id = cp.provider_id
     where cp.id::text = substr(p_key, 4) and cp.is_current and p.lifecycle_status = 'active'
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id);
  elsif p_key like 'pc:%' then
    select jsonb_build_object('contact_id', p_key, 'provider_id', p.stable_key, 'cricos_provider_code', security.zoho_v2_provider_cricos_v1(p.id),
             'provider_name', coalesce(p.display_name, p.canonical_name),
             'type', case pc.record_type when 'named_staff' then 'staff' when 'team_contact' then 'team' else pc.record_type end,
             'name', cv.full_name, 'title', cv.job_title, 'team', cv.team_name, 'email', cv.work_email, 'phone', cv.work_phone,
             'source', coalesce(cv.source_class, 'Contact list'), 'source_url', cv.source_url, 'checked_at', coalesce(cv.verified_on::timestamptz, cv.created_at))
      into v
      from pipeline.provider_contacts pc join pipeline.provider_contact_versions cv on cv.id = pc.current_version_id
      join catalogue.providers p on p.id = pc.provider_id
     where pc.id::text = substr(p_key, 4) and pc.lifecycle_status = 'active' and pc.deleted_at is null and p.lifecycle_status = 'active'
       and not exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id);
  end if;
  return v;
end $$;


ALTER FUNCTION "security"."zoho_v2_contact_item_v1"("p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."zoho_v2_course_extra_v1"("p_item" "jsonb", "p_course_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb := p_item; v_pid uuid;
begin
  if v is null or v = 'null'::jsonb then return null; end if;
  select c.provider_id into v_pid from catalogue.courses c where c.id = p_course_id;
  v := v || jsonb_build_object(
    'cricos_course_code', (select upper(cr.registration_code) from catalogue.course_registrations cr where cr.course_id = p_course_id and lower(cr.scheme) = 'cricos' order by cr.registration_code limit 1),
    'publication_status', 'published');  -- Zoho v2: returned items are those the provider Published switch allows
  if jsonb_typeof(v->'provider') = 'object' then
    v := jsonb_set(v, '{provider,cricos_provider_code}', coalesce(to_jsonb(security.zoho_v2_provider_cricos_v1(v_pid)), 'null'::jsonb));
  end if;
  return v;
end $$;


ALTER FUNCTION "security"."zoho_v2_course_extra_v1"("p_item" "jsonb", "p_course_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."zoho_v2_csv_v1"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case when p is null then '' when p ~ '[",\r\n]' or p <> btrim(p) then '"' || replace(p, '"', '""') || '"' else p end
$$;


ALTER FUNCTION "security"."zoho_v2_csv_v1"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."zoho_v2_provider_cricos_v1"("p_provider_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select upper(pr.registration_code) from catalogue.provider_registrations pr
   where pr.provider_id = p_provider_id and lower(pr.registration_scheme) = 'cricos' and nullif(btrim(pr.registration_code), '') is not null
   order by (coalesce(pr.status, 'active') in ('inactive', 'cancelled', 'archived')), pr.checked_at desc nulls last limit 1
$$;


ALTER FUNCTION "security"."zoho_v2_provider_cricos_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "security"."zoho_v2_provider_item_v1"("p_provider_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare p catalogue.providers%rowtype; v jsonb;
begin
  select * into p from catalogue.providers where id = p_provider_id;
  if p.id is null or p.lifecycle_status <> 'active' or exists (select 1 from security.provider_hidden_v1 h where h.provider_id = p.id) then return null; end if;
  -- the website item where the provider has courses (rankings, outcomes, logo, campuses summary), else the basic facts
  select w.item into v from pipeline.website_sync_items w where w.entity = 'provider' and w.item_key = p.stable_key and w.removed_at is null;
  v := coalesce(v, jsonb_build_object('provider_id', p.stable_key, 'name', coalesce(p.display_name, p.canonical_name), 'legal_name', p.canonical_name,
         'website', p.website, 'institution_type', api.website_v2_institution_type(p.id), 'course_count', 0, 'publication_status', 'published'));
  return v || jsonb_build_object(
    'cricos_provider_code', security.zoho_v2_provider_cricos_v1(p.id),
    'country_code', (select c.iso_alpha2 from ref.countries c where c.id = p.country_id),
    'subdivision_code', (select s.code from ref.subdivisions s where s.id = p.subdivision_id),
    'city', p.primary_city, 'postcode', p.postcode, 'phone', p.phone, 'email', p.email,
    'campus_count', (select count(*) from catalogue.campuses k where k.provider_id = p.id and coalesce(k.status, 'active') = 'active'),
    'contact_count', (select count(*) from pipeline.provider_contact_points cp where cp.provider_id = p.id and cp.is_current)
                     + (select count(*) from pipeline.provider_contacts pc where pc.provider_id = p.id and pc.lifecycle_status = 'active' and pc.deleted_at is null),
    'updated_at', p.updated_at);
end $$;


ALTER FUNCTION "security"."zoho_v2_provider_item_v1"("p_provider_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "catalogue"."campuses" (
    "id" "uuid" DEFAULT "extensions"."gen_random_uuid"() NOT NULL,
    "stable_key" "text" NOT NULL,
    "provider_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "campus_code" "text",
    "country_id" "uuid" NOT NULL,
    "subdivision_id" "uuid",
    "city" "text",
    "address_line1" "text",
    "address_line2" "text",
    "postcode" "text",
    "latitude" numeric(9,6),
    "longitude" numeric(9,6),
    "phone" "text",
    "website" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "publication_status" "text" DEFAULT 'unpublished'::"text" NOT NULL,
