CREATE OR REPLACE VIEW "pipeline"."aer_labelled_rows_v1" WITH ("security_invoker"='true') AS
 SELECT 'country_table'::"text" AS "source_kind",
    "m"."id" AS "row_id",
    "m"."provider_id",
    "m"."course_id",
    "m"."course_label",
    "m"."country_code",
    NULL::"text" AS "qualification_code",
    "m"."qualification_name",
    "m"."level_label",
    "m"."min_grade",
    "m"."min_value",
    "m"."grade_scale",
    "m"."benchmark_band",
    "m"."quote",
    "m"."source_id",
    "m"."evidence_id",
    "m"."content_hash",
    "m"."run_id",
    "d"."review_item_id",
    "d"."action" AS "decision",
        CASE
            WHEN ("d"."actor_id" = 'c0ffee00-0000-4000-8000-000000000150'::"uuid") THEN 'machine'::"text"
            WHEN ("d"."actor_id" IS NOT NULL) THEN 'person'::"text"
            ELSE NULL::"text"
        END AS "decided_by",
    "d"."created_at" AS "decided_at",
        CASE
            WHEN ("m"."status" = 'active'::"text") THEN 'accepted'::"text"
            WHEN ("m"."status_reason" ~~ 'excluded by approve except%'::"text") THEN 'left_out'::"text"
            WHEN ("m"."status_reason" ~~ 'quarantined (rejected)%'::"text") THEN 'rejected'::"text"
            ELSE NULL::"text"
        END AS "label",
    "m"."status_reason",
    ("m"."provenance" ->> 'reader'::"text") AS "reader",
    ("m"."provenance" ->> 'worker'::"text") AS "worker"
   FROM (("catalogue"."provider_entry_matrix" "m"
     LEFT JOIN "pipeline"."entry_matrix_runs" "r" ON (("r"."id" = "m"."run_id")))
     LEFT JOIN LATERAL ( SELECT "x"."id",
            "x"."review_item_id",
            "x"."action",
            "x"."actor_id",
            "x"."reason",
            "x"."before_value",
            "x"."proposed_value",
            "x"."final_value",
            "x"."evidence_id",
            "x"."layer2_state",
            "x"."layer3_state",
            "x"."scalar_resolution_id",
            "x"."change_control_ref",
            "x"."created_at"
           FROM "pipeline"."layer4_decisions" "x"
          WHERE ("x"."review_item_id" = "r"."review_item_id")
          ORDER BY "x"."created_at" DESC
         LIMIT 1) "d" ON (true))
  WHERE (("m"."status" = 'active'::"text") OR ("m"."status_reason" ~~ 'excluded by approve except%'::"text") OR ("m"."status_reason" ~~ 'quarantined (rejected)%'::"text"))
UNION ALL
 SELECT 'qualification'::"text" AS "source_kind",
    "q"."id" AS "row_id",
    "q"."provider_id",
    "q"."course_id",
    "q"."course_label",
    NULL::"text" AS "country_code",
    "q"."qualification_code",
    "q"."qualification_label" AS "qualification_name",
    "q"."level_label",
    "q"."min_grade",
    "q"."min_value",
    "q"."grade_scale",
    NULL::"text" AS "benchmark_band",
    "q"."quote",
    "q"."source_id",
    "q"."evidence_id",
    "q"."content_hash",
    "q"."run_id",
    NULL::"uuid" AS "review_item_id",
    NULL::"text" AS "decision",
    NULL::"text" AS "decided_by",
    NULL::timestamp with time zone AS "decided_at",
        CASE
            WHEN ("q"."status" = 'active'::"text") THEN 'accepted'::"text"
            WHEN ("q"."status" = 'inactive'::"text") THEN 'rejected'::"text"
            ELSE NULL::"text"
        END AS "label",
    "q"."status_reason",
    ("q"."provenance" ->> 'reader'::"text") AS "reader",
    ("q"."provenance" ->> 'worker'::"text") AS "worker"
   FROM "catalogue"."provider_qualification_requirements" "q"
  WHERE ("q"."status" = ANY (ARRAY['active'::"text", 'inactive'::"text"]))
UNION ALL
 SELECT 'course_page'::"text" AS "source_kind",
    "c"."id" AS "row_id",
    "co"."provider_id",
    "c"."course_id",
    "co"."canonical_title" AS "course_label",
    "k"."iso_alpha2" AS "country_code",
    NULL::"text" AS "qualification_code",
    "c"."description" AS "qualification_name",
    NULL::"text" AS "level_label",
    "c"."min_grade",
    "c"."min_value",
    "c"."grade_scale",
    "c"."benchmark_band",
    "c"."quote",
    NULL::"uuid" AS "source_id",
    "c"."evidence_id",
    NULL::"text" AS "content_hash",
    NULL::"uuid" AS "run_id",
    NULL::"uuid" AS "review_item_id",
    NULL::"text" AS "decision",
    NULL::"text" AS "decided_by",
    "c"."updated_at" AS "decided_at",
        CASE
            WHEN ("c"."status" = 'active'::"text") THEN 'accepted'::"text"
            WHEN ("c"."status" = 'inactive'::"text") THEN 'rejected'::"text"
            ELSE NULL::"text"
        END AS "label",
    "c"."status_reason",
    ("c"."provenance" ->> 'reader'::"text") AS "reader",
    ("c"."provenance" ->> 'worker'::"text") AS "worker"
   FROM (("catalogue"."course_entry_requirements" "c"
     JOIN "catalogue"."courses" "co" ON (("co"."id" = "c"."course_id")))
     LEFT JOIN "ref"."countries" "k" ON (("k"."id" = "c"."country_id")))
  WHERE ("c"."status" = ANY (ARRAY['active'::"text", 'inactive'::"text"]));


ALTER VIEW "pipeline"."aer_labelled_rows_v1" OWNER TO "postgres";


COMMENT ON VIEW "pipeline"."aer_labelled_rows_v1" IS 'AER v2 step 0 (Decision 276): every AER row a decision has labelled (accepted, left out, rejected) with its evidence; the labelled validation set of the v2 shadow trial';



