ALTER SEQUENCE "pipeline"."ai_spend_ledger_id_seq" OWNED BY "pipeline"."ai_spend_ledger"."id";



CREATE TABLE IF NOT EXISTS "pipeline"."alert_delivery_attempts" (
    "attempt_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "batch_id" "uuid" NOT NULL,
    "alert_source" "text" NOT NULL,
    "alert_id" bigint NOT NULL,
    "attempt_no" integer DEFAULT 1 NOT NULL,
    "state" "text" DEFAULT 'leased'::"text" NOT NULL,
    "taken_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "released_at" timestamp with time zone,
    "release_reason" "text",
    CONSTRAINT "alert_delivery_attempts_alert_source_check" CHECK (("alert_source" = ANY (ARRAY['platform'::"text", 'queue_watch'::"text"]))),
    CONSTRAINT "alert_delivery_attempts_state_check" CHECK (("state" = ANY (ARRAY['leased'::"text", 'generated'::"text", 'acknowledged'::"text", 'released'::"text"])))
);


ALTER TABLE "pipeline"."alert_delivery_attempts" OWNER TO "postgres";


COMMENT ON TABLE "pipeline"."alert_delivery_attempts" IS 'CF-247 P1 (7 Nov 2026): one row per alert per attempt with a durable attempt_id. The partial unique index alert_delivery_attempts_live_uq allows one live attempt per alert (leased, generated or acknowledged), so delivery is idempotent and concurrent collectors cannot take the same alert. released = eligible for a bounded retry. Never read by the consumer API.';



CREATE TABLE IF NOT EXISTS "pipeline"."alert_delivery_batches" (
    "batch_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "purpose" "text" NOT NULL,
    "test_ref" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "text" DEFAULT 'scheduled task'::"text" NOT NULL,
    "lease_until" timestamp with time zone NOT NULL,
    "items" integer DEFAULT 0 NOT NULL,
    "transport_state" "text" DEFAULT 'leased'::"text" NOT NULL,
    "generated_at" timestamp with time zone,
    "output_md5" "text",
    "output_items" integer,
    "transport_evidence" "jsonb" DEFAULT '{"channel": "scheduled task", "transport_ack": "not exposed by the channel", "receipt_signal": "not exposed by the channel"}'::"jsonb" NOT NULL,
    "receipt_state" "text" DEFAULT 'unverified'::"text" NOT NULL,
    "receipt_channels" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "receipt_by" "text",
    "receipt_at" timestamp with time zone,
    "receipt_note" "text",
    CONSTRAINT "alert_delivery_batches_purpose_check" CHECK (("purpose" = ANY (ARRAY['alerts'::"text", 'test'::"text"]))),
    CONSTRAINT "alert_delivery_batches_receipt_state_check" CHECK (("receipt_state" = ANY (ARRAY['unverified'::"text", 'confirmed'::"text", 'not_received'::"text"]))),
    CONSTRAINT "alert_delivery_batches_transport_state_check" CHECK (("transport_state" = ANY (ARRAY['leased'::"text", 'generated'::"text", 'transport_acknowledged'::"text", 'transport_failed'::"text", 'expired'::"text"])))
);


ALTER TABLE "pipeline"."alert_delivery_batches" OWNER TO "postgres";


COMMENT ON TABLE "pipeline"."alert_delivery_batches" IS 'CF-247 P1 (7 Nov 2026): append-only alert delivery outbox, one row per delivery try or notification-only test. transport_state (what the run did) and receipt_state (what a person confirmed) are separate; the scheduled-task channel exposes no transport acknowledgement or receipt, so a generated batch stays unverified until a person confirms or the issue is acknowledged. Unverified batches do not block later batches. Never read by the consumer API.';



