    CONSTRAINT "layer2_execution_policies_routing_strategy_check" CHECK (("routing_strategy" = ANY (ARRAY['direct_then_best_value'::"text", 'lowest_cost_proven'::"text", 'highest_success'::"text", 'manual_provider'::"text"]))),
