    "entered_route" "text",
    "state" "text" DEFAULT 'needs_paid_discovery'::"text" NOT NULL,
    "step" integer,
    "free_routes" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "fingerprint" "text",
    "fingerprint_changed_at" timestamp with time zone,
    "state_changed_at" timestamp with time zone,
