    "search_credits" numeric DEFAULT 0 NOT NULL,
    "recovered_at" timestamp with time zone,
    "filled_since_entry" integer DEFAULT 0 NOT NULL,
    "open_absences" integer DEFAULT 0 NOT NULL,
    "detail" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "field_absence_recovery_state_check" CHECK (("state" = ANY (ARRAY['recovered_free'::"text", 'waiting_current_work'::"text", 'waiting_layer4'::"text", 'locked'::"text", 'free_route_capacity'::"text", 'free_route_refused_status'::"text", 'free_route_stored_search'::"text", 'free_route_provider_list'::"text", 'free_route_canonical_year'::"text", 'needs_authorised_read'::"text", 'needs_paid_research'::"text", 'needs_paid_discovery'::"text"]))),
    CONSTRAINT "field_absence_recovery_step_check" CHECK ((("step" >= 1) AND ("step" <= 8)))
);


ALTER TABLE "pipeline"."field_absence_recovery" OWNER TO "postgres";


COMMENT ON TABLE "pipeline"."field_absence_recovery" IS 'CF-247 ops B (mandate 3 Nov 2026 15:37 §4, the D1 special case): the persistent recovery cohort: every course the source-proof lane has held without a free route (no_route, exhausted, or waiting for free capacity), with its state (recovered free, waiting on current work, waiting on Layer 4, locked, a free route open by kind, needs an authorised page read, needs paid search again or for the first time), the discovery step reached (mandate §4 order 1-8), the free routes open, an evidence fingerprint (a course is tried again only when it changes), the paid search already spent and the fields filled since entry. Written by security.field_absence_recovery_refresh_v1 (job field-absence-recovery); read by security.field_absence_d1_decision_v1 and the view pipeline.field_absence_recovery_providers.';



CREATE OR REPLACE VIEW "pipeline"."field_absence_recovery_providers" WITH ("security_invoker"='true') AS
 WITH "rl" AS (
         SELECT "x"."provider_id",
            "count"(*) FILTER (WHERE ("x"."state" = 'found'::"text")) AS "found",
            "count"(*) FILTER (WHERE (("x"."state" = ANY (ARRAY['found'::"text", 'absent'::"text"])) AND ("jsonb_typeof"("x"."candidates") = 'array'::"text") AND ("jsonb_array_length"("x"."candidates") > 0))) AS "tried"
           FROM "pipeline"."course_relink" "x"
          GROUP BY "x"."provider_id"
        ), "g" AS (
         SELECT COALESCE(("sum"("rl_1"."found") / NULLIF("sum"("rl_1"."tried"), (0)::numeric)), (0)::numeric) AS "rate"
           FROM "rl" "rl_1"
        )
 SELECT "fr"."provider_id",
    "p"."canonical_name" AS "provider",
    "count"(*) AS "courses",
    "count"(*) FILTER (WHERE ("fr"."state" = 'recovered_free'::"text")) AS "recovered_free",
    "count"(*) FILTER (WHERE ("fr"."state" = 'waiting_current_work'::"text")) AS "waiting_current_work",
    "count"(*) FILTER (WHERE ("fr"."state" = 'waiting_layer4'::"text")) AS "waiting_layer4",
    "count"(*) FILTER (WHERE ("fr"."state" = 'locked'::"text")) AS "locked",
    "count"(*) FILTER (WHERE ("fr"."state" ~~ 'free_route_%'::"text")) AS "free_route_open",
    "count"(*) FILTER (WHERE ("fr"."state" = 'needs_authorised_read'::"text")) AS "needs_authorised_read",
    "count"(*) FILTER (WHERE ("fr"."state" = 'needs_paid_research'::"text")) AS "needs_paid_research",
    "count"(*) FILTER (WHERE ("fr"."state" = 'needs_paid_discovery'::"text")) AS "needs_paid_discovery",
    "round"(COALESCE((("max"("rl"."found"))::numeric / (NULLIF("max"("rl"."tried"), 0))::numeric), "max"("g"."rate")), 3) AS "relink_found_rate",
    "round"((("count"(*) FILTER (WHERE ("fr"."state" ~~ 'free_route_%'::"text")))::numeric * COALESCE((("max"("rl"."found"))::numeric / (NULLIF("max"("rl"."tried"), 0))::numeric), "max"("g"."rate"))), 1) AS "est_free_recoveries",
    "sum"("fr"."search_credits") AS "paid_search_credits_spent",
    "sum"("fr"."filled_since_entry") AS "fields_filled_since_entry"
   FROM ((("pipeline"."field_absence_recovery" "fr"
     JOIN "catalogue"."providers" "p" ON (("p"."id" = "fr"."provider_id")))
     LEFT JOIN "rl" ON (("rl"."provider_id" = "fr"."provider_id")))
     CROSS JOIN "g")
  GROUP BY "fr"."provider_id", "p"."canonical_name";


ALTER VIEW "pipeline"."field_absence_recovery_providers" OWNER TO "postgres";


COMMENT ON VIEW "pipeline"."field_absence_recovery_providers" IS 'CF-247 ops B (mandate 3 Nov 2026 15:37 §4 D1): the recovery cohort per provider: courses by state and the estimated free recoveries (free routes open times the provider''s measured relink found rate, or the platform rate when it has none).';



