CREATE TABLE IF NOT EXISTS "pipeline"."important_dates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "country_code" "text" NOT NULL,
    "event_type" "text" NOT NULL,
    "title" "text" NOT NULL,
    "source_url" "text" NOT NULL,
    "evidence_id" "uuid",
    "scope_type" "text" NOT NULL,
    "source_profile_id" "uuid",
    "entity_type" "text",
    "entity_id" "uuid",
    "date_precision" "text" NOT NULL,
    "starts_at" timestamp with time zone,
    "ends_at" timestamp with time zone,
    "timezone" "text",
    "source_wording" "text",
    "warning_window" interval DEFAULT '14 days'::interval NOT NULL,
    "expires_at" timestamp with time zone,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "refresh_layer" smallint,
    "change_control_ref" "text" NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "source_id" "uuid",
    "starts_on" "date",
    "ends_on" "date",
    CONSTRAINT "important_dates_bounded_scope_check" CHECK ((("scope_type" = 'country_reference'::"text") OR ("source_id" IS NOT NULL) OR ("source_profile_id" IS NOT NULL) OR ("entity_id" IS NOT NULL))),
    CONSTRAINT "important_dates_check1" CHECK ((("date_precision" <> 'source_vague'::"text") OR ("source_wording" IS NOT NULL))),
    CONSTRAINT "important_dates_date_precision_check" CHECK (("date_precision" = ANY (ARRAY['exact'::"text", 'date_range'::"text", 'month'::"text", 'term'::"text", 'year'::"text", 'source_vague'::"text"]))),
    CONSTRAINT "important_dates_event_type_check" CHECK (("event_type" = ANY (ARRAY['course_application_deadline'::"text", 'intake_date'::"text", 'scholarship_window'::"text", 'regulatory_dataset_release'::"text", 'provider_application_window'::"text", 'national_education_event'::"text"]))),
    CONSTRAINT "important_dates_exact_source_value_check" CHECK ((("date_precision" <> 'exact'::"text") OR ("starts_at" IS NOT NULL) OR ("starts_on" IS NOT NULL))),
    CONSTRAINT "important_dates_refresh_layer_check" CHECK ((("refresh_layer" >= 1) AND ("refresh_layer" <= 4))),
    CONSTRAINT "important_dates_scope_type_check" CHECK (("scope_type" = ANY (ARRAY['source'::"text", 'provider'::"text", 'course'::"text", 'scholarship'::"text", 'country_reference'::"text"]))),
    CONSTRAINT "important_dates_source_url_check" CHECK (("source_url" ~* '^https?://'::"text")),
    CONSTRAINT "important_dates_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'expired'::"text", 'cancelled'::"text", 'unverified'::"text"])))
);


