    "id" bigint NOT NULL,
    "issue_id" bigint NOT NULL,
    "at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "kind" "text" NOT NULL,
    "from_status" "text",
    "to_status" "text",
    "actor" "text" NOT NULL,
    "note" "text",
    "detail" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "integration_issue_events_kind_check" CHECK (("kind" = ANY (ARRAY['detected'::"text", 'observed'::"text", 'not_observed'::"text", 'observed_again'::"text", 'escalated'::"text", 'status'::"text", 'reopened_regression'::"text", 'closed'::"text", 'updated'::"text", 'alert_opened'::"text", 'alert_resolved'::"text"])))
);


ALTER TABLE "pipeline"."integration_issue_events" OWNER TO "postgres";


COMMENT ON TABLE "pipeline"."integration_issue_events" IS 'CF-247 continuous validation mandate §3/§5: the history of each integration issue (detected, material re-observations, condition cleared or back, status changes with their evidence, regression reopenings, closure with its verification, P0 alert opened and resolved). Written only by the integration functions; never read by the consumer API.';



