    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE "pipeline"."integration_issue_events_id_seq" OWNER TO "postgres";


ALTER SEQUENCE "pipeline"."integration_issue_events_id_seq" OWNED BY "pipeline"."integration_issue_events"."id";



