    "production_rotation_required" boolean DEFAULT true NOT NULL,
    "description" "text",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "pipeline"."integration_secret_registry" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "pipeline"."integration_validate_state" (
    "check_key" "text" NOT NULL,
    "last_run_at" timestamp with time zone,
    "watermark_id" bigint,
    "watermark_at" timestamp with time zone,
    "last_found" integer,
    "last_ms" integer,
    "last_error" "text",
    "detail" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL
);


ALTER TABLE "pipeline"."integration_validate_state" OWNER TO "postgres";


COMMENT ON TABLE "pipeline"."integration_validate_state" IS 'CF-247 mandate §4 V4: per-check watermark (newest scheduler run or ledger row already looked at) and last result of job integration-validate (security.integration_validate_v1), so each run reads only what is new. Never read by the consumer API.';



CREATE TABLE IF NOT EXISTS "pipeline"."integration_yield_buckets" (
    "kind" "text" NOT NULL,
    "key" "text" NOT NULL,
    "bucket" timestamp with time zone NOT NULL,
    "calls" integer DEFAULT 0 NOT NULL,
    "failures" integer DEFAULT 0 NOT NULL,
    "items" integer DEFAULT 0 NOT NULL,
    "ok" integer DEFAULT 0 NOT NULL,
    "sample" "text",
    CONSTRAINT "integration_yield_buckets_kind_check" CHECK (("kind" = ANY (ARRAY['edge'::"text", 'ledger'::"text"])))
);


ALTER TABLE "pipeline"."integration_yield_buckets" OWNER TO "postgres";


COMMENT ON TABLE "pipeline"."integration_yield_buckets" IS 'CF-247 pipeline yield checks (Platform Admin direction 2 Nov 2026 23:24 §3): hourly tallies per worker mode, filled incrementally by security.integration_yield_checks_v1 (job integration-validate) from the newest edge responses (kind edge: calls and failed answers, with a sample) and the newest worker ledger rows (kind ledger: calls, items, ok, failed), past the watermarks in pipeline.integration_validate_state. Kept for integration.bucket_keep_hours. Never read by the consumer API.';



CREATE TABLE IF NOT EXISTS "pipeline"."job_idle_watch" (
    "jobname" "text" NOT NULL,
    "output_sql" "text" NOT NULL,
    "input_sql" "text" NOT NULL,
    "note" "text",
    "paused_at" timestamp with time zone,
    "resumed_at" timestamp with time zone,
    "last_checked_at" timestamp with time zone,
    "last_output" bigint,
    "last_input" bigint
);


ALTER TABLE "pipeline"."job_idle_watch" OWNER TO "postgres";


COMMENT ON TABLE "pipeline"."job_idle_watch" IS 'CF-247 15 Oct 2026: jobs the waste guard pauses when they produce nothing and nothing waits (output_sql takes $1 = since; input_sql counts waiting work). Only jobs it paused are resumed.';



CREATE TABLE IF NOT EXISTS "pipeline"."job_input_marks" (
    "job_key" "text" NOT NULL,
    "last_input_at" timestamp with time zone,
