    "last_source_hash" "text",
    "last_verified_at" timestamp with time zone,
    "verification_status" "text" DEFAULT 'unverified'::"text" NOT NULL,
    "verification_message" "text",
    "variance_percent" numeric(10,4),
    "variance_decision" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "next_verification_at" timestamp with time zone,
    "next_ingestion_at" timestamp with time zone,
    "last_schedule_status" "text",
    "last_schedule_error" "text",
    "consecutive_failures" integer DEFAULT 0 NOT NULL,
    "change_reason" "text" DEFAULT 'initial baseline'::"text" NOT NULL,
    "updated_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "previous_accepted_hash" "text",
    "auto_ingest" boolean DEFAULT false NOT NULL,
    "seen_tracking_since" timestamp with time zone,
    CONSTRAINT "layer1_source_operations_authority_domains_check" CHECK (("cardinality"("authority_domains") > 0)),
    CONSTRAINT "layer1_source_operations_check" CHECK ((("variance_block_percent" >= "variance_warn_percent") AND ("variance_block_percent" <= (100)::numeric))),
    CONSTRAINT "layer1_source_operations_consecutive_failures_check" CHECK (("consecutive_failures" >= 0)),
    CONSTRAINT "layer1_source_operations_ingestion_cadence_days_check" CHECK ((("ingestion_cadence_days" >= 1) AND ("ingestion_cadence_days" <= 365))),
