CREATE TABLE IF NOT EXISTS "pipeline"."work_items" (
    "id" bigint NOT NULL,
    "lane" "text" NOT NULL,
    "entity" "text" NOT NULL,
    "work_kind" "text" NOT NULL,
    "provider_id" "uuid",
    "field" "text",
    "owner" "text" NOT NULL,
    "stage" "text" DEFAULT 'eligible'::"text" NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "total_attempts" integer DEFAULT 0 NOT NULL,
    "failure_class" "text",
    "failure_fingerprint" "text",
    "repeat_count" integer DEFAULT 0 NOT NULL,
    "evidence" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "first_blocked_at" timestamp with time zone,
    "last_attempt_at" timestamp with time zone,
    "next_eligible_at" timestamp with time zone,
    "recover_by" timestamp with time zone,
    "lease_until" timestamp with time zone,
    "escalation" "jsonb",
    "dependency_refs" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "lock_refs" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "review_ref" "text",
    "review_category" "text",
    "evidence_version" "text",
    "outcome" "text",
    "unresolved_blocker" "jsonb",
    "recovered_at" timestamp with time zone,
    "last_recovery_minutes" numeric,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "work_items_entity_check" CHECK (("length"("entity") > 0)),
    CONSTRAINT "work_items_lane_check" CHECK (("lane" ~ '^[a-z][a-z0-9_]*$'::"text")),
    CONSTRAINT "work_items_stage_check" CHECK (("stage" = ANY (ARRAY['eligible'::"text", 'active'::"text", 'retry_wait'::"text", 'deferred'::"text", 'parked'::"text", 'quarantined'::"text", 'awaiting_review'::"text", 'lane_paused'::"text", 'done'::"text"]))),
    CONSTRAINT "work_items_work_kind_check" CHECK (("work_kind" ~ '^[a-z*][a-z0-9_:*]*$'::"text"))
);


ALTER TABLE "pipeline"."work_items" OWNER TO "postgres";


COMMENT ON TABLE "pipeline"."work_items" IS 'CF-247 SS-021 work continuity (mandate 3 Nov 2026 21:19 §2): one continuity record per lane, entity and work kind: owner and stage, attempts in a row and in total, failure class (pipeline.work_recovery_policies) with deduplicated diagnostic evidence, first blocked, last attempt, next eligible time, recovery deadline (recover_by) and escalation, dependency and manual-lock references, the evidence or source version used, and the outcome (pipeline.ops_outcome_codes) or the unresolved blocker. Written only through security.work_item_report_v1, work_claim_v1, work_claims_release_v1 and job work-continuity. A parked, deferred, quarantined or waiting item holds no claim. Rows with entity ''*lane'' hold a lane''s own state (a paused paid lane, the course-relink attribution cursor). Never read by the consumer API.';



CREATE SEQUENCE IF NOT EXISTS "pipeline"."work_items_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE "pipeline"."work_items_id_seq" OWNER TO "postgres";


ALTER SEQUENCE "pipeline"."work_items_id_seq" OWNED BY "pipeline"."work_items"."id";



CREATE TABLE IF NOT EXISTS "pipeline"."work_recovery_policies" (
    "failure_class" "text" NOT NULL,
    "title" "text" NOT NULL,
    "action" "text" NOT NULL,
    "counts_attempt" boolean DEFAULT true NOT NULL,
    "max_attempts_key" "text",
    "recheck_key" "text",
    "escalate_as" "text",
    "escalate_when" "text" DEFAULT 'exhausted'::"text" NOT NULL,
    "root_cause" "text",
    "description" "text" NOT NULL,
    CONSTRAINT "work_recovery_policies_action_check" CHECK (("action" = ANY (ARRAY['retry_backoff'::"text", 'park'::"text", 'quarantine'::"text", 'defer_recheck'::"text", 'layer4_review'::"text", 'pause_lane'::"text", 'defer_admission'::"text", 'hold_lock'::"text"]))),
    CONSTRAINT "work_recovery_policies_escalate_as_check" CHECK ((("escalate_as" IS NULL) OR ("escalate_as" = ANY (ARRAY['release'::"text", 'authority'::"text", 'budget'::"text", 'identity'::"text", 'policy'::"text"])))),
    CONSTRAINT "work_recovery_policies_escalate_when_check" CHECK (("escalate_when" = ANY (ARRAY['never'::"text", 'exhausted'::"text", 'always'::"text"]))),
    CONSTRAINT "work_recovery_policies_failure_class_check" CHECK (("failure_class" ~ '^[a-z][a-z0-9_]*$'::"text"))
);


ALTER TABLE "pipeline"."work_recovery_policies" OWNER TO "postgres";


COMMENT ON TABLE "pipeline"."work_recovery_policies" IS 'CF-247 SS-021 work continuity (mandate 3 Nov 2026 21:19 §3): the automatic action for each failure class: bounded exponential backoff (retry_backoff, wc.backoff_* settings), park with evidence, quarantine (identity conflicts; accepted data is kept), defer with a re-check (unavailable website), Layer 4 review (a human decision), pause only the paid lane (budget), defer for admission (the review category is at its existing limit) and hold for a manual lock. Every threshold is a wc.* setting; no class retries for ever. escalate_as says what kind of blocker reaches the operations controller (as integration issue work_blocked:<lane>:<class>, root_cause). Changed by a release. Never read by the consumer API.';



CREATE TABLE IF NOT EXISTS "pipeline"."work_review_categories" (
    "category" "text" NOT NULL,
    "field_codes" "text"[] NOT NULL,
    "limit_key" "text" NOT NULL,
    "in_progress_fields" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "description" "text" NOT NULL,
    "count_rule" "text" DEFAULT 'raw'::"text" NOT NULL,
    "count_switch_key" "text",
    CONSTRAINT "work_review_categories_category_check" CHECK (("category" ~ '^[a-z][a-z0-9_]*$'::"text")),
    CONSTRAINT "work_review_categories_count_rule_check" CHECK (("count_rule" = ANY (ARRAY['raw'::"text", 'distinct_ready'::"text"])))
);


ALTER TABLE "pipeline"."work_review_categories" OWNER TO "postgres";


COMMENT ON TABLE "pipeline"."work_review_categories" IS 'CF-247 SS-021 work continuity (mandate 3 Nov 2026 21:19 §5): which Layer 4 kinds make up a review category and the existing setting that caps it (read, never changed). security.work_review_room_v1 says how much room a category has; work in a full category is deferred without an attempt or a review item, and independent categories and lanes continue. Never read by the consumer API.';



COMMENT ON COLUMN "pipeline"."work_review_categories"."count_rule" IS 'CF-247 SS-021 F4: raw (every waiting item and read in progress counts) or distinct_ready (while count_switch_key is 1: distinct review-ready decisions, one per entity and kind, not technical_blocked or resolvable, plus distinct reads in progress). The limit itself is never changed.';



COMMENT ON COLUMN "pipeline"."work_review_categories"."count_switch_key" IS 'CF-247 SS-021 F4: the setting that switches count_rule distinct_ready on (raw while it is 0).';



