    CONSTRAINT "api_keys_previous_token_sha256_check" CHECK ((("previous_token_sha256" IS NULL) OR ("previous_token_sha256" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "api_keys_rate_per_minute_check" CHECK ((("rate_per_minute" IS NULL) OR (("rate_per_minute" >= 1) AND ("rate_per_minute" <= 10000)))),
