    "scholarship_type" "text",
    "description" "text",
    "audience" "text",
    "award_value_text" "text",
    "application_required" boolean,
    "application_open_date" "date",
    "application_close_date" "date",
    "academic_year" integer,
    "source_url" "text",
    "lifecycle_status" "text" DEFAULT 'active'::"text" NOT NULL,
    "publication_status" "text" DEFAULT 'unpublished'::"text" NOT NULL,
    "source_id" "uuid",
    "evidence_id" "uuid",
    "confidence" numeric(5,4),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "award_value_type" "text",
    "award_percentage" numeric(7,4),
    "award_amount" numeric(14,2),
    "award_currency_code" character(3),
    "award_applies_to_fee_type" "text",
    "award_fee_basis" "text",
    "award_duration_basis" "text",
    "award_value_is_maximum" boolean DEFAULT false NOT NULL,
    "nationalities" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "application_open_precision" "text",
    "application_close_precision" "text",
    "study_start_label" "text",
    "study_start_date" "date",
    CONSTRAINT "scholarships_award_percentage_check" CHECK ((("award_percentage" IS NULL) OR (("award_percentage" > (0)::numeric) AND ("award_percentage" <= (100)::numeric)))),
    CONSTRAINT "scholarships_award_value_type_check" CHECK ((("award_value_type" IS NULL) OR ("award_value_type" = ANY (ARRAY['percentage'::"text", 'fixed_amount'::"text", 'text_only'::"text"]))))
);


ALTER TABLE "scholarship"."scholarships" OWNER TO "postgres";


COMMENT ON COLUMN "scholarship"."scholarships"."award_percentage" IS 'Percentage award value when explicitly evidenced. CF-199 structures only unambiguous first-party percentage tuition/reduction text; tiered/up-to and non-tuition awards remain unresolved.';



COMMENT ON COLUMN "scholarship"."scholarships"."award_amount" IS 'Fixed award amount when explicitly evidenced. CF-204 records UWA International Student Award as AUD 5,000 per year tuition reduction for program duration; fixed-amount Course net-fee calculation is not yet authorised by the percentage-only calculator.';



COMMENT ON COLUMN "scholarship"."scholarships"."award_applies_to_fee_type" IS 'Exact catalogue.course_fees.fee_type against which the award may be calculated when verified by first-party evidence.';



COMMENT ON COLUMN "scholarship"."scholarships"."award_fee_basis" IS 'Expected fee basis for deterministic calculation, e.g. annual or registered_total_course. Null means calculation is unresolved.';



COMMENT ON COLUMN "scholarship"."scholarships"."award_duration_basis" IS 'Governed award duration. CF-203 records UNSW International Student Award as 20% tuition for program duration from captured first-party detail Evidence; Course/country eligibility remains a separate review gate.';



COMMENT ON COLUMN "scholarship"."scholarships"."award_value_is_maximum" IS 'Decision 212: the stated value is a maximum ("up to"); shown as "Up to ..." and never used for a fee saving.';



COMMENT ON COLUMN "scholarship"."scholarships"."study_start_label" IS 'The intake or study start the scholarship is for, as the provider page states it (CF-247, 11 Oct 2026).';



CREATE TABLE IF NOT EXISTS "scholarship"."scopes" (
    "id" "uuid" DEFAULT "extensions"."gen_random_uuid"() NOT NULL,
    "scholarship_id" "uuid" NOT NULL,
    "scope_type" "text" NOT NULL,
    "provider_id" "uuid",
    "course_id" "uuid",
    "course_collection_id" "uuid",
    "study_level_id" "uuid",
    "field_id" "uuid",
    "country_id" "uuid",
    "campus_id" "uuid",
    "include_exclude" "text" DEFAULT 'include'::"text" NOT NULL,
    "source_id" "uuid",
    "evidence_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "cycle_id" "uuid",
    CONSTRAINT "scopes_include_exclude_check" CHECK (("include_exclude" = ANY (ARRAY['include'::"text", 'exclude'::"text"]))),
    CONSTRAINT "scopes_scope_type_check" CHECK (("scope_type" = ANY (ARRAY['provider'::"text", 'course'::"text", 'course_collection'::"text", 'study_level'::"text", 'field_of_study'::"text", 'country'::"text", 'campus'::"text", 'global'::"text"]))),
    CONSTRAINT "scopes_target_shape_check" CHECK (((("scope_type" = 'global'::"text") AND ("provider_id" IS NULL) AND ("course_id" IS NULL) AND ("course_collection_id" IS NULL) AND ("study_level_id" IS NULL) AND ("field_id" IS NULL) AND ("country_id" IS NULL) AND ("campus_id" IS NULL)) OR (("scope_type" = 'provider'::"text") AND ("provider_id" IS NOT NULL) AND ("course_id" IS NULL) AND ("course_collection_id" IS NULL) AND ("study_level_id" IS NULL) AND ("field_id" IS NULL) AND ("country_id" IS NULL) AND ("campus_id" IS NULL)) OR (("scope_type" = 'course'::"text") AND ("provider_id" IS NULL) AND ("course_id" IS NOT NULL) AND ("course_collection_id" IS NULL) AND ("study_level_id" IS NULL) AND ("field_id" IS NULL) AND ("country_id" IS NULL) AND ("campus_id" IS NULL)) OR (("scope_type" = 'course_collection'::"text") AND ("provider_id" IS NULL) AND ("course_id" IS NULL) AND ("course_collection_id" IS NOT NULL) AND ("study_level_id" IS NULL) AND ("field_id" IS NULL) AND ("country_id" IS NULL) AND ("campus_id" IS NULL)) OR (("scope_type" = 'study_level'::"text") AND ("provider_id" IS NULL) AND ("course_id" IS NULL) AND ("course_collection_id" IS NULL) AND ("study_level_id" IS NOT NULL) AND ("field_id" IS NULL) AND ("country_id" IS NULL) AND ("campus_id" IS NULL)) OR (("scope_type" = 'field_of_study'::"text") AND ("provider_id" IS NULL) AND ("course_id" IS NULL) AND ("course_collection_id" IS NULL) AND ("study_level_id" IS NULL) AND ("field_id" IS NOT NULL) AND ("country_id" IS NULL) AND ("campus_id" IS NULL)) OR (("scope_type" = 'country'::"text") AND ("provider_id" IS NULL) AND ("course_id" IS NULL) AND ("course_collection_id" IS NULL) AND ("study_level_id" IS NULL) AND ("field_id" IS NULL) AND ("country_id" IS NOT NULL) AND ("campus_id" IS NULL)) OR (("scope_type" = 'campus'::"text") AND ("provider_id" IS NULL) AND ("course_id" IS NULL) AND ("course_collection_id" IS NULL) AND ("study_level_id" IS NULL) AND ("field_id" IS NULL) AND ("country_id" IS NULL) AND ("campus_id" IS NOT NULL))))
);


