CREATE OR REPLACE VIEW "security"."layer4_active_blocks" WITH ("security_barrier"='true') AS
 SELECT "id",
    "entity_type",
    "entity_id",
    "block_scope",
    "reason_code",
    "comment",
    "actor_id",
    "actor_email",
    "expires_at",
    "review_at",
    "approval_context",
    "created_at"
   FROM ( SELECT DISTINCT ON ("d"."entity_type", "d"."entity_id", "d"."block_scope") "d"."id",
            "d"."entity_type",
            "d"."entity_id",
            "d"."block_scope",
            "d"."event_type",
            "d"."reason_code",
            "d"."comment",
            "d"."actor_id",
            "d"."actor_email",
            "d"."expires_at",
            "d"."review_at",
            "d"."approval_context",
            "d"."created_at"
           FROM "pipeline"."layer4_block_decisions" "d"
          ORDER BY "d"."entity_type", "d"."entity_id", "d"."block_scope", "d"."created_at" DESC, "d"."id" DESC) "x"
  WHERE (("event_type" = 'block'::"text") AND (("expires_at" IS NULL) OR ("expires_at" > "now"())));


ALTER VIEW "security"."layer4_active_blocks" OWNER TO "postgres";


CREATE OR REPLACE VIEW "security"."provider_hidden_v1" AS
 SELECT "id" AS "provider_id"
   FROM "catalogue"."providers" "p"
  WHERE (("publication_status" IS DISTINCT FROM 'published'::"text") OR ("lifecycle_status" IS DISTINCT FROM 'active'::"text"));


ALTER VIEW "security"."provider_hidden_v1" OWNER TO "postgres";


CREATE OR REPLACE VIEW "security"."layer4_search_blocked_campuses" AS
 SELECT "layer4_active_blocks"."entity_id" AS "campus_id"
   FROM "security"."layer4_active_blocks"
  WHERE (("layer4_active_blocks"."block_scope" = 'search'::"text") AND ("layer4_active_blocks"."entity_type" = 'campus'::"text"))
UNION
 SELECT "c"."id" AS "campus_id"
   FROM ("security"."layer4_active_blocks" "b"
     JOIN "catalogue"."campuses" "c" ON (("c"."provider_id" = "b"."entity_id")))
  WHERE (("b"."block_scope" = 'search'::"text") AND ("b"."entity_type" = 'provider'::"text"))
UNION
 SELECT "c"."id" AS "campus_id"
   FROM ("security"."provider_hidden_v1" "h"
     JOIN "catalogue"."campuses" "c" ON (("c"."provider_id" = "h"."provider_id")));


ALTER VIEW "security"."layer4_search_blocked_campuses" OWNER TO "postgres";


CREATE OR REPLACE VIEW "security"."layer4_search_blocked_courses" AS
 SELECT "layer4_active_blocks"."entity_id" AS "course_id"
   FROM "security"."layer4_active_blocks"
  WHERE (("layer4_active_blocks"."block_scope" = 'search'::"text") AND ("layer4_active_blocks"."entity_type" = 'course'::"text"))
UNION
 SELECT "c"."id" AS "course_id"
   FROM ("security"."layer4_active_blocks" "b"
     JOIN "catalogue"."courses" "c" ON (("c"."provider_id" = "b"."entity_id")))
  WHERE (("b"."block_scope" = 'search'::"text") AND ("b"."entity_type" = 'provider'::"text"))
UNION
 SELECT "c"."id" AS "course_id"
   FROM ("security"."provider_hidden_v1" "h"
     JOIN "catalogue"."courses" "c" ON (("c"."provider_id" = "h"."provider_id")))
UNION
 SELECT "c"."id" AS "course_id"
   FROM "catalogue"."courses" "c"
  WHERE ("c"."lifecycle_status" IS DISTINCT FROM 'active'::"text");


ALTER VIEW "security"."layer4_search_blocked_courses" OWNER TO "postgres";


CREATE OR REPLACE VIEW "security"."layer4_search_blocked_providers" AS
 SELECT "layer4_active_blocks"."entity_id" AS "provider_id"
   FROM "security"."layer4_active_blocks"
  WHERE (("layer4_active_blocks"."block_scope" = 'search'::"text") AND ("layer4_active_blocks"."entity_type" = 'provider'::"text"))
UNION
 SELECT "h"."provider_id"
   FROM "security"."provider_hidden_v1" "h";


ALTER VIEW "security"."layer4_search_blocked_providers" OWNER TO "postgres";


CREATE OR REPLACE VIEW "security"."layer4_search_blocked_scholarships" AS
 SELECT "layer4_active_blocks"."entity_id" AS "scholarship_id"
   FROM "security"."layer4_active_blocks"
  WHERE (("layer4_active_blocks"."block_scope" = 'search'::"text") AND ("layer4_active_blocks"."entity_type" = 'scholarship'::"text"))
UNION
 SELECT "s"."id" AS "scholarship_id"
   FROM ("security"."layer4_active_blocks" "b"
     JOIN "scholarship"."scholarships" "s" ON (("s"."provider_id" = "b"."entity_id")))
  WHERE (("b"."block_scope" = 'search'::"text") AND ("b"."entity_type" = 'provider'::"text"))
UNION
 SELECT "s"."id" AS "scholarship_id"
   FROM ("security"."provider_hidden_v1" "h"
     JOIN "scholarship"."scholarships" "s" ON (("s"."provider_id" = "h"."provider_id")));


ALTER VIEW "security"."layer4_search_blocked_scholarships" OWNER TO "postgres";


