CREATE TABLE IF NOT EXISTS "workflow"."review_actions" (
    "id" "uuid" DEFAULT "extensions"."gen_random_uuid"() NOT NULL,
    "review_id" "uuid" NOT NULL,
    "action" "text" NOT NULL,
    "actor_id" "uuid",
    "before_value" "jsonb",
    "after_value" "jsonb",
    "reason" "text",
    "evidence_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "review_actions_action_check" CHECK (("action" = ANY (ARRAY['open'::"text", 'assign'::"text", 'approve'::"text", 'reject'::"text", 'edit'::"text", 'reclassify'::"text", 'reopen'::"text", 'supersede'::"text", 'close'::"text", 'comment'::"text"])))
);


ALTER TABLE "workflow"."review_actions" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "workflow"."review_queue" (
