    "entity_id" "uuid" NOT NULL,
    "domain" "text" NOT NULL,
    "field_code" "text",
    "candidate_claim_id" "uuid",
    "previous_review_id" "uuid",
    "reopen_reason" "text",
    "priority" smallint DEFAULT 50 NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "assigned_to" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "closed_at" timestamp with time zone,
    CONSTRAINT "review_queue_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'in_review'::"text", 'approved'::"text", 'rejected'::"text", 'superseded'::"text", 'closed'::"text"])))
);


ALTER TABLE "workflow"."review_queue" OWNER TO "postgres";


