CREATE POLICY "destination_career_outcomes_read_published" ON "destination"."career_outcomes" FOR SELECT TO "authenticated", "anon" USING ((EXISTS ( SELECT 1
   FROM "destination"."editions" "e"
  WHERE (("e"."id" = "career_outcomes"."edition_id") AND ("e"."status" = 'published'::"text")))));



CREATE POLICY "destination_city_profiles_read_published" ON "destination"."city_profiles" FOR SELECT TO "authenticated", "anon" USING ((EXISTS ( SELECT 1
   FROM "destination"."editions" "e"
  WHERE (("e"."id" = "city_profiles"."edition_id") AND ("e"."status" = 'published'::"text")))));



CREATE POLICY "destination_editions_read_published" ON "destination"."editions" FOR SELECT TO "authenticated", "anon" USING (("status" = 'published'::"text"));



CREATE POLICY "destination_study_rules_read_published" ON "destination"."study_rules" FOR SELECT TO "authenticated", "anon" USING ((EXISTS ( SELECT 1
   FROM "destination"."editions" "e"
  WHERE (("e"."id" = "study_rules"."edition_id") AND ("e"."status" = 'published'::"text")))));



